INSERT INTO verses (goi, conical, edition_id, version, language_subtag, book, chapter, verse, testament, verse_text) VALUES
(1, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 1, 1, 'OT', 'Ban đầu, Đức Chúa Trời đã sáng tạo trời và đất.'),
(2, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 1, 2, 'OT', 'Đất thì hoang vu và trống không, tối tăm bao phủ mặt vực sâu; và Thần Đức Chúa Trời vận hành trên mặt các dòng nước.'),
(3, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 1, 3, 'OT', 'Đức Chúa Trời phán: "Hãy có ánh sáng"; thì có ánh sáng.'),
(4, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 1, 4, 'OT', 'Đức Chúa Trời thấy ánh sáng là tốt, và Đức Chúa Trời phân biệt giữa ánh sáng và bóng tối.'),
(5, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 1, 5, 'OT', 'Đức Chúa Trời gọi sự sáng là ngày, và sự tối thì Ngài gọi là đêm. Vậy có buổi chiều và buổi mai, một ngày.'),
(6, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 1, 6, 'OT', 'Đức Chúa Trời phán rằng: Hãy có một vòm trời ở giữa nước, để phân rẽ nước với nước.'),
(7, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 1, 7, 'OT', 'Đức Chúa Trời làm nên vòm trời, và phân biệt giữa nước ở dưới vòm trời với nước ở trên vòm trời; thì có như vậy.'),
(8, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 1, 8, 'OT', 'Đức Chúa Trời gọi khoảng không là trời. Vậy, có buổi chiều và buổi mai; ấy là ngày thứ hai.'),
(9, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 1, 9, 'OT', 'Đức Chúa Trời phán rằng: Các nước dưới trời hãy tụ lại một nơi, và chỗ khô cạn phải lộ ra; thì đã xảy ra như vậy.'),
(10, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 1, 10, 'OT', 'Đức Chúa Trời gọi chỗ khô là đất, và chỗ nước tụ lại Người gọi là biển. Đức Chúa Trời thấy điều đó là tốt.'),
(11, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 1, 11, 'OT', 'Đức Chúa Trời phán: Đất hãy nảy sinh cây cỏ, cây có hạt giống, cây trái kết quả, mỗi thứ theo giống nó, trong đó có hạt giống nó trên đất. Thì có như vậy.'),
(12, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 1, 12, 'OT', 'Đất sinh ra thảm thực, cỏ mọc ra kết hạt theo từng loại của nó, và cây sinh trái có hạt ở trong theo từng loại của nó. Đức Chúa Trời thấy điều đó là tốt lành.'),
(13, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 1, 13, 'OT', 'Có buổi chiều, có buổi mai, ấy là ngày thứ ba.'),
(14, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 1, 14, 'OT', 'Đức Chúa Trời phán: Phải có các vật phát sáng trên vòm trời để phân biệt ngày với đêm; và chúng sẽ làm dấu hiệu, định các kỳ lễ, các ngày và các năm.'),
(15, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 1, 15, 'OT', 'và hãy làm các vì sáng trên vòm trời để chiếu sáng trên đất; thì có như vậy.'),
(16, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 1, 16, 'OT', 'Đức Chúa Trời làm nên hai cái đèn lớn: cái đèn lớn để quản trị ban ngày, và cái đèn nhỏ để quản trị ban đêm, cùng các ngôi sao.'),
(17, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 1, 17, 'OT', 'Đức Chúa Trời đặt chúng trong vòm trời để chiếu sáng trên đất.'),
(18, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 1, 18, 'OT', 'đặng cai trị ban ngày và ban đêm, và đặng phân biệt giữa ánh sáng và bóng tối. Đức Chúa Trời thấy điều đó là tốt lành.'),
(19, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 1, 19, 'OT', 'Thế là có buổi chiều và có buổi sáng: ngày thứ tư.'),
(20, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 1, 20, 'OT', 'Đức Chúa Trời phán rằng: Các nước phải sinh ra đầy những sinh vật sống động, và các loài chim phải bay lượn trên mặt đất, trên khoảng không của bầu trời.'),
(21, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 1, 21, 'OT', 'Đức Chúa Trời tạo nên các loài sinh vật biển lớn và mọi sinh vật sống động mà nước sinh ra theo giống loài nó, cùng mọi loài chim có cánh theo giống loài nó. Đức Chúa Trời thấy điều đó là tốt lành.'),
(22, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 1, 22, 'OT', 'Đức Chúa Trời ban phước cho chúng, phán rằng: Hãy sinh sôi, nẩy nở, làm đầy các vùng nước trong biển; và loài chim hãy nẩy nở ra nhiều trên đất.'),
(23, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 1, 23, 'OT', 'Có buổi chiều và buổi sáng, ấy là ngày thứ năm.'),
(24, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 1, 24, 'OT', 'Đức Chúa Trời phán: Đất phải sinh ra các sinh vật sống theo giống loài của chúng, súc vật, loài bò sát và thú hoang trên đất theo các loại của chúng. Và thì có như vậy.'),
(25, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 1, 25, 'OT', 'Đức Chúa Trời làm các loài vật trên đất theo giống của nó, và các loài thú theo giống của nó, và mọi sinh vật bò trên đất theo giống của nó; và Đức Chúa Trời thấy điều đó là tốt lành.'),
(26, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 1, 26, 'OT', 'Đức Chúa Trời phán: "Chúng ta hãy làm nên loài người theo hình ảnh chúng ta, giống như chúng ta, để quản lý loài cá biển, chim trời, loài vật trên đất, mọi sinh vật bò trên mặt đất, và khắp cả đất."'),
(27, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 1, 27, 'OT', 'Đức Chúa Trời đã tạo nên loài người theo hình ảnh Ngài, theo hình ảnh Đức Chúa Trời Ngài đã tạo nên người; Ngài đã tạo nên người nam và người nữ.'),
(28, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 1, 28, 'OT', 'Đức Chúa Trời ban phước cho họ, và Đức Chúa Trời phán với họ rằng: Hãy sinh sản, gia tăng, làm đầy dẫy đất và chinh phục nó; hãy quản trị loài cá biển, loài chim trời và mọi loài vật sống động trên đất.'),
(29, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 1, 29, 'OT', 'Đức Chúa Trời phán: Kìa, Ta đã ban cho các ngươi mọi thứ cỏ sinh hạt trên khắp mặt đất, và mọi thứ cây có trái sinh hạt; ấy sẽ là thức ăn cho các ngươi.'),
(30, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 1, 30, 'OT', 'Còn cho mọi sinh vật sống trên đất, mọi chim trời, và mọi loài bò trên mặt đất, mà trong chúng có sự sống, ta ban cho mọi thứ cỏ xanh làm thức ăn; thì có như vậy.'),
(31, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 1, 31, 'OT', 'Đức Chúa Trời nhìn xem mọi điều Ngài đã làm, và kìa, thật là rất tốt lành. Vậy, có buổi chiều và buổi mai, ấy là ngày thứ sáu.'),
(32, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 2, 1, 'OT', 'Vậy là các tầng trời, đất và muôn vật trên đó đều hoàn thành.'),
(33, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 2, 2, 'OT', 'Đức Chúa Trời đã hoàn tất công việc Ngài làm vào ngày thứ bảy, và Ngài nghỉ vào ngày thứ bảy khỏi mọi công việc Ngài đã làm.'),
(34, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 2, 3, 'OT', 'Đức Chúa Trời ban phước cho ngày thứ bảy và biệt riêng ra làm thánh, vì trong ngày ấy Ngài nghỉ khỏi mọi công việc mà Đức Chúa Trời đã sáng tạo và làm xong.'),
(35, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 2, 4, 'OT', 'Đây là dòng dõi của trời và đất khi được sáng tạo ra, trong ngày Đức Giê-hô-va Đức Chúa Trời làm nên đất và trời.'),
(36, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 2, 5, 'OT', 'Chưa có cây đồng nào mọc trên đất, cũng chưa có ngọn cỏ đồng nào đâm chồi, vì Đức Giê-hô-va Đức Chúa Trời chưa làm mưa xuống trên đất, và cũng không có người để làm ruộng đất.'),
(37, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 2, 6, 'OT', 'Một luồng hơi nước bốc lên từ đất và tưới khắp mặt đất.'),
(38, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 2, 7, 'OT', 'Đức Giê-hô-va Đức Chúa Trời dùng bụi đất nắn hình người, hà sinh khí vào lỗ mũi người ấy; thì người trở nên một sinh vật sống.'),
(39, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 2, 8, 'OT', 'Đức Giê-hô-va Đức Chúa Trời trồng một vườn ở Ê-đen về phía đông, và đặt người mà Ngài đã nặn vào đó.'),
(40, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 2, 9, 'OT', 'Đức Giê-hô-va Đức Chúa Trời khiến mọc lên từ đất mọi thứ cây đẹp để nhìn, và tốt để làm thức ăn, cùng cây sự sống ở giữa vườn, và cây biết điều thiện và điều ác.'),
(41, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 2, 10, 'OT', 'Một dòng sông chảy ra từ Ê-đen để tưới vườn, rồi từ đó chia ra và trở thành bốn nhánh.'),
(42, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 2, 11, 'OT', 'Tên của dòng sông thứ nhất là Bi-sôn; chính dòng sông ấy chảy quanh toàn bộ đất Ha-vi-la, là nơi có vàng.'),
(43, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 2, 12, 'OT', 'Vàng của đất ấy rất tốt; ở đó có bạch kim và đá mã não.'),
(44, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 2, 13, 'OT', 'Tên của dòng sông thứ hai là Ghi-hôn, dòng sông này chảy quanh toàn bộ đất xứ Cu-sơ.'),
(45, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 2, 14, 'OT', 'Tên sông thứ ba là Hi-đê-ke, chảy về phía đông xứ A-si-ri; còn sông thứ tư là sông Ơ-phra-tơ.'),
(46, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 2, 15, 'OT', 'Đức Giê-hô-va Đức Chúa Trời lấy người và đặt người vào vườn Ê-đen để làm cho vườn và giữ vườn.'),
(47, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 2, 16, 'OT', 'Đức Giê-hô-va Đức Chúa Trời truyền cho A-đam rằng: Ngươi được tự do ăn mọi thứ cây trong vườn;'),
(48, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 2, 17, 'OT', 'nhưng về cây biết điều thiện và điều ác, ngươi không được ăn trái của nó; vì ngày nào ngươi ăn, chắc chắn ngươi sẽ chết.'),
(49, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 2, 18, 'OT', 'Đức Giê-hô-va Đức Chúa Trời phán: "Không tốt khi loài người sống một mình; Ta sẽ làm cho người một kẻ giúp đỡ phù hợp với người."'),
(50, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 2, 19, 'OT', 'Đức Giê-hô-va Đức Chúa Trời dùng bụi đất nắn nên mọi loài vật sống trên đồng ruộng và mọi loài chim trời, rồi dẫn đến cùng A-đam để xem người sẽ gọi chúng là gì; và mọi vật sống mà A-đam gọi tên là gì, thì tên đó sẽ là tên riêng của nó.'),
(51, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 2, 20, 'OT', 'A-đam đặt tên cho mọi loài vật, cho loài chim trời và mọi loài thú đồng; nhưng không tìm được một người giúp đỡ nào giống như mình.'),
(52, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 2, 21, 'OT', 'Đức Giê-hô-va Đức Chúa Trời khiến A-đam ngủ mê, và trong khi người ngủ, Ngài lấy một xương sườn của người, rồi lấp thịt thế vào chỗ đó.'),
(53, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 2, 22, 'OT', 'Đức Giê-hô-va Đức Chúa Trời lấy cái xương sườn mà Ngài đã lấy từ A-đam, xây nên một người nữ, rồi dẫn người nữ đến cùng A-đam.'),
(54, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 2, 23, 'OT', 'A-đam nói: "Đây là xương bởi xương tôi, thịt bởi thịt tôi; người này sẽ được gọi là người nữ, vì nàng được lấy ra từ người nam."'),
(55, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 2, 24, 'OT', 'Vì vậy, người nam sẽ lìa cha mẹ mình mà gắn bó với vợ mình, và cả hai sẽ thành một thân.'),
(56, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 2, 25, 'OT', 'A-đam và vợ mình, cả hai đều trần truồng, mà không hề xấu hổ.'),
(57, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 3, 1, 'OT', 'Con rắn vốn khôn khéo hơn mọi loài vật hoang mà Đức Giê-hô-va Đức Chúa Trời đã làm nên. Nó nói với người đàn bà rằng: "Chẳng lẽ Đức Chúa Trời thật đã phán: Các ngươi không được ăn trái của mọi cây trong vườn sao?"'),
(58, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 3, 2, 'OT', 'Người vợ nói với con rắn: "Chúng tôi ăn trái của các cây trong vườn.'),
(59, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 3, 3, 'OT', 'Nhưng về trái của cây ở giữa vườn, Đức Chúa Trời đã nói: Các ngươi không được ăn nó, cũng không được động đến nó, kẻo các ngươi phải chết.'),
(60, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 3, 4, 'OT', 'Con rắn nói với người nữ: "Các ngươi sẽ không chết đâu;'),
(61, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 3, 5, 'OT', 'vì Đức Chúa Trời biết rằng ngày nào các ngươi ăn trái ấy, mắt các ngươi sẽ mở ra, và các ngươi sẽ như Đức Chúa Trời, biết điều thiện và điều ác.'),
(62, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 3, 6, 'OT', 'Người nữ thấy cây đó tốt cho việc ăn, đẹp mắt và đáng ước ao để làm cho thông sáng, bèn hái trái nó mà ăn, rồi đưa cho chồng mình ở gần đó, và chồng cũng ăn theo.'),
(63, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 3, 7, 'OT', 'Mắt của cả hai người đều mở ra, họ biết rằng mình trần truồng, bèn may những lá cây vả làm khố cho mình.'),
(64, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 3, 8, 'OT', 'Khi gió thổi nhẹ vào buổi chiều, họ nghe tiếng Đức Giê-hô-va Đức Chúa Trời đi dạo trong vườn; thì A-đam và vợ ông ẩn mình giữa các cây trong vườn để tránh mặt Đức Giê-hô-va Đức Chúa Trời.'),
(65, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 3, 9, 'OT', 'Đức Giê-hô-va Đức Chúa Trời gọi A-đam và phán với người rằng: Ngươi ở đâu?'),
(66, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 3, 10, 'OT', 'A-đam thưa rằng: Tôi có nghe tiếng Ngài trong vườn, bèn sợ vì tôi trần truồng, nên tôi trốn đi.'),
(67, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 3, 11, 'OT', 'Đức Giê-hô-va Đức Chúa Trời phán: Ai đã cho ngươi biết rằng ngươi trần truồng? Ngươi có ăn từ cây mà Ta đã dặn ngươi không được ăn hay chăng?'),
(68, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 3, 12, 'OT', 'Người đàn ông nói: "Người phụ nữ mà Ngài đã đặt ở cùng tôi, chính nàng đã đưa cho tôi trái cây từ cây đó, và tôi đã ăn."'),
(69, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 3, 13, 'OT', 'Đức Giê-hô-va Đức Chúa Trời phán cùng người nữ rằng: "Ngươi đã làm điều này là sao?" Người nữ thưa rằng: "Con rắn dỗ dành tôi, nên tôi đã ăn."'),
(70, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 3, 14, 'OT', 'Đức Giê-hô-va Đức Chúa Trời phán cùng con rắn rằng: Vì ngươi đã làm điều này, ngươi sẽ bị rủa sả hơn mọi loài vật, hơn mọi loài sinh vật nơi đồng vắng; ngươi sẽ đi bằng bụng ngươi, và phải ăn bụi đất trọn các ngày sống của ngươi.'),
(71, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 3, 15, 'OT', 'Ta sẽ đặt sự thù nghịch giữa mầy và người phụ nữ, giữa dòng dõi mầy và dòng dõi nàng. Dòng dõi nàng sẽ đánh đầu mầy, còn mầy sẽ cắn gót chân người ấy.'),
(72, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 3, 16, 'OT', 'Đức Giê-hô-va phán cùng người đàn bà rằng: Ta sẽ làm cho sự khổ cực của ngươi tăng thêm rất nhiều, cả trong cơn mang thai và sinh con; ngươi sẽ sinh con trong đau đớn; lòng ham muốn ngươi sẽ hướng về chồng ngươi, và chồng ngươi sẽ quản trị ngươi.'),
(73, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 3, 17, 'OT', 'Đức Giê-hô-va phán cùng A-đam rằng: Vì ngươi đã nghe theo tiếng vợ mình và ăn từ cây mà Ta đã dặn ngươi rằng: Ngươi không được ăn từ nó, nên đất bị rủa sả vì ngươi; ngươi phải vất vả làm lụng mới được ăn từ nó trọn các ngày đời ngươi.'),
(74, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 3, 18, 'OT', 'Đất sẽ sinh ra gai và cây tật lê cho ngươi, và ngươi sẽ ăn rau cỏ ngoài đồng;'),
(75, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 3, 19, 'OT', 'Ngươi sẽ ăn lương thực nhờ mồ hôi trên trán ngươi, cho đến khi ngươi trở về đất, vì từ đất ngươi đã được lấy ra; vì ngươi là bụi, và ngươi sẽ trở về bụi.'),
(76, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 3, 20, 'OT', 'A-đam gọi tên vợ mình là Ê-va, vì nàng là mẹ của mọi loài sống.'),
(77, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 3, 21, 'OT', 'Đức Giê-hô-va Đức Chúa Trời làm cho A-đam và vợ của người những chiếc áo bằng da thú, rồi mặc cho hai người.'),
(78, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 3, 22, 'OT', 'Đức Giê-hô-va Đức Chúa Trời phán: "Kìa, loài người đã trở nên như một trong chúng ta, biết điều thiện và điều ác; vậy bây giờ, phải coi chừng, e nó giơ tay ra lấy cũng từ cây sự sống, ăn vào, rồi sống đời đời."'),
(79, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 3, 23, 'OT', 'Đức Giê-hô-va Đức Chúa Trời sai loài người ra khỏi vườn Ê-đen, để cày cấy đất, là nơi người đã được lấy ra từ đó.'),
(80, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 3, 24, 'OT', 'Ngài đuổi loài người ra, rồi đặt các chê-ru-bin và lưỡi gươm chói lóa xoay chuyển về phía đông vườn Ê-đen, để canh giữ con đường dẫn đến cây sự sống.'),
(81, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 4, 1, 'OT', 'A-đam biết vợ mình là Ê-va; người thọ thai, sinh ra Ca-in, rồi nói: Tôi đã được một người nam bởi Đức Giê-hô-va.'),
(82, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 4, 2, 'OT', 'Ê-va lại sinh em trai của nó là A-bên; A-bên thì chăn nuôi chiên, còn Ca-in thì làm nghề trồng trọt.'),
(83, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 4, 3, 'OT', 'Sau một thời gian, Ca-in đem dâng cho Đức Giê-hô-va của lễ từ sản vật của đất.'),
(84, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 4, 4, 'OT', 'Còn A-bên thì cũng dâng những con đầu lòng trong đàn chiên mình và mỡ của những con ấy; và Đức Giê-hô-va đoái đến A-bên và lễ vật của người.'),
(85, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 4, 5, 'OT', 'Nhưng Đức Giê-hô-va không đoái đến Ca-in và lễ vật của người; nên Ca-in giận dữ lắm, và nét mặt người sụp xuống.'),
(86, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 4, 6, 'OT', 'Đức Giê-hô-va phán cùng Ca-in rằng: Sao ngươi giận dữ, và sao nét mặt ngươi sa sầm xuống?'),
(87, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 4, 7, 'OT', 'Nếu ngươi làm lành, ắt được ngước mặt lên; còn nếu không làm lành, thì tội lỗi đang rình rập ngay trước cửa, nó thèm muốn ngươi, nhưng ngươi phải chế ngự nó.'),
(88, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 4, 8, 'OT', 'Ca-in nói với A-bên, em trai mình. Khi họ đang ở ngoài đồng, thì Ca-in đứng lên nghịch cùng A-bên, em trai mình, và giết người.'),
(89, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 4, 9, 'OT', 'Đức Giê-hô-va phán cùng Ca-in rằng: A-bên, em ngươi, đâu rồi? Nó thưa rằng: Tôi không biết; tôi há là người giữ em tôi sao?'),
(90, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 4, 10, 'OT', 'Đức Giê-hô-va phán: "Ngươi đã làm gì? Tiếng máu của anh ngươi kêu lên cùng ta từ nơi đất."'),
(91, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 4, 11, 'OT', 'Bây giờ, ngươi bị rủa sả từ đất, là đất đã mở miệng mình đón lấy máu của anh ngươi từ tay ngươi.'),
(92, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 4, 12, 'OT', 'Khi ngươi làm ruộng, đất sẽ không còn cho sức lực của nó đối với ngươi nữa; ngươi sẽ lưu lạc và rong ruổi trên đất.'),
(93, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 4, 13, 'OT', 'Ca-in thưa cùng Đức Giê-hô-va rằng: Lỗi lầm tôi nặng nề quá, không sao mang nổi.'),
(94, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 4, 14, 'OT', 'Kìa, ngày nay Ngài đuổi tôi ra khỏi mặt đất, và tôi sẽ bị che khuất khỏi mặt Ngài; tôi sẽ lưu lạc và phiêu bạt trên đất, và hễ ai gặp tôi sẽ giết tôi.'),
(95, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 4, 15, 'OT', 'Đức Giê-hô-va phán với hắn: "Vì vậy, hễ ai giết Ca-in sẽ bị trừng phạt bảy lần." Rồi Đức Giê-hô-va đặt cho Ca-in một dấu hiệu, để mọi người gặp hắn không đánh giết.'),
(96, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 4, 16, 'OT', 'Ca-in ra khỏi mặt Đức Giê-hô-va và ở tại đất Nốt, về phía đông Ê-đen.'),
(97, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 4, 17, 'OT', 'Ca-in ăn ở cùng vợ mình, nàng thọ thai và sinh được Hê-nóc; rồi người xây một cái thành, và đặt tên thành theo tên con trai mình là Hê-nóc.'),
(98, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 4, 18, 'OT', 'Hê-nóc sinh ra Y-rát; Y-rát sinh ra Nê-hu-đa-ên; Nê-hu-đa-ên sinh ra Mê-tu-sa-ên; Mê-tu-sa-ên sinh ra Lê-méc.'),
(99, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 4, 19, 'OT', 'Lê-méc lấy cho mình hai vợ; tên người vợ thứ nhất là A-đa, tên người vợ thứ hai là Si-la.'),
(100, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 4, 20, 'OT', 'A-đa sinh ra Gia-banh; chính người ấy là tổ phụ của những kẻ sống trong lều và chăn nuôi súc vật.'),
(101, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 4, 21, 'OT', 'Và tên em trai người là Giu-banh; chính người ấy làm tổ phụ của mọi kẻ cầm đàn cầm sáo.'),
(102, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 4, 22, 'OT', 'Còn Si-la cũng sinh ra Tu-banh-Ca-in, là người rèn mọi thứ đồ bằng đồng và bằng sắt. Em gái của Tu-banh-Ca-in là Na-a-ma.'),
(103, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 4, 23, 'OT', 'Lê-méc nói với các vợ mình: A-đa và Si-la, hãy nghe tiếng ta; hỡi các vợ Lê-méc, hãy lắng tai nghe lời ta; vì ta đã giết một người vì vết thương ta, và một đứa trẻ vì vết bầm ta.'),
(104, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 4, 24, 'OT', 'Vì Ca-in sẽ được báo trả bảy lần, còn Lê-méc sẽ được bảy mươi lần bảy.'),
(105, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 4, 25, 'OT', 'A-đam lại biết vợ mình, thì người sinh một con trai, đặt tên là Sết, vì nói rằng: Đức Chúa Trời đã cho tôi một dòng dõi khác thay cho A-bên, vì Ca-in đã giết người.'),
(106, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 4, 26, 'OT', 'Sết cũng sinh một người con trai, đặt tên cho nó là Ê-nốt. Bấy giờ người ta bắt đầu kêu cầu danh Đức Giê-hô-va.'),
(107, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 5, 1, 'OT', 'Đây là sách gia phổ của A-đam. Ngày Đức Chúa Trời tạo nên A-đam, Ngài làm người ấy theo hình ảnh Đức Chúa Trời.'),
(108, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 5, 2, 'OT', 'Ngài tạo nên người nam và người nữ, ban phước cho họ, và trong ngày Ngài tạo nên họ, đặt tên họ là A-đam.'),
(109, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 5, 3, 'OT', 'A-đam sống một trăm ba mươi năm, rồi sinh một người con trai giống hình ảnh mình, và đặt tên con trai ấy là Sết.'),
(110, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 5, 4, 'OT', 'A-đam sống tám trăm năm sau khi sinh Sết, và sinh các con trai và các con gái.'),
(111, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 5, 5, 'OT', 'A-đam sống tất cả chín trăm ba mươi năm, rồi qua đời.'),
(112, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 5, 6, 'OT', 'Sết sống được một trăm lẻ năm năm, rồi sinh ra Ê-nót.'),
(113, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 5, 7, 'OT', 'Sau khi Sết sinh Ê-nót, người sống thêm tám trăm bảy năm, rồi sinh các con trai và các con gái.'),
(114, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 5, 8, 'OT', 'Sết sống được chín trăm mười hai năm, rồi qua đời.'),
(115, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 5, 9, 'OT', 'Ê-nót sống chín mươi năm, rồi sinh ra Kê-nan.'),
(116, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 5, 10, 'OT', 'Ê-nót sống tám trăm mười lăm năm sau khi sinh Kê-nan, và sinh các con trai và các con gái.'),
(117, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 5, 11, 'OT', 'Ê-nót sống chín trăm lẻ năm, rồi qua đời.'),
(118, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 5, 12, 'OT', 'Kê-nan sống bảy mươi năm, rồi sinh ra Ma-ha-la-le.'),
(119, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 5, 13, 'OT', 'Kê-nan sống tám trăm bốn mươi năm sau khi sinh Ma-ha-la-le, rồi sinh các con trai và các con gái.'),
(120, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 5, 14, 'OT', 'Tất cả các ngày của Kê-nan là chín trăm mười năm; rồi người qua đời.'),
(121, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 5, 15, 'OT', 'Ma-ha-la-le sống sáu mươi lăm năm, rồi sinh ra Giê-rết.'),
(122, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 5, 16, 'OT', 'Ma-ha-la-le sống tám trăm ba mươi năm sau khi sinh Giê-rết, rồi sinh các con trai và các con gái.'),
(123, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 5, 17, 'OT', 'Tất cả các ngày của Ma-ha-la-le là tám trăm chín mươi lăm năm, rồi ông qua đời.'),
(124, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 5, 18, 'OT', 'Giê-rết sống một trăm sáu mươi hai năm, rồi sinh ra Hê-nóc.'),
(125, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 5, 19, 'OT', 'Giê-rết sống tám trăm năm sau khi sinh Hê-nóc, và sinh các con trai và các con gái.'),
(126, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 5, 20, 'OT', 'Giê-rết sống chín trăm sáu mươi hai năm, rồi qua đời.'),
(127, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 5, 21, 'OT', 'Hê-nóc sống sáu mươi lăm năm, rồi sinh ra Mê-tu-sê-la.'),
(128, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 5, 22, 'OT', 'Sau khi Hê-nóc sinh Mê-tu-sê-la, người đồng đi với Đức Chúa Trời ba trăm năm, và sinh con trai, con gái.'),
(129, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 5, 23, 'OT', 'Tất cả các ngày của Hê-nóc là ba trăm sáu mươi lăm năm.'),
(130, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 5, 24, 'OT', 'Hê-nóc đi cùng Đức Chúa Trời, rồi không còn nữa, vì Đức Chúa Trời đã đem người đi.'),
(131, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 5, 25, 'OT', 'Mê-tu-sê-la sống một trăm tám mươi bảy năm, rồi sinh ra Lê-méc.'),
(132, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 5, 26, 'OT', 'Sau khi Mê-tu-sê-la sinh ra Lê-méc, ông còn sống bảy trăm tám mươi hai năm, và sinh các con trai và các con gái.'),
(133, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 5, 27, 'OT', 'Mọi ngày của Mê-tu-sê-la là chín trăm sáu mươi chín năm, rồi người qua đời.'),
(134, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 5, 28, 'OT', 'Lê-méc sống một trăm tám mươi hai năm, rồi sinh một con trai.'),
(135, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 5, 29, 'OT', 'Và người đặt tên nó là Nô-ê, mà nói rằng: Chính nó sẽ an ủi chúng ta về công việc và sự đau đớn của tay chúng ta do đất mà Đức Giê-hô-va đã rủa sả.'),
(136, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 5, 30, 'OT', 'Lê-méc sống năm trăm chín mươi lăm năm sau khi sinh Nô-ê, rồi sinh các con trai và các con gái.'),
(137, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 5, 31, 'OT', 'Lê-méc sống được bảy trăm bảy mươi bảy năm, rồi qua đời.'),
(138, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 5, 32, 'OT', 'Khi Nô-ê được năm trăm tuổi thì sinh ra Sêm, rồi đến Hăm và Gia-phết.'),
(139, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 6, 1, 'OT', 'Khi loài người bắt đầu gia tăng trên mặt đất, và các con gái được sinh ra cho họ,'),
(140, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 6, 2, 'OT', 'Các con trai của Đức Chúa Trời thấy con gái loài người đẹp, bèn lấy vợ từ những người mà họ chọn.'),
(141, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 6, 3, 'OT', 'Đức Giê-hô-va phán: Thần Ta sẽ không còn tranh luận với loài người mãi mãi, vì nó cũng chỉ là xác thịt; tuổi đời của nó sẽ là một trăm hai mươi năm.'),
(142, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 6, 4, 'OT', 'Thời đó, và cả sau đó nữa, có những người khổng lồ trên đất, khi các con trai của Đức Chúa Trời đến cùng các con gái loài người và sinh con cho họ; ấy chính là những người anh hùng thời xưa, những người nổi danh.'),
(143, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 6, 5, 'OT', 'Đức Giê-hô-va thấy sự ác của loài người rất nhiều trên mặt đất, và mọi ý tưởng trong lòng họ chỉ là ác luôn mỗi ngày.'),
(144, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 6, 6, 'OT', 'Đức Giê-hô-va hối tiếc vì đã làm nên loài người trên đất, và Ngài cảm thấy đau buồn trong lòng.'),
(145, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 6, 7, 'OT', 'Đức Giê-hô-va phán: Ta sẽ xóa bỏ loài người mà Ta đã tạo nên khỏi mặt đất, từ loài người đến súc vật, đến loài bò sát và đến chim trời; vì Ta hối tiếc vì đã tạo nên chúng.'),
(146, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 6, 8, 'OT', 'Nhưng Nô-ê tìm được ơn trước mặt Đức Giê-hô-va.'),
(147, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 6, 9, 'OT', 'Nầy là dòng dõi của Nô-ê. Nô-ê là người công bình, trọn vẹn trong các đời của mình; Nô-ê đã đi cùng Đức Chúa Trời.'),
(148, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 6, 10, 'OT', 'Nô-ê sinh ba con trai: Sêm, Hăm và Gia-phết.'),
(149, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 6, 11, 'OT', 'Thế gian bại hoại trước mặt Đức Chúa Trời và đầy dẫy sự hung bạo.'),
(150, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 6, 12, 'OT', 'Đức Chúa Trời nhìn xem thế gian, nầy, nó đã bại hoại; vì mọi xác thịt đã làm cho con đường mình trên đất phải bại hoại.'),
(151, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 6, 13, 'OT', 'Đức Chúa Trời phán cùng Nô-ê rằng: Cuối cùng của mọi xác thịt đã đến trước mặt ta, vì đất đầy dẫy hung bạo bởi họ; nầy, ta sẽ diệt họ cùng với đất.'),
(152, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 6, 14, 'OT', 'Hãy làm cho mình một cái tàu bằng gỗ gô-phê, làm các ngăn cho cái tàu, và trét nhựa cây bề trong và bề ngoài.'),
(153, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 6, 15, 'OT', 'Và điều nầy ngươi phải làm: tàu dài ba trăm thước, rộng năm mươi thước, và cao ba mươi thước.'),
(154, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 6, 16, 'OT', 'Ngươi phải làm một cửa sổ cho tàu, và ngươi phải hoàn tất nó cách một thước về phía trên; ngươi phải đặt cửa tàu bên hông; ngươi sẽ làm nó gồm ba tầng: tầng dưới, tầng giữa và tầng trên.'),
(155, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 6, 17, 'OT', 'Còn ta đây, nầy ta sẽ khiến nước lụt dâng lên trên đất để tiêu diệt mọi loài xác thịt có sinh khí sống ở dưới trời; mọi vật ở trên đất sẽ chết hết.'),
(156, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 6, 18, 'OT', 'Nhưng ta sẽ lập giao ước ta cùng ngươi, và ngươi cùng các con trai ngươi, vợ ngươi và các vợ các con trai ngươi sẽ vào trong tàu cùng ngươi.'),
(157, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 6, 19, 'OT', 'Và từ mọi loài sống, từ mọi xác thịt, ngươi hãy đem theo hai con, mỗi loài một đôi, để giữ sống chúng cùng ngươi; đó phải là một con đực và một con cái.'),
(158, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 6, 20, 'OT', 'Từ các loài chim theo thứ tự nó, từ các loài thú theo thứ tự nó, từ mọi loài sinh vật bò trên đất theo thứ tự nó, mỗi thứ hai con sẽ đến cùng ngươi để ngươi giữ cho sống.'),
(159, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 6, 21, 'OT', 'Còn ngươi, hãy lấy cho mình mọi thứ thức ăn ngươi có thể ăn, và ngươi hãy thu tích lại cho mình; thì nó sẽ là lương thực cho ngươi và cho chúng nó.'),
(160, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 6, 22, 'OT', 'Nô-ê làm theo mọi điều mà Đức Chúa Trời đã truyền dạy ông.'),
(161, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 7, 1, 'OT', 'Đức Giê-hô-va phán cùng Nô-ê rằng: Hãy vào trong tàu, ngươi và cả nhà ngươi, vì ta thấy ngươi là người công bình trước mặt ta trong thế hệ này.'),
(162, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 7, 2, 'OT', 'Hãy lấy các loài vật sạch, mỗi loài bảy con, cả đực lẫn cái; còn các loài vật không sạch thì mỗi loài hai con, đực và cái.'),
(163, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 7, 3, 'OT', 'Cũng từ loài chim trên trời, mỗi loài bảy con đực và bảy con cái, để duy trì dòng giống trên khắp mặt đất.'),
(164, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 7, 4, 'OT', 'Vì còn bảy ngày nữa, chính Ta sẽ làm mưa trên mặt đất trong bốn mươi ngày và bốn mươi đêm, và Ta sẽ tiêu diệt mọi sinh vật mà Ta đã tạo nên khỏi mặt đất.'),
(165, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 7, 5, 'OT', 'Nô-ê làm theo mọi điều mà Đức Giê-hô-va đã truyền cho ông.'),
(166, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 7, 6, 'OT', 'Nô-ê sáu trăm tuổi thì tai họa nước lụt xảy ra, nước tràn trên mặt đất.'),
(167, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 7, 7, 'OT', 'Nô-ê vào tàu, cùng các con trai, vợ mình và các dâu của các con trai mình, vì cớ nước lụt.'),
(168, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 7, 8, 'OT', 'loài vật thanh sạch và loài vật không thanh sạch, loài chim và mọi loài bò sát trên mặt đất,'),
(169, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 7, 9, 'OT', 'Hai hai con, đực và cái, đến cùng Nô-ê mà vào tàu, như Đức Chúa Trời đã truyền dặn Nô-ê.'),
(170, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 7, 10, 'OT', 'Bảy ngày sau, nước lụt xảy ra trên mặt đất.'),
(171, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 7, 11, 'OT', 'Năm sáu trăm đời của Nô-ê, tháng thứ hai, ngày mười bảy tháng ấy, chính ngày đó, tất cả các mạch nước của vực thẳm vỡ tung ra, và các cửa sổ trên trời mở ra.'),
(172, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 7, 12, 'OT', 'Mưa giáng trên đất bốn mươi ngày và bốn mươi đêm.'),
(173, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 7, 13, 'OT', 'Ngay trong ngày ấy, Nô-ê cùng với Sêm, Hăm và Gia-phết, các con trai của Nô-ê, và vợ của Nô-ê, cùng ba vợ các con trai mình, đều vào trong tàu với các con trai ấy.'),
(174, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 7, 14, 'OT', 'Họ và mọi loài sinh vật theo giống của nó, mọi loài vật trên đất theo giống của nó, mọi loài bò sát bò trên mặt đất theo giống của nó, và mọi loài chim theo giống của nó, mọi loài chim có cánh.'),
(175, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 7, 15, 'OT', 'Chúng đến cùng Nô-ê, vào tàu từng cặp, mỗi loài hai con, từ mọi loài xác thịt có thần khí sống.'),
(176, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 7, 16, 'OT', 'Mỗi cặp một đực một cái, từ mọi loài sinh vật đều đi vào, y như Đức Chúa Trời đã truyền dặn nó; rồi Đức Giê-hô-va đóng cửa lại bên ngoài nó.'),
(177, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 7, 17, 'OT', 'Lụt kéo dài bốn mươi ngày trên đất; nước gia tăng, nâng tàu lên khỏi mặt đất.'),
(178, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 7, 18, 'OT', 'Nước dâng lên và gia tăng rất nhiều trên mặt đất; chiếc tàu bè trôi trên mặt nước.'),
(179, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 7, 19, 'OT', 'Nước càng dâng lên rất cao trên mặt đất, và che phủ hết thảy những ngọn núi cao ở dưới khắp các trời.'),
(180, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 7, 20, 'OT', 'Nước dâng lên trên cao mười lăm thước, và các ngọn núi đều bị che khuất.'),
(181, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 7, 21, 'OT', 'Mọi loài sinh vật sống động trên mặt đất đều chết hết, cả loài chim, loài vật ăn cỏ, loài thú dữ, và mọi loài bò sát bò trên mặt đất, cùng với mọi người.'),
(182, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 7, 22, 'OT', 'Mọi vật nào có khí sống trong lỗ mũi nó, mọi vật nào ở trên đất liền, đều chết hết.'),
(183, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 7, 23, 'OT', 'Mọi loài sống trên mặt đất đều bị tiêu diệt, từ loài người cho đến loài thú, loài bò sát và loài chim trời; chúng bị quét sạch khỏi đất; chỉ còn lại Nô-ê và những loài ở với ông trong chiếc tàu.'),
(184, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 7, 24, 'OT', 'Nước dâng cao trên mặt đất một trăm năm mươi ngày.'),
(185, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 8, 1, 'OT', 'Đức Chúa Trời nhớ đến Nô-ê và mọi loài sinh vật, cùng mọi loài thú mà ở với người trong tàu; rồi Đức Chúa Trời khiến một luồng gió đi ngang qua trên đất, và nước bắt đầu rút xuống.'),
(186, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 8, 2, 'OT', 'Các mạch của vực thẳm và các cửa sổ trên trời đều bị đóng lại; mưa không còn đổ xuống từ trời nữa.'),
(187, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 8, 3, 'OT', 'Nước rút khỏi mặt đất dần dần, vừa đi vừa rút; và nước bớt lại từ cuối ngày thứ một trăm năm mươi.'),
(188, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 8, 4, 'OT', 'Chiếc tàu dừng lại vào tháng thứ bảy, ngày mười bảy của tháng, trên các núi A-ra-rát.'),
(189, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 8, 5, 'OT', 'Nước tiếp tục rút dần cho đến tháng mười; ngày mồng một tháng ấy, các đỉnh núi hiện ra.'),
(190, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 8, 6, 'OT', 'Sau bốn mươi ngày, Nô-ê mở cửa sổ của chiếc tàu mà ông đã làm.'),
(191, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 8, 7, 'OT', 'Thả con quạ ra; nó bay đi bay lại cho đến khi nước trên mặt đất rút khô.'),
(192, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 8, 8, 'OT', 'Người thả con bồ câu từ mình ra để xem nước đã rút khỏi mặt đất chưa.'),
(193, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 8, 9, 'OT', 'Bồ câu không tìm được chỗ nào cho bàn chân nó đậu, nên bay trở lại với ông trong tàu, vì nước còn phủ khắp mặt đất. Ông đưa tay ra, bắt lấy nó, rồi đưa nó vào tàu với mình.'),
(194, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 8, 10, 'OT', 'Người đợi thêm bảy ngày nữa, rồi lại sai con bồ câu ra khỏi tàu.'),
(195, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 8, 11, 'OT', 'Chiều đến, con bồ câu bay về cùng ông, và nầy, trong mỏ nó mang một lá ô-liu tươi; Nô-ê biết rằng nước đã giảm bớt trên mặt đất.'),
(196, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 8, 12, 'OT', 'Ngài đợi thêm bảy ngày nữa, rồi thả chim bồ câu ra; và nó không trở lại cùng Ngài nữa.'),
(197, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 8, 13, 'OT', 'Sáu trăm lẻ một tuổi đời của Nô-ê, ngày mồng một tháng giêng, nước đã rút khỏi mặt đất; Nô-ê liền dời tấm nắp tàu ra, nhìn xem, và nầy, mặt đất đã khô.'),
(198, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 8, 14, 'OT', 'Đến tháng hai, ngày hai mươi bảy của tháng ấy, đất đã khô.'),
(199, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 8, 15, 'OT', 'Đức Chúa Trời phán cùng Nô-ê rằng:'),
(200, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 8, 16, 'OT', 'Hãy ra khỏi tàu, ngươi và vợ ngươi, các con ngươi và các con dâu ngươi cùng với ngươi.'),
(201, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 8, 17, 'OT', 'Hãy dẫn ra khỏi ngươi mọi loài sinh vật thuộc mọi xác thịt, tức những loài chim, loài thú và mọi loài bò sát bò trên đất, để chúng sinh sôi nảy nở và gia tăng nhiều trên đất.'),
(202, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 8, 18, 'OT', 'Nô-ê ra khỏi tàu, cùng các con trai mình, vợ mình, và các vợ các con trai mình với người.'),
(203, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 8, 19, 'OT', 'Mọi loài vật, mọi loài bò sát và mọi loài chim, tất cả những gì bò trên mặt đất theo các họ hàng của chúng, đều ra khỏi tàu.'),
(204, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 8, 20, 'OT', 'Nô-ê xây một bàn thờ cho Đức Giê-hô-va, rồi lấy các loài thú vật thanh sạch và các loài chim thanh sạch, dâng của lễ thiêu trên bàn thờ.'),
(205, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 8, 21, 'OT', 'Đức Giê-hô-va cảm nhận mùi thơm dễ chịu, và Ngài phán trong lòng mình: Ta sẽ không còn rủa đất vì cớ loài người nữa, vì ý tưởng lòng người xấu từ khi còn thơ ấu; Ta cũng sẽ không còn đánh phạt mọi loài sống như Ta đã làm.'),
(206, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 8, 22, 'OT', 'Trọn các ngày đất còn, thì gieo giống và gặt hái, lạnh và nóng, mùa hè và mùa đông, ngày và đêm, sẽ không ngưng nghỉ.'),
(207, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 9, 1, 'OT', 'Đức Chúa Trời ban phước cho Nô-ê và các con trai người, rồi phán cùng họ rằng: Hãy sinh sản, gia tăng và làm đầy dẫy mặt đất.'),
(208, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 9, 2, 'OT', 'Sự khiếp sợ và kinh khủng các ngươi sẽ giáng trên mọi loài vật sống trên đất, mọi loài chim trời, mọi sinh vật bò trên đất và mọi loài cá biển; chúng đều được trao vào tay các ngươi.'),
(209, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 9, 3, 'OT', 'Mọi loài vật sống động đều được dùng làm thức ăn cho các ngươi; ta đã ban cho các ngươi mọi loài đó như [ta đã ban] các thứ cỏ xanh.'),
(210, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 9, 4, 'OT', 'Chỉ có điều, thịt còn hồn sống của nó, tức là máu của nó, các ngươi không được ăn.'),
(211, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 9, 5, 'OT', 'Quả thật, Ta sẽ đòi lại huyết các ngươi cho linh hồn các ngươi; Ta sẽ đòi lại nơi tay mọi loài vật sống, và nơi tay loài người, nơi tay mỗi người anh em của mình, Ta sẽ đòi lại mạng sống của loài người.'),
(212, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 9, 6, 'OT', 'Ai làm đổ máu người khác, thì máu người ấy cũng sẽ bị đổ; vì Đức Chúa Trời đã làm nên con người theo hình ảnh Ngài.'),
(213, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 9, 7, 'OT', 'Các ngươi hãy sinh sản, thêm nhiều, sinh sôi nảy nở trên đất và làm cho đầy dẫy đất.'),
(214, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 9, 8, 'OT', 'Đức Chúa Trời phán cùng Nô-ê và các con trai người, rằng:'),
(215, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 9, 9, 'OT', 'Còn ta đây, ta lập giao ước cùng các ngươi và cùng dòng dõi các ngươi sau các ngươi.'),
(216, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 9, 10, 'OT', 'và cùng mọi sinh vật sống ở với các ngươi, gồm loài chim, loài súc vật, và mọi loài thú trên đất, tức là tất cả những loài từ trong tàu ra, cho đến mọi loài vật trên đất.'),
(217, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 9, 11, 'OT', 'Ta lập giao ước cùng các ngươi, và mọi loài xác thịt sẽ không còn bị tiêu diệt bởi nước lụt nữa, và sẽ không còn có nước lụt để hủy hoại đất.'),
(218, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 9, 12, 'OT', 'Đức Chúa Trời phán: Đây là dấu chỉ của giao ước mà Ta đặt giữa Ta và các ngươi, và giữa mọi sinh vật sống đi cùng các ngươi, cho các thế hệ mãi mãi.'),
(219, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 9, 13, 'OT', 'Ta đặt cây cung của Ta trong đám mây, và nó sẽ là dấu chỉ cho sự giao ước giữa Ta và đất.'),
(220, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 9, 14, 'OT', 'Khi ta kéo các đám mây phủ trên mặt đất, thì cầu vồng sẽ hiện ra trong đám mây.'),
(221, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 9, 15, 'OT', 'Ta sẽ nhớ lại giao ước của Ta đã lập giữa Ta và các ngươi, và giữa Ta và mọi sinh vật sống, tức là mọi loài xác thịt; và nước sẽ không còn trở thành lụt để hủy diệt mọi loài xác thịt nữa.'),
(222, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 9, 16, 'OT', 'Và cầu vồng sẽ hiện trên mây, Ta nhìn thấy nó để nhớ giao ước đời đời giữa Đức Chúa Trời và mọi sinh vật sống, tức mọi loài xác thịt trên đất.'),
(223, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 9, 17, 'OT', 'Đức Chúa Trời phán cùng Nô-ê rằng: Đây là dấu chỉ của sự giao ước mà Ta đã lập giữa Ta và mọi loài xác thịt trên mặt đất.'),
(224, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 9, 18, 'OT', 'Các con trai của Nô-ê ra khỏi tàu là Sêm, và Hăm, và Gia-phết; và Hăm là cha của Ca-na-an.'),
(225, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 9, 19, 'OT', 'Ba người nầy là con trai của Nô-ê, và cũng từ ba người nầy mà toàn thể đất đai được phân ra.'),
(226, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 9, 20, 'OT', 'Người khởi sự cày ruộng, là Nô-ê, một người của đất, và trồng một vườn nho.'),
(227, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 9, 21, 'OT', 'Ông uống rượu rồi say, và để lộ mình trong lều của ông.'),
(228, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 9, 22, 'OT', 'Hăm, cha của Ca-na-an, thấy sự trần truồng của cha mình, bèn đi ra ngoài thuật lại cho hai anh em mình.'),
(229, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 9, 23, 'OT', 'Sêm và Gia-phết lấy cái áo choàng, đặt trên vai hai người, đi lùi lại, và lấy áo choàng mà che khuất sự trần truồng của cha mình; mặt hai người xây đi, không nhìn thấy sự trần truồng của cha mình.'),
(230, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 9, 24, 'OT', 'Nô-ê tỉnh rượu, và biết điều mà con út đã làm cho mình.'),
(231, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 9, 25, 'OT', 'Ngài phán rằng: Đáng rủa sả thay Ca-na-an! Nó sẽ làm tôi mọi cho anh em nó.'),
(232, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 9, 26, 'OT', 'Đức Giê-hô-va, Đức Chúa Trời của Sêm, đáng được ca ngợi; và Ca-na-an sẽ làm tôi mọi cho họ.'),
(233, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 9, 27, 'OT', 'Nguyện Đức Chúa Trời làm cho Gia-phết được mở rộng, và người sẽ ở trong các trại của Sêm; còn Ca-na-an sẽ làm tôi cho họ.'),
(234, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 9, 28, 'OT', 'Sau trận lụt, Nô-ê sống thêm ba trăm năm và năm mươi năm nữa.'),
(235, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 9, 29, 'OT', 'Nô-ê sống được chín trăm năm và năm mươi năm, rồi qua đời.'),
(236, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 10, 1, 'OT', 'Đây là dòng dõi của các con trai Nô-ê, ấy là Sêm, Hăm và Gia-phết; sau trận lụt, người ta sanh con cái.'),
(237, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 10, 2, 'OT', 'Các con trai của Gia-phết là Gô-me, Ma-gốc, Ma-đai, Gia-van, Tu-banh, Mê-siếc và Ti-ra.'),
(238, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 10, 3, 'OT', 'Các con trai của Gô-me là Aùch-kê-na, Ri-phát và Tô-ga-ma.'),
(239, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 10, 4, 'OT', 'Con trai của Gia-van là Ê-li-sa, Ta-rê-si, Kít-tim và Đô-đa-nim.'),
(240, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 10, 5, 'OT', 'Từ những người ấy, các dân tộc trên các đảo được phân rã theo đất nước mình, mỗi người theo tiếng nói, họ hàng và dân tộc của mình.'),
(241, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 10, 6, 'OT', 'Con trai của Hăm là Cút, Mích-ra-im, Phút và Ca-na-an.'),
(242, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 10, 7, 'OT', 'Con trai của Cút là Sê-ba, Ha-vi-la, Sáp-ta, Ra-ê-ma và Sáp-tê-ca; con trai của Ra-ê-ma là Sê-la và Đê-đan.'),
(243, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 10, 8, 'OT', 'Cút sinh ra Nim-rốt; chính người ấy là người đầu tiên trở nên một anh hùng quyền thế trên đất.'),
(244, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 10, 9, 'OT', 'Người là một chiến sĩ săn bắn hùng mạnh trước mặt Đức Giê-hô-va. Bởi cớ ấy, người ta thường nói: "Giống như Nim-rốt, một chiến sĩ săn bắn hùng mạnh trước mặt Đức Giê-hô-va."'),
(245, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 10, 10, 'OT', 'Khởi đầu vương quốc của người là Ba-bên, rồi Ê-réc, A-cát và Ca-ne, tại đất Si-nê-a.'),
(246, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 10, 11, 'OT', 'Từ xứ đó, A-si-ri đã đi ra, xây thành Ni-ni-ve, Rê-hô-bô-ti và Ca-lách,'),
(247, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 10, 12, 'OT', 'Và Rê-sen, giữa Ni-ni-ve và Ca-lách, ấy là thành lớn.'),
(248, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 10, 13, 'OT', 'Mích-ra-im sanh ra họ Lu-đim, họ A-na-mim, họ Lê-ha-bim và họ Náp-tu-him.'),
(249, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 10, 14, 'OT', 'và họ Bát-ru-sim, và họ Cách-lu-him, bởi đó sanh ra họ Phi-li-tin, và họ Cáp-tô-rim.'),
(250, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 10, 15, 'OT', 'Ca-na-an sinh Si-đôn, con trai đầu lòng của người, và Hết.'),
(251, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 10, 16, 'OT', 'và dân Giê-bu-sít, và dân A-mô-rít, và dân Ghi-rê-ga-sít,'),
(252, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 10, 17, 'OT', 'và người Hê-vít, và người A-rê-kít, và người Si-nít.'),
(253, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 10, 18, 'OT', 'Và người A-va-đít, và người Xê-ma-rít, và người Ha-ma-tít; sau đó, các gia tộc của người Ca-na-an bị phân tán.'),
(254, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 10, 19, 'OT', 'Địa giới của người Ca-na-an chạy từ Si-đôn về phía Ghê-ra, cho đến Ga-xa; và từ Sô-đôm, Gô-mô-rơ, Aùt-ma và Sê-bô-im, cho đến Lê-sa.'),
(255, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 10, 20, 'OT', 'Đây là các con trai của Hăm, theo các gia tộc của họ, theo các thứ tiếng nói của họ, trong các xứ của họ, theo các dân tộc của họ.'),
(256, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 10, 21, 'OT', 'Sêm cũng có sinh con trai; người là tổ phụ của tất cả các con cháu của Hê-be, anh cả của Gia-phết.'),
(257, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 10, 22, 'OT', 'Các con trai của Sêm là Ê-lam, A-su-rơ, A-bác-sát, Lút và A-ram.'),
(258, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 10, 23, 'OT', 'Con trai của A-ram là U-xơ, Hu-lơ, Ghê-te và Mách.'),
(259, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 10, 24, 'OT', 'A-bác-sát sinh ra Sê-lách; Sê-lách sinh ra Hê-be.'),
(260, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 10, 25, 'OT', 'Hê-be sinh hai con trai; tên một người là Bê-léc, vì trong đời người ấy, đất bị chia cách ra; tên người anh em người ấy là Giốc-tan.'),
(261, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 10, 26, 'OT', 'Giốc-tan sinh ra A-mô-đát, Sê-lép, Ha-sa-ma-vết và Giê-rách.'),
(262, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 10, 27, 'OT', 'Và Ha-đô-ram, và U-xa, và Điếc-la,'),
(263, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 10, 28, 'OT', 'và Ô-banh, A-bi-ma-ên, và Sê-ba,'),
(264, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 10, 29, 'OT', 'Ô-phia, Ha-vi-la và Giô-báp. Tất cả những người này là con trai của Giốc-tan.'),
(265, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 10, 30, 'OT', 'Chỗ ở của họ từ Mê-sa, trải dài đến Sê-pha, núi về phía đông.'),
(266, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 10, 31, 'OT', 'Đây là các con trai của Sêm, theo các họ hàng, theo các thứ tiếng của họ, tại các xứ của họ, theo các dân tộc của họ.'),
(267, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 10, 32, 'OT', 'Đây là các gia tộc của con trai Nô-ê, theo các dòng dõi của họ trong các dân tộc mình; từ những người này mà các dân đã phân tán ra trên đất sau trận lụt.'),
(268, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 11, 1, 'OT', 'Cả đất đều có một thứ tiếng và cùng một cách diễn đạt.'),
(269, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 11, 2, 'OT', 'Họ khởi hành từ phương đông, rồi tìm được một thung lũng trong đất Si-nê-a, và ở lại đó.'),
(270, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 11, 3, 'OT', 'Họ nói với nhau: "Hãy đi, chúng ta hãy làm gạch và nung trong lửa." Gạch bèn dùng làm đá, và nhựa sô làm hồ.'),
(271, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 11, 4, 'OT', 'Họ nói: Nào, chúng ta hãy xây cho mình một thành và một tháp, đỉnh tháp hướng lên trời; hãy làm cho mình danh tiếng, e rằng chúng ta bị phân tán khắp mặt đất.'),
(272, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 11, 5, 'OT', 'Đức Giê-hô-va ngự xuống để xem thành và tháp mà con cái loài người đã xây.'),
(273, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 11, 6, 'OT', 'Đức Giê-hô-va phán: Nầy, chúng là một dân, một thứ tiếng cho hết thảy; và nầy là điều chúng khởi sự làm; bây giờ không gì ngăn trở được chúng, mọi điều chúng toan làm.'),
(274, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 11, 7, 'OT', 'Chúng ta hãy xuống, và ở đó làm lộn xộn tiếng nói của chúng nó, để người này không hiểu được tiếng nói của người kia.'),
(275, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 11, 8, 'OT', 'Đức Giê-hô-va làm cho chúng tản lạc từ đó ra khắp mặt đất, và họ thôi xây cất thành.'),
(276, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 11, 9, 'OT', 'Bởi vậy người ta đặt tên cho thành ấy là Ba-bên, vì tại đó Đức Giê-hô-va đã làm lộn xộn tiếng nói của toàn thể thế gian, và từ đó Đức Giê-hô-va làm cho họ tản lạc khắp mặt đất.'),
(277, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 11, 10, 'OT', 'Đây là dòng dõi của Sêm: Sêm được một trăm tuổi và sinh ra A-bác-sát, hai năm sau cơn Đại Hồng Thủy.'),
(278, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 11, 11, 'OT', 'Sau khi Sêm sinh ra A-bác-sát, người còn sống năm trăm năm nữa, và sinh các con trai và các con gái.'),
(279, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 11, 12, 'OT', 'A-bác-sát sống ba mươi lăm năm rồi sinh ra Sê-lách.'),
(280, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 11, 13, 'OT', 'A-bác-sát sống thêm bốn trăm ba năm sau khi sinh Sê-lách, rồi sinh các con trai và các con gái.'),
(281, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 11, 14, 'OT', 'Sê-lách sống ba mươi năm, rồi sinh ra Hê-be.'),
(282, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 11, 15, 'OT', 'Sê-lách sống sau khi sinh ra Hê-be ba năm và bốn trăm năm nữa, rồi sinh các con trai và các con gái.'),
(283, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 11, 16, 'OT', 'Hê-be sống ba mươi bốn năm, rồi sinh Bê-léc.'),
(284, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 11, 17, 'OT', 'Hê-be sống sau khi sanh Bê-léc ba mươi năm và bốn trăm năm nữa, rồi sanh các con trai và các con gái.'),
(285, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 11, 18, 'OT', 'Bê-léc sống ba mươi năm, rồi sanh Rê-hu.'),
(286, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 11, 19, 'OT', 'Bê-léc sống hai trăm chín năm sau khi sanh Rê-hu, và sanh các con trai và các con gái.'),
(287, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 11, 20, 'OT', 'Rê-hu sống ba mươi hai năm, rồi sinh Sê-rúc.'),
(288, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 11, 21, 'OT', 'Rê-hu sống sau khi sinh Sê-rúc bảy năm và hai trăm năm, và sinh các con trai và các con gái.'),
(289, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 11, 22, 'OT', 'Sê-rúc sống ba mươi năm và sinh ra Na-cô.'),
(290, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 11, 23, 'OT', 'Sau khi Sê-rúc sanh Na-cô rồi, còn sống hai trăm năm, và sanh các con trai và các con gái.'),
(291, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 11, 24, 'OT', 'Na-cô sống hai mươi chín năm, rồi sanh Tha-rê.'),
(292, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 11, 25, 'OT', 'Na-cô sống một trăm mười chín năm sau khi sanh Tha-rê, rồi sanh con trai và con gái.'),
(293, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 11, 26, 'OT', 'Tha-rê sống được bảy mươi tuổi, rồi sinh Aùp-ram, Na-cô và Ha-ran.'),
(294, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 11, 27, 'OT', 'Đây là dòng dõi của Tha-rê: Tha-rê sinh Aùp-ram, Na-cô và Ha-ran; và Ha-ran sinh ra Lót.'),
(295, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 11, 28, 'OT', 'Ha-ran qua đời trước mặt Tha-rê, cha người, tại đất sinh ra ông, tức là U-rơ thuộc xứ Canh-đê.'),
(296, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 11, 29, 'OT', 'Aùp-ram và Na-cô cưới vợ; tên vợ Aùp-ram là Sa-rai, và tên vợ Na-cô là Minh-ca, con gái của Ha-ran, cha của Minh-ca và cha của Dích-ca.'),
(297, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 11, 30, 'OT', 'Sa-rai thì son sẻ, không có con.'),
(298, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 11, 31, 'OT', 'Tha-rê dẫn Aùp-ram, con trai mình, và Lót, con trai Ha-ran, cháu mình, cùng Sa-rai, vợ Aùp-ram, con dâu mình, cùng ra khỏi U-rơ thuộc xứ Canh-đê, đặng đi đến đất Ca-na-an; thì họ đến Cha-ran và ở lại đó.'),
(299, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 11, 32, 'OT', 'Tha-rê hưởng thọ được hai trăm lẻ năm năm, rồi qua đời tại Cha-ran.'),
(300, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 12, 1, 'OT', 'Đức Giê-hô-va phán cùng Aùp-ram: Hãy đi ra khỏi xứ ngươi, nơi ngươi sinh ra và nhà cha ngươi, đến xứ mà Ta sẽ chỉ cho ngươi.'),
(301, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 12, 2, 'OT', 'Ta sẽ làm cho ngươi thành một dân lớn, sẽ ban phước cho ngươi, sẽ làm cho danh ngươi được tôn trọng, và ngươi sẽ trở nên một nguồn phước.'),
(302, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 12, 3, 'OT', 'Ta sẽ ban phước cho những người chúc phước ngươi, và ai rủa sả ngươi, Ta sẽ rủa sả; mọi chi họ trên đất sẽ nhờ ngươi mà được ban phước.'),
(303, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 12, 4, 'OT', 'Aùp-ram bèn đi, theo như điều Đức Giê-hô-va đã phán cùng người; và Lót đi cùng người. Aùp-ram bảy mươi lăm tuổi khi người ra đi từ Cha-ran.'),
(304, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 12, 5, 'OT', 'Aùp-ram dẫn Sa-rai, vợ mình, và Lót, con trai em mình, cùng mọi tài sản mà họ đã có, và những người mà họ đã làm ra tại Cha-ran; rồi họ ra đi đến xứ Ca-na-an; và họ đều đến xứ Ca-na-an.'),
(305, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 12, 6, 'OT', 'Aùp-ram đi ngang qua xứ đến nơi Si-chem, đến cây dẻ bộp của Mô-rê; lúc ấy, dân Ca-na-an đang ở trong xứ.'),
(306, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 12, 7, 'OT', 'Đức Giê-hô-va hiện ra cùng Aùp-ram, và phán rằng: Ta sẽ ban đất nầy cho dòng dõi ngươi. Rồi người xây một bàn thờ tại đó cho Đức Giê-hô-va là Đấng đã hiện ra cùng người.'),
(307, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 12, 8, 'OT', 'Người dời khỏi nơi đó đến vùng núi phía đông Bê-tên, dựng lều; Bê-tên ở về phía tây, còn A-hi ở phía đông. Người xây dựng một bàn thờ tại đó cho Đức Giê-hô-va và kêu cầu danh Đức Giê-hô-va.'),
(308, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 12, 9, 'OT', 'Aùp-ram đi tiếp, vừa đi vừa dời trại về miền Nam.'),
(309, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 12, 10, 'OT', 'Xảy ra đói kém trong đất; và vì cơn đói kém rất nặng trong đất, nên Aùp-ram đi xuống Ê-díp-tô để tạm cư ở đó.'),
(310, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 12, 11, 'OT', 'Khi gần vào Ai-cập, Aùp-ram nói cùng Sa-rai, vợ mình, rằng: Nầy, ta biết ngươi là một người đàn bà đẹp.'),
(311, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 12, 12, 'OT', 'Khi người Ai Cập thấy nàng, họ sẽ nói: "Đó là vợ hắn"; rồi họ sẽ giết tôi, nhưng sẽ để nàng sống.'),
(312, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 12, 13, 'OT', 'Xin hãy nói rằng: "Ngài là em gái tôi," để nhờ đó tôi được đối xử tốt vì cớ ngài, và mạng tôi được giữ nhờ ngài.'),
(313, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 12, 14, 'OT', 'Khi Aùp-ram đến xứ Ê-díp-tô, người Ê-díp-tô thấy người đàn bà đó, vì nàng rất đẹp.'),
(314, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 12, 15, 'OT', 'Các quan của Pha-ra-ôn thấy nàng, bèn khen ngợi nàng trước mặt Pha-ra-ôn; và người đàn bà ấy được đưa vào nhà của Pha-ra-ôn.'),
(315, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 12, 16, 'OT', 'Vì cớ nàng, Aùp-ram được đãi ngộ tốt nơi Pha-ra-ôn, và ông có được chiên, bò, lừa đực, tôi trai, tớ gái, lừa cái và lạc đà.'),
(316, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 12, 17, 'OT', 'Đức Giê-hô-va giáng những tai họa nặng nề cho Pha-ra-ôn và nhà người, vì cớ Sa-rai, vợ Aùp-ram.'),
(317, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 12, 18, 'OT', 'Pha-ra-ôn gọi Aùp-ram và nói: Ngươi đã làm chi cho ta vậy? Sao không nói cho ta biết nàng là vợ ngươi?'),
(318, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 12, 19, 'OT', 'Sao ông nói: "Chị ấy là em gái tôi," khiến tôi lấy nàng làm vợ? Bây giờ, vợ ông đây, hãy nhận nàng và đi đi.'),
(319, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 12, 20, 'OT', 'Pha-ra-ôn truyền cho các người hầu về Aùp-ram, và họ đưa người cùng vợ và mọi vật người có đi.'),
(320, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 13, 1, 'OT', 'Aùp-ram đi lên từ Ê-díp-tô, người và vợ người, cùng mọi vật sở hữu của người, và Lót đi với người về miền Nam.'),
(321, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 13, 2, 'OT', 'Aùp-ram rất giàu có về súc vật, bạc và vàng.'),
(322, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 13, 3, 'OT', 'Người đi từng trạm, từ miền Nam cho đến Bê-tên, đến nơi trước kia người đã dựng lều giữa Bê-tên và A-hi.'),
(323, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 13, 4, 'OT', 'đến nơi có bàn thờ mà người đã làm trước đó, và tại đó Aùp-ram kêu cầu danh Đức Giê-hô-va.'),
(324, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 13, 5, 'OT', 'Lúc ấy, Lót đi với Aùp-ram cũng có chiên, bò và trại.'),
(325, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 13, 6, 'OT', 'Xứ đó không thể nào dung chứa nổi cả hai người cùng ở chung, vì tài sản của họ rất nhiều, khiến họ không thể ở chung với nhau được.'),
(326, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 13, 7, 'OT', 'Có sự tranh chấp giữa các mục đồng của Aùp-ram và các mục đồng của Lót; lúc ấy người Ca-na-an và người Phê-rê-sít đang cư ngụ trong xứ.'),
(327, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 13, 8, 'OT', 'Aùp-ram nói với Lót: "Xin đừng có sự tranh cãi giữa tôi và anh, giữa các người chăn chiên của tôi và các người chăn chiên của anh, vì chúng ta là anh em ruột thịt."'),
(328, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 13, 9, 'OT', 'Toàn bộ đất đai há chẳng ở trước mặt ngươi sao? Vậy, hãy tách rời khỏi ta; nếu ngươi đi về phía bên trái, ta sẽ đi về phía bên phải; nếu ngươi đi về phía bên phải, ta sẽ đi về phía bên trái.'),
(329, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 13, 10, 'OT', 'Lót ngước mắt lên, thấy toàn bộ đồng bằng bên sông Giô-đanh; vì trước khi Đức Giê-hô-va hủy diệt Sô-đôm và Gô-mô-rơ, nơi ấy thảy đều được tưới nước, như vườn của Đức Giê-hô-va, như xứ Ê-díp-tô, cho đến Xoa.'),
(330, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 13, 11, 'OT', 'Lót chọn cho mình toàn bộ vùng đất bằng bên sông Giô-đanh, rồi Lót đi về phía đông. Thế là hai người tách ra khỏi nhau.'),
(331, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 13, 12, 'OT', 'Aùp-ram ở trong xứ Ca-na-an, còn Lót ở trong các thành phố của đồng bằng, và dựng lều mình cho đến Sô-đôm.'),
(332, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 13, 13, 'OT', 'Dân Sô-đôm thì độc ác và phạm tội cùng Đức Giê-hô-va cách nghiêm trọng.'),
(333, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 13, 14, 'OT', 'Sau khi Lót đã tách khỏi Aùp-ram, Đức Giê-hô-va phán cùng Aùp-ram rằng: Hãy ngước mắt lên, nhìn từ nơi ngươi đang đứng về phía bắc, nam, đông và tây:'),
(334, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 13, 15, 'OT', 'Vì mọi đất đai ngươi thấy, Ta sẽ ban cho ngươi và cho dòng dõi ngươi đến đời đời.'),
(335, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 13, 16, 'OT', 'Ta sẽ làm cho dòng dõi ngươi như bụi trên đất; nếu ai đó có thể đếm được bụi trên đất, thì dòng dõi ngươi cũng sẽ được đếm như vậy.'),
(336, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 13, 17, 'OT', 'Hãy đứng dậy, đi dọc theo chiều dài và chiều rộng của đất nầy, vì Ta sẽ ban nó cho ngươi.'),
(337, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 13, 18, 'OT', 'Aùp-ram dời trại mình đến ở nơi lùm cây Mam-rê tại Hếp-rôn, và người lập tại đó một bàn thờ cho Đức Giê-hô-va.'),
(338, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 14, 1, 'OT', 'Trong những ngày của Am-ra-phên, vua Si-nê-a, A-ri-óc, vua Ê-la-sa, Kết-rô-Lao me, vua Ê-lam, và Ti-đanh, vua Gô-im,'),
(339, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 14, 2, 'OT', 'Các vua này giao chiến với Bê-ra, vua Sô-đôm, với Bi-rê-sa, vua Gô-mô-rơ, Si-nê-áp, vua Aùt-ma, Sê-mê-bê, vua Xê-bô-im, và vua Bê-la, tức là Xoa.'),
(340, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 14, 3, 'OT', 'Tất cả những người nầy hiệp lại tại trũng Si-điêm, tức là biển Muối.'),
(341, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 14, 4, 'OT', 'Mười hai năm, họ phục dịch vua Kết-rô-Lao; đến năm thứ mười ba, họ nổi loạn.'),
(342, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 14, 5, 'OT', 'Năm thứ mười bốn, Kết-rô-Lao-me và các vua đi cùng người đến đánh dân Rê-pha-im tại Aùch-tê-rót-Ca-na-im, dân Xu-xin tại Ham, và dân Ê-mim tại đồng bằng Ki-ri-a-ta-im.'),
(343, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 14, 6, 'OT', 'và dân Hô-rít tại các núi Sê-i-rơ, cho đến nơi Eân-Ba-ran, là nơi ở gần đồng vắng.'),
(344, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 14, 7, 'OT', 'Rồi họ trở lại và đến Suối Xử-đoán, tức là Ca-đe, đánh bại toàn bộ vùng đất của người A-ma-léc, và cả người A-mô-rít đang sống tại Hát-sát-sôn-Tha-ma.'),
(345, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 14, 8, 'OT', 'Vua của Sô-đôm, vua của Gô-mô-rơ, vua của Aùt-ma, vua của Xê-bô-im và vua Bê-la, tức là Xoa, liền xuất trận và bày trận nghịch cùng chúng tại trũng Si-điêm.'),
(346, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 14, 9, 'OT', 'đấu cùng Kết-rô-Lao-me, vua Ê-lam, và Ti-đanh, vua Gô-im, và Am-ra-phên, vua Si-nê-a, và A-ri-óc, vua Ê-la-sa; bốn vua nầy đánh năm vua.'),
(347, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 14, 10, 'OT', 'Vả chăng, trong trũng Si-điêm có các hố đầy nhựa hắc ín; vua Sô-đôm và vua Gô-mô-rơ thua chạy, đều sa xuống đó; còn những kẻ sót lại thì chạy trốn lên núi.'),
(348, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 14, 11, 'OT', 'Bọn chúng lấy hết thảy tài sản của Sô-đôm và Gô-mô-rơ, cùng mọi lương thực của hai thành ấy, rồi đi.'),
(349, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 14, 12, 'OT', 'Bọn chúng bắt lấy Lót và mọi tài sản của ông, cháu trai của Aùp-ram, người đang sống tại Sô-đôm, rồi đi khỏi.'),
(350, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 14, 13, 'OT', 'Và một người thoát được đã đến báo cho Aùp-ram, người Hê-bơ-rơ, là kẻ đang ở tại các cây sồi của Mam-rê, người A-mô-rít, anh của Eách-côn và anh của A-ne; và họ là những người đồng lập giao ước với Aùp-ram.'),
(351, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 14, 14, 'OT', 'Aùp-ram nghe tin cháu mình bị bắt đi, liền đem các đầy tớ trung thành sinh ra trong nhà mình, gồm ba trăm mười tám người, cùng đuổi theo đến Đan.'),
(352, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 14, 15, 'OT', 'Aùp-ram chia các đầy tớ mình ra, tấn công chúng ban đêm, đánh bại chúng, và rượt đuổi đến Hô-ba, nằm bên tay trái Đa-mách.'),
(353, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 14, 16, 'OT', 'Người đem trả lại tất cả tài sản, và cũng đem trả cháu mình là Lót cùng tài sản của người, các người đàn bà và dân chúng.'),
(354, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 14, 17, 'OT', 'Sau khi Aùp-ram trở về từ cuộc đánh bại Kết-rô-Lao-me và các vua đi cùng người ấy, thì vua Sô-đôm ra đón người tại trũng Sa-ve, tức là trũng Vua.'),
(355, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 14, 18, 'OT', 'Mên-chi-xê-đéc, vua Sa-lem, đem bánh và rượu ra; người là thầy tế lễ của Đức Chúa Trời Chí Cao.'),
(356, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 14, 19, 'OT', 'Chúc phước cho Aùp-ram và nói rằng: Đáng chúc tụng thay Aùp-ram, bởi Đức Chúa Trời Chí cao, là Đấng dựng nên trời và đất!'),
(357, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 14, 20, 'OT', 'Đáng ngợi khen thay Đức Chúa Trời Chí cao, là Đấng đã giao các kẻ thù của ngươi vào tay ngươi! Aùp-ram dâng cho người một phần mười về tất cả.'),
(358, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 14, 21, 'OT', 'Vua Sô-đôm nói với Aùp-ram: Hãy giao người cho tôi, còn của cải thì ông lấy đi.'),
(359, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 14, 22, 'OT', 'Aùp-ram nói với vua Sô-đôm: Tôi giơ tay lên hướng về Đức Giê-hô-va Đức Chúa Trời Chí cao, Đấng dựng nên trời và đất.'),
(360, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 14, 23, 'OT', 'Tôi chẳng thèm lấy từ một sợi chỉ cho đến một sợi dây giày, và chẳng lấy bất cứ điều chi thuộc về ngài, hầu cho ngài không thể nói: "Tôi đã làm cho Aùp-ram trở nên giàu có."'),
(361, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 14, 24, 'OT', 'Chỉ những người trẻ đã ăn, và phần của những người đã đi cùng tôi, là A-ne, Eách-côn và Mam-rê; chính họ sẽ nhận phần của mình.'),
(362, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 15, 1, 'OT', 'Sau các điều đó, có lời của Đức Giê-hô-va phán cùng Aùp-ram trong một sự hiện thấy rằng: Đừng sợ, hỡi Aùp-ram! Ta đây là cái khiên che chở ngươi; phần thưởng ngươi sẽ rất lớn.'),
(363, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 15, 2, 'OT', 'Aùp-ram thưa rằng: Lạy Đức Giê-hô-va, Chúa sẽ cho tôi điều gì? Tôi vẫn đi mà không có con, và người kế tự nhà tôi là Ê-li-é-xe, người Đa-mách.'),
(364, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 15, 3, 'OT', 'Aùp-ram nói: Nầy, Ngài chưa cho tôi một đứa con, và một đầy tớ sinh ra trong nhà tôi sẽ là người kế vị tôi.'),
(365, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 15, 4, 'OT', 'Đức Giê-hô-va phán cùng Aùp-ram rằng: Kẻ nầy sẽ không kế tự ngươi; nhưng chính người nào ra từ mình ngươi, ấy là kẻ sẽ kế tự ngươi.'),
(366, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 15, 5, 'OT', 'Người đưa ông ra ngoài và nói: "Hãy ngước mắt lên trời, đếm các ngôi sao xem ông có đếm được không." Ngài phán với ông: "Dòng dõi ông sẽ đông như vậy."'),
(367, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 15, 6, 'OT', 'Aùp-ram tin Đức Giê-hô-va, và Ngài kể sự đó là công bình cho người.'),
(368, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 15, 7, 'OT', 'Đức Giê-hô-va phán cùng Aùp-ram: Ta là Đức Giê-hô-va, Đấng đã dẫn ngươi ra khỏi U-rơ của người Canh-đê, để ban cho ngươi đất nầy làm sản nghiệp.'),
(369, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 15, 8, 'OT', 'Aùp-ram thưa: Lạy Đức Giê-hô-va, tôi biết bằng cách nào rằng tôi sẽ nhận được xứ nầy làm sản nghiệp?'),
(370, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 15, 9, 'OT', 'Đức Giê-hô-va phán cùng người rằng: Hãy bắt đem cho Ta một con bò cái ba tuổi, một con dê cái ba tuổi, một con chiên đực ba tuổi, một con chim ưng và một con bồ câu non.'),
(371, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 15, 10, 'OT', 'Aùp-ram bắt các loài vật ấy, mổ chúng ra làm đôi, đặt mỗi nửa con đối diện nhau; còn loài chim thì ông không mổ ra làm đôi.'),
(372, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 15, 11, 'OT', 'Các chim ưng bay xuống trên các xác chết, thì Aùp-ram đuổi chúng đi.'),
(373, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 15, 12, 'OT', 'Mặt trời vừa lặn, thì Aùp-ram bị ngủ mê, và nầy, một cơn kinh hãi tối tăm lớn lao giáng trên người.'),
(374, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 15, 13, 'OT', 'Đức Giê-hô-va phán cùng Aùp-ram rằng: Phải biết rõ rằng dòng dõi ngươi sẽ làm khách lạ trong đất không thuộc về chúng nó, và phục vụ họ, và bị họ hà hiếp bốn trăm năm.'),
(375, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 15, 14, 'OT', 'Nhưng ta sẽ đoán phạt dân mà họ phải phục sự; và sau đó họ sẽ ra đi với của cải rất lớn.'),
(376, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 15, 15, 'OT', 'Còn ngươi sẽ về cùng tổ phụ mình trong bình an, được chôn cất khi đã sống lâu và hưởng phúc lộc.'),
(377, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 15, 16, 'OT', 'Đời thứ tư, họ sẽ trở lại đây, vì tội ác của dân A-mô-rít chưa đầy đủ đến lúc này.'),
(378, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 15, 17, 'OT', 'Khi mặt trời lặn và trời tối lại, nầy, một cái lò khói và một ngọn đuốc lửa đi ngang qua giữa những miếng thịt ấy.'),
(379, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 15, 18, 'OT', 'Trong ngày ấy, Đức Giê-hô-va lập giao ước với Aùp-ram, phán rằng: Ta đã ban cho dòng dõi ngươi đất nầy, từ sông Ê-díp-tô cho đến sông lớn, tức sông Ơ-phơ-rát.'),
(380, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 15, 19, 'OT', 'Dân Cát-mô-nít, dân Kê-nê-sít, và dân Kê-nít.'),
(381, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 15, 20, 'OT', 'và dân Hê-tít, dân Phê-rê-sít, và dân Rê-pha-im,'),
(382, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 15, 21, 'OT', 'và người A-mô-rít, và người Ca-na-an, và người Ghi-ê-ga-sít, và người Giê-bu-sít.'),
(383, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 16, 1, 'OT', 'Sa-rai, vợ của Aùp-ram, không sanh con cho người; nàng có một tớ gái người Ai-cập, tên là A-ga.'),
(384, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 16, 2, 'OT', 'Sa-rai nói cùng Aùp-ram rằng: Nầy, Đức Giê-hô-va đã ngăn tôi khỏi việc sinh đẻ; vậy hãy vào cùng con tớ gái tôi, may ra tôi sẽ được xây dựng bởi nàng. Aùp-ram bèn nghe theo tiếng của Sa-rai.'),
(385, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 16, 3, 'OT', 'Sau mười năm Aùp-ram sống tại xứ Ca-na-an, Sa-rai, vợ người, bèn bắt A-ga, người đầy tớ gái người Ai Cập, và đưa cho Aùp-ram, chồng mình, làm vợ.'),
(386, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 16, 4, 'OT', 'Người vào cùng A-ga, và nàng thọ thai; khi thấy mình đã thọ thai, thì coi thường bà chủ mình.'),
(387, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 16, 5, 'OT', 'Sa-rai nói với Aùp-ram: "Sự oán trách của tôi là tại ông! Tôi đã trao nữ tì tôi vào lòng ông, mà từ khi thấy mình mang thai, nó khinh tôi. Đức Giê-hô-va hãy xét xử giữa tôi và ông."'),
(388, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 16, 6, 'OT', 'Aùp-ram nói cùng Sa-rai: Nầy, A-ga là tôi tớ ngươi, ngươi cứ xử với nàng theo ý ngươi cho phải. Nhưng Sa-rai đối đãi cay nghiệt với nàng, nên nàng trốn khỏi mặt người.'),
(389, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 16, 7, 'OT', 'Thiên sứ của Đức Giê-hô-va gặp nàng bên cạnh suối nước trong đồng vắng, tức là bên cạnh suối nước trên đường đi về Su-rơ.'),
(390, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 16, 8, 'OT', 'Đức Giê-hô-va phán: "Hỡi A-ga, đòi của Sa-rai, ngươi từ đâu đến, và ngươi sẽ đi đâu?" Nàng thưa: "Tôi đang trốn khỏi mặt Sa-rai, chủ tôi."'),
(391, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 16, 9, 'OT', 'Thiên sứ của Đức Giê-hô-va bảo nàng rằng: "Hãy trở về cùng bà chủ ngươi, và chịu khuất phục dưới tay bà ấy."'),
(392, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 16, 10, 'OT', 'Đức Giê-hô-va phán cùng người rằng: Ta sẽ làm cho dòng dõi ngươi đông vô số, đông đến nỗi không thể đếm được.'),
(393, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 16, 11, 'OT', 'Đức Giê-hô-va phán cùng nàng rằng: Nầy, ngươi đang mang thai, sẽ sinh một trai, và ngươi sẽ đặt tên nó là Ích-ma-ên, vì Đức Giê-hô-va đã nghe sự khốn khổ của ngươi.'),
(394, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 16, 12, 'OT', 'Nó sẽ như một con lừa rừng; tay nó sẽ chống lại mọi người, và tay mọi người chống lại nó. Nó sẽ ở đối diện với tất cả anh em mình.'),
(395, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 16, 13, 'OT', 'Bấy giờ nàng kêu danh Đức Giê-hô-va, là Đấng đã phán cùng nàng rằng: "Ngài là Đức Chúa Trời thấy tôi," vì nàng nói: "Phải, tại đây tôi đã thấy Đấng thấy tôi sao?"'),
(396, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 16, 14, 'OT', 'Bởi cớ ấy, người ta gọi cái giếng ấy là Bê-er La-chai-Roi; nó ở giữa Ca-đe và Bê-re.'),
(397, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 16, 15, 'OT', 'A-ga sanh cho Aùp-ram một con trai, và Aùp-ram đặt tên con trai mà A-ga đã sanh là Ích-ma-ên.'),
(398, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 16, 16, 'OT', 'Aùp-ram tám mươi sáu tuổi khi A-ga sanh Ích-ma-ên cho Aùp-ram.'),
(399, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 17, 1, 'OT', 'Khi Aùp-ram được chín mươi chín tuổi, thì Đức Giê-hô-va hiện ra cùng Aùp-ram và phán rằng: Ta là Đức Chúa Trời Toàn Năng; hãy đi trước mặt ta và hãy làm một người trọn vẹn.'),
(400, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 17, 2, 'OT', 'Ta sẽ lập giao ước giữa Ta và ngươi, và làm cho ngươi thêm đông đảo cách rất nhiều.'),
(401, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 17, 3, 'OT', 'Aùp-ram sấp mình xuống đất; Đức Chúa Trời phán cùng người rằng:'),
(402, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 17, 4, 'OT', 'Nầy, ta đây lập giao ước cùng ngươi, và ngươi sẽ trở nên tổ phụ của nhiều dân tộc.'),
(403, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 17, 5, 'OT', 'Và từ nay ngươi sẽ không còn được gọi là Aùp-ram nữa, mà tên ngươi sẽ là Aùp-ra-ham, vì ta đặt ngươi làm tổ phụ của nhiều dân tộc.'),
(404, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 17, 6, 'OT', 'Ta sẽ khiến ngươi sinh sản cực kỳ dồi dào, khiến ngươi thành nên các nước, và các vua sẽ xuất hiện từ nơi ngươi.'),
(405, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 17, 7, 'OT', 'Ta sẽ lập giao ước Ta giữa Ta và ngươi, và giữa Ta và dòng dõi ngươi sau ngươi, trải qua các thế hệ, làm giao ước đời đời, để Ta làm Đức Chúa Trời của ngươi và của dòng dõi ngươi sau ngươi.'),
(406, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 17, 8, 'OT', 'Ta sẽ ban cho ngươi và cho dòng dõi ngươi sau này xứ mà ngươi đang tạm trú, tức là toàn thể xứ Ca-na-an, làm cơ nghiệp đời đời; và Ta sẽ làm Đức Chúa Trời của họ.'),
(407, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 17, 9, 'OT', 'Đức Chúa Trời phán cùng Aùp-ra-ham rằng: "Ngươi phải giữ giao ước của Ta, tức là ngươi và dòng dõi ngươi sau ngươi, các thế hệ ngươi."'),
(408, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 17, 10, 'OT', 'Đây là giao ước mà các ngươi phải giữ, lập giữa ta và các ngươi, cùng dòng dõi sau ngươi: mỗi người nam trong các ngươi phải chịu cắt bì.'),
(409, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 17, 11, 'OT', 'Các ngươi phải chịu cắt bì phần thịt dương vật của các ngươi; ấy sẽ là dấu hiệu của sự giao ước giữa ta và các ngươi.'),
(410, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 17, 12, 'OT', 'Người nam nào trong vòng các ngươi, hoặc sinh tại nhà, hoặc mua bằng tiền từ mọi người ngoại bang không thuộc dòng dõi các ngươi, thì khi được tám ngày tuổi, phải chịu cắt bì qua các thế hệ các ngươi.'),
(411, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 17, 13, 'OT', 'Các ngươi phải làm phép cắt bì cho người sinh tại nhà ngươi và người ngươi mua bằng tiền; và sự giao ước của ta sẽ lập trong thân thể các ngươi làm một giao ước đời đời.'),
(412, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 17, 14, 'OT', 'Người nam nào không chịu cắt bì phần thịt dương vật của mình, thì linh hồn người ấy sẽ bị truất ra khỏi dân sự nó; ấy là kẻ đã vi phạm giao ước ta.'),
(413, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 17, 15, 'OT', 'Đức Chúa Trời phán cùng Aùp-ra-ham rằng: Sa-rai, vợ ngươi, ngươi không được gọi tên nàng là Sa-rai nữa; vì Sa-ra là tên nàng.'),
(414, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 17, 16, 'OT', 'Ta sẽ ban phước cho nàng, và cũng sẽ cho ngươi một con trai bởi nàng; Ta sẽ ban phước cho nàng, nàng sẽ trở thành các dân tộc, các vua của các dân tộc sẽ bởi nàng mà ra.'),
(415, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 17, 17, 'OT', 'Aùp-ra-ham sấp mặt xuống đất, cười, rồi nói trong lòng mình: "Người đã trăm tuổi rồi, mà còn sanh con sao? Còn Sa-ra, vợ tôi, đã chín mươi tuổi, há có thể sanh con được sao?"'),
(416, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 17, 18, 'OT', 'Aùp-ra-ham thưa cùng Đức Chúa Trời: "Ước chi Ích-ma-ên được sống trước mặt Ngài!"'),
(417, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 17, 19, 'OT', 'Đức Chúa Trời phán: Nhưng Sa-ra, vợ ngươi, sẽ sinh cho ngươi một con trai, và ngươi sẽ đặt tên nó là Y-sác. Ta sẽ lập giao ước của Ta với nó làm giao ước đời đời cho dòng dõi nó sau nó.'),
(418, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 17, 20, 'OT', 'Về Ích-ma-ên, Ta đã nhậm lời ngươi; nầy, Ta ban phước cho người, làm cho người sinh sôi nảy nở rất dồi dào, khiến người trở nên cực kỳ đông đảo; mười hai vị lãnh tụ sẽ từ người mà ra, và Ta sẽ làm cho người thành một dân lớn.'),
(419, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 17, 21, 'OT', 'Nhưng Ta sẽ lập giao ước Ta với Y-sác, mà Sa-ra sẽ sinh cho ngươi vào đúng kỳ nầy năm tới.'),
(420, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 17, 22, 'OT', 'Khi Đức Chúa Trời đã phán xong với Aùp-ra-ham, thì Ngài từ bỏ người mà ngự lên.'),
(421, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 17, 23, 'OT', 'Chính ngày đó, Aùp-ra-ham đem Ích-ma-ên, con trai mình, và hết thảy những người nam trong nhà người, hoặc sinh tại nhà, hoặc do tiền mua, đều làm phép cắt bì phần thịt dương vật của họ, y như lời Đức Chúa Trời đã phán cùng người.'),
(422, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 17, 24, 'OT', 'Aùp-ra-ham chín mươi chín tuổi khi người chịu cắt bì phần thịt dương vật mình.'),
(423, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 17, 25, 'OT', 'Và Ích-ma-ên, con trai người, lúc chịu phép cắt bì phần thịt dương vật mình, thì được mười ba tuổi.'),
(424, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 17, 26, 'OT', 'Trong chính ngày ấy, Aùp-ra-ham và Ích-ma-ên, con trai ông, đã chịu phép cắt bì.'),
(425, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 17, 27, 'OT', 'Và mọi người nam trong nhà ông, sinh tại nhà hay mua bằng tiền từ người ngoại bang, đều chịu cắt bì với ông.'),
(426, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 1, 'OT', 'Đức Giê-hô-va hiện ra cùng Aùp-ra-ham nơi các cây dẻ của Mam-rê, và người đang ngồi nơi cửa trại vào lúc nóng trong ngày.'),
(427, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 2, 'OT', 'Aùp-ra-ham ngước mắt lên, thấy ba người đang đứng trước mặt mình. Thấy vậy, ông liền chạy ra đón họ từ lối vào lều, rồi cúi mình xuống đất.'),
(428, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 3, 'OT', 'Thưa rằng: Lạy Đức Giê-hô-va, nếu tôi thật sự được ơn trước mắt Ngài, xin đừng từ chối đi qua khỏi kẻ tôi tớ Ngài.'),
(429, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 4, 'OT', 'Xin hãy lấy ít nước rửa chân các ông, rồi hãy nằm nghỉ dưới gốc cây.'),
(430, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 5, 'OT', 'Tôi sẽ lấy một chút bánh, mời các ngài ăn cho vững lòng, rồi hãy đi tiếp; vì đó là lý do các ngài đã ghé qua nhà tôi tớ của các ngài. Các ngài đáp: Hãy cứ làm như lời ông nói.'),
(431, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 6, 'OT', 'Aùp-ra-ham vội vàng vào trại cùng Sa-ra và nói: "Hãy mau mau lấy ba đấu bột lọc, nhồi và làm những chiếc bánh nhỏ."'),
(432, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 7, 'OT', 'Aùp-ra-ham chạy đến bầy bò, lấy một con bò tơ mập mạp và tốt, rồi trao cho đầy tớ, và người ấy vội vàng chế biến nó.'),
(433, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 8, 'OT', 'Người lấy kem, sữa và con bê đã nấu sẵn, dọn ra trước mặt họ; còn người thì đứng gần họ dưới gốc cây, và họ ăn.'),
(434, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 9, 'OT', 'Các đấng phán cùng Aùp-ra-ham rằng: Sa-ra, vợ ngươi, ở đâu? Aùp-ra-ham thưa: Kìa, nàng ở trong trại.'),
(435, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 10, 'OT', 'Đức Giê-hô-va phán: "Ta sẽ trở lại cùng ngươi trong vòng một năm, đúng vào kỳ hẹn nầy, và Sa-ra, vợ ngươi, sẽ có một con trai." Bấy giờ Sa-ra nghe các lời nầy ở nơi cửa trại, phía sau Ngài.'),
(436, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 11, 'OT', 'Aùp-ra-ham và Sa-ra đã già, tuổi tác đã cao; Sa-ra không còn kinh nguyệt như các người đàn bà nữa.'),
(437, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 12, 'OT', 'Sa-ra cười thầm trong lòng mà rằng: Sau khi tôi đã già, làm sao có thể còn được điều vui ấy? Và ông chủ tôi cũng đã già rồi!'),
(438, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 13, 'OT', 'Đức Giê-hô-va phán cùng Aùp-ra-ham rằng: Vì cớ nào Sa-ra cười, nói rằng: Ta đã già vậy, há thật còn sanh con sao?'),
(439, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 14, 'OT', 'Đức Giê-hô-va há có việc chi khó mà không làm được sao? Đến kỳ đã hẹn, ta sẽ trở lại cùng ngươi vào đúng mùa này, và Sa-ra sẽ có một con trai.'),
(440, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 15, 'OT', 'Sa-ra chối và nói: Tôi không cười đâu, vì bà sợ; nhưng Ngài phán: Không phải vậy, ngươi đã cười thật.'),
(441, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 16, 'OT', 'Các người ấy đứng dậy khỏi nơi đó và nhìn xuống phía Sô-đôm, còn Aùp-ra-ham thì đi cùng họ để tiễn biệt.'),
(442, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 17, 'OT', 'Đức Giê-hô-va phán: Ta há sẽ giấu Aùp-ra-ham điều Ta sắp làm chăng?'),
(443, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 18, 'OT', 'vì Aùp-ra-ham sẽ trở nên một dân lớn và mạnh mẽ, và mọi dân tộc trên đất sẽ được phước bởi người.'),
(444, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 19, 'OT', 'Vì Ta đã biết Aùp-ra-ham, để người dạy các con mình và gia đình mình sau người giữ đường lối của Đức Giê-hô-va, làm điều công bình và chính trực, hầu cho Đức Giê-hô-va thực hiện điều đã phán về Aùp-ra-ham.'),
(445, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 20, 'OT', 'Đức Giê-hô-va phán: "Tiếng kêu về Sô-đôm và Gô-mô-rơ thật quá nhiều, và tội lỗi chúng thật nặng nề lắm."'),
(446, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 21, 'OT', 'Ta sẽ xuống xem xét, có thật như tiếng kêu thấu đến Ta chăng, chúng nó đã làm trọn điều ác hay chưa; nếu không, Ta sẽ biết.'),
(447, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 22, 'OT', 'Bấy giờ những người ấy từ nơi đó đi về hướng Sô-đôm, còn Aùp-ra-ham vẫn còn đứng trước mặt Đức Giê-hô-va.'),
(448, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 23, 'OT', 'Aùp-ra-ham tiến gần lại mà thưa rằng: Đức Giê-hô-va há thật diệt cả người công bình với kẻ ác sao?'),
(449, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 24, 'OT', 'Há Ngài sẽ tiêu diệt nơi nầy sao, mà không tha thứ cho nó vì cớ năm mươi người công bình ở giữa thành?'),
(450, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 25, 'OT', 'Xin đừng để điều đó xảy đến cho Ngài, làm điều này mà giết người công bình cùng với kẻ ác, khiến người công bình bị xử như kẻ ác! Xin đừng để điều đó xảy đến cho Ngài! Đấng xét đoán khắp đất, há chẳng thực hiện sự công bình sao?'),
(451, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 26, 'OT', 'Đức Giê-hô-va phán: Nếu ta tìm được trong Sô-đôm năm mươi người công bình ở giữa thành, ta sẽ vì họ mà khoan dung cho cả nơi ấy.'),
(452, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 27, 'OT', 'Aùp-ra-ham thưa rằng: Xin Chúa để tôi mạnh mật nói cùng Chúa; tôi vốn là bụi tro.'),
(453, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 28, 'OT', 'Biết đâu năm mươi người công bình lại thiếu năm người; Ngài há sẽ tiêu diệt cả thành vì thiếu năm sao? Ngài phán: Nếu Ta tìm được ở đó bốn mươi lăm người, Ta sẽ không tiêu diệt thành.'),
(454, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 29, 'OT', 'Aùp-ra-ham lại tiếp tục nói với Ngài rằng: Có thể trong thành chỉ còn bốn mươi người công bình, thì sao? Ngài phán: Ta sẽ không làm điều đó, vì cớ bốn mươi người ấy.'),
(455, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 30, 'OT', 'Aùp-ra-ham thưa: Xin Đức Giê-hô-va đừng nổi giận, tôi xin nói một điều nữa: há chẳng lẽ trong đó tìm được ba mươi người sao? Ngài phán: Nếu ta tìm được trong đó ba mươi người, ta sẽ không hủy diệt nó.'),
(456, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 31, 'OT', 'Aùp-ra-ham thưa rằng: Xin Chúa hãy để tôi nói một điều cùng Chúa: nếu tại đó chỉ tìm được hai mươi người, vậy Chúa sẽ không tiêu diệt thành sao? Ngài đáp: Vì hai mươi người đó, ta sẽ không tiêu diệt nó.'),
(457, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 32, 'OT', 'Aùp-ra-ham thưa: Xin Đức Giê-hô-va đừng nổi giận, tôi xin thưa chỉ một lần nầy nữa: Ngộ nhỡ trong đó còn có mười người, thì sao? Ngài phán: Ta sẽ chẳng tiêu diệt, vì cớ mười người đó.'),
(458, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 18, 33, 'OT', 'Đức Giê-hô-va đi khỏi khi Ngài phán xong cùng Aùp-ra-ham, còn Aùp-ra-ham trở về chỗ mình.'),
(459, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 1, 'OT', 'Hai thiên sứ đến Sô-đôm vào lúc chiều tối; và Lót đang ngồi tại cửa thành Sô-đôm. Khi thấy họ, Lót liền đứng dậy đón tiếp và sấp mình xuống đất.'),
(460, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 2, 'OT', 'Nầy, xin các ông hãy đến nhà kẻ tôi tớ, và nghỉ đêm tại đó; các ông hãy rửa chân, rồi sáng mai hãy dậy sớm và lên đường. Nhưng các ông nói: Không, chúng ta sẽ nghỉ đêm tại quảng trường.'),
(461, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 3, 'OT', 'Người nài xin họ hết sức, nên họ bèn trở lại cùng người và đi vào nhà người; người dọn cho họ một bữa tiệc, nướng những ổ bánh không men, và họ ăn.'),
(462, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 4, 'OT', 'Chưa khi nào hai người nằm xuống, thì các người nam trong thành, tức dân Sô-đôm, từ trẻ đến già, đều vây quanh nhà ấy.'),
(463, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 5, 'OT', 'Bọn họ gọi Lót và hỏi: Người đàn ông nào đã đến nhà ông đêm nay ở đâu? Hãy dẫn họ ra đây cho chúng tôi, để chúng tôi biết họ.'),
(464, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 6, 'OT', 'Lót bèn đi ra gặp họ ở ngay cửa, rồi đóng cửa lại phía sau mình.'),
(465, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 7, 'OT', 'Người nói: Tôi xin anh em, đừng làm điều xấu xa này!'),
(466, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 8, 'OT', 'Này, tôi có hai đứa con gái chưa biết đến người nam, tôi xin đưa chúng nó ra cho các anh, hãy làm điều tốt nhất theo ý các anh đối với chúng; chỉ xin đừng làm gì đến những người đàn ông này, vì cớ họ đã đến nương dưới bóng mái nhà tôi.'),
(467, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 9, 'OT', 'Họ bảo: "Hãy tránh ra!" Rồi họ nói: "Người này đến trú tạm mà đã tự cho mình có quyền xét xử. Bây giờ chúng ta sẽ đối xử với ngươi tệ hại hơn cả bọn họ." Họ liền xô đẩy người đàn ông, tức là Lót, rất mạnh, và tiến đến để phá cửa.'),
(468, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 10, 'OT', 'Hai người đưa tay ra, kéo Lót vào nhà với mình, rồi đóng cửa lại.'),
(469, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 11, 'OT', 'Họ đánh những người đàn ông đang đứng trước cửa nhà, từ người nhỏ đến người lớn, khiến họ mù mắt, nên họ mệt nhọc mà không tìm được cửa.'),
(470, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 12, 'OT', 'Hai người ấy nói với Lót rằng: Ngươi còn ai nữa ở đây không? Rể, các con trai, các con gái và tất cả những người thuộc về ngươi trong thành, hãy dẫn ra khỏi nơi này!'),
(471, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 13, 'OT', 'Chúng tôi sẽ hủy diệt nơi này, vì tiếng kêu than của chúng đã vang lên trước mặt Đức Giê-hô-va, nên Đức Giê-hô-va sai chúng tôi đến để hủy diệt nó.'),
(472, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 14, 'OT', 'Lót đi ra nói với các chàng rể đã đính hôn với các con gái mình rằng: "Hãy chổi dậy, đi ra khỏi nơi nầy, vì Đức Giê-hô-va sẽ hủy diệt thành nầy." Nhưng các chàng rể nghĩ ông đang nói đùa.'),
(473, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 15, 'OT', 'Khi rạng đông lên, các thiên sứ thúc giục Lót mà nói rằng: "Hãy chỗi dậy, dẫn lấy vợ ngươi và hai con gái ngươi đang có ở đây, e ngươi bị tiêu diệt vì tội ác của thành."'),
(474, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 16, 'OT', 'Nhưng người lần lữa; các người ấy nắm lấy tay người, tay vợ người và tay hai con gái người, vì cớ Đức Giê-hô-va thương xót người, rồi họ dẫn người ra và đặt người ra ngoài thành.'),
(475, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 17, 'OT', 'Khi hai thiên sứ dẫn họ ra ngoài, thì nói: "Hãy chạy trốn cứu lấy mạng mình; chớ ngoái nhìn lại phía sau, và chớ dừng lại đâu giữa đồng bằng; hãy chạy trốn lên núi, e ngươi bị tiêu diệt."'),
(476, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 18, 'OT', 'Lót nói với họ: Xin đừng, thưa chúa!'),
(477, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 19, 'OT', 'Nầy, tôi tớ Ngài đã tìm được ơn trước mặt Ngài, và Ngài đã làm lớn sự nhân từ mà Ngài đã làm cùng tôi, để cứu sống mạng tôi; nhưng tôi không thể chạy trốn đến núi, e tai họa theo kịp tôi, và tôi phải chết.'),
(478, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 20, 'OT', 'Nầy, thành này gần đây, để tôi có thể chạy trốn đến đó; nó nhỏ thôi. Xin hãy để tôi chạy đến đó—không phải nó nhỏ sao?—để mạng sống tôi được cứu.'),
(479, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 21, 'OT', 'Người phán với người ấy: Này, Ta đã đoái đến mặt ngươi, cũng để làm điều nầy, không hủy diệt thành mà ngươi đã nói.'),
(480, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 22, 'OT', 'Hãy nhanh lên, trốn ngay đến nơi ấy, vì ta không thể làm điều gì cho đến khi ngươi đến đó. Bởi vậy, người ta gọi tên thành ấy là Xô-a.'),
(481, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 23, 'OT', 'Mặt trời đã mọc lên trên đất, thì Lót đã vào đến Xô-a.'),
(482, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 24, 'OT', 'Đức Giê-hô-va làm mưa diêm sinh và lửa từ nơi Đức Giê-hô-va từ trên trời xuống trên Sô-đôm và Gô-mô-rơ,'),
(483, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 25, 'OT', 'Đã lật đổ các thành ấy, toàn bộ đồng bằng, mọi cư dân trong các thành và mọi thực vật trên đất.'),
(484, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 26, 'OT', 'Vợ người quay lại đằng sau mình, liền hóa thành một trụ muối.'),
(485, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 27, 'OT', 'Aùp-ra-ham dậy sớm vào buổi sáng, đi đến nơi mà người đã đứng trước mặt Đức Giê-hô-va.'),
(486, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 28, 'OT', 'Ngó về phía Sô-đôm và Gô-mô-rơ, và về khắp mọi phần đất của đồng bằng, thì thấy khói từ đất bay lên như khói của lò lửa.'),
(487, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 29, 'OT', 'Khi Đức Chúa Trời hủy diệt các thành trong đồng bằng, thì nhớ đến Aùp-ra-ham, và sai đưa Lót ra khỏi giữa sự lật đổ, khi các thành ấy bị lật đổ, tức là các thành mà Lót đã sống trong đó.'),
(488, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 30, 'OT', 'Lót từ Xô-a đi lên, đến ở trên núi cùng hai con gái mình, vì người sợ ở Xô-a; người ở trong một cái hang, chính người và hai con gái mình.'),
(489, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 31, 'OT', 'Chị cả nói với em rằng: Cha chúng ta đã già, và không có người nào trên đất đến cùng chúng ta theo như tục lệ mọi nơi trên thế gian.'),
(490, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 32, 'OT', 'Hãy đi, chúng ta sẽ cho cha uống rượu, rồi nằm cùng với người, để nhờ cha mà còn dòng dõi.'),
(491, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 33, 'OT', 'Đêm ấy, hai người con gái làm cha mình uống rượu; người con gái cả đến nằm cùng cha mình, nhưng ông không biết lúc nàng nằm xuống cũng không biết lúc nàng trỗi dậy.'),
(492, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 34, 'OT', 'Sang ngày hôm sau, người chị nói cùng em rằng: Nầy, đêm qua tôi đã nằm cùng cha rồi; hôm nay chúng ta hãy phục rượu cho cha nữa, rồi em hãy vào nằm cùng cha, để chúng ta lưu truyền dòng dõi từ cha chúng ta.'),
(493, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 35, 'OT', 'Đêm ấy, hai người con gái cũng lại làm cho cha mình uống rượu; người em thức dậy, nằm cùng với người cha; nhưng người không biết khi người ấy nằm xuống, cũng không biết khi người ấy chỗi dậy.'),
(494, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 36, 'OT', 'Hai con gái của Lót đã mang thai bởi cha mình.'),
(495, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 37, 'OT', 'Người con gái đầu lòng sinh một con trai, đặt tên là Mô-áp; chính người ấy là tổ phụ của dân Mô-áp cho đến ngày nay.'),
(496, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 19, 38, 'OT', 'Người em cũng sinh một con trai, đặt tên là Bên-Am-mi; người ấy là tổ phụ của con cháu Am-môn cho đến ngày nay.'),
(497, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 20, 1, 'OT', 'Aùp-ra-ham từ đó đi đến miền Nam, rồi tạm trú giữa Ca-đe và Su-rơ, và kiều ngụ tại Ghê-ra.'),
(498, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 20, 2, 'OT', 'Aùp-ra-ham nói về Sa-ra, vợ mình, rằng: "Nàng là em gái tôi." Rồi A-bi-mê-léc, vua Ghê-ra, sai người đến và đem Sa-ra đi.'),
(499, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 20, 3, 'OT', 'Đức Chúa Trời hiện đến cùng A-bi-mê-léc trong cơn chiêm bao ban đêm, và phán với người rằng: "Nầy, ngươi sẽ chết vì người đàn bà mà ngươi đã đem đến; vì nàng là vợ của một người khác."'),
(500, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 20, 4, 'OT', 'Vả lại, A-bi-mê-léc chưa hề đến gần người ấy, nên thưa rằng: Lạy Đức Giê-hô-va, Ngài há sẽ hủy diệt cả một dân tộc ngay chính sao?'),
(501, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 20, 5, 'OT', 'Chẳng phải người ấy đã nói với tôi: "Cô ấy là em gái tôi" sao? Và chính cô ấy cũng nói: "Ông ấy là anh tôi"? Tôi làm điều này với lòng ngay thẳng và tay trong sạch.'),
(502, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 20, 6, 'OT', 'Trong cơn chiêm bao, Đức Chúa Trời phán cùng người rằng: "Chính Ta cũng biết ngươi đã làm điều này vì lòng ngay thẳng của ngươi; chính Ta cũng đã ngăn cản ngươi khỏi phạm tội cùng Ta, nên Ta không để ngươi động đến người ấy."'),
(503, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 20, 7, 'OT', 'Bây giờ, hãy trả người vợ của người đàn ông lại, vì người ấy là một đấng tiên tri, sẽ cầu nguyện cho ngươi, và ngươi sẽ được sống. Nhưng nếu ngươi không trả lại, hãy biết rằng ngươi chắc chắn sẽ chết, ngươi và tất cả những gì thuộc về ngươi.'),
(504, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 20, 8, 'OT', 'A-bi-mê-léc dậy sớm vào buổi sáng, gọi tất cả các tôi tớ mình lại và thuật lại cho họ mọi chuyện ấy; thì những người ấy rất sợ hãi.'),
(505, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 20, 9, 'OT', 'A-bi-mê-léc đòi Aùp-ra-ham mà nói rằng: Ngươi đã làm gì cho chúng ta vậy? Ta có làm điều gì trái với ngươi mà ngươi làm cho ta và nước ta phạm một tội lớn như vậy? Những việc không nên làm, ngươi đã làm cùng ta.'),
(506, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 20, 10, 'OT', 'A-bi-mê-léc nói cùng Aùp-ra-ham: "Ngươi đã thấy điều gì mà làm việc nầy?"'),
(507, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 20, 11, 'OT', 'Aùp-ra-ham nói: Vì tôi nghĩ rằng chắc ở nơi này không có kính sợ Đức Chúa Trời, họ sẽ giết tôi vì cớ vợ tôi.'),
(508, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 20, 12, 'OT', 'Và thật, nàng là em gái tôi, con gái của cha tôi, nhưng không phải con gái của mẹ tôi, và nàng đã trở thành vợ tôi.'),
(509, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 20, 13, 'OT', 'Khi Đức Chúa Trời khiến tôi phải rời khỏi nhà cha mình, thì tôi đã nói với nàng: "Đây là ơn mà ngươi sẽ làm cho ta: Hễ nơi nào chúng ta đến, hãy nói về ta rằng: ''Người ấy là anh tôi.''"'),
(510, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 20, 14, 'OT', 'A-bi-mê-léc lấy chiên, bò, đầy tớ trai và tớ gái, rồi trao cho Aùp-ra-ham, và trả lại Sa-ra, vợ người.'),
(511, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 20, 15, 'OT', 'Nầy, đất nước ta sẵn sàng trước mặt ngươi; hãy ở đâu tùy theo ý tốt của ngươi.'),
(512, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 20, 16, 'OT', 'Còn cùng Sa-ra, người nói: Nầy, ta đã cho anh ngươi một ngàn miếng bạc; nầy, ấy là sự che khuất mắt cho ngươi trước mặt mọi người ở cùng ngươi, và ngươi được minh bạch trước mọi người.'),
(513, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 20, 17, 'OT', 'Aùp-ra-ham cầu nguyện cùng Đức Chúa Trời, và Đức Chúa Trời chữa lành cho A-bi-mê-léc, vợ người và các tì nữ của người, rồi họ sinh con.'),
(514, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 20, 18, 'OT', 'Vì Đức Giê-hô-va đã phong tỏa mọi nơi sinh sản trong nhà của A-bi-mê-léc, vì cớ Sa-ra, vợ Aùp-ra-ham.'),
(515, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 1, 'OT', 'Đức Giê-hô-va viếng Sa-ra như lời Ngài đã phán, và Đức Giê-hô-va làm cho Sa-ra như lời Ngài đã nói.'),
(516, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 2, 'OT', 'Sa-ra thọ thai và sanh cho Aùp-ra-ham một con trai trong khi ông đã già, đúng kỳ Đức Chúa Trời đã phán cùng ông.'),
(517, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 3, 'OT', 'Aùp-ra-ham đặt tên cho con trai mình, đứa con mà Sa-ra đã sanh cho ông, là Y-sác.'),
(518, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 4, 'OT', 'Aùp-ra-ham làm phép cắt bì cho Y-sác con trai mình, khi nó được tám ngày tuổi, y như lời Đức Chúa Trời đã truyền cho ông.'),
(519, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 5, 'OT', 'Aùp-ra-ham một trăm tuổi khi Y-sác, con trai ông, được sinh ra.'),
(520, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 6, 'OT', 'Sa-ra nói: Đức Chúa Trời đã làm cho tôi một nụ cười; hễ ai nghe đến sẽ cười với tôi.'),
(521, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 7, 'OT', 'Rồi bà nói: Ai có thể nói với Aùp-ra-ham rằng Sa-ra sẽ cho các con bú? Vì tôi đã sinh một con trai cho người trong lúc già yếu.'),
(522, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 8, 'OT', 'Đứa trẻ lớn lên và thôi bú; Aùp-ra-ham dọn một bữa tiệc lớn vào ngày Y-sác được thôi bú.'),
(523, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 9, 'OT', 'Sa-ra thấy đứa con trai của A-ga, người Ai-cập, mà A-ga đã sanh cho Aùp-ra-ham, đang cười cợt,'),
(524, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 10, 'OT', 'Bà nói với Aùp-ra-ham: "Hãy đuổi người nữ tớ nữ nầy cùng con trai nó đi, vì con trai của người nữ tớ nữ nầy sẽ không được thừa kế cùng con trai tôi là Y-sác."'),
(525, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 11, 'OT', 'Aùp-ra-ham lấy làm rất buồn lòng vì chuyện ấy, vì cớ con trai mình.'),
(526, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 12, 'OT', 'Đức Chúa Trời phán cùng Aùp-ra-ham: "Đừng để điều đó làm ngươi buồn lòng vì đứa trẻ và vì con đòi ngươi. Tất cả những gì Sa-ra nói với ngươi, hãy nghe theo tiếng người; vì bởi Y-sác, dòng dõi ngươi sẽ được gọi nên danh."'),
(527, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 13, 'OT', 'Ta cũng sẽ khiến cho con trai của người tớ gái trở thành một dân tộc, vì nó cũng là dòng dõi ngươi.'),
(528, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 14, 'OT', 'Sáng sớm, Aùp-ra-ham chỗi dậy, lấy bánh và một bầu nước, đưa cho A-ga, đặt trên vai nàng cùng với đứa trẻ, rồi sai nàng đi; nàng bèn đi và lang thang trong đồng vắng Bê-e-Sê-ba.'),
(529, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 15, 'OT', 'Khi nước trong bị đã hết, thì nàng đặt đứa trẻ dưới một trong những bụi cây.'),
(530, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 16, 'OT', 'Bà đi ra ngồi cách xa đối diện, khoảng một tầm bắn tên, vì bà nói: "Tôi không nỡ nhìn thấy đứa trẻ chết!" Rồi từ chỗ ngồi đối diện đó, bà cất tiếng khóc.'),
(531, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 17, 'OT', 'Đức Chúa Trời đã nghe tiếng đứa trẻ, và thiên sứ của Đức Chúa Trời từ trời gọi A-ga, mà nói rằng: "A-ga, ngươi làm sao vậy? Đừng sợ, vì Đức Chúa Trời đã nghe tiếng đứa trẻ ở ngay chỗ nó đang nằm."'),
(532, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 18, 'OT', 'Hãy đứng dậy, nâng đứa trẻ lên và nắm lấy tay nó, vì Ta sẽ khiến nó trở thành một dân lớn.'),
(533, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 19, 'OT', 'Đức Chúa Trời mở mắt nàng ra, và nàng thấy một cái giếng nước; nàng đi múc đầy bầu nước và cho đứa trẻ uống.'),
(534, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 20, 'OT', 'Đức Chúa Trời ở cùng đứa trẻ, nó lớn lên, ở trong đồng vắng và trở nên thiện nghệ bắn cung.'),
(535, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 21, 'OT', 'Người ở tại đồng vắng Pha-ran, và mẹ người lấy cho người một người vợ từ xứ Ê-díp-tô.'),
(536, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 22, 'OT', 'Vào thời ấy, A-bi-mê-léc và Phi-côn, quan trưởng đạo binh người, nói với Aùp-ra-ham rằng: Đức Chúa Trời ở cùng ông trong mọi điều ông làm.'),
(537, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 23, 'OT', 'Vậy bây giờ, hãy thề với ta tại đây nhân danh Đức Chúa Trời rằng ngươi sẽ không làm điều gian dối cùng ta, cùng con trai ta, và cùng dòng dõi ta; nhưng ngươi sẽ lấy lòng nhân từ mà ta đã làm cùng ngươi mà đối đãi cùng ta và cùng đất mà ngươi đã trú ngụ.'),
(538, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 24, 'OT', 'Aùp-ra-ham đáp: Tôi xin chỉ Đức Giê-hô-va mà thề.'),
(539, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 25, 'OT', 'Aùp-ra-ham trách A-bi-mê-léc về một giếng nước mà các đầy tớ của A-bi-mê-léc đã cướp đoạt.'),
(540, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 26, 'OT', 'A-bi-mê-léc nói: Tôi không biết ai đã làm điều này, chính bạn cũng không nói cho tôi biết, và tôi cũng chẳng nghe điều gì cho đến ngày hôm nay.'),
(541, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 27, 'OT', 'Aùp-ra-ham lấy chiên và bò, trao cho A-bi-mê-léc; rồi hai người lập giao ước với nhau.'),
(542, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 28, 'OT', 'Aùp-ra-ham lựa để riêng ra bảy con chiên cái trong bầy;'),
(543, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 29, 'OT', 'A-bi-mê-léc nói với Áp-ra-ham: Điều này là gì? Bảy con chiên cái mà ngươi đã tách riêng ra đây là sao?'),
(544, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 30, 'OT', 'Aùp-ra-ham nói: "Ngươi phải nhận từ tay ta bảy con chiên, để làm chứng cho ta rằng chính ta đã đào cái giếng nầy."'),
(545, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 31, 'OT', 'Vì vậy, người ta đặt tên cho nơi ấy là Bê-e-Sê-ba, vì tại đó hai người đã thề cùng nhau.'),
(546, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 32, 'OT', 'Vậy, họ lập giao ước tại Bê-e-Sê-ba. Đoạn, A-bi-mê-léc cùng Phi-côn, quan trưởng đạo binh người, đứng dậy trở về đất Phi-li-tin.'),
(547, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 33, 'OT', 'Aùp-ra-ham trồng một cây vả tại Bê-e-Sê-ba, và ở đó người kêu cầu danh Đức Giê-hô-va, là Đức Chúa Trời đời đời.'),
(548, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 21, 34, 'OT', 'Aùp-ra-ham trú ngụ lâu ngày trong xứ Phi-li-tin.'),
(549, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 22, 1, 'OT', 'Sau các việc ấy, Đức Chúa Trời thử Aùp-ra-ham, và phán cùng người rằng: Aùp-ra-ham! Người thưa rằng: Có tôi đây.'),
(550, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 22, 2, 'OT', 'Đức Chúa Trời phán: Hãy lấy con ngươi, con một mà ngươi yêu, là Y-sác, và đi đến xứ Mô-ri-a, ở đó dâng nó làm của lễ thiêu trên một ngọn núi mà Ta sẽ chỉ cho.'),
(551, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 22, 3, 'OT', 'Aùp-ra-ham dậy sớm vào buổi sáng, buộc lừa của ông, đem theo hai đầy tớ và Y-sác, con ông; ông cũng chặt củi dùng về của lễ thiêu, rồi chỗi dậy và đi đến nơi mà Đức Chúa Trời đã chỉ dạy cho ông.'),
(552, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 22, 4, 'OT', 'Đến ngày thứ ba, Aùp-ra-ham ngước mắt lên và thấy nơi ấy ở đằng xa.'),
(553, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 22, 5, 'OT', 'Aùp-ra-ham nói với các đầy tớ rằng: "Các ngươi hãy ở lại đây với con lừa, còn ta và đứa trẻ sẽ đi đến một nơi kia, rồi chúng ta sẽ thờ lạy và trở lại cùng các ngươi."'),
(554, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 22, 6, 'OT', 'Aùp-ra-ham lấy các cây củi về lễ thiêu, chất trên Y-sác, con trai mình; rồi người cầm lửa và con dao trong tay, và cả hai cùng đi chung một chỗ.'),
(555, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 22, 7, 'OT', 'Y-sác nói cùng Aùp-ra-ham, cha mình rằng: "Hỡi cha!" Người đáp: "Này cha đây, hỡi con!" Y-sác nói: "Này lửa và củi đây, nhưng chiên con đâu để làm của lễ thiêu?"'),
(556, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 22, 8, 'OT', 'Aùp-ra-ham nói: Đức Chúa Trời sẽ tự sắm cho Ngài chiên làm của lễ thiêu, hỡi con trai ta; rồi hai người cùng đi.'),
(557, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 22, 9, 'OT', 'Họ đến nơi Đức Chúa Trời đã phán bảo; tại đó, Aùp-ra-ham xây bàn thờ, chất củi lên, trói Y-sác con trai mình lại, rồi đặt nó trên bàn thờ, phía trên các củi.'),
(558, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 22, 10, 'OT', 'Aùp-ra-ham giơ tay ra, lấy con dao để giết con mình.'),
(559, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 22, 11, 'OT', 'Thiên sứ của Đức Giê-hô-va kêu người từ trên trời và nói: "Aùp-ra-ham! Aùp-ra-ham!" Người thưa: "Có tôi đây."'),
(560, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 22, 12, 'OT', 'Đức Chúa Trời phán: "Đừng tra tay vào đứa trẻ và đừng làm gì nó; vì bây giờ Ta biết rằng ngươi kính sợ Đức Chúa Trời, và đã không giữ lại con trai ngươi, con một ngươi, khỏi Ta."'),
(561, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 22, 13, 'OT', 'Aùp-ra-ham ngước mắt lên, thấy sau mình một con chiên đực, sừng vướng trong bụi rậm; Aùp-ra-ham đi lấy con chiên đực ấy, dâng nó làm của lễ thiêu thay cho con trai mình.'),
(562, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 22, 14, 'OT', 'Aùp-ra-ham gọi tên nơi đó là Đức Giê-hô-va Di-rê, nên ngày nay người ta nói: Trên núi của Đức Giê-hô-va sẽ được thấy.'),
(563, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 22, 15, 'OT', 'Thiên sứ của Đức Giê-hô-va kêu Aùp-ra-ham lần thứ hai từ trời, mà rằng:'),
(564, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 22, 16, 'OT', 'Đức Giê-hô-va phán: "Nhân danh chính mình ta mà ta đã thề, vì ngươi đã làm điều nầy và không giữ lại con ngươi, tức con một ngươi.'),
(565, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 22, 17, 'OT', 'Sẽ ban phước cho ngươi và làm cho dòng dõi ngươi đông vô số như các ngôi sao trên trời và như cát nơi bờ biển; và dòng dõi ngươi sẽ chiếm được cửa thành của quân nghịch.'),
(566, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 22, 18, 'OT', 'Vì ngươi đã vâng theo tiếng ta, nên mọi dân tộc trên đất sẽ nhờ dòng dõi ngươi mà được hưởng ơn phước.'),
(567, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 22, 19, 'OT', 'Aùp-ra-ham trở về cùng các đầy tớ của mình, rồi cùng nhau đứng dậy và đi về Bê-e-Sê-ba. Aùp-ra-ham ở lại tại Bê-e-Sê-ba.'),
(568, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 22, 20, 'OT', 'Sau các việc ấy, người ta báo cho Aùp-ra-ham rằng: Nầy, nàng Minh-ca cũng đã sinh con cho Na-cô, anh ngươi.'),
(569, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 22, 21, 'OT', 'Con trưởng nam là Uùt-xơ, và Bu-xơ em trai người, và Kê-mu-ên, cha của A-ram;'),
(570, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 22, 22, 'OT', 'Kê-sết, Ha-xô, Phin-đát, Díp-láp và Bê-tu-ên;'),
(571, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 22, 23, 'OT', 'Bê-tu-ên sanh Rê-be-ca. Tám người con này là con của Minh-ca, sanh cho Na-cô, em của Aùp-ra-ham.'),
(572, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 22, 24, 'OT', 'Còn người hầu của người, tên là Rê-u-ma, cũng sinh ra Tê-la, Ga-ham, Ta-hách và Ma-a-ca.'),
(573, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 23, 1, 'OT', 'Sa-ra sống được một trăm năm, hai mươi năm, và bảy năm; ấy là tuổi thọ của Sa-ra.'),
(574, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 23, 2, 'OT', 'Sa-ra qua đời tại Ki-ri-át-A-ra-ba, tức là Hếp-rôn, thuộc xứ Ca-na-an. Aùp-ra-ham đến để khóc than cho Sa-ra và chịu tang người.'),
(575, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 23, 3, 'OT', 'Aùp-ra-ham đứng dậy khỏi trước mặt người chết mình, và nói cùng các con trai của Hê-th rằng:'),
(576, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 23, 4, 'OT', 'Ta là một khách lạ và người tạm trú giữa các ngươi; xin hãy cho ta một chỗ chôn xác người chết của ta giữa các ngươi.'),
(577, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 23, 5, 'OT', 'Con cái Hê-th thưa với Áp-ra-ham rằng:'),
(578, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 23, 6, 'OT', 'Lạy ngài, xin hãy nghe chúng tôi: chính ngài là một lãnh tụ của Đức Chúa Trời giữa chúng tôi; xin hãy chôn người chết của ngài trong những phần mộ tốt nhất của chúng tôi. Không một người nào trong chúng tôi sẽ từ chối nhường mộ phần của mình để ngài chôn người chết của ngài.'),
(579, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 23, 7, 'OT', 'Aùp-ra-ham đứng dậy, cúi mình xuống trước mặt dân xứ, tức con cái của dân Hê-th.'),
(580, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 23, 8, 'OT', 'mà nói rằng: Nếu các ngươi bằng lòng cho chôn người chết của ta, thì hãy nghe ta, và cầu xin Eùp-rôn, con của Xô-ha, giúp ta,'),
(581, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 23, 9, 'OT', 'Xin hãy nhượng cho tôi hang đá Mặc-bê-la, là hang thuộc về ông, nằm ở cuối thửa đất của ông; ông hãy bán cho tôi cái hang ấy với giá đầy đủ, để tôi có được một nơi phần mộ giữa các ông.'),
(582, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 23, 10, 'OT', 'Vả lại, Eùp-rôn đang ngồi giữa những con trai của Hê-tít, thì Eùp-rôn người Hê-tít đáp lại cùng Aùp-ra-ham, trước mặt những con trai của Hê-tít và trước mặt mọi người đến nơi cửa thành của người ấy, mà rằng:'),
(583, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 23, 11, 'OT', 'Thưa ngài, xin hãy nghe tôi: tôi xin tặng ngài mảnh đất này, và cái hang ở trong đất ấy, tôi cũng đã tặng ngài rồi, trước mặt các con trai dân tôi, để ngài chôn người chết của ngài.'),
(584, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 23, 12, 'OT', 'Aùp-ra-ham sấp mình xuống trước mặt dân của đất nước,'),
(585, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 23, 13, 'OT', 'ta nói cùng Eùp-rôn trước mặt dân xứ rằng: Xin hãy nghe ta, tôi xin trả tiền mảnh đất, ông hãy nhận lấy, để tôi chôn người chết tôi tại đó.'),
(586, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 23, 14, 'OT', 'Eùp-rôn đáp cùng Áp-ra-ham rằng:'),
(587, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 23, 15, 'OT', 'Thưa ngài, xin hãy nghe tôi: bốn trăm siếc-lơ bạc là giá đất, giữa tôi và ngài có là bao, xin cứ chôn người chết của ngài đi.'),
(588, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 23, 16, 'OT', 'Aùp-ra-ham nghe theo lời Eùp-rôn, và Aùp-ra-ham cân cho Eùp-rôn bốn trăm siếc-lơ bạc, là bạc thông dụng nơi các tay buôn bán, đúng như số tiền mà Eùp-rôn đã nói trước mặt các con trai của Hết.'),
(589, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 23, 17, 'OT', 'Đồng ruộng của Eùp-rôn tại Mặc-bê-la, đối diện Mam-rê, tức là đồng ruộng, hang đá ở trong đó, và mọi cây cối ở trong đồng ruộng ấy, cùng khắp ranh giới chung quanh nó, đều được xác lập.'),
(590, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 23, 18, 'OT', 'trước mặt các con trai của Hê-th, cho Aùp-ra-ham làm sở hữu, để làm phần mộ, trước mặt mọi người vào ra nơi cửa thành của họ.'),
(591, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 23, 19, 'OT', 'Sau đó, Aùp-ra-ham chôn Sa-ra, vợ mình, trong hang đá tại đồng đất Mặc-bê-la, đối diện với Nam-rê, là Hếp-rôn, trong xứ Ca-na-an.'),
(592, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 23, 20, 'OT', 'Đồng ruộng và cái hang trong đó đều được các con trai của Hê-th nhượng lại cho Aùp-ra-ham làm chỗ chôn xác.'),
(593, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 1, 'OT', 'Aùp-ra-ham đã về già, tuổi tác đã cao, và Đức Giê-hô-va ban phước cho Aùp-ra-ham trong mọi việc.'),
(594, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 2, 'OT', 'Aùp-ra-ham nói cùng người đầy tớ già nhất trong nhà mình, người quản trị mọi vật sở hữu của ông, rằng: Hãy đặt tay ngươi dưới đùi ta,'),
(595, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 3, 'OT', 'Hãy để tôi khiến ngươi thề bằng Đức Giê-hô-va, Đức Chúa Trời của các từng trời và Đức Chúa Trời của đất, rằng ngươi sẽ không cưới một người vợ nào từ các con gái của người Ca-na-an, mà ta đang sống giữa họ, cho con trai ta.'),
(596, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 4, 'OT', 'Hãy đi về đất ta, về nơi dòng họ ta, và cưới một người vợ cho Y-sác, con trai ta.'),
(597, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 5, 'OT', 'Người đầy tớ thưa người rằng: Nếu như người đàn bà không chịu theo tôi về xứ nầy, vậy tôi có phải dẫn con trai ông trở về xứ mà ông đã ra đi khỏi chăng?'),
(598, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 6, 'OT', 'Aùp-ra-ham nói với người ấy: Hãy coi chừng, đừng dẫn con trai ta trở về nơi đó!'),
(599, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 7, 'OT', 'Đức Giê-hô-va Đức Chúa Trời trên trời, là Đấng đã dẫn tôi ra khỏi nhà cha tôi và khỏi đất sinh trưởng tôi, và đã phán cùng tôi, và thề cùng tôi rằng: Cho dòng dõi ngươi đất nầy; chính Ngài sẽ sai thiên sứ Ngài đi trước mặt ngươi, để ngươi lấy một người vợ cho con trai ta ở đó.'),
(600, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 8, 'OT', 'Nếu người phụ nữ không chịu đi theo ngươi, thì ngươi sẽ được miễn khỏi lời thề này của ta; chỉ ngươi chớ đem con ta trở về nơi đó.'),
(601, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 9, 'OT', 'Người đầy tớ đặt tay mình dưới đùi Aùp-ra-ham, chủ mình, và thề với người về điều đó.'),
(602, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 10, 'OT', 'Vậy người đầy tớ lấy mười con lạc đà từ bầy lạc đà của chủ mình, và mọi thứ tốt lành của chủ mình đều ở trong tay người; rồi người đứng dậy, đi đến xứ Mê-sô-bô-ta-mi, đến thành của Na-cô.'),
(603, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 11, 'OT', 'Người cho các lạc đà uống nước bên ngoài thành, gần một cái giếng nước, vào buổi chiều, lúc những thiếu nữ ra đi lấy nước.'),
(604, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 12, 'OT', 'Người nói: Đức Giê-hô-va, Đức Chúa Trời của chủ tôi Aùp-ra-ham, xin hãy làm ơn cho chủ tôi Aùp-ra-ham ngày nay, và xin giúp tôi gặp điều thuận lợi trước mặt Ngài.'),
(605, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 13, 'OT', 'Nầy, tôi đang đứng bên giếng nước, và các con gái của người trong thành sẽ ra để lấy nước,'),
(606, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 14, 'OT', 'Vậy thì cô gái trẻ mà tôi nói: "Xin hãy nghiêng bầu nước của cô xuống để tôi uống," và cô ấy đáp: "Xin mời uống, và tôi cũng sẽ cho lạc đà của ông uống nữa," chính cô ấy là người mà Đức Giê-hô-va đã chỉ định cho Y-sác, kẻ tôi tớ Ngài; và nhờ điều đó tôi sẽ biết rằng Ngài đã làm ơn thương xót cho chủ tôi.'),
(607, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 15, 'OT', 'Người đầy tớ chưa dứt lời, nầy, nàng Rê-be-ca đi ra, là con gái của Bê-tu-ên, con trai của Minh-ca, vợ Na-cô, em trai của Aùp-ra-ham, và bình của nàng đặt trên vai.'),
(608, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 16, 'OT', 'Cô gái trẻ ấy rất xinh đẹp, còn trinh tiết, chưa ai từng biết đến nàng. Nàng xuống bể, múc đầy bình và đi lên.'),
(609, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 17, 'OT', 'Người đầy tớ chạy đến đón nàng và nói: Xin hãy cho tôi uống một ít nước trong bình của nàng.'),
(610, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 18, 'OT', 'Bà nói: Xin mời ông uống. Rồi bà vội vàng hạ bình xuống tay bà và cho ông uống.'),
(611, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 19, 'OT', 'Sau khi người uống xong, cô gái nói: Tôi cũng sẽ múc nước cho các lạc đà của ông uống cho đến khi nào chúng uống đủ.'),
(612, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 20, 'OT', 'Nàng vội vàng đổ bình nước xuống máng, chạy xuống giếng múc thêm nước, và múc nước cho tất cả các lạc đà uống.'),
(613, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 21, 'OT', 'Người ấy nín lặng mà nhìn nàng, đợi xem Đức Giê-hô-va có làm cho con đường của mình thành công hay không.'),
(614, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 22, 'OT', 'Khi các lạc đà uống xong, người ấy lấy một cái vòng vàng nặng nửa siếc-lơ, và hai cái vòng đeo tay nặng mười siếc-lơ.'),
(615, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 23, 'OT', 'Nàng là con ai? Xin hãy nói cho tôi biết. Trong nhà cha nàng có chỗ nào cho chúng tôi nghỉ đêm không?'),
(616, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 24, 'OT', 'Nàng nói với người ấy: "Tôi là con gái của Bê-tu-ên, con trai của Minh-ca, người mà nàng đã sinh cho Na-cô."'),
(617, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 25, 'OT', 'Cũng rơm, cũng cỏ khô, và nhiều lắm nơi chúng tôi; cũng có chỗ để nghỉ đêm.'),
(618, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 26, 'OT', 'Người ấy cúi đầu xuống và thờ lạy Đức Giê-hô-va.'),
(619, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 27, 'OT', 'Đáng ngợi khen thay Đức Giê-hô-va, là Đức Chúa Trời của chủ tôi Aùp-ra-ham, Đấng không từ bỏ ân sủng và sự thật của Ngài đối với chủ tôi. Chính tôi, khi đang đi trên đường, Đức Giê-hô-va đã dẫn tôi đến nhà anh em của chủ tôi.'),
(620, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 28, 'OT', 'Cô gái liền chạy về, thuật lại những điều ấy cho gia đình mẹ mình.'),
(621, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 29, 'OT', 'Rê-be-ca có một người anh, tên là La-ban. La-ban chạy đến người ấy ở ngoài gần bên giếng.'),
(622, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 30, 'OT', 'Khi thấy cái vòng và các vòng xuyến nơi tay em gái mình, và khi nghe lời Rê-be-ca, em gái mình, nói rằng: "Người ấy nói với tôi như vậy," thì người ấy đi đến gặp người đàn ông, và nầy, người ấy đang đứng gần các con lạc đà ở bên giếng nước.'),
(623, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 31, 'OT', 'Bởi vậy người nói: Hãy vào, hỡi người được Đức Giê-hô-va ban phước, sao đứng ngoài trời như vậy? Nầy, tôi đã sửa soạn nhà rồi, và chỗ cho các lạc đà cũng đã sẵn.'),
(624, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 32, 'OT', 'Người ấy vào nhà; La-ban cởi yên cho các lạc đà, rồi trải rơm và thóc cho lạc đà ăn, và lấy nước rửa chân mình cùng chân các người đi với ông.'),
(625, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 33, 'OT', 'Người ta dọn đồ ăn trước mặt ông, nhưng ông nói: "Tôi sẽ không ăn cho đến khi tôi nói xong điều tôi phải nói." La-ban đáp: "Hãy nói đi!"'),
(626, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 34, 'OT', 'Người nói: Tôi là đầy tớ của Aùp-ra-ham.'),
(627, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 35, 'OT', 'Đức Giê-hô-va đã ban phước cho chủ tôi cách rất dồi dào, khiến ông trở nên giàu có, và ban cho ông chiên, bò, bạc, vàng, đầy tớ trai, tớ gái, lạc đà và lừa.'),
(628, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 36, 'OT', 'Sa-ra, vợ của chủ tôi, đã sinh cho chủ tôi một con trai sau khi bà đã già, và chủ tôi đã trao cho con trai ấy mọi thứ mình có.'),
(629, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 37, 'OT', 'Chúa tôi đã khiến tôi thề rằng: Ngươi chớ cưới vợ cho con trai ta trong các con gái của dân Ca-na-an, là nơi ta đang cư ngụ;'),
(630, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 38, 'OT', 'Nhưng ngươi phải đi về nhà cha ta, đến họ hàng ta, mà cưới vợ cho con trai ta tại đó.'),
(631, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 39, 'OT', 'Tôi nói với chủ tôi: "Biết đâu người phụ nữ sẽ không theo tôi đi theo."'),
(632, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 40, 'OT', 'Người nói với tôi: "Đức Giê-hô-va, Đấng tôi đã đi trước mặt Ngài, sẽ sai thiên sứ Ngài cùng đi với ngươi và làm cho con đường ngươi được thành công; và ngươi sẽ lấy một người vợ cho con trai ta từ gia đình ta và từ nhà cha ta."'),
(633, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 41, 'OT', 'Vậy ngươi sẽ được giải thoát khỏi lời nguyền của ta, nếu ngươi đi đến họ hàng ta mà họ không chịu gả cho ngươi; và ngươi sẽ vô tội khỏi lời nguyền của ta.'),
(634, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 42, 'OT', 'Ngày nay, tôi đi đến nơi giếng nước và thưa rằng: Đức Giê-hô-va Đức Chúa Trời của chủ Aùp-ra-ham tôi, xin hãy làm cho con đường tôi đi được thuận lợi, tức là con đường tôi đang đi đây.'),
(635, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 43, 'OT', 'Nầy, tôi đang đứng bên cạnh giếng nước; và cô gái trẻ nào ra đây múc nước, tôi sẽ nói cùng nàng: Xin hãy cho tôi uống một ít nước trong bình của nàng;'),
(636, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 44, 'OT', 'nếu cô ấy nói với tôi: "Cả ông nữa, hãy uống đi, và tôi cũng sẽ xách nước cho các lạc đà của ông uống," thì đó chính là người phụ nữ mà Đức Giê-hô-va đã chỉ định cho con trai của chủ tôi.'),
(637, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 45, 'OT', 'Tôi chưa kịp nói xong trong lòng mình, thì nầy, Rê-be-ca đi ra, với cái bình trên vai; nàng xuống giếng múc nước, và tôi nói với nàng: Xin hãy cho tôi uống chút nước.'),
(638, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 46, 'OT', 'Nàng vội vàng hạ bình mình xuống khỏi vai và nói: "Xin mời uống, tôi cũng sẽ cho các lạc đà của ngài uống nữa." Vậy tôi đã uống, và nàng cũng cho các lạc đà uống nữa.'),
(639, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 47, 'OT', 'Tôi bèn hỏi nàng rằng: "Nàng là con gái ai?" Nàng đáp: "Tôi là con gái của Bê-tu-ên, con trai của Na-cô, mà Na-cô sinh ra bởi Minh-ca." Tôi liền đặt vòng mũi vào lỗ mũi nàng và vòng đeo tay vào tay nàng.'),
(640, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 48, 'OT', 'Tôi cúi đầu và sấp mình xuống trước mặt Đức Giê-hô-va, rồi tôi chúc tụng Đức Giê-hô-va, Đức Chúa Trời của chủ tôi Aùp-ra-ham, là Đấng đã dẫn tôi trong con đường ngay thẳng để đem con gái của anh em chủ tôi về cho con trai người.'),
(641, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 49, 'OT', 'Bây giờ, nếu các ông muốn làm ơn và giữ lòng trung tín đối với chủ tôi, thì hãy nói cho tôi biết; nếu không, cũng hãy nói cho tôi biết, để tôi có thể rẽ sang bên phải hoặc bên trái.'),
(642, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 50, 'OT', 'La-ban và Bê-tu-ên đáp và nói: Việc nầy là từ Đức Giê-hô-va mà ra; chúng tôi không thể nói với ngươi điều ác hay điều lành.'),
(643, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 51, 'OT', 'Này, Rê-be-ca đang ở trước mặt ngươi, hãy nhận lấy và đi đi, để nàng trở thành vợ cho con trai của chủ ngươi, như Đức Giê-hô-va đã phán.'),
(644, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 52, 'OT', 'Khi đầy tớ của Aùp-ra-ham nghe các lời ấy của họ, thì người ấy sấp mình xuống đất trước mặt Đức Giê-hô-va.'),
(645, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 53, 'OT', 'Người đầy tớ lấy ra các đồ bằng bạc, các đồ bằng vàng và các áo xống, rồi trao cho Rê-be-ca; và người cũng trao các lễ vật cho anh của nàng và cho mẹ nàng.'),
(646, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 54, 'OT', 'Họ ăn uống, người ấy cùng những người đi với ông; rồi họ ngủ tại đó. Sáng hôm sau, khi họ thức dậy, ông nói: Hãy để tôi đi về cùng chủ tôi.'),
(647, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 55, 'OT', 'Anh cô gái và mẹ cô nói: Hãy để cô gái ở lại với chúng tôi vài ngày, hoặc khoảng mười ngày, rồi cô ấy mới đi.'),
(648, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 56, 'OT', 'Đừng níu tôi lại, vì Đức Giê-hô-va đã làm cho hành trình tôi đi được thành công; hãy để tôi đi đến chủ tôi.'),
(649, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 57, 'OT', 'Họ nói: Hãy gọi người gái trẻ, và chúng ta sẽ hỏi ý kiến của cô ấy.'),
(650, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 58, 'OT', 'Mọi người gọi Rê-be-ca và nói với nàng: "Con có muốn đi với người đàn ông này không?" Nàng đáp: "Tôi sẽ đi."'),
(651, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 59, 'OT', 'Họ cho Rê-be-ca, em gái mình, và người vú của nàng, cùng với đầy tớ của Aùp-ra-ham và các người của ông đi.'),
(652, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 60, 'OT', 'Họ chúc phước cho Rê-be-ca và nói với nàng: "Hỡi chị em chúng ta, nàng hãy trở nên mẹ của hàng ngàn vạn người, và dòng dõi nàng sẽ chiếm lấy cửa thành của những kẻ thù nghịch nàng."'),
(653, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 61, 'OT', 'Rê-be-ca cùng các nữ tì của nàng đứng dậy, lên cỡi những con lạc đà và đi theo người đàn ông ấy. Người đầy tớ dẫn Rê-be-ca đi.'),
(654, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 62, 'OT', 'Y-sác từ giếng La-chai-Roi trở về, đang lúc người đang ngồi trong xứ Nam Phương.'),
(655, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 63, 'OT', 'Y-sác đi ra ngoài đồng để suy gẫm lúc chiều tối; người ngước mắt lên và thấy các lạc đà đang đi tới.'),
(656, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 64, 'OT', 'Rê-be-ca ngước mắt lên, thấy Y-sác, liền từ xuống khỏi lạc đà.'),
(657, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 65, 'OT', 'Nàng hỏi đầy tớ rằng: "Người đàn ông ấy là ai, đang đi trên đồng ra gặp chúng ta đây?" Đầy tớ đáp: "Chính là chủ tôi." Nàng liền lấy tấm khăn voan che mặt lại.'),
(658, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 66, 'OT', 'Người đầy tớ thuật lại cho Y-sác nghe tất cả các việc mà ông đã làm.'),
(659, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 24, 67, 'OT', 'Y-sác dẫn Rê-be-ca vào trướng của Sa-ra, mẹ mình, rồi tiếp nhận Rê-be-ca làm vợ; và người yêu thương nàng. Vậy, Y-sác được an ủi sau khi mẹ mình qua đời.'),
(660, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 1, 'OT', 'Aùp-ra-ham lại cưới một người vợ, tên là Kê-tu-ra.'),
(661, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 2, 'OT', 'Aùp-ra-ham sanh cho Xim-ram, Giốc-chan, Mê-đan, Ma-đi-an, Dích-bác và Su-ách.'),
(662, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 3, 'OT', 'Giốc-chan sinh ra Sê-ba và Đê-đan; con cái của Đê-đan là A-chu-rim, Lê-tu-chim và Lê-um-mim.'),
(663, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 4, 'OT', 'Các con trai của Ma-đi-an là Ê-pha, Ê-phe, Ha-nóc, A-bi-đa và Eân-đa. Tất cả những người này đều là con cháu của Kê-tu-ra.'),
(664, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 5, 'OT', 'Aùp-ra-ham cho Y-sác hết thảy những gì mình có;'),
(665, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 6, 'OT', 'Còn các con trai của các người thứ mà Áp-ra-ham có, thì Áp-ra-ham cho của cải, rồi sai họ đi về phía đông, cách xa Y-sác, con trai người, khi người còn sống.'),
(666, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 7, 'OT', 'Aùp-ra-ham sống một trăm bảy mươi lăm năm.'),
(667, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 8, 'OT', 'Áp-ra-ham qua đời trong tuổi già, đầy đủ ngày tháng, đã hưởng thọ; người tắt hơi và được về cùng tổ tiên mình.'),
(668, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 9, 'OT', 'Y-sác và Ích-ma-ên, hai con trai người, chôn người trong hang đá Mặc-bê-la, tại nơi đồng của Eùp-rôn, con trai Sô-ha, người Hê-tít, nằm đối diện Mam-rê.'),
(669, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 10, 'OT', 'Cánh đồng mà Aùp-ra-ham đã mua từ con cái Hê-th; ở đó Aùp-ra-ham và Sa-ra, vợ người, được chôn.'),
(670, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 11, 'OT', 'Sau khi Aùp-ra-ham qua đời, Đức Chúa Trời ban phước cho Y-sác con trai người. Y-sác ở gần bên giếng La-chai-Roi.'),
(671, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 12, 'OT', 'Đây là dòng dõi của Ích-ma-ên, con trai của Aùp-ra-ham, mà A-ga, người Ai Cập, tớ gái của Sa-ra, đã sinh cho Aùp-ra-ham.'),
(672, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 13, 'OT', 'Và đây là các tên các con trai của Ích-ma-ên, theo thứ tự sinh của họ: con trai cả của Ích-ma-ên là Nê-ba-giốt, rồi đến Kê-đa, Aùt-bê-ên, và Mi-bô-sam.'),
(673, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 14, 'OT', 'Mích-ma, Đu-ma và Ma-sa.'),
(674, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 15, 'OT', 'Ha-đa, Thê-ma, Giê-thu, Na-phích và Kết-ma.'),
(675, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 16, 'OT', 'Đây là các con trai của Ích-ma-ên, và đây là tên của họ theo các làng và các trại của chúng; mười hai người lãnh tụ theo các dân tộc của chúng.'),
(676, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 17, 'OT', 'Nầy là tuổi thọ của Ích-ma-ên: một trăm ba mươi bảy năm; rồi người tắt hơi và qua đời, và được nhóm lại cùng dân người.'),
(677, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 18, 'OT', 'Dòng dõi người ở từ Ha-vi-la cho đến Xu-xơ, đối ngang trước mặt Ê-díp-tô, khi đi vào A-si-ri; người nằm trước mặt tất cả anh em mình.'),
(678, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 19, 'OT', 'Đây là dòng dõi của Y-sác, con trai Aùp-ra-ham; Aùp-ra-ham sanh Y-sác.'),
(679, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 20, 'OT', 'Khi Y-sác bốn mươi tuổi thì cưới Rê-be-ca, con gái Bê-tu-ên, người A-ram ở Pha-đan-A-ram, và là em gái của La-ban người A-ram, làm vợ mình.'),
(680, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 21, 'OT', 'Y-sác cầu xin Đức Giê-hô-va cho Rê-be-ca, vợ mình, vì nàng son sẻ; và Đức Giê-hô-va nhậm lời người, nên Rê-be-ca, vợ người, thọ thai.'),
(681, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 22, 'OT', 'Các con trẻ đụng nhau trong lòng nàng, thì nàng nói: Nếu vậy, tại sao tôi lại thế này? Rồi nàng đi cầu hỏi Đức Giê-hô-va.'),
(682, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 23, 'OT', 'Đức Giê-hô-va phán với nàng: "Hai dân tộc đang ở trong bụng ngươi, và hai dân tộc sẽ từ ngươi mà ra; dân này sẽ mạnh hơn dân kia, và người lớn sẽ phục người nhỏ."'),
(683, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 24, 'OT', 'Đến kỳ sinh nở, thì thấy có hai con trong bụng nàng.'),
(684, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 25, 'OT', 'Đứa ra trước có màu đỏ, toàn thân như cái áo choàng bằng lông; người ta đặt tên nó là Ê-sau.'),
(685, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 26, 'OT', 'Và sau đó, em trai ra, tay nắm lấy gót của Ê-sau; và người ta đặt tên nó là Gia-cốp. Y-sác lúc sinh hai đứa trẻ ấy được sáu mươi tuổi.'),
(686, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 27, 'OT', 'Lớn lên rồi, các chàng trai ấy trở nên khác nhau: Ê-sau là một người thợ săn tinh khôn, là người của đồng ruộng; còn Gia-cốp là một người hiền lành, sống trong lều.'),
(687, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 28, 'OT', 'Y-sác yêu Ê-sau vì người hay săn bắn cho người ăn; còn Rê-be-ca thì yêu Gia-cốp.'),
(688, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 29, 'OT', 'Gia-cốp nấu một món canh, thì Ê-sau từ ngoài đồng trở về, và người mệt lả.'),
(689, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 30, 'OT', 'Ê-sau nói cùng Gia-cốp: "Hãy cho tôi ăn chút gì từ món đỏ đỏ này, vì tôi mệt lử rồi." Bởi vậy, người ta đặt tên cho người là Ê-đôm.'),
(690, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 31, 'OT', 'Gia-cốp nói: Hãy bán hôm nay quyền trưởng nam của anh cho tôi.'),
(691, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 32, 'OT', 'Ê-sau nói: Nầy, tôi sắp chết, quyền trưởng nam ấy có ích lợi gì cho tôi?'),
(692, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 33, 'OT', 'Gia-cốp nói: Ngày nay anh hãy chỉ Đức Giê-hô-va mà thề cho tôi. Người bèn chỉ Đức Giê-hô-va mà thề cho người; vậy, người bán quyền trưởng nam của mình cho Gia-cốp.'),
(693, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 25, 34, 'OT', 'Gia-cốp đưa cho Ê-sau bánh và cháo đậu đỏ; Ê-sau ăn, uống, rồi đứng dậy đi; và Ê-sau khinh thường quyền trưởng nam.'),
(694, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 1, 'OT', 'Xứ lại có cơn đói kém, ngoài cơn đói kém đầu tiên đã xảy ra trong đời Aùp-ra-ham; Y-sác bèn đi đến A-bi-mê-léc, vua Phi-li-tin, tại Ghê-ra.'),
(695, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 2, 'OT', 'Đức Giê-hô-va hiện ra cùng người và phán: "Đừng xuống xứ Ai Cập; hãy ở lại trong xứ mà Ta sẽ chỉ cho ngươi."'),
(696, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 3, 'OT', 'Hãy ngụ tại đất nầy; ta sẽ ở cùng ngươi và ban phước cho ngươi; vì ngươi và dòng dõi ngươi, ta sẽ ban cho tất cả các xứ nầy, và ta sẽ làm vững chắc lời thề mà ta đã thề cùng Aùp-ra-ham, cha ngươi.'),
(697, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 4, 'OT', 'Ta sẽ làm cho dòng dõi ngươi đông vô số như các ngôi sao trên trời, và sẽ ban cho dòng dõi ngươi tất cả các xứ nầy, và mọi dân trên đất sẽ nhờ dòng dõi ngươi mà được hưởng ơn phước.'),
(698, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 5, 'OT', 'vì Aùp-ra-ham đã vâng theo tiếng ta, và đã giữ gìn các điều răn, các mạng lịnh, các luật lệ và các chỉ thị của ta.'),
(699, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 6, 'OT', 'Vậy Y-sác ở tại Ghê-ra.'),
(700, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 7, 'OT', 'Khi những người trong xứ hỏi về vợ mình, thì người nói: "Cô ấy là em gái tôi," vì người sợ nói "Cô ấy là vợ tôi," e rằng người của xứ sẽ giết người vì Rê-be-ca, bởi nàng có sắc đẹp.'),
(701, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 8, 'OT', 'Khi người đã ngụ tại đó khá lâu, A-bi-mê-léc, vua Phi-li-tin, nhìn qua cửa sổ, thấy Y-sác đang đùa giỡn cùng Rê-be-ca, vợ người.'),
(702, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 9, 'OT', 'A-bi-mê-léc gọi Y-sác và nói: "Quả thật, nàng là vợ ngươi; sao ngươi lại nói: ''Nàng là em gái ta''?" Y-sác đáp người: "Vì tôi nghĩ: ''Đừng để tôi chết vì nàng.''"'),
(703, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 10, 'OT', 'A-bi-mê-léc nói: Ngươi làm chi cho chúng ta vậy? Kẻ hầu một người trong dân đến nằm cùng vợ ngươi, thì ngươi đã gây tội lỗi cho chúng ta rồi!'),
(704, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 11, 'OT', 'A-bi-mê-léc truyền lệnh cho toàn dân rằng: "Kẻ nào đụng đến người đàn ông nầy và vợ người ấy, sẽ phải chết."'),
(705, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 12, 'OT', 'Y-sác gieo trồng trong xứ đó, và năm ấy ông tìm được một trăm bội phần; Đức Giê-hô-va ban phước cho ông.'),
(706, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 13, 'OT', 'Người ấy trở nên giàu có, và cứ tiếp tục phát triển mãi cho đến khi trở nên cực kỳ giàu có.'),
(707, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 14, 'OT', 'Người có bầy chiên và bầy bò rất đông, cùng nhiều tôi tớ; nên dân Phi-li-tin ganh ghét người.'),
(708, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 15, 'OT', 'Tất cả các giếng mà đầy tớ của Aùp-ra-ham, cha người, đã đào trong đời Aùp-ra-ham, thì dân Phi-li-tin đều lấp đầy bằng bụi đất.'),
(709, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 16, 'OT', 'A-bi-mê-léc nói cùng Y-sác rằng: Hãy đi khỏi chúng ta, vì ngươi đã trở nên mạnh hơn chúng ta rất nhiều.'),
(710, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 17, 'OT', 'Vậy, Y-sác rời khỏi nơi ấy, đi đến đóng trại tại khe Ghê-ra và ở lại đó.'),
(711, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 18, 'OT', 'Y-sác bèn trở lại đào lại các giếng nước mà Aùp-ra-ham, cha người, đã đào thời xưa, và dân Phi-li-tin đã lấp chúng lại sau khi Aùp-ra-ham qua đời; người đặt tên cho các giếng đó theo các tên mà cha người đã đặt.'),
(712, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 19, 'OT', 'Các đầy tớ của Y-sác đào giếng trong trũng, và tìm được ở đó một giếng nước sống.'),
(713, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 20, 'OT', 'Các đầy tớ chăn chiên của Ghê-ra tranh giành với các đầy tớ chăn chiên của Y-sác, nói rằng: "Nước này là của chúng ta." Vậy nên Y-sác đặt tên giếng đó là Ê-xéc, vì chúng tranh giành với ông.'),
(714, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 21, 'OT', 'Các đầy tớ của người đào một cái giếng khác, thì người ta cũng tranh giành với người về cái giếng ấy nữa; người đặt tên giếng đó là Sít-na.'),
(715, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 22, 'OT', 'Người rời khỏi nơi đó và đào một cái giếng khác, và họ không tranh cãi về nó; nên Người đặt tên cho nó là Rê-hô-bốt, mà rằng: "Bây giờ Đức Giê-hô-va đã rộng rãi cho chúng ta, và chúng ta sẽ sinh sôi nảy nở trong đất."'),
(716, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 23, 'OT', 'Y-sác từ đó lên Bê-e-Sê-ba.'),
(717, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 24, 'OT', 'Đức Giê-hô-va hiện đến cùng người trong đêm đó và phán: Ta là Đức Chúa Trời của Aùp-ra-ham, cha ngươi; chớ sợ, vì Ta ở cùng ngươi, và Ta sẽ ban phước cho ngươi, làm cho dòng dõi ngươi thêm nhiều, vì cớ Aùp-ra-ham là tôi tớ Ta.'),
(718, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 25, 'OT', 'Y-sác xây một bàn thờ tại đó, cầu khẩn danh Đức Giê-hô-va, dựng trại tại đó, và các tôi tớ của Y-sác đào một cái giếng tại đó.'),
(719, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 26, 'OT', 'A-bi-mê-léc đi từ Ghê-ra đến cùng Y-sác, có A-hu-sát bạn người và Phi-côn quan trưởng đạo binh người đi theo.'),
(720, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 27, 'OT', 'Y-sác nói với họ: "Sao các người đến cùng tôi, trong khi các người ghét tôi và đã đuổi tôi ra khỏi các người?"'),
(721, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 28, 'OT', 'Chúng tôi nói: Quả thật, chúng tôi đã thấy rõ Đức Giê-hô-va ở cùng anh; nên chúng tôi nói: Hãy lập một lời thề giữa chúng tôi với anh, giữa chúng tôi và anh, để chúng tôi lập giao ước với anh.'),
(722, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 29, 'OT', 'Nếu các ông định làm điều ác cho chúng tôi, thì xin hãy thề rằng, như chúng tôi đã không đụng đến ông, và chỉ làm điều tốt cho ông, rồi cho ông đi bình an, thì bây giờ ông được Đức Giê-hô-va ban phước.'),
(723, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 30, 'OT', 'Y-sác bày cho họ một bữa tiệc, họ ăn và uống.'),
(724, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 31, 'OT', 'Sáng hôm sau, họ chỗi dậy sớm, mỗi người thề hứa với anh em mình; rồi Y-sác tiễn họ đi, và họ đi khỏi người cách bình an.'),
(725, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 32, 'OT', 'Ngày hôm đó, các đầy tớ của Y-sác đến thưa với người về các giếng mà họ đã đào, và nói với người: Chúng tôi đã tìm thấy nước.'),
(726, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 33, 'OT', 'Người đặt tên cho nó là Si-ba; vì vậy tên thành ấy là Bê-e-Sê-ba cho đến ngày nay.'),
(727, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 34, 'OT', 'Khi Ê-sau được bốn mươi tuổi thì lấy vợ là Giu-đít, con gái của Bê-ê-ri, người Hê-tít, và Bách-mát, con gái của Ê-lôn, người Hê-tít.'),
(728, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 26, 35, 'OT', 'Hai nàng dâu ấy trở nên nỗi buồn rầu trong lòng cho Y-sác và Rê-be-ca.'),
(729, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 1, 'OT', 'Y-sác đã già, mắt mờ không còn thấy rõ, bèn gọi Ê-sau, con trai cả của mình, và nói: Hỡi con! Ê-sau thưa: Có con đây.'),
(730, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 2, 'OT', 'Người nói: Nầy, ta đã già rồi, chẳng biết ngày nào sẽ chết;'),
(731, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 3, 'OT', 'Bây giờ, hãy mang theo túi đựng đồ và cây cung con, ra đồng bắt một con mồi cho cha.'),
(732, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 4, 'OT', 'Hãy làm cho ta những món ăn ngon như ta vẫn yêu thích, rồi đem đến cho ta, để ta ăn, hầu linh hồn ta chúc phước cho con trước khi ta chết.'),
(733, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 5, 'OT', 'Rê-be-ca nghe thấy khi Y-sác nói với Ê-sau con trai mình, và Ê-sau đi ra đồng để săn bắt vật săn đem về.'),
(734, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 6, 'OT', 'Rê-be-ca nói cùng Gia-cốp, con trai mình, rằng: Nầy, tôi có nghe cha con nói cùng Ê-sau, anh con, rằng:'),
(735, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 7, 'OT', 'Hãy đem cho ta thịt săn được, và làm cho ta món ngon để ta ăn, hầu ta có thể chúc phước cho con trước mặt Đức Giê-hô-va trước khi ta chết.'),
(736, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 8, 'OT', 'Vậy bây giờ, hỡi con trai ta, hãy nghe theo tiếng nói của ta, theo điều ta đang biểu con.'),
(737, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 9, 'OT', 'Hãy đi đến bầy chiên, bắt cho mẹ hai dê con tốt lành, rồi mẹ sẽ làm thành món ngon theo đúng sở thích của cha con;'),
(738, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 10, 'OT', 'Hãy mang đến cho cha ngươi, người sẽ ăn, để trước khi chết người chúc phước cho con.'),
(739, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 11, 'OT', 'Gia-cốp nói cùng Rê-be-ca, mẹ người rằng: Nầy, Ê-sau, anh con, là người có lông, còn con lại là người trơn.'),
(740, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 12, 'OT', 'Má sợ cha mình sẽ rờ mình ra, rồi mình bị coi là kẻ lừa dối trước mặt người, và mình sẽ mang lấy sự rủa sả, chứ không phải sự chúc phước.'),
(741, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 13, 'OT', 'Mẹ người đáp: Hỡi con trai ta, sự rủa sả ấy hãy để cho mẹ chịu; hãy nghe theo tiếng mẹ và đi lấy cho mẹ'),
(742, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 14, 'OT', 'Gia-cốp đi, bắt hai con dê con, đem đến cho mẹ; và mẹ người làm những món ngon theo như cha người ưa thích.'),
(743, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 15, 'OT', 'Rê-be-ca lấy những áo tốt nhất của Ê-sau, con trai cả của bà, đang để sẵn trong nhà, mà mặc vào cho Gia-cốp, con trai út của bà.'),
(744, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 16, 'OT', 'Người lấy da dê con bao quanh hai tay và phần cổ của Gia-cốp.'),
(745, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 17, 'OT', 'Rê-be-ca đặt món ăn ngon và cái bánh mà bà đã làm vào tay của Gia-cốp, con trai bà.'),
(746, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 18, 'OT', 'Gia-cốp đi đến cùng cha mình và nói: Thưa cha! Y-sác đáp: Ta đây, con là ai, hỡi con trai ta?'),
(747, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 19, 'OT', 'Gia-cốp thưa cùng cha mình rằng: "Chính con đây, Ê-sau, trưởng nam của cha; con đã làm như lời cha dặn con. Xin cha hãy chỗi dậy, ngồi ăn thịt săn của con, để linh hồn cha chúc phước cho con."'),
(748, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 20, 'OT', 'Y-sác nói với con trai mình: "Sao con vội vàng tìm được vậy, hỡi con trai ta?" Người đáp: "Vì Đức Giê-hô-va Đức Chúa Trời của cha đã khiến con gặp được mau vậy."'),
(749, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 21, 'OT', 'Y-sác nói cùng Gia-cốp: "Hỡi con, hãy lại gần đây, để cha rờ thử con, hỡi con của cha, phải chăng con đây là Ê-sau, con trai cha?"'),
(750, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 22, 'OT', 'Gia-cốp bèn đến gần Y-sác cha mình, người rờ và nói: "Tiếng nói thì là tiếng của Gia-cốp, còn hai tay lại là tay của Ê-sau."'),
(751, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 23, 'OT', 'Người không nhận biết, vì hai tay người ấy lông lá như hai tay Ê-sau, anh người ấy; vậy Y-sác chúc phước cho người.'),
(752, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 24, 'OT', 'Người nói: Con đây phải là Ê-sau, con trai ta chăng? Gia-cốp đáp: Phải, con đây.'),
(753, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 25, 'OT', 'Y-sác nói: "Hãy dọn cho ta, để ta ăn thịt săn của con trai ta, hầu cho linh hồn ta ban phước cho con." Gia-cốp liền dọn cho người, và người ăn; rồi Gia-cốp đem rượu đến, và người uống.'),
(754, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 26, 'OT', 'Bấy giờ Y-sác, cha người, nói rằng: Hỡi con, hãy lại gần đây và hôn cha.'),
(755, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 27, 'OT', 'Gia-cốp lại gần và hôn người; Y-sác đánh hơi mùi thơm của áo xống người, bèn chúc phước cho người và nói: "Nầy, mùi thơm của con ta như mùi thơm cánh đồng mà Đức Giê-hô-va đã ban phước cho."'),
(756, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 28, 'OT', 'Đức Chúa Trời sẽ ban cho con sương từ các tầng trời và sự màu mỡ của đất, cùng nhiều lúa mì và rượu nho.'),
(757, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 29, 'OT', 'Các dân sẽ phục ngươi, các nước sẽ quì lạy ngươi. Hãy làm chủ các anh em ngươi, các con trai của mẹ ngươi sẽ quì lạy ngươi. Kẻ nào rủa ngươi sẽ bị rủa, kẻ nào chúc phước ngươi sẽ được phước.'),
(758, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 30, 'OT', 'Khi Y-sác vừa chúc phước cho Gia-cốp xong, và chính lúc ấy Gia-cốp mới ra đi khỏi trước mặt Y-sác, cha mình, thì nầy, Ê-sau, anh người, đến từ cuộc săn của người.'),
(759, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 31, 'OT', 'Người cũng làm những món ngon, đem dâng cho cha mình, và nói với cha mình rằng: "Xin cha hãy chỗi dậy, ăn thịt săn của con trai cha, hầu cho linh hồn cha ban phước cho con."'),
(760, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 32, 'OT', 'Y-sác, cha người, nói: Con là ai? Người đáp: Tôi là con của cha, con trưởng nam của cha, Ê-sau.'),
(761, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 33, 'OT', 'Y-sác run rẩy dữ dội và nói: Vậy ai là người đã đi săn và mang thức ăn đến cho ta, khiến ta ăn hết mọi thứ trước khi con về, rồi ta đã chúc phước cho người đó? Người ấy thật sự sẽ được ban phước.'),
(762, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 34, 'OT', 'Khi Ê-sau nghe những lời của cha mình, thì kêu lên một tiếng kêu lớn và đắng cay vô cùng, rồi nói với cha mình rằng: "Cha ơi, xin hãy chúc phước cho con nữa!"'),
(763, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 35, 'OT', 'Y-sác nói: Anh con đã đến cùng sự dối trá và đã nhận lấy phước lành của con.'),
(764, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 36, 'OT', 'Ê-sau nói: "Hắn đã hai lần lừa tôi: lấy mất quyền trưởng nam của tôi, và bây giờ lại lấy mất sự chúc phước của tôi." Rồi nói tiếp: "Cha há chẳng có dành sự chúc phước nào cho tôi sao?"'),
(765, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 37, 'OT', 'Y-sác đáp và nói với Ê-sau: Nầy, ta đã đặt nó làm chủ ngươi; ta đã ban tất cả các anh em ngươi làm tôi cho nó; ta đã cấp cho nó lúa mì và rượu; vậy ta sẽ làm gì cho ngươi đây, hỡi con trai ta?'),
(766, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 38, 'OT', 'Ê-sau nói với cha mình: "Cha chỉ có một lời chúc phước sao, hỡi cha? Xin hãy chúc phước cho con nữa, hỡi cha!" Rồi Ê-sau cất tiếng khóc lên.'),
(767, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 39, 'OT', 'Y-sác cha người đáp và nói với người rằng: Nầy, nơi con ở sẽ đầy mỡ đất, và đầy sương trời từ trên cao.'),
(768, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 40, 'OT', 'Ngươi sẽ sống nhờ gươm của mình, và phải phục vụ anh ngươi. Nhưng khi ngươi nổi loạn, thì sẽ bẻ ách nó ra khỏi cổ ngươi.'),
(769, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 41, 'OT', 'Ê-sau ghét Gia-cốp về việc cha đã chúc phước cho ông; và Ê-sau nói trong lòng mình: "Ngày để tang cho cha ta sẽ gần đến; rồi ta sẽ giết Gia-cốp, anh ta."'),
(770, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 42, 'OT', 'Họ thuật lại cho Rê-be-ca những lời của Ê-sau, con trai lớn của bà; bà liền sai người gọi Gia-cốp, con trai út mình, và nói với người rằng: Nầy, Ê-sau, anh con, đang toan giết con để báo thù.'),
(771, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 43, 'OT', 'Vậy bây giờ, hỡi con, hãy nghe theo tiếng của ta; đứng dậy, trốn đi đến La-ban, anh ta của ta tại Cha-ran.'),
(772, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 44, 'OT', 'hãy ở cùng người một vài ngày, cho đến khi cơn thịnh nộ của anh ngươi qua đi.'),
(773, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 45, 'OT', 'Cho đến khi cơn thịnh nộ của anh con nguôi đi và nó quên điều con đã làm cho nó, rồi ta sẽ sai người đi đón con về; tại sao ta phải chịu cảnh mất cả hai con trong một ngày?'),
(774, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 27, 46, 'OT', 'Rê-be-ca nói cùng Y-sác: Tôi chán sống rồi vì các con gái người Hê-th; nếu Gia-cốp lấy vợ từ các con gái người Hê-th như những người con gái xứ này, thì tôi sống còn ích gì?'),
(775, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 28, 1, 'OT', 'Y-sác gọi Gia-cốp, chúc phước cho người và dặn rằng: "Ngươi chớ lấy vợ từ các con gái Ca-na-an."'),
(776, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 28, 2, 'OT', 'Hãy đứng dậy, đi đến Pha-đan-A-ram, đến nhà Bê-tu-ên, cha của mẹ ngươi, và cưới một người vợ cho mình ở đó, từ các con gái của La-ban, anh trai của mẹ ngươi.'),
(777, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 28, 3, 'OT', 'Đức Chúa Trời toàn năng ban phước cho con, làm con sinh sản thêm nhiều, gia tăng con, và khiến con trở nên một hội chúng của các dân tộc.'),
(778, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 28, 4, 'OT', 'Và ban cho con phước lành của Aùp-ra-ham, cho con và dòng dõi con, để con nhận lấy đất con đang cư ngụ, tức đất mà Đức Chúa Trời đã ban cho Aùp-ra-ham.'),
(779, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 28, 5, 'OT', 'Y-sác sai Gia-cốp đi qua xứ Pha-đan-A-ram, đến cùng La-ban, con trai Bê-tu-ên, người A-ram, anh của Rê-be-ca, mẹ của Gia-cốp và Ê-sau.'),
(780, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 28, 6, 'OT', 'Ê-sau thấy Y-sác đã chúc phước cho Gia-cốp và sai người đi Pha-đan-A-ram để cưới vợ ở đó cho mình; và khi chúc phước cho người, người dặn rằng: Đừng cưới vợ trong các con gái Ca-na-an;'),
(781, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 28, 7, 'OT', 'Gia-cốp vâng lời cha và mẹ mình, rồi đi đến Pha-đan-A-ram.'),
(782, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 28, 8, 'OT', 'Ê-sau thấy các con gái Ca-na-an không đẹp lòng Y-sác, cha người;'),
(783, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 28, 9, 'OT', 'Ê-sau đi đến cùng Ích-ma-ên, lấy thêm Ma-ha-lát, con gái của Ích-ma-ên, con trai Aùp-ra-ham, em gái của Nê-ba-giốt, làm vợ ngoài hai người vợ đã có.'),
(784, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 28, 10, 'OT', 'Gia-cốp từ Bê-e-Sê-ba đi ra, đi về hướng Cha-ran,'),
(785, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 28, 11, 'OT', 'Người đến một nơi, thì ở lại đó qua đêm, vì mặt trời đã lặn; người lấy những hòn đá ở nơi ấy, đặt dưới đầu mình, rồi nằm ngủ tại nơi ấy.'),
(786, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 28, 12, 'OT', 'Một giấc mơ hiện đến với người, và này, một chiếc thang dựng dưới đất, đầu thang chạm đến trời; và này, các thiên sứ của Đức Chúa Trời đang lên và xuống trên đó.'),
(787, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 28, 13, 'OT', 'Nầy, Đức Giê-hô-va đứng trên đầu người ấy mà phán rằng: Ta là Đức Giê-hô-va Đức Chúa Trời của Aùp-ra-ham, cha ngươi, và là Đức Chúa Trời của Y-sác. Đất mà ngươi đang nằm ngủ đây, Ta sẽ cho ngươi và dòng dõi ngươi.'),
(788, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 28, 14, 'OT', 'Dòng dõi ngươi sẽ đông như bụi trên mặt đất; ngươi sẽ mở rộng về phía tây, đông, bắc và nam; và mọi chi tộc trên đất sẽ nhờ ngươi mà được phước và nhờ dòng dõi ngươi.'),
(789, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 28, 15, 'OT', 'Nầy, chính Ta ở cùng ngươi, sẽ gìn giữ ngươi khắp nơi ngươi đi, và sẽ đem ngươi trở lại đất nầy; vì Ta sẽ không lìa ngươi cho đến khi Ta làm trọn điều Ta đã phán cùng ngươi.'),
(790, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 28, 16, 'OT', 'Gia-cốp thức dậy khỏi giấc ngủ, nói rằng: Thật vậy, Đức Giê-hô-va hiện diện tại nơi này, mà tôi không biết!'),
(791, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 28, 17, 'OT', 'Người sợ hãi và nói: Chỗ nầy đáng sợ thay! Đâu phải nơi nầy là gì khác ngoài nhà của Đức Chúa Trời, và đây là cửa của trời!'),
(792, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 28, 18, 'OT', 'Sáng hôm ấy, Gia-cốp dậy sớm, lấy hòn đá mình đã đặt làm gối, dựng làm trụ đá, và đổ dầu trên đỉnh nó.'),
(793, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 28, 19, 'OT', 'và đặt tên chỗ ấy là Bê-tên; nhưng tên thành trước kia là Lu-xơ.'),
(794, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 28, 20, 'OT', 'Gia-cốp khấn hứa rằng: Nếu Đức Chúa Trời ở cùng tôi, gìn giữ tôi trong con đường mà tôi đang đi, và cho tôi bánh để ăn, áo để mặc,'),
(795, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 28, 21, 'OT', 'Và tôi sẽ trở về bình an đến nhà cha tôi, thì Đức Giê-hô-va sẽ là Đức Chúa Trời tôi.'),
(796, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 28, 22, 'OT', 'Hòn đá nầy, mà tôi đã dựng làm trụ, sẽ là nhà Đức Chúa Trời; và mọi điều gì mà Đức Giê-hô-va sẽ cho tôi, tôi sẽ dâng một phần mười cho Ngài.'),
(797, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 1, 'OT', 'Gia-cốp nhấc chân mình lên và đi đến đất của con cái phương Đông.'),
(798, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 2, 'OT', 'Người nhìn thấy kìa, một cái giếng ở trong đồng ruộng, và nầy, ở đó có ba bầy chiên đang nằm nghỉ trên nó; vì từ cái giếng ấy, người ta cho các bầy chiên uống nước; và hòn đá lớn nằm trên miệng giếng.'),
(799, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 3, 'OT', 'Các bầy chiên đều hiệp lại đó, rồi họ lăn hòn đá khỏi miệng giếng, cho các bầy chiên uống nước; sau đó, họ đặt hòn đá trở lại chỗ cũ, đậy trên miệng giếng.'),
(800, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 4, 'OT', 'Gia-cốp nói với họ: "Hỡi anh em, các anh từ đâu đến?" Họ đáp: "Chúng tôi từ Cha-ran đến."'),
(801, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 5, 'OT', 'Người hỏi họ: Các anh có biết La-ban, con trai Na-cô, chăng? Họ đáp: Chúng tôi biết.'),
(802, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 6, 'OT', 'Người hỏi họ: "Có bình an chăng?" Họ đáp: "Bình an," và nầy, Ra-chên, con gái người, đang đi đến cùng bầy chiên.'),
(803, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 7, 'OT', 'Người nói: Này, ngày còn chưa tắt, chưa phải là giờ thu lượm bầy chiên; hãy cho chiên uống nước, rồi đi chăn rải ra.'),
(804, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 8, 'OT', 'Họ đáp: Chúng tôi không thể làm được, cho đến khi tất cả các bầy chiên tụ họp đầy đủ, rồi người ta sẽ lăn tảng đá khỏi miệng giếng để chúng tôi cho chiên uống nước.'),
(805, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 9, 'OT', 'Đang khi người còn nói chuyện với họ, thì Ra-chên dẫn bầy chiên của cha mình đến, vì nàng là người chăn chiên.'),
(806, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 10, 'OT', 'Khi Gia-cốp thấy Ra-chên, con gái La-ban, anh trai của mẹ mình, và các bầy chiên của La-ban, anh trai của mẹ mình, thì Gia-cốp liền đi đến, lăn hòn đá khỏi miệng giếng và cho các bầy chiên của La-ban, anh trai của mẹ mình, uống nước.'),
(807, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 11, 'OT', 'Gia-cốp hôn Ra-chên, rồi cất tiếng lên khóc.'),
(808, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 12, 'OT', 'Gia-cốp nói cho Ra-chên biết mình là anh em của cha nàng và là con trai của Rê-be-ca; rồi nàng chạy đi báo cho cha mình biết.'),
(809, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 13, 'OT', 'Khi La-ban nghe tin về Gia-cốp, con trai em gái mình, thì chạy ra đón, ôm hôn người và dẫn vào nhà mình. Rồi Gia-cốp thuật lại cho La-ban nghe mọi việc ấy.'),
(810, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 14, 'OT', 'La-ban nói với người rằng: "Thật vậy, cháu là xương thịt của ta." Rồi Gia-cốp ở cùng người một tháng.'),
(811, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 15, 'OT', 'La-ban nói với Gia-cốp: "Cháu là anh em ruột thịt của ta, thế mà lại phục dịch ta không công sao? Hãy cho ta biết tiền công của cháu là bao nhiêu."'),
(812, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 16, 'OT', 'La-ban có hai con gái; tên người con lớn là Lê-a, và tên người con nhỏ là Ra-chên.'),
(813, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 17, 'OT', 'Mắt Lê-a yếu, còn Ra-chên thì có sắc đẹp hình thể và dung mạo xinh đẹp.'),
(814, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 18, 'OT', 'Gia-cốp yêu Ra-chên, và nói: "Tôi sẽ phục vụ cậu bảy năm vì Ra-chên, con gái út của cậu."'),
(815, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 19, 'OT', 'La-ban nói: Thà ta gả nàng cho ngươi hơn là gả cho người khác; hãy ở lại với ta.'),
(816, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 20, 'OT', 'Gia-cốp phục vụ vì Ra-chên bảy năm, và những năm ấy đối với người như chỉ là vài ngày, vì người yêu nàng.'),
(817, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 21, 'OT', 'Gia-cốp nói với La-ban: "Xin hãy giao vợ tôi lại, vì hạn của tôi đã mãn rồi, để tôi được đến cùng nàng."'),
(818, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 22, 'OT', 'La-ban bèn nhóm tất cả những người trong vùng lại và làm một bữa tiệc.'),
(819, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 23, 'OT', 'Đến chiều tối, ông ta lấy Lê-a, con gái mình, đem đến cho Gia-cốp, và Gia-cốp vào cùng nàng.'),
(820, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 24, 'OT', 'La-ban đưa Xinh-ba, người tớ gái của mình, cho Lê-a, con gái mình, làm tớ gái.'),
(821, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 25, 'OT', 'Sáng hôm sau, thấy đó là Lê-a, Gia-cốp nói với La-ban: "Điều này ông đã làm cho tôi là gì vậy? Chẳng phải tôi đã phục vụ ông vì Ra-chên sao? Vậy mà ông lại lừa dối tôi?"'),
(822, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 26, 'OT', 'La-ban đáp: "Ở đây, người ta không làm như thế: không gả người em trước khi gả người chị cả."'),
(823, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 27, 'OT', 'Hãy làm trọn tuần lễ này, rồi ta sẽ gả cả đứa kia cho ngươi; ngươi phải phục vụ ta thêm bảy năm nữa.'),
(824, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 28, 'OT', 'Gia-cốp làm như vậy, và làm trọn tuần lễ ấy, thì La-ban gả Ra-chên, con gái mình, cho người làm vợ.'),
(825, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 29, 'OT', 'Laban cho Ra-chên, con gái mình, Bi-la, tớ gái của người, làm tớ gái cho nàng.'),
(826, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 30, 'OT', 'Gia-cốp cũng đến cùng Ra-chên, và yêu Ra-chên hơn Lê-a; người phục vụ La-ban thêm bảy năm nữa.'),
(827, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 31, 'OT', 'Đức Giê-hô-va thấy Lê-a bị ghét, bèn mở dạ con của nàng; còn Ra-chên thì son sẻ.'),
(828, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 32, 'OT', 'Lê-a thọ thai, sanh một con trai, đặt tên nó là Ru-bên, vì bà nói: "Đức Giê-hô-va đã thấy sự khốn khổ của tôi; thật vậy, bây giờ chồng tôi sẽ yêu tôi."'),
(829, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 33, 'OT', 'Bà thọ thai nữa và sinh một con trai, rồi nói: "Đức Giê-hô-va đã nghe biết tôi bị ghét, nên cũng ban cho tôi con trai này." Bà đặt tên con trai là Si-mê-ôn.'),
(830, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 34, 'OT', 'Bà lại thọ thai và sinh một con trai; bà nói: "Lần này chồng tôi sẽ gắn bó với tôi, vì tôi đã sinh cho ông ấy ba người con trai." Bởi vậy, bà đặt tên con là Lê-vi.'),
(831, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 29, 35, 'OT', 'Bà thọ thai nữa, sanh một con trai, và nói: "Lần này tôi cảm tạ Đức Giê-hô-va"; vì cớ ấy, bà đặt tên con trai là Giu-đa; rồi bà thôi sinh con.'),
(832, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 1, 'OT', 'Ra-chên thấy mình không sinh con cho Gia-cốp, liền ghen tức với chị mình, và nói cùng Gia-cốp rằng: "Hãy cho tôi có con, nếu không thì tôi sẽ chết."'),
(833, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 2, 'OT', 'Gia-cốp nổi giận cùng Ra-chên, rồi nói: "Tôi há có thể thay thế Đức Giê-hô-va, Đấng đã ngăn cản bạn khỏi sinh sản sao?"'),
(834, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 3, 'OT', 'Ra-chên nói: Này, con đòi Bi-la của tôi, hãy đến cùng nó, để nó sinh đẻ trên đầu gối tôi, và tôi cũng sẽ được xây dựng từ nó.'),
(835, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 4, 'OT', 'Ra-chên đưa Bi-la, người hầu của mình, cho Gia-cốp làm vợ, và Gia-cốp đi vào cùng nàng.'),
(836, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 5, 'OT', 'Bi-la thọ thai, sanh một con trai cho Gia-cốp.'),
(837, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 6, 'OT', 'Ra-chên nói: Đức Chúa Trời đã xét xử tôi, và cũng nghe theo tiếng kêu của tôi, rồi ban cho tôi một con trai; vì vậy, nàng đặt tên nó là Đan.'),
(838, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 7, 'OT', 'Bi-la, con đòi của Ra-chên, thọ thai nữa và sanh cho Gia-cốp một con trai thứ hai.'),
(839, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 8, 'OT', 'Ra-chên nói: Những cuộc tranh đấu của Đức Chúa Trời tôi đã tranh đấu với chị tôi, và tôi đã chiến thắng; rồi bà đặt tên đứa trẻ là Nép-ta-li.'),
(840, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 9, 'OT', 'Lê-a thấy mình thôi sanh sản, bèn lấy Xinh-ba, tớ gái mình, đem cho Gia-cốp làm vợ.'),
(841, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 10, 'OT', 'Xinh-ba, con đòi của Lê-a, sanh một con trai cho Gia-cốp.'),
(842, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 11, 'OT', 'Lê-a nói: "Phước hạnh đến rồi!" và đặt tên con trai mình là Gát.'),
(843, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 12, 'OT', 'Xinh-ba, con đòi của Lê-a, sanh cho Gia-cốp một con trai thứ hai;'),
(844, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 13, 'OT', 'Lê-a nói: "Tôi thật có phước, vì các thiếu nữ sẽ xưng tôi là có phước," và bà đặt tên con trai mình là A-se.'),
(845, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 14, 'OT', 'Vào những ngày mùa gặt lúa mì, Ru-bên đi ra đồng và tìm được những trái phong già, liền đem về dâng cho Lê-a, mẹ mình. Ra-chên nói với Lê-a: "Xin chị hãy cho tôi một ít những trái phong già của con trai chị."'),
(846, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 15, 'OT', 'Ra-chên nói với nàng: "Chị đã lấy mất chồng tôi còn chưa đủ sao, mà chị lại còn muốn lấy cả trái phong già của con trai chị nữa?" Ra-chên nói: "Vì vậy, đêm nay chồng tôi sẽ nằm với chị, để đổi lấy trái phong già của con chị."'),
(847, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 16, 'OT', 'Đến chiều, Gia-cốp từ ngoài đồng trở về, thì Lê-a đi ra đón người và nói: "Người hãy vào cùng tôi, vì tôi đã thuê người bằng trái phong già của con tôi." Vậy, đêm đó người nằm cùng nàng.'),
(848, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 17, 'OT', 'Đức Chúa Trời nhậm lời Lê-a; nàng thọ thai và sanh cho Gia-cốp một con trai thứ năm.'),
(849, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 18, 'OT', 'Lê-a nói: Đức Chúa Trời đã ban cho tôi phần thưởng của tôi, vì tôi đã trao nữ tì tôi cho chồng tôi; và bà đặt tên đứa con trai là Y-sa-ca.'),
(850, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 19, 'OT', 'Lê-a lại thọ thai và sanh cho Gia-cốp một con trai, con trai thứ sáu của người.'),
(851, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 20, 'OT', 'Lê-a nói: Đức Chúa Trời đã ban cho tôi phần thưởng tốt; lần này chồng tôi sẽ ở với tôi, vì tôi đã sinh cho ông ấy sáu con trai. Vậy bà đặt tên đứa con ấy là Sa-bu-lôn.'),
(852, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 21, 'OT', 'Sau đó, nàng sinh một con gái, và đặt tên là Đi-na.'),
(853, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 22, 'OT', 'Đức Chúa Trời nhớ đến Ra-chên, nhậm lời nàng và mở tử cung nàng.'),
(854, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 23, 'OT', 'Bà thọ thai, sinh một con trai, rồi nói: Đức Chúa Trời đã xoá bỏ sự sỉ nhục của tôi.'),
(855, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 24, 'OT', 'bèn đặt tên nó là Giô-sép, mà nói rằng: Đức Giê-hô-va sẽ thêm cho tôi một người con trai khác.'),
(856, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 25, 'OT', 'Khi Ra-chên sanh Giô-sép, thì Gia-cốp nói cùng La-ban rằng: Xin hãy để tôi đi, đặng trở về chỗ tôi, và về đất tôi.'),
(857, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 26, 'OT', 'Xin hãy giao các vợ tôi và các con tôi mà tôi đã phục vụ ông vì họ, để tôi đi; vì ông biết rõ công việc mà tôi đã phục vụ ông.'),
(858, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 27, 'OT', 'La-ban nói với người ấy: Nếu ta thật sự được ơn trước mặt ngươi, thì ta đã nhận thấy rõ Đức Giê-hô-va đã ban phước cho ta vì cớ ngươi.'),
(859, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 28, 'OT', 'Hãy chỉ định phần thưởng của con, rồi ta sẽ trả cho con.'),
(860, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 29, 'OT', 'Gia-cốp nói với người ấy: "Chính cậu biết tôi đã phục dịch cậu thể nào, và bầy súc vật của cậu đã sinh sôi ra sao dưới tay tôi."'),
(861, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 30, 'OT', 'Vì ít ỏi là điều cậu có trước khi tôi đến, mà nay đã gia tăng rất nhiều; Đức Giê-hô-va đã ban phước cho cậu vì cớ tôi; vậy bây giờ, bao giờ tôi mới lo được cho nhà tôi?'),
(862, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 31, 'OT', 'La-ban nói: Ta sẽ cho ngươi cái gì? Gia-cốp nói: Ngài sẽ không cho tôi điều gì cả, nếu ngài làm cho tôi điều nầy, tôi sẽ trở lại chăn bầy chiên của ngài.'),
(863, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 32, 'OT', 'Hôm nay tôi sẽ đi ngang qua toàn thể bầy chiên của anh; tôi sẽ tách ra khỏi đó mọi con chiên có rằn và đốm, mọi con chiên màu nâu trong bầy chiên, và mọi con có đốm và rằn trong bầy dê; và điều đó sẽ là phần thưởng của tôi.'),
(864, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 33, 'OT', 'Sự ngay thẳng của tôi sẽ làm chứng cho tôi về sau, khi cậu xem xét công giá tôi trước mặt cậu: bất cứ con nào không có vằn và đốm ở các con dê, hay không có màu nâu ở các chiên con, thì đó là vật ăn cắp ở cùng tôi.'),
(865, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 34, 'OT', 'La-ban nói: Này, ước gì theo như lời ngươi nói.'),
(866, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 35, 'OT', 'Ngay ngày đó, La-ban tách riêng các dê đực có sọc và có đốm, và tất cả các dê cái có đốm và có đốm trắng, cùng mọi con chiên nào có màu sậm trong đàn của La-ban, rồi giao chúng cho các con trai mình.'),
(867, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 36, 'OT', 'Đặt cách biệt ba ngày đường giữa mình và Gia-cốp; và Gia-cốp chăn giữ những chiên của La-ban còn lại.'),
(868, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 37, 'OT', 'Gia-cốp lấy các nhánh cây bạch dương, cây hạnh và cây phong, rồi bóc những vạch trắng lộ phần trắng ra trên các nhánh cây ấy.'),
(869, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 38, 'OT', 'Người đặt những cây gậy đã lột vỏ vào rương nước, trước mặt bầy chiên, là nơi chúng đến uống; khi chúng đến uống nước thì động dục mà giao phối với nhau.'),
(870, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 39, 'OT', 'Các con chiên động dục nhìn những cây gậy đó, rồi các con chiên cái sinh ra những con chiên con có khoang, có đốm và có vằn.'),
(871, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 40, 'OT', 'Gia-cốp tách riêng các chiên con ra, rồi đặt mặt bầy chiên đối diện với các chiên có vằn và tất cả chiên màu sẫm trong bầy của La-ban; người lập riêng các đàn chiên của mình, không đặt chúng gần bầy chiên của La-ban.'),
(872, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 41, 'OT', 'Mỗi khi các bầy chiên giao phối, Gia-cốp đặt những cây gậy trước mắt chiên trong các máng uống nước, để chiên giao phối trước những cây gậy đó.'),
(873, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 42, 'OT', 'Nhưng khi nào các chiên gầy ốm, thì người không đặt các nhành đó; vậy thì, các chiên con gầy ốm thuộc về La-ban, còn các chiên con khỏe mạnh thuộc về Gia-cốp.'),
(874, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 30, 43, 'OT', 'Người ấy trở nên cực kỳ giàu có, có rất nhiều chiên, các nữ tớ, các nam tớ, lạc đà và lừa.'),
(875, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 1, 'OT', 'Gia-cốp nghe được lời các con trai của La-ban nói rằng: "Gia-cốp đã lấy hết những gì thuộc về cha chúng ta, và nhờ những gì thuộc về cha chúng ta mà làm nên tất cả vinh hiển này."'),
(876, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 2, 'OT', 'Gia-cốp thấy nét mặt của Lavan, và nầy, người không đối xử với mình như trước kia nữa.'),
(877, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 3, 'OT', 'Đức Giê-hô-va phán cùng Gia-cốp: Hãy trở về đất của tổ phụ ngươi và nơi sinh quán ngươi, Ta sẽ ở cùng ngươi.'),
(878, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 4, 'OT', 'Gia-cốp sai người gọi Ra-chên và Lê-a đến nơi bầy chiên của mình ngoài đồng,'),
(879, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 5, 'OT', 'Tôi thấy rõ vẻ mặt cha các con đối với tôi không còn như trước nữa, nhưng Đức Chúa Trời của cha tôi đã ở cùng tôi.'),
(880, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 6, 'OT', 'Vả hai ngươi cũng biết rằng ta đã phục dịch cha hai ngươi hết sức ta,'),
(881, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 7, 'OT', 'Cha hai ngươi đã lừa dối ta và đã mười lần đổi tiền công của ta, nhưng Đức Chúa Trời không cho phép người làm hại ta chút nào.'),
(882, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 8, 'OT', 'Nếu người nói: "Chiên nào có đốm sẽ là phần thưởng của ngươi", thì tất cả các con chiên đều sinh ra có đốm; và nếu người nói: "Chiên nào có sọc sẽ là phần thưởng của ngươi", thì tất cả các con chiên đều sinh ra có sọc.'),
(883, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 9, 'OT', 'Đức Chúa Trời đã cứu lấy bầy vật của cha các ngươi và ban cho ta.'),
(884, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 10, 'OT', 'Vả lại, trong lúc chiên giao phối, tôi ngước mắt lên và thấy trong giấc mơ: các con dê đực nhảy lên những con chiên đều có vằn, có đốm và có lốm đốm.'),
(885, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 11, 'OT', 'Thiên sứ của Đức Chúa Trời phán cùng ta trong mộng rằng: Hỡi Gia-cốp! Ta bèn thưa: Có tôi đây.'),
(886, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 12, 'OT', 'Thiên sứ phán: Hãy ngước mắt lên mà xem, tất cả các con dê đực đang lên trên bầy chiên đều có khoang, có vằn và có đốm; vì ta đã thấy mọi điều La-ban làm cùng ngươi.'),
(887, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 13, 'OT', 'Ta là Đức Chúa Trời của Bê-tên, nơi ngươi đã đổ dầu trên trụ đá và đã khấn hứa cùng Ta; bây giờ, hãy chỗi dậy, đi ra khỏi đất nầy và trở về đất tổ của ngươi.'),
(888, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 14, 'OT', 'Ra-chên và Lê-a đáp cùng người mà rằng: Chúng tôi còn phần nào hay là cơ nghiệp nào nơi nhà cha chúng tôi chăng?'),
(889, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 15, 'OT', 'Chẳng phải chúng tôi đã bị coi là người ngoài đối với người sao, vì người đã bán chúng tôi và ăn hết tiền của chúng tôi?'),
(890, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 16, 'OT', 'Tất cả tài sản mà Đức Chúa Trời đã đoạt lấy từ cha chúng tôi đều thuộc về chúng tôi và con cái chúng tôi. Vậy bây giờ, hãy làm mọi điều Đức Chúa Trời đã phán dạy chàng.'),
(891, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 17, 'OT', 'Gia-cốp đứng dậy, đỡ các con trai và các vợ mình lên lưng lạc đà.'),
(892, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 18, 'OT', 'Dẫn tất cả các bầy vật và mọi tài sản mình đã có, tức các bầy vật mình đã sắm được tại Pha-đan-A-ram, để đến cùng Y-sác, cha mình, tại đất Ca-na-an.'),
(893, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 19, 'OT', 'Khi La-ban đi cắt lông chiên mình, thì Ra-chên ăn cắp các tượng thần của cha nàng.'),
(894, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 20, 'OT', 'Gia-cốp đã lén lấy lòng La-ban người Syri, mà không nói cho ông biết rằng mình sẽ trốn đi.'),
(895, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 21, 'OT', 'Vậy người trốn đi, đem theo tất cả những gì thuộc về mình, rồi đứng dậy, đi qua sông và hướng về núi Ga-la-át.'),
(896, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 22, 'OT', 'Đến ngày thứ ba, người ta báo cho La-ban rằng Gia-cốp đã trốn chạy.'),
(897, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 23, 'OT', 'Người bèn đem các anh em mình đi theo mình, đuổi theo Gia-cốp một quãng đường bảy ngày, và đuổi kịp người tại núi Ga-la-át.'),
(898, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 24, 'OT', 'Đức Chúa Trời đến cùng La-ban người A-ram trong cơn chiêm bao ban đêm, phán với người rằng: Ngươi phải giữ mình cẩn thận, đừng nói với Gia-cốp điều gì, từ điều lành đến điều dữ.'),
(899, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 25, 'OT', 'La-ban đuổi kịp Gia-cốp; còn Gia-cốp thì đã dựng trại trên núi, và La-ban cùng các anh em mình cũng dựng trại trên núi Ga-la-át.'),
(900, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 26, 'OT', 'La-ban nói cùng Gia-cốp: "Ngươi đã làm gì vậy? Ngươi đã trộm lấy lòng ta và đem các con gái ta đi như những người bị bắt làm phu tù bằng gươm."'),
(901, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 27, 'OT', 'Tại sao ngươi lại lén lút mà trốn đi, đem ta đi như một kẻ bị đánh cắp, mà không báo cho ta biết, để ta có thể tiễn ngươi ra đi với niềm vui, với bài ca, với trống và với đờn cầm?'),
(902, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 28, 'OT', 'Và cháu đã không để cho ta hôn các con trai và các con gái ta; bây giờ cháu đã làm điều này cách dại dột.'),
(903, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 29, 'OT', 'Tay Ta có đủ quyền làm hại các ngươi, nhưng Đức Chúa Trời của cha các ngươi tối hôm qua đã nói cùng ta rằng: Ngươi phải giữ mình, đừng nói với Gia-cốp điều gì, dù lành hay dữ.'),
(904, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 30, 'OT', 'Bây giờ, ngươi đã đi vì nhớ nhà cha ngươi; vậy sao ngươi đã trộm các thần của ta?'),
(905, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 31, 'OT', 'Gia-cốp đáp và nói với Laban: "Vì tôi sợ, tôi nghĩ rằng có lẽ cậu sẽ cướp các con gái của cậu khỏi tôi."'),
(906, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 32, 'OT', 'Cùng ai mà tìm được các thần tượng của ngươi, thì người đó sẽ không sống! Trước mặt anh em chúng ta, hãy nhận biết những gì thuộc về ngươi nơi ta và hãy lấy đi; nhưng Gia-cốp không biết rằng Ra-chên đã trộm các thần tượng ấy.'),
(907, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 33, 'OT', 'La-ban vào trại của Gia-cốp, trại của Lê-a và trại của hai người đầy tớ, nhưng không tìm thấy gì cả. Rồi ông đi ra khỏi trại của Lê-a và vào trại của Ra-chên.'),
(908, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 34, 'OT', 'Ra-chên đã lấy các tượng thần, đặt vào trong túi da lạc đà và ngồi lên trên; La-ban tìm kiếm khắp lều nhưng không tìm thấy.'),
(909, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 35, 'OT', 'Bà nói cùng cha mình rằng: Xin chớ nổi giận cùng tôi, vì tôi không thể đứng dậy trước mặt ngài, bởi vì tôi đang có kỳ của đàn bà. Người tìm kiếm, nhưng không tìm thấy các tượng thần.'),
(910, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 36, 'OT', 'Gia-cốp bèn nổi giận và tranh cãi với La-ban. Gia-cốp đáp và nói với La-ban: "Tôi có tội gì, có lỗi gì, mà ông hăng hái đuổi theo tôi?'),
(911, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 37, 'OT', 'Ngươi đã dò xét mọi đồ vật của ta; vậy ngươi tìm được vật chi thuộc về nhà ngươi? Hãy đặt nó ra đây trước mặt anh em ta và anh em ngươi, để họ xét xử giữa hai chúng ta.'),
(912, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 38, 'OT', 'Này, hai mươi năm nay tôi ở cùng cậu, chiên và dê của cậu không sẩy một con nào, và tôi cũng không ăn chiên đực nào trong bầy chiên của cậu.'),
(913, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 39, 'OT', 'Con nào bị xé, tôi chẳng đem về cho ông; chính tôi sẽ bồi thường cho ông, dù con vật bị ăn cắp ban ngày hay bị ăn cắp ban đêm.'),
(914, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 40, 'OT', 'Ban ngày tôi bị nắng thiêu đốt, ban đêm bị lạnh giá hành hạ, giấc ngủ đã trốn khỏi mắt tôi.'),
(915, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 41, 'OT', 'Hãy xem, đã hai mươi năm nay tôi ở nhà ông; tôi đã phục vụ ông mười bốn năm vì hai con gái ông, và sáu năm vì bầy chiên của ông, mà ông đã thay đổi tiền công tôi đến mười lần.'),
(916, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 42, 'OT', 'Nếu không có Đức Chúa Trời của cha tôi, Đức Chúa Trời của Aùp-ra-ham và sự kính sợ của Y-sác, thì chắc lúc này ngươi đã đuổi tôi đi tay không. Nhưng Đức Chúa Trời đã thấy cảnh khốn khổ của tôi và công việc hai tay tôi làm, nên đêm qua Ngài đã xét xử công bình cho tôi.'),
(917, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 43, 'OT', 'La-ban đáp và nói với Gia-cốp: Các con gái là con gái ta, các con trai là con trai ta, các bầy chiên là bầy chiên ta, và mọi điều mà ngươi thấy đều là của ta. Ta sẽ làm gì được cho các con gái ta ngày hôm nay, hay cho các con trai chúng, mà chúng đã sinh ra?'),
(918, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 44, 'OT', 'Vậy bây giờ, hãy đến, chúng ta sẽ lập giao ước với nhau, để làm chứng giữa ta và ngươi.'),
(919, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 45, 'OT', 'Gia-cốp lấy một hòn đá, dựng đứng nó lên làm trụ.'),
(920, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 46, 'OT', 'Gia-cốp nói cùng các anh em mình: "Hãy góp đá lại." Họ bèn góp đá lại, chất thành một đống, rồi ngồi trên đống đó ăn uống.'),
(921, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 47, 'OT', 'La-ban gọi nó là Y-ê-ga Sa-ha-đu-ta, còn Gia-cốp gọi nó là Ga-lét.'),
(922, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 48, 'OT', 'La-ban nói: Đống đá nầy ngày nay làm chứng giữa tôi và anh; bởi vậy người ta gọi tên nó là Ga-lét.'),
(923, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 49, 'OT', 'và Mích-ba, mà La-ban nói: Nguyện Đức Giê-hô-va nhìn xem giữa tôi và ông, khi mỗi người chúng ta khuất khỏi tầm mắt người kia.'),
(924, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 50, 'OT', 'Nếu ngươi hành hại các con gái ta, hoặc nếu ngươi lấy vợ khác ngoài các con gái ta, thì hãy biết rằng Đức Chúa Trời chứng giám giữa ta và ngươi.'),
(925, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 51, 'OT', 'La-ban nói cùng Gia-cốp: Nầy, đống đá nầy, và nầy cây trụ mà ta đã dựng giữa ta và ngươi.'),
(926, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 52, 'OT', 'Đống đá nầy và trụ đá nầy làm chứng rằng ta sẽ không đi ngang qua đống đá nầy mà đến cùng ngươi để làm điều ác, và ngươi cũng sẽ không đi ngang qua đống đá nầy và trụ đá nầy mà đến cùng ta để làm điều ác.'),
(927, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 53, 'OT', 'Đức Chúa Trời của Aùp-ra-ham và Đức Chúa Trời của Na-cô sẽ xét xử giữa chúng ta, Đức Chúa Trời của cha các người đó; rồi Gia-cốp thề theo Đấng mà cha người, Y-sác, kính sợ.'),
(928, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 54, 'OT', 'Gia-cốp dâng một lễ tế trên núi, rồi gọi các anh mình đến ăn bánh; họ bèn ăn bánh và ngủ đêm trên núi.'),
(929, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 31, 55, 'OT', 'La-ban dậy sớm vào buổi sáng, hôn các con trai và các con gái mình, chúc phước cho họ, rồi đi và trở về chỗ mình.'),
(930, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 32, 1, 'OT', 'Gia-cốp đi theo đường lối mình, thì có các thiên sứ của Đức Chúa Trời gặp ông.'),
(931, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 32, 2, 'OT', 'Khi Gia-cốp thấy họ, nói rằng: Đây là trại quân của Đức Chúa Trời! Nên người đặt tên chỗ đó là Ma-ha-na-im.'),
(932, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 32, 3, 'OT', 'Gia-cốp sai các thiên sứ đi trước mình đến cùng Ê-sau, anh mình, tại xứ Sê-i-rơ, vùng đất Ê-đôm.'),
(933, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 32, 4, 'OT', 'Người bèn dặn họ rằng: "Hãy nói như thế này với chủ tôi là Ê-sau: Gia-cốp, kẻ tôi tớ ngài, nói rằng: Tôi đã ở với La-ban và ở lại cho đến ngày nay."'),
(934, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 32, 5, 'OT', 'Tôi có bò, lừa, chiên, đầy tớ trai, tớ gái; tôi sai người đi báo cho chủ tôi biết, để được ơn trước mặt ngài.'),
(935, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 32, 6, 'OT', 'Các thiên sứ trở về cùng Gia-cốp, nói rằng: Chúng tôi đã đi đến anh ngươi, đến Ê-sau; nầy, người đang đi đến đón ngươi, và có bốn trăm người cùng đi với người ấy.'),
(936, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 32, 7, 'OT', 'Gia-cốp rất sợ hãi và lo lắng, bèn chia những người cùng đi với mình, và các bầy chiên, bò, lạc đà ra làm hai đạo quân.'),
(937, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 32, 8, 'OT', 'Nếu Ê-xau đến đánh một trong hai trại, thì trại còn lại sẽ được thoát.'),
(938, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 32, 9, 'OT', 'Gia-cốp nói: Đức Chúa Trời của cha tôi là Aùp-ra-ham, Đức Chúa Trời của cha tôi là Y-sác, Đức Giê-hô-va, Đấng đã phán cùng tôi rằng: Hãy trở về đất ngươi và cùng dân tộc ngươi, ta sẽ làm ơn cho ngươi.'),
(939, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 32, 10, 'OT', 'Tôi thật sự nhỏ bé hơn tất cả các ân sủng và sự thật mà Đức Giê-hô-va đã làm cho kẻ tôi tớ Ngài, vì tôi đã qua sông Giô-đanh này chỉ với cây gậy trong tay, còn bây giờ tôi đã trở thành hai đạo quân.'),
(940, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 32, 11, 'OT', 'Xin Đức Chúa Trời cứu con khỏi tay anh con, khỏi tay Ê-sau; vì con sợ người đó, e rằng người sẽ đến đánh con, và đánh luôn mẹ cùng con cái nữa.'),
(941, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 32, 12, 'OT', 'Còn Ngài thì đã phán: "Ta sẽ thật lòng làm ơn cho ngươi, và đặt dòng dõi ngươi như cát biển, không thể đếm được vì quá đông."'),
(942, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 32, 13, 'OT', 'Đêm ấy, người ngủ lại tại đó, rồi lấy từ những gì có trong tay mình làm lễ vật dâng cho Ê-sau, anh mình.'),
(943, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 32, 14, 'OT', 'hai trăm dê cái và hai mươi dê đực, hai trăm chiên cái và hai mươi chiên đực;'),
(944, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 32, 15, 'OT', 'ba mươi lạc đà cái có con đang bú, bốn mươi bò cái và mười bò đực, hai mươi lừa cái và mười lừa con.'),
(945, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 32, 16, 'OT', 'Trao vào tay các đầy tớ mình mỗi đàn riêng rẽ, rồi bảo các đầy tớ mình: "Hãy đi trước mặt ta, và giữa đàn nầy với đàn kia phải giữ một khoảng cách."'),
(946, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 32, 17, 'OT', 'Người dặn người đi đầu rằng: "Khi Ê-sau, anh ta, gặp ngươi và hỏi ngươi rằng: ''Ngươi là ai, đi đâu, và những vật này trước mặt ngươi là của ai?''"'),
(947, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 32, 18, 'OT', 'hãy nói rằng: Đây là lễ vật được gởi cho chủ tôi là Ê-sau; và nầy, chính Gia-cốp cũng đang theo sau chúng tôi.'),
(948, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 32, 19, 'OT', 'Gia-cốp cũng dặn người thứ hai, cũng dặn người thứ ba, và dặn tất cả những người đi theo sau các bầy, rằng: "Theo đúng lời này, các ngươi phải nói với Ê-sau khi gặp người."'),
(949, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 32, 20, 'OT', 'Hãy nói thêm rằng: "Nầy, Gia-cốp, kẻ tôi tớ của ngài, đang theo sau chúng tôi." Vì người nói trong lòng: "Ta sẽ lấy lễ vật đi trước làm dịu lòng người, rồi sau đó mới đến diện kiến; có lẽ người sẽ nhận lời ta."'),
(950, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 32, 21, 'OT', 'Vậy lễ vật đi trước mặt người, còn người thì trọ đêm đó trong trại.'),
(951, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 32, 22, 'OT', 'Đoạn ấy, người chổi dậy, đem hai người vợ, hai người tớ gái và mười một đứa con mình, đi qua chỗ qua sông Gia-bốc.'),
(952, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 32, 23, 'OT', 'Người lấy họ, đưa qua dòng sông, và đưa cả những gì thuộc về mình.'),
(953, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 32, 24, 'OT', 'Gia-cốp ở lại một mình; rồi có một người vật lộn với ông cho đến khi rạng đông.'),
(954, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 32, 25, 'OT', 'Người ấy thấy mình không thắng nổi, bèn đánh vào ổ háng của Gia-cốp, và ổ háng của Gia-cốp liền trật khi vật lộn với người ấy.'),
(955, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 32, 26, 'OT', 'Người ấy nói: "Hãy để tôi đi, vì rạng đông đã lên rồi." Nhưng Gia-cốp đáp: "Tôi sẽ không để người đi, nếu người chưa ban phước cho tôi."'),
(956, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 32, 27, 'OT', 'Người ấy hỏi: "Tên ngươi là gì?" Đáp rằng: "Tên tôi là Gia-cốp."'),
(957, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 32, 28, 'OT', 'Người nói: Danh ngươi sẽ không còn gọi là Gia-cốp nữa, mà sẽ là Y-sơ-ra-ên, vì ngươi đã vật lộn cùng Đức Chúa Trời và cùng người ta, và ngươi đã được.'),
(958, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 32, 29, 'OT', 'Gia-cốp hỏi và nói: Xin hãy cho tôi biết tên ông. Người đáp: Sao ngươi lại hỏi tên ta? Rồi người ấy ban phước cho ông tại đó.'),
(959, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 32, 30, 'OT', 'Gia-cốp đặt tên cho nơi ấy là Phê-ni-ên, vì người nói: "Tôi đã thấy Đức Chúa Trời mặt đối mặt, và linh hồn tôi được cứu sống."'),
(960, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 32, 31, 'OT', 'Mặt trời mọc lên khi người qua khỏi Phê-ni-ên, và người đi khập khiễng vì hông mình.'),
(961, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 32, 32, 'OT', 'Bởi vậy, cho đến ngày nay con cháu Y-sơ-ra-ên không ăn gân thần kinh ở đùi; vì người ấy đã chạm vào đùi Gia-cốp, ngay nơi gân thần kinh.'),
(962, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 33, 1, 'OT', 'Gia-cốp ngước mắt lên và thấy, nầy Ê-sau đang đến, đi cùng người là bốn trăm người đàn ông. Gia-cốp bèn chia các con trẻ ra, đặt trên Lê-a, trên Ra-chên và trên hai người tớ gái.'),
(963, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 33, 2, 'OT', 'xếp các người hầu gái cùng con cái mình ở đằng trước, Lê-a và các con nàng ở giữa, còn Ra-chên và Giô-sép ở cuối cùng.'),
(964, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 33, 3, 'OT', 'Người đi trước họ, rồi sấp mình xuống đất bảy lần, cho đến khi gần anh mình.'),
(965, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 33, 4, 'OT', 'Ê-sau chạy đến gặp người, ôm choàng cổ, hôn người, và cả hai đều khóc.'),
(966, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 33, 5, 'OT', 'Ê-xau ngước mắt lên, thấy các người đàn bà và các trẻ nhỏ, bèn hỏi: "Những người nầy là ai của anh?" Gia-cốp đáp: "Là các trẻ nhỏ mà Đức Chúa Trời đã ban cho kẻ tôi tớ của ngài."'),
(967, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 33, 6, 'OT', 'Các người tớ gái cùng con cái họ đi tới gần, rồi cúi mình xuống.'),
(968, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 33, 7, 'OT', 'Lê-a cùng các con của nàng cũng lại gần và sấp mình xuống; sau đó Giô-sép và Ra-chên lại gần và sấp mình xuống.'),
(969, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 33, 8, 'OT', 'Ê-sau nói: Toán dân sự mà tôi đã gặp đi trước đó là của ai? Gia-cốp đáp: Để được ơn trước mặt chúa tôi.'),
(970, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 33, 9, 'OT', 'Ê-sau nói: Anh có đủ rồi, hỡi anh em ta; hãy để cho ngươi những gì thuộc về ngươi.'),
(971, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 33, 10, 'OT', 'Gia-cốp nói: Xin anh, nếu tôi được ơn trước mặt anh, xin hãy nhận lễ vật tôi dâng từ tay tôi; vì tôi đã thấy mặt anh như thấy mặt Đức Chúa Trời, và anh đã đẹp lòng tiếp nhận tôi.'),
(972, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 33, 11, 'OT', 'Hãy nhận lấy lễ vật mà tôi đã dâng cho anh, vì Đức Chúa Trời đã thương xót tôi và ban cho tôi đủ mọi thứ; người nài xin ông quá đỗi, nên ông phải nhận lấy.'),
(973, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 33, 12, 'OT', 'Ê-sau nói: Hãy lên đường, chúng ta sẽ đi; tôi sẽ đi trước mặt anh.'),
(974, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 33, 13, 'OT', 'Gia-cốp thưa: Chúa tôi biết rằng các con trẻ còn yếu đuối, và chiên cùng bò cái đang nuôi con cũng đang theo tôi; nếu bắt chúng đi mau trong một ngày, thì cả bầy chiên sẽ chết hết.'),
(975, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 33, 14, 'OT', 'Xin chúa hãy đi trước kẻ tôi tớ chúa, còn tôi sẽ từ từ dẫn đoàn theo bước của súc vật và các trẻ nhỏ đi trước, cho đến khi tôi đến cùng chúa tại Sê-i-rơ.'),
(976, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 33, 15, 'OT', 'Ê-sau nói: Xin để lại cùng anh một số người của tôi đây. Gia-cốp đáp: Làm chi vậy? miễn tôi được ơn trước mặt chúa tôi vậy!'),
(977, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 33, 16, 'OT', 'Ngày ấy, Ê-sau trở về đường lối mình đi về Sê-i-rơ.'),
(978, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 33, 17, 'OT', 'Gia-cốp đi đến Su-cốt, xây một ngôi nhà cho mình và làm những cái lều cho súc vật của ông; vì cớ đó, ông đặt tên chỗ ấy là Su-cốt.'),
(979, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 33, 18, 'OT', 'Gia-cốp đi đến thành Si-chem thuộc về đất Ca-na-an, được bình an, khi người từ Pha-đan-A-ram trở về, và người cắm trại trước thành.'),
(980, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 33, 19, 'OT', 'Mua miếng đất chỗ người dựng trại, giá một trăm quế tạ, của các con trai Hê-mô, cha của Si-chem.'),
(981, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 33, 20, 'OT', 'Người lập một bàn thờ tại nơi đó, và đặt tên cho nó là Eân-Eân-ô-hê-Y-sơ-ra-ên.'),
(982, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 34, 1, 'OT', 'Đi-na, con gái của Lê-a mà Lê-a đã sinh cho Gia-cốp, đi ra để xem các con gái của xứ.'),
(983, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 34, 2, 'OT', 'Si-chem, con trai của Hê-mô người Hê-vít, là người lãnh đạo vùng đất ấy, thấy nàng, liền bắt lấy, nằm với nàng và làm nhục nàng.'),
(984, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 34, 3, 'OT', 'Tâm hồn chàng gắn bó với Đi-na, con gái Gia-cốp, và chàng yêu người thiếu nữ ấy, lấy lời dịu dàng nói chuyện cùng nàng.'),
(985, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 34, 4, 'OT', 'Si-chem nói cùng Hê-mô, cha mình, rằng: Hãy lấy cho tôi đứa gái nầy làm vợ.'),
(986, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 34, 5, 'OT', 'Gia-cốp nghe tin người ta làm ô uế Đi-na, con gái mình, nhưng các con trai ông đang ở ngoài đồng với đoàn gia súc, nên Gia-cốp làm thinh cho đến khi các con trai ông trở về.'),
(987, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 34, 6, 'OT', 'Hê-mô, cha của Si-chem, đi ra gặp Gia-cốp để nói chuyện với người.'),
(988, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 34, 7, 'OT', 'Các con trai của Gia-cốp từ ngoài đồng trở về, khi nghe việc ấy thì buồn bã, và rất giận dữ, vì Si-chem đã làm điều nhục nhã trong Y-sơ-ra-ên, khi nằm cùng con gái của Gia-cốp; điều đó thì không nên làm.'),
(989, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 34, 8, 'OT', 'Hê-mô nói cùng họ rằng: Tâm hồn Si-chem, con trai tôi, đã say mê con gái các ông; xin hãy cho nàng làm vợ nó.'),
(990, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 34, 9, 'OT', 'Hãy kết thông gia với chúng tôi: các ông hãy gả con gái mình cho chúng tôi, và cưới các con gái chúng tôi về cho các ông.'),
(991, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 34, 10, 'OT', 'Hãy ở cùng chúng tôi; đất nầy sẽ sẵn cho các ngươi; hãy ở, buôn bán và chiếm hữu nó.'),
(992, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 34, 11, 'OT', 'Si-chem nói với cha và anh em của nàng rằng: Xin cho tôi được ơn trước mặt các ông, và điều gì các ông nói với tôi, tôi sẽ cho.'),
(993, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 34, 12, 'OT', 'Hãy đòi ta rất nhiều của hồi môn và lễ vật; ta sẽ trả đúng như các ngươi nói với ta; nhưng hãy gả cô gái ấy cho ta làm vợ.'),
(994, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 34, 13, 'OT', 'Các con trai Gia-cốp đáp lại Si-chem và Hê-mô, cha người, cách dối trá mà nói chuyện với họ, vì người đã làm ô uế Đi-na, em gái họ.'),
(995, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 34, 14, 'OT', 'Họ nói với các người ấy: Chúng tôi không thể làm việc này, gả em gái chúng tôi cho một người đàn ông chưa chịu cắt bì, vì điều đó là một sự sỉ nhục đối với chúng tôi.'),
(996, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 34, 15, 'OT', 'Chỉ điều này chúng tôi sẽ chấp thuận cho các ông: nếu các ông trở nên giống như chúng tôi, tức là mọi người nam trong các ông phải chịu phép cắt bì.'),
(997, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 34, 16, 'OT', 'Chúng tôi sẽ gả con gái chúng tôi cho các ông, và cưới con gái các ông về cho chúng tôi; rồi chúng tôi sẽ ở cùng các ông, và trở thành một dân tộc duy nhất.'),
(998, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 34, 17, 'OT', 'Nếu các ngươi không chịu nghe lời chúng tôi mà chịu phép cắt bì, thì chúng tôi sẽ lấy lại con gái mình rồi đi khỏi nơi khác.'),
(999, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 34, 18, 'OT', 'Lời nói của họ làm đẹp lòng Hê-mô và Si-chem, con trai Hê-mô.'),
(1000, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 34, 19, 'OT', 'Người trai trẻ không chậm trễ trong việc thực hiện điều đó, vì người ta ưa thích con gái của Gia-cốp; và người này được trọng vọng hơn tất cả những người trong nhà cha mình.'),
(1001, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 34, 20, 'OT', 'Hê-mô và Si-chem, con trai người, đi đến cửa thành mình, nói cùng những người trong thành rằng:'),
(1002, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 34, 21, 'OT', 'Các người ấy hòa thuận với chúng ta; họ sẽ ở trong đất và buôn bán trên đất; và đất nầy rõ ràng rộng rãi trước mặt họ. Chúng ta sẽ lấy con gái họ làm vợ, và gả con gái chúng ta cho họ.'),
(1003, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 34, 22, 'OT', 'Chỉ điều nầy họ sẽ thuận ở cùng chúng ta, để trở thành một dân: khi mọi người nam trong chúng ta chịu cắt bì như chính họ đã chịu cắt bì.'),
(1004, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 34, 23, 'OT', 'Bầy gia súc, của cải và mọi súc vật của chúng, há chẳng phải là của chúng ta sao? Chỉ cần làm cho họ vừa lòng, thì chúng sẽ ở cùng chúng ta.'),
(1005, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 34, 24, 'OT', 'Mọi người ra khỏi cửa thành mình đều nghe theo Hê-mô và Si-chem, con trai người, và mọi nam giới ra khỏi cửa thành mình đều chịu cắt bì.'),
(1006, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 34, 25, 'OT', 'Đến ngày thứ ba, khi họ đang đau đớn, thì hai con trai của Gia-cốp là Si-mê-ôn và Lê-vi, anh em của Đi-na, mỗi người cầm gươm của mình, xông vào thành một cách bất ngờ và giết hết mọi người nam.'),
(1007, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 34, 26, 'OT', 'Họ giết Hê-mô và Si-chem, con trai người, bằng lưỡi gươm, rồi đem Đi-na ra khỏi nhà Si-chem và đi ra.'),
(1008, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 34, 27, 'OT', 'Các con trai Gia-cốp đến trên những người đã bị giết và cướp phá thành phố, vì chúng đã làm ô uế em gái họ.'),
(1009, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 34, 28, 'OT', 'bắt các bầy chiên, bò, lừa của chúng, cùng mọi vật trong thành và mọi vật ngoài đồng;'),
(1010, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 34, 29, 'OT', 'Họ lấy hết tài sản của chúng, tất cả con trẻ và vợ các nàng, rồi cướp phá, và lấy mọi thứ ở trong nhà.'),
(1011, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 34, 30, 'OT', 'Gia-cốp nói với Si-mê-ôn và Lê-vi: Các con đã làm cho ta lâm vào cảnh khốn quẫn, khiến ta bị sỉ nhục giữa những người sống trong đất này, là người Ca-na-an và người Phê-rê-sít. Ta đây chỉ có ít người; nếu họ hiệp lại chống lại ta và đánh ta, thì ta và nhà ta sẽ bị tiêu diệt.'),
(1012, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 34, 31, 'OT', 'Họ đáp: Đáng lẽ người ta làm nhục em gái chúng tôi như một kẻ điếm sao?'),
(1013, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 35, 1, 'OT', 'Đức Chúa Trời phán cùng Gia-cốp: "Hãy chổi dậy, đi lên Bê-tên và ở đó; và hãy làm tại đó một bàn thờ cho Đức Chúa Trời, là Đấng đã hiện ra cùng ngươi khi ngươi chạy trốn khỏi Ê-sau, anh ngươi."'),
(1014, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 35, 2, 'OT', 'Gia-cốp nói với gia đình mình và với mọi người ở cùng ông rằng: "Hãy dẹp các thần ngoại bang khỏi giữa các ngươi, hãy làm cho mình được thanh sạch và hãy đổi áo xống các ngươi."'),
(1015, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 35, 3, 'OT', 'Hãy chổi dậy, lên Bê-tên, ta sẽ lập một bàn thờ tại đó cho Đức Chúa Trời, là Đấng đã đáp lời ta trong ngày ta gặp hoạn nạn, và đã ở cùng ta trong con đường ta đã đi.'),
(1016, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 35, 4, 'OT', 'Vậy họ đưa cho Gia-cốp mọi thần tượng của các thần ngoại bang mà họ có trong tay mình, và các vòng đeo ở tai họ; rồi Gia-cốp chôn những vật ấy dưới gốc cây sồi gần Si-chem.'),
(1017, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 35, 5, 'OT', 'Họ khởi hành, và Đức Chúa Trời khiến sự kinh hãi giáng trên các thành ở chung quanh chúng, nên họ không dám đuổi theo các con trai của Gia-cốp.'),
(1018, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 35, 6, 'OT', 'Gia-cốp cùng mọi người đi theo ông đến Lu-xơ, là Bê-tên, thuộc đất Ca-na-an.'),
(1019, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 35, 7, 'OT', 'Người xây một bàn thờ tại đó, và Người đặt tên cho nơi ấy là Eân-Bê-tên, vì tại đó Đức Chúa Trời đã hiện ra cùng Người khi Người đang trốn chạy khỏi mặt anh mình.'),
(1020, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 35, 8, 'OT', 'Đê-bô-ra, người vú nuôi của Rê-be-ca, qua đời và được chôn dưới gốc cây dẻ bộp gần Bê-tên; người ta gọi cây đó là A-lôn-Ba-cút.'),
(1021, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 35, 9, 'OT', 'Đức Chúa Trời lại hiện ra cùng Gia-cốp khi người trở về từ Pha-đan-A-ram và ban phước cho người.'),
(1022, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 35, 10, 'OT', 'Đức Chúa Trời phán cùng người rằng: "Tên ngươi là Gia-cốp; từ nay về sau, tên ngươi sẽ không còn gọi là Gia-cốp nữa, nhưng ngươi sẽ được gọi là Y-sơ-ra-ên." Và Ngài đặt tên người là Y-sơ-ra-ên.'),
(1023, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 35, 11, 'OT', 'Đức Chúa Trời phán cùng người rằng: Ta là Đức Chúa Trời Toàn Năng, hãy sinh sản và thêm nhiều; một dân và hội các dân sẽ phát ra từ ngươi, và các vua sẽ ra từ ngươi.'),
(1024, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 35, 12, 'OT', 'Đất mà ta đã ban cho Aùp-ra-ham và Y-sác, ta sẽ ban cho ngươi và cho dòng dõi ngươi sau ngươi.'),
(1025, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 35, 13, 'OT', 'Đức Chúa Trời bèn ngự lên khỏi nơi Ngài đã phán cùng Gia-cốp.'),
(1026, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 35, 14, 'OT', 'Gia-cốp dựng một trụ đá tại nơi Đức Chúa Trời đã phán cùng người, đổ rượu tế lên nó và đổ dầu lên nó.'),
(1027, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 35, 15, 'OT', 'Gia-cốp đặt tên cho nơi Đức Chúa Trời đã phán cùng ông là Bê-tên.'),
(1028, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 35, 16, 'OT', 'Họ rời khỏi Bê-tên, và khi còn cách Ê-phrát một đoạn đường ngắn, thì Ra-chên đau đớn khi sinh nở.'),
(1029, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 35, 17, 'OT', 'Đang lúc bà ấy đau đớn khi sinh, bà đỡ đã nói với bà ấy: "Đừng sợ, vì con trai này cũng thuộc về ngươi."'),
(1030, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 35, 18, 'OT', 'Khi mạng sống của nàng ra đi vì nàng chết, thì nàng đặt tên con trai là Bê-nô-ni; nhưng cha nó đặt tên cho nó là Bên-gia-min.'),
(1031, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 35, 19, 'OT', 'Ra-chên qua đời và được chôn bên đường đi về Ê-phrát, tức là Bết-lê-hem.'),
(1032, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 35, 20, 'OT', 'Gia-cốp dựng một trụ đá trên phần mộ của nàng; ấy là trụ đá trên phần mộ của Ra-chên cho đến ngày nay.'),
(1033, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 35, 21, 'OT', 'Y-sơ-ra-ên đi tiếp, và dời trại mình ra khỏi phía bên kia tháp Ê-đe.'),
(1034, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 35, 22, 'OT', 'Khi Y-sơ-ra-ên đang cư ngụ tại vùng đất ấy, thì Ru-bên đi và nằm cùng Bi-la, người hầu của cha mình; và Y-sơ-ra-ên nghe biết việc đó. Vậy, các con trai của Gia-cốp là mười hai người.'),
(1035, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 35, 23, 'OT', 'Các con trai của Lê-a, trưởng nam của Gia-cốp là Ru-bên, rồi Si-mê-ôn, Lê-vi, Giu-đa, Y-sa-ca và Sa-bu-lôn.'),
(1036, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 35, 24, 'OT', 'Con trai của Ra-chên là Giô-sép và Bên-gia-min.'),
(1037, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 35, 25, 'OT', 'Các con trai của Bi-la, tôi tớ của Ra-chên, là Đan và Nép-ta-li.'),
(1038, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 35, 26, 'OT', 'Và các con trai của Xinh-ba, tớ gái của Lê-a, là Gát và A-se. Những người này là các con trai của Gia-cốp, sinh cho người tại Pha-đan-A-ram.'),
(1039, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 35, 27, 'OT', 'Gia-cốp đến cùng Y-sác, cha mình, ở Mam-rê, tại Ki-ri-át-A-ra-ba, tức là Hếp-rôn, nơi Aùp-ra-ham và Y-sác đã cư ngụ.'),
(1040, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 35, 28, 'OT', 'Tuổi của Y-sác là một trăm tám mươi năm.'),
(1041, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 35, 29, 'OT', 'Ê-sau và Gia-cốp, các con trai của người, chôn Y-sác. Người qua đời, được thu về cùng dân mình, khi đã già và sống đủ số năm.'),
(1042, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 1, 'OT', 'Đây là các thế hệ của Ê-sau, tức là Ê-đôm.'),
(1043, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 2, 'OT', 'Ê-xau lấy các vợ mình từ con gái xứ Ca-na-an: A-đa, con gái Ê-lôn, người Hê-tít, và A-hô-li-ba-ma, con gái A-na, con gái Xi-bê-ôn, người Hê-vít.'),
(1044, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 3, 'OT', 'và Bách-mát, con gái của Ích-ma-ên, em gái của Nê-ba-giốt.'),
(1045, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 4, 'OT', 'A-đa sinh Ê-li-pha cho Ê-sau; Bách-mát sinh Rê-u-ên;'),
(1046, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 5, 'OT', 'Và A-hô-li-ba-ma sinh Giê-úc, Gia-lam và Cô-ra. Đây là các con trai của Ê-sau, sinh cho người tại xứ Ca-na-an.'),
(1047, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 6, 'OT', 'Ê-sau đem các vợ mình, các con trai, các con gái, mọi người trong nhà mình, các bầy súc vật mình, mọi súc vật mình, và mọi tài sản mình đã thu được tại đất Ca-na-an, rồi đi đến một xứ khác, tránh xa Gia-cốp, anh mình.'),
(1048, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 7, 'OT', 'Vì tài sản của họ rất nhiều đến nỗi không thể ở chung với nhau được, và đất nơi họ cư ngụ không đủ rộng để nuôi sống họ vì bầy gia súc của họ.'),
(1049, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 8, 'OT', 'Ê-sau ở trên núi Sê-i-rơ; ấy là Ê-sau, tức là Ê-đôm.'),
(1050, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 9, 'OT', 'Đây là dòng dõi của Ê-sau, cha của Ê-đôm, ở trên núi Sê-i-rơ.'),
(1051, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 10, 'OT', 'Đây là các tên con trai của Ê-sau: Ê-li-pha, con trai của A-đa-vợ, vợ Ê-sau; Rê-u-ên, con trai của Bách-mát, vợ Ê-sau.'),
(1052, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 11, 'OT', 'Các con trai của Ê-li-phách là Thê-ma, Ô-ma, Xê-phô, Ga-tham và Kê-na.'),
(1053, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 12, 'OT', 'Thim-na là người vợ lẽ của Ê-li-phách, con trai của Ê-sau; và Thim-na đã sanh A-ma-léc cho Ê-li-phách. Đó là các con của A-đa, vợ của Ê-sau.'),
(1054, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 13, 'OT', 'Còn đây là các con trai của Rê-u-ên: Na-hát, Sê-rách, Sam-ma và Mích-xa. Những người này là con trai của Bách-mát, vợ của Ê-sau.'),
(1055, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 14, 'OT', 'Và đây là các con trai của A-hô-li-ba-ma, con gái A-na, con gái Xi-bê-ôn, vợ của Ê-sau: nàng sinh cho Ê-sau Giê-úc, Gia-lam và Cô-ra.'),
(1056, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 15, 'OT', 'Đây là các trưởng tộc trong vòng con cháu Ê-sau: các con trai Ê-li-pha, con trưởng nam của Ê-sau, là trưởng tộc Thê-man, trưởng tộc Ô-ma, trưởng tộc Xê-phô, trưởng tộc Kê-na.'),
(1057, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 16, 'OT', 'trưởng tộc Cô-ra, trưởng tộc Ga-tham, trưởng tộc A-ma-léc. Đó là các trưởng tộc của Ê-li-phaz trong đất Ê-đôm, là con cháu của A-đa.'),
(1058, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 17, 'OT', 'Đây là các con trai của Rê-u-ên, con trai của Ê-sau: trưởng tộc Na-hát, trưởng tộc Sê-rách, trưởng tộc Sam-ma, trưởng tộc Mích-xa. Đó là các trưởng tộc của Rê-u-ên tại đất Ê-đôm, và là các con trai của Bách-mát.'),
(1059, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 18, 'OT', 'Và đây là các con trai của A-hô-li-ba-ma, vợ Ê-sau: trưởng tộc Giê-úc, trưởng tộc Gia-lam, trưởng tộc Cô-ra. Đó là các trưởng tộc do A-hô-li-ba-ma, con gái của A-na, vợ Ê-sau, sinh ra.'),
(1060, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 19, 'OT', 'Đây là các con trai của Ê-sau và đây là các trưởng tộc của người; ấy là Ê-đôm.'),
(1061, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 20, 'OT', 'Đây là các con trai của Sê-i-rơ người Hô-rít, những người ở đất ấy: Lô-than, Sô-banh, Xi-bê-ôn, A-na,'),
(1062, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 21, 'OT', 'Đi-sôn, Eùt-xe và Đi-san. Đó là các trưởng tộc người Hô-rít, con cháu của Sê-i-rơ, tại xứ Ê-đôm.'),
(1063, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 22, 'OT', 'Các con trai của Lô-than là Hô-ri và Hê-man; còn Thim-na là em gái của Lô-than.'),
(1064, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 23, 'OT', 'Đây là các con trai của Sô-banh: Anh-van, Ma-na-hát, Ê-banh, Sê-phô và Ô-nam.'),
(1065, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 24, 'OT', 'Và đây là các con trai của Xi-bê-ôn: Ai-gia và A-na, chính là A-na, người đã tìm thấy các suối nước nóng trong đồng vắng, khi đang chăn lừa cho Xi-bê-ôn, cha mình.'),
(1066, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 25, 'OT', 'Và đây là các con của A-na: Đi-sôn và A-hô-li-ba-ma, con gái A-na.'),
(1067, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 26, 'OT', 'Đây là các con trai của Đi-sôn: Hem-đan, Eách-ban, Dít-ran và Kê-ran.'),
(1068, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 27, 'OT', 'Đây là con trai của Eùt-xe: Binh-han, Xa-van và A-can.'),
(1069, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 28, 'OT', 'Đây là các con trai của Đi-san: Uùt-sơ và A-ran.'),
(1070, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 29, 'OT', 'Đây là các quan trưởng của dân Hô-rít: quan trưởng Lô-than, quan trưởng Sô-banh, quan trưởng Xi-bê-ôn, quan trưởng A-na,'),
(1071, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 30, 'OT', 'Trưởng tộc Đi-sôn, trưởng tộc Eùt-xe, trưởng tộc Đi-san. Đó là các trưởng tộc của dân Hô-rít, theo các trưởng tộc của họ, tại xứ Sê-i-rơ.'),
(1072, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 31, 'OT', 'Các vua nầy trị vì trong xứ Ê-đôm trước khi có một vua trị vì trên con cái Y-sơ-ra-ên.'),
(1073, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 32, 'OT', 'Bê-la, con trai của Bê-ô, trị vì tại Ê-đôm; tên thành của người là Đin-ha-ba.'),
(1074, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 33, 'OT', 'Bê-la băng hà, rồi Giô-báp, con trai Sê-rách, người Bốt-ra, lên ngôi kế vị người.'),
(1075, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 34, 'OT', 'Giô-báp băng hà, rồi Hu-sam, người xứ Thê-man, lên ngôi vua thay người.'),
(1076, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 35, 'OT', 'Vua Hu-sam băng, và Ha-đát, con trai Bê-đát, lên ngôi kế vị người; người đã đánh bại dân Ma-đi-an tại đồng Mô-áp; tên thành của người là A-vít.'),
(1077, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 36, 'OT', 'Ha-đát băng hà, và Sam-la người Ma-rê-ca lên ngôi thế cho người.'),
(1078, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 37, 'OT', 'Vua Sam-la băng hà, Sau-lơ người Rê-hô-bốt ở bên bờ sông lên nối ngôi vua.'),
(1079, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 38, 'OT', 'Sau-lơ băng hà, Ba-anh-ha-nan con trai Aïc-bồ lên ngôi vua thay người.'),
(1080, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 39, 'OT', 'Ba-anh-ha-nan, con trai của A-cha-bô, qua đời; Ha-đa lên ngôi vua thay người. Tên thành người là Ba-u. Vợ người là Mê-hê-ta-bê-ên, con gái của Mát-rết, con gái của Mê-xa-háp.'),
(1081, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 40, 'OT', 'Còn đây là các danh hiệu của các tộc trưởng thuộc dòng họ Ê-sau, theo các chi tộc và các nơi xứ sở của họ, theo các danh hiệu của họ: tộc trưởng Thim-na, tộc trưởng Anh-va, tộc trưởng Giê-hết,'),
(1082, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 41, 'OT', 'trưởng tộc Ô-hô-li-ba-ma, trưởng tộc Ê-la, trưởng tộc Phi-nôn,'),
(1083, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 42, 'OT', 'Trưởng tộc Kê-na, trưởng tộc Thê-man, trưởng tộc Mép-xa,'),
(1084, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 36, 43, 'OT', 'Các trưởng tộc Mác-đi-ên, trưởng tộc Y-ram. Đó là các trưởng tộc của Ê-đôm, theo các nơi ở của họ trong xứ sở cơ nghiệp của họ. Chính Ê-sau là tổ phụ của Ê-đôm.'),
(1085, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 1, 'OT', 'Gia-cốp sống tại xứ mà cha mình đã kiều ngụ, là xứ Ca-na-an.'),
(1086, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 2, 'OT', 'Đây là dòng dõi của Gia-cốp: Giô-sép, khi được mười bảy tuổi, chăn chiên cùng các anh mình; cậu là người trẻ tuổi, cùng làm việc với các con trai của Bi-la và các con trai của Xinh-ba, vợ của cha cậu. Giô-sép đem tin xấu về các anh mình đến cho cha.'),
(1087, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 3, 'OT', 'Y-sơ-ra-ên yêu thương Giô-sép hơn tất cả các con trai mình, vì người là con của tuổi già; và người làm cho người một áo dài nhiều màu.'),
(1088, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 4, 'OT', 'Các anh nhìn thấy cha mình yêu Giô-sép hơn tất cả các anh em khác, nên họ ghét người ấy, và không thể nói với người ấy lời nào cách hòa nhã.'),
(1089, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 5, 'OT', 'Giô-sép nằm chiêm bao, rồi thuật lại cho các anh mình nghe; và họ lại càng ghét ông thêm.'),
(1090, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 6, 'OT', 'Hắn nói với họ: Hãy nghe tôi kể điềm chiêm bao mà tôi đã mơ:'),
(1091, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 7, 'OT', 'Này, chúng ta đang bó lúa giữa đồng, và này, bó lúa của tôi đứng thẳng lên, và này, bó lúa các anh đến vây quanh mà sấp mình xuống trước bó lúa tôi.'),
(1092, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 8, 'OT', 'Các anh chàng nói với chàng rằng: "Ngươi định cai trị chúng ta sao? Ngươi định thống trị chúng ta sao?" Và họ càng ghét chàng hơn nữa vì những giấc mơ và những lời nói của chàng.'),
(1093, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 9, 'OT', 'Giô-sép nằm chiêm bao một giấc mơ nữa, rồi thuật lại cho các anh mình rằng: Nầy, tôi lại nằm chiêm bao và thấy mặt trời, mặt trăng cùng mười một ngôi sao đều cúi mình xuống lạy tôi!'),
(1094, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 10, 'OT', 'Ông kể lại chiêm bao ấy cho cha mình và các anh mình; rồi cha ông quở trách ông và nói: Chiêm bao này mà con đã chiêm bao là nghĩa gì? Ta, mẹ con và các anh con phải đến sấp mình xuống đất trước mặt con sao?'),
(1095, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 11, 'OT', 'Các anh ganh ghét chàng, còn cha thì ghi giữ lời ấy.'),
(1096, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 12, 'OT', 'Các anh của nó đi chăn chiên cho cha chúng tại Si-chem.'),
(1097, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 13, 'OT', 'Y-sơ-ra-ên nói với Giô-sép: "Các anh ngươi há chẳng đang chăn chiên tại Si-chem sao? Hãy đi, ta sẽ sai ngươi đến cùng họ." Và người nói với ông: "Này con đây."'),
(1098, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 14, 'OT', 'Y-sơ-ra-ên bảo Giô-sép: "Hãy đi, xem tình hình các anh con và tình trạng bầy chiên, rồi đem tin trở lại cho cha." Vậy người sai người đi từ trũng Hếp-rôn, và người đến Si-chem.'),
(1099, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 15, 'OT', 'Có một người gặp chàng, và nầy, chàng đang đi lạc trong đồng ruộng; người ấy hỏi chàng rằng: Ngươi tìm gì?'),
(1100, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 16, 'OT', 'Nói rằng: Tôi đang tìm các anh tôi. Xin hãy chỉ cho tôi biết họ đang chăn chiên ở đâu.'),
(1101, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 17, 'OT', 'Người ấy nói: "Họ đã đi khỏi đây, vì tôi nghe họ nói: ''Chúng ta hãy đi đến Đô-ta-in.'' Vậy Giô-sép đi theo các anh mình, và tìm gặp họ tại Đô-ta-in."'),
(1102, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 18, 'OT', 'Chúng thấy cậu từ đằng xa, và trước khi cậu đến gần chúng, thì đã lập mưu giết cậu.'),
(1103, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 19, 'OT', 'Bọn họ nói với nhau rằng: Kìa, kẻ mơ mộng kia đến!'),
(1104, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 20, 'OT', 'Bây giờ, hãy đến, giết nó đi, rồi quăng nó xuống một trong những cái hố này; và chúng ta sẽ nói: Một thú dữ đã ăn nuốt nó; rồi xem những giấc mơ của nó sẽ ra sao.'),
(1105, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 21, 'OT', 'Ru-bên nghe thấy, bèn cứu người khỏi tay các anh mình, mà nói rằng: Chúng ta chớ giết mạng sống người.'),
(1106, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 22, 'OT', 'Ru-bên nói với họ: "Đừng làm đổ máu ra; hãy ném nó xuống cái hố này trong đồng vắng, nhưng tay các anh đừng tra vào nó, để tôi cứu nó khỏi tay họ, rồi trả nó về cho cha nó."'),
(1107, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 23, 'OT', 'Khi Giô-sép đến cùng các anh mình, thì các anh lột áo của Giô-sép, tức là áo dài có nhiều màu mà người đang mặc,'),
(1108, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 24, 'OT', 'họ bắt lấy chàng, rồi quăng xuống hố; hố thì khô, không có nước.'),
(1109, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 25, 'OT', 'Họ ngồi xuống ăn bánh, ngước mắt lên và nhìn thấy, nầy, một đoàn người Ích-ma-ên từ Ga-la-át đi đến; các con lạc đà của họ chở đầy nhựa thơm, thuốc trầm hương và nhựa đậu sống, đang đi xuống Ai-cập.'),
(1110, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 26, 'OT', 'Giu-đa nói cùng các anh em mình rằng: Lợi ích gì nếu ta giết em ta và giấu máu người?'),
(1111, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 27, 'OT', 'Hãy đi, bán nó cho người Ích-ma-ên, và tay chúng ta chớ giơ ra chống nó; vì nó là anh em, là huyết thống của chúng ta. Các anh em bèn nghe theo lời người ấy.'),
(1112, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 28, 'OT', 'Các người Ma-đi-an là thương gia đi ngang qua, bèn kéo Giô-sép lên khỏi hầm, rồi bán Giô-sép cho người Ích-ma-ên với hai mươi miếng bạc; và người Ích-ma-ên đem Giô-sép sang Ai Cập.'),
(1113, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 29, 'OT', 'Ru-bên trở lại nơi cái hố, thì thấy Giô-sép không còn ở trong hố nữa, bèn xé áo mình,'),
(1114, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 30, 'OT', 'liền trở về cùng các anh mình và nói: Đứa trẻ không còn ở đó! Còn tôi, tôi sẽ đi đâu đây?'),
(1115, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 31, 'OT', 'Họ lấy áo của Giô-sép, giết một con dê đực, rồi nhúng áo vào máu.'),
(1116, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 32, 'OT', 'Gởi cái áo sọc đó đi và đem đến cho cha mình, rồi nói rằng: "Chúng tôi tìm được cái này; xin hãy xem kỹ áo của con trai ngài có phải là áo này không."'),
(1117, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 33, 'OT', 'Gia-cốp nhìn áo đó và nói: "Áo của con trai ta đây! Một thú dữ đã nuốt nó rồi! Giô-sép chắc hẳn đã bị xé xác!"'),
(1118, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 34, 'OT', 'Gia-cốp xé rách áo mình, đặt bao lên nơi hông mình, và than khóc cho con trai mình nhiều ngày.'),
(1119, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 35, 'OT', 'Tất cả các con trai và các con gái của người đứng dậy để an ủi người, nhưng người từ chối không chịu được an ủi, và người nói: "Chính ta sẽ đi xuống cùng con ta, người đã chết, trong tang tóc đến âm phủ!" Cha của Giô-sép khóc than người như vậy.'),
(1120, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 37, 36, 'OT', 'Các người Ma-đi-an đã bán chàng cho người Ai-cập, là Phô-ti-pha, hoạn quan của Pha-ra-ôn, quản gia các đầu bếp.'),
(1121, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 38, 1, 'OT', 'Bấy giờ, Giu-đa rời các anh em mình, đi xuống đến cùng một người A-đu-lam, tên là Hi-ra.'),
(1122, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 38, 2, 'OT', 'Tại đó, Giu-đa thấy con gái của một người Ca-na-an, tên người ấy là Su-a, bèn cưới nàng làm vợ và ăn ở cùng nàng.'),
(1123, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 38, 3, 'OT', 'Bà thọ thai, sinh được một con trai, và đặt tên nó là Ê-rơ.'),
(1124, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 38, 4, 'OT', 'Bà thọ thai lần nữa, sinh được một con trai và đặt tên nó là Ô-nan.'),
(1125, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 38, 5, 'OT', 'Bà lại sanh thêm một con trai nữa, đặt tên nó là Sê-la; và nó sinh ra tại Kê-xíp.'),
(1126, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 38, 6, 'OT', 'Giu-đa cưới một người vợ cho Ê-rơ, con trai đầu lòng của mình, và tên người vợ ấy là Ta-ma.'),
(1127, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 38, 7, 'OT', 'Ê-rơ, con cả của Giu-đa, là ác trước mặt Đức Giê-hô-va, nên Đức Giê-hô-va giết người đi.'),
(1128, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 38, 8, 'OT', 'Giu-đa bảo Ô-nan rằng: "Hãy đến cùng vợ anh con, cùng nằm với nàng như luật em chồng, để nối dòng dõi cho anh con."'),
(1129, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 38, 9, 'OT', 'Ô-nan biết rằng dòng dõi sẽ không thuộc về mình, nên mỗi khi vào cùng vợ anh trai, thì làm đổ xuống đất, để không cho dòng dõi nào ra đời cho anh.'),
(1130, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 38, 10, 'OT', 'Điều người làm khiến Đức Giê-hô-va lấy làm xấu hổ, nên Ngài cũng khiến người ấy chết.'),
(1131, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 38, 11, 'OT', 'Giu-đa nói với Ta-ma, con dâu mình: "Hãy về sống như một góa phụ tại nhà cha ngươi, cho đến khi Sê-la, con trai ta, lớn lên"; vì người nói: "Kẻo nó cũng chết như hai anh nó." Vậy Ta-ma đi về và sống tại nhà cha mình.'),
(1132, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 38, 12, 'OT', 'Lâu ngày sau, con gái của Su-a, vợ Giu-đa, qua đời. Giu-đa bèn nguôi nỗi buồn, rồi đi lên Thim-na cùng với Hi-ra, bạn mình, người A-đu-lam, đến nơi những người đang hớt lông chiên của mình.'),
(1133, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 38, 13, 'OT', 'Người ta báo cho Ta-ma biết mà rằng: Nầy, cha chồng ngươi đang lên Thim-na để xén lông chiên của người.'),
(1134, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 38, 14, 'OT', 'Bà cởi bỏ những áo tang của mình, lấy khăn trùm đầu che mặt và phủ kín mình lại, rồi ngồi ở lối vào Ê-naim, dọc đường đi đến Thim-na; vì bà thấy rằng Sê-la đã lớn lên rồi, nhưng bà không được gả cho ông làm vợ.'),
(1135, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 38, 15, 'OT', 'Giu-đa thấy nàng, liền nghĩ là một gái điếm, vì nàng che khuất mặt.'),
(1136, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 38, 16, 'OT', 'Liền rẽ vào bên đường mà nói: "Xin hãy cho phép tôi vào cùng bà, vì tôi không biết bà là con dâu ông." Bà đáp: "Ông sẽ cho tôi gì để ông được vào cùng tôi?"'),
(1137, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 38, 17, 'OT', 'Ta sẽ gởi cho nàng một con dê con trong bầy chiên của ta, nàng nói: Nếu người không đưa của tin trước, cho đến chừng nào người gởi con dê đó đến cho tôi, tôi sẽ không chịu.'),
(1138, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 38, 18, 'OT', 'Người nói: Ta sẽ cho ngươi của tin gì? Cô đáp: Con dấu của anh, dây chỉ và cây gậy mà anh đang cầm trong tay. Người liền đưa cho cô những thứ đó, rồi vào cùng cô, và cô thụ thai vì người.'),
(1139, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 38, 19, 'OT', 'Bà đứng dậy, đi đi, cất chiếc khăn choàng khỏi mình, và mặc lại quần áo goá bụa.'),
(1140, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 38, 20, 'OT', 'Giu-đa sai bạn mình là người A-đu-lam mang một con dê con đến để lấy lại vật tin nơi tay người đàn bà, nhưng không tìm thấy nàng.'),
(1141, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 38, 21, 'OT', 'Người hỏi các người ở nơi ấy rằng: "Người đàn bà điếm mà ta thấy ở vệ đường nay đâu rồi?" Họ đáp: "Ở đây không có người đàn bà điếm nào cả."'),
(1142, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 38, 22, 'OT', 'Rồi người trở về cùng Giu-đa và nói: "Tôi đã không tìm thấy nàng; hơn nữa, những người ở đó cũng nói: ''Ở đây không hề có một kỵ nữ nào.''"'),
(1143, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 38, 23, 'OT', 'Giu-đa nói: "Hãy để cho nàng giữ lấy của tin đó, kẻo chúng ta bị sỉ nhục. Nầy, ta đã sai con dê đực đến, mà ngươi không tìm thấy nàng."'),
(1144, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 38, 24, 'OT', 'Khoảng ba tháng sau, người ta báo cho Giu-đa rằng: "Ta-ma, con dâu ông, đã phạm tội dâm dục, và nay nàng mang thai bởi sự dâm dục." Giu-đa nói: "Hãy dẫn nàng ra, để nàng bị thiêu chết."'),
(1145, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 38, 25, 'OT', 'Khi nàng bị dẫn ra ngoài, thì sai đến cha chồng mình mà rằng: "Tôi mang thai bởi người mà những vật nầy là của người đó"; và nàng nói: "Xin hãy nhận biết xem, chiếc ấn, dây chỉ và cây gậy nầy là của ai?"'),
(1146, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 38, 26, 'OT', 'Giu-đa nhận biết các món đồ ấy, bèn nói: "Cô ấy công bình hơn ta, vì ta đã không giao Sê-la, con trai ta, cho nàng." Và người không còn ăn ở cùng nàng nữa.'),
(1147, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 38, 27, 'OT', 'Đến kỳ sinh nở, nầy, trong bụng nàng có đôi sinh đôi.'),
(1148, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 38, 28, 'OT', 'Khi cô ấy sinh nở, đứa trẻ thò tay ra, và bà đỡ lấy, buộc một sợi chỉ đỏ quanh tay nó, nói rằng: "Đứa này ra trước."'),
(1149, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 38, 29, 'OT', 'Khi nó rút tay ra, thì nầy, anh nó liền ra; bà đỡ nói: "Sao ngươi xé rách ra như thế!" Vậy người ta đặt tên nó là Phê-rết.'),
(1150, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 38, 30, 'OT', 'Sau đó, em trai nó ra, là đứa nơi tay có sợi chỉ đỏ, và người ta đặt tên nó là Sê-rách.'),
(1151, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 39, 1, 'OT', 'Giô-sép bị đưa xuống Ai Cập, và Phô-ti-pha, một người Ai Cập, quan trưởng các thị vệ của Pha-ra-ôn, đã mua ông từ tay những người Ích-ma-ên đã mang ông đến đó.'),
(1152, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 39, 2, 'OT', 'Đức Giê-hô-va ở cùng Giô-sép, và người là một người thạnh lợi, và người ở trong nhà chủ mình là người Ê-díp-tô.'),
(1153, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 39, 3, 'OT', 'Chủ thấy Đức Giê-hô-va ở cùng người và mọi việc người làm, Đức Giê-hô-va khiến thành công nơi tay người.'),
(1154, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 39, 4, 'OT', 'Giô-sép được ơn trước mặt chủ mình, và phục sự chủ; chủ đặt người cai quản nhà mình, và trao mọi điều mình có vào tay người.'),
(1155, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 39, 5, 'OT', 'Từ khi người đặt Giô-sép cai quản trong nhà mình và trên mọi vật thuộc về mình, thì Đức Giê-hô-va ban phước cho nhà người Ai-cập vì cớ Giô-sép; và phước của Đức Giê-hô-va ở trên mọi vật thuộc về người, cả trong nhà lẫn ngoài đồng ruộng.'),
(1156, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 39, 6, 'OT', 'Người giao hết mọi điều thuộc về mình trong tay Giô-sép, và chẳng biết chi cùng người, ngoại trừ phần bánh mà người ăn. Còn Giô-sép thì có vẻ đẹp hình thể và đẹp trai.'),
(1157, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 39, 7, 'OT', 'Sau các việc ấy, vợ chủ của Giô-sép đưa mắt nhìn Giô-sép và nói: Hãy nằm với tôi.'),
(1158, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 39, 8, 'OT', 'Người từ chối và nói với vợ chủ mình rằng: "Nầy, chủ tôi không biết chi về việc nhà với tôi, và mọi vật người có, người đã trao vào tay tôi."'),
(1159, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 39, 9, 'OT', 'Người không lớn hơn tôi trong nhà này, và chẳng giữ lại điều gì khỏi tôi, ngoại trừ chính mình ngươi, vì ngươi là vợ của chủ tôi. Vậy thì tôi làm sao có thể làm điều ác lớn như thế này và phạm tội cùng Đức Chúa Trời được?'),
(1160, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 39, 10, 'OT', 'Mỗi ngày người đàn bà ấy đều dỗ dành Giô-sép, nhưng người không nghe theo lời nàng để nằm cùng hay ở cùng nàng.'),
(1161, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 39, 11, 'OT', 'Vào ngày đó, Giô-sép vào nhà để làm việc của mình, và không có một người nào trong các đầy tớ của nhà ở đó trong nhà.'),
(1162, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 39, 12, 'OT', 'Thì người vội nắm lấy áo chàng mà nói: "Hãy nằm với tôi!" Nhưng chàng liền bỏ lại áo trong tay người mà chạy trốn ra ngoài.'),
(1163, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 39, 13, 'OT', 'Khi người thấy áo chàng để lại trong tay mình, và chàng đã chạy trốn ra ngoài,'),
(1164, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 39, 14, 'OT', 'bèn gọi những người trong nhà mình mà nói với họ rằng: Hãy xem, người ta đã đem một người Hê-bơ-rơ đến để chế nhạo chúng ta; người ấy đã vào gần tôi để nằm cùng tôi, nhưng tôi đã kêu lớn tiếng.'),
(1165, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 39, 15, 'OT', 'Vừa khi nó nghe ta cất tiếng kêu la, thì bỏ áo lại bên ta, chạy trốn ra ngoài.'),
(1166, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 39, 16, 'OT', 'Người bèn để áo của Giô-sép bên mình, đợi khi chủ của người ấy về nhà.'),
(1167, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 39, 17, 'OT', 'Rồi cô nói với chủ mình y như những lời ấy, rằng: Thằng tôi mọi Hê-bơ-rơ mà ông đã đem về nhà để nhạo báng tôi đã đến gần tôi.'),
(1168, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 39, 18, 'OT', 'Nhưng khi tôi cất tiếng kêu lên và kêu cứu, thì người ấy bỏ áo mình lại bên tôi và chạy trốn ra ngoài.'),
(1169, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 39, 19, 'OT', 'Khi chủ của Giô-sép nghe lời vợ nói với mình rằng: "Chính kẻ tôi tớ ông đã làm cho tôi điều như vậy," thì cơn thịnh nộ của người bùng lên.'),
(1170, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 39, 20, 'OT', 'Ông chủ của Giô-sép bắt ông và giao ông vào nhà ngục, nơi những người phạm tội của vua bị giam giữ. Vậy, ông ở đó trong nhà ngục.'),
(1171, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 39, 21, 'OT', 'Đức Giê-hô-va ở cùng Giô-sép và làm ơn cho người, khiến cho được ơn trước mắt viên quản ngục.'),
(1172, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 39, 22, 'OT', 'Chúa của ngục giam trao vào tay Giô-sép mọi kẻ bị giam trong ngục; và mọi việc phải làm tại đó, chính người làm.'),
(1173, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 39, 23, 'OT', 'Chủ ngục không kiểm soát bất cứ điều gì trong tay Giô-sép, vì Đức Giê-hô-va ở cùng người, và mọi việc người làm thì Đức Giê-hô-va khiến thành công.'),
(1174, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 40, 1, 'OT', 'Sau các việc ấy, quan quản lý rượu của vua Ai Cập và quan làm bánh đã phạm tội đối với chủ mình là vua Ai Cập.'),
(1175, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 40, 2, 'OT', 'Pha-ra-ôn nổi giận cùng hai hoạn quan của mình, quan coi việc uống và quan coi việc nướng bánh.'),
(1176, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 40, 3, 'OT', 'Rồi người ta giao họ vào tay quản ngục, giam trong nhà tù, nơi Giô-sép bị giam giữ.'),
(1177, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 40, 4, 'OT', 'Quan tổng quản các thợ nấu ăn giao phó Giô-sép ở cùng họ, và người phục vụ họ; họ sống trong tù một thời gian.'),
(1178, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 40, 5, 'OT', 'Hai người, quan tửu chánh và quan thượng thiện của vua Ai Cập đang bị giam trong ngục, cùng chiêm bao một giấc mơ trong một đêm, mỗi người một giấc mơ theo cách giải của mình.'),
(1179, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 40, 6, 'OT', 'Sáng hôm sau, Giô-sép đến cùng họ, thấy họ đang buồn bực,'),
(1180, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 40, 7, 'OT', 'Ông hỏi các hoạn quan của Pha-ra-ôn đang cùng ông bị giam trong nhà tù của chủ ông rằng: "Hôm nay tại sao sắc mặt các quan lại buồn rầu vậy?"'),
(1181, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 40, 8, 'OT', 'Họ nói với người: "Chúng tôi chiêm bao một giấc mơ, nhưng không có ai giải nghĩa. Giô-sép đáp: "Lẽ nào giải nghĩa chiêm bao không phải do nơi Đức Chúa Trời? Vậy hãy thuật lại cho tôi nghe."'),
(1182, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 40, 9, 'OT', 'Quan tửu chánh thuật lại điềm chiêm bao của mình cho Giô-sép, và nói với người rằng: "Trong lúc chiêm bao, tôi thấy một cây nho ở trước mặt tôi."'),
(1183, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 40, 10, 'OT', 'và trên cây nho có ba nhánh; nó đâm chồi, nụ hoa trổ ra, chùm nho của nó trổ trái nho.'),
(1184, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 40, 11, 'OT', 'Tay tôi cầm chén của Pha-ra-ôn; tôi hái những trái nho, vắt nước vào chén của Pha-ra-ôn, rồi trao chén ấy vào tay Pha-ra-ôn.'),
(1185, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 40, 12, 'OT', 'Giô-sép nói với người ấy: "Đây là lời giải nghĩa của chiêm bao: ba cái chòm nho là ba ngày.'),
(1186, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 40, 13, 'OT', 'Trong ba ngày nữa, Pha-ra-ôn sẽ ngước đầu quan lên và phục chức quan lại như xưa, quan sẽ trao chén của Pha-ra-ôn vào tay người như thể thức cũ mà quan đã từng rót cho người uống.'),
(1187, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 40, 14, 'OT', 'Nhưng khi quan được may mắn, xin nhớ đến tôi và làm ơn với tôi, hãy nhắc tôi với Pha-ra-ôn để tôi được ra khỏi cái nhà này.'),
(1188, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 40, 15, 'OT', 'Vì tôi đã bị bắt cóc từ xứ của người Hê-bơ-rơ, và ngay tại đây tôi cũng chẳng làm điều gì mà họ lại ném tôi vào hầm ngục này.'),
(1189, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 40, 16, 'OT', 'Khi thấy quan quản lý rượu nói lời giải mộng được tốt, quan quản lý bánh cũng nói với Giô-sép: "Còn tôi, trong giấc mơ của tôi, tôi thấy trên đầu mình có ba cái giỏ bánh.'),
(1190, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 40, 17, 'OT', 'Trong giỏ cao nhất có đủ các món ăn của Pha-ra-ôn do thợ làm bánh hấp, và chim đáp xuống ăn các món đó từ giỏ trên đầu tôi.'),
(1191, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 40, 18, 'OT', 'Giô-sép đáp và nói: Đây là lời giải nghĩa của chiêm bao ấy: Ba giỏ là ba ngày.'),
(1192, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 40, 19, 'OT', 'Trong ba ngày nữa, Pha-ra-ôn sẽ nhấc đầu ngươi khỏi cổ ngươi và treo ngươi trên cây; chim trời sẽ ăn thịt ngươi khỏi thân ngươi.'),
(1193, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 40, 20, 'OT', 'Vào ngày thứ ba, là ngày sinh nhật của Pha-ra-ôn, người làm tiệc cho tất cả các tôi tớ mình, và nâng đầu quan trưởng các thợ uống rượu và đầu quan trưởng các thợ làm bánh giữa các tôi tớ mình.'),
(1194, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 40, 21, 'OT', 'Pha-ra-ôn phục hồi chức quan coi việc uống nước như trước, và đặt cái chén vào tay Pha-ra-ôn.'),
(1195, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 40, 22, 'OT', 'Còn quan quản lý các thợ làm bánh thì người ta treo lên, đúng như lời giải mộng của Giô-sép.'),
(1196, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 40, 23, 'OT', 'Quan coi việc uống chẳng nhớ đến Giô-sép nữa, và quên người đi.'),
(1197, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 1, 'OT', 'Hết hai năm trọn, Pha-ra-ôn nằm mộng thấy mình đứng bên bờ sông.'),
(1198, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 2, 'OT', 'Kìa, từ trong sông đi lên bảy con bò cái tốt lành về hình dáng và mập mạnh về thân thể, rồi chúng ăn cỏ trong đồng cỏ.'),
(1199, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 3, 'OT', 'Và nầy, bảy con bò khác đi lên sau chúng từ sông, xấu dạng và gầy guộc, và đứng gần các con bò trước trên bờ sông.'),
(1200, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 4, 'OT', 'Bảy con bò xấu dạng và gầy ốm đã nuốt bảy con bò đẹp và mập mạp; rồi Pha-ra-ôn thức giấc.'),
(1201, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 5, 'OT', 'Vua ngủ lại và chiêm bao lần thứ hai, nầy bảy bông lúa trĩu, tốt tươi, mọc trên một cây rạ.'),
(1202, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 6, 'OT', 'Và nầy, bảy gié lúa khác, gầy và bị gió nóng thổi háp, mọc theo sau bảy gié lúa ấy.'),
(1203, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 7, 'OT', 'Bảy gié lúa lép nuốt chửng bảy gié lúa mập mạp và đầy đủ. Pha-ra-ôn thức dậy, và kìa, đó chỉ là một giấc mơ.'),
(1204, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 8, 'OT', 'Sáng hôm sau, lòng vua bồn chồn lo lắng, bèn sai đòi tất cả các thầy phù thủy và các bậc khôn ngoan của Ai Cập đến; Pha-ra-ôn thuật lại cho họ về giấc mơ của mình, nhưng không ai giải được các giấc mơ ấy cho Pha-ra-ôn.'),
(1205, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 9, 'OT', 'Quan tửu chánh tâu cùng Pha-ra-ôn rằng: Chính hôm nay tôi nhớ lại tội lỗi mình.'),
(1206, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 10, 'OT', 'Pha-ra-ô nổi giận cùng các tôi tớ của người, và người đã giao tôi vào nơi giam giữ tại nhà của quan trưởng các thợ nấu ăn, cả tôi lẫn quan trưởng các thợ làm bánh.'),
(1207, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 11, 'OT', 'Chúng tôi chiêm bao trong một đêm, tôi và ông ấy, mỗi người theo cách giải nghĩa chiêm bao của mình, chúng tôi đã chiêm bao.'),
(1208, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 12, 'OT', 'Tại đó, cùng chúng tôi có một người trẻ tuổi, là người Hê-bơ-rơ, tôi tớ của quan trưởng các vệ sĩ; chúng tôi thuật lại cho anh ta những giấc mơ của mình, và anh ta giải thích các giấc mơ cho chúng tôi, mỗi người theo giấc mơ của mình.'),
(1209, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 13, 'OT', 'Đúng như điều mà anh ta đã giải nghĩa cho chúng tôi, sự việc đã xảy ra như vậy: người ấy phục chức tôi lại, còn người kia thì bị treo.'),
(1210, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 14, 'OT', 'Pha-ra-ôn sai đi gọi Giô-sép; họ vội vã dẫn người ra khỏi hầm ngục, cạo râu tóc và thay quần áo cho người, rồi Giô-sép vào ra mắt Pha-ra-ôn.'),
(1211, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 15, 'OT', 'Pha-ra-ôn nói với Giô-sép: "Ta đã chiêm bao, nhưng không ai giải được điềm chiêm bao ấy. Ta đã nghe nói về ngươi, rằng ngươi nghe một điềm chiêm bao và có thể giải nó."'),
(1212, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 16, 'OT', 'Giô-sép đáp cùng Pha-ra-ôn rằng: Không phải bởi tôi; Đức Chúa Trời sẽ ban sự bình an cho Pha-ra-ôn.'),
(1213, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 17, 'OT', 'Pha-ra-ôn nói với Giô-sép: "Nầy, trong giấc chiêm bao ta đang đứng bên bờ sông."'),
(1214, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 18, 'OT', 'Và nầy, bảy con bò mập thịt và tốt hình dáng đi lên từ sông, và chúng ăn cỏ trong đồng cỏ.'),
(1215, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 19, 'OT', 'Và nầy, bảy con bò khác đi lên theo sau chúng, gầy guộc và xấu dạng cực kỳ, thịt rất tiều tụy; tôi chưa từng thấy những con bò như thế trong khắp đất Ai Cập về điều xấu.'),
(1216, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 20, 'OT', 'Bảy con bò gầy xấu đó đã nuốt bảy con bò mập mạp đầu tiên.'),
(1217, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 21, 'OT', 'rồi chúng đi vào trong bụng các con bò xấu đó, nhưng dường như chẳng ai biết là chúng đã đi vào trong bụng, vì hình dạng các con bò xấu đó vẫn như lúc ban đầu; rồi tôi tỉnh giấc.'),
(1218, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 22, 'OT', 'Tôi thấy trong giấc mơ của tôi, và nầy, bảy bông lúa trĩu nặng và tốt tươi mọc trên một cây lúa.'),
(1219, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 23, 'OT', 'Và nầy, bảy gié lúa khác, mảnh khảnh, héo quắt, bị gió nóng thiêu đốt, mọc lên sau các gié ấy.'),
(1220, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 24, 'OT', 'Bảy bông lúa gầy đã nuốt bảy bông lúa tốt; rồi ta nói cho các thầy bói, nhưng không ai giải thích cho ta.'),
(1221, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 25, 'OT', 'Giô-sép nói với Pha-ra-ôn: "Điềm chiêm bao của Pha-ra-ôn là một; Đức Chúa Trời đã tỏ cho Pha-ra-ôn điều Ngài sắp làm."'),
(1222, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 26, 'OT', 'Bảy con bò tốt là bảy năm; bảy bông lúa tốt cũng là bảy năm; đó là một điềm chiêm bao.'),
(1223, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 27, 'OT', 'Bảy con bò gầy ốm xấu xí lên theo sau chúng, ấy là bảy năm; và bảy bông lúa lép, bị cháy bởi gió nóng, ấy sẽ là bảy năm đói kém.'),
(1224, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 28, 'OT', 'Đây là điều ta đã nói với Pha-ra-ôn: Đức Chúa Trời đã làm cho Pha-ra-ôn thấy điều Ngài sắp thực hiện.'),
(1225, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 29, 'OT', 'Nầy, bảy năm dư dật lớn sẽ đến trong khắp đất Ai Cập.'),
(1226, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 30, 'OT', 'và bảy năm đói kém sẽ nổi lên sau đó, khiến cho mọi sự dư dật đều bị lãng quên trong đất Ai Cập, và cơn đói kém sẽ làm cho cả đất ấy hao mòn.'),
(1227, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 31, 'OT', 'Và sự no đủ sẽ không còn được biết đến trong đất, vì cơn đói kém sau đó sẽ rất nặng.'),
(1228, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 32, 'OT', 'Sự hiện điềm chiêm bao hai lần cho Pha-ra-ôn là vì việc đó đã được quyết định từ nơi Đức Chúa Trời, và Đức Chúa Trời sẽ mau chóng làm thành điều đó.'),
(1229, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 33, 'OT', 'Bây giờ, đức vua hãy tìm một người thông minh và khôn ngoan, rồi đặt người ấy cai trị trên đất Ai Cập.'),
(1230, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 34, 'OT', 'Pha-ra-ôn hãy làm và bổ nhiệm các quan chức trong cả đất nước, để thu một phần năm sản vật của đất Ai Cập trong bảy năm dư dật.'),
(1231, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 35, 'OT', 'Họ hãy thu góp tất cả lương thực của bảy năm tốt lành sắp tới, và hãy tích trữ lúa mì dưới quyền Pha-ra-ôn, làm lương thực dự trữ trong các thành, và hãy giữ kỹ.'),
(1232, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 36, 'OT', 'Thức ăn ấy sẽ được để dành làm kho dự trữ cho đất nước trong bảy năm đói kém sẽ xảy đến trong đất Ai Cập, hầu cho đất không bị tiêu diệt trong cơn đói kém.'),
(1233, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 37, 'OT', 'Lời ấy đẹp ý Pha-ra-ôn và mọi tôi tớ người.'),
(1234, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 38, 'OT', 'Pha-ra-ôn nói với các tôi tớ mình: "Trong vòng những người như thế này, ta há tìm được một người nào mà có thần của Đức Chúa Trời ở trong người đó sao?"'),
(1235, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 39, 'OT', 'Bấy giờ Pha-ra-ôn nói với Giô-sép: "Vì Đức Chúa Trời đã cho ngươi biết tất cả những điều nầy, thì chẳng ai khôn ngoan và thông sáng như ngươi."'),
(1236, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 40, 'OT', 'Ngươi sẽ cai trị nhà ta, và toàn thể dân ta sẽ vâng theo lời ngươi; chỉ ngôi vua là ta lớn hơn ngươi.'),
(1237, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 41, 'OT', 'Pha-ra-ôn nói với Giô-sép: Hãy xem, ta đã đặt ngươi làm người quản trị trên khắp đất Ai Cập.'),
(1238, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 42, 'OT', 'Vua Pha-ra-ôn cởi ấn triện khỏi tay mình, đặt lên tay Giô-sép, mặc cho người áo bằng vải gai mịn, và đặt vòng vàng quanh cổ người.'),
(1239, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 43, 'OT', 'Người ta cho Giô-sép ngồi trên xe thứ hai mà vua có, và người ta kêu lên trước mặt người rằng: "Quì xuống!" Như vậy, người ta đặt người cai trị trên khắp đất Ai Cập.'),
(1240, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 44, 'OT', 'Pha-ra-ôn nói với Giô-sép: Ta là Pha-ra-ôn, và không ai được phép giơ tay hay đưa chân trong khắp đất Ai Cập mà không có ngươi.'),
(1241, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 45, 'OT', 'Pha-ra-ôn đặt tên Giô-sép là Xa-phơ-nát-Pha-nê-ách, và ban cho người Aùch-nát, con gái của Phô-ti-phê-ra, thầy tế lễ của thành Oân, làm vợ; rồi Giô-sép ra đi khắp đất Ai Cập.'),
(1242, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 46, 'OT', 'Giô-sép lúc ra trước mặt Pha-ra-ôn, vua nước Ai Cập, thì được ba mươi tuổi. Rồi Giô-sép từ tạ Pha-ra-ôn mà đi qua khắp đất Ai Cập.'),
(1243, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 47, 'OT', 'Đất liền sanh sản ra đầy lúa mì trong bảy năm được mùa dư dật.'),
(1244, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 48, 'OT', 'Giô-sép thâu góp tất cả lương thực của bảy năm mà các ruộng ở đất Ai Cập sản xuất, rồi chứa lương thực vào các thành; lương thực do các ruộng quanh mỗi thành sản xuất thì được chứa vào chính thành ấy.'),
(1245, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 49, 'OT', 'Vậy, Giô-sép thâu góp lúa mì nhiều như cát nơi bờ biển, rất nhiều vô kể, đến nỗi người ta thôi không đếm nữa vì không thể đếm được.'),
(1246, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 50, 'OT', 'Trước khi đến năm đói kém, Aùch-nát, con gái Phô-ti-phê-ra, thầy tế lễ thành Oân, đã sanh cho Giô-sép hai con trai.'),
(1247, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 51, 'OT', 'Giô-sép đặt tên đứa con đầu lòng là Ma-na-se, vì nói rằng: Đức Chúa Trời đã khiến ta quên hết mọi cực nhọc của ta và cả nhà cha ta.'),
(1248, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 52, 'OT', 'Đứa thứ hai thì người đặt tên là Eùp-ra-im, vì nói rằng: Đức Chúa Trời làm cho tôi được hưng vượng trong xứ mà tôi bị khốn khổ.'),
(1249, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 53, 'OT', 'Bảy năm dư dật trong xứ Ai Cập đã qua,'),
(1250, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 54, 'OT', 'bảy năm đói kém bắt đầu xảy đến, y như lời Giô-sép đã nói; và có sự đói kém trong khắp các xứ, nhưng trong cả đất Ai Cập thì có bánh.'),
(1251, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 55, 'OT', 'Cả đất Ê-díp-tô bị đói, dân chúng kêu khóc cùng Pha-ra-ôn xin lương thực. Pha-ra-ôn nói với toàn dân Ê-díp-tô: "Hãy đi đến Giô-sép, và làm theo mọi điều người sẽ bảo các ngươi."'),
(1252, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 56, 'OT', 'Khi nạn đói kém xảy ra khắp mọi nơi trên đất, thì Giô-sép mở tất cả các kho chứa để bán cho dân Ai-cập; và nạn đói kém ngày càng gia tăng trong đất Ai-cập.'),
(1253, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 41, 57, 'OT', 'Mọi nơi trên đất đều đổ về Ai Cập để mua lương thực nơi Giô-sép, vì nạn đói ngày càng nghiêm trọng khắp đất.'),
(1254, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 1, 'OT', 'Gia-cốp thấy ở xứ Ai Cập có lúa bán ra, bèn nói cùng các con trai mình rằng: Sao các con nhìn nhau ngơ ngẩn vậy?'),
(1255, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 2, 'OT', 'Bấy giờ người nói: Nầy, ta nghe tin ở xứ Ai Cập có thóc bán; hãy xuống đó mua thóc cho chúng ta, hầu cho chúng ta sống và không chết!'),
(1256, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 3, 'OT', 'Mười người anh của Giô-sép xuống đó để mua lương thực tại Ai Cập.'),
(1257, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 4, 'OT', 'Gia-cốp không cho Bên-gia-min, em trai của Giô-sép, đi cùng các anh mình, vì người nói: "Lẽ nào tai họa sẽ xảy đến cho nó?"'),
(1258, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 5, 'OT', 'Các con trai của Y-sơ-ra-ên đi đến để mua lúa giữa những người đến, vì xứ Ca-na-an bị đói.'),
(1259, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 6, 'OT', 'Giô-sép là người cai trị toàn cõi đất, chính người bán lương thực cho mọi dân trong xứ; các anh của Giô-sép đến, cúi mặt xuống đất mà lạy người.'),
(1260, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 7, 'OT', 'Giô-sép thấy các anh mình, nhận biết họ, nhưng giả làm người lạ, nói với họ cách nghiêm khắc và hỏi: "Các ngươi từ đâu đến?" Họ đáp: "Từ đất Ca-na-an đến để mua lương thực."'),
(1261, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 8, 'OT', 'Giô-sép nhìn biết các anh mình, nhưng các anh chẳng nhận ra ông.'),
(1262, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 9, 'OT', 'Giô-sép nhớ lại những điều chiêm bao mà ông đã chiêm bao về các anh em mình, rồi nói với họ rằng: Các ngươi là thám tử, đến để xem những chỗ yếu của đất nước này.'),
(1263, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 10, 'OT', 'Họ thưa với ông: "Thưa chúa, không phải vậy; các tôi tớ ngài đến để mua lương thực."'),
(1264, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 11, 'OT', 'Chúng tôi đều là con trai của một người cha; chúng tôi là những người ngay thẳng, thưa ông: các đầy tớ của ông chẳng phải là những kẻ do thám.'),
(1265, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 12, 'OT', 'Người nói với họ: Không phải vậy; các ngươi đến để dò xét những nơi yếu kém của đất nước này.'),
(1266, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 13, 'OT', 'Chúng tôi, những kẻ tôi tớ của ngài, là mười hai anh em, con trai của một người cha, ở đất Ca-na-an; và nầy, người con út hiện ở với cha chúng tôi, còn người kia thì không còn.'),
(1267, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 14, 'OT', 'Giô-sép nói với họ: "Đúng như ta đã nói với các ngươi: Các ngươi là những kẻ do thám."'),
(1268, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 15, 'OT', 'Nhân điều nầy, các ngươi sẽ được thử thách: Ta thề bằng mạng Pha-ra-ôn, nếu các ngươi ra khỏi đây mà em út các ngươi không đến đây cùng, thì sẽ không bao giờ ra khỏi được.'),
(1269, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 16, 'OT', 'Hãy sai một người trong các ngươi đi, đem em út các ngươi đến; còn các ngươi thì phải bị giam giữ, để thử xem lời các ngươi có thật hay không. Nếu không, Pha-ra-ôn hằng sống, các ngươi chắc chắn là thám tử.'),
(1270, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 17, 'OT', 'Giô-sép truyền giam họ trong ngục ba ngày.'),
(1271, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 18, 'OT', 'Đến ngày thứ ba, Giô-sép nói với họ: "Hãy làm điều nầy thì các ngươi sẽ sống, vì ta kính sợ Đức Chúa Trời."'),
(1272, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 19, 'OT', 'Nếu các ngươi thật lòng ngay thẳng, hãy để một người anh em các ngươi bị giam giữ trong ngục, còn các ngươi hãy đi mang thóc về nuôi sống gia đình mình.'),
(1273, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 20, 'OT', 'Hãy dẫn em út của các ngươi xuống đây cùng ta, thì lời các ngươi sẽ được xác nhận, và các ngươi sẽ không phải chết. Họ liền làm theo điều ấy.'),
(1274, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 21, 'OT', 'Họ nói với nhau: Thật vậy, chúng ta có tội với anh em mình, vì chúng ta đã thấy cảnh khốn khổ của anh em khi anh em nài xin chúng ta, mà chúng ta không chịu nghe; chính vì điều đó mà tai họa này đã giáng trên chúng ta.'),
(1275, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 22, 'OT', 'Ru-bên đáp cùng họ rằng: "Tôi há chẳng đã nói cùng các anh em rằng: ''Đừng phạm tội cùng đứa trẻ nầy'' sao? Nhưng các anh em không nghe; và nầy, huyết nó đang bị đòi hỏi."'),
(1276, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 23, 'OT', 'Họ không biết rằng Giô-sép đang nghe, vì có người thông dịch giữa họ.'),
(1277, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 24, 'OT', 'Giô-sép xây mặt qua chỗ khác mà khóc; rồi trở lại nói chuyện cùng họ, và bắt Si-mê-ôn trong vòng anh em mình, truyền trói lại trước mặt họ.'),
(1278, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 25, 'OT', 'Giô-sép ra lệnh, và người ta đổ đầy các bao của họ bằng lúa, trả lại tiền của mỗi người vào bao mình, rồi cấp lương thực cho họ dùng dọc đường. Người ta làm đúng như vậy cho họ.'),
(1279, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 26, 'OT', 'Chúng bèn khiêng thóc của mình chất lên các con lừa và ra đi khỏi đó.'),
(1280, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 27, 'OT', 'Tại quán trọ, một người anh mở bao của mình để lấy thức ăn cho lừa, thì thấy tiền của mình, và này, nó ở trong miệng bao của người ấy.'),
(1281, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 28, 'OT', 'mới nói với các anh em rằng: Tiền của tôi đã được trả lại, và đây, còn ở trong bị tôi nữa! Lòng các anh em bèn hoảng hốt, run sợ lẫn nhau mà rằng: Đức Chúa Trời đã làm điều nầy cho chúng ta là thể nào?'),
(1282, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 29, 'OT', 'Các anh em đến cùng Gia-cốp, cha mình, tại xứ Ca-na-an, và thuật lại cho ông biết mọi việc đã xảy đến cho mình, mà rằng:'),
(1283, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 30, 'OT', 'Người làm chủ xứ ấy nói với chúng tôi cách nghiêm khắc, và coi chúng tôi như gián điệp vào xứ.'),
(1284, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 31, 'OT', 'Chúng tôi tâu cùng người rằng: Chúng tôi là anh em, chúng tôi đâu phải là gián điệp.'),
(1285, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 32, 'OT', 'Chúng tôi là mười hai anh em, con trai của cha chúng tôi; một người thì không còn, và người út hiện nay đang ở với cha chúng tôi tại xứ Ca-na-an.'),
(1286, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 33, 'OT', 'Người làm chủ xứ bảo chúng tôi rằng: ''Như thế này, ta mới biết các ngươi là người ngay thật: Hãy để một người anh em các ngươi lại cùng ta, còn các ngươi thì hãy lấy lương thực đi về nuôi đói cho nhà các ngươi, rồi hãy đi.'''),
(1287, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 34, 'OT', 'Hãy dẫn em trai út của các ngươi đến cùng ta, để ta biết các ngươi không phải là thám tử, mà là người ngay thẳng; ta sẽ giao các anh em ngươi cho các ngươi, và các ngươi sẽ được buôn bán trong đất này.'),
(1288, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 35, 'OT', 'Chính khi họ đang đổ thóc ra khỏi bao, thì nầy, mỗi người thấy gói bạc của mình trong bao mình; họ và cha họ thấy các gói bạc của mình, thì đều sợ hãi.'),
(1289, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 36, 'OT', 'Gia-cốp, cha các anh, nói với họ: "Chính tôi bị mất các con trai mình! Giô-sép không còn, Si-mê-ôn cũng không còn, và bây giờ các anh muốn đem Bên-gia-min đi nữa sao? Tất cả những điều nầy đều đổ lại cho tôi!"'),
(1290, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 37, 'OT', 'Ru-bên nói cùng cha người rằng: Cha hãy giết hai đứa con trai tôi, nếu tôi không dẫn nó về cho cha; hãy giao nó cho tôi, tôi sẽ dẫn nó về cho cha.'),
(1291, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 42, 38, 'OT', 'Gia-cốp nói: Con trai ta sẽ không đi xuống với các con, vì anh nó đã chết, và chỉ còn một mình nó; nếu tai họa xảy đến cho nó trên đường các con đi, thì các con sẽ làm cho đầu bạc ta đau buồn xuống âm phủ.'),
(1292, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 1, 'OT', 'Vả lại, cơn đói kém trong xứ rất nặng.'),
(1293, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 2, 'OT', 'Khi họ đã ăn hết lương thực mình mang từ Ai Cập về, thì cha các người ấy bảo họ rằng: "Hãy đi mua thêm ít thực phẩm cho chúng ta."'),
(1294, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 3, 'OT', 'Giu-đa thưa cùng người rằng: Người ấy đã nghiêm nghị dặn chúng tôi rằng: Nếu em út các ngươi không đi xuống với các ngươi, thì các ngươi sẽ không được thấy mặt ta.'),
(1295, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 4, 'OT', 'Nếu cha cho phép em trai chúng tôi đi cùng chúng tôi, thì chúng tôi mới xuống Ai Cập mua lương thực cho cha được.'),
(1296, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 5, 'OT', 'Nếu ông không cho phép, chúng tôi sẽ không xuống, vì người ấy đã nói với chúng tôi: "Nếu các ngươi không mang em trai mình xuống, thì sẽ không được thấy mặt ta."'),
(1297, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 6, 'OT', 'Y-sơ-ra-ên nói: Sao các con làm hại ta như thế, mà nói cho người ấy biết các con còn có em nữa?'),
(1298, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 7, 'OT', 'Họ thưa rằng: Người ấy đã hỏi chúng tôi kỹ lưỡng về bản thân và về bà con chúng tôi, rằng: Thân-phụ các ngươi còn sống chăng? Các ngươi có còn một người anh em nào nữa không? Chúng tôi đã thuật lại cho người ấy theo đúng những lời hỏi đó. Làm sao chúng tôi biết được rằng người ấy sẽ nói: Hãy đem em các ngươi xuống đây?'),
(1299, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 8, 'OT', 'Giu-đa nói với Y-sơ-ra-ên, cha mình: "Xin cha hãy để cho đứa trẻ đi với con, để chúng ta đứng dậy đi, hầu cho chúng ta, cả cha, cả chúng con và các con trẻ của chúng con đều được sống và không chết."'),
(1300, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 9, 'OT', 'Tôi sẽ bảo lãnh cho nó; từ tay tôi, cha sẽ đòi lại nó. Nếu tôi không mang nó về và đặt nó trước mặt cha, thì suốt đời tôi sẽ mang tội cùng cha.'),
(1301, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 10, 'OT', 'Vì nếu không trì hoãn thì giờ đây chúng tôi đã đi và trở về hai lần rồi.'),
(1302, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 11, 'OT', 'Y-sơ-ra-ên, cha các người, nói: Nếu quả thật như thế, hãy làm điều này: Hãy lấy một ít sản vật tốt nhất của đất trong hành lý các ngươi, và mang xuống cho người ấy như của lễ: một ít nhựa thơm, một ít mật ong, nhựa thơm, dầu thơm, hạt dẻ và hạt hạnh nhân.'),
(1303, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 12, 'OT', 'Hãy cầm theo tay số tiền gấp đôi, và đem trả lại số tiền đã được đặt lại trong miệng bao các ngươi; có lẽ đó là sự nhầm lẫn.'),
(1304, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 13, 'OT', 'Hãy đem theo anh em các con mà đứng dậy, trở lại cùng người ấy.'),
(1305, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 14, 'OT', 'Nguyện Đức Chúa Trời toàn năng ban lòng thương xót cho các con trước mặt người ấy, khiến người thả em các con kia và Bên-gia-min về; còn ta, nếu phải mất con, thì ta đành chịu mất vậy!'),
(1306, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 15, 'OT', 'Các người ấy lấy của lễ, và đem theo một số tiền gấp đôi, rồi dẫn Bên-gia-min đi lên; họ chỗi dậy và xuống Ai-cập, rồi đứng trước mặt Giô-sép.'),
(1307, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 16, 'OT', 'Giô-sép thấy Bên-gia-min đi cùng anh em mình, liền nói với quản gia nhà mình: "Hãy dẫn những người này vào nhà, làm thịt một con vật và chuẩn bị sẵn sàng, vì những người này sẽ ăn trưa cùng tôi."'),
(1308, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 17, 'OT', 'Người ấy làm y như lời Giô-sép đã dặp; người ấy đưa những người ấy vào nhà của Giô-sép.'),
(1309, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 18, 'OT', 'Họ sợ hãi khi bị đưa vào nhà Giô-sép, và nói với nhau: "Chúng ta bị đưa đến đây vì số bạc đã được đặt lại trong bị của chúng ta từ đầu; họ định dùng điều đó để chống lại chúng ta, đổ lỗi cho chúng ta, rồi bắt chúng ta làm tôi mọi và chiếm đoạt cả lừa của chúng ta."'),
(1310, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 19, 'OT', 'Các anh em đến gần người quản lý nhà của Giô-sép và nói chuyện với người ấy ngay tại cửa nhà.'),
(1311, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 20, 'OT', 'thưa rằng: Thưa ông, xin hãy tha thứ cho chúng tôi! Chúng tôi đã xuống đây lần đầu để mua lương thực;'),
(1312, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 21, 'OT', 'Khi chúng tôi đến quán trọ và mở các bị của mình ra, thì nầy, tiền của mỗi người đều ở trong miệng bị, đúng theo trọng lượng; và chúng tôi đã mang tiền đó trở lại theo tay mình.'),
(1313, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 22, 'OT', 'Chúng tôi cũng mang theo bạc khác trong tay để mua lương thực; không biết ai đã để bạc của chúng tôi vào các bị.'),
(1314, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 23, 'OT', 'Hắn nói: Bình an cho các ngươi, đừng sợ! Đức Chúa Trời của các ngươi và Đức Chúa Trời của cha các ngươi đã ban kho tàng vào túi các ngươi; còn bạc các ngươi thì đã đến tay ta. Rồi hắn đưa Si-mê-ôn ra gặp họ.'),
(1315, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 24, 'OT', 'Người ấy đưa những người anh em vào nhà Giô-sép, rồi lấy nước cho họ rửa chân, và cho đồ ăn cho các lừa của họ.'),
(1316, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 25, 'OT', 'Họ sửa soạn của lễ, đợi khi Giô-sép đến vào buổi trưa, vì họ nghe nói mình sẽ ăn bữa tại đây.'),
(1317, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 26, 'OT', 'Vậy Giô-sép vào nhà, thì các anh em đem dâng cho người của lễ mình mang theo, và sấp mình xuống đất trước mặt người.'),
(1318, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 27, 'OT', 'Người hỏi thăm họ về sự bình an, rồi nói: "Người cha già mà các ngươi đã nói đến, ông ấy còn sống chăng?"'),
(1319, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 28, 'OT', 'Họ thưa: "Kẻ tôi tớ của ngài, cha chúng tôi, vẫn còn sống mạnh khỏe." Rồi họ cúi đầu và sấp mình xuống.'),
(1320, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 29, 'OT', 'Giô-sép ngước mắt lên và thấy Bên-gia-min, anh em mình, con trai của mẹ mình, thì nói: "Đây có phải là em trai út mà các ngươi đã nói với ta chăng?" Rồi nói tiếp: "Nguyện Đức Chúa Trời làm ơn cho con, hỡi con trai ta!"'),
(1321, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 30, 'OT', 'Giô-sép vội vàng đi ra vì lòng thương cảm em mình dấy lên, và Người tìm chỗ để khóc; Người vào phòng trong và khóc ở đó.'),
(1322, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 31, 'OT', 'Rửa mặt xong, đi ra ngoài, nén lòng lại và nói: "Hãy dọn cơm ra."'),
(1323, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 32, 'OT', 'Họ dọn cho Giô-sép ăn riêng, còn cho các anh em ông thì ăn riêng, và cho những người Ai Cập ăn cùng ông cũng ngồi riêng; vì người Ai Cập không thể ăn chung với người Hê-bơ-rơ, vì điều đó là điều gớm ghiếc đối với người Ai Cập.'),
(1324, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 33, 'OT', 'Các anh em ngồi trước mặt Giô-sép, người anh cả theo ngôi trưởng, người em út theo ngôi út; và những người đàn ông ấy nhìn nhau sửng sốt.'),
(1325, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 43, 34, 'OT', 'Giô-sép lấy các món ăn từ trước mặt mình mà dâng cho anh em mình; nhưng phần của Bên-gia-min thì nhiều hơn phần của những người kia năm lần; họ uống và say cùng người.'),
(1326, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 1, 'OT', 'Giô-sép truyền lịnh cho người quản gia của mình rằng: "Hãy đổ lương thực cho đầy các bị của những người ấy, tùy theo sức họ có thể mang được, và đặt tiền của mỗi người nơi miệng bị của người ấy."'),
(1327, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 2, 'OT', 'Quản gia hãy để cái chén bạc của ta vào miệng bao của người út, cùng với bạc mua lúa của người ấy. Quản gia bèn làm y như lời Giô-sép đã dặn.'),
(1328, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 3, 'OT', 'Sáng hôm sau, trời vừa tảng sáng, những người ấy cùng với các con lừa của họ được cho đi.'),
(1329, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 4, 'OT', 'Họ vừa ra khỏi thành, chưa đi xa, thì Giô-sép bảo người quản gia của mình: "Hãy đứng dậy, đuổi theo những người kia; khi đuổi kịp, hãy nói với họ: ''Sao các ngươi đền trả điều ác thay vì điều lành?''"'),
(1330, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 5, 'OT', 'Chẳng phải đây là cái chén mà chủ ta vẫn dùng để uống và dùng để bói sao? Các ngươi đã làm điều ác trong việc nầy.'),
(1331, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 6, 'OT', 'Quản gia đuổi kịp và nói với họ những lời này.'),
(1332, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 7, 'OT', 'Các anh thưa người rằng: "Chúa tại sao lại nói như thế? Các đầy tớ ngài chớ có làm điều như lời nầy!'),
(1333, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 8, 'OT', 'Nầy, chúng tôi đã đem bạc tìm được nơi miệng bao của chúng tôi từ xứ Ca-na-an mà trả lại cho ông; làm sao chúng tôi có thể trộm bạc hay vàng từ nhà chủ ông được?'),
(1334, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 9, 'OT', 'Kẻ nào trong các đầy tớ của ngài mà người ta tìm thấy chén này nơi nó, thì kẻ ấy phải chết; còn chúng tôi, chúng tôi sẽ trở thành tôi mọi cho ngài.'),
(1335, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 10, 'OT', 'Người ấy nói: Thật vậy, theo như lời các ngươi nói, thì chính như vậy: kẻ nào tìm thấy chén ở cùng, sẽ làm tôi tớ cho ta; còn các ngươi thì được xem là vô tội.'),
(1336, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 11, 'OT', 'Họ vội vàng hạ bao của mỗi người xuống đất và mở bao của mình ra.'),
(1337, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 12, 'OT', 'Quản gia tìm kiếm, từ bao của người lớn nhất mà bắt đầu, rồi đến bao của người nhỏ nhất mà thôi; và cái chén được tìm thấy trong bao của Bên-gia-min.'),
(1338, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 13, 'OT', 'Mỗi người xé áo mình, chất bao lúa lên lưng lừa, rồi cùng trở lại thành.'),
(1339, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 14, 'OT', 'Giu-đa cùng các anh em vào nhà Giô-sép, và người ấy vẫn còn ở đó; họ bèn sấp mình xuống đất trước mặt người.'),
(1340, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 15, 'OT', 'Giô-sép nói với họ: "Việc này các ngươi làm là việc gì vậy? Há chẳng biết rằng người như tôi đây có tài bói được sao?"'),
(1341, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 16, 'OT', 'Giu-đa nói: Chúng tôi sẽ nói gì cùng chúa tôi, và nói gì để minh bạch mình? Đức Chúa Trời đã tìm thấy tội lỗi của các đầy tớ Ngài. Nầy, chúng tôi đây, cả chúng tôi lẫn người mà chén đã được tìm thấy trong tay, đều làm tôi tớ cho chúa tôi.'),
(1342, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 17, 'OT', 'Giô-sép đáp: "Tôi chẳng hề làm điều đó! Người nào bị tìm thấy cái chén trong tay, người ấy sẽ làm tôi mọi cho tôi; còn các ông thì hãy trở về bình an cùng cha các ông."'),
(1343, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 18, 'OT', 'Giu-đa bèn đến gần Giô-sép và nói: Tôi xin chúa hãy nghe tôi, tôi tớ của chúa, thưa một lời vào tai chúa; xin chớ nổi giận cùng tôi tớ của chúa, vì chúa ngang hàng với Pha-ra-ôn.'),
(1344, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 19, 'OT', 'Chúa đã hỏi các tôi tớ người rằng: Các ngươi có cha hay là anh em không?'),
(1345, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 20, 'OT', 'Chúng tôi thưa cùng chúa rằng: Cha chúng tôi đã già, và chúng tôi còn một đứa con trai nhỏ tuổi, là con của tuổi già. Anh nó đã chết, nó là đứa con trai duy nhất còn lại của mẹ nó, và cha nó rất yêu thương nó.'),
(1346, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 21, 'OT', 'Rồi ngài bảo các đầy tớ ngài rằng: "Hãy mang nó xuống đây cho ta, để ta được tận mắt nhìn thấy nó."'),
(1347, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 22, 'OT', 'Chúng tôi đã thưa cùng ông chủ rằng: Cậu bé không thể nào bỏ cha mình được; nếu bỏ cha thì cha sẽ chết.'),
(1348, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 23, 'OT', 'Rồi người bảo các đầy tớ ngài: "Nếu em út của các ngươi không đi xuống đây cùng các ngươi, các ngươi sẽ không được phép thấy mặt ta nữa."'),
(1349, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 24, 'OT', 'Khi chúng tôi trở về cùng người tôi tớ của chúa, là cha tôi, thì chúng tôi thuật lại cho người những lời của chúa.'),
(1350, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 25, 'OT', 'Thì cha chúng tôi nói: Hãy trở xuống, mua ít lương thực cho chúng ta.'),
(1351, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 26, 'OT', 'Chúng tôi nói: "Chúng tôi không thể xuống đó được, nếu em út của chúng tôi không đi cùng chúng tôi; bởi vì chúng tôi không thể nào ra mắt người ấy nếu em út của chúng tôi không ở cùng chúng tôi."'),
(1352, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 27, 'OT', 'Tôi tớ chúa, là cha tôi, nói với chúng tôi rằng: Các ngươi biết rằng vợ tôi đã sinh cho tôi hai người con trai;'),
(1353, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 28, 'OT', 'Một đứa đã ra đi khỏi ta, và ta nói: Chắc chắn đã bị xé nát rồi; và ta chưa hề thấy nó cho đến bây giờ.'),
(1354, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 29, 'OT', 'Nếu các con còn đem đứa này đi khỏi mặt ta nữa, và tai họa xảy đến cho nó, thì các con sẽ khiến đầu bạc nầy đau buồn mà xuống âm phủ.'),
(1355, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 30, 'OT', 'Bây giờ, nếu tôi trở về cùng người tôi tớ của ngài, cha tôi, mà người thiếu niên ấy không cùng về với chúng tôi, thì hồn người ấy đã ràng buộc chặt chẽ với hồn người thiếu niên ấy.'),
(1356, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 31, 'OT', 'thì khi thấy đứa trẻ không còn ở đó, người sẽ chết, và các tôi tớ chúa sẽ làm cho cha già tóc bạc của tôi tớ chúa, là cha chúng tôi, phải đau buồn mà xuống âm phủ.'),
(1357, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 32, 'OT', 'Vì tôi đã bảo lãnh đứa trẻ này cùng cha tôi, nói rằng: Nếu tôi không đem nó về cho cha, thì tôi sẽ phạm tội cùng cha trọn đời.'),
(1358, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 33, 'OT', 'Vậy bây giờ, xin để cho tôi tớ của chúa ở lại đây làm tôi mọi thay cho đứa trẻ, còn đứa trẻ thì hãy để nó đi lên cùng các anh của nó.'),
(1359, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 44, 34, 'OT', 'Làm sao tôi có thể trở về cùng cha tôi, khi đứa trẻ này không ở cùng tôi? Kẻo tôi phải nhìn thấy tai họa giáng xuống cha tôi.'),
(1360, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 45, 1, 'OT', 'Giô-sép không thể nén lòng nổi trước mặt mọi người đang đứng chung quanh ông, bèn truyền rằng: "Hãy cho mọi người lui ra khỏi ta!" Vậy không còn một ai ở đó khi Giô-sép tỏ mình ra cho các anh em mình.'),
(1361, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 45, 2, 'OT', 'Người cất tiếng khóc; dân Ê-díptô nghe thấy, và nhà Pha-ra-ôn cũng nghe biết.'),
(1362, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 45, 3, 'OT', 'Giô-sép nói với các anh em mình rằng: "Tôi là Giô-sép. Cha tôi còn sống chăng?" Nhưng các anh em không thể đáp lại người, vì họ kinh hãi trước mặt người.'),
(1363, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 45, 4, 'OT', 'Giô-sép nói với các anh em mình: "Hãy lại gần ta." Họ liền lại gần. Người nói: "Ta là Giô-sép, em các anh, người mà các anh đã bán ta xuống Ai-cập."'),
(1364, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 45, 5, 'OT', 'Bây giờ, đừng buồn, và cũng đừng tức giận trong lòng vì các anh đã bán tôi đến đây; vì Đức Chúa Trời đã sai tôi đến đây trước các anh để giữ gìn sự sống.'),
(1365, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 45, 6, 'OT', 'Vì hai năm nay đói kém trong xứ rồi, và còn năm năm nữa sẽ không có gieo sạ, cũng không có mùa màng.'),
(1366, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 45, 7, 'OT', 'Đức Chúa Trời đã sai tôi đến trước mặt anh em, để dành giữ một dòng dõi cho anh em trên đất, và để cứu sống anh em bằng một sự giải cứu lớn.'),
(1367, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 45, 8, 'OT', 'Vì vậy, không phải các anh đã sai tôi đến đây, mà là Đức Chúa Trời đã đặt tôi làm cha của Pha-ra-ôn, làm chủ mọi nhà người, và làm người quản trị toàn cõi đất Ai-cập.'),
(1368, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 45, 9, 'OT', 'Hãy mau lên, trở về cùng cha tôi và nói với người rằng: Giô-sép, con trai của cha, nói như thế này: Đức Chúa Trời đã đặt tôi làm chúa toàn xứ Ai Cập; xin cha hãy xuống cùng tôi, đừng chậm trễ.'),
(1369, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 45, 10, 'OT', 'Ngươi và các con, các cháu, các chiên, bò cùng mọi vật thuộc về ngươi sẽ ở tại xứ Gô-sen, gần ta đây.'),
(1370, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 45, 11, 'OT', 'Tôi sẽ nuôi dưỡng ông ở đó, vì còn năm năm đói kém nữa, kẻo ông và nhà ông cùng mọi thứ thuộc về ông bị tiêu hao hết.'),
(1371, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 45, 12, 'OT', 'Này, mắt các anh và mắt Bên-gia-min, em ta, đang thấy rằng chính miệng ta đang nói với các anh.'),
(1372, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 45, 13, 'OT', 'Hãy thuật lại cho cha tôi biết mọi sự vinh hiển của tôi tại Ai Cập và tất cả những điều anh em đã thấy; và hãy nhanh chóng đưa cha tôi xuống đây.'),
(1373, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 45, 14, 'OT', 'Người ôm lấy cổ Bên-gia-min, anh em mình, mà khóc; và Bên-gia-min cũng khóc trên cổ người.'),
(1374, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 45, 15, 'OT', 'Ông ôm hôn tất cả các anh mình và khóc trên các anh em ấy; sau đó, các anh ông mới dám nói chuyện với ông.'),
(1375, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 45, 16, 'OT', 'Và tiếng nói đã lan đến nhà Pha-ra-ôn rằng: Anh em Giô-sép đã đến. Pha-ra-ôn và các tôi tớ người lấy làm vui mừng.'),
(1376, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 45, 17, 'OT', 'Pha-ra-ôn nói với Giô-sép: "Hãy bảo các anh ngươi rằng: Các ngươi hãy làm điều này: chất đồ lên các con lừa của các ngươi, đi và trở về đất Ca-na-an."'),
(1377, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 45, 18, 'OT', 'Hãy đem cha các ngươi và các gia đình các ngươi đến cùng ta, ta sẽ ban cho các ngươi những điều tốt lành nhất của đất Ai Cập, và các ngươi sẽ ăn những sản vật tốt nhất của đất.'),
(1378, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 45, 19, 'OT', 'Và ngươi đã được lệnh điều nầy: Hãy làm điều nầy, hãy lấy những xe từ đất Ai Cập để chở con nhỏ và vợ các ngươi, rồi các ngươi sẽ rước cha các ngươi mà đến đây.'),
(1379, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 45, 20, 'OT', 'Đừng tiếc của cải mình, vì của tốt nhất trong khắp đất Ai Cập đều sẽ về phần các ngươi.'),
(1380, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 45, 21, 'OT', 'Các con trai của Y-sơ-ra-ên làm như vậy; Giô-sép cấp cho họ những xe bò theo lệnh của Pha-ra-ôn, và cấp lương thực cho họ dùng trên đường.'),
(1381, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 45, 22, 'OT', 'Mỗi người anh em được ban cho một bộ quần áo mới; còn Bên-gia-min thì được ban ba trăm miếng bạc và năm bộ quần áo mới.'),
(1382, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 45, 23, 'OT', 'Và người đã gửi cho cha mình mười con lừa đực chở những sản vật tốt nhất của Ai Cập, và mười con lừa cái chở lúa mì, bánh và lương thực cho cha mình dùng dọc đường.'),
(1383, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 45, 24, 'OT', 'Giô-sép sai anh em mình đi, và họ ra đi; người nói với họ: Đừng tranh cãi với nhau dọc đường.'),
(1384, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 45, 25, 'OT', 'Các anh em đi lên từ Ai-cập và đến xứ Ca-na-an, đến cùng Gia-cốp, cha mình.'),
(1385, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 45, 26, 'OT', 'Họ thuật lại cho người rằng: "Giô-sép vẫn còn sống, và chính người đang cai trị toàn cõi đất Ê-díp-tô." Lòng Gia-cốp liền bủn rủn, vì người không tin lời họ.'),
(1386, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 45, 27, 'OT', 'Các anh em nói với người mọi lời mà Giô-sép đã nói với họ; và Gia-cốp thấy các xe mà Giô-sép đã sai đến rước mình, thì thần trí của Gia-cốp cha họ sống lại.'),
(1387, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 45, 28, 'OT', 'Bấy giờ Y-sơ-ra-ên nói: Đủ rồi, Giô-sép, con trai ta, còn sống; ta sẽ đi, nhìn thấy nó trước khi ta chết.'),
(1388, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 1, 'OT', 'Y-sơ-ra-ên khởi đi, đem theo tất cả những gì mình có; người đến Bê-e-Sê-ba và dâng những lễ vật làm của lễ thiêu cho Đức Chúa Trời của Y-sác, cha người.'),
(1389, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 2, 'OT', 'Đức Chúa Trời phán cùng Y-sơ-ra-ên trong một thị kiến ban đêm, Ngài phán: "Gia-cốp, Gia-cốp!" Gia-cốp thưa: "Có tôi đây."'),
(1390, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 3, 'OT', 'Đức Chúa Trời phán: Ta là Đức Chúa Trời, Đức Chúa Trời của cha ngươi. Đừng sợ xuống Ai Cập, vì tại đó Ta sẽ làm cho ngươi thành một dân lớn.'),
(1391, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 4, 'OT', 'Ta sẽ xuống Ai Cập cùng ngươi, và Ta cũng sẽ đưa ngươi lên lại; và Giô-sép sẽ đặt tay mình trên mắt ngươi.'),
(1392, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 5, 'OT', 'Từ Bê-e-Sê-ba, Gia-cốp đứng dậy; các con trai Y-sơ-ra-ên khiêng Gia-cốp, cha mình, cùng các con nhỏ và các vợ mình lên các xe mà Pha-ra-ôn đã sai đến đón ông.'),
(1393, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 6, 'OT', 'Chúng đem theo các bầy súc vật và của cải mình đã gây dựng tại xứ Ca-na-an, rồi cùng nhau đi đến Ê-díp-tô: Gia-cốp và tất cả các con cháu người.'),
(1394, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 7, 'OT', 'Các con trai và các cháu trai người, các con gái và các cháu gái người, cùng với cả dòng dõi người, Gia-cốp đều đem theo xuống Ai-cập.'),
(1395, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 8, 'OT', 'Đây là các tên con trai của Y-sơ-ra-ên đến Ai-cập: Gia-cốp và các con trai ông; con trưởng của Gia-cốp là Ru-bên.'),
(1396, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 9, 'OT', 'Các con trai của Ru-bên là Hê-nóc, Pha-lu, Hết-rôn và Cạt-mi.'),
(1397, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 10, 'OT', 'Các con trai của Si-mê-ôn là Giê-mu-ên, Gia-min, Ô-hát, Gia-kin, Xô-ha, và Sau-lơ, con trai người Ca-na-an.'),
(1398, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 11, 'OT', 'Các con trai của Lê-vi là Ghẹt-sôn, Kê-hát, và Mê-ra-ri.'),
(1399, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 12, 'OT', 'Các con trai của Giu-đa là Ê-rơ, O-nan, Sê-la, Phê-rết và Sê-rách. Ê-rơ và O-nan đã chết tại đất Ca-na-an; các con trai của Phê-rết là Hết-rôn và Ha-mun.'),
(1400, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 13, 'OT', 'Các con trai của Y-sa-ca là Thô-la, Phu-va, Gióp và Sim-rôn.'),
(1401, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 14, 'OT', 'Các con trai của Sa-bu-lôn là Sê-rết, Ê-lôn và Gia-lê-ên.'),
(1402, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 15, 'OT', 'Đây là các con trai của Lê-a, mà bà đã sinh cho Gia-cốp tại Pha-đan-A-ram, cùng với Đi-na, con gái bà; tổng số người con trai và con gái của ông là ba mươi ba người.'),
(1403, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 16, 'OT', 'Các con trai của Gát là Xi-phi-ôn, Ha-ghi, Su-ni, Eùt-bôn, Ê-ri, A-rô-đi và A-rê-li.'),
(1404, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 17, 'OT', 'Các con trai của A-se là Dim-na, Dích-và, Dích-vi, và Bê-ri-a, cùng Sê-rách, em gái các người đó. Các con trai của Bê-ri-a là Hê-be và Manh-ki-ên.'),
(1405, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 18, 'OT', 'Đây là các con trai của Xinh-ba, người mà La-ban đã cho Lê-a, con gái mình; Xinh-ba đã sinh những người này cho Gia-cốp: tất cả là mười sáu mạng sống.'),
(1406, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 19, 'OT', 'Các con trai của Ra-chên, vợ Gia-cốp, là Giô-sép và Bên-gia-min.'),
(1407, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 20, 'OT', 'Giô-sép sanh được Ma-na-se và Eùp-ra-im tại đất Ai Cập, mà Aùch-nát, con gái của Phô-ti-phê-ra, thầy tế lễ của thành Óan, đã sanh cho người.'),
(1408, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 21, 'OT', 'Các con trai của Bên-gia-min là Bê-la, Bê-kê, Aùch-bên, Giê-ra, Na-a-man, Ê-hi, Rô-sơ, Mốp-bim, Hốp-bim và A-rết.'),
(1409, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 22, 'OT', 'Đây là các con trai của Ra-chên, những người được sinh cho Gia-cốp; tổng số là mười bốn người.'),
(1410, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 23, 'OT', 'Con trai của Đan là Hu-sim.'),
(1411, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 24, 'OT', 'Các con trai của Nép-ta-li là Giát-sê-ên, Gu-ni, Dít-se, và Si-lem.'),
(1412, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 25, 'OT', 'Đây là các con trai của Bi-la, người mà La-ban đã cho Ra-chên con gái mình; Bi-la đã sinh những người này cho Gia-cốp; tất cả số người là bảy.'),
(1413, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 26, 'OT', 'Tất cả những người đi đến Ai-cập với Gia-cốp, tức là những người do chính Gia-cốp sinh ra, không kể các vợ của các con trai Gia-cốp; trọn số là sáu mươi sáu người.'),
(1414, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 27, 'OT', 'Con cái của Giô-sép, những người sanh cho người tại Ai-cập, là hai người. Tất cả những người thuộc nhà Gia-cốp đến Ai-cập là bảy mươi người.'),
(1415, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 28, 'OT', 'Gia-cốp sai Giu-đa đi trước đến cùng Giô-sép, đặng chỉ dẫn đường cho mình vào bờ cõi Gô-sen; rồi họ mới vào đất Gô-sen.'),
(1416, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 29, 'OT', 'Giô-sép thắng xe mình và lên đường đến Gô-sen đón Y-sơ-ra-ên, cha mình; rồi người ra mắt cha, ôm cổ cha và khóc trên cổ cha một hồi lâu.'),
(1417, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 30, 'OT', 'Y-sơ-ra-ên nói với Giô-sép: "Cha sẽ chết bây giờ đi, sau khi đã thấy mặt con, vì con vẫn còn sống."'),
(1418, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 31, 'OT', 'Giô-sép nói cùng anh em và người nhà cha mình rằng: Tôi sẽ lên tâu với Pha-ra-ôn và nói với người rằng: Anh em tôi và cả nhà cha tôi, ở xứ Ca-na-an, đã đến cùng tôi.'),
(1419, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 32, 'OT', 'Những người nầy là kẻ chăn chiên, vì họ vốn là người chăn nuôi súc vật; họ đã đem theo bầy chiên, bò và mọi thứ thuộc về mình.'),
(1420, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 33, 'OT', 'Vậy khi Pha-ra-ôn truyền gọi các ngươi và hỏi: Các ngươi làm nghề gì?'),
(1421, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 46, 34, 'OT', 'Hãy nói rằng: Những kẻ tôi tớ ngài từ khi còn nhỏ cho đến bây giờ, cả chúng tôi lẫn tổ phụ chúng tôi, đều là những người chăn nuôi súc vật, để anh em được ở trong đất Gô-sen, vì người Ai-cập ghê tởm mọi kẻ chăn chiên.'),
(1422, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 47, 1, 'OT', 'Giô-sép đến tâu với Pha-ra-ôn và nói: Cha tôi và các anh em tôi, cùng chiên, bò và mọi vật sở hữu của họ, đã đến từ xứ Ca-na-an và nay đang ở trong xứ Gô-sen.'),
(1423, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 47, 2, 'OT', 'Người bèn lấy năm người trong anh em mình mà dẫn đến trước mặt Pha-ra-ôn.'),
(1424, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 47, 3, 'OT', 'Pha-ra-ôn hỏi các anh em mình: Các ngươi làm nghề gì? Họ thưa với Pha-ra-ôn: Những kẻ tôi tớ bệ hạ là người chăn chiên, cả chúng tôi lẫn tổ tiên chúng tôi.'),
(1425, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 47, 4, 'OT', 'Chúng tôi đến đây để kiều ngụ trong xứ, vì các tôi tớ của bệ hạ không còn đồng cỏ nào cho bầy chiên, bởi nạn đói ở đất Ca-na-an rất nặng. Vậy, xin vua cho các tôi tớ của bệ hạ được ở trong đất Gô-sen.'),
(1426, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 47, 5, 'OT', 'Pha-ra-ôn nói cùng Giô-sép rằng: Cha ngươi và anh em ngươi đã đến cùng ngươi;'),
(1427, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 47, 6, 'OT', 'Đất Ai Cập sẵn sàng trước mặt ngươi; hãy để cho cha và các anh em ngươi ở nơi tốt nhất của đất; họ sẽ cư ngụ tại đất Gô-sen. Nếu ngươi biết trong số họ có những người tài giỏi, hãy đặt họ làm quản lý các đàn súc vật của ta.'),
(1428, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 47, 7, 'OT', 'Giô-sép dẫn Gia-cốp, cha mình, và để người trước mặt Pha-ra-ôn; Gia-cốp chúc phước cho Pha-ra-ôn.'),
(1429, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 47, 8, 'OT', 'Pha-ra-ôn hỏi Gia-cốp: "Ngươi đã sống được bao nhiêu năm?"'),
(1430, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 47, 9, 'OT', 'Gia-cốp nói với Pha-ra-ôn: Những năm đời tôi làm khách lạ là một trăm ba mươi năm; ít ỏi và đầy gian nan những năm đời tôi, chưa đạt đến số năm đời của tổ tiên tôi trong thời gian họ làm khách lạ.'),
(1431, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 47, 10, 'OT', 'Gia-cốp chúc phước cho Pha-ra-ôn, rồi đi ra khỏi mặt Pha-ra-ôn.'),
(1432, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 47, 11, 'OT', 'Giô-sép định chỗ ở cho cha và các anh em mình, và cấp cho họ một đặc quyền sở hữu tại đất Ai Cập, tại phần tốt nhất của đất, tại đất Ram-se, như Pha-ra-ôn đã truyền.'),
(1433, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 47, 12, 'OT', 'Giô-sép cấp lương thực cho cha, các anh em và cả nhà cha mình, tùy theo số người trong gia đình.'),
(1434, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 47, 13, 'OT', 'Lương thực không còn trong khắp đất, vì nạn đói rất nặng; đất Ê-díp-tô và đất Ca-na-an đều bị suy sụp vì nạn đói.'),
(1435, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 47, 14, 'OT', 'Giô-sép thu lấy hết mọi bạc ở trong xứ Ê-díp-tô và trong xứ Ca-na-an, vì dân chúng mua lúa; rồi Giô-sép đem bạc đó vào kho của Pha-ra-ôn.'),
(1436, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 47, 15, 'OT', 'Khi bạc tiền trong xứ Ai Cập và xứ Ca-na-an đã hết sạch, thì tất cả dân Ai Cập đều đến cùng Giô-sép mà nói rằng: Xin hãy cho chúng tôi lương thực; lẽ nào vì hết tiền mà chúng tôi phải chết trước mặt ông sao?'),
(1437, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 47, 16, 'OT', 'Giô-sép nói: Hãy đưa súc vật các ngươi cho ta, ta sẽ cho các ngươi lương thực đổi lấy súc vật các ngươi, nếu bạc đã hết.'),
(1438, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 47, 17, 'OT', 'Dân chúng đem súc vật mình đến cho Giô-sép; rồi Giô-sép cấp thực phẩm cho họ đổi lấy ngựa, đàn chiên, đàn bò và lừa. Người nuôi dưỡng họ bằng thực phẩm, đổi lấy tất cả súc vật họ có trong năm đó.'),
(1439, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 47, 18, 'OT', 'Hết năm ấy, năm sau họ lại đến cùng ông và nói: "Chúng tôi không giấu gì chúa cả, vì tiền bạc đã hết, súc vật cũng đã về cho chúa; hiện tại trước mặt chúa chẳng còn gì ngoài thân thể và đất đai của chúng tôi."'),
(1440, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 47, 19, 'OT', 'Làm sao chúng tôi và đất đai của chúng tôi phải chết rũ rượi trước mặt Pha-ra-ôn? Xin hãy mua chúng tôi và đất đai của chúng tôi lấy lương thực; chúng tôi và đất đai sẽ làm tôi mọi cho Pha-ra-ôn. Xin cấp giống ra, để chúng tôi sống, không chết mất, và đất không bị bỏ hoang.'),
(1441, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 47, 20, 'OT', 'Giô-sép bèn mua hết thảy đất đai của xứ Ai Cập cho Pha-ra-ôn, vì người Ai Cập đã bán mỗi người ruộng đất của mình, do cơn đói kém ngày càng gia tăng; và đất đai bèn thuộc về Pha-ra-ôn.'),
(1442, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 47, 21, 'OT', 'Còn về dân chúng, người đã chuyển họ vào các thành, từ đầu ranh giới Ai Cập cho đến đầu kia.'),
(1443, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 47, 22, 'OT', 'Chỉ có ruộng đất của các thầy tế lễ, Giô-sép không mua; vì các thầy tế lễ được nhận phần định từ Pha-ra-ôn, và họ ăn phần định mà Pha-ra-ôn cấp cho; bởi vậy, họ không bán ruộng đất mình.'),
(1444, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 47, 23, 'OT', 'Giô-sép nói với dân chúng rằng: Này, hôm nay ta đã mua các ngươi và đất đai các ngươi cho Pha-ra-ôn; đây, hạt giống cho các ngươi, hãy gieo trồng trên đất ấy.'),
(1445, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 47, 24, 'OT', 'Đến mùa gặt, các ngươi phải nộp cho Pha-ra-ôn một phần năm; còn bốn phần kia sẽ thuộc về các ngươi, để làm giống gieo trên ruộng, và làm lương thực cho các ngươi, cho những người trong nhà các ngươi, và cho các con nhỏ của các ngươi.'),
(1446, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 47, 25, 'OT', 'Dân chúng nói: Xin ngài đã cho chúng tôi được sống, nguyện chúng tôi được ơn trước mặt ngài, thì chúng tôi sẽ làm tôi mọi cho Pha-ra-ôn.'),
(1447, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 47, 26, 'OT', 'Vì thế, Giô-sép ban hành luật lệ ấy làm quy định đến ngày nay trên đất Ai Cập: phải nộp một phần năm cho Pha-ra-ôn; chỉ đất của các thầy tế lễ thì riêng họ giữ, không thuộc về Pha-ra-ôn.'),
(1448, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 47, 27, 'OT', 'Y-sơ-ra-ên trú ngụ tại đất Ê-díp-tô, tại đất Gô-sen; họ chiếm hữu đất ấy, và sinh sôi nảy nở rất nhiều.'),
(1449, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 47, 28, 'OT', 'Gia-cốp sống tại đất Ai-cập mười bảy năm; tuổi thọ của Gia-cốp là một trăm bốn mươi bảy năm.'),
(1450, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 47, 29, 'OT', 'Khi những ngày của Y-sơ-ra-ên gần đến để qua đời, ông gọi Giô-sép, con trai mình, và nói với người rằng: Nếu bây giờ tôi được ơn trước mặt con, xin hãy đặt tay con dưới đùi tôi, và con hãy làm ơn thật và giữ lòng trung tín với tôi; xin đừng chôn tôi trong đất Ê-díp-tô.'),
(1451, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 47, 30, 'OT', 'Ta sẽ nằm cùng các tổ phụ ta; ngươi phải mang ta ra khỏi Ai Cập và chôn ta trong mồ mả của tổ tiên ta. Giô-sép thưa: Con sẽ làm theo lời cha dạy.'),
(1452, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 47, 31, 'OT', 'Y-sơ-ra-ên nói: Hãy thề cho ta. Vậy Giô-sép thề cho người. Rồi Y-sơ-ra-ên cúi lạy trên đầu giường.'),
(1453, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 48, 1, 'OT', 'Sau các việc ấy, có người nói cùng Giô-sép rằng: Nầy, cha ngươi đang đau. Vậy Giô-sép đem hai con trai mình là Ma-na-se và Eùp-ra-im cùng đi đến.'),
(1454, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 48, 2, 'OT', 'Họ báo cho Gia-cốp biết và nói: Nầy, Giô-sép, con trai ông, đang đến gặp ông. Y-sơ-ra-ên bèn cố sức ngồi dậy trên giường.'),
(1455, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 48, 3, 'OT', 'Gia-cốp nói với Giô-sép: Đức Chúa Trời Toàn Năng đã hiện ra cùng ta tại Lu-xơ, trong xứ Ca-na-an, và đã ban phước cho ta.'),
(1456, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 48, 4, 'OT', 'và nói với tôi: Nầy, Ta sẽ làm cho ngươi sinh sôi nảy nở và gia tăng rất nhiều, biến ngươi thành một hội chúng các dân tộc; và Ta sẽ ban cho dòng dõi ngươi đất nầy làm cơ nghiệp đời đời.'),
(1457, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 48, 5, 'OT', 'Bây giờ, hai con trai mà con đã sinh ra tại đất Ai Cập trước khi ta đến Ai Cập, tức là Eùp-ra-im và Ma-na-se, sẽ thuộc về ta như Ru-bên và Si-mê-ôn vậy.'),
(1458, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 48, 6, 'OT', 'Các con sinh sau những đứa này sẽ thuộc về con; về phần cơ nghiệp, chúng sẽ được gọi theo tên các anh em mình.'),
(1459, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 48, 7, 'OT', 'Còn ta, khi ta từ Pha-đan trở về, thì Ra-chên chết trên đất Ca-na-an dọc đường, còn cách Ê-phrát một khoảng đất ngắn; ta đã chôn nàng ở đó bên đường Ê-phrát, tức là Bết-lê-hem.'),
(1460, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 48, 8, 'OT', 'Y-sơ-ra-ên thấy các con trai của Giô-sép, bèn nói: Những người nầy là ai?'),
(1461, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 48, 9, 'OT', 'Giô-sép nói với Y-sơ-ra-ên: "Chúng là con trai tôi mà Đức Chúa Trời đã ban cho tôi tại đây." Y-sơ-ra-ên nói: "Hãy mang chúng đến cho tôi, để tôi chúc phước cho chúng."'),
(1462, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 48, 10, 'OT', 'Mắt của Y-sơ-ra-ên mờ vì già, không thể nhìn rõ; người bèn đưa chúng nó lại gần mình, rồi hôn và ôm chúng nó.'),
(1463, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 48, 11, 'OT', 'Y-sơ-ra-ên nói với Giô-sép: "Tôi đã không dám nghĩ rằng tôi sẽ thấy mặt con, nhưng nầy, Đức Chúa Trời đã cho tôi thấy cả dòng dõi của con nữa."'),
(1464, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 48, 12, 'OT', 'Giô-sép dẫn chúng ra khỏi đầu gối mình, rồi cúi mình xuống đất.'),
(1465, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 48, 13, 'OT', 'Giô-sép đem cả hai đứa trẻ lại gần cha mình: đặt Eùp-ra-im bên tay phải mình, về phía bên trái của Ít-ra-en, và đặt Ma-na-se bên tay trái mình, về phía bên phải của Ít-ra-en, rồi dẫn chúng đến gần cha.'),
(1466, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 48, 14, 'OT', 'Y-sơ-ra-ên đưa tay phải ra và đặt trên đầu Eùp-ra-im, dù người là đứa nhỏ hơn, còn tay trái thì đặt trên đầu Ma-na-se; Người cố ý xếp đặt hai tay mình như vậy, mặc dù Ma-na-se là con cả.'),
(1467, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 48, 15, 'OT', 'Người chúc phước cho Giô-sép và nói: Đức Chúa Trời mà Aùp-ra-ham và Y-sác, tổ phụ tôi, đã sống trước mặt Ngài; Đức Chúa Trời chăn giữ tôi từ khi tôi sinh ra cho đến ngày nay,'),
(1468, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 48, 16, 'OT', 'Thiên sứ đã chuộc tôi khỏi mọi điều ác, hãy ban phước cho các con trẻ; và danh tôi cùng danh các tổ phụ tôi là Aùp-ra-ham và Y-sác được đặt trên chúng; chúng sẽ sinh sôi nảy nở vô số trên đất.'),
(1469, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 48, 17, 'OT', 'Khi thấy cha mình đặt tay phải lên đầu Eùp-ra-im, Giô-sép lấy làm khó chịu trong lòng, bèn nắm tay cha mình để dời tay ấy khỏi đầu Eùp-ra-im sang đầu Ma-na-se.'),
(1470, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 48, 18, 'OT', 'Giô-sép nói với cha mình rằng: "Không phải vậy, cha ơi; vì đây mới là trưởng nam; xin đặt tay phải của cha trên đầu nó."'),
(1471, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 48, 19, 'OT', 'Nhưng cha người không chịu, và nói: Ta biết, con ơi, ta biết; chính nó cũng sẽ trở nên một dân, và chính nó cũng sẽ lớn mạnh; nhưng em trai nó, người em út, sẽ lớn mạnh hơn nó, và dòng dõi nó sẽ đầy các nước.'),
(1472, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 48, 20, 'OT', 'Trong ngày đó, Gia-cốp chúc phước cho chúng mà nói rằng: Nhờ ngươi, Y-sơ-ra-ên sẽ chúc phước rằng: Đức Chúa Trời khiến ngươi được như Eùp-ra-im và như Ma-na-se. Rồi Gia-cốp đặt Eùp-ra-im trước Ma-na-se.'),
(1473, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 48, 21, 'OT', 'Y-sơ-ra-ên nói với Giô-sép: Nầy, ta sắp chết, nhưng Đức Chúa Trời sẽ ở cùng các con và đưa các con trở lại đất tổ phụ các con.'),
(1474, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 48, 22, 'OT', 'Và ta đã cho ngươi một phần hơn anh em ngươi, phần mà ta đã chiếm lấy từ tay người A-mô-rít bằng gươm và bằng cung tên ta.'),
(1475, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 1, 'OT', 'Gia-cốp gọi các con trai mình lại và nói: Hãy nhóm lại đây, để tôi nói cho các con điều sẽ xảy đến cho các con trong những ngày cuối cùng.'),
(1476, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 2, 'OT', 'Hỡi các con trai Gia-cốp, hãy nhóm lại mà nghe; hãy lắng nghe Y-sơ-ra-ên, cha các con.'),
(1477, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 3, 'OT', 'Ru-bên, con là trưởng nam của cha, là sức lực cha và là đầu tiên của sức mạnh cha, có sự tôn trọng hơn người và quyền năng hơn người.'),
(1478, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 4, 'OT', 'Con sôi trào như nước, sẽ không được ưu việt hơn ai; vì con đã lên giường cha mình, lên giường cha mình, làm ô uế chốn nằm của người!'),
(1479, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 5, 'OT', 'Si-mê-ôn và Lê-vi là anh em, các thứ khí giới của chúng nó là khí giới bạo tàn.'),
(1480, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 6, 'OT', 'Đừng cho linh hồn ta vào hội họ, đừng cho vinh hiển ta hiệp cùng hội chúng; vì trong cơn giận của chúng, chúng đã giết người, và theo ý riêng của chúng, chúng đã hủy hoại bò đực.'),
(1481, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 7, 'OT', 'Đáng rủa sả thay cơn giận của họ, vì thật mạnh mẽ; và cơn thịnh nộ của họ, vì thật dữ dội. Ta sẽ chia họ ra trong Gia-cốp, và tản họ khắp trong Y-sơ-ra-ên.'),
(1482, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 8, 'OT', 'Hỡi Giu-đa! các anh em ngươi sẽ ca ngợi ngươi; tay ngươi sẽ đặt trên gáy kẻ thù ngươi; các anh em ngươi sẽ cúi lạy trước mặt ngươi.'),
(1483, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 9, 'OT', 'Giu-đa là sư tử tơ; hỡi con, con đã lên khỏi miếng mồi; nó cúi xuống, nằm phục như sư tử đực và như sư tử cái; ai dám khiến nó đứng dậy?'),
(1484, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 10, 'OT', 'Cây quyền trượng sẽ không rời khỏi Giu-đa, kẻ cầm quyền sẽ không dứt khỏi giữa các chân nó, cho đến khi Đấng Si-lô đến, và các dân sẽ vâng phục Người.'),
(1485, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 11, 'OT', 'Buộc lừa tơ của nó vào gốc nho, và lừa con của nó vào nhành nho tốt; giặt áo mình trong rượu, và nhuộm áo choàng mình trong huyết nho.'),
(1486, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 12, 'OT', 'Mắt đỏ hơn cả rượu, răng trắng hơn cả sữa.'),
(1487, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 13, 'OT', 'Sa-bu-lôn sẽ ở nơi bờ biển, làm nơi đậu tàu thuyền, và bờ cõi người sẽ giáp ranh Si-đôn.'),
(1488, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 14, 'OT', 'Y-sa-ca là một con lừa khỏe mạnh, nằm nghỉ giữa hai dải đất.'),
(1489, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 15, 'OT', 'Thấy nơi nghỉ ngơi là tốt lành, và đất đai là dễ chịu, bèn cúi vai mình xuống để mang gánh nặng, và phải phục vụ kẻ bắt lao dịch.'),
(1490, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 16, 'OT', 'Đan sẽ xét đoán dân sự mình như một trong các chi phái Y-sơ-ra-ên.'),
(1491, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 17, 'OT', 'Đan sẽ là con rắn ven lối đi, rắn hổ mang ven lối mòn; cắn gót ngựa, khiến người cỡi ngã ngửa.'),
(1492, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 18, 'OT', 'Hỡi Đức Giê-hô-va, tôi trông đợi sự cứu rỗi của Ngài.'),
(1493, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 19, 'OT', 'Gát sẽ bị một đạo quân tấn công, nhưng nó sẽ tấn công gót chân chúng.'),
(1494, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 20, 'OT', 'Từ A-se có lương thực dồi dào; người ấy sẽ cung cấp các món ngon cho vua.'),
(1495, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 21, 'OT', 'Nép-ta-li là nai cái được thả ra, nói những lời mỹ miều.'),
(1496, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 22, 'OT', 'Giô-sép là cây con xanh tốt, cây con xanh tốt gần suối nước; các con gái đi tới gần tường.'),
(1497, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 23, 'OT', 'Người ta làm cho người cay đắng, người ta chống người; những kẻ cầm cung ghẹo chọc người.'),
(1498, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 24, 'OT', 'Cung người vẫn bền vững nơi sức mạnh, và cánh tay người được làm mạnh từ nơi Đấng Toàn Năng của Gia-cốp, từ nơi Đấng Chăn Chiên, là Đá của Y-sơ-ra-ên.'),
(1499, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 25, 'OT', 'Từ Đức Chúa Trời của cha ngươi, Ngài sẽ giúp đỡ ngươi; và từ Đấng Toàn Năng, Ngài sẽ ban phước cho ngươi; các phước lành từ các tầng trời ở trên, các phước lành từ vực sâu nằm dưới, các phước lành của vú và của lòng mẹ.'),
(1500, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 26, 'OT', 'Các phước lành của cha ngươi mạnh hơn các phước lành của tổ tiên ngươi, cho đến các đỉnh núi vĩnh hằng; chúng sẽ thuộc về đầu Giô-sép, và về trán của người được biệt riêng giữa anh em mình.'),
(1501, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 27, 'OT', 'Bên-gia-min là chó sói hay cắn xé; ban mai ăn mồi, chiều chia của cướp.'),
(1502, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 28, 'OT', 'Tất cả những người này là mười hai chi phái của Y-sơ-ra-ên; ấy là điều mà cha các người ấy đã nói với họ, khi chúc phước cho họ, mỗi người theo phước riêng của mình mà chúc phước cho họ.'),
(1503, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 29, 'OT', 'Người căn dặn các con mình và nói: Ta sẽ được thu về cùng dân ta; hãy chôn ta với tổ tiên ta, trong hang đá tại đồng ruộng của Eùp-rôn, người Hê-tít,'),
(1504, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 30, 'OT', 'trong hang đá ở trong đồng bằng Mặc-bê-la, đối diện với Mam-rê, tại xứ Ca-na-an, là nơi Aùp-ra-ham đã mua mảnh đất ấy từ Eùp-rôn, người dân Hê-th, để làm nơi chôn cất riêng'),
(1505, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 31, 'OT', 'Nơi đó, họ chôn Aùp-ra-ham và Sa-ra, vợ người; nơi đó, họ chôn Y-sác và Rê-be-ca, vợ người; và nơi đó, tôi đã chôn Lê-a.'),
(1506, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 32, 'OT', 'Đồng ruộng và cái hang ở trong đó, đã mua từ con cái của Hê-th.'),
(1507, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 49, 33, 'OT', 'Gia-cốp ngừng trối trăng các điều đó cho các con mình, bèn co chân lại lên giường, rồi tắt hơi và được thu về cùng tổ tiên mình.'),
(1508, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 50, 1, 'OT', 'Giô-sép bèn ngã xuống trên mặt cha mình, khóc nức nở và hôn người.'),
(1509, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 50, 2, 'OT', 'Giô-sép truyền lịnh cho các đầy tớ mình, là các thầy thuốc, hãy ướp xác cha người; các thầy thuốc bèn ướp xác Y-sơ-ra-ên.'),
(1510, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 50, 3, 'OT', 'Bốn mươi ngày xức dầu thơm cho ông đã trọn, vì thời gian xức dầu thơm cho người chết là như vậy; người Ai Cập khóc than ông bảy mươi ngày.'),
(1511, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 50, 4, 'OT', 'Khi những ngày khóc than ông qua đời đã chấm dứt, Giô-sép nói với gia đình của Pha-ra-ôn rằng: "Nếu bây giờ tôi được ơn trước mặt các ông, xin hãy nói với Pha-ra-ôn rằng:'),
(1512, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 50, 5, 'OT', 'Cha tôi đã bắt tôi thề rằng: Nầy, ta sắp chết; trong mồ mả mà ta đã đào cho ta trong xứ Ca-na-an, ở đó ngươi phải chôn ta. Vậy bây giờ, xin cho tôi lên chôn cha tôi, rồi tôi sẽ trở xuống.'),
(1513, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 50, 6, 'OT', 'Pha-ra-ôn nói: Hãy lên, đi chôn cha ngươi, theo đúng điều mà người đã khiến ngươi thề.'),
(1514, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 50, 7, 'OT', 'Giô-sép liền đi lên để chôn cha mình; và các tôi tớ của Pha-ra-ôn, các bậc trưởng lão trong nhà người, cùng tất cả các bậc trưởng lão trong đất Ê-díp-tô đều đi lên với người.'),
(1515, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 50, 8, 'OT', 'Hết thảy nội nhà Giô-sép, các anh em người và nội nhà cha người đều đi lên; chỉ để lại những đứa trẻ và chiên cùng bò của họ tại đất Gô-sen.'),
(1516, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 50, 9, 'OT', 'Cũng đi cùng người cả xe ngựa lẫn kỵ binh, và đoàn người đông đảo ấy quả thật rất lớn.'),
(1517, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 50, 10, 'OT', 'Họ đến sân đạp lúa của A-tát, bên kia sông Giô-đanh, và khóc than tại đó một cách rất lớn và nặng nề; rồi Giô-sép để tang cha mình trong bảy ngày.'),
(1518, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 50, 11, 'OT', 'Dân Ca-na-an, tức là những người sống trong xứ ấy, thấy cảnh than khóc tại sân đạp lúa A-tát, bèn nói: Đây là một cảnh để tang rất lớn của người Ai-cập! Vì cớ ấy, người ta đặt tên cho nơi ấy là A-bên-Mích-ra-im, tức là nơi để tang của người Ai-cập, ở bên kia sông Giô-đanh.'),
(1519, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 50, 12, 'OT', 'Các con trai của Gia-cốp đã làm cho người như vậy, đúng như điều người đã truyền cho họ.'),
(1520, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 50, 13, 'OT', 'Các con trai người khiêng xác người về đất Ca-na-an và chôn người trong hang đá tại đồng ruộng Mặc-bê-la, đối diện với Mam-rê, là đồng ruộng mà Aùp-ra-ham đã mua từ Eùp-rôn người Hê-tít để làm nơi chôn cất.'),
(1521, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 50, 14, 'OT', 'Sau khi chôn cha mình xong, Giô-sép trở lại Ai-cập, cùng các anh em và tất cả những người lên cùng ông để chôn cha ông.'),
(1522, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 50, 15, 'OT', 'Các anh của Giô-sép thấy cha mình đã qua đời, thì nói với nhau: "Biết đâu Giô-sép sẽ ghét chúng ta và trả đủ cho chúng ta mọi điều ác mà chúng ta đã làm cho người."'),
(1523, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 50, 16, 'OT', 'Các anh sai đến nói cùng Giô-sép rằng: Cha ngươi đã trối trước khi người qua đời rằng:'),
(1524, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 50, 17, 'OT', 'Hãy nói cùng Giô-sép rằng: "Xin hãy tha thứ sự phạm tội và tội lỗi của các anh con, vì họ đã đối xử xấu với con. Bây giờ, xin hãy tha thứ sự phạm tội của các tôi tớ Đức Chúa Trời của cha con." Khi họ nói với người như vậy, Giô-sép liền khóc.'),
(1525, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 50, 18, 'OT', 'Các anh người cũng đi đến, sấp mình xuống trước mặt người và nói: Này chúng tôi đây, thật sự là tôi tớ của anh.'),
(1526, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 50, 19, 'OT', 'Giô-sép nói với họ: "Đừng sợ, vì tôi há có thể thay thế Đức Chúa Trời được sao?"'),
(1527, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 50, 20, 'OT', 'Các anh toan hại tôi, nhưng Đức Chúa Trời đã toan định điều đó cho điều lành, để thực hiện như ngày nay, là cứu sống một dân đông đảo.'),
(1528, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 50, 21, 'OT', 'Vậy bây giờ, đừng sợ; chính tôi sẽ cấp dưỡng các ngươi và con cái các ngươi. Rồi Giô-sép an ủi họ và nói chuyện thân tình với họ.'),
(1529, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 50, 22, 'OT', 'Giô-sép cùng nhà cha mình ở tại Ai-cập; Giô-sép sống được một trăm mười năm.'),
(1530, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 50, 23, 'OT', 'Giô-sép thấy các con của Eùp-ra-im, đến đời thứ ba; và các con của Ma-ki, con trai của Ma-na-se, cũng được sinh ra và được nâng niu trên đầu gối Giô-sép.'),
(1531, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 50, 24, 'OT', 'Giô-sép nói cùng các anh em mình rằng: Tôi sẽ chết, nhưng Đức Chúa Trời sẽ thăm viếng các anh em và đem các anh em lên khỏi đất này, đến đất mà Ngài đã thề hứa cùng Aùp-ra-ham, Y-sác và Gia-cốp.'),
(1532, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 50, 25, 'OT', 'Giô-sép biểu các con trai của Y-sơ-ra-ên thề mà rằng: Đức Chúa Trời sẽ thăm viếng các ngươi, và các ngươi phải đem hài cốt tôi lên khỏi nơi nầy.'),
(1533, 1, 'GOI_vi', 'GOI_vi', 'vi', 'GEN', 50, 26, 'OT', 'Giô-sép qua đời hưởng thọ một trăm mười tuổi; người ta ướp xác người và đặt người trong một cái hòm tại Ai-cập.'),
(1534, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 1, 1, 'OT', 'Đây là tên các con trai của Y-sơ-ra-ên, những người đã đến Ai-cập cùng với Gia-cốp, mỗi người đều đến với gia đình mình.'),
(1535, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 1, 2, 'OT', 'Ru-bên, Si-mê-ôn, Lê-vi và Giu-đa;'),
(1536, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 1, 3, 'OT', 'Y-sa-ca, Sa-bu-lôn và Bên-gia-min;'),
(1537, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 1, 4, 'OT', 'Đan, Nép-ta-li, Gát và A-se.'),
(1538, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 1, 5, 'OT', 'Tất cả những người sinh ra bởi Gia-cốp, gồm bảy mươi người, và Giô-sép đã ở Ai-cập.'),
(1539, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 1, 6, 'OT', 'Giô-sép qua đời, cùng với tất cả anh em người và cả thế hệ ấy.'),
(1540, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 1, 7, 'OT', 'Con cháu Y-sơ-ra-ên sinh sôi nảy nở, gia tăng và trở nên đông đảo cách quyền thế; cả đất nước đều đầy dẫy họ.'),
(1541, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 1, 8, 'OT', 'Có một vua mới trị vì trên đất Ai Cập, là người không biết đến Giô-sép.'),
(1542, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 1, 9, 'OT', 'Vua nói cùng dân mình rằng: Nầy, dân Y-sơ-ra-ên đông và mạnh hơn chúng ta;'),
(1543, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 1, 10, 'OT', 'Hãy đến, ta hãy dùng mưu khôn ngoan đối với chúng, e rằng chúng sẽ sinh sôi thêm, và xảy ra chiến tranh, thì cả nó cũng sẽ gia nhập vào kẻ thù nghịch chúng ta, đánh nghịch lại chúng ta và đi lên khỏi xứ.'),
(1544, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 1, 11, 'OT', 'Họ đặt những người cai trị lao dịch trên dân ấy, để hành hạ họ bằng những công việc nặng nhọc; và họ xây các thành kho tàng cho Pha-ra-ôn là Phi-thom và Ram-se.'),
(1545, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 1, 12, 'OT', 'Càng bắt bớ họ chừng nào, họ càng thêm nhiều và lan tràn ra chừng ấy; người Ai-cập bèn ghét dân Y-sơ-ra-ên.'),
(1546, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 1, 13, 'OT', 'Người Ai Cập bắt các con trai của Y-sơ-ra-ên làm việc cực nhọc.'),
(1547, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 1, 14, 'OT', 'Làm cho đời sống của dân ấy nên cay đắng vì công việc nặng nhọc, nhồi đất và làm gạch, cùng mọi công việc ngoài đồng, tức là mọi công việc mà người Ai-cập bắt dân Y-sơ-ra-ên phải làm cách khắc nghiệt.'),
(1548, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 1, 15, 'OT', 'Vua Ai Cập nói với các bà đỡ người Hê-bơ-rơ, tên một người là Siếp-ra, tên người kia là Phu-a,'),
(1549, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 1, 16, 'OT', 'Hãy nói rằng: Khi các ngươi đỡ đẻ cho các phụ nữ Hê-bơ-rơ, nếu thấy sinh con trai thì hãy giết nó đi; còn nếu là con gái thì để cho sống.'),
(1550, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 1, 17, 'OT', 'Nhưng các bà đỡ kính sợ Đức Chúa Trời, không làm theo điều vua Ai Cập đã dặn bảo, mà giữ cho các con trai sống.'),
(1551, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 1, 18, 'OT', 'Vua Ai Cập gọi các bà đỡ mà nói với họ: "Tại sao các ngươi làm điều này, để cho các con trai sống?"'),
(1552, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 1, 19, 'OT', 'Các bà đỡ thưa cùng Pha-ra-ôn rằng: "Bởi vì đàn bà Hê-bơ-rơ không giống như đàn bà Ê-díp-tô; họ mạnh mẽ, sinh con trước khi bà đỡ đến với họ."'),
(1553, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 1, 20, 'OT', 'Đức Chúa Trời làm ơn cho các bà đỡ; dân sự gia tăng và trở nên mạnh mẽ rất nhiều.'),
(1554, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 1, 21, 'OT', 'Vì các bà đỡ kính sợ Đức Chúa Trời, nên Ngài làm cho các bà có nhà.'),
(1555, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 1, 22, 'OT', 'Vua Pha-ra-ôn truyền lệnh cho toàn dân mình rằng: "Mọi con trai của người Hê-bơ-rơ mới sinh, phải ném xuống sông; còn mọi con gái, thì để cho sống."'),
(1556, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 2, 1, 'OT', 'Một người của nhà Lê-vi đi lấy một con gái của Lê-vi làm vợ.'),
(1557, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 2, 2, 'OT', 'Người đàn bà thọ thai, sinh một con trai; thấy đứa trẻ xinh đẹp, liền giấu nó ba tháng.'),
(1558, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 2, 3, 'OT', 'Nhưng không thể giấu em bé được nữa, người phụ nữ bèn lấy một cái thúng bằng cây sậy, trét nhựa chai và nhựa thông vào, rồi đặt đứa trẻ vào trong đó, và đặt nó giữa đám sậy bên bờ sông.'),
(1559, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 2, 4, 'OT', 'Chị của nó đứng từ xa để xem điều gì sẽ xảy ra với nó.'),
(1560, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 2, 5, 'OT', 'Con gái Pha-ra-ôn đi xuống sông để tắm, các nữ tì của nàng đi dọc bờ sông; nàng thấy cái hòm trong bụi sậy, liền sai nữ tì mình đi lấy lên.'),
(1561, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 2, 6, 'OT', 'Mở ra, thấy đứa trẻ, là một đứa con trai đang khóc, bèn thương xót nó và nói: "Đây là một đứa trẻ Hê-bơ-rơ."'),
(1562, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 2, 7, 'OT', 'Người chị của đứa trẻ nói với con gái của Pha-ra-ôn: "Tôi phải đi gọi cho bà một người đàn bà Hê-bơ-rơ làm vú nuôi để cho đứa trẻ bú chứ?"'),
(1563, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 2, 8, 'OT', 'Công chúa nói cùng nàng: Hãy đi. Nàng liền đi và gọi mẹ của đứa trẻ.'),
(1564, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 2, 9, 'OT', 'Cô gái của Pha-ra-ôn nói với nàng rằng: "Hãy mang đứa trẻ này đi, cho nó bú cho tôi, và tôi sẽ trả công cho cô." Người phụ nữ bèn nhận lấy đứa trẻ và cho nó bú.'),
(1565, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 2, 10, 'OT', 'Đứa trẻ lớn lên, người đàn bà đem nó đến cho con gái của Pha-ra-ôn, và nó trở thành con trai của bà; bà đặt tên nó là Môi-se, và nói: "Vì tôi đã vớt nó từ trong nước."'),
(1566, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 2, 11, 'OT', 'Một ngày nọ, khi Môi-se đã trưởng thành, ông ra đi đến cùng anh em mình và thấy cảnh lao động cực nhọc của họ; ông cũng thấy một người Ai Cập đánh một người Hê-bơ-rơ trong vòng anh em mình.'),
(1567, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 2, 12, 'OT', 'Ngó nầy qua nọ, thấy chẳng có ai, bèn đánh người Ai Cập và chôn hắn trong cát.'),
(1568, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 2, 13, 'OT', 'Ngày hôm sau, Môi-se đi ra và nầy, hai người Hê-bơ-rơ đang đánh nhau; ông nói với kẻ có lỗi: "Tại sao ngươi đánh người đồng loại mình?"'),
(1569, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 2, 14, 'OT', 'Người ấy nói: Ai đã đặt ngươi làm người lãnh đạo và quan xét trị chúng ta? Có phải ngươi định giết ta như đã giết người Ai Cập kia chăng? Môi-se sợ hãi và nói: Thật vậy, việc ấy đã lộ ra rồi.'),
(1570, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 2, 15, 'OT', 'Pha-ra-ôn nghe tin đó thì tìm giết Môi-se; nhưng Môi-se trốn khỏi mặt Pha-ra-ôn, đi đến xứ Ma-đi-an và ngồi bên một cái giếng.'),
(1571, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 2, 16, 'OT', 'Thầy tế lễ xứ Ma-đi-an có bảy con gái; các nàng đến, xách nước đổ đầy máng để cho bầy chiên của cha mình uống.'),
(1572, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 2, 17, 'OT', 'Các kẻ chăn chiên đến và xua đuổi các nàng ấy; Môi-se bèn đứng dậy, cứu giúp các nàng và cho bầy chiên của các nàng uống nước.'),
(1573, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 2, 18, 'OT', 'Các nàng trở về cùng Rê-u-ên, cha mình; người hỏi: "Tại sao hôm nay các con về sớm vậy?"'),
(1574, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 2, 19, 'OT', 'Các cô thưa rằng: Một người Ai Cập đã cứu chúng tôi khỏi tay những kẻ chăn chiên, và cũng xách nước múc đầy cho chúng tôi nữa, rồi cho bầy chiên uống.'),
(1575, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 2, 20, 'OT', 'Người nói với các con gái mình: "Tại sao các con lại bỏ người đàn ông ấy? Hãy gọi người đến để người ăn bánh."'),
(1576, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 2, 21, 'OT', 'Môi-se bằng lòng ở lại với người ấy, và người ấy đã gả Sê-phô-ra, con gái mình, cho Môi-se.'),
(1577, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 2, 22, 'OT', 'Sinh một trai, đặt tên là Ghẹt-sôn, vì nói rằng: Tôi là kẻ khách lạ tại đất ngoại bang.'),
(1578, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 2, 23, 'OT', 'Các ngày dài ấy kéo dài, vua nước Ai Cập băng hà; con cháu Y-sơ-ra-ên thở than vì công việc khổ sở, và kêu lên; tiếng kêu của họ vì công việc khổ sở đã dâng lên Đức Chúa Trời.'),
(1579, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 2, 24, 'OT', 'Đức Chúa Trời nghe tiếng khóc than của họ, và Đức Chúa Trời nhớ đến giao ước Ngài lập cùng Aùp-ra-ham, Y-sác và Gia-cốp.'),
(1580, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 2, 25, 'OT', 'Đức Chúa Trời nhìn xem con cái Y-sơ-ra-ên, và Đức Chúa Trời biết rõ tình cảnh của họ.'),
(1581, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 3, 1, 'OT', 'Môi-se chăn bầy chiên của Giê-trô, cha vợ mình, thầy tế lễ xứ Ma-đi-an; ông dẫn bầy chiên qua phía xa của đồng vắng và đến núi Đức Chúa Trời, là Hô-rếp.'),
(1582, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 3, 2, 'OT', 'Thiên sứ của Đức Giê-hô-va hiện ra cùng người trong ngọn lửa giữa bụi gai; người nhìn thấy và nầy, bụi gai cháy trong lửa, nhưng bụi gai không hề bị thiêu đốt.'),
(1583, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 3, 3, 'OT', 'Môi-se nói: "Tôi xin tấp lại xem cái dị tượng lớn này, tại sao bụi gai không cháy hết?"'),
(1584, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 3, 4, 'OT', 'Đức Giê-hô-va thấy Môi-se tẽ bước lại xem, thì Đức Chúa Trời gọi người từ giữa bụi gai và nói: "Môi-se, Môi-se!" Môi-se đáp: "Có tôi đây!"'),
(1585, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 3, 5, 'OT', 'Đức Chúa Trời phán: Đừng lại gần; hãy cởi giày ngươi ra khỏi chân ngươi, vì chỗ ngươi đang đứng là đất thánh.'),
(1586, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 3, 6, 'OT', 'Ta là Đức Chúa Trời của tổ phụ ngươi, Đức Chúa Trời của Aùp-ra-ham, Đức Chúa Trời của Y-sác và Đức Chúa Trời của Gia-cốp. Môi-se liền che mặt mình, vì sợ nhìn đến Đức Chúa Trời.'),
(1587, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 3, 7, 'OT', 'Đức Giê-hô-va phán: Ta đã nhìn thấy rõ sự khốn khổ của dân Ta ở Ai-cập, và đã nghe tiếng kêu than của họ vì những người cai đói; phải, Ta biết được nỗi đau đớn của họ.'),
(1588, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 3, 8, 'OT', 'Ta đã xuống để giải cứu họ khỏi tay người Ai-cập và đưa họ lên khỏi đất ấy đến một đất tốt và rộng lớn, một đất chảy sữa và mật, tức là nơi đất của người Ca-na-an, người Hê-tít, người A-mô-rít, người Phê-rê-sít, người Hê-vít và người Giê-bu-sít.'),
(1589, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 3, 9, 'OT', 'Nầy, tiếng kêu của con cái Y-sơ-ra-ên đã thấu đến ta; và ta cũng đã thấy sự hà hiếp mà người Ê-díp-tô dùng để áp bức chúng nó.'),
(1590, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 3, 10, 'OT', 'Vậy bây giờ, hãy đi, ta sẽ sai ngươi đến cùng Pha-ra-ôn, để đưa dân ta, là con cháu Y-sơ-ra-ên, ra khỏi xứ Ai-cập.'),
(1591, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 3, 11, 'OT', 'Môi-se thưa cùng Đức Chúa Trời: Tôi là ai, mà tôi dám đi đến Pha-ra-ôn, và dám đem con cái Y-sơ-ra-ên ra khỏi xứ Ai-cập?'),
(1592, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 3, 12, 'OT', 'Đức Chúa Trời phán: Ta sẽ ở cùng ngươi, và đây là dấu cho ngươi biết rằng chính Ta đã sai ngươi đi: khi ngươi dẫn dân ra khỏi Ai Cập, thì các ngươi sẽ thờ phượng Đức Chúa Trời trên ngọn núi nầy.'),
(1593, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 3, 13, 'OT', 'Môi-se thưa cùng Đức Chúa Trời: "Nầy, tôi sẽ đi đến con cái Y-sơ-ra-ên và nói với họ: Đức Chúa Trời của tổ phụ các ngươi đã sai tôi đến cùng các ngươi. Nhưng nếu họ hỏi tôi: Danh Ngài là gì? thì tôi phải nói gì với họ?"'),
(1594, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 3, 14, 'OT', 'Đức Chúa Trời phán cùng Môi-se rằng: Ta sẽ là Đấng Ta sẽ là; rồi phán: Ngươi hãy nói cùng con cái Y-sơ-ra-ên như thế này: Ta sẽ là đã sai ta đến cùng các ngươi.'),
(1595, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 3, 15, 'OT', 'Đức Chúa Trời phán thêm cùng Môi-se: "Ngươi sẽ nói cùng con cái Y-sơ-ra-ên như thế này: Đức Giê-hô-va, Đức Chúa Trời của tổ phụ các ngươi, Đức Chúa Trời của Aùp-ra-ham, Đức Chúa Trời của Y-sác và Đức Chúa Trời của Gia-cốp, đã sai ta đến cùng các ngươi. Đây là danh ta đời đời, và đây là sự tưởng nhớ ta cho các thế hệ tiếp nối."'),
(1596, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 3, 16, 'OT', 'Hãy đi và nhóm các trưởng lão Y-sơ-ra-ên lại, rồi nói với họ: Đức Giê-hô-va, Đức Chúa Trời của tổ phụ các ngươi, Đức Chúa Trời của Aùp-ra-ham, Y-sác và Gia-cốp, đã hiện ra cùng ta mà phán: Ta đã thăm viếng các ngươi và thấy điều đã xảy ra cho các ngươi tại Ai-cập,'),
(1597, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 3, 17, 'OT', 'Ta đã phán rằng: Ta sẽ đưa các ngươi lên khỏi cảnh khốn khổ tại Ai-cập, đến xứ của người Ca-na-an, người Hê-tít, người A-mô-rít, người Phê-rê-sít, người Hê-vít và người Giê-bu-sít, là một xứ chảy sữa và mật.'),
(1598, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 3, 18, 'OT', 'Dân sự sẽ nghe theo lời ngươi; ngươi và các trưởng lão Y-sơ-ra-ên hãy đến cùng vua Ai Cập mà tâu rằng: Đức Giê-hô-va Đức Chúa Trời của người Hê-bơ-rơ đã hiện ra cùng chúng tôi; vậy bây giờ, xin để chúng tôi đi ba ngày đường vào đồng vắng đặng dâng lễ tế cho Đức Giê-hô-va Đức Chúa Trời chúng tôi.'),
(1599, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 3, 19, 'OT', 'Ta biết rõ rằng dù dùng tay quyền năng, vua Ê-díp-tô cũng sẽ không cho các ngươi đi.'),
(1600, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 3, 20, 'OT', 'Ta sẽ giơ tay ra và đánh xứ Ai Cập bằng mọi phép lạ mà Ta sẽ làm giữa họ; sau đó họ sẽ cho các ngươi đi.'),
(1601, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 3, 21, 'OT', 'Ta sẽ ban ơn cho dân nầy trước mắt người Ai-cập; và khi các ngươi ra đi, các ngươi sẽ không ra đi tay không.'),
(1602, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 3, 22, 'OT', 'Mỗi người phụ nữ sẽ xin từ người nữ hàng xóm mình và từ người ở trong nhà mình những đồ bằng bạc, những đồ bằng vàng và quần áo; các ngươi sẽ mặc những thứ đó lên con trai và con gái mình; và các ngươi sẽ lấy hết tài sản của người Ai Cập.'),
(1603, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 4, 1, 'OT', 'Môi-se thưa lại rằng: Nhưng dân đó sẽ không tin tôi, cũng không nghe tiếng tôi, vì họ sẽ nói: Đức Giê-hô-va chưa từng hiện ra cùng ngươi.'),
(1604, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 4, 2, 'OT', 'Đức Giê-hô-va phán cùng người rằng: Trong tay ngươi có cái gì? Người thưa rằng: Một cây gậy.'),
(1605, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 4, 3, 'OT', 'Người phán: "Hãy ném xuống đất." Người bèn ném xuống đất, và nó trở thành một con rắn; Môi-se chạy trốn khỏi mặt nó.'),
(1606, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 4, 4, 'OT', 'Đức Giê-hô-va phán cùng Môi-se: "Hãy đưa tay ngươi ra và nắm lấy đuôi nó." Người đưa tay ra và nắm lấy nó, thì nó trở thành cây gậy trong tay người.'),
(1607, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 4, 5, 'OT', 'để họ tin rằng Đức Giê-hô-va, Đức Chúa Trời của tổ phụ họ, Đức Chúa Trời của Aùp-ra-ham, Đức Chúa Trời của Y-sác và Đức Chúa Trời của Gia-cốp đã hiện ra cùng ngươi'),
(1608, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 4, 6, 'OT', 'Đức Giê-hô-va phán cùng người rằng: Hãy đưa tay ngươi vào lòng ngươi nữa. Người liền đưa tay vào lòng, rồi rút ra; nầy, tay người bị phung trắng như tuyết.'),
(1609, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 4, 7, 'OT', 'Hãy đưa tay trở lại vào lòng ngươi. Người liền đưa tay trở lại vào lòng mình; rồi rút ra, và nầy, tay người trở lại như thịt mình.'),
(1610, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 4, 8, 'OT', 'Nếu họ không tin ngươi và không nghe theo tiếng của dấu hiệu đầu tiên, thì họ sẽ tin theo tiếng của dấu hiệu sau rốt.'),
(1611, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 4, 9, 'OT', 'Nếu họ không tin và không nghe theo lời ngươi, dù cho cả hai dấu ấy, thì ngươi hãy lấy nước từ sông và đổ lên đất khô; và nước mà ngươi lấy từ sông sẽ trở thành huyết trên mặt đất.'),
(1612, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 4, 10, 'OT', 'Môi-se thưa cùng Đức Giê-hô-va rằng: Lạy Đức Giê-hô-va, tôi vốn không phải người giỏi nói, chẳng những từ hôm qua, hôm kia, mà ngay cả từ khi Ngài phán cùng tôi tớ Ngài, vì tôi nặng miệng và nặng lưỡi.'),
(1613, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 4, 11, 'OT', 'Đức Giê-hô-va phán với người rằng: Ai đặt miệng cho loài người? Hay là ai làm cho người câm, hay điếc, hay sáng, hay mù? Há chẳng phải chính ta là Đức Giê-hô-va sao?'),
(1614, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 4, 12, 'OT', 'Vậy bây giờ, hãy đi; Ta sẽ ở cùng miệng ngươi và chỉ dạy ngươi điều ngươi phải nói.'),
(1615, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 4, 13, 'OT', 'Môi-se thưa rằng: Xin Chúa, xin hãy sai người nào mà Chúa muốn sai.'),
(1616, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 4, 14, 'OT', 'Đức Giê-hô-va nổi giận cùng Môi-se, phán rằng: Chẳng phải A-rôn, anh ngươi, người Lê-vi, sao? Ta biết người ấy có tài nói; hơn nữa, nầy, người ấy đang đi ra đón ngươi; người thấy ngươi sẽ mừng trong lòng.'),
(1617, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 4, 15, 'OT', 'Ngươi sẽ nói với người ấy và đặt những lời đó vào miệng người ấy; chính Ta sẽ ở cùng miệng ngươi và miệng người ấy, và Ta sẽ dạy cho các ngươi điều các ngươi phải làm.'),
(1618, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 4, 16, 'OT', 'Người ấy sẽ nói cùng ngươi để truyền đạt cho dân chúng; người ấy sẽ làm miệng cho ngươi, còn ngươi sẽ làm Đức Chúa Trời cho người ấy.'),
(1619, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 4, 17, 'OT', 'Và cây gậy nầy, ngươi hãy cầm lấy nơi tay, mà dùng nó làm các dấu kỳ.'),
(1620, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 4, 18, 'OT', 'Môi-se bèn đi trở về cùng Giê-trô, cha vợ mình, và nói với người rằng: "Tôi xin đi trở về cùng anh em tôi tại Ai-cập, để xem họ còn sống hay không." Giê-trô nói với Môi-se: "Hãy đi bình an."'),
(1621, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 4, 19, 'OT', 'Đức Giê-hô-va phán cùng Môi-se tại Ma-đi-an rằng: Hãy đi, trở về xứ Ê-díp-tô, vì mọi người tìm giết ngươi đều đã chết hết.'),
(1622, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 4, 20, 'OT', 'Môi-se rước vợ và các con mình, đặt lên lưng lừa, rồi trở về đất Ê-díp-tô; và Môi-se cầm cây gậy của Đức Chúa Trời trong tay.'),
(1623, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 4, 21, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Khi ngươi trở về Ai-cập, hãy nhìn xem mọi dấu kỳ mà ta đã đặt nơi tay ngươi, và ngươi hãy làm các dấu kỳ đó trước mặt Pha-ra-ôn; nhưng ta sẽ khiến lòng người ra cứng cỏi, và người sẽ không để cho dân sự đi.'),
(1624, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 4, 22, 'OT', 'Hãy nói cùng Pha-ra-ôn rằng: Đức Giê-hô-va phán như vầy: Y-sơ-ra-ên là con ta, con cả ta.'),
(1625, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 4, 23, 'OT', 'Ta đã bảo ngươi: Hãy để con Ta đi, để nó hầu việc Ta; nhưng ngươi từ chối không cho đi. Nầy, Ta sẽ giết con trai ngươi, con đầu lòng của ngươi.'),
(1626, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 4, 24, 'OT', 'Dọc đường, tại một nơi nghỉ ngơi, Đức Giê-hô-va gặp gỡ người, và tìm cách giết ông.'),
(1627, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 4, 25, 'OT', 'Sê-phô-ra lấy một hòn đá, cắt phần bì cho con trai mình, rồi cầm lấy và ném vào chân Môi-se, mà nói rằng: Ngươi thật là chồng bằng máu đối với ta.'),
(1628, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 4, 26, 'OT', 'Ngài bèn buông tha người ấy; lúc ấy nàng nói: Chồng bằng máu, vì cớ các phép cắt bì.'),
(1629, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 4, 27, 'OT', 'Đức Giê-hô-va phán cùng A-rôn: "Hãy đi ra đồng vắng đón Môi-se." A-rôn bèn đi, và gặp người tại núi của Đức Chúa Trời, rồi hôn người.'),
(1630, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 4, 28, 'OT', 'Môi-se thuật lại cho A-rôn mọi lời của Đức Giê-hô-va mà Ngài đã sai mình đến, và mọi dấu hiệu mà Ngài đã truyền dặn mình làm.'),
(1631, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 4, 29, 'OT', 'Môi-se và A-rôn đi, nhóm lại tất cả các trưởng lão của con cái Y-sơ-ra-ên.'),
(1632, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 4, 30, 'OT', 'A-rôn nói các lời ấy mà Đức Giê-hô-va đã phán cùng Môi-se, và làm các dấu lạ trước mắt dân sự.'),
(1633, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 4, 31, 'OT', 'Dân chúng tin theo, và nghe rằng Đức Giê-hô-va đã đoái đến con cái Y-sơ-ra-ên, và đã thấy cảnh khốn khổ của họ; rồi họ cúi lạy và thờ lạy.'),
(1634, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 5, 1, 'OT', 'Sau đó, Môi-se và A-rôn đến cùng Pha-ra-ôn và nói: "Đức Giê-hô-va, Đức Chúa Trời của Y-sơ-ra-ên, phán như vầy: Hãy để dân ta đi, để chúng giữ lễ cho Ta trong đồng vắng."'),
(1635, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 5, 2, 'OT', 'Pha-ra-ôn nói: "Giê-hô-va là ai mà ta phải nghe theo tiếng của Ngài, để cho Y-sơ-ra-ên đi? Ta không biết Giê-hô-va, và cũng sẽ không cho Y-sơ-ra-ên đi."'),
(1636, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 5, 3, 'OT', 'Môi-se và A-rôn nói: Đức Chúa Trời của dân Hê-bơ-rơ đã gọi chúng tôi; xin hãy để chúng tôi đi ba ngày đường vào trong đồng vắng, hầu dâng của lễ cho Đức Giê-hô-va Đức Chúa Trời chúng tôi, e Ngài giáng trên chúng tôi cơn dịch hoặc gươm dao chăng.'),
(1637, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 5, 4, 'OT', 'Vua Ai Cập nói với Môi-se và A-rôn rằng: "Tại sao Môi-se và A-rôn khiến cho dân chúng rời khỏi công việc của họ? Hãy đi làm công việc mình!"'),
(1638, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 5, 5, 'OT', 'Pha-ra-ôn nói: Kìa, bây giờ dân trong đất đã đông rồi, mà hai ngươi lại muốn khiến họ thôi làm các công việc nặng nhọc của họ sao?'),
(1639, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 5, 6, 'OT', 'Trong ngày đó, Pha-ra-ôn ra lệnh cho các đốc công và các viên chức cai quản dân rằng:'),
(1640, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 5, 7, 'OT', 'Đừng tiếp tục cấp rơm cho dân để làm gạch như trước đây nữa; chính họ phải đi tìm lấy rơm cho mình.'),
(1641, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 5, 8, 'OT', 'Nhưng các ngươi hãy giao cho chúng số gạch như trước đây, không được bớt lại chút nào, vì chúng biếng nhác nên mới kêu lên rằng: Hãy đi, dâng tế lễ cho Đức Chúa Trời của chúng ta!'),
(1642, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 5, 9, 'OT', 'Hãy làm cho công việc nặng nề hơn đối với những người này, và họ sẽ làm nó, và đừng để họ tin vào những lời nói dối.'),
(1643, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 5, 10, 'OT', 'Các đốc công và các viên chức ra đi, nói với dân rằng: Pha-ra-ôn phán như vầy: Ta sẽ không cấp rơm cho các ngươi nữa.'),
(1644, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 5, 11, 'OT', 'Hãy đi, tự các ngươi lấy rơm ở bất cứ nơi nào các ngươi tìm được; vì không điều gì sẽ bị trừ khỏi công việc của các ngươi.'),
(1645, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 5, 12, 'OT', 'Dân chúng bèn đi tản ra khắp đất Ai Cập để nhặt rơm thế cho rạ.'),
(1646, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 5, 13, 'OT', 'Các đốc công thúc giục rằng: Hãy làm xong công việc của các ngươi, mỗi ngày một phần, như khi còn có rơm.'),
(1647, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 5, 14, 'OT', 'Các thợ quản đốc của con cái Y-sơ-ra-ên mà các đốc công của Pha-ra-ôn đặt lên trên họ, bị đánh và bị hỏi rằng: "Tại sao hôm qua và hôm nay các ngươi không làm xong số gạch chỉ định cho các ngươi như hôm kia?"'),
(1648, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 5, 15, 'OT', 'Các đốc công của con cái Y-sơ-ra-ên đến kêu cùng Pha-ra-ôn rằng: Vì sao ngài làm như thế nầy cho kẻ tôi tớ của ngài?'),
(1649, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 5, 16, 'OT', 'Rơm thì không cấp cho đầy tớ của ngài, mà lại bảo chúng tôi rằng: "Hãy làm gạch đi!" Nầy, những đầy tớ của ngài đây đang bị đánh, nhưng lỗi lại tại dân của ngài.'),
(1650, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 5, 17, 'OT', 'Nhưng vua nói: Các ngươi biếng nhác, biếng nhác thật! Vì vậy các ngươi mới nói: Hãy để chúng tôi đi dâng lễ cho Đức Giê-hô-va!'),
(1651, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 5, 18, 'OT', 'Vậy bây giờ, hãy đi làm việc đi; các ngươi sẽ không được cấp rơm, nhưng vẫn phải nộp số gạch như thường lệ.'),
(1652, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 5, 19, 'OT', 'Các cai đội của con cái Y-sơ-ra-ên thấy mình bị khốn khổ, khi người ta nói rằng: Các ngươi không được bớt gạch của mình đi, mỗi ngày phải nộp số gạch như ngày nào.'),
(1653, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 5, 20, 'OT', 'Khi Môi-se và A-rôn đi ra khỏi Pha-ra-ôn, thì họ gặp Môi-se và A-rôn đang đứng đó chờ họ.'),
(1654, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 5, 21, 'OT', 'Họ nói với họ: "Nguyện Đức Giê-hô-va nhìn xem và xét đoán các ngươi, vì các ngươi đã làm cho mùi vị chúng tôi trở nên hôi hám trước mắt Pha-ra-ôn và trước mắt các tôi tớ ông, để trao vào tay họ gươm mà giết chúng tôi."'),
(1655, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 5, 22, 'OT', 'Môi-se trở về cùng Đức Giê-hô-va và thưa rằng: Lạy Đức Giê-hô-va, tại sao Ngài làm hại dân này? Tại sao Ngài sai tôi đến đây?'),
(1656, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 5, 23, 'OT', 'Từ khi tôi đến yết kiến Pha-ra-ôn để nhân danh Đức Giê-hô-va mà nói, thì người lại làm ác cho dân nầy, và Đức Giê-hô-va chẳng giải cứu dân của Ngài.'),
(1657, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 6, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Bây giờ ngươi sẽ thấy điều ta sẽ làm cho Pha-ra-ôn; vì nhờ tay quyền năng, người ấy sẽ thả họ, và nhờ tay quyền năng, người ấy sẽ đuổi họ ra khỏi đất nước mình.'),
(1658, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 6, 2, 'OT', 'Đức Chúa Trời phán cùng Môi-se và nói với người: Ta là Đức Giê-hô-va.'),
(1659, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 6, 3, 'OT', 'Ta đã hiện ra cùng Aùp-ra-ham, cùng Y-sác và cùng Gia-cốp trong danh Đức Chúa Trời Toàn Năng, nhưng với danh Ta là Đức Giê-hô-va, Ta không tỏ cho họ biết.'),
(1660, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 6, 4, 'OT', 'Và Ta cũng đã lập giao ước của Ta với họ, để ban cho họ đất Ca-na-an, là đất nơi họ đã kiều ngụ như khách lạ.'),
(1661, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 6, 5, 'OT', 'Ta cũng đã nghe tiếng kêu than của con cái Y-sơ-ra-ên, là dân mà người Ê-díp-tô bắt làm tôi mọi, và Ta nhớ lại giao ước của Ta.'),
(1662, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 6, 6, 'OT', 'Vì vậy, hãy nói cùng con cái Y-sơ-ra-ên rằng: Ta là Đức Giê-hô-va, chính Ta sẽ đem các ngươi ra khỏi dưới gánh nặng của người Ai-cập, giải cứu các ngươi khỏi cảnh làm tôi mọi, và lấy cánh tay giơ thẳng ra cùng những điều xét xử lớn lao mà cứu chuộc các ngươi.'),
(1663, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 6, 7, 'OT', 'Ta sẽ nhận các ngươi làm dân Ta, và Ta sẽ làm Đức Chúa Trời của các ngươi; các ngươi sẽ biết rằng chính Ta là Giê-hô-va Đức Chúa Trời của các ngươi, là Đấng đem các ngươi ra khỏi gánh nặng của người Ai-cập.'),
(1664, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 6, 8, 'OT', 'Và Ta sẽ dẫn các ngươi vào đất mà Ta đã giơ tay thề ban cho Aùp-ra-ham, cho Y-sác và cho Gia-cốp; và Ta sẽ ban đất đó cho các ngươi làm cơ nghiệp; Ta là Đức Giê-hô-va.'),
(1665, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 6, 9, 'OT', 'Môi-se nói như vậy cho con cái Y-sơ-ra-ên, nhưng họ không nghe Môi-se, vì tâm thần hụt hẫng và vì công việc nặng nhọc.'),
(1666, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 6, 10, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(1667, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 6, 11, 'OT', 'Hãy đi, nói cùng Pha-ra-ôn, vua xứ Ai-cập, phải để dân Y-sơ-ra-ên ra khỏi đất nước mình.'),
(1668, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 6, 12, 'OT', 'Nhưng Môi-se thưa cùng Đức Giê-hô-va rằng: Nầy, dân Y-sơ-ra-ên chẳng nghe tôi, thì Pha-ra-ôn há sẽ nghe tôi sao? Tôi là người vụng về lời nói.'),
(1669, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 6, 13, 'OT', 'Đức Giê-hô-va phán cùng Môi-se và A-rôn, rồi truyền cho hai người đến cùng con cái Y-sơ-ra-ên và Pha-ra-ôn, vua xứ Ê-díp-tô, để đem con cái Y-sơ-ra-ên ra khỏi đất Ê-díp-tô.'),
(1670, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 6, 14, 'OT', 'Này là các tổ trưởng theo nhà họ của mình: con trai Ru-bên, trưởng tử Y-sơ-ra-ên, là Hê-nóc, Pha-lu, Hết-rôn và Cạt-mi; ấy là các chi họ của Ru-bên.'),
(1671, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 6, 15, 'OT', 'Các con trai của Si-mê-ôn là Giê-mu-ên, Gia-min, Ô-hát, Gia-kin, Xô-ha và Sau-lơ là con trai của người Ca-na-an. Đó là các dòng họ của Si-mê-ôn.'),
(1672, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 6, 16, 'OT', 'Đây là các tên con trai của Lê-vi theo dòng dõi của họ: Ghẹt-sôn, Kê-hát và Mê-ra-ri. Và số năm của đời Lê-vi là một trăm ba mươi bảy năm.'),
(1673, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 6, 17, 'OT', 'Các con trai của Ghẹt-sôn, theo các họ hàng của họ: Líp-ni và Si-mê-y.'),
(1674, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 6, 18, 'OT', 'Các con trai của Kê-hát là Am-ram, Dít-sê-ha, Hếp-rôn và U-xi-ên. Tuổi thọ của Kê-hát là một trăm ba mươi ba năm.'),
(1675, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 6, 19, 'OT', 'Các con trai của Mê-ra-ri là Mách-li và Mu-si. Đó là các chi họ của Lê-vi, theo các thế hệ của họ.'),
(1676, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 6, 20, 'OT', 'Am-ram lấy Giô-kê-bết, là cô mình, làm vợ; nàng sanh cho người A-rôn và Môi-se. Tuổi thọ của Am-ram là một trăm ba mươi bảy năm.'),
(1677, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 6, 21, 'OT', 'Các con trai của Dít-sê-ha là Cô-rê, Nê-phết và Xiếc-ri.'),
(1678, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 6, 22, 'OT', 'Các con trai của U-xi-ên là Mi-sa-ên, Eân-sa-phan và Sít-ri.'),
(1679, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 6, 23, 'OT', 'A-rôn cưới Ê-li-sê-ba, con gái của A-mi-na-đáp, em gái của Na-ha-sôn, làm vợ; và nàng sanh cho người các con trai là Na-đáp, A-bi-hu, Ê-lê-a-sa và Y-tha-ma.'),
(1680, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 6, 24, 'OT', 'Các con trai của Cô-rê là Aùt-si, Eân-ca-na và A-bi-a-sáp; ấy là các họ hàng của người Cô-rê.'),
(1681, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 6, 25, 'OT', 'Ê-lê-a-sa, con trai của A-rôn, lấy con gái của Phu-ti-ên làm vợ; và nàng sanh cho người con trai Phi-nê-a. Đó là các tổ trưởng của các gia tộc người Lê-vi, theo các họ hàng của họ.'),
(1682, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 6, 26, 'OT', 'A-rôn và Môi-se là những người mà Đức Giê-hô-va đã phán dạy rằng: Hãy đem con cái Y-sơ-ra-ên ra khỏi đất Ê-díp-tô tùy theo đạo quân của họ.'),
(1683, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 6, 27, 'OT', 'Chính họ là những người nói với Pha-ra-ôn, vua nước Ai-cập, để đưa con cái Y-sơ-ra-ên ra khỏi Ai-cập; chính Môi-se và A-rôn.'),
(1684, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 6, 28, 'OT', 'Vậy, trong ngày Đức Giê-hô-va phán cùng Môi-se tại đất Ai-cập,'),
(1685, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 6, 29, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: "Ta là Đức Giê-hô-va; hãy nói với Pha-ra-ôn, vua Ai-cập, tất cả những điều Ta phán cùng ngươi."'),
(1686, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 6, 30, 'OT', 'Môi-se thưa cùng Đức Giê-hô-va rằng: Nầy, tôi là người môi miệng nặng nề; Pha-ra-ôn há sẽ nghe tôi sao?'),
(1687, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 7, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Hãy xem, ta đã đặt ngươi làm Đức Chúa Trời cho Pha-ra-ôn, và A-rôn anh ngươi sẽ làm đấng tiên tri cho ngươi.'),
(1688, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 7, 2, 'OT', 'Ngươi sẽ nói lại mọi điều ta truyền cho ngươi, và A-rôn, anh ngươi, sẽ nói với Pha-ra-ôn, để người thả các con trai Y-sơ-ra-ên ra khỏi đất nước mình.'),
(1689, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 7, 3, 'OT', 'Ta sẽ làm cho lòng Pha-ra-ôn trở nên cứng cỏi, và ta sẽ gia tăng các dấu kỳ và phép lạ của ta trong đất Ai-cập.'),
(1690, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 7, 4, 'OT', 'Nhưng Pha-ra-ôn sẽ không nghe các ngươi; ta sẽ tra tay ta vào xứ Ê-díp-tô, và đem các đạo quân ta, là dân Y-sơ-ra-ên, ra khỏi đất Ê-díp-tô bằng những sự đoán phạt lớn.'),
(1691, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 7, 5, 'OT', 'Các người Ê-díp-tô sẽ biết ta là Đức Giê-hô-va, khi ta giơ tay ra chống lại xứ Ê-díp-tô và đem dân Y-sơ-ra-ên ra khỏi giữa họ.'),
(1692, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 7, 6, 'OT', 'Môi-se và A-rôn làm y như điều Đức Giê-hô-va đã truyền dặn hai người; chính như vậy hai người đã làm.'),
(1693, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 7, 7, 'OT', 'Môi-se tám mươi tuổi, và A-rôn tám mươi ba tuổi, khi hai người nói với Pha-ra-ôn.'),
(1694, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 7, 8, 'OT', 'Đức Giê-hô-va phán cùng Môi-se và A-rôn, rằng:'),
(1695, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 7, 9, 'OT', 'Khi nào Pha-ra-ôn nói với các ngươi rằng: Hãy làm một phép lạ đi, thì ngươi sẽ nói cùng A-rôn: Hãy lấy cây gậy của ngươi và ném trước mặt Pha-ra-ôn, nó sẽ hóa thành một con rắn.'),
(1696, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 7, 10, 'OT', 'Môi-se và A-rôn đến cùng Pha-ra-ôn và làm như Đức Giê-hô-va đã truyền dạy; A-rôn ném cây gậy của mình trước mặt Pha-ra-ôn và các tôi tớ người, thì nó trở thành một con rắn.'),
(1697, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 7, 11, 'OT', 'Pha-ra-ôn cũng gọi các thầy thông thái và thầy phù thủy; các thầy phù thủy Ai Cập cũng dùng các phép thuật của mình làm giống như vậy.'),
(1698, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 7, 12, 'OT', 'Mỗi người liệng cây gậy mình xuống, thì biến thành rắn; và cây gậy của A-rôn nuốt các cây gậy của chúng nó.'),
(1699, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 7, 13, 'OT', 'Lòng Pha-ra-ôn vẫn cứng cỏi, không chịu nghe theo A-rôn và Môi-se, y như lời Đức Giê-hô-va đã phán.'),
(1700, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 7, 14, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Lòng Pha-ra-ôn đã cứng cỏi, từ chối không để cho dân ấy đi.'),
(1701, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 7, 15, 'OT', 'Sáng mai, hãy đi đến gặp Pha-ra-ôn khi người đang ra bờ sông; ngươi hãy đứng chờ người tại bờ sông, và cầm theo cây gậy đã biến thành rắn trong tay ngươi.'),
(1702, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 7, 16, 'OT', 'Hãy nói với người ấy: "Đức Giê-hô-va, Đức Chúa Trời của dân Hê-bơ-rơ, đã sai tôi đến cùng ngài, để nói rằng: Hãy để cho dân ta đi, hầu việc ta trong đồng vắng; nhưng đến nay, ngài vẫn chưa nghe theo."'),
(1703, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 7, 17, 'OT', 'Đức Giê-hô-va phán như vầy: Bởi điều nầy ngươi sẽ biết ta là Đức Giê-hô-va: Nầy, ta sẽ dùng cây gậy trong tay ta đập trên nước ở sông, và nước sẽ biến thành huyết.'),
(1704, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 7, 18, 'OT', 'Cá trong sông sẽ chết, và sông sẽ trở nên hôi thối; người Ai Cập sẽ kinh tởm khi uống nước từ sông.'),
(1705, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 7, 19, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Hãy nói cùng A-rôn rằng: Hãy cầm lấy cây gậy ngươi, và giơ tay ngươi ra trên các nước của xứ Ai-cập, trên các sông ngòi, ao hồ và mọi chỗ chứa nước, để trở nên huyết; huyết sẽ đầy khắp đất Ai-cập, cả trong các chén bằng gỗ lẫn bằng đá.'),
(1706, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 7, 20, 'OT', 'Vậy, Môi-se và A-rôn làm y như Đức Giê-hô-va đã truyền dạy; Môi-se giơ cây gậy lên, đánh vào nước trong sông trước mặt Pha-ra-ôn và các tôi tớ người, và mọi nước trong sông đều biến thành huyết.'),
(1707, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 7, 21, 'OT', 'Cá trong sông chết, nước sông trở nên hôi thối, người Ai Cập không thể uống được nước từ sông; huyết trải khắp đất nước Ai Cập.'),
(1708, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 7, 22, 'OT', 'Các thầy phù thủy Ai Cập cũng làm như vậy bằng những phù chú của mình; lòng Pha-ra-ôn trở nên cứng cỏi, và ông không nghe Môi-se và A-rôn, y như lời Đức Giê-hô-va đã phán.'),
(1709, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 7, 23, 'OT', 'Pha-ra-ôn xây đi về nhà mình, lòng chẳng để ý đến điều đó chút nào.'),
(1710, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 7, 24, 'OT', 'Vậy, hết thảy người Ai Cập đã đào xung quanh sông để tìm nước uống, vì họ không thể uống được nước sông ấy.'),
(1711, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 7, 25, 'OT', 'Đức Giê-hô-va đánh sông xong, đầy đủ bảy ngày.'),
(1712, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 8, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: "Hãy đi đến Pha-ra-ôn và nói cùng người rằng: Đức Giê-hô-va phán như vầy: Hãy để cho dân ta đi, để chúng nó hầu việc ta."'),
(1713, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 8, 2, 'OT', 'Nếu ngươi từ chối thả họ đi, hãy xem, chính Ta sẽ đánh khắp đất nước ngươi bằng những con ếch.'),
(1714, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 8, 3, 'OT', 'Sông sẽ đầy ếch nhái, chúng sẽ bò lên, vào trong nhà ngươi, vào buồng ngủ và trên giường ngươi, vào nhà các đầy tớ và dân sự ngươi, vào các lò nướng và các thùng nhồi bột của ngươi.'),
(1715, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 8, 4, 'OT', 'Ếch sẽ nhảy lên mình ngươi, lên dân sự ngươi và lên mọi đầy tớ ngươi.'),
(1716, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 8, 5, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: "Hãy nói cùng A-rôn rằng: Hãy giơ cây gậy của ngươi, vươn tay ngươi ra trên các sông, các chi lưu và các ao hồ, khiến cho ếch nhái tràn lên đất nước Ai Cập."'),
(1717, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 8, 6, 'OT', 'A-rôn giơ tay mình trên các nước của xứ Ai Cập, thì ếch nhái nổi lên và che phủ khắp đất Ai Cập.'),
(1718, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 8, 7, 'OT', 'Các thầy phù thủy cũng làm như vậy bằng những phù chú của họ, và những con ếch nhảy lên trên đất nước Ai Cập.'),
(1719, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 8, 8, 'OT', 'Pha-ra-ôn gọi Môi-se và A-rôn, rồi nói: Hãy cầu xin Đức Giê-hô-va khiến lũ ếch nhái rời khỏi ta và dân sự ta; thì ta sẽ thả dân Hê-bơ-rơ đi, để họ dâng tế lễ cho Đức Giê-hô-va.'),
(1720, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 8, 9, 'OT', 'Môi-se nói với Pha-ra-ôn: "Xin hãy chỉ định cho tôi thời điểm nào tôi sẽ cầu khẩn Đức Giê-hô-va vì ông, các đầy tớ ông và dân ông, để diệt sạch loài ếch ra khỏi ông và các nhà của ông; chỉ để lại chúng trong sông thôi."'),
(1721, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 8, 10, 'OT', 'Môi-se nói: Ngày mai. Và người nói: Như lời của ngài, để bệ hạ biết rằng không ai giống như Đức Giê-hô-va Đức Chúa Trời chúng tôi.'),
(1722, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 8, 11, 'OT', 'Các con ếch sẽ rời khỏi ngươi, nhà ngươi, đầy tớ ngươi và dân ngươi; chỉ còn lại trong sông mà thôi.'),
(1723, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 8, 12, 'OT', 'Môi-se và A-rôn đi ra khỏi Pha-ra-ôn; rồi Môi-se kêu lên cùng Đức Giê-hô-va về việc những con ếch mà Ngài đã khiến đặt trên Pha-ra-ôn.'),
(1724, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 8, 13, 'OT', 'Đức Giê-hô-va làm theo lời Môi-se; các con ếch chết hết khỏi trong nhà, trong sân và ngoài đồng.'),
(1725, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 8, 14, 'OT', 'Người ta chất đống những con ếch thành từng đống lớn, và đất trở nên hôi thối.'),
(1726, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 8, 15, 'OT', 'Pha-ra-ôn thấy nạn được giảm, liền làm cho lòng mình trở nên cứng cỏi, không nghe theo Môi-se và A-rôn, y như Đức Giê-hô-va đã phán.'),
(1727, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 8, 16, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Hãy nói cùng A-rôn rằng: Hãy giơ cây gậy của ngươi ra và đánh vào bụi trên đất, thì bụi đó sẽ trở thành muỗi khắp đất Ai-cập.'),
(1728, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 8, 17, 'OT', 'Hai người làm như vậy. A-rôn giơ tay mình ra với cây gậy của ông, đánh vào bụi đất; và bụi đất trở thành những con rận, trên người và trên súc vật; tất cả bụi đất đều trở thành rận trong khắp đất Ai Cập.'),
(1729, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 8, 18, 'OT', 'Các thầy phù thủy cũng làm như vậy bằng những phù chú của họ để sinh ra những con muỗi, nhưng không thể được. Những con muỗi ấy bèn xuất hiện trên người và trên súc vật.'),
(1730, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 8, 19, 'OT', 'Các thầy phù thủy tâu cùng Pha-ra-ôn: "Đây là ngón tay của Đức Chúa Trời." Nhưng lòng Pha-ra-ôn trở nên cứng cỏi, và ông không nghe theo Môi-se và A-rôn, đúng như điều Đức Giê-hô-va đã phán.'),
(1731, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 8, 20, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: "Hãy dậy sớm, đứng trước mặt Pha-ra-ôn; nầy, người sẽ ra sông; và ngươi hãy nói cùng người rằng: Đức Giê-hô-va phán như vầy: Hãy để cho dân ta đi, để chúng nó hầu việc ta."'),
(1732, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 8, 21, 'OT', 'Nếu ngươi không buông thả dân Ta, thì nầy, Ta sẽ sai lũ ruồi muỗi đến cùng ngươi, các tôi tớ ngươi, dân ngươi và trong nhà ngươi; các nhà của người Ai Cập sẽ đầy dẫy lũ ruồi muỗi, và cả đất đai nơi chúng ở nữa.'),
(1733, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 8, 22, 'OT', 'Và ta sẽ phân biệt trong ngày đó vùng đất Gô-sen, nơi dân ta đang ở, để không có ruồi muỗi ở đó, hầu cho ngươi biết rằng chính ta, Đức Giê-hô-va, ở giữa đất nước này.'),
(1734, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 8, 23, 'OT', 'Ta sẽ đặt sự cứu chuộc giữa dân Ta và dân ngươi. Đến ngày mai, dấu kỳ nầy sẽ xảy ra.'),
(1735, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 8, 24, 'OT', 'Đức Giê-hô-va làm như vậy; bèn có một đám ruồi mòng lớn vào trong nhà của Pha-ra-ôn, nhà của các tôi tớ người, và khắp đất Ai-cập; đất bị hủy hoại vì cớ đàn ruồi mòng.'),
(1736, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 8, 25, 'OT', 'Pha-ra-ôn đòi Môi-se và A-rôn, rồi nói: Hãy đi, dâng tế lễ cho Đức Chúa Trời các ngươi trong đất này.'),
(1737, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 8, 26, 'OT', 'Môi-se nói: "Không thể làm như vậy được, vì của lễ chúng tôi dâng cho Đức Giê-hô-va Đức Chúa Trời chúng tôi là điều gớm ghê đối với người Ai-cập. Nếu chúng tôi dâng của lễ điều gớm ghê trước mắt người Ai-cập, họ há chẳng ném đá chúng tôi sao?"'),
(1738, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 8, 27, 'OT', 'Chúng tôi sẽ đi ba ngày đường trong đồng vắng, và dâng của lễ cho Đức Giê-hô-va Đức Chúa Trời chúng tôi, y như điều Ngài sẽ phán dạy chúng tôi.'),
(1739, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 8, 28, 'OT', 'Pha-ra-ôn nói: Ta sẽ cho các ngươi đi để dâng tế lễ cho Đức Giê-hô-va Đức Chúa Trời các ngươi trong đồng vắng; nhưng không được đi xa quá. Hãy cầu xin cho ta!'),
(1740, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 8, 29, 'OT', 'Môi-se nói: Nầy, tôi sẽ ra đi khỏi ngài và cầu khẩn Đức Giê-hô-va; ngày mai, bầy ruồi sẽ rời khỏi Pha-ra-ôn, các tôi tớ ngài và dân sự ngài. Nhưng đừng để Pha-ra-ôn lại tiếp tục gạt gẫm, không chịu thả dân đi để dâng tế lễ cho Đức Giê-hô-va.'),
(1741, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 8, 30, 'OT', 'Môi-se bèn đi ra khỏi Pha-ra-ôn và cầu khẩn Đức Giê-hô-va.'),
(1742, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 8, 31, 'OT', 'Đức Giê-hô-va làm y như lời Môi-se; Ngài dẹp bầy ruồi ra khỏi Pha-ra-ôn, các tôi tớ ông ấy và dân sự ông ấy; không còn sót lại một con nào.'),
(1743, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 8, 32, 'OT', 'Pha-ra-ôn làm cho lòng mình ra nặng thêm trong lần này nữa, và không để cho dân sự đi.'),
(1744, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Hãy đến cùng Pha-ra-ôn và nói với người rằng: Đức Giê-hô-va, Đức Chúa Trời của người Hê-bơ-rơ, phán như vầy: Hãy để cho dân ta đi, để chúng nó hầu việc ta.'),
(1745, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 2, 'OT', 'vì nếu ngươi từ chối không chịu thả họ ra, và còn tiếp tục cầm giữ họ,'),
(1746, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 3, 'OT', 'Nầy, tay của Đức Giê-hô-va sẽ tra vào các súc vật của ngươi ngoài đồng, vào ngựa, lừa, lạc đà, bò và chiên: sẽ có dịch hạch rất nặng.'),
(1747, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 4, 'OT', 'Đức Giê-hô-va sẽ phân biệt giữa súc vật của Y-sơ-ra-ên và súc vật của người Ai-cập, và không một vật gì thuộc về các con trai của Y-sơ-ra-ên sẽ chết.'),
(1748, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 5, 'OT', 'Đức Giê-hô-va định một kỳ mà rằng: Ngày mai, Đức Giê-hô-va sẽ làm điều nầy tại trong đất.'),
(1749, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 6, 'OT', 'Ngày hôm sau, Đức Giê-hô-va làm điều đó: tất cả súc vật của người Ai-cập đều chết, nhưng chẳng có một con súc vật nào của con cái Y-sơ-ra-ên chết.'),
(1750, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 7, 'OT', 'Pha-ra-ôn sai người đi dò xét, thì thấy chẳng có một con súc vật nào của dân Y-sơ-ra-ên chết cả; nhưng lòng Pha-ra-ôn lại trở nên cứng cỏi, và ông ta không cho dân ấy đi.'),
(1751, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 8, 'OT', 'Đức Giê-hô-va phán cùng Môi-se và A-rôn: "Hãy lấy đầy hai tay các ngươi bằng tro bếp lò, rồi Môi-se sẽ ném lên trời ngay trước mặt Pha-ra-ôn."'),
(1752, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 9, 'OT', 'Tro sẽ trở thành bụi khắp cả đất Ai Cập, và nó sẽ gây ra những vết loét mưng mủ nổi lên trên người và trên súc vật trong khắp cả đất Ai Cập.'),
(1753, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 10, 'OT', 'Môi-se và A-rôn lấy tro trong lò, đứng trước mặt Pha-ra-ôn; rồi Môi-se ném tro lên không trung, và nó trở thành những mụp ghẻ đầy mủ nổi lên trên loài người và trên súc vật.'),
(1754, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 11, 'OT', 'Các thầy phù thủy không thể đứng trước mặt Môi-se được, vì bệnh ghẻ chốc đã giáng trên các thầy phù thủy và trên khắp dân Ai Cập.'),
(1755, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 12, 'OT', 'Đức Giê-hô-va khiến lòng Pha-ra-ôn trở nên cứng cỏi, và ông không nghe Môi-se và A-rôn, y như lời Đức Giê-hô-va đã phán cùng Môi-se.'),
(1756, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 13, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Hãy thức dậy sớm, ra đứng trước mặt Pha-ra-ôn và nói cùng người ấy rằng: Đức Giê-hô-va, Đức Chúa Trời của dân Hê-bơ-rơ, phán như vầy: Hãy để dân ta đi, để chúng nó hầu việc ta.'),
(1757, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 14, 'OT', 'Vì lần này Ta sẽ sai tất cả các tai họa của Ta đến trên lòng ngươi, các tôi tớ ngươi và dân sự ngươi, để ngươi biết rằng không ai sánh kịp Ta trong khắp đất.'),
(1758, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 15, 'OT', 'Vì nếu lúc này ta giơ tay ra giáng dịch hại ngươi và dân ngươi, thì ngươi đã bị quét khỏi đất rồi.'),
(1759, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 16, 'OT', 'Nhưng chính vì điều nầy Ta đã đặt ngươi lên, là để cho ngươi thấy quyền năng của Ta, và để danh Ta được rao truyền khắp đất.'),
(1760, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 17, 'OT', 'Ngươi còn chống cự dân ta, không chịu để họ đi,'),
(1761, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 18, 'OT', 'Nầy, ta sẽ làm mưa đá nặng nề và dữ dội vào giờ nầy ngày mai, đến nỗi tại Ai-cập từ khi thành lập cho đến bây giờ chưa từng có thứ gì giống như vậy.'),
(1762, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 19, 'OT', 'Vậy thì, bây giờ hãy sai đem súc vật ngươi và tất cả những gì thuộc về ngươi ở ngoài đồng vào; hễ người hay súc vật nào bị gặp thấy ở ngoài đồng mà không được đem vào nhà, thì mưa đá sẽ đổ xuống trên chúng và chúng sẽ chết.'),
(1763, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 20, 'OT', 'Những kẻ nào trong các tôi tớ của Pha-ra-ôn kính sợ lời Đức Giê-hô-va, thì đã nhanh chóng đem các tôi tớ mình và súc vật mình vào trong nhà.'),
(1764, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 21, 'OT', 'Còn ai không để lòng mình vào lời Đức Giê-hô-va, thì để đầy tớ và súc vật mình ngoài đồng.'),
(1765, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 22, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Hãy giơ tay ngươi lên trời, để mưa đá rơi xuống trên khắp đất Ai-cập, trên người, trên súc vật, và trên mọi thứ cỏ ngoài đồng trong đất Ai-cập.'),
(1766, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 23, 'OT', 'Môi-se giơ cây gậy của mình lên trời, và Đức Giê-hô-va khiến có tiếng sấm, mưa đá và lửa chạy xuống đất; Đức Giê-hô-va làm mưa đá rơi trên đất Ai-cập.'),
(1767, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 24, 'OT', 'Và có mưa đá, và lửa cháy hừng hực lẫn vào trong mưa đá, nặng nề cực kỳ, đến nỗi trong khắp đất Ai Cập, từ khi đất ấy trở thành một nước, chưa từng có cái nào giống như vậy.'),
(1768, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 25, 'OT', 'Mưa đá đã đánh khắp đất Ai Cập, mọi vật ở ngoài đồng, từ loài người cho đến súc vật; mưa đá đánh hại mọi thứ rau cỏ ngoài đồng và làm gãy mọi cây ngoài đồng.'),
(1769, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 26, 'OT', 'Chỉ có đất Gô-sen, nơi dân Y-sơ-ra-ên ở, là không có mưa đá.'),
(1770, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 27, 'OT', 'Pha-ra-ôn sai người gọi Môi-se và A-rôn, rồi nói với họ: "Lần này tôi đã phạm tội; Đức Giê-hô-va là công bình, còn tôi và dân tôi thì có tội."'),
(1771, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 28, 'OT', 'Hãy cầu xin Đức Giê-hô-va cho bớt tiếng sấm và mưa đá; rồi ta sẽ cho các ngươi đi, các ngươi sẽ không còn phải ở đây nữa.'),
(1772, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 29, 'OT', 'Môi-se nói với người ấy: "Khi tôi ra khỏi thành, tôi sẽ giơ tay mình lên Đức Giê-hô-va; sấm sét sẽ dứt, mưa đá sẽ không còn nữa, để bệ hạ biết rằng đất nầy thuộc về Đức Giê-hô-va."'),
(1773, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 30, 'OT', 'Nhưng tôi biết các ngươi và các tôi tớ ngươi vẫn chưa kính sợ Đức Giê-hô-va Đức Chúa Trời.'),
(1774, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 31, 'OT', 'Gai và lúa mạch bị đánh; vì lúa mạch thì trổ bông, và gai thì trổ hoa.'),
(1775, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 32, 'OT', 'Lúa mì và lúa mạch muộn nên không bị đánh.'),
(1776, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 33, 'OT', 'Rồi Môi-se đi ra khỏi cùng Pha-ra-ôn đến ngoài thành, giơ tay lên cùng Đức Giê-hô-va; và các tiếng sấm cùng mưa đá liền dứt, mưa cũng không đổ xuống đất nữa.'),
(1777, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 34, 'OT', 'Khi Pha-ra-ôn thấy mưa ngừng, mưa đá và sấm sét cũng dứt, thì lại tiếp tục phạm tội, và lòng người cùng các tôi tớ người trở nên chai cứng.'),
(1778, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 9, 35, 'OT', 'Lòng Pha-ra-ôn trở nên cứng cỏi, và ông không cho dân Y-sơ-ra-ên đi, y như lời Đức Giê-hô-va đã phán qua Môi-se.'),
(1779, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 10, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Hãy đi đến Pha-ra-ôn, vì ta đã làm cho lòng người ấy và lòng các tôi tớ của người trở nên cứng cỏi, để ta đặt các dấu kỳ lạ của ta giữa người ấy.'),
(1780, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 10, 2, 'OT', 'Hầu cho ngươi thuật lại trong tai con trai ngươi và cháu ngươi những điều ta đã làm cho dân Ê-díp-tô, và các dấu kỳ ta đã đặt giữa họ, để các ngươi biết rằng ta là Đức Giê-hô-va.'),
(1781, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 10, 3, 'OT', 'Môi-se và A-rôn đến cùng Pha-ra-ôn và nói với người rằng: "Đức Giê-hô-va, Đức Chúa Trời của dân Hê-bơ-rơ, phán như vầy: Ngươi sẽ còn từ chối hạ mình trước mặt ta cho đến bao giờ? Hãy để dân ta đi, để họ hầu việc ta."'),
(1782, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 10, 4, 'OT', 'Nếu ngươi từ chối không chịu để cho dân ta đi, nầy, ngày mai ta sẽ sai châu chấu đến trong địa phận ngươi;'),
(1783, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 10, 5, 'OT', 'Nó sẽ che khuất ánh sáng mặt đất, khiến người ta không thể thấy đất được nữa; nó sẽ ăn sạch phần còn sót lại mà trận mưa đá đã để lại cho các ngươi, và sẽ ăn hết mọi cây cối mọc nơi đồng ruộng các ngươi.'),
(1784, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 10, 6, 'OT', 'Và các nhà ngươi, các nhà của mọi tôi tớ ngươi và mọi nhà người Ai-cập sẽ đầy dẫy; điều mà tổ phụ ngươi và tổ tiên của tổ phụ ngươi chưa từng thấy, kể từ ngày họ hiện hữu trên đất cho đến ngày nay. Rồi Môi-se quay đi và ra khỏi cùng Pha-ra-ôn.'),
(1785, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 10, 7, 'OT', 'Các tôi tớ của Pha-ra-ôn nói với người rằng: Bao lâu nữa thì người nầy còn làm cớ vấp ngã cho chúng tôi? Hãy để những người ấy đi, để họ có thể hầu việc Đức Giê-hô-va Đức Chúa Trời của họ. Há người chưa biết rằng Ai Cập đã bị tiêu diệt sao?'),
(1786, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 10, 8, 'OT', 'Người ta liền triệu Môi-se và A-rôn trở lại cùng Pha-ra-ôn, và người nói với họ: Hãy đi phục vụ Đức Giê-hô-va Đức Chúa Trời các ngươi. Ai và ai là những người sẽ đi?'),
(1787, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 10, 9, 'OT', 'Môi-se nói: Chúng tôi sẽ đi với người trẻ và người già, với con trai và con gái của chúng tôi, cùng chiên và bò của chúng tôi, vì lễ của Đức Giê-hô-va là dành cho chúng tôi.'),
(1788, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 10, 10, 'OT', 'Pha-ra-ôn nói với họ: "Đức Giê-hô-va sẽ ở cùng các ngươi, nếu ta để cho các ngươi và con nhỏ các ngươi đi! Thật vậy, hãy xem, điều ác đang ở trước mặt các ngươi!"'),
(1789, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 10, 11, 'OT', 'Không phải vậy đâu; chỉ những người đàn ông được đi hầu việc Đức Giê-hô-va, vì điều đó chính là điều các ngươi xin. Rồi ông ta đuổi Môi-se và A-rôn ra khỏi trước mặt Pha-ra-ôn.'),
(1790, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 10, 12, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Hãy giơ tay ngươi ra trên đất Ai-cập về loài châu chấu, để nó tràn lên đất Ai-cập và ăn hết mọi thứ cỏ trên đất, tức là mọi thứ mà mưa đá đã để lại.'),
(1791, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 10, 13, 'OT', 'Môi-se đưa cây gậy mình ra trên đất Ai-cập, và Đức Giê-hô-va khiến gió đông thổi trên đất suốt cả ngày đó và đêm ấy; đến sáng hôm sau, thì gió đông đã thổi dạt đàn cào cào đến.'),
(1792, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 10, 14, 'OT', 'Cào cào tràn lên khắp đất Ai Cập, và nó đậu xuống trên toàn cõi đất Ai Cập; nó rất nặng nề, trước nó chưa từng có cào cào nào như vậy, và sau nó cũng sẽ không có cào cào nào như vậy nữa.'),
(1793, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 10, 15, 'OT', 'Nó che khuất toàn bộ mắt đất, khiến đất tối tăm; nó ăn hết mọi thứ cỏ trên đất và mọi trái cây trên cây mà mưa đá đã để lại; chẳng còn chút xanh tươi nào sót lại trên cây cối và trên cỏ ngoài đồng khắp đất Ai Cập.'),
(1794, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 10, 16, 'OT', 'Pha-ra-ôn vội vàng gọi Môi-se và A-rôn mà nói rằng: Ta đã phạm tội cùng Đức Giê-hô-va Đức Chúa Trời của các ngươi và cùng các ngươi nữa.'),
(1795, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 10, 17, 'OT', 'Bây giờ, hãy mang lấy tội lỗi tôi, chỉ một lần này thôi, và cầu xin Đức Giê-hô-va Đức Chúa Trời các ngươi, để Ngài gỡ bỏ khỏi tôi chỉ cái sự chết này mà thôi.'),
(1796, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 10, 18, 'OT', 'Môi-se lui ra khỏi Pha-ra-ôn và khẩn cầu Đức Giê-hô-va.'),
(1797, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 10, 19, 'OT', 'Đức Giê-hô-va khiến ngọn gió biển mạnh mẽ thổi ngược lại, đem hất cào cào lên, quăng nó xuống Biển Sụp; khắp vùng biên giới Ai-cập chẳng còn sót lại một con cào cào nào.'),
(1798, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 10, 20, 'OT', 'Đức Giê-hô-va làm cho lòng Pha-ra-ôn trở nên cứng cỏi, và ông không thả các con trai của Y-sơ-ra-ên đi.'),
(1799, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 10, 21, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Hãy giơ tay ngươi lên trời, hầu cho có sự tối tăm trên đất nước Ai Cập, và sự tối tăm ấy dày đặc đến nỗi có thể sờ được.'),
(1800, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 10, 22, 'OT', 'Môi-se giơ tay mình lên trời, liền có sự tối tăm mù mịt trong khắp đất Ai-cập ba ngày.'),
(1801, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 10, 23, 'OT', 'Ba ngày ấy, không người nào thấy anh em mình, và không ai rời khỏi chỗ mình được. Nhưng đối với mọi con cháu Y-sơ-ra-ên, thì có ánh sáng tại các nơi ở của họ.'),
(1802, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 10, 24, 'OT', 'Pha-ra-ôn gọi Môi-se mà nói: "Hãy đi phục vụ Đức Giê-hô-va; chỉ chiên và bò các ngươi phải để lại; cả trẻ nhỏ các ngươi cũng sẽ đi cùng các ngươi."'),
(1803, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 10, 25, 'OT', 'Môi-se nói: Chính ngài phải trao vào tay chúng tôi các của lễ thiêu và của lễ toàn thiêu, để chúng tôi dâng cho Đức Giê-hô-va Đức Chúa Trời chúng tôi.'),
(1804, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 10, 26, 'OT', 'Các bầy gia súc của chúng tôi cũng sẽ đi cùng chúng tôi; không một móng chân nào sẽ bị bỏ lại, vì chúng tôi phải dùng chúng để hầu việc Đức Giê-hô-va Đức Chúa Trời chúng tôi, và chúng tôi sẽ không biết phải thờ phượng Đức Giê-hô-va bằng điều gì cho đến khi chúng tôi đến nơi đó.'),
(1805, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 10, 27, 'OT', 'Đức Giê-hô-va khiến lòng Pha-ra-ôn trở nên cứng cỏi, nên người không chịu để cho dân Y-sơ-ra-ên đi.'),
(1806, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 10, 28, 'OT', 'Pha-ra-ôn nói với ông: Hãy đi khỏi ta! Hãy giữ mình cẩn thận, đừng thấy mặt ta nữa, vì ngày nào ngươi thấy mặt ta, ngươi sẽ chết!'),
(1807, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 10, 29, 'OT', 'Môi-se nói: "Bệ hạ nói đúng; tôi sẽ không còn thấy mặt bệ hạ nữa."'),
(1808, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 11, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Ta sẽ giáng cho Pha-ra-ôn và xứ Ê-díp-tô một tai vạ nữa; sau đó người sẽ cho các ngươi đi khỏi đây. Khi người cho các ngươi đi, thì sẽ đuổi các ngươi ra khỏi đây.'),
(1809, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 11, 2, 'OT', 'Hãy nói vào tai dân sự rằng mỗi người nam phải xin bạn mình, mỗi người nữ phải xin bạn mình những đồ bằng bạc và những đồ bằng vàng.'),
(1810, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 11, 3, 'OT', 'Đức Giê-hô-va khiến cho dân sự được ơn trước mặt người Ai-cập; chính Môi-se cũng rất được tôn trọng trong đất Ai-cập, trước mắt các tôi tớ của Pha-ra-ôn và trước mắt dân chúng.'),
(1811, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 11, 4, 'OT', 'Môi-se nói: Đức Giê-hô-va phán như vầy: Chừng nửa đêm, chính Ta sẽ ra đi giữa xứ Ai-cập.'),
(1812, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 11, 5, 'OT', 'Hết thảy con trưởng nam trong đất nước Ai Cập sẽ chết, từ con trưởng nam của Pha-ra-ôn đang ngồi trên ngôi người cho đến con trưởng nam của người đòi ở sau cối xay, và tất cả con đầu lòng của súc vật.'),
(1813, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 11, 6, 'OT', 'Trong khắp đất Ai-cập sẽ có tiếng kêu la lớn, chưa từng có như vậy và sẽ không bao giờ có nữa.'),
(1814, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 11, 7, 'OT', 'Nhưng đối với mọi người Y-sơ-ra-ên, không một con chó nào sẽ liếm lưỡi mình, dù là người hay vật, để các ngươi biết rằng Đức Giê-hô-va phân biệt giữa người Ê-díp-tô và Y-sơ-ra-ên.'),
(1815, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 11, 8, 'OT', 'Và mọi tôi tớ của bệ hạ sẽ xuống cùng tôi, sấp mình trước mặt tôi mà rằng: Xin Môi-se và cả dân sự theo người hãy đi đi! Sau đó tôi mới đi ra. Rồi Môi-se lui ra khỏi Pha-ra-ôn, đầy cơn thịnh nộ.'),
(1816, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 11, 9, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Pha-ra-ôn sẽ không nghe các ngươi, hầu cho các dấu kỳ ta được nhân lên trong đất Ai-cập.'),
(1817, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 11, 10, 'OT', 'Môi-se và A-rôn đã làm tất cả các phép lạ ấy trước mặt Pha-ra-ôn, nhưng Đức Giê-hô-va khiến lòng Pha-ra-ôn trở nên cứng cỏi, và ông không để cho con cái Y-sơ-ra-ên ra khỏi đất nước mình.'),
(1818, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se và A-rôn tại đất Ai Cập rằng:'),
(1819, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 2, 'OT', 'Tháng nầy phải là tháng đầu tiên cho các ngươi, là tháng thứ nhất trong các tháng của năm.'),
(1820, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 3, 'OT', 'Hãy nói cho toàn thể hội chúng Y-sơ-ra-ên rằng: Ngày mười tháng này, mỗi người phải lấy một con chiên con cho từng nhà, một con chiên con cho mỗi gia đình.'),
(1821, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 4, 'OT', 'Nếu nhà quá nhỏ không ăn hết một con chiên, thì người đó và người lân cận gần nhà mình sẽ chung nhau, tùy theo số lượng người; mỗi người theo lượng thức ăn của mình, các ngươi sẽ tính toán về con chiên.'),
(1822, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 5, 'OT', 'Hãy lấy chiên con đực, trọn vẹn, được một tuổi, từ trong bầy chiên hoặc từ trong bầy dê.'),
(1823, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 6, 'OT', 'Phải giữ con đó cho đến ngày mười bốn tháng này; rồi toàn thể hội chúng Y-sơ-ra-ên sẽ giết nó vào buổi chiều tối.'),
(1824, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 7, 'OT', 'Họ sẽ lấy máu và bôi lên hai cây đố cửa và trên vòm cửa, cho các nhà mà tại đó họ ăn con chiên ấy.'),
(1825, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 8, 'OT', 'Đêm nay họ sẽ ăn thịt đó, nướng bằng lửa, cùng với bánh không men và rau đắng.'),
(1826, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 9, 'OT', 'Đừng ăn thịt nó nửa chín hay luộc trong nước; nhưng phải nướng bằng lửa, cả đầu, các chân và nội tạng của nó.'),
(1827, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 10, 'OT', 'Các ngươi không được để phần nào còn lại cho đến sáng mai; phần nào còn lại cho đến sáng mai, phải lấy lửa thiêu đi.'),
(1828, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 11, 'OT', 'Vậy, các ngươi phải ăn thịt đó như thế này: lưng thắt dây, chân mang giày, gậy cầm trong tay; và phải ăn thịt đó cách vội vàng; ấy là lễ Vượt-qua của Đức Giê-hô-va.'),
(1829, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 12, 'OT', 'Trong đêm nầy, Ta sẽ đi qua xứ Ai Cập, đánh chết mọi con đầu lòng trong xứ Ai Cập, từ loài người cho đến súc vật; và đối với mọi thần của Ai Cập, Ta sẽ thi hành sự đoán xét. Ta là Đức Giê-hô-va.'),
(1830, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 13, 'OT', 'Máu sẽ là dấu hiệu cho các ngươi trên các nhà ngươi ở đó; Ta sẽ thấy máu và nhậm qua, các ngươi sẽ không bị tai họa tiêu diệt khi Ta giáng họa trên đất Ai-cập.'),
(1831, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 14, 'OT', 'Ngày nầy sẽ là ngày kỷ niệm cho các ngươi; các ngươi phải giữ lễ cho Đức Giê-hô-va trong các đời, làm lễ kỷ niệm đời đời.'),
(1832, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 15, 'OT', 'Trong bảy ngày phải ăn bánh không men; ngay ngày đầu tiên, phải dẹp men khỏi các nhà mình; vì hễ ai ăn điều gì có men từ ngày đầu cho đến ngày thứ bảy, thì linh hồn người ấy sẽ bị truất khỏi Y-sơ-ra-ên.'),
(1833, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 16, 'OT', 'Ngày đầu tiên sẽ là dịp nhóm họp thánh, và ngày thứ bảy cũng sẽ là dịp nhóm họp thánh cho các ngươi; mọi công việc không được làm trong những ngày ấy, chỉ có điều gì được phép ăn cho mọi người thì chính điều đó mà thôi được làm cho các ngươi.'),
(1834, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 17, 'OT', 'Vậy, các ngươi phải giữ lễ bánh không men, vì chính ngày này Ta đã đem các đạo quân các ngươi ra khỏi đất Ai-cập; các ngươi phải giữ ngày này theo các thế hệ của các ngươi như một luật lệ đời đời.'),
(1835, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 18, 'OT', 'Mười bốn ngày trong tháng, vào chiều tối, các ngươi sẽ ăn bánh không men cho đến chiều ngày hai mươi mốt ngày trong tháng.'),
(1836, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 19, 'OT', 'Trong bảy ngày, men không được tìm thấy trong các nhà các ngươi; vì bất cứ ai ăn đồ có men, thì linh hồn ấy sẽ bị truất khỏi hội chúng Y-sơ-ra-ên, dù là người ngoại hay là người bản xứ.'),
(1837, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 20, 'OT', 'Chớ ăn bất cứ thứ gì làm men; ở mọi nơi các ngươi ở, phải ăn bánh không men.'),
(1838, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 21, 'OT', 'Môi-se gọi tất cả các trưởng lão Y-sơ-ra-ên, rồi nói với họ: "Hãy đi và lấy cho mình một con chiên theo các gia tộc của các ông, rồi giết con chiên lễ Vượt-qua."'),
(1839, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 22, 'OT', 'Hãy lấy một bó kinh giới, nhúng vào huyết ở trong chậu, rồi chấm huyết lên vòm cửa và hai trụ cửa bên phải bên trái; huyết phải chấm nơi chậu; và các ngươi không ai được ra khỏi cửa nhà mình cho đến sáng mai.'),
(1840, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 23, 'OT', 'Đức Giê-hô-va sẽ đi qua để đánh phạt xứ Ai-cập; khi thấy huyết trên tấm ngang và hai bên trụ cửa, Đức Giê-hô-va sẽ vượt qua cửa ấy, không để kẻ tiêu diệt vào nhà các ngươi để hành hại.'),
(1841, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 24, 'OT', 'Các ngươi phải giữ điều nầy làm luật lệ cho ngươi và con cháu ngươi đến đời đời.'),
(1842, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 25, 'OT', 'Khi các ngươi vào xứ mà Đức Giê-hô-va sẽ ban cho các ngươi, như lời Ngài đã phán, thì phải giữ lễ nầy.'),
(1843, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 26, 'OT', 'Khi con cái các ngươi hỏi các ngươi rằng: Việc thờ phượng nầy là gì cho các ngươi?'),
(1844, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 27, 'OT', 'Và các ngươi sẽ nói: "Đây là của lễ Vượt-qua dành cho Đức Giê-hô-va, vì Ngài đã đi qua các nhà con cái Y-sơ-ra-ên tại Ai-cập, khi Ngài đánh phạt Ai-cập và cứu nhà chúng ta." Bấy giờ dân chúng cúi đầu thờ lạy.'),
(1845, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 28, 'OT', 'Bấy giờ, con cái Y-sơ-ra-ên đi ra và làm y như Đức Giê-hô-va đã truyền cho Môi-se và A-rôn; chính họ đã làm như vậy.'),
(1846, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 29, 'OT', 'Vào giữa đêm, Đức Giê-hô-va đánh chết mọi con đầu lòng trong đất Ai-cập, từ con đầu lòng của Pha-ra-ôn đang ngồi trên ngôi người, cho đến con đầu lòng của người bị tù giam trong ngục, và mọi con đầu lòng của súc vật.'),
(1847, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 30, 'OT', 'Đang đêm, Pha-ra-ôn cùng mọi tôi tớ người và mọi người Ai-cập đều chỗi dậy; và có tiếng kêu lớn trong xứ Ai-cập, vì chẳng một nhà nào mà không có người chết.'),
(1848, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 31, 'OT', 'Trong đêm đó, Pha-ra-ôn gọi Môi-se và A-rôn mà nói: Hãy chỗi dậy, ra khỏi giữa vòng dân ta, cả các ngươi lẫn các con cái Y-sơ-ra-ên; và hãy đi phục sự Đức Giê-hô-va như lời các ngươi đã nói.'),
(1849, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 32, 'OT', 'Hãy đem theo cả chiên và bò của các ngươi, như lời các ngươi đã nói, rồi đi đi; và hãy ban phước cho ta nữa.'),
(1850, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 33, 'OT', 'Người Ai-cập thúc giục dân Y-sơ-ra-ên phải vội vàng ra khỏi xứ, vì họ nói: "Chúng ta đều sẽ chết!"'),
(1851, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 34, 'OT', 'Dân chúng mang theo bột nhồi của mình trước khi kịp lên men, những thùng đựng bột được gói trong áo choàng, đặt trên vai mình.'),
(1852, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 35, 'OT', 'Con cái Y-sơ-ra-ên làm theo lời Môi-se, xin người Ai-cập những đồ bằng bạc, đồ bằng vàng và áo xống.'),
(1853, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 36, 'OT', 'Đức Giê-hô-va ban cho dân sự ơn trước mặt người Ai-cập, nên họ mượn được của người Ai-cập; và dân Y-sơ-ra-ên đã vơ vét người Ai-cập.'),
(1854, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 37, 'OT', 'Dân Y-sơ-ra-ên đi từ Ram-se đến Su-cốt, khoảng sáu trăm ngàn người đàn ông đi bộ, chưa kể trẻ em.'),
(1855, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 38, 'OT', 'Cũng có một đoàn người hỗn tạp đông đảo đi lên cùng với họ, cùng các chiên, bò và súc vật rất nhiều.'),
(1856, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 39, 'OT', 'Họ nướng bột mà họ đã mang ra khỏi Ai Cập thành những ổ bánh không men, vì bột không kịp lên men; bởi họ bị đuổi khỏi Ai Cập và không thể chậm trễ, cũng không kịp sắm lấy lương thực cho mình.'),
(1857, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 40, 'OT', 'Còn thì kiều ngụ của con cháu Y-sơ-ra-ên, là nơi họ đã ở tại Ai-cập, là bốn trăm ba mươi năm.'),
(1858, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 41, 'OT', 'Và đã qua bốn trăm ba mươi năm, thì cũng trong ngày này, mọi đạo binh của Đức Giê-hô-va đều ra khỏi đất Ai Cập.'),
(1859, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 42, 'OT', 'Đêm canh giữ ấy là của Đức Giê-hô-va, để đưa họ ra khỏi đất Ai-cập; chính đêm nầy Đức Giê-hô-va giữ cho, cho mọi con cái Y-sơ-ra-ên theo các thế hệ của họ.'),
(1860, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 43, 'OT', 'Đức Giê-hô-va phán cùng Môi-se và A-rôn: Đây là luật lệ của lễ Vượt-qua: Mọi người ngoại bang không được ăn trong đó.'),
(1861, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 44, 'OT', 'Còn mọi tôi mọi nam là nô lệ mua bằng tiền, ngươi phải làm phép cắt bì cho người ấy; bấy giờ người ấy mới được ăn trong đó.'),
(1862, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 45, 'OT', 'Người ngoại bang và kẻ làm công không được ăn lễ ấy.'),
(1863, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 46, 'OT', 'Chỉ ăn lễ đó trong một nhà; ngươi không được đem thịt ra ngoài nhà, và cũng không được bẻ một cái xương nào của nó.'),
(1864, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 47, 'OT', 'Hết thảy hội chúng Y-sơ-ra-ên phải giữ lễ Vượt-qua.'),
(1865, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 48, 'OT', 'Khi một khách ngoại bang nào ở giữa ngươi và muốn giữ lễ Vượt-qua cho Đức Giê-hô-va, thì phải chịu phép cắt bì cho mọi người nam thuộc về hắn; rồi hắn mới được đến gần để giữ lễ ấy, và sẽ được coi như người bản xứ; nhưng không một ai chưa chịu phép cắt bì được phép ăn lễ ấy.'),
(1866, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 49, 'OT', 'Luật lệ phải như nhau cho người bản xứ và cho người ngoại bang kiều ngụ giữa các ngươi.'),
(1867, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 50, 'OT', 'Toàn thể dân Y-sơ-ra-ên đều làm như Đức Giê-hô-va đã truyền dạy Môi-se và A-rôn.'),
(1868, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 12, 51, 'OT', 'Cũng trong ngày đó, Đức Giê-hô-va đem con cái Y-sơ-ra-ên ra khỏi đất Ê-díp-tô tùy theo các đạo quân của họ.'),
(1869, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 13, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(1870, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 13, 2, 'OT', 'Hãy biệt riêng cho Đức Giê-hô-va mọi con đầu lòng trong vòng con cái Y-sơ-ra-ên, cả loài người lẫn loài vật; vì nó thuộc về ta.'),
(1871, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 13, 3, 'OT', 'Môi-se nói cùng dân sự rằng: Hãy nhớ ngày nầy, là ngày các ngươi ra khỏi xứ Ê-díptô, khỏi nhà nô lệ, vì Đức Giê-hô-va đã đem các ngươi ra khỏi nơi đó bằng tay quyền năng; nên không ai được ăn bánh có men.'),
(1872, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 13, 4, 'OT', 'Ngày nay, các ngươi ra đi, vào tháng giêng.'),
(1873, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 13, 5, 'OT', 'Và sẽ xảy ra khi Đức Giê-hô-va dẫn ngươi vào đất của người Ca-na-an, người Hê-tít, người A-mô-rít, người Hê-vít và người Giê-bu-sít, là đất mà Ngài đã thề hứa cùng tổ phụ ngươi để ban cho ngươi, một đất chảy sữa và mật ong, thì ngươi phải giữ công việc thờ phượng nầy trong tháng nầy.'),
(1874, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 13, 6, 'OT', 'Trong bảy ngày phải ăn bánh không men; và ngày thứ bảy sẽ là lễ kỷ niệm dành cho Đức Giê-hô-va.'),
(1875, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 13, 7, 'OT', 'Phải ăn bánh không men trong bảy ngày; bánh có men không được thấy nơi ngươi, và men cũng không được thấy trong toàn cõi lãnh thổ ngươi.'),
(1876, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 13, 8, 'OT', 'Trong ngày đó, hãy nói cho con trai ngươi rằng: Vì việc này, Đức Giê-hô-va đã làm cho ta khi ta ra khỏi Ai-cập.'),
(1877, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 13, 9, 'OT', 'Điều đó sẽ là một dấu hiệu trên tay ngươi và một sự nhắc nhở giữa hai mắt ngươi, để luật pháp của Đức Giê-hô-va luôn ở nơi miệng ngươi; vì chính tay quyền năng Đức Giê-hô-va đã đem ngươi ra khỏi xứ Ai Cập.'),
(1878, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 13, 10, 'OT', 'Vậy ngươi phải giữ điều lệ nầy theo đúng kỳ lễ của nó, từ ngày này sang ngày khác.'),
(1879, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 13, 11, 'OT', 'Khi Đức Giê-hô-va đưa ngươi vào đất Ca-na-an, như Ngài đã thề với ngươi và với tổ phụ ngươi, và ban xứ ấy cho ngươi,'),
(1880, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 13, 12, 'OT', 'Ngươi hãy biệt riêng cho Đức Giê-hô-va mọi con đầu lòng; và mọi con đầu lòng của súc vật đực thuộc về ngươi, thì phải dâng cho Đức Giê-hô-va.'),
(1881, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 13, 13, 'OT', 'Mỗi con lừa đầu lòng, ngươi phải chuộc bằng một chiên con; nếu không chuộc, thì phải bẻ cổ nó; và mọi con đầu lòng trong các con trai ngươi, ngươi phải chuộc.'),
(1882, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 13, 14, 'OT', 'Và xảy ra ngày mai, con trai ngươi sẽ hỏi ngươi mà nói rằng: Điều nầy là gì? thì ngươi sẽ nói cho nó rằng: Bởi tay quyền năng, Đức Giê-hô-va đã đem chúng ta ra khỏi xứ Ai-cập, khỏi nhà tôi mọi.'),
(1883, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 13, 15, 'OT', 'Vì Pha-ra-ôn cứng lòng không chịu thả chúng ta đi, nên Đức Giê-hô-va đã giết tất cả các con đầu lòng trong đất Ai-cập, từ con đầu lòng của loài người cho đến con đầu lòng của súc vật. Vì thế, tôi dâng cho Đức Giê-hô-va mọi con đực đầu lòng sinh ra từ loài vật, còn mọi con đầu lòng của các con trai tôi thì tôi chuộc lại.'),
(1884, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 13, 16, 'OT', 'Và ấy sẽ là một dấu hiệu trên tay ngươi, và một ấn chí giữa hai mắt ngươi, vì Đức Giê-hô-va đã dùng quyền năng tay mà đem chúng ta ra khỏi xứ Ê-díp-tô.'),
(1885, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 13, 17, 'OT', 'Khi Pha-ra-ôn thả dân Y-sơ-ra-ên đi, Đức Chúa Trời không dẫn họ theo con đường đất nước Phi-li-tin, vì con đường ấy gần; bởi Đức Chúa Trời phán rằng: Kẻo dân thấy chiến tranh mà đổi lòng, rồi trở lại xứ Ê-díp-tô.'),
(1886, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 13, 18, 'OT', 'Vì vậy Đức Chúa Trời dẫn dân về con đường qua đồng vắng, hướng về Biển-dỏ; và dân Y-sơ-ra-ên ra đi từng hàng năm người, từ đất Ê-díp-tô.'),
(1887, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 13, 19, 'OT', 'Môi-se đem hài cốt Giô-sép theo mình, vì Giô-sép đã bắt con cháu Y-sơ-ra-ên phải thề rằng: Đức Chúa Trời chắc chắn sẽ viếng thăm các ngươi, và các ngươi phải đem hài cốt ta theo khỏi đây.'),
(1888, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 13, 20, 'OT', 'Họ đi khỏi Su-cốt, rồi đóng trại tại Ê-tam, ở cuối đầu đồng vắng.'),
(1889, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 13, 21, 'OT', 'Đức Giê-hô-va đi trước mặt họ ban ngày trong một trụ mây để dẫn đường cho họ, và ban đêm trong một trụ lửa để soi sáng cho họ, hầu cho họ có thể đi cả ngày lẫn đêm.'),
(1890, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 13, 22, 'OT', 'Cột mây ban ngày không rời khỏi dân sự, và cột lửa ban đêm cũng vậy, luôn đi trước mặt dân sự.'),
(1891, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 14, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(1892, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 14, 2, 'OT', 'Hãy bảo các con trai Y-sơ-ra-ên rằng: Hãy quay trở lại và đóng trại trước Phi-Ha-hi-rốt, giữa Mít-đôn và biển, đối diện Ba-anh-Sê-phôn; các ngươi sẽ đóng trại gần biển.'),
(1893, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 14, 3, 'OT', 'Pha-ra-ôn sẽ nói về con cái Y-sơ-ra-ên rằng: Chúng lạc lối trong đất nầy; đồng vắng đã khép kín lại trên chúng.'),
(1894, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 14, 4, 'OT', 'Ta sẽ làm cho lòng Pha-ra-ôn trở nên cứng cỏi, và người sẽ đuổi theo họ; rồi Ta sẽ được tôn vinh nơi Pha-ra-ôn và toàn thể đạo binh của người; và người Ê-díp-tô sẽ biết Ta là Đức Giê-hô-va. Dân Y-sơ-ra-ên bèn làm như vậy.'),
(1895, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 14, 5, 'OT', 'Vua xứ Ê-díp-tô được báo tin rằng dân Hê-bơ-rơ đã trốn đi. Lòng Pha-ra-ôn và các tôi tớ người trở nên đổi khác đối với dân Y-sơ-ra-ên, bèn nói: "Chúng ta đã làm điều nầy là chi, mà lại để cho dân Y-sơ-ra-ên thôi không phục dịch chúng ta nữa?"'),
(1896, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 14, 6, 'OT', 'Pha-ra-ôn bèn sai thắng xe mình và đem dân mình theo cùng mình.'),
(1897, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 14, 7, 'OT', 'Người đem sáu trăm xe chọn lọc và toàn thể xe của Ai Cập, cùng các sĩ quan chỉ huy trên mỗi xe.'),
(1898, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 14, 8, 'OT', 'Đức Giê-hô-va làm cho lòng Pha-ra-ôn, vua Ai Cập, trở nên cứng cỏi, và ông đuổi theo sau các con trai Y-sơ-ra-ên; còn các con trai Y-sơ-ra-ên thì ra đi với tay cao.'),
(1899, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 14, 9, 'OT', 'Người Ê-díp-tô đuổi theo dân Y-sơ-ra-ên; và họ đuổi kịp dân ấy đang đóng trại bên bờ biển, gần Phi-Ha-hi-rốt, đối diện Ba-anh-Sê-phôn: tất cả ngựa xe của Pha-ra-ôn, lính kỵ cùng đạo quân của người.'),
(1900, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 14, 10, 'OT', 'Khi Pha-ra-ôn đến gần, con cái Y-sơ-ra-ên ngước mắt lên và thấy người Ê-díp-tô đang tiến tới phía sau họ; họ rất sợ hãi, và con cái Y-sơ-ra-ên kêu cứu Đức Giê-hô-va.'),
(1901, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 14, 11, 'OT', 'Chúng nói cùng Môi-se: "Phải chi trong xứ Ai Cập không có mồ mả, nên người mới đem chúng tôi ra đây để chết trong đồng vắng sao? Người làm điều này với chúng tôi, đem chúng tôi ra khỏi xứ Ai Cập, là để làm gì?"'),
(1902, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 14, 12, 'OT', 'Há chẳng phải điều này là điều mà chúng tôi đã nói cùng ông tại Ai-cập rằng: ''Xin để mặc chúng tôi phục vụ dân Ai-cập; vì tốt hơn cho chúng tôi phục vụ dân Ai-cập còn hơn là chết trong đồng vắng''?'),
(1903, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 14, 13, 'OT', 'Môi-se nói cùng dân sự rằng: Đừng sợ, hãy đứng vững và xem sự cứu độ mà Đức Giê-hô-va sẽ thực hiện cho các ngươi hôm nay; vì những người Ê-díp-tô mà các ngươi thấy hôm nay, các ngươi sẽ không còn thấy họ nữa mãi mãi.'),
(1904, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 14, 14, 'OT', 'Đức Giê-hô-va sẽ chiến đấu cho các ngươi, còn các ngươi chỉ cần im lặng.'),
(1905, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 14, 15, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Môi-se, ngươi kêu khóc cùng ta làm gì? Hãy bảo dân Y-sơ-ra-ên đi đi.'),
(1906, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 14, 16, 'OT', 'Còn ngươi, hãy nâng cây gậy của ngươi lên, giơ tay ngươi ra trên mặt biển và phân rẽ nó, thì con cái Y-sơ-ra-ên sẽ đi vào giữa biển trên đất khô.'),
(1907, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 14, 17, 'OT', 'Và chính Ta đây, Ta sẽ làm cho lòng dân Ê-díp-tô trở nên cứng cỏi, khiến chúng đuổi theo sau họ; và Ta sẽ được tôn vinh nơi Pha-ra-ôn cùng toàn thể đạo binh của người, trong các xe chiến của người và các kỵ binh của người.'),
(1908, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 14, 18, 'OT', 'Người Ai Cập sẽ biết ta là Đức Giê-hô-va, khi ta được tôn vinh vì Pha-ra-ôn, vì xe chiến của người và lính cưỡi ngựa của người.'),
(1909, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 14, 19, 'OT', 'Thiên sứ của Đức Chúa Trời, Đấng đi trước trại quân Y-sơ-ra-ên, chuyển đi phía sau họ; và trụ mây vốn ở trước mặt họ, thì chuyển đi đứng phía sau họ.'),
(1910, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 14, 20, 'OT', 'đi vào giữa trại người Ai Cập và giữa trại Y-sơ-ra-ên; và có mây và bóng tối, và soi sáng đêm ấy; và bên nầy không lại gần bên kia suốt đêm.'),
(1911, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 14, 21, 'OT', 'Môi-se giơ tay mình ra trên biển, và Đức Giê-hô-va dẫn biển bằng một trận gió đông mạnh suốt cả đêm; Ngài làm cho biển trở nên chỗ khô, và các nước bị tách ra.'),
(1912, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 14, 22, 'OT', 'Dân Y-sơ-ra-ên đi vào giữa biển trên đất khô; nước làm thành vách ngăn cho họ bên phải và bên trái.'),
(1913, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 14, 23, 'OT', 'Người Ai Cập đuổi theo, và hết thảy ngựa, xe chiến của Pha-ra-ôn cùng lính kỵ của người đều theo sau chúng vào giữa biển.'),
(1914, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 14, 24, 'OT', 'Đến canh sáng, Đức Giê-hô-va nhìn xuống trại quân Ê-dốp-tô qua trụ cột lửa và mây, và làm cho trại quân Ê-dốp-tô bị rối loạn.'),
(1915, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 14, 25, 'OT', 'Ngài tháo bánh xe các xe của chúng nó, khiến chúng phải chật vật khi điều khiển; người Ai-cập bèn nói: "Ta hãy trốn khỏi mặt Y-sơ-ra-ên, vì Đức Giê-hô-va chiến đấu cho họ chống lại người Ai-cập."'),
(1916, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 14, 26, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Hãy đưa tay ngươi ra trên biển, và nước sẽ trở lại trên người Ê-díp-tô, trên xe và lính kỵ của chúng nó.'),
(1917, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 14, 27, 'OT', 'Môi-se giơ tay mình ra trên biển, đến gần sáng mai nước biển trở lại đúng chỗ cũ, người Ai-cập chạy trốn thì gặp nước tràn đến; Đức Giê-hô-va xô người Ai-cập vào giữa biển.'),
(1918, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 14, 28, 'OT', 'Nước trở lại, phủ kín xe và kỵ binh, toàn thể đạo binh của Pha-ra-ôn đã theo sau họ xuống biển; chẳng còn sót lại một người nào trong số họ.'),
(1919, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 14, 29, 'OT', 'Dân Y-sơ-ra-ên đi trên đất khô giữa biển; nước làm thành lũy bên phải và bên trái họ.'),
(1920, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 14, 30, 'OT', 'Đức Giê-hô-va cứu Y-sơ-ra-ên khỏi tay người Ai-cập trong ngày đó; Y-sơ-ra-ên thấy người Ai-cập chết nằm trên bờ biển.'),
(1921, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 14, 31, 'OT', 'Dân Y-sơ-ra-ên thấy tay quyền năng lớn lao mà Đức Giê-hô-va đã làm tại Ai-cập, thì kính sợ Đức Giê-hô-va, và tin nơi Đức Giê-hô-va và nơi Môi-se, tôi tớ Ngài.'),
(1922, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 15, 1, 'OT', 'Khi ấy, Môi-se và con cái Y-sơ-ra-ên hát bài ca nầy cho Đức Giê-hô-va, và họ nói rằng: Tôi sẽ ca hát cho Đức Giê-hô-va, vì Ngài rất cao cả oai nghiêm; ngựa và người cỡi ngựa, Ngài đã quăng xuống biển.'),
(1923, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 15, 2, 'OT', 'Đức Giê-hô-va là sức mạnh và bài ca của tôi, Ngài đã trở nên sự cứu rỗi cho tôi. Đây là Đức Chúa Trời tôi, tôi sẽ ca ngợi Ngài; Đức Chúa Trời của cha tôi, tôi sẽ tôn cao Ngài.'),
(1924, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 15, 3, 'OT', 'Đức Giê-hô-va là một chiến sĩ, Giê-hô-va là danh Ngài.'),
(1925, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 15, 4, 'OT', 'Các xe ngựa của Pha-ra-ôn và đạo quân của nó, Đức Giê-hô-va đã quăng xuống biển; những người chỉ huy tinh nhuệ nhất của nó thì bị chìm nơi biển Sậu.'),
(1926, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 15, 5, 'OT', 'Những vực thẳm nuốt chửng chúng; chúng nó chìm xuống đáy sâu như thể một hòn đá.'),
(1927, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 15, 6, 'OT', 'Tay hữu Đức Giê-hô-va đầy oai quyền hùng mạnh; tay hữu Đức Giê-hô-va nghiền nát kẻ thù.'),
(1928, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 15, 7, 'OT', 'Vì sự cao cả của oai nghi Ngài, Ngài đánh đổ những kẻ dấy lên nghịch cùng Ngài; Ngài sai cơn thạnh nộ của Ngài, lửa thiêu nuốt chúng như rơm rạ.'),
(1929, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 15, 8, 'OT', 'Bởi cơn gió giận dữ của Ngài thổi ra, nước liền dâng lên, chất cao như đống, vực thẳm đông đặc giữa lòng biển.'),
(1930, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 15, 9, 'OT', 'Kẻ thù nói: Ta sẽ đuổi theo, ta sẽ bắt kịp; ta sẽ chia của cải cướp được; tâm hồn ta sẽ thỏa mãn chúng; ta sẽ rút gươm ta ra, tay ta sẽ tiêu diệt chúng.'),
(1931, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 15, 10, 'OT', 'Ngài hít một hơi, biển liền phủ kín chúng; chúng chìm xuống như chì giữa những dòng nước sâu.'),
(1932, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 15, 11, 'OT', 'Đức Giê-hô-va, ai trong các thần giống như Ngài? Ai giống như Ngài, đầy vẻ vang thánh khiết, đáng sợ, đáng ca ngợi, làm nên điều kỳ diệu?'),
(1933, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 15, 12, 'OT', 'Chúa đưa tay phải Ngài ra, đất liền nuốt chúng nó.'),
(1934, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 15, 13, 'OT', 'Nhờ ân từ Ngài, Ngài dẫn dắt dân nầy mà Ngài đã chuộc; Ngài dùng quyền năng dẫn nó đến nơi ở thánh của Ngài.'),
(1935, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 15, 14, 'OT', 'Các dân nghe thấy đều run rẩy, cơn kinh hoàng bao trùm những kẻ ở đất Pha-lê-tin.'),
(1936, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 15, 15, 'OT', 'Bấy giờ các lãnh tụ Ê-đôm đều bối rối; các trưởng làng Mô-áp bị cơn run sợ ập lấy; mọi người ở trong xứ Ca-na-an đều hoảng hốt.'),
(1937, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 15, 16, 'OT', 'Sự kinh hãi và sợ hãi sẽ giáng trên chúng nó; vì sự lớn lao của cánh tay Ngài, chúng sẽ đứng im như đá, cho đến khi dân Ngài đi qua, hỡi Đức Giê-hô-va, cho đến khi dân mà Ngài đã mua chuộc đi qua.'),
(1938, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 15, 17, 'OT', 'Ngài sẽ dẫn họ vào, và trồng họ trên núi cơ nghiệp Ngài, nơi Ngài đã sắm sẵn làm chỗ ở, hỡi Đức Giê-hô-va; đền thánh mà tay Ngài đã lập.'),
(1939, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 15, 18, 'OT', 'Đức Giê-hô-va sẽ trị vì đời đời vô cùng.'),
(1940, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 15, 19, 'OT', 'Vì ngựa của Pha-ra-ôn cùng xe và lính kỵ người đã đi xuống biển; và Đức Giê-hô-va đã khiến nước biển trở lại phủ lên chúng; còn con cái Y-sơ-ra-ên thì đi giữa biển trên đất khô.'),
(1941, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 15, 20, 'OT', 'Nữ tiên tri Mi-ri-am, em gái A-rôn, cầm trống cơm trong tay; và mọi phụ nữ đi ra theo sau người, đều cầm trống cơm và nhảy múa.'),
(1942, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 15, 21, 'OT', 'Mi-ri-am đáp lại cho họ rằng: Hãy hát xướng cho Đức Giê-hô-va, vì Ngài rất cao cả vinh hiển; ngựa và người cỡi ngựa, Ngài đã liệng xuống biển.'),
(1943, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 15, 22, 'OT', 'Môi-se dẫn dân Y-sơ-ra-ên đi khỏi Biển Đỏ, rồi đi đến đồng vắng Su-rơ; họ đi ba ngày trong đồng vắng mà không tìm được nước.'),
(1944, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 15, 23, 'OT', 'Họ đi đến Ma-ra, nhưng không thể uống nước ở Ma-ra vì nước đắng; bởi vậy, người ta gọi tên chỗ ấy là Ma-ra.'),
(1945, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 15, 24, 'OT', 'Dân sự oán trách Môi-se, nói rằng: Chúng tôi lấy chi uống?'),
(1946, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 15, 25, 'OT', 'Môi-se kêu cầu Đức Giê-hô-va; thì Ngài chỉ cho ông một cây, ông liệng xuống nước, và nước trở nên ngọt. Tại đó, Ngài ban cho ông luật lệ và mạng lịnh, và tại đó Ngài thử họ.'),
(1947, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 15, 26, 'OT', 'Nếu ngươi chăm chỉ nghe lời Đức Giê-hô-va Đức Chúa Trời ngươi, làm điều ngay thẳng trước mặt Ngài, lắng tai nghe các điều răn Ngài và tu giữ mọi luật lệ Ngài, thì ta sẽ không giáng trên ngươi một trong các bệnh mà ta đã giáng trên người Ai Cập; vì ta là Đức Giê-hô-va, Đấng chữa lành ngươi.'),
(1948, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 15, 27, 'OT', 'Dân sự đến Ê-li-m, và tại đó có mười hai suối nước và bảy mươi cây chà là; họ cắm trại tại đó bên cạnh các suối nước.'),
(1949, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 1, 'OT', 'Cả hội chúng Y-sơ-ra-ên từ Ê-lim đi ra, đến đồng vắng Si-na-i, là nơi ở giữa Ê-lim và Si-na-i, nhằm ngày mười lăm tháng hai, sau khi ra khỏi xứ Ê-díp-tô.'),
(1950, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 2, 'OT', 'Cả hội chúng dân Y-sơ-ra-ên oán trách Môi-se và A-rôn trong đồng vắng,'),
(1951, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 3, 'OT', 'Bèn nói cùng Môi-se và A-rôn rằng: Ước chi chúng tôi đã chết về tay Đức Giê-hô-va tại đất Ai-cập, khi chúng tôi còn ngồi cạnh nồi thịt, và được ăn bánh no nê! Vì các ông đã đem chúng tôi vào nơi đồng vắng nầy, để làm chết cả hội chúng nầy bởi sự đói khát.'),
(1952, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 4, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Nầy, ta sẽ làm mưa bánh cho các ngươi từ trên trời xuống; dân sự sẽ đi ra và thâu mỗi ngày một ít đủ cho ngày ấy, để ta thử xem chúng có đi theo luật pháp ta hay không.'),
(1953, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 5, 'OT', 'Đến ngày thứ sáu, họ sẽ chuẩn bị những gì mình mang đến, và phần được mang đến sẽ gấp đôi phần họ thu mỗi ngày.'),
(1954, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 6, 'OT', 'Môi-se và A-rôn nói cùng toàn thể dân Y-sơ-ra-ên rằng: Chiều nay các ngươi sẽ biết rằng chính Đức Giê-hô-va đã đem các ngươi ra khỏi xứ Ai Cập.'),
(1955, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 7, 'OT', 'Và sáng mai, các ngươi sẽ thấy vinh quang của Đức Giê-hô-va, vì Ngài đã nghe những lời than trách của các ngươi chống lại Đức Giê-hô-va; còn chúng ta là ai, mà các ngươi lại than trách chúng ta?'),
(1956, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 8, 'OT', 'Môi-se nói: Khi Đức Giê-hô-va ban cho các ngươi chiều nay thịt để ăn và sáng mai bánh no đủ, ấy là vì Ngài đã nghe những lời oán trách mà các ngươi oán trách Ngài; còn chúng tôi là gì? Các lời oán trách các ngươi chẳng phải chống lại chúng tôi, mà chống lại Đức Giê-hô-va.'),
(1957, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 9, 'OT', 'Môi-se nói cùng A-rôn: "Hãy nói cùng cả hội chúng con cái Y-sơ-ra-ên rằng: Các ngươi hãy đến gần trước mặt Đức Giê-hô-va, vì Ngài đã nghe lời than trách của các ngươi."'),
(1958, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 10, 'OT', 'Khi A-rôn nói với toàn thể hội chúng con cái Y-sơ-ra-ên, thì họ quay mặt về phía đồng vắng; và nầy, vinh hiển của Đức Giê-hô-va hiện ra trong đám mây.'),
(1959, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 11, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(1960, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 12, 'OT', 'Ta đã nghe lời than vãn của con cái Y-sơ-ra-ên; hãy nói cùng chúng nó rằng: Buổi chiều các ngươi sẽ ăn thịt, và sáng hôm sau sẽ được no nê bánh, để các ngươi biết ta là Đức Giê-hô-va Đức Chúa Trời của các ngươi.'),
(1961, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 13, 'OT', 'Chiều đến, chim cút bay lên phủ kín toàn thể trại quân; rồi sáng mai, xung quanh trại quân có một lớp sương đọng lại.'),
(1962, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 14, 'OT', 'Lớp sương tan đi, thì nầy, trên mặt đồng vắng có vật mỏng mảnh như lớp sương mỏng phủ trên mặt đất.'),
(1963, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 15, 'OT', 'Khi dân Y-sơ-ra-ên thấy, thì hỏi nhau rằng: "Cái đó là gì?" vì họ không biết đó là gì. Môi-se nói với họ: "Đó là bánh mà Đức Giê-hô-va đã ban cho các ngươi làm của ăn."'),
(1964, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 16, 'OT', 'Đây là điều Đức Giê-hô-va đã truyền: Mỗi người hãy lấy theo lượng thức ăn của mình, mỗi người một ô-me cho mỗi người trong trại mình.'),
(1965, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 17, 'OT', 'Dân Y-sơ-ra-ên bèn làm như vậy, kẻ thì lượm nhiều, người thì lượm ít,'),
(1966, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 18, 'OT', 'Họ đo bằng ô-me, người lượm nhiều thì không dư, người lượm ít thì không thiếu; mỗi người lượm vừa đủ phần ăn của mình.'),
(1967, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 19, 'OT', 'Môi-se nói với họ rằng: Đừng ai để phần mình còn lại đến sáng mai.'),
(1968, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 20, 'OT', 'Nhưng họ không nghe theo Môi-se, mà một vài người đã để dành phần đó cho đến sáng hôm sau, thì sâu bọ sinh ra và bốc mùi hôi thối; Môi-se bèn nổi giận cùng họ.'),
(1969, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 21, 'OT', 'Vậy họ thâu lấy nó mỗi buổi sáng, mỗi người tùy theo lượng ăn của mình; rồi khi mặt trời lên nóng, thì vật ấy tan ra.'),
(1970, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 22, 'OT', 'Vào ngày thứ sáu, họ lượm bánh gấp đôi; mỗi người hai ô-me. Tất cả các trưởng tộc đến trình cùng Môi-se.'),
(1971, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 23, 'OT', 'Người bảo họ: "Chính điều Đức Giê-hô-va đã phán: Ngày mai là ngày nghỉ, Sa-bát thánh cho Đức Giê-hô-va. Những gì các ngươi muốn nướng thì hãy nướng, những gì các ngươi muốn nấu thì hãy nấu; còn tất cả phần dư ra, hãy để dành cho các ngươi giữ đến sáng mai."'),
(1972, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 24, 'OT', 'Dân sự bèn để dành nó cho đến sáng mai, y như lời Môi-se đã truyền; và nó chẳng hư nát, cũng chẳng có sâu nào ở trong nó.'),
(1973, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 25, 'OT', 'Môi-se nói: Hãy ăn nó hôm nay, vì hôm nay là ngày Sa-bát dành cho Đức Giê-hô-va; hôm nay các ngươi sẽ không tìm thấy nó trong đồng.'),
(1974, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 26, 'OT', 'Hãy thu lượm trong sáu ngày, còn ngày thứ bảy là ngày Sa-bát, sẽ không có gì trong ngày ấy.'),
(1975, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 27, 'OT', 'Ngày thứ bảy, dân chúng ra đi lượm lặt, nhưng không tìm được gì.'),
(1976, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 28, 'OT', 'Đức Giê-hô-va phán cùng Môi-se: Các ngươi sẽ không chịu vâng giữ các điều răn và luật lệ ta cho đến bao giờ?'),
(1977, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 29, 'OT', 'Hãy xem, Đức Giê-hô-va đã ban cho các ngươi ngày Sa-bát; vì vậy, Ngài ban cho các ngươi đồ ăn hai ngày trong ngày thứ sáu. Mỗi người hãy ở yên tại chỗ mình; chớ ai ra khỏi nơi mình ở trong ngày thứ bảy.'),
(1978, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 30, 'OT', 'Dân sự nghỉ ngày thứ bảy.'),
(1979, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 31, 'OT', 'Nhà Y-sơ-ra-ên gọi vật ấy là ma-na; nó như hột ngọc trai trắng, và mùi vị như bánh chiên ngọt làm bằng mật ong.'),
(1980, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 32, 'OT', 'Môi-se nói: "Đây là điều Đức Giê-hô-va đã truyền: Hãy lấy đầy một ô-me ma-na, để dành giữ lại cho các thế hệ của các ngươi, hầu cho họ thấy thứ bánh mà ta đã cho các ngươi ăn trong đồng vắng, khi ta dẫn các ngươi ra khỏi đất Ê-díp-tô."'),
(1981, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 33, 'OT', 'Môi-se nói cùng A-rôn: "Hãy lấy một cái khay, đặt vào đó đầy một ô-me ma-na, và để trước mặt Đức Giê-hô-va để giữ cho các thế hệ của các ngươi."'),
(1982, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 34, 'OT', 'Như Đức Giê-hô-va đã truyền cho Môi-se, thì A-rôn đã để nó trước chứng chỉ, để giữ gìn.'),
(1983, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 35, 'OT', 'Dân Y-sơ-ra-ên ăn ma-na bốn mươi năm, cho đến khi vào đất Ca-na-an có người ở; họ ăn ma-na cho đến khi vào nơi cuối cùng của đất Ca-na-an.'),
(1984, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 16, 36, 'OT', 'Và ô-me là một phần mười của ê-pha.'),
(1985, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 17, 1, 'OT', 'Cả hội chúng Y-sơ-ra-ên đi từ đồng vắng Sin, theo các trạm của họ, theo lệnh Đức Giê-hô-va, rồi đóng trại tại Rê-phi-đim; nhưng ở đó không có nước cho dân sự uống.'),
(1986, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 17, 2, 'OT', 'Dân sự tranh cãi với Môi-se, nói rằng: "Hãy cho chúng tôi nước để uống." Môi-se nói với họ: "Tại sao các ngươi tranh cãi với ta? Tại sao các ngươi thử Đức Giê-hô-va?"'),
(1987, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 17, 3, 'OT', 'Dân sự khát nước tại đó, nên oán trách Môi-se mà nói: "Tại sao ông đưa chúng tôi ra khỏi Ai-cập, để làm cho tôi cùng con cái và súc vật của tôi chết khát như thế này?"'),
(1988, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 17, 4, 'OT', 'Môi-se kêu cầu Đức Giê-hô-va và nói: Tôi phải làm gì với dân này? Chỉ một chút nữa là họ ném đá tôi rồi!'),
(1989, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 17, 5, 'OT', 'Đức Giê-hô-va phán cùng Môi-se: "Hãy đi trước mặt dân sự, và đem theo ngươi mấy trưởng lão Y-sơ-ra-ên; còn gậy ngươi đã dùng đập xuống sông, hãy cầm trong tay mà đi."'),
(1990, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 17, 6, 'OT', 'Nầy, ta sẽ đứng trước mặt ngươi ở đó trên hòn đá tại Hô-rếp; ngươi hãy đập vào hòn đá, thì nước sẽ chảy ra từ nó, và dân sự sẽ uống. Môi-se làm như vậy trước mặt các trưởng lão Y-sơ-ra-ên.'),
(1991, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 17, 7, 'OT', 'Người đặt tên cho nơi ấy là Ma-sa và Mê-ri-ba, vì sự cãi cọ của con cái Y-sơ-ra-ên và vì họ đã thử Đức Giê-hô-va mà nói rằng: Đức Giê-hô-va có ở giữa chúng ta chăng, hay là không?'),
(1992, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 17, 8, 'OT', 'Dân A-ma-léc đến đánh Y-sơ-ra-ên tại Rê-phi-đim.'),
(1993, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 17, 9, 'OT', 'Môi-se nói với Giô-suê: Hãy chọn những người cho chúng ta, và đi ra chiến đấu với dân A-ma-léc; ngày mai ta sẽ đứng trên đỉnh đồi, với cây gậy của Đức Chúa Trời trong tay ta.'),
(1994, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 17, 10, 'OT', 'Giô-suê làm theo như Môi-se nói, ra đánh dân A-ma-léc; còn Môi-se, A-rôn và Hu-rơ lên đầu ngọn núi.'),
(1995, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 17, 11, 'OT', 'Hễ khi Môi-se giơ tay lên thì Y-sơ-ra-ên thắng hơn; nhưng khi người xụi tay xuống thì A-ma-léc thắng hơn.'),
(1996, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 17, 12, 'OT', 'Tay Môi-se nặng quá, A-rôn và Hu-rơ bèn lấy một hòn đá đặt dưới người, rồi người ngồi trên đó; A-rôn và Hu-rơ nâng đỡ hai tay người, một người bên này, một người bên kia, và tay người cứ vững chắc cho đến khi mặt trời lặn.'),
(1997, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 17, 13, 'OT', 'Giô-suê đánh bại A-ma-léc và dân sự người bằng lưỡi gươm.'),
(1998, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 17, 14, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Hãy chép điều nầy làm kỷ niệm trong sách và nhắc vào tai Giô-suê rằng chính ta sẽ hoàn toàn xoá bỏ kỷ niệm về A-ma-léc dưới bầu trời.'),
(1999, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 17, 15, 'OT', 'Môi-se xây một bàn thờ và đặt tên là Giê-hô-va, cờ xí của tôi.'),
(2000, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 17, 16, 'OT', 'Người nói: Bởi tay chống lại ngôi Đức Giê-hô-va, nên Đức Giê-hô-va sẽ chinh chiến với A-ma-léc từ đời này sang đời kia.'),
(2001, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 18, 1, 'OT', 'Giê-trô, thầy tế lễ xứ Ma-đi-an, cha vợ của Môi-se, nghe được mọi điều Đức Chúa Trời đã làm cho Môi-se và cho Y-sơ-ra-ên, dân sự Ngài, vì Đức Giê-hô-va đã đem Y-sơ-ra-ên ra khỏi xứ Ê-díp-tô.'),
(2002, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 18, 2, 'OT', 'Giê-trô rước Sê-phô-ra, vợ Môi-se, sau khi đã để nàng trở về nhà cha nàng.'),
(2003, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 18, 3, 'OT', 'và hai con trai của người, tên đứa thứ nhất là Ghẹt-sôn, vì Môi-se nói: Tôi đã là một khách lạ tại đất nước ngoại bang;'),
(2004, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 18, 4, 'OT', 'Và tên đứa con thứ nhất là Ê-li-ê-xe, vì nói rằng: Đức Chúa Trời của cha tôi đã giúp đỡ tôi và giải cứu tôi khỏi gươm của Pha-ra-ôn.'),
(2005, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 18, 5, 'OT', 'Vậy Giê-trô, cha vợ của Môi-se, cùng các con trai và vợ của Môi-se, đến thăm Môi-se tại đồng vắng, nơi người đang đóng trại gần núi Đức Chúa Trời.'),
(2006, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 18, 6, 'OT', 'Giê-trô nói cùng Môi-se: "Tôi là cha vợ ngươi, Giê-trô, đến cùng ngươi, và vợ ngươi cùng hai con trai nàng đi với nàng."'),
(2007, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 18, 7, 'OT', 'Môi-se đi ra đón rước cha vợ mình, rồi cúi lạy và hôn người; mỗi người hỏi thăm người kia về sự bình an, sau đó hai người vào trại.'),
(2008, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 18, 8, 'OT', 'Môi-se thuật lại cho cha vợ mình mọi điều Đức Giê-hô-va đã làm cho Pha-ra-ôn và cho người Ê-díp-tô vì cớ Y-sơ-ra-ên, và mọi sự gian nan mà họ đã gặp trên đường, và Đức Giê-hô-va đã cứu họ thể nào.'),
(2009, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 18, 9, 'OT', 'Giê-trô vui mừng về mọi điều lành mà Đức Giê-hô-va đã làm cho Y-sơ-ra-ên, khi giải cứu họ khỏi tay người Ai-cập.'),
(2010, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 18, 10, 'OT', 'Giê-trô nói: Đáng ngợi khen Đức Giê-hô-va, là Đấng đã giải cứu các ngươi khỏi tay người Ai-cập và khỏi tay Pha-ra-ôn, và đã giải cứu dân sự khỏi tay người Ai-cập.'),
(2011, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 18, 11, 'OT', 'Bây giờ tôi biết rằng Đức Giê-hô-va lớn hơn mọi thần, vì trong điều mà chúng kiêu ngạo chống lại họ, thì Ngài đã thắng hơn họ.'),
(2012, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 18, 12, 'OT', 'Giê-trô, cha vợ của Môi-se, dâng của lễ thiêu và các của lễ tế cho Đức Chúa Trời; rồi A-rôn và mọi bậc trưởng lão của Y-sơ-ra-ên đến ăn bánh cùng cha vợ của Môi-se tại trước mặt Đức Chúa Trời.'),
(2013, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 18, 13, 'OT', 'Hôm sau, Môi-se ngồi xét đoán dân sự, và dân sự đứng trước mặt Môi-se từ sáng sớm cho đến chiều tối.'),
(2014, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 18, 14, 'OT', 'Ông gia thấy mọi điều người làm cho dân sự, liền nói: Điều này con đang làm cho dân sự là gì? Sao con chỉ ngồi một mình, còn cả dân sự đứng chực trước mặt con từ sáng sớm cho đến chiều tối?'),
(2015, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 18, 15, 'OT', 'Môi-se đáp với cha vợ rằng: "Bởi vì dân sự đến cùng tôi để cầu hỏi ý Đức Chúa Trời."'),
(2016, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 18, 16, 'OT', 'Vì khi nào họ có việc gì, thì đến cùng tôi; tôi xét đoán giữa người với người lân cận mình, và cho họ biết các mạng lệnh và luật pháp của Đức Chúa Trời.'),
(2017, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 18, 17, 'OT', 'Người cha vợ của Môi-se nói với người rằng: Điều con làm không tốt.'),
(2018, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 18, 18, 'OT', 'Con sẽ kiệt sức, cả con lẫn dân này ở với con, vì việc này quá nặng đối với con; con không thể làm một mình được.'),
(2019, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 18, 19, 'OT', 'Bây giờ hãy nghe theo tiếng nói của tôi, tôi sẽ chỉ bảo cho anh; và Đức Chúa Trời sẽ ở cùng anh. Anh hãy làm người thay mặt cho dân sự trước mặt Đức Giê-hô-va, và đem các việc đưa đến cùng Đức Chúa Trời.'),
(2020, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 18, 20, 'OT', 'Hãy chỉ bảo cho họ các luật lệ và các điều răn, và dạy họ con đường mà họ phải đi, và những việc mà họ phải làm.'),
(2021, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 18, 21, 'OT', 'Nhưng ngươi hãy chọn trong toàn dân những người tài giỏi, kính sợ Đức Chúa Trời, trung thực và ghét sự tham lam, rồi đặt họ lên làm các quan cai trị ngàn người, quan cai trị trăm người, quan cai trị năm mươi người và quan cai trị mười người,'),
(2022, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 18, 22, 'OT', 'Họ sẽ xét đoán dân chúng mọi lúc; và mọi việc lớn họ sẽ dâng lên cho ông, còn mọi việc nhỏ thì họ sẽ xét đoán; như vậy, ông sẽ giảm gánh nặng trên vai mình, và họ sẽ cùng chia sẻ gánh nặng với ông.'),
(2023, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 18, 23, 'OT', 'Nếu ngươi làm điều nầy, và Đức Chúa Trời phán dặn ngươi, thì ngươi sẽ chịu đựng nổi, và cả dân sự nầy cũng sẽ trở về bình an tại nơi mình.'),
(2024, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 18, 24, 'OT', 'Môi-se nghe theo tiếng của cha vợ mình, và làm tất cả mọi điều mà người đã nói.'),
(2025, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 18, 25, 'OT', 'Môi-se chọn những người tài năng trong toàn thể Y-sơ-ra-ên, và đặt họ làm các trưởng trên dân sự, làm các quan cai ngàn người, quan cai trăm người, quan cai năm mươi người, và quan cai mười người.'),
(2026, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 18, 26, 'OT', 'họ xét đoán dân sự hằng ngày; các việc khó thì đem trình lên Môi-se, còn các việc nhỏ thì họ xét xử.'),
(2027, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 18, 27, 'OT', 'Môi-se cho ông gia mình đi, và ông ấy trở về xứ mình.'),
(2028, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 19, 1, 'OT', 'Tháng thứ ba, sau khi dân Y-sơ-ra-ên ra khỏi xứ Ê-díp-tô, trong ngày đó họ đến đồng vắng Si-na-i.'),
(2029, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 19, 2, 'OT', 'Dân chúng rời Rê-phi-đim, đến đồng vắng Si-na-i và đóng trại trong đồng vắng; dân Y-sơ-ra-ên đóng trại tại đó, đối diện trước núi.'),
(2030, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 19, 3, 'OT', 'Môi-se lên đến Đức Chúa Trời, và Đức Giê-hô-va từ trên núi gọi người, phán rằng: Hãy nói điều nầy cho nhà Gia-cốp và báo cho con cái Y-sơ-ra-ên:'),
(2031, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 19, 4, 'OT', 'Các ngươi đã thấy điều ta đã làm cho người Ai Cập: ta đã mang các ngươi trên cánh chim ưng và đưa các ngươi đến cùng ta.'),
(2032, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 19, 5, 'OT', 'Vậy bây giờ, nếu các ngươi thực sự vâng nghe tiếng ta và giữ giao ước ta, thì các ngươi sẽ là đặc sản riêng của ta giữa mọi dân, vì cả đất đều thuộc về ta.'),
(2033, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 19, 6, 'OT', 'Các ngươi sẽ thuộc về ta làm một vương quốc các thầy tế lễ và một dân thánh; những lời nầy ngươi sẽ nói cho con cái Y-sơ-ra-ên.'),
(2034, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 19, 7, 'OT', 'Môi-se đến, gọi các trưởng lão trong dân sự, và đặt trước mặt họ mọi lời nầy, tức là tất cả những điều Đức Giê-hô-va đã truyền cho người.'),
(2035, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 19, 8, 'OT', 'Cả dân sự đồng thanh đáp rằng: Mọi điều Đức Giê-hô-va phán, chúng tôi sẽ làm. Môi-se bèn đem lời của dân sự trình lại cùng Đức Giê-hô-va.'),
(2036, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 19, 9, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Nầy, ta sẽ đến cùng ngươi trong đám mây dày đặc, để dân sự nghe khi ta phán cùng ngươi và cũng tin ngươi luôn luôn. Rồi Môi-se thuật lại các lời của dân sự cho Đức Giê-hô-va.'),
(2037, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 19, 10, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Hãy đi đến cùng dân sự, khiến họ giữ mình thánh sạch ngày nay và ngày mai, và phải giặt áo xống họ.'),
(2038, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 19, 11, 'OT', 'Qua ngày thứ ba, các ngươi phải sẵn sàng, vì vào ngày thứ ba ấy Đức Giê-hô-va sẽ ngự xuống trước mắt mọi người tại núi Si-na-i.'),
(2039, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 19, 12, 'OT', 'Ngươi hãy vạch ranh giới cho dân chúng chung quanh, mà dặn rằng: Hãy giữ mình, đừng lên núi hoặc đụng đến rìa núi; bất cứ ai đụng đến núi sẽ bị xử tử.'),
(2040, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 19, 13, 'OT', 'Đừng để tay mình động vào người ấy, vì phải ném đá hoặc bắn tên cho chết; dù là vật hay người, không được để sống. Khi kèn hiệu thổi lên, chúng mới được lên núi.'),
(2041, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 19, 14, 'OT', 'Môi-se đi xuống núi đến cùng dân sự, khiến họ giữ mình thánh sạch, và họ giặt áo xống mình.'),
(2042, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 19, 15, 'OT', 'Người bảo dân chúng rằng: Hãy sẵn sàng trong ba ngày; chớ đến gần vợ mình.'),
(2043, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 19, 16, 'OT', 'Sáng ngày thứ ba, có tiếng sấm, chớp nhoáng và một đám mây nặng nề đậu trên núi; tiếng kèn thổi rất mạnh vang dội, khiến toàn thể dân sự trong trại đều run rẩy sợ hãi.'),
(2044, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 19, 17, 'OT', 'Môi-se dẫn dân ra khỏi trại để gặp Đức Chúa Trời; họ đứng dưới chân núi.'),
(2045, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 19, 18, 'OT', 'Núi Si-na-i đầy khói tràn trề, vì Đức Giê-hô-va ngự xuống trên nó trong ngọn lửa; khói bay lên như khói của lò luyện kim, và toàn thể núi ấy run rẩy dữ dội.'),
(2046, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 19, 19, 'OT', 'Tiếng kèn phát ra ngày càng lớn và mạnh; Môi-se nói, Đức Chúa Trời đáp lại người bằng tiếng nói.'),
(2047, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 19, 20, 'OT', 'Đức Giê-hô-va ngự xuống núi Si-na-i, đến tận đỉnh núi; Đức Giê-hô-va gọi Môi-se lên tận đỉnh núi, và Môi-se liền lên.'),
(2048, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 19, 21, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Hãy xuống cảnh cáo dân chúng, e họ xông đến gần Đức Giê-hô-va mà nhìn, và nhiều người trong họ sẽ ngã chết.'),
(2049, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 19, 22, 'OT', 'Các thầy tế lễ vốn đến gần Đức Giê-hô-va cũng phải tự làm cho mình nên thánh, e rằng Đức Giê-hô-va sẽ đột kích họ.'),
(2050, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 19, 23, 'OT', 'Môi-se nói với Đức Giê-hô-va: "Dân sự không thể lên núi Si-na-i được, vì chính Ngài đã cảnh cáo chúng tôi rằng: Hãy định giới hạn quanh núi và biệt riêng nó làm thánh."'),
(2051, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 19, 24, 'OT', 'Đức Giê-hô-va phán cùng người rằng: Hãy đi xuống, ngươi và A-rôn sẽ lên cùng nhau; nhưng các thầy tế lễ và dân chúng không được xông lên cùng Đức Giê-hô-va, e Ngài đột kích họ.'),
(2052, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 19, 25, 'OT', 'Môi-se đi xuống đến dân sự và nói với họ.'),
(2053, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 20, 1, 'OT', 'Đức Chúa Trời phán mọi lời nầy, rằng:'),
(2054, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 20, 2, 'OT', 'Ta là Đức Giê-hô-va Đức Chúa Trời ngươi, Đấng đã đem ngươi ra khỏi đất nước Ai Cập, khỏi nhà của sự nô lệ.'),
(2055, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 20, 3, 'OT', 'Ngươi chớ có các thần nào khác trước mặt ta.'),
(2056, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 20, 4, 'OT', 'Ngươi không được làm tượng chạm cho mình, hay bất kỳ hình tượng nào giống như những vật ở trên trời cao, hoặc ở dưới đất thấp, hoặc trong nước dưới lòng đất.'),
(2057, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 20, 5, 'OT', 'Ngươi chớ cúi lạy chúng nó và chớ làm tôi chúng nó; vì ta là Đức Giê-hô-va Đức Chúa Trời ngươi, Đức Chúa Trời hay ghen, phạt tội cha ông cho con cháu đến đời thứ ba và thứ tư của những kẻ ghét ta.'),
(2058, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 20, 6, 'OT', 'và làm ơn đến ngàn đời cho những kẻ yêu mến ta và giữ các điều răn ta.'),
(2059, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 20, 7, 'OT', 'Chớ lấy danh Đức Giê-hô-va Đức Chúa Trời ngươi làm vô ích; vì Đức Giê-hô-va sẽ không cho kẻ nào lấy danh Ngài làm vô ích được khỏi tội.'),
(2060, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 20, 8, 'OT', 'Hãy nhớ ngày Sa-bát, để làm nên ngày thánh.'),
(2061, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 20, 9, 'OT', 'Ngươi hãy làm việc trong sáu ngày và làm mọi công việc của mình;'),
(2062, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 20, 10, 'OT', 'Còn ngày thứ bảy là ngày Sa-bát dành cho Đức Giê-hô-va Đức Chúa Trời ngươi: ngươi không được làm bất cứ công việc gì, cả ngươi, con trai, con gái, đầy tớ trai, tớ gái, súc vật của ngươi, và khách ngoại bang đang ở trong các cửa nhà ngươi.'),
(2063, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 20, 11, 'OT', 'vì trong sáu ngày Đức Giê-hô-va đã làm trời đất, biển và muôn vật ở trong đó, rồi nghỉ ngày thứ bảy; bởi vậy Đức Giê-hô-va đã ban phước cho ngày Sa-bát và biệt riêng ra làm thánh.'),
(2064, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 20, 12, 'OT', 'Hãy tôn trọng cha ngươi và mẹ ngươi, để cho những ngày của ngươi được kéo dài trên đất mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi.'),
(2065, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 20, 13, 'OT', 'Ngươi không được giết người.'),
(2066, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 20, 14, 'OT', 'Ngươi chớ phạm tội dâm dục.'),
(2067, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 20, 15, 'OT', 'Ngươi chớ trộm cắp.'),
(2068, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 20, 16, 'OT', 'Ngươi chớ làm chứng dối cho người lân cận mình.'),
(2069, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 20, 17, 'OT', 'Ngươi chớ tham nhà người lân cận ngươi; ngươi chớ tham vợ người lân cận ngươi, tôi trai, tớ gái, bò, lừa, hay là mọi vật chi thuộc về người lân cận ngươi.'),
(2070, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 20, 18, 'OT', 'Toàn dân thấy những tiếng sấm, những ngọn lửa, tiếng kèn và núi đầy khói; dân thấy thì run rẩy, và đứng từ xa.'),
(2071, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 20, 19, 'OT', 'Dân sự nói cùng Môi-se rằng: Chính ông hãy nói với chúng tôi, chúng tôi sẽ nghe; nhưng Đức Chúa Trời chớ phán cùng chúng tôi, e chúng tôi phải chết chăng.'),
(2072, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 20, 20, 'OT', 'Môi-se nói với dân chúng: "Đừng sợ, vì Đức Chúa Trời đã đến để thử các ngươi, và để sự kính sợ Ngài ở trên mặt các ngươi, hầu các ngươi không phạm tội."'),
(2073, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 20, 21, 'OT', 'Dân sự đứng ở xa, còn Môi-se lại gần nơi đám mây u ám, là nơi Đức Chúa Trời ngự.'),
(2074, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 20, 22, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Hãy nói cho con cái Y-sơ-ra-ên như vầy: Các ngươi đã thấy ta từ trên trời phán cùng các ngươi;'),
(2075, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 20, 23, 'OT', 'Chớ làm các thần bằng bạc hay bằng vàng để đối nghịch cùng ta.'),
(2076, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 20, 24, 'OT', 'Hãy làm cho ta một bàn thờ bằng đất, và hãy giết trên đó những lễ thiêu và lễ thù ân của ngươi, chiên hay bò của ngươi; tại bất kỳ nơi nào ta nhắc đến danh ta, ta sẽ đến cùng ngươi và ban phước cho ngươi.'),
(2077, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 20, 25, 'OT', 'Nếu ngươi làm cho ta một bàn thờ bằng đá, thì chớ dùng đá đã đẽo; vì nếu ngươi dùng rìu mà đập trên nó, thì đã làm nó ra ô uế rồi.'),
(2078, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 20, 26, 'OT', 'Ngươi chớ đi lên bằng những bậc thang đến bàn thờ ta, hầu cho sự lõa lồ ngươi không bị lộ ra trên đó.'),
(2079, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 1, 'OT', 'Đây là các điều luật mà ngươi phải đặt ra trước mặt chúng.'),
(2080, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 2, 'OT', 'Nếu ngươi mua một đầy tớ Hê-bơ-rơ, người ấy sẽ làm việc cho ngươi sáu năm; sang năm thứ bảy, người ấy sẽ ra đi tự do, không phải trả tiền.'),
(2081, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 3, 'OT', 'Nếu người ấy vào một mình, thì sẽ ra một mình; nếu là chồng một người vợ, thì vợ người ấy sẽ ra cùng với người ấy.'),
(2082, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 4, 'OT', 'Nếu chủ nó cưới vợ cho nó, mà người vợ ấy sinh con trai hay con gái, thì người vợ và các con của nàng đều thuộc về chủ, còn nó thì phải ra đi một mình.'),
(2083, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 5, 'OT', 'Nếu người đầy tớ nói: Tôi yêu chủ tôi, vợ tôi và các con tôi; tôi không muốn ra đi tự do,'),
(2084, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 6, 'OT', 'thì người chủ phải dẫn người ấy đến trước mặt Đức Chúa Trời, dẫn đến cửa hoặc trụ nhà, rồi lấy mũi khoan xỏ thủng tai; và người ấy sẽ làm tôi tớ cho chủ mình trọn đời.'),
(2085, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 7, 'OT', 'Nếu một người đàn ông bán con gái mình làm nữ tớ, thì nàng không được ra như cách ra của các kẻ tôi mọi.'),
(2086, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 8, 'OT', 'Nếu người nữ không đẹp lòng chủ mình, vì ông đã không chọn nàng làm vợ mình, thì ông phải chuộc lại nàng; ông không được bán nàng cho dân ngoại, vì đã lừa dối nàng.'),
(2087, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 9, 'OT', 'Nếu người ta định gả nàng cho con trai mình, thì phải đối xử với nàng theo luật đối với con gái.'),
(2088, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 10, 'OT', 'Nếu người ấy lấy thêm vợ khác, thì không được giảm bớt thức ăn, quần áo và bổn phận vợ chồng của người vợ thứ nhất.'),
(2089, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 11, 'OT', 'Nếu không làm ba điều ấy cho nàng, thì nàng được ra đi tự do, không phải đền tiền.'),
(2090, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 12, 'OT', 'Ai đánh người nào làm chết, sẽ bị xử tử.'),
(2091, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 13, 'OT', 'Và nếu người đó không cố ý giết, mà Đức Chúa Trời đã để người bị giết vào tay người đó, thì Ta sẽ chỉ định cho ngươi một nơi mà người đó có thể trốn đến.'),
(2092, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 14, 'OT', 'Nếu có người nào toan tính hại bạn mình để giết cách gian ác, thì phải bắt kẻ đó từ nơi bàn thờ ta mà xử tử.'),
(2093, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 15, 'OT', 'Ai đánh cha mình hay mẹ mình thì phải bị xử tử.'),
(2094, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 16, 'OT', 'Ai bắt cóc một người rồi bán hoặc giữ người ấy trong tay mình, thì phải bị xử tử.'),
(2095, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 17, 'OT', 'Ai xúc phạm cha hay mẹ mình, phải bị xử tử.'),
(2096, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 18, 'OT', 'Khi người ta xô xát nhau, nếu một người đánh kẻ khác bằng đá hay bằng nắm tay, mà người bị đánh không chết nhưng phải nằm trên giường,'),
(2097, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 19, 'OT', 'Nếu người bị đánh đứng dậy được và đi ra ngoài với cây gậy chống, thì người đánh sẽ được tha; nhưng phải bồi thường tiền mất công cho những ngày nghỉ và lo thuốc thang cho đến khi lành hẳn.'),
(2098, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 20, 'OT', 'Nếu người nào đánh tôi trai hay tớ gái mình bằng cây gậy, mà người đó chết ngay tại tay mình, thì phải bị trừng phạt.'),
(2099, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 21, 'OT', 'Nhưng nếu còn sống một ngày hay hai ngày, thì chủ không bị trừng phạt, vì tiền bạc của chủ đã mua nó.'),
(2100, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 22, 'OT', 'Nếu có người đàn ông đánh nhau, vô ý đánh trúng một phụ nữ có thai khiến đứa trẻ ra khỏi bụng mẹ, nhưng không xảy ra tai họa nghiêm trọng nào, thì người gây ra việc ấy phải bị phạt tiền tùy theo số tiền mà chồng người phụ nữ sẽ ấn định, và phải nộp tiền đó trước mặt các quan xét.'),
(2101, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 23, 'OT', 'Nếu xảy ra tai hại, thì phải lấy mạng người này đền mạng người kia.'),
(2102, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 24, 'OT', 'mắt thường mắt, răng thường răng, tay thường tay, chân thường chân,'),
(2103, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 25, 'OT', 'phỏng thường phỏng, bầm thường bầm, vết thương thường vết thương.'),
(2104, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 26, 'OT', 'Nếu một người đánh làm hỏng mất mắt của đầy tớ trai hay đầy tớ gái mình, thì phải để người ấy được tự do vì mắt đó.'),
(2105, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 27, 'OT', 'Nếu ai làm rụng răng của đầy tớ trai hay gái mình, thì phải để nó được tự do vì cớ mất răng ấy.'),
(2106, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 28, 'OT', 'Nếu một con bò đâm một người đàn ông hay một người đàn bà đến chết, con bò ấy sẽ bị ném đá cho chết, thịt nó sẽ không được ăn; còn chủ con bò thì vô tội.'),
(2107, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 29, 'OT', 'Nếu một con bò đã từng húc từ trước, mà chủ nó đã bị cảnh cáo rồi nhưng không giữ nó, và nó làm chết một người đàn ông hay một người đàn bà, thì con bò ấy sẽ bị ném đá chết, và chính chủ nó cũng sẽ bị xử tử.'),
(2108, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 30, 'OT', 'Nếu người ta đặt tiền chuộc mạng cho hắn, thì hắn phải nộp giá chuộc mạng sống mình tùy theo bất cứ điều gì được đặt trên hắn.'),
(2109, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 31, 'OT', 'Hoặc trâu húc một đứa con trai hay là một đứa con gái, thì phải xử cho người ấy theo luật lệ nầy.'),
(2110, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 32, 'OT', 'Nếu con bò đâm chết một người đầy tớ trai hay một người đầy tớ gái, chủ bò phải nộp ba mươi miếng bạc cho chủ người ấy, còn con bò thì sẽ bị ném đá chết.'),
(2111, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 33, 'OT', 'Nếu một người nào đào hầm hay mở miệng giếng mà không đậy lại, và có bò hay lừa nào sa xuống đó,'),
(2112, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 34, 'OT', 'Chủ hầm phải bồi thường tiền; tiền đó sẽ trả cho chủ con vật, còn con vật chết thì thuộc về chủ hầm.'),
(2113, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 35, 'OT', 'Khi bò của người này húc chết bò của người khác, thì phải bán con bò sống và chia tiền; và cũng phải chia con bò chết.'),
(2114, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 21, 36, 'OT', 'Nếu người ta đã biết con bò có tật hay húc, từ hôm qua hay hôm kia, mà chủ nó không giữ nó lại, thì chủ phải bồi thường: bò đổi lấy bò, còn con bò chết sẽ thuộc về chủ nó.'),
(2115, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 22, 1, 'OT', 'Nếu ai bắt trộm bò hay chiên, rồi giết hoặc bán đi, thì phải bồi thường năm con bò thay cho một con bò, và bốn con chiên thay cho một con chiên.'),
(2116, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 22, 2, 'OT', 'Nếu tên trộm bị bắt lúc đang đào ngạch mà bị đánh chết, thì người đánh không phải mang tội giết người.'),
(2117, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 22, 3, 'OT', 'Nếu mặt trời đã mọc chiếu trên người ấy, thì người ấy mang tội huyết; phải đền bồi đầy đủ; nếu không có gì, thì phải bị bán đền cho tội trộm của mình.'),
(2118, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 22, 4, 'OT', 'Nếu vật trộm bị bắt gặp còn sống trong tay kẻ trộm, dù là bò, lừa hay chiên, thì phải bồi thường gấp đôi.'),
(2119, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 22, 5, 'OT', 'Nếu ai để súc vật mình ăn trong ruộng hay vườn nho, rồi thả nó ăn trong ruộng của kẻ khác, thì phải lấy hoa lợi tốt nhất của ruộng mình và hoa lợi tốt nhất của vườn nho mình mà đền bồi.'),
(2120, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 22, 6, 'OT', 'Nếu lửa bùng lên và lan đến đống rơm, hoặc lúa đang chín, hoặc cánh đồng, thì người làm lửa bùng lên phải bồi thường trọn vẹn vật bị cháy.'),
(2121, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 22, 7, 'OT', 'Khi người nào giao tiền hoặc đồ vật cho người lân cận mình giữ, mà bị trộm lấy tại nhà người ấy, nếu tên trộm bị bắt được thì phải bồi thường gấp đôi.'),
(2122, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 22, 8, 'OT', 'Nếu kẻ trộm không bị tìm thấy, thì chủ nhà phải đến gần Đức Chúa Trời, để xét xem người ấy có giơ tay phạm đến tài sản của người lân cận mình hay không.'),
(2123, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 22, 9, 'OT', 'Trong mọi việc phạm tội, về một con bò, một con lừa, một con chiên, một cái áo hay bất cứ vật gì bị mất, mà người nầy nói: "Đây chính là vật của tôi", thì phải đem vụ việc của hai bên đến trước mặt Đức Chúa Trời; người nào bị Đức Chúa Trời xử là có tội phải bồi thường gấp hai cho người lân cận mình.'),
(2124, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 22, 10, 'OT', 'Nếu một người giao cho người lân cận mình lừa, bò, chiên hay bất kỳ loài vật nào để giữ, mà vật ấy chết, gãy chân hay bị bắt đi, không ai thấy,'),
(2125, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 22, 11, 'OT', 'Hai bên phải lấy danh Đức Giê-hô-va mà thề, để xem người ấy có đặt tay trên tài sản của người lân cận mình hay không; chủ vật sẽ nhận lời thề ấy, và người kia không phải bồi thường.'),
(2126, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 22, 12, 'OT', 'Nếu vật ấy bị kẻ trộm lấy khỏi tay người đó, thì người ấy phải bồi thường cho chủ vật.'),
(2127, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 22, 13, 'OT', 'Nếu vật bị xé nát bởi thú dữ, người giữ phải mang nó đến làm chứng; người ấy sẽ không phải đền bù cho vật bị xé đó.'),
(2128, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 22, 14, 'OT', 'Nếu một người mượn một vật từ người khác, mà vật ấy bị hư hại hoặc chết, mà chủ nó không có mặt cùng, thì người mượn phải bồi thường đầy đủ.'),
(2129, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 22, 15, 'OT', 'Nếu chủ vật ở cùng với người đó, thì không phải bồi thường; nếu là vật mướn, thì tiền mướn sẽ thế cho tiền bồi thường.'),
(2130, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 22, 16, 'OT', 'Nếu một người đàn ông quyến rũ một người gái đồng trinh chưa đính hôn và nằm với nàng, thì phải cưới nàng làm vợ, nộp tiền sính lễ cho nàng.'),
(2131, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 22, 17, 'OT', 'Nếu cha người nữ từ chối không chịu gả cho người ấy, thì người ấy phải nộp tiền, theo số tiền sính lễ của các người gái đồng trinh.'),
(2132, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 22, 18, 'OT', 'Không được để sống nữ phù thủy.'),
(2133, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 22, 19, 'OT', 'Người nào nằm với thú vật phải bị giết chết.'),
(2134, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 22, 20, 'OT', 'Kẻ nào dâng của lễ cho các thần khác ngoài Đức Giê-hô-va mà chỉ mình Ngài thôi, thì sẽ bị diệt vong.'),
(2135, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 22, 21, 'OT', 'Chớ bắt nạt người ngoại bang, cũng đừng hà hiếp người ấy, vì các ngươi đã từng làm khách kiều ngụ trong đất Ai Cập.'),
(2136, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 22, 22, 'OT', 'Chớ ức hiếp bất kỳ góa phụ hay kẻ mồ côi nào.'),
(2137, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 22, 23, 'OT', 'Nếu ức hiếp người ấy, và người ấy kêu cứu ta, thì ta sẽ nghe tiếng kêu của người ấy.'),
(2138, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 22, 24, 'OT', 'Nếu cơn giận ta bừng lên, ta sẽ giết các ngươi bằng gươm, và vợ các ngươi sẽ trở nên goá bụa, con các ngươi sẽ mồ côi.'),
(2139, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 22, 25, 'OT', 'Nếu ngươi cho dân ta, kẻ nghèo ở cùng ngươi, vay tiền, thì chớ xử ngươi như kẻ cho vay; cũng đừng bắt người phải chịu lời.'),
(2140, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 22, 26, 'OT', 'Nếu ngươi giữ áo choàng của người lân cận làm vật thế chấp, phải trả lại cho người ấy trước khi mặt trời lặn.'),
(2141, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 22, 27, 'OT', 'vì đó là áo che thân duy nhất của người ấy, là áo mặc trên thân; người ấy sẽ nằm ngủ bằng gì? Nếu người ấy kêu cứu ta, ta sẽ nghe, vì ta là Đấng hay thương xót.'),
(2142, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 22, 28, 'OT', 'Đức Chúa Trời, ngươi không được rủa sả; và người cầm quyền trong dân ngươi, ngươi không được nguyền rủa.'),
(2143, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 22, 29, 'OT', 'Ngươi không được trì hoãn dâng cho Ta đầy đủ kho lẫm và nơi ép rượu của ngươi; con trai đầu lòng ngươi, ngươi phải dâng cho Ta.'),
(2144, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 22, 30, 'OT', 'Về phần bò và chiên của ngươi, ngươi cũng phải làm như vậy: trong bảy ngày, nó ở cùng với mẹ nó; đến ngày thứ tám, ngươi phải dâng nó cho Ta.'),
(2145, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 22, 31, 'OT', 'Các ngươi phải là những người thánh dành riêng cho Ta; không được ăn thịt bị xé nát ngoài đồng; phải ném thịt ấy cho chó.'),
(2146, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 1, 'OT', 'Chớ nói lời vu khống; chớ hiệp tay cùng kẻ ác mà làm chứng gian.'),
(2147, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 2, 'OT', 'Ngươi không được theo đám đông làm điều ác; cũng không được thiên vị phe đông mà làm chứng gian, lệch khỏi lẽ công bình.'),
(2148, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 3, 'OT', 'Ngươi không được thiên vị người nghèo trong vụ kiện của người ấy.'),
(2149, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 4, 'OT', 'Nếu ngươi gặp bò hay lừa của kẻ thù mình bị đi lạc, phải trả lại cho người ấy.'),
(2150, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 5, 'OT', 'Nếu ngươi thấy lừa của kẻ thù mình nằm gục dưới gánh nặng, chớ từ chối giúp đỡ; phải giúp người ấy cùng nhau gánh vác.'),
(2151, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 6, 'OT', 'Đừng làm lệch công lý của người nghèo khi người ấy tranh tụng.'),
(2152, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 7, 'OT', 'Hãy tránh xa lời nói dối, và chớ giết người vô tội và người công bình, vì ta không cho kẻ ác được trắng án.'),
(2153, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 8, 'OT', 'Chớ nhận của hối lộ, vì của hối lộ làm mờ mắt người sáng suốt và làm sai lệch lời nói của người công chính.'),
(2154, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 9, 'OT', 'Ngươi không được hà hiếp người ngoại kiều, vì chính các ngươi đã biết rõ tâm trạng của người ngoại kiều, bởi các ngươi cũng từng là những người ngoại kiều tại đất nước Ai Cập.'),
(2155, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 10, 'OT', 'Sáu năm, ngươi hãy gieo trồng đất nước ngươi và thu hoạch các sản vật của nó.'),
(2156, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 11, 'OT', 'Nhưng năm thứ bảy, ngươi phải để đất nghỉ, phải bỏ mặc hoang, để kẻ nghèo khổ trong dân ngươi ăn lấy sản vật nó, và phần còn lại thì thú vật ngoài đồng ăn. Ngươi cũng phải làm như vậy đối với vườn nho ngươi và cây ô-li-ve ngươi.'),
(2157, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 12, 'OT', 'Sáu ngày, ngươi hãy làm công việc của mình; nhưng ngày thứ bảy, ngươi phải nghỉ, hầu cho bò và lừa ngươi được nghỉ ngơi, và con trai của nữ tôi tớ ngươi cùng người ngoại bang được phục hồi sức lực.'),
(2158, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 13, 'OT', 'Hãy giữ mọi điều ta phán cùng các ngươi. Đừng nhắc đến danh các thần khác; danh ấy chẳng được lọt vào miệng các ngươi.'),
(2159, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 14, 'OT', 'Hằng năm, ngươi phải giữ ba kỳ lễ kính ta.'),
(2160, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 15, 'OT', 'Hãy giữ lễ bánh không men: trong bảy ngày phải ăn bánh không men, đúng như ta đã truyền cho ngươi, vào thời kỳ chỉ định trong tháng giêng, vì trong tháng ấy ngươi ra khỏi Ai Cập; và không ai được đến trước mặt ta tay không.'),
(2161, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 16, 'OT', 'Hãy giữ lễ mùa gặt, tức là những trái đầu tiên của công việc ngươi, mà ngươi đã gieo ngoài đồng; và lễ thu hoạch vào cuối năm, khi ngươi thu góp các sản phẩm của công việc ngươi từ ngoài đồng.'),
(2162, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 17, 'OT', 'Mỗi năm ba lần, mọi người nam trong các ngươi phải xuất hiện trước mặt Đức Giê-hô-va.'),
(2163, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 18, 'OT', 'Đừng dâng huyết sinh tế của ta trên bánh có men, và đừng để mỡ lễ vật của ta qua đêm cho đến sáng mai.'),
(2164, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 19, 'OT', 'Hãy mang những hoa quả đầu mùa của đất ngươi đến nhà Đức Giê-hô-va Đức Chúa Trời ngươi. Đừng nấu dê con trong sữa mẹ nó.'),
(2165, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 20, 'OT', 'Nầy, ta đang sai một thiên sứ đi trước mặt ngươi, để bảo vệ ngươi trên đường đi, và dẫn ngươi đến nơi ta đã chuẩn bị sẵn.'),
(2166, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 21, 'OT', 'Hãy giữ mình trước mặt người, phải nghe theo lời người, chớ chống nghịch lại người; vì người sẽ không tha tội cho các ngươi, bởi danh Ta ở trong người.'),
(2167, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 22, 'OT', 'Nếu ngươi thực sự vâng nghe tiếng người và làm theo mọi điều ta phán dạy, ta sẽ trở thành kẻ thù của kẻ thù ngươi và chống lại những kẻ chống ngươi.'),
(2168, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 23, 'OT', 'Vì thiên sứ của ta sẽ đi trước mặt ngươi, dẫn ngươi đến với dân A-mô-rít, dân Hê-tít, dân Phê-rê-sít, dân Ca-na-an, dân Hê-vít và dân Giê-bu-sít, rồi ta sẽ tiêu diệt chúng nó.'),
(2169, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 24, 'OT', 'Ngươi chớ cúi lạy các thần của chúng nó, cũng chớ phục vụ chúng, và chớ làm theo các việc chúng nó làm; nhưng ngươi phải phá hủy chúng triệt để và đập bể các trụ đá của chúng nó.'),
(2170, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 25, 'OT', 'Ngươi phải phục sự Đức Giê-hô-va Đức Chúa Trời ngươi, thì Ngài sẽ ban phước cho lương thực và nước ngươi, và Ta sẽ dẹp bệnh tật khỏi giữa vòng ngươi.'),
(2171, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 26, 'OT', 'Trong đất nước ngươi sẽ không có người sảy thai hay người son sẻ; Ta sẽ cho đầy số các ngày của ngươi.'),
(2172, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 27, 'OT', 'Ta sẽ sai sự kinh khủng của Ta đi trước mặt ngươi, và làm cho mọi dân mà ngươi đến bị khuấy động, rồi Ta sẽ khiến mọi kẻ thù nghịch ngươi quay lưng chạy trốn trước mặt ngươi.'),
(2173, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 28, 'OT', 'Ta sẽ sai ong lỗ đi trước mặt ngươi để đuổi dân Hê-vít, dân Ca-na-an và dân Hê-tít khỏi trước mặt ngươi.'),
(2174, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 29, 'OT', 'Ta sẽ không đuổi chúng nó ra khỏi trước mặt ngươi trong một năm, e rằng đất sẽ trở nên hoang vu, và loài thú đồng sẽ sanh sản đông lên hại ngươi.'),
(2175, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 30, 'OT', 'Ta sẽ đuổi chúng nó ra khỏi trước mặt ngươi từng chút một, cho đến khi ngươi sinh sản đông đúc và chiếm hữu đất ấy làm sản nghiệp.'),
(2176, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 31, 'OT', 'Ta sẽ định biên giới ngươi từ Biển Đỏ cho đến biển Phi-li-tin, và từ đồng vắng cho đến sông cái; vì Ta sẽ phó dân cư trong xứ ấy vào tay ngươi, và ngươi sẽ đuổi chúng nó ra khỏi trước mặt ngươi.'),
(2177, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 32, 'OT', 'Đừng lập giao ước với chúng nó hoặc với các thần của chúng nó.'),
(2178, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 23, 33, 'OT', 'Họ không được ở trong đất nước của ngươi, e rằng họ sẽ khiến ngươi phạm tội cùng ta, vì ngươi sẽ thờ các thần của họ; điều đó sẽ trở thành một cái bẫy cho ngươi.'),
(2179, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 24, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Ngươi và A-rôn, Na-đáp, A-bi-hu cùng bảy mươi trưởng lão Y-sơ-ra-ên hãy lên cùng Đức Giê-hô-va; các ngươi sẽ thờ lạy từ xa.'),
(2180, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 24, 2, 'OT', 'Chỉ một mình Môi-se sẽ đến gần Đức Giê-hô-va, còn họ không được đến gần, và dân sự cũng không được lên cùng người.'),
(2181, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 24, 3, 'OT', 'Môi-se đến thuật lại cho dân sự mọi lời của Đức Giê-hô-va và mọi luật lệ; cả dân sự đều đồng thanh đáp rằng: Mọi lời mà Đức Giê-hô-va đã phán, chúng tôi sẽ làm.'),
(2182, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 24, 4, 'OT', 'Môi-se chép hết thảy các lời của Đức Giê-hô-va, rồi dậy sớm ngày hôm sau, xây một bàn thờ dưới chân núi và dựng mười hai trụ đá, tượng trưng cho mười hai chi phái Y-sơ-ra-ên.'),
(2183, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 24, 5, 'OT', 'Người sai các thiếu niên trong dân Y-sơ-ra-ên đi, và họ dâng những của lễ thiêu, cùng tế những của lễ thù ân cho Đức Giê-hô-va bằng những con bò tơ.'),
(2184, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 24, 6, 'OT', 'Môi-se lấy phân nửa lượng huyết và đổ vào các chậu, còn phân nửa lượng huyết thì rảy lên bàn thờ.'),
(2185, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 24, 7, 'OT', 'Người lấy sách giao ước mà đọc cho dân sự nghe; thì họ nói: Mọi điều Đức Giê-hô-va phán, chúng tôi sẽ làm và vâng theo.'),
(2186, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 24, 8, 'OT', 'Môi-se lấy huyết rưới trên dân sự và nói: "Nầy là huyết của giao ước mà Đức Giê-hô-va đã lập cùng các ngươi trên mọi lời nầy."'),
(2187, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 24, 9, 'OT', 'Môi-se cùng với A-rôn, Na-đáp và A-bi-hu, và bảy mươi trưởng lão của Y-sơ-ra-ên đều lên núi.'),
(2188, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 24, 10, 'OT', 'Họ thấy Đức Chúa Trời của Y-sơ-ra-ên; dưới chân Ngài như công việc bằng đá xanh lam, và như bản chất của trời trong sạch.'),
(2189, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 24, 11, 'OT', 'Nhưng Ngài không tra tay vào những người quyền quý trong vòng con cái Y-sơ-ra-ên; họ được thấy Đức Chúa Trời, rồi ăn và uống.'),
(2190, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 24, 12, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Hãy lên núi cùng ta và ở đó; ta sẽ ban cho ngươi các bảng đá, và luật pháp cùng điều răn mà ta đã chép để dạy dỗ chúng.'),
(2191, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 24, 13, 'OT', 'Môi-se bèn đứng dậy, cùng Giô-suê, người hầu việc mình; rồi Môi-se đi lên núi Đức Chúa Trời.'),
(2192, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 24, 14, 'OT', 'Người nói cùng các trưởng lão: "Hãy ngồi chờ chúng tôi tại đây cho đến khi chúng tôi trở lại cùng các ông. Nầy, A-rôn và Hu-rơ ở cùng các ông; ai có việc gì thì hãy đến cùng hai người ấy."'),
(2193, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 24, 15, 'OT', 'Môi-se lên núi, và mây che phủ núi.'),
(2194, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 24, 16, 'OT', 'Sự vinh hiển của Đức Giê-hô-va ngự trên núi Si-na-i, và mây che phủ nó trong sáu ngày; rồi ngày thứ bảy, Đức Giê-hô-va gọi Môi-se từ giữa đám mây.'),
(2195, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 24, 17, 'OT', 'Cảnh tượng vinh quang của Đức Giê-hô-va giống như ngọn lửa thiêu đốt trên đỉnh núi, trước mắt con cái Y-sơ-ra-ên.'),
(2196, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 24, 18, 'OT', 'Môi-se vào trong đám mây, rồi lên núi; và Môi-se ở trên núi bốn mươi ngày và bốn mươi đêm.'),
(2197, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(2198, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 2, 'OT', 'Hãy nói cùng con cái Y-sơ-ra-ên, để họ dâng lễ vật cho ta; các ngươi hãy nhận lấy lễ vật của ta từ mỗi người nào có lòng hăng hái dâng lên.'),
(2199, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 3, 'OT', 'Nầy là lễ vật mà các ngươi sẽ nhận lấy từ họ: vàng, bạc, và đồng;'),
(2200, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 4, 'OT', 'chỉ tím, chỉ đỏ, chỉ đỏ điều, vải gai mịn và lông dê'),
(2201, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 5, 'OT', 'da chiên đực nhuộm đỏ, da thú biển, và gỗ cây si-tim,'),
(2202, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 6, 'OT', 'dầu để thắp sáng, các loại hương liệu để làm dầu xức và để làm hương,'),
(2203, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 7, 'OT', 'đá ô-phan và các đá khảm để làm áo ê-phót và bảng đeo ngực.'),
(2204, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 8, 'OT', 'Họ sẽ làm cho ta một đền thánh, để ta ở giữa họ.'),
(2205, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 9, 'OT', 'Hãy làm mọi điều theo đúng kiểu mẫu mà ta chỉ cho ngươi, tức là kiểu mẫu của đền tạm và kiểu mẫu của mọi đồ dùng thuộc về nó.'),
(2206, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 10, 'OT', 'Họ phải làm một cái rương bằng gỗ si-tim, dài hai thước rưỡi, rộng một thước rưỡi, và cao một thước rưỡi.'),
(2207, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 11, 'OT', 'Hãy mạ nó bằng vàng ròng, từ bên trong và bên ngoài; rồi làm một viền vàng chung quanh trên đó.'),
(2208, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 12, 'OT', 'Hãy đúc cho nó bốn cái khoen bằng vàng và đặt trên bốn góc của nó; hai cái khoen ở bên hông này, và hai cái khoen ở bên hông kia.'),
(2209, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 13, 'OT', 'Hãy làm các cây đòn bằng gỗ si-tim, và bọc chúng bằng vàng.'),
(2210, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 14, 'OT', 'Và ngươi hãy tra các cây đòn vào các vòng ở hai bên hông hòm, để lấy các cây đòn ấy khiêng hòm.'),
(2211, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 15, 'OT', 'Các cây đòn phải ở trong các vòng của hòm, không được rút ra khỏi nó.'),
(2212, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 16, 'OT', 'Ngươi sẽ đặt vào trong hòm bảng chứng mà ta sẽ ban cho ngươi.'),
(2213, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 17, 'OT', 'Ngươi phải làm một cái nắp thương xót bằng vàng ròng, dài hai thước rưỡi và rộng một thước rưỡi.'),
(2214, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 18, 'OT', 'Hãy làm hai tượng chê-ru-bin bằng vàng; các ngươi phải làm chúng bằng cách đúc liền từ hai đầu mút của nắp thi ân.'),
(2215, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 19, 'OT', 'Làm một con chê-ru-bim ở đầu này và một con chê-ru-bim ở đầu kia, hai con chê-ru-bim đó phải làm cùng một khối với nắp ở hai đầu của nắp ấy.'),
(2216, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 20, 'OT', 'Hai con chê-ru-bin sẽ giang cánh ra phía trên, lấy cánh che phủ trên nắp thi ân; mặt chúng hướng về nhau, và mặt của hai con chê-ru-bin đều hướng về phía nắp thi ân.'),
(2217, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 21, 'OT', 'Ngươi hãy đặt nắp che phủ lên hòm bia từ phía trên, và ngươi hãy đặt vào trong hòm bia bảng chứng mà Ta sẽ ban cho ngươi.'),
(2218, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 22, 'OT', 'Ta sẽ hẹn gặp ngươi tại đó, và Ta sẽ phán cùng ngươi từ trên nắp chỗ đặt hai tượng Kê-ru-bim, trên hòm bảng chứng, mọi điều mà Ta sẽ truyền cho ngươi về dân Y-sơ-ra-ên.'),
(2219, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 23, 'OT', 'Hãy làm một cái bàn bằng gỗ acacia, dài hai thước, rộng một thước, cao một thước rưỡi.'),
(2220, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 24, 'OT', 'Bọc nó bằng vàng ròng, và làm cho nó một viền vàng chung quanh.'),
(2221, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 25, 'OT', 'và ngươi hãy làm cho nó một cái thành cao một gang tay chung quanh, và ngươi hãy làm một cái viền vàng cho cái thành của nó chung quanh.'),
(2222, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 26, 'OT', 'Và ngươi hãy làm cho nó bốn cái vòng vàng, rồi đặt các vòng đó vào bốn góc ở nơi bốn chân của nó.'),
(2223, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 27, 'OT', 'Các vòng sẽ ở đối diện viền, làm chỗ xỏ các cây đòn để khiêng bàn.'),
(2224, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 28, 'OT', 'Ngươi phải làm các đòn bằng gỗ si-tim, bọc vàng các đòn đó, và dùng các đòn đó mà khiêng bàn.'),
(2225, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 29, 'OT', 'Hãy làm các dĩa, chén, thìa và bình rót của nó, mà dùng để rót lễ quán; phải làm các vật ấy bằng vàng ròng.'),
(2226, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 30, 'OT', 'Trên bàn ngươi sẽ đặt bánh của sự hiện diện để trước mặt ta luôn luôn.'),
(2227, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 31, 'OT', 'Ngươi phải làm một chân đèn bằng vàng ròng; chân đèn, thân nó, các chén, các hình trái hạnh và các bông hoa phải làm liền một khối với nó.'),
(2228, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 32, 'OT', 'Sáu cây nhánh sẽ từ thân đèn mà ra, ba cây nhánh của chân đèn ở phía nầy và ba cây nhánh của chân đèn ở phía kia.'),
(2229, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 33, 'OT', 'Ba cái chén hình trái hạnh nhân nở hoa cùng với bầu và hoa trên một nhánh, và ba cái chén hình trái hạnh nhân nở hoa cùng với bầu và hoa trên nhánh kia; cứ như thế cho sáu nhánh phát ra từ chân đèn.'),
(2230, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 34, 'OT', 'Trên chân đèn, có bốn cái chén hình trái hạnh, cái nở và hoa của nó.'),
(2231, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 35, 'OT', 'Và một bông tròn dưới hai nhánh từ nó mọc ra, một bông tròn dưới hai nhánh từ nó mọc ra, và một bông tròn dưới hai nhánh từ nó mọc ra; cho sáu nhánh mọc ra từ chân đèn.'),
(2232, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 36, 'OT', 'Bầu của nó và các nhánh của nó sẽ làm cùng với nó; toàn bộ nó sẽ làm bằng một khối vàng ròng.'),
(2233, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 37, 'OT', 'Ngươi phải làm bảy cái đèn của nó, và phải thắp bảy cái đèn của nó, để chiếu sáng về phía trước mặt nó.'),
(2234, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 38, 'OT', 'Và cái kéo cùng cái xẻng đựng tro của nó phải làm bằng vàng ròng.'),
(2235, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 39, 'OT', 'Dùng một ta-lâng vàng ròng làm chân đèn nầy và các đồ dùng của nó.'),
(2236, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 25, 40, 'OT', 'Vậy, hãy xem và làm theo mẫu đã chỉ cho ngươi trên núi.'),
(2237, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 1, 'OT', 'Ngươi phải làm đền tạm bằng mười bức màn, bằng sợi gai mịn, màu tím, đỏ điều và đỏ sậm, có hình các chê-ru-bin thêu theo kiểu thợ khéo làm.'),
(2238, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 2, 'OT', 'Mỗi bức màn dài hai mươi tám thước, rộng bốn thước. Các bức màn đều cùng một kích cỡ.'),
(2239, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 3, 'OT', 'Năm bức màn sẽ nối kết với nhau, mỗi bức kết với bức kề bên nó; và năm bức màn khác cũng nối kết với nhau, mỗi bức kết với bức kề bên nó.'),
(2240, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 4, 'OT', 'Ngươi hãy làm những cái móc bằng chỉ tím ở mép của bức màn đầu tiên nơi đầu mối nối, và cũng vậy, ngươi hãy làm ở mép của bức màn ngoài cùng nơi mối nối thứ hai.'),
(2241, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 5, 'OT', 'Làm năm mươi cái móc nơi bức màn này, và làm năm mươi cái móc nơi mép bức màn kia trong mối nối thứ hai; các móc phải đối xứng từng cặp, cái này đối diện cái kia.'),
(2242, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 6, 'OT', 'Hãy làm năm mươi cái móc bằng vàng, rồi nối các tấm màn lại với nhau bằng những cái móc đó, và đền tạm sẽ trở thành một.'),
(2243, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 7, 'OT', 'Ngươi phải làm mười một bức màn bằng lông dê, để làm mái che trên nơi thánh. Mười một bức màn đó, ngươi phải làm như vậy.'),
(2244, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 8, 'OT', 'Mỗi tấm màn dài ba mươi thước, rộng bốn thước; mười một tấm màn đều cùng một kích thước.'),
(2245, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 9, 'OT', 'Ngươi hãy nối năm bức màn riêng ra, và sáu bức màn kia riêng ra; rồi gấp đôi bức màn thứ sáu về phía trước của trại.'),
(2246, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 10, 'OT', 'Và ngươi hãy làm năm mươi cái móc ở bờ của bức màn đầu tiên ở cuối cùng của bức màn ghép nối, và năm mươi cái móc ở bờ của bức màn thứ hai nối tiếp.'),
(2247, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 11, 'OT', 'Làm năm mươi cái móc bằng đồng, đưa các móc vào những vòng, rồi nối cái lều lại, để nó thành một.'),
(2248, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 12, 'OT', 'Phần thừa dài ra của các bức màn lều trại, tức là nửa bức màn thừa, sẽ phủ xuống phía sau nơi thánh.'),
(2249, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 13, 'OT', 'Và một thước phần dư nầy, một thước phần dư kia, theo chiều dài các bức màn của trại tạm, sẽ xõa xuống hai bên hông đền tạm, bên nầy và bên kia, để che phủ nó.'),
(2250, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 14, 'OT', 'Ngươi hãy làm một cái lều che bằng da chiên đực nhuộm đỏ, và một cái lều che bằng da thú mầu xanh dương để phủ lên trên.'),
(2251, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 15, 'OT', 'Hãy làm những tấm ván cho đền tạm bằng gỗ si-tim, đứng thẳng.'),
(2252, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 16, 'OT', 'Mười thước dài cho mỗi tấm ván, và một thước rưỡi rộng cho mỗi tấm ván.'),
(2253, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 17, 'OT', 'Mỗi tấm ván của mái nhà tạm đều có hai cái chốt nối liền với nhau; ngươi phải làm như vậy cho tất cả các tấm ván của mái nhà tạm.'),
(2254, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 18, 'OT', 'Ngươi hãy làm các tấm ván cho đền tạm: hai mươi tấm ván về phía nam, hướng về phương nam.'),
(2255, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 19, 'OT', 'Bốn mươi bệ đỡ bằng bạc ngươi phải làm dưới hai mươi tấm ván: hai bệ đỡ dưới một tấm ván cho hai đầu của nó, và hai bệ đỡ dưới một tấm ván cho hai đầu của nó.'),
(2256, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 20, 'OT', 'Và hai mươi tấm ván cho bên thứ nhì của đền tạm, về phía bắc.'),
(2257, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 21, 'OT', 'bốn mươi chân đế bằng bạc, hai chân đế dưới tấm ván nầy và hai chân đế dưới tấm ván kia'),
(2258, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 22, 'OT', 'Về phía sau của đền tạm, tức là về hướng tây, ngươi hãy làm sáu tấm ván.'),
(2259, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 23, 'OT', 'Hai tấm ván ngươi sẽ làm cho hai góc phía sau của đền tạm.'),
(2260, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 24, 'OT', 'Chúng sẽ khít nhau từ phía dưới, và cả hai sẽ trọn vẹn ở đầu, hướng đến một cái khoen duy nhất; cả hai góc đều phải làm như vậy.'),
(2261, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 25, 'OT', 'Và sẽ có tám tấm ván, và các bệ đỡ bằng bạc của chúng là mười sáu bệ; hai bệ dưới mỗi tấm ván này, và hai bệ dưới mỗi tấm ván kia.'),
(2262, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 26, 'OT', 'Ngươi phải làm các thanh ngang bằng gỗ acacia, năm cái cho các tấm ván bên hông của đền tạm này.'),
(2263, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 27, 'OT', 'Và năm cái thanh ngang cho các tấm ván bên hông thứ hai của đền tạm, và năm cái thanh ngang cho các tấm ván bên hông đền tạm phía sau về phía tây.'),
(2264, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 28, 'OT', 'Cây đòn giữa sẽ ở giữa các tấm ván, chạy xuyên suốt từ đầu này đến đầu kia.'),
(2265, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 29, 'OT', 'Hãy lấy vàng bao phủ các tấm ván, làm những cái vòng bằng vàng cho các cây đòn ngang, và lấy vàng bao phủ các cây đòn ngang.'),
(2266, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 30, 'OT', 'Hãy dựng đền tạm theo đúng cách thức mà ngươi đã thấy trên núi.'),
(2267, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 31, 'OT', 'Ngươi hãy làm một bức màn bằng vải gai mịn, màu xanh lam, tím sẫm và đỏ điều, được dệt bằng kỹ thuật thêu tinh xảo, có hình các chê-ru-bin.'),
(2268, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 32, 'OT', 'Ngươi hãy đặt màn đó trên bốn trụ bằng gỗ si-tim, được mạ vàng; các móc của nó bằng vàng, dựng trên bốn bệ bằng bạc.'),
(2269, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 33, 'OT', 'Ngươi sẽ đặt bức màn dưới các móc ở phía dưới mái nhà, rồi đem hòm bảng chứng vào bên trong, phía sau bức màn; và bức màn sẽ phân cách cho các ngươi giữa nơi thánh và nơi chí thánh.'),
(2270, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 34, 'OT', 'Hãy đặt cái nắp thi ân trên hòm bảng chứng, đặt trong nơi thánh của các nơi thánh.'),
(2271, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 35, 'OT', 'Đặt bàn ở bên ngoài bức màn, và đặt cây đèn vàng đối diện với bàn, ở phía nam của nhà tạm; còn bàn thì đặt ở phía bắc.'),
(2272, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 36, 'OT', 'Hãy làm một bức màn cho cửa trại bằng chỉ xanh lam, tím, đỏ điều, và vải gai mịn xoắn, thêu bằng kỹ thuật dệt.'),
(2273, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 26, 37, 'OT', 'Và ngươi hãy làm cho bức màn năm cột trụ bằng gỗ si-tim, bọc vàng cho chúng; các móc của chúng cũng bằng vàng; và ngươi hãy đúc cho chúng năm đế bằng đồng.'),
(2274, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 27, 1, 'OT', 'Hãy làm cái bàn thờ bằng gỗ si-tim, dài năm thước, rộng năm thước; cái bàn thờ phải hình vuông, và cao ba thước.'),
(2275, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 27, 2, 'OT', 'Hãy làm các sừng của nó nơi bốn góc bàn thờ; các sừng ấy phải làm cùng một khối với bàn thờ; và ngươi phải bọc nó bằng đồng.'),
(2276, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 27, 3, 'OT', 'Hãy làm những cái chảo đựng tro của nó, những cái dĩa, những cái muỗng rưới, những cái nĩa và những cái xẻng của nó; mọi đồ dùng của nó, ngươi hãy làm bằng đồng.'),
(2277, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 27, 4, 'OT', 'Làm cho nó một cái lồng bằng công trình lưới đồng, và làm trên cái lưới ấy bốn cái vòng đồng đặt tại bốn góc của nó.'),
(2278, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 27, 5, 'OT', 'Và ngươi sẽ đặt cái lưới ấy phía dưới viền bàn thờ, từ phía dưới lên, và cái lưới sẽ kéo dài đến giữa bàn thờ.'),
(2279, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 27, 6, 'OT', 'Ngươi phải làm những cây đòn cho bàn thờ, bằng gỗ si-tim, và bọc chúng bằng đồng.'),
(2280, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 27, 7, 'OT', 'Và các đòn sẽ được đưa vào các vòng, và các đòn sẽ ở hai bên bàn thờ khi khiêng nó.'),
(2281, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 27, 8, 'OT', 'Hãy làm cái bàn thờ bằng những tấm ván rỗng, y như điều đã cho ngươi xem thấy trên núi, họ phải làm như vậy.'),
(2282, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 27, 9, 'OT', 'Ngươi hãy làm hành lang của đền tạm; về phía nam, về hướng nam, làm các bức màn cho hành lang bằng vải gai mịn, dài một trăm thước, cho một phía đó.'),
(2283, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 27, 10, 'OT', 'và các trụ của nó là hai mươi, các đế của chúng là hai mươi bằng đồng; móc các trụ và thanh ngang của chúng thì bằng bạc.'),
(2284, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 27, 11, 'OT', 'Tương tự về phía bắc, chiều dài là một trăm đơn vị; các bức màn, hai mươi trụ, và hai mươi bệ bằng đồng; các móc của trụ và các thanh ngang nối chúng với nhau bằng bạc.'),
(2285, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 27, 12, 'OT', 'Bề rộng của hành lang về phía tây là năm mươi thước, mười cây trụ và mười đế trụ.'),
(2286, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 27, 13, 'OT', 'Chiều ngang của hành lang về phía đông là năm mươi thước.'),
(2287, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 27, 14, 'OT', 'Mười lăm thước vải màn cho phía bên phải, ba cái cột và ba bệ đỡ của nó;'),
(2288, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 27, 15, 'OT', 'Phía bên kia có mười lăm tấm màn, các trụ của nó là ba cái, và bệ đỡ của nó là ba cái.'),
(2289, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 27, 16, 'OT', 'Cửa hành lang thì có bức màn dài hai mươi thước bằng chỉ xanh lam, tím, đỏ điều và vải gai mịn xoắn, thêu hình; các trụ của nó là bốn cái, và các đế của nó là bốn cái.'),
(2290, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 27, 17, 'OT', 'Tất cả các trụ xung quanh hành lang đều mạ bạc, móc của chúng bằng bạc, và bệ đỡ của chúng bằng đồng.'),
(2291, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 27, 18, 'OT', 'Chiều dài hành lang là một trăm thước, chiều ngang mỗi bên năm mươi thước, chiều cao năm thước, bằng vải gai mịn; các chân trụ của nó bằng đồng.'),
(2292, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 27, 19, 'OT', 'Hết thảy các khí cụ dùng cho mọi công việc của đền tạm, cùng mọi cây chốt của đền tạm và mọi cây chốt của hành lang, đều làm bằng đồng.'),
(2293, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 27, 20, 'OT', 'Ngươi hãy truyền cho con cái Y-sơ-ra-ên đem đến cho ngươi dầu ô-liu nguyên chất, ép ra, để thắp đèn luôn luôn.'),
(2294, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 27, 21, 'OT', 'Trong hội mạc, ở ngoài bức màn trước hòm chứng cớ, A-rôn và các con trai người phải sửa đèn ấy trước mặt Đức Giê-hô-va từ chiều tối cho đến sáng, làm luật định đời đời cho các thế hệ của Y-sơ-ra-ên.'),
(2295, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 1, 'OT', 'Ngươi hãy đưa đến gần ngươi A-rôn, anh ngươi, cùng các con trai người là Na-đáp, A-bi-hu, Ê-lê-a-sa và Y-tha-ma, từ giữa các con trai Y-sơ-ra-ên, để A-rôn phục vụ chức tế lễ cho Đức Giê-hô-va.'),
(2296, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 2, 'OT', 'Hãy làm những bộ áo thánh cho A-rôn, anh ngươi, để tôn vinh và làm vẻ vang.'),
(2297, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 3, 'OT', 'Ngươi hãy nói với mọi người khôn ngoan, là những người Ta đã đầy lấy thần trí khôn, để làm các y phục của A-rôn, khiến người được biệt riêng ra thánh mà tế tự Ta.'),
(2298, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 4, 'OT', 'Đây là những áo mà họ phải làm: bảng đeo ngực, ê-phót, áo choàng, áo trong thêu, mũ và đai lưng. Họ phải làm những áo thánh cho A-rôn, anh ngươi, và các con trai ngươi, để các người ấy làm chức tế lễ cho ta.'),
(2299, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 5, 'OT', 'Họ sẽ lấy vàng, cùng với chỉ màu xanh lam, màu tím sẫm, màu sợi đỏ điều, và vải gai mịn.'),
(2300, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 6, 'OT', 'Họ sẽ làm cái ê-phót bằng vàng, chỉ xanh lam, tím sẫm, đỏ điều và sợi gai mịn, thêu bằng kỹ nghệ khéo léo.'),
(2301, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 7, 'OT', 'Hai cái quai nối sẽ ở hai đầu của nó, và sẽ được nối liền.'),
(2302, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 8, 'OT', 'Dây đai thắt của nó, là phần trên nó, phải làm cùng một miếng với nó, y như cách làm của nó: bằng vàng, chỉ xanh, tím, đỏ sậm và vải gai mịn.'),
(2303, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 9, 'OT', 'Hãy lấy hai hòn đá mã não và chạm khắc trên đó các tên của con trai Y-sơ-ra-ên.'),
(2304, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 10, 'OT', 'sáu tên của họ trên hòn đá thứ nhất, và sáu tên còn lại trên hòn đá thứ hai, theo thứ tự sinh của họ.'),
(2305, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 11, 'OT', 'Hãy làm hai viên đá bằng kỹ nghệ thợ chạm nổi, theo cách đóng ấn, khắc trên hai viên đá đó các tên con trai Y-sơ-ra-ên; ngươi phải làm các khung bằng vàng khảm hai viên đá.'),
(2306, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 12, 'OT', 'Và ngươi sẽ đặt hai hòn đá đó trên hai cái quai của cái ê-phót, làm hai hòn đá kỷ niệm cho con cháu Y-sơ-ra-ên; A-rôn sẽ mang các tên của họ trước mặt Đức Giê-hô-va trên hai vai mình, làm kỷ niệm.'),
(2307, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 13, 'OT', 'Ngươi hãy làm các cái móc bằng vàng.'),
(2308, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 14, 'OT', 'Làm hai dây chuyền bằng vàng ròng, theo kiểu xích, công việc bằng cách bện; rồi đặt hai dây chuyền bằng cách bện ấy vào hai cái móc.'),
(2309, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 15, 'OT', 'Ngươi phải làm bảng đeo ngực xét đoán, do thợ khéo tay thực hiện, như cách làm áo ê-phót: bằng vàng, chỉ xanh, tím, đỏ điều, và vải gai mịn xoắn lại.'),
(2310, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 16, 'OT', 'Bảng ngực phải làm hình vuông và gấp đôi; dài một thước và rộng một thước.'),
(2311, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 17, 'OT', 'Ngươi hãy gắn vào đó bốn hàng đá quý: hàng thứ nhất là ngọc hồng, ngọc xanh lam và ngọc xanh lục.'),
(2312, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 18, 'OT', 'và hàng thứ hai là ngọc nốp-ách, ngọc sa-phia và ngọc ya-ha-lôm.'),
(2313, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 19, 'OT', 'Hàng thứ ba là ngọc hồng bửu, ngọc bạch mã não và ngọc tử tinh.'),
(2314, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 20, 'OT', 'Hàng thứ tư là ngọc thah-rê-sish, ngọc shô-ham và ngọc ya-shê-fê; chúng sẽ được khảm vào các khuôn bằng vàng.'),
(2315, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 21, 'OT', 'Mười hai viên ngọc đó sẽ mang tên mười hai con trai Y-sơ-ra-ên, mỗi viên khắc theo tên của từng người, như những con dấu ấn; các ngọc đó sẽ theo số mười hai chi phái.'),
(2316, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 22, 'OT', 'Ngươi hãy làm các dây cái bằng vàng ròng, kiểu cách như dây bện, gắn vào bảng đeo ngực.'),
(2317, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 23, 'OT', 'Ngươi hãy làm hai cái vòng bằng vàng và đặt hai cái vòng ấy vào hai đầu của bảng quyết định.'),
(2318, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 24, 'OT', 'Hãy đặt hai dây xích vàng vào hai cái vòng ở hai đầu bảng.'),
(2319, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 25, 'OT', 'Hãy đem hai đầu của hai dây đeo nầy đặt trên hai cái móc, rồi buộc vào hai cái quai của y-ê-phót ở phía trước ngực.'),
(2320, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 26, 'OT', 'Ngươi phải làm hai vòng vàng, rồi đặt chúng vào hai đầu của bảng đeo ngực, ở mép của nó hướng về phía trong của ê-phót.'),
(2321, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 27, 'OT', 'Làm hai cái vòng bằng vàng, rồi đặt chúng trên hai cái nắp vai của ê-phót, ở phía dưới, đối diện với mặt trước, đối xứng với chỗ nối của nó, phía trên dây đai của ê-phót.'),
(2322, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 28, 'OT', 'Và ngươi phải dùng chỉ tím buộc cái bảng đeo ngực vào các vòng của áo thầy tế lễ, để nó gắn liền với cái đai, hầu cho cái bảng đeo ngực không rời khỏi áo thầy tế lễ.'),
(2323, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 29, 'OT', 'A-rôn sẽ mang tên các con trai Y-sơ-ra-ên trên bảng xét đoán đặt trên lòng mình, khi người vào nơi thánh, để ghi nhớ trước mặt Đức Giê-hô-va luôn mãi.'),
(2324, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 30, 'OT', 'Và ngươi hãy đặt vào bảng đeo ngực xét đoán các vật U-rim và Thu-mim; chúng sẽ ở trên lòng A-rôn khi người vào trước mặt Đức Giê-hô-va. A-rôn sẽ mang sự xét đoán của con cái Y-sơ-ra-ên trên lòng mình trước mặt Đức Giê-hô-va luôn mãi.'),
(2325, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 31, 'OT', 'Ngươi phải làm áo choàng của ê-phót toàn bằng vải màu xanh sậm.'),
(2326, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 32, 'OT', 'Vòng cổ áo phải ở giữa, viền chung quanh cổ áo, làm theo kiểu dệt, như lỗ áo giáp bằng lưới, để khỏi rách.'),
(2327, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 33, 'OT', 'Ở biên dưới của áo, hãy làm những trái lựu bằng chỉ màu xanh ngọc, tím sẫm và đỏ điều quanh viền áo, và những chiếc chuông bằng vàng ở giữa chúng quanh viền theo vòng.'),
(2328, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 34, 'OT', 'chuông vàng và trái lựu, chuông vàng và trái lựu, vòng quanh viền áo choàng.'),
(2329, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 35, 'OT', 'A-rôn sẽ mặc áo nầy khi thi hành chức tế lễ; tiếng chuông sẽ vang lên khi người vào hoặc ra khỏi nơi thánh trước mặt Đức Giê-hô-va, để người không chết.'),
(2330, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 36, 'OT', 'Ngươi phải làm một cái băng bằng vàng ròng, và chạm trên nó như cách đóng ấn, lời ghi: Thánh dành riêng cho Đức Giê-hô-va.'),
(2331, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 37, 'OT', 'Và ngươi sẽ đặt nó trên một sợi dây màu xanh sẫm, và nó sẽ ở trên mũ, ngay trước mặt mũ.'),
(2332, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 38, 'OT', 'A-rôn sẽ mang tấm thẻ trên trán; A-rôn sẽ mang tội lỗi của các vật thánh mà con cái Y-sơ-ra-ên biệt riêng ra, tức mọi của lễ thánh họ dâng; tấm thẻ sẽ ở trên trán người luôn luôn, để họ được đẹp lòng Đức Giê-hô-va.'),
(2333, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 39, 'OT', 'Ngươi hãy dệt cái áo trong bằng vải gai mịn, làm cái mũ bằng vải gai mịn, và làm cái đai theo kiểu thêu.'),
(2334, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 40, 'OT', 'Hãy làm những chiếc áo dài cho các con trai A-rôn, và làm đai cho họ, cùng làm mũ cho họ, để được tôn trọng và vinh hiển.'),
(2335, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 41, 'OT', 'Hãy mặc các bộ áo đó cho A-rôn, anh ngươi, và cho các con trai người cùng với người; hãy xức dầu cho họ, bổ nhiệm họ và biệt riêng họ ra thánh để họ làm chức tế lễ cho ta.'),
(2336, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 42, 'OT', 'Hãy làm cho họ quần vải gai để che phần thân thể trần trụi, từ ngang hông cho đến đùi.'),
(2337, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 28, 43, 'OT', 'A-rôn và các con trai người sẽ mặc những thứ đó khi vào Hội mạc hoặc khi đến gần bàn thờ để thi hành chức vụ trong nơi thánh, hầu khỏi mang tội mà chết. Đó là một mạng lệnh đời đời cho A-rôn và dòng dõi người sau người.'),
(2338, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 1, 'OT', 'Đây là điều ngươi phải làm để biệt riêng A-rôn và các con trai người ra thánh, khiến họ làm thầy tế lễ cho ta: hãy lấy một con bò đực đực con, và hai chiên đực không tật.'),
(2339, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 2, 'OT', 'bánh không men, và bánh nhỏ không men trộn với dầu, và bánh tráng không men phết dầu; lấy bột mì làm các thứ đó'),
(2340, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 3, 'OT', 'Ngươi sẽ đặt chúng vào một cái giỏ, dâng chúng lên trong cái giỏ ấy, cùng với con bò đực và hai con chiên đực.'),
(2341, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 4, 'OT', 'Ngươi sẽ dẫn A-rôn và các con trai người đến gần cửa Đền tạm, rồi lấy nước tắm cho họ.'),
(2342, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 5, 'OT', 'Lấy các áo và mặc cho A-rôn áo trong, áo choàng của ê-phót, ê-phót và bảng ngực; rồi lấy dây của ê-phót thắt cho người.'),
(2343, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 6, 'OT', 'đặt mũ lễ trên đầu người ấy, và đặt tấm bảng thánh trên mũ lễ.'),
(2344, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 7, 'OT', 'Hãy lấy dầu xức đổ trên đầu người ấy và xức cho người ấy.'),
(2345, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 8, 'OT', 'Hãy dẫn các con trai của A-rôn mà đến gần, và mặc áo dài cho chúng.'),
(2346, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 9, 'OT', 'Hãy lấy đai thắt cho A-rôn và các con trai người, và đội mũ cho họ; thì chức tế lễ sẽ là của họ theo luật định đời đời. Ngươi sẽ phong chức cho A-rôn và cho các con trai người.'),
(2347, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 10, 'OT', 'Hãy dẫn con bò đực đến trước hội mạc; A-rôn và các con trai người sẽ đặt tay mình trên đầu con bò đực.'),
(2348, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 11, 'OT', 'Ngươi hãy giết con bò đực trước mặt Đức Giê-hô-va, tại nơi cửa nhà tạm.'),
(2349, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 12, 'OT', 'Ngươi hãy lấy huyết con bò, đặt huyết trên các sừng của bàn thờ bằng ngón tay ngươi, và đổ toàn bộ huyết xuống nền bàn thờ.'),
(2350, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 13, 'OT', 'Hãy lấy hết thảy mỡ che phủ nội tạng, và phần dư trên gan, cùng hai quả thận và mỡ trên hai quả thận, mà đốt trên bàn thờ.'),
(2351, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 14, 'OT', 'Thịt con bò đực, cùng với da và phân nó, ngươi phải thiêu bằng lửa bên ngoài trại quân; ấy là lễ chuộc tội.'),
(2352, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 15, 'OT', 'Hãy lấy con chiên đực kia, rồi A-rôn và các con trai người sẽ đặt tay mình trên đầu con chiên đực ấy.'),
(2353, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 16, 'OT', 'Hãy giết con chiên đực, lấy huyết nó mà rưới quanh bàn thờ.'),
(2354, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 17, 'OT', 'Hãy xẻ con chiên ra từng phần, rửa sạch lòng ruột và các chân nó, rồi đặt lên các phần thịt và đầu nó.'),
(2355, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 18, 'OT', 'Hãy nhóm lên toàn bộ con chiên đực trên bàn thờ; ấy là của lễ thiêu dâng cho Đức Giê-hô-va, một mùi thơm, một của lễ dùng lửa dâng cho Đức Giê-hô-va.'),
(2356, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 19, 'OT', 'Ngươi hãy lấy con chiên đực thứ hai, rồi A-rôn và các con trai người sẽ đặt tay mình trên đầu con chiên đực ấy.'),
(2357, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 20, 'OT', 'Hãy giết chiên đực, lấy máu nó bôi vào vành tai bên phải của A-rôn và vành tai bên phải các con trai người, và lên ngón tay cái bên phải của họ và ngón chân cái bên phải của họ; rồi rảy máu còn lại quanh bàn thờ.'),
(2358, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 21, 'OT', 'Hãy lấy huyết ở trên bàn thờ và dầu xức, rồi rảy trên A-rôn và quần áo người, trên các con trai người và quần áo các con trai người cùng người; như vậy, A-rôn và quần áo người, các con trai người và quần áo các con trai người cùng người sẽ được biệt riêng ra thánh.'),
(2359, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 22, 'OT', 'Ngươi hãy lấy mỡ con chiên, cái đuôi, mỡ che phủ lòng, phần mỡ che phủ gan, hai quả thận và mỡ trên hai quả thận, cùng cái chân phải, vì đây là con chiên dùng làm lễ đầy tay.'),
(2360, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 23, 'OT', 'lại lấy một ổ bánh, một bánh mì dầu và một bánh mỏng từ giỏ bánh không men, là những vật đặt trước mặt Đức Giê-hô-va;'),
(2361, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 24, 'OT', 'Ngươi phải đặt mọi thứ đó trên các lòng bàn tay của A-rôn và trên các lòng bàn tay của các con trai người, rồi ngươi phải đưa chúng qua đưa lại làm lễ vật dâng trước mặt Đức Giê-hô-va.'),
(2362, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 25, 'OT', 'Vậy ngươi hãy lấy những vật ấy khỏi tay họ, rồi dâng lên bàn thờ, ở trên của lễ thiêu, làm mùi thơm đẹp lòng Đức Giê-hô-va; ấy là của lễ thiêu đốt dâng cho Đức Giê-hô-va.'),
(2363, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 26, 'OT', 'Hãy lấy cái ngực của con chiên đực về lễ phong chức cho A-rôn, rồi đưa nó qua đưa lại làm lễ vật dâng trước mặt Đức Giê-hô-va; và cái ngực ấy sẽ thuộc về ngươi.'),
(2364, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 27, 'OT', 'Hãy biệt riêng ra thánh phần ngực của lễ giơ qua đưa lại và phần giò của lễ dâng lên, tức là phần ngực và phần giò đã được giơ lên và dâng lên từ con chiên đực lễ phong chức, thuộc về A-rôn và về các con trai người.'),
(2365, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 28, 'OT', 'Và lễ vật ấy sẽ thuộc về A-rôn và các con trai người làm luật lệ đời đời từ nơi con cái Y-sơ-ra-ên, vì là lễ dâng lên; ấy sẽ là lễ dâng lên từ nơi con cái Y-sơ-ra-ên, lễ vật họ dâng lên cho Đức Giê-hô-va từ các của lễ thù ân của họ.'),
(2366, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 29, 'OT', 'Những áo thánh của A-rôn sẽ thuộc về các con trai người sau người, để xức dầu và đầy tay họ trong những áo đó.'),
(2367, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 30, 'OT', 'Trong bảy ngày, thầy tế lễ nào là con trai người và sẽ vào Lều Hẹn để phụng sự tại nơi thánh, thì sẽ mặc những áo đó thay cho người.'),
(2368, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 31, 'OT', 'Ngươi hãy lấy con chiên đực dùng làm lễ khai mạc, và nấu thịt nó tại một nơi thánh.'),
(2369, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 32, 'OT', 'A-rôn và các con trai người sẽ ăn thịt con chiên đực và bánh trong giỏ tại cửa Nhà hội mạc.'),
(2370, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 33, 'OT', 'Họ phải ăn những thứ mà nhờ đó họ được chuộc tội, để được đầy tay và biệt riêng ra thánh; nhưng người ngoại không được ăn, vì chúng là thánh.'),
(2371, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 34, 'OT', 'Nếu thịt lễ lễ phong chức và bánh còn sót lại cho đến sáng hôm sau, ngươi phải thiêu những gì còn sót lại trong lửa; không được ăn, vì đó là vật thánh.'),
(2372, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 35, 'OT', 'Ngươi hãy làm cho A-rôn và các con trai người như vậy, theo mọi điều ta đã truyền cho ngươi: trong bảy ngày, ngươi sẽ bổ nhiệm tay họ.'),
(2373, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 36, 'OT', 'Mỗi ngày ngươi phải dâng một con bò đực làm của lễ chuộc tội; ngươi phải làm lễ chuộc tội cho bàn thờ khi chuộc tội cho nó, và ngươi phải xức dầu cho nó để biệt nó ra thánh.'),
(2374, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 37, 'OT', 'Trong bảy ngày, ngươi phải làm lễ chuộc tội cho bàn thờ và biệt nó ra thánh; bàn thờ sẽ trở nên thánh, tức là nơi cực thánh; hễ ai đụng đến bàn thờ sẽ được biệt ra thánh.'),
(2375, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 38, 'OT', 'Và điều nầy là điều ngươi sẽ làm trên bàn thờ: hai chiên con một tuổi, hằng ngày luôn như thế.'),
(2376, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 39, 'OT', 'Chiên con thứ nhất, ngươi sẽ dâng vào buổi sáng; chiên con thứ hai, ngươi sẽ dâng giữa chiều tối.'),
(2377, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 40, 'OT', 'Còn một phần mười bột mịn trộn với dầu ô-liu, tức một phần tư hin, và lễ quán là một phần tư hin rượu, thì dâng cho mỗi con chiên.'),
(2378, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 41, 'OT', 'Còn chiên thứ hai, ngươi hãy dâng vào buổi chiều tối; ngươi hãy dâng của lễ và lễ quán cho nó như của lễ buổi sáng, làm của lễ thiêu, có mùi thơm đẹp lòng Đức Giê-hô-va.'),
(2379, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 42, 'OT', 'Lễ thiêu luôn luôn, trải qua các đời các ngươi, tại cửa nhà hội mạc trước mặt Đức Giê-hô-va, là nơi Ta sẽ hẹn gặp các ngươi để phán cùng các ngươi tại đó.'),
(2380, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 43, 'OT', 'Và Ta sẽ hẹn gặp tại đó cùng con cái Y-sơ-ra-ên; và Ta sẽ được biệt riêng ra thánh bởi sự vinh hiển của Ta.'),
(2381, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 44, 'OT', 'Ta sẽ biệt riêng đền tạm và bàn thờ ra thánh, và biệt riêng A-rôn và các con trai người ra thánh, để họ làm thầy tế lễ cho ta.'),
(2382, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 45, 'OT', 'Ta sẽ ngự giữa con cái Y-sơ-ra-ên, và Ta sẽ là Đức Chúa Trời của chúng nó.'),
(2383, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 29, 46, 'OT', 'Dân ấy sẽ biết rằng chính Ta là Đức Giê-hô-va Đức Chúa Trời của họ, Đấng đã đem họ ra khỏi đất Ai Cập để ở giữa họ. Ta là Đức Giê-hô-va Đức Chúa Trời của họ.'),
(2384, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 1, 'OT', 'Ngươi phải làm một bàn thờ để đốt hương, bằng gỗ cây si-tim, ngươi phải làm cái bàn thờ ấy.'),
(2385, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 2, 'OT', 'Mặt bàn sẽ dài một thước, rộng một thước, vuông vức; chiều cao của nó sẽ là hai thước; từ chính nó mà phát ra các sừng của nó.'),
(2386, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 3, 'OT', 'Ngươi phải bao phủ nó bằng vàng tinh khiết, cả mặt trên và các vách chung quanh cùng các sừng của nó; ngươi phải làm cho nó một vòng viền vàng chung quanh.'),
(2387, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 4, 'OT', 'Dưới vòng viền của nó, ngươi hãy làm hai cái khoen bằng vàng ở hai bên cạnh của nó; ngươi hãy làm chúng nơi hai cạnh của nó, và chúng sẽ dùng làm nơi đặt đòn khiêng để khiêng nó.'),
(2388, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 5, 'OT', 'Hãy làm các đòn khiêng bằng gỗ si-tim, và bọc chúng bằng vàng.'),
(2389, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 6, 'OT', 'Ngươi sẽ đặt bàn thờ ấy trước bức màn che hòm bảng chứng, trên hòm có nắp thi ân, là nơi ta sẽ tỏ mình cho ngươi.'),
(2390, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 7, 'OT', 'Mỗi buổi sáng, khi A-rôn sửa soạn các ngọn đèn, người sẽ dâng hương thơm lên trên đó.'),
(2391, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 8, 'OT', 'Và khi A-rôn thắp các ngọn đèn vào buổi chiều tối, người sẽ xông hương đó lên; một thứ hương đốt hằng ngày trước mặt Đức Giê-hô-va, trải qua các thế hệ của các ngươi.'),
(2392, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 9, 'OT', 'Đừng dâng trên bàn thờ nầy hương lạ, lễ thiêu, lễ chay, hay lễ quán nào.'),
(2393, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 10, 'OT', 'Mỗi năm một lần, A-rôn phải làm lễ chuộc tội cho các sừng bàn thờ bằng huyết của sinh tế chuộc tội; mỗi năm một lần, người phải làm lễ chuộc tội cho bàn thờ để chuộc tội cho các ngươi qua các thế hệ. Đây là nơi cực thánh dành cho Đức Giê-hô-va.'),
(2394, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 11, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(2395, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 12, 'OT', 'Khi ngươi điểm danh con cái Y-sơ-ra-ên theo số người được kê khai, mỗi người phải nộp tiền đền chuộc mạng mình cho Đức Giê-hô-va; như vậy, trong khi điểm danh họ, họ sẽ không bị tai họa.'),
(2396, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 13, 'OT', 'Mọi người qua danh sách điểm danh phải nộp nửa siếc-lơ, theo siếc-lơ của nơi thánh, siếc-lơ nặng hai mươi ghê-ra; nửa siếc-lơ ấy là của lễ dâng cho Đức Giê-hô-va.'),
(2397, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 14, 'OT', 'Mọi người qua sự điểm danh, từ hai mươi tuổi trở lên, sẽ dâng lễ vật cho Đức Giê-hô-va.'),
(2398, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 15, 'OT', 'Người giàu không được nộp quá, và người nghèo không được nộp thiếu nửa siếc-lơ, để dâng của lễ dâng cho Đức Giê-hô-va, hầu làm lễ chuộc mạng cho mình.'),
(2399, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 16, 'OT', 'Ngươi sẽ nhận lấy tiền chuộc từ con cái Y-sơ-ra-ên và dùng tiền đó cho công việc của hội mạc; nó sẽ là một kỷ niệm cho con cái Y-sơ-ra-ên trước mặt Đức Giê-hô-va, để chuộc mạng sống các ngươi.'),
(2400, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 17, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(2401, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 18, 'OT', 'Hãy làm một cái chậu bằng đồng và một chân đế bằng đồng để rửa; ngươi phải đặt nó giữa hội mạc và bàn thờ, rồi đổ nước vào đó.'),
(2402, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 19, 'OT', 'A-rôn và các con trai người sẽ rửa tay và chân mình ở trong đó.'),
(2403, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 20, 'OT', 'Khi họ vào hội mạc, phải lấy nước mà rửa; nếu không, họ sẽ chết. Cũng vậy, khi họ đến gần bàn thờ để phục vụ, để dâng của lễ thiêu cho Đức Giê-hô-va, họ phải rửa như vậy.'),
(2404, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 21, 'OT', 'Họ phải rửa tay và chân mình, hầu cho khỏi chết; ấy sẽ là một luật lệ đời đời cho A-rôn và dòng dõi người trải qua các thế hệ.'),
(2405, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 22, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(2406, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 23, 'OT', 'Hãy lấy cho ngươi những thứ hương tốt nhất: năm trăm siếc-lơ mộc dược nguyên chất, một nửa số đó là hai trăm năm mươi siếc-lơ quế thơm, hai trăm năm mươi siếc-lơ sậy thơm,'),
(2407, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 24, 'OT', 'quế đỏ năm trăm theo siếc-lơ nơi thánh, và một hin dầu ô-liu.'),
(2408, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 25, 'OT', 'Ngươi hãy chế dầu ấy thành dầu xức thánh, một thứ thuốc thơm theo cách chế của người hòa hương, dầu xức thánh sẽ là thứ dầu thánh.'),
(2409, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 26, 'OT', 'Ngươi phải xức dầu cho hội mạc và hòm bảng chứng bằng thứ dầu đó.'),
(2410, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 27, 'OT', 'cái bàn và mọi đồ dùng của nó, chân đèn và mọi đồ dùng của nó, bàn thờ hương,'),
(2411, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 28, 'OT', 'và bàn thờ của lễ thiêu cùng mọi đồ dùng của nó, và cái thùng rửa cùng chân đỡ của nó.'),
(2412, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 29, 'OT', 'Ngươi sẽ biệt riêng các vật ấy ra thánh, và chúng sẽ là nơi thánh, mọi vật nào đụng đến nó đều được biệt riêng ra thánh.'),
(2413, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 30, 'OT', 'Ngươi phải xức dầu cho A-rôn và các con trai người, và biệt riêng họ ra thánh để làm chức tế lễ cho ta.'),
(2414, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 31, 'OT', 'Hãy nói cùng các con cái Y-sơ-ra-ên rằng: Dầu xức thánh nầy sẽ thuộc về ta trải qua các đời các ngươi.'),
(2415, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 32, 'OT', 'Chớ đổ trên thân thể người nào, và chớ pha chế dầu nào khác theo công thức ấy; dầu ấy là thánh, phải thánh cho các ngươi.'),
(2416, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 33, 'OT', 'Người nào pha chế thứ hương thơm giống như vậy, hay ai đem trao cho một người ngoại, thì sẽ bị truất khỏi vòng dân sự mình.'),
(2417, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 34, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Hãy lấy cho ngươi các thứ hương: nhựa thơm, nhựa mộc dược, nhựa thơm hảo hạng, và nhũ hương tinh khiết; mỗi thứ phải bằng nhau,'),
(2418, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 35, 'OT', 'Ngươi hãy làm thứ hương này theo cách thức của người pha chế, một thứ hương được phối chế công phu, mặn, tinh khiết và thánh.'),
(2419, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 36, 'OT', 'Hãy nghiền nhỏ một phần của nó, rồi đặt một phần của nó trước hòm chứng trong hội mạc, là nơi Ta sẽ gặp ngươi; về phần các ngươi, nó sẽ là vật chí thánh.'),
(2420, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 37, 'OT', 'Chớ làm thứ hương mà ngươi sẽ chế theo công thức của nó cho các ngươi; nó phải là vật thánh dành riêng cho Đức Giê-hô-va.'),
(2421, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 30, 38, 'OT', 'Người nào làm giống như vậy để ngửi mùi thơm, sẽ bị truất khỏi dân sự mình.'),
(2422, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 31, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(2423, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 31, 2, 'OT', 'Nầy, ta đã gọi Bết-sa-lê-ên, con trai của U-ri, cháu của Hu-rơ, thuộc chi phái Giu-đa, bằng danh của người.'),
(2424, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 31, 3, 'OT', 'Ta đã đầy dẫy người bởi Thần của Đức Chúa Trời, với sự khôn ngoan, sự thông sáng, sự hiểu biết, và trong mọi công việc thủ nghệ.'),
(2425, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 31, 4, 'OT', 'để suy nghĩ ra các ý tưởng, đặng làm các vật bằng vàng, bạc và đồng,'),
(2426, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 31, 5, 'OT', 'và khảm đá, đẽo gỗ, làm mọi công việc thợ thủ công.'),
(2427, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 31, 6, 'OT', 'Và này, Ta đã đặt cùng người ấy Ô-hô-li-áp, con trai của A-hi-sa-mạc, thuộc chi phái Đan; và Ta đã ban sự khôn ngoan cho lòng mọi người có tài năng, để họ làm mọi điều Ta đã truyền cho ngươi.'),
(2428, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 31, 7, 'OT', 'Rồi đến trại tạm, hòm bảng chứng, cái nắp che trên hòm, và mọi đồ dùng trong trại tạm;'),
(2429, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 31, 8, 'OT', 'và cái bàn cùng các đồ của nó, và chân đèn tinh khiết cùng mọi đồ của nó, và bàn thờ xông hương,'),
(2430, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 31, 9, 'OT', 'và bàn thờ thiêu cùng mọi đồ dùng của nó, và cái bồn nước cùng giá đỡ của nó;'),
(2431, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 31, 10, 'OT', 'và các áo lễ, cùng các áo thánh cho A-rôn thầy tế lễ và các áo cho các con trai người để làm chức tế lễ;'),
(2432, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 31, 11, 'OT', 'và dầu xức, và hương thơm dùng trong nơi thánh; họ phải làm mọi điều theo đúng điều Ta đã truyền dạy ngươi.'),
(2433, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 31, 12, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(2434, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 31, 13, 'OT', 'Phần ngươi, hãy nói cùng con cái Y-sơ-ra-ên rằng: Các ngươi phải giữ các ngày sa-bát của ta, vì ấy là dấu giữa ta và các ngươi, trải qua các đời, để biết rằng chính ta, Đức Giê-hô-va, là Đấng làm các ngươi nên thánh.'),
(2435, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 31, 14, 'OT', 'Vậy, hãy giữ ngày Sa-bát, vì là ngày thánh cho các ngươi; ai phạm đến ngày ấy sẽ bị xử tử. Bởi hễ ai làm công việc gì trong ngày ấy, thì linh hồn ấy sẽ bị truất khỏi vòng dân sự mình.'),
(2436, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 31, 15, 'OT', 'Sáu ngày phải làm công việc, nhưng ngày thứ bảy là ngày Sa-bát, tức là ngày nghỉ, biệt riêng ra thánh cho Đức Giê-hô-va. Hễ ai làm công việc trong ngày Sa-bát sẽ bị xử tử.'),
(2437, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 31, 16, 'OT', 'Vậy nên, con cái Y-sơ-ra-ên phải giữ ngày Sa-bát, để giữ ngày Sa-bát cho các đời của họ như một giao ước đời đời.'),
(2438, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 31, 17, 'OT', 'Dấu đó là dấu đời đời giữa ta và con cái Y-sơ-ra-ên, vì Đức Giê-hô-va đã làm trời đất trong sáu ngày, và ngày thứ bảy thì nghỉ và lấy lại sức.'),
(2439, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 31, 18, 'OT', 'Khi Đức Giê-hô-va làm xong việc phán cùng Môi-se tại núi Si-na-i, thì Ngài trao cho Môi-se hai bảng chứng, là hai bảng đá, được viết bằng ngón tay Đức Chúa Trời.'),
(2440, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 1, 'OT', 'Dân sự thấy Môi-se chậm trễ xuống núi, bèn nhóm lại cùng A-rôn và nói với người rằng: "Hãy đứng lên, làm cho chúng tôi các thần để đi trước chúng tôi, vì về phần Môi-se, là người đã dẫn chúng tôi lên khỏi đất Ê-díp-tô, chúng tôi không biết điều gì đã xảy đến cho người."'),
(2441, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 2, 'OT', 'A-rôn nói với họ: "Hãy tháo những vòng vàng nơi tai vợ, con trai và con gái các ngươi ra, rồi mang đến cho ta."'),
(2442, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 3, 'OT', 'Hết thảy dân chúng đều lột những vòng vàng nơi tai mình và đem đến cho A-rôn.'),
(2443, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 4, 'OT', 'Người nhận lấy nơi tay họ, rồi lấy khuôn đúc mà đúc thành một con bò con, và dân chúng nói rằng: "Nầy là các thần của ngươi, hỡi Y-sơ-ra-ên, đã đem ngươi lên khỏi đất Ê-díp-tô."'),
(2444, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 5, 'OT', 'A-rôn thấy điều đó, bèn xây một bàn thờ trước mặt nó; rồi A-rôn kêu lên rằng: Ngày mai sẽ là lễ kính Đức Giê-hô-va!'),
(2445, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 6, 'OT', 'Sáng hôm sau, họ dậy sớm, dâng những của lễ thiêu và dâng những của lễ thù ân; dân chúng ngồi ăn uống, rồi chỗi dậy vui chơi.'),
(2446, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 7, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Hãy xuống đi, vì dân sự ngươi, mà chính ngươi đã dẫn ra khỏi đất Ê-díp-tô, đã bại hoại rồi.'),
(2447, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 8, 'OT', 'Chúng đã vội vàng rời khỏi con đường mà Ta đã truyền cho chúng, đúc một con bò tơ và thờ lạy nó, dâng của lễ cho nó, rồi nói rằng: "Nầy là các thần của ngươi, hỡi Y-sơ-ra-ên, đã đưa ngươi lên khỏi đất Ê-díp-tô!"'),
(2448, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 9, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Ta đã thấy dân này, kìa họ là một dân cứng cổ.'),
(2449, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 10, 'OT', 'Bây giờ hãy để mặc ta, để cơn thịnh nộ ta nổi lên nghịch cùng chúng nó và ta sẽ tiêu diệt chúng đi; rồi ta sẽ làm cho ngươi thành một dân lớn.'),
(2450, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 11, 'OT', 'Môi-se nài xin mặt Đức Giê-hô-va Đức Chúa Trời của mình, mà nói rằng: Lạy Đức Giê-hô-va, sao Ngài nổi giận cùng dân Ngài, là dân mà Ngài đã đem ra khỏi đất Ê-díp-tô bằng quyền năng lớn và tay mạnh?'),
(2451, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 12, 'OT', 'Đừng để người Ai Cập nói rằng: "Ngài đem họ ra khỏi để làm hại họ, giết họ trên núi và tiêu diệt họ khỏi mặt đất." Xin hãy nguôi cơn thịnh nộ của Ngài và đổi ý về điều tai họa sắp giáng trên dân Ngài.'),
(2452, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 13, 'OT', 'Xin hãy nhớ lại Aùp-ra-ham, Y-sác và Y-sơ-ra-ên, là các tôi tớ Ngài, mà Ngài đã chỉ chính mình mà thề cùng họ rằng: Ta sẽ làm cho dòng dõi các ngươi đông vô số như các ngôi sao trên trời, và Ta sẽ ban cho dòng dõi các ngươi toàn cõi đất nầy, mà Ta đã phán hứa, để họ được hưởng làm cơ nghiệp đời đời.'),
(2453, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 14, 'OT', 'Đức Giê-hô-va hối tiếc về điều rủi ro mà Ngài đã nói sẽ làm cho dân Ngài.'),
(2454, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 15, 'OT', 'Môi-se quay lại, đi xuống từ trên núi, tay cầm hai bảng chứng; hai bảng chứng có chữ viết cả hai mặt, mặt nầy và mặt kia.'),
(2455, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 16, 'OT', 'Hai bảng ấy là công việc Đức Chúa Trời làm ra, và chữ viết cũng là chữ Đức Chúa Trời khắc trên các bảng.'),
(2456, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 17, 'OT', 'Giô-suê nghe tiếng dân chúng la ầm ĩ, bèn nói với Môi-se: "Tiếng chiến tranh vang lên trong trại quân."'),
(2457, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 18, 'OT', 'Không phải tiếng reo hò chiến thắng, cũng không phải tiếng kêu than thất bại; ấy là tiếng hát mà tôi đang nghe.'),
(2458, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 19, 'OT', 'Khi Môi-se đến gần trại quân, thấy bò con và cảnh nhảy múa, thì cơn thịnh nộ của Môi-se nổi lên, bèn liệng hai bảng chứng khỏi tay mình, và đập bể chúng ra nơi chân núi;'),
(2459, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 20, 'OT', 'Ông lấy con bò con mà họ đã làm, đem đốt trong lửa, nghiền đến khi thật nhỏ, rải trên mặt nước, rồi cho dân Y-sơ-ra-ên uống.'),
(2460, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 21, 'OT', 'Môi-se nói với A-rôn: "Dân nầy đã làm chi cho anh, mà anh lại khiến họ phạm tội trọng như vậy?"'),
(2461, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 22, 'OT', 'A-rôn nói: Xin chúa tôi chớ nổi giận; chính ngài biết dân nầy là kẻ làm ác.'),
(2462, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 23, 'OT', 'Họ nói cùng tôi rằng: Hãy làm cho chúng tôi các thần để đi trước mặt chúng tôi, vì về phần Môi-se, người đàn ông đã dẫn chúng tôi lên từ đất Ai Cập, chúng tôi không biết điều gì đã xảy đến cho ông ấy.'),
(2463, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 24, 'OT', 'Tôi nói với họ: "Ai có vàng, hãy tháo ra!" Họ liền đưa cho tôi; tôi ném vàng vào lửa, và con bò vàng ấy liền xuất hiện.'),
(2464, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 25, 'OT', 'Môi-se thấy dân sự buông lung, vì A-rôn đã để họ buông lung, đến nỗi bị sỉ nhục giữa các kẻ thù nghịch của họ.'),
(2465, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 26, 'OT', 'Môi-se đứng nơi cửa trại quân, nói rằng: Ai thuộc về Đức Giê-hô-va, hãy đến cùng ta! Hết thảy con cái Lê-vi liền nhóm lại gần người.'),
(2466, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 27, 'OT', 'Người nói với họ: Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên phán như vầy: Mỗi người hãy đặt gươm mình trên hông, đi qua đi lại trong trại từ cửa này đến cửa kia, và mỗi người hãy giết anh em mình, bạn mình, và người thân gần mình.'),
(2467, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 28, 'OT', 'Bấy giờ, các con trai Lê-vi làm theo lời Môi-se; và trong ngày ấy, có khoảng ba ngàn người trong dân chúng bị giết.'),
(2468, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 29, 'OT', 'Vậy Môi-se nói: "Hôm nay, hãy làm cho tay các ngươi đầy vì Đức Giê-hô-va, mỗi người vì con trai mình và vì anh em mình, để ngày nay ban phước cho các ngươi."'),
(2469, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 30, 'OT', 'Sáng hôm sau, Môi-se nói với dân chúng rằng: Các ngươi đã phạm một tội rất lớn; nhưng bây giờ ta sẽ lên đến Đức Giê-hô-va, có thể ta sẽ làm sự chuộc tội cho tội các ngươi.'),
(2470, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 31, 'OT', 'Môi-se trở lại cùng Đức Giê-hô-va và thưa rằng: Ôi, dân sự nầy đã phạm tội lớn, họ đã làm cho mình các thần bằng vàng.'),
(2471, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 32, 'OT', 'Bây giờ, nếu Ngài tha tội cho họ, thì tốt; còn nếu không, xin hãy xóa tôi khỏi sách mà Ngài đã chép tên.'),
(2472, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 33, 'OT', 'Đức Giê-hô-va phán cùng Môi-se: "Kẻ nào phạm tội cùng ta, ta sẽ xóa khỏi sách của ta."'),
(2473, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 34, 'OT', 'Bây giờ, hãy đi, dẫn dân nầy đến nơi ta đã phán cùng ngươi; nầy, thiên sứ ta sẽ đi trước mặt ngươi; nhưng đến ngày ta hình phạt, ta sẽ trừng phạt chúng nó về tội lỗi của chúng nó.'),
(2474, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 32, 35, 'OT', 'Đức Giê-hô-va giáng họa cho dân sự vì điều chúng đã làm về con bò vàng mà A-rôn đã làm ra.'),
(2475, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 33, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Hãy đi lên từ đây, ngươi và dân mà ngươi đã dẫn ra khỏi đất Ê-díp-tô, đến đất ta đã chỉ cho Aùp-ra-ham, Y-sác và Gia-cốp mà thề rằng: Ta sẽ ban cho dòng dõi ngươi.'),
(2476, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 33, 2, 'OT', 'Ta sẽ sai một thiên sứ đi trước ngươi, và Ta sẽ đuổi dân Ca-na-an, dân A-mô-rít, dân Hê-tít, dân Phê-rê-sít, dân Hê-vít và dân Giê-bu-sít,'),
(2477, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 33, 3, 'OT', 'vào xứ chảy sữa và mật; nhưng Ta sẽ không đi lên giữa ngươi, vì ngươi là một dân cứng cổ, e rằng Ta sẽ tiêu diệt ngươi trên đường đi.'),
(2478, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 33, 4, 'OT', 'Dân sự nghe lời xấu hôi nầy, bèn buồn rầu, và không một người nào đeo đồ trang sức của mình trên mình.'),
(2479, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 33, 5, 'OT', 'Đức Giê-hô-va phán cùng Môi-se: Hãy nói cùng con cái Y-sơ-ra-ên rằng: Các ngươi là một dân cứng cổ; chỉ một khoảnh khắc thôi, nếu Ta lên giữa các ngươi, Ta sẽ tiêu diệt các ngươi. Vậy bây giờ, hãy cất bỏ đồ trang sức ngươi khỏi mình đi, để Ta biết Ta sẽ làm gì cho các ngươi.'),
(2480, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 33, 6, 'OT', 'Vì vậy, từ núi Hô-rếp, con cái Y-sơ-ra-ên đã lột bỏ các đồ trang sức của mình.'),
(2481, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 33, 7, 'OT', 'Môi-se lấy trại và dựng nó ra ngoài trại quân, cách xa trại quân; người gọi nó là Trại Hội mạc. Xảy ra rằng hễ ai tìm kiếm Đức Giê-hô-va thì đều đi ra trại Hội mạc, là nơi ở ngoài trại quân.'),
(2482, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 33, 8, 'OT', 'Khi Môi-se ra đi đến nơi ở tạm, thì toàn thể dân sự đều đứng dậy; mỗi người đứng nơi cửa lều mình và nhìn theo Môi-se cho đến khi ông vào nơi ở tạm.'),
(2483, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 33, 9, 'OT', 'Khi Môi-se vào nơi trại, thì trụ mây hạ xuống, đứng tại cửa trại, và Đức Giê-hô-va phán cùng Môi-se.'),
(2484, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 33, 10, 'OT', 'Toàn dân thấy cột mây đứng tại cửa hội mạc, thì mỗi người đều đứng dậy và thờ lạy tại cửa lều mình.'),
(2485, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 33, 11, 'OT', 'Đức Giê-hô-va phán cùng Môi-se mặt đối mặt, như một người nói chuyện với bạn mình. Rồi Môi-se trở về trại; còn Giô-suê, con trai Nun, người đầy tớ trẻ tuổi của ông, thì không rời khỏi giữa hội mạc.'),
(2486, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 33, 12, 'OT', 'Môi-se thưa cùng Đức Giê-hô-va rằng: "Xin xem, Ngài phán cùng tôi rằng: Hãy đem dân nầy lên, nhưng Ngài chưa cho tôi biết kẻ nào Ngài sai đi cùng tôi. Dầu Ngài có phán rằng: Ta biết ngươi theo danh ngươi, và ngươi đã được ơn trước mặt ta."'),
(2487, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 33, 13, 'OT', 'Vậy bây giờ, nếu thật tôi đã được ơn trước mặt Ngài, xin hãy cho tôi biết đường lối Ngài, để tôi nhận biết Ngài, hầu tìm được ơn trước mặt Ngài; xin hãy nhìn xem, vì dân nầy là dân của Ngài!'),
(2488, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 33, 14, 'OT', 'Đức Giê-hô-va phán: Chính mặt ta sẽ đi và ta sẽ ban cho ngươi được an nghỉ.'),
(2489, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 33, 15, 'OT', 'Môi-se nói với Ngài: "Nếu chính mặt Ngài không đi, thì xin đừng dẫn chúng tôi lên khỏi nơi này."'),
(2490, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 33, 16, 'OT', 'Vậy thì, bằng cách nào người ta sẽ biết rằng tôi và dân Ngài được ơn trước mặt Ngài, nếu không phải là khi Ngài đi cùng chúng tôi? Như vậy, tôi và dân Ngài sẽ được phân biệt khỏi mọi dân trên mặt đất.'),
(2491, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 33, 17, 'OT', 'Đức Giê-hô-va phán cùng Môi-se: "Ngay điều nầy mà ngươi đã nói, Ta cũng sẽ làm, vì ngươi đã được ơn trước mặt Ta, và Ta biết ngươi theo danh ngươi."'),
(2492, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 33, 18, 'OT', 'Môi-se thưa rằng: Xin hãy cho tôi xem sự vinh hiển của Ngài!'),
(2493, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 33, 19, 'OT', 'Đức Giê-hô-va phán: Ta sẽ làm cho toàn thể sự tốt lành của Ta đi qua trước mặt ngươi, và sẽ kêu lên danh Giê-hô-va trước mặt ngươi; Ta sẽ làm ơn cho ai Ta muốn làm ơn, và sẽ thương xót ai Ta muốn thương xót.'),
(2494, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 33, 20, 'OT', 'Ngài phán: Ngươi sẽ không thể thấy được mặt ta, vì không người nào thấy mặt ta mà còn sống.'),
(2495, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 33, 21, 'OT', 'Đức Giê-hô-va phán: Nầy, có một chỗ gần ta, ngươi hãy đứng trên hòn đá;'),
(2496, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 33, 22, 'OT', 'Khi sự vinh hiển của Ta đi ngang qua, Ta sẽ đặt ngươi trong khe hở của tảng đá, và Ta sẽ che tay Ta trên ngươi cho đến khi Ta đi qua.'),
(2497, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 33, 23, 'OT', 'Ta sẽ rút tay Ta ra, và ngươi sẽ thấy phía sau lưng Ta; nhưng mặt Ta thì không được thấy.'),
(2498, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Hãy đục cho mình hai bảng đá như hai bảng trước; rồi ta sẽ viết trên các bảng đó các lời đã ở trên hai bảng đá trước mà ngươi đã đập bể.'),
(2499, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 2, 'OT', 'Sáng mai, hãy sẵn sàng, lên núi Si-na-i vào buổi sáng và đứng trước mặt ta tại đó, trên đỉnh núi.'),
(2500, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 3, 'OT', 'Chẳng ai được lên cùng ngươi, và cũng không ai được thấy ở khắp núi nầy; chiên và bò cũng không được ăn cỏ đối diện núi nầy.'),
(2501, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 4, 'OT', 'Môi-se đục hai bảng đá như hai bảng trước, rồi sáng sớm dậy, lên núi Si-na-i, tay cầm hai bảng đá, y như lời Đức Giê-hô-va đã truyền cho ông.'),
(2502, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 5, 'OT', 'Đức Giê-hô-va ngự xuống trong đám mây, đứng gần bên Môi-se và xướng danh Giê-hô-va.'),
(2503, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 6, 'OT', 'Đức Giê-hô-va đi ngang qua trước mặt người, và kêu lên: Đức Giê-hô-va! Đức Giê-hô-va! là Đức Chúa Trời nhân từ, hay thương xót, chậm giận, đầy dẫy ân điển và sự thật,'),
(2504, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 7, 'OT', 'giữ lòng nhân từ cho đến ngàn đời, tha thứ tội lỗi, sự vi phạm và tội nhân; nhưng không coi kẻ có tội là vô tội, mà phạt tội tổ phụ đến con cháu, đến thế hệ thứ ba và thứ tư.'),
(2505, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 8, 'OT', 'Môi-se vội vã cúi mặt xuống đất và thờ lạy.'),
(2506, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 9, 'OT', 'Xin hãy nói: Nếu thật tôi được ơn trước mặt Ngài, hỡi Chúa, xin Chúa hãy đi giữa chúng con; vì dân nầy là một dân cứng cổ. Xin hãy tha thứ cho sự gian ác và tội lỗi chúng con, và nhận chúng con làm cơ nghiệp của Ngài.'),
(2507, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 10, 'OT', 'Đức Giê-hô-va phán: Nầy, ta lập giao ước trước mặt cả dân ngươi; ta sẽ làm những điều kỳ diệu chưa hề được tạo ra trên khắp đất hay trong bất cứ dân tộc nào. Toàn thể dân chúng mà ngươi đang ở giữa họ sẽ thấy công việc của Đức Giê-hô-va, vì điều ta làm cùng ngươi thật đáng kinh sợ.'),
(2508, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 11, 'OT', 'Hãy giữ lấy điều mà Đức Giê-hô-va truyền cho ngươi ngày nay: Nầy, ta sẽ đuổi khỏi trước mặt ngươi dân A-mô-rít, dân Ca-na-an, dân Hê-tít, dân Phê-rê-sít, dân Hê-vít và dân Giê-bu-sít.'),
(2509, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 12, 'OT', 'Hãy giữ mình, chớ lập giao ước với dân của xứ mà ngươi sẽ vào, e nó sẽ trở thành cái bẫy giữa vòng ngươi.'),
(2510, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 13, 'OT', 'Phải phá dỡ các bàn thờ của chúng, đập bể các trụ thờ, và chặt các trụ đá của chúng nó.'),
(2511, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 14, 'OT', 'Vì ngươi không được thờ lạy một thần nào khác, vì Đức Giê-hô-va, danh Ngài là Đấng Ghen, chính Ngài là Đức Chúa Trời hay ghen.'),
(2512, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 15, 'OT', 'Hãy giữ mình, đừng lập giao ước với dân ở đất này, e khi chúng nó làm điều dâm loạn theo các thần của chúng nó, và dâng tế lễ cho các thần của chúng nó, rồi mời ngươi, và ngươi ăn của lễ nơi bàn thờ nó.'),
(2513, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 16, 'OT', 'Đừng đem con gái của chúng nó mà gả cho con trai ngươi; vì các con gái ấy sẽ hành dâm theo các thần của chúng nó, và sẽ quyến dụ con trai ngươi cũng đi hành dâm theo các thần của chúng nó.'),
(2514, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 17, 'OT', 'Ngươi không được làm các thần bằng cách đúc.'),
(2515, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 18, 'OT', 'Hãy giữ lễ bánh không men: trong bảy ngày, ngươi phải ăn bánh không men, như Ta đã truyền cho ngươi, đúng vào thời kỳ tháng lúa trỗ; vì trong tháng lúa trỗ ngươi đã ra khỏi Ai-cập.'),
(2516, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 19, 'OT', 'Mọi con đầu lòng đều thuộc về ta; và mọi súc vật đực đầu lòng của ngươi, cả bò và chiên, cũng phải được biệt riêng ra.'),
(2517, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 20, 'OT', 'Con đầu lòng của lừa đực, ngươi phải chuộc bằng chiên con; nếu không chuộc, phải bẻ cổ nó. Tất cả con đầu lòng của các con trai ngươi, ngươi phải chuộc; và không ai được đến trước mặt ta tay không.'),
(2518, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 21, 'OT', 'Trong sáu ngày ngươi phải làm việc, còn ngày thứ bảy ngươi phải nghỉ, dù trong mùa cày hay mùa gặt ngươi cũng phải nghỉ.'),
(2519, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 22, 'OT', 'Hãy giữ lễ Mùa Gặt, tức lễ của các tuần lễ, vào lúc đầu mùa gặt lúa mì; và lễ Thu Hoạch vào lúc cuối năm.'),
(2520, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 23, 'OT', 'Hằng năm ba lần, mọi người nam trong các ngươi phải xuất hiện trước mặt Đức Giê-hô-va, là Đức Chúa Trời của Y-sơ-ra-ên.'),
(2521, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 24, 'OT', 'Vì Ta sẽ đuổi các dân ra khỏi trước mặt ngươi và mở rộng bờ cõi ngươi; và chẳng ai sẽ tham muốn đất ngươi, khi ngươi lên chầu trước mặt Đức Giê-hô-va Đức Chúa Trời ngươi ba lần trong năm.'),
(2522, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 25, 'OT', 'Ngươi không được giết sinh tế của ta trên bánh có men, và sinh tế lễ Vượt-qua không được để đến sáng hôm sau.'),
(2523, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 26, 'OT', 'Hãy đem những sản vật đầu mùa của đất mà dâng vào nhà Đức Giê-hô-va Đức Chúa Trời ngươi. Đừng nấu dê con trong sữa mẹ nó.'),
(2524, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 27, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Hãy chép những lời nầy cho mình ngươi; vì theo các lời nầy mà ta đã lập giao ước cùng ngươi và cùng Y-sơ-ra-ên.'),
(2525, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 28, 'OT', 'Môi-se ở đó cùng Đức Giê-hô-va bốn mươi ngày và bốn mươi đêm, không ăn bánh, không uống nước; và Môi-se chép trên các bảng đá các lời của giao ước, là mười điều răn.'),
(2526, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 29, 'OT', 'Khi Môi-se đi xuống từ núi Si-na-i, tay Môi-se cầm hai bảng chứng, và Môi-se không biết rằng da mặt mình phát sáng khi Đức Giê-hô-va phán cùng người.'),
(2527, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 30, 'OT', 'A-rôn cùng tất cả con cái Y-sơ-ra-ên nhìn thấy Môi-se, thấy da mặt người phát sáng, thì sợ không dám đến gần người.'),
(2528, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 31, 'OT', 'Môi-se gọi họ, A-rôn và tất cả các quan trưởng trong hội chúng trở về cùng người, rồi Môi-se nói chuyện cùng họ.'),
(2529, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 32, 'OT', 'Sau đó, toàn thể con cái Y-sơ-ra-ên đến gần, và ông truyền cho họ mọi điều mà Đức Giê-hô-va đã phán cùng ông tại núi Si-na-i.'),
(2530, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 33, 'OT', 'Khi Môi-se chấm dứt việc nói chuyện với họ, ông đặt một cái màn che trên mặt mình.'),
(2531, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 34, 'OT', 'Khi Môi-se vào trước mặt Đức Giê-hô-va để nói chuyện với Ngài, thì cởi tấm lúp cho đến khi ra đi; rồi khi ra, ông nói với con cái Y-sơ-ra-ên mọi điều mà Đức Giê-hô-va đã truyền dặn ông.'),
(2532, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 34, 35, 'OT', 'Dân Y-sơ-ra-ên nhìn thấy mặt Môi-se, thấy da mặt Môi-se phát sáng; rồi Môi-se lấy khăn che mặt mình cho đến khi vào nói chuyện với Đức Giê-hô-va.'),
(2533, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 1, 'OT', 'Môi-se nhóm toàn thể hội chúng Y-sơ-ra-ên lại, rồi nói với họ rằng: Đây là những điều mà Đức Giê-hô-va đã truyền phải làm.'),
(2534, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 2, 'OT', 'Sáu ngày phải làm công việc, nhưng ngày thứ bảy sẽ là ngày thánh cho các ngươi, một ngày Sa-bát nghỉ ngơi biệt riêng ra thánh cho Đức Giê-hô-va. Hễ ai làm công việc trong ngày đó sẽ bị xử tử.'),
(2535, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 3, 'OT', 'Ngày sa-bát, các ngươi không được nhóm lửa trong bất kỳ nơi ở nào của mình.'),
(2536, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 4, 'OT', 'Môi-se nói với toàn thể hội chúng Y-sơ-ra-ên rằng: Đây là điều mà Đức Giê-hô-va đã truyền dạy để nói:'),
(2537, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 5, 'OT', 'Hãy lấy từ giữa các ngươi một lễ vật dâng cho Đức Giê-hô-va; hễ ai có lòng sốt sắng, lòng người đó sẽ dâng lễ vật dâng cho Đức Giê-hô-va: vàng, bạc và đồng.'),
(2538, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 6, 'OT', 'xanh thẫm, đỏ điều, đỏ sậm, vải gai mịn và lông dê'),
(2539, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 7, 'OT', 'da chiên đực nhuộm đỏ, da thú biển, và cây gỗ si-tim'),
(2540, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 8, 'OT', 'dầu để thắp sáng, các thứ hương liệu để chế dầu xức và hương thơm,'),
(2541, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 9, 'OT', 'các viên ngọc ô-ni và các viên ngọc khảm khác, để khảm vào áo ê-phót và bảng đeo ngực.'),
(2542, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 10, 'OT', 'Mọi người thợ khéo trong lòng các ngươi hãy đến và làm mọi điều Đức Giê-hô-va đã truyền dạy.'),
(2543, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 11, 'OT', 'đền tạm, trại và cái lều che của nó, các móc, các ván, các thanh ngang, các trụ và các đế của nó;'),
(2544, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 12, 'OT', 'rương chứng ước và các đòn khiêng, nắp thi ân cùng bức màn che phủ;'),
(2545, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 13, 'OT', 'cái bàn và các đòn khiêng của nó, cùng mọi đồ dùng của nó và bánh trần thiết;'),
(2546, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 14, 'OT', 'và chân đèn của sự sáng, các đồ của nó, các đèn của nó, và dầu của chân đèn sự sáng;'),
(2547, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 15, 'OT', 'và bàn thờ xông hương cùng các đòn khiêng của nó, dầu xức, hương thơm, và bức màn che cửa đền tạm tại cửa đền tạm.'),
(2548, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 16, 'OT', 'bàn thờ lễ thiêu, cái nắp bằng đồng của nó, các đòn khiêng và mọi đồ dùng của nó, cái thùng nước và chân thùng của nó;'),
(2549, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 17, 'OT', 'các bức màn hành lang, các trụ của nó, các đế của nó, và bức màn cửa hành lang;'),
(2550, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 18, 'OT', 'các trụ của đền tạm, cùng các trụ của hành lang và dây của chúng;'),
(2551, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 19, 'OT', 'các áo lễ để phục vụ nơi thánh, các áo thánh cho A-rôn thầy tế lễ và các áo cho các con trai người để làm thầy tế lễ.'),
(2552, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 20, 'OT', 'Cả hội chúng con cái Y-sơ-ra-ên bèn lui ra khỏi mặt Môi-se.'),
(2553, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 21, 'OT', 'Mọi người, mỗi ai có lòng được cảm động và mỗi ai có tâm tình tự nguyện, đều mang của lễ dâng lên Đức Giê-hô-va để làm công việc về Hội mạc, mọi công việc phục vụ nó và các bộ áo thánh.'),
(2554, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 22, 'OT', 'Các người nam cùng đi với các người nữ, mọi kẻ có lòng hăng hái đều mang đến vòng móc, vòng khuyên, ấn triện, vòng đeo cổ, mọi thứ đồ bằng vàng; và mỗi người nam nào dâng lễ vật lay động bằng vàng cho Đức Giê-hô-va.'),
(2555, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 23, 'OT', 'Mỗi người đàn ông nào ở cùng mình có màu xanh lam, màu tím đỏ, màu đỏ điều, vải gai mịn, lông dê, da chiên đực nhuộm đỏ và da thú mòng biển thì mang đến.'),
(2556, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 24, 'OT', 'Hễ ai dâng lễ vật bằng bạc hay bằng đồng, thì đem dâng lễ vật cho Đức Giê-hô-va; và hễ ai có gỗ si-tim trong tay mình để làm mọi công việc của công trình phục vụ, thì đều đem đến.'),
(2557, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 25, 'OT', 'Mọi người phụ nữ khéo léo trong tay mình đã kéo chỉ, và họ mang đến các thứ chỉ đã kéo: chỉ màu xanh lam, chỉ màu tím đỏ, chỉ màu đỏ điều, và chỉ gai mịn.'),
(2558, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 26, 'OT', 'Và mọi người phụ nữ mà lòng họ cảm động và tài khéo léo, thì kéo chỉ lông dê.'),
(2559, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 27, 'OT', 'Các quan lãnh đạo dâng những viên ngọc onyx và các viên ngọc khác để khảm vào áo thầy tế lễ và bảng đeo ngực.'),
(2560, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 28, 'OT', 'và mộc dược, cùng dầu để thắp sáng, và dầu để xức, và các hương liệu đốt.'),
(2561, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 29, 'OT', 'Mọi người nam và nữ trong dân Y-sơ-ra-ên, ai có lòng được cảm động để tự nguyện dâng cho mọi công việc mà Đức Giê-hô-va đã truyền phải làm qua tay Môi-se, đều dâng của lễ tự nguyện cho Đức Giê-hô-va.'),
(2562, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 30, 'OT', 'Môi-se nói cùng con cái Y-sơ-ra-ên rằng: Này, Đức Giê-hô-va đã gọi danh Bết-sa-lê-ên, con trai của U-ri, cháu của Hu-rơ, thuộc chi phái Giu-đa.'),
(2563, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 31, 'OT', 'và khiến người đầy dẫy Thần của Đức Chúa Trời, với sự khôn ngoan, sự thông sáng, và sự hiểu biết, cùng mọi nghề thợ,'),
(2564, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 32, 'OT', 'đặng suy nghĩ ra các ý tưởng, để làm công việc bằng vàng, bạc và đồng,'),
(2565, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 33, 'OT', 'khắc đá để khảm, và chạm trổ gỗ để làm mọi công việc tinh xảo.'),
(2566, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 34, 'OT', 'Ngài cũng ban cho người tài dạy dỗ, và cho Ô-hô-li-áp, con của A-hi-sa-mạc, thuộc chi phái Đan.'),
(2567, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 35, 35, 'OT', 'Đầy dẫy họ sự khôn ngoan trong lòng đặng làm mọi công việc của thợ mộc, thợ thiết kế, thợ thêu bằng chỉ xanh biếc, đỏ điều, đỏ sặm và vải gai mịn, và thợ dệt, tức là những người làm mọi công việc và suy nghĩ ra các ý tưởng.'),
(2568, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 1, 'OT', 'Bết-sa-lê-ên, Ô-hô-li-áp và mọi người khôn ngoan, tức là những người mà Đức Giê-hô-va đã ban sự khôn ngoan và thông sáng để biết làm mọi công việc phục vụ nơi thánh, đều làm mọi điều mà Đức Giê-hô-va đã truyền dặn.'),
(2569, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 2, 'OT', 'Môi-se gọi Bết-sa-lê-ên, A-hô-li-áp và mọi người khôn ngoan mà Đức Giê-hô-va đã ban sự khôn ngoan vào lòng, mọi người mà lòng họ đầy khao khát đến gần để làm công việc ấy.'),
(2570, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 3, 'OT', 'Trước mặt Môi-se, họ lấy tất cả các lễ vật mà con cái Y-sơ-ra-ên đã mang đến, để làm các công việc phục vụ nơi thánh; và họ còn tiếp tục mang đến cho ông những lễ dâng tự nguyện mỗi buổi sáng sớm.'),
(2571, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 4, 'OT', 'Bấy giờ, mọi người thợ khéo làm các công việc về nơi thánh đều đến, mỗi người từ công việc mình đang làm,'),
(2572, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 5, 'OT', 'đến cùng Môi-se mà nói rằng: Dân sự đem đến quá nhiều cho công việc, tức là mọi công việc mà Đức Giê-hô-va đã truyền phải làm.'),
(2573, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 6, 'OT', 'Theo lịnh Môi-se truyền, người ta sai rao khắp trại quân rằng: "Mỗi người, bất luận nam hay nữ, chớ làm công việc gì nữa về lễ vật của nơi thánh!" Vậy dân sự thôi không đem của đến nữa.'),
(2574, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 7, 'OT', 'Công việc làm đủ cho mọi công việc phải làm, và còn dư nữa.'),
(2575, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 8, 'OT', 'Vậy các người khôn lòng trong những thợ làm công việc đã làm mười bức màn cho đền tạm bằng vải gai mịn, màu xanh, tím và đỏ sậm, thêu hình các chê-ru-bin theo kiểu thợ khéo.'),
(2576, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 9, 'OT', 'Chiều dài của mỗi tấm màn là hai mươi tám thước, chiều rộng là bốn thước; tất cả các tấm màn đều cùng một kích thước.'),
(2577, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 10, 'OT', 'Họ nối năm bức màn nầy lại với nhau, và nối năm bức màn kia lại với nhau.'),
(2578, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 11, 'OT', 'Làm những cái móc bằng chỉ xanh nơi mép của bức màn đầu tiên ở đầu mối nối, và cũng làm như vậy cho mép của bức màn nơi chót trong mối nối thứ hai.'),
(2579, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 12, 'OT', 'Làm năm mươi cái móc ở bức màn nọ, và làm năm mươi cái móc ở đầu bức màn kia, tức là nơi mối nối thứ hai; các cái móc đối xứng nhau, cái này đối diện cái kia.'),
(2580, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 13, 'OT', 'Làm năm mươi cái móc bằng vàng, rồi dùng các móc đó nối các tấm trại với nhau, khiến cho đền tạm trở thành một khối.'),
(2581, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 14, 'OT', 'Họ làm các bức màn bằng lông dê để làm mái che cho đền tạm; họ đã làm mười một bức màn.'),
(2582, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 15, 'OT', 'Mỗi bức màn dài ba mươi thước, rộng bốn thước; mười một bức màn đều cùng một kích thước.'),
(2583, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 16, 'OT', 'Mỗi người nối năm bức màn riêng ra; và sáu bức màn khác riêng ra.'),
(2584, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 17, 'OT', 'Làm năm mươi cái móc nơi mép của bức màn ngoài cùng trong mối nối, và làm năm mươi cái móc nơi mép của bức màn nối thứ hai.'),
(2585, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 18, 'OT', 'Làm năm mươi cái móc bằng đồng, để nối cái lều lại thành một.'),
(2586, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 19, 'OT', 'Họ làm một cái lều che cho đền tạm bằng da chiên đực nhuộm đỏ, và một cái lều che bằng da thú biển đặt lên phía trên.'),
(2587, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 20, 'OT', 'Họ làm các tấm ván cho đền tạm bằng gỗ cây si-tim, đứng thẳng.'),
(2588, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 21, 'OT', 'Mười thước dài mỗi tấm ván, và một thước rưỡi bề rộng của mỗi tấm ván.'),
(2589, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 22, 'OT', 'Hai cái chốt cho mỗi tấm ván, cái nầy hiệp với cái kia; người làm như thế cho mọi tấm ván của đền tạm.'),
(2590, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 23, 'OT', 'Họ làm các tấm ván cho đền tạm: hai mươi tấm ván về phía nam.'),
(2591, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 24, 'OT', 'Làm bốn mươi đế bạc đặt dưới hai mươi tấm ván: hai đế dưới một tấm ván cho hai đầu của nó, và hai đế dưới một tấm ván cho hai đầu của nó.'),
(2592, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 25, 'OT', 'Họ làm hai mươi tấm ván cho cạnh thứ hai của đền tạm, về phía bắc.'),
(2593, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 26, 'OT', 'Bốn mươi bệ bằng bạc; hai bệ dưới tấm này, và hai bệ dưới tấm kia.'),
(2594, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 27, 'OT', 'Phía sau của đền tạm, về phía tây, người ta làm sáu tấm ván,'),
(2595, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 28, 'OT', 'Và làm hai tấm ván cho hai góc của nhà tạm ở phía sau.'),
(2596, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 29, 'OT', 'Hai tấm cuối cùng ở phía dưới khít với nhau, và cả hai sẽ trọn vẹn đến đầu chúng, đến cái vòng duy nhất; người ta làm như vậy cho cả hai tấm cuối cùng ở hai phía.'),
(2597, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 30, 'OT', 'Và có tám tấm ván, và đế bạc của chúng là mười sáu cái, hai cái đế dưới mỗi tấm ván.'),
(2598, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 31, 'OT', 'Họ làm năm cây đòn ngang bằng gỗ cây si-tim cho các tấm ván bên cạnh này của đền tạm,'),
(2599, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 32, 'OT', 'Năm cái thanh ngang cho các tấm ván bên hông thứ hai của đền tạm, và năm cái thanh ngang cho các tấm ván của đền tạm về phía sau, tức là phía tây.'),
(2600, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 33, 'OT', 'Họ làm cây đòn ngang giữa để luồn qua bên trong các tấm ván từ đầu này đến đầu kia.'),
(2601, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 34, 'OT', 'Họ đã bọc vàng các tấm ván, và làm các vòng của chúng bằng vàng để xỏ các cây đòn ngang, rồi bọc vàng các cây đòn ngang.'),
(2602, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 35, 'OT', 'Họ làm bức màn bằng chỉ xanh lam, tím, đỏ điều và vải gai mịn, thêu hình các chê-ru-bin theo kiểu thợ khéo léo.'),
(2603, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 36, 'OT', 'Họ làm cho nó bốn trụ bằng gỗ si-tim, mạ vàng các móc và các đế của nó bằng vàng, và đúc cho chúng bốn đế bằng bạc.'),
(2604, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 37, 'OT', 'Họ làm một cái màn che lối vào mái trại bằng chỉ xanh lam, tím sẫm, đỏ điều và vải gai mịn, thêu bằng kỹ thuật thợ khéo.'),
(2605, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 36, 38, 'OT', 'Và năm cây trụ của nó, cùng các móc của chúng, và cái đầu cùng các vòng đai của chúng thì mạ vàng; còn bệ của chúng thì năm cái bằng đồng.'),
(2606, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 37, 1, 'OT', 'Bết-sa-lê-ên làm hòm bằng gỗ si-tim, dài hai thước rưỡi, rộng một thước rưỡi, và cao một thước rưỡi.'),
(2607, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 37, 2, 'OT', 'Người bọc vàng ròng bên trong và bên ngoài, và làm cho nó một viền vàng ròng bao quanh.'),
(2608, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 37, 3, 'OT', 'Đúc cho nó bốn cái vòng vàng trên bốn chân của nó, và hai cái vòng bên cạnh này, hai cái vòng bên cạnh kia.'),
(2609, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 37, 4, 'OT', 'Người làm các đòn bằng gỗ si-tim, và bọc chúng bằng vàng.'),
(2610, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 37, 5, 'OT', 'rồi đưa các cây đòn vào các vòng trên các cạnh của hòm để khiêng hòm.'),
(2611, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 37, 6, 'OT', 'Người làm một nắp thi ân bằng vàng ròng, dài hai thước rưỡi, rộng một thước rưỡi.'),
(2612, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 37, 7, 'OT', 'Làm hai tượng chê-ru-bim bằng vàng, đúc cùng một khối, làm chúng nơi hai đầu nắp thi ân.'),
(2613, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 37, 8, 'OT', 'Một con Kê-ru-ub ở đầu này và một con Kê-ru-ub ở đầu kia, các con Kê-ru-ub được làm cùng với nắp nơi hai đầu mút của nó.'),
(2614, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 37, 9, 'OT', 'Hai con chê-ru-bin giang cánh ra phía trên, lấy cánh che phủ xuống nắp thi ân, và mặt chúng hướng về nhau, mặt của hai con chê-ru-bin đều hướng về phía nắp thi ân.'),
(2615, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 37, 10, 'OT', 'Người làm cái bàn bằng gỗ si-tim; dài hai thước, rộng một thước, cao một thước rưỡi.'),
(2616, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 37, 11, 'OT', 'Phủ nó bằng vàng ròng, và làm cho nó một viền vàng chung quanh.'),
(2617, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 37, 12, 'OT', 'Làm cho nó viền xung quanh rộng một gang tay, và làm một cái viền bằng vàng cho viền của nó xung quanh.'),
(2618, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 37, 13, 'OT', 'Đúc cho nó bốn cái vòng vàng, và đặt các cái vòng ấy trên bốn góc, tại các chân của nó.'),
(2619, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 37, 14, 'OT', 'Các vòng đeo ở ngang hàng với viền, là những cái nhà cho các cây đòn dùng để khiêng cái bàn.'),
(2620, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 37, 15, 'OT', 'Chế tạo các đòn bằng gỗ si-tim, rồi mạ vàng chúng, để khiêng bàn.'),
(2621, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 37, 16, 'OT', 'Người làm các đồ dùng trên bàn: đĩa đựng đồ của người, chén rót rượu, thìa múc rượu và các bình đổ nước, tất cả đều bằng vàng ròng.'),
(2622, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 37, 17, 'OT', 'Người làm cây đèn bằng vàng ròng; từ chính khối vàng mà làm ra cây đèn, gồm đế nó, thân nó, chén nó, búp nó và bông hoa nó; tất cả đều làm từ khối vàng ấy.'),
(2623, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 37, 18, 'OT', 'Sáu cây gậy vươn ra từ hai bên nó: ba cây gậy của chân đèn từ bên này và ba cây gậy của chân đèn từ bên kia.'),
(2624, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 37, 19, 'OT', 'Ba cái chén hình trái hạnh nhân, cùng với nụ và hoa, trên một nhánh; ba cái chén hình trái hạnh nhân, cùng với nụ và hoa, trên một nhánh khác; cứ như vậy cho sáu nhánh xuất ra từ chân đèn.'),
(2625, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 37, 20, 'OT', 'Trên chân đèn có bốn cái chén hình hoa hạnh nhân nở, cả những cái núm và những bông hoa của nó.'),
(2626, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 37, 21, 'OT', 'Dưới mỗi hai nhánh trong sáu nhánh mọc ra từ thân ấy đều có một cái hoa văn.'),
(2627, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 37, 22, 'OT', 'Bầu và các nhánh của nó đều làm bằng vàng ròng, toàn bộ đều được đúc bằng một khối vàng ròng.'),
(2628, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 37, 23, 'OT', 'Người làm bảy cái đèn của nó, và kéo bắt tim cùng muỗng hốt than của nó bằng vàng ròng.'),
(2629, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 37, 24, 'OT', 'Người làm chân đèn bằng một ta-lâng vàng ròng, và làm tất cả các đồ dùng của nó.'),
(2630, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 37, 25, 'OT', 'Người làm cái bàn thờ xông hương bằng gỗ si-tim; bàn thờ dài một thước, rộng một thước, hình vuông, cao hai thước; các sừng của nó làm ra từ chính nó.'),
(2631, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 37, 26, 'OT', 'Người bọc nó bằng vàng ròng, mặt trên và các vách chung quanh và các sừng của nó; Người làm cho nó một viền vàng chung quanh.'),
(2632, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 37, 27, 'OT', 'Dưới đường viền của nó, nơi hai bên cạnh, người làm hai cái khoen vàng để xỏ đòn khiêng.'),
(2633, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 37, 28, 'OT', 'Người làm các đòn bằng gỗ si-tim và bọc chúng bằng vàng.'),
(2634, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 37, 29, 'OT', 'Người làm dầu xức thánh và hương thanh sạch, theo công việc của người pha chế hương.'),
(2635, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 38, 1, 'OT', 'Người làm bàn thờ của lễ thiêu bằng gỗ si-tim, dài năm thước, rộng năm thước, hình vuông, và cao ba thước.'),
(2636, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 38, 2, 'OT', 'Ông làm các sừng của nó trên bốn góc bàn thờ, các sừng ấy được đúc liền với bàn thờ, và ông mạ nó bằng đồng.'),
(2637, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 38, 3, 'OT', 'Làm tất cả các đồ dùng của bàn thờ, tức là các cái chảo, các cái vá, các cái xô, các cái dĩa và các cái xẻng; tất cả các đồ dùng của bàn thờ, người làm bằng đồng.'),
(2638, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 38, 4, 'OT', 'Làm cho bàn thờ một cái lồng bằng lưới đồng, dưới chân nó từ phía dưới lên đến giữa.'),
(2639, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 38, 5, 'OT', 'Đúc bốn cái vòng ở bốn góc cái bàn thờ bằng đồng, làm nơi đặt các cây khiêng.'),
(2640, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 38, 6, 'OT', 'Làm những cây đòn bằng gỗ si-tim, và bọc đồng.'),
(2641, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 38, 7, 'OT', 'Xỏ các đòn vào các vòng nơi hai bên bàn thờ, để khiêng nó; bàn thờ được làm bằng các tấm ván rỗng.'),
(2642, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 38, 8, 'OT', 'Người làm cái thùng bằng đồng và chân thùng bằng đồng, bằng các tấm gương của những người đàn bà nhóm lại hầu việc nơi cửa hội mạc.'),
(2643, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 38, 9, 'OT', 'Người làm hành lang; về phía nam, phía nam, các bức vải hành lang bằng vải gai mịn, dài một trăm thước.'),
(2644, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 38, 10, 'OT', 'hai mươi cái trụ và hai mươi đế trụ bằng đồng, các móc trụ và các thanh ngang nối các trụ bằng bạc.'),
(2645, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 38, 11, 'OT', 'Phía bắc dài một trăm thước, có hai mươi trụ, hai mươi đế trụ bằng đồng, còn móc các trụ và đòn ngang của chúng thì bằng bạc.'),
(2646, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 38, 12, 'OT', 'Về phía tây, có năm mươi thước vải màn, mười cột và mười bệ đáy; các móc và thanh ngang của các cột cùng với các vòng nối đều bằng bạc.'),
(2647, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 38, 13, 'OT', 'Về phía đông, năm mươi thước.'),
(2648, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 38, 14, 'OT', 'Mười lăm thước vải màn về phía bờ vai, cùng với ba cái trụ và ba cái đế của chúng.'),
(2649, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 38, 15, 'OT', 'Về phía bên kia của cổng hành lang, từ phía này đến phía kia, có năm tấm màn, mỗi tấm mười lăm thước; các cây trụ của nó là ba cây, và đế của nó là ba cái.'),
(2650, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 38, 16, 'OT', 'Tất cả các bức màn quanh hành lang đều bằng vải gai mịn.'),
(2651, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 38, 17, 'OT', 'Các đế trụ bằng đồng, các móc và vòng nối trụ bằng bạc, và các đầu trụ được mạ bạc; và hết thảy các trụ của hành lang đều được nối với nhau bằng các vòng nối bạc.'),
(2652, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 38, 18, 'OT', 'Và bức màn nơi cửa hành lang làm bằng nghề thêu, bằng chỉ xanh lam, tím sẫm, đỏ điều và vải gai mịn nhuộm màu; chiều dài hai mươi thước, chiều cao năm thước, theo chiều rộng của các tấm màn xung quanh hành lang.'),
(2653, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 38, 19, 'OT', 'Bốn cây trụ và bốn đế trụ bằng đồng, móc của chúng bằng bạc, các đầu trụ và các thanh ngang của chúng cũng bằng bạc.'),
(2654, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 38, 20, 'OT', 'Tất cả các chốt của đền tạm và của hành lang xung quanh đều bằng đồng.'),
(2655, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 38, 21, 'OT', 'Đây là sổ tổng cộng về đền tạm, là đền tạm chứng cớ, đã được định đoạt theo lời chỉ dạy của Môi-se, công việc của người Lê-vi dưới sự quản lý của Y-tha-ma, con trai thầy tế lễ A-rôn.'),
(2656, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 38, 22, 'OT', 'Bết-sa-lê-ên, con trai của U-ri, cháu trai của Hu-rơ, thuộc chi phái Giu-đa, đã làm mọi điều mà Đức Giê-hô-va đã truyền cho Môi-se.'),
(2657, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 38, 23, 'OT', 'Và cùng người ấy là Ô-hô-li-áp, con trai A-hi-sa-mạc, thuộc chi phái Đan, một thợ đục, một người khéo vẽ mẫu, và một thợ thêu bằng chỉ tím, chỉ đỏ điều, chỉ đỏ sặm và chỉ gai mịn.'),
(2658, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 38, 24, 'OT', 'Hết thảy vàng đã dùng cho mọi công việc tại nơi thánh, tức là vàng dâng, gồm hai mươi chín ta lâng và bảy trăm ba mươi siếc-lơ, theo siếc-lơ của nơi thánh.'),
(2659, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 38, 25, 'OT', 'Bạc dành cho những người được điểm danh của hội chúng là một trăm kikar, một ngàn bảy trăm bảy mươi lăm séc-lơ, theo séc-lơ thánh.'),
(2660, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 38, 26, 'OT', 'Mỗi người qua danh sách kiểm tra, từ hai mươi tuổi trở lên, đều nộp nửa siếc-lơ theo siếc-lơ của nơi thánh, tức là một bê-ca cho mỗi đầu người; tổng số là sáu trăm ngàn, ba ngàn, năm trăm và năm mươi người.'),
(2661, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 38, 27, 'OT', 'Vậy, một trăm kik gan bạc dùng để đúc các bệ đỡ của nơi thánh và các bệ đỡ của bức màn; một trăm bệ đỡ cho một trăm kik gan bạc, mỗi kik gan bạc cho một bệ đỡ.'),
(2662, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 38, 28, 'OT', 'Còn một ngàn bảy trăm bảy mươi lăm miếng bạc, thì làm những cái móc cho các trụ, và bọc các đầu trụ, rồi dùng mộng nối các trụ với nhau.'),
(2663, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 38, 29, 'OT', 'Đồng dùng cho lễ vật dâng là bảy mươi kikar, và hai ngàn bốn trăm siếc-lơ.'),
(2664, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 38, 30, 'OT', 'Dùng đồng đó, người làm các đế trụ ở cửa nhà hội, và bàn thờ bằng đồng, và cái rá bằng đồng đi kèm với bàn thờ ấy, và mọi đồ dùng của bàn thờ.'),
(2665, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 38, 31, 'OT', 'các bệ đỡ của hành lang chung quanh, các bệ đỡ của cửa hành lang, và mọi cây đinh của đền tạm cùng mọi cây đinh của hành lang chung quanh.'),
(2666, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 1, 'OT', 'Họ dùng màu xanh ngọc, màu tím đỏ và màu đỏ điều mà làm các áo lễ để phục vụ trong nơi thánh, và họ làm các áo thánh cho A-rôn như Đức Giê-hô-va đã truyền cho Môi-se.'),
(2667, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 2, 'OT', 'Họ làm cái ê-phót bằng vàng, chỉ xanh, đỏ tía, đỏ điều và sợi gai mịn xoắn lại.'),
(2668, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 3, 'OT', 'Họ đập dẹp các tấm vàng, rồi cắt thành sợi, để làm xen vào giữa chỉ xanh lam, chỉ tím, chỉ điều đỏ và chỉ gai mịn, theo công việc thợ khéo.'),
(2669, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 4, 'OT', 'Họ làm cho nó hai cái quai nối, được gắn vào hai đầu mút của nó.'),
(2670, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 5, 'OT', 'Và dây đai thắt trên áo ê-phót, ở phía trên, liền với nó, làm nguyên một miếng như công việc của ê-phót, bằng vàng, chỉ xanh, đỏ điều, đỏ sặm và chỉ gai mịn, y như Đức Giê-hô-va đã truyền dặn Môi-se.'),
(2671, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 6, 'OT', 'Họ làm những hòn ngọc đỏ, đóng viền bằng vàng, chạm khắc như ấn triện, theo tên các con trai của Y-sơ-ra-ên.'),
(2672, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 7, 'OT', 'Họ đặt hai viên đó trên hai cái đai vai của cái ê-phót, làm những viên ngọc kỷ niệm cho con cháu Y-sơ-ra-ên, y như lời Đức Giê-hô-va đã truyền cho Môi-se.'),
(2673, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 8, 'OT', 'Người đã làm bảng ê-phót bằng kỹ nghệ thợ khéo như công việc của ê-phót, bằng vàng, chỉ xanh, tím, đỏ điều và chỉ gai mịn đã xoắn.'),
(2674, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 9, 'OT', 'Bảng đeo ngực làm thành hình vuông, gấp đôi; dài một thước, rộng một thước.'),
(2675, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 10, 'OT', 'Họ làm đầy dẫy nó bằng bốn hàng đá: hàng thứ nhất là ngọc hồng ngọc, ngọc thạch anh, và ngọc lam bửu;'),
(2676, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 11, 'OT', 'và hàng thứ hai là ngọc thạch lục, ngọc lam và ngọc kim cương;'),
(2677, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 12, 'OT', 'Hàng thứ ba là ngọc hồng bửu, ngọc bạch mã não, và ngọc tử tinh.'),
(2678, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 13, 'OT', 'Hàng thứ tư là ngọc thạch anh vàng, ngọc mã não và ngọc bích; chúng được đính bằng những cái đai vàng với các đồ nhận của chúng.'),
(2679, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 14, 'OT', 'Mười hai viên ngọc mang tên của các con trai Y-sơ-ra-ên, mỗi viên khắc theo tên riêng của từng người, theo mười hai chi phái, như cách khắc dấu ấn.'),
(2680, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 15, 'OT', 'Họ làm các sợi dây chuyền bằng vàng ròng, chế bằng cách đánh sợi như dây, để gắn vào bảng đeo ngực.'),
(2681, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 16, 'OT', 'Họ làm hai cái móc vàng và hai cái vòng vàng, rồi đặt hai cái vòng ấy nơi hai đầu của bảng đeo ngực.'),
(2682, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 17, 'OT', 'Họ đặt hai cái móc vàng vào hai cái vòng đó, ở hai đầu của bảng quyết định.'),
(2683, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 18, 'OT', 'Hai đầu của hai dây chuyền, họ đặt vào hai cái móc, rồi đặt chúng trên hai vai của áo ê-phót, ở phía trước.'),
(2684, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 19, 'OT', 'Họ làm hai cái vòng vàng, rồi đặt vào hai đầu của bảng đeo ngực, ở mép của nó, phía bên trong về phía chiếc áo dài.'),
(2685, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 20, 'OT', 'Họ làm hai cái vòng vàng, rồi đặt chúng trên hai vai áo ê-phót, phía dưới, đằng trước, đối diện với chỗ nối, phía trên dây đai của áo ê-phót.'),
(2686, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 21, 'OT', 'Họ buộc bảng đeo ngực bằng những vòng của nó vào những vòng ê-phót bằng dây chỉ tím, để nó gắn trên đai ê-phót, hầu cho bảng đeo ngực không rời khỏi ê-phót, y như lời Đức Giê-hô-va đã truyền cho Môi-se.'),
(2687, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 22, 'OT', 'Họ làm áo dài của ê-phót bằng nghề dệt, toàn bằng màu xanh.'),
(2688, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 23, 'OT', 'Cổ áo ở giữa, như lỗ áo giáp, viền quanh cổ áo để khỏi rách.'),
(2689, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 24, 'OT', 'Họ làm những trái lựu bằng chỉ điều lam, tím sẫm và sợi chỉ đỏ điều, khâu nơi tà áo.'),
(2690, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 25, 'OT', 'Họ làm những chiếc chuông nhỏ bằng vàng ròng, rồi đặt những chiếc chuông nhỏ ấy xen giữa các trái lựu, vòng theo các vạt áo, xen giữa các trái lựu.'),
(2691, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 26, 'OT', 'Chuông nhỏ và trái lựu, chuông nhỏ và trái lựu, vòng theo chung quanh tà áo nơi phía dưới, để dùng vào việc phục vụ, y như lời Đức Giê-hô-va đã truyền cho Môi-se.'),
(2692, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 27, 'OT', 'Họ làm những chiếc áo trong bằng vải gai mịn, thợ dệt làm, cho A-rôn và các con trai người;'),
(2693, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 28, 'OT', 'và chiếc mũ bằng vải gai mịn, các đồ trang sức trên mũ bằng vải gai mịn, và quần lót bằng vải gai mịn xoắn tơ.'),
(2694, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 29, 'OT', 'Cái đai bằng vải gai mịn, màu lam, tím, điều, thêu theo kiểu dệt, y như Đức Giê-hô-va đã truyền cho Môi-se.'),
(2695, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 30, 'OT', 'Họ làm cái bảng thánh bằng vàng ròng, và ghi trên đó bằng chữ khắc như dấu ấn, rằng: Thánh dành cho Đức Giê-hô-va.'),
(2696, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 31, 'OT', 'Họ đặt trên đó một sợi dây bằng chỉ tía để buộc trên mũ từ phía trên, y như Đức Giê-hô-va đã truyền cho Môi-se.'),
(2697, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 32, 'OT', 'Vậy các công việc của nhà tạm, tức là hội mạc, đã được hoàn tất; dân Y-sơ-ra-ên đã làm mọi điều y như Đức Giê-hô-va đã truyền cho Môi-se, thì họ làm như vậy.'),
(2698, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 33, 'OT', 'Họ đem đền tạm đến cho Môi-se, tức là cái trại cùng với mọi đồ của nó, các nọc, các ván, cây xà ngang, các trụ và các đế lỗ.'),
(2699, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 34, 'OT', 'và cái màn che bằng da chiên đực nhuộm đỏ, và cái màn che bằng da thú mống, và cái màn che của bức rèm.'),
(2700, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 35, 'OT', 'rương bảng chứng cớ và các đòn khiêng của nó, cùng với nắp thi ân;'),
(2701, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 36, 'OT', 'cái bàn và mọi đồ dùng của bàn, cùng với các bánh trần thiết;'),
(2702, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 37, 'OT', 'bóng đèn bằng vàng ròng, các ngọn đèn của nó, các ngọn đèn được sắp đặt, và mọi đồ dùng của nó, cùng với dầu để thắp sáng,'),
(2703, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 38, 'OT', 'và cái bàn thờ bằng vàng, và dầu xức, và hương thơm, và cái màn ở cửa trại;'),
(2704, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 39, 'OT', 'bàn thờ bằng đồng và cái rá bằng đồng đi với bàn thờ, các đòn khiêng và mọi đồ dùng của nó, cái thùng nước và chân đỡ của nó;'),
(2705, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 40, 'OT', 'các bức màn hành lang, các trụ và bệ của nó, cái màn cửa hành lang, dây giằng và các cây nọc của nó, cùng với mọi đồ dùng phục vụ công việc của đền tạm, tức là Lều Hẹn;'),
(2706, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 41, 'OT', 'các áo lễ để thi hành chức vụ trong nơi thánh, các áo thánh cho A-rôn thầy tế lễ và các áo của các con trai người để làm thầy tế lễ.'),
(2707, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 42, 'OT', 'Y-sơ-ra-ên làm mọi công việc đó y như mọi điều Đức Giê-hô-va đã truyền cho Môi-se.'),
(2708, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 39, 43, 'OT', 'Môi-se xem xét toàn thể công việc, thấy họ đã làm y như Đức Giê-hô-va đã truyền dặn; và Môi-se chúc phước cho họ.'),
(2709, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(2710, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 2, 'OT', 'Ngày mồng một tháng giêng, ngươi sẽ dựng lên nhà tạm, tức là nhà tạm hội ngộ.'),
(2711, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 3, 'OT', 'Hãy đặt vào đó hòm bảng chứng, rồi lấy bức màn che phủ trên hòm ấy.'),
(2712, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 4, 'OT', 'Hãy đem bàn đến, bày biện các vật trên nó; hãy đem chân đèn đến, và thắp các ngọn đèn của nó.'),
(2713, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 5, 'OT', 'Hãy đặt bàn thờ bằng vàng để đốt hương trước hòm chứng, và treo màn ở cửa đền tạm.'),
(2714, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 6, 'OT', 'Hãy đặt bàn thờ của lễ thiêu trước lối vào nhà tạm, tức là trước cửa nhà tạm hội ngộ.'),
(2715, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 7, 'OT', 'Hãy đặt cái bồn giữa hội mạc và bàn thờ, rồi đổ nước vào đó.'),
(2716, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 8, 'OT', 'Lại đặt hành lang bao quanh và đặt tấm màn nơi cửa hành lang.'),
(2717, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 9, 'OT', 'Ngươi hãy lấy dầu xức mà xức đền tạm và tất cả những vật ở trong nó, và biệt riêng nó và tất cả các đồ dùng của nó ra thánh, thì nó sẽ là nơi thánh.'),
(2718, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 10, 'OT', 'Hãy xức dầu bàn thờ về của lễ thiêu và mọi đồ dùng của nó; rồi biệt bàn thờ ra thánh, thì bàn thờ sẽ trở nên nơi rất thánh.'),
(2719, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 11, 'OT', 'Hãy xức dầu cho cái thùng và cái chân đỡ thùng, rồi biệt riêng cái thùng ra thánh.'),
(2720, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 12, 'OT', 'Hãy dẫn A-rôn và các con trai người đến trước cửa hội mạc, rồi tắm các người đó trong nước.'),
(2721, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 13, 'OT', 'Ngươi hãy mặc các áo thánh cho A-rôn, xức dầu cho người và biệt người ra thánh, để người làm thầy tế lễ cho ta.'),
(2722, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 14, 'OT', 'Hãy dẫn các con trai người đến gần, rồi mặc cho họ những chiếc áo dài;'),
(2723, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 15, 'OT', 'Xức dầu cho họ như ngươi đã xức dầu cho cha họ, thì họ sẽ làm thầy tế lễ cho ta; và sự xức dầu cho họ sẽ là chức tế lễ đời đời trải qua các thế hệ của họ.'),
(2724, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 16, 'OT', 'Môi-se làm theo mọi điều Đức Giê-hô-va đã truyền cho người.'),
(2725, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 17, 'OT', 'Vào tháng giêng năm thứ hai, ngày mồng một tháng ấy, đền tạm đã được dựng lên.'),
(2726, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 18, 'OT', 'Môi-se dựng đền tạm, đặt các chân đế của nó, dựng các tấm ván của nó, đặt các thanh ngang của nó, và dựng các trụ của nó.'),
(2727, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 19, 'OT', 'Người trải mái che trên nơi tạm, rồi đặt lớp phủ mái che lên trên, phía trên cao, y như Đức Giê-hô-va đã truyền dặn Môi-se.'),
(2728, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 20, 'OT', 'Người lấy bảng chứng đưa vào trong hòm, đặt các đòn khiêng vào hòm, rồi đặt nắp thi ân lên trên hòm.'),
(2729, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 21, 'OT', 'Môi-se mang rương vào trong nhà tạm, đặt bức màn che chắn, rồi che phủ rương chứng ước lại, y như lời Đức Giê-hô-va đã truyền dạy Môi-se.'),
(2730, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 22, 'OT', 'Đặt cái bàn trong hội mạc, về phía bắc của đền tạm, ở bên ngoài bức màn;'),
(2731, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 23, 'OT', 'và bày bánh trên đó trước mặt Đức Giê-hô-va, như Đức Giê-hô-va đã truyền cho Môi-se.'),
(2732, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 24, 'OT', 'Và đặt chân đèn trong nhà hội, đối diện cái bàn, ở bên hông đền thờ, về phía nam.'),
(2733, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 25, 'OT', 'Người thắp các ngọn đèn trước mặt Đức Giê-hô-va, y như Đức Giê-hô-va đã truyền cho Môi-se.'),
(2734, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 26, 'OT', 'Đặt bàn thờ bằng vàng trong hội mạc, trước bức màn.'),
(2735, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 27, 'OT', 'Người xông hương trên đó bằng hương thơm, y như Đức Giê-hô-va đã truyền cho Môi-se.'),
(2736, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 28, 'OT', 'Người đặt bức màn nơi cửa đền tạm.'),
(2737, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 29, 'OT', 'Đặt bàn thờ của lễ thiêu nơi cửa Nhà tạm, tức là lều hội ngộ, rồi dâng trên đó của lễ thiêu và của lễ chay, y như Đức Giê-hô-va đã truyền cho Môi-se.'),
(2738, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 30, 'OT', 'Đặt cái thùng giữa hội mạc và bàn thờ, rồi đổ nước vào đó để tắm rửa.'),
(2739, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 31, 'OT', 'Môi-se và A-rôn cùng các con trai người rửa tay và chân mình trong đó.'),
(2740, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 32, 'OT', 'Khi họ vào hội mạc và đến gần bàn thờ thì phải rửa mình, y như điều Đức Giê-hô-va đã truyền cho Môi-se.'),
(2741, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 33, 'OT', 'Rồi người dựng hàng rào chung quanh nơi ở thánh và bàn thờ, và đặt màn cửa nơi cửa hàng rào; và Môi-se làm xong công việc.'),
(2742, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 34, 'OT', 'Và đám mây bao phủ hội mạc, và sự vinh hiển của Đức Giê-hô-va đầy dẫy đền tạm.'),
(2743, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 35, 'OT', 'Môi-se không thể vào trong hội mạc, vì mây đã đậu trên đó, và sự vinh hiển của Đức Giê-hô-va đầy dẫy đền tạm.'),
(2744, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 36, 'OT', 'Trong mọi cuộc hành trình của dân Y-sơ-ra-ên, khi đám mây từ đền tạm cất lên, thì dân Y-sơ-ra-ên sẽ ra đi.'),
(2745, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 37, 'OT', 'Còn nếu đám mây không lên, thì họ cũng không đi, cho đến ngày nào đám mây lên.'),
(2746, 2, 'GOI_vi', 'GOI_vi', 'vi', 'EXO', 40, 38, 'OT', 'Vì mây của Đức Giê-hô-va ở trên đền tạm ban ngày, và lửa ở trong nó ban đêm, trước mắt mọi người Y-sơ-ra-ên, trong mọi nơi họ dừng chân.'),
(2747, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 1, 1, 'OT', 'Đức Giê-hô-va gọi Môi-se, và phán cùng người từ trong hội mạc rằng:'),
(2748, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 1, 2, 'OT', 'Hãy nói cùng con cái Y-sơ-ra-ên rằng: Khi một người trong vòng các ngươi dâng của lễ cho Đức Giê-hô-va, thì phải dâng từ súc vật, từ bò hoặc từ chiên; các ngươi sẽ dâng của lễ các ngươi.'),
(2749, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 1, 3, 'OT', 'Nếu của lễ người đó dâng là của lễ thiêu lấy từ bò, thì phải dâng con đực không tật nguyền; người ấy sẽ dâng nó tại cửa Nhà Hội Ngộ, để được đẹp lòng trước mặt Đức Giê-hô-va.'),
(2750, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 1, 4, 'OT', 'Người sẽ đặt tay mình trên đầu con vật thiêu tế, và con vật ấy sẽ được chấp nhận vì người, để chuộc tội cho người.'),
(2751, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 1, 5, 'OT', 'Người sẽ giết con bò đực trước mặt Đức Giê-hô-va, rồi các con trai A-rôn, tức những thầy tế lễ, sẽ dâng huyết lên và rảy huyết chung quanh bàn thờ, là nơi ở cửa Hội mạc.'),
(2752, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 1, 6, 'OT', 'Sau đó, người ấy phải lột da của của lễ toàn thiêu và chặt thịt ra từng phần.'),
(2753, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 1, 7, 'OT', 'Các con trai của A-rôn, các thầy tế lễ, sẽ đặt lửa trên bàn thờ và xếp củi trên lửa ấy.'),
(2754, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 1, 8, 'OT', 'Các con trai của A-rôn, các thầy tế lễ, sẽ sắp đặt những miếng thịt, đầu và mỡ lên trên các khúc gỗ nằm trên lửa, ở trên bàn thờ.'),
(2755, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 1, 9, 'OT', 'Người sẽ lấy nước rửa bộ lòng và các chân, rồi thầy tế lễ sẽ dâng toàn thể làm của lễ thiêu trên bàn thờ, tức một của lễ bằng lửa, có mùi thơm vừa lòng Đức Giê-hô-va.'),
(2756, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 1, 10, 'OT', 'Nếu lễ vật của người ấy là của lễ thiêu từ chiên hoặc dê, thì phải dâng một con đực không tật xấu,'),
(2757, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 1, 11, 'OT', 'Sẽ giết nó về phía bắc bàn thờ, trước mặt Đức Giê-hô-va; rồi các con trai A-rôn, là những thầy tế lễ, sẽ rảy huyết nó chung quanh bàn thờ.'),
(2758, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 1, 12, 'OT', 'xả thịt ra từng miếng, và đặt đầu nó cùng với mỡ nó; thầy tế lễ sẽ chất các phần đó lên các khúc củi đã đặt trên lửa tại bàn thờ.'),
(2759, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 1, 13, 'OT', 'Bộ lòng và chân sẽ rửa bằng nước; thầy tế lễ sẽ dâng và thiêu trọn tế vật trên bàn thờ; ấy là của lễ thiêu, một của lễ dùng lửa dâng lên, có mùi thơm cho Đức Giê-hô-va.'),
(2760, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 1, 14, 'OT', 'Nếu của lễ thiêu người ấy dâng cho Đức Giê-hô-va là từ loài chim, thì phải dâng chim cu hay bồ câu con làm của lễ mình.'),
(2761, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 1, 15, 'OT', 'Thầy tế lễ sẽ dâng nó đến bàn thờ, vặn đứt đầu nó, rồi thiêu trên bàn thờ; huyết của nó sẽ được rảy nơi thành bàn thờ.'),
(2762, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 1, 16, 'OT', 'Người ấy sẽ bỏ đi cái mào của nó cùng với lông tơ, rồi ném gần bàn thờ về phía đông, là nơi đổ tro.'),
(2763, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 1, 17, 'OT', 'xé nó ra tại hai cánh, nhưng không tách rời, rồi thầy tế lễ sẽ thiêu trên bàn thờ, trên củi đang cháy; ấy là của lễ thiêu, một của lễ dùng lửa dâng lên, có mùi thơm cho Đức Giê-hô-va.'),
(2764, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 2, 1, 'OT', 'Khi một người dâng của lễ chay cho Đức Giê-hô-va, thì của lễ người phải bằng bột mịn; người phải đổ dầu lên và đặt nhựa trầm hương lên trên.'),
(2765, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 2, 2, 'OT', 'Người sẽ đem đến cho các con trai A-rôn, các thầy tế lễ; thầy tế lễ sẽ lấy một nắm đầy bột từ thúng và dầu của nó, cùng với toàn thể nhũ hương trên nó, rồi thầy tế lễ sẽ đốt phần kỷ niệm ấy trên bàn thờ làm của lễ thiêu, một mùi thơm làm vừa lòng Đức Giê-hô-va.'),
(2766, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 2, 3, 'OT', 'Phần còn lại của lễ chay phải thuộc về A-rôn và các con trai người, là vật chí thánh trong các của lễ dùng lửa dâng cho Đức Giê-hô-va.'),
(2767, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 2, 4, 'OT', 'Khi ngươi dâng của lễ chay là vật nướng bằng lò, phải dùng bột mịn làm những ổ bánh không men trộn dầu, và những bánh mỏng không men phết dầu.'),
(2768, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 2, 5, 'OT', 'Nếu của lễ chay ngươi dâng là thứ nướng trong chảo, thì phải là bột mịn trộn dầu, không men.'),
(2769, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 2, 6, 'OT', 'Bẻ nhỏ miếng ra, rồi chế dầu lên trên; ấy là lễ chay.'),
(2770, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 2, 7, 'OT', 'Nếu của lễ ngươi dâng là lễ chay nấu trong chảo, thì phải làm bằng bột mịn trộn dầu.'),
(2771, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 2, 8, 'OT', 'Ngươi sẽ đem dâng cho Đức Giê-hô-va của lễ chay đã được chế biến theo cách nầy, rồi thầy tế lễ sẽ dâng nó và mang đến bàn thờ.'),
(2772, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 2, 9, 'OT', 'Thầy tế lễ sẽ lấy phần nhớ lại từ của lễ chay, đem thiêu trên bàn thờ làm của lễ dùng lửa, một mùi thơm vừa lòng cho Đức Giê-hô-va.'),
(2773, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 2, 10, 'OT', 'Phần còn lại của lễ chay sẽ thuộc về A-rôn và các con trai người; ấy là vật chí thánh trong các của lễ dùng lửa dâng cho Đức Giê-hô-va.'),
(2774, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 2, 11, 'OT', 'Mọi của lễ chay mà các ngươi dâng cho Đức Giê-hô-va không được làm men; vì các ngươi không được đốt lên làm của lễ dùng lửa dâng cho Đức Giê-hô-va bất kỳ thứ gì có men hoặc mật.'),
(2775, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 2, 12, 'OT', 'Các ngươi phải dâng những vật đó cho Đức Giê-hô-va làm của lễ đầu mùa; nhưng không được đem lên bàn thờ để làm mùi thơm vừa lòng Đức Giê-hô-va.'),
(2776, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 2, 13, 'OT', 'Mọi của lễ thiêu đốt về của lễ chay ngươi phải nêm muối; ngươi không được để thiếu muối của giao ước Đức Chúa Trời ngươi trên của lễ chay ngươi; trên mọi của lễ ngươi phải dâng muối.'),
(2777, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 2, 14, 'OT', 'Nếu ngươi dâng lễ vật chay đầu mùa cho Đức Giê-hô-va, thì phải dâng lúa mới rang trong lửa, hột lúa mới giã ra, làm lễ vật chay đầu mùa của ngươi.'),
(2778, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 2, 15, 'OT', 'Đổ dầu trên nó và đặt trên nó một ít nhũ hương; ấy là lễ chay.'),
(2779, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 2, 16, 'OT', 'Thầy tế lễ sẽ đốt phần kỷ niệm của nó, tức là phần nhỏ từ bột mịn và dầu cùng với toàn thể nhũ hương, làm của lễ thiêu dâng cho Đức Giê-hô-va.'),
(2780, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 3, 1, 'OT', 'Nếu của lễ người đó dâng là của lễ thù ân, và người đó dâng từ bò, thì dù con đực hay con cái, phải dâng không tì vít trước mặt Đức Giê-hô-va.'),
(2781, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 3, 2, 'OT', 'Người sẽ đặt tay mình trên đầu sinh lễ của mình, rồi giết nó tại cửa Lều Hội Kiến; các con trai A-rôn, các thầy tế lễ, sẽ rảy huyết nó chung quanh bàn thờ.'),
(2782, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 3, 3, 'OT', 'Người sẽ dâng từ của lễ thù ân làm của lễ dùng lửa dâng cho Đức Giê-hô-va, mỡ che phủ bộ lòng và mọi mỡ trên bộ lòng.'),
(2783, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 3, 4, 'OT', 'hai trái cật và mỡ trên hai trái cật ở gần hông, cùng với cái màng nơi gan, gần hai trái cật, thì phải gỡ ra.'),
(2784, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 3, 5, 'OT', 'Các con trai A-rôn sẽ xông nó trên bàn thờ, trên của lễ thiêu đã đặt trên củi cháy lửa; của lễ dùng lửa, mùi thơm vừa lòng Đức Giê-hô-va.'),
(2785, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 3, 6, 'OT', 'Nếu của lễ người đó dâng cho Đức Giê-hô-va là của lễ thù ân bằng chiên, thì phải dâng con đực hay con cái, không tì vít.'),
(2786, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 3, 7, 'OT', 'Nếu người dâng chiên con làm của lễ mình, thì phải dâng nó lên trước mặt Đức Giê-hô-va.'),
(2787, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 3, 8, 'OT', 'đặt tay mình trên đầu của lễ, rồi sát tế nó trước mặt nhà hội; các con trai của A-rôn sẽ rảy huyết nó chung quanh trên bàn thờ.'),
(2788, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 3, 9, 'OT', 'Từ của lễ thù hoà, phải dâng của lễ dùng lửa dâng cho Đức Giê-hô-va, mỡ cái đuôi trọn vẹn, chặt gần xương sống; và mỡ che phủ bộ lòng, cùng mọi mỡ trên bộ lòng.'),
(2789, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 3, 10, 'OT', 'hai trái cật, và mỡ trên hai trái cật ở gần hông, cùng với tấm màng trên gan, gần hai trái cật, thì phải gỡ ra.'),
(2790, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 3, 11, 'OT', 'Thầy tế lễ sẽ đốt trên bàn thờ làm của lễ dùng lửa dâng cho Đức Giê-hô-va.'),
(2791, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 3, 12, 'OT', 'Nếu của lễ người đó là một con dê, thì phải dâng nó lên trước mặt Đức Giê-hô-va.'),
(2792, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 3, 13, 'OT', 'đặt tay mình trên đầu con sinh ấy, rồi giết nó trước nhà Đức hội mạc; các con trai A-rôn sẽ rảy huyết nó chung quanh trên bàn thờ.'),
(2793, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 3, 14, 'OT', 'Và người phải dâng từ nó của lễ dùng lửa dâng cho Đức Giê-hô-va, là lớp mỡ che phủ bộ lòng và mọi mỡ trên bộ lòng.'),
(2794, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 3, 15, 'OT', 'hai trái cật, và mỡ trên hai trái cật ở gần hông, cùng với tấm màng trên gan, gần hai trái cật, thì phải gỡ ra.'),
(2795, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 3, 16, 'OT', 'Thầy tế lễ sẽ xông các món đó trên bàn thờ làm của lễ dùng lửa dâng lên Đức Giê-hô-va, có mùi thơm vừa lòng; mọi phần mỡ đều thuộc về Đức Giê-hô-va.'),
(2796, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 3, 17, 'OT', 'Là một luật lệ đời đời cho các dòng dõi các ngươi, trong mọi nơi ở của các ngươi: mọi mỡ và mọi huyết, các ngươi không được ăn.'),
(2797, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(2798, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 2, 'OT', 'Hãy nói cùng con cái Y-sơ-ra-ên rằng: Một người nào đó nếu lỡ phạm tội cách vô ý trong bất kỳ điều răn nào của Đức Giê-hô-va mà không nên làm, và làm một trong những điều ấy;'),
(2799, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 3, 'OT', 'Nếu thầy tế lễ đã được xức dầu mà phạm tội, gây nên sự phạm tội cho dân sự, thì vì tội mình đã phạm, người ấy phải dâng cho Đức Giê-hô-va một con bò đực tơ không tì vít làm của lễ chuộc tội.'),
(2800, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 4, 'OT', 'Người sẽ dẫn con bò đực đến trước cửa Hội mạc, vào trước mặt Đức Giê-hô-va, đặt tay mình trên đầu con bò đực, rồi giết con bò đực trước mặt Đức Giê-hô-va.'),
(2801, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 5, 'OT', 'Vị thầy tế lễ được xức dầu sẽ lấy huyết con bò và đem huyết ấy vào trong hội mạc,'),
(2802, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 6, 'OT', 'và thầy tế lễ sẽ lấy ngón tay mình nhúng vào huyết, rồi rảy huyết bảy lần trước mặt Đức Giê-hô-va, về phía trước mặt bức màn nơi thánh.'),
(2803, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 7, 'OT', 'Thầy tế lễ sẽ lấy huyết bôi trên các sừng của bàn thờ xông hương bằng vàng, ở trước mặt Đức Giê-hô-va, trong nơi thánh; và đổ toàn thể huyết con bò tơ nơi chân bàn thờ về của lễ thiêu, để trước cửa hội mạc.'),
(2804, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 8, 'OT', 'Người phải lấy hết mỡ con bò dùng làm của lễ chuộc tội, tức là mỡ phủ phủ tạng và hết thảy mỡ trên tạng.'),
(2805, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 9, 'OT', 'hai trái cật và mỡ trên hai trái cật ở gần hai hông, cùng với màng trên gan, gần hai trái cật, thì phải gỡ ra'),
(2806, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 10, 'OT', 'như cách lấy các phần của con bò dùng làm của lễ an hoà; thầy tế lễ sẽ đốt những phần đó trên bàn thờ của của lễ thiêu.'),
(2807, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 11, 'OT', 'Da con bò, và toàn thể thịt nó, đầu nó, các chân nó, lòng nó và phân nó,'),
(2808, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 12, 'OT', 'Mang toàn bộ con bò ra ngoài trại, đến một nơi sạch sẽ, là chỗ đổ tro, rồi thiêu nó trên củi bằng lửa; phải thiêu nó tại chỗ đổ tro.'),
(2809, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 13, 'OT', 'Nếu toàn thể hội chúng Y-sơ-ra-ên lầm lỡ, và điều đó bị giấu khỏi mắt của cộng đồng, rồi họ làm một trong các điều răn mà Đức Giê-hô-va đã phán không được làm, thì họ sẽ mang tội.'),
(2810, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 14, 'OT', 'Khi tội lỗi đã phạm được tiết lộ, thì hội chúng phải dâng một con bò đực tơ làm của lễ chuộc tội, và đem nó đến trước lều hội ngộ.'),
(2811, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 15, 'OT', 'Các trưởng lão của hội chúng phải đặt tay mình trên đầu con bò đực trước mặt Đức Giê-hô-va, rồi giết con bò đực trước mặt Đức Giê-hô-va.'),
(2812, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 16, 'OT', 'và thầy tế lễ đã được xức dầu phải đem huyết con bò vào trong hội mạc'),
(2813, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 17, 'OT', 'và thầy tế lễ lấy ngón tay mình, nhúng vào huyết, rồi rảy bảy lần trước mặt Đức Giê-hô-va, đối ngang mặt bức màn.'),
(2814, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 18, 'OT', 'Người sẽ lấy huyết bôi trên các sừng của bàn thờ trước mặt Đức Giê-hô-va, là bàn thờ ở trong hội mạc; và đổ toàn bộ huyết xuống chân bàn thờ về của lễ thiêu, là bàn thờ ở trước cửa hội mạc.'),
(2815, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 19, 'OT', 'Người phải lấy hết mỡ của nó mà đốt trên bàn thờ.'),
(2816, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 20, 'OT', 'Làm cho con bò như cách đã làm cho con bò dùng về lễ chuộc tội; thầy tế lễ sẽ làm lễ chuộc tội cho họ, thì họ sẽ được tha.'),
(2817, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 21, 'OT', 'Người phải đem con bò ra ngoài trại, thiêu nó như thiêu con bò cái đầu tiên; ấy là của lễ chuộc tội cho hội chúng.'),
(2818, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 22, 'OT', 'Khi một quan trưởng phạm tội, vì lầm lỡ làm một trong các điều răn của Đức Giê-hô-va là Đức Chúa Trời mình, là những điều không nên làm, thì người ấy mắc tội.'),
(2819, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 23, 'OT', 'hoặc người ta tỏ cho người ấy biết tội mà người ấy đã phạm, thì người ấy phải đem của lễ mình là một con dê đực không tật nguyền.'),
(2820, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 24, 'OT', 'Người ấy đặt tay mình trên đầu con dê đực, rồi giết nó tại nơi giết con sinh làm của lễ thiêu trước mặt Đức Giê-hô-va; ấy là của lễ chuộc tội.'),
(2821, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 25, 'OT', 'Thầy tế lễ phải lấy máu sinh tế chuộc tội bằng ngón tay mình, rồi bôi lên các sừng của bàn thờ về lễ thiêu; còn huyết thì đổ xuống chân bàn thờ về lễ thiêu.'),
(2822, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 26, 'OT', 'Mọi mỡ của nó phải đốt trên bàn thờ, như mỡ của lễ thù ân; thầy tế lễ sẽ làm lễ chuộc tội cho người ấy vì tội lầm lỗi, và người ấy sẽ được tha.'),
(2823, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 27, 'OT', 'Nếu một người nào trong dân chúng lỡ phạm tội cách vô ý, khi làm một điều trong các điều răn của Đức Giê-hô-va mà không nên làm, thì người đó sẽ mắc tội.'),
(2824, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 28, 'OT', 'hoặc người ta tỏ cho người đó biết tội mình đã phạm, thì người phải dâng của lễ mình là một con dê cái không tì vít, dùng làm của lễ chuộc tội cho tội mà người đó đã phạm'),
(2825, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 29, 'OT', 'đặt tay mình trên đầu con vật làm của lễ chuộc tội, rồi giết con vật chuộc tội tại nơi làm của lễ thiêu.'),
(2826, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 30, 'OT', 'Thầy tế lễ sẽ lấy máu bằng ngón tay mình, nhỏ lên các sừng của bàn thờ về của lễ thiêu, và đổ toàn bộ máu dưới chân bàn thờ.'),
(2827, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 31, 'OT', 'rồi, gỡ hết mỡ của nó như cách gỡ mỡ khỏi của lễ thù ân, thầy tế lễ sẽ đốt trên bàn thờ làm của lễ thiêu có mùi thơm cho Đức Giê-hô-va. Thầy tế lễ sẽ làm lễ chuộc tội cho người ấy, thì người ấy sẽ được tha.'),
(2828, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 32, 'OT', 'Nếu người dâng chiên con làm của lễ chuộc tội, thì phải dâng một con cái không tật nguyền.'),
(2829, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 33, 'OT', 'đặt tay mình trên đầu con vật làm của lễ chuộc tội, rồi giết nó làm của lễ chuộc tội tại nơi giết con vật làm của lễ thiêu.'),
(2830, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 34, 'OT', 'Thầy tế lễ sẽ lấy huyết của của lễ chuộc tội bằng ngón tay mình, rồi bôi lên các sừng của bàn thờ về của lễ thiêu, và đổ toàn bộ huyết đó xuống chân bàn thờ.'),
(2831, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 4, 35, 'OT', 'và phải gỡ bỏ hết mỡ ra như cách gỡ mỡ của chiên con nơi lễ thù ân; thầy tế lễ sẽ đốt những thứ ấy trên bàn thờ, làm của lễ dùng lửa dâng lên Đức Giê-hô-va. Thầy tế lễ sẽ làm lễ chuộc tội cho người ấy vì tội mà người đã phạm, thì người ấy sẽ được tha.'),
(2832, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 5, 1, 'OT', 'Nếu một người nào phạm tội mà nghe tiếng thề, và người ấy là nhân chứng, hoặc đã thấy hoặc đã biết điều gì, mà không chịu làm chứng, thì phải mang tội mình.'),
(2833, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 5, 2, 'OT', 'Hoặc một người nào đụng đến bất cứ vật gì ô uế, hoặc xác chết của thú dữ không sạch, hoặc xác chết của súc vật không sạch, hoặc xác chết của loài bò sát không sạch, mà người ấy không biết, thì người ấy bị ô uế và mắc tội.'),
(2834, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 5, 3, 'OT', 'Hoặc nếu người nào chạm vào sự ô uế của loài người, bất cứ sự ô uế nào khiến người ấy bị ô uế, mà không biết đến, nhưng rồi sau đó nhận biết, thì người ấy mang tội.'),
(2835, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 5, 4, 'OT', 'Hoặc có người nào thề thốt bằng môi miệng để làm điều ác hay làm điều thiện, bất cứ điều gì người ta thề thốt; rồi sau đó quên mất, nhưng khi biết lại thì mắc tội về một trong những điều ấy.'),
(2836, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 5, 5, 'OT', 'Khi nào người ấy mắc tội về một trong các điều nầy, phải thú nhận tội mình đã phạm về điều đó.'),
(2837, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 5, 6, 'OT', 'Người ấy phải đem của lễ chuộc tội vì tội mình đã phạm đến Đức Giê-hô-va, một con cái trong bầy chiên, hoặc chiên cái hoặc dê cái; thầy tế lễ sẽ làm lễ chuộc tội thay cho người ấy vì tội đã phạm.'),
(2838, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 5, 7, 'OT', 'Nếu tay người đó không đủ tiền để dâng một chiên cái, thì phải dâng của lễ chuộc tội mình đã phạm cho Đức Giê-hô-va hai con chim gò hoặc hai con bồ câu con: một con làm của lễ chuộc tội, và một con làm của lễ thiêu.'),
(2839, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 5, 8, 'OT', 'Người ấy sẽ đem cặp đó đến cho thầy tế lễ; thầy tế lễ sẽ dâng con dùng làm của lễ chuộc tội trước tiên, rồi bẻ đầu gần phía cổ, nhưng không được cắt lìa ra.'),
(2840, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 5, 9, 'OT', 'Rồi rảy huyết của của lễ chuộc tội lên vách bàn thờ; huyết còn lại thì đổ nơi chân bàn thờ; ấy là của lễ chuộc tội.'),
(2841, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 5, 10, 'OT', 'Còn con thứ hai, thì phải dùng làm của lễ thiêu theo như luật định; và thầy tế lễ sẽ làm lễ chuộc tội cho người ấy về tội mà người đã phạm, thì người ấy sẽ được tha.'),
(2842, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 5, 11, 'OT', 'Nếu tay người đó không đủ sức mang hai con chim cu hoặc hai con bồ câu con, thì phải dâng của lễ mình đã phạm tội, là một phần mười ê-pha bột lọc làm của lễ chuộc tội; không được đổ dầu trên đó, cũng không được rắc nhũ hương trên đó, vì là của lễ chuộc tội.'),
(2843, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 5, 12, 'OT', 'Người ấy sẽ đem bột đó đến cho thầy tế lễ; thầy tế lễ sẽ lấy đầy một nắm tay làm phần tưởng nhớ, rồi đốt trên bàn thờ như của lễ thiêu đốt dâng cho Đức Giê-hô-va: ấy là của lễ chuộc tội.'),
(2844, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 5, 13, 'OT', 'Thầy tế lễ sẽ làm lễ chuộc tội thay cho người ấy về tội lỗi mà người ấy đã phạm về một trong những điều đó, thì người ấy sẽ được tha thứ; và phần của lễ chay còn lại sẽ thuộc về thầy tế lễ như lễ chay vậy.'),
(2845, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 5, 14, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(2846, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 5, 15, 'OT', 'Khi một người nào phạm tội bất trung, vô ý làm điều sai trái đối với các vật thánh của Đức Giê-hô-va, thì phải mang đến cho Đức Giê-hô-va một của lễ chuộc tội là một con chiên đực không tật tật từ bầy chiên, theo giá trị bằng bạc siếc-lơ, tùy theo siếc-lơ của đền thánh.'),
(2847, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 5, 16, 'OT', 'Người ấy phải đền bù phần mình phạm đến nơi thánh, lại phải thêm một phần năm giá trị nữa, rồi giao cho thầy tế lễ. Thầy tế lễ sẽ chuộc tội cho người ấy bằng con chiên đực về của lễ chuộc tội, thì người ấy sẽ được tha thứ.'),
(2848, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 5, 17, 'OT', 'Nếu một người nào phạm một trong các điều răn của Đức Giê-hô-va mà không nên làm, dù không biết, thì người đó sẽ mắc lỗi và mang lấy tội mình.'),
(2849, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 5, 18, 'OT', 'Người ấy phải dẫn một con chiên đực không tật nguyền từ bầy chiên, tùy theo giá ngươi định, dâng cho thầy tế lễ làm của lễ chuộc tội; thầy tế lễ sẽ làm lễ chuộc tội thay cho người ấy vì sự lầm lỗi mà người đã phạm nhưng không hay biết, và người ấy sẽ được tha thứ.'),
(2850, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 5, 19, 'OT', 'Người ấy đã phạm tội; thật đã phạm tội cùng Đức Giê-hô-va.'),
(2851, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 6, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(2852, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 6, 2, 'OT', 'Người nào phạm tội, làm điều gian ác phạm đến Đức Giê-hô-va và nói dối người đồng loại mình về vật được giao giữ, hoặc về sự ủy thác, hoặc về của cướp đoạt, hoặc về việc hà hiếp người đồng loại mình;'),
(2853, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 6, 3, 'OT', 'hoặc tìm thấy của đánh mất mà chối bỏ, lại còn chỉ Đức Giê-hô-va mà thề dối, về bất cứ việc gì mà loài người phạm tội mà phạm phải;'),
(2854, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 6, 4, 'OT', 'Khi nào người đó phạm tội và mắc tội, thì phải hoàn trả vật mình đã cướp lấy, hoặc vật mình đã ức hiếp chiếm đoạt, hoặc vật gửi giữ mà người ta đã giao cho mình, hoặc vật thất lạc mà người đó đã tìm thấy.'),
(2855, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 6, 5, 'OT', 'hoặc về bất cứ điều gì mà người ấy đã thề dối; người ấy phải bồi thường nguyên cả giá trị và thêm một phần năm nữa, giao cho chủ vật đó vào ngày người ấy dâng của lễ chuộc tội.'),
(2856, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 6, 6, 'OT', 'người ấy phải mang của lễ chuộc tội mình là một con chiên đực không tật nguyền từ bầy chiên, tùy theo sự đánh giá của ngươi, mà dâng cho Đức Giê-hô-va, đến thầy tế lễ;'),
(2857, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 6, 7, 'OT', 'Thầy tế lễ sẽ làm lễ chuộc tội cho người ấy trước mặt Đức Giê-hô-va, thì người ấy sẽ được tha thứ vì bất cứ điều gì trong những điều mà người ấy đã làm để mắc tội.'),
(2858, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 6, 8, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(2859, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 6, 9, 'OT', 'Hãy truyền cho A-rôn và các con trai người rằng: Đây là luật lệ về lễ thiêu: chính lễ thiêu ấy phải ở trên đống lửa tại bàn thờ suốt đêm cho đến sáng, và lửa trên bàn thờ phải được duy trì cháy luôn.'),
(2860, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 6, 10, 'OT', 'Thầy tế lễ phải mặc áo vải gai và mặc quần vải gai che thân mình, rồi xúc tro mà lửa đã thiêu của lễ thiêu trên bàn thờ, và đặt bên cạnh bàn thờ.'),
(2861, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 6, 11, 'OT', 'cởi bỏ các áo xống mình ra, mặc các áo xống khác, rồi đem tro đi ra ngoài trại quân, đổ tại một nơi thanh sạch.'),
(2862, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 6, 12, 'OT', 'Lửa trên bàn thờ phải được nhóm lên, không được để tắt; mỗi buổi sáng thầy tế lễ sẽ chất củi lên trên, dọn của lễ thiêu lên và đốt những phần mỡ của các của lễ thù ân trên đó.'),
(2863, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 6, 13, 'OT', 'Lửa phải hằng cháy trên bàn thờ, không được tắt.'),
(2864, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 6, 14, 'OT', 'Đây là luật về lễ chay: các con trai A-rôn phải mang lễ vật ấy đến trước mặt Đức Giê-hô-va, tại mặt bàn thờ.'),
(2865, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 6, 15, 'OT', 'Người sẽ lấy một nắm bột lọc của lễ chay và dầu của nó, cùng toàn thể nhũ hương trên lễ chay, mà đốt trên bàn thờ làm mùi thơm làm kỷ niệm cho Đức Giê-hô-va.'),
(2866, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 6, 16, 'OT', 'Phần còn sót lại, A-rôn và các con trai người sẽ ăn, phải ăn không men tại một nơi thánh; họ sẽ ăn nó trong hành lang của hội mạc.'),
(2867, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 6, 17, 'OT', 'Đừng nướng phần của họ đã cho ta từ của lễ dùng lửa với men; ấy là vật chí thánh, như của lễ chuộc tội và của lễ chuộc sự mắc lỗi.'),
(2868, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 6, 18, 'OT', 'Mọi người nam trong vòng con cái A-rôn sẽ ăn; ấy là luật lệ đời đời cho các dòng dõi các ngươi về những của lễ dùng lửa dâng cho Đức Giê-hô-va; bất cứ ai đụng đến các của lễ đó sẽ nên thánh.'),
(2869, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 6, 19, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(2870, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 6, 20, 'OT', 'Đây là của lễ mà A-rôn và các con trai người phải dâng cho Đức Giê-hô-va trong ngày chịu xức dầu: một phần mười ê-pha bột lọc làm của lễ chay mãi mãi; phân nửa vào buổi sáng và phân nửa vào buổi chiều.'),
(2871, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 6, 21, 'OT', 'Trên cái chảo trộn dầu, ngươi phải dâng miếng bánh mì đã chiên, tức của lễ chay cắt ra từng miếng, làm mùi thơm vừa lòng Đức Giê-hô-va.'),
(2872, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 6, 22, 'OT', 'Con trai nào của A-rôn được xức dầu thay người làm thầy tế lễ phải thực hiện điều đó; luật lệ đời đời trước mặt Đức Giê-hô-va, phải thiêu đốt trọn vẹn.'),
(2873, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 6, 23, 'OT', 'Mọi lễ vật chay của thầy tế lễ phải được thiêu hủy trọn vẹn, không được ăn.'),
(2874, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 6, 24, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(2875, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 6, 25, 'OT', 'Hãy nói với A-rôn và các con trai người rằng: Đây là luật lệ về của lễ chuộc tội: Tại nơi giết của lễ thiêu, thì phải giết của lễ chuộc tội trước mặt Đức Giê-hô-va; ấy là vật chí thánh.'),
(2876, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 6, 26, 'OT', 'Thầy tế lễ đã chuộc tội cho người ấy phải ăn của lễ nầy tại một nơi thánh, tức là trong hành lang của hội mạc.'),
(2877, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 6, 27, 'OT', 'Mọi vật nào chạm vào thịt của nó sẽ nên thánh; và nếu máu của nó văng trên một cái áo nào, thì cái áo đó phải giặt trong một nơi thánh.'),
(2878, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 6, 28, 'OT', 'Nồi đất nào dùng để nấu thịt ấy phải đập bể đi; còn nếu nồi đồng dùng để nấu thì phải cạo sạch và rửa bằng nước.'),
(2879, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 6, 29, 'OT', 'Mọi người nam trong các thầy tế lễ sẽ ăn nó; ấy là vật chí thánh.'),
(2880, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 6, 30, 'OT', 'Mọi sinh tế chuộc tội mà huyết của nó sẽ được mang vào trong hội mạc để làm lễ chuộc tội nơi nơi thánh thì không được phép ăn; phải thiêu hủy nó bằng lửa.'),
(2881, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 1, 'OT', 'Đây là luật về của lễ chuộc tội: vật đó là một vật chí thánh.'),
(2882, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 2, 'OT', 'Tại nơi người ta sát tế của lễ thiêu, thì phải sát tế của lễ chuộc tội; và huyết nó sẽ rưới chung quanh trên bàn thờ.'),
(2883, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 3, 'OT', 'Dâng hết thảy mỡ của nó, đuôi và mỡ che phủ lòng.'),
(2884, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 4, 'OT', 'hai trái cật và mỡ trên hai trái cật, mỡ trên cạnh hông, và cái màng trên gan, gần hai trái cật, người ta sẽ gỡ ra.'),
(2885, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 5, 'OT', 'Thầy tế lễ sẽ đốt những thứ ấy trên bàn thờ làm của lễ thiêu khói dâng cho Đức Giê-hô-va; ấy là của lễ chuộc tội.'),
(2886, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 6, 'OT', 'Mọi người nam trong các thầy tế lễ sẽ ăn; phải ăn tại nơi thánh; vì đó là vật thánh, tức vật chí thánh.'),
(2887, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 7, 'OT', 'Của lễ chuộc tội và của lễ chuộc sự mắc lỗi đều chịu một luật lệ như nhau; thầy tế lễ nào dùng của lễ ấy để làm lễ chuộc tội thì của lễ ấy sẽ thuộc về người ấy.'),
(2888, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 8, 'OT', 'Thầy tế lễ dâng của lễ thiêu cho người nào, thì miếng da con sinh dùng làm của lễ thiêu mà người ấy đã dâng sẽ thuộc về thầy tế lễ ấy.'),
(2889, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 9, 'OT', 'Mọi lễ vật chay nào được nướng trong lò, hoặc làm bằng chảo, hoặc trên vỉ, thì thuộc về thầy tế lễ đã dâng nó.'),
(2890, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 10, 'OT', 'Mọi của lễ chay trộn dầu hoặc nướng khô đều phải thuộc về mọi con trai A-rôn, mỗi người như nhau.'),
(2891, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 11, 'OT', 'Đây là luật lệ về của lễ thù ân mà người ta dâng cho Đức Giê-hô-va.'),
(2892, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 12, 'OT', 'Nếu ai dâng của lễ đó vì lời cảm tạ, thì phải dâng cùng với của lễ thù ân những ổ bánh không men trộn dầu, những bánh mỏng không men phết dầu, và bột lọc nhồi thành những ổ bánh trộn dầu.'),
(2893, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 13, 'OT', 'Cùng với các ổ bánh không men, người ấy phải dâng lễ vật mình lên; cùng với của lễ thù ân về những của lễ bình an mình.'),
(2894, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 14, 'OT', 'Họ phải dâng một phần từ mỗi của lễ ấy làm lễ vật dâng lên cho Đức Giê-hô-va; phần lễ vật dâng lên ấy sẽ thuộc về thầy tế lễ đã rưới huyết của con sinh tế thù ân.'),
(2895, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 15, 'OT', 'Thịt sinh tế tạ ơn của các lễ thù ân phải được ăn hết trong ngày dâng của lễ; không được để sót lại đến sáng.'),
(2896, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 16, 'OT', 'Nếu là của lễ về điều khấn hay của lễ tự nguyện, thì phải ăn con sinh ấy trong ngày dâng của lễ mình; còn nếu còn thừa lại, thì có thể ăn vào ngày hôm sau.'),
(2897, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 17, 'OT', 'Phần thịt của lễ thiêu còn sót lại đến ngày thứ ba sẽ bị thiêu trong lửa.'),
(2898, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 18, 'OT', 'Nếu ai ăn thịt của lễ thù ân vào ngày thứ ba, thì của lễ ấy sẽ không được chấp nhận, người dâng nó sẽ không được kể công; ấy là điều ô uế, và ai ăn từ của lễ ấy sẽ mang tội mình.'),
(2899, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 19, 'OT', 'Thịt nào chạm đến bất cứ vật gì ô uế thì không được ăn, phải lấy lửa thiêu đi; còn thịt nào thì người tinh sạch mới được ăn.'),
(2900, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 20, 'OT', 'Người nào bị ô uế mà ăn thịt của lễ thù ân dâng cho Đức Giê-hô-va, thì người ấy sẽ bị truất khỏi dân sự mình.'),
(2901, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 21, 'OT', 'Nếu có người nào đụng đến bất cứ vật gì ô uế, dù là sự ô uế của loài người, hoặc của loài vật không sạch, hoặc bất cứ vật gì ghê tởm, mà lại ăn thịt của lễ thù ân thuộc về Đức Giê-hô-va, thì linh hồn người ấy sẽ bị truất khỏi dân sự mình.'),
(2902, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 22, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(2903, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 23, 'OT', 'Hãy nói với các con trai của Y-sơ-ra-ên rằng: Mọi mỡ của bò, chiên hay dê, các ngươi không được ăn.'),
(2904, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 24, 'OT', 'Mỡ của con vật chết hay bị xé nát sẽ dùng được cho mọi công việc, nhưng các ngươi không được ăn.'),
(2905, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 25, 'OT', 'Vì hễ ai ăn mỡ của loài vật mà người ta dâng làm của lễ thiêu cho Đức Giê-hô-va, thì linh hồn người ấy sẽ bị truất khỏi dân sự mình.'),
(2906, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 26, 'OT', 'Mọi thứ huyết, các ngươi không được ăn, dù là huyết của loài chim hay loài vật, trong bất cứ nơi nào các ngươi ở.'),
(2907, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 27, 'OT', 'Phàm người nào ăn mọi thứ huyết, thì người ấy sẽ bị truất khỏi dân sự mình.'),
(2908, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 28, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(2909, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 29, 'OT', 'Hãy nói cùng con cái Y-sơ-ra-ên rằng: Ai dâng của lễ thù ân cho Đức Giê-hô-va, thì phải đem lễ vật mình dâng cho Đức Giê-hô-va từ của lễ thù ân mình.'),
(2910, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 30, 'OT', 'Chính tay người sẽ đem lễ vật thiêu đốt cho Đức Giê-hô-va, tức là phần mỡ và cái ngực; người sẽ đem cái ngực để dâng làm lễ vật đưa qua đưa lại trước mặt Đức Giê-hô-va.'),
(2911, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 31, 'OT', 'Thầy tế lễ sẽ xông mỡ trên bàn thờ, còn phần ngực thì thuộc về A-rôn và các con trai người.'),
(2912, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 32, 'OT', 'Các ngươi phải dâng cho thầy tế lễ cái giò phải làm lễ vật dâng lên từ các lễ thù ân của các ngươi.'),
(2913, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 33, 'OT', 'Phần cái giò bên phải phải thuộc về người trong các con trai A-rôn dâng huyết và mỡ của sinh tế thù ân.'),
(2914, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 34, 'OT', 'Vì chính ta đã lấy phần ngực lễ đưa qua đưa lại và phần giò lễ nâng lên, từ các lễ thù ân của dân Y-sơ-ra-ên, mà ban cho A-rôn thầy tế lễ và các con trai người, làm phần luật định đời đời, từ dân Y-sơ-ra-ên.'),
(2915, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 35, 'OT', 'Đây là phần lễ thiêu của A-rôn và phần lễ thiêu của các con trai người từ những của lễ dùng lửa dâng cho Đức Giê-hô-va, vào ngày Đức Giê-hô-va khiến họ đến gần để làm thầy tế lễ cho Đức Giê-hô-va;'),
(2916, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 36, 'OT', 'là điều Đức Giê-hô-va đã chỉ định để ban cho họ vào ngày xức dầu cho họ, từ nơi con cái Y-sơ-ra-ên; một luật lệ đời đời cho các thế hệ của họ.'),
(2917, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 37, 'OT', 'Đây là luật lệ về của lễ thiêu, về của lễ chay, về của lễ chuộc tội, về của lễ đền tội, về của lễ lễ phong chức, và về của lễ thù ân.'),
(2918, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 7, 38, 'OT', 'mà Đức Giê-hô-va đã truyền cho Môi-se tại núi Si-na-i, khi Ngài dặn biểu con cái Y-sơ-ra-ên dâng của lễ họ cho Đức Giê-hô-va trong đồng vắng Si-na-i.'),
(2919, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(2920, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 2, 'OT', 'Hãy đem A-rôn cùng các con trai người, các áo xống, dầu xức, con bò tơ làm của lễ chuộc tội, hai con chiên đực, và giỏ bánh không men;'),
(2921, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 3, 'OT', 'Hãy nhóm toàn thể hội chúng lại tại cửa Nhà tạm.'),
(2922, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 4, 'OT', 'Môi-se làm y như điều Đức Giê-hô-va đã truyền cho ông, và hội chúng nhóm hiệp tại cửa Nhà tạm.'),
(2923, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 5, 'OT', 'Môi-se nói với hội chúng rằng: Đây là điều mà Đức Giê-hô-va đã truyền phải làm.'),
(2924, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 6, 'OT', 'Môi-se dẫn A-rôn và các con trai người lại gần, rồi lấy nước rửa họ.'),
(2925, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 7, 'OT', 'Mặc áo trong cho A-rôn, thắt lưng người bằng đai, mặc áo dài cho người, đặt ê-phót trên người, thắt ê-phót bằng dây ê-phót và dùng dây đó mà buộc.'),
(2926, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 8, 'OT', 'Người đặt bảng đeo ngực lên người ông và đặt vào bảng đeo ngực các u-rim và thu-mim.'),
(2927, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 9, 'OT', 'Môi-se đội mũ ê-phu trên đầu người, rồi đặt trên mũ ê-phu phía trước mặt, tấm bảng bằng vàng, vòng triều thánh, y như lời Đức Giê-hô-va đã truyền cho Môi-se.'),
(2928, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 10, 'OT', 'Môi-se lấy dầu xức mà xức cho đền tạm và mọi vật ở trong đó, và biệt riêng chúng ra thánh.'),
(2929, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 11, 'OT', 'Rưới dầu từ nó trên bàn thờ bảy lần, rồi xức dầu cho bàn thờ và mọi đồ dùng của nó, cái thùng rửa và chân thùng của nó, để biệt riêng ra thánh.'),
(2930, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 12, 'OT', 'Người đổ dầu xức trên đầu A-rôn và xức cho người để biệt riêng người ra thánh.'),
(2931, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 13, 'OT', 'Môi-se đưa các con trai của A-rôn lại gần, mặc cho họ những chiếc áo dài, thắt đai cho họ, đội mão cho họ, y như Đức Giê-hô-va đã truyền cho Môi-se.'),
(2932, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 14, 'OT', 'Người biểu đem con bò tơ dùng làm của lễ chuộc tội lại gần, A-rôn và các con trai người đặt tay mình trên đầu con bò tơ dùng làm của lễ chuộc tội.'),
(2933, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 15, 'OT', 'Môi-se giết nó, rồi lấy huyết và dùng ngón tay bôi huyết lên các sừng của bàn thờ khắp bốn phía, làm cho bàn thờ nên thanh sạch; huyết còn lại thì đổ xuống nền bàn thờ, như vậy biệt bàn thờ riêng ra thánh để làm lễ chuộc tội tại đó.'),
(2934, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 16, 'OT', 'Người lấy toàn bộ mỡ phủ nội tạng, tấm mỡ trên gan, hai quả thận và mỡ của hai quả thận, rồi Môi-se đốt trên bàn thờ.'),
(2935, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 17, 'OT', 'Còn con bò, da nó, thịt nó và phân nó, thì thiêu bằng lửa ở ngoài trại quân, y như Đức Giê-hô-va đã truyền cho Môi-se.'),
(2936, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 18, 'OT', 'Người dẫn con chiên đực dùng làm của lễ thiêu lại gần, rồi A-rôn và các con trai người đặt tay mình trên đầu con chiên đực ấy.'),
(2937, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 19, 'OT', 'Rồi Môi-se giết nó và rưới huyết chung quanh bàn thờ.'),
(2938, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 20, 'OT', 'Môi-se lấy con chiên đực, xẻ từng phần, rồi thiêu cái đầu, các phần thịt và mỡ.'),
(2939, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 21, 'OT', 'Người lấy nước rửa bộ lòng và giò; rồi Môi-se xông trọn con chiên đực trên bàn thờ làm của lễ thiêu, là của lễ có mùi thơm, một của lễ dùng lửa dâng cho Đức Giê-hô-va, y như Đức Giê-hô-va đã truyền cho Môi-se.'),
(2940, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 22, 'OT', 'Người cũng dâng con chiên đực thứ hai, tức là con chiên đực về lễ phong chức; A-rôn và các con trai người đặt tay mình trên đầu con chiên đực đó.'),
(2941, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 23, 'OT', 'Môi-se giết con vật, rồi lấy huyết bôi vào vành tai phải của A-rôn, và lên ngón tay cái của tay phải người, và lên ngón chân cái của chân phải người.'),
(2942, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 24, 'OT', 'Môi-se dẫn các con trai A-rôn đến gần, rồi lấy huyết bôi vào vành tai bên phải họ, và lên ngón tay cái bên phải, và lên ngón chân cái bên phải; rồi Môi-se rảy huyết chung quanh bàn thờ.'),
(2943, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 25, 'OT', 'Người lấy mỡ, cái đuôi, toàn bộ mỡ phủ trên lòng, màng trên gan, hai quả thận cùng mỡ hai quả thận, và cái đùi bên phải.'),
(2944, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 26, 'OT', 'lại lấy từ giỏ bánh không men để trước mặt Đức Giê-hô-va một ổ bánh không men, một ổ bánh mì có dầu và một cái bánh tráng, đặt những cái đó trên các phần mỡ và trên cái giò bên phải,'),
(2945, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 27, 'OT', 'Đặt tất cả những vật ấy trên các bàn tay của A-rôn và trên các bàn tay của các con trai người, rồi đưa qua đưa lại trước mặt Đức Giê-hô-va.'),
(2946, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 28, 'OT', 'Môi-se lấy các món đó khỏi tay họ, rồi nhóm trên bàn thờ trên của lễ thiêu; ấy là các lễ đầy tay, có mùi thơm vừa lòng, là lễ thiêu dành cho Đức Giê-hô-va.'),
(2947, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 29, 'OT', 'Môi-se lấy cái ngực con chiên đực lễ phong chức mà rung qua rung lại trước mặt Đức Giê-hô-va; phần ấy thuộc về Môi-se làm của lễ, y như Đức Giê-hô-va đã truyền cho Môi-se.'),
(2948, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 30, 'OT', 'Môi-se lấy dầu xức và huyết ở trên bàn thờ mà rảy trên A-rôn, trên áo xống người, trên các con trai người và trên áo xống các con trai người cùng với người; như vậy, người biệt riêng A-rôn, áo xống người, các con trai người và áo xống các con trai người cùng với người ra thánh.'),
(2949, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 31, 'OT', 'Môi-se nói cùng A-rôn và các con trai người rằng: Hãy nấu thịt tại cửa Hội mạc, và ăn thịt ấy cùng với bánh trong giỏ lễ đầy tay, y như ta đã truyền rằng: A-rôn và các con trai người sẽ ăn nó.'),
(2950, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 32, 'OT', 'Thịt và bánh còn sót lại phải các ngươi thiêu bằng lửa.'),
(2951, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 33, 'OT', 'Trong bảy ngày, các ngươi không được ra khỏi cửa Lều Hội Kiến, cho đến ngày trọn những ngày phong chức các ngươi; vì trong bảy ngày, Ngài sẽ đặt tay các ngươi vào chức vụ.'),
(2952, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 34, 'OT', 'Như điều đã làm trong ngày nầy, Đức Giê-hô-va đã truyền phải làm để chuộc tội cho các ngươi.'),
(2953, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 35, 'OT', 'Hãy ngồi trọn cả ngày lẫn đêm tại cửa Đền tạm trong bảy ngày, và giữ trọn sự canh giữ của Đức Giê-hô-va, hầu các ngươi khỏi chết; vì Ta đã được truyền dặn như vậy.'),
(2954, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 8, 36, 'OT', 'A-rôn và các con trai người làm mọi điều mà Đức Giê-hô-va đã truyền cho Môi-se.'),
(2955, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 9, 1, 'OT', 'Đến ngày thứ tám, Môi-se gọi A-rôn và các con trai người, cùng các trưởng lão Y-sơ-ra-ên.'),
(2956, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 9, 2, 'OT', 'A-rôn, hãy bắt một con bò con đực làm của lễ chuộc tội và một con chiên đực làm của lễ thiêu, đều không tì vít, rồi dâng trước mặt Đức Giê-hô-va.'),
(2957, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 9, 3, 'OT', 'Hãy nói cùng con cái Y-sơ-ra-ên rằng: Hãy lấy một con dê đực làm của lễ chuộc tội, và một con bò con cùng một con chiên con, đều một tuổi, không tật nguyền, để dùng làm của lễ thiêu.'),
(2958, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 9, 4, 'OT', 'một con bò và một con chiên đực để dùng làm của lễ thù ân, để dâng trước mặt Đức Giê-hô-va, và một của lễ chay trộn dầu; vì ngày nay Đức Giê-hô-va sẽ hiện ra cùng các ngươi.'),
(2959, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 9, 5, 'OT', 'Họ lấy những vật mà Môi-se đã truyền, đem đến trước mặt Đền tạm; cả hội chúng đến gần và đứng trước mặt Đức Giê-hô-va.'),
(2960, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 9, 6, 'OT', 'Môi-se nói: "Đây là điều mà Đức Giê-hô-va đã truyền lệnh phải làm; các ngươi hãy thực hiện điều đó, thì sự vinh hiển của Đức Giê-hô-va sẽ hiện ra cho các ngươi."'),
(2961, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 9, 7, 'OT', 'Môi-se nói cùng A-rôn: "Hãy đến gần bàn thờ và dâng của lễ chuộc tội và của lễ thiêu của ngươi, để làm lễ chuộc tội cho ngươi và cho dân sự; lại hãy dâng của lễ của dân sự và làm lễ chuộc tội cho họ, y như Đức Giê-hô-va đã truyền dạy."'),
(2962, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 9, 8, 'OT', 'A-rôn lại gần bàn thờ và giết con bò con dùng làm của lễ chuộc tội cho mình.'),
(2963, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 9, 9, 'OT', 'Các con trai của A-rôn đem huyết đến cho người; người lấy ngón tay mình nhúng vào huyết, rồi nhỏ lên các sừng của bàn thờ, và đổ huyết còn lại dưới chân bàn thờ.'),
(2964, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 9, 10, 'OT', 'Mỡ, hai trái cật và cái màng trên gan của của lễ chuộc tội, thì người làm cho cháy thơm trên bàn thờ, y như Đức Giê-hô-va đã truyền cho Môi-se.'),
(2965, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 9, 11, 'OT', 'Còn thịt và da thì thiêu trong lửa bên ngoài trại quân.'),
(2966, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 9, 12, 'OT', 'Người giết con sinh dùng làm của lễ thiêu; các con trai A-rôn đem huyết đến cho người, và người rảy huyết chung quanh trên bàn thờ.'),
(2967, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 9, 13, 'OT', 'Họ cũng mang của lễ thiêu đến cho A-rôn, gồm các phần thân và cái đầu; rồi người xông toàn bộ trên bàn thờ.'),
(2968, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 9, 14, 'OT', 'Người rửa bộ lòng và các chân, rồi xông lên trên của lễ thiêu nơi bàn thờ.'),
(2969, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 9, 15, 'OT', 'Dâng của lễ dân sự, bắt con dê đực làm của lễ chuộc tội cho dân sự, giết nó và làm lễ chuộc tội cho nó như lần đầu.'),
(2970, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 9, 16, 'OT', 'Dâng của lễ thiêu và làm theo đúng nghi thức quy định.'),
(2971, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 9, 17, 'OT', 'Dâng của lễ chay, lấy đầy lòng hai tay mình từ của lễ ấy mà xông trên bàn thờ, ngoài của lễ thiêu buổi sáng.'),
(2972, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 9, 18, 'OT', 'A-rôn giết con bò và con chiên đực làm của lễ thù ân cho dân sự; các con trai A-rôn đem huyết đến cho người, và người rưới huyết chung quanh trên bàn thờ.'),
(2973, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 9, 19, 'OT', 'và mỡ của con bò và của con chiên đực, đuôi, mỡ trên các bộ lòng, hai quả thận và phần mỡ che phủ gan;'),
(2974, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 9, 20, 'OT', 'Họ đặt các phần mỡ trên ngực, rồi nhóm mỡ trên bàn thờ.'),
(2975, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 9, 21, 'OT', 'A-rôn đưa qua đưa lại trước mặt Đức Giê-hô-va phần mỡ và cái giò bên phải, y như Môi-se đã truyền dạy.'),
(2976, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 9, 22, 'OT', 'A-rôn giơ tay mình trên dân sự và chúc phước cho họ; rồi người bước xuống sau khi dâng xong của lễ chuộc tội, của lễ thiêu và của lễ thù ân.'),
(2977, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 9, 23, 'OT', 'Môi-se và A-rôn đi vào hội mạc, rồi đi ra và chúc phước cho dân chúng; vinh hiển của Đức Giê-hô-va hiện ra cho toàn thể dân chúng.'),
(2978, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 9, 24, 'OT', 'Một ngọn lửa từ trước mặt Đức Giê-hô-va bùng ra, thiêu nuốt của lễ toàn thiêu và các phần mỡ trên bàn thờ. Cả dân chúng thấy điều đó, liền reo lên mừng rỡ và phủ phục xuống đất.'),
(2979, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 10, 1, 'OT', 'A-rôn có các con trai là Na-đáp và A-bi-hu; mỗi người lấy lư của mình, bỏ lửa vào, để hương lên, rồi dâng trước mặt Đức Giê-hô-va một thứ lửa lạ, điều mà Ngài chẳng hề truyền dặn họ.'),
(2980, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 10, 2, 'OT', 'Một ngọn lửa từ trước mặt Đức Giê-hô-va bốc ra, thiêu đốt họ, và họ chết trước mặt Đức Giê-hô-va.'),
(2981, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 10, 3, 'OT', 'Môi-se nói cùng A-rôn: "Chính điều mà Đức Giê-hô-va đã phán rằng: Ta sẽ được xưng thánh nơi những kẻ gần ta, và trước mặt cả dân sự Ta sẽ được tôn vinh." Và A-rôn nín lặng.'),
(2982, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 10, 4, 'OT', 'Môi-se gọi Mi-sa-ên và Eân-sa-phan, các con trai của U-xi-ên, chú của A-rôn, mà nói với họ rằng: Hãy đến gần, khiêng anh em các ngươi ra khỏi trước mặt nơi thánh ra ngoài trại quân.'),
(2983, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 10, 5, 'OT', 'Họ đến gần, khiêng xác hai người còn mặc áo trong ra ngoài trại, y như lời Môi-se đã phán.'),
(2984, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 10, 6, 'OT', 'Môi-se nói cùng A-rôn và cùng Ê-lê-a-sa và Y-tha-ma, các con trai người: Các ngươi chớ để đầu trần, và các ngươi chớ xé áo mình, hầu cho các ngươi không chết, và Ngài không nổi giận cùng cả hội chúng; nhưng anh em các ngươi, cả nhà Y-sơ-ra-ên, sẽ than khóc sự thiêu hủy mà Đức Giê-hô-va đã thiêu đốt.'),
(2985, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 10, 7, 'OT', 'Đừng ra khỏi cửa Đền tạm, e rằng các ngươi phải chết; vì dầu xức của Đức Giê-hô-va ở trên các ngươi. Vậy họ làm theo lời Môi-se.'),
(2986, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 10, 8, 'OT', 'Đức Giê-hô-va phán cùng A-rôn rằng:'),
(2987, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 10, 9, 'OT', 'Ngươi và các con trai ngươi chớ uống rượu hay vật gì gây say khi vào Hội mạc, hầu khỏi chết; ấy là một luật lệ đời đời cho các thế hệ các ngươi.'),
(2988, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 10, 10, 'OT', 'để các ngươi phân biệt điều thánh với điều thường, và điều ô uế với điều thanh sạch,'),
(2989, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 10, 11, 'OT', 'và dạy con cái Y-sơ-ra-ên mọi mạng lịnh mà Đức Giê-hô-va đã phán cho họ qua tay Môi-se.'),
(2990, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 10, 12, 'OT', 'Môi-se nói với A-rôn và với Ê-lê-a-sa và Y-tha-ma, các con trai người còn lại, rằng: Hãy lấy phần lễ chay còn lại từ các lễ lửa của Đức Giê-hô-va, và ăn đi không pha men, gần bàn thờ, vì ấy là vật chí thánh.'),
(2991, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 10, 13, 'OT', 'Hãy ăn của lễ ấy tại nơi thánh, vì ấy là phần ngươi và phần các con trai ngươi trong những của lễ thiêu của Đức Giê-hô-va; bởi vì ta đã được truyền dạy như vậy.'),
(2992, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 10, 14, 'OT', 'Chiếc ngực dâng đưa qua lại và cái giò dâng giơ lên, ngươi cùng các con trai và các con gái ngươi phải ăn tại nơi thanh sạch; vì phần ngươi và phần các con trai ngươi, ấy là điều đã ban cho từ các bàn thờ của lễ thù ân của dân Y-sơ-ra-ên.'),
(2993, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 10, 15, 'OT', 'Họ sẽ đem đến cái giò dâng giơ lên và cái o dâng đưa qua đưa lại, cùng với những mỡ của lễ thiêu hóa, để dâng đưa qua đưa lại trước mặt Đức Giê-hô-va; và điều đó sẽ thuộc về ngươi và các con trai ngươi cùng với ngươi, làm luật lệ đời đời, như Đức Giê-hô-va đã truyền dạy.'),
(2994, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 10, 16, 'OT', 'Môi-se tìm kiếm con dê đực dùng làm của lễ chuộc tội, thì nầy, nó đã bị thiêu đốt; bèn nổi giận cùng Ê-lê-a-sa và Y-tha-ma, các con trai còn lại của A-rôn, mà nói rằng:'),
(2995, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 10, 17, 'OT', 'Tại sao các ngươi không ăn của lễ chuộc tội tại nơi thánh? Vì đó là vật chí thánh, mà Đức Giê-hô-va đã ban cho các ngươi, để các ngươi mang lấy tội lỗi của hội chúng và làm lễ chuộc tội cho họ trước mặt Đức Giê-hô-va.'),
(2996, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 10, 18, 'OT', 'Nầy, huyết của nó không được mang vào nơi thánh; các ngươi đáng phải ăn nó trong nơi thánh, y như điều ta đã truyền dạy.'),
(2997, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 10, 19, 'OT', 'A-rôn nói với Môi-se: "Này, ngày nay họ đã dâng của lễ chuộc tội và của lễ thiêu mình trước mặt Đức Giê-hô-va, và những điều nầy đã xảy đến cho tôi; vậy nếu tôi ăn của lễ chuộc tội ngày nay, điều đó há có đẹp lòng Đức Giê-hô-va chăng?"'),
(2998, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 10, 20, 'OT', 'Môi-se nghe xong, thì lấy làm đẹp lòng.'),
(2999, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se và A-rôn, rằng:'),
(3000, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 2, 'OT', 'Hãy nói với các con của Y-sơ-ra-ên rằng: Đây là loài vật các ngươi được ăn, trong các loài vật trên mặt đất:'),
(3001, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 3, 'OT', 'Hết thảy loài vật nào có móng chẻ ra và phân hai ngón, lại nhai lại trong loài thú vật, các ngươi được phép ăn loài ấy.'),
(3002, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 4, 'OT', 'Nhưng các ngươi không được ăn những loài này trong các loài nhai lại và có móng chẻ: lạc đà, vì nó nhai lại nhưng không chẻ móng; nó là loài không sạch đối với các ngươi.'),
(3003, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 5, 'OT', 'Con nhơi thì nhơi, nhưng không rẽ móng, nên nó là loài không sạch đối với các ngươi.'),
(3004, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 6, 'OT', 'và con thỏ rừng, vì nó nhai lại nhưng không chia móng guốc; nó là loài không sạch đối với các ngươi.'),
(3005, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 7, 'OT', 'Con heo, vì nó có móng rẽ và chân chia hai nhưng không nhai lại, nên nó là vật không sạch đối với các ngươi.'),
(3006, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 8, 'OT', 'Các ngươi không được ăn thịt chúng, và không được đụng đến xác chết của chúng; chúng là vật ô uế cho các ngươi.'),
(3007, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 9, 'OT', 'Các ngươi được phép ăn mọi loài vật ở trong nước, tức là mọi loài vật ở biển hay ở sông có vây và có vảy.'),
(3008, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 10, 'OT', 'Những loài nào sống trong biển hay trong sông, tức mọi sinh vật bò dưới nước và mọi sinh mạng sống trong nước, mà không có vây và không có vảy, thì các ngươi phải coi chúng là vật gớm ghiếc.'),
(3009, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 11, 'OT', 'Chúng sẽ là vật gớm ghiếc cho các ngươi; không được ăn thịt chúng, và phải coi xác chết của chúng là điều gớm ghiếc.'),
(3010, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 12, 'OT', 'Mọi loài vật nào ở trong nước mà không có vây và không có vảy thì phải xem là điều gớm ghiếc cho các ngươi.'),
(3011, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 13, 'OT', 'Các loài này, các ngươi phải coi là vật gớm ghiếc trong các loài chim; không được ăn, vì chúng thật là đồ gớm ghiếc: chim ưng, chim ngạc, và ó biển.'),
(3012, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 14, 'OT', 'và con kền kền, và chim ưng, theo thứ giống của nó;'),
(3013, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 15, 'OT', 'mọi loài quạ theo thứ của nó,'),
(3014, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 16, 'OT', 'và con gái đà điểu, và con ụt, và con thủy kê, và con bò cắc, theo loài của nó;'),
(3015, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 17, 'OT', 'và chim cú, chim thằn lằn, chim cò quắm,'),
(3016, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 18, 'OT', 'và con chim thìn-sấm, và con chim ka-át, và con chim ra-ham.'),
(3017, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 19, 'OT', 'và chim bồ nông, chim diệc theo thứ tự nó; và chim cú mèo, và con dơi.'),
(3018, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 20, 'OT', 'Mọi loài côn trùng bay được, đi bốn chân, thì các ngươi phải lấy làm gớm ghiếc.'),
(3019, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 21, 'OT', 'Tuy nhiên, trong mọi loài côn trùng bay trên mặt đất đi bằng bốn chân, các ngươi được ăn những loài có chân nhảy ở phía trên chân chúng để nhảy trên mặt đất;'),
(3020, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 22, 'OT', 'Các thứ này các ngươi được ăn: châu chấu theo loài nó, cào cào theo giống nó, dế mèn theo loài nó, và ve sầu theo giống nó.'),
(3021, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 23, 'OT', 'Mọi loài côn trùng bay có bốn chân thì các ngươi phải lấy làm gớm ghiếc.'),
(3022, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 24, 'OT', 'Các ngươi sẽ bị ô uế vì những loài này; hễ ai đụng đến xác chết của chúng sẽ bị ô uế cho đến chiều tối.'),
(3023, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 25, 'OT', 'Ai mang xác chết của các loài ấy phải giặt quần áo mình và bị ô uế cho đến chiều tối.'),
(3024, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 26, 'OT', 'Mọi loài vật có móng chẻ ra nhưng không nhai lại và không có chân chia hai thì đều là vật ô uế cho các ngươi; hễ ai đụng đến chúng sẽ bị ô uế.'),
(3025, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 27, 'OT', 'Mọi loài đi bằng bàn chân trong các loài vật đi bốn chân đều là vật không sạch cho các ngươi; hễ ai rờ đến xác chết của những loài ấy sẽ bị ô uế cho đến chiều tối.'),
(3026, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 28, 'OT', 'Kẻ nào mang xác chết của những loài ấy phải giặt quần áo mình và bị ô uế cho đến chiều tối; các loài ấy là không sạch cho các ngươi.'),
(3027, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 29, 'OT', 'Nầy là những loài không sạch cho các ngươi trong các loài vật bò trên đất: con chuột nhửi, con chuột lắt, con rắn mối, tùy theo thứ nó;'),
(3028, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 30, 'OT', 'con thằn lằn, con kỳ đà, con thạch sùng, con rắn đất và con rết'),
(3029, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 31, 'OT', 'Các loài vật bò sát này là những loài không sạch cho các ngươi: bất cứ ai đụng đến xác của chúng khi chúng đã chết sẽ bị ô uế cho đến chiều tối.'),
(3030, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 32, 'OT', 'Bất cứ vật gì mà khi các loài ấy chết rơi trúng thì đều bị ô uế, dù là đồ gỗ, hay quần áo, hay da, hay bao gai, tức mọi thứ đồ dùng làm việc; phải đem ngâm trong nước, và sẽ bị ô uế cho đến chiều tối, rồi mới được tinh sạch.'),
(3031, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 33, 'OT', 'Mọi đồ sành mà một trong các vật đó rơi vào bên trong nó, thì mọi thứ ở trong nó sẽ bị ô uế, và chính cái đó các ngươi phải đập bể ra.'),
(3032, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 34, 'OT', 'Mọi thứ thực phẩm có thể ăn được, nếu bị nước rớt vào, sẽ trở nên ô uế; và mọi thứ uống được, dù đựng trong bất kỳ đồ chứa nào, cũng sẽ trở nên ô uế.'),
(3033, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 35, 'OT', 'Mọi vật nào mà xác chết của chúng rơi trên đó sẽ bị ô uế; lò nướng và bếp cũng phải đập phá; chúng là điều ô uế và sẽ là điều ô uế cho các ngươi.'),
(3034, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 36, 'OT', 'Chỉ có suối nước hay hồ chứa nước thì vẫn được xem là thanh sạch; còn ai chạm vào xác chết của những vật ấy sẽ bị ô uế.'),
(3035, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 37, 'OT', 'Nếu một phần của xác chết chúng rơi trên bất cứ thứ hạt giống nào được gieo xuống, thì nó vẫn được xem là thanh sạch.'),
(3036, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 38, 'OT', 'Nếu người ta đổ nước trên hột giống, mà có vật gì từ xác chết rớt vào, thì hột giống ấy trở nên ô uế cho các ngươi.'),
(3037, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 39, 'OT', 'Nếu một con vật trong các loài vật mà các ngươi được phép ăn chết đi, thì người nào chạm vào xác chết của nó sẽ bị ô uế cho đến chiều tối.'),
(3038, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 40, 'OT', 'Ai ăn xác chết của loài đó phải giặt quần áo mình và sẽ ô uế cho đến chiều tối; còn ai mang xác chết của nó cũng phải giặt quần áo và sẽ ô uế cho đến chiều tối.'),
(3039, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 41, 'OT', 'Mọi loài sinh vật bò trên mặt đất đều là vật gớm ghiếc, không được ăn.'),
(3040, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 42, 'OT', 'Mọi loài bò sát trên bụng, và mọi loài bốn chân, cho đến mọi loài sinh sản nhiều chân, tức mọi loài côn trùng bò trên đất, các ngươi không được ăn vì chúng là sự gớm ghê.'),
(3041, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 43, 'OT', 'Chớ làm cho linh hồn các ngươi trở nên gớm ghiếc vì bất cứ loài côn trùng nào bò trên đất; các ngươi không được làm cho mình ra ô uế vì chúng, để trở nên ô uế vì chúng.'),
(3042, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 44, 'OT', 'Vì ta là Giê-hô-va Đức Chúa Trời của các ngươi; hãy biệt riêng mình ra và nên thánh, vì ta là thánh; các ngươi chớ làm cho linh hồn mình ra ô uế bởi bất cứ loài bò sát nào trườn trên đất.'),
(3043, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 45, 'OT', 'Vì ta là Đức Giê-hô-va, Đấng đã đem các ngươi lên khỏi đất Ai Cập, để làm Đức Chúa Trời cho các ngươi; các ngươi phải nên thánh, vì ta là thánh.'),
(3044, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 46, 'OT', 'Đây là luật lệ về loài vật trên đất, loài chim trời, mọi sinh mạng sống động bò lội dưới nước và mọi sinh mạng bò trên mặt đất.'),
(3045, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 11, 47, 'OT', 'để phân biệt giữa vật không sạch và vật sạch, giữa loài vật ăn được và loài vật không được ăn.'),
(3046, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 12, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3047, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 12, 2, 'OT', 'Hãy nói cùng con cái Y-sơ-ra-ên rằng: Nếu người phụ nữ thọ thai và sinh con trai, thì sẽ bị ô uế bảy ngày, như những ngày ô uế vì kinh nguyệt của nàng.'),
(3048, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 12, 3, 'OT', 'Vào ngày thứ tám, phải cắt bì phần thịt dương vật của nó.'),
(3049, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 12, 4, 'OT', 'Và ba mươi ngày và ba ngày, người ấy sẽ ở trong huyết sự sạch của mình; không được đụng đến một vật thánh nào, và không được vào nơi thánh, cho đến khi trọn các ngày sự sạch của người ấy.'),
(3050, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 12, 5, 'OT', 'Nếu người sanh con gái, thì sẽ bị ô uế trong hai tuần lễ như khi hành kinh; và phải ở riêng trong sáu mươi ngày và sáu ngày để tẩy sạch huyết mình.'),
(3051, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 12, 6, 'OT', 'Khi trọn ngày thanh sạch vì sinh con trai hay con gái, thì phải mang đến nơi cửa Hội mạc cho thầy tế lễ một con chiên con một tuổi làm của lễ thiêu, và một con bồ câu con hoặc một con cu con làm của lễ chuộc tội.'),
(3052, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 12, 7, 'OT', 'Thầy tế lễ sẽ dâng người đó trước mặt Đức Giê-hô-va, và làm lễ chuộc tội cho người ấy, thì người sẽ được sạch khỏi chỗ phát ra huyết mình. Đó là luật lệ về người đàn bà sinh con trai hay con gái.'),
(3053, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 12, 8, 'OT', 'Nếu tay người ấy không đủ sức mua chiên, thì phải lấy hai con bồ câu hoặc hai con chim cu, một con làm của lễ thiêu và một con làm của lễ chuộc tội; thầy tế lễ sẽ làm lễ chuộc tội cho người ấy, và người ấy sẽ được sạch.'),
(3054, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se và A-rôn rằng:'),
(3055, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 2, 'OT', 'Người nào trên da mình có u, nhọt hay vết trắng, nếu những cái đó trên da mình trở thành vết phung, thì phải dẫn người ấy đến A-rôn thầy tế lễ hoặc đến một trong các con trai người là những thầy tế lễ.'),
(3056, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 3, 'OT', 'Thầy tế lễ sẽ xem xét vít trên da thân thể; nếu lông ở vít đã chuyển trắng, và bề mặt vết thương sâu hơn da thân người, thì đó là vít phung; thầy tế lễ phải xem xét người ấy và tuyên bố người ấy là ô uế.'),
(3057, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 4, 'OT', 'Nếu trên da thân thể người ấy có một vết trắng, nhưng vết ấy không sâu hơn da, và lông không chuyển thành trắng, thì thầy tế lễ phải giam người bị nhiễm ô uế ấy trong bảy ngày.'),
(3058, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 5, 'OT', 'Thầy tế lễ sẽ xem người ấy vào ngày thứ bảy; này vít đó đứng tại chỗ, chưa lan ra trên da, thì thầy tế lễ phải giam người ấy thêm bảy ngày nữa.'),
(3059, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 6, 'OT', 'Thầy tế lễ sẽ xem người ấy vào ngày thứ bảy; nếu vết ấy đã tái đi, không lan trên da, thì thầy tế lễ sẽ tuyên người ấy là sạch; ấy là nhọt. Người ấy phải giặt quần áo mình, rồi sẽ được sạch.'),
(3060, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 7, 'OT', 'Nhưng nếu chỗ loét lan rộng trên da, sau khi người ấy đã được đưa đến cho thầy tế lễ để làm lễ tinh sạch, thì phải đưa người ấy đến cho thầy tế lễ xem lần thứ hai.'),
(3061, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 8, 'OT', 'Thầy tế lễ sẽ xem xét; nếu thấy chỗ lở lan rộng trên da, thầy tế lễ phải tuyên bố người ấy là ô uế; ấy là bệnh phung.'),
(3062, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 9, 'OT', 'Khi người nào bị bệnh phong hủi, thì phải dẫn người ấy đến cùng thầy tế lễ.'),
(3063, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 10, 'OT', 'Thầy tế lễ sẽ xem xét; nầy, nếu trên da có một vết loét trắng, và lông đã biến thành trắng, và có thịt sống còn ở trong vết loét ấy,'),
(3064, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 11, 'OT', 'Đó là bệnh phong cùi mãn tính trên da thân thể người ấy; thầy tế lễ phải tuyên bố người ấy là ô uế, không được giam người ấy, vì người ấy đã ô uế rồi.'),
(3065, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 12, 'OT', 'Nếu bệnh phung lan ra trên da và lan tràn khắp da người bị vít, từ đầu cho đến chân, khắp mọi nơi mà mắt thầy tế lễ thấy được,'),
(3066, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 13, 'OT', 'Thầy tế lễ phải xem xét; nếu thấy bệnh phong đã phủ toàn bộ thịt người đó, thì hãy tuyên bố người bị nhiễm là sạch, vì toàn thân đã trở nên trắng: người ấy là sạch.'),
(3067, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 14, 'OT', 'Nhưng vào ngày nào thấy thịt sống hiện ra trên người ấy, thì người ấy bị ô uế.'),
(3068, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 15, 'OT', 'Thầy tế lễ sẽ xem thấy thịt sống thì phải tuyên bố người ấy là ô uế; thịt sống là ô uế, ấy là bệnh phong cùi.'),
(3069, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 16, 'OT', 'Hoặc nếu thịt sống trở lại và chuyển sang trắng, thì phải đến cùng thầy tế lễ.'),
(3070, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 17, 'OT', 'Thầy tế lễ sẽ xem xét người ấy; nếu vết phong đã trở nên trắng, thì thầy tế lễ phải tuyên bố người đó được sạch, vì người ấy đã sạch.'),
(3071, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 18, 'OT', 'Khi trên da thân mình có mụn mủ và đã được chữa lành,'),
(3072, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 19, 'OT', 'và tại nơi mụt nhọt xuất hiện một vết sưng trắng hoặc một đốm trắng hơi đỏ, thì phải đưa đến thầy tế lễ xem xét;'),
(3073, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 20, 'OT', 'Thầy tế lễ sẽ xem xét; nếu thấy chỗ ấy lõm dưới da và lông trên đó đã chuyển sang màu trắng, thì thầy tế lễ phải tuyên bố người ấy là ô uế; đó là một bệnh phong cùi đã bùng phát trong vùng da bị viêm.'),
(3074, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 21, 'OT', 'Nếu thầy tế lễ xem xét mà không thấy trong đó có lông trắng, và chỗ ấy không lõm sâu hơn da, lại có màu xám xịt, thì thầy tế lễ phải giam người ấy trong bảy ngày.'),
(3075, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 22, 'OT', 'Nếu đốm lan rộng trên da thì thầy tế lễ phải tuyên bố người ấy là ô uế; ấy là một vết phong.'),
(3076, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 23, 'OT', 'Nếu vết loét ở dưới đó đứng yên, không lan rộng, thì đó là sẹo của mụt nhọt; thầy tế lễ phải tuyên cho người ấy là tinh sạch.'),
(3077, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 24, 'OT', 'Hoặc về thịt, khi trên da người ấy có vết phỏng do lửa, rồi tại nơi vết phỏng ấy xuất hiện một đám trắng đỏ hoặc trắng.'),
(3078, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 25, 'OT', 'Thầy tế lễ sẽ xem xét người ấy; nếu thấy lông trong chỗ loét đã chuyển thành trắng và chỗ loét sâu hơn da, thì đó là bệnh phong hủi do vết bỏng gây ra; thầy tế lễ phải tuyên bố người ấy là ô uế, vì đó là một chứng bệnh phong hủi.'),
(3079, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 26, 'OT', 'Nếu thầy tế lễ khám xét, thấy trong đốm không có lông trắng, không lõm sâu hơn da, và đốm ấy đã tái, thì thầy tế lễ phải giam người ấy trong bảy ngày.'),
(3080, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 27, 'OT', 'Đến ngày thứ bảy, thầy tế lễ sẽ xem người ấy; nếu đốm lan rộng trên da, thì thầy tế lễ sẽ tuyên người đó là ô uế; ấy là bệnh phong.'),
(3081, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 28, 'OT', 'Nếu đốm đó đứng yên, không lan ra trên da và đã nhạt đi, ấy là vết thương do bỏng; thầy tế lễ phải tuyên bố người ấy là tinh sạch, vì đó chỉ là sẹo của vết bỏng.'),
(3082, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 29, 'OT', 'Người nam hay người nữ nào bị vít trên đầu hoặc nơi râu,'),
(3083, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 30, 'OT', 'Thầy tế lễ sẽ xem xét vết đó; nếu thấy vết ấy lõm sâu hơn da, và trong đó có lông mỏng màu vàng, thì thầy tế lễ phải tuyên bố người ấy là ô uế: đó là bệnh hủi trên đầu hoặc trên râu.'),
(3084, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 31, 'OT', 'Nếu thầy tế lễ thấy vết phong trên da, mà hình dạng của nó không sâu hơn da, và trong đó không có lông đen, thì thầy tế lễ phải cách ly người có vết phong ấy trong bảy ngày.'),
(3085, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 32, 'OT', 'Ngày thứ bảy, thầy tế lễ sẽ xem xét vết đó; này, đòng đanh không lan rộng, không có lông màu vàng, và bề ngoài của đòng đanh không sâu hơn da.'),
(3086, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 33, 'OT', 'Người ấy phải cạo đầu, nhưng không được cạo chỗ mụn nhọt; rồi thầy tế lễ phải cách ly người đó thêm bảy ngày thứ hai.'),
(3087, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 34, 'OT', 'Đến ngày thứ bảy, thầy tế lễ sẽ xem xét vết bịnh; nếu thấy vết bịnh không lan rộng trên da, và vẻ ngoài của nó không sâu hơn da, thì thầy tế lực phải tuyên bố người ấy tinh sạch; người ấy phải giặt quần áo mình, và sẽ được xem là tinh sạch.'),
(3088, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 35, 'OT', 'Nếu sau khi người ấy đã được làm sạch, đốm ghẻ lại lan rộng trên da, thì phải khám lại.'),
(3089, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 36, 'OT', 'Thầy tế lễ phải xem xét người ấy; nếu thấy đống đanh đã lan rộng trên da, thì thầy tế lễ không cần xét đến tóc vàng: người ấy đã bị ô uế.'),
(3090, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 37, 'OT', 'Nhưng nếu người xem xét, vết này đứng lại và đã mọc ra lông đen, thì vết này đã được chữa lành; người ấy là sạch, thầy tế lễ phải làm lễ tinh sạch cho người ấy.'),
(3091, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 38, 'OT', 'Người nam hay người nữ nào trên da thịt mình có những vết loét, những vết loét trắng,'),
(3092, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 39, 'OT', 'Thầy tế lễ sẽ xem xét; nếu thấy trên da thân thể có những vết trắng nhợt, những đốm xanh nhạt, ấy chỉ là đốm trắng lở trên da; người ấy là sạch.'),
(3093, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 40, 'OT', 'Người nào hói đầu thì trơ trọi đầu mình; người ấy là sạch.'),
(3094, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 41, 'OT', 'Nếu tóc rụng ở phía trán làm trán hói, người ấy vẫn tinh sạch.'),
(3095, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 42, 'OT', 'Nếu trên chỗ hói phía trước hoặc phía sau có một vết thương màu trắng hồng, ấy là bệnh phong nổi lên trên chỗ hói của người đó hoặc trên chỗ hói phía sau của người đó.'),
(3096, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 43, 'OT', 'Thầy tế lễ phải xem người ấy; nếu vết loét của bệnh hủi tại chỗ trọc trước hoặc trọc sau có màu trắng đỏ, như vẻ phong hủi nơi da thân thể,'),
(3097, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 44, 'OT', 'Người nào bị phung thì là người ô uế; thầy tế lễ phải tuyên bố người ấy là ô uế; vết nhọt của người ấy ở trên đầu.'),
(3098, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 45, 'OT', 'Người phong cùi mà trong người có vết ấy phải xé rách áo mình, đầu để trần, râu che khuất, và phải kêu lên rằng: "Ô uế! Ô uế!"'),
(3099, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 46, 'OT', 'Trọn đời người ấy mang vết nhọt, thì phải bị ô uế; người ấy phải ở riêng, chỗ ở của người ấy là bên ngoài trại quân.'),
(3100, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 47, 'OT', 'Khi nào trên quần áo xuất hiện dấu hiệu phung, bất luận là trên quần áo bằng len hay trên quần áo bằng vải gai,'),
(3101, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 48, 'OT', 'trên vải gai hoặc chỉ gai, hoặc trên len hay sợi len, trên da hay trên mọi vật dụng bằng da.'),
(3102, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 49, 'OT', 'Nếu vết đó có màu xanh lục hoặc đỏ nâu trên quần áo, hoặc trên da, hoặc trên sợi gai, hoặc trên sợi len, hoặc trên mọi vật dụng bằng da, thì đó là bệnh phong cùi; phải đem cho thầy tế lễ xem.'),
(3103, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 50, 'OT', 'Thầy tế lễ sẽ xem xét vết vít, rồi nhốt người bị vít ấy trong bảy ngày.'),
(3104, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 51, 'OT', 'Đến ngày thứ bảy, thầy tế lễ sẽ xem lại vết ô uế; nếu thầy thấy vết ô uế đã lan trên vải, hoặc trên len, hoặc trên da dê, hoặc trên da, hoặc trên bất cứ vật gì làm bằng da, thì vết ô uế ấy là bệnh phong ăn lan; vật đó là ô uế.'),
(3105, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 52, 'OT', 'Người phải thiêu quần áo hay vải dệt, hay vải thêu, bằng len hay bằng gai, hoặc bất kỳ đồ vật nào bằng da mà có vết đó, vì đó là bệnh phong thối rữa; phải đem thiêu trong lửa.'),
(3106, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 53, 'OT', 'Nếu thầy tế lễ xem xét, và nầy, vít đó không lan ra trên áo, hoặc trên sợi gai, hoặc trên sợi len, hoặc trên bất cứ đồ vật da nào,'),
(3107, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 54, 'OT', 'Thầy tế lễ phải truyền đem giặt món có vết đó, rồi giam nó thêm bảy ngày nữa.'),
(3108, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 55, 'OT', 'Sau khi đã giặt, nếu thầy tế lễ xem xét lại và thấy vít đó không đổi màu, và vít đó không lan ra, thì món đó là ô uế; ngươi phải lấy lửa thiêu nó đi; ấy là một thứ vít mốc ở trên phần trọc phía trước hay là phía sau đầu.'),
(3109, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 56, 'OT', 'Nếu thầy tế lễ xem thấy vít đã tái sau khi giặt, thì phải xé nó ra khỏi áo xống, hoặc khỏi da, hoặc khỏi sợi gai, hoặc khỏi sợi len.'),
(3110, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 57, 'OT', 'Nếu mảng ô uế lại xuất hiện trên áo xống, hay trên vải dệt, hay trên vải thêu, hay trên vật gì bằng da, ấy là sự ô uế lan ra; chính vật có vết ô uế ấy phải bị thiêu đốt bằng lửa.'),
(3111, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 58, 'OT', 'Và nếu bộ áo, hoặc vải gai mịn, hoặc vải len, hoặc bất kỳ đồ vật bằng da nào mà ngươi đã giặt, mà vết ô uế đã biến mất khỏi các vật ấy, thì phải giặt lại lần thứ hai, rồi sẽ được sạch.'),
(3112, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 13, 59, 'OT', 'Đó là luật về bệnh phong trên áo bằng len hoặc bằng vải gai, trên sợi canh hoặc sợi chéo, hoặc trên mọi vật dụng bằng da, để định việc làm cho nó trở nên tinh sạch hay ô uế.'),
(3113, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3114, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 2, 'OT', 'Đây sẽ là luật lệ về người phung trong ngày người ấy được làm sạch; người đó phải được dẫn đến thầy tế lễ.'),
(3115, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 3, 'OT', 'thầy tế lễ phải ra ngoài trại, thầy tế lễ sẽ kiểm tra, và nếu thấy bệnh phong đã được chữa lành khỏi người bị phong,'),
(3116, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 4, 'OT', 'Thầy tế lễ sẽ truyền lấy cho người được sạch hai con chim sống, tinh sạch, một cây gỗ hương nam, chỉ chỉ son đỏ và cây kinh giới.'),
(3117, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 5, 'OT', 'Thầy tế lễ sẽ truyền lấy một con trong hai con chim kia mà giết trong cái chậu bằng đất sét, trên nước sống.'),
(3118, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 6, 'OT', 'Bắt lấy con chim sống, cây gỗ hương nam, sợi chỉ đỏ sậm và nhành kinh giới, rồi nhúng những vật ấy cùng con chim sống vào huyết con chim đã bị giết trên nước chảy.'),
(3119, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 7, 'OT', 'Thầy tế lễ phải rảy bảy lần trên người đã được làm sạch khỏi bệnh phung; và thầy làm cho người ấy được coi là tinh sạch, rồi thả con chim sống ra trên mặt đất đồng.'),
(3120, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 8, 'OT', 'Người được sạch sẽ phải giặt quần áo mình, cạo hết lông tóc, tắm trong nước rồi sẽ được sạch; sau đó mới được vào trong trại, nhưng phải ở ngoài lều mình bảy ngày.'),
(3121, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 9, 'OT', 'Đến ngày thứ bảy, người ấy sẽ cạo hết mọi lông tóc trên mình, cả đầu, râu, lông mày và mọi lông trên thân thể; rồi giặt quần áo mình và tắm rửa thân thể trong nước, thì sẽ được sạch.'),
(3122, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 10, 'OT', 'Vào ngày thứ tám, người ấy sẽ lấy hai chiên đực không tật nguyền, một chiên cái một tuổi không tật nguyền, ba phần mười ê-pha bột lọc trộn dầu làm lễ thiêu, và một lô dầu;'),
(3123, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 11, 'OT', 'Thầy tế lễ sẽ đặt người được làm cho sạch và những vật đó trước mặt Đức Giê-hô-va, tại cửa nhà hội.'),
(3124, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 12, 'OT', 'Thầy tế lễ sẽ lấy chiên con đực ấy và dâng nó làm của lễ chuộc tội, cùng với một lót dầu, rồi đưa cả hai qua lại làm lễ vật dâng trước mặt Đức Giê-hô-va.'),
(3125, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 13, 'OT', 'Người sẽ giết con chiên con tại nơi thường giết con sinh tế tội và con sinh thiêu, tức là tại nơi thánh; vì của lễ chuộc tội về sự phạm lỗi cũng thánh như của lễ tế tội, thuộc về thầy tế lễ; ấy là vật chí thánh.'),
(3126, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 14, 'OT', 'Thầy tế lễ sẽ lấy huyết của con sinh tế chuộc tội, rồi thầy tế lễ sẽ bôi huyết lên vành tai phải của người được làm sạch, và lên ngón tay cái bên phải và ngón chân cái bên phải.'),
(3127, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 15, 'OT', 'tư tế sẽ lấy dầu từ bình đổ trên lòng bàn tay trái của mình,'),
(3128, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 16, 'OT', 'và thầy tế lễ phải lấy ngón tay phải mình, nhúng vào dầu trên lòng bàn tay trái mình, rồi rảy dầu bằng ngón tay mình bảy lần trước mặt Đức Giê-hô-va.'),
(3129, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 17, 'OT', 'Dầu còn lại trong tay mình, thầy tế lễ sẽ lấy bôi trên vành tai phải của người được làm cho sạch, trên ngón tay cái bên phải và trên ngón chân cái bên phải, tức là trên huyết của sinh tế chuộc tội.'),
(3130, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 18, 'OT', 'Số dầu còn lại trên bàn tay của thầy tế lễ, thầy tế lễ sẽ đổ trên đầu người được sạch; và thầy tế lễ sẽ làm lễ chuộc tội cho người đó trước mặt Đức Giê-hô-va.'),
(3131, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 19, 'OT', 'Rồi thầy tế lễ sẽ dâng của lễ chuộc tội, làm lễ chuộc tội cho người được sạch sự ô uế của mình; sau đó mới giết con sinh dùng làm của lễ thiêu.'),
(3132, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 20, 'OT', 'thầy tế lễ sẽ dâng của lễ thiêu và của lễ chay lên bàn thờ; thầy tế lễ sẽ làm lễ chuộc tội cho người ấy, thì người ấy sẽ được tinh sạch.'),
(3133, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 21, 'OT', 'Nếu người ấy nghèo, không đủ khả lực dâng lễ vật, thì phải lấy một chiên con đực làm của lễ chuộc sự mắc lỗi, dâng đưa qua đưa lại để làm lễ chuộc tội cho mình, cùng một phần mười bột lọc trộn dầu làm của lễ chay và một lít dầu.'),
(3134, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 22, 'OT', 'và hai con bồ câu hoặc hai con chim cu, tùy theo khả lực của người ấy; con này dùng làm của lễ chuộc tội, con kia dùng làm của lễ thiêu.'),
(3135, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 23, 'OT', 'Vào ngày thứ tám, người ấy phải mang các lễ vật ấy đến cho thầy tế lễ tại cửa Nhà Hội, trước mặt Đức Giê-hô-va, để được làm sạch.'),
(3136, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 24, 'OT', 'Thầy tế lễ sẽ lấy chiên con đực làm của lễ chuộc tội và một lít dầu, rồi thầy tế lễ sẽ dâng chúng đưa qua đưa lại trước mặt Đức Giê-hô-va.'),
(3137, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 25, 'OT', 'Thầy tế lễ sẽ giết chiên con dùng làm của lễ chuộc tội, lấy huyết của lễ chuộc tội đó bôi vào vành tai phải của người được làm sạch, và lên ngón cái tay phải và ngón cái chân phải.'),
(3138, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 26, 'OT', 'Rồi thầy tế lễ đổ dầu trên lòng bàn tay trái của thầy tế lễ.'),
(3139, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 27, 'OT', 'Thầy tế lễ lấy ngón tay phải, nhúng vào dầu đổ trên bàn tay trái mình, rồi rảy bảy lần trước mặt Đức Giê-hô-va.'),
(3140, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 28, 'OT', 'và thầy tế lễ sẽ lấy dầu trên lòng bàn tay mình, đổ trên vành tai phải của người được làm sạch, trên ngón tay cái bên phải và trên ngón chân cái bên phải, tại nơi đã đổ huyết của lễ chuộc tội.'),
(3141, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 29, 'OT', 'Dầu còn dư lại trên lòng bàn tay của thầy tế lễ, thì phải đổ trên đầu người được làm sạch, để làm lễ chuộc tội cho người ấy trước mặt Đức Giê-hô-va.'),
(3142, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 30, 'OT', 'và người ấy sẽ dâng một trong hai con bồ câu hoặc một trong các con chim cu, tùy theo vật mà tay người ấy với tới được.'),
(3143, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 31, 'OT', 'dâng con mà tay người ấy có thể chu cấp: một con dùng làm của lễ chuộc tội, một con dùng làm của lễ thiêu, cùng với của lễ chay. Thầy tế lễ sẽ làm lễ chuộc tội cho người được sạch trước mặt Đức Giê-hô-va.'),
(3144, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 32, 'OT', 'Đó là luật lệ về lễ thanh sạch cho người bị phong cùi mà tay người ấy không đủ khả năng để chu cấp cho lễ vật thanh sạch của mình.'),
(3145, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 33, 'OT', 'Đức Giê-hô-va phán cùng Môi-se và A-rôn rằng:'),
(3146, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 34, 'OT', 'Khi các ngươi vào xứ Ca-na-an mà Ta sẽ ban cho các ngươi làm sản nghiệp, nếu Ta đặt một bệnh phong cùi trong nhà tại xứ sản nghiệp của các ngươi,'),
(3147, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 35, 'OT', 'Chủ nhà đó phải đến và báo cho thầy tế lễ biết rằng: Tôi thấy như có một vết mốc xuất hiện trong nhà.'),
(3148, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 36, 'OT', 'Thầy tế lễ phải truyền đem đồ đạc ra khỏi nhà trước khi thầy tế lễ vào xem xét vết mốc, hầu cho mọi vật trong nhà khỏi bị ô uế; sau đó thầy tế lễ mới vào xem xét ngôi nhà.'),
(3149, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 37, 'OT', 'Người sẽ xem xét vết vít; nầy, nếu vết vít ở nơi các vách nhà, có những chỗ lõm màu xanh lục hoặc đỏ, và bề mặt của chúng thấp hơn mặt vách,'),
(3150, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 38, 'OT', 'rồi thầy tế lễ phải đi ra ngoài cửa nhà, và niêm phong nhà lại trong bảy ngày.'),
(3151, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 39, 'OT', 'Ngày thứ bảy, thầy tế lễ phải trở lại xem xét; nếu thấy vết bịnh hủi đã lan ra trên các vách nhà,'),
(3152, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 40, 'OT', 'rồi thầy tế lễ sẽ truyền phải gỡ những hòn đá bị dính bệnh ra, đem ném ra ngoài thành, đến một nơi ô uế;'),
(3153, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 41, 'OT', 'phải cạo bên trong nhà và bốn phía xung quanh, rồi đổ bụi đã cạo ra ngoài thành, vào một nơi ô uế;'),
(3154, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 42, 'OT', 'sẽ lấy những hòn đá khác để thay thế những hòn đá kia, và lấy đất sét khác trát lên toàn bộ ngôi nhà.'),
(3155, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 43, 'OT', 'Nếu sau khi đã gỡ những hòn đá, cạo sạch nhà và trát lại, mà vết loét đó lại bùng phát trong nhà,'),
(3156, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 44, 'OT', 'thầy tế lễ phải đến xem; nếu thấy vết loét lan ra trong nhà, thì đó là bệnh phong ăn mòn trong nhà: nhà ấy là điều ô uế.'),
(3157, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 45, 'OT', 'Phải đập phá ngôi nhà, lấy những hòn đá của nó, các cây xà gỗ và tất cả bụi nhà, rồi đem ra ngoài thành, đến một nơi ô uế.'),
(3158, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 46, 'OT', 'Người nào vào nhà trong suốt thời gian nhà ấy bị niêm phong sẽ bị ô uế cho đến chiều.'),
(3159, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 47, 'OT', 'Người nằm ngủ trong nhà phải giặt quần áo mình; và người ăn trong nhà cũng phải giặt quần áo mình.'),
(3160, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 48, 'OT', 'Nếu thầy tế lễ trở lại xem, thấy vít không lan ra trong nhà sau khi nhà đã được trát lại, thì thầy tế lễ sẽ làm lễ tinh sạch cho nhà, vì vít đã được chữa lành.'),
(3161, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 49, 'OT', 'Người phải lấy hai con chim, cây gỗ hương nam, chỉ đỏ sặm và cây hyssôp, để làm lễ chuộc tội cho nhà.'),
(3162, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 50, 'OT', 'và sẽ giết con chim thứ nhất trong một cái chậu bằng đất nung, trên nước sống.'),
(3163, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 51, 'OT', 'Người ấy phải lấy cây gỗ hương nam, nhành hyssôp, sợi chỉ đỏ sậm, và con chim sống, rồi nhúng những vật ấy trong huyết con chim đã bị giết và trong nước sống; sau đó rảy bảy lần lên ngôi nhà.'),
(3164, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 52, 'OT', 'Người sẽ dùng huyết con chim, nước sống, con chim sống, cây gỗ hương nam, lá hyssôp, và chỉ màu điều sặm mà làm lễ chuộc cho cái nhà.'),
(3165, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 53, 'OT', 'Và hãy thả con chim sống ra ngoài thành, về phía đồng vắng; rồi làm lễ chuộc tội cho ngôi nhà, thì ngôi nhà sẽ được tinh sạch.'),
(3166, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 54, 'OT', 'Đó là luật lệ về mọi bệnh phong và nhọt.'),
(3167, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 55, 'OT', 'về bệnh phong trên quần áo và trên nhà.'),
(3168, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 56, 'OT', 'về chỗ phồng rộp, chỗ loét ra và chỗ trắng.'),
(3169, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 14, 57, 'OT', 'để dạy biết ngày nào ô uế và ngày nào tinh sạch. Đó là luật về bệnh phung.'),
(3170, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se và A-rôn rằng:'),
(3171, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 2, 'OT', 'Hãy nói với con cái Y-sơ-ra-ên và bảo họ: Mỗi người nam nào thân thể bị rong huyết ra từ thịt mình, thì người ấy trở nên ô uế.'),
(3172, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 3, 'OT', 'Đây sẽ là sự ô uế của người bởi nơi rong rêu ra từ thân thể: hoặc thân thể để rong rêu chảy ra, hoặc thân thể ngưng rong rêu lại, thì sự ô uệ của người là như vậy.'),
(3173, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 4, 'OT', 'Mọi giường mà người bị xuất huyết nằm trên đó sẽ bị ô uế, và mọi đồ vật mà người ấy ngồi trên cũng sẽ bị ô uế.'),
(3174, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 5, 'OT', 'Người nào đụng đến giường của người ấy phải giặt quần áo mình, tắm trong nước và bị ô uế cho đến chiều tối.'),
(3175, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 6, 'OT', 'Người nào ngồi trên đồ vật mà người bị lậu đã ngồi, phải giặt quần áo mình, tắm trong nước và bị ô uế cho đến chiều tối.'),
(3176, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 7, 'OT', 'Ai đụng đến thân thể người bị xuất bạch trược phải giặt quần áo mình, tắm trong nước và bị ô uế cho đến chiều tối.'),
(3177, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 8, 'OT', 'Nếu người bị bệnh lậu nhổ nhằm người tinh sạch, thì người ấy phải giặt quần áo mình, tắm trong nước, và bị ô uế cho đến chiều tối.'),
(3178, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 9, 'OT', 'Mọi cái xe nào mà người bị bệnh lậu ngồi lên sẽ bị ô uế.'),
(3179, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 10, 'OT', 'Hễ ai đụng đến bất cứ vật gì đã ở dưới người bị bệnh xuất tinh, sẽ bị ô uế cho đến chiều tối; còn ai mang những vật đó phải giặt quần áo mình, tắm trong nước, và bị ô uế cho đến chiều tối.'),
(3180, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 11, 'OT', 'Ai bị người bị bệnh xuất dịch rờ đến mà không rửa tay trong nước, thì phải giặt quần áo, tắm trong nước và bị ô uế cho đến chiều tối.'),
(3181, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 12, 'OT', 'Đồ gốm mà người bị bệnh xuất tinh vô ý đụng đến phải đập bể; còn mọi đồ bằng gỗ thì phải rửa bằng nước.'),
(3182, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 13, 'OT', 'Khi người bị xuất huyết trong mình được sạch rồi, phải đếm cho mình bảy ngày để tinh sạch; giặt quần áo mình, tắm thân thể trong nước chảy, rồi sẽ được tinh sạch.'),
(3183, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 14, 'OT', 'Đến ngày thứ tám, người ấy phải lấy cho mình hai con chim cu hoặc hai con bồ câu con, rồi đến trước mặt Đức Giê-hô-va, tại cửa Nhà Hội, và trao chúng cho thầy tế lễ.'),
(3184, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 15, 'OT', 'Thầy tế lễ sẽ dâng con này làm của lễ chuộc tội, con kia làm của lễ thiêu; thầy tế lễ sẽ làm lễ chuộc tội cho người trước mặt Đức Giê-hô-va vì cớ bạch trược của người.'),
(3185, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 16, 'OT', 'Người nam nào nếu có tinh dịch xuất ra khỏi mình, thì phải tắm toàn thân trong nước và bị ô uế cho đến chiều tối.'),
(3186, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 17, 'OT', 'Mọi quần áo và mọi vật bằng da có dính tinh dịch phải giặt trong nước và bị ô uế cho đến chiều tối.'),
(3187, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 18, 'OT', 'Người nữ nào mà một người nam nằm cùng với nàng trong sự giao hợp, thì cả hai phải tắm trong nước và bị ô uế cho đến chiều tối.'),
(3188, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 19, 'OT', 'Khi một người phụ nữ bị hành kinh, máu sẽ chảy ra khỏi thân thể nàng; trong bảy ngày nàng sẽ bị ô uế vì cữ kinh này; hễ ai đụng đến nàng sẽ bị ô uế cho đến chiều tối.'),
(3189, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 20, 'OT', 'Mọi vật mà người đàn bà nằm hay ngồi trên trong lúc bị kinh nguyệt sẽ bị ô uế.'),
(3190, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 21, 'OT', 'Ai chạm vào giường của người ấy phải giặt quần áo mình, tắm trong nước và bị ô uế cho đến chiều tối.'),
(3191, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 22, 'OT', 'Ai đụng đến vật gì người ấy ngồi trên phải giặt quần áo mình, tắm trong nước và bị ô uế cho đến chiều tối.'),
(3192, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 23, 'OT', 'Nếu người ấy chạm vào giường hay đồ vật nào mà người đàn bà ấy ngồi trên đó, thì người ấy sẽ bị ô uế cho đến chiều tối.'),
(3193, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 24, 'OT', 'Nếu một người nam nằm chung với nàng, và huyết kinh nguyệt nàng dính vào người nam, thì người nam ấy sẽ bị ô uế bảy ngày; và mọi giường mà người nam nằm trên đó cũng sẽ bị ô uế.'),
(3194, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 25, 'OT', 'Người đàn bà nào bị ra huyết nhiều ngày không phải trong kỳ kinh nguyệt, hoặc bị ra huyết trong kỳ kinh nguyệt mình, thì mọi ngày ra huyết ô uế của nàng sẽ như những ngày nàng bị kinh nguyệt; nàng sẽ là người ô uế.'),
(3195, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 26, 'OT', 'Trong suốt những ngày bị rong kinh, mọi giường mà người đàn bà nằm trên sẽ trở nên ô uế như giường khi người đó bị kinh nguyệt, và mọi vật gì mà người đó ngồi trên cũng sẽ bị ô uế như sự ô uế của kỳ kinh nguyệt.'),
(3196, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 27, 'OT', 'Ai đụng đến các vật đó sẽ bị ô uế; phải giặt quần áo, tắm trong nước, và bị ô uế cho đến chiều tối.'),
(3197, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 28, 'OT', 'Khi nào người nữ sạch huyết mình rồi, phải đếm cho mình bảy ngày, rồi sau mới được tinh sạch.'),
(3198, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 29, 'OT', 'Vào ngày thứ tám, phải lấy cho người hai con chim cu hoặc hai con bồ câu con, và đem chúng đến cho thầy tế lễ tại cửa Nhà hội.'),
(3199, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 30, 'OT', 'Thầy tế lễ sẽ dâng một con làm của lễ chuộc tội, và con kia làm của lễ thiêu; thầy tế lễ sẽ làm lễ chuộc tội cho người trước mặt Đức Giê-hô-va vì sự ô uế do rong kinh.'),
(3200, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 31, 'OT', 'Hãy phân biệt con cái Y-sơ-ra-ên ra khỏi sự ô uế của chúng, để chúng không chết trong sự ô uế mình, khi làm ô uế nơi thánh của Ta ở giữa chúng.'),
(3201, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 32, 'OT', 'Đây là luật lệ về người bị ra máu mủ và về người nào xuất ra từ mình tinh dịch để bị ô uế vì cớ đó.'),
(3202, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 15, 33, 'OT', 'về người nữ bị ra huyết trong lúc kinh nguyệt, về mọi người nam hay nữ bị rong huyết, và về người nam nằm cùng người nữ trong lúc nàng bị ô uế.'),
(3203, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se, sau khi hai con trai của A-rôn chết trong lúc đến gần trước mặt Đức Giê-hô-va, thì họ chết.'),
(3204, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 2, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Hãy nói cùng A-rôn, anh ngươi, chớ vào bất cứ lúc nào vào nơi thánh, ở phía trong bức màn, trước nắp chỗ hiện diện, là nơi trên hòm chứng, hầu người không chết; vì ta sẽ hiện ra trong đám mây trên nắp chỗ hiện diện.'),
(3205, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 3, 'OT', 'A-rôn sẽ vào nơi thánh như thế nầy: lấy một con bò đực tơ dùng làm của lễ chuộc tội, và một con chiên đực dùng làm của lễ thiêu.'),
(3206, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 4, 'OT', 'Người sẽ mặc áo trong bằng vải gai mịn thánh, và quần bằng vải gai mịn sẽ mặc trên thân thể; người sẽ thắt đai bằng vải gai mịn, và đội mão bằng vải gai mịn; ấy là những áo xưng thánh; người sẽ tắm mình trong nước, rồi mới mặc các áo đó.'),
(3207, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 5, 'OT', 'Từ nơi hội chúng Y-sơ-ra-ên, người ta sẽ lấy hai con dê đực dùng làm của lễ chuộc tội, và một con chiên đực dùng làm của lễ thiêu.'),
(3208, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 6, 'OT', 'A-rôn phải dâng con bò đực làm của lễ chuộc tội cho mình, và làm lễ chuộc tội cho chính mình và cho nhà mình.'),
(3209, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 7, 'OT', 'Người phải lấy hai con dê đực và đặt chúng trước mặt Đức Giê-hô-va, tại cửa nhà hội.'),
(3210, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 8, 'OT', 'A-rôn sẽ bắt thăm cho hai con dê đực: một thăm về phần Đức Giê-hô-va, một thăm về phần A-xa-sên.'),
(3211, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 9, 'OT', 'A-rôn sẽ dẫn con dê mà thăm đã chỉ về phần Đức Giê-hô-va, và dâng nó làm của lễ chuộc tội.'),
(3212, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 10, 'OT', 'Còn con dê mà bắt thăm về phần A-xa-sên, sẽ để sống trước mặt Đức Giê-hô-va, để làm lễ chuộc tội cho nó, rồi thả nó vào đồng vắng đặng đi về A-xa-sên.'),
(3213, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 11, 'OT', 'A-rôn sẽ dâng con bò con sinh tế chuộc tội là của mình, và làm lễ chuộc tội cho mình và cho nhà mình; rồi giết con bò con sinh tế chuộc tội là của mình.'),
(3214, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 12, 'OT', 'Đoạn lấy một cái chảo đầy than cháy đỏ từ bàn thờ trước mặt Đức Giê-hô-va, và hai tay đầy hương nghiền mịn, rồi đem vào phía trong bức màn.'),
(3215, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 13, 'OT', 'Người phải đặt hương trên lửa trước mặt Đức Giê-hô-va, hầu cho đám mây của hương bao phủ nắp thi ân ở trên hòm bảng chứng, thì người không chết.'),
(3216, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 14, 'OT', 'Người phải lấy huyết con bò đực, lấy ngón tay rảy lên mặt nắp che khuất về phía đông, rồi lấy ngón tay rảy huyết bảy lần về phía trước nắp che khuất.'),
(3217, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 15, 'OT', 'Sau đó, người sẽ giết con dê đực làm của lễ chuộc tội cho dân chúng, đem huyết nó vào bên trong bức màn, và dùng huyết nó như cách đã dùng huyết con bò tơ, tức là rảy huyết lên nắp thi ân và trước nắp thi ân.'),
(3218, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 16, 'OT', 'Đức Giê-hô-va sẽ làm lễ chuộc tội cho nơi thánh, vì cớ các sự ô uế của con cái Y-sơ-ra-ên và các sự vi phạm của chúng nó, cho mọi tội lỗi chúng nó; cũng vậy, phải làm lễ chuộc tội cho hội mạc, là nơi Đức Chúa Trời ngự giữa chúng nó giữa các sự ô uế của chúng nó.'),
(3219, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 17, 'OT', 'Khi người vào nơi thánh để làm lễ chuộc tội, thì không một người nào được ở trong hội mạc cho đến khi người ra; người sẽ làm lễ chuộc tội cho mình, cho nhà mình, và cho toàn thể hội chúng Y-sơ-ra-ên.'),
(3220, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 18, 'OT', 'Người sẽ đi ra đến bàn thờ ở trước mặt Đức Giê-hô-va và làm lễ chuộc tội cho bàn thờ; người sẽ lấy huyết con bò và huyết con dê, rồi đặt huyết trên các sừng của bàn thờ xung quanh.'),
(3221, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 19, 'OT', 'Dùng ngón tay rảy huyết trên bàn thờ bảy lần, làm cho bàn thờ nên sạch và thánh vì cớ những sự ô uế của dân Y-sơ-ra-ên.'),
(3222, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 20, 'OT', 'Khi người đã làm lễ chuộc tội cho nơi thánh, cho hội mạc và cho bàn thờ rồi, thì phải dâng con dê sống.'),
(3223, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 21, 'OT', 'A-rôn sẽ đặt hai tay mình trên đầu con dê sống, xưng trên nó mọi tội ác và mọi sự vi phạm của dân Y-sơ-ra-ên, dù là tội gì đi nữa, rồi đặt những điều đó trên đầu con dê, và sai một người sẵn sàng dẫn nó đi vào đồng vắng.'),
(3224, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 22, 'OT', 'Con dê đực sẽ mang trên mình mọi tội lỗi của Y-sơ-ra-ên đến một đất hoang vắng; rồi người ta sẽ thả nó vào trong đồng vắng.'),
(3225, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 23, 'OT', 'A-rôn sẽ vào hội mạc, cởi những áo bằng vải gai mà ông đã mặc khi vào nơi thánh, rồi để những áo đó tại đó.'),
(3226, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 24, 'OT', 'Rồi hãy tắm mình bằng nước tại một nơi thánh, mặc lại các đồ của mình, đi ra và dâng của lễ thiêu về phần mình và của lễ thiêu về phần dân chúng, đặng làm lễ chuộc tội cho mình và cho dân chúng.'),
(3227, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 25, 'OT', 'Người phải xông mỡ của con sinh tế chuộc tội trên bàn thờ.'),
(3228, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 26, 'OT', 'Người dẫn dê đực về phần A-xa-sên phải giặt quần áo mình, tắm thân thể trong nước, rồi sau mới được vào trại quân.'),
(3229, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 27, 'OT', 'Phải đem con bò mộng làm của lễ chuộc tội và con dê làm của lễ chuộc tội, mà huyết của chúng đã mang vào nơi thánh để làm lễ chuộc tội, ra ngoài trại quân; rồi lấy da, thịt và phân của chúng mà đốt trong lửa.'),
(3230, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 28, 'OT', 'Người đốt các vật ấy phải giặt quần áo mình và tắm mình trong nước, rồi sau mới được vào trại.'),
(3231, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 29, 'OT', 'Đó sẽ là một luật lệ đời đời cho các ngươi: vào ngày mười tháng bảy, các ngươi phải ăn năn hối tội; không được làm bất cứ công việc gì, dù là người bản xứ hay là người ngoại khách đang trú ngụ giữa các ngươi.'),
(3232, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 30, 'OT', 'Vì trong ngày nầy, Đức Giê-hô-va sẽ làm lễ chuộc tội cho các ngươi để làm cho các ngươi được tinh sạch; các ngươi sẽ được sạch mọi tội lỗi mình trước mặt Đức Giê-hô-va.'),
(3233, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 31, 'OT', 'Đó là một ngày Sa-bát, một ngày nghỉ ngơi cho các ngươi, và các ngươi phải ép tâm hồn mình; ấy là một luật lệ đời đời.'),
(3234, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 32, 'OT', 'Vị thầy tế lễ đã được xức dầu và được bổ nhiệm kế vị cha mình sẽ mặc các áo bằng vải gai, tức là các áo thánh, mà làm lễ chuộc tội.'),
(3235, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 33, 'OT', 'Người sẽ làm lễ chuộc tội cho nơi thánh, cho hội mạc, cho bàn thờ, cho các thầy tế lễ và cho toàn thể dân hội chúng.'),
(3236, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 16, 34, 'OT', 'Đây sẽ là một luật lệ đời đời cho các ngươi, để làm lễ chuộc tội cho con cái Y-sơ-ra-ên mỗi năm một lần, vì mọi tội lỗi của chúng; A-rôn làm y như Đức Giê-hô-va đã truyền dạy Môi-se.'),
(3237, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 17, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3238, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 17, 2, 'OT', 'Hãy nói cùng A-rôn, các con trai người và toàn thể dân Y-sơ-ra-ên, mà rằng: Đây là điều Đức Giê-hô-va đã truyền dạy rằng:'),
(3239, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 17, 3, 'OT', 'Mỗi người nam nào trong nhà Y-sơ-ra-ên giết một con bò, một con chiên, hoặc một con dê trong trại quân hay là ngoài trại quân,'),
(3240, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 17, 4, 'OT', 'nếu không đem đến trước lều hội ngộ để dâng của lễ cho Đức Giê-hô-va, trước trại tạm của Đức Giê-hô-va, thì huyết sẽ bị kể là tội cho người ấy, vì đã làm đổ huyết ra; người ấy sẽ bị cắt đứt khỏi giữa dân sự mình.'),
(3241, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 17, 5, 'OT', 'để con cái Y-sơ-ra-ên mang những của lễ họ dâng ngoài đồng mà đến trước mặt Đức Giê-hô-va, tại cửa hội mạc, nộp cho thầy tế lễ và dâng những của lễ thù ân cho Đức Giê-hô-va.'),
(3242, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 17, 6, 'OT', 'Thầy tế lễ sẽ rảy huyết lên bàn thờ Đức Giê-hô-va tại cửa Nhà Hội, và sẽ đốt mỡ làm của lễ thiêu, một mùi thơm cho Đức Giê-hô-va.'),
(3243, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 17, 7, 'OT', 'Dân Y-sơ-ra-ên không được giết của lễ mình cho các con dê rừng nữa, là những vật mà họ đã phạm tội tà dâm theo chúng. Luật lệ nầy sẽ là một định lệ đời đời cho họ qua các thế hệ.'),
(3244, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 17, 8, 'OT', 'Hãy nói cùng dân Y-sơ-ra-ên và kẻ khách kiều ngụ giữa họ rằng: Phàm người nào dâng của lễ thiêu hay của lễ giết,'),
(3245, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 17, 9, 'OT', 'và không đem đến nơi cửa Rạp Gặp để dâng cho Đức Giê-hô-va, thì người ấy sẽ bị truất khỏi dân sự mình.'),
(3246, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 17, 10, 'OT', 'Người nào của nhà Y-sơ-ra-ên hay là khách kiều ngụ giữa họ mà ăn bất kỳ huyết nào, thì ta sẽ nghiêm nghị chống lại linh hồn người ấy và truất nó khỏi giữa dân sự mình.'),
(3247, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 17, 11, 'OT', 'Vì sinh mạng của xác thịt ở trong huyết, và Ta đã ban huyết cho các ngươi trên bàn thờ để làm lễ chuộc tội cho linh hồn các ngươi; vì chính huyết, nhờ sinh mạng, mà chuộc tội được.'),
(3248, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 17, 12, 'OT', 'Vì cớ ấy, ta đã phán cùng con cái Y-sơ-ra-ên rằng: Mọi người trong các ngươi không được ăn huyết; và người ngoại kiều sống giữa các ngươi cũng không được ăn huyết.'),
(3249, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 17, 13, 'OT', 'Mỗi người trong vòng con cái Y-sơ-ra-ên hoặc khách kiều ngụ giữa họ, khi săn được một con vật sống hay một loài chim nào dùng làm thức ăn được, phải đổ huyết nó ra, rồi lấy bụi đất phủ lên.'),
(3250, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 17, 14, 'OT', 'Vì sinh mạng của mọi xác thịt là huyết của nó, huyết ấy là sinh mạng; Ta đã phán cùng con cái Y-sơ-ra-ên rằng: Các ngươi không được ăn huyết của bất cứ xác thịt nào, vì sinh mạng của mọi xác thịt là huyết nó; hễ ai ăn huyết sẽ bị truất khỏi dân sự.'),
(3251, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 17, 15, 'OT', 'Mọi người, dù là người bản xứ hay khách lạ, ăn xác chết hay con vật bị xé nát, phải giặt quần áo mình, tắm trong nước, và sẽ bị ô uế cho đến chiều tối, rồi được tinh sạch.'),
(3252, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 17, 16, 'OT', 'Nếu không giặt quần áo và thân thể không rửa, thì phải mang tội mình.'),
(3253, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 18, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3254, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 18, 2, 'OT', 'Hãy nói cùng con cái Y-sơ-ra-ên và bảo họ: Ta là Đức Giê-hô-va Đức Chúa Trời các ngươi.'),
(3255, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 18, 3, 'OT', 'Các ngươi không được làm theo các việc người ta làm tại xứ Ê-díp-tô, nơi các ngươi đã ở, và không được làm theo các việc tại xứ Ca-na-an, là nơi Ta dẫn các ngươi đến; các ngươi cũng không được đi theo luật lệ của họ.'),
(3256, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 18, 4, 'OT', 'Các ngươi phải thực hành các mạng lịnh ta và giữ các luật lệ ta để noi theo; Ta là Đức Giê-hô-va Đức Chúa Trời các ngươi.'),
(3257, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 18, 5, 'OT', 'Các ngươi phải giữ các luật lệ và các mạng lịnh của ta, mà ai làm theo những điều đó thì sẽ nhờ nó mà được sống; Ta là Đức Giê-hô-va.'),
(3258, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 18, 6, 'OT', 'Mỗi người không được đến gần người bà con ruột thịt mình để tiết lộ sự trần truồng của họ; Ta là Đức Giê-hô-va.'),
(3259, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 18, 7, 'OT', 'Chớ tiết lộ sự trần truồng của cha ngươi và sự trần truồng của mẹ ngươi; mẹ ngươi là người sinh ngươi, ngươi chớ tiết lộ sự trần truồng của bà.'),
(3260, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 18, 8, 'OT', 'Chớ tiết lộ sự trần truồng của vợ cha ngươi; ấy là sự trần truồng của cha ngươi.'),
(3261, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 18, 9, 'OT', 'Chớ tiết lộ sự trần truồng của chị em ngươi, con gái cha ngươi hoặc con gái mẹ ngươi, dù sinh trong nhà hay sinh ngoài nhà.'),
(3262, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 18, 10, 'OT', 'Không được tiết lộ điều xấu hổ của con gái con trai ngươi hoặc con gái con gái ngươi; vì chúng là điều xấu hổ của chính ngươi.'),
(3263, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 18, 11, 'OT', 'Không được tiết lộ sự trần truồng của con gái vợ cha ngươi, người do cha ngươi sinh ra, vì nàng là em gái ngươi.'),
(3264, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 18, 12, 'OT', 'Chớ tiết lộ sự trần trụi của chị em ruột của cha ngươi; vì nàng là huyết thống của cha ngươi.'),
(3265, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 18, 13, 'OT', 'Chớ tiết lộ sự trần truồng của chị em ruột mẹ ngươi, vì nàng là huyết thống của mẹ ngươi.'),
(3266, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 18, 14, 'OT', 'Không được tiết lộ sự xấu hổ của anh trai cha ngươi; đừng đến gần vợ người ấy, vì người ấy là dì ngươi.'),
(3267, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 18, 15, 'OT', 'Chớ vén sự lõa thể của dâu ngươi; vì nàng là vợ con trai ngươi, chớ vén sự lõa thể của nàng.'),
(3268, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 18, 16, 'OT', 'Chớ vén sự trần truồng của vợ người anh em ngươi; ấy là sự trần truồng của người anh em ngươi.'),
(3269, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 18, 17, 'OT', 'Chớ tiết lộ sự trần truồng của người vợ và con gái nàng; chớ lấy con gái của con trai ngươi hoặc con gái của con gái ngươi để tiết lộ sự trần truồng nàng; chúng đều là người thân thích; làm điều đó là một sự gian ác.'),
(3270, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 18, 18, 'OT', 'Chớ lấy người đàn bà nào mà cùng lúc gả cho chị hoặc em của vợ mình, để làm lộ sự trần truồng nàng trước mặt nàng, khi nàng còn sống.'),
(3271, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 18, 19, 'OT', 'Chớ đến gần người nữ đang trong kỳ ô uế kinh nguyệt để lộ sự trần truồng của nàng.'),
(3272, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 18, 20, 'OT', 'Chớ giao hợp với vợ người đồng loại mình, để làm cho mình ô uế bởi người.'),
(3273, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 18, 21, 'OT', 'Chớ dâng một người nào trong dòng dõi mình cho thần Mo-lóc, và chớ làm profane danh Đức Chúa Trời ngươi; ta là Đức Giê-hô-va.'),
(3274, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 18, 22, 'OT', 'Chớ nằm với người nam như nằm với người nữ; ấy là điều đáng ghê tởm.'),
(3275, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 18, 23, 'OT', 'Chớ để giống các loài vật của ngươi để làm cho mình ra ô uế với nó; và một người đàn bà không được đứng trước mặt loài vật để ăn nằm với nó; ấy là sự gớm ghiếc.'),
(3276, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 18, 24, 'OT', 'Các ngươi chớ làm mình ô uế vì bất cứ điều gì như thế, vì các dân tộc mà ta sẽ đuổi khỏi trước mặt các ngươi đã trở nên ô uế vì những điều đó.'),
(3277, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 18, 25, 'OT', 'Đất bị ô uế, và Ta sẽ trừng phạt tội lỗi nó trên nó; đất sẽ khinh ghét những kẻ ở trong nó.'),
(3278, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 18, 26, 'OT', 'Các ngươi phải tuân giữ các luật lệ và các mạng lịnh của ta; cả người bản xứ lẫn người ngoại kiều sống giữa các ngươi, không được làm bất cứ điều gì gớm ghiếc nầy.'),
(3279, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 18, 27, 'OT', 'Vì dân các xứ trước các ngươi đã làm mọi điều ghê tởm này, nên đất đã bị ô uế.'),
(3280, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 18, 28, 'OT', 'Đừng để đất nôn ra các ngươi vì các ngươi làm đất ra ô uế, như đất đã nôn ra các dân tộc ở trước các ngươi.'),
(3281, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 18, 29, 'OT', 'Vì mọi người nào làm một trong những điều ghê tởm nầy sẽ bị truất khỏi giữa dân sự mình.'),
(3282, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 18, 30, 'OT', 'Vậy, các ngươi phải giữ những điều ta truyền dạy, để không làm theo các luật lệ gớm ghiếc đã được thực hành trước các ngươi, và các ngươi không được tự làm mình ô uế vì những điều đó. Ta là Đức Giê-hô-va Đức Chúa Trời của các ngươi.'),
(3283, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3284, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 2, 'OT', 'Hãy nói với toàn thể hội chúng Y-sơ-ra-ên rằng: Các ngươi phải nên thánh, vì ta, Đức Giê-hô-va Đức Chúa Trời các ngươi, là Đấng thánh.'),
(3285, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 3, 'OT', 'Mỗi người phải kính sợ cha mình và mẹ mình, và giữ các ngày Sa-bát ta; ta là Đức Giê-hô-va Đức Chúa Trời các ngươi.'),
(3286, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 4, 'OT', 'Chớ xây về các hình tượng, và các thần tượng bằng đúc các ngươi chớ làm cho mình; ta là Đức Giê-hô-va Đức Chúa Trời của các ngươi.'),
(3287, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 5, 'OT', 'Khi các ngươi dâng của lễ thù ân cho Đức Giê-hô-va, phải dâng một cách cho được nhậm;'),
(3288, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 6, 'OT', 'Phải ăn trong ngày các ngươi dâng của lễ; phần còn lại có thể ăn vào ngày hôm sau; nhưng bất cứ phần nào còn lại đến ngày thứ ba thì phải đốt trong lửa.'),
(3289, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 7, 'OT', 'Nếu còn ăn đến ngày thứ ba, thì điều đó trở thành gớm ghiếc, không được chấp nhận.'),
(3290, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 8, 'OT', 'Ai ăn của lễ ấy sẽ mang lấy tội mình, vì đã làm ô uế vật thánh của Đức Giê-hô-va; người ấy sẽ bị truất khỏi dân sự mình.'),
(3291, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 9, 'OT', 'Khi các ngươi gặt lúa trong ruộng mình, thì không được gặt đến tận cùng các đầu ruộng, và cũng không được mót những bông lúa còn sót lại.'),
(3292, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 10, 'OT', 'Các ngươi không được cắn mót nho mình, cũng không được nhặt những trái rớt lại nơi vườn nho; hãy để phần đó cho kẻ nghèo và cho người ngoại kiều. Ta là Đức Giê-hô-va Đức Chúa Trời của các ngươi.'),
(3293, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 11, 'OT', 'Các ngươi chớ trộm cắp, chớ chối tội, và chớ nói dối người đồng loại mình.'),
(3294, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 12, 'OT', 'Chớ chỉ danh Đức Giê-hô-va mà thề dối, để các ngươi khỏi làm profane danh của Đức Chúa Trời mình; ta là Đức Giê-hô-va.'),
(3295, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 13, 'OT', 'Không được ức hiếp người đồng loại, cũng không được cướp đoạt; tiền công của người làm thuê, không được để lại với ngươi cho đến sáng hôm sau.'),
(3296, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 14, 'OT', 'Chớ rủa sả người điếc, chớ để trước mặt người mù vật làm cho vấp ngã; ngươi phải kính sợ Đức Chúa Trời ngươi: Ta là Đức Giê-hô-va.'),
(3297, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 15, 'OT', 'Không được làm điều bất công trong xét xử, không được thiên vị người nghèo, cũng không được nể mặt người quyền quý; phải xét xử người đồng loại mình cách công bình.'),
(3298, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 16, 'OT', 'Chớ đi rêu rao tin đồn trong dân sự mình; chớ đứng yên khi mạng sống của người đồng loại mình bị đe dọa: Ta là Đức Giê-hô-va.'),
(3299, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 17, 'OT', 'Chớ ghét anh em mình trong lòng; phải thẳng thắn sửa trách người đồng loại mình, và đừng mang tội thay cho người ấy.'),
(3300, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 18, 'OT', 'Chớ báo thù và chớ oán hận con cái dân ngươi; nhưng hãy yêu kẻ lân cận ngươi như chính mình ngươi: Ta là Đức Giê-hô-va.'),
(3301, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 19, 'OT', 'Hãy giữ các mạng lệnh của Ta: vật súc vật ngươi không được phối giống khác loài; ruộng ngươi không được gieo hai thứ giống; và áo dệt bằng nhiều thứ chỉ thì không được mặc trên mình ngươi.'),
(3302, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 20, 'OT', 'Nếu một người đàn ông nằm cùng một người phụ nữ, giao hợp với nàng, mà nàng là một nữ tớ gái đã đính hôn với một người đàn ông, nhưng chưa được chuộc bằng tiền chuộc, hay chưa được ban tự do, thì hai người sẽ bị phạt; họ sẽ không bị xử tử, vì nàng chưa được giải thoát.'),
(3303, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 21, 'OT', 'Người ấy phải đem của lễ chuộc lỗi mình đến Đức Giê-hô-va, tại cửa Hội mạc, một con chiên đực để làm của lễ chuộc lỗi.'),
(3304, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 22, 'OT', 'Thầy tế lễ sẽ dùng con chiên đực làm của lễ chuộc tội mà làm lễ chuộc cho người ấy trước mặt Đức Giê-hô-va vì tội mà người ấy đã phạm; và người ấy sẽ được tha cho tội mà người ấy đã phạm.'),
(3305, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 23, 'OT', 'Khi các ngươi vào đất Ca-na-an và trồng mọi thứ cây ăn trái, hãy coi trái nó như chưa chịu phép cắt bì; trong ba năm, trái nó sẽ không được phép ăn cho các ngươi.'),
(3306, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 24, 'OT', 'Sang năm thứ tư, toàn thể trái của nó sẽ là điều thánh, dùng làm lễ ca ngợi Đức Giê-hô-va.'),
(3307, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 25, 'OT', 'Qua năm thứ năm, các ngươi phải ăn trái của nó, để nó thêm hoa quả cho các ngươi. Ta là Đức Giê-hô-va Đức Chúa Trời của các ngươi.'),
(3308, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 26, 'OT', 'Các ngươi không được ăn gì có huyết; các ngươi không được bói toán, cũng không được đoán vận mệnh.'),
(3309, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 27, 'OT', 'Không được cắt xén mép tóc mình, và không được làm hư hại mép râu mình.'),
(3310, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 28, 'OT', 'Chớ vì kẻ chết mà rạch thân mình, và chớ xăm hình trên mình các ngươi; Ta là Đức Giê-hô-va.'),
(3311, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 29, 'OT', 'Chớ làm ô danh con gái ngươi khiến nó phải đi làm gái điếm, để đất không bị bại hoại và đầy dẫy điều gian ác.'),
(3312, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 30, 'OT', 'Các ngươi phải giữ các ngày sa-bát của ta và kính sợ nơi thánh của ta; ta là Đức Giê-hô-va.'),
(3313, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 31, 'OT', 'Chớ hướng về các đồng cốt và thầy bói, chớ tìm cầu chúng để bị ô uế bởi chúng; ta là Đức Giê-hô-va, Đức Chúa Trời của các ngươi.'),
(3314, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 32, 'OT', 'Trước mặt người tóc bạc, ngươi phải đứng dậy và kính trọng người già; ngươi phải kính sợ Đức Chúa Trời ngươi. Ta là Đức Giê-hô-va.'),
(3315, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 33, 'OT', 'Khi một người ngoại kiều cư ngụ cùng các ngươi trong đất nước các ngươi, thì các ngươi không được hà hiếp người ấy.'),
(3316, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 34, 'OT', 'Người ngoại kiều sống giữa các ngươi sẽ được đối xử như người bản xứ; ngươi phải yêu người ấy như chính mình, vì các ngươi đã từng là ngoại kiều tại đất Ai-cập. Ta là Đức Giê-hô-va, Đức Chúa Trời của các ngươi.'),
(3317, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 35, 'OT', 'Các ngươi không được làm điều bất công trong xét xử, trong đơn vị đo lường, trong cân nặng hoặc trong thước đo.'),
(3318, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 36, 'OT', 'Các ngươi phải có cân công bằng, những hòn đá bằng đá công bằng, một ê-pha công bằng và một hin công bằng sẽ thuộc về các ngươi. Ta là Đức Giê-hô-va Đức Chúa Trời của các ngươi, Đấng đã đem các ngươi ra khỏi đất Ê-díp-tô.'),
(3319, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 19, 37, 'OT', 'Vậy, các ngươi phải giữ mọi luật lệ và mọi mạng lịnh ta, và phải thực hành chúng; Ta là Đức Giê-hô-va.'),
(3320, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 20, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3321, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 20, 2, 'OT', 'Hãy nói cùng con cái Y-sơ-ra-ên rằng: Người nào, hoặc trong con cái Y-sơ-ra-ên hoặc khách kiều ngụ giữa vòng Y-sơ-ra-ên, dâng một trong con mình cho thần Mo-lóc, thì chắc sẽ bị xử tử; dân trong xứ phải ném đá người ấy.'),
(3322, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 20, 3, 'OT', 'Ta sẽ nghiêm mặt cùng người ấy, truất nó khỏi giữa dân sự nó, vì nó đã nộp con cái mình cho thần Mo-lóc, để làm ô uế nơi thánh của Ta và xúc phạm đến danh thánh của Ta.'),
(3323, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 20, 4, 'OT', 'Nếu dân trong xứ nhắm mắt mình khỏi người đàn ông ấy, vì người ấy dâng một trong các con cái mình cho thần Mo-lóc, mà không giết người ấy,'),
(3324, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 20, 5, 'OT', 'Ta đây sẽ đặt mặt Ta đối cùng người đàn ông ấy và cùng dòng họ người ấy; Ta sẽ truất người ấy và tất cả những kẻ dâm dục theo sau người ấy mà dâm dục theo sau thần Mo-lóc, khỏi giữa dân sự mình.'),
(3325, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 20, 6, 'OT', 'Nếu ai xây về những kẻ đồng cốt và những kẻ bói toán, mà thông dâm cùng chúng, thì ta sẽ quay mặt chống lại người đó, và sẽ truất nó khỏi giữa dân sự nó.'),
(3326, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 20, 7, 'OT', 'Hãy làm cho mình nên thánh và phải thánh, vì ta là Đức Giê-hô-va Đức Chúa Trời của các ngươi.'),
(3327, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 20, 8, 'OT', 'Các ngươi phải giữ các mạng lịnh ta và làm theo; Ta là Đức Giê-hô-va, Đấng làm cho các ngươi nên thánh.'),
(3328, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 20, 9, 'OT', 'Người nào chúc dữ cha mình hay mẹ mình, thì phải bị xử tử; người đó đã chúc dữ cha mẹ mình, huyết nó sẽ đổ lại trên mình nó.'),
(3329, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 20, 10, 'OT', 'Người đàn ông nào phạm tội thông dâm với vợ của người khác, hay là phạm tội thông dâm với vợ người đồng loại mình, thì kẻ thông dâm và người đàn bà thông dâm phải bị xử tử.'),
(3330, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 20, 11, 'OT', 'Người nào nằm cùng vợ của cha mình, tức là phơi bày sự trần truồng của cha mình, thì cả hai người ấy phải bị giết chết; huyết của họ sẽ đổ lại trên mình họ.'),
(3331, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 20, 12, 'OT', 'Người đàn ông nào nằm với con dâu mình, cả hai đều phải bị giết chết; họ đã làm điều gớm ghiếc, huyết các người ấy sẽ đổ lại trên mình họ.'),
(3332, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 20, 13, 'OT', 'Người nam nào nằm cùng người nam khác như nằm cùng người nữ, thì cả hai đều đã làm điều ghê tởm; họ phải bị xử tử, huyết các người đó sẽ đổ lại trên mình họ.'),
(3333, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 20, 14, 'OT', 'Nếu một người đàn ông lấy vợ mình và cả mẹ vợ, ấy là điều gian ác; cả người ấy và hai người phụ nữ phải bị thiêu cháy, hầu cho điều gian ác không còn ở giữa các ngươi.'),
(3334, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 20, 15, 'OT', 'Người nào nằm cùng thú vật, thì phải bị xử tử; còn thú vật ấy, các ngươi phải giết đi.'),
(3335, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 20, 16, 'OT', 'Người đàn bà nào lại gần bất kỳ loài vật nào để giao hợp với nó, thì phải giết người đàn bà ấy và con vật ấy; chúng phải bị giết chết, huyết họ sẽ ở trên chính mình họ.'),
(3336, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 20, 17, 'OT', 'Người đàn ông nào lấy chị hoặc em gái mình, con gái của cha mình hay con gái của mẹ mình, và thấy sự trần truồng của nàng, và nàng cũng thấy sự trần truồng của người ấy, thì đó là điều gớm ghê; cả hai sẽ bị truất khỏi trước mặt con cái dân sự mình; người đã để lộ sự trần truồng của chị em mình sẽ mang tội mình.'),
(3337, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 20, 18, 'OT', 'Người nam nào nằm cùng người nữ đang trong kỳ kinh nguyệt và để lộ phần kín của nàng, tức là đã xâm phạm mạch sống của nàng, và chính nàng cũng tiết lộ mạch máu của mình, thì cả hai người ấy sẽ bị truất khỏi giữa lòng dân sự họ.'),
(3338, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 20, 19, 'OT', 'Chớ tiết lộ sự trần truồng của chị em ruột mẹ ngươi và chị em ruột cha ngươi; vì người đã để lộ sự thân thuộc của mình; chính họ sẽ mang tội ác mình.'),
(3339, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 20, 20, 'OT', 'Người nam nào nằm cùng bác gái hay thím mình, tức là đã làm lộ sự trần truồng của chú bác mình; cả hai sẽ mang tội mình, phải chết không con nối dòng.'),
(3340, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 20, 21, 'OT', 'Người nào lấy vợ anh mình là làm điều ô uế; người ấy đã tiết lộ sự trần truồng của anh mình; họ sẽ không có con cháu.'),
(3341, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 20, 22, 'OT', 'Các ngươi phải giữ và làm theo mọi luật lệ và mọi mạng lịnh của ta, hầu cho đất mà ta dẫn các ngươi đến để ở không mửa các ngươi ra.'),
(3342, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 20, 23, 'OT', 'Các ngươi chớ đi theo các luật lệ của dân tộc mà Ta sắp đuổi ra khỏi mặt các ngươi; vì chúng đã làm tất cả những điều ấy, nên Ta lấy làm ghê tởm chúng.'),
(3343, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 20, 24, 'OT', 'Ta đã nói cùng các ngươi rằng: Các ngươi sẽ được hưởng đất của chúng nó; chính ta sẽ ban cho các ngươi đất ấy để chiếm lấy, một đất chảy sữa và mật; ta là Giê-hô-va Đức Chúa Trời của các ngươi, Đấng đã phân rẽ các ngươi khỏi các dân.'),
(3344, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 20, 25, 'OT', 'Các ngươi phải phân biệt giữa loài vật sạch và loài vật không sạch, giữa loài chim không sạch và loài chim sạch; các ngươi không được làm cho linh hồn mình ra gớm ghiếc vì loài vật, vì chim chóc, hay vì mọi loài bò sát trên đất mà ta đã phân biệt cho các ngươi để làm cho các ngươi ra ô uế.'),
(3345, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 20, 26, 'OT', 'Các ngươi phải nên thánh cho ta, vì ta, Đức Giê-hô-va, là thánh; và ta đã biệt các ngươi ra khỏi các dân để các ngươi thuộc về ta.'),
(3346, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 20, 27, 'OT', 'Người nam hay người nữ nào có trong mình thần đồng cốt hay thầy bói, thì phải bị xử tử bằng đá; huyết họ sẽ đổ trên chính mình họ.'),
(3347, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 21, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Hãy nói cùng các thầy tế lễ là con trai A-rôn, và bảo họ: Đừng để mình bị ô uế vì một người chết trong dân sự mình.'),
(3348, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 21, 2, 'OT', 'trừ ra vì người thân cận với mình, vì mẹ mình và vì cha mình, vì con trai mình và con gái mình, và vì anh em mình,'),
(3349, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 21, 3, 'OT', 'Và vì chị em gái đồng trinh, người thân cận với người đó, chưa từng thuộc về người đàn ông nào, thì người ấy có thể làm mình ra ô uế.'),
(3350, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 21, 4, 'OT', 'Đừng để mình bị ô uế trong dân sự mình, để làm mình ra tục.'),
(3351, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 21, 5, 'OT', 'Các thầy tế lễ không được cạo trọc đầu mình, không được cạo mép râu mình, và không được xẻ thịt mình.'),
(3352, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 21, 6, 'OT', 'Họ phải nên thánh cho Đức Chúa Trời mình, và không được làm profane danh Ngài, vì họ dâng các lễ vật dùng lửa thiêu cho Đức Giê-hô-va, tức là thức ăn của Đức Chúa Trời mình; họ phải nên thánh.'),
(3353, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 21, 7, 'OT', 'Đừng cưới một người đàn bà là kẻ dâm dật hay là kẻ ô uế, và đừng cưới một người đàn bà đã bị chồng để; vì thầy tế lễ là người biệt riêng ra thánh cho Đức Chúa Trời mình.'),
(3354, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 21, 8, 'OT', 'Vậy, ngươi hãy thánh hóa người, vì người dâng bánh của Đức Chúa Trời ngươi; người phải thánh cho ngươi, vì ta là Đức Giê-hô-va, Đấng thánh hóa các ngươi.'),
(3355, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 21, 9, 'OT', 'Nếu con gái của một thầy tế lễ phạm tội dâm loạn, nó sẽ làm ô danh cho cha mình; nó phải bị thiêu bằng lửa.'),
(3356, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 21, 10, 'OT', 'Thầy tế lễ cả, người được xức dầu thánh trên đầu và được biệt riêng ra thánh để mặc các áo lễ, là người đứng trội hơn các anh em mình; người ấy không được để đầu trần và không được xé các áo mình.'),
(3357, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 21, 11, 'OT', 'Chớ đến gần bất kỳ người chết nào, cũng không được làm mình ra ô uế vì cha hay mẹ mình.'),
(3358, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 21, 12, 'OT', 'Người không được ra khỏi nơi thánh, và không được làm ô uế nơi thánh của Đức Chúa Trời mình, vì mão dầu xức của Đức Chúa Trời mình còn trên đầu người; Ta là Đức Giê-hô-va.'),
(3359, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 21, 13, 'OT', 'Người phải lấy người phụ nữ đồng trinh làm vợ.'),
(3360, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 21, 14, 'OT', 'Người không được cưới đàn bà goá, bị ruồng bỏ, người bị làm ô uế hay là kẻ hành dâm; nhưng phải cưới một trinh nữ trong dân mình.'),
(3361, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 21, 15, 'OT', 'Người không được làm ô uế dòng dõi mình giữa các dân tộc mình, vì ta là Đức Giê-hô-va, Đấng làm cho người nên thánh.'),
(3362, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 21, 16, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3363, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 21, 17, 'OT', 'Hãy nói cùng A-rôn rằng: Một người nào trong dòng dõi ngươi, trải qua các thế hệ, mà có dị tật trong thân thể, thì không được đến gần để dâng của lễ thực phẩm cho Đức Chúa Trời mình.'),
(3364, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 21, 18, 'OT', 'Mọi người nào mang dị tật thì không được đến gần, tức là người mù, hay què, hay vẹo mũi, hay tay chân không đều.'),
(3365, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 21, 19, 'OT', 'hoặc một người có chân hay tay bị gãy,'),
(3366, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 21, 20, 'OT', 'hay là gù, hay là lùn, hay là có vết trắng trong mắt, hay là ghẻ, hay là vảy cá, hay là tinh hoàn bị dập.'),
(3367, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 21, 21, 'OT', 'Mọi người nào trong dòng dõi thầy tế lễ A-rôn mà có tật, thì không được đến gần để dâng các của lễ thiêu của Đức Giê-hô-va; người ấy có tật trong mình, nên không được đến gần dâng bánh của Đức Chúa Trời mình.'),
(3368, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 21, 22, 'OT', 'Người được ăn bánh của Đức Chúa Trời mình, tức các vật thánh và các vật chí thánh.'),
(3369, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 21, 23, 'OT', 'Nhưng không được đến gần bức màn, cũng không được đến gần bàn thờ, vì người ấy có tật; như vậy sẽ không làm ô uế các nơi thánh ta, vì ta, Đức Giê-hô-va, là Đấng khiến các nơi ấy nên thánh.'),
(3370, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 21, 24, 'OT', 'Môi-se nói với A-rôn, các con trai người và tất cả các con trai của Y-sơ-ra-ên.'),
(3371, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3372, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 2, 'OT', 'Hãy nói cùng A-rôn và các con trai người rằng phải giữ mình khỏi các vật thánh của con cái Y-sơ-ra-ên, không được làm profane danh thánh ta mà họ biệt riêng ra thánh cho ta; ta là Đức Giê-hô-va.'),
(3373, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 3, 'OT', 'Hãy nói cùng họ: Mọi người trong dòng dõi các ngươi, nếu đến gần các vật thánh mà con cái Y-sơ-ra-ên biệt riêng cho Đức Giê-hô-va, mà người ấy còn mang sự ô uế của mình, thì linh hồn ấy sẽ bị truất khỏi trước mặt ta: Ta là Đức Giê-hô-va.'),
(3374, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 4, 'OT', 'Người nào là dòng dõi của A-rôn, nếu bị phung hay bị xuất tinh, thì không được ăn các vật thánh cho đến khi được làm sạch; và người nào đụng đến bất cứ người chết nào bị ô uế, hay là người nào có sự xuất tinh,'),
(3375, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 5, 'OT', 'hoặc một người chạm vào bất kỳ loài vật bò sát nào làm cho mình trở nên ô uế, hay một người nào bị ô uế bởi bất cứ sự ô uế nào của người ấy, thì cũng phải như vậy.'),
(3376, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 6, 'OT', 'Người nào rờ đến các vật ấy sẽ bị ô uế cho đến chiều tối, và không được ăn các vật thánh, trừ khi đã rửa thân thể trong nước.'),
(3377, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 7, 'OT', 'Mặt trời lặn rồi người ấy sẽ được sạch, sau đó mới được ăn các vật thánh, vì đó là lương thực của người ấy.'),
(3378, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 8, 'OT', 'Đừng ăn một con vật chết tự nhiên hay bị xé, hầu khỏi bị ô uế vì điều đó; Ta là Đức Giê-hô-va.'),
(3379, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 9, 'OT', 'Họ phải giữ các điều ta truyền, để khỏi mang tội vì phạm đến vật thánh và chết vì làm ô uế nó; ta là Đức Giê-hô-va, Đấng làm cho họ nên thánh.'),
(3380, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 10, 'OT', 'Người ngoại nào cũng không được ăn vật thánh; người ở nhờ hay người làm thuê trong nhà thầy tế lễ cũng không được ăn vật thánh.'),
(3381, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 11, 'OT', 'Nhưng nếu thầy tế lễ mua một người hầu bằng tiền của mình, thì người ấy được ăn; và những người sinh ra trong nhà người ấy cũng được ăn thức ăn của người ấy.'),
(3382, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 12, 'OT', 'Nếu con gái thầy tế lễ lấy người ngoài, thì nàng không được ăn các phần thánh của lễ chí thánh.'),
(3383, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 13, 'OT', 'Nếu con gái thầy tế lễ là góa phụ hay bị bỏ, không có con, và trở về nhà cha mình như lúc còn trẻ, thì nàng sẽ được ăn bánh của cha mình; nhưng người ngoài không được ăn cùng.'),
(3384, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 14, 'OT', 'Nếu một người nào lỡ ăn vật thánh, phải đền cho thầy tế lễ giá của vật thánh đó, lại thêm một phần năm.'),
(3385, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 15, 'OT', 'Chúng nó sẽ không được làm ô uế các vật thánh mà con cái Y-sơ-ra-ên dâng giơ lên cho Đức Giê-hô-va.'),
(3386, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 16, 'OT', 'Chúng sẽ mang tội mình vì ăn các vật thánh, khi các vật đó đã được biệt riêng ra; vì ta là Đức Giê-hô-va, Đấng làm cho chúng nên thánh.'),
(3387, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 17, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3388, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 18, 'OT', 'Hãy nói với A-rôn và các con trai người, cùng với mọi con cái Y-sơ-ra-ên mà rằng: Mỗi người, người nào thuộc nhà Y-sơ-ra-ên hoặc khách kiều ngụ trong Y-sơ-ra-ên, khi dâng lễ vật cho Đức Giê-hô-va, dù là của lễ khấn, hay là của lễ tự nguyện, đều phải dâng làm của lễ thiêu.'),
(3389, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 19, 'OT', 'phải dâng một con đực không tật nguyền, trong bò, trong chiên hoặc trong dê.'),
(3390, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 20, 'OT', 'Mọi vật nào có tật, các ngươi không được dâng; vì nó sẽ không được đẹp lòng các ngươi.'),
(3391, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 21, 'OT', 'Người nào dâng cho Đức Giê-hô-va của lễ thù ân, hoặc dâng lễ khấn, hoặc dâng lễ lạc ý, bằng bò hay bằng chiên, phải được nhậm, con sinh vật ấy phải không tì vít chi.'),
(3392, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 22, 'OT', 'Không được dâng cho Đức Giê-hô-va những con vật mù, què, xé, hủi, ghẻ hay vảy cá; các ngươi cũng không được dâng những con đó làm của lễ thiêu trên bàn thờ cho Đức Giê-hô-va.'),
(3393, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 23, 'OT', 'Bò hay chiên có chân dài quá hoặc ngắn quá, các ngươi có thể dâng làm của lễ lạc ý; nhưng để làm của lễ khấn nguyện, thì sẽ không được chấp nhận.'),
(3394, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 24, 'OT', 'Chớ dâng cho Đức Giê-hô-va những con vật bị dập nát, bị đứt, bị rứt hay bị thiến; tại xứ các ngươi cũng không được làm điều đó.'),
(3395, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 25, 'OT', 'Chớ dâng của lễ từ tay con người ngoại bang nào cho Đức Chúa Trời các ngươi, vì trong các thứ đó có điều sứt thiếu và tì vít; chúng sẽ không được chấp nhận cho các ngươi.'),
(3396, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 26, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3397, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 27, 'OT', 'Bò con, chiên con, hay dê con, khi sinh ra phải ở dưới mẹ nó bảy ngày; từ ngày thứ tám trở đi, nó sẽ được nhận để dâng làm của lễ thiêu cho Đức Giê-hô-va.'),
(3398, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 28, 'OT', 'Bò cái hay chiên cái, các ngươi không được giết nó cùng con nó trong một ngày.'),
(3399, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 29, 'OT', 'Khi các ngươi dâng của lễ thù ân cho Đức Giê-hô-va, phải dâng cách cho các ngươi được nhậm.'),
(3400, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 30, 'OT', 'Ngày ấy phải ăn, các ngươi không được để phần nào còn lại đến sáng mai. Ta là Đức Giê-hô-va.'),
(3401, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 31, 'OT', 'Vậy, các ngươi phải giữ các điều răn của ta và làm theo; ta là Đức Giê-hô-va.'),
(3402, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 32, 'OT', 'Chớ làm ô danh thánh ta, để ta được tôn làm thánh giữa vòng con cái Y-sơ-ra-ên; ta là Đức Giê-hô-va, Đấng làm cho các ngươi nên thánh.'),
(3403, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 22, 33, 'OT', 'Là Đấng đã đem các ngươi ra khỏi đất Ai Cập, để làm Đức Chúa Trời cho các ngươi; chính Ta là Đức Giê-hô-va.'),
(3404, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3405, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 2, 'OT', 'Hãy nói cùng con cái Y-sơ-ra-ên và bảo họ: Nầy là những kỳ lễ của Đức Giê-hô-va, mà các ngươi phải gọi là các cuộc họp thánh; ấy là những kỳ lễ của ta.'),
(3406, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 3, 'OT', 'Sáu ngày có thể làm việc, nhưng ngày thứ bảy là ngày Sa-bát, ngày nghỉ lễ thiêng liêng, một sự nhóm họp thánh; không được làm bất cứ công việc gì; ấy là ngày Sa-bát dành cho Đức Giê-hô-va tại mọi nơi các ngươi ở.'),
(3407, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 4, 'OT', 'Đây là những lễ của Đức Giê-hô-va, tức những cuộc nhóm họp thánh, mà các ngươi phải công bố đúng thì giờ của chúng.'),
(3408, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 5, 'OT', 'Vào ngày mười bốn tháng giêng, giữa chiều tối, là lễ Vượt-qua của Đức Giê-hô-va.'),
(3409, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 6, 'OT', 'Vào ngày mười lăm của tháng này là lễ bánh không men để kính trọng Đức Giê-hô-va; các ngươi sẽ ăn bánh không men trong bảy ngày.'),
(3410, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 7, 'OT', 'Ngày đầu tiên sẽ là một ngày nhóm họp thánh cho các ngươi; các ngươi không được làm bất cứ công việc phục vụ nào.'),
(3411, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 8, 'OT', 'Trong bảy ngày, các ngươi phải dâng cho Đức Giê-hô-va những của lễ dùng lửa dâng lên; ngày thứ bảy sẽ là một ngày nhóm hiệp thánh, mọi công việc làm không được làm.'),
(3412, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 9, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3413, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 10, 'OT', 'Hãy nói với con cái Y-sơ-ra-ên rằng: Khi các ngươi vào đất mà Ta sẽ ban cho các ngươi, và các ngươi gặt mùa màng rồi, thì phải đem đến cho thầy tế lễ bó lúa đầu mùa của mùa gặt các ngươi.'),
(3414, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 11, 'OT', 'Ngày sau ngày sa-bát, thầy tế lễ sẽ đưa bó lúa đầu mùa qua lại trước mặt Đức Giê-hô-va, để các ngươi được nhậm.'),
(3415, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 12, 'OT', 'Ngày các ngươi dâng bó lúa đưa qua đưa lại, phải dâng cho Đức Giê-hô-va một chiên con đực giáp năm, không tì vít, làm của lễ thiêu;'),
(3416, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 13, 'OT', 'và của lễ chay người đó dâng là hai phần mười phần e-phah bột lọc trộn dầu, làm của lễ thiêu dâng lên Đức Giê-hô-va, một mùi hương dễ chịu; còn lễ quán của người đó là một phần tư hin rượu.'),
(3417, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 14, 'OT', 'Các ngươi không được ăn bánh, hoặc lúa rang, hoặc lúa mới, cho đến chính ngày nầy, cho đến khi các ngươi dâng của lễ cho Đức Chúa Trời mình. Đó là một luật lệ đời đời cho các thế hệ các ngươi, trong mọi nơi ở của các ngươi.'),
(3418, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 15, 'OT', 'Các ngươi phải tính cho mình kể từ ngày sau ngày Sa-bát, tức ngày các ngươi mang lễ vật là bó lúa đầu mùa dâng đưa qua đưa lại: bảy tuần lễ trọn sẽ phải được kể.'),
(3419, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 16, 'OT', 'Cho đến ngày sau ngày Sa-bát thứ bảy, các ngươi phải đếm đủ năm mươi ngày, rồi dâng một lễ vật mới cho Đức Giê-hô-va.'),
(3420, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 17, 'OT', 'Các ngươi phải đem từ nơi mình ở hai ổ bánh làm lễ dâng đưa qua đưa lại, mỗi ổ bằng hai phần mười ê-pha bột mịn, phải được làm men; đó là những sản phẩm đầu mùa dâng cho Đức Giê-hô-va.'),
(3421, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 18, 'OT', 'Các ngươi phải dâng trên bánh ấy bảy chiên con trọn vẹn, con đực một tuổi, một con bò tơ và hai con chiên đực; chúng phải là của lễ thiêu dâng cho Đức Giê-hô-va, cùng với của lễ chay và lễ quán của chúng, là của lễ dùng lửa, có mùi thơm cho Đức Giê-hô-va.'),
(3422, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 19, 'OT', 'Các ngươi cũng phải dâng một con dê đực để làm của lễ chuộc tội, và hai chiên con một tuổi để làm của lễ thù ân.'),
(3423, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 20, 'OT', 'Thầy tế lễ sẽ dâng đưa qua đưa lại những vật đó cùng với hai ổ bánh đầu mùa trước mặt Đức Giê-hô-va, làm lễ đưa qua đưa lại; hai chiên con sẽ là của lễ thánh dành riêng cho Đức Giê-hô-va, thuộc về thầy tế lễ.'),
(3424, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 21, 'OT', 'Các ngươi hãy công bố trong chính ngày nầy một sự nhóm hiệp thánh sẽ thuộc về các ngươi; mọi công việc làm ăn đều không được làm; ấy là một điều luật đời đời trong mọi nơi ở của các ngươi, cho các dòng dõi các ngươi.'),
(3425, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 22, 'OT', 'Khi các ngươi gặt lúa trong đất các ngươi, thì không được gặt tận cùng các đầu đồng; cũng không được mót lúa đã gặt; hãy để phần đó cho người nghèo và cho kẻ ngoại bang. Ta là Đức Giê-hô-va, Đức Chúa Trời của các ngươi.'),
(3426, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 23, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3427, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 24, 'OT', 'Hãy nói với dân Y-sơ-ra-ên rằng: Trong tháng bảy, ngày mồng một tháng ấy, sẽ là ngày nghỉ ngơi, một lễ kỷ niệm lấy tiếng thổi kèn báo hiệu, một sự nhóm hiệp thánh.'),
(3428, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 25, 'OT', 'Chớ làm bất cứ công việc phục dịch nào; phải dâng của lễ thiêu cho Đức Giê-hô-va.'),
(3429, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 26, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3430, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 27, 'OT', 'Chỉ ngày mười tháng bảy nầy là ngày lễ Khuôn Tội; các ngươi sẽ có sự nhóm hiệp thánh; hãy ép tâm hồn mình và dâng cho Đức Giê-hô-va của lễ dùng lửa dâng lên.'),
(3431, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 28, 'OT', 'Trong chính ngày nầy, các ngươi không được làm bất cứ công việc gì, vì là ngày lễ Chuộc Tội, đặng làm lễ chuộc tội cho các ngươi trước mặt Đức Giê-hô-va, Đức Chúa Trời các ngươi.'),
(3432, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 29, 'OT', 'Vì mọi linh hồn nào không ép mình chịu khổ trong chính ngày nầy, sẽ bị truất khỏi dân sự mình.'),
(3433, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 30, 'OT', 'Mọi người nào làm bất cứ công việc gì trong chính ngày nầy, thì ta sẽ diệt người đó khỏi giữa vòng dân sự mình.'),
(3434, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 31, 'OT', 'Chớ làm bất kỳ công việc gì; ấy là một luật lệ đời đời cho các thế hệ của các ngươi, trong mọi nơi các ngươi ở.'),
(3435, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 32, 'OT', 'Đó sẽ là ngày Sa-bát trọn vẹn cho các ngươi, và các ngươi phải tự tiết chế linh hồn mình. Vào ngày mồng chín của tháng ấy, từ chiều hôm nay cho đến chiều ngày mai, các ngươi phải giữ ngày Sa-bát của mình.'),
(3436, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 33, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3437, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 34, 'OT', 'Hãy nói cùng con cái Y-sơ-ra-ên rằng: Ngày mười lăm tháng nầy, là tháng bảy, các ngươi sẽ giữ lễ Lều Tạm trong bảy ngày cho Đức Giê-hô-va.'),
(3438, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 35, 'OT', 'Ngày đầu tiên sẽ là ngày nhóm họp thánh, mọi công việc làm thuê các ngươi không được làm.'),
(3439, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 36, 'OT', 'Trong bảy ngày phải dâng của lễ thiêu cho Đức Giê-hô-va; ngày thứ tám sẽ là ngày hội thánh đối với các ngươi, và các ngươi phải dâng của lễ thiêu cho Đức Giê-hô-va. Đó là ngày nghỉ lễ trọng thể; các ngươi không được làm bất cứ công việc nào.'),
(3440, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 37, 'OT', 'Đây là các ngày lễ trọng của Đức Giê-hô-va, mà các ngươi phải công bố là những cuộc nhóm họp thánh, để dâng cho Đức Giê-hô-va của lễ dùng lửa, của lễ thiêu, của lễ chay, của lễ thù ân và lễ quán, mỗi ngày một phần việc đã định.'),
(3441, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 38, 'OT', 'Ngoài các ngày sa-bát của Đức Giê-hô-va, và ngoài các lễ vật bắt buộc, các lời khấn, cùng mọi của lễ tự nguyện mà các ngươi dâng cho Đức Giê-hô-va.'),
(3442, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 39, 'OT', 'Tuy nhiên, vào ngày mười lăm tháng bảy, khi các ngươi đã thu hoạch sản vật của đất xong, phải giữ lễ cho Đức Giê-hô-va trong bảy ngày. Ngày thứ nhất là ngày nghỉ lễ, và ngày thứ tám cũng là ngày nghỉ lễ.'),
(3443, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 40, 'OT', 'Các ngươi hãy lấy cho mình trong ngày đầu tiên trái cây tốt, tàu lá chà là, nhành cây rậm và cây dương liễu, rồi vui mừng trước mặt Đức Giê-hô-va, Đức Chúa Trời của các ngươi bảy ngày.'),
(3444, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 41, 'OT', 'Các ngươi phải giữ lễ cho Đức Giê-hô-va trong bảy ngày mỗi năm, vào tháng bảy; các ngươi phải giữ lễ nầy như một luật lệ đời đời cho các thế hệ các ngươi.'),
(3445, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 42, 'OT', 'Các ngươi sẽ ở trong các trại trong bảy ngày; mọi người Y-sơ-ra-ên sẽ ở trong các trại,'),
(3446, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 43, 'OT', 'để dòng dõi các ngươi biết rằng Ta đã cho con cái Y-sơ-ra-ên ở trong những cái lều khi Ta đem họ ra khỏi đất Ê-díp-tô; Ta là Đức Giê-hô-va Đức Chúa Trời của các ngươi.'),
(3447, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 23, 44, 'OT', 'Môi-se nói cho con cái Y-sơ-ra-ên biết các lễ hội của Đức Giê-hô-va.'),
(3448, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 24, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3449, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 24, 2, 'OT', 'Hãy truyền cho con cái Y-sơ-ra-ên đem dầu ô-liu nguyên chất ép ra đến cùng ngươi, để thắp đèn, hầu cho ngọn đèn cháy luôn luôn.'),
(3450, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 24, 3, 'OT', 'A-rôn sẽ sắp đặt đèn đó bên ngoài bức màn che hòm chứng, trong hội mạc, để đèn cháy luôn từ chiều tối cho đến sáng sớm trước mặt Đức Giê-hô-va, làm luật lệ đời đời cho dòng dõi các ngươi.'),
(3451, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 24, 4, 'OT', 'A-rôn phải sửa các ngọn đèn trên chân đèn bằng vàng tinh sạch, để các ngọn đèn cháy trước mặt Đức Giê-hô-va luôn mãi.'),
(3452, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 24, 5, 'OT', 'Ngươi phải lấy bột mịn, rồi nướng thành mười hai ổ bánh; mỗi ổ dùng hai phần mười ê-pha bột.'),
(3453, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 24, 6, 'OT', 'Đoạn sắp ra hai hàng, mỗi hàng sáu ổ, trên cái bàn thánh trước mặt Đức Giê-hô-va.'),
(3454, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 24, 7, 'OT', 'Ngươi phải đặt trên bàn xếp bánh mì tấm thanh sạch, và nó sẽ là của lễ tưởng nhớ cho bánh, tức là của lễ dùng lửa dâng cho Đức Giê-hô-va.'),
(3455, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 24, 8, 'OT', 'Mỗi ngày sa-bát, phải lần lượt đặt bánh trước mặt Đức Giê-hô-va luôn luôn, do dân Y-sơ-ra-ên cung cấp; ấy là một giao ước đời đời.'),
(3456, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 24, 9, 'OT', 'Các bánh ấy sẽ thuộc về A-rôn và các con trai người; họ phải ăn tại một nơi thánh, vì đó là vật chí thánh dành cho người, từ các lễ vật thiêu đốt dâng cho Đức Giê-hô-va, một luật lệ đời đời.'),
(3457, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 24, 10, 'OT', 'Có một người con trai, mẹ là người Y-sơ-ra-ên, còn cha là người Ai Cập, đã đi ra giữa vòng con cái Y-sơ-ra-ên; và người con trai người Y-sơ-ra-ên và một người Y-sơ-ra-ên đã đánh nhau trong trại quân.'),
(3458, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 24, 11, 'OT', 'Con trai người đàn bà người Y-sơ-ra-ên đã nguyền rủa và nói phạm đến danh Đức Giê-hô-va; người ta đem nó đến cùng Môi-se, tên mẹ nó là Sê-lô-mít, con gái Điệp-ri, thuộc chi phái Đan.'),
(3459, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 24, 12, 'OT', 'Họ giam ông tại nơi giam giữ để Đức Giê-hô-va phán dạy họ.'),
(3460, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 24, 13, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3461, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 24, 14, 'OT', 'Hãy đem kẻ rủa sả ra ngoài trại quân; hết thảy những người đã nghe phải đặt tay mình trên đầu người đó, rồi cả hội chúng phải ném đá người ấy.'),
(3462, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 24, 15, 'OT', 'Hãy nói cùng con cái Y-sơ-ra-ên rằng: Mỗi người, ai rủa sả Đức Chúa Trời mình, sẽ mang lấy tội của mình.'),
(3463, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 24, 16, 'OT', 'Ai nói phạm đến danh Đức Giê-hô-va thì phải bị xử tử; cả hội chúng phải ném đá người đó: dù là người ngoại bang hay là người bản xứ, hễ khi nào nói phạm đến danh Đức Giê-hô-va thì phải bị xử tử.'),
(3464, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 24, 17, 'OT', 'Người nào đánh chết bất cứ một người nào, thì phải bị xử tử.'),
(3465, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 24, 18, 'OT', 'Kẻ đánh chết một con vật phải đền bù; mạng sống đổi mạng sống.'),
(3466, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 24, 19, 'OT', 'Nếu một người nào làm tổn hại cho người đồng loại mình, thì phải đối xử với người đó như thể người đó đã đối xử.'),
(3467, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 24, 20, 'OT', 'gãy xương đền gãy xương, mắt đền mắt, răng đền răng; ai làm cho người khác bị thương thể nào thì cũng sẽ bị phạt thể ấy.'),
(3468, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 24, 21, 'OT', 'Kẻ nào đánh chết một con vật thì phải bồi thường; còn kẻ nào đánh chết một người thì phải bị xử tử.'),
(3469, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 24, 22, 'OT', 'Luật lệ phải như nhau cho các ngươi, cả người khách lạ lẫn người bản xứ; vì ta là Đức Giê-hô-va, Đức Chúa Trời của các ngươi.'),
(3470, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 24, 23, 'OT', 'Môi-se nói với dân Y-sơ-ra-ên, và họ đem người đã rủa sả ra ngoài trại quân, rồi ném đá người ấy. Dân Y-sơ-ra-ên đã làm y như Đức Giê-hô-va đã truyền dặn Môi-se.'),
(3471, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se tại núi Si-na-i rằng:'),
(3472, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 2, 'OT', 'Hãy nói với con cái Y-sơ-ra-ên rằng: Khi các ngươi vào đất mà Ta sẽ ban cho các ngươi, thì đất phải nghỉ lễ Sa-bát cho Đức Giê-hô-va.'),
(3473, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 3, 'OT', 'Sáu năm, ngươi sẽ gieo ruộng mình và sáu năm, ngươi sẽ tuốt nho vườn nho mình, rồi thu hoạch sản vật của nó.'),
(3474, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 4, 'OT', 'Nhưng trong năm thứ bảy, đất phải được nghỉ ngày Sa-bát, một ngày Sa-bát cho Đức Giê-hô-va; ngươi không được gieo ruộng mình, cũng không được tỉa cây nho mình.'),
(3475, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 5, 'OT', 'Đức Giê-hô-va phán: "Ngươi không được gặt những gì tự mọc lên trong mùa gặt của ngươi, và không được hái những trái nho nơi vườn nho không tỉa sửa; năm ấy phải là năm nghỉ ngơi cho đất."'),
(3476, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 6, 'OT', 'Sản vật của đất trong năm Sa-bát sẽ dùng làm của ăn cho ngươi, cho tôi trai tớ gái ngươi, cho kẻ làm thuê và cho khách ngoại bang đang kiều ngụ cùng ngươi.'),
(3477, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 7, 'OT', 'Cả sản vật của đất phải dành cho súc vật ngươi và các loài vật sống trong xứ ngươi ăn.'),
(3478, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 8, 'OT', 'Ngươi phải tính cho mình bảy tuần năm, mỗi tuần bảy năm; như vậy bảy tuần năm sẽ là bốn mươi chín năm.'),
(3479, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 9, 'OT', 'Rồi ngươi hãy thổi tiếng kèn vang dội trong tháng bảy, ngày mùng mười tháng ấy, tức là ngày lễ Khuôn Tội; các ngươi phải thổi kèn trong khắp đất nước các ngươi.'),
(3480, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 10, 'OT', 'Các ngươi phải biệt năm thứ năm mươi ra làm thánh, và công bố sự tự do trong khắp đất cho mọi người ở đó. Đó sẽ là năm hân hỉ cho các ngươi; mỗi người sẽ trở về cơ nghiệp mình, và mỗi người sẽ trở về gia tộc mình.'),
(3481, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 11, 'OT', 'Năm năm mươi sẽ là năm hân hỉ cho các ngươi; các ngươi sẽ không gieo, không gặt những gì tự mọc, và không hái những chùm nho của năm ấy.'),
(3482, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 12, 'OT', 'Vì đó là năm hân hỉ, nó sẽ là thánh cho các ngươi; các ngươi phải ăn những sản vật của đất.'),
(3483, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 13, 'OT', 'Trong năm hân hỉ nầy, mỗi người phải trở về sản nghiệp của mình.'),
(3484, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 14, 'OT', 'Khi các ngươi bán hay mua hàng hóa cho kẻ đồng loại mình, thì không được ai làm thiệt hại cho anh em mình.'),
(3485, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 15, 'OT', 'Ngươi sẽ mua từ kẻ lân cận mình theo số năm kể từ sau năm hân hỉ; người ấy sẽ bán cho ngươi theo số năm mùa màng.'),
(3486, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 16, 'OT', 'Tùy theo số năm nhiều, ngươi sẽ tăng giá mua của người; tùy theo số năm ít, ngươi sẽ giảm giá mua của người; vì theo số mùa gặt mà người bán cho ngươi.'),
(3487, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 17, 'OT', 'Chớ ai trong vòng các ngươi làm lận kẻ lân cận mình; nhưng hãy kính sợ Đức Chúa Trời, vì ta là Giê-hô-va Đức Chúa Trời của các ngươi.'),
(3488, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 18, 'OT', 'Các ngươi phải thực hiện các quy định của ta và tuân giữ các điều lệ ta, rồi thực hiện chúng; và các ngươi sẽ cư ngụ trên đất cách an toàn.'),
(3489, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 19, 'OT', 'Đất sẽ sinh ra hoa lợi của nó, và các ngươi sẽ ăn no nê, sống an toàn trên đất ấy.'),
(3490, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 20, 'OT', 'Nếu các ngươi nói: Năm thứ bảy này chúng ta sẽ ăn gì, vì chúng ta không được gieo và cũng không thu hoạch các sản vật của mình?'),
(3491, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 21, 'OT', 'Đức Giê-hô-va phán: Ta sẽ truyền phước Ta cho các ngươi trong năm thứ sáu, và đất sẽ sinh sản mùa màng đủ cho ba năm.'),
(3492, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 22, 'OT', 'Năm thứ tám, các ngươi sẽ gieo và ăn các hoa lợi cũ cho đến năm thứ chín; các ngươi sẽ ăn các hoa lợi cũ cho đến khi mùa màng mới đến.'),
(3493, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 23, 'OT', 'Đất không được bán mãi mãi, vì đất thuộc về ta; các ngươi là khách và là người tạm trú cùng ta.'),
(3494, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 24, 'OT', 'Trong khắp đất sản nghiệp của các ngươi, phải cho phép đất được chuộc lại.'),
(3495, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 25, 'OT', 'Nếu anh em ngươi trở nên nghèo túng mà phải bán một phần đất sản nghiệp của mình, thì người bà con gần gũi nhất phải đến chuộc lại phần đất mà anh em mình đã bán.'),
(3496, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 26, 'OT', 'Nếu có người nào không có người được quyền chuộc, mà tay người ấy lại tìm đủ tiền chuộc của mình,'),
(3497, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 27, 'OT', 'Phải tính số năm kể từ khi bán, hoàn trả phần thặng dư cho người đã mua, rồi người đó sẽ trở về sở hữu đất của mình.'),
(3498, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 28, 'OT', 'Nếu tay người bán không tìm đủ tiền để hoàn lại cho người mua, thì tài sản đã bán sẽ ở lại trong tay người mua cho đến năm hân hỉ; và đến năm hân hỉ ấy, tài sản ấy sẽ được giải thoát, và người bán sẽ trở về sở hữu đất đai của mình.'),
(3499, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 29, 'OT', 'Người nào bán một ngôi nhà ở trong thành có tường bao quanh, thì quyền chuộc lại ngôi nhà ấy được duy trì cho đến trọn năm sau khi bán; trọn một năm là thời hạn để người ấy được chuộc lại.'),
(3500, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 30, 'OT', 'Nếu trước khi trọn một năm trọn vẹn mà nhà ấy không được chuộc lại, thì nhà trong thành có vách thành nầy sẽ thuộc về người mua và dòng dõi người đời đời; đến năm sang năm, nhà ấy không được ra khỏi tay người mua.'),
(3501, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 31, 'OT', 'Còn các nhà ở làng quê không có vách thành bao quanh thì kể như đất đồng ruộng; có thể được chuộc lại, và đến năm hân hỉ thì nhà ấy phải trả về chủ cũ.'),
(3502, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 32, 'OT', 'Còn các thành của người Lê-vi, các nhà trong thành là sản nghiệp riêng của họ, thì luôn luôn có quyền chuộc lại.'),
(3503, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 33, 'OT', 'Nếu có ai mua nhà của người Lê-vi, thì nhà đã bán đó, tức là thành sản nghiệp của người ấy, phải được thả ra trong năm hân hỉ; vì các nhà trong các thành người Lê-vi là sản nghiệp riêng của họ giữa con cái Y-sơ-ra-ên.'),
(3504, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 34, 'OT', 'Các ruộng đất thuộc về các thành người Lê-vi không được phép bán, vì là sản nghiệp đời đời cho họ.'),
(3505, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 35, 'OT', 'Nếu anh em ngươi trở nên túng thiếu và tay người sa sút bên ngươi, ngươi phải nâng đỡ người, dù là khách ngoại kiều hay là người tạm trú, để người có thể sống bên ngươi.'),
(3506, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 36, 'OT', 'Đừng lấy lời nặng hay lợi tức của người, nhưng phải kính sợ Đức Chúa Trời mình, để anh em ngươi có thể sống cùng ngươi.'),
(3507, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 37, 'OT', 'Đừng lấy tiền của ngươi mà cho người ấy vay ăn lời, và cũng đừng lấy lương thực ngươi mà cho mượn để lấy lời.'),
(3508, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 38, 'OT', 'Ta là Đức Giê-hô-va Đức Chúa Trời các ngươi, Đấng đã đem các ngươi ra khỏi đất Ê-díp-tô, để ban cho các ngươi đất Ca-na-an, và làm Đức Chúa Trời của các ngươi.'),
(3509, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 39, 'OT', 'Nếu anh em ngươi trở nên nghèo khó và bán mình cho ngươi, ngươi không được bắt người phải làm công việc của kẻ tôi mọi.'),
(3510, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 40, 'OT', 'Người sẽ ở cùng ngươi như một người làm công, một người ngoại trú; người ấy sẽ phục vụ ngươi cho đến năm hân hỉ.'),
(3511, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 41, 'OT', 'thì người ấy và các con người ấy sẽ ra khỏi người, người ấy sẽ trở về cùng dòng họ người ấy, và trở về sản nghiệp tổ tiên người ấy.'),
(3512, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 42, 'OT', 'Vì chúng là những tôi tớ Ta, mà Ta đã đem ra khỏi đất Ai Cập; chúng không được bán như cách bán một tôi mọi.'),
(3513, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 43, 'OT', 'Ngươi không được ngược đãi người ấy cách khắc nghiệt, mà phải kính sợ Đức Chúa Trời.'),
(3514, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 44, 'OT', 'Tôi trai và tớ gái mà ngươi sẽ có đều thuộc các dân tộc xung quanh các ngươi; từ những dân đó ngươi được mua tôi trai và tớ gái.'),
(3515, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 45, 'OT', 'Cũng từ con cái của những người ngoại kiều sống giữa các ngươi, và từ họ hàng chúng nó, là những người sinh ra trong xứ các ngươi, các ngươi có thể mua; họ sẽ thuộc về các ngươi làm sản nghiệp.'),
(3516, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 46, 'OT', 'Các ngươi sẽ để họ lại làm cơ nghiệp cho con cái các ngươi sau các ngươi, để họ giữ mãi mãi; các ngươi sẽ bắt họ làm tôi mọi. Nhưng về phần anh em các ngươi, là con cháu Y-sơ-ra-ên, mỗi người không được hà hiếp anh em mình cách khắc nghiệt.'),
(3517, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 47, 'OT', 'Nếu tay của một người ngoại bang hay một người kiều ngụ ở giữa ngươi trở nên giàu có, còn anh em ngươi ở giữa người ấy lại trở nên nghèo, và người ấy bán mình cho một người ngoại bang kiều ngụ ở giữa ngươi, hay cho một người thuộc dòng họ của người ngoại bang ấy,'),
(3518, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 48, 'OT', 'Sau khi đã bị bán, thì có quyền được chuộc lại; một trong những anh em người ấy sẽ chuộc nó.'),
(3519, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 49, 'OT', 'Hoặc anh em họ hàng, hoặc con trai anh em họ hàng, hoặc một người thân thích trong gia đình mình sẽ chuộc nó; hoặc nếu tay người đó với tới, thì chính người đó phải chuộc nó.'),
(3520, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 50, 'OT', 'Người đó phải tính với người mua mình, từ năm mà người đó đã bán mình cho người ấy cho đến năm hân hỉ; và số tiền trả cho người đó phải được tính theo số năm, như tiền công của người làm thuê theo ngày vậy.'),
(3521, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 51, 'OT', 'Nếu còn nhiều năm, thì phải cứ theo số năm ấy mà hoàn trả tiền chuộc của mình, tức là tiền đã mua.'),
(3522, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 52, 'OT', 'Nếu còn ít năm nữa mới đến năm hân hỉ, thì phải tính cho người đó số tiền chuộc theo số năm ấy mà hoàn lại.'),
(3523, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 53, 'OT', 'Người sẽ ở với chủ như một người làm thuê từng năm; ngươi không được bắt người ấy phục dịch cách khắc nghiệt trước mặt ngươi.'),
(3524, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 54, 'OT', 'Nếu người ấy không được chuộc lại bởi những cách đó, thì đến năm hân hỉ, người ấy và các con trai người ấy sẽ ra đi cùng người ấy.'),
(3525, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 25, 55, 'OT', 'Vì Y-sơ-ra-ên là những tôi tớ ta; chính ta là Đức Chúa Trời của các ngươi, Đấng đã đem họ ra khỏi đất Ê-díp-tô. Ta là Giê-hô-va.'),
(3526, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 1, 'OT', 'Các ngươi chớ làm cho mình các hình tượng, cũng đừng dựng lên tượng chạm hay tượng trụ, và chớ đặt trong đất các ngươi một tảng đá có hình dạng để các ngươi cúi lạy trước nó; vì ta là Đức Giê-hô-va, Đức Chúa Trời của các ngươi.'),
(3527, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 2, 'OT', 'Hãy giữ các ngày sa-bát của Ta, và kính sợ nơi thánh của Ta. Ta là Đức Giê-hô-va.'),
(3528, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 3, 'OT', 'Nếu các ngươi tuân theo các luật lệ ta, giữ các điều răn ta và làm theo,'),
(3529, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 4, 'OT', 'thì ta sẽ ban cho các ngươi mưa đúng thì, đất sẽ sinh ra hoa lợi, và cây ngoài đồng sẽ cho quả của nó.'),
(3530, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 5, 'OT', 'Vụ đập lúa sẽ tới kỳ vụ hái nho, và vụ hái nho sẽ tới kỳ gieo giống; các ngươi sẽ ăn bánh no nê và ở yên ổn trong đất các ngươi.'),
(3531, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 6, 'OT', 'Ta sẽ ban sự bình an trong đất, các ngươi sẽ nằm ngủ mà không ai làm kinh sợ; Ta sẽ loại bỏ các loài thú dữ khỏi đất, và gươm không đi ngang qua đất các ngươi.'),
(3532, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 7, 'OT', 'Các ngươi sẽ đuổi theo các kẻ thù các ngươi, và chúng sẽ bị gươm ngã xuống trước mặt các ngươi.'),
(3533, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 8, 'OT', 'Năm người trong các ngươi sẽ đuổi theo năm trăm, và một trăm trong các ngươi sẽ đuổi theo vạn người; quân nghịch các ngươi sẽ bị gươm giết trước mặt các ngươi.'),
(3534, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 9, 'OT', 'Ta sẽ đoái hướng về các ngươi, làm cho các ngươi sinh sản và gia tăng, khiến các ngươi trở nên đông đảo, và Ta sẽ thiết lập giao ước của Ta với các ngươi.'),
(3535, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 10, 'OT', 'Các ngươi sẽ ăn các hoa lợi cũ đã để dành, và phải đem cái cũ ra để nhường chỗ cho cái mới.'),
(3536, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 11, 'OT', 'Ta sẽ đặt nơi ở của Ta giữa các ngươi, và lòng Ta sẽ không ghê tởm các ngươi.'),
(3537, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 12, 'OT', 'Ta sẽ đi giữa các ngươi, làm Đức Chúa Trời các ngươi, và các ngươi sẽ làm dân ta.'),
(3538, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 13, 'OT', 'Ta là Đức Giê-hô-va Đức Chúa Trời của các ngươi, Đấng đã đem các ngươi ra khỏi đất Ê-díp-tô, hầu cho khỏi làm tôi mọi cho chúng; và Ta đã bẻ gãy những cái gậy của ách các ngươi, và dẫn các ngươi đi ngước đầu lên.'),
(3539, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 14, 'OT', 'Nhưng nếu các ngươi không nghe ta, và không làm trọn các điều răn nầy,'),
(3540, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 15, 'OT', 'Nếu các ngươi khinh bỉ các luật lệ ta, và linh hồn các ngươi ghét bỏ các mạng lịnh ta, đến nỗi không thực hiện mọi điều răn ta, mà vi phạm giao ước ta,'),
(3541, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 16, 'OT', 'Ta cũng sẽ làm điều nầy cho các ngươi: Ta sẽ giáng trên các ngươi sự kinh hoàng, bệnh sốt rét và bệnh sốt nóng làm mòn mắt và làm tan tâm hồn. Các ngươi sẽ gieo giống các ngươi cách luống công, vì quân thù của các ngươi sẽ ăn nó.'),
(3542, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 17, 'OT', 'Ta sẽ nghịch lại các ngươi; các ngươi sẽ bị kẻ thù đánh bại; những kẻ ghét các ngươi sẽ thống trị các ngươi; các ngươi sẽ chạy trốn nhưng chẳng có ai đuổi theo.'),
(3543, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 18, 'OT', 'Nếu các ngươi không nghe ta, dù ta đã cảnh cáo như thế, ta sẽ sửa phạt các ngươi thêm bảy lần vì tội các ngươi.'),
(3544, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 19, 'OT', 'Ta sẽ đập tan sự kiêu ngạo về sức lực các ngươi; Ta sẽ khiến các ngươi trời cứng như sắt và đất các ngươi cứng như đồng.'),
(3545, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 20, 'OT', 'Sức lực các ngươi sẽ cạn kiệt vô ích, đất các ngươi sẽ không sinh ra hoa lợi, và cây cối trên đất sẽ không trổ bông trái.'),
(3546, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 21, 'OT', 'Nếu các ngươi đi nghịch cùng ta và không chịu nghe theo ta, thì ta sẽ gia tăng hình phạt các ngươi gấp bảy lần theo các tội lỗi của các ngươi.'),
(3547, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 22, 'OT', 'Ta sẽ sai các thú dữ ngoài đồng vào giữa các ngươi, khiến các ngươi mất con cái, tiêu diệt súc vật các ngươi, làm cho các ngươi trở nên ít người, và các nẻo đường các ngươi sẽ trở nên hoang vắng.'),
(3548, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 23, 'OT', 'Nếu các ngươi không chịu sửa mình trước những điều ấy đối với ta, mà cứ đi nghịch cùng ta,'),
(3549, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 24, 'OT', 'Ta đây cũng sẽ nghịch lại cùng các ngươi, và Ta sẽ đánh các ngươi bảy lần nữa vì tội lỗi các ngươi.'),
(3550, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 25, 'OT', 'Ta sẽ mang gươm đến trên các ngươi để báo oán giao ước, các ngươi sẽ bị nhóm lại trong các thành mình, Ta sẽ sai dịch lệ đến giữa các ngươi, và các ngươi sẽ bị nộp vào tay kẻ thù.'),
(3551, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 26, 'OT', 'Khi Ta bẻ gãy cho các ngươi cây gậy của bánh, thì mười người đàn bà sẽ nướng bánh các ngươi trong một cái lò, và trả lại bánh các ngươi theo cân lượng; các ngươi sẽ ăn mà không no.'),
(3552, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 27, 'OT', 'Nếu các ngươi không nghe ta vì điều đó, mà còn đi nghịch cùng ta cách ngạo mạn,'),
(3553, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 28, 'OT', 'Ta sẽ đi nghịch lại các ngươi trong cơn thịnh nộ, và chính ta sẽ sửa phạt các ngươi bảy lần vì tội lỗi các ngươi.'),
(3554, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 29, 'OT', 'Các ngươi sẽ ăn thịt con trai mình, và thịt con gái mình các ngươi sẽ ăn.'),
(3555, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 30, 'OT', 'Ta sẽ tiêu diệt các nơi cao của các ngươi, hủy bỏ các hình tượng mặt trời các ngươi, và để xác các ngươi nằm chồng trên xác hình tượng bẩn thỉu của các ngươi; thì lòng Ta sẽ ghê tởm các ngươi.'),
(3556, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 31, 'OT', 'Ta sẽ khiến các thành các ngươi ra hoang vu, và làm cho các nơi thánh các ngươi trở nên vắng vẻ; Ta sẽ không còn nhận mùi thơm dễ chịu của lễ vật các ngươi nữa.'),
(3557, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 32, 'OT', 'Ta sẽ khiến đất trở nên hoang vu, khiến kẻ thù các ngươi ở giữa đất phải kinh hãi.'),
(3558, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 33, 'OT', 'Ta sẽ tản lạc các ngươi giữa các dân, và rút gươm đuổi theo sau lưng các ngươi; đất các ngươi sẽ trở nên hoang vu, các thành các ngươi sẽ bị hủy hoại.'),
(3559, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 34, 'OT', 'Bấy giờ đất sẽ được hưởng các ngày sa-bát mình trọn vẹn trong mọi năm đất bị bỏ hoang, còn các ngươi thì ở trong đất của kẻ thù nghịch mình; khi ấy đất sẽ được nghỉ an và được hưởng các ngày sa-bát mình.'),
(3560, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 35, 'OT', 'Trong mọi ngày đất bị bỏ hoang, nó sẽ được nghỉ ngơi, bù lại những ngày nó không được nghỉ khi các ngươi ở trên đó trong các năm Sa-bát của các ngươi.'),
(3561, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 36, 'OT', 'Còn những kẻ sót lại trong các ngươi, ta sẽ khiến lòng họ yếu đuối trong các xứ của kẻ thù nghịch mình; tiếng lá bị xua đuổi sẽ khiến họ chạy trốn như chạy trốn khỏi lưỡi gươm, và họ sẽ ngã xuống mà không có ai đuổi theo.'),
(3562, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 37, 'OT', 'Người nầy sẽ vấp ngã trên anh em mình như khi trốn chạy trước lưỡi gươm, dù không ai rượt đuổi; các ngươi sẽ không thể đứng vững trước mặt kẻ thù mình.'),
(3563, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 38, 'OT', 'Các ngươi sẽ bị tiêu diệt giữa các dân; đất của kẻ thù các ngươi sẽ nuốt các ngươi.'),
(3564, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 39, 'OT', 'Kẻ nào còn sót lại trong các ngươi sẽ tiều tụy vì tội lỗi mình, và cũng vì tội lỗi tổ tiên mình, họ sẽ tiều tụy trong đất nước của kẻ thù mình.'),
(3565, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 40, 'OT', 'Họ sẽ thú nhận tội lỗi mình và tội lỗi tổ phụ mình, về sự bất trung mà họ đã bất trung cùng ta, và cũng về việc họ đã đi nghịch cùng ta.'),
(3566, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 41, 'OT', 'thì chính ta cũng sẽ đối xử với họ cách ngẫu nhiên, dẫn họ đến đất của kẻ thù họ; bấy giờ nếu lòng họ không chịu cắt bì sẽ ăn năn, và bấy giờ họ sẽ chuộc lấy tội gian ác mình,'),
(3567, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 42, 'OT', 'thì ta sẽ nhớ lại giao ước ta đã lập với Gia-cốp, cũng nhớ lại giao ước ta đã lập với Y-sác, và cũng nhớ lại giao ước ta đã lập với Aùp-ra-ham; ta cũng sẽ nhớ lại đất nầy.'),
(3568, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 43, 'OT', 'Xứ sẽ bị bỏ hoang vì họ, và sẽ được nghỉ những năm sa-bát mình trong sự hoang vu vì họ; họ sẽ chịu hình phạt vì tội mình, bởi vì họ đã khinh bỉ các mạng lịnh ta và linh hồn họ đã ghê tởm các luật lệ ta.'),
(3569, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 44, 'OT', 'Dẫu vậy, ngay khi chúng nó ở trong đất của kẻ thù nghịch, Ta cũng không khinh bỏ chúng nó, không ghê gớm chúng nó đến nỗi tiêu diệt hết và hủy bỏ giao ước Ta lập với chúng nó, vì Ta là Đức Giê-hô-va, Đức Chúa Trời của chúng nó.'),
(3570, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 45, 'OT', 'Ta sẽ nhớ lại cho họ giao ước đời đầu, là giao ước mà Ta đã đem họ ra khỏi đất Ê-díp-tô, trước mặt các dân, để làm Đức Chúa Trời của họ. Ta là Đức Giê-hô-va.'),
(3571, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 26, 46, 'OT', 'Đó là các điều lệ, các mạng lệnh và các luật lệ mà Đức Giê-hô-va đã đặt giữa Ngài và con cái Y-sơ-ra-ên tại trên núi Si-nai-i, nhờ tay Môi-se.'),
(3572, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3573, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 2, 'OT', 'Hãy nói với con cái Y-sơ-ra-ên rằng: Nếu một người khấn hứa dâng Đức Giê-hô-va giá trị một linh hồn theo định giá của ngươi,'),
(3574, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 3, 'OT', 'Nếu giá định về người nam từ hai mươi tuổi đến sáu mươi tuổi, thì giá định của ngươi là năm mươi siếc-lơ bạc, theo siếc-lơ nơi thánh.'),
(3575, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 4, 'OT', 'Nếu là một người nữ, thì giá trị của ngươi sẽ là ba mươi siếc-lơ.'),
(3576, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 5, 'OT', 'Nếu từ năm tuổi đến hai mươi tuổi, thì giá định cho người nam là hai mươi siếc-lơ, còn cho người nữ là mười siếc-lơ.'),
(3577, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 6, 'OT', 'Nếu từ một tháng tuổi cho đến năm tuổi, thì giá ngươi định cho con trai là năm chỉ bạc; còn cho con gái là ba chỉ bạc.'),
(3578, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 7, 'OT', 'Nếu từ con trai sáu mươi tuổi trở lên, thì giá định cho ngươi là mười lăm sikê bạc; còn về người nữ, thì là mười sikê bạc.'),
(3579, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 8, 'OT', 'Nếu người ấy nghèo, không đủ khả năng theo giá trị ngươi định, thì phải đem người ấy đến trình trước mặt thầy tế lễ; và thầy tế lễ sẽ định giá cho người đó theo khả năng của người khấn nguyện.'),
(3580, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 9, 'OT', 'Nếu dâng làm của lễ cho Đức Giê-hô-va một con thú thuộc loại có thể dùng làm của lễ dâng cho Đức Giê-hô-va, thì bất cứ điều gì người ta dâng từ nó cho Đức Giê-hô-va sẽ là vật thánh.'),
(3581, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 10, 'OT', 'Người ta không được đổi, cũng không được thế con tốt lấy con xấu hay con xấu lấy con tốt; nếu ai thế một con vật này lấy một con vật khác, thì chính con vật ấy và con vật thế vào nó đều sẽ nên thánh.'),
(3582, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 11, 'OT', 'Nếu là một loài thú vật không sạch, mà người ta không thể dâng nó làm của lễ cho Đức Giê-hô-va, thì phải đem con thú đó đặt trước mặt thầy tế lễ.'),
(3583, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 12, 'OT', 'thầy tế lễ sẽ định giá nó, tùy theo nó tốt hay xấu; theo giá mà thầy tế lễ định thì nó sẽ như vậy.'),
(3584, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 13, 'OT', 'Nếu muốn cứu chuộc, thì phải cộng thêm một phần năm giá trị ngươi đã ước định.'),
(3585, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 14, 'OT', 'Người nào biệt nhà mình ra thánh cho Đức Giê-hô-va, thì thầy tế lễ sẽ định giá cho nhà ấy, không kể nhà tốt hay xấu; theo giá mà thầy tế lễ định thì nó sẽ đứng vững.'),
(3586, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 15, 'OT', 'Nếu người đã biệt riêng ra thánh mà muốn chuộc lại nhà mình, thì phải thêm một phần năm giá ngươi đã định trên nhà đó, rồi nhà ấy sẽ thuộc về người.'),
(3587, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 16, 'OT', 'Nếu một người biệt một phần ruộng đất tổ nghiệp mình ra thánh cho Đức Giê-hô-va, thì giá trị sẽ được ước định tùy theo lượng giống của nó: một chômer lúa mạch giá năm mươi siếc-lơ bạc.'),
(3588, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 17, 'OT', 'Nếu biệt riêng ruộng mình ra thánh từ năm hân hỉ, thì giá trị nó sẽ đứng theo định giá của ngươi.'),
(3589, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 18, 'OT', 'Nếu người ấy biệt riêng ruộng mình ra thánh sau năm hân hỉ, thì thầy tế lễ sẽ tính cho người ấy số tiền theo số năm còn lại đến năm hân hỉ, và sẽ trừ đi từ giá trị ước định của ngươi.'),
(3590, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 19, 'OT', 'Nếu người đã biệt riêng ruộng mình ra thánh mà muốn chuộc lại, thì phải thêm một phần năm giá trị ngươi định cho nó, rồi ruộng ấy sẽ thuộc về người đó.'),
(3591, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 20, 'OT', 'Nếu không chuộc lại miếng đất, hoặc nếu đã bán miếng đất ấy cho một người khác, thì sẽ không được chuộc lại nữa.'),
(3592, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 21, 'OT', 'Khi đến năm hân hỉ, ruộng đất sẽ trở lại thánh cho Đức Giê-hô-va, như một miếng đất bị cấm; sản nghiệp của nó sẽ thuộc về thầy tế lễ.'),
(3593, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 22, 'OT', 'Nếu ai biệt riêng ra thánh cho Đức Giê-hô-va một cánh đồng mình đã mua, mà không phải là đất cơ nghiệp của tổ tiên,'),
(3594, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 23, 'OT', 'thầy tế lễ sẽ tính cho người đó số tiền ngươi đã định, cho đến năm thứ năm mươi, rồi người ấy phải nộp số tiền ngươi định vào chính ngày đó, vì là một vật biệt riêng ra thánh cho Đức Giê-hô-va.'),
(3595, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 24, 'OT', 'Vào năm hân hỉ, ruộng đất sẽ trở về cho người đã bán nó, tức là trở về cho chủ sở hữu ban đầu của đất ấy.'),
(3596, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 25, 'OT', 'Mọi giá trị ước định của ngươi đều phải theo siếc-lơ nơi thánh: một siếc-lơ gồm hai mươi ghê-ra.'),
(3597, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 26, 'OT', 'Chỉ có con đầu lòng trong số các loài súc vật, khi đã được biệt riêng cho Đức Giê-hô-va, thì không ai được biệt riêng nó ra thánh nữa; dù là bò hay chiên, nó thuộc về Đức Giê-hô-va.'),
(3598, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 27, 'OT', 'Nếu là súc vật không sạch, ngươi phải lấy giá trị ngươi định mà thay thế, và thêm một phần năm vào đó; nếu nó không được thay thế, thì phải bán nó tùy theo giá trị ngươi định.'),
(3599, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 28, 'OT', 'Nhưng hễ vật nào bị tuyệt giao, tức là mọi vật thuộc về người nào mà người ấy đã tuyệt giao dâng cho Đức Giê-hô-va, dù là người, súc vật, hay ruộng đất tổ nghiệp của mình, thì không được phép bán, cũng không được phép chuộc lại; mọi vật bị tuyệt giao đều là chí thánh dành riêng cho Đức Giê-hô-va.'),
(3600, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 29, 'OT', 'Mọi thứ bị rủa bởi người nào không được phép chuộc lại; nó phải bị giết chết.'),
(3601, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 30, 'OT', 'Mọi phần mười của đất, dù là từ sản vật của đất hay là trái cây của cây cối, đều thuộc về Đức Giê-hô-va; nó là một vật thánh biệt riêng ra cho Đức Giê-hô-va.'),
(3602, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 31, 'OT', 'Nếu một người muốn chuộc lại vật thuộc về phần mười của mình, thì phải cộng thêm một phần năm của giá trị nó.'),
(3603, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 32, 'OT', 'Mọi phần mười về bò và chiên, tức là mọi vật đi ngang dưới gậy, con thứ mười sẽ là thánh, biệt riêng ra thánh cho Đức Giê-hô-va.'),
(3604, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 33, 'OT', 'Không được phân biệt giữa tốt và xấu, cũng không được đổi; nếu đổi, thì chính nó và vật đổi nó đều phải thánh, không được chuộc lại.'),
(3605, 3, 'GOI_vi', 'GOI_vi', 'vi', 'LEV', 27, 34, 'OT', 'Đây là các mạng lệnh mà Đức Giê-hô-va đã truyền cho Môi-se về dân Y-sơ-ra-ên tại núi Si-na-i.'),
(3606, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se tại đồng vắng Si-na-i, trong hội mạc, ngày mồng một tháng hai, năm thứ hai sau khi dân Y-sơ-ra-ên ra khỏi xứ Ê-díp-tô, mà rằng:'),
(3607, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 2, 'OT', 'Hãy điểm danh đầu của cả hội chúng Y-sơ-ra-ên theo các họ hàng và nhà tổ phụ của chúng, theo số tên của từng người nam, mỗi người theo đầu mình.'),
(3608, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 3, 'OT', 'Từ hai mươi tuổi trở lên, mọi người trong Y-sơ-ra-ên có thể ra trận được, thì ngươi và A-rôn phải kiểm tra họ theo các đạo quân của họ.'),
(3609, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 4, 'OT', 'Các ngươi sẽ có một người nam cho mỗi chi phái, mỗi người là đầu trưởng của nhà cha ông mình.'),
(3610, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 5, 'OT', 'Và đây là tên những người sẽ giúp đỡ các ngươi: về phần Ru-bên, Ê-lít-xu, con trai của Sê-đêu;'),
(3611, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 6, 'OT', 'Về chi phái Si-mê-ôn, Sê-lu-mi-ên con trai Xu-ri-ha-đai;'),
(3612, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 7, 'OT', 'về chi phái Giu-đa, Na-ha-sôn, con trai của A-mi-na-đáp;'),
(3613, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 8, 'OT', 'Về chi phái Y-sa-ca, Na-tha-na-ên, con trai của Xu-a;'),
(3614, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 9, 'OT', 'Về chi phái Sa-bu-lôn, Ê-li-áp, con trai của Hê-lôn;'),
(3615, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 10, 'OT', 'Về con cháu Giô-sép, về chi phái Eùp-ra-im, Ê-li-sa-ma, con trai của A-mi-hút; về chi phái Ma-na-se, Ga-ma-li-ên, con trai của Phê-đát-su.'),
(3616, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 11, 'OT', 'Về chi phái Bên-gia-min, A-bi-đan con trai của Ghi-đeo-ni.'),
(3617, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 12, 'OT', 'Về chi phái Đan, A-hi-ê-xe, con trai của A-mi-sa-đai;'),
(3618, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 13, 'OT', 'về chi phái A-se, Pha-ghi-ên, con trai của Oùc-ran;'),
(3619, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 14, 'OT', 'về chi phái Gát, Ê-li-a-sáp, con trai của Đê-u-ên;'),
(3620, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 15, 'OT', 'Về chi phái Nép-ta-li, A-hi-ra, con trai của Ê-nan.'),
(3621, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 16, 'OT', 'Đó là những người được gọi từ hội chúng, các thủ lĩnh các chi phái tổ phụ họ, các trưởng quan của ngàn người Y-sơ-ra-ên.'),
(3622, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 17, 'OT', 'Môi-se và A-rôn nhận lấy những người nầy, là những người đã được điểm danh theo tên.'),
(3623, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 18, 'OT', 'Vào ngày mồng một tháng hai, họ triệu tập toàn thể hội chúng, và mọi người được ghi chép theo các chi phái và nhà tổ phụ mình, theo số danh sách, từng người một, từ tuổi hai mươi trở lên, theo đầu người.'),
(3624, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 19, 'OT', 'Y như Đức Giê-hô-va đã truyền cho Môi-se, người ấy đã kiểm tra họ tại đồng vắng Si-na-i.'),
(3625, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 20, 'OT', 'Con cháu Ru-bên, trưởng tử của Y-sơ-ra-ên, theo các gia hệ và tông tộc của họ, được liệt kê theo tên, mọi người nam từ hai mươi tuổi trở lên, tất cả những ai đi ra trận được,'),
(3626, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 21, 'OT', 'Theo số người được điểm danh của chi phái Ru-bên, có bốn mươi sáu ngàn năm trăm người.'),
(3627, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 22, 'OT', 'Dòng dõi của Si-mê-ôn, theo các họ hàng và tông tộc của họ, theo gia đình tổ tiên họ; những người được kiểm điểm, kể theo tên, từng người một, tất cả nam giới từ hai mươi tuổi trở lên, mọi người có thể ra đi chinh chiến.'),
(3628, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 23, 'OT', 'theo danh sách của họ về chi phái Si-mê-ôn, là năm mươi chín ngàn ba trăm.'),
(3629, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 24, 'OT', 'Các con cháu của Gát, theo các họ hàng và nhà tổ phụ của họ, được điểm danh theo tên, từ hai mươi tuổi trở lên, tất cả những người có thể ra đi chinh chiến.'),
(3630, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 25, 'OT', 'bốn mươi lăm ngàn sáu trăm năm mươi người, theo các gia tộc của chi phái Gát.'),
(3631, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 26, 'OT', 'Dòng dõi của các con trai Giu-đa, theo các họ hàng và tông tộc của họ, cứ kể từng tên, từ hai mươi tuổi trở lên, tức là mọi người trong chi phái Giu-đa có thể ra trận được,'),
(3632, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 27, 'OT', 'bảy mươi bốn ngàn sáu trăm người, theo các chi phái của con trai Giu-đa.'),
(3633, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 28, 'OT', 'Dòng dõi của Y-sa-ca, theo các chi phái và các nhà tổ phụ họ, theo số tên gọi, từ con trai hai mươi tuổi trở lên, mọi người ra trận được,'),
(3634, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 29, 'OT', 'Theo các gia tộc của họ, thuộc chi phái Y-sa-ca, là năm mươi bốn ngàn bốn trăm người.'),
(3635, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 30, 'OT', 'Theo dòng dõi của con trai Sa-bu-lôn, theo các họ hàng và nhà tổ tiên họ, theo số tên từng người, từ con trai hai mươi tuổi trở lên, tất cả những người ra trận được,'),
(3636, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 31, 'OT', 'số người được kiểm tra thuộc chi phái Xê-bu-lôn là năm mươi bảy ngàn bốn trăm.'),
(3637, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 32, 'OT', 'Về con cháu Giô-sép, về con cháu Eùp-ra-im, gia phả của họ theo các họ hàng và nhà tổ phụ họ, tính theo tên, từ con trai hai mươi tuổi trở lên, mọi người ra trận được,'),
(3638, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 33, 'OT', 'Số người được kiểm tra thuộc chi phái Ép-ra-im là bốn mươi ngàn năm trăm.'),
(3639, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 34, 'OT', 'Theo các gia đình, các tông tộc, các nhà tổ phụ của con cháu Ma-na-se, theo số tên của từng người, từ hai mươi tuổi trở lên, mọi người trong chi phái Ma-na-se có thể ra đi chinh chiến,'),
(3640, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 35, 'OT', 'ba mươi hai ngàn hai trăm, theo các chi phái của chi phái Ma-na-se.'),
(3641, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 36, 'OT', 'Dòng dõi của Bên-gia-min, theo các họ hàng và tông tộc của họ, theo nhà tổ phụ họ, từng người một, kể từ hai mươi tuổi trở lên, mọi người ra trận được.'),
(3642, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 37, 'OT', 'ba mươi lăm ngàn bốn trăm, theo các chi phái của con trai Bên-gia-min.'),
(3643, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 38, 'OT', 'Các con cháu của Đan, theo các họ hàng và nhà tổ tiên của họ, theo số tên gọi, từ hai mươi tuổi trở lên, tất cả những người ra trận được,'),
(3644, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 39, 'OT', 'số người được kiểm tra thuộc chi phái Đan là sáu mươi hai ngàn bảy trăm.'),
(3645, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 40, 'OT', 'Con cháu A-se, các dòng dõi của họ theo các gia tộc và nhà tổ phụ họ, theo số tên gọi, từ con trai hai mươi tuổi trở lên, tức là tất cả những người ra trận được.'),
(3646, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 41, 'OT', 'số người được kiểm tra theo chi phái A-xe, là một và bốn mươi ngàn năm trăm.'),
(3647, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 42, 'OT', 'Con cháu Nép-ta-li, theo dòng dõi họ, theo các nhà họ hàng của tổ tiên họ, được kể tên từng người, từ hai mươi tuổi trở lên, tất cả những người đi ra trận được,'),
(3648, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 43, 'OT', 'thống kê theo chi phái Na-phtha-li là năm mươi ba ngàn bốn trăm.'),
(3649, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 44, 'OT', 'Đó là những người đã được Môi-se và A-rôn cùng các quan trưởng Y-sơ-ra-ên, mười hai người, mỗi người một người theo nhà tổ phụ mình, điểm sổ.'),
(3650, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 45, 'OT', 'Vậy thì, tất cả những người được điểm danh trong dân Y-sơ-ra-ên theo từng gia tộc của họ, từ hai mươi tuổi trở lên, tức là mọi người ra trận được trong Y-sơ-ra-ên,'),
(3651, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 46, 'OT', 'Tất cả những người được điểm danh là sáu trăm ngàn, ba ngàn năm trăm năm mươi người.'),
(3652, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 47, 'OT', 'Nhưng người Lê-vi, theo chi phái tổ phụ mình, không được liệt kê vào giữa họ.'),
(3653, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 48, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3654, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 49, 'OT', 'Chỉ chi phái Lê-vi, ngươi không được kê sổ; và ngươi không được điểm danh họ giữa con cái Y-sơ-ra-ên.'),
(3655, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 50, 'OT', 'Nhưng ngươi hãy chỉ định người Lê-vi coi sóc Nhà tạm Chứng cớ và tất cả các đồ dùng của nó, cùng mọi thứ thuộc về nó. Chính họ sẽ mang Nhà tạm và mọi đồ dùng của nó, và họ sẽ phục vụ nó; họ sẽ đóng trại xung quanh Nhà tạm.'),
(3656, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 51, 'OT', 'Khi trại tạm dời chỗ, người Lê-vi sẽ tháo dỡ nó; khi trại tạm dừng lại, người Lê-vi sẽ dựng nó lên; còn người ngoại nào đến gần thì sẽ bị xử tử.'),
(3657, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 52, 'OT', 'Dân Y-sơ-ra-ên phải đóng trại, mỗi người tại trại quân mình và mỗi người gần bên ngọn cờ mình, theo các đạo quân của họ.'),
(3658, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 53, 'OT', 'Người Lê-vi sẽ đóng trại chung quanh Nhà tạm Chứng cớ, để cơn thịnh nộ không đổ trên hội chúng con cái Y-sơ-ra-ên; và người Lê-vi sẽ giữ nhiệm vụ canh giữ Nhà tạm Chứng cớ.'),
(3659, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 1, 54, 'OT', 'Người Y-sơ-ra-ên làm y như mọi điều Đức Giê-hô-va đã truyền dạy Môi-se.'),
(3660, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se và A-rôn rằng:'),
(3661, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 2, 'OT', 'Mỗi người Y-sơ-ra-ên phải đóng trại gần ngọn cờ của mình, theo các dấu hiệu của gia tộc tổ tiên mình; họ phải đóng trại đối diện chung quanh Rạp Hẹn.'),
(3662, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 3, 'OT', 'Trại quân Giu-đa sẽ đóng về phía đông, hướng mặt trời mọc, theo cờ hiệu và các đạo quân của họ; và quan trưởng của con trai Giu-đa là Na-ha-sôn, con trai A-mi-na-đáp.'),
(3663, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 4, 'OT', 'và đạo binh của họ, theo số người đã được điểm danh, là bảy mươi bốn ngàn sáu trăm người.'),
(3664, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 5, 'OT', 'Chi phái Y-sa-ca phải đóng trại bên cạnh; quan trưởng của con cháu Y-sa-ca là Na-tha-na-ên, con trai Xu-a.'),
(3665, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 6, 'OT', 'và đạo binh của họ, theo số điểm danh, là năm mươi bốn ngàn bốn trăm người.'),
(3666, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 7, 'OT', 'Chi phái Sa-bu-lôn; và người lãnh đạo của con trai Sa-bu-lôn là Ê-li-áp, con trai Hê-lôn.'),
(3667, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 8, 'OT', 'và đạo quân người cùng số người được kiểm tra là năm mươi bảy ngàn bốn trăm người.'),
(3668, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 9, 'OT', 'Tất cả những người đã điểm danh theo trại quân Giu-đa, theo các đạo quân của họ, là một trăm tám mươi sáu ngàn bốn trăm người; họ sẽ đi đầu.'),
(3669, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 10, 'OT', 'Ngọn cờ của trại quân Ru-bên theo các đội ngũ của họ phải đóng về hướng nam; và quan trưởng của con trai Ru-bên là Ê-li-xu, con trai của Sê-đêu.'),
(3670, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 11, 'OT', 'Và đạo quân người, theo số điểm danh, gồm bốn mươi sáu ngàn năm trăm người.'),
(3671, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 12, 'OT', 'Chi phái Si-mê-ôn phải đóng trại bên Ru-bên; quan trưởng của con cái Si-mê-ôn là Sê-lu-mi-ên, con trai của Xu-ri-ha-đai.'),
(3672, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 13, 'OT', 'và đạo binh của họ, theo số điểm danh, là năm mươi chín ngàn ba trăm người.'),
(3673, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 14, 'OT', 'Chi phái Gát; và quan trưởng của con trai Gát là Ê-li-a-sáp, con trai Rê-u-ên.'),
(3674, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 15, 'OT', 'Và đạo quân của họ, theo số người được kiểm điểm, là bốn mươi lăm ngàn sáu trăm năm mươi người.'),
(3675, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 16, 'OT', 'Tất cả những người được điểm danh theo trại quân Ru-bên, theo các đạo quân của họ, là một trăm vạn một ngàn năm trăm bốn trăm năm mươi người; họ sẽ đi thứ nhì.'),
(3676, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 17, 'OT', 'Hội mạc sẽ đi, trại quân Lê-vi ở giữa các trại quân; theo đúng như cách họ đóng trại, thì cũng vậy họ sẽ đi, mỗi người theo hàng ngũ mình, theo các ngọn cờ của họ.'),
(3677, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 18, 'OT', 'Ngọn cờ trại quân đội Eùp-ra-im theo các đạo quân họ về hướng tây; và người lãnh đạo con trai của Eùp-ra-im là Ê-li-sa-ma, con trai A-mi-hút.'),
(3678, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 19, 'OT', 'và đạo quân người, theo số điểm danh, gồm bốn mươi ngàn năm trăm người.'),
(3679, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 20, 'OT', 'Chi phái Ma-na-se đóng trại bên cạnh Eùp-ra-im; quan trưởng của con trai Ma-na-se là Ga-ma-li-ên, con trai Phê-đát-su.'),
(3680, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 21, 'OT', 'Và đạo binh của họ, theo số điểm danh, là ba mươi hai ngàn hai trăm người.'),
(3681, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 22, 'OT', 'Chi phái Bên-gia-min; quan trưởng của con trai Bên-gia-min là A-bi-đan, con trai Ghi-đeo-ni.'),
(3682, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 23, 'OT', 'và đạo binh của họ, theo số người được kiểm điểm, là ba mươi lăm ngàn bốn trăm người.'),
(3683, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 24, 'OT', 'Tất cả những người được điểm danh theo trại quân Ép-ra-im, theo các đạo quân của họ, là một trăm ngàn tám ngàn một trăm người; họ sẽ đi thứ ba.'),
(3684, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 25, 'OT', 'Ngọn cờ của trại quân Đan và các đạo quân họ phải đóng về hướng bắc. Người lãnh đạo con trai Đan là A-hi-ê-xe, con trai A-mi-sa-đai.'),
(3685, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 26, 'OT', 'và đạo binh của họ, theo số người đã điểm danh, là sáu mươi hai ngàn bảy trăm người.'),
(3686, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 27, 'OT', 'Chi phái A-se phải đóng trại bên cạnh; quan trưởng của con trai A-se là Pha-ghi-ên, con trai của Oùc-ran.'),
(3687, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 28, 'OT', 'và đạo binh của họ, theo số người đã điểm danh, là bốn mươi mốt ngàn năm trăm người.'),
(3688, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 29, 'OT', 'Chi phái Nép-ta-li; và quan trưởng của con trai Nép-ta-li là A-hi-ra, con trai Ê-nan.'),
(3689, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 30, 'OT', 'và đạo quân của họ, theo số người được kiểm điểm, là ba mươi lăm ngàn bốn trăm người.'),
(3690, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 31, 'OT', 'Tất cả những người được chỉ định theo trại quân Đan là một trăm năm mươi bảy ngàn, sáu trăm người; họ sẽ đi về phía sau cùng theo các ngọn cờ của họ.'),
(3691, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 32, 'OT', 'Đó là những người được chỉ định trong dân Y-sơ-ra-ên theo các nhà của tổ phụ họ; tổng số những người được chỉ định trong các trại theo các đạo quân của họ là sáu trăm ngàn, ba ngàn, năm trăm và năm mươi người.'),
(3692, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 33, 'OT', 'Nhưng người Lê-vi không được điểm danh giữa con cái Y-sơ-ra-ên, theo như Đức Giê-hô-va đã truyền dặn cho Môi-se.'),
(3693, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 2, 34, 'OT', 'Dân Y-sơ-ra-ên làm y như mọi điều Đức Giê-hô-va đã truyền cho Môi-se: họ đóng trại theo các ngọn cờ của mình, và ra đi theo các gia đình và nhà tổ phụ của mình.'),
(3694, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 1, 'OT', 'Nầy là dòng dõi của A-rôn và Môi-se, về ngày Đức Giê-hô-va phán cùng Môi-se tại núi Si-na-i.'),
(3695, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 2, 'OT', 'Nầy là tên các con trai của A-rôn: trưởng nam là Na-đáp, rồi đến A-bi-hu, Ê-lê-a-sa và Y-tha-ma.'),
(3696, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 3, 'OT', 'Đây là những tên các con trai A-rôn, các thầy tế lễ đã được xức dầu và được lập tay lên để làm chức tế lễ.'),
(3697, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 4, 'OT', 'Na-đáp và A-bi-hu chết trước mặt Đức Giê-hô-va khi dâng lửa lạ trước mặt Đức Giê-hô-va trong đồng vắng Si-na-i; và họ không có con trai. Vậy Ê-lê-a-sa và Y-tha-ma làm thầy tế lễ trước mặt A-rôn, cha các người ấy.'),
(3698, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 5, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3699, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 6, 'OT', 'Hãy khiến chi phái Lê-vi lại gần, và đặt họ trước mặt A-rôn thầy tế lễ, để họ phục sự ông.'),
(3700, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 7, 'OT', 'Người Lê-vi sẽ giữ chức phận của mình và chức phận của cả hội chúng trước mặt hội mạc, để làm các công việc của đền tạm.'),
(3701, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 8, 'OT', 'Họ phải giữ mọi khí cụ của hội mạc và giữ nhiệm vụ thay mặt con cái Y-sơ-ra-ên để làm công việc phục vụ đền tạm.'),
(3702, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 9, 'OT', 'Vậy, ngươi phải giao những người Lê-vi cho A-rôn và cho các con trai người; họ đã được trao cho người từ giữa vòng con cái Y-sơ-ra-ên.'),
(3703, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 10, 'OT', 'Ngươi phải chỉ định A-rôn và các con trai người để giữ chức thầy tế lễ của mình; còn người nào không phải là thầy tế lễ mà lại đến gần thì sẽ bị xử tử.'),
(3704, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 11, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3705, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 12, 'OT', 'Nầy, chính ta đã chọn lấy người Lê-vi từ giữa con cái Y-sơ-ra-ên thế cho mọi con đầu lòng, tức là mọi đứa con đầu lòng từ lòng mẹ ra trong con cái Y-sơ-ra-ên; và người Lê-vi sẽ thuộc về ta.'),
(3706, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 13, 'OT', 'Vì mọi con đầu lòng đều thuộc về ta: trong ngày ta giết các con đầu lòng tại đất Ê-díp-tô, ta đã biệt riêng ra thánh cho ta mọi con đầu lòng trong Y-sơ-ra-ên, từ loài người cho đến loài vật; chúng nó sẽ thuộc về ta. Ta là Đức Giê-hô-va.'),
(3707, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 14, 'OT', 'Đức Giê-hô-va phán cùng Môi-se tại đồng vắng Si-na-i rằng:'),
(3708, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 15, 'OT', 'Hãy điểm số con cháu Lê-vi theo nhà các tổ phụ và theo các chi phái của chúng nó, tất cả nam giới từ một tháng tuổi trở lên, ngươi phải điểm sổ chúng.'),
(3709, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 16, 'OT', 'Môi-se bèn điểm danh họ theo mạng của Đức Giê-hô-va, y như Ngài đã truyền dạy người vậy.'),
(3710, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 17, 'OT', 'Và đây là các con trai của Lê-vi, theo tên của họ: Ghẹt-sôn, Kê-hát và Mê-ra-ri.'),
(3711, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 18, 'OT', 'Và đây là những tên của các con trai Ghẹt-sôn, theo các họ hàng của chúng: Líp-ni và Si-mê-y.'),
(3712, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 19, 'OT', 'Các con trai của Kê-hát theo các họ hàng mình: Am-ram, Dít-sa, Hếp-rôn và U-xi-ên.'),
(3713, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 20, 'OT', 'Các con trai của Mê-ra-ri, theo các họ hàng của họ, là Mách-li và Mu-si; những người này là các họ hàng của người Lê-vi, theo các nhà tổ phụ của họ.'),
(3714, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 21, 'OT', 'Họ hàng của Ghẹt-sôn: họ hàng của Líp-ni và họ hàng của Si-mê-y; ấy là các họ hàng của người Ghẹt-sôn.'),
(3715, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 22, 'OT', 'Số người được kiểm điểm trong gia đình Ghẹt-sôn, gồm mọi nam giới từ một tháng tuổi trở lên, là bảy ngàn năm trăm người.'),
(3716, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 23, 'OT', 'Các họ hàng của Ghẹt-sôn sẽ trại về phía sau đền tạm, về phía tây.'),
(3717, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 24, 'OT', 'Và người lãnh đạo của chi tộc Ghẹt-sôn là Ê-li-a-sáp, con trai của La-ên.'),
(3718, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 25, 'OT', 'Nhiệm vụ giữ gìn của các con trai Ghẹt-sôn trong hội mạc là đền tạm và trại, tấm che của nó, và bức màn cửa vào hội mạc.'),
(3719, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 26, 'OT', 'các màn của hành lang, và bức màn lối vào hành lang bao quanh nơi thánh và bàn thờ, cùng các dây chằng cho mọi công việc của nó.'),
(3720, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 27, 'OT', 'Thuộc về Kê-hát có các họ hàng: họ hàng của Am-ram, họ hàng của Dít-sa, họ hàng của Hếp-rôn và họ hàng của U-xi-ên; ấy chính là các họ hàng của người Kê-hát.'),
(3721, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 28, 'OT', 'Tám ngàn sáu trăm người nam, từ một tháng tuổi trở lên, đảm nhiệm chức vụ canh giữ nơi thánh.'),
(3722, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 29, 'OT', 'Các họ hàng của con cháu Kê-hát sẽ trại bên hông đền tạm về phía nam.'),
(3723, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 30, 'OT', 'Và người lãnh đạo của gia đình theo các chi phái của người Kê-hát là Ê-li-xa-phan, con trai của U-xi-ên.'),
(3724, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 31, 'OT', 'Người Kê-hát coi sóc hòm giao ước, cái bàn, chân đèn, các bàn thờ, và các đồ dùng thánh mà họ dùng hầu việc, cùng với bức màn và mọi công việc của nó.'),
(3725, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 32, 'OT', 'Người đứng đầu các lãnh tụ của người Lê-vi là Ê-lê-a-sa, con trai của A-rôn thầy tế lễ, được trao nhiệm vụ quản lý những người giữ sự canh giữ thánh địa.'),
(3726, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 33, 'OT', 'Thuộc về Mê-ra-ri, các họ hàng là họ hàng Mách-li và họ hàng Mu-si; ấy chính là các họ hàng của Mê-ra-ri.'),
(3727, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 34, 'OT', 'Số người được chỉ định trong nhóm Mê-ra-ri, tính theo số nam giới từ một tháng tuổi trở lên, là sáu ngàn hai trăm người.'),
(3728, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 35, 'OT', 'Và người lãnh đạo của gia đình phụ hệ các họ hàng Mê-ra-ri là Xu-ri-ên, con trai A-bi-hai; họ sẽ dựng trại về phía bắc dọc theo thành hông của đền tạm.'),
(3729, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 36, 'OT', 'Phần kiểm tra trách nhiệm giữ gìn của các con trai Mê-ra-ri gồm các tấm ván của đền tạm, các cây đòn tay, các trụ, các đế trụ, mọi đồ dùng và mọi công việc phục vụ của chúng.'),
(3730, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 37, 'OT', 'Các trụ bao quanh hành lang, và đế của chúng, các nọc và dây chằng của chúng.'),
(3731, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 38, 'OT', 'Những người đóng trại phía trước nhà tạm về phía đông, tức là phía trước Lều Hội ngộ về hướng mặt trời mọc, là Môi-se, A-rôn và các con trai người, có nhiệm vụ giữ giữ nơi thánh thay cho dân Y-sơ-ra-ên. Người ngoại nào đến gần sẽ bị xử tử.'),
(3732, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 39, 'OT', 'Hết thảy những người Lê-vi mà Môi-se và A-rôn điểm danh theo lệnh Đức Giê-hô-va, theo các họ hàng của họ, mọi nam giới từ một tháng tuổi trở lên, là hai mươi hai ngàn người.'),
(3733, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 40, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Hãy kiểm tra mọi con trưởng nam của con cái Y-sơ-ra-ên, từ một tháng tuổi trở lên, và hãy ghi lại số tên của chúng nó.'),
(3734, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 41, 'OT', 'Ta là Đức Giê-hô-va, ngươi phải nhận lấy người Lê-vi cho Ta thay thế cho mọi con đầu lòng trong con cái Y-sơ-ra-ên; và ngươi phải nhận súc vật của người Lê-vi thay thế cho mọi con đầu lòng trong súc vật của con cái Y-sơ-ra-ên.'),
(3735, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 42, 'OT', 'Môi-se đã điểm sổ mọi con trưởng nam trong các con trai của Y-sơ-ra-ên, y như Đức Giê-hô-va đã truyền cho người.'),
(3736, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 43, 'OT', 'Tất cả những con trai trưởng nam, tính theo tên gọi, từ một tháng tuổi trở lên, theo số người được kiểm tra, là hai mươi hai ngàn hai trăm bảy mươi ba người.'),
(3737, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 44, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3738, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 45, 'OT', 'Hãy lấy những người Lê-vi thế cho mọi con trưởng nam trong con cái Y-sơ-ra-ên, và súc vật của người Lê-vi thế cho súc vật của chúng; và những người Lê-vi sẽ thuộc về ta. Ta là Đức Giê-hô-va.'),
(3739, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 46, 'OT', 'Và về những người phải chuộc thay cho hai trăm bảy mươi ba người còn thừa so với số người Lê-vi trong các con trưởng nam của con cái Y-sơ-ra-ên.'),
(3740, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 47, 'OT', 'Ngươi phải lấy năm siếc-lơ cho mỗi đầu người, theo siếc-lơ nơi thánh; một siếc-lơ là hai mươi ghê-ra.'),
(3741, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 48, 'OT', 'Ngươi phải giao bạc cho A-rôn và các con trai người, là tiền chuộc những người thay thế họ.'),
(3742, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 49, 'OT', 'Vậy, Môi-se lấy bạc chuộc những người được chuộc thay cho người Lê-vi.'),
(3743, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 50, 'OT', 'Người đã lấy bạc từ những con trưởng nam của con cái Y-sơ-ra-ên, một ngàn ba trăm sáu mươi lăm siếc-lơ theo siếc-lơ của nơi thánh.'),
(3744, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 3, 51, 'OT', 'Môi-se đã giao bạc của những người được chuộc cho A-rôn và các con trai người, theo lệnh của Đức Giê-hô-va, y như Đức Giê-hô-va đã truyền cho Môi-se.'),
(3745, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se và A-rôn rằng:'),
(3746, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 2, 'OT', 'Hãy điểm danh các con trai của Kê-hát trong vòng các con trai của Lê-vi, theo các gia tộc và theo các nhà họ hàng của chúng nó,'),
(3747, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 3, 'OT', 'từ ba mươi tuổi trở lên cho đến năm mươi tuổi, tức là hết thảy những người đến làm việc phục vụ trong hội mạc.'),
(3748, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 4, 'OT', 'Đây là công việc của các con trai Kê-hát trong hội mạc, về những vật chí thánh.'),
(3749, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 5, 'OT', 'Khi dời trại đi, A-rôn và các con trai người phải đến hạ xuống bức màn che và lấy màn đó phủ lên hòm bảng chứng.'),
(3750, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 6, 'OT', 'Họ sẽ đặt một cái phủ bằng da thú màu đỏ tía lên trên, trải một tấm vải toàn bằng màu xanh biếc ở phía trên, rồi cắm các đòn khiêng vào.'),
(3751, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 7, 'OT', 'Trên bàn bánh trần thiết, họ sẽ trải một tấm vải màu xanh; trên đó, họ sẽ đặt các đĩa, các chén, các thìa rót và các bình rót lễ quán; bánh lễ hằng định cũng sẽ ở trên đó.'),
(3752, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 8, 'OT', 'Rồi họ sẽ trải trên các vật ấy một tấm vải điều, phủ nó bằng một cái lọng da thú mầu tía, và tra các đòn khiêng vào.'),
(3753, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 9, 'OT', 'Họ phải lấy một tấm vải bằng sắc điều xanh mà phủ lên chân đèn của sự sáng, các đèn của nó, các cái kẹp của nó, các cái muỗng tro của nó, và tất cả các đồ đựng dầu của nó mà người ta dùng để phục vụ cho nó.'),
(3754, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 10, 'OT', 'Rồi họ sẽ đặt chân đèn và tất cả các đồ dùng của nó vào một cái bọc bằng da thú, và đặt lên cái khiêng.'),
(3755, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 11, 'OT', 'Họ phải trải trên bàn thờ bằng vàng một tấm vải xanh, và phủ nó bằng một tấm phủ bằng da thú, rồi tra các cây khiêng vào.'),
(3756, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 12, 'OT', 'Họ phải lấy tất cả các đồ dùng để phục vụ thánh lễ mà họ dùng trong nơi thánh, đặt vào một tấm vải điều xanh, phủ chúng bằng một lớp bọc bằng da thú biển, rồi đặt lên cáng.'),
(3757, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 13, 'OT', 'Họ phải hốt tro khỏi bàn thờ, rồi trải lên đó một tấm vải điều.'),
(3758, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 14, 'OT', 'và họ sẽ đặt lên nó mọi đồ dùng phục vụ nơi nó, tức là các lư hương, các nĩa, các cái xẻng, các cái mâm, mọi đồ dùng của bàn thờ; rồi họ sẽ trải lên nó một cái phủ bằng da thú và đặt các đòn khiêng vào.'),
(3759, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 15, 'OT', 'Sau khi A-rôn và các con trai người hoàn tất việc che phủ các vật thánh và mọi đồ dùng thánh, khi trại quân dời đi, thì các con cháu Kê-hát mới được đến khiêng; họ không được đụng vào các vật thánh, kẻo phải chết. Đó là gánh nặng mà các con cháu Kê-hát phải mang trong Hội mạc.'),
(3760, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 16, 'OT', 'Ê-lê-a-sa, con trai thầy tế lễ A-rôn, sẽ coi sóc dầu thắp đèn, hương liệu, của lễ chay hằng hiến, dầu xức, toàn thể đền tạm và mọi vật ở trong nơi thánh cùng các đồ phụ tùng của nó.'),
(3761, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 17, 'OT', 'Đức Giê-hô-va phán cùng Môi-se và A-rôn rằng:'),
(3762, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 18, 'OT', 'Chớ diệt trừ các họ hàng của chi phái Kê-hát giữa vòng các người Lê-vi.'),
(3763, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 19, 'OT', 'Và điều nầy các ngươi phải làm cho họ, để họ được sống và không chết khi đến gần nơi thánh của các nơi thánh: A-rôn và các con trai người phải đến, đặt mỗi người vào chức việc của mình và vào gánh nặng mà họ phải mang.'),
(3764, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 20, 'OT', 'Chúng không được vào xem những vật thánh, khi những vật ấy bị che khuất, e chết mất.'),
(3765, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 21, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3766, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 22, 'OT', 'Hãy đem các con cháu Ghẹt-sôn ra, theo nhà phụ hệ và các chi phái của chúng.'),
(3767, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 23, 'OT', 'Từ con trai ba mươi tuổi trở lên cho đến con trai năm mươi tuổi, ngươi phải kiểm tra tất cả những người đến nhập ngũ để làm việc trong hội mạc.'),
(3768, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 24, 'OT', 'Đây là công việc của các họ hàng Ghẹt-sôn: phải làm việc và khiêng đồ.'),
(3769, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 25, 'OT', 'Họ sẽ khiêng những tấm trải của đền tạm và lều hội ngộ, tấm phủ bên trên của nó và tấm phủ bằng da thú mầu đỏ sậm ở bên trên cùng, cùng với bức màn cửa lều hội ngộ.'),
(3770, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 26, 'OT', 'và các tấm màn hành lang, cùng bức màn cửa vào hành lang bao quanh đền tạm và bàn thờ, các dây thừng của chúng, và mọi đồ dùng để làm công việc ấy, và mọi điều phải làm cho các vật đó, thì chúng sẽ phục vụ.'),
(3771, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 27, 'OT', 'Theo lịnh A-rôn và các con trai người, sẽ là mọi công việc của con cháu Ghẹt-sôn, mọi thứ họ phải khiêng và mọi việc họ phải làm; và ngươi phải giao cho họ coi sóc mọi thứ họ phải khiêng.'),
(3772, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 28, 'OT', 'Đây là công việc của các gia tộc con cái Ghẹt-sôn trong hội mạc; chức trách của họ dưới quyền quản lý của Y-tha-ma, con trai thầy tế lễ A-rôn.'),
(3773, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 29, 'OT', 'Hãy điểm danh con cháu Mê-ra-ri theo các họ hàng và nhà cha ông của họ.'),
(3774, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 30, 'OT', 'Từ ba mươi tuổi trở lên cho đến năm mươi tuổi, ngươi phải kiểm tra tất cả những người đến phục vụ công việc nơi Hội mạc.'),
(3775, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 31, 'OT', 'Đây là bổn phận phải khiêng mang của họ trong mọi công việc tại hội mạc: các tấm ván của đền tạm, các thanh ngang, các trụ và các đế trụ.'),
(3776, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 32, 'OT', 'các trụ bao quanh hành lang cùng các đế lót, các cái chốt và dây giằng của chúng, cùng mọi đồ dùng và mọi vật dụng phục vụ công việc ấy; theo danh sách, các ngươi sẽ điểm danh những đồ dùng thuộc nhiệm vụ gánh vác của họ.'),
(3777, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 33, 'OT', 'Đó là công việc của các họ hàng con cháu Mê-ra-ri, về mọi công việc của họ trong Hội mạc, dưới quyền Y-tha-ma, con trai thầy tế lễ A-rôn.'),
(3778, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 34, 'OT', 'Môi-se, A-rôn và các trưởng hội đồng đã điểm danh con cháu Kê-hát theo các họ hàng và theo các nhà tổ phụ của họ.'),
(3779, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 35, 'OT', 'từ con trai ba mươi tuổi trở lên cho đến con trai năm mươi tuổi, tất cả những người đến phục vụ công việc trong hội mạc;'),
(3780, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 36, 'OT', 'Số người được kiểm kê theo các gia tộc của họ là hai ngàn bảy trăm năm mươi người.'),
(3781, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 37, 'OT', 'Đó là những người được điểm danh theo các họ hàng của Kê-hát, tất cả những người phục vụ trong hội mạc mà Môi-se và A-rôn điểm danh theo lệnh của Đức Giê-hô-va qua tay Môi-se.'),
(3782, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 38, 'OT', 'Còn những người được điểm danh trong con cháu của Ghẹt-sôn, theo các chi họ và các nhà tổ phụ của họ,'),
(3783, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 39, 'OT', 'từ ba mươi tuổi trở lên cho đến năm mươi tuổi, tức là tất cả những người đến phiên phục vụ công việc trong hội mạc,'),
(3784, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 40, 'OT', 'Họ được điểm danh theo các chi phái, theo các nhà tổ phụ của mình, gồm hai ngàn sáu trăm ba mươi người.'),
(3785, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 41, 'OT', 'Đây là những người được chỉ định theo các họ hàng của con cháu Ghẹt-sôn, mọi người phục vụ trong hội mạc, mà Môi-se và A-rôn đã chỉ định theo lệnh của Đức Giê-hô-va.'),
(3786, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 42, 'OT', 'Còn những người thuộc các họ hàng con cháu Mê-ra-ri đã được kiểm tra theo các họ hàng và theo các nhà tổ phụ của họ.'),
(3787, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 43, 'OT', 'từ ba mươi tuổi trở lên cho đến năm mươi tuổi, tất cả những người đến phục vụ công việc trong hội mạc,'),
(3788, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 44, 'OT', 'Ba ngàn hai trăm người, theo các chi phái tổ tiên của họ.'),
(3789, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 45, 'OT', 'Đó là những người thuộc các gia tộc con cháu Mê-ra-ri mà Môi-se và A-rôn đã điểm danh theo lệnh của Đức Giê-hô-va, do tay Môi-se thực hiện.'),
(3790, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 46, 'OT', 'Hết thảy những người được Môi-se, A-rôn và các trưởng tộc Y-sơ-ra-ên điểm danh trong vòng người Lê-vi, theo các họ hàng và các nhà tổ phụ của họ,'),
(3791, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 47, 'OT', 'Từ con trai ba mươi tuổi trở lên cho đến con trai năm mươi tuổi, tất cả những người đến làm công việc phục vụ và công việc khiêng đồ trong hội mạc,'),
(3792, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 48, 'OT', 'Tám ngàn năm trăm tám mươi người.'),
(3793, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 4, 49, 'OT', 'Theo lệnh của Đức Giê-hô-va, Môi-se đã kiểm tra họ, mỗi người theo công việc mình và theo gánh nặng mình phải mang, theo đúng điều Đức Giê-hô-va đã truyền cho Môi-se.'),
(3794, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 5, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3795, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 5, 2, 'OT', 'Hãy truyền cho con cái Y-sơ-ra-ên phải đuổi ra khỏi trại quân mọi người phong cùi, mọi người bị xuất tinh và mọi người bị ô uế vì chết.'),
(3796, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 5, 3, 'OT', 'Dù là nam hay nữ, các ngươi phải đuổi họ ra ngoài trại quân; như vậy họ sẽ không làm cho trại quân của Ta, là nơi Ta ngự giữa họ, bị ô uế.'),
(3797, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 5, 4, 'OT', 'Dân Y-sơ-ra-ên bèn làm như vậy, đuổi họ ra khỏi trại quân, y như Đức Giê-hô-va đã truyền cho Môi-se; dân Y-sơ-ra-ên làm như vậy.'),
(3798, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 5, 5, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3799, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 5, 6, 'OT', 'Hãy nói cùng con cái Y-sơ-ra-ên rằng: Nếu một người nam hoặc nữ phạm một trong các tội mà loài người thường phạm, làm điều bất trung cùng Đức Giê-hô-va, thì linh hồn ấy sẽ mang tội.'),
(3800, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 5, 7, 'OT', 'Người ấy phải thú nhận tội mình đã phạm, và bồi hoàn đầy đủ món nợ ấy, lại thêm một phần năm nữa, rồi giao cho người mà mình đã làm tổn hại.'),
(3801, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 5, 8, 'OT', 'Nếu không có người nào thuộc về người ấy để trả lại số tiền bồi thường cho, thì số tiền bồi thường phải trả cho Đức Giê-hô-va, tức là cho thầy tế lễ, ngoại trừ con chiên đực dùng làm lễ chuộc tội mà thầy tế lễ sẽ dùng để làm lễ chuộc tội cho người ấy.'),
(3802, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 5, 9, 'OT', 'Mọi lễ vật dâng cho Đức Chúa Trời từ các vật thánh của con cái Y-sơ-ra-ên mà họ dâng cho thầy tế lễ thì sẽ thuộc về thầy tế lễ ấy.'),
(3803, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 5, 10, 'OT', 'Mỗi người sẽ được hưởng những vật thánh của mình; vật gì mỗi người dâng cho thầy tế lễ thì sẽ thuộc về người ấy.'),
(3804, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 5, 11, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3805, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 5, 12, 'OT', 'Hãy nói với các con trai của Y-sơ-ra-ên và bảo họ: Nếu người nào có vợ phạm tội bất trung và phạm tội phản lại chồng,'),
(3806, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 5, 13, 'OT', 'nếu có người nam nằm cùng nàng trong sự giao hợp, mà điều đó khuất khỏi mắt chồng nàng, và nàng đã bị che giấu, thì nàng đã bị ô uế; không có nhân chứng về việc đó nơi nàng, và nàng cũng không bị bắt tại chỗ;'),
(3807, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 5, 14, 'OT', 'hoặc thần ghen tuông xâm chiếm người ấy, khiến người ấy ghen vợ mình, mà vợ đã thật bị ô uế; hoặc thần ghen tuông xâm chiếm người ấy, khiến người ấy ghen vợ mình, mà vợ chưa thật bị ô uệ.'),
(3808, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 5, 15, 'OT', 'Người chồng phải dẫn vợ mình đến cùng thầy tế lễ, và vì nàng mà dâng của lễ mình là một phần mười e-pha bột lúa mạch; người không được đổ dầu lên trên, cũng không được bỏ nhũ hương lên trên, vì đó là của lễ chay về sự ghen tương, của lễ chay để nhắc lại tội lỗi.'),
(3809, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 5, 16, 'OT', 'Thầy tế lễ sẽ dẫn người nữ ấy đến, và đặt nàng đứng trước mặt Đức Giê-hô-va.'),
(3810, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 5, 17, 'OT', 'Rồi thầy tế lễ sẽ lấy nước thánh đổ vào một cái bình bằng đất, và thầy tế lễ sẽ lấy bụi ở trên nền của đền tạm mà bỏ vào nước.'),
(3811, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 5, 18, 'OT', 'Rồi thầy tế lễ phải cho người đàn bà đứng trước mặt Đức Giê-hô-va, xốc tóc người đàn bà ra, đặt trên tay nàng lễ vật kỷ niệm, lễ vật chay về sự ghen tương; và trong tay thầy tế lễ phải có nước đắng gây rủa sả.'),
(3812, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 5, 19, 'OT', 'Thầy tế lễ phải khiến người đàn bà ấy thề, rồi nói với nàng rằng: Nếu không một người nam nào đã nằm cùng ngươi, và nếu ngươi không phạm tội ô uế mà phản lại chồng mình, thì ngươi sẽ được thoát khỏi nước đắng gây rủa sả này.'),
(3813, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 5, 20, 'OT', 'Nhưng ngươi, vì đã phạm tội ngoại tình khi còn dưới quyền chồng, vì đã tự làm mình ô uế, và có một người khác ngoài chồng ngươi đã nằm cùng ngươi,'),
(3814, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 5, 21, 'OT', 'Thầy tế lễ phải khiến người phụ nữ thề bằng lời thề rủa sả, và thầy tế lễ nói với người phụ nữ rằng: Đức Giê-hô-va khiến cho ngươi trở thành lời rủa sả và lời thề giữa vòng dân sự ngươi, khi Đức Giê-hô-va khiến hông ngươi sụp xuống và bụng ngươi sưng phồng;'),
(3815, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 5, 22, 'OT', 'Các nước rủa sả nầy khá vào trong lòng ngươi, khiến cho bụng ngươi phình ra và đùi ngươi teo mòn. Người đàn bà ấy sẽ nói: A-men, A-men!'),
(3816, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 5, 23, 'OT', 'Rồi thầy tế lễ sẽ viết các lời nguyền rủa nầy vào sách, và xóa chúng vào nước đắng.'),
(3817, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 5, 24, 'OT', 'Thầy tế lễ sẽ cho người đàn bà ấy uống nước đắng có lời rủa sả, và nước đắng có lời rủa sả ấy sẽ vào trong người nàng để gây nên sự đắng cay cho nàng.'),
(3818, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 5, 25, 'OT', 'Rồi thầy tế lễ sẽ lấy khỏi tay người nữ lễ vật chay về sự ghen tương, đưa lễ vật chay ấy qua lại trước mặt Đức Giê-hô-va, và dẫn dâng nó gần bàn thờ.'),
(3819, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 5, 26, 'OT', 'Thầy tế lễ phải lấy một nắm lễ vật chay làm phần tưởng nhớ, đem đốt trên bàn thờ; sau đó mới biểu người vợ uống nước ấy.'),
(3820, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 5, 27, 'OT', 'Người ta sẽ cho người phụ nữ ấy uống nước ấy; nếu nàng quả thực đã bị ô uế và phạm tội bất trung với chồng mình, thì nước gây rủa sả nầy sẽ vào trong mình nàng để gây đắng cay; bụng nàng sẽ sưng phồng lên, đùi nàng sẽ teo mòn, và người phụ nữ ấy sẽ trở nên một lời rủa sả giữa vòng dân sự nàng.'),
(3821, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 5, 28, 'OT', 'Nếu người đàn bà ấy không bị ô uế, mà thật sự thanh sạch, thì sẽ được trắng án và sẽ được ban cho con cháu.'),
(3822, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 5, 29, 'OT', 'Đây là luật lệ về sự ghen tuông, khi một người vợ phạm tội bất trung với chồng mình và bị ô uế.'),
(3823, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 5, 30, 'OT', 'hoặc khi một người chồng bị thần ghen tuông xâm chiếm, mà ghen vợ mình, thì phải dẫn vợ đến trước mặt Đức Giê-hô-va, và thầy tế lễ sẽ làm cho nàng mọi điều luật lệ nầy.'),
(3824, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 5, 31, 'OT', 'Người đàn ông sẽ được tha khỏi tội lỗi; còn người đàn bà ấy sẽ mang lấy tội mình.'),
(3825, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 6, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3826, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 6, 2, 'OT', 'Hãy nói với con cái Y-sơ-ra-ên rằng: Người nam hay người nữ, nếu muốn khấn hứa một lời thề Na-xi-rê, để biệt riêng mình ra cho Đức Giê-hô-va,'),
(3827, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 6, 3, 'OT', 'Chớ uống rượu, vật uống say, giấm rượu hay giấm của vật uống say; chớ uống bất kỳ thứ nước nào chế từ nho, cũng đừng ăn nho tươi hay nho khô.'),
(3828, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 6, 4, 'OT', 'Trong mọi ngày người biệt riêng mình, người không được ăn bất cứ vật gì làm từ cây nho, từ hột nho cho đến vỏ nho.'),
(3829, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 6, 5, 'OT', 'Trọn mọi ngày hứa nguyện Na-xi-rê mình, dao cạo sẽ không được đưa trên đầu người ấy; cho đến khi trọn những ngày người ấy biệt mình riêng ra cho Đức Giê-hô-va, người ấy sẽ nên thánh, phải để tóc đầu mình mọc dài.'),
(3830, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 6, 6, 'OT', 'Trọn mọi ngày người biệt riêng mình cho Đức Giê-hô-va, chớ đến gần một người chết nào.'),
(3831, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 6, 7, 'OT', 'Người không được làm mình ô uế vì cha mình hay vì mẹ mình, vì anh trai hay vì chị gái mình khi họ chết, vì triều miện của Đức Chúa Trời ở trên đầu người.'),
(3832, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 6, 8, 'OT', 'Trọn những ngày của sự biệt riêng Na-xi-rê, người ấy là thánh cho Đức Giê-hô-va.'),
(3833, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 6, 9, 'OT', 'Nếu có người chết thình lình gần người ấy, làm cho đầu của người đã biệt riêng ra thánh bị ô uế, thì phải cạo đầu mình trong ngày được sạch, tức là ngày thứ bảy.'),
(3834, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 6, 10, 'OT', 'Vào ngày thứ tám, người ấy phải mang hai con chim cu hoặc hai con bồ câu con đến cho thầy tế lễ tại cửa nhà hội.'),
(3835, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 6, 11, 'OT', 'Vị thầy tế lễ sẽ dâng một con làm của lễ chuộc tội và một con làm của lễ toàn thiêu, rồi làm lễ chuộc tội cho người ấy vì tội lỗi người đã phạm do xác chết; và trong ngày đó, người ấy sẽ biệt riêng đầu mình ra thánh.'),
(3836, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 6, 12, 'OT', 'Người phải biệt riêng ra cho Đức Giê-hô-va những ngày về nguyện Na-xi-rê mình, và dâng một con chiên đực giáp năm làm của lễ chuộc tội; còn những ngày trước đây thì không kể, vì nguyện Na-xi-rê của người đã bị ô uế.'),
(3837, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 6, 13, 'OT', 'Đây là luật lệ về người Na-xi-rê: khi trọn những ngày về thời Na-xi-rê của người ấy, thì phải đem người ấy đến nơi cửa Hội mạc.'),
(3838, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 6, 14, 'OT', 'người phải dâng của lễ mình cho Đức Giê-hô-va, một con chiên đực giáp năm không tật, làm của lễ thiêu, một con chiên cái giáp năm không tật, làm của lễ chuộc tội, và một con chiên đực không tật, làm của lễ thù ân;'),
(3839, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 6, 15, 'OT', 'một giỏ bánh không men bằng bột lọc, các bánh nhỏ nhồi dầu và các bánh tráng không men phết dầu, cùng với lễ vật chay và lễ đồ uống của chúng.'),
(3840, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 6, 16, 'OT', 'Thầy tế lễ sẽ dâng các lễ vật nầy trước mặt Đức Giê-hô-va, và làm lễ chuộc tội cùng lễ thiêu của người.'),
(3841, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 6, 17, 'OT', 'và lấy chiên đực, dâng làm của lễ thù ân cho Đức Giê-hô-va, ngoài giỏ bánh không men; thầy tế lễ sẽ dâng của lễ chay và của lễ quán người ấy.'),
(3842, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 6, 18, 'OT', 'Người Na-xi-rê phải cạo đầu mình đã biệt riêng ra tại cửa nhà tạm; lấy tóc trên đầu mình đã biệt riêng ra mà để trên lửa dưới của lễ thù ân.'),
(3843, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 6, 19, 'OT', 'Sau khi người Na-xi-rê cạo đầu mình, thầy tế lễ sẽ lấy cái đùi trước của con chiên đực, một ổ bánh không men từ trong giỏ, và một bánh phẳng không men, rồi đặt trên hai tay người Na-xi-rê.'),
(3844, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 6, 20, 'OT', 'Rồi thầy tế lễ sẽ dâng các vật đó làm lễ lay trước mặt Đức Giê-hô-va; ấy là vật thánh thuộc về thầy tế lễ, gồm ngực lễ lay và cái chân dâng hiến; sau đó, người Na-xi-rê mới được uống rượu.'),
(3845, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 6, 21, 'OT', 'Đó là luật lệ về người Na-xi-rê đã hứa nguyện, của lễ người ấy dâng cho Đức Giê-hô-va về thời kỳ Na-xi-rê mình, ngoài điều mà tay người ấy có thể dâng thêm; theo đúng lời hứa nguyện mình đã hứa, người ấy phải làm như vậy, theo luật lệ về thời kỳ Na-xi-rê mình.'),
(3846, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 6, 22, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3847, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 6, 23, 'OT', 'Hãy nói cùng A-rôn và các con trai người rằng: Các ngươi phải chúc phước cho con cái Y-sơ-ra-ên như thế này:'),
(3848, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 6, 24, 'OT', 'Đức Giê-hô-va ban phước cho ngươi và giữ gìn ngươi.'),
(3849, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 6, 25, 'OT', 'Xin Đức Giê-hô-va soi sáng mặt Ngài về phía ngươi và thương xót ngươi.'),
(3850, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 6, 26, 'OT', 'Đức Giê-hô-va sẽ soi mặt Ngài về phía ngươi và ban cho ngươi sự bình an.'),
(3851, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 6, 27, 'OT', 'Họ phải đặt danh Đức Giê-hô-va trên các con trai của Y-sơ-ra-ên, và chính Ta sẽ ban phước cho họ.'),
(3852, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 1, 'OT', 'Khi Môi-se đã dựng xong đền tạm, thì người xức dầu và biệt riêng ra thánh đền tạm cùng mọi đồ dùng của nó, và bàn thờ cùng mọi đồ dùng của nó; người xức dầu và biệt riêng ra thánh các vật ấy.'),
(3853, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 2, 'OT', 'Các quan trưởng của Y-sơ-ra-ên, là những người đứng đầu các nhà họ hàng của mình, tức các quan trưởng các chi phái, là những người đứng đầu các đơn vị được kiểm điểm, đã dâng mình lên.'),
(3854, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 3, 'OT', 'Họ mang lễ vật của mình đến trước mặt Đức Giê-hô-va: sáu xe bò và mười hai con bò đực, mỗi hai chiếc xe dành cho hai vị lãnh tụ, và mỗi con bò dành cho một người; họ dâng những lễ vật ấy trước mặt đền tạm.'),
(3855, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 4, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3856, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 5, 'OT', 'Hãy nhận lấy từ họ, và chúng sẽ dùng để làm công việc tại Hội mạc; ngươi hãy trao chúng cho người Lêvi, mỗi người tùy theo công việc mình.'),
(3857, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 6, 'OT', 'Vậy, Môi-se nhận lấy các xe và bò, rồi trao cho người Lê-vi.'),
(3858, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 7, 'OT', 'Giao cho con cháu Ghẹt-sôn hai cái xe và bốn con bò, tùy theo công việc của họ.'),
(3859, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 8, 'OT', 'Người giao cho con cháu Mê-ra-ri bốn cái xe và tám con bò đực, tùy theo chức vụ phục vụ của họ, dưới quyền quản lý của Y-tha-ma, con trai thầy tế lễ A-rôn.'),
(3860, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 9, 'OT', 'Nhưng người không ban cho các con trai Kê-hát, vì công việc về các vật thánh thuộc về họ, họ phải khiêng các vật đó trên vai mình.'),
(3861, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 10, 'OT', 'Các quan trưởng dâng lễ khánh thành bàn thờ trong ngày bàn thờ được xức dầu; các quan trưởng dâng lễ vật mình trước mặt bàn thờ.'),
(3862, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 11, 'OT', 'Đức Giê-hô-va phán cùng Môi-se: Mỗi ngày một quan trưởng, mỗi ngày một quan trưởng sẽ dâng lễ vật mình cho lễ khánh thành bàn thờ.'),
(3863, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 12, 'OT', 'Người dâng lễ vật mình trong ngày đầu tiên là Na-ha-sôn, con trai của A-mi-na-đáp, thuộc chi phái Giu-đa.'),
(3864, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 13, 'OT', 'Lễ vật của người là một cái đĩa bạc nặng một trăm ba mươi siếc-lơ, một cái bình bạc duy nhất nặng bảy mươi siếc-lơ, theo đơn vị siếc-lơ của nơi thánh; cả hai thứ đều đầy bột lọc nhồi dầu, dùng về lễ vật chay.'),
(3865, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 14, 'OT', 'một cái chén bằng vàng mười, đầy hương thơm;'),
(3866, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 15, 'OT', 'một con bò đực đực, một con chiên đực, một con chiên con tròn một năm, dùng về của lễ thiêu;'),
(3867, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 16, 'OT', 'một con dê đực dùng về của lễ chuộc tội;'),
(3868, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 17, 'OT', 'Về của lễ thù ân, hai con bò, năm con chiên đực, năm con dê đực, năm con chiên con giáp năm. Đó là lễ vật của Na-ha-sôn, con trai A-mi-na-đáp.'),
(3869, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 18, 'OT', 'Ngày thứ hai, Na-tha-na-ên, con trai của Xu-a, quan trưởng của Y-sa-ca, dâng của lễ mình.'),
(3870, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 19, 'OT', 'Dâng lễ vật của mình: một cái đĩa bạc nặng một trăm ba mươi siếc-lơ, một cái chậu bạc nặng bảy mươi siếc-lơ, theo siếc-lơ của nơi thánh, cả hai cái đều đầy bột lọc trộn dầu, dùng về lễ vật chay;'),
(3871, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 20, 'OT', 'một cái dĩa vàng nặng mười siếc-lơ, đầy thuốc trầm hương;'),
(3872, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 21, 'OT', 'một con bò đực tơ, một con chiên đực, một con chiên con tròn một năm, dùng về của lễ thiêu;'),
(3873, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 22, 'OT', 'một con dê đực để làm của lễ chuộc tội;'),
(3874, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 23, 'OT', 'Và về của lễ thù ân, hai con bò đực, năm con chiên đực, năm con dê đực, năm chiên con một tuổi. Đó là lễ vật của Na-tha-na-ên, con trai Xu-a.'),
(3875, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 24, 'OT', 'Ngày thứ ba, một lãnh tụ của con cháu Sa-bu-lôn, Ê-li-áp, con trai của Hê-lôn.'),
(3876, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 25, 'OT', 'Lễ vật của người là một cái đĩa bạc nặng một trăm ba mươi siếc-lơ, một cái chậu bạc nặng bảy mươi siếc-lơ, theo siếc-lơ của nơi thánh; cả hai đều đầy bột lọc nhồi dầu, dùng về lễ vật chay.'),
(3877, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 26, 'OT', 'một cái đĩa vàng mười siếc-lơ, đầy hương thơm;'),
(3878, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 27, 'OT', 'một con bò đực tơ, một con chiên đực, một con chiên con tròn một tuổi, dùng về của lễ thiêu;'),
(3879, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 28, 'OT', 'một con dê đực để làm của lễ chuộc tội;'),
(3880, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 29, 'OT', 'Về lễ hy sinh hóa lễ, hai con bò đực, năm con chiên đực, năm con dê đực, năm con chiên con một tuổi. Đó là lễ vật của Ê-li-áp, con trai Hê-lôn.'),
(3881, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 30, 'OT', 'Ngày thứ tư, một lãnh tụ thuộc con cháu Ru-bên, Ê-li-xu, con trai của Sê-đêu.'),
(3882, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 31, 'OT', 'Lễ vật của người là một cái đĩa bạc nặng một trăm ba mươi siếc-lơ, một cái thìa bạc nặng bảy mươi siếc-lơ theo siếc-lơ của nơi thánh; cả hai đều đầy bột lọc nhồi dầu, dùng về của lễ chay.'),
(3883, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 32, 'OT', 'một cái đĩa vàng nặng mười siếc-lơ, đầy hương thơm;'),
(3884, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 33, 'OT', 'một con bò đực tơ, một con chiên đực, một con chiên con trống một tuổi, dùng về của lễ thiêu;'),
(3885, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 34, 'OT', 'một con dê đực dùng về của lễ chuộc tội;'),
(3886, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 35, 'OT', 'Và về của lễ thù ân, hai con bò, năm con chiên đực, năm con dê đực, năm con chiên con một tuổi. Đó là lễ vật của Ê-lít-xu, con trai Sê-đêu.'),
(3887, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 36, 'OT', 'Ngày thứ năm, vị lãnh tụ của con cái Si-mê-ôn, là Sê-lu-mi-ên, con trai Xu-ri-ha-đai.'),
(3888, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 37, 'OT', 'Lễ vật của người là một cái đĩa bạc nặng một trăm ba mươi siếc-lơ, một cái chậu bạc nặng bảy mươi siếc-lơ, theo siếc-lơ của nơi thánh; cả hai cái đều đầy bột lọc nhồi dầu, dùng về của lễ chay.'),
(3889, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 38, 'OT', 'một cái thìa vàng mười siếc-lơ, đầy thuốc trầm hương;'),
(3890, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 39, 'OT', 'một con bò đực tơ, một con chiên đực, một con chiên con tròn một tuổi, dùng về của lễ thiêu;'),
(3891, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 40, 'OT', 'một con dê đực để làm của lễ chuộc tội;'),
(3892, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 41, 'OT', 'Về lễ tế thù ân, hai con bò, năm con chiên đực, năm con dê đực, và năm con chiên con một tuổi. Đó là của lễ dâng của Sê-lu-mi-ên, con trai Xu-ri-ha-đai.'),
(3893, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 42, 'OT', 'Ngày thứ sáu, người lãnh đạo của con cháu Gát, Ê-li-a-sáp con trai Đê-u-ên.'),
(3894, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 43, 'OT', 'Lễ vật của người là một cái đĩa bạc nặng một trăm ba mươi siếc-lơ, một cái thìa bạc nặng bảy mươi siếc-lơ, theo siếc-lơ của nơi thánh; cả hai cái đều đầy bột lọc trộn dầu, dùng về lễ vật chay.'),
(3895, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 44, 'OT', 'một cái thìa vàng mười siếc-lơ, đầy thuốc thơm;'),
(3896, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 45, 'OT', 'một con bò đực tơ, một con chiên đực, một con chiên con tròn một tuổi, dùng về của lễ thiêu;'),
(3897, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 46, 'OT', 'một con dê đực để làm của lễ chuộc tội;'),
(3898, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 47, 'OT', 'Về của lễ thù ân, hai con bò, năm con chiên đực, năm con dê đực, và năm con chiên con một tuổi. Đó là lễ vật của Ê-li-a-sáp, con trai Đê-u-ên.'),
(3899, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 48, 'OT', 'Ngày thứ bảy, quan trưởng của con cháu Eùp-ra-im là Ê-li-sa-ma, con trai A-mi-hút.'),
(3900, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 49, 'OT', 'Lễ vật của người là một cái đĩa bạc nặng một trăm ba mươi siếc-lơ, một cái chậu bạc nặng bảy mươi siếc-lơ, theo siếc-lơ của nơi thánh; cả hai cái đều đầy bột lọc nhồi dầu, dùng về của lễ chay.'),
(3901, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 50, 'OT', 'một cái chén vàng mười siếc-lơ đầy thuốc thơm;'),
(3902, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 51, 'OT', 'một con bò đực tơ, một con chiên đực, một con chiên con tròn một năm, dùng về của lễ thiêu;'),
(3903, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 52, 'OT', 'một con dê cái để làm của lễ chuộc tội;'),
(3904, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 53, 'OT', 'Về của lễ thù ân, hai con bò, năm con chiên đực, năm con dê đực, và năm con chiên con một tuổi. Đó là lễ vật của Ê-li-sa-ma, con trai A-mi-hút.'),
(3905, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 54, 'OT', 'Ngày thứ tám, là quan trưởng của con cháu Ma-na-se, Ga-ma-li-ên, con trai Phê-đát-su.'),
(3906, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 55, 'OT', 'Lễ vật của người là một cái đĩa bạc nặng một trăm ba mươi siếc-lơ, một cái muỗng bạc nặng bảy mươi siếc-lơ, theo siếc-lơ của nơi thánh; cả hai đều đầy bột lọc nhồi dầu, dùng về của lễ chay.'),
(3907, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 56, 'OT', 'một cái chén bằng vàng ròng, đầy thuốc trầm hương;'),
(3908, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 57, 'OT', 'một con bò đực tơ, một con chiên đực, một con chiên con đực một tuổi, dùng về của lễ thiêu;'),
(3909, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 58, 'OT', 'một con dê đực dùng về của lễ chuộc tội;'),
(3910, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 59, 'OT', 'và về của lễ thù ân, hai con bò đực, năm con chiên đực, năm con dê đực, năm con chiên con một tuổi. Đó là lễ vật của Ga-ma-li-ên, con trai Phê-đát-su.'),
(3911, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 60, 'OT', 'Ngày thứ chín, vị lãnh tụ của con cháu Bên-gia-min: A-bi-đan, con trai của Ghi-đeo-ni.'),
(3912, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 61, 'OT', 'Lễ vật của người là một cái đĩa bạc nặng một trăm ba mươi siếc-lơ, một cái muỗng bạc nặng bảy mươi siếc-lơ theo siếc-lơ của nơi thánh, cả hai cái đều đầy bột lọc nhồi dầu để làm lễ vật chay;'),
(3913, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 62, 'OT', 'một cái chén vàng mười siếc-lơ đầy đầy thuốc trầm hương;'),
(3914, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 63, 'OT', 'một con bò đực tơ, một con chiên đực, một con chiên con tròn một năm, dùng về của lễ thiêu;'),
(3915, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 64, 'OT', 'một con dê đực dùng về của lễ chuộc tội;'),
(3916, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 65, 'OT', 'Về lễ hy lễ cầu an: hai con bò đực, năm con chiên đực, năm con dê đực, năm con chiên con một tuổi. Đó là của lễ dâng của A-bi-đan, con trai Ghi-đeo-ni.'),
(3917, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 66, 'OT', 'Ngày thứ mười, vị lãnh tụ của con cháu Đan, là A-hi-ê-xe, con trai A-mi-sa-đai.'),
(3918, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 67, 'OT', 'Lễ vật của người là một cái đĩa bạc nặng một trăm ba mươi siếc-lơ, một cái muỗng bạc nặng bảy mươi siếc-lơ, theo siếc-lơ của nơi thánh; cả hai đều đầy bột lọc nhồi dầu, dùng về của lễ chay;'),
(3919, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 68, 'OT', 'một cái đĩa vàng mười siếc-lơ, đầy thuốc thơm;'),
(3920, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 69, 'OT', 'một con bò đực tơ, một con chiên đực, một con chiên con một tuổi, dùng về của lễ thiêu;'),
(3921, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 70, 'OT', 'một con dê đực để làm của lễ chuộc tội;'),
(3922, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 71, 'OT', 'Về lễ hy sinh hóa bình an: hai con bò, năm con chiên đực, năm con dê đực, và năm con chiên con một tuổi. Đó là của lễ dâng của A-hi-ê-xe, con trai A-mi-sa-đai.'),
(3923, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 72, 'OT', 'Ngày thứ mười một, vị lãnh tụ của con cháu A-se, là Pha-ghi-ên, con trai của Oùc-ran.'),
(3924, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 73, 'OT', 'Lễ vật của người là một cái đĩa bạc nặng một trăm ba mươi siếc-lơ, một cái muỗng bạc nặng bảy mươi siếc-lơ, theo siếc-lơ của nơi thánh, cả hai cái đều đầy bột lọc nhồi dầu, dùng về của lễ chay;'),
(3925, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 74, 'OT', 'một cái đĩa bằng vàng mười siếc-lơ, đầy thuốc trầm hương;'),
(3926, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 75, 'OT', 'một con bò đực tơ, một con chiên đực, một con chiên con trai một tuổi, dùng về của lễ thiêu;'),
(3927, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 76, 'OT', 'một con dê đực dùng về của lễ chuộc tội;'),
(3928, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 77, 'OT', 'Về của lễ thù ân, hai con bò đực, năm con chiên đực, năm con dê đực, năm con chiên con một tuổi. Đó là lễ vật của Pha-ghi-ên, con trai Oùc-ran.'),
(3929, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 78, 'OT', 'Ngày thứ mười hai, một thủ lãnh của con cái Nép-ta-li, là A-hi-ra, con trai của Ê-nan.'),
(3930, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 79, 'OT', 'Lễ vật của người là một cái đĩa bạc nặng một trăm ba mươi siếc-lơ, một cái chậu bạc nặng bảy mươi siếc-lơ, theo siếc-lơ của nơi thánh; cả hai cái đều đầy bột lọc nhồi dầu, dùng về của lễ chay.'),
(3931, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 80, 'OT', 'một cái đĩa bằng vàng mười quen-ta, đầy thuốc thơm;'),
(3932, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 81, 'OT', 'một con bò đực, một con chiên đực, một con chiên con trai một tuổi, dùng về của lễ thiêu;'),
(3933, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 82, 'OT', 'một con dê đực để làm của lễ chuộc tội;'),
(3934, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 83, 'OT', 'Về lễ hy sinh hóa bình an: hai con bò, năm con chiên đực, năm con dê đực, và năm con chiên con một tuổi. Đó là lễ vật của A-hi-ra, con trai của Ê-nan.'),
(3935, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 84, 'OT', 'Đây là lễ khánh thành bàn thờ trong ngày xức dầu bàn thờ, do các quan trưởng Y-sơ-ra-ên dâng: mười hai đĩa bạc, mười hai bình rót bạc, mười hai chén vàng.'),
(3936, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 85, 'OT', 'Mỗi đĩa bạc nặng một trăm ba mươi siếc-lơ; mỗi chậu bạc nặng bảy mươi siếc-lơ. Tất cả số bạc của các đồ dùng này là hai ngàn bốn trăm siếc-lơ, theo đơn vị siếc-lơ của nơi thánh.'),
(3937, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 86, 'OT', 'Mười hai cái thìa vàng đầy thuốc thơm, mỗi cái thìa mười siếc-lơ theo siếc-lơ của nơi thánh; toàn bộ vàng của các cái thìa nặng hai trăm mười siếc-lơ.'),
(3938, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 87, 'OT', 'Tất cả số bò về của lễ thiêu là mười hai con bò đực, mười hai con chiên đực, mười hai con chiên con một tuổi cùng của lễ chay kèm theo, và mười hai con dê đực dùng về của lễ chuộc tội.'),
(3939, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 88, 'OT', 'Tất cả bò đực về của lễ thù ân là hai mươi bốn con; chiên đực sáu mươi con; dê đực sáu mươi con; chiên con giáp năm sáu mươi con. Đó là lễ khánh thành bàn thờ, sau khi đã xức dầu cho nó.'),
(3940, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 7, 89, 'OT', 'Khi Môi-se vào hội mạc để nói chuyện với Đức Giê-hô-va, thì nghe tiếng nói cùng mình từ trên nắp thi ân, là nơi trên hòm bảng chứng, ở giữa hai chê-ru-bin; Đức Giê-hô-va phán dạy người.'),
(3941, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 8, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3942, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 8, 2, 'OT', 'Hãy nói cùng A-rôn và bảo người rằng: "Khi ngươi thắp các ngọn đèn, bảy ngọn đèn phải chiếu về phía trước mặt chân đèn."'),
(3943, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 8, 3, 'OT', 'A-rôn đã làm như vậy: đặt các ngọn đèn trên phía trước chân đèn, như Đức Giê-hô-va đã truyền cho Môi-se.'),
(3944, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 8, 4, 'OT', 'Chân đèn nầy được làm bằng vàng ròng, từ đế đến hoa của nó đều đúc liền một khối; theo hình dạng mà Đức Giê-hô-va đã chỉ cho Môi-se xem, thì người ta làm chân đèn như vậy.'),
(3945, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 8, 5, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3946, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 8, 6, 'OT', 'Hãy đem người Lê-vi ra khỏi giữa con cái Y-sơ-ra-ên và làm cho họ được sạch.'),
(3947, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 8, 7, 'OT', 'Nầy là điều ngươi phải làm cho họ để làm cho họ được sạch: ngươi phải rảy nước chuộc tội trên họ, họ phải dùng dao cạo cạo toàn thân mình, giặt quần áo mình và làm cho mình được sạch.'),
(3948, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 8, 8, 'OT', 'Họ phải lấy một con bò đực tơ cùng lễ vật chay là bột lọc trộn dầu; ngươi phải lấy một con bò đực tơ thứ hai để làm của lễ chuộc tội.'),
(3949, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 8, 9, 'OT', 'Hãy dẫn những người Lê-vi đến gần trước hội mạc, và nhóm toàn thể hội chúng các con cái Y-sơ-ra-ên.'),
(3950, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 8, 10, 'OT', 'Hãy dẫn người Lê-vi đến gần trước mặt Đức Giê-hô-va, và dân Y-sơ-ra-ên sẽ đặt tay mình trên người Lê-vi.'),
(3951, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 8, 11, 'OT', 'A-rôn sẽ dâng người Lê-vi làm lễ vật do phần dân Y-sơ-ra-ên mà đưa qua đưa lại trước mặt Đức Giê-hô-va, và họ sẽ phục vụ công việc của Đức Giê-hô-va.'),
(3952, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 8, 12, 'OT', 'Người Lê-vi sẽ đặt tay mình trên đầu những con bò đực; ngươi phải dâng con nầy làm của lễ chuộc tội và con kia làm của lễ thiêu cho Đức Giê-hô-va, để làm lễ chuộc tội cho người Lê-vi.'),
(3953, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 8, 13, 'OT', 'Ngươi phải đặt những người Lê-vi đứng trước mặt A-rôn và trước mặt các con trai người, rồi dâng họ làm lễ vật đưa qua đưa lại cho Đức Giê-hô-va.'),
(3954, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 8, 14, 'OT', 'Ngươi sẽ biệt riêng người Lê-vi ra khỏi giữa các con trai Y-sơ-ra-ên, và người Lê-vi sẽ thuộc về ta.'),
(3955, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 8, 15, 'OT', 'Sau đó, người Lê-vi sẽ đến để làm việc tại hội mạc. Ngươi phải làm cho họ được sạch và dâng họ làm lễ vật đưa qua đưa lại.'),
(3956, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 8, 16, 'OT', 'Vì người Lê-vi đã được trao trọn cho Ta giữa con cái Y-sơ-ra-ên; thay cho mọi con đầu lòng mở tử cung, mọi con đầu lòng trong con cái Y-sơ-ra-ên, Ta đã lấy họ về cho Ta.'),
(3957, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 8, 17, 'OT', 'Vì ta là chủ của mọi con đầu lòng trong con cái Y-sơ-ra-ên, bất luận người hay vật; trong ngày ta đánh chết mọi con đầu lòng trong đất Ê-dip-tô, ta đã biệt riêng chúng nó ra cho ta.'),
(3958, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 8, 18, 'OT', 'Ta đã chọn lấy người Lê-vi thế cho mọi con đầu lòng trong các con trai của Y-sơ-ra-ên.'),
(3959, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 8, 19, 'OT', 'Ta đã ban những người Lê-vi làm người thuộc về A-rôn và các con trai người từ giữa các con trai Y-sơ-ra-ên, để thi hành công việc thay mặt các con trai Y-sơ-ra-ên trong hội mạc và để làm lễ chuộc tội cho các con trai Y-sơ-ra-ên, hầu cho khi các con trai Y-sơ-ra-ên đến gần nơi thánh thì không xảy ra tai họa nào giữa các con trai Y-sơ-ra-ên.'),
(3960, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 8, 20, 'OT', 'Môi-se, A-rôn và cả hội chúng Y-sơ-ra-ên đã làm cho người Lê-vi như vậy, theo mọi điều Đức Giê-hô-va đã truyền cho Môi-se về người Lê-vi; chính như vậy dân Y-sơ-ra-ên đã làm cho họ.'),
(3961, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 8, 21, 'OT', 'Người Lê-vi làm cho mình được sạch khỏi tội và giặt áo xống mình; rồi A-rôn dâng họ làm lễ đưa qua đưa lại trước mặt Đức Giê-hô-va, và A-rôn làm lễ chuộc tội cho họ để làm cho họ được sạch.'),
(3962, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 8, 22, 'OT', 'Sau đó, người Lê-vi đến để làm công việc phục vụ của họ trong hội mạc, trước mặt A-rôn và trước mặt các con trai ông, y như Đức Giê-hô-va đã truyền cho Môi-se về người Lê-vi; người ta đã làm cho họ như vậy.'),
(3963, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 8, 23, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3964, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 8, 24, 'OT', 'Đây là điều dành cho người Lê-vi: Từ hai mươi lăm tuổi trở lên, người ấy phải đến phục vụ trong công việc của hội mạc.'),
(3965, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 8, 25, 'OT', 'Từ năm mươi tuổi trở lên, người ấy phải thôi làm việc và không được phục vụ nữa.'),
(3966, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 8, 26, 'OT', 'người phải phục vụ anh em mình trong hội mạc để giữ những điều đã giao phó, nhưng không được làm công việc. Ngươi phải làm như vậy cho người Lê-vi trong các nhiệm vụ của họ.'),
(3967, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 9, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se trong đồng vắng Si-na-i, tháng đầu năm thứ hai sau khi dân Y-sơ-ra-ên ra khỏi xứ Ê-díp-tô, rằng:'),
(3968, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 9, 2, 'OT', 'Các con trai Y-sơ-ra-ên phải giữ lễ Vượt-qua theo kỳ định của nó.'),
(3969, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 9, 3, 'OT', 'Vào ngày mười bốn tháng này, giữa hai buổi chiều tối, các ngươi phải làm lễ đó đúng theo kỳ lễ của nó; theo mọi mạng lịnh và mọi luật lệ của nó, các ngươi phải làm lễ đó.'),
(3970, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 9, 4, 'OT', 'Môi-se nói cùng con cái Y-sơ-ra-ên để giữ lễ Vượt-qua.'),
(3971, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 9, 5, 'OT', 'Dân Y-sơ-ra-ên giữ lễ Vượt-qua vào ngày mười bốn tháng đầu, vào buổi chiều tối, tại đồng vắng Si-na-i; theo đúng mọi điều Đức Giê-hô-va đã truyền cho Môi-se, thì con cái Y-sơ-ra-ên làm như vậy.'),
(3972, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 9, 6, 'OT', 'Có mấy người bị ô uế vì xác chết người, nên không thể giữ lễ Vượt-qua trong ngày đó, bèn đến cùng Môi-se và A-rôn trong ngày ấy.'),
(3973, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 9, 7, 'OT', 'Các người ấy thưa cùng Môi-se rằng: Chúng tôi bị ô uế vì xác chết người; sao chúng tôi bị loại ra khỏi việc dâng lễ vật cho Đức Giê-hô-va đúng kỳ định giữa vòng dân Y-sơ-ra-ên?'),
(3974, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 9, 8, 'OT', 'Môi-se nói với họ: "Hãy đứng đó, để ta nghe xem Đức Giê-hô-va sẽ truyền cho các ngươi điều gì."'),
(3975, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 9, 9, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3976, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 9, 10, 'OT', 'Hãy nói cùng con cái Y-sơ-ra-ên rằng: Một người nào, hoặc trong các ngươi hoặc trong các đời sau các ngươi, bị ô uế vì xác chết, hoặc ở đường xa, thì phải giữ lễ Vượt-qua cho Đức Giê-hô-va.'),
(3977, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 9, 11, 'OT', 'Vào tháng thứ hai, ngày mười bốn giữa hai buổi chiều tối, họ phải làm lễ đó; phải ăn nó với bánh không men và rau đắng.'),
(3978, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 9, 12, 'OT', 'Chớ để thịt còn lại đến sáng, và đừng bẻ gãy một cái xương nào; phải làm theo mọi luật lệ về lễ Vượt-qua.'),
(3979, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 9, 13, 'OT', 'Nhưng người nào tinh sạch mà không đi đường, nếu kiêng không giữ lễ Vượt-qua, thì linh hồn người ấy sẽ bị truất khỏi dân sự mình; vì người ấy đã không dâng của lễ Đức Giê-hô-va trong kỳ định cho nó, nên người ấy sẽ mang lấy tội mình.'),
(3980, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 9, 14, 'OT', 'Khi một khách ngoại bang kiều ngụ giữa các ngươi mà làm lễ Vượt-qua cho Đức Giê-hô-va, thì phải làm theo luật lệ và mạng lệnh về lễ Vượt-qua. Một luật lệ như nhau sẽ áp dụng cho các ngươi, cho khách ngoại bang, và cho người bản xứ.'),
(3981, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 9, 15, 'OT', 'Vào ngày dựng đền tạm, mây bao phủ đền tạm và trại chứng cớ; và đến chiều tối, có vẻ như lửa phủ trên đền tạm cho đến sáng mai.'),
(3982, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 9, 16, 'OT', 'Cũng sẽ như vậy luôn luôn: đám mây của Đức Giê-hô-va che phủ nó, và ban đêm có vẻ như lửa.'),
(3983, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 9, 17, 'OT', 'Mỗi khi đám mây rời khỏi trại, thì con cái Y-sơ-ra-ên sẽ ra đi; và tại nơi nào đám mây dừng lại, thì con cái Y-sơ-ra-ên sẽ dựng trại tại đó.'),
(3984, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 9, 18, 'OT', 'Theo mạng Đức Giê-hô-va, con cái Y-sơ-ra-ên ra đi; theo mạng Đức Giê-hô-va, họ đóng trại. Trọn những ngày mây nương trên đền tạm, họ đóng trại.'),
(3985, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 9, 19, 'OT', 'Khi đám mây ở lâu ngày trên đền tạm, thì con cái Y-sơ-ra-ên tuân giữ sự chỉ dẫn của Đức Giê-hô-va và không đi đâu.'),
(3986, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 9, 20, 'OT', 'Và có khi mây ở trên đền tạm vài ngày; theo lệnh Đức Giê-hô-va, người ta đóng trại, và theo lệnh Đức Giê-hô-va, người ta khởi hành.'),
(3987, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 9, 21, 'OT', 'Có khi đám mây ở lại từ chiều tối cho đến sáng mai; và khi đám mây cất lên vào buổi sáng, thì họ khởi hành. Hoặc ngày và đêm, nếu đám mây cất lên, thì họ khởi hành.'),
(3988, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 9, 22, 'OT', 'Hoặc hai ngày, hoặc một tháng, hoặc nhiều ngày, khi mây ở lâu trên nơi thánh để nương náu, thì con cái Y-sơ-ra-ên sẽ ở trại, không đi đâu; và khi mây cất lên, thì họ sẽ ra đi.'),
(3989, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 9, 23, 'OT', 'Dân Y-sơ-ra-ên hạ trại và ra đi tùy theo mạng Đức Giê-hô-va; họ giữ mạng lệnh của Đức Giê-hô-va theo mạng Đức Giê-hô-va mà Môi-se truyền.'),
(3990, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(3991, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 2, 'OT', 'Hãy làm cho mình hai chiếc kèn bằng bạc, đúc nguyên khối, để dùng cho ngươi gọi hội chúng họp lại và ra lệnh cho các trại quân khởi hành.'),
(3992, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 3, 'OT', 'Khi các ngươi thổi vào những chiếc kèn đó, thì toàn thể hội chúng sẽ nhóm lại cùng ngươi tại cửa Lều Hẹn.'),
(3993, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 4, 'OT', 'Nếu chỉ thổi một tiếng, thì các quan trưởng, các đầu mục ngàn người của Y-sơ-ra-ên, sẽ nhóm lại cùng ngươi.'),
(3994, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 5, 'OT', 'Khi các ngươi thổi tiếng báo động, thì các trại quân đóng về phía đông phải khởi hành.'),
(3995, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 6, 'OT', 'Khi các ngươi thổi tiếng kèn báo động lần thứ hai, thì các trại quân đóng về hướng nam phải khởi hành; chính lúc các trại quân khởi hành, người ta sẽ thổi tiếng kèn báo động.'),
(3996, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 7, 'OT', 'Khi triệu tập hội chúng, các ngươi phải thổi loa, nhưng không được thổi vang.'),
(3997, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 8, 'OT', 'Các con trai của A-rôn, là những thầy tế lễ, sẽ thổi những chiếc tù và. Đó sẽ là một điều luật đời đời cho các ngươi, theo các đời các ngươi.'),
(3998, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 9, 'OT', 'Khi các ngươi bị kẻ thù nghịch trong xứ mình xâm hại mà phải ra chiến trận, thì phải thổi tiếng kèn; các ngươi sẽ được nhớ đến trước mặt Đức Giê-hô-va, Đức Chúa Trời của các ngươi, và các ngươi sẽ được giải cứu khỏi kẻ thù nghịch mình.'),
(3999, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 10, 'OT', 'Vào ngày lễ vui mừng của các ngươi, trong các ngày lễ hội và đầu các tháng các ngươi, hãy thổi kèn trên các của lễ thiêu và các của lễ thù ân của các ngươi; và điều đó sẽ là một kỷ niệm cho các ngươi trước mặt Đức Chúa Trời các ngươi. Ta là Đức Giê-hô-va, Đức Chúa Trời của các ngươi.'),
(4000, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 11, 'OT', 'Và xảy ra vào ngày hai mươi tháng hai, năm thứ hai, mây liền nhấc lên khỏi đền tạm chứng cớ.'),
(4001, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 12, 'OT', 'Dân Y-sơ-ra-ên khởi hành theo các trạm của mình ra khỏi đồng vắng Si-na-i, và trụ mây dừng lại tại đồng vắng Pha-ran.'),
(4002, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 13, 'OT', 'Dân Y-sơ-ra-ên ra đi lần thứ nhất, theo mạng của Đức Giê-hô-va do tay Môi-se truyền.'),
(4003, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 14, 'OT', 'Ngọn cờ của trại quân con trai Giu-đa, tùy theo các đội ngũ mình, đi trước; và trên đội quân mình là Na-ha-sôn, con trai A-mi-na-đáp.'),
(4004, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 15, 'OT', 'Trên đạo quân của chi phái Y-sa-ca là Na-tha-na-ên, con trai Xu-a.'),
(4005, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 16, 'OT', 'Ê-li-áp, con trai của Hê-lôn, chỉ huy đạo quân chi phái Sa-bu-lôn.'),
(4006, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 17, 'OT', 'Đoạn đền tạm được tháo dỡ, thì con cháu Ghẹt-sôn và con cháu Mê-ra-ri, kẻ khiêng đền tạm, ra đi.'),
(4007, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 18, 'OT', 'Vậy, ngọn cờ của trại quân Ru-bên ra đi theo các đạo quân mình; và người đứng đầu đạo quân người là Ê-lít-xu, con trai Sê-đêu.'),
(4008, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 19, 'OT', 'Về đạo quân của chi phái Si-mê-ôn, thì Sê-lu-mi-ên, con trai Xu-ri-ha-đai, chỉ huy đạo quân ấy.'),
(4009, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 20, 'OT', 'Và trên đạo quân của chi phái con cái Gát là Ê-li-sáp, con trai Đê-u-ên.'),
(4010, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 21, 'OT', 'Các người Kê-hát, kẻ khiêng các vật thuộc nơi thánh, sẽ ra đi; và người ta sẽ dựng đền tạm lên, đợi cho họ đến.'),
(4011, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 22, 'OT', 'Vậy, ngọn cờ của trại quân con cháu Eùp-ra-im ra đi, tùy theo đội ngũ của họ; và người chỉ huy đội quân ấy là Ê-li-sa-ma, con trai A-mi-hút.'),
(4012, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 23, 'OT', 'Ga-ma-li-ên, con trai của Phê-đát-su, chỉ huy đạo quân của chi phái Ma-na-se.'),
(4013, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 24, 'OT', 'A-bi-đan, con trai của Ghi-đeo-ni, chỉ huy đạo quân của chi phái Bên-gia-min.'),
(4014, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 25, 'OT', 'Và ngọn cờ của trại quân con cái Đan ra đi, làm người thu nhặt sau cùng cho mọi trại quân theo các đạo quân của họ; và người đứng đầu đạo quân của họ là A-hi-ê-xe, con trai A-mi-sa-đai.'),
(4015, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 26, 'OT', 'Và người chỉ huy đạo quân của chi phái A-se là Pha-ghi-ên, con trai Oùc-ran.'),
(4016, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 27, 'OT', 'A-hi-ra, con trai của Ê-nan, chỉ huy đạo quân của chi phái Nép-ta-li.'),
(4017, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 28, 'OT', 'Đó là các cuộc hành trình của con cái Y-sơ-ra-ên theo các đạo quân của họ; và họ đã ra đi.'),
(4018, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 29, 'OT', 'Môi-se nói cùng Hô-báp, con trai Rê-u-ên người Ma-đi-an, là cha vợ mình: Chúng tôi đang đi đến nơi mà Đức Giê-hô-va đã phán rằng: Ta sẽ ban nơi ấy cho các ngươi; hãy đi cùng chúng tôi, và chúng tôi sẽ đối xử tốt với anh, vì Đức Giê-hô-va đã phán điều lành về Y-sơ-ra-ên.'),
(4019, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 30, 'OT', 'Hô-báp nói với người rằng: Tôi sẽ không đi; nhưng tôi sẽ đi về đất nước tôi, và về nơi sinh quán tôi.'),
(4020, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 31, 'OT', 'Môi-se nói: Xin anh chớ từ bỏ chúng tôi, vì anh biết những nơi chúng tôi có thể đóng trại trong đồng vắng, và anh sẽ là mắt cho chúng tôi.'),
(4021, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 32, 'OT', 'Nếu ngươi đi cùng chúng ta, thì điều lành mà Đức Giê-hô-va sẽ làm cho chúng ta, chúng ta cũng sẽ làm cho ngươi.'),
(4022, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 33, 'OT', 'Dân Y-sơ-ra-ên khởi hành từ núi Đức Giê-hô-va, đi đường ba ngày; và hòm giao ước của Đức Giê-hô-va đi trước mặt họ, đi đường ba ngày, để tìm cho họ một nơi dừng nghỉ.'),
(4023, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 34, 'OT', 'Và một đám mây của Đức Giê-hô-va ở trên dân Y-sơ-ra-ên ban ngày, khi họ khởi hành khỏi trại quân.'),
(4024, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 35, 'OT', 'Khi rạp hòm đi, Môi-se nói: "Lên đường, Đức Giê-hô-va, để các kẻ thù nghịch Ngài bị tan tác, và những kẻ ghét Ngài chạy trốn khỏi trước mặt Ngài!"'),
(4025, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 10, 36, 'OT', 'Khi rỗi, người nói: Lạy Đức Giê-hô-va, xin trở lại cùng hàng vạn ngàn ngàn người Y-sơ-ra-ên!'),
(4026, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 1, 'OT', 'Dân sự bắt đầu than vãn điều xấu trước mặt Đức Giê-hô-va; Đức Giê-hô-va nghe thấy và cơn thịnh nộ của Ngài nổi lên, lửa của Đức Giê-hô-va bùng lên giữa dân sự, thiêu đốt những phần rìa trại quân.'),
(4027, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 2, 'OT', 'Dân sự kêu khóc cùng Môi-se; Môi-se cầu nguyện cùng Đức Giê-hô-va, và lửa liền tắt.'),
(4028, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 3, 'OT', 'Người ta đặt tên nơi ấy là Tha-bê-ra, vì lửa của Đức Giê-hô-va đã bùng lên giữa họ.'),
(4029, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 4, 'OT', 'Bọn người ngoại đạo ở giữa dân Y-sơ-ra-ên sanh lòng thèm muốn; đến nỗi con cái Y-sơ-ra-ên lại khóc lóc mà nói: Ai sẽ cho chúng tôi ăn thịt?'),
(4030, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 5, 'OT', 'Chúng tôi nhớ đến con cá chúng tôi đã ăn ở Ai-cập, không mất tiền, cùng các thứ dưa chuột, dưa hấu, hành lá, hành củ và tỏi.'),
(4031, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 6, 'OT', 'Bây giờ linh hồn chúng tôi khô héo; chẳng còn gì cả, chỉ thấy ma-na trước mắt mà thôi.'),
(4032, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 7, 'OT', 'Ma-na giống như hột cây thì là, và màu sắc nó như ngọc trai.'),
(4033, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 8, 'OT', 'Dân sự đi rải ra, hốt lấy, rồi nghiền bằng cối xay hay giã trong cối giã, nấu trong nồi và làm thành bánh; mùi vị của nó giống như mùi vị của bánh chiên ngập dầu.'),
(4034, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 9, 'OT', 'Khi sương xuống trên trại quân vào ban đêm, thì ma-na cũng xuống trên đó.'),
(4035, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 10, 'OT', 'Môi-se nghe dân chúng khóc, mỗi người tại gia đình mình, mỗi người ở nơi cửa lều mình; và cơn thịnh nộ của Đức Giê-hô-va nổi lên rất dữ dội, và trong mắt Môi-se thì điều đó là điều ác.'),
(4036, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 11, 'OT', 'Môi-se thưa cùng Đức Giê-hô-va: "Tại sao Ngài làm điều ác cho tôi tớ Ngài, và tại sao tôi không được ơn trước mặt Ngài, mà Ngài lại đặt gánh nặng của cả dân sự nầy trên tôi?"'),
(4037, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 12, 'OT', 'Tôi đã mang thai toàn thể dân này sao? Tôi đã sinh đẻ họ sao, mà Ngài lại bảo tôi: Hãy bồng họ trong lòng ngươi, như người vú nuôi bồng đứa trẻ đang bú, cho đến đất mà Ngài đã thề hứa ban cho tổ tiên họ?'),
(4038, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 13, 'OT', 'Tôi sẽ lấy thịt ở đâu để cấp cho cả dân này đây? Vì họ khóc lóc cùng tôi rằng: Hãy cho chúng tôi thịt để ăn.'),
(4039, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 14, 'OT', 'Tôi không thể một mình gánh chịu toàn thể dân này, vì nó quá nặng đối với tôi.'),
(4040, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 15, 'OT', 'Nếu Ngài cứ đối xử với tôi như thế nầy, thì xin hãy giết tôi đi, nếu tôi đã tìm được ơn trước mặt Ngài, để tôi không phải thấy sự khốn khổ của tôi!'),
(4041, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 16, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Hãy nhóm cho ta bảy mươi người trong các trưởng lão Y-sơ-ra-ên, là những người mà ngươi biết họ là các trưởng lão và các quan chức của dân sự; ngươi hãy dẫn họ đến nơi hội mạc, và họ sẽ đứng đó cùng với ngươi.'),
(4042, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 17, 'OT', 'Ta sẽ ngự xuống và phán cùng ngươi tại đó; Ta sẽ lấy phần thần khí đang ở trên ngươi mà đặt trên họ, để họ cùng mang gánh nặng của dân sự với ngươi, và ngươi sẽ không phải mang một mình.'),
(4043, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 18, 'OT', 'Ngươi phải nói cùng dân sự rằng: Hãy dọn mình ra thánh cho ngày mai, và các ngươi sẽ ăn thịt; vì các ngươi đã khóc đến tai Đức Giê-hô-va mà rằng: Ai sẽ cho chúng ta ăn thịt, vì chúng ta lấy làm sung sướng tại xứ Ê-díp-tô? Bởi cớ đó, Đức Giê-hô-va sẽ ban thịt cho các ngươi, và các ngươi sẽ ăn.'),
(4044, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 19, 'OT', 'Các ngươi sẽ không ăn thịt một ngày, cũng không hai ngày, không năm ngày, không mười ngày, không hai mươi ngày,'),
(4045, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 20, 'OT', 'trọn một tháng cho đến khi thịt trào ra khỏi lỗ mũi các ngươi và trở nên điều ghê tởm cho các ngươi, vì các ngươi đã khinh bỉ Đức Giê-hô-va là Đấng ở giữa các ngươi và khóc lóc trước mặt Ngài mà nói: "Tại sao chúng tôi đã ra khỏi Ai Cập?"'),
(4046, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 21, 'OT', 'Môi-se thưa rằng: Sáu trăm ngàn người đàn ông là dân sự mà tôi đang ở giữa họ, mà Ngài lại phán: Ta sẽ ban thịt cho chúng nó, và chúng nó sẽ ăn trong trọn một tháng.'),
(4047, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 22, 'OT', 'Sẽ giết chiên và bò cho họ, và có đủ cho họ chăng? Hay sẽ bắt các loài cá trong biển cho đầy đủ cho họ chăng?'),
(4048, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 23, 'OT', 'Đức Giê-hô-va phán cùng Môi-se: Tay của Đức Giê-hô-va há bị ngắn sao? Hiện nay ngươi sẽ thấy lời Ta phán cùng ngươi có xảy đến hay không.'),
(4049, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 24, 'OT', 'Môi-se ra đi và nói với dân sự các lời của Đức Giê-hô-va, rồi nhóm lại bảy mươi người trong các trưởng lão của dân sự, và đặt họ đứng chung quanh trại.'),
(4050, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 25, 'OT', 'Đức Giê-hô-va ngự xuống trong đám mây, phán cùng Môi-se; Ngài lấy bớt Thần trên người và đặt trên bảy mươi người trưởng lão. Khi Thần đậu trên họ, thì họ nói tiên tri, nhưng không tiếp tục nữa.'),
(4051, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 26, 'OT', 'Nhưng có hai người ở lại trong trại; tên một người là Eân-đát, tên người kia là Mê-đát. Thần đã ngự trên hai người ấy, và họ thuộc những người đã được ghi tên, nhưng không ra khỏi trại; họ nói tiên tri trong trại.'),
(4052, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 27, 'OT', 'Một đứa trẻ chạy đi thuật lại cho Môi-se rằng: Eân-đát và Mê-đát đang nói tiên tri trong trại quân.'),
(4053, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 28, 'OT', 'Giô-suê, con trai của Nun, người hầu việc Môi-se, thưa rằng: Lạy chúa tôi là Môi-se, xin hãy ngăn cấm chúng nó!'),
(4054, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 29, 'OT', 'Môi-se nói với người ấy: "Ngươi ganh tị cho ta sao? Ước gì toàn dân của Đức Giê-hô-va đều là các nhà tiên tri, và ước gì Đức Giê-hô-va ban Thần Ngài trên họ!"'),
(4055, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 30, 'OT', 'Môi-se và các bậc trưởng lão của Y-sơ-ra-ên liền trở về trại.'),
(4056, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 31, 'OT', 'Đức Giê-hô-va khiến một luồng gió thổi từ Đức Giê-hô-va đi, và Người làm cho những con chim cút bay đến từ biển, rồi ném xuống trên trại quân và chung quanh trại quân, trải dài chừng một ngày đường về phía này, và chừng một ngày đường về phía kia, phủ khắp mặt đất chừng hai thước.'),
(4057, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 32, 'OT', 'Dân sự đứng dậy, lượm chim cút suốt cả ngày hôm ấy, cả đêm ấy và cả ngày hôm sau; người lượm ít nhất cũng được mười ô-me; họ trải ra khắp xung quanh trại quân.'),
(4058, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 33, 'OT', 'Thịt còn nơi răng họ, chưa kịp nuốt xong, thì cơn thịnh nộ của Đức Giê-hô-va nổi lên cùng dân sự, và Đức Giê-hô-va giáng cho dân sự một tai họa nặng nề rất lớn.'),
(4059, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 34, 'OT', 'Người ta gọi tên chỗ đó là Kíp-rốt Ha-tha-va, vì tại đó đã chôn những người thèm muốn.'),
(4060, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 11, 35, 'OT', 'Dân sự từ Kíp-rốt Ha-tha-va đi đến Hát-sê-rốt, rồi ở lại tại Hát-sê-rốt.'),
(4061, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 12, 1, 'OT', 'Mi-ri-am và A-rôn nói nghịch Môi-se về người vợ người Cúp-sít mà ông đã lấy; vì ông đã lấy một người vợ người Cúp-sít.'),
(4062, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 12, 2, 'OT', 'Hai người nói: "Phải chăng Đức Giê-hô-va chỉ phán cùng Môi-se mà thôi? Ngài há chẳng phải cũng đã phán cùng chúng ta sao?" Và Đức Giê-hô-va nghe điều đó.'),
(4063, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 12, 3, 'OT', 'Môi-se là người rất khiêm nhường, hơn mọi người trên mặt đất.'),
(4064, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 12, 4, 'OT', 'Đức Giê-hô-va phán cách thình lình cùng Môi-se, A-rôn và Mi-ri-am: "Cả ba hãy ra đến nơi hội mạc." Cả ba người liền ra đi.'),
(4065, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 12, 5, 'OT', 'Đức Giê-hô-va ngự xuống trong trụ mây, rồi đứng tại cửa hội mạc, và gọi A-rôn và Mi-ri-am; cả hai người ra đi.'),
(4066, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 12, 6, 'OT', 'Đức Giê-hô-va phán: Hãy nghe rõ lời ta. Nếu trong các ngươi có một tiên tri của Đức Giê-hô-va, ta sẽ cho người ấy thấy sự hiện thấy, và ta sẽ phán cùng người trong cơn chiêm bao.'),
(4067, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 12, 7, 'OT', 'Tôi tớ Môi-se ta không như vậy, người trung tín trong cả nhà ta.'),
(4068, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 12, 8, 'OT', 'Ta phán cùng người ấy mặt đối mặt, bằng cách rõ ràng, không dùng lời đố, và người ấy thấy hình dạng của Đức Giê-hô-va. Vậy sao các ngươi không sợ mà dám nói hành kẻ tôi tớ ta là Môi-se?'),
(4069, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 12, 9, 'OT', 'Cơn thạnh nộ của Đức Giê-hô-va nổi lên cùng hai người, rồi Ngài đi khỏi.'),
(4070, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 12, 10, 'OT', 'Và đám mây rút khỏi trên trại tạm, thì kìa, Mi-ri-am bị phong cùi trắng như tuyết. A-rôn quay về phía Mi-ri-am và thấy người đã bị phong cùi.'),
(4071, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 12, 11, 'OT', 'A-rôn nói cùng Môi-se: "Ôi, thưa chúa tôi, xin đừng để tội lỗi mà chúng tôi đã phạm và đã sai lầm chất trên chúng tôi."'),
(4072, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 12, 12, 'OT', 'Xin đừng để nàng như một người chết, vừa ra khỏi lòng mẹ mà đã phân nửa thân thể bị ăn mòn.'),
(4073, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 12, 13, 'OT', 'Môi-se kêu lên cùng Đức Giê-hô-va rằng: Lạy Đức Chúa Trời, xin chữa lành cho nàng, xin chữa lành đi.'),
(4074, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 12, 14, 'OT', 'Đức Giê-hô-va phán cùng Môi-se: Nếu cha nàng nhổ trên mặt nàng, há nàng chẳng phải hổ thẹn bảy ngày sao? Nàng phải bị giam riêng ngoài trại quân bảy ngày, rồi sau mới được nhận lại.'),
(4075, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 12, 15, 'OT', 'Mi-ri-am bị giam riêng ngoài trại quân bảy ngày, và dân sự không khởi hành cho đến khi Mi-ri-am được nhận trở lại.'),
(4076, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 12, 16, 'OT', 'Sau đó, dân sự ra đi từ Hát-sê-rốt và đóng trại trong đồng vắng Pha-ran.'),
(4077, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(4078, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 2, 'OT', 'Hãy sai những người đi do thám xứ Ca-na-an mà Ta sẽ ban cho dân Y-sơ-ra-ên; mỗi một chi phái tổ tiên, các ngươi phải sai một người, mỗi người là quan trưởng trong các chi phái ấy.'),
(4079, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 3, 'OT', 'Môi-se sai các người ấy đi từ đồng vắng Pha-ran, theo lệnh của Đức Giê-hô-va; tất cả họ đều là những người lãnh đạo của dân Y-sơ-ra-ên.'),
(4080, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 4, 'OT', 'Đây là tên của các người ấy: về chi phái Ru-bên, Sam-mua, con trai Xa-cu;'),
(4081, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 5, 'OT', 'về chi phái Si-mê-ôn, Sa-phát, con trai của Hô-ri;'),
(4082, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 6, 'OT', 'về chi phái Giu-đa, Ca-lép, con trai của Giê-phu-nê;'),
(4083, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 7, 'OT', 'Về chi phái Y-sa-ca, là Di-ganh, con trai của Giô-sép.'),
(4084, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 8, 'OT', 'Về chi phái Eùp-ra-im, Hô-sê con trai của Nun;'),
(4085, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 9, 'OT', 'Về chi phái Bên-gia-min, Phan-thi con trai của Ra-phu;'),
(4086, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 10, 'OT', 'Về chi phái Sa-bu-lôn, Gát-đi-ên, con trai của Sô-đi;'),
(4087, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 11, 'OT', 'về chi phái Giô-sép, về chi phái Ma-na-se, Ga-đi, con trai của Su-si;'),
(4088, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 12, 'OT', 'về chi phái Đan, A-mi-ên, con trai của Ghê-ma-li;'),
(4089, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 13, 'OT', 'Về chi phái A-se, Sê-thu, con trai của Mi-ca-ên;'),
(4090, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 14, 'OT', 'Về chi phái Nép-ta-li, Nách-bi con trai của Vấp-si;'),
(4091, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 15, 'OT', 'Về chi phái Gát, Gu-ên, con trai của Ma-ki.'),
(4092, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 16, 'OT', 'Đó là những tên người mà Môi-se sai đi do thám xứ. Và Môi-se đặt tên cho Hô-sê, con trai của Nun, là Giô-suê.'),
(4093, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 17, 'OT', 'Môi-se sai họ đi do thám xứ Ca-na-an, và nói với họ rằng: Các ngươi hãy lên đây, đi về miền Nam, và lên miền núi.'),
(4094, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 18, 'OT', 'Hãy xem xứ đó ra sao, và dân cư ngụ trên đó thế nào: họ mạnh hay yếu, ít hay đông.'),
(4095, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 19, 'OT', 'Xứ dân ấy ở là thế nào, đất tốt hay xấu? Các thành mà dân ấy ở là những nơi đóng trại hay là thành có vách thành vững chắc?'),
(4096, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 20, 'OT', 'Hãy xem đất ấy màu mỡ hay cằn cỗi, có cây cối hay không, hãy vững lòng và lấy ít trái của xứ ấy; lúc ấy là mùa nho đầu vụ.'),
(4097, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 21, 'OT', 'Vậy các người ấy đi lên do thám xứ, từ đồng vắng Xin cho đến Rê-hốp, đi về Ha-mát.'),
(4098, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 22, 'OT', 'Họ đi lên miền Nam và đến thành Hếp-rôn; và tại đó có A-hi-man, Sê-sai và Tanh-mai, con cháu của A-nác. Thành Hếp-rôn được xây dựng bảy năm trước Xô-an của Ai Cập.'),
(4099, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 23, 'OT', 'Các người đi đến khe Eách-côn, cắt từ đó một nhành nho và một chùm nho duy nhất, rồi khiêng trên cây sào hai người mang, cùng những trái lựu và trái vả.'),
(4100, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 24, 'OT', 'Người ta gọi nơi ấy là khe Eách-côn, vì những chùm nho mà con cái Y-sơ-ra-ên đã cắt lấy từ đó.'),
(4101, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 25, 'OT', 'Họ trở về từ cuộc thám thính xứ, sau bốn mươi ngày.'),
(4102, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 26, 'OT', 'Họ đi và đến cùng Môi-se, A-rôn và toàn thể hội chúng Y-sơ-ra-ên tại đồng vắng Pha-ran, tại Ca-đe; họ trình lại cho hai người và toàn thể hội chúng biết, và cho xem trái của đất.'),
(4103, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 27, 'OT', 'Các người ấy thuật lại cho Môi-se và nói: Chúng tôi đã đi đến xứ mà người đã sai chúng tôi đến; ấy quả thật là xứ chảy sữa và mật, và nầy là hoa quả của nó.'),
(4104, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 28, 'OT', 'Nhưng dân sự ở trong xứ ấy rất mạnh, các thành thì kiên cố và cực kỳ lớn, và chúng tôi cũng đã thấy con cháu của A-nác ở đó.'),
(4105, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 29, 'OT', 'Dân A-ma-léc ở trong xứ miền Nam, dân Hê-tít, dân Giê-bu-sít và dân A-mô-rít ở trong núi, còn dân Ca-na-an thì ở gần biển và dọc theo bờ sông Giô-đanh.'),
(4106, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 30, 'OT', 'Ca-lép làm cho dân sự im lặng trước mặt Môi-se, rồi nói: Chúng ta hãy lên ngay và chiếm lấy xứ ấy, vì chúng ta hoàn toàn có thể làm được.'),
(4107, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 31, 'OT', 'Nhưng những người đi cùng với ông nói: Chúng ta không thể lên đánh dân ấy được, vì họ mạnh hơn chúng ta.'),
(4108, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 32, 'OT', 'Các người đó đã làm cho dân Y-sơ-ra-ên mất lòng tin về xứ mà họ đã đi do thám, mà rằng: Xứ mà chúng tôi đã đi qua để do thám là một xứ nuốt những người ở đó; và hết thảy những người chúng tôi đã thấy trong xứ đó đều là những người khổng lồ.'),
(4109, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 13, 33, 'OT', 'Chúng tôi thấy người khổng lồ, con cháu A-nác, thuộc về dòng người khổng lồ; chúng tôi thấy mình như cào cào trong mắt mình, và họ cũng thấy chúng tôi như vậy.'),
(4110, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 1, 'OT', 'Cả hội chúng cùng cất tiếng kêu lên; và dân sự khóc lóc trong đêm ấy.'),
(4111, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 2, 'OT', 'Hết thảy con cái Y-sơ-ra-ên lằm bằm cùng Môi-se và A-rôn; cả hội chúng nói cùng hai người rằng: Chớ chi chúng tôi đã chết trong xứ Ê-díp-tô, hay là đã chết trong đồng vắng nầy!'),
(4112, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 3, 'OT', 'Vì cớ nào Đức Giê-hô-va dẫn chúng tôi vào đất nầy để ngã bởi gươm? Vợ và con nhỏ chúng tôi sẽ trở thành mồi. Há chẳng tốt hơn cho chúng tôi trở về xứ Ê-díp-tô sao?'),
(4113, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 4, 'OT', 'Dân sự nói với nhau rằng: Hãy lập cho chúng ta một người lãnh đạo, rồi chúng ta sẽ trở về Ai Cập.'),
(4114, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 5, 'OT', 'Môi-se và A-rôn bèn phủ phục xuống trước mặt toàn thể hội chúng của dân Y-sơ-ra-ên.'),
(4115, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 6, 'OT', 'Giô-suê, con trai của Nun, và Ca-lép, con trai của Giê-phu-nê, hai người trong số những kẻ đi thám thính đất ấy, bèn xé áo quần mình.'),
(4116, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 7, 'OT', 'Hai người nói cùng cả hội chúng Y-sơ-ra-ên rằng: Xứ mà chúng tôi đã đi qua để do thám thật là một xứ rất tốt, rất tốt.'),
(4117, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 8, 'OT', 'Nếu Đức Giê-hô-va đẹp lòng chúng ta, thì Ngài sẽ đem chúng ta vào đất nầy và ban cho chúng ta, một đất chảy sữa và mật.'),
(4118, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 9, 'OT', 'Chỉ các ngươi, chớ dấy loạn cùng Đức Giê-hô-va; và các ngươi chớ sợ dân của xứ; vì họ sẽ là lương thực cho chúng ta; bóng che chở họ đã rời khỏi họ rồi; và Đức Giê-hô-va ở cùng chúng ta; các ngươi chớ sợ họ.'),
(4119, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 10, 'OT', 'Cả hội chúng nói muốn ném đá họ, thì sự vinh hiển của Đức Giê-hô-va hiện ra trong trại tạm trước mặt mọi con cái Y-sơ-ra-ên.'),
(4120, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 11, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Dân nầy khinh ta cho đến chừng nào, và không tin ta cho đến chừng nào, mặc dầu mọi dấu kỳ ta đã làm giữa họ?'),
(4121, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 12, 'OT', 'Ta sẽ dùng dịch lệ diệt dân nầy, và sẽ dẹp bỏ họ; nhưng Ta sẽ làm cho ngươi thành một dân lớn mạnh hơn họ.'),
(4122, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 13, 'OT', 'Môi-se thưa cùng Đức Giê-hô-va rằng: Dân Ê-díp-tô sẽ nghe biết rằng chính Ngài đã dùng quyền năng của Ngài đưa dân nầy ra khỏi giữa họ;'),
(4123, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 14, 'OT', 'và sẽ nói cho dân cư xứ này rằng: Đức Giê-hô-va, Ngài đã được thấy rõ ràng giữa dân này, Ngài hiện ra mặt đối mặt, mây của Ngài ở trên họ, và ban ngày Ngài đi trước họ trong một trụ mây, ban đêm trong một trụ lửa.'),
(4124, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 15, 'OT', 'Nếu Ngài giết dân này như một người, thì các dân tộc đã nghe danh Ngài sẽ nói rằng:'),
(4125, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 16, 'OT', 'Vì Đức Giê-hô-va không thể dẫn dân nầy vào đất mà Ngài đã thề hứa cho họ, nên Ngài giết họ trong đồng vắng.'),
(4126, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 17, 'OT', 'Bây giờ, xin hãy làm cho quyền năng của Đức Giê-hô-va được lớn lên, y như Ngài đã phán rằng:'),
(4127, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 18, 'OT', 'Đức Giê-hô-va chậm giận, đầy ơn sủng, tha thứ tội lỗi và sự bất tuân, nhưng không dung tha cho kẻ có tội; Ngài nhớ tội tổ phụ đến con cháu, đến đời thứ ba và đời thứ tư.'),
(4128, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 19, 'OT', 'Xin hãy tha thứ lỗi lầm của dân nầy theo sự lớn rộng của ân sủng Ngài, y như điều Ngài đã dung thứ cho dân nầy từ khi ra khỏi Ai-cập cho đến bây giờ.'),
(4129, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 20, 'OT', 'Đức Giê-hô-va phán: Ta đã tha theo lời ngươi.'),
(4130, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 21, 'OT', 'Nhưng ta chỉ lấy sự sống của ta mà thề rằng, sự vinh hiển của Đức Giê-hô-va sẽ đầy dẫy khắp đất!'),
(4131, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 22, 'OT', 'Vì mọi người đã thấy sự vinh hiển của Ta và các dấu kỳ Ta đã làm tại Ai Cập và nơi đồng vắng, mà đã thử Ta mười lần và không vâng theo tiếng Ta,'),
(4132, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 23, 'OT', 'chúng nó sẽ chẳng thấy đất mà ta đã thề hứa cho tổ phụ chúng nó; mọi kẻ khinh bỉ ta sẽ không thấy đất ấy.'),
(4133, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 24, 'OT', 'Nhưng kẻ tôi tớ ta là Ca-lép, vì có một tâm thần khác cùng người và người đã trung thành theo ta, thì ta sẽ đem người vào đất mà người đã đi đến, và dòng dõi người sẽ chiếm hữu đất ấy.'),
(4134, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 25, 'OT', 'Dân A-ma-léc và dân Ca-na-an đang ở trong trũng; ngày mai hãy đi lui lại, và đi về phía đồng vắng, theo đường Biển Đỏ.'),
(4135, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 26, 'OT', 'Đức Giê-hô-va phán cùng Môi-se và A-rôn, mà rằng:'),
(4136, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 27, 'OT', 'Đức Giê-hô-va phán: "Ta phải chịu đựng hội chúng ác nầy, là những kẻ oán trách Ta, cho đến chừng nào? Ta đã nghe những lời oán trách của Y-sơ-ra-ên mà chúng đang oán trách Ta.'),
(4137, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 28, 'OT', 'Hãy nói với họ: Đức Giê-hô-va phán: Ta lấy sự sống của Ta mà thề, chính như lời các ngươi đã nói trong tai Ta, Ta sẽ làm cho các ngươi y như vậy.'),
(4138, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 29, 'OT', 'Trong đồng vắng nầy, các xác các ngươi sẽ ngã xuống; và hết thảy những kẻ được điểm danh trong các ngươi, theo số lượng của các ngươi, từ hai mươi tuổi trở lên, là những kẻ đã chống nghịch ta,'),
(4139, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 30, 'OT', 'Các ngươi chắc chắn sẽ không vào xứ mà Ta đã giơ tay thề để cho các ngươi ở, ngoại trừ Ca-lép, con trai của Giê-phu-nê, và Giô-suê, con trai của Nun.'),
(4140, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 31, 'OT', 'Những con trẻ của các ngươi mà các ngươi nói rằng sẽ bị làm mồi, chính ta sẽ đem chúng vào, và chúng sẽ biết đến đất các ngươi đã chê bỏ.'),
(4141, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 32, 'OT', 'Còn các ngươi, chính mình các ngươi sẽ ngã xuống và chết trong đồng vắng nầy.'),
(4142, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 33, 'OT', 'Con cái các ngươi sẽ chăn dắt trong đồng vắng bốn mươi năm, và sẽ mang gánh nặng vì sự dâm dục của các ngươi, cho đến khi xác các ngươi đã ngã xuống hết trong đồng vắng.'),
(4143, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 34, 'OT', 'Theo số ngày các ngươi do thám đất ấy, là bốn mươi ngày, mỗi ngày ứng một năm: các ngươi sẽ mang gánh nặng tội lỗi mình trong bốn mươi năm, và các ngươi sẽ biết sự từ chối của Ta.'),
(4144, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 35, 'OT', 'Ta, Đức Giê-hô-va, đã phán: Nếu không phải điều nầy Ta sẽ làm cho cả hội chúng ác nghịch nầy đã cùng nhau chống nghịch lại Ta; tại đồng vắng nầy chúng nó sẽ bị tiêu diệt và chết tại đó.'),
(4145, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 36, 'OT', 'Còn những người mà Môi-se đã sai đi do thám xứ, khi trở về thì xúi giục cả hội chúng chống lại ông, làm cho người ta nói xấu về xứ ấy.'),
(4146, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 37, 'OT', 'Các người đàn ông đã đưa ra tin đồn xấu về miền đất ấy đều chết vì tai vạ, trước mặt Đức Giê-hô-va.'),
(4147, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 38, 'OT', 'Chỉ có Giô-suê, con trai của Nun, và Ca-lép, con trai của Giê-phu-nê, còn sống sót trong những người ấy, những kẻ đã đi do thám xứ.'),
(4148, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 39, 'OT', 'Môi-se nói những lời nầy cho toàn thể dân Y-sơ-ra-ên, và dân sự rất buồn bã.'),
(4149, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 40, 'OT', 'Sáng sớm, họ chỗi dậy và đi lên đến đỉnh núi, nói rằng: Này, chúng tôi đây, chúng tôi sẽ lên đến nơi mà Đức Giê-hô-va đã phán, vì chúng tôi đã phạm tội.'),
(4150, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 41, 'OT', 'Môi-se nói: "Tại sao các ngươi vi phạm mạng lịnh của Đức Giê-hô-va? Việc đó sẽ không thành công."'),
(4151, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 42, 'OT', 'Đừng đi lên, vì Đức Giê-hô-va không ở giữa các ngươi; e rằng các ngươi bị đánh bại trước mặt kẻ thù của mình.'),
(4152, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 43, 'OT', 'Vì dân A-ma-léc và dân Ca-na-an đang ở đó trước mặt các ngươi, và các ngươi sẽ ngã chết dưới lưỡi gươm; bởi các ngươi đã quay lưng khỏi Đức Giê-hô-va, nên Đức Giê-hô-va sẽ không ở cùng các ngươi.'),
(4153, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 44, 'OT', 'Nhưng họ cố ý đi lên đỉnh núi, còn hòm giao ước của Đức Giê-hô-va và Môi-se thì không rời khỏi giữa trại quân.'),
(4154, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 14, 45, 'OT', 'Dân A-ma-léc và dân Ca-na-an, là những kẻ ở trong núi nầy, đi xuống đánh bại dân Y-sơ-ra-ên cho đến tận Họt-ma.'),
(4155, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(4156, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 2, 'OT', 'Hãy nói cùng con cái Y-sơ-ra-ên và bảo họ: Khi các ngươi vào đất nơi ở mà ta ban cho các ngươi,'),
(4157, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 3, 'OT', 'Các ngươi hãy dâng cho Đức Giê-hô-va một của lễ thiêu, hoặc một của lễ, để thực hiện điều hứa nguyện, hoặc của lễ tự nguyện, hoặc trong các lễ hội các ngươi, hầu làm một mùi thơm đẹp lòng Đức Giê-hô-va, từ bò hoặc từ chiên.'),
(4158, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 4, 'OT', 'Người dâng lễ vật mình cho Đức Giê-hô-va phải dâng một của lễ chay bằng một phần mười ê-pha bột lọc, trộn với một phần tư hin dầu.'),
(4159, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 5, 'OT', 'Về rượu làm lễ quán, mỗi con chiên con phải dùng một phần tư hin, dâng cùng của lễ thiêu hay cùng của lễ hy sinh.'),
(4160, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 6, 'OT', 'Hoặc về một con chiên đực, ngươi phải làm của lễ chay bằng hai phần mười ê-pha bột lọc, trộn với dầu ô-liu, một phần ba hin.'),
(4161, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 7, 'OT', 'và một phần ba hin rượu làm lễ quán, dâng lên Đức Giê-hô-va làm của lễ thơm.'),
(4162, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 8, 'OT', 'Khi ngươi dâng một con bò đực làm của lễ thiêu hoặc của lễ xép, để thực hiện điều ước, hay của lễ thù ơn cho Đức Giê-hô-va,'),
(4163, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 9, 'OT', 'khi dâng con bò đực thì phải dâng chung với nó một của lễ chay bằng ba phần mười ê-pha bột lọc, trộn với nửa hin dầu,'),
(4164, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 10, 'OT', 'và phải dâng nửa hin rượu làm lễ quán: của lễ dùng lửa, có mùi thơm vừa lòng cho Đức Giê-hô-va.'),
(4165, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 11, 'OT', 'Như thế nào, phải làm như vậy cho mỗi con bò đực, hoặc mỗi con chiên đực, hoặc mỗi con chiên con trong các chiên con hoặc trong các dê.'),
(4166, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 12, 'OT', 'Tùy theo số lượng các ngươi làm, thì phải làm như vậy cho từng con, theo số lượng của chúng.'),
(4167, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 13, 'OT', 'Mọi người bản xứ phải làm như thế nầy, khi dâng của lễ thiêu, một mùi thơm cho Đức Giê-hô-va.'),
(4168, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 14, 'OT', 'Khi một khách lạ kiều ngụ giữa các ngươi, hay một người nào sống giữa các ngươi trong các thế hệ của các ngươi, dâng của lễ thiêu làm mùi thơm vừa lòng Đức Giê-hô-va, thì phải làm y như các ngươi làm.'),
(4169, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 15, 'OT', 'Cộng đồng sẽ có một luật lệ duy nhất cho các ngươi và cho khách lạ đang kiều ngụ giữa các ngươi; đó là một luật lệ đời đời cho các dòng dõi các ngươi: trước mặt Đức Giê-hô-va, khách lạ sẽ như các ngươi vậy.'),
(4170, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 16, 'OT', 'Luật lệ và mạng lịnh phải như nhau cho các ngươi và cho khách lạ là người ngoại bang đang kiều ngụ giữa các ngươi.'),
(4171, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 17, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(4172, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 18, 'OT', 'Hãy nói với các con trai Y-sơ-ra-ên rằng: Khi các ngươi vào đất mà Ta dẫn các ngươi đến,'),
(4173, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 19, 'OT', 'Khi các ngươi ăn bánh của đất nầy, thì phải dâng một phần lễ vật cho Đức Giê-hô-va.'),
(4174, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 20, 'OT', 'Các ngươi phải dâng lên bánh đầu tiên của đống bột các ngươi làm lễ vật dâng, như cách các ngươi dâng lễ vật đầu mùa về sân đạp lúa, thì cũng phải dâng lên như vậy.'),
(4175, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 21, 'OT', 'Các ngươi phải dâng cho Đức Giê-hô-va phần đầu tiên của bột nhồi các ngươi, làm lễ dâng cho các thế hệ các ngươi.'),
(4176, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 22, 'OT', 'Khi các ngươi lỡ phạm tội, không làm trọn các điều răn mà Đức Giê-hô-va đã phán dạy Môi-se,'),
(4177, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 23, 'OT', 'tất cả những điều mà Đức Giê-hô-va đã truyền cho các ngươi qua tay Môi-se, từ ngày Đức Giê-hô-va truyền và về sau, cho các dòng dõi các ngươi'),
(4178, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 24, 'OT', 'Nếu toàn thể hội chúng lỡ phạm tội mà các mắt của hội chúng không thấy, thì cả hội chúng phải dâng một con bò đực tơ làm của lễ thiêu, làm mùi thơm vừa lòng Đức Giê-hô-va, cùng với của lễ chay và lễ quán theo qui định; và một con dê đực làm của lễ chuộc tội.'),
(4179, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 25, 'OT', 'Thầy tế lễ sẽ làm lễ chuộc tội cho toàn thể hội chúng Y-sơ-ra-ên, thì tội lỗi của họ sẽ được tha, vì đó là tội phạm trong lúc lầm lạc; và chính họ đã dâng của lễ thiêu cho Đức Giê-hô-va, cùng với của lễ chuộc tội vì sự lầm lạc của mình, trước mặt Đức Giê-hô-va.'),
(4180, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 26, 'OT', 'Cả hội chúng con cái Y-sơ-ra-ên và khách ngoại bang kiều ngụ giữa họ sẽ được tha thứ, vì toàn thể dân sự đã phạm tội cách vô ý.'),
(4181, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 27, 'OT', 'Nếu một người nào lỡ phạm tội cách vô ý, thì phải dâng một con dê cái giáp năm làm của lễ chuộc tội.'),
(4182, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 28, 'OT', 'Thầy tế lễ sẽ làm lễ chuộc tội cho linh hồn đã phạm tội cách vô ý trước mặt Đức Giê-hô-va, để làm lễ chuộc tội cho người ấy, và người ấy sẽ được tha thứ.'),
(4183, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 29, 'OT', 'Dân Y-sơ-ra-ên và khách kiều ngụ giữa các ngươi sẽ có cùng một luật lệ, khi người nào lầm lỡ mà phạm tội.'),
(4184, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 30, 'OT', 'Nhưng nếu có người nào phạm tội cách cố ý, dù là người bản xứ hay là khách lạ, người đó đã khinh bỉ Đức Giê-hô-va; thì người ấy sẽ bị truất khỏi giữa dân sự mình.'),
(4185, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 31, 'OT', 'vì người ấy đã khinh bỉ lời Đức Giê-hô-va và vi phạm mạng lịnh Ngài; người ấy sẽ bị truất diệt, tội lỗi người sẽ ở trên mình người.'),
(4186, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 32, 'OT', 'Dân Y-sơ-ra-ên đang ở trong đồng vắng, thì gặp một người đang lượm củi trong ngày Sa-bát.'),
(4187, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 33, 'OT', 'Những người đã bắt gặp người đang lượm củi thì dẫn người ấy đến Môi-se, A-rôn và toàn thể hội chúng.'),
(4188, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 34, 'OT', 'Họ giam người ấy trong nơi giữ, vì chưa rõ điều phải làm cho người ấy là gì.'),
(4189, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 35, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Người đàn ông nầy phải bị xử tử bằng cách ném đá; cả hội chúng phải ném đá người tại nơi ngoài trại quân.'),
(4190, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 36, 'OT', 'Cả hội chúng đem người ấy ra ngoài trại quân, rồi ném đá người ấy cho đến chết, y như Đức Giê-hô-va đã truyền cho Môi-se.'),
(4191, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 37, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(4192, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 38, 'OT', 'Hãy nói cùng con cái Y-sơ-ra-ên và bảo họ rằng: Qua các thế hệ, họ phải làm những tua nơi các gấu áo mình, và phải đặt trên tua nơi gấu áo một sợi chỉ màu xanh thẫm.'),
(4193, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 39, 'OT', 'Các ngươi sẽ mang cái tua đó; khi thấy nó, các ngươi sẽ nhớ lại mọi điều răn của Đức Giê-hô-va mà thực hành, không đi theo lòng mình và theo mắt mình mà chạy theo sự dâm dục như các ngươi đã làm.'),
(4194, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 40, 'OT', 'Để các ngươi nhớ mà làm theo mọi điều răn của ta, và trở nên thánh cho Đức Chúa Trời của các ngươi.'),
(4195, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 15, 41, 'OT', 'Ta là Đức Giê-hô-va Đức Chúa Trời của các ngươi, Đấng đã đem các ngươi ra khỏi đất Ai-cập, để làm Đức Chúa Trời của các ngươi. Ta là Đức Giê-hô-va Đức Chúa Trời của các ngươi.'),
(4196, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 1, 'OT', 'Cô-rê, con trai của Dít-sê-ha, cháu của Kê-hát, chít của Lê-vi, cùng Đa-than và A-bi-ram, con trai của Ê-li-áp, và Oân, con trai của Phê-lết, cháu nội của Ru-bên, đã đứng lên chống lại.'),
(4197, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 2, 'OT', 'Hai trăm năm mươi người trong dân Y-sơ-ra-ên, tức là các quan trưởng của hội chúng, những người được gọi đến cuộc họp, là những người có danh tiếng, đều đứng lên nghịch cùng Môi-se và A-rôn.'),
(4198, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 3, 'OT', 'Họ nhóm lại nghịch Môi-se và A-rôn, mà rằng: Thôi đủ rồi! Vì cả hội chúng đều là thánh, và Đức Giê-hô-va ngự giữa họ; vậy sao các ngươi tự nâng mình lên trên hội chúng của Đức Giê-hô-va?'),
(4199, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 4, 'OT', 'Môi-se nghe vậy, liền phục mặt xuống đất.'),
(4200, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 5, 'OT', 'nói cùng Cô-rê và toàn thể nhóm người theo ông rằng: Sáng mai Đức Giê-hô-va sẽ cho biết ai thuộc về Ngài và ai là người thánh; Ngài sẽ khiến người ấy đến gần Ngài, và người mà Ngài chọn, thì Ngài sẽ khiến đến gần Ngài.'),
(4201, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 6, 'OT', 'Hãy làm điều nầy: Cô-rê và toàn thể hội chúng ngươi hãy lấy lư hương của mình;'),
(4202, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 7, 'OT', 'Sáng mai, hãy đặt lửa vào trong chúng và đặt hương trên đó trước mặt Đức Giê-hô-va. Người nào mà Đức Giê-hô-va chọn, chính người ấy là người thánh. Đủ rồi! Hỡi con cháu Lê-vi.'),
(4203, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 8, 'OT', 'Môi-se nói cùng Cô-rê: Hỡi các con trai của Lê-vi, hãy nghe bây giờ.'),
(4204, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 9, 'OT', 'Các ngươi mà Đức Chúa Trời của Y-sơ-ra-ên đã biệt riêng ra khỏi hội chúng Y-sơ-ra-ên, để đưa các ngươi đến gần Ngài, làm công việc trong đền tạm của Đức Giê-hô-va và phục vụ trước mặt hội chúng, việc ấy há phải là nhỏ mọn sao?'),
(4205, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 10, 'OT', 'Ngài đã khiến ngươi và tất cả anh em ngươi, con cháu Lê-vi, đến gần Ngài; vậy mà các ngươi còn đòi cả chức tế lễ nữa sao?'),
(4206, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 11, 'OT', 'Vì vậy, ngươi và toàn thể hội chúng của ngươi nhóm lại nghịch cùng Đức Giê-hô-va! Còn A-rôn là ai mà các ngươi lằm bằm chống lại người?'),
(4207, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 12, 'OT', 'Môi-se sai đi gọi Đa-than và A-bi-ram, con trai Ê-li-áp; nhưng họ đáp: Chúng tôi sẽ không lên đâu.'),
(4208, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 13, 'OT', 'Điều nhỏ bé đó đã đủ sao, mà ngươi đem chúng ta lên khỏi xứ chảy sữa và mật để làm chết chúng ta trong đồng vắng, ngươi lại còn muốn thống trị, thống trị trên chúng ta nữa sao?'),
(4209, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 14, 'OT', 'Huống chi, các ông chẳng dẫn chúng tôi vào đất chảy sữa và mật; các ông cũng chẳng cấp cho chúng tôi đất đai và vườn nho làm cơ nghiệp. Đôi mắt những người đàn ông ấy, các ông định khoét sao? Chúng tôi sẽ không đi lên.'),
(4210, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 15, 'OT', 'Môi-se rất giận dữ, nói cùng Đức Giê-hô-va: Xin chớ đoái đến của lễ chay của chúng nó; tôi đã không lấy một con lừa nào của chúng nó, cũng không làm hại một người nào trong chúng nó.'),
(4211, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 16, 'OT', 'Môi-se nói với Cô-rê: Ngươi và toàn thể hội chúng của ngươi, cùng với A-rôn, hãy đứng trước mặt Đức Giê-hô-va ngày mai; chính ngươi và họ.'),
(4212, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 17, 'OT', 'Mỗi người hãy lấy lư hương của mình, bỏ hương lên trên, rồi dâng lư hương mình trước mặt Đức Giê-hô-va, mỗi người một cái; tất cả có hai trăm năm mươi cái lư hương. Còn ngươi và A-rôn, mỗi người cũng phải lấy lư hương của mình.'),
(4213, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 18, 'OT', 'Mỗi người lấy lư hương mình, bỏ lửa vào, đặt hương trên đó, rồi đứng tại cửa Hội mạc, cùng với Môi-se và A-rôn.'),
(4214, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 19, 'OT', 'Cô-rê nhóm cả hội chúng lại nghịch cùng người, đến trước cửa nhà hội; và vinh hiển của Đức Giê-hô-va hiện ra trước toàn thể hội chúng.'),
(4215, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 20, 'OT', 'Đức Giê-hô-va phán cùng Môi-se và A-rôn rằng:'),
(4216, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 21, 'OT', 'Hãy tách ra khỏi giữa hội chúng nầy, để Ta tiêu diệt chúng trong chớp mắt.'),
(4217, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 22, 'OT', 'Hai người bèn sấp mặt xuống và nói: Lạy Đức Chúa Trời, là Đức Chúa Trời của các thần linh cho mọi xác thịt! Há một người phạm tội mà Ngài nổi giận cùng cả hội chúng sao?'),
(4218, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 23, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(4219, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 24, 'OT', 'Hãy nói cùng hội chúng rằng: Hãy lui ra khỏi chung quanh nơi ở của Cô-rê, Đa-than và A-bi-ram.'),
(4220, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 25, 'OT', 'Môi-se đứng dậy, đi đến Đa-than và A-bi-ram; các trưởng lão Y-sơ-ra-ên đi theo sau người.'),
(4221, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 26, 'OT', 'Người bảo hội chúng rằng: "Hãy rút lui ra khỏi các lều của những người đàn ông ác ấy, và chớ đụng đến bất cứ điều gì thuộc về họ, e các ngươi bị tiêu diệt vì mọi tội lỗi của họ."'),
(4222, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 27, 'OT', 'Dân chúng bèn rời khỏi chung quanh nơi ở của Cô-rê, Đa-than và A-bi-ram; và Đa-than cùng A-bi-ram ra đứng nơi cửa lều mình, cùng với các vợ, con trai và con nhỏ của họ.'),
(4223, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 28, 'OT', 'Môi-se nói: "Điều nầy sẽ cho các ngươi biết rằng chính Đức Giê-hô-va đã sai ta làm tất cả các việc nầy, vì các việc nầy không phải do ý ta mà làm."'),
(4224, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 29, 'OT', 'Nếu những người nầy chết như mọi người chết, và chịu sự thăm viếng như mọi người, thì Đức Giê-hô-va không sai tôi.'),
(4225, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 30, 'OT', 'Nhưng nếu Đức Giê-hô-va làm một điều lạ kỳ, và đất hả miệng ra nuốt họ cùng mọi vật thuộc về họ, và họ còn sống mà xuống âm phủ, thì các ngươi sẽ biết rằng những người nầy đã khinh bỉ Đức Giê-hô-va.'),
(4226, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 31, 'OT', 'Vừa khi Môi-se nói dứt các lời nầy, đất ngay dưới chân họ bèn nứt ra;'),
(4227, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 32, 'OT', 'Đất bèn há miệng mình nuốt họ và các gia đình họ, cùng hết thảy những người thuộc về Cô-rê và hết thảy tài sản.'),
(4228, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 33, 'OT', 'Chúng nó và mọi vật thuộc về chúng, còn sống, đều bị chìm xuống âm phủ; đất liền phủ kín chúng, và chúng bị tiêu diệt khỏi hội chúng.'),
(4229, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 34, 'OT', 'Cả Y-sơ-ra-ên ở xung quanh họ nghe tiếng kêu thì chạy trốn, vì nói rằng: Đừng để đất nuốt chúng ta!'),
(4230, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 35, 'OT', 'Và lửa từ Đức Giê-hô-va bốc ra, thiêu đốt hai trăm năm mươi người dâng hương.'),
(4231, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 36, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(4232, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 37, 'OT', 'Hãy nói cùng Ê-lê-a-sa, con trai thầy tế lễ A-rôn, biểu nhấc các lư hương lên khỏi giữa đám cháy, và đổ lửa ra chỗ xa, vì các lư hương đã được biệt riêng ra thánh.'),
(4233, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 38, 'OT', 'Hãy lấy những cái chậu đồng của những người đã phạm tội cùng mạng sống mình, mà làm các tấm mỏng để bọc bàn thờ, vì các người ấy đã dâng chậu trước mặt Đức Giê-hô-va, nên các chậu ấy đã được biệt riêng ra thánh; và chúng sẽ làm dấu cho con cái Y-sơ-ra-ên.'),
(4234, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 39, 'OT', 'Ê-lê-a-xa, thầy tế lễ, lấy những cái chảo bằng đồng mà những người bị thiêu đã dâng lên, rồi người ta cán mỏng ra để làm lớp mạ cho bàn thờ.'),
(4235, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 40, 'OT', 'Làm kỷ niệm cho con cái Y-sơ-ra-ên, hầu cho không một người nào không thuộc dòng dõi A-rôn lại gần để dâng hương trước mặt Đức Giê-hô-va, hầu không xảy ra như thể Cô-rê và hội chúng người, theo lời Đức Giê-hô-va đã phán bởi tay Môi-se cho ông.'),
(4236, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 41, 'OT', 'Ngày hôm sau, cả hội chúng dân Y-sơ-ra-ên nổi loạn cùng Môi-se và A-rôn, mà rằng: Các ngươi đã làm chết dân của Đức Giê-hô-va.'),
(4237, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 42, 'OT', 'Khi hội chúng họp lại nghịch cùng Môi-se và A-rôn, thì họ quay về hướng nhà tạm, và nầy, mây bao phủ nhà tạm, và sự vinh hiển của Đức Giê-hô-va hiện ra.'),
(4238, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 43, 'OT', 'Môi-se và A-rôn đi vào trước mặt hội mạc,'),
(4239, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 44, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(4240, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 45, 'OT', 'Hãy rút lui khỏi giữa hội chúng nầy, để Ta tiêu diệt chúng trong chớp mắt. Nhưng hai người sấp mặt xuống đất,'),
(4241, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 46, 'OT', 'Môi-se nói cùng A-rôn: "Hãy lấy cái lư hương, đặt lửa từ bàn thờ vào, bỏ hương lên, rồi mau mau đi đến hội chúng và làm lễ chuộc tội cho họ, vì cơn thịnh nộ từ trước mặt Đức Giê-hô-va đã nổi lên, tai họa đã bắt đầu xảy ra."'),
(4242, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 47, 'OT', 'A-rôn lấy lư hương như Môi-se đã phán, chạy đến giữa vòng dân chúng; nầy, tai họa đã bắt đầu lan giữa dân sự. A-rôn đặt hương lên, và làm lễ chuộc tội cho dân sự.'),
(4243, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 48, 'OT', 'Người đứng giữa những kẻ chết và những kẻ sống, thì tai họa liền bị ngăn lại.'),
(4244, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 49, 'OT', 'Mười bốn ngàn bảy trăm người chết vì tai họa, ngoài những người chết vì cớ Cô-rê.'),
(4245, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 16, 50, 'OT', 'A-rôn trở về cùng Môi-se tại cửa nhà hội, và tai họa đã bị ngăn lại.'),
(4246, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 17, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(4247, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 17, 2, 'OT', 'Hãy nói cùng con cái Y-sơ-ra-ên và lấy từ họ gậy này, mỗi gậy cho một nhà tổ tiên, lấy từ tất cả các quan trưởng của họ theo nhà tổ tiên; mười hai gậy, mỗi người ghi tên mình trên gậy của mình.'),
(4248, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 17, 3, 'OT', 'Ngươi hãy viết tên A-rôn trên cây gậy của Lê-vi, vì phải có một cây gậy cho mỗi trưởng họ.'),
(4249, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 17, 4, 'OT', 'Ngươi phải để chúng trong hội mạc, trước hòm bảng chứng, là nơi ta sẽ gặp ngươi.'),
(4250, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 17, 5, 'OT', 'Người nào Ta chọn, thì cây gậy của người ấy sẽ nở hoa; và Ta sẽ làm cho im đi trước mặt Ta những lời than trách của con cái Y-sơ-ra-ên mà chúng dành cho các ngươi.'),
(4251, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 17, 6, 'OT', 'Môi-se nói với các con trai của Y-sơ-ra-ên, thì tất cả các trưởng tộc của họ đã nộp cho ông một cây gậy, mỗi trưởng tộc một cây gậy theo từng nhà tổ tiên; tổng cộng mười hai cây gậy, và cây gậy của A-rôn ở giữa các cây gậy của họ.'),
(4252, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 17, 7, 'OT', 'Môi-se đặt những cây gậy đó trước mặt Đức Giê-hô-va trong hội mạc, tại nơi chứng tích.'),
(4253, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 17, 8, 'OT', 'Hôm sau, Môi-se vào nhà hội chứng, và nầy, cây gậy của A-rôn thuộc về nhà Lê-vi đã nứt lộc, sinh hoa và kết trái hạnh nhân.'),
(4254, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 17, 9, 'OT', 'Môi-se đem tất cả các cây gậy ra khỏi trước mặt Đức Giê-hô-va đến cùng mọi con trai của Y-sơ-ra-ên; họ nhìn xem và mỗi người lấy lại cây gậy của mình.'),
(4255, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 17, 10, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Hãy đem cây gậy của A-rôn trở lại để trước rương chứng cớ, mà giữ làm dấu cho con cái phản nghịch; các lời than trách của chúng sẽ thôi không còn chống nghịch ta nữa, hầu cho chúng không chết.'),
(4256, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 17, 11, 'OT', 'Môi-se làm như Đức Giê-hô-va đã truyền cho mình.'),
(4257, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 17, 12, 'OT', 'Dân Y-sơ-ra-ên nói cùng Môi-se rằng: Này, chúng tôi chết mất rồi, chúng tôi tiêu vong hết thảy, chúng tôi chết mất rồi!'),
(4258, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 17, 13, 'OT', 'Mọi người nào đến gần nhà Đức Giê-hô-va sẽ chết; phải chăng chúng tôi sẽ chết hết sao?'),
(4259, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 18, 1, 'OT', 'Đức Giê-hô-va phán cùng A-rôn rằng: Ngươi và các con trai ngươi cùng nhà tổ ngươi với ngươi sẽ mang lấy tội lỗi phạm trong nơi thánh; còn ngươi và các con trai ngươi với ngươi sẽ mang lấy tội lỗi phạm trong chức tế lễ của các ngươi.'),
(4260, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 18, 2, 'OT', 'Hãy đem các anh em ngươi, tức chi phái Lê-vi, chi phái của cha ngươi, đến gần ngươi, để họ gắn bó với ngươi và giúp việc ngươi; nhưng ngươi và các con trai ngươi phải ở trước Lều Chứng cớ.'),
(4261, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 18, 3, 'OT', 'Các người ấy sẽ giữ trách nhiệm của ngươi và trách nhiệm của toàn thể nơi thánh, nhưng không được đến gần các đồ thánh hay bàn thờ, để khỏi chết, và các ngươi cũng khỏi chết theo.'),
(4262, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 18, 4, 'OT', 'Các người ấy sẽ gắn bó với các ngươi và giữ nhiệm vụ của hội mạc, để làm mọi công việc tại trại; còn người ngoại nào thì không được đến gần các ngươi.'),
(4263, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 18, 5, 'OT', 'Các ngươi phải giữ điều thuộc về nơi thánh và điều thuộc về bàn thờ, để cơn thịnh nộ không còn giáng trên con cái Y-sơ-ra-ên nữa.'),
(4264, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 18, 6, 'OT', 'Và này ta đã chọn lấy anh em các ngươi là những người Lê-vi từ giữa các con cái Y-sơ-ra-ên, để ban cho các ngươi như một món quà đã được trao cho Đức Giê-hô-va, hầu phục vụ công việc của hội mạc.'),
(4265, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 18, 7, 'OT', 'Nhưng ngươi và các con trai ngươi cùng với ngươi phải giữ chức tế lễ của các ngươi đối với mọi điều thuộc về bàn thờ và bên trong bức màn; các ngươi phải làm việc đó. Ta ban cho các ngươi chức tế lễ như một của lễ ban; người ngoại nào đến gần sẽ bị giết.'),
(4266, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 18, 8, 'OT', 'Đức Giê-hô-va phán cùng A-rôn: Nầy, ta đã trao cho ngươi việc giữ các lễ vật thánh của ta, tức mọi vật thánh của con cái Y-sơ-ra-ên; ta đã trao chúng cho ngươi và cho các con trai ngươi như một phần riêng, để làm một luật lệ đời đời, do phép xức dầu truyền lại.'),
(4267, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 18, 9, 'OT', 'Đây sẽ là phần thuộc về ngươi trong các vật rất thánh từ lửa: mọi lễ vật của họ, mọi của lễ chay, mọi của lễ chuộc tội, mọi của lễ chuộc sự mắc lỗi mà họ dâng lại cho Đức Giê-hô-va; các vật rất thánh nầy sẽ thuộc về ngươi và các con trai ngươi.'),
(4268, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 18, 10, 'OT', 'Ngươi phải ăn nó trong nơi thánh của các nơi thánh; mọi người nam sẽ ăn nó, nó sẽ là vật thánh cho ngươi.'),
(4269, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 18, 11, 'OT', 'Và đây là phần lễ vật dâng lên cho ngươi từ các lễ vật mà con cái Y-sơ-ra-ên dâng: Ta đã ban cho ngươi, các con trai ngươi và các con gái ngươi cùng ngươi làm luật lệ đời đời; mọi người tinh sạch trong nhà ngươi sẽ được ăn nó.'),
(4270, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 18, 12, 'OT', 'Mọi mỡ của dầu, mọi mỡ của rượu mới và lúa mì; phần đầu mùa mà họ dâng cho Đức Giê-hô-va, Ta đã ban cho ngươi.'),
(4271, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 18, 13, 'OT', 'Mọi sản vật đầu mùa trên đất mà dân Y-sơ-ra-ên dâng cho Đức Giê-hô-va, đều sẽ thuộc về ngươi; mỗi người tinh sạch trong nhà ngươi sẽ được ăn nó.'),
(4272, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 18, 14, 'OT', 'Mọi vật bị tuyệt diệt trong Y-sơ-ra-ên sẽ thuộc về ngươi.'),
(4273, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 18, 15, 'OT', 'Mọi con đầu lòng của mọi xác thịt, bất luận người hay súc vật, mà dân Y-sơ-ra-ên dâng cho Đức Giê-hô-va, đều thuộc về ngươi; nhưng ngươi phải chuộc lại con đầu lòng của loài người, và cũng phải chuộc lại con đầu lòng của súc vật không sạch.'),
(4274, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 18, 16, 'OT', 'Về những đứa con đã được chuộc từ một tháng tuổi trở lên, ngươi phải chuộc chúng theo giá định của ngươi, là năm miếng bạc theo miếng bạc của nơi thánh; một miếng bạc của nơi thánh bằng hai mươi ghê-ra.'),
(4275, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 18, 17, 'OT', 'Chỉ con đầu lòng của bò đực, hoặc con đầu lòng của chiên đực, hoặc con đầu lòng của dê đực, ngươi không được chuộc lại; chúng là thánh. Ngươi phải rưới huyết chúng trên bàn thờ và đốt mỡ chúng làm lễ thiêu, làm của lễ dùng lửa thiêu dâng lên có mùi thơm cho Đức Giê-hô-va.'),
(4276, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 18, 18, 'OT', 'Thịt của chúng sẽ thuộc về ngươi, như vòm ngực dâng đưa và như cái giò bên phải; chúng sẽ được trao cho ngươi.'),
(4277, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 18, 19, 'OT', 'Mọi lễ vật thánh mà con cái Y-sơ-ra-ên dâng lên cho Đức Giê-hô-va, Ta đã ban cho ngươi, các con trai ngươi và các con gái ngươi cùng ngươi làm luật lệ đời đời; ấy là giao ước muối đời đời trước mặt Đức Giê-hô-va, dành cho ngươi và dòng dõi ngươi cùng ngươi.'),
(4278, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 18, 20, 'OT', 'Đức Giê-hô-va phán cùng A-rôn: Trong xứ của dân Y-sơ-ra-ên, ngươi sẽ không được chia đất làm cơ nghiệp, cũng không có phần nào cho ngươi giữa họ; ta là phần ngươi được hưởng và là cơ nghiệp của ngươi giữa con cái Y-sơ-ra-ên.'),
(4279, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 18, 21, 'OT', 'Ta đã ban cho con cháu Lê-vi mọi phần mười trong Y-sơ-ra-ên làm cơ nghiệp, để đền bù cho công việc phục vụ mà họ làm trong hội mạc.'),
(4280, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 18, 22, 'OT', 'Dân Y-sơ-ra-ên không được lại gần hội mạc nữa, hầu cho khỏi mang tội mà chết.'),
(4281, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 18, 23, 'OT', 'Chính người Lê-vi sẽ đảm nhiệm công việc nơi Hội mạc; chính họ sẽ mang gánh nặng vì tội mình; đó là luật định đời đời cho các thế hệ các ngươi, và giữa các con trai Y-sơ-ra-ên họ sẽ không được nhận phần cơ nghiệp.'),
(4282, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 18, 24, 'OT', 'Vì ta đã ban cho người Lê-vi làm cơ nghiệp phần thập phần của dân Y-sơ-ra-ên, mà họ dâng lên cho Đức Giê-hô-va làm của lễ; bởi cớ đó, ta đã phán cùng họ rằng: Các ngươi sẽ không được nhận cơ nghiệp giữa các con dân Y-sơ-ra-ên.'),
(4283, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 18, 25, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(4284, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 18, 26, 'OT', 'Hãy nói với người Lê-vi rằng: Khi các ngươi nhận từ con cái Y-sơ-ra-ên phần mười mà ta đã ban cho các ngươi làm sản nghiệp, thì các ngươi phải dâng lên Đức Giê-hô-va phần mười lấy từ chính phần mười ấy làm lễ vật dâng.'),
(4285, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 18, 27, 'OT', 'Lễ vật dâng lên cho các ngươi sẽ được kể như lúa lấy từ sân đạp lúa, và như đầy đủ lấy từ nơi ép rượu.'),
(4286, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 18, 28, 'OT', 'Vậy các ngươi cũng phải dâng lên Đức Giê-hô-va phần đầu tiên trong mọi thứ các ngươi lấy được từ dân Y-sơ-ra-ên; và phải giao phần đầu tiên dâng lên Đức Giê-hô-va đó cho A-rôn, thầy tế lễ.'),
(4287, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 18, 29, 'OT', 'Trong mọi lễ vật các ngươi nhận được, phải dâng lên Đức Giê-hô-va phần đầu tiên trọn vẹn, lấy từ phần tốt nhất của nó, biệt riêng phần thánh của nó ra.'),
(4288, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 18, 30, 'OT', 'Ngươi phải nói cùng người Lê-vi rằng: Khi các ngươi dâng lấy phần mỡ của nó lên, thì sẽ kể cho người Lê-vi như sản vật của sân đạp lúa và như sản vật của bồn ép rượu.'),
(4289, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 18, 31, 'OT', 'Các ngươi và nhà các ngươi sẽ ăn nó tại mọi nơi, vì ấy là phần thưởng cho các ngươi, để đền bù công việc các ngươi làm tại hội mạc.'),
(4290, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 18, 32, 'OT', 'Các ngươi sẽ không mang tội khi dâng phần mỡ của nó lên; các ngươi cũng không được làm profane các vật thánh của dân Y-sơ-ra-ên, hầu các ngươi không chết.'),
(4291, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 19, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se và A-rôn rằng:'),
(4292, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 19, 2, 'OT', 'Đây là luật lệ của luật pháp mà Đức Giê-hô-va đã truyền dạy, rằng: Hãy nói với con cái Y-sơ-ra-ên rằng phải đem đến cho ngươi một con bò cái đỏ tơ, hoàn toàn, không tì vết, chưa mang ách trên mình.'),
(4293, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 19, 3, 'OT', 'Trao nó cho Ê-lê-a-xa, thầy tế lễ; người ấy sẽ dẫn nó ra ngoài trại quân, rồi giết nó trước mặt người ấy.'),
(4294, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 19, 4, 'OT', 'Ê-lê-a-xa, thầy tế lễ, sẽ lấy huyết con bò bằng ngón tay mình, rồi rảy huyết về phía trước mặt Nhà Hội mạc bảy lần.'),
(4295, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 19, 5, 'OT', 'Người ta phải thiêu con bò cái trước mặt người ấy: thiêu cả da, thịt và huyết của nó cùng với phân nó.'),
(4296, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 19, 6, 'OT', 'Thầy tế lễ sẽ lấy cây bách, cây hyssôp, và chỉ sợi điều, rồi quăng vào giữa đám lửa thiêu con bò cái.'),
(4297, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 19, 7, 'OT', 'Rồi thầy tế lễ phải giặt áo xống mình và tắm rửa thân thể trong nước; sau đó mới được vào trại quân, và thầy tế lễ sẽ bị ô uế cho đến chiều tối.'),
(4298, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 19, 8, 'OT', 'Người thiêu con bò cái ấy phải giặt áo xống mình trong nước và rửa thân thể mình trong nước, rồi bị ô uế cho đến chiều tối.'),
(4299, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 19, 9, 'OT', 'Một người thanh sạch sẽ thu lấy tro con bò cái tơ và để ra ngoài trại, tại một nơi thanh sạch; tro ấy phải được dành giữ cho hội chúng con cái Y-sơ-ra-ên dùng làm nước thanh tẩy; ấy là một lễ chuộc tội.'),
(4300, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 19, 10, 'OT', 'Kẻ hốt tro con bò phải giặt áo xống mình và bị ô uế cho đến chiều tối. Việc nầy sẽ làm luật lệ đời đời cho con cái Y-sơ-ra-ên và cho khách ngoại bang kiều ngụ giữa họ.'),
(4301, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 19, 11, 'OT', 'Người nào đụng đến xác chết của bất cứ người nào sẽ bị ô uế bảy ngày.'),
(4302, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 19, 12, 'OT', 'Người ấy phải làm cho mình được sạch vào ngày thứ ba và ngày thứ bảy, thì sẽ được sạch; còn nếu không làm cho mình được sạch vào ngày thứ ba và ngày thứ bảy, thì sẽ không được sạch.'),
(4303, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 19, 13, 'OT', 'Phàm mọi người nào đụng đến xác chết của một người, tức là một linh hồn người chết, mà không làm cho mình được sạch, thì sẽ làm cho nơi ở của Đức Giê-hô-va bị ô uế; và linh hồn ấy sẽ bị truất khỏi Y-sơ-ra-ên, vì nước tẩy uế không được rảy trên người ấy, nên người ấy sẽ vẫn ô uế; sự ô uế của người ấy vẫn còn ở trên mình người ấy.'),
(4304, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 19, 14, 'OT', 'Đây là luật lệ: khi một người chết trong một cái lều, bất kỳ ai vào lều và mọi vật ở trong lều đều bị ô uế bảy ngày.'),
(4305, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 19, 15, 'OT', 'Mọi vật dụng bằng gốm hở miệng, mà không có dây niêm phong buộc quanh nắp, thì bị ô uế.'),
(4306, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 19, 16, 'OT', 'Ai đụng đến xác bị giết bằng gươm, hoặc xác chết, hoặc xương người, hoặc một ngôi mộ ngoài đồng, sẽ bị ô uế bảy ngày.'),
(4307, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 19, 17, 'OT', 'Người ta phải lấy tro của con sinh tế đền tội đã bị thiêu đốt cho người bị ô uế, rồi đổ nước sống vào một cái bình.'),
(4308, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 19, 18, 'OT', 'Một người tinh sạch sẽ lấy cây kinh giới nhúng vào nước, rồi rảy trên trại, trên mọi đồ vật, trên những người có mặt tại đó, và trên người đã đụng đến xương người chết, hay một xác chết bị giết, hay một xác chết, hay một ngôi mộ.'),
(4309, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 19, 19, 'OT', 'Người tinh sạch sẽ rảy nước trên người bị ô uế vào ngày thứ ba và ngày thứ bảy; người ấy sẽ làm cho người bị ô uế được sạch vào ngày thứ bảy, rồi giặt quần áo mình, tắm trong nước và đến chiều tối mới được tinh sạch.'),
(4310, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 19, 20, 'OT', 'Người nào bị ô uế mà không làm cho mình được sạch, thì linh hồn người ấy sẽ bị cắt đứt khỏi giữa vòng hội chúng, vì người ấy đã làm cho nơi thánh của Đức Giê-hô-va bị ô uế; nước tẩy uế không được rảy trên người ấy, nên người ấy vẫn ô uế.'),
(4311, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 19, 21, 'OT', 'Đó sẽ là một luật lệ đời đời cho họ: người rảy nước thanh tẩy phải giặt quần áo mình; ai chạm vào nước thanh tẩy sẽ bị ô uế cho đến chiều tối.'),
(4312, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 19, 22, 'OT', 'Phàm vật gì mà người ô uế đụng đến sẽ bị ô uế; còn người nào đụng đến người đó thì sẽ bị ô uế cho đến chiều tối.'),
(4313, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 20, 1, 'OT', 'Cả hội chúng dân Y-sơ-ra-ên đến đồng vắng Xin trong tháng giêng, và dân chúng ở lại tại Ca-đe. Tại đó, Mi-ri-am qua đời và được chôn tại đó.'),
(4314, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 20, 2, 'OT', 'Vả không có nước cho hội chúng; bèn nhóm lại nghịch cùng Môi-se và A-rôn.'),
(4315, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 20, 3, 'OT', 'Dân sự tranh cãi với Môi-se, và nói rằng: Phải chi chúng tôi đã chết khi anh em chúng tôi qua đời trước mặt Đức Giê-hô-va!'),
(4316, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 20, 4, 'OT', 'Tại sao các người đem hội chúng của Đức Giê-hô-va vào đồng vắng nầy, để chết tại đây chúng tôi và súc vật của chúng tôi?'),
(4317, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 20, 5, 'OT', 'Tại sao các người khiến chúng tôi lên khỏi Ai Cập, để dẫn chúng tôi đến nơi độc ác nầy? Đây chẳng phải là nơi có thể gieo giống, cũng chẳng có cây vả, cây nho, hay cây lựu; và cũng không có nước để uống.'),
(4318, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 20, 6, 'OT', 'Môi-se và A-rôn đi từ trước mặt hội chúng đến cửa Đền tạm, rồi sấp mặt xuống đất; và vinh hiển của Đức Giê-hô-va hiện ra cùng họ.'),
(4319, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 20, 7, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(4320, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 20, 8, 'OT', 'Hãy cầm lấy cây gậy, rồi ngươi và A-rôn anh ngươi nhóm hội chúng lại, và hai ngươi phải nói cùng hòn đá trước mặt họ, thì nó sẽ cho nước ra; ngươi sẽ rút nước từ hòn đá cho hội chúng và súc vật của họ uống.'),
(4321, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 20, 9, 'OT', 'Môi-se lấy cây gậy ra khỏi trước mặt Đức Giê-hô-va, y như điều Đức Giê-hô-va đã truyền cho ông.'),
(4322, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 20, 10, 'OT', 'Môi-se và A-rôn nhóm dân sự lại trước mặt hòn đá, rồi nói với họ rằng: "Hỡi những kẻ phản nghịch, hãy nghe đây! Chúng ta há phải lấy nước ra cho các ngươi từ hòn đá nầy sao?"'),
(4323, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 20, 11, 'OT', 'Môi-se giơ tay lên, rồi dùng cây gậy mình đập vào hòn đá hai lần; nước chảy ra rất nhiều, và hội chúng cùng súc vật của họ đã uống.'),
(4324, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 20, 12, 'OT', 'Đức Giê-hô-va phán cùng Môi-se và A-rôn: "Bởi các ngươi không tin Ta, để thánh hóa Ta trước mặt con cái Y-sơ-ra-ên, nên các ngươi sẽ không dẫn được hội chúng này vào xứ mà Ta đã ban cho chúng nó."'),
(4325, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 20, 13, 'OT', 'Ấy là những nước của Mê-ri-ba, là nơi con cái Y-sơ-ra-ên tranh cãi cùng Đức Giê-hô-va, và Ngài được xưng thánh giữa họ.'),
(4326, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 20, 14, 'OT', 'Từ Ca-đe, Môi-se sai các sứ giả đi đến vua Ê-đôm, nói rằng: Y-sơ-ra-ên, là anh em của vua, có nói như vầy: Vua biết tất cả các sự khốn khổ mà chúng tôi đã gặp phải.'),
(4327, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 20, 15, 'OT', 'Tổ tiên chúng tôi đã xuống Ai Cập, và chúng tôi sống tại Ai Cập nhiều ngày. Dân Ai Cập đã đối xử ác với chúng tôi và với tổ tiên chúng tôi.'),
(4328, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 20, 16, 'OT', 'Chúng tôi đã kêu cứu cùng Đức Giê-hô-va, và Ngài đã nghe tiếng chúng tôi, sai một thiên sứ đem chúng tôi ra khỏi Ai-cập; nầy, chúng tôi hiện ở tại Ca-đe, thành ở nơi rìa biên giới của vua.'),
(4329, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 20, 17, 'OT', 'Xin hãy để chúng tôi đi ngang qua xứ của ngài; chúng tôi sẽ không đi ngang qua ruộng đồng, cũng không đi ngang qua vườn nho, và sẽ không uống nước từ các giếng; chúng tôi sẽ đi theo con đường của vua, không rẽ về bên phải, cũng không rẽ về bên trái, cho đến khi chúng tôi đi ngang qua bờ cõi của ngài.'),
(4330, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 20, 18, 'OT', 'Ê-đôm đáp: Ngươi không được đi ngang qua đất ta; nếu không, ta sẽ cầm gươm ra nghênh chiến với ngươi.'),
(4331, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 20, 19, 'OT', 'Dân Y-sơ-ra-ên nói với người rằng: Chúng tôi sẽ đi theo đường cái; nếu chúng tôi và súc vật của chúng tôi uống nước của ông, thì tôi sẽ trả tiền cho nước đó. Chỉ xin không làm gì khác ngoài việc đi bộ ngang qua mà thôi.'),
(4332, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 20, 20, 'OT', 'Ê-đôm đáp: "Ngươi không được qua!" Rồi Ê-đôm kéo ra nghênh chiến với Y-sơ-ra-ên, cùng một đạo quân đông đảo và tay cầm binh khí hùng mạnh.'),
(4333, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 20, 21, 'OT', 'Ê-đôm từ chối cho phép Y-sơ-ra-ên đi ngang qua bờ cõi mình, nên Y-sơ-ra-ên bèn trở đi khỏi người.'),
(4334, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 20, 22, 'OT', 'Cả hội chúng Y-sơ-ra-ên dời khỏi Ca-đe và đi đến núi Hô-rơ.'),
(4335, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 20, 23, 'OT', 'Đức Giê-hô-va phán cùng Môi-se và A-rôn trên núi Hô-rơ, tại biên giới đất Ê-đôm, mà rằng:'),
(4336, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 20, 24, 'OT', 'A-rôn sẽ được thu về cùng dân người, vì người sẽ không vào được đất mà Ta đã ban cho con cái Y-sơ-ra-ên; bởi các ngươi đã chống nghịch lời Ta tại các nước Mê-ri-ba.'),
(4337, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 20, 25, 'OT', 'Hãy lấy A-rôn và Ê-lê-a-xa, con trai người, rồi dẫn hai người lên núi Hô-rơ.'),
(4338, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 20, 26, 'OT', 'Hãy cởi áo xống của A-rôn ra và mặc cho Ê-lê-a-sa, con trai người; rồi A-rôn sẽ được thu nhận và qua đời tại đó.'),
(4339, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 20, 27, 'OT', 'Môi-se làm y như Đức Giê-hô-va đã truyền, và họ lên núi Hô-rơ, trước mặt cả hội chúng.'),
(4340, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 20, 28, 'OT', 'Môi-se lột áo của A-rôn và mặc cho Ê-lê-a-sa, con trai người; A-rôn chết tại đó trên đỉnh núi; rồi Môi-se và Ê-lê-a-sa đi xuống khỏi núi.'),
(4341, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 20, 29, 'OT', 'Toàn thể hội chúng thấy A-rôn đã qua đời, bèn khóc thương A-rôn ba mươi ngày, cả nhà Y-sơ-ra-ên.'),
(4342, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 1, 'OT', 'Vua A-rát, người Ca-na-an, ở miền Nam, nghe tin Y-sơ-ra-ên đến theo con đường các do thám, bèn đánh giặc với Y-sơ-ra-ên và bắt một số người làm tù binh.'),
(4343, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 2, 'OT', 'Y-sơ-ra-ên khấn hứa cùng Đức Giê-hô-va, mà rằng: Nếu Ngài chắc chắn phó dân nầy vào tay tôi, tôi sẽ tiêu diệt các thành của nó.'),
(4344, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 3, 'OT', 'Đức Giê-hô-va nhậm lời Y-sơ-ra-ên, và phó dân Ca-na-an vào tay họ; nên họ diệt dân ấy và các thành của chúng; và đặt tên chỗ đó là Họt-ma.'),
(4345, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 4, 'OT', 'Dân Y-sơ-ra-ên khởi hành từ núi Hô-rơ, đi theo con đường Biển Đỏ để vòng quanh xứ Ê-đôm; lòng dân sự hao mòn vì đường đi.'),
(4346, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 5, 'OT', 'Dân sự nói nghịch cùng Đức Chúa Trời và Môi-se rằng: "Tại sao người đưa chúng tôi lên khỏi Ai-cập để chết trong đồng vắng? Vì không có bánh, cũng không có nước, và linh hồn chúng tôi đã chán ngấy thứ lương thực đạm bạc này."'),
(4347, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 6, 'OT', 'Đức Giê-hô-va sai các con rắn lửa đến trong dân sự, cắn những người Y-sơ-ra-ên, và một số rất đông người Y-sơ-ra-ên đã chết.'),
(4348, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 7, 'OT', 'Dân sự đến cùng Môi-se và nói: "Chúng tôi đã phạm tội, vì đã nói nghịch lại Đức Giê-hô-va và ông. Hãy cầu nguyện cùng Đức Giê-hô-va để Ngài gỡ bỏ con rắn khỏi chúng tôi." Môi-se bèn cầu nguyện cho dân sự.'),
(4349, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 8, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Hãy làm cho mình một con rắn bằng đồng, rồi đặt nó trên một cây sào; và sẽ xảy ra rằng, hễ ai bị rắn cắn mà nhìn thấy nó thì sẽ sống.'),
(4350, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 9, 'OT', 'Môi-se làm một con rắn bằng đồng, rồi đặt nó trên cây sào; nếu rắn cắn người nào, mà người ấy nhìn con rắn bằng đồng thì sẽ sống.'),
(4351, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 10, 'OT', 'Dân Y-sơ-ra-ên đi và đóng trại tại Ô-bốt.'),
(4352, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 11, 'OT', 'Họ khởi hành từ Ô-bốt và đóng trại tại Y-giê-A-ba-rim, trong đồng vắng, đối ngang Mô-áp về phía mặt trời mọc.'),
(4353, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 12, 'OT', 'Họ đi từ đó và cắm trại tại khe Xê-rết.'),
(4354, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 13, 'OT', 'Từ đó, họ khởi hành và đóng trại bên kia Aït-nôn, ở trong đồng vắng, là nơi bắt đầu từ ranh giới của dân A-mô-rít; vì Aït-nôn là ranh giới của Mô-áp, giữa Mô-áp và dân A-mô-rít.'),
(4355, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 14, 'OT', 'Bởi cớ đó, trong sách Chiến trận của Đức Giê-hô-va có chép rằng: Va-hép tại Su-pha, và các khe Aït-nôn,'),
(4356, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 15, 'OT', 'cùng những triền trũng chảy xuống phía A-rơ, và tựa vào ranh giới Mô-áp.'),
(4357, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 16, 'OT', 'Từ đó họ đến Bê-re; ấy là cái giếng mà Đức Giê-hô-va đã phán cùng Môi-se: Hãy nhóm dân sự lại, ta sẽ ban nước cho họ.'),
(4358, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 17, 'OT', 'Bấy giờ Y-sơ-ra-ên hát bài ca nầy: Hỡi giếng, hãy trào lên! Hãy đáp lại nó!'),
(4359, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 18, 'OT', 'Giếng mà các quan đã đào, các lãnh tụ dân sự đã cùng nhau đào, bằng cây trượng quyền năng của mình; từ đồng vắng, đến Mathana.'),
(4360, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 19, 'OT', 'Từ Ma-tha-na đến Na-ha-li-ên; từ Na-ha-li-ên đến Ba-mốt.'),
(4361, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 20, 'OT', 'và từ Ba-mốt đến trũng trong đồng bằng Mô-áp, trên đỉnh núi Phích-ga, nhìn xuống phía trước đồng bằng.'),
(4362, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 21, 'OT', 'Y-sơ-ra-ên sai các sứ giả đến Si-hôn, vua của dân A-mô-rít, nói rằng:'),
(4363, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 22, 'OT', 'Xin cho phép tôi đi ngang qua xứ của ngài; chúng tôi sẽ không rẽ vào ruộng đồng hay vườn nho, cũng không uống nước từ các giếng; chúng tôi sẽ đi theo con đường của vua cho đến khi vượt qua biên giới của ngài.'),
(4364, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 23, 'OT', 'Nhưng Si-hôn không cho phép Y-sơ-ra-ên đi ngang qua bờ cõi mình, bèn tập hợp toàn thể dân mình, đi ra nghênh chiến cùng Y-sơ-ra-ên trong đồng vắng, và đến Gia-hát, rồi giao chiến với Y-sơ-ra-ên.'),
(4365, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 24, 'OT', 'Y-sơ-ra-ên đánh bại người bằng lưỡi gươm và chiếm lấy đất người, từ Aït-nôn cho đến Gia-bốc, cho đến con cái Am-môn; vì ranh giới con cái Am-môn rất vững chắc.'),
(4366, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 25, 'OT', 'Dân Y-sơ-ra-ên chiếm lấy hết các thành nầy, và Y-sơ-ra-ên ở trong mọi thành của dân A-mô-rít, tại Hết-bôn và trong mọi thành thuộc về nó.'),
(4367, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 26, 'OT', 'Vì Hết-bôn là thành của Si-hôn, vua dân A-mô-rít; chính người đã giao chiến cùng vua đầu tiên của Mô-áp, chiếm lấy toàn bộ đất người ấy từ tay người cho đến Aït-nôn.'),
(4368, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 27, 'OT', 'Vì cớ đó, những người nói lời châm ngôn sẽ nói: Hãy đến Hết-bôn! Phải xây và lập vững thành của Si-hôn.'),
(4369, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 28, 'OT', 'Vì một ngọn lửa đã ra từ Hết-bôn, một ngọn lửa từ thành Si-hôn, thiêu rụi A-rơ của Mô-áp, các chúa tể các nơi cao Aït-nôn.'),
(4370, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 29, 'OT', 'Khốn thay cho ngươi, hỡi Mô-áp! Ngươi đã bị tiêu diệt, hỡi dân của Kê-móc! Ngươi đã trao con trai mình làm kẻ chạy trốn, và con gái mình làm phu tù cho vua A-mô-rít là Si-hôn.'),
(4371, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 30, 'OT', 'Chúng ta đã thiêu hủy, Hết-bôn bị tiêu diệt cho đến Đi-bôn; chúng ta đã hủy diệt đến Nô-phách, nơi đến tận Mê-đê-ba.'),
(4372, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 31, 'OT', 'Vậy, Y-sơ-ra-ên ở trong đất của dân A-mô-rít.'),
(4373, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 32, 'OT', 'Môi-se sai quân đi do thám Gia-ê-xe, chiếm các thành thuộc vùng đất ấy, rồi đuổi dân A-mô-rít đang sống tại đó.'),
(4374, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 33, 'OT', 'Dân Y-sơ-ra-ên quay lại và lên đường về Ba-san; thì Oùc, vua Ba-san, cùng toàn thể dân sự người đi ra đón chiến trận tại Eát-rê-i.'),
(4375, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 34, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Đừng sợ nó, vì ta đã phó nó, toàn dân nó và đất nó vào tay ngươi; ngươi sẽ làm cho nó như đã làm cho Si-hôn, vua dân A-mô-rít ở tại Hết-bôn.'),
(4376, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 21, 35, 'OT', 'Dân Y-sơ-ra-ên đánh bại người, các con trai người và toàn thể dân sự người, cho đến nỗi không để lại cho người một ai; rồi họ chiếm lấy đất người.'),
(4377, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 1, 'OT', 'Dân Y-sơ-ra-ên đi và đóng trại trong các đồng bằng Mô-áp, bên kia sông Giô-đanh, đối diện Giê-ri-cô.'),
(4378, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 2, 'OT', 'Ba-lác, con trai của Xếp-bô, thấy mọi điều mà Y-sơ-ra-ên đã làm cho dân A-mô-rít.'),
(4379, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 3, 'OT', 'Mô-áp lấy làm sợ hãi rất nhiều trước mặt dân Y-sơ-ra-ên, vì dân đó rất đông; và Mô-áp lấy làm kinh hãi trước mặt con cái Y-sơ-ra-ên.'),
(4380, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 4, 'OT', 'Mô-áp nói cùng các trưởng lão Ma-đi-an: "Bây giờ đoàn dân nầy sẽ liếm sạch mọi thứ chung quanh chúng ta như bò liếm sạch cỏ trên đồng." Và lúc ấy, Ba-lác, con trai Xếp-bô, làm vua xứ Mô-áp.'),
(4381, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 5, 'OT', 'Vua sai các sứ giả đến cùng Ba-la-am con trai Bê-ô, ở Phê-thô-rơ, trên bờ sông, trong xứ con cái dân sự người, để gọi người mà nói rằng: Nầy, một dân đã ra khỏi Ai-cập, nầy nó đã che phủ mặt đất, và nó đang ở đối ngang ta.'),
(4382, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 6, 'OT', 'Vậy bây giờ, hãy đi, ta nài xin ngươi hãy rủa dân nầy cho ta, vì nó mạnh hơn ta; có lẽ ta sẽ đánh bại nó và đuổi nó khỏi đất này được. Vì ta biết rõ rằng ai ngươi chúc phước thì được phước, ai ngươi rủa thì bị rủa.'),
(4383, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 7, 'OT', 'Các trưởng lão Mô-áp và các trưởng lão Ma-đi-an đi, tay cầm những lễ vật bói toán, đến gặp Ba-la-am và thuật lại cho ông những lời của Ba-lác.'),
(4384, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 8, 'OT', 'Hắn nói với họ: "Hãy ở lại đây đêm nay, để ta có thể trả lời các ngươi điều gì mà Đức Giê-hô-va sẽ phán dạy ta." Các sứ giả của Mô-áp bèn ở lại cùng Ba-la-am.'),
(4385, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 9, 'OT', 'Đức Chúa Trời đến cùng Ba-la-am và phán: "Những người nầy cùng ngươi là ai?"'),
(4386, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 10, 'OT', 'Ba-la-am nói cùng Đức Chúa Trời rằng: Ba-lác, con trai Xếp-bô, vua xứ Mô-áp, đã sai đến tôi.'),
(4387, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 11, 'OT', 'Nầy, dân nầy đã ra khỏi xứ Ai Cập, và đã phủ kín mặt đất. Bây giờ, hãy đến rủa sả nó cho ta, hầu ta có thể chiến đấu với nó và đuổi nó đi.'),
(4388, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 12, 'OT', 'Đức Chúa Trời phán cùng Ba-la-am: "Ngươi không được đi với chúng nó; ngươi không được rủa sả dân ấy, vì dân ấy được Đức Giê-hô-va ban phước."'),
(4389, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 13, 'OT', 'Sáng hôm ấy, Ba-la-am chỗi dậy, nói cùng các quan trưởng của Ba-lác rằng: "Hãy đi về đất nước mình, vì Đức Giê-hô-va không cho phép tôi đi cùng các ngươi."'),
(4390, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 14, 'OT', 'Các quan trưởng Mô-áp đứng dậy, đến cùng Ba-lác và tâu rằng: Ba-la-am từ chối không chịu đi với chúng tôi.'),
(4391, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 15, 'OT', 'Ba-lác lại tiếp tục sai thêm các sứ thần, đông hơn và trọng hơn những người trước,'),
(4392, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 16, 'OT', 'Các sứ giả đến cùng Ba-la-am và nói với ông: "Ba-lác, con trai Xếp-bô, nói như vầy: Ta xin ngươi, chớ từ chối đến cùng ta."'),
(4393, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 17, 'OT', 'vì ta sẽ rất trọng đãi ngươi, và mọi điều ngươi nói cùng ta, ta sẽ làm; vậy hãy đến đây, ta xin ngươi hãy nguyền rủa dân nầy.'),
(4394, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 18, 'OT', 'Ba-la-am đáp và nói với các đầy tớ của Ba-lác: "Dầu Ba-lác có cho tôi đầy nhà người bạc và vàng, tôi cũng không thể làm trái mạng của Đức Giê-hô-va, Đức Chúa Trời của tôi, để làm điều gì dù nhỏ hay lớn."'),
(4395, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 19, 'OT', 'Vậy bây giờ, hãy ở lại đây cũng trong đêm nay, để ta biết điều gì Đức Giê-hô-va sẽ phán cùng ta thêm nữa.'),
(4396, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 20, 'OT', 'Đức Chúa Trời đến cùng Ba-la-am trong đêm và phán với người rằng: Nếu những người kia đến gọi ngươi, hãy chỗi dậy đi với họ; nhưng ngươi chỉ được làm điều mà Ta sẽ phán cùng ngươi.'),
(4397, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 21, 'OT', 'Sáng hôm sau, Ba-la-am chỗi dậy, buộc lừa mình vào, rồi đi cùng các quan trưởng Mô-áp.'),
(4398, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 22, 'OT', 'Cơn thịnh nộ của Đức Chúa Trời nổi lên vì người đi; thiên sứ của Đức Giê-hô-va đứng trên đường để chống lại người. Còn người thì cỡi lừa của mình, và hai đầy tớ đi theo cùng người.'),
(4399, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 23, 'OT', 'Lừa cái thấy thiên sứ của Đức Giê-hô-va đứng trên đường, tay cầm gươm tuốt trần, bèn tẽ khỏi đường mà đi vào giữa đồng; Ba-la-am đánh lừa đặng quay nó trở lại đường.'),
(4400, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 24, 'OT', 'Thiên sứ của Đức Giê-hô-va đứng ở lối đi giữa hai vườn nho, có tường bên này và tường bên kia.'),
(4401, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 25, 'OT', 'Lừa thấy thiên sứ của Đức Giê-hô-va, liền ép sát vào vách và dồn chân Ba-la-am vào vách; nhưng Ba-la-am vẫn tiếp tục đánh nó.'),
(4402, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 26, 'OT', 'Đức Giê-hô-va tiếp tục sai thiên sứ của Ngài đi tới, và người đứng tại một nơi hẹp, không có lối nào để rẽ phải hay rẽ trái.'),
(4403, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 27, 'OT', 'Lừa thấy thiên sứ của Đức Giê-hô-va, liền nằm quỵ dưới Ba-la-am. Ba-la-am nổi giận, đánh lừa bằng cây gậy.'),
(4404, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 28, 'OT', 'Đức Giê-hô-va mở miệng con lừa, thì nó nói cùng Ba-la-am rằng: Tôi đã làm gì cho ông mà ông đánh tôi đến ba lần?'),
(4405, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 29, 'OT', 'Ba-la-am nói với con lừa: "Ngươi đã nhạo báng ta. Ước chi có thanh gươm trong tay ta, bây giờ ta đã giết ngươi rồi!"'),
(4406, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 30, 'OT', 'Lừa nói cùng Ba-la-am: "Tôi há chẳng phải là con lừa của ông, mà ông đã cỡi từ trước đến nay cho đến ngày nay sao? Tôi há đã từng làm điều này cùng ông chưa?" Ông đáp: "Không."'),
(4407, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 31, 'OT', 'Đức Giê-hô-va mở mắt Ba-la-am, thì người thấy thiên sứ của Đức Giê-hô-va đứng trên đường, tay cầm gươm trần; bèn cúi mình xuống và sấp mặt xuống đất.'),
(4408, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 32, 'OT', 'Thiên sứ của Đức Giê-hô-va phán cùng người rằng: "Ngươi đã đánh con lừa mình ba lần, vì cớ điều chi? Nầy, ta ra đi đặng chống cự ngươi, vì con đường ngươi đi trước mặt ta là con đường sai lạc."'),
(4409, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 33, 'OT', 'Thật, con lừa cái đã thấy ta và né tránh ta ba lần; nếu nó không né tránh ta, chắc ta đã giết ngươi và để nó sống.'),
(4410, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 34, 'OT', 'Bấy giờ Ba-la-am thưa cùng thiên sứ của Đức Giê-hô-va rằng: Tôi đã phạm tội, vì tôi không biết rằng chính Ngài đứng chặn đường tôi. Bây giờ, nếu điều đó làm Ngài bất lòng, tôi sẽ trở về.'),
(4411, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 35, 'OT', 'Thiên sứ của Đức Giê-hô-va phán cùng Ba-la-am rằng: "Hãy đi cùng những người nầy, nhưng chỉ điều chi ta bảo ngươi nói, thì ngươi hãy nói." Vậy Ba-la-am đi cùng các quan trưởng của Ba-lác.'),
(4412, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 36, 'OT', 'Khi Ba-lác nghe tin Ba-la-am đã đến, thì ông đi ra đón người tại thành Mô-áp, là thành ở gần khe Aït-nôn, nơi tận biên giới.'),
(4413, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 37, 'OT', 'Ba-lác nói với Ba-la-am: "Này, ta há chẳng đã sai sứ đến mời ngươi sao? Sao ngươi không đến cùng ta? Ta há thật sự không thể tôn vinh ngươi sao?"'),
(4414, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 38, 'OT', 'Ba-la-am đáp cùng Ba-lác: Nầy, tôi đã đến cùng ngươi; bây giờ, tôi há có thể nói điều gì sao? Tôi sẽ nói điều mà Đức Chúa Trời đặt trong miệng tôi.'),
(4415, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 39, 'OT', 'Vậy Ba-la-am đi với Ba-lác, và cả hai đến Ki-ri-át-Hút-sốt.'),
(4416, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 40, 'OT', 'Ba-lác giết bò và chiên, rồi sai mang đến cho Ba-la-am và các quan trưởng ở cùng người.'),
(4417, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 22, 41, 'OT', 'Sáng hôm sau, Ba-lác dẫn Ba-la-am lên các nơi cao Ba-mốt-Ba-anh, và từ đó người thấy tận cùng dân sự.'),
(4418, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 23, 1, 'OT', 'Ba-la-am nói với Ba-lác: "Hãy xây cho tôi tại đây bảy bàn thờ, và chuẩn bị cho tôi tại đây bảy con bò đực và bảy con chiên đực."'),
(4419, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 23, 2, 'OT', 'Ba-lác làm như lời Ba-la-am đã nói; rồi Ba-lác và Ba-la-am dâng một con bò đực và một con chiên đực trên bàn thờ.'),
(4420, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 23, 3, 'OT', 'Ba-la-am nói cùng Ba-lác: "Hãy đứng gần của lễ thiêu của ngươi, ta sẽ đi; có lẽ Đức Giê-hô-va sẽ hiện ra cùng ta, ta sẽ thuật lại cho ngươi điều gì Ngài cho ta thấy." Người bèn đi lên một nơi trống trải.'),
(4421, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 23, 4, 'OT', 'Đức Chúa Trời hiện đến cùng Ba-la-am, và phán cùng người rằng: "Ta đã lập bảy bàn thờ, và dâng một con bò đực và một con chiên đực trên mỗi bàn thờ."'),
(4422, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 23, 5, 'OT', 'Đức Giê-hô-va đặt một lời trong miệng Ba-la-am, và phán: "Hãy trở về cùng Ba-lác, và nói như thế này."'),
(4423, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 23, 6, 'OT', 'Rồi Ba-la-am trở về cùng Ba-lác, và nầy, Ba-lác đang đứng gần của lễ thiêu mình với tất cả các quan trưởng Mô-áp.'),
(4424, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 23, 7, 'OT', 'Ba-la-am cất bài ca mình mà nói rằng: Từ A-ram, Ba-lác vua Mô-áp đã sai đón tôi, từ các núi phía Đông; hãy đến, nguyền rủa tôi Gia-cốp, và hãy đến, nổi giận cùng Y-sơ-ra-ên.'),
(4425, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 23, 8, 'OT', 'Làm sao ta rủa sả kẻ mà Đức Chúa Trời chưa rủa sả? Làm sao ta nguyền rủa kẻ mà Đức Giê-hô-va chưa nguyền rủa?'),
(4426, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 23, 9, 'OT', 'Vì từ đầu các vầng đá ta thấy nó, và từ các gò cao ta ngó nó: Kìa, một dân sống riêng rẽ, không bị đếm cùng các nước.'),
(4427, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 23, 10, 'OT', 'Ai có thể đếm được bụi của Gia-cốp, ai có thể tính được phần tư của Y-sơ-ra-ên? Nguyện cho linh hồn tôi chết theo kiểu chết của người ngay thẳng, và cuối cùng đời tôi cũng giống như vậy!'),
(4428, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 23, 11, 'OT', 'Bấy giờ, Ba-lác nói cùng Ba-la-am: "Ngươi đã làm chi ta vậy? Ta mời ngươi đến để nguyền rủa kẻ thù ta, thế mà ngươi lại chúc phước, chúc phước!'),
(4429, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 23, 12, 'OT', 'Người đáp và nói: "Tôi há chẳng giữ kỹ điều Đức Giê-hô-va đặt vào miệng tôi sao, để nói đúng như vậy?"'),
(4430, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 23, 13, 'OT', 'Ba-lác nói với người rằng: "Hãy đi cùng tôi đến một nơi khác, từ đó ngươi sẽ thấy dân nầy; ngươi chỉ thấy một phần đầu của họ, chứ không thấy hết toàn thể; và từ đó hãy nguyền rủa họ cho tôi."'),
(4431, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 23, 14, 'OT', 'Người dẫn người đến đồng Xô-phim, trên đỉnh núi Phích-ga, và người xây bảy bàn thờ, rồi dâng lên mỗi bàn thờ một con bò đực và một con chiên đực.'),
(4432, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 23, 15, 'OT', 'Ba-la-am nói cùng Ba-lác: "Hãy đứng tại đây gần của lễ thiêu ngươi, còn ta sẽ đi đến đó đón Đức Giê-hô-va."'),
(4433, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 23, 16, 'OT', 'Đức Giê-hô-va phán cùng Ba-la-am, đặt lời vào miệng người, và phán: "Hãy trở về cùng Ba-lác, và nói như thế nầy."'),
(4434, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 23, 17, 'OT', 'Người đến cùng người, và nầy, người đứng trên của lễ thiêu của mình, và các quan trưởng Mô-áp ở cùng người. Ba-lác nói cùng người rằng: Đức Giê-hô-va đã phán chi?'),
(4435, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 23, 18, 'OT', 'Vậy người cất lời mình lên và nói rằng: Hỡi Ba-lác, hãy chỗi dậy mà nghe! Hỡi Ba-lác, con trai Xếp-bô, hãy lắng tai mà nghe!'),
(4436, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 23, 19, 'OT', 'Đức Chúa Trời không phải là người để nói dối, cũng không phải là con loài người để phải hối tiếc; Ngài há đã nói mà chẳng làm sao? hay đã phán mà chẳng giữ lời?'),
(4437, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 23, 20, 'OT', 'Nầy, ta đã nhận lấy mệnh lệnh phải chúc phước; Ngài đã chúc phước, ta không thể rút lại được.'),
(4438, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 23, 21, 'OT', 'Không thấy điều ác nào nơi Gia-cốp, cũng chẳng thấy điều gian tà nào nơi Y-sơ-ra-ên; Đức Giê-hô-va Đức Chúa Trời người ở cùng người, và tiếng reo mừng của vua vang nơi người.'),
(4439, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 23, 22, 'OT', 'Đức Chúa Trời đã đem chúng ra khỏi Ai Cập; Sức lực chúng như bò tót vậy.'),
(4440, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 23, 23, 'OT', 'Vì nơi Gia-cốp không có phù phép, và nơi Y-sơ-ra-ên không có bói toán; theo kỳ định, người ta sẽ nói cho Gia-cốp và cho Y-sơ-ra-ên biết: Đức Chúa Trời đã làm những điều kỳ diệu thể nào.'),
(4441, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 23, 24, 'OT', 'Kìa, dân nầy chỗi dậy như sư tử cái, và trỗi dậy như sư tử đực; nó sẽ không nằm ngủ cho đến khi nào ăn xong mồi, và uống huyết những kẻ bị giết.'),
(4442, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 23, 25, 'OT', 'Bấy giờ Ba-lác nói cùng Ba-la-am: "Ngươi chớ rủa nó, nhưng cũng chớ chúc phước cho nó."'),
(4443, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 23, 26, 'OT', 'Bấy giờ Ba-la-am đáp và nói cùng Ba-lác rằng: "Tôi há chẳng đã nói với ngươi rằng: Mọi điều nào Đức Giê-hô-va phán ra, tôi phải làm điều ấy?'),
(4444, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 23, 27, 'OT', 'Ba-lác nói cùng Ba-la-am rằng: Hãy đến, ta sẽ dẫn ngươi đến một nơi khác, hoặc là Đức Chúa Trời sẽ thấy đẹp lòng và ngươi có thể rủa sả nó cho ta từ nơi đó.'),
(4445, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 23, 28, 'OT', 'Vậy Ba-lác dẫn Ba-la-am đến đầu núi Phê-ô, đối diện với đồng vắng.'),
(4446, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 23, 29, 'OT', 'Ba-la-am nói cùng Ba-lác: "Hãy xây cho tôi tại đây bảy cái bàn thờ, và chuẩn bị cho tôi tại đây bảy con bò đực và bảy con chiên đực."'),
(4447, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 23, 30, 'OT', 'Vậy, Ba-lác làm như Ba-la-am đã nói; người dâng một con bò đực và một con chiên đực trên các bàn thờ.'),
(4448, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 24, 1, 'OT', 'Ba-la-am thấy rõ rằng Đức Giê-hô-va muốn ban phước cho Y-sơ-ra-ên, nên không đi như những lần trước để tìm các dấu kỳ, mà đặt mặt hướng về đồng vắng.'),
(4449, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 24, 2, 'OT', 'Ba-la-am nhướng mắt lên, thấy Y-sơ-ra-ên đang đóng trại theo các chi phái mình, và Đức Chúa Trời ngự trên người.'),
(4450, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 24, 3, 'OT', 'Người cất lời nói tiên tri mình và nói rằng: Lời phán của Ba-la-am, con trai Bê-ô, lời phán của người có mắt sáng suốt,'),
(4451, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 24, 4, 'OT', 'Lời của người nghe các lời của Đức Chúa Trời, Đấng xem sự hiện thấy của Đấng Toàn Năng, Sấp mình xuống và mắt mở ra:'),
(4452, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 24, 5, 'OT', 'Hỡi Gia-cốp, những trại ngươi tốt lành thay! Hỡi Y-sơ-ra-ên, những nơi ở ngươi xinh đẹp làm sao!'),
(4453, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 24, 6, 'OT', 'Như các khe nước trải dài, như vườn cây bên bờ sông, như những lều mà Đức Giê-hô-va đã dựng lên, như những cây bá hương bên bờ nước.'),
(4454, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 24, 7, 'OT', 'Nước chảy ra từ thùng của người, và dòng dõi người sẽ ở trong những nước lớn; người ấy sẽ cao hơn A-gát, và vương quyền của người sẽ được nâng cao.'),
(4455, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 24, 8, 'OT', 'Đức Chúa Trời đã dẫn người ra khỏi xứ Ai-cập; người có sức mạnh như trâu rừng; người sẽ nuốt các dân, tức kẻ thù nghịch mình, nghiền nát xương chúng nó, và bẻ gãy tên chúng nó.'),
(4456, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 24, 9, 'OT', 'Nó nằm phục xuống như sư tử đực, như sư tử cái, ai sẽ khiến nó đứng dậy? Kẻ nào chúc phước ngươi sẽ được chúc phước, kẻ nào rủa sả ngươi sẽ bị rủa sả.'),
(4457, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 24, 10, 'OT', 'Bấy giờ, Ba-lác nổi giận cùng Ba-la-am, vỗ tay mà nói với Ba-la-am rằng: "Ta đã mời ngươi đến để nguyền rủa kẻ thù ta, thế mà ngươi lại chúc phước, chúc phước đi chúc phước lại đã ba lần!"'),
(4458, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 24, 11, 'OT', 'Vậy bây giờ, hãy trốn về nơi ngươi đã đến; ta đã nói ta sẽ tôn vinh ngươi, nhưng nầy, Đức Giê-hô-va đã ngăn ngươi khỏi sự vinh hiển.'),
(4459, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 24, 12, 'OT', 'Ba-la-am đáp cùng Ba-lác: "Chẳng phải ta đã nói cùng các sứ giả ngươi đã sai đến ta rằng:'),
(4460, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 24, 13, 'OT', 'Dầu Ba-lác cho tôi đầy nhà người bạc và vàng, tôi cũng không thể vượt qua lệnh của Đức Giê-hô-va để làm điều lành hay điều dữ theo ý mình; điều nào Đức Giê-hô-va phán, tôi sẽ nói điều đó.'),
(4461, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 24, 14, 'OT', 'Bây giờ, nầy, ta sắp trở về cùng dân ta; hãy lại, ta sẽ bày cho ngươi biết điều mà dân nầy sẽ làm cho dân ngươi trong những ngày sau rốt.'),
(4462, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 24, 15, 'OT', 'Người cất lời mình lên và nói: Ba-la-am, con trai Bê-ô, phán vậy; người có mắt mở ra phán vậy.'),
(4463, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 24, 16, 'OT', 'Lời của người nghe các lời Đức Chúa Trời, biết tri thức của Đấng Chí Cao, thấy sự hiện thấy của Đấng Toàn Năng, ngã xuống mà mắt mở ra:'),
(4464, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 24, 17, 'OT', 'Tôi thấy người, nhưng không phải bây giờ; tôi nhìn người, nhưng chẳng gần; một ngôi sao sẽ mọc lên từ Gia-cốp, và một cây trượng sẽ trỗi dậy từ Y-sơ-ra-ên; người ấy sẽ đánh tan các đầu mút của Mô-áp, và phá hủy tất cả con cháu của Sết.'),
(4465, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 24, 18, 'OT', 'Ê-đôm sẽ bị chiếm giữ; kẻ thù nghịch mình là Sê-i-rơ sẽ bị Y-sơ-ra-ên chiếm lấy; Y-sơ-ra-ên sẽ làm điều quyền năng.'),
(4466, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 24, 19, 'OT', 'Đấng ra từ Gia-cốp sẽ thống trị, và những người sót lại của thành sẽ bị tiêu diệt.'),
(4467, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 24, 20, 'OT', 'Ba-la-am thấy A-ma-léc, bèn ngước lên lời tiên tri mình và nói rằng: A-ma-léc là đầu các dân, nhưng cuối cùng sẽ hoàn toàn bị tiêu diệt.'),
(4468, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 24, 21, 'OT', 'Ba-la-am thấy người Kê-nít, bèn ngước cao bài ca của mình mà nói rằng: Chỗ ở ngươi là vững bền, và tổ ngươi đặt trong hòn đá.'),
(4469, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 24, 22, 'OT', 'Nhưng Ca-in sẽ bị tiêu diệt, cho đến khi A-su-rơ bắt ngươi làm tù binh.'),
(4470, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 24, 23, 'OT', 'Người cất bài ca mình mà nói rằng: Ôi! Ai sẽ còn sống khi Đức Chúa Trời đặt điều đó?'),
(4471, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 24, 24, 'OT', 'Và những tàu sẽ đến từ gành Kít-tim, và nó sẽ làm khổ A-su, và làm khổ Hê-be; và chính nó cũng sẽ bị tiêu diệt.'),
(4472, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 24, 25, 'OT', 'Bấy giờ Ba-la-am đứng dậy, đi về chỗ mình, và cũng vậy, Ba-lác đi đường riêng của người.'),
(4473, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 25, 1, 'OT', 'Dân Y-sơ-ra-ên ở tại Si-tim, và dân sự bắt đầu phạm tội tà dâm cùng các con gái Mô-áp.'),
(4474, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 25, 2, 'OT', 'Các cô gái mời dân chúng đến dự tiệc tế lễ các thần của chúng; dân chúng ăn và thờ lạy các thần của chúng.'),
(4475, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 25, 3, 'OT', 'Y-sơ-ra-ên liền gắn bó với Ba-anh-Phê-ô; và cơn thịnh nộ của Đức Giê-hô-va nổi lên nghịch cùng Y-sơ-ra-ên.'),
(4476, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 25, 4, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Hãy bắt tất cả các đầu mục của dân sự, và treo chúng nó lên trước mặt Đức Giê-hô-va đối với mặt trời, để cơn thạnh nộ của Đức Giê-hô-va xây khỏi Y-sơ-ra-ên.'),
(4477, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 25, 5, 'OT', 'Môi-se nói cùng các quan xét của Y-sơ-ra-ên rằng: Mỗi người phải giết những kẻ trong dân sự mình đã gắn bó với Ba-anh-Phê-ô.'),
(4478, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 25, 6, 'OT', 'Nầy, một người trong con cái Y-sơ-ra-ên đến và dẫn người nữ Ma-đi-an đến cùng anh em mình, trước mặt Môi-se và trước mặt cả hội chúng con cái Y-sơ-ra-ên, khi họ đang khóc tại cửa trại hội.'),
(4479, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 25, 7, 'OT', 'Phi-nê-a, con trai Ê-lê-a-sa, cháu A-rôn, thầy tế lễ, thấy điều đó, bèn đứng dậy giữa vòng hội chúng, và cầm một cây giáo nơi tay mình.'),
(4480, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 25, 8, 'OT', 'người ấy đi theo một người Y-sơ-ra-ên vào trong trại, đâm xuyên hai người, cả người nam Y-sơ-ra-ên lẫn người nữ vào ngay bụng; tai ương liền dứt khỏi dân Y-sơ-ra-ên.'),
(4481, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 25, 9, 'OT', 'Số người chết trong cơn dịch bệnh ấy là hai mươi bốn ngàn.'),
(4482, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 25, 10, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(4483, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 25, 11, 'OT', 'Phi-nê-a, con trai Ê-lê-a-sa, con trai A-rôn, thầy tế lễ, đã làm cho cơn thạnh nộ của ta rời khỏi dân Y-sơ-ra-ên, vì người đã vì ta mà ganh ghét giữa họ; nên ta đã không tiêu diệt dân Y-sơ-ra-ên trong cơn ganh ghét của ta.'),
(4484, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 25, 12, 'OT', 'Vì vậy, hãy nói rằng: Nầy, Ta ban cho người giao ước bình an của Ta.'),
(4485, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 25, 13, 'OT', 'Giao ước về chức tế lễ đời đời sẽ thuộc về người và dòng dõi người sau người, vì người đã sốt sắng cho Đức Chúa Trời mình và chuộc tội cho con cái Y-sơ-ra-ên.'),
(4486, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 25, 14, 'OT', 'Tên người Y-sơ-ra-ên đã bị giết, là kẻ bị giết cùng với người nữ Ma-đi-an, là Xim-ri con trai Sa-lu, quan trưởng một họ hàng của người Si-mê-ôn.'),
(4487, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 25, 15, 'OT', 'Tên người nữ Ma-đi-an bị giết là Cốt-bi, con gái Xu-rơ, đầu trưởng các họ hàng trong nhà cha của người ấy tại Ma-đi-an.'),
(4488, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 25, 16, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(4489, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 25, 17, 'OT', 'Hãy gây chiến với dân Ma-đi-an và đánh bại chúng.'),
(4490, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 25, 18, 'OT', 'Vì chúng nó đã trở thành kẻ khuấy rối các ngươi bằng mưu kế của chúng đối với các ngươi về việc Phê-ô, và về việc của Cốt-bi, con gái quan trưởng Ma-đi-an, chị em của chúng, là người đã bị giết trong ngày tai họa vì cớ việc Phê-ô.'),
(4491, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 1, 'OT', 'Sau tai vạ đó, Đức Giê-hô-va phán cùng Môi-se và Ê-lê-a-sa, con trai A-rôn, thầy tế lễ, rằng:'),
(4492, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 2, 'OT', 'Hãy điểm danh đầu của cả hội chúng con cái Y-sơ-ra-ên, từ con trai hai mươi tuổi trở lên, theo nhà tổ phụ của chúng, mọi người có thể ra đi chinh chiến trong Y-sơ-ra-ên.'),
(4493, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 3, 'OT', 'Môi-se và thầy tế lễ Ê-lê-a-sa nói cùng họ tại các đồng bằng Mô-áp bên bờ sông Giô-đanh đối ngang Giê-ri-cô, rằng:'),
(4494, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 4, 'OT', 'Từ hai mươi tuổi trở lên, theo như Đức Giê-hô-va đã truyền dặn Môi-se và con cái Y-sơ-ra-ên, những người ra khỏi đất Ê-díp-tô.'),
(4495, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 5, 'OT', 'Ru-bên, trưởng nam của Y-sơ-ra-ên. Con trai của Ru-bên: Hê-nóc, dòng họ Hê-nóc; Pha-lu, dòng họ Pha-lu.'),
(4496, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 6, 'OT', 'Do nơi Hết-rôn sanh ra họ Hết-rôn; do nơi Cạt-mi sanh ra họ Cạt-mi.'),
(4497, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 7, 'OT', 'Đó là các họ của Ru-bên; và số người được điểm danh của họ là bốn mươi ba ngàn bảy trăm ba mươi người.'),
(4498, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 8, 'OT', 'Con trai của Pha-lu là Ê-li-áp.'),
(4499, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 9, 'OT', 'Các con trai của Ê-li-áp là Nê-mu-ên, Đa-than và A-bi-ram; ấy chính là Đa-than và A-bi-ram, những người được gọi trong hội chúng, đã chống nghịch lại Môi-se và A-rôn trong phe đảng của Cô-rê, khi chúng nổi loạn nghịch cùng Đức Giê-hô-va.'),
(4500, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 10, 'OT', 'Đất bèn nứt ra miệng mình và nuốt sống họ cùng với Cô-rê trong tai nạn của hội chúng, khi lửa thiêu hủy hai trăm năm mươi người; và họ trở thành một dấu hiệu cảnh cáo.'),
(4501, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 11, 'OT', 'Nhưng các con trai Cô-rê không chết.'),
(4502, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 12, 'OT', 'Các con trai của Si-mê-ôn, theo các họ hàng của họ: của Nê-mu-ên, dòng họ Nê-mu-ên; của Gia-min, dòng họ Gia-min; của Gia-kin, dòng họ Gia-kin.'),
(4503, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 13, 'OT', 'Do nơi Sê-rách sanh ra họ Sê-rách; do nơi Sau-lơ sanh ra họ Sau-lơ.'),
(4504, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 14, 'OT', 'Đó là các họ của Si-mê-ôn: hai mươi hai ngàn hai trăm người.'),
(4505, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 15, 'OT', 'Các con trai của Gát, theo các họ hàng của họ: về Xê-phôn, dòng họ Xê-phôn; về Ha-ghi, dòng họ Ha-ghi; về Su-ni, dòng họ Su-ni.'),
(4506, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 16, 'OT', 'do nơi Oùc-ni sanh ra họ Oùc-ni; do nơi Ê-ri sanh ra họ Ê-ri;'),
(4507, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 17, 'OT', 'Do nơi A-rốt sanh ra họ A-rốt; do nơi A-rê-li sanh ra họ A-rê-li.'),
(4508, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 18, 'OT', 'Đây là các họ hàng của con trai Gát, theo số điểm danh của họ: bốn mươi ngàn năm trăm người.'),
(4509, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 19, 'OT', 'Các con trai của Giu-đa là Ê-rơ và Ô-nan; rồi Ê-rơ và Ô-nan đã qua đời tại đất Ca-na-an.'),
(4510, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 20, 'OT', 'Các con trai của Giu-đa, theo các họ hàng của họ: do nơi Sê-la sanh ra họ Sê-la-ni; do nơi Phê-rết sanh ra họ Pha-rết-si; do nơi Sê-rách sanh ra họ Xa-rách-si.'),
(4511, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 21, 'OT', 'Các con trai của Pha-rết: do nơi Hết-rôn sanh ra họ Hết-rôn; do nơi Ha-mun sanh ra họ Ha-mun.'),
(4512, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 22, 'OT', 'Đó là các họ của Giu-đa, tùy theo số điểm của họ: bảy mươi sáu ngàn năm trăm người.'),
(4513, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 23, 'OT', 'Các con trai của Y-sa-ca, theo các họ hàng mình: Thô-la, họ hàng của người Thô-la; Phu-va, họ hàng của người Phu-va;'),
(4514, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 24, 'OT', 'do nơi Gia-súp sanh ra họ Gia-súp; do nơi Sim-rôn sanh ra họ Sim-rôn.'),
(4515, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 25, 'OT', 'Đó là các họ hàng của Y-sa-ca, theo số người được kiểm tra: sáu mươi bốn ngàn ba trăm người.'),
(4516, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 26, 'OT', 'Các con trai của Sa-bu-lôn, theo các họ hàng của họ: do nơi Sê-rết, họ hàng của người Sê-rết; do nơi Ê-lôn, họ hàng của người Ê-lôn; do nơi Gia-lê-ên, họ hàng của người Gia-lê-ên.'),
(4517, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 27, 'OT', 'Đó là các họ hàng của Sa-bu-lôn theo sự điểm danh của họ: sáu mươi ngàn năm trăm người.'),
(4518, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 28, 'OT', 'Con cái của Giô-sép theo các chi họ của họ là Ma-na-se và Eùp-ra-im.'),
(4519, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 29, 'OT', 'Các con trai của Ma-na-se: theo họ của Ma-ki, là dòng họ Ma-ki; và Ma-ki sinh ra Ga-la-át; theo Ga-la-át, là dòng họ Ga-la-át.'),
(4520, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 30, 'OT', 'Đây là các con trai của Ga-la-át: họ Giê-xe, do Giê-xe; họ Hê-léc, do Hê-léc.'),
(4521, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 31, 'OT', 'và của Aùch-ri-ên, là dòng họ Aùch-ri-ên; và của Si-chem, là dòng họ Si-chem;'),
(4522, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 32, 'OT', 'do nơi Sê-mi-đa sanh ra họ Sê-mi-đa; do nơi Hê-phe sanh ra họ Hê-phe.'),
(4523, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 33, 'OT', 'Xê-lô-phát, con trai của Hê-phe, không có con trai, chỉ có con gái; tên các con gái của Xê-lô-phát là Mách-la, Nô-a, Hốt-la, Minh-ca và Thiệt-sa.'),
(4524, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 34, 'OT', 'Đó là các chi phái của Ma-na-se; số người được kiểm tra là năm mươi hai ngàn bảy trăm.'),
(4525, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 35, 'OT', 'Đây là con trai của Eùp-ra-im, theo các họ hàng của họ: thuộc về Su-thê-lách thì có họ hàng Su-thê-lách; thuộc về Bê-kê thì có họ hàng Bê-kê; thuộc về Tha-chan thì có họ hàng Tha-chan.'),
(4526, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 36, 'OT', 'Đây là các con trai của Su-thê-lách: theo dòng họ Ê-ran, là họ hàng của Ê-ran.'),
(4527, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 37, 'OT', 'Đó là các họ hàng của con trai Eùp-ra-im, theo số điểm kiểm của họ: ba mươi hai ngàn năm trăm người. Đó là con trai Giô-sép, theo các họ hàng của họ.'),
(4528, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 38, 'OT', 'Các con trai của Bên-gia-min, theo các họ hàng của họ: do Bê-la, họ hàng của người là họ Bê-la; do Aùch-bên, họ hàng của người là họ Aùch-bên; do A-chi-ram, họ hàng của người là họ A-chi-ram.'),
(4529, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 39, 'OT', 'do nơi Sê-phu-pham sanh ra họ Sê-phu-pham; do nơi Hu-pham sanh ra họ Hu-pham.'),
(4530, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 40, 'OT', 'Các con trai của Bê-la là A-rết và Na-a-man; dòng họ A-rết theo A-rết, dòng họ Na-a-man theo Na-a-man.'),
(4531, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 41, 'OT', 'Đó là các con trai của Bên-gia-min, theo các họ hàng của họ; số người được điểm danh là bốn mươi lăm ngàn sáu trăm người.'),
(4532, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 42, 'OT', 'Đây là các con trai của Đan theo các họ hàng của họ: theo dòng họ Su-cham, họ hàng của người Su-cham. Đó là các họ hàng của Đan theo các họ hàng của họ.'),
(4533, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 43, 'OT', 'Tất cả các họ hàng của người Su-cham, theo số người được điểm danh: sáu mươi bốn ngàn bốn trăm người.'),
(4534, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 44, 'OT', 'Các con trai của A-se, theo các họ hàng của họ: họ của Di-ma, theo dòng họ Di-ma; họ của Dích-vi, theo dòng họ Dích-vi; họ của Bê-ri-a, theo dòng họ Bê-ri-a.'),
(4535, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 45, 'OT', 'Các con trai của Bê-ri-a: do nơi Hê-be sanh ra dòng họ Hê-be; do nơi Manh-ki-ên sanh ra dòng họ Manh-ki-ên.'),
(4536, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 46, 'OT', 'Tên con gái của A-se là Sê-rách.'),
(4537, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 47, 'OT', 'Đó là các họ hàng của con trai A-se, theo số người được kiểm tra: năm mươi ba ngàn bốn trăm người.'),
(4538, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 48, 'OT', 'Con trai của Nép-ta-li theo các họ hàng của họ: về Giát-sê-ên, dòng họ Giát-sê-ên; về Gu-ni, dòng họ Gu-ni.'),
(4539, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 49, 'OT', 'do nơi Dít-se sanh ra họ Dít-se; do nơi Si-lem sanh ra họ Si-lem.'),
(4540, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 50, 'OT', 'Đó là các chi phái của Nép-ta-li, theo các chi phái của họ; và số người được kiểm tra là bốn mươi lăm ngàn bốn trăm người.'),
(4541, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 51, 'OT', 'Đây là những người được kiểm tra trong dân Y-sơ-ra-ên: sáu trăm ngàn, một ngàn bảy trăm ba mươi người.'),
(4542, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 52, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(4543, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 53, 'OT', 'Phải chia đất làm sản nghiệp cho những người nầy theo số các danh.'),
(4544, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 54, 'OT', 'Chi phái nào đông người thì phải tăng phần sản nghiệp của họ; chi phái nào ít người thì phải giảm phần sản nghiệp của họ; mỗi người sẽ được chia sản nghiệp theo số lượng những người được liệt kê trong họ.'),
(4545, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 55, 'OT', 'Nhưng phải bắt thăm mà chia đất ra; Y-sơ-ra-ên sẽ nhận phần sản nghiệp theo tên các chi phái tổ tiên mình.'),
(4546, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 56, 'OT', 'Phải chia sản nghiệp cho họ tùy theo sự bắt thăm, dù chi phái đông người hay ít người.'),
(4547, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 57, 'OT', 'Và đây là những người Lê-vi theo các họ hàng của họ: của Ghẹt-sôn, họ hàng Ghẹt-sôn; của Kê-hát, họ hàng Kê-hát; của Mê-ra-ri, họ hàng Mê-ra-ri.'),
(4548, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 58, 'OT', 'Đây là các họ Lê-vi: họ Líp-ni, họ Hếp-rôn, họ Mách-li, họ Mu-si, họ Cô-rê. Và Kê-hát sinh ra Am-ram.'),
(4549, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 59, 'OT', 'Tên vợ của Am-ram là Giô-kê-bết, con gái của Lê-vi, sinh ra cho Lê-vi tại Ai-cập; và nàng sinh cho Am-ram A-rôn, Môi-se và Mi-ri-am, chị của hai người.'),
(4550, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 60, 'OT', 'A-rôn sinh ra Na-đáp và A-bi-hu, Ê-lê-a-sa và Y-tha-ma.'),
(4551, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 61, 'OT', 'Na-đáp và A-bi-hu chết khi dâng lửa lạ trước mặt Đức Giê-hô-va.'),
(4552, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 62, 'OT', 'Tổng số người được kiểm tra trong các cuộc kiểm tra của họ là hai mươi ba ngàn, tất cả đều là nam giới từ một tháng tuổi trở lên; vì người Lê-vi không được kiểm tra giữa các con trai Y-sơ-ra-ên, bởi Đức Giê-hô-va đã không ban cho họ sản nghiệp giữa các con trai Y-sơ-ra-ên.'),
(4553, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 63, 'OT', 'Đó là những cuộc kiểm tra dân số mà Môi-se và thầy tế lễ Ê-lê-a-xa đã thực hiện đối với con cái Y-sơ-ra-ên, tại các đồng bằng Mô-áp, bên bờ sông Giô-đanh, đối diện Giê-ri-cô.'),
(4554, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 64, 'OT', 'Trong những người nầy không có một người nào thuộc về bọn được Môi-se và A-rôn, thầy tế lễ, kiểm tra khi hai người kiểm tra con cái Y-sơ-ra-ên tại đồng vắng Si-na-i.'),
(4555, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 26, 65, 'OT', 'Vì Đức Giê-hô-va phán về họ rằng: Họ sẽ chết trong đồng vắng! Và không một người nào trong bọn họ được còn sống, ngoại trừ Ca-lép con trai Giê-phu-nê và Giô-suê con trai Nun.'),
(4556, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 27, 1, 'OT', 'Các con gái của Xê-lô-phát, con trai của Hê-phe, cháu trai của Ga-la-át, chắt trai của Ma-ki, chít trai của Ma-na-se, thuộc các họ hàng của Ma-na-se, con trai của Giô-sép, đã đến gần; và đây là tên các con gái của người: Mách-la, Nô-a, Hốt-la, Minh-ca và Thiệt-sa.'),
(4557, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 27, 2, 'OT', 'Các con gái của Xê-lô-phát đứng trước mặt Môi-se, trước mặt Ê-lê-a-sa thầy tế lễ, trước mặt các quan trưởng và toàn thể hội chúng, tại cửa nhà hội, mà thưa rằng:'),
(4558, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 27, 3, 'OT', 'Cha chúng tôi chết trong đồng vắng, và ông không ở giữa hội chúng đã họp lại nghịch cùng Đức Giê-hô-va trong phe đảng Cô-rê; nhưng ông chết vì tội mình, và không có con trai cho ông.'),
(4559, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 27, 4, 'OT', 'Tại sao danh cha chúng tôi lại bị trừ khỏi giữa vòng họ hàng người, vì người không có con trai? Xin hãy ban cho chúng tôi một phần sản nghiệp giữa anh em của cha chúng tôi.'),
(4560, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 27, 5, 'OT', 'Môi-se đem vụ án ấy đến trước mặt Đức Giê-hô-va.'),
(4561, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 27, 6, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(4562, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 27, 7, 'OT', 'Các con gái Xê-lô-phát nói phải; phải ban cho chúng nó một phần sản nghiệp giữa các anh em của cha chúng nó, và phải chuyển sản nghiệp của cha chúng nó sang cho chúng nó.'),
(4563, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 27, 8, 'OT', 'Ngươi cũng phải nói cùng các con của Y-sơ-ra-ên rằng: Nếu một người chết mà không có con trai, thì các ngươi phải chuyển sản nghiệp của người ấy cho con gái người ấy.'),
(4564, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 27, 9, 'OT', 'Nếu người ấy không có con gái, thì các ngươi phải trao sản nghiệp của người ấy cho các anh em người ấy.'),
(4565, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 27, 10, 'OT', 'Nếu người ấy không có anh em trai, thì phải trao cơ nghiệp của người ấy cho các anh em của cha người ấy.'),
(4566, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 27, 11, 'OT', 'Nếu cha người đó không có anh em, thì các ngươi phải trao sản nghiệp người đó cho người bà con gần gũi nhất thuộc cùng một gia tộc với người ấy, và người ấy sẽ hưởng lấy; điều này sẽ làm luật lệ về xét xử cho con cái Y-sơ-ra-ên, y như Đức Giê-hô-va đã truyền cho Môi-se.'),
(4567, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 27, 12, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Hãy lên núi A-ba-rim nầy và nhìn xem xứ mà ta đã ban cho con cái Y-sơ-ra-ên.'),
(4568, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 27, 13, 'OT', 'Ngươi sẽ nhìn thấy xứ đó, rồi ngươi cũng sẽ được thu về cùng tổ tiên ngươi, như A-rôn, anh ngươi, đã được thu về vậy.'),
(4569, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 27, 14, 'OT', 'vì các ngươi đã không vâng lời Ta tại đồng vắng Xin, trong sự tranh tụng của hội chúng, và vì trước mặt chúng nó, các ngươi không thánh hóa Ta về việc nước. Ấy là các nước về sự tranh tụng tại Ca-đe, trong đồng vắng Xin.'),
(4570, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 27, 15, 'OT', 'Môi-se thưa cùng Đức Giê-hô-va rằng:'),
(4571, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 27, 16, 'OT', 'Xin Giê-hô-va là Đức Chúa Trời của các thần linh mọi loài xác thịt, lập một người trên hội chúng'),
(4572, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 27, 17, 'OT', 'để ra trước mặt chúng nó và vào trước mặt chúng nó, để dẫn chúng nó ra và dẫn chúng nó vào, hầu cho hội chúng của Đức Giê-hô-va không như chiên không có người chăn.'),
(4573, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 27, 18, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Hãy đem Giô-suê con trai của Nun, một người có thần trong mình, và đặt tay ngươi trên người ấy.'),
(4574, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 27, 19, 'OT', 'Hãy đặt người ấy đứng trước mặt Ê-lê-a-sa, thầy tế lễ, và trước toàn thể hội chúng, rồi truyền lệnh cho người trước mặt họ.'),
(4575, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 27, 20, 'OT', 'Và ngươi hãy trao phần oai nghi của mình cho người, hầu cho toàn thể hội chúng Y-sơ-ra-ên nghe người.'),
(4576, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 27, 21, 'OT', 'Giô-suê phải đứng trước mặt Ê-lê-a-xa, thầy tế lễ, và người ấy sẽ cầu hỏi Đức Giê-hô-va về sự xét đoán của các U-rim. Theo lời người ấy, Giô-suê và toàn thể con cái Y-sơ-ra-ên cùng toàn thể hội chúng sẽ ra đi và trở về.'),
(4577, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 27, 22, 'OT', 'Môi-se làm y như Đức Giê-hô-va đã truyền dặn mình, bèn dẫn Giô-suê đến, đặt người trước mặt thầy tế lễ Ê-lê-a-sa và trước mặt toàn thể hội chúng.'),
(4578, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 27, 23, 'OT', 'Môi-se đặt tay mình trên người và truyền lệnh cho người, y như Đức Giê-hô-va đã phán dạy qua tay Môi-se.'),
(4579, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 28, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(4580, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 28, 2, 'OT', 'Hãy truyền cho dân Y-sơ-ra-ên và nói với họ: Các ngươi phải giữ các lễ vật của ta, lương thực của ta, là của lễ dùng lửa dâng lên, có mùi thơm vừa lòng ta, để dâng cho ta đúng kỳ lễ định kỳ.'),
(4581, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 28, 3, 'OT', 'Vậy, ngươi phải nói cùng họ rằng: Đây là của lễ thiêu dùng lửa mà các ngươi sẽ dâng cho Đức Giê-hô-va: mỗi ngày hai chiên con đực một tuổi, không tật, làm của lễ thiêu hằng hiến.'),
(4582, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 28, 4, 'OT', 'Con chiên con thứ nhất, ngươi phải dâng vào buổi sáng; con chiên con thứ hai, ngươi phải dâng giữa chiều tối.'),
(4583, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 28, 5, 'OT', 'và một phần mười e-pha bột mịn làm lễ chay, trộn với dầu ô-liu ép, một phần tư hin.'),
(4584, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 28, 6, 'OT', 'Là của lễ thiêu hằng định, đã làm trên núi Si-na-i làm của lễ dùng lửa, có mùi thơm dâng cho Đức Giê-hô-va.'),
(4585, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 28, 7, 'OT', 'Lễ quán sẽ là một phần tư hin rượu cho mỗi chiên con; ngươi phải đổ lễ quán bằng rượu cho Đức Giê-hô-va trong nơi thánh.'),
(4586, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 28, 8, 'OT', 'Chiên con thứ hai, ngươi phải dâng giữa chiều tối; ngươi phải dâng của lễ chay và lễ quán như của lễ buổi sáng; làm của lễ dùng lửa, mùi thơm vừa lòng Đức Giê-hô-va.'),
(4587, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 28, 9, 'OT', 'Vào ngày Sa-bát, hai chiên con đực trọn một tuổi, không tật bệnh, và hai phần mười ếpha bột lọc, làm lễ chay trộn dầu, cùng với lễ quán của nó.'),
(4588, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 28, 10, 'OT', 'Lễ thiêu về ngày Sa-bát, mỗi ngày Sa-bát, phải dâng thêm trên lễ thiêu hằng hiến và của lễ đi kèm theo nó.'),
(4589, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 28, 11, 'OT', 'Vào các ngày đầu tháng, các ngươi phải dâng của lễ thiêu cho Đức Giê-hô-va: hai con bò đực, một con chiên đực, bảy con chiên con một tuổi, không tật nguyền.'),
(4590, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 28, 12, 'OT', 'ba phần mười ế-pha bột mịn làm lễ vật chay, trộn với dầu, cho mỗi con bò đực; hai phần mười ế-pha bột mịn làm lễ vật chay, trộn với dầu, cho mỗi con chiên đực;'),
(4591, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 28, 13, 'OT', 'Mười phần mười ơ-phah bột mịn trộn dầu, dùng làm lễ vật chay cho mỗi con chiên cái, của lễ thiêu, mùi thơm vừa lòng, lễ vật bằng lửa dâng cho Đức Giê-hô-va.'),
(4592, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 28, 14, 'OT', 'Lễ quán sẽ là nửa hin rượu về con bò, một phần ba hin về con chiên đực, và một phần tư hin về con chiên con. Đó là của lễ thiêu về các tháng trong năm, từng tháng theo kỳ nó.'),
(4593, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 28, 15, 'OT', 'và một con dê đực làm của lễ chuộc tội cho Đức Giê-hô-va, phải dâng ngoài của lễ thiêu hằng hiến và của lễ quán theo nó.'),
(4594, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 28, 16, 'OT', 'Ngày mười bốn tháng giêng, phải giữ lễ Vượt-qua cho Đức Giê-hô-va.'),
(4595, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 28, 17, 'OT', 'Vào ngày mười lăm của tháng này, sẽ có lễ; phải ăn bánh không men trong bảy ngày.'),
(4596, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 28, 18, 'OT', 'Ngày đầu tiên sẽ là ngày hội thánh; các ngươi không được làm bất cứ công việc phục vụ nào.'),
(4597, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 28, 19, 'OT', 'Các ngươi phải dâng cho Đức Giê-hô-va của lễ thiêu, hai con bò đực, một con chiên đực, và bảy chiên con đực giáp một năm, phải không tật nguyền, thì các ngươi sẽ được chấp nhận.'),
(4598, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 28, 20, 'OT', 'của lễ chay bằng bột lọc trộn dầu: các ngươi phải dâng ba phần mười ế-pha cho mỗi con bò tơ, và hai phần mười ế-pha cho mỗi con chiên đực,'),
(4599, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 28, 21, 'OT', 'Một phần mười ế-pha cho mỗi con chiên, cho bảy con chiên.'),
(4600, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 28, 22, 'OT', 'và một con dê đực làm của lễ chuộc tội, để làm lễ chuộc tội cho các ngươi.'),
(4601, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 28, 23, 'OT', 'Ngoài của lễ thiêu buổi sáng, là của lễ thiêu hằng định, các ngươi phải dâng những lễ vật nầy.'),
(4602, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 28, 24, 'OT', 'Các ngươi phải làm như thế mỗi ngày trong bảy ngày, làm của lễ dùng lửa dâng lên, có mùi thơm cho Đức Giê-hô-va; phải dâng của lễ thiêu ấy ngoài của lễ thiêu hằng hiến và của lễ quán đi kèm theo nó.'),
(4603, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 28, 25, 'OT', 'Ngày thứ bảy sẽ là ngày nhóm họp thánh cho các ngươi; mọi công việc làm chẳng được làm.'),
(4604, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 28, 26, 'OT', 'Vào ngày lễ các trái đầu mùa, khi các ngươi dâng cho Đức Giê-hô-va của lễ chay mới trong các ngày lễ Ngũ tuần của các ngươi, thì phải có một sự nhóm họp thánh dành cho các ngươi; mọi công việc lao động không được làm.'),
(4605, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 28, 27, 'OT', 'Các ngươi sẽ dâng của lễ thiêu làm mùi thơm đẹp lòng Đức Giê-hô-va: hai con bò đực, một con chiên đực, và bảy chiên con đực giáp năm.'),
(4606, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 28, 28, 'OT', 'của lễ chay là bột lọc trộn dầu, ba phần mười ê-pha cho mỗi con bò đực, hai phần mười ê-pha cho mỗi con chiên đực,'),
(4607, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 28, 29, 'OT', 'mười phần mười ê-pha cho mỗi con chiên, cho bảy con chiên;'),
(4608, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 28, 30, 'OT', 'một con dê đực làm của lễ chuộc tội cho các ngươi.'),
(4609, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 28, 31, 'OT', 'Ngoài của lễ thiêu hằng hiến và lễ chay của nó, các ngươi phải dâng các lễ vật ấy; chúng phải không tật tật cho các ngươi, và cả lễ quán của chúng nữa.'),
(4610, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 1, 'OT', 'Vào tháng bảy, ngày mồng một tháng, các ngươi sẽ có một ngày hội thánh; các ngươi không được làm bất cứ công việc phục vụ nào; ấy sẽ là một ngày các ngươi thổi kèn.'),
(4611, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 2, 'OT', 'Các ngươi phải dâng làm của lễ thiêu có mùi thơm cho Đức Giê-hô-va một con bò đực tơ, một con chiên đực, bảy chiên con đực giáp năm, không tì vít.'),
(4612, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 3, 'OT', 'của lễ chay bằng bột lọc nhồi dầu, ba phần mười ếpha cho mỗi con bò đực, hai phần mười ếpha cho mỗi con chiên đực,'),
(4613, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 4, 'OT', 'một phần mười ê-pha để dâng cho mỗi con chiên con, cho bảy con chiên con;'),
(4614, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 5, 'OT', 'và một con dê đực làm của lễ chuộc tội, để làm lễ chuộc tội cho các ngươi;'),
(4615, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 6, 'OT', 'Ngoài của lễ thiêu về ngày mồng một tháng, cùng của lễ chay và của lễ thiêu hằng hiến với của lễ chay cặp theo, và các lễ quán đi kèm theo đúng qui định của chúng, để dâng làm của lễ dùng lửa, có mùi thơm cho Đức Giê-hô-va.'),
(4616, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 7, 'OT', 'Ngày mùng mười tháng bảy nầy, các ngươi sẽ có một ngày hội thánh; phải ép tâm thần mình ra, chớ làm bất cứ công việc nào.'),
(4617, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 8, 'OT', 'Các ngươi phải dâng lên Đức Giê-hô-va của lễ thiêu, làm mùi thơm vừa lòng Ngài: một con bò đực tơ, một con chiên đực, và bảy chiên con đực, mỗi chiên một tuổi, phải không tì vít.'),
(4618, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 9, 'OT', 'Lễ vật chay của chúng, bằng bột lọc trộn dầu, là ba phần mười ếch-sa cho mỗi con bò đực, hai phần mười ếch-sa cho mỗi con chiên đực.'),
(4619, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 10, 'OT', 'một phần mười ê-pha cho mỗi con chiên con, cho bảy con chiên con.'),
(4620, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 11, 'OT', 'Một con dê đực làm của lễ chuộc tội, ngoài của lễ chuộc tội trong ngày lễ chuộc tội, và của lễ thiêu hằng ngày, cùng với của lễ chay và các lễ quán của nó.'),
(4621, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 12, 'OT', 'Vào ngày mười lăm tháng bảy, các ngươi sẽ có một sự nhóm họp thánh; không được làm bất cứ công việc nào; và các ngươi sẽ giữ lễ cho Đức Giê-hô-va trong bảy ngày.'),
(4622, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 13, 'OT', 'Các ngươi phải dâng làm của lễ thiêu, tức là của lễ thiêu dùng lửa có mùi thơm cho Đức Giê-hô-va, mười ba con bò đực tơ, hai con chiên đực, và mười bốn chiên con đực giáp năm, phải không tật tật.'),
(4623, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 14, 'OT', 'của lễ chay kèm theo là bột lọc trộn dầu, ba phần mười ê-pha cho mỗi con bò đực, cho mười ba con bò đực, hai phần mười ê-pha cho mỗi con chiên đực, cho hai con chiên đực'),
(4624, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 15, 'OT', 'và một phần mười ê-pha bột mịn cho mỗi con chiên, cho mười bốn con chiên con.'),
(4625, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 16, 'OT', 'Các ngươi cũng phải dâng một con dê đực làm của lễ chuộc tội, ngoài của lễ thiêu hằng hiến, của lễ chay và lễ quán của nó.'),
(4626, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 17, 'OT', 'Ngày thứ hai, phải dâng mười hai con bò đực tơ, hai con chiên đực, mười bốn chiên con đực giáp năm, không tì vết,'),
(4627, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 18, 'OT', 'với của lễ chay và các lễ quán về những con bò đực, chiên đực và chiên con, theo số lượng quy định theo luật lệ.'),
(4628, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 19, 'OT', 'và một con dê đực làm của lễ chuộc tội, ngoài của lễ thiêu hằng định cùng lễ vật tế kèm theo và các lễ libation của nó.'),
(4629, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 20, 'OT', 'Ngày thứ ba, phải dâng mười một con bò đực, hai con chiên đực, mười bốn chiên con đực một tuổi, không tật lỗi,'),
(4630, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 21, 'OT', 'và các lễ chay cùng các lễ quán của chúng dành cho những con bò đực, chiên đực và chiên con, theo số lượng quy định như luật lệ.'),
(4631, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 22, 'OT', 'Một con dê đực làm của lễ chuộc tội, ngoài của lễ thiêu luôn luôn, cùng với của lễ chay và lễ quán kèm theo.'),
(4632, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 23, 'OT', 'Ngày thứ tư, dâng mười con bò đực, hai con chiên đực, mười bốn chiên con đực một tuổi, không tật nguyền,'),
(4633, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 24, 'OT', 'Các lễ vật chay và lễ quán của chúng dành cho những con bò đực, những con chiên đực và những con chiên con, theo số lượng quy định theo luật lệ.'),
(4634, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 25, 'OT', 'Một con dê đực làm của lễ chuộc tội, ngoài của lễ thiêu hằng ngày cùng của lễ thực và lễ quán theo nó.'),
(4635, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 26, 'OT', 'Ngày thứ năm, phải dâng chín con bò đực, hai con chiên đực, mười bốn chiên con đực một tuổi, không tì vít,'),
(4636, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 27, 'OT', 'Và của lễ chay cùng các lễ quán dành cho những con bò đực, những con chiên đực và những con chiên con, theo số lượng quy định theo luật lệ.'),
(4637, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 28, 'OT', 'Một con dê đực làm của lễ chuộc tội, ngoài của lễ thiêu hằng định, cùng với lễ vật chay và lễ đồ uống của nó.'),
(4638, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 29, 'OT', 'Ngày thứ sáu, dâng tám con bò đực, hai con chiên đực, mười bốn chiên con đực giáp một năm, không tì vít,'),
(4639, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 30, 'OT', 'với của lễ chay và các lễ quán của chúng về những con bò tơ, những con chiên đực và những con chiên con, theo số lượng quy định.'),
(4640, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 31, 'OT', 'và một con dê đực làm của lễ chuộc tội, ngoài của lễ thiêu hằng hiến, lễ vật bằng bánh mì đi kèm và lễ quán của nó.'),
(4641, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 32, 'OT', 'Ngày thứ bảy, phải dâng bảy con bò đực, hai con chiên đực, mười bốn chiên con đực một tuổi, không tật,'),
(4642, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 33, 'OT', 'Các lễ vật chay và lễ quán của chúng về những con bò đực, những con chiên đực và những con chiên con, theo số lượng của chúng, theo qui tắc của chúng.'),
(4643, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 34, 'OT', 'và một con dê đực làm của lễ chuộc tội, ngoài của lễ thiêu thường ngày, cùng lễ vật bằng bánh mì và lễ đồ uống cặp theo.'),
(4644, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 35, 'OT', 'Ngày thứ tám, các ngươi phải có một buổi nhóm họp thánh; mọi công việc làm nghề nghiệp không được làm.'),
(4645, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 36, 'OT', 'phải dâng lên Đức Giê-hô-va của lễ thiêu, tức là của lễ dùng lửa dâng lên có mùi thơm cho Đức Giê-hô-va: một con bò đực, một con chiên đực, bảy chiên con đực giáp năm, không tì vít,'),
(4646, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 37, 'OT', 'của lễ chay và các lễ quán về con bò đực, con chiên đực và các chiên con, theo số lượng của chúng, như luật quy định.'),
(4647, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 38, 'OT', 'và một con dê đực làm của lễ chuộc tội, ngoài của lễ thiêu hằng hiến, cùng lễ vật bằng tế và lễ quán của nó.'),
(4648, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 39, 'OT', 'Các ngươi phải làm những lễ nầy cho Đức Giê-hô-va trong các ngày lễ của các ngươi, ngoài các lễ hứa nguyện và các lễ lạc ý của các ngươi, tức là các lễ thiêu, các lễ chay, các lễ quán, và các lễ thù ân của các ngươi.'),
(4649, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 29, 40, 'OT', 'Môi-se nói cùng con cái Y-sơ-ra-ên mọi điều mà Đức Giê-hô-va đã truyền cho Môi-se.'),
(4650, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 30, 1, 'OT', 'Môi-se nói cùng các trưởng tộc của các chi phái Y-sơ-ra-ên rằng: Đây là điều mà Đức Giê-hô-va đã truyền dạy:'),
(4651, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 30, 2, 'OT', 'Người đàn ông nào hứa một lời hứa cùng Đức Giê-hô-va, hoặc thề một lời thề để buộc mình vào một điều cấm, thì không được vi phạm lời mình; mọi điều ra khỏi miệng người ấy, người ấy phải làm.'),
(4652, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 30, 3, 'OT', 'Khi một người nữ, trong buổi còn thơ ấu, ở nhà cha mình, hứa một lời khấn cùng Đức Giê-hô-va và buộc mình giữ một lời hứa,'),
(4653, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 30, 4, 'OT', 'Nếu người cha nghe biết lời khấn nguyện của nàng và sự ràng buộc mà nàng đã tự buộc lấy trên chính mình, mà người cha làm thinh trước nàng, thì mọi lời khấn nguyện của nàng sẽ đứng vững, và mọi sự ràng buộc mà nàng đã tự buộc lấy trên chính mình sẽ được giữ vững.'),
(4654, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 30, 5, 'OT', 'Nếu cha nàng cản trở nàng trong ngày biết được điều đó, thì mọi lời hứa nguyện của nàng và mọi điều buộc lòng nàng đã tự cam kết trên linh hồn mình sẽ không có hiệu lực; và Đức Giê-hô-va sẽ tha thứ cho nàng, vì cha nàng đã cản trở nàng.'),
(4655, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 30, 6, 'OT', 'Nếu người phụ nữ ấy đã thuộc về một người chồng, thì lời hứa nguyện của nàng hoặc lời khấn mà môi nàng đã nói ra để tự ràng buộc mình, đều còn hiệu lực.'),
(4656, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 30, 7, 'OT', 'Nếu chồng nàng nghe được vào ngày nào đó mà không nói gì với nàng, thì các lời khấn của nàng sẽ đứng vững, và các lời hứa mà nàng đã buộc mình phải giữ sẽ được giữ.'),
(4657, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 30, 8, 'OT', 'Nếu ngày nào chồng nàng nghe biết mà cấm đoán nàng, thì người ấy sẽ hủy bỏ lời khấn nguyện mà nàng đã khấn và lời nào lỡ ra khỏi môi miệng, khiến nàng buộc mình vào, và Đức Giê-hô-va sẽ tha thứ cho nàng.'),
(4658, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 30, 9, 'OT', 'Lời hứa nguyện của một người đàn bà goá hoặc một người bị ruồng bỏ, mọi điều chi người ấy đã buộc mình, thì phải lập tức có hiệu lực đối với người ấy.'),
(4659, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 30, 10, 'OT', 'Nếu người đàn bà hứa nguyện, hoặc thề hứa kiêng cữ điều gì trong nhà chồng mình,'),
(4660, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 30, 11, 'OT', 'Nếu chồng nàng nghe được mà làm thinh, không ngăn cản nàng, thì mọi lời hứa nguyện của nàng và mọi điều buộc lòng mà nàng đã tự cam kết trên mình sẽ được giữ vững.'),
(4661, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 30, 12, 'OT', 'Nếu chồng nàng hủy bỏ các lời ấy vào ngày nào người ấy hay biết, thì mọi lời phát ra từ môi nàng về những lời hứa nguyện và về những điều buộc lòng mình sẽ không còn hiệu lực; chồng nàng đã hủy bỏ các lời ấy, và Đức Giê-hô-va sẽ tha thứ cho nàng.'),
(4662, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 30, 13, 'OT', 'Mọi lời hứa nguyện và mọi lời thề kiêng cữ mà ép lấy linh hồn, chồng nàng sẽ xác nhận thì lời ấy được giữ vững, chồng nàng sẽ hủy bỏ thì lời ấy bị huỷ bỏ.'),
(4663, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 30, 14, 'OT', 'Nếu chồng làm thinh, không nói gì với nàng từ ngày này sang ngày khác, thì mọi lời khấn của nàng và mọi lời thề ràng buộc nàng đều được xác nhận; ấy là vì chồng đã làm thinh không phản đối nàng trong ngày ông nghe biết.'),
(4664, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 30, 15, 'OT', 'Nếu người chồng hủy bỏ các điều đó sau khi đã nghe biết, thì người ấy sẽ mang tội lỗi của vợ mình.'),
(4665, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 30, 16, 'OT', 'Đó là những điều luật mà Đức Giê-hô-va đã truyền cho Môi-se về mối liên hệ giữa người chồng với vợ mình, giữa người cha với con gái mình, trong lúc còn trẻ tuổi ở nhà cha.'),
(4666, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(4667, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 2, 'OT', 'Hãy báo sự báo thù của con cái Y-sơ-ra-ên đối với Ma-đi-an; sau đó ngươi sẽ được thu về cùng dân ngươi.'),
(4668, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 3, 'OT', 'Môi-se nói với dân sự rằng: "Hỡi các ngươi, hãy biệt riêng những người trong các ngươi ra để ra trận, chống lại dân Ma-đi-an, để thực hiện sự báo thù của Đức Giê-hô-va trên dân Ma-đi-an."'),
(4669, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 4, 'OT', 'Mỗi chi phái Y-sơ-ra-ên phải sai một ngàn người ra trận.'),
(4670, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 5, 'OT', 'Vậy, từ các ngàn người của Y-sơ-ra-ên, mỗi chi phái một ngàn, chọn ra mười hai ngàn người tinh nhuệ đã sẵn sàng ra chiến trận.'),
(4671, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 6, 'OT', 'Môi-se sai họ đi, mỗi chi phái một ngàn người ra trận, cùng với Phi-nê-a, con trai của Ê-lê-a-sa, thầy tế lễ, và đem theo các khí cụ thánh cùng chiếc kèn báo hiệu chiến trận trong tay người.'),
(4672, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 7, 'OT', 'Chúng đóng quân nghịch cùng dân Ma-đi-an, y như Đức Giê-hô-va đã truyền cho Môi-se, và giết hết mọi người nam.'),
(4673, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 8, 'OT', 'Chúng giết các vua Ma-đi-an trên những người đã bị giết của chúng, ấy là Ê-vi, Rê-kem, Xu-rơ, Hu-rơ và Rê-ba, năm vua Ma-đi-an; và chúng cũng giết Ba-la-am, con trai của Bê-ô, bằng gươm.'),
(4674, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 9, 'OT', 'Con cái Y-sơ-ra-ên bắt các phụ nữ Ma-đi-an và con trẻ chúng, cướp lấy tất cả súc vật, tất cả gia súc và mọi của cải chúng, lấy làm chiến lợi phẩm.'),
(4675, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 10, 'OT', 'Họ đốt các thành của chúng, mọi nơi ở và mọi nơi đậu của chúng bằng lửa.'),
(4676, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 11, 'OT', 'Họ lấy tất cả những của cải chiến lợi phẩm, cả người lẫn súc vật.'),
(4677, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 12, 'OT', 'Họ dẫn những kẻ bị bắt, của chiến lợi phẩm và của cướp được đến cho Môi-se, cho Ê-lê-a-sa thầy tế lễ và cho hội chúng Y-sơ-ra-ên, đến trại quân tại các đồng bằng Mô-áp, bên sông Giô-đanh, đối ngang Giê-ri-cô.'),
(4678, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 13, 'OT', 'Môi-se cùng với Ê-lê-a-sa thầy tế lễ và tất cả các quan trưởng của hội chúng đi ra ngoài trại đón họ.'),
(4679, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 14, 'OT', 'Môi-se nổi giận cùng các viên chỉ huy quân đội, các quan trưởng ngàn người và các quan trưởng trăm người, là những người trở về từ cuộc chiến.'),
(4680, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 15, 'OT', 'Môi-se nói cùng họ rằng: Các ngươi để cho tất cả những người nữ sống sao?'),
(4681, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 16, 'OT', 'Kìa, chính chúng đã theo mưu kế của Ba-la-am mà khiến con cái Y-sơ-ra-ên phạm tội bất trung cùng Đức Giê-hô-va qua việc thờ phụng Phê-ô, và tai họa đã xảy đến trong hội chúng của Đức Giê-hô-va.'),
(4682, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 17, 'OT', 'Vậy bây giờ, hãy giết hết thảy con trai nhỏ trong vòng con trẻ, và giết mọi người nữ đã biết đến người nam trong sự nằm cùng nhau;'),
(4683, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 18, 'OT', 'Còn hết thảy các trẻ nhỏ là nữ, những kẻ chưa biết đến sự nằm cùng người nam, thì hãy để cho các ngươi sống.'),
(4684, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 19, 'OT', 'Còn các ngươi, hãy ở ngoài trại quân bảy ngày; hễ ai giết người và ai đụng đến xác chết, thì phải làm cho mình được sạch vào ngày thứ ba và ngày thứ bảy, cả các ngươi lẫn những kẻ bị bắt theo các ngươi.'),
(4685, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 20, 'OT', 'Mọi thứ áo xống, mọi vật dụng bằng da, mọi vật dụng bằng lông dê, và mọi đồ dùng bằng gỗ, các ngươi phải làm cho sạch.'),
(4686, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 21, 'OT', 'Ê-lê-a-sa, thầy tế lễ, nói với những người lính đã ra trận rằng: "Đây là điều răn của luật pháp mà Đức Giê-hô-va đã truyền cho Môi-se:'),
(4687, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 22, 'OT', 'chỉ vàng, bạc, đồng, sắt, thiếc và chì,'),
(4688, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 23, 'OT', 'Mọi vật gì chịu được lửa thì phải đưa qua lửa, rồi sẽ được tinh sạch, nhưng phải tẩy uế bằng nước tẩy uế; còn mọi vật gì không đưa qua lửa được thì phải đưa qua nước.'),
(4689, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 24, 'OT', 'Vào ngày thứ bảy, các ngươi phải giặt quần áo mình, rồi sẽ được sạch; sau đó mới được vào trại.'),
(4690, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 25, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(4691, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 26, 'OT', 'Ngươi và Ê-lê-a-xa thầy tế lễ, cùng các tộc trưởng của hội chúng, hãy kiểm tra số người và súc vật trong số những kẻ bị bắt làm tù binh.'),
(4692, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 27, 'OT', 'Hãy chia phần chiến lợi phẩm giữa những người ra trận đã đi ra chiến trận và giữa toàn thể hội chúng.'),
(4693, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 28, 'OT', 'Đức Giê-hô-va phán: Từ phần của những người ra trận, tức những người đã đi ra chiến trận, hãy lấy một phần năm trăm, từ người, từ bò, từ lừa và từ chiên, để nộp cho Đức Giê-hô-va.'),
(4694, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 29, 'OT', 'Hãy lấy từ phân nửa của chúng, và nộp cho Ê-lê-a-xa, thầy tế lễ, làm lễ vật dâng cho Đức Giê-hô-va.'),
(4695, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 30, 'OT', 'Và từ phân nửa của dân Y-sơ-ra-ên, ngươi phải lấy một phần năm mươi, từ người, từ bò, từ lừa và từ chiên, tức là từ mọi súc vật, rồi giao chúng cho người Lê-vi, những kẻ giữ nhiệm vụ canh giữ đền tạm của Đức Giê-hô-va.'),
(4696, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 31, 'OT', 'Môi-se và Ê-lê-a-sa thầy tế lễ làm y như Đức Giê-hô-va đã truyền cho Môi-se.'),
(4697, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 32, 'OT', 'Và số của cướp còn lại mà quân đội đã chiếm được là sáu trăm bảy mươi lăm ngàn con chiên.'),
(4698, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 33, 'OT', 'và bò cái, bảy mươi hai ngàn con,'),
(4699, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 34, 'OT', 'sáu mươi mốt ngàn con lừa đực.'),
(4700, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 35, 'OT', 'Các người nữ chưa biết đến người nam, tất cả là ba vạn hai ngàn người.'),
(4701, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 36, 'OT', 'Phần phân nửa thuộc về những người ra trận, là ba trăm ba mươi bảy ngàn năm trăm chiên.'),
(4702, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 37, 'OT', 'Số con chiên phải đóng làm thuế cho Đức Giê-hô-va là sáu trăm bảy mươi lăm con.'),
(4703, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 38, 'OT', 'ba mươi sáu ngàn con bò, và thuế đóng cho Đức Giê-hô-va là bảy mươi hai con;'),
(4704, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 39, 'OT', 'ba mươi ngàn năm trăm con lừa, và thuế nộp cho Đức Giê-hô-va là một phần sáu mươi.'),
(4705, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 40, 'OT', 'mười sáu ngàn người, và tiền chuộc cho Đức Giê-hô-va là ba mươi hai người.'),
(4706, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 41, 'OT', 'Môi-se đưa phần thuế dành riêng cho Đức Giê-hô-va mà dâng cho Ê-lê-a-sa thầy tế lễ, y như Đức Giê-hô-va đã truyền cho Môi-se.'),
(4707, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 42, 'OT', 'Và từ phân nửa của dân Y-sơ-ra-ên, là phần mà Môi-se đã chia ra từ những người lính ra trận,'),
(4708, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 43, 'OT', 'Phần phân nửa của hội chúng từ các chiên cái là ba trăm ba mươi ngàn, bảy ngàn và năm trăm con.'),
(4709, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 44, 'OT', 'ba mươi sáu ngàn con bò,'),
(4710, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 45, 'OT', 'ba mươi ngàn năm trăm con lừa,'),
(4711, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 46, 'OT', 'và linh hồn người là mười sáu ngàn.'),
(4712, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 47, 'OT', 'Môi-se lấy từ phân nửa của dân Y-sơ-ra-ên một phần năm mươi, một người hay một con vật, và trao cho những người Lê-vi giữ chức canh giữ đền tạm Đức Giê-hô-va, y như Đức Giê-hô-va đã truyền cho Môi-se.'),
(4713, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 48, 'OT', 'Các quan trưởng, là những người chỉ huy ngàn người và những người chỉ huy trăm người, đến gần Môi-se.'),
(4714, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 49, 'OT', 'Các tôi tớ ông thưa với Môi-se rằng: Tôi tớ ông đã kiểm tra số người chiến đấu dưới quyền chúng tôi, và không một người nào trong số họ bị thiếu.'),
(4715, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 50, 'OT', 'Chúng tôi xin dâng lễ vật cho Đức Giê-hô-va, mỗi người tùy theo những đồ bằng vàng mình đã tìm được, như vòng đeo cổ, vòng tay, nhẫn, bông tai và kiềng, để chuộc tội cho linh hồn chúng tôi trước mặt Đức Giê-hô-va.'),
(4716, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 51, 'OT', 'Môi-se và Ê-lê-a-xa thầy tế lễ nhận lấy vàng từ họ, mọi thứ đồ bằng vàng, mỗi vật làm ra đều là đồ chạm.'),
(4717, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 52, 'OT', 'Tất cả vàng về lễ vật mà các quan trưởng ngàn quân và các quan trưởng trăm quân dâng cho Đức Giê-hô-va là mười sáu ngàn bảy trăm năm mươi siếc-lơ.'),
(4718, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 53, 'OT', 'Các người lính đã cướp lấy của cải, mỗi người cho mình.'),
(4719, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 31, 54, 'OT', 'Vậy Môi-se và Ê-lê-a-sa thầy tế lễ nhận lấy vàng từ tay các quan trưởng ngàn người và trăm người, rồi đem vào nhà hội làm kỷ niệm cho con cái Y-sơ-ra-ên trước mặt Đức Giê-hô-va.'),
(4720, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 1, 'OT', 'Các con cháu của Ru-bên và các con cháu của Gát có rất nhiều súc vật; họ thấy xứ Gia-ê-xe và xứ Ga-la-át, thì thấy rằng nơi ấy là nơi thích hợp cho việc chăn nuôi súc vật.'),
(4721, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 2, 'OT', 'Các con trai của Gát và các con trai của Ru-bên đến thưa cùng Môi-se, cùng Ê-lê-a-sa thầy tế lễ, và các lãnh tụ hội chúng mà rằng:'),
(4722, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 3, 'OT', 'A-ta-rốt, Đi-bôn, Gia-ê-xe, Nim-ra, Hết-bôn, Ê-lê-a-lê, Sê-bam, Nê-bô và Bê-ôn'),
(4723, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 4, 'OT', 'Xứ mà Đức Giê-hô-va đã đánh bại trước mặt hội chúng Y-sơ-ra-ên, là một xứ tiện nuôi súc vật, và các tôi tớ ông có súc vật.'),
(4724, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 5, 'OT', 'Họ thưa: Nếu chúng tôi được ơn trước mặt ngài, xin hãy ban vùng đất nầy cho các đầy tớ ngài làm sản nghiệp; chớ dẫn chúng tôi qua sông Giô-đanh.'),
(4725, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 6, 'OT', 'Môi-se nói với con cái của Gát và con cái của Ru-bên: "Anh em các ngươi sẽ đi ra chiến trận, còn các ngươi thì ngồi đây sao?"'),
(4726, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 7, 'OT', 'Vì sao các ngươi khiến lòng con cái Y-sơ-ra-ên ngã lòng, không chịu đi qua đất mà Đức Giê-hô-va đã ban cho chúng?'),
(4727, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 8, 'OT', 'Chính như vậy tổ tiên các ngươi đã làm, khi Ta sai họ từ Ca-đe-Ba-nê-a đi xem xét xứ.'),
(4728, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 9, 'OT', 'Khi tổ tiên các ngươi lên đến khe Eách-côn, thấy xứ đó, bèn làm cho lòng con cái Y-sơ-ra-ên nản chí, không dám vào xứ mà Đức Giê-hô-va đã ban cho họ.'),
(4729, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 10, 'OT', 'Trong ngày ấy, cơn thịnh nộ của Đức Giê-hô-va nổi phừng lên, và Ngài thề rằng:'),
(4730, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 11, 'OT', 'Những người từ hai mươi tuổi trở lên, là những người đã lên từ xứ Ai Cập, sẽ chẳng thấy đất mà Ta đã thề ban cho Aùp-ra-ham, Y-sác và Gia-cốp, vì họ không trung thành đi theo Ta.'),
(4731, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 12, 'OT', 'trừ ra Ca-lép, con trai của Giê-phu-nê, người Kê-nít, và Giô-suê, con trai của Nun; vì hai người ấy đã trung thành theo Đức Giê-hô-va.'),
(4732, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 13, 'OT', 'Đức Giê-hô-va nổi giận cùng Y-sơ-ra-ên, khiến họ lưu lạc trong đồng vắng bốn mươi năm, cho đến khi cả thế hệ làm điều ác trước mặt Đức Giê-hô-va đều chết hết.'),
(4733, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 14, 'OT', 'Nầy, các ngươi dấy lên thế chỗ tổ phụ mình, là dòng dõi những người có tội, để gia tăng cơn thịnh nộ của Đức Giê-hô-va đối cùng Y-sơ-ra-ên nữa.'),
(4734, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 15, 'OT', 'Nếu các ngươi trở lại, rời khỏi Ngài, thì Ngài sẽ lại để dân ấy ở trong đồng vắng, và các ngươi sẽ làm hư mất toàn thể dân này.'),
(4735, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 16, 'OT', 'Chúng đến gần Môi-se và nói: Chúng tôi sẽ xây chuồng cho súc vật của chúng tôi tại đây, và thành cho con trẻ chúng tôi.'),
(4736, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 17, 'OT', 'Và chúng tôi sẽ cầm khí giới vội vã đi trước mặt con cái Y-sơ-ra-ên, cho đến khi nào dẫn họ vào nơi chỉ định của họ; còn con trẻ chúng tôi sẽ ở trong các thành có vách thành vững chắc, vì cớ những dân cư trong xứ.'),
(4737, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 18, 'OT', 'Chúng tôi sẽ không trở về nhà mình cho đến khi các con trai Y-sơ-ra-ên mỗi người nhận được sản nghiệp của mình.'),
(4738, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 19, 'OT', 'Vì chúng tôi sẽ không được hưởng phần cùng họ bên kia sông Giô-đanh và xa hơn, vì phần sản nghiệp của chúng tôi đã về chúng tôi bên này sông Giô-đanh về phía đông.'),
(4739, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 20, 'OT', 'Môi-se nói với họ rằng: Nếu các ngươi làm điều nầy, nếu mặc áo giáp ra đi chiến trận trước mặt Đức Giê-hô-va,'),
(4740, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 21, 'OT', 'Mọi người cầm binh khí phải đi qua sông Giô-đanh trước mặt Đức Giê-hô-va, cho đến khi nào Ngài đuổi các kẻ thù khỏi trước mặt Ngài.'),
(4741, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 22, 'OT', 'Và nếu xứ được chinh phục trước mặt Đức Giê-hô-va, rồi sau đó các ngươi mới trở về, thì các ngươi sẽ được xem là vô tội trước Đức Giê-hô-va và trước Y-sơ-ra-ên; và đất nầy sẽ thuộc về các ngươi làm sản nghiệp trước mặt Đức Giê-hô-va.'),
(4742, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 23, 'OT', 'Nếu các ngươi không làm như vậy, thì nầy, các ngươi sẽ phạm tội cùng Đức Giê-hô-va, và hãy biết rằng tội các ngươi sẽ tìm đến các ngươi.'),
(4743, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 24, 'OT', 'Hãy xây thành cho con cái các ngươi, và làm hàng rào giữ chiên bò các ngươi; còn điều gì các ngươi đã nói ra từ miệng mình, thì phải làm cho trọn.'),
(4744, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 25, 'OT', 'Con cháu Gát và con cháu Ru-bên thưa cùng Môi-se rằng: Các tôi tớ ngài sẽ làm như điều mà chúa tôi truyền dạy.'),
(4745, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 26, 'OT', 'Con trẻ và vợ chúng tôi, gia súc và tất cả súc vật của chúng tôi sẽ ở tại các thành xứ Ga-la-át;'),
(4746, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 27, 'OT', 'Còn các tôi tớ của ông sẽ cầm khí giới, tất cả những người tinh nhuệ ra trận, đi qua trước mặt Đức Giê-hô-va để chiến đấu, y như điều mà chúa tôi đã nói.'),
(4747, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 28, 'OT', 'Môi-se truyền lịnh cho Ê-lê-a-sa thầy tế lễ, cho Giô-suê con trai của Nun, và cho các trưởng tộc của các chi phái dân Y-sơ-ra-ên.'),
(4748, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 29, 'OT', 'Môi-se nói với họ rằng: Nếu con cháu Gát và con cháu Ru-bên cùng đi với các ngươi qua sông Giô-đanh, tất cả những người lính chiến đi trước mặt Đức Giê-hô-va để chinh phục đất, và nếu đất được dẹp yên trước mặt các ngươi, thì các ngươi phải ban cho họ đất Ga-la-át làm sản nghiệp.'),
(4749, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 30, 'OT', 'Nhưng nếu họ không chịu cầm vũ khí đi qua cùng các ngươi, thì họ sẽ nhận phần sản nghiệp giữa các ngươi trong xứ Ca-na-an.'),
(4750, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 31, 'OT', 'Con cháu Gát và con cháu Ru-bên thưa rằng: Chúng tôi sẽ làm như điều mà Đức Giê-hô-va đã phán cùng tôi tớ của Ngài.'),
(4751, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 32, 'OT', 'Chúng tôi sẽ cầm khí giới đi qua trước mặt Đức Giê-hô-va vào đất Ca-na-an, và phần sản nghiệp của chúng tôi sẽ ở bên này sông Giô-đanh.'),
(4752, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 33, 'OT', 'Vậy Môi-se ban cho con cháu của Ru-bên, con cháu của Gát và phân nửa chi phái Ma-na-se con trai của Giô-sép, làm sản nghiệp là vương quốc của Si-hôn vua dân A-mô-rít và vương quốc của Oùc vua Ba-san, tức là xứ ấy với các thành của nó, và các thành trong các miền bao quanh.'),
(4753, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 34, 'OT', 'Con cháu Gát xây cất Đi-bôn, A-ta-rốt và A-rô-e,'),
(4754, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 35, 'OT', 'Aït-rốt-Sô-phan, Gia-ê-xe và Giô-bê-ha.'),
(4755, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 36, 'OT', 'Bết-Nim-ra và Bết-Ha-ran, các thành kiên cố, và các ràn chiên.'),
(4756, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 37, 'OT', 'Con cháu Ru-bên xây cất Hết-bôn, Ê-lê-a-lê và Ki-ri-a-ta-im.'),
(4757, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 38, 'OT', 'Và họ chiếm lấy Nê-bô và Ba-anh-Mê-ôn, đã đổi tên hai thành ấy, và Síp-ma; và họ đặt tên cho các thành mà họ đã xây cất.'),
(4758, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 39, 'OT', 'Con cháu Ma-ki, con trai Ma-na-se, đi vào xứ Ga-la-át, chiếm lấy nó và đuổi người A-mô-rít đang ở đó ra.'),
(4759, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 40, 'OT', 'Vậy, Môi-se ban xứ Ga-la-át cho Ma-ki, con trai Ma-na-se, và Ma-ki ở tại đó.'),
(4760, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 41, 'OT', 'Giai-rơ, con trai Ma-na-se, đi và chiếm các làng của người A-mô-rít, rồi đặt tên các làng ấy là thôn Giai-rơ.'),
(4761, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 32, 42, 'OT', 'Nô-bách đi và chiếm lấy Kê-nát cùng các con gái nó, rồi đặt tên cho nó là Nô-bách theo danh mình.'),
(4762, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 1, 'OT', 'Nầy là các trạm dừng chân của con cái Y-sơ-ra-ên, là những người đã ra khỏi đất Ê-díp-tô theo các đạo quân của họ, dưới sự hướng dẫn của Môi-se và A-rôn.'),
(4763, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 2, 'OT', 'Môi-se chép các nơi xuất phát của họ tùy theo các trạm hành trình, theo lệnh Đức Giê-hô-va; và đây là các trạm hành trình tùy theo các nơi xuất phát của họ.'),
(4764, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 3, 'OT', 'Dân Y-sơ-ra-ên ra đi từ Ram-se ngày mười lăm tháng giêng, tức ngày sau lễ Vượt-qua, cách dạn dĩ, có mắt của hết thảy người Ê-díp-tô thấy.'),
(4765, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 4, 'OT', 'Người Ê-díp-tô chôn những kẻ mà Đức Giê-hô-va đã giết giữa họ, tức là mọi con đầu lòng; và Đức Giê-hô-va đã thi hành sự phán xét trên các thần của chúng nó.'),
(4766, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 5, 'OT', 'Dân Y-sơ-ra-ên đi từ Ram-se và đóng trại tại Su-cốt;'),
(4767, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 6, 'OT', 'rời khỏi Su-cốt, rồi đóng trại tại Ê-tam, là nơi tận cùng của đồng vắng.'),
(4768, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 7, 'OT', 'Họ khởi hành từ Ê-tam, rồi quay trở lại đóng trại gần Phi-Ha-hi-rốt, đối diện với Ba-anh-Sê-phôn, và đóng trại trước Mít-đôn.'),
(4769, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 8, 'OT', 'Dân Y-sơ-ra-ên khởi hành từ trước mặt Phi-Ha-hi-rốt, đi qua giữa biển vào đồng vắng, đi đường ba ngày ngang qua đồng vắng Ê-tam, rồi đóng trại tại Ma-ra.'),
(4770, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 9, 'OT', 'Đoạn, họ đi từ Ma-ra đến Ê-lim; và tại Ê-lim có mười hai suối nước và bảy mươi cây chà là, bèn cắm trại tại đó.'),
(4771, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 10, 'OT', 'Dân sự khởi hành từ Ê-lim và đóng trại bên Biển Sậy.'),
(4772, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 11, 'OT', 'Khởi hành từ Biển Đỏ, họ đóng trại tại đồng vắng Xin.'),
(4773, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 12, 'OT', 'Dân Y-sơ-ra-ên đi từ đồng vắng Sin, rồi đóng trại tại Đáp-ca.'),
(4774, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 13, 'OT', 'Đi từ Đáp-ca và đóng trại tại A-lúc.'),
(4775, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 14, 'OT', 'Dân Y-sơ-ra-ên đi từ A-lúc và đóng trại tại Rê-phi-đim; nhưng ở đó không có nước cho dân chúng uống.'),
(4776, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 15, 'OT', 'Dân Y-sơ-ra-ên đi từ Rê-phi-đim và đóng trại trong đồng vắng Si-na-i.'),
(4777, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 16, 'OT', 'Đi từ đồng vắng Si-na-i, rồi đóng trại tại Kíp-rốt Ha-tha-va.'),
(4778, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 17, 'OT', 'Đi từ Kíp-rốt-Ha-tha-va và đóng trại tại Hát-sê-rốt.'),
(4779, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 18, 'OT', 'Đoạn, đi từ Hát-sê-rốt và đóng trại tại Rít-ma.'),
(4780, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 19, 'OT', 'Đi từ Rít-ma, rồi đóng trại tại Ri-môn Phê-rết.'),
(4781, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 20, 'OT', 'Đi từ Ri-môn-Phê-rết và đóng trại tại Líp-na.'),
(4782, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 21, 'OT', 'Khởi hành từ Líp-na, họ đóng trại tại Ri-sa.'),
(4783, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 22, 'OT', 'Đi từ Ri-sa, đóng trại tại Kê-hê-la-tha.'),
(4784, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 23, 'OT', 'Dời khỏi Kê-hê-la-tha, rồi đóng trại tại núi Sê-phe.'),
(4785, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 24, 'OT', 'Dời khỏi núi Sê-phe, họ đóng trại tại Ha-ra-đa.'),
(4786, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 25, 'OT', 'Đi từ Ha-ra-đa, rồi đóng trại tại Mác-hê-lốt.'),
(4787, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 26, 'OT', 'Đoạn, họ đi từ Mác-hê-lốt và đóng trại tại Ta-hát.'),
(4788, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 27, 'OT', 'Dân Y-sơ-ra-ên đi từ Ta-hát và đóng trại tại Ta-rách.'),
(4789, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 28, 'OT', 'Đi từ Ta-rách và đóng trại tại Mít-ga.'),
(4790, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 29, 'OT', 'Dời khỏi Mít-ga, rồi đóng trại tại Hách-mô-na.'),
(4791, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 30, 'OT', 'Khởi hành từ Hách-mô-na, họ đóng trại tại Mô-sê-rốt.'),
(4792, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 31, 'OT', 'Khởi hành từ Mô-sê-rốt, họ đóng trại tại Bê-nê-Gia-can.'),
(4793, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 32, 'OT', 'Khởi hành từ Bê-nê-Gia-can, họ đóng trại tại Hô-Ghi-gát.'),
(4794, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 33, 'OT', 'Dời khỏi Hô-Ghi-gát, đóng trại tại Dốt-ba-tha.'),
(4795, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 34, 'OT', 'Dân sự rời khỏi Dốt-ba-tha và đóng trại tại Aùp-rô-na.'),
(4796, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 35, 'OT', 'Dân sự đi từ Aùp-rô-na, rồi đóng trại tại Ê-xi-ôn-Ghê-be.'),
(4797, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 36, 'OT', 'Dời khỏi Ê-xi-ôn Ghê-be, rồi đóng trại tại đồng vắng Xin, tức là Ca-đe.'),
(4798, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 37, 'OT', 'Đoàn dân rời Ca-đe, rồi đóng trại tại núi Hô-rơ, ở tận cùng biên giới đất Ê-đôm.'),
(4799, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 38, 'OT', 'A-rôn, thầy tế lễ, theo mạng Đức Giê-hô-va lên núi Hô-rơ và qua đời tại đó, trong năm thứ bốn mươi sau khi dân Y-sơ-ra-ên ra khỏi xứ Ê-díp-tô, nhằm ngày mồng một tháng năm.'),
(4800, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 39, 'OT', 'A-rôn qua đời trên núi Hô-rơ, khi người được một trăm hai mươi ba tuổi.'),
(4801, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 40, 'OT', 'Vua A-rát là người Ca-na-an, ở miền nam xứ Ca-na-an, nghe được khi con cái Y-sơ-ra-ên đến.'),
(4802, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 41, 'OT', 'Dân Y-sơ-ra-ên đi từ núi Hô-rơ và đóng trại tại Xa-mô-na.'),
(4803, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 42, 'OT', 'Dời khỏi Xa-mô-na, rồi đóng trại tại Phu-nôn.'),
(4804, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 43, 'OT', 'Đi từ Phu-nôn và đóng trại tại Ô-bốt.'),
(4805, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 44, 'OT', 'Đi từ Ô-bốt, rồi đóng trại tại Y-giê-A-ba-rim, trên ranh giới Mô-áp.'),
(4806, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 45, 'OT', 'Đi từ Y-giê-A-ba-rim và đóng trại tại Đi-bôn-Gát.'),
(4807, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 46, 'OT', 'Đi từ Đi-bôn-Gát, rồi đóng trại tại Anh-môn-Đíp-la-tha-im.'),
(4808, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 47, 'OT', 'Đoàn dân rời Anh-môn-Đíp-la-tha-im và đóng trại tại các núi A-ba-rim, đối diện Nê-bô.'),
(4809, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 48, 'OT', 'Dời khỏi các núi A-ba-rim, họ đóng trại tại các đồng bằng Mô-áp, bên bờ sông Giô-đanh, đối ngang Giê-ri-cô.'),
(4810, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 49, 'OT', 'Dân Y-sơ-ra-ên đóng trại dọc theo sông Giô-đanh, từ Bết-Giê-si-mốt đến A-bên-Si-tim trong đồng bằng Mô-áp.'),
(4811, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 50, 'OT', 'Đức Giê-hô-va phán cùng Môi-se trong đồng bằng Mô-áp, bên kia sông Giô-đanh, đối ngang Giê-ri-cô, mà rằng:'),
(4812, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 51, 'OT', 'Hãy nói cùng con cái Y-sơ-ra-ên rằng: Khi các ngươi qua sông Giô-đanh vào đất Ca-na-an,'),
(4813, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 52, 'OT', 'Các ngươi phải đuổi hết thảy những người sống trong xứ khỏi trước mặt mình, tiêu diệt hết thảy các hình tượng chạm khắc của chúng nó, phá hủy hoàn toàn hết thảy các hình tượng đúc của chúng nó, và hủy diệt hết thảy các nơi cao của chúng nó.'),
(4814, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 53, 'OT', 'Các ngươi phải chiếm lấy xứ và ở trong đó, vì ta đã ban xứ ấy cho các ngươi để làm sản nghiệp.'),
(4815, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 54, 'OT', 'Các ngươi sẽ bắt thăm chia đất nầy ra theo các họ hàng mình: kẻ nào nhiều người thì sẽ được chia phần sản nghiệp lớn hơn, kẻ nào ít người thì sẽ được chia phần sản nghiệp nhỏ hơn; phần đất nào mà thăm chỉ ra cho ai thì sẽ thuộc về người ấy; các ngươi phải chia đất nầy theo các chi phái tổ tiên mình.'),
(4816, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 55, 'OT', 'Nếu các ngươi không đuổi dân cư của đất ấy ra khỏi trước mặt mình, thì những kẻ các ngươi để lại trong bọn họ sẽ trở thành những cái gai nơi mắt các ngươi và những cái chông nơi hông các ngươi; chúng sẽ làm cho các ngươi khốn khổ trên đất mà các ngươi đang ở.'),
(4817, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 33, 56, 'OT', 'Và sẽ xảy ra rằng, như Ta đã định làm cho chúng nó, thì Ta cũng sẽ làm cho các ngươi vậy.'),
(4818, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 34, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(4819, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 34, 2, 'OT', 'Hãy truyền cho con cái Y-sơ-ra-ên và nói với họ: Khi các ngươi vào đất Ca-na-an, thì đây là đất các ngươi sẽ nhận được làm sản nghiệp, tức là đất Ca-na-an theo các ranh giới của nó.'),
(4820, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 34, 3, 'OT', 'Miền nam sẽ thuộc về các ngươi, từ đồng vắng Xin dọc theo Ê-đôm; và ranh giới phía nam của các ngươi sẽ bắt đầu từ cuối Biển-mặn về phía đông.'),
(4821, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 34, 4, 'OT', 'Đường biên giới sẽ cong xuống phía nam từ Aïc-ráp-bim, đi ngang qua Xin, và các ngọn nguồn của nó ở về phía nam Ca-đe-Ba-nê-a; rồi đi ra khỏi Hát-sa-Aùt-đa và chạy qua Aùt-môn.'),
(4822, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 34, 5, 'OT', 'Giới hạn đó sẽ đi từ Aùt-môn về phía suối của xứ Ê-díp-tô, và các lối ra của nó sẽ hướng về biển.'),
(4823, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 34, 6, 'OT', 'Giới hạn về phía tây sẽ là biển; biển lớn sẽ là giới hạn các ngươi; ấy sẽ là giới hạn phía biển.'),
(4824, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 34, 7, 'OT', 'Đây sẽ là ranh giới của các ngươi về phía bắc: từ biển lớn, các ngươi sẽ lấy núi Hô-rơ làm ranh giới cho các ngươi.'),
(4825, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 34, 8, 'OT', 'Từ núi Hô-rơ, các ngươi sẽ đi đến chỗ vào Ha-mát; và các đầu mút của biên giới sẽ là Xê-đát.'),
(4826, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 34, 9, 'OT', 'Ranh giới sẽ đi đến Xíp-rôn, và các điểm cuối cùng của nó là Hát-sa-Ê-nan; đây sẽ là ranh giới phía bắc của các ngươi.'),
(4827, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 34, 10, 'OT', 'Phía đông, các ngươi sẽ định ranh giới mình từ Hát-sa-Ê-nan đến Sê-pham.'),
(4828, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 34, 11, 'OT', 'Rồi ranh giới sẽ đi từ Sê-pham xuống đến Ríp-la, về phía đông của A-in; đoạn ranh giới đi xuống và giáp bờ biển về phía đông của biển Ki-nê-rết.'),
(4829, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 34, 12, 'OT', 'Giới hạn sẽ chạy xuống về phía sông Giô-đanh, và các lối ra của nó sẽ là Biển-mặn. Đó sẽ là xứ các ngươi, với các giới hạn của nó xung quanh.'),
(4830, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 34, 13, 'OT', 'Môi-se truyền cho dân Y-sơ-ra-ên rằng: Đây là đất mà các ngươi sẽ chia nhau bằng cách bắt thăm, theo lệnh của Đức Giê-hô-va, để trao cho chín chi phái và phân nửa chi phái.'),
(4831, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 34, 14, 'OT', 'Vì chi phái con cháu Ru-bên, theo nhà tổ phụ mình, và chi phái con cháu Gát, theo nhà tổ phụ mình, cùng phân nửa chi phái Ma-na-se, đã nhận phần sản nghiệp của họ.'),
(4832, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 34, 15, 'OT', 'Hai chi phái và nửa chi phái đã nhận lãnh sản nghiệp của mình ở bên kia sông Giô-đanh, đối ngang Giê-ri-cô về phía đông, tức về phía mặt trời mọc.'),
(4833, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 34, 16, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(4834, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 34, 17, 'OT', 'Đây là những tên người sẽ chia đất cho các ngươi: Ê-lê-a-sa, thầy tế lễ, và Giô-suê, con trai của Nun.'),
(4835, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 34, 18, 'OT', 'Các ngươi phải chọn một người lãnh đạo, mỗi người một người từ mỗi chi phái, để chia đất làm sản nghiệp.'),
(4836, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 34, 19, 'OT', 'Đây là tên những người đó: về chi phái Giu-đa, Ca-lép, con trai Giê-phu-nê.'),
(4837, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 34, 20, 'OT', 'Về chi phái con cháu Si-mê-ôn, Sê-mu-ên, con trai A-mi-hút;'),
(4838, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 34, 21, 'OT', 'Về chi phái Bên-gia-min, Ê-li-đát con trai Kít-lon.'),
(4839, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 34, 22, 'OT', 'Về chi phái con cháu Đan, một quan trưởng là Bu-ki, con trai Giốc-li.'),
(4840, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 34, 23, 'OT', 'Về con cháu Giô-sép, về chi phái con cháu Ma-na-se, một lãnh tụ tên là Ha-ni-ên, con trai Ê-phát.'),
(4841, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 34, 24, 'OT', 'Về chi phái con cháu Eùp-ra-im, một thủ lãnh là Kê-mu-ên, con trai Síp-tan.'),
(4842, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 34, 25, 'OT', 'Về chi phái con cháu Sa-bu-lôn, quan trưởng là Ê-lít-sa-phan, con trai Phác-nát.'),
(4843, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 34, 26, 'OT', 'Về chi phái con cháu Y-sa-ca, một quan trưởng tên là Pha-ti-ên, con trai A-xan;'),
(4844, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 34, 27, 'OT', 'Về chi phái con cháu A-se, có một quan trưởng tên là A-hi-hút, con trai của Se-lu-mi.'),
(4845, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 34, 28, 'OT', 'Về chi phái con cháu Nép-ta-li, có viên quan trưởng là Phê-đa-ên, con trai A-mi-hút.'),
(4846, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 34, 29, 'OT', 'Đây là những người mà Đức Giê-hô-va đã truyền phải chia sản nghiệp cho con cái Y-sơ-ra-ên trong đất Ca-na-an.'),
(4847, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 1, 'OT', 'Đức Giê-hô-va phán cùng Môi-se trong đồng bằng Mô-áp, bên bờ sông Giô-đanh gần Giê-ri-cô, mà rằng:'),
(4848, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 2, 'OT', 'Hãy truyền biểu dân Y-sơ-ra-ên, họ phải trao cho người Lê-vi các thành để ở, từ phần sản nghiệp của mình, và các ngươi phải trao cho người Lê-vi đất đai ở chung quanh các thành ấy.'),
(4849, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 3, 'OT', 'Các thành sẽ dùng làm nơi ở cho người Lê-vi; đồng cỏ xung quanh các thành ấy sẽ dùng cho súc vật, cho tài sản và cho mọi loài vật của họ.'),
(4850, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 4, 'OT', 'Đất chung quanh các thành mà các ngươi sẽ ban cho người Lê-vi, kể từ vách thành trở ra ngoài, sẽ là một ngàn thước về mọi phía.'),
(4851, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 5, 'OT', 'Các ngươi phải đo từ phía ngoài thành về phía đông hai ngàn thước, về phía nam hai ngàn thước, về phía tây hai ngàn thước, và về phía bắc hai ngàn thước; thành sẽ ở giữa. Đất ấy sẽ thuộc về người Lê-vi làm đất khoanh vùng quanh các thành.'),
(4852, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 6, 'OT', 'Các thành mà các ngươi sẽ ban cho Lê-vi, gồm sáu thành nơi ẩn náu mà các ngươi phải ban ra để kẻ giết người trốn đến đó; ngoài sáu thành ấy, các ngươi phải ban thêm bốn mươi hai thành.'),
(4853, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 7, 'OT', 'Tất cả các thành mà các ngươi sẽ ban cho người Lê-vi là bốn mươi tám thành, cả thành lẫn đất đai xung quanh.'),
(4854, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 8, 'OT', 'Các thành mà các ngươi phải trao ra từ sản nghiệp của con cái Y-sơ-ra-ên thì phải lấy nhiều hơn từ chi phái đông người, và lấy ít hơn từ chi phái ít người; mỗi người tùy theo phần sản nghiệp mình nhận được thì phải trao các thành của mình cho Lê-vi.'),
(4855, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 9, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng:'),
(4856, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 10, 'OT', 'Hãy nói cùng con cái Y-sơ-ra-ên rằng: Khi các ngươi đi qua sông Giô-đanh vào đất Ca-na-an,'),
(4857, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 11, 'OT', 'Các ngươi phải chỉ định cho mình những thành làm các thành trú ẩn, để kẻ giết người vô ý, là người đánh chết một mạng sống một cách vô tình, có thể chạy đến đó mà trốn.'),
(4858, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 12, 'OT', 'Các thành ấy sẽ làm nơi ẩn náu cho các ngươi khỏi người báo thù, hầu cho kẻ giết người không chết cho đến khi người ấy ra trình diện trước mặt hội chúng để chịu xét xử.'),
(4859, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 13, 'OT', 'Và các thành mà các ngươi phải trao cho sẽ là sáu thành nơi nương náu cho các ngươi.'),
(4860, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 14, 'OT', 'Phải chỉ định ba thành bên kia sông Giô-đanh, và phải chỉ định ba thành trong xứ Ca-na-an; các thành ấy sẽ là những thành bảo vệ.'),
(4861, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 15, 'OT', 'Sáu thành nầy sẽ làm nơi ẩn náu cho con cái Y-sơ-ra-ên, cho khách ngoại bang và kẻ kiều ngụ giữa vòng chúng, để mọi kẻ giết người vô ý có thể chạy trốn đến đó.'),
(4862, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 16, 'OT', 'Nếu người nào dùng vật bằng sắt đánh người khác mà chết, thì kẻ giết người ấy phải bị xử tử hình.'),
(4863, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 17, 'OT', 'Nếu lấy hòn đá trong tay mà đánh, khiến người kia chết, thì kẻ đánh đó là sát nhân; sát nhân ấy phải bị xử tử hình.'),
(4864, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 18, 'OT', 'Hoặc bằng khí giới bằng gỗ cầm tay mà đánh người khác đến chết, thì kẻ đã đánh phải bị xử tử, vì người ấy là kẻ giết người.'),
(4865, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 19, 'OT', 'Kẻ báo thù huyết chính người ấy sẽ giết kẻ giết người; khi gặp nó, thì người ấy phải giết nó.'),
(4866, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 20, 'OT', 'Nếu người nào vì lòng ghét mà xô đẩy người khác, hoặc ném vật gì vào người ấy khiến người ấy chết,'),
(4867, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 21, 'OT', 'Hoặc vì thù hằn mà đánh người đó bằng tay, khiến người ấy chết, thì kẻ đánh phải bị xử tử hình; ấy là kẻ giết người; người báo thù huyết sẽ giết kẻ giết người đó khi gặp nó.'),
(4868, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 22, 'OT', 'Nếu một cách tình cờ, không có thù oán, mà người nầy xô người kia, hoặc ném vật gì trên người kia, không có ác ý.'),
(4869, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 23, 'OT', 'hoặc ném trúng người ấy bằng một hòn đá nào đó mà không thấy, khiến người ấy chết, mà người ném không phải là kẻ thù và cũng không có ý hại người ấy,'),
(4870, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 24, 'OT', 'Hội chúng phải xét xử giữa kẻ đánh và người báo oán huyết, theo những luật lệ nầy.'),
(4871, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 25, 'OT', 'Hội chúng phải cứu kẻ giết người khỏi tay người báo thù huyết; hội chúng phải đưa hắn trở lại thành nơi nương náu mà hắn đã chạy đến; và hắn phải ở đó cho đến khi thầy tế lễ thượng phẩm, là người đã được xức dầu thánh cho, qua đời.'),
(4872, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 26, 'OT', 'Nhưng nếu kẻ giết người ra khỏi giới hạn thành nơi người đó chạy đến nương náu,'),
(4873, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 27, 'OT', 'Nếu kẻ báo oán mạng gặp người đó ở ngoài ranh giới thành trú ẩn của người ấy và giết người đó, thì kẻ báo oán mạng không mắc tội giết người.'),
(4874, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 28, 'OT', 'Vì người đó phải ở trong thành trú ẩn cho đến khi thầy tế lễ lớn qua đời; còn sau khi thầy tế lễ lớn qua đời, thì kẻ giết người mới được trở về đất sản nghiệp của mình.'),
(4875, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 29, 'OT', 'Các điều nầy sẽ là luật lệ xét đoán cho các ngươi qua các thế hệ, ở khắp mọi nơi các ngươi cư ngụ.'),
(4876, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 30, 'OT', 'Mọi người giết người phải bị xử tử theo lời khai của các nhân chứng; nhưng một nhân chứng thì không đủ căn cứ để xử một người nào phải chết.'),
(4877, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 31, 'OT', 'Các ngươi không được nhận tiền bồi thường cho mạng sống của kẻ giết người đã phạm tội phải chết, vì nó chắc chắn phải bị xử tử.'),
(4878, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 32, 'OT', 'Các ngươi không được nhận tiền chuộc cho kẻ trốn đến thành trú ẩn của mình, để trở về ở trong đất nầy, cho đến khi thầy tế lễ cả qua đời.'),
(4879, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 33, 'OT', 'Các ngươi không được làm ô uế đất mà các ngươi đang ở, vì huyết mới làm ô uế đất; và đất ấy không được chuộc tội cho huyết đã đổ ra giữa nó, ngoại trừ bằng huyết của kẻ đã đổ huyết ấy.'),
(4880, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 35, 34, 'OT', 'Chớ làm ô uế đất mà các ngươi đang ở, là nơi ta ngự giữa, vì ta, Đức Giê-hô-va, ngự giữa dân Y-sơ-ra-ên.'),
(4881, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 36, 1, 'OT', 'Các trưởng tộc thuộc các họ hàng của con cháu Ga-la-át, con trai Ma-ki, cháu Ma-na-se, thuộc các họ hàng của con cháu Giô-sép, đã đến gần và nói trước mặt Môi-se và trước mặt các thủ lãnh, các trưởng tộc của con cháu Y-sơ-ra-ên.'),
(4882, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 36, 2, 'OT', 'Họ nói: Đức Giê-hô-va đã truyền cho chúa tôi bắt thăm chia đất làm sản nghiệp cho con cái Y-sơ-ra-ên, và chúa tôi đã nhận lệnh từ Đức Giê-hô-va trao sản nghiệp của Xê-lô-phát, anh chúng tôi, cho các con gái người.'),
(4883, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 36, 3, 'OT', 'Nếu các con gái ấy kết hôn với một trong những con trai của các chi phái Y-sơ-ra-ên, thì sản nghiệp của các cô sẽ bị trừ khỏi sản nghiệp tổ tiên chúng tôi và sẽ được cộng thêm vào sản nghiệp của chi phái mà các cô sẽ thuộc về, như vậy phần sản nghiệp đã bắt thăm cho chúng tôi sẽ bị giảm đi.'),
(4884, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 36, 4, 'OT', 'Nếu năm định kỳ được cử hành cho con cái Y-sơ-ra-ên, thì sản nghiệp của các cô ấy sẽ được thêm vào sản nghiệp của chi phái mà các cô ấy thuộc về; như vậy, sản nghiệp của các cô ấy sẽ bị trừ khỏi sản nghiệp của chi phái tổ tiên chúng tôi.'),
(4885, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 36, 5, 'OT', 'Môi-se truyền cho các con cái Y-sơ-ra-ên theo lệnh của Đức Giê-hô-va rằng: Điều chi phái con cháu Giô-sép nói là đúng.'),
(4886, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 36, 6, 'OT', 'Nầy là điều Đức Giê-hô-va đã truyền dạy về các con gái Xê-lô-phát, rằng: "Chúng sẽ lấy người nào mà chúng thấy đẹp lòng mình, nhưng phải lấy người trong họ hàng của chi phái tổ phụ mình."'),
(4887, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 36, 7, 'OT', 'Trong dân Y-sơ-ra-ên, sản nghiệp không được chuyển từ một chi phái này sang chi phái khác, vì mỗi người trong con cháu Y-sơ-ra-ên phải gắn bó với sản nghiệp của chi phái tổ tiên mình.'),
(4888, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 36, 8, 'OT', 'Mọi con gái được kế tự sản nghiệp trong các chi phái Y-sơ-ra-ên phải lấy một người thuộc cùng một chi phái với chi họ của cha mình, để con cháu Y-sơ-ra-ên ai nấy đều giữ sản nghiệp của tổ tiên mình.'),
(4889, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 36, 9, 'OT', 'Một phần sản nghiệp không được chuyển từ một chi phái này sang chi phái khác; nhưng mỗi chi phái trong các chi phái của Y-sơ-ra-ên sẽ giữ sản nghiệp của mình.'),
(4890, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 36, 10, 'OT', 'Các con gái Xê-lô-phát làm như Đức Giê-hô-va đã truyền Môi-se.'),
(4891, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 36, 11, 'OT', 'Mách-la, Thiệt-sa, Hốt-la, Minh-ca và Nô-a, các con gái của Xê-lô-phát, đều trở thành vợ của các con trai của cậu mình.'),
(4892, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 36, 12, 'OT', 'Chúng kết hôn trong các gia đình của con cháu Ma-na-se, con trai Giô-sép, và sản nghiệp của chúng thuộc về chi phái tổ phụ mình.'),
(4893, 4, 'GOI_vi', 'GOI_vi', 'vi', 'NUM', 36, 13, 'OT', 'Đây là các mạng lệnh và các điều luật mà Đức Giê-hô-va đã truyền cho dân Y-sơ-ra-ên qua tay Môi-se, tại các đồng bằng Mô-áp, bên bờ sông Giô-đanh, đối ngang Giê-ri-cô.'),
(4894, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 1, 'OT', 'Nầy là những lời Môi-se nói với cả Y-sơ-ra-ên, bên kia sông Giô-đanh, tại đồng vắng, trong đồng bằng, đối ngang Su-phơ, giữa khoảng Pha-ran và Tô-phên, La-ban, Hát-sê-rốt, và Đi-xa-háp.'),
(4895, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 2, 'OT', 'Mười một ngày đường từ Hô-rếp, dọc theo núi Sê-i-rơ, đến Ca-đe-Ba-nê-a.'),
(4896, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 3, 'OT', 'Năm thứ bốn mươi, ngày mồng một tháng mười một, Môi-se nói với con cái Y-sơ-ra-ên mọi điều mà Đức Giê-hô-va đã truyền cho ông phải nói cùng họ.'),
(4897, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 4, 'OT', 'Sau khi đánh bại Si-hôn, vua dân A-mô-rít, người ở tại Hết-bôn, và Oùc, vua Ba-san, người ở tại Aùch-ta-rốt và Eát-rê-i.'),
(4898, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 5, 'OT', 'Tại bên kia sông Giô-đanh, trong xứ Mô-áp, Môi-se bắt đầu giảng dạy luật pháp nầy, mà rằng:'),
(4899, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 6, 'OT', 'Giê-hô-va Đức Chúa Trời chúng ta phán cùng chúng ta tại Hô-rếp rằng: Đủ rồi, các ngươi đã ở lâu trên núi nầy.'),
(4900, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 7, 'OT', 'Hãy vòng lại, lên đường và đi đến núi dân A-mô-rít, cùng tất cả các vùng lân cận: đến vùng đồng bằng, lên núi, vào các vùng thấp, đến miền nam, đến bờ biển, vào đất dân Ca-na-an và Li-ban, cho đến sông lớn, sông Ơ-phơ-rát.'),
(4901, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 8, 'OT', 'Này, ta đã đặt đất trước mặt các ngươi; hãy vào và chiếm lấy đất mà Đức Giê-hô-va đã thề ban cho các tổ phụ các ngươi, là Aùp-ra-ham, Y-sác và Gia-cốp, cùng cho dòng dõi họ sau họ.'),
(4902, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 9, 'OT', 'Ta đã nói cùng các ngươi trong lúc ấy rằng: Một mình ta không thể gánh nổi các ngươi.'),
(4903, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 10, 'OT', 'Giê-hô-va Đức Chúa Trời của các ngươi đã làm cho các ngươi đông thêm; và nầy, ngày nay các ngươi đông như các ngôi sao trên trời.'),
(4904, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 11, 'OT', 'Nguyện Đức Giê-hô-va Đức Chúa Trời của tổ phụ các ngươi khiến các ngươi thêm lên gấp ngàn lần và ban phước cho các ngươi như Ngài đã phán cùng các ngươi.'),
(4905, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 12, 'OT', 'Làm sao ta có thể một mình mang nổi gánh nặng và trách nhiệm của các ngươi, cùng những sự tranh tụng của các ngươi?'),
(4906, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 13, 'OT', 'Hãy chọn các ngươi những người khôn ngoan, thông sáng và được biết đến trong các chi phái các ngươi, thì ta sẽ đặt họ lên làm đầu các ngươi.'),
(4907, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 14, 'OT', 'Các ngươi đáp lại ta rằng: "Điều mà ngài nói làm thật là tốt."'),
(4908, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 15, 'OT', 'Ta bèn chọn lấy các trưởng tộc của các ngươi, là những người khôn ngoan, nổi tiếng, ta đặt họ làm trưởng lãnh các ngươi, làm các quan cai ngàn người, cai trăm người, cai năm mươi người, cai mười người, và các chức quản lý trong các chi phái của các ngươi.'),
(4909, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 16, 'OT', 'Ta truyền cho các quan xét của các ngươi trong lúc ấy rằng: Hãy nghe xét giữa anh em các ngươi, và xét đoán cách công bình giữa một người với anh em mình và với người ngoại bang ở cùng người ấy.'),
(4910, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 17, 'OT', 'Trong việc xét xử, các ngươi không được thiên vị; phải nghe người bé nhỏ cũng như người lớn, không được sợ hãi ai, vì sự xét xử thuộc về Đức Chúa Trời. Việc nào khó khăn giữa các ngươi, hãy đem đến cho ta, thì ta sẽ nghe xét.'),
(4911, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 18, 'OT', 'Vậy, trong lúc ấy, ta đã truyền cho các ngươi mọi điều mà các ngươi phải làm.'),
(4912, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 19, 'OT', 'Chúng ta rời khỏi Hô-rếp, đi qua khắp đồng vắng lớn và khủng khiếp mà các ngươi đã thấy, theo hướng núi của dân A-mô-rít, như Giê-hô-va Đức Chúa Trời chúng ta đã truyền cho chúng ta, rồi đến Ca-đe-Ba-nê-a.'),
(4913, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 20, 'OT', 'Ta nói cùng các ngươi rằng: Chúng ta đã đến núi của dân A-mô-rít, là nơi Đức Giê-hô-va Đức Chúa Trời chúng ta ban cho chúng ta.'),
(4914, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 21, 'OT', 'Kìa, Đức Giê-hô-va Đức Chúa Trời ngươi đã phó đất nầy cho ngươi; hãy đi lên, chiếm lấy, y như Đức Giê-hô-va Đức Chúa Trời của tổ phụ ngươi đã phán cùng ngươi; chớ sợ, chớ kinh hãi.'),
(4915, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 22, 'OT', 'Tất cả các ngươi đến gần ta và nói: "Xin hãy sai những người đi trước chúng ta, để dò xét xứ nầy, rồi báo lại cho chúng ta biết con đường nào chúng ta phải đi và các thành nào chúng ta phải vào."'),
(4916, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 23, 'OT', 'Lời ấy đẹp lòng ta, ta bèn chọn trong các ngươi mười hai người, mỗi một người một chi phái.'),
(4917, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 24, 'OT', 'Bấy giờ họ quay đi, lên núi, đi đến khe Eách-côn và do thám nơi ấy.'),
(4918, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 25, 'OT', 'Họ đã lấy trong tay mình trái cây của đất ấy, đem về cho chúng ta, và thuật lại cùng chúng ta rằng: "Tốt lắm đất mà Đức Giê-hô-va Đức Chúa Trời chúng ta ban cho chúng ta."'),
(4919, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 26, 'OT', 'Nhưng tổ tiên các ngươi không chịu lên, và đã nổi loạn cùng mạng lịnh của Giê-hô-va Đức Chúa Trời các ngươi,'),
(4920, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 27, 'OT', 'Các ngươi than vãn trong các trại mình mà rằng: "Chính vì Đức Giê-hô-va ghét chúng tôi, nên Ngài đã đưa chúng tôi ra khỏi xứ Ê-díp-tô, để giao chúng tôi vào tay người A-mô-rít mà tiêu diệt chúng tôi."'),
(4921, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 28, 'OT', 'Chúng ta sẽ lên đâu? Anh em chúng ta làm tan chảy lòng chúng ta, nói rằng: Dân ấy lớn và cao hơn chúng ta, các thành thì lớn và kiên cố đến tận trời, và chúng tôi cũng đã thấy tại đó con cháu của A-na-kim.'),
(4922, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 29, 'OT', 'Ta nói cùng các ngươi: Đừng sợ hãi, cũng đừng kinh hãi trước mặt chúng.'),
(4923, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 30, 'OT', 'Giê-hô-va Đức Chúa Trời các ngươi đi trước mặt các ngươi, chính Ngài sẽ chiến đấu cho các ngươi, y như mọi điều Ngài đã làm cho các ngươi trước mắt các ngươi tại Ai Cập.'),
(4924, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 31, 'OT', 'Trong đồng vắng, là nơi ngươi đã thấy Đức Giê-hô-va Đức Chúa Trời ngươi bồng ngươi như một người bồng con trai mình, trên trọn con đường ngươi đã đi, cho đến khi tới nơi nầy.'),
(4925, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 32, 'OT', 'Dầu vậy, các ngươi vẫn không tin cậy nơi Đức Giê-hô-va Đức Chúa Trời các ngươi, trong việc nầy,'),
(4926, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 33, 'OT', 'Đức Giê-hô-va đi trước mặt các ngươi trên đường, để tìm cho các ngươi chỗ dừng chân, ban đêm trong đám lửa để soi đường các ngươi phải đi, và ban ngày trong đám mây.'),
(4927, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 34, 'OT', 'Đức Giê-hô-va đã nghe tiếng của lời các ngươi, bèn nổi giận và thề rằng:'),
(4928, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 35, 'OT', 'Chẳng một người nào trong thế hệ ác bạc này sẽ thấy đất tốt lành mà Ta đã thề ban cho tổ phụ các ngươi.'),
(4929, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 36, 'OT', 'Trừ ra Ca-lép, con trai của Giê-phu-nê, chính người ấy sẽ thấy xứ đó; và ta sẽ ban cho người ấy cùng con cháu người xứ mà người đã đi qua, vì người đã hết lòng theo Đức Giê-hô-va.'),
(4930, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 37, 'OT', 'Đức Giê-hô-va cũng nổi giận cùng tôi vì cớ các ngươi, mà phán rằng: Ngươi cũng sẽ không vào đó đâu.'),
(4931, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 38, 'OT', 'Giô-suê, con trai của Nun, là người đang hầu trước mặt ngươi, chính người ấy sẽ vào đó. Hãy khích lệ người, vì chính người ấy sẽ khiến Y-sơ-ra-ên nhận xứ ấy làm sản nghiệp.'),
(4932, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 39, 'OT', 'Còn con trẻ các ngươi, là những kẻ mà các ngươi nói sẽ bị cướp giựt, và các con trai các ngươi hiện nay chưa biết điều thiện hay điều ác, chính chúng sẽ vào đó; Ta sẽ ban cho chúng nó đất ấy, và chúng sẽ chiếm hữu nó.'),
(4933, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 40, 'OT', 'Các ngươi hãy quay mặt về phía các ngươi, rồi lên đường đi vào đồng vắng, theo con đường Biển Đỏ.'),
(4934, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 41, 'OT', 'Và các ngươi đáp cùng ta rằng: "Chúng tôi đã phạm tội cùng Đức Giê-hô-va; chúng tôi sẽ đi lên, chiến đấu, và làm mọi điều mà Đức Giê-hô-va Đức Chúa Trời chúng tôi đã truyền cho chúng tôi." Bấy giờ mỗi người các ngươi đều thắt khí giới của mình và sẵn sàng đi lên núi.'),
(4935, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 42, 'OT', 'Đức Giê-hô-va phán cùng tôi rằng: Hãy nói cùng họ: Các ngươi chớ đi lên, chớ chiến đấu, vì ta không ở giữa các ngươi; e các ngươi bị đánh bại trước mặt kẻ thù các ngươi.'),
(4936, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 43, 'OT', 'Ta đã nói với các ngươi, nhưng các ngươi không nghe; các ngươi đã chống nghịch mạng của Đức Giê-hô-va, đầy lòng kiêu ngạo, rồi kéo lên núi.'),
(4937, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 44, 'OT', 'Người A-mô-rít, là dân sống trong núi ấy, đi ra đón các ngươi và đuổi các ngươi như thể ong làm; chúng đánh bại các ngươi tại Sê-i-rơ cho đến Họt-ma.'),
(4938, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 45, 'OT', 'Các ngươi trở về và khóc lóc trước mặt Đức Giê-hô-va, nhưng Đức Giê-hô-va không nghe tiếng các ngươi, cũng chẳng để ý đến các ngươi.'),
(4939, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 1, 46, 'OT', 'Và các ngươi ở lại tại Ca-đe những ngày lâu dài, những ngày mà các ngươi đã ở.'),
(4940, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 1, 'OT', 'Chúng ta bèn trở lại, đi vào đồng vắng theo con đường Biển Đỏ, y như Đức Giê-hô-va đã phán dạy tôi; và chúng ta đi vòng quanh núi Sê-i-rơ nhiều ngày lâu.'),
(4941, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 2, 'OT', 'Đức Giê-hô-va phán cùng tôi mà rằng:'),
(4942, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 3, 'OT', 'Các ngươi đi vòng quanh ngọn núi nầy đã đủ lâu rồi; hãy trở lại đi về hướng bắc.'),
(4943, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 4, 'OT', 'Hãy truyền cho dân sự rằng: Các ngươi đang đi qua vùng đất biên giới của anh em mình, con cháu Ê-sau, những người đang sống tại Sê-i-rơ; và chúng sẽ sợ các ngươi; vậy các ngươi phải hết sức giữ mình.'),
(4944, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 5, 'OT', 'Đừng gây hấn với chúng, vì Ta sẽ không ban cho các ngươi đất của chúng, dù chỉ một bước chân đất; vì Ta đã ban cho Ê-sau núi Sê-i-rơ làm sản nghiệp.'),
(4945, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 6, 'OT', 'Ngươi phải mua lương thực của chúng bằng bạc mà ăn; và cũng phải mua nước của chúng bằng bạc mà uống.'),
(4946, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 7, 'OT', 'Vì Đức Giê-hô-va Đức Chúa Trời ngươi đã ban phước cho mọi công việc của tay ngươi; Ngài biết rõ cuộc hành trình ngươi đi qua đồng vắng lớn nầy. Trong bốn mươi năm, Đức Giê-hô-va Đức Chúa Trời ngươi ở cùng ngươi; ngươi không thiếu điều chi.'),
(4947, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 8, 'OT', 'Chúng ta đi ngang qua cách xa anh em ta, là con cháu Ê-sau, những người ở tại Sê-i-rơ, theo con đường đồng vắng, từ Ê-lát và Ê-xi-ôn Ghê-be; rồi chúng ta quay lại và đi ngang qua theo con đường đồng vắng Mô-áp.'),
(4948, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 9, 'OT', 'Đức Giê-hô-va phán cùng ta rằng: "Chớ chống cự dân Mô-áp và chớ gây chiến tranh cùng chúng; vì ta sẽ không ban cho ngươi điều gì từ đất chúng làm sản nghiệp, bởi ta đã ban A-rơ cho con cháu Lót làm sản nghiệp."'),
(4949, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 10, 'OT', 'Trước kia, dân Ê-mim đã sống ở đó, một dân đông đảo, hùng mạnh và cao lớn như dân A-na-kim.'),
(4950, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 11, 'OT', 'Người ta cũng coi chúng như dân A-na-kim, nhưng dân Mô-áp gọi chúng là Ê-mim.'),
(4951, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 12, 'OT', 'Dân Hô-rít trước kia ở tại Sê-i-rơ; nhưng con cháu của Ê-sau đã đến, diệt họ khỏi nơi ấy, và ở thế chỗ họ, y như Y-sơ-ra-ên đã làm cho đất sản nghiệp mà Đức Giê-hô-va đã ban cho họ.'),
(4952, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 13, 'OT', 'Bây giờ, hãy đứng dậy và đi ngang qua khe Xê-rết. Vậy, chúng ta đi ngang qua khe Xê-rết.'),
(4953, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 14, 'OT', 'Thời gian chúng ta đi từ Ca-đe-Ba-nê-a cho đến khi qua khe Xê-rết là ba mươi tám năm, cho đến khi toàn thể thế hệ những người lính ra trận đã chết hết khỏi trại quân, y như Đức Giê-hô-va đã thề cùng họ.'),
(4954, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 15, 'OT', 'Vả lại, tay Đức Giê-hô-va cũng ở trên họ để tiêu diệt họ khỏi giữa trại quân, cho đến khi chúng đều bị tiêu diệt.'),
(4955, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 16, 'OT', 'Khi toàn thể những người lính đã chết hết khỏi giữa dân sự,'),
(4956, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 17, 'OT', 'Đức Giê-hô-va phán cùng tôi rằng:'),
(4957, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 18, 'OT', 'Hôm nay ngươi sẽ đi ngang qua biên giới của Mô-áp, đến A-rơ.'),
(4958, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 19, 'OT', 'Khi các ngươi đến gần dân con cháu Am-môn, chớ gây hấn với họ và chớ gây chiến cùng họ; vì ta sẽ không ban cho ngươi bất cứ phần nào đất của con cháu Am-môn làm sản nghiệp, bởi ta đã ban đất ấy cho con cháu Lót làm sản nghiệp.'),
(4959, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 20, 'OT', 'Cũng được kể là đất Rê-pha-im; người Rê-pha-im đã ở đó trước kia, và dân Am-môn gọi họ là Xam-xu-mim.'),
(4960, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 21, 'OT', 'Dân đó là một dân lớn, mạnh và cao lớn như dân A-na-kim; nhưng Đức Giê-hô-va đã tiêu diệt chúng khỏi trước mặt chúng, và chúng chiếm lấy đất ấy rồi ở đó thay thế chúng.'),
(4961, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 22, 'OT', 'Như Đức Giê-hô-va đã làm cho con cháu Ê-sau, là những người sống tại Sê-i-rơ, khi Ngài tiêu diệt dân Hô-rít trước mặt họ, và họ chiếm lấy đất ấy, rồi ở thế chỗ cho đến ngày nay.'),
(4962, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 23, 'OT', 'Dân A-vim, ở trong các làng cho đến Ga-xa, thì bị dân Cáp-tô-rim, xuất phát từ Cáp-tô, tiêu diệt, và dân Cáp-tô-rim ở thế vào chỗ họ.'),
(4963, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 24, 'OT', 'Hãy chỗi dậy, đi qua khe Aït-nôn. Kìa, ta đã phó Si-hôn, vua Hết-bôn, người A-mô-rít, cùng xứ ông ấy vào tay các ngươi; hãy khởi sự chiếm lấy và giao chiến với ông ấy.'),
(4964, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 25, 'OT', 'Ngày nay, ta sẽ bắt đầu ban sự kinh sợ và sợ hãi về ngươi trên các dân tộc dưới khắp các trời, để khi nghe danh ngươi, họ sẽ run rẩy và kinh hoàng trước mặt ngươi.'),
(4965, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 26, 'OT', 'Từ đồng vắng Kê-đê-mốt, ta sai các sứ giả đến Si-hôn, vua Hết-bôn, với những lời hòa bình, để nói rằng:'),
(4966, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 27, 'OT', 'Tôi sẽ đi ngang qua đất nước của ngài; tôi sẽ đi trên con đường chính, không rẽ sang bên phải hay bên trái.'),
(4967, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 28, 'OT', 'Ta sẽ mua bằng tiền lương thực để ăn, và bằng tiền ngươi sẽ bán nước cho ta để uống; ta chỉ đi qua thôi, bằng đôi chân mình.'),
(4968, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 29, 'OT', 'Cũng như con cháu Ê-sau sống tại Sê-i-rơ và dân Mô-áp sống tại A-rơ đã làm cho tôi, cho đến khi tôi qua sông Giô-đanh, vào đất mà Đức Giê-hô-va Đức Chúa Trời chúng tôi ban cho chúng tôi.'),
(4969, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 30, 'OT', 'Nhưng Si-hôn, vua Hết-bôn, không chịu để chúng ta đi ngang qua đất người; vì Đức Giê-hô-va Đức Chúa Trời ngươi đã làm cho tâm thần người trở nên cứng cỏi và lòng người ngoan cường, để phó người vào tay ngươi, như ngày nay đã xảy ra.'),
(4970, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 31, 'OT', 'Đức Giê-hô-va phán cùng ta rằng: Hãy xem, ta đã bắt đầu phó Si-hôn và xứ người ra trước mặt ngươi; hãy bắt đầu chiếm lấy xứ người làm sản nghiệp.'),
(4971, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 32, 'OT', 'Si-hôn và cả dân sự người ra đón chúng ta đặng giao chiến tại Gia-hát.'),
(4972, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 33, 'OT', 'Nhưng Đức Giê-hô-va Đức Chúa Trời chúng ta đã phó người cho chúng ta, và chúng ta đánh bại người, các con trai người cùng toàn thể dân sự người.'),
(4973, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 34, 'OT', 'Bấy giờ, chúng tôi chiếm lấy tất cả các thành của người, và diệt sạch mọi thành, cả đàn ông, đàn bà và trẻ nhỏ, không để sót một ai.'),
(4974, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 35, 'OT', 'Chúng ta chỉ cướp lấy cho mình các loài vật, và của cướp từ các thành mà chúng ta đã chiếm được.'),
(4975, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 36, 'OT', 'Từ A-rô-e, nơi ở bên bờ khe Aït-nôn, và thành ở trong khe ấy, cho đến Ga-la-át, không có thành nào cao lớn khỏi tầm tay chúng ta; Giê-hô-va Đức Chúa Trời chúng ta đã trao hết cả vào tay chúng ta.'),
(4976, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 2, 37, 'OT', 'Chỉ có đất của con cái Am-môn, ngươi không được đến gần; dọc theo toàn bộ dòng suối Gia-bốc, các thành trên núi và tất cả những gì Đức Giê-hô-va Đức Chúa Trời chúng ta đã truyền lệnh không được đến gần.'),
(4977, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 3, 1, 'OT', 'Chúng tôi bèn quay lại, đi lên đường Ba-san; thì Oùc, vua Ba-san, cùng toàn thể dân sự người đi ra đón chúng tôi để giao chiến tại Eách-rê-i.'),
(4978, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 3, 2, 'OT', 'Đức Giê-hô-va phán cùng tôi rằng: "Ngươi chớ sợ nó, vì ta đã phó nó, toàn dân nó, và đất nó vào tay ngươi; ngươi sẽ làm cho nó như ngươi đã làm cho Si-hôn, vua A-mô-rít, ở tại Hết-bôn."'),
(4979, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 3, 3, 'OT', 'Giê-hô-va Đức Chúa Trời chúng ta cũng đã phó vào tay chúng ta cả Oùc, vua Ba-san, và toàn thể dân sự người; chúng ta đã đánh bại người đến nỗi không còn để lại cho người một kẻ sống sót nào.'),
(4980, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 3, 4, 'OT', 'Bấy giờ chúng ta chiếm lấy tất cả các thành của người; không có thành nào mà chúng ta không chiếm lấy từ tay người; sáu mươi thành, toàn thể vùng Aït-gốp, là vương quốc của Oùc trong xứ Ba-san.'),
(4981, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 3, 5, 'OT', 'Tất cả những thành nầy đều có vách thành cao, cửa và then khóa; chỉ trừ các thành của người Phê-rê-xi rất nhiều.'),
(4982, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 3, 6, 'OT', 'Chúng ta đã biệt sự cho Đức Giê-hô-va sự diệt tận, y như điều chúng ta đã làm cho Si-hôn, vua Hết-bôn, tức là diệt tận mọi thành, các người nam, người nữ và con trẻ.'),
(4983, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 3, 7, 'OT', 'Chúng ta chiếm lấy về mình tất cả súc vật và hóa tài của các thành ấy.'),
(4984, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 3, 8, 'OT', 'Vào lúc ấy, chúng ta đã chiếm lấy vùng đất từ tay hai vua A-mô-rít, là xứ bên kia sông Giô-đanh, từ khe Aït-nnôn cho đến núi Hẹt-môn.'),
(4985, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 3, 9, 'OT', 'Dân Si-đôn gọi Hẹt-môn là Si-ri-ôn, còn dân A-mô-rít gọi nó là Sê-ni-rơ.'),
(4986, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 3, 10, 'OT', 'Toàn thể các thành thuộc đồng bằng, toàn thể Ga-la-át, toàn thể Ba-san, cho đến Sanh-ca và Eát-rê-i, là các thành của vương quốc Oùc trong Ba-san.'),
(4987, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 3, 11, 'OT', 'Vì chỉ còn lại Oùc, vua xứ Ba-san, thuộc dòng dõi Rê-pha-im; nầy, cái giường bằng sắt của người, há chẳng phải ở tại Ráp-ba, thành của con cháu Am-môn sao? Chiều dài giường là chín thước, chiều ngang bốn thước, theo thước tay một người nam.'),
(4988, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 3, 12, 'OT', 'Và lúc ấy, chúng tôi đã chiếm lấy đất nầy, từ A-rô-e, nơi bên bờ suối Aït-nôn, và phân nửa núi Ga-la-át cùng các thành của nó, thì tôi đã ban cho chi phái Ru-bên và chi phái Gát.'),
(4989, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 3, 13, 'OT', 'Phần còn lại của Ga-la-át và toàn thể Ba-san, tức là vương quốc của Oùc, Ta đã ban cho phân nửa chi phái Ma-na-se: toàn vùng Aït-gốp, thuộc về toàn thể Ba-san, là nơi được gọi là đất nước của dân Rê-pha-im.'),
(4990, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 3, 14, 'OT', 'Giai-rơ, con trai của Ma-na-se, đã chiếm lấy toàn bộ vùng Aït-gốp cho đến ranh giới của người Ghê-su-rít và người Ma-ca-thít, và ông đặt tên cho các nơi ấy theo danh ông là các làng của Giai-rơ trong xứ Ba-san, cho đến ngày nay.'),
(4991, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 3, 15, 'OT', 'Ta đã ban cho Ma-ki phần đất của Ga-la-át.'),
(4992, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 3, 16, 'OT', 'Ta đã ban cho con cháu Ru-bên và con cháu Gát từ Ga-la-át cho đến khe Aït-nôn, giữa khe ấy và ranh giới, cho đến khe Gia-bốt, là ranh giới của con cháu Am-môn.'),
(4993, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 3, 17, 'OT', 'Vùng đồng bằng và sông Giô-đanh, với phần đất giáp giới, từ hồ Ki-nê-rết cho đến Biển mặn, là biển của đồng bằng, ở dưới các sườn đồi của núi Phích-ga về phía đông.'),
(4994, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 3, 18, 'OT', 'Trong lúc ấy, ta đã truyền cho các ngươi rằng: Đức Giê-hô-va Đức Chúa Trời các ngươi đã ban cho các ngươi đất nầy để chiếm làm sản nghiệp; các ngươi, tất cả những chiến sĩ, phải đi qua trước mặt anh em mình, là con cháu Y-sơ-ra-ên.'),
(4995, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 3, 19, 'OT', 'Nhưng các vợ, con nhỏ và súc vật của các ngươi—ta biết rằng các ngươi có rất nhiều súc vật—sẽ ở lại trong các thành mà ta đã ban cho các ngươi.'),
(4996, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 3, 20, 'OT', 'Cho đến khi Đức Giê-hô-va khiến anh em các ngươi được an nghỉ như các ngươi, và họ cũng chiếm hữu đất mà Đức Giê-hô-va Đức Chúa Trời các ngươi ban cho họ bên kia sông Giô-đanh; bấy giờ mỗi người các ngươi sẽ trở về sản nghiệp mình, là điều mà ta đã ban cho các ngươi.'),
(4997, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 3, 21, 'OT', 'Và tại thời điểm ấy, ta đã dặn Giô-suê rằng: "Mắt ngươi đã thấy tất cả những gì Đức Giê-hô-va Đức Chúa Trời các ngươi đã làm cho hai vua nầy; chính như vậy, Đức Giê-hô-va sẽ làm cho mọi nước mà ngươi sắp đi qua."'),
(4998, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 3, 22, 'OT', 'Đừng sợ chúng, vì chính Đức Giê-hô-va Đức Chúa Trời các ngươi chiến đấu cho các ngươi.'),
(4999, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 3, 23, 'OT', 'Ta đã khẩn cầu Đức Giê-hô-va trong lúc ấy, mà rằng:'),
(5000, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 3, 24, 'OT', 'Lạy Đức Giê-hô-va, chính Ngài đã khởi sự tỏ cho kẻ tôi tớ Ngài thấy sự lớn lao của Ngài và tay quyền năng của Ngài; vì trên trời dưới đất, nào có thần nào làm được việc và công việc quyền năng giống như việc và công việc quyền năng của Ngài?'),
(5001, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 3, 25, 'OT', 'Xin hãy để tôi đi qua và xem đất tốt lành bên kia sông Giô-đanh, núi tốt lành nầy và Li-ban.'),
(5002, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 3, 26, 'OT', 'Nhưng Đức Giê-hô-va nổi giận cùng tôi vì cớ các ngươi, và không nghe lời tôi; Đức Giê-hô-va phán cùng tôi rằng: Đủ rồi cho ngươi; chớ còn nói cùng Ta nữa về việc nầy.'),
(5003, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 3, 27, 'OT', 'Hãy đi lên chót núi Phích-ga, ngước mắt ngươi lên về hướng tây, bắc, nam và đông mà nhìn xem bằng chính mắt ngươi, vì ngươi sẽ không qua sông Giô-đanh nầy đâu.'),
(5004, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 3, 28, 'OT', 'Hãy truyền lệnh cho Giô-suê, và làm cho người vững mạnh, bền chí; vì chính người sẽ đi qua trước mặt dân sự nầy, và chính người sẽ khiến họ nhận được xứ mà ngươi sẽ nhìn thấy.'),
(5005, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 3, 29, 'OT', 'Chúng ta ở trong trũng, đối ngang Bết-Phê-o.'),
(5006, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 1, 'OT', 'Hỡi Y-sơ-ra-ên, bây giờ hãy nghe những luật lệ và mạng lịnh mà ta dạy các ngươi để làm, hầu các ngươi được sống, vào và chiếm lấy đất mà Đức Giê-hô-va Đức Chúa Trời của tổ phụ các ngươi ban cho các ngươi.'),
(5007, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 2, 'OT', 'Các ngươi chớ thêm điều gì vào lời ta truyền cho các ngươi, cũng đừng bớt đi điều gì từ đó, để giữ các điều răn của Đức Giê-hô-va Đức Chúa Trời các ngươi mà ta truyền cho các ngươi.'),
(5008, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 3, 'OT', 'Mắt các ngươi đã thấy điều Đức Giê-hô-va đã làm tại Ba-anh-Phê-ô, vì mọi người nào đi theo Ba-anh-Phê-ô thì Đức Giê-hô-va Đức Chúa Trời ngươi đã tiêu diệt khỏi giữa các ngươi.'),
(5009, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 4, 'OT', 'Còn các ngươi, là những kẻ níu chặt vào Giê-hô-va Đức Chúa Trời mình, ngày nay tất cả đều còn sống.'),
(5010, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 5, 'OT', 'Nầy, ta đã dạy cho các ngươi các mạng lịnh và luật lệ như Giê-hô-va Đức Chúa Trời ta đã truyền cho ta, để làm theo trong xứ mà các ngươi sẽ vào để chiếm hữu.'),
(5011, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 6, 'OT', 'Các ngươi phải giữ gìn và thực hành, vì ấy là sự khôn ngoan và thông sáng của các ngươi trước mắt các dân, là những kẻ sẽ nghe biết mọi luật lệ nầy và nói rằng: "Chỉ có dân lớn này là dân khôn ngoan và sáng suốt!"'),
(5012, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 7, 'OT', 'Vả lại, có dân nào lớn bằng dân nầy, mà có Đức Chúa Trời gần gũi họ như Giê-hô-va Đức Chúa Trời chúng ta gần gũi chúng ta, mỗi khi chúng ta kêu cầu Ngài?'),
(5013, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 8, 'OT', 'Có dân nào lớn bằng dân nầy, có những mạng lịnh và luật lệ công bình như cả luật pháp nầy, mà ngày nay ta đặt trước mặt các ngươi?'),
(5014, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 9, 'OT', 'Chỉ hãy giữ mình và giữ gìn linh hồn ngươi cách kỹ lưỡng, e ngươi quên những điều mà mắt ngươi đã thấy, và e những điều đó rời khỏi lòng ngươi trọn mọi ngày trong đời ngươi; ngươi phải dạy cho các con ngươi và các con của các con ngươi.'),
(5015, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 10, 'OT', 'Hãy nhớ ngày ngươi đứng trước mặt Đức Giê-hô-va Đức Chúa Trời ngươi tại Hô-rếp, khi Đức Giê-hô-va phán cùng ta rằng: "Hãy nhóm lại cho ta dân sự, để ta khiến chúng nghe các lời ta, hầu cho chúng học biết kính sợ ta mọi ngày chúng còn sống trên đất, và dạy con cái mình."'),
(5016, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 11, 'OT', 'Các ngươi lại gần và đứng dưới chân núi; và núi ấy cháy trong lửa, vươn lên tận lòng trời, giữa cảnh tối tăm, mây đen và sự u ám.'),
(5017, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 12, 'OT', 'Đức Giê-hô-va phán cùng các ngươi từ trong lửa; các ngươi nghe tiếng các lời nói, nhưng không thấy hình dạng nào, chỉ nghe tiếng mà thôi.'),
(5018, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 13, 'OT', 'Ngài đã công bố cho các ngươi biết giao ước của Ngài, mà Ngài truyền cho các ngươi phải thực hiện, tức là mười điều răn, và Ngài đã chép chúng trên hai bảng đá.'),
(5019, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 14, 'OT', 'Đức Giê-hô-va cũng truyền lịnh cho ta trong lúc đó phải dạy các ngươi các luật lệ và án lệ, để các ngươi thực hành chúng trong đất mà các ngươi sẽ sang đó để chiếm hữu.'),
(5020, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 15, 'OT', 'Vậy, các ngươi hãy giữ gìn rất cẩn thận lấy mạng sống mình, vì các ngươi không thấy hình dạng nào hết trong ngày Đức Giê-hô-va phán cùng các ngươi tại Hô-rếp từ giữa ngọn lửa.'),
(5021, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 16, 'OT', 'e các ngươi làm hư mất mình, mà làm tượng chạm nào, hình tượng của bất cứ vật gì, hình người nam hay người nữ,'),
(5022, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 17, 'OT', 'hoặc hình tượng mọi loài vật trên đất, hoặc hình tượng mọi loài chim có cánh bay trên trời,'),
(5023, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 18, 'OT', 'hoặc hình dạng của mọi loài sinh vật bò trên đất, hay hình dạng của mọi loài cá ở trong nước dưới đất;'),
(5024, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 19, 'OT', 'Hãy coi chừng, e khi ngươi ngước mắt lên trời mà thấy mặt trời, mặt trăng, các ngôi sao, tức là toàn thể đạo binh trên trời, thì ngươi bị dẫn dụ mà quì lạy và thờ lạy các vì đó, là điều mà Đức Giê-hô-va Đức Chúa Trời ngươi đã phân định cho mọi dân trên toàn cõi đất dưới trời.'),
(5025, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 20, 'OT', 'Còn các ngươi, Đức Giê-hô-va đã lấy các ngươi ra khỏi lò lửa bằng sắt, tức là xứ Ê-díp-tô, để làm cho các ngươi trở nên dân thuộc về Ngài, như ngày nay vậy.'),
(5026, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 21, 'OT', 'Đức Giê-hô-va nổi giận tôi vì cớ các ngươi, và đã thề rằng tôi sẽ không được qua sông Giô-đanh, cũng không được vào đất tốt mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi làm sản nghiệp.'),
(5027, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 22, 'OT', 'Vì ta phải chết trong đất nầy, không được qua sông Giô-đanh; nhưng các ngươi sẽ qua và chiếm lấy đất tốt lành nầy.'),
(5028, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 23, 'OT', 'Hãy giữ lấy mình, kẻo quên sự giao ước của Đức Giê-hô-va Đức Chúa Trời các ngươi, mà Ngài đã lập với các ngươi; và các ngươi chớ làm cho mình tượng chạm hay hình tượng của bất cứ vật gì mà Đức Giê-hô-va Đức Chúa Trời ngươi đã cấm ngươi.'),
(5029, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 24, 'OT', 'Vì Đức Giê-hô-va Đức Chúa Trời ngươi là lửa thiêu đốt, là Đức Chúa Trời hay ghen.'),
(5030, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 25, 'OT', 'Khi các ngươi sinh con và cháu, sống lâu đời trên đất và trở nên bại hoại, làm tượng chạm hay hình tượng của bất cứ vật gì, làm điều ác trước mặt Đức Giê-hô-va Đức Chúa Trời các ngươi để chọc giận Ngài,'),
(5031, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 26, 'OT', 'Hôm nay ta bắt trời và đất làm chứng cho các ngươi rằng các ngươi sẽ chết vội, và khuất mắt khỏi đất mà các ngươi sẽ qua sông Giô-đanh để nhận lấy; các ngươi sẽ không sống lâu trên đất ấy, vì các ngươi sẽ bị tiêu diệt.'),
(5032, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 27, 'OT', 'Đức Giê-hô-va sẽ tản lạc các ngươi trong các dân, và các ngươi sẽ còn sót lại một số ít trong các nước mà Đức Giê-hô-va dẫn các ngươi đến đó.'),
(5033, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 28, 'OT', 'Các ngươi sẽ hầu việc các thần ở đó, là những vật do tay người làm ra, bằng gỗ và bằng đá, không thấy, không nghe, không ăn, không ngửi.'),
(5034, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 29, 'OT', 'Nhưng tại đó, các ngươi sẽ tìm cầu Đức Giê-hô-va Đức Chúa Trời ngươi, và các ngươi sẽ gặp Ngài, nếu các ngươi hết lòng hết dạ tìm cầu Ngài.'),
(5035, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 30, 'OT', 'Khi ngươi bị gian nan và hết thảy các điều nầy xảy đến cho ngươi, trong những ngày cuối cùng, ngươi sẽ trở lại cùng Đức Giê-hô-va Đức Chúa Trời ngươi và nghe theo tiếng Ngài.'),
(5036, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 31, 'OT', 'Vì Đức Giê-hô-va Đức Chúa Trời ngươi là Đức Chúa Trời hay thương xót, Ngài sẽ không buông thả ngươi, không tiêu diệt ngươi, và không quên giao ước mà Ngài đã thề cùng các tổ phụ ngươi.'),
(5037, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 32, 'OT', 'Hãy hỏi thử thời xưa, từ ngày Đức Chúa Trời dựng nên loài người trên đất cho đến tận cùng các trời, có bao giờ xảy ra điều lớn lao như điều nầy chăng, hay là có nghe điều gì giống như vậy chăng?'),
(5038, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 33, 'OT', 'Há có dân nào đã nghe tiếng Đức Chúa Trời phán từ trong lửa như ngươi đã nghe, mà vẫn còn sống?'),
(5039, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 34, 'OT', 'Hay có Đức Chúa Trời nào đã thử nghiệm để đi lấy một dân tộc ra khỏi lòng một dân tộc khác bằng các thử thách, các dấu kỳ, các điềm lạ, cuộc chiến tranh, bằng tay hùng mạnh, cánh tay giơ thẳng ra và các sự kinh khủng lớn lao, như mọi điều Đức Giê-hô-va Đức Chúa Trời các ngươi đã làm cho các ngươi tại Ai Cập, ngay trước mắt các ngươi?'),
(5040, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 35, 'OT', 'Ngươi đã được thấy, để biết rằng Đức Giê-hô-va chính là Đức Chúa Trời, ngoài Ngài ra không có thần nào khác.'),
(5041, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 36, 'OT', 'Từ trên trời, Đức Giê-hô-va khiến ngươi nghe tiếng của Ngài để dạy dỗ ngươi; còn trên đất, Ngài cho ngươi thấy đám lửa lớn của Ngài, và ngươi đã nghe các lời của Ngài từ giữa đám lửa.'),
(5042, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 37, 'OT', 'vì Ngài đã yêu các tổ phụ ngươi, nên chọn dòng dõi của họ, và chính tay Ngài dùng quyền năng lớn đưa ngươi ra khỏi Ai Cập,'),
(5043, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 38, 'OT', 'để đuổi khỏi trước mặt ngươi các dân tộc lớn và mạnh hơn ngươi, và dẫn ngươi vào đất của các dân ấy mà ban cho làm sản nghiệp, như ngày nay vậy.'),
(5044, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 39, 'OT', 'Vậy hôm nay, hãy biết và đem lòng suy xét rằng chính Đức Giê-hô-va là Đức Chúa Trời, trên các từng trời ở phía trên và trên đất ở phía dưới; chẳng có ai khác.'),
(5045, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 40, 'OT', 'Ngươi phải giữ các luật lệ và các điều răn của Ngài, mà ngày nay ta truyền cho ngươi, để ngươi được phước và con cháu ngươi sau ngươi cũng được phước, và để ngươi sống lâu trên đất mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi luôn luôn.'),
(5046, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 41, 'OT', 'Bấy giờ Môi-se biệt ra ba thành ở bên kia sông Giô-đanh, về hướng mặt trời mọc,'),
(5047, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 42, 'OT', 'để kẻ nào giết người lân cận mình vô ý, mà trước đó không có ghét người ấy, có thể chạy trốn đến một trong những thành nầy và được sống.'),
(5048, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 43, 'OT', 'Bết-se trong đồng vắng, tại xứ đồng bằng, cho người Ru-bên; Ra-mốt trong Ga-la-át cho người Gát; và Gô-lan trong Ba-san cho người Ma-na-se.'),
(5049, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 44, 'OT', 'Nầy là luật pháp mà Môi-se đặt trước mặt con cái Y-sơ-ra-ên.'),
(5050, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 45, 'OT', 'Nầy là những chứng cớ, những mạng lịnh và những luật lệ mà Môi-se đã truyền cho con cái Y-sơ-ra-ên khi họ ra khỏi xứ Ê-díp-tô.'),
(5051, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 46, 'OT', 'Bên kia sông Giô-đanh, trong trũng, đối ngang Bết-Phê-o, tại đất của Si-hôn, vua dân A-mô-rít, ở Hết-bôn, là người mà Môi-se và các con trai Y-sơ-ra-ên đã đánh bại khi ra khỏi Ai-cập.'),
(5052, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 47, 'OT', 'Dân Y-sơ-ra-ên chiếm lấy đất của hai vua dân A-mô-rít, là đất người và đất của Oùc, vua Ba-san, ở bên kia sông Giô-đanh về phía mặt trời mọc, từ A-rô-e'),
(5053, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 48, 'OT', 'từ A-roi, nằm trên bờ khe Aït-nôn, cho đến núi Si-ôn, tức là Hẹt-môn,'),
(5054, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 4, 49, 'OT', 'Toàn thể vùng đồng bằng bên kia sông Giô-đanh về phía đông, cho đến Biển Đồng Bằng, dưới các sườn núi Phích-ga.'),
(5055, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 1, 'OT', 'Môi-se gọi cả Y-sơ-ra-ên mà nói rằng: Hỡi Y-sơ-ra-ên, hãy nghe những luật lệ và mạng lịnh mà hôm nay ta truyền cho các ngươi; các ngươi phải học tập và giữ cẩn thận để thực hành.'),
(5056, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 2, 'OT', 'Giê-hô-va Đức Chúa Trời chúng ta đã lập giao ước với chúng ta tại Hô-rếp.'),
(5057, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 3, 'OT', 'Chẳng phải cùng tổ phụ chúng ta mà Đức Giê-hô-va đã lập giao ước nầy, nhưng cùng chính chúng ta, tất cả những người hiện nay còn sống ở đây.'),
(5058, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 4, 'OT', 'Đức Giê-hô-va phán cùng các ngươi mặt đối mặt tại trên núi, từ giữa trong đám lửa.'),
(5059, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 5, 'OT', 'Ta đứng giữa Đức Giê-hô-va và các ngươi trong lúc ấy, để truyền lại cho các ngươi lời của Đức Giê-hô-va, vì các ngươi sợ hãi trước mặt ngọn lửa, nên không lên trên núi; Ngài phán rằng:'),
(5060, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 6, 'OT', 'Ta là Đức Giê-hô-va Đức Chúa Trời ngươi, Đấng đã đem ngươi ra khỏi đất nước Ai Cập, khỏi nhà nô lệ.'),
(5061, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 7, 'OT', 'Ngươi không được có các thần khác trước mặt ta.'),
(5062, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 8, 'OT', 'Ngươi chớ làm tượng chạm cho mình, cũng chớ làm hình tượng nào giống như những vật ở trên trời cao, hoặc ở dưới đất thấp, hoặc trong nước dưới mặt đất.'),
(5063, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 9, 'OT', 'Ngươi chớ thờ lạy chúng nó, cũng đừng hầu việc chúng nó; vì ta là Giê-hô-va Đức Chúa Trời ngươi, Đức Chúa Trời đầy lòng ghen, phạt tội tổ phụ đến con cháu, đến thế hệ thứ ba, thứ tư của những kẻ ghét ta.'),
(5064, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 10, 'OT', 'và làm ơn đến ngàn đời cho những kẻ yêu mến ta và giữ các điều răn ta.'),
(5065, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 11, 'OT', 'Ngươi chớ lấy danh Đức Giê-hô-va Đức Chúa Trời ngươi mà làm vô ích; vì Đức Giê-hô-va không để kẻ nào lấy danh Ngài mà làm vô ích thì thoát khỏi tội.'),
(5066, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 12, 'OT', 'Hãy giữ ngày Sa-bát, để làm nên thánh, y như Giê-hô-va Đức Chúa Trời ngươi đã truyền cho ngươi.'),
(5067, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 13, 'OT', 'Trong sáu ngày, ngươi phải làm việc và làm mọi công việc của mình;'),
(5068, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 14, 'OT', 'Nhưng ngày thứ bảy là ngày Sa-bát dành cho Đức Giê-hô-va Đức Chúa Trời ngươi; ngươi không được làm bất cứ công việc gì, cả ngươi, con trai, con gái, đầy tớ trai, tớ gái, bò, lừa, mọi súc vật của ngươi, và khách ngoại kiều ở trong các cổng thành ngươi, hầu cho đầy tớ trai và tớ gái ngươi được nghỉ ngơi như ngươi.'),
(5069, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 15, 'OT', 'Hãy nhớ rằng ngươi đã làm tôi mọi trong đất Ê-díp-tô, và Đức Giê-hô-va Đức Chúa Trời ngươi đã đem ngươi ra khỏi đó bằng tay mạnh và cánh tay giơ thẳng; bởi vậy Đức Giê-hô-va Đức Chúa Trời ngươi truyền cho ngươi phải giữ ngày Sa-bát.'),
(5070, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 16, 'OT', 'Hãy tôn trọng cha ngươi và mẹ ngươi, như Đức Giê-hô-va Đức Chúa Trời ngươi đã truyền cho ngươi, để các ngày của ngươi được dài lâu và để ngươi được thịnh vượng trên đất mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi.'),
(5071, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 17, 'OT', 'Ngươi không được giết người.'),
(5072, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 18, 'OT', 'Ngươi chớ phạm tội thông dâm.'),
(5073, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 19, 'OT', 'Ngươi không được trộm cắp.'),
(5074, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 20, 'OT', 'Ngươi chớ làm chứng dối cho người lân cận mình.'),
(5075, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 21, 'OT', 'Ngươi không được tham vợ của người lân cận mình; không được thèm muốn nhà của người, ruộng đất, tôi trai, tớ gái, bò, lừa, hay bất cứ điều gì thuộc về người lân cận ngươi.'),
(5076, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 22, 'OT', 'Đức Giê-hô-va đã phán các lời nầy cho cả hội chúng ngươi tại trên núi, từ giữa lửa, mây và sự tối tăm, bằng tiếng lớn, và không thêm chi nữa; rồi Ngài chép các lời đó trên hai bảng đá và trao cho ta.'),
(5077, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 23, 'OT', 'Khi các ngươi nghe tiếng từ giữa chỗ tối tăm, và ngọn núi bốc lửa cháy, thì tất cả các trưởng tộc của các chi phái và các trưởng lão các ngươi đã đến gần ta.'),
(5078, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 24, 'OT', 'Chúng tôi nói: Này, Đức Giê-hô-va Đức Chúa Trời chúng tôi đã cho chúng tôi thấy sự vinh hiển và sự lớn lao của Ngài, và chúng tôi đã nghe tiếng Ngài từ giữa lửa; ngày nay chúng tôi thấy rằng Đức Chúa Trời phán cùng loài người và người ấy vẫn sống.'),
(5079, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 25, 'OT', 'Bây giờ, tại sao chúng tôi phải chết? Vì ngọn lửa lớn này sẽ thiêu cháy chúng tôi; nếu chúng tôi còn tiếp tục nghe tiếng của Đức Giê-hô-va Đức Chúa Trời chúng tôi, thì chúng tôi sẽ chết.'),
(5080, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 26, 'OT', 'Vì trong loài người, có ai đã nghe tiếng Đức Chúa Trời hằng sống phán ra từ giữa lửa như chúng tôi mà vẫn còn sống?'),
(5081, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 27, 'OT', 'Hãy đến gần mà nghe mọi điều mà Đức Giê-hô-va Đức Chúa Trời chúng ta sẽ phán; rồi chính ngươi sẽ nói lại cho chúng ta mọi điều mà Đức Giê-hô-va Đức Chúa Trời chúng ta phán với ngươi, và chúng ta sẽ nghe mà làm theo.'),
(5082, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 28, 'OT', 'Đức Giê-hô-va đã nghe tiếng các lời các ngươi nói khi các ngươi nói với ta; Đức Giê-hô-va phán cùng ta rằng: Ta đã nghe tiếng các lời dân sự nầy nói với ngươi; điều chúng nó nói mọi điều đó là phải.'),
(5083, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 29, 'OT', 'Ôi! Phải chi lòng chúng nó luôn kính sợ Ta và giữ mọi điều răn của Ta mọi ngày, để chúng nó và con cháu chúng nó được phước đời đời!'),
(5084, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 30, 'OT', 'Hãy đi, nói cùng họ rằng: Hãy trở về trại mình;'),
(5085, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 31, 'OT', 'Còn ngươi, hãy đứng đây cùng ta, để ta truyền cho ngươi mọi điều răn, luật lệ và án lệ mà ngươi sẽ dạy chúng nó, hầu chúng nó thực hiện trong đất mà ta sắp ban cho chúng để chiếm hữu.'),
(5086, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 32, 'OT', 'Vậy, các ngươi phải giữ cẩn thận làm theo như Đức Giê-hô-va Đức Chúa Trời các ngươi đã truyền cho các ngươi; không được xây qua bên phải hoặc bên trái.'),
(5087, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 5, 33, 'OT', 'Các ngươi phải đi theo mọi con đường mà Đức Giê-hô-va Đức Chúa Trời các ngươi đã truyền dặn cho các ngươi, để các ngươi được sống, được phước, và sống lâu trên đất mà các ngươi sẽ chiếm hữu.'),
(5088, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 6, 1, 'OT', 'Và đây là điều răn, các luật lệ và các mạng lệnh mà Đức Giê-hô-va Đức Chúa Trời các ngươi đã truyền cho ta dạy các ngươi, để các ngươi làm theo trong đất mà các ngươi qua đó để nhận lấy;'),
(5089, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 6, 2, 'OT', 'để ngươi kính sợ Đức Giê-hô-va Đức Chúa Trời ngươi, giữ mọi luật lệ và mạng lịnh mà ta truyền cho ngươi, ngươi và con ngươi và con trai của con ngươi, trọn mọi ngày trong đời ngươi, hầu cho các ngày của ngươi được kéo dài.'),
(5090, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 6, 3, 'OT', 'Hỡi Y-sơ-ra-ên, ngươi hãy nghe và phải cẩn thận làm theo, hầu cho ngươi được phước và sinh sản ra rất nhiều, y như Giê-hô-va Đức Chúa Trời của tổ phụ ngươi đã phán cùng ngươi về đất chảy sữa và mật.'),
(5091, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 6, 4, 'OT', 'Hỡi Y-sơ-ra-ên, hãy nghe: Đức Giê-hô-va Đức Chúa Trời chúng ta, Đức Giê-hô-va là một.'),
(5092, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 6, 5, 'OT', 'Ngươi phải hết lòng, hết mạng sống, hết sức lực yêu Giê-hô-va Đức Chúa Trời ngươi.'),
(5093, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 6, 6, 'OT', 'Các lời nầy mà ta truyền cho ngươi ngày nay sẽ ở trong lòng ngươi;'),
(5094, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 6, 7, 'OT', 'Hãy hết lòng dạy dỗ điều đó cho con cái ngươi; và phải nói đến nó, khi ngồi trong nhà, khi đi ngoài đường, khi nằm xuống hay khi chổi dậy.'),
(5095, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 6, 8, 'OT', 'Hãy buộc chúng làm dấu trên tay ngươi, và chúng sẽ trở thành ấn trên trán ngươi.'),
(5096, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 6, 9, 'OT', 'Cũng phải viết chúng trên khung cửa và các cổng nhà ngươi.'),
(5097, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 6, 10, 'OT', 'Khi Đức Giê-hô-va Đức Chúa Trời dẫn ngươi vào đất mà Ngài đã thề cùng các tổ phụ ngươi, là Aùp-ra-ham, Y-sác và Gia-cốp, để ban cho ngươi, thì ngươi sẽ nhận được những thành lớn và tốt mà ngươi không xây cất;'),
(5098, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 6, 11, 'OT', 'những nhà đầy đủ mọi điều tốt lành mà ngươi không xây đầy, những giếng đã đào sẵn mà ngươi không đào, những vườn nho và cây ô-liu mà ngươi không trồng; ngươi sẽ ăn và được no đủ,'),
(5099, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 6, 12, 'OT', 'Khá giữ mình, kẻo ngươi quên Đức Giê-hô-va, là Đấng đã đem ngươi ra khỏi xứ Ai Cập, khỏi nhà tôi mọi.'),
(5100, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 6, 13, 'OT', 'Ngươi phải kính sợ Đức Giê-hô-va Đức Chúa Trời ngươi, phục sự Ngài, và lấy danh Ngài mà thề.'),
(5101, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 6, 14, 'OT', 'Chớ đi theo các thần khác, trong những thần của các dân tộc ở chung quanh các ngươi,'),
(5102, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 6, 15, 'OT', 'vì Đức Giê-hô-va Đức Chúa Trời ngươi là Đức Chúa Trời ganh, ngự giữa ngươi, e cơn thạnh nộ của Đức Giê-hô-va Đức Chúa Trời ngươi nổi lên cùng ngươi, và Ngài tiêu diệt ngươi khỏi mặt đất.'),
(5103, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 6, 16, 'OT', 'Các ngươi chớ thử Đức Giê-hô-va Đức Chúa Trời các ngươi như các ngươi đã thử Ngài tại Ma-sa.'),
(5104, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 6, 17, 'OT', 'Hãy hết sức giữ gìn các điều răn, các lời chứng và các luật lệ của Đức Giê-hô-va Đức Chúa Trời các ngươi mà Ngài đã truyền cho các ngươi.'),
(5105, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 6, 18, 'OT', 'Ngươi phải làm điều ngay thẳng và tốt lành trước mặt Đức Giê-hô-va, để điều lành đến cho ngươi, và ngươi sẽ vào chiếm lấy đất tốt đẹp mà Đức Giê-hô-va đã thề hứa cùng tổ phụ ngươi.'),
(5106, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 6, 19, 'OT', 'để đuổi mọi kẻ thù nghịch ngươi ra khỏi trước mặt ngươi, y như Đức Giê-hô-va đã phán.'),
(5107, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 6, 20, 'OT', 'Ngày mai, khi con ngươi hỏi ngươi mà nói rằng: Các điều răn, các luật lệ và các mạng lịnh mà Đức Giê-hô-va Đức Chúa Trời chúng ta đã truyền cho các ngươi là gì?'),
(5108, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 6, 21, 'OT', 'Hãy nói cho con trai ngươi rằng: Chúng ta đã làm tôi mọi cho Pha-ra-ôn tại Ai-cập, và Đức Giê-hô-va dùng tay mạnh mẽ đem chúng ta ra khỏi Ai-cập.'),
(5109, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 6, 22, 'OT', 'Đức Giê-hô-va đã làm những dấu kỳ và phép lạ lớn và kinh khủng tại Ai-cập, trước mắt chúng ta, trên Pha-ra-ôn và trên cả nhà người.'),
(5110, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 6, 23, 'OT', 'Ngài đã đem chúng ta ra khỏi nơi ấy, để dẫn chúng ta vào đất mà Ngài đã thề hứa cùng tổ phụ chúng ta, mà ban cho chúng ta.'),
(5111, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 6, 24, 'OT', 'Đức Giê-hô-va đã truyền cho chúng ta phải làm theo các luật lệ này, để kính sợ Đức Giê-hô-va Đức Chúa Trời chúng ta, hầu cho chúng ta được phước mọi ngày, và để Ngài giữ cho chúng ta sống như ngày nay.'),
(5112, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 6, 25, 'OT', 'Và sự công bình sẽ thuộc về chúng ta, khi chúng ta cẩn thận tuân giữ làm theo trọn các điều răn nầy trước mặt Đức Giê-hô-va Đức Chúa Trời chúng ta, như Ngài đã truyền cho chúng ta.'),
(5113, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 7, 1, 'OT', 'Khi Đức Giê-hô-va Đức Chúa Trời ngươi dẫn ngươi vào đất ngươi sắp vào để chiếm lấy, thì Ngài sẽ đuổi ra khỏi trước mặt ngươi nhiều dân tộc, là dân Hê-tít, dân Ghi-rê-ga-sít, dân A-mô-rít, dân Ca-na-an, dân Phê-rê-sít, dân Hê-vít và dân Giê-bu-sít, tức bảy dân tộc đông và mạnh hơn ngươi.'),
(5114, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 7, 2, 'OT', 'Khi Đức Giê-hô-va Đức Chúa Trời ngươi phó các dân ấy cho ngươi, ngươi phải đánh bại chúng; ngươi phải tận diệt chúng, chớ lập giao ước với chúng, và cũng không được thương xót chúng.'),
(5115, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 7, 3, 'OT', 'Ngươi chớ kết thông gia với chúng; con gái ngươi, ngươi chớ gả cho con trai họ, và con gái họ, ngươi chớ cưới cho con trai ngươi.'),
(5116, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 7, 4, 'OT', 'vì nó sẽ làm cho con trai ngươi lìa bỏ Ta mà phục sự các thần khác; rồi cơn thạnh nộ của Đức Giê-hô-va sẽ nổi lên cùng các ngươi, và Ngài sẽ diệt các ngươi cách mau chóng.'),
(5117, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 7, 5, 'OT', 'Nhưng các ngươi phải làm điều này cho chúng: phải phá các bàn thờ của chúng, đập bể các trụ đá, chặt các thần A-sê-ra của chúng, và đốt các tượng chạm của chúng trong lửa.'),
(5118, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 7, 6, 'OT', 'Vì ngươi là dân thánh dành cho Đức Giê-hô-va Đức Chúa Trời ngươi; chính ngươi, Đức Giê-hô-va Đức Chúa Trời ngươi đã chọn để trở nên dân thuộc riêng về Ngài giữa muôn dân trên mặt đất.'),
(5119, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 7, 7, 'OT', 'Đức Giê-hô-va không yêu thương các ngươi và chọn các ngươi vì các ngươi đông hơn mọi dân, nhưng chính vì các ngươi là dân ít hơn mọi dân.'),
(5120, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 7, 8, 'OT', 'Nhưng ấy là vì Đức Giê-hô-va yêu thương các ngươi và giữ giao ước mà Ngài đã thề cùng tổ phụ các ngươi, nên Đức Giê-hô-va đã đem các ngươi ra bằng tay quyền năng, chuộc các ngươi khỏi nhà nô lệ, khỏi tay Pha-ra-ôn, vua xứ Ê-díp-tô.'),
(5121, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 7, 9, 'OT', 'Vậy hãy biết rằng Giê-hô-va Đức Chúa Trời ngươi là Đức Chúa Trời, tức là Đức Chúa Trời thành tín, giữ giao ước và sự nhân từ cho những người yêu mến Ngài và tuân giữ các điều răn Ngài đến ngàn đời;'),
(5122, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 7, 10, 'OT', 'Và Ngài báo trả kẻ ghét Ngài ngay trước mặt, để tiêu diệt nó; không chậm trễ với kẻ ghét Ngài, Ngài sẽ báo trả ngay trước mặt nó.'),
(5123, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 7, 11, 'OT', 'Vậy, ngươi phải giữ điều răn, các luật lệ và các án lệ mà ta truyền cho ngươi ngày nay, để làm theo những điều ấy.'),
(5124, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 7, 12, 'OT', 'Vậy nên, nếu các ngươi vâng nghe các mạng lịnh nầy, giữ gìn và làm theo, thì Đức Giê-hô-va Đức Chúa Trời ngươi sẽ giữ giao ước và sự thương xót mà Ngài đã thề cùng tổ phụ các ngươi.'),
(5125, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 7, 13, 'OT', 'Đức Giê-hô-va sẽ yêu thương ngươi, ban phước cho ngươi và làm ngươi trở nên đông đảo; Ngài sẽ ban phước cho con cái ngươi trong lòng mẹ ngươi và sản vật đất đai ngươi, cho lúa mì, rượu mới và dầu ô-liu ngươi, cho bầy bò và bầy chiên ngươi, trên đất mà Đức Giê-hô-va đã thề cùng tổ phụ ngươi để ban cho ngươi.'),
(5126, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 7, 14, 'OT', 'Ngươi sẽ được phước hơn mọi dân; giữa vòng ngươi sẽ không có kẻ son sẻ, hay là con cái son sẻ, hay là súc vật của ngươi.'),
(5127, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 7, 15, 'OT', 'Đức Giê-hô-va sẽ dẹp khỏi ngươi mọi thứ bệnh tật, và các bệnh hiểm ác của xứ Ê-díp-tô mà ngươi đã biết, Ngài sẽ không giáng cho ngươi, mà giáng cho mọi kẻ ghét ngươi.'),
(5128, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 7, 16, 'OT', 'Ngươi phải ăn sạch mọi dân tộc mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi; mắt ngươi chớ thương xót chúng nó, và ngươi chớ hầu việc các thần của chúng nó, vì chúng sẽ là cái bẫy cho ngươi.'),
(5129, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 7, 17, 'OT', 'Nếu ngươi nói trong lòng mình: Các dân tộc nầy đông hơn ta, làm sao ta có thể đuổi chúng nó ra khỏi?'),
(5130, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 7, 18, 'OT', 'Đừng sợ chúng; hãy nhớ lại điều Đức Giê-hô-va Đức Chúa Trời ngươi đã làm cho Pha-ra-ôn và toàn thể người Ai Cập.'),
(5131, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 7, 19, 'OT', 'những sự thử thách lớn mà mắt ngươi đã thấy, những dấu hiệu, phép lạ, bàn tay quyền năng và cánh tay giơ ra, mà Đức Giê-hô-va Đức Chúa Trời ngươi dùng để đem ngươi ra: chính như vậy Đức Giê-hô-va Đức Chúa Trời ngươi sẽ làm cho mọi dân tộc mà ngươi sợ hãi trước mặt chúng.'),
(5132, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 7, 20, 'OT', 'Đức Giê-hô-va Đức Chúa Trời ngươi sẽ sai ong lỗ đến giữa chúng nó, cho đến khi những kẻ còn sót lại và trốn tránh khỏi ngươi bị diệt hết.'),
(5133, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 7, 21, 'OT', 'Đừng sợ chúng nó, vì Đức Giê-hô-va Đức Chúa Trời ngươi ở giữa ngươi, là Đức Chúa Trời lớn và đáng sợ.'),
(5134, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 7, 22, 'OT', 'Đức Giê-hô-va Đức Chúa Trời ngươi sẽ lần lần đuổi các dân tộc nầy khỏi trước mặt ngươi; ngươi không thể tiêu diệt chúng nó mau được, e rằng loài thú đồng thêm nhiều lên mà hãm hại ngươi.'),
(5135, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 7, 23, 'OT', 'Đức Giê-hô-va Đức Chúa Trời ngươi sẽ phó chúng nó cho ngươi, và khiến chúng nó kinh hoàng dữ dội, cho đến khi chúng nó bị tiêu diệt.'),
(5136, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 7, 24, 'OT', 'Ngài sẽ trao các vua chúng nó vào tay ngươi, và ngươi phải tiêu diệt danh chúng nó khỏi dưới trời; không một ai sẽ đứng vững trước mặt ngươi, cho đến khi ngươi đã tiêu diệt sạch chúng nó.'),
(5137, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 7, 25, 'OT', 'Các tượng chạm về các thần chúng nó, ngươi phải thiêu đốt trong lửa. Chớ ham muốn bạc hay vàng trên các tượng ấy mà lấy cho mình, e rằng ngươi sẽ bị mắc bẫy; vì điều đó là sự gớm ghiếc cho Đức Giê-hô-va Đức Chúa Trời ngươi.'),
(5138, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 7, 26, 'OT', 'Chớ đem điều gớm ghiếc vào nhà ngươi, e ngươi sẽ bị tiêu diệt như nó; ngươi phải ghét nó cách trọn, và ghê tởm nó trọn, vì là vật đáng bị tiêu diệt.'),
(5139, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 8, 1, 'OT', 'Hãy giữ trọn mọi điều răn mà Đức Giê-hô-va truyền cho các ngươi ngày nay, để các ngươi được sống, được thêm đông và vào chiếm lấy đất mà Đức Giê-hô-va đã chỉ Đức Chúa Trời mà thề cùng tổ phụ các ngươi để ban cho các ngươi.'),
(5140, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 8, 2, 'OT', 'Hãy nhớ lại toàn thể con đường mà Đức Giê-hô-va Đức Chúa Trời ngươi đã dẫn ngươi đi trong bốn mươi năm nầy trong đồng vắng, để thử ngươi và rèn luyện ngươi, hầu biết được điều gì ở trong lòng ngươi, xem ngươi có giữ các điều răn của Ngài hay không.'),
(5141, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 8, 3, 'OT', 'Vậy Ngài làm cho ngươi bị yếu đuối, khiến ngươi phải đói, rồi cho ngươi ăn thứ ma-na mà ngươi chưa từng biết, tổ phụ ngươi cũng chưa từng biết, để dạy ngươi rằng loài người không sống chỉ nhờ bánh mà thôi, nhưng loài người sống nhờ mọi lời ra từ miệng Đức Giê-hô-va.'),
(5142, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 8, 4, 'OT', 'Áo xống ngươi không rách từ trên người ngươi, và chân ngươi không phù lên trong bốn mươi năm nầy.'),
(5143, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 8, 5, 'OT', 'Vậy, khá nhận biết trong lòng ngươi rằng chính như một người cha sửa phạt con mình, thì Đức Giê-hô-va Đức Chúa Trời ngươi cũng sửa phạt ngươi.'),
(5144, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 8, 6, 'OT', 'Hãy giữ các điều răn của Đức Giê-hô-va Đức Chúa Trời ngươi, đi trong các đường lối Ngài và kính sợ Ngài.'),
(5145, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 8, 7, 'OT', 'vì Đức Giê-hô-va Đức Chúa Trời ngươi sẽ dẫn ngươi vào một xứ tốt lành, một xứ có các khe nước, các suối và các vực sâu phun ra trong các thung lũng và trên các ngọn núi;'),
(5146, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 8, 8, 'OT', 'đất có lúa mì, lúa mạch, nho, vả và lựu; đất có dầu ô-liu và mật ong;'),
(5147, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 8, 9, 'OT', 'Đất ấy ngươi sẽ không thiếu thốn bánh, chẳng thiếu điều chi; đất ấy đá nó là sắt, và từ các núi nó ngươi sẽ đào đồng ra.'),
(5148, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 8, 10, 'OT', 'Ngươi sẽ ăn và no đủ, rồi phải chúc phước cho Đức Giê-hô-va Đức Chúa Trời ngươi vì đất tốt lành mà Ngài đã ban cho ngươi.'),
(5149, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 8, 11, 'OT', 'Hãy giữ mình cẩn thận, kẻo quên Đức Giê-hô-va Đức Chúa Trời ngươi, không giữ các điều răn, các luật lệ và các quy định Ngài truyền cho ngươi ngày nay.'),
(5150, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 8, 12, 'OT', 'e rằng khi ăn no rồi, xây nhà tốt để ở,'),
(5151, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 8, 13, 'OT', 'bò và chiên của ngươi sẽ sinh sôi thêm nhiều, bạc và vàng ngươi sẽ dồi dào, và mọi điều thuộc về ngươi sẽ gia tăng'),
(5152, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 8, 14, 'OT', 'thì lòng ngươi sẽ tự cao và quên Đức Giê-hô-va Đức Chúa Trời ngươi, là Đấng đã đem ngươi ra khỏi đất Ê-díp-tô, khỏi nhà nô lệ.'),
(5153, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 8, 15, 'OT', 'Đức Giê-hô-va dẫn ngươi đi qua đồng vắng lớn và đáng sợ, nơi có rắn lửa, bọ cạp và sự khát nước không có nước; Đấng khiến nước ngươi ra từ tảng đá cứng.'),
(5154, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 8, 16, 'OT', 'Đức Giê-hô-va khiến ngươi ăn ma-na trong đồng vắng, điều mà tổ phụ ngươi chưa từng biết, để thử thách ngươi và rèn luyện ngươi, hầu làm điều tốt lành cho ngươi về sau.'),
(5155, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 8, 17, 'OT', 'Vậy, khá coi chừng, chớ nói trong lòng rằng: chính sức lực tôi và quyền năng của tay tôi đã làm nên cho tôi tài sản này.'),
(5156, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 8, 18, 'OT', 'Hãy nhớ đến Đức Giê-hô-va Đức Chúa Trời ngươi, vì chính Ngài là Đấng ban cho ngươi sức lực để làm nên sự giàu có, hầu lập vững chắc giao ước Ngài đã chỉ Đức tay mà thề cùng tổ phụ ngươi, như ngày nay.'),
(5157, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 8, 19, 'OT', 'Nếu các ngươi quên Đức Giê-hô-va Đức Chúa Trời các ngươi, đi theo các thần khác, phục vụ chúng và thờ lạy chúng, thì ngày nay ta làm chứng trước mặt các ngươi rằng các ngươi sẽ bị tiêu diệt hoàn toàn.'),
(5158, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 8, 20, 'OT', 'Như các dân tộc mà Đức Giê-hô-va làm cho tiêu mất trước mặt các ngươi, các ngươi cũng sẽ bị tiêu mất, vì không nghe theo tiếng Đức Giê-hô-va Đức Chúa Trời các ngươi.'),
(5159, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 9, 1, 'OT', 'Hỡi Y-sơ-ra-ên, hãy nghe! Hôm nay ngươi sẽ đi qua sông Giô-đanh để chiếm lấy các dân lớn và mạnh hơn ngươi, những thành lớn và kiên cố cao tận trời.'),
(5160, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 9, 2, 'OT', 'một dân lớn và cao lớn, là con cháu A-na-kim, mà ngươi đã biết và đã nghe nói rằng: "Ai sẽ đứng vững trước mặt con cháu A-nác?"'),
(5161, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 9, 3, 'OT', 'Vậy ngày nay ngươi phải biết rằng chính Đức Giê-hô-va Đức Chúa Trời ngươi đi trước mặt ngươi như lửa thiêu đốt; chính Ngài sẽ tiêu diệt chúng và chính Ngài sẽ khuất phục chúng trước mặt ngươi, để ngươi đuổi chúng ra và tiêu diệt chúng mau chóng, y như Đức Giê-hô-va đã phán cùng ngươi.'),
(5162, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 9, 4, 'OT', 'Chớ nói trong lòng ngươi rằng: Vì cớ sự công bình của ta mà Đức Giê-hô-va đã dẫn ta vào để chiếm lấy đất nầy; nhưng chính vì sự gian ác của các dân tộc đó mà Đức Giê-hô-va đuổi chúng nó ra khỏi trước mặt ngươi.'),
(5163, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 9, 5, 'OT', 'Ngươi vào nhận lấy đất của các dân ấy, chẳng phải vì sự công bình ngươi hay lòng ngay thẳng của ngươi đâu, nhưng vì sự gian ác của các dân ấy, nên Đức Giê-hô-va Đức Chúa Trời ngươi đuổi chúng nó ra khỏi trước mặt ngươi, để thực hiện lời hứa mà Đức Giê-hô-va đã thề cùng các tổ phụ ngươi, là Aùp-ra-ham, Y-sác và Gia-cốp.'),
(5164, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 9, 6, 'OT', 'Vậy, hãy biết rằng Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi đất tốt lành nầy để nhận lấy, chẳng phải vì sự công bình của ngươi đâu; bởi ngươi là một dân cứng cổ.'),
(5165, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 9, 7, 'OT', 'Hãy nhớ, chớ quên điều ngươi đã làm khiến Đức Giê-hô-va Đức Chúa Trời ngươi nổi giận trong đồng vắng; từ ngày ngươi ra khỏi xứ Ai Cập cho đến khi đến nơi này, các ngươi luôn chống nghịch Đức Giê-hô-va.'),
(5166, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 9, 8, 'OT', 'Tại Hô-rếp, các ngươi đã làm cho Đức Giê-hô-va nổi giận; nên Đức Giê-hô-va nổi thạnh nộ cùng các ngươi, định diệt các ngươi.'),
(5167, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 9, 9, 'OT', 'Khi ta đi lên núi để nhận hai bảng đá, tức là hai bảng về giao ước mà Đức Giê-hô-va đã lập với các ngươi, ta ở trên núi bốn mươi ngày và bốn mươi đêm, không ăn bánh, không uống nước;'),
(5168, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 9, 10, 'OT', 'Đức Giê-hô-va đã trao cho tôi hai bảng đá, được viết bằng ngón tay Đức Chúa Trời, trên đó có chép trọn vẹn mọi lời mà Đức Giê-hô-va đã phán cùng các ngươi từ giữa ngọn lửa, trên núi, trong ngày hội họp.'),
(5169, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 9, 11, 'OT', 'Hết bốn mươi ngày và bốn mươi đêm, Đức Giê-hô-va ban cho tôi hai bảng đá, các bảng của giao ước.'),
(5170, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 9, 12, 'OT', 'Đức Giê-hô-va phán cùng ta rằng: Hãy đứng dậy, mau xuống khỏi đây, vì dân ngươi mà ta đã đem ra khỏi Ai-cập đã nhanh chóng hư hỏng, họ đã vội vàng rời khỏi con đường ta đã truyền cho họ, và đã đúc cho mình một tượng.'),
(5171, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 9, 13, 'OT', 'Đức Giê-hô-va phán cùng tôi rằng: Ta đã nhìn xem dân nầy, thì nầy là một dân cứng cổ.'),
(5172, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 9, 14, 'OT', 'Hãy để ta cùng ngươi, ta sẽ tiêu diệt chúng, và xóa tên chúng khỏi dưới các từng trời, rồi ta sẽ làm cho ngươi thành một dân mạnh và đông hơn nó.'),
(5173, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 9, 15, 'OT', 'Tôi quay đi, rồi đi xuống từ núi, khi núi đang cháy trong lửa; và hai bảng giao ước đặt trên hai tay tôi.'),
(5174, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 9, 16, 'OT', 'Ta thấy các ngươi đã phạm tội cùng Đức Giê-hô-va Đức Chúa Trời các ngươi, các ngươi đã làm cho mình một con bò con đúc, rất vội bỏ con đường mà Đức Giê-hô-va đã truyền cho các ngươi.'),
(5175, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 9, 17, 'OT', 'Tôi đã cầm lấy hai bảng đá, ném ra khỏi hai tay mình, và đập vỡ chúng ngay trước mặt các ngươi.'),
(5176, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 9, 18, 'OT', 'Tôi sấp mình xuống trước mặt Đức Giê-hô-va như lần đầu, bốn mươi ngày và bốn mươi đêm; tôi không ăn bánh, không uống nước, vì mọi tội các ngươi đã phạm, làm điều ác trước mặt Đức Giê-hô-va, khiến Ngài nổi giận.'),
(5177, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 9, 19, 'OT', 'Vì tôi đã sợ trước cơn thịnh nộ và cơn giận mà Đức Giê-hô-va nổi phừng lên nghịch cùng các ngươi, đặng tiêu diệt các ngươi; nhưng Đức Giê-hô-va đã nhậm lời tôi cả trong lần ấy nữa.'),
(5178, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 9, 20, 'OT', 'Đức Giê-hô-va cũng nổi giận dữ cùng A-rôn đến nỗi muốn tiêu diệt người, nên ta đã cầu nguyện cho A-rôn trong lúc ấy.'),
(5179, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 9, 21, 'OT', 'Vật thờ thần bò con mà các ngươi đã làm, ta đã lấy nó, đốt trong lửa, đập vỡ ra, nghiền nhỏ cho đến khi tan thành bụi, rồi ném bụi ấy vào khe nước chảy xuống từ trên núi.'),
(5180, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 9, 22, 'OT', 'Tại Tha-bê-ra, tại Ma-sa, và tại Kíp-rốt-Ha-tha-va, các ngươi đã làm cho Đức Giê-hô-va nổi giận.'),
(5181, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 9, 23, 'OT', 'Khi Đức Giê-hô-va sai các ngươi đi từ Ca-đe-Ba-nê-a, phán rằng: Hãy lên và chiếm lấy đất mà Ta đã ban cho các ngươi; nhưng các ngươi đã nổi loạn nghịch mạng Đức Giê-hô-va Đức Chúa Trời các ngươi, không tin Ngài, và không vâng theo tiếng Ngài.'),
(5182, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 9, 24, 'OT', 'Từ ngày ta biết các ngươi, các ngươi luôn chống nghịch cùng Đức Giê-hô-va.'),
(5183, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 9, 25, 'OT', 'Tôi sấp mình xuống trước mặt Đức Giê-hô-va bốn mươi ngày và bốn mươi đêm, là những ngày tôi đã sấp mình xuống, vì Đức Giê-hô-va có phán sẽ diệt các ngươi.'),
(5184, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 9, 26, 'OT', 'Tôi đã cầu nguyện cùng Đức Giê-hô-va và nói: Lạy Chúa Giê-hô-va, xin chớ hủy diệt dân Ngài và cơ nghiệp mà Ngài đã chuộc bằng quyền năng lớn lao của Ngài, và đã đem ra khỏi Ai Cập bằng tay hùng mạnh.'),
(5185, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 9, 27, 'OT', 'Xin hãy nhớ đến những tôi tớ Ngài là Aùp-ra-ham, Y-sác và Gia-cốp; chớ để ý đến sự cứng lòng, sự gian ác và tội lỗi của dân nầy.'),
(5186, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 9, 28, 'OT', 'e các dân tộc của xứ mà Đức Giê-hô-va đã đem chúng tôi ra khỏi đó, nói rằng: Bởi vì Đức Giê-hô-va không thể đem họ vào đất Ngài đã hứa với họ, và vì Ngài ghét họ, nên Ngài dẫn họ ra để giết họ trong đồng vắng.'),
(5187, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 9, 29, 'OT', 'Chúng là dân Ngài và cơ nghiệp Ngài, mà Ngài đã dùng quyền năng lớn và cánh tay giơ ra mà đem ra.'),
(5188, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 10, 1, 'OT', 'Trong lúc đó, Đức Giê-hô-va phán cùng ta rằng: Hãy đục cho mình hai bảng đá như hai bảng trước, và hãy lên cùng ta trên núi; ngươi cũng phải làm cho mình một hòm bằng gỗ.'),
(5189, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 10, 2, 'OT', 'Ta sẽ viết trên các bảng đá những lời như những lời đã có trên các bảng đầu tiên mà ngươi đã đập bể, rồi ngươi sẽ đặt chúng vào hòm.'),
(5190, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 10, 3, 'OT', 'Tôi đã làm một cái rương bằng gỗ si-tim, và tôi đã đục hai bảng đá giống như lần đầu, rồi tôi đi lên núi, hai bảng đá trong tay tôi.'),
(5191, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 10, 4, 'OT', 'Ngài viết trên các bảng như lời đã viết trước đây, mười điều răn mà Đức Giê-hô-va đã phán cùng các ngươi trên núi từ giữa ngọn lửa trong ngày hội tụ; rồi Đức Giê-hô-va trao chúng cho tôi.'),
(5192, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 10, 5, 'OT', 'Ta trở xuống từ trên núi, đặt hai bảng vào hòm mà ta đã làm, và hai bảng ấy ở đó như Đức Giê-hô-va đã truyền dặn ta.'),
(5193, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 10, 6, 'OT', 'Dân Y-sơ-ra-ên đi từ Bê-rốt Bê-nê-Gia-can đến Mô-sê-ra. Tại đó, A-rôn qua đời và được chôn; Ê-lê-a-sa, con trai người, làm thầy tế lễ thế cho người.'),
(5194, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 10, 7, 'OT', 'Từ đó, họ đi đến Gút-gô-đa, rồi từ Gút-gô-đa đến Dốt-ba-tha, là đất có các suối nước.'),
(5195, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 10, 8, 'OT', 'Trong lúc ấy, Đức Giê-hô-va biệt riêng chi phái Lê-vi ra để khiêng hòm giao ước của Đức Giê-hô-va, đứng trước mặt Đức Giê-hô-va mà phục sự Ngài và nhân danh Ngài mà chúc phước, cho đến ngày nay.'),
(5196, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 10, 9, 'OT', 'Bởi vậy, Lê-vi không có phần và cơ nghiệp cùng anh em mình; Đức Giê-hô-va là cơ nghiệp của người, như Đức Giê-hô-va Đức Chúa Trời đã phán cùng người.'),
(5197, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 10, 10, 'OT', 'Ta đã đứng trên núi như những ngày đầu tiên, bốn mươi ngày và bốn mươi đêm; Đức Giê-hô-va đã nghe ta, và lần ấy Đức Giê-hô-va cũng không chịu tiêu diệt ngươi.'),
(5198, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 10, 11, 'OT', 'Đức Giê-hô-va phán cùng tôi rằng: Hãy đứng dậy, đi trước mặt dân sự, để chúng nó vào và chiếm lấy đất mà Ta đã thề cùng tổ phụ chúng nó sẽ ban cho họ.'),
(5199, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 10, 12, 'OT', 'Vậy bây giờ, hỡi Y-sơ-ra-ên, Giê-hô-va Đức Chúa Trời ngươi đòi ngươi điều gì, nếu không phải là kính sợ Giê-hô-va Đức Chúa Trời ngươi, đi trong mọi con đường của Ngài, yêu mến Ngài và phục sự Giê-hô-va Đức Chúa Trời ngươi hết lòng hết ý?'),
(5200, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 10, 13, 'OT', 'giữ các điều răn và luật lệ của Đức Giê-hô-va mà ta truyền cho ngươi ngày nay, để ngươi được phước lành.'),
(5201, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 10, 14, 'OT', 'Kìa, các từng trời và các từng trời của các từng trời, đất và mọi vật ở trong đó đều thuộc về Giê-hô-va Đức Chúa Trời ngươi.'),
(5202, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 10, 15, 'OT', 'Chỉ các tổ phụ ngươi mà Đức Giê-hô-va yêu thương, yêu mến họ và chọn dòng dõi họ, tức là các ngươi, giữa muôn dân, như ngày nay.'),
(5203, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 10, 16, 'OT', 'Hãy cắt bỏ sự ô uế của lòng các ngươi, và đừng cứng cổ nữa.'),
(5204, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 10, 17, 'OT', 'vì Giê-hô-va Đức Chúa Trời các ngươi chính là Đức Chúa Trời của các thần và Chúa của các chúa, là Đức Chúa Trời lớn, quyền năng và đáng sợ, không thiên vị ai và không nhận của hối lộ,'),
(5205, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 10, 18, 'OT', 'Người làm công lý cho kẻ mồ côi và người góa bụa, và yêu thương người ngoại để cho người ấy đồ ăn và áo xống.'),
(5206, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 10, 19, 'OT', 'Vậy, hãy yêu người ngoại, vì các ngươi đã từng là người ngoại tại đất Ai Cập.'),
(5207, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 10, 20, 'OT', 'Hãy kính sợ Giê-hô-va Đức Chúa Trời ngươi, phục sự Ngài, và níu chặt lấy Ngài, và chỉ nhân danh Ngài mà thề.'),
(5208, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 10, 21, 'OT', 'Chính Ngài là sự tôn vinh của ngươi và là Đức Chúa Trời ngươi, Đấng đã làm những việc lớn lao và đáng sợ ấy mà mắt ngươi đã thấy.'),
(5209, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 10, 22, 'OT', 'Khi tổ tiên ngươi xuống Ai-cập, số ấy là bảy mươi người; còn bây giờ, Đức Giê-hô-va Đức Chúa Trời ngươi đã làm cho ngươi nhiều như các ngôi sao trên trời.'),
(5210, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 11, 1, 'OT', 'Hãy yêu Giê-hô-va Đức Chúa Trời ngươi và giữ các điều răn, luật lệ, mạng lịnh và quy định của Ngài mọi ngày.'),
(5211, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 11, 2, 'OT', 'Hôm nay, các ngươi phải biết rằng không phải con cái các ngươi, là những người chưa từng biết và chưa từng thấy sự dạy dỗ của Đức Giê-hô-va Đức Chúa Trời các ngươi, quyền năng lớn lao của Ngài, cánh tay quyền năng và cánh tay giơ thẳng ra của Ngài.'),
(5212, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 11, 3, 'OT', 'và những dấu kỳ cùng các việc Ngài làm giữa đất Ai-cập, cho Pha-ra-ôn, vua Ai-cập, và toàn cõi đất người.'),
(5213, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 11, 4, 'OT', 'Hãy nhận biết điều Đức Giê-hô-va đã làm cho đạo binh Ê-díp-tô, ngựa và xe của chúng, khi Ngài lấp đầy nước Biển Sậy trên mặt chúng trong khi chúng đuổi theo các ngươi; và Đức Giê-hô-va đã tiêu diệt chúng cho đến ngày nay.'),
(5214, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 11, 5, 'OT', 'việc Ngài đã làm cho các ngươi trong đồng vắng, cho đến khi các ngươi đến nơi này;'),
(5215, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 11, 6, 'OT', 'và điều Ngài đã làm cho Đa-than và A-bi-ram, con trai của Ê-li-áp, cháu của Ru-bên, khi đất hả miệng nuốt họ cùng với gia quyến, trại của họ, và mọi vật thuộc về họ, ngay giữa toàn thể Y-sơ-ra-ên.'),
(5216, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 11, 7, 'OT', 'Vì chính mắt các ngươi đã thấy mọi việc lớn lao mà Đức Giê-hô-va đã làm.'),
(5217, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 11, 8, 'OT', 'Vậy, hãy giữ trọn mọi điều răn mà ta truyền cho các ngươi ngày nay, để các ngươi được mạnh mẽ và vào chiếm lấy đất mà các ngươi sẽ đi qua đó để nhận lấy.'),
(5218, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 11, 9, 'OT', 'hầu cho các ngươi được sống lâu ngày trên đất mà Đức Giê-hô-va đã thề ban cho tổ phụ các ngươi và cho dòng dõi họ, là xứ đượm sữa và mật.'),
(5219, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 11, 10, 'OT', 'Vì đất ngươi sắp vào để chiếm lấy không giống như đất Ai Cập, nơi các ngươi đã ra khỏi; tại đó ngươi gieo giống và phải lấy chân mà tưới, như một vườn rau.'),
(5220, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 11, 11, 'OT', 'Nhưng đất mà các ngươi qua đó để chiếm lấy là đất có núi và trũng, sẽ uống nước mưa từ trời.'),
(5221, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 11, 12, 'OT', 'Là đất mà Đức Giê-hô-va Đức Chúa Trời ngươi hằng săn sóc; mắt Đức Giê-hô-va Đức Chúa Trời ngươi hằng nhìn xem đất ấy từ đầu năm cho đến cuối năm.'),
(5222, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 11, 13, 'OT', 'Vậy, nếu các ngươi chăm chỉ nghe các điều răn ta truyền cho các ngươi ngày nay, để kính mến Đức Giê-hô-va Đức Chúa Trời các ngươi và phục sự Ngài hết lòng, hết ý,'),
(5223, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 11, 14, 'OT', 'Thì ta sẽ ban cho đất các ngươi mưa đúng thì, cả mưa đầu mùa và mưa cuối mùa, và ngươi sẽ thâu hoạch lúa mì, rượu nho và dầu ô-liu của ngươi.'),
(5224, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 11, 15, 'OT', 'Ta sẽ ban cho đồng ruộng ngươi cỏ cho súc vật ngươi, và ngươi sẽ ăn và được no đủ.'),
(5225, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 11, 16, 'OT', 'Hãy giữ lấy mình, kẻo lòng các ngươi bị mê hoặc, rồi các ngươi xây đi, hầu việc các thần khác và thờ lạy chúng nó.'),
(5226, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 11, 17, 'OT', 'Đức Giê-hô-va sẽ nổi giận cùng các ngươi, khiến các từng trời bị đóng lại, không có mưa, đất không sinh ra sản vật; và các ngươi sẽ mau chóng bị tiêu diệt khỏi đất tốt lành mà Đức Giê-hô-va ban cho các ngươi.'),
(5227, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 11, 18, 'OT', 'Vậy, hãy đặt những lời nầy của ta trên lòng các ngươi và trên tâm thần các ngươi, buộc chúng làm dấu nơi tay các ngươi, và chúng sẽ làm ấn giữa hai mắt các ngươi.'),
(5228, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 11, 19, 'OT', 'Và các ngươi phải dạy bảo con cái mình về những điều ấy, nói đến khi ngồi trong nhà, khi đi đường, khi nằm xuống và khi chổi dậy.'),
(5229, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 11, 20, 'OT', 'Ngươi phải viết chúng trên các khung cửa nhà và các cổng của ngươi.'),
(5230, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 11, 21, 'OT', 'hầu cho các ngươi và con cái các ngươi sống lâu trên đất mà Đức Giê-hô-va đã thề ban cho tổ tiên các ngươi, như những ngày trời trên đất.'),
(5231, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 11, 22, 'OT', 'Vì nếu các ngươi cẩn thận giữ trọn mọi điều răn nầy mà ta truyền cho các ngươi để làm, yêu Giê-hô-va Đức Chúa Trời các ngươi, đi theo mọi con đường của Ngài, và gắn bó với Ngài,'),
(5232, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 11, 23, 'OT', 'thì Đức Giê-hô-va sẽ đuổi các dân tộc nầy ra khỏi trước mặt các ngươi, và các ngươi sẽ chiếm hữu các dân tộc lớn và hùng mạnh hơn các ngươi.'),
(5233, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 11, 24, 'OT', 'Mọi nơi nào bàn chân các ngươi sẽ đạp đến đều thuộc về các ngươi; từ đồng vắng cho đến Li-ban, từ sông Ơ-phơ-rát cho đến biển phía tây sẽ là ranh giới của các ngươi.'),
(5234, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 11, 25, 'OT', 'Chẳng có ai sẽ đứng vững trước mặt các ngươi; Đức Giê-hô-va Đức Chúa Trời các ngươi sẽ đặt sự khiếp sợ và kinh hoàng của các ngươi trên khắp đất mà các ngươi sẽ bước đi trên đó, như Ngài đã phán với các ngươi.'),
(5235, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 11, 26, 'OT', 'Hãy xem, ngày nay ta đặt trước mặt các ngươi sự ban phước và sự rủa sả.'),
(5236, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 11, 27, 'OT', 'sự phước lành, nếu các ngươi nghe theo các điều răn của Đức Giê-hô-va Đức Chúa Trời các ngươi, mà ta truyền cho các ngươi ngày hôm nay;'),
(5237, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 11, 28, 'OT', 'và sự rủa sả, nếu các ngươi không nghe theo các mệnh lệnh của Đức Giê-hô-va Đức Chúa Trời các ngươi, và xây bỏ con đường mà ta truyền cho các ngươi ngày nay, để đi theo các thần khác mà các ngươi không biết.'),
(5238, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 11, 29, 'OT', 'Khi Đức Giê-hô-va Đức Chúa Trời ngươi khiến ngươi vào xứ mà ngươi đang đến để nhận lấy, thì phải đặt sự chúc lành trên núi Ga-ri-xim, và sự rủa sả trên núi Ê-banh.'),
(5239, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 11, 30, 'OT', 'Hai ngọn núi ấy há chẳng phải ở bên kia sông Giô-đanh, theo hướng lối vào nơi mặt trời lặn, tại đất của người Ca-na-an đang ở trong đồng bằng, đối diện Ghinh-ganh, gần những cây sồi của Mô-rê sao?'),
(5240, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 11, 31, 'OT', 'Vì các ngươi sẽ đi qua sông Giô-đanh để vào chiếm lấy đất mà Đức Giê-hô-va Đức Chúa Trời các ngươi ban cho các ngươi; các ngươi sẽ chiếm hữu đất ấy và ở tại đó.'),
(5241, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 11, 32, 'OT', 'Và các ngươi phải giữ để thực hiện trọn vẹn mọi luật lệ và các điều xét đoán mà hôm nay ta đặt trước mặt các ngươi.'),
(5242, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 12, 1, 'OT', 'Đây là những mạng lịnh và những luật lệ mà các ngươi phải giữ làm theo trong xứ mà Đức Giê-hô-va Đức Chúa Trời của tổ phụ các ngươi đã ban cho các ngươi để nhận lấy, trọn những ngày các ngươi sống trên đất.'),
(5243, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 12, 2, 'OT', 'Các ngươi phải tận diệt mọi nơi mà các dân tộc mà các ngươi sẽ chiếm lấy làm cơ nghiệp đã thờ thần của chúng, trên các núi cao, trên các gò và dưới mọi cây xanh.'),
(5244, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 12, 3, 'OT', 'Phải phá đổ các bàn thờ của chúng, đập bể các trụ đá của chúng, thiêu các tượng A-sê-ra của chúng trong lửa, làm tan nát các tượng chạm về các thần chúng nó, và xóa tên chúng khỏi nơi ấy.'),
(5245, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 12, 4, 'OT', 'Các ngươi không được làm như vậy cho Đức Giê-hô-va Đức Chúa Trời của các ngươi.'),
(5246, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 12, 5, 'OT', 'nhưng phải đến nơi mà Đức Giê-hô-va Đức Chúa Trời các ngươi sẽ chọn trong các chi phái các ngươi, để đặt danh Ngài tại đó; các ngươi phải tìm kiếm nơi Ngài ngự và đến đó,'),
(5247, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 12, 6, 'OT', 'đem đến đó các lễ thiêu, các của lễ súc vật, phần mười, của lễ dâng nơi tay các ngươi, các của lễ hứa, các của lễ tự nguyện và con đầu lòng của bò và chiên các ngươi;'),
(5248, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 12, 7, 'OT', 'Các ngươi sẽ ăn tại đó, trước mặt Đức Giê-hô-va Đức Chúa Trời các ngươi, và sẽ vui vẻ trong mọi công việc tay các ngươi làm, các ngươi và các gia đình các ngươi, mà Đức Giê-hô-va Đức Chúa Trời ngươi đã ban phước cho.'),
(5249, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 12, 8, 'OT', 'Các ngươi không được làm như mọi điều chúng ta làm ngày nay, mỗi người làm điều mình cho là ngay thẳng trong mắt mình.'),
(5250, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 12, 9, 'OT', 'Vì các ngươi chưa đến nơi an nghỉ và nơi cơ nghiệp mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi.'),
(5251, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 12, 10, 'OT', 'Khi các ngươi qua sông Giô-đanh, và ở trong đất mà Đức Giê-hô-va Đức Chúa Trời các ngươi ban cho các ngươi làm sản nghiệp, thì Ngài sẽ khiến các ngươi được yên ổn, diệt hết mọi kẻ thù nghịch xung quanh các ngươi, và các ngươi sẽ ở an toàn.'),
(5252, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 12, 11, 'OT', 'Nơi nào mà Đức Giê-hô-va Đức Chúa Trời các ngươi chọn để ngự danh Ngài tại đó, thì các ngươi phải đem đến nơi ấy mọi điều mà ta truyền cho các ngươi: những của lễ thiêu, các của lễ hy sinh, phần mười các ngươi dâng, lễ vật các ngươi dâng giơ lên, và mọi thứ tốt nhất trong các lời hứa nguyện mà các ngươi khấn nguyện cho Đức Giê-hô-va.'),
(5253, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 12, 12, 'OT', 'Các ngươi sẽ vui vẻ trước mặt Đức Giê-hô-va Đức Chúa Trời các ngươi, chính các ngươi, con trai, con gái, tôi trai, tớ gái của các ngươi, và người Lê-vi ở trong các thành các ngươi, vì người không có phần và cơ nghiệp nào chung với các ngươi.'),
(5254, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 12, 13, 'OT', 'Hãy giữ mình cẩn thận, đừng dâng của lễ thiêu của ngươi tại bất kỳ nơi nào ngươi thấy.'),
(5255, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 12, 14, 'OT', 'nhưng phải dâng nơi mà Đức Giê-hô-va sẽ chọn trong một chi phái của ngươi; tại đó ngươi phải dâng của lễ thiêu và làm mọi điều ta truyền cho ngươi.'),
(5256, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 12, 15, 'OT', 'Chỉ tại các thành mình, ngươi được phép giết và ăn thịt theo lòng ước muốn mình, tùy theo sự phước lành mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi; người ô uế và người tinh sạch đều có thể ăn nó, như ăn con hoẵng và con nai.'),
(5257, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 12, 16, 'OT', 'Chỉ huyết, các ngươi không được ăn; phải đổ huyết trên đất như nước.'),
(5258, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 12, 17, 'OT', 'Ngươi không được phép ăn trong các thành ngươi phần thập phần của lúa mì, rượu mới, dầu ô-liu, con đầu lòng của bò và chiên ngươi, cùng mọi vật hứa nguyện ngươi khấn, các của lễ tự nguyện, và lễ vật dâng nơi tay ngươi.'),
(5259, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 12, 18, 'OT', 'Nhưng ngươi phải ăn những vật ấy trước mặt Đức Giê-hô-va Đức Chúa Trời ngươi, tại nơi mà Đức Giê-hô-va Đức Chúa Trời ngươi sẽ chọn, tức là ngươi, con trai ngươi, con gái ngươi, tôi tớ ngươi, tớ gái ngươi, và người Lê-vi ở trong các cổng thành ngươi; và ngươi sẽ vui vẻ trước mặt Đức Giê-hô-va Đức Chúa Trời ngươi về mọi công việc tay ngươi làm.'),
(5260, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 12, 19, 'OT', 'Hãy giữ lấy mình ngươi, kẻo ngươi bỏ người Lê-vi; trọn đời ngươi trên đất ngươi.'),
(5261, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 12, 20, 'OT', 'Khi Đức Giê-hô-va Đức Chúa Trời ngươi mở rộng đất ngươi ra, như Ngài đã phán với ngươi, và ngươi nói: Ta sẽ ăn thịt, vì ta ước ao được ăn thịt, thì ngươi được ăn thịt tùy theo mọi sự ước ao của lòng ngươi.'),
(5262, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 12, 21, 'OT', 'Nếu nơi mà Đức Giê-hô-va Đức Chúa Trời ngươi chọn để đặt danh Ngài ở đó cách xa ngươi, thì ngươi có thể giết bò hay chiên mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi, theo như điều ta đã truyền cho ngươi; và ngươi có thể ăn nó trong các cổng thành ngươi, tùy theo mọi sự ước ao của lòng ngươi.'),
(5263, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 12, 22, 'OT', 'Chỉ có thể ăn thịt nó như cách ăn con hoàng dương và con nai; người ô uế và người tinh sạch đều cùng nhau ăn được.'),
(5264, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 12, 23, 'OT', 'Chỉ hãy giữ mình, đừng ăn huyết, vì huyết là mạng sống; và ngươi không được ăn mạng sống cùng với thịt.'),
(5265, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 12, 24, 'OT', 'Ngươi không được ăn huyết; ngươi phải đổ nó trên đất như nước.'),
(5266, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 12, 25, 'OT', 'Đừng ăn huyết, để ngươi và con cháu ngươi được phước, vì ngươi làm điều ngay thẳng trước mặt Đức Giê-hô-va.'),
(5267, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 12, 26, 'OT', 'Chỉ các vật thánh của ngươi và những điều ngươi hứa nguyện, ngươi phải mang theo và đi đến nơi Đức Giê-hô-va sẽ chọn.'),
(5268, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 12, 27, 'OT', 'Ngươi sẽ dâng các của lễ thiêu mình, thịt và huyết, trên bàn thờ của Đức Giê-hô-va Đức Chúa Trời ngươi; còn huyết các của lễ hy sinh ngươi thì phải đổ trên bàn thờ của Đức Giê-hô-va Đức Chúa Trời ngươi, và ngươi sẽ ăn thịt.'),
(5269, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 12, 28, 'OT', 'Hãy giữ và vâng theo mọi lời nầy mà ta truyền cho ngươi, để ngươi và con cháu ngươi luôn được phước đời đời, khi ngươi làm điều thiện và điều ngay thẳng trước mặt Đức Giê-hô-va Đức Chúa Trời ngươi.'),
(5270, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 12, 29, 'OT', 'Khi Đức Giê-hô-va Đức Chúa Trời ngươi diệt các dân tộc ấy khỏi trước mặt ngươi, là những dân tộc mà ngươi đi đến để chiếm lấy chúng nó, ngươi sẽ chiếm lấy chúng nó và ở trong đất của chúng nó.'),
(5271, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 12, 30, 'OT', 'Hãy giữ lấy mình, kẻo sau khi các dân ấy đã bị tiêu diệt khỏi trước mặt ngươi, ngươi lại bị lôi kéo theo chúng, và ngươi lại cầu hỏi các thần của chúng mà nói rằng: "Các dân tộc này đã thờ phượng các thần mình thể nào?" để ngươi cũng làm theo như vậy.'),
(5272, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 12, 31, 'OT', 'Ngươi chớ làm như vậy cho Đức Giê-hô-va Đức Chúa Trời ngươi, vì mọi điều gớm ghiếc mà Đức Giê-hô-va ghét, thì chúng nó đã làm cho các thần mình: đến nỗi chúng nó thiêu con trai và con gái mình trong lửa để cúng các thần mình.'),
(5273, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 12, 32, 'OT', 'Các ngươi phải cẩn thận làm theo mọi điều mà ta truyền cho các ngươi: không được thêm vào, cũng không được bớt ra khỏi điều đó.'),
(5274, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 13, 1, 'OT', 'Nếu giữa anh em nổi lên một tiên tri hoặc một người chiêm bao, và người ấy đưa ra cho anh em một dấu kỳ hoặc một phép lạ,'),
(5275, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 13, 2, 'OT', 'Nếu dấu điềm hay phép lạ mà người ấy đã nói với ngươi xảy ra, và người ấy nói rằng: "Hãy đi theo các thần khác mà ngươi chưa từng biết, và chúng ta sẽ phục vụ chúng,"'),
(5276, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 13, 3, 'OT', 'Đừng nghe theo lời của đấng tiên tri ấy hay kẻ chiêm bao thấy điềm đó, vì Đức Giê-hô-va Đức Chúa Trời các ngươi đang thử các ngươi, để biết các ngươi có yêu mến Đức Giê-hô-va Đức Chúa Trời mình hết lòng, hết ý hay không.'),
(5277, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 13, 4, 'OT', 'Các ngươi phải đi theo Đức Giê-hô-va Đức Chúa Trời các ngươi, kính sợ Ngài, giữ các mệnh lệnh của Ngài, vâng nghe tiếng Ngài, phục sự Ngài và gắn bó với Ngài.'),
(5278, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 13, 5, 'OT', 'Nhưng phải giết tiên tri ấy hoặc kẻ chiêm bao mộng ấy, vì người đó đã nói điều trái ngược về Đức Giê-hô-va Đức Chúa Trời các ngươi, là Đấng đã đem các ngươi ra khỏi đất Ê-díp-tô và cứu các ngươi khỏi nhà nô lệ, để xui các ngươi bỏ con đường mà Đức Giê-hô-va Đức Chúa Trời các ngươi đã truyền các ngươi phải đi. Ngươi phải diệt cái ác khỏi giữa các ngươi.'),
(5279, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 13, 6, 'OT', 'Nếu anh em ngươi, con trai của mẹ ngươi, hay là con trai, con gái ngươi, vợ ngươi, hoặc bạn hữu thân cận ngươi như mạng sống ngươi, xúi giục ngươi cách kín nhiệm mà nói: "Chúng ta hãy đi phục sự các thần khác mà ngươi và tổ phụ ngươi chưa hề biết,"'),
(5280, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 13, 7, 'OT', 'các thần của những dân tộc ở chung quanh các ngươi, gần các ngươi hay xa các ngươi, từ đầu đất nầy cho đến đầu đất kia'),
(5281, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 13, 8, 'OT', 'Đừng chịu theo nó, cũng đừng nghe nó; mắt ngươi chớ thương tiếc nó, chớ động lòng thương xót, và chớ che chở cho nó.'),
(5282, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 13, 9, 'OT', 'Ngươi hẳn phải giết nó; tay ngươi phải tra vào nó trước hết để giết nó đi, rồi tay của cả dân sự sau đó.'),
(5283, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 13, 10, 'OT', 'Phải ném đá người đó bằng những hòn đá cho đến chết, vì người đó đã tìm cách khiến ngươi lìa bỏ Đức Giê-hô-va Đức Chúa Trời ngươi, là Đấng đã dẫn ngươi ra khỏi đất Ê-díp-tô, khỏi nhà nô lệ.'),
(5284, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 13, 11, 'OT', 'Cả Y-sơ-ra-ên sẽ nghe biết và phải sợ hãi, không ai dám làm điều ác như thế nầy trong vòng ngươi nữa.'),
(5285, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 13, 12, 'OT', 'Khi ngươi nghe nói trong một trong các thành mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi ở, rằng'),
(5286, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 13, 13, 'OT', 'Có những người gian ác từ giữa anh em ra đi, xúi giục dân cư thành mình rằng: "Chúng ta hãy đi hầu việc các thần khác mà anh em chưa hề biết."'),
(5287, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 13, 14, 'OT', 'Hãy tra khảo, điều tra và hỏi kỹ càng; và này, nếu điều đó là thật, sự việc đã được xác nhận, tội ác ghê tởm này đã được thực hiện giữa anh em,'),
(5288, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 13, 15, 'OT', 'Hãy đánh giết dân cư của thành ấy bằng lưỡi gươm; phải tận diệt nó và mọi vật ở trong nó, cùng với súc vật của nó bằng lưỡi gươm.'),
(5289, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 13, 16, 'OT', 'Ngươi phải gom tất cả chiến lợi phẩm của thành ấy ra giữa phố nó, rồi đốt bằng lửa thành ấy và mọi chiến lợi phẩm của nó trọn vẹn trước mặt Đức Giê-hô-va Đức Chúa Trời ngươi; và nó sẽ trở nên một đống đổ nát đời đời, không bao giờ được xây dựng lại nữa.'),
(5290, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 13, 17, 'OT', 'Chớ để điều gì đáng bị tiêu diệt dính lại trong tay ngươi, hầu cho Đức Giê-hô-va sẽ nguôi cơn thạnh nộ, và sẽ thương xót ngươi, thương yêu ngươi, và làm cho ngươi sinh sôi nảy nở, như Ngài đã thề cùng tổ phụ ngươi.'),
(5291, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 13, 18, 'OT', 'Vì ngươi sẽ nghe theo tiếng Đức Giê-hô-va Đức Chúa Trời ngươi, để giữ mọi điều răn mà ta truyền cho ngươi ngày nay, để làm điều ngay thẳng trong mắt Đức Giê-hô-va Đức Chúa Trời ngươi.'),
(5292, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 14, 1, 'OT', 'Các ngươi là con cái Đức Giê-hô-va Đức Chúa Trời các ngươi; các ngươi không được rạch mình và không được cạo trán giữa hai mắt vì kẻ chết.'),
(5293, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 14, 2, 'OT', 'Vì ngươi là một dân thánh dành cho Đức Giê-hô-va Đức Chúa Trời ngươi; chính Đức Giê-hô-va đã chọn ngươi giữa muôn dân trên mặt đất, để ngươi trở nên dân riêng thuộc về Ngài.'),
(5294, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 14, 3, 'OT', 'Chớ ăn bất cứ vật gì là sự gớm ghiếc.'),
(5295, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 14, 4, 'OT', 'Nầy là loài vật mà ngươi được ăn: bò, chiên đực, chiên cái,'),
(5296, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 14, 5, 'OT', 'nai, hoàng dương, hoẵng, dê rừng, sơn dương, bò tót và linh dương.'),
(5297, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 14, 6, 'OT', 'Mọi loài vật có móng rẽ ra, chân chia hai và nhai lại, các ngươi được ăn loài ấy.'),
(5298, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 14, 7, 'OT', 'Nhưng các ngươi không được ăn những loài này trong các loài nhai lại và có móng vuốt rẽ làm hai phần, đó là con lạc đà, con thỏ rừng và con nhím đá; vì chúng nhai lại, nhưng không chia móng vuốt; các ngươi phải xem chúng là không sạch.'),
(5299, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 14, 8, 'OT', 'Còn con heo thì vì nó có móng rẽ ra nhưng không nhai lại, nên nó là vật không sạch đối với các ngươi. Các ngươi không được ăn thịt nó, và cũng không được đụng đến xác chết của nó.'),
(5300, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 14, 9, 'OT', 'Các ngươi được ăn mọi loài vật nào ở trong nước có vây và có vảy.'),
(5301, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 14, 10, 'OT', 'Mọi loài vật nào không có vây và vảy thì các ngươi không được ăn; loài ấy là không sạch đối với các ngươi.'),
(5302, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 14, 11, 'OT', 'Mọi loài chim sạch, các ngươi được ăn.'),
(5303, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 14, 12, 'OT', 'Và đây là những loài các ngươi không được ăn: chim ưng, chim ngạc, và chim kên kên;'),
(5304, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 14, 13, 'OT', 'và chim diều, chim ó, và chim ưng theo thứ loài của nó;'),
(5305, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 14, 14, 'OT', 'và mọi loài quạ theo thứ tự của nó;'),
(5306, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 14, 15, 'OT', 'và con đà điểu, và con tu hú, và con thủy kê, và con diều theo giống nó;'),
(5307, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 14, 16, 'OT', 'con kô-sô, con ya-nhúp, và con tin-sa-mết'),
(5308, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 14, 17, 'OT', 'và chim ưng, và chim ráo, và chim cồng cộc,'),
(5309, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 14, 18, 'OT', 'và con bồ nông, và con diệc theo thứ lớp của nó, và con cú mèo, và con dơi.'),
(5310, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 14, 19, 'OT', 'Mọi loài côn trùng bay được đều là không sạch cho các ngươi; các ngươi không được ăn.'),
(5311, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 14, 20, 'OT', 'Mọi loài chim sạch, các ngươi được ăn.'),
(5312, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 14, 21, 'OT', 'Các ngươi không được ăn bất cứ con vật chết nào; hãy đưa nó cho người ngoại bang ở trong các thành ngươi, và người ấy sẽ ăn nó, hoặc ngươi có thể bán cho người ngoại bang; vì ngươi là một dân thánh cho Đức Giê-hô-va Đức Chúa Trời ngươi. Ngươi không được nấu dê con trong sữa mẹ nó.'),
(5313, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 14, 22, 'OT', 'Hằng năm, ngươi phải dâng trọn một phần mười về mọi sản vật do hạt giống mình sinh ra từ đồng ruộng.'),
(5314, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 14, 23, 'OT', 'Tại trước mặt Đức Giê-hô-va Đức Chúa Trời ngươi, trong nơi mà Ngài sẽ chọn để đặt danh Ngài ở đó, ngươi phải ăn phần mười ngũ cốc, rượu mới và dầu ô-liu, và con đầu lòng của bò và chiên ngươi, hầu cho ngươi học cách kính sợ Đức Giê-hô-va Đức Chúa Trời ngươi mọi ngày trong đời.'),
(5315, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 14, 24, 'OT', 'Khi đường đi quá xa cho ngươi, đến nỗi không thể mang của lễ đó đi được, vì nơi mà Đức Giê-hô-va Đức Chúa Trời ngươi chọn để đặt danh Ngài ở đó quá xa ngươi, khi Đức Giê-hô-va Đức Chúa Trời ngươi ban phước cho ngươi,'),
(5316, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 14, 25, 'OT', 'thì ngươi hãy đổi bạc đó ra tiền, cầm tiền trong tay mình, đi đến nơi mà Đức Giê-hô-va Đức Chúa Trời ngươi sẽ chọn,'),
(5317, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 14, 26, 'OT', 'Ngươi sẽ dùng bạc đó để mua bất cứ điều gì lòng ngươi ước ao, về bò hay chiên, về rượu hay rượu mạnh, và mọi thứ mà lòng ngươi đòi hỏi; ngươi phải ăn tại đó trước mặt Đức Giê-hô-va Đức Chúa Trời ngươi, và ngươi cùng gia đình ngươi sẽ vui vẻ.'),
(5318, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 14, 27, 'OT', 'Ngươi không được bỏ người Lê-vi ở trong các thành ngươi, vì người không có phần và cơ nghiệp nào cùng ngươi.'),
(5319, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 14, 28, 'OT', 'Hết ba năm, ngươi phải đem đưa ra mọi phần mười sản vật của năm ấy, và cất giữ tại các cửa thành ngươi.'),
(5320, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 14, 29, 'OT', 'Khi người Lê-vi đến, vì người không có phần và cơ nghiệp nào cùng ngươi, cùng với người ngoại bang, kẻ mồ côi và người goá bụa ở trong các thành của ngươi, thì họ sẽ ăn và được no đủ, để Đức Giê-hô-va Đức Chúa Trời ngươi ban phước cho ngươi trong mọi công việc tay ngươi làm.'),
(5321, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 15, 1, 'OT', 'Hết bảy năm, ngươi phải làm sự buông bỏ.'),
(5322, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 15, 2, 'OT', 'Nầy là lời về sự tha nợ: mỗi chủ nợ phải tha món nợ mà người khác nợ mình; ngươi không được đòi lại anh em mình hay kẻ lân cận mình, vì người ta đã công bố năm giải thoát cho Đức Giê-hô-va.'),
(5323, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 15, 3, 'OT', 'Ngươi được đòi người ngoại bang trả; nhưng vật gì thuộc anh em ngươi, thì tay ngươi phải tha bỏ.'),
(5324, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 15, 4, 'OT', 'Nhưng sẽ không có kẻ nghèo trong các ngươi, vì Đức Giê-hô-va sẽ ban phước cho ngươi cách dồi dào trong đất mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi để nhận làm sản nghiệp,'),
(5325, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 15, 5, 'OT', 'Chỉ cần ngươi chăm chỉ nghe theo tiếng của Đức Giê-hô-va Đức Chúa Trời ngươi, để cẩn thận làm theo mọi điều răn mà ta truyền cho ngươi ngày nay.'),
(5326, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 15, 6, 'OT', 'Vì Đức Giê-hô-va Đức Chúa Trời ngươi sẽ ban phước cho ngươi, như Ngài đã phán; ngươi sẽ cho các dân tộc nhiều nước vay, còn chính ngươi thì không vay ai; ngươi sẽ thống trị các dân tộc nhiều nước, còn họ thì không thống trị ngươi.'),
(5327, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 15, 7, 'OT', 'Nếu trong các thành của xứ mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi có một người anh em nghèo, thì lòng ngươi không được cứng và tay ngươi không được nắm lại trước mặt anh em nghèo của ngươi.'),
(5328, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 15, 8, 'OT', 'Nhưng phải mở rộng tay ngươi ra cho người, và cho vay mượn anh ta những thứ cần thiết cho nhu cầu của người ấy.'),
(5329, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 15, 9, 'OT', 'Hãy giữ mình cẩn thận, kẻo lòng ngươi sinh điều ác, mà nói rằng: "Năm thứ bảy, năm tha nợ, gần đến rồi", rồi mắt ngươi trở nên độc ác đối với anh em nghèo của ngươi, và ngươi không cho người ấy gì hết; người ấy sẽ kêu cầu cùng Đức Giê-hô-va chống lại ngươi, và ngươi sẽ mắc tội.'),
(5330, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 15, 10, 'OT', 'Ngươi phải ban cho người, và lòng ngươi chớ thấy tiếc khi ban cho người; vì tại điều này, Đức Giê-hô-va Đức Chúa Trời ngươi sẽ ban phước cho ngươi trong mọi công việc ngươi làm và trong mọi điều ngươi đặt tay vào.'),
(5331, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 15, 11, 'OT', 'Vì sẽ không hề vắng bóng kẻ nghèo trong xứ ngươi, nên ta truyền cho ngươi rằng: Ngươi phải mở rộng tay mình ra giúp anh em ngươi, người nghèo và kẻ khốn cùng ở trong xứ ngươi.'),
(5332, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 15, 12, 'OT', 'Khi một người anh em ngươi, là người Hê-bơ-rơ, hoặc là người Hê-bơ-rơ nữ, bị bán cho ngươi, thì sẽ phục dịch ngươi trong sáu năm; nhưng đến năm thứ bảy, ngươi phải để người ấy ra đi tự do khỏi ngươi.'),
(5333, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 15, 13, 'OT', 'Khi ngươi cho người ấy được tự do khỏi ngươi, thì không được để người ấy ra đi tay không.'),
(5334, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 15, 14, 'OT', 'Hãy ban phát cho người một cách hào phóng từ bầy chiên, sân đạp lúa và hầm ép rượu của ngươi, tức là từ những điều mà Đức Giê-hô-va Đức Chúa Trời ngươi đã ban phước cho ngươi.'),
(5335, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 15, 15, 'OT', 'Hãy nhớ rằng ngươi đã làm tôi mọi trong đất Ê-díp-tô, và Đức Giê-hô-va Đức Chúa Trời ngươi đã chuộc ngươi; vì cớ đó, hôm nay ta truyền cho ngươi điều này.'),
(5336, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 15, 16, 'OT', 'Nếu người ấy nói cùng ngươi: Tôi không muốn ra khỏi nhà ngươi, vì tôi yêu ngươi và gia đình ngươi, và tôi sống hạnh phúc nơi ngươi,'),
(5337, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 15, 17, 'OT', 'Thì ngươi phải lấy cái vỉ sắt mà đục thủng tai người đó nơi cửa, và người ấy sẽ làm đầy tớ ngươi trọn đời. Ngươi cũng phải làm như vậy cho nữ tớ của ngươi.'),
(5338, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 15, 18, 'OT', 'Ngươi chớ coi điều đó là nặng lòng khi giải phóng người ấy ra khỏi tay ngươi, vì người đã phục dịch ngươi gấp đôi công giá của một người làm thuê trong sáu năm; và Đức Giê-hô-va Đức Chúa Trời ngươi sẽ ban phước cho ngươi trong mọi việc ngươi làm.'),
(5339, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 15, 19, 'OT', 'Mọi con đầu lòng đực sinh ra trong bầy bò và bầy chiên của ngươi, hãy biệt riêng ra thánh cho Đức Giê-hô-va Đức Chúa Trời ngươi; chớ cày bằng con đầu lòng của bò ngươi, và chớ hớt lông con đầu lòng của chiên ngươi.'),
(5340, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 15, 20, 'OT', 'Hằng năm, ngươi và nhà ngươi sẽ ăn nó trước mặt Đức Giê-hô-va Đức Chúa Trời ngươi, tại nơi mà Đức Giê-hô-va sẽ chọn.'),
(5341, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 15, 21, 'OT', 'Nhưng nếu trong nó có tật, què hay đui, mọi tật xấu, thì ngươi không được dâng nó làm của lễ thiêu cho Đức Giê-hô-va Đức Chúa Trời ngươi.'),
(5342, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 15, 22, 'OT', 'Ngươi phải ăn nó trong các cổng thành ngươi; kẻ ô uế và kẻ sạch sẽ cùng nhau ăn, như ăn con hoẵng hay là con nai.'),
(5343, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 15, 23, 'OT', 'Chỉ ngươi chớ ăn huyết nó; phải đổ huyết nó trên đất như nước.'),
(5344, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 16, 1, 'OT', 'Hãy giữ tháng lúa trỗ và làm lễ Vượt-qua cho Đức Giê-hô-va Đức Chúa Trời ngươi, vì trong tháng lúa trỗ, Đức Giê-hô-va Đức Chúa Trời ngươi đã đem ngươi ra khỏi xứ Ê-díp-tô giữa ban đêm.'),
(5345, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 16, 2, 'OT', 'Ngươi phải dâng sinh tế lễ Vượt-qua cho Đức Giê-hô-va Đức Chúa Trời ngươi, chiên và bò, tại nơi mà Đức Giê-hô-va sẽ chọn để ngự danh Ngài tại đó.'),
(5346, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 16, 3, 'OT', 'Đừng ăn bánh có men cùng với lễ Vượt-qua; bảy ngày phải ăn bánh không men, tức là bánh của sự khốn khổ, vì ngươi đã vội vàng ra khỏi đất Ai-cập, để trọn đời ngươi nhớ ngày ngươi ra khỏi đất Ai-cập.'),
(5347, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 16, 4, 'OT', 'Trong bảy ngày, không được thấy men trong toàn cõi đất ngươi; và thịt con vật mà ngươi giết vào chiều ngày thứ nhất, không được để lại đến sáng hôm sau.'),
(5348, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 16, 5, 'OT', 'Ngươi không được giết con sinh lễ Vượt-qua trong một trong các cửa thành nào mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi;'),
(5349, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 16, 6, 'OT', 'nhưng chỉ tại nơi mà Đức Giê-hô-va Đức Chúa Trời ngươi chọn để ngự danh Ngài, tại đó ngươi phải giết con sinh lễ Vượt-qua vào buổi chiều, khi mặt trời lặn, đúng vào thời điểm ngươi ra khỏi xứ Ai Cập.'),
(5350, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 16, 7, 'OT', 'Phải nấu và ăn tại nơi mà Đức Giê-hô-va Đức Chúa Trời ngươi chọn; rồi sáng hôm sau, ngươi phải trở về trại mình.'),
(5351, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 16, 8, 'OT', 'Trong sáu ngày, ngươi phải ăn bánh không men; còn ngày thứ bảy là lễ hội thánh dành cho Đức Giê-hô-va Đức Chúa Trời ngươi, ngươi không được làm bất cứ công việc gì.'),
(5352, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 16, 9, 'OT', 'Ngươi phải đếm bảy tuần; hãy bắt đầu đếm bảy tuần từ khi bắt đầu dùng liềm gặt lúa mì.'),
(5353, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 16, 10, 'OT', 'Ngươi sẽ giữ lễ Bảy Tuần cho Đức Giê-hô-va Đức Chúa Trời ngươi, dâng của lễ theo sự rộng tay ngươi cho, tùy theo điều Đức Giê-hô-va Đức Chúa Trời ngươi ban phước cho ngươi.'),
(5354, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 16, 11, 'OT', 'Ngươi sẽ vui vẻ trước mặt Đức Giê-hô-va Đức Chúa Trời ngươi, ngươi và con trai, con gái ngươi, tôi trai, tớ gái ngươi, người Lê-vi ở trong các cửa thành ngươi, và người khách lạ, kẻ mồ côi, người góa bụa ở giữa vòng ngươi, tại nơi mà Đức Giê-hô-va Đức Chúa Trời ngươi chọn để đặt danh Ngài tại đó.'),
(5355, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 16, 12, 'OT', 'Hãy nhớ rằng ngươi đã làm tôi mọi tại Ai-cập, và phải cẩn thận giữ và làm theo các luật lệ nầy.'),
(5356, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 16, 13, 'OT', 'Ngươi phải giữ lễ Lều Tạm bảy ngày, khi đã thâu góp từ sân đập lúa và hầm ép rượu mình.'),
(5357, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 16, 14, 'OT', 'Ngươi và con trai ngươi, con gái ngươi, tôi trai ngươi, tớ gái ngươi, người Lê-vi, khách lạ, kẻ mồ côi và người góa bụa ở trong các cửa thành ngươi sẽ vui mừng trong lễ ngươi giữ.'),
(5358, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 16, 15, 'OT', 'Trong bảy ngày ngươi phải giữ lễ cho Đức Giê-hô-va Đức Chúa Trời ngươi, tại nơi mà Đức Giê-hô-va sẽ chọn; vì Đức Giê-hô-va Đức Chúa Trời ngươi sẽ ban phước cho ngươi trong mọi sản lượng mùa màng và trong mọi công việc tay ngươi làm, và ngươi sẽ chỉ toàn thể vui mừng.'),
(5359, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 16, 16, 'OT', 'Mỗi năm ba lần, mọi người nam trong các ngươi phải ra mắt Đức Giê-hô-va Đức Chúa Trời ngươi, tại nơi mà Ngài sẽ chọn, trong lễ Mùa bánh không men, lễ Bảy tuần và lễ Lều tạm; và không ai được ra mắt Đức Giê-hô-va tay không.'),
(5360, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 16, 17, 'OT', 'Mỗi người dâng theo sự rộng rãi của tay mình, tùy theo phước mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi.'),
(5361, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 16, 18, 'OT', 'Ngươi phải lập các quan xét xử và các viên chức trong các cửa thành của ngươi, tức là các thành mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho các chi phái ngươi; và họ phải xét xử dân sự cách công bình.'),
(5362, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 16, 19, 'OT', 'Ngươi không được làm lệch công lý, không được thiên vị, cũng không được nhận hối lộ, vì hối lộ làm mờ mắt người khôn ngoan và làm sai lạc lời của người công chính.'),
(5363, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 16, 20, 'OT', 'Hãy theo đuổi công lý, công lý trọn vẹn, để ngươi được sống và nhận lấy đất mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi.'),
(5364, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 16, 21, 'OT', 'Chớ trồng cho mình cây A-sê-ra hay bất kỳ cây nào gần bên bàn thờ Đức Giê-hô-va Đức Chúa Trời ngươi mà ngươi sẽ lập.'),
(5365, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 16, 22, 'OT', 'Cũng không được dựng cho mình một trụ thờ, vì Đức Giê-hô-va Đức Chúa Trời ngươi ghét các vật ấy.'),
(5366, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 17, 1, 'OT', 'Ngươi không được dâng cho Đức Giê-hô-va Đức Chúa Trời ngươi con bò đực hoặc con chiên nào có tật, hay bất cứ điều gì xấu, vì điều đó là sự gớm ghiếc đối với Đức Giê-hô-va Đức Chúa Trời ngươi.'),
(5367, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 17, 2, 'OT', 'Khi ở giữa anh em, trong một trong các thành mà Đức Giê-hô-va Đức Chúa Trời anh em ban cho anh em, có một người nam hay nữ làm điều ác trước mặt Đức Giê-hô-va Đức Chúa Trời anh em, để vi phạm giao ước Ngài,'),
(5368, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 17, 3, 'OT', 'đi hầu việc các thần khác và quì lạy chúng, hay là mặt trời, mặt trăng, hoặc toàn thể thiên binh trên trời, điều mà ta không có truyền dạy;'),
(5369, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 17, 4, 'OT', 'Khi điều đó được báo cho ngươi và ngươi nghe thấy, thì ngươi phải điều tra kỹ lưỡng; và này, nếu điều đó là thật, sự việc xác đáng, thì điều gớm ghê này đã được làm trong Y-sơ-ra-ên,'),
(5370, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 17, 5, 'OT', 'Ngươi phải dẫn người đàn ông hay người đàn bà đã làm điều ác này ra khỏi các cổng thành ngươi, là người đàn ông hay người đàn bà đó, rồi ném đá họ cho đến chết.'),
(5371, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 17, 6, 'OT', 'Phải theo lời hai hay ba nhân chứng mới thi hành án tử cho kẻ bị xử tử; không được thi hành án tử theo lời một nhân chứng.'),
(5372, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 17, 7, 'OT', 'Tay các nhân chứng phải tra trước vào nó để giết nó, rồi tay cả dân sự sẽ tra vào sau. Ngươi phải gỡ bỏ kẻ ác khỏi giữa ngươi.'),
(5373, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 17, 8, 'OT', 'Khi nào trong các ngươi có điều gì khó khăn về việc xét xử, giữa huyết với huyết, giữa vụ kiện với vụ kiện, giữa ôn dịch với ôn dịch, tức những việc tranh tụng tại các cửa thành ngươi, thì ngươi phải đứng dậy, đi lên nơi mà Đức Giê-hô-va Đức Chúa Trời ngươi sẽ chọn.'),
(5374, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 17, 9, 'OT', 'Ngươi hãy đến cùng các thầy tế lễ Lê-vi và cùng quan xét, là người sẽ tại nơi ấy trong những ngày đó; ngươi hãy hỏi, và họ sẽ nói cho ngươi biết lời phán xét.'),
(5375, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 17, 10, 'OT', 'Ngươi phải làm theo mọi lời mà họ sẽ báo cho ngươi từ nơi mà Đức Giê-hô-va sẽ chọn, và phải cẩn thận làm theo mọi điều họ dạy ngươi.'),
(5376, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 17, 11, 'OT', 'Hãy làm theo luật pháp mà họ sẽ dạy ngươi, và theo sự xét đoán mà họ sẽ nói cho ngươi; chớ xây ra khỏi điều họ báo cho ngươi, dù về bên phải hay bên trái.'),
(5377, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 17, 12, 'OT', 'Người nào làm cách kiêu ngạo, không chịu nghe theo thầy tế lễ đứng phục vụ tại đó trước mặt Đức Giê-hô-va Đức Chúa Trời ngươi, hoặc không nghe theo quan xét, thì người ấy phải chết; và ngươi phải gạt bỏ điều ác khỏi giữa Y-sơ-ra-ên.'),
(5378, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 17, 13, 'OT', 'Cả dân sẽ nghe và phải sợ, không dám phạm tội nữa.'),
(5379, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 17, 14, 'OT', 'Khi ngươi vào xứ mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi, và đã nhận lấy nó, ở tại đó, rồi nói: Ta sẽ lập một vua cai trị trên ta, như mọi dân tộc chung quanh ta,'),
(5380, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 17, 15, 'OT', 'Ngươi phải lập một vua làm chủ ngươi, là người mà Đức Giê-hô-va Đức Chúa Trời ngươi chọn, phải lập một người trong anh em ngươi làm vua trên ngươi; ngươi không được lập một người ngoại bang làm vua trên ngươi, là người không phải anh em ngươi.'),
(5381, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 17, 16, 'OT', 'Chỉ mình vua ấy không được nhân nhiều ngựa cho mình, và không được khiến dân trở lại xứ Ê-díp-tô để nhân nhiều ngựa; vì Đức Giê-hô-va đã phán cùng các ngươi rằng: Các ngươi sẽ không trở về con đường nầy nữa.'),
(5382, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 17, 17, 'OT', 'Và người không được lấy nhiều vợ làm cho lòng người đi sai lạc; cũng không được thu góp bạc vàng quá nhiều cho mình.'),
(5383, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 17, 18, 'OT', 'Khi người ngồi trên ngôi vương quốc mình, phải chép cho mình bản sao luật pháp nầy trên một cuốn sách, theo bản đã chép trước mặt các thầy tế lễ, là những người Lê-vi.'),
(5384, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 17, 19, 'OT', 'Bản ấy phải ở cùng vua trọn đời, và vua phải đọc trong đó mọi ngày đời mình, để học biết kính sợ Đức Giê-hô-va Đức Chúa Trời mình, và cẩn thận làm theo mọi lời của luật pháp nầy và các điều răn nầy.'),
(5385, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 17, 20, 'OT', 'để lòng người vua không dâng lên cao quá giữa anh em mình, và không xây khỏi điều răn về bên phải hay bên trái, hầu cho người vua và các con trai người được kéo dài những ngày trên ngôi vương quốc giữa Y-sơ-ra-ên.'),
(5386, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 18, 1, 'OT', 'Các thầy tế lễ là người Lê-vi, toàn thể chi phái Lê-vi, sẽ không có phần và sản nghiệp chung với Y-sơ-ra-ên; họ sẽ ăn những lễ vật thiêu của Đức Giê-hô-va và sản nghiệp của Ngài.'),
(5387, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 18, 2, 'OT', 'Vậy, người Lê-vi sẽ không có phần sản nghiệp giữa anh em mình; Đức Giê-hô-va là cơ nghiệp của người, y như Đức Giê-hô-va đã phán với người.'),
(5388, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 18, 3, 'OT', 'Đây sẽ là luật lệ dành cho các thầy tế lễ từ dân: bất cứ ai dâng sinh tế là bò hay chiên, phải trao cho thầy tế lễ cái đùi trước, hai hàm và cái bụng.'),
(5389, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 18, 4, 'OT', 'Ngươi phải đưa cho người phần đầu tiên của ngũ cốc, rượu mới và dầu ô-liu ngươi, cùng phần đầu tiên của lông chiên ngươi.'),
(5390, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 18, 5, 'OT', 'Vì Giê-hô-va Đức Chúa Trời ngươi đã chọn người ấy giữa các chi phái ngươi, để người và các con trai người luôn luôn nhân danh Đức Giê-hô-va phục sự và chầu chực trước mặt Ngài mọi ngày.'),
(5391, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 18, 6, 'OT', 'Khi một người Lê-vi từ một trong các thành của Y-sơ-ra-ên, nơi người đó đang cư ngụ, đến nơi Đức Giê-hô-va chọn, theo trọn ý muốn lòng mình,'),
(5392, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 18, 7, 'OT', 'và người sẽ phục vụ nhân danh Đức Giê-hô-va Đức Chúa Trời mình, như mọi anh em mình là người Lê-vi, đang đứng đó trước mặt Đức Giê-hô-va,'),
(5393, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 18, 8, 'OT', 'Người sẽ ăn phần bằng phần các anh em mình, ngoài phần người có được từ việc bán đất tổ tiên mình.'),
(5394, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 18, 9, 'OT', 'Khi ngươi vào đất mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi, ngươi không được học làm theo những điều gớm ghiếc của các dân tộc ở đó.'),
(5395, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 18, 10, 'OT', 'Giữa các ngươi không được có ai làm con trai hay con gái mình đi ngang qua lửa, không được có người bói toán, thầy xem chỉ, kẻ bói bằng dấu lạ, hay thầy phù thủy.'),
(5396, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 18, 11, 'OT', 'không được làm thầy phù thủy, không được đi hỏi đồng cốt, không được thuật số, cũng không được đi cầu vong;'),
(5397, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 18, 12, 'OT', 'Vì mọi điều làm những việc ấy là điều Đức Giê-hô-va ghét; và chính vì những điều ghê tởm này, nên Đức Giê-hô-va Đức Chúa Trời ngươi đuổi các dân tộc ấy ra khỏi trước mặt ngươi.'),
(5398, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 18, 13, 'OT', 'Ngươi phải trọn vẹn với Đức Giê-hô-va Đức Chúa Trời ngươi.'),
(5399, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 18, 14, 'OT', 'Vì các dân tộc mà ngươi sẽ chiếm lấy, chúng nghe theo những người bói toán và thầy bói; nhưng về phần ngươi, Đức Giê-hô-va Đức Chúa Trời ngươi không cho phép ngươi làm như vậy.'),
(5400, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 18, 15, 'OT', 'Đức Giê-hô-va Đức Chúa Trời ngươi sẽ dấy lên cho các ngươi một đấng tiên tri từ giữa anh em ngươi, như ta; các ngươi phải nghe theo người ấy.'),
(5401, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 18, 16, 'OT', 'Đó là điều mà ngươi đã xin Đức Giê-hô-va Đức Chúa Trời ngươi tại Hô-rếp trong ngày hội tụ, mà rằng: Tôi sẽ không nghe tiếng Đức Giê-hô-va Đức Chúa Trời tôi nữa, và tôi sẽ không thấy ngọn lửa lớn hãi hùng này nữa, hầu tôi khỏi chết.'),
(5402, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 18, 17, 'OT', 'Đức Giê-hô-va phán cùng ta rằng: Chúng nó nói điều tốt mà chúng nó đã nói.'),
(5403, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 18, 18, 'OT', 'Ta sẽ dấy lên cho chúng một đấng tiên tri như ngươi, từ giữa anh em ngươi; Ta sẽ đặt các lời Ta vào miệng người ấy, và người ấy sẽ nói với chúng mọi điều mà Ta truyền cho người ấy.'),
(5404, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 18, 19, 'OT', 'Người nào không nghe theo các lời ta, tức là các lời mà đấng tiên tri sẽ nhân danh ta nói ra, thì chính ta sẽ đòi người ấy phải trả lẽ.'),
(5405, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 18, 20, 'OT', 'Nhưng vị tiên tri nào dám nhân danh ta nói điều ta không truyền cho người ấy nói, hoặc nói nhân danh các thần khác, thì vị tiên tri ấy phải chết.'),
(5406, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 18, 21, 'OT', 'Nếu ngươi nói trong lòng mình rằng: Làm sao chúng ta biết được điều nào Đức Giê-hô-va không phán?'),
(5407, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 18, 22, 'OT', 'Khi đấng tiên tri nói nhân danh Đức Giê-hô-va mà lời nói ấy không xảy đến và không ứng nghiệm, thì đó chính là lời mà Đức Giê-hô-va đã không phán ra; đấng tiên tri ấy đã nói bởi lòng kiêu ngạo; ngươi chớ sợ người ấy.'),
(5408, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 19, 1, 'OT', 'Khi Đức Giê-hô-va Đức Chúa Trời ngươi diệt các dân tộc mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi đất của chúng nó, và ngươi chiếm hữu chúng, rồi ở trong các thành và các nhà của chúng nó,'),
(5409, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 19, 2, 'OT', 'Phải dành riêng ra ba thành giữa xứ mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi để nhận lấy.'),
(5410, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 19, 3, 'OT', 'Hãy sửa sẵn con đường, và chia ba phần lãnh thổ xứ mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi làm sản nghiệp, để bất cứ kẻ nào giết người có thể chạy đến đó mà trốn.'),
(5411, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 19, 4, 'OT', 'Nầy là lời về kẻ giết người sẽ chạy trốn đến nơi ấy và được sống, là kẻ vô ý đánh người đồng loại mình, mà không ghét người ấy từ trước.'),
(5412, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 19, 5, 'OT', 'Giả thử người nầy cùng đi với người lân cận mình vào rừng đốn củi, tay người ấy vung rìu để đốn cây, nhưng lưỡi rìu trượt khỏi cán, bay trúng người lân cận khiến người ấy chết, thì người đó phải chạy trốn đến một trong các thành nầy và được sống.'),
(5413, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 19, 6, 'OT', 'Kẻo chăng, người báo thù mạng sống đuổi theo kẻ giết người, khi cơn giận của người ấy nổi lên, bắt kịp người đó vì đường xa, rồi đánh người ấy chết, mặc dầu người bị giết không đáng bị án tử, vì người ấy không phải là kẻ thù ghét người kia từ trước.'),
(5414, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 19, 7, 'OT', 'Vì vậy, ta truyền cho ngươi rằng: Hãy phân ra cho mình ba thành.'),
(5415, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 19, 8, 'OT', 'Nếu Đức Giê-hô-va Đức Chúa Trời ngươi mở rộng bờ cõi ngươi, như Ngài đã thề với tổ phụ ngươi, và ban cho ngươi tất cả đất đai mà Ngài đã phán sẽ ban cho tổ phụ ngươi,'),
(5416, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 19, 9, 'OT', 'nếu ngươi tuân giữ trọn vẹn mọi điều răn nầy, để thực hiện điều ta truyền cho ngươi ngày nầy, là yêu mến Giê-hô-va Đức Chúa Trời ngươi và đi theo các đường lối Ngài trọn mọi ngày, thì ngươi sẽ thêm cho mình ba thành nữa bên cạnh ba thành đó.'),
(5417, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 19, 10, 'OT', 'Hầu cho huyết vô tội không đổ ra giữa đất nước ngươi mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi làm sản nghiệp, và không có huyết trên ngươi.'),
(5418, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 19, 11, 'OT', 'Nhưng nếu có người ghét người lân cận mình, phục mưu hại người ấy, chỗi dậy đánh người ấy đến chết, rồi người đó chạy trốn đến một trong những thành nầy,'),
(5419, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 19, 12, 'OT', 'Thì các trưởng lão của thành người đó phải đi, đem người ấy ra khỏi nơi đó, và trao người ấy vào tay kẻ báo oán về huyết, để người ấy chết.'),
(5420, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 19, 13, 'OT', 'Mắt ngươi sẽ không thương xót nó; ngươi phải trừ huyết người vô tội khỏi Y-sơ-ra-ên, và ngươi sẽ được phước.'),
(5421, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 19, 14, 'OT', 'Ngươi chớ dời mốc giới của người láng giềng mình, là nơi các tổ tiên ngươi đã đóng, trên phần sản nghiệp ngươi sẽ được nhận, tại đất mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi để nhận lấy.'),
(5422, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 19, 15, 'OT', 'Một người chứng không thể đứng lên làm chứng chống lại một người về bất cứ tội lỗi hay tội phạm nào mà người đó phạm phải; việc chỉ được xác định nhờ lời của hai hoặc ba nhân chứng.'),
(5423, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 19, 16, 'OT', 'Khi có người làm chứng gian dối đứng lên chống lại một người nào, đặng tố cáo người đó phạm tội gian tà.'),
(5424, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 19, 17, 'OT', 'Hai người đàn ông có điều tranh chấp sẽ đứng trước mặt Đức Giê-hô-va, trước mặt các thầy tế lễ và các quan xét đang tại chức trong những ngày ấy.'),
(5425, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 19, 18, 'OT', 'Các quan xét xử phải điều tra kỹ lưỡng; nếu thấy chứng cớ là giả, người làm chứng đã nói dối chống lại anh em mình,'),
(5426, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 19, 19, 'OT', 'thì các ngươi phải làm cho hắn như điều hắn đã toan tính làm cho anh em mình; và ngươi sẽ gột bỏ điều ác khỏi giữa các ngươi.'),
(5427, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 19, 20, 'OT', 'Những người còn lại sẽ nghe và phải sợ, không dám làm điều ác như thế nữa giữa anh em.'),
(5428, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 19, 21, 'OT', 'Mắt ngươi không được thương xót: mạng đền mạng, mắt đền mắt, răng đền răng, tay đền tay, chân đền chân.'),
(5429, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 20, 1, 'OT', 'Khi ngươi ra chiến trận nghịch cùng các kẻ thù mình, và thấy ngựa, xe và dân sự đông hơn mình, thì đừng sợ chúng, vì Đức Giê-hô-va Đức Chúa Trời ngươi, Đấng đã đem ngươi lên khỏi đất Ê-díp-tô, ở cùng ngươi.'),
(5430, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 20, 2, 'OT', 'Khi các ngươi đến gần trận chiến, thì thầy tế lễ sẽ tiến lên và nói với dân sự.'),
(5431, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 20, 3, 'OT', 'Hỡi Y-sơ-ra-ên, hãy nghe! Các ngươi hôm nay đến gần cuộc chiến chống lại kẻ thù các ngươi; lòng các ngươi chớ yếu đuối, chớ sợ hãi, chớ hấp tấp, và chớ kinh hoàng trước mặt chúng nó.'),
(5432, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 20, 4, 'OT', 'Vì Đức Giê-hô-va Đức Chúa Trời các ngươi đi cùng các ngươi, để chiến đấu cho các ngươi chống lại kẻ thù của các ngươi và giải cứu các ngươi.'),
(5433, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 20, 5, 'OT', 'Các quan trưởng sẽ nói với dân chúng rằng: Ai là người đã xây một ngôi nhà mới mà chưa làm lễ khánh thành, thì hãy đi trở về nhà mình, e rằng người ấy chết trong cuộc chiến, rồi một người khác phải làm lễ khánh thành cho nó.'),
(5434, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 20, 6, 'OT', 'Ai là người đã trồng một vườn nho mà chưa hưởng sản của nó? Người ấy hãy đi trở về nhà mình, e rằng người ấy chết trong cuộc chiến, rồi một người khác sẽ hưởng sản của nó.'),
(5435, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 20, 7, 'OT', 'Người nào đã đính hôn một người nữ mà chưa cưới nàng, thì hãy đi trở về nhà mình, e rằng người ấy chết trong cuộc chiến, rồi một người khác sẽ cưới nàng.'),
(5436, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 20, 8, 'OT', 'Các quan xét sẽ tiếp tục nói với dân chúng và bảo: "Ai là người sợ hãi, lòng yếu đuối, hãy đi trở về nhà mình, để khỏi làm tan nát lòng anh em mình như lòng mình."'),
(5437, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 20, 9, 'OT', 'Khi các quan xét nói xong với dân sự, thì những tướng các đạo quân sẽ đứng đầu dân sự.'),
(5438, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 20, 10, 'OT', 'Khi ngươi đến gần một thành để đánh giặc chống lại nó, trước hết phải kêu gọi nó giảng hòa.'),
(5439, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 20, 11, 'OT', 'Nếu nó đáp lời hòa bình và mở cửa cho ngươi, thì toàn dân cư ngụ trong đó sẽ phải phục dịch ngươi và nộp thuế cho ngươi.'),
(5440, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 20, 12, 'OT', 'Nếu nó không chịu hòa thuận với ngươi, mà gây chiến cùng ngươi, thì ngươi phải vây hãm thành ấy.'),
(5441, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 20, 13, 'OT', 'Giê-hô-va Đức Chúa Trời ngươi sẽ phó nó vào tay ngươi, rồi ngươi đánh giết mọi người nam bằng lưỡi gươm.'),
(5442, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 20, 14, 'OT', 'Chỉ những người đàn bà, con trẻ, súc vật và mọi vật gì trong thành, tức là toàn bộ chiến lợi phẩm, ngươi sẽ lấy làm của mình; và ngươi sẽ ăn chiến lợi phẩm của các kẻ thù ngươi mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi.'),
(5443, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 20, 15, 'OT', 'Ngươi phải làm như vậy đối với mọi thành ở xa ngươi rất nhiều, không thuộc các thành của những dân tộc nầy.'),
(5444, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 20, 16, 'OT', 'Nhưng trong các thành của các dân nầy, mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi làm sản nghiệp, ngươi không được để sống một sinh mạng nào.'),
(5445, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 20, 17, 'OT', 'phải tận diệt các dân Hê-tít, A-mô-rít, Ca-na-an, Phê-rê-sít, Hê-vít và Giê-bu-sít, y như điều Đức Giê-hô-va Đức Chúa Trời ngươi đã truyền dạy.'),
(5446, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 20, 18, 'OT', 'để chúng nó không dạy các ngươi làm theo những điều gớm ghiếc mà chúng nó đã làm cho các thần của chúng nó, hầu cho các ngươi khỏi phạm tội cùng Đức Giê-hô-va Đức Chúa Trời các ngươi'),
(5447, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 20, 19, 'OT', 'Khi ngươi vây một thành nhiều ngày, để chiến đấu chống lại nó nhằm chiếm lấy, thì không được phá hủy các cây cối của nó bằng cách dùng rìu chặt xuống; vì ngươi có thể ăn từ các cây ấy, nên không được chặt nó đi. Bởi người là cây của đồng ruộng sao, để vào trước mặt ngươi trong cuộc vây hãm?'),
(5448, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 20, 20, 'OT', 'Chỉ những cây mà ngươi biết không phải là cây ăn quả thì ngươi mới được phá hại và chặt đi; ngươi phải dùng chúng để xây đồn lũy chống lại thành đang giao chiến với ngươi, cho đến khi thành ấy bị khuất phục.'),
(5449, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 21, 1, 'OT', 'Khi trong đất mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi để nhận lấy, tìm thấy một người bị giết nằm trên đồng, không biết ai đã đánh người ấy,'),
(5450, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 21, 2, 'OT', 'Bấy giờ các trưởng lão và quan xét của ngươi phải đi ra, đo đạc khoảng cách đến các thành ở chung quanh nơi người bị giết nằm.'),
(5451, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 21, 3, 'OT', 'Vậy thì thành nào gần nhất với người bị giết, các trưởng lão của thành ấy phải lấy một con bò cái tơ chưa từng bị dùng vào việc gì, chưa từng kéo ách,'),
(5452, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 21, 4, 'OT', 'Các trưởng lão của thành ấy phải đem con bò cái tơ xuống một dòng nước chảy mạnh, là nơi không được cày cấy, rồi bẻ cổ con bò cái tơ ấy trong khe nước.'),
(5453, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 21, 5, 'OT', 'Các thầy tế lễ là con trai Lê-vi sẽ đến gần, vì Đức Giê-hô-va Đức Chúa Trời ngươi đã chọn họ để hầu việc Ngài và để chúc phước nhân danh Đức Giê-hô-va; và theo lời của họ sẽ xét đoán mọi sự tranh chấp và mọi việc thương tích.'),
(5454, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 21, 6, 'OT', 'Tất cả các trưởng lão của thành ấy, là những người gần nhất với người bị giết, sẽ rửa tay mình trên con bò cái tơ bị bẻ cổ ở trong suối.'),
(5455, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 21, 7, 'OT', 'Chúng tôi xin thưa: tay chúng tôi không đổ máu này, và mắt chúng tôi không thấy điều đó.'),
(5456, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 21, 8, 'OT', 'Xin Đức Giê-hô-va làm ơn chuộc tội cho dân Y-sơ-ra-ên mà Ngài đã chuộc; chớ để huyết vô tội ở giữa dân sự Ngài, Y-sơ-ra-ên; thì huyết đó sẽ được tha cho họ.'),
(5457, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 21, 9, 'OT', 'Ngươi phải tẩy sạch huyết vô tội khỏi giữa các ngươi, để làm điều phải trước mặt Đức Giê-hô-va.'),
(5458, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 21, 10, 'OT', 'Khi ngươi ra chiến trận chống lại các kẻ thù mình, và Giê-hô-va Đức Chúa Trời ngươi trao chúng vào tay ngươi, và ngươi bắt được những kẻ bị đày làm phu tù,'),
(5459, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 21, 11, 'OT', 'Khi ngươi thấy giữa những người bị bắt làm phu tù một người nữ xinh đẹp, và ngươi ưa chuộng nàng, muốn lấy nàng làm vợ,'),
(5460, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 21, 12, 'OT', 'và dẫn nàng vào trong nhà ngươi; nàng sẽ cạo đầu mình, làm móng tay mình;'),
(5461, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 21, 13, 'OT', 'cởi bỏ áo tang, ở trong nhà ngươi khóc cha và mẹ mình một tháng trăng; rồi sau đó, ngươi sẽ đến cùng nàng, ăn ở với nàng, và nàng sẽ làm vợ ngươi.'),
(5462, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 21, 14, 'OT', 'Nếu sau này ngươi không còn ưa nàng nữa, thì phải để nàng đi theo ý nàng; ngươi không được bán nàng lấy tiền, cũng không được đối xử tàn tệ với nàng, vì ngươi đã chiếm đoạt nàng.'),
(5463, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 21, 15, 'OT', 'Khi một người đàn ông có hai vợ, người này được yêu, người kia bị ghét, và cả hai đều sinh con cho người ấy, nếu con trai đầu lòng thuộc về người vợ bị ghét,'),
(5464, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 21, 16, 'OT', 'Khi người chia sản nghiệp cho các con trai mình, thì không được phép cho con trai của người vợ được yêu thương hưởng quyền trưởng nam thay cho con trai của người vợ bị ghét, mặc dù nó mới thật sự là trưởng nam.'),
(5465, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 21, 17, 'OT', 'Nhưng ngươi phải công nhận con trai đầu lòng của người vợ bị ghét, mà cho nó hưởng phần gấp đôi trong mọi tài sản ngươi có; vì nó là sự khởi đầu sức lực ngươi, quyền trưởng nam thuộc về nó.'),
(5466, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 21, 18, 'OT', 'Khi một người có con trai bướng bỉnh và phản nghịch, không nghe tiếng cha mình và không nghe tiếng mẹ mình, và họ đã sửa dạy nó mà nó vẫn không nghe theo chúng,'),
(5467, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 21, 19, 'OT', 'Thì cha mẹ phải nắm lấy nó, dẫn nó đến các trưởng lão của thành mình và đến nơi cửa thành mình.'),
(5468, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 21, 20, 'OT', 'Họ sẽ nói cùng các trưởng lão của thành mình rằng: Con trai chúng tôi nầy là kẻ bội nghịch, không nghe lời chúng tôi, ăn uống lãng phí và say sưa.'),
(5469, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 21, 21, 'OT', 'Cả những người trong thành ấy sẽ lấy đá ném nó cho chết; ngươi phải gạt bỏ điều ác khỏi giữa ngươi, và cả Y-sơ-ra-ên sẽ nghe biết điều đó và sẽ sợ.'),
(5470, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 21, 22, 'OT', 'Nếu một người phạm tội đáng chết và bị xử tử, thì ngươi phải treo người ấy trên cây.'),
(5471, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 21, 23, 'OT', 'Không được để xác người bị treo trên cây qua đêm, phải chôn người ấy trong ngày hôm đó, vì kẻ bị treo là bị Đức Chúa Trời rủa sả; như vậy, ngươi sẽ không làm ô uế đất mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi làm sản nghiệp.'),
(5472, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 22, 1, 'OT', 'Nếu ngươi thấy bò hay chiên của anh em mình bị lạc, thì không được làm như không thấy; phải dẫn nó về trả cho anh em mình.'),
(5473, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 22, 2, 'OT', 'Nếu anh em ngươi không gần ngươi và ngươi không biết người ấy, thì phải thu góp nó vào giữa nhà ngươi; nó sẽ ở cùng ngươi cho đến khi anh em ngươi đến tìm nó, rồi ngươi phải trả lại cho người ấy.'),
(5474, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 22, 3, 'OT', 'Cũng vậy, ngươi phải làm cho lừa của người anh em ngươi, cũng vậy cho áo xống người anh em ngươi, và cũng vậy cho mọi vật gì bị mất của người anh em ngươi mà ngươi tìm được; ngươi không được làm ngơ.'),
(5475, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 22, 4, 'OT', 'Không được thấy lừa hay bò của anh em mình ngã trên đường mà làm ngơ; phải giúp đỡ người ấy cùng đứng dậy.'),
(5476, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 22, 5, 'OT', 'Người nữ không được mặc quần áo của người nam, và người nam cũng không được mặc áo của người nữ, vì mọi kẻ làm điều đó đều là sự gớm ghiếc cho Đức Giê-hô-va Đức Chúa Trời ngươi.'),
(5477, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 22, 6, 'OT', 'Khi ngươi gặp trên đường một tổ chim, hoặc trên cây hoặc dưới đất, có những chim non hoặc trứng, và chim mẹ đang nằm ấp trên những chim non hoặc trên các trứng, thì ngươi không được bắt chim mẹ cùng với các con.'),
(5478, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 22, 7, 'OT', 'Phải thả chim mẹ đi, nhưng có thể bắt các con cho mình, để ngươi được phước và sống lâu.'),
(5479, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 22, 8, 'OT', 'Khi ngươi xây một ngôi nhà mới, phải làm lan can quanh mái nhà ngươi, để khỏi làm đổ huyết trong nhà ngươi, nếu người nào ngã từ trên đó xuống.'),
(5480, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 22, 9, 'OT', 'Đừng gieo trồng trong vườn nho ngươi các thứ giống khác nhau, e rằng cả sản vật ngươi đã gieo và hoa lợi của vườn nho đều bị biệt riêng làm thánh.'),
(5481, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 22, 10, 'OT', 'Chớ cày bằng con bò và con lừa cùng nhau.'),
(5482, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 22, 11, 'OT', 'Không được mặc đồ dệt bằng len và gai kết hợp chung với nhau.'),
(5483, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 22, 12, 'OT', 'Ngươi phải làm các tua nơi bốn góc áo choàng mà ngươi dùng để che mình.'),
(5484, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 22, 13, 'OT', 'Khi một người đàn ông lấy vợ, vào cùng nàng, rồi ghét nàng,'),
(5485, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 22, 14, 'OT', 'và đặt cho nàng những điều buộc tội, làm xấu danh tiếng nàng, mà nói rằng: Tôi đã cưới người đàn bà này, khi đến gần nàng, thì thấy nàng không còn trinh tiết,'),
(5486, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 22, 15, 'OT', 'Vậy cha và mẹ của người trai trẻ sẽ lấy và mang những bằng chứng về sự trinh tiết của người trai trẻ ra trình trước mặt các trưởng lão của thành ấy, tại cửa thành.'),
(5487, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 22, 16, 'OT', 'Cha của người gái sẽ nói cùng các trưởng lão: Tôi đã gả con gái tôi cho người đàn ông này làm vợ, nhưng anh ta lại ghét nàng.'),
(5488, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 22, 17, 'OT', 'Và nầy, hắn đặt điều vu khống, nói rằng: Tôi không thấy trinh tiết nơi con gái ông; nhưng nầy là dấu chỉ trinh tiết của con gái tôi. Rồi cha mẹ sẽ trải tấm áo ra trước mặt các trưởng lão của thành.'),
(5489, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 22, 18, 'OT', 'Bấy giờ các trưởng lão của thành ấy sẽ bắt người đàn ông đó và sửa phạt người ấy.'),
(5490, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 22, 19, 'OT', 'Và họ sẽ phạt người ấy một trăm miếng bạc và trao cho cha của cô gái, vì người ấy đã vu cáo danh tiếng của một trinh nữ Y-sơ-ra-ên; và người ấy phải giữ nàng làm vợ mình, không được rẫy nàng suốt đời.'),
(5491, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 22, 20, 'OT', 'Nhưng nếu điều đó là thật, người ta không tìm thấy trinh tiết nơi người gái trẻ.'),
(5492, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 22, 21, 'OT', 'Những người trong thành phải dẫn nàng ra tận cửa nhà cha nàng và dân thành lấy đá ném nàng cho chết; vì nàng đã làm điều nhục nhã trong Y-sơ-ra-ên khi hành dâm trong nhà cha mình. Ngươi phải trục xuất điều ác khỏi giữa ngươi.'),
(5493, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 22, 22, 'OT', 'Nếu người ta phát hiện một người nam đang nằm với một người nữ có chồng, thì cả hai người ấy, người nam đã nằm với người nữ và người nữ đó, đều phải chết; ngươi phải loại bỏ điều ác khỏi Y-sơ-ra-ên.'),
(5494, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 22, 23, 'OT', 'Khi một người nữ đồng trinh đã đính hôn với một người nam, mà có người nam khác gặp nàng trong thành phố và nằm cùng nàng,'),
(5495, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 22, 24, 'OT', 'Các ngươi phải đem cả hai người ra cổng thành đó, rồi ném đá cho họ chết: người trai trẻ vì đã không kêu la trong thành, và người đàn ông vì đã làm ô nhục vợ người đồng loại mình; như vậy, các ngươi sẽ diệt trừ điều ác khỏi giữa các ngươi.'),
(5496, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 22, 25, 'OT', 'Nếu người đàn ông gặp cô gái đã đính hôn trong đồng ruộng, rồi người đàn ông ấy ép nàng và nằm với nàng, thì chỉ mình người đàn ông ấy phải chết.'),
(5497, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 22, 26, 'OT', 'Chớ làm gì cho người nữ trẻ tuổi đó; nàng không phạm tội đáng chết. Vì điều đó giống như khi một người trỗi dậy nghịch cùng người lân cận mình mà giết đi mạng sống người ấy; chính điều nầy cũng vậy.'),
(5498, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 22, 27, 'OT', 'vì người ta gặp nàng ở ngoài đồng, nàng đã kêu cứu nhưng không có ai giải cứu cho nàng.'),
(5499, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 22, 28, 'OT', 'Nếu một người nam gặp một cô gái trẻ đồng trinh, chưa đính hôn, rồi nắm lấy nàng và nằm cùng nàng, mà người ta phát hiện ra,'),
(5500, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 22, 29, 'OT', 'Người nam đã nằm cùng cô gái trẻ ấy phải đưa cho cha của nàng năm mươi miếng bạc; và nàng sẽ trở thành vợ người đó, vì người ấy đã làm nhục nàng; trọn đời người đó không được phép đuổi nàng đi.'),
(5501, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 22, 30, 'OT', 'Người đàn ông không được lấy vợ của cha mình, và không được tiết lộ sự che khuất của cha mình.'),
(5502, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 23, 1, 'OT', 'Người bị hoạn, hoặc bị dập tinh hoàn, hay bị cắt dương vật, thì không được vào hội của Đức Giê-hô-va.'),
(5503, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 23, 2, 'OT', 'Con hoang không được vào hội của Đức Giê-hô-va; ngay cả đến đời thứ mười cũng không được vào hội của Đức Giê-hô-va.'),
(5504, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 23, 3, 'OT', 'Người Am-môn và người Mô-áp không được vào hội của Đức Giê-hô-va; ngay cả đến đời thứ mười cũng không được vào hội của Đức Giê-hô-va mãi mãi.'),
(5505, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 23, 4, 'OT', 'vì chúng không ra đón tiếp các ngươi với bánh và nước trên đường khi các ngươi ra đi từ xứ Ai Cập, và vì chúng đã mướn Ba-la-am, con trai Bê-ô, ở Phê-thô-rơ, Mê-sô-bô-ta-mi, để nguyền rủa ngươi.'),
(5506, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 23, 5, 'OT', 'Nhưng Đức Giê-hô-va Đức Chúa Trời ngươi không chịu nghe Ba-la-am, nên Đức Giê-hô-va Đức Chúa Trời ngươi đã đổi lời rủa cho ngươi ra lời chúc phước, vì Đức Giê-hô-va Đức Chúa Trời ngươi yêu mến ngươi.'),
(5507, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 23, 6, 'OT', 'Trọn đời ngươi, không được cầu sự bình an và phước lành cho chúng nó, đến mãi mãi.'),
(5508, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 23, 7, 'OT', 'Không được khinh bỉ người Ê-đôm, vì người ấy là anh em ngươi; không được khinh bỉ người Ai Cập, vì ngươi đã từng là khách lạ trong đất nước của họ.'),
(5509, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 23, 8, 'OT', 'Con cái sanh ra cho chúng, đến đời thứ ba, sẽ được vào hội của Đức Giê-hô-va.'),
(5510, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 23, 9, 'OT', 'Khi ngươi ra khỏi trại để nghịch cùng kẻ thù mình, phải giữ mình khỏi mọi điều ác.'),
(5511, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 23, 10, 'OT', 'Nếu trong các ngươi có người nào không được tinh sạch vì điều xảy đến trong đêm, thì phải ra ngoài trại, không được vào giữa trại.'),
(5512, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 23, 11, 'OT', 'Buổi chiều, người ấy phải tắm trong nước; rồi khi mặt trời lặn, mới được vào trong trại.'),
(5513, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 23, 12, 'OT', 'Ngươi cũng phải có một nơi ở ngoài trại, là nơi ngươi sẽ đi ra đó.'),
(5514, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 23, 13, 'OT', 'Ngươi phải có một cái mai trong đồ dùng của mình; khi ngươi ra ngoài đi vệ sinh, hãy dùng nó đào hố, rồi quay lại lấp phân mình lại.'),
(5515, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 23, 14, 'OT', 'Vì Đức Giê-hô-va Đức Chúa Trời ngươi đang đi giữa trại quân ngươi, để giải cứu ngươi và phó các kẻ thù nghịch ngươi vào tay ngươi; nên trại quân ngươi phải thánh, hầu cho Ngài chẳng thấy điều gì bất khiết trong ngươi, mà phải xây khỏi ngươi.'),
(5516, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 23, 15, 'OT', 'Không được giao nộp kẻ tôi tớ chạy trốn đến với ngươi khỏi chủ mình.'),
(5517, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 23, 16, 'OT', 'Nó sẽ ở cùng ngươi, giữa vòng ngươi, tại nơi nào nó chọn trong một trong các cửa thành ngươi, tùy theo điều tốt cho nó; ngươi không được ngược đãi nó.'),
(5518, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 23, 17, 'OT', 'Trong các con gái Y-sơ-ra-ên, không được có người làm nghề điếm; và trong các con trai Y-sơ-ra-ên, không được có người làm nghề dâm ô.'),
(5519, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 23, 18, 'OT', 'Chớ đem tiền công của một người nữ điếm hay giá bán một con chó vào nhà của Đức Giê-hô-va Đức Chúa Trời ngươi để dâng bất cứ lễ vật nào, vì cả hai điều đó đều là sự gớm ghiếc cho Đức Giê-hô-va Đức Chúa Trời ngươi.'),
(5520, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 23, 19, 'OT', 'Ngươi không được đòi anh em mình lời về tiền bạc, lời về đồ ăn, lời về bất cứ vật gì có thể sinh lời.'),
(5521, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 23, 20, 'OT', 'Ngươi được phép cho người ngoại bang vay lấy lợi, nhưng không được lấy lợi của anh em mình, để Đức Giê-hô-va Đức Chúa Trời ngươi ban phước cho ngươi trong mọi công việc tay ngươi làm, tại đất mà ngươi sắp vào để chiếm lấy.'),
(5522, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 23, 21, 'OT', 'Nếu ngươi hứa một lời khấn cùng Đức Giê-hô-va Đức Chúa Trời ngươi, thì chớ chậm trễ thực hiện; vì Đức Giê-hô-va Đức Chúa Trời ngươi sẽ đòi ngươi thực hiện, và ngươi sẽ mắc tội.'),
(5523, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 23, 22, 'OT', 'Nhưng nếu ngươi kiêng không hứa hứa nguyện, thì sẽ không có tội trong ngươi.'),
(5524, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 23, 23, 'OT', 'Khi môi ngươi hứa điều gì cùng Đức Giê-hô-va Đức Chúa Trời ngươi, thì phải giữ lời hứa và làm trọn điều ngươi đã nói ra bằng miệng mình.'),
(5525, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 23, 24, 'OT', 'Khi ngươi vào vườn nho của người láng giềng mình, thì được ăn nho tùy theo lòng mình muốn cho đến no, nhưng không được bỏ vào túi mình.'),
(5526, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 23, 25, 'OT', 'Khi ngươi vào ruộng lúa của người đồng loại mình, được phép hái những bông lúa bằng tay; nhưng không được vung lưỡi hái trên ruộng lúa của người đồng loại mình.'),
(5527, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 24, 1, 'OT', 'Khi một người đàn ông lấy vợ và ăn ở với nàng, nếu sau đó nàng không đẹp lòng người, vì người thấy nơi nàng một điều gì đáng ghét, thì người phải viết một giấy ly dị, trao vào tay nàng và đuổi nàng khỏi nhà mình.'),
(5528, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 24, 2, 'OT', 'Thì nàng ra khỏi nhà người đó, đi và trở thành vợ của một người khác.'),
(5529, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 24, 3, 'OT', 'Nếu người chồng sau ghét nàng, thì phải viết cho nàng một giấy ly dị, trao vào tay nàng và đuổi nàng ra khỏi nhà; hoặc nếu người chồng sau ấy, người đã cưới nàng làm vợ, chết đi,'),
(5530, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 24, 4, 'OT', 'Người chồng đầu tiên đã để nàng đi, không được phép trở lại đón nàng làm vợ, sau khi nàng đã bị ô uế; vì điều đó là một điều gớm ghê trước mặt Đức Giê-hô-va; ngươi chớ làm cho đất mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi làm sản nghiệp bị tội lỗi.'),
(5531, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 24, 5, 'OT', 'Khi một người đàn ông mới cưới vợ, thì không được ra đi chiến trận, cũng không bị bắt làm bất cứ công việc gì; người ấy phải được miễn trừ để ở nhà trọn một năm, và vui vẻ cùng người vợ mình đã cưới.'),
(5532, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 24, 6, 'OT', 'Không được lấy cái cối xay dưới hay trên làm vật cầm cố, vì như vậy là cầm giữ mạng sống của người ta.'),
(5533, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 24, 7, 'OT', 'Nếu ai bị bắt gặp đang ăn cắp một người anh em mình thuộc dân Y-sơ-ra-ên, rồi ngược đãi và bán người ấy đi, thì tên trộm đó phải bị xử tử; ngươi phải trừng trừ điều ác khỏi giữa ngươi.'),
(5534, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 24, 8, 'OT', 'Hãy coi chừng tai vạ của bệnh phung, phải hết sức gìn giữ và làm theo mọi điều mà các thầy tế lễ, những người Lê-vi, sẽ chỉ dạy các ngươi; các ngươi phải tuân giữ và làm theo đúng như ta đã truyền cho họ.'),
(5535, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 24, 9, 'OT', 'Hãy nhớ điều Đức Giê-hô-va đã làm cho Mi-ri-am dọc đường khi các ngươi ra khỏi Ai Cập.'),
(5536, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 24, 10, 'OT', 'Khi ngươi cho người anh em mình vay một món đồ vật gì, thì không được vào nhà người ấy để lấy đồ cầm của người ấy.'),
(5537, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 24, 11, 'OT', 'Ngươi phải đứng ở bên ngoài, còn người mà ngươi cho vay sẽ mang đồ cầm ra ngoài đưa cho ngươi.'),
(5538, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 24, 12, 'OT', 'Nếu người ấy nghèo, ngươi không được ngủ với áo choàng mà người đó thế chấp.'),
(5539, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 24, 13, 'OT', 'Phải trả lại áo cho người ấy trước khi mặt trời lặp, để người có thể ngủ trong áo choàng của mình và chúc phước cho ngươi; và điều đó sẽ là sự công bình cho ngươi trước mặt Đức Giê-hô-va Đức Chúa Trời ngươi.'),
(5540, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 24, 14, 'OT', 'Ngươi không được hà hiếp người làm công nghèo và túng thiếu, dù là anh em ngươi hay là khách lạ ở trong đất ngươi, trong các thành ngươi.'),
(5541, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 24, 15, 'OT', 'Trong ngày ấy, phải trả tiền công cho người làm công, không để mặt trời lặn trước khi trả, vì người ấy nghèo, và chính mạng sống người ấy trông đợi vào tiền công đó; kẻo người kêu lên Đức Giê-hô-va chống lại ngươi, và ngươi sẽ mắc tội.'),
(5542, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 24, 16, 'OT', 'Không được giết cha vì tội của con, cũng không được giết con vì tội của cha; mỗi người phải bị giết vì tội riêng của mình.'),
(5543, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 24, 17, 'OT', 'Không được xử oan án của người ngoại và kẻ mồ côi, cũng không được cầm áo choàng của người góa bụ0'),
(5544, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 24, 18, 'OT', 'Hãy nhớ rằng ngươi đã làm đầy tớ trong xứ Ai Cập, và Đức Giê-hô-va Đức Chúa Trời ngươi đã cứu chuộc ngươi khỏi đó. Bởi vậy, ta truyền cho ngươi phải thực hiện điều nầy.'),
(5545, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 24, 19, 'OT', 'Khi ngươi gặt lúa trong đồng ruộng mình và quên mất một bó lúa tại đó, thì không được trở lại lấy; bó lúa ấy phải dành cho khách lạ, cho kẻ mồ côi và người góa bụa, để Đức Giê-hô-va Đức Chúa Trời ngươi ban phước cho ngươi trong mọi công việc của tay ngươi làm.'),
(5546, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 24, 20, 'OT', 'Khi ngươi vặt cây ô-li-ve mình, không được mót lại những trái sót lại phía sau; ấy sẽ về phần cho khách lạ, kẻ mồ côi và người góa bụa.'),
(5547, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 24, 21, 'OT', 'Khi ngươi hái nho nơi vườn nho mình, không được mót lại những gì còn sót; điều đó phải dành cho người ngoại, kẻ mồ côi và người goá bụa.'),
(5548, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 24, 22, 'OT', 'Hãy nhớ rằng ngươi đã từng là kẻ nô lệ trong đất Ai Cập; vì lý do đó, ta truyền cho ngươi phải thực hiện điều này.'),
(5549, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 25, 1, 'OT', 'Khi giữa hai người có sự tranh chấp, họ sẽ đến trước tòa án, và các quan án sẽ xét xử; họ phải tuyên người vô tội là công bình, và tuyên người có tội là gian ác.'),
(5550, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 25, 2, 'OT', 'Nếu người phạm tội đáng bị đánh, thì quan xét phải khiến người ấy nằm xuống và đánh trước mặt mình, theo số lần tương xứng với tội lỗi của người đó.'),
(5551, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 25, 3, 'OT', 'Đánh người ấy bốn mươi roi, chớ đánh quá mức, e rằng nếu cứ đánh quá mức ấy, anh em ngươi sẽ bị sỉ nhục trước mặt ngươi.'),
(5552, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 25, 4, 'OT', 'Đừng lấy vật gì bịt mõm con bò khi nó đạp lúa.'),
(5553, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 25, 5, 'OT', 'Khi anh em sống chung với nhau, nếu một người trong các anh em ấy chết mà không có con trai, thì vợ của người chết không được lấy người ngoài; anh em chồng phải đến cùng nàng, lấy nàng làm vợ mình và thực hiện bổn phận của anh em chồng.'),
(5554, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 25, 6, 'OT', 'Con đầu lòng mà người đàn bà sinh ra sẽ mang danh nghĩa cho anh em đã chết của chồng mình, hầu cho danh người ấy không bị xoá khỏi Y-sơ-ra-ên.'),
(5555, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 25, 7, 'OT', 'Nếu người anh em chồng không muốn lấy nàng làm vợ, thì nàng phải lên cùng các trưởng lão tại cổng thành và nói: "Người anh em chồng tôi không chịu lưu danh cho anh em mình trong Y-sơ-ra-ên; người ấy không chịu cưới tôi theo luật anh em chồng."'),
(5556, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 25, 8, 'OT', 'Các trưởng lão của thành người ấy sẽ gọi người đó và nói với người ấy; người ấy sẽ đứng lên và nói: Tôi không muốn lấy nàng.'),
(5557, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 25, 9, 'OT', 'Nếu người anh em dâu người lại gần người, trước mặt các trưởng lão, cởi giày khỏi chân người, khạc vào mặt người và lên tiếng nói rằng: "Cũng sẽ làm cho người đàn ông nào không xây lại nhà anh em mình như thế này!"'),
(5558, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 25, 10, 'OT', 'Trong Y-sơ-ra-ên, nhà người sẽ được gọi là nhà kẻ bị lột giày.'),
(5559, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 25, 11, 'OT', 'Khi hai người đánh nhau, nếu vợ của một người đến gần để cứu chồng mình khỏi tay kẻ đánh anh ấy, và nàng đưa tay ra, nắm lấy chỗ kín của người ấy,'),
(5560, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 25, 12, 'OT', 'thì ngươi phải chặt tay nàng; mắt ngươi chớ thương xót nàng.'),
(5561, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 25, 13, 'OT', 'Trong túi ngươi không được có hai thứ đá, một thứ lớn và một thứ nhỏ.'),
(5562, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 25, 14, 'OT', 'Trong nhà ngươi không được có hai e-phah, một cái lớn và một cái nhỏ.'),
(5563, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 25, 15, 'OT', 'Phải có hòn đá trọn vẹn và công bình, và ê-pha trọn vẹn và công bình, để các ngày của ngươi được dài lâu trên đất mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi.'),
(5564, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 25, 16, 'OT', 'Vì mọi kẻ làm các điều nầy, mọi kẻ làm điều gian ác, đều là sự gớm ghiếc cho Đức Giê-hô-va Đức Chúa Trời ngươi.'),
(5565, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 25, 17, 'OT', 'Hãy nhớ điều A-ma-léc đã làm cho ngươi trên đường khi các ngươi ra khỏi Ai-cập.'),
(5566, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 25, 18, 'OT', 'đã đến đón ngươi trên đường, xông vào những người yếu đuối nhất theo sau ngươi, trong khi ngươi đang mệt mỏi và kiệt sức, và không kính sợ Đức Chúa Trời.'),
(5567, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 25, 19, 'OT', 'Khi Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi được an nghỉ khỏi mọi kẻ thù xung quanh trong đất mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi nhận lấy làm sản nghiệp, ngươi phải xoá sạch dấu tích của A-ma-léc khỏi dưới trời. Đừng bao giờ quên điều đó.'),
(5568, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 26, 1, 'OT', 'Khi ngươi vào trong đất mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho làm sản nghiệp, ngươi sẽ nhận lấy và ở trong đó,'),
(5569, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 26, 2, 'OT', 'Hãy lấy hoa quả đầu mùa của mọi sản vật đất đai mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi, đặt vào một cái rổ, rồi đi đến nơi mà Đức Giê-hô-va Đức Chúa Trời ngươi sẽ chọn để đặt danh Ngài tại đó.'),
(5570, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 26, 3, 'OT', 'Ngươi sẽ đến cùng thầy tế lễ, là người sẽ tại chức trong những ngày đó, mà nói cùng người rằng: Tôi đã báo cho Đức Giê-hô-va Đức Chúa Trời của ông hôm nay rằng tôi đã vào trong đất mà Đức Giê-hô-va đã thề cùng tổ phụ chúng tôi để ban cho chúng tôi.'),
(5571, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 26, 4, 'OT', 'Thầy tế lễ sẽ nhận cái giỏ khỏi tay ngươi và đặt trước bàn thờ Đức Giê-hô-va Đức Chúa Trời ngươi.'),
(5572, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 26, 5, 'OT', 'Ngươi sẽ cất tiếng nói trước mặt Đức Giê-hô-va Đức Chúa Trời ngươi rằng: "Tổ phụ tôi là người A-ram bị mất, đi xuống Ai-cập và kiều ngụ tại đó với số ít người, rồi trở thành một dân lớn, mạnh mẽ và đông đảo."'),
(5573, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 26, 6, 'OT', 'Người Ai Cập đã đối xử ác với chúng tôi, làm cho chúng tôi khốn khổ, và bắt chúng tôi làm việc nặng nhọc.'),
(5574, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 26, 7, 'OT', 'Chúng tôi kêu lên cùng Đức Giê-hô-va Đức Chúa Trời của tổ phụ chúng tôi; Đức Giê-hô-va đã nghe tiếng kêu của chúng tôi, đã thấy cảnh khốn khổ, công việc vất vả và sự hà hiếp chúng tôi phải chịu.'),
(5575, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 26, 8, 'OT', 'Đức Giê-hô-va đem chúng tôi ra khỏi xứ Ai Cập bằng tay hùng mạnh, bằng cánh tay giơ thẳng ra, bằng sự kinh khủng lớn, bằng các dấu kỳ và phép lạ.'),
(5576, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 26, 9, 'OT', 'Đức Giê-hô-va dẫn chúng tôi đến nơi nầy và ban cho chúng tôi đất nầy, tức là đất chảy sữa và mật ong.'),
(5577, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 26, 10, 'OT', 'Vậy bây giờ, nầy, tôi đã đem những hoa quả đầu mùa của đất mà Đức Giê-hô-va đã ban cho tôi; và ngươi sẽ đặt nó trước mặt Đức Giê-hô-va Đức Chúa Trời ngươi, và ngươi sẽ thờ lạy trước mặt Đức Giê-hô-va Đức Chúa Trời ngươi.'),
(5578, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 26, 11, 'OT', 'Ngươi và người Lê-vi, cùng với người ngoại kiều ở giữa ngươi, sẽ vui mừng về mọi điều lành mà Đức Giê-hô-va Đức Chúa Trời ngươi đã ban cho ngươi và cho nhà ngươi.'),
(5579, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 26, 12, 'OT', 'Khi ngươi đã dứt việc đóng các thứ thuế một phần mười về huê lợi của ngươi trong năm thứ ba, là năm đóng thuế một phần mười, thì phải cấp phần thuế đó cho người Lê-vi, cho khách lạ, cho kẻ mồ côi và cho người góa bụa, để họ ăn trong các thành ngươi và được no đủ;'),
(5580, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 26, 13, 'OT', 'Ta sẽ thưa trước mặt Đức Giê-hô-va Đức Chúa Trời ngươi rằng: Tôi đã đem các vật thánh ra khỏi nhà, và cũng đã cấp cho người Lê-vi, cho khách lạ, cho kẻ mồ côi và cho người góa bụa, theo trọn mạng lịnh nào mà Ngài đã truyền cho tôi; tôi không vi phạm các mạng lịnh của Ngài, cũng không quên.'),
(5581, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 26, 14, 'OT', 'Tôi đã không ăn phần thánh ấy trong lúc buồn khổ, cũng không lấy nó khi đang ô uế, và không trao nó cho người chết; tôi đã nghe theo tiếng Đức Giê-hô-va Đức Chúa Trời tôi, và làm mọi điều mà Ngài đã truyền dạy tôi.'),
(5582, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 26, 15, 'OT', 'Xin Đức Giê-hô-va đoái xem từ nơi thánh Ngài ở trên trời, và ban phước cho dân Y-sơ-ra-ên của Ngài, cùng cho đất mà Ngài đã ban cho chúng tôi, y như Ngài đã thề cùng tổ phụ chúng tôi, một xứ chảy sữa và mật.'),
(5583, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 26, 16, 'OT', 'Hôm nay, Đức Giê-hô-va Đức Chúa Trời ngươi truyền cho ngươi làm các luật lệ và các điều răn nầy; ngươi phải hết lòng, hết lòng mà giữ và làm các điều đó.'),
(5584, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 26, 17, 'OT', 'Hôm nay, các ngươi đã tuyên bố Giê-hô-va là Đức Chúa Trời mình, để làm Đức Chúa Trời mình, và đi theo các đường lối Ngài, và giữ các luật lệ, các điều răn và các mạng lịnh Ngài, và vâng nghe tiếng Ngài.'),
(5585, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 26, 18, 'OT', 'Hôm nay, Đức Giê-hô-va đã khiến ngươi cam kết trở nên dân thuộc riêng về Ngài, y như Ngài đã phán cùng ngươi, và để ngươi giữ trọn mọi điều răn của Ngài.'),
(5586, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 26, 19, 'OT', 'và để đặt ngươi cao hơn mọi dân mà Đức Giê-hô-va đã làm ra, để được ngợi khen, danh tiếng, và tôn trọng, và để ngươi trở nên dân thánh cho Đức Giê-hô-va Đức Chúa Trời ngươi, như lời Ngài đã phán.'),
(5587, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 27, 1, 'OT', 'Môi-se và các trưởng lão truyền cho dân sự rằng: Hãy giữ trọn mọi điều răn mà ta truyền cho các ngươi ngày nay.'),
(5588, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 27, 2, 'OT', 'Khi các ngươi qua sông Giô-đanh vào đất mà Đức Giê-hô-va Đức Chúa Trời các ngươi ban cho các ngươi, thì phải dựng những tảng đá lớn và trét vôi lên các tảng ấy.'),
(5589, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 27, 3, 'OT', 'Khi ngươi đã đi qua sông Giô-đanh vào xứ mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho, là xứ đượm sữa và mật, y như Đức Giê-hô-va Đức Chúa Trời của tổ phụ ngươi đã hứa cùng ngươi, thì phải ghi trên các bia đá ấy mọi lời của luật pháp nầy.'),
(5590, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 27, 4, 'OT', 'Khi các ngươi đã qua sông Giô-đanh rồi, phải dựng những tảng đá nầy, mà hôm nay ta truyền cho các ngươi, trên núi Ê-banh, và quét vôi lên các tảng đá ấy.'),
(5591, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 27, 5, 'OT', 'Tại nơi ấy, ngươi phải xây một bàn thờ cho Đức Giê-hô-va Đức Chúa Trời ngươi, một bàn thờ bằng những hòn đá; ngươi không được đưa lưỡi sắt chạm vào chúng.'),
(5592, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 27, 6, 'OT', 'Ngươi phải dùng những hòn đá nguyên vẹn mà xây bàn thờ cho Đức Giê-hô-va Đức Chúa Trời ngươi, và dâng lên đó của lễ thiêu cho Đức Giê-hô-va Đức Chúa Trời ngươi.'),
(5593, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 27, 7, 'OT', 'Hãy dâng của lễ thù ân, và ăn tại đó; ngươi phải vui vẻ trước mặt Đức Giê-hô-va Đức Chúa Trời ngươi.'),
(5594, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 27, 8, 'OT', 'Ngươi phải viết trên các hòn đá mọi lời của luật pháp nầy, và viết thật rõ ràng.'),
(5595, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 27, 9, 'OT', 'Môi-se và các thầy tế lễ Lê-vi nói cùng cả Y-sơ-ra-ên rằng: Hỡi Y-sơ-ra-ên, hãy im lặng và nghe! Ngày nay, ngươi đã trở nên dân của Đức Giê-hô-va Đức Chúa Trời ngươi.'),
(5596, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 27, 10, 'OT', 'Vậy, ngươi phải nghe theo tiếng phán của Đức Giê-hô-va Đức Chúa Trời ngươi, và làm theo các điều răn và các luật lệ của Ngài, mà ta truyền cho ngươi ngày nay.'),
(5597, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 27, 11, 'OT', 'Ngày ấy, Môi-se truyền cho dân sự, mà rằng:'),
(5598, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 27, 12, 'OT', 'Khi các ngươi đi qua sông Giô-đanh, thì Si-mê-ôn, Lê-vi, Giu-đa, Y-sa-ca, Giô-sép và Bên-gia-min phải đứng trên núi Ga-ri-xim để chúc phước cho dân sự;'),
(5599, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 27, 13, 'OT', 'Còn Ru-bên, Gát, A-se, Sa-bu-lôn, Đan và Nép-ta-li sẽ đứng trên núi Ê-banh để tuyên bố lời rủa sả.'),
(5600, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 27, 14, 'OT', 'Người Lê-vi sẽ cất tiếng và nói cách lớn tiếng đến mọi người nam Y-sơ-ra-ên,'),
(5601, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 27, 15, 'OT', 'Đáng rủa sả thay người nào làm tượng chạm hay tượng đúc, là điều gớm ghiếc cho Đức Giê-hô-va, công việc của tay thợ, rồi đặt nó trong chỗ khuất mắt! Cả dân phải đáp và nói: A-men!'),
(5602, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 27, 16, 'OT', 'Đáng rủa sả thay người nào khinh bỉ cha mình và mẹ mình! Cả dân sự phải đáp: A-men!'),
(5603, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 27, 17, 'OT', 'Đáng rủa thay người dời mốc giới của kẻ lân cận mình! Cả dân phải đáp: A-men!'),
(5604, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 27, 18, 'OT', 'Đáng rủa thay người làm cho kẻ mù lạc đường trong lối đi! Cả dân phải đáp: A-men!'),
(5605, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 27, 19, 'OT', 'Đáng rủa sả thay người nào làm lệch luật pháp của người ngoại, kẻ mồ côi và người góa! Cả dân sự sẽ đáp: A-men!'),
(5606, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 27, 20, 'OT', 'Đáng rủa sả thay kẻ nào nằm cùng vợ của cha mình, vì người đó đã làm nhục chỗ nằm của cha mình. Cả dân phải đáp: A-men!'),
(5607, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 27, 21, 'OT', 'Đáng rủa thay kẻ nằm cùng bất kỳ loài vật nào! Và toàn thể dân chúng phải nói: A-men!'),
(5608, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 27, 22, 'OT', 'Đáng rủa thay kẻ nằm cùng chị em ruột, con gái của cha mình hay con gái của mẹ mình! Cả dân phải đáp: A-men!'),
(5609, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 27, 23, 'OT', 'Đáng rủa thay kẻ nằm cùng bà gia mình! Cả dân phải nói: A-men!'),
(5610, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 27, 24, 'OT', 'Đáng rủa thay kẻ đánh người lân cận mình cách lén lút! Cả dân phải đáp: A-men!'),
(5611, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 27, 25, 'OT', 'Đáng rủa sả thay kẻ nhận của hối lộ để giết người vô tội! Cả dân sự sẽ đáp: A-men!'),
(5612, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 27, 26, 'OT', 'Phải rủa sả kẻ nào không lập vững các lời của luật pháp nầy để thực hiện chúng. Cả dân sự sẽ đáp: A-men!'),
(5613, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 1, 'OT', 'Nếu ngươi chăm chỉ nghe theo tiếng phán của Đức Giê-hô-va Đức Chúa Trời ngươi, để cẩn thận làm theo mọi điều răn của Ngài mà ta truyền cho ngươi ngày nay, thì Đức Giê-hô-va Đức Chúa Trời ngươi sẽ đặt ngươi cao hơn mọi dân trên đất.'),
(5614, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 2, 'OT', 'Các phước lành nầy sẽ đến cùng ngươi và theo kịp ngươi, nếu ngươi nghe theo tiếng phán của Đức Giê-hô-va Đức Chúa Trời ngươi.'),
(5615, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 3, 'OT', 'Ngươi sẽ được phước trong thành, và được phước trên đồng ruộng.'),
(5616, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 4, 'OT', 'Được phước về bông trái trong lòng ngươi, bông trái của đất ruộng ngươi, và bông trái của súc vật ngươi, về bò cái đẻ và chiên cái sinh sản.'),
(5617, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 5, 'OT', 'Đức Giê-hô-va sẽ ban phước cho cái giỏ và cái thùng nhồi bột của ngươi.'),
(5618, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 6, 'OT', 'Ngươi sẽ được phước khi đi vào và được phước khi đi ra.'),
(5619, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 7, 'OT', 'Đức Giê-hô-va sẽ khiến các kẻ thù nghịch ngươi trỗi dậy chống ngươi bị đánh bại trước mặt ngươi; chúng sẽ theo một con đường mà đến đánh ngươi, nhưng sẽ theo bảy con đường mà chạy trốn trước mặt ngươi.'),
(5620, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 8, 'OT', 'Đức Giê-hô-va sẽ truyền phước lành cho ngươi trong các kho thóc và trong mọi công việc tay ngươi làm, và sẽ ban phước cho ngươi trong đất mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi.'),
(5621, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 9, 'OT', 'Nếu ngươi gìn giữ các điều răn của Đức Giê-hô-va Đức Chúa Trời ngươi và đi theo các đường lối Ngài, thì Đức Giê-hô-va sẽ lập ngươi cho Ngài làm một dân thánh, y như Ngài đã thề cùng ngươi;'),
(5622, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 10, 'OT', 'Muôn dân trên đất sẽ thấy rằng danh Đức Giê-hô-va được gọi trên ngươi, và chúng sẽ sợ ngươi.'),
(5623, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 11, 'OT', 'Đức Giê-hô-va sẽ khiến ngươi được dư dật về điều thiện, trong hoa quả của bụng ngươi, trong sản vật của súc vật ngươi, và trong bông trái đất ruộng ngươi, trên đất mà Đức Giê-hô-va đã thề cùng các tổ phụ ngươi để ban cho ngươi.'),
(5624, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 12, 'OT', 'Đức Giê-hô-va sẽ mở kho báu tốt lành của Ngài là trời để cho mưa đất ngươi vào đúng mùa, và ban phước cho mọi công việc tay ngươi làm; ngươi sẽ cho nhiều dân tộc vay, còn ngươi thì không phải vay ai.'),
(5625, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 13, 'OT', 'Nếu ngươi nghe theo các điều răn của Đức Giê-hô-va Đức Chúa Trời ngươi mà ngày nay ta truyền cho ngươi để giữ và làm theo, thì Đức Giê-hô-va sẽ đặt ngươi làm đầu, chứ không làm đuôi; ngươi sẽ chỉ ở trên, chứ không ở dưới.'),
(5626, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 14, 'OT', 'và ngươi sẽ không đi lạc khỏi mọi điều phán mà ta truyền cho các ngươi ngày nay, không chếch sang bên phải hay bên trái, để đi theo và phục sự các thần khác'),
(5627, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 15, 'OT', 'Nhưng nếu ngươi không nghe theo tiếng của Đức Giê-hô-va Đức Chúa Trời ngươi, để cẩn thận làm theo mọi điều răn và luật lệ của Ngài mà ta truyền cho ngươi ngày nay, thì các sự rủa sả nầy sẽ giáng trên ngươi và đuổi kịp ngươi.'),
(5628, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 16, 'OT', 'Ngươi sẽ bị rủa sả trong thành và bị rủa sả ngoài đồng ruộng,'),
(5629, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 17, 'OT', 'Giỏ và thùng nhồi bột của ngươi bị rủa sả.'),
(5630, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 18, 'OT', 'Đức Giê-hô-va sẽ rủa sả hoa quả trong lòng ngươi, hoa quả của đất ruộng ngươi, bò cái đẻ ra và chiên cái sinh sản.'),
(5631, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 19, 'OT', 'Ngươi bị rủa sả khi vào, và ngươi bị rủa sả khi ra.'),
(5632, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 20, 'OT', 'Đức Giê-hô-va sẽ sai sự rủa sả, sự kinh khủng, và sự quở trách trên ngươi trong mọi việc ngươi làm, cho đến khi ngươi bị tiêu diệt và bị diệt vong nhanh chóng, vì sự ác của các việc ngươi làm mà ngươi đã lìa bỏ Ta.'),
(5633, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 21, 'OT', 'Đức Giê-hô-va sẽ khiến bệnh dịch dính chặt vào ngươi, cho đến khi Ngài tiêu diệt ngươi khỏi đất mà ngươi sẽ vào chiếm lấy.'),
(5634, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 22, 'OT', 'Đức Giê-hô-va sẽ đánh ngươi bằng bệnh lao, bệnh sốt rét, bệnh phù, bệnh nóng cháy, gươm đao, sâu lúa và sự vàng úa; các điều đó sẽ đuổi theo ngươi cho đến khi ngươi bị tiêu diệt.'),
(5635, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 23, 'OT', 'Các tầng trời trên đầu ngươi sẽ như đồng, và đất dưới chân ngươi sẽ như sắt.'),
(5636, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 24, 'OT', 'Đức Giê-hô-va sẽ khiến mưa đất ngươi trở thành bụi và tro, từ trên trời sa xuống trên ngươi, cho đến khi ngươi bị tiêu diệt.'),
(5637, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 25, 'OT', 'Đức Giê-hô-va sẽ khiến ngươi bị đánh bại trước mặt kẻ thù ngươi; ngươi sẽ đi một đường mà ra đánh chúng nó, nhưng sẽ chạy trốn trước mặt chúng nó theo bảy đường; và ngươi sẽ bị khinh bỉ giữa mọi nước trên đất.'),
(5638, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 26, 'OT', 'Thây ngươi sẽ trở thành thức ăn cho mọi loài chim trên trời và mọi loài thú vật dưới đất, và không ai hù đuổi chúng đi.'),
(5639, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 27, 'OT', 'Đức Giê-hô-va sẽ đánh ngươi bằng ghẻ loét của Ai Cập, bằng trĩ, bằng ghẻ ngứa và bằng lác, mà ngươi không thể chữa lành được.'),
(5640, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 28, 'OT', 'Đức Giê-hô-va sẽ đánh ngươi bằng sự sảng sốt, bằng sự đui mù, và bằng sự bối rối trong lòng.'),
(5641, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 29, 'OT', 'Giữa trưa ngươi sẽ mò mẫm như người mù trong chỗ tối tăm, và ngươi sẽ không thành công trên các nẻo đường mình; ngươi chỉ hằng bị áp bức và cướp đoạt trọn ngày, mà chẳng có ai giải cứu.'),
(5642, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 30, 'OT', 'Ngươi sẽ cưới vợ, nhưng một người đàn ông khác sẽ ăn ở với nàng; ngươi sẽ xây một ngôi nhà, nhưng không được ở trong đó; ngươi sẽ trồng một vườn nho, nhưng không được hưởng sản phẩm của nó.'),
(5643, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 31, 'OT', 'Bò của ngươi sẽ bị giết ngay trước mắt ngươi, nhưng ngươi sẽ không ăn được từ nó; lừa của ngươi sẽ bị cướp đi ngay trước mặt ngươi, và nó sẽ không trở lại với ngươi; chiên của ngươi sẽ bị trao cho kẻ thù ngươi, và ngươi sẽ không có ai cứu giúp ngươi.'),
(5644, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 32, 'OT', 'Các con trai và con gái ngươi sẽ bị trao cho một dân khác; mắt ngươi sẽ thấy và hao mòn vì trông mong chúng suốt cả ngày; nhưng tay ngươi không có quyền năng cứu vớt.'),
(5645, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 33, 'OT', 'Các sản vật của đất ngươi và mọi công khó ngươi làm sẽ bị một dân mà ngươi chưa biết ăn hết; và ngươi sẽ chỉ bị áp bức và nghiền nát trọn mọi ngày.'),
(5646, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 34, 'OT', 'Ngươi sẽ trở nên điên loạn vì cảnh tượng mắt mình thấy.'),
(5647, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 35, 'OT', 'Đức Giê-hô-va sẽ đánh ngươi bằng một ung thư độc ác trên đầu gối và bắp chân, không thể chữa lành được, từ lòng bàn chân ngươi cho đến đỉnh đầu ngươi.'),
(5648, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 36, 'OT', 'Đức Giê-hô-va sẽ dẫn ngươi và vị vua mà ngươi đặt lên mình đến một dân tộc mà ngươi và tổ tiên ngươi chưa từng biết; và ngươi sẽ hầu việc các thần khác tại đó, bằng gỗ và bằng đá.'),
(5649, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 37, 'OT', 'Ngươi sẽ trở thành điều kinh hãi, tục ngữ và tiếu đàm giữa mọi dân tộc mà Đức Giê-hô-va dẫn ngươi đến đó.'),
(5650, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 38, 'OT', 'Ngươi sẽ gieo rất nhiều hạt nơi ruộng mình, nhưng thu hoạch ít, vì cào cào sẽ nuốt sạch.'),
(5651, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 39, 'OT', 'Ngươi sẽ trồng nho và làm công khó nhọc, nhưng sẽ không uống rượu hay thu hoạch được gì, vì sâu sẽ ăn hết.'),
(5652, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 40, 'OT', 'Các cây ô-li-ve sẽ có khắp mọi nơi trong bờ cõi ngươi, nhưng ngươi sẽ không được xức dầu, vì ô-li-ve của ngươi sẽ rụng trái.'),
(5653, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 41, 'OT', 'Ngươi sẽ sinh con trai và con gái, nhưng chúng không thuộc về ngươi, vì chúng sẽ bị bắt đi làm phu tù.'),
(5654, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 42, 'OT', 'Tất cả các cây và trái đất của ngươi sẽ bị châu chấu nuốt sạch.'),
(5655, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 43, 'OT', 'Người ngoại kiêng ở giữa anh em sẽ ngày càng lên cao hơn anh em, còn anh em thì ngày càng đi xuống thấp hơn.'),
(5656, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 44, 'OT', 'Người ấy sẽ cho ngươi vay, còn ngươi thì không cho người ấy vay; người ấy sẽ làm đầu, còn ngươi sẽ làm đuôi.'),
(5657, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 45, 'OT', 'Tất cả những sự rủa sả này sẽ giáng trên ngươi, đuổi theo ngươi và bắt kịp ngươi, cho đến khi ngươi bị tiêu diệt, vì ngươi đã không nghe theo tiếng của Đức Giê-hô-va Đức Chúa Trời ngươi, và không tuân giữ các điều răn và luật lệ mà Ngài đã truyền cho ngươi.'),
(5658, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 46, 'OT', 'Các điều ấy sẽ ở nơi ngươi và nơi dòng dõi ngươi như một dấu và một sự kỳ lạ đến muôn đời.'),
(5659, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 47, 'OT', 'Vì ngươi không vui lòng và hết lòng phục sự Giê-hô-va Đức Chúa Trời ngươi, dù khi được dư dật mọi thứ.'),
(5660, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 48, 'OT', 'vì vậy ngươi sẽ hầu việc kẻ thù nghịch mà Đức Giê-hô-va sai đến đánh ngươi, trong lúc đói khát, trần truồng và thiếu thốn mọi điều; Ngài sẽ đặt ách sắt trên cổ ngươi, cho đến khi tiêu diệt ngươi.'),
(5661, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 49, 'OT', 'Đức Giê-hô-va sẽ giương lên nghịch cùng ngươi một dân từ nơi xa, tận cùng đất, như chim ưng bay đến; một dân mà ngươi sẽ không hiểu tiếng nói của họ.'),
(5662, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 50, 'OT', 'một dân tộc mặt mày dữ tợn, không nể vì người già, cũng chẳng thương xót kẻ trẻ;'),
(5663, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 51, 'OT', 'Nó sẽ ăn sản vật của bò và sản vật của đất ruộng ngươi, cho đến chừng nào ngươi bị tiêu diệt; nó sẽ không để lại cho ngươi ngũ cốc, rượu mới, dầu ô-liu, bê của bò ngươi, hay chiên của ngươi, cho đến khi nó tiêu diệt ngươi.'),
(5664, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 52, 'OT', 'Dân đó sẽ vây hãm ngươi trong mọi thành của ngươi, cho đến khi những vách thành cao lớn và kiên cố mà ngươi tin cậy bị sụp đổ, ở khắp đất ngươi, mà Đức Giê-hô-va Đức Chúa Trời ngươi ban cho ngươi.'),
(5665, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 53, 'OT', 'Ngươi sẽ ăn hoa quả của bụng mình, tức là thịt các con trai và các con gái mà Đức Giê-hô-va Đức Chúa Trời ngươi đã ban cho ngươi, trong lúc bị vây khốn và bị ép bức, khi kẻ thù nghịch ngươi siết chặt ngươi.'),
(5666, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 54, 'OT', 'Người đàn ông nhu nhược và kiêu kỳ nhất trong các ngươi sẽ nhìn anh em mình, vợ lòng mình và những con còn sót lại với ánh mắt độc ác.'),
(5667, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 55, 'OT', 'không chịu cho một người nào trong bọn họ chút thịt của các con mình mà người sẽ ăn, vì người không còn sót lại điều gì, trong sự vây hãm và sự khốn khổ mà kẻ thù ngươi sẽ gây cho ngươi trong mọi thành phố ngươi.'),
(5668, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 56, 'OT', 'Người nữ nhã nhặn và mỏng manh nhất trong các ngươi, người vốn không từng đặt bàn chân mình xuống đất vì sự nhã nhặn và mỏng manh, sẽ trợn mắt tức tối nhìn chồng mình, con trai mình và con gái mình.'),
(5669, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 57, 'OT', 'Cô ta sẽ nhìn con trẻ mới sinh từ giữa hai chân mình và những con cái mình đã sinh ra, vì trong cảnh thiếu thốn mọi thứ, giữa sự bao vây và khốn khổ mà kẻ thù ngươi gây ra cho ngươi nơi các cổng thành ngươi, nàng sẽ ăn những con cái mình.'),
(5670, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 58, 'OT', 'Nếu ngươi không cẩn thận làm theo mọi lời của luật pháp nầy, đã được chép trong sách nầy, để kính sợ danh vinh hiển và đáng sợ nầy là Đức Giê-hô-va Đức Chúa Trời ngươi,'),
(5671, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 59, 'OT', 'Thì Đức Giê-hô-va sẽ làm cho những tai họa của ngươi và tai họa của dòng dõi ngươi trở nên lạ lùng, những tai họa lớn lao và vững chắc, cùng những bệnh tật ác liệt và bền lâu.'),
(5672, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 60, 'OT', 'Ngài sẽ khiến các bệnh tật của Ai Cập mà ngươi đã sợ hãi giáng xuống trên ngươi, và chúng sẽ bám chặt vào ngươi.'),
(5673, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 61, 'OT', 'Cũng mọi thứ bệnh tật và mọi thứ tai họa không được chép trong sách luật pháp nầy, Đức Giê-hô-va sẽ khiến giáng trên ngươi, cho đến khi ngươi bị tiêu diệt.'),
(5674, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 62, 'OT', 'Các ngươi vốn đông như sao trên trời, nhưng vì không nghe theo tiếng của Đức Giê-hô-va Đức Chúa Trời ngươi, nên các ngươi sẽ chỉ còn lại ít người.'),
(5675, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 63, 'OT', 'Hễ Đức Giê-hô-va lấy làm vui mà làm lành và gia tăng các ngươi thể nào, thì Đức Giê-hô-va cũng sẽ lấy làm vui mà làm cho các ngươi hư mất và tiêu diệt các ngươi thể ấy. Các ngươi sẽ bị trục xuất khỏi đất mà ngươi vào đó để chiếm lấy.'),
(5676, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 64, 'OT', 'Đức Giê-hô-va sẽ tản lạc ngươi giữa muôn dân, từ đầu này của đất cho đến đầu kia của đất; và tại đó, ngươi sẽ hầu việc các thần khác mà ngươi và tổ phụ ngươi chưa từng biết, bằng gỗ và bằng đá.'),
(5677, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 65, 'OT', 'Trong các dân ấy, ngươi sẽ không được yên ổn, và bàn chân ngươi sẽ không có nơi nào nghỉ ngơi; Đức Giê-hô-va sẽ ban cho ngươi tại đó một tấm lòng bồn chồn, mắt mờ mịt, và linh hồn hao mòn.'),
(5678, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 66, 'OT', 'Sự sống ngươi sẽ treo lơ lửng trước mặt ngươi; ngươi sẽ sợ hãi ban ngày và ban đêm, và không dám tin cậy nơi sự sống của mình.'),
(5679, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 67, 'OT', 'Sáng mai ngươi sẽ nói: "Ước gì được chiều tối!" Chiều tối ngươi sẽ nói: "Ước gì được sáng mai!" Vì sự kinh khủng trong lòng ngươi phải sợ hãi, và cảnh tượng mắt ngươi sẽ thấy.'),
(5680, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 28, 68, 'OT', 'Đức Giê-hô-va sẽ khiến ngươi trở lại Ai-cập bằng tàu bè, theo con đường mà Ta đã nói với ngươi: Ngươi sẽ không thấy nó nữa; và ngươi sẽ bị bán tại đó cho kẻ thù nghịch làm tôi mọi và tì nữ, nhưng không có ai mua.'),
(5681, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 29, 1, 'OT', 'Nầy là các lời của giao ước mà Đức Giê-hô-va dặn Môi-se lập cùng con cái Y-sơ-ra-ên tại đất Mô-áp, ngoài giao ước mà Ngài đã lập cùng họ tại Hô-rếp.'),
(5682, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 29, 2, 'OT', 'Môi-se gọi cả Y-sơ-ra-ên mà nói rằng: Các ngươi đã thấy mọi điều Đức Giê-hô-va làm trước mắt các ngươi trong xứ Ê-díp-tô cho Pha-ra-ôn, cho mọi tôi tớ người và cho cả đất nước người.'),
(5683, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 29, 3, 'OT', 'những thử thách lớn mà mắt ngươi đã thấy, tức là các dấu kỳ và những điềm lớn ấy'),
(5684, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 29, 4, 'OT', 'Nhưng cho đến ngày nay Đức Giê-hô-va chưa ban cho các ngươi một tấm lòng để biết, mắt để thấy và tai để nghe.'),
(5685, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 29, 5, 'OT', 'Ta đã dẫn dắt các ngươi bốn mươi năm trong đồng vắng, áo các ngươi không cũ mòn trên mình các ngươi, và giày các ngươi cũng không mòn mòn dưới chân các ngươi.'),
(5686, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 29, 6, 'OT', 'Các ngươi không ăn bánh, cũng không uống rượu hay nước có men, để các ngươi biết rằng Ta, Đức Giê-hô-va, là Đức Chúa Trời của các ngươi.'),
(5687, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 29, 7, 'OT', 'Các ngươi đã đến nơi đây, thì Si-hôn, vua Hết-bôn, và Oùc, vua Ba-san, đi ra nghênh chiến với chúng ta; và chúng ta đã đánh bại họ.'),
(5688, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 29, 8, 'OT', 'Chúng ta chiếm lấy xứ của họ và ban cho làm sản nghiệp cho Ru-bên, Gát và phân nửa chi phái Ma-na-se.'),
(5689, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 29, 9, 'OT', 'Vậy, các ngươi phải giữ và làm theo các lời của giao ước nầy, để các ngươi được thông sáng trong mọi việc mình làm.'),
(5690, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 29, 10, 'OT', 'Hết thảy các ngươi, nào các trưởng tộc, các chi phái, nào các trưởng lão, các quan cai, nào mọi người nam của Y-sơ-ra-ên, hôm nay đều đứng trước mặt Đức Giê-hô-va Đức Chúa Trời các ngươi.'),
(5691, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 29, 11, 'OT', 'những con trẻ, vợ các ngươi, và người ngoại kiều ở giữa trại quân ngươi, từ người chặt củi cho đến người xách nước, đều đứng trước mặt Đức Giê-hô-va Đức Chúa Trời các ngươi ngày nay,'),
(5692, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 29, 12, 'OT', 'để vào giao ước của Đức Giê-hô-va Đức Chúa Trời ngươi và vào lời thề mà Đức Giê-hô-va Đức Chúa Trời ngươi lập cùng ngươi ngày nay,'),
(5693, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 29, 13, 'OT', 'để ngày nay lập ngươi làm dân thuộc về Ngài, và Ngài sẽ làm Đức Chúa Trời ngươi, như Ngài đã phán với ngươi và như Ngài đã thề cùng các tổ phụ ngươi, là Aùp-ra-ham, Y-sác và Gia-cốp.'),
(5694, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 29, 14, 'OT', 'Không phải chỉ với các ngươi mà Ta lập giao ước nầy và lời nguyền nầy,'),
(5695, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 29, 15, 'OT', 'Vì những người đang đứng đây hôm nay cùng chúng ta trước mặt Đức Giê-hô-va Đức Chúa Trời chúng ta, và cũng vì những người không có mặt đây cùng chúng ta hôm nay.'),
(5696, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 29, 16, 'OT', 'Vì các ngươi đã biết những điều chúng ta ở trong đất Ai Cập, và những điều chúng ta đi qua giữa các dân tộc mà các ngươi đã đi ngang qua.'),
(5697, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 29, 17, 'OT', 'Các ngươi đã thấy những vật đáng gớm ghiếc của chúng và những hình tượng bẩn thỉu của chúng, bằng gỗ, bằng đá, bằng bạc và bằng vàng, mà chúng có cùng nhau.'),
(5698, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 29, 18, 'OT', 'Trong các ngươi, chớ có người nam, người nữ, gia đình hay chi phái nào lòng ngày nay trở về phía khác khỏi Đức Giê-hô-va Đức Chúa Trời chúng ta, để đi phục sự các thần của các dân tộc ấy; trong các ngươi chớ có rễ sinh ra cây đầu lâu và ngải cứu.'),
(5699, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 29, 19, 'OT', 'Người nghe các lời của sự rủa nầy, thì tự chúc phước cho mình trong lòng mà rằng: Ta sẽ được bình an, dù khi ta đi theo sự cứng lòng ta; để kẻ được tưới và kẻ khát cùng bị tiêu hủy.'),
(5700, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 29, 20, 'OT', 'Đức Giê-hô-va sẽ không chịu tha thứ cho người ấy; vì lúc ấy cơn thịnh nộ và sự ghen tương của Đức Giê-hô-va sẽ bốc cháy phừng lên cùng người đó, và mọi điều rủa sả đã chép trong sách này sẽ đè nặng trên người ấy; Đức Giê-hô-va sẽ xóa tên người ấy khỏi dưới trời.'),
(5701, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 29, 21, 'OT', 'Đức Giê-hô-va sẽ biệt người ấy ra khỏi các chi phái Y-sơ-ra-ên để chịu tai họa, theo mọi lời rủa sủa trong giao ước đã chép trong sách Luật Pháp nầy.'),
(5702, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 29, 22, 'OT', 'Đời sau, con cái các ngươi sẽ nói, những người sẽ chỗi dậy từ sau các ngươi, và người ngoại đến từ đất xa, khi thấy các tai họa và chứng bệnh của đất ấy, mà Đức Giê-hô-va đã giáng trên nó,'),
(5703, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 29, 23, 'OT', 'Lưu huỳnh và muối thiêu hủy toàn cõi đất; đất ấy chẳng được gieo trồng, chẳng sinh ra gì, chẳng mọc lên một cây cỏ nào, như sự lật đổ của Sô-đôm, Gô-mô-rơ, Aùt-ma và Sê-bô-im, mà Đức Giê-hô-va đã lật đổ trong cơn thạnh nộ và cơn giận Ngài.'),
(5704, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 29, 24, 'OT', 'Mọi dân tộc sẽ hỏi: Tại sao Đức Giê-hô-va làm điều này cho đất nầy? Cơn thạnh nộ lớn lao nầy là vì cớ gì?'),
(5705, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 29, 25, 'OT', 'Người ta sẽ nói: Vì chúng đã lìa bỏ giao ước của Giê-hô-va, Đức Chúa Trời của tổ phụ chúng, mà Ngài đã lập cùng họ khi dẫn họ ra khỏi đất Ê-dốp-tô.'),
(5706, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 29, 26, 'OT', 'Họ đi theo và hầu việc các thần khác, thờ lạy chúng, tức các thần mà họ chưa hề biết, và Đức Giê-hô-va cũng chẳng phân phát cho họ.'),
(5707, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 29, 27, 'OT', 'Cơn thịnh nộ của Đức Giê-hô-va nổi lên nghịch cùng đất nầy, đặng giáng trên nó mọi sự rủa sả đã chép trong sách nầy.'),
(5708, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 29, 28, 'OT', 'Vì cơn thịnh nộ, cơn giận dữ và cơn phẫn nộ lớn, Đức Giê-hô-va đã giựt họ khỏi đất họ, và ném họ vào một xứ khác, như ngày nay vẫn thấy.'),
(5709, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 29, 29, 'OT', 'Những điều khuất tất thuộc về Giê-hô-va Đức Chúa Trời chúng ta, còn những điều tỏ ra thì thuộc về chúng ta và con cháu chúng ta đời đời, để chúng ta thực hiện mọi lời của luật pháp nầy.'),
(5710, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 30, 1, 'OT', 'Khi các điều nầy đã xảy đến cho ngươi, tức là phước lành và sự rủa sả mà ta đã đặt trước mặt ngươi, nếu ngươi đem lòng suy gẫm trong các nước mà Đức Giê-hô-va Đức Chúa Trời ngươi đã đuổi ngươi đến,'),
(5711, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 30, 2, 'OT', 'và ngươi sẽ trở lại cùng Đức Giê-hô-va Đức Chúa Trời ngươi, và ngươi sẽ nghe theo tiếng Ngài, theo mọi điều mà tôi đang truyền cho ngươi ngày hôm nay, ngươi và các con của ngươi hết lòng hết linh hồn ngươi.'),
(5712, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 30, 3, 'OT', 'Đức Giê-hô-va Đức Chúa Trời ngươi sẽ đem những phu tù ngươi trở về, thương xót ngươi, nhóm hiệp ngươi từ giữa mọi dân, là nơi Đức Giê-hô-va Đức Chúa Trời ngươi đã tản lạc ngươi đến đó.'),
(5713, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 30, 4, 'OT', 'Dẫu những kẻ bị đuổi của ngươi ở tận cùng trời, thì từ đó Đức Giê-hô-va Đức Chúa Trời ngươi sẽ nhóm ngươi lại và đem ngươi về.'),
(5714, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 30, 5, 'OT', 'Giê-hô-va Đức Chúa Trời ngươi sẽ đem ngươi vào đất mà tổ phụ ngươi đã chiếm hữu, và ngươi sẽ chiếm hữu nó; Ngài sẽ làm cho ngươi hưng thịnh và sinh sản thêm đông hơn tổ phụ ngươi.'),
(5715, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 30, 6, 'OT', 'Giê-hô-va Đức Chúa Trời ngươi sẽ cắt bỏ lớp da lòng ngươi và lòng dòng dõi ngươi, để ngươi yêu Giê-hô-va Đức Chúa Trời ngươi hết lòng, hết linh hồn ngươi, hầu cho ngươi được sống.'),
(5716, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 30, 7, 'OT', 'Giê-hô-va Đức Chúa Trời ngươi sẽ đặt tất cả các lời rủa sả nầy trên kẻ thù nghịch ngươi và trên những kẻ ghét ngươi, là những kẻ đã bắt bớ ngươi.'),
(5717, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 30, 8, 'OT', 'Còn ngươi sẽ trở lại, nghe theo tiếng Đức Giê-hô-va, và làm theo mọi điều răn của Ngài mà ta truyền cho ngươi ngày nay.'),
(5718, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 30, 9, 'OT', 'Đức Giê-hô-va Đức Chúa Trời ngươi sẽ làm cho ngươi thịnh vượng trong mọi công việc tay ngươi làm, trong trái bụng ngươi, trong súc vật ngươi và trong sản vật đất ngươi, để làm điều thiện; vì Đức Giê-hô-va sẽ lại vui mừng về ngươi để làm điều thiện, như Ngài đã vui mừng về tổ phụ ngươi.'),
(5719, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 30, 10, 'OT', 'vì ngươi sẽ nghe theo tiếng Đức Giê-hô-va Đức Chúa Trời ngươi, để giữ các điều răn và các luật lệ của Ngài đã chép trong sách Luật Pháp nầy, khi ngươi trở lại cùng Đức Giê-hô-va Đức Chúa Trời ngươi hết cả lòng ngươi và hết cả linh hồn ngươi.'),
(5720, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 30, 11, 'OT', 'Vì điều răn nầy mà ta truyền cho ngươi ngày nay, không phải là điều xa lạ đối với ngươi, cũng chẳng phải là điều xa cách.'),
(5721, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 30, 12, 'OT', 'Nó không ở trên trời, để phải nói rằng: Ai sẽ lên trời lấy xuống cho chúng ta và nói cho chúng ta nghe, để chúng ta làm theo?'),
(5722, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 30, 13, 'OT', 'Cũng không phải ở bên kia biển, để nói rằng: Ai sẽ qua biển cho chúng ta, lấy điều đó về cho chúng ta, và nói cho chúng ta nghe, để chúng ta thực hiện?'),
(5723, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 30, 14, 'OT', 'Vì lời đó rất gần ngươi, ở trong miệng và trong lòng ngươi, để ngươi thực hiện nó.'),
(5724, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 30, 15, 'OT', 'Hãy xem, ngày nay Ta đặt trước mặt ngươi sự sống và điều thiện, cùng sự chết và điều ác.'),
(5725, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 30, 16, 'OT', 'Mà ngày nay ta truyền cho ngươi là phải yêu Giê-hô-va Đức Chúa Trời ngươi, đi trong các đường lối Ngài, và giữ các điều răn, luật lệ, mạng lịnh Ngài, hầu cho ngươi sống, sinh sản nhiều ra, và Giê-hô-va Đức Chúa Trời ngươi sẽ ban phước cho ngươi trong đất mà ngươi sẽ vào để chiếm hữu.'),
(5726, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 30, 17, 'OT', 'Nhưng nếu lòng ngươi quay đi và không nghe theo, rồi ngươi lìa bỏ và thờ lạy các thần khác mà hầu việc chúng,'),
(5727, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 30, 18, 'OT', 'Hôm nay ta đã báo cho các ngươi biết rằng các ngươi chắc sẽ bị tiêu diệt, không được sống lâu trên đất mà ngươi sắp qua sông Giô-đanh để vào chiếm lấy.'),
(5728, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 30, 19, 'OT', 'Hôm nay ta lấy trời và đất làm chứng cho các ngươi; ta đã đặt trước mặt ngươi sự sống và sự chết, sự phước lành và sự rủa sả. Vậy ngươi phải chọn sự sống, để ngươi và dòng dõi ngươi được sống.'),
(5729, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 30, 20, 'OT', 'yêu mến Đức Giê-hô-va Đức Chúa Trời ngươi, nghe tiếng Ngài, và gắn bó với Ngài; vì chính Ngài là sự sống ngươi và là lâu dài ngày ngươi, để ngươi ở trên đất mà Đức Giê-hô-va đã thề ban cho các tổ phụ ngươi, là Aùp-ra-ham, Y-sác, và Gia-cốp.'),
(5730, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 31, 1, 'OT', 'Môi-se đi và nói những lời nầy cho cả Y-sơ-ra-ên.'),
(5731, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 31, 2, 'OT', 'Người nói với họ: Ngày nay tôi được một trăm hai mươi tuổi, không thể ra vào được nữa; và Đức Giê-hô-va đã phán cùng tôi: Ngươi sẽ không qua sông Giô-đanh này đâu.'),
(5732, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 31, 3, 'OT', 'Chính Đức Giê-hô-va Đức Chúa Trời ngươi sẽ đi trước mặt ngươi; chính Ngài sẽ tiêu diệt các dân tộc nầy khỏi trước mặt ngươi, và ngươi sẽ chiếm hữu đất chúng nó; Giô-suê sẽ đi trước mặt ngươi, y như Đức Giê-hô-va đã phán.'),
(5733, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 31, 4, 'OT', 'Đức Giê-hô-va sẽ làm cho chúng nó như Ngài đã làm cho Si-hôn và Oùc, các vua dân A-mô-rít, và xứ của chúng mà Ngài đã tiêu diệt.'),
(5734, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 31, 5, 'OT', 'Đức Giê-hô-va sẽ phó chúng nó ra trước mặt các ngươi, và các ngươi phải xử chúng nó y như mọi điều răn mà ta đã truyền cho các ngươi.'),
(5735, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 31, 6, 'OT', 'Hãy mạnh dạn và can đảm; đừng sợ hãi, cũng đừng kinh hoàng trước mặt chúng, vì Đức Giê-hô-va Đức Chúa Trời ngươi đi cùng ngươi; Ngài sẽ không lìa ngươi, cũng chẳng từ bỏ ngươi.'),
(5736, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 31, 7, 'OT', 'Vậy Môi-se gọi Giô-suê và nói cùng người trước mặt cả Y-sơ-ra-ên rằng: Hãy vững lòng bền chí, vì chính ngươi sẽ dẫn dân này vào trong đất mà Đức Giê-hô-va đã thề ban cho tổ tiên họ, và chính ngươi sẽ chia đất ấy cho họ.'),
(5737, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 31, 8, 'OT', 'Chính Đức Giê-hô-va là Đấng đi trước ngươi; Ngài sẽ ở cùng ngươi, không buông thả ngươi, cũng không từ bỏ ngươi. Đừng sợ, và đừng kinh hãi.'),
(5738, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 31, 9, 'OT', 'Môi-se chép luật pháp nầy và trao cho các thầy tế lễ là con trai Lê-vi, những người khiêng hòm giao ước của Đức Giê-hô-va, và trao cho tất cả các trưởng lão Y-sơ-ra-ên.'),
(5739, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 31, 10, 'OT', 'Và Môi-se truyền lịnh cho họ rằng: Cuối bảy năm, vào năm xả nợ, trong dịp lễ Lều Tạm,'),
(5740, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 31, 11, 'OT', 'Khi cả Y-sơ-ra-ên đến chầu trước mặt Đức Giê-hô-va Đức Chúa Trời ngươi, tại nơi mà Ngài sẽ chọn, ngươi phải đọc luật pháp nầy trước mặt cả Y-sơ-ra-ên, cho họ nghe.'),
(5741, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 31, 12, 'OT', 'Hãy nhóm lại dân sự, gồm những người nam, người nữ, con trẻ và khách lạ ở trong các thành ngươi, để họ nghe, học và kính sợ Đức Giê-hô-va Đức Chúa Trời ngươi, và cẩn thận làm theo mọi lời của luật pháp nầy.'),
(5742, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 31, 13, 'OT', 'Và con cái họ, những kẻ chưa biết, sẽ nghe và học biết kính sợ Đức Giê-hô-va Đức Chúa Trời các ngươi, trong mọi ngày các ngươi còn sống trên đất mà các ngươi sẽ đi qua sông Giô-đanh để nhận lấy.'),
(5743, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 31, 14, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: "Này, ngày ngươi qua đời đã gần; hãy gọi Giô-suê, và hai ngươi hãy ra mắt tại hội mạc, để ta truyền lịnh cho người." Môi-se và Giô-suê bèn đi, và hai người ra mắt tại hội mạc.'),
(5744, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 31, 15, 'OT', 'Đức Giê-hô-va hiện ra trong trại, trong trụ mây; và trụ mây dừng lại tại cửa trại.'),
(5745, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 31, 16, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Kìa, ngươi sẽ nằm nghỉ cùng các tổ phụ ngươi; dân sự nầy sẽ dấy lên và làm điều dâm loạn cùng các thần của dân ngoại trong xứ mà họ sẽ vào giữa họ, và họ sẽ lìa bỏ ta, phá vỡ giao ước ta mà ta đã lập cùng họ.'),
(5746, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 31, 17, 'OT', 'Trong ngày ấy, cơn giận của Ta sẽ nổi phừng lên cùng họ, Ta sẽ bỏ mặc họ và giấu mặt Ta khỏi họ; chúng sẽ bị tiêu diệt, và những điều ác và nỗi gian nan khốn khổ nhiều sẽ xảy đến cùng chúng. Bấy giờ chúng sẽ nói trong ngày ấy: "Chẳng phải vì Đức Chúa Trời không ở giữa tôi, nên những điều ác này đã xảy đến cùng tôi sao?"'),
(5747, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 31, 18, 'OT', 'Và ta sẽ giấu mặt ta trong ngày đó, vì mọi điều ác mà nó đã làm, vì nó đã quay về các thần khác.'),
(5748, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 31, 19, 'OT', 'Vậy bây giờ, hãy chép cho các ngươi bài ca nầy và dạy cho các con cái Y-sơ-ra-ên; hãy đặt nó trong miệng chúng nó, để bài ca nầy làm chứng cho ta nghịch cùng các con cái Y-sơ-ra-ên.'),
(5749, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 31, 20, 'OT', 'Vì Ta sẽ dẫn dân ấy vào đất mà Ta đã chỉ cho tổ tiên chúng nó, đất chảy sữa và mật; chúng nó sẽ ăn, no đủ và béo tốt, rồi quay sang các thần khác, phục vụ chúng, khinh dể Ta và vi phạm giao ước của Ta.'),
(5750, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 31, 21, 'OT', 'Khi các tai họa và khốn khổ nhiều xảy đến cùng chúng, thì bài ca nầy sẽ cất lên làm chứng nghịch lại chúng, vì nó sẽ không bị quên nơi miệng dòng dõi chúng; bởi ta biết lòng ham muốn của chúng, là điều chúng đang làm ngày nay, trước khi ta dẫn chúng vào đất ta đã chỉ thiên mà hứa.'),
(5751, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 31, 22, 'OT', 'Trong ngày ấy, Môi-se chép bài thơ nầy và dạy cho con cái Y-sơ-ra-ên.'),
(5752, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 31, 23, 'OT', 'Đức Giê-hô-va truyền cho Giô-suê, con trai của Nun, rằng: Hãy mạnh mẽ và can đảm, vì chính ngươi sẽ dẫn dân Y-sơ-ra-ên vào đất mà Ta đã chỉ cho họ, và chính Ta sẽ ở cùng ngươi.'),
(5753, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 31, 24, 'OT', 'Khi Môi-se chép xong các lời của luật pháp nầy vào sách, cho đến trọn.'),
(5754, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 31, 25, 'OT', 'Môi-se ra lệnh cho những người Lê-vi khiêng hòm giao ước của Đức Giê-hô-va, rằng:'),
(5755, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 31, 26, 'OT', 'Hãy lấy cuốn sách luật pháp nầy và đặt nó bên cạnh hòm giao ước của Đức Giê-hô-va Đức Chúa Trời các ngươi, để nó ở đó làm chứng cho ngươi.'),
(5756, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 31, 27, 'OT', 'Vì ta biết sự bội nghịch và cái cổ cứng của các ngươi; nầy, ngày nay, khi ta còn sống với các ngươi, các ngươi đã phản nghịch cùng Đức Giê-hô-va; huống chi sau khi ta qua đời!'),
(5757, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 31, 28, 'OT', 'Hãy nhóm lại cùng ta tất cả các trưởng lão của các chi phái và các quan xét các ngươi, để ta nói những lời nầy vào tai họ, và ta sẽ khiến trời và đất làm chứng nghịch cùng họ.'),
(5758, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 31, 29, 'OT', 'Vì ta biết rằng sau khi ta qua đời, các ngươi hẳn sẽ bại hoại và xây bỏ con đường mà ta đã truyền cho các ngươi; và trong những ngày sau rốt, các ngươi sẽ gặp tai họa, vì các ngươi làm điều ác trước mặt Đức Giê-hô-va, khiến Ngài nổi giận bởi những việc tay các ngươi làm.'),
(5759, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 31, 30, 'OT', 'Môi-se nói vào tai cả hội chúng Y-sơ-ra-ên những lời của bài ca nầy cho đến trọn.'),
(5760, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 1, 'OT', 'Hỡi các từng trời, hãy lắng nghe, tôi sẽ nói; Và đất ơi, hãy nghe những lời từ miệng tôi.'),
(5761, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 2, 'OT', 'Lời ta tuôn xuống như mưa móc, đạo ta nhỏ xuống như sương mai, như mưa phùn trên chồi non, như giọt nước trên cỏ xanh.'),
(5762, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 3, 'OT', 'Tôi sẽ xưng danh Đức Giê-hô-va; hãy ban sự vinh hiển cho Đức Chúa Trời chúng ta!'),
(5763, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 4, 'OT', 'Hòn Đá, công việc Ngài trọn vẹn, vì mọi nẻo đường Ngài là sự công bình; Đức Chúa Trời thành tín và chẳng có sự gian ác, Ngài công bình và ngay thẳng.'),
(5764, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 5, 'OT', 'Chúng nó hư hỏng, chẳng phải con cái Ngài; ấy là dòng dõi gian tà và điên đảo.'),
(5765, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 6, 'OT', 'Hỡi dân khờ dại không trí, các ngươi báo đáp Đức Giê-hô-va như vậy sao? Chính Ngài há chẳng phải là Cha ngươi, Đấng đã tạo ngươi sao? Chính Ngài đã làm nên ngươi và lập nền cho ngươi.'),
(5766, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 7, 'OT', 'Hãy nhớ những ngày đời xưa, suy xét các năm của từng thế hệ; hãy hỏi cha ngươi, người sẽ chỉ bảo ngươi, các bậc lão thành của ngươi, họ sẽ nói cho ngươi.'),
(5767, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 8, 'OT', 'Khi Đấng Chí Cao chia sản nghiệp cho các dân, khi phân biệt con cái A-đam, thì Ngài thiết lập ranh giới các dân theo số con cái Y-sơ-ra-ên.'),
(5768, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 9, 'OT', 'Vì phần của Đức Giê-hô-va là dân Ngài, Gia-cốp là dây đo cơ nghiệp Ngài.'),
(5769, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 10, 'OT', 'Người tìm thấy người ấy trong một vùng đất hoang, giữa nơi hoang vu và tiếng rên rỉ của đồng vắng; Ngài bao quanh người ấy, chăm sóc người ấy, gìn giữ người ấy như con ngươi nơi mắt mình.'),
(5770, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 11, 'OT', 'Như chim ưng đánh thức tổ mình, vỗ cánh trên các con nhỏ, sẽ giang cánh ra, bắt lấy nó, và nâng nó lên trên đôi cánh mình.'),
(5771, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 12, 'OT', 'Đức Giê-hô-va một mình dẫn dắt nó, chẳng có thần ngoại nào cùng nó.'),
(5772, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 13, 'OT', 'Ngài khiến Y-sơ-ra-ên cỡi trên các nơi cao của đất, ăn hoa quả đồng ruộng, hút mật từ hòn đá, và dầu từ tảng đá cứng.'),
(5773, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 14, 'OT', 'Sữa bò và sữa chiên, cùng mỡ của chiên đực và chiên đực con sinh tại Ba-san, cùng dê đực, cùng mỡ của thận lúa mì; ngươi uống huyết nho như rượu mạnh.'),
(5774, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 15, 'OT', 'Giê-su-run đã mập mạp và đá, ngươi trở nên mập, béo tròn và đầy đặn; rồi ngươi đã lìa bỏ Đức Chúa Trời, là Đấng đã tạo nên ngươi, và khinh dể Hòn Đá cứu rỗi ngươi.'),
(5775, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 16, 'OT', 'Chúng khiến Ngài ghen tuông bởi những thần ngoại đạo, chọc giận Ngài bởi những điều ghê tởm.'),
(5776, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 17, 'OT', 'Họ dâng tế lễ cho các thần chẳng phải là Đức Chúa Trời, cho các thần mà họ không biết, các thần mới xuất hiện gần đây, mà tổ phụ các ngươi không kính sợ.'),
(5777, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 18, 'OT', 'Ngươi đã ruồng bỏ Đức Chúa Trời là Đấng sanh ngươi, và quên Đấng đã sinh ra ngươi.'),
(5778, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 19, 'OT', 'Đức Giê-hô-va thấy vậy, bèn khinh bỉ vì tức giận về các con trai và con gái mình.'),
(5779, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 20, 'OT', 'Đức Giê-hô-va phán: Ta sẽ giấu mặt khỏi chúng nó, Ta sẽ xem chúng nó cuối cùng ra sao; vì là một dòng dõi gian tà, những con cái không trung tín.'),
(5780, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 21, 'OT', 'Chúng đã khiến Ta ghen tức vì những thần chẳng phải là Đức Chúa Trời, chọc giận Ta vì những điều hư không của chúng; và Ta sẽ khiến chúng ghen tức vì một dân chẳng phải là dân Ta, chọc giận chúng vì một dân tộc ngu dại.'),
(5781, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 22, 'OT', 'Vì một ngọn lửa bừng lên trong cơn thịnh nộ ta, bốc cháy cho đến tận âm phủ sâu thẳm, thiêu đốt đất và mùa màng, và đốt cháy nền tảng các núi.'),
(5782, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 23, 'OT', 'Ta sẽ chất những tai họa trên chúng nó, dùng các mũi tên ta tiêu diệt chúng.'),
(5783, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 24, 'OT', 'Bị tiêu hao bởi đói khát, bị thiêu đốt bởi sức nóng dữ dội, bị nuốt chửng bởi bệnh dịch tàn ác; ta sẽ sai răng các loài thú dữ và nọc độc của những sinh vật bò trên đất.'),
(5784, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 25, 'OT', 'Ngoài thì gươm sẽ giết, trong thì kinh hoàng sẽ hại; cả người trai trẻ, gái đồng trinh, trẻ đang bú lẫn người già cả.'),
(5785, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 26, 'OT', 'Ta nói: Ta sẽ khiến hơi thở Ta tiêu tan chúng đi, sẽ làm mất khỏi loài người kỷ niệm về chúng.'),
(5786, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 27, 'OT', 'Ví bằng ta không sợ cơn giận của kẻ thù, e đối thủ chúng hiểu lầm, kẻo chúng nói rằng: Tay chúng ta đã cao cường, chứ chẳng phải Đức Giê-hô-va đã làm mọi điều nầy!'),
(5787, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 28, 'OT', 'Vì là một dân mất trí, trong lòng không có thông sáng!'),
(5788, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 29, 'OT', 'Ước gì họ có sự khôn ngoan, hiểu điều nầy, và suy gẫm về phần cuối cùng của mình!'),
(5789, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 30, 'OT', 'Làm sao một người đuổi được ngàn người, và hai người làm cho vạn người chạy trốn? Nếu không phải vì Hòn Đá của họ đã bán họ, và Đức Giê-hô-va đã phó họ?'),
(5790, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 31, 'OT', 'Vì hòn đá của họ không giống như Hòn Đá của chúng ta; chính kẻ thù chúng ta cũng phải xét xử điều đó.'),
(5791, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 32, 'OT', 'Vì cây nho của chúng là từ Sô-đôm, và từ các vườn Gô-mô-rơ; trái nho của chúng là trái độc cần, chùm nho của chúng là những chùm đắng cay.'),
(5792, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 33, 'OT', 'Rượu của chúng là nọc rắn, đầu độc của rắn hổ, rất cay đắng.'),
(5793, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 34, 'OT', 'Chẳng phải những điều ấy đều được cất giữ gần Ta, niêm phong trong các kho tàng của Ta sao?'),
(5794, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 35, 'OT', 'Sự báo thù thuộc về ta, ta sẽ đối đền; khi chân chúng nó xiêu ngã. Vì ngày tai họa của chúng nó đã gần kề, và những điều sắp xảy đến cho chúng nó sẽ mau chóng xảy ra.'),
(5795, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 36, 'OT', 'Vì Đức Giê-hô-va sẽ xét đoán dân Ngài và sẽ thương xót các tôi tớ Ngài, khi thấy tay không còn sức lực, và chẳng còn kẻ bị giam hay kẻ được thả ra.'),
(5796, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 37, 'OT', 'Thì Ngài sẽ nói: Các thần của chúng nó đâu, hòn đá mà chúng nó nương nhờ,'),
(5797, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 38, 'OT', 'Các thần hưởng mỡ của lễ tế chúng nó, uống rượu lễ quán của chúng; hãy chỗi dậy giúp đỡ các ngươi, và che chở các ngươi!'),
(5798, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 39, 'OT', 'Hãy xem đây, chính Ta là Đức Chúa Trời, ngoài Ta không có Đức Chúa Trời nào khác. Chính Ta làm cho chết và cho sống lại, Ta đánh phạt và Ta chữa lành, chẳng có ai cứu được khỏi tay Ta.'),
(5799, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 40, 'OT', 'Vì ta sẽ giơ tay chỉ trời mà thề rằng: Đức Giê-hô-va hằng sống đời đời.'),
(5800, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 41, 'OT', 'Khi Ta mài sắc lưỡi gươm Ta, và tay Ta nắm giữ sự xét đoán, thì Ta sẽ báo trả sự báo thù cho kẻ thù nghịch Ta, và hoàn trả cho những kẻ ghét Ta.'),
(5801, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 42, 'OT', 'Ta sẽ làm cho các mũi tên Ta say máu; gươm Ta sẽ ăn thịt, tức là máu của những người bị giết và những kẻ bị bắt, từ đầu các thủ lĩnh kẻ thù.'),
(5802, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 43, 'OT', 'Hỡi các nước, hãy reo vui cùng dân Ngài, vì Đức Giê-hô-va sẽ báo thù huyết của tôi tớ Ngài, và báo sự báo thù cho kẻ thù nghịch Ngài, và sẽ làm cho đất Ngài được xá tội cho dân Ngài.'),
(5803, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 44, 'OT', 'Môi-se cùng Giô-suê, con trai của Nun, đến và nói hết các lời của bài ca nầy vào tai dân sự.'),
(5804, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 45, 'OT', 'Môi-se đã nói xong tất cả các lời nầy cho toàn thể Y-sơ-ra-ên.'),
(5805, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 46, 'OT', 'Hãy để lòng vào trọn những lời mà hôm nay ta làm chứng cho các ngươi, để các ngươi truyền cho con cái mình, phải cẩn thận làm theo trọn các lời của luật pháp nầy.'),
(5806, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 47, 'OT', 'Vì đó chẳng phải là một lời trống rỗng đối với các ngươi, mà chính là sự sống của các ngươi; và nhờ điều răn nầy, các ngươi sẽ sống lâu ngày trên đất mà các ngươi sắp qua sông Giô-đanh để chiếm lấy.'),
(5807, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 48, 'OT', 'Trong ngày ấy, Đức Giê-hô-va phán cùng Môi-se rằng:'),
(5808, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 49, 'OT', 'Hãy đi lên núi A-ba-rim này, núi Nê-bô, ở trong đất Mô-áp, đối diện Giê-ri-cô, và nhìn xem đất Ca-na-an mà Đức Giê-hô-va ban cho con cái Y-sơ-ra-ên làm sản nghiệp.'),
(5809, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 50, 'OT', 'rồi ngươi sẽ chết trên núi mà ngươi đang lên đó, và sẽ được thu nhận về cùng dân ngươi, y như A-rôn, anh ngươi, đã chết trên núi Hô-rơ và được thu nhận về cùng dân người.'),
(5810, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 51, 'OT', 'vì các ngươi đã phạm tội cùng ta giữa con cái Y-sơ-ra-ên tại các nước Mê-ri-ba ở Ca-đe, trong đồng vắng Xin; vì các ngươi không thánh hóa ta giữa con cái Y-sơ-ra-ên.'),
(5811, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 32, 52, 'OT', 'Vì ngươi sẽ thấy đất từ xa, nhưng không được vào đất ấy, là đất ta ban cho Y-sơ-ra-ên.'),
(5812, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 33, 1, 'OT', 'Đây là lời chúc phước mà Môi-se, người của Đức Chúa Trời, đã chúc cho con cái Y-sơ-ra-ên, trước khi ông qua đời.'),
(5813, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 33, 2, 'OT', 'Người phán: Đức Giê-hô-va từ Si-na-i mà đến, chiếu sáng từ Sê-i-rơ cho họ, hiện ra từ núi Pha-ran, và đến từ giữa muôn vàn thánh, từ tay hữu Ngài đưa ra cho họ lửa của luật pháp Ngài.'),
(5814, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 33, 3, 'OT', 'Đức Giê-hô-va yêu thương các dân tộc, tất cả những người thánh của Ngài đều ở trong tay Ngài; họ sẽ quì xuống trước chân Ngài, và nhận lấy các lời giáo huấn của Ngài.'),
(5815, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 33, 4, 'OT', 'Môi-se đã truyền cho chúng tôi một luật pháp, làm cơ nghiệp cho hội chúng Gia-cốp.'),
(5816, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 33, 5, 'OT', 'Người trở thành vua trong Giê-su-run, khi các đầu mục của dân họp lại, các chi phái Y-sơ-ra-ên họp chung một nơi.'),
(5817, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 33, 6, 'OT', 'Nguyện Ru-bên được sống và chớ chết; số người của người ấy sẽ đông.'),
(5818, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 33, 7, 'OT', 'Và đây là điều dành cho Giu-đa: Xin Đức Giê-hô-va nghe tiếng của Giu-đa, và đưa người về cùng dân mình; nguyện tay người tranh chiến cho người, và nguyện Đấng phù trợ người khỏi các kẻ thù nghịch!'),
(5819, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 33, 8, 'OT', 'Và về Lê-vi, Người nói: "Thu-mim và U-rim của ngươi thuộc về người trung thành của ngươi, mà ngươi đã thử tại Ma-sa, đã tranh luận với người ấy tại nước Mê-ri-ba."'),
(5820, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 33, 9, 'OT', 'Người nói cùng cha mình: Ta chẳng thấy cha; cùng mẹ mình: Ta không biết mẹ; chẳng nhận anh em mình, chẳng biết con cái mình; vì họ giữ lời Đức Giê-hô-va, và gìn giữ giao ước Ngài.'),
(5821, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 33, 10, 'OT', 'Họ sẽ dạy mạng lịnh Ngài cho Gia-cốp và luật pháp Ngài cho Y-sơ-ra-ên; họ sẽ đặt hương trong sự hiện diện Ngài, và lễ toàn thiêu trên bàn thờ Ngài.'),
(5822, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 33, 11, 'OT', 'Xin Đức Giê-hô-va ban phước cho sức mạnh của người, và chấp nhận công việc do tay người làm ra; xin đánh đổ những kẻ vùng lên chống lại người và những kẻ ghét người, để chúng không thể đứng lên được nữa.'),
(5823, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 33, 12, 'OT', 'Về Bên-gia-min, người nói: Người được Đức Giê-hô-va yêu thương sẽ ở an toàn bên Ngài; suốt cả ngày, Ngài sẽ che chở người ấy, và nơi ở của Ngài sẽ đặt giữa hai vai người ấy.'),
(5824, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 33, 13, 'OT', 'Về Giô-sép, người nói: Đất của người được Đức Giê-hô-va ban phước, từ tinh hoa trên trời, từ sương, và từ vực sâu nằm dưới đất.'),
(5825, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 33, 14, 'OT', 'Và những sản vật quý báu nhất của mặt trời, và những hoa màu tinh túy nhất của các tháng.'),
(5826, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 33, 15, 'OT', 'Và từ đầu các núi xưa, cùng từ những điều tốt nhất của các gò vĩnh hằng,'),
(5827, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 33, 16, 'OT', 'Và sự tốt lành của đất cùng mọi điều phong phú trong nó, và ơn của Đấng ngự nơi bụi gai, nguyện đổ xuống trên đầu Giô-sép, và trên trán người được biệt riêng ra giữa anh em người!'),
(5828, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 33, 17, 'OT', 'Sức mạnh của nó giống như con bò đực đầu lòng, oai nghi thuộc về nó; hai sừng của nó là sừng trâu rừng; nhờ hai sừng ấy nó sẽ húc, cùng nhau đánh đổ các dân cho đến tận cùng đất; ấy là hằng muôn của Eùp-ra-im, ấy là hằng ngàn của Ma-na-se.'),
(5829, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 33, 18, 'OT', 'Đức Giê-hô-va phán về Sa-bu-lôn: Hỡi Sa-bu-lôn, hãy vui mừng trong cuộc ra đi của ngươi; và hỡi Y-sa-ca, hãy hớn hở trong các trại ngươi!'),
(5830, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 33, 19, 'OT', 'Các dân sẽ được gọi đến núi ấy, nơi họ dâng những của lễ tế công bình; vì họ sẽ hút lấy sự phong phú của biển cả, và những kho tàng ẩn giấu trong cát.'),
(5831, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 33, 20, 'OT', 'Đức Giê-hô-va phán về Gát: Đáng ca ngợi là người làm cho Gát được mở rộng; người nằm như sư tử cái, và xé nát cánh tay cùng đỉnh đầu.'),
(5832, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 33, 21, 'OT', 'Người đã thấy phần đầu tiên của mình, vì tại đó phần của đấng lãnh đạo được dành riêng; Người đến đầu các dân, thực hiện sự công bình của Đức Giê-hô-va và các phán quyết của Ngài cùng với Y-sơ-ra-ên.'),
(5833, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 33, 22, 'OT', 'Đan là một sư tử tơ, từ Ba-san nhảy xổ tới.'),
(5834, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 33, 23, 'OT', 'Và về Nép-ta-li, người nói: Hỡi Nép-ta-li, đầy sự hài lòng, và đầy dẫy phước lành của Đức Giê-hô-va, ngươi sẽ chiếm giữ biển và phương nam.'),
(5835, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 33, 24, 'OT', 'Chúc phước cho A-se rằng: A-se được phước hơn các con trai Y-sơ-ra-ên; được đẹp lòng anh em mình, và dầm chân mình trong dầu!'),
(5836, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 33, 25, 'OT', 'Then cửa của người sẽ bằng sắt và đồng; bao lâu người sống, sức lực người cũng bấy lâu.'),
(5837, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 33, 26, 'OT', 'Không ai giống như Giê-su-run, Đức Chúa Trời cỡi các từng trời đến giúp ngươi, và trong sự oai nghiêm Ngài, các tầng mây.'),
(5838, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 33, 27, 'OT', 'Đức Chúa Trời hằng hữu là nơi nương náu của ngươi, và dưới có những cánh tay đời đời; Ngài đã đuổi kẻ thù ra khỏi trước mặt ngươi, và phán: Hãy tiêu diệt!'),
(5839, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 33, 28, 'OT', 'Gia-cốp sẽ ở an toàn một mình; Y-sơ-ra-ên sẽ ở trong một xứ có lúa mì và rượu mới; các từng trời ngươi cũng nhỏ xuống sương.'),
(5840, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 33, 29, 'OT', 'Phước thay cho Y-sơ-ra-ên! Ai giống như ngươi, một dân được Đức Giê-hô-va cứu giúp? Ngài là cái khiên che chở ngươi, và là gươm oai hùng của ngươi; các kẻ thù ngươi sẽ phải khuất phục ngươi, còn ngươi sẽ đạp chân lên các nơi cao của chúng nó.'),
(5841, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 34, 1, 'OT', 'Môi-se từ các đồng bằng Mô-áp lên núi Nê-bô, đến đỉnh Phích-ga, đối diện Giê-ri-cô, và Đức Giê-hô-va cho người xem toàn cõi đất, từ Ga-la-át cho đến Đan.'),
(5842, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 34, 2, 'OT', 'toàn thể xứ Nép-ta-li, và xứ Eùp-ra-im cùng Ma-na-se, và toàn thể xứ Giu-đa cho đến biển phía tây,'),
(5843, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 34, 3, 'OT', 'miền Nam, đồng bằng, thung lũng sông Giô-đanh và thành Giê-ri-cô, thành cây chà là, cho đến Xoa.'),
(5844, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 34, 4, 'OT', 'Đức Giê-hô-va phán cùng Môi-se rằng: Đây là xứ mà Ta đã thề ban cho Aùp-ra-ham, Y-sác và Gia-cốp, mà rằng: Ta sẽ ban cho dòng dõi ngươi. Ta đã cho ngươi thấy bằng chính mắt ngươi, nhưng ngươi sẽ không sang qua đó được.'),
(5845, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 34, 5, 'OT', 'Môi-se, tôi tớ của Đức Giê-hô-va, qua đời tại đó, trong đất Mô-áp, theo như lịnh của Đức Giê-hô-va.'),
(5846, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 34, 6, 'OT', 'Đức Chúa Trời chôn người trong trũng, tại xứ Mô-áp, đối ngang Bết-Phê-o; và không ai biết nơi mai táng của người cho đến ngày nay.'),
(5847, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 34, 7, 'OT', 'Môi-se một trăm hai mươi tuổi khi qua đời; mắt người không mờ, sức lực người không suy.'),
(5848, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 34, 8, 'OT', 'Dân Y-sơ-ra-ên khóc than Môi-se trong ba mươi ngày tại các đồng bằng Mô-áp. Những ngày khóc than và để tang cho Môi-se đã xong.'),
(5849, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 34, 9, 'OT', 'Giô-suê, con trai của Nun, được đầy dẫy thần linh khôn ngoan, vì Môi-se đã đặt tay mình trên người; và con cái Y-sơ-ra-ên vâng lời người, làm theo mọi điều Đức Giê-hô-va đã truyền cho Môi-se.'),
(5850, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 34, 10, 'OT', 'Về sau, trong Y-sơ-ra-ên không còn dấy lên một đấng tiên tri nào giống như Môi-se, là người mà Đức Giê-hô-va biết mặt giáp mặt.'),
(5851, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 34, 11, 'OT', 'về mọi dấu kỳ và phép lạ mà Đức Giê-hô-va sai ông làm tại đất Ê-díp-tô, cho Pha-ra-ôn và cho mọi tôi tớ ông, và cho cả đất nước ông;'),
(5852, 5, 'GOI_vi', 'GOI_vi', 'vi', 'DEU', 34, 12, 'OT', 'và cho mọi việc tay quyền năng và mọi sự khủng khiếp lớn lao mà Môi-se đã làm trước mặt cả Y-sơ-ra-ên.'),
(5853, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 1, 1, 'OT', 'Sau khi Môi-se, tôi tớ của Đức Giê-hô-va, qua đời, thì Đức Giê-hô-va phán cùng Giô-suê, con trai của Nun, người giúp việc Môi-se, rằng:'),
(5854, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 1, 2, 'OT', 'Môi-se, tôi tớ ta, đã chết; bây giờ hãy chỗi dậy, qua sông Giô-đanh nầy, ngươi và toàn thể dân sự nầy, đến đất mà ta sắp ban cho con cháu Y-sơ-ra-ên.'),
(5855, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 1, 3, 'OT', 'Mọi nơi nào lòng bàn chân các ngươi đặt tới, Ta đã ban cho các ngươi, như Ta đã phán cùng Môi-se.'),
(5856, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 1, 4, 'OT', 'Từ sa mạc và vùng Li-băng này cho đến sông lớn, sông Eu-phrát, toàn cõi đất của người Hê-tít, và cho đến Biển Lớn về hướng lặn của mặt trời, sẽ là phần đất biên giới của các ngươi.'),
(5857, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 1, 5, 'OT', 'Chẳng có ai sẽ đứng nổi trước mặt ngươi suốt mọi ngày trong đời ngươi; như Ta đã ở cùng Môi-se, Ta cũng sẽ ở cùng ngươi. Ta sẽ không buông ngươi ra, cũng chẳng lìa bỏ ngươi.'),
(5858, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 1, 6, 'OT', 'Hãy mạnh mẽ và can đảm, vì chính ngươi sẽ chia đất nầy làm sản nghiệp cho dân nầy, là đất mà Ta đã thề cùng tổ tiên họ để ban cho họ.'),
(5859, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 1, 7, 'OT', 'Chỉ cần ngươi phải mạnh mẽ và hết sức can đảm, để cẩn thận tuân theo và thực hiện trọn vẹn mọi điều trong luật pháp mà Môi-se, tôi tớ ta, đã truyền cho ngươi; đừng xây khỏi nó sang bên phải hay bên trái, hầu ngươi được thành công trong mọi nơi ngươi đi đến.'),
(5860, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 1, 8, 'OT', 'Đừng để cuốn sách Luật pháp nầy ra khỏi miệng ngươi; hãy suy ngẫm trong đó ngày và đêm, để cẩn thận làm theo mọi điều đã viết trong đó; vì khi ấy, ngươi sẽ làm cho con đường mình được thịnh vượng, và khi ấy, ngươi sẽ thành công.'),
(5861, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 1, 9, 'OT', 'Hãy chẳng phải Ta đã truyền cho ngươi sao? Hãy mạnh mẽ và can đảm; đừng sợ hãi, cũng đừng kinh hoàng, vì Đức Giê-hô-va Đức Chúa Trời ngươi sẽ ở cùng ngươi trong mọi nơi ngươi đi đến.'),
(5862, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 1, 10, 'OT', 'Giô-suê ra lệnh cho các sĩ quan của dân chúng, rằng:'),
(5863, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 1, 11, 'OT', 'Hãy đi ngang qua trại quân và truyền cho dân chúng rằng: "Hãy chuẩn bị lương thực; vì ba ngày nữa, các ngươi sẽ vượt qua sông Giô-đanh này để vào chiếm lấy đất mà Đức Giê-hô-va Đức Chúa Trời các ngươi ban cho các ngươi làm sản nghiệp."'),
(5864, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 1, 12, 'OT', 'Giô-suê nói với người Ru-bên, người Ga-đi và phân nửa chi phái Ma-na-se rằng:'),
(5865, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 1, 13, 'OT', 'Hãy nhớ lời mà Môi-se, đầy tớ của Đức Giê-hô-va, đã truyền cho các ngươi, rằng: Đức Giê-hô-va Đức Chúa Trời các ngươi đã cho các ngươi được nghỉ ngơi, và đã ban cho các ngươi đất nầy.'),
(5866, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 1, 14, 'OT', 'Vợ các ngươi, con nhỏ và súc vật của các ngươi sẽ ở lại trong đất mà Môi-se đã ban cho các ngươi bên kia sông Giô-đanh; còn các ngươi, hãy đi qua trước mặt anh em mình, tất cả những người tráng kiện và dũng cảm, để giúp đỡ họ.'),
(5867, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 1, 15, 'OT', 'Cho đến khi Đức Giê-hô-va ban cho anh em anh em sự an nghỉ như Ngài đã ban cho anh em, và họ cũng chiếm hữu đất mà Đức Giê-hô-va Đức Chúa Trời của anh em ban cho họ; bấy giờ anh em hãy trở về đất sản nghiệp của mình và chiếm hữu nó, là đất mà Môi-se, tôi tớ của Đức Giê-hô-va, đã ban cho anh em bên kia sông Giô-đanh, về hướng mặt trời mọc.'),
(5868, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 1, 16, 'OT', 'Họ trả lời với Giô-suê, rằng: Tất cả những gì ông truyền cho chúng tôi, chúng tôi sẽ làm, và bất cứ nơi nào ông sai chúng tôi đi, chúng tôi sẽ đi.'),
(5869, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 1, 17, 'OT', 'Chúng tôi sẽ nghe theo ông y như chúng tôi đã nghe theo Môi-se trong mọi điều; chỉ xin Đức Giê-hô-va Đức Chúa Trời của ông ở cùng ông, như Ngài đã ở cùng Môi-se.'),
(5870, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 1, 18, 'OT', 'Bất cứ người nào chống cự lại lời ngươi hoặc không nghe theo các lời ngươi trong mọi điều ngươi truyền cho người ấy, thì phải bị xử tử; chỉ cần mạnh mẽ và can đảm.'),
(5871, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 2, 1, 'OT', 'Giô-suê con trai của Nun sai hai người đàn ông từ Sit-tim đi do thám cách kín, nói rằng: "Hãy đi, xem xét vùng đất và Giê-ri-khô." Họ đi và vào nhà một người đàn bà điếm tên là Ra-háp, rồi ở lại đó.'),
(5872, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 2, 2, 'OT', 'Và người ta báo cho vua Giê-ri-khô rằng: "Kìa, có những người đã đến đây đêm nay từ giữa các con trai của Y-sơ-ra-ên để do thám vùng đất."'),
(5873, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 2, 3, 'OT', 'Vua thành Giê-ri-cô sai người đến Ra-háp, nói rằng: "Hãy đưa ra những người đã đến cùng ngươi, đã vào nhà ngươi, vì họ đến để do thám khắp đất này."'),
(5874, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 2, 4, 'OT', 'Người đàn bà lấy hai người đàn ông và giấu đi, rồi nói: Đúng vậy, hai người ấy đã đến cùng tôi, nhưng tôi không biết họ từ đâu đến.'),
(5875, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 2, 5, 'OT', 'Khi cửa sắp đóng vào lúc trời tối, những người đàn ông đã ra đi. Tôi không biết họ đi đâu. Hãy nhanh chóng đuổi theo họ, vì các ông sẽ bắt kịp họ.'),
(5876, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 2, 6, 'OT', 'Nhưng bà đã đưa họ lên mái nhà và giấu họ dưới những cây gai dầu mà bà đã xếp sẵn trên mái nhà.'),
(5877, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 2, 7, 'OT', 'Còn những người đàn ông thì đuổi theo họ dọc đường về sông Giô-đanh đến các chỗ lội qua; và khi những kẻ đuổi theo họ vừa ra đi, người ta liền đóng cửa thành lại.'),
(5878, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 2, 8, 'OT', 'Chúng chưa đi ngủ thì nàng đã lên mái nhà đến cùng họ.'),
(5879, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 2, 9, 'OT', 'Bà nói với những người ấy: "Tôi biết Đức Giê-hô-va đã ban đất nầy cho các ông, và rằng sự kinh khủng của các ông đã giáng trên chúng tôi, và rằng mọi dân cư trong đất đều tan tác vì các ông."'),
(5880, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 2, 10, 'OT', 'Vì chúng tôi đã nghe Đấng Giê-hô-va làm cho nước Biển Đỏ khô cạn trước mặt các ngươi khi các ngươi ra khỏi Ai-cập; và điều các ngươi đã làm cho hai vua dân A-mô-rít ở bên kia sông Giô-đanh, cho Xi-hôn và Oùc, mà các ngươi đã tiêu diệt hoàn toàn.'),
(5881, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 2, 11, 'OT', 'Khi chúng tôi vừa nghe điều đó, lòng chúng tôi tan chảy, và chẳng còn ai dám giữ vững tinh thần trước mặt các ông; vì Đức Giê-hô-va Đức Chúa Trời các ông chính là Đức Chúa Trời trên các tầng trời bên trên và trên đất bên dưới.'),
(5882, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 2, 12, 'OT', 'Bây giờ, tôi nài xin các ông hãy chỉ Đức Giê-hô-va mà thề, vì tôi đã đối xử nhân từ với các ông, rằng các ông cũng sẽ đối xử nhân từ với nhà cha tôi, và sẽ ban cho tôi một dấu thực sự.'),
(5883, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 2, 13, 'OT', 'Hãy ban sự sống cho cha tôi, mẹ tôi, các anh tôi, các chị tôi, và tất cả những gì thuộc về họ, và giải cứu mạng sống chúng tôi khỏi sự chết.'),
(5884, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 2, 14, 'OT', 'Hai người nói với cô: "Tính mạng chúng tôi thay cho các cô, nếu các cô không tiết lộ việc này của chúng tôi. Và khi Đức Giê-hô-va trao cho chúng tôi đất nầy, thì chúng tôi sẽ đối xử nhân từ và thành thật với cô."'),
(5885, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 2, 15, 'OT', 'Bà cho họ xuống bằng dây qua cửa sổ, vì nhà bà nằm ngay trên vách thành, và bà sống ngay trên vách thành ấy.'),
(5886, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 2, 16, 'OT', 'Bà ấy nói với họ: "Hãy đi trốn lên núi, kẻo những người đang truy đuổi gặp các ông. Các ông hãy ẩn náu ở đó ba ngày, cho đến khi những người truy đuổi trở về; rồi sau đó hãy đi đường các ông."'),
(5887, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 2, 17, 'OT', 'Các người đàn ông nói với cô: Chúng tôi được miễn trách nhiệm về lời thề mà cô đã khiến chúng tôi thề.'),
(5888, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 2, 18, 'OT', 'Này, khi chúng ta vào đất ấy, ngươi phải buộc sợi dây chỉ đỏ này vào cửa sổ mà ngươi đã thả chúng ta xuống, và phải đưa cha ngươi, mẹ ngươi, các anh em ngươi, cùng mọi người trong nhà cha ngươi về nhà ngươi.'),
(5889, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 2, 19, 'OT', 'Nếu ai ra khỏi cửa nhà ngươi ra ngoài đường phố, máu người ấy sẽ đổ trên đầu người ấy, còn chúng tôi sẽ vô can; nhưng nếu ai ở cùng ngươi trong nhà, máu người ấy sẽ đổ trên đầu chúng tôi, nếu tay nào chống lại người ấy.'),
(5890, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 2, 20, 'OT', 'Và nếu cô tiết lộ việc của chúng tôi, thì chúng tôi sẽ được miễn trách nhiệm về lời thề mà cô đã buộc chúng tôi thề.'),
(5891, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 2, 21, 'OT', 'Bà nói: "Theo như lời các anh đã nói, thì cứ như vậy đi." Rồi bà tiễn họ đi, và họ ra đi; bà liền buộc sợi dây chỉ đỏ vào cửa sổ.'),
(5892, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 2, 22, 'OT', 'Họ đi và đến núi, rồi ở đó ba ngày, cho đến khi những kẻ đuổi theo trở về; những kẻ đuổi theo đã tìm kiếm dọc suốt con đường, nhưng không tìm thấy họ.'),
(5893, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 2, 23, 'OT', 'Hai người đàn ông trở về, xuống khỏi núi, đi qua và đến cùng Giô-suê con trai của Nun, rồi thuật lại cho ông mọi điều đã xảy đến với họ.'),
(5894, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 2, 24, 'OT', 'Họ nói với Giô-suê: "Thật vậy, Đức Giê-hô-va đã trao toàn bộ đất nầy vào tay chúng ta, và mọi dân cư trong đất đều tan mất trước mặt chúng ta."'),
(5895, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 3, 1, 'OT', 'Giô-suê dậy sớm vào buổi sáng, rồi họ rời khỏi Sit-tim và đến sông Giô-đanh, người cùng với toàn thể con cái Ít-ra-en; và họ ở trọ tại đó trước khi qua sông.'),
(5896, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 3, 2, 'OT', 'Sau ba ngày, các quan chỉ huy đi qua giữa trại quân.'),
(5897, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 3, 3, 'OT', 'Họ dặn dân chúng rằng: "Khi các ngươi thấy hòm giao ước của Đức Giê-hô-va Đức Chúa Trời các ngươi, và các thầy tế lễ người Lê-vi khiêng nó, thì các ngươi hãy rời khỏi chỗ mình đứng và đi theo nó."'),
(5898, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 3, 4, 'OT', 'Nhưng phải có khoảng cách giữa các ngươi và nó, khoảng hai ngàn thước đo; chớ lại gần nó, để các ngươi biết con đường mà các ngươi phải đi, vì các ngươi chưa từng đi qua con đường ấy từ trước.'),
(5899, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 3, 5, 'OT', 'Và Giô-suê nói với dân chúng: "Hãy làm cho mình nên thánh, vì ngày mai Đức Giê-hô-va sẽ làm những điều kỳ diệu giữa các ngươi."'),
(5900, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 3, 6, 'OT', 'Và Giô-suê nói với các thầy tế lễ rằng: "Hãy khiêng hòm giao ước và đi qua trước mặt dân chúng." Vậy họ khiêng hòm giao ước và đi trước mặt dân chúng.'),
(5901, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 3, 7, 'OT', 'Đức Giê-hô-va phán cùng Giô-suê rằng: "Ngày nay Ta sẽ bắt đầu làm cho ngươi được tôn trọng trước mặt toàn thể Y-sơ-ra-ên, để họ biết rằng Ta sẽ ở cùng ngươi như Ta đã ở cùng Môi-se."'),
(5902, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 3, 8, 'OT', 'Còn ngươi, hãy truyền cho các thầy tế lễ mang hòm giao ước, rằng: "Khi các ngươi đến bờ nước sông Giô-đanh, hãy đứng lại trong sông Giô-đanh."'),
(5903, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 3, 9, 'OT', 'Và Giô-suê nói với các con trai của Y-sơ-ra-ên: "Hãy đến đây và nghe các lời của Đức Giê-hô-va Đức Chúa Trời các ngươi."'),
(5904, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 3, 10, 'OT', 'Giô-suê nói: "Chính bởi điều nầy các ngươi sẽ biết Đức Chúa Trời hằng sống đang ở giữa các ngươi, và Ngài chắc chắn sẽ đuổi ra khỏi trước mặt các ngươi người Ca-na-an, người Hê-th, người Hê-vi, người Phê-ri-xi, người Ghích-ga-xi, người A-mô-rít và người Giê-bu-xi."'),
(5905, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 3, 11, 'OT', 'Này, hòm giao ước của Đức Giê-hô-va, là Chúa của cả đất, sẽ đi trước mặt các ngươi qua sông Giô-đanh.'),
(5906, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 3, 12, 'OT', 'Bây giờ, hãy chọn cho các ngươi mười hai người từ các chi phái của Y-sơ-ra-ên, mỗi chi phái một người.'),
(5907, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 3, 13, 'OT', 'Xảy đến lúc các lòng bàn chân của các thầy tế lễ, những kẻ khiêng hòm giao ước của Đức Giê-hô-va, Chúa của cả đất, dừng lại trong các nước sông Giô-đanh, thì các nước sông Giô-đanh sẽ bị ngăn lại, các nước chảy từ phía trên sẽ ngưng lại và chất đống lên thành một đống.'),
(5908, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 3, 14, 'OT', 'Khi dân chúng dời khỏi các trại để đi qua sông Giô-đanh, các thầy tế lễ khiêng hòm giao ước đi trước dân chúng.'),
(5909, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 3, 15, 'OT', 'Khi những người khiêng hòm đến bên sông Giô-đanh, và chân các thầy tế lễ khiêng hòm chạm xuống mé nước, thì sông Giô-đanh đang đầy tràn khỏi các bờ của nó suốt thời gian gặt hái.'),
(5910, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 3, 16, 'OT', 'Các nước từ trên chảy xuống thì đứng lại, dưng lên thành một đống rất xa, gần thành A-đam, tức là thành bên cạnh Xa-rê-than; còn các nước chảy xuống biển đồng bằng, tức là Biển Mặn, thì cạn hẳn và bị ngắt; dân chúng thì đi qua, đối diện với Giê-ri-cô.'),
(5911, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 3, 17, 'OT', 'Các thầy tế lễ mang hòm giao ước của Đức Giê-hô-va thì đứng vững trên đất khô giữa sông Giô-đanh; và toàn thể Ít-ra-en đi qua trên đất khô, cho đến khi cả dân chúng đều đi ngang qua sông Giô-đanh.'),
(5912, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 4, 1, 'OT', 'Khi toàn thể dân đã qua sông Giô-đanh xong, thì Đức Giê-hô-va phán cùng Giô-suê rằng:'),
(5913, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 4, 2, 'OT', 'Hãy chọn cho các ngươi mười hai người từ dân sự, mỗi chi phái một người.'),
(5914, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 4, 3, 'OT', 'Hãy truyền cho họ rằng: "Hãy lấy từ đây, từ giữa sông Giô-đanh, từ chỗ các thầy tế lễ đang đứng, mười hai hòn đá, và các ngươi hãy mang theo mình, rồi đặt những hòn đá đó tại nơi các ngươi sẽ nghỉ đêm nay."'),
(5915, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 4, 4, 'OT', 'Bấy giờ Giô-suê gọi mười hai người mà ông đã chọn từ con cái Y-sơ-ra-ên, mỗi chi phái một người.'),
(5916, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 4, 5, 'OT', 'Rồi Giô-suê nói với họ: "Hãy đi qua trước hòm bia của Đức Giê-hô-va Đức Chúa Trời các ngươi vào giữa sông Giô-đanh, và mỗi người hãy khiêng một tảng đá trên vai mình, theo số các chi phái của con cái Ít-ra-en."'),
(5917, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 4, 6, 'OT', 'Để điều nầy làm dấu giữa các ngươi, hầu khi con cháu các ngươi ngày sau hỏi rằng: Những hòn đá nầy là gì cho các ngươi?'),
(5918, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 4, 7, 'OT', 'Các ngươi sẽ nói cho họ biết: "Nước sông Giô-đanh đã bị chặn lại trước hòm giao ước của Đức Giê-hô-va khi dân này qua sông; nước sông Giô-đanh đã bị chặn lại. Những tảng đá nầy sẽ làm kỷ niệm cho con cháu Ít-ra-en đến đời đời."'),
(5919, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 4, 8, 'OT', 'Dân Y-sơ-ra-ên làm như vậy, theo như Giô-suê đã truyền; họ khiêng mười hai hòn đá từ giữa sông Giô-đanh, y như lời Đức Giê-hô-va truyền cho Giô-suê, theo đúng số chi phái của con cái Y-sơ-ra-ên; rồi họ mang những hòn đá ấy theo mình đến nơi họ trọ, và đặt tại đó.'),
(5920, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 4, 9, 'OT', 'Giô-suê dựng mười hai tảng đá giữa sông Giô-đanh, ngay tại nơi chân các thầy tế lễ đang khiêng hòm giao ước đứng; và các tảng đá ấy vẫn còn ở đó cho đến ngày nay.'),
(5921, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 4, 10, 'OT', 'Các thầy tế lễ mang hòm bia thì đứng giữa sông Giô-đanh, cho đến khi hoàn thành mọi điều mà Đức Giê-hô-va đã truyền cho Giô-suê nói với dân chúng, y như mọi điều mà Môi-se đã truyền cho Giô-suê; rồi dân chúng vội vã đi qua.'),
(5922, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 4, 11, 'OT', 'Khi toàn thể dân chúng đã đi qua hoàn toàn, thì hòm của Đức Giê-hô-va và các thầy tế lễ đi qua trước mặt dân sự.'),
(5923, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 4, 12, 'OT', 'Các con trai của Ru-bên, các con trai của Gát và phân nửa chi phái Ma-na-se đã đi qua, sẵn sàng chiến đấu, ở trước mặt các con trai của Ít-ra-en, y như điều Ma-se đã nói với họ.'),
(5924, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 4, 13, 'OT', 'Khoảng bốn mươi ngàn người lính tinh nhuệ đã đi qua trước mặt Đức Giê-hô-va để ra trận, đến các đồng bằng Giê-ri-cô.'),
(5925, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 4, 14, 'OT', 'Ngày ấy, Đức Giê-hô-va làm cho Giô-suê được trọng vọng trước mặt toàn thể Ít-ra-en; và họ kính sợ ông như đã kính sợ Môi-se trong suốt cả những ngày sống của ông.'),
(5926, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 4, 15, 'OT', 'Đức Giê-hô-va phán cùng Giô-suê rằng:'),
(5927, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 4, 16, 'OT', 'Hãy truyền lệnh cho các thầy tế lễ mang hòm bảng chứng cớ, để họ đi lên khỏi sông Giô-đanh.'),
(5928, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 4, 17, 'OT', 'Vì vậy, Giô-suê truyền lệnh cho các thầy tế lễ rằng: "Hãy lên khỏi sông Giô-đanh."'),
(5929, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 4, 18, 'OT', 'Khi các thầy tế lễ khiêng hòm giao ước của Đức Giê-hô-va bước lên khỏi giữa sông Giô-đanh, và lòng bàn chân các thầy tế lễ vừa chạm đến đất khô, thì nước sông Giô-đanh liền trở lại chỗ cũ, chảy tràn đầy mọi bờ như trước.'),
(5930, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 4, 19, 'OT', 'Dân chúng lên khỏi sông Giô-đanh vào ngày mùng mười tháng giêng, rồi đóng trại tại Ghinh-ganh, ở biên giới phía đông Giê-ri-cô.'),
(5931, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 4, 20, 'OT', 'Mười hai tảng đá mà họ đã lấy từ sông Giô-đanh, ông Giô-suê dựng lên tại Ghinh-ganh.'),
(5932, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 4, 21, 'OT', 'Người nói với các con trai của Y-sơ-ra-ên rằng: "Ngày mai, khi con cái các ngươi hỏi các tổ phụ chúng rằng: ''Những hòn đá này là gì?''"'),
(5933, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 4, 22, 'OT', 'Hãy cho con cái các ngươi biết, mà nói rằng: Y-sơ-ra-ên đã qua sông Giô-đanh này trên đất khô.'),
(5934, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 4, 23, 'OT', 'Vì Đức Giê-hô-va Đức Chúa Trời các ngươi đã làm cho nước sông Giô-đanh khô cạn trước mặt các ngươi cho đến khi các ngươi đi qua, cũng như điều Đức Giê-hô-va Đức Chúa Trời các ngươi đã làm cho Biển Đỏ, khi Ngài làm cho nó khô cạn trước mặt chúng tôi cho đến khi chúng tôi đi qua.'),
(5935, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 4, 24, 'OT', 'Để mọi dân trên đất biết tay Đức Giê-hô-va rất mạnh, hầu cho các ngươi kính sợ Đức Giê-hô-va Đức Chúa Trời các ngươi mọi ngày.'),
(5936, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 5, 1, 'OT', 'Khi mọi vua của dân Amôrì, là những người ở bên kia sông Giô-đanh về phía tây, và mọi vua của dân Ca-na-an, là những người ở gần biển, nghe tin Đức Giê-hô-va đã làm cho nước sông Giô-đanh khô cạn trước mặt dân Y-sơ-ra-ên cho đến khi chúng ta đi ngang qua, thì lòng chúng tan chảy ra, và không còn tinh thần nào trong chúng nữa, vì cớ dân Y-sơ-ra-ên.'),
(5937, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 5, 2, 'OT', 'Vào lúc ấy, Đức Giê-hô-va phán cùng Giô-suê rằng: "Hãy làm cho mình những con dao bằng đá, và hãy đi cắt bì cho con cái Y-sơ-ra-ên lần thứ hai."'),
(5938, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 5, 3, 'OT', 'Rồi Giô-suê làm những con dao bằng đá mài, và ông đã cắt bì cho con cái Ít-ra-en tại đồi của những người chưa cắt bì.'),
(5939, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 5, 4, 'OT', 'Và điều nầy là lý do tại sao Giô-suê đã làm phép cắt bì: toàn thể dân sự ra khỏi Ai Cập, những người nam, mọi người lính chiến, đều đã chết trong đồng vắng trên đường ra khỏi Ai Cập.'),
(5940, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 5, 5, 'OT', 'Vì toàn dân từng ra đi đều đã được cắt bì; nhưng mọi người sinh ra trong đồng vắng dọc đường khi họ ra khỏi Ai Cập thì chưa được cắt bì.'),
(5941, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 5, 6, 'OT', 'Vì bốn mươi năm trời, con cái Ít-ra-en đi trong đồng vắng, cho đến khi toàn thể dân sự là những người lính chiến ra khỏi Ai-cập đều đã chết hết, những kẻ không vâng theo tiếng Đức Giê-hô-va; là dân mà Đức Giê-hô-va đã thề không cho thấy đất nầy, tức là đất chảy sữa và mật ong, mà Đức Giê-hô-va đã thề ban cho tổ tiên chúng ta.'),
(5942, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 5, 7, 'OT', 'Còn con cái mà ông đã cho lớn lên thay thế chúng, thì chính những người ấy, Giô-suê đã làm phép cắt bì; vì chúng chưa được cắt bì, bởi họ đã không làm phép cắt bì cho chúng trong khi đi đường.'),
(5943, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 5, 8, 'OT', 'Khi toàn thể dân đã hoàn tất việc cắt bì, họ ở lại chỗ mình trong trại cho đến khi lành lại.'),
(5944, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 5, 9, 'OT', 'Đức Giê-hô-va phán cùng Giô-suê rằng: "Ngày nay Ta đã lăn đi khỏi các ngươi sự sỉ nhục của Ê-díp-tô." Vậy, người ta đặt tên nơi ấy là Ghinh-ganh, cho đến ngày nay.'),
(5945, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 5, 10, 'OT', 'Con dân Y-sơ-ra-ên đóng trại tại Ghinh-ganh, và giữ lễ Vượt Qua vào ngày mười bốn của tháng, lúc chiều tối, tại các đồng bằng Giê-ri-khô.'),
(5946, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 5, 11, 'OT', 'Họ ăn hoa màu cũ của đất ngay ngày hôm sau lễ Vượt Qua, tức là ngay trong ngày ấy, bánh không men và lúa rang.'),
(5947, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 5, 12, 'OT', 'Từ ngày hôm sau, manna ngừng rơi khi họ ăn lương thực từ đất đai; và dân Y-sơ-ra-ên không còn có manna nữa; họ ăn sản vật của đất Ca-na-an trong năm ấy.'),
(5948, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 5, 13, 'OT', 'Khi Giô-suê ở gần Giê-ri-khô, thì ngước mắt lên và thấy một người đang đứng đối diện mình, gươm đã rút ra trong tay. Giô-suê đi đến người ấy và nói: "Ông thuộc về chúng tôi hay thuộc về kẻ thù chúng tôi?"'),
(5949, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 5, 14, 'OT', 'Người đáp: "Không phải vậy, ta là tướng chỉ huy đạo quân của Đức Giê-hô-va, và bây giờ ta mới đến." Bấy giờ Giô-suê sấp mặt xuống đất, cúi lạy và thưa với Người: "Thưa chúa tôi, ông muốn nói gì với đầy tớ mình?"'),
(5950, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 5, 15, 'OT', 'Viên tướng của đạo binh Đức Giê-hô-va nói với Giô-suê: "Hãy cởi giày ngươi ra khỏi chân ngươi, vì nơi ngươi đang đứng là thánh." Và Giô-suê làm như vậy.'),
(5951, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 6, 1, 'OT', 'Thành Giê-ri-cô bị đóng chặt và khóa kỹ vì cớ con cái Y-sơ-ra-ên; không ai ra, cũng không ai vào.'),
(5952, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 6, 2, 'OT', 'Đức Giê-hô-va phán cùng Giô-suê rằng: Hãy xem, Ta đã phó thành Giê-ri-cô, vua nó và những chiến sĩ dũng mãnh vào tay ngươi.'),
(5953, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 6, 3, 'OT', 'Các ngươi, toàn thể những người chiến đấu, hãy đi vòng quanh thành một lượt. Các ngươi phải làm như vậy trong sáu ngày.'),
(5954, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 6, 4, 'OT', 'Bảy thầy tế lễ sẽ mang bảy chiếc kèn sừng chiên trước hòm giao ước; đến ngày thứ bảy, các ngươi phải đi quanh thành bảy lần, và các thầy tế lễ sẽ thổi các chiếc kèn.'),
(5955, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 6, 5, 'OT', 'Và sẽ xảy ra rằng, khi tiếng kèn ram vang dài lên, và các ngươi nghe tiếng tù và, thì toàn thể dân chúng sẽ thét vang một tiếng thét lớn; và tường thành của thành ấy sẽ sụp đổ xuống ngay chỗ nó đứng, rồi dân chúng sẽ lên, mỗi người tiến thẳng về phía trước mặt mình.'),
(5956, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 6, 6, 'OT', 'Vậy, Giô-suê, con trai của Nun, gọi các thầy tế lễ và nói với họ: "Hãy khiêng hòm giao ước, và bảy thầy tế lễ hãy mang bảy chiếc kèn ram trước hòm của Đức Giê-hô-va."'),
(5957, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 6, 7, 'OT', 'Họ nói với dân chúng: "Hãy đi qua và đi vòng quanh thành phố; và những người lính vũ trang sẽ đi trước hòm giao ước của Đức Giê-hô-va."'),
(5958, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 6, 8, 'OT', 'Khi Giô-suê nói với dân chúng xong, bảy thầy tế lễ mang bảy chiếc sừng ram đi trước mặt Đức Giê-hô-va, thổi các chiếc sừng; và hòm giao ước của Đức Giê-hô-va đi theo sau họ.'),
(5959, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 6, 9, 'OT', 'Các chiến binh đi trước các thầy tế lễ đang thổi những chiếc kèn; và toán đi sau cùng thì đi sau hòm giao ước, cứ vừa đi vừa thổi những chiếc kèn.'),
(5960, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 6, 10, 'OT', 'Và Giô-suê ra lệnh cho dân chúng rằng: "Các ngươi không được thét lên, không được để tiếng các ngươi vang ra, cũng không được để một lời nào ra khỏi miệng các ngươi, cho đến ngày ta bảo các ngươi: ''Hãy thét lên,'' thì lúc ấy các ngươi sẽ thét lên."'),
(5961, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 6, 11, 'OT', 'Vậy, rương giao ước của Đức Giê-hô-va đi vòng quanh thành một lần; rồi họ trở về trại và nghỉ đêm tại trại.'),
(5962, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 6, 12, 'OT', 'Giô-suê chổi dậy sớm vào buổi sáng, và các thầy tế lễ khiêng rương giao ước của Đức Giê-hô-va.'),
(5963, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 6, 13, 'OT', 'Bảy thầy tế lễ mang bảy chiếc tù và bằng sừng chiên đi trước hòm của Đức Giê-hô-va, cứ đi mà thổi tù và không ngừng; những người lính đi trước họ, còn toán đi sau cùng thì đi phía sau hòm của Đức Giê-hô-va, cứ tiếp tục đi và thổi tù và.'),
(5964, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 6, 14, 'OT', 'Ngày thứ hai, họ đi quanh thành một lần, rồi trở về trại; họ làm như vậy trong sáu ngày.'),
(5965, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 6, 15, 'OT', 'Vào ngày thứ bảy, họ chỗi dậy sớm khi vừa rạng đông, và đi quanh thành theo cách thức này bảy lần; chỉ riêng ngày đó, họ đi quanh thành bảy lần.'),
(5966, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 6, 16, 'OT', 'Đến lần thứ bảy, khi các thầy tế lễ thổi kèn, thì Giô-suê nói với dân chúng: "Hãy reo vang; vì Đức Giê-hô-va đã ban thành nầy cho các ngươi."'),
(5967, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 6, 17, 'OT', 'Thành ấy sẽ bị tiêu hủy, nó và mọi thứ trong đó đều thuộc về Đức Giê-hô-va; chỉ có Ra-háp, người đàn bà điếm, sẽ được sống, nàng và mọi người ở cùng nàng trong nhà, vì nàng đã giấu các sứ giả mà chúng tôi đã sai đi.'),
(5968, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 6, 18, 'OT', 'Nhưng các ngươi phải giữ mình khỏi điều bị nguyền rủa, hầu đừng lấy điều bị nguyền rủa, e các ngươi làm cho trại Ít-ra-en bị nguyền rủa và gây rối cho nó.'),
(5969, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 6, 19, 'OT', 'Mọi bạc, vàng, đồ đồng và sắt đều biệt riêng ra cho Đức Giê-hô-va; chúng sẽ được đưa vào kho tàng của Đức Giê-hô-va.'),
(5970, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 6, 20, 'OT', 'Dân chúng thét lên, và các thầy tế lễ thổi vào những chiếc kèn; khi dân chúng nghe tiếng kèn, họ liền thét lên một tiếng kêu lớn; lập tức, bức tường thành sụp đổ xuống ngay chỗ nó đứng, và dân chúng xông lên thành phố, mỗi người tiến thẳng trước mặt mình, rồi họ chiếm lấy thành phố.'),
(5971, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 6, 21, 'OT', 'Họ đã tiêu diệt tất cả những gì trong thành, từ người nam đến người nữ, từ người trẻ cho đến người già, và cả bò, chiên, lừa, bằng lưỡi gươm.'),
(5972, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 6, 22, 'OT', 'Nhưng Giô-suê nói với hai người đàn ông đã do thám vùng đất: "Hãy vào nhà người đàn bà điếm nầy, và đưa từ đó ra người đàn bà và tất cả những gì thuộc về bà, như các ngươi đã thề hứa với bà."'),
(5973, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 6, 23, 'OT', 'Các thanh niên là thám tử đi vào, đem Ra-háp, cha nàng, mẹ nàng, các anh em nàng và tất cả những gì thuộc về nàng ra ngoài, và họ đem tất cả các họ hàng của nàng ra, rồi đặt họ bên ngoài trại quân của Y-sơ-ra-ên.'),
(5974, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 6, 24, 'OT', 'Họ đốt thành bằng lửa, và mọi thứ ở trong đó; chỉ để riêng bạc, vàng, đồ đồng và sắt, thì họ gom vào kho tàng của nhà Đức Giê-hô-va.'),
(5975, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 6, 25, 'OT', 'Và Giô-suê cứu sống Rách-áp, người đàn bà điếm, cùng cả nhà cha nàng và tất cả những gì thuộc về nàng; nàng ở giữa vòng dân Y-sơ-ra-ên cho đến ngày nay, vì nàng đã giấu hai sứ giả mà Giô-suê sai đi do thám Giê-ri-cô.'),
(5976, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 6, 26, 'OT', 'Bấy giờ Giô-suê thề và nói rằng: "Đáng rủa sả thay người nào trước mặt Đức Giê-hô-va, người đó sẽ chỗi dậy xây cất thành Giê-ri-khô nầy; người ấy sẽ dùng con đầu lòng mình mà đặt nền thành, và dùng con út mình mà dựng cổng thành."'),
(5977, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 6, 27, 'OT', 'Đức Giê-hô-va ở cùng với Giô-suê, và tiếng đồn về người đã vang ra khắp cả đất.'),
(5978, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 7, 1, 'OT', 'Con cái Y-sơ-ra-ên đã phạm tội phản nghịch cùng Đức Giê-hô-va khi lấy điều bị rủa sả; A-chan, con trai của Ca-mi, con trai của Xáp-đi, con trai của Sê-rách, thuộc chi phái Giu-đa, đã lấy điều bị rủa sả ấy; và cơn thịnh nộ của Đức Giê-hô-va nổi phừng lên cùng con cái Y-sơ-ra-ên.'),
(5979, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 7, 2, 'OT', 'Giô-suê sai những người từ Giê-ri-cô đến A-i, là nơi gần Bê-thanh, ở phía đông Bê-thên, và bảo họ: "Hãy đi lên dò xét vùng đất nầy." Bấy giờ những người ấy đi lên và dò xét A-i.'),
(5980, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 7, 3, 'OT', 'Họ trở về cùng Giô-suê và nói với ông: "Đừng để toàn thể dân chúng lên; chỉ cần khoảng hai ngàn hoặc ba ngàn người lên để đánh thành Ai. Đừng làm cho toàn thể dân chúng phải vất vả đến nơi đó, vì chúng chỉ là một nhóm nhỏ."'),
(5981, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 7, 4, 'OT', 'Dân chúng đi lên từ trong dân sự đến nơi ấy khoảng ba ngàn người đàn ông, nhưng họ đã chạy trốn trước mặt những người của thành Ai.'),
(5982, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 7, 5, 'OT', 'Dân thành Ai đánh bại khoảng ba mươi sáu người trong số họ, rượt đuổi họ từ trước cổng cho đến các tảng đá, và đánh họ khi họ đang xuống dốc; vì thế lòng dân chúng tan ra như nước.'),
(5983, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 7, 6, 'OT', 'Và Giô-suê xé áo mình, rồi ngã sấp mặt xuống đất trước hòm bia của Đức Giê-hô-va cho đến chiều tối, cùng với các trưởng lão của Y-sơ-ra-ên, và họ lấy tro rắc trên đầu mình.'),
(5984, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 7, 7, 'OT', 'Bấy giờ Giô-suê nói: "Than ôi, thưa Chúa Giê-hô-va, tại sao Ngài lại khiến dân nầy qua sông Giô-đanh để trao chúng tôi vào tay người A-mô-rê mà tiêu diệt chúng tôi? Giá như chúng tôi bằng lòng ở lại bên kia sông Giô-đanh thì tốt biết mấy!"'),
(5985, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 7, 8, 'OT', 'Lạy Chúa, tôi phải nói gì đây, sau khi Y-sơ-ra-ên đã quay lưng chạy trốn trước mặt kẻ thù!'),
(5986, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 7, 9, 'OT', 'Các người Ca-na-an và mọi dân cư xứ nầy sẽ nghe biết chuyện nầy, họ sẽ bao vây chúng tôi lại, và tiêu diệt danh chúng tôi khỏi đất; vậy thì Ngài sẽ làm gì cho danh lớn của Ngài đây?'),
(5987, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 7, 10, 'OT', 'Đức Giê-hô-va phán cùng Giô-suê: "Hãy đứng dậy! Sao ngươi nằm sấp mặt xuống đất như thế này?"'),
(5988, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 7, 11, 'OT', 'Y-sơ-ra-ên đã phạm tội, và còn vi phạm giao ước Ta đã truyền cho họ: vì chúng đã lấy của vật bị rủa, lại còn trộm cắp, che giấu sự thật, và đặt những vật đó vào giữa các đồ riêng của chúng.'),
(5989, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 7, 12, 'OT', 'Vì vậy, con cái Ít-ra-en không thể đứng vững trước mặt các kẻ thù của chúng, mà phải quay lưng chạy trốn trước mặt các kẻ thù của chúng, vì chúng đã trở nên điều bị cấm; ta sẽ không còn ở cùng các ngươi nữa, nếu các ngươi không tiêu diệt điều bị cấm khỏi giữa các ngươi.'),
(5990, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 7, 13, 'OT', 'Hãy chỗi dậy, biệt riêng dân sự ra, và nói rằng: Hãy biệt riêng mình ra cho ngày mai; vì Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên phán như vầy: Có một vật bị nguyền rủa ở giữa ngươi; hỡi Y-sơ-ra-ên, ngươi không thể đứng trước mặt các kẻ thù ngươi cho đến khi các ngươi dẹp bỏ vật bị nguyền rủa khỏi giữa các ngươi.'),
(5991, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 7, 14, 'OT', 'Sáng ngày mai, các ngươi sẽ đến theo các chi phái mình; và chi phái nào mà Đức Giê-hô-va chọn, sẽ đến gần theo các gia tộc mình; và gia tộc nào mà Đức Giê-hô-va chọn, sẽ đến gần theo các gia đình; và gia đình nào mà Đức Giê-hô-va chọn, sẽ đến gần từng người một.'),
(5992, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 7, 15, 'OT', 'Người nào bị bắt gặp mang vật bị nguyền rủa sẽ bị thiêu trong lửa, cùng với mọi vật thuộc về người ấy; vì người ấy đã vi phạm giao ước của Đức Giê-hô-va và đã làm điều nhơ nhuốc trong Ít-ra-en.'),
(5993, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 7, 16, 'OT', 'Giô-suê chổi dậy sớm vào buổi sáng, đem Ít-ra-en đến theo các chi phái của họ; và chi phái Giu-đa bị bắt.'),
(5994, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 7, 17, 'OT', 'Đức Giê-hô-va khiến cho gia đình Giu-đa tiến lên; rồi Ngài bắt trúng gia đình Xa-rết. Ngài khiến cho gia đình Xa-rết từng người một tiến lên, và Xáp-đi bị bắt trúng.'),
(5995, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 7, 18, 'OT', 'Rồi người đưa từng người trong gia đình ra; và A-can, con trai của Ca-rơ-mi, con trai của Xáp-đi, con trai của Sê-rách, thuộc chi phái Giu-đa, bị bắt trọn.'),
(5996, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 7, 19, 'OT', 'Rồi Giô-suê nói với A-can: Hỡi con trai ta, hãy dâng vinh hiển cho Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en, và hãy tỏ lòng cảm tạ Ngài. Hãy nói cho ta biết ngay bây giờ ngươi đã làm điều gì; đừng giấu ta điều gì.'),
(5997, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 7, 20, 'OT', 'A-kan đáp lời Giô-suê và nói: Thật, tôi đã phạm tội cùng Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên, và tôi đã làm điều này, điều này nữa:'),
(5998, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 7, 21, 'OT', 'Tôi thấy trong chiến lợi phẩm một chiếc áo Ba-by-lôn đẹp, hai trăm séc-lơ bạc và một thỏi vàng nặng năm mươi séc-lơ; tôi thèm muốn và lấy đi; nầy, chúng được giấu trong đất ở giữa lều tôi, và bạc thì ở dưới nó.'),
(5999, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 7, 22, 'OT', 'Vậy Giô-suê sai các sứ giả đi, và họ chạy đến trại; nầy, vật đó giấu trong trại người, và bạc ở dưới nó.'),
(6000, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 7, 23, 'OT', 'Họ lấy những thứ đó ra khỏi giữa trại, đem đến cho Giô-suê và cho toàn thể con cái Ít-ra-en, rồi bày chúng ra trước mặt Đức Giê-hô-va.'),
(6001, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 7, 24, 'OT', 'Giô-suê dẫn A-can, con trai Sê-rách, cùng với bạc, áo choàng, miếng vàng hình lưỡi liềm, các con trai, các con gái, con bò đực, con lừa đực, chiên, trại của người, và mọi vật thuộc về người ấy, cùng với toàn thể Ít-ra-en đi theo, và họ đem tất cả lên thung lũng A-cô.'),
(6002, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 7, 25, 'OT', 'Rồi Giô-suê nói: "Sao ngươi làm rối loạn chúng ta? Hôm nay Đức Giê-hô-va sẽ làm rối loạn ngươi." Toàn thể Ít-ra-en ném đá người ấy, rồi thiêu người ấy và những người ấy bằng lửa, và ném đá những người ấy bằng những tảng đá.'),
(6003, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 7, 26, 'OT', 'Họ dựng lên trên người ấy một đống đá lớn cho đến ngày nay. Đức Giê-hô-va bèn thôi không còn nổi giận dữ nữa. Bởi vậy, người ta gọi nơi ấy là Thung lũng A-chor cho đến ngày nay.'),
(6004, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 1, 'OT', 'Đức Giê-hô-va phán cùng Giô-suê rằng: "Đừng sợ, cũng đừng kinh hãi; hãy đem theo ngươi tất cả dân sự chiến đấu, chỗi dậy, lên đường đến thành Ai. Nầy, Ta đã trao vào tay ngươi vua thành Ai, dân sự người, thành người và đất đai người."'),
(6005, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 2, 'OT', 'Hãy làm cho Ai và vua nó như ngươi đã làm cho Giê-ri-cô và vua nó; chỉ lấy chiến lợi phẩm và súc vật của nó làm của cướp cho các ngươi; hãy đặt phục kích cho thành phía sau nó.'),
(6006, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 3, 'OT', 'Vậy Giô-suê chỗi dậy, cùng với toàn thể quân đội, để tiến lên đánh thành Ai; và Giô-suê chọn ra ba vạn chiến sĩ dũng cảm, rồi sai họ đi trong đêm.'),
(6007, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 4, 'OT', 'Ông truyền lệnh cho họ rằng: "Nầy, các ngươi hãy phục kích thành, ở phía sau thành; đừng đi xa khỏi thành quá mức, và tất cả các ngươi phải sẵn sàng."'),
(6008, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 5, 'OT', 'Còn ta và toàn dân đi theo ta sẽ tiến gần về phía thành phố; và khi chúng ra đánh chúng ta như lần trước, thì ta sẽ chạy trốn trước mặt chúng.'),
(6009, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 6, 'OT', 'Họ sẽ ra đuổi theo chúng tôi cho đến khi chúng tôi lôi kéo họ ra khỏi thành; vì họ sẽ nói: "Chúng nó chạy trốn trước mặt chúng ta như lần trước"; nên chúng tôi sẽ chạy trốn trước mặt chúng nó.'),
(6010, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 7, 'OT', 'Các ngươi hãy chổi dậy khỏi nơi phục kích và chiếm lấy thành phố; vì Đức Giê-hô-va Đức Chúa Trời các ngươi sẽ trao nó vào tay các ngươi.'),
(6011, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 8, 'OT', 'Khi các ngươi chiếm được thành, phải thiêu hủy thành bằng lửa, theo như lời Đức Giê-hô-va đã phán. Này, ta đã truyền cho các ngươi.'),
(6012, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 9, 'OT', 'Vì vậy, Giô-suê sai phái họ đi; họ liền đi phục kích và ở lại giữa Bê-tên và A-i, về phía tây A-i. Còn Giô-suê thì đêm ấy ngủ lại giữa dân sự.'),
(6013, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 10, 'OT', 'Giô-suê chỗi dậy sớm vào buổi sáng, điểm danh dân sự, rồi cùng với các trưởng lão của Ít-ra-en đi lên phía trước dân sự đến thành Ai.'),
(6014, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 11, 'OT', 'Toàn thể dân chúng, tức những người lính chiến đi cùng ông, đều lên, đến gần, và tiến đến trước thành phố, rồi đóng trại phía bắc Ai; còn một thung lũng nằm giữa họ và Ai.'),
(6015, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 12, 'OT', 'Ông lấy khoảng năm ngàn người, và đặt họ phục kích giữa Bê-tên và Ai, về phía tây thành phố đó.'),
(6016, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 13, 'OT', 'Dân sự đặt toàn thể đạo quân ở phía bắc thành phố, và toán phục kích ở phía tây thành phố; còn Giô-suê thì đi đêm ấy vào giữa thung lũng.'),
(6017, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 14, 'OT', 'Khi vua thành Ai thấy điều đó, thì họ vội vàng trỗi dậy sớm, và những người trong thành ra đi nghênh chiến cùng Y-sơ-ra-ên, vua và toàn dân người, đến một nơi hẹn trước, phía trước đồng bằng; nhưng người không biết rằng có toán mai phục rình người ở phía sau thành.'),
(6018, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 15, 'OT', 'Giô-suê và toàn thể Ít-ra-en đã bị đánh bại trước mặt chúng, rồi chạy trốn theo con đường đồng vắng.'),
(6019, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 16, 'OT', 'Toàn thể dân chúng trong thành Ai đều được triệu tập để truy đuổi họ; họ truy đuổi theo sau Giô-suê, và bị lôi xa khỏi thành.'),
(6020, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 17, 'OT', 'Không còn một người nào ở Ai hoặc Bê-tên mà không ra đi theo sau Y-sơ-ra-ên; và họ để thành phố mở cửa, rồi đuổi theo sau Y-sơ-ra-ên.'),
(6021, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 18, 'OT', 'Đức Giê-hô-va phán cùng Giô-suê: "Hãy giơ ngọn giáo trong tay ngươi về phía thành Ai, vì ta sẽ trao nó vào tay ngươi." Bấy giờ Giô-suê giơ ngọn giáo trong tay mình về phía thành.'),
(6022, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 19, 'OT', 'Những người phục kích liền đứng dậy nhanh chóng khỏi nơi ẩn nấp của mình, chạy ngay khi ông giơ tay ra, xông vào thành, chiếm lấy nó, vội vã đốt thành lên bằng lửa.'),
(6023, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 20, 'OT', 'Dân thành Ai nhìn về phía sau, thấy khói thành bay lên trời, bèn mất hết sức chạy trốn qua bên này hay bên kia; còn dân chúng chạy trốn vào đồng vắng thì quay lại nghịch chiến với những kẻ đuổi theo.'),
(6024, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 21, 'OT', 'Khi Giô-suê và toàn thể Ít-ra-en thấy rằng toán phục kích đã chiếm được thành phố, và thấy khói thành phố bay lên, thì họ quay trở lại và đánh giết những người của Ai.'),
(6025, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 22, 'OT', 'Và những người kia thì từ trong thành đi ra nghênh chiến với chúng; và họ ở giữa dân Y-sơ-ra-ên, bên này một nhóm, bên kia một nhóm; rồi họ đánh bại chúng, đến nỗi không để sót lại một ai, cũng không để ai thoát được.'),
(6026, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 23, 'OT', 'Vua thành Ai bị bắt sống, và người ta điệu hắn đến Y-sô-sua.'),
(6027, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 24, 'OT', 'Khi người Y-sơ-ra-ên giết hết mọi người ở Ai ngoài đồng trống, trong sa mạc nơi chúng đuổi theo họ, và tất cả bọn chúng đều ngã xuống dưới lưỡi gươm cho đến khi bị tiêu diệt hoàn toàn, thì toàn thể Y-sơ-ra-ên trở lại Ai và đánh thành ấy bằng lưỡi gươm.'),
(6028, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 25, 'OT', 'Tất cả những người ngã xuống trong ngày ấy, từ người nam cho đến người nữ, là mười hai ngàn người, toàn thể những người của thành Ai.'),
(6029, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 26, 'OT', 'Giô-suê không rút lại tay mình, là tay đã giơ ra với ngọn giáo, cho đến khi dân Ai bị tiêu diệt hoàn toàn.'),
(6030, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 27, 'OT', 'Chỉ có súc vật và chiến lợi phẩm của thành ấy, dân Y-sơ-ra-ên đã lấy làm của riêng cho mình, theo lời Đức Giê-hô-va mà Ngài đã truyền cho Giô-suê.'),
(6031, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 28, 'OT', 'Giô-suê thiêu hủy thành Ai, và biến nó thành một đống đổ nát mãi mãi, một nơi hoang vu cho đến ngày nay.'),
(6032, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 29, 'OT', 'Vua thành Ai bị treo trên cây cho đến chiều tối; và khi mặt trời lặn, Giô-suê ra lệnh, người ta liền tháo xác hắn khỏi cây, ném xuống ngay lối vào cổng thành, rồi chất lên đó một đống đá lớn, còn tồn tại cho đến ngày nay.'),
(6033, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 30, 'OT', 'Bấy giờ, Giô-suê xây một bàn thờ cho Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên trên núi Ê-banh.'),
(6034, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 31, 'OT', 'Như Môi-se, đầy tớ của Đức Giê-hô-va, đã truyền cho con cái Ít-ra-en, theo như điều đã chép trong sách Luật pháp của Môi-se: một bàn thờ bằng những viên đá nguyên vẹn, mà không ai dùng dao sắt đụng đến; và họ dâng lên đó các của lễ thiêu cho Đức Giê-hô-va, cũng như tế các của lễ thù ân.'),
(6035, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 32, 'OT', 'Và ông đã chép ở đó trên các tảng đá bản sao của luật pháp Môi-se, mà ông đã chép ra trước mặt các con trai của Ít-ra-en.'),
(6036, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 33, 'OT', 'Toàn thể Y-sơ-ra-ên, các trưởng lão, các sĩ quan và các quan xét của họ đứng hai bên hòm giao ước, đối diện với các thầy tế lễ người Lê-vi đang khiêng hòm giao ước của Đức Giê-hô-va, cả người ngoại bang lẫn người bản xứ; một nửa dân chúng đối diện với núi Ghẹ-ri-zim, một nửa kia đối diện với núi Ê-banh, y như điều Môi-se, đầy tớ của Đức Giê-hô-va, đã truyền dạy trước đó, để chúc phước cho dân Y-sơ-ra-ên.'),
(6037, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 34, 'OT', 'Sau đó, ông đọc tất cả các lời của luật pháp, phần chúc phước và phần rủa sả, y như mọi điều đã chép trong sách luật pháp.'),
(6038, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 8, 35, 'OT', 'Không có một lời nào trong tất cả những điều Môi-se đã truyền mà Giô-suê không đọc trước toàn thể hội chúng Y-sơ-ra-ên, cùng các phụ nữ, con trẻ và những người ngoại kiều sống giữa họ.'),
(6039, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 9, 1, 'OT', 'Khi tất cả các vua ở bên kia sông Giô-đanh, trên vùng núi, trong các thung lũng, và khắp bờ biển lớn đối diện Li-băng, gồm người Hê-tít, người A-mô-rít, người Ca-na-an, người Phê-ri-xít, người Hê-vít và người Giê-bu-sít, nghe tin ấy,'),
(6040, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 9, 2, 'OT', 'Họ họp lại với nhau để chiến đấu cùng Giô-suê và cùng Ít-ra-en, đồng lòng một ý.'),
(6041, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 9, 3, 'OT', 'Dân cư Ghi-bê-ôn nghe được điều mà Giô-suê đã làm cho Giê-ri-cô và cho Ai.'),
(6042, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 9, 4, 'OT', 'Họ cũng hành động một cách xảo quyệt, đi và giả vờ như thể mình là các sứ giả; họ lấy các bao tải cũ kỹ chất lên các con lừa của mình, và các bầu rượu cũ, rách nát và vá lại.'),
(6043, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 9, 5, 'OT', 'Giày trên chân họ cũ kỹ và vá vá, quần áo mặc trên người cũng cũ kỹ, và mọi bánh mì dự trữ của họ đã khô và mốc meo.'),
(6044, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 9, 6, 'OT', 'Họ đi đến Giô-suê tại trại quân ở Ghinh-ganh, và nói với ông và với những người đàn ông Ít-ra-en: "Chúng tôi đã đến từ một xứ xa; vậy bây giờ hãy lập giao ước với chúng tôi."'),
(6045, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 9, 7, 'OT', 'Người của Y-sơ-ra-ên nói với người Hê-vít: "Biết đâu các ngươi lại ở giữa chúng tôi; vậy làm sao chúng tôi lập giao ước với các ngươi?"'),
(6046, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 9, 8, 'OT', 'Họ nói với Giô-suê: "Chúng tôi là đầy tớ của ngài." Giô-suê nói với họ: "Các ngươi là ai, và từ đâu đến?"'),
(6047, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 9, 9, 'OT', 'Chúng nói với ông: "Tôi tớ của ngài đến từ một xứ rất xa, vì danh của Đức Giê-hô-va Đức Chúa Trời của ngài; vì chúng tôi đã nghe tiếng đồn về Ngài, và tất cả những gì Ngài đã làm tại Ai-cập."'),
(6048, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 9, 10, 'OT', 'và tất cả những gì Ngài đã làm cho hai vua người Amôrít ở bên kia sông Giô-đanh, cho Si-hôn vua của Hết-bôn và cho Oùc vua của Ba-san, người ở tại Át-ta-rốt.'),
(6049, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 9, 11, 'OT', 'Các bậc trưởng lão của chúng tôi và toàn thể dân trong xứ chúng tôi đã nói với chúng tôi rằng: "Hãy mang lương thực theo trong hành trình, đi gặp họ và nói với họ: ''Chúng tôi là tôi tớ của các ông; vậy bây giờ, hãy lập giao ước với chúng tôi.''"'),
(6050, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 9, 12, 'OT', 'Bánh mì này là bánh chúng tôi đã mang theo, còn nóng khi rời nhà chúng tôi vào ngày chúng tôi khởi hành đến gặp các ông; nhưng bây giờ, hãy xem, nó đã khô và mốc meo.'),
(6051, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 9, 13, 'OT', 'Và đây là những bầu rượu mà chúng tôi đã đổ đầy khi còn mới, và nầy, chúng đã rách nát; và đây là áo xống và giày dép của chúng tôi, đã cũ mòn vì cớ cuộc hành trình rất dài.'),
(6052, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 9, 14, 'OT', 'Các người đàn ông lấy lương thực của chúng, nhưng không hỏi ý kiến của Đức Giê-hô-va.'),
(6053, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 9, 15, 'OT', 'Và Giô-suê lập hòa ước với họ, lập giao ước để cho họ sống, và các quan trưởng của hội chúng đã thề với họ.'),
(6054, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 9, 16, 'OT', 'Sau ba ngày kể từ khi lập giao ước với chúng, thì họ mới hay rằng những người này ở gần mình và đang cư ngụ giữa họ.'),
(6055, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 9, 17, 'OT', 'Con cái Y-sơ-ra-ên khởi hành và đến các thành của chúng vào ngày thứ ba. Các thành của chúng là Ghi-bê-ôn, Kê-phi-ra, Bê-e-rot và Ki-ri-át Giê-a-rim.'),
(6056, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 9, 18, 'OT', 'Dân Y-sơ-ra-ên không đánh giết họ, vì các quan trưởng của hội chúng đã chỉ Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên mà thề với họ. Nhưng toàn thể hội chúng đều than trách các quan trưởng.'),
(6057, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 9, 19, 'OT', 'Tất cả các quan trưởng nói với toàn thể hội chúng: Chúng tôi đã thề hứa với họ nhân danh Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên; vậy bây giờ chúng ta không thể động đến họ.'),
(6058, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 9, 20, 'OT', 'Điều nầy chúng ta sẽ làm cho họ: chúng ta sẽ để họ sống, hầu cho cơn thịnh nộ không đổ trên chúng ta, vì lời thề mà chúng ta đã chỉ Đức Giê-hô-va mà thề với họ.'),
(6059, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 9, 21, 'OT', 'Các quan trưởng nói với họ: "Hãy để họ sống, nhưng phải là người chặt củi và gánh nước cho toàn thể cộng đồng, như các quan trưởng đã nói với họ."'),
(6060, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 9, 22, 'OT', 'Ông Giô-suê gọi họ đến và nói với họ rằng: "Tại sao các ngươi đã lừa dối chúng ta, nói rằng: ''Chúng tôi ở rất xa các ông,'' trong khi các ngươi lại sống ngay giữa chúng tôi?"'),
(6061, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 9, 23, 'OT', 'Bây giờ, các ngươi bị rủa sả, và sẽ không ai trong các ngươi được thoát khỏi làm đầy tớ, chặt củi và gánh nước cho nhà Đức Chúa Trời ta.'),
(6062, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 9, 24, 'OT', 'Họ trả lời Giô-suê và nói: "Vì người ta đã thuật lại cho các đầy tớ của ngài, chính Đức Giê-hô-va Đức Chúa Trời của ngài đã truyền cho Môi-se, đầy tớ Ngài, phải ban cho các ngài toàn bộ đất nầy và tiêu diệt mọi dân cư trong đất khỏi trước mặt các ngài; nên chúng tôi rất sợ mạng sống mình vì cớ các ngài, và đã làm điều nầy."'),
(6063, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 9, 25, 'OT', 'Vậy bây giờ, chúng tôi đang ở trong tay ông; ông hãy làm cho chúng tôi điều gì ông cho là tốt và phải theo mắt ông nhìn.'),
(6064, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 9, 26, 'OT', 'Và ông đã làm cho họ như vậy, giải cứu họ khỏi tay con cái Y-sơ-ra-ên, khiến họ không bị giết.'),
(6065, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 9, 27, 'OT', 'Ngày ấy, Giô-suê bổ nhiệm họ làm người chặt củi và gánh nước cho hội chúng và cho bàn thờ Đức Giê-hô-va, cho đến ngày nay, tại nơi mà Ngài sẽ chọn.'),
(6066, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 1, 'OT', 'Khi A-đô-ni-xe-đéc, vua thành Giê-ru-sa-lem, nghe tin rằng Giô-suê đã chiếm lấy Ai và đã tiêu diệt thành đó như đã làm với Giê-ri-cô và vua thành ấy, cũng vậy, ông đã làm với Ai và vua thành ấy; và dân cư thành Ghi-bê-ôn đã giảng hòa với Y-sơ-ra-ên và đang sống giữa họ,'),
(6067, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 2, 'OT', 'Họ hết sức sợ hãi, vì Ghi-bê-ôn là một thành lớn, thuộc các thành của vua, và vì thành ấy lớn hơn Ai, và mọi người trong thành đều là những chiến sĩ mạnh mẽ.'),
(6068, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 3, 'OT', 'Vua A-đô-ni-xe-đéc của Giê-ru-sa-lem sai sứ đến Hô-ham, vua của Hếp-rôn, và đến Pi-ram, vua của Giạt-mút, và đến Gia-phia, vua của La-kích, và đến Đê-bia, vua của Ê-chôn, nói rằng:'),
(6069, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 4, 'OT', 'Hãy lên đây cùng tôi và giúp tôi đánh Ghi-bê-ôn, vì thành đã giảng hòa với Giô-suê và với con cái Y-sơ-ra-ên.'),
(6070, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 5, 'OT', 'Vậy nên năm vua người Amôrì, tức là vua Giê-ru-sa-lem, vua Hếp-bôn, vua Gia-mút, vua La-kích, và vua Ê-đôn, cùng hợp lại và đi lên, họ và toàn thể đạo quân của họ, rồi đóng trại trước Ghi-bê-ôn và gây chiến cùng thành ấy.'),
(6071, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 6, 'OT', 'Các người của Ghi-bê-ôn sai người đến gặp Giô-suê tại trại quân ở Gilgal, nói rằng: "Đừng để tay ông thôi việc khỏi các đầy tớ ông; hãy lên đây mau chóng, cứu và giúp chúng tôi, vì tất cả các vua người Amôrít sống trên núi đã nhóm lại nghịch cùng chúng tôi."'),
(6072, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 7, 'OT', 'Vậy Giô-suê đi lên từ Ghinh-ganh, người và toàn thể quân đội chiến đấu cùng người, và tất cả những chiến sĩ dũng cảm.'),
(6073, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 8, 'OT', 'Đức Giê-hô-va phán cùng Giô-suê: "Đừng sợ chúng nó, vì ta đã phó chúng nó vào tay ngươi; không một người nào trong chúng nó sẽ đứng vững trước mặt ngươi."'),
(6074, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 9, 'OT', 'Vì vậy, Giô-suê đến đột ngột với họ, đi lên từ Ghinh-ganh suốt đêm.'),
(6075, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 10, 'OT', 'Đức Giê-hô-va làm cho chúng hoảng loạn trước mặt Ít-ra-en, đánh chúng một đòn nặng tại Ghi-bê-ôn; rồi Ít-ra-en đuổi theo chúng dọc con đường lên Bết-hô-rôn, đánh chúng cho đến A-xê-ka và cho đến Mác-kê-đa.'),
(6076, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 11, 'OT', 'Khi chúng chạy trốn khỏi mặt dân Y-sơ-ra-ên, đang lúc xuống dốc gần Bê-thên Hô-rôn, thì Đức Giê-hô-va ném những tảng đá lớn từ trời xuống trên chúng cho đến A-xê-ka, và chúng chết; số người chết vì những tảng đá mưa đá nhiều hơn số người bị con cái Y-sơ-ra-ên giết bằng gươm.'),
(6077, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 12, 'OT', 'Bấy giờ, Giô-suê cầu Đức Giê-hô-va nói trong ngày Đức Giê-hô-va trao người A-mô-rít ra trước mặt con cái Ít-ra-en; và người nói trước mặt Ít-ra-en: "Mặt Trời, hãy dừng lại trên Ghíp-bôn; và Mặt Trăng, trên thung lũng A-ya-lôn."'),
(6078, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 13, 'OT', 'Mặt trời đứng yên và mặt trăng dừng lại cho đến khi dân sự báo thù được kẻ thù mình. Há điều đó không được chép trong sách Y-xơ-rơ sao? Vậy nên mặt trời đứng giữa trời và không vội lặn, như trọn một ngày dài.'),
(6079, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 14, 'OT', 'Chưa từng có ngày nào như ngày ấy trước hay sau đó, khi Đức Giê-hô-va nghe tiếng một người; vì Đức Giê-hô-va chiến đấu cho Ít-ra-en.'),
(6080, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 15, 'OT', 'Rồi Giô-suê trở về, và toàn thể Y-sơ-ra-ên cùng với người, đến trại quân ở Ghinh-ganh.'),
(6081, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 16, 'OT', 'Năm vị vua ấy đã trốn chạy, và ẩn náu trong một cái hang ở Makkêđa.'),
(6082, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 17, 'OT', 'Và người ta báo cho Giô-suê rằng: Năm vị vua đang ẩn nấp trong một cái hang ở Mạt-kê-đa.'),
(6083, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 18, 'OT', 'Và Giô-suê nói: "Hãy lăn những tảng đá lớn bịt kín cửa hang, rồi đặt người canh giữ ở đó."'),
(6084, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 19, 'OT', 'Và các ngươi, đừng đứng dừng lại; hãy đuổi theo các kẻ thù của mình, đánh tan họ, đừng để họ vào các thành mình; vì Đức Giê-hô-va Đức Chúa Trời các ngươi đã giao họ vào tay các ngươi.'),
(6085, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 20, 'OT', 'Khi Giô-suê và các con trai Y-sơ-ra-ên đã đánh bại chúng bằng một trận đánh lớn đến mức tận cùng, thì những kẻ sót lại từ chúng đã trốn vào các thành có vách thành.'),
(6086, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 21, 'OT', 'Toàn thể dân chúng trở về trại, đến cùng Giô-suê tại Mạt-kê-đa, trong sự bình an; không ai giơ môi nói một lời chống lại dân Y-sơ-ra-ên.'),
(6087, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 22, 'OT', 'Rồi Giô-suê nói: "Hãy mở miệng hang và dẫn năm vị vua ra cho tôi từ trong hang."'),
(6088, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 23, 'OT', 'Họ làm như vậy, và dẫn năm vị vua ấy ra khỏi hang cho ông, tức vua Giê-ru-sa-lem, vua Hếp-rôn, vua Gia-mút, vua La-ki, và vua Ê-chôn.'),
(6089, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 24, 'OT', 'Khi người ta dẫn những vị vua ấy ra cho Giô-suê, thì Giô-suê gọi tất cả những người nam Ít-ra-en và nói với các viên chỉ huy quân sự đi cùng ông rằng: "Hãy lại gần, đặt chân các ngươi trên cổ những vị vua nầy." Bèn có những người lại gần và đặt chân trên cổ các vị vua ấy.'),
(6090, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 25, 'OT', 'Và Giô-suê nói với họ: "Đừng sợ, cũng đừng kinh hoàng; hãy mạnh dạn và can đảm, vì Đức Giê-hô-va sẽ làm như vậy cho tất cả các kẻ thù của các ngươi mà các ngươi phải chiến đấu."'),
(6091, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 26, 'OT', 'Sau đó, Giô-suê ra tay đánh bại chúng, giết chúng, và treo chúng trên năm cây; và chúng bị treo trên các cây cho đến chiều tối.'),
(6092, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 27, 'OT', 'Khi mặt trời lặn, Giô-suê ra lệnh, người ta liền tháo năm vua khỏi các cây, ném chúng vào hang mà chúng đã từng trốn, và đặt những tảng đá lớn ngay cửa hang; chúng còn ở đó cho đến chính ngày nay.'),
(6093, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 28, 'OT', 'Ngày ấy, Giô-suê chiếm lấy Ma-kết, đánh thành ấy bằng lưỡi gươm, và đem vua thành ấy ra tiêu diệt, cùng với mọi sinh mạng ở trong thành; không để sót một ai. Người xử với vua Ma-kết như đã xử với vua Giê-ri-cô.'),
(6094, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 29, 'OT', 'Rồi Giô-suê và toàn thể Ít-ra-en đi cùng ông từ Mác-kê-đa đến Lib-na, và chiến đấu chống lại Lib-na.'),
(6095, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 30, 'OT', 'Đức Giê-hô-va cũng trao thành ấy và vua nó vào tay Y-sơ-ra-ên; người đánh thành ấy bằng lưỡi gươm, cùng mọi sinh mạng ở trong thành; người không để sót lại một ai trong thành; và người xử với vua thành ấy như cách người đã xử với vua Giê-ri-cô.'),
(6096, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 31, 'OT', 'Rồi Giô-suê và toàn thể Ít-ra-en cùng đi với ông từ Lib-na đến La-ki, đóng trại chống lại thành ấy và giao chiến với nó.'),
(6097, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 32, 'OT', 'Đức Giê-hô-va đã trao Lakis vào tay Ít-ra-en, và họ chiếm lấy nó vào ngày thứ hai, đánh giết nó bằng lưỡi gươm cùng mọi sinh mạng ở trong nó, y như mọi điều ông đã làm cho Lib-na.'),
(6098, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 33, 'OT', 'Bấy giờ, Horam, vua của Gezer, đi lên để giúp đỡ La-kích; và Giô-suê đánh bại ông cùng dân của ông, cho đến nỗi không còn sót lại ai thuộc về ông.'),
(6099, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 34, 'OT', 'Rồi Giô-suê và toàn thể Ít-ra-en đi cùng người từ La-ki đến Éc-lôn, đóng trại chống lại thành nầy và giao chiến với nó.'),
(6100, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 35, 'OT', 'Họ chiếm lấy thành ấy trong ngày đó, đánh giết nó và mọi sinh mạng ở trong thành ấy bằng lưỡi gươm; họ tiêu diệt hoàn toàn trong ngày đó, y như mọi điều ông đã làm cho La-kích.'),
(6101, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 36, 'OT', 'Giô-suê và toàn thể Ít-ra-en cùng đi lên từ Ê-ghôn đến Hếp-rôn, và họ chiến đấu chống lại thành ấy.'),
(6102, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 37, 'OT', 'Họ chiếm lấy thành, đánh thành ấy bằng lưỡi gươm, cùng với vua thành ấy, và tất cả các thành thuộc nó, và mọi người sống ở đó; họ không để lại ai sót lại, y như mọi điều họ đã làm cho Ê-ghôn; họ tiêu diệt thành ấy hoàn toàn, cùng với mọi người sống ở đó.'),
(6103, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 38, 'OT', 'Rồi Giô-suê trở về, và toàn thể Ít-ra-en cùng với người đến Đê-bia, và chiến đấu chống lại thành ấy.'),
(6104, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 39, 'OT', 'Rồi họ chiếm lấy thành ấy cùng vua thành, và tất cả các thành thuộc vùng ấy; họ đánh giết mọi người trong đó bằng lưỡi gươm, và tiêu diệt hoàn toàn mọi sinh mạng ở đó, không để lại ai; y như điều ông đã làm cho Hếp-rôn, cũng vậy ông đã làm cho Đê-bia và vua thành ấy; cũng như điều ông đã làm cho Lib-na và vua thành ấy.'),
(6105, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 40, 'OT', 'Giô-suê đánh bại toàn bộ vùng đất miền núi, miền Nam, miền đồng bằng và sườn đồi, cùng với tất cả các vua của chúng; người không để sót ai, mà hủy diệt hoàn toàn mọi sinh mạng, y như điều Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en đã truyền dạy.'),
(6106, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 41, 'OT', 'Rồi Giô-suê đánh bại chúng từ Ki-đết cho đến Ga-xa, cùng toàn bộ vùng đất Gô-sen cho đến Ghi-bê-ôn.'),
(6107, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 42, 'OT', 'Toàn thể các vua nầy và xứ của họ, Giô-suê đã chiếm lấy trong một lần duy nhất, vì Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en đã chiến đấu cho Ít-ra-en.'),
(6108, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 10, 43, 'OT', 'Rồi Giô-suê trở về, và toàn thể Ít-ra-en cùng đi với ông, đến trại tại Ghinh-ganh.'),
(6109, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 11, 1, 'OT', 'Khi Gia-bin, vua thành Ha-xô, nghe tin ấy, thì sai sứ đến Giô-báp, vua Ma-đôn, và đến vua Si-mê-ron, và đến vua A-cha-ph.'),
(6110, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 11, 2, 'OT', 'và các vua ở phía bắc vùng núi, và các vùng đồng bằng về phía nam Kinh-nê-rot, và trong thung lũng, và các miền phía tây Đô-rơ dọc theo biển.'),
(6111, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 11, 3, 'OT', 'Người Ca-na-an ở phương đông và phương tây, người A-mô-rít, người Hê-th, người Phê-ri-xi, người Yê-bu-xi trên vùng núi, và người Hí-vi dưới chân Hẹc-môn, trong đất Mích-pe.'),
(6112, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 11, 4, 'OT', 'Họ cùng toàn thể đạo quân họ kéo ra theo họ, dân đông như cát ven biển về số lượng, cùng với ngựa và xe chiến xa rất nhiều.'),
(6113, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 11, 5, 'OT', 'Các vua ấy đều họp lại, đến cùng nhau và đóng trại gần các vùng nước của Mê-rom, để đánh nhau với Y-sơ-ra-ên.'),
(6114, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 11, 6, 'OT', 'Đức Giê-hô-va phán cùng Giô-suê rằng: "Đừng sợ chúng nó, vì ngày mai vào giờ này, Ta sẽ phó tất cả chúng nó bị giết trước mặt Ít-ra-en; ngươi phải chặt gân ngựa của chúng nó và đốt các xe chiến của chúng nó bằng lửa."'),
(6115, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 11, 7, 'OT', 'Rồi Giô-suê và toàn thể quân đội kéo đến chống lại chúng, bất thần tiến đánh tại các vùng nước của Ma-rôn; và họ xông vào chúng.'),
(6116, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 11, 8, 'OT', 'Đức Giê-hô-va đã giao họ vào tay Y-sơ-ra-ên, và họ đánh bại chúng, đuổi theo đến Xi-đôn lớn, đến Mít-rê-phốt-ma-im, và đến thung lũng Mít-phe về hướng đông; họ đánh chúng cho đến khi không còn sót lại một ai trong chúng.'),
(6117, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 11, 9, 'OT', 'Và Giô-suê làm cho chúng như Đức Giê-hô-va đã phán dạy người: người cắt gân ngựa của chúng, và đốt các xe chiến của chúng bằng lửa.'),
(6118, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 11, 10, 'OT', 'Bấy giờ, Giô-suê trở lại, chiếm lấy Ha-xô và đánh giết vua nó bằng gươm; vì Ha-xô trước kia là thành đứng đầu trong các vương quốc nầy.'),
(6119, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 11, 11, 'OT', 'Họ đánh giết mọi sinh mạng ở đó bằng lưỡi gươm, hoàn toàn tiêu diệt, không còn sót lại một hơi thở nào; và họ đã thiêu cháy Ha-xô bằng lửa.'),
(6120, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 11, 12, 'OT', 'Giô-suê chiếm lấy mọi thành của các vua ấy và mọi vua của chúng, đánh chúng bằng lưỡi gươm, tiêu diệt chúng hoàn toàn, y như Môi-se, đầy tớ của Đức Giê-hô-va, đã truyền dạy.'),
(6121, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 11, 13, 'OT', 'Các thành còn lại đứng vững trên đồi của mình thì Y-sơ-ra-ên không thiêu hủy, ngoại trừ Ha-xô, chỉ thành ấy Giô-suê đã thiêu hủy.'),
(6122, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 11, 14, 'OT', 'Toàn bộ chiến lợi phẩm của các thành nầy và súc vật, con cái Y-sơ-ra-ên đã lấy làm của cướp cho mình; nhưng mọi người, họ đánh bằng lưỡi gươm cho đến khi tiêu diệt chúng hoàn toàn, không để lại một hơi thở nào.'),
(6123, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 11, 15, 'OT', 'Như Đức Giê-hô-va đã truyền dặn Môi-se tôi tớ Ngài, thì Môi-se cũng truyền dặn Giô-suê như vậy; và Giô-suê làm y như thế, không bỏ sót điều gì trong tất cả những điều Đức Giê-hô-va đã truyền dặn Môi-se.'),
(6124, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 11, 16, 'OT', 'Vậy Giô-suê chiếm lấy toàn cõi đất ấy, gồm các vùng núi, toàn vùng Nam Cương, toàn bộ đất Gô-sen, các đồng bằng, các vùng đồng trũng, núi của Y-sơ-ra-ên và các vùng đất thấp của nó.'),
(6125, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 11, 17, 'OT', 'Từ ngọn núi Halak, nơi lên đến Seir, cho đến Ba-al Gad trong thung lũng Li-băng, dưới chân núi Hẹt-môn; và tất cả các vua của chúng, người ấy bắt lấy, đánh bại và giết chết.'),
(6126, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 11, 18, 'OT', 'Giô-suê đã đánh các vua ấy trong các cuộc chiến tranh suốt một thời gian dài.'),
(6127, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 11, 19, 'OT', 'Không có thành nào đầu hàng cho con cái Y-sơ-ra-ên, ngoại trừ người Hê-vi, các dân cư ở Ghi-bê-ôn; mọi thành khác, họ chiếm lấy bằng chiến tranh.'),
(6128, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 11, 20, 'OT', 'Vì chính Đức Giê-hô-va khiến lòng chúng trở nên cứng cỏi, để chúng xông vào chiến đấu cùng Y-sơ-ra-ên, hầu cho chúng bị tiêu diệt hoàn toàn, không được tỏ lòng thương xót; để chúng bị tiêu diệt, y như Đức Giê-hô-va đã truyền cho Môi-se.'),
(6129, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 11, 21, 'OT', 'Bấy giờ, Giô-suê đến và tiêu diệt những người A-na-kim khỏi vùng núi, khỏi Hếp-rôn, khỏi Đê-bích, khỏi A-náp, và khỏi mọi núi xứ Giu-đa, cùng mọi núi xứ Ít-ra-ên; Giô-suê đã hủy diệt hoàn toàn chúng cùng các thành của chúng.'),
(6130, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 11, 22, 'OT', 'Không còn sót lại người nào thuộc dòng giống A-nác trong đất của con cái Y-sơ-ra-ên; chỉ còn lại ở Gát, ở A-xa và ở A-xốt.'),
(6131, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 11, 23, 'OT', 'Vì vậy, Giô-suê chiếm lấy toàn bộ xứ, đúng như Đức Giê-hô-va đã phán với Môi-se; và Giô-suê đã phân chia xứ ấy cho Y-sơ-ra-ên làm sản nghiệp, theo sự chia sẻ của các chi phái. Rồi xứ được yên nghỉ, không còn chiến tranh nữa.'),
(6132, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 12, 1, 'OT', 'Còn đây là các vua của đất mà con cái Ít-ra-en đã đánh bại và chiếm lấy đất của chúng, ở bên kia sông Giô-đanh về hướng đông mặt trời mọc, từ sông A-rôn cho đến núi Hẹc-môn, và toàn thể vùng đồng bằng về phía đông.'),
(6133, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 12, 2, 'OT', 'Si-ho, vua dân A-mô-rít, ở tại Hết-bôn, trị vì từ A-rô-er, là nơi bên bờ sông Ác-nôn, và giữa dòng sông, và nửa phần đất Ghi-lê-át, cho đến sông Y-bốc, là ranh giới của con cháu Am-môn.'),
(6134, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 12, 3, 'OT', 'và đồng bằng cho đến Biển Kinneroth về phía đông, và cho đến Biển Đồng Bằng, tức Biển Mặn về phía đông, theo con đường đến Bết-Giê-si-mốt; và từ phía nam, dưới chân A-sốt-Pít-ga.'),
(6135, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 12, 4, 'OT', 'Và phần đất giáp ranh của Óc, vua xứ Ba-san, thuộc về những người còn sót lại của dân Rê-pha-im, là người ở tại Ách-ta-rot và Ê-đrê-i,'),
(6136, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 12, 5, 'OT', 'và cai trị trên núi Hẹc-môn, tại Xa-cha, và khắp Ba-san cho đến ranh giới của người Ghê-sua-rít và người Ma-a-khat, và nửa phần Ga-la-át, ranh giới của Si-hôn, vua Hết-bôn.'),
(6137, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 12, 6, 'OT', 'Môi-se, tôi tớ của Đức Giê-hô-va, và các con trai Y-sơ-ra-ên đã đánh bại chúng; và Môi-se, tôi tớ của Đức Giê-hô-va, đã ban đất ấy làm sản nghiệp cho người Ru-bên, cho người Ga-đi, và cho phân nửa chi phái Ma-na-se.'),
(6138, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 12, 7, 'OT', 'Còn đây là các vua của đất mà Giô-suê và con cái Ít-ra-en đã đánh bại, bên kia sông Giô-đanh về hướng tây, từ Ba-anh-Gát trong thung lũng Li-ban cho đến núi Ha-lác, nơi lên đến Xi-rát; và Giô-suê đã ban đất ấy cho các chi phái Ít-ra-en làm sản nghiệp, tùy theo sự phân chia của từng chi phái.'),
(6139, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 12, 8, 'OT', 'trên núi, trong các thung lũng, trên đồng bằng, trong các vùng đất khô cằn, trong đồng vắng, và miền Nam; dân Hê-tít, dân A-mô-rít, dân Ca-na-an, dân Phê-ri-xít, dân Hí-vít, và dân Giê-bu-xít.'),
(6140, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 12, 9, 'OT', 'Vua của Giê-ri-cô, một người; vua của Ai, là thành gần Bê-thên, một người.'),
(6141, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 12, 10, 'OT', 'Vua của Giê-ru-sa-lem, một người; vua của Hếp-rôn, một người;'),
(6142, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 12, 11, 'OT', 'Vua của Y-rơ-mút, một người; vua của La-ki, một người.'),
(6143, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 12, 12, 'OT', 'Vua của Éc-lôn, một vị; vua của Kê-xe, một vị;'),
(6144, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 12, 13, 'OT', 'Vua của Dê-bir, một vị; vua của Ghê-đe, một vị;'),
(6145, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 12, 14, 'OT', 'Vua của Hô-rơ-ma, một người; vua của A-rát, một người.'),
(6146, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 12, 15, 'OT', 'Vua của Lib-na một người; vua của A-đu-lam một người.'),
(6147, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 12, 16, 'OT', 'Vua của Makkêđa, một vị; vua của Bê-thên, một vị;'),
(6148, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 12, 17, 'OT', 'Vua của Táp-pha, một người; vua của Hép-hơ, một người;'),
(6149, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 12, 18, 'OT', 'Vua của A-phéc, một vị; vua của La-sa-rôn, một vị;'),
(6150, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 12, 19, 'OT', 'Vua của Ma-đôn, một người; vua của Ha-xô, một người.'),
(6151, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 12, 20, 'OT', 'Vua của Si-mê-rôn Mê-rôn, một người; vua của A-cháp, một người;'),
(6152, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 12, 21, 'OT', 'Vua của Ta-nanh, một người; vua của Mê-gi-đô, một người;'),
(6153, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 12, 22, 'OT', 'Vua của Kê-đe, một người; vua của Giô-kê-nê-am tại Cạt-mên, một người.'),
(6154, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 12, 23, 'OT', 'Vua của Đô-rơ, tại bờ biển Đô-rơ, một vua; vua của các dân tộc tại Ghích-ganh, một vua.'),
(6155, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 12, 24, 'OT', 'Vua của thành Tiếc-xa, một vị; tất cả các vua là ba mươi mốt vị.'),
(6156, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 1, 'OT', 'Giô-suê đã về già, tuổi tác cao cả; và Đức Giê-hô-va phán cùng người rằng: "Ngươi đã về già, tuổi tác cao cả, và còn rất nhiều đất phải chiếm lấy."'),
(6157, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 2, 'OT', 'Đây là đất còn sót lại: toàn bộ các vùng duyên hải của người Phi-li-tin và toàn bộ đất của người Ghê-sua-ri,'),
(6158, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 3, 'OT', 'Từ sông Sihor, nằm trước mặt Ai Cập, cho đến ranh giới Éc-rôn về phía bắc, kể về người Ca-na-an; năm lãnh chúa của dân Phi-li-tin, gồm người Ga-xa, người Ách-đốt, người Ét-ki-nôn, người Gát, và người Ê-cơ-rôn, cùng với dân A-vi.'),
(6159, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 4, 'OT', 'Từ miền nam, toàn bộ đất của người Ca-na-an, và hang Mê-a-ra gần người Xi-đôn, cho đến A-phê-ka, đến ranh giới của người A-mô-rít.'),
(6160, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 5, 'OT', 'Và vùng đất của người Ghíp-lít, và toàn thể Li-băng về phía mặt trời mọc, từ Ba-anh-Gát dưới chân núi Hẹc-môn cho đến nơi dẫn vào Ha-mát.'),
(6161, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 6, 'OT', 'Tất cả những người sống ở vùng núi từ Li-băng cho đến Mích-rê-phốt-ma-im, và toàn thể người Xi-đôn, chính Ta sẽ đuổi họ khỏi mặt con cái Y-sơ-ra-ên; chỉ phần ngươi phải chia đất ấy ra bằng thăm cho dân Y-sơ-ra-ên làm sản nghiệp, như Ta đã truyền cho ngươi.'),
(6162, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 7, 'OT', 'Bây giờ, hãy chia đất nầy làm sản nghiệp cho chín chi phái và phân nửa chi phái Ma-na-se.'),
(6163, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 8, 'OT', 'Các chi phái Ru-bên và Ga-đi đã nhận lãnh phần sản nghiệp mà Môi-se ban cho họ, bên kia sông Giô-đanh về hướng đông, y như điều Môi-se, đầy tớ của Đức Giê-hô-va, đã ban cho họ.'),
(6164, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 9, 'OT', 'Từ A-rô-er, là thành ở bên bờ sông A-r-non, và thành ở giữa dòng sông, cùng toàn thể đồng bằng từ Mê-đê-ba cho đến Đíp-bôn.'),
(6165, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 10, 'OT', 'và tất cả các thành của Si-hôn, vua dân A-mô-rít, người đã trị vì tại Hết-bôn, cho đến ranh giới của con cái Am-môn;'),
(6166, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 11, 'OT', 'Và đất Ga-la-át, và vùng biên giới của người Ghê-sua và Ma-a-khat, và toàn bộ núi Hẹt-môn, và toàn bộ Ba-san cho đến Xanh-ca.'),
(6167, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 12, 'OT', 'Toàn bộ vương quốc của Oùc tại Ba-san, người đã trị vì tại Ách-ta-rốt và Ê-đơ-rê; người này là kẻ còn sót lại của phần sót lại của người Rê-pha-im; Môi-se đã đánh bại họ và chiếm lấy đất đai của họ.'),
(6168, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 13, 'OT', 'Con cái Y-sơ-ra-ên không trục xuất người Ghê-sua-rít và người Ma-a-cát; người Ghê-sua-rít và người Ma-a-cát vẫn cư trú giữa vòng Y-sơ-ra-ên cho đến ngày nay.'),
(6169, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 14, 'OT', 'Chỉ về chi phái Lê-vi, ông không ban sản nghiệp; các lễ thiêu của Đức Giê-hô-va Đức Chúa Trời Ít-ra-en là sản nghiệp của họ, như Ngài đã phán về họ.'),
(6170, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 15, 'OT', 'Môi-se đã ban cho chi phái con cháu Ru-bên theo các họ hàng của họ.'),
(6171, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 16, 'OT', 'Giới hạn của họ bắt đầu từ A-rô-ẹt, nằm bên bờ sông A-r-non, và thành phố ở giữa dòng sông, cùng toàn thể vùng đồng bằng gần Mê-đê-ba.'),
(6172, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 17, 'OT', 'Hes-bôn và tất cả các thành thuộc đồng bằng của nó; Đi-bôn, Ba-mốt Ba-al, và Bê-th Ba-al Mê-on.'),
(6173, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 18, 'OT', 'Và Ya-ha-xa, và Kê-đê-mốt, và Mê-phaa.'),
(6174, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 19, 'OT', 'Và Ki-ri-a-tha-im, và Síp-ma, và Xê-rết-sa-ha ở trên núi trong thung lũng.'),
(6175, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 20, 'OT', 'và Bết-Pê-ô, và A-sốt-Pít-ga, và Bết-Y-si-mốt,'),
(6176, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 21, 'OT', 'Tất cả các thành thuộc đồng bằng và toàn bộ vương quốc của Si-hôn, vua dân Amôrị, người đã trị vì tại Hết-bôn, là người Môi-se đã đánh bại cùng với các lãnh tụ của Ma-đi-an, tức Ê-vi, Rê-kem, Xua, Hu và Rê-ba, các hoàng tử của Si-hôn, những người cư ngụ trong xứ.'),
(6177, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 22, 'OT', 'Dân Y-sơ-ra-ên đã giết Ba-la-am, con trai của Bê-ô, là thầy bói, bằng gươm, cùng những người bị chúng giết.'),
(6178, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 23, 'OT', 'Giới hạn của con cái Ru-bên là sông Giô-đanh và ranh giới của nó. Đây là phần sản nghiệp của con cái Ru-bên theo các họ hàng họ, gồm các thành và các làng mạc của chúng.'),
(6179, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 24, 'OT', 'Môi-se ban cho chi phái Gát, cho con cháu Gát theo các họ hàng của họ.'),
(6180, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 25, 'OT', 'Giới hạn của họ gồm có Ja-ze và tất cả các thành của Ga-la-át, và phân nửa xứ con cái Am-môn, cho đến A-rô-e thuộc về phía đối diện của Ra-ba.'),
(6181, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 26, 'OT', 'Từ Hes-bôn cho đến Ra-mát Mi-xpê, và Bê-tô-ním; từ Ma-ha-na-im cho đến ranh giới Đê-biếc.'),
(6182, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 27, 'OT', 'và trong thung lũng, Bết-ha-ram, Bết-Nim-ra, Su-cốt và Xáp-thon, phần còn lại của vương quốc Si-hôn, vua Hết-bôn, sông Giô-đanh và ranh giới của nó cho đến tận bờ Biển Kinh-nê-rết bên kia sông Giô-đanh về hướng đông.'),
(6183, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 28, 'OT', 'Đây là sản nghiệp của các con trai Gát theo các họ hàng của họ, các thành phố và các làng mạc thuộc về các thành ấy.'),
(6184, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 29, 'OT', 'Môi-se ban phần đất cho phân nửa chi phái Ma-na-se; và phần đất của phân nửa chi phái con cháu Ma-na-se theo các họ hàng của họ là như vậy.'),
(6185, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 30, 'OT', 'Giáp ranh của chúng gồm từ Ma-ha-na-im, toàn thể Ba-san, toàn bộ vương quốc của Óc, vua Ba-san, và tất cả các thành của Gia-ir, là những thành thuộc Ba-san, gồm sáu mươi thành.'),
(6186, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 31, 'OT', 'Nửa đất Ga-la-át, A-sát-rốt và Ê-đrê-i, các thành thuộc vương quốc của Oùc tại Ba-san, thuộc về các con trai của Ma-kích, con trai của Ma-na-se, và thuộc về nửa chi phái của các con trai Ma-kích, theo các họ hàng của họ.'),
(6187, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 32, 'OT', 'Đây là các vùng đất mà Môi-se đã phân chia để chia làm cơ nghiệp tại các đồng bằng của Mô-áp, bên kia sông Giô-đanh, về phía đông của Giê-ri-cô.'),
(6188, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 13, 33, 'OT', 'Còn về chi phái Lê-vi, Môi-se không ban cho họ phần sản nghiệp nào; Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en là sản nghiệp của họ, như Ngài đã phán cùng họ.'),
(6189, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 14, 1, 'OT', 'Các vùng đất mà con cháu Ít-ra-en đã nhận được trong xứ Ca-na-an, mà Ê-lê-a-xa thầy tế lễ, Giô-suê con trai của Nun và các tộc trưởng các chi phái con cháu Ít-ra-en đã phân chia để nhận làm sản nghiệp,'),
(6190, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 14, 2, 'OT', 'Theo sự chỉ định bằng lots của Đức Giê-hô-va qua tay Môi-se, cho chín chi phái và phân nửa chi phái.'),
(6191, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 14, 3, 'OT', 'Vì Môi-se đã ban phần cơ nghiệp của hai chi phái và phân nửa chi phái bên kia sông Giô-đanh; nhưng ông không ban phần cơ nghiệp nào cho người Lê-vi giữa họ.'),
(6192, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 14, 4, 'OT', 'Vì con cháu của Giô-sép gồm hai chi phái, Ma-na-se và Ép-ra-im; nên họ không chia phần đất cho người Lê-vi, ngoại trừ các thành để ở cùng vùng đất hoang quanh thành cho súc vật và tài sản của họ.'),
(6193, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 14, 5, 'OT', 'Như Đức Giê-hô-va đã truyền dặn Môi-se, các con trai của Y-sơ-ra-ên cũng vậy, họ chia đất.'),
(6194, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 14, 6, 'OT', 'Các con trai của Giu-đa đến cùng Giô-suê tại Gil-ganh; và Ca-lép, con trai của Y-phu-nê, người Kê-nít, nói với người rằng: "Ngươi biết điều mà Đức Giê-hô-va đã phán cùng Môi-se, người của Đức Chúa Trời, về ta và về ngươi tại Ca-đết Ba-nê-a."'),
(6195, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 14, 7, 'OT', 'Ta bốn mươi tuổi khi Môi-se, đầy tớ của Đức Giê-hô-va, sai ta từ Ca-đe-si Ba-nê-a đi do thám xứ đất; ta đã đem tin trở lại cho người theo như điều lòng ta nghĩ.'),
(6196, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 14, 8, 'OT', 'Các anh em tôi đi lên cùng tôi đã khiến lòng dân chúng tan chảy; nhưng tôi đã trung thành theo Đức Giê-hô-va Đức Chúa Trời tôi.'),
(6197, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 14, 9, 'OT', 'Và Môi-se đã thề vào ngày ấy, nói rằng: "Chắc chắn đất đai mà bàn chân ngươi đã đặt lên sẽ thuộc về ngươi làm sản nghiệp, và cho con cháu ngươi mãi mãi, vì ngươi đã trung thành theo Đức Giê-hô-va Đức Chúa Trời tôi.'),
(6198, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 14, 10, 'OT', 'Và bây giờ, nầy, Đức Giê-hô-va đã giữ tôi sống, y như Ngài đã phán, đã bốn mươi lăm năm nay, từ khi Đức Giê-hô-va phán lời nầy cho Môi-se, lúc dân Y-sơ-ra-ên đi trong đồng vắng; và bây giờ, nầy, tôi ngày nay là người tám mươi lăm tuổi.'),
(6199, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 14, 11, 'OT', 'Ngày nay tôi vẫn còn mạnh mẽ như ngày Môi-se sai tôi đi; sức lực tôi ngày đó thế nào thì sức lực tôi ngày nay cũng như vậy, để ra chiến trận và để ra vào.'),
(6200, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 14, 12, 'OT', 'Vì vậy, bây giờ xin hãy ban cho tôi núi nầy, là nơi Đức Giê-hô-va đã phán trong ngày ấy; vì ông đã nghe trong ngày ấy rằng người A-na-kim ở đó, và các thành phố thì lớn và kiên cố; có thể Đức Giê-hô-va sẽ ở cùng tôi, và tôi sẽ đuổi được chúng ra, như Đức Giê-hô-va đã phán.'),
(6201, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 14, 13, 'OT', 'Rồi Giô-suê chúc phước cho người ấy, và ban cho Ca-lép, con trai của Y-phu-nê, Hếp-rôn làm sản nghiệp.'),
(6202, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 14, 14, 'OT', 'Vì vậy, Hếp-rôn thuộc về Ca-lép, con trai của Y-phu-nê, người Kê-nít, làm sản nghiệp cho đến ngày nay, vì người đã trung thành theo Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en.'),
(6203, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 14, 15, 'OT', 'Tên gọi trước kia của Hếp-rôn là Kinh-thành Ác-ba, là người vĩ đại giữa những người A-nác; và vùng đất được yên nghỉ khỏi chiến tranh.'),
(6204, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 1, 'OT', 'Sau đây là phần đất được phân chia cho chi phái con cháu Giu-đa theo các gia tộc của họ, đến ranh giới Ê-đôm, từ phía nam sa mạc Xin trở về phía nam.'),
(6205, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 2, 'OT', 'Giới hạn phía nam của họ bắt đầu từ cuối Biển Mặn, từ vịnh hướng về phía nam.'),
(6206, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 3, 'OT', 'Và ranh giới chạy về phía nam đến Maaleh Acrabbim, rồi đi ngang qua Xin, và lên phía nam đến Ca-đe Ba-nê-a, rồi đi ngang qua Hết-rôn, và lên đến A-đa-rah, rồi vòng quanh Cạt-ca.'),
(6207, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 4, 'OT', 'Rồi ranh giới chạy về hướng Azmon, và chạy ra tới sông Ai Cập; các điểm cực nam của bờ cõi sẽ giáp biển. Đây sẽ là bờ cõi phía Nam của các ngươi.'),
(6208, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 5, 'OT', 'Biên giới phía đông là Biển Mặn cho đến tận cùng của sông Giô-đanh; còn biên giới phía bắc là từ đầu vịnh Biển Mặn, bắt đầu từ tận cùng phía bắc của sông Giô-đanh.'),
(6209, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 6, 'OT', 'Đường biên giới đi lên đến Bết Hôg-la, rồi chạy qua về phía bắc Bết A-ra-ba; và đường biên giới đi lên đến hòn đá Bô-han, con trai của Ru-bên.'),
(6210, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 7, 'OT', 'Đường biên giới đi lên về Đê-bia từ thung lũng A-cha, rồi hướng về phía bắc, đối diện với Ghinh-ganh, tức là nơi lên A-đum-mim; và từ phía nam con sông, biên giới đi ngang qua các nguồn nước Ên-sê-mết, và điểm cuối cùng của nó ở Ên-rô-gên.'),
(6211, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 8, 'OT', 'Và ranh giới đi lên qua thung lũng con trai Hinnom, đến phía nam của người Yebus, tức là Giê-ru-sa-lem; rồi ranh giới đi lên đến đỉnh núi ở phía trước thung lũng Hinnom về hướng tây, nằm ở cuối thung lũng Rê-pha-im về phía bắc.'),
(6212, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 9, 'OT', 'Đường biên giới đi từ đỉnh núi đến mạch nước của Néphtô-ah, rồi chạy ra đến các thành phố trên núi Ép-rôn; sau đó đường biên giới tiếp tục đến Ba-a-lah, tức là Ki-ri-át Giê-a-rim.'),
(6213, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 10, 'OT', 'Và ranh giới vòng từ Ba-a-la về hướng tây đến núi Xi-rít, rồi đi ngang qua sườn núi Giê-a-rit về phía bắc, tức là Kê-xa-lôn, và xuống đến Bết- Sê-mết, rồi đi qua Thim-nah.'),
(6214, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 11, 'OT', 'Và ranh giới chạy đến phía bắc của E-cơ-rôn; rồi ranh giới quay về Xi-cha-rôn, đi ngang qua núi Ba-a-lah, và chạy ra đến Gia-bơ-nê-ên; các lối ra của ranh giới đều đổ ra biển.'),
(6215, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 12, 'OT', 'Giới hạn về phía tây là biển lớn; đó là giới hạn của con cái Giu-đa theo các gia tộc của họ.'),
(6216, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 13, 'OT', 'Ca-lép, con trai của Giê-phu-nê, được ban một phần đất giữa các con trai của Giu-đa, theo lệnh của Đức Giê-hô-va cho Giô-suê, là thành Ki-ri-át Ác-ba, tức là Hếp-rôn, cha của người A-nác.'),
(6217, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 14, 'OT', 'Ca-lép trục xuất từ nơi ấy ba con trai của A-nác, là Sê-xai, A-hi-man và Tan-mai, những người con dòng dõi của A-nác.'),
(6218, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 15, 'OT', 'Người từ đó lên cùng những người ở Đa-víp; tên gọi Đa-víp trước kia là Ki-ri-át Sê-phe.'),
(6219, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 16, 'OT', 'Ca-lép nói: Ai đánh chiếm được Ki-ri-át Sê-phe và chiếm lấy nó, ta sẽ gả Aïc-sa, con gái ta, cho người ấy làm vợ.'),
(6220, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 17, 'OT', 'Ốt-ni-ên, con trai của Kê-nát, anh em của Ca-lép, chiếm lấy thành ấy; và người ta đã gả Ách-xa, con gái ông, cho người ấy làm vợ.'),
(6221, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 18, 'OT', 'Khi nàng đến, thì nàng xúi giục người ấy để xin cha nàng một thửa đất; nàng bước xuống khỏi lưng lừa, và Ca-lép hỏi nàng: "Cô muốn gì?"'),
(6222, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 19, 'OT', 'Bà ấy nói: "Xin hãy ban cho tôi một phước; vì ông đã ban cho tôi đất vùng Nam, vậy xin cũng ban cho tôi các suối nước." Người ấy liền ban cho bà các suối trên và các suối dưới.'),
(6223, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 20, 'OT', 'Đây là phần sản nghiệp của chi phái con cái Giu-đa theo các họ hàng của chúng.'),
(6224, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 21, 'OT', 'Các thành phố tận cùng về phía nam của chi phái con cái Giu-đa, giáp ranh giới Ê-đôm, là Ca-bết-xên, Ê-đe và Gia-gu-rơ.'),
(6225, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 22, 'OT', 'Và Ki-na, và Đim-mô-na, và A-đa-đa,'),
(6226, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 23, 'OT', 'Và Kê-đe, và Ha-xô, và Ít-nan.'),
(6227, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 24, 'OT', 'Xíp, và Tê-lem, và Bê-a-lốt,'),
(6228, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 25, 'OT', 'Và Ha-xor, Ha-đát-ta, và Kê-ri-ốt, và Hết-rôn, là Ha-xor.'),
(6229, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 26, 'OT', 'Amam, và Sê-ma, và Mô-la-đa.'),
(6230, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 27, 'OT', 'Và Ha-xa Gát-ta, và Hẹt-môn, và Bết-pa-lết,'),
(6231, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 28, 'OT', 'Và Ha-xa Sua, và Bê-e Sê-va, và Bích-xi-ốt-gia.'),
(6232, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 29, 'OT', 'Ba-a-la, và Ai-im, và A-xem,'),
(6233, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 30, 'OT', 'Và Êt-thô-lát, và Kê-xíl, và Hô-rơ-ma.'),
(6234, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 31, 'OT', 'Và Xích-lác, và Ma-đăm-na, và San-san-na.'),
(6235, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 32, 'OT', 'Và Le-ba-ốt, Si-lim, A-in, và Rim-môn; tất cả các thành là hai mươi chín thành, cùng các làng mạc của chúng.'),
(6236, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 33, 'OT', 'Trên vùng đồng bằng, Ét-tha-ôn, Xô-ré-ách và Ách-nát.'),
(6237, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 34, 'OT', 'Và Xa-nô, và Ên Gan-nim, Ta-phu-a, và Ên-am.'),
(6238, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 35, 'OT', 'Yarmuth, A-đu-lam, Sokho và Azekah.'),
(6239, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 36, 'OT', 'Và Xa-a-rim, và A-đi-tha-im, và Gê-đê-rah, và Ghê-đê-rô-tha-im; mười bốn thành phố và các làng mạc của chúng.'),
(6240, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 37, 'OT', 'Xenán, và Ha-đa-sa, và Mích-đanh Gát.'),
(6241, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 38, 'OT', 'Và Đích-lê-an, và Ha-mít-xách, và Gia-úc-thê-ên,'),
(6242, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 39, 'OT', 'La-ki và Bốt-xách và Éc-lôn.'),
(6243, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 40, 'OT', 'Và Ca-bôn, và Lách-mam, và Kít-lích.'),
(6244, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 41, 'OT', 'Gẹ-đê-rốt, Bết-Đa-gôn, Na-a-ma và Mác-kê-đa; mười sáu thành cùng các làng mạc của chúng.'),
(6245, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 42, 'OT', 'Lib-na, Ê-ther và A-sán.'),
(6246, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 43, 'OT', 'Và Y-ph-tách, và A-sê-nah, và Nết-íp,'),
(6247, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 44, 'OT', 'Và Kê-ri-la, A-kh-xíp, và Ma-rê-xa; chín thành phố với các làng mạc của chúng:'),
(6248, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 45, 'OT', 'Ê-cơ-rôn cùng các thành con và các làng mạc của nó.'),
(6249, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 46, 'OT', 'Từ Ê-cơ-rôn trở về phía biển, tất cả những nơi gần A-xốt và các làng mạc của chúng;'),
(6250, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 47, 'OT', 'A-xơ-đốt với các thành thị và làng mạc của nó, Gát với các thành thị và làng mạc của nó, cho đến sông Ai Cập; biển lớn và ranh giới của nó.'),
(6251, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 48, 'OT', 'Và trên núi, Sa-mia, và Gia-tia, và Xô-cô.'),
(6252, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 49, 'OT', 'Và Đan-na, và Kinh thành San-na, tức là Đê-bia.'),
(6253, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 50, 'OT', 'Và Anab, và Eshtemô, và Anim,'),
(6254, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 51, 'OT', 'Gô-sen, và Hô-lôn, và Gi-lô; mười một thành cùng các làng mạc của chúng.'),
(6255, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 52, 'OT', 'A-ra-bơ, Ru-ma và Et-xê-an.'),
(6256, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 53, 'OT', 'Và Yanim, và Bết-ta-phu-ách, và A-phê-ka.'),
(6257, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 54, 'OT', 'Và Hơmta, và Ki-ri-át Ác-ba, tức là Hếp-rôn, và Xi-ô; chín thành ấy cùng các làng mạc của chúng.'),
(6258, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 55, 'OT', 'Ma-on, Ca-rmên, Xi-ph và Yu-ta.'),
(6259, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 56, 'OT', 'Và Y-xơ-rên, và Yốc-đê-am, và Xa-nô-ách.'),
(6260, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 57, 'OT', 'Kain, Ghíp-ha và Tím-nah; mười thành với các làng mạc của chúng.'),
(6261, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 58, 'OT', 'Halhul, Bết-tu-rơ và Ghê-đô.'),
(6262, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 59, 'OT', 'Ma-a-rát, Bê-tha-nót và Ên-tê-kôn; sáu thành ấy cùng các làng mạc của chúng.'),
(6263, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 60, 'OT', 'Kir-gát Ba-an, tức là Kir-gát Giê-a-rim, và Ra-ba; hai thành ấy và các làng mạc của chúng.'),
(6264, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 61, 'OT', 'Trong đồng vắng, Bết A-ra-ba, Mít-đin và Xê-ca-ca.'),
(6265, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 62, 'OT', 'Và Níp-sán, và thành của Muối, và Ên-ghi-đi; sáu thành với các làng mạc của chúng.'),
(6266, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 15, 63, 'OT', 'Còn người Y-bu-si, là dân cư Giê-ru-sa-lem, thì con cháu Giu-đa không thể đuổi ra khỏi đó được; và người Y-bu-si cứ ở cùng con cháu Giu-đa tại Giê-ru-sa-lem cho đến ngày nay.'),
(6267, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 16, 1, 'OT', 'Số phận dành cho con cháu của Giô-sép bắt đầu từ sông Giô-đanh gần Giê-ri-cô, hướng về phía đông đến các suối nước của Giê-ri-cô, rồi lên vùng hoang mạc từ Giê-ri-cô đến vùng núi Bê-thên.'),
(6268, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 16, 2, 'OT', 'Từ Bê-thên đi đến Lốt, rồi qua khỏi ranh giới của người A-ki đến A-ta-rốt.'),
(6269, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 16, 3, 'OT', 'Và ranh giới đi xuống phía tây đến ranh giới của Yaphleti, cho đến ranh giới Bê-th-hô-rôn phía dưới, và đến Ghê-xe; các lối ra của nó ở biển.'),
(6270, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 16, 4, 'OT', 'Các con trai của Giô-sép, Ma-na-se và Ê-phra-im, nhận được phần đất của mình.'),
(6271, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 16, 5, 'OT', 'Giới hạn của con cái Ép-ra-im theo các họ hàng của chúng là: giới hạn phần đất được chia cho chúng về phía đông là A-ta-rốt Ha-đa, cho đến Bết-đô-rôn trên.'),
(6272, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 16, 6, 'OT', 'Đường biên giới chạy ra biển, đến Mikhem-ta ở phía bắc; rồi đường biên giới cong về phía đông đến Ta-anat-si-lô, và đi ngang qua đó về phía đông đến Gia-nô-ha.'),
(6273, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 16, 7, 'OT', 'Và ranh giới đi xuống từ Yanôhah đến Atarôth và đến Naarat, rồi đến Giê-ri-cô và đổ ra sông Giô-đanh.'),
(6274, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 16, 8, 'OT', 'Giới hạn sẽ đi từ Táp-pu-ách về hướng tây đến sông Ca-na; và các lối ra của nó sẽ đổ ra biển. Đây là phần sản nghiệp của chi phái con cháu Ép-ra-im, theo các họ hàng của họ.'),
(6275, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 16, 9, 'OT', 'Các thành bị tách ra cho con cái Ép-ra-im nằm giữa phần sản nghiệp của con cái Ma-na-se, gồm tất cả các thành và các làng mạc thuộc về chúng.'),
(6276, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 16, 10, 'OT', 'Họ không đuổi khỏi người Ca-na-an sống tại Ghê-xe; người Ca-na-an cứ ở giữa chi phái Ép-ra-im cho đến ngày nay, và phải làm công việc phục dịch dưới quyền cai trị.'),
(6277, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 17, 1, 'OT', 'Một phần đất được chia cho chi phái Ma-na-se, vì người là con cả của Yosép; còn về Ma-khích, con cả của Ma-na-se, cha của Ghi-lê-át, vì người là một người chiến sĩ, nên người được Ghi-lê-át và Ba-san.'),
(6278, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 17, 2, 'OT', 'Cũng có phần cho những con trai còn lại của Ma-na-se theo các họ hàng của họ, cho con cháu của A-bi-ê-xe, và cho con cháu của Hê-léc, và cho con cháu của A-si-ên, và cho con cháu của Sê-cêm, và cho con cháu của Hê-phe, và cho con cháu của Sê-mi-đa; những người này là các con trai của Ma-na-se, con trai của Giô-sép, theo các họ hàng của họ.'),
(6279, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 17, 3, 'OT', 'Nhưng Xê-lô-phê-hát, con trai của Hê-phẹt, con trai của Ghít-thê-át, con trai của Mạc-khia, con trai của Ma-na-se, thì không có con trai, chỉ có con gái; và đây là các tên của các con gái người: Mách-la, Nô-a, Hô-ghla, Minh-ca và Tít-xa.'),
(6280, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 17, 4, 'OT', 'Các người ấy đến gần trước mặt thầy tế lễ Ê-le-a-sa, trước mặt Giô-suê con trai của Nun và trước mặt các lãnh tụ, nói rằng: Đức Giê-hô-va đã truyền cho Môi-se phải ban cho chúng tôi phần sản nghiệp giữa các anh em của chúng tôi. Vậy theo lời Đức Giê-hô-va, người đã cấp cho họ phần sản nghiệp giữa các anh em của cha họ.'),
(6281, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 17, 5, 'OT', 'Vậy, người ta chia cho Ma-na-se mười phần, ngoài vùng đất Ga-la-át và Ba-san, là những nơi ở bên kia sông Giô-đanh.'),
(6282, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 17, 6, 'OT', 'Vì các con gái của Ma-na-se được chia phần sản nghiệp giữa những con trai của ông; còn đất của Ga-la-át thì thuộc về các con trai Ma-na-se còn lại.'),
(6283, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 17, 7, 'OT', 'Biên giới của Ma-na-se bắt đầu từ A-se, đến Mích-mê-tha nằm trước mặt Si-chem; rồi đường biên giới chạy về phía bên phải đến các dân cư ở Ên Táp-pu-ách.'),
(6284, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 17, 8, 'OT', 'Một phần đất của Ma-na-se thuộc về Táp-pu-ách; còn Táp-pu-ách ở biên giới Ma-na-se thì thuộc về các con trai Ép-ra-im.'),
(6285, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 17, 9, 'OT', 'Và ranh giới đi xuống sông Kana về phía nam sông; những thành này của Ép-ra-im nằm giữa các thành của Ma-na-se; ranh giới của Ma-na-se ở phía bắc sông, và các lối ra của nó dẫn ra biển.'),
(6286, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 17, 10, 'OT', 'Phía nam là của Ép-ra-im, phía bắc là của Ma-na-se; biển là ranh giới của họ; họ giáp ranh với A-xơ về phía bắc và với Y-xa-sác về phía đông.'),
(6287, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 17, 11, 'OT', 'Ma-na-se được phần đất ở trong vùng I-sa-ca và A-xơ: Bết-si-an cùng các thị trấn thuộc về nó, Y-bê-am cùng các thị trấn thuộc về nó, dân cư Đô và các thị trấn thuộc về nó, dân cư Ên-đô và các thị trấn thuộc về nó, dân cư Ta-anhách và các thị trấn thuộc về nó, dân cư Mê-gi-đô và các thị trấn thuộc về nó, tổng cộng là ba vùng đất.'),
(6288, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 17, 12, 'OT', 'Nhưng con cháu của Ma-na-se không thể chiếm được những thành nầy; và người Ca-na-an không chịu dời khỏi đất nầy.'),
(6289, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 17, 13, 'OT', 'Khi con cái Y-sơ-ra-ên trở nên mạnh mẽ, họ bắt người Ca-na-an phải nộp cống, nhưng không trục xuất họ khỏi đất.'),
(6290, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 17, 14, 'OT', 'Con cái Giô-sép nói với Giô-suê rằng: "Tại sao ông chỉ cấp cho tôi một phần đất làm sản nghiệp, chỉ một phần duy nhất, trong khi tôi là một dân đông, vì cho đến nay Đức Giê-hô-va vẫn ban phước cho tôi?"'),
(6291, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 17, 15, 'OT', 'Và Giô-suê nói với họ: "Nếu ngươi là một dân đông, hãy lên vùng rừng núi mà tự khai phá nơi đó, trong đất của người Phê-ri-xi và người Rê-pha-im, vì núi Ép-ra-im quá chật cho ngươi."'),
(6292, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 17, 16, 'OT', 'Con cái Giô-sép nói: "Núi đất thì không đủ cho chúng tôi, mà mọi người Ca-na-an ở trong vùng thung lũng đều có xe sắt, cả những kẻ ở Bết-sê-an và các thị trấn chung quanh nó, lẫn những kẻ ở thung lũng Y-xa-rên."'),
(6293, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 17, 17, 'OT', 'Rồi Giô-suê nói với nhà Giô-sép, tức Ép-ra-im và Ma-na-se, rằng: "Ngươi là một dân đông và có quyền năng lớn; ngươi sẽ không chỉ được một phần đất mà thôi."'),
(6294, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 17, 18, 'OT', 'Núi đó sẽ thuộc về ngươi, vì đó chỉ là rừng, và ngươi phải đốn nó đi; các vùng đất ở rìa núi sẽ thuộc về ngươi, nếu ngươi đuổi được người Ca-na-an ra khỏi đó, dù chúng có xe chiến bằng sắt và rất mạnh.'),
(6295, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 18, 1, 'OT', 'Hội chúng của các con trai Y-sơ-ra-ên nhóm lại tại Si-lô, và họ dựng nơi đó cái lều hội ngộ. Và đất đã bị chinh phục trước mặt họ.'),
(6296, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 18, 2, 'OT', 'Còn lại bảy chi phái trong con cái Ít-ra-en, chưa chia phần sản nghiệp của mình.'),
(6297, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 18, 3, 'OT', 'Rồi Giô-suê nói với con cái Ít-ra-en: "Còn bao lâu các ngươi chần chừ không đi chiếm đất mà Đức Giê-hô-va Đức Chúa Trời của tổ phụ các ngươi đã ban cho các ngươi?"'),
(6298, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 18, 4, 'OT', 'Hãy chọn cho mỗi chi phái ba người, rồi ta sẽ sai họ đi; họ sẽ đi khắp đất, ghi chép lại các phần đất được chia cho từng chi phái, rồi trở về gặp ta.'),
(6299, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 18, 5, 'OT', 'Họ phải chia xứ ấy ra làm bảy phần; người Giu-đa sẽ ở trong vùng đất của mình về phía nam, còn nhà Giô-sép sẽ ở trong vùng đất của mình về phía bắc.'),
(6300, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 18, 6, 'OT', 'Các ngươi hãy chia đất thành bảy phần và mang bản mô tả về đây cho ta, để ta bốc thăm phân chia trước mặt Đức Giê-hô-va Đức Chúa Trời của chúng ta tại đây.'),
(6301, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 18, 7, 'OT', 'Vì người Lê-vi không có phần giữa các ngươi, vì chức thầy tế lễ của Đức Giê-hô-va là sản nghiệp của họ; còn Gad, và Ru-bên, và phân nửa chi phái Ma-na-se, thì đã nhận sản nghiệp mình bên kia sông Giô-đanh về phía đông, là điều mà Môi-se, tôi tớ của Đức Giê-hô-va, đã ban cho họ.'),
(6302, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 18, 8, 'OT', 'Bấy giờ những người ấy đứng dậy và đi; và Giô-suê dặn các người đi đặng mô tả xứ ấy rằng: "Hãy đi, đi quanh trong xứ, mô tả nó, rồi trở lại cùng ta; tại đây ta sẽ bắt thăm cho các ngươi trước mặt Đức Giê-hô-va tại Si-lô."'),
(6303, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 18, 9, 'OT', 'Bấy giờ những người ấy đi qua xứ, ghi lại các thành của bảy phần đất vào một cuốn sách, rồi trở về cùng Giô-suê tại trại quân ở Si-lô.'),
(6304, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 18, 10, 'OT', 'Rồi ông Giô-suê bắt thăm cho họ tại Si-lô, trước mặt Đức Giê-hô-va; và tại đó, ông Giô-suê chia đất cho con cái Ít-ra-en tùy theo các nhóm của họ.'),
(6305, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 18, 11, 'OT', 'Tổ của chi phái con cái Bên-gia-min được rút thăm theo các họ hàng của chúng; và ranh giới phần đất của chúng xuất hiện ở giữa con cái của Giu-đa và con cái của Giô-sép.'),
(6306, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 18, 12, 'OT', 'Biên giới của họ về phía bắc bắt đầu từ sông Giô-đanh; biên giới ấy lên đến sườn thành Giê-ri-cô về phía bắc, rồi đi lên miền núi về hướng tây; các lối ra của nó dẫn đến sa mạc Bê-tha-ven.'),
(6307, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 18, 13, 'OT', 'Và ranh giới vượt qua từ đó về phía Luz, đến phía bên cạnh Luz về hướng nam, tức là Bê-thên; rồi ranh giới đi xuống At-ta-rốt A-đa, gần ngọn đồi ở phía nam của Bê-thôn Hạ.'),
(6308, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 18, 14, 'OT', 'Đường biên giới vòng về phía tây nam, từ ngọn đồi đối diện với Bết-hô-rôn về hướng nam; và các lối ra vào của nó dẫn đến Ki-ri-át Ba-anh, tức là Ki-ri-át Giê-a-rim, một thành của con cái Giu-đa; đây là phần phía tây.'),
(6309, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 18, 15, 'OT', 'Phía nam bắt đầu từ cuối Ki-ri-át Giê-a-rim, và ranh giới chạy ra phía tây, rồi chạy ra đến suối nước Nephtoah.'),
(6310, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 18, 16, 'OT', 'Và ranh giới đi xuống đến cuối ngọn núi nằm trước thung lũng con trai của Hin-nom, tức là ở thung lũng Rê-pha-im về phía bắc; rồi đi xuống thung lũng Hin-nom, đến sườn đồi về phía nam của người Y-bu-si, và đi xuống đến En-rô-gên.'),
(6311, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 18, 17, 'OT', 'Vạch ranh từ phương bắc, đi đến Ên-sê-mết, rồi đi về phía Ghê-li-lốt, đối diện với dốc lên A-đu-mim, và xuống đến hòn đá Bô-han, con trai của Ru-bên.'),
(6312, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 18, 18, 'OT', 'và đi ngang qua bên sườn đối diện với A-ra-ba về hướng bắc, rồi đi xuống vùng A-ra-ba.'),
(6313, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 18, 19, 'OT', 'Và ranh giới đi ngang qua bên sườn phía bắc của Bê-tha Hô-ghla; và các lối ra của ranh giới là về phía vịnh biển mặn về phía bắc, đến đầu phía nam của sông Giô-đanh; đây là ranh giới phía nam.'),
(6314, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 18, 20, 'OT', 'Sông Giô-đanh làm ranh giới cho nó về phía đông. Đây là sản nghiệp của con cái Bên-gia-min, theo các ranh giới bao quanh, theo các họ hàng của chúng.'),
(6315, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 18, 21, 'OT', 'Các thành thuộc về chi phái con trai của Bên-gia-min theo các gia tộc của chúng gồm có Giê-ri-cô, Bê-thên-hô-ghanh, và thung lũng Kê-xích.'),
(6316, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 18, 22, 'OT', 'Và Bê-ta Ha-a-ra-ba, và Xe-ma-ra-im, và Bê-tên.'),
(6317, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 18, 23, 'OT', 'Và người A-vim, và Pa-ra, và Óc-pha.'),
(6318, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 18, 24, 'OT', 'và Kê-phạt- Ha-am-mô-nai, và Ô-phi, và Ga-ba; mười hai thành với các làng xã của chúng.'),
(6319, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 18, 25, 'OT', 'Ghi-bê-ôn, và Ra-ma, và Bê-rốt,'),
(6320, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 18, 26, 'OT', 'Và Mít-pê, và Kê-phi-ra, và Mô-xa.'),
(6321, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 18, 27, 'OT', 'Và Rê-kem, và I-rp-phi-ên, và Ta-ra-la,'),
(6322, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 18, 28, 'OT', 'Và Xê-la, Ê-lê-ph, và người Y-bu-si, tức là Giê-ru-sa-lem, Ghi-bê-át Ki-ri-át; mười bốn thành cùng các làng mạc của chúng. Đó là sản nghiệp của con cái Bên-gia-min theo các họ hàng của chúng.'),
(6323, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 1, 'OT', 'Lô thứ hai được rút ra cho Si-mê-ôn, cho chi phái con cháu Si-mê-ôn theo các họ hàng của họ; và phần sản nghiệp của họ nằm trong phần sản nghiệp của con cháu Giu-đa.'),
(6324, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 2, 'OT', 'Họ nhận được phần đất kế tự là Bê-er-Sê-ba, Xi-ba và Mô-la-đa.'),
(6325, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 3, 'OT', 'Và Hát-xa Sú-an, và Ba-la, và A-xem,'),
(6326, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 4, 'OT', 'Và Êt-lô-đa, và Bết-út, và Hôc-ma,'),
(6327, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 5, 'OT', 'Và Xích-lác, và Bết-ha-mác-ca-bốt, và Ha-xa-xu-sa.'),
(6328, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 6, 'OT', 'Và Bết-lê-a-ốt, và Sa-ru-hên; mười ba thành và các làng mạc của chúng.'),
(6329, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 7, 'OT', 'Ein, Rim-môn, Éther và Ashan; bốn thành và các làng mạc của chúng.'),
(6330, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 8, 'OT', 'Và tất cả các làng mạc xung quanh những thành này cho đến Ba-a-lát Bê-e, Ramath của miền Nam; đây là sản nghiệp của chi phái con cái Si-mê-ôn theo các họ hàng của chúng.'),
(6331, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 9, 'OT', 'Từ phần đất của con cái Giu-đa, con cái Si-mê-ôn nhận được cơ nghiệp; vì phần của con cái Giu-đa quá rộng lớn đối với họ, nên con cái Si-mê-ôn được chia đất cơ nghiệp ở giữa phần đất cơ nghiệp của họ.'),
(6332, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 10, 'OT', 'Lô thứ ba đã đến phiên con cháu Xê-bu-lun theo các gia tộc của chúng; và ranh giới phần sản nghiệp của chúng là cho đến Sa-rid.'),
(6333, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 11, 'OT', 'Và ranh giới của chúng đi lên phía biển, rồi Marala, và giáp đến Dabbasheth, và giáp đến con sông nằm trước mặt Yôkneam.'),
(6334, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 12, 'OT', 'và từ Xa-rid, đổi hướng về phía đông, về phía mặt trời mọc, đến ranh giới Khi-xlốt Ta-bor, rồi đi ra đến Đa-be-rát, và lên đến Ya-phi-a.'),
(6335, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 13, 'OT', 'Từ đó, ranh giới chạy về phía đông đến Ghít-tha Hépher, rồi đến Ít-ta Hác-xin, và chạy ra đến Rê-môn Mê-thoa, đến Nê-ah.'),
(6336, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 14, 'OT', 'Ranh giới vòng quanh về phía bắc đến Han-na-thôn; và các lối ra của nó dẫn đến thung lũng I-phúc-pha-ên.'),
(6337, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 15, 'OT', 'Và Kát-thát, và Na-ha-lần, và Si-môn, và I-đa-la, và Bết-lê-hem; mười hai thành, cùng các làng mạc của chúng.'),
(6338, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 16, 'OT', 'Đây là sản nghiệp của các con trai Xê-bu-lôn theo các họ hàng họ, những thành này cùng các làng mạc của chúng.'),
(6339, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 17, 'OT', 'Số phận phần thứ tư được rút ra cho Y-sa-xa, cho các con trai của Y-sa-xa theo các họ hàng của họ.'),
(6340, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 18, 'OT', 'Giới hạn của chúng gồm có Y-xơ-rê-ên, và Hách-xu-lốt, và Sô-nêm.'),
(6341, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 19, 'OT', 'Và Ha-phê-rai, và Si-ôn, và A-na-ha-rát.'),
(6342, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 20, 'OT', 'Và Rabbith, và Ki-si-ôn, và Abetz,'),
(6343, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 21, 'OT', 'Và Rê-mết, và Ên Gan-nim, và Ên Ha-đa, và Bê-th Pát-xết.'),
(6344, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 22, 'OT', 'Đoạn ranh giới chạy đến Tabor, Shahazimah và Bết-sê-mết; các điểm cuối cùng của ranh giới họ là sông Giô-đanh: mười sáu thành cùng các làng mạc của chúng.'),
(6345, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 23, 'OT', 'Đây là phần sản nghiệp của chi phái con cháu Y-xa-sác theo các họ hàng họ, gồm các thành và các làng mạc của chúng.'),
(6346, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 24, 'OT', 'Lô thứ năm đã ra cho chi phái con cháu A-xe, theo các họ hàng của họ.'),
(6347, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 25, 'OT', 'Giới hạn của chúng gồm có đất Hel-kát, Ha-li, Bê-tên và A-cha-ph.'),
(6348, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 26, 'OT', 'Và Alam-mê-léc, và Am-mác, và Mích-sanh; và đến tận Ca-mên về phía tây, và đến Si-hô-ríp-nát.'),
(6349, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 27, 'OT', 'Rồi quay về hướng đông, đến Bết-Đa-gôn, tiếp đến Xê-bu-lôn và vùng thung lũng của Y-phát-cha-ên ở phía bắc Bết-Ê-méc, rồi đến Nê-ên, và chạy ra đến Ca-bun về phía bên trái.'),
(6350, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 28, 'OT', 'Và Hẹ-bơ-rôn, và Rê-hốp, và Ha-môn, và Ca-na, cho đến Xi-đôn lớn;'),
(6351, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 29, 'OT', 'Ranh giới lại chạy đến Ra-ma và đến thành pháo đài Ty-rơ; ranh giới lại chạy đến Hô-sa, và các lối ra của nó là biển, từ vùng bờ biển A-khíp.'),
(6352, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 30, 'OT', 'U-ma, A-phéc, và Rê-hốp, gồm hai mươi hai thành cùng các làng mạc của chúng.'),
(6353, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 31, 'OT', 'Đây là sản nghiệp của chi phái con cái A-xe theo các họ hàng của họ, những thành này cùng các làng mạc thuộc về chúng.'),
(6354, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 32, 'OT', 'Số phận phần thứ sáu được rút ra cho các con trai của Náp-ta-li, cho các con trai của Náp-ta-li theo các gia tộc của họ.'),
(6355, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 33, 'OT', 'Vùng đất của họ bắt đầu từ Heleph, từ A-lôn đến Sa-an-na-nim, rồi đến A-đa-mi, Nê-kép và Gia-bnê-en, cho đến Lakum; và các lối ra của nó là sông Giô-đanh.'),
(6356, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 34, 'OT', 'Ranh giới quay về hướng tây đến A-xnốt-tha-bô, rồi từ đó đi ra đến Húc-cốc, chạm đến Xê-bu-lôn ở phía nam, chạm đến A-xe ở phía tây, và đến Giu-đa ở sông Giô-đanh về phía đông mặt trời mọc.'),
(6357, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 35, 'OT', 'Các thành kiên cố là Xít-tim, Xe, và Ha-mát, Ra-quat và Kin-nê-rết.'),
(6358, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 36, 'OT', 'Và A-đa-ma, và Ra-ma, và Ha-xô.'),
(6359, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 37, 'OT', 'Và Kê-đe, và Ê-đrê, và En Ha-xor,'),
(6360, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 38, 'OT', 'Và Y-rôn, và Mích-ga-đên Ên, và Hô-rêm, và Bê-tha-anát, và Bê-tha-sa-mết; mười chín thành với các làng mạc của chúng.'),
(6361, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 39, 'OT', 'Đây là phần sản nghiệp của chi phái con cái Nép-ta-li theo các họ hàng họ, gồm các thành và các làng mạc của thành ấy.'),
(6362, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 40, 'OT', 'Lô thứ bảy đã ra cho chi phái con cháu Đan theo các họ hàng của họ.'),
(6363, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 41, 'OT', 'Ranh giới của phần đất được chia cho họ gồm Xô-ra, Ét-tha-ô và Y-rơ-sê-mết.'),
(6364, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 42, 'OT', 'Và Sa-a-láp-bin, và A-ja-lôn, và Yết-la.'),
(6365, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 43, 'OT', 'và Ê-lôn, và Thimnathah, và Éc-rôn,'),
(6366, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 44, 'OT', 'Và Ê-thê-keh, Ghíp-bê-thôn, và Ba-anh-tha,'),
(6367, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 45, 'OT', 'Và Giê-hút, và các con trai Bê-rác, và Gát-Rim-môn,'),
(6368, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 46, 'OT', 'Và Mê-Giạt-côn, và Ha-ra-côn, cùng với ranh giới đối diện với Gia-phô.'),
(6369, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 47, 'OT', 'Biên giới của con cái Đan thì quá hẹp đối với chúng; nên con cái Đan đã lên đánh thành Lết-sêm, chiếm lấy thành ấy, dùng lưỡi gươm đánh bại nó, chiếm hữu nó, và cư ngụ tại đó; rồi họ gọi Lết-sêm là Đan, theo tên Đan tổ phụ họ.'),
(6370, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 48, 'OT', 'Đây là sản nghiệp của chi phái con trai Đan theo các họ hàng của chúng; những thành này và các làng mạc thuộc về chúng.'),
(6371, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 49, 'OT', 'Các con trai của Y-sơ-ra-ên đã chia xong đất đai theo các ranh giới của nó, rồi ban cho Giô-suê, con trai của Nun, một phần sản nghiệp giữa họ.'),
(6372, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 50, 'OT', 'Theo lời của Đức Giê-hô-va, người ta đã ban cho ông thành mà ông đã xin, tức là Tím-nát Sê-ra ở trên núi Ép-ra-im; ông xây cất thành ấy và ở đó.'),
(6373, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 19, 51, 'OT', 'Đây là những phần sản nghiệp mà Ê-lê-a-xa thầy tế lễ, Giô-suê con trai của Nun và các tộc trưởng các chi phái của con cái Ít-ra-en đã chia làm sản nghiệp bằng sự bắt thăm tại Si-lô, trước mặt Đức Giê-hô-va, ở cửa lều hội kiến; và họ đã hoàn tất việc chia đất.'),
(6374, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 20, 1, 'OT', 'Đức Giê-hô-va phán cùng Giô-suê, rằng:'),
(6375, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 20, 2, 'OT', 'Hãy nói cùng con cái Y-sơ-ra-ên rằng: Hãy chọn cho mình các thành làm nơi nương nhờ, như Ta đã phán cùng các ngươi qua tay Môi-se.'),
(6376, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 20, 3, 'OT', 'Để kẻ giết người vô ý, không cố ý, có thể chạy trốn đến đó; và chúng sẽ làm nơi ẩn náu cho các ngươi khỏi người báo thù huyết.'),
(6377, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 20, 4, 'OT', 'Hắn sẽ chạy đến một trong những thành ấy, đứng tại lối vào cổng thành, trình bày lý do mình với các trưởng lão của thành đó; họ sẽ tiếp nhận hắn vào thành với họ, cấp cho hắn một chỗ ở, và hắn sẽ sống giữa họ.'),
(6378, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 20, 5, 'OT', 'Nếu kẻ báo thù huyết thống đuổi theo người đó, thì họ không được giao kẻ giết người ấy vào tay hắn; vì người này đã đánh chết đồng loại mình cách vô ý, và trước đó không hề ghét bỏ người ấy.'),
(6379, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 20, 6, 'OT', 'Người ấy phải ở lại thành ấy cho đến khi ra đứng trước hội chúng để xét xử, và cho đến khi thầy tế lễ lớn đương thời qua đời; rồi người giết người ấy mới được trở về nhà mình, về thành mình, tức thành mà người ấy đã trốn chạy khỏi đó.'),
(6380, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 20, 7, 'OT', 'Họ biệt riêng Kê-đết trong vùng Ga-li-lê, trên núi Náp-ta-li, và Si-chem trên núi Ép-ra-im, và Kir-yát Ác-ba, tức là Hếp-rôn, trên núi Giu-đa.'),
(6381, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 20, 8, 'OT', 'Về phía bên kia sông Giô-đanh, về phía đông Giê-ri-cô, họ chỉ định Bết-xe trong đồng vắng trên đồng bằng thuộc chi phái Ru-bên, và Ra-mốt trong đất Ghi-lê-át thuộc chi phái Gát, và Ga-lôn trong đất Ba-san thuộc chi phái Ma-na-se.'),
(6382, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 20, 9, 'OT', 'Đây là các thành cho mọi con trai của Y-sơ-ra-ên và cho người ngoại kiều ngụ giữa họ, để bất cứ ai giết người vô ý thì chạy trốn đến đó, hầu khỏi chết bởi tay kẻ báo thù huyết cho đến khi người ấy ra trình diện trước hội chúng.'),
(6383, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 1, 'OT', 'Các trưởng tộc của các thầy Lêvi đến gần thầy tế lễ Ê-lê-a-sa, và đến gần Giô-suê con trai của Nun, và đến gần các trưởng tộc của các chi phái con cái Ít-ra-en.'),
(6384, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 2, 'OT', 'Họ nói với họ tại Si-lô, trong đất Ca-na-an, rằng: Đức Giê-hô-va đã truyền dạy qua tay Môi-se phải cấp cho chúng tôi các thành để ở, cùng đồng cỏ quanh đó cho súc vật chúng tôi.'),
(6385, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 3, 'OT', 'Con cái Y-sơ-ra-ên đã trao cho người Lê-vi những thành ấy và các vùng ngoại ô của chúng, từ sản nghiệp của mình, theo chỉ thị của Đức Giê-hô-va.'),
(6386, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 4, 'OT', 'Số phận đã trúng các gia tộc người Kê-hát; và cho các con trai của A-ha-ron, thầy tế lễ, thuộc người Lê-vi, từ chi phái Giu-đa, và từ chi phái Si-mê-ôn, và từ chi phái Bên-gia-min, theo sự bắt thăm, được mười ba thành.'),
(6387, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 5, 'OT', 'Còn về các con trai Kê-hát còn lại, theo các họ hàng của chi phái Ép-ra-im, và của chi phái Đan, và của phân nửa chi phái Ma-na-se, thì được bắt thăm mười thành.'),
(6388, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 6, 'OT', 'Các con trai của Ghẹt-sôn được bằng cách bốc thăm, theo các họ hàng của chi phái Y-xa-cha, và từ chi phái A-xơ, và từ chi phái Náp-ta-li, và từ phân nửa chi phái Ma-na-se ở Ba-san, tổng cộng mười ba thành.'),
(6389, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 7, 'OT', 'Con trai của Mê-ra-ri, theo các họ hàng của họ, từ chi phái Ru-bên, từ chi phái Gát và từ chi phái Xê-bu-lun, được mười hai thành.'),
(6390, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 8, 'OT', 'Các con trai của Y-sơ-ra-ên đã trao cho người Lê-vi những thành này cùng với các vùng đất đệm xung quanh, y như ĐỨC Giê-hô-va đã truyền dạy qua tay Môi-se bằng cách bắt thăm.'),
(6391, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 9, 'OT', 'Các con trai của chi phái Giu-đa và các con trai của chi phái Si-mê-ôn đã trao những thành này, là những thành được gọi tên như thế này.'),
(6392, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 10, 'OT', 'Các con trai của A-ha-ron, thuộc các họ hàng Kê-hát, là những người Lê-vi, nhận được phần đất đầu tiên bằng sự bắt thăm.'),
(6393, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 11, 'OT', 'Họ đã trao cho họ thành phố Ki-ri-át Ác-ba, cha của A-nác; thành ấy là Hếp-rôn, tại vùng núi Giu-đa, cùng với các vùng đất đệm xung quanh nó.'),
(6394, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 12, 'OT', 'Còn đồng ruộng của thành và các làng mạc xung quanh, họ đã trao cho Ca-lép, con trai của Y-phu-nê, làm phần sở hữu của người.'),
(6395, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 13, 'OT', 'Vậy, họ trao cho các con trai của A-ha-ron, thầy tế lễ, thành Hếp-rôn cùng các vùng đất chung quanh làm thành trì cứu nguy cho kẻ giết người, và Li-bơ-nah cùng các vùng đất chung quanh.'),
(6396, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 14, 'OT', 'Và Yát-tir cùng với các nơi ngoại vi của nó, và Ét-thê-mô-a cùng với các nơi ngoại vi của nó.'),
(6397, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 15, 'OT', 'và Hô-lôn cùng các vùng đất chung quanh nó, và Đê-bia cùng các vùng đất chung quanh nó,'),
(6398, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 16, 'OT', 'Và A-in cùng với đồng cỏ quanh nó, và Yu-ta cùng với đồng cỏ quanh nó, và Bết-sê-mết cùng với đồng cỏ quanh nó; chín thành phố từ hai chi phái ấy.'),
(6399, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 17, 'OT', 'Và từ chi phái Bên-ya-min, Ghíp-ôn cùng các nơi đất đệm quanh nó, Ghê-ba cùng các nơi đất đệm quanh nó.'),
(6400, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 18, 'OT', 'A-na-thốt và vùng đất đệm quanh nó, và Almon và vùng đất đệm quanh nó; bốn thành phố.'),
(6401, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 19, 'OT', 'Mười ba thành và đồng nội của chúng thuộc về các con trai của A-ha-ron, các thầy tế lễ.'),
(6402, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 20, 'OT', 'Các chi phái của con cái Kê-hát, những người Lê-vi còn sót lại trong con cái Kê-hát, đã nhận các thành phố của họ bằng thăm từ chi phái Ép-ra-im.'),
(6403, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 21, 'OT', 'Họ cấp cho họ thành Sêm cùng vùng đất quanh đó trên núi Ép-ra-im, làm thành trú ẩn cho kẻ giết người, và Ghê-xe cùng vùng đất quanh đó.'),
(6404, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 22, 'OT', 'Và Kíp-xai-im cùng các vùng đất chung quanh, và Bết-hô-rôn cùng các vùng đất chung quanh; bốn thành phố.'),
(6405, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 23, 'OT', 'Từ chi phái Đan, [các chi phái đó nhận được] Ên-tê-kê cùng các vùng phụ cận, và Gíp-bê-thôn cùng các vùng phụ cận.'),
(6406, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 24, 'OT', 'Ainôl với các vùng đất chung quanh, Gát-Rim-môn với các vùng đất chung quanh; bốn thành.'),
(6407, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 25, 'OT', 'Và từ phân nửa chi phái Ma-na-se, Ta-nách cùng vùng đất đệm quanh nó, và Gát-Rim-môn cùng vùng đất đệm quanh nó; hai thành.'),
(6408, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 26, 'OT', 'Mười thành cùng các vùng đất hoang xung quanh dành cho các gia tộc của con cháu Kehat còn sót lại.'),
(6409, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 27, 'OT', 'Còn về con cháu Ghẹc-sun, thuộc các họ hàng của người Lê-vi, từ phân nửa chi phái Ma-na-se, thì trao thành Gô-lan tại Ba-san cùng vùng đất đệm quanh nó, để làm thành trì cho kẻ giết người; và trao Bết-sê-ra cùng vùng đất đệm quanh nó; tất cả là hai thành.'),
(6410, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 28, 'OT', 'Và từ chi phái Y-xa-sác, Kít-sôn cùng các nơi đất đai chung quanh nó, Đa-ba-rết cùng các nơi đất đai chung quanh nó.'),
(6411, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 29, 'OT', 'Giạt-mút và các vùng phụ cận, Engannim và các vùng phụ cận; bốn thành.'),
(6412, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 30, 'OT', 'Và từ chi phái A-xe, Mích-sanh cùng với các ngoại vi của thành, Áp-đôn cùng với các ngoại vi của thành,'),
(6413, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 31, 'OT', 'Hê-lê-cát và vùng đất đệm quanh đó, Rê-hốp và vùng đất đệm quanh nó; bốn thành.'),
(6414, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 32, 'OT', 'Từ chi phái Nép-ta-li, thành trú ẩn cho kẻ giết người vô ý là Kê-đết trong Ga-li-lê cùng vùng đất đai chung quanh, và Ha-mốt-Đô với vùng đất đai chung quanh, và Ca-đát với vùng đất đai chung quanh; tất cả ba thành.'),
(6415, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 33, 'OT', 'Tất cả các thành của người Ghẹc-sôn theo các họ hàng của họ, gồm mười ba thành và các vùng đất bao quanh.'),
(6416, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 34, 'OT', 'Còn về các họ hàng của con cái Mê-ra-ri, những người Lê-vi còn sót lại, từ chi phái Xê-bu-lôn, thì có Gia-cha-nêm cùng vùng đất đệm quanh nó, và Ca-tha cùng vùng đất đệm quanh nó.'),
(6417, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 35, 'OT', 'Dim-na và các vùng đất quanh đó, Na-ha-lal và các vùng đất quanh đó; bốn thành phố.'),
(6418, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 36, 'OT', 'Và từ chi phái Ru-bên, Bết-xe với các vùng đất quanh nó, và Gia-ha-xa với các vùng đất quanh nó,'),
(6419, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 37, 'OT', 'Kê-đê-mốt và các vùng phụ cận của thành, và Mê-phát và các vùng phụ cận của thành; bốn thành.'),
(6420, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 38, 'OT', 'Và từ chi phái Gad, thành trú ẩn cho kẻ giết người là Ra-mốt trong đất Ga-la-át cùng với đồng ngoại quanh nó, và Ma-ha-na-im cùng với đồng ngoại quanh nó.'),
(6421, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 39, 'OT', 'Hết-bôn và vùng đất chung quanh nó, Gia-xe và vùng đất chung quanh nó; tất cả bốn thành.'),
(6422, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 40, 'OT', 'Tất cả các thành thuộc về con cháu Mê-ra-ri theo các họ hàng của họ, là những người còn sót lại trong các họ hàng của người Lê-vi, và phần chỉ định cho họ theo sự bắt thăm là mười hai thành.'),
(6423, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 41, 'OT', 'Tất cả các thành của người Lê-vi ở giữa phần đất mà con cháu Y-sơ-ra-ên nhận được là bốn mươi tám thành cùng các vùng đất đệm quanh thành.'),
(6424, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 42, 'OT', 'Các thành nầy là từng thành với các vùng đất bao quanh nó; ấy vậy cho tất cả các thành nầy.'),
(6425, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 43, 'OT', 'Đức Giê-hô-va ban cho Y-sơ-ra-ên tất cả đất đai mà Ngài đã thề ban cho tổ phụ họ; họ chiếm hữu đất ấy và ở trong đó.'),
(6426, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 44, 'OT', 'Đức Giê-hô-va ban cho họ sự yên nghỉ xung quanh, y như mọi điều Ngài đã chỉ thiên thề hứa cùng các tổ phụ họ; không một người nào trong các kẻ thù của họ dám đứng lên chống lại họ; mọi kẻ thù của họ, Đức Giê-hô-va đều trao vào tay họ.'),
(6427, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 21, 45, 'OT', 'Không có điều gì từ mọi điều tốt lành mà Đức Giê-hô-va đã phán với nhà Y-sơ-ra-ên bị thất bại; mọi điều ấy đều ứng nghiệm.'),
(6428, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 1, 'OT', 'Bấy giờ, Giô-suê gọi các người thuộc chi phái Ru-bên, chi phái Gát và phân nửa chi phái Ma-na-se.'),
(6429, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 2, 'OT', 'Ông nói với họ: "Các ngươi đã giữ mọi điều mà Môi-se, tôi tớ của Đức Giê-hô-va, đã truyền cho các ngươi, và đã vâng theo tiếng tôi trong mọi điều tôi truyền cho các ngươi.'),
(6430, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 3, 'OT', 'Các ngươi đã không lìa bỏ anh em mình từ những ngày lâu nay cho đến ngày nay, và đã giữ trọn bổn phận giữ mạng lịnh của Đức Giê-hô-va Đức Chúa Trời các ngươi.'),
(6431, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 4, 'OT', 'Bây giờ Đức Giê-hô-va Đức Chúa Trời các ngươi đã cho anh em các ngươi được an nghỉ, như Ngài đã phán dạy họ; vậy bây giờ, hãy trở về, đi đến các trại của các ngươi, đến đất sản nghiệp mà Môi-se, đầy tớ Đức Giê-hô-va, đã ban cho các ngươi bên kia sông Giô-đanh.'),
(6432, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 5, 'OT', 'Chỉ cần hết sức giữ cẩn thận để làm theo điều răn và luật pháp mà Môi-se, tôi tớ của Đức Giê-hô-va, đã truyền cho các ngươi: yêu mến Đức Giê-hô-va Đức Chúa Trời các ngươi, đi trong mọi con đường của Ngài, giữ các điều răn của Ngài, gắn bó với Ngài, và phục sự Ngài với trọn tấm lòng và trọn mạng sống các ngươi.'),
(6433, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 6, 'OT', 'Rồi Giô-suê ban phước cho họ, và sai họ đi; họ bèn trở về lều mình.'),
(6434, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 7, 'OT', 'Còn về phân nửa chi phái Ma-na-se, thì Môi-se đã ban cho họ tại Ba-san; còn phân nửa kia, thì Giô-suê ban cho họ cùng anh em mình bên kia sông Giô-đanh về phía tây. Và khi Giô-suê sai họ trở về nhà mình, thì ông đã ban phước cho họ.'),
(6435, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 8, 'OT', 'Hãy trở về trại của các ngươi với rất nhiều tài sản, và với số lượng lớn súc vật, bạc, vàng, đồng, sắt, và rất nhiều quần áo; hãy chia của cải cướp được từ kẻ thù các ngươi cùng với anh em các ngươi.'),
(6436, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 9, 'OT', 'Bấy giờ các con trai của Ru-bên, các con trai của Gát và phân nửa chi phái Ma-na-se trở về, rời bỏ các con trai của Y-sơ-ra-ên tại Si-lô, là nơi ở trong đất Ca-na-an, để đi đến đất Ga-la-át, đến đất sản nghiệp của họ, là nơi họ đã được chiếm hữu theo lời của Đức Giê-hô-va qua tay Môi-se.'),
(6437, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 10, 'OT', 'Khi đến vùng bờ bên kia sông Giô-đanh, thuộc đất Ca-na-an, các con trai của Ru-bên, các con trai của Gát và phân nửa chi phái Ma-na-se đã xây dựng một bàn thờ bên bờ sông Giô-đanh, một bàn thờ lớn để nhìn thấy.'),
(6438, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 11, 'OT', 'Các con trai của Y-sơ-ra-ên nghe nói: Kìa, các con trai của Ru-bên và các con trai của Gát và phân nửa chi phái Ma-na-se đã xây một bàn thờ đối diện với đất Ca-na-an, bên các bờ sông Giô-đanh, tại chỗ qua lại của các con trai Y-sơ-ra-ên.'),
(6439, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 12, 'OT', 'Nghe xong, toàn thể hội chúng của con cái Ít-ra-en họp lại tại Si-lô, để cùng đi lên đánh chiến tranh chống lại họ.'),
(6440, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 13, 'OT', 'Các con trai của Y-sơ-ra-ên sai Phi-nê-a, con trai thầy tế lễ Ê-lê-a-xa, đến cùng các con trai của Ru-bên, các con trai của Gát và phân nửa chi phái Ma-na-se tại đất Ga-la-át.'),
(6441, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 14, 'OT', 'Và người đi cùng mười vị lãnh tụ, mỗi vị lãnh tụ là một người đứng đầu một gia đình tổ tiên, thuộc về tất cả các chi phái của Y-sơ-ra-ên; mỗi người ấy là người lãnh đạo nhà tổ tiên mình giữa các ngàn người Y-sơ-ra-ên.'),
(6442, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 15, 'OT', 'Họ đến cùng con cái của Ru-bên, cùng con cái của Gát và phân nửa chi phái Ma-na-se, tại đất Ga-la-át, rồi nói chuyện với họ rằng:'),
(6443, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 16, 'OT', 'Đức Giê-hô-va phán: Toàn thể hội chúng của Đức Giê-hô-va nói rằng: Lòng bất trung này mà các ngươi phạm đến Đức Chúa Trời của Y-sơ-ra-ên là gì vậy? Tại sao hôm nay các ngươi từ bỏ đi theo sau Đức Giê-hô-va, mà lại xây cho mình một bàn thờ để nổi loạn chống lại Đức Giê-hô-va hôm nay?'),
(6444, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 17, 'OT', 'Làm sao chúng ta còn chưa đủ tội lỗi tại Phê-ô, mà đến nay chúng ta vẫn chưa được tinh sạch khỏi nó, và tai họa đã xảy đến cho hội chúng của Đức Giê-hô-va?'),
(6445, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 18, 'OT', 'Và hôm nay, các ngươi sẽ trở lại, không theo sau Đức Giê-hô-va nữa; và xem, các ngươi sẽ phạm tội nghịch lại Đức Giê-hô-va ngày hôm nay; rồi ngày mai, cơn thịnh nộ sẽ giáng trên toàn thể hội chúng Y-sơ-ra-ên.'),
(6446, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 19, 'OT', 'Nếu đất mà anh em đang giữ trở nên ô uế, hãy qua đất thuộc về sản nghiệp của Đức Giê-hô-va, là nơi có nhà tạm của Đức Giê-hô-va ngự, và chiếm lấy một phần giữa chúng tôi; nhưng chớ nổi loạn nghịch lại Đức Giê-hô-va, cũng đừng nổi loạn nghịch lại chúng tôi, bằng cách xây cho mình một bàn thờ khác ngoài bàn thờ của Đức Giê-hô-va Đức Chúa Trời chúng ta.'),
(6447, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 20, 'OT', 'Chẳng phải A-can, con trai Sê-rách, đã phạm tội vi phạm trong điều bị rủa sả sao? Cơn thịnh nộ đã giáng trên toàn thể hội chúng Y-sơ-ra-ên; ấy thế mà người đàn ông ấy đã không chết một mình trong tội lỗi mình.'),
(6448, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 21, 'OT', 'Bấy giờ, con cái của Ru-bên, con cái của Gát và phân nửa chi phái Ma-na-se đáp và nói với các thủ lãnh của các ngàn người Ít-ra-en,'),
(6449, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 22, 'OT', 'Đức Chúa Trời của các thần, Đức Giê-hô-va của các thần, chính Ngài biết rõ, và Ít-ra-en cũng sẽ biết rõ; nếu việc này là sự phản nghịch, hay là sự phạm tội cùng Đức Giê-hô-va, thì ngày nay xin chớ cứu chúng tôi.'),
(6450, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 23, 'OT', 'Xây cho chúng tôi một bàn thờ để xây lại sau khi rời khỏi Đức Giê-hô-va, hay để dâng lên đó của lễ thiêu và của lễ chay, hay để dâng các lễ thù ân trên đó, chính Đức Giê-hô-va sẽ đòi lại.'),
(6451, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 24, 'OT', 'Và nếu chúng tôi không làm điều này vì lo sợ điều đó, mà nói: Ngày mai, con cái các ngươi sẽ nói với con cái chúng tôi rằng: Các ngươi có phần gì với Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên?'),
(6452, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 25, 'OT', 'Đức Giê-hô-va đã đặt sông Giô-đanh làm ranh giới giữa chúng tôi và các anh, hỡi con cái Ru-bên và con cái Gát; các anh không có phần trong Đức Giê-hô-va; chính điều đó sẽ khiến con cái các anh làm cho con cái chúng tôi thôi không kính sợ Đức Giê-hô-va.'),
(6453, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 26, 'OT', 'Chúng tôi nói: Thà rằng chúng ta hãy chuẩn bị xây cho mình một bàn thờ, không phải để dâng của lễ toàn thiêu, cũng không phải để dâng của lễ tế.'),
(6454, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 27, 'OT', 'Vì đó là một bằng chứng giữa chúng tôi và các ông, và giữa các thế hệ sau chúng tôi, để chúng tôi thực hiện công việc thờ phượng Đức Giê-hô-va trước mặt Ngài bằng các của lễ thiêu, các của lễ tế và các của lễ thù ân của chúng tôi, hầu các con cháu các ông ngày sau này không nói với con cháu chúng tôi: Các ngươi không có phần trong Đức Giê-hô-va.'),
(6455, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 28, 'OT', 'Vậy nên chúng tôi nói: Nếu ngày sau, họ nói với chúng tôi hay với các thế hệ chúng tôi, thì chúng tôi sẽ đáp: Hãy xem kiểu mẫu bàn thờ Đức Giê-hô-va mà tổ tiên chúng tôi đã làm, không phải để dâng của lễ thiêu hay của lễ tế, nhưng để làm chứng giữa chúng tôi và các ông.'),
(6456, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 29, 'OT', 'Chớ thì đừng để chúng tôi phạm tội phản nghịch lại Đức Giê-hô-va, hay quay trở lại ngày nay khỏi theo Đức Giê-hô-va mà xây một bàn thờ để dâng của lễ thiêu, của lễ chay, hay của lễ giết, ngoài bàn thờ của Đức Giê-hô-va Đức Chúa Trời chúng tôi, là bàn thờ ở trước mặt đền tạm của Ngài.'),
(6457, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 30, 'OT', 'Và khi Phi-nê-a, thầy tế lễ, các lãnh tụ của hội chúng và các thủ lĩnh ngàn người Ít-ra-en đi cùng ông nghe những lời mà con cái Ru-bên, con cái Gát và con cái Ma-na-se nói, thì điều đó đẹp lòng họ.'),
(6458, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 31, 'OT', 'Phi-nê-a, con trai của Ê-lê-a-xa, thầy tế lễ, nói cùng con cái Ru-bên, con cái Gát và con cái Ma-na-se: "Hôm nay chúng tôi biết rằng Đức Giê-hô-va ở giữa chúng ta, vì các ngươi đã không phạm tội bất trung cùng Đức Giê-hô-va về điều nầy; ngày nay các ngươi đã giải cứu con cái Ít-ra-en khỏi tay Đức Giê-hô-va."'),
(6459, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 32, 'OT', 'Phi-nê-a, con trai của thầy tế lễ E-le-a-xa, cùng các thủ lĩnh, trở về từ con cái Ru-bên và con cái Gát từ đất Ga-la-át sang đất Ca-na-an, đến cùng con cái Y-sơ-ra-ên, và báo cáo lại điều đó cho họ.'),
(6460, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 33, 'OT', 'Điều đó làm đẹp lòng con cái Ít-ra-en; con cái Ít-ra-en chúc tụng Đức Chúa Trời, và không nói đến việc lên đánh nhau để hủy diệt miền đất mà con cái Ru-bên và con cái Gát đang ở.'),
(6461, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 22, 34, 'OT', 'Các con trai của Ru-bên và các con trai của Gát đặt tên cho bàn thờ là Ê-đơ, vì nó làm chứng giữa chúng ta rằng Đức Giê-hô-va là Đức Chúa Trời.'),
(6462, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 23, 1, 'OT', 'Một thời gian khá lâu sau khi Đức Giê-hô-va ban cho Ít-ra-en sự yên nghỉ khỏi mọi kẻ thù chung quanh họ, thì Giô-suê đã già, tuổi tác cao cả.'),
(6463, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 23, 2, 'OT', 'Giô-suê gọi toàn thể dân Ít-ra-en, các bậc trưởng lão, các lãnh đạo, các quan xét và các viên chức của họ, rồi nói với họ: "Tôi đã già, tuổi tác đã cao."'),
(6464, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 23, 3, 'OT', 'Các ngươi đã thấy mọi điều mà Đức Giê-hô-va Đức Chúa Trời các ngươi đã làm cho mọi dân tộc này trước mặt các ngươi; vì chính Đức Giê-hô-va Đức Chúa Trời các ngươi là Đấng chiến đấu cho các ngươi.'),
(6465, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 23, 4, 'OT', 'Hãy xem, tôi đã chia cho các ngươi bằng lots những dân còn sót lại nầy, để làm sản nghiệp cho các chi phái của các ngươi, từ sông Giô-đanh trở đi, và tất cả các dân mà tôi đã tiêu diệt, cho đến biển lớn về hướng tây mặt trời.'),
(6466, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 23, 5, 'OT', 'Đức Giê-hô-va Đức Chúa Trời các ngươi, chính Ngài sẽ đẩy lui chúng khỏi trước mặt các ngươi và đuổi chúng ra khỏi nơi các ngươi; các ngươi sẽ chiếm lấy đất của chúng, như Đức Giê-hô-va Đức Chúa Trời các ngươi đã hứa cho các ngươi.'),
(6467, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 23, 6, 'OT', 'Hãy hết sức bền lòng tuân giữ và thực hiện trọn vẹn mọi điều đã chép trong sách Luật pháp của Môi-se, để không xây khỏi điều đó sang bên phải hoặc bên trái;'),
(6468, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 23, 7, 'OT', 'Chớ đến cùng các dân tộc nầy, là những dân còn sót lại giữa các ngươi; các ngươi chớ nhắc đến danh các thần của chúng, chớ khiến người ta lấy chúng mà thề, chớ thờ lạy chúng, và chớ cúi lạy chúng.'),
(6469, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 23, 8, 'OT', 'Nhưng phải gắn bó với Đức Giê-hô-va Đức Chúa Trời các ngươi, như các ngươi đã làm cho đến ngày nay.'),
(6470, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 23, 9, 'OT', 'Đức Giê-hô-va đã đuổi ra khỏi trước mặt các ngươi các dân lớn và mạnh; còn các ngươi, không một người nào đứng nổi trước mặt các ngươi cho đến ngày nay.'),
(6471, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 23, 10, 'OT', 'Một người trong các ngươi sẽ đuổi theo ngàn người, vì chính Đức Giê-hô-va Đức Chúa Trời các ngươi là Đấng chiến đấu cho các ngươi, như Ngài đã hứa với các ngươi.'),
(6472, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 23, 11, 'OT', 'Hãy giữ gìn chính mình các ngươi cách rất cẩn thận, để yêu mến Đức Giê-hô-va Đức Chúa Trời các ngươi.'),
(6473, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 23, 12, 'OT', 'Nếu các ngươi trở lại và gắn bó với những dân tộc còn sót lại nầy giữa các ngươi, và lập hôn nhân với chúng, vào đến chúng và chúng vào đến các ngươi,'),
(6474, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 23, 13, 'OT', 'Hãy biết chắc rằng Đức Giê-hô-va Đức Chúa Trời của các ngươi sẽ không còn đuổi các dân nầy ra khỏi trước mặt các ngươi nữa; chúng sẽ trở thành cái bẫy và cái cạm bẫy cho các ngươi, roi đánh vào cạnh sườn và gai nhọn trong mắt các ngươi, cho đến khi các ngươi bị tiêu diệt khỏi đất tốt lành nầy, mà Đức Giê-hô-va Đức Chúa Trời của các ngươi đã ban cho các ngươi.'),
(6475, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 23, 14, 'OT', 'Này, hôm nay ta phải đi theo con đường mà mọi người trên đất đều phải đi; và các ngươi phải biết bằng trọn cả lòng trọn cả linh hồn mình rằng không một lời nào trong mọi lời tốt lành mà Đức Giê-hô-va Đức Chúa Trời các ngươi đã phán về các ngươi đã thất hứa; tất cả những điều đó đã ứng nghiệm cho các ngươi, không một lời nào trong số ấy đã thất hứa.'),
(6476, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 23, 15, 'OT', 'Vậy sẽ xảy ra như sau: như mọi điều lành tốt mà Đức Giê-hô-va Đức Chúa Trời các ngươi đã hứa các ngươi, thì chính Đức Giê-hô-va sẽ mang đến cho các ngươi mọi điều dữ, cho đến khi Ngài tiêu diệt các ngươi khỏi đất tốt lành nầy, là đất mà Đức Giê-hô-va Đức Chúa Trời các ngươi đã ban cho các ngươi.'),
(6477, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 23, 16, 'OT', 'Khi các ngươi vi phạm giao ước của Đức Giê-hô-va Đức Chúa Trời các ngươi, mà Ngài đã truyền cho các ngươi, rồi đi phục vụ các thần khác và cúi lạy chúng nó, thì cơn thịnh nộ của Đức Giê-hô-va sẽ nổi lên nghịch cùng các ngươi, và các ngươi sẽ mau chóng bị tiêu diệt khỏi đất tốt lành mà Ngài đã ban cho các ngươi.'),
(6478, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 1, 'OT', 'Giô-suê tập hợp tất cả các chi phái của Y-sơ-ra-ên tại Sêm, rồi gọi các trưởng lão của Y-sơ-ra-ên, các thủ lãnh, các quan xét và các viên chức; họ liền đứng trước mặt Đức Chúa Trời.'),
(6479, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 2, 'OT', 'Giô-suê nói với toàn thể dân chúng rằng: "Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên phán như vầy: ''Xưa kia, tổ tiên các ngươi, từ lâu đời, đã sống bên kia sông lớn, tức là Tê-ra, cha của Áp-ram và cha của Na-hô, và họ đã thờ các thần khác.''"'),
(6480, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 3, 'OT', 'Ta đã lấy cha các ngươi, tức Áp-ram, từ bên kia sông lớn, dẫn người đi khắp đất Ca-na-an, làm cho dòng dõi người sinh sôi nảy nở, và ban cho người Y-sác.'),
(6481, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 4, 'OT', 'Ta đã ban cho Y-sác các con là Gia-cốp và Ê-sau; Ta đã ban cho Ê-sau núi Sê-ir để làm sản nghiệp cho người; còn Gia-cốp và các con trai người thì xuống Ai-cập.'),
(6482, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 5, 'OT', 'Tôi đã sai đi Môi-se và A-rôn, và Tôi đã giáng tai vạ trên Ê-díp-tô, y như điều Tôi đã làm giữa họ; rồi sau đó Tôi đem các ngươi ra.'),
(6483, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 6, 'OT', 'Ta đã dẫn tổ tiên các ngươi ra khỏi Ai Cập; các ngươi đến bên bờ biển, và người Ai Cập đuổi theo tổ tiên các ngươi với xe chiến và kỵ binh đến Biển Đỏ.'),
(6484, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 7, 'OT', 'Khi các ngươi kêu lên cùng Đức Giê-hô-va, thì Ngài khiến sự tối tăm xen giữa các ngươi và người Ai Cập, và Ngài đổ biển xuống trên họ mà che phủ họ; mắt các ngươi đã thấy điều ta đã làm cho người Ai Cập; rồi các ngươi ở trong đồng vắng một thời gian lâu dài.'),
(6485, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 8, 'OT', 'Ta dẫn các ngươi đến đất của người Amôrị, là dân sống bên kia sông Giô-đanh; họ chiến đấu với các ngươi, và Ta đã giao họ vào tay các ngươi, để các ngươi chiếm lấy đất của họ; và Ta đã tiêu diệt họ khỏi trước mặt các ngươi.'),
(6486, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 9, 'OT', 'Bấy giờ Ba-lác, con trai Xíp-phô, vua xứ Mô-áp, nổi dậy đánh chiến tranh cùng Y-sơ-ra-ên, và sai người đi gọi Ba-la-am, con trai Bê-ô, đến để nguyền rủa các ngươi.'),
(6487, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 10, 'OT', 'Nhưng tôi đã không chịu nghe theo Ba-la-am; người ấy đã phải chúc phước cho các ngươi, và tôi đã giải cứu các ngươi khỏi tay người ấy.'),
(6488, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 11, 'OT', 'Các ngươi băng qua sông Giô-đanh và đến Giê-ri-cô; những người ở Giê-ri-cô là người A-mô-rít, Phê-ri-xi, Ca-na-an, Hê-th, Ghích-ga-si, Hí-vi và Giê-bu-xi đã chiến đấu chống lại các ngươi; và Ta đã trao họ vào tay các ngươi.'),
(6489, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 12, 'OT', 'Ta đã sai ong bắp cày đi trước các ngươi, khiến hai vua người Amôr bị đuổi ra khỏi trước mặt các ngươi; chẳng phải bởi gươm ngươi, cũng chẳng phải bởi cung ngươi.'),
(6490, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 13, 'OT', 'Ta đã ban cho các ngươi một đất đai mà các ngươi đã không vất vả làm, và những thành phố mà các ngươi đã không xây dựng, các ngươi đã ở trong đó; các ngươi ăn từ những vườn nho và vườn cây ô-liu mà các ngươi đã không trồng.'),
(6491, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 14, 'OT', 'Vì vậy, hãy kính sợ Đức Giê-hô-va và phục vụ Ngài với lòng ngay thẳng và chân thật; hãy loại bỏ những thần mà tổ tiên các ngươi đã phục vụ bên kia sông và ở Ai Cập; và hãy phục vụ Đức Giê-hô-va.'),
(6492, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 15, 'OT', 'Nếu điều đó là điều xấu trong mắt các ngươi để phục vụ Đức Giê-hô-va, thì hãy chọn ngày hôm nay các ngươi sẽ phục vụ ai: hoặc là các thần mà tổ tiên các ngươi đã thờ ở bên kia sông, hoặc là các thần của người Amôrít, mà các ngươi đang sống trong đất của họ. Nhưng còn tôi và nhà tôi, chúng tôi sẽ phục vụ Đức Giê-hô-va.'),
(6493, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 16, 'OT', 'Dân chúng đáp và nói: Xin Đức Giê-hô-va chớ để chúng tôi bỏ Ngài mà phục vụ các thần khác!'),
(6494, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 17, 'OT', 'Vì chính Đức Giê-hô-va Đức Chúa Trời chúng tôi là Đấng đã đưa chúng tôi và tổ phụ chúng tôi ra khỏi đất Ai Cập, khỏi nhà tôi mọi; Ngài đã làm những dấu kỳ lớn ấy ngay trước mắt chúng tôi, và bảo vệ chúng tôi trong suốt con đường chúng tôi đã đi, cũng như giữa mọi dân chúng tôi đã đi ngang qua.'),
(6495, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 18, 'OT', 'Đức Giê-hô-va đã đuổi ra khỏi mặt chúng tôi mọi dân tộc và người Amôrí, là kẻ ở trong đất nầy; vậy chúng tôi cũng sẽ phục sự Đức Giê-hô-va, vì chính Ngài là Đức Chúa Trời chúng tôi.'),
(6496, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 19, 'OT', 'Rồi Giô-suê nói với dân chúng: "Các ngươi không thể phục vụ Đức Giê-hô-va được, vì Ngài là Đức Chúa Trời thánh khiết, là Đức Chúa Trời ghen tương; Ngài sẽ không tha thứ cho các tội ác và tội lỗi của các ngươi."'),
(6497, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 20, 'OT', 'Nếu các ngươi từ bỏ Đức Giê-hô-va mà thờ các thần ngoại bang, thì Ngài sẽ quay lại, làm hại các ngươi, và tiêu diệt các ngươi sau khi đã làm điều thiện cho các ngươi.'),
(6498, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 21, 'OT', 'Dân chúng nói với Giô-suê: "Không, nhưng chúng tôi sẽ phục vụ Đức Giê-hô-va."'),
(6499, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 22, 'OT', 'Rồi Giô-suê nói với dân chúng: "Chính các ngươi làm chứng cho chính mình rằng các ngươi đã chọn Đức Giê-hô-va để phục sự Ngài." Họ đáp: "Chúng tôi làm chứng."'),
(6500, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 23, 'OT', 'Bây giờ, hãy loại bỏ các thần ngoại bang đang ở giữa các ngươi, và hãy nghiêng lòng mình về phía Đức Giê-hô-va, Đức Chúa Trời của Y-sơ-ra-ên.'),
(6501, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 24, 'OT', 'Dân chúng nói với Giô-suê: "Chúng tôi sẽ phục vụ Đức Giê-hô-va Đức Chúa Trời chúng tôi, và sẽ vâng nghe tiếng Ngài."'),
(6502, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 25, 'OT', 'Vào ngày ấy, Giô-suê lập giao ước với dân chúng, và ban cho họ những điều luật và quy định tại Si-chem.'),
(6503, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 26, 'OT', 'Rồi Giô-suê chép những lời nầy vào sách luật pháp của Đức Chúa Trời; người lấy một hòn đá lớn và dựng nó lên đó, dưới cây sồi, tại nơi thánh của Đức Giê-hô-va.'),
(6504, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 27, 'OT', 'Rồi Giô-suê nói với toàn thể dân chúng: "Nầy, hòn đá nầy sẽ làm chứng cho chúng ta; vì nó đã nghe mọi lời của Đức Giê-hô-va mà Ngài phán cùng chúng ta. Nó sẽ làm chứng cho các ngươi, để các ngươi không chối bỏ Đức Chúa Trời các ngươi."'),
(6505, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 28, 'OT', 'Rồi Giô-suê giải tán dân chúng, mỗi người về phần đất được chỉ định cho mình.'),
(6506, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 29, 'OT', 'Sau những việc ấy, Giô-suê, con trai của Nun, tôi tớ của Đức Giê-hô-va, qua đời, thọ được một trăm mười tuổi.'),
(6507, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 30, 'OT', 'Họ chôn ông trong vùng đất thuộc phần cơ nghiệp của ông, tại Thim-nát-xe-ra, là nơi ở trên núi Ép-ra-im, về phía bắc núi Ga-ách.'),
(6508, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 31, 'OT', 'Dân Y-sơ-ra-ên phục sự Đức Giê-hô-va trọn các ngày đời của Giô-suê, và trọn các ngày đời của các bậc trưởng lão sống lâu hơn Giô-suê, và biết rõ mọi công việc của Đức Giê-hô-va mà Ngài đã làm cho Y-sơ-ra-ên.'),
(6509, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 32, 'OT', 'Và xương cốt của Giô-sép, mà con cái Ít-ra-en đã mang lên từ Ai-cập, thì họ chôn ở Sêm, trong phần đất mà Gia-cốp đã mua của con cái Ha-môr, cha của Sêm, với giá một trăm miếng bạc; và đất ấy thuộc về con cháu Giô-sép làm sản nghiệp.'),
(6510, 6, 'GOI_vi', 'GOI_vi', 'vi', 'JOS', 24, 33, 'OT', 'Và Ê-lê-a-xa, con trai của A-rôn, qua đời; và họ chôn ông tại đồi của Phi-nê-a, con trai ông, là nơi được ban cho Phi-nê-a trên núi Ép-ra-im.'),
(6511, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 1, 'OT', 'Sau khi Giô-suê qua đời, con cái Ít-ra-en cầu hỏi Đức Giê-hô-va, nói: Ai sẽ đi lên trước cho chúng tôi chống lại người Ca-na-an để chiến đấu với họ?'),
(6512, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 2, 'OT', 'Đức Giê-hô-va phán: "Giu-đa phải lên; nầy, Ta đã giao đất nầy vào tay người."'),
(6513, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 3, 'OT', 'Và Giu-đa nói với Si-mê-ôn, anh mình: "Hãy đi lên cùng tôi vào phần đất được chỉ định cho tôi, để chúng ta chiến đấu chống lại người Ca-na-an; và tôi cũng sẽ đi cùng anh vào phần đất được chỉ định cho anh." Thế là Si-mê-ôn đi cùng người ấy.'),
(6514, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 4, 'OT', 'Và người Giu-đa đi lên; và Đức Giê-hô-va đã giao người Ca-na-an và người Phê-ri-xi vào tay họ; và họ đánh bại chúng tại Bê-xek, giết mười ngàn người nam.'),
(6515, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 5, 'OT', 'Họ gặp A-đô-ni-bê-xek tại Bê-xek, rồi giao chiến với người; họ đánh bại người Ca-na-an và người Phê-ri-xi.'),
(6516, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 6, 'OT', 'Nhưng A-đô-ni-bê-xek chạy trốn; và họ đuổi theo, bắt được ông, rồi chặt ngón tay cái và ngón chân cái của ông.'),
(6517, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 7, 'OT', 'Bấy giờ A-đô-ni-bê-xek nói rằng: "Bảy mươi vua, tay và chân bị chặt ngón cái, đã nhặt những miếng rơi dưới bàn ta; tôi đã làm điều đó thì Đức Chúa Trời cũng đã báo ứng tôi như vậy." Họ dẫn người ấy đến Giê-ru-sa-lem, và người ấy chết tại đó.'),
(6518, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 8, 'OT', 'Các con trai của Giu-đa đã chiến đấu chống lại Giê-ru-sa-lem, chiếm lấy thành ấy, đánh thành bằng lưỡi gươm, và thiêu hủy thành phố bằng lửa.'),
(6519, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 9, 'OT', 'Sau đó, con trai của Giu-đa đi xuống để đánh giặc cùng người Ca-na-an, là những kẻ sống trên vùng núi, và tại miền Nam, và trong vùng đất thấp.'),
(6520, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 10, 'OT', 'Và người Giu-đa đi đánh dân Ca-na-an ở Hẹ-bơ-rôn; tên Hẹ-bơ-rôn trước kia là Ki-ri-át Ác-ba. Họ đã giết Xi-xai, A-hi-man và Tan-mai.'),
(6521, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 11, 'OT', 'Từ đó, ông đi đến những người ở Đê-bia; và tên gọi Đê-bia trước kia là Ki-ri-át Sê-phe.'),
(6522, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 12, 'OT', 'Ca-le nói: "Ai đánh chiếm được Kir-yát Sê-phe và chiếm được nó, ta sẽ gả A-cha cho người ấy làm vợ."'),
(6523, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 13, 'OT', 'Ốt-ni-ên, con trai của Kê-nát, em trai của Ca-lép, đã chiếm lấy nơi ấy; và người ta đã giao Ách-sa, con gái người, cho người ấy làm vợ.'),
(6524, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 14, 'OT', 'Khi nàng đến, thì nàng xúi giục người ấy xin cha nàng một thửa đất; và nàng bước xuống khỏi lưng lừa. Ca-lép hỏi nàng: "Con muốn gì?"'),
(6525, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 15, 'OT', 'Bà ấy nói với ông: Xin ông ban cho tôi một phước lành, vì ông đã cho tôi một vùng đất miền Nam, xin cũng cho tôi những suối nước. Vậy Ca-lép ban cho bà những suối nước trên và những suối nước dưới.'),
(6526, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 16, 'OT', 'Các con trai của người Kê-nít, cha vợ của Môi-se, đã lên từ thành của các cây chà là cùng với các con trai của Giu-đa đến đồng vắng Giu-đa, là nơi ở phía nam A-rát; rồi họ đi và ở giữa dân chúng.'),
(6527, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 17, 'OT', 'Và người Giu-đa đi cùng Si-mê-ôn, anh em mình, và đánh bại người Ca-na-an đang cư ngụ tại Xépát, rồi họ tiêu diệt thành ấy hoàn toàn. Thành ấy được đặt tên là Họa-ma.'),
(6528, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 18, 'OT', 'Rồi người Giu-đa chiếm lấy Ách-gia cùng vùng đất đai chung quanh nó, và Ách-ke-lôn cùng vùng đất đai chung quanh nó, và Éc-rôn cùng vùng đất đai chung quanh nó.'),
(6529, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 19, 'OT', 'Đức Giê-hô-va ở cùng với người Giu-đa; người ấy chiếm được vùng núi, nhưng không thể đuổi được những người sống trong thung lũng, vì họ có xe chiến bằng sắt.'),
(6530, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 20, 'OT', 'Họ đã trao Hếp-rôn cho Ca-lép, như Môi-se đã nói; và ông đã đuổi khỏi đó ba con trai của A-nác.'),
(6531, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 21, 'OT', 'Còn con cháu Giê-bu-sít, là dân cư Giê-ru-sa-lem, thì con cháu Bên-gia-min không đuổi ra; nên người Giê-bu-sít vẫn ở cùng con cháu Bên-gia-min tại Giê-ru-sa-lem cho đến ngày nay.'),
(6532, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 22, 'OT', 'Nhà của Giô-sép cũng đi lên đánh Bết Ê-l; và Đức Giê-hô-va ở cùng họ.'),
(6533, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 23, 'OT', 'Nhà Giô-sép sai người đi do thám Bê-tên. (Tên thành ấy trước kia là Lútx.)'),
(6534, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 24, 'OT', 'Bấy giờ những người do thám thấy một người ra khỏi thành, liền nói với người ấy rằng: "Xin hãy chỉ cho chúng tôi lối vào thành, và chúng tôi sẽ đối xử nhân từ với ông."'),
(6535, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 25, 'OT', 'Khi người chỉ cho họ lối vào thành, họ dùng lưỡi gươm đánh chiếm thành ấy; còn người đàn ông và cả gia đình người ấy thì họ thả đi.'),
(6536, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 26, 'OT', 'Người ấy đi đến đất của dân Hê-th, xây một thành và đặt tên thành ấy là Lútz; đó là tên thành ấy cho đến ngày nay.'),
(6537, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 27, 'OT', 'Mên-xa-sê cũng không đuổi được dân Bê-th-sê-an và các thành phụ thuộc, hay dân Ta-anách và các thành phụ thuộc, hay dân Đô và các thành phụ thuộc, hay dân cư của Y-bla-am và các thành phụ thuộc, hay dân cư của Mê-gít-đô và các thành phụ thuộc; nhưng dân Ca-na-an vẫn muốn ở lại đất ấy.'),
(6538, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 28, 'OT', 'Khi Ít-ra-en trở nên mạnh, họ bắt người Ca-na-an phải nộp thuế, nhưng không trục xuất họ ra khỏi đất.'),
(6539, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 29, 'OT', 'Ê-phra-im không đuổi dân Ca-na-an ra khỏi Ghê-xe, nơi chúng đang cư ngụ; và dân Ca-na-an cứ ở giữa họ tại Ghê-xe.'),
(6540, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 30, 'OT', 'Dân sự Xê-bu-lôn không trục xuất những người ở Ki-trôn và những người ở Na-ha-lôn; nhưng người Ca-na-an lại sống giữa họ và phải đóng thuế cho họ.'),
(6541, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 31, 'OT', 'A-xẹc không trục xuất những người ở Ác-cô, cũng không trục xuất những người ở Xi-đôn, và Ách-láp, và Ách-xíp, và Hên-ba, và A-phích, và Rê-hốp.'),
(6542, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 32, 'OT', 'Người A-se sống giữa người Ca-na-an, những kẻ cư ngụ trong đất, vì họ không đuổi những kẻ đó ra khỏi đất.'),
(6543, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 33, 'OT', 'Na-ph-ta-li không trục xuất những người ở Bê-thêm-ết và những người ở Bê-than-nát; nhưng người ấy sống giữa người Ca-na-an, những người cư ngụ trong đất. Còn những người ở Bê-thêm-ết và Bê-than-nát thì phải phục dịch họ.'),
(6544, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 34, 'OT', 'Người Amôrít ép con cháu Đan phải ở vùng núi, vì không cho họ xuống thung lũng:'),
(6545, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 35, 'OT', 'Người A-mô-rít vẫn muốn ở lại trên núi Hê-rết, tại Ai-ja-lôn và tại Sa-ach-bim; nhưng tay nhà Giô-sép trở nên mạnh, khiến họ phải chịu thuế.'),
(6546, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 1, 36, 'OT', 'Biên giới của dân Amôri bắt đầu từ nơi lên đến A-kráp-pim, từ tảng đá trở lên.'),
(6547, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 2, 1, 'OT', 'Một thiên sứ của Đức Giê-hô-va đi lên từ Ghinh-ganh đến Bô-chim, và nói: "Ta đã đem các ngươi ra khỏi Ai-cập, dẫn các ngươi vào đất mà Ta đã chỉ trỏ các tổ phụ các ngươi và Ta phán: Ta sẽ không bao giờ hủy bỏ giao ước của Ta với các ngươi đến muôn đời."'),
(6548, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 2, 2, 'OT', 'Các ngươi không được lập giao ước với những người ở trong đất nầy; các ngươi phải phá hủy các bàn thờ của chúng nó; nhưng các ngươi đã không vâng theo tiếng ta: các ngươi đã làm điều nầy là gì vậy?'),
(6549, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 2, 3, 'OT', 'Ta cũng đã phán: Ta sẽ không đuổi chúng ra khỏi trước mặt các ngươi; chúng sẽ trở thành những chiếc gai chọc vào hai bên sườn các ngươi, và các thần của chúng sẽ là cái bẫy rập cho các ngươi.'),
(6550, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 2, 4, 'OT', 'Khi thiên sứ của Đức Giê-hô-va phán những lời nầy cho toàn thể con cái Y-sơ-ra-ên, thì dân sự cất tiếng khóc lên và khóc.'),
(6551, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 2, 5, 'OT', 'Họ gọi tên nơi ấy là Bô-chim; và họ dâng tế lễ tại đó cho Đức Giê-hô-va.'),
(6552, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 2, 6, 'OT', 'Sau khi Giô-suê giải tán dân chúng, thì các con trai Y-sơ-ra-ên mỗi người đi đến phần đất được chỉ định cho mình để chiếm hữu đất ấy.'),
(6553, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 2, 7, 'OT', 'Dân sự phục sự Đức Giê-hô-va trọn các ngày đời của Giô-suê, và trọn các ngày của các bậc trưởng lão sống lâu hơn Giô-suê, những người đã thấy mọi công việc lớn lao mà Đức Giê-hô-va đã làm cho Y-sơ-ra-ên.'),
(6554, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 2, 8, 'OT', 'Và Giô-suê, con trai của Nun, tôi tớ của Đức Giê-hô-va, qua đời, thọ một trăm mười tuổi.'),
(6555, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 2, 9, 'OT', 'Họ chôn ông trong vùng đất thuộc cơ nghiệp của ông, tại Thim-nát-He-rết, trên núi Ép-ra-im, ở phía bắc đồi Ga-ách.'),
(6556, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 2, 10, 'OT', 'Thế rồi cả thế hệ ấy cũng được lãnh về cùng tổ tiên mình. Sau đó, một thế hệ khác nổi lên thay thế họ, là thế hệ không biết Đức Giê-hô-va, cũng chẳng biết các việc Ngài đã làm cho Y-sơ-ra-ên.'),
(6557, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 2, 11, 'OT', 'Con cái Y-sơ-ra-ên làm điều ác trước mặt Đức Giê-hô-va, và phục sự các thần Ba-anh.'),
(6558, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 2, 12, 'OT', 'Họ đã từ bỏ Đức Giê-hô-va, Đức Chúa Trời của tổ tiên mình, Đấng đã đưa họ ra khỏi đất Ai Cập; họ đi theo các thần khác của các dân tộc xung quanh mình, cúi lạy các thần ấy, và làm cho Đức Giê-hô-va nổi giận.'),
(6559, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 2, 13, 'OT', 'Họ từ bỏ Đức Giê-hô-va, và phục vụ Ba-al và các A-sạt-tơ.'),
(6560, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 2, 14, 'OT', 'Đức Giê-hô-va nổi giận cùng Y-sơ-ra-ên, và Ngài phó họ vào tay những kẻ cướp, những kẻ đó đã cướp phá họ; Ngài cũng bán họ vào tay các kẻ thù xung quanh, đến nỗi họ không còn đủ sức chống cự nổi trước mặt các kẻ thù mình.'),
(6561, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 2, 15, 'OT', 'Đức Giê-hô-va khiến tay Ngài chống lại họ trong mọi việc họ ra đi, để gây tai họa cho họ, y như điều Đức Giê-hô-va đã phán và như Đức Giê-hô-va đã thề với họ; và họ rất đau khổ.'),
(6562, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 2, 16, 'OT', 'Đức Giê-hô-va lập các quan xét, và các quan ấy cứu dân khỏi tay những kẻ cướp phá họ.'),
(6563, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 2, 17, 'OT', 'Họ cũng không vâng lời các quan xét của mình, vì họ đã thờ lạy các thần khác và cúi lạy chúng; họ nhanh chóng xây bỏ khỏi con đường mà tổ tiên họ đã đi, là con đường vâng giữ các điều răn của Đức Giê-hô-va; họ đã không làm như vậy.'),
(6564, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 2, 18, 'OT', 'Khi Đức Giê-hô-va dấy lên cho họ các quan xét, thì Đức Giê-hô-va ở cùng quan xét ấy và giải cứu họ khỏi tay kẻ thù nghịch mọi ngày đời quan xét, vì Đức Giê-hô-va cảm thương họ vì tiếng kêu than của họ do những kẻ áp bức và hành hại họ.'),
(6565, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 2, 19, 'OT', 'Khi quan xét qua đời, họ lại trở lại, làm bại hoại hơn tổ tiên mình, đi theo các thần khác để phục sự và thờ lạy chúng; chúng không thôi làm những điều mình đã làm, cũng không thôi đi theo con đường ngoan cố của mình.'),
(6566, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 2, 20, 'OT', 'Đức Giê-hô-va nổi giận cùng Y-sơ-ra-ên, và Ngài phán: "Bởi dân nầy đã vi phạm giao ước ta mà ta đã truyền cho các tổ phụ chúng, và đã không nghe theo tiếng ta."'),
(6567, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 2, 21, 'OT', 'Ta cũng sẽ không còn đuổi một người nào khỏi mặt họ, trong các dân tộc mà Giô-suê đã để lại và đã qua đời.'),
(6568, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 2, 22, 'OT', 'để thử thách Y-sơ-ra-ên bằng những dân đó, xem chúng có giữ đường lối của Đức Giê-hô-va mà đi theo, như tổ tiên chúng đã giữ hay không.'),
(6569, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 2, 23, 'OT', 'Vì vậy, Đức Giê-hô-va để các dân tộc ấy ở yên, không vội đuổi chúng ra, và không giao chúng vào tay Giô-suê.'),
(6570, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 3, 1, 'OT', 'Còn đây là các dân tộc mà Đức Giê-hô-va để lại, để thử thách Y-sơ-ra-ên bằng chúng, tức là tất cả những người trong Y-sơ-ra-ên chưa từng biết các cuộc chiến tranh của Ca-na-an.'),
(6571, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 3, 2, 'OT', 'Chỉ để các thế hệ sau của con cái Y-sơ-ra-ên biết, dạy chúng chiến tranh, tức là những người trước đó chưa từng biết điều đó.'),
(6572, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 3, 3, 'OT', 'Năm tên chúa của người Phi-li-tin, và toàn thể người Ca-na-an, người Xi-đôn, và người Hê-vi ở trên núi Li-băng, từ núi Ba-anh-her-môn cho đến nơi vào Ha-mát.'),
(6573, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 3, 4, 'OT', 'Chúng trở nên điều thử thách cho Y-sơ-ra-ên, để biết chúng có vâng theo các điều răn của Đức Giê-hô-va mà Người đã truyền cho tổ tiên chúng qua tay Môi-se hay không.'),
(6574, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 3, 5, 'OT', 'Con cái Y-sơ-ra-ên sống giữa dân Ca-na-an, dân Hê-th, dân A-mô-rít, dân Phê-ri-xi, dân Hí-vi và dân Giê-bu-xi.'),
(6575, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 3, 6, 'OT', 'Họ lấy các con gái của chúng làm vợ mình, và gả các con gái mình cho con trai chúng, rồi thờ lạy các thần của chúng.'),
(6576, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 3, 7, 'OT', 'Con cái Y-sơ-ra-ên làm điều ác trước mặt Đức Giê-hô-va, và bỏ quên Đức Giê-hô-va Đức Chúa Trời của mình, mà phục vụ các thần Ba-anh và các tượng A-sê-ra.'),
(6577, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 3, 8, 'OT', 'Đức Giê-hô-va nổi giận cùng dân Ít-ra-en, và Ngài bán họ vào tay Cu-sân Ri-sa-thai, vua xứ A-ram Na-ha-ri-im; và con cháu Ít-ra-en phục vụ Cu-sân Ri-sa-thai tám năm.'),
(6578, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 3, 9, 'OT', 'Khi con cái Ít-ra-en kêu khóc cùng Đức Giê-hô-va, thì Đức Giê-hô-va đã cho nổi lên một đấng giải cứu cho con cái Ít-ra-en, và người ấy đã giải cứu họ, ấy là A-cha-ni-ên, con trai của Kê-nát, anh em ruột của Ca-lép, người em hơn ông.'),
(6579, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 3, 10, 'OT', 'Thần của Đức Giê-hô-va ngự trên người ấy, và người ấy xét xử cho dân Y-sơ-ra-ên; người ấy ra đi chinh chiến, và Đức Giê-hô-va đã phó Cô-sân Ri-sa-thai-im, vua xứ Mê-sô-pô-ta-mi, vào tay người; tay người ấy chiến thắng Cô-sân Ri-sa-thai-im.'),
(6580, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 3, 11, 'OT', 'Và đất liền được yên lặng bốn mươi năm. Rồi Ốt-ni-ên, con trai của Kenaz, qua đời.'),
(6581, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 3, 12, 'OT', 'Con cái Ít-ra-en lại tiếp tục làm điều ác trước mặt Đức Giê-hô-va; nên Đức Giê-hô-va làm cho Ê-ghi-ôn, vua xứ Mô-áp, trở nên mạnh mẽ chống lại Ít-ra-en, vì họ đã làm điều ác trước mặt Đức Giê-hô-va.'),
(6582, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 3, 13, 'OT', 'Người đã tập hợp các con trai của Amôn và A-ma-léc lại cùng mình, rồi đi đánh Ít-ra-en và chiếm lấy thành của các cây chà là.'),
(6583, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 3, 14, 'OT', 'Dân Y-sơ-ra-ên phục dịch Ê-ghi-ôn, vua xứ Mô-áp, mười tám năm.'),
(6584, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 3, 15, 'OT', 'Dân Y-sơ-ra-ên kêu khóc cùng Đức Giê-hô-va, thì Đức Giê-hô-va dấy lên cho họ một đấng cứu giúp, là A-hút, con trai Ghê-ra, con trai người Bên-gia-min, một người thuận tay trái; và dân Y-sơ-ra-ên sai A-hút mang lễ vật đến Éc-lôn, vua xứ Mô-áp.'),
(6585, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 3, 16, 'OT', 'Ê-hút làm cho mình một con dao gươm có hai lưỡi, dài một thước; và người thắt nó bên dưới quần áo, nơi đùi phải của mình.'),
(6586, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 3, 17, 'OT', 'Người dâng lễ vật cho Eglôn, vua xứ Mô-áp; và Eglôn là một người béo phì rất nhiều.'),
(6587, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 3, 18, 'OT', 'Khi người dâng của lễ xong, thì người cho những kẻ mang lễ vật ấy đi.'),
(6588, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 3, 19, 'OT', 'Nhưng chính y trở lại từ các hòn đá gần Ghích-ganh, rồi nói: "Tôi có việc kín cần trình vua." Vua bảo: "Im đi!" Rồi tất cả những người đang đứng bên cạnh vua đều lui ra khỏi người đó.'),
(6589, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 3, 20, 'OT', 'Ê-hút đến gặp người ấy, và người ấy đang ngồi trong phòng mát mẻ riêng của mình. Ê-hút nói: "Tôi có một lời từ Đức Chúa Trời cho ông." Người ấy liền đứng dậy khỏi ngai vàng.'),
(6590, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 3, 21, 'OT', 'Ê-hút đưa tay trái ra, rút thanh gươm nơi đùi phải mình, và đâm vào bụng hắn.'),
(6591, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 3, 22, 'OT', 'Cán gươm cũng lọt sâu vào theo lưỡi gươm; mỡ bịt kín quanh lưỡi gươm, vì hắn không rút gươm khỏi bụng mình; và chất nhầy trào ra.'),
(6592, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 3, 23, 'OT', 'Ê-hút đi ra khỏi phòng giữa, đóng các cửa phòng trên lại sau lưng mình và khóa lại.'),
(6593, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 3, 24, 'OT', 'Người ấy ra ngoài, còn các tôi tớ của người thì đến; họ nhìn thấy, nầy, các cửa phòng trên đã đóng kín, nên họ nói: "Chắc hẳn người đang che chân mình trong buồng mát."'),
(6594, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 3, 25, 'OT', 'Họ đợi đến khi bẽ mặt, và này, người ấy không mở cửa phòng trên; họ bèn lấy chìa khóa mở ra, và này, chủ nhân của họ nằm gục xuống đất đã chết.'),
(6595, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 3, 26, 'OT', 'Ê-hút đã trốn thoát trong lúc họ đang chần chờ, người qua các tảng đá, rồi trốn đến Sê-i-ra-tha.'),
(6596, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 3, 27, 'OT', 'Khi ông đến nơi, ông đã thổi loa trên núi Ép-ra-im; và các con trai của Ít-ra-en đi xuống cùng ông từ trên núi, ông đi trước họ.'),
(6597, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 3, 28, 'OT', 'Hãy theo ta, vì Đức Giê-hô-va đã giao các kẻ thù của các ngươi là dân Mô-áp vào tay các ngươi. Vậy họ đi theo người, chiếm các bến qua sông Giô-đanh về phía Mô-áp, và không để một người nào qua được.'),
(6598, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 3, 29, 'OT', 'Họ đánh bại người Mô-áp tại thời điểm ấy khoảng mười ngàn người, tất cả những người mập mạp và tất cả những người tráng kiện; không một người nào thoát được.'),
(6599, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 3, 30, 'OT', 'Mô-áp bị khuất phục ngày ấy dưới tay Y-sơ-ra-ên, và đất được yên lặng tám mươi năm.'),
(6600, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 3, 31, 'OT', 'Sau người ấy, có Sâm-ga, con trai của A-nát, đánh giết sáu trăm người Phi-li-tin bằng cái móc bò, và ông cũng giải cứu Ít-ra-en.'),
(6601, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 4, 1, 'OT', 'Con cái Ít-ra-en lại làm điều ác trước mặt Đức Giê-hô-va, sau khi Ê-hút qua đời.'),
(6602, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 4, 2, 'OT', 'Đức Giê-hô-va bán họ vào tay Y-a-bin, vua xứ Ca-na-an, người trị vì tại Ha-xô; và viên tướng quân đội người là Xi-xê-ra, sống tại Ha-rô-sết của các dân tộc.'),
(6603, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 4, 3, 'OT', 'Con cái Ít-ra-en kêu khóc cùng Đức Giê-hô-va, vì người ấy có chín trăm cỗ xe bằng sắt; và người ấy đã áp bức con cái Ít-ra-en cách mạnh mẽ trong hai mươi năm.'),
(6604, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 4, 4, 'OT', 'Đê-bô-ra là một nữ tiên tri, vợ của La-pi-đốt, chính bà ấy làm quan xét cho Y-sơ-ra-ên trong thời ấy.'),
(6605, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 4, 5, 'OT', 'Bà ngự dưới cây dừa của Đê-bô-ra, ở giữa Ra-mah và Bê-thên, trên núi Ép-ra-im; và con cái Ít-ra-en đi lên đến bà để được xét xử.'),
(6606, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 4, 6, 'OT', 'Bà sai người đi gọi Ba-rác, con trai của A-bi-nô-am, ở Kê-đết Na-phtha-li, và nói với ông: "Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en há chẳng đã truyền lệnh rằng: ''Hãy đi, dẫn quân lên núi Ta-bô, và đem theo ngươi mười ngàn người từ con cái Na-phtha-li và con cái Xê-bu-lun'' sao?"'),
(6607, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 4, 7, 'OT', 'Ta sẽ lôi kéo Xi-xê-ra, tướng lãnh đạo quân đội của Y-a-bin, cùng với các xe ngựa và đoàn quân đông đảo của hắn, đến sông Ki-sôn mà nghịch ngươi; rồi Ta sẽ phó hắn vào tay ngươi.'),
(6608, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 4, 8, 'OT', 'Ba-rác nói với nàng: "Nếu bà đi với tôi, thì tôi sẽ đi; nếu bà không đi với tôi, thì tôi sẽ không đi."'),
(6609, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 4, 9, 'OT', 'Bà ấy nói: "Tôi sẽ đi với ông, nhưng danh dự của ông trên con đường ông đi sẽ không thuộc về ông, vì Đức Giê-hô-va sẽ nộp Xi-xê-ra vào tay một người phụ nữ." Rồi Đê-bô-ra đứng dậy và đi cùng Ba-rác đến Kê-đết.'),
(6610, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 4, 10, 'OT', 'Bàrác triệu tập những người thuộc về Xê-bu-lun và Náp-ta-li đến Kê-đết; ông đi lên với mười ngàn người lính theo ông, và Đê-bô-ra cũng đi lên cùng ông.'),
(6611, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 4, 11, 'OT', 'Vả lại, Hê-ber người Kê-nít, là con cháu của Hô-báp, rể của Môi-se, đã rời khỏi các người Kê-nít và dựng lều mình đến cây sồi ở giữa các cây tại Ê-xa-ân, gần Kê-đe.'),
(6612, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 4, 12, 'OT', 'Người ta báo cho Xi-xê-ra biết rằng Ba-rác, con trai của A-bi-nô-am, đã lên núi Ta-bô.'),
(6613, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 4, 13, 'OT', 'Xi-xê-ra triệu tập tất cả các xe ngựa của người, chín trăm chiếc xe bằng sắt, và toàn thể quân đội đi theo người, từ Ha-rô-sết của các dân tộc đến sông Ki-sôn.'),
(6614, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 4, 14, 'OT', 'Đa-ga nói với Ba-rác: "Hãy đứng dậy, vì hôm nay chính là ngày Đức Giê-hô-va đã trao Xi-xê-ra vào tay ngươi. Đức Giê-hô-va há chẳng đi trước ngươi sao?" Bấy giờ Ba-rác đi xuống từ núi Ta-bô, với mười ngàn người theo sau.'),
(6615, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 4, 15, 'OT', 'Đức Giê-hô-va khiến Sísơra cùng với mọi xe chiến và toàn thể đạo quân của hắn bị đánh bại bởi lưỡi gươm trước mặt Ba-rác; Sísơra bèn xuống khỏi xe, trốn chạy bộ.'),
(6616, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 4, 16, 'OT', 'Nhưng Ba-rác đuổi theo các xe chiến và đạo quân cho đến Ha-rô-sết của dân ngoại; và toàn thể đạo quân của Xi-xê-ra đều ngã xuống bởi lưỡi gươm, không còn sót lại một người nào.'),
(6617, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 4, 17, 'OT', 'Nhưng Xít-raa chạy trốn bằng đôi chân mình đến lều của Gia-ên, vợ của Hê-bơ người Kê-nít, vì giữa Y-a-bin vua thành Ha-dô và nhà của Hê-bơ người Kê-nít có sự hòa bình.'),
(6618, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 4, 18, 'OT', 'Y-xa-ên đi ra đón Xi-xê-ra, nói với người rằng: "Xin mời ngài rẽ vào đây, thưa ông chủ, xin rẽ vào nhà tôi, đừng sợ." Thế là người rẽ vào cùng người nữ vào lều, rồi người nữ lấy chăn đắp cho người.'),
(6619, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 4, 19, 'OT', 'Bấy giờ người nói với nàng: "Xin hãy cho tôi uống ít nước, vì tôi khát." Nàng liền mở bầu sữa, cho người uống, rồi phủ kín người ấy lại.'),
(6620, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 4, 20, 'OT', 'Người nói với nàng: "Hãy đứng ở cửa lều. Nếu có người nào đến hỏi nàng và nói: ''Ở đây có ai không?'' thì nàng hãy trả lời: ''Không có.''"'),
(6621, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 4, 21, 'OT', 'Sau đó, Y-a-hên, vợ của Hê-bec, lấy một cây đinh lều, cầm búa trong tay, rồi nhẹ nhàng đến gần ông ta, đâm cây đinh vào thái dương ông ấy, ghim xuống đất; người ấy đang ngủ mê và mệt lử, nên đã chết.'),
(6622, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 4, 22, 'OT', 'Nầy, khi Ba-rác đang đuổi theo Xi-xê-ra, thì Gia-ên đi ra đón người, và nói với người rằng: "Xin mời ngài vào, tôi sẽ chỉ cho ngài xem người đàn ông ngài đang tìm." Bấy giờ người vào với nàng, và nầy, Xi-xê-ra đã ngã xuống chết, và cái đinh trại cắm ngập trong thái dương người.'),
(6623, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 4, 23, 'OT', 'Vào ngày ấy, Đức Chúa Trời đã khuất phục Yabin, vua xứ Ca-na-an, trước mặt con cái Ít-ra-en.'),
(6624, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 4, 24, 'OT', 'Tay các con trai Y-sơ-ra-ên càng ngày càng mạnh, chống lại Y-a-bin, vua Ca-na-an, cho đến khi họ tiêu diệt hoàn toàn Y-a-bin, vua Ca-na-an.'),
(6625, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 5, 1, 'OT', 'Đoạn đó, Đê-bô-ra và Ba-rác con trai của A-bi-nô-am đã hát vào ngày ấy, rằng:'),
(6626, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 5, 2, 'OT', 'Khi các lãnh tụ cai trị Y-sơ-ra-ên, khi dân chúng sẵn lòng dâng mình, hãy ca ngợi Đức Giê-hô-va.'),
(6627, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 5, 3, 'OT', 'Hỡi các vua, hãy nghe; hỡi các quan trưởng, hãy lắng tai; chính tôi, tôi sẽ hát cho Đức Giê-hô-va; tôi sẽ ca ngợi Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên.'),
(6628, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 5, 4, 'OT', 'Đức Giê-hô-va, khi Ngài đi ra từ Sê-ir, khi Ngài bước ra từ đồng bằng Ê-đôm, đất rung chuyển, các từng trời cũng nhỏ xuống, các đám mây cũng nhỏ nước.'),
(6629, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 5, 5, 'OT', 'Các núi đều rúng động trước mặt Đức Giê-hô-va, chính Si-na-i cũng rúng động trước mặt Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en.'),
(6630, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 5, 6, 'OT', 'Trong những ngày Xa-mạc con trai của A-nát, trong những ngày của Gia-ên, các con đường cái bị bỏ hoang, những kẻ đi đường phải đi các lối mòn quanh co.'),
(6631, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 5, 7, 'OT', 'Dân làng ngưng hoạt động, ngưng hoạt động trong Y-sơ-ra-ên, cho đến khi Đê-bô-ra nổi dậy, tôi nổi dậy như một người mẹ trong Y-sơ-ra-ên.'),
(6632, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 5, 8, 'OT', 'Chúng chọn các thần mới, bấy giờ chiến tranh xảy ra nơi các cổng thành; chẳng thấy khiên hay ngọn giáo giữa bốn mươi ngàn người trong Ít-ra-en.'),
(6633, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 5, 9, 'OT', 'Lòng tôi hướng về những người lãnh đạo Y-sơ-ra-ên, những người đã tự nguyện giữa dân chúng. Hãy ca ngợi Đức Giê-hô-va.'),
(6634, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 5, 10, 'OT', 'Hỡi những người cỡi lừa trắng, hỡi những người ngồi nơi tòa xét xử và đi bộ dọc đường, hãy nói lên đi.'),
(6635, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 5, 11, 'OT', 'Từ tiếng vang những người giương cung giữa các nơi múc nước, tại đó họ sẽ thuật lại các việc công bình của Đức Giê-hô-va, các việc công bình của Ngài đối với các làng mạc Ngài trong Ít-ra-en. Bấy giờ dân sự của Đức Giê-hô-va xuống các cửa thành.'),
(6636, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 5, 12, 'OT', 'Thức dậy, thức dậy, Ðê-bô-ra! Thức dậy, thức dậy, hãy hát bài ca! Chỗi dậy, Bả-ra-que, và hãy bắt kẻ bị ngươi bắt làm phu tù, hỡi con trai của A-bi-nô-am.'),
(6637, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 5, 13, 'OT', 'Bấy giờ, Đấng còn sót lại đã xuống đế quốc các bậc cao cả, dân sự của Đức Giê-hô-va; chính Đức Giê-hô-va đã xuống nơi các anh hùng.'),
(6638, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 5, 14, 'OT', 'Từ Ép-ra-im, gốc rễ họ nổi lên chống lại A-ma-léc; sau ngươi, Bên-gia-min, giữa các dân ngươi; từ Ma-khích, các quan xét đã xuống; và từ Xê-bu-lun, những người cầm cây bút của người chép sử.'),
(6639, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 5, 15, 'OT', 'Và các lãnh tụ của Y-xa-sa-cha ở cùng Đê-bô-ra; chính Y-xa-sa-cha cũng vậy, cùng với Ba-rác, người được sai đi bộ xuống thung lũng. Trong các chi phái Ru-bên, có những ý tưởng lớn trong lòng.'),
(6640, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 5, 16, 'OT', 'Tại sao ngươi ngồi giữa các máng ăn, để nghe tiếng kêu của những bầy chiên? Những phân chia của Ru-bên đã gây ra những lần suy xét sâu xa trong lòng.'),
(6641, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 5, 17, 'OT', 'Ga-la-át ở bên kia sông Giô-đanh; còn Đan, tại sao lại ở trong các thuyền? A-xẹt đã ở dọc theo bờ biển, và sống tại các vịnh cảng của mình.'),
(6642, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 5, 18, 'OT', 'Xê-bu-lun là dân dám liều mạng sống mình đến chết; Na-phi-ta-li là dân dũng cảm trên các ngọn đồi trống trải.'),
(6643, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 5, 19, 'OT', 'Các vua đến đánh nhau; bấy giờ các vua của Ca-na-an đã chiến đấu tại Ta-nách, gần các vùng nước Mê-gi-đô; chúng không lấy được tiền bạc.'),
(6644, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 5, 20, 'OT', 'Từ trời cao họ chiến đấu; các ngôi sao trong quỹ đạo của chúng đã chiến đấu chống lại Xít-ra.'),
(6645, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 5, 21, 'OT', 'Sông Kích-sôn cuốn trôi chúng đi, con sông cổ xưa, sông Kích-sôn. Hỡi linh hồn ta, hãy bước đi trong sức mạnh.'),
(6646, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 5, 22, 'OT', 'Bấy giờ vó ngựa vang dội, giữa những cuộc phi nước đại của các dũng sĩ Ngài.'),
(6647, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 5, 23, 'OT', 'Hỡi Mê-rô-xơ, hãy bị rủa sả! Thiên sứ của Đức Giê-hô-va phán: Hãy rủa sả dữ dội những người ở đó, vì chúng không đến giúp đỡ Đức Giê-hô-va, không đến giúp đỡ Đức Giê-hô-va chống lại các dũng sĩ.'),
(6648, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 5, 24, 'OT', 'Được chúc phước giữa các người phụ nữ, ấy là Y-ael, vợ của Hê-ber người Kê-nít; giữa các người phụ nữ trong trại, nàng được chúc phước.'),
(6649, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 5, 25, 'OT', 'Người xin nước, nàng cho sữa; nàng mang kem đựng trong cái chén sang trọng.'),
(6650, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 5, 26, 'OT', 'Nàng đưa tay ra đóng đinh, tay phải cầm búa thợ; nàng dùng búa đánh Xi-xê-ra, đánh rơi đầu người ấy, đâm thủng và xuyên qua thái dương người ấy.'),
(6651, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 5, 27, 'OT', 'Giữa hai chân nàng, hắn khuỵu xuống, ngã gục và nằm đó; giữa hai chân nàng, hắn khuỵu xuống, ngã gục; nơi nào hắn khuỵu xuống, chính tại đó hắn ngã gục, bị giết.'),
(6652, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 5, 28, 'OT', 'Qua cửa sổ, mẹ Xít-ra ngó ra, khóc lóc nơi song cửa: "Sao xe người chậm đến thế? Sao các bước xe người trì hoãn?"'),
(6653, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 5, 29, 'OT', 'Các bà thông thái trong triều đình bà đáp lời; chính bà cũng tự trả lời mình,'),
(6654, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 5, 30, 'OT', 'Chẳng lẽ họ không chia của cướp sao? Một thiếu nữ, hai thiếu nữ cho mỗi người; của cướp đủ màu cho Xi-xê-ra, của cướp thêu hoa văn đủ màu, vải thêu hoa văn đủ màu hai mặt, dành cho cổ những người mang của cướp.'),
(6655, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 5, 31, 'OT', 'Nguyện mọi kẻ thù Ngài, Đức Giê-hô-va, đều tiêu tan; và những kẻ yêu mến Ngài như mặt trời mọc lên trong quyền năng mình. Rồi đất được yên ổn bốn mươi năm.'),
(6656, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 1, 'OT', 'Con cái Ít-ra-en làm điều ác trước mặt Đức Giê-hô-va; và Đức Giê-hô-va phó họ vào tay Mi-đi-an trong bảy năm.'),
(6657, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 2, 'OT', 'Tay của dân Ma-đi-an mạnh quyền trên Ít-ra-en; vì cớ dân Ma-đi-an, con cái Ít-ra-en làm cho mình những cái hầm trong các núi, và các hang và các đồn lũy.'),
(6658, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 3, 'OT', 'Xảy ra rằng, khi dân Y-sơ-ra-ên vừa gieo giống, thì người Mi-đi-an, người A-ma-léc và con cháu phương đông liền kéo lên, và xâm chiếm họ.'),
(6659, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 4, 'OT', 'Họ đóng trại chống lại dân ấy, tàn phá sản vật của đất đai cho đến tận Ga-xa, không để lại chút của ăn nào cho Y-sơ-ra-ên, cũng không để lại chiên, bò, hay lừa.'),
(6660, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 5, 'OT', 'Vì chúng và súc vật chúng kéo đến, cùng với các trại của chúng, đông như châu chấu, vô số kể, cả chúng lẫn lạc đà của chúng; và chúng vào trong đất để hủy diệt nó.'),
(6661, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 6, 'OT', 'Và Y-sơ-ra-ên bị suy sụp rất nhiều vì người Mi-đi-an; và con cháu Y-sơ-ra-ên kêu lên Đức Giê-hô-va.'),
(6662, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 7, 'OT', 'Khi con cái Y-sơ-ra-ên kêu cứu Đức Giê-hô-va vì cơn thạnh nộ của người Mi-đi-an,'),
(6663, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 8, 'OT', 'Đức Giê-hô-va sai một người tiên tri đến cùng con cái Ít-ra-en, người nói với họ: "Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en phán như vầy: Chính Ta đã đem các ngươi lên từ Ai Cập, và đưa các ngươi ra khỏi nhà tôi mọi."'),
(6664, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 9, 'OT', 'Ta đã giải cứu các ngươi khỏi tay người Ai-cập, và khỏi tay mọi kẻ áp bức các ngươi; Ta đã đuổi chúng nó ra khỏi trước mặt các ngươi, và ban cho các ngươi đất của chúng nó.'),
(6665, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 10, 'OT', 'Ta đã nói với các ngươi: "Ta là Đức Giê-hô-va Đức Chúa Trời của các ngươi; chớ sợ các thần của người A-mô-rít, trong đất của họ các ngươi đang ở"; nhưng các ngươi đã không vâng theo tiếng Ta.'),
(6666, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 11, 'OT', 'Thiên sứ của Đức Giê-hô-va đến và ngồi dưới cây sồi ở Ô-phơ-ra, thuộc về Giô-ách người A-bi-ê-xơ-rít; và Ghi-đê-ôn, con trai ông, đang đập lúa mì trong cái bể ép rượu để giấu khỏi người Mi-đi-an.'),
(6667, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 12, 'OT', 'Thiên sứ của Đức Giê-hô-va hiện ra cùng người, và nói với người rằng: Đức Giê-hô-va ở cùng ngươi, hỡa sĩ dũng cảm.'),
(6668, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 13, 'OT', 'Ghi-đê-ôn nói với người ấy: "Thưa ông, nếu Đức Giê-hô-va ở cùng chúng tôi, thì tại sao mọi điều này lại xảy đến cho chúng tôi? Và những phép lạ của Ngài mà tổ phụ chúng tôi từng thuật lại cho chúng tôi, rằng: ''Chẳng phải Đức Giê-hô-va đã đem chúng ta lên từ Ai Cập sao?''—nay Đức Giê-hô-va đã từ bỏ chúng tôi, và phó chúng tôi vào tay người Ma-đi-an."'),
(6669, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 14, 'OT', 'Đức Giê-hô-va nhìn người và phán: "Hãy đi với sức mạnh của ngươi, và ngươi sẽ giải cứu Y-sơ-ra-ên khỏi tay dân Mi-đi-an. Chẳng phải Ta đã sai ngươi sao?"'),
(6670, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 15, 'OT', 'Tôi nói với Ngài: "Thưa Chúa, tôi sẽ cứu Y-sơ-ra-ên bằng gì? Vì nầy, họ hàng tôi nghèo nhất trong chi phái Ma-na-xe, và tôi là kẻ nhỏ nhất trong nhà cha tôi."'),
(6671, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 16, 'OT', 'Đức Giê-hô-va phán cùng người: "Vì Ta sẽ ở cùng ngươi, và ngươi sẽ đánh bại dân Míp-đi-ân như một người."'),
(6672, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 17, 'OT', 'Người nói với ông: "Nếu bây giờ tôi được ơn trước mặt ngài, xin hãy cho tôi một dấu hiệu rằng chính ngài đang nói chuyện với tôi."'),
(6673, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 18, 'OT', 'Xin ngài chớ đi khỏi đây cho đến khi tôi đến cùng ngài và mang lễ vật của tôi ra đặt trước mặt ngài. Người đáp: Ta sẽ ở đây cho đến khi ngươi trở lại.'),
(6674, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 19, 'OT', 'Ghẹ-đi-ôn đi vào, làm thịt một con dê con, và làm bánh không men bằng một e-pha bột; ông đặt thịt vào một cái giỏ, đặt nước dùng vào một cái nồi, rồi mang ra cho người ấy dưới gốc cây sồi và dâng lên.'),
(6675, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 20, 'OT', 'Và thiên sứ của Đức Chúa Trời nói với người rằng: "Hãy lấy thịt và các ổ bánh không men, đặt lên tảng đá này, và đổ nước dùng ra." Người liền làm như vậy.'),
(6676, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 21, 'OT', 'Thiên sứ của Đức Giê-hô-va đưa đầu cây gậy nơi tay mình chạm vào thịt và các ổ bánh không men; lửa từ tảng đá bốc lên, thiêu đốt thịt và các ổ bánh không men. Rồi thiên sứ của Đức Giê-hô-va biến khỏi mắt người ấy.'),
(6677, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 22, 'OT', 'Ghi-đê-ôn thấy đó là thiên sứ của Đức Giê-hô-va, thì thưa rằng: "Than ôi, lạy Đức Chúa là Đức Giê-hô-va! Vì tôi đã thấy thiên sứ của Đức Giê-hô-va mặt đối mặt."'),
(6678, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 23, 'OT', 'Đức Giê-hô-va phán cùng người: "Bình an cho ngươi, chớ sợ; ngươi sẽ không chết."'),
(6679, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 24, 'OT', 'Bấy giờ Ghẹt-thôn xây một bàn thờ tại đó cho Đức Giê-hô-va, và đặt tên là Đức Giê-hô-va là sự bình an; cho đến ngày nay nó vẫn còn ở Óp-ra của người A-bi-ê-xơ-rít.'),
(6680, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 25, 'OT', 'Đức Giê-hô-va phán cùng người trong đêm ấy: "Hãy lấy con bò đực tơ của cha ngươi, và con bò đực thứ hai đã bảy tuổi, rồi phá cái bàn thờ Ba-al mà cha ngươi có, và chặt cây A-sê-ra ở gần đó."'),
(6681, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 26, 'OT', 'Hãy xây một bàn thờ cho Đức Giê-hô-va Đức Chúa Trời ngươi trên đỉnh tảng đá này, tại nơi đã định; rồi hãy lấy con bò đực thứ hai, và dâng của lễ thiêu bằng những cây gỗ của trụ đá thần mà ngươi sẽ đốn xuống.'),
(6682, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 27, 'OT', 'Ghi-đê-ôn lấy mười người đầy tớ mình và làm theo như Đức Giê-hô-va đã phán dạy người; người sợ gia đình cha mình và những người trong thành, không dám làm ban ngày, nên đã làm ban đêm.'),
(6683, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 28, 'OT', 'Sáng hôm sau, những người trong thành thức dậy sớm, và nầy, bàn thờ của Ba-al đã bị phá đổ, và cây A-sê-ra gần đó đã bị chặt hạ, và con bò đực thứ hai đã được dâng làm của lễ thiêu trên bàn thờ vừa được xây dựng.'),
(6684, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 29, 'OT', 'Họ nói với nhau: "Ai đã làm việc này?" Rồi họ tra xét, tìm kiếm, và nói rằng: "Ghi-đê-ôn, con trai của Giô-ách, đã làm việc này."'),
(6685, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 30, 'OT', 'Người của thành nói với Giô-ash: "Hãy dẫn con trai ngươi ra để nó chết, vì nó đã phá bàn thờ của Ba-an và chặt cây A-she-ra ở gần đó."'),
(6686, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 31, 'OT', 'Bấy giờ, Giô-ách nói với tất cả những người chống đối mình: "Các ngươi định biện hộ cho Ba-an sao? Các ngươi định cứu nó sao? Ai biện hộ cho nó thì phải bị xử tử trước khi buổi sáng qua đi. Nếu nó là thần thật, chính nó sẽ tự biện hộ cho mình, vì người ta đã đập phá bàn thờ của nó."'),
(6687, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 32, 'OT', 'Ngày ấy, người đặt tên cho ông là Y-ru-ba-al, nói rằng: Ba-anh hãy tranh tụng với ông ấy, vì ông ấy đã phá hủy bàn thờ của thần.'),
(6688, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 33, 'OT', 'Và toàn thể dân Mi-đi-an, A-ma-léc và con cháu phương Đông đều được tập hợp lại với nhau, rồi đi qua và đóng trại trong thung lũng Y-xơ-rê-ên.'),
(6689, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 34, 'OT', 'Nhưng Đức Giê-hô-va mặc lấy Ghi-đê-ôn, và người thổi kèn; rồi toàn thể dòng họ A-bi-ê-xe được triệu tập theo sau người.'),
(6690, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 35, 'OT', 'Người sai các sứ giả đi khắp toàn thể Ma-na-se; và chính họ cũng được tập hợp theo sau người. Người cũng sai các sứ giả đến với Asher, và với Xê-bu-lôn, và với Náp-ta-li; và họ liền lên đường đến gặp họ.'),
(6691, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 36, 'OT', 'Gẹđê-ôn nói với Đức Chúa Trời: "Nếu Ngài thật sự sẽ dùng tay con mà giải cứu Y-sơ-ra-ên, như lời Ngài đã phán,"'),
(6692, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 37, 'OT', 'Này, tôi sẽ đặt một tấm lông chiên xuống sân đập lúa; nếu chỉ có sương đọng trên tấm lông chiên mà khắp đất còn khô ráo, thì tôi sẽ biết rằng Ngài sẽ dùng tay tôi mà cứu Ít-ra-en, như lời Ngài đã phán.'),
(6693, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 38, 'OT', 'Và điều đó đã xảy ra: sáng hôm sau, ông dậy sớm, vắt tấm vải len và vắt sương từ tấm vải len, được đầy một thùng nước.'),
(6694, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 39, 'OT', 'Gẹt-ê-ôn nói với Đức Chúa Trời: Xin đừng nổi giận cùng tôi, tôi chỉ xin nói điều nầy một lần nữa: tôi xin thử một lần nữa bằng cái lông chiên; xin cho chỉ cái lông chiên nầy được khô, còn khắp đất thì có sương sa.'),
(6695, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 6, 40, 'OT', 'Đức Chúa Trời làm như vậy trong đêm đó: chỉ có sương trên tấm vải lông cừu, còn khắp đất thì khô ráo.'),
(6696, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 7, 1, 'OT', 'Rồi Giê-ru-ba-an, tức là Ghi-đê-ôn, cùng với tất cả dân chúng đi theo ông, dậy sớm và đóng trại bên cạnh suối Ha-rod; còn trại quân Ma-đi-an thì ở phía bắc đối diện họ, gần đồi Mô-rê, trong thung lũng.'),
(6697, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 7, 2, 'OT', 'Đức Giê-hô-va phán cùng Ghít-thê: "Dân chúng ở cùng ngươi quá đông để Ta trao dân Mi-đi-an vào tay chúng; e rằng Ít-ra-en khoe mình nghịch cùng Ta mà nói rằng: Chính tay tôi đã cứu tôi."'),
(6698, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 7, 3, 'OT', 'Bây giờ, hãy công bố vào tai dân chúng rằng: "Ai sợ hãi và run rẩy, hãy trở về và rời khỏi núi Ga-la-át." Vậy hai mươi hai ngàn người trong dân chúng đã trở về, còn lại mười ngàn người.'),
(6699, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 7, 4, 'OT', 'Đức Giê-hô-va phán cùng Ghítêôn: "Dân vẫn còn đông. Hãy dẫn họ xuống nước, để Ta thử họ cho ngươi tại đó. Ai mà Ta bảo ngươi: ''Người nầy sẽ đi cùng ngươi,'' thì người ấy sẽ đi cùng ngươi; còn ai mà Ta bảo ngươi: ''Người nầy sẽ không đi cùng ngươi,'' thì người ấy sẽ không đi."'),
(6700, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 7, 5, 'OT', 'Người đưa dân chúng xuống nước. Đức Giê-hô-va phán cùng Ghít-thê: "Ai uống nước bằng lưỡi như chó liếm, ngươi hãy để riêng ra một bên; và ai quỳ gối xuống để uống, ngươi cũng vậy."'),
(6701, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 7, 6, 'OT', 'Số người múc nước bằng tay đưa lên miệng là ba trăm người; còn tất cả những người khác trong dân chúng thì quỳ gối xuống để uống nước.'),
(6702, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 7, 7, 'OT', 'Đức Giê-hô-va phán cùng Ghi-đê-ôn: "Ta sẽ dùng ba trăm người múc nước bằng cách liếm mà giải cứu các ngươi, và phó dân Ma-đi-an vào tay ngươi; còn tất cả dân chúng kia, mỗi người hãy trở về chỗ mình."'),
(6703, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 7, 8, 'OT', 'Dân chúng nhận lấy lương thực trong tay mình và các chiếc tù và của họ; Ghi-đê-ôn giải tán toàn thể dân Ít-ra-en, mỗi người về trại của mình, chỉ giữ lại ba trăm người kia; còn doanh trại của dân Mi-đi-an thì ở dưới thung lũng, gần họ.'),
(6704, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 7, 9, 'OT', 'Đức Giê-hô-va phán cùng người trong đêm ấy: "Hãy chỗi dậy, đi xuống trại quân; vì Ta đã giao nó vào tay ngươi."'),
(6705, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 7, 10, 'OT', 'Nếu ngươi sợ không dám xuống, hãy xuống cùng Phu-rah đầy tớ ngươi đến trại quân địch.'),
(6706, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 7, 11, 'OT', 'Ngươi sẽ nghe điều họ nói; rồi sau đó tay ngươi sẽ được vững mạnh mà đi xuống trại. Vậy người đi xuống cùng Phu-rah, đầy tớ mình, đến tận rìa các toán lính đang ở trong trại.'),
(6707, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 7, 12, 'OT', 'Và người Mi-đi-an, người A-ma-léc và tất cả con cháu phương Đông ở trải đầy trong thung lũng như cào cào về số lượng; còn lạc đà của chúng thì vô số, như cát bên bờ biển về nhiều vô kể.'),
(6708, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 7, 13, 'OT', 'Ghi-đê-ôn đến gần, và nầy, có một người đang thuật lại một giấc mơ cho bạn mình, và nói: "Tôi đã mơ một giấc mơ, và nầy, một chiếc bánh lúa mạch lăn vào trại quân của dân Mi-đi-an, đến gần một cái lều, đụng vào khiến nó đổ xuống, lật úp lại, và cái lều nằm sấp trên mặt đất."'),
(6709, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 7, 14, 'OT', 'Người bạn bè của người ấy đáp và nói: "Đây chẳng phải là gì khác hơn gươm của Ghi-đê-ôn, con trai của Giô-ách, một người Ít-ra-en đâu! Đức Chúa Trời đã trao dân Ma-đi-an và toàn thể đạo quân vào tay người ấy."'),
(6710, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 7, 15, 'OT', 'Khi Ghẹ-đi-ôn nghe kể lại giấc mơ và lời giải nghĩa, ông liền thờ lạy, rồi trở về trại quân Ít-ra-en, và nói: "Hãy đứng dậy! Vì Đức Giê-hô-va đã giao trại quân của Mi-đi-an vào tay các ngươi."'),
(6711, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 7, 16, 'OT', 'Ông chia ba trăm người ấy ra làm ba nhóm, rồi trao kèn vào tay mỗi người, và những cái bình rỗng, cùng những ngọn đuốc ở bên trong các cái bình.'),
(6712, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 7, 17, 'OT', 'Rồi ông nói với họ: "Hãy nhìn tôi và làm theo như vậy. Này, tôi sẽ đến nơi rìa trại quân; và khi tôi làm điều gì, thì các ngươi cũng hãy làm như vậy."'),
(6713, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 7, 18, 'OT', 'Khi ta thổi kèn, ta và tất cả những người cùng ta, thì các ngươi cũng hãy thổi kèn xung quanh khắp doanh trại, và kêu lên: "Gươm cho Đức Giê-hô-va và cho Ghít-eôn!"'),
(6714, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 7, 19, 'OT', 'Ghi-đê-ôn và một trăm người đi với ông đến bên ngoài doanh trại vào đầu canh giữa, lúc các lính canh vừa mới được thay vào; họ thổi kèn và đập vỡ các bình gốm đang ở trong tay mình.'),
(6715, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 7, 20, 'OT', 'Và ba nhóm thổi kèn, đập vỡ các bình, tay trái cầm đuốc, tay phải cầm kèn để thổi; rồi họ kêu lên: Gươm cho Đức Giê-hô-va và cho Ghi-đê-ôn.'),
(6716, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 7, 21, 'OT', 'Họ đứng mỗi người tại chỗ mình, vây quanh doanh trại; và toàn thể đạo quân chạy, kêu la và tháo chạy.'),
(6717, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 7, 22, 'OT', 'Ba trăm người thổi những chiếc tù và; Đức Giê-hô-va khiến gươm của mỗi người quay chống lại đồng bạn mình và khắp toàn trại; toàn trại bèn chạy trốn về phía Bê-thên-sít-ta, cho đến Xê-rê-rát, và đến bờ giáp với A-bên-mê-hô-lah, cho tận Táp-bát.'),
(6718, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 7, 23, 'OT', 'Các người của Y-sơ-ra-ên từ Na-phtha-li, từ A-ser và từ toàn thể Ma-na-xe cùng tụ họp lại và đuổi theo người Mi-đi-an.'),
(6719, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 7, 24, 'OT', 'Ghi-đê-ôn sai các sứ giả đi khắp núi Ép-ra-im, nói rằng: "Hãy xuống nghênh chiến với dân Mi-đi-an và chiếm lấy các chỗ nước trước họ cho đến Bết Ba-rah và sông Giô-đanh." Vậy, tất cả các người nam của Ép-ra-im đều nổi dậy, chiếm lấy các chỗ nước cho đến Bết Ba-rah và sông Giô-đanh.'),
(6720, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 7, 25, 'OT', 'Họ bắt được hai lãnh chúa của dân Mi-đi-an, là Óc và Xíp; họ giết Óc tại vách đá Óc, và giết Xíp tại sân ép rượu Xíp; rồi họ đuổi theo dân Mi-đi-an, và mang đầu của Óc và Xíp đến cho Ghít-thi-ôn bên kia sông Giô-đanh.'),
(6721, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 1, 'OT', 'Người của Ép-ra-im nói với ông: "Ông đã làm điều này với chúng tôi là thế nào, khi không gọi chúng tôi đến giúp, trong khi ông đi đánh giặc với người Mi-đi-an sao?" Rồi họ tranh cãi với ông một cách gay gắt.'),
(6722, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 2, 'OT', 'Người nói với họ: "Tôi đã làm điều gì đây, so sánh với các anh? Há chẳng phải phần sót lại của vụ gặt của Ép-ra-im tốt hơn cả mùa màng của A-bi-ê-xe sao?"'),
(6723, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 3, 'OT', 'Đức Chúa Trời đã phó các lãnh tụ của dân Mi-đi-an, tức là Óc và Xíp, vào tay các ngươi; tôi có thể làm được điều gì so với các ngươi? Khi ông nói lời ấy, thì cơn giận của họ liền dịu xuống nơi ông.'),
(6724, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 4, 'OT', 'Ghi-đê-ôn đến sông Giô-đanh, băng qua cùng ba trăm người theo ông, tất cả đều mệt lả nhưng vẫn tiếp tục đuổi theo.'),
(6725, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 5, 'OT', 'Ông nói với những người thành Súcốt: "Xin hãy cho bánh ăn cho dân theo tôi, vì họ đã mệt; còn tôi, tôi đang đuổi theo Xê-ba và Xanh-mu-na, các vua của Ma-đi-an."'),
(6726, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 6, 'OT', 'Các quan trưởng của Súcốt nói: "Bây giờ tay của Xê-ba và Xanh-mu-na có ở trong tay ngươi sao, mà chúng tôi phải cấp bánh cho đạo binh ngươi?"'),
(6727, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 7, 'OT', 'Ghi-đê-ôn nói: "Vì vậy, khi Đức Giê-hô-va đã trao Zeba và Xalmuna vào tay ta, ta sẽ lấy gai trong đồng vắng và cây gai dại mà đập nát thân thể các ngươi."'),
(6728, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 8, 'OT', 'Ông đi lên từ nơi đó đến Phên-ù-ên, và nói với họ như vậy; và những người đàn ông ở Phên-ù-ên đáp lại ông như thể những người đàn ông ở Xúcốt đã đáp lại.'),
(6729, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 9, 'OT', 'Rồi Gẹc-ba-ên nói cùng những người ở Phên-ù-ên rằng: "Khi tôi trở lại bình an, tôi sẽ phá đổ tháp này."'),
(6730, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 10, 'OT', 'Sê-ba và Xanh-mu-nna đang ở tại Ca-úc, cùng đoàn quân của chúng với khoảng mười lăm ngàn người, tất cả những kẻ còn sót lại trong các đạo quân của con cháu phương Đông; còn số người bị giết là một trăm hai mươi ngàn chiến sĩ rút gươm ra đánh.'),
(6731, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 11, 'OT', 'Ghi-đê-ôn đi lên theo con đường của những người ở lều, về phía đông của Nobah và Jogbeha, rồi đánh vào trại quân; vì trại quân ấy đang yên ổn.'),
(6732, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 12, 'OT', 'Sê-ba và Xanh-mu-na chạy trốn; Ghi-đê-ôn đuổi theo, bắt được hai vua Ma-đi-ên là Sê-ba và Xanh-mu-na, và làm tan tác toàn thể đạo quân.'),
(6733, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 13, 'OT', 'Vậy Ghi-đê-ôn, con trai của Joash, trở về từ trận chiến, từ trên cao nguyên của Heres.'),
(6734, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 14, 'OT', 'Bấy giờ ông bắt một người trai trẻ trong các người của Súcốt, rồi hỏi tra; và người ấy đã viết cho ông danh sách các quan trưởng và các bậc trưởng lão của Súcốt, gồm bảy mươi bảy người.'),
(6735, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 15, 'OT', 'Ông đến cùng những người ở Xúcốt, rồi nói: "Này Xê-ba và Xan-mu-na, những người mà các ngươi đã chế nhạo ta, nói rằng: ''Bây giờ tay Xê-ba và Xan-mu-na đã trong tay ngươi sao, mà ngươi đòi cho bánh ăn cho những người lính mệt mỏi của ngươi?''"'),
(6736, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 16, 'OT', 'Rồi ông lấy các trưởng lão của thành, các gai dại trong đồng vắng và những cây gai, rồi dùng những thứ đó để dạy dỗ dân thành Su-cốt.'),
(6737, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 17, 'OT', 'Và người phá đổ tháp Phên-ù-ên, rồi giết các người đàn ông trong thành.'),
(6738, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 18, 'OT', 'Người hỏi Xê-ba và Xanh-mu-na rằng: "Các người mà các ngươi đã giết tại Ta-bô là người như thế nào?" Họ trả lời: "Họ giống như ngươi, mỗi người đều có vẻ giống con trai vua."'),
(6739, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 19, 'OT', 'Ông ấy nói: "Chúng là anh em tôi, con trai cùng mẹ với tôi. Đức Giê-hô-va hằng sống, nếu các ngươi đã để cho chúng sống, tôi sẽ không giết các ngươi."'),
(6740, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 20, 'OT', 'Ông nói với Y-thẹt, con trai cả của mình: "Hãy chỗi dậy, hãy giết chúng." Nhưng người thanh niên không rút gươm ra, vì anh sợ, vì anh còn trẻ.'),
(6741, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 21, 'OT', 'Zebah và Tsal-mu-na nói: "Hãy đứng dậy, và xông vào chúng tôi; vì sức của người như thế nào thì người ấy mạnh như vậy." Bấy giờ Ghi-đê-ôn đứng dậy, giết Zebah và Tsal-mu-na, rồi lấy các vòng vàng nơi cổ lạc đà của chúng.'),
(6742, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 22, 'OT', 'Dân Y-sơ-ra-ên nói với Ghi-đê-ôn: "Hãy trị vì chúng tôi, cả ngài, con trai ngài, và cháu trai ngài nữa, vì ngài đã giải cứu chúng tôi khỏi tay người Mi-đi-an."'),
(6743, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 23, 'OT', 'Ghi-đê-ôn nói với họ: "Tôi sẽ không cai trị các ông, và con trai tôi cũng sẽ không cai trị các ông; Đức Giê-hô-va sẽ cai trị các ông."'),
(6744, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 24, 'OT', 'Ghi-đê-ôn nói với họ: "Tôi muốn xin anh em một điều, hãy cho tôi mỗi người chiếc bông tai lấy từ chiến lợi phẩm của mình, vì họ có bông tai bằng vàng, bởi họ là người Ích-ma-ên."'),
(6745, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 25, 'OT', 'Họ đáp: "Chúng tôi xin vui lòng dâng." Rồi họ trải một cái áo ra, và mỗi người ném vào đó chiếc vòng tai chiến lợi phẩm của mình.'),
(6746, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 26, 'OT', 'Số cân các khuyên vàng mà người ấy xin là một ngàn bảy trăm sức vàng; không kể các vòng, các hoa tai, và áo xanh tía mà các vua Ma-đi-an đã mặc, cũng không kể các vòng đeo nơi cổ lạc đà của chúng.'),
(6747, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 27, 'OT', 'Ghẹt-thôn làm một cái e-phót bằng vật ấy, rồi đặt nó trong thành mình, tại Ô-phơ-ra; và toàn thể Y-sơ-ra-ên đều đi theo nó mà phạm tội tà dâm tại đó; và điều đó đã trở thành cái bẫy cho Ghẹt-thôn và cho nhà người.'),
(6748, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 28, 'OT', 'Mi-đi-an bị khuất phục trước mặt con cái Ít-ra-en, và chúng không còn dám ngẩng đầu lên nữa. Xứ được yên lặng bốn mươi năm trong những ngày của Ghít-thi-ôn.'),
(6749, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 29, 'OT', 'Và Ghi-đê-ôn, con trai của Yô-ách, đi về và ở lại trong nhà mình.'),
(6750, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 30, 'OT', 'Ghi-đê-ôn có bảy mươi con trai sinh ra từ thân thể ông, vì ông có nhiều vợ.'),
(6751, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 31, 'OT', 'Người hầu thiếp của ông ở Sêm cũng sinh cho ông một người con trai, và ông đặt tên cho con là Áp-hi-mê-léc.'),
(6752, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 32, 'OT', 'Ghi-đê-ôn, con trai của Giô-ách, qua đời trong tuổi già hạnh phúc, và được chôn trong mồ mả của Giô-ách, cha mình, tại Ê-phơ-ra của người A-bi-ê-xơ-rít.'),
(6753, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 33, 'OT', 'Sau khi Ghi-đê-ôn qua đời, con cái Ít-ra-en lại trở lại đi theo các thần Ba-anh, phạm tội tà dâm với các thần ấy và đặt Ba-anh Bê-rit làm thần của mình.'),
(6754, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 34, 'OT', 'Dân Y-sơ-ra-ên không nhớ Đức Giê-hô-va Đức Chúa Trời của mình, là Đấng đã giải cứu họ khỏi tay mọi kẻ thù xung quanh.'),
(6755, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 8, 35, 'OT', 'Họ không tỏ lòng nhân từ với nhà Giê-ru-ba-an, tức là Ghi-đê-ôn, y như mọi điều tốt lành mà ông đã làm cho Y-sơ-ra-ên.'),
(6756, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 1, 'OT', 'A-bi-mê-léc, con trai của Giê-ru-ba-anh, đi đến Sêm gặp các anh em của mẹ mình, rồi nói chuyện với họ và với cả gia đình nhà cha của mẹ mình, rằng:'),
(6757, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 2, 'OT', 'Hãy nói, ta xin các ngươi, vào tai mọi người của các chủ Sêm: Điều nào tốt hơn cho các ngươi, là bảy mươi người, tất cả con trai của Y-ru-ba-an, cai trị các ngươi, hay là một người cai trị các ngươi? Cũng hãy nhớ rằng ta là xương cốt và thịt của các ngươi.'),
(6758, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 3, 'OT', 'Anh em của người mẹ ông nói về ông với tất cả những người đàn ông ở Sêm những lời nầy; và lòng họ theo A-bi-mê-léc, vì họ nói: Ông ấy là anh em chúng ta.'),
(6759, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 4, 'OT', 'Họ đưa cho ông bảy mươi miếng bạc từ đền của Ba-al Bê-rit, và bằng số bạc đó, A-bi-mê-léc đã thuê những người vô tích sự và liều lĩnh, và họ đi theo ông.'),
(6760, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 5, 'OT', 'Người đi đến nhà cha mình tại Ô-phơ-ra, rồi giết các anh em mình, những con trai của Giê-ru-ba-ên, bảy mươi người, trên một tảng đá; nhưng Giô-tham, con trai út của Giê-ru-ba-ên, được sót lại, vì người đã giấu mình.'),
(6761, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 6, 'OT', 'Toàn thể những người thuộc thành Sêm và toàn thể gia đình Míp-lô đã tụ họp lại, rồi đi đến và tôn A-bi-mê-léc làm vua, tại cây sồi thờ thần đứng ở Sêm.'),
(6762, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 7, 'OT', 'Khi người ta thuật lại cho Giô-tham nghe, ông đi ra, đứng trên đỉnh núi Ghê-ri-xim, cất cao tiếng nói và kêu lớn rằng: "Hỡi các người dân Si-chem, hãy nghe tôi, để Đức Chúa Trời nghe các ông."'),
(6763, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 8, 'OT', 'Các cây đi ra để xức vua cho mình, và chúng nói với cây ô liu: "Hãy trị vì trên chúng tôi."'),
(6764, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 9, 'OT', 'Bấy giờ cây ô-liu nói với chúng nó: "Tôi há bỏ được chất mỡ của tôi, tức là điều nhờ đó người ta tôn kính Đức Chúa Trời và loài người, mà đi lay động trên các cây cối sao?"'),
(6765, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 10, 'OT', 'Bấy giờ các cây nói với cây vả: "Hãy đến, hãy làm vua cai trị chúng tôi."'),
(6766, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 11, 'OT', 'Bấy giờ cây vả nói với chúng rằng: "Tôi há sẽ bỏ sự ngọt ngào và trái tốt lành của tôi để đi rung rinh trên các cây cối sao?"'),
(6767, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 12, 'OT', 'Các cây nói với cây nho: "Hãy đến, hãy cai trị chúng tôi."'),
(6768, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 13, 'OT', 'Rồi cây nho nói với chúng: "Tôi phải bỏ rượu của tôi, thứ làm cho Đức Chúa Trời và loài người vui vẻ sao, rồi đi lay động trên các cây cối?"'),
(6769, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 14, 'OT', 'Bấy giờ, tất cả các cây đều nói với cây gai: "Hãy đến, ngươi hãy làm vua cai trị chúng ta."'),
(6770, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 15, 'OT', 'Rồi cây gai dại nói với các cây cối: "Nếu các ngươi thực sự xức dầu cho ta làm vua cai trị các ngươi, thì hãy đến nương bóng dưới ta. Còn nếu không, thì lửa sẽ bùng ra từ cây gai dại, thiêu cháy các cây bá hương ở Li-băng."'),
(6771, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 16, 'OT', 'Bây giờ, nếu các ngươi thật lòng và trung thực khi làm cho A-bi-mê-léc làm vua, nếu các ngươi đã đối xử tốt với Giê-ru-ba-an và nhà ông ấy, và đã đối xử với ông theo công việc tay ông làm,'),
(6772, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 17, 'OT', 'Cha ta đã chiến đấu vì các ngươi, liều mạng mình chống lại, và giải cứu các ngươi khỏi tay người Mi-đi-an.'),
(6773, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 18, 'OT', 'Còn các ngươi, hôm nay các ngươi đã nổi dậy chống lại nhà cha ta, giết bảy mươi người con trai của ông trên một tảng đá, và đã tôn A-bi-mê-léc, con trai của nữ tớ hầu của ông, làm vua trên những người thành Sêm, vì nó là anh em các ngươi.'),
(6774, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 19, 'OT', 'Nếu các ngươi đã thực sự và chân thành đối xử với Y-rơ-ba-an và nhà của người hôm nay, thì hãy vui mừng vì A-bi-mê-léc, và chính người cũng hãy vui mừng vì các ngươi.'),
(6775, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 20, 'OT', 'Nhưng nếu không, nguyện lửa phát ra từ A-bi-mê-léc mà thiêu hủy những người của Sêm và nhà Mi-lô; và nguyện lửa phát ra từ những người của Sêm và nhà Mi-lô mà thiêu hủy A-bi-mê-léc.'),
(6776, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 21, 'OT', 'Vậy Giô-tham chạy trốn, và đi đến Bê-e-ra, rồi ở đó, vì sợ A-bi-mê-léc, anh mình.'),
(6777, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 22, 'OT', 'A-bi-mê-léc cai trị trên Ít-ra-en ba năm.'),
(6778, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 23, 'OT', 'Đức Chúa Trời sai một thần dữ đến giữa A-bi-mê-léc và những người ở Sêm, và những người ở Sêm đã phản nghịch A-bi-mê-léc.'),
(6779, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 24, 'OT', 'Để sự hung bạo đối với bảy mươi con trai của Y-rơ-ba-an và huyết của họ được đổ trên A-bi-mê-léc, anh em chúng, là người đã giết họ, và trên những người thành Sêm, là những kẻ đã giúp tay cho hắn giết các anh em mình.'),
(6780, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 25, 'OT', 'Các lãnh chúa của Si-chem đặt những toán mai phục cho ông trên các đỉnh núi, và họ cướp hết thảy những ai đi ngang qua đó trên đường; điều đó được báo cho A-bi-mê-léc biết.'),
(6781, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 26, 'OT', 'Ga-anh, con trai của Ébed, cùng các anh em mình đến và đi ngang qua Sêm; và các người lãnh đạo Sêm đã tin cậy nơi người.'),
(6782, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 27, 'OT', 'Họ ra đồng, hái nho trong các vườn nho mình, đạp ép, tổ chức tiệc vui, rồi vào nhà thần của mình, ăn uống và rủa sả A-bi-mê-léc.'),
(6783, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 28, 'OT', 'Ga-anh, con trai của Ebed, nói: "A-bi-mê-léc là ai, và Sêm là ai, mà chúng ta phải phục vụ hắn? Hắn chẳng phải là con trai của Yê-ru-ba-al hay sao? Và Xê-bun, viên chức của hắn? Hãy phục vụ những người của Ha-mô, cha của Sêm; tại sao chúng ta phải phục vụ hắn?"'),
(6784, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 29, 'OT', 'Ước chi dân sự nầy được trao vào tay ta, để ta đuổi được A-bi-mê-léc! Rồi người nói cùng A-bi-mê-léc rằng: Hãy tăng thêm đạo quân ngươi và ra đi!'),
(6785, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 30, 'OT', 'Zê-bun, quan tổng quản thành ấy, nghe thấy các lời của Ga-an, con trai Ê-bết, thì nổi giận.'),
(6786, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 31, 'OT', 'Người sai các sứ giả đến A-bi-mê-léc cách kín đáo, nói rằng: Này, Ga-anh con trai của Ebed và các anh em người đã đến Shechem; và này, họ đang bao vây thành chống lại ngươi.'),
(6787, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 32, 'OT', 'Vì vậy, bây giờ hãy chỗi dậy đi ban đêm, ngươi và dân sự đi cùng ngươi, rồi phục kích trong đồng vắng.'),
(6788, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 33, 'OT', 'Và sẽ xảy ra vào buổi sáng, khi mặt trời mọc lên, ngươi hãy chỗi dậy sớm và xông vào thành; và nầy, khi hắn và dân chúng đi theo hắn đi ra nghênh chiến ngươi, thì ngươi hãy làm cho hắn điều gì mà tay ngươi thấy thuận tiện.'),
(6789, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 34, 'OT', 'A-bi-mê-léc cùng toàn thể dân chúng đi theo ông trỗi dậy vào ban đêm, rồi rình phục kích tại bốn điểm quanh Sêm.'),
(6790, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 35, 'OT', 'Ga-anh, con trai của Ébed, đi ra và đứng tại lối vào cổng thành; rồi A-bi-mê-léc cùng những người đi theo ông ấy đứng dậy từ nơi phục kích.'),
(6791, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 36, 'OT', 'Ga-a-l thấy dân chúng, liền nói với Xê-bun: "Nầy, có một đoàn người đang xuống từ các đỉnh núi." Xê-bun đáp lại người rằng: "Ngươi thấy bóng các ngọn núi, mà tưởng như là người."'),
(6792, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 37, 'OT', 'Gaan lại tiếp tục nói và rằng: Này, dân chúng đang đi xuống từ giữa đất, và một nhóm khác đang đến từ hướng đường cái của Ê-lôn-Meô-nên.'),
(6793, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 38, 'OT', 'Bấy giờ Xê-bun nói với người rằng: "Miệng ngươi nay ở đâu rồi, tức miệng đã nói: ''A-bi-mê-léc là ai mà chúng ta phải phục vụ hắn?'' Chẳng phải đây là dân mà ngươi đã khinh dể sao? Vậy hãy đi ra, và chiến đấu với họ đi!"'),
(6794, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 39, 'OT', 'Và Ga-an đi ra trước mặt các chủ nhân của Sêm, rồi giao chiến với A-bi-mê-léc.'),
(6795, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 40, 'OT', 'A-bi-mê-léc đuổi theo người ấy, và người ấy chạy trốn khỏi mặt người; nhiều người bị ngã gục, chết chất đầy cho đến ngay cửa thành.'),
(6796, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 41, 'OT', 'A-bi-mê-léc ở tại A-ru-ma; còn Xê-bun thì đuổi Ga-an và các anh em người khỏi ở tại Si-chem.'),
(6797, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 42, 'OT', 'Ngày hôm sau, dân chúng ra đồng, và họ báo tin cho A-bi-mê-léc.'),
(6798, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 43, 'OT', 'Ông đem dân chúng, chia họ ra làm ba nhóm, rồi phục kích trong đồng vắng. Ông nhìn thấy, nầy, dân chúng đi ra khỏi thành phố; ông liền đứng lên nghênh chiến với họ và đánh bại họ.'),
(6799, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 44, 'OT', 'A-bi-mê-léc cùng những người lãnh đạo đi theo ông xông tới, đứng tại lối vào cổng thành; còn hai nhóm lãnh đạo kia thì xông vào tất cả những người ở ngoài đồng và đánh giết họ.'),
(6800, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 45, 'OT', 'A-bi-mê-léc giao chiến với thành ấy suốt cả ngày đó; người chiếm được thành, giết dân cư trong thành, phá hủy thành ấy và rải muối lên đó.'),
(6801, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 46, 'OT', 'Và khi tất cả những người ở tháp Sêm nghe điều đó, thì họ vào nơi an toàn trong đền thờ của thần Ên Bê-rít.'),
(6802, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 47, 'OT', 'Và người ta báo cho A-bi-mê-léc biết rằng tất cả những người ở tháp Si-chem đã tụ họp lại.'),
(6803, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 48, 'OT', 'A-bi-mê-léc lên núi Xal-môn, cùng với mọi người đi theo ông. A-bi-mê-léc cầm rìu trong tay, chặt một nhánh cây từ rừng, vác lên vai mình, rồi nói với dân chúng đi theo ông: "Điều các ngươi thấy ta làm, hãy mau làm như ta đã làm."'),
(6804, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 49, 'OT', 'Dân chúng cũng đều hái mỗi người một nhánh, rồi đi theo A-bi-mê-léc, chất các nhánh vào trong tháp, và đốt tháp lên bằng lửa; và tất cả những người trong tháp của Si-chem đều chết, khoảng một ngàn người nam và nữ.'),
(6805, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 50, 'OT', 'A-bi-mê-léc đi đến Thê-bết, đóng trại quanh Thê-bết và chiếm lấy thành ấy.'),
(6806, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 51, 'OT', 'Có một tháp kiên cố ở giữa thành, và toàn thể những người nam và nữ, cùng tất cả dân trong thành, đều chạy trốn đến đó, rồi đóng cửa lại với mình và lên nóc tháp.'),
(6807, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 52, 'OT', 'A-bi-mê-léc tiến đến tháp và giao chiến với nó; ông tiến sát đến cửa tháp để đốt nó bằng lửa.'),
(6808, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 53, 'OT', 'Một người phụ nữ ném một tảng đá xay vào đầu A-bi-mê-léc, và vỡ sọ người ấy.'),
(6809, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 54, 'OT', 'Vậy người vội gọi người trai trẻ mang khí giới cho mình, và bảo người ấy: "Hãy rút gươm ngươi mà giết ta, để người ta không nói về ta rằng một người đàn bà đã giết ta." Người trai trẻ bèn đâm người, và người chết.'),
(6810, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 55, 'OT', 'Khi người Ít-ra-en thấy A-bi-mê-léc đã chết, thì mỗi người đều đi về nơi mình.'),
(6811, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 56, 'OT', 'Đức Chúa Trời khiến cho sự ác mà A-bi-mê-léc đã làm cùng cha mình, là giết bảy mươi anh em ruột của mình, trở lại trên đầu hắn.'),
(6812, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 9, 57, 'OT', 'Đức Chúa Trời khiến cho mọi điều ác mà những người thành Sêm đã làm đổ xuống đầu họ, và lời nguyền rủa của Yô-tham, con trai Giê-ru-ba-an, đã giáng trên họ.'),
(6813, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 10, 1, 'OT', 'Sau khi A-bi-mê-léc qua đời, Tô-la, con trai của Pu-ách, cháu trai của Đô-đô, một người thuộc chi phái Y-xa-sa-cha, nổi dậy để cứu Ít-ra-en; người ấy sống tại Xa-mi-er, trên núi Ép-ra-im.'),
(6814, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 10, 2, 'OT', 'Ông cai trị Y-sơ-ra-ên hai mươi ba năm, rồi qua đời và được chôn cất tại Sâm-ia.'),
(6815, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 10, 3, 'OT', 'Sau người ấy, Gi-ai-ách, người Ghít-xa-đi, nổi dậy và xét xử Ít-ra-en hai mươi hai năm.'),
(6816, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 10, 4, 'OT', 'Ông có ba mươi người con trai, cỡi ba mươi lừa đực, và họ có ba mươi thành phố; người ta gọi các thành ấy là Các làng Cha-ir cho đến ngày nay, là những nơi tại đất Gi-lean.'),
(6817, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 10, 5, 'OT', 'Yai-rơ qua đời và được chôn cất tại Ca-môn.'),
(6818, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 10, 6, 'OT', 'Con cái Y-sơ-ra-ên lại tiếp tục làm điều ác trước mặt Đức Giê-hô-va, thờ lạy các thần Ba-an, các thần Át-ta-rốt, các thần của người Sy-ri, các thần của Xi-đôn, các thần của người Mô-áp, các thần của con cái Am-môn, và các thần của người Phi-li-tin; chúng từ bỏ Đức Giê-hô-va và không phục vụ Ngài.'),
(6819, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 10, 7, 'OT', 'Đức Giê-hô-va nổi giận cùng Y-sơ-ra-ên, và Ngài bán họ vào tay người Phi-li-tin và vào tay con cháu Am-môn.'),
(6820, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 10, 8, 'OT', 'Họ đã hành hạ và áp bức con cái Ít-ra-en trong năm ấy: mười tám năm, đối với tất cả con cái Ít-ra-en ở bên kia sông Giô-đanh, trong xứ của người A-mô-rít, tức là tại Ga-la-át.'),
(6821, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 10, 9, 'OT', 'Các con trai của Am-môn đã qua sông Giô-đanh để gây chiến cùng với Giu-đa, cùng với Bên-gia-min, và cùng với nhà Ép-ra-im; và điều đó khiến cho Ít-ra-en bị khốn khổ rất nhiều.'),
(6822, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 10, 10, 'OT', 'Con cái Y-sơ-ra-ên kêu khóc cùng Đức Giê-hô-va, nói rằng: Chúng tôi đã phạm tội cùng Ngài, vì chúng tôi đã từ bỏ Đức Chúa Trời chúng tôi và phục sự các thần Ba-al.'),
(6823, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 10, 11, 'OT', 'Đức Giê-hô-va phán cùng con cái Ít-ra-en: "Chẳng phải Ta đã giải cứu các ngươi khỏi người Ê-díp-tô, khỏi người A-mô-rít, khỏi con cái Am-môn và khỏi người Phi-li-tin sao?"'),
(6824, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 10, 12, 'OT', 'Người Xi-đô-ni, người A-ma-léc và người Ma-on đã ngược đãi các ngươi; các ngươi kêu cứu cùng ta, và ta đã giải cứu các ngươi khỏi tay chúng nó.'),
(6825, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 10, 13, 'OT', 'Các ngươi đã từ bỏ Ta và thờ các thần khác; vì vậy Ta sẽ không còn cứu các ngươi nữa.'),
(6826, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 10, 14, 'OT', 'Hãy đi kêu lên các thần mà các ngươi đã chọn; chính chúng sẽ cứu các ngươi trong lúc hoạn nạn của các ngươi.'),
(6827, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 10, 15, 'OT', 'Các con trai của Y-sơ-ra-ên nói với Đức Giê-hô-va: "Chúng tôi đã phạm tội. Xin Ngài làm điều tốt lành theo mắt Ngài thấy đối với chúng tôi. Nhưng xin hãy giải cứu chúng tôi ngày nay."'),
(6828, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 10, 16, 'OT', 'Họ dẹp bỏ các thần ngoại bang khỏi giữa họ và thờ phượng Đức Giê-hô-va; thì Ngài cảm động lòng thương xót trước cảnh khốn khổ của Y-sơ-ra-ên.'),
(6829, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 10, 17, 'OT', 'Các con trai của Am-môn bèn nhóm lại, và đóng trại tại Ghi-lê-át. Các con trai của Ít-ra-ên cũng nhóm lại với nhau, và đóng trại tại Mít-pa.'),
(6830, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 10, 18, 'OT', 'Các dân sự và các thủ lĩnh xứ Ga-la-át nói mỗi người với người kia: "Người nào sẽ là người khởi sự đánh giặc cùng con cái Am-môn, người ấy sẽ làm đầu cho mọi người ở Ga-la-át."'),
(6831, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 1, 'OT', 'Ghẹp-tha người Ghinh-ê-át là một người anh hùng dũng cảm, và ông là con trai của một người đàn bà điếm; Ghinh-ê-át sinh ra Ghẹp-tha.'),
(6832, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 2, 'OT', 'Vợ của Ghít-đôn sinh cho ông các con trai; các con trai người vợ lớn lên, rồi xua đuổi Y-phát, và nói với ông: "Ngươi không được hưởng cơ nghiệp trong nhà cha chúng ta, vì ngươi là con của một người đàn bà khác."'),
(6833, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 3, 'OT', 'Vậy Jáp-tha phải trốn tránh mặt các anh mình, rồi đi ở trong đất Tôp; và có những người vô trị tụ họp về cùng Jáp-tha, rồi ra đi với ông.'),
(6834, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 4, 'OT', 'Sau những ngày đó, con cái Am-môn đã gây chiến cùng Ít-ra-en.'),
(6835, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 5, 'OT', 'Khi con cái Am-môn gây chiến cùng Ít-ra-en, thì các trưởng lão của Ghi-lê-át đi đến để đón Y-phách từ xứ Tôb.'),
(6836, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 6, 'OT', 'Họ nói với Y-phách: "Hãy đến, hãy làm lãnh tụ cho chúng tôi, để chúng tôi chiến đấu chống lại con cái của dân Am-môn."'),
(6837, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 7, 'OT', 'Y-phi-tha nói với các trưởng lão của Ghi-lê-át: "Chẳng phải các ông ghét tôi và đuổi tôi ra khỏi nhà cha tôi sao? Vậy tại sao bây giờ các ông lại đến cùng tôi khi các ông đang gặp hoạn nạn?"'),
(6838, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 8, 'OT', 'Các trưởng lão của Ga-la-át nói với Y-phát: "Chính vì lý do này mà hiện nay chúng tôi trở lại tìm ông, để ông đi cùng chúng tôi, đánh giặc với con cái Am-môn, và làm đầu lãnh của mọi người dân ở Ga-la-át."'),
(6839, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 9, 'OT', 'Và Y-phúc nói với các trưởng lão của Ghinh-ê-át: Nếu các ông mang tôi trở về để chiến đấu chống lại con cái của Am-môn, và Đức Giê-hô-va trao chúng vào tay tôi, thì tôi sẽ làm đầu cho các ông.'),
(6840, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 10, 'OT', 'Các trưởng lão của Gileát nói với Y-phách: Đức Giê-hô-va sẽ làm chứng giữa chúng ta; nếu chúng tôi không làm theo lời ông như vậy.'),
(6841, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 11, 'OT', 'Vậy Giép-tha đi cùng các trưởng lão của Ga-la-át, và dân chúng lập ông làm lãnh tụ và quan xét cai trị họ. Giép-tha nói hết mọi lời của mình trước mặt Đức Giê-hô-va tại Mít-pah.'),
(6842, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 12, 'OT', 'Ghẹt-tha sai các sứ giả đến cùng vua con cái Am-môn, nói rằng: Ngươi có điều gì với ta, mà ngươi đến cùng ta để chiến đấu trên đất nước ta?'),
(6843, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 13, 'OT', 'Vua của con cái Amôn nói với các sứ giả của Y-phát: "Vì Y-sơ-ra-ên đã chiếm đất của ta khi họ lên từ Ai Cập, từ sông A-rôn cho đến sông Gia-bốc và cho đến sông Giô-đanh. Bây giờ, hãy trả lại những vùng đất ấy cho ta một cách hòa bình."'),
(6844, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 14, 'OT', 'Và Jip-ta tiếp tục sai các sứ giả đến vua con cái Am-môn.'),
(6845, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 15, 'OT', 'Và người nói với ông rằng: "Jip-ta nói như vầy: ''Ít-ra-en đã không chiếm lấy đất của Mô-áp, cũng chẳng chiếm lấy đất của con cái Am-môn.''"'),
(6846, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 16, 'OT', 'Khi dân Y-sơ-ra-ên đi lên từ Ai Cập, họ đi qua đồng vắng cho đến Biển Đỏ, rồi đến Ca-đết.'),
(6847, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 17, 'OT', 'Y-sơ-ra-ên sai các sứ giả đến vua Ê-đôm, nói rằng: Xin hãy để tôi đi ngang qua đất nước ngài; nhưng vua Ê-đôm không chịu nghe. Họ cũng sai đến vua Mô-áp, nhưng người ấy cũng không chịu đồng ý. Vậy Y-sơ-ra-ên ở lại tại Ca-đe.'),
(6848, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 18, 'OT', 'Họ đi qua đồng vắng, vòng quanh đất Ê-đôm và đất Mô-áp, rồi đến từ phía đông mặt trời lên đến đất Mô-áp và đóng trại bên kia sông A-r-non; nhưng họ không vào trong lãnh thổ Mô-áp, vì sông A-r-non là ranh giới của Mô-áp.'),
(6849, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 19, 'OT', 'Y-sơ-ra-ên sai các sứ giả đến Si-hôn, vua dân A-mô-rít, vua thành Hết-bôn; và Y-sơ-ra-ên nói với người: "Xin cho chúng tôi đi qua đất của ngài đến nơi của chúng tôi."'),
(6850, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 20, 'OT', 'Nhưng Xi-hôn không tin để Ít-ra-en đi qua vùng biên giới của mình; vì thế Xi-hôn tập hợp toàn thể dân mình, đóng trại tại Gia-hát, và giao chiến với Ít-ra-en.'),
(6851, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 21, 'OT', 'Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên đã trao Si-hôn và toàn dân người vào tay Y-sơ-ra-ên, và họ đánh bại chúng; rồi Y-sơ-ra-ên chiếm lấy toàn bộ đất đai của người A-mô-rít, là những kẻ đang cư ngụ trong xứ ấy.'),
(6852, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 22, 'OT', 'Họ chiếm hữu toàn bộ vùng đất của người Amôrì, từ sông Arnôn cho đến sông Yabbôc, và từ đồng vắng cho đến sông Giô-đanh.'),
(6853, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 23, 'OT', 'Bây giờ, Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên đã đuổi dân A-mô-rít ra khỏi trước mặt dân Y-sơ-ra-ên, vậy mà ngươi lại muốn chiếm lấy đất ấy sao?'),
(6854, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 24, 'OT', 'Chẳng phải ngươi sẽ chiếm hữu điều mà Chemôs, thần của ngươi, ban cho ngươi sao? Cũng vậy, chúng ta sẽ chiếm hữu điều mà Đức Giê-hô-va, Đức Chúa Trời của chúng ta, đuổi ra khỏi trước mặt chúng ta.'),
(6855, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 25, 'OT', 'Bây giờ, ngươi có tốt hơn Ba-lác, con trai Xíp-phô, vua xứ Mô-áp chăng? Phải chăng người ấy đã từng tranh tụng với Y-sơ-ra-ên, hay từng chiến đấu với họ chăng?'),
(6856, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 26, 'OT', 'Khi dân Y-sơ-ra-ên ở tại Hết-bôn và các thị trấn thuộc về nó, tại A-rô-er và các thị trấn thuộc về nó, và tại mọi thành phố dọc theo hai bên bờ sông A-nôn suốt ba trăm năm trời, vậy mà sao các ngươi không giành lại những nơi ấy trong thời gian đó?'),
(6857, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 27, 'OT', 'Ta không hề phạm tội gì cùng ngươi, nhưng ngươi lại làm điều ác khi đem quân đánh ta. Đức Giê-hô-va, Đấng xét xử, sẽ hôm nay phân xử giữa con cái Ít-ra-en và con cái Am-môn.'),
(6858, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 28, 'OT', 'Vua của con cái Am-môn không chịu nghe các lời mà Y-phách đã sai đến cho ông.'),
(6859, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 29, 'OT', 'Rồi Đức Giê-hô-va đặt thần trên Y-phát, và ông đi qua Ga-la-át và Ma-na-xe, rồi đi qua Mít-peh ở Ga-la-át, và từ Mít-peh ở Ga-la-át, ông đi đến các con trai của Am-môn.'),
(6860, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 30, 'OT', 'Ghẹt-tha lập một lời khấn nguyện cùng Đức Giê-hô-va và nói: Nếu Ngài chắc chắn giao con cái của Am-môn vào tay tôi,'),
(6861, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 31, 'OT', 'Thì điều gì ra khỏi cửa nhà tôi để đón tôi, khi tôi trở về bình an từ các con trai của Am-môn, điều đó sẽ thuộc về Đức Giê-hô-va, và tôi sẽ dâng nó làm của lễ thiêu.'),
(6862, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 32, 'OT', 'Giu-đèp đi ngang qua đến cùng con cái Am-môn để đánh giặc với chúng; và Đức Giê-hô-va đã nộp chúng vào tay người.'),
(6863, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 33, 'OT', 'Người đánh bại họ từ A-rô-er cho đến khi đến Min-nít, hai mươi thành phố, và cho đến đồng bằng A-bên các vườn nho, bằng một cuộc đánh giết rất lớn; và con cái Am-môn bị khuất phục trước mặt con cái Ít-ra-en.'),
(6864, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 34, 'OT', 'Sau đó, Yiphtach trở về Mizpeh, đến nhà mình, và nầy, con gái ông đi ra đón ông, cầm trống và nhảy múa; cô là con một, ngoài cô ra, ông không có con trai hay con gái nào khác.'),
(6865, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 35, 'OT', 'Khi thấy nàng, ông xé rách quần áo mình và nói: "Than ôi, con gái ta! Con làm ta đau đớn biết bao, và chính con là người làm ta khốn khổ! Vì ta đã mở miệng khấn Đức Giê-hô-va, và ta không thể rút lại được."'),
(6866, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 36, 'OT', 'Bà nói với ông: "Thưa cha, cha đã mở miệng khấn hứa với Đức Giê-hô-va, xin cha làm cho con theo điều đã ra từ miệng cha, sau khi Đức Giê-hô-va đã báo thù cho cha, khiến các kẻ thù của cha, tức con cái Am-môn, phải khuất phục cha."'),
(6867, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 37, 'OT', 'Bà ấy nói với cha mình: "Xin hãy làm điều nầy cho con: để con được tự do hai tháng; con sẽ đi lên xuống trên các núi và than khóc vì sự đồng trinh của con, con và các bạn con."'),
(6868, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 38, 'OT', 'Và ông nói: "Hãy đi." Rồi ông cho cô đi trong hai tháng. Cô cùng các bạn mình ra đi, và than khóc đời trinh nữ của cô trên các ngọn núi.'),
(6869, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 39, 'OT', 'Hai tháng sau, cô trở về cùng cha mình, và ông đã làm cho cô điều mà ông đã hứa theo lời khấn của mình; cô chưa từng biết đến người đàn ông nào. Việc đó đã trở thành một phong tục tại Y-sơ-ra-ên.'),
(6870, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 11, 40, 'OT', 'Hằng năm, các con gái Y-sơ-ra-ên đi ra để than khóc con gái của Y-phách, người Ghi-lê-át, bốn ngày mỗi năm.'),
(6871, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 12, 1, 'OT', 'Các người của Ép-ra-im tụ họp lại, đi về phía bắc, và nói với Y-ftp-tha: "Tại sao ngươi qua sông để đánh con cái Am-môn mà không gọi chúng ta đi cùng ngươi? Chúng ta sẽ đốt nhà ngươi bằng lửa."'),
(6872, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 12, 2, 'OT', 'Và Y-phách nói với họ: "Tôi và dân tôi đã có một cuộc tranh chấp lớn với con cái Am-môn; khi tôi kêu cầu các ông, các ông đã không giải cứu tôi khỏi tay chúng."'),
(6873, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 12, 3, 'OT', 'Tôi thấy rõ các ngươi không chịu giải cứu, nên tôi liều mạng mình mà đánh các con trai của Am-môn, và Đức Giê-hô-va đã nộp họ vào tay tôi. Vậy thì hôm nay các ngươi đến cùng tôi để chiến đấu vì cớ gì?'),
(6874, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 12, 4, 'OT', 'Đoạn Yiphtach tập hợp tất cả những người của Ga-la-át, rồi giao chiến với Ép-ra-im; và những người của Ga-la-át đánh bại Ép-ra-im, vì họ nói: "Các ngươi là những người trốn chạy khỏi Ép-ra-im, hỡi người Ga-la-át, giữa Ép-ra-im và giữa Ma-na-se."'),
(6875, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 12, 5, 'OT', 'Bấy giờ, người Ga-la-át bắt giữ các bến qua sông Giô-đanh khỏi tay người Ép-ra-im. Xảy ra rằng khi những người Ép-ra-im trốn thoát xin đi qua, thì người Ga-la-át hỏi người ấy rằng: "Ngươi có phải là người Ép-ra-im không?" Nếu người ấy nói: "Không,"'),
(6876, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 12, 6, 'OT', 'Họ bảo người ấy: "Hãy nói thử ''Sê-bô-lết''." Người ấy nói: "Xi-bô-lết," vì không thể phát âm đúng được. Vậy họ bắt người ấy và giết tại các bến qua sông Giô-đanh. Trong thời điểm ấy, bốn mươi hai ngàn người Ép-ra-im đã ngã xuống.'),
(6877, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 12, 7, 'OT', 'Ê-phi-ta đã xét xử Y-sơ-ra-ên trong sáu năm. Sau đó, Ê-phi-ta người Ghít-le-át qua đời và được chôn trong các thành của Ghít-le-át.'),
(6878, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 12, 8, 'OT', 'Sau người ấy, Íp-xan, người Bết-lê-hem, xét xử cho Ít-ra-en.'),
(6879, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 12, 9, 'OT', 'Người có ba mươi con trai và ba mươi con gái; người cho ba mươi con gái đi lấy chồng nơi khác, và lấy ba mươi con gái từ nơi khác về cho ba mươi con trai mình. Người cai trị cho Y-sơ-ra-ên bảy năm.'),
(6880, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 12, 10, 'OT', 'Rồi Íp-xan qua đời và được chôn cất tại Bết-lê-hem.'),
(6881, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 12, 11, 'OT', 'Ê-lôn, người Xê-bu-lôn, xét xử cho Ít-ra-en sau người ấy; và ông xét xử cho Ít-ra-en mười năm.'),
(6882, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 12, 12, 'OT', 'Ê-lôn người Xê-bu-lôn qua đời, và được chôn tại Ai-ga-lôn, trong đất Xê-bu-lôn.'),
(6883, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 12, 13, 'OT', 'Sau người, Áp-đôn con trai của Hi-lên, người Pi-ra-thôn, xét xử Ít-ra-en.'),
(6884, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 12, 14, 'OT', 'Và người có bốn mươi con trai và ba mươi cháu trai, cỡi bảy mươi lừa con; người xét xử cho Y-sơ-ra-ên tám năm.'),
(6885, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 12, 15, 'OT', 'Ab-đôn, con trai của Hi-lên người Pi-ra-thôn, qua đời và được chôn cất tại Pi-ra-thôn, trong đất Ép-ra-im, trên núi của người A-ma-léc.'),
(6886, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 13, 1, 'OT', 'Dân Y-sơ-ra-ên lại tiếp tục làm điều ác trước mặt Đức Giê-hô-va, nên Đức Giê-hô-va đã trao họ vào tay người Phi-li-tin trong bốn mươi năm.'),
(6887, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 13, 2, 'OT', 'Có một người đàn ông ở Xô-ra, thuộc dòng họ Đan, tên là Ma-nô-a; vợ ông son sẻ, không sinh được con.'),
(6888, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 13, 3, 'OT', 'Thiên sứ của Đức Giê-hô-va hiện ra cùng người đàn bà và nói với nàng rằng: Này, nàng son sẻ, chưa hề sinh con; nhưng nàng sẽ thụ thai và sinh một con trai.'),
(6889, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 13, 4, 'OT', 'Vì vậy, bây giờ hãy cẩn thận, và đừng uống rượu hay rượu mạnh, cũng đừng ăn bất cứ vật gì không sạch.'),
(6890, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 13, 5, 'OT', 'Này, ngươi sẽ mang thai và sinh một con trai; dao cạo sẽ không được chạm đến đầu nó, vì đứa trẻ sẽ là một người biệt riêng cho Đức Chúa Trời ngay từ trong lòng mẹ; và nó sẽ khởi sự giải cứu Y-sơ-ra-ên khỏi tay người Phi-li-tin.'),
(6891, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 13, 6, 'OT', 'Người đàn bà về nhà và nói với chồng mình: "Một người của Đức Chúa Trời đã đến cùng tôi, và vẻ ngoài của ông ta giống như vẻ ngoài của một thiên sứ Đức Chúa Trời, rất oai nghiêm và đáng sợ. Tôi đã không hỏi ông ấy từ đâu đến, và ông ấy cũng không tiết lộ cho tôi danh tánh của mình."'),
(6892, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 13, 7, 'OT', 'Người phán cùng tôi: "Nầy, ngươi sẽ mang thai và sinh một trai. Vậy bây giờ, chớ uống rượu, bia, và chớ ăn bất cứ vật gì ô uế, vì đứa trẻ sẽ là một người biệt riêng cho Đức Chúa Trời ngay từ lúc trong lòng mẹ cho đến ngày nó chết."'),
(6893, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 13, 8, 'OT', 'Ma-nô-a cầu khẩn Đức Giê-hô-va và nói: Ôi, thưa Chúa tôi, xin cho người của Đức Chúa Trời mà Ngài đã sai đến, xin hãy đến cùng chúng tôi một lần nữa, và dạy chúng tôi biết điều phải làm cho đứa trẻ sẽ được sinh ra.'),
(6894, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 13, 9, 'OT', 'Đức Chúa Trời đã nghe theo tiếng của Ma-nô; và thiên sứ của Đức Chúa Trời lại đến cùng người đàn bà khi bà đang ngồi trong đồng trống; còn Ma-nô, chồng bà, thì không ở cùng bà.'),
(6895, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 13, 10, 'OT', 'Người đàn bà vội vàng đứng dậy, chạy đi báo cho chồng mình, và nói với ông: "Này, người đàn ông đã hiện ra cùng tôi, là người đã đến cùng tôi hôm trước."'),
(6896, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 13, 11, 'OT', 'Và Manôch chỗi dậy, đi theo vợ mình, đến gặp người đàn ông, và nói với ông ấy: "Ông có phải là người đã nói với người đàn bà chăng?" Người ấy đáp: "Tôi đây."'),
(6897, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 13, 12, 'OT', 'Và Ma-nô-a nói: "Các lời của ngài rồi sẽ ứng nghiệm. Luật lệ cho đứa trẻ và việc nó phải làm là gì?"'),
(6898, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 13, 13, 'OT', 'Thiên sứ của Đức Giê-hô-va nói với Ma-nô: "Tất cả những điều ta đã nói với người đàn bà, nàng phải giữ."'),
(6899, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 13, 14, 'OT', 'Mọi thứ sinh ra từ cây nho, nàng không được ăn; rượu hay rượu mạnh, nàng không được uống; mọi thứ ô uế, nàng không được ăn; tất cả những điều Ta đã truyền cho nàng, nàng phải giữ.'),
(6900, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 13, 15, 'OT', 'Ma-nô-a nói với thiên sứ của Đức Giê-hô-va: "Xin hãy ở lại đây, chúng tôi sẽ dọn một con dê đực con làm của lễ cho ngài."'),
(6901, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 13, 16, 'OT', 'Và thiên sứ của Đức Giê-hô-va nói với Ma-nô-a: "Dù ngươi có giữ ta lại, ta cũng sẽ không ăn bánh của ngươi; và nếu ngươi dâng của lễ thiêu cho Đức Giê-hô-va, ngươi phải dâng nó lên cho Đức Giê-hô-va." Vì Ma-nô-a không biết rằng người ấy là thiên sứ của Đức Giê-hô-va.'),
(6902, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 13, 17, 'OT', 'Ma-nô-ách nói với thiên sứ của Đức Giê-hô-va: "Tên ngài là gì, để khi lời ngài ứng nghiệm, chúng tôi có thể tôn kính ngài?"'),
(6903, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 13, 18, 'OT', 'Thiên sứ của Đức Giê-hô-va đáp: "Sao ngươi hỏi tên ta? Vì tên ta là bí ẩn."'),
(6904, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 13, 19, 'OT', 'Ma-nô-a lấy con dê đực và lễ vật, dâng lên Đức Giê-hô-va trên tảng đá; và người làm điều kỳ diệu; Ma-nô-a và vợ nhìn xem.'),
(6905, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 13, 20, 'OT', 'Khi ngọn lửa bốc lên trời từ bàn thờ, thì thiên sứ của Đức Giê-hô-va cũng lên trong ngọn lửa của bàn thờ. Manô và vợ ông thấy điều đó, liền sấp mặt xuống đất.'),
(6906, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 13, 21, 'OT', 'Và thiên sứ của Đức Giê-hô-va không hiện ra nữa với Ma-nô và vợ ông. Bấy giờ Ma-nô mới biết người đó là thiên sứ của Đức Giê-hô-va.'),
(6907, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 13, 22, 'OT', 'Ma-nô-ách nói với vợ mình: "Chúng ta chắc chắn sẽ chết, vì chúng ta đã thấy Đức Chúa Trời."'),
(6908, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 13, 23, 'OT', 'Vợ người ấy nói với ông: "Nếu Đức Giê-hô-va muốn giết chúng ta, thì Ngài đã chẳng nhận của lễ thiêu và lễ vật từ tay chúng ta, chẳng cho chúng ta thấy những điều nầy, và lúc nầy cũng đã chẳng cho chúng ta nghe những điều như thế nầy."'),
(6909, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 13, 24, 'OT', 'Người đàn bà sinh một con trai, đặt tên con là Sam-sôn. Đứa trẻ lớn lên, và Đức Giê-hô-va ban phước cho nó.'),
(6910, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 13, 25, 'OT', 'Thần của Đức Giê-hô-va bắt đầu thúc đẩy anh tại trại quân Đan, giữa Xô-ra và Ét-ta-ôn.'),
(6911, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 14, 1, 'OT', 'Sam-sôn đi xuống Thin-na, và thấy một người phụ nữ ở Thin-na, thuộc các con gái của người Phi-li-tin.'),
(6912, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 14, 2, 'OT', 'Và anh ta đi lên, thuật lại cho cha và mẹ mình, rồi nói: "Con đã thấy một người phụ nữ ở Tím-nát, thuộc dòng dõi dân Phi-li-tin; vậy bây giờ hãy đi lấy cô ấy cho con làm vợ."'),
(6913, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 14, 3, 'OT', 'Bấy giờ cha và mẹ người nói với người rằng: "Làm sao không tìm được người vợ trong các con gái anh em ngươi hoặc trong toàn dân ta, mà ngươi lại đi lấy vợ nơi người Phi-li-tin không chịu cắt bì?" Nhưng Sam-sôn nói với cha mình: "Cha hãy lấy nàng cho con, vì nàng đẹp lòng con."'),
(6914, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 14, 4, 'OT', 'Cha mẹ của anh không biết điều đó đến từ Đức Giê-hô-va, vì người đang tìm kiếm dịp để chống lại người Phi-li-tin; bởi lúc ấy người Phi-li-tin đang cai trị trên Ít-ra-en.'),
(6915, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 14, 5, 'OT', 'Sam-sôn cùng cha và mẹ người xuống thành Ti-mơ-nát; khi đến các vườn nho của Ti-mơ-nát, bỗng một con sư tử con gầm lên, xông ra nghênh chiến với người.'),
(6916, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 14, 6, 'OT', 'Thần của Đức Giê-hô-va ngự trên ông, và ông xé con sư tử ra như xé con dê con, dù chẳng có gì trong tay. Nhưng ông không nói cho cha hay mẹ mình biết điều ông đã làm.'),
(6917, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 14, 7, 'OT', 'Rồi anh xuống và nói chuyện với người phụ nữ ấy; và nàng đẹp lòng Sam-ôn.'),
(6918, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 14, 8, 'OT', 'Một thời gian sau, chàng trở lại để cưới nàng, thì thấy xác con sư tử, và nầy, một đàn ong cùng mật ong ở trong xác con sư tử ấy.'),
(6919, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 14, 9, 'OT', 'Ông lấy mật ấy trong tay mình, rồi đi vừa ăn vừa đi, đến cùng cha mẹ mình, và ông đưa cho họ, họ bèn ăn; nhưng ông không nói cho họ rằng ông đã lấy mật ấy từ xác con sư tử.'),
(6920, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 14, 10, 'OT', 'Cha người xuống gặp người phụ nữ, và tại đó Xa-mi-ôn làm một bữa tiệc, vì các thanh niên thường làm như vậy.'),
(6921, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 14, 11, 'OT', 'Khi họ thấy chàng, thì họ chọn ba mươi người bạn đi cùng chàng.'),
(6922, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 14, 12, 'OT', 'Sam-ôn nói với họ: "Tôi xin đặt một câu đố cho các anh; nếu các anh có thể giải được cho tôi trong bảy ngày tiệc cưới, và tìm ra được, thì tôi sẽ tặng các anh ba mươi tấm vải lanh và ba mươi bộ quần áo."'),
(6923, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 14, 13, 'OT', 'Nếu các ngươi không thể giải câu đố của ta, thì các ngươi phải đưa cho ta ba mươi tấm vải lanh và ba mươi bộ quần áo mới. Họ nói với người: Hãy nói ra câu đố của ngươi, để chúng tôi nghe.'),
(6924, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 14, 14, 'OT', 'Người nói với họ: "Từ vật ăn mồi ra của ăn, từ vật mạnh ra điều ngọt. Và họ không thể giải được câu đố ấy trong ba ngày."'),
(6925, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 14, 15, 'OT', 'Vào ngày thứ bảy, họ nói với vợ của Sam-sôn: "Hãy quyến rũ chồng ngươi để anh ấy tiết lộ cho chúng ta câu đố, nếu không, chúng ta sẽ thiêu ngươi và nhà cha ngươi trong lửa. Các ngươi gọi chúng ta đến để cướp bóc, phải không? Có phải vậy không?"'),
(6926, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 14, 16, 'OT', 'Vợ của Sam-sôn khóc lóc trước mặt người, rồi nói: "Chỉ vì anh ghét tôi, nên anh không yêu tôi! Anh đã đặt một câu đố cho những người trẻ tuổi trong dân tôi, nhưng lại không tiết lộ cho tôi biết." Người nói với cô: "Này, tôi đã không tiết lộ điều đó cho cha tôi hay mẹ tôi, lẽ nào tôi lại tiết lộ cho cô sao?"'),
(6927, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 14, 17, 'OT', 'Cô khóc lóc bên người bảy ngày, trong suốt thời gian tiệc cưới của họ; và đến ngày thứ bảy, người ấy nói cho cô biết, vì cô đã nài ép quá mức, rồi cô nói câu đố đó cho những người trong dân tộc mình.'),
(6928, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 14, 18, 'OT', 'Các người trong thành nói với anh ta vào ngày thứ bảy, trước khi mặt trời lặn: "Cái gì ngọt hơn mật ong? Cái gì mạnh hơn sư tử?" Anh đáp: "Nếu các anh không cày bằng bò cái của ta, thì đã chẳng tìm ra được câu đố ta đặt."'),
(6929, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 14, 19, 'OT', 'Thần của Đức Giê-hô-va ngự trên người, và người đi xuống A-xiếc-lôn, đánh giết ở đó ba mươi người, lấy áo quần của họ, rồi đem đổi cho những người giải câu đố. Nhưng cơn giận của người nổi lên, và người đi lên nhà cha mình.'),
(6930, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 14, 20, 'OT', 'Vợ của Sam-sôn được gả cho người bạn thân của chàng, tức người đã từng làm bạn cùng chàng.'),
(6931, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 15, 1, 'OT', 'Một thời gian sau, vào mùa gặt lúa mì, Sam-sôn đi thăm vợ mình, đem theo một con dê con; và người nói: "Tôi sẽ vào phòng với vợ tôi." Nhưng cha vợ không cho người vào.'),
(6932, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 15, 2, 'OT', 'Cha nàng nói: Tôi nghĩ rằng anh ghét nàng, nên tôi đã gả nàng cho bạn anh. Em gái nàng chẳng đẹp hơn nàng sao? Xin hãy nhận em gái thay nàng.'),
(6933, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 15, 3, 'OT', 'Sam-sôn nói với họ: "Lần này tôi vô tội trước người Phi-li-tin, dù tôi làm điều ác nghịch cùng họ."'),
(6934, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 15, 4, 'OT', 'Rồi Sam-sôn đi bắt ba trăm con chồn, lấy những bó đuốc, nối đuôi chồn này với đuôi chồn kia, và đặt một bó đuốc ở giữa, giữa hai đuôi.'),
(6935, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 15, 5, 'OT', 'Đốt lửa vào những bó đuốc, rồi thả vào các ruộng lúa của người Phi-li-tin, thiêu cháy cả đống lúa đã gặt, cả ruộng lúa đang đứng, và cả vườn nho lẫn vườn ô-liu.'),
(6936, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 15, 6, 'OT', 'Người Phi-li-tin nói: "Ai đã làm điều này?" Họ đáp: "Sa-mi-ôn, con rể người Ti-mơ-nai, vì hắn đã lấy vợ mình rồi lại trao nàng cho bạn mình." Bấy giờ người Phi-li-tin kéo đến, thiêu sống nàng và cha nàng.'),
(6937, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 15, 7, 'OT', 'Sam-sôn nói với họ: "Nếu các ngươi làm điều này, thì ta sẽ báo thù các ngươi, rồi sau đó mới thôi."'),
(6938, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 15, 8, 'OT', 'Người đánh họ một đòn lớn về hông và đùi, rồi đi xuống và ở lại trên đỉnh vách đá Ê-tam.'),
(6939, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 15, 9, 'OT', 'Dân Phi-li-tin lên đánh, đóng trại trong xứ Giu-đa, và rải ra khắp vùng Lê-chi.'),
(6940, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 15, 10, 'OT', 'Các người của Giu-đa nói: "Tại sao các ngươi lên nghịch cùng chúng tôi?" Họ đáp: "Chúng tôi lên để trói Sam-sôn, làm cho nó điều mà nó đã làm cho chúng tôi."'),
(6941, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 15, 11, 'OT', 'Ba ngàn người đàn ông từ Giu-đa đi xuống vách đá Ê-tam, và nói với Xim-xôn: "Anh há chẳng biết người Phi-li-tin đang cai trị chúng ta sao? Vậy thì điều này anh làm với chúng tôi là gì?" Nhưng anh đáp: "Như họ đã làm với tôi, tôi cũng vậy đã làm với họ."'),
(6942, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 15, 12, 'OT', 'Họ nói với ông: "Chúng tôi xuống đây để bắt ông, để giao ông cho tay người Phi-li-tin." Sam-sôn nói với họ: "Hãy thề với tôi rằng các anh sẽ không tự mình tấn công tôi."'),
(6943, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 15, 13, 'OT', 'Họ nói với anh rằng: "Không, chúng tôi chỉ trói anh thật chặt rồi giao anh vào tay chúng; nhưng chắc chắn sẽ không giết anh." Vậy họ trói anh bằng hai dây mới, rồi đưa anh lên khỏi vách đá.'),
(6944, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 15, 14, 'OT', 'Khi ông đến nơi gọi là Lê-hi, thì dân Phi-li-tin hò reo tiến về phía ông. Bấy giờ Thần của Đức Giê-hô-va ngập tràn trên ông, và những dây trói trên cánh tay ông trở nên như những sợi gai bị lửa thiêu, và các dây trói nơi tay ông liền đứt ra.'),
(6945, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 15, 15, 'OT', 'Người tìm thấy một hàm dưới mới của lừa, bèn giơ tay ra, lấy nó, và dùng nó đánh giết một ngàn người.'),
(6946, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 15, 16, 'OT', 'Rồi Sam-sôn nói: "Nhờ xương hàm của một con lừa, đống này chồng lên đống kia, nhờ xương hàm của một con lừa, tôi đã đánh giết một ngàn người."'),
(6947, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 15, 17, 'OT', 'Sau khi ông nói xong, ông ném cái hàm ra khỏi tay mình, và gọi nơi ấy là Râmát Lêchi.'),
(6948, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 15, 18, 'OT', 'Vì khát nước quá đỗi, ông kêu cầu Đức Giê-hô-va và nói: "Chính Ngài đã ban sự giải cứu lớn lao nầy vào tay đầy tớ Ngài; vậy mà bây giờ tôi sẽ chết vì khát và rơi vào tay những kẻ không chịu cắt bì sao?"'),
(6949, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 15, 19, 'OT', 'Đức Chúa Trời bèn làm nứt khe đá ở Lehi, và nước từ đó chảy ra; ông uống nước, rồi thần khí ông trở lại, và ông sống lại. Vì vậy, ông đặt tên nơi ấy là Ên-ha-cô-rê, ở Lehi cho đến ngày nay.'),
(6950, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 15, 20, 'OT', 'Người cai trị cho Y-sơ-ra-ên trong những ngày dân Phi-li-tin, suốt hai mươi năm.'),
(6951, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 16, 1, 'OT', 'Sau đó, Sam-sôn đi đến Ga-za, thấy ở đó một người đàn bà điếm, và ông vào cùng nàng.'),
(6952, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 16, 2, 'OT', 'Người ta báo cho người Gạt-xít biết rằng Xa-mạc-ôn đã đến nơi đây; họ vây quanh và rình phục kích người suốt đêm tại cửa thành, và họ nín lặng suốt đêm, nói: "Chờ đến khi trời sáng, chúng ta sẽ giết hắn."'),
(6953, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 16, 3, 'OT', 'Sau đó, Sam-sôn nằm ngủ cho đến nửa đêm; rồi người thức dậy giữa đêm, lấy các cánh cửa thành cùng hai trụ cửa và then chốt then, moi cả lên, đặt trên vai mình và khiêng đi, đem lên đỉnh núi phía trước thành Hếp-rôn.'),
(6954, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 16, 4, 'OT', 'Sau đó, người yêu một người phụ nữ ở thung lũng Sô-réc, tên bà là Đa-li-la.'),
(6955, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 16, 5, 'OT', 'Các quan trưởng người Phi-li-tin đi đến cùng nàng và nói: "Hãy quyến rũ hắn và xem sức lực lớn của hắn ở chỗ nào, và bằng cách nào chúng ta có thể thắng được hắn, để chúng ta trói hắn mà hành hạ. Này, mỗi người trong chúng ta sẽ đưa cho nàng một ngàn một trăm miếng bạc."'),
(6956, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 16, 6, 'OT', 'Đa-li-la nói với Sam-sôn: "Xin hãy cho tôi biết, sức mạnh lớn của anh nằm ở đâu, và bằng cách nào người ta có thể trói anh để hành hạ anh?"'),
(6957, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 16, 7, 'OT', 'Sam-sôn nói với nàng: "Nếu người ta trói tôi bằng bảy sợi dây mới chưa khô, thì tôi sẽ yếu đi và sẽ giống như một người đàn ông khác."'),
(6958, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 16, 8, 'OT', 'Các quan trưởng người Phi-li-tin đem đến cho nàng bảy dây gai chưa khô, và nàng trói chàng bằng những dây đó.'),
(6959, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 16, 9, 'OT', 'Kẻ phục kích đang nằm chờ trong phòng. Cô nói với anh: "Người Phi-li-tin đang bắt ngươi, Xim-xôn!" Nhưng anh bẻ gãy những dây trói như sợi chỉ bịt bị đốt cháy khi gặp lửa, và người ta vẫn không biết sức mạnh của anh.'),
(6960, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 16, 10, 'OT', 'Đa-li-đa nói với Sam-sôn: "Kìa, anh đã chế nhạo tôi và nói dối tôi; bây giờ xin hãy nói cho tôi biết bằng cách nào anh có thể bị trói."'),
(6961, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 16, 11, 'OT', 'Người nói với nàng: Nếu người ta trói tôi bằng những dây mới chưa dùng vào việc gì, thì tôi sẽ yếu đi và trở nên như một người thường.'),
(6962, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 16, 12, 'OT', 'Đa-li-la lấy những dây mới trói người, rồi nói với người: "Kìa, người Phi-li-tin đến bắt ông đây, Sim-sôn!" Nhưng người nằm rình trong phòng. Người bẻ gãy những dây đó khỏi tay mình như gãy chỉ.'),
(6963, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 16, 13, 'OT', 'Đa-li-la nói với Xa-mạc-xôn: "Tới nay anh vẫn chế nhạo tôi và nói dối tôi; hãy nói cho tôi biết anh sẽ bị trói bằng gì?" Xa-mạc-xôn nói với nàng: "Nếu nàng dệt bảy lọn tóc trên đầu tôi vào tấm vải đang dệt."'),
(6964, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 16, 14, 'OT', 'Bà đóng đinh cái thoi vào, rồi nói với ông: "Người Phi-li-tin đến bắt ông đây, Sim-sôn ơi!" Ông liền thức tỉnh khỏi giấc ngủ, giật bật cái thoi khỏi khung cửi cùng với tấm vải.'),
(6965, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 16, 15, 'OT', 'Bà nói với ông: "Ông làm sao có thể nói ''Tôi yêu ông'', trong khi lòng ông đâu có ở cùng tôi? Đây đã ba lần ông chế nhạo tôi, mà chẳng cho tôi biết sức lực lớn của ông ở chỗ nào?"'),
(6966, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 16, 16, 'OT', 'Và xảy ra rằng, khi nàng lấy lời nói hằng ngày mà ép buộc hắn, khiến cho tâm thần hắn đau đớn đến nỗi muốn chết;'),
(6967, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 16, 17, 'OT', 'Người kể cho nàng mọi điều trong lòng mình, rồi nói với nàng: "Dao cạo chưa từng chạm đến đầu tôi, vì tôi là người được biệt riêng cho Đức Chúa Trời từ khi còn trong bụng mẹ. Nếu đầu tôi bị cạo trọc, sức mạnh tôi sẽ rời khỏi tôi, tôi sẽ yếu đi và trở nên như mọi người khác."'),
(6968, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 16, 18, 'OT', 'Vì thấy Đa-li-la rằng người đã nói cho nàng biết mọi điều trong lòng mình, nên nàng sai người mời các quan trưởng Phi-li-tin mà nói rằng: "Xin hãy lên lần này, vì người đã tiết lộ cho tôi mọi điều trong lòng mình." Bấy giờ các quan trưởng Phi-li-tin lên gặp nàng, tay cầm tiền bạc.'),
(6969, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 16, 19, 'OT', 'Bà làm ông ngủ gục trên đầu gối mình, rồi gọi một người đàn ông, và người ấy cạo đi bảy lọn tóc trên đầu ông; bà bắt đầu hành hạ ông, và sức mạnh ông rời khỏi ông.'),
(6970, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 16, 20, 'OT', 'Cô ấy nói: "Người Phi-li-tin đang trên ngươi, Sam-sôn đây!" Sam-sôn liền tỉnh giấc, nói: "Ta sẽ ra đi như lần trước, và lắc mình." Nhưng ông không biết rằng Đức Giê-hô-va đã lìa khỏi ông.'),
(6971, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 16, 21, 'OT', 'Người Phi-li-tin bắt ông, khoét mắt ông, đem xuống Gát và xiềng ông bằng xích đồng; ông phải xay bột trong nhà tù.'),
(6972, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 16, 22, 'OT', 'Tuy nhiên, tóc trên đầu anh bắt đầu mọc lại như trước khi bị cạo.'),
(6973, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 16, 23, 'OT', 'Các quan cai trị của người Phi-li-tin nhóm lại để dâng một lễ tế lớn cho Đa-gôn, thần của chúng, và ăn mừng. Chúng nói: "Thần của chúng ta đã trao Sam-sôn, kẻ thù của chúng ta, vào tay chúng ta."'),
(6974, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 16, 24, 'OT', 'Dân chúng thấy hắn thì ca ngợi thần của chúng, vì chúng nói: "Thần chúng ta đã trao vào tay chúng ta kẻ thù nghịch chúng ta, kẻ hủy hoại đất nước chúng ta và kẻ làm cho nhiều người trong chúng ta bị giết."'),
(6975, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 16, 25, 'OT', 'Khi lòng họ vui vẻ, thì nói: "Hãy gọi Sam-sôn đến để làm trò vui cho chúng ta." Vậy họ gọi Sam-sôn từ trong nhà tù; và người làm trò vui cho họ. Rồi họ đặt người giữa hai cột trụ.'),
(6976, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 16, 26, 'OT', 'Rồi Sam-sôn nói với đứa trẻ đang dìu tay mình: "Hãy để tôi, và đỡ tôi vào những cái cột mà ngôi nhà dựng trên đó, để tôi có thể tựa vào."'),
(6977, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 16, 27, 'OT', 'Nhà đầy người nam và người nữ; tất cả các quan trưởng của người Phi-li-tin đều ở đó; và trên mái nhà có khoảng ba ngàn người, cả nam lẫn nữ, đang xem khi Xim-sôn biểu diễn trò vui.'),
(6978, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 16, 28, 'OT', 'Rồi Sam-sôn kêu cầu Đức Giê-hô-va, mà rằng: "Lạy Chúa Đức Chúa Trời, xin nhớ đến tôi, và xin làm tôi mạnh mẽ chỉ lần nầy thôi, hỡi Đức Chúa Trời, để tôi báo một mối thù cho hai con mắt tôi từ các người Phi-li-tin."'),
(6979, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 16, 29, 'OT', 'Sam-sôn nắm lấy hai cột trụ giữa mà nhà tựa trên đó, rồi tựa vào chúng, một bên bằng tay phải, một bên bằng tay trái.'),
(6980, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 16, 30, 'OT', 'Rồi Sam-sôn nói: "Nguyện cho linh hồn tôi chết cùng với dân Phi-li-tin!" Rồi ông cúi xuống hết sức lực mình, và ngôi nhà sụp đổ trên các quan trưởng và trên tất cả những người ở bên trong. Vậy số người chết mà ông giết khi chết nhiều hơn số người ông đã giết khi còn sống.'),
(6981, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 16, 31, 'OT', 'Các anh trai người ấy và cả nhà của cha người ấy đi xuống, đem xác người ấy đi, rồi khiêng lên chôn trong phần mộ của Manôah, cha người ấy, ở giữa Xô-ra và Ét-tha-ôn. Người ấy đã xét xử cho Ít-ra-en hai mươi năm.'),
(6982, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 17, 1, 'OT', 'Có một người đàn ông từ núi Ép-ra-im, tên ông là Mi-cha.'),
(6983, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 17, 2, 'OT', 'Thế rồi anh ta nói với mẹ mình: "Ngần ấy bạc, một ngàn một trăm mi-cha, vốn bị lấy đi từ mẹ, và mẹ đã nguyền rủa trước mặt tôi, nay đây, bạc này ở với tôi; chính tôi đã lấy nó." Mẹ anh ta nói: "Con trai ta, con được phước của Đức Giê-hô-va."'),
(6984, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 17, 3, 'OT', 'Khi người ấy hoàn trả một ngàn một trăm miếng bạc cho mẹ mình, thì mẹ người ấy nói: "Tôi đã biệt riêng số bạc này cho Đức Giê-hô-va từ tay tôi, để dành cho con trai tôi, hầu làm tượng chạm và tượng đúc; nhưng bây giờ tôi sẽ hoàn lại cho con."'),
(6985, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 17, 4, 'OT', 'Người con trả lại số bạc cho mẹ mình; rồi mẹ người con lấy hai trăm miếng bạc, giao cho thợ đúc, người ấy đã dùng số bạc đó làm một tượng chạm và một tượng đúc; và những tượng ấy ở trong nhà của Míchah.'),
(6986, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 17, 5, 'OT', 'Người đàn ông Míchah có một nhà thần, và ông làm một e-phót và các hình tượng thần linh, rồi biệt riêng một trong các con trai mình, khiến người ấy làm thầy tế lễ cho ông.'),
(6987, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 17, 6, 'OT', 'Trong những ngày ấy, không có vua cai trị trên Y-sơ-ra-ên; mỗi người làm điều mình cho là phải trong mắt mình.'),
(6988, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 17, 7, 'OT', 'Có một thanh niên từ Bết-lê-hem thuộc xứ Giu-đa, thuộc dòng họ Giu-đa, người là thầy Lê-vi, và người này đang tạm trú ở đó.'),
(6989, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 17, 8, 'OT', 'Người ấy rời khỏi thành Bết-lê-hem thuộc xứ Giu-đa, đi trọ nơi nào mà người gặp được; và người đến vùng núi Ép-ra-im, tại nhà của Mích-gia, trong khi đang đi đường.'),
(6990, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 17, 9, 'OT', 'Míchah nói với người ấy: "Ngươi từ đâu đến?" Người ấy đáp: "Tôi là một người Lê-vi, từ Bết-lê-hem thuộc xứ Giu-đa, và tôi đang đi tìm nơi nào để tạm cư."'),
(6991, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 17, 10, 'OT', 'Mi-ca nói với người ấy: "Hãy ở lại với ta, làm cha và làm thầy tế lễ cho ta; ta sẽ cấp cho ngươi mười miếng bạc mỗi năm, cùng với quần áo và lương thực." Thế là người Lê-vi đi vào.'),
(6992, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 17, 11, 'OT', 'Người Lê-vi ấy bằng lòng ở lại với người đàn ông đó; và người thanh niên trở nên như một trong các con trai của ông.'),
(6993, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 17, 12, 'OT', 'Mi-ka bổ nhiệm người Lê-vi; người thanh niên ấy làm thầy tế lễ cho người, và ở trong nhà của Mi-ka.'),
(6994, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 17, 13, 'OT', 'Mica nói: "Bây giờ tôi biết rằng Đức Giê-hô-va sẽ làm điều tốt lành cho tôi, vì tôi đã có một người Lê-vi làm thầy tế lễ."'),
(6995, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 18, 1, 'OT', 'Trong những ngày ấy, chưa có vua cai trị trên Y-sơ-ra-ên; và trong những ngày ấy, chi phái Đan đang tìm kiếm cho mình một phần sản nghiệp để định cư, vì cho đến ngày ấy, chưa có phần sản nghiệp nào được phân cho họ giữa các chi phái Y-sơ-ra-ên.'),
(6996, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 18, 2, 'OT', 'Dân sai năm người trong dòng họ mình, là những người dũng cảm từ các vùng đất Xô-ra và Ê-shta-ol, đi do thám và dò xét vùng đất; và họ bảo các người ấy: "Hãy đi dò xét vùng đất." Khi họ đến vùng núi Ép-ra-im, tới nhà Mi-ca, thì nghỉ đêm tại đó.'),
(6997, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 18, 3, 'OT', 'Họ đi ngang qua nhà của Míchah, thì nhận biết tiếng nói của người trẻ tuổi, người Lêvi. Họ bèn rẽ vào đó và hỏi người ấy rằng: "Ai đã đưa ông đến đây? Ông đang làm gì ở đây? Và ông có việc gì ở đây?"'),
(6998, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 18, 4, 'OT', 'Hắn nói với họ: "Míchách đối xử với tôi như thế này và như thế kia, đã thuê tôi, và tôi làm thầy tế lễ cho người ấy."'),
(6999, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 18, 5, 'OT', 'Họ nói với ông: "Xin ông hãy cầu hỏi Đức Chúa Trời, để chúng tôi biết con đường chúng tôi đang đi có được thành công hay không."'),
(7000, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 18, 6, 'OT', 'Vị thầy tế lễ nói với họ: "Hãy đi bình an; con đường các ngươi đi, có Đức Giê-hô-va chứng giám."'),
(7001, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 18, 7, 'OT', 'Vậy năm người ấy đi đến Laish; họ thấy dân sự ở đó sống an nhiên, theo phong tục của người Si-đôn, bình an và thản nhiên, không có ai cai trị đất ấy, không ai gây sự với họ, và họ sống xa cách người Si-đôn, chẳng giao thiệp gì với ai.'),
(7002, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 18, 8, 'OT', 'Họ đến cùng anh em mình tại Xô-ra và Ê-xơ-tha-ol; và anh em họ nói với họ rằng: Các anh nói điều gì?'),
(7003, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 18, 9, 'OT', 'Họ nói: "Hãy chổi dậy, lên đường đánh chiếm họ đi! Vì chúng tôi đã xem xét vùng đất ấy, và nầy, nó thật rất tốt; còn các anh thì sao, cứ đứng nghỉ mãi ư? Đừng biếng nhác, hãy đi vào để chiếm lấy vùng đất ấy."'),
(7004, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 18, 10, 'OT', 'Khi các ngươi đi, các ngươi sẽ đến một dân đang sống yên ổn, và một vùng đất rộng lớn; vì Đức Chúa Trời đã trao nó vào tay các ngươi, một nơi không thiếu thốn bất cứ điều gì trên đất.'),
(7005, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 18, 11, 'OT', 'Họ rời khỏi nơi đó thuộc dòng họ Đan, từ Xô-ra và từ Ê-xơ-tha-ôn, sáu trăm người, thắt đai các khí giới chiến tranh.'),
(7006, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 18, 12, 'OT', 'Họ đi lên và đóng trại tại Ki-ri-át Giê-a-rim, thuộc xứ Giu-đa; vì vậy, người ta gọi nơi ấy là Ma-ha-ne Đan cho đến ngày nay; này, nó ở phía sau Ki-ri-át Giê-a-rim.'),
(7007, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 18, 13, 'OT', 'Họ đi ngang qua đó đến núi Ép-ra-im, rồi đến nhà của Mi-cha.'),
(7008, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 18, 14, 'OT', 'Năm người trong số những người đã đi do thám vùng đất Laish đáp lời và nói với anh em mình: "Anh em có biết rằng trong các nhà này có áo thầy tế lễ, các hình tượng thần, một tượng chạm và một tượng đúc không? Vậy bây giờ hãy suy xét xem mình phải làm gì."'),
(7009, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 18, 15, 'OT', 'Họ rẽ sang đó và đến nhà của người thanh niên người Lê-vi, tức nhà của Mi-ca, rồi hỏi thăm tình trạng bình an của người ấy.'),
(7010, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 18, 16, 'OT', 'Sáu trăm người đàn ông mang theo khí giới chiến tranh, đứng tại lối vào cổng, là những người thuộc con cái Đan.'),
(7011, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 18, 17, 'OT', 'Các người năm đi do thám đất ấy lên đó, vào trong đó, lấy tượng chạm, bàn thờ bằng da, các tượng thần gia đình và tượng đúc; thầy tế lễ đứng ở lối vào cổng, còn sáu trăm người lính mang khí giới chiến tranh thì đứng đó.'),
(7012, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 18, 18, 'OT', 'Họ vào nhà của Mi-ca, lấy tượng chạm khắc, áo ê-phót, các tượng thần và tượng đúc. Rồi thầy tế lễ nói với họ: "Các anh đang làm gì vậy?"'),
(7013, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 18, 19, 'OT', 'Họ nói với người ấy: "Hãy im lặng, đặt tay lên miệng ngươi, rồi đi với chúng tôi; hãy làm cha và thầy tế lễ cho chúng tôi. Ngươi làm thầy tế lễ cho nhà một người, hay làm thầy tế lễ cho một chi phái và một dòng họ trong Y-sơ-ra-ên, điều nào tốt hơn?"'),
(7014, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 18, 20, 'OT', 'Lòng thầy tế lễ vui vẻ, bèn lấy áo ê-phót, các tượng Thê-ra-phim và tượng chạm, rồi đi giữa đoàn dân.'),
(7015, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 18, 21, 'OT', 'Họ quay đi và ra đi, rồi đặt các trẻ nhỏ, súc vật và những vật quý giá ở phía trước mình.'),
(7016, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 18, 22, 'OT', 'Họ đi xa khỏi nhà của Míchách; rồi những người ở các nhà gần nhà của Míchách kêu lên, và đuổi theo con cháu của Đan.'),
(7017, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 18, 23, 'OT', 'Họ kêu lên cùng các con trai Đan, và các con trai Đan quay mặt lại; rồi họ nói với Míchã: "Việc gì khiến ngươi kêu la như vậy?"'),
(7018, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 18, 24, 'OT', 'Người ấy nói: "Các ngươi đã mang đi các thần mà tôi đã làm, và cả thầy tế lễ nữa; các ngươi đi mất rồi. Vậy tôi còn gì nữa? Các ngươi nói gì với tôi đây: ''Ngươi có điều chi vậy?''"'),
(7019, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 18, 25, 'OT', 'Các con trai của Đan nói với người ấy: "Đừng để tiếng nói của ông vang lên giữa chúng tôi, kẻo những người hung dữ sẽ xông vào ông, và ông sẽ mất mạng sống mình cùng mạng sống cả nhà ông."'),
(7020, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 18, 26, 'OT', 'Các con trai của Đan đi theo đường lối mình; và khi Mi-ca thấy họ mạnh hơn mình, thì người quay lại và trở về nhà mình.'),
(7021, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 18, 27, 'OT', 'Họ lấy những vật mà Mích-gia đã làm và lấy cả thầy tế lễ vốn thuộc về người ấy, rồi đi đến Laís, đến một dân đang yên ổn và thản nhiên. Họ đánh dân ấy bằng lưỡi gươm và đốt thành ấy bằng lửa.'),
(7022, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 18, 28, 'OT', 'Không có ai giải cứu vì nơi ấy ở xa Si-đôn, và họ không có liên hệ gì với ai; nơi ấy nằm trong thung lũng gần Bết-rê-hốp. Họ xây cất một thành phố và ở đó.'),
(7023, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 18, 29, 'OT', 'Họ gọi tên thành ấy là Đan, theo tên Đan cha mình, là người sinh ra cho Y-sơ-ra-ên; nhưng trước kia tên thành ấy là La-is.'),
(7024, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 18, 30, 'OT', 'Consequently, con trai Dan lập tượng chạm khắc cho mình; và Giô-na-than, con của Gershom, con của Ma-na-se, cùng các con trai ông, làm thầy tế lễ cho chi phái Dan cho đến ngày đất bị lưu đày.'),
(7025, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 18, 31, 'OT', 'Họ đặt tượng chạm khắc của Míchá mà người ấy đã làm cho mình, suốt mọi ngày nhà của Đức Chúa Trời còn ở tại Si-lô.'),
(7026, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 19, 1, 'OT', 'Xảy ra trong những ngày ấy, không có vua cai trị trên Y-sơ-ra-ên, và có một người Lê-vi tạm trú ở vùng rìa núi Ép-ra-im, người ấy lấy cho mình một người vợ lẽ từ Bê-lem thuộc Giu-đa.'),
(7027, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 19, 2, 'OT', 'Người nữ hầu của ông đã phản bội ông, rồi bỏ ông đi về nhà cha mình tại Bê-lem của Giu-đa, và ở đó bốn tháng.'),
(7028, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 19, 3, 'OT', 'Người chồng đứng dậy, đi theo nàng để nói chuyện với lòng tốt nhằm đưa nàng trở về, có đầy tớ đi cùng ông và một đôi lừa; và nàng đã đưa ông vào nhà cha nàng. Khi cha của người thiếu nữ thấy ông, thì người cha vui mừng đón tiếp ông.'),
(7029, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 19, 4, 'OT', 'Người cha vợ, tức là cha của người thiếu nữ, níu giữ chàng lại; và chàng ở với ông ấy ba ngày. Họ ăn uống và nghỉ đêm tại đó.'),
(7030, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 19, 5, 'OT', 'Vào ngày thứ tư, họ chổi dậy sớm vào buổi sáng, rồi người đàn ông đứng dậy để ra đi; nhưng cha của người thiếu nữ nói với con rể mình: "Hãy ăn miếng bánh cho vững dạ, rồi sau đó hãy đi."'),
(7031, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 19, 6, 'OT', 'Họ ngồi xuống, cả hai cùng ăn uống; rồi cha của người thiếu nữ nói với người đàn ông: "Tôi xin anh hãy ở lại, và hãy vui lòng ở lại đêm nay, để lòng anh được vui vẻ."'),
(7032, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 19, 7, 'OT', 'Người đàn ông đứng dậy để ra đi, nhưng cha vợ níu lại; người ấy bèn trở lại và ngủ lại đó.'),
(7033, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 19, 8, 'OT', 'Sáng sớm ngày thứ năm, người ấy chỗi dậy để lên đường. Nhưng cha của người thiếu nữ nói: "Hãy ở lại, xin hãy vững lòng." Vậy họ nán lại cho đến khi trời xế chiều, và cả hai cùng ăn uống.'),
(7034, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 19, 9, 'OT', 'Người đàn ông đứng dậy để ra đi, cùng người thứ thiếp và người đầy tớ trai của mình; thì cha vợ, tức là cha của người thiếu nữ, bảo ông: "Này, ngày đã gần xế về chiều, hãy ở lại đây đêm nay. Kìa, hãy nghỉ lại đây cho đến sáng mai, để lòng anh được vui vẻ; rồi ngày mai hãy dậy sớm lên đường trở về lều của anh."'),
(7035, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 19, 10, 'OT', 'Nhưng người đàn ông không chịu ở lại đêm đó, bèn đứng dậy và đi, đến gần Giê-bu-s, tức là Giê-ru-sa-lem. Có hai lừa cái được đóng yên đi cùng ông, và người hầu thiếp của ông cũng đi cùng.'),
(7036, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 19, 11, 'OT', 'Khi họ đến gần Y-bu-s, thì ngày đã xế lắm; và người đầy tớ nói với chủ mình: "Xin hãy vào thành của người Y-bu-sít này, và chúng ta sẽ nghỉ qua đêm tại đó."'),
(7037, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 19, 12, 'OT', 'Chúa nhân nói với người ấy: "Chúng ta sẽ không rẽ vào thành của người ngoại, không thuộc con cháu Y-sơ-ra-ên; chúng ta sẽ đi qua đến Ghi-bê-ah."'),
(7038, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 19, 13, 'OT', 'Bấy giờ người nói với đầy tớ mình: "Hãy đi, chúng ta sẽ đến một trong những nơi nầy để ngủ đêm, tại Ghi-bê hay là Ra-ma."'),
(7039, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 19, 14, 'OT', 'Họ đi qua và tiếp tục lên đường; rồi mặt trời lặn khi họ đến gần Ghi-bê-ah, thuộc về Bên-gia-min.'),
(7040, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 19, 15, 'OT', 'Họ rẽ vào đó để đi vào ở lại trong Ghi-bê-ah; và khi người ấy vào, thì ngồi xuống trong quảng trường của thành phố; nhưng không có người nào nhận họ vào nhà để ở trọ.'),
(7041, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 19, 16, 'OT', 'Kìa, có một người đàn ông già từ công việc ngoài đồng trở về vào buổi chiều tối; người ấy là người thuộc núi Ép-ra-im, và ông đang tạm cư tại Ghi-bê-ah; còn những người ở nơi đó là con cháu Bên-gia-min.'),
(7042, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 19, 17, 'OT', 'Hắn ngước mắt lên và thấy người khách lạ ở trong phố của thành phố; thì người già ấy nói: "Ngươi đi đâu và từ đâu đến?"'),
(7043, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 19, 18, 'OT', 'Người ấy nói với ông: "Chúng tôi đang đi từ Bê-lem thuộc Giu-đa đến vùng phía tây núi Ép-ra-im. Tôi xuất phát từ nơi đó, rồi đi đến Bê-lem thuộc Giu-đa, và bây giờ tôi đang đi đến nhà của Đức Giê-hô-va; nhưng không có ai tiếp nhận tôi vào nhà."'),
(7044, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 19, 19, 'OT', 'Tôi và các đầy tớ của ngài, cùng người nữ và thanh niên đi với chúng tôi, không thiếu thứ gì; chúng tôi có cả rơm và thức ăn cho các con lừa, lại cũng có bánh và rượu.'),
(7045, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 19, 20, 'OT', 'Người đàn ông già nói: Bình an cho anh; mọi nhu cầu của anh, tôi sẽ lo; nhưng đừng ngủ ngoài phố.'),
(7046, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 19, 21, 'OT', 'Người ấy dẫn ông vào nhà mình, rồi cấp thức ăn cho các lừa; họ rửa chân, rồi ăn và uống.'),
(7047, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 19, 22, 'OT', 'Chúng đang vui mừng thì nầy, những người trong thành, mấy kẻ gian ác thuộc dòng dõi Bê-li-ân, vây quanh nhà, đấm cửa và nói với người chủ nhà, ông già kia, rằng: "Hãy đưa ra người đàn ông đã vào nhà ông, để chúng tôi biết hắn."'),
(7048, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 19, 23, 'OT', 'Người đàn ông, chủ nhà, đi ra gặp họ và nói: "Xin anh em đừng làm điều ác này; người đàn ông này đã vào nhà tôi, xin đừng làm điều điên rồ như thế."'),
(7049, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 19, 24, 'OT', 'Này, đây là con gái ta, còn trinh, và người thứ thiếp của người ấy; ta sẽ đưa hai người ra, hãy làm nhục họ và làm điều gì đẹp lòng các ngươi; nhưng đừng làm điều nhục nhã này đối với người đàn ông này.'),
(7050, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 19, 25, 'OT', 'Nhưng những người đàn ông ấy không chịu nghe lời người ấy; người chồng liền nắm lấy người thứ thiếp mình, kéo ra ngoài cho họ, và họ đã ăn ở với nàng, hành hạ nàng suốt đêm cho đến sáng; khi rạng đông vừa bừng lên, họ buông thả nàng ra.'),
(7051, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 19, 26, 'OT', 'Người đàn bà ấy đến trước khi trời sáng, và ngã gục tại cửa nhà người đàn ông, nơi chủ của bà ở, cho đến khi trời sáng.'),
(7052, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 19, 27, 'OT', 'Chồng của nàng chỗi dậy sáng hôm ấy, mở cửa nhà và ra đi đường mình; này, người đàn bà, tức người thứ thiếp của ông, đã ngã gục trước cửa nhà, và hai tay nàng đặt trên ngưỡng cửa.'),
(7053, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 19, 28, 'OT', 'Người nói với nàng: "Hãy đứng dậy, chúng ta đi thôi," nhưng không ai trả lời. Rồi người đàn ông bồng nàng lên lưng lừa, đứng dậy và trở về nơi ở của mình.'),
(7054, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 19, 29, 'OT', 'Khi người vào nhà, ông lấy con dao, nắm lấy người thứ thiếp của mình, xẻ bà ra từng bộ phận cùng các xương, thành mười hai phần, rồi sai người mang đi khắp các vùng lãnh thổ của Ít-ra-en.'),
(7055, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 19, 30, 'OT', 'Khi ấy, mọi người thấy điều này liền nói: "Chưa từng có việc như thế này xảy ra hoặc được thấy từ ngày con cái Ít-ra-en ra khỏi đất Ai-cập cho đến ngày nay. Hãy suy xét điều này, đưa ra ý kiến và phát biểu."'),
(7056, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 1, 'OT', 'Hết thảy các con trai của Y-sơ-ra-ên đều ra đi, và toàn thể hội chúng được nhóm hiệp lại như một người, từ Đan cho đến Bê-e-Sê-ba, và xứ Ga-la-át, để ra trước mặt Đức Giê-hô-va tại Mít-ba.'),
(7057, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 2, 'OT', 'Toàn thể các đầu mục của toàn dân, mọi chi phái Y-sơ-ra-ên đều đứng ra trước hội nghị của dân sự Đức Chúa Trời, gồm bốn trăm ngàn người lính bộ đã rút gươm ra.'),
(7058, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 3, 'OT', 'Các con trai của Bên-gia-min nghe biết rằng các con trai Y-sơ-ra-ên đã lên đến Mít-pa; và các con trai Y-sơ-ra-ên nói: Hãy nói cho chúng tôi biết, điều ác này đã xảy ra như thế nào?'),
(7059, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 4, 'OT', 'Người thầy Lê-vi, chồng của người phụ nữ đã bị giết, trả lời và nói: Tôi và người thứ thiếp của tôi đã đến Ghi-bê-ah thuộc về Bên-gia-min để nghỉ qua đêm.'),
(7060, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 5, 'OT', 'Các người ở Ghíp-ê nổi lên chống tôi, vây nhà tôi lại vào ban đêm, định giết tôi; họ hãm hiếp người hầu gái của tôi khiến nàng chết.'),
(7061, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 6, 'OT', 'Tôi đã nắm lấy người thứ thiếp của mình, xé nàng ra từng mảnh, rồi sai người mang đi khắp các vùng đất thuộc sản nghiệp của Ít-ra-en; vì chúng đã làm điều gian ác và điên dại trong Ít-ra-en.'),
(7062, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 7, 'OT', 'Nầy, tất cả các ngươi đều là con cháu Y-sơ-ra-ên; hãy bàn luận và đưa ra ý kiến của mình.'),
(7063, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 8, 'OT', 'Cả dân chúng đứng dậy như một người, nói rằng: Không ai trong chúng ta sẽ đi về lều mình, cũng không ai trở về nhà mình.'),
(7064, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 9, 'OT', 'Bây giờ, điều nầy sẽ làm cho Ghi-bê-ah: chúng ta sẽ lên đánh nó theo sự chỉ định bằng thăm.'),
(7065, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 10, 'OT', 'Chúng ta sẽ chọn mười người trong mỗi một trăm, một trăm trong mỗi một ngàn, và một ngàn trong mỗi mười ngàn, từ mọi chi phái Y-sơ-ra-ên, để chuẩn bị lương thực cho dân chúng, hầu khi họ đến Ghíp-ê-th trong chi phái Bên-gia-min, thì thi hành điều mà chúng đã làm theo sự điên rồ mà chúng đã phạm trong Y-sơ-ra-ên.'),
(7066, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 11, 'OT', 'Toàn thể người Y-sơ-ra-ên đều tụ họp lại nơi thành ấy, như một người đồng lòng hiệp một.'),
(7067, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 12, 'OT', 'Các chi phái Y-sơ-ra-ên sai người đi khắp các chi phái Bên-gia-min, nói rằng: "Tội ác này, là điều dữ đã xảy ra giữa các ngươi, là điều gì?"'),
(7068, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 13, 'OT', 'Bây giờ hãy trao những người gian ác ở Ghi-bê-ah cho chúng tôi, để chúng tôi giết đi và gột bỏ điều ác khỏi Ít-ra-en. Nhưng con cái Bên-gia-min không chịu nghe theo tiếng gọi của anh em mình, là con cái Ít-ra-en.'),
(7069, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 14, 'OT', 'Các con trai của Bên-gia-min nhóm lại từ các thành đến Ghi-bê-ah, để ra đi giao chiến cùng các con trai của Ít-ra-en.'),
(7070, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 15, 'OT', 'Ngày ấy, người Bên-gia-min được điểm danh từ các thành, hai mươi sáu ngàn người rút gươm ra, ngoài những người ở Ghi-bê, được điểm danh là bảy trăm người trai trẻ chọn lọc.'),
(7071, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 16, 'OT', 'Trong toàn thể dân ấy có bảy trăm người trai trẻ chọn lọc, đều thuận tay trái; mỗi người này đều bắn trúng viên đá vào sợi tóc mà không hề trượt.'),
(7072, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 17, 'OT', 'Các người của Ít-ra-en, không kể chi phái Bên-gia-min, được kiểm tra số là bốn trăm ngàn người, tất cả đều là những người cầm gươm, toàn là chiến sĩ.'),
(7073, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 18, 'OT', 'Dân Y-sơ-ra-ên đứng dậy, lên Bê-thên và cầu hỏi Đức Chúa Trời. Họ hỏi: "Ai trong chúng tôi sẽ đi lên trước để giao chiến với con cháu Bên-gia-min?" Đức Giê-hô-va đáp: "Giu-đa sẽ đi lên trước."'),
(7074, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 19, 'OT', 'Dân Y-sơ-ra-ên dậy sớm vào buổi sáng và đóng trại đối diện với Ghi-bê-ah.'),
(7075, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 20, 'OT', 'Các người đàn ông của Y-sơ-ra-ên đi ra để giao chiến với Bên-gia-min; và các người đàn ông Y-sơ-ra-ên đã sắp hàng để chiến đấu với họ tại Ghi-bê-ah.'),
(7076, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 21, 'OT', 'Con cái của Bên-gia-min ra khỏi Ghi-bê-ah, và giết chết trong ngày ấy hai mươi hai ngàn người của Y-sơ-ra-ên.'),
(7077, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 22, 'OT', 'Dân sự, tức những người nam của Y-sơ-ra-ên, được thêm sức mạnh; họ lại sắp đặt đội hình chiến trận tại nơi mà họ đã bố trí trận thế trong ngày đầu tiên.'),
(7078, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 23, 'OT', 'Các con trai của Y-sơ-ra-ên đi lên, khóc lóc trước mặt Đức Giê-hô-va cho đến chiều tối, và hỏi Đức Giê-hô-va, nói rằng: "Tôi có nên tiếp tục lên đánh giặc với các con trai của Bên-gia-min, anh em tôi, không?" Đức Giê-hô-va đáp: "Hãy lên đánh nó."'),
(7079, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 24, 'OT', 'Dân Y-sơ-ra-ên tiến gần đến con cái của Bên-gia-min trong ngày thứ hai.'),
(7080, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 25, 'OT', 'Dân Xứ Bên-gia-min ra nghênh chiến với họ từ Ghi-bê-ah ngày thứ hai, và giết thêm mười tám ngàn người của con cái Ít-ra-en; tất cả những người này đều là chiến binh cầm gươm.'),
(7081, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 26, 'OT', 'Toàn thể con cái Y-sơ-ra-ên và toàn thể dân chúng lên đường, đến Bê-thên, khóc lóc, ngồi đó trước mặt Đức Giê-hô-va, nhịn ăn suốt ngày ấy cho đến chiều tối, và dâng những của lễ thiêu cùng những của lễ thù ân trước mặt Đức Giê-hô-va.'),
(7082, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 27, 'OT', 'Bấy giờ, con cái Y-sơ-ra-ên cầu hỏi Đức Giê-hô-va, và hòm giao ước của Đức Chúa Trời đang ở đó trong những ngày ấy.'),
(7083, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 28, 'OT', 'Bấy giờ, Phi-nê-ết, con trai của Ê-lê-a-xa, con trai của A-ha-ron, đứng trước hòm giao ước trong những ngày ấy, cầu hỏi rằng: "Tôi còn nên ra đi đánh giặc nữa với các con trai Bên-gia-min, anh em tôi, hay là tôi sẽ thôi?" Và Đức Giê-hô-va đáp: "Hãy đi lên, vì ngày mai Ta sẽ phó chúng nó vào tay các ngươi."'),
(7084, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 29, 'OT', 'Y-sơ-ra-ên đặt những toán phục kích vây quanh Ghi-bê-ah.'),
(7085, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 30, 'OT', 'Dân Y-sơ-ra-ên đi lên nghịch cùng con cháu Bên-gia-min vào ngày thứ ba, và họ bố trí đội hình đối nghịch với Ghi-bê-ah như trước kia, lần này đến lần khác.'),
(7086, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 31, 'OT', 'Các con trai Bên-gia-min xông ra đánh dân sự, rời khỏi thành phố, và bắt đầu giết những người chết trong dân sự như mọi lần, trên các con đường cái, một con dẫn lên Bê-thên và con kia dẫn đến Ghíp-tha trong đồng vắng, khoảng ba mươi người của Y-sơ-ra-ên.'),
(7087, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 32, 'OT', 'Các con trai của Bên-y-min nói: "Chúng đã bị đánh bại trước mặt chúng ta như lần đầu tiên." Nhưng các con trai của Y-sơ-ra-ên nói: "Hãy chạy trốn đi, để dụ chúng ra khỏi thành về phía các con đường cái."'),
(7088, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 33, 'OT', 'Mọi người của Y-sơ-ra-ên đều đứng dậy khỏi chỗ mình và bố trí quân đội tại Ba-anh Ta-ma; còn những toán phục kích của Y-sơ-ra-ên thì xông ra khỏi nơi ẩn nấp, từ các bụi rậm gần Ghi-bê-ah.'),
(7089, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 34, 'OT', 'Từ hướng đối diện với Ghi-bê-ah, mười ngàn người trai tráng được chọn lọc từ toàn thể Ít-ra-en kéo đến; cuộc chiến rất ác liệt, nhưng họ không biết rằng điều dữ đang giáng trên họ.'),
(7090, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 35, 'OT', 'Đức Giê-hô-va đánh bại người Bên-gia-min trước mặt Ít-ra-en; và các con trai Ít-ra-en tiêu diệt người Bên-gia-min trong ngày đó hai mươi lăm ngàn một trăm người, tất cả những người này đều rút gươm ra.'),
(7091, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 36, 'OT', 'Các con trai của Bên-gia-min thấy mình bị đánh bại; và các người của Ít-ra-en nhường chỗ cho Bên-gia-min, vì họ tin cậy vào những người phục kích mà họ đã đặt gần Ghi-bê-ah.'),
(7092, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 37, 'OT', 'Những người phục kích vội vàng đứng dậy, xông vào Gibêah; những người phục kích kéo dài hàng ngũ, dùng lưỡi gươm giết hết mọi người trong thành.'),
(7093, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 38, 'OT', 'Và người Y-sơ-ra-ên đã hẹn với những kẻ phục kích rằng, họ phải làm cho một cột khói lớn bốc lên từ thành phố.'),
(7094, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 39, 'OT', 'Các người của Y-sơ-ra-ên quay trở lại trong cuộc chiến, và Bên-gia-min bắt đầu đánh giết khoảng ba mươi người của Y-sơ-ra-ên; vì chúng nó nói: "Chắc chắn chúng nó đã bị đánh bại trước mặt chúng ta, như trong trận chiến đầu tiên."'),
(7095, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 40, 'OT', 'Khi ngọn lửa bắt đầu bốc lên từ thành với một cột khói, người Bên-gia-min quay lại nhìn đằng sau mình, và nầy, khói của thành đã bốc lên trời cao.'),
(7096, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 41, 'OT', 'Dân Y-sơ-ra-ên quay lại, và các người của Bên-gia-min hoảng hốt, vì thấy rằng tai họa đã giáng trên họ.'),
(7097, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 42, 'OT', 'Họ quay lưng lại trước mặt người Ít-ra-en về phía con đường sa mạc; nhưng trận chiến đuổi theo kịp họ, và những người từ các thành phố đánh bại họ ở giữa vòng vây.'),
(7098, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 43, 'OT', 'Họ vây các người Bên-gia-min, đuổi theo, dồn ép họ đến gần Ghi-bê-ah về phía đông mặt trời mọc.'),
(7099, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 44, 'OT', 'Bấy giờ có mười tám ngàn người Bên-gia-min ngã xuống; tất cả những người nầy đều là chiến sĩ dũng cảm.'),
(7100, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 45, 'OT', 'Họ quay lưng chạy trốn về phía đồng vắng đến hòn đá Rim-môn; người ta giết năm ngàn người trong bọn họ dọc các con đường; và tiếp tục đuổi theo họ sát đến Ghít-đôm, rồi giết thêm hai ngàn người nữa.'),
(7101, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 46, 'OT', 'Tất cả những người ngã xuống trong ngày ấy thuộc chi phái Bên-gia-min là hai mươi lăm ngàn người, đều là những chiến sĩ dũng cảm, rút gươm ra chiến đấu.'),
(7102, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 47, 'OT', 'Nhưng sáu trăm người quay đi và trốn vào đồng vắng, đến hòn đá Rim-môn, và ở lại trong hòn đá Rim-môn bốn tháng.'),
(7103, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 20, 48, 'OT', 'Người của Ít-ra-en quay lại đánh dân Bên-gia-min, giết họ bằng lưỡi gươm, từ thành người cho đến súc vật, và tất cả những gì tìm thấy; họ cũng phóng hỏa thiêu các thành mà họ tìm thấy.'),
(7104, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 21, 1, 'OT', 'Các người đàn ông của Y-sơ-ra-ên đã thề tại Mít-pa, nói rằng: Không ai trong chúng ta sẽ gả con gái mình cho người Bên-gia-min làm vợ.'),
(7105, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 21, 2, 'OT', 'Dân sự đến nhà Đức Chúa Trời, và ở đó cho đến chiều tối trước mặt Đức Chúa Trời; họ cất tiếng khóc, khóc lóc thảm thiết.'),
(7106, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 21, 3, 'OT', 'Họ nói: "Lạy Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en, tại sao điều này lại xảy ra tại Ít-ra-en, khiến hôm nay một chi phái lại thiếu vắng trong Ít-ra-en?"'),
(7107, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 21, 4, 'OT', 'Hôm sau, dân chúng dậy sớm, xây một bàn thờ tại đó và dâng các lễ thiêu cùng các lễ thù ân.'),
(7108, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 21, 5, 'OT', 'Các con trai của Y-sơ-ra-ên nói: "Ai là người trong tất cả các chi phái Y-sơ-ra-ên đã không lên cùng hội chúng đến cùng Đức Giê-hô-va? Vì đã có lời thề lớn đối với bất cứ ai không lên đến cùng Đức Giê-hô-va tại Mít-pa, rằng: ''Người ấy chắc chắn sẽ bị giết chết.''"'),
(7109, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 21, 6, 'OT', 'Các con trai Ít-ra-en thương tiếc Bên-gia-min, anh em mình, và nói: Hôm nay một chi phái đã bị cắt đứt khỏi Ít-ra-en.'),
(7110, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 21, 7, 'OT', 'Chúng ta phải làm gì cho những người còn sống sót về vấn đề vợ? Vì chúng ta đã thề bởi Đức Giê-hô-va rằng không được gả con gái mình cho họ làm vợ.'),
(7111, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 21, 8, 'OT', 'Họ nói: "Ai là một trong các chi phái của Y-sơ-ra-ên mà chưa lên đến Mít-pê để gặp Đức Giê-hô-va? Và nầy, chẳng có ai từ Gia-bết Ghi-lê-át đến trại quân để dự hội nghị."'),
(7112, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 21, 9, 'OT', 'Dân sự được điểm danh, và này, không có một người nào trong những người ở Gia-be-s Ga-la-át ở đó.'),
(7113, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 21, 10, 'OT', 'Hội chúng sai đến đó mười hai ngàn người trai tráng, và truyền cho họ rằng: "Hãy đi, đánh giết dân cư Giáp-ết trong đất Ga-la-át bằng lưỡi gươm, cả đàn bà và trẻ em."'),
(7114, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 21, 11, 'OT', 'Đây là điều các ngươi phải làm: phải tiêu diệt hoàn toàn mọi người nam, và mọi người nữ đã biết nằm cùng người nam.'),
(7115, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 21, 12, 'OT', 'Họ tìm thấy trong các cư dân ở Yabe-s Ghi-lê-đa bốn trăm cô gái trẻ còn trinh, chưa từng có người đàn ông nào nằm với họ; và họ đem các cô ấy đến trại tại Si-lô, là nơi thuộc đất Ca-na-an.'),
(7116, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 21, 13, 'OT', 'Toàn thể hội chúng sai sứ đi nói chuyện với những người con trai của Bên-gia-min đang ở nơi hòn đá Rim-môn, và mời họ đến trong hòa bình.'),
(7117, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 21, 14, 'OT', 'Bấy giờ, Bên-gia-min trở về; và người ta đã giao các người vợ mà họ đã cứu sống từ các phụ nữ ở Gia-bết-Gi-lean cho chúng; nhưng dù vậy, các người vợ ấy vẫn không đủ cho chúng.'),
(7118, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 21, 15, 'OT', 'Dân chúng cảm thấy tiếc cho chi phái Bên-gia-min, vì Đức Giê-hô-va đã gây ra một khoảng trống trong các chi phái của Ít-ra-en.'),
(7119, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 21, 16, 'OT', 'Các bậc trưởng lão của hội chúng nói: "Chúng ta phải làm gì cho những người còn sót lại để có vợ, vì các phụ nữ đã bị tiêu diệt khỏi chi phái Bên-gia-min?"'),
(7120, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 21, 17, 'OT', 'Họ nói: "Phải có cơ nghiệp cho những người sống sót thuộc chi phái Bên-gia-min, để chi phái ấy không bị xoá khỏi Ít-ra-en."'),
(7121, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 21, 18, 'OT', 'Chúng tôi không thể trao các cô gái từ con gái chúng tôi cho họ, vì các con trai Y-sơ-ra-ên đã thề rằng: "Phải bị rủa sả người nào trao vợ cho Bên-gia-min."'),
(7122, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 21, 19, 'OT', 'Họ nói: "Kìa, hằng năm có lễ của Đức Giê-hô-va tại Si-lô, ở phía bắc Bê-thên, bên phía đông con đường cái lên từ Bê-thên đến Si-chem, và ở phía nam Lê-bô-na."'),
(7123, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 21, 20, 'OT', 'Họ dặn các con trai Bên-gia-min rằng: "Hãy đi phục kích trong các vườn nho."'),
(7124, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 21, 21, 'OT', 'Hãy nhìn xem, này nếu các con gái Si-lô ra đi nhảy múa trong các điệu múa, thì các ngươi hãy ra khỏi các vườn nho, mỗi người hãy bắt vợ mình từ các con gái Si-lô, rồi đi về đất Bên-gia-min.'),
(7125, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 21, 22, 'OT', 'Và xảy ra khi cha của họ hoặc anh em họ đến cùng chúng tôi để khiếu nại, thì chúng tôi sẽ nói với họ: "Xin hãy tỏ lòng nhân từ đối với họ vì chúng tôi, vì chúng tôi đã không chiếm lấy vợ cho mỗi người trong chiến tranh; bởi các ông đã không trao họ cho họ vào lúc đó, nên các ông không mắc tội."'),
(7126, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 21, 23, 'OT', 'Các con trai của Bên-gia-min cũng làm như vậy, lấy các người vợ theo số lượng của mình từ những người con gái đang múa, mà họ đã bắt được; rồi họ đi và trở về cơ nghiệp mình, xây cất các thành và ở trong đó.'),
(7127, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 21, 24, 'OT', 'Bấy giờ, các con trai của Y-sơ-ra-ên rời khỏi đó, mỗi người về chi phái và về gia tộc mình, và họ ra đi từ đó, mỗi người đến phần đất cơ nghiệp của mình.'),
(7128, 7, 'GOI_vi', 'GOI_vi', 'vi', 'JDG', 21, 25, 'OT', 'Trong những ngày ấy, không có vua ở Y-sơ-ra-ên; mỗi người làm điều mình cho là đúng trong mắt mình.'),
(7129, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 1, 1, 'OT', 'Xảy ra trong những ngày các quan xét trị vì, thì có nạn đói trong đất. Một người đàn ông từ Bê-lem thuộc xứ Giu-đa đi sống tạm ở đồng Mô-áp, cùng với vợ và hai người con trai của ông.'),
(7130, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 1, 2, 'OT', 'Tên người chồng là Ê-li-me-lech, tên vợ ông là Na-ô-mi, và tên hai con trai ông là Ma-lôn và Ki-li-ôn, người Ê-phrát thuộc Bết-lê-hem Giu-đa. Họ đi đến vùng đất Mô-áp và sống ở đó.'),
(7131, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 1, 3, 'OT', 'Ê-li-me-léc, chồng của Na-ô-mi, qua đời; bà ở lại với hai người con trai của mình.'),
(7132, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 1, 4, 'OT', 'Họ cưới vợ người Mô-áp cho mình; tên người vợ thứ nhất là Ô-ru-pha, tên người vợ thứ hai là Ru-tơ. Họ sống ở đó khoảng mười năm.'),
(7133, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 1, 5, 'OT', 'Rồi Ma-lôn và Ki-li-ôn cũng đều qua đời; và người đàn bà bị bỏ lại, không còn hai người con trai và chồng mình.'),
(7134, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 1, 6, 'OT', 'Bà ấy liền đứng dậy cùng với hai con dâu mình, trở về từ các đồng Mô-áp, vì bà đã nghe ở đồng Mô-áp rằng Đức Giê-hô-va đã thăm viếng dân Ngài để ban cho họ lương thực.'),
(7135, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 1, 7, 'OT', 'Bà rời khỏi nơi bà đang ở, và hai con dâu đi cùng bà; họ lên đường trở về đất Giu-đa.'),
(7136, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 1, 8, 'OT', 'Na-ô-mi nói với hai con dâu mình: "Hãy đi, trở về nhà mẹ mình. Nguyện Đức Giê-hô-va làm ơn bao dung với các con, như các con đã làm ơn với những người đã khuất và với tôi."'),
(7137, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 1, 9, 'OT', 'Nguyện Đức Giê-hô-va ban cho các con được an nghỉ, mỗi người trong nhà chồng mình. Rồi bà hôn hai con dâu; cả hai bật khóc nức nở.'),
(7138, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 1, 10, 'OT', 'Hai người nói với bà: "Chúng tôi sẽ trở về với dân của bà."'),
(7139, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 1, 11, 'OT', 'Na-ô-mi nói: "Hỡi các con gái của ta, hãy trở về đi! Sao các con lại muốn đi với ta? Trong lòng ta còn có con trai nào nữa đâu, để làm chồng các con sao?"'),
(7140, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 1, 12, 'OT', 'Hỡi các con gái của ta, hãy trở về đi; ta đã quá già để có thể lấy chồng nữa. Dù ta nói rằng ta còn hy vọng, dù ta có thể lấy chồng ngay đêm nay và sinh thêm con trai,'),
(7141, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 1, 13, 'OT', 'Hỡi các con gái của ta, các con có chịu đợi đến khi chúng lớn lên không? Các con có chịu ở góa, không lấy chồng để chờ chúng không? Không, các con gái của ta ơi, vì ta rất buồn bã vì các con, bởi tay Đức Giê-hô-va đã chống lại ta.'),
(7142, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 1, 14, 'OT', 'Họ cất tiếng khóc và khóc lần nữa; rồi Or-pa hôn người mẹ chồng mình, còn Ru-tơ thì níu chặt bà.'),
(7143, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 1, 15, 'OT', 'Bà ấy nói: "Này, chị dâu con đã trở về cùng dân tộc và cùng các thần của nàng rồi; con hãy trở về theo chị dâu con đi."'),
(7144, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 1, 16, 'OT', 'Rút nói: Xin đừng nài tôi bỏ bà mà trở về, vì đâu bà đi, tôi sẽ đi; đâu bà nghỉ đêm, tôi sẽ nghỉ đêm; dân của bà là dân của tôi, và Đức Chúa Trời của bà là Đức Chúa Trời của tôi.'),
(7145, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 1, 17, 'OT', 'Mẹ chết nơi nào, con sẽ chết nơi đó, và con sẽ được chôn ở đó. Nguyện Đức Giê-hô-va xử với con thể ấy, và thêm nữa, nếu có sự chi khác hơn sự chết phân cách mẹ và con.'),
(7146, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 1, 18, 'OT', 'Thấy rõ nàng quyết tâm đi cùng mình, bà liền thôi không nói gì thêm với nàng nữa.'),
(7147, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 1, 19, 'OT', 'Hai người đàn bà ấy cùng đi, cho đến khi họ đến Bết-lê-hem. Khi họ đến Bết-lê-hem, thì cả thành phố đều xôn xao vì họ, và người ta nói: "Đây có phải là Na-ô-mi không?"'),
(7148, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 1, 20, 'OT', 'Bà ấy nói với họ: "Đừng gọi tôi là Na-ô-mi, hãy gọi tôi là Ma-ra, vì Đấng Toàn Năng đã khiến tôi phải đắng cay vô cùng."'),
(7149, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 1, 21, 'OT', 'Tôi ra đi đầy đủ, nhưng Đức Giê-hô-va đã khiến tôi trở về tay không; sao các cô còn gọi tôi là Na-ô-mi, khi Đức Giê-hô-va đã chống lại tôi và Đấng Toàn Năng đã làm tôi khốn khổ?'),
(7150, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 1, 22, 'OT', 'Na-ô-mi trở về, và Rút, người phụ nữ Mô-áp, con dâu bà, cùng về với bà, hai người trở về từ các cánh đồng của Mô-áp; và họ đến Bết-lê-hem vào lúc đầu mùa gặt lúa mạch.'),
(7151, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 2, 1, 'OT', 'Na-ô-mi có một người thân của chồng, là một người đàn ông giàu có và danh giá, thuộc dòng họ Ê-li-me-léc; tên người ấy là Bô-az.'),
(7152, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 2, 2, 'OT', 'Rút, người phụ nữ Mô-áp, nói với Na-ô-mi: "Con xin đi ra đồng, và nhặt lúa rơi sau người mà con được ơn trước mặt người ấy." Na-ô-mi nói với nàng: "Con cứ đi, con gái ta ơi."'),
(7153, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 2, 3, 'OT', 'Bà đi, vào ruộng và nhặt lúa sau các thợ gặt; tình cờ bà gặp phần ruộng thuộc về Bô-az, người thuộc họ Ê-li-mê-léc.'),
(7154, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 2, 4, 'OT', 'Kìa, Bô-az từ Bết-lê-hem đi đến, và nói với những người gặt: Đức Giê-hô-va ở cùng các anh em. Họ đáp lại người rằng: Nguyện Đức Giê-hô-va ban phước cho ông.'),
(7155, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 2, 5, 'OT', 'Bấy giờ, Bô-az nói với người đầy tớ coi sóc các thợ gặt rằng: "Cô gái này là của ai?"'),
(7156, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 2, 6, 'OT', 'Người trẻ tuổi được đặt coi sóc những thợ gặt đáp lại và nói: "Cô gái người Mô-áp đó là ai, đã trở về cùng Na-ô-mi từ đồng Mô-áp."'),
(7157, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 2, 7, 'OT', 'Cô ấy nói: "Tôi xin được nhặt và gom lúa sau những người gặt trong các đụm lúa"; cô ấy đã đến và đứng ở đây từ sáng sớm cho đến bây giờ, chỉ mới vào nhà nghỉ một chút.'),
(7158, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 2, 8, 'OT', 'Bấy giờ Bô-az nói với Rút: "Này con gái ta, hãy nghe đây: con đừng đi gặt lượm ở ruộng người khác, cũng đừng rời khỏi đây, nhưng hãy ở gần các nữ tớ gái của ta."'),
(7159, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 2, 9, 'OT', 'Mắt ngươi hãy để trên ruộng mà những người ấy đang gặt, và ngươi hãy đi theo sau họ; chẳng phải ta đã dặn các thanh niên đừng đụng đến ngươi sao? Và khi ngươi khát, hãy đi đến các cái bình và uống nước mà các thanh niên đã xách lên.'),
(7160, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 2, 10, 'OT', 'Bà liền cúi sấp mặt xuống đất, lạy ông và thưa: "Tại sao tôi lại được ơn trước mắt ông, đến nỗi ông quan tâm đến tôi, trong khi tôi chỉ là một người ngoại quốc?"'),
(7161, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 2, 11, 'OT', 'Bô-az đáp và nói với nàng: "Tất cả những điều nàng đã làm cho mẹ chồng mình từ khi chồng nàng qua đời đã được thuật lại cho tôi biết rõ; nàng đã bỏ cha mẹ và xứ sở sinh trưởng của mình, đến cùng một dân tộc mà trước đây nàng chưa hề biết."'),
(7162, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 2, 12, 'OT', 'Đức Giê-hô-va ban cho con phần thưởng xứng đáng với việc con làm, và con sẽ nhận được phần thưởng trọn vẹn từ Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên, Đấng mà con đã đến nương náu dưới cánh của Ngài.'),
(7163, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 2, 13, 'OT', 'Bà ấy thưa: "Xin hãy để tôi tìm được ơn trước mặt ngài, thưa ông chủ tôi, vì ngài đã an ủi tôi và nói lời tử tế với nữ tớ gái của ngài, dù tôi không bằng một trong các nữ tớ gái của ngài."'),
(7164, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 2, 14, 'OT', 'Bấy giờ Bô-az nói với nàng: "Đến trưa, hãy lại gần đây mà ăn bánh, và chấm miếng bánh của nàng trong dấm." Nàng bèn ngồi bên những thợ gặt; rồi ông đưa cho nàng những hạt lúa rang, nàng ăn xong, được no đủ, và còn dư lại.'),
(7165, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 2, 15, 'OT', 'Cô đứng dậy để gặt lúa mót, thì Bô-az truyền lệnh cho các thanh niên mình rằng: "Ngay cả giữa những bó lúa, cô ấy cũng được gặt lúa mót, và các ngươi không được trách móc cô ấy."'),
(7166, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 2, 16, 'OT', 'Hãy cố ý rút bớt một ít lúa từ các bó lúa và để lại cho nàng; nàng sẽ nhặt, và các ngươi không được quở trách nàng.'),
(7167, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 2, 17, 'OT', 'Bà mót lúa đến chiều tối, rồi đập lúa mà bà đã gặt được; thì ra được khoảng một e-pha lúa mạch.'),
(7168, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 2, 18, 'OT', 'Bà ấy mang lúa về, vào thành; mẹ chồng bà thấy những gì bà gặt được; bà lấy ra và đưa cho mẹ chồng những gì còn sót lại sau khi mình đã ăn đủ.'),
(7169, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 2, 19, 'OT', 'Bà mẹ chồng hỏi bà: "Hôm nay con gặt lúa ở đâu, và làm việc ở chỗ nào? Nguyện người đã để ý đến con được phước!" Rồi bà thuật lại cho bà mẹ chồng biết mọi điều mình đã làm cùng người ấy, và nói: "Tên người đàn ông mà hôm nay con làm việc cùng ông ấy là Bô-az."'),
(7170, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 2, 20, 'OT', 'Na-ô-mi nói với con dâu mình: "Người ấy được Đúc Giê-hô-va ban phước, vì Ngài không thôi làm ơn cho kẻ sống và kẻ chết." Rồi Na-ô-mi nói với nàng: "Người ấy là người thân gần của chúng ta, một trong những người bà con gần nhất của chúng ta."'),
(7171, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 2, 21, 'OT', 'Rút, người phụ nữ Mô-áp, nói: "Người ấy cũng nói với tôi: ''Ngươi hãy bám chặt vào những người trẻ làm việc cho ta, cho đến khi họ hoàn tất toàn bộ mùa gặt của ta.''"'),
(7172, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 2, 22, 'OT', 'Na-ô-mi nói với Rút, con dâu mình: "Thật tốt, con gái ta, nếu con đi ra đồng cùng với các nữ tì của anh ấy, để con khỏi bị ai sàm sỡ trong cánh đồng khác."'),
(7173, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 2, 23, 'OT', 'Bà liền gắn bó với các nữ tì của Bô-az để gặt lúa mạch cho đến khi mùa gặt lúa mạch và mùa gặt lúa mì kết thúc; rồi bà ở cùng với bà mẹ chồng mình.'),
(7174, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 3, 1, 'OT', 'Bà Na-ô-mi, mẹ chồng nàng, nói với nàng: "Này con gái ta, ta chẳng nên tìm nơi an nghỉ cho con sao, để con được hạnh phúc?"'),
(7175, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 3, 2, 'OT', 'Và bây giờ, chẳng phải Bô-az là người bà con của chúng ta sao, mà cô đã làm việc cùng các nữ tì của ông ấy? Kìa, ông ấy đang đập lúa mạch trên sân đập lúa đêm nay.'),
(7176, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 3, 3, 'OT', 'Hãy tắm rửa, xức dầu, mặc áo choàng của con vào, rồi xuống sân lúa; chớ để người đàn ông nhận biết con, cho đến khi người ấy ăn và uống xong.'),
(7177, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 3, 4, 'OT', 'Và khi người nằm xuống, hãy xem chỗ ông ấy nằm, rồi ngươi hãy đi, lật phần chân ra và nằm xuống; chính người ấy sẽ chỉ cho ngươi biết điều ngươi phải làm.'),
(7178, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 3, 5, 'OT', 'Bà ấy nói với nàng: Tất cả những gì con nói với ta, ta sẽ làm.'),
(7179, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 3, 6, 'OT', 'Bà đi xuống sân đập lúa và làm theo mọi điều mà mẹ chồng đã dặn bà.'),
(7180, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 3, 7, 'OT', 'Bô-az ăn và uống xong, lòng người vui vẻ, bèn đi nằm ở cuối đống lúa; rồi Rút đến, lén mở chăn ở chân người và nằm xuống.'),
(7181, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 3, 8, 'OT', 'Đến giữa đêm, người đàn ông bỗng sợ hãi và quay mình lại, thì thấy một người phụ nữ đang nằm ở dưới chân mình.'),
(7182, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 3, 9, 'OT', 'Người ấy hỏi: "Cô là ai?" Cô đáp: "Tôi là Rút, người đầy tớ của ngài. Xin hãy trải áo choàng của ngài ra che phủ lấy người đầy tớ ngài, vì ngài là người chuộc.'),
(7183, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 3, 10, 'OT', 'Và ông nói: "Con được phước của Đức Giê-hô-va, hỡi con gái ta! Lòng nhân từ sau cùng của con tốt hơn lòng nhân từ đầu tiên, vì con đã không đi theo những người trẻ tuổi, dù nghèo hay giàu."'),
(7184, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 3, 11, 'OT', 'Và bây giờ, hỡi con gái ta, đừng sợ; ta sẽ làm cho con mọi điều con nói, vì mọi người trong thành của dân ta đều biết con là người đức hạnh.'),
(7185, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 3, 12, 'OT', 'Và bây giờ, quả thật ta là người bà con gần, nhưng cũng có một người bà con gần hơn ta.'),
(7186, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 3, 13, 'OT', 'Hãy ở lại đây đêm nay; và nếu sáng mai người ấy muốn làm trọn bổn phận người bà con, thì cứ để người ấy làm; nhưng nếu người ấy không muốn làm trọn bổn phận người bà con đối với con, thì chính tôi sẽ làm trọn bổn phận người bà con cho con, Đức Giê-hô-va hằng sống. Hãy nằm xuống cho đến sáng.'),
(7187, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 3, 14, 'OT', 'Cô nằm nơi chân ông cho đến sáng, rồi thức dậy trước khi người nọ nhận ra người kia. Ông nói: "Đừng để ai biết rằng có một người phụ nữ đã đến nơi đống lúa."'),
(7188, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 3, 15, 'OT', 'Người nói: "Cô hãy mang tấm khăn choàng đang đắp trên mình ra, và cầm lấy." Cô liền cầm lấy; người đo sáu lạng lúa mạch rồi đặt lên cho cô; rồi người vào thành.'),
(7189, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 3, 16, 'OT', 'Khi cô về gặp mẹ chồng, bà hỏi: "Con là ai, hỡi con gái ta?" Cô thuật lại cho bà mọi điều mà người đàn ông đã làm cho cô.'),
(7190, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 3, 17, 'OT', 'Bà ấy nói: "Người đã đưa cho tôi sáu lạng lúa mạch này, vì người nói với tôi: ''Đừng trở về với mẹ chồng mà tay không.''"'),
(7191, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 3, 18, 'OT', 'Bà nói: "Hãy ngồi yên, con gái ta, cho đến khi con biết việc này sẽ ra sao, vì người đàn ông ấy sẽ không yên nghỉ cho đến khi hoàn tất việc này trong ngày hôm nay."'),
(7192, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 4, 1, 'OT', 'Bấy giờ Bô-az đi lên cổng thành và ngồi ở đó. Nầy, người anh em họ mà Bô-az đã nói đến đang đi ngang qua; ông bèn nói: "Nầy anh kia, hãy ghé vào đây và ngồi xuống." Người ấy liền ghé vào và ngồi xuống.'),
(7193, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 4, 2, 'OT', 'Ông lấy mười người trong các bậc trưởng lão của thành, rồi nói: "Hãy ngồi xuống đây." Và họ ngồi xuống.'),
(7194, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 4, 3, 'OT', 'Rút nói với người bà con: Na-ô-mi, người đã trở về từ đồng cỏ Mô-áp, đang bán phần đất thuộc về anh chúng ta là Ê-li-me-léc.'),
(7195, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 4, 4, 'OT', 'Tôi đã nghĩ đến việc báo cho ông biết, nói rằng: Hãy mua đi trước mặt những người sống ở đây và trước mặt các trưởng lão của dân tôi. Nếu ông muốn chuộc, thì hãy chuộc; còn nếu ông không muốn chuộc, hãy nói cho tôi biết ngay, vì ngoài ông ra thì không ai có quyền chuộc tôi cả; và tôi là người kế tiếp sau ông. Ông ấy đáp: Tôi sẽ chuộc.'),
(7196, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 4, 5, 'OT', 'Bởi vậy, Bô-az nói: "Ngày nào ngươi mua thửa ruộng từ tay Na-ô-mi, thì cũng phải mua từ Ru-tơ người Mô-áp, vợ của người đã chết, để phục hồi danh tiếng của người đã chết trên cơ nghiệp của người."'),
(7197, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 4, 6, 'OT', 'Người cứu chuộc nói: Tôi không thể cứu chuộc cho mình được, e rằng tôi sẽ làm hại phần sản nghiệp của tôi; chính anh hãy cứu chuộc lấy quyền cứu chuộc của tôi, vì tôi không thể cứu chuộc được.'),
(7198, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 4, 7, 'OT', 'Trước kia, trong Y-sơ-ra-ên, để làm chứng về việc chuộc lại hoặc trao đổi, một người nào đó cởi giày mình ra trao cho người hàng xóm mình; và điều này là bằng chứng trong Y-sơ-ra-ên.'),
(7199, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 4, 8, 'OT', 'Người chuộc ấy nói với Bô-az: "Hãy mua đi." Rồi ông cởi giày mình ra.'),
(7200, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 4, 9, 'OT', 'Bởi vậy, Bô-az nói với các trưởng lão và toàn thể dân chúng: "Hôm nay, các ngài làm chứng cho tôi rằng tôi đã mua tất cả những gì thuộc về Ê-li-me-léc, và tất cả những gì thuộc về Ki-li-ôn và Ma-lôn, do tay Na-ô-mi."'),
(7201, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 4, 10, 'OT', 'Đồng thời, tôi cũng đã đón nàng Rút, người phụ nữ Mô-áp, vợ của Ma-lôn, làm vợ mình, để lập danh tiếng cho người đã khuất trên cơ nghiệp của người ấy, hầu danh người đã khuất không bị xoá bỏ giữa anh em và nơi cửa thành của nơi người ấy ở. Hôm nay, các ông là chứng nhân.'),
(7202, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 4, 11, 'OT', 'Tất cả dân chúng tại cửa thành và các bậc trưởng lão đều nói: "Chúng tôi làm chứng. Nguyện Đức Giê-hô-va khiến cho người phụ nữ vào nhà ngươi được như Ra-chên và Lê-a, hai người đã xây dựng nên nhà Y-sơ-ra-ên; nguyện ngươi làm nên việc lớn tại Ép-ra-tha và nổi danh tại Bê-lem."'),
(7203, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 4, 12, 'OT', 'Nguyện nhà ngươi được như nhà Phê-rết mà Ta-ma đã sinh cho Giu-đa, bởi dòng dõi mà Đức Giê-hô-va sẽ ban cho ngươi từ người thiếu nữ này.'),
(7204, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 4, 13, 'OT', 'Vậy Bô-az lấy Rút làm vợ mình; và khi ông vào cùng nàng, thì Đức Giê-hô-va ban cho nàng được thọ thai, và nàng sinh một con trai.'),
(7205, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 4, 14, 'OT', 'Các người phụ nữ nói với Na-ô-mi: "Đức Giê-hô-va được tôn vinh, Đấng ngày nay không để bà thiếu người chuộc, để danh người ấy được lưu danh trong Y-sơ-ra-ên."'),
(7206, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 4, 15, 'OT', 'Người sẽ là nguồn an ủi cho linh hồn ngươi và nuôi dưỡng tuổi già ngươi; bởi vì con dâu ngươi, người đã yêu thương ngươi, đã sinh ra người ấy, và nàng tốt cho ngươi hơn bảy người con trai.'),
(7207, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 4, 16, 'OT', 'Na-ô-mi bồng đứa trẻ, đặt nó vào lòng mình và chăm sóc nó như một người vú nuôi.'),
(7208, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 4, 17, 'OT', 'Các người hàng xóm đã đặt tên cho đứa trẻ, nói: "Một đứa con trai đã sinh ra cho Na-ô-mi"; và họ đặt tên nó là Ô-bết, chính người cha của Ít-sai, cha của Đa-vít.'),
(7209, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 4, 18, 'OT', 'Đây là các thế hệ của Pha-rết: Pha-rết sinh ra Hết-rôn.'),
(7210, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 4, 19, 'OT', 'Hết-rôn sinh Ra-am, và Ra-am sinh A-mi-na-đáp.'),
(7211, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 4, 20, 'OT', 'A-min-na-đáp sinh ra Nát-sôn, và Nát-sôn sinh ra Xan-ma.'),
(7212, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 4, 21, 'OT', 'Xa-lô-mon sinh ra Bô-az, và Bô-az sinh ra Ô-bết.'),
(7213, 8, 'GOI_vi', 'GOI_vi', 'vi', 'RUT', 4, 22, 'OT', 'Và Ô-bết sinh ra Ít-sai, và Ít-sai sinh ra Đa-vít.'),
(7214, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 1, 1, 'OT', 'Có một người đàn ông ở Rama-thai-mi-xo-phi, thuộc núi Ép-ra-im, tên là Ên-ca-na, con trai của Giê-rô-ham, con trai của Ê-li-hu, con trai của Tô-hu, con trai của Xúp, người Ép-ra-thi.'),
(7215, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 1, 2, 'OT', 'Người có hai vợ; tên một người là Ha-na, tên người kia là Pên-ni-na. Pên-ni-na có con cái, còn Ha-na thì không có con.'),
(7216, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 1, 3, 'OT', 'Người đàn ông ấy từ thành phố mình lên mỗi năm để thờ lạy và dâng của lễ cho Đức Giê-hô-va vạn quân tại Si-lô. Tại đó, hai con trai của Ê-li, là Hop-ni và Phi-nê-has, các thầy tế lễ cho Đức Giê-hô-va.'),
(7217, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 1, 4, 'OT', 'Một ngày kia, khi Ên-ca-na dâng của lễ, ông đã đưa phần cho Pên-ni-na, vợ mình, và cho tất cả các con trai và con gái của bà.'),
(7218, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 1, 5, 'OT', 'Còn về phần Ha-na, ông ban cho một phần bội phần, vì ông yêu thương Ha-na; nhưng Đức Giê-hô-va đã đóng kín tử cung bà.'),
(7219, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 1, 6, 'OT', 'Người vợ gây ghen ghét nàng cũng làm nàng bực bội rất nhiều, để khiến nàng buồn rầu, vì Đức Giê-hô-va đã đóng tử cung nàng lại.'),
(7220, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 1, 7, 'OT', 'Mỗi năm, mỗi khi nàng lên nhà của Đức Giê-hô-va, thì cũng vậy, người vợ kia làm nàng tức giận; nàng bèn khóc và không ăn.'),
(7221, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 1, 8, 'OT', 'Vậy Ên-ca-na, chồng bà, nói với nàng Ha-na: "Hỡi Ha-na, tại sao ngươi khóc? Tại sao ngươi không ăn? Tại sao lòng ngươi buồn bã? Ta chẳng tốt cho ngươi hơn mười đứa con trai sao?"'),
(7222, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 1, 9, 'OT', 'Ha-na đứng dậy sau khi ăn và uống xong ở Si-lô; còn thầy tế lễ Ê-li đang ngồi trên một cái ghế gần trụ cửa đền thờ của Đức Giê-hô-va.'),
(7223, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 1, 10, 'OT', 'Bà ấy tâm hồn đầy buồn bã, bèn cầu nguyện cùng Đức Giê-hô-va và khóc rất thảm thiết.'),
(7224, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 1, 11, 'OT', 'Người đã khấn một lời khấn và nói: Lạy Đức Giê-hô-va vạn quân, nếu Ngài thật sự nhìn đến nỗi khốn khổ của tớ gái Ngài, và nhớ đến tôi, không quên tớ gái Ngài, mà ban cho tớ gái Ngài một con trai, thì tôi sẽ dâng nó cho Đức Giê-hô-va trọn đời nó, và dao cạo sẽ không hề chạm đến đầu nó.'),
(7225, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 1, 12, 'OT', 'Xảy ra khi nàng cầu nguyện lâu dài trước mặt Đức Giê-hô-va, thì Ê-li chăm chú nhìn miệng nàng.'),
(7226, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 1, 13, 'OT', 'Hannah nói thầm trong lòng; chỉ có môi nàng chuyển động, nhưng tiếng nói của nàng không nghe thấy được; nên Ê-li tưởng nàng say rượu.'),
(7227, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 1, 14, 'OT', 'Ê-li nói với nàng: "Bao lâu nữa ngươi mới thôi say sưa? Hãy dẹp rượu của ngươi khỏi ngươi."'),
(7228, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 1, 15, 'OT', 'Hannah đáp và nói: "Thưa không, bệ hạ, tôi là một người phụ nữ có tâm hồn đầy ưu sầu. Tôi chẳng uống rượu hay đồ uống say nào cả, mà đã dâng trọn tâm hồn mình ra trước mặt Đức Giê-hô-va."'),
(7229, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 1, 16, 'OT', 'Đừng coi kẻ tớ gái của ngài là con gái của Bê-li-âm; vì tôi đã nói đến chừng này là bởi sự phiền muộn và đau lòng rất nhiều.'),
(7230, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 1, 17, 'OT', 'Bấy giờ Ê-li đáp và nói: "Cô hãy đi bình an; và Đức Chúa Trời của Y-sơ-ra-ên sẽ ban cho cô điều cô đã xin Ngài."'),
(7231, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 1, 18, 'OT', 'Bà ấy nói: "Nguyện cho tôi tớ của ngài được ơn trước mặt ngài." Rồi người phụ nữ đi theo đường mình, và bà ăn, và nét mặt bà không còn buồn rầu nữa.'),
(7232, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 1, 19, 'OT', 'Sáng hôm sau, họ dậy sớm, thờ lạy trước mặt Đức Giê-hô-va, rồi trở về nhà mình tại Ra-ma. Ên-ca-na biết đến Ha-nanh, vợ mình, và Đức Giê-hô-va nhớ đến nàng.'),
(7233, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 1, 20, 'OT', 'Hết thời gian đã định, thì Ha-nun mang thai và sinh một con trai. Bà đặt tên con trai mình là Sa-mu-ên, vì bà nói: "Tôi đã cầu xin người ấy từ Đức Giê-hô-va."'),
(7234, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 1, 21, 'OT', 'Người đàn ông Ê-li-cát và cả nhà người lên để dâng của lễ cho Đức Giê-hô-va là của lễ hàng năm và của lễ khấn hứa người đã khấn.'),
(7235, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 1, 22, 'OT', 'Nhưng Ha-nun không đi lên, vì bà nói với chồng mình: "Tôi sẽ không đi lên cho đến khi nào đứa trẻ cai sữa; rồi tôi sẽ đem nó đến, để nó ra mắt Đức Giê-hô-va và ở lại đó mãi mãi."'),
(7236, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 1, 23, 'OT', 'Ê-li-ca-na, chồng bà, nói với bà: "Hãy làm điều gì bà thấy tốt trước mặt bà; hãy ở lại cho đến khi cai sữa con, chỉ có Đức Giê-hô-va mới làm nên lời Ngài." Vậy người đàn bà ở lại và cho con bú cho đến khi cai sữa con.'),
(7237, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 1, 24, 'OT', 'Sau khi cai sữa cho cậu bé, người phụ nữ đưa cậu lên cùng mình đến nhà của Đức Giê-hô-va tại Si-lô, với ba con bò đực, một é-pha bột mì và một bầu rượu; và cậu bé vẫn còn rất nhỏ.'),
(7238, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 1, 25, 'OT', 'Họ giết con bò đực, rồi đem đứa trẻ đến gặp Ê-li.'),
(7239, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 1, 26, 'OT', 'Bẩm ông, hỡi đức chúa của tôi, nguyện linh hồn ông sống mãi, hỡi đức chúa của tôi, tôi là người phụ nữ đã đứng bên ông ở đây để cầu nguyện cùng Đức Giê-hô-va.'),
(7240, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 1, 27, 'OT', 'Tôi đã cầu nguyện vì đứa trẻ này, và Đức Giê-hô-va đã nhậm lời tôi, tức là điều tôi đã xin từ nơi Ngài.'),
(7241, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 1, 28, 'OT', 'Vì vậy, tôi cũng đã dâng nó cho Đức Giê-hô-va; suốt mọi ngày nó sống, nó sẽ được dâng cho Đức Giê-hô-va. Rồi người thờ lạy Đức Giê-hô-va tại đó.'),
(7242, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 1, 'OT', 'Ha-na cầu nguyện và nói: Lòng tôi vui vẻ trong Đức Giê-hô-va, sừng tôi được nâng cao trong Đức Giê-hô-va; miệng tôi rộng mở chống lại kẻ thù tôi, vì tôi vui mừng trong sự cứu rỗi của Ngài.'),
(7243, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 2, 'OT', 'Không có ai thánh như Đức Giê-hô-va, vì chẳng ai ngoài Ngài; cũng chẳng có vầng đá nào như Đức Chúa Trời chúng tôi.'),
(7244, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 3, 'OT', 'Đừng nói những lời kiêu ngạo cách quá đáng, đừng để lời tự phụ ra khỏi miệng các ngươi; vì Đức Giê-hô-va là Đức Chúa Trời đầy tri thức, và các hành động được cân đo trước mặt Ngài.'),
(7245, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 4, 'OT', 'Cây cung của những người mạnh mẽ bị gãy, còn những kẻ vấp ngã lại được thắt lưng bằng sức lực.'),
(7246, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 5, 'OT', 'Kẻ no đủ phải bán mình để có bánh ăn; còn kẻ đói thì thôi đói. Người son sẻ sinh được bảy người; còn người có nhiều con cái lại yếu đuối.'),
(7247, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 6, 'OT', 'Đức Giê-hô-va khiến chết và khiến sống; Ngài đưa xuống âm phủ và đưa lên.'),
(7248, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 7, 'OT', 'Đức Giê-hô-va làm cho nghèo và làm cho giàu; Ngài hạ thấp và cũng nâng cao.'),
(7249, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 8, 'OT', 'Người nâng kẻ nghèo khó từ bụi đất, và làm cho người ăn xin từ đống rác được ngồi cùng các quí tộc, để hưởng ngôi vinh hiển; vì các trụ của đất thuộc về Đức Giê-hô-va, và chính Ngài đặt thế gian trên các trụ ấy.'),
(7250, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 9, 'OT', 'Đức Giê-hô-va sẽ giữ gìn bước chân những người thánh của Ngài, còn kẻ ác sẽ bị câm lặng trong bóng tối; vì chẳng phải nhờ sức mạnh mà một người nào có thể chiến thắng.'),
(7251, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 10, 'OT', 'Các kẻ thù của Đức Giê-hô-va sẽ bị đập tan; từ các từng trời Ngài sẽ sấm sét nghịch lại chúng; Đức Giê-hô-va sẽ xét xử các đầu mút đất; và Ngài sẽ ban sức mạnh cho vua mình, cùng nâng cao sừng của Đấng chịu xức dầu mình.'),
(7252, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 11, 'OT', 'Ê-li-cam-na đi về Ra-ma, đến nhà mình. Còn cậu bé thì đang phục vụ Đức Giê-hô-va trước mặt Ê-li, thầy tế lễ.'),
(7253, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 12, 'OT', 'Các con trai của Ê-li là những kẻ vô lại; chúng không biết Đức Giê-hô-va.'),
(7254, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 13, 'OT', 'Phong tục của các thầy tế lễ đối với dân chúng là như sau: mỗi khi một người nào dâng của lễ thiêu, thì cậu bé giúp việc thầy tế lễ đến ngay khi thịt đang được nấu, tay cầm cái chĩa ba răng.'),
(7255, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 14, 'OT', 'Rồi người đánh vào nồi hoặc cái vạc hoặc cái chảo hoặc cái nồi; mọi thứ mà cái xiên đưa lên thì thầy tế lễ lấy cho mình. Họ làm như vậy cho mọi người Y-sơ-ra-ên đến đó tại Si-lô.'),
(7256, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 15, 'OT', 'Ngay trước khi họ đốt mỡ, thì người đầy tớ của thầy tế lễ đến và nói với người dâng tế lễ: "Hãy đưa thịt để nướng cho thầy tế lễ, vì người này sẽ không lấy thịt luộc từ ngươi, chỉ lấy thịt sống mà thôi."'),
(7257, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 16, 'OT', 'Người ấy nói với anh ta: "Hãy để họ đốt mỡ trước đi, rồi hãy lấy phần mà lòng ngươi ước muốn." Nhưng anh ta đáp: "Không, bây giờ ngươi phải đưa cho ta; nếu không, ta sẽ lấy bằng sức mạnh."'),
(7258, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 17, 'OT', 'Vì vậy, tội của các thiếu niên rất lớn trước mặt Đức Giê-hô-va, vì những người đàn ông đó khinh dể của lễ dâng cho Đức Giê-hô-va.'),
(7259, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 18, 'OT', 'Nhưng Sa-mu-ên phục sự trước mặt Đức Giê-hô-va, là một đứa trẻ, thắt e-phót bằng vải gai.'),
(7260, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 19, 'OT', 'Và mẹ cậu làm cho cậu một chiếc áo dài nhỏ, và đem lên cho cậu hằng năm khi bà lên cùng chồng mình để dâng của lễ thường niên.'),
(7261, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 20, 'OT', 'Ê-li chúc phước cho Ên-ka-nah và vợ người, rồi nói: "Nguyện Đức Giê-hô-va ban cho ông con cháu từ người vợ nầy, như điều ông đã xin Đức Giê-hô-va." Rồi họ trở về nhà mình.'),
(7262, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 21, 'OT', 'Đức Giê-hô-va nhớ đến Han-nui, và bà thụ thai, sinh được ba trai và hai gái. Còn cậu bé Sa-mu-ên thì lớn lên bên cạnh Đức Giê-hô-va.'),
(7263, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 22, 'OT', 'Ê-li đã rất già, và ông nghe biết mọi điều mà các con trai ông làm cho toàn thể Y-sơ-ra-ên, và việc chúng nằm cùng các người phụ nữ phục vụ tại cửa Lều Hẹn.'),
(7264, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 23, 'OT', 'Người nói với họ: "Tại sao các ngươi làm những điều này? Vì tôi nghe các lời xấu về các ngươi từ khắp dân chúng này."'),
(7265, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 24, 'OT', 'Đừng vậy, các con ta; vì tiếng đồn ta nghe được không tốt: các con khiến dân của Đức Giê-hô-va phạm tội.'),
(7266, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 25, 'OT', 'Nếu một người phạm tội cùng người khác, thì Đức Chúa Trời sẽ xét xử người ấy; nhưng nếu một người phạm tội cùng Đức Giê-hô-va, thì ai sẽ cầu thay cho người ấy? Và chúng không nghe theo tiếng cha mình, vì Đức Giê-hô-va muốn giết chúng.'),
(7267, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 26, 'OT', 'Còn cậu bé Sa-mu-ên thì lớn lên, càng ngày càng thịnh vượng, vừa đẹp lòng Đức Giê-hô-va, vừa đẹp lòng người ta.'),
(7268, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 27, 'OT', 'Một người của Đức Chúa Trời đến cùng Ê-li, và nói với người rằng: "Đức Giê-hô-va phán như thế này: Ta há chẳng rõ ràng tỏ hiện cho nhà ngươi khi tổ tiên ngươi còn ở trong nhà Pha-ra-ôn tại Ai-cập sao?"'),
(7269, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 28, 'OT', 'Và Ta đã chọn người ấy khỏi mọi chi phái Y-sơ-ra-ên để làm thầy tế lễ cho Ta, để dâng lên bàn thờ Ta, đốt hương, mang áo ê-phót mà hầu trước mặt Ta; và Ta đã ban cho nhà cha ngươi mọi lễ vật thiêu của con cái Y-sơ-ra-ên.'),
(7270, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 29, 'OT', 'Tại sao các ngươi giày đạp lên của lễ thiêu và lễ vật dâng của ta, mà ta đã truyền trong nơi ở ta? Các ngươi làm cho con cái các ngươi được trọng hơn ta, để lấy phần đầu của mọi lễ vật dâng của dân ta mà nuôi mình cho béo tốt?'),
(7271, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 30, 'OT', 'Vì vậy, Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en phán: Ta quả thật đã nói rằng nhà ngươi và nhà tổ phụ ngươi sẽ đi trước mặt Ta mãi mãi; nhưng hiện nay Đức Giê-hô-va phán: Không hề như vậy! Vì ta sẽ tôn kính những kẻ tôn kính ta, và những kẻ khinh bỉ ta sẽ bị coi thường.'),
(7272, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 31, 'OT', 'Nầy, những ngày sẽ đến, ta sẽ chặt tay ngươi và tay nhà tổ phụ ngươi, đến nỗi không có người già trong nhà ngươi.'),
(7273, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 32, 'OT', 'Ngươi sẽ nhìn thấy kẻ thù trong nơi ở của Ta, trong mọi điều tốt lành mà Đức Chúa Trời sẽ ban cho Y-sơ-ra-ên; và sẽ không có người già nào trong nhà ngươi trọn đời.'),
(7274, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 33, 'OT', 'Người nào thuộc về ngươi mà Ta không cắt bỏ khỏi bàn thờ của Ta sẽ làm hao mòn mắt ngươi và làm đau lòng ngươi; và mọi người trai trẻ trong nhà ngươi sẽ chết.'),
(7275, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 34, 'OT', 'Và đây là dấu cho ngươi, điều sẽ xảy đến cho hai con trai ngươi, là Hop-ni và Pi-nê-has: cả hai sẽ chết trong cùng một ngày.'),
(7276, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 35, 'OT', 'Ta sẽ dựng lên cho Ta một thầy tế lễ trung thành, người sẽ làm theo điều Ta nghĩ và Ta mong ước; Ta sẽ xây cho người một nhà vững chắc, và người sẽ luôn đi trước mặt Đấng Ta xức dầu trọn đời.'),
(7277, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 2, 36, 'OT', 'Và sẽ xảy ra rằng, mỗi người còn sót lại trong nhà ngươi sẽ đến quỳ lạy người ấy để xin một miếng bạc và một ổ bánh mì, rồi nói rằng: Tôi xin ông làm ơn, hãy nhận tôi vào một trong các chức vụ thầy tế lễ, để tôi có miếng bánh ăn.'),
(7278, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 3, 1, 'OT', 'Và cậu bé Sa-mu-ên phục vụ Đức Giê-hô-va trước mặt Ê-li. Lời của Đức Giê-hô-va trở nên quý hiếm trong những ngày ấy; không có thị kiến nào được tỏ bày.'),
(7279, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 3, 2, 'OT', 'Và xảy ra vào ngày đó, khi Ê-li đang nằm ở chỗ của mình, thì mắt người đã mờ đi, không thể nhìn thấy được.'),
(7280, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 3, 3, 'OT', 'Và đèn của Đức Chúa Trời chưa tắt, còn Sa-mu-ên thì đang nằm ngủ trong đền thờ của Đức Giê-hô-va, nơi đặt hòm giao ước của Đức Chúa Trời.'),
(7281, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 3, 4, 'OT', 'Đức Giê-hô-va gọi Sa-mu-ên, rồi nói: "Nầy, ta đây."'),
(7282, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 3, 5, 'OT', 'Vậy người chạy đến cùng Ê-li, và nói: "Nầy, tôi đây, vì ông đã gọi tôi." Nhưng người nói: "Ta không gọi đâu; hãy nằm xuống lại." Vậy người đi và nằm xuống.'),
(7283, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 3, 6, 'OT', 'Đức Giê-hô-va lại gọi thêm một lần nữa: "Sa-mu-ên!" Sa-mu-ên liền chỗi dậy, đi đến Ê-li và nói: "Nầy, tôi đây, vì ông đã gọi tôi." Nhưng Ê-li đáp: "Ta không có gọi, hỡi con ta; hãy nằm xuống lần nữa."'),
(7284, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 3, 7, 'OT', 'Sa-mu-ên chưa biết Đức Giê-hô-va, và lời Đức Giê-hô-va chưa được tỏ hiện cho người.'),
(7285, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 3, 8, 'OT', 'Đức Giê-hô-va gọi Sa-mu-ên lần thứ ba; người liền chỗi dậy, đi đến Ê-li và nói: "Này tôi đây, vì thầy đã gọi tôi." Bấy giờ Ê-li mới hiểu rằng chính Đức Giê-hô-va đã gọi đứa trẻ.'),
(7286, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 3, 9, 'OT', 'Vì vậy, Ê-li nói với Sa-mu-ên: "Hãy đi, nằm xuống; và nếu Ngài gọi con, thì con hãy nói: ''Xin hãy phán, Đức Giê-hô-va, vì tôi tớ Ngài đang nghe.''" Rồi Sa-mu-ên đi nằm xuống tại chỗ của mình.'),
(7287, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 3, 10, 'OT', 'Đức Giê-hô-va đến, đứng đó, và gọi như những lần trước: "Sa-mu-ên, Sa-mu-ên." Sa-mu-ên thưa: "Xin hãy phán, vì tôi tớ Ngài đang nghe."'),
(7288, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 3, 11, 'OT', 'Đức Giê-hô-va phán cùng Sa-mu-ên: Nầy, Ta sẽ làm một điều trong Y-sơ-ra-ên, đến nỗi hễ ai nghe được điều đó thì cả hai tai đều sẽ ù lên.'),
(7289, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 3, 12, 'OT', 'Trong ngày đó, Ta sẽ thực hiện đối với Ê-li mọi điều Ta đã phán về nhà nó: khi bắt đầu, Ta cũng sẽ làm trọn.'),
(7290, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 3, 13, 'OT', 'Ta sẽ tỏ cho người biết rằng Ta sẽ đoán xét nhà người đến đời đời, vì tội lỗi mà người biết, bởi các con trai người đã làm mình ra ô uế, mà người không ngăn cản chúng.'),
(7291, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 3, 14, 'OT', 'Vì vậy, Ta đã thề nghịch cùng nhà Ê-li: tội lỗi của nhà Ê-li sẽ không được xóa bỏ bằng của lễ thiêu hay của lễ chay đến mãi mãi.'),
(7292, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 3, 15, 'OT', 'Sa-mu-ên nằm đến sáng, rồi mở các cửa nhà của Đức Giê-hô-va. Nhưng Sa-mu-ên sợ không dám thuật lại cho Ê-li cái thị kiến.'),
(7293, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 3, 16, 'OT', 'Ê-li gọi Sa-mu-ên và nói: "Sa-mu-ên, con ta." Sa-mu-ên đáp: "Dạ, con đây."'),
(7294, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 3, 17, 'OT', 'Ông nói: "Điều gì mà Đức Giê-hô-va đã phán cùng con? Tôi xin con đừng giấu tôi điều gì cả. Đức Chúa Trời sẽ xử con như vậy, và còn xử nặng hơn nữa, nếu con giấu tôi một điều nào trong mọi điều mà Ngài đã phán cùng con."'),
(7295, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 3, 18, 'OT', 'Rồi Sa-mu-ên thuật cho ông mọi điều, chẳng giấu giếm điều gì. Ông nói: "Đức Giê-hô-va là Đấng quyết định; xin Ngài làm điều Ngài cho là tốt."'),
(7296, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 3, 19, 'OT', 'Và Sa-mu-ên lớn lên, và Đức Giê-hô-va ở cùng người, và không để một lời nào của các lời người rơi xuống đất.'),
(7297, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 3, 20, 'OT', 'Và toàn thể Y-sơ-ra-ên, từ Đan cho đến Bê-e-Sê-ba, đều biết rằng Sa-mu-ên được công nhận là một nhà tiên tri trung tín của Đức Giê-hô-va.'),
(7298, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 3, 21, 'OT', 'Đức Giê-hô-va tiếp tục tỏ mình ra tại Si-lô, vì Đức Giê-hô-va đã hiện ra với Sa-mu-ên tại Si-lô bằng lời của Đức Giê-hô-va.'),
(7299, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 4, 1, 'OT', 'Lời của Sa-mu-ên truyền đến khắp cả Ít-ra-en. Ít-ra-en đi ra đánh giặc cùng người Phi-li-tin, và đóng trại bên tảng đá Ê-bên-ê-xe; còn người Phi-li-tin thì đóng trại tại A-phéc.'),
(7300, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 4, 2, 'OT', 'Dân Phi-li-tin dàn trận nghịch cùng dân Y-sơ-ra-ên; hai bên giao chiến, và dân Y-sơ-ra-ên bị đánh bại trước mặt dân Phi-li-tin. Chúng giết trong đạo quân tại nơi chiến trường khoảng bốn ngàn người.'),
(7301, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 4, 3, 'OT', 'Khi dân sự vào trại, các trưởng lão của Y-sơ-ra-ên nói: "Tại sao ngày nay Đức Giê-hô-va đánh bại chúng ta trước mặt người Phi-li-tin? Hãy mang đến cùng chúng ta từ Si-lô hòm giao ước của Đức Giê-hô-va, để khi nó đến giữa chúng ta, nó sẽ cứu chúng ta khỏi tay kẻ thù của chúng ta."'),
(7302, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 4, 4, 'OT', 'Dân chúng sai người đến Si-lô, đem từ đó hòm giao ước của Đức Giê-hô-va Toàn Năng, là Đấng ngự trên các cụp, và hai con trai của Ê-li, là Hô-phi-ni và Phi-nê-xết, ở đó cùng với hòm giao ước của Đức Chúa Trời.'),
(7303, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 4, 5, 'OT', 'Khi hòm giao ước của Đức Giê-hô-va vào trại, toàn thể Y-sơ-ra-ên reo hò một tiếng kêu lớn, và đất rung chuyển.'),
(7304, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 4, 6, 'OT', 'Người Phi-li-tin nghe tiếng reo hò ấy, bèn nói: "Tiếng reo hò lớn dữ dội này trong trại người Hê-bơ-rơ có ý nghĩa gì?" Rồi họ biết được rằng rương của Đức Giê-hô-va đã đến trong trại.'),
(7305, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 4, 7, 'OT', 'Người Phi-li-tin sợ hãi, vì họ nói: "Đức Chúa Trời đã vào trại quân rồi." Họ nói: "Khốn cho chúng ta! Vì chưa từng có điều gì như thế này từ ngày hôm qua và ngày kia."'),
(7306, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 4, 8, 'OT', 'Ôi chúng ta khốn đốn rồi! Ai sẽ cứu chúng ta khỏi tay các thần quyền năng này? Chính các thần nầy đã dùng mọi tai họa mà đánh dân Ai-cập trong đồng vắng.'),
(7307, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 4, 9, 'OT', 'Hãy can đảm lên và tỏ ra mình là người đàn ông, hỡi người Phi-li-tin, hầu các ngươi khỏi phải làm tôi cho người Hê-bơ-rơ như chúng đã làm tôi cho các ngươi; hãy can đảm lên và chiến đấu.'),
(7308, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 4, 10, 'OT', 'Dân Phi-li-tin giao chiến, và Ít-ra-en bị đánh bại; họ chạy trốn, mỗi người về lều mình. Cuộc thảm sát rất lớn, và ba mươi ngàn lính bộ của Ít-ra-en ngã gục.'),
(7309, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 4, 11, 'OT', 'Hòm giao ước của Đức Chúa Trời bị cất đi, và hai con trai của Ê-li, là Hô-phi-ni và Phi-nê-ha, đều chết.'),
(7310, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 4, 12, 'OT', 'Một người của chi phái Bên-gia-min chạy từ nơi chiến trận, đến Si-lô vào chính ngày ấy, quần áo xé rách và đất phủ trên đầu.'),
(7311, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 4, 13, 'OT', 'Kìa người ấy đến, và thấy Éc-li đang ngồi trên chiếc ghế bên vệ đường, ngóng trông, vì lòng người ấy lo sợ về hòm bia Đức Chúa Trời. Người ấy liền vào thành báo tin, và cả thành phố kêu lên thất thanh.'),
(7312, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 4, 14, 'OT', 'Khi Ê-li nghe tiếng kêu la, ông nói: "Tiếng ồn ào dữ dội này nghĩa là gì?" Người đàn ông đó vội vàng chạy đến báo cho Ê-li biết.'),
(7313, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 4, 15, 'OT', 'Ê-li được chín mươi tám tuổi, mắt ông mờ đục, không còn thấy được nữa.'),
(7314, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 4, 16, 'OT', 'Người ấy nói với Ê-li: "Tôi là người từ trận địa đến, hôm nay tôi đã chạy trốn khỏi trận địa." Người ấy nói: "Chuyện gì đã xảy ra, con ơi?"'),
(7315, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 4, 17, 'OT', 'Người báo tin trả lời và nói: "Ít-ra-en đã chạy trốn trước mặt người Phi-li-tin, và cũng có một cơn thảm sát lớn trong dân chúng; hơn nữa, hai con trai ngươi là Hop-ni và Phi-nê-xa đều đã chết, và hòm giao ước Đức Chúa Trời đã bị đem đi."'),
(7316, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 4, 18, 'OT', 'Khi người ta nhắc đến hòm của Đức Chúa Trời, ông ngã ngửa khỏi cái ghế xuống bên cạnh cổng thành, cổ ông gãy ra và ông chết, vì ông là một người già và mập. Ông đã xét xử cho Ít-ra-en bốn mươi năm.'),
(7317, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 4, 19, 'OT', 'Vợ của Phinehas, con dâu bà, đang mang thai và gần đến kỳ sinh nở; khi nghe tin hòm của Đức Chúa Trời bị đem đi, và cha chồng cùng chồng bà đã qua đời, thì bà cúi mình xuống và chuyển dạ sinh con, vì cơn đau chuyển đến bà.'),
(7318, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 4, 20, 'OT', 'Đến lúc nàng chết, các người phụ nữ đứng bên cạnh an ủi nàng rằng: "Đừng sợ, vì chị đã sinh được một con trai." Nhưng nàng không trả lời, cũng chẳng để tâm đến lời họ.'),
(7319, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 4, 21, 'OT', 'Bà đặt tên đứa trẻ là Ích-ca-bốt, nói rằng: Vinh hiển đã rời khỏi Ít-ra-en; vì hòm của Đức Chúa Trời bị đem đi, và vì cha chồng bà và chồng bà đã qua đời.'),
(7320, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 4, 22, 'OT', 'Bà ấy nói: Vinh hiển đã lìa khỏi Ít-ra-en, vì hòm của Đức Chúa Trời đã bị cất đi.'),
(7321, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 5, 1, 'OT', 'Người Phi-li-tin lấy hòm của Đức Chúa Trời và đem từ Ê-bên-Ê-xe đến Ách-đốt.'),
(7322, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 5, 2, 'OT', 'Người Phi-li-tin lấy hòm giao ước của Đức Chúa Trời, đem vào nhà Đa-gôn và đặt nó gần Đa-gôn.'),
(7323, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 5, 3, 'OT', 'Sáng hôm sau, những người Asdốt chỗi dậy sớm, thì thấy tượng Đa-gôn đã ngã sấp mặt xuống đất trước hòm giao ước của Đức Giê-hô-va. Họ bèn khiêng tượng Đa-gôn lên và đặt lại vào chỗ cũ của nó.'),
(7324, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 5, 4, 'OT', 'Sáng hôm sau, khi họ chỗi dậy sớm, thì kìa, tượng Đa-gôn đã ngã sấp mặt xuống đất trước hòm giao ước của Đức Giê-hô-va; đầu của Đa-gôn và cả hai lòng bàn tay của nó bị cắt đứt trên ngưỡng cửa, chỉ còn phần thân của Đa-gôn còn lại trên đó.'),
(7325, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 5, 5, 'OT', 'Bởi vậy, các thầy tế lễ của Đa-gôn và mọi người vào nhà Đa-gôn tại Ách-đốt không bước trên ngưỡng cửa của Đa-gôn cho đến ngày nay.'),
(7326, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 5, 6, 'OT', 'Đức Giê-hô-va giáng tay nặng nề trên dân A-sốt, khiến chúng hoang vu, và đánh chúng bằng các khối nhọt, cả A-sốt lẫn vùng lân cận nó.'),
(7327, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 5, 7, 'OT', 'Các người A-sốt thấy vậy thì nói: Hòm của Đức Chúa Trời của Y-sơ-ra-ên không thể ở cùng chúng ta được, vì tay Ngài đã giáng họa nặng nề trên chúng ta và trên Đa-gôn, thần của chúng ta.'),
(7328, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 5, 8, 'OT', 'Họ sai người đi và triệu tập tất cả các quan trưởng của dân Phi-li-tin đến cùng mình, rồi nói: "Chúng ta phải làm gì về hòm của Đức Chúa Trời của Ít-ra-en?" Họ đáp: "Hãy chuyển hòm của Đức Chúa Trời của Ít-ra-en đến Gat." Vậy họ chuyển hòm của Đức Chúa Trời của Ít-ra-en đến đó.'),
(7329, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 5, 9, 'OT', 'Sau khi chúng đem nó đi khắp nơi, tay của Đức Giê-hô-va chống lại thành ấy bằng một sự hỗn loạn lớn vô cùng; Ngài đánh các người trong thành, từ nhỏ đến lớn, và chúng bị nổi nhọt sinh dục.'),
(7330, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 5, 10, 'OT', 'Họ bèn gửi hòm của Đức Chúa Trời đến Éc-rôn. Khi hòm của Đức Chúa Trời đến Éc-rôn, thì dân Éc-rôn kêu lên rằng: "Họ mang hòm của Đức Chúa Trời của Ít-ra-en đến đây để giết tôi và dân tôi!"'),
(7331, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 5, 11, 'OT', 'Họ sai người đi triệu tập tất cả các quan tổng của người Phi-li-tin, rồi nói: "Hãy để cho rương của Đức Chúa Trời của Ít-ra-en đi, và để nó trở về nơi nó, đừng để nó giết chúng ta và dân chúng ta", vì sự chết khủng khiếp đã xảy ra khắp thành phố; tay Đức Chúa Trời ở đó thật nặng nề.'),
(7332, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 5, 12, 'OT', 'Còn những người đàn ông không chết thì bị đánh bằng các khối u trĩ; và tiếng kêu của thành phố vang lên đến trời.'),
(7333, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 6, 1, 'OT', 'Hòm giao ước của Đức Giê-hô-va ở trong đất nước của người Phi-li-tin bảy tháng.'),
(7334, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 6, 2, 'OT', 'Dân Phi-li-tin gọi các thầy tế lễ và các thầy bói, nói rằng: Chúng ta phải làm gì về hòm giao ước của Đức Giê-hô-va? Hãy chỉ cho chúng tôi biết phải gửi nó về nơi nó bằng cách nào.'),
(7335, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 6, 3, 'OT', 'Họ nói: "Nếu các ngươi sai đi hòm báu của Đức Chúa Trời của Ít-ra-en, thì đừng sai đi mà không có gì; phải chắc chắn hoàn trả cho Ngài một của lễ đền tội; bấy giờ các ngươi sẽ được lành, và sẽ biết tại sao tay Ngài không rời khỏi các ngươi."'),
(7336, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 6, 4, 'OT', 'Họ nói: "Chúng tôi phải dâng lễ đền tội gì để trả lại cho Ngài?" Họ trả lời: "Theo số lượng các lãnh chúa của người Phi-li-tin, năm khối u bằng vàng và năm chuột bằng vàng, vì một tai họa đã giáng trên tất cả các ngươi và các lãnh chúa của các ngươi."'),
(7337, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 6, 5, 'OT', 'Hãy làm những hình tượng của các khối u nhọt và những hình tượng của các con chuột phá hại đất, và hãy dâng cho Đức Chúa Trời của Y-sơ-ra-ên; có lẽ Ngài sẽ nhẹ tay khỏi các ngươi, khỏi các thần của các ngươi, và khỏi đất các ngươi.'),
(7338, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 6, 6, 'OT', 'Tại sao các ngươi lại làm cho lòng các ngươi trở nên cứng cỏi, như người Ai Cập và Pha-ra-ôn đã làm cho lòng họ trở nên cứng cỏi? Khi Ngài đã hành động cách lạ lùng giữa họ, chẳng phải họ đã để cho dân sự đi và họ đã ra đi sao?'),
(7339, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 6, 7, 'OT', 'Bây giờ, hãy đi và làm một cái xe mới, lấy hai con bò cái đang cho con bú, chưa từng mang ách, rồi buộc những con bò ấy vào xe, và đem các con bê của chúng trở về nhà, không để theo sau chúng.'),
(7340, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 6, 8, 'OT', 'Hãy đem rương của Đức Giê-hô-va, đặt nó trên xe, rồi đặt những đồ bằng vàng mà các ngươi trả Người như tiền đền tội vào một cái hòm bên cạnh nó; và hãy cho nó đi, để nó đi đi.'),
(7341, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 6, 9, 'OT', 'Hãy xem, nếu nó đi lên theo con đường vùng đất quê hương nó đến Bết-sê-mết, thì chính nó đã làm cho chúng ta điều ác lớn này; còn nếu không, thì chúng ta sẽ biết rằng tay Ngài đã không đụng đến chúng ta; ấy chỉ là một sự tình cờ xảy đến cho chúng ta.'),
(7342, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 6, 10, 'OT', 'Dân chúng làm đúng như vậy; họ bắt hai con bò cái đang cho con bú, cột chúng vào xe, rồi nhốt các con bê của chúng trong chuồng.'),
(7343, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 6, 11, 'OT', 'Họ đặt rương của Đức Giê-hô-va lên xe, và cái hòm cùng với những con chuột bằng vàng và các tượng hình những khối u nhọt của chúng.'),
(7344, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 6, 12, 'OT', 'Bầy bò rống đi theo con đường thẳng về hướng Beth-sê-mết, đi dọc theo con đường cái, không rẽ sang phải hay trái; các quan trưởng người Phi-li-tin đi theo chúng cho đến ranh giới Beth-sê-mết.'),
(7345, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 6, 13, 'OT', 'Người ở Bết-sê-mết đang gặt lúa mì mùa gặt của họ trong thung lũng; họ ngước mắt lên, thấy hòm giao ước, và vui mừng khi thấy nó.'),
(7346, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 6, 14, 'OT', 'Chiếc xe đi vào đồng ruộng của Giô-suê, người Bết-sê-mết, rồi đứng lại tại đó, và tại đó có một hòn đá lớn; họ bèn chặt gỗ của chiếc xe, và dâng những con bò cái làm của lễ thiêu cho Đức Giê-hô-va.'),
(7347, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 6, 15, 'OT', 'Các thầy Lê-vi hạ hòm giao ước của Đức Giê-hô-va và cái rương đi kèm theo, trong đó có các vật dụng bằng vàng, rồi đặt chúng trên tảng đá lớn; còn những người ở Bết-sê-mết thì dâng những của lễ thiêu và tế những của lễ sinh tế trong ngày ấy cho Đức Giê-hô-va.'),
(7348, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 6, 16, 'OT', 'Năm viên quan trưởng của người Phi-li-tin đã thấy điều đó, rồi cùng nhau trở về Éc-rôn trong ngày ấy.'),
(7349, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 6, 17, 'OT', 'Còn đây là những khối vàng mà người Phi-li-tin dâng trả cho Đức Giê-hô-va để đền tội: một cái cho A-sốt, một cái cho Ga-xa, một cái cho Ách-ke-lôn, một cái cho Gát, một cái cho Ê-cơ-rôn.'),
(7350, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 6, 18, 'OT', 'Các con chuột bằng vàng, theo số lượng các thành của người Phi-li-tin, thuộc về năm lãnh chúa, từ thành có vách thành đến các làng đồng bằng, cho đến Abel lớn, nơi họ đặt hòm giao ước của Đức Giê-hô-va; cho đến ngày nay, trong đồng ruộng của Giô-suê người Bết-sê-mết.'),
(7351, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 6, 19, 'OT', 'Đức Giê-hô-va đánh những người ở Bết-sê-mết, vì họ đã nhìn vào hòm giao ước của Đức Giê-hô-va; và Đức Giê-hô-va đánh dân sự, bảy mươi người và năm mươi ngàn người; dân sự than khóc, vì Đức Giê-hô-va đã giáng trên dân sự một tai họa lớn.'),
(7352, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 6, 20, 'OT', 'Các người ở Bết-sê-mết nói: "Ai có thể đứng trước mặt Đức Giê-hô-va, Đức Chúa Trời thánh này? Và ai sẽ tiếp nhận Ngài từ chúng tôi?"'),
(7353, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 6, 21, 'OT', 'Họ sai các sứ giả đến những người ở Kiryath-ye''arim, nói rằng: Người Phi-li-tin đã trả lại rương của Đức Giê-hô-va; hãy xuống, mang nó lên cùng các ngươi.'),
(7354, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 7, 1, 'OT', 'Các người của Kiriat-yearim đến, rước hòm bia của Đức Giê-hô-va lên, đem vào nhà Abinadap ở trên đồi, và biệt riêng Elêazar, con trai ông, để giữ hòm bia của Đức Giê-hô-va.'),
(7355, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 7, 2, 'OT', 'Và xảy ra từ ngày hòm bệ đặt tại Ki-ri-át Jearim, thì những ngày kéo dài, và đã được hai mươi năm; cả nhà Y-sơ-ra-ên đều khao khát Đức Giê-hô-va.'),
(7356, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 7, 3, 'OT', 'Sa-mu-ên nói với cả nhà Y-sơ-ra-ên rằng: "Nếu các ngươi thật lòng trở lại cùng Đức Giê-hô-va, hãy dẹp các thần ngoại bang và các hình tượng Ách-ta-rốt khỏi giữa các ngươi, và chuẩn bị lòng các ngươi hướng về Đức Giê-hô-va, chỉ phục vụ một mình Ngài, thì Ngài sẽ giải cứu các ngươi khỏi tay người Phi-li-tin."'),
(7357, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 7, 4, 'OT', 'Dân Y-sơ-ra-ên bèn loại bỏ các hình tượng Ba-anh và Ách-ta-thốt, và chỉ thờ phượng Đức Giê-hô-va.'),
(7358, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 7, 5, 'OT', 'Rồi Sa-mu-ên nói: "Hãy nhóm toàn thể dân Y-sơ-ra-ên lại tại Mít-pha, tôi sẽ cầu nguyện cùng Đức Giê-hô-va nhân danh các ngươi."'),
(7359, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 7, 6, 'OT', 'Họ nhóm lại tại Mít-pha, múc nước ra và đổ ra trước mặt Đức Giê-hô-va, nhịn ăn trong ngày ấy, và nói tại đó: "Chúng tôi đã phạm tội cùng Đức Giê-hô-va." Sau đó, Sa-mu-ên xét xử các con cái Ít-ra-en tại Mít-pha.'),
(7360, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 7, 7, 'OT', 'Khi người Phi-li-tin nghe biết rằng các con trai Ít-ra-en đã tụ họp tại Mít-pa, các lãnh chúa Phi-li-tin liền kéo lên nghịch cùng Ít-ra-en. Khi các con trai Ít-ra-en nghe điều đó, họ sợ hãi trước mặt người Phi-li-tin.'),
(7361, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 7, 8, 'OT', 'Các con trai của Y-sơ-ra-ên nói với Sa-mu-ên: Đừng nín lặng mà không kêu lên cùng Đức Giê-hô-va Đức Chúa Trời chúng tôi, để Ngài cứu chúng tôi khỏi tay người Phi-li-tin.'),
(7362, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 7, 9, 'OT', 'Sa-mu-ên lấy một con chiên con đang bú mớm, dâng làm lễ thiêu toàn phần cho Đức Giê-hô-va; rồi Sa-mu-ên kêu cầu Đức Giê-hô-va vì Ít-ra-en, và Đức Giê-hô-va nhậm lời người.'),
(7363, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 7, 10, 'OT', 'Khi Sa-mu-ên dâng của lễ thiêu lên, thì người Phi-li-tin đến gần để giao chiến với Y-sơ-ra-ên; nhưng Đức Giê-hô-va khiến sấm sét lớn vang dội trên người Phi-li-tin trong ngày đó, làm họ hoảng loạn, và họ bị đánh bại trước mặt Y-sơ-ra-ên.'),
(7364, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 7, 11, 'OT', 'Các người của Y-sơ-ra-ên đi ra từ Mít-phe, rượt đuổi người Phi-li-tin và đánh bại chúng cho đến nơi thấp hơn Bết-ca.'),
(7365, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 7, 12, 'OT', 'Rồi Sa-mu-ên lấy một hòn đá, đặt giữa Mít-bê và Sên, và đặt tên nó là Ê-bên-ê-xe, nói rằng: "Đến nơi này, Đức Giê-hô-va đã giúp chúng ta."'),
(7366, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 7, 13, 'OT', 'Người Phi-li-tin bị khuất phục và không còn dám vào trong vùng biên giới của Y-sơ-ra-ên nữa; và tay của Đức Giê-hô-va chống lại người Phi-li-tin trọn mọi ngày đời của Sa-mu-ên.'),
(7367, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 7, 14, 'OT', 'Các thành mà người Phi-li-tin đã chiếm từ Y-sơ-ra-ên được trả lại cho Y-sơ-ra-ên, từ Ê-cơ-rôn cho đến Ga-th; và phần đất đai của chúng, Y-sơ-ra-ên đã giải thoát khỏi tay người Phi-li-tin. Và có sự hòa bình giữa Y-sơ-ra-ên và người A-mô-rít.'),
(7368, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 7, 15, 'OT', 'Sa-mu-ên xét xử cho Ít-ra-en trọn mọi ngày trong đời sống của ông.'),
(7369, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 7, 16, 'OT', 'Hằng năm, ông tuần tự đi vòng quanh Bê-thên, Ghinh-ganh, và Mít-pa, và xét xử dân Y-sơ-ra-ên tại tất cả những nơi ấy.'),
(7370, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 7, 17, 'OT', 'Và nơi ông trở về là Ra-ma, vì ở đó là nhà ông; và ở đó ông xét xử Y-sơ-ra-ên; và ở đó ông xây một bàn thờ cho Đức Giê-hô-va.'),
(7371, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 8, 1, 'OT', 'Và xảy ra rằng, khi Sa-mu-ên đã về già, thì người đặt các con trai mình làm quan xét cho Y-sơ-ra-ên.'),
(7372, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 8, 2, 'OT', 'Tên đứa con trai đầu lòng của ông là Giô-ên, và tên đứa thứ hai là A-bi-gia; hai người làm quan xét ở Bê-er-Sê-ba.'),
(7373, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 8, 3, 'OT', 'Nhưng các con trai của ông không đi theo con đường của ông, mà quay sang theo lợi lộc, nhận của hối lộ và làm sai lệch công lý.'),
(7374, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 8, 4, 'OT', 'Bấy giờ, tất cả các trưởng lão của Y-sơ-ra-ên đều nhóm lại và đến cùng Sa-mu-ên tại Ra-ma.'),
(7375, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 8, 5, 'OT', 'Họ nói với ông: "Nầy, ông đã già rồi, và các con trai ông không đi theo đường lối của ông. Bây giờ, xin đặt một vị vua cai trị chúng tôi như mọi dân tộc khác."'),
(7376, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 8, 6, 'OT', 'Nhưng điều đó làm Sa-mu-ên bất bình khi họ nói: "Hãy ban cho chúng tôi một vị vua để cai trị chúng tôi." Rồi Sa-mu-ên cầu nguyện cùng Đức Giê-hô-va.'),
(7377, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 8, 7, 'OT', 'Đức Giê-hô-va phán cùng Sa-mu-ên: "Hãy nghe theo tiếng dân về mọi điều họ nói cùng ngươi; vì họ không từ bỏ ngươi, nhưng đã từ bỏ Ta không cho Ta trị vì trên họ."'),
(7378, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 8, 8, 'OT', 'Cũng như mọi việc chúng đã làm từ ngày Ta dẫn chúng ra khỏi Ai Cập cho đến ngày nay, khi chúng từ bỏ Ta và thờ các thần khác, thì chúng cũng sẽ làm như vậy đối với ngươi.'),
(7379, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 8, 9, 'OT', 'Vậy hãy nghe theo tiếng nói của họ; nhưng phải nghiêm khắc cảnh cáo họ và cho họ biết về cách thức của vị vua sẽ cai trị trên họ.'),
(7380, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 8, 10, 'OT', 'Sa-mu-ên nói với toàn thể dân chúng những lời của Đức Giê-hô-va, là những người đã xin người một vị vua.'),
(7381, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 8, 11, 'OT', 'Ông ấy nói: "Đây sẽ là cách thức của vị vua, người sẽ trị vì trên các ngươi: ông ấy sẽ lấy các con trai các ngươi, và đặt các con trai ấy cho mình, để phục vụ các xe chiến của ông ấy và các kỵ binh của ông ấy; và một số sẽ chạy trước các xe chiến của ông ấy."'),
(7382, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 8, 12, 'OT', 'và đặt người chỉ huy các ngàn và các năm mươi; và cày ruộng của người, gặt mùa màng của người, làm khí giới cho chiến tranh của người và khí giới cho xe chiến của người.'),
(7383, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 8, 13, 'OT', 'Và các con gái các ngươi, người sẽ bắt lấy để làm thợ xức dầu, và làm thợ nấu ăn, và làm thợ nướng bánh.'),
(7384, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 8, 14, 'OT', 'Ngài sẽ lấy các ruộng đất các ngươi, các vườn nho các ngươi, và các vườn ô-liu tốt nhất của các ngươi, rồi ban cho các đầy tớ Ngài.'),
(7385, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 8, 15, 'OT', 'Và các ngươi sẽ phải nộp hạt giống và vườn nho của mình, rồi ông ta sẽ trao cho các hoạn quan và đầy tớ của mình.'),
(7386, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 8, 16, 'OT', 'Và người sẽ lấy các đầy tớ trai, các tớ gái, những thanh niên tốt nhất và các lừa của các ngươi, rồi bắt làm việc cho mình.'),
(7387, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 8, 17, 'OT', 'Đức Giê-hô-va sẽ lấy phần mười của bầy chiên các ngươi, và các ngươi sẽ trở thành tôi tớ cho người ấy.'),
(7388, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 8, 18, 'OT', 'Và các ngươi sẽ kêu khóc trong ngày ấy vì vua mà các ngươi đã chọn cho mình; nhưng Đức Giê-hô-va sẽ không nhậm lời các ngươi trong ngày ấy.'),
(7389, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 8, 19, 'OT', 'Dân sự từ chối nghe theo tiếng của Sa-mu-ên, và họ nói: "Không! Nhưng phải có một vị vua cai trị trên chúng tôi."'),
(7390, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 8, 20, 'OT', 'Chúng tôi cũng sẽ giống như mọi dân tộc trên đất; và vua chúng tôi sẽ xét xử chúng tôi, đi trước chúng tôi, và chiến đấu các trận chiến của chúng tôi.'),
(7391, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 8, 21, 'OT', 'Rồi Sa-mu-ên nghe tất cả các lời của dân chúng, và trình các lời ấy vào tai Đức Giê-hô-va.'),
(7392, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 8, 22, 'OT', 'Đức Giê-hô-va phán cùng Sa-mu-ên: "Hãy nghe theo tiếng của họ và lập một vị vua cho họ." Rồi Sa-mu-ên nói với những người Ít-ra-en: "Hãy về mỗi người mỗi thành của mình."'),
(7393, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 9, 1, 'OT', 'Có một người thuộc chi phái Bên-gia-min, tên là Kích, con trai của A-bi-ên, con trai của Xê-rô, con trai của Bê-cho-rát, con trai của A-phai, con trai của một người Bên-gia-min, là một người tráng kiện.'),
(7394, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 9, 2, 'OT', 'Và người có một người con trai, tên là Sau-lơ, một thanh niên khôi ngô tuấn tú; không có ai trong các con trai Y-sơ-ra-ên đẹp đẽ hơn chàng; từ vai trở lên thì cao hơn tất cả dân chúng.'),
(7395, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 9, 3, 'OT', 'Các lừa của Kích, cha của Sau-lơ, bị thất lạc. Kích nói với Sau-lơ, con trai mình: "Hãy đem theo một trong các đầy tớ và đứng dậy đi tìm các con lừa."'),
(7396, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 9, 4, 'OT', 'Người ấy đi qua núi Ép-ra-im, rồi đi qua đất nước Sa-li-sa, nhưng không tìm được; sau đó đi qua đất nước Sa-lim, nhưng cũng không thấy; rồi đi qua đất Giê-mi-ni, nhưng vẫn không tìm được.'),
(7397, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 9, 5, 'OT', 'Họ đi đến miền Xô-phơ, Sa-un nói với người đầy tớ đi cùng mình: "Nào, chúng ta hãy trở về, kẻo cha ta lo cho chúng ta, không còn quan tâm đến những con lừa nữa."'),
(7398, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 9, 6, 'OT', 'Người ấy nói với ông: "Nầy, trong thành nầy có một người của Đức Chúa Trời, một người rất được kính trọng; mọi điều ông ấy nói đều ứng nghiệm. Bây giờ chúng ta hãy đi đến đó, may ra ông ấy sẽ chỉ cho chúng ta con đường mà chúng ta đang đi."'),
(7399, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 9, 7, 'OT', 'Sa-un nói với đầy tớ mình: "Này, nếu chúng ta đi, thì đem gì đến cho người đó? Vì bánh trong các bị của chúng ta đã hết, và cũng không có lễ vật nào để dâng cho người của Đức Chúa Trời; chúng ta còn gì nữa đây?"'),
(7400, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 9, 8, 'OT', 'Người đầy tớ trả lời Xao lần nữa và nói: Này, tôi có sẵn trong tay một phần tư si-quel bạc; tôi sẽ đưa cho người của Đức Chúa Trời để ông chỉ cho chúng ta con đường.'),
(7401, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 9, 9, 'OT', 'Trước kia tại Y-sơ-ra-ên, khi một người đi cầu hỏi Đức Chúa Trời, người ta thường nói: "Nào, chúng ta hãy đi đến đấng tiên kiến," vì đấng tiên tri ngày nay trước kia được gọi là đấng tiên kiến.'),
(7402, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 9, 10, 'OT', 'Sa-un nói với người đầy tớ: "Lời ngươi nói tốt lắm; nào, chúng ta hãy đi." Vậy hai người đi đến thành phố nơi có người của Đức Chúa Trời.'),
(7403, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 9, 11, 'OT', 'Khi họ lên đồi vào thành phố, họ gặp các thiếu nữ đang ra đi múc nước, bèn nói với các cô ấy: Đấng tiên kiến có ở đây không?'),
(7404, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 9, 12, 'OT', 'Chúng trả lời và nói: Có, này, người ấy đang ở trước mặt các ông; hãy nhanh lên, vì hôm nay người ấy đã đến thành phố; vì hôm nay dân chúng có lễ tế tại nơi cao.'),
(7405, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 9, 13, 'OT', 'Khi các ngươi vào thành, lập tức sẽ gặp người ấy, trước khi người ấy lên nơi cao để ăn; vì dân chúng sẽ không ăn cho đến khi người ấy đến, vì người ấy sẽ chúc phước cho của lễ; sau đó những người được mời mới ăn. Bây giờ hãy lên đường đi, vì vào khoảng giờ này các ngươi sẽ gặp được người ấy.'),
(7406, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 9, 14, 'OT', 'Họ lên thành phố; khi vừa vào trong thành, thì nầy, Sa-mu-ên đang đi ra đón họ, để lên nơi cao.'),
(7407, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 9, 15, 'OT', 'Đức Giê-hô-va đã làm lộ tai của Sa-mu-ên một ngày trước khi Sau-lơ đến, mà phán rằng:'),
(7408, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 9, 16, 'OT', 'Ngày mai vào giờ này, Ta sẽ sai một người từ đất Bên-gia-min đến cùng ngươi; ngươi sẽ xức dầu cho người ấy làm lãnh tụ trên dân Ta, là Y-sơ-ra-ên, để người ấy cứu dân Ta khỏi tay dân Phi-li-tin; vì Ta đã nhìn xem dân Ta, bởi tiếng kêu cứu của họ đã thấu đến Ta.'),
(7409, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 9, 17, 'OT', 'Khi Sa-mu-ên thấy Sa-un, Đức Giê-hô-va phán với người rằng: Này là người mà Ta đã nói với ngươi; chính người nầy sẽ cai trị dân Ta.'),
(7410, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 9, 18, 'OT', 'Sa-un đến gần Sa-mu-ên tại giữa cổng thành, và nói: Xin ông vui lòng cho tôi biết nhà của người thấy ở đâu?'),
(7411, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 9, 19, 'OT', 'Sa-mu-ên đáp lời Sa-un rằng: "Tôi là người thấy đó. Hãy đi lên trước tôi đến nơi cao, vì hôm nay các ngươi sẽ ăn với tôi. Sáng mai tôi sẽ cho ngươi đi, và sẽ nói cho ngươi biết mọi điều trong lòng ngươi."'),
(7412, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 9, 20, 'OT', 'Ba con lừa của ngươi mà ngươi đã mất cách đây ba ngày, chớ lo lắng về chúng; chúng đã được tìm thấy rồi. Và ai là người mà cả Y-sơ-ra-ên đều mong ước? Chẳng phải là ngươi và cả nhà cha ngươi sao?'),
(7413, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 9, 21, 'OT', 'Sa-un đáp và nói: Tôi há chẳng phải là người thuộc chi phái Bên-gia-min, nhỏ bé nhất trong các chi phái của Y-sơ-ra-ên? Gia đình tôi há chẳng phải là dòng họ nhỏ nhất trong mọi dòng họ của chi phái Bên-gia-min? Vậy tại sao ông lại nói với tôi điều này?'),
(7414, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 9, 22, 'OT', 'Rồi Sa-mu-ên dẫn Sau-lơ và đầy tớ người vào buồng trên, đặt chỗ cho hai người ở đầu chỗ ngồi của những người được mời, khoảng ba mươi người.'),
(7415, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 9, 23, 'OT', 'Rồi Sa-mu-ên nói với người đầu bếp: "Hãy mang phần thịt mà ta đã giao cho ngươi, phần mà ta bảo ngươi để riêng ra."'),
(7416, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 9, 24, 'OT', 'Người đầu bếp nâng cái đùi cùng phần thịt trên đó, đặt trước mặt Sau-lơ. Sau-mu-ên nói: "Này, phần còn lại, hãy đặt trước mặt ngươi và ăn; vì phần này đã được giữ riêng cho ngươi từ khi ta nói: Ta đã mời dân chúng." Vậy Sau-lơ ăn cùng Sau-mu-ên trong ngày ấy.'),
(7417, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 9, 25, 'OT', 'Họ đi xuống từ nơi cao sang thành phố, rồi người ấy nói chuyện với Sa-un trên nóc nhà.'),
(7418, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 9, 26, 'OT', 'Họ dậy sớm; khi hừng đông vừa bừng sáng, Sa-mu-ên gọi Sau-lơ ở trên mái nhà, nói: "Hãy chỗi dậy, để tôi tiễn anh đi." Sau-lơ liền chỗi dậy, và cả hai cùng đi ra ngoài, tức là ông và Sa-mu-ên.'),
(7419, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 9, 27, 'OT', 'Họ đi xuống đến cuối thành, thì Sa-mu-ên nói với Sa-un: "Hãy bảo người đầy tớ đi trước chúng ta"; người ấy liền đi trước; còn ông thì hãy đứng lại đây một lát, để tôi nói cho ông biết lời của Đức Chúa Trời.'),
(7420, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 10, 1, 'OT', 'Rồi Sa-mu-ên lấy bình dầu và đổ trên đầu người ấy, và hôn người ấy, rồi nói: "Chẳng phải Đức Giê-hô-va đã xức dầu cho ngươi làm lãnh tụ cai trị cơ nghiệp của Ngài sao?"'),
(7421, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 10, 2, 'OT', 'Khi ngươi rời khỏi ta hôm nay, ngươi sẽ gặp hai người đàn ông gần ngôi mộ của Ra-chên, ở vùng biên giới Bên-gia-min, tại Xên-xa; và họ sẽ nói với ngươi rằng: "Những con lừa mà ngươi đã đi tìm đã được tìm thấy rồi." Và nầy, cha ngươi đã thôi lo về những con lừa và đang buồn vì ngươi, nói rằng: "Ta sẽ làm gì cho con ta đây?"'),
(7422, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 10, 3, 'OT', 'Ngươi sẽ đi tiếp từ nơi đó đến cây sồi Tabor, và ở đó ngươi sẽ gặp ba người đàn ông đang lên đường đến nơi thánh ở Bê-tên; một người mang ba con dê con, một người mang ba ổ bánh mì, và một người mang một bầu rượu vang.'),
(7423, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 10, 4, 'OT', 'Họ sẽ chào ngươi bình an và đưa cho ngươi hai ổ bánh; ngươi hãy nhận lấy từ tay họ.'),
(7424, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 10, 5, 'OT', 'Sau đó, ngươi sẽ đến nơi đồi của Đức Chúa Trời, nơi có toán quân đóng giữ của người Phi-li-tin; và khi ngươi vừa đến thành ấy, thì ngươi sẽ gặp một nhóm các nhà tiên tri đang đi xuống từ nơi cao, phía trước họ có đàn nguyệt, trống nhỏ, sáo và đờn cầm, và họ đang nói tiên tri.'),
(7425, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 10, 6, 'OT', 'Thần của Đức Giê-hô-va sẽ ngự xuống trên ngươi, và ngươi sẽ nói tiên tri cùng với họ, và ngươi sẽ trở thành một người khác.'),
(7426, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 10, 7, 'OT', 'Và khi những dấu hiệu này đến cùng ngươi, hãy làm điều mà tay ngươi gặp phải, vì Đức Chúa Trời ở cùng ngươi.'),
(7427, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 10, 8, 'OT', 'Ngươi hãy xuống trước mặt ta đến Ghinh-ganh; và nầy, ta sẽ xuống cùng ngươi để dâng những của lễ thiêu và tế những của lễ thù ân. Ngươi phải đợi bảy ngày, cho đến khi ta đến cùng ngươi và chỉ cho ngươi biết điều ngươi phải làm.'),
(7428, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 10, 9, 'OT', 'Khi người vừa quay lưng để đi khỏi Sa-mu-ên, Đức Chúa Trời đã đổi một tấm lòng khác cho người, và tất cả những điềm ấy đã xảy ra trong ngày đó.'),
(7429, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 10, 10, 'OT', 'Khi họ đến nơi đó trên đồi, thì này, một nhóm các nhà tiên tri đi ra đón ông; và Thần của Đức Chúa Trời xâm chiếm ông, và ông nói tiên tri giữa họ.'),
(7430, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 10, 11, 'OT', 'Khi tất cả những người quen biết anh từ trước thấy việc ấy, rằng này, anh ta đang nói tiên tri giữa các nhà tiên tri, thì dân chúng nói với nhau: Con trai Kích đã gặp chuyện gì vậy? Há phải Sa-un cũng ở giữa các nhà tiên tri sao?'),
(7431, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 10, 12, 'OT', 'Người trong nhóm đó trả lời và nói: "Cha của họ là ai?" Vì vậy, câu nói đó trở thành một câu tục ngữ: "Liệu Sa-un cũng ở giữa các đấng tiên tri sao?"'),
(7432, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 10, 13, 'OT', 'Sau khi dứt nói tiên tri, ông lên đến nơi cao.'),
(7433, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 10, 14, 'OT', 'Đo-út, chú của Sau-lơ, nói với người và với đầy tớ rằng: "Các ngươi đi đâu vậy?" Người đáp: "Chúng tôi đi tìm những con lừa; thấy chúng không ở đâu cả, nên chúng tôi đến gặp Sa-mu-ên."'),
(7434, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 10, 15, 'OT', 'Và người chú của Sau-lơ nói: Hãy nói cho tôi biết, tôi xin anh, Sa-mu-ên đã nói gì với anh.'),
(7435, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 10, 16, 'OT', 'Và Sa-un nói với người cậu của mình: "Người ấy đã báo cho chúng tôi biết các lừa đã được tìm thấy." Nhưng về việc vương quốc mà Sa-mu-ên đã nói, ông không nói cho người cậu ấy biết.'),
(7436, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 10, 17, 'OT', 'Và Sa-mu-ên triệu tập toàn thể dân chúng đến cùng Đức Giê-hô-va tại Mích-pha.'),
(7437, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 10, 18, 'OT', 'Bấy giờ người nói với các con trai của Y-sơ-ra-ên rằng: "Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên phán như vầy: Ta đã đem Y-sơ-ra-ên lên từ Ai-cập, và giải cứu các ngươi khỏi tay người Ai-cập, khỏi tay mọi nước và khỏi tay các vương quốc đã áp bức các ngươi."'),
(7438, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 10, 19, 'OT', 'Hôm nay các ngươi đã từ bỏ Đức Chúa Trời mình, là Đấng đã giải cứu các ngươi khỏi mọi tai họa và mọi cảnh khốn khó của các ngươi; các ngươi đã nói với Ngài: "Không, hãy đặt một vị vua cai trị trên chúng tôi." Vậy bây giờ, hãy đứng trước mặt Đức Giê-hô-va theo các chi phái và các ngàn người của các ngươi.'),
(7439, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 10, 20, 'OT', 'Sau đó, Sa-mu-ên triệu tập tất cả các chi phái của Y-sơ-ra-ên, và chi phái Bên-gia-min được chọn ra.'),
(7440, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 10, 21, 'OT', 'Người ta đưa chi phái Bên-gia-min đến theo các gia đình của họ, thì gia đình Ma-tri bị chọn ra; và Sau-lơ, con trai của Kích, được chọn ra. Nhưng khi người ta tìm ông, thì không tìm thấy ông.'),
(7441, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 10, 22, 'OT', 'Họ lại hỏi Đức Giê-hô-va lần nữa: "Người ấy có đến đây nữa không?" Đức Giê-hô-va đáp: "Này, người đang ẩn mình giữa các đồ vật."'),
(7442, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 10, 23, 'OT', 'Họ chạy đi và mang anh ấy từ nơi đó đến; khi anh ấy đứng giữa dân chúng, thì anh ấy cao hơn tất cả mọi người, từ vai trở lên.'),
(7443, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 10, 24, 'OT', 'Rồi Sa-mu-ên nói với toàn thể dân chúng: "Hỡi các ngươi, hãy xem người mà Đức Giê-hô-va đã chọn, không ai sánh được với người trong toàn thể dân chúng!" Cả dân chúng reo hò và nói: "Vạn tuế vua!"'),
(7444, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 10, 25, 'OT', 'Sa-mu-ên nói cho dân chúng biết những điều luật lệ về nền quân chủ, và ông chép vào một cuốn sách, rồi đặt nó trước mặt Đức Giê-hô-va. Sau đó, Sa-mu-ên cho tất cả dân chúng về, mỗi người về nhà mình.'),
(7445, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 10, 26, 'OT', 'Sau đó, Sa-un cũng đi về nhà mình tại Ghi-bê-ah; và có một nhóm người dũng cảm đi cùng ông, những người mà Đức Chúa Trời đã cảm động lòng họ.'),
(7446, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 10, 27, 'OT', 'Nhưng những con trai của Bê-li-ál nói: "Người này sẽ cứu chúng ta bằng cách nào?" Và họ khinh bỉ người ấy, không mang lễ vật nào đến cho người ấy; và người ấy giữ im lặng.'),
(7447, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 11, 1, 'OT', 'Nahách, người Am-môn, kéo lên và đóng trại đối với Gia-be Ghi-lê-át; và mọi người nam của Gia-be nói với Nahách: "Hãy lập giao ước với chúng tôi, và chúng tôi sẽ phục vụ ông."'),
(7448, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 11, 2, 'OT', 'Na-ha-sết, người Am-môn, đáp: "Ta sẽ lập giao ước với các ngươi trên điều kiện này: ta sẽ móc bỏ mắt phải của từng người các ngươi, để làm điều sỉ nhục cho toàn thể Y-sơ-ra-ên."'),
(7449, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 11, 3, 'OT', 'Các trưởng lão ở Y-bê-s nói với người rằng: "Hãy để cho chúng tôi bảy ngày nghỉ ngơi, để chúng tôi sai sứ giả đi khắp các vùng đất của Y-sơ-ra-ên. Nếu không có ai đến cứu chúng tôi, thì chúng tôi sẽ ra hàng ông."'),
(7450, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 11, 4, 'OT', 'Các sứ giả đến thành Gibeat của Sa-un và thuật lại tin tức cho dân chúng nghe; toàn thể dân chúng liền cất tiếng khóc than.'),
(7451, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 11, 5, 'OT', 'Và nầy, Sa-un đến sau bầy bò từ ngoài đồng; Sa-un nói: "Dân chúng làm sao mà khóc vậy?" Họ bèn thuật cho ông những lời của các người ở Y-bê-s.'),
(7452, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 11, 6, 'OT', 'Thần của Đức Chúa Trời ngự trên Sa-un khi ông nghe những tin ấy, và cơn giận của ông bốc lên dữ dội.'),
(7453, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 11, 7, 'OT', 'Ông lấy một đôi bò, chặt chúng ra từng mảnh, rồi sai các sứ giả mang đi khắp các vùng lãnh thổ của Y-sơ-ra-ên, truyền rằng: "Ai không ra đi theo Sau-lơ và theo Sa-mu-ên, thì cũng sẽ bị xử trí như những con bò của người ấy." Bấy giờ, sự kính sợ Đức Giê-hô-va giáng trên toàn dân, và họ ra đi như một người duy nhất.'),
(7454, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 11, 8, 'OT', 'Người điểm họ tại Bê-xek, và con cái Ít-ra-en gồm ba trăm ngàn người, còn người của Giu-đa là ba vạn người.'),
(7455, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 11, 9, 'OT', 'Họ nói với các sứ giả đến rằng: "Các ông hãy nói như thế này với những người đàn ông ở Y-bê-sết Ghi-lê-át: Ngày mai, khi mặt trời lên nóng gắt, các ông sẽ được giải cứu." Các sứ giả đi và loan báo cho những người ở Y-bê-sết; và họ vui mừng.'),
(7456, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 11, 10, 'OT', 'Các người của Y-bê-sai nói: "Ngày mai chúng tôi sẽ ra đầu hàng các ông, và các ông sẽ làm điều gì tốt lành theo ý các ông đối với chúng tôi."'),
(7457, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 11, 11, 'OT', 'Hôm sau, Sa-un chia quân đội ra làm ba đạo; họ xông vào giữa trại giặc lúc canh sáng, đánh giết người Am-môn cho đến trưa. Những kẻ còn sót lại thì bị tan rã, không còn hai người nào ở lại cùng nhau.'),
(7458, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 11, 12, 'OT', 'Dân chúng nói với Sa-mu-ên: "Ai là người đã nói: ''Sa-un sẽ trị vì trên chúng ta''? Hãy đưa những người đó ra đây, để chúng tôi giết họ."'),
(7459, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 11, 13, 'OT', 'Và Sa-un nói: "Không ai được giết hôm nay, vì ngày nay Đức Giê-hô-va đã thực hiện sự cứu rỗi trong Y-sa-ra-ên."'),
(7460, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 11, 14, 'OT', 'Bấy giờ Sa-mu-ên nói với dân chúng: "Hãy đi, chúng ta sẽ đi đến Ghíp-ganh và ở đó làm lễ lập lại vương quốc."'),
(7461, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 11, 15, 'OT', 'Cả dân chúng đi đến Ghinh-ganh; và tại đó, họ tôn Sa-un làm vua trước mặt Đức Giê-hô-va tại Ghinh-ganh; và tại đó, họ dâng những của lễ thù ân trước mặt Đức Giê-hô-va; và tại đó, Sa-un và mọi người Ít-ra-en vui mừng hết sức.'),
(7462, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 12, 1, 'OT', 'Và Sa-mu-ên nói với toàn thể dân Y-sơ-ra-ên: "Nầy, tôi đã nghe theo tiếng các ngươi trong mọi điều các ngươi nói với tôi, và đã lập một vị vua cai trị các ngươi."'),
(7463, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 12, 2, 'OT', 'Và bây giờ, hãy xem, vua đang đi trước mặt các ngươi; còn ta, ta đã già và tóc bạc; này, các con trai ta ở cùng các ngươi; và ta đã đi trước mặt các ngươi từ khi ta còn trẻ cho đến ngày nay.'),
(7464, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 12, 3, 'OT', 'Nầy, tôi đây, hãy làm chứng chống lại tôi trước mặt Đức Giê-hô-va và trước mặt Đấng chịu xức dầu của Ngài: tôi đã lấy bò của ai, hay lừa của ai? Tôi đã ức hiếp ai, hay làm thiệt hại ai? Tôi đã nhận hối lộ từ tay ai để làm mờ mắt mình? Nếu có, tôi sẽ hoàn trả lại cho các ông.'),
(7465, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 12, 4, 'OT', 'Họ nói: "Ngài không chiếm đoạt chúng tôi, cũng không áp bức chúng tôi, và không lấy điều gì từ tay một người nào."'),
(7466, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 12, 5, 'OT', 'Người nói với họ: "Đức Giê-hô-va làm chứng cho các ngươi, và Đấng được xức dầu của Ngài làm chứng ngày nay, rằng các ngươi không tìm thấy điều gì trong tay ta." Họ đáp: "Ngài làm chứng."'),
(7467, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 12, 6, 'OT', 'Và Sa-mu-ên nói với dân chúng: "Đức Giê-hô-va là Đấng đã làm nên Môi-se và A-rôn, và Đấng đã đưa tổ tiên các ngươi lên từ đất Ai-cập."'),
(7468, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 12, 7, 'OT', 'Hãy đứng yên tại đây, để tôi xét xử cùng các ngươi trước mặt Đức Giê-hô-va về mọi việc công bình mà Đức Giê-hô-va đã làm cho các ngươi và cho các tổ phụ các ngươi.'),
(7469, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 12, 8, 'OT', 'Khi Gia-cốp vào Ai Cập, tổ tiên các ngươi kêu cứu Đức Giê-hô-va, thì Đức Giê-hô-va sai Môi-se và A-rôn, hai người ấy đưa tổ tiên các ngươi ra khỏi Ai Cập và cho họ ở tại nơi này.'),
(7470, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 12, 9, 'OT', 'Khi họ quên Đức Giê-hô-va là Đức Chúa Trời của mình, thì Ngài đã bán họ vào tay Si-sê-ra, tướng quân đội của Ha-dô, và vào tay người Phi-li-tin, và vào tay vua xứ Mô-áp; và họ đã chiến đấu chống lại họ.'),
(7471, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 12, 10, 'OT', 'Họ kêu lên cùng Đức Giê-hô-va và nói: "Chúng tôi đã phạm tội, vì chúng tôi đã lìa bỏ Đức Giê-hô-va và phục vụ các thần Ba-al và các nữ thần Ách-ta-rốt. Nhưng bây giờ, xin giải cứu chúng tôi khỏi tay kẻ thù của chúng tôi, và chúng tôi sẽ phục vụ Ngài."'),
(7472, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 12, 11, 'OT', 'Đức Giê-hô-va sai Ghi-đê-ôn, Bê-đan, Y-phát và Sa-mu-ên, giải cứu các ngươi khỏi tay kẻ thù xung quanh, và các ngươi sống yên ổn.'),
(7473, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 12, 12, 'OT', 'Khi các ngươi thấy Na-hách, vua của con cái Am-môn, đến đánh các ngươi, thì các ngươi nói cùng ta rằng: "Không! Nhưng một vị vua phải trị vì trên chúng tôi"; trong khi Đức Giê-hô-va Đức Chúa Trời các ngươi chính là Vua của các ngươi.'),
(7474, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 12, 13, 'OT', 'Bây giờ, hãy xem, đây là vua mà các ngươi đã chọn, mà các ngươi đã đòi hỏi; và, nầy, Đức Giê-hô-va đã đặt một vua trên các ngươi.'),
(7475, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 12, 14, 'OT', 'Nếu các ngươi kính sợ Đức Giê-hô-va, phục sự Ngài, nghe theo tiếng Ngài, và không chống nghịch mạng lịnh của Đức Giê-hô-va, thì cả các ngươi lẫn vị vua cai trị các ngươi cũng sẽ tiếp tục theo Đức Giê-hô-va Đức Chúa Trời của các ngươi.'),
(7476, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 12, 15, 'OT', 'Nhưng nếu các ngươi không nghe theo tiếng của Đức Giê-hô-va, và chống nghịch lại mệnh lệnh của Ngài, thì tay Đức Giê-hô-va sẽ chống lại các ngươi và tổ tiên các ngươi.'),
(7477, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 12, 16, 'OT', 'Bây giờ hãy đứng dậy và xem điều lớn lao nầy mà Đức Giê-hô-va sẽ làm ngay trước mặt các ngươi.'),
(7478, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 12, 17, 'OT', 'Hôm nay chẳng phải là mùa gặt lúa mì sao? Ta sẽ kêu cầu Đức Giê-hô-va, Ngài sẽ cho sấm sét và mưa xuống; để các ngươi nhận biết và thấy rằng tội ác các ngươi rất lớn trước mặt Đức Giê-hô-va, vì các ngươi đã xin một vị vua.'),
(7479, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 12, 18, 'OT', 'Bấy giờ, Sa-mu-ên kêu cầu Đức Giê-hô-va; và Đức Giê-hô-va khiến có tiếng sấm và mưa đá trong ngày ấy. Mọi người rất sợ Đức Giê-hô-va và Sa-mu-ên.'),
(7480, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 12, 19, 'OT', 'Và toàn thể dân chúng nói với Sa-mu-ên: "Hãy cầu nguyện cho các tôi tớ ông trước mặt Đức Giê-hô-va Đức Chúa Trời của ông, để chúng tôi không chết, vì chúng tôi đã phạm thêm điều ác vào mọi tội lỗi mình, khi xin một vị vua cho chúng tôi."'),
(7481, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 12, 20, 'OT', 'Và Sa-mu-ên nói với dân chúng: "Đừng sợ; các ngươi đã làm mọi điều ác này; nhưng chớ xây bỏ mà không theo Đức Giê-hô-va, mà hãy hầu việc Đức Giê-hô-va hết lòng các ngươi.'),
(7482, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 12, 21, 'OT', 'Và các ngươi chớ đi lạc, vì những điều hư không vốn chẳng ích lợi gì và chẳng cứu giúp được; vì chúng là điều hư không.'),
(7483, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 12, 22, 'OT', 'Vì Đức Giê-hô-va sẽ không từ bỏ dân Ngài vì danh Ngài rất lớn; vì Đức Giê-hô-va đã bằng lòng làm cho các ngươi trở nên dân thuộc về Ngài.'),
(7484, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 12, 23, 'OT', 'Còn tôi, Đức Giê-hô-va forbid tôi phạm tội cùng Đức Giê-hô-va bằng cách thôi không cầu nguyện cho các ông; tôi sẽ dạy các ông con đường tốt lành và ngay thẳng.'),
(7485, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 12, 24, 'OT', 'Chỉ hãy kính sợ Đức Giê-hô-va và phục sự Ngài cách chân thật với trọn tấm lòng các ngươi; vì hãy xem điều lớn lao nào Ngài đã làm cho các ngươi.'),
(7486, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 12, 25, 'OT', 'Nhưng nếu các ngươi cứ làm điều ác, thì cả các ngươi và vua các ngươi sẽ bị tiêu diệt.'),
(7487, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 13, 1, 'OT', 'Sau-lơ lên ngôi vua được một năm, và ông trị vì trên Ít-ra-en được hai năm.'),
(7488, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 13, 2, 'OT', 'Sa-un chọn cho mình ba ngàn người trong Y-sơ-ra-ên; hai ngàn người ở với Sa-un tại Mích-mát và núi Bê-thên, và một ngàn người ở với Giô-na-than tại Ghi-bê-ôn, thuộc đất Bên-gia-min; còn phần còn lại của dân chúng thì người cho mỗi người trở về trại mình.'),
(7489, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 13, 3, 'OT', 'Và Giô-na-than đánh bại đội quân đóng giữ của người Phi-li-tin tại Gê-ba; người Phi-li-tin nghe được điều đó. Sau đó, Sau-lơ thổi kèn khắp cả đất, nói: "Hỡi người Hê-bơ-rơ, hãy nghe đây!"'),
(7490, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 13, 4, 'OT', 'Toàn thể Y-sơ-ra-ên nghe tin rằng Sau-lơ đã đánh bại một trại quân của người Phi-li-tin, và rằng Y-sơ-ra-ên đã trở nên đáng ghét đối với người Phi-li-tin; rồi toàn dân liền tụ họp lại theo Sau-lơ tại Ghinh-ganh.'),
(7491, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 13, 5, 'OT', 'Người Phi-li-tin nhóm lại để giao chiến với Y-sơ-ra-ên: ba mươi ngàn xe, sáu ngàn kỵ binh, và dân chúng đông như cát trên bờ biển. Chúng kéo lên và đóng trại tại Mích-mát, về phía đông Bê-tha-ven.'),
(7492, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 13, 6, 'OT', 'Dân Y-sơ-ra-ên thấy mình lâm vào cảnh khốn quẫn, vì dân chúng bị áp bức; dân chúng bèn trốn vào các hang, các hốc đá, các vách đá, các vũng trũng và các hố sâu.'),
(7493, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 13, 7, 'OT', 'Các người Hê-bơ-rơ đi qua sông Giô-đanh đến xứ Gát và Ga-la-át. Còn Sau-lơ, ông vẫn còn ở Ghinh-ganh, và toàn thể dân chúng đi theo ông mà run sợ.'),
(7494, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 13, 8, 'OT', 'Ông đợi bảy ngày, đúng thời gian mà Sa-mu-ên đã định, nhưng Sa-mu-ên không đến Ga-la; và dân chúng bắt đầu tan rã khỏi ông.'),
(7495, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 13, 9, 'OT', 'Sa-un nói: "Hãy đem đến cho ta của lễ thiêu và của lễ thù ân." Rồi người dâng của lễ thiêu lên.'),
(7496, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 13, 10, 'OT', 'Xảy ra rằng, khi vừa dâng xong của lễ thiêu, thì này, Sa-mu-ên đang đến; và Sau-lơ đi ra đón người để chào hỏi người.'),
(7497, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 13, 11, 'OT', 'Đức Sa-mu-ên nói: "Ngươi đã làm điều gì vậy?" Sa-un đáp: "Vì tôi thấy dân chúng rời bỏ tôi, còn ông thì không đến trong thời hạn đã định, và người Phi-li-tin đã tụ họp tại Mích-mát."'),
(7498, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 13, 12, 'OT', 'Tôi nói: "Bây giờ người Phi-li-tin sẽ xuống đánh tôi tại Ghinh-ganh, mà tôi thì chưa cầu khẩn Đức Giê-hô-va," nên tôi cưỡng ép chính mình dâng của lễ thiêu.'),
(7499, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 13, 13, 'OT', 'Sa-mu-ên nói với Sa-un: "Ngươi đã làm điều dại dột; ngươi không tuân giữ điều răn mà Đức Giê-hô-va Đức Chúa Trời ngươi đã truyền cho ngươi. Vì bây giờ Đức Giê-hô-va đã định sẽ lập vương quốc ngươi trên Ít-ra-en đời đời."'),
(7500, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 13, 14, 'OT', 'Bây giờ, vương quốc của ngươi sẽ không còn tồn tại; Đức Giê-hô-va đã tìm một người theo ý lòng Ngài, và Đức Giê-hô-va đã chỉ định người ấy làm lãnh tụ cai trị dân Ngài, vì ngươi đã không tuân giữ điều mà Đức Giê-hô-va đã truyền cho ngươi.'),
(7501, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 13, 15, 'OT', 'Rồi Sa-mu-ên đứng dậy, đi lên từ Ghinh-ganh đến Ghi-bê-ah của Bên-gia-min. Sau đó, Sau-lơ điểm số những người hiện diện cùng ông, khoảng sáu trăm người.'),
(7502, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 13, 16, 'OT', 'Và Sa-un, cùng với Giô-na-than, con trai người, và dân chúng còn lại ở cùng họ, ở lại tại Ghíp-ê của Bên-gia-min; còn người Phi-li-tin thì đóng trại tại Mích-mát.'),
(7503, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 13, 17, 'OT', 'Và những toán quân cướp phá xuất phát từ trại quân người Phi-li-tin, chia làm ba nhóm; nhóm thứ nhất rẽ về hướng đường đi đến Ô-phơ-ra, thuộc vùng đất Sú-an.'),
(7504, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 13, 18, 'OT', 'Và một nhóm sẽ rẽ đường về hướng nhà Hô-rôn; còn một nhóm khác sẽ rẽ đường về hướng vùng biên giới nhìn xuống thung lũng Xê-bô-im về phía đồng vắng.'),
(7505, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 13, 19, 'OT', 'Không tìm thấy thợ rèn nào trong khắp đất Y-sơ-ra-ên, vì người Phi-li-tin nói: "Kẻo dân Hê-bơ-rơ làm ra gươm hoặc giáo."'),
(7506, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 13, 20, 'OT', 'Toàn thể dân Y-sơ-ra-ên phải xuống với người Phi-li-tin để mài mỗi người cái ách cày, cái cày, cái rìu và cái thuổng của mình.'),
(7507, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 13, 21, 'OT', 'Họ phải mài nhọn các cái cuốc, các cái cày đực, ba răng, các cái rìu và cái chông cày.'),
(7508, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 13, 22, 'OT', 'Xảy ra trong ngày giao chiến, không tìm thấy gươm hay giáo trong tay toàn thể dân chúng đi theo Sa-un và Yô-na-than; chỉ có Sa-un và Yô-na-than, con trai ông, mới tìm thấy.'),
(7509, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 13, 23, 'OT', 'Bấy giờ một toán quân của người Phi-li-tin đi ra đến lối qua Mích-mát.'),
(7510, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 1, 'OT', 'Một ngày kia, Giô-na-than con trai của Sau-lơ nói với người đầy tớ mang áo giáp cho mình: "Nào, hãy sang bên kia trại quân của người Phi-li-tin." Nhưng người ấy không nói cho cha người ấy biết.'),
(7511, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 2, 'OT', 'Sa-un ngồi ở phần rìa của Ghíp-ê, dưới cây lựu ở Mích-rôn; và những người đi theo ông khoảng sáu trăm người.'),
(7512, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 3, 'OT', 'Ahia, con trai của Ahitub, anh em của Y-ca-bốt, con trai của Pinehas, con trai của Eli, thầy tế lễ của Đức Giê-hô-va tại Si-lô, đang mang áo ê-phót; và dân chúng không biết rằng Giô-na-than đã đi.'),
(7513, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 4, 'OT', 'Giữa những lối đi mà Giô-nát-an tìm cách vượt qua đến đồn lính Phi-li-tin, có một tảng đá nhọn bên này và một tảng đá nhọn bên kia; tên của tảng này là Bô-xe-x, tên của tảng kia là Xê-nê.'),
(7514, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 5, 'OT', 'Tảng đá này ở về phía bắc đối diện với Mích-mát, và tảng đá kia ở về phía nam đối diện với Ghi-bê-ah.'),
(7515, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 6, 'OT', 'Vậy Giô-na-than nói với người trai trẻ mang áo giáp cho mình: "Nào, hãy đi qua chỗ đồn quân của những kẻ không chịu cắt bì kia; có lẽ Đức Giê-hô-va sẽ hành động nhân danh chúng ta; vì đối với Đức Giê-hô-va, không có gì ngăn trở để cứu giúp, dù bằng nhiều người hay ít người."'),
(7516, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 7, 'OT', 'Người mang áo giáp nói với người ấy: "Hãy làm mọi điều theo ý ông muốn; ông cứ đi đi, tôi sẽ ở cùng ông theo như lòng ông."'),
(7517, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 8, 'OT', 'Rồi Giô-na-than nói: Này, chúng ta hãy qua bên kia gặp những người đó, và sẽ để lộ mình cho họ.'),
(7518, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 9, 'OT', 'Nếu chúng nói với chúng ta như thế này: "Hãy đứng yên cho đến khi chúng tôi đến gần các ngươi," thì chúng ta sẽ đứng tại chỗ mình đang đứng, và sẽ không tiến lên phía chúng.'),
(7519, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 10, 'OT', 'Nhưng nếu họ nói như thế này: "Hãy lên đây đến với chúng tôi," thì chúng ta sẽ lên, vì Đức Giê-hô-va đã giao họ vào tay chúng ta; và điều nầy sẽ là dấu cho chúng ta.'),
(7520, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 11, 'OT', 'Cả hai người lộ mình ra trước trại lính của người Phi-li-tin; và người Phi-li-tin nói: Kìa, những người Hê-bơ-rơ đi ra từ các hang mà họ đã ẩn nấp ở đó.'),
(7521, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 12, 'OT', 'Những người lính canh nơi trại đáp lời Giô-na-than và người mang khí giới cho ông, nói: "Hãy lên đây với chúng tôi, để chúng tôi cho các anh biết một điều." Giô-na-than liền nói với người mang khí giới: "Hãy theo tôi lên, vì Đức Giê-hô-va đã trao họ vào tay Ít-ra-en."'),
(7522, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 13, 'OT', 'Và Giô-na-than trèo lên bằng tay và bằng chân, người lính mang khí giới theo sau ông; và chúng ngã xuống trước mặt Giô-na-than, còn người lính mang khí giới thì giết những kẻ theo sau ông.'),
(7523, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 14, 'OT', 'Số người bị giết trong cuộc tấn công đầu tiên mà Giô-na-than và người mang khí giới của ông gây ra khoảng hai mươi người, trên diện tích đất bằng nửa bề rộng một mẫu ruộng do một cặp bò cày.'),
(7524, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 15, 'OT', 'Và sự run rẩy xảy đến trong trại quân ngoài đồng, trong toàn thể dân chúng; cả toán đồn trú và toán cướp phá cũng run sợ, đất thì rúng động; ấy là một sự run rẩy bởi Đức Chúa Trời.'),
(7525, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 16, 'OT', 'Các người canh gác của Sau-lơ ở Ghíp-tha Bên-gia-min nhìn ra, và kìa, đoàn dân chúng đang tan rã, đi lui đi tới.'),
(7526, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 17, 'OT', 'Sau-đây, Sau-lơ nói với dân sự đi cùng mình: "Hãy kiểm tra xem ai đã đi khỏi chúng ta." Họ liền kiểm tra, và nầy, Giô-na-than và người mang khí giới cho người không có đó.'),
(7527, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 18, 'OT', 'Và Sa-un nói cùng A-hi-a: "Hãy mang đến đây rương của Đức Chúa Trời." Vì rương của Đức Chúa Trời đang ở đó với các con cái Y-sơ-ra-ên trong ngày ấy.'),
(7528, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 19, 'OT', 'Khi Sa-un còn đang nói chuyện với thầy tế lễ, thì tiếng ồn trong trại quân của người Phi-li-tin cứ gia tăng mãi; Sa-un liền nói với thầy tế lễ: "Hãy rút tay ông lại."'),
(7529, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 20, 'OT', 'Sa-un và toàn thể dân sự đi cùng người tụ tập lại, rồi đến nơi chiến trận; và nầy, mỗi người rút gươm chống lại người đồng bạn mình, và xảy ra một sự hỗn loạn rất lớn.'),
(7530, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 21, 'OT', 'Các người Hê-bơ-rơ vốn ở với người Phi-li-tin như những người đến ngày hôm qua và hôm kia, những người đã lên cùng họ vào trại quân quanh đó, cũng quay trở lại đứng về phía Y-sơ-ra-ên, những người theo Sau-lơ và Giô-na-than.'),
(7531, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 22, 'OT', 'Và tất cả những người Ít-ra-en đã ẩn náu trong núi Ép-ra-im, khi nghe tin người Phi-li-tin đã chạy trốn, thì cũng xông lên đuổi theo họ vào giữa trận chiến.'),
(7532, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 23, 'OT', 'Đức Giê-hô-va cứu Ít-ra-en trong ngày ấy; và cuộc chiến lan qua Bê-tha-ven.'),
(7533, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 24, 'OT', 'Ngày ấy, dân Y-sơ-ra-ên bị khốn khổ; và Sau-lơ đã khiến dân phải thề rằng: "Phải nguyền rủa người nào ăn bánh cho đến chiều tối, hầu ta được báo thù trên các kẻ thù mình!" Vì thế, toàn dân không ai dám nếm bánh.'),
(7534, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 25, 'OT', 'Toàn thể dân chúng tiến vào khu rừng, và thấy mật ong chảy trên mặt đất.'),
(7535, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 26, 'OT', 'Dân chúng đi vào rừng, và này, có mật ong chảy ra; nhưng không ai đưa tay lên miệng mình, vì dân sợ lời thề.'),
(7536, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 27, 'OT', 'Nhưng Giô-na-than không nghe khi cha người thề hứa cùng dân sự; người đưa đầu cây gậy nơi tay mình, nhúng vào ổ mật ong, rồi đưa tay lên miệng, và mắt người sáng lên.'),
(7537, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 28, 'OT', 'Một người trong dân đáp và nói: Cha ông đã bắt dân phải thề một cách nghiêm khắc rằng: "Phạt dữ cho người nào ăn thức ăn nào hôm nay." Vì thế, dân cảm thấy mệt lả.'),
(7538, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 29, 'OT', 'Rồi Giô-na-than nói: Cha tôi đã làm cho đất bị rối loạn. Xin hãy xem, mắt tôi đã sáng lên làm sao, vì tôi đã nếm chút mật ong này.'),
(7539, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 30, 'OT', 'Phải chi hôm nay dân có ăn tự do của cướp được từ kẻ thù mình đã gặp, thì chắc chắn sẽ có một sự tàn sát lớn hơn giữa người Phi-li-tin.'),
(7540, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 31, 'OT', 'Họ đánh bại người Phi-li-tin trong ngày ấy từ Mi-khơ-ma đến Ai-ja-lôn, và dân chúng rất mệt mỏi.'),
(7541, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 32, 'OT', 'Dân chúng xông vào chiến lợi phẩm, bắt lấy chiên, bò và bê, rồi giết trên mặt đất; và dân chúng ăn luôn cả huyết.'),
(7542, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 33, 'OT', 'Họ báo cho Sa-un rằng: "Nầy, dân chúng phạm tội nghịch cùng Đức Giê-hô-va, vì họ ăn thịt có máu trong đó." Sa-un đáp: "Các ngươi đã phạm tội rồi; hãy lăn một tảng đá lớn đến cùng ta ngày nay."'),
(7543, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 34, 'OT', 'Vua Sau-lơ nói: "Hãy phân tán giữa dân chúng, và bảo họ: Mỗi người hãy mang bò của mình và chiên của mình đến cho ta, rồi giết tại đây mà ăn, để các ngươi khỏi phạm tội cùng Đức Giê-hô-va bằng cách ăn thịt có huyết." Vậy, toàn thể dân chúng đều mang bò mình đến vào đêm đó, và giết tại đó.'),
(7544, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 35, 'OT', 'Sa-un xây một bàn thờ cho Đức Giê-hô-va; ấy là bàn thờ đầu tiên mà ông xây cho Đức Giê-hô-va.'),
(7545, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 36, 'OT', 'Sa-un nói: "Hãy xuống đuổi theo người Phi-li-tin ban đêm, và cướp phá chúng cho đến khi ánh sáng ban mai xuất hiện, không để sót một người nào trong chúng." Họ đáp: "Xin làm mọi điều theo ý ông thấy tốt." Rồi thầy tế lễ nói: "Hãy đến gần đây, chúng ta sẽ đến cùng Đức Chúa Trời."'),
(7546, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 37, 'OT', 'Sau-lơ cầu hỏi Đức Chúa Trời: "Tôi có nên đi xuống đuổi theo người Phi-li-tin không? Ngài có nộp họ vào tay Y-sơ-ra-ên không?" Nhưng Ngài không đáp lời người trong ngày ấy.'),
(7547, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 38, 'OT', 'Và Sau-lơ nói: "Hãy đến gần đây, tất cả các thủ lĩnh của dân chúng; hãy tìm hiểu và xem xét xem tội lỗi này đã xảy ra như thế nào hôm nay."'),
(7548, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 39, 'OT', 'Đức Giê-hô-va hằng sống, Đấng cứu Ít-ra-en, nếu điều đó xảy ra nơi Giô-na-than, con trai ta, thì nó chắc chắn sẽ chết; nhưng không một người nào trong toàn thể dân sự đáp lại người.'),
(7549, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 40, 'OT', 'Bấy giờ người nói với toàn thể Y-sơ-ra-ên: "Các ngươi hãy đứng về một phía, còn ta và Yô-na-than con trai ta sẽ đứng về một phía khác." Dân chúng nói với Sau-lơ: "Ngài hãy làm điều gì Ngài thấy tốt lành."'),
(7550, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 41, 'OT', 'Sa-un nói cùng Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en: "Xin chỉ ra người vô tội." Vậy thì chỉ có Giô-na-than và Sa-un bị bắt, còn dân chúng thì thoát.'),
(7551, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 42, 'OT', 'Sau-lơ nói: "Hãy bắt thăm giữa ta và Giô-na-than, con trai ta." Và Giô-na-than bị bắt trúng thăm.'),
(7552, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 43, 'OT', 'Sa-ôn nói với Giô-na-than: "Hãy cho ta biết, con đã làm gì?" Giô-na-than thưa: "Con chỉ nếm chút mật ong ở đầu cây gậy con cầm trong tay; nầy, con phải chết sao?"'),
(7553, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 44, 'OT', 'Bấy giờ Sa-un đáp: "Đức Chúa Trời làm sao và còn làm thêm thể nào nữa, thì cũng sẽ như vậy: Giô-na-than chắc chắn phải chết."'),
(7554, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 45, 'OT', 'Dân chúng nói với Sau-lơ: "Giô-na-than phải chết sao, người đã thực hiện sự cứu rỗi lớn lao này cho Ít-ra-en? Chẳng thể nào! Đức Giê-hô-va hằng sống, không một sợi tóc nào trên đầu cậu ấy sẽ rơi xuống đất, vì hôm nay cậu ấy đã hành động cùng Đức Chúa Trời." Vậy dân chúng đã cứu Giô-na-than, và cậu ấy không chết.'),
(7555, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 46, 'OT', 'Sa-un rút lui không đuổi theo người Phi-li-tin nữa, và người Phi-li-tin trở về nơi của họ.'),
(7556, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 47, 'OT', 'Sa-un lên ngôi làm vua trên Ít-ra-en, rồi đánh các kẻ thù mình chung quanh, chống lại Mô-áp, con cái Am-môn, Ê-đôm, các vua Xô-ba, và người Phi-li-tin; và bất cứ nơi nào ông quay đến, ông đều đánh bại chúng.'),
(7557, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 48, 'OT', 'Ông làm những việc lớn, đánh bại người A-ma-léc và giải cứu Y-sơ-ra-ên khỏi tay những kẻ cướp phá họ.'),
(7558, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 49, 'OT', 'Con trai của Sa-un là Giô-na-than, Ích-bi và Mal-khí-xu-a; tên hai con gái ông là tên đứa con gái đầu lòng là Mê-ráp, và tên đứa con gái út là Mích-an.'),
(7559, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 50, 'OT', 'Tên vợ của Sau-lơ là A-hi-nô-am, con gái của A-hi-mát-x; và tên chỉ huy quân đội ông là A-bi-nê, con trai của Nê-er, anh em trai của Sau-lơ.'),
(7560, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 51, 'OT', 'Kích là cha của Sa-un; và Ner là cha của Áp-nê, con trai của A-bi-ên.'),
(7561, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 14, 52, 'OT', 'Và chiến tranh dữ dội xảy ra với người Phi-li-tin suốt mọi ngày của Sau-lơ; và khi Sau-lơ thấy bất kỳ người tráng sĩ nào, hay bất kỳ người nào có tài năng, thì người thu nhận người ấy về mình.'),
(7562, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 1, 'OT', 'Sa-mu-ên cũng nói với Sau-lơ: Đức Giê-hô-va đã sai tôi đến xức vua cho ông làm vua cai trị dân Ngài, tức là dân Y-sơ-ra-ên; vậy bây giờ, hãy vâng nghe tiếng các lời của Đức Giê-hô-va.'),
(7563, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 2, 'OT', 'Đức Giê-hô-va vạn quân phán như sau: Ta nhớ điều A-ma-léc đã làm cho Y-sơ-ra-ên, khi nó chặn đường nó lúc nó đi lên từ Ai-cập.'),
(7564, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 3, 'OT', 'Bây giờ, hãy đi đánh A-ma-léc, và phải tiêu diệt hoàn toàn mọi thứ thuộc về nó; ngươi không được thương xót nó đâu; phải giết từ người nam đến người nữ, từ trẻ nhỏ đến trẻ đang bú, từ bò đực đến chiên cái, từ lạc đà đến lừa.'),
(7565, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 4, 'OT', 'Vua Sau-lơ triệu tập dân chúng và điểm họ tại Tê-lai-ma; có hai trăm ngàn bộ binh và mười ngàn người của chi phái Giu-đa.'),
(7566, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 5, 'OT', 'Sau-lơ đi đến thành của dân A-ma-léc và phục kích trong thung lũng.'),
(7567, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 6, 'OT', 'Sa-un nói với người Kê-nít: "Hãy đi, rời khỏi giữa người A-ma-léc, kẻo ta sẽ tiêu diệt các ngươi cùng với họ; vì các ngươi đã tỏ lòng nhân từ đối với mọi con trai của Y-sơ-ra-ên khi họ đi lên khỏi Ai-cập." Vậy người Kê-nít liền rời khỏi giữa người A-ma-léc.'),
(7568, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 7, 'OT', 'Sa-un đánh giáp các người A-ma-léc, từ Ha-va-lah cho đến khi đến Su-ur, là nơi ở trước mặt xứ Ê-díp-tô.'),
(7569, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 8, 'OT', 'Ông bắt A-gát, vua dân A-ma-léc, còn sống, và diệt sạch toàn thể dân chúng bằng lưỡi gươm.'),
(7570, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 9, 'OT', 'Nhưng Sa-un và dân chúng thương xót A-gách, và những chiên, bò, chiên con mập tốt, cừu đực và mọi vật tốt lành; họ không nỡ tiêu diệt những vật ấy, nhưng mọi vật hèn hạ và vô giá trị, họ mới tiêu diệt triệt để.'),
(7571, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 10, 'OT', 'Rồi có lời của Đức Giê-hô-va phán cùng Sa-mu-ên rằng:'),
(7572, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 11, 'OT', 'Đức Giê-hô-va phán: Ta hối hận vì đã lập Sau-lơ làm vua, vì người đã từ bỏ Ta và không vâng theo mệnh lệnh Ta. Và Sa-mu-ên rất buồn bã, nên ông đã khóc lạy Đức Giê-hô-va suốt cả đêm.'),
(7573, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 12, 'OT', 'Sáng hôm sau, Sa-mu-ên dậy sớm để gặp Sau-lơ; người ta báo cho Sa-mu-ên rằng: "Sau-lơ đã đến Ca-rem, và nầy, người dựng một cái bệ cho mình, rồi quay đi, đi ngang qua và xuống Ghinh-ganh."'),
(7574, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 13, 'OT', 'Và Sa-mu-ên đi đến gặp Sau-lơ. Sau-lơ nói với ông: "Nguyện Đức Giê-hô-va ban phước cho ông! Tôi đã thực hiện trọn lời phán của Đức Giê-hô-va."'),
(7575, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 14, 'OT', 'Rồi Sa-mu-ên nói: "Tiếng chiên kêu bên tai tôi và tiếng bò kêu mà tôi nghe được là gì vậy?"'),
(7576, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 15, 'OT', 'Và Sau-lơ nói: "Chúng tôi đã mang chúng từ người A-ma-léc; vì dân đã thương xót những con chiên và bò tốt nhất để dâng tế lễ cho Đức Giê-hô-va Đức Chúa Trời của ngài; còn phần còn lại, chúng tôi đã tiêu diệt hoàn toàn."'),
(7577, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 16, 'OT', 'Rồi Sa-mu-ên nói với Sa-un: "Hãy dừng lại, để tôi thuật cho ông điều mà Đức Giê-hô-va đã phán cùng tôi đêm nay." Sa-un đáp: "Xin ông hãy nói."'),
(7578, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 17, 'OT', 'Rồi Sa-mu-ên nói: "Nầy, dù ngươi thấy mình nhỏ bé trong mắt mình, chẳng phải ngươi đã được làm đầu các chi phái Y-sơ-ra-ên sao? Đức Giê-hô-va đã xức dầu cho ngươi làm vua cai trị Y-sơ-ra-ên."'),
(7579, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 18, 'OT', 'Đức Giê-hô-va phán cùng ngươi rằng: "Ngươi hãy đi, và ngươi phải tiêu diệt hoàn toàn những kẻ tội lỗi là dân A-ma-léc, và ngươi phải chiến đấu chống lại chúng cho đến khi tiêu diệt chúng hoàn toàn."'),
(7580, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 19, 'OT', 'Vì sao ngươi không vâng theo tiếng của Đức Giê-hô-va, mà lại lao vào của cải chiến lợi phẩm, và làm điều ác trước mắt Đức Giê-hô-va?'),
(7581, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 20, 'OT', 'Sa-un nói với Sa-mu-ên: "Thật, tôi đã vâng theo tiếng của Đức Giê-hô-va, và đi theo con đường mà Đức Giê-hô-va sai tôi, tôi đã mang A-gát, vua dân A-ma-léc, đến, và tôi đã tiêu diệt dân A-ma-léc."'),
(7582, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 21, 'OT', 'Dân chúng đã lấy từ chiến lợi phẩm chiên và bò, những vật đầu tiên phải bị tiêu diệt, để dâng tế lễ cho Đức Giê-hô-va Đức Chúa Trời ngươi tại Ghinh-ganh.'),
(7583, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 22, 'OT', 'Sa-mu-ên nói: Đức Giê-hô-va há thích của lễ thiêu và sinh tế bằng vâng nghe tiếng Đức Giê-hô-va sao? Kìa, vâng nghe thì tốt hơn của lễ, và chăm chỉ nghe lời hơn mỡ chiên đực.'),
(7584, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 23, 'OT', 'Vì sự phản nghịch giống như tội làm phù thủy, và sự cứng lòng giống như tội thờ hình tượng và bói toán; bởi ngươi đã từ chối lời của Đức Giê-hô-va, nên Ngài cũng đã từ chối ngươi không được làm vua.'),
(7585, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 24, 'OT', 'Và Sau-lơ nói với Sa-mu-ên: "Tôi đã phạm tội, vì tôi đã vi phạm mệnh lệnh của Đức Giê-hô-va và các lời của ông, bởi tôi đã sợ dân chúng và vâng theo tiếng nói của họ."'),
(7586, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 25, 'OT', 'Bây giờ, xin hãy nhận lấy tội lỗi của tôi, và trở lại cùng tôi, để tôi có thể thờ lạy Đức Giê-hô-va.'),
(7587, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 26, 'OT', 'Và Sa-mu-ên nói với Sau-lơ: "Tôi sẽ không trở về cùng ông, vì ông đã từ chối lời của Đức Giê-hô-va, nên Đức Giê-hô-va cũng đã từ chối ông làm vua trên Ít-ra-en."'),
(7588, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 27, 'OT', 'Rồi khi Sa-mu-ên quay đi để ra về, ông ấy nắm lấy mép áo choàng của ông, và nó bị rách.'),
(7589, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 28, 'OT', 'Sa-mu-ên nói với ông: "Đức Giê-hô-va đã xé vương quốc Y-sơ-ra-ên khỏi ngươi ngày hôm nay, và ban nó cho một người láng giềng của ngươi, tốt hơn ngươi."'),
(7590, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 29, 'OT', 'Đức Chúa Trời của Ít-ra-en không nói dối, cũng không hối tiếc; vì Ngài không phải là loài người để mà hối tiếc.'),
(7591, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 30, 'OT', 'Vua ấy nói: "Tôi đã phạm tội; bây giờ xin hãy tôn trọng tôi, tôi nài xin, trước mặt các trưởng lão của dân tôi và trước mặt Ít-ra-en, và xin hãy trở lại cùng tôi, để tôi có thể thờ lạy Đức Giê-hô-va Đức Chúa Trời của ngài."'),
(7592, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 31, 'OT', 'Vậy, Sa-mu-ên quay trở lại theo Sau-lơ; và Sau-lơ cúi lạy Đức Giê-hô-va.'),
(7593, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 32, 'OT', 'Rồi Sa-mu-ên nói: "Hãy dẫn A-gát, vua của dân A-ma-léc, đến cùng ta." A-gát liền đến cùng người một cách khoan khoái. A-gát nói: "Thật vậy, sự đắng cay của cái chết đã qua rồi."'),
(7594, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 33, 'OT', 'Sa-mu-ên nói: "Như gươm ngươi đã làm các người phụ nữ trở nên vô con, thì mẹ ngươi cũng sẽ trở nên vô con giữa các người phụ nữ." Rồi Sa-mu-ên xé A-gát ra từng mảnh trước mặt Đức Giê-hô-va tại Ghinh-ganh.'),
(7595, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 34, 'OT', 'Rồi Sa-mu-ên đi về Ra-ma; còn Sa-un thì lên nhà mình ở Ghi-bê của Sa-un.'),
(7596, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 15, 35, 'OT', 'Sa-mu-ên không còn gặp Sau-lơ nữa cho đến ngày Sau-lơ qua đời; Sa-mu-ên than khóc vì Sau-lơ, và Đức Giê-hô-va hối tiếc vì đã đặt Sau-lơ làm vua trên Ít-ra-en.'),
(7597, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 16, 1, 'OT', 'Đức Giê-hô-va phán cùng Sa-mu-ên: "Ngươi sẽ khóc than cho Sau-lơ đến bao giờ? Ta đã từ bỏ người, không cho người còn làm vua trên Ít-ra-en nữa. Hãy đổ đầy dầu vào sừng của ngươi và đi; Ta sẽ sai ngươi đến cùng Ít-si, người Bết-lê-hem, vì Ta đã chọn một vị vua trong các con trai người."'),
(7598, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 16, 2, 'OT', 'Sa-mu-ên nói: "Tôi làm sao đi được? Nếu Sau-lơ nghe được, ông ấy sẽ giết tôi." Và Đức Giê-hô-va phán: "Hãy cầm một con bò cái để dâng sinh tế trong tay ngươi, và nói rằng: Tôi đến để dâng sinh tế cho Đức Giê-hô-va."'),
(7599, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 16, 3, 'OT', 'Hãy gọi Y-sai đến dự lễ tế, Ta sẽ chỉ cho ngươi điều ngươi phải làm; ngươi sẽ xức dầu cho người mà Ta chỉ dạy.'),
(7600, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 16, 4, 'OT', 'Sa-mu-ên làm theo điều Đức Giê-hô-va phán, rồi đi đến Bết-lê-hem. Các bậc trưởng lão của thành sợ hãi khi thấy ông đến, và nói: Ông đến có điều lành chăng?'),
(7601, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 16, 5, 'OT', 'Ông nói: "Bình an, tôi đến để dâng tế lễ cho Đức Giê-hô-va; hãy làm cho mình nên thánh, và hãy đến cùng tôi để dự bữa tế lễ." Ông làm cho Ích-sai và các con trai ông nên thánh, rồi mời họ đến dự bữa tế lễ.'),
(7602, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 16, 6, 'OT', 'Khi họ đến, ông nhìn thấy Ê-li-áp và nói: "Chắc chắn người trước mặt Đức Giê-hô-va đây chính là đấng được Ngài xức dầu."'),
(7603, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 16, 7, 'OT', 'Đức Giê-hô-va phán cùng Sa-mu-ên: "Đừng nhìn đến vẻ bên ngoài hay chiều cao của hắn, vì Ta đã từ chối hắn rồi; bởi vì điều mà người ta thấy không phải là điều mà Đức Giê-hô-va thấy; người ta nhìn vào mặt, nhưng Đức Giê-hô-va nhìn vào lòng."'),
(7604, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 16, 8, 'OT', 'Sau đó, Ích-sai gọi A-bi-na-đáp và đưa người ấy đi ngang qua trước mặt Sa-mu-ên. Nhưng người ấy nói: "Đức Giê-hô-va cũng không chọn người này."'),
(7605, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 16, 9, 'OT', 'Rồi Ích-thai cho Sam-ma đi ngang qua. Nhưng người nói: "Đức Giê-hô-va cũng không chọn người này."'),
(7606, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 16, 10, 'OT', 'Ích-sai cho bảy người con trai mình đi ngang qua trước mặt Sa-mu-ên; Sa-mu-ên nói với Ích-sai: "Đức Giê-hô-va không chọn những người này."'),
(7607, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 16, 11, 'OT', 'Sa-mu-ên nói với Ích-sai: "Các con trai đã hết chưa?" Ông đáp: "Còn lại đứa nhỏ nhất, và nầy, nó đang chăn chiên." Sa-mu-ên nói với Ích-sai: "Hãy sai người đi đón nó, vì chúng tôi sẽ không ngồi dùng bữa cho đến khi nó đến đây."'),
(7608, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 16, 12, 'OT', 'Ông sai đi và đưa cậu ấy đến. Cậu ấy có nước da đỏ, đôi mắt đẹp và vẻ ngoài tuấn tú. Đức Giê-hô-va phán: "Hãy đứng dậy, xức dầu cho cậu ấy, vì chính cậu ấy đây."'),
(7609, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 16, 13, 'OT', 'Sau đó, Sa-mu-ên lấy sừng dầu và xức dầu cho người giữa các anh em mình; và từ ngày ấy trở đi, Thần của Đức Giê-hô-va ngự trên Đa-vít. Rồi Sa-mu-ên đứng dậy và đi về Ra-ma.'),
(7610, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 16, 14, 'OT', 'Thần của Đức Giê-hô-va đã lìa khỏi Sau-lơ, và một thần dữ từ Đức Giê-hô-va khiến ông bồn chồn lo sợ.'),
(7611, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 16, 15, 'OT', 'Bấy giờ các tôi tớ của Sau-lơ nói cùng người rằng: Kìa, bây giờ có một thần ác từ Đức Chúa Trời đến quấy nhiễu người.'),
(7612, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 16, 16, 'OT', 'Xin kính tấu ngài, xin truyền cho các tôi tớ của ngài đang ở trước mặt ngài tìm một người biết chơi đờn cầm; và khi Thần Đức Chúa Trời dữ đến trên ngài, người ấy sẽ chơi đờn, và ngài sẽ được khoẻ lại.'),
(7613, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 16, 17, 'OT', 'Sa-un nói với các đầy tớ mình: "Hãy tìm cho ta một người biết chơi nhạc giỏi, và dẫn người ấy đến cùng ta."'),
(7614, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 16, 18, 'OT', 'Một trong các đầy tớ thưa rằng: "Này tôi thấy một người con trai của Y-sai, người Bê-lem, biết chơi nhạc, là một người dũng cảm, tinh thông việc chiến trận, thông minh trong lời nói, có vẻ ngoài ưa nhìn, và Đức Giê-hô-va ở cùng người ấy."'),
(7615, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 16, 19, 'OT', 'Vậy Sa-un sai các sứ giả đến với Y-xai, và nói: "Hãy sai Đa-vít, con trai ngươi, đến cùng ta, người đang ở với bầy chiên."'),
(7616, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 16, 20, 'OT', 'Và Y-sai lấy một con lừa mang bánh mì, một bầu rượu và một con dê con, rồi sai Đa-vít, con trai mình, mang những thứ đó đến cho Sau-lơ.'),
(7617, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 16, 21, 'OT', 'Đa-vít đến cùng Sau-lơ, đứng trước mặt người; người yêu mến anh rất sâu sắc, và anh trở thành người mang khí giới cho người.'),
(7618, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 16, 22, 'OT', 'Và Sau-lơ sai đến gặp Y-sai, nói rằng: Xin Đa-vít đứng trước mặt tôi; vì người đã được ơn trước mặt tôi.'),
(7619, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 16, 23, 'OT', 'Khi Thần từ Đức Chúa Trời ngự trên Sau-lơ, thì Đa-vít sẽ cầm cây đờn cầm và gảy bằng tay mình; và Sau-lơ được giải thoát, cảm thấy dễ chịu, và thần dữ rời khỏi người.'),
(7620, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 1, 'OT', 'Các người Phi-li-tin nhóm các đạo quân lại để ra trận, và họ tập hợp tại Sô-kô thuộc xứ Giu-đa, rồi đóng trại giữa Sô-kô và A-ze-ka, tại Ê-phết-Đa-mim.'),
(7621, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 2, 'OT', 'Và Sa-un cùng những người Ít-ra-en đã tập hợp lại, và đóng trại trong thung lũng Ê-la, rồi bày binh bố trận đối đầu với người Phi-li-tin.'),
(7622, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 3, 'OT', 'Người Phi-li-tin đứng trên núi bên này, còn Y-sơ-ra-ên đứng trên núi bên kia; thung lũng nằm giữa hai bên.'),
(7623, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 4, 'OT', 'Một người lính từ trại quân của người Phi-li-tin đi ra, tên ông là Gô-li-át, người Gát; chiều cao của ông là sáu thước rưỡi.'),
(7624, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 5, 'OT', 'Và chiếc mũ bằng đồng trên đầu người ấy, và người ấy mặc áo giáp bằng những miếng khâu lại; và trọng lượng của áo giáp là năm ngàn sê-ken đồng.'),
(7625, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 6, 'OT', 'Và một cái mũ bằng đồng trên chân ông, và một ngọn lao bằng đồng đặt giữa hai vai ông.'),
(7626, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 7, 'OT', 'Và cán ngọn giáo của người như trục thoi dệt vải, còn lưỡi giáo nặng sáu trăm sê-ken bằng sắt; và có người mang khiên đi trước mặt người.'),
(7627, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 8, 'OT', 'Người ấy đứng lên, kêu lớn cùng các đạo quân Ít-ra-en và nói với họ: "Tại sao các ngươi ra đây để bày trận chiến? Chẳng phải ta đây là người Phi-li-tin, còn các ngươi là đầy tớ của Sau-lơ sao? Hãy chọn một người trong các ngươi, để người ấy xuống đây cùng ta."'),
(7628, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 9, 'OT', 'Nếu người ấy có thể ra đánh nhau với ta và giết ta, thì chúng ta sẽ làm tôi tớ cho các ngươi; nhưng nếu ta có thể thắng người ấy và giết người ấy, thì các ngươi sẽ làm tôi tớ cho chúng ta và phục vụ chúng ta.'),
(7629, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 10, 'OT', 'Người Phi-li-tin nói: Ta đã sỉ nhục các đạo quân của Y-sơ-ra-ên ngày nay; hãy đưa một người đến cho ta, để chúng ta chiến đấu cùng nhau.'),
(7630, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 11, 'OT', 'Khi Sa-un và toàn thể Ít-ra-en nghe những lời của người Phi-li-tin ấy, họ kinh hãi và rất sợ hãi.'),
(7631, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 12, 'OT', 'Đa-vít là con trai của một người Ê-phơ-ra-thít ở Bê-lem Giu-đa, tên người ấy là Ít-sai; người ấy có tám con trai. Trong đời vua Sau-lơ, người ấy đã già, tuổi tác cao cả.'),
(7632, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 13, 'OT', 'Ba người con trai lớn của Y-xai đi theo Sau-lơ ra trận, và tên của ba người con trai ấy đi ra trận là Ê-li-áp, con cả, người thứ hai là A-bi-na-đáp, và người thứ ba là Sam-ma.'),
(7633, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 14, 'OT', 'Đa-vít là người út; còn ba người anh cả thì đi theo Sau-lơ.'),
(7634, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 15, 'OT', 'Đa-vít đi và trở lại khỏi Sa-un để chăn chiên cho cha mình tại Bết-lê-hem.'),
(7635, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 16, 'OT', 'Người Phi-li-tin ấy tiến đến gần mỗi buổi sáng và chiều tối, và đứng đó bốn mươi ngày.'),
(7636, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 17, 'OT', 'Và Ích-sai nói với Đa-vít, con trai mình: "Hãy mang cho các anh ngươi một e-phah lúa rang này, và mười ổ bánh này, rồi chạy đến trại quân cho các anh ngươi."'),
(7637, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 18, 'OT', 'Và hãy mang mười phần pho mát này đến cho chỉ huy ngàn người, và hãy thăm các anh ngươi xem tình trạng họ ra sao, rồi nhận bằng chứng về sự an toàn của họ.'),
(7638, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 19, 'OT', 'Bây giờ Sau-lơ, các tôi trai người và mọi người đàn ông Ít-ra-en đều ở trong thung lũng Ê-la, đang chiến đấu với người Phi-li-tin.'),
(7639, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 20, 'OT', 'Đa-vít dậy sớm vào buổi sáng, giao các con chiên cho người giữ, rồi mang theo và đi như Ích-sai đã truyền dặn ông; ông đến nơi quân đội rút ra, trong khi đạo binh đang tiến ra trận địa và hò reo xung trận.'),
(7640, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 21, 'OT', 'Ít-ra-en và các Phi-li-tin đã sắp hàng đội ngũ đối nghịch nhau.'),
(7641, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 22, 'OT', 'Đa-vít để các đồ vật mình mang ra khỏi mình vào tay người giữ đồ vật, rồi chạy vào hàng ngũ, đến gần và hỏi thăm sức khỏe các anh em mình.'),
(7642, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 23, 'OT', 'Và khi người đang nói chuyện với họ, thì nầy, tên chiến sĩ là người Phi-li-tin ở Gát, tên là Gô-li-át, từ các đạo quân của người Phi-li-tin đi lên, và nói theo những lời ấy; và Đa-vít nghe thấy.'),
(7643, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 24, 'OT', 'Mọi người Ít-ra-en, khi thấy người đàn ông đó, đều chạy trốn khỏi mặt người ấy và rất sợ hãi.'),
(7644, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 25, 'OT', 'Các người Ít-ra-en nói: Các ngươi đã thấy người đàn ông đang tiến lên kia chưa? Hắn lên để sỉ nhục Ít-ra-en. Vậy, người nào giết được hắn, vua sẽ ban cho rất nhiều của cải, gả con gái mình cho người ấy, và miễn thuế cho gia đình cha của người ấy trong Ít-ra-en.'),
(7645, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 26, 'OT', 'Đa-vít nói với những người đứng bên cạnh mình: "Người nào giết được tên Phi-li-tin này và gỡ bỏ sự sỉ nhục khỏi Ít-ra-en sẽ được đối xử ra sao? Vì sao tên Phi-li-tin không chịu phép cắt bì này lại dám sỉ nhục các đạo quân của Đức Chúa Trời hằng sống?"'),
(7646, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 27, 'OT', 'Bấy giờ dân chúng đáp lại người ấy cùng một lời ấy, mà rằng: Người nào giết nó thì sẽ được đối xử như vậy.'),
(7647, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 28, 'OT', 'Ê-li-áp, anh cả của Đa-vít, nghe Đa-vít nói với những người ấy, thì cơn giận của Ê-li-áp nổi lên nghẹn lòng vì Đa-vít, và người nói: "Ngươi xuống đây để làm gì? Ngươi đã để những con chiên ít ỏi kia ở đồng vắng với ai vậy? Ta biết rõ sự kiêu căng của ngươi và lòng ác của ngươi; ngươi xuống đây chỉ để xem cuộc chiến thôi."'),
(7648, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 29, 'OT', 'Đa-vít nói: "Tôi vừa làm gì vậy? Chẳng phải chỉ là một lời nói thôi sao?"'),
(7649, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 30, 'OT', 'Rồi người ấy quay khỏi người này đến gặp một người khác và nói như lời đó; và dân chúng đáp lại người ấy như lời trước.'),
(7650, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 31, 'OT', 'Và người ta nghe những lời mà Đa-vít đã nói, bèn thuật lại cho Sau-lơ; và Sau-lơ sai người gọi người ấy đến.'),
(7651, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 32, 'OT', 'Đa-vít nói với Sau-lơ: "Đừng để lòng người nào sụp đổ vì hắn; tôi tớ của ngài sẽ đi và chiến đấu với tên Phi-li-tin này."'),
(7652, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 33, 'OT', 'Vua Sau-lơ nói với Đa-vít: "Ngươi không thể đi chống lại tên Phi-li-tin này để chiến đấu với hắn, vì ngươi chỉ là một thanh niên, còn hắn thì đã là một tay chiến binh từ khi còn trẻ."'),
(7653, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 34, 'OT', 'Đa-vít nói với Sau-lơ: "Tôi là kẻ tôi tớ của cha ngài, đã từng chăn chiên cho cha tôi; rồi một con sư tử và một con gấu đến, và cắn lấy một con chiên con từ trong bầy chiên."'),
(7654, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 35, 'OT', 'Tôi đã đuổi theo nó, đánh nó và cứu con vật khỏi miệng nó; khi nó vùng dậy chống tôi, tôi nắm lấy râu nó, đánh và giết nó.'),
(7655, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 36, 'OT', 'Tôi tớ ngài đã giết cả sư tử lẫn gấu, và tên Phi-li-tin không chịu cắt bì này cũng sẽ như một trong những con đó, vì hắn đã sỉ nhục các đạo quân của Đức Chúa Trời hằng sống.'),
(7656, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 37, 'OT', 'Đa-vít nói thêm: "Đức Giê-hô-va, Đấng đã giải cứu tôi khỏi tay sư tử và khỏi tay gấu, chính Ngài cũng sẽ giải cứu tôi khỏi tay tên Phi-li-tin này." Sau đó, Sau-lơ nói với Đa-vít: "Hãy đi, và Đức Giê-hô-va sẽ ở cùng ngươi."'),
(7657, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 38, 'OT', 'Sa-un mặc áo giáp của mình cho Đa-vít, đội mũ bằng đồng lên đầu người, và mặc áo giáp cho người.'),
(7658, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 39, 'OT', 'Đa-vít thắt gươm mình trên áo giáp, rồi thử đi; vì người chưa từng thử. Đa-vít nói với Sau-lơ: "Tôi không thể đi với những thứ này, vì tôi chưa thử chúng." Vậy Đa-vít cởi chúng khỏi mình.'),
(7659, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 40, 'OT', 'Người lấy cây gậy trong tay mình, chọn năm hòn đá nhẵn từ dòng suối, bỏ vào bị chăn chiên mình mang theo, và lấy cái ná trong tay, rồi tiến về phía tên Phi-li-tin.'),
(7660, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 41, 'OT', 'Người Phi-li-tin đi tới, đến gần Đa-vít; và người mang khiên đi trước mặt người đó.'),
(7661, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 42, 'OT', 'Khi người Phi-li-tin nhìn kỹ và thấy Đa-vít, thì khinh bỉ người, vì người là một thanh niên, da đỏ và có vẻ ngoài đẹp đẽ.'),
(7662, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 43, 'OT', 'Người Phi-li-tin nói với Đa-vít: "Ta có phải là một con chó sao mà ngươi đến cùng ta với những cây gậy?" Rồi người Phi-li-tin rủa Đa-vít bằng các thần của mình.'),
(7663, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 44, 'OT', 'Người Phi-li-tin nói với Đa-vít: "Hãy đến cùng ta, để ta nộp thịt ngươi cho các loài chim trên trời và các loài thú ngoài đồng."'),
(7664, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 45, 'OT', 'Đa-vít nói với người Phi-li-tin: "Ngươi đến cùng ta với gươm, với ngọn giáo và với ngọn lao; còn ta, ta đến cùng ngươi nhân danh Đức Giê-hô-va vạn quân, là Đức Chúa Trời của các đạo quân Y-sơ-ra-ên mà ngươi đã sỉ nhục."'),
(7665, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 46, 'OT', 'Ngày nay, Đức Giê-hô-va sẽ phó ngươi vào tay ta; ta sẽ đánh ngươi và cất đầu ngươi khỏi ngươi; và ngày nay ta sẽ phó xác quân đội của người Phi-li-tin cho chim trời và các loài thú đất, để cho cả đất biết rằng có Đức Chúa Trời cho Y-sơ-ra-ên.'),
(7666, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 47, 'OT', 'Và toàn thể hội chúng này sẽ biết rằng Đức Giê-hô-va không cứu bằng gươm và bằng giáo; vì chiến trận thuộc về Đức Giê-hô-va, và Ngài sẽ trao các ngươi vào tay chúng tôi.'),
(7667, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 48, 'OT', 'Khi tên Phi-li-tin đứng dậy, tiến lên và đến gần để đối mặt với Đa-vít, thì Đa-vít vội vàng chạy đến hàng ngũ để đối đầu với tên Phi-li-tin.'),
(7668, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 49, 'OT', 'Đa-vít đưa tay vào bị, lấy ra một hòn đá, ném trúng tên Phi-li-tin vào trán; hòn đá đâm sâu vào trán hắn, và hắn ngã sấp mặt xuống đất.'),
(7669, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 50, 'OT', 'Đa-vít đánh bại người Phi-li-tin bằng dây ná và hòn đá, đánh và giết người Phi-li-tin ấy; nhưng trong tay Đa-vít không có gươm.'),
(7670, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 51, 'OT', 'Đa-vít liền chạy đến, đứng trên người Phi-li-tin, lấy thanh gươm của hắn, rút ra khỏi bao, giết hắn và chặt đầu hắn bằng chính thanh gươm ấy. Khi thấy vị anh hùng của mình đã chết, người Phi-li-tin liền bỏ chạy.'),
(7671, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 52, 'OT', 'Dân Y-sơ-ra-ên và Giu-đa đứng dậy, hò reo, rồi đuổi theo người Phi-li-tin cho đến khi vào thung lũng và đến các cổng thành Éc-rôn. Những người Phi-li-tin bị giết ngã gục dọc đường đến Sê-a-ra-im, và cho đến Ga-th và Éc-rôn.'),
(7672, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 53, 'OT', 'Các con trai của Y-sơ-ra-ên trở về sau khi đuổi theo người Phi-li-tin, và họ cướp phá các trại của chúng.'),
(7673, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 54, 'OT', 'Đa-vít lấy đầu người Phi-li-tin, mang đến Giê-ru-sa-lem; còn khí giới của người thì ông cất trong lều mình.'),
(7674, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 55, 'OT', 'Khi Sa-un thấy Đa-vít đi ra nghênh chiến với người Phi-li-tin, ông nói với Áp-ne, tư lệnh đạo quân: "Này Áp-ne, đứa trẻ này là con trai ai vậy?" Áp-ne đáp: "Tính mạng của bệ hạ làm chứng, tôi không biết."'),
(7675, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 56, 'OT', 'Vua nói: "Hãy hỏi xem người trai trẻ này là con trai của ai?"'),
(7676, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 57, 'OT', 'Khi Đa-vít trở về sau khi đánh bại người Phi-li-tin, Áp-ne liền dẫn ông đi và đưa đến trước mặt Sau-lơ, đầu người Phi-li-tin còn trong tay ông.'),
(7677, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 17, 58, 'OT', 'Vua Sau-lơ nói với anh: "Ngươi là con trai ai, thanh niên?" Đa-vít đáp: "Tôi là con trai của đầy tớ ngài, Ít-ra, người Bết-lê-hem."'),
(7678, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 18, 1, 'OT', 'Sau khi cậu ấy nói xong với Sau-lơ, thì linh hồn của Giô-na-than liền gắn bó với linh hồn của Đa-vít, và Giô-na-than yêu cậu ấy như yêu linh hồn mình.'),
(7679, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 18, 2, 'OT', 'Và Sa-un giữ người đó lại ngay ngày ấy, không để người ấy trở về nhà cha mình nữa.'),
(7680, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 18, 3, 'OT', 'Vì yêu người như chính mạng sống mình, nên Giô-na-than và Đa-vít lập giao ước với nhau.'),
(7681, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 18, 4, 'OT', 'Giô-na-than cởi chiếc áo choàng mình đang mặc và trao cho Đa-vít, cùng với các đồ mặc khác của mình, cả gươm, cung và thắt lưng của người nữa.'),
(7682, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 18, 5, 'OT', 'Đa-vít ra đi bất cứ nơi nào Sau-lơ sai ông đi, và ông xử sự khôn ngoan; nên Sau-lơ đặt ông làm chỉ huy các người lính chiến. Ông được đẹp lòng trước mắt toàn thể dân chúng, và cả trước mắt các tôi tớ của Sau-lơ.'),
(7683, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 18, 6, 'OT', 'Khi họ trở về, trong lúc Đa-vít trở về sau khi đánh bại người Phi-li-tin, thì các phụ nữ từ mọi thành của Y-sơ-ra-ên đi ra, vừa gõ trống vừa nhảy múa để đón vua Sau-lơ, với trống nhỏ, sự vui mừng và sáo nhạc.'),
(7684, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 18, 7, 'OT', 'Các phụ nữ vừa múa vừa đáp: "Sa-un đã giết hàng ngàn, còn Đa-vít giết hàng vạn."'),
(7685, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 18, 8, 'OT', 'Sa-un rất tức giận, và điều ấy làm cho ông khó chịu trong mắt mình; ông nói: "Họ đã ban cho Đa-vít hàng vạn, còn cho tôi chỉ hàng ngàn; ngoài ra, người ấy còn thiếu điều gì nữa nếu không phải là vương quốc?"'),
(7686, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 18, 9, 'OT', 'Từ ngày ấy trở đi, Sa-un bắt đầu để bụng thù ghét Đa-vít.'),
(7687, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 18, 10, 'OT', 'Ngày hôm sau, thần dữ từ Đức Chúa Trời ngự trên Sa-un, và người nói tiên tri giữa trong nhà; còn Đa-vít thì gảy đàn như mọi ngày; và ngọn giáo đang ở trong tay Sa-un.'),
(7688, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 18, 11, 'OT', 'Sa-un ném ngọn giáo, nói rằng: "Ta sẽ đâm Đa-vít và đâm luôn vào tường." Nhưng Đa-vít tránh khỏi mặt người hai lần.'),
(7689, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 18, 12, 'OT', 'Và Sau-lơ sợ Đa-vít, vì Đức Giê-hô-va ở cùng Đa-vít, nhưng đã lìa khỏi Sau-lơ.'),
(7690, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 18, 13, 'OT', 'Vì thế, Sa-un cách ly người khỏi mình và bổ nhiệm người làm chỉ huy một ngàn quân; người ra vào trước mặt dân sự.'),
(7691, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 18, 14, 'OT', 'Và Đa-vít xử sự khôn ngoan trong mọi đường lối của mình; và Đức Giê-hô-va ở cùng người.'),
(7692, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 18, 15, 'OT', 'Sa-un thấy Đa-vít xử sự rất khôn ngoan, thì sợ hãi trước mặt người.'),
(7693, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 18, 16, 'OT', 'Và toàn thể Y-sơ-ra-ên và Giu-đa đều yêu mến Đa-vít, vì chính ông ra vào trước mặt họ.'),
(7694, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 18, 17, 'OT', 'Sa-un nói với Đa-vít: "Này, con gái lớn của ta là Mê-ráp, ta sẽ gả nó cho ngươi làm vợ; chỉ cần ngươi phải làm một người chiến sĩ dũng cảm cho ta và chiến đấu các trận chiến của Đức Giê-hô-va." Nhưng thật ra, Sa-un nghĩ: "Đừng để tay ta đánh nó, mà hãy để tay người Phi-li-tin đánh nó."'),
(7695, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 18, 18, 'OT', 'Đa-vít nói với Sau-lơ: "Tôi là ai, và gia đình cha tôi là ai trong Ít-ra-en, mà tôi đáng trở thành con rể của vua?"'),
(7696, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 18, 19, 'OT', 'Nhưng xảy ra vào thời điểm Mê-ráp, con gái của Sau-lơ, phải được gả cho Đa-vít, thì nàng lại được gả cho A-đri-ên, người Mê-hô-la, làm vợ.'),
(7697, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 18, 20, 'OT', 'Mical, con gái của Sau-lơ, yêu Đa-vít; người ta báo cho Sau-lơ biết, và điều đó làm ông hài lòng.'),
(7698, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 18, 21, 'OT', 'Sa-un nói: "Ta sẽ gả nàng cho hắn, để nàng trở thành cái bẫy cho hắn, và tay dân Phi-li-tin sẽ nghịch lại hắn." Vậy nên, Sa-un nói với Đa-vít: "Hôm nay ngươi sẽ làm con rể ta bằng một trong hai người con gái ta."'),
(7699, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 18, 22, 'OT', 'Vua Sau-lơ ra lệnh cho các tôi tớ mình nói chuyện riêng với Đa-vít và bảo: "Nầy, vua rất yêu mến ngươi, và tất cả các tôi tớ của người đều yêu mến ngươi; vậy bây giờ, hãy làm con rể của vua."'),
(7700, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 18, 23, 'OT', 'Các tôi tớ của Sau-lơ thuật những lời ấy cho Đa-vít nghe. Đa-vít đáp: "Theo các anh thì việc kết hôn với vua có vẻ nhẹ không? Tôi là một người nghèo khó và hèn mọn."'),
(7701, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 18, 24, 'OT', 'Các tôi tớ của Sau-lơ thuật lại cho ông, rằng: "Đa-vít đã nói như thế này."'),
(7702, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 18, 25, 'OT', 'Và Sau-lơ nói: "Hãy nói với Đa-vít như thế này: Đức vua không muốn một thứ tiền cưới nào khác, chỉ cần một trăm cái bìu của người Phi-li-tin, để báo thù cho các kẻ thù của đức vua." Nhưng thật ra, Sau-lơ nghĩ đến việc khiến Đa-vít bị giết bởi tay người Phi-li-tin.'),
(7703, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 18, 26, 'OT', 'Khi các tôi tớ thuật lại cho Đa-vít những lời ấy, thì điều đó vừa lòng Đa-vít, vì anh muốn trở thành con rể của vua; và những ngày ấy chưa trọn.'),
(7704, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 18, 27, 'OT', 'Đa-vít chỗi dậy và đi cùng các người của mình, đánh giết hai trăm người Phi-li-tin; rồi Đa-vít mang những bức bì của chúng đến, nộp đầy đủ cho vua, để trở thành con rể của vua. Sau đó, Sau-lơ đã gả Mi-ca, con gái mình, cho người làm vợ.'),
(7705, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 18, 28, 'OT', 'Sa-un thấy vậy và biết rằng Đức Giê-hô-va ở cùng Đa-vít, và Mích-an, con gái của Sa-un, yêu người.'),
(7706, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 18, 29, 'OT', 'Sa-un lại càng thêm sợ Đa-vít, và Sau-lơ trở thành kẻ thù của Đa-vít trọn mọi ngày.'),
(7707, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 18, 30, 'OT', 'Các quan trưởng người Phi-li-tin ra đi, và xảy ra sau khi họ ra đi, Đa-vít xử sự khôn ngoan hơn tất cả các tôi tớ của Sau-lơ, nên danh tiếng người được rất trọng vọng.'),
(7708, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 19, 1, 'OT', 'Sa-un nói với Giô-na-than, con trai mình, và với tất cả các đầy tớ mình, rằng họ phải giết Đa-vít; nhưng Giô-na-than, con trai của Sau-lơ, lại rất quý mến Đa-vít.'),
(7709, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 19, 2, 'OT', 'Giô-na-than nói với Đa-vít rằng: "Cha tôi là Sau-ôn tìm cách giết ông. Vì vậy, bây giờ xin ông hãy coi chừng, hãy ở lại nơi ẩn khuất và trốn đi."'),
(7710, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 19, 3, 'OT', 'Tôi sẽ đi ra đứng bên cạnh cha tôi trong đồng nơi ngươi đang ở, và tôi sẽ nói với cha tôi về ngươi; điều gì tôi thấy, tôi sẽ báo cho ngươi biết.'),
(7711, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 19, 4, 'OT', 'Và Giô-na-than nói tốt về Đa-vít với Sau-lơ, cha mình, và nói với người rằng: "Xin vua chớ phạm tội cùng tôi tớ của vua là Đa-vít, vì người chẳng phạm tội cùng vua, và các việc người làm thật rất tốt cho vua."'),
(7712, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 19, 5, 'OT', 'Người đã liều mạng mình, đánh bại người Phi-li-tin, và Đức Giê-hô-va đã thực hiện một sự cứu rỗi lớn cho toàn thể Y-sơ-ra-ên; ông đã thấy điều đó và vui mừng. Vậy tại sao ông lại phạm tội nghịch cùng huyết vô tội, bằng cách giết Đa-vít cách vô cớ?'),
(7713, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 19, 6, 'OT', 'Sa-un nghe theo tiếng nói của Giô-na-than, và Sa-un thề rằng: "Nhân danh Đức Giê-hô-va hằng sống, hắn sẽ không bị giết."'),
(7714, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 19, 7, 'OT', 'Giô-na-than gọi Đa-vít, rồi Giô-na-than thuật lại cho Đa-vít mọi điều ấy; sau đó, Giô-na-than dẫn Đa-vít đến cùng Sau-lơ, và người ở trước mặt ông như những ngày trước đây.'),
(7715, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 19, 8, 'OT', 'Và chiến tranh lại tiếp tục xảy ra; Đa-vít ra đi và chiến đấu với người Phi-li-tin, đánh bại họ một trận lớn, và chúng chạy trốn khỏi mặt ông.'),
(7716, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 19, 9, 'OT', 'Và thần dữ từ Đức Giê-hô-va giáng trên Sau-lơ, khi người đang ngồi trong nhà, với ngọn giáo trong tay; còn Đa-vít thì đang gảy đàn bằng tay mình.'),
(7717, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 19, 10, 'OT', 'Sa-un tìm cách dùng ngọn giáo đâm trúng Đa-vít, ép vào tường; nhưng Đa-vít tránh khỏi mặt Sa-un, và ngọn giáo cắm sâu vào tường. Đa-vít bèn trốn thoát và chạy trốn trong đêm đó.'),
(7718, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 19, 11, 'OT', 'Sa-mu-ên sai các sứ giả đến nhà Đa-vít để canh giữ và giết ông vào buổi sáng; nhưng Mi-kal, vợ của Đa-vít, báo cho ông biết, nói rằng: "Nếu đêm nay ngươi không trốn thoát để cứu mạng mình, ngày mai ngươi sẽ bị giết."'),
(7719, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 19, 12, 'OT', 'Mi-cha cho Đa-vít xuống qua cửa sổ; rồi người đi, chạy trốn và thoát khỏi nguy hiểm.'),
(7720, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 19, 13, 'OT', 'Mi-ka lấy tượng thần đặt lên giường, lấy cái gối bằng lông dê đặt dưới đầu, rồi phủ kín bằng tấm vải.'),
(7721, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 19, 14, 'OT', 'Sau-lơ sai các sứ giả đi bắt Đa-vít, thì nàng nói: "Người đang đau ốm."'),
(7722, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 19, 15, 'OT', 'Sa-un sai các sứ giả đi do thám Đa-vít, dặn rằng: "Hãy bắt anh ấy cùng với cái giường mà khiêng đến cho ta, để ta giết anh ấy."'),
(7723, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 19, 16, 'OT', 'Các sứ giả đi vào, và này, tượng hình nằm trên giường, và đầu nó được phủ bằng một cái gối bằng lông dê.'),
(7724, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 19, 17, 'OT', 'Sau-lơ nói với Mi-kal: "Tại sao con đã lừa cha như thế này, để kẻ thù của cha trốn thoát?" Mi-kal đáp lại Sau-lơ: "Chính người nói với con: ''Hãy để tôi đi; tại sao con phải giết tôi?''"'),
(7725, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 19, 18, 'OT', 'Đa-vít trốn chạy và được cứu thoát, rồi đến cùng Sa-mu-ên tại Ra-ma và thuật cho ông biết mọi điều Sau-lơ đã làm cho mình. Sau đó, ông và Sa-mu-ên đi ra và ở tại Na-i-ốt.'),
(7726, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 19, 19, 'OT', 'Và người ta báo cho Sau-lơ rằng: Nầy, Đa-vít đang ở Na-i-ốt tại Ra-ma.'),
(7727, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 19, 20, 'OT', 'Sa-un sai các sứ giả đi bắt Đa-vít; khi họ thấy nhóm các nhà tiên tri đang nói tiên tri, và Sa-mu-ên đứng lãnh đạo họ, thì Đức Chúa Trời đặt thần trên các sứ giả của Sa-un, và họ cũng nói tiên tri.'),
(7728, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 19, 21, 'OT', 'Khi người ta thuật lại cho Sau-lơ, ông sai các sứ giả khác đi, và họ cũng nói tiên tri. Sau-lơ lại sai các sứ giả lần thứ ba, và họ cũng nói tiên tri.'),
(7729, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 19, 22, 'OT', 'Sau đó, ông cũng đi đến Ra-ma, và đến một cái giếng lớn ở Sê-chu. Ông hỏi và nói: "Sa-mu-ên và Đa-vít ở đâu?" Người ta đáp: "Nầy, họ đang ở Na-i-ốt tại Ra-ma."'),
(7730, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 19, 23, 'OT', 'Và người đi đến Na-i-ốt tại Ra-mah; và Thần của Đức Chúa Trời cũng ngự trên người, khiến người cứ đi và nói tiên tri cho đến khi đến nơi Na-i-ốt tại Ra-mah.'),
(7731, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 19, 24, 'OT', 'Và chính hắn cũng cởi bỏ áo quần mình, rồi cũng nói tiên tri trước mặt Sa-mu-ên, và nằm trần truồng suốt ngày ấy và cả đêm đó. Bởi vậy người ta nói: "Sao-nhưng cũng ở giữa các đấng tiên tri sao?"'),
(7732, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 1, 'OT', 'Đa-vít chạy trốn từ Na-i-ốt tại Ra-mah, rồi đến gặp Giô-na-than và nói: "Tôi đã làm gì? Tôi có tội gì? Tôi phạm tội gì trước mặt cha ngươi, mà ông ấy lại tìm mạng sống tôi?"'),
(7733, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 2, 'OT', 'Hắn nói với người đó: "Chớ nói vậy! Chắc chắn ngươi sẽ không chết. Nầy, khi cha ta làm điều gì, dù lớn hay nhỏ, thì chẳng bao giờ ông giấu tai ta. Vậy tại sao cha ta lại giấu ta điều này? Không thể nào!"'),
(7734, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 3, 'OT', 'Đa-vít thề một lần nữa và nói: "Cha ngươi hẳn biết rõ rằng tôi đã được ơn trước mặt ngươi, nên ông nói: ''Đừng để cho Giô-na-than biết chuyện này, kẻo nó buồn.'' Nhưng Đức Giê-hô-va hằng sống, và linh hồn ngươi cũng hằng sống, thật sự chỉ còn cách tôi với cái chết một bước mà thôi."'),
(7735, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 4, 'OT', 'Giô-na-than nói với Đa-vít: "Hãy nói cho tôi biết điều gì lòng anh mong muốn, tôi sẽ làm cho anh."'),
(7736, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 5, 'OT', 'Đa-vít nói với Giô-na-than: "Này, ngày mai là lễ trăng mới, và tôi phải ngồi ăn với vua; nhưng xin hãy để tôi đi, để tôi ẩn mình trong đồng cho đến chiều ngày thứ ba."'),
(7737, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 6, 'OT', 'Nếu cha ngươi có tìm kiếm ta, hãy nói: Đa-vít đã khẩn xin tôi cho người chạy về Bê-lem, thành của người, vì tại đó có lễ tế hằng năm cho cả gia đình người.'),
(7738, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 7, 'OT', 'Nếu người ấy nói: "Tốt lắm, bình an cho đầy tớ ta," thì ngươi hãy biết rằng ngươi được bình an; nhưng nếu người ấy nổi giận dữ dội, hãy biết rằng mọi điều ác đã được quyết định từ phía người ấy.'),
(7739, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 8, 'OT', 'Vậy hãy làm ơn cho đầy tớ của ngài, vì ngài đã đem đầy tớ của ngài vào giao ước của Đức Giê-hô-va với ngài; nhưng nếu trong tôi có tội ác, chính ngài hãy giết tôi đi, chứ đừng dẫn tôi về gặp cha ngài.'),
(7740, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 9, 'OT', 'Giô-na-than nói: Xin đừng như vậy! Vì nếu tôi biết chắc rằng điều ác do cha tôi định làm sẽ giáng trên anh, thì tôi đã không giấu anh.'),
(7741, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 10, 'OT', 'Đa-vít nói với Giô-na-than: Ai sẽ cho tôi biết? Hoặc nếu cha ngươi trả lời ngươi cách nghiêm khắc thì sao?'),
(7742, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 11, 'OT', 'Và Y-hô-nát nói với Đa-vít: "Hãy đi, chúng ta ra đồng." Và cả hai người ra đồng.'),
(7743, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 12, 'OT', 'Và Giô-na-than nói với Đa-vít: "Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en chứng giám: ngày mai, vào buổi chiều thứ ba, tôi sẽ dò ý cha tôi; nếu thấy điều tốt dành cho Đa-vít, mà tôi không sai người báo cho ông biết, thì xin Đức Giê-hô-va xử phạt tôi."'),
(7744, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 13, 'OT', 'Nguyện Đức Giê-hô-va xử với Giô-na-than và nhân thêm cho, nếu cha tôi định làm điều ác cùng ngươi, thì tôi sẽ tiết lộ cho ngươi biết, và cho ngươi đi, để ngươi đi bình an; và nguyện Đức Giê-hô-va ở cùng ngươi, như Ngài đã ở cùng cha tôi.'),
(7745, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 14, 'OT', 'Ngươi chớ những tỏ lòng nhân từ của Đức Giê-hô-va cùng ta đương khi ta còn sống mà thôi, kẻo ta chết chăng,'),
(7746, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 15, 'OT', 'Và chớ rút lui sự nhân từ của ngươi khỏi nhà ta đời đời; và chớ khi Đức Giê-hô-va diệt sạch từng người một các kẻ thù của Đa-vít khỏi mặt đất.'),
(7747, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 16, 'OT', 'Vậy Giô-na-than lập giao ước với nhà Đa-vít, và Đức Giê-hô-va sẽ đòi lại từ tay những kẻ thù của Đa-vít.'),
(7748, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 17, 'OT', 'Và Y-hô-nát làm Đa-vít thề lần nữa, vì Y-hô-nát yêu người; bởi người yêu Đa-vít như yêu chính mạng sống mình.'),
(7749, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 18, 'OT', 'Bấy giờ Giô-na-than nói với Đa-vít: "Ngày mai là ngày trăng mới, và ngươi sẽ bị thiếu vắng, vì chỗ ngồi của ngươi sẽ trống không."'),
(7750, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 19, 'OT', 'Ngươi sẽ ở lại đó ba ngày, rồi mau xuống nơi ngươi đã ẩn thân khi sự việc xảy ra, và ngồi gần hòn đá kia.'),
(7751, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 20, 'OT', 'Còn tôi, tôi sẽ bắn ba mũi tên về phía bên cạnh, như thể bắn vào mục tiêu.'),
(7752, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 21, 'OT', 'Nầy, ta sẽ sai đứa trẻ đi với lời dặn: "Đi tìm các mũi tên." Nếu ta nói rõ với đứa trẻ: "Nầy, các mũi tên ở gần bên ngươi, hãy lấy đi," thì ngươi hãy đến, vì ngươi được an toàn, không có gì nguy hại; Đức Giê-hô-va hằng sống.'),
(7753, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 22, 'OT', 'Và nếu tôi nói với người thanh niên như thế này: Kìa, những mũi tên ở phía bên kia ngươi; hãy đi đi, vì Đức Giê-hô-va đã sai ngươi đi.'),
(7754, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 23, 'OT', 'Về điều mà anh và tôi đã nói, nầy, Đức Giê-hô-va sẽ làm chứng giữa tôi và anh đến đời đời.'),
(7755, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 24, 'OT', 'Đa-vít liền ẩn mình ngoài đồng. Khi rằm đến, vua ngồi xuống ăn bữa ăn.'),
(7756, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 25, 'OT', 'Vua ngồi trên ngôi mình như mọi khi, tức là trên một cái ghế gần tường; Giô-na-than đứng dậy, Áp-ne ngồi bên cạnh Sau-lơ, còn chỗ của Đa-vít thì trống.'),
(7757, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 26, 'OT', 'Đức Sa-un không nói điều gì trong ngày đó, vì người nghĩ: "Chắc có điều gì xảy ra; người ấy không tinh sạch, thật là không tinh sạch."'),
(7758, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 27, 'OT', 'Ngày hôm sau, là ngày thứ hai của tháng, chỗ của Đa-vít bị trống; và Sau-lơ nói với Giô-na-than, con trai mình: "Tại sao con trai của Y-sai không đến ăn bữa ăn, cả hôm qua lẫn hôm nay?"'),
(7759, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 28, 'OT', 'Và Giô-na-than đáp với Sau-lơ: "Đa-vít đã khẩn xin tôi cho đi đến Bết-lê-hem":'),
(7760, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 29, 'OT', 'Xin hãy để tôi đi, vì gia đình chúng tôi có lễ tế tổ chức tại thành phố, và anh tôi đã truyền lệnh cho tôi phải có mặt; vậy bây giờ, nếu tôi được ơn trước mặt ngài, xin cho tôi trốn đi và gặp các anh em tôi. Vì cớ đó tôi không đến dự bàn tiệc của vua.'),
(7761, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 30, 'OT', 'Sau-lơ nổi giận cùng Giô-na-than, và nói với người rằng: "Hỡi con trai của người đàn bà gian ác, há chẳng phải ta biết ngươi đã chọn con trai của Ích-sai, khiến ngươi bị sỉ nhục và làm sỉ nhục sự trần truồng của mẹ ngươi sao?"'),
(7762, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 31, 'OT', 'Vì chừng nào con trai của Y-sai còn sống trên đất, ngươi và vương quốc ngươi sẽ không được vững. Vậy bây giờ hãy đi, bắt nó đến cùng ta, vì nó là kẻ đáng chết.'),
(7763, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 32, 'OT', 'Giô-na-than đáp lại Sau-lơ, cha mình, và nói với người: "Tại sao người ấy phải chết? Người đã làm gì vậy?"'),
(7764, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 33, 'OT', 'Sa-un ném ngọn giáo nhằm giết Đa-vít; và Giô-na-than nhận biết rằng cha mình đã quyết tâm giết Đa-vít.'),
(7765, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 34, 'OT', 'Vậy Giô-na-than đứng dậy khỏi bàn ăn trong cơn giận dữ, và không ăn bánh trong ngày thứ hai của tháng, vì lòng buồn bã cho Đa-vít, bởi cha người đã làm cho Đa-vít phải nhục nhã.'),
(7766, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 35, 'OT', 'Sáng hôm ấy, Giô-na-than ra đồng đến giờ hẹn cùng Đa-vít, và một đứa bé đi theo ông.'),
(7767, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 36, 'OT', 'Bấy giờ người nói với người đầy tớ mình: "Hãy chạy đi, tìm ngay những mũi tên mà ta bắn đi." Người đầy tớ liền chạy, và chính người đó bắn một mũi tên vượt qua người đầy tớ.'),
(7768, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 37, 'OT', 'Đứa trẻ đi đến chỗ mũi tên đã bắn trúng, tức nơi Giô-na-than bắn trúng; rồi Giô-na-than gọi theo sau đứa trẻ và nói: "Mũi tên chẳng phải ở phía bên kia ngươi sao?"'),
(7769, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 38, 'OT', 'Và Giô-na-than gọi theo người đầy tớ, "Nhanh lên, vội vàng lên, đừng đứng lại." Người đầy tớ của Giô-na-than nhặt những mũi tên và trở về với chủ mình.'),
(7770, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 39, 'OT', 'Cậu bé chẳng biết điều gì cả; chỉ có Giô-na-than và Đa-vít biết điều đó.'),
(7771, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 40, 'OT', 'Và Giô-na-than trao các đồ dùng của mình cho người đầy tớ đi theo mình, rồi nói với anh ta: "Hãy đi, mang vào thành."'),
(7772, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 41, 'OT', 'Người đầy tớ vừa đi khuất, Đa-vít liền đứng dậy từ phía nam, sấp mặt xuống đất, cúi lạy ba lần; rồi cả hai ôm hôn nhau và khóc òa lên cùng nhau, đến nỗi Đa-vít khóc thảm thiết.'),
(7773, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 20, 42, 'OT', 'Và Giô-na-than nói với Đa-vít: "Hãy đi bình an," vì chúng ta đã chỉ Đức Giê-hô-va mà thề rằng: "Đức Giê-hô-va sẽ ở giữa tôi và anh, giữa dòng dõi tôi và dòng dõi anh đến mãi mãi." Rồi người đứng dậy và đi; còn Giô-na-than thì vào thành.'),
(7774, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 21, 1, 'OT', 'Đa-vít đến Nôp gặp A-hi-mê-léc, thầy tế lễ. A-hi-mê-léc run sợ khi gặp Đa-vít, và nói với ông: "Tại sao ông lại một mình, chẳng có ai đi cùng ông?"'),
(7775, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 21, 2, 'OT', 'Đa-vít nói với thầy tế lễ A-hi-mê-léc: "Vua đã giao cho tôi một việc, và nói với tôi: ''Chớ để một người nào biết điều gì về việc mà tôi sai ông đi và điều mà tôi truyền cho ông.'' Tôi đã chỉ định các đầy tớ tôi đến một nơi nào đó."'),
(7776, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 21, 3, 'OT', 'Bây giờ, dưới tay anh có gì? Hãy đưa cho tôi năm ổ bánh trong tay tôi, hoặc bất cứ thứ gì tìm được.'),
(7777, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 21, 4, 'OT', 'Đức thầy tế lễ đáp lời Đa-vít và nói: "Không có bánh thường nào nơi tay tôi, chỉ có bánh thánh thôi; nếu các thanh niên đã giữ mình khỏi phụ nữ."'),
(7778, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 21, 5, 'OT', 'Đa-vít đáp lời thầy tế lễ và nói với người: "Thật vậy, đàn bà đã cách ly khỏi chúng tôi khoảng ba ngày nay, kể từ khi tôi ra đi; đồ dùng của các thanh niên đã được biệt riêng làm thánh, và đây là con đường thường ngày; hơn nữa, ngay hôm nay đồ dùng ấy cũng sẽ được biệt riêng thánh."'),
(7779, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 21, 6, 'OT', 'Vị thầy tế lễ đưa cho ông bánh thánh, vì ở đó không có bánh nào khác ngoài bánh sự hiện ra, là những ổ bánh được lấy ra từ trước mặt Đức Giê-hô-va để thay bằng bánh nóng vào ngày chúng được thay thế.'),
(7780, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 21, 7, 'OT', 'Và tại đó, một người trong các đầy tớ của Sau-lơ đang ở đó trong ngày ấy, bị giữ lại trước mặt Đức Giê-hô-va; tên người ấy là Đô-ê-gh, người Ê-đôm, chỉ huy các người chăn chiên thuộc về Sau-lơ.'),
(7781, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 21, 8, 'OT', 'Đa-vít nói với A-hi-mê-léc: "Ở đây dưới tay ông, chẳng có ngọn giáo hay thanh gươm nào sao? Vì cả gươm lẫn khí giới của tôi đều không mang theo, do công việc của vua đòi hỏi phải vội vàng."'),
(7782, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 21, 9, 'OT', 'Vị thầy tế lễ nói: "Gươm của Gô-li-át người Phi-li-tin mà ngươi đã giết trong thung lũng Ê-la, nầy, nó được cuộn trong áo choàng, đằng sau áo thầy tế lễ; nếu ngươi muốn lấy nó, hãy lấy đi, vì ở đây không có gì khác ngoài nó." Đa-vít đáp: "Không có gì giống như nó; hãy đưa nó cho tôi."'),
(7783, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 21, 10, 'OT', 'Đa-vít đứng dậy, trốn chạy trong ngày ấy khỏi mặt Sau-lơ, và đến cùng A-kích, vua của Gát.'),
(7784, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 21, 11, 'OT', 'Các tôi tớ của A-kích nói với người rằng: "Chẳng phải đây là Đa-vít, vua của đất nước sao? Há chẳng phải về người mà họ nhảy múa hát rằng: Sa-un giết hàng ngàn, còn Đa-vít giết hàng vạn sao?"'),
(7785, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 21, 12, 'OT', 'Đa-vít đặt những lời nầy vào lòng mình, và rất sợ A-kích, vua Gát.'),
(7786, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 21, 13, 'OT', 'Và ông làm thay đổi cách ăn nói của mình trước mặt họ, giả vờ điên loạn trong tay họ, gãi cào trên các cánh cửa thành, và nước dãi chảy xuống râu ông.'),
(7787, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 21, 14, 'OT', 'A-kích nói với các tôi tớ mình: "Này, các ngươi thấy người đàn ông điên khùng rồi; tại sao các ngươi lại mang anh ta đến ta?"'),
(7788, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 21, 15, 'OT', 'Ta có thiếu những kẻ điên rồ sao mà các ngươi đem người này đến để làm trò điên rồ trước mặt ta? Kẻ này há sẽ được vào nhà ta sao?'),
(7789, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 22, 1, 'OT', 'Đa-vít rời khỏi nơi đó và trốn đến hang A-đu-lam. Khi các anh em của ông và toàn thể nhà của cha ông nghe được điều này, họ liền xuống gặp ông ở đó.'),
(7790, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 22, 2, 'OT', 'Mọi người đang gặp hoạn nạn, mọi người đang mang nợ nần, và mọi người có lòng cay đắng khốn khổ, đều nhóm lại cùng người ấy; và người ấy làm lãnh tụ dẫn dắt họ, và có khoảng bốn trăm người ở cùng người ấy.'),
(7791, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 22, 3, 'OT', 'Đa-vít đi từ nơi đó đến Mít-pei của Mô-áp, và nói với vua Mô-áp: "Xin hãy để cha tôi và mẹ tôi đến ở cùng ngài, cho đến khi tôi biết Đức Chúa Trời sẽ làm gì cho tôi."'),
(7792, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 22, 4, 'OT', 'Rồi ông dẫn họ đến diện kiến vua xứ Mô-áp, và họ ở cùng vua ấy suốt mọi ngày Đa-vít còn ở trong nơi ẩn náu.'),
(7793, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 22, 5, 'OT', 'Bấy giờ, Gát, nhà tiên tri, nói với Đa-vít: "Đừng ở lại trong đồn bảo vệ; hãy đi và đến đất Giu-đa." Vậy Đa-vít đi và đến rừng Ha-rết.'),
(7794, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 22, 6, 'OT', 'Khi Sa-un nghe tin Đa-vít đã bị lộ diện cùng những người đi với ông, thì Sa-un đang ngồi ở Ghíp-thê, dưới gốc cây sồi ở Ra-ma, với ngọn giáo trong tay, và tất cả các đầy tớ người đứng chung quanh người.'),
(7795, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 22, 7, 'OT', 'Sa-un nói với các đầy tớ mình đang đứng chung quanh: "Hãy nghe đây, hỡi các người thuộc chi phái Bên-gia-min! Liệu con trai của Y-sai có ban cho mỗi người các ngươi ruộng đất và vườn nho, và đặt các ngươi làm các quan chỉ huy ngàn người và quan chỉ huy trăm người chăng?"'),
(7796, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 22, 8, 'OT', 'Vì tất cả các ngươi đã cấu kết chống lại ta, và không ai tiết lộ cho ta biết việc con trai ta kết minh với con trai của Y-sai; không ai trong các ngươi thương xót ta, hay tiết lộ cho ta biết rằng con trai ta đã xúi giục đầy tớ ta chống lại ta để rình rập, như điều xảy ra hôm nay?'),
(7797, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 22, 9, 'OT', 'Bấy giờ Do-eg người Ê-đôm, đang đứng giữa các đầy tớ của Sau-lơ, thưa rằng: Tôi thấy con trai của Y-sai đến Nô-bơ, gặp A-hi-mê-léc, con trai A-hi-túp.'),
(7798, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 22, 10, 'OT', 'Người đã cầu hỏi Đức Giê-hô-va cho ông, và cấp lương thực cho ông, và trao cho ông thanh gươm của Gô-li-át người Phi-li-tin.'),
(7799, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 22, 11, 'OT', 'Vua sai gọi thầy tế lễ A-hi-mê-léc, con trai A-hi-túp, và toàn thể nhà cha người, tức các thầy tế lễ ở Nôp; và tất cả họ đều đến cùng vua.'),
(7800, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 22, 12, 'OT', 'Sau-lơ nói: Hãy nghe đây, hỡi con trai A-hi-túp. Người đáp: Này tôi đây, chúa tôi.'),
(7801, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 22, 13, 'OT', 'Vua Sa-un nói với ông: "Tại sao ngươi và con trai của Y-sai lại cấu kết chống nghịch ta, khi ngươi đã cấp cho nó bánh và gươm, lại còn hỏi ý Đức Chúa Trời cho nó, để nó nổi dậy nghịch lại ta và rình rập như ngày nay vậy?"'),
(7802, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 22, 14, 'OT', 'A-hi-mê-léc đáp vua và nói: "Trong tất cả các tôi tớ ngài, ai trung tín bằng Đa-vít, là con rể của vua, người thường ra vào theo lệnh vua, và được tôn trọng trong nhà ngài?"'),
(7803, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 22, 15, 'OT', 'Ngày nay tôi mới bắt đầu cầu hỏi Đức Chúa Trời cho người đó sao? Đức Giê-hô-va giữ tôi khỏi điều đó! Xin đừng để cho vua quy điều gì cho tôi là kẻ tôi tớ, hay cho cả nhà cha tôi; vì tôi là kẻ tôi tớ chẳng biết gì về chuyện này, dù điều nhỏ hay điều lớn.'),
(7804, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 22, 16, 'OT', 'Vua nói: "Ngươi chắc chắn phải chết, A-hi-mê-léc, ngươi và cả nhà của cha ngươi."'),
(7805, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 22, 17, 'OT', 'Vua nói với những người hầu cận đứng quanh mình: "Hãy quay lại và giết các thầy tế lễ của Đức Giê-hô-va, vì tay các ông ấy cũng ủng hộ Đa-vít, và họ biết khi người ấy trốn đi mà không tiết lộ cho ta." Nhưng các đầy tớ của vua không chịu giơ tay ra để ra tay hại các thầy tế lễ của Đức Giê-hô-va.'),
(7806, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 22, 18, 'OT', 'Vua nói với Đô-ích người Ê-đôm: "Hãy quay lại và tấn công các thầy tế lễ." Bấy giờ Đô-ích người Ê-đôm quay lại, tấn công các thầy tế lễ và giết trong ngày ấy tám mươi lăm người, tất cả đều là những người mang áo e-phót bằng vải gai mịn.'),
(7807, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 22, 19, 'OT', 'Và thành Nôp, thành của các thầy tế lễ, người ra tay giết bằng lưỡi gươm, từ người nam đến người nữ, từ trẻ sơ sinh đến con bú, và từ bò, lừa, chiên cũng bị giết bằng lưỡi gươm.'),
(7808, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 22, 20, 'OT', 'Một người con trai của A-hi-mê-léc, con trai A-hi-túp, tên là A-bi-át-ta, trốn thoát và chạy theo Đa-vít.'),
(7809, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 22, 21, 'OT', 'A-vi-át báo cho Đa-vít biết rằng Sau-lơ đã giết các thầy tế lễ của Đức Giê-hô-va.'),
(7810, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 22, 22, 'OT', 'Đa-vít nói với A-bi-át-tha: "Tôi biết ngày hôm đó, khi Do-êc người Ê-đôm ở đó, rằng hắn sẽ chắc chắn báo tin cho Sau-lơ; chính tôi đã gây ra cái chết của mọi người trong nhà cha ngươi."'),
(7811, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 22, 23, 'OT', 'Hãy ở lại cùng ta, đừng sợ; vì người nào tìm mạng sống ta sẽ tìm mạng sống ngươi; bởi ngươi là người được bảo vệ cùng ta.'),
(7812, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 23, 1, 'OT', 'Họ báo cho Đa-vít rằng: Kìa, người Phi-li-tin đang giao chiến tại Kê-ila và cướp lấy các sân đập lúa.'),
(7813, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 23, 2, 'OT', 'Đa-vít cầu hỏi Đức Giê-hô-va, nói: "Tôi có nên đi đánh những người Phi-li-tin này không?" Đức Giê-hô-va đáp với Đa-vít: "Hãy đi, đánh những người Phi-li-tin và giải cứu Kê-íp."'),
(7814, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 23, 3, 'OT', 'Người của Đa-vít nói với ông: "Nầy, chúng tôi ở đây tại Giu-đa mà còn sợ, huống chi nếu chúng tôi đi đến Kê-ri-lah để đánh các đạo quân của người Phi-li-tin?"'),
(7815, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 23, 4, 'OT', 'Đa-vít lại cầu hỏi Đức Giê-hô-va lần nữa. Đức Giê-hô-va phán trả lời ông rằng: "Hãy đứng dậy, đi xuống Kê-íp; vì Ta sẽ trao người Phi-li-tin vào tay ngươi."'),
(7816, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 23, 5, 'OT', 'Đa-vít và các người của ông đi đến Kê-íp, đánh giặc Phi-li-tin, đoạt lại đàn gia súc của chúng, đánh chúng một trận đại bại. Như thế, Đa-vít cứu được những người cư ngụ tại Kê-íp.'),
(7817, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 23, 6, 'OT', 'Khi A-bi-a-tha, con trai của A-hi-mê-léc, chạy trốn đến cùng Đa-vít tại Kê-íp, thì trên tay người có một áo e-phót.'),
(7818, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 23, 7, 'OT', 'Người ta báo cho Sa-un rằng: Đa-vít đã vào thành Kê-va. Sa-un nói: Đức Chúa Trời đã phó nó vào tay ta, vì nó đã bị nhốt khi đi vào một thành có cổng và then cửa.'),
(7819, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 23, 8, 'OT', 'Sau-lơ triệu tập toàn thể dân chúng ra chiến trận, để xuống Kê-íp-lah, vây hãm Đa-vít và những người của ông.'),
(7820, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 23, 9, 'OT', 'Đa-vít biết rằng Sau-lơ đang âm mưu làm điều ác chống lại mình, thì nói cùng thầy tế lễ A-bi-a-tha rằng: "Hãy mang áo Ê-phót đến đây."'),
(7821, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 23, 10, 'OT', 'Đa-vít nói: "Lạy Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên, tôi tớ Ngài đã thực sự nghe rằng Sau-lơ tìm cách đến Kê-ila để hủy diệt thành ấy vì cớ tôi."'),
(7822, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 23, 11, 'OT', 'Đức Giê-hô-va có cho những người ở Kê-ila nộp tôi vào tay người không? Liệu Sau-lơ có xuống như điều mà tôi tớ Ngài đã nghe không? Lạy Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en, xin hãy nói cho tôi tớ Ngài biết. Và Đức Giê-hô-va đáp: Người sẽ xuống.'),
(7823, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 23, 12, 'OT', 'Rồi Đa-vít nói: "Người của Kê-i-lah có nộp tôi và những người của tôi vào tay Sau-lơ không?" Và Đức Giê-hô-va đáp: "Họ sẽ nộp."'),
(7824, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 23, 13, 'OT', 'Đa-vít cùng những người của ông, khoảng sáu trăm người, đứng dậy rời khỏi Kê-ila và đi đến bất cứ nơi nào họ có thể đi. Người ta báo cho Sau-lơ biết rằng Đa-vít đã trốn thoát khỏi Kê-ila, nên ông từ bỏ ý định đi ra.'),
(7825, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 23, 14, 'OT', 'Đa-vít sống trong đồng vắng tại các nơi pháo đài, và ở trên núi trong đồng vắng Xíp. Sa-un tìm kiếm người ấy suốt cả ngày, nhưng Đức Chúa Trời không giao người ấy vào tay người.'),
(7826, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 23, 15, 'OT', 'Đa-vít thấy rằng Sau-lơ đã ra đi để tìm mạng sống mình, và Đa-vít đang ở trong đồng vắng Xíp, tại rừng cây.'),
(7827, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 23, 16, 'OT', 'Vậy, Giô-na-than, con trai của Sau-lơ, đứng dậy, đi đến Đa-vít trong rừng và làm cho tay người vững mạnh trong Đức Chúa Trời.'),
(7828, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 23, 17, 'OT', 'Đừng sợ, vì tay của Sa-un, cha ta, sẽ không bắt được ngươi; ngươi sẽ làm vua trên Y-sơ-ra-ên, và ta sẽ đứng bên cạnh ngươi; hơn nữa, chính Sa-un, cha ta, cũng biết điều đó.'),
(7829, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 23, 18, 'OT', 'Hai người lập giao ước với nhau trước mặt Đức Giê-hô-va; rồi Đa-vít ở lại trong rừng, còn Giô-na-than trở về nhà mình.'),
(7830, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 23, 19, 'OT', 'Dân Xíp đi lên gặp Sau-lơ tại Ghíp-ê-ah, nói rằng: "Đa-vít há chẳng trốn với chúng tôi trong các nơi ẩn náu trong rừng, trên đồi Ha-khi-la, ở phía nam vùng Gi-si-môn?"'),
(7831, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 23, 20, 'OT', 'Bây giờ, xin vua hãy xuống theo mọi ước nguyện trong lòng vua; còn chúng tôi, chúng tôi sẽ trao nộp người ấy vào tay vua.'),
(7832, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 23, 21, 'OT', 'Sa-un nói: "Các ngươi được Đức Giê-hô-va ban phước, vì các ngươi đã thương xót ta."'),
(7833, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 23, 22, 'OT', 'Hãy đi, hãy chuẩn bị thêm, và tìm hiểu, xem nơi nào hắn ở, ai đã thấy hắn ở đó; vì người ta nói với tôi rằng hắn rất mưu mẹo.'),
(7834, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 23, 23, 'OT', 'Hãy xem xét và tìm hiểu tất cả các nơi ẩn náu mà hắn thường trốn tránh ở đó, rồi trở lại báo cho tôi biết chắc chắn; tôi sẽ đi cùng các ngươi. Nếu hắn ở trong xứ, tôi sẽ tìm kiếm hắn trong tất cả các ngàn người của Giu-đa.'),
(7835, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 23, 24, 'OT', 'Họ liền đứng dậy và đi đến Xíp, đến trước mặt Sau-lơ; còn Đa-vít và những người của ông thì ở trong đồng vắng Ma-on, tại vùng đồng bằng phía nam vùng Gi-si-môn.'),
(7836, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 23, 25, 'OT', 'Sa-un và những người của ông đi tìm [Đa-vít], và người ta báo cho Đa-vít biết; Đa-vít liền xuống tảng đá và ở lại trong đồng vắng Ma-on. Khi Sa-un nghe tin đó, ông liền truy đuổi Đa-vít trong đồng vắng Ma-on.'),
(7837, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 23, 26, 'OT', 'Sa-un đi một bên sườn núi, còn Đa-vít và những người của ông thì đi bên kia sườn núi. Đa-vít vội vã rời đi vì sợ Sa-un, còn Sa-un và những người của ông thì bao vây Đa-vít và những người của ông để bắt giữ họ.'),
(7838, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 23, 27, 'OT', 'Và một thiên sứ đến cùng Sau-lơ, nói rằng: Hãy vội lên và đi, vì người Phi-li-tin đã tràn vào đất nước.'),
(7839, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 23, 28, 'OT', 'Sa-un bèn thôi không đuổi theo Đa-vít nữa, mà đi nghênh chiến cùng người Phi-li-tin; vì cớ đó, người ta gọi nơi ấy là Sê-la-ha-ma-cha-lô-th.'),
(7840, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 23, 29, 'OT', 'Đa-vít đi lên khỏi nơi đó và ở lại trong các pháo đài tại Ên-ghê-đi.'),
(7841, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 24, 1, 'OT', 'Xảy ra sau khi Sau-lơ trở về từ việc đuổi theo người Phi-li-tin, thì có người báo cho ông rằng: Nầy, Đa-vít đang ở trong đồng vắng Ên-ghê-đi.'),
(7842, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 24, 2, 'OT', 'Sau-lơ chọn ra ba ngàn người trai trẻ trong toàn thể Y-sơ-ra-ên, rồi đi tìm Đa-vít và những người của ông trên các vách đá của những dãy núi dê rừng.'),
(7843, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 24, 3, 'OT', 'Người ấy đi đến các chuồng chiên dọc đường, nơi có một cái hang; Sau-lơ đi vào trong đó để che chân mình. Đa-vít và những người của ông đang ngồi ở phía sâu bên trong cái hang.'),
(7844, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 24, 4, 'OT', 'Các người của Đa-vít nói với người rằng: "Kìa ngày mà Đức Giê-hô-va đã nói cùng ông: Nầy, Ta sẽ trao kẻ thù nghịch ngươi vào tay ngươi, để ngươi làm điều thiện theo mắt ngươi thấy. Vậy Đa-vít đứng dậy, lén cắt một phần vạt áo choàng của Sau-lơ."'),
(7845, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 24, 5, 'OT', 'Sau những việc ấy, lòng của Đa-vít cắn rứt vì đã cắt một mảnh áo của Sau-lơ.'),
(7846, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 24, 6, 'OT', 'Ông nói với những người của mình: "Đức Giê-hô-va không thể nào cho phép tôi làm điều này với chủ tôi, Đấng chịu xức dầu của Đức Giê-hô-va, là tra tay vào ông ấy, vì ông ấy là Đấng chịu xức dầu của Đức Giê-hô-va."'),
(7847, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 24, 7, 'OT', 'Đa-vít dùng những lời này can ngăn các người của mình, không cho họ trỗi dậy chống Xao-lơ. Xao-lơ đứng dậy khỏi hang và đi đường mình.'),
(7848, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 24, 8, 'OT', 'Sau đó, Đa-vít đứng dậy, đi ra khỏi hang và kêu lớn về phía Sau-lơ rằng: "Tâu vua chúa tôi!" Khi Sau-lơ quay lại nhìn, Đa-vít cúi mặt xuống đất và sấp mình xuống.'),
(7849, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 24, 9, 'OT', 'Đa-vít nói với Sau-lơ: "Tại sao ngài nghe theo lời của người đàn ông, nói rằng: Này Đa-vít tìm cách hại ngài?"'),
(7850, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 24, 10, 'OT', 'Kìa hôm nay, chính mắt ngươi đã thấy điều Đức Giê-hô-va đã trao ngươi vào tay ta trong hang ngày nay; người ta bảo ta giết ngươi, nhưng ta đã thương xót ngươi, và ta nói: Ta sẽ không tra tay vào chủ ta, vì người ấy là Đấng được Đức Giê-hô-va xức dầu.'),
(7851, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 24, 11, 'OT', 'Lạy cha của con, xin xem đây, chính là xem mép áo cha trong tay con; vì con đã cắt mép áo cha mà không giết cha, vậy xin cha biết và nhìn rõ rằng trong tay con chẳng có điều ác hay tội lỗi gì, con cũng chẳng phạm tội gì cùng cha, nhưng cha lại săn đuổi mạng sống con để lấy đi nó.'),
(7852, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 24, 12, 'OT', 'Đức Giê-hô-va sẽ xét xử giữa tôi và ông, và Đức Giê-hô-va sẽ báo oán tôi nơi ông; nhưng tay tôi sẽ không chống lại ông.'),
(7853, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 24, 13, 'OT', 'Như thể nào người xưa thường nói: Từ kẻ ác sinh ra ác; nhưng tay ta sẽ không chống lại ngươi.'),
(7854, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 24, 14, 'OT', 'Vua của Y-sơ-ra-ên đi ra để đuổi theo ai? Ngươi đuổi theo ai vậy? Theo một con chó đã chết, theo một con bọ chét sao?'),
(7855, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 24, 15, 'OT', 'Đức Giê-hô-va sẽ làm quan án, và xét xử giữa tôi và ông; Ngài sẽ thấy và biện hộ cho vụ tôi, và giải cứu tôi khỏi tay ông.'),
(7856, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 24, 16, 'OT', 'Sau khi Đa-vít nói xong những lời ấy với Sau-lơ, Sau-lơ nói: "Có phải tiếng con chăng, hỡi con ta Đa-vít?" Rồi Sau-lơ cất tiếng lên khóc.'),
(7857, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 24, 17, 'OT', 'Người nói với Đa-vít: "Anh công bình hơn tôi, vì chính anh đã đối xử tốt với tôi, còn tôi lại đối xử xấu với anh."'),
(7858, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 24, 18, 'OT', 'Ngày nay ngươi đã tỏ ra điều tốt lành mà ngươi đã làm cho ta, khi Đức Giê-hô-va đã phó ta vào tay ngươi, nhưng ngươi không giết ta.'),
(7859, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 24, 19, 'OT', 'Vì nếu một người gặp được kẻ thù của mình, mà lại để người ấy đi bình an, thì nguyện Đức Giê-hô-va báo đáp điều thiện cho ngươi, thay cho điều thiện mà ngày nay ngươi đã làm cho ta.'),
(7860, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 24, 20, 'OT', 'Và bây giờ, này, tôi biết chắc chắn rằng ông sẽ làm vua, và vương quốc của Y-sơ-ra-ên sẽ được lập vững chắc trong tay ông.'),
(7861, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 24, 21, 'OT', 'Vì vậy, hãy chỉ Đức Giê-hô-va mà thề với tôi rằng ngươi sẽ không diệt dòng dõi tôi sau tôi, và sẽ không xóa tên tôi khỏi nhà cha tôi.'),
(7862, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 24, 22, 'OT', 'Đa-vít thề hứa với Sau-lơ. Sau-lơ trở về nhà mình; còn Đa-vít và những người của ông thì lên đồn bảo vệ.'),
(7863, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 1, 'OT', 'Rồi Sa-mu-ên qua đời; toàn thể dân Ít-ra-en nhóm lại, khóc than thương tiếc ông và chôn ông trong nhà ông tại Ra-mah. Sau đó, Đa-vít đứng dậy, đi xuống vùng đồng vắng Pa-ran.'),
(7864, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 2, 'OT', 'Có một người ở Ma-on, tài sản của người ấy tại Ca-rmên; người ấy rất giàu có, có ba ngàn chiên và một ngàn dê, và đang lúc xén lông chiên mình tại Ca-rmên.'),
(7865, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 3, 'OT', 'Tên người đàn ông ấy là Na-banh, tên vợ ông là A-bi-gai-ên; người vợ có trí khôn tốt và nhan sắc xinh đẹp, còn người đàn ông thì thô lỗ và xấu xa trong cách hành xử, và ông thuộc dòng dõi Ca-lép.'),
(7866, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 4, 'OT', 'Đa-vít nghe trong đồng vắng rằng Na-banh đang xén lông chiên mình.'),
(7867, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 5, 'OT', 'Đa-vít sai mười người trẻ tuổi, và Đa-vít nói với các người trẻ tuổi ấy: "Hãy lên Kác-mên, đến gặp Na-banh, và chào người nhân danh ta."'),
(7868, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 6, 'OT', 'Hãy nói: Chúc người sống yên ổn; nguyện sự bình an thuộc về ông, nguyện sự bình an thuộc về nhà ông, và nguyện sự bình an thuộc về mọi điều ông có.'),
(7869, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 7, 'OT', 'Bây giờ tôi nghe nói ông đang cắt lông chiên; các mục tử của ông ở với chúng tôi, chúng tôi không làm nhục họ, cũng chẳng thiếu hụt điều gì cho họ, suốt thời gian họ ở tại Kẹ-rem-ên.'),
(7870, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 8, 'OT', 'Hãy hỏi các đầy tớ của ông, họ sẽ cho ông biết. Vậy nguyện các đầy tớ được ơn trước mặt ông, vì chúng tôi đến trong ngày lễ tốt lành. Xin ông vui lòng cho những gì ông có thể tìm thấy nơi tay ông, cho các đầy tớ của ông và cho Đa-vít, con trai ông.'),
(7871, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 9, 'OT', 'Các tôi tớ của Đa-vít đến, nói với Na-banh mọi lời ấy nhân danh Đa-vít, rồi nín lặng.'),
(7872, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 10, 'OT', 'Na-banh đáp lại các đầy tớ của Đa-vít và nói: Ai là Đa-vít, và ai là con trai của Y-sai? Ngày nay có nhiều đầy tớ nổi loạn, mỗi người bỏ chủ mình mà chạy.'),
(7873, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 11, 'OT', 'Ta sẽ lấy bánh ta, nước ta, và thịt ta mà ta đã giết cho những người xén lông chiên ta, rồi đưa cho những người mà ta chẳng biết họ từ đâu tới sao?'),
(7874, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 12, 'OT', 'Các tôi tớ của Đa-vít quay trở lại trên đường của mình, rồi trở về, đến và thuật lại cho ông mọi lời ấy.'),
(7875, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 13, 'OT', 'Đa-vít nói với các người của mình: "Mỗi người hãy thắt gươm của mình vào." Vậy mỗi người thắt gươm của mình vào; Đa-vít cũng thắt gươm mình vào. Khoảng bốn trăm người đi lên theo sau Đa-vít, còn hai trăm người ở lại với các vật dụng.'),
(7876, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 14, 'OT', 'Một người đầy tớ trẻ trong các đầy tớ nói với A-bi-gai-ên, vợ của Na-banh, rằng: "Nầy, Đa-vít đã sai các sứ giả từ trong đồng vắng đến để chào hỏi chủ chúng ta, nhưng ông đã quở trách họ."'),
(7877, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 15, 'OT', 'Các người ấy rất tốt với chúng tôi, và chúng tôi không bị sỉ nhục, cũng không thiếu thứ gì, suốt những ngày chúng tôi đi cùng họ khi chúng tôi ở ngoài đồng.'),
(7878, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 16, 'OT', 'Họ là bức tường che chở chúng tôi cả ban đêm lẫn ban ngày, suốt thời gian chúng tôi ở cùng họ để chăn chiên.'),
(7879, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 17, 'OT', 'Bây giờ, hãy suy nghĩ và xem xét điều ngươi sẽ làm, vì tai họa đã quyết định nghịch cùng chủ chúng ta và toàn thể gia đình người; người ấy là con trai của Bê-li-ách, không thể nói chuyện với người được.'),
(7880, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 18, 'OT', 'A-bi-gai-ên vội vàng lấy hai trăm ổ bánh, hai bầu rượu, năm chiên đã mổ sẵn, năm giạ lúa rang, một trăm chùm nho khô, hai trăm bánh vả, và chất tất cả lên các con lừa.'),
(7881, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 19, 'OT', 'Bà nói với các đầy tớ mình: "Hãy đi trước tôi; nầy, tôi sẽ đi theo các ngươi." Nhưng bà không nói cho chồng mình là Na-banh biết.'),
(7882, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 20, 'OT', 'Đang khi ấy, nàng cỡi lừa đi xuống, đi theo sườn núi; và nầy, Đa-vít và các người của người đang đi xuống đón nàng; thì nàng liền gặp họ.'),
(7883, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 21, 'OT', 'Đa-vít nói: "Chắc hẳn là vô ích thôi, ta đã giữ mọi điều thuộc về người này trong đồng vắng, chẳng thiếu một gì của những gì thuộc về hắn; vậy mà hắn lại lấy điều ác đáp lại điều lành ta làm cho hắn."'),
(7884, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 22, 'OT', 'Cầu Đức Chúa Trời xử với kẻ thù của Đa-vít thể nào, và còn làm thêm thể ấy nữa, nếu tôi để lại điều gì thuộc về nó cho đến sáng mai, dù chỉ là một người tiểu tiện vào vách tường.'),
(7885, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 23, 'OT', 'Khi A-bi-gai-ên thấy Đa-vít, nàng vội vàng xuống khỏi lừa, sấp mặt xuống trước mặt Đa-vít và cúi mình xuống đất.'),
(7886, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 24, 'OT', 'Mà nàng liền sấp mình dưới chân người ấy và nói: "Cúi xin ngài, chính tôi đây, xin chịu lấy tội lỗi nầy; và xin hãy để cho tớ gái ngài được nói vào tai ngài, xin hãy nghe những lời của tớ gái ngài."'),
(7887, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 25, 'OT', 'Xin chúa của tôi chớ để lòng mình bận đến người ác quấy này, là Na-banh; vì như tên ông ta, ông ta là Na-banh, và sự điên dại ở cùng ông ta. Còn tôi, tớ gái của ngài, tôi không thấy các trai trẻ của chúa tôi mà ngài đã sai đi.'),
(7888, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 26, 'OT', 'Bây giờ, thưa chúa tôi, Đức Giê-hô-va hằng sống và linh hồn ngài cũng hằng sống, Đấng đã ngăn cản ngài không để ngài ra tay giết người và tự tay báo thù; vậy bây giờ, nguyện những kẻ thù của ngài và những kẻ tìm hại chúa tôi được như Na-banh.'),
(7889, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 27, 'OT', 'Và bây giờ, phước lành nầy mà tớ gái ngài đã mang đến cho chúa tôi, xin hãy trao cho các người trẻ tuổi đi theo chúa tôi.'),
(7890, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 28, 'OT', 'Xin hãy nhận lấy lỗi lầm của tớ nữ tớ người, vì Đức Giê-hô-va chắc chắn sẽ lập cho chúa của tôi một nhà bền vững; bởi chúa của tôi chiến đấu các cuộc chiến của Đức Giê-hô-va, và điều ác nào cũng không tìm thấy nơi ngài trong suốt các ngày đời của ngài.'),
(7891, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 29, 'OT', 'Khi có người trỗi dậy để đuổi theo ngươi và tìm mạng sống ngươi, thì mạng sống của chủ tôi sẽ được gói ghém trong túi đựng sự sống nơi Đức Giê-hô-va Đức Chúa Trời ngươi; còn mạng sống những kẻ thù ngươi, Ngài sẽ liệng ra như từ giữa cái ná.'),
(7892, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 30, 'OT', 'Và sẽ xảy ra, khi Đức Giê-hô-va làm cho chúa tôi mọi điều thiện mà Ngài đã phán về ngài, và đặt ngài làm người lãnh đạo trên Ít-ra-en;'),
(7893, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 31, 'OT', 'Và điều này sẽ không trở thành gánh nặng và vấp phạm trong lòng cho chúa của tôi, cũng không phải vì chúa của tôi đã đổ máu cách vô cớ hay tự mình báo thù; nhưng khi Đức Giê-hô-va làm điều tốt cho chúa của tôi, thì xin hãy nhớ đến tớ gái của ngài.'),
(7894, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 32, 'OT', 'Đa-vít nói với A-bi-ganh: "Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en đáng được ca ngợi, là Đấng đã sai nàng đến hôm nay để gặp tôi."'),
(7895, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 33, 'OT', 'Được phước vì sự khôn ngoan của nàng, và nàng được phước, vì đã ngăn tôi hôm nay khỏi việc đổ máu và tự tay tôi báo thù.'),
(7896, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 34, 'OT', 'Thật vậy, Đấng Hằng Sống, Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên, là Đấng đã ngăn tôi không làm hại đến ngươi; vì nếu ngươi không vội đến gặp tôi, chắc chắn đến sáng mai, Nha-banh sẽ chẳng còn ai biết đứng tiểu tiện dọc tường.'),
(7897, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 35, 'OT', 'Đa-vít nhận từ tay nàng những gì nàng đã mang đến cho ông, rồi nói với nàng: "Hãy về nhà bình an; này, ta đã nghe theo tiếng ngươi và chấp nhận diện của ngươi."'),
(7898, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 36, 'OT', 'A-bi-gai-ên trở về gặp Na-banh, thì thấy người đang tổ chức tiệc trong nhà mình như thể tiệc của vua; lòng Na-banh vui vẻ, nhưng người say rượu quá mức. Vì vậy, nàng không nói với người điều gì, dù nhỏ hay lớn, cho đến khi sáng hôm sau.'),
(7899, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 37, 'OT', 'Sáng hôm sau, khi rượu đã rút khỏi Na-banh, vợ ông thuật lại cho ông những điều ấy; lòng ông liền chết trong người, và ông trở nên như một hòn đá.'),
(7900, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 38, 'OT', 'Sau khoảng mười ngày, Đức Giê-hô-va giáng bệnh trên Na-banh, và người ấy qua đời.'),
(7901, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 39, 'OT', 'Khi Đa-vít nghe tin Na-banh đã chết, ông nói: "Đáng ngợi khen ĐỨC Giê-hô-va, Đấng đã bênh vực tôi khỏi sự sỉ nhục tôi phải chịu nơi tay Na-banh, và đã giữ cho tôi tớ Ngài khỏi làm điều ác; vì ĐỨC Giê-hô-va đã khiến điều ác của Na-banh đổ lại trên đầu chính hắn." Rồi Đa-vít sai người đến nói chuyện với A-bi-gai-l, để rước nàng làm vợ ông.'),
(7902, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 40, 'OT', 'Các tôi tớ của Đa-vít đến cùng A-bi-gai ở trên núi Ca-rmên, và nói với nàng rằng: Đa-vít đã sai chúng tôi đến cùng nàng, để đem nàng về làm vợ người.'),
(7903, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 41, 'OT', 'Bà ấy liền đứng dậy, cúi mặt xuống đất và nói: Này tôi tớ gái của ngài sẽ làm nữ tớ việc rửa chân cho các đầy tớ của chúa tôi.'),
(7904, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 42, 'OT', 'A-bi-gai-ên vội vàng đứng dậy, cưỡi lên lừa, cùng năm nữ tì của mình đi bộ theo sau bà; bà đi theo các sứ giả của Đa-vít, và trở thành vợ ông.'),
(7905, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 43, 'OT', 'Đa-vít cũng rước A-hi-nô-am từ Gít-rê-ên; cả hai người đàn bà ấy đều trở thành vợ ông.'),
(7906, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 25, 44, 'OT', 'Và Sa-un đã gả Mi-kal, con gái mình, vợ của Đa-vít, cho Phanh-ti, con trai của Lai-xi, người ở Ga-lim.'),
(7907, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 26, 1, 'OT', 'Dân Xíp đến gặp Sau-lơ tại Ghíp-ê-ah, nói: "Đa-vít chẳng đang ẩn náu trên đồi Ha-khi-la, đối diện với vùng Xê-xi-môn sao?"'),
(7908, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 26, 2, 'OT', 'Sau-lơ đứng dậy, đi xuống đồng vắng Xíp, cùng với ba ngàn người tinh nhuệ của Y-sơ-ra-ên, để tìm Đa-vít trong đồng vắng Xíp.'),
(7909, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 26, 3, 'OT', 'Sa-un đóng trại trên đồi Ha-khi-la, nằm phía trước vùng hoang vu Giê-si-môn, bên đường; còn Đa-vít thì ở trong đồng vắng, và ông thấy rằng Sa-un đã đến theo sau ông vào trong đồng vắng ấy.'),
(7910, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 26, 4, 'OT', 'Đa-vít liền sai những người do thám đi, và ông biết rằng Sau-lơ quả thật đã đến Nác-hôn.'),
(7911, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 26, 5, 'OT', 'Đa-vít chỗi dậy, đi đến nơi Sau-lơ đóng quân; Đa-vít nhìn thấy chỗ Sau-lơ nằm, và Áp-ne con trai Nê-er, tướng chỉ huy đạo quân người, và Sau-lơ đang nằm trong trại, còn quân lính thì đóng quanh đó.'),
(7912, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 26, 6, 'OT', 'Đa-vít đáp và nói với A-hi-mê-léc người Hê-tít và với A-bi-sai, con trai Xê-ru-ya, anh em của Giô-áp, rằng: "Ai sẽ đi xuống cùng tôi với Sau-lơ vào doanh trại?" A-bi-sai nói: "Tôi sẽ đi xuống cùng ông."'),
(7913, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 26, 7, 'OT', 'Đoạn và Áp-xi-sai đến nơi quân đội vào ban đêm; nầy, Sau-lơ đang nằm ngủ trong trại, và cây giáo của người cắm xuống đất ở đầu người; còn Áp-ne và quân lính thì nằm ngủ xung quanh người.'),
(7914, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 26, 8, 'OT', 'A-bi-sai nói với Đa-vít: "Hôm nay Đức Chúa Trời đã trao kẻ thù nghịch ngươi vào tay ngươi; vậy bây giờ xin để tôi đâm nó một nhát bằng ngọn giáo xuống đất, và tôi sẽ không đâm lần thứ hai."'),
(7915, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 26, 9, 'OT', 'Đa-vít nói với A-bi-sai: "Đừng giết người ấy, vì ai có thể giơ tay nghịch cùng Đấng được Đức Giê-hô-va xức dầu mà vô tội?"'),
(7916, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 26, 10, 'OT', 'Đa-vít nói thêm: Đức Giê-hô-va hằng sống, chắc chắn Đức Giê-hô-va sẽ đánh ông ta, hoặc đến kỳ ông ta phải chết, hoặc khi đi ra trận thì sẽ bị giết.'),
(7917, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 26, 11, 'OT', 'Đức Giê-hô-va không cho phép tôi giơ tay hại Đấng Xức Dầu của Ngài; vậy bây giờ, hãy lấy cây giáo ở đầu giường và bầu nước bên cạnh, rồi chúng ta đi đi.'),
(7918, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 26, 12, 'OT', 'Đa-vít lấy cây giáo và bầu nước ở đầu giường của Sau-lơ, rồi họ đi đi; không ai thấy, không ai biết, không ai thức dậy, vì tất cả đều đang ngủ mê, bởi giấc ngủ sâu từ Đức Giê-hô-va đã giáng trên họ.'),
(7919, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 26, 13, 'OT', 'Đoạn Đa-vít qua bên kia, rồi đứng trên đỉnh núi ở xa, một khoảng cách lớn nằm giữa họ.'),
(7920, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 26, 14, 'OT', 'Đa-vít kêu lên cùng dân chúng và cùng Áp-ne, con trai của Nê-er, mà nói: "Này Áp-ne, chẳng lẽ ngươi không trả lời sao?" Áp-ne bèn đáp và nói: "Ngươi là ai mà dám kêu lên cùng vua?"'),
(7921, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 26, 15, 'OT', 'Đa-vít nói với Áp-ne: "Chẳng phải anh là một người dũng cảm sao? Và ai giống như anh ở Ít-ra-en? Vậy tại sao anh không canh giữ cho chủ mình là vua? Vì có một người trong dân đến để giết vua, chủ của anh."'),
(7922, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 26, 16, 'OT', 'Việc ngươi làm điều này không tốt. Đức Giê-hô-va hằng sống, các ngươi đáng chết, vì đã không canh giữ chủ mình, là Đấng được Đức Giê-hô-va xức dầu. Và bây giờ, hãy xem ngọn giáo của vua ở đâu, và cái bầu nước vốn đặt ở đầu giường người.'),
(7923, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 26, 17, 'OT', 'Sau-lơ nhận ra tiếng Đa-vít, liền nói: "Có phải tiếng con đây chăng, hỡi con ta Đa-vít?" Đa-vít đáp: "Chính là tiếng con, thưa chủ nhân tôi là vua."'),
(7924, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 26, 18, 'OT', 'Ông nói: "Tại sao bệ hạ lại đuổi theo tôi tớ mình như vậy? Tôi đã làm gì? Và điều ác nào ở trong tay tôi?"'),
(7925, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 26, 19, 'OT', 'Bây giờ, xin kính thỉnh đức vua, chúa tôi, hãy nghe lời kẻ tôi tớ mình. Nếu chính Đức Giê-hô-va đã xúi giục ngài chống lại tôi, nguyện Ngài nhận của lễ thiêu; nhưng nếu là con cái loài người, nguyện chúng bị rủa sả trước mặt Đức Giê-hô-va, vì hôm nay chúng đã xua đuổi tôi khỏi hưởng phần cơ nghiệp của Đức Giê-hô-va, mà rằng: "Hãy đi, hầu việc các thần khác."'),
(7926, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 26, 20, 'OT', 'Bây giờ, xin đừng để huyết ta đổ ra đất trước mặt Đức Giê-hô-va; vì vua Y-sơ-ra-ên đã ra đi để tìm một con bọ chét, như người đuổi chim đa đa trên núi.'),
(7927, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 26, 21, 'OT', 'Sa-un nói: "Ta đã phạm tội; hãy trở lại, hỡi con ta là Đa-vít, vì ta sẽ không còn làm hại ngươi nữa, vì hôm nay ngươi đã coi mạng ta là quý giá trong mắt ngươi. Này, ta đã hành động dại dột và sai lầm rất nhiều."'),
(7928, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 26, 22, 'OT', 'Đáp lại, Đa-vít nói: "Này, giáo của vua đây! Hãy để một trong các trai trẻ sang lấy đi."'),
(7929, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 26, 23, 'OT', 'Đức Giê-hô-va sẽ hoàn trả cho người ấy theo sự công bình và lòng trung tín của anh ta, vì chính Đức Giê-hô-va đã trao ngươi vào tay ta hôm nay, nhưng ta đã không chịu giơ tay lên chống lại người được xức dầu của Đức Giê-hô-va.'),
(7930, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 26, 24, 'OT', 'Nầy, hỡi vua, chính như ngày nay mạng sống vua được coi trọng trong mắt tôi thế nào, thì nguyện mạng sống tôi cũng được coi trọng trong mắt Đức Giê-hô-va như vậy, và nguyện Ngài cứu tôi khỏi mọi nỗi gian truân.'),
(7931, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 26, 25, 'OT', 'Sau-lơ nói với Đa-vít: "Ngươi được phước đấy, hỡi con trai ta là Đa-vít; ngươi sẽ thực hiện điều lớn lao, và cũng sẽ đầy quyền năng." Rồi Đa-vít đi theo đường lối mình, và Sau-lơ trở về chỗ của ông.'),
(7932, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 27, 1, 'OT', 'Đa-vít nói trong lòng mình: "Nay, một ngày nào tôi sẽ chết tay Sau-lơ; chẳng có điều gì tốt cho tôi bằng việc trốn nhanh sang đất của người Phi-li-tin, để Sau-lơ thôi không còn tìm tôi nữa trong khắp các vùng biên giới của Ít-ra-en; như vậy tôi sẽ thoát khỏi tay ông ta."'),
(7933, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 27, 2, 'OT', 'Đa-vít đứng dậy và đi qua cùng sáu trăm người đàn ông đi với ông đến A-khis, con trai của Maoch, vua thành Gát.'),
(7934, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 27, 3, 'OT', 'Đa-vít ở cùng A-kích tại Gát, người và những người của ông, mỗi người với gia đình mình; Đa-vít và hai vợ của người là A-hi-nô-am người Y-xơ-ra-en, và A-bi-gai-ên, vợ của Na-banh người Ca-rơ-mên.'),
(7935, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 27, 4, 'OT', 'Sau khi được báo tin Đa-vít đã trốn đến Gát, Sau-lơ không còn tiếp tục tìm kiếm người nữa.'),
(7936, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 27, 5, 'OT', 'Đa-vít nói với A-kích: Nếu bây giờ tôi được ơn trước mắt ông, xin hãy ban cho tôi một chỗ tại một trong các thành phố ở miền quê, để tôi có thể ở đó; vì sao tôi là đầy tớ ông lại phải ở trong thành phố vương quốc cùng với ông?'),
(7937, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 27, 6, 'OT', 'Vì vậy, ngày ấy A-kích ban cho ông Xích-lag; bởi đó Xích-lag thuộc về các vua nước Giu-đa cho đến ngày nay.'),
(7938, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 27, 7, 'OT', 'Thời gian Đa-vít ở trong xứ của người Phi-li-tin là một năm bốn tháng.'),
(7939, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 27, 8, 'OT', 'Đa-vít cùng những người của ông lên đường, tấn công dân Giát-sua, dân Ghẹt-xua và dân A-ma-léc; vì những dân ấy từ lâu đời đã cư ngụ trong vùng đất này, từ khi vào Su-ru cho đến tận đất Ai-cập.'),
(7940, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 27, 9, 'OT', 'Đa-vít đánh đất ấy, không để lại một người nam hay nữ nào sống sót, rồi cướp lấy chiên, bò, lừa, lạc đà và quần áo, đoạn trở về và đến cùng Ách-ís.'),
(7941, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 27, 10, 'OT', 'A-kích nói: "Hôm nay các ngươi đã đi cướp ở đâu?" Đa-vít đáp: "Chúng tôi đi về phía nam xứ Giu-đa, về phía nam dân Giê-ra-ha-mên, và về phía nam dân Kê-nít."'),
(7942, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 27, 11, 'OT', 'Đa-vít không để sống sót một người nam hay nữ nào, để đem về Ca-thê, vì sợ họ sẽ thuật lại về chúng ta rằng: "Đa-vít đã làm như thế, và đó là cách xử sự của ông, suốt mọi ngày ông cư ngụ trong đất của người Phi-li-tin."'),
(7943, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 27, 12, 'OT', 'A-kích tin Đa-vít, nói rằng: "Người đã làm cho dân Y-sơ-ra-ên ghét bỏ người; vì vậy người sẽ làm đầy tớ ta mãi mãi."'),
(7944, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 28, 1, 'OT', 'Xảy ra trong những ngày ấy, người Phi-li-tin nhóm các đạo quân mình lại để ra chiến trường đánh cùng Y-sơ-ra-ên. A-khis nói với Đa-vít: "Ngươi phải biết chắc rằng ngươi và những người của ngươi sẽ ra đi cùng ta ra trận."'),
(7945, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 28, 2, 'OT', 'Và Đa-vít nói với A-chis: "Vì vậy, bây giờ ông hãy biết điều mà tôi, kẻ tôi tớ của ông, có thể làm." A-chis nói với Đa-vít: "Vì vậy, ta sẽ đặt ngươi làm người giữ đầu ta trọn mọi ngày."'),
(7946, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 28, 3, 'OT', 'Sa-mu-ên đã qua đời, và toàn thể Ít-ra-en đã khóc than ông, mai táng ông tại Ra-ma, ngay trong thành phố của ông. Còn Sau-lơ thì đã trục xuất những kẻ đồng bóng và thầy bói ra khỏi cả đất nước.'),
(7947, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 28, 4, 'OT', 'Người Phi-li-tin nhóm lại, đến và đóng trại tại Su-nem; và Sau-lơ tập hợp toàn thể Ít-ra-en, và họ đóng trại tại Ghil-bô-a.'),
(7948, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 28, 5, 'OT', 'Khi Sa-un thấy đạo quân của người Phi-li-tin, ông sợ hãi và lòng ông run sợ rất dữ.'),
(7949, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 28, 6, 'OT', 'Sa-un cầu hỏi Đức Giê-hô-va, nhưng Đức Giê-hô-va không đáp lại người, cũng chẳng đáp qua chiêm bao, chẳng qua U-rim, cũng chẳng qua các nhà tiên tri.'),
(7950, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 28, 7, 'OT', 'Sa-un nói với các đầy tớ mình: "Hãy tìm cho ta một người đàn bà có thần đồng, để ta đến hỏi bà ấy." Các đầy tớ đáp lại người: "Này, có một người đàn bà có thần đồng ở Ên-đô."'),
(7951, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 28, 8, 'OT', 'Vua Sau-lơ liền cải trang, mặc những quần áo khác, rồi đi cùng với hai người tôi trung; cả ba đến gặp người đàn bà có thần đồng cõi âm vào ban đêm. Vua nói: "Tôi xin bà hãy dùng thần đồng để bói cho tôi, và gọi lên từ cõi âm một người mà tôi sẽ nói tên cho bà."'),
(7952, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 28, 9, 'OT', 'Người đàn bà nói với người ấy: "Nầy, ông biết điều Sa-un đã làm, là đã tiêu diệt những kẻ có thần giao và những kẻ bói toán khỏi đất nước; vậy sao ông lại đặt bẫy mạng sống tôi để giết tôi?"'),
(7953, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 28, 10, 'OT', 'Vậy Sa-un chỉ Đức Giê-hô-va mà thề cùng người ấy, rằng: Đức Giê-hô-va hằng sống, chắc chắn ngươi sẽ không gặp điều gì xấu vì việc này.'),
(7954, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 28, 11, 'OT', 'Người đàn bà nói: "Tôi phải đưa ai lên cho bà?" Người đáp: "Hãy đưa Sa-mu-ên lên cho tôi."'),
(7955, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 28, 12, 'OT', 'Người đàn bà thấy Sa-mu-ên, bèn kêu lên một tiếng lớn; rồi người đàn bà nói với Sau-lơ rằng: "Sao ngài lại lừa dối tôi? Chính ngài là Sau-lơ!"'),
(7956, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 28, 13, 'OT', 'Vua nói với bà: "Đừng sợ; hãy cho ta biết ngươi thấy gì." Bà ấy nói với Sa-un: "Tôi thấy các thần từ dưới đất hiện lên."'),
(7957, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 28, 14, 'OT', 'Người ấy nói với bà: "Ông ấy có hình dạng như thế nào?" Bà trả lời: "Một người già đang đi lên, và ông ấy mặc áo choàng." Sau đó, Sa-un biết rằng đó là Sa-mu-ên, bèn cúi mặt xuống đất và cúi lạy.'),
(7958, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 28, 15, 'OT', 'Rồi Sa-mu-ên nói với Sau-lơ: "Tại sao ngươi làm rối ta, khiến ta phải lên đây?" Sau-lơ đáp: "Ta rất đau khổ; người Phi-li-tin đang chiến đấu chống ta, và Đức Chúa Trời đã lìa bỏ ta, không còn đáp lời ta nữa, chẳng những qua các nhà tiên tri, mà cũng chẳng phải trong chiêm bao. Vì vậy ta đã gọi ngươi, để ngươi cho ta biết điều ta phải làm."'),
(7959, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 28, 16, 'OT', 'Sa-mu-ên nói: "Sao ngươi hỏi ta, vì Đức Giê-hô-va đã rời khỏi ngươi và trở thành kẻ thù nghịch ngươi?"'),
(7960, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 28, 17, 'OT', 'Và Đức Giê-hô-va đã làm cho người điều đó như Ngài đã phán bởi tay ta; Đức Giê-hô-va đã xé bỏ vương quốc khỏi tay ngươi và ban nó cho người bạn ngươi, cho Đa-vít.'),
(7961, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 28, 18, 'OT', 'Vì ngươi đã không vâng theo tiếng của Đức Giê-hô-va, và không thi hành cơn thịnh nộ của Ngài trên dân A-ma-léc, nên Đức Giê-hô-va đã làm điều này cho ngươi ngày hôm nay.'),
(7962, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 28, 19, 'OT', 'Đức Giê-hô-va sẽ trao cả Ít-ra-en cùng ngươi vào tay người Phi-li-tin; và ngày mai, ngươi và các con trai ngươi sẽ ở cùng ta; chính Đức Giê-hô-va cũng sẽ trao đạo quân Ít-ra-en vào tay người Phi-li-tin.'),
(7963, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 28, 20, 'OT', 'Vậy Sa-un vội vàng ngã xuống đất, nằm dài toàn thân, và rất sợ hãi vì những lời của Sa-mu-ên; người cũng không còn sức lực nào, vì người đã không ăn bánh suốt cả ngày và cả đêm.'),
(7964, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 28, 21, 'OT', 'Người đàn bà đến cùng Sau-lơ, thấy người rất kinh hoàng, liền nói với người rằng: "Này tôi tớ gái đã vâng theo tiếng người; tôi đã liều mạng mình, và nghe theo các lời người nói với tôi."'),
(7965, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 28, 22, 'OT', 'Bây giờ, xin ông hãy vâng lời tôi, là tớ gái của ông, và để tôi dọn một miếng bánh trước mặt ông; ông hãy ăn, hầu có sức khi đi trên đường.'),
(7966, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 28, 23, 'OT', 'Nhưng ông từ chối và nói: "Tôi sẽ không ăn." Tuy nhiên, các đầy tớ ông và cả người đàn bà ấy đều nài ép ông, và ông vâng theo lời họ. Vậy ông đứng dậy khỏi đất và ngồi trên giường.'),
(7967, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 28, 24, 'OT', 'Người đàn bà có một con bê béo trong nhà; bà vội vàng giết nó, rồi lấy bột, nhồi và nướng những chiếc bánh không men.'),
(7968, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 28, 25, 'OT', 'Bà dọn ra trước mặt Sa-un và các đầy tớ ông; họ ăn xong, rồi đứng dậy và đi trong đêm đó.'),
(7969, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 29, 1, 'OT', 'Các người Phi-li-tin nhóm toàn bộ đạo quân mình lại tại A-phéc; còn người I-xa-ra-en thì đóng trại bên cạnh suối ở Y-xa-ra-en.'),
(7970, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 29, 2, 'OT', 'Các quan trưởng của người Phi-li-tin đi qua từng trăm và từng ngàn; còn Đa-vít và những người của ông thì đi qua ở hàng hậu vệ cùng với A-chích.'),
(7971, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 29, 3, 'OT', 'Các quan trưởng Phi-li-tin nói: "Những người Do Thái này là ai?" A-khích đáp với các quan trưởng Phi-li-tin: "Chẳng phải đây là Đa-vít, đầy tớ của Sau-lơ, vua Y-sơ-ra-ên sao? Người đã ở cùng tôi những ngày nay, hay những năm nay; và tôi chẳng tìm thấy điều gì sai nơi người, kể từ ngày người đầu hàng tôi cho đến ngày nay."'),
(7972, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 29, 4, 'OT', 'Các quan trưởng người Phi-li-tin nổi giận với vua và nói cùng vua rằng: "Xin hãy cho người đàn ông này trở về nơi mà ngài đã chỉ định cho anh ta, đừng để anh ta đi xuống chiến trận cùng chúng tôi, kẻo trong lúc giao chiến anh ta sẽ trở thành kẻ chống lại chúng tôi. Làm sao người này làm hòa với chủ mình được? Chẳng phải bằng đầu của những người này sao?"'),
(7973, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 29, 5, 'OT', 'Chẳng phải đây là Đa-vít, người mà họ từng hát cho trong các điệu múa, rằng: "Sa-un giết hàng ngàn, còn Đa-vít giết hàng vạn" sao?'),
(7974, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 29, 6, 'OT', 'A-ki-si gọi Đa-vít và nói với người: "Nhân danh Đức Giê-hô-va hằng sống, ngươi thật trung thực, và việc ra vào cùng ta trong doanh trại thật tốt đẹp trong mắt ta. Vì từ ngày ngươi đến cùng ta cho đến ngày nay, ta không tìm thấy điều ác nào nơi ngươi. Nhưng trong mắt các chủ tướng, ngươi không được vừa lòng."'),
(7975, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 29, 7, 'OT', 'Vì vậy, bây giờ hãy trở về và đi bình an, đừng làm điều ác trước mặt các quan trưởng của người Phi-li-tin.'),
(7976, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 29, 8, 'OT', 'Vậy Đa-vít nói với A-kích: "Tôi đã làm điều gì, và ông đã tìm thấy điều gì nơi tôi, tôi tớ ông, kể từ ngày tôi đến trước mặt ông cho đến ngày nay, mà tôi không được đi đánh giặc cùng các kẻ thù của chủ tôi là vua?"'),
(7977, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 29, 9, 'OT', 'A-khích đáp và nói với Đa-vít: Ta biết ngươi thiện lành trước mặt ta như một thiên sứ của Đức Chúa Trời; nhưng các quan trưởng của người Phi-li-tin đã nói: Hắn sẽ không được đi lên cùng chúng ta ra chiến trận.'),
(7978, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 29, 10, 'OT', 'Bây giờ, hãy chỗi dậy sớm vào buổi sáng cùng các đầy tớ của chủ ngươi, những người đã đến với ngươi; và hãy thức dậy sớm vào buổi sáng, khi trời vừa sáng thì hãy đi đi.'),
(7979, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 29, 11, 'OT', 'Đa-vít cùng các người của ông chỗi dậy sớm vào buổi sáng để trở về đất của người Phi-li-tin; còn người Phi-li-tin thì lên đến Y-xơ-rên.'),
(7980, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 30, 1, 'OT', 'Và xảy ra vào ngày thứ ba, khi Đa-vít và những người của ông đến Xi-klác, thì người A-ma-léc đã xâm chiếm vùng miền Nam và Xi-klác, đánh phá Xi-klác và thiêu hủy thành ấy bằng lửa.'),
(7981, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 30, 2, 'OT', 'Họ bắt các phụ nữ ở trong đó, từ nhỏ đến lớn, không giết ai, rồi họ dẫn đi và lên đường theo con đường của mình.'),
(7982, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 30, 3, 'OT', 'Đa-vít và những người của ông đến thành phố, thì thấy nó đã bị thiêu đốt bởi lửa; và các vợ, các con trai, các con gái của họ đã bị bắt đi làm phu tù.'),
(7983, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 30, 4, 'OT', 'Đa-vít và những người đi cùng ông đã cất tiếng khóc, và họ khóc đến nỗi không còn sức lực để khóc nữa.'),
(7984, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 30, 5, 'OT', 'Hai người vợ của Đa-vít bị bắt làm tù binh, đó là A-hi-nô-am người Y-xơ-rên và A-bi-gai-ên, vợ của Na-banh người Ca-rơ-mên.'),
(7985, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 30, 6, 'OT', 'Đa-vít rất buồn bã, vì dân chúng nói sẽ ném đá người; linh hồn của toàn thể dân chúng đều đau buồn, mỗi người vì các con trai và các con gái mình. Nhưng Đa-vít được củng cố trong Đức Giê-hô-va là Đức Chúa Trời của người.'),
(7986, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 30, 7, 'OT', 'Đa-vít nói với A-bi-a-tha thầy tế lễ, con trai của A-hi-mê-léc: "Hãy mang áo e-phót đến cho ta." A-bi-a-tha liền mang áo e-phót đến cho Đa-vít.'),
(7987, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 30, 8, 'OT', 'Đa-vít cầu hỏi Đức Giê-hô-va, nói: "Tôi có nên đuổi theo đoàn quân cướp này không? Tôi có đuổi kịp chúng không?" Người đáp lời ông: "Hãy đi đuổi, vì ngươi chắc chắn sẽ đuổi kịp và giải cứu được tất cả."'),
(7988, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 30, 9, 'OT', 'Đa-vít cùng sáu trăm người đi theo ông lên đường, đến khe nước Bê-sô, còn những người ở lại thì dừng lại đó.'),
(7989, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 30, 10, 'OT', 'Đa-vít cùng bốn trăm người theo mình tiếp tục đuổi theo, còn hai trăm người ở lại vì mệt quá không thể vượt qua suối Ba-sô.'),
(7990, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 30, 11, 'OT', 'Họ gặp một người Ai Cập trong đồng ruộng, rồi dẫn anh ta đến gặp Đa-vít; họ đưa cho anh ta bánh và anh ta ăn, và họ cho anh ta uống nước.'),
(7991, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 30, 12, 'OT', 'Họ đưa cho anh ta một miếng bánh vả và hai chùm nho khô; anh ăn xong, thì thần khí anh trở lại, vì anh đã không ăn bánh, cũng không uống nước suốt ba ngày ba đêm.'),
(7992, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 30, 13, 'OT', 'Đa-vít nói với anh ta: "Ngươi thuộc về ai, và từ đâu đến?" Anh ta trả lời: "Tôi là một người trẻ tuổi người Ai Cập, tôi làm đầy tớ cho một người A-ma-léc; chủ tôi đã bỏ tôi lại vì tôi bị bệnh cách đây ba ngày."'),
(7993, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 30, 14, 'OT', 'Chúng tôi đã cướp phá miền Nam của người Kẹ-thê, và vùng đất thuộc về Giu-đa, và miền Nam Ca-lép; còn Xích-lác thì chúng tôi đã thiêu hủy bằng lửa.'),
(7994, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 30, 15, 'OT', 'Đa-vít nói với người ấy: "Ngươi có thể dẫn ta xuống đến toán cướp ấy không?" Người ấy đáp: "Hãy chỉ Đức Chúa Trời mà thề với ta rằng ngươi sẽ không giết ta, cũng không nộp ta vào tay chủ ta; nếu vậy, ta sẽ dẫn ngươi xuống đến toán cướp ấy."'),
(7995, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 30, 16, 'OT', 'Người đưa anh ta xuống, và này, họ đang lan tràn khắp mặt đất, ăn uống và vui mừng, vì tất cả của cải lớn mà họ đã cướp được từ đất Phi-li-tin và từ đất Giu-đa.'),
(7996, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 30, 17, 'OT', 'Đa-vít đánh bại chúng từ lúc hoàng hôn cho đến chiều hôm sau; không một người nào trong chúng thoát khỏi, ngoại trừ bốn trăm thanh niên cỡi lạc đà mà trốn chạy.'),
(7997, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 30, 18, 'OT', 'Đa-vít cứu lại tất cả những gì người A-ma-léc đã cướp lấy; và Đa-vít giải cứu hai người vợ của mình.'),
(7998, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 30, 19, 'OT', 'Không thiếu hụt điều gì của họ, từ kẻ nhỏ đến người lớn, cũng không thiếu con trai hay con gái, cũng không thiếu của cải hay bất cứ điều gì chúng đã cướp lấy; Đa-vít đã giành lại tất cả.'),
(7999, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 30, 20, 'OT', 'Đa-vít lấy tất cả các bầy chiên và bò, chúng được dẫn đi trước đàn gia súc ấy, và người ta nói: "Đây là chiến lợi phẩm của Đa-vít."'),
(8000, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 30, 21, 'OT', 'Đa-vít đến gặp hai trăm người, là những người mệt lả không thể đi theo Đa-vít được nữa, nên đã được ở lại bên suối Ba-sô. Họ ra nghênh đón Đa-vít và những người đi cùng ông. Khi Đa-vít đến gần những người ấy, ông chào họ bình an.'),
(8001, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 30, 22, 'OT', 'Bấy giờ, mọi người đàn ông gian ác và vô đạo trong những người đã đi theo Đa-vít đều lên tiếng, nói rằng: "Vì chúng nó đã không đi cùng chúng ta, nên chúng ta sẽ không chia cho chúng một phần nào trong chiến lợi phẩm mà chúng ta đã giành lại được, ngoại trừ mỗi người được nhận lại vợ mình và con cái mình, rồi dẫn họ đi mà trở về."'),
(8002, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 30, 23, 'OT', 'Đa-vít nói: "Anh em không được làm như vậy, vì điều mà Đức Giê-hô-va đã ban cho chúng ta, và đã bảo vệ chúng ta, và đã trao nhóm quân đội đến tấn công chúng ta vào tay chúng ta."'),
(8003, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 30, 24, 'OT', 'Ai sẽ nghe lời các ngươi về điều nầy? Vì như phần của người xuống chiến trận, thì phần của người ở lại giữ đồ đạc cũng vậy; cả hai sẽ cùng chia đều nhau.'),
(8004, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 30, 25, 'OT', 'Từ ngày ấy trở đi, người đặt ra điều đó làm luật lệ và quy định cho Y-sơ-ra-ên cho đến ngày nay.'),
(8005, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 30, 26, 'OT', 'Và khi Đa-vít đến Xích-lác, ông sai mang một phần chiến lợi phẩm đến các trưởng lão trong xứ Giu-đa, tức các bạn hữu của ông, nói rằng: Này, xin nhận một món quà từ chiến lợi phẩm của những kẻ thù Đức Giê-hô-va.'),
(8006, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 30, 27, 'OT', 'Cho những người ở Bê-tên, và cho những người ở Ra-mốt vùng Nê-ghép, và cho những người ở Gia-tít.'),
(8007, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 30, 28, 'OT', 'Và cho những người ở A-rô-er, và cho những người ở Si-phơ-mốt, và cho những người ở Ê-thê-mô-a.'),
(8008, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 30, 29, 'OT', 'Và cho những người ở Ra-khal, và cho những người ở các thành của người Giê-ra-ha-mê-lít, và cho những người ở các thành của người Kê-nít.'),
(8009, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 30, 30, 'OT', 'Và cho những người ở Hô-rơ-ma, và cho những người ở Bô-rơ A-sán, và cho những người ở A-tách,'),
(8010, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 30, 31, 'OT', 'Và cho những người ở Hếp-rôn, cùng tất cả các nơi mà Đa-vít và những người của ông thường lui tới.'),
(8011, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 31, 1, 'OT', 'Người Phi-li-tin giao chiến cùng Y-sơ-ra-ên; các người Y-sơ-ra-ên chạy trốn khỏi mặt người Phi-li-tin và ngã xuống chết tại núi Ghinh-bô.'),
(8012, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 31, 2, 'OT', 'Người Phi-li-tin đuổi theo Sau-lơ và các con trai ông; người Phi-li-tin giết Giô-na-than, A-bi-na-đáp và Manh-ki-sú, các con trai của Sau-lơ.'),
(8013, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 31, 3, 'OT', 'Chiến tranh trở nên ác liệt chống lại Sa-un; những người bắn cung đã bắn trúng ông, và ông bị thương nặng vì các mũi tên.'),
(8014, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 31, 4, 'OT', 'Sa-un nói với người mang khí giới mình: "Rút gươm ra và đâm ta bằng nó, kẻo những người không chịu cắt bì nầy đến đâm ta và sỉ nhục ta." Nhưng người mang khí giới không chịu, vì người ấy sợ hãi quá đỗi. Vậy nên Sa-un rút gươm ra và xông vào đó.'),
(8015, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 31, 5, 'OT', 'Khi người mang khí giới thấy Sa-un đã chết, người ấy cũng gục xuống trên thanh gươm mình và chết cùng người.'),
(8016, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 31, 6, 'OT', 'Và Sa-un chết, cùng ba người con trai, người mang áo giáp của ông, và tất cả những người của ông, trong ngày ấy, tất cả cùng chết một lúc.'),
(8017, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 31, 7, 'OT', 'Khi những người Ít-ra-en ở phía bên kia thung lũng và những người ở phía bên kia sông Giô-đanh thấy rằng các người Ít-ra-en đã chạy trốn, và rằng Sa-un cùng các con trai người đã chết, thì họ bỏ các thành, chạy trốn; và người Phi-li-tin đến chiếm đóng các thành ấy.'),
(8018, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 31, 8, 'OT', 'Hôm sau, khi người Phi-li-tin đến cướp xác những người chết, thì thấy Sa-un và ba người con trai của người nằm chết trên núi Ghinh-bô.'),
(8019, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 31, 9, 'OT', 'Họ chặt đầu người, lột lấy áo giáp của người, rồi sai đi khắp đất của người Phi-li-tin để loan tin ấy trong đền các thần tượng họ và giữa dân chúng.'),
(8020, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 31, 10, 'OT', 'Họ đặt giáp của người trong đền thờ của Ách-ta-rốt, và treo xác người lên tường thành Bê-th-sán.'),
(8021, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 31, 11, 'OT', 'Dân cư ở Y-abết Ga-la-đát nghe được điều mà người Phi-li-tin đã làm cho Sau-lơ.'),
(8022, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 31, 12, 'OT', 'Tất cả những người tráng sĩ liền đứng dậy, đi suốt đêm, lấy thi thể của Sa-un và các thi thể các con trai ông khỏi tường thành Bết-san, rồi đến Giáp-ên và thiêu đốt các thi thể đó tại đó.'),
(8023, 9, 'GOI_vi', 'GOI_vi', 'vi', '1SA', 31, 13, 'OT', 'Họ lấy những hài cốt của các người ấy, rồi chôn dưới cây sồi tại Gia-be, và nhịn ăn trong bảy ngày.'),
(8024, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 1, 1, 'OT', 'Sau khi Sa-un qua đời, Đa-vít trở về từ cuộc đánh bại người A-ma-léc và ở lại Xi-klác hai ngày.'),
(8025, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 1, 2, 'OT', 'Vào ngày thứ ba, nầy, một người từ trại quân của Sau-lơ đến, quần áo rách nát, đầu phủ bụi đất. Khi người ấy đến cùng Đa-vít, liền sấp mặt xuống đất và cúi lạy.'),
(8026, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 1, 3, 'OT', 'Đa-vít nói với người ấy: "Ngươi từ đâu đến?" Người ấy thưa với ông: "Tôi trốn thoát từ trại quân của Ít-ra-en."'),
(8027, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 1, 4, 'OT', 'Đa-vít nói với người ấy: "Chuyện gì xảy ra vậy? Hãy nói cho tôi biết." Người ấy đáp: "Dân chúng đã bỏ chạy khỏi trận chiến, nhiều người trong dân chúng đã ngã xuống và chết; và Sau-lơ cùng với Giô-na-than, con trai người, cũng đã chết."'),
(8028, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 1, 5, 'OT', 'Đa-vít nói với người trai trẻ thuật lại cho ông: "Làm sao ngươi biết Sa-un và Giô-na-than, con trai ông ấy, đã chết?"'),
(8029, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 1, 6, 'OT', 'Bấy giờ người trẻ tuổi thuật lại cho ông rằng: "Tôi vô tình đi ngang qua núi Ghilboa, thì thấy Sau-lơ đang tựa trên cây giáo của mình; và nầy, các xe và người cỡi ngựa đuổi theo ông rất sát."'),
(8030, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 1, 7, 'OT', 'Tôi quay lại nhìn thấy người ấy, thì người ấy gọi tôi; tôi thưa: Tôi đây.'),
(8031, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 1, 8, 'OT', 'Và người ấy hỏi tôi: "Ông là ai?" Tôi đáp lại người ấy: "Tôi là người A-ma-léc."'),
(8032, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 1, 9, 'OT', 'Người nói với tôi: "Hãy đến gần tôi và giết tôi đi, vì cơn đau đã giáng trên tôi, và hồn tôi vẫn còn nguyên trong tôi."'),
(8033, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 1, 10, 'OT', 'Tôi đã đứng trên người ấy và giết ông ta, vì tôi biết rõ rằng ông ta không thể sống được sau khi ngã xuống; tôi đã lấy mão triều đình trên đầu ông và vòng đeo tay trên cánh tay ông, rồi mang đến đây dâng cho chủ tôi.'),
(8034, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 1, 11, 'OT', 'Đa-vít liền nắm lấy áo mình và xé ra; và tất cả những người đàn ông đi cùng ông cũng làm như vậy.'),
(8035, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 1, 12, 'OT', 'Họ than khóc, khóc lóc và nhịn ăn cho đến chiều vì Sa-un, vì Yô-na-than con trai người, vì dân sự của Đức Giê-hô-va và vì nhà Ít-ra-en, vì họ đã ngã dưới lưỡi gươm.'),
(8036, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 1, 13, 'OT', 'Đa-vít nói với người thanh niên báo tin cho ông: "Ngươi từ đâu đến?" Người ấy đáp: "Tôi là con trai một người ngoại, người A-ma-léc."'),
(8037, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 1, 14, 'OT', 'Đa-vít nói với người ấy: "Làm sao ngươi dám giơ tay giết người được Đức Giê-hô-va xức dầu?"'),
(8038, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 1, 15, 'OT', 'Đa-vít gọi một trong các thiếu niên, rồi nói: "Lại gần, ngã vào người ấy." Người thiếu niên đánh, và người ấy chết.'),
(8039, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 1, 16, 'OT', 'Đa-vít nói với người ấy: "Máu ngươi sẽ đổ trên đầu ngươi, vì chính miệng ngươi đã làm chứng cho ngươi khi nói: Tôi đã giết người được xức dầu của Đức Giê-hô-va."'),
(8040, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 1, 17, 'OT', 'Đa-vít than khóc bài ca than vãn nầy về Sau-lơ và về Giô-na-than, con trai người:'),
(8041, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 1, 18, 'OT', 'Người ra lệnh dạy cho con cái Giu-đa biết dùng cung; nầy, điều đó được chép trong sách của người ngay thẳng.'),
(8042, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 1, 19, 'OT', 'Sự vinh hiển của Y-sơ-ra-ên đã ngã gục trên các nơi cao của ngươi; làm sao các anh hùng đã ngã xuống!'),
(8043, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 1, 20, 'OT', 'Đừng báo tin này tại Gát, đừng loan truyền trong các phố phường của Ách-kê-lôn, e các con gái người Phi-li-tin mừng rỡ, e các con gái của những kẻ không chịu cắt bì nhảy múa ăn mừng.'),
(8044, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 1, 21, 'OT', 'Hỡi các núi Ghích-bo-a, đừng có sương, cũng đừng có mưa trên các ngươi, và đừng có đồng ruộng sinh của lễ; vì tại đó cái khiên của các dũng sĩ bị vứt bỏ, cái khiên của Sau-lơ, như thể người không được xức dầu.'),
(8045, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 1, 22, 'OT', 'Từ máu kẻ bị giết, từ mỡ các dũng sĩ, cây cung của Giô-na-than không rút lại phía sau, và gươm của Sau-lơ không trở về mà không có kết quả.'),
(8046, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 1, 23, 'OT', 'Sa-un và Giô-na-than thật đáng yêu và dễ thương trong đời sống mình, và khi chết họ không rời xa nhau; họ nhanh hơn chim ưng, mạnh hơn sư tử.'),
(8047, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 1, 24, 'OT', 'Hỡi các con gái của Y-sơ-ra-ên, hãy khóc than cho Sau-lơ, người đã cho các ngươi mặc áo đỏ thắm cùng những điều khoái lạc, người đã đeo đồ trang sức bằng vàng trên y phục các ngươi.'),
(8048, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 1, 25, 'OT', 'Than ôi, các anh hùng đã ngã xuống giữa trận chiến! Hỡi Giô-na-than, ngươi đã bị giết trên các nơi cao sang của ngươi.'),
(8049, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 1, 26, 'OT', 'Ta rất đau buồn vì ngươi, hỡi anh ta là Giô-na-than; ngươi thật quá thân thiết với ta; tình yêu của ngươi đối với ta thật lạ lùng, hơn cả tình yêu của đàn bà.'),
(8050, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 1, 27, 'OT', 'Than ôi! Các anh hùng đã ngã xuống, và những khí giới chiến tranh đã bị tiêu mất!'),
(8051, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 2, 1, 'OT', 'Sau những việc ấy, Đa-vít cầu hỏi Đức Giê-hô-va, nói rằng: "Tôi có nên đi lên một trong các thành của Giu-đa không?" Và Đức Giê-hô-va phán cùng người rằng: "Hãy đi lên." Đa-vít lại nói: "Tôi phải đi lên đâu?" Và Ngài phán: "Đi lên Hếp-rôn."'),
(8052, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 2, 2, 'OT', 'Đa-vít lên đó, và hai người vợ của ông cũng đi lên với ông: A-hi-nô-am người Xít-rê-ên và A-bi-gai-ên, vợ của Na-banh người Các-mên.'),
(8053, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 2, 3, 'OT', 'Đa-vít đưa các người của ông cùng đi với ông lên, mỗi người cùng gia đình mình, và họ ở trong các thành của Hếp-rôn.'),
(8054, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 2, 4, 'OT', 'Các người của xứ Giu-đa đến và xức dầu cho Đa-vít tại đó, đặt người làm vua cai trị nhà Giu-đa. Họ cũng báo cho Đa-vít biết rằng: "Các người của Gia-bết Ghi-lê-át là những kẻ đã chôn cất Sau-lơ."'),
(8055, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 2, 5, 'OT', 'Đa-vít sai các sứ giả đến những người ở Gia-ve-sết Ghi-lê-át, và nói với họ: "Nguyện các ngươi được Đức Giê-hô-va ban phước, vì các ngươi đã làm ơn nầy cách nhân từ đối với chủ các ngươi là Sau-lơ, và đã chôn cất người."'),
(8056, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 2, 6, 'OT', 'Và bây giờ, nguyện Đức Giê-hô-va làm ơn và giữ trọn sự thật với các ngươi; và chính ta đây cũng sẽ làm điều tốt lành này cho các ngươi, vì các ngươi đã làm việc nầy.'),
(8057, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 2, 7, 'OT', 'Vì vậy, bây giờ hãy làm cho tay các ngươi mạnh mẽ lên và hãy làm con trai của sự can đảm; vì chủ các ngươi là Sa-un đã chết, và cũng nhà Giu-đa đã xức dầu cho ta làm vua cai trị họ.'),
(8058, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 2, 8, 'OT', 'Và Áp-nê, con trai của Nê, làm tổng trấn quân đội của Sau-lơ, đã đem Ích-bô-xết, con trai của Sau-lơ, và đưa người ấy đến Ma-ha-na-im.'),
(8059, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 2, 9, 'OT', 'Và họ đã lập ông làm vua trên Ga-la-át, trên các người Ashurít, trên Gít-rê-ên, trên Ép-ra-im, trên Bên-gia-min, và trên toàn thể Ít-ra-en.'),
(8060, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 2, 10, 'OT', 'Con trai của Sau-ly, Ích-bô-xét, bốn mươi tuổi khi người bắt đầu trị vì trên Ít-ra-en, và người trị vì hai năm. Nhưng nhà Giu-đa theo Đa-vít.'),
(8061, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 2, 11, 'OT', 'Thời gian Đa-vít làm vua tại Hếp-rôn trên nhà Giu-đa là bảy năm sáu tháng.'),
(8062, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 2, 12, 'OT', 'Áp-ne, con trai của Ner, và các đầy tớ của Ích-bô-xết, con trai của Sau-lơ, ra đi từ Ma-ha-na-im đến Ghi-bê-ôn.'),
(8063, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 2, 13, 'OT', 'Và Giô-áp, con trai của Xê-ru-gia, cùng các đầy tớ của Đa-vít ra đi, và họ gặp nhau bên hồ Ghinh-ôn; những người này ngồi xuống bên này hồ, những người kia ngồi xuống bên kia hồ.'),
(8064, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 2, 14, 'OT', 'Áp-ne nói với Giô-áp: "Các thanh niên hãy đứng dậy và biểu diễn trước mặt chúng ta." Giô-áp đáp: "Họ hãy đứng dậy."'),
(8065, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 2, 15, 'OT', 'Vậy họ đứng dậy và đi qua từng người một, mười hai người thuộc về Bên-gia-min, thuộc về Ích-bô-xét con trai của Sau-lơ, và mười hai người tôi trai của Đa-vít.'),
(8066, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 2, 16, 'OT', 'Họ nắm đầu đồng đội mình, và gươm của mỗi người đâm vào cạnh sườn đồng đội mình; rồi cả hai cùng ngã xuống. Vì vậy, người ta gọi nơi ấy là Hê-lec-hát Ha-xu-rim, ở Ghi-bê-ôn.'),
(8067, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 2, 17, 'OT', 'Trận chiến ngày ấy rất ác liệt. A-bnơ và những người của Ít-ra-en bị đánh bại trước các đầy tớ của Đa-vít.'),
(8068, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 2, 18, 'OT', 'Tại đó có ba con trai của Xê-ru-ya là Giô-áp, A-bi-sai và A-sa-ên; và A-sa-ên nhẹ chân như một trong những con nai rừng.'),
(8069, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 2, 19, 'OT', 'Ách-ách-ên đuổi theo Áp-nê; và khi chạy, người không tẽ sang bên phải cũng chẳng tẽ sang bên trái, mà cứ đi sát sau Áp-nê.'),
(8070, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 2, 20, 'OT', 'Ông Áp-ne quay lại đằng sau, nói: "Anh có phải Á-xa-ên không?" Người kia đáp: "Chính tôi đây."'),
(8071, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 2, 21, 'OT', 'Áp-ne nói với ông: "Hãy chếch sang bên phải hoặc bên trái, rồi bắt một trong các thanh niên kia, và lấy áo giáp của người ấy." Nhưng Ách-va-ên không chịu tấp sang bên để rời khỏi ông.'),
(8072, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 2, 22, 'OT', 'Áp-ne lại nói với A-sa-ên: "Hãy tránh khỏi ta, đi khỏi ta; tại sao ta phải đánh ngươi xuống đất? Rồi làm sao ta dám nhìn mặt Giô-áp, anh ngươi?"'),
(8073, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 2, 23, 'OT', 'Nhưng người ấy từ chối không chịu tránh, nên Áp-ne dùng đầu giáo đâm vào cạnh sườn thứ năm; mũi giáo xuyên ra phía sau người ấy, người ấy ngã xuống tại chỗ và chết tại đó. Khi ấy, bất kỳ ai đến chỗ A-sa-ên ngã xuống và chết đều đứng lại.'),
(8074, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 2, 24, 'OT', 'Ông Giô-áp và ông A-bi-sai đuổi theo ông Áp-ne; mặt trời lặn khi họ đến đồi A-ma, gần Ga-ia, trên đường dẫn đến sa mạc Ghi-bê-ôn.'),
(8075, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 2, 25, 'OT', 'Các con trai của Bên-gia-min nhóm lại sau Áp-nê, và trở thành một đoàn quân, rồi đứng trên đỉnh một ngọn đồi.'),
(8076, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 2, 26, 'OT', 'Áp-ne gọi cho Giô-áp và nói: "Liệu gươm có nuốt trọn mãi không? Há ngươi chẳng biết rằng rồi cuối cùng sẽ xảy ra điều cay đắng sao? Cho đến bao giờ ngươi mới bảo dân chúng thôi đuổi theo anh em mình?"'),
(8077, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 2, 27, 'OT', 'Giô-áp nói: "Nhân danh Đức Chúa Trời hằng sống, nếu ngươi không nói ra, chắc chắn sáng nay dân chúng đã lên đường, mỗi người rời khỏi anh em mình."'),
(8078, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 2, 28, 'OT', 'Vậy Giô-áp thổi kèn, và toàn thể dân chúng dừng lại, không đuổi theo dân Ít-ra-en nữa, cũng không còn chiến đấu nữa.'),
(8079, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 2, 29, 'OT', 'A-bnê và những người của ông đi suốt đêm ấy qua đồng bằng, rồi băng qua sông Giô-đanh, đi qua toàn bộ Bít-ron, và đến Ma-ha-na-im.'),
(8080, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 2, 30, 'OT', 'Giô-áp trở về sau khi rời khỏi Áp-ne; rồi ông tập hợp toàn thể dân chúng. Khi điểm số các đầy tớ của Đa-vít, thì thiếu mất mười chín người và Á-xa-ên.'),
(8081, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 2, 31, 'OT', 'Nhưng các đầy tớ của Đa-vít đã đánh giết người Bên-gia-min và các người của Áp-ne, khiến ba trăm sáu mươi người chết.'),
(8082, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 2, 32, 'OT', 'Họ khiêng thi thể A-sa-ên và chôn ông trong mộ phần của cha ông tại Bết-lê-hem. Còn Giô-áp và những người theo ông thì đi suốt đêm, và họ đến Hếp-rôn lúc trời vừa hừng sáng.'),
(8083, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 1, 'OT', 'Có sự chiến tranh kéo dài giữa nhà Sau-lơ và nhà Đa-vít; và Đa-vít ngày càng mạnh lên, còn nhà Sau-lơ thì ngày càng suy yếu.'),
(8084, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 2, 'OT', 'Đối với Đa-vít, các con trai được sinh ra tại Hếp-rôn; con trai đầu lòng của người là Am-nôn, do A-hi-nô-am, người phụ nữ Giê-xơ-rê-ên.'),
(8085, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 3, 'OT', 'Và người thứ hai là Khi-lê-áp, sinh bởi Abi-ga-yl, vợ của Na-banh người Ca-rơ-mên; người thứ ba là Áp-sa-lôm, con trai của Ma-a-ca, con gái của Tan-mai, vua xứ Ghê-sua.'),
(8086, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 4, 'OT', 'Và người thứ tư là A-đô-ni-gia, con trai của Ha-git; còn người thứ năm là Sê-pha-ti-a, con trai của A-bi-tal.'),
(8087, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 5, 'OT', 'Và người thứ sáu là Y-tream, do Ê-ga-la, vợ của Đa-vít. Những người này được sinh ra cho Đa-vít tại Hếp-rôn.'),
(8088, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 6, 'OT', 'Trong khi có chiến tranh giữa nhà Sau-lơ và nhà Đa-vít, thì Áp-ne càng ngày càng mạnh lên trong nhà Sau-lơ.'),
(8089, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 7, 'OT', 'Sau-lơ có một người hầu thiếp tên là Rít-ba, con gái A-gia. Ích-bô-sết nói với Áp-ne: Sao ngươi lại đi vào với người hầu thiếp của cha ta?'),
(8090, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 8, 'OT', 'A-bnê-r rất tức giận vì những lời của Ích-bô-xết, bèn nói: "Tôi há là đầu chó đối với Giu-đa sao? Ngày nay tôi làm ơn cho nhà Sau-lơ, cha ngươi, cùng các anh em và bạn hữu người, mà không giao ngươi vào tay Đa-vít, vậy mà ngươi hôm nay lại buộc tội tôi về chuyện người đàn bà này?"'),
(8091, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 9, 'OT', 'Nguyện Đức Chúa Trời làm cho Áp-nê điều nầy, và còn làm thêm nhiều điều nữa, nếu tôi không làm cho Đa-vít điều mà Đức Giê-hô-va đã thề cùng Đa-vít.'),
(8092, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 10, 'OT', 'để chuyển vương quốc khỏi nhà Sau-lơ, và thiết lập ngôi báu của Đa-vít trên Ít-ra-en và trên Giu-đa, từ Đan cho đến Bê-e-xê-ba.'),
(8093, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 11, 'OT', 'Và ông không thể đáp lại một lời nào với Áp-ne, vì ông sợ ông ấy.'),
(8094, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 12, 'OT', 'Áp-ne sai các sứ giả đến gặp Đa-vít nhân danh ông, nói: "Đất nầy thuộc về ai? Hãy lập giao ước với tôi, và nầy, tay tôi sẽ ở cùng ông, để quy tụ toàn thể Y-sơ-ra-ên về với ông."'),
(8095, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 13, 'OT', 'Đa-vít nói: "Tốt; Ta sẽ lập giao ước với ngươi, nhưng Ta chỉ yêu cầu ngươi một điều: Ngươi sẽ không được thấy mặt Ta, nếu ngươi không mang đến cho Ta Míchal, con gái của Sau-lơ, khi ngươi đến để gặp mặt Ta."'),
(8096, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 14, 'OT', 'Đa-vít sai các sứ giả đến Ích-bô-sết, con trai của Sau-lơ, nói rằng: "Hãy trả lại vợ tôi là Mi-kal, người mà tôi đã đính hôn với tôi bằng một trăm bộ phận cắt bì của người Phi-li-tin."'),
(8097, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 15, 'OT', 'Bàn-sát sai người đi, và người ấy đem nàng về, khỏi chồng nàng, khỏi Pha-lơ-ti-ên con trai của La-xích.'),
(8098, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 16, 'OT', 'Người chồng đi theo nàng, vừa đi vừa khóc sau lưng nàng cho đến Bê-hu-rim. Rồi Áp-ne nói với người ấy: "Hãy đi trở về." Và người ấy liền trở về.'),
(8099, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 17, 'OT', 'Áp-ne đã nói chuyện với các trưởng lão của Y-sơ-ra-ên rằng: "Trước đây, cả ngày hôm qua và ngày kia nữa, các ông đã tìm Đa-vít làm vua cai trị các ông."'),
(8100, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 18, 'OT', 'Bây giờ hãy làm điều đó, vì Đức Giê-hô-va đã phán về Đa-vít rằng: "Nhờ tay Đa-vít, tôi tớ ta, ta sẽ cứu dân ta là Y-sơ-ra-ên khỏi tay người Phi-li-tin và khỏi tay mọi kẻ thù nghịch của chúng."'),
(8101, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 19, 'OT', 'Áp-ne cũng nói vào tai người Bên-gia-min; rồi Áp-ne đi đến Đa-vít tại Hếp-rôn, nói với ông mọi điều tốt đẹp trong mắt Ít-ra-en và trong mắt cả nhà Bên-gia-min.'),
(8102, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 20, 'OT', 'Áp-ne đến cùng Đa-vít tại Hếp-rôn, và hai mươi người cùng đi với ông. Đa-vít đã đãi Áp-ne và những người đi cùng ông một bữa tiệc.'),
(8103, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 21, 'OT', 'Áp-ne nói với Đa-vít: "Tôi sẽ đứng dậy đi và tập hợp toàn thể Y-sơ-ra-ên đến cùng chủ nhân tôi là vua, để họ lập giao ước với ngài, và ngài sẽ trị vì trên tất cả những điều lòng ngài mong ước." Rồi Đa-vít tiễn Áp-ne đi, và ông ấy ra đi bình an.'),
(8104, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 22, 'OT', 'Nầy, các đầy tớ của Đa-vít và Giô-áp từ cuộc hành quân trở về, mang theo rất nhiều chiến lợi phẩm; nhưng Áp-ne thì không ở cùng với Đa-vít tại Hếp-rôn, vì người đã sai ông đi rồi, và ông đã ra đi an toàn.'),
(8105, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 23, 'OT', 'Khi Giô-áp và toàn thể đạo quân đi cùng ông trở về, người ta báo cho Giô-áp rằng: "A-bi-nê, con trai của Nê, đã đến gặp vua, và vua đã cho ông ấy đi, nên ông ấy đã ra đi bình an."'),
(8106, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 24, 'OT', 'Vậy, Giô-áp đến cùng vua và nói: "Ngài đã làm điều gì vậy? Kìa, Áp-ne đã đến cùng ngài; tại sao ngài lại để ông ấy đi, và ông ấy đã đi mất rồi?"'),
(8107, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 25, 'OT', 'Ngươi biết A-bi-ne-r, con trai của Nê-er, rằng nó đến để lừa dối ngươi, và để dò xét đường ra vào của ngươi, và để biết mọi điều ngươi làm.'),
(8108, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 26, 'OT', 'Giô-áp đi ra khỏi cùng với Đa-vít, rồi sai các sứ giả đuổi theo Áp-ne, và họ đã dẫn Áp-ne trở lại từ cái giếng Si-ra; nhưng Đa-vít không biết điều đó.'),
(8109, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 27, 'OT', 'Khi Áp-ne trở về Hếp-rôn, thì Giô-áp đưa ông sang một bên ở giữa cửa thành để nói chuyện riêng; nhưng tại đó, ông đã đánh ông vào bụng khiến ông chết, để báo thù cho máu của A-sa-ên, anh mình.'),
(8110, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 28, 'OT', 'Sau đó, khi Đa-vít nghe chuyện này, người nói: "Ta và triều đại ta trọn đời vô tội trước mặt Đức Giê-hô-va về huyết của Áp-ne, con trai Nê-er."'),
(8111, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 29, 'OT', 'Đáng nguyền rủa đổ trên đầu của Giô-ab và trên toàn thể nhà cha người ấy; và đừng để nhà Giô-ab thiếu người bị lở loét, hay người bị phung, hay người phải chống gậy, hay người ngã dưới lưỡi gươm, hay người thiếu bánh ăn.'),
(8112, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 30, 'OT', 'Giô-áp và A-bi-sai, anh em người, đã giết Áp-ne, vì người đã giết A-xa-ên, anh em họ, tại Ghi-bê-ôn trong lúc chiến trận.'),
(8113, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 31, 'OT', 'Đa-vít nói với Giô-áp và với toàn thể dân chúng đi cùng ông: "Hãy xé áo mình, thắt túi vải gai vào người và khóc than trước mặt Áp-ne." Vua Đa-vít đi theo linh cữu.'),
(8114, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 32, 'OT', 'Họ chôn A-bnê ở Hếp-rôn; rồi vua cất tiếng khóc, than khóc bên mộ A-bnê; và toàn thể dân chúng đều khóc.'),
(8115, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 33, 'OT', 'Vua khóc than cho Áp-nê và nói: "Áp-nê chết như một kẻ ngu dại sao?"'),
(8116, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 34, 'OT', 'Tay ngươi không bị trói, chân ngươi cũng không bị xiềng; ngươi ngã như một người ngã trước mặt những kẻ ác. Toàn thể dân chúng lại khóc than người.'),
(8117, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 35, 'OT', 'Dân chúng đều đến khuyên Đa-vít ăn bánh khi mặt trời còn chưa lặn, nhưng Đa-vít thề mà rằng: Đức Chúa Trời sẽ xử với tôi như vậy và còn tệ hơn nữa, nếu tôi nếm bánh hay bất cứ vật gì trước khi mặt trời lặn.'),
(8118, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 36, 'OT', 'Toàn dân nhận biết điều đó, và điều ấy đẹp lòng họ; mọi việc vua làm đều đẹp lòng toàn dân.'),
(8119, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 37, 'OT', 'Ngày ấy, mọi người dân và toàn thể Y-sơ-ra-ên đều hiểu rằng việc giết A-vnê, con trai của Nê, không phải do vua.'),
(8120, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 38, 'OT', 'Vua nói với các tôi tớ mình: "Các ngươi há không biết rằng hôm nay một người lãnh tụ và một người vĩ đại đã ngã gục trong Y-sơ-ra-ên?"'),
(8121, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 3, 39, 'OT', 'Vả tôi nay còn yếu đuối, dù đã được xức vua; còn những người nầy, con trai của Xê-ru-i-a, thì mạnh hơn tôi. Đức Giê-hô-va sẽ báo ứng kẻ làm ác tùy theo sự ác của hắn.'),
(8122, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 4, 1, 'OT', 'Khi con trai của Sa-un nghe tin Áp-ne đã chết tại Hếp-rôn, thì tay người trở nên yếu ớt, và toàn thể dân Ít-ra-en đều hoảng sợ.'),
(8123, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 4, 2, 'OT', 'Con trai của Sau-lơ có hai người chỉ huy các toán quân; tên một người là Ba-a-nah, tên người kia là Rê-cáp, là các con trai của Rim-môn, người Bê-e-rot, thuộc con cháu Bên-gia-min. (Vì Bê-e-rot cũng được kể thuộc Bên-gia-min.)'),
(8124, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 4, 3, 'OT', 'Các người Bê-e-rot trốn đến Gít-ta-im và sống làm khách lạ tại đó cho đến ngày nay.'),
(8125, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 4, 4, 'OT', 'Con trai của Giô-na-than, con trai vua Sa-un, là một đứa trẻ bị tật ở chân. Khi tin tức về cái chết của Sa-un và Giô-na-than từ Y-xơ-ranh truyền đến, nó mới được năm tuổi. Người vú nuôi bế nó chạy trốn, nhưng khi đang vội vã đào tẩu thì nó bị ngã, khiến nó què. Tên của nó là Mê-phi-bô-sết.'),
(8126, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 4, 5, 'OT', 'Hai con trai của Rimon người Bê-rốt, là Rê-káp và Ba-a-nah, ra đi và đến nhà Ích-bô-xết vào lúc nắng trưa, lúc người đang nằm nghỉ trên giường.'),
(8127, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 4, 6, 'OT', 'Họ vào giữa nhà như thể đi lấy lúa mì, rồi đánh ông ta vào cạnh sườn; còn Rê-cáp và Ba-a-nah, anh em ông ấy, thì trốn thoát.'),
(8128, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 4, 7, 'OT', 'Họ vào nhà, thì thấy người ấy đang nằm trên giường trong buồng ngủ của mình. Họ đánh và giết người ấy, rồi chặt đầu người ấy. Họ lấy đầu người ấy và đi suốt đêm qua đồng bằng.'),
(8129, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 4, 8, 'OT', 'Họ mang đầu của Ích-bô-xết đến cho Đa-vít tại Hếp-rôn và nói với vua rằng: "Này là đầu của Ích-bô-xết, con trai Sau-lơ, kẻ thù của ngài, là người đã tìm mạng sống ngài. Ngày nay, Đức Giê-hô-va đã báo thù cho ngài, là chủ tôi, vua, khỏi Sau-lơ và dòng dõi người."'),
(8130, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 4, 9, 'OT', 'Đức vua Đa-vít đáp với Rê-káp và Ba-a-nah, anh em của hắn, hai con trai của Rim-môn người Bê-e-rot, và nói với họ: "Đức Giê-hô-va hằng sống, Đấng đã cứu mạng ta khỏi mọi cảnh khốn khó,"'),
(8131, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 4, 10, 'OT', 'Vì người báo cho tôi rằng: "Này, Sau-lơ đã chết", và tưởng rằng mình đang mang tin mừng; nhưng tôi đã bắt lấy hắn, giết hắn tại Xích-lác, vì nghĩ rằng hắn mong tôi thưởng cho tin đó.'),
(8132, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 4, 11, 'OT', 'Huống chi những kẻ ác đã giết một người công chính ngay trong nhà mình, trên giường mình; lẽ nào ta chẳng đòi huyết người ấy từ tay các ngươi và tiêu diệt các ngươi khỏi đất sao?'),
(8133, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 4, 12, 'OT', 'Đa-vít truyền lệnh cho các đầy tớ, họ liền giết những người đó, chặt tay và chân họ, rồi treo lên bên cạnh hồ ở Hếp-rôn. Còn đầu của Ích-bô-sết, họ lấy đi và chôn trong mộ của Áp-nê tại Hếp-rôn.'),
(8134, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 5, 1, 'OT', 'Hết thảy các chi phái của Y-sơ-ra-ên đều đến cùng Đa-vít tại Hếp-rôn và nói rằng: "Nầy, chúng tôi là xương thịt của ngài."'),
(8135, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 5, 2, 'OT', 'Cả hôm qua lẫn ngày trước nữa, khi Sa-un làm vua trên chúng tôi, chính ngươi đã dẫn dân Ít-ra-en ra vào; và Đức Giê-hô-va đã phán cùng ngươi: Ngươi sẽ chăn dắt dân ta là Ít-ra-en, và ngươi sẽ làm lãnh tụ trên Ít-ra-en.'),
(8136, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 5, 3, 'OT', 'Vậy, tất cả các trưởng lão của Y-sơ-ra-ên đến cùng vua tại Hếp-rôn; và vua Đa-vít lập giao ước với họ tại Hếp-rôn trước mặt Đức Giê-hô-va; rồi họ xức dầu cho Đa-vít làm vua trên Y-sơ-ra-ên.'),
(8137, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 5, 4, 'OT', 'Đa-vít được ba mươi tuổi khi người bắt đầu làm vua, và người trị vì bốn mươi năm.'),
(8138, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 5, 5, 'OT', 'Tại Hếp-rôn, ông làm vua cai trị trên Giu-đa bảy năm sáu tháng; tại Giê-ru-sa-lem, ông làm vua ba mươi ba năm trên toàn thể Ít-ra-en và Giu-đa.'),
(8139, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 5, 6, 'OT', 'Vua và những người theo vua đi đến Giê-ru-sa-lem để gặp người Y-bu-si, là dân sống ở trong xứ; người Y-bu-si nói với Đa-vít rằng: "Ngươi không được vào đây, nếu không đuổi được những kẻ mù và què"; họ nghĩ rằng: "Đa-vít sẽ không thể vào đây được."'),
(8140, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 5, 7, 'OT', 'Đa-vít chiếm lấy pháo đài Xi-ôn; đó là thành của Đa-vít.'),
(8141, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 5, 8, 'OT', 'Đa-vít nói trong ngày ấy: "Ai đánh người Y-bu-si và xâm nhập qua ống dẫn nước, và đánh những kẻ què và mù mà linh hồn Đa-vít ghét bỏ, thì hãy đánh nó." Vì vậy, người ta nói: "Kẻ mù và kẻ què không được vào trong nhà."'),
(8142, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 5, 9, 'OT', 'Đa-vít ở trong pháo đài, và ông đặt tên cho đó là thành của Đa-vít. Đa-vít xây cất xung quanh từ Mi-lô trở vào trong.'),
(8143, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 5, 10, 'OT', 'Đa-vít tiếp tục đi lên và trở nên cường thịnh, và Đức Giê-hô-va Đức Chúa Trời của các đạo binh ở cùng ông.'),
(8144, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 5, 11, 'OT', 'Vua Hi-ram của thành Ty-rơ sai các sứ giả đến cùng Đa-vít, cùng với các cây gỗ bá hương, thợ mộc và thợ xây đá; và họ đã xây một ngôi nhà cho Đa-vít.'),
(8145, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 5, 12, 'OT', 'Đa-vít biết rằng Đức Giê-hô-va đã lập ông làm vua trên Ít-ra-en, và rằng Ngài đã nâng cao vương quốc ông vì cớ dân Ngài là Ít-ra-en.'),
(8146, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 5, 13, 'OT', 'Đa-vít lại lấy thêm các thứ thiếp và vợ từ Giê-ru-sa-lem, sau khi người đến từ Hếp-rôn; và lại có các con trai và con gái được sinh ra cho Đa-vít.'),
(8147, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 5, 14, 'OT', 'Đây là các tên của những người con sinh ra cho ông tại Giê-ru-sa-lem: Sam-mu-ên, và Sô-báp, và Na-than, và Sa-lô-môn.'),
(8148, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 5, 15, 'OT', 'Ib-har, E-li-sú, Né-peg và Ja-phi-a,'),
(8149, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 5, 16, 'OT', 'Ê-li-sa-ma, Ê-li-a-đa và Ê-li-pha-lết.'),
(8150, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 5, 17, 'OT', 'Khi người Phi-li-tin nghe đồn rằng người ta đã xức dầu cho Đa-vít làm vua trên Ít-ra-en, thì toàn thể người Phi-li-tin kéo lên để tìm Đa-vít. Đa-vít nghe được điều đó, liền đi xuống đồn bảo vệ.'),
(8151, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 5, 18, 'OT', 'Người Phi-li-tin đến và rải ra trong thung lũng Rê-pha-im.'),
(8152, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 5, 19, 'OT', 'Đa-vít cầu hỏi Đức Giê-hô-va, nói: "Tôi có nên đi lên đánh người Phi-li-tin không? Ngài có trao họ vào tay tôi không?" Đức Giê-hô-va đáp với Đa-vít: "Hãy đi lên, vì Ta sẽ chắc chắn trao người Phi-li-tin vào tay ngươi."'),
(8153, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 5, 20, 'OT', 'Đa-vít đến Ba-al Pha-ra-zim, và tại đó ông đánh bại chúng. Đa-vít nói: "Đức Giê-hô-va đã xông ra phá tan quân thù tôi trước mặt tôi như nước vỡ bờ." Vì vậy, ông đặt tên cho nơi ấy là Ba-al Pha-ra-zim.'),
(8154, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 5, 21, 'OT', 'Bấy giờ chúng bỏ các hình tượng của chúng tại đó, và Đa-vít cùng các người của ông đã mang chúng đi.'),
(8155, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 5, 22, 'OT', 'Người Phi-li-tin lại tiếp tục kéo đến và trải ra trong thung lũng Rê-pha-im.'),
(8156, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 5, 23, 'OT', 'Đa-vít cầu hỏi Đức Giê-hô-va, và Ngài phán: "Ngươi chớ lên; hãy vòng ra phía sau chúng nó, rồi đến gần chúng nó đối diện với các cây bách hương."'),
(8157, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 5, 24, 'OT', 'Khi ngươi nghe tiếng động nơi ngọn các cây dâu, thì phải nhanh chóng hành động, vì Đức Giê-hô-va sẽ đi ra trước mặt ngươi để đánh bại đạo quân của dân Phi-li-tin.'),
(8158, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 5, 25, 'OT', 'Đa-vít làm như vậy, y như ĐỨC Giê-hô-va đã truyền cho ông, và đánh bại người Phi-li-tin từ Gê-ba cho đến khi đến Gát-xe.'),
(8159, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 6, 1, 'OT', 'Đa-vít tiếp tục triệu tập tất cả những người trai tráng chọn lọc trong Ít-ra-en, ba mươi ngàn người.'),
(8160, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 6, 2, 'OT', 'Đa-vít chỗi dậy và đi cùng với toàn thể dân sự đi theo ông từ Ba-a-lê của Giu-đa, để mang lên từ đó rương của Đức Chúa Trời, trên đó được gọi bằng danh hiệu Đức Giê-hô-va các đạo binh, Đấng ngự trên các con trâu thiêng.'),
(8161, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 6, 3, 'OT', 'Họ đặt rương của Đức Chúa Trời lên một cái xe mới, rồi khiêng nó ra từ nhà A-bi-na-đáp ở Ghíp-ê-ah; còn U-xa và A-hi-ô, hai con trai của A-bi-na-đáp, thì điều khiển cái xe mới ấy.'),
(8162, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 6, 4, 'OT', 'Họ khiêng hòm từ nhà A-bi-na-đáp ở trên đồi, cùng với hòm của Đức Chúa Trời; còn A-hi-ô thì đi trước hòm.'),
(8163, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 6, 5, 'OT', 'Và Đa-vít cùng với cả nhà Ít-ra-en nhảy múa trước mặt Đức Giê-hô-va bằng mọi thứ đàn bằng gỗ thông, bằng đờn cầm, đờn lia, trống cơm, nhạc cụ rung và chập chỏa.'),
(8164, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 6, 6, 'OT', 'Khi họ đến nơi sân đập lúa của Nakhon, thì U-xa đưa tay ra với hòm của Đức Chúa Trời và nắm lấy nó, vì các con bò đã làm nó xô nghiêng.'),
(8165, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 6, 7, 'OT', 'Cơn thịnh nộ của Đức Giê-hô-va nổi lên nghịch cùng U-xa; và Đức Chúa Trời đánh người tại đó vì đã với tay vào hòm; và người chết tại đó bên cạnh hòm của Đức Chúa Trời.'),
(8166, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 6, 8, 'OT', 'Đa-vít nổi giận vì Đức Giê-hô-va đã giáng cơn thịnh nộ trên Út-xa, nên người đặt tên cho nơi ấy là Phê-rết Út-xa cho đến ngày nay.'),
(8167, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 6, 9, 'OT', 'Đa-vít sợ Đức Giê-hô-va ngày hôm ấy, và nói: "Làm sao hòm giao ước Đức Giê-hô-va có thể đến cùng tôi được?"'),
(8168, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 6, 10, 'OT', 'Đa-vít không chịu mang rương của Đức Giê-hô-va về thành Đa-vít; nhưng Đa-vít mang rương ấy vào nhà Ô-bết Ê-đôm, người Ghít.'),
(8169, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 6, 11, 'OT', 'Hòm giao ước của Đức Giê-hô-va ở trong nhà của Ô-bếp Ê-đôm người Ghít-thi trong ba tháng; và Đức Giê-hô-va ban phước cho Ô-bếp Ê-đôm và cho cả nhà người.'),
(8170, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 6, 12, 'OT', 'Và người ta báo cho vua Đa-vít biết rằng: "Đức Giê-hô-va đã ban phước cho nhà Ô-bết-Ê-đôm và cho mọi điều thuộc về người, vì hòm của Đức Chúa Trời." Bấy giờ, Đa-vít đi và rước hòm của Đức Chúa Trời từ nhà Ô-bết-Ê-đôm về thành Đa-vít trong niềm vui mừng.'),
(8171, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 6, 13, 'OT', 'Khi những người khiêng hòm giao ước của Đức Giê-hô-va đã đi được sáu bước, thì người ta dâng một con bò đực và một con thú béo tốt.'),
(8172, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 6, 14, 'OT', 'Đa-vít nhảy múa hết sức mình trước mặt Đức Giê-hô-va; và Đa-vít thắt một cái y xê-ri bằng vải gai.'),
(8173, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 6, 15, 'OT', 'Vậy Đa-vít và toàn thể nhà Ít-ra-en khiêng hòm giao ước của Đức Giê-hô-va lên với tiếng hô vang và tiếng kèn loa.'),
(8174, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 6, 16, 'OT', 'Khi hòm giao ước của Đức Giê-hô-va vào thành Đa-vít, Mi-kal, con gái của Sau-lơ, nhìn qua cửa sổ và thấy vua Đa-vít nhảy mừng và múa lượn trước mặt Đức Giê-hô-va; nàng bèn khinh bỉ người trong lòng mình.'),
(8175, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 6, 17, 'OT', 'Họ mang rương của Đức Giê-hô-va đến và đặt nó vào chỗ của nó, ở giữa mái lều mà Đa-vít đã dựng lên cho nó; rồi Đa-vít dâng các của lễ thiêu và các của lễ thù ân trước mặt Đức Giê-hô-va.'),
(8176, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 6, 18, 'OT', 'Sau khi Đa-vít dâng xong của lễ thiêu và của lễ thù ân, người chúc phước cho dân chúng nhân danh Đức Giê-hô-va Toàn năng.'),
(8177, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 6, 19, 'OT', 'Người chia cho toàn thể dân chúng Ít-ra-en, mỗi người, nam cũng như nữ, một ổ bánh mì, một khối thịt nướng và một bánh nho khô. Rồi toàn thể dân chúng đều trở về nhà mình.'),
(8178, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 6, 20, 'OT', 'Đa-vít trở về để ban phước cho gia đình mình. Rồi Mi-kal, con gái của Sau-ôn, đi ra đón Đa-vít và nói: "Hôm nay vua Ít-ra-en đã tự tôn vinh mình cách nào vậy, khi ông để lộ mình ra trước mắt các nữ tì của các đầy tớ mình, như một trong những tên vô lại phô mình ra vậy!"'),
(8179, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 6, 21, 'OT', 'Đa-vít nói với Mi-kal: "Tôi đã nhảy múa trước mặt Đức Giê-hô-va, Đấng đã chọn tôi hơn cha cô và hơn cả nhà người ấy, để lập tôi làm người cai trị trên dân Đức Giê-hô-va, trên Ít-ra-en; vì vậy tôi sẽ nhảy múa trước mặt Đức Giê-hô-va."'),
(8180, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 6, 22, 'OT', 'Và tôi sẽ tự hạ mình xuống thấp hơn nữa, và tôi sẽ coi mình như chẳng đáng gì; nhưng với các nữ tì mà ngươi đã nói đến, tôi sẽ được tôn trọng.'),
(8181, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 6, 23, 'OT', 'Mical, con gái của Sa-un, không có con trai nào cho đến ngày cô qua đời.'),
(8182, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 7, 1, 'OT', 'Khi vua đang ngự trong nhà mình, thì Đức Giê-hô-va đã cho người được an nghỉ xung quanh khỏi mọi kẻ thù của người.'),
(8183, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 7, 2, 'OT', 'Vua nói cùng nhà tiên tri Na-than: "Nầy, tôi đang ở trong một ngôi nhà bằng gỗ hương, còn hòm của Đức Chúa Trời thì ở trong lều vải."'),
(8184, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 7, 3, 'OT', 'Na-than nói với vua: "Cứ làm tất cả những điều trong lòng vua muốn, vì Đức Giê-hô-va ở cùng vua."'),
(8185, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 7, 4, 'OT', 'Đoạn ấy xảy ra trong đêm đó, thì có lời của Đức Giê-hô-va phán cùng Na-than rằng,'),
(8186, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 7, 5, 'OT', 'Hãy đi và nói cùng đầy tớ Ta là Đa-vít rằng: Đức Giê-hô-va phán như vầy: Ngươi há sẽ xây cho Ta một nhà để Ta ở sao?'),
(8187, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 7, 6, 'OT', 'Ta chưa hề ở trong ngôi nhà nào từ khi Ta đem con cái Y-sơ-ra-ên ra khỏi Ai-cập cho đến ngày nay; Ta chỉ đi qua đi lại trong một cái lều và một trại tạm.'),
(8188, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 7, 7, 'OT', 'Trong mọi nơi Ta đi cùng với mọi con cái Y-sơ-ra-ên, Ta đã nói lời nào với một trong các chi phái Y-sơ-ra-ên, mà Ta đã chỉ định để chăn giữ dân Ta, là Y-sơ-ra-ên, rằng: "Tại sao các ngươi không xây cho Ta một ngôi nhà bằng gỗ hương?"'),
(8189, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 7, 8, 'OT', 'Bây giờ, ngươi hãy nói cùng đầy tớ ta là Đa-vít rằng: Đức Giê-hô-va vạn quân phán thế nầy: Chính Ta đã đem ngươi từ nơi đồng cỏ, từ đàng sau bầy chiên, để làm người lãnh đạo trên dân ta, trên Y-sơ-ra-ên.'),
(8190, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 7, 9, 'OT', 'Ta đã ở cùng ngươi trong mọi nơi ngươi đi, đã tiêu diệt mọi kẻ thù ngươi khỏi trước mặt ngươi, và đã làm cho ngươi được danh tiếng lẫy lừng, như danh tiếng của những người nổi tiếng trên đất.'),
(8191, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 7, 10, 'OT', 'Ta sẽ định một chỗ cho dân Ta là Y-sơ-ra-ên, sẽ trồng họ xuống để họ cư ngụ tại đó và không còn bị lay chuyển nữa; con cái sự gian ác sẽ không còn làm họ khốn khổ như thời xưa.'),
(8192, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 7, 11, 'OT', 'Kể từ ngày Ta truyền các quan xét xử cai trị trên dân Ta là Y-sơ-ra-ên, và khiến ngươi được an nghỉ khỏi mọi kẻ thù ngươi, thì Đức Giê-hô-va phán cùng ngươi rằng: Đức Giê-hô-va sẽ cho ngươi một nhà.'),
(8193, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 7, 12, 'OT', 'Khi các ngày của ngươi được đầy đủ và ngươi nằm nghỉ cùng với các tổ phụ ngươi, thì Ta sẽ làm cho dòng dõi ngươi, sinh ra từ ngươi, được nối ngôi, và Ta sẽ củng cố vương quốc người ấy.'),
(8194, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 7, 13, 'OT', 'Người sẽ xây một nhà cho danh Ta, và Ta sẽ lập vững ngôi vương quyền của người đến mãi mãi.'),
(8195, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 7, 14, 'OT', 'Ta sẽ làm cha của nó, và nó sẽ làm con của Ta. Nếu nó phạm tội, Ta sẽ sửa phạt nó bằng roi của loài người và bằng những vết roi của con cái loài người.'),
(8196, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 7, 15, 'OT', 'Nhưng sự thương xót của Ta sẽ không rời khỏi người, như Ta đã rút khỏi Sau-lơ, người Ta đã loại khỏi mặt ngươi.'),
(8197, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 7, 16, 'OT', 'Và nhà của ngươi cùng vương quyền của ngươi sẽ được kiên định mãi mãi trước mặt ngươi; ngai ngươi sẽ được lập vững chắc mãi mãi.'),
(8198, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 7, 17, 'OT', 'Theo tất cả những lời nầy, và theo tất cả thị kiến nầy, thì Nát-an nói cho Đa-vít như vậy.'),
(8199, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 7, 18, 'OT', 'Vua Đa-vít vào, ngồi trước mặt Đức Giê-hô-va và nói: "Tôi là ai, thưa Chúa là Đức Giê-hô-va, và nhà tôi là gì, mà Ngài đã đưa tôi đến mức này?"'),
(8200, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 7, 19, 'OT', 'Lại còn điều nầy nữa, thật nhỏ bé trong mắt Chúa, lạy Đức Giê-hô-va, nhưng Chúa đã phán thêm về nhà của đầy tớ Chúa cho một thời gian lâu dài; và điều nầy là luật lệ của loài người, lạy Đức Giê-hô-va?'),
(8201, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 7, 20, 'OT', 'Và còn điều gì nữa Đa-vít có thể nói cùng Ngài chăng? Vì chính Ngài, Chúa Giê-hô-va, biết rõ đầy tớ của Ngài.'),
(8202, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 7, 21, 'OT', 'Vì cớ lời Ngài và theo ý muốn của Ngài, Ngài đã làm tất cả những điều lớn lao nầy, để cho tôi tớ Ngài biết.'),
(8203, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 7, 22, 'OT', 'Vì vậy, Đức Giê-hô-va Đức Chúa Trời, Ngài thật vĩ đại; vì không ai sánh bằng Ngài, và không có Đức Chúa Trời nào ngoài Ngài, theo mọi điều chúng tôi đã nghe bằng tai mình.'),
(8204, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 7, 23, 'OT', 'Và ai bằng dân Ngài trong các nước, hỡi Y-sơ-ra-ên, một dân duy nhất trên đất, mà Đức Chúa Trời đã đi ra để chuộc lấy cho Ngài làm dân riêng, và để đặt danh cho Ngài, và để làm những việc lớn lao và khủng khiếp cho đất nước Ngài, trước mặt dân Ngài mà Ngài đã chuộc khỏi Ai-cập, tức các dân tộc và các thần của chúng?'),
(8205, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 7, 24, 'OT', 'Và Ngài đã lập cho mình dân Y-sơ-ra-ên làm dân thuộc về Ngài mãi mãi; còn Ngài, Đức Giê-hô-va, đã trở nên Đức Chúa Trời của họ.'),
(8206, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 7, 25, 'OT', 'Và bây giờ, Đức Giê-hô-va Đức Chúa Trời ơi, xin làm vững bền điều mà Ngài đã phán về tôi tớ Ngài và về nhà của người, mãi mãi; và xin làm như điều Ngài đã phán.'),
(8207, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 7, 26, 'OT', 'Nguyện danh Ngài được tôn cao đời đời, để người ta nói: "Đức Giê-hô-va các đạo quân là Đức Chúa Trời trên Ít-ra-en"; và nguyện nhà của đầy tớ Ngài là Đa-vít được lập vững chắc trước mặt Ngài.'),
(8208, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 7, 27, 'OT', 'Vì chính Ngài, Đức Giê-hô-va các đạo binh, Đức Chúa Trời của Y-sơ-ra-ên, đã tỏ cho tôi tớ Ngài biết, rằng: "Ta sẽ xây một ngôi nhà cho ngươi." Bởi vậy, tôi tớ Ngài mới dám đặt trọn lòng mình để cầu nguyện với Ngài lời cầu nguyện nầy.'),
(8209, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 7, 28, 'OT', 'Và bây giờ, Chúa Giê-hô-va, chính Ngài là Đức Chúa Trời, và các lời của Ngài là chân thật; Ngài đã phán cùng tôi tớ Ngài điều thiện tốt nầy.'),
(8210, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 7, 29, 'OT', 'Vì vậy, xin hãy vui lòng ban phước cho nhà của đầy tớ Ngài, để nhà ấy tồn tại mãi mãi trước mặt Ngài; vì chính Ngài, Đức Giê-hô-va, đã phán, và nhờ phước lành của Ngài, nhà của đầy tớ Ngài sẽ được ban phước mãi mãi.'),
(8211, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 8, 1, 'OT', 'Sau những việc ấy, Đa-vít đánh người Phi-li-tin và khuất phục chúng; Đa-vít lấy Mét-gha-ăm-ma ra khỏi tay người Phi-li-tin.'),
(8212, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 8, 2, 'OT', 'Đa-vít đánh Mô-áp, rồi lấy dây đo để định số người phải giết và số người được sống. Ông đo hai dây để giết, và một dây đầy đủ để cho sống. Từ đó, người Mô-áp trở thành đầy tớ phục vụ Đa-vít và nộp cống phẩm.'),
(8213, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 8, 3, 'OT', 'Đa-vít đánh A-ha-đéc-xe, con trai của Rê-hốp, vua nước Xô-ba, khi người đi phục hồi quyền lực của mình tại sông ngạn.'),
(8214, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 8, 4, 'OT', 'Đa-vít bắt được từ hắn một ngàn bảy trăm người cỡi ngựa và hai vạn quân bộ; rồi Đa-vít cắt gân ngựa của tất cả các xe chiến, chỉ để lại một trăm xe cho mình.'),
(8215, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 8, 5, 'OT', 'Khi người A-ram ở Đa-mách đến giúp Ha-đa-đe-xe, vua Xô-ba, thì Đa-vít đánh bại người A-ram và giết hai mươi hai ngàn người.'),
(8216, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 8, 6, 'OT', 'Đa-vít đặt các đội quân đồn trú tại vùng A-ram Đa-mách; và người A-ram trở thành tôi tớ của Đa-vít, phải nộp cống vật. Đức Giê-hô-va phù hộ Đa-vít trong mọi nơi người đi đến.'),
(8217, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 8, 7, 'OT', 'Đa-vít lấy các cái khiên bằng vàng vốn thuộc các đầy tớ của Ha-đa-đe-xe, và mang chúng về Giê-ru-sa-lem.'),
(8218, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 8, 8, 'OT', 'Và từ Bết-ách và từ Bê-rốt-hai, các thành của Ha-đa-đe-xe, vua Đa-vít đã lấy được rất nhiều đồng.'),
(8219, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 8, 9, 'OT', 'Tô-i, vua của Ha-mát, nghe tin Đa-vít đã đánh bại toàn thể đạo quân của Ha-đa-đe-xe.'),
(8220, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 8, 10, 'OT', 'Tô-i sai Giô-ram, con trai mình, đến cùng vua Đa-vít để hỏi thăm và chúc phước cho người, vì người đã chiến đấu cùng Ha-đa-đe-xe và đánh bại hắn; bởi lẽ Ha-đa-đe-xe thường hay gây chiến với Tô-i. Và Giô-ram mang theo những đồ đựng bằng bạc, đồ đựng bằng vàng, và đồ đựng bằng đồng.'),
(8221, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 8, 11, 'OT', 'Vua Đa-vít cũng dâng những thứ đó cho Đức Giê-hô-va, cùng với bạc và vàng mà người đã biệt riêng ra từ mọi dân tộc mà người đã chinh phục.'),
(8222, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 8, 12, 'OT', 'Từ Sy-ri, và từ Mô-áp, và từ con cái Amôn, và từ người Phi-li-tin, và từ A-ma-léc, và từ chiến lợi phẩm của Ha-đa-đe-xe, con trai Rê-hốp, vua Xô-ba.'),
(8223, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 8, 13, 'OT', 'Đa-vít lập được danh tiếng khi trở về sau khi đánh bại người A-ram tại thung lũng Muối, giết chết mười tám ngàn người.'),
(8224, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 8, 14, 'OT', 'Đặt các đội quân canh giữ trong Ê-đôm; khắp mọi nơi ở Ê-đôm, ông đặt các đội quân canh giữ, và toàn thể dân Ê-đôm trở thành đầy tớ của Đa-vít. Đức Giê-hô-va phù trợ Đa-vít trong mọi nơi ông đi đến.'),
(8225, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 8, 15, 'OT', 'Đa-vít làm vua cai trị trên toàn thể Ít-ra-en; và Đa-vít thi hành sự xét xử và công lý đối với toàn thể dân sự của ông.'),
(8226, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 8, 16, 'OT', 'Và Giô-áp, con trai của Xê-ru-ya, làm tổng chỉ huy đạo binh; còn Giô-sa-phát, con trai của A-hi-lút, làm quan ký lục.'),
(8227, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 8, 17, 'OT', 'Xa-đốc, con trai của A-hi-túp, và A-hi-mê-léc, con trai của A-bi-a-tha, làm thầy tế lễ; Xê-rai-ah làm ký lục.'),
(8228, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 8, 18, 'OT', 'Bê-nai-a, con trai của Giô-ya-đa, chỉ huy các người Cherethi và Pelethi; và các con trai của Đa-vít làm các thầy tế lễ.'),
(8229, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 9, 1, 'OT', 'Đa-vít nói: "Còn ai sót lại trong nhà Sau-lơ không, để ta làm ơn cho người ấy vì Giô-na-than?"'),
(8230, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 9, 2, 'OT', 'Và nhà của Sau-lơ có một đầy tớ tên là Xi-ba. Người ta gọi người ấy đến cùng Đa-vít, và vua nói với người ấy: "Ngươi phải là Xi-ba chăng?" Người ấy thưa: "Tôi là đầy tớ của ngài."'),
(8231, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 9, 3, 'OT', 'Vua hỏi: "Nhà Xa-un còn ai sót lại chăng, để ta làm ơn của Đức Chúa Trời cho người ấy?" Xíp-a thưa với vua: "Còn lại một người con của ông Giô-na-than, bị què hai chân."'),
(8232, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 9, 4, 'OT', 'Vua hỏi: "Anh ta ở đâu?" và Xi-ba thưa với vua: "Nầy, anh ta đang ở nhà Ma-kích, con trai Am-mi-ên, tại Lô-đe-ba."'),
(8233, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 9, 5, 'OT', 'Vua Đa-vít sai người đi và đưa anh ấy ra khỏi nhà của Ma-kích, con trai của Am-mi-ên, ở Lô-đe-ba.'),
(8234, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 9, 6, 'OT', 'Mephiboshết, con trai của Yônatan, con trai của Sa-un, đến cùng Đa-vít; người phục xuống, cúi mặt xuống đất. Đa-vít nói: "Mephiboshết!" Người đáp: "Này tôi tớ của ngài!"'),
(8235, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 9, 7, 'OT', 'Đa-vít nói với người ấy: "Đừng sợ, vì tôi sẽ chắc chắn làm ơn cho ngươi vì cớ Giô-na-than, cha ngươi; tôi sẽ trả lại cho ngươi tất cả ruộng đất của Sau-lơ, cha ngươi; và ngươi sẽ ăn bánh trên bàn tôi luôn mãi."'),
(8236, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 9, 8, 'OT', 'Ông ta cúi lạy và nói: Tôi là tôi tớ gì, mà ngài lại để ý đến một con chó chết như tôi đây?'),
(8237, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 9, 9, 'OT', 'Vua truyền cho Xíp-a, đầy tớ của Sau-lơ, và nói với người rằng: "Ta đã ban cho con trai chủ ngươi mọi điều thuộc về Sau-lơ và cả nhà người."'),
(8238, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 9, 10, 'OT', 'Ngươi và các con trai ngươi cùng các đầy tớ của ngươi hãy làm ruộng cho người, và mang sản phẩm về, để con trai chủ ngươi có lương thực để ăn; còn Mê-phi-bô-sết, con trai chủ ngươi, sẽ luôn luôn ăn bánh tại bàn ta. Bấy giờ Xíp-a có mười lăm con trai và hai mươi đầy tớ.'),
(8239, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 9, 11, 'OT', 'Rồi Xípai tâu với vua: "Theo mọi điều mà chúa tôi là vua đã truyền cho đầy tớ mình, thì đầy tớ tôi sẽ làm như vậy. Còn Mê-phi-bô-sết sẽ ăn tại bàn của tôi như một trong các con trai của vua."'),
(8240, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 9, 12, 'OT', 'Mê-phi-bô-sết có một con trai nhỏ, tên là Mi-ca. Tất cả những người ở trong nhà của Xi-ba đều làm đầy tớ cho Mê-phi-bô-sết.'),
(8241, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 9, 13, 'OT', 'Mê-phi-bô-sết sống tại Giê-ru-sa-lem, vì người thường ăn tại bàn vua; và người què cả hai chân.'),
(8242, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 10, 1, 'OT', 'Sau điều đó không lâu, vua của con cái Am-môn qua đời, và Ha-nun, con trai ông, lên ngôi kế vị.'),
(8243, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 10, 2, 'OT', 'Đa-vít nói: "Ta sẽ làm ơn lành cho Ha-nun, con trai của Na-hách, như cha người đã làm ơn lành cho ta." Rồi Đa-vít sai các tôi tớ mình đi, nhân danh mình đến an ủi người vì cớ cha người. Các tôi tớ của Đa-vít đến xứ con cái Am-môn.'),
(8244, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 10, 3, 'OT', 'Các quan trưởng của con cái Amôn nói với Ha-nun, chủ của họ: "Đa-vít tôn vinh cha ngươi trước mặt ngươi sao, mà sai những kẻ an ủi đến cho ngươi? Há chẳng phải Đa-vít sai các đầy tớ mình đến ngươi để dò xét thành phố, do thám và lật đổ nó sao?"'),
(8245, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 10, 4, 'OT', 'Ha-nun bắt các đầy tớ của Đa-vít, cạo một nửa râu của họ, cắt áo họ ở giữa, đến tận mông, rồi đuổi họ đi.'),
(8246, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 10, 5, 'OT', 'Khi người ta thuật lại điều đó cho Đa-vít, ông sai người đi đón họ vì những người ấy rất xấu hổ. Vua nói: "Hãy ở lại Giê-ri-cô cho đến khi râu các ngươi mọc dài ra, rồi hãy trở về."'),
(8247, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 10, 6, 'OT', 'Thấy mình đã đắc tội cùng vua Đa-vít, các con trai của Am-môn liền sai người đi và thuê người Sy-ri ở Bê-thê-rê-hôb, và người Sy-ri ở Xô-ba, hai mươi ngàn bộ binh, và vua Ma-a-ca một ngàn người, cùng người Ích-tô-b mười hai ngàn người.'),
(8248, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 10, 7, 'OT', 'Khi Đa-vít nghe điều đó, ông sai Giô-áp và toàn thể đạo quân các dũng sĩ.'),
(8249, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 10, 8, 'OT', 'Các con trai của Amôn ra đi và bố trí trận chiến ở lối vào thành; còn người Sy-ri ở Sô-ba, ở Rê-hốp, người Ích-tô-b, và người Ma-a-ca đặt riêng mình ra ngoài đồng.'),
(8250, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 10, 9, 'OT', 'Khi Giô-áp thấy rằng trận chiến diễn ra chống lại mình ở cả phía trước và phía sau, thì ông chọn tất cả những người tráng kiện nhất trong Ít-ra-en, và bố trí họ đối đầu với người Sy-ri.'),
(8251, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 10, 10, 'OT', 'Còn phần còn lại của dân chúng thì ông giao vào tay Ab-sai, anh mình, để họ bố trí đối đầu với con cái của Am-môn.'),
(8252, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 10, 11, 'OT', 'Ông ấy nói: "Nếu người Sy-ria mạnh hơn ta, thì ngươi sẽ đến giúp ta; còn nếu con cái Am-môn mạnh hơn ngươi, thì ta sẽ đi đến giúp ngươi."'),
(8253, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 10, 12, 'OT', 'Hãy vững lòng và cùng nhau mạnh mẽ vì dân ta và vì các thành của Đức Chúa Trời chúng ta; và Đức Giê-hô-va sẽ làm điều tốt lành theo ý Ngài.'),
(8254, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 10, 13, 'OT', 'Giô-áp và những người đi cùng ông xông vào trận chiến chống lại người Sy-ri; và chúng chạy trốn khỏi mặt ông.'),
(8255, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 10, 14, 'OT', 'Khi con cái Am-môn thấy quân Sy-ri đã chạy trốn, thì chúng cũng chạy trốn trước mặt A-bi-sai và vào trong thành. Vậy rồi Giô-áp trở về từ trước mặt con cái Am-môn và đi đến Giê-ru-sa-lem.'),
(8256, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 10, 15, 'OT', 'Khi người Sy-ri thấy mình bị đánh bại trước mặt Ít-ra-en, thì họ tập hợp lại với nhau.'),
(8257, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 10, 16, 'OT', 'Hã-đa-xe gửi đi và triệu hồi người Sy-ria từ bên kia sông; họ đến nơi Hê-lam, và Sô-ba-kh, viên tướng chỉ huy đạo quân của Hã-đa-xe, đi trước họ.'),
(8258, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 10, 17, 'OT', 'Khi có tin báo cho Đa-vít, ông liền tập hợp toàn thể Ít-ra-en, rồi qua sông Giô-đanh, đến nơi gọi là Hê-lam. Người Xy-ri đã giương cung nghênh chiến cùng Đa-vít và giao chiến với ông.'),
(8259, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 10, 18, 'OT', 'Người A-ram chạy trốn khỏi mặt Ít-ra-en; và Đa-vít giết từ giữa người A-ram bảy trăm xe và bốn mươi ngàn kỵ binh, và đánh thương tích Xô-ba-ách, quan tổng chỉ huy quân đội của họ, người ấy chết tại đó.'),
(8260, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 10, 19, 'OT', 'Khi mọi vua là các đầy tớ của Ha-đa-đe-xe thấy rằng họ bị đánh bại trước mặt Y-sơ-ra-ên, thì họ lập hòa ước với Y-sơ-ra-ên và phục vụ họ. Vậy nên, người A-ram sợ không dám giúp các con trai của Am-môn nữa.'),
(8261, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 11, 1, 'OT', 'Sau khi năm đã qua, vào thời các vua thường ra đi chinh chiến, thì Đa-vít sai Giô-áp và các thuộc hạ đi với ông, cùng toàn thể Y-sơ-ra-ên. Họ đánh bại dân Am-môn và vây hãm thành Ráp-ba. Nhưng Đa-vít vẫn ở lại Giê-ru-sa-lem.'),
(8262, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 11, 2, 'OT', 'Vào buổi chiều, Đa-vít chỗi dậy khỏi giường mình và đi dạo trên mái nhà vua. Người thấy một người đàn bà đang tắm trên mái; người đàn bà ấy rất đẹp.'),
(8263, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 11, 3, 'OT', 'Đa-vít sai người đi hỏi về người đàn bà ấy. Người ấy nói: "Chẳng phải đây là Bát-sê-ba, con gái Ê-li-am, vợ của U-ri-a người Hê-th sao?"'),
(8264, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 11, 4, 'OT', 'Vua Đa-vít sai các sứ giả đi đón nàng; nàng đến cùng vua, và vua nằm với nàng; lúc ấy nàng đang được tinh sạch khỏi sự ô uế của mình. Sau đó, nàng trở về nhà mình.'),
(8265, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 11, 5, 'OT', 'Người đàn bà có thai, rồi sai người đi báo cho Đa-vít, và nói: Tôi đang mang thai.'),
(8266, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 11, 6, 'OT', 'Đa-vít sai người đến Giô-áp, nói: "Hãy sai U-ri-a người Hê-th đến ta." Và Giô-áp sai U-ri-a đến Đa-vít.'),
(8267, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 11, 7, 'OT', 'Và khi U-ri-a đến cùng người, Đa-vít hỏi thăm về tình trạng của Giô-áp, về tình trạng của dân chúng, và về tình hình cuộc chiến.'),
(8268, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 11, 8, 'OT', 'Đa-vít nói với U-ri-a: "Hãy xuống nhà ngươi và rửa chân đi." U-ri-a liền ra khỏi nhà vua, và có một suất ăn từ vua được đưa theo sau ông.'),
(8269, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 11, 9, 'OT', 'Nhưng U-ri-gia nằm ngủ ở cửa nhà vua cùng với tất cả các đầy tớ của chủ mình, và không đi xuống nhà mình.'),
(8270, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 11, 10, 'OT', 'Người ta báo cho Đa-vít biết và nói: "Ô-ri-ah không xuống nhà mình." Đa-vít nói với Ô-ri-ah: "Ngươi há chẳng phải từ cuộc hành trình trở về sao? Vậy sao ngươi không xuống nhà mình?"'),
(8271, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 11, 11, 'OT', 'Và U-ri nói với Đa-vít: "Rương giao ước, cùng với Ít-ra-en và Giu-đa, đang ở trong các trại; còn chúa tôi là Giô-áp và các đầy tớ của chúa tôi thì đang đóng trại ngoài đồng; vậy tôi sao có thể về nhà mình để ăn uống và nằm cùng vợ tôi? Tôi thề bằng mạng sống của vua và mạng sống của chính tôi, tôi sẽ không làm điều này."'),
(8272, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 11, 12, 'OT', 'Đa-vít nói với U-ri-a: "Hãy ở lại đây hôm nay, và ngày mai ta sẽ cho ngươi đi." Vậy U-ri-a ở lại Giê-ru-sa-lem trong ngày ấy và ngày hôm sau.'),
(8273, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 11, 13, 'OT', 'Đa-vít gọi người ấy đến, và người ấy ăn uống trước mặt vua; rồi vua khiến người ấy uống rượu say. Đến chiều tối, người ấy ra đi nằm trên giường mình cùng các đầy tớ của chủ mình, nhưng không trở về nhà.'),
(8274, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 11, 14, 'OT', 'Và xảy ra vào buổi sáng, Đa-vít viết một bức thư cho Giô-áp, rồi sai U-ri-a mang đi.'),
(8275, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 11, 15, 'OT', 'Người viết vào bức thư rằng: "Hãy đặt U-ri-a ở nơi đầu tiên trước mặt trận đánh mạnh nhất, rồi rút lui khỏi người, để người bị đánh và chết."'),
(8276, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 11, 16, 'OT', 'Khi Giô-áp đang vây hãm thành phố, ông đã bố trí U-ri-a đến chỗ mà ông biết những người chiến sĩ dũng cảm đang ở đó.'),
(8277, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 11, 17, 'OT', 'Các người của thành kéo ra và giao chiến với Giô-áp; một số đầy tớ của Đa-vít bị ngã gục, và cũng chết cả U-ri-a người Hê-th.'),
(8278, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 11, 18, 'OT', 'Vậy, Giô-áp sai người và báo cho Đa-vít biết mọi việc xảy ra trong cuộc chiến.'),
(8279, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 11, 19, 'OT', 'Người truyền lệnh cho sứ giả rằng: "Sau khi ngươi thuật xong mọi chuyện về cuộc chiến cho nhà vua,'),
(8280, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 11, 20, 'OT', 'Nếu cơn thịnh nộ của vua nổi lên và người hỏi ngươi: "Tại sao các ngươi lại đến gần thành để giao chiến?"—chẳng lẽ các ngươi không biết rằng người ta sẽ bắn tên từ trên tường sao?'),
(8281, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 11, 21, 'OT', 'Ai đã giết A-bi-mê-léc, con trai của Giê-ru-ba-sết? Há chẳng phải một người phụ nữ ném một tảng đá cối xay lên ông từ trên vách thành, khiến ông chết tại Tê-bết sao? Tại sao các ngươi lại đến gần vách thành? Vậy hãy nói rằng: Tôi tớ ngươi là U-ri-gia người Hê-th cũng đã chết.'),
(8282, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 11, 22, 'OT', 'Người sứ giả đi, đến và báo cho Đa-vít biết mọi điều mà Giô-áp đã sai ông đi.'),
(8283, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 11, 23, 'OT', 'Người sứ giả nói với vua Đa-vít: "Các người ấy đã đánh bại chúng tôi, và xông ra khỏi thành ra đến ngoài đồng, rồi chúng tôi phải đánh họ cho đến tận cửa thành."'),
(8284, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 11, 24, 'OT', 'Các tay bắn cung bắn vào các đầy tớ ngươi từ trên tường thành, và một số đầy tớ của vua đã chết; và đầy tớ ngươi, Út-ri-ah người Hê-th, cũng đã chết.'),
(8285, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 11, 25, 'OT', 'Đa-vít nói với sứ giả: "Hãy nói với Giô-áp như thế này: Đừng để điều này làm ngươi buồn, vì gươm há chẳng nuốt người này hay người khác sao? Hãy làm cho trận chiến của ngươi càng mạnh hơn nữa chống lại thành, và phá hủy nó; hãy khích lệ người ấy."'),
(8286, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 11, 26, 'OT', 'Khi vợ của U-ri-a nghe tin U-ri-a, chồng mình, đã chết, thì bà khóc than chồng mình.'),
(8287, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 11, 27, 'OT', 'Sau khi thời gian để tang qua đi, Đa-vít sai người đón nàng về nhà mình; nàng trở thành vợ ông và sinh cho ông một đứa con trai. Nhưng điều Đa-vít đã làm khiến lòng Đức Giê-hô-va bất bình.'),
(8288, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 12, 1, 'OT', 'Đức Giê-hô-va sai Na-than đến cùng Đa-vít. Ông đến cùng người và nói với người rằng: "Có hai người đàn ông trong một thành; một người giàu, một người nghèo."'),
(8289, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 12, 2, 'OT', 'Người giàu có rất nhiều chiên và bò.'),
(8290, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 12, 3, 'OT', 'Nhưng người nghèo không có gì hết, ngoại trừ một con chi cái nhỏ mà ông đã mua, nuôi lớn lên; con chi ấy sống với ông và với các con ông như một nhà: nó ăn trong đĩa ông, uống trong chén ông, nằm trong lòng ông, và đối với ông thì như con gái.'),
(8291, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 12, 4, 'OT', 'Có một người lữ khách đến với người giàu, nhưng ông ta không chịu bắt từ đàn chiên hay bò của mình để đãi khách; trái lại, ông lấy con chiên của người nghèo và làm thịt đãi người khách đã đến với mình.'),
(8292, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 12, 5, 'OT', 'Đức vua Đa-vít vô cùng tức giận người đàn ông ấy, và nói với Na-than: "Đức Giê-hô-va hằng sống, kẻ đã làm điều này chắc chắn phải chết!"'),
(8293, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 12, 6, 'OT', 'Và con chiên thì phải đền gấp bốn lần, vì đã làm điều này, và vì nó không có lòng thương xót.'),
(8294, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 12, 7, 'OT', 'Na-than nói với Đa-vít: "Chính ngươi là người ấy. Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en phán thế này: Ta đã xức dầu cho ngươi làm vua cai trị Ít-ra-en, và Ta đã giải cứu ngươi khỏi tay Sau-lơ."'),
(8295, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 12, 8, 'OT', 'Ta đã ban cho ngươi nhà của chủ ngươi, và các vợ của chủ ngươi vào lòng ngươi; Ta đã ban cho ngươi nhà Y-sơ-ra-ên và nhà Giu-đa; và nếu điều đó còn quá ít, Ta sẽ còn ban thêm cho ngươi nhiều điều khác nữa.'),
(8296, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 12, 9, 'OT', 'Sao ngươi lại khinh dể lời phán của Đức Giê-hô-va, làm điều ác trước mặt Ngài? Ngươi đã dùng gươm giết U-ri-a người Hê-th, và lấy vợ người làm vợ mình; ngươi đã dùng gươm của con cái Am-môn mà giết chính người ấy.'),
(8297, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 12, 10, 'OT', 'Vì vậy, từ nay, gươm sẽ không bao giờ dứt khỏi nhà ngươi cho đến đời đời; bởi ngươi đã khinh dể Ta và lấy bà vợ của U-ri người Hê-th làm vợ ngươi.'),
(8298, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 12, 11, 'OT', 'Đức Giê-hô-va phán như vầy: Nầy, Ta sẽ gây cho ngươi tai họa từ chính nhà ngươi; Ta sẽ lấy các vợ ngươi ngay trước mặt ngươi mà trao cho người bạn hữu ngươi, và người ấy sẽ nằm với các vợ ngươi ngay trước ánh mắt mặt trời nầy.'),
(8299, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 12, 12, 'OT', 'Vì ngươi đã làm điều này cách kín giấu, nhưng ta sẽ làm điều này trước mặt cả Ít-ra-en và trước mặt mặt trời.'),
(8300, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 12, 13, 'OT', 'Đa-vít nói với Na-than: "Tôi đã phạm tội nghịch cùng Đức Giê-hô-va." Na-than đáp: "Đức Giê-hô-va cũng đã xoá tội ngươi; ngươi sẽ không chết."'),
(8301, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 12, 14, 'OT', 'Dầu vậy, vì cớ ngươi đã dùng việc nầy mà chế nhạo các kẻ thù của Đức Giê-hô-va, đứa con trai vừa sinh cho ngươi chắc chắn sẽ chết.'),
(8302, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 12, 15, 'OT', 'Sau khi Na-than trở về nhà, Đức Giê-hô-va giáng bệnh cho đứa trẻ mà vợ của U-ri-a đã sinh cho Đa-vít, và nó lâm trọng bệnh.'),
(8303, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 12, 16, 'OT', 'Đa-vít cầu xin Đức Chúa Trời vì đứa trẻ; và Đa-vít ăn chay, vào và ở lại, nằm suốt đêm trên đất.'),
(8304, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 12, 17, 'OT', 'Các trưởng lão trong nhà người đứng dậy, đến cùng người để nâng người khỏi đất; nhưng người không chịu, cũng không chịu ăn bánh cùng họ.'),
(8305, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 12, 18, 'OT', 'Vào ngày thứ bảy, đứa trẻ qua đời. Các tôi tớ của Đa-vít sợ không dám báo cho ông biết rằng đứa trẻ đã chết, vì họ nói: "Kìa, khi đứa trẻ còn sống, chúng tôi đã nói với ông, mà ông không nghe theo tiếng chúng tôi; vậy nếu chúng tôi bảo ông rằng đứa trẻ đã chết, ông sẽ làm điều xấu."'),
(8306, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 12, 19, 'OT', 'Thấy các đầy tớ thì thầm với nhau, Đa-vít hiểu rằng đứa trẻ đã chết; Đa-vít hỏi các đầy tớ: "Đứa trẻ có chết rồi không?" Họ thưa: "Thưa, chết rồi."'),
(8307, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 12, 20, 'OT', 'Đa-vít chỗi dậy từ đất, tắm rửa, xức dầu và thay đổi quần áo mình, rồi vào nhà của Đức Giê-hô-va và thờ lạy; sau đó người trở về nhà mình, đòi ăn, và họ dọn bánh cho người, thì người ăn.'),
(8308, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 12, 21, 'OT', 'Các tôi tớ nói với vua: "Điều này nghĩa là gì, tức là điều ông vừa làm? Khi đứa trẻ còn sống, ông nhịn ăn và khóc than; nhưng khi đứa trẻ đã chết, ông chỗi dậy và ăn bánh."'),
(8309, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 12, 22, 'OT', 'Vua Đa-vít đáp: "Trong khi đứa trẻ còn sống, tôi nhịn ăn và khóc lóc, vì tôi nghĩ: Biết đâu Đức Giê-hô-va sẽ thương xót tôi, và đứa trẻ sẽ được sống."'),
(8310, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 12, 23, 'OT', 'Nhưng bây giờ nó đã chết, tôi ăn năn làm chi? Tôi há có thể khiến nó trở lại được nữa sao? Tôi sẽ đi đến nó, nhưng nó thì không trở lại với tôi.'),
(8311, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 12, 24, 'OT', 'Đa-vít an ủi Bát-sê-ba, vợ mình; người vào cùng nàng và nằm với nàng. Nàng sinh một con trai, và người đặt tên con là Sa-lô-môn. Đức Giê-hô-va yêu thương con trẻ.'),
(8312, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 12, 25, 'OT', 'Người sai Na-than, vị tiên tri, đến, và ông đặt tên đứa trẻ là Giê-đi-đi-a, vì cớ Đức Giê-hô-va.'),
(8313, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 12, 26, 'OT', 'Giô-áp giao chiến với Rabbah của con cái Am-môn và chiếm lấy thành phố làm thủ đô.'),
(8314, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 12, 27, 'OT', 'Giô-áp sai các sứ giả đến cùng Đa-vít, và nói: Tôi đã giao chiến với Ráp-ba, và cũng đã chiếm được thành có nước bao bọc.'),
(8315, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 12, 28, 'OT', 'Bây giờ, hãy tập hợp những người còn lại của dân chúng, và đóng trại vây quanh thành, rồi chiếm lấy nó; kẻo chính tôi sẽ chiếm thành, và người ta sẽ đặt tên thành theo danh tôi.'),
(8316, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 12, 29, 'OT', 'Đa-vít tập hợp toàn thể dân chúng, rồi đi ra Ráp-ba, đánh nhau với thành ấy và chiếm lấy nó.'),
(8317, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 12, 30, 'OT', 'Vua Đa-vít lấy mão triều của vua chúng từ trên đầu người ấy, và mão ấy nặng một ta-lâng vàng, đính viên ngọc quý; người ta đặt mão ấy trên đầu Đa-vít. Vua cũng mang ra rất nhiều chiến lợi phẩm từ thành ấy.'),
(8318, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 12, 31, 'OT', 'Rồi ông cho dân cư trong thành ra, bắt họ làm việc cưa, làm việc cày sắt và rìu sắt, và bắt họ đi qua lò gạch; ông cũng làm như vậy cho mọi thành của con cái Am-môn. Sau đó Đa-vít và toàn thể dân chúng trở về Giê-ru-sa-lem.'),
(8319, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 1, 'OT', 'Sau những việc ấy, Áp-sa-lôm, con trai của vua Đa-vít, có một em gái xinh đẹp tên là Ta-ma; và Am-nôn, con trai của vua Đa-vít, yêu nàng.'),
(8320, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 2, 'OT', 'Am-nôn cảm thấy bực bội đến nỗi sinh bệnh vì Ta-ma, em gái mình; nàng vẫn còn trinh tiết, và Am-nôn thấy khó lòng làm điều gì với nàng.'),
(8321, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 3, 'OT', 'Am-nôn có một người bạn, tên là Giô-na-đáp, con trai của Si-mê-a, anh của Đa-vít; và Giô-na-đáp là một người rất khôn ngoan.'),
(8322, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 4, 'OT', 'Người nói với anh: "Tại sao ngươi lại gầy ốm như vậy, hỡi con trai vua, ngày này qua ngày khác? Sao không nói cho ta biết?" Am-nôn nói với người: "Tôi yêu Ta-ma, em gái của Áp-sa-lôm, anh tôi."'),
(8323, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 5, 'OT', 'Bấy giờ Giô-na-đáp nói với anh rằng: "Hãy nằm trên giường mình và giả làm như ốm. Khi cha ngươi đến xem ngươi, hãy nói với người rằng: ''Xin cho em gái tôi là Ta-ma đến, làm một ít bánh trước mặt con, để con thấy và ăn từ tay nàng.''"'),
(8324, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 6, 'OT', 'Am-nôn nằm xuống và giả vờ ốm. Vua đến thăm anh, thì Am-nôn nói với vua: "Xin cha cho Ta-ma, em gái con, đến đây và làm trước mặt con hai chiếc bánh, để con có thể ăn từ tay nàng."'),
(8325, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 7, 'OT', 'Vua Đa-vít sai người về nhà tìm Ta-ma, bảo rằng: "Hãy đi đến nhà Am-nôn, anh ngươi, và nấu một món ăn cho anh ấy."'),
(8326, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 8, 'OT', 'Ta-ma đi đến nhà anh trai mình là Am-nôn, và người này đang nằm. Cô lấy bột, nhồi và làm bánh ngay trước mặt anh ta, rồi nướng những chiếc bánh đó.'),
(8327, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 9, 'OT', 'Cô lấy cái chảo, đổ thức ăn ra trước mặt chàng, nhưng chàng từ chối không ăn. Sau đó Am-nôn nói: "Hãy cho mọi người ra khỏi ta." Vậy tất cả những người kia liền ra khỏi chàng.'),
(8328, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 10, 'OT', 'Am-nôn nói với Ta-ma: "Hãy mang món ăn vào phòng, để tôi ăn từ tay cô." Ta-ma liền lấy những chiếc bánh cô đã làm, mang vào phòng cho Am-nôn, anh trai mình.'),
(8329, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 11, 'OT', 'Cô mang thức ăn đến cho chàng ăn, thì chàng nắm lấy cô và nói: "Em hãy vào nằm với anh, em gái của anh."'),
(8330, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 12, 'OT', 'Đừng làm vậy, anh ơi, đừng hành hạ tôi, vì điều này không bao giờ được làm trong Y-sơ-ra-ên; anh đừng làm điều xấu xa này.'),
(8331, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 13, 'OT', 'Và tôi, tôi sẽ đem nỗi xấu hổ của tôi đi đâu? Còn anh, anh sẽ như một trong những kẻ ngu dại ở Ít-ra-en. Bây giờ, xin hãy nói cùng vua, vì người sẽ không ngăn cản tôi khỏi anh.'),
(8332, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 14, 'OT', 'Dù nàng đã van xin, nhưng hắn không chịu nghe tiếng nàng; hắn mạnh hơn nàng, nên đã hãm hiếp nàng và nằm cùng nàng.'),
(8333, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 15, 'OT', 'Am-nôn ghét nàng một cách cực kỳ sâu sắc; vì sự ghét mà anh ta ghét nàng còn lớn hơn cả tình yêu mà anh ta đã yêu nàng trước đó. Am-nôn nói với nàng: "Hãy đứng dậy, đi đi!"'),
(8334, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 16, 'OT', 'Cô nói với anh ta: "Đừng làm điều ác lớn này lớn hơn điều ác khác mà anh đã làm với tôi bằng cách đuổi tôi đi." Nhưng anh ta không chịu nghe lời cô.'),
(8335, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 17, 'OT', 'Bấy giờ, người gọi đầy tớ hầu việc mình, và nói: "Hãy đuổi người đàn bà này ra khỏi ta ngay lập tức, và khóa cửa lại sau nàng."'),
(8336, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 18, 'OT', 'Trên nàng là chiếc áo dài sặc sỡ, vì các con gái vua còn trinh nữ thường mặc áo như vậy. Người đầy tớ liền đưa nàng ra ngoài, rồi đóng cửa lại sau lưng nàng.'),
(8337, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 19, 'OT', 'Ta-ma lấy tro phủ lên đầu mình, xé áo sặc sỡ mà nàng đang mặc, đặt tay lên đầu và đi vừa khóc vừa kêu la.'),
(8338, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 20, 'OT', 'Áp-sa-lôm, anh trai nàng, nói với nàng: "Anh trai ngươi là Am-nôn có ở với ngươi chăng? Nhưng bây giờ, hỡi em gái ta, hãy nín lặng đi; người ấy là anh em ngươi, đừng để lòng ngươi bận điều nầy." Vậy Ta-ma ở lại, sống buồn bã trong nhà Áp-sa-lôm, anh trai nàng.'),
(8339, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 21, 'OT', 'Vua Đa-vít nghe được mọi chuyện ấy, thì vô cùng tức giận.'),
(8340, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 22, 'OT', 'Áp-sa-lôm không nói với anh trai mình là Am-nôn điều gì xấu cũng không điều gì tốt, vì Áp-sa-lôm ghét Am-nôn, do Am-nôn đã làm nhục Ta-ma, em gái mình.'),
(8341, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 23, 'OT', 'Hai năm trôi qua, rồi các thợ xén lông chiên làm việc cho Áp-sa-lôm tại Ba-anh Ha-xô, gần Efrayim; và Áp-sa-lôm mời tất cả các con trai của nhà vua.'),
(8342, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 24, 'OT', 'Áp-sa-lôm đến cùng vua và nói: Kìa, bây giờ đầy tớ của ngài đang cắt lông chiên; nguyện xin vua và các tôi tớ của vua hãy đi cùng đầy tớ của ngài.'),
(8343, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 25, 'OT', 'Vua nói với Áp-xa-lôm: "Thôi, con trai ta, chúng ta không nên đi hết, kẻo con phải tốn kém." Nhưng Áp-xa-lôm nài xin; vua vẫn không chịu đi, song đã ban phước cho người ấy.'),
(8344, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 26, 'OT', 'Áp-sa-lôm nói: "Xin đừng để Am-nôn, anh tôi, đi cùng chúng tôi." Nhưng vua nói với người: "Tại sao cậu ấy phải đi với ngươi?"'),
(8345, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 27, 'OT', 'Nhưng Áp-sa-lôm nài ép vua, đến nỗi vua để cho Am-nôn và tất cả các con trai của vua đi với người.'),
(8346, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 28, 'OT', 'Áp-sa-lôm dặn các đầy tớ mình rằng: "Hãy để ý, khi nào các ngươi thấy lòng Am-nôn vui vẻ vì rượu, ta sẽ nói với các ngươi: ''Hãy đánh Am-nôn,'' thì hãy giết người đó, chớ sợ hãi; chẳng phải chính ta đã truyền cho các ngươi sao? Hãy can đảm và mạnh mẽ như những người tráng sĩ."'),
(8347, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 29, 'OT', 'Các đầy tớ của Áp-sa-lôm đã làm cho Am-nôn y như điều Áp-sa-lôm đã dặn; rồi tất cả các con trai của vua đều đứng dậy, mỗi người cỡi lên lừa cái của mình và chạy trốn.'),
(8348, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 30, 'OT', 'Khi họ đang trên đường, thì tin tức truyền đến Đa-vít rằng: Áp-sa-lôm đã giết tất cả các con trai của vua, và không còn một ai sót lại nơi chúng nó.'),
(8349, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 31, 'OT', 'Vua chỗi dậy, xé áo mình và nằm sấp trên đất; còn tất cả các tôi tớ của vua thì đứng đó với áo xé nát.'),
(8350, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 32, 'OT', 'Giô-na-đáp, con trai của Si-mê-a, anh của Đa-vít, thưa rằng: "Xin chúa đừng nghĩ rằng tất cả các người trẻ tuổi, con trai của vua, đã bị giết; chỉ một mình Am-nôn là chết mà thôi. Vì điều này đã được Áp-sa-lôm định sẵn từ ngày hắn làm nhục Ta-ma, em gái mình."'),
(8351, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 33, 'OT', 'Bây giờ, xin chúa tôi là vua đừng để điều đó vào lòng mình, mà cho rằng mọi con trai của vua đều đã chết; chỉ có Am-nôn là người chết mà thôi.'),
(8352, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 34, 'OT', 'Áp-sa-lôm trốn chạy. Còn người trai trẻ canh gác thì ngước mắt lên, nhìn thấy, và nầy, một đoàn dân đông đang đi theo con đường phía bên sườn núi đằng sau người ấy.'),
(8353, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 35, 'OT', 'Giô-na-đáp nói với vua: "Này, các con trai của vua đang đến; điều gì xảy ra cũng như lời tôi tớ của ngài đã nói."'),
(8354, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 36, 'OT', 'Khi người ấy vừa dứt lời thì nầy, các con trai của vua đến, họ cất tiếng khóc lớn; và chính vua cùng mọi tôi tớ người cũng khóc rất thảm thiết.'),
(8355, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 37, 'OT', 'Nhưng Áp-sa-lôm đã trốn chạy và đi đến Tanh-mai, con trai của Ammihud, vua xứ Ghê-su-rơ. Áp-sa-lôm than khóc con trai mình suốt mọi ngày.'),
(8356, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 38, 'OT', 'Áp-sa-lôm trốn chạy và đi đến Ghê-su-rơ, và ở đó ba năm.'),
(8357, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 13, 39, 'OT', 'Lòng vua Đa-vít mong mỏi ra gặp Áp-xa-lôm, vì vua đã an ủi về chuyện Am-nôn, vì người đã chết.'),
(8358, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 1, 'OT', 'Giô-áp, con trai của Xê-ru-yah, biết rằng lòng vua hướng về Áp-sa-lôm.'),
(8359, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 2, 'OT', 'Vậy, Giô-áp sai người đến Tê-koa, và từ đó đem về một người đàn bà khôn ngoan; và ông nói với nàng: "Xin hãy làm như kẻ đang để tang, hãy mặc áo tang phục, đừng xức dầu, và hãy tỏ ra như một người đàn bà đã để tang lâu ngày cho kẻ chết."'),
(8360, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 3, 'OT', 'Hãy đến cùng vua và nói với người theo lời này; rồi Giô-áp đặt các lời ấy vào miệng bà.'),
(8361, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 4, 'OT', 'Người đàn bà từ Tê-koa nói với vua, rồi sấp mặt xuống đất, cúi lạy và thưa: "Xin đức vua cứu giúp!"'),
(8362, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 5, 'OT', 'Vua nói với bà: "Bà gặp điều gì vậy?" Bà thưa: "Thật vậy, tôi là một người đàn bà goá, và chồng tôi đã qua đời."'),
(8363, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 6, 'OT', 'Tôi là nữ tớ của ngài, tôi có hai con trai; hai người đó đánh nhau trong đồng, không ai can ngăn giữa họ, rồi một người đánh người kia và giết chết anh ta.'),
(8364, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 7, 'OT', 'Và nầy, toàn thể gia đình đã nổi lên chống lại tớ gái ngài, và họ nói: ''Hãy giao ra kẻ đã đánh giết anh em mình, để chúng tôi giết hắn vì mạng sống anh em hắn mà hắn đã giết; và chúng tôi cũng sẽ tiêu diệt luôn cả người thừa kế.'' Như vậy, họ sẽ dập tắt than hồng còn sót lại của tôi, khiến cho chồng tôi không còn tên tuổi và dòng dõi nào sót lại trên mặt đất.'),
(8365, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 8, 'OT', 'Vua nói với người đàn bà: "Cô hãy về nhà mình, và ta sẽ ra lệnh về cô."'),
(8366, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 9, 'OT', 'Người đàn bà từ Tê-koa nói với vua: "Thưa chúa tôi là vua, tội lỗi thuộc về tôi và nhà cha tôi; còn vua và ngôi vua thì vô tội."'),
(8367, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 10, 'OT', 'Vua nói: "Bất cứ ai nói chuyện với ngươi, hãy dẫn người ấy đến ta, và người đó sẽ không còn đụng đến ngươi nữa."'),
(8368, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 11, 'OT', 'Bà ấy thưa: "Xin vua nhớ đến Đức Giê-hô-va Đức Chúa Trời của ngài, đừng để kẻ báo thù huyết làm thêm điều hủy diệt, và đừng tiêu diệt con trai tôi." Vua đáp: "Đức Giê-hô-va hằng sống, một sợi tóc của con trai bà cũng sẽ không rơi xuống đất."'),
(8369, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 12, 'OT', 'Bà ấy nói: "Xin mời nữ tớ gái của ngài nói một lời với đức vua, chúa của tôi." Người đáp: "Hãy nói đi."'),
(8370, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 13, 'OT', 'Bà ấy nói: "Tại sao ngài lại nghĩ điều này chống lại dân của Đức Chúa Trời? Chính lời của đức vua trong việc này giống như người mắc lỗi, vì đức vua không đón trở lại người bị đuổi đi."'),
(8371, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 14, 'OT', 'Chúng ta rồi cũng phải chết, giống như nước đổ xuống đất không thể gom lại được; Đức Chúa Trời chẳng đoái hoài đến mạng sống, nhưng lại bày ra nhiều mưu kế để kẻ bị đuổi đi không bị loại ra khỏi Ngài.'),
(8372, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 15, 'OT', 'Bây giờ tôi đã đến nói với đức vua, chúa tôi, điều này, vì dân chúng làm tôi sợ; và tôi, kẻ tớ gái của ngài, đã nói: Tôi xin nói với đức vua, mong rằng đức vua sẽ thực hiện lời thỉnh cầu của kẻ tớ gái mình.'),
(8373, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 16, 'OT', 'Vì vua sẽ nghe để giải cứu nữ tớ của ngài khỏi tay người đàn ông, để không tiêu diệt tôi và con trai tôi cùng nhau khỏi cơ nghiệp của Đức Chúa Trời.'),
(8374, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 17, 'OT', 'Hỡi tôi tớ của ngài, nguyện lời của chúa tôi là vua được an ổn; vì chúa tôi là vua khôn ngoan như thiên sứ của Đức Chúa Trời trong việc phân biệt điều thiện và điều ác. Nguyện Đức Giê-hô-va Đức Chúa Trời của ngài ở cùng ngài.'),
(8375, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 18, 'OT', 'Vua đáp lời và nói với người đàn bà: "Xin đừng giấu tôi điều gì tôi sẽ hỏi bà." Người đàn bà thưa: "Xin mời đức vua, chúa tôi, cứ nói."'),
(8376, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 19, 'OT', 'Vua nói: "Chắc hẳn tay của Yo-ab có dính líu đến chuyện này phải không?" Người đàn bà đáp: "Tính mạng của ngài, thưa chúa tôi là vua, xin chứng giám, không ai dám rẽ sang phải hay sang trái khỏi điều gì mà chúa tôi là vua đã phán; vì đích thân đầy tớ ngài là Yo-ab đã ra lệnh cho tôi, và chính ông ta đã đặt tất cả những lời này vào miệng kẻ tớ nữ của ngài."'),
(8377, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 20, 'OT', 'Để xoay chuyển sự việc, chính người tôi tớ của ngài là Giô-áp đã làm điều này; còn ngài thì khôn ngoan, như sự khôn ngoan của thiên sứ Đức Chúa Trời, để biết mọi điều xảy ra trên đất.'),
(8378, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 21, 'OT', 'Vua nói với Giô-áp: Này, ta đã làm điều này; vậy hãy đi, đưa lại người thanh niên Áp-xa-lôm.'),
(8379, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 22, 'OT', 'Giô-áp phục xuống đất, cúi lạy và chúc phước cho vua. Rồi Giô-áp nói: "Ngày nay, tôi tớ ngài biết rằng tôi đã được ơn trước mặt ngài, chúa tôi là vua, vì vua đã làm theo lời thỉnh cầu của tôi tớ ngài."'),
(8380, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 23, 'OT', 'Vậy, Giô-áp đứng dậy đi đến Ghê-sua, và đem Áp-xa-lôm về Giê-ru-sa-lem.'),
(8381, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 24, 'OT', 'Vua nói: "Hãy trở về nhà mình, và mặt ta ngươi sẽ không được thấy." Vậy Áp-sa-lôm trở về nhà mình, và không được thấy mặt vua.'),
(8382, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 25, 'OT', 'Nhưng trong toàn thể Y-sơ-ra-ên, không có người nào được khen ngợi đẹp bằng Áp-xa-lôm; từ lòng bàn chân cho đến đỉnh đầu, người ấy không có tì vết gì.'),
(8383, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 26, 'OT', 'Mỗi khi cạo đầu—vì hằng năm ông đều cạo đầu, vì tóc quá nặng cho ông, nên ông cạo đi—ông cân số tóc đó được hai trăm sê-ken, theo cân vua.'),
(8384, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 27, 'OT', 'Áp-sa-lôm có ba người con trai và một người con gái tên là Ta-ma; nàng là một người phụ nữ có sắc đẹp.'),
(8385, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 28, 'OT', 'Áp-sa-lôm sống tại Giê-ru-sa-lem hai năm trọn, nhưng không được diện kiến mặt vua.'),
(8386, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 29, 'OT', 'Áp-sa-lôm sai người gọi Giô-áp, để nhờ Giô-áp sai người đến cùng vua; nhưng ông không chịu đến cùng người. Người sai ông lần thứ hai, nhưng ông vẫn không chịu đến.'),
(8387, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 30, 'OT', 'Ông ấy nói với các đầy tớ mình: "Hãy xem, thửa ruộng của Giô-áp sát bên thửa ruộng ta, và ông ấy có lúa mạch ở đó; hãy đi mà đốt nó." Các đầy tớ của Áp-sa-lôm liền đốt thửa ruộng ấy.'),
(8388, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 31, 'OT', 'Giô-áp chỗi dậy, đến nhà Áp-sa-lôm và nói với người: "Tại sao các đầy tớ ngươi đã đốt cháy cánh đồng thuộc về ta?"'),
(8389, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 32, 'OT', 'Áp-sa-lôm nói với Giô-áp: "Nầy, tôi đã sai người đến bảo ông: ''Hãy đến đây, để tôi sai ông đến cùng vua, mà nói rằng: Tại sao tôi phải từ Ghết-chua trở về? Thà tôi còn ở đó thì tốt hơn. Bây giờ xin cho tôi được diện kiến mặt vua; nếu tôi có tội, thì xin giết tôi đi.''"'),
(8390, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 14, 33, 'OT', 'Vậy Giô-áp đến cùng vua và tâu cho vua; vua gọi Áp-sa-lôm, người đến cùng vua, và người cúi sấp mặt xuống đất trước mặt vua; vua hôn Áp-sa-lôm.'),
(8391, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 1, 'OT', 'Sau những việc ấy, Áp-sa-lôm sắm cho mình một cỗ xe và ngựa, cùng năm mươi người chạy đi trước mặt ông.'),
(8392, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 2, 'OT', 'Áp-sa-lôm dậy sớm, đứng bên đường vào cổng thành; và xảy ra rằng, mỗi khi có người nào có việc tranh chấp đến cùng vua để được xét xử, thì Áp-sa-lôm gọi người ấy lại và nói: "Ngươi thuộc thành nào?" Người ấy đáp: "Tớ là người thuộc một trong các chi phái của Y-sơ-ra-ên."'),
(8393, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 3, 'OT', 'Áp-sa-lôm nói với người ấy: "Này, việc của anh tốt và phải lẽ; nhưng không có ai thuộc về vua nghe anh cả."'),
(8394, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 4, 'OT', 'Áp-sa-lôm nói: "Ước gì tôi được đặt làm quan xét trong đất, để mỗi người nào có việc tranh tụng hay xét xử đều đến cùng tôi, và tôi sẽ làm cho người ấy được công bằng!"'),
(8395, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 5, 'OT', 'Mỗi khi có người nào đến gần để cúi lạy ông, ông đều giơ tay ra, nắm lấy người ấy và hôn ông ta.'),
(8396, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 6, 'OT', 'Áp-sa-lôm đã làm như vậy đối với mọi người Ít-ra-en đến cùng vua để được xét xử; và Áp-sa-lôm đã chiếm được lòng những người Ít-ra-en.'),
(8397, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 7, 'OT', 'Sau bốn mươi năm, Áp-sa-lôm tâu cùng vua rằng: "Xin cho tôi đi, để tôi trả trọn lời hứa mà tôi đã hứa với Đức Giê-hô-va tại Hếp-rôn."'),
(8398, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 8, 'OT', 'Vì tôi đã khấn một lời khấn khi tôi ở tại Ghẹ- su-rơ trong xứ Sy- ria, rằng: Nếu Đức Giê-hô-va thực sự đem tôi trở lại Giê- ru- sa- lem, thì tôi sẽ hầu việc Đức Giê-hô-va.'),
(8399, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 9, 'OT', 'Vua nói với người ấy: "Hãy đi bình an." Người ấy liền đứng dậy và đi đến Hếp-rôn.'),
(8400, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 10, 'OT', 'Áp-sa-lôm đã sai những người do thám đi khắp các chi phái của Y-sơ-ra-ên, dặn rằng: "Khi các ngươi nghe tiếng kèn, thì hãy nói: Áp-sa-lôm đã làm vua tại Hếp-rôn."'),
(8401, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 11, 'OT', 'Hai trăm người từ Giê-ru-sa-lem đã đi theo Áp-sa-lôm, những người được gọi và đi với lòng ngay thẳng; họ không biết điều gì cả.'),
(8402, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 12, 'OT', 'Aù-áp-sa-lom sai người đi mời A-hi-thô-phên, người Ghí-lô, cố vấn của Đa-vít, từ thành ông ở, Ghí-lô, trong khi ông đang dâng các lễ tế; và phe nổi loạn ngày càng mạnh, và dân chúng ngày càng đông thêm với Aù-áp-sa-lom.'),
(8403, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 13, 'OT', 'Có một người đến báo với Đa-vít rằng: Lòng các người đàn ông Ít-ra-en đã theo Áp-sa-lôm.'),
(8404, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 14, 'OT', 'Đa-vít nói với tất cả các đầy tớ mình đang ở với ông tại Giê-ru-sa-lem: "Hãy đứng dậy, chúng ta hãy trốn chạy, vì chúng ta sẽ không thoát khỏi Áp-sa-lôm được. Hãy vội lên mà đi, kẻo người ấy vội vàng đuổi kịp chúng ta, giáng họa hại xuống trên chúng ta, và dùng lưỡi gươm đánh phá thành phố."'),
(8405, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 15, 'OT', 'Các tôi tớ của vua thưa cùng vua: "Này, các tôi tớ ngài đây, tùy theo điều gì chúa chúng tôi là vua sẽ chọn."'),
(8406, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 16, 'OT', 'Vua đi ra, và cả nhà vua đi theo người; vua để lại mười người đàn bà làm thứ thiếp để giữ nhà.'),
(8407, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 17, 'OT', 'Vua ra đi, và toàn dân đi theo người; họ dừng lại tại một nơi xa cách.'),
(8408, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 18, 'OT', 'Tất cả các đầy tớ của người đi ngang qua bên cạnh người; và tất cả người Cê-rê-thi, và tất cả người Pê-lê-thi, và tất cả người Gít-ti, sáu trăm người đàn ông đi theo người từ Ga-th, đi ngang qua trước mặt vua.'),
(8409, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 19, 'OT', 'Vua nói với Ít-tai người Ghít-ti: "Sao ngươi cũng đi với chúng ta? Hãy trở về và ở lại với vua, vì ngươi là người ngoại quốc và cũng là người lưu vong nơi đất ngươi."'),
(8410, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 20, 'OT', 'Hôm qua ngươi mới đến, hôm nay ta đã khiến ngươi đi cùng chúng ta. Nhưng ta đi đâu thì ta cứ đi; hãy trở về và dẫn các anh em ngươi về cùng ngươi. Ưng thuận và chân thật được ở cùng ngươi.'),
(8411, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 21, 'OT', 'Ittai đáp vua rằng: "Đức Giê-hô-va hằng sống, và chúa tôi là vua cũng hằng sống, tôi xin thề rằng ở đâu chúa tôi là vua ở đó tôi cũng sẽ ở, dù cho là đến chỗ chết hay sống, tôi là tôi tớ ngài cũng sẽ ở đó."'),
(8412, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 22, 'OT', 'Đa-vít nói với Ít-tai: "Hãy đi qua." Vậy Ít-tai người Ghít và tất cả những người của ông, cùng với mọi trẻ nhỏ đi theo ông, đều đi qua.'),
(8413, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 23, 'OT', 'Toàn thể đất nước khóc than bằng tiếng khóc lớn; toàn thể dân chúng đi qua. Vua cũng đi qua suối Ki-trôn, và toàn thể dân chúng đi qua về hướng con đường dẫn đến đồng vắng.'),
(8414, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 24, 'OT', 'Và nầy, cả Xa-đốc cùng mọi người Lê-vi đều ở với người, khiêng hòm giao ước của Đức Chúa Trời. Họ đặt hòm của Đức Chúa Trời xuống, và A-bi-a-tha đi lên, cho đến khi toàn thể dân chúng đã ra khỏi thành.'),
(8415, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 25, 'OT', 'Vua nói với Xa-đốc: "Hãy khiêng lại hòm giao ước của Đức Chúa Trời vào thành. Nếu tôi được ơn trước mặt Đức Giê-hô-va, Ngài sẽ khiến tôi trở lại, và cho tôi thấy hòm đó và nơi Ngài ngự."'),
(8416, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 26, 'OT', 'Nhưng nếu Ngài phán: Ta không ưa ngươi; thì nầy, tôi đây, Ngài hãy làm điều gì tốt trong mắt Ngài.'),
(8417, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 27, 'OT', 'Vua nói với thầy tế lễ Xa-đốc: "Ngươi có phải là người tiên kiến chăng? hãy trở về thành trong bình an, và hai con trai ngươi cũng đi cùng ngươi, tức A-hi-ma-ách con trai ngươi, và Giô-na-than con trai A-bi-a-tha."'),
(8418, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 28, 'OT', 'Hãy xem, ta sẽ nán lại nơi đồng vắng, cho đến khi có tin tức từ các ngươi đến báo cho ta biết.'),
(8419, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 29, 'OT', 'Vậy, Xa-đốc và A-bi-a-tha đem hòm của Đức Chúa Trời trở lại Giê-ru-sa-lem và ở lại đó.'),
(8420, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 30, 'OT', 'Đa-vít đi lên núi Ô-liu, vừa đi vừa khóc, đầu che phủ, đi chân không; và toàn thể dân chúng đi theo ông cũng đều che đầu mỗi người, và họ đi lên, vừa khóc vừa đi.'),
(8421, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 31, 'OT', 'Và Đa-vít được báo tin rằng: A-hi-thô-phên đã cấu kết với Áp-xa-lôm. Đa-vít nói: Lạy Đức Giê-hô-va, xin làm cho lời tư vấn của A-hi-thô-phên trở nên ngu ngốc.'),
(8422, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 32, 'OT', 'Khi Đa-vít đến nơi đỉnh núi, là chỗ người ta thờ phượng Đức Chúa Trời, thì nầy, Húc-sai người A-ki đến đón người, áo trong của người xé rách, và bụi đất trên đầu.'),
(8423, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 33, 'OT', 'Đa-vít nói với người ấy: "Nếu ngươi đi cùng ta, thì sẽ trở thành gánh nặng cho ta."'),
(8424, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 34, 'OT', 'Nếu ngươi trở lại thành và nói cùng Áp-sa-lôm: ''Tôi là tôi tớ của ngài; hễ vua nào, tôi cũng sẽ phục vụ người đó như tôi đã phục vụ cha ngài cho đến nay, thì bây giờ tôi cũng sẽ phục vụ ngài''—thì ngươi hãy phá bỏ cho tôi mưu kế của A-hi-thô-phên.'),
(8425, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 35, 'OT', 'Chẳng phải ở đó với ngươi có Xa-đốc và A-bi-át-ta, các thầy tế lễ sao? Vậy nên bất cứ điều gì ngươi nghe được từ nhà vua, hãy báo cho Xa-đốc và A-bi-át-ta, các thầy tế lễ.'),
(8426, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 36, 'OT', 'Nầy, tại đó cùng họ có hai con trai của họ, A-hi-ma-át, con trai của Xa-đốc, và Giô-na-than, con trai của A-bi-a-tha; và các ngươi hãy sai họ đến ta mang theo mọi điều các ngươi nghe được.'),
(8427, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 15, 37, 'OT', 'Vậy Hú-sai, bạn của Đa-vít, vào thành; và Áp-sa-lôm vào Giê-ru-sa-lem.'),
(8428, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 16, 1, 'OT', 'Đa-vít vừa đi qua đỉnh đồi không bao lâu, thì nầy, Xi-ba, người đầy tớ của Mê-phi-bô-sết, đến đón ông; người ấy dắt theo một đôi lừa đã được đóng yên, trên các con lừa ấy có hai trăm ổ bánh mì, một trăm chùm vả khô, một trăm trái cây mùa hè, và một bầu rượu.'),
(8429, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 16, 2, 'OT', 'Vua nói với Xíp-a: "Điều này nghĩa là sao?" Xíp-a thưa: "Những con lừa để cho gia đình vua cỡi; trái cây mùa hè để cho các người trẻ ăn; và rượu để cho những kẻ mệt mỏi trong đồng vắng uống."'),
(8430, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 16, 3, 'OT', 'Vua hỏi: "Còn con trai chủ ngươi ở đâu?" thì Xi-ba thưa cùng vua rằng: "Nầy, nó đang ở lại Giê-ru-sa-lem; vì nó nói: ''Hôm nay, nhà Y-sơ-ra-ên sẽ phục hồi lại cho tôi vương quyền của cha tôi.''"'),
(8431, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 16, 4, 'OT', 'Vua nói với Xi-ba: "Nầy, mọi điều thuộc về Mê-phi-bô-sết đều thuộc về ngươi." Xi-ba thưa: "Tôi cúi mình; nguyện tôi tìm được ơn trước mặt ngài, chúa tôi là vua."'),
(8432, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 16, 5, 'OT', 'Vua Đa-vít vừa đến Ba-hu- rim, nầy, từ đó có một người đàn ông đi ra, thuộc dòng họ nhà Sau-lơ, tên là Si-mê-i, con trai Ghê-ra; người ấy đi ra, tiếp tục đi ra và nguyền rủa.'),
(8433, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 16, 6, 'OT', 'Ném đá vào Đa-vít và vào tất cả các đầy tớ của vua Đa-vít; và toàn thể dân chúng cùng với tất cả những người chiến sĩ mạnh mẽ đều ở bên phải và bên trái ông.'),
(8434, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 16, 7, 'OT', 'Và Si-mê-i nói khi nguyền rủa: "Ra đi, ra đi, hỡi người đầy máu me, và hỡi người gian ác!"'),
(8435, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 16, 8, 'OT', 'Đức Giê-hô-va đã báo ứng cho ngươi mọi huyết của nhà Sau-lơ, mà ngươi đã trị vì thay người; và Đức Giê-hô-va đã trao vương quyền vào tay Áp-sa-lôm, con trai ngươi; và nầy, ngươi đang lâm vào tai họa, vì ngươi là người đầy dẫy huyết.'),
(8436, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 16, 9, 'OT', 'A-vi-sai, con trai của Xê-ru-ya, nói với vua: "Tại sao con chó chết này lại nguyền rủa chủ tôi là vua? Xin cho tôi qua bắt lấy đầu nó."'),
(8437, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 16, 10, 'OT', 'Vua nói: "Ta có can hệ gì với các ngươi, hỡi con cái của Xê-ru-i-a? Để hắn nguyền rủa đi, vì Đức Giê-hô-va đã bảo hắn: ''Hãy nguyền rủa Đa-vít.'' Vậy thì ai dám hỏi: ''Tại sao ngươi làm như vậy?''"'),
(8438, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 16, 11, 'OT', 'Đa-vít nói với A-bi-sai và với tất cả các đầy tớ mình: "Nầy, con trai ta, người đã ra từ lòng ta, đang tìm mạng sống ta; huống chi bây giờ một người thuộc chi phái Bên-gia-min! Hãy để người đó yên, để người đó rủa; vì Đức Giê-hô-va đã phán dặn người đó."'),
(8439, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 16, 12, 'OT', 'Biết đâu Đức Giê-hô-va sẽ nhìn xem cảnh khốn khổ của tôi, và Đức Giê-hô-va sẽ trả lại cho tôi điều lành thay cho sự rủa sả mà tôi đang chịu hôm nay.'),
(8440, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 16, 13, 'OT', 'Đa-vít và những người của ông đi trên đường, còn Si-mê đi dọc theo sườn núi đối diện ông vừa đi vừa rủa sả, ném đá vào ông và lấy bụi đất ném theo.'),
(8441, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 16, 14, 'OT', 'Vua và tất cả dân chúng đi theo ông đều mệt lả, bèn dừng lại nghỉ ngơi ở đó.'),
(8442, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 16, 15, 'OT', 'Và Áp-sa-lôm cùng với toàn thể dân sự, mọi người Ít-ra-en, đến Giê-ru-sa-lem, và A-hi-thô-phên đi cùng người ấy.'),
(8443, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 16, 16, 'OT', 'Khi Hú-sai, người bạn của Đa-vít, người Archite, đến cùng Áp-sa-lôm, thì Hú-sai nói với Áp-sa-lôm: "Nguyện vua sống mãi, nguyện vua sống mãi."'),
(8444, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 16, 17, 'OT', 'Áp-sa-lôm nói với Hú-sai: "Đây có phải là lòng nhân từ của ngươi đối với bạn hữu ngươi không? Tại sao ngươi không đi theo bạn hữu ngươi?"'),
(8445, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 16, 18, 'OT', 'Hú-sai nói với Áp-sa-lôm: "Không phải vậy; nhưng ai mà Đức Giê-hô-va và dân này, cùng mọi người Y-sơ-ra-ên chọn, thì tôi sẽ thuộc về người đó và ở cùng người ấy."'),
(8446, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 16, 19, 'OT', 'Và lần thứ hai, tôi sẽ phục vụ ai? Há chẳng phải là trước mặt con trai người sao? Như tôi đã phục vụ trước mặt cha ngươi, thì tôi cũng sẽ phục vụ trước mặt ngươi.'),
(8447, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 16, 20, 'OT', 'Aù B-sa-lôm nói với A-chi-thô-phen: Hãy đưa ra ý kiến, chúng ta nên làm gì?'),
(8448, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 16, 21, 'OT', 'A-hi-thô-phên nói với Áp-sa-lôm: "Hãy đến cùng các thứ thiếp của cha ngươi, là những người đã để lại để giữ nhà; và toàn thể Y-sơ-ra-ên sẽ nghe rằng ngươi đã bị cha ngươi khinh bỉ; như vậy, các người đi theo ngươi sẽ thêm vững lòng."'),
(8449, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 16, 22, 'OT', 'Họ trải một cái lều cho Áp-sa-lôm trên mái nhà; và Áp-sa-lôm đi vào cùng các cung phi của cha mình, trước mặt toàn thể Y-sơ-ra-ên.'),
(8450, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 16, 23, 'OT', 'Lời khuyên của A-hi-thô-phên, mà ông đã góp ý trong những ngày ấy, giống như lời người ta cầu hỏi nơi lời Đức Chúa Trời; mọi lời khuyên của A-hi-thô-phên đều được xem trọng như vậy, cả đối với Đa-vít lẫn đối với Áp-sa-lôm.'),
(8451, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 17, 1, 'OT', 'Achitô-phen nói cùng Áp-sa-lôm: "Xin hãy để tôi chọn mười hai ngàn người ngay, và tôi sẽ đứng dậy, rượt đuổi theo Đa-vít trong đêm nay."'),
(8452, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 17, 2, 'OT', 'Tôi sẽ bất ngờ tấn công khi ông ta đang mệt mỏi và suy nhược tay chân, khiến ông ta hoảng sợ; toàn thể dân chúng đi cùng ông ta sẽ chạy trốn, và tôi sẽ đánh giết vua một mình.'),
(8453, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 17, 3, 'OT', 'Tôi sẽ đưa toàn thể dân chúng trở lại cùng ngài; khi người ấy mà ngài tìm kiếm trở về, thì toàn thể dân chúng sẽ được bình an.'),
(8454, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 17, 4, 'OT', 'Lời ấy đẹp lòng Áp-sa-lôm và lòng mọi bậc trưởng lão của Y-sơ-ra-ên.'),
(8455, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 17, 5, 'OT', 'Bấy giờ Áp-sa-lôm nói: "Hãy gọi cả Hú-sai người Archi nữa, để chúng ta nghe xem ông ấy nói gì."'),
(8456, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 17, 6, 'OT', 'Hết-sai đến cùng Áp-sa-lom; và Áp-sa-lom nói cùng người rằng: A-hi-thô-phên đã nói theo cách nầy; chúng ta có nên làm theo lời người nói không? Nếu không, hãy nói đi.'),
(8457, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 17, 7, 'OT', 'Hú-sai nói với Áp-sa-lôm: "Lời khuyên mà A-hi-thô-phên đã đưa ra lúc này không phải là điều tốt."'),
(8458, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 17, 8, 'OT', 'Hú-sai nói: "Ngài biết cha ngài và những người theo ông ấy; họ là những người dũng cảm, lòng đầy căm phẫn như con gấu bị mất gấu con ngoài đồng; cha ngài là một người quen trận mạc, và sẽ không ngủ với dân chúng."'),
(8459, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 17, 9, 'OT', 'Nầy, bây giờ người ấy đang ẩn mình trong một cái hố nào đó, hoặc tại một nơi nào; và xảy ra rằng khi một số người của Áp-sa-lôm ngã xuống lúc đầu, thì bất cứ ai nghe thấy điều đó sẽ nói: "Có một cuộc thảm sát giữa những người theo Áp-xa-lôm."'),
(8460, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 17, 10, 'OT', 'Người ấy cũng là một chiến sĩ gan dạ, lòng người ấy cứng như lòng sư tử, vậy mà sẽ tan chảy; vì toàn thể Y-sơ-ra-ên đều biết cha ngươi là một người hùng, và những người theo cùng người ấy đều là các chiến sĩ dũng cảm.'),
(8461, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 17, 11, 'OT', 'Vì vậy, tôi xin khuyên hãy triệu tập toàn thể Y-sơ-ra-ên đến cùng ngài, từ Đan cho đến Bê-ersê-va, đông như cát bên biển cả, và chính ngài phải ra đi chiến đấu.'),
(8462, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 17, 12, 'OT', 'Chúng tôi sẽ ập đến trên người ấy tại một nơi nào đó mà người ấy đang ở, và chúng tôi sẽ đè lên người ấy như sương rơi trên đất; không còn sót lại người ấy và bất kỳ một người nào trong số những người đi cùng người ấy.'),
(8463, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 17, 13, 'OT', 'Nếu người ấy rút vào một thành nào, thì toàn thể Y-sơ-ra-ên sẽ mang dây thừng đến thành ấy, và chúng ta sẽ kéo nó xuống sông, cho đến khi không còn tìm thấy tại đó một hòn đá nhỏ nào.'),
(8464, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 17, 14, 'OT', 'Áp-sa-lôm và mọi người Ít-ra-en đều nói: "Lời khuyên của Hú-sai người A-ki-thít tốt hơn lời khuyên của A-hi-thô-phên." Vì Đức Giê-hô-va đã định phá hủy lời khuyên tốt của A-hi-thô-phên, để Đức Giê-hô-va giáng điều ác trên Áp-sa-lôm.'),
(8465, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 17, 15, 'OT', 'Hú-sai nói với các thầy tế lễ Xa-đốc và A-bi-a-tha: "A-hi-thô-phên đã bày mưu như thế này, như thế này với Áp-sa-lôm và các trưởng lão của Y-sơ-ra-ên; còn tôi, tôi đã bày mưu như thế này, như thế này."'),
(8466, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 17, 16, 'OT', 'Bây giờ hãy nhanh chóng sai người đi báo cho Đa-vít rằng: "Đừng ngủ đêm nay tại các đồng bằng trong đồng vắng, mà hãy mau chóng qua bên kia, kẻo vua và toàn thể dân chúng đi theo người bị tiêu diệt."'),
(8467, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 17, 17, 'OT', 'Giô-na-than và A-hi-ma-ách đứng ở bên suối Rô-ghên; một nữ tì đi ra báo cho họ, rồi họ đi và báo cho vua Đa-vít, vì họ không thể để lộ mình mà vào thành được.'),
(8468, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 17, 18, 'OT', 'Một thiếu niên thấy họ và báo cho Áp-sa-lôm; nhưng hai người vội vã đi trốn, đến nhà một người đàn ông tại Bahurim, người ấy có một cái giếng trong sân, và họ xuống đó.'),
(8469, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 17, 19, 'OT', 'Người đàn bà lấy tấm vải trải phủ lên miệng giếng, rồi rải lúa xay lên trên, và sự việc không bị lộ ra.'),
(8470, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 17, 20, 'OT', 'Các đầy tớ của Áp-sa-lôm đến nhà người đàn bà ấy và nói: "Ahimaaz và Giô-na-than đâu rồi?" Người đàn bà trả lời họ: "Họ đã qua bên kia suối nước." Chúng tìm kiếm nhưng không tìm thấy, bèn trở về Giê-ru-sa-lem.'),
(8471, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 17, 21, 'OT', 'Sau khi họ đi rồi, hai người ấy liền lên khỏi giếng, đi đến và báo cho vua Đa-vít, rồi nói với Đa-vít: "Xin hãy đứng dậy, mau qua bên kia bờ sông; vì A-hi-thô-phên đã bày mưu nghịch cùng các ngài như thế này."'),
(8472, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 17, 22, 'OT', 'Đa-vít đứng dậy, cùng với toàn thể dân chúng đi theo ông, và họ đều qua sông Giô-đanh; đến sáng sớm, không một ai bị bỏ lại mà chưa qua sông Giô-đanh.'),
(8473, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 17, 23, 'OT', 'Khi A-hi-thô-phên thấy ý kiến mình không được chấp thuận, ông liền cỡi lừa, đứng dậy, trở về nhà mình tại thành phố ông, dặn dò gia đình mình xong, rồi thắt cổ tự tử; ông được chôn trong mồ mả của cha mình.'),
(8474, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 17, 24, 'OT', 'Đa-vít đến Ma-ha-na-im. Còn Áp-xa-lôm thì băng qua sông Giô-đanh, cùng với mọi người Ít-ra-en đi theo ông.'),
(8475, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 17, 25, 'OT', 'Aù-áp-sa-lom đặt A-ma-xa làm tư lệnh đạo quân thay cho Giô-áp; A-ma-xa là con trai một người đàn ông tên là Y-thơ-ra, người Y-sơ-ra-ên, người đã kết hôn với A-bi-gai-ên, con gái của Na-hách, em gái của Xê-ru-i-a, mẹ của Giô-áp.'),
(8476, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 17, 26, 'OT', 'Vua Ít-ra-en và Áp-sa-lôm đóng trại tại đất Gi-lead.'),
(8477, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 17, 27, 'OT', 'Khi Đa-vít đến Ma-ha-na-im, thì Xô-bi, con trai Na-hách, ở Ra-ba của con cái Am-môn, và Ma-kích, con trai A-mi-ên, ở Lô-đe-ba, và Ba-rê-xi-lai người Ghinh-ê-át, ở Rô-gê-lim,'),
(8478, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 17, 28, 'OT', 'Mang đến giường, chậu, đồ dùng bằng sành, lúa mì, lúa mạch, bột mì, lúa mạch rang, đậu xanh, đậu đỏ và các loại đậu rang.'),
(8479, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 17, 29, 'OT', 'Họ mang mật ong, pho mát, chiên và pho mát bò đến cho Đa-vít và cho dân chúng đi cùng ông để ăn, vì họ nói: "Dân chúng đang đói, mệt mỏi và khát trong đồng vắng."'),
(8480, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 1, 'OT', 'Đa-vít điểm duyệt dân chúng đi theo mình, rồi đặt những người chỉ huy từng ngàn người và những người chỉ huy từng trăm người.'),
(8481, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 2, 'OT', 'Đa-vít sai một phần ba dân chúng theo tay Giô-ab, một phần ba theo tay A-bi-sai, con trai Xê-ru-ya, anh em Giô-ab, và một phần ba theo tay Ít-tai người Ghít. Vua nói với dân chúng: "Chính ta cũng sẽ ra đi với các ngươi."'),
(8482, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 3, 'OT', 'Dân chúng nói: "Ngài không nên ra trận, vì nếu chúng tôi bỏ chạy, họ sẽ chẳng bận tâm đến chúng tôi; và nếu một nửa chúng tôi chết, họ cũng chẳng bận tâm đến chúng tôi. Nhưng hiện nay, ngài quý giá hơn mười ngàn người của chúng tôi. Vậy nên, tốt hơn là ngài ở lại thành mà hỗ trợ chúng tôi."'),
(8483, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 4, 'OT', 'Vua nói với họ: "Điều gì đẹp lòng các ngươi, ta sẽ làm." Vua đứng bên cạnh cửa thành, và toàn thể dân chúng ra đi từng trăm và từng ngàn người.'),
(8484, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 5, 'OT', 'Vua truyền lệnh cho Giô-áp, A-vi-sai và Ít-tai rằng: "Hãy đối xử dịu dàng với người thanh niên Áp-sa-lôm vì cớ ta." Toàn thể dân chúng nghe thấy khi vua truyền lệnh cho tất cả các viên tướng về chuyện Áp-sa-lôm.'),
(8485, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 6, 'OT', 'Dân chúng ra đi ra ngoài đồng ruộng nghênh chiến cùng Ít-ra-en; và cuộc chiến xảy ra trong rừng Ê-phrát-im.'),
(8486, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 7, 'OT', 'Dân Y-sơ-ra-ên bị đánh bại tại đó trước các đầy tớ của Đa-vít, và tại đó có một cuộc giết hại lớn trong ngày ấy, hai mươi ngàn người.'),
(8487, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 8, 'OT', 'Chiến trận bấy giờ lan rộng khắp mặt đất; và rừng nuốt mất nhiều người hơn số người mà gươm đã giết trong ngày ấy.'),
(8488, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 9, 'OT', 'Và Áp-sa-lôm gặp các đầy tớ của Đa-vít. Áp-sa-lôm đang cưỡi một con lừa, và khi con lừa đi dưới những cành rậm rạp của một cây sồi lớn, đầu ông bị mắc vào cành cây sồi; ông bị treo giữa trời và đất, còn con lừa ở dưới ông thì bỏ đi.'),
(8489, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 10, 'OT', 'Một người thấy vậy, liền báo cho Giô-áp, nói: Này, tôi thấy Áp-xa-lôm bị treo trên cây sồi.'),
(8490, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 11, 'OT', 'Giô-áp nói với người báo tin cho ông: "Nầy, ngươi đã thấy hắn, vậy sao ngươi không giết hắn tại đó? Ta sẽ trao cho ngươi mười miếng bạc và một cái đai."'),
(8491, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 12, 'OT', 'Người ấy nói với Giô-áp: "Dù tôi có nhận vào tay mình một ngàn mi-nga bạc, tôi cũng sẽ không tra tay vào hoàng tử, vì chính tai chúng tôi đã nghe vua dặn ông, A-bi-sai và Ít-tai rằng: Hãy giữ gìn cho trai trẻ Áp-sa-lôm."'),
(8492, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 13, 'OT', 'Hoặc nếu tôi đã làm điều gian dối với mạng sống mình, thì chẳng có việc gì giấu được vua; và chính ngài sẽ đứng lên chống lại tôi.'),
(8493, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 14, 'OT', 'Ông Giô-áp nói: "Tôi không thể nán lại đây với ngài như thế này." Rồi ông cầm ba cây giáo trong tay, đâm xuyên vào lòng Áp-xa-lôm khi ông ấy còn sống, giữa lúc đang ở trong cây sồi.'),
(8494, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 15, 'OT', 'Mười người trai trẻ mang khí giới của Giô-áp vây quanh, đánh Áp-sa-lôm và giết người.'),
(8495, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 16, 'OT', 'Giô-áp thổi kèn, và dân chúng ngừng đuổi theo Ít-ra-en; vì Giô-áp đã ngăn dân chúng lại.'),
(8496, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 17, 'OT', 'Họ lấy Áp-sa-lôm, ném hắn vào một cái hố lớn trong rừng, rồi chất một đống đá lớn lên trên hắn; và toàn thể Y-sơ-ra-ên đều chạy trốn, mỗi người về trại mình.'),
(8497, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 18, 'OT', 'Trước khi qua đời, Áp-sa-lôm đã lấy và dựng một cột kỷ niệm cho mình tại Thung lũng Vua, vì người nói: "Tôi không có con trai để ghi nhớ danh tôi." Người đã gọi cột kỷ niệm ấy theo tên mình, và cho đến ngày nay nó vẫn được gọi là Cột của Áp-sa-lôm.'),
(8498, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 19, 'OT', 'A-cha-im-ma-ách, con trai của Xa-đốc, nói: "Xin cho tôi chạy đi và báo tin cho vua, vì Đức Giê-hô-va đã cứu vua khỏi tay những kẻ thù nghịch của người."'),
(8499, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 20, 'OT', 'Vậy Giô-áp nói với người ấy: "Hôm nay ngươi không được báo tin mừng; ngươi hãy báo tin một ngày khác. Nhưng hôm nay ngươi không được báo tin, vì con trai của vua đã chết."'),
(8500, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 21, 'OT', 'Giô-áp bảo người Cu-si: "Hãy đi, báo cho vua điều ngươi đã thấy." Người Cu-si cúi mình trước Giô-áp rồi chạy đi.'),
(8501, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 22, 'OT', 'A-ki-ma-át, con trai của Xa-đốc, lại nói với Giô-áp: "Tôi xin được chạy theo người Ê-thi-ô-pi." Nhưng Giô-áp đáp: "Hỡi con ta, tại sao ngươi muốn chạy? Ngươi đâu có tin mừng gì để báo?"'),
(8502, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 23, 'OT', 'Dù sao đi nữa, xin cho tôi chạy, ông nói với ông ta. Vậy ông ta nói với ông ta: Hãy chạy đi. Thế là A-hi-ma-ách chạy theo đường đồng bằng, và vượt qua người Cu-si.'),
(8503, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 24, 'OT', 'Đa-vít đang ngồi giữa hai cổng thành; còn người canh gác thì đi lên mái nhà trên cổng thành gần vách thành, ngước mắt lên, nhìn thấy, và nầy, một người đang chạy một mình.'),
(8504, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 25, 'OT', 'Người canh gác kêu lên và báo cho vua biết. Vua nói: "Nếu một mình anh ta, thì có tin tức trong miệng anh ta." Người ấy cứ tiếp tục chạy tới gần.'),
(8505, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 26, 'OT', 'Người canh thấy một người chạy khác; người canh gọi người giữ cổng và nói: Kìa, một người chạy một mình. Vua nói: Cả người này cũng mang tin báo.'),
(8506, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 27, 'OT', 'Kẻ canh gác nói: "Tôi thấy người chạy đầu tiên giống như cách chạy của A-hi-ma-ách, con trai Xa-đốc." Vua nói: "Anh ta là người tốt, và anh ta đến chắc chắn mang tin lành."'),
(8507, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 28, 'OT', 'Ahimaách kêu lên và nói với vua: "Bình an!" Rồi người cúi mặt xuống đất trước mặt vua và nói: "Đáng chúc tụng thay Đức Giê-hô-va Đức Chúa Trời của ngài, Đấng đã trao những kẻ đã dơ tay nghịch cùng chủ tôi là vua."'),
(8508, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 29, 'OT', 'Vua nói: "Cậu thanh niên Áp-sa-lôm có bình an chăng?" Ahimaaz đáp: "Khi Giô-áp sai đầy tớ của vua và tôi là đầy tớ của ngài đi, tôi thấy một đám đông hỗn loạn, nhưng tôi không biết điều gì đã xảy ra."'),
(8509, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 30, 'OT', 'Vua nói: "Hãy tránh sang một bên và đứng ở đây." Vậy người ấy tránh sang một bên và đứng lại.'),
(8510, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 31, 'OT', 'Kìa, người Cu-si đến và nói: "Có tin lành cho vua chúa tôi! Hôm nay, Đức Giê-hô-va đã cứu vua khỏi tay mọi kẻ dấy lên nghịch cùng vua."'),
(8511, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 32, 'OT', 'Vua nói với người Cu-si: "Cậu thanh niên Áp-xa-lôm có được an toàn chăng?" Người Cu-si thưa: "Xin các kẻ thù của bệ hạ vua và mọi kẻ dấy lên nghịch cùng bệ hạ để làm hại, cũng đều như cậu thanh niên ấy."'),
(8512, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 18, 33, 'OT', 'Vua bồi hồi xúc động, liền lên phòng trên cổng thành mà khóc; và khi đi, ông nói: Hỡi con ta, Áp-xa-lôm, con ta, con ta Áp-xa-lôm! Thà rằng ta chết thay cho con, hỡi Áp-xa-lôm, con ta, con ta!'),
(8513, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 1, 'OT', 'Và người ta báo cho Giô-áp rằng: Nầy, vua đang khóc và than khóc vì Áp-sa-lôm.'),
(8514, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 2, 'OT', 'Và cuộc chiến thắng trong ngày ấy đã trở thành tang tóc cho toàn thể dân chúng; vì dân chúng nghe biết trong ngày ấy rằng vua đang buồn bã vì con trai mình.'),
(8515, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 3, 'OT', 'Dân chúng lén lút vào thành trong ngày đó, như thể dân chúng hổ thẹn lén lút bỏ chạy khi trốn thoát trong trận chiến.'),
(8516, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 4, 'OT', 'Vua thì thầm che mặt, và vua kêu lên bằng tiếng khóc lớn: "Hỡi con ta, Áp-sa-lôm! Áp-sa-lôm, con ta, con ta!"'),
(8517, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 5, 'OT', 'Vậy Giô-áp vào nhà cùng vua và nói: "Ngày nay ngài đã làm hổ thẹn mặt mọi tôi tớ của ngài, là những người vừa cứu mạng sống ngài hôm nay, cùng mạng sống các con trai, con gái, các vợ và các thứ thiếp của ngài."'),
(8518, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 6, 'OT', 'Ngươi đã yêu kẻ ghét ngươi và ghét những người yêu ngươi; vì hôm nay ngươi đã tỏ ra rằng ngươi không coi trọng các quan trưởng và đầy tớ mình; vì nay ta biết rằng Áp-sa-lôm còn sống thì ngươi sẽ vui lòng, dầu tất cả chúng ta phải chết hôm nay.'),
(8519, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 7, 'OT', 'Bây giờ, hãy chỗi dậy, ra đi và nói chuyện với các tôi tớ của ngươi; vì ta chỉ Đức Giê-hô-va mà thề rằng, nếu ngươi không ra đi, thì không một ai sẽ ở lại với ngươi đêm nay; và điều đó sẽ là tai họa cho ngươi, còn tệ hơn mọi tai họa mà ngươi đã gặp từ khi ngươi còn trẻ cho đến bây giờ.'),
(8520, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 8, 'OT', 'Vua chỗi dậy, ngồi nơi cửa thành. Người ta loan báo cho toàn dân biết rằng: "Nầy, vua đang ngồi tại cửa thành." Thế là toàn dân đến trình diện trước mặt vua. Còn dân Y-sơ-ra-ên thì ai nấy đều chạy trốn về trại của mình.'),
(8521, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 9, 'OT', 'Toàn thể dân chúng tranh cãi nhau giữa các chi phái của Y-sơ-ra-ên, nói rằng: "Vua đã giải cứu chúng ta khỏi tay kẻ thù chúng ta, chính người đã cứu chúng ta khỏi tay người Phi-li-tin; vậy mà bây giờ người phải trốn khỏi đất nước vì Áp-sa-lôm."'),
(8522, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 10, 'OT', 'Và Áp-sa-lôm, người mà chúng ta đã xức vua cho mình, đã chết trong trận chiến; vậy bây giờ tại sao các ngươi lại im lặng, không nói một lời nào về việc đưa vua trở về?'),
(8523, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 11, 'OT', 'Vua Đa-vít sai đến thầy tế lễ Xa-đốc và A-bi-a-tha, nói: "Hãy nói với các trưởng lão của Giu-đa rằng: ''Tại sao các ngươi lại là những người cuối cùng đưa vua trở về nhà mình? Trong khi lời nói của cả Ít-ra-en đã hướng về vua, để đưa người trở về nhà.''"'),
(8524, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 12, 'OT', 'Anh em đây, chính là xương thịt tôi; vậy sao lại là những người cuối cùng đưa vua trở lại?'),
(8525, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 13, 'OT', 'Hãy nói với A-ma-sa rằng: "Chẳng phải ngươi là xương thịt ta sao? Nguyện Đức Chúa Trời làm cho ta như vậy và còn gia thêm nữa, nếu ngươi không làm tướng chỉ huy đạo binh trước mặt ta luôn mãi, thay cho Giô-áp."'),
(8526, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 14, 'OT', 'Người khiến lòng mọi người Giu-đa nghiêng về như lòng một người, nên họ sai sứ đến vua rằng: "Xin hãy trở về, và cả các đầy tớ của ngài nữa."'),
(8527, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 15, 'OT', 'Vua trở về và đến tận sông Giô-đanh. Người Giu-đa đến Ghinh-ganh để đi ra gặp vua và giúp vua qua sông Giô-đanh.'),
(8528, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 16, 'OT', 'Và Si-mê-i, con trai của Gera, người thuộc chi phái Bên-gia-min, ở Ba-hu-rim, vội vàng đi xuống cùng các người của Giu-đa để đón vua Đa-vít.'),
(8529, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 17, 'OT', 'Một ngàn người của chi phái Bên-gia-min cùng với mình, và Xi-ba, đầy tớ nhà Sau-lơ, cùng mười lăm người con trai và hai mươi đầy tớ của ông ấy; họ đã qua sông Giô-đanh trước mặt vua.'),
(8530, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 18, 'OT', 'Và một chiếc phà qua sông đã qua để chở gia quyến của vua sang và làm điều tốt theo ý vua; còn Sê-mai, con trai của Ghê-ra, thì sấp mình xuống trước mặt vua khi vua vừa qua sông Giô-đanh.'),
(8531, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 19, 'OT', 'Mà nói cùng vua rằng: "Xin chúa tôi đừng coi tôi là có tội, và xin đừng nhớ điều gì kẻ tôi tớ ngài đã làm trái ngày chúa tôi là vua ra đi từ Giê-ru-sa-lem, để vua đừng để điều đó vào lòng."'),
(8532, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 20, 'OT', 'Vì tôi tớ ngươi biết rằng tôi đã phạm tội; vậy nầy, hôm nay tôi là người đầu tiên trong cả nhà Y-sách đến đây để xuống gặp chúa tôi là vua.'),
(8533, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 21, 'OT', 'A-bi-sai, con trai của Xê-ru-ya, thưa rằng: "Chẳng lẽ Si-mê-i sẽ không bị xử tử vì điều này sao, bởi người ấy đã nguyền rủa Đấng được Đức Giê-hô-va xức dầu?"'),
(8534, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 22, 'OT', 'Đa-vít nói: Ta có liên hệ gì với các ngươi, hỡi các con trai của Xê-ru-ya, mà ngày nay các ngươi lại chống lại ta? Há có người nào bị xử tử hôm nay trong Y-sơ-ra-ên sao? Bởi lẽ chẳng phải ta biết rằng hôm nay ta là vua cai trị Y-sơ-ra-ên sao?'),
(8535, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 23, 'OT', 'Vua nói với Si-mê-i: "Ngươi sẽ không chết." Và vua đã thề hứa cùng người ấy.'),
(8536, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 24, 'OT', 'Mê-phi-bô-sết, con trai của Sa-un, đi xuống để đón vua; người ấy không chăm sóc bàn chân mình, không cắt tỉa râu, cũng không giặt quần áo, từ ngày vua ra đi cho đến ngày vua trở lại bình an.'),
(8537, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 25, 'OT', 'Khi ông đến Giê-ru-sa-lem để đón vua, thì vua nói với ông: "Tại sao ngươi không đi cùng ta, Mê-phi-bô-sết?"'),
(8538, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 26, 'OT', 'Vua chúa, tôi tớ ngài đã lừa dối tôi, vì tôi tớ người nói: "Hãy đóng yên lừa cho tôi, để tôi cỡi và đi gặp vua," vì tôi tớ người què.'),
(8539, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 27, 'OT', 'Và người đã nói xấu tôi với chủ tôi là đức vua; nhưng chủ tôi là đức vua giống như thiên sứ của Đức Chúa Trời vậy: xin hãy làm điều tốt lành trong mắt ngài.'),
(8540, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 28, 'OT', 'Vì toàn thể gia đình cha tôi chẳng qua chỉ là những người đáng chết trước mặt đức vua, chủ tôi; thế mà ngài đã đặt đầy tớ của ngài vào hàng những người ăn tại bàn vua. Vậy tôi còn lý do chính đáng nào nữa để kêu cứu đến đức vua thêm chăng?'),
(8541, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 29, 'OT', 'Vua nói với ông: "Sao ngươi còn nói thêm điều gì nữa? Ta đã phán: Ngươi và Xi-ba phải chia nhau thửa đất."'),
(8542, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 30, 'OT', 'Mê-phi-bô-sết nói với vua: "Cả mọi điều đó, xin người hãy lấy đi; miễn là chúa tôi, vua, đã trở về bình an trong nhà mình."'),
(8543, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 31, 'OT', 'Và Ban-xi-đai người Ghi-lê-át đi xuống từ Rô-ghê-lim, rồi qua sông Giô-đanh với vua để tiễn vua qua sông Giô-đanh.'),
(8544, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 32, 'OT', 'Bấy giờ Bát-xi-đai đã rất già, tám mươi tuổi; ông đã tiếp tế lương thực cho vua khi vua ở Mahanaim, vì ông là một người rất giàu có.'),
(8545, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 33, 'OT', 'Vua nói với Bát-xi-đai: "Hãy đi qua đây với ta, và ta sẽ nuôi ông ở cùng ta tại Giê-ru-sa-lem."'),
(8546, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 34, 'OT', 'Bát-xi-lai nói với vua: "Tôi còn sống được bao nhiêu ngày nữa, mà đi lên cùng vua đến Giê-ru-sa-lem?"'),
(8547, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 35, 'OT', 'Tôi hôm nay đã tám mươi tuổi rồi; tôi còn phân biệt được điều lành điều dữ sao? Tôi tôi có nếm được gì tôi ăn hay gì tôi uống không? Tôi tôi có còn nghe được tiếng các nhạc sĩ nam và nhạc sĩ nữ nữa không? Vậy thì tại sao tôi tôi lại còn trở thành gánh nặng cho chúa tôi là vua nữa?'),
(8548, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 36, 'OT', 'Tôi hầu hạ vua đi một đoạn ngắn qua sông Giô-đanh cùng với vua; vậy tại sao vua lại ban cho tôi tớ nầy một phần thưởng lớn như thế?'),
(8549, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 37, 'OT', 'Xin hãy để cho đầy tớ của ngài trở về, và qua đời tại thành phố của tôi, bên cạnh mộ phần của cha tôi và mẹ tôi. Còn đầy tớ của ngài là Kim-ham, xin để người ấy đi qua cùng với chủ nhân tôi là đức vua; và xin ngài làm điều tốt lành theo mắt ngài thấy cho là phải đối với người.'),
(8550, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 38, 'OT', 'Vua đáp: "Chim-ham sẽ đi qua cùng ta, và ta sẽ làm điều tốt lành trước mặt ngươi cho người ấy; và mọi điều ngươi muốn ta làm, ta sẽ làm cho ngươi."'),
(8551, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 39, 'OT', 'Toàn thể dân chúng qua sông Giô-đanh, rồi vua cũng qua. Vua hôn ông Bát-xi-đai và ban phước cho ông; rồi ông trở về nơi mình.'),
(8552, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 40, 'OT', 'Vua băng qua Gilgal, và Chimham cũng băng qua cùng người; và toàn thể dân Giu-đa cùng băng qua với vua, và cả một nửa dân Y-sơ-ra-ên.'),
(8553, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 41, 'OT', 'Nầy, toàn thể người Y-sơ-ra-ên đều đến cùng vua và nói với vua: "Tại sao anh em chúng tôi, những người của Giu-đa, lại lén mang vua đi, rồi đưa vua cùng gia quyến và tất cả những người của Đa-vít đi qua sông Giô-đanh?"'),
(8554, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 42, 'OT', 'Tất cả những người của Giu-đa đáp lại những người của Y-sơ-ra-ên rằng: "Vì vua là người thân cận với chúng tôi; vậy thì tại sao các ngươi lại nổi giận về điều này? Chúng tôi có ăn gì từ của vua không? Hay là người đã ban cho chúng tôi một món quà nào?"'),
(8555, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 19, 43, 'OT', 'Người của Y-sơ-ra-ên đáp lại người của Giu-đa và nói: "Tôi có mười phần trong vua, và tôi cũng có quyền lợi nơi Đa-vít hơn ông; vậy tại sao ông khinh tôi, khiến cho lời tôi không được hỏi đến trước khi rước vua tôi trở lại?" Nhưng lời của người Giu-đa lại cứng cỏi hơn lời của người Y-sơ-ra-ên.'),
(8556, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 20, 1, 'OT', 'Tại đó có một người vô lại tên là Sê-ba, con trai Bích-ri, người thuộc chi phái Bên-gia-min. Người ấy thổi kèn và nói: "Chúng ta chẳng có phần gì với Đa-vít, cũng chẳng có phần kế tự nào với con trai Y-sai. Mỗi người về lều mình đi, hỡi Ít-ra-en!"'),
(8557, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 20, 2, 'OT', 'Mọi người Ít-ra-en đều đi theo Sau-ba, con trai Bích-ri, rời bỏ Đa-vít; còn những người Giu-đa thì trung thành với vua mình, từ sông Giô-đanh cho đến Giê-ru-sa-lem.'),
(8558, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 20, 3, 'OT', 'Đa-vít vào nhà mình tại Giê-ru-sa-lem. Vua lấy mười người nữ lẽ mà ông đã để lại giữ nhà, giam họ trong một nơi ở riêng, cung cấp thức ăn cho họ, nhưng không đến cùng họ. Họ bị giam giữ như thế cho đến ngày chết, sống trong cảnh goá bụa.'),
(8559, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 20, 4, 'OT', 'Vua nói với A-ma-sa: "Hãy triệu tập cho ta mọi người của Giu-đa trong vòng ba ngày, và ngươi phải ở đây."'),
(8560, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 20, 5, 'OT', 'Ông A-ma-sa đi thu góp người Giu-đa, nhưng ông đã để lỡ quá thời hạn mà người đã ấn định cho ông.'),
(8561, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 20, 6, 'OT', 'Đa-vít nói với A-bi-sai: "Bây giờ, Sê-ba con trai của Bích-ri sẽ gây hại cho chúng ta hơn Áp-sa-lôm. Ngươi hãy đem các đầy tớ của chủ ngươi đi đuổi theo nó, kẻo nó chiếm được các thành có vách thành vững chắc và trốn thoát khỏi tay chúng ta."'),
(8562, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 20, 7, 'OT', 'Người của Giô-áp, các Kê-rê-thi, các Phê-lê-thi và tất cả các chiến sĩ mạnh mẽ ra đi theo ông, và họ rời khỏi Giê-ru-sa-lem để truy đuổi Sê-ba, con trai của Bích-ri.'),
(8563, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 20, 8, 'OT', 'Họ đang ở gần tảng đá lớn tại Ghi-bê-ôn thì A-ma-sa đi ra đón họ. Còn Giô-áp thì mặc áo trong, thắt đai, và trên đai có tra gươm vào bao nơi hông; khi ông bước tới, gươm ấy liền rơi xuống.'),
(8564, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 20, 9, 'OT', 'Giô-áp nói với A-ma-sai: "Anh có khỏe không, hỡi anh em tôi?" Rồi Giô-áp dùng tay phải nắm râu A-ma-sai để hôn người.'),
(8565, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 20, 10, 'OT', 'A-ma-sa không đề phòng thanh gươm trong tay Giô-áp, nên Giô-áp dùng gươm đó đâm vào bụng người ấy, khiến ruột đổ ra đất; người không kịp đâm lại, bèn chết. Rồi Giô-áp và Áp-bi-sai, anh người ấy, tiếp tục đuổi theo Sê-ba, con trai Bích-ri.'),
(8566, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 20, 11, 'OT', 'Một người trong các đầy tớ của Giô-áp đứng gần người đó và nói: "Ai muốn theo Giô-áp, ai thuộc về Đa-vít, hãy đi theo Giô-áp."'),
(8567, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 20, 12, 'OT', 'Bấy giờ A-ma-sa nằm lăn lộn trong vũng máu giữa đường cái. Một người thấy rằng toàn dân đứng lại, bèn khiêng A-ma-sa ra khỏi đường cái đặt vào đồng ruộng, rồi lấy một tấm vải phủ lên người anh ta; vì khi thấy ai đi ngang qua cũng đều dừng lại.'),
(8568, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 20, 13, 'OT', 'Khi người ấy bị dời khỏi con đường cái, mọi người đều đi theo Giô-áp để đuổi theo Sê-ba, con trai của Bích-ri.'),
(8569, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 20, 14, 'OT', 'Người ấy đi qua tất cả các chi phái của Y-sơ-ra-ên, đến A-bên và Bết Ma-a-ca, cùng với toàn thể các người Bê-ri; họ bèn nhóm họp lại và cũng đi theo người ấy.'),
(8570, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 20, 15, 'OT', 'Họ đến vây hãm người tại A-bên của Bết Ma-a-cha, và đổ đống đất chống thành; thành đứng vững trong hào. Toàn dân đi theo Giô-áp đang phá tường để làm sập xuống.'),
(8571, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 20, 16, 'OT', 'Một người phụ nữ khôn ngoan từ trong thành kêu lên: "Hãy nghe, hãy nghe! Xin hãy nói cùng Giô-ab: Xin ngài lại gần đây, để tôi nói chuyện cùng ngài."'),
(8572, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 20, 17, 'OT', 'Người đến gần bà, bà nói: "Ông có phải là Giô-áp không?" Ông trả lời: "Chính tôi." Bà nói với ông: "Xin ông hãy nghe lời của tớ nữ ông." Ông đáp: "Tôi đang nghe."'),
(8573, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 20, 18, 'OT', 'Bà ấy nói tiếp: "Trước kia người ta thường nói, ''Người ta sẽ hỏi tại A-bel,'' và như vậy, mọi việc được giải quyết."'),
(8574, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 20, 19, 'OT', 'Tôi là người hâm mộ hòa bình và trung thành trong Y-sơ-ra-ên. Ngài đang tìm cách tiêu diệt một thành và một mẹ trong Y-sơ-ra-ên. Tại sao Ngài nuốt lấy cơ nghiệp của Đức Giê-hô-va?'),
(8575, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 20, 20, 'OT', 'Ông Giô-áp đáp và nói: Xin đừng, xin đừng để tôi nuốt chửng hay hủy diệt.'),
(8576, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 20, 21, 'OT', 'Không phải như vậy; một người từ núi Ép-ra-im, tên là Sê-ba con trai của Bích-ri, đã chống cự lại vua Đa-vít. Hãy trao cho tôi một mình người đó, thì tôi sẽ rút lui khỏi thành phố. Người đàn bà nói với Giô-áp: Này, đầu của người ấy sẽ bị ném xuống cho ông qua bức tường.'),
(8577, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 20, 22, 'OT', 'Bà ấy trở về cùng toàn thể dân chúng với sự khôn ngoan của mình. Họ liền chặt đầu Sê-ba, con trai của Bích-ri, và ném ra cho Giô-áp. Giô-áp thổi tiếng tù và, và mọi người bèn giải tán, mỗi người trở về lều mình. Còn Giô-áp thì trở về Giê-ru-sa-lem cùng với vua.'),
(8578, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 20, 23, 'OT', 'Giô-áp làm tổng chỉ huy toàn thể đạo quân Ít-ra-en; còn Bê-na-gia, con trai của Giê-hô-gia-đa, thì chỉ huy các người Kê-rê-thít và các người Pê-lê-thít.'),
(8579, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 20, 24, 'OT', 'A-đô-ram quản lý việc sưu thuế; Giô-sa-phát, con trai A-hi-lút, làm quan ghi chép.'),
(8580, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 20, 25, 'OT', 'Và Sheva làm quan văn thư; còn Xa-đốc và A-bi-a-tha làm thầy tế lễ.'),
(8581, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 20, 26, 'OT', 'Vả lại, Ira người Ja-ri cũng là thầy tế lễ cho Đa-vít.'),
(8582, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 21, 1, 'OT', 'Trong những ngày Đa-vít, có nạn đói kéo dài ba năm, năm này qua năm khác; Đa-vít cầu hỏi mặt Đức Giê-hô-va. Đức Giê-hô-va phán với ông: "Là vì Sa-un và nhà của người đầy máu, vì người đã giết dân Ghi-bê-ôn."'),
(8583, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 21, 2, 'OT', 'Vua sai gọi người Ghi-bê-ôn và nói với họ; (người Ghi-bê-ôn không phải là con cháu Y-sơ-ra-ên, nhưng thuộc tàn dư của người A-mô-rị; và con cháu Y-sơ-ra-ên đã thề hứa với họ); song Sau-lơ đã tìm cách giết họ vì lòng sốt sắng của ông dành cho con cháu Y-sơ-ra-ên và Giu-đa.'),
(8584, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 21, 3, 'OT', 'Vua Đa-vít hỏi người Gíp-bê-on: "Tôi phải làm gì cho các ngươi, và bằng cách nào tôi có thể đền tội để các ngươi ban phước cho sản nghiệp của Đức Giê-hô-va?"'),
(8585, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 21, 4, 'OT', 'Người Gi-bê-on nói với người đó: "Chúng tôi chẳng có bạc hay vàng gì với Sau-lơ hay với nhà người; chúng tôi cũng chẳng có quyền giết ai trong Ít-ra-en." Người ấy nói: "Các ngươi muốn tôi làm gì, ta sẽ làm cho các ngươi."'),
(8586, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 21, 5, 'OT', 'Họ thưa với vua: "Người đàn ông đã tiêu diệt chúng tôi, và đã bày mưu chống lại chúng tôi, khiến chúng tôi bị tiêu diệt, không còn đứng vững được trên bất kỳ vùng đất nào của Ít-ra-en."'),
(8587, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 21, 6, 'OT', 'Hãy giao cho chúng tôi bảy người con trai của hắn, để chúng tôi treo cổ chúng trước mặt Đức Giê-hô-va tại Ghi-bê-ah của Sau-lơ, kẻ được Đức Giê-hô-va chọn. Vua nói: Ta sẽ giao nộp.'),
(8588, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 21, 7, 'OT', 'Vua thương xót Mê-phi-bô-sết, con trai của Giô-na-than, con trai của Sa-un, vì lời thề của Đức Giê-hô-va đã lập giữa ông và Đa-vít, giữa Đa-vít và Giô-na-than, con trai của Sa-un.'),
(8589, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 21, 8, 'OT', 'Vua đem hai con trai của Ríp-ca, con gái của A-i-a, mà bà đã sinh cho Sau-lơ, là Ác-mô-ni và Mê-phi-bô-sết, cùng với năm con trai của Mi-kal, con gái của Sau-lơ, mà bà đã sinh cho A-đơ-ri-ên, con trai của Ba-r-xi-lai người Mê-hô-lát.'),
(8590, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 21, 9, 'OT', 'Trao họ vào tay người Ghi-bê-ôn, và họ treo họ trên núi trước mặt Đức Giê-hô-va; bảy người ngã xuống cùng nhau, và bị giết trong những ngày gặt hái, những ngày đầu tiên, lúc bắt đầu mùa gặt lúa mạch.'),
(8591, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 21, 10, 'OT', 'Rít-ba, con gái của A-i-a, lấy tấm vải thô trải ra cho mình trên tảng đá, từ khi bắt đầu mùa gặt cho đến khi nước từ trời rơi xuống trên chúng; bà không để chim trời đậu trên chúng ban ngày, cũng không để thú rừng đậu trên chúng ban đêm.'),
(8592, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 21, 11, 'OT', 'Đa-vít được báo tin về điều mà Rít-pha, con gái của Ai-gia, người hầu thiếp của Sau-lơ, đã làm.'),
(8593, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 21, 12, 'OT', 'Vua Đa-vít đi lấy hài cốt của Sau-lơ và hài cốt của Giô-na-than, con trai ông, từ những người ở Gia-bết Ga-lean, là những người đã trộm lấy chúng khỏi quảng trường Bê-th-sán, nơi người Phi-li-tin treo xác họ lên, khi người Phi-li-tin giết Sau-lơ tại Ghinh-boa.'),
(8594, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 21, 13, 'OT', 'Người ấy đem lên từ nơi đó hài cốt của Sau-lơ và hài cốt của Giô-na-than, con trai người; và họ thu góp các hài cốt của những người bị treo lên.'),
(8595, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 21, 14, 'OT', 'Họ chôn cất các hài cốt của Sa-un và Yô-na-than, con trai người, tại xứ Bên-gia-min, ở Xê-la, trong phần mộ của Kích, cha người. Họ thực hiện mọi điều mà vua đã truyền dặn. Sau đó, Đức Chúa Trời thương xót đất nước.'),
(8596, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 21, 15, 'OT', 'Người Phi-li-tin lại gây chiến tranh với Ít-ra-en; Đa-vít đi xuống cùng các đầy tớ mình và chiến đấu chống lại người Phi-li-tin; rồi Đa-vít mệt lả.'),
(8597, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 21, 16, 'OT', 'Và có người thuộc con cháu Râ-pha, tên là Ishbi-Benob, chiếc giáo của anh ta nặng ba trăm sicl đồng; anh ta được thắt gươm mới, và nói muốn giết vua Đa-vít.'),
(8598, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 21, 17, 'OT', 'Nhưng A-bi-sai, con trai của Xê-ru-gia, đến giúp vua và đánh giết người Phi-ti-nhít. Bấy giờ các người của Đa-vít thề với vua rằng: "Ngài sẽ không đi ra chiến trận với chúng tôi nữa, hầu đừng dập tắt ngọn đèn của Ít-ra-en."'),
(8599, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 21, 18, 'OT', 'Sau những việc ấy, lại xảy ra trận chiến khác với người Phi-li-tin tại Gôp; bấy giờ Xi-bê-cai người Hút-tha giết Xáp, một trong các con trai của người Rê-pha-im.'),
(8600, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 21, 19, 'OT', 'Lại có cuộc chiến khác tại Gob với người Phi-li-tin, và Ê-lha-nan, con trai của Gai-ê-ô-rê-gim, người Bết-lê-hem, đã giết Gô-li-át người Gát; còn cán ngọn giáo của hắn thì như cây thoi của thợ dệt.'),
(8601, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 21, 20, 'OT', 'Lại xảy ra một trận chiến ở Gat, và có một người đàn ông ở đó, cả tay và chân của anh ta đều có sáu ngón, tổng cộng hai mươi bốn; người này cũng là con cháu của người Râ-pha.'),
(8602, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 21, 21, 'OT', 'Người ấy lên tiếng nguyền rủa Y-sơ-ra-ên, và Giô-na-than, con trai của Sê-mê-a, anh em của Đa-vít, đã giết người ấy.'),
(8603, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 21, 22, 'OT', 'Bốn người này sinh ra cho người khổng lồ ở Gat, và ngã xuống bởi tay Đa-vít và bởi tay các đầy tớ người.'),
(8604, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 1, 'OT', 'Đa-vít nói với Đức Giê-hô-va những lời bài ca nầy, vào ngày Đức Giê-hô-va giải cứu ông khỏi tay mọi kẻ thù và khỏi tay Sau-lơ.'),
(8605, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 2, 'OT', 'Đức Giê-hô-va là hòn đá của tôi, là thành trì của tôi, là nơi tôi được giải cứu.'),
(8606, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 3, 'OT', 'Đức Chúa Trời là hòn đá của tôi, nơi tôi nương náu; Ngài là cái khiên tôi, sừng cứu rỗi tôi, nơi tôi được bảo vệ và được che chở, là Đấng cứu tôi khỏi sự bạo lực.'),
(8607, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 4, 'OT', 'Ta sẽ kêu cầu Đức Giê-hô-va, là Đấng đáng được ca ngợi; và ta sẽ được cứu khỏi các kẻ thù mình.'),
(8608, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 5, 'OT', 'Vì các cơn nguy hiểm của sự chết đã vây hãm tôi; các dòng nước của phường ác đã làm tôi khiếp sợ.'),
(8609, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 6, 'OT', 'Các dây trói của âm phủ bao vây tôi; những bẫy chết người đã chặn trước mặt tôi.'),
(8610, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 7, 'OT', 'Trong cơn khốn khổ, tôi kêu cầu Đức Giê-hô-va và cầu xin Đức Chúa Trời tôi; Ngài đã nghe tiếng tôi từ đền thánh Ngài, và tiếng kêu cứu của tôi đã thấu đến tai Ngài.'),
(8611, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 8, 'OT', 'Đất rung chuyển và rúng động; các nền trời lay động và rung rinh, vì Ngài nổi giận.'),
(8612, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 9, 'OT', 'Khói bốc lên nơi cơn thịnh nộ của Ngài, và lửa từ miệng Ngài nuốt hết; những than hồng bừng cháy từ nơi Ngài.'),
(8613, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 10, 'OT', 'Người làm nghiêng trời và ngự xuống; và bóng tối ở dưới chân Người.'),
(8614, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 11, 'OT', 'Và Ngài cỡi trên một con kerub, rồi bay đi; Ngài hiện ra trên cánh của ngọn gió.'),
(8615, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 12, 'OT', 'Đức Giê-hô-va đặt sự tối tăm làm mái che xung quanh Ngài, là những đám mây đen dày đặc của các tầng trời.'),
(8616, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 13, 'OT', 'Từ ánh sáng rực rỡ trước mặt Ngài, những than hồng lửa bùng cháy.'),
(8617, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 14, 'OT', 'Đức Giê-hô-va sấm sét từ các từng trời, và Đấng Chí Cao phát ra tiếng Ngài.'),
(8618, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 15, 'OT', 'Người đã sai những mũi tên ra và làm chúng tan tác; sai chớp xuống và khiến chúng rối loạn.'),
(8619, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 16, 'OT', 'Các khe biển hiện ra, nền tảng của thế gian lộ rõ, bởi sự quở trách của Đức Giê-hô-va, bởi hơi thở từ mũi Ngài.'),
(8620, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 17, 'OT', 'Đức Giê-hô-va sai từ trên cao, Ngài tiếp lấy tôi; Ngài kéo tôi ra khỏi nhiều dòng nước.'),
(8621, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 18, 'OT', 'Đức Giê-hô-va giải cứu tôi khỏi kẻ thù mạnh mẽ, khỏi những người ghét tôi, vì chúng mạnh hơn tôi.'),
(8622, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 19, 'OT', 'Chúng chống lại tôi trong ngày tai họa của tôi; nhưng Đức Giê-hô-va là nơi tôi nương náu.'),
(8623, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 20, 'OT', 'Người đưa tôi ra nơi rộng rãi; Ngài giải cứu tôi, vì Ngài hài lòng về tôi.'),
(8624, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 21, 'OT', 'Đức Giê-hô-va đáp ứng tôi theo sự công chính của tôi; theo sự trong sạch nơi tay tôi, Ngài đã trả lại cho tôi.'),
(8625, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 22, 'OT', 'Vì tôi đã giữ các đường lối của Đức Giê-hô-va, và không gian ác lìa bỏ Đức Chúa Trời tôi.'),
(8626, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 23, 'OT', 'Vì mọi phán quyết của Ngài đều ở trước mặt tôi, và những điều lệ của Ngài, tôi không hề lìa bỏ.'),
(8627, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 24, 'OT', 'Ta đã sống trọn vẹn trước mặt Ngài, và giữ mình khỏi tội lỗi của ta.'),
(8628, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 25, 'OT', 'Vì vậy, Đức Giê-hô-va đã đáp trả tôi theo sự công bình của tôi, theo sự thanh sạch của tôi trong mắt Ngài.'),
(8629, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 26, 'OT', 'Với người nhân từ, Ngài tỏ ra nhân từ; với người ngay thẳng, Ngài tỏ ra hoàn toàn ngay thẳng.'),
(8630, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 27, 'OT', 'Với người thanh khiết, Ngài tỏ ra thanh khiết; còn với kẻ quanh co, Ngài tỏ ra vặn vẹo.'),
(8631, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 28, 'OT', 'Và dân khiêm nhường, Ngài sẽ cứu giúp; nhưng mắt Ngài sẽ nhìn trên những kẻ kiêu ngạo để hạ họ xuống.'),
(8632, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 29, 'OT', 'Vì chính Ngài là ngọn đèn của tôi, Đức Giê-hô-va; và Đức Giê-hô-va sẽ soi sáng tăm tối tôi.'),
(8633, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 30, 'OT', 'Vì nhờ Ngài, tôi có thể xông qua đoàn quân; nhờ Đức Chúa Trời tôi, tôi có thể nhảy qua vách tường.'),
(8634, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 31, 'OT', 'Đức Chúa Trời, đường lối Ngài thật hoàn hảo; lời Đức Giê-hô-va đã được thử luyện; Ngài là cái khiên che chở cho mọi người tin cậy nơi Ngài.'),
(8635, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 32, 'OT', 'Vì ai là Đức Chúa Trời ngoài Đức Giê-hô-va? Và ai là vầng đá ngoài Đức Chúa Trời của chúng ta?'),
(8636, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 33, 'OT', 'Đức Chúa Trời là sức lực và quyền năng của tôi; Ngài làm cho đường lối tôi trọn vẹn.'),
(8637, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 34, 'OT', 'Chúa làm cho chân tôi như chân nai, và đặt tôi trên các nơi cao.'),
(8638, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 35, 'OT', 'Dạy tay tôi giao chiến, và khiến cánh tay tôi bẻ gãy cây cung bằng đồng.'),
(8639, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 36, 'OT', 'Ngài đã ban cho tôi cái khiên của sự cứu rỗi Ngài; và sự nhân từ của Ngài khiến tôi được lớn lên.'),
(8640, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 37, 'OT', 'Người đã làm rộng bước đi của tôi dưới tôi, và bàn chân tôi không vấp ngã.'),
(8641, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 38, 'OT', 'Tôi đã đuổi theo kẻ thù mình và tiêu diệt chúng; tôi đã không quay trở lại cho đến khi chúng bị tiêu diệt.'),
(8642, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 39, 'OT', 'Ta đã tiêu diệt chúng, nghiền nát chúng, khiến chúng không thể đứng dậy; vâng, chúng đã ngã xuống dưới chân Ta.'),
(8643, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 40, 'OT', 'Ngài đã lấy sức mạnh làm đai thắt cho tôi ra trận; những kẻ dấy lên nghịch tôi, Ngài đã khiến họ khuất phục dưới tôi.'),
(8644, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 41, 'OT', 'Người thù nghịch ta, Ngài khiến phải quay lưng chạy trốn; kẻ ghét ta, ta tiêu diệt chúng.'),
(8645, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 42, 'OT', 'Chúng kêu cứu, nhưng chẳng có ai cứu giúp; chúng kêu cầu Đức Giê-hô-va, nhưng Ngài không trả lời.'),
(8646, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 43, 'OT', 'Ta nghiền chúng ra như bụi đất, đạp chúng như bùn ngoài đường, giẫm nát chúng.'),
(8647, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 44, 'OT', 'Ngài đã giải cứu tôi khỏi những tranh chấp của dân tôi, giữ tôi làm đầu các dân tộc; một dân mà tôi chưa từng biết sẽ phục vụ tôi.'),
(8648, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 45, 'OT', 'Các con của người ngoại sẽ chối ta, nghe tiếng thì phải vâng phục ta.'),
(8649, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 46, 'OT', 'Các con của kẻ ngoại bang sẽ tiêu tan, và run sợ từ các nơi ẩn náu của chúng.'),
(8650, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 47, 'OT', 'Đức Giê-hô-va hằng sống; xin phước cho hòn đá tôi. Nguyện Đức Chúa Trời của hòn đá cứu rỗi tôi được tôn cao.'),
(8651, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 48, 'OT', 'Đức Chúa Trời là Đấng ban cho tôi sự báo phục, và khiến các dân xuống dưới tôi.'),
(8652, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 49, 'OT', 'Và Đấng kéo tôi ra khỏi kẻ thù tôi; Ngài cũng nâng tôi lên cao vượt trên những kẻ dấy nghịch tôi; Ngài giải cứu tôi khỏi tay người đàn ông bạo ác.'),
(8653, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 50, 'OT', 'Vì vậy, tôi sẽ cảm tạ Đức Giê-hô-va giữa các dân tộc, và tôi sẽ hát ca ngợi danh Ngài.'),
(8654, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 22, 51, 'OT', 'Đức Giê-hô-va làm cho sự cứu rỗi của vua mình được cao lớn, và bày tỏ lòng nhân từ đối với Đấng Xức Dầu của Ngài, tức là Đa-vít và dòng dõi người cho đến đời đời.'),
(8655, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 1, 'OT', 'Đây là những lời cuối cùng của Đa-vít: Đa-vít, con trai của Y-xai, phán; người đàn ông được đặt cao trọng, Đấng được xức dầu của Đức Chúa Trời Giácốp, và người hát những bài ca ngọt ngào của Ít-ra-en, phán rằng:'),
(8656, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 2, 'OT', 'Đức Giê-hô-va phán qua tôi, và lời của Ngài ở trên lưỡi tôi.'),
(8657, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 3, 'OT', 'Đức Chúa Trời của Ít-ra-en phán: Đấng Tựa Nương của Ít-ra-en phán cùng tôi: Người cai trị loài người phải là người công chính, cai trị trong sự kính sợ Đức Chúa Trời.'),
(8658, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 4, 'OT', 'Và như ánh sáng buổi sáng, mặt trời mọc rạng rỡ, buổi sáng không mây; như cỏ non vươn lên từ đất dưới ánh sáng chói lọi sau cơn mưa.'),
(8659, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 5, 'OT', 'Dù nhà ta không phải như vậy với Đức Chúa Trời, nhưng Ngài đã lập với ta một giao ước đời đời, được sắp đặt mọi điều và được giữ vững; vì mọi sự cứu rỗi của ta và mọi điều ta mong ước, mặc dù Ngài không làm cho nó đâm rễ.'),
(8660, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 6, 'OT', 'Nhưng những kẻ gian ác đều như gai góc bị quăng bỏ; bởi chúng không thể bị tóm lấy bằng tay.'),
(8661, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 7, 'OT', 'Người nào đụng đến chúng sẽ bị sắt và cán giáo đâm, và sẽ bị thiêu đốt hoàn toàn trong lửa tại chỗ ấy.'),
(8662, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 8, 'OT', 'Đây là các tên các dũng sĩ thuộc về Đa-vít: Giô-sép-Ba-sê-bết người Tác-mô-ni, đứng đầu các quan trưởng; chính người ấy là A-đi-nô người Ếch-ni; người đã đánh giết tám trăm người trong một lần.'),
(8663, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 9, 'OT', 'Sau người ấy là Ê-lê-a-xa, con trai Đô-đô, con trai A-hô-chít, thuộc nhóm ba chiến sĩ dũng cảm cùng Đa-vít, khi họ thách thức người Phi-li-tin đang tụ tập tại đó để giao chiến, còn những người Y-sơ-ra-ên thì đã rút đi.'),
(8664, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 10, 'OT', 'Người ấy đứng dậy và đánh người Phi-li-tin cho đến khi tay người mệt lả, và tay người dính chặt vào gươm; Đức Giê-hô-va thực hiện một chiến thắng lớn trong ngày đó; và dân chúng quay lại theo người chỉ để cướp chiến lợi phẩm.'),
(8665, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 11, 'OT', 'Sau người ấy là Sam-ma, con trai của A-ghê, người Ha-ra-ri. Dân Phi-li-tin nhóm lại đông đảo tại một đám đất đầy đậu lăng; nhưng dân chúng chạy trốn khỏi người Phi-li-tin.'),
(8666, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 12, 'OT', 'Nhưng người ấy đứng giữa đám ruộng, cứu lấy nó, và đánh giết người Phi-li-tin; rồi Đức Giê-hô-va thực hiện một chiến thắng lớn.'),
(8667, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 13, 'OT', 'Ba mươi người trong nhóm ba mươi thủ lĩnh đã xuống, đến cùng Đa-vít trong mùa gặt tại hang A-đu-lam; và đạo quân của người Phi-li-tin đóng trại trong thung lũng Rê-pha-im.'),
(8668, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 14, 'OT', 'Bấy giờ Đa-vít đang ở trong pháo đài, và trại lính của người Phi-li-tin lúc ấy ở Bết-lê-hem.'),
(8669, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 15, 'OT', 'Đa-vít khao khát, rồi nói: "Ước gì có ai cho tôi uống nước từ giếng Bết-lê-hem, nước ở bên cạnh cổng thành!"'),
(8670, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 16, 'OT', 'Ba người dũng sĩ xông qua trại quân của người Phi-li-tin, múc nước từ giếng Bết-lê-hem nằm gần cổng thành, rồi khiêng lên mang đến cho Đa-vít; nhưng ông không chịu uống, mà đổ nước đó ra dâng cho Đức Giê-hô-va.'),
(8671, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 17, 'OT', 'Đức Giê-hô-va ôi, tuyệt đối không thể nào tôi làm điều nầy được! Nầy chẳng phải là huyết của những người liều mình bỏ mạng sao? Vì vậy, ông từ chối uống. Nầy là điều mà ba người anh hùng đã làm.'),
(8672, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 18, 'OT', 'Và A-bi-sai, anh của Giô-áp, con trai Xê-ru-ya, là người đứng đầu trong nhóm ba người. Chính ông đã vung ngọn giáo mình nghịch lại ba trăm người bị giết, và ông có danh tiếng trong nhóm ba người.'),
(8673, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 19, 'OT', 'Ông há chẳng phải là người nổi bật hơn ba người kia sao? Vì vậy, ông được chỉ huy họ; tuy nhiên, ông không đạt đến cấp bậc của ba người đầu.'),
(8674, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 20, 'OT', 'Bê-nai-a, con trai của Giê-hô-ia-đa, con trai của một người đàn ông dũng cảm từ Ca-bê-xen, là người đã thực hiện nhiều việc anh hùng; chính người đó đã giết hai người hùng dũng như sư tử ở Mô-áp, và cũng đã xuống hố giết một con sư tử giữa lúc tuyết rơi.'),
(8675, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 21, 'OT', 'Người ấy đã đánh một người Ai Cập, thân hình cao lớn; trong tay người Ai Cập có một ngọn giáo, còn người đó thì đi xuống gặp hắn với một cây gậy, đoạt ngọn giáo khỏi tay người Ai Cập và dùng chính ngọn giáo của hắn để giết hắn.'),
(8676, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 22, 'OT', 'Bản-na-ia, con trai của Giê-hô-i-đa, đã làm những điều ấy, và người có danh tiếng trong nhóm ba người dũng sĩ.'),
(8677, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 23, 'OT', 'Được tôn trọng hơn nhóm Ba Mươi, nhưng không đạt đến nhóm Ba người đầu. Đa-vít đặt ông làm sĩ quan chỉ huy đội vệ binh của mình.'),
(8678, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 24, 'OT', 'Ách-sa-ên, anh của Giô-áp, là một trong nhóm ba mươi; Ê-lha-nan, con trai của Đô-đô, người Bết-lê-hem,'),
(8679, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 25, 'OT', 'Sát-ma người Ha-rô-đi, Ê-li-ka người Ha-rô-đi.'),
(8680, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 26, 'OT', 'Hê-lết người Pa-lít, I-ra con trai của Ích-xết người Tê-ko.'),
(8681, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 27, 'OT', 'A-bi-ê-xe người A-ne-thốt, Mê-bun-nai người Hút-sa-thít.'),
(8682, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 28, 'OT', 'Xa-lô-mon người A-hô-hít, Ma-ha-rai người Nê-tô-pha-thít.'),
(8683, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 29, 'OT', 'Hê-lép, con trai của Ba-a-nah, người Nê-tô-pha-thi; Ít-tai, con trai của Ri-bai, từ Ghíp-tha, thuộc con cháu Bên-gia-min.'),
(8684, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 30, 'OT', 'Bê-nai-a người Pi-ra-thôn, Hít-tai người các khe nước Ga-ách.'),
(8685, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 31, 'OT', 'Abi-albon người Arbathite, Azmaveth người Barhumite,'),
(8686, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 32, 'OT', 'Ê-li-ách-ba người Sa-an-bô-nít, con cháu của Gia-xen, Giô-na-than.'),
(8687, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 33, 'OT', 'Sam-ma người Ha-ra-rit, A-hi-am con trai của Sa-rát người Ha-ra-rit,'),
(8688, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 34, 'OT', 'Eliphelet con của Ahasbai, con của người Maachat; Eliam con của A-hi-thô-phên người Ghilon.'),
(8689, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 35, 'OT', 'Hết-rai người Ca-rơ-mên, Pa-a-rai người Ác-bi.'),
(8690, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 36, 'OT', 'I-ganh, con trai của Na-than, người Xô-ba; Ba-ni người Ga-đi.'),
(8691, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 37, 'OT', 'Xê-léc người Am-môn, Na-ha-ri người Bê-rốt, người mang khí giới cho Giô-áp con trai Xê-ru-gia,'),
(8692, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 38, 'OT', 'I-ra, người Y-thơ-ri; Ga-rép, người Y-thơ-ri.'),
(8693, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 23, 39, 'OT', 'U-ri-a người Hê-th; tất cả ba mươi bảy người.'),
(8694, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 24, 1, 'OT', 'Đức Giê-hô-va lại nổi giận cùng Y-sơ-ra-ên, và Ngài xúi giục Đa-vít nghịch cùng họ, bảo: "Hãy đi, đếm dân Y-sơ-ra-ên và dân Giu-đa."'),
(8695, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 24, 2, 'OT', 'Vua nói với Giô-áp, viên tướng chỉ huy quân đội đi cùng vua: "Hãy đi khắp các chi phái của Y-sơ-ra-ên, từ Đan cho đến Bê-e-Sê-ba, kiểm tra dân số, để ta biết số lượng dân chúng."'),
(8696, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 24, 3, 'OT', 'Giô-áp nói với vua: "Nguyện Giê-hô-va Đức Chúa Trời của ngài thêm dân số gấp trăm lần vào dân sự, hễ bao nhiêu đi nữa, và mắt chúa tôi là vua sẽ thấy điều đó. Nhưng tại sao chúa tôi là vua lại ưa thích điều nầy?"'),
(8697, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 24, 4, 'OT', 'Lời vua quyết liệt đối với Giô-áp và các quan chỉ huy quân đội; và Giô-áp cùng các quan chỉ huy quân đội ra đi từ trước mặt vua để điểm danh dân sự của Ít-ra-en.'),
(8698, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 24, 5, 'OT', 'Họ qua sông Giô-đanh, đóng trại tại A-rô-e, bên phải thành phố nằm giữa thung lũng Gát, và hướng về Gia-xe.'),
(8699, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 24, 6, 'OT', 'Họ đến vùng đất Ga-la-át, rồi đến đất Tahtim-hodshi; họ tiếp tục đến Dan-jaan, và vòng quanh đến Si-đôn.'),
(8700, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 24, 7, 'OT', 'Họ đến pháo đài Ty-rơ, và đến mọi thành của người Hê-vi và người Ca-na-an; rồi họ đi ra vùng Nam Giu-đa, đến Bê-e-Sê-ba.'),
(8701, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 24, 8, 'OT', 'Họ đi khắp đất, rồi trở về Giê-ru-sa-lem sau chín tháng và hai mươi ngày.'),
(8702, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 24, 9, 'OT', 'Giô-áp dâng số người được kiểm tra cho vua; và dân Y-sơ-ra-ên có tám trăm ngàn người trai chiến đấu, rút gươm ra được; còn người Giu-đa là năm trăm ngàn người.'),
(8703, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 24, 10, 'OT', 'Lòng Đa-vít cắn rứt mình sau khi ông điểm dân số. Đa-vít nói với Đức Giê-hô-va: "Tôi đã phạm tội rất nặng trong điều tôi đã làm. Bây giờ, xin Đức Giê-hô-va làm ơn gỡ bỏ tội lỗi của đầy tớ Ngài, vì tôi đã hành động cách rất dại dột."'),
(8704, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 24, 11, 'OT', 'Sáng hôm ấy, khi Đa-vít chỗi dậy, thì lời của Đức Giê-hô-va phán cùng Gát, nhà tiên tri, người thấy của Đa-vít, rằng:'),
(8705, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 24, 12, 'OT', 'Hãy đi và nói với Đa-vít rằng: Đức Giê-hô-va phán như vầy: Ta đang để cho ngươi ba điều; hãy chọn một điều trong các điều đó, để Ta làm cho ngươi.'),
(8706, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 24, 13, 'OT', 'Gát đến cùng Đa-vít và thuật lại cho ông, rồi nói: "Ông muốn chọn điều gì? Bảy năm đói kém trong đất nước ông, hay ba tháng chạy trốn khỏi kẻ thù đang đuổi theo ông, hay ba ngày ôn dịch trong đất nước ông? Bây giờ hãy suy xét và xem tôi phải trả lời thế nào với Đấng đã sai tôi đến."'),
(8707, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 24, 14, 'OT', 'Đa-vít nói với Gát: "Tôi đang gặp khốn khổ rất lớn. Xin hãy để tôi sa vào tay Đức Giê-hô-va, vì những lòng thương xót của Ngài rất lớn; nhưng chớ để tôi sa vào tay loài người."'),
(8708, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 24, 15, 'OT', 'Đức Giê-hô-va giáng một cơn dịch trên Ít-ra-en từ sáng sớm cho đến giờ đã định; và từ Đan cho đến Bê-er-Sê-ba, bảy mươi ngàn người trong dân chúng đã chết.'),
(8709, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 24, 16, 'OT', 'Thiên sứ đưa tay ra trên Giê-ru-sa-lem để hủy diệt thành, nhưng Đức Giê-hô-va đổi ý về điều dữ ấy, bèn nói với thiên sứ đang hủy diệt dân chúng: "Đủ rồi, bây giờ hãy rút tay lại." Bấy giờ thiên sứ của Đức Giê-hô-va đang ở nơi sân đập lúa của A-ru-nah, người Giê-bu-sít.'),
(8710, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 24, 17, 'OT', 'Đa-vít nói với Đức Giê-hô-va khi thấy thiên sứ đang đánh dân sự, và nói: "Nầy, tôi đã phạm tội, tôi đã làm điều ác; nhưng những chiên nầy, chúng đã làm gì? Xin tay Ngài, xin hãy chống nghịch tôi và nhà của cha tôi."'),
(8711, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 24, 18, 'OT', 'Trong ngày ấy, Gad đến cùng Đa-vít và nói với ông: "Hãy đi lên, xây một bàn thờ cho Đức Giê-hô-va tại sân đập lúa của A-rau-na người Giê-bu-sít."'),
(8712, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 24, 19, 'OT', 'Đa-vít đi lên theo lời chỉ bảo của Gát, như Đức Giê-hô-va đã truyền dạy.'),
(8713, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 24, 20, 'OT', 'A-ra-va nhìn thấy vua và các tôi tớ người đang đi về phía mình, bèn đi ra và cúi mặt xuống đất trước mặt vua.'),
(8714, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 24, 21, 'OT', 'A-ra-un nói: "Tại sao chúa tôi là vua lại đến cùng tôi là đầy tớ của ngài?" Đa-vít đáp: "Để mua sân đập lúa của ngươi, xây một bàn thờ cho Đức Giê-hô-va, hầu cho cơn dịch được dứt khỏi dân chúng."'),
(8715, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 24, 22, 'OT', 'A-rau-na nói với Đa-vít: "Xin chúa tôi là vua hãy nhận lấy và dâng lên điều gì tốt lành trước mặt ngài. Này, bò thì có để làm của lễ thiêu, còn cái cối xay và các đồ dùng của bò thì dùng làm củi."'),
(8716, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 24, 23, 'OT', 'Vua A-ra-un-na dâng tất cả những điều đó cho vua Đa-vít; và A-ra-un-na nói với vua rằng: "Cầu xin Đức Giê-hô-va Đức Chúa Trời của ngài chấp nhận ngài."'),
(8717, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 24, 24, 'OT', 'Vua nói với A-rau-na: "Không, ta nhất định phải mua của ngươi với giá cả, và ta sẽ không dâng của lễ thiêu cho Đức Giê-hô-va Đức Chúa Trời ta những gì không tốn kém cho ta." Vậy vua Đa-vít mua sân đập lúa và các con bò với năm mươi sê-ken bạc.'),
(8718, 10, 'GOI_vi', 'GOI_vi', 'vi', '2SA', 24, 25, 'OT', 'Đa-vít xây dựng tại đó một bàn thờ cho Đức Giê-hô-va, dâng các lễ thiêu và các lễ thù ân; rồi Đức Giê-hô-va nhậm lời cầu xin cho đất, và cơn dịch hạch dừng lại không còn hành hại Ít-ra-en nữa.'),
(8719, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 1, 'OT', 'Vua Đa-vít đã già, tuổi cao niên; người ta đắp chăn cho ông, nhưng ông vẫn không thấy ấm.'),
(8720, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 2, 'OT', 'Các tôi tớ của vua nói với vua: "Xin hãy tìm cho đức vua một người gái trẻ, còn trinh, để nàng hầu trước mặt đức vua, chăm sóc vua, và nằm trong lòng vua, hầu cho đức vua được ấm."'),
(8721, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 3, 'OT', 'Họ tìm một gái trẻ đẹp khắp các vùng biên giới của Y-sơ-ra-ên, và tìm được Áp-i-sa-g, người Xu-nam, rồi đem nàng đến cho vua.'),
(8722, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 4, 'OT', 'Cô gái rất xinh đẹp, và cô chăm sóc nhà vua, phục vụ người; nhưng nhà vua không ăn ở với cô.'),
(8723, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 5, 'OT', 'A-đô-ni-gia, con trai của Ha-ghít, tự nâng mình lên mà nói: "Ta sẽ làm vua"; và người ấy sắm sửa cho mình xe chiến và kỵ mã, cùng năm mươi người chạy trước mặt mình.'),
(8724, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 6, 'OT', 'Và cha của cậu đã không trách cậu trong suốt đời cậu, không nói: "Tại sao ngươi làm điều đó?" Cậu cũng rất đẹp trai, và mẹ cậu sinh cậu sau Áp-sa-lôm.'),
(8725, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 7, 'OT', 'Và các lời của ông ta cùng với Giô-áp, con trai của Xê-ru-i, và với A-bi-a-tha thầy tế lễ; họ bèn giúp đỡ theo phe A-đô-ni-gia.'),
(8726, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 8, 'OT', 'Nhưng thầy tế lễ Xa-đốc, Bê-nai-a con trai của Giê-hô-gia-đa, đấng tiên tri Na-than, Si-mê-i, Rei, và những người dũng sĩ thuộc về Đa-vít, thì không theo A-đô-ni-gia.'),
(8727, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 9, 'OT', 'A-đô-ni-gia giết chiên, bò và súc vật mập tại tảng đá Xô-hê-lết, gần bên suối Ên Rô-gên, rồi mời tất cả anh em mình, các con trai của vua, và mọi người của Giu-đa, các tôi tớ của vua.'),
(8728, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 10, 'OT', 'Nhưng không gọi đến nhà tiên tri Na-than, và Benaiah, và các dũng sĩ, và Sa-lô-môn, người anh em của ông.'),
(8729, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 11, 'OT', 'Na-than nói với Bát-sê-ba, mẹ của Sa-lô-môn, rằng: "Chẳng lẽ bà không nghe rằng A-đô-ni-gia, con trai của Ha-ghít, đã lên ngôi vua, trong khi chủ chúng ta là Đa-vít chẳng hay biết gì?"'),
(8730, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 12, 'OT', 'Bây giờ, hãy đi, ta sẽ cho con một lời khuyên, để con cứu mạng sống của con và mạng sống của Sô-lô-môn, con trai con.'),
(8731, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 13, 'OT', 'Hãy đi vào cùng vua Đa-vít và nói với người: "Thưa đức vua, chẳng phải chính ngài đã chỉ về tôi tớ ngài mà thề rằng: ''Sa-lô-môn, con trai ngài, sẽ trị vì sau tôi, và nó sẽ ngồi trên ngôi tôi'' sao? Vậy tại sao A-đô-ni-gia lại đang trị vì?"'),
(8732, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 14, 'OT', 'Này, khi cô còn đang nói chuyện với nhà vua tại đó, tôi sẽ theo sau cô vào và xác nhận những lời của cô.'),
(8733, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 15, 'OT', 'Bà Tạt-sê-ba vào trong phòng gặp vua; vua đã rất già; và A-bi-sa-đa người Xu-nam phục vụ vua.'),
(8734, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 16, 'OT', 'Bàt-xe-ba cúi đầu và sấp mình xuống trước mặt vua. Vua nói: "Bà muốn điều gì?"'),
(8735, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 17, 'OT', 'Bà nói với ông: "Thưa chúa tôi, chính ngài đã chỉ Đức Giê-hô-va Đức Chúa Trời của ngài mà thề cùng tôi tớ ngài rằng: Chắc chắn Sa-lô-môn, con trai ngài, sẽ trị vì sau tôi, và nó sẽ ngồi trên ngôi tôi."'),
(8736, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 18, 'OT', 'Và giờ đây, này, A-đô-ni-gia đã làm vua; và ngay bây giờ, thưa chủ tôi là đức vua, ngài chẳng hay biết điều đó.'),
(8737, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 19, 'OT', 'Người đã giết bò đực, bò mập và chiên rất nhiều, và đã mời tất cả các con trai của vua, cùng với A-bi-a-tha thầy tế lễ, và Giô-áp chỉ huy quân đội; nhưng Sa-lô-môn, đầy tớ của ngài, thì người không mời.'),
(8738, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 20, 'OT', 'Và bây giờ, thưa đức vua, hỡi chủ của tôi, mắt của toàn thể Y-sơ-ra-ên đều đổ về ngài, để ngài chỉ cho họ ai sẽ ngồi trên ngôi vua, là ngôi của chủ tôi là đức vua, sau khi ngài qua đời.'),
(8739, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 21, 'OT', 'Và sẽ xảy ra khi chủ nhân ta là vua nằm ngủ cùng các tổ phụ của người, thì tôi và con trai ta là Sô-lô-môn sẽ bị coi là kẻ có tội.'),
(8740, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 22, 'OT', 'Này, khi bà ấy còn đang nói chuyện với vua, thì Nátan, nhà tiên tri, cũng vào đó.'),
(8741, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 23, 'OT', 'Họ trình với vua rằng: "Này, Na-than, nhà tiên tri." Khi ông vào đến trước mặt vua, ông cúi lạy vua, mặt sát đất.'),
(8742, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 24, 'OT', 'Vua tôi, chúa tôi, ngài đã nói: "A-đô-ni-gia sẽ trị vì sau tôi, và ông ấy sẽ ngồi trên ngôi của tôi" sao?'),
(8743, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 25, 'OT', 'Vì hôm nay người đã đi xuống, giết bò đực, chiên béo và chiên làm của lễ rất nhiều, mời tất cả các con trai của vua, các quan chỉ huy quân đội và thầy tế lễ A-bi-a-tha; và kìa, họ đang ăn uống trước mặt người, và nói: "Nguyện vua A-đô-ni-gia sống mãi!"'),
(8744, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 26, 'OT', 'Nhưng tôi là tôi tớ ngươi, và Xa-đốc thầy tế lễ, và Bê-nai-a con trai Giô-gia-đa, và Sa-lô-môn tôi tớ ngươi, thì người ta không gọi.'),
(8745, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 27, 'OT', 'Nếu điều này do chính chủ tôi là vua quyết định, tại sao ngài không cho các đầy tớ của ngài biết ai sẽ ngồi trên ngôi vua, chủ tôi, sau khi ngài qua đời?'),
(8746, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 28, 'OT', 'Vua Đa-vít đáp và nói: "Hãy gọi cho ta Bát-sê-ba." Bà đến trước mặt vua và đứng trước mặt vua.'),
(8747, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 29, 'OT', 'Vua thề và nói: Đức Giê-hô-va hằng sống, Đấng đã cứu mạng sống tôi khỏi mọi điều nguy khốn,'),
(8748, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 30, 'OT', 'Ngay như Ta đã chỉ Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên mà thề cùng ngươi rằng: Chắc chắn Sa-lô-môn, con trai ngươi, sẽ trị vì sau Ta và ngồi trên ngôi Ta thay Ta; ngay hôm nay Ta sẽ làm đúng như vậy.'),
(8749, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 31, 'OT', 'Baths-sheba cúi mặt xuống đất, lạy vua và thưa: Nguyện chúa tôi là vua Đa-vít được sống đời đời.'),
(8750, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 32, 'OT', 'Vua Đa-vít nói: "Hãy gọi cho ta Xa-đốc thầy tế lễ, Na-than nhà tiên tri, và Bê-na-gia, con trai của Giê-hô-gia-đa." Họ bèn đến cùng trước mặt vua.'),
(8751, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 33, 'OT', 'Vua bảo họ: "Hãy đem theo các đầy tớ của chủ các ngươi, và cho Sa-lô-môn, con trai ta, cỡi lên con lừa cái của ta, rồi đưa nó xuống Ghíchôn."'),
(8752, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 34, 'OT', 'Và tại đó, thầy tế lễ Xa-đốc và nhà tiên tri Na-than sẽ xức dầu cho người làm vua trên Ít-ra-en; các ngươi hãy thổi kèn và tuyên bố: "Cầu Đức Giê-hô-va phù hộ vua Sa-lô-môn!"'),
(8753, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 35, 'OT', 'Rồi các ngươi sẽ đi lên theo sau người, để người ấy đến ngồi trên ngôi ta; người ấy sẽ làm vua thay ta. Ta đã chỉ định người ấy làm lãnh tụ cai trị trên Ít-ra-en và trên Giu-đa.'),
(8754, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 36, 'OT', 'Bấy giờ Bê-nai-a, con trai của Giô-ya-đa, thưa cùng vua rằng: "Amen! Nguyện Đức Giê-hô-va, Đức Chúa Trời của chúa tôi là vua, cũng phán như vậy!"'),
(8755, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 37, 'OT', 'Như Đức Giê-hô-va đã ở cùng chủ nhân ta là vua, xin Ngài cũng ở cùng với Sa-lô-môn, và làm cho ngôi của người lớn hơn ngôi của chủ nhân ta là vua Đa-vít.'),
(8756, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 38, 'OT', 'Xa-đốc thầy tế lễ, Na-than nhà tiên tri, Bên-nai-a con trai của Giê-hô-ia-đa, các Kê-rê-thi và các Phê-lê-thi đi xuống, đặt Sa-lô-môn lên con lừa của vua Đa-vít, và dẫn người đến Ghinh-ôn.'),
(8757, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 39, 'OT', 'Xa-đốc thầy tế lễ lấy sừng dầu từ trong nơi thánh và xức cho Sa-lô-môn. Rồi họ thổi kèn, và toàn thể dân chúng reo lên: "Cầu Đức Giê-hô-va giữ cho vua Sa-lô-môn sống mãi!"'),
(8758, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 40, 'OT', 'Toàn dân đi lên theo sau ông, và dân chúng thổi sáo, reo vui trong niềm hân hoan lớn lao, khiến đất nứt ra bởi tiếng reo của họ.'),
(8759, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 41, 'OT', 'A-đô-ni-gia và tất cả những người được mời đi ăn với ông nghe thấy điều đó khi họ vừa ăn xong; và Giô-áp nghe tiếng tù và, bèn nói: "Sao lại có tiếng ồn ào lộn xộn trong thành?"'),
(8760, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 42, 'OT', 'Đang lúc ông nói, thì nầy, Giô-na-than, con trai thầy tế lễ A-bi-a-tha, đã đến. Và A-đô-ni-gia nói với ông: "Hãy vào, vì ông là người dũng cảm và mang tin tốt lành."'),
(8761, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 43, 'OT', 'Yô-na-than đáp và nói với A-đô-ni-gia: "Nhưng đức vua Đa-vít, chủ chúng ta, đã lập Sa-lô-môn làm vua."'),
(8762, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 44, 'OT', 'Vua đã sai đi cùng ông với Xa-đốc thầy tế lễ, Na-than nhà tiên tri, Bê-na-gia con trai Giô-gia-đa, và các Kê-rê-thi, các Phi-lê-thi; và họ đã đỡ ông cỡi con lừa của vua.'),
(8763, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 45, 'OT', 'Đức thầy tế lễ Xa-đốc và nhà tiên tri Na-than đã xức dầu cho người làm vua tại Ghinhôn; rồi họ đi lên từ đó trong niềm vui mừng, khiến cả thành phố vang dội lên; đó chính là tiếng mà các ngươi đã nghe.'),
(8764, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 46, 'OT', 'Và thật, Sa-lô-môn đã ngồi trên ngôi vương quyền.'),
(8765, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 47, 'OT', 'Các tôi tớ của vua cũng đến chúc phước cho chúa chúng ta là vua Đa-vít, nói rằng: Đức Chúa Trời của ngài khiến danh của Sa-lô-môn tốt lành hơn danh ngài, và làm cho ngôi của người lớn hơn ngôi ngài. Rồi vua cúi mình trên giường.'),
(8766, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 48, 'OT', 'Và vua cũng nói thêm: Đáng chúc tụng Đấng Giê-hô-va Đức Chúa Trời của Ít-ra-en, Đấng đã ban cho một người ngồi trên ngôi ta hôm nay, chính mắt ta được thấy điều đó.'),
(8767, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 49, 'OT', 'Mọi người được mời cùng với A-đô-ni-gia đều run sợ, đứng dậy và mỗi người đi theo đường lối riêng của mình.'),
(8768, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 50, 'OT', 'A-đô-ni-gia sợ vì cớ Sô-lô-môn, bèn chổi dậy, đi đến và nắm chặt các sừng của bàn thờ.'),
(8769, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 51, 'OT', 'Và người ta báo cho Sa-lô-môn rằng: "Nầy, A-đô-ni-gia sợ vua Sa-lô-môn; kìa, người đã nắm lấy các sừng của bàn thờ và nói: ''Nguyện vua Sa-lô-môn hôm nay thề với tôi rằng sẽ không giết kẻ tôi tớ người bằng gươm.''"'),
(8770, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 52, 'OT', 'Vua Sa-lô-môn đáp: "Nếu y chứng tỏ mình là người trung nghĩa, thì không một sợi tóc nào của y sẽ rụng xuống đất; nhưng nếu làm điều ác, thì sẽ chết."'),
(8771, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 1, 53, 'OT', 'Vua Sa-lô-môn sai người, và họ đưa hắn xuống khỏi bàn thờ. Hắn đến, rồi cúi lạy vua Sa-lô-môn. Vua Sa-lô-môn nói với hắn: "Hãy đi về nhà ngươi."'),
(8772, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 1, 'OT', 'Đã gần đến kỳ Ða-vít phải chết, người căn dặn Sa-lô-môn, con trai mình, rằng:'),
(8773, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 2, 'OT', 'Ta sắp đi theo con đường mà mọi người trên đất đều phải đi; vậy hãy vững mạnh và sống như một người đàn ông.'),
(8774, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 3, 'OT', 'Hãy giữ mạng lịnh của Đức Giê-hô-va Đức Chúa Trời ngươi, để đi trong các đường lối Ngài, giữ các luật lệ, các điều răn, các mạng lịnh và các lời chứng của Ngài như đã chép trong luật pháp của Môi-se, hầu cho ngươi được thạnh vượng trong mọi việc ngươi làm và trong mọi nơi ngươi trở mình đến.'),
(8775, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 4, 'OT', 'Đức Giê-hô-va sẽ thực hiện lời Ngài đã phán về tôi, rằng: "Nếu các con trai ngươi chăm chỉ giữ đường lối mình, đi trước mặt ta thật lòng, hết lòng và hết lòng trọn ý, thì sẽ không hề thiếu một người nào từ dòng dõi ngươi ngồi trên ngôi nước của Ít-ra-en."'),
(8776, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 5, 'OT', 'Ngươi cũng biết điều mà Giô-áp, con trai của Xê-ru-ya, đã làm cho ta, và điều hắn đã làm cho hai viên chỉ huy quân đội của Ít-ra-en, là Áp-ne, con trai của Nê, và A-ma-xa, con trai của Giết-xe, mà hắn đã giết; hắn đã đổ máu chiến tranh vào lúc hòa bình, và mang máu chiến tranh ấy vào đai lưng mình nơi hông, và vào giày mình nơi chân.'),
(8777, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 6, 'OT', 'Vì vậy, hãy hành động theo sự khôn ngoan của ngươi, và đừng để đầu bạc của người ấy xuống âm phủ bình an.'),
(8778, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 7, 'OT', 'Nhưng hãy làm ơn lành cho các con trai của Bar-zi-lai, người Gi-lean, và để họ ăn tại bàn ngươi; vì chính họ đã đến cùng ta khi ta trốn tránh vì cớ Áp-sa-lôm, anh ngươi.'),
(8779, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 8, 'OT', 'Này, Si-mê-i con trai của Gê-ra, người Bên-gia-min ở Ba-hu-rim, hiện đang ở với ngươi; người ấy đã nguyền rủa ta một lời nguyền nặng nề trong ngày ta đi về Ma-ha-na-im; nhưng người ấy đã xuống gặp ta bên sông Giô-đanh, và ta đã chỉ Đức Giê-hô-va mà thề rằng: Ta sẽ không giết ngươi bằng gươm.'),
(8780, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 9, 'OT', 'Bây giờ, đừng để người ấy vô tội, vì ngươi là người khôn ngoan, và biết điều mình phải làm cho người ấy; hãy làm cho đầu bạc của người ấy xuống âm phủ với máu.'),
(8781, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 10, 'OT', 'Đa-vít nằm ngủ cùng với tổ tiên mình và được chôn trong thành của Đa-vít.'),
(8782, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 11, 'OT', 'Số ngày Đa-vít trị vì trên Ít-ra-en là bốn mươi năm: người trị vì bảy năm tại Hếp-rôn, và trị vì ba mươi ba năm tại Giê-ru-sa-lem.'),
(8783, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 12, 'OT', 'Và Sa-lô-môn ngồi trên ngôi vua của Đa-vít, cha mình; và vương quốc người được củng cố rất vững chắc.'),
(8784, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 13, 'OT', 'Và A-đô-ni-gia, con trai của Ha-ghít, đến cùng bà Bát-sê-ba, mẹ của Sa-lô-môn. Bà nói: "Ngươi đến có điều lành chăng?" Và người đáp: "Có điều lành."'),
(8785, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 14, 'OT', 'Người nói thêm: "Tôi có điều muốn thưa cùng bà." Bà nói: "Xin cứ nói."'),
(8786, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 15, 'OT', 'Ông biết rằng triều đại thuộc về tôi, và toàn thể Y-sơ-ra-ên đã đặt niềm trông cậy nơi tôi để tôi trị vì; nhưng triều đại đã chuyển sang anh tôi, vì điều đó do từ Đức Giê-hô-va.'),
(8787, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 16, 'OT', 'Và bây giờ, tôi xin ngươi một điều, xin đừng từ chối tôi. Người ấy nói với bà: Xin hãy nói đi.'),
(8788, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 17, 'OT', 'Hãy nói, nhân danh ta, cùng vua Sa-lô-môn, vì người sẽ không từ chối ngươi, xin người cho ta A-bi-sa-g người Su-nem làm vợ.'),
(8789, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 18, 'OT', 'Bathsêba nói: Tốt lắm, chính tôi sẽ nói chuyện của ngươi với vua.'),
(8790, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 19, 'OT', 'Bà Tát-bát liền đến gặp vua Sa-lô-môn để nói với người về A-đô-ni-gia. Vua đứng dậy đón bà, cúi mình trước bà, rồi ngồi trên ngôi mình; vua cũng cho đặt một cái ghế cho mẹ vua, và bà ngồi bên phải người.'),
(8791, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 20, 'OT', 'Bà ấy nói: "Tôi xin một điều nhỏ; xin đừng từ chối tôi." Và vua nói với bà: "Hãy xin đi, thưa mẹ tôi, vì tôi sẽ không từ chối bà."'),
(8792, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 21, 'OT', 'Bà ấy nói: Xin hãy giao Áp-sa-gát người Xu-nam-mít cho A-đô-ni-gia, anh ngươi, làm vợ.'),
(8793, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 22, 'OT', 'Vua Sa-lô-môn đáp và nói với mẹ mình: "Sao mẹ lại xin nàng Áp-sa-ga người Su-nem cho A-đô-ni-gia? Hãy xin luôn cả vương quốc cho người ấy nữa, vì người ấy là anh cả của con, và điều đó cũng thuộc về người, cùng với Áp-gia thầy tế lễ và Giô-áp con trai của Xê-ru-gia."'),
(8794, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 23, 'OT', 'Vua Sa-lô-môn chỉ Đức Giê-hô-va mà thề, rằng: "Điều nầy Đức Chúa Trời làm cho tôi, và còn làm thêm nữa, vì A-đô-ni-gia đã nói lời nầy nghịch cùng chính mạng sống mình."'),
(8795, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 24, 'OT', 'Vậy nên, nhân danh Đức Giê-hô-va hằng sống, Đấng đã lập ta và đặt ta ngồi trên ngôi của Đa-vít, cha ta, và Đấng đã làm cho ta một nhà như lời Ngài đã hứa, ngày nay A-đô-ni-gia phải bị xử tử.'),
(8796, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 25, 'OT', 'Vua Sa-lô-môn sai Bê-nai-a, con trai của Giê-hô-i-đa, đi thi hành; người ấy ra tay xử tử hắn.'),
(8797, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 26, 'OT', 'Vua nói với thầy tế lễ A-bi-a-tha: "Hãy đi về A-na-thốt, đến ruộng đất của ngươi, vì ngươi đáng chết; nhưng hôm nay ta sẽ không giết ngươi, vì ngươi đã mang hòm giao ước của Đức Giê-hô-va trước mặt Đa-vít cha ta, và ngươi đã cùng chịu khốn khổ với cha ta trong mọi sự người ấy phải chịu."'),
(8798, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 27, 'OT', 'Vua Sa-lô-môn đuổi Áp-bi-át-ta khỏi chức thầy tế lễ cho Đức Giê-hô-va, để ứng nghiệm lời Đức Giê-hô-va đã phán về nhà Ê-li tại Si-lô.'),
(8799, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 28, 'OT', 'Mọi tin tức này đến với Yo-áp; bởi vì Yo-áp đã nghiêng theo A-đô-ni-gia, nhưng không nghiêng theo Áp-sa-lôm. Vậy Yo-áp chạy trốn đến trại của Đức Giê-hô-va và nắm chặt các sừng của bàn thờ.'),
(8800, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 29, 'OT', 'Vua Sô-lô-môn được báo rằng Giô-áp đã chạy đến trại của Đức Giê-hô-va và đang ở bên cạnh bàn thờ. Bấy giờ, Sô-lô-môn sai Bên-nai, con trai của Giê-hô-i-đa, đi và dặn rằng: "Hãy đi, xử tử hắn."'),
(8801, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 30, 'OT', 'Bấy giờ Bê-nai-a đi đến nơi thánh của Đức Giê-hô-va, nói với người rằng: "Vua truyền như vầy: Hãy ra đi." Nhưng người đáp: "Không, tôi sẽ chết tại đây." Bê-nai-a bèn trở về tâu lại cho vua biết, nói: "Jo-áp đã nói như thế nầy, và đã trả lời tôi như thế đó."'),
(8802, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 31, 'OT', 'Vua nói với người: "Hãy làm theo lời người ấy, hãy xông vào và chôn cất người đó, để ngươi dẹp khỏi ta và khỏi nhà cha ta huyết vô tội mà Giô-ab đã đổ ra."'),
(8803, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 32, 'OT', 'Đức Giê-hô-va sẽ khiến huyết của người đổ lại trên đầu chính mình, vì người đã đánh và giết hai người đàn ông công bình và tốt lành hơn mình bằng gươm, mà cha ta là Đa-vít không biết điều đó: Áp-ne, con trai Nê-er, tướng quân đạo binh Ít-ra-en, và A-ma-sa, con trai của Giê-thẹc, tướng quân đạo binh Giu-đa.'),
(8804, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 33, 'OT', 'Máu của họ sẽ đổ lại trên đầu Giô-áp và trên đầu dòng dõi nó đến mãi mãi; còn trên Đa-vít và trên dòng dõi người, trên nhà người và trên ngôi người, sẽ có sự bình an đời đời từ trước mặt Đức Giê-hô-va.'),
(8805, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 34, 'OT', 'Bấy giờ Bê-nai-a, con trai của Giô-ya-đa, lên đường, gặp hắn và giết hắn; rồi hắn được chôn trong nhà riêng của mình ở nơi hoang mạc.'),
(8806, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 35, 'OT', 'Vua đặt Bê-nai-a, con trai của Giô-ya-đa, thay ông làm tướng quân đội; và vua đặt thầy tế lễ Xa-đốc thay Abi-athar.'),
(8807, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 36, 'OT', 'Vua sai người điệu Si-mê-i đến, rồi bảo ông: "Hãy xây nhà mình tại Giê-ru-sa-lem, ở đó, và chớ ra khỏi đó đi bất cứ nơi nào."'),
(8808, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 37, 'OT', 'Ngày nào ngươi ra đi và qua suối Kidron, thì chắc chắn sẽ biết rằng ngươi phải chết; máu ngươi sẽ đổ trên đầu ngươi.'),
(8809, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 38, 'OT', 'Và Si-mê-i nói với vua: "Lời nói tốt lành; điều gì chủ tôi là vua đã nói, thì tôi là đầy tớ sẽ làm như vậy." Và Si-mê-i đã ở tại Giê-ru-sa-lem nhiều ngày.'),
(8810, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 39, 'OT', 'Sau ba năm, hai đầy tớ của Sê-mi trốn đến A-kích, con trai của Ma-a-ca, vua của Gát. Người ta báo cho Sê-mi rằng: "Này, các đầy tớ của ông đang ở Gát."'),
(8811, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 40, 'OT', 'Sau đó, Sê-mi đứng dậy, tra cương lừa mình và đi đến Gát, đến cùng A-khis để tìm các đầy tớ mình; rồi Sê-mi đi và dẫn các đầy tớ mình từ Gát về.'),
(8812, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 41, 'OT', 'Và người ta báo cho Sa-lô-môn rằng: Si-mê đã đi từ Giê-ru-sa-lem đến Ga-th, rồi lại trở về.'),
(8813, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 42, 'OT', 'Vua sai người gọi Si-mê-i và nói với người ấy: "Ta há chẳng đã khiến ngươi chỉ Đức Giê-hô-va mà thề, và cảnh cáo ngươi rằng: ''Ngươi phải biết chắc chắn rằng, trong ngày ngươi đi ra và đi bất cứ nơi nào, ngươi sẽ chắc chắn phải chết'' sao? Và ngươi đã nói với ta rằng: ''Lời ta nghe là tốt.''"'),
(8814, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 43, 'OT', 'Tại sao ngươi không giữ lời thề của Đức Giê-hô-va và điều răn mà ta đã truyền cho ngươi?'),
(8815, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 44, 'OT', 'Vua nói với Si-mê-i: "Ngươi biết rõ mọi điều ác mà lòng ngươi đã giấu kín, điều ngươi đã làm cho Đa-vít, cha ta; nên Đức Giê-hô-va sẽ khiến điều ác của ngươi đổ lại trên đầu ngươi."'),
(8816, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 45, 'OT', 'Vua Sa-lô-môn được phước, và ngai vàng của Đa-vít sẽ được lập vững chắc trước mặt Đức Giê-hô-va đến mãi mãi.'),
(8817, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 2, 46, 'OT', 'Vua truyền lệnh cho Bê-nai-a, con trai của Giô-ya-đa; người ấy ra đi, xông vào hắn và hắn chết. Vương quốc được củng cố dưới tay Sa-lô-môn.'),
(8818, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 3, 1, 'OT', 'Vua Sa-lô-môn kết thông gia với Pha-ra-ôn, vua nước Ai Cập; người lấy con gái của Pha-ra-ôn và đem nàng vào thành Đa-vít, cho đến khi người hoàn tất việc xây cất nhà mình, nhà của Đức Giê-hô-va, và vách thành Giê-ru-sa-lem bao quanh.'),
(8819, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 3, 2, 'OT', 'Dân chúng chỉ dâng tế lễ tại các nơi cao, vì cho đến những ngày ấy, chưa có nhà nào được xây cho danh Đức Giê-hô-va.'),
(8820, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 3, 3, 'OT', 'Vua Sa-lô-môn yêu mến Đức Giê-hô-va, đi theo các luật lệ của Đa-vít, cha mình; nhưng người vẫn dâng tế lễ và đốt hương trên các nơi cao.'),
(8821, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 3, 4, 'OT', 'Vua đi đến Ghi-bê-ôn để dâng tế lễ tại đó, vì đó là nơi cao lớn nhất; một ngàn của lễ thiêu, vua Sô-lô-môn dâng trên bàn thờ ấy.'),
(8822, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 3, 5, 'OT', 'Tại Ghi-bê-ôn, Đức Giê-hô-va hiện ra cùng Sa-lô-môn trong giấc mơ ban đêm; và Đức Chúa Trời phán: "Hãy xin điều ngươi muốn Ta ban cho."'),
(8823, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 3, 6, 'OT', 'Đa-vít, cha tôi, là tôi tớ của Ngài, thì Ngài đã làm ơn lớn cho người, y như người đã đi trước mặt Ngài trong chân lý, sự công chính và lòng ngay thẳng; và Ngài đã giữ ơn lớn nầy cho người, là đã ban cho người một người con ngồi trên ngôi người, như ngày nay vậy.'),
(8824, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 3, 7, 'OT', 'Bây giờ, lạy Đức Giê-hô-va Đức Chúa Trời tôi, Ngài đã lập tôi tớ Ngài làm vua thay cho Đa-vít, cha tôi; nhưng tôi là một đứa trẻ nhỏ, không biết ra vào.'),
(8825, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 3, 8, 'OT', 'Tôi tớ của Ngài đang ở giữa dân sự mà Ngài đã chọn, một dân đông đảo không thể đếm được, không thể tính được vì quá nhiều.'),
(8826, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 3, 9, 'OT', 'Xin hãy ban cho đầy tớ Ngài một lòng biết lắng nghe, để đoán xét dân Ngài và phân biệt giữa điều thiện và điều ác; vì ai có thể đoán xét dân lớn đông này của Ngài?'),
(8827, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 3, 10, 'OT', 'Lời ấy đẹp lòng Đức Giê-hô-va, vì Sa-lô-môn đã xin điều nầy.'),
(8828, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 3, 11, 'OT', 'Đức Chúa Trời phán cùng người rằng: "Bởi ngươi đã xin điều nầy, không xin sống lâu, cũng không xin của cải cho mình, không xin mạng kẻ thù, mà chỉ xin sự hiểu biết để phân xét công bình,'),
(8829, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 3, 12, 'OT', 'Này, Ta đã làm theo lời ngươi: này, Ta đã ban cho ngươi một lòng đầy sự khôn ngoan và thông sáng, đến nỗi trước ngươi không ai giống như ngươi, và sau ngươi cũng sẽ không ai nổi lên giống như ngươi.'),
(8830, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 3, 13, 'OT', 'Ta cũng ban cho ngươi điều mà ngươi không cầu xin, ấy là sự giàu có và danh dự, đến nỗi trong các vua, suốt cả ngày đời ngươi, sẽ không có ai sánh bằng ngươi.'),
(8831, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 3, 14, 'OT', 'Nếu ngươi đi theo các đường lối ta, giữ các luật lệ và mệnh lệnh ta như Đa-vít, cha ngươi, đã làm, thì ta sẽ kéo dài ngày sống của ngươi.'),
(8832, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 3, 15, 'OT', 'Vua Sa-lô-môn thức dậy, thì thấy rằng đó chỉ là một giấc mơ. Người đi đến Giê-ru-sa-lem, đứng trước hòm giao ước của Đức Giê-hô-va, dâng các lễ thiêu, thực hiện các lễ hòa bình, và làm một bữa tiệc cho tất cả các tôi tớ mình.'),
(8833, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 3, 16, 'OT', 'Bấy giờ có hai người đàn bà là phường điếm đến cùng vua, và đứng trước mặt người.'),
(8834, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 3, 17, 'OT', 'Thưa ngài, tôi và người phụ nữ này sống trong cùng một nhà; tôi đã sinh con trong nhà cùng với nàng.'),
(8835, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 3, 18, 'OT', 'Vào ngày thứ ba sau khi tôi sinh, người phụ nữ này cũng sinh; và chúng tôi ở cùng nhau, không có người ngoài nào với chúng tôi trong nhà, chỉ có hai chúng tôi mà thôi.'),
(8836, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 3, 19, 'OT', 'Con trai của người đàn bà nầy đã chết trong đêm, khi nàng nằm trên nó.'),
(8837, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 3, 20, 'OT', 'Đoạn đó chỗi dậy giữa đêm khuya, lấy đứa con tôi khỏi bên tôi khi tớ bà đang ngủ, rồi đặt nó vào lòng bà; còn con bà thì đã chết, bà đặt vào lòng tôi.'),
(8838, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 3, 21, 'OT', 'Tôi chỗi dậy lúc sáng sớm để cho con mình bú, thì thấy nó đã chết; tôi nhìn kỹ đứa trẻ lúc sáng sớm, thì kìa, đó không phải là con trai tôi mà tôi đã sinh ra.'),
(8839, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 3, 22, 'OT', 'Người đàn bà kia nói: "Không, con sống là con tôi, còn con chết là con bà." Nhưng người này lại nói: "Không, con chết là con bà, còn con sống là con tôi." Và họ tranh cãi trước mặt nhà vua.'),
(8840, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 3, 23, 'OT', 'Vua nói: "Người này nói: ''Con trai sống là con tôi, còn con trai chết là con bà''; còn người kia nói: ''Không phải vậy, con bà chết, còn con tôi sống''."'),
(8841, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 3, 24, 'OT', 'Vua nói: "Hãy mang gươm đến cho ta." Họ liền mang gươm đến trước mặt vua.'),
(8842, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 3, 25, 'OT', 'Vua nói: "Hãy chia đứa trẻ sống làm hai phần, rồi đưa một nửa cho người này, một nửa cho người kia."'),
(8843, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 3, 26, 'OT', 'Người phụ nữ có con sống liền nói với vua, vì lòng trắc ẩn của bà dấy lên thương con mình, rằng: "Tâu chúa, xin hãy trao đứa trẻ sống cho người, đừng giết nó." và cũng chính người ấy lại nói: "Đứa trẻ cũng không phải của tôi, cũng không phải của bà, hãy chia ra."'),
(8844, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 3, 27, 'OT', 'Vua trả lời và nói: "Hãy đưa đứa trẻ sống cho người đàn bà nầy, đừng giết nó; nàng là mẹ nó."'),
(8845, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 3, 28, 'OT', 'Toàn thể dân Ít-ra-en nghe biết về phán quyết mà vua đã xét xử, và họ kính sợ vua, vì họ thấy rằng sự khôn ngoan của Đức Chúa Trời ở trong người, để thực hiện công lý.'),
(8846, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 1, 'OT', 'Vua Sa-lô-môn trị vì trên toàn thể Y-sơ-ra-ên.'),
(8847, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 2, 'OT', 'Và đây là các quan trưởng thuộc về ông: A-xa-ria, con trai của Xa-đốc, thầy tế lễ.'),
(8848, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 3, 'OT', 'Ê-li-hô-rép và A-hi-a, các con trai của Si-sa, làm thư ký; Giê-hô-sa-phát, con trai của A-hi-lút, làm người ghi chép.'),
(8849, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 4, 'OT', 'Và Bê-nai-a, con trai của Giê-hô-i-đa, làm tướng quân đội; Xa-đốc và A-bi-a-tha làm thầy tế lễ.'),
(8850, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 5, 'OT', 'A-xa-ria, con trai của Na-than, quản lý các viên chức; còn Xa-bút, con trai của Na-than, làm thầy tế lễ và bạn thân của vua.'),
(8851, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 6, 'OT', 'A-hi-sa làm quản lý gia đình, và A-đô-ni-ram, con trai của Áp-đa, quản lý việc cống nạp.'),
(8852, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 7, 'OT', 'Vua Sa-lô-môn có mười hai viên quan cai trị khắp cả Ít-ra-en, lo cung cấp lương thực cho vua và gia đình vua; mỗi người lo một tháng trong năm.'),
(8853, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 8, 'OT', 'Và đây là tên của họ: con trai của Hur, ở trên núi Ép-ra-im.'),
(8854, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 9, 'OT', 'Con trai của Đê-ker, ở Ma-kát, ở Sa-an-bim, và Bết Sê-mết, và Ê-lôn Bết Ha-nan.'),
(8855, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 10, 'OT', 'Con trai của Hesed, ở Aruboth; người ấy có Sochoh và toàn thể đất đai của Hepher.'),
(8856, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 11, 'OT', 'Con trai của A-bi-na-đáp, cai quản toàn bộ vùng đất Đô; Ta-pha, con gái của vua Sa-lô-môn, làm vợ người.'),
(8857, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 12, 'OT', 'Ba-ana, con trai của A-hi-lút; [thuộc về ông] Ta-nách và Mê-gít-đô, và toàn thể Bết-sê-an, tức là cái ở gần Xác-ta-nah, ở dưới Giê-xơ-rê-ên, từ Bết-sê-an cho đến A-bên Mê-hô-lah, cho đến bên kia của Giốc-nê-am.'),
(8858, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 13, 'OT', 'Con trai của Ghê-be, ở Ra-mốt, trong đất Ga-la-át; thuộc về người là các thị trấn của Gia-ir, con trai của Ma-na-xe, là những nơi trong đất Ga-la-át; thuộc về người cũng là vùng A-rgôp, trong Ba-san, gồm sáu mươi thành lớn có vách thành và then cửa bằng đồng.'),
(8859, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 14, 'OT', 'A-hi-na-đáp, con trai của Ít-đô, ở Ma-ha-na-im.'),
(8860, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 15, 'OT', 'A-hi-ma-ách, con trai của Náp-ta-li, cũng cưới Bát-sé-mát, con gái của Sa-lô-môn, làm vợ.'),
(8861, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 16, 'OT', 'Baanah con trai của Hú-sai ở tại Asher và Aloth.'),
(8862, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 17, 'OT', 'Yehô-sa-phát, con trai của Pa-ru-ha, thuộc chi phái Y-xa-sa.'),
(8863, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 18, 'OT', 'Si-mê-i, con trai của Elah, thuộc chi phái Bên-gia-min.'),
(8864, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 19, 'OT', 'Gẹ-be, con trai của U-ri, ở đất Ghi-lê-át, đất của Si-hôn, vua dân A-mô-rị, và của Oùc, vua Ba-san; và người là viên chức duy nhất đặt tại đất ấy.'),
(8865, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 20, 'OT', 'Giô-đa và Ít-ra-en đông đảo như cát bên bờ biển về số lượng, ăn uống và vui vẻ.'),
(8866, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 21, 'OT', 'Vua Sa-lô-môn cai trị trên mọi nước từ sông Ơ-phơ-rát cho đến xứ Phi-li-tin và cho đến ranh giới Ai-cập; các nước ấy dâng lễ vật và phục vụ vua Sa-lô-môn trọn mọi ngày đời người.'),
(8867, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 22, 'OT', 'Bánh mì của vua Sô-lô-môn mỗi ngày là ba mươi kôr bột mịn và sáu mươi kôr bột thô.'),
(8868, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 23, 'OT', 'Mười con bò béo từ đồng cỏ, hai mươi con bò từ đồng cỏ, một trăm con chiên, ngoài ra còn có nai, linh dương, lợn rừng và gia cầm béo.'),
(8869, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 24, 'OT', 'Vì vua cai trị toàn bộ vùng bên kia sông, từ Thíp-xa cho đến A-xách, trên mọi vua của các vùng bên kia sông; và vua được hòa bình về mọi phía xung quanh mình.'),
(8870, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 25, 'OT', 'Giô-đa và Ít-ra-en sống yên ổn, mỗi người dưới gốc nho và dưới gốc vả của mình, từ Đan cho đến Bê-e-Sê-ba, suốt mọi ngày đời của Sa-lô-môn.'),
(8871, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 26, 'OT', 'Vua Sa-lô-môn có bốn mươi ngàn chuồng ngựa cho các xe chiến của ông, và mười hai ngàn ngựa kỵ sĩ.'),
(8872, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 27, 'OT', 'Các quan cung cấp thực phẩm cho vua Sa-lô-môn và cho mọi người đến bàn tiệc của vua Sa-lô-môn, mỗi người một tháng: họ không thiếu thứ gì.'),
(8873, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 28, 'OT', 'Lúa mạch và rơm cho ngựa và ngựa cái được mang đến nơi người ấy ở, mỗi người theo phần bổ nhiệm của mình.'),
(8874, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 29, 'OT', 'Đức Chúa Trời ban cho Sa-lô-môn sự khôn ngoan và sự hiểu biết rất lớn, cùng lòng rộng rãi như cát nơi bờ biển.'),
(8875, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 30, 'OT', 'Sự khôn ngoan của Sa-lô-môn vượt xa sự khôn ngoan của mọi người con đông phương và toàn thể sự khôn ngoan của Ai Cập.'),
(8876, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 31, 'OT', 'Ông thông minh hơn tất cả mọi người, hơn Ê-than người Ê-xơ-ra-hít, hơn Hê-man, Kha-lốc và Đạt-đa, các con trai của Ma-hôn; và danh tiếng ông lan rộng khắp các dân tộc xung quanh.'),
(8877, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 32, 'OT', 'Ông đã nói ba ngàn câu châm ngôn, và những bài ca của ông là một ngàn lẻ năm bài.'),
(8878, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 33, 'OT', 'Ông nói về các loài cây, từ cây bá hương ở Li-băng cho đến cây hy-xôp mọc ra từ vách đá; ông cũng nói về các loài vật, chim chóc, sinh vật bò trên mặt đất, và cá.'),
(8879, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 4, 34, 'OT', 'Dân của mọi nước đã đến để nghe sự khôn ngoan của Sa-lô-môn, từ tất cả các vua trên đất, là những người đã nghe danh sự khôn ngoan của ông.'),
(8880, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 5, 1, 'OT', 'Hi-ram, vua thành Típ, sai các đầy tớ mình đến cùng Sa-lô-môn; vì người đã nghe rằng họ đã xức dầu cho người làm vua thay cho cha người; bởi Hi-ram hằng yêu mến Đa-vít mọi ngày trọn đời.'),
(8881, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 5, 2, 'OT', 'Vua Sa-lô-môn sai người đến Hi-ram, nói rằng:'),
(8882, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 5, 3, 'OT', 'Ngươi biết rõ Đa-vít, cha ta, vì ông không thể xây nhà cho danh Đức Giê-hô-va Đức Chúa Trời của ông, do các cuộc chiến tranh vây quanh ông, cho đến khi Đức Giê-hô-va đặt chúng dưới bàn chân ông.'),
(8883, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 5, 4, 'OT', 'Bây giờ Đức Giê-hô-va Đức Chúa Trời tôi đã cho tôi được yên nghỉ xung quanh; không còn kẻ thù, cũng không có điều ác nào xảy đến.'),
(8884, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 5, 5, 'OT', 'Và nầy, tôi định xây một ngôi nhà cho danh Đức Giê-hô-va Đức Chúa Trời tôi, như Đức Giê-hô-va đã phán cùng Đa-vít cha tôi, rằng: Con trai ngươi, là người ta sẽ đặt lên ngôi ngươi, chính người đó sẽ xây nhà cho danh ta.'),
(8885, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 5, 6, 'OT', 'Bây giờ, xin ngài hãy ra lệnh cho người ta đốn cho tôi những cây bá hương từ Li-ban; các tôi tớ tôi sẽ làm việc cùng các tôi tớ của ngài; tôi sẽ trả tiền công cho các tôi tớ của ngài tùy theo tất cả những gì ngài chỉ định; vì ngài biết rằng trong chúng tôi không có ai biết cách đốn gỗ như người Xi-đôn.'),
(8886, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 5, 7, 'OT', 'Khi Hi-ram nghe các lời của Sa-lô-môn, thì người rất vui mừng và nói: Đáng chúc tụng Đức Giê-hô-va ngày hôm nay, là Đấng đã ban cho Đa-vít một người con trai khôn ngoan để cai trị dân lớn này.'),
(8887, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 5, 8, 'OT', 'Hi-ram sai đến nói với Sa-lô-môn: "Tôi đã nghe điều mà ông đã sai đến tôi; tôi sẽ làm mọi điều ông mong muốn về gỗ bá hương và gỗ tùng."'),
(8888, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 5, 9, 'OT', 'Các đầy tớ của tôi sẽ xuống Li-băng mang gỗ ra biển; còn tôi, tôi sẽ ghép chúng thành bè trên biển, chở đến nơi mà ngài sẽ chỉ định; tại đó, tôi sẽ tháo dỡ chúng ra, và ngài sẽ nhận lấy. Ngài phải thực hiện điều tôi mong muốn, là cung cấp lương thực cho nhà tôi.'),
(8889, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 5, 10, 'OT', 'Hi-ram cung cấp cho Sa-lô-môn các cây bá hương và các cây thông đỏ theo mọi điều người muốn.'),
(8890, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 5, 11, 'OT', 'Vua Sa-lô-môn cấp cho Hi-ram hai mươi ngàn kôr lúa mì làm lương thực cho gia đình ông, và hai mươi kôr dầu ô-liu nguyên chất; vua Sa-lô-môn cấp như thế cho Hi-ram hằng năm.'),
(8891, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 5, 12, 'OT', 'Đức Giê-hô-va ban sự khôn ngoan cho Sa-lô-môn, như Ngài đã hứa với ông; và có sự hòa bình giữa Hi-ram và Sa-lô-môn; rồi hai người lập giao ước với nhau.'),
(8892, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 5, 13, 'OT', 'Vua Sa-lô-môn ra lệnh động viên bắt lính từ khắp dân Y-sơ-ra-ên; và số người bị bắt lính này là ba mươi ngàn người đàn ông.'),
(8893, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 5, 14, 'OT', 'Ngài sai họ đến Li-băng, mỗi tháng một vạn người thay phiên nhau; một tháng họ ở Li-băng, hai tháng ở nhà mình; và A-đô-ni-ram quản lý việc bắt lính.'),
(8894, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 5, 15, 'OT', 'Vua Sa-lô-môn có bảy mươi ngàn người khiêng gánh và tám mươi ngàn người đục đá trên núi.'),
(8895, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 5, 16, 'OT', 'Ngoài các viên quản nhiệm của Sa-lô-môn cai trị công việc ra, thì có ba ngàn ba trăm người chỉ huy dân chúng làm việc.'),
(8896, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 5, 17, 'OT', 'Vua ra lệnh, người ta đem đến những tảng đá lớn, những tảng đá quý giá và những tảng đá đã được đẽo để xây nền nhà.'),
(8897, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 5, 18, 'OT', 'Các thợ xây của vua Sa-lô-môn, các thợ xây của Hi-ram và những người Ghíp-lít đã đục những tảng đá và chuẩn bị gỗ cùng những tảng đá để xây cất đền thờ.'),
(8898, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 1, 'OT', 'Vào năm bốn trăm tám mươi kể từ khi các con trai của Y-sơ-ra-ên ra khỏi đất Ai-cập, năm thứ tư đời vua Sô-lô-môn trị vì trên Y-sơ-ra-ên, vào tháng Xi, tức là tháng thứ hai, người đã xây cất đền thờ cho Đức Giê-hô-va.'),
(8899, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 2, 'OT', 'Nhà mà vua Sa-lô-môn xây cho Đức Giê-hô-va dài sáu mươi thước, rộng hai mươi thước, và cao ba mươi thước.'),
(8900, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 3, 'OT', 'Và phần hiên trước nơi thánh của đền thờ, chiều dài là hai mươi thước theo chiều rộng của đền thờ; chiều rộng của hiên là mười thước, hướng về phía trước đền thờ.'),
(8901, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 4, 'OT', 'Người làm cho ngôi nhà những cửa sổ hẹp và khép kín.'),
(8902, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 5, 'OT', 'Ông xây các phòng dọc theo vách tường của đền thờ, dọc theo các vách tường của đền thờ, cả bên trong nơi thánh và nơi chí thánh; và ông làm các phòng dọc theo các phía.'),
(8903, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 6, 'OT', 'Tầng dưới cùng rộng năm thước, tầng giữa rộng sáu thước, và tầng thứ ba rộng bảy thước; vì Ngài làm các chỗ lùi vào quanh bên ngoài nhà, để các xà không đụng trực tiếp vào tường nhà.'),
(8904, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 7, 'OT', 'Nhà được xây dựng bằng những tảng đá nguyên vẹn đã được đẽo sẵn, nên khi xây nhà không nghe thấy tiếng búa, rìu hay bất kỳ dụng cụ sắt nào.'),
(8905, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 8, 'OT', 'Lối vào buồng giữa ở phía bên phải của nhà; và họ đi lên bằng những bậc thang xoắn ốc lên buồng giữa, rồi từ buồng giữa lên buồng trên cùng.'),
(8906, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 9, 'OT', 'Người xây cất đền thờ và hoàn thành nó; rồi lợp mái đền thờ bằng các xà gỗ và ván gỗ bá hương.'),
(8907, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 10, 'OT', 'Người xây các phòng xung quanh toàn bộ ngôi nhà, cao năm thước; và các phòng nầy tựa vào ngôi nhà bằng những tấm gỗ bá hương.'),
(8908, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 11, 'OT', 'Lời Đức Giê-hô-va phán cùng Sa-lô-môn rằng:'),
(8909, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 12, 'OT', 'Nhà nầy mà ngươi đang xây, nếu ngươi vâng theo các luật lệ ta, thực hành các điều xét đoán ta, và giữ mọi điều răn ta để thực hiện theo, thì ta sẽ thực hiện lời ta đã phán cùng Đa-vít, cha ngươi.'),
(8910, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 13, 'OT', 'Ta sẽ ngự giữa con cái Y-sơ-ra-ên, và sẽ không lìa bỏ dân Ta là Y-sơ-ra-ên.'),
(8911, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 14, 'OT', 'Vậy, Sa-lô-môn xây đền thờ và hoàn thành nó.'),
(8912, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 15, 'OT', 'Người xây các tường nhà bên trong bằng ván gỗ hương nam, từ nền nhà đến các tường của mái vòm, đều lát gỗ bên trong; và Người lát nền nhà bằng ván gỗ tùng.'),
(8913, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 16, 'OT', 'Ông xây hai mươi thước dọc theo hai bên nhà, từ nền đến vách, bằng các tấm gỗ hương nam; ông xây cho nó một nội thất, tức là nơi chí thánh, bên trong nhà.'),
(8914, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 17, 'OT', 'Nhà, tức là đền thờ phía trước, dài bốn mươi thước.'),
(8915, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 18, 'OT', 'Bên trong đền thờ, toàn bộ gỗ hương được chạm trổ hình những nụ hoa và bông nở; tất cả đều bằng gỗ hương, không thấy đá nào lộ ra.'),
(8916, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 19, 'OT', 'Và người đã chuẩn bị nơi chí thánh bên trong nhà, để đặt ở đó hòm giao ước của Đức Giê-hô-va.'),
(8917, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 20, 'OT', 'Và phía trước nơi chí thánh dài hai mươi thước, rộng hai mươi thước, cao hai mươi thước; người ta ốp vàng ròng toàn bộ nơi ấy, và cũng ốp vàng bàn thờ làm bằng gỗ hương nam.'),
(8918, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 21, 'OT', 'Vua Sa-lô-môn lát vàng ròng bên trong toàn bộ đền thờ, và làm một bức ngăn bằng xích vàng trước nơi Thánh Nơi, rồi cũng lát vàng ròng bức ngăn ấy.'),
(8919, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 22, 'OT', 'Toàn thể đền thờ, người phủ vàng cho đến khi hoàn thành toàn bộ đền thờ; và toàn bộ bàn thờ, tức là bàn thờ ở nơi thánh, người cũng phủ vàng.'),
(8920, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 23, 'OT', 'Trong nơi thánh, ông làm hai tượng Kê-ru-bim bằng gỗ ô-liu, mỗi tượng cao mười thước.'),
(8921, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 24, 'OT', 'Mỗi cánh của con kerub này dài năm thước; mỗi cánh của con kerub kia cũng dài năm thước; từ đầu cánh nọ đến đầu cánh kia dài mười thước.'),
(8922, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 25, 'OT', 'Cherub thứ hai là mười thước; cả hai cherub đều cùng một kích thước và một hình dạng.'),
(8923, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 26, 'OT', 'Chiều cao của một chê-ru-bim là mười thước, và chê-ru-bim thứ hai cũng vậy.'),
(8924, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 27, 'OT', 'Ông đặt hai con Kê-ru-bim vào bên trong nhà nội; chúng giang cánh ra: cánh của con Kê-ru-bim nọ chạm vào tường nọ, cánh của con Kê-ru-bim kia chạm vào tường kia, và cánh của chúng chạm nhau ở giữa nhà.'),
(8925, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 28, 'OT', 'Người đã mạ vàng các tượng Kê-ru-bim.'),
(8926, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 29, 'OT', 'Người ta chạm trổ tất cả các vách quanh nhà bằng các hình chạm nổi của các sứ-thần, các cây chà-là và các bông hoa nở, bên trong và bên ngoài.'),
(8927, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 30, 'OT', 'Còn nền nhà của đền thờ, người lát vàng, bên trong và bên ngoài.'),
(8928, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 31, 'OT', 'Và cho lối vào nơi Thánh Nơi Thánh, người làm các cánh cửa bằng gỗ ô-liu; cái ngưỡng và các trụ cửa chiếm một phần năm bức tường.'),
(8929, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 32, 'OT', 'Hai cánh cửa làm bằng gỗ ô-liu; người chạm trổ trên đó các hình trang trí gồm các chê-ru-bim, các cây chà là và các bông hoa nở, rồi mạ vàng; và người trải vàng trên các chê-ru-bim và trên các cây chà là.'),
(8930, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 33, 'OT', 'Người cũng làm cho cửa đền thờ các trụ cửa bằng gỗ ô-liu, theo một phần tư tường.'),
(8931, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 34, 'OT', 'Và hai cửa làm bằng gỗ bá hương: hai cánh của cánh cửa thứ nhất có các nếp gấp, và hai cánh của cánh cửa thứ hai cũng có các nếp gấp.'),
(8932, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 35, 'OT', 'Và ông chạm khắc các hình Kê-ru-bim, các cây dừa và các bông hoa nở; rồi ông phủ vàng ròng lên các chạm trổ đó.'),
(8933, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 36, 'OT', 'Ông xây sân trong bằng ba hàng đá xẻ và một hàng xà gỗ bá hương.'),
(8934, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 37, 'OT', 'Năm thứ tư, nền nhà của Đức Giê-hô-va được đặt, trong tháng Ziv.'),
(8935, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 6, 38, 'OT', 'Đến năm thứ mười một, trong tháng Bul, tức là tháng tám, đền thờ được hoàn tất trọn vẹn mọi phần và mọi qui định của nó. Người đã xây cất nó trong bảy năm.'),
(8936, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 1, 'OT', 'Vua Sô-lô-môn xây cất lâu đài cho mình mất mười ba năm, và người hoàn tất toàn bộ cung điện của mình.'),
(8937, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 2, 'OT', 'Ông xây cất ngôi nhà Rừng Li-băng, dài một trăm thước, rộng năm mươi thước, cao ba mươi thước, dựng trên bốn hàng cột bằng gỗ hương, và những xà ngang bằng gỗ hương đặt trên các cột.'),
(8938, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 3, 'OT', 'Và được lợp bằng gỗ hương nam phía trên các xà ngang, những cái nằm trên bốn mươi lăm cột trụ, mỗi hàng mười lăm cái.'),
(8939, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 4, 'OT', 'Và có ba hàng cửa sổ, mỗi hàng đối diện nhau ba lần.'),
(8940, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 5, 'OT', 'Và mọi cửa và khung cửa đều vuông vức, có các ô cửa sổ; và đối diện với ô cửa sổ là ô cửa sổ, ba hàng.'),
(8941, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 6, 'OT', 'Người làm hành lang các trụ cột; chiều dài của nó là năm mươi thước, chiều rộng là ba mươi thước; và hành lang ở phía trước chúng; các trụ cột và xà ngang lớn cũng ở phía trước chúng.'),
(8942, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 7, 'OT', 'Ngài làm một hành lang cho ngôi báu, nơi Ngài sẽ xét xử, tức là hành lang xét xử, và được lợp gỗ hương từ mặt sàn này đến mặt sàn kia.'),
(8943, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 8, 'OT', 'Nhà người ở, có một sân khác bên trong hành lang, giống như công trình này. Vua Sa-lô-môn cũng xây một ngôi nhà cho con gái của Pha-ra-ôn, mà người đã cưới, giống như hành lang này.'),
(8944, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 9, 'OT', 'Tất cả những điều này đều là những tảng đá quý, theo kích thước đã được đẽo gọt, được cưa bằng cưa, bên trong và bên ngoài, từ nền móng đến các viên đá lát mái, và bên ngoài đến sân lớn.'),
(8945, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 10, 'OT', 'Và nền được xây bằng những khối đá quý, những khối đá lớn, những khối đá dài mười thước, và những khối đá dài tám thước.'),
(8946, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 11, 'OT', 'Và ở phía trên là những tảng đá quý, theo kích thước đá xẻ, cùng với gỗ hương nam.'),
(8947, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 12, 'OT', 'Sân lớn bao quanh gồm ba hàng đá xẻ, và một hàng xà gỗ hương, cả cho sân trong của nhà Đức Giê-hô-va lẫn cho tiền đình của đền thờ.'),
(8948, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 13, 'OT', 'Vua Sa-lô-môn sai người đi và mang Hi-ram từ thành Típ-ru đến.'),
(8949, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 14, 'OT', 'Là con trai của một người đàn bà góa, thuộc chi phái Na-ph ta-li; cha người là một người thành Xi-đôn, thợ khéo về đồng. Người được đầy sự khôn ngoan, sự hiểu biết và sự tinh tế để làm mọi công việc bằng đồng. Người đến cùng vua Sa-lô-môn và làm mọi công việc của vua.'),
(8950, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 15, 'OT', 'Người đã đúc hai trụ bằng đồng; trụ thứ nhất cao mười tám thước, và trụ thứ hai thì một sợi dây dài mười hai thước mới đủ vòng quanh.'),
(8951, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 16, 'OT', 'Ông làm hai đầu trụ bằng đồng đúc để đặt trên đầu hai trụ; chiều cao của đầu trụ nầy là năm thước, và chiều cao của đầu trụ kia cũng là năm thước.'),
(8952, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 17, 'OT', 'Lưới đan kiểu hoa văn, dây xích kiểu vòng nối vòng dành cho các đầu trụ trên cùng các cột trụ; bảy cái cho đầu trụ này, bảy cái cho đầu trụ kia.'),
(8953, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 18, 'OT', 'Người làm các cột trụ, và hai hàng vòng tròn bao quanh cái lưới duy nhất, để che các mão đội đầu ở trên đỉnh những quả lựu; và người làm như vậy cho cái mão đội đầu thứ hai.'),
(8954, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 19, 'OT', 'Các đầu trụ đứng trên đỉnh các cột trụ làm theo kiểu hoa huệ trong hành lang, cao bốn thước.'),
(8955, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 20, 'OT', 'Hai đầu trụ trên hai trụ còn có các vòng tròn trên cao, đối ngang phần bầu tròn gần mạng lưới; và hai trăm trái lựu xếp thành hàng bao quanh đầu trụ thứ hai.'),
(8956, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 21, 'OT', 'Ông dựng hai trụ ở hành lang của đền thờ; ông dựng trụ bên phải và đặt tên là Jachin; ông dựng trụ bên trái và đặt tên là Bô-az.'),
(8957, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 22, 'OT', 'Trên đầu các trụ là công trình hình hoa sen; như vậy công việc làm các trụ đã hoàn tất.'),
(8958, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 23, 'OT', 'Người làm cái biển đúc, rộng mười thước từ mép nầy đến mép kia, tròn toàn vòng quanh, cao năm thước, và một sợi dây ba mươi thước mới đủ vòng quanh nó.'),
(8959, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 24, 'OT', 'Dưới vành mép nó, bao quanh xung quanh, có những trái lựu, mười trái trong một sải tay, bao quanh cái biển xung quanh; những trái lựu đó được đúc thành hai hàng, khi cái biển được đúc.'),
(8960, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 25, 'OT', 'Đứng trên mười hai con bò, ba con quay mặt về hướng bắc, ba con quay mặt về hướng tây, ba con quay mặt về hướng nam, và ba con quay mặt về hướng đông. Chiếc biển đặt phía trên các con bò ấy, và toàn bộ phần phía sau của chúng quay vào trong.'),
(8961, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 26, 'OT', 'Và nó dày một gang tay, mép của nó được làm giống như mép của một cái chén, với những bông hoa bách hợp; nó chứa được hai ngàn bát.'),
(8962, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 27, 'OT', 'Ông làm mười cái bệ bằng đồng; mỗi cái bệ dài bốn thước, rộng bốn thước, cao ba thước.'),
(8963, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 28, 'OT', 'Và đây là công việc của các bệ: chúng có các vách ngăn, và các vách ngăn ở giữa các tầng.'),
(8964, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 29, 'OT', 'Trên các viền ngăn cách giữa các tầng nắp là những hình sư tử, bò tót và các trái nhân; và trên các tầng nắp ấy cũng vậy, ở phía trên; còn dưới các sư tử và bò tót thì có những hình lá kiểu cách, làm bằng kỹ thuật đúc tinh xảo.'),
(8965, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 30, 'OT', 'Và bốn cái bánh xe bằng đồng cho mỗi chân đế, và các trục xe bằng đồng; bốn chân của nó có các tấm đỡ; các tấm đỡ dưới bồn nước được đúc liền, gắn liền với mỗi chân.'),
(8966, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 31, 'OT', 'Miệng nó từ bên trong phần trang trí phía trên là một thước; còn miệng của nó thì tròn, theo kiểu dáng đế, rộng một thước rưỡi. Trên chính miệng ấy có những hình chạm khắc, và các viền của chúng thì vuông, chứ không tròn.'),
(8967, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 32, 'OT', 'Và bốn cái bánh xe ở dưới các khung đỡ; các trục của bánh xe gắn liền với bệ đỡ; và chiều cao của mỗi bánh xe là một thước rưỡi.'),
(8968, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 33, 'OT', 'Các bánh xe được làm giống như bánh xe xe chiến xa; các trục, vành, mo và nan hoa của chúng đều được đúc toàn bộ.'),
(8969, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 34, 'OT', 'Và bốn cái chận đặt ở bốn góc của cái đế nầy; các cái chận nầy là bộ phận của chính cái đế.'),
(8970, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 35, 'OT', 'Trên đầu bệ có viền tròn, cao nửa thước, bao quanh; và trên đầu bệ ấy có các tấm viền và các tấm chắn cùng chất liệu.'),
(8971, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 36, 'OT', 'Người chạm trổ trên các tấm viền của các giá đỡ và trên các khung viền của chúng các hình thần Kê-ru-bim, sư tử và cây cọ, theo khoảng trống thích hợp của từng hình, cùng các hình lá dây vòng quanh.'),
(8972, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 37, 'OT', 'Người đã làm mười cái bệ như thế; tất cả đều cùng một khuôn đúc, cùng một kích thước và cùng một kiểu dáng.'),
(8973, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 38, 'OT', 'Người ấy làm mười cái bồn bằng đồng; mỗi cái bồn chứa được bốn mươi bát; mỗi cái bồn rộng bốn thước; mỗi cái bồn đặt trên một trong mười cái đế.'),
(8974, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 39, 'OT', 'Ông đặt năm cái đế về phía bên phải của nhà, và năm cái đế về phía bên trái của nhà; còn cái biển thì ông đặt về phía bên phải của nhà, về hướng đông, đối diện với phương nam.'),
(8975, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 40, 'OT', 'Hi-ram làm các bồn, các xẻng và các chậu. Hi-ram hoàn thành mọi công việc mà ông đã làm cho vua Sa-lô-môn trong đền thờ Đức Giê-hô-va.'),
(8976, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 41, 'OT', 'Hai cây trụ, hai cái hình cầu trang trí trên đầu hai cây trụ, và hai tấm lưới để che hai cái hình cầu trang trí trên đầu hai cây trụ;'),
(8977, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 42, 'OT', 'Và bốn trăm trái lựu cho hai mạng lưới, mỗi mạng lưới hai hàng trái lựu để phủ hai cái bát của các đầu trụ trên hai cây cột.'),
(8978, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 43, 'OT', 'Mười cái đế và mười cái bồn đặt trên các cái đế.'),
(8979, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 44, 'OT', 'Một cái biển và mười hai con bò đực đặt dưới cái biển ấy.'),
(8980, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 45, 'OT', 'Và những cái chậu, những cái xẻng, những cái bát, và tất cả các đồ dùng bằng đồng cho đền thờ mà Hi-ram làm cho vua Sa-lô-môn cho đền thờ Đức Giê-hô-va, đều làm bằng đồng đánh bóng.'),
(8981, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 46, 'OT', 'Vua đã đúc những vật ấy trong đồng bằng Giô-đanh, trên đất sét, giữa Xúc-cốt và Xáp-than.'),
(8982, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 47, 'OT', 'Vua Sa-lô-môn để tất cả các đồ dùng đó, vì rất nhiều vô số kể, nên không cân được lượng đồng.'),
(8983, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 48, 'OT', 'Sa-lô-môn làm tất cả các đồ dùng thuộc về đền thờ của Đức Giê-hô-va: bàn thờ bằng vàng và cái bàn bằng vàng để bày bánh trần.'),
(8984, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 49, 'OT', 'Và năm cây đèn vàng ròng bên phải và năm cây đèn vàng ròng bên trái đặt trước nơi thánh; các bông hoa, các ngọn đèn và các cái kẹp đèn bằng vàng.'),
(8985, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 50, 'OT', 'Các cái âu, các cái kéo đèn, các cái tưới nước, các cái chén và các cái xẻng bằng vàng ròng; và các bản lề bằng vàng cho các cửa nhà nội, tức nơi chí thánh, và cho các cửa nhà, tức đền thờ.'),
(8986, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 7, 51, 'OT', 'Vậy, mọi công việc mà vua Sa-lô-môn làm cho đền thờ Đức Giê-hô-va đều được hoàn tất. Vua Sa-lô-môn đem những vật thánh mà Đa-vít, cha người, đã biệt riêng ra, tức là bạc, vàng và các đồ dùng, rồi đặt vào các kho tàng trong đền thờ Đức Giê-hô-va.'),
(8987, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 1, 'OT', 'Bấy giờ, Sa-lô-môn triệu tập các trưởng lão của Y-sơ-ra-ên, tất cả các thủ lãnh các chi phái, các tộc trưởng của con cái Y-sơ-ra-ên, đến cùng vua Sa-lô-môn tại Giê-ru-sa-lem, để rước hòm giao ước của Đức Giê-hô-va từ thành Đa-vít, tức là Xi-ôn, lên đó.'),
(8988, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 2, 'OT', 'Hết thảy mọi người Y-sơ-ra-ên đều tập hợp về cùng vua Sa-lô-môn trong tháng Ê-ta-nim, vào dịp lễ hội, tức là tháng bảy.'),
(8989, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 3, 'OT', 'Mọi bậc trưởng lão của Y-sơ-ra-ên đều đến, và các thầy tế lễ khiêng hòm giao ước.'),
(8990, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 4, 'OT', 'Các thầy tế lễ và người Lê-vi khiêng hòm giao ước của Đức Giê-hô-va, cái lều hội ngộ, và mọi đồ thánh ở trong cái lều.'),
(8991, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 5, 'OT', 'Vua Sa-lô-môn và toàn thể hội chúng Ít-ra-en đã được triệu tập đến cùng người, đều ở với người trước hòm giao ước, dâng những con chiên và bò làm của lễ thiêu, đến nỗi không thể đếm được, và không thể tính được vì quá đông.'),
(8992, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 6, 'OT', 'Các thầy tế lễ khiêng hòm giao ước của Đức Giê-hô-va vào nơi của nó, vào nơi chí thánh trong đền thờ, tức là nơi cực thánh, dưới các cánh của các sứ-thần.'),
(8993, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 7, 'OT', 'Vì các chê-ru-bim đã giang hai cánh ra trên nơi đặt hòm bia, và các chê-ru-bim ấy che phủ hòm bia cùng các đòn khiêng của nó từ phía trên.'),
(8994, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 8, 'OT', 'Các cây đòn được kéo dài ra, và các đầu mút của các cây đòn có thể nhìn thấy từ nơi thánh phía trước phòng chí thánh; nhưng bên ngoài thì không thể thấy được. Các cây đòn vẫn còn ở đó cho đến ngày nay.'),
(8995, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 9, 'OT', 'Trong hòm chỉ có hai bảng đá mà Môi-se đã đặt ở Hô-rếp, là những bảng mà Đức Giê-hô-va lập giao ước với con cái Ít-ra-en khi họ ra khỏi đất Ai-cập.'),
(8996, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 10, 'OT', 'Khi các thầy tế lễ ra khỏi nơi thánh, thì đám mây đã đầy cả nhà của Đức Giê-hô-va.'),
(8997, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 11, 'OT', 'Các thầy tế lễ không thể đứng để thi hành chức vụ vì mây che phủ; vì vinh hiển của Đức Giê-hô-va đã đầy nhà của Đức Giê-hô-va.'),
(8998, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 12, 'OT', 'Bấy giờ, Sa-lô-môn nói: Đức Giê-hô-va đã phán Ngài sẽ ngự trong nơi tối tăm.'),
(8999, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 13, 'OT', 'Tôi đã xây một đền thờ uy nghi cho Ngài, một nơi ở vĩnh viễn để Ngài ngự đến muôn đời.'),
(9000, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 14, 'OT', 'Vua quay mặt lại, chúc phước cho toàn thể hội chúng Ít-ra-en; và toàn thể hội chúng Ít-ra-en đang đứng.'),
(9001, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 15, 'OT', 'Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en được tôn phong, Đấng đã dùng miệng phán cùng Đa-vít, cha tôi, và dùng tay Ngài thực hiện điều phán, rằng:'),
(9002, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 16, 'OT', 'Kể từ ngày Ta dẫn dân Ta, là Y-sơ-ra-ên, ra khỏi Ai-cập, Ta đã không chọn một thành nào trong mọi chi phái Y-sơ-ra-ên để xây một ngôi nhà cho Danh Ta ngự đó; nhưng Ta đã chọn Đa-vít để cai trị trên dân Ta, là Y-sơ-ra-ên.'),
(9003, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 17, 'OT', 'Đa-vít, cha tôi, đã có lòng định xây một ngôi nhà cho danh Đức Giê-hô-va, Đức Chúa Trời của Ít-ra-en.'),
(9004, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 18, 'OT', 'Đức Giê-hô-va phán cùng Đa-vít, cha tôi: "Vì lòng ngươi đã có ý định xây một nhà cho danh ta, ngươi đã làm điều tốt, vì lòng ngươi đã có điều đó."'),
(9005, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 19, 'OT', 'Nhưng ngươi sẽ không xây nhà ấy; chính con trai ngươi, người sẽ sinh ra từ ngươi, người ấy sẽ xây nhà cho danh ta.'),
(9006, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 20, 'OT', 'Đức Giê-hô-va đã thực hiện lời Ngài phán, và tôi đã đứng lên thay cho Đa-vít, cha tôi, rồi ngồi trên ngôi vua Ít-ra-en, như Đức Giê-hô-va đã hứa; và tôi đã xây cất nhà cho danh Đức Giê-hô-va, Đức Chúa Trời của Ít-ra-en.'),
(9007, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 21, 'OT', 'Và tôi đã đặt ở đó một chỗ cho hòm giao ước, là nơi có bảng giao ước của Đức Giê-hô-va mà Ngài đã lập với tổ tiên chúng tôi khi đem họ ra khỏi đất Ai-cập.'),
(9008, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 22, 'OT', 'Vua Sa-lô-môn đứng trước bàn thờ của Đức Giê-hô-va, đối diện với toàn thể hội chúng Ít-ra-en, rồi giơ hai tay lên trời.'),
(9009, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 23, 'OT', 'Và ông nói: Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en, không có thần nào như Ngài ở trên trời cao kia và dưới đất này, là Đấng giữ giao ước và sự nhân từ đối với các đầy tớ Ngài, là những người đi trước mặt Ngài với trọn cả tấm lòng mình.'),
(9010, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 24, 'OT', 'Đã giữ lời hứa cùng tôi tớ Ngài là Đa-vít, cha tôi, điều mà Ngài đã phán cùng người; chính miệng Ngài đã phán, và chính tay Ngài đã làm trọn điều đó cho đến ngày nay.'),
(9011, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 25, 'OT', 'Lạy Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên, xin hãy giữ lời Ngài đã hứa cùng đầy tớ Ngài là Đa-vít, cha tôi, rằng: "Ngươi sẽ không thiếu người trước mặt Ta để ngồi trên ngôi Y-sơ-ra-ên," miễn là các con trai ngươi giữ đường lối mình, đi trước mặt Ta như ngươi đã đi trước mặt Ta.'),
(9012, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 26, 'OT', 'Bây giờ, hỡi Đức Chúa Trời của Y-sơ-ra-ên, xin làm cho ứng nghiệm những lời Ngài đã phán cùng đầy tớ Ngài là Đa-vít, cha tôi.'),
(9013, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 27, 'OT', 'Đức Giê-hô-va há thật sự sẽ ngự trên đất sao? Kìa, các từng trời và các từng trời của các từng trời còn chẳng chứa nổi Ngài, huống chi ngôi nhà này mà tôi đã xây!'),
(9014, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 28, 'OT', 'Xin hãy đoái đến lời cầu nguyện của đầy tớ Ngài và lời khẩn xin của người, hỡi Đức Giê-hô-va Đức Chúa Trời tôi, để nghe tiếng kêu và lời cầu nguyện mà đầy tớ Ngài đang dâng lên Ngài ngày hôm nay.'),
(9015, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 29, 'OT', 'Nguyện mắt Ngài luôn mở ra hướng về đền thờ này đêm ngày, hướng về nơi Ngài phán rằng: Danh Ta sẽ ở đó, để nghe lời cầu nguyện mà tôi tớ Ngài dâng lên nơi này.'),
(9016, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 30, 'OT', 'Xin hãy nghe lời khẩn cầu của tôi tớ Ngài và của dân Ngài Y-sơ-ra-ên khi họ cầu nguyện về nơi này; xin Ngài nghe từ nơi Ngài ngự, tức là các từng trời; và khi Ngài nghe, xin tha thứ.'),
(9017, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 31, 'OT', 'Khi có người nào phạm tội cùng người khác, và người kia bắt phải thề để buộc lời thề, thì lời thề ấy được mang đến trước bàn thờ của Ngài trong đền thờ nầy.'),
(9018, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 32, 'OT', 'Đức Giê-hô-va hãy nghe từ các từng trời, rồi thi hành và xét xử các tôi tớ Ngài, lên án kẻ ác, khiến hắn gánh hậu quả con đường hắn đã đi, và tuyên bố người công bình vô tội, để ban cho người ấy theo sự công bình của người.'),
(9019, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 33, 'OT', 'Khi dân Y-sơ-ra-ên của Ngài bị đánh bại trước mặt kẻ thù vì họ đã phạm tội nghịch cùng Ngài, rồi họ trở lại cùng Ngài, công nhận danh Ngài, và cầu nguyện, van xin Ngài trong đền thờ nầy,'),
(9020, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 34, 'OT', 'Thì xin Ngài ở trên trời hãy nghe, tha tội cho dân Ngài là Y-sơ-ra-ên, và đem họ trở về đất mà Ngài đã ban cho tổ phụ họ.'),
(9021, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 35, 'OT', 'Khi các từng trời bị đóng lại, không có mưa, vì chúng nó đã phạm tội nghịch cùng Ngài, nếu chúng nó cầu nguyện về nơi này, công nhận danh Ngài, và từ bỏ tội lỗi mình khi Ngài giáng họ sự khốn khổ:'),
(9022, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 36, 'OT', 'Đức Giê-hô-va từ trời hãy nghe, và tha thứ cho tội lỗi của các tôi tớ Ngài và của dân Ngài Y-sơ-ra-ên, vì Ngài dạy họ con đường tốt lành mà họ phải đi; và ban mưa xuống trên đất nước Ngài đã ban cho dân Ngài làm sản nghiệp.'),
(9023, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 37, 'OT', 'Nếu trong đất có sự đói kém, nếu có ôn dịch, thối rữa, sâu lửa, châu chấu, sâu non; nếu kẻ thù của chúng vây hãm chúng trong đất các thành của chúng; mọi tai họa, mọi bệnh tật;'),
(9024, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 38, 'OT', 'Mọi lời cầu nguyện, mọi lời khẩn nguyện mà bất cứ người nào hay toàn thể dân ngươi là Y-sơ-ra-ên sẽ dâng lên, khi mỗi người biết được tai họa trong lòng mình và giơ tay hướng về đền thờ nầy,'),
(9025, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 39, 'OT', 'Đức Giê-hô-va, xin hãy nghe từ các từng trời, nơi ngự của Ngài, và tha thứ, thực hiện, và ban cho mỗi người tùy theo mọi đường lối của người ấy, là điều Ngài biết trong lòng người; vì chính Ngài, một mình Ngài, biết lòng mọi con người.'),
(9026, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 40, 'OT', 'Nguyện họ kính sợ Đức Giê-hô-va mọi ngày họ còn sống trên đất mà Ngài đã ban cho tổ tiên chúng tôi.'),
(9027, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 41, 'OT', 'Còn về người ngoại bang, không thuộc dân ngươi là Y-sơ-ra-ên, nhưng từ một xứ xa xôi đến vì danh Ngài,'),
(9028, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 42, 'OT', 'Vì họ sẽ nghe danh lớn của Ngài, và cánh tay quyền năng của Ngài, cùng với cánh tay giơ ra xa; khi người ấy đến và cầu nguyện về hướng nhà này,'),
(9029, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 43, 'OT', 'Đức Giê-hô-va sẽ nghe từ trời, nơi ngự của Ngài, và làm theo mọi điều mà người ngoại bang kêu cầu Ngài, để mọi dân trên đất biết đến danh Ngài, kính sợ Ngài như dân Ngài là Y-sơ-ra-ên, và biết rằng danh Ngài được gọi trên đền thờ nầy, mà tôi đã xây dựng.'),
(9030, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 44, 'OT', 'Khi dân Ngài ra đi đánh giặc chống lại kẻ thù, bất cứ nơi nào Ngài sai họ đi, họ sẽ cầu nguyện cùng Đức Giê-hô-va hướng về thành phố mà Ngài đã chọn và về nhà mà tôi đã xây để tôn vinh danh Ngài.'),
(9031, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 45, 'OT', 'Đức Giê-hô-va sẽ nghe từ trời lời cầu nguyện và lời khẩn nài của họ, và thực hiện công lý cho họ.'),
(9032, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 46, 'OT', 'Nếu chúng phạm tội cùng Ngài, vì chẳng có người nào chẳng phạm tội, và Ngài nổi giận cùng chúng, rồi trao chúng vào tay kẻ thù, khiến chúng bị kẻ thù bắt đi làm phu tù đến đất của kẻ thù, xa hay gần;'),
(9033, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 47, 'OT', 'và họ sẽ trở lại trong lòng mình tại đất mà họ bị bắt làm phu tù, và họ sẽ trở lại cùng nài xin Ngài trong đất của những kẻ đã bắt họ đi, mà rằng: Chúng tôi đã phạm tội, đã làm điều ác, đã làm điều gian ác.'),
(9034, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 48, 'OT', 'Và khi họ trở lại cùng Ngài hết lòng, hết linh hồn mình, trong đất của kẻ thù đã bắt họ làm phu tù, và khi họ cầu nguyện cùng Ngài, hướng về đất nước mà Ngài đã ban cho tổ tiên họ, về thành phố mà Ngài đã chọn, và về đền thờ mà tôi đã xây dựng cho danh Ngài,'),
(9035, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 49, 'OT', 'Xin hãy nghe từ các từng trời, nơi Ngài ngự, lời cầu nguyện và khẩn nài của họ, và xét xử công bằng cho họ.'),
(9036, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 50, 'OT', 'Xin tha thứ cho dân Ngài là kẻ đã phạm tội nghịch cùng Ngài, và cho mọi sự vi phạm mà họ đã phạm nghịch cùng Ngài; xin ban cho họ lòng thương xót trước mặt những kẻ đã bắt họ làm phu tù, để những kẻ ấy thương xót họ.'),
(9037, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 51, 'OT', 'Vì họ là dân sự ngươi và sản nghiệp ngươi, là những người ngươi đã dẫn ra khỏi Ai Cập, từ giữa lò lửa bằng sắt.'),
(9038, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 52, 'OT', 'Xin cho mắt Ngài luôn mở ra nhìn đến lời khẩn nguyện của kẻ tôi tớ Ngài và lời khẩn nguyện của dân Ngài là Y-sơ-ra-ên, để nghe họ trong mọi điều họ kêu cầu Ngài.'),
(9039, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 53, 'OT', 'Vì chính Ngài đã biệt riêng họ ra khỏi mọi dân trên đất để làm cơ nghiệp thuộc về Ngài, như Ngài đã phán qua tay Môi-se, tôi tớ Ngài, khi Ngài đem tổ phụ chúng tôi ra khỏi Ai-cập, hỡi Đức Giê-hô-va Đức Chúa Trời.'),
(9040, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 54, 'OT', 'Khi Sa-lô-môn cầu nguyện xong với Đức Giê-hô-va tất cả lời cầu nguyện và khẩn nài nầy, người đứng dậy khỏi trước bàn thờ Đức Giê-hô-va, từ tư thế quỳ gối với hai tay giơ lên trời.'),
(9041, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 55, 'OT', 'Ông đứng dậy và chúc phước cho toàn thể hội chúng Ít-ra-en bằng tiếng nói lớn, rằng:'),
(9042, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 56, 'OT', 'Đức Giê-hô-va phước cho, Đấng đã ban sự yên nghỉ cho dân Y-sơ-ra-ên của Ngài, y như mọi điều Ngài đã phán; không một lời nào trong mọi lời tốt lành của Ngài mà Ngài đã phán qua tay Môi-se, tôi tớ Ngài, bị thất bại.'),
(9043, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 57, 'OT', 'Nguyện Đức Giê-hô-va Đức Chúa Trời chúng tôi ở cùng chúng tôi như Ngài đã ở cùng các tổ phụ chúng tôi; chớ có lìa bỏ chúng tôi, cũng đừng từ bỏ chúng tôi.'),
(9044, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 58, 'OT', 'Nguyện Ngài làm cho lòng chúng ta hướng về Ngài, để chúng ta bước đi trong mọi con đường của Ngài, và giữ các điều răn, các luật lệ và các mạng lệnh mà Ngài đã truyền dạy cho tổ tiên chúng ta.'),
(9045, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 59, 'OT', 'Nguyện những lời nầy, mà tôi đã nài xin trước mặt Đức Giê-hô-va, luôn ở trước mặt Đức Giê-hô-va Đức Chúa Trời chúng ta ngày và đêm, để Ngài thực hiện sự xét xử cho tôi tớ Ngài và cho dân Ngài là Y-sơ-ra-ên, mỗi ngày một việc.'),
(9046, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 60, 'OT', 'Để cho mọi dân trên đất biết rằng Đức Giê-hô-va là Đức Chúa Trời, ngoài Ngài chẳng có ai khác.'),
(9047, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 61, 'OT', 'Lòng các ngươi phải trọn vẹn với Đức Giê-hô-va Đức Chúa Trời chúng ta, để đi theo các luật lệ Ngài và giữ các điều răn của Ngài, như ngày nay.'),
(9048, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 62, 'OT', 'Vua và toàn thể Y-sơ-ra-ên cùng với người dâng của lễ thiêu trước mặt Đức Giê-hô-va.'),
(9049, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 63, 'OT', 'Vua Sa-lô-môn dâng những của lễ thù ân mà người dâng cho Đức Giê-hô-va: hai mươi hai ngàn con bò và một trăm hai mươi ngàn con chiên. Rồi vua và toàn thể con cái Ít-ra-en dâng lễ khánh thành đền thờ Đức Giê-hô-va.'),
(9050, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 64, 'OT', 'Ngày ấy, vua đã biệt riêng phần giữa sân, là nơi trước nhà Đức Giê-hô-va, vì tại đó ông dâng của lễ thiêu, của lễ chay và mỡ các của lễ thù ân; bởi cái bàn thờ đồng đặt trước mặt Đức Giê-hô-va thì quá nhỏ để chứa của lễ thiêu, của lễ chay và mỡ các của lễ thù ân.'),
(9051, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 65, 'OT', 'Bấy giờ, Sa-lô-môn dâng lễ, và cả Ít-ra-en cùng người họp lại thành một hội lớn, từ nơi vào Ha-mát cho đến sông Ai-cập, trước mặt Đức Giê-hô-va Đức Chúa Trời chúng ta, bảy ngày và bảy ngày, tức là mười bốn ngày.'),
(9052, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 8, 66, 'OT', 'Vào ngày thứ tám, ông cho dân chúng về, và họ chúc phước cho vua, rồi đi về lều trại mình trong niềm vui mừng và lòng hân hoan vì mọi điều tốt lành mà Đức Giê-hô-va đã làm cho Đa-vít, tôi tớ Ngài, và cho Ít-ra-en, dân sự Ngài.'),
(9053, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 9, 1, 'OT', 'Khi Sô-lô-môn đã hoàn thành việc xây cất nhà của Đức Giê-hô-va, cung điện của vua, và mọi điều mà Sô-lô-môn mong muốn làm,'),
(9054, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 9, 2, 'OT', 'Đức Giê-hô-va hiện ra cùng Sa-lô-môn lần thứ hai, như Ngài đã hiện ra cho người tại Ghíp-ôn.'),
(9055, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 9, 3, 'OT', 'Đức Giê-hô-va phán cùng người rằng: Ta đã nghe lời cầu nguyện và khẩn nguyện mà ngươi đã dâng trước mặt Ta. Ta đã biệt riêng ngôi nhà nầy, mà ngươi đã xây, để đặt danh Ta ở đó mãi mãi; và mắt Ta cùng lòng Ta sẽ ở đó mọi ngày.'),
(9056, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 9, 4, 'OT', 'Và nếu ngươi sẽ đi trước mặt ta như Đa-vít cha ngươi đã đi, với lòng trọn vẹn và ngay thẳng, để làm theo mọi điều ta đã truyền cho ngươi, thì ngươi sẽ giữ các luật lệ và các quyết định ta.'),
(9057, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 9, 5, 'OT', 'Thì ta sẽ lập ngôi vương quyền của ngươi trên Ít-ra-en đời đời, như ta đã phán cùng Đa-vít cha ngươi rằng: Chẳng hề bị cắt đứt khỏi ngươi một người nào ngồi trên ngôi Ít-ra-en.'),
(9058, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 9, 6, 'OT', 'Nếu các ngươi và con cái các ngươi từ bỏ Ta mà không giữ các điều răn, các luật lệ Ta đã ban cho các ngươi, mà đi theo và thờ lạy các thần khác, và cúi lạy chúng,'),
(9059, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 9, 7, 'OT', 'Ta sẽ cắt đứt Y-sơ-ra-ên khỏi đất Ta đã ban cho họ, và Ta sẽ đuổi khỏi trước mặt Ta ngôi nhà mà Ta đã biệt riêng ra cho danh Ta; và Y-sơ-ra-ên sẽ trở thành một câu chuyện châm biếm và một đề tài nhạo báng giữa mọi dân tộc.'),
(9060, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 9, 8, 'OT', 'Và đền thờ này sẽ trở nên cao cả, mọi người đi ngang qua sẽ kinh ngạc và huýt sáo; họ sẽ nói: "Tại sao Đức Giê-hô-va làm điều này cho đất nước này và cho đền thờ này?"'),
(9061, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 9, 9, 'OT', 'Và họ sẽ nói: "Bởi vì chúng nó đã lìa bỏ Đức Giê-hô-va Đức Chúa Trời của chúng nó, Đấng đã đem tổ tiên chúng nó ra khỏi đất Ai-cập; chúng nó bám víu vào các thần khác, cúi lạy và phục sự các thần ấy. Vì cớ đó, Đức Giê-hô-va đã giáng trên chúng nó mọi điều tai họa nghiêm trọng này."'),
(9062, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 9, 10, 'OT', 'Sau hai mươi năm, khi Sô-lô-môn đã xây xong hai ngôi nhà, là nhà của Đức Giê-hô-va và nhà của vua,'),
(9063, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 9, 11, 'OT', 'Hi-ram, vua thành Týre, đã cung cấp cho Sa-lô-môn các cây bá hương, cây hương nam và vàng, tùy theo mọi điều người muốn. Bấy giờ, vua Sa-lô-môn cho Hi-ram hai mươi thành trong xứ Ga-li-lê.'),
(9064, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 9, 12, 'OT', 'Hi-ram đi ra từ Típ để xem các thành mà Sa-lô-môn đã ban cho ông, nhưng chúng không đẹp lòng ông.'),
(9065, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 9, 13, 'OT', 'Vua Hi-ram nói: "Những thành nào đây mà ngài đã ban cho tôi, hỡi anh tôi?" Rồi người gọi các thành ấy là đất Ca-bun, cho đến ngày nay.'),
(9066, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 9, 14, 'OT', 'Hi-ram sai vua một trăm hai mươi kikar vàng.'),
(9067, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 9, 15, 'OT', 'Và đây là lý do về số lao dịch mà vua Sa-lô-môn đã huy động để xây cất đền thờ của Đức Giê-hô-va, cung điện của mình, khu thành bổ sung, tường thành Giê-ru-sa-lem, Ha-xor, Mê-gi-đô và Ghe-xer.'),
(9068, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 9, 16, 'OT', 'Pha-ra-ô, vua nước Ai Cập, đã kéo lên, chiếm lấy Gẹ-ze và thiêu hủy nó bằng lửa, rồi giết những người Ca-na-an đang ở trong thành đó; và ông đã ban thành ấy làm của hồi môn cho con gái mình, vợ của Sa-lô-môn.'),
(9069, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 9, 17, 'OT', 'Vua Sa-lô-môn xây cất Ghê-xe và Bết-hô-rôn Hạ.'),
(9070, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 9, 18, 'OT', 'Và Ba-a-lát, và Ta-ma-r trong đồng vắng, tại miền đất ấy.'),
(9071, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 9, 19, 'OT', 'Tất cả các thành chứa đồ tiếp tế mà Sa-lô-môn có, các thành cho xe chiến mã, các thành cho ngựa, và các nơi mà Sa-lô-môn muốn xây cất tại Giê-ru-sa-lem, tại Li-băng, và trong khắp đất nước của người.'),
(9072, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 9, 20, 'OT', 'Tất cả những người còn sót lại là người Amôrít, người Hêthít, người Phêrizít, người Hivít và người Yêbusít, không phải là con cháu của Y-sơ-ra-ên,'),
(9073, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 9, 21, 'OT', 'Con cái của các dân ấy, là những kẻ còn sót lại giữa đất sau chúng nó, mà con cái Y-sơ-ra-ên không thể tiêu diệt hết được, thì Sa-lô-môn bắt chúng phục dịch lao động buộc phải làm đến ngày nay.'),
(9074, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 9, 22, 'OT', 'Vua Sa-lô-môn không bắt con cháu Y-sơ-ra-ên làm đầy tớ; vì họ là những người lính chiến, là tôi tớ của vua, là các quan trưởng, là các đội trưởng, là các quan cai xe ngựa và là các kỵ binh của vua.'),
(9075, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 9, 23, 'OT', 'Đây là các quan cai trị được đặt lên công việc của Sa-lô-môn, gồm năm trăm năm mươi người, những người chỉ huy dân chúng làm việc.'),
(9076, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 9, 24, 'OT', 'Chỉ có con gái của Pha-ra-ôn đi lên khỏi thành của Đa-vít đến nhà mà người đã xây cho nàng; lúc ấy, người xây xong Mi-lô.'),
(9077, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 9, 25, 'OT', 'Và ba lần mỗi năm, Sa-lô-môn dâng các của lễ thiêu và của lễ thù ân trên bàn thờ mà người đã xây cho Đức Giê-hô-va, và đốt hương trên bàn thờ ở trước mặt Đức Giê-hô-va. Như vậy, người hoàn thành việc xây cất ngôi nhà.'),
(9078, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 9, 26, 'OT', 'Vua Sa-lô-môn đóng các tàu chiến tại Ê-xi-ôn-ghê-be, là nơi gần Ê-lốt, bên bờ Biển Đỏ, trong xứ Ê-đôm.'),
(9079, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 9, 27, 'OT', 'Hi-ram sai các đầy tớ mình đi trong hạm đội, những người lái thuyền quen biết biển cả, cùng với các đầy tớ của Sa-lô-môn.'),
(9080, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 9, 28, 'OT', 'Họ đến Ofir, lấy từ đó vàng bốn trăm hai mươi kikar, và mang đến cho vua Sô-lô-môn.'),
(9081, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 10, 1, 'OT', 'Vua nữ Sê-ba nghe đồn danh tiếng của Sa-lô-môn về danh Đức Giê-hô-va, bèn đến để thử ông bằng những câu đố.'),
(9082, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 10, 2, 'OT', 'Bà ấy đến Giê-ru-sa-lem với một đoàn tùy tùng rất đông đảo, những con lạc đà chở đầy các thứ hương liệu, vàng rất nhiều và những viên đá quý; bà ấy đến gặp Sa-lô-môn và nói với ông tất cả những điều nằm trong lòng bà.'),
(9083, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 10, 3, 'OT', 'Vua Sa-lô-môn đã đáp cho bà mọi điều bà hỏi; chẳng có điều gì vua giấu kín mà không nói cho bà biết.'),
(9084, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 10, 4, 'OT', 'Vua nữ Sheba thấy toàn bộ sự khôn ngoan của Sa-lô-môn và ngôi nhà mà người đã xây.'),
(9085, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 10, 5, 'OT', 'Và thức ăn trên bàn của người, chỗ ngồi của các đầy tớ người, sự phục vụ của các quan viên người, y phục của họ, cách uống rượu của người, và những lễ vật thiêu người dâng trong nhà của Đức Giê-hô-va; thì bà không còn hơi sức nào nữa.'),
(9086, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 10, 6, 'OT', 'Bà nói với nhà vua: "Thật vậy, điều tôi đã nghe ở đất nước tôi về các việc của ngài và sự khôn ngoan của ngài là đúng."'),
(9087, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 10, 7, 'OT', 'Tôi đã không tin những lời đó cho đến khi tôi đến tận nơi và mắt tôi đã tận mắt chứng kiến; và này, người ta đã chẳng nói cho tôi biết đến phân nửa; ngài đã vượt trội về sự khôn ngoan và điều thiện hơn những gì tôi đã nghe.'),
(9088, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 10, 8, 'OT', 'Phước cho các người của vua, phước cho những đầy tớ của vua, những người luôn luôn đứng trước mặt vua, được nghe sự khôn ngoan của vua.'),
(9089, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 10, 9, 'OT', 'Được thay thế bởi Đức Giê-hô-va Đức Chúa Trời của ngươi, là Đấng đã yêu thích ngươi, đặt ngươi lên ngôi vua trên Y-sơ-ra-ên; vì Đức Giê-hô-va yêu Y-sơ-ra-ên đời đời, nên Ngài lập ngươi làm vua để thực hành sự xét xử và công lý.'),
(9090, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 10, 10, 'OT', 'Hoàng hậu đã dâng cho vua một trăm hai mươi kikar vàng, rất nhiều hương liệu và các loại đá quý. Không còn có lượng hương liệu nào lớn như thế nữa, như lượng mà hoàng hậu xứ Sê-ba đã dâng cho vua Sa-lô-môn.'),
(9091, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 10, 11, 'OT', 'Cũng vậy, đoàn tàu của Hi-ram, người đã chở vàng từ Ô-phia, đã chở từ Ô-phia rất nhiều cây lim và những viên đá quý.'),
(9092, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 10, 12, 'OT', 'Vua dùng các cây bạch đàn làm cột cho nhà Đức Giê-hô-va và cho cung điện của vua, cùng với những cây đờn cầm và đờn lia cho các ca sĩ; chưa từng có các cây bạch đàn như thế đến, cũng chưa từng thấy cho đến ngày nay.'),
(9093, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 10, 13, 'OT', 'Vua Sa-lô-môn ban cho nữ vương xứ Sê-ba mọi điều bà mong muốn, bất cứ điều gì bà xin, ngoài những gì vua Sa-lô-môn đã ban cho bà theo khả năng của mình. Rồi bà trở về đất nước mình, cùng các đầy tớ của bà.'),
(9094, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 10, 14, 'OT', 'Số lượng vàng mà Sa-lô-môn nhận được trong một năm là sáu trăm sáu mươi sáu ta-lâng vàng.'),
(9095, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 10, 15, 'OT', 'Ngoài số tiền thu được từ các thương gia, lợi nhuận từ các nhà buôn hương liệu, và từ tất cả các vua của vùng Ả-rập cùng các quan tổng trấn trong xứ.'),
(9096, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 10, 16, 'OT', 'Vua Sa-lô-môn làm hai trăm cái khiên bằng vàng ròng; sáu trăm chỉ vàng dùng cho một cái khiên.'),
(9097, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 10, 17, 'OT', 'Và ba trăm cái khiên bằng vàng ròng, mỗi khiên dùng ba mina vàng; và nhà vua đặt những cái khiên ấy trong nhà Rừng Li-ban.'),
(9098, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 10, 18, 'OT', 'Vua làm một cái ngôi bằng ngà rất lớn và bọc nó bằng vàng ròng.'),
(9099, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 10, 19, 'OT', 'Ngai có sáu bậc thang, và đầu ngai tròn về phía sau; hai bên chỗ ngồi có tay vịn, và hai con sư tử đứng bên cạnh các tay vịn.'),
(9100, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 10, 20, 'OT', 'Và mười hai con sư tử đứng đó, sáu con ở mỗi bên các bậc thang; chẳng có cái nào như vậy được làm cho bất kỳ vương quốc nào.'),
(9101, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 10, 21, 'OT', 'Mọi đồ đựng rượu của vua Sô-lô-môn đều bằng vàng, và mọi đồ dùng trong nhà Rừng Li-băng đều bằng vàng ròng; thời Sô-lô-môn, bạc không được coi là gì cả.'),
(9102, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 10, 22, 'OT', 'Vì các tàu của Tarsis thuộc về nhà vua trên biển cùng với các tàu của Hi-ram; cứ ba năm một lần, đoàn tàu Tarsis đến, chở vàng, bạc, ngà voi, khỉ và công.'),
(9103, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 10, 23, 'OT', 'Vua Sa-lô-môn trở nên lớn hơn tất cả các vua trên đất về của cải và sự khôn ngoan.'),
(9104, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 10, 24, 'OT', 'Toàn thể đất đều tìm đến cùng Sa-lô-môn để nghe sự khôn ngoan mà Đức Chúa Trời đã đặt trong lòng người.'),
(9105, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 10, 25, 'OT', 'Họ mỗi người mang lễ vật của mình đến, gồm các đồ bằng bạc, các đồ bằng vàng, áo xống, khí giới, hương liệu, ngựa và lừa, mỗi năm một lần.'),
(9106, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 10, 26, 'OT', 'Vua Sa-lô-môn tập trung các xe chiến và ngựa chiến; người có một ngàn bốn trăm xe chiến và mười hai ngàn ngựa chiến, và người bố trí chúng trong các thành dành cho xe chiến, và cùng với vua tại Giê-ru-sa-lem.'),
(9107, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 10, 27, 'OT', 'Vua khiến bạc ở Giê-ru-sa-lem trở nên như những viên đá, và khiến các cây hương nam trở nên như những cây vả ở các thung lũng về số lượng rất nhiều.'),
(9108, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 10, 28, 'OT', 'Xe ngựa mà Sa-lô-môn có đều được đưa từ Ai Cập; các thương gia của nhà vua mua từng đàn ngựa với giá định sẵn.'),
(9109, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 10, 29, 'OT', 'Một cỗ xe được đưa lên và xuất phát từ Ai Cập với giá sáu trăm miếng bạc; một con ngựa giá một trăm năm mươi miếng; và cũng vậy, cho mọi vua dân Heth và các vua nước Sy-ria, họ đã xuất cảng bằng tay họ.'),
(9110, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 1, 'OT', 'Vua Sa-lô-môn yêu nhiều phụ nữ ngoại bang, cùng với con gái của Pha-ra-ôn, những người đàn bà của dân Mô-áp, Am-môn, Ê-đôm, Xi-đôn, và dân Hê-th;'),
(9111, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 2, 'OT', 'Các dân tộc mà Đức Giê-hô-va đã phán cùng con cái Y-sơ-ra-ên: "Ngươi chẳng nên kết hôn với chúng, và chúng cũng không nên kết hôn với ngươi," vì chắc chắn chúng sẽ làm lòng ngươi theo các thần của chúng; vua Sô-lô-môn đã gắn bó với những dân này vì tình yêu.'),
(9112, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 3, 'OT', 'Ông có bảy trăm vợ là các công chúa, và ba trăm nàng hầu; các vợ của ông đã làm lòng ông đi theo hướng khác.'),
(9113, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 4, 'OT', 'Khi Sa-lô-môn về già, các vợ của ông làm lòng ông xao lạc theo các thần khác; lòng ông không trọn vẹn với Đức Giê-hô-va Đức Chúa Trời của ông, như lòng Đa-vít cha ông.'),
(9114, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 5, 'OT', 'Vua Sa-lô-môn đi theo Át-tô-rết, nữ thần của người Xi-đôn, và theo Mi-lóc, hình tượng đáng ghê tởm của người Am-môn.'),
(9115, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 6, 'OT', 'Vua Sa-lô-môn làm điều ác trước mặt Đức Giê-hô-va, và không trung thành theo Đức Giê-hô-va như Đa-vít, cha người.'),
(9116, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 7, 'OT', 'Bấy giờ, Sa-lô-môn xây một nơi cao cho Kê-mô-sơ, hình tượng gớm ghiếc của Mô-áp, trên ngọn núi phía trước Giê-ru-sa-lem, và cho Mô-léc, hình tượng gớm ghiếc của con cái Am-môn.'),
(9117, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 8, 'OT', 'Và người cũng làm như vậy cho tất cả các vợ ngoại của mình, những người đốt hương và dâng tế lễ cho các thần của họ.'),
(9118, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 9, 'OT', 'Đức Giê-hô-va nổi giận cùng Sa-lô-môn, vì lòng người đã xây khỏi Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en, là Đấng đã hiện ra cùng người hai lần.'),
(9119, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 10, 'OT', 'Đức Giê-hô-va đã căn dặn người về điều này, không được đi theo các thần khác; nhưng người ấy đã không tuân giữ điều Đức Giê-hô-va đã truyền dạy.'),
(9120, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 11, 'OT', 'Đức Giê-hô-va phán cùng Sa-lô-môn: "Vì điều này đã xảy ra nơi ngươi, và ngươi đã không giữ giao ước và các luật lệ ta đã truyền cho ngươi, ta sẽ chắc chắn xé bỏ vương quốc khỏi ngươi và ban nó cho tôi tớ ngươi."'),
(9121, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 12, 'OT', 'Dẫu vậy, trong đời ngươi, Ta sẽ không làm điều đó, vì cớ Đa-vít, cha ngươi; nhưng Ta sẽ đoạt lấy nó khỏi tay con trai ngươi.'),
(9122, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 13, 'OT', 'Tuy nhiên, Ta sẽ không xé bỏ toàn bộ vương quốc; một chi phái Ta sẽ ban cho con trai ngươi, vì cớ Đa-vít, tôi tớ Ta, và vì cớ Giê-ru-sa-lem, thành mà Ta đã chọn.'),
(9123, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 14, 'OT', 'Đức Giê-hô-va khiến cho một kẻ thù nổi lên chống lại vua Sa-lô-môn, là Ha-đáp người Ê-đôm, thuộc dòng dõi vua trong xứ Ê-đôm.'),
(9124, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 15, 'OT', 'Khi Đa-vít ở Ê-đôm, và Giô-áp, tư lệnh đạo quân, đã lên để chôn những người bị giết, thì ông đã đánh giết mọi nam giới trong Ê-đôm.'),
(9125, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 16, 'OT', 'Sáu tháng, Giô-áp và toàn thể Y-sơ-ra-ên ở lại đó cho đến khi diệt sạch mọi người nam ở Ê-đôm.'),
(9126, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 17, 'OT', 'A-đát đã trốn đi, cùng với một số người Ê-đôm, là các đầy tớ của cha người, đến Ai Cập; lúc ấy A-đát còn là một đứa trẻ nhỏ.'),
(9127, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 18, 'OT', 'Họ rời khỏi Mídian, đến Pa-ran, rồi chiêu mộ những người ở Pa-ran đi theo mình; sau đó họ đến Ai Cập, yết kiến Pha-ra-ôn, vua Ai Cập. Vua ban cho người ấy một ngôi nhà, cung cấp thực phẩm và cấp cho người ấy một miếng đất.'),
(9128, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 19, 'OT', 'Hadad được Pha-ra-ô rất thương mến, nên Pha-ra-ô đã gả cho ông một người vợ là em gái vợ mình, em gái của nữ hoàng Tah-phan-ê.'),
(9129, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 20, 'OT', 'Chị của Tah-phen-ê-xơ đã sinh cho người ấy là Ghen-u-bát, con trai người; và Tah-phen-ê-xơ nuôi dứt sữa người ấy trong nhà của Pha-ra-ôn; và Ghen-u-bát sống trong nhà Pha-ra-ôn giữa các con trai của Pha-ra-ôn.'),
(9130, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 21, 'OT', 'Khi Hadađ nghe ở Ai Cập rằng Đa-vít đã an giấc cùng các tổ phụ mình, và rằng Giô-áp, tổng chỉ huy đạo binh, đã chết, thì Hadađ thưa cùng vua Pha-ra-ôn: "Xin cho tôi đi, để tôi về đất nước tôi."'),
(9131, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 22, 'OT', 'Pha-ra-ô nói với ông: "Ngươi thiếu điều gì nơi ta mà nay ngươi lại tìm cách trở về xứ mình?" Ông đáp: "Tôi không thiếu gì cả; nhưng xin hãy cho tôi đi."'),
(9132, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 23, 'OT', 'Đức Chúa Trời khiến cho ông ta có một kẻ thù là Rê-zôn, con trai Ê-li-a-đa, người đã trốn khỏi chủ mình là Ha-đa-đe-xe, vua Xô-ba.'),
(9133, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 24, 'OT', 'Và người tập họp những người theo mình, rồi trở thành thủ lĩnh một nhóm quân, khi Đa-vít đánh bại họ; họ đi đến Đa-mách, ở lại đó, và làm vua tại Đa-mách.'),
(9134, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 25, 'OT', 'Toàn bộ thời gian của Sa-lô-môn, người này làm kẻ thù nghịch với Ít-ra-en, ngoài điều ác mà Ha-đáp gây ra; người đã nổi dậy chống lại Ít-ra-en và làm vua trên A-ram.'),
(9135, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 26, 'OT', 'Và Giê-rô-bô-am, con trai của Nê-bát, người Ê-phơ-ra-thi, ở Xê-rê-đa, mẹ người là Xê-ru-a, một người đàn bà goá, là đầy tớ của Sa-lô-môn, đã dơ tay chống lại vua.'),
(9136, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 27, 'OT', 'Và điều nầy là lý do tại sao người đã chống lại vua: khi Sa-lô-môn xây cất Mi-lô và vá các chỗ sụp đổ trong thành Đa-vít, cha người.'),
(9137, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 28, 'OT', 'Và người đàn ông Giê-rô-bô-am là một người mạnh mẽ dũng cảm; và khi Sa-lô-môn thấy người thanh niên này siêng năng làm việc, ông đã bổ nhiệm anh ta làm người quản lý toàn bộ công việc của nhà Giô-sép.'),
(9138, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 29, 'OT', 'Và xảy ra vào lúc ấy, khi Giê-rô-bô-am ra khỏi Giê-ru-sa-lem, thì A-hi-gia, vị ngôn sứ người Si-lô, gặp ông trên đường; ông này đang mặc áo mới, và chỉ có hai người ở riêng một mình ngoài đồng.'),
(9139, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 30, 'OT', 'A-hi-gia nắm lấy chiếc áo mới đang mặc trên người mình, rồi xé nó ra mười hai mảnh.'),
(9140, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 31, 'OT', 'Đức Giê-hô-va phán cùng Giê-rô-bô-am rằng: "Hãy lấy cho mình mười miếng; vì Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên phán như vầy: Nầy, Ta sẽ xé nước khỏi tay Sa-lô-môn và sẽ trao cho ngươi mười chi phái."'),
(9141, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 32, 'OT', 'Nhưng một chi phái sẽ thuộc về người ấy, vì cớ tôi tớ ta là Đa-vít, và vì cớ Giê-ru-sa-lem, thành phố mà ta đã chọn giữa tất cả các chi phái của Y-sơ-ra-ên.'),
(9142, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 33, 'OT', 'Vì chúng đã lìa bỏ Ta, thờ lạy A-shtô-rét, nữ thần của người Xi-đôn, Kê-mô-sê, thần của người Mô-áp, và Mít-côm, thần của con cái Am-môn; chúng không đi theo các đường lối Ta, không làm điều ngay thẳng trước mắt Ta, không tuân giữ các luật lệ và mạng lịnh Ta như Đa-vít, cha người.'),
(9143, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 34, 'OT', 'Dẫu vậy, Ta sẽ không đoạt toàn bộ vương quốc khỏi tay người ấy; Ta sẽ để người ấy làm lãnh tụ suốt mọi ngày đời sống của người, vì cớ Đa-vít, đầy tớ Ta, người mà Ta đã chọn, và người đã giữ các điều răn và luật lệ Ta.'),
(9144, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 35, 'OT', 'Nhưng Ta sẽ đoạt lấy vương quốc khỏi tay con trai người ấy và ban cho ngươi, mười chi phái.'),
(9145, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 36, 'OT', 'Và cho con trai người, Ta sẽ ban cho một chi phái, để Đa-vít, tôi tớ Ta, luôn có ánh sáng trước mặt Ta tại Giê-ru-sa-lem, thành mà Ta đã chọn để đặt danh Ta tại đó.'),
(9146, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 37, 'OT', 'Ta sẽ chọn ngươi, ngươi sẽ trị vì theo mọi điều lòng ngươi ước ao, và ngươi sẽ làm vua trên Ít-ra-en.'),
(9147, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 38, 'OT', 'Nếu ngươi vâng theo mọi điều ta truyền cho ngươi, đi trong các đường lối ta, làm điều ngay thẳng trước mặt ta, để giữ các luật lệ và các điều răn của ta như Đa-vít, tôi tớ ta, đã làm; thì ta sẽ ở cùng ngươi, xây cho ngươi một nhà vững chắc như ta đã xây cho Đa-vít, và ban cho ngươi Ít-ra-en.'),
(9148, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 39, 'OT', 'Ta sẽ trừng phạt dòng dõi Đa-vít vì điều này, nhưng không suốt đời.'),
(9149, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 40, 'OT', 'Vua Sa-lô-môn tìm cách giết Giê-rô-bô-am. Nhưng Giê-rô-bô-am chỗi dậy, trốn sang Ai-cập cùng Si-sắc, vua Ai-cập, và ở đó cho đến khi vua Sa-lô-môn qua đời.'),
(9150, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 41, 'OT', 'Còn những việc khác của Sa-lô-môn, và tất cả những điều ông đã làm cùng sự khôn ngoan của ông, há chẳng phải đều đã chép trong sách Các Việc của Sa-lô-môn sao?'),
(9151, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 42, 'OT', 'Thời gian mà Sa-lô-môn trị vì tại Giê-ru-sa-lem trên toàn thể Ít-ra-en là bốn mươi năm.'),
(9152, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 11, 43, 'OT', 'Vua Sa-lô-môn nằm ngủ cùng các tổ phụ mình và được chôn trong thành Đa-vít, cha của người; rồi Rê-hô-bô-am, con trai người, lên ngôi làm vua thay cho người.'),
(9153, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 1, 'OT', 'Rê-hô-bô-am đi đến Si-chem, vì toàn thể Y-sơ-ra-ên đã đến Si-chem để tôn ông lên làm vua.'),
(9154, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 2, 'OT', 'Khi Giả-rô-bô-am, con trai của Nê-bát, đang còn ở Ai Cập, nghe tin ấy—vì người đã trốn khỏi mặt vua Sa-lô-môn và ở lại Ai Cập—'),
(9155, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 3, 'OT', 'Họ sai người đi và gọi ông ấy. Rồi Giê-rô-bô-am và toàn thể hội chúng Y-sơ-ra-ên đến, và nói với Rê-hô-bô-am rằng:'),
(9156, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 4, 'OT', 'Cha ngươi đã làm cho ách chúng tôi nặng nề; vậy bây giờ, hãy làm cho nhẹ bớt công việc nặng nề và ách nặng mà cha ngươi đã đặt trên chúng tôi, thì chúng tôi sẽ phục vụ ngươi.'),
(9157, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 5, 'OT', 'Hắn nói với họ: "Hãy đi thêm ba ngày nữa, rồi hãy trở lại cùng ta." Dân chúng liền đi.'),
(9158, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 6, 'OT', 'Vua Rê-hô-bô-am cùng các bậc lão thành, là những người từng phục vụ trước mặt Sa-lô-môn cha người khi người còn sống, và nói: "Các ngài nghĩ sao, tôi nên trả lời dân này điều gì?"'),
(9159, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 7, 'OT', 'Họ nói với ông rằng: "Nếu hôm nay ngài làm tôi tớ cho dân này, phục vụ họ, đáp lời họ, và nói những lời tốt đẹp với họ, thì suốt đời họ sẽ làm tôi tớ cho ngài."'),
(9160, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 8, 'OT', 'Nhưng người đã bỏ lời khuyên của các bậc lão thành mà họ đã khuyên người, và lại hỏi ý kiến những người trẻ tuổi đã lớn lên cùng người, và thường đứng trước mặt người.'),
(9161, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 9, 'OT', 'Người nói với họ: "Các ông nghĩ sao, để chúng ta trả lời dân này điều gì? Họ đã nói với ta rằng: ''Hãy làm nhẹ ách mà cha ngươi đã đặt trên chúng ta.''"'),
(9162, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 10, 'OT', 'Các thanh niên đã lớn lên cùng người ấy nói với người ấy rằng: "Ngươi phải nói với dân chúng này, là những kẻ đã nói cùng ngươi rằng: ''Cha ngươi đã làm cho ách chúng tôi nặng nề; bây giờ ngươi hãy làm cho nhẹ bớt trên chúng tôi'', ngươi phải nói như thế này với họ: ''Ngón út ta còn to hơn hông cha ta''."'),
(9163, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 11, 'OT', 'Và bây giờ, cha ta đã đặt trên các ngươi một ách nặng, còn ta sẽ gia tăng thêm ách của các ngươi; cha ta đã dùng roi mà răn phạt các ngươi, nhưng ta sẽ dùng roi bọ cạp mà răn phạt các ngươi.'),
(9164, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 12, 'OT', 'Vậy nên Giê-rô-bô-am và toàn thể dân chúng đến cùng Rê-hô-bô-am vào ngày thứ ba, như lời vua đã dặn rằng: "Hãy trở lại cùng ta vào ngày thứ ba."'),
(9165, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 13, 'OT', 'Vua đáp lại dân một cách gay gắt, và bỏ lời khuyên của các bậc lão thành mà họ đã khuyên vua.'),
(9166, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 14, 'OT', 'Người nói với họ theo lời khuyên của các thanh niên, rằng: "Cha ta đã làm cho ách các ngươi nặng, và ta sẽ làm cho ách các ngươi nặng thêm; cha ta đã sửa trị các ngươi bằng roi, nhưng ta sẽ sửa trị các ngươi bằng những chiếc bọ cạp."'),
(9167, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 15, 'OT', 'Vua không nghe theo dân chúng; vì điều đó do từ Đức Giê-hô-va, để ứng nghiệm lời Ngài đã phán qua A-hi-gia người Si-lô, cho Giê-rô-bô-am con trai của Nê-bát.'),
(9168, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 16, 'OT', 'Khi toàn thể Ít-ra-en thấy rằng vua chẳng nghe theo mình, thì dân chúng trả lời cho vua rằng: "Chúng tôi có phần chi trong Đa-vít đâu, chẳng hưởng được cơ nghiệp nào trong con trai của Y-sai. Hỡi Ít-ra-en, hãy về trại mình đi! Còn Đa-vít, bây giờ hãy lo cho nhà của ông ta!" Thế rồi Ít-ra-en đi về các trại của họ.'),
(9169, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 17, 'OT', 'Nhưng các con trai của Y-sơ-ra-ên sống trong các thành của Giu-đa, thì Rê-hô-bô-am cai trị trên họ.'),
(9170, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 18, 'OT', 'Vua Rê-ha-bâm sai A-đô-ram, người quản lý việc cống nạp, đi; và toàn thể Y-sơ-ra-ên đã ném đá người ấy cho đến chết. Vua Rê-ha-bâm vội vã lên xe mình để chạy trốn về Giê-ru-sa-lem.'),
(9171, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 19, 'OT', 'Vì vậy, Ít-ra-en đã phạm tội phản nghịch nhà Đa-vít cho đến ngày nay.'),
(9172, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 20, 'OT', 'Khi toàn thể Ít-ra-en nghe tin Giê-rô-bô-am đã trở về, thì họ sai người đi và gọi người ấy đến hội chúng, rồi phong người ấy làm vua cai trị toàn thể Ít-ra-en; không còn một ai theo nhà Đa-vít, ngoại trừ chi phái Giu-đa mà thôi.'),
(9173, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 21, 'OT', 'Vừa đến Giê-ru-sa-lem, Rê-ha-ba-am liền triệu tập toàn thể nhà Giu-đa và chi phái Bên-gia-min, tổng cộng một trăm tám mươi ngàn trai tráng tinh nhuệ, thiện chiến, để giao chiến với nhà Ít-ra-en, hầu khôi phục lại vương quyền cho Rê-ha-ba-am, con trai của Sa-lô-môn.'),
(9174, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 22, 'OT', 'Lời Đức Chúa Trời phán cùng Sê-ma-ia, một người của Đức Chúa Trời, rằng:'),
(9175, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 23, 'OT', 'Hãy nói cùng Rê-ha-bâm, con trai của Sa-lô-môn, vua xứ Giu-đa, và cùng cả nhà Giu-đa và Bên-gia-min, cùng phần còn lại của dân sự, rằng:'),
(9176, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 24, 'OT', 'Đức Giê-hô-va phán như vầy: "Ngươi chớ lên, cũng đừng chiến đấu cùng anh em ngươi là con cháu Y-sơ-ra-ên. Hãy trở về mỗi người nhà mình, vì điều nầy là từ nơi ta." Vậy, họ vâng theo lời Đức Giê-hô-va, và trở về không đi nữa theo lời Đức Giê-hô-va.'),
(9177, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 25, 'OT', 'Giê-rô-bô-am xây dựng Si-chem trên núi Ép-ra-im, rồi ở đó; người rời khỏi đó và xây dựng Phên-ù-ên.'),
(9178, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 26, 'OT', 'Rồi Giê-rô-bô-am nói trong lòng mình: "Bây giờ vương quốc sẽ trở về nhà Đa-vít."'),
(9179, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 27, 'OT', 'Nếu dân này lên làm lễ tế trong nhà Đức Giê-hô-va tại Giê-ru-sa-lem, thì lòng dân này sẽ trở lại cùng chủ mình, tức là về với Rê-hô-bô-am, vua Giu-đa, và họ sẽ giết tôi, rồi trở lại cùng Rê-hô-bô-am, vua Giu-đa.'),
(9180, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 28, 'OT', 'Vua bèn bàn luận và làm hai con bò vàng, rồi nói với họ rằng: "Đủ rồi cho các ngươi lên Giê-ru-sa-lem; này đây các thần của ngươi, hỡi Y-sơ-ra-ên, đã đưa ngươi lên khỏi đất Ê-díp-tô."'),
(9181, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 29, 'OT', 'Người đặt cái này tại Bê-thên, và cái kia Người đặt tại Đan.'),
(9182, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 30, 'OT', 'Việc ấy trở thành dịp phạm tội, vì dân chúng đi đến trước hình tượng kia, ngay cả đến Đan.'),
(9183, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 31, 'OT', 'Ông đã xây một ngôi đền trên các nơi cao, và chọn những thầy tế lễ từ những người thấp kém trong dân, những người không thuộc con cháu Lê-vi.'),
(9184, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 32, 'OT', 'Vua Yê-rob-ô-am lập một lễ hội vào tháng thứ tám, ngày rằm tháng ấy, giống như lễ hội ở Giu-đa, và người lên tế lễ trên bàn thờ; người làm như vậy tại Bê-tên để tế lễ cho những con bò con mà người đã làm, và người đặt tại Bê-tên các thầy tế lễ các nơi cao mà người đã lập.'),
(9185, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 12, 33, 'OT', 'Và người lên bàn thờ mà người đã làm tại Bê-tên vào ngày mười lăm của tháng thứ tám, trong tháng mà người đã tự ý nghĩ ra; và người cử hành một lễ cho con cái Ít-ra-en; và người lên bàn thờ để dâng của lễ thiêu.'),
(9186, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 1, 'OT', 'Kìa, một người của Đức Chúa Trời từ Giu-đa đến, theo lời của Đức Giê-hô-va, đến Bê-tên; và Giê-rô-bô-am đang đứng bên bàn thờ để dâng hương.'),
(9187, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 2, 'OT', 'Người kêu lên chống lại bàn thờ nhân danh Đức Giê-hô-va, và nói: "Hỡi bàn thờ, bàn thờ, Đức Giê-hô-va phán thế này: Kìa, một con trai sẽ sinh ra trong nhà Đa-vít, tên là Giô-si-a; người sẽ dâng trên ngươi các thầy tế lễ của các nơi cao, những kẻ đốt hương trên ngươi, và các xương người sẽ bị đốt trên ngươi."'),
(9188, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 3, 'OT', 'Ngày ấy, người đưa ra một dấu kỳ, nói rằng: "Đây là dấu kỳ mà Đức Giê-hô-va đã phán: Kìa, bàn thờ sẽ bị nứt ra, và đống tro trên nó sẽ đổ xuống."'),
(9189, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 4, 'OT', 'Khi vua Giê-rô-bô-am nghe lời của người của Đức Chúa Trời, người đã kêu lên chống lại bàn thờ tại Bê-tên, thì vua đưa tay ra từ trên bàn thờ, nói: "Hãy bắt lấy người ấy." Nhưng tay vua đưa ra chống lại người ấy liền khô lại, không thể rút về được.'),
(9190, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 5, 'OT', 'Bàn thờ cũng bị nứt ra, và tro đổ xuống từ bàn thờ, đúng như điềm mà người của Đức Chúa Trời đã đưa ra nhân danh lời của Đức Giê-hô-va.'),
(9191, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 6, 'OT', 'Vua đáp và nói với người của Đức Chúa Trời: "Xin hãy cầu xin Đức Giê-hô-va Đức Chúa Trời ngươi, và cầu thay cho tôi, để tay tôi được phục hồi lại tôi." Người của Đức Chúa Trời bèn cầu xin Đức Giê-hô-va, và tay vua được phục hồi lại cho vua, trở nên như trước.'),
(9192, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 7, 'OT', 'Vua nói với người của Đức Chúa Trời: "Hãy vào nhà với ta, và hãy ăn uống cho thêm sức lực; ta sẽ ban cho ngươi một phần thưởng."'),
(9193, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 8, 'OT', 'Người của Đức Chúa Trời nói với vua: "Dù ngài có cho tôi phân nửa ngôi nhà của ngài, tôi cũng sẽ không đi theo ngài, cũng sẽ không ăn bánh hay uống nước tại nơi này."'),
(9194, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 9, 'OT', 'Vì Đức Giê-hô-va đã truyền cho tôi qua lời của Ngài rằng: "Ngươi không được ăn bánh, không được uống nước, và không được quay trở lại bằng con đường ngươi đã đi."'),
(9195, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 10, 'OT', 'Ông đi theo một con đường khác, và không trở lại bằng con đường mà ông đã dùng để đến Bê-tên.'),
(9196, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 11, 'OT', 'Và có một đấng tiên tri già sống ở Bê-tên; các con trai ông đến và thuật lại cho ông mọi việc mà người của Đức Chúa Trời đã làm trong ngày đó tại Bê-tên, và các lời mà người ấy đã nói với vua; chúng cũng thuật lại các lời ấy cho cha mình.'),
(9197, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 12, 'OT', 'Người cha hỏi họ: "Người của Đức Chúa Trời đến từ Giu-đa đi đường nào?" Các con trai ông thấy con đường mà người của Đức Chúa Trời đã đi.'),
(9198, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 13, 'OT', 'Bấy giờ người nói với các con trai: "Hãy tra lừa cho ta." Vậy chúng tra lừa cho người, và người cỡi lên đi.'),
(9199, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 14, 'OT', 'Ông đi theo người của Đức Chúa Trời, và thấy người ấy đang ngồi dưới một cây sồi; ông nói với người ấy: "Ông có phải là người của Đức Chúa Trời, Đấng đã đến từ Giu-đa không?" Người ấy đáp: "Đúng vậy."'),
(9200, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 15, 'OT', 'Hắn nói với người ấy: "Hãy đi về nhà với tôi và ăn bánh."'),
(9201, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 16, 'OT', 'Người nói: Tôi không thể trở về với ông, cũng không thể đi cùng ông; tôi cũng sẽ không ăn bánh hay uống nước với ông tại nơi này:'),
(9202, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 17, 'OT', 'Vì Đức Giê-hô-va đã phán với tôi qua lời của Ngài: Ngươi sẽ không được ăn bánh, cũng không được uống nước tại nơi đó, và không được trở lại đi bằng con đường mà ngươi đã đi đến.'),
(9203, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 18, 'OT', 'Người ấy nói với ông: "Tôi cũng là một đấng tiên tri như ông, và một thiên sứ đã phán cùng tôi bởi lời của Đức Giê-hô-va rằng: ''Hãy đưa người ấy trở lại nhà ngươi, để người ấy ăn bánh và uống nước.''" Nhưng người ấy đã nói dối ông.'),
(9204, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 19, 'OT', 'Ông ấy trở về cùng người đó, ăn bánh trong nhà người ấy và uống nước.'),
(9205, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 20, 'OT', 'Và xảy ra rằng, khi họ đang ngồi tại bàn ăn, thì có lời của Đức Giê-hô-va phán cùng đấng tiên tri đã đưa người ấy trở về.'),
(9206, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 21, 'OT', 'Người ấy kêu lên cùng người của Đức Chúa Trời, là người đã đến từ Giu-đa, mà nói rằng: Đức Giê-hô-va phán như vầy: "Vì ngươi đã không vâng theo lời Đức Giê-hô-va, và không giữ điều răn mà Đức Giê-hô-va Đức Chúa Trời ngươi đã truyền cho ngươi,"'),
(9207, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 22, 'OT', 'Nhưng ngươi đã trở lại, ăn bánh và uống nước tại nơi mà Ngài phán cùng ngươi: "Chớ ăn bánh, chớ uống nước." Xác ngươi sẽ không được chôn vào mồ mả tổ phụ ngươi.'),
(9208, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 23, 'OT', 'Sau khi người ấy ăn bánh và uống xong, thì người đã dắt lừa đến cho nhà tiên tri mà ông đã đưa trở lại, và đặt cương lên lừa ấy.'),
(9209, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 24, 'OT', 'Người ấy đi, và một con sư tử gặp người ấy trên đường, giết người ấy; thân thể người ấy bị quăng xuống đường, còn lừa thì đứng bên cạnh, và sư tử cũng đứng bên cạnh xác người ấy.'),
(9210, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 25, 'OT', 'Này, có những người đi ngang qua, thấy xác người ấy bị quăng ra giữa đường và sư tử đang đứng cạnh xác; họ đến và thuật lại trong thành, nơi đấng tiên tri già sống.'),
(9211, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 26, 'OT', 'Vị tiên tri đã gọi ông trở lại từ con đường, khi nghe tin ấy, liền nói: "Chính ông ấy là người của Đức Chúa Trời, người đã chống nghịch mạng lịnh của Đức Giê-hô-va; nên Đức Giê-hô-va đã trao ông ấy cho sư tử, và sư tử đã xé xác và giết ông ấy, y như lời Đức Giê-hô-va đã phán cùng ông ấy."'),
(9212, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 27, 'OT', 'Người nói với các con trai mình rằng: "Hãy xăm lừa cho ta." Và họ liền xăm lừa.'),
(9213, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 28, 'OT', 'Người ấy đi và thấy xác người của ông bị ném ra giữa đường, còn lừa và sư tử thì đứng bên xác; sư tử không ăn xác người ấy, cũng không xé xác con lừa.'),
(9214, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 29, 'OT', 'Người tiên tri nâng xác người của Đức Chúa Trời lên, đặt trên lừa và đem về; rồi đến thành của vị tiên tri già để than khóc và chôn cất người ấy.'),
(9215, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 30, 'OT', 'Người ta đặt xác chết của ông vào ngôi mộ của chính ông; và họ khóc than ông, rằng: "Than ôi, anh tôi!"'),
(9216, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 31, 'OT', 'Sau khi chôn ông rồi, người ấy nói với các con mình rằng: "Khi ta chết, hãy chôn ta trong mồ mà người của Đức Chúa Trời đã được chôn ở đó; hãy đặt xương ta bên cạnh xương ông ấy."'),
(9217, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 32, 'OT', 'Vì lời ấy mà ông đã công bố nhân danh Đức Giê-hô-va nghịch cùng bàn thờ tại Bê-tên và nghịch cùng mọi ngôi nhà các nơi cao ở các thành xứ Sa-ma-ri, chắc chắn sẽ ứng nghiệm.'),
(9218, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 33, 'OT', 'Sau việc ấy, Giê-rô-bô-am không trở lại từ con đường xấu xa của mình, mà lại tiếp tục lập từ những người trong dân chúng làm thầy tế lễ các nơi cao; bất cứ ai muốn, người đó sẽ được bổ nhiệm và trở thành thầy tế lễ các nơi cao.'),
(9219, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 13, 34, 'OT', 'Việc này đã trở thành tội lỗi cho nhà Giê-rô-bô-am, dẫn đến sự tiêu diệt và quét sạch họ khỏi mặt đất.'),
(9220, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 14, 1, 'OT', 'Vào thời ấy, A-bi-gia, con trai của Giê-rô-bô-am, bị bệnh.'),
(9221, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 14, 2, 'OT', 'Và Giê-rô-bô-am nói với vợ mình: "Hãy chỗi dậy, hãy cải trang, để người ta không nhận biết ngươi là vợ của Giê-rô-bô-am, rồi đi đến Si-lô; nầy, tại đó có A-hi-gia đấng tiên tri, chính người đã nói về ta rằng: ''Ngươi sẽ làm vua cai trị dân nầy.''"'),
(9222, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 14, 3, 'OT', 'Hãy lấy trong tay ngươi mười ổ bánh, những món ăn nhẹ và một bầu mật ong, rồi đi đến cùng người ấy; chính người ấy sẽ nói cho ngươi biết điều gì sẽ xảy ra với đứa trẻ.'),
(9223, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 14, 4, 'OT', 'Vợ của Giê-rô-bô-am làm như vậy, đứng dậy và đi đến Si-lô, rồi vào nhà A-hi-gia. Nhưng A-hi-gia không thể thấy được, vì mắt ông đã mờ do tuổi già.'),
(9224, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 14, 5, 'OT', 'Đức Giê-hô-va phán cùng A-hi-gia rằng: "Nầy, vợ của Giê-rô-bô-am đang đến để hỏi ngươi về con trai mình, vì nó đang đau yếu. Ngươi hãy nói với bà ấy như thế này và như thế kia. Khi bà ấy vào, thì bà ấy sẽ giả dạng như một người đàn bà khác."'),
(9225, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 14, 6, 'OT', 'Khi A-hi-gia vừa nghe tiếng bước chân bà ấy vào cửa, thì nói rằng: "Hãy vào đi, hỡi vợ Giê-rô-bô-am! Sao bà phải giả dạng? Chính ta đây được sai đến bà với tin dữ."'),
(9226, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 14, 7, 'OT', 'Hãy đi, bảo Giê-rô-bô-am: Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên phán như vầy: "Vì ta đã nâng ngươi lên từ giữa dân chúng, và đặt ngươi làm lãnh tụ cai trị trên dân ta là Y-sơ-ra-ên,'),
(9227, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 14, 8, 'OT', 'Ta đã xé vương quốc khỏi nhà Đa-vít và ban cho ngươi; nhưng ngươi đã không như đầy tớ Ta là Đa-vít, người đã giữ các điều răn của Ta, và đã theo Ta trọn lòng, để làm điều ngay thẳng trước mặt Ta.'),
(9228, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 14, 9, 'OT', 'Nhưng ngươi đã làm điều ác hơn tất cả những người trước ngươi: ngươi đã đi và làm các thần khác cùng các tượng đúc để làm ta nổi giận, và ngươi đã ném ta ra phía sau lưng ngươi.'),
(9229, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 14, 10, 'OT', 'Vì vậy, nầy, ta sẽ giáng họa lên nhà Giê-rô-bô-am, và ta sẽ diệt sạch dòng dõi Giê-rô-bô-am, từ kẻ nào đi tiểu bên vách cho đến kẻ bị bỏ lại và cô lập trong Ít-ra-en; ta sẽ quét sạch nhà Giê-rô-bô-am như người ta quét sạch phân cho đến khi không còn gì hết.'),
(9230, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 14, 11, 'OT', 'Người nào chết thuộc về Giê-rô-bô-am trong thành, chó sẽ ăn; người nào chết ngoài đồng, chim trời sẽ ăn: vì Đức Giê-hô-va đã phán.'),
(9231, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 14, 12, 'OT', 'Hãy đứng dậy, trở về nhà ngươi; ngay khi ngươi bước chân vào thành, đứa trẻ sẽ chết.'),
(9232, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 14, 13, 'OT', 'Toàn thể Y-sơ-ra-ên sẽ khóc than cho người, và chôn cất người; vì chỉ có mình người là được chôn trong phần mộ của Giê-rô-bô-am, bởi người được tìm thấy điều thiện lành trước mặt Đức Giê-hô-va, Đức Chúa Trời của Y-sơ-ra-ên, trong nhà Giê-rô-bô-am.'),
(9233, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 14, 14, 'OT', 'Đức Giê-hô-va sẽ lập một vua cai trị trên Ít-ra-en, người sẽ tiêu diệt nhà Giê-rô-bô-am trong ngày nay; và hơn thế nữa, ngay lúc này.'),
(9234, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 14, 15, 'OT', 'Đức Giê-hô-va sẽ đánh dẹp Y-sơ-ra-ên như cây sậy bị lay động trong nước; Ngài sẽ nhổ Y-sơ-ra-ên ra khỏi đất tốt lành nầy, mà Ngài đã ban cho tổ tiên họ, và sẽ tản lạc họ qua bên kia sông, vì họ đã dựng các hình tượng thần tượng, khiến Đức Giê-hô-va nổi giận.'),
(9235, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 14, 16, 'OT', 'Người sẽ phó cho Y-sơ-ra-ên vì những tội lỗi của Giê-rô-bô-am, kẻ đã phạm tội và khiến Y-sơ-ra-ên phạm tội.'),
(9236, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 14, 17, 'OT', 'Vợ của Giê-rô-bô-am đứng dậy, đi lên và vào thành Tít-ra; khi bà vừa đến cửa nhà thì đứa trẻ qua đời.'),
(9237, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 14, 18, 'OT', 'Họ chôn cất người, và toàn thể Y-sơ-ra-ên để tang cho người, theo lời của Đức Giê-hô-va mà Ngài đã phán qua tay đầy tớ Ngài, là nhà tiên tri A-ki-a.'),
(9238, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 14, 19, 'OT', 'Còn các việc khác của Giê-rô-bô-am, những điều người đã chiến đấu và những điều người đã làm khi trị vì, đều được chép trong sách Các sự việc hàng ngày đời các vua Y-sơ-ra-ên.'),
(9239, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 14, 20, 'OT', 'Thời gian Giê-rô-bô-am trị vì là hai mươi hai năm; rồi người nằm ngủ cùng các tổ phụ mình, và Na-đáp, con trai người, lên ngôi kế vị.'),
(9240, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 14, 21, 'OT', 'Rê-hô-bô-am, con trai của Sa-lô-môn, trị vì trên nước Giu-đa. Rê-hô-bô-am được bốn mươi mốt tuổi khi người bắt đầu trị vì, và người trị vì mười bảy năm tại Giê-ru-sa-lem, thành mà Đức Giê-hô-va đã chọn từ giữa mọi chi phái của Y-sơ-ra-ên để đặt danh Ngài tại đó. Tên mẹ người là Na-a-ma, người Am-môn.'),
(9241, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 14, 22, 'OT', 'Giu-đa làm điều ác trước mặt Đức Giê-hô-va, và họ khiến Ngài ghen tức vì những tội lỗi mà họ đã phạm, hơn tất cả những điều tổ tiên họ đã làm.'),
(9242, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 14, 23, 'OT', 'Họ cũng xây cho mình các nơi cao, các trụ thờ, và các tượng thần Asherah trên mọi ngọn đồi cao và dưới mọi cây xanh tươi.'),
(9243, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 14, 24, 'OT', 'Vả lại, cũng có kẻ nam sắc dâm cho đền miếu trong đất; chúng làm mọi điều gớm ghê như các dân tộc mà Đức Giê-hô-va đã đuổi ra khỏi trước mặt con cái Y-sơ-ra-ên.'),
(9244, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 14, 25, 'OT', 'Vào năm thứ năm đời vua Rê-hô-bô-am, thì Sô-sác, vua Ê-díp-tô, lên đánh Giê-ru-sa-lem.'),
(9245, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 14, 26, 'OT', 'Và người lấy các kho báu trong nhà Đức Giê-hô-va, và các kho báu trong nhà vua; người lấy hết thảy, và lấy các cái khiên bằng vàng mà Sa-lô-môn đã làm.'),
(9246, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 14, 27, 'OT', 'Vua Rê-hô-bô-am làm thay thế cho chúng những cái khiên bằng đồng, và giao chúng vào tay các quan cai trị vệ binh, là những người canh giữ cửa nhà vua.'),
(9247, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 14, 28, 'OT', 'Mỗi khi vua vào đền thờ Đức Giê-hô-va, các vệ binh sẽ khiêng chúng và mang trở lại phòng các vệ binh.'),
(9248, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 14, 29, 'OT', 'Còn những việc khác của Rê-ha-ba-am và tất cả những điều ông đã làm, há chẳng chép trong sách Các sự việc trong các ngày của các vua Giu-đa sao?'),
(9249, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 14, 30, 'OT', 'Và có chiến tranh giữa Rê-hô-bô-am và Giê-rô-bô-am suốt mọi ngày đời của họ.'),
(9250, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 14, 31, 'OT', 'Rê-ha-bô-am nằm nghỉ cùng các tổ tiên mình và được chôn cùng các tổ tiên mình trong thành Đa-vít. Tên mẹ người là Na-a-ma, người Am-môn. A-bi-gia, con trai người, lên ngôi làm vua thay cho người.'),
(9251, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 1, 'OT', 'Trong năm thứ mười tám đời vua Giê-rô-bô-am, con trai của Nê-bát, thì A-bi-giam lên ngôi vua cai trị trên Giu-đa.'),
(9252, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 2, 'OT', 'Ông trị vì tại Giê-ru-sa-lem ba năm. Tên mẹ ông là Ma-a-ca, con gái của Áp-sa-lôm.'),
(9253, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 3, 'OT', 'Và người đi theo mọi tội lỗi mà cha mình đã làm trước mặt người; và lòng người không trọn vẹn với Đức Giê-hô-va Đức Chúa Trời của người, như lòng Đa-vít, cha người.'),
(9254, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 4, 'OT', 'Nhưng vì Đa-vít, Đức Giê-hô-va Đức Chúa Trời của người đã ban cho người một ngọn đèn tại Giê-ru-sa-lem, để lập con trai người lên kế vị sau người và để củng cố Giê-ru-sa-lem.'),
(9255, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 5, 'OT', 'Đa-vít đã làm điều ngay thẳng trong mắt Đức Giê-hô-va, và không xây bỏ mọi điều Đức Giê-hô-va truyền cho ông trọn những ngày đời ông, ngoại trừ việc liên can đến U-ri người Hê-th.'),
(9256, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 6, 'OT', 'Và có chiến tranh giữa Rê-hô-bô-am và Giê-rô-bô-am suốt mọi ngày trong đời sống của người ấy.'),
(9257, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 7, 'OT', 'Còn các việc khác của A-bi-giam và mọi điều ông làm, há chẳng chép trong sách Các Việc Kỷ Niên của các vua Giu-đa sao? Và có chiến tranh xảy ra giữa A-bi-giam và Giả-rô-bô-am.'),
(9258, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 8, 'OT', 'A-bi-a ngủ cùng các tổ tiên mình; người ta mai táng ông trong thành của Đa-vít. A-sa, con trai ông, lên ngôi vua thế ông.'),
(9259, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 9, 'OT', 'Bảy năm thứ hai mươi đời Giê-rô-bô-am, vua nước Ít-ra-en, thì A-xa lên làm vua nước Giu-đa.'),
(9260, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 10, 'OT', 'Bốn mươi mốt năm, người cai trị tại Giê-ru-sa-lem. Tên mẹ người là Ma-a-ca, con gái của Áp-sa-lôm.'),
(9261, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 11, 'OT', 'Vua A-sa làm điều ngay thẳng trước mặt Đức Giê-hô-va, giống như Đa-vít cha ông.'),
(9262, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 12, 'OT', 'Ông dẹp bỏ các hình tượng khiêu dâm khỏi đất nước và gỡ bỏ mọi hình tượng gớm ghiếc mà các tổ tiên ông đã làm.'),
(9263, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 13, 'OT', 'Và Ma-cha, mẹ vua, cũng bị vua phế khỏi chức thái hậu, vì bà đã làm một hình tượng gớm ghiếc cho Át-tơ-ra; vua A-sa đập phá hình tượng gớm ghiếc của bà và thiêu đốt nó bên suối Ki-trôn.'),
(9264, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 14, 'OT', 'Những nơi thờ thần trên các nơi cao thì không bị bỏ đi; nhưng lòng của A-sa vẫn trung thành với Đức Giê-hô-va trọn mọi ngày đời người.'),
(9265, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 15, 'OT', 'Vua A-ram đưa vào đền thờ Đức Giê-hô-va những vật thánh mà cha người đã biệt riêng ra, và những vật thánh mà chính người đã biệt riêng ra, gồm bạc, vàng và các đồ dùng.'),
(9266, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 16, 'OT', 'Có chiến tranh giữa A-sa và Ba-a-sa, vua Y-sơ-ra-ên, trong suốt mọi ngày đời của họ.'),
(9267, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 17, 'OT', 'Vua Ba-a-sa của Ít-ra-en đi lên nghịch cùng Giu-đa, và xây dựng Ra-ma, để không cho phép ai ra vào với vua A-sa của Giu-đa.'),
(9268, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 18, 'OT', 'A-xa lấy tất cả bạc và vàng còn sót lại trong các kho báu của đền thờ Đức Giê-hô-va và các kho báu trong cung điện vua, rồi trao vào tay các đầy tớ mình; và vua A-xa sai họ đến Bên-ha-đác, con trai của Ta-bri-môn, con trai của Hê-xi-ôn, vua nước Sy-ri, là người đang ở tại Đa-mách, mà nói rằng:'),
(9269, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 19, 'OT', 'Có một giao ước giữa ta và ngươi, giữa cha ta và cha ngươi. Nầy, ta đã sai đến cho ngươi một món quà là bạc và vàng. Hãy đến, phá giao ước của ngươi với Ba-a-sa, vua Y-sơ-ra-ên, để người ấy rút lui khỏi ta.'),
(9270, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 20, 'OT', 'Bên-ha-đát nghe theo vua A-sa, và sai các quan trưởng quân đội mình đi đánh các thành của Y-sơ-ra-ên; người đánh chiếm I-ôn, Đan, A-bên Bết-Ma-a-ca, và toàn thể Kinh-nết, cùng toàn bộ đất Na-ph-ta-li.'),
(9271, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 21, 'OT', 'Khi Ba-a-sa nghe tin ấy, thì người thôi việc xây cất Ra-ma, và ở tại Tít-sa.'),
(9272, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 22, 'OT', 'Vua A-sa truyền lệnh trong toàn thể Giu-đa, không ai được miễn; họ bèn khiêng đi những tảng đá và gỗ tại Ra-ma, mà Ba-a-sa đã dùng để xây cất; vua A-sa dùng những vật ấy xây cất Ghê-ba thuộc Bên-gia-min và Mít-pah.'),
(9273, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 23, 'OT', 'Còn các việc khác của A-sa, mọi sức mạnh người làm, mọi việc người thực hiện, các thành người xây dựng, há chẳng chép trong sách Các Việc Làm Hằng Ngày của các vua Giu-đa sao? Nhưng đến thời tuổi già, người bị bệnh ở đôi chân mình.'),
(9274, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 24, 'OT', 'A-sa nằm nghỉ cùng các tổ phụ mình và được chôn cùng các tổ phụ mình trong thành Đa-vít, cha ông; và Giê-hô-sa-phát, con trai ông, lên ngôi kế vị ông.'),
(9275, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 25, 'OT', 'Na-đáp, con trai của Giê-rô-bô-am, làm vua trên Ít-ra-en trong năm thứ hai đời A-sa, vua Giu-đa; người cai trị trên Ít-ra-en hai năm.'),
(9276, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 26, 'OT', 'Vua ấy làm điều ác trước mặt Đức Giê-hô-va, đi theo con đường của cha mình, và trong tội lỗi mà cha mình đã khiến cho dân Y-sơ-ra-ên phạm tội.'),
(9277, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 27, 'OT', 'Bấy giờ Ba-a-sa, con trai A-hi-gia, thuộc nhà Y-xa-sác, lập mưu nghịch cùng người; và Ba-a-sa đánh giết người tại Ghíp-tho, là thành thuộc về người Phi-li-tin; lúc ấy Na-đáp và toàn thể Y-sơ-ra-ên đang vây hãm Ghíp-tho.'),
(9278, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 28, 'OT', 'Ba-xa giết người ấy trong năm thứ ba đời A-sa, vua xứ Giu-đa, rồi lên ngôi thay cho người ấy.'),
(9279, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 29, 'OT', 'Khi người lên ngôi vua, người giết hết toàn thể nhà Giê-rô-bô-am; người không để lại cho Giê-rô-bô-am một ai còn sống, cho đến khi tiêu diệt sạch, y như lời Đức Giê-hô-va đã phán qua tôi tớ Ngài là A-hi-gia người Si-lô.'),
(9280, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 30, 'OT', 'Bởi các tội lỗi của Giê-rô-bô-am mà người đã phạm và khiến cho Ít-ra-en phạm tội, cùng cơn thịnh nộ mà người đã khiến Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en nổi giận.'),
(9281, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 31, 'OT', 'Còn các việc khác của Na-đáp và mọi điều ông làm, há chẳng chép trong sách Các niên kỷ về các vua Y-sơ-ra-ên sao?'),
(9282, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 32, 'OT', 'Và có chiến tranh giữa A-sa và Ba-a-sa, vua của Y-sơ-ra-ên, trong suốt mọi ngày đời của họ.'),
(9283, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 33, 'OT', 'Năm thứ ba đời vua A-sa nước Giu-đa, Ba-a-sa con trai A-hi-ya lên làm vua cai trị toàn thể Y-sơ-ra-ên tại Tít-sanh, trị vì hai mươi bốn năm.'),
(9284, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 15, 34, 'OT', 'Và người làm điều ác trước mặt Đức Giê-hô-va, và đi theo con đường của Giê-rô-bô-am, và trong tội lỗi mà người đã khiến cho Ít-ra-en phạm tội.'),
(9285, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 1, 'OT', 'Lời của Đức Giê-hô-va phán cùng Giê-hu, con trai của Ha-na-ni, nghịch cùng Ba-a-sa, rằng:'),
(9286, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 2, 'OT', 'Vì Ta đã nâng ngươi từ bụi đất lên, đặt ngươi làm người cai trị trên dân Ta là Y-sơ-ra-ên, nhưng ngươi đã đi theo đường lối của Giê-rô-bô-am, khiến dân Ta là Y-sơ-ra-ên phạm tội, làm Ta nổi giận vì tội lỗi họ.'),
(9287, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 3, 'OT', 'Nầy, Ta sẽ khiến cho dòng dõi của Ba-a-sa và dòng dõi nhà nó bị tiêu diệt; và Ta sẽ khiến cho nhà ngươi trở nên như nhà của Giê-rô-bô-am, con trai của Nê-bát.'),
(9288, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 4, 'OT', 'Ai chết trong thành thuộc về Ba-a-sa sẽ bị chó ăn; ai chết ngoài đồng thuộc về người ấy sẽ bị chim trời ăn.'),
(9289, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 5, 'OT', 'Phần còn lại của các việc Ba-a-sa đã làm, và những điều ông thực hiện, cùng quyền năng của ông, há chẳng ghi chép trong sách Các Sự Việc Hằng Năm của các vua Y-sơ-ra-ên sao?'),
(9290, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 6, 'OT', 'Ba-asha nằm xuống cùng với tổ tiên mình và được chôn cất tại Tiệt-sa. Ê-la, con trai ông, lên ngôi làm vua thay cho ông.'),
(9291, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 7, 'OT', 'Đức Giê-hô-va cũng dùng tay của Giê-hu, con trai của Ha-nan, là đấng tiên tri, để phán nghịch lại Ba-a-sa và nghịch lại nhà người, vì mọi điều ác mà người đã làm trong mắt Đức Giê-hô-va, khiến Ngài nổi giận vì những việc tay người làm, khiến người trở nên như nhà của Giê-rô-bô-am; và vì người đã giết người ấy.'),
(9292, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 8, 'OT', 'Trong năm hai mươi sáu đời vua A-sa nước Giu-đa, Ê-la con trai của Ba-a-sa lên làm vua cai trị trên Ít-ra-en tại Tít-sa, trong hai năm.'),
(9293, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 9, 'OT', 'Tôi tớ của ông, Xim-ri, chỉ huy một nửa đạo quân xe ngựa, đã lập mưu nghịch ông, khi ông đang ở Tiệt-sa, uống rượu say trong nhà Arza, quản gia của cung điện tại Tiệt-sa.'),
(9294, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 10, 'OT', 'Xim-ri đi vào, đánh và giết người ấy, trong năm thứ hai mươi bảy đời vua A-sa, vua Giu-đa, rồi lên ngôi kế vị người.'),
(9295, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 11, 'OT', 'Khi vừa lên ngôi, ngay lúc ngồi trên ngôi báu của mình, thì người đã đánh giết trọn nhà Ba-a-sa; người không để lại cho hắn một ai có thể tiểu tiện được, cũng không để lại người thân hay bạn hữu nào của hắn.'),
(9296, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 12, 'OT', 'Xim-ri tiêu diệt toàn bộ nhà của Ba-a-sa, y như lời Đức Giê-hô-va đã phán nghịch cùng Ba-a-sa bởi đấng tiên tri Giê-hu.'),
(9297, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 13, 'OT', 'Vì mọi tội lỗi của Ba-a-sa và các tội lỗi của Ê-la, con trai người, mà họ đã phạm và khiến cho Ít-ra-en phạm tội, làm cho Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en nổi giận bằng những điều hư không của chúng.'),
(9298, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 14, 'OT', 'Còn những việc khác của Ê-la và tất cả những điều người làm, há chẳng có chép trong sách Các sự việc ngày xưa của các vua Y-sơ-ra-ên sao?'),
(9299, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 15, 'OT', 'Năm thứ hai mươi bảy đời vua A-sa nước Giu-đa, Xim-ri trị vì bảy ngày tại Tít-sa. Dân chúng đang đóng trại vây thành Ghíp-bê-tôn thuộc về người Phi-li-tin.'),
(9300, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 16, 'OT', 'Dân chúng đang đóng trại nghe đồn rằng: "Xim-ri đã phản loạn và còn giết cả vua nữa!" Vậy nên toàn thể Y-sơ-ra-ên đã tôn O-mê-ri, viên tướng chỉ huy quân đội, lên làm vua trên Y-sơ-ra-ên trong ngày đó tại trại quân.'),
(9301, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 17, 'OT', 'Om-ri và toàn thể Y-sơ-ra-ên đi lên khỏi Ghíp-bê-thôn, và họ vây hãm Tiếc-xa.'),
(9302, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 18, 'OT', 'Và xảy ra khi Xim-ri thấy thành đã bị chiếm, thì người vào cung điện trong nhà vua, và phóng hỏa thiêu đốt nhà vua, rồi chết.'),
(9303, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 19, 'OT', 'Vì tội lỗi mà ông phạm, khi làm điều ác trước mặt Đức Giê-hô-va, khi đi theo con đường của Giê-rô-bô-am, và vì tội lỗi mà ông đã làm khiến cho Ít-ra-en phạm tội.'),
(9304, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 20, 'OT', 'Phần còn lại của các việc của Xim-ri và âm mưu mà người đã thực hiện, há chẳng được chép trong sách Các Việc Hằng Năm của các vua Y-sơ-ra-ên sao?'),
(9305, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 21, 'OT', 'Bấy giờ, dân Y-sơ-ra-ên chia làm hai phần; một nửa dân theo Thi-bni, con trai của Gi-nát, để tôn người lên làm vua; và một nửa kia theo Ôm-ri.'),
(9306, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 22, 'OT', 'Dân chúng đi theo Om-ri mạnh hơn dân chúng đi theo Tin-bi, con trai của Gin-tha; Tin-bi qua đời, và Om-ri lên làm vua.'),
(9307, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 23, 'OT', 'Năm thứ ba mươi mốt đời vua A-sa nước Giu-đa, Ôm-ri lên làm vua trên Ít-ra-en được mười hai năm; người trị vì sáu năm tại thành Tít-sa.'),
(9308, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 24, 'OT', 'Ông mua núi Sa-ma-ri-a của Sêm với hai ta-lâng bạc, rồi xây trên núi đó, và đặt tên thành phố mà ông xây theo tên Sêm, chủ núi, là Sa-ma-ri-a.'),
(9309, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 25, 'OT', 'Ông Ôm-ri làm điều ác trước mặt Đức Giê-hô-va, và làm điều ác hơn tất cả những người đã sống trước ông.'),
(9310, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 26, 'OT', 'Người đi theo mọi con đường của Giê-rô-bô-am, con trai của Nê-bát, và trong tội lỗi mà người đó đã phạm khiến cho dân Ít-ra-en vấp phạm, để làm cho Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en nổi giận bởi những điều hư không của chúng.'),
(9311, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 27, 'OT', 'Còn việc khác của Ôm-ri mà người đã làm, cùng sức mạnh mà người đã thi thố, thì chẳng phải đã chép trong sách Các Việc Làm Hằng Ngày của các vua Ít-ra-en sao?'),
(9312, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 28, 'OT', 'Ôm-ri nằm nghỉ cùng với tổ tiên mình và được chôn cất tại Sa-ma-ri; A-háp, con trai ông, lên ngôi vua thay cho ông.'),
(9313, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 29, 'OT', 'A-háp, con trai của Ôm-ri, lên ngôi làm vua trên Ít-ra-en trong năm thứ ba mươi tám đời vua A-sa, vua của Giu-đa; và A-háp, con trai của Ôm-ri, trị vì trên Ít-ra-en tại Sa-ma-ri hai mươi hai năm.'),
(9314, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 30, 'OT', 'A-háp, con trai của Ôm-ri, làm điều ác trước mặt Đức Giê-hô-va hơn tất cả những người trước ông.'),
(9315, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 31, 'OT', 'Vả lại, điều đó vẫn coi là nhẹ đối với người ấy khi đi trong tội lỗi của Giê-rô-bô-am, con trai của Nê-bát; người ấy đã lấy vợ là Ít-chê-bên, con gái của Êt-ba-ên, vua của dân Xi-đôn, rồi đi phục vụ Ba-anh và cúi lạy người ấy.'),
(9316, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 32, 'OT', 'Và người lập một bàn thờ cho Ba-al trong đền thờ của Ba-al, mà người đã xây tại Sa-ma-ri.'),
(9317, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 33, 'OT', 'A-háp dựng nên cây thờ A-sê-ra; A-háp còn làm nhiều điều nữa để làm giận Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en, hơn tất cả các vua Ít-ra-en trước người.'),
(9318, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 16, 34, 'OT', 'Trong những ngày của người ấy, Hiel người Bê-thên đã xây dựng lại Giê-ri-cô: người đặt nền móng thành ấy trên A-bi-ram, con trai đầu lòng của mình, và dựng cổng thành ấy trên Sê-gíp, con trai út mình, y như lời Đức Giê-hô-va đã phán qua Giô-suê, con trai của Nun.'),
(9319, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 17, 1, 'OT', 'Ê-li-a, người Thi-bê-ri, thuộc nhóm người sống ở Gi-lean, nói với A-háp: "Đức Giê-hô-va, Đức Chúa Trời của Ít-ra-en, là Đấng tôi đang đứng trước mặt Ngài, thật sống, tôi xin nói rằng trong những năm nầy sẽ không có sương hay mưa, ngoại trừ theo lời tôi nói."'),
(9320, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 17, 2, 'OT', 'Lời của Đức Giê-hô-va phán cùng người rằng:'),
(9321, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 17, 3, 'OT', 'Hãy đi từ đây, quay về hướng đông và ẩn mình bên dòng suối Xê-rit, là dòng suối ở phía trước sông Giô-đanh.'),
(9322, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 17, 4, 'OT', 'Ngươi sẽ uống nước từ dòng suối; và Ta đã truyền cho những con quạ nuôi sống ngươi tại đó.'),
(9323, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 17, 5, 'OT', 'Ông đi và làm theo lời của Đức Giê-hô-va; ông đi và ở bên dòng suối Kê-rít, là dòng suối đối diện với sông Giô-đanh.'),
(9324, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 17, 6, 'OT', 'Quạ mang đến cho ông bánh và thịt vào buổi sáng và bánh và thịt vào buổi tối; còn ông thì uống nước từ dòng suối.'),
(9325, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 17, 7, 'OT', 'Sau một thời gian, dòng nước liền cạn khô, vì không có mưa trên đất.'),
(9326, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 17, 8, 'OT', 'Lời Đức Giê-hô-va phán cùng người rằng:'),
(9327, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 17, 9, 'OT', 'Hãy chỗi dậy, đi đến Xa-rép-hát thuộc Xít-đôn, và ở đó; nầy, Ta đã truyền cho một người đàn bà góa ở đó nuôi sống ngươi.'),
(9328, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 17, 10, 'OT', 'Ông liền chỗi dậy, đi đến Xa-rép-thát. Khi ông đến cổng thành thì thấy ở đó một người đàn bà góa đang nhóm củi. Ông gọi bà ấy và nói: "Xin bà hãy lấy ít nước trong cái bình mà đưa cho tôi uống."'),
(9329, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 17, 11, 'OT', 'Cô đi lấy thì người gọi cô lại và nói: "Xin hãy mang cho tôi một miếng bánh trong tay cô."'),
(9330, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 17, 12, 'OT', 'Bà nói: "Đức Giê-hô-va Đức Chúa Trời của ngài hằng sống, tôi không có cái bánh nào, chỉ còn một nắm bột trong thùng và một ít dầu trong bình thôi; và nầy, tôi đang đi lấy hai que củi, rồi về làm một bữa cho tôi và con trai tôi, để chúng tôi ăn rồi chết."'),
(9331, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 17, 13, 'OT', 'Ê-li bảo bà ấy: "Đừng sợ! Hãy đi làm như lời bà nói, nhưng trước hết hãy làm một chiếc bánh nhỏ từ đó và mang cho tôi; sau đó bà và con trai bà hãy làm phần của mình."'),
(9332, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 17, 14, 'OT', 'Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên phán như vầy: Hũ bột sẽ không cạn, và bình dầu sẽ không thiếu cho đến ngày Đức Giê-hô-va khiến mưa rơi xuống trên mặt đất.'),
(9333, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 17, 15, 'OT', 'Bà đi và làm theo lời Ê-li-ia; ông ấy, bà ấy và nhà của bà ấy đã ăn trong nhiều ngày.'),
(9334, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 17, 16, 'OT', 'Hũ bột mì không hề cạn, và bầu dầu cũng chẳng thiếu hụt, y như lời Đức Giê-hô-va đã phán qua lời Ê-li-a.'),
(9335, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 17, 17, 'OT', 'Sau các việc ấy, đứa con trai của người đàn bà, chủ nhà, bị bệnh; và cơn bệnh của nó trở nên nặng lắm, đến nỗi không còn hơi thở trong người nó nữa.'),
(9336, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 17, 18, 'OT', 'Bà nói với Ê-li: "Tôi và ông có can hệ gì với nhau, hỡi người của Đức Chúa Trời? Ông đến đây để nhắc lại tội tôi hay để giết con trai tôi?"'),
(9337, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 17, 19, 'OT', 'Người nói với bà: "Hãy đưa con bà cho tôi." Rồi người nhận đứa trẻ từ lòng bà, đem lên phòng trên, nơi người đang ở, và đặt nó trên giường của mình.'),
(9338, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 17, 20, 'OT', 'Ôi Đức Giê-hô-va Đức Chúa Trời của tôi, phải chăng Ngài cũng gây tai họa cho góa phụ mà tôi đang tạm trú cùng, bằng cách giết chết con trai bà ấy sao?'),
(9339, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 17, 21, 'OT', 'Ông nằm dài trên đứa trẻ ba lần, và kêu cầu Đức Giê-hô-va, rồi nói: "Lạy Đức Giê-hô-va, Đức Chúa Trời của tôi, xin hãy làm cho linh hồn đứa trẻ này trở lại trong nó."'),
(9340, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 17, 22, 'OT', 'Đức Giê-hô-va đã nghe tiếng Ê-li; và linh hồn của đứa trẻ trở lại trong lòng nó, rồi nó sống lại.'),
(9341, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 17, 23, 'OT', 'Ê-li lấy đứa trẻ, đem nó từ buồng trên xuống nhà dưới và trao cho người mẹ. Rồi Ê-li nói: "Này, con trai bà còn sống!"'),
(9342, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 17, 24, 'OT', 'Người đàn bà nói với Ê-li: "Bây giờ tôi biết chắc rằng ông thật là một người của Đức Chúa Trời, và lời của Đức Giê-hô-va trong miệng ông là sự thật."'),
(9343, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 1, 'OT', 'Một thời gian dài trôi qua, rồi lời của Đức Giê-hô-va phán cùng Ê-li trong năm thứ ba rằng: "Hãy đi, trình diện trước mặt A-háp; ta sẽ sai mưa xuống trên mặt đất."'),
(9344, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 2, 'OT', 'Ê-li đã đi để trình diện trước mặt A-háp. Lúc ấy, nạn đói nghiêm trọng đang hoành hành tại Xa-ma-ri.'),
(9345, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 3, 'OT', 'A-háp gọi Ô-ba-đi-a, người quản lý nhà vua; và Ô-ba-đi-a rất kính sợ Đức Giê-hô-va.'),
(9346, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 4, 'OT', 'Khi Ích-bên tiêu diệt các nhà tiên tri của Đức Giê-hô-va, thì Óp-đi-a lấy một trăm nhà tiên tri, giấu họ thành nhóm năm mươi người trong các hang đá, và cung cấp bánh và nước cho họ.'),
(9347, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 5, 'OT', 'A-háp nói với Ô-ba-đi-a: "Hãy đi khắp đất, đến mọi suối nước và mọi khe nước; may ra tìm được cỏ để cứu sống ngựa và lừa, hầu khỏi phải mất hết súc vật."'),
(9348, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 6, 'OT', 'Vậy họ chia đất ra để đi qua đó; A-háp đi một con đường riêng, và Ô-ba-đi-ah đi một con đường riêng.'),
(9349, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 7, 'OT', 'Đang khi Ô-ba-đi-a đi đường, thì nầy, Ê-li-ah từ phía trước đón người; người nhận ra ông, liền sấp mặt xuống đất và nói: "Chính ông đây sao, thầy tôi, ông Ê-li-ah?"'),
(9350, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 8, 'OT', 'Và người nói với ông: Ta đây. Hãy đi, nói với chủ ngươi: Này, Ê-li-ah đang ở đây.'),
(9351, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 9, 'OT', 'Người ấy thưa: Tôi đã phạm tội gì, mà ngài lại trao đầy tớ của ngài vào tay A-háp để giết tôi?'),
(9352, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 10, 'OT', 'Chúa Giê-hô-va hằng sống, nếu có dân tộc hay nước nào mà chủ nhân ta chưa sai người đến tìm ngươi; và khi họ nói: "Không có," thì người bắt nước ấy và dân tộc ấy phải thề rằng họ không tìm thấy ngươi.'),
(9353, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 11, 'OT', 'Bây giờ ngươi lại bảo: "Hãy đi, nói với chủ ngươi: Nầy, Ê-li-ah đây."'),
(9354, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 12, 'OT', 'Khi tôi rời khỏi ông, thì Thần của Đức Giê-hô-va sẽ đem ông đi đến nơi mà tôi không biết; rồi khi tôi đi báo cho A-háp, mà ông không tìm thấy ông, ông ấy sẽ giết tôi; nhưng tôi, đầy tớ ông, đã kính sợ Đức Giê-hô-va từ khi còn trẻ.'),
(9355, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 13, 'OT', 'Chẳng phải đã báo cho chủ tôi biết điều tôi đã làm khi Ít-sa-bên giết các nhà tiên tri của Đức Giê-hô-va sao? Tôi đã giấu một trăm người là các nhà tiên tri của Đức Giê-hô-va, mỗi nhóm năm mươi người trong một hang, và cung cấp cho họ bánh và nước.'),
(9356, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 14, 'OT', 'Bây giờ ngươi lại bảo: "Hãy đi, nói với chủ ngươi: Kìa, Ê-li-a đây"; nhưng người sẽ giết tôi.'),
(9357, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 15, 'OT', 'Bấy giờ Ê-li nói: Đức Giê-hô-va vạn quân mà tôi đứng trước mặt Ngài, hằng sống; ngày nay tôi sẽ đến ra mắt người.'),
(9358, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 16, 'OT', 'Ông Ô-ba-đi-a đi gặp A-háp và thuật lại cho ông ấy; rồi A-háp đi gặp Ê-li-a.'),
(9359, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 17, 'OT', 'Khi A-háp thấy Ê-li, thì A-háp nói với người rằng: "Chính ngươi chăng, người làm rối loạn Y-sơ-ra-ên?"'),
(9360, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 18, 'OT', 'Người đáp: "Tôi chẳng làm cho Y-sơ-ra-ên bị rối loạn đâu; nhưng chính ngươi và nhà cha ngươi đã làm, vì các ngươi đã từ bỏ các điều răn của Đức Giê-hô-va và đi theo các thần Ba-anh."'),
(9361, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 19, 'OT', 'Bây giờ, hãy sai người đi tập họp cho ta toàn thể dân Y-sơ-ra-ên đến núi Các-mên, cùng với các nhà tiên tri của Ba-an, bốn trăm năm mươi người, và các nhà tiên tri của A-sê-ra, bốn trăm người, là những kẻ ăn ở bàn của Y-ze-bên.'),
(9362, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 20, 'OT', 'A-háp đã sai người đi khắp toàn thể con dân Ít-ra-en, rồi triệu tập các nhà tiên tri đến núi Ca-ranh-el.'),
(9363, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 21, 'OT', 'Ê-li đã đến gần toàn thể dân chúng và nói: "Các ngươi còn nhảy nhót giữa hai bên cho đến bao giờ? Nếu Đức Giê-hô-va là Đức Chúa Trời, hãy theo Ngài; còn nếu Ba-anh là thần, hãy theo nó." Nhưng dân chúng không trả lời người một lời nào.'),
(9364, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 22, 'OT', 'Ê-li bảo dân chúng rằng: "Chính tôi, tôi còn lại làm đấng tiên tri cho Đức Giê-hô-va, chỉ một mình tôi thôi; còn các tiên tri của Ba-anh thì có bốn trăm năm mươi người."'),
(9365, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 23, 'OT', 'Hãy để họ đưa cho chúng tôi hai con bò đực; rồi họ hãy chọn lấy một con cho mình, xẻ thịt ra, đặt trên củi, nhưng không đặt lửa vào; còn tôi sẽ làm thịt con bò đực kia, đặt trên củi, nhưng không đặt lửa vào.'),
(9366, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 24, 'OT', 'Hãy kêu cầu danh các thần của các ngươi, còn ta sẽ kêu cầu danh Đức Giê-hô-va; và thần nào đáp lại bằng lửa thì chính là Đức Chúa Trời. Toàn thể dân chúng đáp và nói: Điều đó thật tốt lành.'),
(9367, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 25, 'OT', 'Ê-li-a nói với các nhà tiên tri của Ba-anh: "Hãy chọn lấy một con bò đực trong hai con, rồi chuẩn bị trước, vì các ngươi đông hơn; hãy kêu cầu danh các thần của các ngươi, nhưng đừng châm lửa."'),
(9368, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 26, 'OT', 'Họ lấy con bò đực mà người ta đã giao cho, rồi chế biến nó, và kêu cầu danh Ba-anh từ sáng sớm cho đến trưa, nói rằng: "Hỡi Ba-anh, hãy đáp lại chúng tôi!" Nhưng không có tiếng nào, cũng chẳng có ai đáp lại. Và họ nhảy nhót quanh bàn thờ mà họ đã làm.'),
(9369, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 27, 'OT', 'Đến trưa, Ê-li-a chế giễu chúng nó và nói: "Hãy kêu lớn tiếng, vì người là thần! Có thể người đang trò chuyện, hoặc người đang mải mê, hoặc người đang trên đường đi; hay là người đang ngủ và phải đánh thức!"'),
(9370, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 28, 'OT', 'Họ kêu la thật lớn, và cứ theo lệ thường của mình mà tự xé xác bằng gươm và giáo, cho đến khi máu chảy ra trên mình họ.'),
(9371, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 29, 'OT', 'Khi đã qua trưa, họ tiếp tục nói tiên tri cho đến giờ dâng lễ chiều, nhưng không có tiếng nào, cũng không ai trả lời, và chẳng ai để ý.'),
(9372, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 30, 'OT', 'Ê-li nói với toàn thể dân chúng: "Hãy đến gần ta." Toàn thể dân chúng liền đến gần người. Rồi người sửa lại bàn thờ của Đức Giê-hô-va đã bị phá đổ.'),
(9373, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 31, 'OT', 'Ê-li lấy mười hai hòn đá, theo số lượng các chi phái của con trai Gia-cốp, là người mà lời của Đức Giê-hô-va phán cùng, rằng: "Ít-ra-en sẽ là danh ngươi."'),
(9374, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 32, 'OT', 'Ông lấy các tảng đá xây một bàn thờ nhân danh Đức Giê-hô-va, rồi đào một cái rãnh chung quanh bàn thờ, đủ chứa hai đấu hạt giống.'),
(9375, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 33, 'OT', 'Sắp đặt các khúc gỗ, rồi chặt con bò mộng ra từng miếng, đặt lên các khúc gỗ.'),
(9376, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 34, 'OT', 'Rồi người nói: "Hãy đổ đầy bốn chum nước, rồi rưới lên của lễ thiêu và lên các củi." Người nói: "Làm lần thứ hai," và họ làm lần thứ hai. Người nói: "Làm lần thứ ba," và họ làm lần thứ ba.'),
(9377, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 35, 'OT', 'Nước chảy quanh bàn thờ, và người đó cũng đổ đầy nước vào rãnh.'),
(9378, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 36, 'OT', 'Khi đến giờ dâng lễ chiều, thì Ê-li-a, đấng tiên tri, đến gần và nói: "Lạy Đức Giê-hô-va, Đức Chúa Trời của Áp-ra-ham, Y-sác và Ít-ra-ên, ngày nay xin cho người ta biết rằng Ngài là Đức Chúa Trời ở trong Ít-ra-ên, và tôi là đầy tớ Ngài, và tôi đã làm tất cả những điều nầy theo lời Ngài."'),
(9379, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 37, 'OT', 'Lạy Đức Giê-hô-va, xin đáp lời tôi, xin đáp lời tôi, để dân sự này biết rằng chính Ngài là Đức Giê-hô-va, là Đức Chúa Trời, và xin Ngài làm cho lòng họ trở lại cùng Ngài.'),
(9380, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 38, 'OT', 'Bấy giờ lửa của Đức Giê-hô-va từ trên rơi xuống, thiêu đốt của lễ thiêu, các khúc gỗ, những hòn đá, và bụi đất; lại còn hút cạn nước trong hào.'),
(9381, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 39, 'OT', 'Toàn thể dân chúng thấy vậy, liền phủ phục xuống đất và reo lên: "Đức Giê-hô-va mới thật là Đức Chúa Trời! Đức Giê-hô-va mới thật là Đức Chúa Trời!"'),
(9382, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 40, 'OT', 'Ê-li bảo họ: "Hãy bắt các nhà tiên tri Ba-an, đừng để một ai thoát khỏi tay các ngươi." Vậy họ bắt các nhà tiên tri ấy; rồi Ê-li đem chúng xuống suối Ki-sôn và giết chúng tại đó.'),
(9383, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 41, 'OT', 'Ê-li nói với A-háp: "Ngươi hãy lên, ăn và uống đi, vì ta nghe tiếng mưa đổ xuống rất lớn."'),
(9384, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 42, 'OT', 'A-háp đi lên ăn và uống. Còn Ê-li giêng lên đỉnh núi Cạt-mên, rồi cúi mình xuống đất, đặt mặt mình giữa hai đầu gối.'),
(9385, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 43, 'OT', 'Người nói với đầy tớ mình: "Hãy lên, hãy nhìn về hướng biển." Người ấy lên, nhìn, rồi nói: "Không có gì cả." Ê-li bảo: "Hãy trở lại, đi bảy lần."'),
(9386, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 44, 'OT', 'Bảy lần rồi, người ấy nói: "Kìa, một đám mây nhỏ bằng bàn tay người trỗi dậy từ biển." Rồi người ấy nói: "Hãy lên, bảo A-háp: Hãy buộc dây lên, rồi xuống ngay, kẻo mưa cản trở ông."'),
(9387, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 45, 'OT', 'Và xảy ra đến khi ấy, trời đầy mây đen và gió nổi lên, và có cơn mưa lớn đổ xuống. A-háp cỡi ngựa đi về Y-xơ-rên.'),
(9388, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 18, 46, 'OT', 'Bấy giờ tay của Đức Giê-hô-va giáng trên Ê-li, ông liền thắt lưng, chạy trước mặt A-háp cho đến khi vào đến cửa Y-xơ-rên.'),
(9389, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 19, 1, 'OT', 'A-cha-b nói với Ích-xa-bên mọi điều Ê-li-gia đã làm, và mọi điều người đã giết các nhà tiên tri bằng gươm.'),
(9390, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 19, 2, 'OT', 'Bấy giờ, nữ vương Y-xa-bên sai một sứ giả đến gặp Ê-li, nói rằng: "Các thần hãy đối xử với ta cách nào, và còn làm thêm điều gì nữa, nếu đến giờ này ngày mai ta không khiến mạng sống ngươi giống như mạng sống một người trong bọn chúng, thì các thần khá xử ta thật vậy."'),
(9391, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 19, 3, 'OT', 'Thấy vậy, ông đứng dậy, trốn đi để cứu mạng mình, đến Bê-er-Sê-ba thuộc về xứ Giu-đa, và để đầy tớ mình lại đó.'),
(9392, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 19, 4, 'OT', 'Nhưng người đi một ngày đường vào đồng vắng, rồi đến và ngồi dưới một cây đỗ quyên; người xin chính mình được chết, và nói: Đủ rồi! Bây giờ, lạy Đức Giê-hô-va, xin hãy lấy mạng sống tôi, vì tôi chẳng tốt hơn tổ tiên tôi.'),
(9393, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 19, 5, 'OT', 'Ông nằm ngủ dưới một cây đỗ hương. Nầy, một thiên sứ chạm vào ông và nói với ông: "Hãy trỗi dậy, ăn đi."'),
(9394, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 19, 6, 'OT', 'Ông nhìn, và này, bên cạnh đầu ông có một cái bánh nướng trên than hồng và một bầu nước. Ông ăn và uống, rồi nằm xuống ngủ tiếp.'),
(9395, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 19, 7, 'OT', 'Thiên sứ của Đức Giê-hô-va lại đến lần thứ hai, chạm vào ông và nói: "Hãy chỗi dậy, ăn đi, vì đường còn dài hơn ông tưởng."'),
(9396, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 19, 8, 'OT', 'Ông đứng dậy, ăn và uống, rồi đi trong sức lực của thức ăn ấy bốn mươi ngày bốn mươi đêm, đến núi Đức Chúa Trời là Hô-rếp.'),
(9397, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 19, 9, 'OT', 'Ông đến nơi đó, vào một cái hang và ở lại đó. Kìa, lời của Đức Giê-hô-va phán cùng ông, phán rằng: "Ê-li-a, ngươi ở đây làm gì?"'),
(9398, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 19, 10, 'OT', 'Người nói: "Tôi đã sốt sắng vì Đức Giê-hô-va Đức Chúa Trời của các đạo binh; vì dân Y-sơ-ra-ên đã từ bỏ giao ước Ngài, phá đổ các bàn thờ Ngài, và giết các đấng tiên tri Ngài bằng gươm; và tôi đây chỉ còn lại một mình, mà họ cũng đang tìm cách lấy mạng tôi."'),
(9399, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 19, 11, 'OT', 'Đức Giê-hô-va phán: "Hãy đi ra, đứng trên núi trước mặt Đức Giê-hô-va." Nầy, Đức Giê-hô-va đang đi ngang qua; và có một gió lớn mạnh làm nứt núi và đập vỡ đá trước mặt Đức Giê-hô-va, nhưng Đức Giê-hô-va không ở trong gió; sau gió có một cơn động đất, nhưng Đức Giê-hô-va không ở trong động đất.'),
(9400, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 19, 12, 'OT', 'Sau trận động đất có lửa, nhưng Đức Giê-hô-va không ở trong lửa; và sau lửa có tiếng nói nhỏ nhẹ mảnh mai.'),
(9401, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 19, 13, 'OT', 'Khi Ê-li-a nghe xong, ông liền lấy áo choàng che mặt, đi ra và đứng ở lối vào hang. Nầy, có tiếng phán cùng ông rằng: "Ê-li-a, ngươi ở đây làm gì?"'),
(9402, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 19, 14, 'OT', 'Người thưa: "Tôi đã sốt sắng hết lòng cho Đức Giê-hô-va, Đức Chúa Trời của các đạo quân, vì các con trai Y-sơ-ra-ên đã từ bỏ giao ước Ngài, phá đổ các bàn thờ Ngài, và dùng gươm giết các nhà tiên tri Ngài; còn tôi, chỉ mình tôi còn sót lại, và họ đang tìm cách lấy mạng tôi."'),
(9403, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 19, 15, 'OT', 'Đức Giê-hô-va phán cùng người rằng: "Hãy đi, trở lại đường ngươi qua đồng vắng Đa-mách; và khi ngươi đến, hãy xức dầu cho Ha-za-ên làm vua trên A-ram."'),
(9404, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 19, 16, 'OT', 'Và ngươi sẽ xức dầu cho Giê-hu, con trai của Nim-si, làm vua cai trị trên Ít-ra-en; và ngươi sẽ xức dầu cho Ê-li-sa, con trai của Sa-phát, ở A-bên Mê-hô-la, làm đấng tiên tri thay thế ngươi.'),
(9405, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 19, 17, 'OT', 'Kẻ nào trốn thoát khỏi gươm của Ha-xa-ên sẽ bị Giê-hu giết; và kẻ nào trốn thoát khỏi gươm của Giê-hu sẽ bị Ê-li-sa giết.'),
(9406, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 19, 18, 'OT', 'Ta sẽ để lại trong Y-sơ-ra-ên bảy ngàn người, tất cả những đầu gối không hề quỳ xuống trước Ba-anh, và mọi miệng không hề hôn người ấy.'),
(9407, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 19, 19, 'OT', 'Ông đi từ nơi đó, gặp Ê-li-sê con trai của Sa-phát, đang cày với mười hai đôi bò trước mặt ông, và ông đang ở với đôi thứ mười hai. Ê-li-a đi ngang qua ông, ném áo choàng mình lên ông.'),
(9408, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 19, 20, 'OT', 'Ông bỏ bò đực, chạy theo Ê-li, rồi nói: "Tôi xin được hôn cha mẹ tôi, rồi tôi sẽ đi theo ông." Ê-li nói với ông: "Hãy đi, trở lại đi; vì ta đã làm gì cho ông đâu?"'),
(9409, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 19, 21, 'OT', 'Ông trở về từ sau người đó, bắt lấy một đôi bò đực, giết chúng, rồi dùng đồ nghề của bò đực mà nấu thịt, và đem cho dân chúng; họ ăn. Rồi ông chỗi dậy, đi theo Ê-li, và hầu việc người.'),
(9410, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 1, 'OT', 'Và Bên-ha-đát, vua xứ Sy-ria, tập hợp toàn bộ đạo quân mình, cùng ba mươi hai vua đi theo người, và ngựa cùng xe chiến đấu; người lên đánh, vây hãm Sa-ma-ri và giao chiến với thành ấy.'),
(9411, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 2, 'OT', 'Vua đã sai các sứ giả đến A-háp, vua Y-sơ-ra-ên, trong thành, mà nói rằng:'),
(9412, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 3, 'OT', 'Bên-Ha-đát phán như vầy: Bạc ngươi và vàng ngươi là của ta; các vợ ngươi và các con ngươi, những người tốt nhất, cũng là của ta.'),
(9413, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 4, 'OT', 'Vua Y-sơ-ra-ên đáp và nói: "Tâu chúa tôi là vua, theo lời chúa tôi, tôi và tất cả những gì thuộc về tôi đều thuộc về ngài."'),
(9414, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 5, 'OT', 'Các sứ giả lại trở về và nói: Bên-ha-đát truyền lời như vầy: Ta đã sai người đến bảo ngươi rằng: Bạc của ngươi, vàng của ngươi, vợ của ngươi, con cái của ngươi phải đưa cho ta.'),
(9415, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 6, 'OT', 'Ngày mai vào giờ này, ta sẽ sai các đầy tớ ta đến cùng ngươi, và chúng sẽ lục soát nhà ngươi và các nhà của các đầy tớ ngươi; và tất cả những gì ngươi thấy đẹp mắt sẽ được chúng bỏ vào tay mình mà mang đi.'),
(9416, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 7, 'OT', 'Vua Y-sơ-ra-ên triệu tập tất cả các bậc trưởng lão trong xứ, rồi nói: "Hãy nhìn xem, hãy nhận biết điều ác mà người này đang tìm kiếm: người ấy đã sai sứ đến đòi vợ tôi, con cái tôi, bạc tôi, vàng tôi, mà tôi đã không từ chối điều gì cả."'),
(9417, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 8, 'OT', 'Các bậc trưởng lão và toàn thể dân chúng đều thưa với vua: "Đừng nghe theo hắn, và đừng chịu phục."'),
(9418, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 9, 'OT', 'Vua nói với các sứ giả của Bên-ha-đát: "Hãy nói cho chủ tôi là vua rằng: Mọi điều mà ngài đã sai đến đòi tôi tớ tôi lúc ban đầu, tôi sẽ làm; nhưng điều này tôi không thể làm được." Các sứ giả đi đi và đem lời đáp lại cho người.'),
(9419, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 10, 'OT', 'Bản Hadát sai người đến nói với vua Ít-ra-en rằng: "Các thần làm cho tôi như thế nào, và còn tệ hơn nữa, nếu bụi của Sa-ma-ri-a đủ để mỗi người theo tôi nắm một nắm."'),
(9420, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 11, 'OT', 'Vua Y-sơ-ra-ên đáp và nói: Hãy nói, đừng để người thắt dây lưng khoe mình như người cởi ra.'),
(9421, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 12, 'OT', 'Khi nghe được lời này, còn người thì đang uống rượu cùng các vua trong các lều, thì người bảo các tôi tớ mình: "Hãy sắp hàng." Vậy họ liền xếp hàng nghịch thành phố.'),
(9422, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 13, 'OT', 'Kìa, có một nhà tiên tri đến cùng A-háp, vua Y-sơ-ra-ên, và nói rằng: Đức Giê-hô-va phán như vầy: Ngươi có thấy toàn thể đoàn người đông đảo nầy chăng? Kìa, chính ta sẽ phó nó vào tay ngươi hôm nay, để ngươi biết rằng ta là Đức Giê-hô-va.'),
(9423, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 14, 'OT', 'A-háp nói: "Bởi tay ai?" Người ấy đáp: "Đức Giê-hô-va phán như vầy: ''Bởi các thiếu niên của các quan tổng trấn các tỉnh.''" A-háp lại hỏi: "Ai sẽ khởi sự cuộc chiến?" Người ấy đáp: "Chính ngươi."'),
(9424, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 15, 'OT', 'Người đã điểm số các thiếu niên là các quan tổng trấn các tỉnh, thì được hai trăm ba mươi hai người; và sau đó, người điểm số toàn thể dân sự, tức là tất cả con trai của Y-sa-ra-ên, là bảy ngàn người.'),
(9425, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 16, 'OT', 'Họ ra đi vào buổi trưa, còn Bên-ha-đát thì đang uống rượu say trong các lều, cùng với ba mươi hai vua giúp đỡ ông ấy.'),
(9426, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 17, 'OT', 'Các đầy tớ trẻ của các quan tổng trấn ra đi trước; rồi Bên-ha-đát sai người đi, và họ báo cho ông rằng: "Có những người ra từ Sa-ma-ri."'),
(9427, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 18, 'OT', 'Người nói: Nếu họ ra đi để giảng hòa, hãy bắt sống họ; nếu họ ra đi để gây chiến, hãy bắt sống họ.'),
(9428, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 19, 'OT', 'Các thiếu niên là các quan tổng trấn các tỉnh đi ra khỏi thành, và đạo quân theo sau họ.'),
(9429, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 20, 'OT', 'Mỗi người đánh giặc của mình; người Sy-ri chạy trốn, và Ít-ra-en đuổi theo họ. Nhưng Bên-ha-đát, vua Sy-ri, trốn thoát trên lưng một con ngựa cùng các kỵ binh.'),
(9430, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 21, 'OT', 'Vua Y-sơ-ra-ên đi ra, đánh giết ngựa và xe chiến, và đánh dân A-ram một trận đại bại.'),
(9431, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 22, 'OT', 'Vị tiên tri đến cùng vua Y-sơ-ra-ên và nói với người rằng: "Hãy đi, tự làm cho mình mạnh mẽ, và hãy biết, hãy xem điều ngươi sẽ làm, vì vào mùa trở lại năm nay, vua A-ram sẽ lên nghịch cùng ngươi."'),
(9432, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 23, 'OT', 'Các tôi tớ của vua A-ram nói với người rằng: "Các thần của chúng nó là các thần của các ngọn đồi, vì vậy chúng nó mạnh hơn chúng ta; nhưng hãy chiến đấu với chúng nó trên vùng đồng bằng, chắc chắn chúng ta sẽ mạnh hơn chúng nó."'),
(9433, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 24, 'OT', 'Hãy làm điều này: Hãy thay các vua khỏi chỗ của mỗi người, và đặt những viên chỉ huy thay vào chỗ họ.'),
(9434, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 25, 'OT', 'Hãy bổ sung cho mình một đạo quân như đạo quân mà ngươi đã mất, ngựa theo ngựa, xe theo xe; rồi chúng ta sẽ chiến đấu với họ trên đồng bằng; chắc chắn ta sẽ mạnh hơn họ. Vua nghe theo tiếng nói của họ và làm như vậy.'),
(9435, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 26, 'OT', 'Sang năm sau, khi mùa chiến tranh trở lại, thì Bên-ha-đát điểm quân A-ram và lên Aphek để chiến đấu cùng Y-sơ-ra-ên.'),
(9436, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 27, 'OT', 'Các con trai của Y-sơ-ra-ên được điểm danh, được cung cấp đầy đủ nhu yếu phẩm, rồi đi ra nghênh chiến với chúng; các con trai của Y-sơ-ra-ên đóng trại đối diện chúng như hai bầy dê con nhỏ; còn người A-ram thì đầy đất.'),
(9437, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 28, 'OT', 'Một người của Đức Chúa Trời đến và nói với vua Y-sơ-ra-ên rằng: "Đức Giê-hô-va phán như vầy: Vì người A-ram đã nói: ''Đức Giê-hô-va là Đức Chúa Trời của các núi, nhưng Ngài không phải là Đức Chúa Trời của các đồng bằng,'' cho nên Ta sẽ trao toàn thể đoàn người đông đảo lớn này vào tay ngươi, để các ngươi biết rằng Ta là Đức Giê-hô-va."'),
(9438, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 29, 'OT', 'Họ đóng trại đối diện nhau bảy ngày. Đến ngày thứ bảy, trận chiến bùng nổ; và con cái Y-sơ-ra-ên đã đánh bại người A-ram, giết một trăm ngàn lính bộ trong một ngày.'),
(9439, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 30, 'OT', 'Số người còn sót lại chạy trốn đến A-phéc, vào thành phố; và bức tường đổ sập xuống trên hai mươi bảy ngàn người còn lại. Bên-ha-đát chạy thoát và vào thành, vào một phòng trong.'),
(9440, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 31, 'OT', 'Các tôi tớ của ông thưa rằng: "Thưa chúa, chúng tôi đã nghe rằng các vua nhà Y-sơ-ra-ên là những vua nhân từ. Vậy xin để chúng tôi đặt vải thô vào hông và dây thừng trên đầu, rồi ra gặp vua Y-sơ-ra-ên; may ra người sẽ cứu mạng sống chúa."'),
(9441, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 32, 'OT', 'Họ lấy vải gai quấn quanh hông, lấy dây trói đầu, rồi đến cùng vua Y-sơ-ra-ên mà thưa rằng: "Bên-ha-đát, đầy tớ ngài, xin ngài làm ơn cho tôi được sống." Vua đáp: "Anh ta còn sống ư? Anh ta là anh em ta."'),
(9442, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 33, 'OT', 'Các người ấy chăm chú quan sát, vội vàng nhanh tay bắt lấy lời nói đó, rồi thưa: "Bên-ha-đát, anh vua." Vua bảo: "Hãy đi, dẫn người ấy đến." Thế là Bên-ha-đát ra gặp vua, và vua cho người ấy lên xe mình.'),
(9443, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 34, 'OT', 'Vua ấy nói với người rằng: "Những thành nào mà cha tôi đã chiếm được từ cha ông, tôi sẽ trả lại; và ông có thể lập các khu phố cho mình tại Đa-mách, như cha tôi đã làm tại Sa-ma-ri. Tôi sẽ cho ông đi theo giao ước này." Vậy người ấy lập giao ước với vua và cho vua đi.'),
(9444, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 35, 'OT', 'Một người trong các con trai của các nhà tiên tri nói với người đồng bạn của mình nhân danh lời của Đức Giê-hô-va: "Xin hãy đánh tôi." Nhưng người ấy từ chối đánh ông.'),
(9445, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 36, 'OT', 'Vậy người ấy nói với ông: "Vì ngươi đã không vâng theo tiếng nói của Đức Giê-hô-va, hãy xem, khi ngươi vừa rời khỏi ta, một con sư tử sẽ giết ngươi." Rồi khi ông vừa rời khỏi người ấy, một con sư tử gặp ông và giết ông.'),
(9446, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 37, 'OT', 'Người ấy gặp một người khác, rồi nói: "Tôi xin ông hãy đánh tôi." Người kia bèn đánh ông, và khi đánh đã làm ông bị thương.'),
(9447, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 38, 'OT', 'Đoạn tiên tri đi ra, đứng chờ vua bên đường và lấy tro che mặt mình.'),
(9448, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 39, 'OT', 'Vua đi ngang qua, thì người kêu lên cùng vua. Người nói: "Tôi là đầy tớ của ngài, tôi đã ra giữa trận đánh. Kìa, một người tách ra và dẫn một người đến cho tôi, rồi nói: ''Hãy giữ người này. Nếu người ấy bị mất, mạng sống ngươi sẽ thay cho mạng sống người ấy, hoặc ngươi phải nộp một kikar bạc.''"'),
(9449, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 40, 'OT', 'Bấy giờ tôi tớ của ngài đang làm việc nọ việc kia, thì người ấy đã biến mất. Vua Y-sơ-ra-ên nói với ông ta: "Đúng rồi, án phạt của ngươi sẽ như vậy; chính ngươi đã quyết định điều đó."'),
(9450, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 41, 'OT', 'Ông vội vàng lấy tro khỏi mặt mình, và vua Y-sơ-ra-ên nhận biết ông, vì ông thuộc nhóm các nhà tiên tri.'),
(9451, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 42, 'OT', 'Đức Giê-hô-va phán như vầy: "Vì ngươi đã buông tay một người mà Ta đã phó vào sự hủy diệt, nên mạng ngươi sẽ thay cho mạng hắn, và dân ngươi sẽ thay cho dân hắn."'),
(9452, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 20, 43, 'OT', 'Vua Y-sơ-ra-ên bèn đi về nhà mình, buồn bã và tức giận, rồi vào Sa-ma-ri.'),
(9453, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 21, 1, 'OT', 'Sau những việc ấy, Nápốt người Y-xơ-rên có một vườn nho ở Y-xơ-rên, gần cung điện của A-háp, vua Xa-ma-ri.'),
(9454, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 21, 2, 'OT', 'A-háp nói với Na-bốt rằng: "Hãy giao cho ta vườn nho của ngươi, để ta làm vườn rau, vì nó gần bên nhà ta; và ta sẽ cho ngươi một vườn nho tốt hơn thay thế, hoặc nếu ngươi muốn, ta sẽ trả cho ngươi tiền tương xứng với giá của nó."'),
(9455, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 21, 3, 'OT', 'Na-bốt nói với A-háp: Đức Giê-hô-va chớ cho phép tôi làm điều đó, để tôi trao phần cơ nghiệp của tổ tiên tôi cho ngài.'),
(9456, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 21, 4, 'OT', 'A-háp trở về nhà mình, buồn bã và tức giận vì lời mà Na-bốt người Y-xơ-rên đã nói với ông: "Tôi sẽ không trao cho ngài cơ nghiệp của tổ tiên tôi." Rồi ông nằm xuống giường, quay mặt vào tường và không chịu ăn bánh.'),
(9457, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 21, 5, 'OT', 'Bà Ích-sa-bên, vợ ông, đến cùng ông và nói với ông: "Tại sao thần khí ngài lại sầu não, đến nỗi ngài không ăn bánh?"'),
(9458, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 21, 6, 'OT', 'Và người nói với bà: "Tôi đã nói với Na-bốt người Y-xơ-ra-en rằng: ''Hãy cho tôi vườn nho của ông lấy tiền; hoặc nếu ông bằng lòng, tôi sẽ đưa ông một vườn nho khác thay thế.'' Nhưng ông ấy đáp: ''Tôi sẽ không cho ngài vườn nho của tôi.''"'),
(9459, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 21, 7, 'OT', 'Và Ích-xa-bên, vợ ông, nói với ông: "Ông hiện đang cai trị vương quốc Y-sơ-ra-ên đó! Hãy đứng dậy, ăn bánh đi, để lòng ông được vui vẻ; tôi sẽ cho ông vườn nho của Na-bô, người Ghít-rê-ên."'),
(9460, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 21, 8, 'OT', 'Bà viết các bức thư nhân danh A-háp, đóng dấu ấn của ông, rồi sai người mang các bức thư đến các bậc trưởng lão và các người quyền quý trong thành ấy, là những người sống cùng Nát-thốt.'),
(9461, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 21, 9, 'OT', 'Hãy viết vào các bức thư, nói rằng: "Hãy công bố một thời kỳ ăn chay, và đặt Nabốt ở hàng đầu giữa dân chúng."'),
(9462, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 21, 10, 'OT', 'Hãy đặt hai người đàn ông gian ác ngồi đối diện với người ấy, để làm chứng rằng: "Ngươi đã nguyền rủa Đức Chúa Trời và vua." Rồi hãy dẫn người ấy ra ngoài, ném đá cho chết.'),
(9463, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 21, 11, 'OT', 'Các người trong thành người, tức các bậc trưởng lão và các người quyền quý sống ở thành người, đã làm theo như Ize-bel đã sai bảo họ, và theo như điều đã viết trong các bức thư mà bà đã sai đến họ.'),
(9464, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 21, 12, 'OT', 'Họ công bố một kỳ ăn chay, và đặt Na-bốt lên hàng đầu giữa dân chúng.'),
(9465, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 21, 13, 'OT', 'Có hai người đàn ông gian ác đến, ngồi đối diện trước mặt ông. Những người gian ác làm chứng chống lại Na-bốt trước mặt dân chúng, nói: "Na-bốt đã sỉ nhục Đức Chúa Trời và vua." Rồi họ dẫn ông ra khỏi thành, ném đá ông cho đến chết.'),
(9466, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 21, 14, 'OT', 'Họ sai người đến cùng Ích-xa-bên, nói rằng: Nát-bốt đã bị ném đá cho chết rồi.'),
(9467, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 21, 15, 'OT', 'Khi Ít-chẹ-ven nghe tin Na-bốt bị ném đá chết, thì bà nói với A-háp: "Hãy chỗi dậy, chiếm lấy vườn nho của Na-bốt người Y-xơ-ranh, mà nó đã từ chối không chịu bán cho ngươi bằng tiền, vì Na-bốt không còn sống nữa, nó đã chết."'),
(9468, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 21, 16, 'OT', 'Khi A-háp nghe tin Na-bốt đã chết, thì A-háp chỗi dậy đi xuống vườn nho của Na-bốt người Y-xơ-rên, để chiếm hữu nó.'),
(9469, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 21, 17, 'OT', 'Lời Đức Giê-hô-va phán cùng Ê-li, người Thinh-bích, rằng,'),
(9470, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 21, 18, 'OT', 'Hãy chỗi dậy, đi xuống gặp A-háp, vua Ít-ra-en, người đang ở Sa-ma-ri. Nầy, người đang ở trong vườn nho của Na-bốt, nơi người đã đi xuống để chiếm hữu nó.'),
(9471, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 21, 19, 'OT', 'Ngươi hãy nói với người ấy rằng: Đức Giê-hô-va phán như vầy: "Ngươi đã giết, lại còn chiếm hữu nữa sao?" Ngươi hãy nói với người ấy rằng: Đức Giê-hô-va phán như vầy: "Tại nơi chó liếm huyết của Na-bốt, chó cũng sẽ liếm huyết ngươi nữa."'),
(9472, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 21, 20, 'OT', 'A-háp nói với Ê-li: "Ngươi đã tìm được ta, hỡi kẻ thù ta sao?" Ê-li đáp: "Ta đã tìm được ngươi, vì ngươi đã bán mình để làm điều ác trước mặt Đức Giê-hô-va."'),
(9473, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 21, 21, 'OT', 'Nầy, Ta sẽ giáng họa cho ngươi, và Ta sẽ tiêu diệt dòng dõi ngươi; Ta sẽ cắt đứt khỏi nhà A-háp những người còn lại ở Ít-ra-en, cả những kẻ bị giam giữ lẫn những kẻ bị bỏ lại.'),
(9474, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 21, 22, 'OT', 'Ta sẽ khiến nhà ngươi giống như nhà của Giê-rô-bô-am, con trai của Nê-bát, và giống như nhà của Ba-a-sa, con trai của A-hi-gia, vì sự xúc phạm mà ngươi đã khiến Ta nổi giận, và khiến Ít-ra-en phạm tội.'),
(9475, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 21, 23, 'OT', 'Đức Giê-hô-va cũng đã phán về Ích-xa-bên rằng: Những con chó sẽ ăn Ích-xa-bên tại ruộng Jiz-rê-ên.'),
(9476, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 21, 24, 'OT', 'Ai chết thuộc về A-háp trong thành thì chó sẽ ăn; ai chết nơi đồng vắng thì chim trời sẽ ăn.'),
(9477, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 21, 25, 'OT', 'Chỉ có điều không ai giống như A-háp, người đã bán mình để làm điều ác trước mặt Đức Giê-hô-va, mà chính Ít-xa-bên, vợ người, đã xúi giục người.'),
(9478, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 21, 26, 'OT', 'Và người đã làm điều cực kỳ ghê tởm khi theo các thần tượng, y như mọi điều mà người Amôrít đã làm, mà Đức Giê-hô-va đã đuổi ra khỏi trước mặt con cái Ít-ra-en.'),
(9479, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 21, 27, 'OT', 'Khi A-háp nghe những lời ấy, thì xé rách áo mình, lấy bao gai mặc trên thân thể, ăn chay, nằm trong bao gai, và đi đứng cách rón rén.'),
(9480, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 21, 28, 'OT', 'Lời Đức Giê-hô-va phán cùng Ê-li, người Thi-sê-bê, rằng:'),
(9481, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 21, 29, 'OT', 'Ngươi có thấy rằng A-háp đã hạ mình trước mặt ta không? Bởi vì hắn đã hạ mình trước mặt ta, ta sẽ không giáng họa xuống nhà nó trong đời nó; nhưng trong đời con trai nó, ta sẽ giáng họa xuống nhà nó.'),
(9482, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 1, 'OT', 'Ba năm trời, không có chiến tranh xảy ra giữa Sy-ri và Y-sơ-ra-ên.'),
(9483, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 2, 'OT', 'Vào năm thứ ba, vua Giô-sa-phát của Giu-đa đi xuống gặp vua của Y-sơ-ra-ên.'),
(9484, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 3, 'OT', 'Vua Y-sơ-ra-ên nói với các tôi tớ mình: "Các ngươi có biết rằng Ra-mốt ở Ga-la-át là của chúng ta, mà chúng ta lại ngồi yên, không đoạt lại nó khỏi tay vua A-ram sao?"'),
(9485, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 4, 'OT', 'Vua nói với Giô-sa-phát: "Ngươi có đi cùng ta đánh giặc tại Ra-mốt Ga-la-đa không?" Giô-sa-phát đáp với vua Y-sơ-ra-ên: "Tôi như ngươi, dân tôi như dân ngươi, ngựa tôi như ngựa ngươi."'),
(9486, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 5, 'OT', 'Đa-ha-phát nói với vua Ít-ra-en: "Hãy cầu hỏi lời của Đức Giê-hô-va hôm nay."'),
(9487, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 6, 'OT', 'Vua Y-sơ-ra-ên tập họp các nhà tiên tri, khoảng bốn trăm người, rồi nói với họ: "Ta có nên đi đánh Ra-mốt trong xứ Ghích-xi-ôn hay nên thôi?" Họ đáp: "Hãy đi lên, vì Đức Giê-hô-va sẽ trao thành vào tay vua."'),
(9488, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 7, 'OT', 'Giô-sa-phát nói: "Chẳng còn một ngôn sứ nào của Đức Giê-hô-va sao, để chúng ta hỏi người đó?"'),
(9489, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 8, 'OT', 'Vua Y-sơ-ra-ên nói với Giê-hô-sa-phát: "Còn một người nữa, là Mích-a-hu, con trai của Y-ma-lát, nhờ người đó chúng ta có thể cầu hỏi Đức Giê-hô-va." Nhưng tôi ghét người này, vì người ấy chẳng bao giờ nói điều tốt về tôi, mà chỉ nói điều xấu." Giê-hô-sa-phát đáp: "Đừng để cho đức vua nói như vậy."'),
(9490, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 9, 'OT', 'Vua Y-sơ-ra-ên gọi một viên thái giám, rồi nói: Hãy mau gọi Mi-ki-a, con trai của I-ma-lát.'),
(9491, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 10, 'OT', 'Vua Y-sơ-ra-ên và Giô-sa-phát, vua Giu-đa, ngồi mỗi người trên ngôi mình, mặc các bộ áo choàng, tại nơi trống trải ở cửa thành Sa-ma-ri; và tất cả các nhà tiên tri đều đang nói tiên tri trước mặt hai người.'),
(9492, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 11, 'OT', 'Xy-đê-kia, con trai của Xê-na-nah, làm cho người những chiếc sừng bằng sắt, rồi nói rằng: Đức Giê-hô-va phán như vầy: Ngươi sẽ dùng những chiếc này mà húc dân Sy-ria cho đến khi tiêu diệt chúng nó.'),
(9493, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 12, 'OT', 'Tất cả các nhà tiên tri đều nói tiên tri như vậy, rằng: "Hãy đi lên Râmôth-Ga-la-át và sẽ thành công; vì Đức Giê-hô-va sẽ phó nó vào tay vua."'),
(9494, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 13, 'OT', 'Và thiên sứ đã đi gọi Mi-cai-a nói với người rằng: "Nầy, các lời của các nhà tiên tri đều đồng lòng nói điều tốt cho vua; nguyện lời của ngươi cũng như lời của một trong những người ấy, và hãy nói điều tốt."'),
(9495, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 14, 'OT', 'Mi-cai-a nói: "Nhân danh Đức Giê-hô-va, Đấng Hằng Sống, điều gì Đức Giê-hô-va phán cùng tôi, tôi sẽ nói điều đó."'),
(9496, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 15, 'OT', 'Người ấy đến cùng vua. Vua nói với người ấy: "Mi-cai-a, chúng ta có nên đi đánh Ra-mốt trong xứ Ghil-ead hay không, hay là nên kiêng cữ?" Người thưa với vua: "Xin hãy đi, và sẽ thành công; vì Đức Giê-hô-va sẽ trao nó vào tay vua."'),
(9497, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 16, 'OT', 'Vua nói với ông: "Ta sẽ phải lấy danh Đức Giê-hô-va khiến ngươi thề mấy lần nữa, để ngươi nói cho ta chỉ điều thật?"'),
(9498, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 17, 'OT', 'Bấy giờ người nói: Tôi thấy toàn thể dân Y-sơ-ra-ên rải rác trên các núi, như những con chiên không có người chăn. Và Đức Giê-hô-va phán: Những người nầy không có chủ, hãy để mỗi người trở về nhà mình trong bình an.'),
(9499, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 18, 'OT', 'Vua Y-sơ-ra-ên nói với Giô-sa-phát: "Tôi há chẳng nói với ông rằng người nầy sẽ không nói tiên tri lành cho tôi, mà chỉ nói điều dữ sao?"'),
(9500, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 19, 'OT', 'Vậy nên, hãy nghe lời của Đức Giê-hô-va: tôi đã thấy Đức Giê-hô-va ngồi trên ngôi của Ngài, và toàn thể đạo binh trên trời đứng chung quanh Ngài, bên phải và bên trái Ngài.'),
(9501, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 20, 'OT', 'Đức Giê-hô-va phán: "Ai sẽ lừa A-háp, để người đi lên và ngã xuống tại Ra-mốt trong xứ Ghi-lê-đa?" Một người nói theo cách này, một người nói theo cách kia.'),
(9502, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 21, 'OT', 'Một thần linh đi ra, đứng trước mặt Đức Giê-hô-va và nói: Tôi sẽ lừa phỉnh người ấy.'),
(9503, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 22, 'OT', 'Đức Giê-hô-va phán cùng người: "Ngươi sẽ làm điều đó bằng cách nào?" Người ấy đáp: "Tôi sẽ đi ra, và sẽ làm thần linh nói dối trong miệng mọi đấng tiên tri của người ấy." Đức Giê-hô-va phán: "Ngươi sẽ thuyết phục người ấy và ngươi cũng sẽ thành công. Hãy đi ra và làm như vậy."'),
(9504, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 23, 'OT', 'Vậy bây giờ, Đức Giê-hô-va đã đặt thần nói dối vào miệng tất cả các đấng tiên tri của ngươi, và Đức Giê-hô-va đã phán điều dữ nghịch lại ngươi.'),
(9505, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 24, 'OT', 'Bấy giờ Xít-ki-gia, con trai của Xê-na-nia, đến gần, đánh Mích-gia vào má, rồi nói rằng: Thần của Đức Giê-hô-va đã đi khỏi ta để phán cùng ngươi theo đường nào?'),
(9506, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 25, 'OT', 'Rồi Mi-cai-a nói: "Này, ngươi sẽ thấy trong ngày đó, khi ngươi vào một phòng nọ để lẩn trốn."'),
(9507, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 26, 'OT', 'Vua Y-sơ-ra-ên nói: "Hãy bắt Mi-cai-a, rồi dẫn hắn về cho A-môn, quan tổng trấn thành phố, và cho Giô-ách, con trai vua."'),
(9508, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 27, 'OT', 'Hãy nói: Vua phán như vầy: Hãy nhốt người này trong ngục, và cho người ấy ăn bánh hoạn nạn cùng uống nước hoạn nạn, cho đến khi ta trở về bình an.'),
(9509, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 28, 'OT', 'Mi-cai-a nói: "Nếu ngươi trở về bình an, thì Đức Giê-hô-va chưa từng phán qua tôi." Rồi ông nói: "Hỡi mọi người, hãy lắng nghe đi!"'),
(9510, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 29, 'OT', 'Vua của Y-sơ-ra-ên và Giô-sa-phát, vua của Giu-đa, lên Ra-mốt trong đất Ga-la-át.'),
(9511, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 30, 'OT', 'Vua Y-sơ-ra-ên nói với Giô-sa-phát: "Hãy để tôi cải trang và đi vào trận chiến, còn ông thì hãy mặc áo xống của mình." Vậy vua Y-sơ-ra-ên cải trang và đi vào trận chiến.'),
(9512, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 31, 'OT', 'Vua của Sy-ri truyền lệnh cho ba mươi hai viên chỉ huy các xe chiến xa thuộc về ông rằng: "Các ngươi chớ chiến đấu cùng kẻ nhỏ hay kẻ lớn, nhưng chỉ chiến đấu với vua Y-sơ-ra-ên mà thôi."'),
(9513, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 32, 'OT', 'Khi các quan chỉ huy xe chiến thấy Giô-sa-phát, thì nói: "Chắc hẳn đây là vua Ít-ra-en!" và họ quay sang tấn công ông. Nhưng Giô-sa-phát kêu lớn lên.'),
(9514, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 33, 'OT', 'Khi các đội trưởng xe nhìn thấy người đó không phải là vua Y-sơ-ra-ên, họ liền quay lại, không đuổi theo nữa.'),
(9515, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 34, 'OT', 'Một người giương cung bắn bừa, trúng vua Y-sơ-ra-ên giữa các miếng áo giáp và vành đai; người ấy nói với người đánh xe mình rằng: "Hãy quay tay lại và đưa ta ra khỏi trại quân, vì ta đang bị thương."'),
(9516, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 35, 'OT', 'Và trận chiến ngày ấy càng lúc càng ác liệt; vua đứng vững trong cỗ xe để chống lại quân Sy-ri, rồi qua đời vào buổi chiều; máu từ vết thương chảy xuống đáy cỗ xe.'),
(9517, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 36, 'OT', 'Một tiếng hô vang vang lên trong trại quân lúc mặt trời lặn, rằng: "Mỗi người về thành mình, mỗi người về xứ sở mình."'),
(9518, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 37, 'OT', 'Vua qua đời, rồi người ta chở xác về Sa-ma-ri; và họ chôn vua tại Sa-ma-ri.'),
(9519, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 38, 'OT', 'Người ta rửa xe chiến ở hồ Sa-ma-ri; còn các chó liếm máu của người, và những kẻ điếm rửa mình tại đó; đúng như lời Đức Giê-hô-va đã phán.'),
(9520, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 39, 'OT', 'Còn các việc khác của A-háp, mọi điều ông làm, và cung điện ngà mà ông xây dựng, cùng mọi thành phố mà ông xây cất, há chẳng chép trong sách Các Việc Làm Hằng Năm của các vua Y-sơ-ra-ên sao?'),
(9521, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 40, 'OT', 'A-háp nằm ngủ cùng các tổ phụ mình, và A-ha-xi-a, con trai người, lên ngôi vua kế vị người.'),
(9522, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 41, 'OT', 'Giô-sa-phát, con trai của A-sa, trị vì làm vua xứ Giu-đa trong năm thứ tư đời A-háp, vua của Y-sơ-ra-ên.'),
(9523, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 42, 'OT', 'Giô-sa-phát, khi người lên ngôi, được ba mươi lăm tuổi, và trị vì hai mươi lăm năm tại Giê-ru-sa-lem. Tên mẹ người là A-xu-va, con gái của Si-lhi.'),
(9524, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 43, 'OT', 'Và người đi theo mọi con đường của Asa, cha người; người không xây bỏ khỏi đó, làm điều ngay thẳng trước mặt Đức Giê-hô-va; tuy nhiên, các nơi cao không bị bỏ đi; dân chúng vẫn dâng của lễ và đốt hương tại các nơi cao.'),
(9525, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 44, 'OT', 'Vậy Giô-sa-phát lập hòa ước với vua Y-sơ-ra-ên.'),
(9526, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 45, 'OT', 'Còn các việc khác của Giô-sa-phát, cùng những chiến công và sức mạnh người đã làm, và những gì người chiến đấu, thì chẳng phải đã chép trong sách Các Việc Làm Hằng Ngày của các vua Giu-đa sao?'),
(9527, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 46, 'OT', 'Phần còn lại của những kẻ gian dâm thánh, là những kẻ còn sót lại trong các ngày của Asa, cha người, thì người đã quét sạch khỏi đất.'),
(9528, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 47, 'OT', 'Vua thì không có trong Ê-đôm; một quan phó vương cai trị.'),
(9529, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 48, 'OT', 'Đa-ha-sáp làm các tàu biển đi Tạt-si sang Ô-phia để chở vàng, nhưng không đi được, vì các tàu bị vỡ tại Ê-xi-ôn- Ghê-be.'),
(9530, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 49, 'OT', 'Sau đó, A-ha-xi-a, con trai của A-háp, nói với Giê-hô-sa-phát: "Các tôi tớ tôi hãy đi cùng các tôi tớ ngươi trên các tàu thuyền." Nhưng Giê-hô-sa-phát không chịu.'),
(9531, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 50, 'OT', 'Vậy nên, Giô-sa-phát nằm ngủ cùng các tổ phụ mình, và được chôn cùng các tổ phụ mình trong thành Đa-vít, cha của ông; rồi Giô-ram, con trai ông, lên ngôi làm vua thế cho ông.'),
(9532, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 51, 'OT', 'A-ha-xi-a, con trai của A-háp, làm vua trên Ít-ra-en tại Sa-ma-ri trong năm thứ mười bảy đời Giô-sa-phát, vua của Giu-đa, và trị vì trên Ít-ra-en hai năm.'),
(9533, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 52, 'OT', 'Vua A-ha-xi-ah làm điều ác trước mặt Đức Giê-hô-va, đi theo đường lối của cha mình, đường lối của mẹ mình, và đường lối của Giê-rô-bô-am, con trai của Nê-bát, người đã khiến cho Ít-ra-en phạm tội.'),
(9534, 11, 'GOI_vi', 'GOI_vi', 'vi', '1KI', 22, 53, 'OT', 'Vì người thờ Ba-al và cúi lạy nó, khiến Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en nổi giận, y như mọi điều mà cha người đã làm.'),
(9535, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 1, 1, 'OT', 'Mô-áp nổi loạn chống lại Y-sơ-ra-ên sau khi A-háp qua đời.'),
(9536, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 1, 2, 'OT', 'A-cha-xia ngã xuống qua cửa sổ lầu trên phòng mình ở Sa-ma-ri, và bị bệnh; người sai các sứ giả đi và dặn họ rằng: "Hãy đi hỏi Ba-anh-xê-búp, thần của thành Êc-rôn, xem ta có thể sống được khỏi cơn bệnh này không?"'),
(9537, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 1, 3, 'OT', 'Nhưng thiên sứ của Đức Giê-hô-va phán cùng Ê-li-a người Thi-sa-bê rằng: "Hãy chỗi dậy, đi lên đón các sứ giả của vua Sa-ma-ri, và nói với họ: ''Tại sao các ngươi đi hỏi Ba-anh-Xe-bub, thần của Ê-cơ-rôn, vì không có Đức Chúa Trời trong Y-sơ-ra-ên sao?''"'),
(9538, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 1, 4, 'OT', 'Vì vậy, Đức Giê-hô-va phán như thế này: Chiếc giường mà ngươi đã nằm lên đó, ngươi sẽ không xuống khỏi nó, vì ngươi chắc chắn sẽ chết. Rồi Ê-li-a đi đi.'),
(9539, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 1, 5, 'OT', 'Các sứ giả bèn trở lại cùng người, và người nói với họ: "Sao các ngươi trở lại?"'),
(9540, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 1, 6, 'OT', 'Họ thưa với vua: "Một người đàn ông đã đến gặp chúng tôi và nói: ''Hãy đi trở lại cùng vua, người đã sai các ngươi, và nói với người ấy: Đức Giê-hô-va phán như thế này: Tại sao ngươi sai người đi hỏi Ba-an-xê-bút, thần của Ê-cơ-rôn, như thể không có Đức Chúa Trời nào trong Y-sơ-ra-ên sao? Vì vậy, ngươi sẽ không xuống khỏi giường mà ngươi đã lên đó, vì ngươi chắc chắn sẽ chết.''"'),
(9541, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 1, 7, 'OT', 'Và người nói với họ: "Người đàn ông ấy có hình dạng như thế nào, người đã lên gặp các ngươi và nói những lời này với các ngươi?"'),
(9542, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 1, 8, 'OT', 'Họ thưa người đó: "Một người đàn ông có bộ râu, và thắt lưng bằng da quanh hông." Vua nói: "Chính Ê-li, người Ti-sê-bi."'),
(9543, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 1, 9, 'OT', 'Vua sai một đội trưởng cùng với năm mươi thuộc hạ đến gặp người ấy. Người đội trưởng đi lên và thấy Ê-li-xơ đang ngồi trên đỉnh núi. Ông nói với người của Đức Chúa Trời rằng: "Người của Đức Chúa Trời, nhà vua truyền lệnh: ''Hãy xuống đây!''"'),
(9544, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 1, 10, 'OT', 'Ê-li đã trả lời và nói với viên chỉ huy đội năm mươi rằng: "Nếu ta là người của Đức Chúa Trời, thì xin lửa từ trời hãy xuống thiêu đốt ngươi và năm mươi người thuộc hạ của ngươi." Bèn có lửa từ trời xuống thiêu đốt ông ta và năm mươi người thuộc hạ của ông ta.'),
(9545, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 1, 11, 'OT', 'Người ấy trở lại và sai một viên chỉ huy của năm mươi cùng năm mươi thuộc hạ đến ông. Viên chỉ huy đáp và nói với người của Đức Chúa Trời: "Nhà vua bảo: ''Hãy mau xuống đây.''"'),
(9546, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 1, 12, 'OT', 'Ê-li-a đáp và nói với họ: "Nếu ta là người của Đức Chúa Trời, thì lửa hãy từ trời xuống mà thiêu đốt ngươi và năm mươi người thuộc hạ ngươi." Bấy giờ lửa của Đức Chúa Trời từ trời xuống, thiêu đốt người ấy và năm mươi người thuộc hạ người ấy.'),
(9547, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 1, 13, 'OT', 'Vua sai một viên chỉ huy của đạo quân năm mươi cùng năm mươi thuộc hạ mình. Viên chỉ huy đạo quân năm mươi thứ ba ấy đi lên, đến gần, cúi lạy trước mặt Ê-li-a, nài xin người và thưa rằng: "Thưa người của Đức Chúa Trời, xin ông làm ơn coi mạng sống tôi và mạng sống của năm mươi đầy tớ ông này là quý giá trước mặt ông."'),
(9548, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 1, 14, 'OT', 'Nầy, lửa từ trên trời đã xuống và thiêu đốt hai đội trưởng của hai đội năm mươi người trước kia cùng với những người năm mươi của họ; vậy bây giờ, nguyện mạng tôi được coi là quý cho mắt ngươi.'),
(9549, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 1, 15, 'OT', 'Thiên sứ của Đức Giê-hô-va phán cùng Ê-li: "Hãy đi xuống với người; chớ sợ người." Ê-li bèn chỗi dậy, đi xuống cùng người đến cùng vua.'),
(9550, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 1, 16, 'OT', 'Người nói với ông: "Đức Giê-hô-va phán như thế này: Bởi ngươi đã sai các sứ giả đi cầu hỏi Ba-anh-xê-bút, thần của thành Êc-rôn, phải chăng vì không có Đức Chúa Trời trong Y-sơ-ra-ên để cầu hỏi lời Ngài, nên ngươi sẽ không xuống khỏi giường mà ngươi đã lên đó; ngươi chắc chắn sẽ chết."'),
(9551, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 1, 17, 'OT', 'Và người ấy đã chết theo lời của Đức Giê-hô-va mà Ê-li-a đã nói. Rồi Giô-ram lên ngôi vua thay cho người, vào năm thứ hai đời Giô-ram, con trai của Giô-sa-phát, vua nước Giu-đa; vì người ấy không có con trai.'),
(9552, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 1, 18, 'OT', 'Còn các việc khác của A-ha-xi-a mà người đã làm, há chẳng chép trong sách Các Việc Làm Thời Nhật Ký của các vua Y-sơ-ra-ên sao?'),
(9553, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 2, 1, 'OT', 'Xảy ra khi Đức Giê-hô-va đem Ê-li lên trời trong cơn gió lốc, thì Ê-li và Ê-li-sa đi từ Ghinh-ganh.'),
(9554, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 2, 2, 'OT', 'Ê-li bảo Ê-li-sê: "Hãy ở lại đây, vì Đức Giê-hô-va đã sai tôi đến Bê-tên." Nhưng Ê-li-sê đáp: "Nhân danh Đức Giê-hô-va hằng sống và hồn mạng sống ngươi, tôi sẽ không rời bỏ ngươi." Vậy hai người đi xuống Bê-tên.'),
(9555, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 2, 3, 'OT', 'Các con trai của các nhà tiên tri ở Bê-tên đi ra gặp Ê-li-sê, và nói với người: "Ông có biết hôm nay Đức Giê-hô-va sẽ đem thầy ông khỏi đầu ông không?" Người đáp: "Tôi cũng biết; hãy im lặng."'),
(9556, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 2, 4, 'OT', 'Ê-li bảo Ê-li-sê: "Hãy ở lại đây, vì Đức Giê-hô-va đã sai ta đến Giê-ri-cô." Nhưng Ê-li-sê đáp: "Nhân danh Đức Giê-hô-va hằng sống và hồn ngươi sống, tôi sẽ không rời bỏ ngươi." Vậy hai người cùng đến Giê-ri-cô.'),
(9557, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 2, 5, 'OT', 'Các con trai của các nhà tiên tri ở Giê-ri-cô đến cùng Ê-li-sê và nói với người: "Ông có biết hôm nay Đức Giê-hô-va sẽ đem thầy ông khỏi đầu ông không?" Người đáp: "Tôi cũng biết; hãy im lặng."'),
(9558, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 2, 6, 'OT', 'Ê-li bảo ông: "Hãy ở lại đây, vì Đức Giê-hô-va đã sai tôi đến sông Giô-đanh." Nhưng ông đáp: "Nhân danh Đức Giê-hô-va hằng sống và nhân danh mạng sống của thầy, tôi sẽ không rời thầy." Rồi cả hai cùng đi.'),
(9559, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 2, 7, 'OT', 'Năm mươi người trong các con trai của các nhà tiên tri đã đi và đứng nhìn từ xa, còn hai người ấy thì đứng bên bờ sông Giô-đanh.'),
(9560, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 2, 8, 'OT', 'Ê-li đã lấy áo choàng mình ra, cuộn lại, rồi đánh vào nước; nước liền tách sang hai bên, và cả hai người đi qua sông trên đất khô.'),
(9561, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 2, 9, 'OT', 'Khi hai người qua đến nơi, Ê-li bảo Ê-li-sê: "Hãy xin điều gì ta sẽ làm cho ngươi trước khi ta được đem đi khỏi ngươi." Ê-li-sê đáp: "Xin cho tôi được hai phần của thần khí ngài."'),
(9562, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 2, 10, 'OT', 'Ông nói: "Ông đã xin điều khó. Nếu ông thấy tôi khi tôi được đem đi khỏi ông, thì điều ông xin sẽ được như vậy; còn nếu không thấy, thì sẽ không được như vậy."'),
(9563, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 2, 11, 'OT', 'Đang khi hai người đi và nói chuyện, thì nầy, một cỗ xe bằng lửa và những ngựa bằng lửa hiện ra, chia cách hai người; rồi Ê-li đi lên trời trong cơn gió lốc.'),
(9564, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 2, 12, 'OT', 'Ê-li-sa thấy vậy, liền kêu lên: "Cha tôi, cha tôi! Hỡi chiến xa của Ít-ra-en và các kỵ binh của nó!" Rồi ông không thấy ông ấy nữa. Ông nắm lấy áo mình và xé ra làm hai mảnh.'),
(9565, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 2, 13, 'OT', 'Ông lấy lấy chiếc áo choàng của Ê-li-a mà đã rơi khỏi người ông ấy, rồi trở lại và đứng bên bờ sông Giô-đanh.'),
(9566, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 2, 14, 'OT', 'Ông lấy áo choàng của Ê-li-a mà người đã để lại cho ông, đánh vào nước và nói: "Đức Giê-hô-va, Đức Chúa Trời của Ê-li-a ở đâu?" Rồi ông đánh nước lần nữa, nước liền tách sang hai bên, và Ê-li-sê đi qua.'),
(9567, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 2, 15, 'OT', 'Khi các con trai của các nhà tiên tri ở Giê-ri-cô thấy ông từ xa, thì nói rằng: Thần của Ê-li đã ngự trên Ê-li-sê. Họ đến gặp ông và cúi mặt xuống đất trước mặt ông.'),
(9568, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 2, 16, 'OT', 'Họ nói với ông: "Này xin ông, hiện có năm mươi người trai tráng là tôi tớ của ông; xin hãy để họ đi tìm chủ ông, e rằng Thần của Đức Giê-hô-va đã mang ông ấy đi và ném ông ấy trên một ngọn núi hoặc xuống một thung lũng nào." Nhưng ông nói: "Các ngươi sẽ không được sai đi."'),
(9569, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 2, 17, 'OT', 'Họ nài ép ông cho đến khi ông hổ thẹn, rồi ông nói: "Hãy sai đi." Vậy họ sai năm mươi người; họ tìm kiếm suốt ba ngày, nhưng không tìm thấy ông ấy.'),
(9570, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 2, 18, 'OT', 'Họ trở lại cùng ông, còn ông thì đang ngồi tại Giê-ri-cô. Ông nói với họ: "Tôi đã chẳng bảo các ông đừng đi sao?"'),
(9571, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 2, 19, 'OT', 'Các người trong thành nói với Ê-li-sê: "Xin ông vui lòng, nơi ở của thành này tốt, như chính ông thấy; nhưng nước thì xấu và đất thì cằn cỗi."'),
(9572, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 2, 20, 'OT', 'Ông nói: "Hãy đem cho tôi một cái bình mới, và đặt muối vào đó." Họ liền đem cho ông.'),
(9573, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 2, 21, 'OT', 'Người ra đến nguồn nước, ném muối vào đó và nói: "Đức Giê-hô-va phán thế này: Ta đã chữa lành nước này; từ đây sẽ không còn cái chết hay mất mùa nữa."'),
(9574, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 2, 22, 'OT', 'Vì vậy, các dòng nước được chữa lành cho đến ngày nay, theo lời Ê-li-sê mà ông đã nói.'),
(9575, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 2, 23, 'OT', 'Người lên từ đó đến Bê-thên; và khi Người đang đi lên đường, thì có những đứa trẻ nhỏ từ thành phố đi ra, chế giễu Người và nói với Người rằng: "Hãy lên, hỡi người trọc! Hãy lên, hỡy người trọc!"'),
(9576, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 2, 24, 'OT', 'Ông quay lại, nhìn thấy chúng, rồi nguyền rủa chúng nhân danh Đức Giê-hô-va. Bấy giờ hai con gấu cái từ trong rừng lao ra, xé toạc bốn mươi hai đứa trẻ trong số chúng.'),
(9577, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 2, 25, 'OT', 'Người đi từ đó đến núi Cạt-mên, rồi từ đó trở về Sa-ma-ri.'),
(9578, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 3, 1, 'OT', 'Giô-ram, con trai của A-háp, lên làm vua cai trị trên Ít-ra-en tại Sa-ma-ri trong năm thứ mười tám đời của Giô-sa-phát, vua nước Giu-đa, và trị vì được mười hai năm.'),
(9579, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 3, 2, 'OT', 'Vua ấy làm điều ác trong mắt Đức Giê-hô-va, nhưng không như cha mình và như mẹ mình; vua đã dẹp bỏ tượng trụ thờ Ba-al mà cha mình đã làm.'),
(9580, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 3, 3, 'OT', 'Chỉ gắn chặt vào các tội lỗi của Giê-rô-bô-am, con trai của Nê-bát, là người đã khiến cho Ít-ra-en phạm tội; người nầy không từ bỏ các tội lỗi ấy.'),
(9581, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 3, 4, 'OT', 'Vua Mô-áp là Mê-sa chăn nuôi chiên, và mỗi năm dâng cho vua Y-sơ-ra-ên một trăm ngàn chiên con và một trăm ngàn con cừu đực cùng với lông chiên.'),
(9582, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 3, 5, 'OT', 'Sau khi A-háp qua đời, vua xứ Mô-áp nổi dậy chống lại vua Ít-ra-en.'),
(9583, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 3, 6, 'OT', 'Vua Giô-ram ra đi từ Sa-ma-ri vào ngày ấy, và ông kiểm điểm toàn thể dân Y-sơ-ra-ên.'),
(9584, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 3, 7, 'OT', 'Vua ấy đi và sai sứ đến cùng Giô-sa-phát, vua xứ Giu-đa, nói rằng: "Vua xứ Mô-áp đã nổi loạn nghịch cùng ta; ngươi có muốn đi cùng ta đánh Mô-áp chăng?" Nhưng ông đáp: "Ta sẽ đi lên; ta như ngươi, dân ta như dân ngươi, ngựa của ta như ngựa của ngươi."'),
(9585, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 3, 8, 'OT', 'Ông ấy nói: "Chúng ta sẽ lên đường nào?" Và ông ấy đáp: "Đường qua đồng vắng Ê-đôm."'),
(9586, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 3, 9, 'OT', 'Vua Y-sơ-ra-ên cùng đi, vua Giu-đa và vua Ê-đôm; họ đi vòng đường bảy ngày; nhưng không có nước cho đạo quân và cho súc vật đi theo họ.'),
(9587, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 3, 10, 'OT', 'Vua Y-sơ-ra-ên nói: Ôi! Đức Giê-hô-va đã gọi ba vị vua nầy lại với nhau để nộp họ vào tay người Mô-áp!'),
(9588, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 3, 11, 'OT', 'Đoạn đó, Giô-sa-phát nói: "Ở đây chẳng có một đấng tiên tri nào của Đức Giê-hô-va để chúng ta cầu hỏi Đức Giê-hô-va qua người sao?" Một trong các đầy tớ của vua Y-sơ-ra-ên đáp lời và nói: "Ở đây có Ê-li-sê, con trai của Sa-phát, người đã đổ nước trên tay Ê-li-a."'),
(9589, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 3, 12, 'OT', 'Bấy giờ Giô-sa-phát nói: "Ở đó có đấng nói lời của Đức Giê-hô-va." Vậy, vua Y-sơ-ra-ên, Giô-sa-phát và vua Ê-đôm liền đi xuống gặp người ấy.'),
(9590, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 3, 13, 'OT', 'Ê-li-sê nói với vua Y-sơ-ra-ên: "Ta có can hệ gì với ngươi? Hãy đi đến các nhà tiên tri của cha ngươi, và các nhà tiên tri của mẹ ngươi." Nhưng vua Y-sơ-ra-ên nói với người: "Không, vì chính Đức Giê-hô-va đã gọi ba vua nầy lại với nhau, để nộp họ vào tay dân Mô-áp."'),
(9591, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 3, 14, 'OT', 'Ê-li-sê nói: "Đức Giê-hô-va vạn quân, Đấng tôi đang đứng trước mặt Ngài, hằng sống; nếu không phải vì tôi coi trọng mặt của Giô-sa-phát, vua nước Giu-đa, thì tôi đâu thèm ngó ngàng đến ngươi, hay nhìn thấy ngươi."'),
(9592, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 3, 15, 'OT', 'Bây giờ hãy đem cho tôi một người đánh đàn. Và xảy ra khi người đánh đàn vừa chơi, thì tay của Đức Giê-hô-va ngự trên người ấy.'),
(9593, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 3, 16, 'OT', 'Vậy Đức Giê-hô-va phán: Hãy làm cho thung lũng nầy đầy những hố hố.'),
(9594, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 3, 17, 'OT', 'Vì Đức Giê-hô-va phán như vầy: Các ngươi sẽ không thấy gió, cũng chẳng thấy mưa; nhưng chính thung lũng nầy sẽ đầy nước, và các ngươi sẽ uống, cùng với súc vật và gia súc của các ngươi.'),
(9595, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 3, 18, 'OT', 'Điều nầy thật nhẹ nhỏ trước mặt Đức Giê-hô-va; Ngài sẽ phó dân Mô-áp vào tay các ngươi.'),
(9596, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 3, 19, 'OT', 'Các ngươi sẽ đánh phá mọi thành có vách thành và mọi thành tốt nhất, đốn ngã mọi cây tốt, bịt mọi suối nước, và dùng đá làm hư hại mọi miếng đất tốt.'),
(9597, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 3, 20, 'OT', 'Vào buổi sáng, khi của lễ chiều được dâng lên, thì nầy, nước từ hướng Ê-đôm chảy đến, và đất liền được đầy nước.'),
(9598, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 3, 21, 'OT', 'Toàn thể dân Mô-áp nghe tin các vua đã lên để giao chiến với họ, thì họ liền kêu gọi mọi người từ kẻ thắt lưng đến người lớn tuổi, và đứng ra tại biên giới.'),
(9599, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 3, 22, 'OT', 'Họ chổi dậy sớm vào buổi sáng, mặt trời mọc chiếu trên mặt nước, người Mô-áp thấy mặt nước từ phía bên kia đỏ như máu.'),
(9600, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 3, 23, 'OT', 'Họ nói: "Đây là máu! Các vua đã bị tiêu diệt, và mỗi người đã đánh giết kẻ bên cạnh mình. Vậy bây giờ, hỡi Mô-áp, hãy đi cướp của cải!"'),
(9601, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 3, 24, 'OT', 'Khi họ đến trại của Y-sơ-ra-ên, thì dân Y-sơ-ra-ên đứng dậy đánh người Mô-áp, khiến chúng chạy trốn khỏi mặt họ; và họ đuổi theo vào trong xứ chúng, tiếp tục đánh người Mô-áp.'),
(9602, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 3, 25, 'OT', 'Họ phá hủy các thành, và trên mỗi mảnh đất tốt, mỗi người ném hòn đá của mình và làm đầy nó; họ bịt tất cả các suối nước và đốn ngã mọi cây tốt, cho đến khi chỉ để lại những hòn đá của nó tại Kir-ha-ra-sết; rồi những người bắn đá vây quanh nó và đánh thành ấy.'),
(9603, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 3, 26, 'OT', 'Khi vua Mô-áp thấy trận chiến trở nên quá nặng nề đối với mình, ông liền dẫn theo bảy trăm người cầm gươm, muốn phá vỡ hàng ngũ để tấn công vua Ê-đôm, nhưng họ không thể làm được.'),
(9604, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 3, 27, 'OT', 'Vua Mô-áp lấy con trai cả của mình, người sẽ nối ngôi người, và dâng nó làm lễ thiêu trên tường thành. Đức Giê-hô-va nổi cơn thịnh nộ dữ dội cùng Y-sơ-ra-ên; họ bèn rời khỏi người và trở về xứ mình.'),
(9605, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 1, 'OT', 'Một người đàn bà trong các vợ của các con các đấng tiên tri kêu khóc cùng Ê-li-sê, nói rằng: "Chồng tôi là đầy tớ của ông đã chết; và ông biết rằng đầy tớ ông vốn kính sợ Đức Giê-hô-va. Bây giờ người cho vay nợ đã đến để bắt hai đứa con trai tôi đi làm đầy tớ cho người ấy."'),
(9606, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 2, 'OT', 'Ê-li-sa nói với bà ấy: "Tôi phải làm gì cho bà đây? Hãy nói cho tôi biết bà còn gì trong nhà?" Bà ấy đáp: "Tôi tớ bà không còn gì trong nhà, ngoại trừ một cái bình dầu."'),
(9607, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 3, 'OT', 'Đức Giê-hô-va phán: "Hãy đi, mượn ngươi các đồ chứa từ bên ngoài, từ tất cả các hàng xóm ngươi; các đồ chứa rỗng, chớ mượn ít."'),
(9608, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 4, 'OT', 'Con hãy vào trong, đóng cửa lại với con và các con trai của con, rồi đổ dầu vào tất cả những cái bình này; cái nào đầy rồi thì con hãy đặt riêng ra.'),
(9609, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 5, 'OT', 'Bà đi khỏi người ấy, rồi đóng cửa lại với bà và các con bà; các con bà mang đồ đến cho bà, và bà đổ ra.'),
(9610, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 6, 'OT', 'Khi các đồ đựng đã đầy, người mẹ nói với con trai: "Hãy đưa thêm một cái đồ đựng nữa cho mẹ." Nhưng nó nói: "Không còn cái đồ đựng nào nữa." Rồi dầu liền ngừng chảy.'),
(9611, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 7, 'OT', 'Bà đi vào và thuật lại cho người của Đức Chúa Trời. Người ấy nói: "Hãy đi, bán dầu mà trả nợ; còn bà và các con bà thì sống bằng phần còn lại."'),
(9612, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 8, 'OT', 'Một ngày kia, Ê-li-sê đi ngang qua Su-nem, ở đó có một người đàn bà giàu có; bà níu ông lại để ăn bánh. Mỗi khi ông đi ngang qua, ông đều tấp vào đó để ăn bánh.'),
(9613, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 9, 'OT', 'Cô ấy nói với chồng mình: "Nầy, tôi biết rồi, người nầy là một người thánh của Đức Chúa Trời, thường đi ngang qua đây luôn."'),
(9614, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 10, 'OT', 'Chúng ta hãy làm một phòng nhỏ trên tường, xin ông, và đặt ở đó cho người một cái giường, một cái bàn, một cái ghế và một cây đèn. Khi người đến nhà chúng ta, người sẽ lui vào đó.'),
(9615, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 11, 'OT', 'Một ngày kia, ông đến đó, đi vào buồng trên và nằm nghỉ ở đó.'),
(9616, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 12, 'OT', 'Bấy giờ, người nói với Gẹt-xi, đầy tớ mình: "Hãy gọi người phụ nữ Xunam kia." Vậy người ấy gọi bà, và bà đứng trước mặt người.'),
(9617, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 13, 'OT', 'Người nói với ông: "Hãy nói với bà ấy: ''Nầy, bà đã lo lắng cho chúng tôi mọi điều chăm sóc này. Bà muốn làm gì đây? Có cần nói với vua hay tướng quân không?''" Nhưng bà đáp: "Tôi đang sống giữa dân tôi."'),
(9618, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 14, 'OT', 'Người hỏi: "Ta phải làm gì cho nàng?" Ghê-ha-xi đáp: "Nhưng nàng không có con, mà chồng nàng thì đã già."'),
(9619, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 15, 'OT', 'Bấy giờ, người nói: "Hãy gọi bà ấy." Người liền gọi bà ấy, và bà đứng ở nơi cửa.'),
(9620, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 16, 'OT', 'Người của Đức Chúa Trời nói: "Đúng mùa này, vào thời điểm này năm sau, bà sẽ ôm một đứa con trai." Bà ấy thưa: "Không, thưa ông chủ tôi, người của Đức Chúa Trời ơi, xin đừng nói dối với tớ gái ông."'),
(9621, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 17, 'OT', 'Người đàn bà ấy đã mang thai và sinh một con trai đúng vào thời kỳ đã chỉ định, vào thời điểm mà Ê-li-sê đã nói với bà, theo kỳ hẹn của sự sống.'),
(9622, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 18, 'OT', 'Cậu bé lớn lên, và một ngày kia, cậu ra đi đến cùng cha mình đến những người đang gặt.'),
(9623, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 19, 'OT', 'Bấy giờ cậu bé nói với cha mình rằng: "Đầu tôi, đầu tôi!" Rồi người ấy nói với một thiếu niên: "Hãy bồng nó đưa cho mẹ nó."'),
(9624, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 20, 'OT', 'Người ấy nâng cậu bé lên và đem giao cho người mẹ. Cậu bé ngồi trên lòng bà cho đến trưa, rồi chết.'),
(9625, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 21, 'OT', 'Cô ấy đi lên, đặt cậu lên giường của người đàn ông của Đức Chúa Trời, rồi đóng cửa lại trên cậu và ra ngoài.'),
(9626, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 22, 'OT', 'Bà gọi chồng mình và nói: "Xin hãy cho tôi một trong các đầy tớ trẻ và một trong các lừa cái, để tôi chạy đến gặp người của Đức Chúa Trời rồi trở về ngay."'),
(9627, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 23, 'OT', 'Người ấy nói: "Hôm nay, tại sao bà đi đến với ông ấy? Không phải ngày sóc, cũng chẳng phải ngày Sa-bát." Bà đáp: "Bình an."'),
(9628, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 24, 'OT', 'Bà liền đặt yên lên lừa, rồi bảo đầy tớ mình: "Hãy đi, cứ tiếp tục đi; đừng ai ngưng cương lừa cho tôi, trừ khi tôi bảo."'),
(9629, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 25, 'OT', 'Bà đi và đến cùng người của Đức Chúa Trời tại núi Carmel. Khi người của Đức Chúa Trời thấy bà từ xa, ông nói với Ghê-ha-xi, đầy tớ mình: "Kìa, người phụ nữ Shunam đó!"'),
(9630, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 26, 'OT', 'Hãy chạy mau đến đón bà ấy, và nói với bà: "Bà có bình an chăng? Chồng bà có bình an chăng? Con bà có bình an chăng?" Bà ấy đáp: "Bình an."'),
(9631, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 27, 'OT', 'Bà đến cùng người của Đức Chúa Trời trên núi, rồi nắm chặt lấy chân người. Nhưng Ghê-ha-xi đến gần để đẩy bà ra, thì người của Đức Chúa Trời nói: "Hãy để bà ấy yên, vì tâm thần bà rất đau khổ; Đức Giê-hô-va đã giấu tôi điều đó, và không tỏ cho tôi biết."'),
(9632, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 28, 'OT', 'Bà ấy nói: Tôi có xin thầy tôi một đứa con trai đâu? Tôi chẳng nói: Đừng làm tôi buồn khổ sao?'),
(9633, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 29, 'OT', 'Ê-li-sê nói cùng Ghê-ha-xi: "Hãy thắt lưng ngươi lại, cầm cây gậy ta trong tay và đi đi. Nếu ngươi gặp người nào, chớ chào người đó; và nếu có ai chào ngươi, chớ trả lời. Hãy đặt cây gậy ta trên mặt đứa trẻ."'),
(9634, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 30, 'OT', 'Người mẹ của đứa trẻ nói: "Đức Giê-hô-va hằng sống, và linh hồn ngươi cũng hằng sống, tôi sẽ không bỏ ngươi." Rồi người ấy đứng dậy và đi theo bà.'),
(9635, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 31, 'OT', 'Ghê-ha-xi đi trước họ, đặt cây gậy lên mặt đứa trẻ, nhưng không có tiếng nói và cũng không có tiếng đáp lại. Vậy nên anh trở lại gặp Ê-li-sê và báo cáo cho ông rằng: "Đứa trẻ chưa tỉnh lại."'),
(9636, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 32, 'OT', 'Rồi Ê-li-sê vào nhà, và nầy, đứa trẻ đã chết, đang nằm trên giường nó.'),
(9637, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 33, 'OT', 'Ông vào, rồi đóng cửa lại hai người, và cầu nguyện cùng Đức Giê-hô-va.'),
(9638, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 34, 'OT', 'Ông đi lên, nằm trên đứa trẻ, đặt miệng mình lên miệng đứa trẻ, đặt mắt mình lên mắt đứa trẻ, và đặt tay mình lên tay đứa trẻ; rồi ông cúi xuống trên đứa trẻ, và thân thể đứa trẻ trở nên ấm lại.'),
(9639, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 35, 'OT', 'Người trở lại, đi qua đi lại trong nhà một lần này đến một lần khác; rồi đi lên, nằm dài trên đứa trẻ. Đứa trẻ hắt hơi bảy lần, rồi mở mắt ra.'),
(9640, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 36, 'OT', 'Người gọi Ghê-ha-xi và nói: "Hãy gọi người phụ nữ Su-nem này." Ghê-ha-xi gọi bà ấy, và khi bà đến cùng người, ông nói: "Hãy bế con bà lên."'),
(9641, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 37, 'OT', 'Bà ấy vào, sấp mình xuống dưới chân ông, cúi đầu xuống đất, rồi bồng lấy con trai mình và đi ra.'),
(9642, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 38, 'OT', 'Ê-li-sê trở lại Ghinh-ganh; lúc ấy trong đất có nạn đói, và các con trai của các nhà tiên tri đang ngồi trước mặt ông. Ông nói với đầy tớ mình: "Hãy đặt cái nồi lớn lên và nấu cháo cho các con trai của các nhà tiên tri."'),
(9643, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 39, 'OT', 'Một người ra đồng để hái rau, và tìm được một dây nho hoang dã, liền hái những quả bầu bí hoang đầy vạt áo mình; người ấy trở về, rồi thái nhỏ những quả đó bỏ vào nồi nấu thức ăn, vì họ không nhận biết đó là gì.'),
(9644, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 40, 'OT', 'Họ đổ ra cho những người ăn, nhưng khi họ đang ăn món đó thì kêu lên và nói: "Chết rồi, hỡi người của Đức Chúa Trời!" và họ không thể ăn được.'),
(9645, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 41, 'OT', 'Ông bảo: "Hãy lấy bột đem đến." Rồi ông ném vào nồi và bảo: "Đổ ra cho dân chúng ăn." Và trong nồi không còn điều gì xấu nữa.'),
(9646, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 42, 'OT', 'Có một người từ Ba-an-sa-li-sa mang đến cho người của Đức Chúa Trời bánh đầu mùa, hai mươi ổ bánh lúa mạch và những bắp lúa mì còn nguyên vỏ trong túi mình; người ấy nói: "Hãy đưa cho dân chúng, để họ ăn."'),
(9647, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 43, 'OT', 'Người đầy tớ nói: "Tôi lấy cái này dọn cho một trăm người sao?" Nhưng ông nói: "Hãy đưa cho dân chúng, để họ ăn; vì Đức Giê-hô-va phán như vầy: Họ sẽ ăn và còn dư."'),
(9648, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 4, 44, 'OT', 'Người bày ra trước mặt họ, họ ăn và còn thừa lại, đúng như lời Đức Giê-hô-va.'),
(9649, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 5, 1, 'OT', 'Na-a-man, tư lệnh quân đội của vua Áram, là một người quan trọng trước mặt chủ mình và được trọng vọng, vì nhờ người ấy Đức Giê-hô-va đã ban sự giải cứu cho Áram; người này là một chiến sĩ dũng cảm, nhưng bị phung.'),
(9650, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 5, 2, 'OT', 'Đoàn quân A-ram đã ra đi từng toán, và bắt giữ một thiếu nữ nhỏ từ xứ Y-sơ-ra-ên; cô bé ấy ở hầu trước mặt vợ Na-a-man.'),
(9651, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 5, 3, 'OT', 'Cô gái nói với bà chủ mình: "Ước gì ông chủ tôi được ở cùng với đấng tiên tri ở Sa-ma-ri, thì ông ấy sẽ chữa lành ông khỏi bệnh phong!"'),
(9652, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 5, 4, 'OT', 'Người ấy vào và thuật lại cho chủ mình, rằng: "Cô gái từ xứ Y-sơ-ra-ên đã nói như thế này và như thế này."'),
(9653, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 5, 5, 'OT', 'Vua xứ A-ram nói: "Hãy đi, ta sẽ gửi một bức thư đến vua Y-sơ-ra-ên." Rồi ông đi, mang theo mười kik-kal bạc, sáu ngàn tiền vàng, và mười bộ quần áo.'),
(9654, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 5, 6, 'OT', 'Mang thư đến cho vua Y-sơ-ra-ên, nói rằng: "Này khi thư nầy đến cùng ngươi, nầy ta đã sai Na-a-man, đầy tớ ta, đến cùng ngươi, để ngươi chữa lành người khỏi bệnh phung."'),
(9655, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 5, 7, 'OT', 'Khi vua Y-sơ-ra-ên đọc xong thư, thì xé áo mình và nói: "Ta há phải là Đức Chúa Trời sao, có thể khiến người chết sống lại? Tại sao người này lại sai đến ta để chữa lành một người khỏi bệnh phong? Hãy suy xét điều này và nhận thấy rõ rằng người ấy đang tìm cách gây sự với ta."'),
(9656, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 5, 8, 'OT', 'Khi Ê-li-sê, người của Đức Chúa Trời, nghe tin vua Y-sơ-ra-ên xé áo mình, thì người sai đến nói với vua: "Tại sao ngài xé áo mình? Hãy để người ấy đến cùng tôi, và người ấy sẽ biết rằng có một đấng tiên tri ở Y-sơ-ra-ên."'),
(9657, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 5, 9, 'OT', 'Na-a-man bèn đến với ngựa và xe mình, rồi đứng ở cửa nhà Ê-li-sê.'),
(9658, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 5, 10, 'OT', 'Ê-li-sê sai một sứ giả đến bảo người ấy rằng: "Hãy đi, hãy tắm bảy lần trong sông Giô-đanh; thân thể ngươi sẽ trở lại như cũ và ngươi sẽ được sạch."'),
(9659, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 5, 11, 'OT', 'Na-a-man nổi giận và đi khỏi, rồi nói: "Này, tôi đã nghĩ rằng chắc chắn ông ấy sẽ ra gặp tôi, đứng đó, kêu cầu danh Đức Giê-hô-va Đức Chúa Trời mình, vung tay trên nơi ấy và chữa lành người phung."'),
(9660, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 5, 12, 'OT', 'Há chẳng phải các sông A-ba-na và Pha-pha, các sông của Đa-mách, tốt hơn mọi nước của Y-sơ-ra-ên sao? Tôi chẳng thể tắm trong chúng và được sạch sao? Rồi ông quay đi và bỏ đi trong cơn thịnh nộ.'),
(9661, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 5, 13, 'OT', 'Các tôi tớ người đến gần, nói với người rằng: Thưa cha, nếu nhà tiên tri bảo cha làm điều gì lớn, cha há chẳng làm sao? Huống chi bây giờ người chỉ nói: Hãy rửa và được sạch?'),
(9662, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 5, 14, 'OT', 'Ông đi xuống và nhúng mình bảy lần trong sông Giô-đanh, theo lời người của Đức Chúa Trời; rồi da ông trở lại như da của một trẻ nhỏ, và ông được sạch.'),
(9663, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 5, 15, 'OT', 'Rồi ông ấy trở lại cùng người của Đức Chúa Trời, ông và toàn thể đoàn tùy tùng; ông đến, đứng trước mặt người ấy và nói: "Kìa, bây giờ tôi biết chắc rằng không có Đức Chúa Trời nào trên khắp đất nầy ngoài Đức Chúa Trời ở Y-sơ-ra-ên. Vậy bây giờ, xin ông vui lòng nhận một món quà từ tớ của ông."'),
(9664, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 5, 16, 'OT', 'Người ấy nói: "Đức Giê-hô-va, Đấng tôi đang đứng trước mặt Ngài, hằng sống; tôi thề sẽ không nhận gì cả." Nhưng người kia năn nỉ, người ấy vẫn từ chối.'),
(9665, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 5, 17, 'OT', 'Na-a-man nói: "Cầu xin ngài ban cho đầy tớ của ngài hai tải đất, vì từ nay về sau, đầy tớ của ngài sẽ không dâng của lễ toàn thiêu hay của lễ tế nữa cho các thần khác ngoài Đức Giê-hô-va."'),
(9666, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 5, 18, 'OT', 'Xin Đức Giê-hô-va tha cho đầy tớ Ngài trong điều nầy: khi chúa tôi vào nhà Ri-môn để thờ lạy tại đó, và người tựa tay trên tôi, thì tôi phải cúi mình trong nhà Ri-môn; khi tôi cúi mình trong nhà Ri-môn, xin Đức Giê-hô-va tha cho đầy tớ Ngài trong điều nầy.'),
(9667, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 5, 19, 'OT', 'Và người nói với ông: "Hãy đi bình an." Ông liền đi khỏi người đó một đoạn đường.'),
(9668, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 5, 20, 'OT', 'Ghê-ha-xi, đầy tớ của Ê-li-sê, người của Đức Chúa Trời, nói: "Kìa, thầy tôi đã để Na-a-man, người Sy-ri, này không nhận điều gì từ tay người ấy, nhân danh Đức Giê-hô-va, tôi thề rằng tôi sẽ chạy theo và nhận một ít từ người ấy."'),
(9669, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 5, 21, 'OT', 'Ghê-ha-xi liền đuổi theo Na-a-man. Khi Na-a-man thấy ông chạy theo mình, ông ta liền bước xuống khỏi xe ngựa để đón ông, và hỏi: "Bình an chăng?"'),
(9670, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 5, 22, 'OT', 'Hắn nói: "Bình an! Thầy tôi sai tôi đến nói: Nầy, ngay bây giờ có hai người trai trẻ từ núi Ép-ra-im, thuộc con cái các đấng tiên tri, đến cùng tôi. Vậy xin ông vui lòng đưa cho họ một kikar bạc và hai bộ quần áo."'),
(9671, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 5, 23, 'OT', 'Na-a-man nói: "Hãy nhận lấy hai vạc bạc." Nhưng ông vẫn nài ép, rồi gói hai vạc bạc trong hai túi, cùng hai bộ quần áo, đặt lên cho hai đầy tớ mình, và họ khiêng đi trước mặt ông.'),
(9672, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 5, 24, 'OT', 'Khi người đến nơi tháp, liền nhận lấy từ tay họ, rồi cất vào nhà; sau đó cho những người kia đi, và họ ra đi.'),
(9673, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 5, 25, 'OT', 'Rồi người vào, đứng trước chủ mình. Ê-li-sê nói với người: "Ghê-ha-xi, ngươi đi đâu vậy?" Người đáp: "Tôi tớ ngài chẳng đi đâu cả."'),
(9674, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 5, 26, 'OT', 'Ngài phán cùng người rằng: "Lòng ta há chẳng đi với người sao, khi người ấy xây khỏi xe đi ra đón ngươi? Đây há phải lúc nhận lấy tiền bạc, nhận lấy áo xống, ô liu, vườn nho, chiên, bò, đầy tớ trai gái sao?"'),
(9675, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 5, 27, 'OT', 'Bệnh phong của Na-a-man sẽ bám chặt lấy ngươi và dòng dõi ngươi đời đời. Rồi người ấy đi ra khỏi mặt ông, da trắng như tuyết.'),
(9676, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 1, 'OT', 'Các con trai của các nhà tiên tri nói với Ê-li-sê: "Kìa, bây giờ chỗ mà chúng tôi đang ở cùng ông thì quá chật hẹp so với chúng tôi."'),
(9677, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 2, 'OT', 'Chúng tôi xin đi đến sông Giô-đanh, mỗi người lấy một cây xà, và chúng tôi sẽ làm một nơi ở tại đó. Người đáp: Hãy đi.'),
(9678, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 3, 'OT', 'Một người nói: "Xin ông vui lòng đi cùng các đầy tớ của ông." Ông đáp: "Tôi sẽ đi."'),
(9679, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 4, 'OT', 'Ông đi với họ. Khi đến sông Giô-đanh, họ đốn cây gỗ.'),
(9680, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 5, 'OT', 'Một người đang đốn cây, thì đầu cái rìu rơi xuống nước; người ấy kêu lên rằng: "Than ôi, thưa thầy, vì cái rìu ấy tôi có mượn!"'),
(9681, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 6, 'OT', 'Người của Đức Chúa Trời nói: "Nơi nào rơi?" Rồi người chỉ cho ông chỗ đó. Ông bèn chặt một khúc cây, ném vào đó, và cây sắt nổi lên.'),
(9682, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 7, 'OT', 'Bấy giờ người nói: "Hãy nhấc nó lên." Người đưa tay ra và lấy nó.'),
(9683, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 8, 'OT', 'Vua của Sy-ri đang giao chiến với Y-sơ-ra-ên, thì bàn luận với các tôi tớ mình rằng: "Ta sẽ đóng trại tại một nơi nào đó."'),
(9684, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 9, 'OT', 'Người của Đức Chúa Trời sai đi đến vua Y-sơ-ra-ên, nói rằng: Hãy giữ mình, chớ đi qua nơi này, vì tại đó người A-ram đã xuống.'),
(9685, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 10, 'OT', 'Vua Y-sơ-ra-ên sai người đến chỗ mà người của Đức Chúa Trời đã nói cho ông và cảnh cáo ông, ông liền giữ mình tại đó; không phải chỉ một lần hay hai lần.'),
(9686, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 11, 'OT', 'Lòng vua của Sy-ri bực tức về điều này, bèn gọi các tôi tớ mình và nói với họ: "Sao các ngươi không cho ta biết ai trong chúng ta đứng về phía vua Y-sơ-ra-ên?"'),
(9687, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 12, 'OT', 'Một người trong các đầy tớ người nói: "Thưa chúa tôi, không phải vậy, bệ hạ! Nhưng Ê-li-sê, đấng tiên tri ở Y-sơ-ra-ên, đã cho vua Y-sơ-ra-ên biết những lời mà bệ hạ nói trong buồng ngủ của mình."'),
(9688, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 13, 'OT', 'Bấy giờ, người nói: "Hãy đi và dò xem người ở đâu, để ta sai người đi bắt ông ấy." Rồi có người báo cho người biết rằng: "Kìa, ông ấy đang ở Đô-than."'),
(9689, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 14, 'OT', 'Người sai ngựa, xe chiến và đạo quân đông đảo đến đó; họ đến vào ban đêm và vây kín thành.'),
(9690, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 15, 'OT', 'Sáng sớm, đầy tớ của người của Đức Chúa Trời chỗi dậy và ra đi, thì thấy một đạo quân vây quanh thành, với ngựa và xe chiến. Người đầy tớ nói với người ấy: "Ôi, thưa thầy tôi, chúng ta phải làm sao?"'),
(9691, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 16, 'OT', 'Đừng sợ, vì những người ở cùng chúng ta đông hơn những người ở cùng họ.'),
(9692, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 17, 'OT', 'Ê-li-sê cầu nguyện và nói: "Lạy Đức Giê-hô-va, xin mở đôi mắt nó để nó thấy được." Đức Giê-hô-va bèn mở mắt người trai trẻ, và người ấy thấy; nầy, núi đầy những ngựa và xe lửa vây quanh Ê-li-sê.'),
(9693, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 18, 'OT', 'Khi chúng xuống đến gần ông, Ê-li-sê cầu nguyện cùng Đức Giê-hô-va và nói: "Xin hãy đánh dân này bằng sự mù lòa." Và Đức Giê-hô-va đánh chúng bằng sự mù lòa, đúng như lời Ê-li-sê.'),
(9694, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 19, 'OT', 'Ê-li-sê nói với họ: "Đây không phải là con đường, và đây cũng không phải là thành phố. Hãy theo tôi, tôi sẽ dẫn các ông đến người mà các ông đang tìm." Rồi ông dẫn họ đến Sa-ma-ri.'),
(9695, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 20, 'OT', 'Khi họ đến thành Sa-ma-ri, Ê-li-sê nói: "Lạy Đức Giê-hô-va, xin mở mắt những người nầy để họ thấy." Đức Giê-hô-va bèn mở mắt họ, họ thấy, và nầy, họ đang ở giữa thành Sa-ma-ri.'),
(9696, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 21, 'OT', 'Vua của Y-sơ-ra-ên nói với Ê-li-sê, khi thấy các người đó: "Thưa cha, tôi có nên đánh họ không? Tôi có nên đánh họ không?"'),
(9697, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 22, 'OT', 'Đừng giết họ! Những người mà ngươi bắt được bằng gươm và cung tên, ngươi lại muốn giết sao? Hãy đặt bánh và nước trước mặt họ, để họ ăn, uống, rồi đi về với chủ mình.'),
(9698, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 23, 'OT', 'Người cho họ ăn uống no nê, đãi đã một bữa tiệc lớn, rồi cho họ về, và họ đi đến chủ mình. Từ đó, các toán quân của Sy-ri không còn dám vào đất Y-sơ-ra-ên nữa.'),
(9699, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 24, 'OT', 'Sau những việc ấy, Bên Ha-đát, vua của Sy-ri, tập hợp toàn bộ đạo quân mình, rồi kéo lên và vây hãm Xa-ma-ri.'),
(9700, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 25, 'OT', 'Xảy ra một cơn đói lớn tại Sa-ma-ri; và nầy, họ vây thành cho đến nỗi đầu một con lừa bán được tám mươi miếng bạc, và một phần tư cab phân bồ câu giá năm miếng bạc.'),
(9701, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 26, 'OT', 'Vua Y-sơ-ra-ên đi ngang qua trên vách thành, thì một người đàn bà kêu lên cùng người rằng: "Xin cứu giúp, thưa chúa tôi là vua."'),
(9702, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 27, 'OT', 'Người nói: "Nếu Đức Giê-hô-va không cứu ngươi, ta sẽ cứu ngươi từ đâu? Từ sân đập lúa hay từ nơi ép rượu?"'),
(9703, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 28, 'OT', 'Vua nói với bà: "Bà gặp điều gì vậy?" Bà trả lời: "Người đàn bà này nói với tôi: ''Hãy đưa con bà đây, để hôm nay chúng ta ăn thịt nó, rồi ngày mai chúng ta sẽ ăn thịt con tôi.''"'),
(9704, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 29, 'OT', 'Chúng tôi đã nấu con trai tôi và ăn thịt cậu bé; rồi ngày hôm sau, tôi bảo người đàn bà ấy: "Hãy đưa con trai cô ra, để chúng ta ăn," thì cô ấy lại giấu con trai mình đi.'),
(9705, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 30, 'OT', 'Khi vua nghe lời người đàn bà ấy, thì xé áo mình ra; vua đang đi ngang qua trên tường thành, và dân chúng nhìn thấy, nầy, người mặc áo bằng bao gai ở trong sát da mình.'),
(9706, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 31, 'OT', 'Ông ấy nói: Đức Chúa Trời sẽ xử với tôi như vậy, và còn xử tệ hơn nữa, nếu hôm nay đầu của Ê-li-sê, con trai Xáp-hát, còn đứng trên vai người ấy.'),
(9707, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 32, 'OT', 'Ê-li-sê đang ngồi trong nhà, các bậc trưởng lão ngồi cùng người. Người sai một người đi trước đến cùng người, nhưng trước khi sứ giả đến nơi, người nói với các bậc trưởng lão: "Các ông có thấy không, tên con trai kẻ sát nhân này đã sai đến để lấy đầu ta sao? Hãy xem, khi sứ giả đến, hãy đóng cửa lại và giữ chặt người đó ở cửa. Chẳng phải tiếng chân chủ của người ấy đang theo sau sao?"'),
(9708, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 6, 33, 'OT', 'Đang khi người ấy còn nói chuyện với họ, thì nầy, sứ giả từ trên trời xuống cùng người; và người ấy nói: Nầy, tai họa nầy là từ Đức Giê-hô-va; tôi còn trông đợi Đức Giê-hô-va chi nữa?'),
(9709, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 7, 1, 'OT', 'Ê-li-sa nói: "Hãy nghe lời của Đức Giê-hô-va. Đức Giê-hô-va phán như vầy: Ngày mai vào giờ này, một sê-a bột mịn sẽ được bán với giá một sê-ken, và hai sê-a lúa mạch với một sê-ken, tại cổng thành Sa-ma-ri."'),
(9710, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 7, 2, 'OT', 'Vị quan cận vệ đang đỡ tay vua đáp lại người của Đức Chúa Trời và nói: "Này, nếu Đức Giê-hô-va làm các cửa sổ trên trời, thì điều nầy há có thể xảy ra sao?" Người ấy đáp: "Này, ngươi sẽ thấy điều đó bằng mắt mình, nhưng sẽ không ăn được từ đó."'),
(9711, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 7, 3, 'OT', 'Có bốn người phong cùi ở ngay lối vào cổng; họ nói với nhau: "Tại sao chúng ta cứ ngồi đây cho đến khi chết?"'),
(9712, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 7, 4, 'OT', 'Nếu chúng ta nói: "Chúng ta hãy vào thành," thì nạn đói đang ở trong thành, và chúng ta sẽ chết tại đó; còn nếu chúng ta ngồi yên tại đây, thì cũng sẽ chết. Vậy bây giờ hãy đến và đầu hàng trại quân của người Sy-ri; nếu họ để chúng ta sống, thì chúng ta sẽ sống; nếu họ giết chúng ta, thì chúng ta cũng chỉ chết mà thôi.'),
(9713, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 7, 5, 'OT', 'Họ chỗi dậy lúc rạng đông, đi đến trại quân của người Sy-ria; khi họ đến tận cùng trại quân người Sy-ria, thì thấy không một ai ở đó.'),
(9714, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 7, 6, 'OT', 'Đức Giê-hô-va khiến đạo quân của A-ram nghe được tiếng xe, tiếng ngựa, tiếng của một đạo quân lớn. Chúng liền nói với nhau: "Kìa, vua Y-sơ-ra-ên đã thuê các vua của dân Hít-ti và các vua của Ê-díp-tô đến đánh chúng ta."'),
(9715, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 7, 7, 'OT', 'Họ liền đứng dậy và chạy trốn vào lúc chập tối, bỏ lại các trại của mình, và các ngựa, các lừa của họ; trại quân ở nguyên trạng như nó vốn có; họ chạy trốn để cứu mạng sống mình.'),
(9716, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 7, 8, 'OT', 'Các người phong cùi nầy đến tận đầu trại, bèn vào một cái lều, ăn và uống ở đó, rồi lấy từ đó bạc, vàng và quần áo, đem đi chôn giấu; đoạn trở lại, vào một cái lều khác, lấy từ đó những vật nữa, rồi đi chôn giấu.'),
(9717, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 7, 9, 'OT', 'Họ nói với nhau: "Chúng ta làm điều nầy không phải đâu; hôm nay là ngày có tin tốt, mà chúng ta lại giữ im lặng. Nếu chúng ta đợi đến sáng mai, tai họa sẽ giáng trên chúng ta. Vậy bây giờ hãy đi, và báo cho nhà vua biết."'),
(9718, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 7, 10, 'OT', 'Họ liền đến, gọi người canh giữ thành, và thuật cho họ rằng: "Chúng tôi đã vào trại của quân Sy-ria, và nầy, chẳng thấy một người nào ở đó, cũng chẳng nghe tiếng người nào, chỉ thấy ngựa bị buộc, lừa bị buộc, và các trại vẫn còn nguyên như trước."'),
(9719, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 7, 11, 'OT', 'Các người giữ cổng liền kêu lên và báo tin vào trong cung vua.'),
(9720, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 7, 12, 'OT', 'Vua chổi dậy giữa đêm, nói cùng các tôi tớ mình: "Ta muốn cho các ngươi biết điều mà người Sy-ri đã làm cho chúng ta. Họ biết chúng ta đang đói, nên đã ra khỏi trại, lẩn trốn trong đồng ruộng, nói rằng: ''Khi dân trong thành ra, ta sẽ bắt sống họ, rồi vào thành.''"'),
(9721, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 7, 13, 'OT', 'Một người trong các đầy tớ của vua thưa rằng: "Xin hãy lấy năm con ngựa còn sót lại, tức là những con còn lại trong thành; vì chúng nó giống như toàn thể dân Y-sơ-ra-ên còn sót lại trong thành; này, tôi xin nói, chúng nó giống như toàn thể dân Y-sơ-ra-ên đã bị tiêu diệt. Vậy hãy sai người đi và xem thử."'),
(9722, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 7, 14, 'OT', 'Họ bèn lấy hai con ngựa kéo xe, và vua sai đi sau đạo quân của người Sy-ri, nói rằng: "Hãy đi xem."'),
(9723, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 7, 15, 'OT', 'Họ đi theo chúng cho đến tận sông Giô-đanh; và này, khắp dọc đường đầy những áo quần và đồ đạc mà người Sy-ri đã vứt bỏ trong cơn hoảng hốt. Các sứ giả bèn quay trở lại và báo cho vua biết.'),
(9724, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 7, 16, 'OT', 'Dân chúng ra đi, cướp phá trại quân của người Sy-ri. Một sê-a bột mịn được bán với giá một siếc-ken, và hai sê-a lúa mạch được bán với giá một siếc-ken, đúng như lời Đức Giê-hô-va.'),
(9725, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 7, 17, 'OT', 'Vua chỉ định viên quan cận vệ mà vua nương tựa vào tay ông, giữ chức coi sóc cửa thành; nhưng dân chúng giày đạp ông tại cửa thành, và ông đã chết, y như lời người của Đức Chúa Trời đã nói, khi vua xuống gặp ông.'),
(9726, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 7, 18, 'OT', 'Và đã xảy ra như lời người của Đức Chúa Trời nói với vua rằng: Ngày mai vào giờ này, tại cửa thành Sa-ma-ri, hai sê-a lúa mạch sẽ được một siếc-ên, và một sê-a bột mịn cũng sẽ được một siếc-ên.'),
(9727, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 7, 19, 'OT', 'Và viên tướng đáp lại người của Đức Chúa Trời rằng: "Thưa, nếu Đức Giê-hô-va làm ra các cửa sổ trên trời, thì điều nầy có thể xảy ra chăng?" Người ấy đáp: "Nhìn đây, ngươi sẽ thấy điều đó bằng chính mắt mình, nhưng ngươi sẽ không ăn từ đó."'),
(9728, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 7, 20, 'OT', 'Và điều đó đã xảy ra cho người ấy: dân chúng giày đạp lên người ấy trong cổng thành, và người ấy chết.'),
(9729, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 8, 1, 'OT', 'Ê-li-sê nói với người đàn bà mà ông đã khiến con trai bà sống lại rằng: "Hãy đứng dậy, đi cùng gia đình bà đến nơi nào bà có thể tạm cư; vì Đức Giê-hô-va đã gọi một nạn đói đến, và nó sẽ xảy ra trên đất trong bảy năm."'),
(9730, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 8, 2, 'OT', 'Người đàn bà ấy liền đứng dậy, làm theo lời người của Đức Chúa Trời; bà đi cùng gia đình mình và cư ngụ tại đất Phi-li-tin bảy năm.'),
(9731, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 8, 3, 'OT', 'Hết thời gian bảy năm, người đàn bà trở về từ xứ Phi-li-tin; bà đi thưa với vua xin lại nhà cửa và ruộng đất của mình.'),
(9732, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 8, 4, 'OT', 'Vua đang nói chuyện với Ghê-ha-xi, đầy tớ của người của Đức Chúa Trời, rằng: "Hãy kể cho ta nghe, xin ngươi, mọi việc lớn mà Ê-li-sê đã làm."'),
(9733, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 8, 5, 'OT', 'Người ấy đang thuật cho vua nghe về việc mình làm sống lại người chết, thì nầy, người đàn bà mà con trai bà đã được làm sống lại đang kêu khóc cùng vua về nhà cửa và đất đai của bà. Ghê-ha-xi nói: Thưa chúa tôi là vua, đây là người đàn bà, và đây là con trai bà, mà Ê-li-sê đã làm cho sống lại.'),
(9734, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 8, 6, 'OT', 'Vua hỏi người đàn bà, thì bà thuật lại cho vua. Vua bèn chỉ định một viên thái giám cho bà, nói rằng: "Hãy hoàn trả lại cho bà mọi thứ thuộc về bà, và mọi sản vật của ruộng đồng từ ngày bà bỏ đất ấy cho đến nay."'),
(9735, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 8, 7, 'OT', 'Ê-li-sê đến thành Đa-mách; bấy giờ Bên-ha-đát, vua nước Sy-ri, đang đau ốm; người ta báo cho vua biết rằng: "Người của Đức Chúa Trời đã đến đây."'),
(9736, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 8, 8, 'OT', 'Vua nói với Ha-xa-ên: "Hãy cầm lễ vật trong tay ngươi, đi gặp người của Đức Chúa Trời, và hỏi Đức Giê-hô-va qua người ấy, rằng: ''Tôi sẽ sống lại khỏi cơn bệnh này không?''"'),
(9737, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 8, 9, 'OT', 'Hát-sa-ên đi gặp ông, tay mang lễ vật gồm mọi thứ tốt lành của Đa-mách, nặng bốn mươi lạc đà, rồi đến đứng trước mặt ông và nói: "Con trai ngài, Bên-ha-đát, vua A-ram, sai tôi đến cùng ngài, để hỏi: ''Tôi có thể sống lại được khỏi cơn bệnh này chăng?''"'),
(9738, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 8, 10, 'OT', 'Ê-li-sê nói với người ấy: "Hãy đi, nói với anh ta: ''Anh sẽ khỏi bệnh''; nhưng Đức Giê-hô-va đã cho tôi thấy rằng anh ta chắc chắn sẽ chết."'),
(9739, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 8, 11, 'OT', 'Người đưa mặt lên và giữ nguyên như vậy cho đến khi xấu hổ, rồi người của Đức Chúa Trời khóc.'),
(9740, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 8, 12, 'OT', 'Ha-xa-ên hỏi: "Tại sao chúa tôi lại khóc?" Người đáp: "Vì tôi biết điều ác mà ngươi sẽ làm cho con cái Y-sơ-ra-ên: ngươi sẽ phóng hỏa các thành pháo mạnh của chúng, giết các thanh niên chúng bằng gươm, đập nát trẻ nhỏ chúng, và xé toang bụng các phụ nữ mang thai chúng."'),
(9741, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 8, 13, 'OT', 'Vậy Ha-xa-ên nói: "Kìa, tôi tớ ngài là con chó, sao có thể làm điều lớn lao nầy?" Ê-li-sê đáp: "Đức Giê-hô-va đã cho tôi thấy rằng ông sẽ làm vua trên A-ram."'),
(9742, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 8, 14, 'OT', 'Ông ấy rời khỏi Ê-li-sê, rồi đến cùng chủ mình. Chủ hỏi: "Ê-li-sê nói gì với ngươi?" Ông ấy đáp: "Người nói với tôi: ''Ngươi chắc chắn sẽ sống.''"'),
(9743, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 8, 15, 'OT', 'Ngày hôm sau, người ấy lấy một tấm vải dày, nhúng nước, rồi trải lên mặt mình, và người ấy chết. Ha-xa-ên lên ngôi thay cho người ấy.'),
(9744, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 8, 16, 'OT', 'Vào năm thứ năm đời của Yô-ram, con trai của A-háp, vua Ít-ra-en, khi Giô-sa-phát làm vua Giu-đa, thì Giô-ram, con trai của Giô-sa-phát, vua Giu-đa, lên ngôi vua.'),
(9745, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 8, 17, 'OT', 'Ba mươi hai tuổi người bắt đầu trị vì; người trị vì tám năm tại Giê-ru-sa-lem.'),
(9746, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 8, 18, 'OT', 'Người đi theo con đường của các vua Y-sơ-ra-ên, như nhà A-háp đã làm; vì con gái A-háp là vợ người; và người làm điều ác trước mặt Đức Giê-hô-va.'),
(9747, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 8, 19, 'OT', 'Đức Giê-hô-va không chịu tiêu diệt Giu-đa, vì Đa-vít tôi tớ Ngài, như Ngài đã hứa với ông rằng sẽ ban cho ông một ngọn đèn sáng luôn luôn cho con cháu ông.'),
(9748, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 8, 20, 'OT', 'Trong những ngày của người, Ê-đôm nổi dậy khỏi dưới tay Giu-đa, và họ lập một vua trên mình.'),
(9749, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 8, 21, 'OT', 'Vua Giô-ram đi đến Xai-rơ, và tất cả các xe chiến cùng đi với ông. Một đêm nọ, ông vùng dậy, đánh bại người Ê-đôm vây quanh mình và các sĩ quan chỉ huy các xe chiến; rồi dân chúng chạy trốn về các trại của họ.'),
(9750, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 8, 22, 'OT', 'Ê-đôm đã nổi dậy khỏi quyền cai trị của Giu-đa cho đến ngày nay. Vào lúc ấy, Líp-na cũng nổi dậy.'),
(9751, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 8, 23, 'OT', 'Phần còn lại của các việc của Giô-ram và tất cả những điều người đã làm, há chẳng chép trong sách Các Sự Việc của các Vua Giu-đa sao?'),
(9752, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 8, 24, 'OT', 'Vua Giô-ram nằm ngủ cùng các tổ tiên mình, và được chôn cùng các tổ tiên mình trong thành Đa-vít; rồi A-cha-xia, con trai ông, lên ngôi kế vị ông.'),
(9753, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 8, 25, 'OT', 'Trong năm thứ mười hai đời Giô-ram, con trai của A-háp, vua nước Ít-ra-en, thì A-ha-xi-a, con trai của Giô-ram, vua nước Giu-đa, lên ngôi làm vua.'),
(9754, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 8, 26, 'OT', 'Hai mươi hai tuổi, A-cha-xia bắt đầu trị vì; người trị vì một năm tại Giê-ru-sa-lem. Tên mẹ người là A-ta-li-a, con gái của Ôm-ri, vua của Y-sơ-ra-ên.'),
(9755, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 8, 27, 'OT', 'Mùa ông đi theo con đường của nhà A-háp, và làm điều ác trước mặt Đức Giê-hô-va như nhà A-háp đã làm; vì ông là con rể của nhà A-háp.'),
(9756, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 8, 28, 'OT', 'Mạc-thê-gia đi cùng với Giô-ram, con trai của A-háp, ra chiến trận chống lại Ha-xa-ên, vua của Sy-ria, tại Ra-mốt trong Ga-la-át; và người Sy-ria đã đánh trọng thương Giô-ram.'),
(9757, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 8, 29, 'OT', 'Vua Giô-ram trở về Giết-rê-ên để được chữa lành những vết thương mà người Sy-ria đã gây ra cho ông tại Ra-ma, khi ông chiến đấu với Ha-xa-ên, vua Sy-ria. Và A-cha-xia, con trai của Giô-ram, vua Giu-đa, đi xuống thăm Giô-ram, con trai của A-háp, tại Giết-rê-ên, vì ông ấy đang đau yếu.'),
(9758, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 1, 'OT', 'Ê-li-sê, đấng tiên tri, gọi một trong các môn đệ của các nhà tiên tri, rồi nói với người ấy: "Hãy thắt lưng, cầm lấy bình dầu này trong tay, và đi đến Ra-mốt trong Gileađ."'),
(9759, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 2, 'OT', 'Hãy đi đến đó, tìm thấy ở đó Giê-hu, con trai của Giô-sa-phát, con trai của Nim-si; rồi hãy vào, khiến người đứng dậy giữa anh em mình, và dẫn người vào một phòng trong.'),
(9760, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 3, 'OT', 'Hãy lấy vò dầu, đổ trên đầu người ấy và nói: "Đức Giê-hô-va phán như vầy: Ta đã xức dầu cho ngươi làm vua trên Y-sơ-ra-ên." Rồi hãy mở cửa chạy trốn, chớ chậm lại.'),
(9761, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 4, 'OT', 'Vậy người trai trẻ, là nhà tiên tri trẻ tuổi ấy, đi đến Ramôth trong đất Ga-la-át.'),
(9762, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 5, 'OT', 'Vừa khi người ấy đến, nầy, các quan trưởng của đạo binh đang ngồi; người ấy nói: "Tôi có việc cần nói với ông, thưa quan trưởng." Giê-hu hỏi: "Ngài nói với một trong tất cả chúng tôi sao?" Người ấy đáp: "Chính ông, thưa quan trưởng."'),
(9763, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 6, 'OT', 'Ông chỗi dậy, vào trong nhà; người đổ dầu trên đầu ông và nói với ông: "Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên phán như vầy: Ta đã xức dầu cho ngươi làm vua cai trị dân Đức Giê-hô-va, tức là Y-sơ-ra-ên."'),
(9764, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 7, 'OT', 'Ngươi hãy đánh diệt nhà A-háp, chủ ngươi, để ta báo thù huyết các tôi tớ ta là các nhà tiên tri và huyết mọi tôi tớ của Đức Giê-hô-va, do tay Ích-xa-bên.'),
(9765, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 8, 'OT', 'Cả nhà A-ha sẽ bị tiêu diệt; ta sẽ tiêu diệt khỏi A-ha kẻ còn tiểu vào tường, và cả kẻ bị giam giữ lẫn kẻ bị bỏ lại ở Ít-ra-en.'),
(9766, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 9, 'OT', 'Ta sẽ khiến nhà của A-cha bị tiêu diệt như nhà của Giê-rô-bô-am, con trai của Nê-bát, và như nhà của Ba-a-sa, con trai của A-hi-gia.'),
(9767, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 10, 'OT', 'Chó sẽ ăn Ize-bel tại phần đất của Y-xơ-rên, và sẽ không có ai chôn xác bà ấy. Rồi người mở cửa và trốn chạy.'),
(9768, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 11, 'OT', 'Rồi Giê-hu đi ra gặp các đầy tớ của chủ mình. Một người nói với người: "Bình an chăng? Tại sao tên điên rồ kia lại đến tìm ngươi?" Người đáp với họ: "Các ngươi biết người ấy và cách người ấy nói chuyện."'),
(9769, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 12, 'OT', 'Họ nói: "Hãy nói dối đi; hãy nói cho chúng tôi biết." Người ấy đáp: "Người ấy nói với tôi như thế này và như thế này, rằng: ''Đức Giê-hô-va phán như vầy: Ta đã xức dầu cho ngươi làm vua cai trị trên Y-sơ-ra-ên.''"'),
(9770, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 13, 'OT', 'Họ vội vàng đứng dậy, mỗi người lấy áo mình trải xuống dưới chân người ấy trên bậc thềm, rồi thổi kèn và reo lên: "Giê-hu làm vua!"'),
(9771, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 14, 'OT', 'Ê-hu, con trai của Giê-hô-sa-phát, con trai của Nim-si, âm mưu chống lại Giô-ram. Còn Giô-ram thì đang canh giữ Ra-mốt, trong đất Ga-la-át, cùng với toàn thể Y-sơ-ra-ên, vì sợ Ha-xa-ên, vua của A-ram.'),
(9772, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 15, 'OT', 'Vua Giô-ram trở về điều trị tại Y-xơ-rên vì những vết thương mà người Sy-ri đã gây ra cho ông, khi ông chiến đấu với Ha-xa-ên, vua Sy-ri. Rồi Giê-hu nói: "Nếu các ngươi đồng ý, thì đừng để một ai thoát khỏi thành mà đi báo tin tại Y-xơ-rên."'),
(9773, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 16, 'OT', 'Vậy Giê-hu cỡi xe ngựa và đi về Y-xơ-ra-en; vì Giô-ram đang nằm nghỉ tại đó. Và A-ha-xi-a, vua nước Giu-đa, đã xuống để thăm Giô-ram.'),
(9774, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 17, 'OT', 'Kìa, người lính canh đang đứng trên tháp canh tại Y-xơ-ra-en thấy đoàn người của Giê-hu khi ông đến gần, bèn kêu lên: "Tôi thấy một đoàn người!" Giô-ram nói: "Hãy lấy một người cỡi ngựa, sai đi đón họ và hỏi: ''Có bình an chăng?''"'),
(9775, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 18, 'OT', 'Một người cưỡi ngựa đi ra đón người đó và nói: "Vua hỏi: ''Bình an chăng?''" Nhưng Giê-hu đáp: "Ngươi có việc gì với sự bình an? Hãy quay lại phía sau ta." Người canh gác báo tin rằng: "Người đưa tin đã đến cùng họ, nhưng không trở lại nữa."'),
(9776, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 19, 'OT', 'Người ấy sai một người cưỡi ngựa thứ hai đi; người ấy đến cùng họ và nói: "Vua truyền rằng: ''Bình an chăng?''" Nhưng Giê-hu đáp: "Ngươi có việc gì với sự bình an? Hãy quay lại phía sau ta."'),
(9777, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 20, 'OT', 'Người canh gác báo tin rằng: "Người ấy đã đến nơi họ, nhưng không trở lại; và cách điều khiển xe giống như cách điều khiển của Giê-hu, con trai Nim-si, vì người ấy lái xe cuồng nhiệt."'),
(9778, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 21, 'OT', 'Vua Giô-ram bảo: "Hãy chuẩn bị xe!" Vậy người ta liền chuẩn bị xe của vua. Rồi vua Giô-ram của Y-sơ-ra-ên và vua A-cha-xia của Giu-đa cùng ra đi, mỗi người trên xe riêng của mình, đến đón Hê-u; và họ gặp Hê-u tại phần đất của Na-bốt, người Y-xơ-ra-en.'),
(9779, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 22, 'OT', 'Khi Giô-ram thấy Giê-hu, ông nói: "Bình an chăng, hỡi Giê-hu?" Nhưng Giê-hu đáp: "Bình an sao được, khi sự dâm loạn và phù phép nhiều vô kể của Ize-bel, mẹ ngươi, còn tồn tại?"'),
(9780, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 23, 'OT', 'Giô-ram quay tay lại và chạy trốn, rồi nói với A-cha-xia: "Có sự phản trắc, hỡi A-cha-xia!"'),
(9781, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 24, 'OT', 'Giê-hu hết sức giương cung bắn trúng Giô-ram giữa hai vai; mũi tên xuyên qua tim, và người ngã quỵ trong xe mình.'),
(9782, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 25, 'OT', 'Bấy giờ người nói với Bích-đa, viên chỉ huy của mình: "Hãy khiêng xác hắn lên, ném vào phần ruộng của Na-bốt, người Ghít-rê-ên; vì hãy nhớ rằng khi ta và ngươi cùng cỡi ngựa song song theo sau A-háp, cha người ấy, thì Đức Giê-hô-va đã giáng gánh nặng nầy trên người."'),
(9783, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 26, 'OT', 'Phải, ta đã thấy hôm qua máu của Na-bốt và máu các con trai nó, Đức Giê-hô-va phán; và ta sẽ báo ứng ngươi trên mảnh đất nầy, Đức Giê-hô-va phán. Vậy bây giờ, hãy khiêng xác nó ra, ném vào mảnh đất nầy, theo như lời Đức Giê-hô-va.'),
(9784, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 27, 'OT', 'Vua A-ha-xi-a xứ Giu-đa thấy điều đó, liền chạy trốn theo đường nhà vườn. Nhưng Giê-hu đuổi theo và ra lệnh: "Bắn cả hắn nữa, ngay trong cỗ xe, tại dốc lên Ghút, gần Íp-lê-am." Vậy người ta bắn ông tại đó. Nhưng ông vẫn chạy trốn đến Mê-ghi-đô và chết tại đó.'),
(9785, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 28, 'OT', 'Bấy giờ các tôi tớ người chở xác người về Giê-ru-sa-lem, và chôn người trong mồ mả của người cùng với các tổ phụ người tại thành Đa-vít.'),
(9786, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 29, 'OT', 'Vào năm thứ mười một đời Giô-ram, con trai của A-háp, thì A-ha-xi-a bắt đầu trị vì trên Giu-đa.'),
(9787, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 30, 'OT', 'Khi Giê-hu đến Giê-xe-ren, Ích-xa-bên nghe tin ấy, liền tô mắt, trang điểm đầu mình, rồi nhìn ra từ cửa sổ.'),
(9788, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 31, 'OT', 'Khi Giê-hu vào cổng, thì bà nói: "Xim-ri, bình an chăng, ngươi là kẻ giết chủ mình?"'),
(9789, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 32, 'OT', 'Người ngước mặt lên cửa sổ và nói: Ai thuộc phe ta? Ai vậy? Có hai hay ba thái giám nhìn ra theo người.'),
(9790, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 33, 'OT', 'Người bảo: "Ném nó xuống!" Họ liền ném nó xuống; máu bắn lên tường và lên các ngựa, rồi người ấy giày đạp lên.'),
(9791, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 34, 'OT', 'Vừa vào, ông ăn và uống xong, rồi nói: "Hãy đi, lo việc cho người bị rủa nầy, và chôn cô ta đi, vì cô ta là con gái của một vị vua."'),
(9792, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 35, 'OT', 'Họ đi chôn cất nàng, nhưng không tìm thấy gì nơi nàng ngoài cái đầu, đôi bàn chân và các lòng bàn tay.'),
(9793, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 36, 'OT', 'Họ trở lại và thuật lại cho ông. Ông nói: "Đây là lời của Đức Giê-hô-va, mà Ngài đã phán qua tôi tớ Ngài là Ê-li-a người Thi-si-bê, rằng: ''Tại phần đất Giê-xe-ren, chó sẽ ăn thịt của Ít-xa-bên.''"'),
(9794, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 9, 37, 'OT', 'Thi thể của Ít-sa-bên sẽ bị vứt bỏ như phân bò trên mặt đất tại phần đất Giếch-rê-ên, đến nỗi không ai nói được: "Đây là Ít-sa-bên."'),
(9795, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 1, 'OT', 'A-háp có bảy mươi con trai ở Sa-ma-ri. Rồi Giê-hu viết các bức thư và sai người mang đến Sa-ma-ri, cho các quan trưởng ở Giê-xơ-rên, các bậc trưởng lão và những người nuôi dạy các con trai của A-háp, rằng:'),
(9796, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 2, 'OT', 'Bây giờ, khi lá thư này đến các ngươi, và các ngươi có các con trai của chủ các ngươi ở cùng các ngươi, cùng với xe ngựa, ngựa chiến, một thành có vách thành vững chắc và khí giới;'),
(9797, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 3, 'OT', 'Hãy nhìn xem những người con trai tốt lành và ngay thẳng nhất trong các con trai của chủ các ngươi, lập người ấy lên ngôi vua của cha người ấy, và chiến đấu để bảo vệ nhà của chủ các ngươi.'),
(9798, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 4, 'OT', 'Họ hết sức kinh sợ, rồi nói: Này, hai vị vua còn không đứng vững được trước mặt người, huống chi chúng ta?'),
(9799, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 5, 'OT', 'Người quản lý nhà và người cai trị thành, các trưởng lão và những người nuôi dạy con cái, sai người đến nói với Giê-hu rằng: "Chúng tôi là tôi tớ ngài; mọi điều ngài truyền dạy chúng tôi, chúng tôi sẽ làm. Chúng tôi sẽ không lập ai làm vua; xin ngài làm điều tốt lành theo ý ngài."'),
(9800, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 6, 'OT', 'Người viết bức thư thứ hai cho họ, nói rằng: "Nếu các ngươi thuộc về ta và vâng nghe tiếng ta, hãy bắt các đầu của những người con trai chủ các ngươi, và mai đến giờ này hãy đến cùng ta tại Y-xơ-rên." Bấy giờ, bảy mươi người con trai của vua đang ở cùng các quan chức thành phố, những người đã nuôi dưỡng họ.'),
(9801, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 7, 'OT', 'Khi bức thư đến tay họ, họ liền bắt các con trai của vua, giết bảy mươi người, đặt đầu của họ vào các giỏ, rồi sai người mang đến cho Ghít-rê-ên.'),
(9802, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 8, 'OT', 'Một sứ giả đến và báo cho ông biết, nói: "Họ đã mang đầu của các con trai vua đến." Ông nói: "Hãy đặt chúng thành hai đống ở lối vào cổng cho đến sáng."'),
(9803, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 9, 'OT', 'Sáng hôm sau, người ra đi, đứng dậy và nói với toàn thể dân chúng: "Các ngươi hãy xét đoán tôi là người ngay thẳng. Này đây, tôi đã lập mưu nghịch lại chủ mình và giết người; nhưng ai đã giết tất cả những người nầy?"'),
(9804, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 10, 'OT', 'Hãy biết điều nầy, từ nay, chẳng có điều gì trong lời của Đức Giê-hô-va sẽ đổ xuống đất, tức lời mà Đức Giê-hô-va đã phán về nhà A-háp; vì Đức Giê-hô-va đã làm điều mà Ngài đã phán qua đầy tớ Ngài là Ê-li-a.'),
(9805, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 11, 'OT', 'Ê-xu giết hết những người còn sót lại thuộc nhà A-háp tại Xít-rên, cùng với tất cả các quan trưởng, bạn hữu thân tín và các thầy tế lễ của người, đến nỗi không để sót lại cho người ấy một ai.'),
(9806, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 12, 'OT', 'Người ấy chỗi dậy, đi ra đi và đến Sa-ma-ri. Người ấy đang ở nhà xén lông chiên trên đường.'),
(9807, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 13, 'OT', 'Ê-hu gặp các anh em của A-cha-xia, vua Giu-đa, và hỏi: "Các ông là ai?" Họ đáp: "Chúng tôi là anh em của A-cha-xia; chúng tôi đang đi xuống để chào các con trai của vua và các con trai của hoàng hậu."'),
(9808, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 14, 'OT', 'Người bảo: "Hãy bắt sống chúng!" Vậy họ bắt sống chúng, rồi giết tất cả bên cái hầm ở nhà cắt lông chiên, tất cả bốn mươi hai người; và người không để sót một ai trong số họ.'),
(9809, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 15, 'OT', 'Đoạn ấy, người đi từ đó và gặp được Giô-na-đáp, con trai của Rê-cáp, đang đến đón mình; người bèn chúc phước cho ông và nói với ông: "Lòng ngươi có ngay thẳng như lòng ta dành cho lòng ngươi chăng?" Giô-na-đáp đáp: "Có, thật vậy. Hãy đưa tay ngươi ra." Người bèn đưa tay ra, và ông lên cùng người vào xe.'),
(9810, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 16, 'OT', 'Hãy đi với tôi và xem lòng tôi sốt sắng vì Đức Giê-hô-va. Rồi họ cho người lên xe chiến của mình.'),
(9811, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 17, 'OT', 'Khi người đến Sa-ma-ri, người giết hết những kẻ còn sót lại thuộc về nhà A-háp tại Sa-ma-ri, cho đến khi tiêu diệt hoàn toàn họ, y như lời Đức Giê-hô-va đã phán dạy Ê-li-a.'),
(9812, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 18, 'OT', 'Vua Giê-hu triệu tập toàn thể dân chúng lại, rồi bảo họ: "A-háp chỉ phụng sự Ba-an một chút; còn Giê-hu sẽ phụng sự người ấy cách dồi dào."'),
(9813, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 19, 'OT', 'Bây giờ hãy gọi cho ta tất cả các tiên tri của Ba-anh, tất cả những kẻ phục vụ nó và tất cả các thầy tế lễ của nó; đừng để một ai vắng mặt; vì ta có một lễ tế lớn dâng cho Ba-anh; bất cứ ai vắng mặt sẽ không được sống. Nhưng Giê-hu làm điều này cách mưu mẹo, để tiêu diệt những kẻ thờ Ba-anh.'),
(9814, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 20, 'OT', 'Ê-xu bảo: "Hãy tuyên bố một lễ hội trọng đại cho Ba-an. Hãy triệu tập dân chúng!"'),
(9815, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 21, 'OT', 'Giê-hu sai sứ giả đi khắp Ít-ra-en; và tất cả những kẻ thờ Ba-anh đều đến, không một người nào vắng mặt. Họ vào đền thờ Ba-anh, và đền thờ Ba-anh đầy ắp người từ đầu đến cuối.'),
(9816, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 22, 'OT', 'Ông bảo người quản lý phòng để y phục: "Hãy mang áo ra cho tất cả những kẻ thờ Ba-anh." Người ấy mang áo ra cho họ.'),
(9817, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 23, 'OT', 'Ê-hu và Giô-hô-na-đáp con trai của Rê-cáp vào nhà của Ba-an, rồi nói với những kẻ thờ Ba-an rằng: "Hãy tìm kỹ và xem xét, đừng để một tôi tớ nào của Đức Giê-hô-va ở đây giữa các ngươi; chỉ những kẻ thờ Ba-an mà thôi."'),
(9818, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 24, 'OT', 'Họ vào để dâng tế lễ và lễ thiêu, thì Giê-hu đã đặt tám mươi người ở bên ngoài, và nói: "Bất kỳ người nào trong những người ta đã giao vào tay các ngươi mà trốn thoát, mạng sống hắn phải chuộc mạng sống ngươi."'),
(9819, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 25, 'OT', 'Khi người vừa dâng xong của lễ thiêu, thì Giê-hu nói với toán hộ vệ và các quan chỉ huy rằng: "Hãy vào, mỗi người đừng để ai thoát ra." Vậy họ dùng lưỡi gươm giết hết chúng; rồi toán hộ vệ và các quan chỉ huy ném xác chúng ra ngoài, rồi đi đến thành nhà Ba-anh.'),
(9820, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 26, 'OT', 'Họ đem các trụ thờ trong nhà Ba-al ra ngoài, rồi đốt cháy những thứ ấy.'),
(9821, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 27, 'OT', 'Họ đập nát trụ thờ Ba-al, phá hủy nhà thờ Ba-al và biến nơi ấy thành một cái nhà xí cho đến ngày nay.'),
(9822, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 28, 'OT', 'Vậy Giê-hu tiêu diệt thần Ba-anh khỏi Y-sơ-ra-ên.'),
(9823, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 29, 'OT', 'Chỉ các tội lỗi của Giê-rô-bô-am, con trai của Nê-bát, người đã khiến cho Ít-ra-en phạm tội, thì Giê-hu không từ bỏ những điều đó: các con bò vàng ở Bê-thên và cái ở Đan.'),
(9824, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 30, 'OT', 'Đức Giê-hô-va phán cùng Giê-hu: "Vì ngươi đã làm điều ngay thẳng trước mắt Ta, theo mọi điều Ta mong ước về nhà A-háp, nên con cháu đời thứ tư của ngươi sẽ ngồi trên ngôi nước I-sơ-ra-ên."'),
(9825, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 31, 'OT', 'Nhưng Giê-hu không giữ lấy việc đi theo luật pháp của Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên với cả tấm lòng mình; người không xây bỏ khỏi các tội lỗi của Giê-rô-bô-am, là tội lỗi mà Giê-rô-bô-am đã khiến cho Y-sơ-ra-ên phạm tội.'),
(9826, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 32, 'OT', 'Trong những ngày ấy, Đức Giê-hô-va bắt đầu cắt ngắn Ít-ra-en; và Ha-xa-ên đánh họ trên khắp các bờ cõi của Ít-ra-en.'),
(9827, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 33, 'OT', 'Từ sông Giô-đanh trở về phía đông mặt trời mọc, toàn thể đất xứ Ga-la-át, của người Ga-đi và Ru-bên, và của người Ma-na-se, từ A-rô-er, là nơi bên bờ sông Ác-nôn, cho đến toàn thể xứ Ga-la-át và Ba-san.'),
(9828, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 34, 'OT', 'Còn những việc khác của Giê-hu, và tất cả những điều ông đã làm, và mọi chiến công của ông, há chẳng ghi chép trong sách Các chuyện hàng ngày của các vua Y-sơ-ra-ên sao?'),
(9829, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 35, 'OT', 'Ê-xu nằm ngủ cùng các tổ phụ mình, người ta mai táng ông ở Xa-ma-ri. Ê-xa-hát, con trai ông, lên ngôi làm vua thế cho ông.'),
(9830, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 10, 36, 'OT', 'Thời gian mà Giê-hu trị vì trên Ít-ra-en tại Sa-ma-ri là hai mươi tám năm.'),
(9831, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 11, 1, 'OT', 'Bà A-tha-ly, mẹ của A-cha-xia, thấy con trai mình đã chết, bèn chỗi dậy diệt sạch toàn thể dòng dõi hoàng gia.'),
(9832, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 11, 2, 'OT', 'Nhưng Giô-sê-bát, con gái của vua Giô-ram, em gái của A-cha-xia, đã đem Giô-ách, con trai của A-cha-xia, và bí mật cứu cậu bé ra khỏi những người con trai của vua bị giết; họ giấu cậu cùng với vú nuôi trong phòng ngủ, nên cậu không bị giết chết vì A-ta-li-a.'),
(9833, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 11, 3, 'OT', 'Cô ấy ở cùng người đó trong nhà Đức Giê-hô-va, được giấu kín sáu năm, còn A-ta-li-a thì làm nữ vương cai trị đất nước.'),
(9834, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 11, 4, 'OT', 'Đến năm thứ bảy, Giô-ya-đa sai người đi gọi các quan chỉ huy ngàn người, các đội trưởng và các vệ binh, rồi dẫn họ đến nhà Đức Giê-hô-va. Ông lập giao ước với họ, khiến họ thề hứa trong nhà Đức Giê-hô-va, và cho họ xem hoàng tử.'),
(9835, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 11, 5, 'OT', 'Người truyền lệnh cho họ rằng: "Điều này là điều các ngươi phải làm: một phần ba trong các ngươi vào phiên trực trong ngày Sa-bát, và canh giữ khu vực bảo vệ cung điện của vua;'),
(9836, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 11, 6, 'OT', 'Một phần ba sẽ canh ở cổng Sau, một phần ba sẽ canh ở cổng phía sau hàng rào; các ngươi phải giữ vòng đai bảo vệ đền thờ, để nó không bị phá đổ.'),
(9837, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 11, 7, 'OT', 'Hai phần trong các ngươi, tất cả những người ra khỏi ngày Sa-bát, phải giữ vòng canh gác nhà Đức Giê-hô-va quanh vua.'),
(9838, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 11, 8, 'OT', 'Các ngươi hãy vây quanh vua, mỗi người cầm vũ khí trong tay; bất cứ ai tiến vào hàng rào, phải bị giết; và các ngươi phải ở bên cạnh vua khi người ra và khi người vào.'),
(9839, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 11, 9, 'OT', 'Các viên đội trưởng đã làm theo mọi điều mà thầy tế lễ Giô-ya-đa đã truyền; mỗi người nhận những thuộc hạ mình đến phiên trực trong ngày Sa-bát, cùng những người đang phiên ra về, rồi cùng đến với thầy tế lễ Giô-ya-đa.'),
(9840, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 11, 10, 'OT', 'Tư tế trao cho các viên chỉ huy trăm người những ngọn giáo và cái khiên của vua Đa-vít, là những thứ vốn thuộc về đền thờ của Đức Giê-hô-va.'),
(9841, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 11, 11, 'OT', 'Các vệ binh đứng đó, mỗi người tay cầm khí giới, từ bên phải đền thờ cho đến bên trái đền thờ, quanh bàn thờ và đền thờ, chung quanh vua.'),
(9842, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 11, 12, 'OT', 'Người đưa hoàng tử ra, đặt mão triều lên đầu người và trao cho người bảng chứng cớ; họ tôn người làm vua và xức dầu cho người; rồi vỗ tay reo: "Cầu vua vạn tuế!"'),
(9843, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 11, 13, 'OT', 'Bà A-tha-lya nghe tiếng ồn ào của dân chúng, bèn đi đến nơi dân chúng ở trong đền thờ Đức Giê-hô-va.'),
(9844, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 11, 14, 'OT', 'Bà A-ta-li-a nhìn thấy, nầy vua đang đứng bên một cột trụ theo nghi thức, các quan trưởng và những người thổi kèn đứng gần vua, toàn thể dân trong xứ vui mừng và thổi kèn; bà A-ta-li-a xé áo mình ra, kêu lên: "Phản nghịch! Phản nghịch!"'),
(9845, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 11, 15, 'OT', 'Đoạn thầy tế lễ Giô-ya-đa truyền lệnh cho các viên chỉ huy, những người chỉ huy đoàn quân, và nói với họ: "Hãy dẫn nàng ra khỏi khu vực đền thờ; bất cứ ai theo sau nàng, hãy giết bằng gươm." Vì thầy tế lễ đã nói: "Đừng để nàng bị giết trong đền thờ của Đức Giê-hô-va."'),
(9846, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 11, 16, 'OT', 'Họ tra tay vào nàng; nàng đi theo lối ngựa vào nhà vua, và bị giết tại đó.'),
(9847, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 11, 17, 'OT', 'Và Giô-ya-đa lập giao ước giữa Đức Giê-hô-va và nhà vua, và giữa dân chúng, để dân chúng thuộc về Đức Giê-hô-va; và cũng giữa nhà vua và dân chúng.'),
(9848, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 11, 18, 'OT', 'Toàn thể dân trong xứ vào đền thờ của Ba-anh, phá hủy nơi ấy, đập tan các bàn thờ và các tượng hình tượng của nó, nghiền nát hoàn toàn; còn Mát-tan, thầy tế lễ của Ba-anh, thì bị giết chết ngay trước các bàn thờ. Rồi thầy tế lễ đặt các chức việc canh giữ đền thờ của Đức Giê-hô-va.'),
(9849, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 11, 19, 'OT', 'Ông đem các quan chỉ huy ngàn người, các quan cai đội và đội canh gác, cùng toàn thể dân trong xứ; họ đưa hoàng tử từ đền thờ Đức Giê-hô-va xuống, rồi đi qua cổng đội canh gác mà đến cung điện vua. Rồi hoàng tử ngồi trên ngôi vua của các vua.'),
(9850, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 11, 20, 'OT', 'Cả dân trong xứ đều vui mừng, và thành được yên lặng; còn A-tha-lia thì họ giết bằng gươm tại nhà vua.'),
(9851, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 11, 21, 'OT', 'Giô-ách lên ngôi lúc được bảy tuổi.'),
(9852, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 12, 1, 'OT', 'Năm thứ bảy đời Giê-hu, Giô-ách lên ngôi làm vua và trị vì bốn mươi năm tại Giê-ru-sa-lem. Tên mẹ người là Xi-bi-a, quê ở Bê-ersê-va.'),
(9853, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 12, 2, 'OT', 'Giô-ách làm điều ngay thẳng trong mắt Đức Giê-hô-va trong suốt mọi ngày đời mình, mọi ngày mà thầy tế lễ Giô-ia-đa hướng dẫn ông.'),
(9854, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 12, 3, 'OT', 'Nhưng các nơi cao thì chưa bị dẹp bỏ; dân chúng vẫn tiếp tục dâng của lễ thiêu và đốt hương tại các nơi cao ấy.'),
(9855, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 12, 4, 'OT', 'Vua Giô-a-s nói với các thầy tế lễ: "Tất cả tiền của những vật thánh được mang vào đền thờ Đức Giê-hô-va, tiền của mỗi người qua đếm, tiền giá chuộc mạng mình, và mọi tiền mà ai đem dâng vào đền thờ Đức Giê-hô-va tùy lòng muốn,"'),
(9856, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 12, 5, 'OT', 'Các thầy tế lễ hãy nhận tiền từ những người quen biết mình, và chính họ phải sửa chữa những chỗ hư hại của đền thờ, bất cứ nơi nào tìm thấy hư hại.'),
(9857, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 12, 6, 'OT', 'Đến năm thứ hai mươi ba đời vua Giô-ách, các thầy tế lễ vẫn chưa sửa chữa các chỗ nứt nẻ của đền thờ.'),
(9858, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 12, 7, 'OT', 'Vua Giô-ách gọi thầy tế lễ Giô-ya-đa và các thầy tế lễ, rồi nói với họ: "Tại sao các ngươi không sửa chữa các chỗ nứt nẻ của đền thờ? Từ nay, đừng nhận tiền từ những người quen các ngươi nữa, mà phải giao tiền ấy để sửa các chỗ nứt nẻ của đền thờ."'),
(9859, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 12, 8, 'OT', 'Các thầy tế lễ không nhận tiền từ dân chúng, cũng không sửa chữa các chỗ hư hại của đền thờ.'),
(9860, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 12, 9, 'OT', 'Vua Giô-ya-đa, thầy tế lễ, lấy một cái hòm, đục một lỗ trên nắp của nó, rồi đặt nó gần bàn thờ, bên phải khi người ta vào nhà của Đức Giê-hô-va. Các thầy tế lễ giữ cửa đưa vào đó tất cả tiền bạc được mang đến nhà của Đức Giê-hô-va.'),
(9861, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 12, 10, 'OT', 'Khi thấy tiền bạc trong hòm quá nhiều, thì viên ký lục của vua và thầy tế lễ thượng phẩm cùng lên, rồi họ buộc tiền vào các túi và đong đếm số tiền tìm được trong nhà Đức Giê-hô-va.'),
(9862, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 12, 11, 'OT', 'Họ trao số bạc đã được giao vào tay những người làm công việc, những người quản lý tại đền thờ Đức Giê-hô-va, và họ dùng số bạc đó trả cho các thợ mộc và thợ xây đang làm việc trong đền thờ Đức Giê-hô-va.'),
(9863, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 12, 12, 'OT', 'Và cho các thợ xây, các thợ cưa đá, và để mua gỗ và đá đã cưa để sửa chữa những chỗ sứt mẻ trong nhà của Đức Giê-hô-va, và cho mọi thứ chi phí cho ngôi nhà nhằm sửa chữa nó.'),
(9864, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 12, 13, 'OT', 'Nhưng những tiền bạc dâng vào đền thờ Đức Giê-hô-va không được dùng để làm những cái chậu bạc, những cái đèn, những cái bát, những cái kèn, hay bất kỳ đồ vật bằng vàng hoặc đồ vật bằng bạc nào cho đền thờ Đức Giê-hô-va.'),
(9865, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 12, 14, 'OT', 'Họ sẽ trao số tiền đó cho các thợ làm công việc, và họ sẽ dùng số tiền ấy để sửa chữa đền thờ của Đức Giê-hô-va.'),
(9866, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 12, 15, 'OT', 'Họ không cần phải kiểm tra những người nhận tiền trong tay mình để giao cho thợ làm việc, vì họ làm việc đó cách trung thực.'),
(9867, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 12, 16, 'OT', 'Tiền đền tội và tiền chuộc tội không được mang vào nhà Đức Giê-hô-va; chúng thuộc về các thầy tế lễ.'),
(9868, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 12, 17, 'OT', 'Bấy giờ, Hát-xa-ên, vua của Sy-ria, đi lên, tấn công Gát và chiếm lấy nó. Rồi Hát-xa-ên quyết định tiến lên Giê-ru-sa-lem.'),
(9869, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 12, 18, 'OT', 'Vua Giô-ách xứ Giu-đa lấy tất cả các vật thánh mà các vua Giu-đa là Giô-sa-phát, Giô-ram và A-cha-xia, tổ tiên người, đã biệt riêng ra, cùng các vật thánh riêng của người, và lấy tất cả vàng bạc tìm thấy trong kho đền thờ Đức Giê-hô-va và trong kho vua, rồi sai mang đến Ha-xa-ên, vua Sy-ria; và người ấy rút khỏi Giê-ru-sa-lem.'),
(9870, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 12, 19, 'OT', 'Phần còn lại của các việc Giô-ách đã làm và mọi điều ông thực hiện, há chẳng chép trong sách Các việc ngày xưa của các vua Giu-đa sao?'),
(9871, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 12, 20, 'OT', 'Các tôi tớ của ông đứng dậy làm phản, và đánh giết Giô-ách trong nhà Mi-lô, nơi dẫn xuống Si-la.'),
(9872, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 12, 21, 'OT', 'Và Giô-xa-bát, con trai của Si-mết, và Giê-hô-xa-bát, con trai của Sô-mê, là các đầy tớ người, đánh người, và người qua đời; họ chôn người cùng các tổ phụ người trong thành Đa-vít; rồi A-ma-xia, con trai người, lên ngôi làm vua thay cho người.'),
(9873, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 13, 1, 'OT', 'Trong năm hai mươi ba của đời Giô-ách, con trai A-cha-xia, vua nước Giu-đa, thì Giê-hô-a-cha, con trai của Giê-hu, lên làm vua cai trị trên Ít-ra-en tại Xô-rem, và trị vì được mười bảy năm.'),
(9874, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 13, 2, 'OT', 'Và người làm điều ác trong mắt Đức Giê-hô-va, đi theo những tội lỗi của Giê-rô-bô-am, con trai của Nê-bát, người đã khiến cho Ít-ra-en phạm tội; người không từ bỏ những điều đó.'),
(9875, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 13, 3, 'OT', 'Đức Giê-hô-va nổi giận cùng Y-sơ-ra-ên, và Ngài đã phó họ vào tay Ha-xa-ên, vua của A-ram, và vào tay Bên-ha-đát, con trai của Ha-xa-ên, suốt mọi ngày ấy.'),
(9876, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 13, 4, 'OT', 'Vậy nên, Giô-a-cha cầu xin Đức Giê-hô-va, và Đức Giê-hô-va lắng nghe người; vì Ngài thấy sự khốn khổ của Ít-ra-en, do vua A-ram đã đè nén họ.'),
(9877, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 13, 5, 'OT', 'Đức Giê-hô-va ban cho Y-sơ-ra-ên một đấng cứu rỗi, và họ ra khỏi tay người Sy-ria; con cái Y-sơ-ra-ên ở trong các trại của mình như trước kia.'),
(9878, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 13, 6, 'OT', 'Dầu vậy, họ không từ bỏ các tội lỗi của nhà Giê-rô-bô-am, người đã khiến Ít-ra-en phạm tội; họ vẫn tiếp tục như thế; và cả cây thờ A-she-ra cũng vẫn còn đứng ở Sa-ma-ri.'),
(9879, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 13, 7, 'OT', 'Vì người đã không để lại cho Giô-a-cha một dân nào cả, ngoại trừ năm mươi người cỡi ngựa, mười cỗ xe và mười ngàn bộ binh; vì vua A-ram đã tiêu diệt họ, và khiến họ như bụi đất bị giẫm đạp.'),
(9880, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 13, 8, 'OT', 'Phần còn lại của các việc Giô-a-ha-đát, mọi điều người làm và các chiến công người, há chẳng chép trong sách Các việc trong các ngày đời các vua của Y-sơ-ra-ên sao?'),
(9881, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 13, 9, 'OT', 'Vua Giô-aha-xa nằm ngủ cùng các tổ tiên mình, và người ta chôn ông trong thành Sa-ma-ri; rồi Giô-ash, con trai ông, lên ngôi kế vị vua thay ông.'),
(9882, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 13, 10, 'OT', 'Trong năm thứ ba mươi bảy đời vua Giô-ách, vua của Giu-đa, thì Giô-ách, con trai của Giô-ách-ách, lên ngôi vua cai trị trên Ít-ra-en tại Xô-mê-ri, và trị vì được mười sáu năm.'),
(9883, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 13, 11, 'OT', 'Người đã làm điều ác trước mặt Đức Giê-hô-va, không xây bỏ khỏi mọi tội lỗi của Giê-rô-bô-am, con trai của Nê-bát, người đã khiến cho Ít-ra-en phạm tội; người đã đi theo các điều ấy.'),
(9884, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 13, 12, 'OT', 'Phần còn lại của các việc của Giô-ách, và mọi điều người đã làm, cùng các chiến công người đã thực hiện khi chiến đấu với A-ma-xia, vua nước Giu-đa, thì chẳng phải đã chép trong sách Các Sự Việc trong Các Ngày của các vua Ít-ra-en sao?'),
(9885, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 13, 13, 'OT', 'Vua Giô-ách nằm nghỉ cùng các tổ tiên mình; và Giê-rô-bô-am lên ngôi kế vị. Giô-ách được chôn cất tại Xô-ma-rim, cùng các vua của Y-sơ-ra-ên.'),
(9886, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 13, 14, 'OT', 'Ê-li-sê bị đau ốm vì căn bệnh mà ông sẽ chết. Giô-ách, vua của Y-sơ-ra-ên, xuống thăm ông, khóc trên mặt ông và nói: "Cha tôi, cha tôi! Xe và ngựa của Y-sơ-ra-ên!"'),
(9887, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 13, 15, 'OT', 'Ê-li-sê nói với người ấy: "Hãy lấy cung và các mũi tên." Người ấy bèn lấy cung và các mũi tên đến cùng ông.'),
(9888, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 13, 16, 'OT', 'Người nói với vua Y-sơ-ra-ên: "Hãy đặt tay ngươi trên cây cung." Vua liền đặt tay mình lên, và Ê-li-sê đặt tay mình trên tay vua.'),
(9889, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 13, 17, 'OT', 'Hãy mở cửa sổ về hướng đông. Người ấy liền mở cửa sổ. Rồi Ê-li-sê nói: Hãy bắn tên đi. Người ấy bèn bắn. Ê-li-sê nói: Mũi tên giải cứu của Đức Giê-hô-va, và mũi tên giải cứu khỏi A-ram; ngươi sẽ đánh bại dân A-ram tại A-phéc cho đến khi tiêu diệt chúng hoàn toàn.'),
(9890, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 13, 18, 'OT', 'Người ấy nói: "Hãy lấy các mũi tên." Ông ta bèn lấy. Đoạn người ấy nói với vua Y-sơ-ra-ên: "Hãy đánh xuống đất." Ông ta bèn đánh xuống đất ba lần rồi dừng lại.'),
(9891, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 13, 19, 'OT', 'Người của Đức Chúa Trời nổi giận cùng ông, và nói: "Ngươi đáng lẽ phải đánh năm hoặc sáu lần; như vậy ngươi đã đánh Xy-ri đến nỗi tiêu diệt nó; nhưng bây giờ ngươi chỉ đánh nó ba lần mà thôi."'),
(9892, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 13, 20, 'OT', 'Ê-li-sê qua đời, rồi người ta chôn ông. Các toán quân Ma-áp xâm nhập vào trong đất nước vào đầu năm.'),
(9893, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 13, 21, 'OT', 'Xảy ra khi họ đang chôn một người, thì thấy một đoàn lính, họ bèn ném người đó xuống mồ của Ê-li-sê. Người đó vừa được hạ xuống và chạm vào xương của Ê-li-sê thì sống lại, đứng lên trên đôi chân mình.'),
(9894, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 13, 22, 'OT', 'Vua Ha-xa-ên của A-ram đã áp bức Ít-ra-en suốt mọi ngày của Giô-ha-ách.'),
(9895, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 13, 23, 'OT', 'Đức Giê-hô-va thương xót họ, đoái thương họ, và trở lại nhìn đến họ vì giao ước của Ngài với Áp-ra-ham, Y-sác và Gia-cốp; Ngài không chịu tiêu diệt họ, cũng không đuổi họ khỏi trước mặt Ngài cho đến nay.'),
(9896, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 13, 24, 'OT', 'Vua Ha-xa-ên của A-ram qua đời; và Bên-ha-đát, con trai người, lên ngôi vua thay cho người.'),
(9897, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 13, 25, 'OT', 'Và Giô-ách, con trai của Giô-a-cha, đã lấy lại các thành từ tay Bên-ha-đát, con trai của Ha-xa-ên, là những thành mà Bên-ha-đát đã chiếm từ tay Giô-a-cha, cha của người, trong chiến tranh. Giô-ách đã đánh bại Bên-ha-đát ba lần và lấy lại các thành của Ít-ra-en.'),
(9898, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 14, 1, 'OT', 'Trong năm thứ hai đời Giô-ách, con trai của Giô-aha-xa, vua Ít-ra-en, thì A-ma-xia, con trai của Giô-ách, vua Giu-đa, lên ngôi vua.'),
(9899, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 14, 2, 'OT', 'Hai mươi lăm tuổi, người bắt đầu trị vì; và người trị vì hai mươi chín năm tại Giê-ru-sa-lem. Tên mẹ người là Giô-hê-đan, người Giê-ru-sa-lem.'),
(9900, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 14, 3, 'OT', 'Vua A-ma-xia làm điều ngay thẳng trong mắt Đức Giê-hô-va, nhưng không như vua Đa-vít tổ tiên mình; người làm theo mọi điều vua Giô-a-s cha mình đã làm.'),
(9901, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 14, 4, 'OT', 'Chỉ có các nơi cao thì chưa bị loại bỏ; dân chúng vẫn tiếp tục dâng của lễ và đốt hương trên các nơi cao ấy.'),
(9902, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 14, 5, 'OT', 'Sau khi vương quốc đã được củng cố trong tay người, thì người đã giết các đầy tớ đã giết vua cha người.'),
(9903, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 14, 6, 'OT', 'Nhưng các con trai của những kẻ giết người, vua không giết; y làm theo điều đã chép trong sách Luật pháp Môi-se, mà Đức Giê-hô-va đã truyền rằng: "Cha không bị xử tử vì con, con cũng không bị xử tử vì cha; mỗi người phải bị xử tử vì tội riêng của mình."'),
(9904, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 14, 7, 'OT', 'Người đã đánh bại Ê-đôm trong Thung lũng Muối, mười ngàn người; và chiếm lấy Sê-la trong trận chiến, rồi đặt tên cho nơi ấy là Gia-ktê-ên, cho đến ngày nay.'),
(9905, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 14, 8, 'OT', 'Sau đó, A-ma-xia sai các sứ giả đến Jê-hô-ách, con trai của Jê-hô-a-ha, con trai của Giê-hu, vua của Y-sơ-ra-ên, nói rằng: Hãy đến, chúng ta hãy nhìn mặt nhau.'),
(9906, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 14, 9, 'OT', 'Vua Giô-ách của Y-sơ-ra-ên sai sứ đến vua A-ma-xia của Giu-đa, nói rằng: "Cây chà là gai ở Li-băng đã sai đến cây bách ở Li-băng, nói rằng: ''Hãy gả con gái ngươi cho con trai ta làm vợ''; nhưng có một con thú rừng đi ngang qua Li-băng, giày đạp cây chà là gai."'),
(9907, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 14, 10, 'OT', 'Ngươi đã đánh bại Ê-đôm, và lòng ngươi đã tự đắc; hãy tự hào và ở tại nhà ngươi; tại sao ngươi phải gây chiến tranh để chuốc lấy tai họa, khiến ngươi và cả Giu-đa cùng ngã xuống?'),
(9908, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 14, 11, 'OT', 'Nhưng Amat-xia không chịu nghe. Bấy giờ Giô-ách, vua của Y-sơ-ra-ên, đi lên; và ông cùng Amat-xia, vua của Giu-đa, nhìn mặt nhau tại Bết-sê-mết thuộc về Giu-đa.'),
(9909, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 14, 12, 'OT', 'Giô-đa bị đánh bại trước mặt Ít-ra-en, và mỗi người chạy trốn về trại của mình.'),
(9910, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 14, 13, 'OT', 'Vua Giô-ách của Y-sơ-ra-ên bắt vua A-ma-xia của Giu-đa, con trai của Giô-ách, con trai của A-cha-xia, tại Bết-sê-mết, rồi đi đến Giê-ru-sa-lem, và phá tường thành Giê-ru-sa-lem từ cổng Ép-ra-im cho đến cổng Góc, dài bốn trăm thước.'),
(9911, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 14, 14, 'OT', 'Và người lấy tất cả vàng và bạc, cùng mọi đồ vật được tìm thấy trong đền thờ Đức Giê-hô-va và trong các kho tàng của cung vua, cùng con cháu những người bảo lãnh, rồi trở về Sa-ma-ri.'),
(9912, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 14, 15, 'OT', 'Phần còn lại của các việc Giô-ách đã làm, cùng quyền năng người và những gì người đã chiến đấu cùng A-ma-xia, vua nước Giu-đa, há chẳng chép trong sách Các sự việc hàng năm của các vua Ít-ra-en sao?'),
(9913, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 14, 16, 'OT', 'Giê-hô-ách nằm ngủ cùng các tổ phụ mình, và được chôn cất tại Sa-ma-ri cùng các vua của Y-sơ-ra-ên; và Giê-rô-bô-am, con trai ông, lên ngôi vua thay cho ông.'),
(9914, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 14, 17, 'OT', 'Am-xtia, con trai của Giô-ách, vua nước Giu-đa, sống thêm mười lăm năm sau khi Giô-ách, con trai của Giê-hô-ách, vua nước Y-sơ-ra-ên, qua đời.'),
(9915, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 14, 18, 'OT', 'Còn các việc khác của Am-xa-ia, há chẳng chép trong sách Các sự việc trong đời các vua Giu-đa sao?'),
(9916, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 14, 19, 'OT', 'Họ lập mưu nghịch cùng người tại Giê-ru-sa-lem; vua bèn trốn đến La-kích. Nhưng họ sai người đuổi theo đến La-kích, và giết người tại đó.'),
(9917, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 14, 20, 'OT', 'Họ khiêng ông trên những con ngựa, và ông được chôn cất tại Giê-ru-sa-lem cùng với các tổ tiên của mình trong thành Đa-vít.'),
(9918, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 14, 21, 'OT', 'Toàn thể dân Giu-đa lấy A-xa-ri-ah, khi người lên mười sáu tuổi, và lập người làm vua thay cho cha người là A-ma-xia.'),
(9919, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 14, 22, 'OT', 'Người xây dựng lại Ê-la và khôi phục nó về cho Giu-đa, sau khi vua an giấc cùng các tổ tiên của mình.'),
(9920, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 14, 23, 'OT', 'Năm thứ mười lăm đời Am-xa-xia, con trai của Giô-ash, vua nước Giu-đa, thì Giê-rô-bô-am, con trai của Giô-ách, vua nước Ít-ra-en, bắt đầu trị vì tại Sa-ma-ri, và trị vì bốn mươi mốt năm.'),
(9921, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 14, 24, 'OT', 'Vua làm điều ác trước mặt Đức Giê-hô-va; người không từ bỏ mọi tội lỗi của Giê-rô-bô-am con trai của Nê-bát, người đã khiến cho Ít-ra-en phạm tội.'),
(9922, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 14, 25, 'OT', 'Chính người đã khôi phục lại bờ cõi của Y-sơ-ra-ên, từ lối vào Ha-mát cho đến biển A-ra-vah, theo lời của Đức Giê-hô-va Đức Chúa Trời Ít-ra-en, mà Ngài đã phán qua tay đầy tớ Ngài là Giô-na, con trai của A-mi-tai, đấng tiên tri, người Ghát Hê-phẹr.'),
(9923, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 14, 26, 'OT', 'Đức Giê-hô-va thấy sự khốn khổ của Y-sơ-ra-ên rất nặng: không còn kẻ bị giam, cũng không còn kẻ sót lại, và không có ai giúp đỡ cho Y-sơ-ra-ên.'),
(9924, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 14, 27, 'OT', 'Đức Giê-hô-va chưa từng phán sẽ xóa bỏ danh của Y-sơ-ra-ên khỏi dưới trời; và Ngài đã cứu họ bằng tay của Y-ru-bô-am, con trai của Giô-ách.'),
(9925, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 14, 28, 'OT', 'Còn những việc khác của Giê-rô-bô-am, và mọi điều người đã làm, cùng các chiến công của người, cách người đánh giặc và cách người giành lại Đa-mách và Ha-mát để phục hồi cho Giu-đa thuộc về Ít-ra-en, thì chẳng phải tất cả những điều ấy đã được chép trong sách Các sự việc hàng ngày của các vua Ít-ra-en sao?'),
(9926, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 14, 29, 'OT', 'Giê-rô-bô-am nằm nghỉ cùng các tổ phụ mình, cùng các vua Y-sơ-ra-ên; và Xa-cha-ri, con trai người, lên ngôi vua thế cho người.'),
(9927, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 1, 'OT', 'A-xa-ria, con trai của A-ma-xia, vua nước Giu-đa, lên ngôi vua trong năm thứ hai mươi bảy đời Giê-rô-bô-am, vua Ít-ra-en.'),
(9928, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 2, 'OT', 'Mười sáu tuổi thì người bắt đầu trị vì; và người trị vì năm mươi hai năm tại Giê-ru-sa-lem. Tên mẹ người là Giê-ca-li-a, người Giê-ru-sa-lem.'),
(9929, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 3, 'OT', 'Vua Giô-tham làm điều phải trước mắt Đức Giê-hô-va, giống như mọi điều mà cha ông là A-ma-xia đã làm.'),
(9930, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 4, 'OT', 'Chỉ có điều các nơi cao thì chưa bị bỏ đi; dân chúng vẫn tiếp tục dâng của lễ và đốt hương trên các nơi cao ấy.'),
(9931, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 5, 'OT', 'Đức Giê-hô-va làm cho vua bị phung cho đến ngày vua qua đời, và vua sống trong một ngôi nhà riêng biệt. Còn Giô-tham, con trai vua, thì cai quản trong cung, xét xử dân sự của đất nước.'),
(9932, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 6, 'OT', 'Còn các việc khác của A-xa-ria, và mọi điều ông đã làm, há chẳng được chép trong sách Các sự việc trong đời các vua Giu-đa sao?'),
(9933, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 7, 'OT', 'Az-ri-a ngủ cùng các tổ tiên mình; người ta chôn ông cùng các tổ tiên mình trong thành Đa-vít. Giô-tham, con trai ông, lên ngôi làm vua thay ông.'),
(9934, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 8, 'OT', 'Năm thứ ba mươi tám đời vua A-xa-ria, vua xứ Giu-đa, Xa-cha-ri, con trai của Giê-rô-bô-am, lên ngôi làm vua cai trị trên Ít-ra-en tại Xô-mê-ri trong sáu tháng.'),
(9935, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 9, 'OT', 'Vua ấy làm điều ác trước mặt Đức Giê-hô-va, như các tổ tiên người đã làm; người không xây bỏ các tội lỗi của Giê-rô-bô-am, con trai của Nê-bát, người đã khiến cho Ít-ra-en phạm tội.'),
(9936, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 10, 'OT', 'Sa-lum, con trai của Gia-bết, âm mưu chống nghịch người, đánh giết người trước mặt dân chúng, rồi lên ngôi thay thế người.'),
(9937, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 11, 'OT', 'Phần còn lại về các việc của Xa-cha-ri, nầy, đều chép trong sách Các sự việc đời đời của các vua Y-sơ-ra-ên.'),
(9938, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 12, 'OT', 'Đây là lời của Đức Giê-hô-va mà Ngài đã phán cho Giê-hu, rằng: Con cháu ngươi sẽ ngồi trên ngôi nước của Y-sơ-ra-ên cho đến đời thứ tư. Và điều đó đã xảy ra như vậy.'),
(9939, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 13, 'OT', 'Sa-lum, con trai của Ya-béch, lên ngôi làm vua trong năm thứ ba mươi chín đời Út-xia, vua nước Giu-đa; người trị vì được một tháng tại Sa-ma-ri.'),
(9940, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 14, 'OT', 'Mê-na-hem, con trai của Ga-đi, từ Tir-za đi lên, đến Sa-ma-ri, đánh giết Sa-lum, con trai của Gia-bết, tại Sa-ma-ri, rồi lên ngôi vua thay người.'),
(9941, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 15, 'OT', 'Phần còn lại về các việc của Sa-lum và âm mưu mà người đã thực hiện, thì nầy, đều đã chép trong sách Các Lịch Sử của các vua Y-sơ-ra-ên.'),
(9942, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 16, 'OT', 'Bấy giờ, Mê-na-hem đánh thành Típ-sa và mọi người ở đó, cùng toàn cõi đất nó từ Tít-sa, vì thành không chịu mở cửa cho ông, nên ông đánh phá, và chọc thủng bụng mọi phụ nữ đang mang thai trong thành.'),
(9943, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 17, 'OT', 'Năm thứ ba mươi chín đời vua A-xa-ria trị vì nước Giu-đa, thì Mê-na-hem, con trai của Ga-đi, lên ngôi làm vua cai trị trên Ít-ra-en tại Sa-ma-ri trong mười năm.'),
(9944, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 18, 'OT', 'Vua ấy làm điều ác trước mặt Đức Giê-hô-va; người không từ bỏ các tội lỗi của Giê-rô-bô-am con trai của Nê-bát, người đã khiến cho Ít-ra-en phạm tội, suốt mọi ngày đời người.'),
(9945, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 19, 'OT', 'Phù, vua nước A-si-ri, đến đánh đất nước ấy; và Mê-na-hem đưa cho Phù một ngàn ta-lâng bạc, để tay người ấy giúp mình củng cố vương quyền trong tay mình.'),
(9946, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 20, 'OT', 'Vua Mê-na-hem lấy tiền của Ít-ra-en, của mọi người giàu có quyền thế, mỗi người năm mươi si-ckên bạc, để nộp cho vua A-đu. Rồi vua A-đu trở về, và không ở lại trong xứ đó.'),
(9947, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 21, 'OT', 'Còn các việc khác của Mê-na-hem và mọi điều ông làm, há chẳng được chép trong sách Các Sự Việc Hằng Ngày của các vua Y-sơ-ra-ên sao?'),
(9948, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 22, 'OT', 'Mê-na-hem nằm ngủ cùng các tổ tiên mình, và Pekahiah, con trai ông, lên ngôi làm vua thay ông.'),
(9949, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 23, 'OT', 'Năm thứ năm mươi đời vua A-xa-ria xứ Giu-đa, thì Pê-ca-hia, con trai của Mê-na-hem, lên làm vua cai trị trên Ít-ra-en tại Sa-ma-ri, và trị vì được hai năm.'),
(9950, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 24, 'OT', 'Người làm điều ác trước mặt Đức Giê-hô-va; người không từ bỏ những tội lỗi của Giê-rô-bô-am con trai Nê-bát, là tội đã gây cho Ít-ra-en phạm tội.'),
(9951, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 25, 'OT', 'Pekah, con trai của Remaliah, một viên tướng của ông, âm mưu nghịch lại ông; và người đã đánh giết ông tại Sa-ma-ri, trong cung điện của nhà vua, cùng với Argob và Arieh; và cùng người có năm mươi người Ga-la-át; người đã giết ông và lên ngôi vua thay ông.'),
(9952, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 26, 'OT', 'Còn các việc khác của Phê-ca-gia và tất cả những điều ông đã làm, đều đã chép trong sách Các niên kỷ của các vua Y-sơ-ra-ên.'),
(9953, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 27, 'OT', 'Trong năm thứ năm mươi hai đời U-xi-a, vua nước Giu-đa, thì Phê-ca, con trai của Rê-ma-ly-a, lên làm vua cai trị trên Ít-ra-en tại Sa-ma-ri, và trị vì hai mươi năm.'),
(9954, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 28, 'OT', 'Vua ấy làm điều ác trước mặt Đức Giê-hô-va; người không từ bỏ các tội lỗi của Giê-rô-bô-am, con trai của Nê-bát, kẻ đã khiến cho Ít-ra-en phạm tội.'),
(9955, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 29, 'OT', 'Trong những ngày Pê-ca, vua Ít-ra-en, thì Tiếc-lát Phi-lê-se, vua A-si-ri, đến và chiếm lấy Y-giôn, A-bên Bết Ma-a-cha, Gia-nô-ách, Kê-đe, Hát-so, đất Ga-la-át, và cả miền Ga-li-lê, toàn bộ đất Nép-ta-li; rồi ông ta đem dân chúng đi đày sang A-si-ri.'),
(9956, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 30, 'OT', 'Hô-xê-a, con trai của Ê-la, lập mưu nghịch cùng Pê-ka, con trai của Rê-ma-ly-a, rồi đánh và giết người ấy, và lên ngôi thay cho người, trong năm thứ hai mươi đời Giô-tham, con trai của Út-xi-a.'),
(9957, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 31, 'OT', 'Phần còn lại của các việc của Phê-ka và tất cả những điều ông đã làm, thì ghi chép trong sách Các sự việc đời ngày xưa của các vua Y-sơ-ra-ên.'),
(9958, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 32, 'OT', 'Vào năm thứ hai đời Pê-ka, con trai của Rê-ma-lia, vua Ít-ra-en, thì Giô-tham, con trai của Óc-xia, vua Giu-đa, bắt đầu trị vì.'),
(9959, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 33, 'OT', 'Hai mươi lăm tuổi, người bắt đầu trị vì; người trị vì mười sáu năm tại Giê-ru-sa-lem. Tên mẹ người là Giê-ru-sa, con gái Xa-đốc.'),
(9960, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 34, 'OT', 'Và người đã làm điều ngay thẳng trong mắt Đức Giê-hô-va, giống như mọi điều mà cha mình là Ô-xi-a đã làm.'),
(9961, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 35, 'OT', 'Nhưng các nơi cao vẫn chưa bị bỏ đi; dân chúng vẫn tiếp tục dâng tế lễ và đốt hương trên các nơi cao. Người ấy đã xây cổng trên của nhà Đức Giê-hô-va.'),
(9962, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 36, 'OT', 'Còn các việc khác của Yô-tham mà người đã làm, há chẳng chép trong sách Các Việc Kỷ Niên của các vua Giu-đa sao?'),
(9963, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 37, 'OT', 'Trong những ngày ấy, Đức Giê-hô-va bắt đầu sai Rê-xin, vua nước Sy-ri, và Phê-ca, con trai Rê-ma-lia, đến chống lại Giu-đa.'),
(9964, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 15, 38, 'OT', 'Vua Yô-tham nằm ngủ cùng các tổ tiên mình và được chôn cùng các tổ tiên mình trong thành Đa-vít, cha của ông; và A-hát, con trai ông, lên ngôi vua thay ông.'),
(9965, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 16, 1, 'OT', 'Trong năm thứ mười bảy đời của Phê-ka, con trai của Rê-ma-ly-a, A-cha, con trai của Giô-tham, vua nước Giu-đa, lên ngôi làm vua.'),
(9966, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 16, 2, 'OT', 'Ahát hai mươi tuổi khi người bắt đầu trị vì, và trị vì mười sáu năm tại Giê-ru-sa-lem; người không làm điều ngay thẳng trước mắt Đức Giê-hô-va, Đức Chúa Trời của người, như Đa-vít, cha người.'),
(9967, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 16, 3, 'OT', 'Người đi theo con đường của các vua Y-sơ-ra-ên, và cũng khiến con trai mình đi qua lửa, theo những điều gớm ghiếc của các dân tộc mà Đức Giê-hô-va đã đuổi ra khỏi trước mặt con cái Y-sơ-ra-ên.'),
(9968, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 16, 4, 'OT', 'Và người dâng tế lễ và đốt hương trên các nơi cao, trên các ngọn đồi, và dưới mọi cây xanh tươi.'),
(9969, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 16, 5, 'OT', 'Bấy giờ Rê-xin, vua của Á-ram, và Phê-ca, con trai của Rê-ma-lia, vua của Y-sơ-ra-ên, đi lên Giê-ru-sa-lem để gây chiến; họ vây hãm A-xách, nhưng không thể nào thắng được.'),
(9970, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 16, 6, 'OT', 'Đúng lúc ấy, Rê-xin, vua của Sy-ria, đã đoạt lại Ê-la-thơ về cho Sy-ria, và đuổi người Giu-đa khỏi Ê-la-thơ; rồi người Sy-ria đến Ê-la-thơ và ở đó cho đến ngày nay.'),
(9971, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 16, 7, 'OT', 'A-cha sai sứ giả đến Tiếc-lát Phi-lê-se, vua xứ A-si-ri, nói rằng: Tôi là tôi tớ và con của ngài; xin ngài hãy lên và cứu tôi khỏi tay vua A-ram và khỏi tay vua Y-sơ-ra-ên, những kẻ đang nổi lên nghịch lại tôi.'),
(9972, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 16, 8, 'OT', 'A-cha lấy bạc và vàng có trong đền thờ của Đức Giê-hô-va và trong kho tàng của cung điện vua, rồi sai mang đi dâng lễ vật cho vua Ái-thu.'),
(9973, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 16, 9, 'OT', 'Vua A-si-ri nghe theo người ấy; vua A-si-ri đi lên Đa-mách, chiếm lấy thành ấy, bắt dân chúng nó đi đày sang Ki-rơ, và giết Rê-xin.'),
(9974, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 16, 10, 'OT', 'Vua A-cha đi đến Đa-mách để gặp Ti-ghạt-phi-lé-xe, vua A-si-ri; và người thấy cái bàn thờ tại Đa-mách. Vua A-cha sai đến thầy tế lễ U-ri-gia mẫu bàn thờ và kiểu vẽ của nó, theo đúng mọi cách chế tác của nó.'),
(9975, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 16, 11, 'OT', 'Và U-ri-gia thầy tế lễ đã xây bàn thờ, y như mọi điều vua A-cha sai từ Đa-mách; thầy tế lễ U-ri-gia đã làm như thế, trước khi vua A-cha trở về từ Đa-mách.'),
(9976, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 16, 12, 'OT', 'Khi vua từ Đa-mách về, vua thấy bàn thờ; vua lại gần bàn thờ và dâng của lễ thiêu lên đó.'),
(9977, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 16, 13, 'OT', 'Rồi người dâng lễ thiêu và lễ vật chay của mình, đổ nước libation của mình, và rảy huyết các lễ xàm hòa của mình trên bàn thờ.'),
(9978, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 16, 14, 'OT', 'Và cái bàn thờ đồng vốn ở trước mặt Đức Giê-hô-va, người đem đi khỏi trước nhà, khỏi giữa bàn thờ và nhà của Đức Giê-hô-va, rồi đặt nó bên cạnh bàn thờ, về phía bắc.'),
(9979, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 16, 15, 'OT', 'Vua A-cha truyền lệnh cho thầy tế lễ U-ri-gia rằng: "Hãy dâng trên bàn thờ lớn lễ thiêu buổi sáng, lễ thực vật buổi chiều, lễ thiêu và lễ thực vật của nhà vua, lễ thiêu và lễ thực vật cùng lễ rưới nước của toàn dân trong xứ; và hãy rưới trên đó mọi huyết lễ thiêu, mọi huyết lễ giết tế; còn bàn thờ bằng đồng thì để riêng cho ta dùng cầu hỏi."'),
(9980, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 16, 16, 'OT', 'Và U-ri-a, thầy tế lễ, làm theo mọi điều vua A-cha truyền dặn.'),
(9981, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 16, 17, 'OT', 'Vua A-cha tháo dỡ những tấm viền trang trí trên các bệ đỡ, và tháo bỏ cái bồn rửa khỏi các bệ đó; còn cái biển thì ông hạ xuống khỏi những con bò bằng đồng ở dưới nó, rồi đặt cái biển ấy trên một nền lát đá.'),
(9982, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 16, 18, 'OT', 'Và cái hành lang của ngày Sa-bát mà họ đã xây trong đền thờ, cùng với lối vào bên ngoài của nhà vua, thì ông chuyển khỏi đền thờ của Đức Giê-hô-va vì vua A-si-ri.'),
(9983, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 16, 19, 'OT', 'Còn những việc khác mà A-cha đã làm, thì chẳng phải đã chép trong sách Các sự việc hàng năm của các vua Giu-đa sao?'),
(9984, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 16, 20, 'OT', 'A-cha nằm với các tổ tiên mình, và được chôn cùng các tổ tiên mình trong thành Đa-vít; và Ê-xe-chia, con trai ông, lên ngôi kế vị ông.'),
(9985, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 1, 'OT', 'Trong năm thứ mười hai đời vua A-cha nước Giu-đa, thì Ô-sê con trai Ê-la bắt đầu trị vì tại Sa-ma-ri trên nước Ít-ra-en trong chín năm.'),
(9986, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 2, 'OT', 'Vua làm điều ác trong mắt Đức Giê-hô-va, nhưng không giống như các vua Y-sơ-ra-ên đã làm trước mặt người.'),
(9987, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 3, 'OT', 'Salach-man-xết, vua xứ A-si-ri, kéo lên nghịch cùng người; và Hô-sê-a phục người, và dâng lễ vật cho người.'),
(9988, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 4, 'OT', 'Vua nước A-ssy bị bắt gặp âm mưu nơi Hô-sê; vì người này đã sai các sứ giả đến So, vua Ê-díp-tô, và không dâng lễ vật cho vua A-ssy như từng làm hằng năm. Bấy giờ vua A-ssy bắt giam người và tống giam trong ngục.'),
(9989, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 5, 'OT', 'Vua nước A-si-ri đi lên khắp cả đất nước, đến thành Sa-ma-ri và vây hãm thành đó trong ba năm.'),
(9990, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 6, 'OT', 'Trong năm thứ chín đời Hô-sê, vua nước A-si-ri chiếm lấy Sa-ma-ri, và bắt dân Y-sơ-ra-ên đem sang A-si-ri, rồi định cư họ tại Ha-lách, bên sông Ha-bô, gần Ga-za-an, và các thành của người Ma-đai.'),
(9991, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 7, 'OT', 'Vì con cái Y-sơ-ra-ên đã phạm tội nghịch cùng Đức Giê-hô-va Đức Chúa Trời của chúng, là Đấng đã đem chúng lên khỏi đất Ê-díp-tô, ra khỏi tay Pha-ra-ôn, vua Ê-díp-tô, và chúng đã kính sợ các thần khác.'),
(9992, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 8, 'OT', 'Họ đi theo các luật lệ của các dân tộc mà Đức Giê-hô-va đã đuổi ra khỏi trước mặt con cái Ít-ra-en, và theo các vua Ít-ra-en đã làm.'),
(9993, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 9, 'OT', 'Con cái Y-sơ-ra-ên đã làm những điều không ngay thẳng chống nghịch lại Đức Giê-hô-va Đức Chúa Trời của chúng, và chúng đã xây cho mình các nơi cao trong mọi thành phố của chúng, từ các tháp canh cho đến các thành có vách thành.'),
(9994, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 10, 'OT', 'Họ dựng những trụ thờ và các trụ đá cho mình trên mọi ngọn đồi cao và dưới mọi cây xanh tươi.'),
(9995, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 11, 'OT', 'Họ dâng hương trên mọi nơi cao, như các dân tộc mà Đức Giê-hô-va đã đuổi ra khỏi trước mặt họ; và họ làm những điều ác để chọc giận Đức Giê-hô-va.'),
(9996, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 12, 'OT', 'Họ thờ lạy các hình tượng mà Đức Giê-hô-va đã phán cùng họ: Các ngươi không được làm điều này.'),
(9997, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 13, 'OT', 'Đức Giê-hô-va cảnh cáo dân Y-sơ-ra-ên và dân Giu-đa bằng lời của mọi nhà tiên tri và mọi đấng tiên kiến, rằng: "Hãy trở lại khỏi các đường lối ác của các ngươi, và giữ các điều răn, các luật lệ ta, tức là toàn thể luật pháp mà ta đã truyền cho tổ tiên các ngươi, và mà ta đã sai các tôi tớ ta là các nhà tiên tri đến cùng các ngươi."'),
(9998, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 14, 'OT', 'Họ không chịu nghe, mà lại cứng cổ mình như cổ cha ông họ, những người không tin nơi Đức Giê-hô-va Đức Chúa Trời của họ.'),
(9999, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 15, 'OT', 'Họ đã từ chối các mạng luật của Ngài, và giao ước mà Ngài đã lập với tổ phụ họ, và các lời chứng mà Ngài đã làm chứng cho họ; họ đi theo điều hư không và trở nên hư không, và đi theo các dân tộc xung quanh họ, mà Đức Giê-hô-va đã dặn họ không được làm như các dân ấy.'),
(10000, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 16, 'OT', 'Họ đã từ bỏ mọi điều răn của Đức Giê-hô-va Đức Chúa Trời mình, và làm cho mình hai con bò con bằng kim loại đúc, dựng lên một cây A-she-ra, thờ lạy toàn thể thiên thể trên trời, và phục vụ thần Ba-anh.'),
(10001, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 17, 'OT', 'Họ khiến con trai và con gái mình đi ngang qua lửa; họ dùng bói toán và thầy phù thủy; họ bán mình để làm điều ác trước mặt Đức Giê-hô-va, khiến Ngài nổi giận.'),
(10002, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 18, 'OT', 'Đức Giê-hô-va đã rất giận dữ cùng Y-sơ-ra-ên, và đuổi họ ra khỏi mặt Ngài; chẳng còn sót lại chi ngoài chi phái Giu-đa mà thôi.'),
(10003, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 19, 'OT', 'Cũng vậy, Giu-đa không giữ các điều răn của Đức Giê-hô-va Đức Chúa Trời mình, mà đi theo các luật lệ của Ít-ra-en mà họ đã lập ra.'),
(10004, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 20, 'OT', 'Đức Giê-hô-va từ chối toàn thể dòng dõi Y-sơ-ra-ên, khiến họ bị khốn khổ, và phó họ vào tay những kẻ cướp phá, cho đến khi Ngài đuổi họ ra khỏi mặt Ngài.'),
(10005, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 21, 'OT', 'Vì Y-sơ-ra-ên đã rời khỏi nhà Đa-vít, và họ đã tôn Giê-rô-bô-am, con trai của Nê-bát, làm vua; chính Giê-rô-bô-am đã khiến Y-sơ-ra-ên lìa bỏ Đức Giê-hô-va, và khiến họ phạm tội lớn.'),
(10006, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 22, 'OT', 'Các con trai của Y-sơ-ra-ên tiếp tục phạm mọi tội lỗi mà Giê-rô-bô-am đã phạm; họ không từ bỏ những điều đó.'),
(10007, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 23, 'OT', 'Cho đến khi Đức Giê-hô-va đuổi Y-sơ-ra-ên khỏi trước mặt Ngài, y như điều Ngài đã phán qua tay tất cả các tiên tri, tôi tớ của Ngài. Vậy nên, Y-sơ-ra-ên bị lưu đày khỏi đất đai mình đến A-thi-ri, cho đến ngày nay.'),
(10008, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 24, 'OT', 'Vua nước A-si-ri đem người từ Ba-by-lôn, và từ Cu-tha, và từ A-va, và từ Ha-mát, và từ Xe-pha-ra-vim, rồi đặt họ vào các thành của Sa-ma-ri thay cho con cái Ít-ra-en; họ chiếm lấy Sa-ma-ri và ở trong các thành ấy.'),
(10009, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 25, 'OT', 'Vào lúc đầu họ ở đó, họ không kính sợ Đức Giê-hô-va; nên Đức Giê-hô-va sai những con sư tử vào giữa họ, và những con sư tử giết chết một số người trong họ.'),
(10010, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 26, 'OT', 'Bấy giờ họ nói cùng vua A-si-ri rằng: Các dân tộc mà ngài đã bắt đi và đặt vào các thành của Sa-ma-ri không biết luật lệ của Đức Chúa Trời đất; nên Ngài đã sai những con sư tử đến giữa họ, và nầy, những con sư tử đang giết họ, vì họ không biết luật lệ của Đức Chúa Trời đất.'),
(10011, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 27, 'OT', 'Vua A-si-ri ra lệnh rằng: "Hãy mang một trong các thầy tế lễ mà các ngươi đã bắt đi từ nơi đó trở lại đây; người ấy phải đi sống ở đó và dạy dân chúng cách thờ phượng Đức Chúa Trời của đất này."'),
(10012, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 28, 'OT', 'Một trong các thầy tế lễ mà người ta đã bắt đi đày từ Sa-ma-ri đã đến ở tại Bê-thên và dạy họ phải kính sợ Đức Giê-hô-va thể nào.'),
(10013, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 29, 'OT', 'Dân vô phái nào cũng tự làm các thần của mình, rồi đặt chúng trong các đền thờ trên các nơi cao mà những người từ Sa-ma-ri đã xây; mỗi phái đặt thần của mình trong các thành phố nơi chúng nó ở.'),
(10014, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 30, 'OT', 'Dân thành Ba-by-lôn làm hình tượng Su-cốt-bê-nốt; dân thành Cu-tha làm hình tượng Néc-ganh; dân thành Ha-mát làm hình tượng A-si-ma.'),
(10015, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 31, 'OT', 'Dân Avít làm hình tượng Nibhaz và Tartak; còn dân Sê-pha-vim thì thiêu các con mình trong lửa để dâng cho Adram-mê-lêch và Anam-mê-lêch, các thần của người Sê-pha-vim.'),
(10016, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 32, 'OT', 'Họ kính sợ Đức Giê-hô-va, nhưng lại tự chọn những người trong số họ làm thầy tế lễ các nơi cao, và những người này dâng của lễ cho họ trong các đền thờ các nơi cao.'),
(10017, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 33, 'OT', 'Họ kính sợ Đức Giê-hô-va, nhưng cũng thờ các thần của mình, theo quy tắc của các dân tộc mà họ đã bị đem đi từ đó.'),
(10018, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 34, 'OT', 'Cho đến ngày nay họ vẫn làm theo các tục lệ xưa; họ không kính sợ Đức Giê-hô-va, cũng không làm theo các luật lệ, mạng lệnh, luật pháp và điều răn mà Đức Giê-hô-va đã truyền cho con cháu của Gia-cốp, mà Ngài đặt tên là Y-sơ-ra-ên.'),
(10019, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 35, 'OT', 'Đức Giê-hô-va lập giao ước với họ và truyền cho họ rằng: Các ngươi sẽ không được kính sợ các thần khác, không được cúi lạy chúng, không được hầu việc chúng, cũng không được dâng của lễ cho chúng.'),
(10020, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 36, 'OT', 'Chỉ Đức Giê-hô-va, là Đấng đã đem các ngươi ra khỏi đất Ai-cập bằng quyền năng lớn và cánh tay giang ra, thì các ngươi phải kính sợ, và các ngươi phải thờ lạy Ngài, và các ngươi phải dâng tế lễ cho Ngài.'),
(10021, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 37, 'OT', 'Các điều luật, các phán quyết, luật pháp và mệnh lệnh mà Ngài đã viết cho các ngươi, các ngươi phải giữ để thực hiện trọn đời; và các ngươi sẽ không được kính sợ các thần khác.'),
(10022, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 38, 'OT', 'Giao ước mà Ta đã lập với các ngươi, các ngươi không được quên; các ngươi cũng không được kính sợ các thần khác.'),
(10023, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 39, 'OT', 'Nhưng các ngươi phải kính sợ Đức Giê-hô-va Đức Chúa Trời các ngươi; chính Ngài sẽ giải cứu các ngươi khỏi tay mọi kẻ thù nghịch các ngươi.'),
(10024, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 40, 'OT', 'Họ không chịu nghe, nhưng cứ làm theo cách thức ban đầu của mình.'),
(10025, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 17, 41, 'OT', 'Dân các nước ấy kính sợ Đức Giê-hô-va, nhưng cũng thờ lạy các tượng chạm của chúng; cả con cái và cháu chắt chúng nữa, cứ như cách tổ tiên mình đã làm, chúng cũng làm cho đến ngày nay.'),
(10026, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 1, 'OT', 'Vào năm thứ ba đời vua Hô-sê, con trai của Ê-la, vua Ít-ra-en, thì Ê-xê-chia, con trai của A-cha, làm vua Giu-đa.'),
(10027, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 2, 'OT', 'Hai mươi lăm tuổi, ông lên ngôi vua; ông trị vì hai mươi chín năm tại Giê-ru-sa-lem. Tên mẹ ông là A-bi, con gái Xa-cha-ri.'),
(10028, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 3, 'OT', 'Vua Ê-xê-chia làm điều ngay thẳng trong mắt Đức Giê-hô-va, giống như tất cả những gì vua Đa-vít, cha người, đã làm.'),
(10029, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 4, 'OT', 'Người đã dẹp bỏ các nơi cao, đập bể các trụ đá, chặt bỏ cây A-she-ra, và đập tan con rắn bằng đồng mà Môi-se đã làm, vì đến những ngày ấy con cái Ít-ra-en vẫn còn đốt hương cho nó; người gọi nó là Nehushtan.'),
(10030, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 5, 'OT', 'Đức vua tin cậy nơi Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en, và sau ông, không có ai giống như ông trong số tất cả các vua Giu-đa, cũng không có ai trong những người đã có trước ông.'),
(10031, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 6, 'OT', 'Vì người gắn bó với Đức Giê-hô-va, không rời bỏ Ngài, và tuân giữ các điều răn mà Đức Giê-hô-va đã truyền cho Môi-se.'),
(10032, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 7, 'OT', 'Đức Giê-hô-va ở cùng người; và ở khắp mọi nơi người ra đi, người đều thành công. Người chống cự vua Ái-thu, và không phục vụ người ấy.'),
(10033, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 8, 'OT', 'Người đánh bại người Phi-li-tin cho đến tận Ách-đót và vùng biên giới của chúng, từ tháp canh cho đến thành có vách thành.'),
(10034, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 9, 'OT', 'Vào năm thứ tư đời vua Ê-xê-chia, tức là năm thứ bảy đời Hô-sê con trai Ê-la, vua Ít-ra-en, thì San-man-ê-xe, vua A-xi-ri, kéo lên nghịch cùng Sa-ma-ri và vây thành ấy.'),
(10035, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 10, 'OT', 'Sau ba năm, họ chiếm được thành ấy, vào năm thứ sáu đời Ê-xê-chia, tức là năm thứ chín đời Ô-sê, vua Ít-ra-en; Sa-ma-ri bị chiếm lấy.'),
(10036, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 11, 'OT', 'Vua nước A-ssu-ri đã bắt dân Y-sơ-ra-ên đi đày đến A-ssu-ri, và định cư họ tại Ha-lách, tại Ha-bô, bên bờ sông Gô-zan, và tại các thành của người Ma-đai.'),
(10037, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 12, 'OT', 'vì chúng không vâng theo tiếng của Đức Giê-hô-va Đức Chúa Trời mình, mà vi phạm giao ước Ngài, mọi điều Môi-se, tôi tớ của Đức Giê-hô-va, đã truyền, và chúng không nghe, cũng không làm theo.'),
(10038, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 13, 'OT', 'Vào năm thứ mười bốn đời vua Ê-xê-chia, thì San-chê-rib, vua Ái-thuật, đã lên đánh tất cả các thành có vách thành của Giu-đa, và chiếm được các thành ấy.'),
(10039, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 14, 'OT', 'Vua Ê-xê-chia của Giu-đa sai sứ đến vua A-si-ri tại La-ki-s, nói rằng: Tôi đã phạm tội; xin ngài rút lui khỏi tôi. Những gì vua đặt trên tôi, tôi sẽ chịu. Vua A-si-ri liền định cho Ê-xê-chia, vua Giu-đa, ba trăm kikốt bạc và ba mươi kikốt vàng.'),
(10040, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 15, 'OT', 'Vua Ê-xê-chia đưa tất cả bạc tìm được trong đền thờ Đức Giê-hô-va và trong kho báu của vua.'),
(10041, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 16, 'OT', 'Vào thời ấy, Ê-xê-chia cắt những cửa đền thờ của Đức Giê-hô-va và những tấm ốp mà vua Ê-xê-chia nước Giu-đa đã dát, rồi đưa cho vua A-si-ri.'),
(10042, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 17, 'OT', 'Vua nước A-si-ri sai Tartan, Rabsaris và Rab-sa-ke từ La-chis đến vua Hi-zechi-a tại Giê-ru-sa-lem với một đạo quân đông đảo. Họ lên đường và đến Giê-ru-sa-lem; họ lên và đến, rồi đứng tại mương dẫn nước của cái hồ phía trên, nằm trên con đường dẫn đến cánh đồng của thợ giặt vải.'),
(10043, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 18, 'OT', 'Họ gọi vua, thì Ê-li-a-kim, con trai của Hil-ki-a, người quản lý nhà vua, cùng với Sê-bna, viên ký thư, và Giô-ách, con trai của A-sáp, người giữ chức sử quan, đi ra gặp họ.'),
(10044, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 19, 'OT', 'Rab-sa-ke nói với họ: "Hãy nói với Ê-xe-kia rằng: Đức vua lớn, vua A-si-ri, phán như vầy: Ngươi cậy vào sự tự tin này là gì?'),
(10045, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 20, 'OT', 'Ngươi nói: "Chỉ là những lời suông, mưu kế và sức mạnh để chiến đấu." Bây giờ, ngươi tin cậy vào ai mà dám nổi loạn chống lại ta?'),
(10046, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 21, 'OT', 'Bây giờ, này, ngươi tin cậy vào cây gậy sậy đã bị dập nát nầy, tức là Ai Cập, mà nếu một người chống vào, thì nó sẽ đâm xuyên qua tay người ấy; cũng vậy, Pha-ra-ôn, vua của Ai Cập, đối với mọi người tin cậy nơi người ấy.'),
(10047, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 22, 'OT', 'Nhưng nếu các ngươi nói cùng ta: Chúng tôi tin cậy Đức Giê-hô-va Đức Chúa Trời chúng tôi; chẳng phải chính Ngài là Đấng mà Hê-xê-kia đã dẹp bỏ các nơi cao và các bàn thờ của Ngài, và đã nói cùng Giu-đa và Giê-ru-sa-lem rằng: Các ngươi phải thờ lạy trước bàn thờ nầy tại Giê-ru-sa-lem sao?'),
(10048, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 23, 'OT', 'Bây giờ, hãy đưa ra lời cam đoan cùng chủ nhân ta, vua A-si-ri, và ta sẽ trao cho ngươi hai ngàn ngựa, nếu ngươi có thể cung cấp những người cưỡi ngựa cho chúng.'),
(10049, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 24, 'OT', 'Làm thế nào ngươi có thể chống cự nổi một viên chỉ huy nhỏ nhất trong các đầy tớ của chủ ta đây? Thế mà ngươi lại tin cậy vào Ai Cập về xe chiến và kỵ binh.'),
(10050, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 25, 'OT', 'Bây giờ, phải chăng ta lên đây để hủy diệt nơi này mà không có Đức Giê-hô-va? Đức Giê-hô-va phán cùng ta rằng: Hãy lên đất nước này và hủy diệt nó.'),
(10051, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 26, 'OT', 'Bấy giờ Ê-li-a-kím, con trai của Hil-ki-a, và Sê-bna, và Giô-ách nói với Ráp-sa-kê: "Xin hãy nói với các đầy tớ ông bằng tiếng Sy-ri, vì chúng tôi hiểu; và đừng nói với chúng tôi bằng tiếng Giu-đa, tại trước mặt dân chúng đang đứng trên vách thành."'),
(10052, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 27, 'OT', 'Ráp-sa-kê nói với họ: "Có phải chúa ta đã sai ta đến cùng chủ ngươi và ngươi để nói những lời nầy không? Há chẳng phải là để nói nghịch cùng những người ngồi trên tường, khiến họ phải ăn phân và uống nước tiểu của chính mình cùng với các ngươi sao?"'),
(10053, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 28, 'OT', 'Rabsake đứng lên, kêu lớn bằng tiếng Do-thái, và nói rằng: Hãy nghe lời của vua lớn, vua A-si-ri,'),
(10054, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 29, 'OT', 'Đức vua phán như vầy: "Đừng để Hê-xê-kia làm cho các ngươi thất vọng; vì người ấy sẽ không thể giải cứu các ngươi khỏi tay người đó."'),
(10055, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 30, 'OT', 'Đừng để Ê-xê-chia khiến các ngươi tin nơi Đức Giê-hô-va mà nói rằng: Đức Giê-hô-va chắc chắn sẽ giải cứu chúng ta, và thành nầy sẽ không bị trao vào tay vua A-si-ri.'),
(10056, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 31, 'OT', 'Đừng nghe theo Hê-xê-kia; vì vua A-si-ri có phán như vầy: Hãy lập giao ước với ta và đầu hàng ta, rồi mỗi người sẽ ăn nho từ cây nho của mình, mỗi người sẽ ăn trái vả của mình, và mỗi người sẽ uống nước từ giếng của mình.'),
(10057, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 32, 'OT', 'Cho đến khi ta đến, đem các ngươi đi đến một đất giống như đất các ngươi, một đất có lúa mì và rượu, một đất có bánh và vườn nho, một đất có dầu ô-liu và mật ong, để các ngươi sống và không chết. Đừng nghe theo Ê-xê-chia, vì người sẽ xúi giục các ngươi rằng: Đức Giê-hô-va sẽ giải cứu chúng ta.'),
(10058, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 33, 'OT', 'Các thần của các nước có giải cứu mỗi nước mình khỏi tay vua Ách-đù không?'),
(10059, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 34, 'OT', 'Các thần của Hama và Arphad ở đâu? Các thần của Sê-phạt-va-im, Hê-na và I-va ở đâu? Chúng đã giải cứu Sa-ma-ri khỏi tay ta chưa?'),
(10060, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 35, 'OT', 'Các thần trong mọi nước nào đã cứu đất nước mình khỏi tay ta, mà Đức Giê-hô-va có thể cứu Giê-ru-sa-lem khỏi tay ta?'),
(10061, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 36, 'OT', 'Dân chúng làm thinh, không đáp người một lời nào, vì lệnh vua có phán rằng: "Đừng đáp lại người."'),
(10062, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 18, 37, 'OT', 'Ê-li-a-kim, con trai của Hil-ki-a, người cai quản nhà vua, và Sê-bna, viên ký thư, và Giô-ách, con trai của A-sáp, người ghi chép sử, đến cùng Ê-xe-ki-a với những bộ áo xé rách, và thuật lại cho ông các lời của Ráp-sa-kê.'),
(10063, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 1, 'OT', 'Xảy ra sau khi vua Ê-xê-chia nghe điều đó, thì ông xé áo mình, lấy bao gai mặc trên thân, và vào nhà Đức Giê-hô-va.'),
(10064, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 2, 'OT', 'Ông sai Ê-li-a-kim, người quản gia, và Sê-bna, viên ký thư, cùng các trưởng lão của các thầy tế lễ, đều mặc áo bằng vải gai, đến gặp nhà tiên tri Ê-sai, con trai A-mốt.'),
(10065, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 3, 'OT', 'Họ nói với ông: "Ê-xê-kia nói như vầy: Hôm nay là ngày khốn khổ, quở trách và sỉ nhục; vì con cái đã đến lúc sinh nở, nhưng không có sức lực để đẻ."'),
(10066, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 4, 'OT', 'Có lẽ Đức Giê-hô-va Đức Chúa Trời ngươi sẽ nghe mọi lời của Ráp-sách, mà vua A-si-ri đã sai đến để sỉ nhục Đức Chúa Trời hằng sống, và sẽ quở trách những lời mà Đức Giê-hô-va Đức Chúa Trời ngươi đã nghe; vậy hãy dâng lời cầu nguyện vì số còn sót lại đang được tìm thấy.'),
(10067, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 5, 'OT', 'Các tôi tớ của vua Ê-xê-chia đi đến Ê-sai.'),
(10068, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 6, 'OT', 'Ê-sai nói với họ: "Hãy nói với chủ các ngươi như vầy: Đức Giê-hô-va phán: Đừng sợ những lời mà ngươi đã nghe, tức những lời mà các đầy tớ của vua A-si-ri đã nói phạm đến Ta.'),
(10069, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 7, 'OT', 'Nầy, Ta sẽ đặt thần trong người ấy; người ấy sẽ nghe một tin đồn và trở về đất nước mình; rồi Ta sẽ khiến người ấy ngã dưới gươm trong đất nước mình.'),
(10070, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 8, 'OT', 'Rab-sa-ke trở về, gặp vua A-si-ri đang chiến đấu tại Lib-na, vì vua đã nghe tin người đã rời khỏi La-ki-s.'),
(10071, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 9, 'OT', 'Vua Ê-thi-ô-pi Ti-rha-ca nghe tin rằng: "Nầy, người đã ra đi để chiến đấu cùng ngươi," thì người trở lại và sai các sứ giả đến cùng Hê-xê-kia, nói rằng:'),
(10072, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 10, 'OT', 'Hãy nói cùng Hê-xê-kia, vua Giu-đa, như vầy: Đừng để Đức Chúa Trời ngươi, Đấng ngươi tin cậy, lừa dối ngươi, khi nói rằng Giê-ru-sa-lem sẽ không bị trao vào tay vua Át-xu-ri.'),
(10073, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 11, 'OT', 'Này, ngươi đã nghe những gì các vua Ái-thu-thi đã làm cho mọi xứ, khi hoàn toàn tiêu diệt chúng; vậy ngươi sẽ được cứu thoát sao?'),
(10074, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 12, 'OT', 'Các thần của các dân tộc mà tổ tiên ta đã tiêu diệt, như Gô-zan, Ha-ran, Rết-ép và con cái Ê-đen ở Tê-la-sa, có giải cứu họ chăng?'),
(10075, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 13, 'OT', 'Vua của Ha-mát ở đâu? Vua của A-ráp ở đâu? Vua của thành Sê-pha-va-im, Hê-na và I-va ở đâu?'),
(10076, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 14, 'OT', 'Ê-xê-chia nhận lấy các bức thư từ tay các sứ giả và đọc chúng; rồi Ê-xê-chia đi lên đền thờ Đức Giê-hô-va và trải các bức thư ra trước mặt Đức Giê-hô-va.'),
(10077, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 15, 'OT', 'Ê-xê-chia cầu nguyện trước mặt Đức Giê-hô-va và nói: Lạy Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên, Đấng ngự trên các chê-ru-bim, chính Ngài là Đức Chúa Trời, một mình Ngài thôi, của mọi nước trên đất; chính Ngài đã làm nên các từng trời và đất.'),
(10078, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 16, 'OT', 'Lạy Đức Giê-hô-va, xin nghiêng tai Ngài và nghe; xin mở mắt Đức Giê-hô-va và nhìn xem; và hãy nghe những lời của San-chê-rib mà người đã sai đến để sỉ nhục Đức Chúa Trời hằng sống.'),
(10079, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 17, 'OT', 'Thật vậy, Đức Giê-hô-va, các vua A-sy-ri đã hủy diệt các dân tộc và đất đai của chúng.'),
(10080, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 18, 'OT', 'và họ đã ném các thần của mình vào lửa; vì chúng không phải là thần, mà chỉ là sản phẩm do tay người làm ra, bằng gỗ và đá; nên họ đã hủy diệt chúng.'),
(10081, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 19, 'OT', 'Bây giờ, lạy Đức Giê-hô-va Đức Chúa Trời chúng tôi, xin hãy giải cứu chúng tôi khỏi tay người, để cho mọi vương quốc trên đất đều biết rằng chính Ngài, Đức Giê-hô-va Đức Chúa Trời, là Đấng duy nhất.'),
(10082, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 20, 'OT', 'Ê-sai, con trai của A-mốt, sai người đến nói với Ê-xe-chia rằng: "Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên phán như vầy: Ta đã nghe lời ngươi cầu nguyện cho Ta về chuyện San-chê-ríp, vua A-si-ri,'),
(10083, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 21, 'OT', 'Đây là điều mà Đức Giê-hô-va đã phán về ngươi: Trinh nữ, con gái Xi-ôn, đã khinh bỉ ngươi, chế giễu ngươi; con gái Giê-ru-sa-lem đã lắc đầu chế nhạo ngươi.'),
(10084, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 22, 'OT', 'Ngươi đã sỉ nhục và nguyền rủa ai? Ngươi đã cất tiếng chống lại ai, và ngước mắt mình lên cao cách kiêu ngạo chống lại Đấng Thánh của Ít-ra-en?'),
(10085, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 23, 'OT', 'Bởi tay các thiên sứ của ngươi, ngươi đã sỉ nhục Đức Giê-hô-va và nói rằng: "Nhờ đoàn xe hùng mạnh của ta, ta đã lên đến đỉnh các núi, đến những nơi xa xăm của Li-ban; ta sẽ đốn hạ chiều cao của những cây bách nó, những cây tùng tốt nhất của nó; ta sẽ vào nơi ở tận cùng rìa của nó, vào rừng rậm của Cạt-mên nó."'),
(10086, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 24, 'OT', 'Ta đã đào và uống những nước lạ, và bằng lòng bàn chân ta đã làm cạn mọi sông ngòi của các nơi bị vây khốn.'),
(10087, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 25, 'OT', 'Chẳng phải ngươi đã nghe từ lâu Ta đã làm điều nầy từ những ngày xa xưa, và đã định sẵn từ thời cổ xưa sao? Bây giờ Ta đã thực hiện nó, để ngươi sẽ phá hủy các thành có vách thành vững chắc, biến chúng thành đống đá đổ nát.'),
(10088, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 26, 'OT', 'Còn dân ở trong đó thì tay chân yếu ớt, hốt hoảng và hổ thẹn; chúng nó trở nên như cỏ ngoài đồng, rau xanh mới mọc, cỏ mọc trên mái nhà, và như lúa bị cháy trước khi trổ bông.'),
(10089, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 27, 'OT', 'Nhưng Ta biết nơi ngươi ở, và lúc ngươi ra, lúc ngươi vào, cùng cơn thịnh nộ ngươi chống nghịch Ta.'),
(10090, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 28, 'OT', 'Vì ngươi nổi giận chống nghịch Ta, và tiếng ồn ào của ngươi đã thấu đến tai Ta, nên Ta sẽ đặt cái móc của Ta vào mũi ngươi, và cái dây cương vào môi ngươi, rồi Ta sẽ khiến ngươi quay trở lại con đường mà ngươi đã đến.'),
(10091, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 29, 'OT', 'Này đây là dấu cho ngươi: năm nay các ngươi sẽ ăn những thứ mọc hoang, năm thứ hai sẽ ăn những thứ mọc tự nhiên; còn năm thứ ba, hãy gieo giống, gặt hái, trồng nho và ăn trái của nó.'),
(10092, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 30, 'OT', 'Phần sót lại thoát khỏi nhà Giu-đa, là phần sót còn lại, sẽ đâm rễ xuống dưới và sinh trái lên trên.'),
(10093, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 31, 'OT', 'Vì từ Giê-ru-sa-lem sẽ có một nhóm sót lại ra đi, và những người thoát khỏi núi Xi-ôn: lòng sốt sắng của Đức Giê-hô-va sẽ làm điều nầy.'),
(10094, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 32, 'OT', 'Vì vậy, Đức Giê-hô-va phán như vầy về vua A-xua: hắn sẽ không vào thành nầy, không bắn một mũi tên nào vào đó, không tiến đến gần nó với khiên, và không đắp lũy vây công thành nầy.'),
(10095, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 33, 'OT', 'Theo con đường mà hắn đến, theo con đường ấy hắn sẽ trở về, và sẽ không vào thành nầy, Đức Giê-hô-va phán như vậy.'),
(10096, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 34, 'OT', 'Ta sẽ bảo vệ thành này mà giải cứu nó, vì cớ Ta và vì Đa-vít, tôi tớ Ta.'),
(10097, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 35, 'OT', 'Đoạn đêm ấy, một thiên sứ của Đức Giê-hô-va ra đi và đánh giết trong trại quân của người A-si-ri một trăm tám mươi lăm ngàn người; sáng hôm sau, khi họ chỗi dậy sớm, kìa tất cả đều là những xác chết.'),
(10098, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 36, 'OT', 'Vua San-chê-rib của A-si-ri bèn dời đi, đi và trở về, rồi ở lại Ninh-veh.'),
(10099, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 19, 37, 'OT', 'Và xảy ra khi ông ta đang thờ lạy trong đền thờ Nít-rôch thần của mình, thì A-đơ-rơ-mơ-léc và Xa-rết-xe, hai con trai ông ta, đã giết ông bằng gươm; rồi chúng trốn đến xứ A-ra-rát. Sau đó Ê-xa-hát-đôn, con trai ông, lên ngôi kế vị.'),
(10100, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 20, 1, 'OT', 'Trong những ngày ấy, Ê-xê-chia bị bệnh nặng gần chết. Bấy giờ, nhà tiên tri Ê-sai, con trai A-mốt, đến gặp người và nói với người rằng: "Đức Giê-hô-va phán như vầy: Hãy sắp đặt nhà ngươi, vì ngươi sẽ chết và không sống."'),
(10101, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 20, 2, 'OT', 'Ông quay mặt vào tường và cầu nguyện cùng Đức Giê-hô-va, nói rằng'),
(10102, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 20, 3, 'OT', 'Lạy Đức Giê-hô-va, xin hãy nhớ lại làm ơn, tôi đã bước đi trước mặt Ngài trong chân lý và với một tấm lòng trọn vẹn, và tôi đã làm điều thiện trước mắt Ngài. Rồi Hê-xê-kia khóc rất thảm thiết.'),
(10103, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 20, 4, 'OT', 'Ê-sai chưa ra khỏi sân trong thì có lời của Đức Giê-hô-va phán cùng người rằng:'),
(10104, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 20, 5, 'OT', 'Hãy trở lại và nói cùng Hê-xê-kia, lãnh tụ của dân ta: Đức Giê-hô-va phán như vầy, Đức Chúa Trời của Đa-vít tổ ngươi: Ta đã nghe lời cầu nguyện của ngươi, Ta đã thấy những giọt lệ của ngươi; nầy, Ta sẽ chữa lành ngươi; ngày thứ ba ngươi sẽ đi lên đền Đức Giê-hô-va.'),
(10105, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 20, 6, 'OT', 'Ta sẽ thêm cho ngươi mười lăm năm nữa, và Ta sẽ giải cứu ngươi cùng thành này khỏi tay vua xứ A-si-ri; Ta sẽ bảo vệ thành này vì cớ Ta và vì cớ Đa-vít, tôi tớ Ta.'),
(10106, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 20, 7, 'OT', 'Ê-sai nói: "Hãy lấy một miếng vả khô." Họ bèn lấy và đặt trên ổ loét, rồi người ấy sống lại.'),
(10107, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 20, 8, 'OT', 'Ê-xê-chia nói với Ê-sai: Dấu hiệu nào cho thấy Đức Giê-hô-va sẽ chữa lành cho tôi, và tôi sẽ lên đền thờ Đức Giê-hô-va vào ngày thứ ba?'),
(10108, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 20, 9, 'OT', 'Ê-sai bảo: "Đây là dấu hiệu từ Đức Giê-hô-va, để Đức Giê-hô-va làm điều Ngài đã phán: bóng sẽ đi tới mười độ, hay là lui lại mười độ?"'),
(10109, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 20, 10, 'OT', 'Ê-xê-chia đáp: "Việc bóng đi xuống mười độ là điều dễ. Nhưng không, hãy để cho bóng lui lại mười độ."'),
(10110, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 20, 11, 'OT', 'Đa-tri-ngôn Ê-sai kêu cầu Đức Giê-hô-va, và Ngài khiến bóng trên các bậc thang mà nó đã đi xuống nơi các bậc thang của A-xai trở lại mười bậc.'),
(10111, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 20, 12, 'OT', 'Bấy giờ, Bê-rô-đác-ba-la-đan, con trai của Ba-la-đan, vua Ba-by-lôn, sai các thơ và lễ vật đến cho Ê-xê-chia; vì người nghe biết rằng Ê-xê-chia đã bị bệnh.'),
(10112, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 20, 13, 'OT', 'Vua Hê-xê-kia nghe các sứ giả ấy, bèn cho họ xem toàn bộ kho báu của mình, gồm bạc, vàng, các loại hương liệu, dầu thơm hảo hạng, toàn bộ kho vũ khí của vua, và mọi thứ được tìm thấy trong các kho tàng của vua; chẳng có điều gì trong nhà vua hay trong toàn cõi lãnh thổ của vua mà vua Hê-xê-kia không cho họ xem.'),
(10113, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 20, 14, 'OT', 'Đoạn Ê-sai, vị ngôn sứ, đến cùng vua Ê-xe-chia, và nói với người rằng: "Những người này đã nói gì, và họ từ đâu đến cùng ông?" Ê-xe-chia đáp: "Họ đến từ một xứ xa, tức là Ba-by-lôn."'),
(10114, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 20, 15, 'OT', 'Vua ấy hỏi: "Họ đã thấy những gì trong nhà ngươi?" Ê-xê-chia đáp: "Tất cả những gì trong nhà ta, họ đã thấy; chẳng có điều gì trong các kho tàng ta mà ta không cho họ xem."'),
(10115, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 20, 16, 'OT', 'Ê-sai nói với Ê-xê-chia rằng: "Hãy nghe lời của Đức Giê-hô-va."'),
(10116, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 20, 17, 'OT', 'Này, những ngày sẽ đến, khi mọi điều ở trong nhà ngươi và những gì tổ tiên ngươi đã tích trữ cho đến ngày nay sẽ bị mang đi Ba-by-lôn; chẳng còn sót lại điều gì, Đức Giê-hô-va phán.'),
(10117, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 20, 18, 'OT', 'Và trong số các con trai ngươi, những người sẽ sinh ra từ ngươi, chúng sẽ bắt đi, và chúng sẽ làm hoạn quan trong cung điện của vua Ba-by-lôn.'),
(10118, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 20, 19, 'OT', 'Ê-xê-chia nói với Ê-sai: "Lời của Đức Giê-hô-va mà ông đã nói là tốt lành. Vì tự nghĩ rằng: Nếu sự bình an và chân thật được thấy trong đời ta thì chẳng phải tốt lắm sao?"'),
(10119, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 20, 20, 'OT', 'Còn những việc khác của Ê-xê-chia, và mọi chiến công người làm, cùng việc người đào ao và hầm dẫn nước vào thành, thì chẳng phải đã được chép trong sách Các Việc Làm của các vua Giu-đa sao?'),
(10120, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 20, 21, 'OT', 'Ê-xê-chia an nghỉ cùng các tổ phụ mình; và Ma-na-xe, con trai người, lên ngôi kế vị người.'),
(10121, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 21, 1, 'OT', 'Ma-na-se lên ngôi làm vua lúc được mười hai tuổi, và trị vì năm mươi lăm năm tại Giê-ru-sa-lem. Tên mẹ người là Hếp-xi-ba.'),
(10122, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 21, 2, 'OT', 'Màu làm điều ác trước mặt Đức Giê-hô-va, theo những điều gớm ghiếc của các dân tộc mà Đức Giê-hô-va đã đuổi ra khỏi trước mặt con cái Ít-ra-en.'),
(10123, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 21, 3, 'OT', 'Vua Mạnh lại xây dựng các nơi cao mà Ê-xê-chia, cha người, đã phá hủy; người dựng các bàn thờ cho Ba-an, làm một cây A-she-ra như A-háp, vua Ít-ra-en, đã làm; người thờ lạy toàn thể thiên thể và phục vụ chúng.'),
(10124, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 21, 4, 'OT', 'Và người đã xây các bàn thờ trong đền thờ của Đức Giê-hô-va, là nơi Đức Giê-hô-va đã phán: "Ta sẽ đặt danh Ta tại Giê-ru-sa-lem."'),
(10125, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 21, 5, 'OT', 'Và người đã xây các bàn thờ cho toàn thể đạo binh trên trời, trong hai sân của đền thờ Đức Giê-hô-va.'),
(10126, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 21, 6, 'OT', 'Và người khiến con trai mình đi qua lửa, làm thầy bói, thầy phù thủy, dùng bùa chú và giao cấu với các thần linh; người làm nhiều điều ác trước mắt Đức Giê-hô-va, khiến Ngài nổi giận.'),
(10127, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 21, 7, 'OT', 'Và người đặt tượng gỗ của thần A-she-ra mà người đã làm vào trong đền thờ, là nơi mà Đức Giê-hô-va đã phán cùng Đa-vít và cùng Sa-lô-môn, con trai người rằng: "Trong đền thờ nầy và trong Giê-ru-sa-lem, là thành ta đã chọn ra khỏi mọi chi phái Y-sơ-ra-ên, ta sẽ đặt danh ta đời đời."'),
(10128, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 21, 8, 'OT', 'Ta sẽ không còn bắt dân Y-sơ-ra-ên phải dời chân khỏi đất mà Ta đã ban cho các tổ phụ chúng; chỉ cần chúng giữ làm theo mọi điều mà Ta đã truyền cho chúng, và theo trọn luật pháp mà tôi tớ Ta là Môi-se đã truyền cho chúng.'),
(10129, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 21, 9, 'OT', 'Họ không chịu nghe; và Ma-na-xe khiến họ làm điều ác hơn các dân tộc mà Đức Giê-hô-va đã tiêu diệt trước mặt con cái Ít-ra-en.'),
(10130, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 21, 10, 'OT', 'Đức Giê-hô-va phán qua các tôi tớ Ngài là các nhà tiên tri, rằng:'),
(10131, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 21, 11, 'OT', 'Vì Mạn-né-xe, vua Giu-đa, đã làm những điều ghê tởm ấy, làm điều ác hơn tất cả những gì các người Amôrít đã làm trước mặt người, và khiến Giu-đa phạm tội bởi những hình tượng của người.'),
(10132, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 21, 12, 'OT', 'Vì vậy, Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên phán như vầy: Nầy, Ta sẽ mang điều dữ đến trên Giê-ru-sa-lem và Giu-đa, đến nỗi ai nghe thấy cũng phải nhói tai hai bên.'),
(10133, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 21, 13, 'OT', 'Ta sẽ giăng dây đo của Sa-ma-ri qua Giê-ru-sa-lem, và cái dọi của nhà A-cháp; Ta sẽ xóa bỏ Giê-ru-sa-lem như người lau dọn cái đĩa, lau xong rồi úp mặt xuống.'),
(10134, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 21, 14, 'OT', 'Ta sẽ từ bỏ phần sót lại của cơ nghiệp Ta, và phó họ vào tay kẻ thù; chúng sẽ trở thành mồi cho mọi kẻ thù của chúng và bị cướp phá.'),
(10135, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 21, 15, 'OT', 'Vì chúng đã làm điều ác trước mặt ta và khiến ta nổi giận, từ ngày tổ tiên chúng ra khỏi Ai Cập cho đến ngày nay.'),
(10136, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 21, 16, 'OT', 'Vả lại, Mê-na-xe cũng đổ máu vô tội rất nhiều, cho đến nỗi làm đầy Giê-ru-sa-lem từ đầu này đến đầu kia; ngoài tội lỗi mà người đã phạm khiến cho Giu-đa phạm tội, làm điều ác trước mặt Đức Giê-hô-va.'),
(10137, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 21, 17, 'OT', 'Còn các việc khác của Ma-na-xe, và mọi điều ông đã làm, cùng tội lỗi ông đã phạm, chẳng phải tất cả đều chép trong sách Các Việc trong đời các vua Giu-đa sao?'),
(10138, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 21, 18, 'OT', 'Man-xe giải nằm chung với tổ tiên mình, và được chôn trong vườn nhà mình, tức vườn U-za; rồi A-môn, con trai người, lên ngôi kế vị.'),
(10139, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 21, 19, 'OT', 'A-môn hai mươi hai tuổi khi người lên ngôi vua, và người trị vì hai năm tại Giê-ru-sa-lem. Tên mẹ người là Mê-sun-lê-mết, con gái của Ha-rút đến từ Yốt-bah.'),
(10140, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 21, 20, 'OT', 'Người làm điều ác trước mặt Đức Giê-hô-va, y như điều mà Ma-na-xe, cha người, đã làm.'),
(10141, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 21, 21, 'OT', 'Và người đi theo mọi con đường mà cha người đã đi, và phục vụ các hình tượng mà cha người đã phục vụ, và thờ lạy chúng.'),
(10142, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 21, 22, 'OT', 'Và người bỏ Đức Giê-hô-va, Đức Chúa Trời của tổ tiên mình, và không đi theo con đường của Đức Giê-hô-va.'),
(10143, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 21, 23, 'OT', 'Các đầy tớ của A-môn lập mưu nghịch cùng người, và giết vua trong nhà của chính người.'),
(10144, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 21, 24, 'OT', 'Dân chúng trong xứ giết hết những kẻ âm mưu nghịch cùng vua A-môn; rồi dân chúng trong xứ lập Giô-si-a, con trai ông, lên làm vua thế cho ông.'),
(10145, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 21, 25, 'OT', 'Phần còn lại của các việc A-môn đã làm, há chẳng chép trong sách Các Việc Làm Hằng Ngày của các vua Giu-đa sao?'),
(10146, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 21, 26, 'OT', 'Ông được chôn trong mồ mả của mình tại vườn U-xa; và Giô-si-ah, con trai ông, lên ngôi kế vị.'),
(10147, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 22, 1, 'OT', 'Giô-xi-ah lên ngôi vua lúc tám tuổi, và trị vì ba mươi mốt năm tại Giê-ru-sa-lem. Tên mẹ người là Giê-di-đa, con gái của A-đai-ah, người Bốt-ca-tha.'),
(10148, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 22, 2, 'OT', 'Và người làm điều ngay thẳng trong mắt Đức Giê-hô-va, và đi theo mọi con đường của Đa-vít, cha người, không chếch sang bên phải hay bên trái.'),
(10149, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 22, 3, 'OT', 'Năm thứ mười tám đời vua Giô-si-a, vua sai Xáp-phan, con trai A-xa-ly-a, cháu trai Mết-đu-lam, người văn thư, đến nhà Đức Giê-hô-va, dặn rằng:'),
(10150, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 22, 4, 'OT', 'Hãy đi đến Hinh-kia, thầy tế lễ thượng phẩm, và bảo ông cộng lại số bạc đã được mang vào nhà Đức Giê-hô-va, tức là số bạc mà những người giữ cửa đã thu từ dân chúng.'),
(10151, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 22, 5, 'OT', 'Hãy trao nó cho những người làm công việc, là những người được chỉ định quản lý trong nhà của Đức Giê-hô-va; và họ sẽ giao nó cho những người làm công việc tại nhà của Đức Giê-hô-va để sửa chữa những chỗ hư hại của nhà.'),
(10152, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 22, 6, 'OT', 'cho thợ mộc, thợ xây và thợ đá, và để mua gỗ và đá xẻ để tu sửa nhà ấy.'),
(10153, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 22, 7, 'OT', 'Tuy nhiên, không cần kiểm tra số bạc giao vào tay chúng, vì chúng làm việc trung thực.'),
(10154, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 22, 8, 'OT', 'Thầy tế lễ thượng phẩm Hinh-kia nói với người chép sách Sáp-phan: "Tôi đã tìm được sách Luật Pháp trong đền Đức Giê-hô-va." Rồi thầy tế lễ Hinh-kia trao cuốn sách cho Sáp-phan, và ông đọc nó.'),
(10155, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 22, 9, 'OT', 'Sê-phan quan sao chép đến cùng vua, và tâu lại cho vua, rằng: "Các đầy tớ của ngài đã thu góp số bạc tìm được trong đền thờ, rồi giao số bạc ấy cho những người làm công việc, là những người được chỉ định quản lý nhà của Đức Giê-hô-va."'),
(10156, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 22, 10, 'OT', 'Sê-pha-nơ, viên thư ký, tâu với vua rằng: "Hinh-ki-ah, thầy tế lễ, đã trao cho tôi một cuốn sách." Rồi Sê-pha-nơ đọc sách ấy trước mặt vua.'),
(10157, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 22, 11, 'OT', 'Khi vua nghe những lời trong sách Luật Pháp, vua xé áo mình.'),
(10158, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 22, 12, 'OT', 'Vua truyền cho thầy tế lễ Hil-ki-a, cho A-hi-kam con trai Xáp-phan, cho A-khôp con trai Mi-khai-a, cho Xáp-phan văn sĩ, và cho A-xa-ia tôi tớ của vua, rằng:'),
(10159, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 22, 13, 'OT', 'Hãy đi, hãy cầu hỏi Đức Giê-hô-va nhân danh tôi, nhân danh dân chúng và toàn thể Giu-đa về những lời trong cuốn sách đã tìm thấy này; vì cơn thịnh nộ lớn của Đức Giê-hô-va đã nổi lên nghịch cùng chúng tôi, do các tổ tiên chúng tôi đã không nghe theo những lời trong cuốn sách này để làm theo mọi điều đã chép cho chúng tôi.'),
(10160, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 22, 14, 'OT', 'Vậy, thầy tế lễ Hinh-kia, và A-hi-kam, và A-cha-bor, và Sáp-an, và A-xa-ia đi đến với nữ tiên tri Hút-đa, vợ của Sa-lum, con trai của Tích-va, con trai của Ha-rát, người giữ áo lễ, và bà đang ở tại Giê-ru-sa-lem trong khu phố thứ hai; họ nói chuyện với bà.'),
(10161, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 22, 15, 'OT', 'Bà nói với họ: "Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên phán như vầy: Hãy nói với người đàn ông đã sai các ông đến gặp ta,"'),
(10162, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 22, 16, 'OT', 'Đức Giê-hô-va phán như vầy: Nầy, Ta sẽ giáng họa xuống nơi nầy và trên những người ở đây, tức là mọi lời trong quyển sách mà vua Giu-đa đã đọc:'),
(10163, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 22, 17, 'OT', 'Vì chúng đã lìa bỏ Ta và đốt hương cho các thần khác, để chọc giận Ta bằng mọi việc tay chúng làm; nên cơn thịnh nộ của Ta sẽ bùng lên tại nơi này và không bị dập tắt.'),
(10164, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 22, 18, 'OT', 'Còn về vua Giu-đa đã sai các ngươi đi cầu hỏi Đức Giê-hô-va, các ngươi hãy nói với người như thế này: Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en phán như thế này: Về những lời mà ngươi đã nghe,'),
(10165, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 22, 19, 'OT', 'Vì lòng ngươi mềm mại và ngươi đã tự hạ mình trước mặt Đức Giê-hô-va khi nghe những điều Ta phán nghịch cùng nơi này và nghịch cùng dân cư tại đây, rằng chúng sẽ trở nên hoang vu và bị rủa sả, ngươi đã xé áo mình và khóc than trước mặt Ta; chính Ta đây cũng đã nghe ngươi, Đức Giê-hô-va phán vậy.'),
(10166, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 22, 20, 'OT', 'Vì vậy, Ta sẽ khiến ngươi được thu về cùng các tổ tiên ngươi, và ngươi sẽ được an táng về cùng các mộ phần của ngươi trong bình an; mắt ngươi sẽ không thấy mọi điều dữ mà Ta sẽ giáng trên nơi này. Rồi họ trình lại cho nhà vua điều đó.'),
(10167, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 1, 'OT', 'Vua sai người đi, và họ tập hợp về cùng vua tất cả các trưởng lão của Giu-đa và Giê-ru-sa-lem.'),
(10168, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 2, 'OT', 'Vua lên đền thờ của Đức Giê-hô-va, cùng với mọi người nam của Giu-đa và mọi người sống tại Giê-ru-sa-lem, các thầy tế lễ, các nhà tiên tri và toàn thể dân chúng, từ nhỏ đến lớn. Rồi vua đọc cho họ nghe mọi lời trong sách của giao ước mà đã được tìm thấy trong đền thờ của Đức Giê-hô-va.'),
(10169, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 3, 'OT', 'Vua đứng bên cột trụ, lập giao ước trước mặt Đức Giê-hô-va rằng sẽ đi theo Đức Giê-hô-va, giữ các điều răn, các lời chứng, các luật lệ của Ngài với trọn tấm lòng và trọn linh hồn mình, để thực hiện những lời giao ước nầy, là những lời đã được chép trong sách nầy. Toàn thể dân chúng đều cam kết giữ giao ước.'),
(10170, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 4, 'OT', 'Vua truyền lệnh cho Hinh-kia, thầy tế lễ thượng phẩm, và các thầy tế lễ cấp bậc thứ hai, và những người giữ cửa, đem tất cả các đồ dùng đã làm cho Ba-anh, cho Ashera, và cho toàn thể đạo binh trên trời, ra khỏi đền thờ của Đức Giê-hô-va; vua đốt các đồ đó bên ngoài Giê-ru-sa-lem, tại các cánh đồng Ki-trôn, rồi đem tro chúng đến Bê-thên.'),
(10171, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 5, 'OT', 'Và ông loại bỏ các thầy tế lễ thờ hình tượng mà các vua Giu-đa đã lập lên, những kẻ đốt hương trên các nơi cao ở các thành Giu-đa và quanh Giê-ru-sa-lem; cũng như những kẻ đốt hương cho Ba-anh, cho mặt trời, cho mặt trăng, cho các chòm sao và cho toàn thể đạo binh trên trời.'),
(10172, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 6, 'OT', 'Vua Giô-xi-ách đem tượng A-xe-ra ra khỏi đền thờ của Đức Giê-hô-va, ra khỏi Giê-ru-sa-lem đến bên suối Kít-đôn, rồi đốt nó tại suối Kít-đôn, nghiền thành bụi và rải bụi đó trên các ngôi mộ của dân chúng.'),
(10173, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 7, 'OT', 'Và người đã phá hủy các nhà thờ của những người nữ phục vụ hình tượng, là những nhà ở trong đền thờ của Đức Giê-hô-va, nơi các phụ nữ dệt màn che cho hình tượng A-she-ra.'),
(10174, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 8, 'OT', 'Và người đem tất cả các thầy tế lễ ra khỏi các thành của Giu-đa, và làm ô uế các nơi cao mà tại đó các thầy tế lễ đã dâng hương, từ Ghê-ba cho đến Bê-e-Sê-ba; và người phá đổ các nơi cao ở các cổng, tức những nơi ở lối vào cổng Giô-suê, tổng trấn thành, nằm bên tay trái người nào vào cổng thành.'),
(10175, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 9, 'OT', 'Tuy nhiên, các thầy tế lễ của các nơi cao không lên đến bàn thờ của Đức Giê-hô-va tại Giê-ru-sa-lem, mà chỉ ăn bánh không men giữa anh em mình.'),
(10176, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 10, 'OT', 'Và người làm cho nơi Tô-phết, ở trong thung lũng con cái Hin-nom, trở nên ô uế, để không ai được dâng con trai hay con gái mình vào lửa cho thần Mô-léc.'),
(10177, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 11, 'OT', 'Vua Giô-xi-a đuổi những con ngựa mà các vua Giu-đa đã dâng cho mặt trời, tại lối vào nhà Đức Giê-hô-va, gần phòng của Nát-than-mê-léc, viên hoạn quan, ở trong khu vực bên ngoài; vua cũng đốt các xe ngựa mặt trời bằng lửa.'),
(10178, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 12, 'OT', 'Vua phá bỏ các bàn thờ trên nóc buồng trên cùng của A-xa, là những bàn thờ mà các vua Giu-đa đã làm, và các bàn thờ mà Ma-na-xe đã dựng trong hai sân của nhà Đức Giê-hô-va; vua đập nát chúng, mang bụi chúng ra ném xuống suối Ki-trôn.'),
(10179, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 13, 'OT', 'Vua làm ô uế các nơi cao ở trước mặt Giê-ru-sa-lem, ở bên phải núi sự bại hoại, mà vua Sa-lô-môn, vua Y-sơ-ra-ên, đã xây cho Át-tô-rét, hình tượng đáng ghê tởm của người Xi-đôn, và cho Kê-mô-s, hình tượng đáng ghê tởm của người Mô-áp, và cho Mi-lơ-côm, hình tượng đáng ghê tởm của con cái Am-môn.'),
(10180, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 14, 'OT', 'Người đã đập bể các trụ thờ, chặt bỏ các tượng thần A-she-ra, và lấy xương người chất đầy các nơi ấy.'),
(10181, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 15, 'OT', 'Cũng vậy, cái bàn thờ tại Bê-tên, nơi cao mà Giê-rô-bô-am con trai của Nê-bát đã lập, người đã khiến cho Ít-ra-en phạm tội, cả cái bàn thờ đó và nơi cao ấy, người đã phá hủy; người đốt cháy nơi cao, nghiền nhỏ thành bụi, và thiêu đốt hình tượng A-she-ra.'),
(10182, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 16, 'OT', 'Vua Giô-si-a quay lại, thấy các ngôi mộ nằm trên núi ấy, bèn sai người đi lấy các hài cốt ra khỏi các ngôi mộ, đốt trên bàn thờ và làm cho nó ra ô uế, y như lời Đức Giê-hô-va đã phán qua người của Đức Chúa Trời, là người đã công bố các lời ấy.'),
(10183, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 17, 'OT', 'Bấy giờ người nói: "Bia đá kia mà ta thấy là gì?" Những người trong thành đáp rằng: "Đó là ngôi mộ của người của Đức Chúa Trời, là người từ Giu-đa đến, và đã tuyên bố những điều nầy mà vua đã làm đối với bàn thờ tại Bê-tên."'),
(10184, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 18, 'OT', 'Ông ấy nói: "Cứ để yên, đừng ai động đến xương người ấy." Vậy nên họ đã không động đến xương người ấy, cùng với xương của đấng tiên tri đã đến từ Xô-ma-ri.'),
(10185, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 19, 'OT', 'Đặc biệt, các đền thờ trên các nơi cao ở các thành phố của Sa-ma-ri mà các vua I-sơ-ra-ên đã xây dựng để làm cho Đức Giê-hô-va nổi giận, thì Giô-xi-a hủy bỏ; và ông xử lý các nơi ấy như cách ông đã làm tại Bê-tên.'),
(10186, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 20, 'OT', 'Người giết hết các thầy tế lễ của các nơi cao, những người đang phục vụ tại các bàn thờ đó, và thiêu những bộ xương người trên các bàn thờ ấy, rồi trở về Giê-ru-sa-lem.'),
(10187, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 21, 'OT', 'Vua truyền lệnh cho toàn thể dân chúng rằng: "Hãy giữ lễ Vượt Qua cho Đức Giê-hô-va Đức Chúa Trời các ngươi, như đã chép trong sách giao ước nầy."'),
(10188, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 22, 'OT', 'Vì chưa từng có lễ Vượt Qua nào giống như lễ Vượt Qua nầy từ những ngày các quan xét xử Y-sơ-ra-ên, và trong mọi ngày các vua Y-sơ-ra-ên và các vua Giu-đa trị vì.'),
(10189, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 23, 'OT', 'Chỉ vào năm thứ mười tám đời vua Giô-xi-a, lễ Vượt Qua nầy mới được thực hiện cho Đức Giê-hô-va tại Giê-ru-sa-lem.'),
(10190, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 24, 'OT', 'Cũng vậy, các thầy đồng cốt, các thầy bói, các tượng thần bằng da, các hình tượng gớm ghiếc và mọi điều đáng ghét mà thấy được trong đất Giu-đa và tại Giê-ru-sa-lem, thì vua Giô-xi-a đều tẩy sạch đi, để thực hiện lời dạy của luật pháp đã chép trong sách mà thầy tế lễ Hi-lê-kia tìm được trong đền Đức Giê-hô-va.'),
(10191, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 25, 'OT', 'Không có vua nào như người trước mặt người, đã hết lòng, hết linh hồn, hết sức lực trở về cùng Đức Giê-hô-va theo trọn luật pháp Môi-se; và sau người, cũng không có ai nổi lên như người.'),
(10192, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 26, 'OT', 'Dẫu vậy, Đức Giê-hô-va không thôi cơn thịnh nộ lớn của Ngài, mà cơn thịnh nộ ấy đã nổi lên cùng Giu-đa, vì mọi điều khuấy động khiến Ma-na-xe đã khiến Ngài nổi giận.'),
(10193, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 27, 'OT', 'Đức Giê-hô-va phán: "Ta cũng sẽ dẹp bỏ Giu-đa khỏi mặt ta, như Ta đã dẹp bỏ Y-sơ-ra-ên; và Ta sẽ chán ghét thành Giê-ru-sa-lem nầy, là thành mà Ta đã chọn, và ngôi đền mà Ta đã phán: Danh Ta sẽ ở đó."'),
(10194, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 28, 'OT', 'Còn các việc khác của Giô-xi-a, và mọi điều ông đã làm, há chẳng được chép trong sách Các Việc Đời của các vua Giu-đa sao?'),
(10195, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 29, 'OT', 'Trong những ngày ấy, Pha-ra-ôn Nê-cô, vua Ai Cập, lên nghịch cùng vua A-si-ri tại sông Ơ-phrát; vua Giô-si-a đi ra nghênh chiến với người, nhưng khi người thấy vua, thì giết vua tại Mê-gi-đô.'),
(10196, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 30, 'OT', 'Các tôi tớ của người chở xác người từ Mê-ghi-đô về Giê-ru-sa-lem, và chôn cất người trong mộ của người. Dân chúng trong xứ đã đón Giê-hô-a-hát, con trai của Giô-si-a, xức dầu cho người và lập người lên làm vua thay cho cha người.'),
(10197, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 31, 'OT', 'Giô-a-cha được hai mươi ba tuổi khi người lên ngôi vua; người trị vì ba tháng tại Giê-ru-sa-lem. Tên mẹ người là Ham-utal, con gái của Giê-ri-mi, người thành Li-phanh.'),
(10198, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 32, 'OT', 'Và người làm điều ác trước mắt Đức Giê-hô-va, giống như tất cả những gì tổ tiên người đã làm.'),
(10199, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 33, 'OT', 'Pha-ra-ôn Nê-cô bắt giữ người ấy tại Ríp-la, trong xứ Ha-mát, đương khi người trị vì tại Giê-ru-sa-lem, và người đặt cho xứ một khoản phạt là một trăm vạn quan bạc và một vạn quan vàng.'),
(10200, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 34, 'OT', 'Pha-ra-ô Nê-cho lập Ê-li-a-ki-ím, con trai của Giô-si-a, làm vua thay cho Giô-si-a, cha người; người đổi tên người ấy thành Giê-hô-i-a-ki-ím; còn Giê-hô-a-ha-xát thì người bắt đi, và người ấy đến Ai-cập, rồi qua đời tại đó.'),
(10201, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 35, 'OT', 'Giô-ya-kim đã đưa bạc và vàng cho Pha-ra-ôn; nhưng người đã đánh thuế trên đất đai để nộp tiền theo lệnh của Pha-ra-ôn: người bắt mỗi người trong dân sự trên đất phải nộp bạc và vàng tùy theo mức thuế của mỗi người, để nộp cho Pha-ra-ôn Nê-cho.'),
(10202, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 36, 'OT', 'Jo-ki-im được hai mươi lăm tuổi khi người lên ngôi; người trị vì ở Giê-ru-sa-lem mười một năm. Tên mẹ người là Xê-bi-đa, con gái của Phê-đai-a, thuộc Ru-ma.'),
(10203, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 23, 37, 'OT', 'Và người làm điều ác trong mắt Đức Giê-hô-va, giống như tất cả những gì tổ tiên người đã làm.'),
(10204, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 24, 1, 'OT', 'Trong những ngày ấy, Nê-bu-cát-nết-sa, vua Ba-by-lôn, đã lên đánh; và Giô-ya-kim phải phục vụ người ba năm, rồi người trở lại và phản nghịch cùng người ấy.'),
(10205, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 24, 2, 'OT', 'Đức Giê-hô-va sai các toán quân Can-đê, các toán quân người Sy-ri, các toán quân người Mô-áp, và các toán quân con cái Am-môn đến nghịch cùng Giu-đa để tiêu diệt nó, y như lời Đức Giê-hô-va đã phán qua các tôi tớ Ngài là các nhà tiên tri.'),
(10206, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 24, 3, 'OT', 'Chỉ vì lời phán của Đức Giê-hô-va mà điều này xảy đến trên Giu-đa, để dẹp bỏ chúng khỏi trước mặt Ngài, vì tội lỗi của Ma-na-xe, theo mọi điều mà người đã làm.'),
(10207, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 24, 4, 'OT', 'Và cả huyết vô tội mà người đã đổ ra, khiến Giê-ru-sa-lem đầy dẫy huyết vô tội; và Đức Giê-hô-va không chịu tha thứ.'),
(10208, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 24, 5, 'OT', 'Còn các việc khác của Giô-ya-kim và mọi điều ông làm, há chẳng chép trong sách Các Việc Làm của các vua Giu-đa sao?'),
(10209, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 24, 6, 'OT', 'Vậy Giô-ya-kim nằm ngủ cùng với các tổ phụ mình; và Giô-ya-khin, con trai ông, lên ngôi kế vị ông.'),
(10210, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 24, 7, 'OT', 'Vua Ai Cập không còn dám ra khỏi đất nước mình nữa; vì vua Ba-by-lôn đã chiếm từ sông Ai Cập cho đến sông Ơ-phơ-rát, mọi nơi vốn thuộc về vua Ai Cập.'),
(10211, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 24, 8, 'OT', 'Giê-hô-gia-kin lên ngôi làm vua khi được mười tám tuổi, và người trị vì tại Giê-ru-sa-lem ba tháng. Tên mẹ người là Nê-hu-shta, con gái Ê-len-than, người Giê-ru-sa-lem.'),
(10212, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 24, 9, 'OT', 'Vua ấy làm điều ác trong mắt Đức Giê-hô-va, giống như tất cả những gì cha mình đã làm.'),
(10213, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 24, 10, 'OT', 'Vào thời ấy, các đầy tớ của Nê-bu-cát-nết-xa, vua Ba-by-lôn, kéo lên đánh Giê-ru-sa-lem, và thành bị bao vây.'),
(10214, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 24, 11, 'OT', 'Vua Nê-bu-cát-nết-xa của Ba-by-lôn đến đánh thành phố, và các tôi tớ của ông vây hãm thành ấy.'),
(10215, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 24, 12, 'OT', 'Vua Giê-hô-gia-kin của Giu-đa ra đầu hàng vua Ba-by-lôn, cùng với mẹ vua, các tôi tớ, các quan lớn và các thái giám của vua; và vua Ba-by-lôn bắt vua trong năm thứ tám đời trị vì của mình.'),
(10216, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 24, 13, 'OT', 'Và người đem ra khỏi nơi đó mọi kho báu trong đền thờ của Đức Giê-hô-va, và các kho báu trong cung điện của vua; người cũng đập vụn tất cả các đồ dùng bằng vàng mà vua Sa-lô-môn của Ít-ra-en đã làm trong đền thờ của Đức Giê-hô-va, y như điều Đức Giê-hô-va đã phán.'),
(10217, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 24, 14, 'OT', 'Đức Giê-hô-va đã bắt đi đầy toàn thể dân Giê-ru-sa-lem, tất cả các quan chức và tất cả những chiến sĩ dũng cảm, mười ngàn người bị đày; và tất cả thợ khéo và thợ rèn. Không còn sót lại ai, ngoại trừ những người nghèo nhất trong dân của đất.'),
(10218, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 24, 15, 'OT', 'Và ông ta đã lưu đày Giô-áchin sang Ba-by-lôn, cùng với mẹ của vua, các vợ của vua, các hoạn quan của vua, và những người quyền thế trong xứ; tất cả những người này đã bị đưa đi lưu đày từ Giê-ru-sa-lem đến Ba-by-lôn.'),
(10219, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 24, 16, 'OT', 'Và tất cả những người trai tráng, bảy ngàn người, cùng các thợ khéo và thợ rèn, một ngàn người, tất cả đều là những chiến sĩ dũng cảm, nhà vua Ba-by-lôn đã dẫn họ đi đày đến Ba-by-lôn.'),
(10220, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 24, 17, 'OT', 'Vua Ba-by-lôn làm cho Ma-ta-nia, anh em họ của người ấy, lên ngôi làm vua thay cho người ấy, và đổi tên người ấy thành Xít-ki-gia.'),
(10221, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 24, 18, 'OT', 'Hai mươi mốt tuổi, Xít-ki-gia lên ngôi vua, và người trị vì tại Giê-ru-sa-lem mười một năm. Tên mẹ người là Ham-út-tal, con gái của Giê-ri-mi, người thành Li-bnah.'),
(10222, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 24, 19, 'OT', 'Và người làm điều ác trước mắt Đức Giê-hô-va, giống như tất cả những gì vua Giê-hô-ya-kim đã làm.'),
(10223, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 24, 20, 'OT', 'Vì cơn thịnh nộ của Đức Giê-hô-va giáng trên Giê-ru-sa-lem và trên Giu-đa, cho đến khi Ngài quăng họ ra khỏi mặt Ngài; và Xít-ki-gia đã nổi loạn cùng vua Ba-by-lôn.'),
(10224, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 25, 1, 'OT', 'Năm thứ chín đời trị vì của ông, vào tháng mười, ngày mùng mười tháng ấy, Nê-bu-cát-nết-xa, vua Ba-by-lôn, đến cùng toàn thể đạo binh người chống lại Giê-ru-sa-lem; người đóng trại quanh thành và xây các đồn lũy bao quanh nó.'),
(10225, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 25, 2, 'OT', 'Thành ấy bị vây khốn trong vòng vây cho đến năm thứ mười một đời vua Xít-ki-gia.'),
(10226, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 25, 3, 'OT', 'Vào ngày mồng chín của tháng đó, nạn đói trở nên nghiêm trọng trong thành, và không còn bánh cho dân trong xứ.'),
(10227, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 25, 4, 'OT', 'Thành bị vỡ, và mọi người lính chiến đã đi vào ban đêm theo đường cổng giữa hai bức tường, gần vườn của vua; còn người Can-đê thì đang vây quanh thành; vua đi theo đường đồng bằng.'),
(10228, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 25, 5, 'OT', 'Quân đội người Canh-đê đuổi theo vua, và bắt kịp ông tại các đồng bằng Giê-ri-cô; còn toàn thể đạo quân của ông thì tan rã khỏi ông.'),
(10229, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 25, 6, 'OT', 'Họ bắt vua, rồi dẫn vua lên cùng vua Ba-by-lôn tại Rib-lát; và họ xét xử vua.'),
(10230, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 25, 7, 'OT', 'Họ giết các con trai của Xi-đê-ki ngay trước mặt ông, và làm mù mắt Xi-đê-ki, rồi xiềng ông bằng xích đồng, và dẫn ông đến Ba-by-lôn.'),
(10231, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 25, 8, 'OT', 'Vào tháng năm, ngày mùng bảy của tháng, năm thứ mười chín đời vua Nê-bu-cát-nết-xa, vua Ba-by-lôn, thì Nê-bu-xa-ra-đan, quan tướng hầu cận vua Ba-by-lôn, đến Giê-ru-sa-lem.'),
(10232, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 25, 9, 'OT', 'Rồi người đốt cháy đền thờ của Đức Giê-hô-va, và đốt nhà của vua, cùng mọi nhà trong Giê-ru-sa-lem, và mọi nhà lớn đều bị người đốt bằng lửa.'),
(10233, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 25, 10, 'OT', 'Toàn thể đạo quân của người Can-đê, tức là những người ở dưới quyền viên chỉ huy các vệ sĩ, đã phá sập mọi bức tường thành Giê-ru-sa-lem ở chung quanh.'),
(10234, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 25, 11, 'OT', 'Và phần dân còn sót lại trong thành, những kẻ đào ngũ đã đầu hàng vua Ba-by-lôn, cùng phần sót lại của đám đông, thì Nê-bu-xa-ra-đan, quan tướng của các vệ sĩ, đã bắt đi đày.'),
(10235, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 25, 12, 'OT', 'Nhưng viên chỉ huy quân đội để lại những người nghèo trong xứ làm thợ trồng nho và làm ruộng.'),
(10236, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 25, 13, 'OT', 'Người Canh-đê đập vỡ các trụ đồng ở trong đền thờ Đức Giê-hô-va, và các đế đỡ, và cái biển đồng ở trong đền thờ Đức Giê-hô-va, và mang đồng của chúng về Ba-by-lôn.'),
(10237, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 25, 14, 'OT', 'Và những cái chảo, những cái xẻng, những cái dũa đèn, những cái muỗng, và tất cả các đồ dùng bằng đồng mà người ta dùng để hầu việc, thì họ đã lấy đi.'),
(10238, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 25, 15, 'OT', 'Và các chảo lửa, cùng các cái bát rưới mà bằng vàng thì lấy vàng, và những cái nào bằng bạc thì lấy bạc, viên chỉ huy quân đội đã mang đi.'),
(10239, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 25, 16, 'OT', 'Hai cái trụ, cái bể một và các chân đế mà Sa-lô-môn đã làm cho đền thờ Đức Giê-hô-va; đồng của tất cả các đồ đó không thể cân được.'),
(10240, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 25, 17, 'OT', 'Chiều cao của cái trụ thứ nhất là mười tám thước, và cái đầu trụ bằng đồng ở trên nó; chiều cao của cái đầu trụ là ba thước; xung quanh cái đầu trụ có hình lưới và quả lựu, tất cả đều bằng đồng; và cái trụ thứ hai cũng giống như vậy, có hình lưới quấn quanh.'),
(10241, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 25, 18, 'OT', 'Vua đội trưởng các đầu bếp bắt thầy tế lễ thượng phẩm Sê-rai, và thầy tế lễ cấp hai Xáp-pha-nia, và ba người giữ cửa.'),
(10242, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 25, 19, 'OT', 'Và người ấy bắt một viên thái giám, là người chỉ huy các binh sĩ trong thành, cùng năm người trong những kẻ thân cận vua mà người ta tìm thấy trong thành, và viên chánh văn thư của đạo binh, người đã kiểm tra dân sự trong xứ, cùng sáu mươi người dân trong xứ mà người ta tìm thấy trong thành.'),
(10243, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 25, 20, 'OT', 'Vua Nê-bu-xa-ra-đan, chỉ huy trưởng các vệ binh, bắt những người ấy và dẫn họ đến vua Ba-by-lôn tại Ríp-la.'),
(10244, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 25, 21, 'OT', 'Vua Ba-by-lôn đánh giết họ tại Rib-lah, trong đất Ha-mát; và người ta bắt Giu-đa phải lưu đày khỏi đất nước của họ.'),
(10245, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 25, 22, 'OT', 'Dân sự còn sót lại trong đất Giu-đa, mà Nê-bu-cát-nết-xa, vua Ba-by-lôn, đã để lại, thì người đó đặt Ghê-đa-lia, con trai A-hi-kam, con trai Xáp-phan, làm quan cai trị họ.'),
(10246, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 25, 23, 'OT', 'Các viên tướng toàn quân và những người đi theo họ nghe rằng vua Ba-by-lôn đã đặt Ghê-đa-lia làm quan tổng trấn, thì họ và các thuộc hạ của họ đều đến cùng Ghê-đa-lia tại Mít-pa, gồm Ích-ma-ên con trai Nê-than-gia, Giô-ha-nan con trai Ca-rê-ách, Xê-rai-ah con trai Tan-hu-mết người Nê-tô-pha-thi, và Gia-a-za-niah con trai người Ma-a-khat, họ và các thuộc hạ của họ.'),
(10247, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 25, 24, 'OT', 'Gẹ-đa-lia đã thề nguyện cùng họ và những người của họ, rồi nói với họ: "Đừng sợ phải phục vụ người Canh-đê; hãy ở lại trong đất này, và phục vụ vua Ba-by-lôn, thì các ngươi sẽ được bình an."'),
(10248, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 25, 25, 'OT', 'Vào tháng bảy, thì Ích-ma-ên, con trai của Nê-than-nia, con trai Ê-li-sa-ma, thuộc dòng dõi vua, đến cùng mười người đàn ông với mình, và họ đánh giết Ghê-đa-lia, khiến ông chết, cùng các người Giu-đa và người Can-đê đang ở với ông tại Mít-ba.'),
(10249, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 25, 26, 'OT', 'Dân chúng, từ kẻ nhỏ đến người lớn, cùng các quan chỉ huy quân đội, đều đứng dậy và đi đến Ai Cập, vì họ sợ người Canh-đê.'),
(10250, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 25, 27, 'OT', 'Vào năm ba mươi bảy của cuộc lưu đày Giô-ya-kim, vua Giu-đa, vào tháng mười hai, ngày hai mươi bảy của tháng ấy, Ê-vít mê-rô-đác, vua Ba-by-lôn, trong năm người bắt đầu trị vì, đã cho tha Giô-ya-kim, vua Giu-đa, ra khỏi ngục.'),
(10251, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 25, 28, 'OT', 'Người nói lời tốt lành với ông, và đặt ngôi ông cao hơn ngôi các vua đang ở với ông tại Ba-by-lôn.'),
(10252, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 25, 29, 'OT', 'Và người thay đổi quần áo tù nhân của mình; và người ăn bánh hằng định trước mặt vua mọi ngày trong đời sống của mình.'),
(10253, 12, 'GOI_vi', 'GOI_vi', 'vi', '2KI', 25, 30, 'OT', 'Và phần ăn của ông được cấp cho mỗi ngày một lần, một phần ăn đều đặn từ vua, suốt mọi ngày đời sống của ông.'),
(10254, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 1, 'OT', 'A-đam, Sết, Enốt.'),
(10255, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 2, 'OT', 'Kê-nan, Ma-ha-la-lên, Giê-rết,'),
(10256, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 3, 'OT', 'Ha-nóc, Mê-tu-sanh, La-méc.'),
(10257, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 4, 'OT', 'Nô-ê, Sêm, Hăm và Gia-phết.'),
(10258, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 5, 'OT', 'Các con trai của Y-phết là Gô-me, Mác-ốc, Ma-đai, Gia-van, Tu-banh, Mê-sêch và Ti-rát.'),
(10259, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 6, 'OT', 'Các con trai của Gô-me là Ách-ken-za, và Đíp-hát, và Tô-ga-ma.'),
(10260, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 7, 'OT', 'Các con trai của Javan là Elisa, Thar-si-sa, Kitim và Rô-đa-nim.'),
(10261, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 8, 'OT', 'Con cái của Hăm là Cush, Mizraim, Put và Ca-na-an.'),
(10262, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 9, 'OT', 'Các con trai của Cush là Seba, Havilah, Sabta, Raama và Sabtechaca. Các con trai của Raama là Sheba và Dedan.'),
(10263, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 10, 'OT', 'Cúch sinh ra Nim-rốt; người ấy là người đầu tiên trở nên cường tráng trên đất.'),
(10264, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 11, 'OT', 'Mi-sơ-ra-im sinh ra các dân Lu-đi, các dân A-na-mi, các dân Lê-ha-bi, và các dân Nap-tu-hi.'),
(10265, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 12, 'OT', 'Và người Phathô-ri-mít, và người Ca-slu-hít, là những người xuất phát từ đó người Phi-li-tin, và người Ca-phê-tô-rit.'),
(10266, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 13, 'OT', 'Ca-na-an sinh ra Xi-đôn, con đầu lòng của người, và Hết.'),
(10267, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 14, 'OT', 'và người Y-bu-si, và người A-mô-rị, và người Gi-ri-ga-si,'),
(10268, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 15, 'OT', 'và người Hê-vi, và người A-ri-ki, và người Xi-ni,'),
(10269, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 16, 'OT', 'và người Ar-vát, và người Xem-ma-ri, và người Ha-mát.'),
(10270, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 17, 'OT', 'Con cái của Sêm là Ê-lam, A-su, A-rập-sác, Lud, A-ram, Ót, Hút, Gê-thê và Mê-séc.'),
(10271, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 18, 'OT', 'Ar-phác-sát sinh ra Sê-la, và Sê-la sinh ra Ê-béc.'),
(10272, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 19, 'OT', 'Ê-bép sinh được hai người con trai; tên một người là Phê-léc, vì trong đời người ấy đất bị chia rẽ; và tên người anh em của người ấy là Gia-ktanh.'),
(10273, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 20, 'OT', 'Và Giốc-tan sinh ra An-mô-đa, Sê-lép, Ha-xa-ma-vết và Giê-rách.'),
(10274, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 21, 'OT', 'Và Hadoram, và Uzal, và Dikla.'),
(10275, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 22, 'OT', 'Và Ê-banh, và A-bi-ma-ên, và Sê-ba,'),
(10276, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 23, 'OT', 'Ô-phít, Ha-va-lát và Giô-báp. Tất cả những người này là con trai của Giốc-tan.'),
(10277, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 24, 'OT', 'Sêm, Áp-ra-cát, Xê-la,'),
(10278, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 25, 'OT', 'Ê-béc, Phê-léc, Rê-ú,'),
(10279, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 26, 'OT', 'Sê-rúc, Na-hô, Ta-ra,'),
(10280, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 27, 'OT', 'Áp-ram, chính là Áp-ra-ham.'),
(10281, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 28, 'OT', 'Các con trai của Áp-ra-ham là Y-sác và Ích-ma-ên.'),
(10282, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 29, 'OT', 'Đây là các dòng dõi của họ: Nê-bai-ốt, con cả của Ích-ma-ên, rồi Kê-đa, và A-đbê-ên, và Míp-xam.'),
(10283, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 30, 'OT', 'Mishma, Dumah, Ma-sa, Hadad và Tema.'),
(10284, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 31, 'OT', 'Jetur, Naphish và Kedemah. Đây là các con trai của Y-sác-mi-ên.'),
(10285, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 32, 'OT', 'Các con trai của Keturah, người hầu của Áp-ra-ham, là Xim-ram, Giốc-san, Mê-đan, Mi-đi-an, Ích-bác và Su-ha. Các con trai của Giốc-san là Sê-ba và Đê-đan.'),
(10286, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 33, 'OT', 'Và các con trai của Ma-đi-ên là Ê-pha, Ê-pher, Ha-nóc, A-bi-đa và Ên-đa-a. Tất cả những người này là con trai của Kê-tu-ra.'),
(10287, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 34, 'OT', 'Áp-ra-ham sinh ra Y-sác. Các con trai của Y-sác là Ê-sau và Ít-ra-ên.'),
(10288, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 35, 'OT', 'Con cái của Ê-sau: Ê-líp-ha, Rê-u-ên, Giê-u, Gia-lam và Cô-rách.'),
(10289, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 36, 'OT', 'Các con trai của Ê-li-pha: Tê-man, Ô-ma, Xê-phi, Gátam, Kê-nác, Tim-na và A-ma-léc.'),
(10290, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 37, 'OT', 'Những người con trai của Rê-uel là Na-hát, Xe-ranh, Sam-ma và Mít-xa.'),
(10291, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 38, 'OT', 'Và các con trai của Sê-ir là Lô-tan, Sô-banh, Xi-bê-ôn, A-na, Đích-sôn, Ê-xe, và Đích-xan.'),
(10292, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 39, 'OT', 'Các con trai của Lô-tan là Hô-ri và Hô-mam; và Tim-na là em gái của Lô-tan.'),
(10293, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 40, 'OT', 'Các con trai của Sô-banh: A-li-an, Ma-na-hát, Ê-banh, Sê-phi và Ô-nam. Các con trai của Xi-bê-ôn: A-i-a và A-na.'),
(10294, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 41, 'OT', 'Con của A-na là Đi-sôn. Con của Đi-sôn là Ha-mơ-ran, Ê-sơ-ban, Yít-ran và Kê-ran.'),
(10295, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 42, 'OT', 'Con trai của Ê-xe: Binh-an, Xa-va và Gia-can. Con trai của Đích-sôn: Út và A-ran.'),
(10296, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 43, 'OT', 'Các vua nầy trị vì trong xứ Ê-đôm, trước khi có vua trị vì trên dân Y-sơ-ra-ên: Bê-la, con trai của Bê-ô, và tên thành người là Đin-ha-ba.'),
(10297, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 44, 'OT', 'Bấy giờ Ba-la qua đời, và Giô-báp, con trai của Sê-rách, người Bốt-ra, lên ngôi vua thế cho người.'),
(10298, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 45, 'OT', 'Khi Giô-báp qua đời, Húc-sam, người xứ Thê-man, lên ngôi vua thay ông.'),
(10299, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 46, 'OT', 'Hu-sam qua đời, và Ha-đát, con trai của Bê-đát, đánh bại dân Mi-đi-an tại đồng bằng Mô-áp, lên ngôi vua thay người; tên thành người là A-vít.'),
(10300, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 47, 'OT', 'Và Hadát qua đời, và Sam-la từ Ma-xrê-ca lên ngôi kế vị người.'),
(10301, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 48, 'OT', 'Sam-la qua đời, và Sau-lơ, người Rê-hô-bốt thuộc vùng bên bờ sông, lên ngôi vua thay cho người.'),
(10302, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 49, 'OT', 'Sau khi Sau-ên qua đời, Ba-an-ha-nan, con trai của A-cha-bô, lên ngôi vua thay người.'),
(10303, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 50, 'OT', 'Bấy giờ Ba-anh-ha-nan qua đời, và Hadát trị vì thay người. Tên thành người là Pai, và tên vợ người là Mê-hê-ta-bên, con gái của Mát-rết, cháu gái của Mê-za-háp.'),
(10304, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 51, 'OT', 'Ha-đát qua đời. Những lãnh tụ của Ê-đôm là: lãnh tụ Tim-na, lãnh tụ A-li-ách, lãnh tụ Giê-thết.'),
(10305, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 52, 'OT', 'Đầu lĩnh A-hô-li-ba-ma, đầu lĩnh Ê-la, đầu lĩnh Phi-nôn.'),
(10306, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 53, 'OT', 'Các tộc trưởng là Kênách, tộc trưởng Tê-man, tộc trưởng Míp-xa.'),
(10307, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 1, 54, 'OT', 'Quận trưởng Ma-ghi-đi-ên, quận trưởng I-ram. Đây là các quận trưởng của Ê-đôm.'),
(10308, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 1, 'OT', 'Đây là các con trai của Ích-thiên: Ru-bên, Si-mê-ôn, Lê-vi và Giu-đa, Y-xa-sác và Xép-u-lun.'),
(10309, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 2, 'OT', 'Dân, Giô-sép và Bên-gia-min, Náp-ta-li, Gát và A-xe.'),
(10310, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 3, 'OT', 'Con trai của Giu-đa là Ê-r, Ô-nam và Sê-la; ba người sinh ra cho người bởi con gái của Su-a người Ca-na-an. Ê-r, con cả của Giu-đa, là ác trước mặt Đức Giê-hô-va, nên Ngài giết người.'),
(10311, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 4, 'OT', 'Ta-ma, con dâu của ông, sinh cho ông Phê-rết và Sê-rách. Tất cả con trai của Giu-đa là năm người.'),
(10312, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 5, 'OT', 'Các con trai của Pha-rết: Hết-rôn và Ha-mun.'),
(10313, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 6, 'OT', 'Các con trai của Xe-ra là Xim-ri, Ê-than, Hê-man, Canh-côn và A-ra; tất cả năm người.'),
(10314, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 7, 'OT', 'Con cái của Carmi gồm Achar, kẻ gây rối cho Y-sơ-ra-ên, người đã phạm tội trong vật bị rủa sả.'),
(10315, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 8, 'OT', 'Các con trai của Ê-than là A-xa-ri-ah.'),
(10316, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 9, 'OT', 'Các con trai của Hết-rôn, những người sinh ra cho người, là Giê-ra-ha-mên, Ram và Kê-lu-bai.'),
(10317, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 10, 'OT', 'Râm sinh A-min-na-đáp; A-min-na-đáp sinh Na-hôn, người lãnh đạo của con cháu Giu-đa.'),
(10318, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 11, 'OT', 'Na-ha-sôn sinh ra Sát-ma, và Sát-ma sinh ra Bô-az.'),
(10319, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 12, 'OT', 'Bô-az sinh ra Óc-đết, và Óc-đết sinh ra Y-sai.'),
(10320, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 13, 'OT', 'Và Ích-sai sinh người con đầu lòng là Ê-li-áp, và A-bi-na-đáp là người thứ hai, và Sim-ma là người thứ ba,'),
(10321, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 14, 'OT', 'Nét-ha-nên là người thứ tư, Ra-đai là người thứ năm.'),
(10322, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 15, 'OT', 'Ô-xem người thứ sáu, Đa-vít người thứ bảy.'),
(10323, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 16, 'OT', 'Các chị em của họ là Xê-ru-i-a và A-bi-gai-l. Các con trai của Xê-ru-i-a là A-bi-sai, Giô-ab và A-sa-ên, ba người.'),
(10324, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 17, 'OT', 'A-bi-gai-ên sinh ra A-ma-sa; và cha của A-ma-sa là Jether, người Ích-ma-ên.'),
(10325, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 18, 'OT', 'Ca-lép, con trai của Hết-rôn, sinh ra Ách-u-ba, vợ người, và Giê-ri-ốt; những con trai của người là Giê-sơ, và Xô-báp, và Ác-đôn.'),
(10326, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 19, 'OT', 'Ách-su-ba qua đời, rồi Ca-lép cưới Ê-phrát, và bà sinh ra cho ông Húc.'),
(10327, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 20, 'OT', 'Và Hur sinh ra Uri, và Uri sinh ra Bết-xa-ên.'),
(10328, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 21, 'OT', 'Sau đó, Hết-rôn lấy con gái của Ma-khia, cha của Ghi-lê-át, khi ông đã sáu mươi tuổi; bà sinh cho ông Xê-gub.'),
(10329, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 22, 'OT', 'Sê-gub sinh ra Gia-ir; người có hai mươi ba thành trong đất Ga-la-át.'),
(10330, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 23, 'OT', 'Ghê-su-rơ và A-ram đã chiếm lấy các thị trấn của Jair, cùng với Kenath và các thị trấn thuộc về nó, tổng cộng sáu mươi thành. Tất cả những nơi này thuộc về các con trai của Machir, cha của Ga-la-át.'),
(10331, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 24, 'OT', 'Sau khi Hết-rôn qua đời tại Kha-lép Ê-phơ-ra-tha, Áp-i-ah, vợ của Hết-rôn, sinh cho người con trai Ách-úp, cha của Tê-koa.'),
(10332, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 25, 'OT', 'Con trai của Y-đa-mê-ên, trưởng nam của Hết-rôn, là Ram, trưởng nam, rồi Bu-na, và Ô-ren, và Ô-xem, và A-hi-gia.'),
(10333, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 26, 'OT', 'Giê-ra-ha-mên có một người vợ khác tên là A-ta-ra; bà ấy là mẹ của Ô-nam.'),
(10334, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 27, 'OT', 'Các con trai của Ram, con trưởng của Giê-ra-ha-mên, là Ma-ách, và Gia-min, và Ê-kẹt.'),
(10335, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 28, 'OT', 'Con trai của Ô-nam là Sâm-mai và Gia-đa. Con trai của Sâm-mai là Na-đáp và A-bi-sú.'),
(10336, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 29, 'OT', 'Tên vợ của A-bi-sú là A-bi-hai, và bà sinh cho ông A-han và Mô-lít.'),
(10337, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 30, 'OT', 'Con trai của Na-đáp là Seled và Appaim; nhưng Seled chết, không có con trai.'),
(10338, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 31, 'OT', 'Con cái của A-phai-im là I-si. Con cái của I-si là Sê-san. Con cái của Sê-san là A-hlai.'),
(10339, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 32, 'OT', 'Các con trai của Y-đa, anh em của Sham-mai, là E-te và Giô-na-than; và E-te qua đời mà không có con cái.'),
(10340, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 33, 'OT', 'Con cái của Giô-na-than là Phê-lết và Xa-xa. Đây là những người con trai của Giê-ra-ha-mên.'),
(10341, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 34, 'OT', 'Sê-sam không có con trai, chỉ có con gái; Sê-sam có một đầy tớ người Ê-díp-tô, tên là Gia-cha.'),
(10342, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 35, 'OT', 'Xê-san gả con gái mình cho Giác, đầy tớ mình, làm vợ; và người sanh cho ông ta A-tai.'),
(10343, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 36, 'OT', 'At-tai sinh ra Na-than, và Na-than sinh ra Xa-bát.'),
(10344, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 37, 'OT', 'Và Xa-bát sinh ra Ép-phal, và Ép-phal sinh ra Ô-bết.'),
(10345, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 38, 'OT', 'Và Ô-bết sinh ra Giê-hu, và Giê-hu sinh ra A-xa-ri-ah.'),
(10346, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 39, 'OT', 'A-xa-ri-ah sinh ra Ha-lết, và Ha-lết sinh ra Ê-lê-a-sa.'),
(10347, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 40, 'OT', 'Và Ê-lê-a-sa sinh Xít-mai, và Xít-mai sinh Sa-lum.'),
(10348, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 41, 'OT', 'Sau-lum sinh Y-ke-am-ia, và Y-ke-am-ia sinh Ê-li-sa-ma.'),
(10349, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 42, 'OT', 'Các con trai của Ca-lép, anh em của Giê-ra-ha-mên, là Mê-sa, con đầu lòng của người, là tổ phụ của Xíp; và các con trai của Ma-rê-sa, tổ phụ của Hếp-rôn.'),
(10350, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 43, 'OT', 'Các con trai của Hếp-rôn là Cô-ra, Táp-bu-a, Rê-kem và Sê-ma.'),
(10351, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 44, 'OT', 'Sê-ma sinh ra Ra-ham, cha của Giôc-ko-am; và Rê-kem sinh ra Sâm-mai.'),
(10352, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 45, 'OT', 'Con trai của Sơ-mai là Ma-on; và Ma-on là cha của Bết-xua.'),
(10353, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 46, 'OT', 'E-pha, người thứ thiếp của Ca-lép, sinh ra Ha-ran, Mô-xa và Ga-xe-x; và Ha-ran sinh ra Ga-xe-x.'),
(10354, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 47, 'OT', 'Con cái của Jahdai là Regem, Giô-tham, Geshan, Pelet, Ephah và Shaaph.'),
(10355, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 48, 'OT', 'Ma-ách, người thứ thiếp của Ca-lép, sinh ra Sê-bec và Tích-ha-na.'),
(10356, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 49, 'OT', 'Người sinh ra Sa-áp, cha của Ma-đăm-na, và Sê-va, cha của Ma-chen-na và cha của Gi-bê-a; và con gái của Ca-lép là Ách-sa.'),
(10357, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 50, 'OT', 'Đây là các con trai của Ca-lép, con trai của Hur, trưởng nam của Ép-ra-tha: Sô-banh, cha của Ki-ri-át Giê-a-rim.'),
(10358, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 51, 'OT', 'Sa-lơ-ma, cha của Bết-lê-hem; Ha-rép, cha của Bết Ga-đe.'),
(10359, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 52, 'OT', 'Sô-banh và các con trai của người là cha đẻ của Kir-iath-ye-a-rim; người là người trông nom phân nửa Man-hết.'),
(10360, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 53, 'OT', 'Các họ hàng ở Kiriat-yearim: người Ithri, người Pu-thi, người Shu-ma-thi và người Mish-ra-thi; từ những người ấy xuất ra các Zare-thai và các Es-thau-li.'),
(10361, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 54, 'OT', 'Con cái của Sát-ma gồm Bết-lê-hem, người Nê-tô-phát, A-ta-rốt, nhà Giô-áp, phân nửa người Ma-na-hết, và người Xô-rít.'),
(10362, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 2, 55, 'OT', 'Các gia đình thợ thông văn sống tại Ja-bết gồm người Ti-ra-thít, người Si-mê-a-thít và người Xu-cát-hít. Đó là người Kênít xuất xứ từ Khamát, cha của nhà Rê-cáp.'),
(10363, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 3, 1, 'OT', 'Đây là các con trai của Đa-vít, sinh ra cho người tại Hếp-rôn: con cả là Am-nôn, mẹ là A-hi-nô-am, người Gi-xe-rem; con thứ hai là Đa-ni-ên, mẹ là A-bi-gai-ên, người Ca-rem.'),
(10364, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 3, 2, 'OT', 'Con thứ ba là Áp-xa-lôm, con trai của Ma-a-ca, con gái của Ta-lmai, vua xứ Ghê-sua; con thứ tư là A-đô-ni-gia, con trai của Ha-git.'),
(10365, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 3, 3, 'OT', 'Người thứ năm, Sê-pha-ti-a, mẹ là A-bi-tal; người thứ sáu, Y-thơ-râm, mẹ là Ếc-la, vợ người.'),
(10366, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 3, 4, 'OT', 'Sáu người con sinh ra cho ông tại Hếp-rôn; và ông trị vì tại đó bảy năm sáu tháng; còn tại Giê-ru-sa-lem, ông trị vì ba mươi ba năm.'),
(10367, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 3, 5, 'OT', 'Còn đây là những người sinh ra cho ông tại Giê-ru-sa-lem: Sê-ma, Sô-báp, Na-than và Sa-lô-môn, bốn người con trai, mẹ là Bat-xua, con gái của Am-mi-ên.'),
(10368, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 3, 6, 'OT', 'Ib-ha, và E-li-sa-ma, và E-li-phe-lết.'),
(10369, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 3, 7, 'OT', 'Và Nô-ga, và Né-phéch, và Gia-phia.'),
(10370, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 3, 8, 'OT', 'Ê-li-sa-ma, Ê-li-a-đa và Ê-li-phê-lết, tất cả chín người.'),
(10371, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 3, 9, 'OT', 'Tất cả các con trai của Đa-vít, ngoài các con trai của các thứ phi, và Ta-ma, em gái của chúng.'),
(10372, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 3, 10, 'OT', 'Con trai của Sa-lô-môn là Rê-hô-bô-am, A-bi-gia con trai ông, A-sa con trai ông, và Giê-hô-sa-phát con trai ông.'),
(10373, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 3, 11, 'OT', 'Giô-ram là con trai của người, A-cha-xia là con trai của người, Giô-ách là con trai của người.'),
(10374, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 3, 12, 'OT', 'Am-xia, con trai của người; A-xa-ria, con trai của người; Giô-tham, con trai của người;'),
(10375, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 3, 13, 'OT', 'A-cha là con trai người, Hít-xe-ki-a là con trai người, Ma-na-xe là con trai người.'),
(10376, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 3, 14, 'OT', 'A-môn là con trai người; Giô-si-a là con trai A-môn.'),
(10377, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 3, 15, 'OT', 'Con trai của Giô-si-a là: con cả là Giô-ha-nan, con thứ nhì là Giê-hô-i-a-kim, con thứ ba là Xi-đê-ki-a, con thứ tư là Sa-lum.'),
(10378, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 3, 16, 'OT', 'Các con trai của Giê-hô-ya-kim: Giê-khôn-gia là con trai ông, và Xi-đê-ki-a là con trai ông.'),
(10379, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 3, 17, 'OT', 'Các con trai của Giê-kô-nia là A-xia và Sa-la-thi-ên, con trai ông ấy.'),
(10380, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 3, 18, 'OT', 'Ma-lcị-ra, Phê-đai-a, Sê-na-a-xa, Giê-cam-mi-a, Hô-sa-ma và Nê-đa-bi-a.'),
(10381, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 3, 19, 'OT', 'Con cái của Phê-đai-a là Xê-ru-báp-banh và Si-mê-i; và con cái của Xê-ru-báp-banh là Mê-thu-lam, Ha-na-nia và Sê-lô-mít, em gái họ.'),
(10382, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 3, 20, 'OT', 'Và Hát-su-ba, và Ô-hên, và Bê-rê-ki-a, và Ha-sa-đi-a, và Giu-sáp-hết-xết; tất cả năm người.'),
(10383, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 3, 21, 'OT', 'Các con trai của Hananiah là Pelatiah và Jesaiah; các con trai của Refaiah, các con trai của Arnan, các con trai của Obadyah, các con trai của Shechaniah.'),
(10384, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 3, 22, 'OT', 'Các con trai của Sê-can-ghi-a là Sê-ma-ia; các con trai của Sê-ma-ia là Ha-tút, và I-ge-ên, và Ba-ri-ách, và Nê-a-ri-ách, và Sa-phát, tất cả sáu người.'),
(10385, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 3, 23, 'OT', 'Và các con trai của Nê-a-ria: Ê-li-ô-ênai, và Hít-ki-a, và A-xơ-ri-cam, ba người.'),
(10386, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 3, 24, 'OT', 'Còn các con trai của Ê-li-ô-ênai là Hô-đai-a, Ê-li-a-síp, Phi-lai-a, A-cúc, Giô-ha-nan, Đa-lai-a và A-na-ni, tất cả bảy người.'),
(10387, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 1, 'OT', 'Các con trai của Giu-đa: Pha-rết, Hết-rôn, Ca-mi, Hu và Sô-ba-l.'),
(10388, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 2, 'OT', 'Và Rê-a-gia, con trai của Sô-banh, sinh ra Gia-thát; Gia-thát sinh ra A-hu-mai và La-hát. Những người nầy là các gia tộc của người Xô-ra-thít.'),
(10389, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 3, 'OT', 'Và đây là những người con trai của Ê-tam: Y-xơ-rên, Y-sơ-ma và Y-đa-bát; và tên người chị em của họ là Ha-xe-lê-poni.'),
(10390, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 4, 'OT', 'Và Pha-nu-ên là cha của Ghê-đô, và Ê-xe là cha của Hu-sa. Đây là các con trai của Hur, con trưởng của Ép-ra-tha, cha của Bết-lê-hem.'),
(10391, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 5, 'OT', 'Và Ashur, cha của Tekoa, có hai vợ là Helah và Na-a-ra.'),
(10392, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 6, 'OT', 'Na-a-ra sinh cho ông Ahuzam, Hepher, Temeni và Haahashtari. Đây là các con trai của Na-a-ra.'),
(10393, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 7, 'OT', 'Các con trai của Hê-la là Xê-rết, Y-xa-ha và Ê-th-nan.'),
(10394, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 8, 'OT', 'Và Kôts sinh ra Anub và Xôbêba, cùng các gia đình của A-ha-ranh, con trai của Ha-rum.'),
(10395, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 9, 'OT', 'Và Giáp-éts được tôn trọng hơn các anh em mình; mẹ người đặt tên người là Giáp-éts, nói rằng: "Vì tôi đã sinh người trong sự đau đớn."'),
(10396, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 10, 'OT', 'Và Gia-bết cầu khẩn Đức Chúa Trời của Y-sơ-ra-ên, rằng: "Nguyện Ngài thật sự ban phước cho tôi, mở rộng bờ cõi tôi, tay Ngài ở cùng tôi, và giữ tôi khỏi điều ác, để nó không gây buồn bã cho tôi!" Và Đức Chúa Trời đã làm theo điều người đã xin.'),
(10397, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 11, 'OT', 'Chê-lub, anh của Su-ha, sinh ra Mê-hia, là cha của Ê-thôn.'),
(10398, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 12, 'OT', 'Ê-xton sinh ra Bết-ra-pha, Pa-xê-ách và Thê-hin-na, cha của Ích-na-hát. Những người nầy là dân ở Rê-cha.'),
(10399, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 13, 'OT', 'Và các con trai của Kê-nách là Ô-thi-ni-ên và Xê-rai-ah; và con trai của Ô-thi-ni-ên là Ha-thát.'),
(10400, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 14, 'OT', 'Me-ôn-tai sinh ra Ô-phơ-ra; và Xê-rai-a sinh ra Giô-ab, cha của thung lũng Thợ thủ công, vì họ là thợ thủ công.'),
(10401, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 15, 'OT', 'Và các con trai của Ca-lép, con trai của Y-phu-nê, là I-ru, Ê-la và Na-am. Các con trai của Ê-la là Kê-nát.'),
(10402, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 16, 'OT', 'Con trai của Giê-ha-lê-lết là Xíp, Xípah, Ti-ri-a và A-sa-rên.'),
(10403, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 17, 'OT', 'Con trai của Ê-xơ-ra là Giê-thê, Mê-rết, Ê-phẹt và Gia-lôn. Người ấy sinh Mi-ri-am, Sâm-mai và Ích-bách, cha của Ê-them-ô-a.'),
(10404, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 18, 'OT', 'Và vợ người là người nữ Giu-đa sinh ra Giê-rết, cha của Ghê-đôr, và Hê-ber, cha của Sô-cô, và Giê-ku-thi-ên, cha của Xa-nôa. Và đây là các con trai của Bít-hia, con gái của Pháp-lao, mà Ma-rết đã cưới.'),
(10405, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 19, 'OT', 'Và các con trai của vợ Hodia, em gái của Na-ham, cha của Kê-i-lah người Gạt-mi, và Ét-thê-mô-a người Ma-a-cát.'),
(10406, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 20, 'OT', 'Các con trai của Si-môn là Am-nôn, Rin-na, Ben-ha-nan và Ti-lôn. Các con trai của Y-si là Xô-hết và Ben-xô-hết.'),
(10407, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 21, 'OT', 'Con trai của Sê-la, con trai của Giu-đa, gồm có Ê-rơ, cha của Lê-ca; và La-a-đa, cha của Ma-rê-sa; và các họ hàng của nhà thợ dệt vải gai mịn, thuộc nhà Ách-bê-a.'),
(10408, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 22, 'OT', 'Và Giô-kim, những người của Cô-xe-ba, Giô-ách, và Xa-ráp, người cai trị tại Mô-áp, và Gia-subi Lê-hem. Những điều này là những điều xưa cũ.'),
(10409, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 23, 'OT', 'Họ là những thợ gốm, và những người ở giữa các luống cây và hàng rào; họ sống đó cùng với vua để làm công việc của người.'),
(10410, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 24, 'OT', 'Con trai của Si-mê-ôn là Nê-mu-ên, Yamín, Yaríp, Xe-ra và Sau-lơ.'),
(10411, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 25, 'OT', 'Sách-lum, con trai của người, Míp-sam, con trai của người, Mít-sma, con trai của người.'),
(10412, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 26, 'OT', 'Các con trai của Mích-ma: Ham-mu-ên, con trai người; Xác-cua, con trai người; Sê-mi, con trai người.'),
(10413, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 27, 'OT', 'Si-mê-i có mười sáu con trai và sáu con gái; còn các anh em ông thì không có nhiều con, và toàn thể dòng họ họ cũng không sinh sôi đông đúc như con cháu của Giu-đa.'),
(10414, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 28, 'OT', 'Họ ở tại Bê-er-Sê-ba, Mô-la-đa và Ha-xa Sô-ách.'),
(10415, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 29, 'OT', 'Tại Binh-la, tại Et-xem, và tại Tô-lát.'),
(10416, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 30, 'OT', 'Và tại Bê-tu-ên, và tại Hô-ram, và tại Xi-klác,'),
(10417, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 31, 'OT', 'Và tại Bết Mác-ca-bốt, và Ha-xa-xu-sim, và tại Bết Bi-rê-i, và tại Sa-a-ra-im. Đây là các thành của họ cho đến thời vua Đa-vít trị vì.'),
(10418, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 32, 'OT', 'Và các làng mạc của chúng là Ê-tam, và Ain, Rim-môn, và Tô-chen, và A-sán, năm thành phố:'),
(10419, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 33, 'OT', 'Và tất cả các làng mạc thuộc về họ, nằm chung quanh những thành phố ấy cho đến Ba-anh. Đây là nơi ở của họ, và là gia phả của họ.'),
(10420, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 34, 'OT', 'Và Mê-sô-báp, và Gia-miếc, và Giô-sa, con trai của A-ma-xia,'),
(10421, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 35, 'OT', 'Và Giô-ên, và Giê-hu con trai của Giô-xi-bia, con trai của Xê-rai-ah, con trai của A-xi-ên.'),
(10422, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 36, 'OT', 'Và Ê-li-ô-e-nai, và Gia-a-cô-ba, và Giết-hô-hai-a, và A-xa-ia, và A-đi-ên, và Giết-xi-mi-ên, và Bê-na-gia.'),
(10423, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 37, 'OT', 'Và Xí-za, con trai của Síp-hi, con trai của A-lôn, con trai của Giê-đa-i-a, con trai của Sim-ri, con trai của Sê-ma-gia.'),
(10424, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 38, 'OT', 'Những người này được ghi theo tên, là các quan trưởng trong các chi tộc của họ; và nhà các tổ phụ họ ngày càng thêm đông.'),
(10425, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 39, 'OT', 'Họ đi đến lối vào Ghê-đô, đến phía đông của thung lũng, để tìm đồng cỏ cho bầy chiên của mình.'),
(10426, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 40, 'OT', 'Họ đã tìm được đồng cỏ béo tốt và tốt lành, đất rộng rãi, yên tĩnh và thanh bình; vì những người thuộc dòng dõi Hăm trước kia đã sống ở đó.'),
(10427, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 41, 'OT', 'Và những người này được ghi theo tên, đã đến vào các ngày của Ê-xê-chia, vua Giu-đa; họ đánh các trại của dân cư nơi đó, và các nơi ở được tìm thấy tại đó, rồi tiêu diệt sạch chúng cho đến ngày nay; và họ ở lại trong các nơi ở của những người ấy, vì tại đó có đồng cỏ cho các bầy chiên của họ.'),
(10428, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 42, 'OT', 'Và từ họ, tức là những con trai của Si-mê-ôn, đã đi đến núi Seir năm trăm người, và có Pelatiah, Neariah, Rephaiah, và Uziel, các con trai của Ishi, làm lãnh đạo họ.'),
(10429, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 4, 43, 'OT', 'Họ đánh những người sót lại của A-ma-léc đã trốn thoát, và ở đó cho đến ngày nay.'),
(10430, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 5, 1, 'OT', 'Và các con trai của Ru-bên, con trưởng nam của Ít-ra-en, người vốn là trưởng nam; nhưng vì người đã làm ô uế giường cha mình, nên quyền sinh đôi của người đã được trao cho các con trai của Giô-sép, con trai Ít-ra-en; tuy nhiên, người không được ghi vào gia phổ theo quyền trưởng nam.'),
(10431, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 5, 2, 'OT', 'Vì Giu-đa mạnh hơn các anh em mình, và từ người ấy phát xuất ra vị lãnh đạo; nhưng quyền trưởng nam thuộc về Giô-sép.'),
(10432, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 5, 3, 'OT', 'Các con trai của Ru-bên, con trưởng của Ít-ra-en, là Ha-nóc, Pha-lu, Hết-rôn và Carmi.'),
(10433, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 5, 4, 'OT', 'Con trai của Giô-ên là Sê-ma-gia, con trai người là Gô-gơ, con trai người là Sê-mai.'),
(10434, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 5, 5, 'OT', 'Mích-si, con trai của người; Rê-aia, con trai của người; Ba-al, con trai của người.'),
(10435, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 5, 6, 'OT', 'Bê-ra, con trai người, là kẻ bị Til-gát-pi-ncơ-sơ, vua xứ A-si-ri, bắt đi đày; chính người nầy làm lãnh tụ của chi phái Ru-bên.'),
(10436, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 5, 7, 'OT', 'Các anh em của người theo các gia tộc mình, khi được tính theo gia phả các đời của họ, thì trưởng tộc là Giê-đi-ên và Xa-cha-ri.'),
(10437, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 5, 8, 'OT', 'Và Bê-la, con trai của A-xát, con trai của Sê-ma, con trai của Giô-ên, người ở tại A-rô-er cho đến Nê-bô và Ba-an-Mê-ôn.'),
(10438, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 5, 9, 'OT', 'Về hướng đông, họ ở cho đến nơi vào sa mạc từ sông Eu-phrát; vì súc vật của họ sinh sôi rất nhiều trong đất Ga-la-át.'),
(10439, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 5, 10, 'OT', 'Vào các ngày của Sau-lơ, họ làm chiến với người Ha-ga-ri, và người Ha-ga-ri ngã xuống tay họ; họ sống trong lều của người ấy trên khắp vùng đất phía đông của Gi-lean.'),
(10440, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 5, 11, 'OT', 'Con trai của Gát sống đối diện với họ, tại đất Ba-san cho đến Sa-lê-ca.'),
(10441, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 5, 12, 'OT', 'Joel là người đứng đầu, Shapham là người thứ hai, và Jaanai cùng Shaphat ở Ba-san.'),
(10442, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 5, 13, 'OT', 'Và các anh em của họ, theo các nhà tổ phụ họ, là Mícháchên, Mê-su-lam, Sêva, Giôrai, Giachan, Zia và Êber, tất cả bảy người.'),
(10443, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 5, 14, 'OT', 'Đây là các con trai của A-bi-hai, con trai của Hu-ri, con trai của Gia-rô-ách, con trai của Ghi-lê-át, con trai của Mi-chai-ên, con trai của Giê-si-sai, con trai của Gia-đô, con trai của Bút.'),
(10444, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 5, 15, 'OT', 'A-hi, con trai của Áp-đi-ên, con trai của Gu-ni, là người đứng đầu nhà các tổ phụ của họ.'),
(10445, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 5, 16, 'OT', 'Họ ở tại Ga-la-át, tại Ba-san và các thị trấn thuộc vùng đó, cũng như trong mọi vùng đồng cỏ của Sharon theo các biên giới của họ.'),
(10446, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 5, 17, 'OT', 'Tất cả những người này đều được ghi chép gia phả trong các ngày của Yô-tham, vua Giu-đa, và trong các ngày của Gia-ram, vua Y-sơ-ra-ên.'),
(10447, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 5, 18, 'OT', 'Con trai của Ru-bên, con trai của Ga-đi và phân nửa chi phái Ma-na-xe, gồm những người tráng kiện, là những người cầm khiên và gươm, bắn cung và được luyện tập trong chiến trận, tổng cộng bốn mươi bốn ngàn bảy trăm sáu mươi người ra trận.'),
(10448, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 5, 19, 'OT', 'Họ làm chiến với người Hagrite, với Yetur, và Naphish, và Nodab.'),
(10449, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 5, 20, 'OT', 'Họ được giúp đỡ chống lại chúng, và người Hagria cùng tất cả những kẻ theo chúng bị nộp vào tay họ; vì trong cuộc chiến, họ đã kêu cầu Đức Chúa Trời, và Ngài nhậm lời họ; bởi họ tin cậy nơi Ngài.'),
(10450, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 5, 21, 'OT', 'Họ đã chiếm đoạt súc vật của chúng: lạc đà năm mươi ngàn, chiên hai trăm năm mươi ngàn, lừa hai ngàn, và một trăm ngàn mạng người.'),
(10451, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 5, 22, 'OT', 'Vì có rất nhiều người chết nằm xuống, bởi chiến tranh là từ Đức Chúa Trời. Họ sống trong các nơi của những người ấy cho đến thời bị lưu đày.'),
(10452, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 5, 23, 'OT', 'Con trai của phân nửa chi phái Ma-na-se ở trong xứ, từ Ba-san cho đến Ba-al Hẹc-môn, Xê-nia và núi Hẹc-môn; số người ấy rất đông.'),
(10453, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 5, 24, 'OT', 'Và đây là các tổ trưởng của họ: Ê-phẹ, và Y-si, và Ê-li-ên, và A-xri-ên, và Giê-rê-mi, và Hô-đa-vi-a, và Gia-đi-ên, những người dũng cảm, những người nổi tiếng, các tổ trưởng của họ.'),
(10454, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 5, 25, 'OT', 'Họ phạm tội bất trung cùng Đức Chúa Trời của tổ tiên mình, và đi theo các thần của dân xứ, mà Đức Chúa Trời đã tiêu diệt khỏi trước mặt họ.'),
(10455, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 5, 26, 'OT', 'Đức Chúa Trời của Ít-ra-en khiến thần của Phu-lơ, vua A-sy-ri, và thần của Til-lách-pích-nê-xe, vua A-sy-ri, nổi lên, rồi người ấy bắt những người thuộc chi phái Ru-bên, và Ga-đi, và phân nửa chi phái Ma-na-xe phải đi đày, và đem họ đến Ha-la, và Ha-bô, và Ha-ra, và sông Gô-zan, cho đến ngày nay.'),
(10456, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 1, 'OT', 'Các con trai của Lêvi: Ghẹt-sôn, Kê-hát và Mê-ra-ri.'),
(10457, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 2, 'OT', 'Và các con trai của Kê-hát là Am-ram, Y-xách, Hếp-rôn và Út-xi-ên.'),
(10458, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 3, 'OT', 'Con cái của Am-ram là A-ha-ron, Môi-se và Mi-ri-am. Con cái của A-ha-ron là Na-đáp, A-bi-hu, Ê-lê-a-xa và I-tha-ma.'),
(10459, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 4, 'OT', 'Ê-lê-a-xa sinh Phi-nê-xa, Phi-nê-xa sinh A-bi-xu.'),
(10460, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 5, 'OT', 'Abi-sú-cha sinh Búc-ki, và Búc-ki sinh Út-xi.'),
(10461, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 6, 'OT', 'Và U-xi sinh ra Xa-cha-ia, và Xa-cha-ia sinh ra Mê-ra-i-ốt.'),
(10462, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 7, 'OT', 'Mê-ra-i-ốt sinh ra A-ma-ri-a, và A-ma-ri-a sinh ra A-hi-túp.'),
(10463, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 8, 'OT', 'Và A-hi-túp sinh ra Xa-đốc, và Xa-đốc sinh ra A-hi-ma-ách.'),
(10464, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 9, 'OT', 'A-hi-ma-át sinh ra A-xa-ria, và A-xa-ria sinh ra Giô-ha-nan.'),
(10465, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 10, 'OT', 'Và Giô-ha-nan sinh ra A-xa-ria, người đã làm thầy tế lễ trong đền thờ mà Sa-lô-môn đã xây tại Giê-ru-sa-lem.'),
(10466, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 11, 'OT', 'Azaryah sinh Amaryah, và Amaryah sinh Ahitub.'),
(10467, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 12, 'OT', 'A-hi-tu-bê sinh ra Xa-đốc, và Xa-đốc sinh ra Sa-lum.'),
(10468, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 13, 'OT', 'Và Sa-lum sinh ra Hil-ki-a, và Hil-ki-a sinh ra A-xa-ria.'),
(10469, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 14, 'OT', 'A-xa-ria sinh ra Xê-rai-a, và Xê-rai-a sinh ra Giê-hô-xa-đác.'),
(10470, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 15, 'OT', 'Và Giê-hô-xa-đác đi đi đày khi Đức Giê-hô-va đem Giu-đa và Giê-ru-sa-lem đi đày bởi tay Nê-bu-cát-nết-xa.'),
(10471, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 16, 'OT', 'Con trai của Lêvi: Ghẹt-sô-nơ, Kê-hát và Mê-ra-ri.'),
(10472, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 17, 'OT', 'Và đây là những tên các con trai của Ghẹt-sôm: Lib-ni và Si-mi.'),
(10473, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 18, 'OT', 'Các con trai của Kehat là Am-ram, Yitxhar, Hẹbron và Uzziel.'),
(10474, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 19, 'OT', 'Con cái của Mê-ra-ri: Ma-hê-li và Mu-si. Đây là các chi họ của người Lê-vi theo các tổ phụ của họ.'),
(10475, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 20, 'OT', 'Gẹr-sôm sinh ra Lib-ni, Lib-ni sinh ra Gia-hát, Gia-hát sinh ra Xim-ma.'),
(10476, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 21, 'OT', 'Giô-ách, con trai của người; Ít-đô, con trai của người; Xe-ra, con trai của người; Giê-a-tê-rai, con trai của người.'),
(10477, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 22, 'OT', 'Con trai của Kê-hát: Amminadab là con trai người, Korah là con trai người, A-si là con trai người.'),
(10478, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 23, 'OT', 'Ê-lê-ka-nah sinh ra Ê-bi-a-sáp, Ê-bi-a-sáp sinh ra A-xia.'),
(10479, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 24, 'OT', 'Tahath là con trai ông ấy, Uriel là con trai Tahath, U-xi-a là con trai Uriel, và Shaul là con trai U-xi-a.'),
(10480, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 25, 'OT', 'Các con trai của Ên-ka-na là A-ma-xai và A-hi-mốt.'),
(10481, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 26, 'OT', 'Ên-ca-nam; các con trai của Ên-ca-nam: Xô-phai là con trai ông, và Na-hát là con trai ông.'),
(10482, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 27, 'OT', 'Ê-li-áp, con trai của người; Giơ-rô-ham, con trai của người; Ên-ca-nah, con trai của người.'),
(10483, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 28, 'OT', 'Các con trai của Sa-mu-ên là con cả Vashni và con thứ hai Abiah.'),
(10484, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 29, 'OT', 'Các con trai của Mê-ra-ri: Ma-hli, Lib-ni con trai người, Sim-mê-i con trai người, Út-xa con trai người.'),
(10485, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 30, 'OT', 'Si-mê-i con trai ông ấy, Haggia con trai ông ấy, Asaia con trai ông ấy.'),
(10486, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 31, 'OT', 'Và đây là những người Đa-vít đặt lên lo việc hát xướng trong nhà của Đức Giê-hô-va, từ khi hòm giao ước được đặt yên nghỉ.'),
(10487, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 32, 'OT', 'Họ phục vụ trước nơi ở của hội mạc, tức là lều gặp gỡ, bằng các bài ca cho đến khi Sa-lô-môn xây xong đền thờ Đức Giê-hô-va tại Giê-ru-sa-lem; và họ đứng giữ chức vụ mình theo đúng quy định của họ.'),
(10488, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 33, 'OT', 'Và đây là những người phục vụ cùng con cái họ, thuộc con cháu của Kê-hát: Hê-man, người lãnh xướng hát, con trai của Giô-ên, con trai của Sê-mu-ên.'),
(10489, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 34, 'OT', 'Con trai của Ên-ca-na, con trai của Giê-hô-ram, con trai của Ê-li-ên, con trai của Thoa.'),
(10490, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 35, 'OT', 'Con trai của Xíp, con trai của Ên-ka-na, con trai của Ma-hát, con trai của A-ma-xai.'),
(10491, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 36, 'OT', 'Con trai của Ên-ca-na, con trai của Giô-ên, con trai của A-xa-ria, con trai của Xô-phan-nia.'),
(10492, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 37, 'OT', 'Con trai của Tha-hát, con trai của A-xíp, con trai của Ê-bi-a-xáp, con trai của Kô-rách,'),
(10493, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 38, 'OT', 'Con trai của Ích-ha, con trai của Kô-hát, con trai của Lê-vi, con trai của Ích-ra-en.'),
(10494, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 39, 'OT', 'Và anh của người là A-sáp, đứng bên phải người, A-sáp con trai của Bê-rác-ki-a, con trai của Si-mê-a.'),
(10495, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 40, 'OT', 'Con trai của Mi-cha-ên, con trai của Ba-a-xe-ia, con trai của Man-ki-a.'),
(10496, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 41, 'OT', 'Con trai của Ê-thni, con trai của Xe-ra, con trai của A-đai-a.'),
(10497, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 42, 'OT', 'Con trai của Ê-than, con trai của Xim-ma, con trai của Sê-mai.'),
(10498, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 43, 'OT', 'Con của Xa-thát, con của Ghẹt-sôm, con của Lê-vi.'),
(10499, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 44, 'OT', 'Các anh em của họ, con cháu Mê-ra-ri, thì đứng bên trái: Ê-than, con trai của Kích-i, con trai của Áp-di, con trai của Ma-lúc.'),
(10500, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 45, 'OT', 'con trai của Ha-sa-bia, con trai của A-ma-xia, con trai của Hil-ki-a,'),
(10501, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 46, 'OT', 'Con trai của Am-xi, con trai của Ba-ni, con trai của Sa-me.'),
(10502, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 47, 'OT', 'Con trai của Mạt-hli, con trai của Mu-si, con trai của Mê-ra-ri, con trai của Lê-vi.'),
(10503, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 48, 'OT', 'Anh em họ là những người Lê-vi được giao cho mọi công việc phục vụ nơi hội mạc của nhà Đức Chúa Trời.'),
(10504, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 49, 'OT', 'Và A-ha-ron cùng các con trai người dâng hương trên bàn thờ của lễ thiêu và trên bàn thờ hương, lo mọi công việc về nơi Thánh của các thánh, và thực hiện sự chuộc tội cho Y-sơ-ra-ên, theo mọi điều mà Môi-se, tôi tớ Đức Chúa Trời, đã truyền dạy.'),
(10505, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 50, 'OT', 'Và đây là các con trai của A-rôn: Ê-lê-a-xa, con trai người; Phi-nê-xa, con trai người; A-bi-xhua, con trai người.'),
(10506, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 51, 'OT', 'Bùkki, con trai của người; Út-si, con trai của người; Xa-rai-a, con trai của người.'),
(10507, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 52, 'OT', 'Mê-ra-i-ốt là con trai người, A-ma-ri-a là con trai Mê-ra-i-ốt, A-hi-túp là con trai A-ma-ri-a.'),
(10508, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 53, 'OT', 'Xa-đốc, con trai của người; A-hi-ma-ách, con trai của Xa-đốc.'),
(10509, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 54, 'OT', 'Còn đây là nơi ở của họ theo các thành trì của họ trong lãnh thổ họ, thuộc về các con trai của A-ha-ron, theo các họ hàng của người Kê-hát; vì phần đất được bắt thăm thuộc về họ.'),
(10510, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 55, 'OT', 'Họ đã trao cho họ Hếp-rôn trong đất Giu-đa, và các vùng đất phụ cận xung quanh nó.'),
(10511, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 56, 'OT', 'Nhưng đồng ruộng của thành và các xóm làng của nó, họ đã trao cho Ca-lép, con trai của Y-phu-nê.'),
(10512, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 57, 'OT', 'Về các con trai của A-ha-ron, người ta trao cho các thành trú ẩn, là Hếp-rôn, và Li-bơ-na cùng các vùng đất đệm chung quanh, và Gia-tia, và Ét-thơ-mô-a cùng các vùng đất đệm chung quanh.'),
(10513, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 58, 'OT', 'Và Hilen cùng với các vùng phụ cận của nó, Đê-bia cùng với các vùng phụ cận của nó.'),
(10514, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 59, 'OT', 'Và A-sán cùng các vùng phụ cận của thành, và Bết Sê-mết cùng các vùng phụ cận của thành.'),
(10515, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 60, 'OT', 'Và từ chi phái Bên-gia-min: Gê-ba cùng các vùng đất ngoại vi, A-lê-mết cùng các vùng đất ngoại vi, và A-na-thốt cùng các vùng đất ngoại vi. Tất cả các thành của họ theo các gia tộc là mười ba thành.'),
(10516, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 61, 'OT', 'Còn về các con trai của Kê-hát, là những người còn sót lại trong các họ hàng của chi phái đó, thì được trao mười thành phố bằng sự bắt thăm, từ nửa chi phái Ma-na-xe.'),
(10517, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 62, 'OT', 'Còn về các con trai của Ghẹt-sôn, theo các họ hàng của họ, thì từ chi phái Y-xa-cha, từ chi phái A-xe, từ chi phái Náp-ta-li, và từ chi phái Ma-na-xe ở Ba-san, được trao ban mười ba thành.'),
(10518, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 63, 'OT', 'Cho con cháu của Mê-ra-ri, theo các họ hàng của họ, được bắt thăm chia đất, từ chi phái Ru-bên, từ chi phái Ga-đi và từ chi phái Xê-bu-lôn, gồm mười hai thành.'),
(10519, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 64, 'OT', 'Con cái Y-sơ-ra-ên đã trao cho những người Lê-vi các thành phố cùng với các vùng đất hoang nằm chung quanh.'),
(10520, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 65, 'OT', 'Họ trao bằng sự bắt thăm từ chi phái con cái Giu-đa, và từ chi phái con cái Si-mê-ôn, và từ chi phái con cái Bên-gia-min, những thành nầy, mà người ta gọi tên của chúng.'),
(10521, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 66, 'OT', 'Các gia đình con cháu Kê-hát được các thành phố thuộc vùng đất của họ từ chi phái Ép-ra-im.'),
(10522, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 67, 'OT', 'Họ đã trao cho họ các thành trú ẩn, là Sêm và các vùng đất phụ cận ở trên núi Ép-ra-im, và Ghê-xe và các vùng đất phụ cận.'),
(10523, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 68, 'OT', 'và Yạc-mê-am cùng các vùng ngoại vi quanh nó, và Bết Hô-rôn cùng các vùng ngoại vi quanh nó,'),
(10524, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 69, 'OT', 'Và A-ya-lôn cùng các vùng đất phụ cận, và Gat Rim-môn cùng các vùng đất phụ cận của thành ấy.'),
(10525, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 70, 'OT', 'Và từ phân nửa chi phái Ma-na-se: A-ne với các vùng đất quanh nó, và Bích-lê-am với các vùng đất quanh nó, dành cho gia đình của những người con trai Kô-hát còn sót lại.'),
(10526, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 71, 'OT', 'Cho các con trai của Ghẹc-sôm, từ họ hàng của phân nửa chi phái Ma-na-se, [được ban] thành Gô-lan trong Ba-san và các vùng phụ cận, cùng với A-sơ-ta-rot và các vùng phụ cận.'),
(10527, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 72, 'OT', 'Và từ chi phái Y-xa-sác, Kê-đết cùng các vùng phụ cận, Đa-be-rát cùng các vùng phụ cận.'),
(10528, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 73, 'OT', 'Và Ra-mốt cùng với các vùng đất chung quanh nó, và A-nem cùng với các vùng đất chung quanh nó.'),
(10529, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 74, 'OT', 'Và từ chi phái A-xơ: Mát-sanh với các vùng phụ cận quanh nó, và Áp-đôn với các vùng phụ cận quanh nó.'),
(10530, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 75, 'OT', 'và Húcốc cùng các vùng đất ngoại vi của thành, và Rêhốp cùng các vùng đất ngoại vi của thành.'),
(10531, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 76, 'OT', 'Về chi phái Na-phtha-li, có Kê-đe-s thuộc Ga-li-lê cùng các vùng phụ cận, và Ha-môn cùng các vùng phụ cận, và Kích-tha-tai-mai cùng các vùng phụ cận.'),
(10532, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 77, 'OT', 'Còn về những con trai Mê-ra-ri còn sót lại, thì từ chi phái Xê-bu-lôn, cho chúng Rim-môn cùng vùng đất ngoại ô quanh nó, và Ta-bô cùng vùng đất ngoại ô quanh nó.'),
(10533, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 78, 'OT', 'Về phía bên kia sông Giô-đanh, gần Giê-ri-cô, ở phía đông sông Giô-đanh, từ chi phái Ru-bên, gồm Bết-xe trong đồng vắng cùng các vùng phụ cận, và Giát-xa cùng các vùng phụ cận.'),
(10534, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 79, 'OT', 'và Kê-đê-mốt cùng với các vùng phụ cận, và Mê-pa-át cùng với các vùng phụ cận,'),
(10535, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 80, 'OT', 'Và từ chi phái Gad, [được chỉ định] Ra-mốt trong đất Ga-la-át cùng các vùng phụ cận, và Ma-ha-na-im cùng các vùng phụ cận.'),
(10536, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 6, 81, 'OT', 'và Hết-bôn cùng các vùng phụ cận, và Gia-xe cùng các vùng phụ cận.'),
(10537, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 1, 'OT', 'Con trai của Y-sa-xa gồm có Tô-la, Pu-a, Gia-sub và Si-môn, tất cả bốn người.'),
(10538, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 2, 'OT', 'Con trai của Tô-la là Út-xi, Rê-pha-i-a, Giê-ri-ên, Gia-mai, Giíp-sam và Sê-mu-ên. Họ là các trưởng tộc theo nhà tổ phụ của mình, thuộc dòng Tô-la; những người dũng cảm, hùng mạnh trong các thế hệ của họ. Số người của họ vào đời Đa-vít là hai mươi hai ngàn sáu trăm người.'),
(10539, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 3, 'OT', 'Con cái của Uzzi là Izrahiah; con cái của Izrahiah là Mi-ca-ên, Obadyah, Joel, Ishiah, tất cả năm người đều là các lãnh tụ.'),
(10540, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 4, 'OT', 'Và cùng họ, theo các thế hệ của họ, theo nhà các tổ phụ họ, có các toán quân chiến đấu, ba mươi sáu ngàn người; vì họ có nhiều vợ và con trai.'),
(10541, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 5, 'OT', 'Và anh em họ thuộc về mọi gia đình của Y-sa-sác đều là những người dũng cảm, mạnh mẽ, tổng cộng tám mươi bảy ngàn người, được ghi chép đầy đủ theo gia phả của họ.'),
(10542, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 6, 'OT', 'Bên-gia-min: Bê-la, Bê-cher và Giê-đi-ên, ba người.'),
(10543, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 7, 'OT', 'Các con trai của Bê-la là Ê-xbôn, U-xi, U-xi-ên, Giê-ri-mốt và I-ri, tất cả năm người; họ là các tổ trưởng, những chiến sĩ dũng cảm. Số người trong các gia phả của họ là hai mươi hai ngàn ba mươi bốn người.'),
(10544, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 8, 'OT', 'Các con trai của Bê-cher là Xê-mi-ra, và Giô-ách, và Ê-li-ê-xe, và Ê-li-ô-ênai, và Ôm-ri, và Giê-ri-mốt, và A-bi-a, và A-na-thốt, và A-la-mết. Tất cả những người này là con trai của Bê-cher.'),
(10545, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 9, 'OT', 'Và số người trong các gia phả của họ, theo các thế hệ, là các trưởng tộc, những người tráng kiện dũng cảm, gồm hai mươi ngàn và hai trăm người.'),
(10546, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 10, 'OT', 'Con trai của Giê-đi-ên là Binh-an; con trai của Binh-an là Giếu, và Bên-gia-min, và Ê-hút, và Kê-na-anh, và Xết-than, và Tạt-si-s, và A-hi-sa-sa.'),
(10547, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 11, 'OT', 'Tất cả những người này là con trai của Giê-đi-ên, theo các tổ phụ của họ, là những người tráng kiện, dũng cảm, tổng cộng mười bảy ngàn hai trăm người, sẵn sàng ra trận để chiến đấu.'),
(10548, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 12, 'OT', 'Súp-im và Húp-im, con trai của Ích; Hút-im, con trai của A-hẹc.'),
(10549, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 13, 'OT', 'Con trai của Na-phtha-li: Gia-xi-ên, Gu-ni, và Giê-xe, và Sát-lum, con trai của Binh-ha.'),
(10550, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 14, 'OT', 'Các con trai của Ma-na-se là A-sri-ên, người mà vợ thứ của người, là người đàn bà A-ram, đã sinh ra; bà ấy sinh ra Mác-hiếc, cha của Ghi-lê-át.'),
(10551, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 15, 'OT', 'Mác-sích lấy vợ là chị em của Húp-pim và Súp-pim; tên chị em ấy là Ma-a-ca; còn tên người thứ hai là Xê-lô-phê-hát; và Xê-lô-phê-hát có các con gái.'),
(10552, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 16, 'OT', 'Ma-ách, vợ của Ma-khích, sinh một con trai, và bà đặt tên nó là Phê-rết; tên người anh em nó là Sa-rết; và các con trai nó là Út-lam và Ra-kết.'),
(10553, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 17, 'OT', 'Và các con trai của Ú-lam là Bê-đan. Đây là các con trai của Ghi-lê-át, con trai của Ma-khia, con trai của Ma-na-xe.'),
(10554, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 18, 'OT', 'Và người chị em gái của ông, Hammô-lê-kết, đã sinh ra Y-sốt, A-bi-ê-xe và Ma-khê-la.'),
(10555, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 19, 'OT', 'Con trai của Sê-mi-đa là A-hi-an, Sêm, Li-khi và A-ni-am.'),
(10556, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 20, 'OT', 'Con trai của Ép-ra-im là Su-tha-lách, Bê-red con trai người, và Ta-hát con trai người, và Ê-la-đa con trai người, và Ta-hát con trai người.'),
(10557, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 21, 'OT', 'Và Xa-bát là con trai người, và Sút-hê-la là con trai người; còn Ê-xe và Ê-lê-át, thì bị những người Ga-thên sinh tại đất ấy giết chết, vì chúng nó đã xuống để cướp bò chiên của những người ấy.'),
(10558, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 22, 'OT', 'Ê-phra-im, cha của họ, khóc than nhiều ngày; và các anh em của người đến an ủi người.'),
(10559, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 23, 'OT', 'Người vào cùng vợ mình, thì vợ thụ thai và sinh một con trai; người đặt tên con là Bê-ri-ia, vì tai họa xảy đến với nhà người.'),
(10560, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 24, 'OT', 'Cô ấy là Sê-ra; chính cô đã xây dựng Bết Hô-rôn dưới và Bết Hô-rôn trên, cùng với Út-xen Sê-ra.'),
(10561, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 25, 'OT', 'Và Rê-pha là con trai người, Rê-shep và Tê-la là con trai người, và Ta-han là con trai người.'),
(10562, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 26, 'OT', 'La-đan là con trai ông; Am-mi-hút là con trai ông; Ê-li-sa-ma là con trai ông.'),
(10563, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 27, 'OT', 'Non sinh ra Giô-suê.'),
(10564, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 28, 'OT', 'Và đất đai cùng nơi ở của họ gồm có Bê-tên và các làng mạc chung quanh; về phía đông là Na-a-ran, về phía tây là Gẹt-xe và các làng mạc chung quanh, Si-chem và các làng mạc chung quanh, cho đến A-đai và các làng mạc chung quanh.'),
(10565, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 29, 'OT', 'Và theo các vùng biên giới của con cái Ma-na-se, có Bết-si-an và các thành thị của nó, Ta-nách và các thành thị của nó, Mê-gít-đô và các thành thị của nó, Đô và các thành thị của nó. Chính những nơi này là nơi cư ngụ của con cái Giô-sép, con trai Ít-ra-en.'),
(10566, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 30, 'OT', 'Các con trai của A-xe: Yim-na, Yish-va, Yish-vi, Bê-ri-ê-ca và Sê-rách, em gái các người ấy.'),
(10567, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 31, 'OT', 'Và các con trai của Bê-ri-ia là Hê-bec và Ma-lác-xi-ên, người là cha của Bích-xa-vít.'),
(10568, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 32, 'OT', 'Hê-phẹr sinh ra Yap-hết, và Sô-mêr, và Hô-tham, và Su-a là em gái các người ấy.'),
(10569, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 33, 'OT', 'Các con trai của Yap-hơ-lết là Pa-sách, Bi-mha-ên và A-sơ-vát. Đây là các con trai của Yap-hơ-lết.'),
(10570, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 34, 'OT', 'Các con trai của Shamer là Ahi, Rohgah, Jehubbah và A-ram.'),
(10571, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 35, 'OT', 'Và các con trai của anh em người là Hê-lêm: Xô-pha, và Yim-na, và Sê-lêch, và A-mal.'),
(10572, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 36, 'OT', 'Các con trai của Xô-pha là Su-ách, và Ha-né-phơ, và Sú-an, và Bê-ri, và I-mơ-ra.'),
(10573, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 37, 'OT', 'Bết-xe, và Hốt, và Sam-ma, và Síp-sa, và Y-than, và Bê-e-ra.'),
(10574, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 38, 'OT', 'Các con trai của Y-ther là Giê-phun-nê, Phi-xpa và A-ra.'),
(10575, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 39, 'OT', 'Các con trai của U-la là A-ra, Ha-ni-ên và Ri-xi-a.'),
(10576, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 7, 40, 'OT', 'Tất cả những người này là con trai của A-se, các trưởng tộc, những người được chọn lựa, là những dũng sĩ, các đầu lĩnh của các quan trưởng; và họ được ghi vào sổ gia phả để phục vụ trong đạo quân ra trận, số người theo gia phả là hai mươi sáu ngàn người.'),
(10577, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 1, 'OT', 'Bản thân Bên-gia-min sinh ra Bê-la, con đầu lòng của người; A-sép-ên là người thứ hai, và A-ha-ra là người thứ ba.'),
(10578, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 2, 'OT', 'Nô-ê người thứ tư, và Râ-pha người thứ năm.'),
(10579, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 3, 'OT', 'Những người con trai của Ba-la là: A-đa, và Ghê-ra, và A-bi-hút.'),
(10580, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 4, 'OT', 'Và A-bi-xu, và Na-a-man, và A-ho-ách.'),
(10581, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 5, 'OT', 'Và Gê-ra, và Sê-phu-phan, và Hu-ram.'),
(10582, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 6, 'OT', 'Và đây là các con trai của Ê-hút; chính họ là các tổ trưởng của những người ở Gê-ba; và người ta đã dời họ đến Ma-na-hát.'),
(10583, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 7, 'OT', 'Na-a-man, A-hi-a và Gê-ra; chính người đã dời họ đi, và sinh ra Út-za và A-hi-hút.'),
(10584, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 8, 'OT', 'Sau khi Shaharaim đuổi các vợ về đất Mô-áp, ông sinh được Hushim và Baara.'),
(10585, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 9, 'OT', 'Người sinh ra từ Hô-đết, vợ mình, Giô-báp, Xi-bi-a, Mê-sa và Ma-lê-kham.'),
(10586, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 10, 'OT', 'Và Giêu-xơ, và Sác-hi-a, và Mia-ma. Những người nầy là các con trai của người, các tổ trưởng.'),
(10587, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 11, 'OT', 'Và từ Hushim sinh ra Abitub và Elpaal.'),
(10588, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 12, 'OT', 'Các con trai của Ê-lê-pha-an: Ê-bẹ, Mít-sâm và Sâm-ết; chính người ấy xây dựng thành Ô-nô và Lốt cùng các thị trấn thuộc về hai thành ấy.'),
(10589, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 13, 'OT', 'Và Bê-ri-a và Sê-ma, họ là các tổ trưởng của những người ở Ai-lôn; chính họ đã đuổi những người ở Gát đi.'),
(10590, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 14, 'OT', 'Và A-hi-ô, Shashak và Giê-rê-mốt.'),
(10591, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 15, 'OT', 'Và Xê-ba-đia, và A-rát, và A-đe-rơ.'),
(10592, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 16, 'OT', 'Míchách, Íp-pha và Giô-ha, các con trai của Bê-ri-ách.'),
(10593, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 17, 'OT', 'Và Xê-ba-đia, và Mê-xu-lam, và Hít-ki, và Hê-ber,'),
(10594, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 18, 'OT', 'Và Yishmerai, và Yizlia, và Yovav, những người con trai của Elpaal;'),
(10595, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 19, 'OT', 'Và Ya-kim, và Xích-ri, và Xáp-đi,'),
(10596, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 20, 'OT', 'Và Ê-li-ên-nai, và Xi-let-hai, và Ê-li-ên,'),
(10597, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 21, 'OT', 'Và A-đai-a, Bê-ra-i-a và Si-mơ-rát, những người con trai của Si-mi.'),
(10598, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 22, 'OT', 'Và Ích-phan, và Ép-va, và Ê-li-ên.'),
(10599, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 23, 'OT', 'Và Ab-đôn, và Xích-ri, và Ha-nan.'),
(10600, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 24, 'OT', 'Và Hanania, và Ê-lam, và An-tốt-ji-a.'),
(10601, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 25, 'OT', 'Và Y-phê-đi-a và Phên-ù-ên, các con trai của Sa-sác.'),
(10602, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 26, 'OT', 'Và Shamsherai, Shehariah và A-ta-li-a,'),
(10603, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 27, 'OT', 'Và Ya-a-rết-xi-a, và Ê-li-a, và Xích-ri, các con trai của Giê-rô-ham.'),
(10604, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 28, 'OT', 'Đây là các tổ trưởng theo các dòng dõi của họ, những người làm đầu. Những người này ở tại Giê-ru-sa-lem.'),
(10605, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 29, 'OT', 'Tại Ghi-bê-ôn, người cha của Ghi-bê-ôn đã sống ở đó; tên vợ ông là Ma-ka.'),
(10606, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 30, 'OT', 'Và con trai cả của người là Áp-đôn, và Zư, và Kích, và Ba-anh, và Na-đáp.'),
(10607, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 31, 'OT', 'Và Ghê-đô, và A-hi-ô, và Xa-khẹ.'),
(10608, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 32, 'OT', 'Mik-lốt sinh ra Sê-mê-a; và chính họ cũng ở tại Giê-ru-sa-lem cùng với anh em mình, đối diện với anh em mình.'),
(10609, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 33, 'OT', 'Và Nêr sinh ra Kích; và Kích sinh ra Sau-lơ; và Sau-lơ sinh ra Giô-na-than, và Ma-lích-xu-a, và A-bi-na-đáp, và Ê-sê-ba-ên.'),
(10610, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 34, 'OT', 'Con trai của Giô-na-than là Mê-ri-ba-an; và Mê-ri-ba-an sinh ra Mích-gia.'),
(10611, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 35, 'OT', 'Các con trai của Mích-gia là Pít-hôn, và Mê-léc, và Ta-a-rê, và A-hách.'),
(10612, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 36, 'OT', 'A-hách sinh ra Giê-hô-a-đa; Giê-hô-a-đa sinh ra A-lê-mết, A-xơ-ma-vết và Xim-ri; Xim-ri sinh ra Mô-xa.'),
(10613, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 37, 'OT', 'Moza sinh Binea; Râ-pha là con trai người, Eleasah là con trai người, Azel là con trai người.'),
(10614, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 38, 'OT', 'Và A-xen có sáu người con trai, và đây là tên các con trai ấy: A-xơ-ri-cam, Bô-chê-ru, Ích-ma-ên, Sê-a-ri-a, Ô-ba-đia, và Ha-nan. Tất cả những người này là con trai của A-xen.'),
(10615, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 39, 'OT', 'Và các con trai của Échek, anh của người, là Ú-lam, con đầu lòng; Giê-u, con thứ hai; và Ê-li-phê-lét, con thứ ba.'),
(10616, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 8, 40, 'OT', 'Các con trai của U-lam là những người tráng kiện, thiện xạ, và có rất nhiều con trai cùng cháu trai, tổng cộng một trăm năm mươi người. Tất cả những người này đều thuộc dòng dõi của Bên-gia-min.'),
(10617, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 1, 'OT', 'Toàn thể Y-sơ-ra-ên đều được ghi gia phổ, và nầy, họ được chép trong sách các vua Y-sơ-ra-ên và Giu-đa; Giu-đa bị đày sang Ba-by-lôn vì tội lỗi mình.'),
(10618, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 2, 'OT', 'Còn những người đầu tiên ở trong các thành thuộc về phần đất của họ là người Y-sơ-ra-ên, các thầy tế lễ, người Lê-vi và những người Nê-ti-nim.'),
(10619, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 3, 'OT', 'Tại Giê-ru-sa-lem, có những người thuộc con cháu Giu-đa, con cháu Bên-gia-min, con cháu Ép-ra-im và con cháu Ma-na-xe sống ở đó.'),
(10620, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 4, 'OT', 'Utai, con trai của Ammi-hu-đ, con trai của Ôm-ri, con trai của Im-ri, con trai của Ba-ni, thuộc dòng dõi Pha-rết, con trai của Giu-đa.'),
(10621, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 5, 'OT', 'Và từ người Si-lô-nít, A-xa-ia người con cả, và các con trai của ông.'),
(10622, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 6, 'OT', 'Và trong các con trai của Xe-ra; Giêu-ên và các anh em họ, sáu trăm chín mươi người.'),
(10623, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 7, 'OT', 'Và trong các con trai của Bên-gia-min: Xan-lu, con trai của Mết-xu-lam, con trai của Hô-đa-vi-a, con trai của Ha-xe-nu-a.'),
(10624, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 8, 'OT', 'Và Y-íp-nê-ya, con trai của Giê-rô-ham; Ê-la, con trai của Út-xi, con trai của Mích-ri; và Mê-thu-lam, con trai của Sê-phát-đi-a, con trai của Rê-u-ên, con trai của Íp-ni-gia.'),
(10625, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 9, 'OT', 'Và các anh em họ, theo các gia phổ của họ, là chín trăm năm mươi sáu người. Tất cả những người đàn ông này đều là các tổ trưởng trong các nhà họ của tổ tiên họ.'),
(10626, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 10, 'OT', 'Về các thầy tế lễ: Jê-đa-i-a, Giê-hô-i-a-ríp và Gia-kin.'),
(10627, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 11, 'OT', 'Và A-xa-ria, con trai của Hi-lê-kia, con trai của Mê-xu-lam, con trai của Xa-đốc, con trai của Mê-ra-i-ốt, con trai của A-hi-túp, người cai quản nhà của Đức Chúa Trời;'),
(10628, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 12, 'OT', 'Và A-đai-a, con trai của Xê-rô-ham, con trai của Pha-súp, con trai của Mác-ki-gia; và Ma-a-xai, con trai của A-đi-ên, con trai của Gia-xe-ra, con trai của Mết-xu-lam, con trai của Mết-xi-lê-mít, con trai của Ít-ma.'),
(10629, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 13, 'OT', 'Và các anh em họ, những người đứng đầu các gia tộc tổ tiên mình, gồm một ngàn bảy trăm sáu mươi người, đều là những người mạnh mẽ, đầy năng lực để làm công việc phục vụ trong đền thờ Đức Chúa Trời.'),
(10630, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 14, 'OT', 'Và trong vòng những người Lê-vi: Sê-ma-gia, con trai của Ha-xúp, con trai của A-xri-cam, con trai của Ha-xa-bi-a, thuộc các con trai của Mê-ra-ri.'),
(10631, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 15, 'OT', 'Và Ba-kbak-kar, Hê-rết, và Ga-lát, và Ma-ta-nia, con trai của Mi-ca, con trai của Xích-ri, con trai của A-sáp.'),
(10632, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 16, 'OT', 'Và Ô-ba-đi-a, con trai của Sê-ma-ia, con trai của Ga-lal, con trai của Giê-đu-thun; và Bê-réc-ki-a, con trai của A-sa, con trai của Ên-ca-nam, người ở tại các làng mạc của người Nê-tô-phah-thi.'),
(10633, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 17, 'OT', 'Các người giữ cửa là Sa-lum, Akkub, Talmon, A-hi-man và các anh em họ; Sa-lum làm người đứng đầu.'),
(10634, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 18, 'OT', 'Cho đến nay, họ vẫn ở nơi cửa vua về hướng đông; họ là những người giữ cửa trong các ban của các con trai Lê-vi.'),
(10635, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 19, 'OT', 'Và Sa-lum, con trai của Cô-rê, con trai của Ê-bi-a-sáp, con trai của Cô-rách, và các anh em người, thuộc nhà tộc tổ tiên người, là những người Cô-rách, được giao quản nhiệm việc phục vụ, giữ các cửa lều; còn tổ tiên người thì giữ cửa vào doanh trại của Đức Giê-hô-va.'),
(10636, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 20, 'OT', 'Phi-nê-xết, con trai của Ê-lê-a-xa, từng làm người lãnh đạo họ; Đức Giê-hô-va ở cùng người.'),
(10637, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 21, 'OT', 'Xa-cha-ri là con trai của Mê-sê-lê-mia, người giữ cửa đền tạm hội ngộ.'),
(10638, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 22, 'OT', 'Tất cả những người này được chỉ định làm kẻ giữ cửa tại các cổng, gồm hai trăm mười hai người. Họ được ghi chép gia phả tại các làng mạc mình; Đa-vít và Sa-mu-ên, người thấy, đã thiết lập họ trong chức vụ theo sự trung tín của họ.'),
(10639, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 23, 'OT', 'Họ và các con trai của họ giữ các cửa của nhà Đức Giê-hô-va, tức là nhà của hội mạc, theo các ca trực.'),
(10640, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 24, 'OT', 'Bốn phía đông, tây, bắc và nam đều có người canh giữ.'),
(10641, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 25, 'OT', 'Và các anh em họ ở các làng quê mình sẽ đến luân phiên hằng tuần với họ.'),
(10642, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 26, 'OT', 'Vì những người Lê-vi này, bốn người trưởng nhóm giữ cửa, được đặt trọn tin cậy trong chức vụ của họ, và coi sóc các phòng và các kho tàng trong nhà Đức Chúa Trời.'),
(10643, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 27, 'OT', 'Họ ở quanh nhà Đức Chúa Trời, vì bổn phận canh giữ đặt trên họ, và họ phải mở cửa mỗi buổi sáng.'),
(10644, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 28, 'OT', 'Và trong số họ có người quản nhiệm các đồ dùng phụng sự, phải mang chúng vào và mang ra theo số lượng đã định.'),
(10645, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 29, 'OT', 'Một số người trong số họ được chỉ định quản lý các đồ dùng, và mọi vật dụng thánh, cùng với bột mịn, rượu, dầu, nhũ hương và các loại hương liệu.'),
(10646, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 30, 'OT', 'Về con cái của các thầy tế lễ, có những người chuyên chế dầu thơm.'),
(10647, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 31, 'OT', 'Và Ma-tít-thi-a, thuộc về người Lê-vi, là con đầu lòng của Sa-lum người Cô-ra, được giao nhiệm vụ trung tín coi sóc công việc về các thức ăn nướng trong chảo.'),
(10648, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 32, 'OT', 'Và trong các anh em của người Kê-hát, có những người trong vòng con cháu người Kê-hát được chỉ định quản lý bánh trần thiết, để sửa soạn mỗi ngày Sa-bát.'),
(10649, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 33, 'OT', 'Và đây là những người ca hát, các tổ trưởng trong các gia đình người Lê-vi, sống trong các phòng riêng và được miễn các công việc khác, vì họ được giao nhiệm vụ phục vụ không ngừng ngày và đêm.'),
(10650, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 34, 'OT', 'Đây là các tổ trưởng của người Lêvi theo các dòng dõi của họ; các tổ trưởng này đã ở tại Giê-ru-sa-lem.'),
(10651, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 35, 'OT', 'Và tại Gi-bê-on, người cha của Gi-bê-on là Giê-hi-ên đã cư trú; tên vợ ông là Ma-a-ca.'),
(10652, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 36, 'OT', 'Và con trai đầu lòng của người là Áp-đôn, rồi đến Zur, Kích, Ba-anh, Ner và Na-đáp.'),
(10653, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 37, 'OT', 'Và Ghê-đô, và A-hi-ô, và Xa-cha-ri, và Mi-clốt.'),
(10654, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 38, 'OT', 'Mikloth sinh ra Simeam. Cũng như vậy, họ đã ở tại Giê-ru-sa-lem cùng với anh em mình, đối diện với anh em mình.'),
(10655, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 39, 'OT', 'Và Nê-er sinh ra Kích; và Kích sinh ra Sau-lơ; và Sau-lơ sinh ra Giô-na-than, và Man-ki-sú-a, và A-bi-na-đáp, và Ê-sơ-ba-an.'),
(10656, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 40, 'OT', 'Con trai của Giô-na-than là Mê-ri-ba-an; và Mê-ri-ba-an sinh ra Mi-ca.'),
(10657, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 41, 'OT', 'Và các con trai của Míchah là Pithon, và Melech, và Tahrea.'),
(10658, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 42, 'OT', 'Và A-hách sinh ra Gia-ra; và Gia-ra sinh ra A-lê-mết, và A-xơ-ma-vết, và Xim-ri; và Xim-ri sinh ra Mô-xa.'),
(10659, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 43, 'OT', 'Mo-za sinh Binh-a; và Rê-pha-i-a, con trai người; Ê-lê-a-sa, con trai người; A-xen, con trai người.'),
(10660, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 9, 44, 'OT', 'Và A-xen có sáu người con trai, và đây là những tên của họ: A-xơ-ri-cam, Bô-chê-ru, và Ích-ma-ên, và Sê-a-ri-a, và Ô-ba-đia, và Ha-nan; đây là các con trai của A-xen.'),
(10661, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 10, 1, 'OT', 'Dân Phi-li-tin giao chiến với Y-sơ-ra-ên; những người Y-sơ-ra-ên chạy trốn khỏi mặt dân Phi-li-tin, và ngã xuống chết tại núi Ghít-bô-a.'),
(10662, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 10, 2, 'OT', 'Người Phi-li-tin đuổi theo Sau-lơ và các con trai người; người Phi-li-tin giết Giô-na-than, và A-bi-na-đáp, và Manh-chi-sua, các con trai của Sau-lơ.'),
(10663, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 10, 3, 'OT', 'Chiến tranh trở nên ác liệt nghịch lại Sa-un; những người bắn cung đã bắn trúng người, và người bị các xạ thủ làm cho bị thương.'),
(10664, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 10, 4, 'OT', 'Sao-lơ nói với người mang khí giới mình: "Hãy rút gươm ngươi và đâm tôi, kẻo những kẻ không chịu cắt bì kia đến sỉ nhục tôi." Nhưng người mang khí giới không chịu, vì người rất sợ hãi. Vậy nên, Sao-lơ rút gươm ra và ngã xuống lưỡi gươm.'),
(10665, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 10, 5, 'OT', 'Khi người mang khí giới thấy Sa-un đã chết, người ấy cũng gục xuống trên thanh gươm và chết.'),
(10666, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 10, 6, 'OT', 'Sao-lơ qua đời, và ba người con trai của người, và cả nhà người đều qua đời cùng nhau.'),
(10667, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 10, 7, 'OT', 'Khi mọi người Ít-ra-en ở trong thung lũng thấy quân đội mình tháo chạy và thấy Sau-lơ cùng các con trai mình đã chết, thì họ bỏ các thành mình mà chạy trốn; người Phi-li-tin đến chiếm đóng và định cư trong các thành ấy.'),
(10668, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 10, 8, 'OT', 'Hôm sau, người Phi-li-tin đến cướp những người đã chết, và họ tìm thấy Sa-un cùng các con trai người nằm chết trên núi Ghinh-boa.'),
(10669, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 10, 9, 'OT', 'Họ lột xác ông, lấy đầu và áo giáp của ông, rồi sai đi khắp đất Phi-li-tin để loan tin cho các thần tượng của chúng và cho dân chúng.'),
(10670, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 10, 10, 'OT', 'Họ đặt áo giáp của người trong nhà thần tượng của họ, và treo đầu người trong đền thờ của Đa-gôn.'),
(10671, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 10, 11, 'OT', 'Toàn thể người Giáp-es Ghi-lê-át nghe được mọi điều mà người Phi-li-tin đã làm cho Sau-lơ.'),
(10672, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 10, 12, 'OT', 'Tất cả những người tráng kiện đều đứng dậy, khiêng xác Sa-un và các xác con trai ông, đem về Y-abết, chôn các hài cốt của họ dưới cây sồi ở Y-abết, rồi ăn chay trong bảy ngày.'),
(10673, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 10, 13, 'OT', 'Sa-un chết vì tội phạm mà người đã phạm cùng Đức Giê-hô-va, tức là không giữ lời Đức Giê-hô-va, và cũng vì đã cầu hỏi nơi thầy bói để xin chỉ dẫn.'),
(10674, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 10, 14, 'OT', 'Và người không cầu hỏi Đức Giê-hô-va, nên Ngài đã giết người, và chuyển triều đại sang cho Đa-vít, con trai của Y-sai.'),
(10675, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 1, 'OT', 'Hết thảy người Y-sơ-ra-ên đều nhóm lại cùng Đa-vít tại Hếp-rôn, nói rằng: Nầy, chúng tôi là xương thịt của ngài.'),
(10676, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 2, 'OT', 'Cũng ngày trước, cũng ngày xưa, ngay cả khi Sau-lơ làm vua, chính ngươi là người dẫn ra và đưa vào cho Ít-ra-en; và Đức Giê-hô-va Đức Chúa Trời ngươi đã phán cùng ngươi rằng: Ngươi sẽ chăn giữ dân ta, là Ít-ra-en, và ngươi sẽ làm lãnh tụ trên dân ta, là Ít-ra-en.'),
(10677, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 3, 'OT', 'Vì vậy, tất cả các trưởng lão của Y-sơ-ra-ên đến cùng vua tại Hếp-rôn; và Đa-vít lập giao ước với họ tại Hếp-rôn trước mặt Đức Giê-hô-va; và họ xức dầu cho Đa-vít làm vua trên Y-sơ-ra-ên, theo lời Đức Giê-hô-va bởi tay Sa-mu-ên.'),
(10678, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 4, 'OT', 'Đa-vít và tất cả người Y-sơ-ra-ên đi đến Giê-ru-sa-lem, ấy là Giê-bu; tại đó người Giê-bu-si, những người sống trong xứ, đang ở.'),
(10679, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 5, 'OT', 'Các dân Y-bu-si nói với Đa-vít: "Ngươi sẽ không vào đây được đâu." Nhưng Đa-vít chiếm lấy pháo đài Xi-ôn, tức là thành của Đa-vít.'),
(10680, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 6, 'OT', 'Đa-vít nói: "Ai đánh người Y-bu-sít trước tiên sẽ làm đầu và làm quan trưởng." Vậy, Giô-ab, con trai của Xê-ru-ya, đi lên trước hết, và trở thành đầu.'),
(10681, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 7, 'OT', 'Đa-vít ở trong đồn giữ; vì vậy người ta gọi nó là thành của Đa-vít.'),
(10682, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 8, 'OT', 'Người xây thành phố bao quanh, từ Mi-lô trở đi bao quanh; còn Yo-áp thì sửa chữa phần còn lại của thành phố.'),
(10683, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 9, 'OT', 'Đa-vít ngày càng lớn mạnh, và Đức Giê-hô-va các đạo binh ở cùng người.'),
(10684, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 10, 'OT', 'Đây là các thủ lĩnh của những người dũng cảm thuộc về Đa-vít, những người đã giúp ông củng cố vương quyền, cùng với toàn thể Y-sơ-ra-ên, để tôn ông làm vua, theo lời của Đức Giê-hô-va về Y-sơ-ra-ên.'),
(10685, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 11, 'OT', 'Đây là những người dũng sĩ thuộc về Đa-vít: Gia-sô-ba-am, con trai của Ha-kh-mô-ni, đứng đầu nhóm ba mươi người; ông đã vung ngọn giáo mình giết ba trăm người chết trong một lần.'),
(10686, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 12, 'OT', 'Sau người ấy là Ê-lê-a-xa, con trai của Đô-đô, người A-hô-hít, người thuộc nhóm ba dũng sĩ.'),
(10687, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 13, 'OT', 'Ông ấy đã ở cùng với Đa-vít tại Pa-đam-mim; và người Phi-li-tin đã tụ họp tại đó để giao chiến, nơi có một mảnh đất đầy lúa mạch; và dân chúng đã chạy trốn khỏi trước mặt người Phi-li-tin.'),
(10688, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 14, 'OT', 'Họ đứng giữa đám đông, giải cứu nó, đánh giết người Phi-li-tin; và Đức Giê-hô-va ban cho một sự giải cứu lớn.'),
(10689, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 15, 'OT', 'Ba người trong ba mươi vị chỉ huy đã xuống cùng nhau đến chỗ Đa-vít trên tảng đá, vào hang A-đu-llam; còn đạo quân của người Phi-li-tin thì đóng trại trong thung lũng Rê-pha-im.'),
(10690, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 16, 'OT', 'Bấy giờ Đa-vít đang ở trong đồn, và trại quân của người Phi-li-tin thì đang ở Bết-lê-hem.'),
(10691, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 17, 'OT', 'Đa-vít khao khát, rồi nói: "Ai sẽ cho tôi uống nước từ cái giếng ở Bết-lê-hem, cái giếng ở bên cổng?"'),
(10692, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 18, 'OT', 'Ba người ấy đột phá vào trại quân của người Phi-li-tin, múc nước từ cái giếng ở Bết-lê-hem, nơi nằm gần cổng vào, rồi khiêng lên và mang đến cho Đa-vít; nhưng Đa-vít không chịu uống, mà đổ nước đó ra làm lễ dâng cho Đức Giê-hô-va.'),
(10693, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 19, 'OT', 'Ông nói: Xin Đức Chúa Trời của tôi giữ tôi khỏi làm điều đó! Tôi há có thể uống huyết của những người này sao? Họ đã đem mạng sống mình mà mang nước đến. Vì họ đã liều mạng đem nước đến, nên ông không chịu uống. Đó là điều mà ba người dũng sĩ đã làm.'),
(10694, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 20, 'OT', 'Và A-bi-sai, anh của Giô-áp, là người đứng đầu trong nhóm ba người; chính người đã vung ngọn giáo mình giết chết ba trăm người, và được danh tiếng trong nhóm ba người, nhưng danh tiếng của người không bằng danh tiếng của nhóm ba người.'),
(10695, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 21, 'OT', 'Trong ba người ấy, người nầy được trọng hơn hai người kia và làm tướng lãnh cho họ, nhưng chưa đạt đến cấp của ba người đầu.'),
(10696, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 22, 'OT', 'Bê-nai-a, con trai của Giê-hô-i-đa, con trai một người anh hùng dũng cảm từ Ca-b-xen-ên, là người đã thực hiện nhiều việc lớn: người ấy đã đánh và giết hai chiến sĩ dũng mãnh như sư tử ở Mô-áp; và người ấy cũng đã xuống hố và đánh giết một con sư tử trong ngày tuyết rơi.'),
(10697, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 23, 'OT', 'Và người đánh giết một người Ai Cập, một người cao lớn, cao năm thước; còn trong tay người Ai Cập thì có ngọn giáo như cây thoi của thợ dệt; người ấy đi xuống gặp hắn với cây gậy, đoạt ngọn giáo khỏi tay người Ai Cập, rồi giết hắn bằng chính ngọn giáo của hắn.'),
(10698, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 24, 'OT', 'Benaiah, con trai của Giô-ya-đa, đã làm những điều đó; và người có danh tiếng trong số ba dũng sĩ.'),
(10699, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 25, 'OT', 'Ông ấy được tôn trọng trong nhóm ba mươi người, nhưng không đạt đến hàng thứ ba; và Đa-vít đặt ông ấy làm chỉ huy đội quân của mình.'),
(10700, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 26, 'OT', 'Các dũng sĩ của đạo quân gồm có A-xa-ên, anh của Giô-áp, Ên-ha-nan con trai của Đô-đô, người Bết-lê-hem.'),
(10701, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 27, 'OT', 'Sâm-mốt người Ha-rô-rít, Hê-lết người Pê-lô-nít,'),
(10702, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 28, 'OT', 'I-ra, con trai của Ích-xết, người Tê-cô-a; A-bi-ê-xe, người A-nát.'),
(10703, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 29, 'OT', 'Síp-bê-cai người Hút-tha-thi, Ít-lai người A-hô-thi,'),
(10704, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 30, 'OT', 'Maha-ri người Nê-tô-phát, Hê-lết con trai của Ba-a-nah người Nê-tô-phát,'),
(10705, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 31, 'OT', 'I-thai, con trai của Ri-bai, ở Ghi-bê-ah thuộc con cháu Bên-gia-min; Bê-na-gia người Pi-ra-thôn.'),
(10706, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 32, 'OT', 'Hurai người ở các suối Gaash, A-bi-ên người Arbathite,'),
(10707, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 33, 'OT', 'Azmavết, người Ba-ha-ru-mít; Ê-li-a-kháp, người Sa-an-bô-nít.'),
(10708, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 34, 'OT', 'Các con trai của Ha-sêm người Ghít-xô-ni, và Giô-na-than con trai của Sa-geh người Ha-ra-ri.'),
(10709, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 35, 'OT', 'Ahiam, con trai của Sacar người Harari; Eliphal, con trai của Ur.'),
(10710, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 36, 'OT', 'Hê-phẹr người Mê-ke-rát, A-hi-gia người Pê-lô-nít.'),
(10711, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 37, 'OT', 'Hết-rô người Ca-rơ-mên, Na-a-ri con trai của Ê-xbai,'),
(10712, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 38, 'OT', 'Giô-ên, anh em của Na-than; Míp-ha, con trai của Ha-ge-ri.'),
(10713, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 39, 'OT', 'Xê-léc người Am-môn, Na-ha-ri người Bê-rô-thít, người mang khí giới cho Giô-áp con trai Xê-ru-gia,'),
(10714, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 40, 'OT', 'I-ra người I-thri, Ga-rem người I-thri,'),
(10715, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 41, 'OT', 'U-ri-gia người Hê-th, Xa-bát, con trai của A-hlai,'),
(10716, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 42, 'OT', 'Adina, con trai của Shiza người Ru-bên, chỉ huy của người Ru-bên, và ba mươi người cùng ông,'),
(10717, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 43, 'OT', 'Hanán, con trai của Ma-cha, và Giô-sa-phát người Mít-ni.'),
(10718, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 44, 'OT', 'U-xi-a người A-xtê-ra-thi, Sa-ma và Giê-hi-ên, các con trai của Hô-than người A-rô-ê-ri.'),
(10719, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 45, 'OT', 'Jediael, con trai của Shimri, và Joha, anh em của người, người Tizite.'),
(10720, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 46, 'OT', 'Ê-li-ên người Ma-ha-vít, Giê-ri-bai và Giô-sa-via, các con trai của Ên-na-am, và Ít-ma người Mô-áp.'),
(10721, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 11, 47, 'OT', 'Ê-li-ên, và Ô-bết, và Gia-xi-ên người Mê-xô-ba-ít.'),
(10722, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 1, 'OT', 'Còn đây là những người đến cùng Đa-vít tại Xi-klác, khi người còn đang ẩn náu vì sợ Sau-lơ, con trai của Kích; họ là những chiến sĩ dũng cảm, giúp ích trong chiến trận.'),
(10723, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 2, 'OT', 'Các người giương cung, dùng được cả tay phải lẫn tay trái để ném đá và bắn tên, trong những anh em của Sa-un thuộc chi phái Bên-gia-min.'),
(10724, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 3, 'OT', 'Người đứng đầu là A-hi-ê-xe và Giô-ách, các con trai của Sê-ma-ha người Ghi-bê-a-thít; và Giê-xi-ên và Phê-lết, các con trai của Ách-ma-vết; và Bê-ra-kha, và Giê-hu người An-tốt-thít.'),
(10725, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 4, 'OT', 'Và Y-sách-gia người Ghi-bê-ôn, một dũng sĩ trong nhóm ba mươi và đứng đầu nhóm ba mươi; và Giê-rê-mi, và Gia-ha-xi-ên, và Giô-ha-nan, và Giô-xa-bát người Ghê-đê-ra-thi,'),
(10726, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 5, 'OT', 'Ê-lu-xai, Giê-ri-mốt, Bê-a-lia, Sơ-ma-ri-a, và Sơ-phát-gia, người Ha-ruphite.'),
(10727, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 6, 'OT', 'Ên-ca-nanh, và Y-si-a-hu, và A-xa-rên, và Giô-ê-xe, và Gia-sô-bê-am, những người Cô-rít.'),
(10728, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 7, 'OT', 'Và Giô-ê-la và Xê-ba-đia, các con trai của Giê-rô-ham, thuộc về Ghê-đô.'),
(10729, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 8, 'OT', 'Và từ người Ga-đi, có những người tách ra đầu phục Đa-vít tại nơi ẩn náu trong đồng vắng, là những chiến sĩ dũng cảm, những người lính thiện chiến, biết dùng khiên và giáo; mặt họ như mặt sư tử, và họ nhanh nhẹn như những con sơn dương trên núi.'),
(10730, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 9, 'OT', 'Ê-xe đứng đầu, Ô-ba-đi-a thứ nhì, Ê-li-áp thứ ba.'),
(10731, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 10, 'OT', 'Mishmanna người thứ tư, Giê-rê-mi người thứ năm.'),
(10732, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 11, 'OT', 'At-tai người thứ sáu, Ê-li-ên người thứ bảy.'),
(10733, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 12, 'OT', 'Giô-ha-nan người thứ tám, Ên-xa-bát người thứ chín.'),
(10734, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 13, 'OT', 'Giê-rê-mi người thứ mười, Mách-ba-nai người thứ mười một.'),
(10735, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 14, 'OT', 'Đây là những người con trai của Ga-đi, các viên chỉ huy quân đội: người ít nhất chỉ huy một trăm người, còn người lớn nhất chỉ huy một ngàn người.'),
(10736, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 15, 'OT', 'Đây là những người đã qua sông Giô-đanh trong tháng đầu, khi nước đã tràn ngập khắp các bờ của nó; họ đã khiến toàn thể các dân trong các thung lũng chạy trốn, về phía đông và về phía tây.'),
(10737, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 16, 'OT', 'Các con trai của Bên-gia-min và Giu-đa đến nơi ẩn náu cùng Đa-vít.'),
(10738, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 17, 'OT', 'Đa-vít đi ra đến trước mặt họ, đáp và nói với họ: "Nếu các ngươi đến cùng ta bình an để giúp đỡ ta, thì lòng ta sẽ gắn bó với các ngươi; nhưng nếu các ngươi đến để phản ta cho kẻ thù ta, trong khi tay ta chẳng có điều ác gì, thì Đức Chúa Trời của tổ tiên chúng ta sẽ nhìn thấy và xét xử điều đó."'),
(10739, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 18, 'OT', 'Rồi Thần đã ngự trên Amasai, người đứng đầu các đội trưởng, người nói: "Chúng tôi thuộc về ngài, hỡi Đa-vít, và ủng hộ ngài, hỡi con trai của Y-sai. Bình an, bình an cho ngài và bình an cho những người giúp đỡ ngài, vì Đức Chúa Trời của ngài phù trợ ngài." Vậy Đa-vít tiếp nhận họ và bổ nhiệm họ làm các đội trưởng.'),
(10740, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 19, 'OT', 'Có những người thuộc chi phái Ma-na-se bị bỏ rơi đến với Đa-vít, khi người đi cùng quân Phi-li-tin để đánh chiến với Sau-lơ; nhưng họ không giúp quân Phi-li-tin, vì các lãnh chúa Phi-li-tin, sau khi bàn luận, đã cho người đi và nói: "Người sẽ phản lại chủ mình là Sau-lơ, và như vậy đầu chúng ta sẽ bị nguy hiểm."'),
(10741, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 20, 'OT', 'Khi người đi về Xích-lai, thì có những người thuộc chi phái Ma-na-xe đến theo người, là A-đanh, Giô-xáp, Giê-đi-ên, Mi-ca-ên, Giô-xáp, Ê-li-hu và Xít-lai, các quan chỉ huy ngàn người thuộc về Ma-na-xe.'),
(10742, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 21, 'OT', 'Họ đã giúp Đa-vít chống lại toán cướp; vì tất cả đều là những người dũng cảm, và họ đã làm các quan chỉ huy trong đạo quân.'),
(10743, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 22, 'OT', 'Vì ngày qua ngày, dân chúng đến cùng Đa-vít để giúp đỡ ông, cho đến khi đạo quân trở nên đông đảo như đạo quân của Đức Chúa Trời.'),
(10744, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 23, 'OT', 'Đây là số người chỉ huy các toán quân đã sẵn sàng ra trận, đến cùng Đa-vít tại Hếp-rôn để chuyển vương quốc của Sau-lơ sang cho ông, theo lời của Đức Giê-hô-va.'),
(10745, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 24, 'OT', 'Con cái Giu-đa, những người mang khiên và giáo, gồm sáu ngàn tám trăm người tinh nhuệ sẵn sàng ra trận.'),
(10746, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 25, 'OT', 'Thuộc con cái của Si-mê-ôn, những người trai tráng dũng cảm cho đạo quân, bảy ngàn một trăm người.'),
(10747, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 26, 'OT', 'Bốn ngàn sáu trăm người trong các con trai của Lêvi.'),
(10748, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 27, 'OT', 'Và Giô-ha-đa làm người lãnh đạo của các thầy tế lễ A-ha-ron, và cùng ông có ba ngàn bảy trăm người.'),
(10749, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 28, 'OT', 'Và Xa-đốc, một người trẻ tuổi mạnh mẽ và dũng cảm, và trong nhà của cha ông có hai mươi hai viên chỉ huy.'),
(10750, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 29, 'OT', 'Và từ con cháu Bên-gia-min, anh em của Sau-lơ, ba ngàn người; đến thời điểm này, phần lớn trong số họ vẫn giữ chức vụ canh giữ nhà của Sau-lơ.'),
(10751, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 30, 'OT', 'Còn từ các con trai của Ép-ra-im, hai mươi ngàn tám trăm người, là những chiến sĩ dũng cảm, nổi tiếng trong các gia tộc tổ tiên của họ.'),
(10752, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 31, 'OT', 'Và từ phân nửa chi phái Ma-na-se, mười tám ngàn người, những người đã được ghi rõ tên tuổi, đến để tôn vương Đa-vít.'),
(10753, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 32, 'OT', 'Còn về con cháu Y-xa-sa, những người hiểu biết thời thế, biết điều mà Y-sơ-ra-ên phải làm: các lãnh tụ của họ là hai trăm người, và tất cả anh em họ đều theo sự chỉ huy của họ.'),
(10754, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 33, 'OT', 'Từ Xê-bu-lôn, những người ra đi ra trận, chuyên về chiến trận, với đủ mọi khí giới chiến tranh, năm mươi ngàn người, và họ trung thành trọn lòng.'),
(10755, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 34, 'OT', 'Từ Na-phtha-li có một ngàn sĩ quan, và cùng họ, với khiên và giáo, ba mươi bảy ngàn người.'),
(10756, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 35, 'OT', 'Và từ chi phái Đan, những người chuyên về chiến trận, hai mươi tám ngàn sáu trăm người.'),
(10757, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 36, 'OT', 'Còn từ chi phái A-xe, những người ra đi để tòng quân và tham gia trận chiến, có bốn mươi ngàn người.'),
(10758, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 37, 'OT', 'Về bên kia sông Giô-đanh, từ con cháu Ru-bên, và người Ga-đi, và phân nửa chi phái Ma-na-xe, tất cả đều cầm các khí giới chiến tranh, gồm một trăm hai mươi ngàn người.'),
(10759, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 38, 'OT', 'Tất cả những người chiến sĩ này, có thể duy trì đội hình, đã đến Hếp-rôn với trọn tấm lòng để tôn Đa-vít làm vua trên toàn thể Y-sơ-ra-ên; và tất cả những người Y-sơ-ra-ên còn lại cũng đồng tâm để tôn Đa-vít làm vua.'),
(10760, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 39, 'OT', 'Họ ở đó với Đa-vít ba ngày, ăn và uống, vì anh em họ đã chuẩn bị cho họ.'),
(10761, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 12, 40, 'OT', 'Các anh em gần họ, cho đến các chi phái Ích-sa-sa, Xê-bu-lôn và Náp-ta-li, cũng mang bánh đến trên các con lừa, các con lạc đà, các con la, và các con bò; thức ăn gồm bột, bánh vả khô, nho khô, rượu, dầu, bò và chiên rất dồi dào, vì trong Ít-ra-en có sự vui mừng lớn.'),
(10762, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 13, 1, 'OT', 'Đa-vít bàn luận cùng các quan trưởng của hàng ngàn và hàng trăm, cùng mọi lãnh đạo.'),
(10763, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 13, 2, 'OT', 'Đa-vít nói với toàn thể hội chúng của Ít-ra-en: "Nếu điều này tốt đẹp trong mắt các ngươi và đến từ Đức Giê-hô-va Đức Chúa Trời chúng ta, thì chúng ta hãy sai người đi khắp nơi đến anh em chúng ta còn sót lại trong mọi vùng đất Ít-ra-en, và đến cả các thầy tế lễ và người Lê-vi ở các thành và vùng phụ cận của họ, để họ nhóm lại với chúng ta."'),
(10764, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 13, 3, 'OT', 'Chúng ta hãy mang rương của Đức Chúa Trời chúng ta trở lại với chúng ta, vì chúng ta đã không cầu hỏi Ngài qua rương ấy trong những ngày của Sau-lơ.'),
(10765, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 13, 4, 'OT', 'Toàn thể hội chúng nói rằng họ sẽ làm điều đó, vì điều ấy đẹp lòng mọi người.'),
(10766, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 13, 5, 'OT', 'Đa-vít triệu tập toàn thể dân Y-sơ-ra-ên, từ Sihor ở Ê-díp-tô cho đến lối vào Ha-mát, để đi rước hòm của Đức Chúa Trời từ Ki-ri-át Giê-a-rim.'),
(10767, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 13, 6, 'OT', 'Đa-vít cùng toàn thể dân Ít-ra-en lên Ba-a-lah, đến Kinh thành Giê-a-rim thuộc về chi phái Giu-đa, để từ đó mang hòm giao ước của Đức Chúa Trời, là Đức Giê-hô-va ngự trên các chê-ru-bim, Đấng được gọi danh.'),
(10768, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 13, 7, 'OT', 'Họ đặt hòm của Đức Chúa Trời lên một cái xe mới, lấy từ nhà A-bi-na-đáp, và U-xa cùng A-hi-ô điều khiển cái xe.'),
(10769, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 13, 8, 'OT', 'Đa-vít và toàn thể Ít-ra-en nhảy múa trước mặt Đức Chúa Trời hết sức mình, cùng với các bài hát, và với đàn cầm, đàn sắt, trống nhỏ, chập chỏa, và tù và.'),
(10770, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 13, 9, 'OT', 'Khi họ đến nơi sân đập lúa của Kidon, U-za đưa tay ra đỡ hòm giao ước, vì các con bò mộng vấp ngã.'),
(10771, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 13, 10, 'OT', 'Đức Giê-hô-va nổi giận cùng U-xa, bèn đánh nó vì đã ra tay đỡ hòm báu; và nó chết tại đó trước mặt Đức Chúa Trời.'),
(10772, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 13, 11, 'OT', 'Đa-vít nổi giận vì Đức Giê-hô-va đã giáng họa trên U-xa; nên người đặt tên cho nơi ấy là Pha-rết U-xa, cho đến ngày nay.'),
(10773, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 13, 12, 'OT', 'Đa-vít sợ Đức Chúa Trời trong ngày ấy, nói rằng: "Làm thế nào tôi có thể mang rương của Đức Chúa Trời về với tôi?"'),
(10774, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 13, 13, 'OT', 'Đa-vít không mang hòm giao ước về cho mình tại thành Đa-vít, mà chuyển nó sang nhà Ô-bê-đê-ôm người Ghít-tít.'),
(10775, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 13, 14, 'OT', 'Hòm của Đức Chúa Trời ở cùng nhà O-bết Ê-đôm trong nhà người ba tháng. Và Đức Giê-hô-va ban phước cho nhà O-bết Ê-đôm và cho mọi điều người có.'),
(10776, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 14, 1, 'OT', 'Hi-ram, vua thành Ty-rơ, sai các sứ giả đến cùng Đa-vít, cùng với những cây gỗ bá hương, thợ xây tường và thợ mộc, để xây một ngôi nhà cho người.'),
(10777, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 14, 2, 'OT', 'Đa-vít biết rằng Đức Giê-hô-va đã lập ông làm vua trên Ít-ra-en, vì vương quyền của ông được nâng cao rất cao, vì cớ dân sự ông là Ít-ra-en.'),
(10778, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 14, 3, 'OT', 'Đa-vít cưới thêm các vợ khác tại Giê-ru-sa-lem; và Đa-vít sinh thêm các con trai và con gái.'),
(10779, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 14, 4, 'OT', 'Còn đây là các tên các con trai sinh ra cho ông tại Giê-ru-sa-lem: Sam-mua, và Sô-báp, Na-than, và Sa-lô-môn,'),
(10780, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 14, 5, 'OT', 'Và I-ba, và Ê-li-sú-a, và Ê-l-ph-a-lết,'),
(10781, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 14, 6, 'OT', 'Và Nô-ga, và Né-phég, và Gia-phia,'),
(10782, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 14, 7, 'OT', 'Và Ê-li-sa-ma, và Bê-ên-i-a-đa, và Ê-li-pha-lết.'),
(10783, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 14, 8, 'OT', 'Khi người Phi-li-tin nghe tin Đa-vít đã được xức làm vua trên toàn thể Y-sơ-ra-ên, thì toàn thể người Phi-li-tin lên đường để tìm đánh Đa-vít. Đa-vít nghe tin đó, liền đi ra nghênh chiến với họ.'),
(10784, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 14, 9, 'OT', 'Người Phi-li-tin đến và trải ra trong trũng Rê-pha-im.'),
(10785, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 14, 10, 'OT', 'Đa-vít cầu hỏi Đức Chúa Trời, nói: "Tôi có nên đi đánh người Phi-li-tin không? Ngài có sẽ nộp họ vào tay tôi không?" Và Đức Giê-hô-va phán cùng ông: "Hãy đi lên, vì Ta sẽ nộp họ vào tay ngươi."'),
(10786, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 14, 11, 'OT', 'Họ lên đến Ba-al Phê-ra-xim, và Đa-vít đánh bại chúng tại đó. Rồi Đa-vít nói: "Đức Chúa Trời đã phá vỡ các kẻ thù tôi trong tay tôi như nước vỡ bờ vậy." Vì lý do đó, người ta gọi tên nơi ấy là Ba-al Phê-ra-xim.'),
(10787, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 14, 12, 'OT', 'Họ bỏ các thần của mình tại đó, rồi Đa-vít truyền lệnh, và người ta đã thiêu các thần ấy trong lửa.'),
(10788, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 14, 13, 'OT', 'Và người Phi-li-tin lại tiếp tục kéo đến, lan tràn khắp thung lũng.'),
(10789, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 14, 14, 'OT', 'Đa-vít lại cầu hỏi Đức Chúa Trời; và Đức Chúa Trời phán cùng người rằng: "Ngươi chớ đi lên theo sau chúng nó; hãy quay vòng khỏi chúng nó, và đến đánh chúng nó đối diện với các cây bách hương."'),
(10790, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 14, 15, 'OT', 'Khi ngươi nghe tiếng động bước đi nơi đầu các cây dâu, thì phải ra đi đánh giặc; vì Đức Chúa Trời đã đi ra trước mặt ngươi để đánh bại đạo quân của người Phi-li-tin.'),
(10791, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 14, 16, 'OT', 'Đa-vít làm theo như Đức Chúa Trời đã truyền dặn ông, và họ đánh bại đạo quân của người Phi-li-tin từ Gíp-bôn cho đến Gát-xe.'),
(10792, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 14, 17, 'OT', 'Danh tiếng của Đa-vít lan ra khắp các nước, và Đức Giê-hô-va khiến sự kính sợ người đè nén trên mọi dân tộc.'),
(10793, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 15, 1, 'OT', 'Đa-vít xây các ngôi nhà trong thành Đa-vít, và chuẩn bị một nơi cho hòm của Đức Chúa Trời, rồi dựng cho nó một cái lều.'),
(10794, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 15, 2, 'OT', 'Đa-vít bèn nói: "Chỉ những người Lê-vi mới được phép khiêng hòm giao ước Đức Chúa Trời, vì chính Đức Giê-hô-va đã chọn họ để khiêng hòm giao ước Đức Giê-hô-va và phụng sự Ngài đời đời."'),
(10795, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 15, 3, 'OT', 'Đa-vít triệu tập toàn thể dân Ít-ra-en về Giê-ru-sa-lem, để rước hòm giao ước của Đức Giê-hô-va về nơi người đã chuẩn bị sẵn cho nó.'),
(10796, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 15, 4, 'OT', 'Đa-vít tập trung các con trai của A-ha-ron và các người Lê-vi.'),
(10797, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 15, 5, 'OT', 'Thuộc về các con trai của Kê-hát: U-ri-ên làm người lãnh đạo, và các anh em người là một trăm hai mươi người.'),
(10798, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 15, 6, 'OT', 'Con trai của Mê-ra-ri: A-xa-ia làm lãnh đạo, và các anh em người là hai trăm hai mươi người.'),
(10799, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 15, 7, 'OT', 'Con trai của Ghẹt-sôm: Giô-ên làm người lãnh đạo, và các anh em người là một trăm ba mươi người.'),
(10800, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 15, 8, 'OT', 'Thuộc về các con trai của Ê-li-xa-phan: Sê-ma-gia làm người đứng đầu, và các anh em người là hai trăm người.'),
(10801, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 15, 9, 'OT', 'Con trai của Hếp-rôn: Ê-li-ên là người đứng đầu, và các anh em người là tám mươi người.'),
(10802, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 15, 10, 'OT', 'Con trai của Út-xi-ên: A-min-na-đáp làm người lãnh đạo, và các anh em người là một trăm mười hai người.'),
(10803, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 15, 11, 'OT', 'Đa-vít gọi các thầy tế lễ Xa-đốc và A-bi-át-ta, và các người Lê-vi là U-ri-ên, A-xa-ia, Giô-ên, Sê-ma-ia, Ê-li-ên và A-mi-na-đáp.'),
(10804, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 15, 12, 'OT', 'Ông nói với họ: "Các ngươi là các tộc trưởng của người Lê-vi; hãy làm cho mình và anh em mình nên thánh, để các ngươi mang rương của Đức Giê-hô-va Đức Chúa Trời Ít-ra-en lên nơi ta đã chuẩn bị sẵn cho nó."'),
(10805, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 15, 13, 'OT', 'Vì từ lúc đầu các ngươi không làm điều đó, nên Đức Giê-hô-va Đức Chúa Trời chúng ta đã giáng họa trên chúng ta, vì chúng ta đã không tìm cầu Ngài theo đúng quy định.'),
(10806, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 15, 14, 'OT', 'Các thầy tế lễ và các người Lê-vi làm cho mình nên thánh để khiêng hòm giao ước của Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en.'),
(10807, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 15, 15, 'OT', 'Các con trai của người Lê-vi khiêng hòm của Đức Chúa Trời trên vai mình, theo như Môi-se đã truyền, y như lời của Đức Giê-hô-va, với các cây khiêng đặt trên đó.'),
(10808, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 15, 16, 'OT', 'Đa-vít nói với các quan trưởng của người Lê-vi rằng hãy chỉ định anh em họ làm những người hát xướng, dùng các nhạc cụ như đờn nghẹt, đờn cầm và chập chỏa, phát ra tiếng vang cùng tiếng hát vui mừng.'),
(10809, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 15, 17, 'OT', 'Các người Lê-vi đặt Hê-man, con trai của Giô-ên; và trong các anh em ông, Áp-áp, con trai của Bê-rê-ki-a; và trong các con trai của Mê-ra-ri, anh em họ, Ê-than, con trai của Cu-sai-a.'),
(10810, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 15, 18, 'OT', 'Và cùng với họ là các anh em của họ thuộc hàng thứ hai: Xa-cha-ri, Bên, và Gia-a-xi-ên, và Sê-mi-ra-mốt, và Giê-hi-ên, và Un-ni, Ê-li-áp, và Bê-nai-a, và Ma-a-xe-ia, và Ma-ti-thia, và Ê-li-phê-lê, và Mích-nê-a, và Ô-ved Ê-đôm, và Giê-iel, những người giữ cửa.'),
(10811, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 15, 19, 'OT', 'Còn những người hát xướng là Hê-man, A-sáp và Ê-than, dùng cymbal bằng đồng để phát ra tiếng.'),
(10812, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 15, 20, 'OT', 'Và Xa-cha-ri, và A-xi-ên, và Sê-mi-ra-mốt, và Giê-hi-ên, và Un-ni, và Ê-li-áp, và Ma-a-xe-ia, và Bê-na-gia, đều cầm cầm nhạc cụ trên các dây đàn dành cho các thiếu nữ.'),
(10813, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 15, 21, 'OT', 'Và Mát-thít-hia, Ê-li-phê-lê, Mích-nê-a, Óp-đết-ôm, Giê-đi-ên và A-xa-xia, dùng đờn cầm trên tám dây để dẫn đầu.'),
(10814, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 15, 22, 'OT', 'Và Khenaniah làm người chỉ huy các người Lê-vi trong việc khiêng đồ; người này được giao lo việc khiêng, vì người hiểu rõ về điều đó.'),
(10815, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 15, 23, 'OT', 'Và Bê-rê-ky-a và Ên-ca-na làm người giữ cửa cho hòm giao ước.'),
(10816, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 15, 24, 'OT', 'Và Sê-ba-nia, Giô-sa-phát, Nét-ha-nên, A-ma-sai, Xa-cha-ri-a, Bê-nai-a và Ê-li-ê-xe, các thầy tế lễ, thổi kèn trước hòm của Đức Chúa Trời; còn Ô-bết-Ê-đôm và Giê-hia thì giữ cửa cho hòm.'),
(10817, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 15, 25, 'OT', 'Đa-vít, các trưởng lão của Ít-ra-en và các quan chỉ huy ngàn người đi lên đem hòm giao ước của Đức Giê-hô-va từ nhà Ô-bết-Ê-đôm với niềm vui mừng.'),
(10818, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 15, 26, 'OT', 'Khi Đức Chúa Trời giúp đỡ những người Lê-vi khiêng hòm giao ước của Đức Giê-hô-va, thì họ dâng bảy con bò đực và bảy con chiên đực làm của lễ.'),
(10819, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 15, 27, 'OT', 'Đa-vít mặc áo bằng vải gai mịn, và mọi người Lê-vi khiêng hòm, các ca sĩ, và Kê-na-nia làm lãnh đạo việc hát cho các ca sĩ; Đa-vít cũng mặc áo thầy tế lễ bằng vải gai.'),
(10820, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 15, 28, 'OT', 'Toàn thể Y-sơ-ra-ên rước hòm giao ước của Đức Giê-hô-va bằng tiếng reo vui, tiếng kèn hu, tiếng tù và và tiếng chập chỏa, đồng thời làm vang lên tiếng đờn cầm và đờn lia.'),
(10821, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 15, 29, 'OT', 'Khi hòm giao ước của Đức Giê-hô-va đến thành Đa-vít, Mi-khai, con gái vua Sau-lơ, nhìn ra từ cửa sổ và thấy vua Đa-vít nhảy múa và ca hát, thì bà khinh bỉ người trong lòng mình.'),
(10822, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 1, 'OT', 'Họ mang rương của Đức Chúa Trời đến và đặt nó ở giữa cái lều mà Đa-vít đã dựng lên cho nó; rồi họ dâng các của lễ thiêu và các của lễ thù ân trước mặt Đức Chúa Trời.'),
(10823, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 2, 'OT', 'Sau khi Đa-vít dâng các lễ toàn thiêu và lễ thù ân xong, người chúc phước cho dân chúng nhân danh Đức Giê-hô-va.'),
(10824, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 3, 'OT', 'Ông phân phát cho mỗi người Ít-ra-en, từ người nam cho đến người nữ: mỗi người một ổ bánh mì, một miếng thịt nạc và một bánh chà là.'),
(10825, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 4, 'OT', 'Ông chỉ định một số người Lê-vi phục vụ trước hòm giao ước của Đức Giê-hô-va, và để nhắc nhớ, cảm tạ và ca ngợi Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en.'),
(10826, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 5, 'OT', 'A-sáp làm trưởng nhóm, và người kế ông là Xác-cha-ri, cùng Giê-đi-ên, Sê-mi-ra-mốt, Giê-hi-ên, Mát-ti-thia, Ê-li-áp, Bê-na-gia, Ô-bết-Ê-đôm, và Giê-đi-ên, tất cả dùng các nhạc cụ tỳ bà và đờn cầm; còn A-sáp thì đánh trống đồng vang lên.'),
(10827, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 6, 'OT', 'Các thầy tế lễ Bê-nai-a và Gia-ha-xi-ên thổi kèn không ngừng trước hòm giao ước của Đức Chúa Trời.'),
(10828, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 7, 'OT', 'Ngày ấy, Đa-vít lần đầu tiên cử A-sáp và các anh em người ca ngợi Đức Giê-hô-va.'),
(10829, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 8, 'OT', 'Hãy tạ ơn Đức Giê-hô-va, hãy kêu cầu danh Ngài, hãy rao truyền các việc Ngài làm giữa các dân.'),
(10830, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 9, 'OT', 'Hãy hát cho Ngài, hãy đàn ca cho Ngài; hãy nói về mọi việc kỳ diệu của Ngài.'),
(10831, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 10, 'OT', 'Hãy vui vẻ trong danh thánh của Ngài; lòng những kẻ tìm kiếm Đức Giê-hô-va hãy mừng rỡ.'),
(10832, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 11, 'OT', 'Hãy tìm Đức Giê-hô-va và quyền năng Ngài, hãy cầu tìm mặt Ngài luôn luôn.'),
(10833, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 12, 'OT', 'Hãy nhớ các việc diệu kỳ mà Ngài đã làm, những dấu kỳ và các phán quyết từ miệng Ngài.'),
(10834, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 13, 'OT', 'Hỡi các con cháu Y-sơ-ra-ên, tôi tớ Ngài, hỡi các con cái của Gia-cốp, những người Ngài chọn lựa.'),
(10835, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 14, 'OT', 'Chính Ngài là Đức Giê-hô-va Đức Chúa Trời chúng ta; các phán quyết của Ngài ở khắp đất.'),
(10836, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 15, 'OT', 'Hãy nhớ mãi mãi giao ước của Ngài, lời Ngài truyền cho ngàn đời.'),
(10837, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 16, 'OT', 'Giao ước Ngài lập với Áp-ra-ham và lời thề Ngài hứa với Y-sác.'),
(10838, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 17, 'OT', 'Và Ngài đã thiết lập điều đó cho Gia-cốp làm một điều răn, cho Ít-ra-en làm một giao ước đời đời.'),
(10839, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 18, 'OT', 'Nói rằng: Ta sẽ ban cho ngươi đất Ca-na-an, làm phần sản nghiệp của các ngươi.'),
(10840, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 19, 'OT', 'Khi các ngươi chỉ là một số ít, rất ít, và là khách lạ tại nơi ấy.'),
(10841, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 20, 'OT', 'Họ đi từ nước nầy sang nước khác, từ một vương quốc đến một dân tộc khác.'),
(10842, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 21, 'OT', 'Người không để một người nào làm ác với họ; và vì cớ họ, Ngài quở trách các vua.'),
(10843, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 22, 'OT', 'Đừng đụng đến những người Ta đã xức dầu, và đừng làm hại các nhà tiên tri của Ta.'),
(10844, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 23, 'OT', 'Hỡi khắp đất, hãy hát bài ca cho Đức Giê-hô-va; mỗi ngày hãy rao ra sự cứu rỗi của Ngài.'),
(10845, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 24, 'OT', 'Hãy rao báo sự vinh hiển của Ngài giữa các dân tộc, và những việc diệu kỳ của Ngài giữa mọi quốc gia.'),
(10846, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 25, 'OT', 'Vì Đức Giê-hô-va là Đấng cao cả và được ngợi khen cách rất nhiều, và Ngài đáng sợ trên hết thảy các thần.'),
(10847, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 26, 'OT', 'Vì mọi thần của các dân tộc đều là hình tượng vô giá trị, còn Đức Giê-hô-va đã tạo nên các tầng trời.'),
(10848, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 27, 'OT', 'Sự vinh hiển và oai nghi ở trước mặt Ngài; quyền năng và niềm vui mừng tại nơi Ngài.'),
(10849, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 28, 'OT', 'Hỡi các dòng họ của các dân, hãy dâng cho Đức Giê-hô-va, hãy dâng cho Đức Giê-hô-va sự vinh hiển và quyền năng.'),
(10850, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 29, 'OT', 'Hãy dâng cho Đức Giê-hô-va sự vinh hiển thuộc về danh Ngài; hãy mang lễ vật và đến trước mặt Ngài; hãy thờ lạy Đức Giê-hô-va trong vẻ trang nghiêm thánh.'),
(10851, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 30, 'OT', 'Hãy run sợ trước mặt Ngài, hỡi cả đất; quả thật, thế gian sẽ được lập vững chắc, không lay động.'),
(10852, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 31, 'OT', 'Các tầng trời hãy vui mừng, và đất hãy hân hoan; và hãy nói giữa các dân tộc: Đức Giê-hô-va làm Vua.'),
(10853, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 32, 'OT', 'Hãy để biển reo vang và mọi vật trong đó; hãy để đồng ruộng hớn hở và mọi vật ở trong nó.'),
(10854, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 33, 'OT', 'Bấy giờ các cây trong rừng sẽ reo mừng trước mặt Đức Giê-hô-va, vì Ngài đến để xét đoán đất.'),
(10855, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 34, 'OT', 'Hãy cảm tạ Đức Giê-hô-va, vì Ngài là thiện; vì sự nhân từ của Ngài còn đời đời.'),
(10856, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 35, 'OT', 'Và hãy nói: "Xin Đức Chúa Trời của sự cứu rỗi chúng tôi, xin hãy cứu chúng tôi, và nhóm họp chúng tôi lại, giải thoát chúng tôi khỏi các dân tộc, để chúng tôi cảm tạ danh thánh của Ngài, và tự hào trong sự ngợi khen Ngài."'),
(10857, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 36, 'OT', 'Được phước thay Đức Giê-hô-va, Đức Chúa Trời của Ít-ra-en, từ đời này sang đời khác. Và toàn thể dân chúng nói: "A-men," và ca ngợi Đức Giê-hô-va.'),
(10858, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 37, 'OT', 'Ông để A-sáp và các anh em người phục vụ trước hòm giao ước của Đức Giê-hô-va, để thường xuyên làm việc hằng ngày như thể, trước hòm đó.'),
(10859, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 38, 'OT', 'Ông Ót-đê-đôm và anh em ông ấy, sáu mươi tám người; ông Ót-đê-đôm, con trai của Giát-đút, và Hô-sa làm người giữ cửa.'),
(10860, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 39, 'OT', 'Còn Xa-đốc thầy tế lễ và các anh em thầy tế lễ của người ở trước nhà tạm của Đức Giê-hô-va tại nơi cao ở Ghi-bê-ôn.'),
(10861, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 40, 'OT', 'Để dâng những của lễ thiêu lên Đức Giê-hô-va trên bàn thờ của lễ thiêu luôn luôn, mỗi buổi sáng và chiều tối, và để làm theo mọi điều đã chép trong luật pháp của Đức Giê-hô-va, mà Ngài đã truyền cho Y-sơ-ra-ên.'),
(10862, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 41, 'OT', 'Cùng với họ là Hê-man, Ít-đu-thun và những người khác đã được chọn lựa, được chỉ định rõ tên, để ca tụng Đức Giê-hô-va, vì sự nhân từ của Ngài còn đến đời đời.'),
(10863, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 42, 'OT', 'Hê-man và Ít-đu-thun cùng với những chiếc tù và và những chiếc chập chỏa để tạo tiếng vang, cùng các nhạc cụ dùng trong việc ca ngợi Đức Chúa Trời; và các con trai của Ít-đu-thun thì làm nhiệm vụ canh giữ cửa.'),
(10864, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 16, 43, 'OT', 'Và toàn thể dân chúng đều đi mỗi người về nhà mình; còn Đa-vít trở về để ban phước cho gia đình ông.'),
(10865, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 17, 1, 'OT', 'Khi Đa-vít đang ở trong nhà mình, thì người nói với Na-than, nhà tiên tri: "Nầy, tôi đang ở trong một ngôi nhà bằng gỗ hương nam, nhưng rương giao ước của Đức Giê-hô-va thì lại dưới những cái lều."'),
(10866, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 17, 2, 'OT', 'Rồi Na-than nói với Đa-vít: "Hãy làm mọi điều ở trong lòng ông, vì Đức Chúa Trời ở cùng ông."'),
(10867, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 17, 3, 'OT', 'Đức Giê-hô-va phán cùng Na-than trong đêm ấy, rằng:'),
(10868, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 17, 4, 'OT', 'Hãy đi và nói cùng Đa-vít, tôi tớ ta: Đức Giê-hô-va phán như vầy: Ngươi sẽ không xây cho Ta một ngôi nhà để ở,'),
(10869, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 17, 5, 'OT', 'Vì ta chưa hề ở trong nhà kể từ ngày ta dẫn Y-sơ-ra-ên lên cho đến ngày nay, mà ta đi từ lều nọ đến lều kia, và từ nơi tạm trú nọ đến nơi tạm trú kia.'),
(10870, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 17, 6, 'OT', 'Trong mọi nơi Ta đi cùng toàn thể Y-sơ-ra-ên, Ta đã nói lời nào với một trong các quan xét Y-sơ-ra-ên, mà Ta đã chỉ định để chăn dắt dân Ta, rằng: "Tại sao các ngươi không xây cho Ta một ngôi nhà bằng gỗ bá hương?"'),
(10871, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 17, 7, 'OT', 'Bây giờ, hãy nói như thế nầy với đầy tớ ta là Đa-vít: Đức Giê-hô-va các đạo binh phán như vầy: Chính Ta đã lấy ngươi từ nơi chuồng chiên, từ sau những con chiên, để ngươi làm người lãnh đạo trên dân Ta là Y-sơ-ra-ên.'),
(10872, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 17, 8, 'OT', 'Ta đã ở cùng ngươi trong mọi nơi ngươi đi, Ta đã tiêu diệt mọi kẻ thù ngươi khỏi trước mặt ngươi, và Ta sẽ làm cho ngươi được danh tiếng như danh tiếng của những người vĩ đại trên đất.'),
(10873, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 17, 9, 'OT', 'Ta sẽ định một nơi cho dân Ta là Y-sơ-ra-ên, và Ta sẽ trồng chúng nó, chúng nó sẽ sống yên ổn tại nơi ấy và sẽ không còn bị lay chuyển nữa; con cái sự gian ác sẽ không còn làm chúng nó khốn khổ như lúc trước.'),
(10874, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 17, 10, 'OT', 'Kể từ khi Ta truyền các quan xét trị vì trên dân Ta là Y-sơ-ra-ên, Ta sẽ khiến mọi kẻ thù của ngươi phải khuất phục; và Ta báo cho ngươi biết rằng Đức Giê-hô-va sẽ xây dựng một ngôi nhà cho ngươi.'),
(10875, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 17, 11, 'OT', 'Khi các ngày của ngươi đã đầy đủ để về cùng các tổ tiên ngươi, ta sẽ khiến dòng dõi ngươi, sinh ra từ con trai ngươi, nổi lên sau ngươi, và ta sẽ củng cố vương quốc người ấy.'),
(10876, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 17, 12, 'OT', 'Người sẽ xây một ngôi nhà cho tôi, và tôi sẽ lập ngôi báu của người đến muôn đời.'),
(10877, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 17, 13, 'OT', 'Ta sẽ làm cha cho nó, và nó sẽ làm con cho Ta; và sự thương xót của Ta sẽ không rút lui khỏi nó, như Ta đã rút khỏi người đã ở trước ngươi.'),
(10878, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 17, 14, 'OT', 'Nhưng Ta sẽ đặt người ấy trong nhà Ta và trong vương quốc Ta mãi mãi; và ngôi vua của người ấy sẽ được lập vững chắc đến muôn đời.'),
(10879, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 17, 15, 'OT', 'Theo tất cả những lời nầy, và theo tất cả thị kiến nầy, thì Nát-an nói cùng Đa-vít.'),
(10880, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 17, 16, 'OT', 'Vua Đa-vít vào, ngồi trước mặt Đức Giê-hô-va, rồi nói: "Tôi là ai, hỡi Đức Giê-hô-va là Đức Chúa Trời, và nhà tôi là gì, mà Ngài đã đưa tôi đến đây?'),
(10881, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 17, 17, 'OT', 'Lại còn điều nầy, Đức Chúa Trời, thật là nhỏ bé trong mắt Ngài, nên Ngài đã phán về nhà của đầy tớ Ngài cho đến một thời gian rất lâu về sau; và Ngài đã nhìn tôi như một người được nâng cao, hỡi Đức Giê-hô-va Đức Chúa Trời.'),
(10882, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 17, 18, 'OT', 'Lạy Đức Giê-hô-va, Đa-vít còn có thể nói thêm điều gì để tôn vinh đầy tớ Ngài được nữa? Vì chính Ngài đã biết đầy tớ của Ngài.'),
(10883, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 17, 19, 'OT', 'Đức Giê-hô-va ơi, vì cớ đầy tớ Ngài và theo lòng Ngài, Ngài đã làm trọn sự cao trọng nầy, để tỏ ra mọi điều cao trọng.'),
(10884, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 17, 20, 'OT', 'Đức Giê-hô-va, không ai giống như Ngài, và chẳng có thần nào ngoài Ngài, theo mọi điều chúng tôi đã nghe bằng tai mình.'),
(10885, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 17, 21, 'OT', 'Và dân nào trên đất giống như dân Ngài, hỡi Y-sơ-ra-ên, một dân duy nhất, mà Đức Chúa Trời đã đi cứu chuộc để làm dân riêng cho Ngài, để làm cho Ngài danh tiếng lớn lao và oai nghiêm, và để đuổi các dân tộc ra khỏi trước mặt dân Ngài mà Ngài đã cứu chuộc khỏi Ai-cập?'),
(10886, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 17, 22, 'OT', 'Ngươi đã khiến cho dân Y-sơ-ra-ên trở thành dân thuộc về chính Ngươi đời đời; và chính Ngươi, Đức Giê-hô-va, đã trở nên Đức Chúa Trời của họ.'),
(10887, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 17, 23, 'OT', 'Bây giờ, lạy Đức Giê-hô-va, xin làm cho lời mà Ngài đã phán về đầy tớ Ngài và về nhà người được vững chắc đến đời đời, và xin làm theo điều mà Ngài đã nói.'),
(10888, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 17, 24, 'OT', 'Xin hãy lập định điều đó, để danh Ngài được tôn vinh đời đời, và người ta sẽ nói: Đức Giê-hô-va vạn quân là Đức Chúa Trời của Ít-ra-en, là Đức Chúa Trời cho Ít-ra-en; và nhà Đa-vít, tôi tớ Ngài, sẽ được lập vững chắc trước mặt Ngài.'),
(10889, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 17, 25, 'OT', 'Vì chính Ngài là Đức Chúa Trời của tôi, Ngài đã mở tai tôi tớ Ngài, hứa sẽ xây cho tôi tớ Ngài một ngôi nhà; nên tôi tớ Ngài đã mạnh dạn cầu nguyện trước mặt Ngài.'),
(10890, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 17, 26, 'OT', 'Và bây giờ, Đức Giê-hô-va, chính Ngài là Đức Chúa Trời, và Ngài đã phán hứa điều thiện này cho tôi tớ Ngài:'),
(10891, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 17, 27, 'OT', 'Bây giờ, xin Ngài vui lòng ban phước cho nhà của đầy tớ Ngài, để nó ở trước mặt Ngài mãi mãi; vì chính Ngài, Đức Giê-hô-va, đã ban phước, nên nhà ấy sẽ được phước đời đời.'),
(10892, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 18, 1, 'OT', 'Sau những việc ấy, Đa-vít đánh người Phi-li-tin, khuất phục họ, và lấy được Gat cùng các thị trấn thuộc về nó khỏi tay người Phi-li-tin.'),
(10893, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 18, 2, 'OT', 'Người đánh Mô-áp, và người Mô-áp trở thành tôi tớ của Đa-vít, dâng lễ vật.'),
(10894, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 18, 3, 'OT', 'Đa-vít đánh A-ha-đéc-xe, vua nước Xô-ba, khi người đi để củng cố quyền cai trị tại vùng Ha-mát, gần sông Ơ-phơ-rát.'),
(10895, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 18, 4, 'OT', 'Đa-vít bắt được từ hắn một ngàn xe, bảy ngàn kỵ binh và hai mươi ngàn bộ binh; rồi Đa-vít cản trở tất cả các xe, chỉ để lại một trăm xe.'),
(10896, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 18, 5, 'OT', 'Khi người A-ram ở Đam-xéc đến giúp Hách-đa-đơ-xe, vua Xô-ba, thì Đa-vít đánh bại người A-ram, giết hai mươi hai ngàn người.'),
(10897, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 18, 6, 'OT', 'Đa-vít đặt quân đồn trú tại A-ram Đa-mách; và người A-ram trở thành các đầy tớ phục vụ Đa-vít, dâng cống vật. Đức Giê-hô-va phù hộ Đa-vít trong mọi nơi người đi đến.'),
(10898, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 18, 7, 'OT', 'Đa-vít lấy các khiên bằng vàng vốn thuộc các đầy tớ của Ha-đa-đe-xe, và mang chúng về Giê-ru-sa-lem.'),
(10899, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 18, 8, 'OT', 'Từ các thành Típ-hát và Chun, những thành của Hã-đa-xe, Đa-vít lấy được rất nhiều đồng, mà của đó Sa-lô-môn đã làm biển đồng, các trụ và các đồ dùng bằng đồng.'),
(10900, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 18, 9, 'OT', 'Khi To-ú, vua của Ha-mát, nghe tin Đa-vít đã đánh bại toàn bộ đạo quân của Hã-đa-xe, vua Xô-ba,'),
(10901, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 18, 10, 'OT', 'Ông sai Ha-đô-ram, con trai mình, đến cùng vua Đa-vít, để hỏi thăm sức khỏe và chúc phước cho ông, vì ông đã chiến đấu với Ha-đa-đe-xe và đánh bại hắn; bởi vì Ha-đa-đe-xe vốn là kẻ thường gây chiến tranh với ông; và ông mang theo mọi thứ đồ dùng bằng vàng, bạc và đồng.'),
(10902, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 18, 11, 'OT', 'Vua Đa-vít cũng dâng những vật ấy riêng ra cho Đức Giê-hô-va, cùng với bạc và vàng mà người lấy được từ mọi dân tộc, từ Ê-đôm, Mô-áp, con cái Am-môn, người Phi-li-tin, và A-ma-léc.'),
(10903, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 18, 12, 'OT', 'Ab-sai, con trai của Xê-ru-i-a, đã đánh giết người Ê-đôm trong Thung lũng Muối mười tám ngàn người.'),
(10904, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 18, 13, 'OT', 'Ông đặt các đội quân canh giữ trong Ê-đôm; và toàn thể người Ê-đôm đều trở thành đầy tớ của Đa-vít. Đức Giê-hô-va phù hộ Đa-vít trong mọi nơi ông đi đến.'),
(10905, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 18, 14, 'OT', 'Vậy Đa-vít trị vì trên toàn thể Y-sơ-ra-ên, và ông thi hành sự xét xử và sự công bình cho toàn thể dân sự mình.'),
(10906, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 18, 15, 'OT', 'Jo-áp, con trai của Xê-ru-gia, làm tổng chỉ huy đạo quân; Giô-sa-phát, con trai của A-hi-lút, làm quan sử ký.'),
(10907, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 18, 16, 'OT', 'Và Xa-đốc, con trai của A-hi-túp, và A-bi-mê-léc, con trai của A-bi-a-tha, làm thầy tế lễ; và Sa-vu-sa làm thư ký.'),
(10908, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 18, 17, 'OT', 'Bê-nai-a, con trai của Giô-ya-đa, làm quan thống quản các người Cê-thê và các người Phê-lê-thê; các con trai của Đa-vít giữ các chức quyền cao cấp bên cạnh vua.'),
(10909, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 19, 1, 'OT', 'Sau việc ấy, Na-ha-sát vua con cái Am-môn qua đời, và con trai người lên ngôi kế vị người.'),
(10910, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 19, 2, 'OT', 'Đa-vít nói: "Ta sẽ làm ơn cho Ha-nun, con trai của Na-hách, vì cha người đã làm ơn cho ta." Vậy Đa-vít sai các sứ giả đi an ủi người về việc cha người qua đời. Các đầy tớ của Đa-vít đến xứ con cái Am-môn, đến cùng Ha-nun để an ủi người.'),
(10911, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 19, 3, 'OT', 'Các quan trưởng của con cái Amôn nói với Ha-nun: "Đa-vít tôn kính cha ngươi trong mắt ngươi sao, mà người sai những kẻ an ủi đến cho ngươi? Các đầy tớ người đến cùng ngươi há chẳng phải để dò xét, lật đổ và do thám xứ sở sao?"'),
(10912, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 19, 4, 'OT', 'Ha-nun bắt các đầy tớ của Đa-vít, cạo râu họ, cắt áo họ đến ngang lưng, rồi đuổi họ đi.'),
(10913, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 19, 5, 'OT', 'Họ đi và thuật lại cho Đa-vít biết về những người bị đối xử như thế nào. Vua sai người đi đón họ, vì những người ấy rất hổ thẹn. Vua nói: "Hãy ở lại Giê-ri-cô cho đến khi râu các ngươi mọc dài ra, rồi hãy trở về."'),
(10914, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 19, 6, 'OT', 'Khi con cái Amôn thấy mình đã làm cho Đa-vít ghét bỏ, thì Ha-nun và con cái Amôn sai mang một ngàn kikar bạc đi mướn xe và kỵ binh từ A-ram Na-ha-rim, từ A-ram Ma-a-ca và từ Xô-ba.'),
(10915, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 19, 7, 'OT', 'Họ đã thuê ba mươi hai ngàn xe chiến, cùng với vua Ma-cha-ca và dân người; họ đến và đóng trại trước Ma-đê-ba. Con cái Am-môn cũng tập hợp từ các thành mình và đến để giao chiến.'),
(10916, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 19, 8, 'OT', 'Đa-vít nghe tin ấy, liền sai Giô-áp và toàn thể đạo quân các dũng sĩ đi.'),
(10917, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 19, 9, 'OT', 'Các con trai của Am-môn đi ra, bày trận chiến trước cửa thành; còn các vua đã đến thì ở riêng một chỗ ngoài đồng.'),
(10918, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 19, 10, 'OT', 'Khi Giô-áp thấy cuộc chiến đã giáp mặt mình từ phía trước và phía sau, ông bèn chọn tất cả những người tinh nhuệ trong Ít-ra-en và bố trí họ để đối đầu với người A-ram.'),
(10919, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 19, 11, 'OT', 'Phần còn lại của dân chúng, ông giao vào tay Ab-sai, anh ông; và họ sắp hàng đối đầu với con cái của Am-môn.'),
(10920, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 19, 12, 'OT', 'Rồi ông nói: Nếu người Syri đánh thắng ta, ngươi sẽ đến giúp ta; nhưng nếu con cái Am-môn đánh thắng ngươi, ta sẽ đến giúp ngươi.'),
(10921, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 19, 13, 'OT', 'Hãy can đảm, và chúng ta hãy mạnh mẽ cho dân ta và các thành của Đức Chúa Trời chúng ta; còn Đức Giê-hô-va sẽ làm điều tốt đẹp theo mắt Ngài.'),
(10922, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 19, 14, 'OT', 'Vậy, Yo-áp và dân sự đi cùng ông tiến đến gần người Sy-ria để giao chiến; nhưng họ đã chạy trốn khỏi mặt ông.'),
(10923, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 19, 15, 'OT', 'Khi con cái Am-môn thấy quân Sy-ri đã bỏ chạy, thì chính họ cũng chạy trốn trước mặt A-bi-sai, anh em người ấy, và vào thành. Rồi Giô-áp trở về Giê-ru-sa-lem.'),
(10924, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 19, 16, 'OT', 'Khi người A-ram thấy mình bị đánh bại trước mặt Ít-ra-en, thì họ sai các sứ giả đi và đưa các quân A-ram từ phía bên kia sông sang; còn Sô-phách, chỉ huy trưởng đạo quân của Ha-đa-rết, thì đi trước họ.'),
(10925, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 19, 17, 'OT', 'Và người ta báo cho Đa-vít biết, thì ông tập hợp toàn thể Ít-ra-en, băng qua sông Giô-đanh, đến gặp chúng, và triển khai đội hình đối phó với chúng. Đa-vít cũng triển khai đội hình nghênh chiến với người Sy-ria, và chúng giao chiến với ông.'),
(10926, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 19, 18, 'OT', 'Người Sy-ri chạy trốn khỏi mặt Ít-ra-en; và Đa-vít giết của người Sy-ri bảy ngàn xe chiến, bốn mươi ngàn bộ binh, và giết Sô-phách, quan tổng chỉ huy đạo quân.'),
(10927, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 19, 19, 'OT', 'Khi các tôi tớ của Hadadezer thấy mình bị đánh bại trước mặt Y-sơ-ra-ên, thì họ lập hòa ước với Đa-vít và phục vụ người; và người ta không còn giúp các con trai của Am-môn nữa.'),
(10928, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 20, 1, 'OT', 'Sang năm mới, vào thời các vua ra đi chinh chiến, Giô-áp dẫn quân đội ra, làm bại hoại đất nước của con cái Am-môn, rồi tiến đến vây hãm Ráp-ba. Nhưng Đa-vít vẫn ở lại Giê-ru-sa-lem. Giô-áp đánh Ráp-ba và phá hủy thành ấy.'),
(10929, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 20, 2, 'OT', 'Đa-vít lấy mão vương của vua chúng từ trên đầu người ấy, và thấy nó nặng một ta-lâng vàng, lại có các viên đá quý; và mão ấy được đặt trên đầu Đa-vít. Người cũng mang ra khỏi thành rất nhiều chiến lợi phẩm.'),
(10930, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 20, 3, 'OT', 'Và người đã dẫn ra dân cư ở đó, rồi bắt họ đi ngang qua cưa sắt, qua các lưỡi cày sắt và qua rìu. Đa-vít đã đối xử như vậy với tất cả các thành phố của con cái Amôn. Sau đó Đa-vít và toàn thể dân chúng trở về Giê-ru-sa-lem.'),
(10931, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 20, 4, 'OT', 'Sau những việc ấy, có cuộc chiến xảy ra tại Gezer với người Phi-li-tin; bấy giờ Síp-ba-khai người Hút-sa-thít đã đánh giết Xi-ppai, thuộc dòng dõi của người Rê-pha-im; và chúng bị khuất phục.'),
(10932, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 20, 5, 'OT', 'Có cuộc chiến nữa với người Phi-li-tin; và Ê-lha-nan, con trai của Gia-ir, giết La-hmi, anh của Ga-li-át người Ga-thi, còn cây giáo của người ấy thì như cây thoi của thợ dệt.'),
(10933, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 20, 6, 'OT', 'Lại xảy ra chiến tranh tại Gat, ở đó có một người từ dòng dõi Râ-pha, ngón tay và ngón chân của người ấy mỗi bên sáu cái, tổng cộng hai mươi bốn; và người ấy cũng là con trai của Râ-pha.'),
(10934, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 20, 7, 'OT', 'Nhưng khi người ấy sỉ nhục Ít-ra-en, thì Giô-na-than, con trai của Si-mê-a, anh trai của Đa-vít, đã đánh và giết hắn.'),
(10935, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 20, 8, 'OT', 'Bốn người này sinh ra cho người Râ-pha tại Gat; và họ ngã xuống tay Đa-vít và tay các đầy tớ người.'),
(10936, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 21, 1, 'OT', 'Sa-tan đứng lên chống lại Ít-ra-en, và xúi giục Đa-vít đếm số dân Ít-ra-en.'),
(10937, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 21, 2, 'OT', 'Đa-vít nói với Giô-áp và các quan trưởng của dân: "Hãy đi đếm dân số Y-sơ-ra-ên từ Bê-er-Sê-ba cho đến Đan, rồi mang số đó đến cho tôi, để tôi biết được số lượng của họ."'),
(10938, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 21, 3, 'OT', 'Ông Yo-áp thưa: "Cầu xin Đức Giê-hô-va khiến dân sự của Ngài đông hơn hiện tại gấp trăm lần. Nhưng thưa chủ tôi là vua, há chẳng phải tất cả họ đều là đầy tớ của chủ tôi sao? Vậy tại sao chủ tôi lại đòi điều này? Tại sao điều đó sẽ trở thành tội lỗi cho Ít-ra-en?"'),
(10939, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 21, 4, 'OT', 'Dù vậy, lời vua vẫn quyết áp đặt đối với Yo-áp; nên Yo-áp ra đi, đi khắp mọi nơi trong toàn thể Y-sơ-ra-ên, rồi trở về Giê-ru-sa-lem.'),
(10940, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 21, 5, 'OT', 'Và Yo-áp dâng số người được kiểm tra cho Đa-vít. Toàn thể Y-sơ-ra-ên có một ngàn ngàn và một trăm ngàn người cầm gươm; còn Giu-đa có bốn trăm bảy mươi ngàn người cầm gươm.'),
(10941, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 21, 6, 'OT', 'Lê-vi và Bên-gia-min, ông không tính trong số họ, vì lời vua khiến cho Giô-áp ghét bỏ.'),
(10942, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 21, 7, 'OT', 'Điều này làm cho Đức Chúa Trời tức giận, nên Ngài giáng họa trên Y-sơ-ra-ên.'),
(10943, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 21, 8, 'OT', 'Và Đa-vít nói với Đức Chúa Trời: "Tôi đã phạm tội rất nặng khi làm điều này; vậy bây giờ, xin hãy tha thứ tội lỗi của đầy tớ Ngài, vì tôi đã hành động cách dại dột quá đỗi."'),
(10944, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 21, 9, 'OT', 'Đức Giê-hô-va phán cùng Gát, người thấy của Đa-vít, rằng:'),
(10945, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 21, 10, 'OT', 'Hãy đi và nói với Đa-vít rằng: Đức Giê-hô-va phán như vầy: Ta đặt trước mặt ngươi ba điều; hãy chọn một điều trong số đó, để Ta làm cho ngươi.'),
(10946, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 21, 11, 'OT', 'Gad đến cùng Đa-vít và nói với ông: "Đức Giê-hô-va phán như vầy: Hãy chọn lấy điều ngươi muốn."'),
(10947, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 21, 12, 'OT', 'Hãy chọn một trong ba điều này: hoặc ba năm đói kém; hoặc ba tháng bị tiêu diệt bởi các kẻ thù của ngươi, khiến cho gươm của kẻ thù ngươi đuổi theo ngươi; hoặc ba ngày gươm của Đức Giê-hô-va, tức là ôn dịch trong đất, và thiên sứ của Đức Giê-hô-va hủy diệt khắp các vùng đất của Y-sơ-ra-ên. Bây giờ hãy xem xét, ta phải trả lời điều gì với Đấng đã sai ta mang lời nầy đến.'),
(10948, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 21, 13, 'OT', 'Đa-vít nói với Gát: "Tôi đang gặp khốn khổ lớn. Xin để tôi sa vào tay của Đức Giê-hô-va, vì lòng thương xót của Ngài rất lớn; nhưng xin đừng để tôi sa vào tay loài người."'),
(10949, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 21, 14, 'OT', 'Đức Giê-hô-va giáng ôn dịch trên Ít-ra-en; và có bảy mươi ngàn người Ít-ra-en ngã gục.'),
(10950, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 21, 15, 'OT', 'Đức Chúa Trời sai một thiên sứ đến Giê-ru-sa-lem để hủy diệt thành ấy; và khi thiên sứ đang hủy diệt, thì Đức Giê-hô-va nhìn thấy và cảm thương trước điều dữ đó, nên phán cùng thiên sứ đang hủy diệt rằng: "Đủ rồi, bây giờ hãy dừng tay lại." Bấy giờ thiên sứ của Đức Giê-hô-va đang đứng gần sân đập lúa của A-rơ-nan người Y-bu-si.'),
(10951, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 21, 16, 'OT', 'Đa-vít ngước mắt lên và thấy thiên sứ của Đức Giê-hô-va đang đứng giữa đất và trời, tay cầm gươm tuốt trần giơ ra trên Giê-ru-sa-lem. Đa-vít và các trưởng lão mặc áo bằng vải thô sấp mặt xuống đất.'),
(10952, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 21, 17, 'OT', 'Đa-vít nói với Đức Chúa Trời: "Chẳng phải tôi đã ra lệnh cho dân chúng được điểm số sao? Chính tôi là người đã phạm tội và làm điều ác; còn những con chiên này thì đã làm gì? Xin tay Đức Giê-hô-va Đức Chúa Trời của tôi hãy chống lại tôi và nhà cha tôi, chứ đừng chống lại dân Ngài để gây ra tai họa."'),
(10953, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 21, 18, 'OT', 'Thiên sứ của Đức Giê-hô-va bảo Gad nói với Đa-vít rằng: "Đa-vít hãy đi lên lập một bàn thờ cho Đức Giê-hô-va tại sân đập lúa của A-rơ-nan người Y-bu-si."'),
(10954, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 21, 19, 'OT', 'Đa-vít đi lên theo lời của Gát, người đã nói nhân danh Đức Giê-hô-va.'),
(10955, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 21, 20, 'OT', 'Ông A-rơ-nan quay lại, thấy thiên sứ; bốn người con trai của ông cùng ông đang trốn giấu. Còn A-rơ-nan thì đang đập lúa mì.'),
(10956, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 21, 21, 'OT', 'Đa-vít đi đến chỗ A-rơ-nan; A-rơ-nan nhìn, thấy Đa-vít, bèn đi ra khỏi nơi đập lúa, và sấp mặt xuống đất, cúi lạy Đa-vít.'),
(10957, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 21, 22, 'OT', 'Đa-vít nói với A-rơ-nan: "Hãy nhường cho tôi chỗ sân đập lúa này, để tôi xây một bàn thờ cho Đức Giê-hô-va; hãy bán nó cho tôi với giá đầy đủ, hầu cho tai họa dứt khỏi dân chúng."'),
(10958, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 21, 23, 'OT', 'A-ram nói với Đa-vít: "Xin ngài hãy nhận lấy; và xin chúa tôi là vua hãy làm điều tốt lành theo ý ngài. Này, tôi xin dâng bò để làm của lễ thiêu, các cối xay lúa để làm củi, và lúa mì để làm lễ chay; tôi dâng tất cả."'),
(10959, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 21, 24, 'OT', 'Vua Đa-vít nói với A-rơ-nan: "Không, nhưng ta sẽ mua thật bằng tiền đầy đủ; vì ta không thể lấy cái thuộc về ngươi mà dâng cho Đức Giê-hô-va, hay dâng của lễ thiêu không tốn phí."'),
(10960, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 21, 25, 'OT', 'Vua Đa-vít đưa cho A-rơ-nan tại nơi ấy sáu trăm siếc-lem vàng theo trọng lượng.'),
(10961, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 21, 26, 'OT', 'Đa-vít xây dựng một bàn thờ cho Đức Giê-hô-va tại đó, dâng các lễ thiêu và lễ thù ân; người kêu cầu Đức Giê-hô-va, và Ngài đáp lời người từ trời bằng lửa trên bàn thờ lễ thiêu.'),
(10962, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 21, 27, 'OT', 'Đức Giê-hô-va phán cùng thiên sứ; và người bèn tra gươm trở lại vào bao.'),
(10963, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 21, 28, 'OT', 'Vào lúc ấy, khi Đa-vít thấy Đức Giê-hô-va đã nhậm lời người tại nơi đập lúa của A-rơ-nan, người dân Giê-bu-xít, thì người dâng của lễ thiêu tại đó.'),
(10964, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 21, 29, 'OT', 'Nhưng hội quán của Đức Giê-hô-va mà Môi-se đã làm trong đồng vắng, và bàn thờ của lễ thiêu, thì lúc ấy ở nơi cao tại Ghi-bê-ôn.'),
(10965, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 21, 30, 'OT', 'Nhưng Đa-vít không thể đi đến trước hòm đó để cầu hỏi Đức Chúa Trời, vì người sợ hãi trước lưỡi gươm của thiên sứ Đức Giê-hô-va.'),
(10966, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 22, 1, 'OT', 'Đa-vít nói: "Đây là đền thờ của Đức Giê-hô-va Đức Chúa Trời, và đây là bàn thờ dâng của lễ thiêu cho Ít-ra-en."'),
(10967, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 22, 2, 'OT', 'Đa-vít ra lệnh tập trung những người ngoại bang đang sống trong đất Y-sơ-ra-ên, rồi sai thợ đục đá để đẽo những tảng đá xẻ, nhằm xây cất nhà của Đức Chúa Trời.'),
(10968, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 22, 3, 'OT', 'Đa-vít dự bị sắt rất nhiều để làm đinh cho các cửa cổng và các mối nối, và đồng rất nhiều đến nỗi không thể cân đong được.'),
(10969, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 22, 4, 'OT', 'Gỗ tùng rất nhiều vô số, vì người Xi-đôn và người Tírơ đã mang đến cho Đa-vít rất nhiều gỗ tùng.'),
(10970, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 22, 5, 'OT', 'Đa-vít nói: "Sa-lô-môn, con trai ta, còn trẻ và yếu đuối, mà đền thờ để xây cho Đức Giê-hô-va phải thật lớn lao, nổi tiếng và vinh hiển khắp các nước; vậy tôi sẽ chuẩn bị sẵn sàng cho nó." Nên Đa-vít đã chuẩn bị rất nhiều trước khi ông qua đời.'),
(10971, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 22, 6, 'OT', 'Người gọi cho Sa-lô-môn, con trai mình, và dặn người phải xây một ngôi nhà cho Đức Giê-hô-va, Đức Chúa Trời của Ít-ra-en.'),
(10972, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 22, 7, 'OT', 'Đa-vít nói với Sa-lô-môn, hỡi con trai ta, tôi đã có ý định trong lòng mình là sẽ xây một ngôi nhà cho danh của Đức Giê-hô-va, Đức Chúa Trời tôi.'),
(10973, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 22, 8, 'OT', 'Nhưng có lời của Đức Giê-hô-va phán cùng ta rằng: Ngươi đã đổ nhiều huyết và làm những cuộc chiến lớn; ngươi sẽ không xây một ngôi nhà cho danh ta, vì ngươi đã đổ nhiều huyết trên đất trước mặt ta.'),
(10974, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 22, 9, 'OT', 'Nầy, một đứa con trai sẽ sinh ra cho ngươi, nó sẽ là một người đầy an nghỉ; ta sẽ ban cho nó được an nghỉ khỏi mọi kẻ thù nó ở khắp bốn phía; vì tên nó sẽ là Sa-lô-môn, và ta sẽ ban sự bình an và yên ổn cho Ít-ra-ên trong các ngày đời nó.'),
(10975, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 22, 10, 'OT', 'Người ấy sẽ xây một ngôi nhà cho danh Ta, và Người ấy sẽ là con trai Ta, Ta sẽ là cha Người ấy, và Ta sẽ thiết lập ngôi vương quyền của người ấy trên Y-sơ-ra-ên đến mãi mãi.'),
(10976, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 22, 11, 'OT', 'Bây giờ, hỡi con trai ta, nguyện Đức Giê-hô-va ở cùng con; con sẽ thành công và xây cất đền thờ cho Đức Chúa Trời của con, như điều Ngài đã phán về con.'),
(10977, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 22, 12, 'OT', 'Chỉ nguyện Đức Giê-hô-va ban cho con sự thông sáng và hiểu biết, và giao trách nhiệm cho con quản lý Ít-ra-en, để con giữ luật pháp của Đức Chúa Trời con là Đức Giê-hô-va.'),
(10978, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 22, 13, 'OT', 'Vậy ngươi sẽ hưng vượng, nếu ngươi chăm giữ làm theo các luật lệ và các điều lệ mà Đức Giê-hô-va đã truyền cho Môi-se về Y-sơ-ra-ên. Hãy mạnh mẽ và can đảm, chớ sợ hãi, cũng đừng kinh hãi.'),
(10979, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 22, 14, 'OT', 'Nầy, ta đã chịu nhiều gian truân mà chuẩn bị cho đền thờ của Đức Giê-hô-va một trăm ngàn kikar vàng, một ngàn ngàn kikar bạc; còn đồng và sắt thì không thể cân được, vì rất nhiều. Ta cũng đã chuẩn bị gỗ và đá, và ngươi có thể bổ sung thêm vào đó.'),
(10980, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 22, 15, 'OT', 'Và ngươi có nhiều thợ khéo ở cùng, những người đẽo đá và thợ mộc, cùng mọi người khôn ngoan trong mọi công việc.'),
(10981, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 22, 16, 'OT', 'Vàng, bạc, đồng và sắt thì vô số. Hãy chổi dậy và làm, và Đức Giê-hô-va sẽ ở cùng ngươi.'),
(10982, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 22, 17, 'OT', 'Đa-vít truyền lệnh cho tất cả các quan trưởng của Ít-ra-en giúp Xô-lô-môn, con trai ông.'),
(10983, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 22, 18, 'OT', 'Đức Giê-hô-va Đức Chúa Trời các ngươi há chẳng ở cùng các ngươi sao? Ngài há chẳng ban cho các ngươi sự yên nghỉ về mọi phía sao? Vì Ngài đã trao những người ở trong xứ nầy vào tay ta, và đất nầy đã bị chinh phục trước mặt Đức Giê-hô-va và trước mặt dân Ngài.'),
(10984, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 22, 19, 'OT', 'Bây giờ, hãy đặt trọn tấm lòng và linh hồn các ngươi để tìm kiếm Đức Giê-hô-va Đức Chúa Trời các ngươi; hãy chỗi dậy và xây cất đền thánh của Đức Giê-hô-va Đức Chúa Trời, để rước rương giao ước của Đức Giê-hô-va và các khí cụ thánh của Đức Chúa Trời vào ngôi nhà sẽ được xây cho danh Đức Giê-hô-va.'),
(10985, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 23, 1, 'OT', 'Đa-vít đã về già, đầy đủ tuổi đời, bèn lập Sa-lô-môn, con trai mình, làm vua cai trị trên Ít-ra-en.'),
(10986, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 23, 2, 'OT', 'Và ông tập hợp tất cả các quan trưởng của Y-sơ-ra-ên, các thầy tế lễ và những người Lê-vi.'),
(10987, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 23, 3, 'OT', 'Người Lê-vi được điểm danh từ tuổi ba mươi trở lên; và số người được điểm danh theo từng nhóm, từng người một, là ba mươi tám ngàn.'),
(10988, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 23, 4, 'OT', 'Trong số đó, hai mươi bốn ngàn người sẽ chỉ huy công việc trong đền thờ của Đức Giê-hô-va; và sáu ngàn người làm viên chức và quan xét:'),
(10989, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 23, 5, 'OT', 'Bốn ngàn người làm kẻ giữ cửa, và bốn ngàn người ca ngợi Đức Giê-hô-va bằng các nhạc cụ mà tôi đã làm để ca ngợi Ngài.'),
(10990, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 23, 6, 'OT', 'Đa-vít chia họ ra thành các nhóm theo các con trai của Lê-vi, là Ghẹt-sôn, Kê-hát và Mê-ra-ri.'),
(10991, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 23, 7, 'OT', 'Thuộc về người Ghẹt-sôn, là La-a-đan và Si-mê-i.'),
(10992, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 23, 8, 'OT', 'Các con trai của La-đan; người đứng đầu là Giê-hi-ên, Xê-tham và Giô-ên, ba người.'),
(10993, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 23, 9, 'OT', 'Con cái của Si-mê-i là Shelomith, Haziel và Haran, ba người này. Những người này là các trưởng tộc của Laadan.'),
(10994, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 23, 10, 'OT', 'Con trai của Sê-mi là Gia-hát, Xi-na, Giê-u và Bê-ri-a. Bốn người này là con trai của Sê-mi.'),
(10995, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 23, 11, 'OT', 'Gia-hát là người đứng đầu, Xi-xa là người thứ hai; còn Giêu-s và Bê-ri-a thì không có nhiều con trai, nên họ được tính chung vào một tổ phụ theo nhà cha ông của mình.'),
(10996, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 23, 12, 'OT', 'Con cái của Kê-hát: Am-ram, Ít-ha, Hếp-rôn và Út-xi-ên, bốn người.'),
(10997, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 23, 13, 'OT', 'Con trai của Am-ram là A-ha-ron và Môi-se. A-ha-ron đã được biệt riêng ra để biệt riêng những vật chí thánh, người và các con trai người đến đời đời, để dâng hương trước mặt Đức Giê-hô-va, hầu việc Ngài và chúc phước bằng danh Ngài đến đời đời.'),
(10998, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 23, 14, 'OT', 'Về Môi-se, người của Đức Chúa Trời, các con trai người sẽ được gọi theo chi phái Lê-vi.'),
(10999, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 23, 15, 'OT', 'Con trai của Môi-se là Ghẹt-sôm và Ê-li-ê-xe.'),
(11000, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 23, 16, 'OT', 'Con trai của Ghẹt-sô-mơ là Sê-bu-ên, người làm đầu.'),
(11001, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 23, 17, 'OT', 'Con trai của Ê-li-ê-xe là Rê-háp-gia, người đứng đầu; và Ê-li-ê-xe không có con trai nào khác; nhưng con cháu của Rê-háp-gia thì rất đông.'),
(11002, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 23, 18, 'OT', 'Con trai của Ích-ha là Sê-lô-mít, người đứng đầu.'),
(11003, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 23, 19, 'OT', 'Con trai của Hếp-rôn: Giê-ri-a là người đầu, A-ma-ri-a là người thứ hai, Gia-ha-xi-ên là người thứ ba, và Giê-ka-meam là người thứ tư.'),
(11004, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 23, 20, 'OT', 'Con trai của Út-xi-ên: Mi-ca là người đầu, và Ích-sai-gia là người thứ hai.'),
(11005, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 23, 21, 'OT', 'Con các đời của Mê-ra-ri là Ma-hli và Mu-si. Con các đời của Ma-hli là Ê-lê-a-xa và Kích.'),
(11006, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 23, 22, 'OT', 'Ê-lê-a-xa qua đời, và không có con trai, chỉ có các con gái; và các anh em họ, con trai của Kít, đã cưới các con gái ấy.'),
(11007, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 23, 23, 'OT', 'Các con trai của Mushi: Mahli, Eder và Giê-rê-mốt, ba người.'),
(11008, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 23, 24, 'OT', 'Đây là các con trai của Lê-vi theo các nhà tổ phụ của họ, các trưởng tộc được kiểm tra theo số tên theo đầu người, làm công việc phục vụ nhà Đức Giê-hô-va, từ con trai hai mươi tuổi trở lên.'),
(11009, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 23, 25, 'OT', 'Vì Đa-vít nói rằng: Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en đã ban cho dân sự Ngài được an nghỉ, và Ngài ngự tại Giê-ru-sa-lem mãi mãi.'),
(11010, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 23, 26, 'OT', 'Cũng vậy, người Lê-vi sẽ không còn phải mang gánh nặng về hội mạc và mọi đồ dùng của nó để làm công việc cho hội mạc nữa.'),
(11011, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 23, 27, 'OT', 'Vì theo lời cuối cùng của Đa-vít, người ta đã điểm số các con trai của Lê-vi từ hai mươi tuổi trở lên.'),
(11012, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 23, 28, 'OT', 'Vì chức vụ của họ là giúp các con trai A-ha-ron lo việc phục vụ trong đền thờ của Đức Giê-hô-va, gồm các hành lang, các phòng, việc thanh tẩy mọi vật thánh, và các công việc phục vụ trong đền thờ Đức Chúa Trời.'),
(11013, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 23, 29, 'OT', 'và vì bánh triển bày, vì bột mịn dùng làm lễ vật chay, vì bánh không men dẹt, vì vật chiên trong chảo, vì vật nướng trong lò, và vì mọi thứ định lượng và kích thước.'),
(11014, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 23, 30, 'OT', 'Và đứng vào buổi sáng sớm để cảm tạ và ca ngợi Đức Giê-hô-va, và cũng vậy vào buổi chiều tối.'),
(11015, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 23, 31, 'OT', 'Và dâng mọi của lễ toàn thiêu cho Đức Giê-hô-va trong các ngày Sa-bát, các ngày trăng mới và các lễ hội định kỳ, theo số lượng và theo quy định dành cho họ, luôn luôn trước mặt Đức Giê-hô-va.'),
(11016, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 23, 32, 'OT', 'và họ phải giữ nhiệm vụ trông coi hội mạc, nhiệm vụ thánh địa, và nhiệm vụ các con trai A-ha-ron anh em mình, để thi hành công việc trong đền thờ Đức Giê-hô-va.'),
(11017, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 24, 1, 'OT', 'Các con trai của A-ha-ron được phân chia theo các nhóm của chúng. Các con trai của A-ha-ron là Na-đáp, A-bi-hu, Ê-lê-a-xa và Ít-ha-ma.'),
(11018, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 24, 2, 'OT', 'Na-đáp và A-bi-hu qua đời trước mặt cha mình, và không có con trai; nên Ê-lê-a-xa và Ít-ha-ma làm chức thầy tế lễ.'),
(11019, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 24, 3, 'OT', 'Đa-vít phân chia họ, gồm Xa-đốc thuộc con cháu Ê-lê-a-xa và A-hi-mê-léc thuộc con cháu Ít-ha-ma, theo chức vụ của họ trong công việc phục vụ.'),
(11020, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 24, 4, 'OT', 'Các con trai của Ê-lê-a-xa có nhiều người lãnh đạo hơn các con trai của Ít-ha-ma; nên họ chia ra: trong các con trai Ê-lê-a-xa có mười sáu người lãnh đạo theo các gia tộc của tổ tiên họ, còn trong các con trai Ít-ha-ma thì có tám người theo các gia tộc của tổ tiên họ.'),
(11021, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 24, 5, 'OT', 'Họ chia nhau bằng các thăm, người nầy với người khác; vì các quan trưởng thánh và các quan trưởng của Đức Chúa Trời đều là con cháu của Ê-lê-a-xa và con cháu của Ít-ha-ma.'),
(11022, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 24, 6, 'OT', 'Sê-ma-gia, con trai của Nết-xan-ên, người thầy ký thuộc về người Lê-vi, đã chép tên họ trước mặt vua, các quan trưởng, Xa-đốc thầy tế lễ, A-hi-mê-léc con trai của A-bi-a-tha, và các trưởng tộc của các thầy tế lễ và người Lê-vi; một chi họ được chọn cho Ê-lê-a-xa, và một chi họ được chọn cho Ít-ha-ma.'),
(11023, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 24, 7, 'OT', 'Lô đầu tiên thuộc về Giô-hoi-a-ríp, lô thứ hai thuộc về Giê-đa-i-a.'),
(11024, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 24, 8, 'OT', 'Người thứ ba thuộc về Ha-rim, người thứ tư thuộc về Xi-ô-rim.'),
(11025, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 24, 9, 'OT', 'Người thứ năm thuộc về Mal-khi-ya, người thứ sáu thuộc về Mi-ya-min.'),
(11026, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 24, 10, 'OT', 'Người thứ bảy thuộc về Hác-côts, người thứ tám thuộc về A-bi-gia.'),
(11027, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 24, 11, 'OT', 'Người thứ chín thuộc về Giê-su, người thứ mười thuộc về Sê-can-gia.'),
(11028, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 24, 12, 'OT', 'Phần thứ mười một thuộc về Ê-li-a-síp, phần thứ mười hai thuộc về Gia-kin.'),
(11029, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 24, 13, 'OT', 'Người thứ mười ba thuộc về Huppah, người thứ mười bốn thuộc về Jeshebeab.'),
(11030, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 24, 14, 'OT', 'Số thứ mười lăm là cho Bích-gát, số thứ mười sáu là cho Ít-ma.'),
(11031, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 24, 15, 'OT', 'Mười bảy cho Hê-xir, mười tám cho Ha-phi-xết.'),
(11032, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 24, 16, 'OT', 'Người thứ mười chín cho Phi-tha-hia, người thứ hai mươi cho Ê-xê-ki-ên.'),
(11033, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 24, 17, 'OT', 'Đối với Y-a-kin là người thứ hai mươi mốt, đối với Ga-mu-l là người thứ hai mươi hai.'),
(11034, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 24, 18, 'OT', 'Đức Giê-hô-va phân định phần thứ hai mươi ba cho Đê-la-i-a, phần thứ hai mươi tư cho Ma-a-xi-a.'),
(11035, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 24, 19, 'OT', 'Đây là những nhiệm vụ của họ trong việc phục vụ, để vào nhà Đức Giê-hô-va theo quy định của họ, dưới sự chỉ dẫn của A-ha-ron, cha họ, y như Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên đã truyền cho người.'),
(11036, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 24, 20, 'OT', 'Còn về các con trai Lêvi còn lại: về các con trai Am-ram, là Súp-ha-ên; về các con trai Súp-ha-ên, là Giê-đê-ia.'),
(11037, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 24, 21, 'OT', 'Về Rê-háp-gia: con trai của Rê-háp-gia, người đứng đầu là Ích-xi-a.'),
(11038, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 24, 22, 'OT', 'Thuộc về các Ích-ha-rít: Xê-lô-mốt; thuộc về các con trai của Xê-lô-mốt: Giácát.'),
(11039, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 24, 23, 'OT', 'Các con trai của Giê-ri-ya-hu: A-ma-ri-a-hu là người thứ hai, Gia-ha-xi-ên là người thứ ba, Giê-ca-meam là người thứ tư.'),
(11040, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 24, 24, 'OT', 'Con trai của U-xi-ên là Mi-ca; con trai của Mi-ca là Sa-mi-rơ.'),
(11041, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 24, 25, 'OT', 'Anh em của Míchah là Ích-si-gia; các con trai của Ích-si-gia là Xác-cha-ri.'),
(11042, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 24, 26, 'OT', 'Con trai của Mê-ra-ri là Ma-hô-li và Mu-si; con trai của Gia-a-xi-a, con trai ông ấy.'),
(11043, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 24, 27, 'OT', 'Con trai của Mê-ra-ri theo dòng họ của Gia-a-xi-a, con trai người, gồm Bê-nô, Sô-ham, Xa-cúc và Íp-ri.'),
(11044, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 24, 28, 'OT', 'Ma-hli sinh ra Ê-lê-a-xa, và người không có con trai.'),
(11045, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 24, 29, 'OT', 'Về Kích: các con trai của Kích là Giê-ra-ha-mên.'),
(11046, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 24, 30, 'OT', 'Và các con trai của Mushi: Mahli, Eder và Jerimoth. Đây là các con trai của người Lêvi theo các nhà họ hàng của tổ tiên họ.'),
(11047, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 24, 31, 'OT', 'Họ cũng bắt thăm như vậy, đối mặt với anh em mình, các con trai của A-ha-ron, trước mặt vua Đa-vít, Xa-đốc, A-hi-mê-léc và các tộc trưởng của các thầy tế lễ và người Lê-vi, tức là các tổ phụ trưởng đối mặt với các anh em trẻ tuổi hơn của mình.'),
(11048, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 25, 1, 'OT', 'Đa-vít và các quan trưởng quân đội phân biệt ra để phục vụ cho các con trai của A-sáp, Hi-man và Giê-đu-thun, những người nầy dùng đờn cầm, đờn sắt và chập chỏa mà nói tiên tri; và số người được phân công theo công việc của họ là:'),
(11049, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 25, 2, 'OT', 'Các con trai của A-sáp là Xác-cua, Giô-sép, Nết-a-ni-a và A-xa-rê-la; những người con trai của A-sáp phục vụ dưới sự hướng dẫn của A-sáp, và họ nói tiên tri theo sự chỉ dẫn của nhà vua.'),
(11050, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 25, 3, 'OT', 'Con trai của Giê-đu-thun: Ghê-đa-lia, Xê-ri, Ích-sa-gia, Ha-sa-bia, và Ma-ti-thia, tất cả sáu người, dưới sự hướng dẫn của cha mình là Giê-đu-thun, dùng đờn cầm mà nói tiên tri để ca ngợi và tạ ơn Đức Giê-hô-va.'),
(11051, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 25, 4, 'OT', 'Họ hàng của Hê-man: các con trai của Hê-man là Bu-ki-a-hu, Ma-tan-gia-hu, U-xi-ên, Sê-bu-ên, Vi-ri-mốt, Ha-nan-gia, Ha-na-ni, Ê-li-a-tha, Gít-đan-thi, và Rô-mam-thi, Ét-xe, Gia-sê-bê-ka-sa, Man-lo-thi, Hô-thir, Ma-ha-xi-ốt.'),
(11052, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 25, 5, 'OT', 'Tất cả những người nầy là con trai của Hê-man, người thấy của vua, theo các lời của Đức Chúa Trời, để nâng cao cái sừng. Đức Chúa Trời đã ban cho Hê-man mười bốn con trai và ba con gái.'),
(11053, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 25, 6, 'OT', 'Tất cả những người này đều dưới quyền của cha họ, phục vụ việc hát ca trong đền thờ của Đức Giê-hô-va, dùng chập chỏa, đờn lia và đờn cầm, để phục vụ trong đền thờ Đức Chúa Trời, theo lệnh của vua giao cho A-sáp, Giê-đu-thun và Hê-man.'),
(11054, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 25, 7, 'OT', 'Số lượng của họ cùng với anh em họ, những người được dạy dỗ về các bài ca cho Đức Giê-hô-va, tất cả những người thông hiểu, là hai trăm tám mươi tám người.'),
(11055, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 25, 8, 'OT', 'Họ bắt thăm, chức vụ đối với chức vụ, kẻ nhỏ cũng như người lớn, thầy cùng với môn sinh.'),
(11056, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 25, 9, 'OT', 'Lô đầu tiên được rút ra cho A-sáp, thuộc về Giô-sép; lô thứ hai thuộc về Ghê-đa-lia; chính ông cùng với anh em và các con trai của ông là mười hai người.'),
(11057, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 25, 10, 'OT', 'Người thứ ba là Zakur, các con trai ông, anh em ông, tổng cộng mười hai người.'),
(11058, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 25, 11, 'OT', 'Người thứ tư thuộc về Ít-xri; con trai và anh em của người, tất cả mười hai người.'),
(11059, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 25, 12, 'OT', 'Người thứ năm thuộc về Nết-a-ni-a; các con trai ông, anh em ông, gồm mười hai người.'),
(11060, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 25, 13, 'OT', 'Sáu là Búc-ki-a, các con trai và anh em người, tổng cộng mười hai người.'),
(11061, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 25, 14, 'OT', 'Người thứ bảy là Giê-xa-rê-la; các con trai ông và anh em ông gồm mười hai người.'),
(11062, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 25, 15, 'OT', 'Tám là Giê-sai-hu, các con trai ông, các anh em ông, tổng cộng mười hai người.'),
(11063, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 25, 16, 'OT', 'Chín là Mát-tha-ni-a; các con trai ông, các anh em ông, gồm mười hai người.'),
(11064, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 25, 17, 'OT', 'Người thứ mười là Si-mê-i; các con trai ông, anh em ông, gồm mười hai người.'),
(11065, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 25, 18, 'OT', 'Đời thứ mười một thuộc về A-xa-rên, gồm các con trai và anh em ông, tổng cộng mười hai người.'),
(11066, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 25, 19, 'OT', 'Mười hai người thuộc về Hát-xa-bia, các con trai ông, anh em ông, tất cả mười hai người.'),
(11067, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 25, 20, 'OT', 'Người thứ mười ba thuộc về Sô-ba-ên, các con trai ông, và anh em ông, tất cả mười hai người.'),
(11068, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 25, 21, 'OT', 'Người thứ mười bốn thuộc về Mattithia; các con trai ông, anh em ông, gồm mười hai người.'),
(11069, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 25, 22, 'OT', 'Người thứ mười lăm là Giê-rê-mốt, các con trai ông, và các anh em ông, tổng cộng mười hai người.'),
(11070, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 25, 23, 'OT', 'Người thứ mười sáu thuộc về Hananiah; các con trai ông, anh em ông, gồm mười hai người.'),
(11071, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 25, 24, 'OT', 'Người thứ mười bảy thuộc về Giô-xép-ka-xa; các con trai và anh em người là mười hai người.'),
(11072, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 25, 25, 'OT', 'Đoàn thứ mười tám thuộc về Ha-na-ni, các con trai ông và anh em ông, tổng cộng mười hai người.'),
(11073, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 25, 26, 'OT', 'Người thứ mười chín thuộc về Ma-lô-thi, các con trai và anh em người là mười hai người.'),
(11074, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 25, 27, 'OT', 'Người thứ hai mươi thuộc về Ê-li-a-tha; các con trai ông và các anh em ông, tất cả mười hai người.'),
(11075, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 25, 28, 'OT', 'Người thứ hai mươi mốt thuộc về Hô-thir, con trai và anh em người, tất cả mười hai người.'),
(11076, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 25, 29, 'OT', 'Người thứ hai mươi hai thuộc về Ghít-ha-li, con trai và anh em ông là mười hai người.'),
(11077, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 25, 30, 'OT', 'Đời thứ hai mươi ba thuộc về Mát-xi-ốt, gồm các con trai, anh em ông ấy, tổng cộng mười hai người.'),
(11078, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 25, 31, 'OT', 'Người thứ hai mươi tư thuộc về Rô-ma-thi-ê-xe; các con trai ông, anh em ông, gồm mười hai người.'),
(11079, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 26, 1, 'OT', 'Về các nhóm chia nhau làm nhiệm vụ của những người giữ cửa: thuộc dòng họ Kôrít là Mê-sê-lê-mia, con trai của Cô-rê, thuộc con cháu của A-sáp.'),
(11080, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 26, 2, 'OT', 'Và các con trai của Mê-sê-lê-mia là: Xa-cha-ri, con cả; Giê-đi-a-ên, con thứ hai; Xê-ba-đia, con thứ ba; và Giát-ni-ên, con thứ tư.'),
(11081, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 26, 3, 'OT', 'Ê-lam, người thứ năm; Giê-hô-chi-nan, người thứ sáu; Ê-li-ô-ên-nai, người thứ bảy.'),
(11082, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 26, 4, 'OT', 'Các con trai của Ô-bết-Ê-đôm là: Sê-ma-gia, con đầu lòng; Giô-hô-xa-bát, con thứ hai; Giô-ách, con thứ ba; Xa-các, con thứ tư; và Nết-an-ên, con thứ năm.'),
(11083, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 26, 5, 'OT', 'Ammiel người thứ sáu, Y-sa-ca người thứ bảy, Peulthai người thứ tám; vì Đức Chúa Trời đã ban phước cho ông.'),
(11084, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 26, 6, 'OT', 'Cũng vậy, các con trai sinh ra cho Sê-ma-gia, con trai ông, là những người cai trị trong nhà cha ông mình; vì họ là những người dũng cảm và mạnh mẽ.'),
(11085, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 26, 7, 'OT', 'Các con trai của Sê-ma-gia gồm A-tni, Rê-pha-ên, Óp-ết, Ên-xa-bát, các anh em người là những người tráng kiện, Ê-li-hu và Xê-ma-ki-a.'),
(11086, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 26, 8, 'OT', 'Tất cả những người này là con cháu của Ô-bết-Ê-đôm, họ cùng các con trai và anh em mình, mỗi người là người mạnh mẽ về sức lực để phục vụ; tất cả có sáu mươi hai người phục vụ Ô-bết-Ê-đôm.'),
(11087, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 26, 9, 'OT', 'Và Mê-sê-lê-mia có các con trai và anh em, những người trai tráng, tổng cộng mười tám người.'),
(11088, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 26, 10, 'OT', 'Hosah, thuộc con cháu Mê-ra-ri, có các con trai: Simri làm lãnh đạo, dù ông không phải con cả, nhưng cha ông đã đặt ông lên làm lãnh đạo.'),
(11089, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 26, 11, 'OT', 'Hinh-kia người thứ hai, Tê-ba-ly-a người thứ ba, Xa-cha-ri người thứ tư; tất cả các con trai và anh em của Hô-sa được mười ba người.'),
(11090, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 26, 12, 'OT', 'Theo các người nầy, có sự phân chia các nhóm giữ cửa, trong các trưởng tộc, mỗi nhóm canh giữ đối diện với anh em mình, để phục vụ trong đền thờ Đức Giê-hô-va.'),
(11091, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 26, 13, 'OT', 'Họ bắt thăm, cả người nhỏ lẫn người lớn, theo nhà các tổ phụ họ, cho từng cửa.'),
(11092, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 26, 14, 'OT', 'Đã bắt thăm về phía đông cho Sê-lê-mi-a. Còn Xa-cha-ri, con trai người, là người tư vấn khôn ngoan, thì bắt thăm; và thăm người trúng về phía bắc.'),
(11093, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 26, 15, 'OT', 'Đối với Ô-bết-đôm về hướng Nam, và các con trai người được giao nhà Asuppim.'),
(11094, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 26, 16, 'OT', 'Về hướng tây, được chỉ định cho các người thuộc về Súp-pim và Hô-sa, gần cổng Sát-lách, dọc theo con đường lên, canh giữ đối diện với canh giữ.'),
(11095, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 26, 17, 'OT', 'Về hướng đông có sáu người Lê-vi, về hướng bắc mỗi ngày bốn người, về hướng nam mỗi ngày bốn người, và về phía các nhà kho, mỗi phía hai người.'),
(11096, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 26, 18, 'OT', 'Tại Parbar về hướng tây, bốn người ở lối đi, và hai người tại Parbar.'),
(11097, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 26, 19, 'OT', 'Đây là các nhóm lính canh thuộc con trai của Kô-rê và con trai của Mê-ra-ri.'),
(11098, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 26, 20, 'OT', 'Về các người Lê-vi, A-hi-gia quản lý các kho tàng của nhà Đức Chúa Trời và các kho tàng để dành riêng cho những vật thánh.'),
(11099, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 26, 21, 'OT', 'Con trai của La-đan, con cháu của Ghẹt-suny, dòng họ trưởng của La-đan, người Ghẹt-suny, là Giê-hi-ên.'),
(11100, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 26, 22, 'OT', 'Con trai của Giê-hi-ên là Xết-tam và Giô-ên, anh em người, quản lý các kho tàng trong đền thờ Đức Giê-hô-va.'),
(11101, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 26, 23, 'OT', 'Của những người Am-ram, những người Yit-xhạt, những người Hếp-rôn, và những người Út-xi-ên.'),
(11102, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 26, 24, 'OT', 'Và Sê-bu-ên, con trai của Ghẹt-sôm, con trai của Môi-se, làm người quản lý các kho tàng.'),
(11103, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 26, 25, 'OT', 'Các anh em của người, thuộc về Ê-li-ê-xe: Rê-ha-bia, con trai người, rồi đến Y-sai-a, con trai người, rồi đến Giô-ram, con trai người, rồi đến Xích-ri, con trai người, và Sê-lô-mít, con trai người.'),
(11104, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 26, 26, 'OT', 'Ông Sê-lô-mít và các anh em ông quản lý mọi kho tàng các vật thánh, tức những vật mà vua Đa-vít, các tổ trưởng, các quan chỉ huy ngàn người và trăm người, cùng các quan chỉ huy quân đội đã biệt riêng ra thánh.'),
(11105, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 26, 27, 'OT', 'Từ các cuộc chiến tranh và từ của cải chiến lợi phẩm, họ dâng riêng ra để củng cố cho đền thờ của Đức Giê-hô-va.'),
(11106, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 26, 28, 'OT', 'Tất cả những gì mà Sa-mu-ên người thấy, Sa-un con trai của Kích, Áp-ne con trai của Ner, và Joab con trai của Zeruiah đã biệt riêng ra thánh, và mọi thứ dâng hiến đều do tay Shelomith và các anh em người ấy quản lý.'),
(11107, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 26, 29, 'OT', 'Thuộc về dòng họ Ích-ha-rít, Kê-nan-gia và các con trai của người được giao các công việc bên ngoài cho dân Y-sơ-ra-ên, làm viên chức và quan xét.'),
(11108, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 26, 30, 'OT', 'Thuộc về người Hẹ-bơ-rôn, Ha-sa-bia và các anh em người, những người trai tài, một ngàn bảy trăm người, làm các chức vụ về dân Y-sơ-ra-ên bên kia sông Giô-đanh về phía tây, để lo mọi công việc của Đức Giê-hô-va và để phục vụ vua.'),
(11109, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 26, 31, 'OT', 'Trong số người Hếp-ron-nít, Giê-ri-gia làm lãnh tụ, trong các thế hệ tổ tiên của người Hếp-ron-nít. Trong năm thứ bốn mươi đời trị vì của Đa-vít, người ta tra cứu và tìm thấy trong số họ những chiến sĩ dũng cảm tại Gia-xe, trong xứ Gi-lean.'),
(11110, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 26, 32, 'OT', 'Và các anh em người, là những người tráng kiện, gồm hai ngàn bảy trăm người làm đầu các họ hàng; vua Đa-vít đã đặt họ làm quan cai trị trên các người Ru-bên, người Ga-đi và nửa chi phái Ma-na-xe, về mọi việc thuộc về Đức Chúa Trời và các việc của nhà vua.'),
(11111, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 1, 'OT', 'Con số người Y-sơ-ra-ên theo từng lớp người, gồm các tộc trưởng, các quan chỉ huy ngàn người và trăm người, cùng các viên chức giúp việc vua trong mọi công việc luân phiên, cứ mỗi tháng một đợt, thay phiên nhau suốt các tháng trong năm; mỗi đợt gồm hai mươi bốn ngàn người.'),
(11112, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 2, 'OT', 'Tháng đầu tiên, chỉ huy đạo đầu tiên là Giát-sô-ba-am, con trai của Xáp-đi-ên; trong đạo của ông có hai mươi bốn ngàn người.'),
(11113, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 3, 'OT', 'Con cái của Pha-rết, người đứng đầu mọi viên tướng trong đạo quân cho tháng đầu tiên.'),
(11114, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 4, 'OT', 'Đoàn người của tháng thứ hai thuộc về Đô-đai, người A-hô-hít; và trong đoàn người ấy có Mích-lốt, người lãnh đạo. Trong đoàn người ấy cũng có hai mươi bốn ngàn người.'),
(11115, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 5, 'OT', 'Viên chỉ huy đạo quân tháng thứ ba là Bê-nai-a, con trai của Giê-hô-ia-đa, thầy tế lễ cả; và trong đạo quân của ông có hai mươi bốn ngàn người.'),
(11116, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 6, 'OT', 'Bản thân ông là Bê-nai-a, một chiến sĩ thuộc nhóm ba mươi người và đứng đầu nhóm ba mươi; và người thay phiên trong đội của ông là Ammizabad, con trai ông.'),
(11117, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 7, 'OT', 'Người thứ tư cho tháng thứ tư là A-xa-ên, anh của Giô-áp, và Xáp-đi-gia, con trai người, nối tiếp sau người; và trong đạo quân của người có hai mươi bốn ngàn người.'),
(11118, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 8, 'OT', 'Viên chỉ huy thứ năm cho tháng năm là Shamhuth người Izrah; và trong đạo quân của ông có hai mươi bốn ngàn người.'),
(11119, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 9, 'OT', 'Người thứ sáu cho tháng thứ sáu là I-ra, con trai của Ích-kết, người Tê-koa; và trong đội của người có hai mươi bốn ngàn người.'),
(11120, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 10, 'OT', 'Tháng thứ bảy, viên chỉ huy là Helez người Pelonite, thuộc con cháu Ép-ra-im; và trong đội của người có hai mươi bốn ngàn.'),
(11121, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 11, 'OT', 'Tháng thứ tám, Síp-bê-cai người Hút-sa-thít, thuộc dòng Xa-rích; và trong đội của ông có hai mươi bốn ngàn người.'),
(11122, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 12, 'OT', 'Tháng thứ chín, chỉ huy là A-bi-ê-xe người A-ne-thốt, thuộc chi phái Bên-gia-min; và trong kỳ phục vụ của ông có hai mươi bốn ngàn người.'),
(11123, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 13, 'OT', 'Tháng thứ mười, người chỉ huy là Maharai người Netophathite, thuộc dòng họ Zarchi; và trong đạo quân của ông có hai mươi bốn ngàn người.'),
(11124, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 14, 'OT', 'Mười một người chỉ huy cho tháng mười một là Bê-nai-a, người Pirathon, thuộc con cháu Ép-ra-im; và trong đội của người có hai mươi bốn ngàn người.'),
(11125, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 15, 'OT', 'Tháng thứ mười hai, người chỉ huy là Hê-đai người Nê-tô-pha-thi, thuộc về Ô-tha-ni-ên; và trong đội của người có hai mươi bốn ngàn người.'),
(11126, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 16, 'OT', 'Về các chi phái của Y-sơ-ra-ên: người cai trị chi phái Ru-bên là Ê-li-ê-xe, con trai Xích-ri; người cai trị chi phái Xi-mê-ôn là Sê-phát-ti-a, con trai Ma-a-cha.'),
(11127, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 17, 'OT', 'Thuộc về người Lê-vi, Ha-sa-bia, con trai của Kê-mu-ên; thuộc về dòng A-ha-ron, Xa-đốc.'),
(11128, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 18, 'OT', 'Thuộc về Giu-đa, Ê-li-hu, một người anh em của Đa-vít; thuộc về Y-xa-sa, Ôm-ri con trai của Mi-chê-ên.'),
(11129, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 19, 'OT', 'Thuộc về Xê-bu-lôn, Ích-ma-ia, con trai của Ô-ba-đia; thuộc về Náp-ta-li, Giê-ri-mốt, con trai của A-xri-ên.'),
(11130, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 20, 'OT', 'Con cái của Ép-ra-im: Hô-sê con trai của A-za-zi-a; phân nửa chi phái Ma-na-xe: Giô-ên con trai của Phê-đai-a.'),
(11131, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 21, 'OT', 'Thuộc về phân nửa chi phái Man-xes-se ở Gi-lean, Ích-đô con trai của Xác-cha-ri; thuộc về Bên-gia-min, Gia-a-xi-ên con trai của Áp-nơ.'),
(11132, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 22, 'OT', 'Về chi phái Đan, A-xa-rê-ên con trai của Giê-rô-ham. Đây là các quan trưởng của các chi phái Y-sơ-ra-ên.'),
(11133, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 23, 'OT', 'Đa-vít không đếm số người từ hai mươi tuổi trở xuống, vì Đức Giê-hô-va phán rằng: "Ta sẽ làm cho Ít-ra-en đông đảo như các ngôi sao trên trời."'),
(11134, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 24, 'OT', 'Yo-áp, con trai của Xê-ru-i-a, bắt đầu lập danh sách, nhưng không hoàn tất; và vì điều đó, cơn thịnh nộ đã giáng trên Ít-ra-en; nên con số ấy không được ghi vào sách sử ký của vua Đa-vít.'),
(11135, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 25, 'OT', 'Về các kho tàng của vua, có A-xơ-ma-vết, con trai của A-đi-ên; còn về các kho tàng ở ngoài đồng, trong các thành, các làng mạc và các tháp canh, có Giê-hô-nát-han, con trai của Ùt-xi-a.'),
(11136, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 26, 'OT', 'Và người quản lý những người làm việc ngoài đồng, lo việc canh tác đất đai, là Ê-xơ-ri, con trai của Kê-lúb.'),
(11137, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 27, 'OT', 'Về các vườn nho, có Si-mê-i người Ra-ma: về sản lượng các vườn nho để cất vào các kho rượu, có Xabdi người Síp-mi.'),
(11138, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 28, 'OT', 'Về các cây ô-liu và cây vả-si-đôn ở các vùng đồi thấp, thì Ba-al-ha-nan người Ghê-đe-ri coi sóc; còn về các kho chứa dầu ô-liu, thì Giô-ách coi sóc.'),
(11139, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 29, 'OT', 'Và người quản lý các đàn bò ở đồng bằng Sa-rôn là Sít-rai người Sa-rôn; còn người quản lý các đàn bò ở các thung lũng là Sa-phát, con trai của A-đlai.'),
(11140, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 30, 'OT', 'Về các lạc đà thì Ô-bích người Ích-ma-ên chịu trách nhiệm; về các lừa thì Giê-đê-gia người Mê-rô-nốt chịu trách nhiệm.'),
(11141, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 31, 'OT', 'Và người quản lý các bầy chiên là Y-a-zích, người Ha-ge-ri. Tất cả những người này là các viên cai trị tài sản thuộc về vua Đa-vít.'),
(11142, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 32, 'OT', 'Ông Giô-na-than, người chú của Đa-vít, là cố vấn, một người khôn ngoan và là thầy thông giáo; còn Giê-hi-ên, con trai của Ha-khô-mô-ni, thì ở cùng các con trai của vua.'),
(11143, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 33, 'OT', 'A-hi-tô-phên là người tư vấn cho vua; còn Hú-sai, người A-ki, là bạn của vua.'),
(11144, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 27, 34, 'OT', 'Sau A-hi-tô-phên là Giô-hoi-ada, con trai của Bê-nai-hu, và A-bi-a-tha; còn Giô-áp là tổng chỉ huy quân đội của vua.'),
(11145, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 28, 1, 'OT', 'Đa-vít triệu tập tất cả các quan trưởng của Y-sơ-ra-ên, các quan trưởng các chi phái, các quan chỉ huy các đạo quân phục vụ vua theo kỳ luân phiên, các quan chỉ huy ngàn người, các quan chỉ huy trăm người, các quản gia trên mọi tài sản và gia súc của vua và các con trai ông, cùng các thái giám, các chiến sĩ dũng cảm, và mọi người tráng kiện đến Giê-ru-sa-lem.'),
(11146, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 28, 2, 'OT', 'Vua Đa-vít đứng dậy trên đôi chân mình và nói: "Hãy nghe tôi, hỡi anh em và dân tôi! Tôi đã hết lòng muốn xây một nhà an nghỉ cho rương giao ước của Đức Giê-hô-va, và cho bệ chân của Đức Chúa Trời chúng ta, và tôi đã chuẩn bị sẵn sàng để xây cất."'),
(11147, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 28, 3, 'OT', 'Đức Chúa Trời phán cùng tôi rằng: "Ngươi không được xây nhà cho danh Ta, vì ngươi là người chiến tranh, đã đổ máu."'),
(11148, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 28, 4, 'OT', 'Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en đã chọn tôi giữa mọi chi phái trong nhà cha tôi, để làm vua cai trị Ít-ra-en đời đời; vì Ngài đã chọn Giu-đa làm người lãnh đạo, và trong nhà Giu-đa, chọn nhà cha tôi, và giữa các con trai của cha tôi, Ngài hài lòng về tôi để lập tôi làm vua cai trị toàn thể Ít-ra-en.'),
(11149, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 28, 5, 'OT', 'Trong tất cả các con trai của ta, vì Đức Giê-hô-va đã ban cho ta nhiều con trai, thì Ngài đã chọn Sa-lô-môn, con trai ta, để ngồi trên ngôi vương quyền của Đức Giê-hô-va trị vì trên Ít-ra-en.'),
(11150, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 28, 6, 'OT', 'Người phán cùng ta rằng: "Sa-lô-môn, con trai ngươi, chính người ấy sẽ xây cất nhà ta và các hành lang của ta; vì ta đã chọn người ấy làm con trai ta, và ta sẽ làm cha người."'),
(11151, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 28, 7, 'OT', 'Và Ta sẽ củng cố vương quốc của người đời đời, nếu người bền lòng làm theo các điều răn và các phán quyết của Ta như ngày hôm nay.'),
(11152, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 28, 8, 'OT', 'Bây giờ, trước mặt cả thể dân Y-sơ-ra-ên, hội chúng của Đức Giê-hô-va, và trong sự chứng kiến của Đức Chúa Trời chúng ta, hãy giữ và tìm kiếm trọn các điều răn của Đức Giê-hô-va Đức Chúa Trời các ngươi, để các ngươi được sở hữu đất tốt lành nầy, và để lại cho con cái các ngươi sau các ngươi làm sản nghiệp đời đời.'),
(11153, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 28, 9, 'OT', 'Và ngươi, Sa-lô-môn, con trai ta, hãy nhận biết Đức Chúa Trời của cha ngươi, và hầu việc Ngài với tấm lòng trọn vẹn và ý chí vui lòng; vì Đức Giê-hô-va dò xét mọi tấm lòng, và hiểu thấu mọi ý tưởng và mưu tính. Nếu ngươi tìm kiếm Ngài, ngươi sẽ được Ngài cho tìm thấy; nhưng nếu ngươi từ bỏ Ngài, Ngài sẽ từ bỏ ngươi đời đời.'),
(11154, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 28, 10, 'OT', 'Nầy, Đức Giê-hô-va đã chọn ngươi để xây cất nhà cho nơi thánh; hãy vững lòng và làm điều đó.'),
(11155, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 28, 11, 'OT', 'Đa-vít trao cho Sa-lô-môn, con trai mình, mẫu thiết kế của tiền sảnh, các phòng ốc, kho tàng, các tầng trên, các phòng trong và nơi đặt nắp thi ân.'),
(11156, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 28, 12, 'OT', 'và bản vẽ tất cả những gì ông nhận được theo cảm hứng, gồm các hành lang của đền thờ Đức Giê-hô-va, và tất cả các phòng xung quanh, các kho chứa của đền thờ Đức Chúa Trời, và các kho chứa các vật thánh.'),
(11157, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 28, 13, 'OT', 'Về các ban thầy tế lễ và người Lê-vi, về mọi công việc phục vụ trong đền thờ của Đức Giê-hô-va, và về mọi đồ dùng phục vụ trong đền thờ của Đức Giê-hô-va.'),
(11158, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 28, 14, 'OT', 'vàng theo cân cho các đồ bằng vàng, cho mọi khí cụ dùng vào công việc phụng sự; bạc theo cân cho các đồ bằng bạc, cho mọi khí cụ dùng vào mọi công việc phục vụ'),
(11159, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 28, 15, 'OT', 'Cả cân lượng cho các chân đèn bằng vàng và các đèn bằng vàng của nó, theo cân lượng từng chân đèn và các đèn của nó; và cho các chân đèn bằng bạc, theo cân lượng cho từng chân đèn và các đèn của nó, tùy theo công việc sử dụng từng chân đèn.'),
(11160, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 28, 16, 'OT', 'Và vàng theo cân để làm các bàn bày bánh trần thiết, mỗi cái bàn; và bạc cho các bàn bạc.'),
(11161, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 28, 17, 'OT', 'Và các móc bằng vàng ròng, các âu, các muỗng; và vàng cho các khay vàng, theo cân nặng cho mỗi khay và từng khay; và bạc cho các khay bạc, theo cân nặng cho mỗi khay và từng khay.'),
(11162, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 28, 18, 'OT', 'Và bàn thờ đốt hương thì dùng vàng ròng theo cân lường; và vàng làm kiểu xe chiến của các sứ thần, những kẻ giang cánh ra che phủ trên hòm giao ước của Đức Giê-hô-va.'),
(11163, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 28, 19, 'OT', 'Mọi điều này đều được chép ra, chính tay Đức Giê-hô-va đã ban cho tôi sự hiểu biết về tất cả các công việc của mẫu đó.'),
(11164, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 28, 20, 'OT', 'Đa-vít nói với Sa-lô-môn, con trai mình: "Hãy vững lòng can đảm và làm đi; đừng sợ, cũng đừng kinh hoàng, vì Đức Giê-hô-va Đức Chúa Trời, là Đức Chúa Trời của tôi, sẽ ở cùng ngươi; Ngài sẽ không buông bỏ ngươi, cũng không từ bỏ ngươi, cho đến khi ngươi hoàn thành mọi công việc về sự phục vụ đền thờ Đức Giê-hô-va."'),
(11165, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 28, 21, 'OT', 'Này, các ban thầy tế lễ và người Lê-vi sẽ cùng ngươi thực hiện mọi công việc nơi đền thờ Đức Chúa Trời; và mọi người thợ khéo có lòng sẵn sàng, giỏi mọi nghề, sẽ ở cùng ngươi để làm mọi công việc; các quan trưởng cùng toàn thể dân chúng cũng sẽ sẵn sàng tuân theo mọi chỉ thị của ngươi.'),
(11166, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 29, 1, 'OT', 'Vua Đa-vít nói với toàn thể hội chúng: "Sa-lô-môn, con trai tôi, là người duy nhất mà Đức Chúa Trời đã chọn, còn trẻ và yếu đuối, mà công việc thì rất lớn, vì đền thờ không phải để cho người, mà để cho Đức Giê-hô-va Đức Chúa Trời."'),
(11167, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 29, 2, 'OT', 'Với tất cả khả năng của tôi, tôi đã chuẩn bị cho nhà của Đức Chúa Trời tôi: vàng cho vàng, bạc cho bạc, đồng cho đồng, sắt cho sắt, gỗ cho gỗ; các viên đá mã não và các loại đá khảm, các viên đá màu sắc lóng lánh, mọi thứ đá quí, và các viên đá cẩm thạch với số lượng lớn.'),
(11168, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 29, 3, 'OT', 'Hơn nữa, vì tôi hết lòng yêu mến đền thờ của Đức Chúa Trời tôi, tôi đã dâng của riêng tôi là vàng và bạc cho đền thờ Đức Chúa Trời tôi, ngoài tất cả những gì tôi đã chuẩn bị cho đền thánh.'),
(11169, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 29, 4, 'OT', 'Ba ngàn ta-lânt vàng từ vàng Ofir, và bảy ngàn ta-lânt bạc đã tinh luyện, để tráng tường các ngôi nhà.'),
(11170, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 29, 5, 'OT', 'Vàng cho những vật bằng vàng, bạc cho những vật bằng bạc, và mọi công việc thợ khéo tay. Ai là người tình nguyện dâng tay mình hôm nay cho Đức Giê-hô-va?'),
(11171, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 29, 6, 'OT', 'Vậy các trưởng tộc, các lãnh tụ các chi phái Ít-ra-en, các chỉ huy ngàn người và trăm người, cùng các quan cai trị công việc của vua, đều dâng của lễ cách vui lòng.'),
(11172, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 29, 7, 'OT', 'Và họ dâng cho công việc nhà Đức Chúa Trời: năm ngàn rơ-pha vàng và mười ngàn a-đa-rơ-khôn, mười ngàn rơ-pha bạc, mười tám ngàn rơ-pha đồng, và một trăm ngàn rơ-pha sắt.'),
(11173, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 29, 8, 'OT', 'Và những người có đá quý trong tay mình thì dâng vào kho báu của đền thờ Đức Giê-hô-va, do tay Giê-hi-ên người Ghẹc-sôn-nít.'),
(11174, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 29, 9, 'OT', 'Dân sự vui mừng vì sự dâng hiến tự nguyện của mình, bởi họ đã dâng cho Đức Giê-hô-va với tấm lòng trọn vẹn; và vua Đa-vít cũng rất vui mừng.'),
(11175, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 29, 10, 'OT', 'Vậy nên Đa-vít chúc phước cho Đức Giê-hô-va trước mặt toàn thể hội chúng; và Đa-vít nói: "Xin chúc phước cho Ngài, lạy Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en, Cha chúng tôi, từ đời này sang đời khác mãi mãi vô cùng."'),
(11176, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 29, 11, 'OT', 'Đức Giê-hô-va, của Ngài là sự vĩ đại, quyền năng, vẻ vang, chiến thắng, và oai nghi; vì mọi vật trên trời và dưới đất đều thuộc về Ngài. Đức Giê-hô-va, của Ngài là vương quốc, và Ngài được tôn cao làm đầu trên muôn vật.'),
(11177, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 29, 12, 'OT', 'Của cải và vinh hiển đều ở trước mặt Ngài; chính Ngài cai trị trên muôn vật; trong tay Ngài có quyền năng và sức mạnh; cũng trong tay Ngài là sự làm cho lớn mạnh và ban sức lực cho tất cả.'),
(11178, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 29, 13, 'OT', 'Bây giờ, hỡi Đức Chúa Trời của chúng tôi, chúng tôi cảm tạ Ngài và ca ngợi danh vinh hiển của Ngài.'),
(11179, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 29, 14, 'OT', 'Nhưng tôi là ai, và dân tôi là ai, mà có thể dâng của lễ cách rộng rãi như thế này? Vì mọi vật đều thuộc về Ngài, và từ tay Ngài, chúng tôi đã dâng lại cho Ngài.'),
(11180, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 29, 15, 'OT', 'Chúng tôi là những kẻ khách lạ và người tạm trú trước mặt Ngài, như mọi tổ tiên chúng tôi; các ngày đời chúng tôi trên đất giống như cái bóng, và không có gì tồn tại mãi mãi.'),
(11181, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 29, 16, 'OT', 'Lạy Đức Giê-hô-va Đức Chúa Trời của chúng tôi, tất cả số lượng lớn này mà chúng tôi đã chuẩn bị để xây cho Ngài một ngôi nhà vì danh thánh Ngài, đều đến từ tay Ngài, và mọi sự đều thuộc về Ngài.'),
(11182, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 29, 17, 'OT', 'Lạy Đức Chúa Trời của con, con biết rằng Ngài thử thách lòng người và ưa điều ngay thẳng. Chính con đã dâng tất cả những điều này cách chân thành từ lòng mình; và bây giờ con thấy dân Ngài hiện diện ở đây, vui mừng dâng mình cho Đức Giê-hô-va.'),
(11183, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 29, 18, 'OT', 'Lạy Đức Giê-hô-va, Đức Chúa Trời của Áp-ra-ham, Y-sác và Y-sơ-ra-ên, tổ tiên chúng tôi, xin gìn giữ điều nầy luôn mãi trong ý tưởng của những suy nghĩ trong lòng dân Ngài, và xin khiến lòng họ hướng về Ngài.'),
(11184, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 29, 19, 'OT', 'Và xin ban cho Sa-lô-môn, con trai tôi, một lòng trọn vẹn để giữ các điều răn, các chứng cớ và các luật lệ của Ngài, và làm tất cả những điều đó, cùng xây cất cung điện mà tôi đã dự bị.'),
(11185, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 29, 20, 'OT', 'Vua Đa-vít nói với toàn thể hội chúng: "Hãy chúc tụng Đức Giê-hô-va là Đức Chúa Trời của các ngươi." Toàn thể hội chúng chúc tụng Đức Giê-hô-va là Đức Chúa Trời của tổ tiên họ, rồi cúi đầu và thờ lạy Đức Giê-hô-va và nhà vua.'),
(11186, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 29, 21, 'OT', 'Họ dâng các lễ tế cho Đức Giê-hô-va, và dâng các lễ thiêu cho Đức Giê-hô-va vào ngày hôm sau, tức là một ngàn con bò đực, một ngàn con chiên đực, một ngàn con chiên con, cùng các lễ đồ uống của chúng; và các lễ tế lớn cho toàn thể Y-sơ-ra-ên.'),
(11187, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 29, 22, 'OT', 'Họ ăn uống trước mặt Đức Giê-hô-va trong ngày ấy với niềm vui lớn; và họ tôn vương Sa-lô-môn, con trai Đa-vít, lần thứ hai, rồi xức dầu cho người trước mặt Đức Giê-hô-va làm lãnh tụ, và Xa-đốc làm thầy tế lễ.'),
(11188, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 29, 23, 'OT', 'Vậy, Sa-lô-môn ngồi trên ngôi của Đức Giê-hô-va làm vua thay cho Đa-vít, cha người; người thịnh vượng, và toàn thể Y-sơ-ra-ên đều vâng phục người.'),
(11189, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 29, 24, 'OT', 'Tất cả các quan trưởng, các dũng sĩ, và cả các con trai của vua Đa-vít đều phục dưới vua Sa-lô-môn.'),
(11190, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 29, 25, 'OT', 'Đức Giê-hô-va khiến cho Sa-lô-môn được tôn trọng rất cao trước mặt toàn thể Y-sơ-ra-ên, và ban cho người sự oai nghi của vương quyền mà trước người, chưa từng có vị vua nào trong Y-sơ-ra-ên được như vậy.'),
(11191, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 29, 26, 'OT', 'Đa-vít, con trai của Y-sai, trị vì trên toàn thể Y-sơ-ra-ên.'),
(11192, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 29, 27, 'OT', 'Thời gian ông trị vì trên Y-sơ-ra-ên là bốn mươi năm: bảy năm ông trị vì tại Hếp-rôn, và ba mươi ba năm ông trị vì tại Giê-ru-sa-lem.'),
(11193, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 29, 28, 'OT', 'Ông qua đời trong tuổi già tốt lành, đầy đủ năm tháng, giàu có và danh dự; và Sa-lô-môn, con trai ông, trị vì thay ông.'),
(11194, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 29, 29, 'OT', 'Các việc của vua Đa-vít, những việc đầu tiên và cuối cùng, đều đã chép trong sách của Sa-mu-ên người thấy, trong sách của Na-than người tiên tri, và trong sách của Gát người thấy.'),
(11195, 13, 'GOI_vi', 'GOI_vi', 'vi', '1CH', 29, 30, 'OT', 'Cùng mọi thời kỳ trị vì và quyền năng của ông, và những thời đại đã xảy ra cho ông, cho Y-sơ-ra-ên, và cho mọi vương quốc các nước.'),
(11196, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 1, 1, 'OT', 'Sa-lô-môn, con trai của Đa-vít, được củng cố trong vương quốc mình, và Đức Giê-hô-va Đức Chúa Trời của người ở cùng người, và làm cho người được tôn cao rất cao.'),
(11197, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 1, 2, 'OT', 'Vua Sa-lô-môn nói với toàn thể Ít-ra-ên, các quan chỉ huy ngàn người và trăm người, các quan xét xử, và mọi viên chức cai trị toàn thể Ít-ra-ên, các tộc trưởng.'),
(11198, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 1, 3, 'OT', 'Vậy thì Sa-lô-môn và cả hội chúng cùng người đi đến nơi cao tại Ghi-bê-ôn; vì tại đó có lều hội kiến của Đức Chúa Trời, mà Môi-se, tôi tớ của Đức Giê-hô-va, đã làm trong đồng vắng.'),
(11199, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 1, 4, 'OT', 'Nhưng rương của Đức Chúa Trời, vua Đa-vít đã rước lên từ Ki-ri-ath Giê-a-rim đến nơi vua đã chuẩn bị cho nó; vì vua đã dựng lều cho nó tại Giê-ru-sa-lem.'),
(11200, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 1, 5, 'OT', 'Và bàn thờ đồng mà Bết-xa-lên, con trai của Ú-ri, con trai của Hu-rơ, đã làm, thì được đặt trước trướng của Đức Giê-hô-va; và Sa-lô-môn cùng hội chúng cầu khẩn nơi đó.'),
(11201, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 1, 6, 'OT', 'Vua Sa-lô-môn đi lên đó đến bàn thờ bằng đồng trước mặt Đức Giê-hô-va, là bàn thờ thuộc lều hội kiến, và dâng trên đó một ngàn của lễ thiêu.'),
(11202, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 1, 7, 'OT', 'Đức Chúa Trời hiện ra cùng với Sa-lô-môn trong đêm đó, và phán cùng người rằng: "Hãy xin điều gì Ta sẽ ban cho ngươi."'),
(11203, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 1, 8, 'OT', 'Vua Sa-lô-môn nói với Đức Chúa Trời: "Chúa đã làm ơn lớn cho Đa-vít, cha tôi, và đã đặt tôi lên ngôi thay cho người."'),
(11204, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 1, 9, 'OT', 'Bây giờ, lạy Đức Giê-hô-va là Đức Chúa Trời, xin cho lời hứa của Ngài với Đa-vít, cha tôi, được xác lập; vì chính Ngài đã lập tôi làm vua trên một dân đông đảo như bụi đất.'),
(11205, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 1, 10, 'OT', 'Bây giờ xin hãy ban cho tôi sự khôn ngoan và tri thức, để tôi có thể ra vào trước mặt dân này; vì ai có thể xét xử dân lớn này của Ngài?'),
(11206, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 1, 11, 'OT', 'Đức Chúa Trời phán cùng Sa-lô-môn: "Bởi vì điều này ở trong lòng ngươi, ngươi không xin của cải, tài sản, danh dự, hay mạng sống những kẻ ghét ngươi, cũng chẳng xin sống lâu, nhưng ngươi đã xin sự khôn ngoan và tri thức để xét đoán dân ta mà Ta đã lập ngươi làm vua trên họ,'),
(11207, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 1, 12, 'OT', 'Ta đã ban cho ngươi sự khôn ngoan và tri thức; Ta cũng sẽ ban cho ngươi sự giàu có, tài sản và danh dự, đến nỗi không có một vị vua nào trước ngươi đã từng có như vậy, và sau ngươi cũng sẽ không có ai được như thế.'),
(11208, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 1, 13, 'OT', 'Rồi Sa-lô-môn đi từ nơi cao ở Ghi-bê-ôn về Giê-ru-sa-lem, từ trước trại tạm hội ngộ, và trị vì trên Ít-ra-en.'),
(11209, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 1, 14, 'OT', 'Sa-lô-môn tập hợp các xe chiến và kỵ binh; người có một ngàn bốn trăm xe chiến và mười hai ngàn kỵ binh, và người bố trí họ trong các thành phố xe chiến, và cùng với vua tại Giê-ru-sa-lem.'),
(11210, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 1, 15, 'OT', 'Vua khiến bạc và vàng ở Giê-ru-sa-lem trở nên phổ biến như đá, và ông khiến các cây hương nam trở nên nhiều như cây vả dại trong các thung lũng.'),
(11211, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 1, 16, 'OT', 'Ngựa mà Sa-lô-môn có đều do mua từ Ai Cập; các thương gia của nhà vua mua ngựa ấy với giá cả định sẵn.'),
(11212, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 1, 17, 'OT', 'Họ mang lên và mang ra khỏi Ai Cập một cỗ xe với sáu trăm miếng bạc, và một con ngựa với một trăm năm mươi miếng, và cũng vậy cho mọi vua dân Hê-tít và các vua xứ A-ram, họ mang ra bởi tay mình.'),
(11213, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 2, 1, 'OT', 'Sô-lô-môn nói: "Ta sẽ xây một đền thờ để tôn vinh danh Đức Giê-hô-va, và một cung điện cho vương quốc của ta."'),
(11214, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 2, 2, 'OT', 'Sa-lô-môn huy động bảy mươi ngàn người khuân vác, tám mươi ngàn người đục đá trên núi, và những người cai quản họ là ba ngàn sáu trăm người.'),
(11215, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 2, 3, 'OT', 'Vua Sa-lô-môn sai sứ đến vua Hu-ram, vua thành Tơ-rơ, rằng: "Như ngài đã làm cho Đa-vít, cha tôi, khi sai gỗ bá hương đến cho người để xây nhà cho người ở, thì xin ngài cũng làm như vậy cho tôi."'),
(11216, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 2, 4, 'OT', 'Nầy, tôi sẽ xây một ngôi nhà để tôn vinh danh Đức Giê-hô-va Đức Chúa Trời tôi, để biệt riêng cho Ngài, đốt trước mặt Ngài hương thơm, bày bánh trần thiết luôn luôn, và dâng các của lễ thiêu buổi sáng và chiều, trong các ngày Sa-bát, các ngày đầu tháng, và các kỳ lễ trọng của Đức Giê-hô-va Đức Chúa Trời chúng tôi. Đây là điều luật đời đời thuộc về Y-sơ-ra-ên.'),
(11217, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 2, 5, 'OT', 'Và đền thờ mà ta đang xây dựng thật lớn lao; vì Đức Chúa Trời chúng ta thật lớn hơn mọi thần.'),
(11218, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 2, 6, 'OT', 'Nhưng ai có thể đủ sức xây nhà cho Ngài, bởi vì các từng trời và các từng trời trên trời còn chẳng chứa được Ngài, huống chi tôi là ai mà xây nhà cho Ngài, ngoài việc dâng hương trước mặt Ngài?'),
(11219, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 2, 7, 'OT', 'Vì vậy, bây giờ xin hãy sai đến cho tôi một người khôn ngoan, để làm việc bằng vàng, bạc, đồng, sắt, màu tía, đỏ sậm và xanh lam, và biết chạm trổ các hình chạm; cùng với những người khôn ngoan mà tôi có ở Giu-đa và Giê-ru-sa-lem, mà Đa-vít cha tôi đã chuẩn bị.'),
(11220, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 2, 8, 'OT', 'Xin hãy sai người mang đến cho tôi gỗ tùng, gỗ bách và gỗ algum từ Li-băng, vì tôi biết các đầy tớ của ngài có thể thạo việc đốn gỗ ở Li-băng; nầy, các đầy tớ tôi sẽ cùng làm việc với các đầy tớ của ngài.'),
(11221, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 2, 9, 'OT', 'Và hãy chuẩn bị cho tôi nhiều gỗ, vì ngôi nhà mà tôi sẽ xây rất lớn và kỳ diệu.'),
(11222, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 2, 10, 'OT', 'Nầy, ta đã cấp cho các thợ đốn cây, những người chặt gỗ cho đầy tớ ngươi, lúa mì giã nhỏ hai mươi ngàn kôr, lúa mạch hai mươi ngàn kôr, rượu hai mươi ngàn ba, và dầu hai mươi ngàn ba.'),
(11223, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 2, 11, 'OT', 'Vua Hô-ram của Típ-rơ đáp bằng thơ tín gửi cho Sa-lô-môn: "Vì Đức Giê-hô-va yêu dân sự mình, nên Ngài đã lập ngươi làm vua trị vì trên họ."'),
(11224, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 2, 12, 'OT', 'Huram nói: "Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên đáng được ca ngợi, Đấng đã làm trời và đất, và đã ban cho vua Đa-vít một người con trai đầy khôn ngoan, thông hiểu và hiểu biết, để xây cất đền thờ cho Đức Giê-hô-va và cung điện cho vương quyền của người."'),
(11225, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 2, 13, 'OT', 'Và bây giờ, ta đã sai một người khôn ngoan, thông hiểu, là Hô-ram, cha ta.'),
(11226, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 2, 14, 'OT', 'Là con trai của một người phụ nữ thuộc các con gái Đan, và cha người là một người nam thành Tí, biết làm việc bằng vàng, bằng bạc, bằng đồng, bằng sắt, bằng đá và bằng gỗ, bằng vải điều, bằng vải xanh, bằng vải gai mịn và bằng vải đỏ; cũng biết chạm trổ mọi kiểu chạm trổ, và suy nghĩ mọi ý tưởng mà người ta giao cho, cùng với các người khôn ngoan của ngươi và các người khôn ngoan của chúa ngươi là Đa-vít, cha ngươi.'),
(11227, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 2, 15, 'OT', 'Bây giờ, hãy gửi lúa mì, lúa mạch, dầu và rượu mà chúa của tôi đã nói đến cho các đầy tớ người:'),
(11228, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 2, 16, 'OT', 'Chúng tôi sẽ đốn gỗ từ Li-băng, tùy theo mọi nhu cầu của ngài, và sẽ ghép chúng thành bè trôi trên biển đến Y-áp-phô; còn ngài sẽ chuyển chúng lên Giê-ru-sa-lem.'),
(11229, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 2, 17, 'OT', 'Vua Sa-lô-môn đã điểm số tất cả những người ngoại bang ở trong đất Ít-ra-en, sau cuộc điểm số mà Đa-vít, cha người, đã từng điểm; và họ được tìm thấy là một trăm năm mươi ngàn người, ba ngàn người và sáu trăm người.'),
(11230, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 2, 18, 'OT', 'Ông chọn ra bảy mươi ngàn người khiêng gánh, tám mươi ngàn người đục đá trên núi, và ba ngàn sáu trăm người chỉ huy để cai quản dân chúng làm việc.'),
(11231, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 3, 1, 'OT', 'Vua Sa-lô-môn bắt đầu xây cất đền thờ Đức Giê-hô-va tại Giê-ru-sa-lem, trên núi Mô-ri-a, là nơi Đức Giê-hô-va hiện ra cho Đa-vít, cha người, tức nơi Đa-vít đã chuẩn bị sẵn, tại sân đập lúa của A-rơ-nan, người Yê-bu-sít.'),
(11232, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 3, 2, 'OT', 'Người ấy bắt đầu xây cất vào tháng thứ hai, năm thứ tư triều đại mình.'),
(11233, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 3, 3, 'OT', 'Và đây là nền tảng mà Sa-lô-môn đặt ra để xây cất đền thờ Đức Chúa Trời: chiều dài theo thước đo đầu tiên là sáu mươi thước, và chiều rộng là hai mươi thước.'),
(11234, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 3, 4, 'OT', 'Hành lang phía trước nhà, theo chiều ngang của nhà, dài hai mươi thước, và cao một trăm hai mươi thước; người ta ốp bên trong bằng vàng ròng.'),
(11235, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 3, 5, 'OT', 'Ngôi nhà lớn được ốp bằng gỗ hương, phủ vàng ròng bên trên, và chạm hình các cây chà là cùng các dây xích.'),
(11236, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 3, 6, 'OT', 'Người trang hoàng ngôi nhà bằng những viên đá quý để làm đẹp, và vàng là vàng của Parvaim.'),
(11237, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 3, 7, 'OT', 'Người đã dát vàng các trần nhà, vách tường và các cửa của đền thờ; và chạm khắc các chê-ru-bim trên các vách tường.'),
(11238, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 3, 8, 'OT', 'Ông làm nơi chí thánh, chiều dài của nó theo chiều rộng của đền thờ là hai mươi thước, và chiều rộng của nó là hai mươi thước; ông phủ nó bằng vàng ròng, số lượng vàng là sáu trăm kikar.'),
(11239, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 3, 9, 'OT', 'Và trọng lượng các cái đinh là năm mươi sê-la vàng. Người phủ vàng lên các phòng trên.'),
(11240, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 3, 10, 'OT', 'Người làm trong nhà nơi thánh chí thánh hai con Kê-ru-bin bằng cách đúc, và mạ vàng chúng.'),
(11241, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 3, 11, 'OT', 'Cánh của các con chê-ru-bim dài hai mươi thước; mỗi cánh dài năm thước, một cánh thì chạm đến tường đền thờ, và cánh kia dài năm thước thì chạm đến cánh của con chê-ru-bim khác.'),
(11242, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 3, 12, 'OT', 'Một cánh của con bò chim thứ hai dài năm thước, chạm đến tường nhà; và cánh kia dài năm thước, dính vào cánh của con bò chim kia.'),
(11243, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 3, 13, 'OT', 'Các cánh của các sứ thần này giang ra hai mươi thước; chúng đứng trên đôi chân mình, và mặt chúng hướng về đền thờ.'),
(11244, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 3, 14, 'OT', 'Người làm bức màn bằng chỉ xanh, tím, đỏ và vải gai mịn, và thêu các thiên sứ trên đó.'),
(11245, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 3, 15, 'OT', 'Ông làm phía trước đền thờ hai cột trụ, mỗi cột cao ba mươi lăm thước, và đầu cột trên cùng mỗi cột cao năm thước.'),
(11246, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 3, 16, 'OT', 'Ông làm các xích ở nơi thánh, đặt trên đầu các trụ, rồi làm một trăm trái lựu, đặt trên các xích.'),
(11247, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 3, 17, 'OT', 'Ông dựng hai trụ ở trước đền thờ, một trụ bên phải và một trụ bên trái; ông đặt tên cho trụ bên phải là Gia-kin, và tên cho trụ bên trái là Bô-az.'),
(11248, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 4, 1, 'OT', 'Người đã làm một bàn thờ bằng đồng, dài hai mươi thước, rộng hai mươi thước, và cao mười thước.'),
(11249, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 4, 2, 'OT', 'Người đã làm cái biển đúc, rộng mười thước từ mép nầy đến mép kia, tròn tròn xung quanh, cao năm thước, và một sợi dây ba mươi thước sẽ đo vòng quanh nó.'),
(11250, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 4, 3, 'OT', 'Dưới nó có hình các con bò tót, vòng quanh bao quanh nó; mười con trong một thước, bao quanh cái biển về khắp các phía; hai hàng các con bò tót được đúc cùng với nó.'),
(11251, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 4, 4, 'OT', 'Đứng trên mười hai con bò, ba con quay mặt về hướng bắc, ba con quay mặt về hướng tây, ba con quay mặt về hướng nam, và ba con quay mặt về hướng đông; và Biển đặt phía trên chúng từ phía trên cao, còn tất cả phần phía sau lưng chúng thì hướng vào trong.'),
(11252, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 4, 5, 'OT', 'Dày một tầm tay, mép nó giống như kiểu mép chén, có hoa sen nở; nó chứa và đựng được ba ngàn bát.'),
(11253, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 4, 6, 'OT', 'Ông làm mười cái chậu, đặt năm cái bên phải và năm cái bên trái, để rửa những vật dâng cho của lễ thiêu; còn cái biển dùng để các thầy tế lễ tắm rửa.'),
(11254, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 4, 7, 'OT', 'Ông làm mười cây đèn bằng vàng theo đúng kiểu dáng của chúng, và đặt trong đền thờ, năm cái bên phải và năm cái bên trái.'),
(11255, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 4, 8, 'OT', 'Ông làm mười cái bàn, đặt trong đền thờ, năm cái bên phải và năm cái bên trái. Ông cũng làm một trăm cái bồn bằng vàng.'),
(11256, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 4, 9, 'OT', 'Người làm sân của các thầy tế lễ, và sân lớn, cùng các cửa cho sân ấy, và những bản lề của các cửa ấy thì được dát đồng.'),
(11257, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 4, 10, 'OT', 'Và ông đặt cái biển ở phía bên phải, về phía đông, đối diện với phía nam.'),
(11258, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 4, 11, 'OT', 'Ông Hu-ram làm các cái vạc, các cái xẻng và các cái chậu. Ông Hu-ram hoàn thành công việc mà ông phải làm cho vua Sô-lô-môn trong đền thờ Đức Chúa Trời.'),
(11259, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 4, 12, 'OT', 'Hai trụ, các hình cầu và các vòng tròn trên đầu hai trụ, và hai mạng lưới để che phủ hai hình cầu của các vòng tròn trên đầu hai trụ.'),
(11260, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 4, 13, 'OT', 'Và bốn trăm trái lựu trên hai mạng lưới, hai hàng trái lựu cho mỗi mạng lưới, để che hai quả cầu trang trí trên các đầu trụ.'),
(11261, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 4, 14, 'OT', 'Người cũng làm các đế đỡ, và các chậu nước đặt trên các đế đỡ.'),
(11262, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 4, 15, 'OT', 'một cái biển và mười hai con bò đực ở dưới nó'),
(11263, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 4, 16, 'OT', 'Các cái vạc, các cái xẻng, các cái móc câu và mọi đồ dùng của chúng, tất cả đều do ông Hô-ram, người cha của ông, làm cho vua Sa-lô-môn dùng trong đền thờ Đức Giê-hô-va, bằng đồng đánh bóng.'),
(11264, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 4, 17, 'OT', 'Vua đúc những cái đó tại đồng bằng Giô-đanh, trên đất sét, giữa Xúc-kốt và Xê-rê-đa-tha.'),
(11265, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 4, 18, 'OT', 'Vậy nên, Sa-lô-môn làm tất cả các đồ đó với số lượng rất lớn, vì trọng lượng của đồng không thể tính được.'),
(11266, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 4, 19, 'OT', 'Vua Sa-lô-môn làm tất cả các đồ dùng cho đền thờ Đức Chúa Trời, bàn thờ bằng vàng, các cái bàn và các đồ đặt trên các cái bàn ấy là bánh trần thiết.'),
(11267, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 4, 20, 'OT', 'Các chân đèn và các đèn của chúng để thắp sáng theo đúng quy định trước nơi Thánh, bằng vàng ròng.'),
(11268, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 4, 21, 'OT', 'Và những bông hoa, những ngọn đèn, và những cái kẹp, đều bằng vàng; chính những đồ dùng bằng vàng ròng.'),
(11269, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 4, 22, 'OT', 'Và các cái kéo hớt tim đèn, các chậu rảy, các thìa và các lư hương bằng vàng ròng; và cửa nhà, các cửa bên trong dẫn vào nơi Thánh của các Thánh, cùng các cửa của nhà đền thờ, đều bằng vàng.'),
(11270, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 5, 1, 'OT', 'Vậy, mọi công việc mà Sa-lô-môn làm cho đền thờ Đức Giê-hô-va đều được hoàn tất; rồi Sa-lô-môn mang đến những vật thánh mà Đa-vít, cha người, đã biệt riêng ra, cùng với bạc, vàng và mọi đồ dùng, và đặt chúng vào các kho tàng trong đền thờ Đức Chúa Trời.'),
(11271, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 5, 2, 'OT', 'Bấy giờ, Sa-lô-môn triệu tập các trưởng lão của Y-sơ-ra-ên, và tất cả các thủ lĩnh các chi phái, các tộc trưởng của con cái Y-sơ-ra-ên, đến Giê-ru-sa-lem, để rước hòm giao ước của Đức Giê-hô-va từ thành Đa-vít, tức là Xi-ôn, lên đó.'),
(11272, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 5, 3, 'OT', 'Vậy, tất cả những người nam của Y-sơ-ra-ên đều nhóm lại cùng vua trong dịp lễ hội, là tháng thứ bảy.'),
(11273, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 5, 4, 'OT', 'Các trưởng lão của Y-sơ-ra-ên đều đến, và những người Lê-vi khiêng hòm giao ước lên.'),
(11274, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 5, 5, 'OT', 'Các thầy tế lễ và người Lê-vi đã khiêng hòm giao ước, và lều hội kiến, và mọi đồ thánh ở trong lều.'),
(11275, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 5, 6, 'OT', 'Vua Sa-lô-môn và toàn thể hội chúng Y-sơ-ra-ên, những người được triệu tập đến cùng người trước hòm giao ước, dâng tế lễ những con chiên và bò, đến nỗi không thể đếm được và không thể tính được vì quá đông.'),
(11276, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 5, 7, 'OT', 'Các thầy tế lễ khiêng hòm giao ước của Đức Giê-hô-va đến nơi của nó, vào nơi chí thánh trong đền thờ, tức là chỗ cực thánh dưới các cánh của các sứ-thần.'),
(11277, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 5, 8, 'OT', 'Các con Kê-ru-bim giang cánh ra trên nơi để hòm, và các con Kê-ru-bim che phủ hòm và các đòn khiêng của nó từ phía trên.'),
(11278, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 5, 9, 'OT', 'Các đòn khiêng được kéo dài ra, và đầu các đòn khiêng có thể nhìn thấy từ bên trong hòm trước nơi chí thánh; nhưng bên ngoài thì không thấy. Và nó vẫn ở đó cho đến ngày nay.'),
(11279, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 5, 10, 'OT', 'Hòm giao ước không chứa gì khác ngoài hai bảng đá mà Môi-se đã đặt tại Hô-rêb, nơi Đức Giê-hô-va lập giao ước với con cháu Ít-ra-en khi họ ra khỏi Ai-cập.'),
(11280, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 5, 11, 'OT', 'Khi các thầy tế lễ ra khỏi nơi thánh, vì mọi thầy tế lễ hiện diện đều đã biệt riêng ra thánh, không cần phải thay phiên theo các ban.'),
(11281, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 5, 12, 'OT', 'Các thầy Lê-vi là những người hát xướng, tất cả đều thuộc về A-sáp, Hê-man, Giê-đu-thun, cùng các con trai và anh em họ, mặc áo vải gai mịn, cầm chập chỏa, đờn cầm và đờn sắt, đứng về phía đông của bàn thờ; và cùng họ có một trăm hai mươi thầy tế lễ thổi kèn.'),
(11282, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 5, 13, 'OT', 'Khi các nhạc công kèn và các nhạc công hát cất tiếng làm thành một âm thanh duy nhất để ca ngợi và cảm tạ Đức Giê-hô-va, khi họ cất tiếng với kèn, với chập chỏa và các nhạc cụ dùng trong bài hát, khi ca ngợi Đức Giê-hô-va rằng: "Vì Ngài là thiện; vì sự nhân từ của Ngài còn đến đời đời", thì đền thờ đầy dẫy mây, tức là đền thờ Đức Giê-hô-va.'),
(11283, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 5, 14, 'OT', 'Các thầy tế lễ không thể đứng được để thi hành chức vụ vì mây mù, bởi vinh hiển của Đức Giê-hô-va đã đầy nhà Đức Chúa Trời.'),
(11284, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 1, 'OT', 'Bấy giờ, Sa-lô-môn nói: Đức Giê-hô-va đã phán rằng Ngài sẽ ngự trong nơi tối tăm.'),
(11285, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 2, 'OT', 'Nhưng tôi đã xây một ngôi nhà uy nghi cho Ngài, và một nơi cho Ngài ngự đến các thế hệ mãi mãi.'),
(11286, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 3, 'OT', 'Vua đổi chiều, ngước mặt và chúc phước cho toàn thể hội chúng Ít-ra-en; và toàn thể hội chúng Ít-ra-en đứng đó.'),
(11287, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 4, 'OT', 'Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en được tôn vinh, Đấng đã dùng miệng phán cùng Đa-vít, cha tôi, và dùng tay Ngài thực hiện điều phán ấy, khi nói rằng:'),
(11288, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 5, 'OT', 'Kể từ ngày Ta dẫn dân Ta ra khỏi đất Ai Cập, Ta đã không chọn một thành nào trong mọi chi phái Y-sơ-ra-ên để xây cất nhà cho Danh Ta ngự ở đó; cũng chẳng chọn một người nào để làm lãnh đạo cai trị dân Ta là Y-sơ-ra-ên.'),
(11289, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 6, 'OT', 'Nhưng Ta đã chọn Giê-ru-sa-lem để danh Ta ngự tại đó, và đã chọn Đa-vít để cai trị dân Ta Y-sơ-ra-ên.'),
(11290, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 7, 'OT', 'Lòng của Đa-vít, cha tôi, đã muốn xây một ngôi nhà cho danh của Đức Giê-hô-va, Đức Chúa Trời của Ít-ra-en.'),
(11291, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 8, 'OT', 'Đức Giê-hô-va phán cùng Đa-vít, cha tôi: "Vì lòng ngươi đã định xây một nhà cho danh ta, ngươi đã làm điều tốt khi lòng ngươi có ý định đó."'),
(11292, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 9, 'OT', 'Nhưng ngươi sẽ không xây nhà ấy; chính con trai ngươi, người sẽ sinh ra từ ngươi, người ấy sẽ xây nhà cho danh ta.'),
(11293, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 10, 'OT', 'Đức Giê-hô-va đã thực hiện lời Ngài phán; tôi đã đứng lên thay chỗ Đa-vít, cha tôi, và ngồi trên ngôi của Y-sơ-ra-ên như Đức Giê-hô-va đã phán, và tôi đã xây cất đền thờ để kính danh Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên.'),
(11294, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 11, 'OT', 'Ta đặt hòm đó ở đó, trong đó có giao ước của Đức Giê-hô-va mà Ngài đã lập với con cái Y-sơ-ra-ên.'),
(11295, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 12, 'OT', 'Và người đứng trước bàn thờ của Đức Giê-hô-va, đối diện với toàn thể hội chúng Y-sơ-ra-ên, rồi giang rộng hai tay mình.'),
(11296, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 13, 'OT', 'Vì Sa-lô-môn đã làm một bệ bằng đồng dài năm thước, rộng năm thước, cao ba thước, rồi đặt nó ở giữa hành lang; người đứng lên trên đó, quỳ gối xuống trước mặt toàn thể hội chúng Ít-ra-en, và giơ hai tay lên trời.'),
(11297, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 14, 'OT', 'Lạy Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên, không có thần nào giống như Ngài trên trời và dưới đất, Đấng giữ giao ước và sự nhân từ đối với các tôi tớ Ngài, là những người đi trước mặt Ngài hết lòng.'),
(11298, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 15, 'OT', 'Đức Giê-hô-va đã giữ lời hứa mà Ngài đã phán cùng Đa-vít, cha tôi, và dùng miệng Ngài phán ra, dùng tay Ngài thực hiện điều đó cho đến ngày nay.'),
(11299, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 16, 'OT', 'Bây giờ, hỡi Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên, xin gìn giữ lời Ngài đã hứa cùng Đa-vít, tôi tớ Ngài, là cha tôi, rằng: "Chẳng hề thiếu ngươi một người nào ở trước mặt ta để ngồi trên ngôi Y-sơ-ra-ên, miễn là các con trai ngươi cẩn thận giữ đường lối mình, đi theo luật pháp ta như ngươi đã đi trước mặt ta."'),
(11300, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 17, 'OT', 'Bây giờ, hỡi Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên, xin làm cho ứng nghiệm lời Ngài đã phán cùng đầy tớ Ngài là Đa-vít.'),
(11301, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 18, 'OT', 'Nhưng thật sự Đức Chúa Trời sẽ ở cùng loài người trên đất chăng? Kìa, các từng trời và các từng trời của các từng trời còn chẳng thể chứa nổi Ngài, huống chi là nhà nầy mà tôi đã xây!'),
(11302, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 19, 'OT', 'Xin hãy đoái xem lời cầu nguyện của đầy tớ Ngài và lời khẩn xin của người, hỡi Đức Giê-hô-va Đức Chúa Trời, để nghe tiếng kêu và lời cầu nguyện mà đầy tớ Ngài đang dâng trước mặt Ngài.'),
(11303, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 20, 'OT', 'Nguyện mắt Ngài luôn mở ra nhìn ngày và đêm về nơi này, tức là nơi Ngài đã phán rằng: "Ta sẽ đặt danh Ta tại đó," để nghe lời cầu nguyện mà tôi tớ Ngài dâng lên hướng về nơi này.'),
(11304, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 21, 'OT', 'Xin hãy nghe những lời nài xin của đầy tớ Ngài và của dân Y-sơ-ra-ên, là dân Ngài, khi họ cầu nguyện về nơi này; xin Ngài nghe từ nơi Ngài ngự, tức từ các từng trời, và khi Ngài nghe, xin tha thứ.'),
(11305, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 22, 'OT', 'Nếu có người nào phạm tội cùng đồng loại mình, và người đó bị bắt phải thề một lời thề, thì lời thề ấy sẽ được mang đến trước bàn thờ của Ngài trong đền thờ này;'),
(11306, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 23, 'OT', 'Đức Giê-hô-va sẽ nghe từ trời, và sẽ thi hành, xét xử các đầy tớ Ngài, để báo ứng kẻ ác, đặt con đường nó trên đầu nó; và làm cho người công bình được công bình, ban cho người theo sự công bình của người.'),
(11307, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 24, 'OT', 'Nếu dân sự Ngài là Y-sơ-ra-ên bị đánh bại trước mặt kẻ thù vì họ phạm tội nghịch cùng Ngài, rồi họ trở lại, xưng tụng danh Ngài, và cầu nguyện, nài xin trước mặt Ngài trong đền thờ nầy;'),
(11308, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 25, 'OT', 'Vậy xin Đức Giê-hô-va nghe từ các từng trời, tha thứ tội lỗi cho dân Y-sơ-ra-ên của Ngài, và đem họ trở lại đất đai mà Ngài đã ban cho họ và cho các tổ phụ họ.'),
(11309, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 26, 'OT', 'Khi các từng trời bị đóng lại và không có mưa, vì chúng nó đã phạm tội nghịch cùng Ngài; nếu chúng nó cầu nguyện về nơi này, xưng nhận danh Ngài, và từ bỏ tội lỗi mình, khi Ngài giáng họ sự khốn khổ;'),
(11310, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 27, 'OT', 'Xin Ngài nghe từ các từng trời, tha thứ tội lỗi cho các tôi tớ Ngài và cho dân Y-sơ-ra-ên của Ngài, khi Ngài dạy họ con đường tốt lành mà họ phải đi; và Ngài sẽ ban mưa trên đất nước Ngài đã ban cho dân Ngài làm sản nghiệp.'),
(11311, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 28, 'OT', 'Nếu trong đất có sự đói kém, nếu có ôn dịch, nếu có nạn khô héo hay mốc meo, châu chấu hay sâu hủy hoại; nếu kẻ thù của chúng vây hãm chúng trong các thành của đất; mọi tai họa, mọi bệnh tật,'),
(11312, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 29, 'OT', 'Mọi lời cầu nguyện, mọi lời khẩn nài mà bất kỳ người nào hay toàn dân Y-sơ-ra-ên của Ngài sẽ dâng lên, khi mỗi người biết rõ nỗi đau và sự thống khổ của mình, và giơ tay mình ra hướng về đền thờ nầy:'),
(11313, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 30, 'OT', 'Và Ngài sẽ nghe từ trời, nơi Ngài ngự, rồi tha thứ và ban cho mỗi người tùy theo mọi đường lối của họ, vì Ngài biết lòng người; thật vậy, chỉ một mình Ngài biết lòng các con cái loài người.'),
(11314, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 31, 'OT', 'Nguyện họ kính sợ Ngài để bước đi trong các đường lối của Ngài, trọn mọi ngày họ sống trên đất mà Ngài đã ban cho tổ tiên chúng tôi.'),
(11315, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 32, 'OT', 'Còn về người ngoại bang, không thuộc dân Y-sơ-ra-ên, mà từ xứ xa đến vì danh lớn của Đức Giê-hô-va, tay quyền năng và cánh tay duỗi ra của Ngài; họ sẽ đến và cầu nguyện trong đền thờ này.'),
(11316, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 33, 'OT', 'Và Ngài sẽ nghe từ các từng trời, từ nơi Ngài ngự, và làm theo mọi điều mà người ngoại bang kêu cầu Ngài, để mọi dân trên đất đều biết danh Ngài, kính sợ Ngài như dân Ngài Y-sơ-ra-ên, và biết rằng danh Ngài được gọi trên đền thờ nầy, là đền thờ mà tôi đã xây.'),
(11317, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 34, 'OT', 'Khi dân sự của Ngài ra đi đánh giặc chống lại kẻ thù, theo con đường mà Ngài sẽ sai họ đi, và họ cầu nguyện cùng Ngài hướng về thành này mà Ngài đã chọn và đền thờ mà tôi đã xây để tôn vinh danh Ngài.'),
(11318, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 35, 'OT', 'Xin hãy nghe từ các từng trời lời cầu nguyện và lời khẩn xin của họ, và xử đoán theo quyền lợi họ.'),
(11319, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 36, 'OT', 'Nếu chúng phạm tội cùng Ngài, vì không có người nào chẳng phạm tội, và Ngài nổi giận cùng chúng, rồi phó chúng vào tay kẻ thù, khiến chúng bị bắt làm phu tù đến một xứ xa hay gần;'),
(11320, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 37, 'OT', 'Nếu chúng trở lại trong lòng mình tại đất mà chúng bị bắt làm phu tù, và trở lại cùng nài xin Ngài tại đất nơi chúng bị lưu đày, mà rằng: "Chúng tôi đã phạm tội, đã làm điều ác và làm điều gian ác."'),
(11321, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 38, 'OT', 'Nếu họ trở lại cùng Ngài với trọn tấm lòng và trọn linh hồn họ, trong đất lưu đày mà tại đó họ bị bắt làm phu tù, và cầu nguyện hướng về đất của tổ tiên họ mà Ngài đã ban cho, và về thành mà Ngài đã chọn, và về đền thờ mà tôi đã xây để tôn vinh danh Ngài.'),
(11322, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 39, 'OT', 'Thì xin Đức Giê-hô-va hãy nghe từ các từng trời, từ nơi Ngài ngự, lời cầu nguyện và khẩn nguyện của họ, xét đoán cho họ, và tha thứ cho dân Ngài là những kẻ đã phạm tội nghịch cùng Ngài.'),
(11323, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 40, 'OT', 'Lạy Đức Chúa Trời của con, xin cho đôi mắt Ngài luôn mở ra và tai Ngài chăm chú nghe lời cầu nguyện dâng nơi chốn này.'),
(11324, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 41, 'OT', 'Bây giờ, xin hãy chỗi dậy, Đức Giê-hô-va Đức Chúa Trời, để vào nơi an nghỉ của Ngài; chính Ngài và hòm chứa sức mạnh của Ngài. Các thầy tế lễ của Ngài, hỡi Đức Giê-hô-va Đức Chúa Trời, hãy mặc lấy sự cứu rỗi; và những người thánh của Ngài hãy vui mừng trong điều thiện.'),
(11325, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 6, 42, 'OT', 'Lạy Đức Giê-hô-va Đức Chúa Trời, xin chớ từ bỏ mặt kẻ xức dầu của Ngài; xin nhớ đến các điều nhân từ của Đa-vít, tôi tớ Ngài.'),
(11326, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 7, 1, 'OT', 'Khi Xô-lô-môn cầu nguyện xong, lửa từ trời giáng xuống, thiêu đốt của lễ toàn thiêu và các của lễ; vinh hiển của Đức Giê-hô-va đầy cả đền thờ.'),
(11327, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 7, 2, 'OT', 'Các thầy tế lễ không thể vào trong nhà của Đức Giê-hô-va, vì sự vinh hiển của Đức Giê-hô-va đã đầy nhà của Đức Giê-hô-va.'),
(11328, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 7, 3, 'OT', 'Toàn thể con cái Ít-ra-en thấy lửa từ trời ngự xuống và sự vinh hiển của Đức Giê-hô-va ngự trên đền thờ, bèn cúi sấp mặt xuống đất trên nền đá, thờ lạy và cảm tạ Đức Giê-hô-va rằng: "Ngài thật tốt lành; lòng nhân từ của Ngài còn mãi đời đời."'),
(11329, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 7, 4, 'OT', 'Vua và toàn thể dân chúng dâng của lễ thiêu trước mặt Đức Giê-hô-va.'),
(11330, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 7, 5, 'OT', 'Vua Sa-lô-môn dâng của lễ thiêu gồm hai mươi hai ngàn con bò và một trăm hai mươi ngàn chiên; vua và toàn thể dân chúng dùng những của lễ ấy để biệt riêng đền thờ Đức Chúa Trời.'),
(11331, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 7, 6, 'OT', 'Các thầy tế lễ đứng giữ chức vụ của mình, còn các thầy Lê-vi thì dùng các nhạc khí của Đức Giê-hô-va, mà vua Đa-vít đã làm để ca ngợi Đức Giê-hô-va, vì sự nhân từ của Ngài tồn tại đời đời; và Đa-vít dùng tay các thầy Lê-vi mà ca ngợi. Các thầy tế lễ thổi kèn trước mặt các thầy Lê-vi, còn toàn thể Y-sơ-ra-ên thì đứng.'),
(11332, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 7, 7, 'OT', 'Vua Sa-lô-môn đã biệt riêng phần giữa sân trước nhà Đức Giê-hô-va, vì tại đó ông dâng các của lễ thiêu và mỡ các của lễ thù ân; bởi cái bàn thờ bằng đồng mà Sa-lô-môn đã làm không đủ chỗ chứa các của lễ thiêu, của lễ chay và mỡ.'),
(11333, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 7, 8, 'OT', 'Đoạn đó, Sa-lô-môn giữ lễ trong bảy ngày, và toàn thể Ít-ra-en cùng với ông, một hội chúng rất đông, từ lối vào Ha-mát cho đến sông Ai-cập.'),
(11334, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 7, 9, 'OT', 'Vào ngày thứ tám, họ tổ chức một buổi họp trang trọng; vì họ đã tổ chức lễ khánh thành bàn thờ bảy ngày, và lễ hội bảy ngày.'),
(11335, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 7, 10, 'OT', 'Vào ngày hai mươi ba tháng bảy, người cho dân chúng về lều mình, lòng vui vẻ và hân hoan vì sự tốt lành mà Đức Giê-hô-va đã làm cho Đa-vít, cho Sa-lô-môn và cho Y-sơ-ra-ên, dân sự Ngài.'),
(11336, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 7, 11, 'OT', 'Vậy, Sa-lô-môn hoàn thành nhà của Đức Giê-hô-va, cùng nhà của vua, và mọi điều nảy ra trong lòng Sa-lô-môn để làm trong nhà của Đức Giê-hô-va và trong nhà mình, thì người đều làm thành công.'),
(11337, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 7, 12, 'OT', 'Đức Giê-hô-va hiện ra cùng với Sa-lô-môn trong ban đêm, và phán cùng người rằng: Ta đã nghe lời cầu nguyện của ngươi, và đã chọn nơi này cho Ta làm đền thờ để dâng tế lễ.'),
(11338, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 7, 13, 'OT', 'Nếu Ta đóng các từng trời khiến không có mưa, hoặc Ta truyền cho châu chấu đến đớp đất, hoặc Nếu Ta sai dịch hạch giữa dân Ta;'),
(11339, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 7, 14, 'OT', 'Nếu dân Ta, là những người được gọi danh Ta, tự hạ mình xuống, cầu nguyện, tìm kiếm mặt Ta và trở lại từ những đường lối ác của chúng, thì Ta sẽ nghe từ trời, tha thứ cho tội lỗi chúng và chữa lành đất nước của chúng.'),
(11340, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 7, 15, 'OT', 'Bây giờ, mắt Ta sẽ mở ra và tai Ta sẽ chăm nghe lời cầu nguyện dâng tại nơi này.'),
(11341, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 7, 16, 'OT', 'Và hiện nay, Ta đã chọn và biệt riêng ngôi nhà này, để danh Ta được ở đó đời đời; và mắt Ta cùng lòng Ta sẽ ở đó mọi ngày không thôi.'),
(11342, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 7, 17, 'OT', 'Và nếu ngươi bước đi trước mặt ta như Đa-vít cha ngươi đã làm, và làm theo mọi điều ta đã truyền cho ngươi, và giữ các luật lệ và các quyết định ta,'),
(11343, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 7, 18, 'OT', 'Ta sẽ lập vững ngôi vương quốc ngươi, như Ta đã lập giao ước với Đa-vít, cha ngươi, mà rằng: Ngươi sẽ không thiếu người cai trị trên Ít-ra-en.'),
(11344, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 7, 19, 'OT', 'Nếu các ngươi trở mình và lìa bỏ các mạng lịnh và điều răn Ta đã đặt trước mặt các ngươi, rồi đi theo và phục sự các thần khác, mà thờ lạy chúng nó;'),
(11345, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 7, 20, 'OT', 'Ta sẽ nhổ chúng ra khỏi đất Ta đã ban cho họ, và sẽ ném bỏ khỏi trước mặt Ta ngôi đền này mà Ta đã biệt riêng cho danh Ta; Ta sẽ khiến nó trở thành lời châm biếm và tiếng nhạo báng giữa mọi dân tộc.'),
(11346, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 7, 21, 'OT', 'Và nhà nầy, vốn rất cao, sẽ khiến mọi người đi ngang qua phải kinh ngạc; họ sẽ nói: "Tại sao Đức Giê-hô-va làm điều nầy cho đất nầy và cho nhà nầy?"'),
(11347, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 7, 22, 'OT', 'Và người ta sẽ nói: "Bởi chúng đã lìa bỏ Đức Giê-hô-va Đức Chúa Trời của tổ tiên chúng, Đấng đã đưa họ ra khỏi đất Ai Cập; chúng bám víu vào các thần khác, cúi lạy và phục sự các thần ấy. Vì cớ đó, Ngài đã giáng trên họ mọi điều dữ hại này."'),
(11348, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 8, 1, 'OT', 'Hết hai mươi năm, tức là thời gian mà Sa-lô-môn đã xây đền của Đức Giê-hô-va và cung điện của mình,'),
(11349, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 8, 2, 'OT', 'Các thành mà Hô-ram đã trao cho Sa-lô-môn, thì Sa-lô-môn xây cất chúng, và đặt con cái Ít-ra-en ở đó.'),
(11350, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 8, 3, 'OT', 'Vua Sa-lô-môn đi đến Ha-mát-xô-ba, rồi củng cố quyền kiểm soát nơi đó.'),
(11351, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 8, 4, 'OT', 'Ngài xây thành Tadmor trong đồng vắng, và tất cả các thành chứa của cải mà Ngài đã xây tại Hamath.'),
(11352, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 8, 5, 'OT', 'Người xây dựng thành Bết-hô-rôn trên và thành Bết-hô-rôn dưới, các thành có vách thành kiên cố, cửa và then cửa.'),
(11353, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 8, 6, 'OT', 'Và Ba-a-lát, và tất cả các thành chứa hàng hóa mà Sa-lô-môn có, và tất cả các thành xe chiến, và các thành của các kỵ binh, và tất cả các thành mà Sa-lô-môn mong muốn xây cất tại Giê-ru-sa-lem, và tại Li-băng, và khắp mọi nơi trong lãnh thổ quyền cai trị của ông.'),
(11354, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 8, 7, 'OT', 'Tất cả những người còn sót lại từ các dân Hê-th, A-mô-rị, Phê-ri-xi, Hê-vi và Giê-bu-xi, không phải là người Y-sơ-ra-ên,'),
(11355, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 8, 8, 'OT', 'Từ con cháu của họ, là những người còn sót lại sau họ trong đất, mà con cái Y-sơ-ra-ên đã không tiêu diệt, thì Sa-lô-môn bắt họ phải phục dịch lao dịch cho đến ngày nay.'),
(11356, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 8, 9, 'OT', 'Nhưng trong con cái Y-sơ-ra-ên, vua Sa-lô-môn không đặt làm đầy tớ cho công việc của mình; vì họ là những người lính chiến, các quan chỉ huy đội trưởng, các quan chỉ huy xe chiến và kỵ binh của người.'),
(11357, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 8, 10, 'OT', 'Và đây là các quan trưởng trong số những người được vua Sô-lô-môn đặt ra, gồm hai trăm năm mươi người, cai trị dân chúng.'),
(11358, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 8, 11, 'OT', 'Vua Sa-lô-môn dời con gái của Pha-ra-ôn từ thành Đa-vít lên nhà mà ông đã xây cho bà; vì ông nói: "Vợ ta không được ở trong nhà của Đa-vít, vua Ít-ra-en, vì những nơi ấy là thánh, tức là nơi hòm giao ước của Đức Giê-hô-va đã đến."'),
(11359, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 8, 12, 'OT', 'Bấy giờ, Sa-lô-môn dâng các của lễ thiêu cho Đức Giê-hô-va trên bàn thờ Đức Giê-hô-va, là bàn thờ mà người đã xây dựng trước hành lang,'),
(11360, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 8, 13, 'OT', 'Theo định kỳ hằng ngày, dâng của lễ theo mạng lịnh của Môi-se, trong các ngày Sa-bát, các ngày đầu tháng và các lễ hội, ba lần mỗi năm, là lễ Vượt Qua, lễ Tuần Thất và lễ Lều Tạm.'),
(11361, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 8, 14, 'OT', 'Ngài thiết lập theo quy định của Đa-vít, cha mình, các nhóm thầy tế lễ theo nhiệm vụ của họ, và các người Lê-vi theo ca trực của họ để ca ngợi và phục vụ trước mặt các thầy tế lễ, theo bổn phận hằng ngày; còn các người giữ cửa thì theo các nhóm của họ canh giữ từng cổng; vì ấy chính là mệnh lệnh của Đa-vít, người của Đức Chúa Trời.'),
(11362, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 8, 15, 'OT', 'Họ không rời khỏi mệnh lệnh của vua về các thầy tế lễ và người Lê-vi trong bất cứ việc gì, hay về các kho tàng.'),
(11363, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 8, 16, 'OT', 'Vậy mọi công việc của Sa-lô-môn được hoàn tất, từ ngày đặt nền nhà của Đức Giê-hô-va cho đến khi nhà ấy được xây xong; nhà của Đức Giê-hô-va đã được xây cất hoàn chỉnh.'),
(11364, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 8, 17, 'OT', 'Bấy giờ, Sa-lô-môn đi đến Ê-xi-ôn-ghê-be và đến Ê-lốt, ở bên bờ biển trong đất Ê-dôm.'),
(11365, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 8, 18, 'OT', 'Vua Hu-ram sai các đầy tớ mình mang tàu và các đầy tớ biết đường biển đến cùng các đầy tớ của vua Sa-lô-môn đi đến Ô-phia, lấy ở đó bốn trăm năm mươi vạc vàng, rồi mang về dâng cho vua Sa-lô-môn.'),
(11366, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 9, 1, 'OT', 'Vua nữ xứ Sê-ba nghe danh tiếng của vua Sô-lô-môn, bèn đến Giê-ru-sa-lem để thử vua Sô-lô-môn bằng những câu đố khó, cùng một đoàn tùy tùng rất đông đảo, và những con lạc đà chở đầy các thứ hương liệu, vàng rất nhiều, và những viên ngọc quí; bà đến gặp vua Sô-lô-môn và nói với ông tất cả những điều đang chất chứa trong lòng bà.'),
(11367, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 9, 2, 'OT', 'Vua Sa-lô-môn đã đáp cho bà tất cả những điều bà hỏi; chẳng có điều gì mà Sa-lô-môn giấu bà, vì người đã nói cho bà biết mọi điều ấy.'),
(11368, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 9, 3, 'OT', 'Bà hoàng hậu nước Sê-ba thấy sự khôn ngoan của Sa-lô-môn và ngôi nhà mà ông đã xây.'),
(11369, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 9, 4, 'OT', 'Và thức ăn trên bàn của ông, chỗ ngồi của các đầy tớ ông, sự phục vụ của các quan viên ông, và y phục của họ; các người rót rượu của ông, và y phục của họ; cùng với lối đi lên mà ông dùng để lên đền thờ của Đức Giê-hô-va; rồi bà không còn hơi sức nào nữa.'),
(11370, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 9, 5, 'OT', 'Bà nói với nhà vua: "Thật đúng như lời tôi đã nghe trong xứ tôi về các việc của ngài và sự khôn ngoan của ngài.'),
(11371, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 9, 6, 'OT', 'Tôi đã không tin những lời họ nói, cho đến khi tôi đến tận nơi và mắt tôi đã thấy; và này, người ta chỉ mới nói cho tôi biết một nửa về sự khôn ngoan vĩ đại của ngài; ngài vượt xa danh tiếng mà tôi đã nghe.'),
(11372, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 9, 7, 'OT', 'Phước cho những người của vua, và phước cho các đầy tớ của vua, những người luôn luôn đứng trước mặt vua và nghe sự khôn ngoan của vua.'),
(11373, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 9, 8, 'OT', 'Đức Giê-hô-va Đức Chúa Trời ngươi đáng được ca ngợi, là Đấng đã yêu thương ngươi để đặt ngươi ngồi trên ngôi vua cho Đức Giê-hô-va Đức Chúa Trời ngươi, vì Đức Chúa Trời ngươi yêu dân Ít-ra-en và muốn lập họ vững chắc đời đời, nên Ngài đã đặt ngươi làm vua cai trị họ, để thi hành sự xét đoán và công bình.'),
(11374, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 9, 9, 'OT', 'Bà hoàng hậu đã dâng cho vua một trăm hai mươi kikar vàng, rất nhiều hương liệu và các loại đá quí; không có thứ hương liệu nào giống như thứ hương liệu mà nữ vương xứ Sê-ba đã dâng cho vua Sa-lô-môn.'),
(11375, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 9, 10, 'OT', 'Các đầy tớ của Hi-ram và các đầy tớ của Sa-lô-môn, là những người đã mang vàng từ Ô-phi, cũng mang gỗ algum và những viên đá quý.'),
(11376, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 9, 11, 'OT', 'Vua dùng các cây gỗ algum làm những bậc cấp cho đền thờ của Đức Giê-hô-va và cho cung điện của vua, cùng những cây đờn cầm và đờn lia cho các nhạc công; và những vật ấy chưa từng thấy trước đó tại đất Giu-đa.'),
(11377, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 9, 12, 'OT', 'Vua Sa-lô-môn ban cho nữ vương xứ Sê-ba mọi điều lòng bà mong muốn, bất cứ điều gì bà xin, ngoài những gì bà đã mang đến cho vua. Sau đó, bà trở về, đi về xứ mình cùng các tôi tớ của bà.'),
(11378, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 9, 13, 'OT', 'Số lượng vàng mà Sa-lô-môn nhận được trong một năm là sáu trăm sáu mươi sáu ta-lâng vàng.'),
(11379, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 9, 14, 'OT', 'Ngoài những người buôn bán và thương gia mang đến, thì mọi vua của Ả-rập và các quan tổng trấn trong đất đều mang vàng và bạc đến cho Sa-lô-môn.'),
(11380, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 9, 15, 'OT', 'Vua Sa-lô-môn làm hai trăm cái khiên bằng vàng ròng; sáu trăm siếc-ên vàng ròng dùng để làm một cái khiên.'),
(11381, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 9, 16, 'OT', 'Ba trăm cái khiên làm bằng vàng giát mỏng; mỗi cái khiên dùng ba trăm chỉ vàng, và nhà vua đặt những cái khiên ấy trong nhà Rừng Li-băng.'),
(11382, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 9, 17, 'OT', 'Vua làm một ngôi ngai bằng ngà voi rất lớn, và bọc toàn bộ bằng vàng ròng.'),
(11383, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 9, 18, 'OT', 'Sáu bậc dẫn lên ngôi báu, và một bệ chân bằng vàng gắn liền với ngôi báu; hai bên chỗ ngồi có tay vịn, và hai con sư tử đứng cạnh các tay vịn.'),
(11384, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 9, 19, 'OT', 'Và mười hai con sư tử đứng đó, sáu con ở một bên và sáu con ở bên kia, trên sáu bậc thang. Không có cái nào giống như vậy được làm ra trong bất kỳ vương quốc nào.'),
(11385, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 9, 20, 'OT', 'Tất cả các đồ dùng uống của vua Sô-lô-môn đều bằng vàng, và mọi đồ dùng trong nhà Rừng Li-ban đều bằng vàng ròng; trong đời Sô-lô-môn, bạc không được coi là gì cả.'),
(11386, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 9, 21, 'OT', 'Vì các tàu của nhà vua đi Tar-si với các đầy tớ của Hu-ram; cứ ba năm một lần, các tàu Tar-si đến mang theo vàng, bạc, ngà, khỉ và công.'),
(11387, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 9, 22, 'OT', 'Vua Sa-lô-môn trở nên vĩ đại hơn mọi vua trên đất về sự giàu có và sự khôn ngoan.'),
(11388, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 9, 23, 'OT', 'Mọi vua các nước đều tìm đến diện kiến vua Sa-lô-môn để nghe sự khôn ngoan mà Đức Chúa Trời đã đặt trong lòng vua.'),
(11389, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 9, 24, 'OT', 'Họ mỗi người mang lễ vật của mình đến, gồm đồ bằng bạc, đồ bằng vàng, áo xống, khí giới, hương liệu, ngựa và lừa, mỗi năm một lần.'),
(11390, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 9, 25, 'OT', 'Vua Sa-lô-môn có bốn ngàn chuồng ngựa và xe ngựa, cùng mười hai ngàn ngựa, và người cất giữ chúng trong các thành xe ngựa và cùng với vua tại Giê-ru-sa-lem.'),
(11391, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 9, 26, 'OT', 'Người cai trị trên tất cả các vua, từ sông Ơ-phơ-rát cho đến đất của người Phi-li-tin và đến ranh giới của Ê-díp-tô.'),
(11392, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 9, 27, 'OT', 'Vua khiến bạc ở Giê-ru-sa-lem trở nên phổ biến như những viên đá, và khiến các cây bách hương được trồng nhiều như cây vả dại ở các vùng đồng bằng thấp.'),
(11393, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 9, 28, 'OT', 'Họ đưa ngựa đến cho Sa-lô-môn từ Ai Cập và từ mọi xứ.'),
(11394, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 9, 29, 'OT', 'Còn những việc khác của Sa-lô-môn, cả những việc đầu tiên và cuối cùng, há chẳng phải đã được chép trong sách Các lời của Na-than, nhà tiên tri, và trong lời tiên tri của A-hi-ya ở Si-lô, và trong các thị kiến của Ích-đô, nhà tiên kiến, về Giê-rô-bô-am, con trai của Nê-bát sao?'),
(11395, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 9, 30, 'OT', 'Vua Sa-lô-môn trị vì tại Giê-ru-sa-lem trên toàn thể Ít-ra-en bốn mươi năm.'),
(11396, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 9, 31, 'OT', 'Vua Sa-lô-môn nằm nghỉ cùng các tổ tiên mình và được chôn trong thành Đa-vít, cha của người; rồi vua Rê-hô-bô-am, con trai người, lên ngôi kế vị.'),
(11397, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 10, 1, 'OT', 'Rê-ha-ba-am đi đến Sêm, vì toàn thể Y-sơ-ra-ên đã đến Sêm để tôn ông làm vua.'),
(11398, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 10, 2, 'OT', 'Khi Giê-rô-bô-am con trai của Nê-bát, đang ở Ai Cập, nơi người đã trốn tránh mặt vua Sa-lô-môn, nghe tin ấy, thì Giê-rô-bô-am liền trở về từ Ai Cập.'),
(11399, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 10, 3, 'OT', 'Họ sai người đi và gọi ông ấy. Vậy nên Giê-rô-bô-am và toàn thể Y-sơ-ra-ên đến và nói với Rê-hô-bô-am rằng:'),
(11400, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 10, 4, 'OT', 'Cha ngươi đã làm cho ách chúng tôi nặng nề; vậy bây giờ hãy làm nhẹ bớt công việc nặng nề và cái ách nặng mà cha ngươi đã đặt trên chúng tôi, thì chúng tôi sẽ phục sự ngươi.'),
(11401, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 10, 5, 'OT', 'Hãy trở lại cùng ta sau ba ngày nữa. Dân chúng liền đi khỏi.'),
(11402, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 10, 6, 'OT', 'Vua Rê-ha-bâm đã tham vấn các bậc lão thành đã từng hầu trước mặt Sa-lô-môn, cha vua, khi người còn sống, và nói: "Theo các ông, tôi nên trả lời dân này điều gì?"'),
(11403, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 10, 7, 'OT', 'Họ nói với người rằng: "Nếu ngươi đối xử tốt với dân này, làm hài lòng họ, và nói những lời tốt lành với họ, thì họ sẽ làm đầy tớ cho ngươi trọn đời."'),
(11404, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 10, 8, 'OT', 'Nhưng người đã bỏ lời khuyên của những người già mà đã tư vấn cho người, và người đã tham khảo ý kiến của những người trẻ tuổi đã lớn lên cùng với người, những người phục vụ trước mặt người.'),
(11405, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 10, 9, 'OT', 'Người nói với họ: "Các ngươi nghĩ sao, chúng ta nên trả lời dân này điều gì, là dân đã nói với ta rằng: ''Hãy giảm nhẹ ách mà cha ngươi đã đặt trên chúng ta''?"'),
(11406, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 10, 10, 'OT', 'Các người trẻ tuổi đã lớn lên cùng với người ấy nói với người ấy rằng: "Hãy nói như thế này với dân chúng, là những người đã nói với ngài rằng: ''Cha ngài đã làm cho ách chúng tôi nặng nề; vậy bây giờ xin ngài làm cho nhẹ bớt khỏi chúng tôi''; hãy nói với họ rằng: ''Ngón tay út của tôi còn dày hơn hông cha tôi.''"'),
(11407, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 10, 11, 'OT', 'Bây giờ, cha ta đã đặt ách nặng trên các ngươi, còn ta sẽ gia tăng thêm ách của các ngươi; cha ta đã sửa trị các ngươi bằng roi, còn ta sẽ sửa trị các ngươi bằng bọ cạp.'),
(11408, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 10, 12, 'OT', 'Vậy Giả-đi-âm và toàn thể dân chúng đến cùng Rê-hô-bô-am vào ngày thứ ba, như vua đã dặn rằng: "Hãy trở lại cùng ta vào ngày thứ ba."'),
(11409, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 10, 13, 'OT', 'Vua đáp lại họ cách thô bạo; vua Rê-hô-bô-am từ bỏ lời khuyên của các bậc già cả.'),
(11410, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 10, 14, 'OT', 'Người đáp lại họ theo lời khuyên của các người trẻ, nói rằng: "Cha ta đã làm cho ách các ngươi nặng, nhưng ta sẽ làm cho nó nặng thêm; cha ta đã sửa trị các ngươi bằng roi, còn ta sẽ sửa trị các ngươi bằng roi bọ cạp."'),
(11411, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 10, 15, 'OT', 'Vua không nghe theo dân chúng; vì sự việc xảy ra là do từ Đức Chúa Trời, để Đức Giê-hô-va thực hiện lời Ngài đã phán qua tay A-hi-ha người Si-lô, cho Giê-rô-bô-am con trai của Nê-bát.'),
(11412, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 10, 16, 'OT', 'Khi toàn thể Y-sơ-ra-ên thấy vua chẳng chịu nghe theo mình, thì dân chúng đáp lại vua rằng: "Chúng tôi có phần chi trong Đa-vít đâu, và chẳng có cơ nghiệp gì trong con trai Y-sai cả! Hỡi người Y-sơ-ra-ên, mỗi người về lều mình đi! Còn Đa-vít, hãy lo cho nhà của ông đi!" Thế rồi toàn thể Y-sơ-ra-ên đều về lều mình.'),
(11413, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 10, 17, 'OT', 'Còn các con trai của Y-sơ-ra-ên sống trong các thành của Giu-đa, thì Rê-ha-ba-am làm vua cai trị họ.'),
(11414, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 10, 18, 'OT', 'Vua Rê-hô-bô-am sai Ha-đô-ram, người cai quản việc cống nạp; nhưng các con trai của Y-sơ-ra-ên đã ném đá ông đến chết. Vua Rê-hô-bô-am vội vã lên xe mình để chạy trốn về Giê-ru-sa-lem.'),
(11415, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 10, 19, 'OT', 'Và Y-sơ-ra-ên đã phạm tội phản nghịch nhà Đa-vít cho đến ngày nay.'),
(11416, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 11, 1, 'OT', 'Vua Rê-ha-be-am về Giê-ru-sa-lem, bèn nhóm lại nhà Giu-đa và Bên-gia-min, một trăm tám mươi ngàn người trai trẻ, toàn là chiến sĩ, để đánh giặc cùng Y-sơ-ra-ên, hầu phục hồi vương quyền cho Rê-ha-be-am.'),
(11417, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 11, 2, 'OT', 'Lời của Đức Giê-hô-va phán cùng Sê-ma-ia, người của Đức Chúa Trời, rằng:'),
(11418, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 11, 3, 'OT', 'Hãy nói cùng Rê-ha-bâm, con trai của Sa-lô-môn, vua nước Giu-đa, và cùng cả Ít-ra-ên ở trong Giu-đa và Bên-gia-min, rằng:'),
(11419, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 11, 4, 'OT', 'Đức Giê-hô-va phán như vầy: "Các ngươi không được đi lên, cũng không được chiến đấu cùng anh em mình. Hãy trở về mỗi người vào nhà mình, vì điều này là do Ta." Vậy họ vâng theo lời Đức Giê-hô-va và trở về, không đi đánh Giê-rô-bô-am.'),
(11420, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 11, 5, 'OT', 'Rê-ha-ba-am ở lại Giê-ru-sa-lem, và người xây các thành để phòng vệ trong xứ Giu-đa.'),
(11421, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 11, 6, 'OT', 'Người xây dựng Bết-lem, và Ê-tam, và Tê-koa.'),
(11422, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 11, 7, 'OT', 'Và Bết-xu, và Sô-kô, và A-đu-lam.'),
(11423, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 11, 8, 'OT', 'Và Gat, và Ma-rê-sa, và Xíp.'),
(11424, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 11, 9, 'OT', 'Và A-đô-ra-im, và La-ki, và A-xê-ka,'),
(11425, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 11, 10, 'OT', 'Và Xô-ra, và Ai-ja-lôn, và Hếp-rôn, là những thành được xây thành lũy ở Giu-đa và Bên-gia-min.'),
(11426, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 11, 11, 'OT', 'Và người củng cố các thành pháo đài, đặt các quan chỉ huy vào đó, cùng những kho lương thực, dầu và rượu.'),
(11427, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 11, 12, 'OT', 'Mỗi thành phố và thành phố, ông đặt những cái khiên và ngọn giáo, và làm cho chúng trở nên rất mạnh; và ông có được Giu-đa và Bên-gia-min đứng về phía mình.'),
(11428, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 11, 13, 'OT', 'Các thầy tế lễ và người Lê-vi ở khắp các nơi trong Y-sơ-ra-ên đều tập hợp về với ông, từ mọi miền xứ của họ.'),
(11429, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 11, 14, 'OT', 'Vì các thầy Lê-vi đã bỏ những vùng đất đệm quanh các thành của họ và ruộng đất được chỉ định cho họ, rồi đến với Giu-đa và Giê-ru-sa-lem; vì Giê-rô-bô-am và các con trai ông đã loại bỏ họ khỏi chức vụ tế lễ cho Đức Giê-hô-va.'),
(11430, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 11, 15, 'OT', 'Người bổ nhiệm các thầy tế lễ cho các nơi cao, cho các thần rừng và cho các con bò con mà người đã làm.'),
(11431, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 11, 16, 'OT', 'Họ cùng với mọi chi phái của Y-sơ-ra-ên, những người dốc lòng tìm kiếm Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên, đều đến Giê-ru-sa-lem để dâng của lễ cho Đức Giê-hô-va Đức Chúa Trời của tổ tiên họ.'),
(11432, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 11, 17, 'OT', 'Họ củng cố vương quốc Giu-đa và làm cho Rê-hô-bô-am, con trai của Sa-lô-môn, được vững mạnh trong ba năm; vì trong ba năm ấy họ đi theo con đường của Đa-vít và Sa-lô-môn.'),
(11433, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 11, 18, 'OT', 'Rê-ha-ba-am lấy Ma-kha-lat, con gái của Giê-ri-mốt, con trai Đa-vít, và A-bi-hai, con gái Ê-li-áp, con trai Ích-sai, làm vợ.'),
(11434, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 11, 19, 'OT', 'Người đã sinh cho ông các con trai: Giêu-sơ, Sơ-ma-ri-a và Xa-ham.'),
(11435, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 11, 20, 'OT', 'Sau người đó, ông lấy Ma-a-ca, con gái của Áp-sa-lôm, và bà sinh cho ông A-bi-gia, A-tai, Xi-xa và Sê-lô-mít.'),
(11436, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 11, 21, 'OT', 'Vua Rê-ha-ba-am yêu Ma-a-ca, con gái của Áp-sa-lôm, hơn tất cả các vợ và các thứ thiếp mình; vì người đã lấy mười tám người vợ và sáu mươi người thiếp, và sinh được hai mươi tám con trai và sáu mươi con gái.'),
(11437, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 11, 22, 'OT', 'Vậy, Rê-hô-bô-am đặt A-bi-gia, con trai của Ma-a-ca, lên làm người đứng đầu giữa các anh em mình, vì người định lập người ấy làm vua.'),
(11438, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 11, 23, 'OT', 'Và người đã xây dựng và mở rộng quyền lực của mình hơn tất cả các con trai mình, khắp mọi vùng đất của Giu-đa và Bên-gia-min, đến mọi thành có vách thành kiên cố; và người cấp cho họ lương thực dồi dào, và mong muốn có nhiều vợ.'),
(11439, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 12, 1, 'OT', 'Khi vương quốc của Rê-hô-bô-am được củng cố và người được củng cố quyền lực, thì người bỏ luật pháp của Đức Giê-hô-va, và cả Ít-ra-en cùng theo người.'),
(11440, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 12, 2, 'OT', 'Năm thứ năm đời vua Rô-hô-ba-m, Si-sắc, vua Ê-díp-tô, kéo lên nghịch cùng Giê-ru-sa-lem, vì chúng đã phạm tội nghịch cùng Đức Giê-hô-va.'),
(11441, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 12, 3, 'OT', 'Một ngàn hai trăm xe, và sáu mươi ngàn kỵ binh; dân chúng đi theo người từ Ai Cập thì vô số kể, gồm người Lu-bim, người Su-ki-im và người Cu-si.'),
(11442, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 12, 4, 'OT', 'Ông chiếm lấy các thành có vách thành thuộc về Giu-đa, rồi tiến đến Giê-ru-sa-lem.'),
(11443, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 12, 5, 'OT', 'Đoạn Semaia, đấng tiên tri, đến cùng Roboam và các quan trưởng Giu-đa đã nhóm hiệp tại Giê-ru-sa-lem vì cớ Si-sắc, thì nói với họ rằng: Đức Giê-hô-va phán như thế này: Các ngươi đã lìa bỏ Ta, nên Ta cũng lìa bỏ các ngươi vào tay Si-sắc.'),
(11444, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 12, 6, 'OT', 'Các quan trưởng của Y-sơ-ra-ên và vua bèn khiêm nhường xuống; họ nói rằng: Đức Giê-hô-va là công chính.'),
(11445, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 12, 7, 'OT', 'Khi Đức Giê-hô-va thấy họ tự hạ mình, thì có lời Đức Giê-hô-va phán cùng Sê-ma-ya rằng: Chúng nó đã tự hạ mình; ta sẽ không tiêu diệt chúng nó, mà sẽ cho chúng nó một ít cơ hội thoát nạn; và cơn thịnh nộ của ta sẽ không đổ ra trên Giê-ru-sa-lem bởi tay Si-sắc.'),
(11446, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 12, 8, 'OT', 'Dù vậy, chúng sẽ làm tôi tớ cho nó, để chúng biết sự phục vụ của Ta và sự phục vụ các vương quốc các nước.'),
(11447, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 12, 9, 'OT', 'Vua Si-sắc của Ê-díp-tô đi lên đánh Giê-ru-sa-lem, và cất lấy các kho báu trong nhà Đức Giê-hô-va và các kho báu trong nhà vua; người lấy tất cả; người cũng lấy các cái khiên bằng vàng mà Sa-lô-môn đã làm.'),
(11448, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 12, 10, 'OT', 'Vua Rê-ha-bâm đã làm những cái khiên bằng đồng thay thế những cái đó, và giao chúng cho các quan chỉ huy đội quân canh giữ cửa vào nhà vua.'),
(11449, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 12, 11, 'OT', 'Mỗi khi vua vào đền thờ của Đức Giê-hô-va, các vệ binh liền đến khiêng những cái khiên đó đi và mang trở lại phòng các vệ binh.'),
(11450, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 12, 12, 'OT', 'Khi người hạ mình xuống, cơn thịnh nộ của Đức Giê-hô-va quay khỏi người, không tiêu diệt người hoàn toàn; và cũng tại Giu-đa, các việc tốt đẹp đã xảy ra.'),
(11451, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 12, 13, 'OT', 'Vua Rê-ha-bâm củng cố quyền lực tại Giê-ru-sa-lem và trị vì; Rê-ha-bâm được bốn mươi mốt tuổi khi người bắt đầu trị vì, và người trị vì mười bảy năm tại Giê-ru-sa-lem, thành phố mà Đức Giê-hô-va đã chọn từ giữa mọi chi phái của Y-sơ-ra-ên để đặt danh Ngài tại đó. Tên mẹ người là Na-a-ma, người Am-môn.'),
(11452, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 12, 14, 'OT', 'Và người đã làm điều ác, vì người không định lòng tìm kiếm Đức Giê-hô-va.'),
(11453, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 12, 15, 'OT', 'Các việc đầu tiên và cuối cùng của Rê-ha-bô-am, chẳng phải đã được chép trong sách các lời của Sê-ma-ia, nhà tiên tri, và Ít-đô, nhà thấy thị, về các gia phả sao? Và các cuộc chiến tranh giữa Rê-ha-bô-am và Giê-rô-bô-am xảy ra suốt các ngày ấy.'),
(11454, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 12, 16, 'OT', 'Rê-ha-ba-am nằm nghỉ cùng với các tổ tiên mình và được chôn trong thành Đa-vít; và A-bi-gia, con trai ông, lên ngôi kế vị ông.'),
(11455, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 13, 1, 'OT', 'Trong năm thứ mười tám đời vua Giê-rô-bô-am, A-bi-gia lên ngôi làm vua cai trị trên Giu-đa.'),
(11456, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 13, 2, 'OT', 'Ông trị vì ba năm tại Giê-ru-sa-lem. Tên mẹ ông là Mi-cai-a, con gái của U-ri-ên ở Ghíp-tha. Và có chiến tranh giữa A-bi-gia và Giê-rô-bô-am.'),
(11457, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 13, 3, 'OT', 'A-bi-gia bày trận với đạo quân gồm bốn trăm ngàn chiến sĩ can đảm và tinh nhuệ; còn Giê-rô-bô-am cũng bày trận nghịch lại người với tám trăm ngàn chiến sĩ tinh nhuệ và hùng mạnh.'),
(11458, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 13, 4, 'OT', 'A-bi-gia đứng dậy trên núi Xe-ma-ra-im, thuộc vùng núi Ép-ra-im, rồi nói: Hãy nghe tôi, hỡi Giê-rô-bô-am và toàn thể Ít-ra-en!'),
(11459, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 13, 5, 'OT', 'Chẳng lẽ các ngươi không biết rằng Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên đã ban vương quyền trên Y-sơ-ra-ên đời đời cho Ða-vít và cho các con trai người bởi một giao ước muối?'),
(11460, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 13, 6, 'OT', 'Nhưng Giê-rô-bô-am, con trai của Nê-bát, tôi tớ của Sa-lô-môn, con trai Đa-vít, đã nổi dậy chống lại chủ mình.'),
(11461, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 13, 7, 'OT', 'Có những kẻ vô ích, con cái của Bê-li-a, đã tụ họp lại cùng hắn và củng cố sức mạnh chống lại Rê-hô-bô-am, con trai của Sa-lô-môn; còn Rê-hô-bô-am thì trẻ tuổi và nhu nhược, nên không thể chống cự nổi chúng.'),
(11462, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 13, 8, 'OT', 'Bây giờ các ngươi nói rằng mình sẽ mạnh lên chống lại vương quốc của Đức Giê-hô-va trong tay các con trai của Đa-vít; các ngươi đông đảo, và cùng các ngươi có những con bò vàng mà Giê-rô-bô-am đã làm cho các ngươi để thờ làm thần.'),
(11463, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 13, 9, 'OT', 'Các ngươi há chẳng đã đuổi khỏi các thầy tế lễ của Đức Giê-hô-va, tức con cháu A-rôn và người Lê-vi, mà tự làm cho mình những thầy tế lễ như các dân tộc trong các xứ? Bất cứ ai đến, dâng tay mình với một con bò đực và bảy con chiên đực, thì người ấy trở thành thầy tế lễ cho những thần không phải là Đức Chúa Trời.'),
(11464, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 13, 10, 'OT', 'Nhưng về phần chúng tôi, Đức Giê-hô-va là Đức Chúa Trời của chúng tôi, và chúng tôi không từ bỏ Ngài; các thầy tế lễ phục sự Đức Giê-hô-va là con cháu của A-ha-ron, và những người Lê-vi đảm nhiệm công việc của mình.'),
(11465, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 13, 11, 'OT', 'Họ dâng của lễ thiêu cho Đức Giê-hô-va mỗi buổi sáng và mỗi buổi tối, dâng hương thơm, bày bánh trần thiết trên bàn thánh khiết, và cây đèn vàng cùng các ngọn đèn của nó để thắp sáng mỗi buổi tối; vì chúng tôi giữ trọn bổn phận thờ phượng Đức Giê-hô-va Đức Chúa Trời chúng tôi, còn các ngươi thì đã lìa bỏ Ngài.'),
(11466, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 13, 12, 'OT', 'Nầy, Đức Chúa Trời và các thầy tế lễ của Ngài ở cùng chúng tôi, với các kèn thổi tiếng kêu chiến để chống lại các ngươi. Hỡi con cái Y-sơ-ra-ên, đừng chiến đấu chống lại Đức Giê-hô-va Đức Chúa Trời của tổ tiên các ngươi, vì các ngươi sẽ không được thạnh vượng.'),
(11467, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 13, 13, 'OT', 'Nhưng Giê-rô-bô-am đã bố trí một toán phục kích để tấn công phía sau họ; và họ ở trước mặt Giu-đa, còn toán phục kích thì ở phía sau họ.'),
(11468, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 13, 14, 'OT', 'Người Giu-đa quay lại, thì thấy mình bị đánh giáp hai mặt, trước và sau; họ kêu lên cùng Đức Giê-hô-va, và các thầy tế lễ thổi kèn.'),
(11469, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 13, 15, 'OT', 'Bấy giờ các người của Giu-đa reo lên tiếng; và khi các người của Giu-đa đang reo lên tiếng, thì Đức Chúa Trời đánh bại Giê-rô-bô-am và toàn thể Ít-ra-en trước mặt A-bi-gia và Giu-đa.'),
(11470, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 13, 16, 'OT', 'Con cái Y-sơ-ra-ên đã chạy trốn khỏi mặt Giu-đa, và Đức Chúa Trời đã phó chúng nó vào tay người.'),
(11471, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 13, 17, 'OT', 'A-bi-a và dân sự người đánh họ một đòn rất nặng; và có năm trăm ngàn người trai tráng của Y-sơ-ra-ên ngã ra chết.'),
(11472, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 13, 18, 'OT', 'Các con trai của Y-sơ-ra-ên bị khuất phục trong thời gian ấy, còn các con trai của Giu-đa thì trở nên mạnh mẽ, vì họ nương dựa vào Đức Giê-hô-va Đức Chúa Trời của tổ tiên mình.'),
(11473, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 13, 19, 'OT', 'Áp-hi-gia đuổi theo Giê-rô-bô-am, và chiếm các thành từ người đó, là Bê-tên cùng các thành thuộc về nó, và Giê-sa-na cùng các thành thuộc về nó, và Ê-phơ-rain cùng các thành thuộc về nó.'),
(11474, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 13, 20, 'OT', 'Giê-rô-bô-am không còn được mạnh mẽ nữa trong đời A-bi-gia; và Đức Giê-hô-va đánh phạt người, rồi người qua đời.'),
(11475, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 13, 21, 'OT', 'Abi-gia-vu trở nên cường thạnh, lấy mười bốn người vợ, và sinh hai mươi hai con trai và mười sáu con gái.'),
(11476, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 13, 22, 'OT', 'Phần còn lại về các việc của A-bi-gia, các đường lối và các lời nói của người, đều được chép trong sách các truyện kể của đấng tiên tri Ích-đô.'),
(11477, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 14, 1, 'OT', 'A-bi-a nằm nghỉ cùng với tổ tiên mình, người ta chôn ông trong thành Đa-vít; A-sa, con trai ông, lên ngôi vua thay ông. Trong đời ông, đất nước được yên ổn mười năm.'),
(11478, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 14, 2, 'OT', 'A-sa làm điều thiện và ngay thẳng trong mắt Đức Giê-hô-va, Đức Chúa Trời của ông.'),
(11479, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 14, 3, 'OT', 'Ông loại bỏ các bàn thờ của các thần ngoại đạo và các nơi cao, đập vỡ các trụ thờ A-sê-ra, và chặt các cây thờ thần.'),
(11480, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 14, 4, 'OT', 'Và người ra lệnh cho Giu-đa phải tìm kiếm Đức Giê-hô-va Đức Chúa Trời của tổ tiên họ, và thực hành luật pháp cùng các điều răn.'),
(11481, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 14, 5, 'OT', 'Người đã dẹp bỏ các nơi cao và các trụ thờ hình tượng khỏi mọi thành của Giu-đa, và vương quốc được an bình dưới thời người.'),
(11482, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 14, 6, 'OT', 'Người xây các thành có vách thành kiên cố trong xứ Giu-đa, vì đất được an nghỉ, và người không có chiến tranh trong những năm ấy, bởi vì Đức Giê-hô-va đã ban cho người sự yên nghỉ.'),
(11483, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 14, 7, 'OT', 'Bấy giờ người nói cùng Giu-đa rằng: "Hãy xây cất lại những thành nầy, và xây tường bao quanh, tháp canh, cửa và then cửa; đất đai còn ở trước mặt chúng ta, vì chúng ta đã tìm kiếm Đức Giê-hô-va Đức Chúa Trời chúng ta, thật lòng tìm kiếm Ngài, nên Ngài ban cho chúng ta sự an nghỉ xung quanh." Vậy họ xây cất và được thạnh vượng.'),
(11484, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 14, 8, 'OT', 'Asa có đạo quân mang khiên và giáo, người Giu-đa là ba trăm ngàn người; và người Bên-gia-min, những người mang thuẫn và kéo cung, là hai trăm tám mươi ngàn người; tất cả những người này đều là các dũng sĩ tinh nhuệ.'),
(11485, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 14, 9, 'OT', 'Rồi Xe-ra người Ê-thi-ô-pi tiến đánh họ với đạo quân một triệu người và ba trăm cỗ xe, và đến tận Ma-rê-sa.'),
(11486, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 14, 10, 'OT', 'Rồi A-sa đi ra nghênh tiếp người ấy, và họ bày trận chiến trong thung lũng Xép-ha-ta, gần Ma-rê-sa.'),
(11487, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 14, 11, 'OT', 'Rồi Asa kêu cầu Đức Giê-hô-va Đức Chúa Trời mình, và nói: "Lạy Đức Giê-hô-va, chẳng có gì khó đối với Ngài để giúp, dù là người nhiều hay người không sức lực. Xin giúp chúng tôi, lạy Đức Giê-hô-va Đức Chúa Trời chúng tôi, vì chúng tôi tin cậy nơi Ngài, và nhân danh Ngài mà ra đi chống lại đoàn đông này. Lạy Đức Giê-hô-va Đức Chúa Trời chúng tôi, chính Ngài là Đức Chúa Trời của chúng tôi; xin đừng để loài người thắng được Ngài."'),
(11488, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 14, 12, 'OT', 'Đức Giê-hô-va đánh bại người Cu-si trước mặt A-sa và trước mặt Giu-đa, và người Cu-si chạy trốn.'),
(11489, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 14, 13, 'OT', 'Đoạn A-sa và dân sự đi cùng người đuổi theo chúng cho đến Ghê-ra. Dân Cút ngã xuống rất nhiều, không còn ai sống sót, vì chúng bị đánh bại trước mặt Đức Giê-hô-va và trước mặt đạo quân người. Chúng thu được rất nhiều chiến lợi phẩm.'),
(11490, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 14, 14, 'OT', 'Họ đánh bại tất cả các thành phố chung quanh Gê-ra, vì sự sợ hãi của Đức Giê-hô-va giáng trên họ; họ cướp phá tất cả các thành phố ấy, vì có rất nhiều chiến lợi phẩm trong các thành ấy.'),
(11491, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 14, 15, 'OT', 'Họ đánh phá các trại chăn nuôi, cướp đi rất nhiều chiên và lạc đà, rồi trở về Giê-ru-sa-lem.'),
(11492, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 15, 1, 'OT', 'Thần của Đức Chúa Trời ngự trên A-xa-ria, con trai của Ô-đết.'),
(11493, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 15, 2, 'OT', 'Vậy người ra đón A-sa, nói với ông: "Hãy nghe tôi, A-sa, và cả người Giu-đa và Bên-gia-min: Đức Giê-hô-va ở cùng các ngươi, nếu các ngươi ở cùng Ngài; các ngươi tìm kiếm Ngài thì Ngài sẽ để cho các ngươi gặp; nhưng nếu các ngươi lìa bỏ Ngài, thì Ngài sẽ lìa bỏ các ngươi."'),
(11494, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 15, 3, 'OT', 'Một thời gian dài, dân Y-sơ-ra-ên không có Đức Chúa Trời chân thật, không có thầy tế lễ dạy dỗ, và không có luật pháp.'),
(11495, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 15, 4, 'OT', 'Khi trong cơn khốn khó, họ trở lại cùng Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en, tìm kiếm Ngài, thì Ngài cho họ gặp được Ngài.'),
(11496, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 15, 5, 'OT', 'Và trong những thời kỳ ấy, không có sự bình an cho người ra cũng không cho người vào; vì có những cơn xao xuyến lớn trên khắp các dân cư trong các miền đất.'),
(11497, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 15, 6, 'OT', 'Các dân bị tiêu diệt lẫn nhau, các thành bị hủy diệt lẫn nhau, vì Đức Chúa Trời khiến chúng bối rối trong mọi cảnh khốn khó.'),
(11498, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 15, 7, 'OT', 'Hãy mạnh mẽ và đừng để tay các ngươi yếu đuối, vì sẽ có phần thưởng cho công việc của các ngươi.'),
(11499, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 15, 8, 'OT', 'Khi Asa nghe những lời nầy và lời tiên tri của Ođết, là đấng tiên tri, thì người được thêm sức mạnh, bèn dẹp bỏ các vật gớm ghiếc khỏi khắp đất Giu-đa và Bên-gia-min, cùng các thành mà người đã chiếm được từ núi Ép-ra-im, và người sửa lại bàn thờ của Đức Giê-hô-va, là bàn thờ ở trước hành lang của Đức Giê-hô-va.'),
(11500, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 15, 9, 'OT', 'Và ông tập hợp toàn thể Giu-đa và Bên-gia-min, cùng những người ngoại ngụ cư giữa họ từ Ép-ra-im, Ma-na-xe và Xi-mê-ôn; vì có rất nhiều người từ Ít-ra-en đầu phục ông, khi họ thấy Đức Giê-hô-va Đức Chúa Trời của ông ở cùng ông.'),
(11501, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 15, 10, 'OT', 'Họ nhóm lại tại Giê-ru-sa-lem trong tháng thứ ba, năm thứ mười lăm triều đại vua A-sa.'),
(11502, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 15, 11, 'OT', 'Họ dâng của lễ cho Đức Giê-hô-va trong ngày ấy, từ chiến lợi phẩm mà họ đã mang về: bảy trăm con bò và bảy ngàn con chiên.'),
(11503, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 15, 12, 'OT', 'Họ vào giao ước để tìm kiếm Đức Giê-hô-va, Đức Chúa Trời của tổ tiên họ, với trọn tấm lòng và trọn tâm hồn mình.'),
(11504, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 15, 13, 'OT', 'Phàm kẻ nào không tìm kiếm Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên thì sẽ bị xử tử, từ kẻ nhỏ đến người lớn, từ nam cho đến nữ.'),
(11505, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 15, 14, 'OT', 'Họ thề hứa cùng Đức Giê-hô-va bằng tiếng reo lớn, bằng tiếng la hét, bằng tiếng kèn và bằng tiếng tù và.'),
(11506, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 15, 15, 'OT', 'Cả Giu-đa đều vui mừng về lời thề; vì họ đã thề bằng trọn tấm lòng mình, và tìm kiếm Ngài với trọn ý muốn mình, thì được Ngài tỏ bày ra; và Đức Giê-hô-va ban cho họ sự yên nghỉ xung quanh.'),
(11507, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 15, 16, 'OT', 'Vua A-sa cũng cách chức Ma-a-ca, mẹ vua, khỏi chức hoàng hậu vì bà đã làm một hình tượng cho A-sê-ra; vua A-sa đốn hình tượng ấy, đập nát, đốt nó ở suối Ki-trôn.'),
(11508, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 15, 17, 'OT', 'Những nơi thờ thần trên các nơi cao thì không bị dẹp bỏ khỏi Y-sơ-ra-ên; tuy nhiên, lòng của A-sa luôn trọn vẹn đối với Đức Giê-hô-va suốt mọi ngày đời người.'),
(11509, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 15, 18, 'OT', 'Người mang vào đền thờ Đức Chúa Trời những vật thánh mà cha người và chính người đã biệt riêng ra, gồm bạc, vàng và các đồ dùng.'),
(11510, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 15, 19, 'OT', 'Và không có chiến tranh cho đến năm ba mươi lăm đời trị vì của A-sa.'),
(11511, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 16, 1, 'OT', 'Trong năm thứ ba mươi sáu triều đại của A-sa, Ba-a-sa, vua Y-sơ-ra-ên, kéo lên chống Giu-đa, và xây thành Ra-ma, để không cho ai ra vào được với A-sa, vua Giu-đa.'),
(11512, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 16, 2, 'OT', 'A-sa lấy bạc và vàng ra từ các kho báu trong đền thờ của Đức Giê-hô-va và trong các kho báu của vua, rồi sai đi cho Bên-ha-đát, vua nước A-ram, là người đang ở Đa-mách, rằng:'),
(11513, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 16, 3, 'OT', 'Có một giao ước giữa ta và ngươi, cũng như giữa cha ta và cha ngươi. Nầy, ta đã sai người mang bạc và vàng đến cho ngươi. Hãy đi, phá giao ước của ngươi với Baasha, vua Y-sơ-ra-ên, để người ấy rút quân khỏi ta.'),
(11514, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 16, 4, 'OT', 'Vua Bên-ha-đát nghe theo vua A-sa, rồi sai các tướng quân của mình đi đánh các thành của Y-sơ-ra-ên; chúng chiếm được Y-chôn, Đan, A-bên Mai-n, và mọi thành kho tàng của Nép-ta-li.'),
(11515, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 16, 5, 'OT', 'Khi Ba-sa nghe điều đó, ông ta liền ngưng việc xây dựng Ra-ma và bỏ dở công việc mình.'),
(11516, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 16, 6, 'OT', 'Vua A-sa triệu tập toàn thể người Giu-đa, và họ khiêng đi những tảng đá và gỗ tại Ra-ma, nơi Ba-a-sa đã xây dựng; rồi vua dùng những vật ấy xây cất Ghê-ba và Mít-pah.'),
(11517, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 16, 7, 'OT', 'Vào thời ấy, Ha-na-ni người thấy đến cùng Asa, vua Giu-đa, và nói với người: "Vì ngươi đã nương nhờ vua A-ram mà không nương nhờ Đức Giê-hô-va Đức Chúa Trời ngươi, nên đạo quân của vua A-ram đã thoát khỏi tay ngươi."'),
(11518, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 16, 8, 'OT', 'Há chẳng phải người Cu-si và người Lu-bim là một đạo quân đông đảo, với rất nhiều xe và kỵ binh sao? Nhưng vì ngươi đã nương tựa vào Đức Giê-hô-va, Ngài đã giao họ vào tay ngươi.'),
(11519, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 16, 9, 'OT', 'Vì Đức Giê-hô-va có mắt ngó khắp toàn đất, đặng tỏ ra quyền năng cùng những người nào lòng trọn vẹn hướng về Ngài. Ngươi đã làm điều dại dột về điều nầy; vì từ nay, ngươi sẽ có chiến tranh.'),
(11520, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 16, 10, 'OT', 'Đoạn A-sa nổi giận cùng người thấy rõ, và ông đã tống giam ông ấy vào ngục; vì cơn thịnh nộ của ông đối với điều này, nên trong thời gian ấy, A-sa đã hà hiếp một số người trong dân.'),
(11521, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 16, 11, 'OT', 'Nầy, các việc đầu tiên và cuối cùng của A-sa đều được chép trong sách các vua Giu-đa và Y-sơ-ra-ên.'),
(11522, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 16, 12, 'OT', 'Asa năm thứ ba mươi chín triều đại mình bị đau ở chân cho đến khi bệnh ông trở nên rất nặng; vậy mà trong lúc đau yếu, ông không cầu hỏi Đức Giê-hô-va, chỉ tìm đến các thầy thuốc.'),
(11523, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 16, 13, 'OT', 'A-sa nằm ngủ cùng các tổ phụ mình và qua đời trong năm thứ bốn mươi mốt đời trị vì của ông.'),
(11524, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 16, 14, 'OT', 'Người ta chôn ông trong các mồ mả của ông, mà ông đã đào sẵn cho mình trong thành Đa-vít; và họ đặt ông trên giường nằm đầy những hương liệu và các loại thuốc thơm, được chế theo nghề pha chế; họ đốt lửa thiêu rất lớn cho ông, đến nỗi cực kỳ huy hoàng.'),
(11525, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 17, 1, 'OT', 'Giô-sa-phát, con trai người, lên ngôi vua thay người và củng cố quyền lực chống lại Y-sơ-ra-ên.'),
(11526, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 17, 2, 'OT', 'Đặt các đạo quân vào mọi thành có vách thành vững chắc của Giu-đa, và đặt những đội quân canh giữ trong đất Giu-đa, và trong các thành của Ép-ra-im mà A-sa, cha người, đã chiếm được.'),
(11527, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 17, 3, 'OT', 'Đức Giê-hô-va ở cùng với Giô-sa-phát, vì người đi theo các đường lối đầu tiên của Đa-vít, cha mình, và không tìm theo các thần Ba-al.'),
(11528, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 17, 4, 'OT', 'Nhưng người đã tìm cầu Đức Chúa Trời của cha mình, và đi theo các điều răn của Ngài, chứ không làm theo các việc của Y-sơ-ra-ên.'),
(11529, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 17, 5, 'OT', 'Đức Giê-hô-va củng cố vương quốc trong tay người; và toàn thể Giu-đa dâng lễ vật cho Giô-sa-phát; và người có được sự giàu có và danh dự rất lớn.'),
(11530, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 17, 6, 'OT', 'Lòng người được nâng cao trong các đường lối của Đức Giê-hô-va; người còn dẹp bỏ các nơi cao và các trụ thờ hình thần A-sê-ra khỏi đất Giu-đa.'),
(11531, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 17, 7, 'OT', 'Vào năm thứ ba đời trị vì của ông, ông sai các quan trưởng mình là Ben-hai-l, Ô-ba-đi-a, Xa-cha-ri, Nét-ha-nên và Mi-cha-ia đến các thành của Giu-đa để dạy dỗ dân chúng.'),
(11532, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 17, 8, 'OT', 'Cùng với họ có các thầy Lê-vi là Sê-ma-gia, Nê-than-nia, Xê-ba-đia, A-xa-ên, Sê-mi-ra-mốt, Giê-hô-nát-han, A-đô-ni-gia, Tô-bi-gia, và Tô-ba-đô-ni-gia, những người Lê-vi; cùng với họ là Ê-li-xa-ma và Giê-hô-ram, các thầy tế lễ.'),
(11533, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 17, 9, 'OT', 'Họ dạy dỗ trong xứ Giu-đa, và mang theo sách Luật pháp của Đức Giê-hô-va, đi khắp các thành của Giu-đa mà dạy dân chúng.'),
(11534, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 17, 10, 'OT', 'Sự kính sợ Đức Giê-hô-va giáng trên tất cả các nước vương quốc xung quanh Giu-đa, và họ không gây chiến với Giô-sa-phát.'),
(11535, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 17, 11, 'OT', 'Các người Phi-li-tin mang lễ vật và bạc cống nạp cho Giô-sa-phát; cả người Ả-rập cũng mang đến cho ông chiên đực, bảy ngàn bảy trăm con, và dê đực, bảy ngàn bảy trăm con.'),
(11536, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 17, 12, 'OT', 'Giô-sa-phát tiếp tục phát triển mạnh cho đến rất cao trọng; người xây cất các thành lũy và các thành chứa kho tàng trong xứ Giu-đa.'),
(11537, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 17, 13, 'OT', 'Và ông có nhiều công việc ở các thành phố của Giu-đa; và những người lính chiến, các chiến binh dũng cảm, ở tại Giê-ru-sa-lem.'),
(11538, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 17, 14, 'OT', 'Và đây là số người theo các gia tộc của họ: thuộc về Giu-đa, các quan chỉ huy ngàn người, A-đa-na là người đứng đầu, và cùng ông có những chiến sĩ can đảm, ba trăm ngàn người.'),
(11539, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 17, 15, 'OT', 'Và dưới quyền ông là Giô-ha-nan, viên chỉ huy, cùng hai trăm tám mươi ngàn người.'),
(11540, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 17, 16, 'OT', 'Và người dưới quyền ông là Amasía, con trai của Xích-ri, người tình nguyện phục vụ Đức Giê-hô-va; và cùng ông có hai trăm ngàn chiến sĩ dũng cảm.'),
(11541, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 17, 17, 'OT', 'Còn từ Bên-gia-min, Ê-li-a-đa, một người tráng sĩ, và cùng người có hai trăm ngàn người lính thiện nghệ dùng cung và khiên.'),
(11542, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 17, 18, 'OT', 'Còn về tay ông, có Giô-xa-bát, và cùng ông ấy có một trăm tám mươi ngàn người lính tinh nhuệ đã sẵn sàng ra trận.'),
(11543, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 17, 19, 'OT', 'Đây là những người phục vụ vua, ngoài những người mà vua đặt tại các thành có vách thành kiên cố trong khắp cả Giu-đa.'),
(11544, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 1, 'OT', 'Vua Giô-sa-phát có nhiều của cải và danh dự, và người kết thông gia với A-háp.'),
(11545, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 2, 'OT', 'Sau một vài năm, người ấy đi xuống gặp A-háp tại Sa-ma-ri. A-háp đã giết chiên và bò làm tiệc lớn cho ông và cho dân chúng đi cùng ông, rồi xúi giục ông đi lên Ra-mốt Ga-la-át.'),
(11546, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 3, 'OT', 'A-háp, vua của Y-sơ-ra-ên, nói với Giô-sa-phát, vua của Giu-đa: "Ngươi có muốn đi với ta đến Ra-mốt trong Ghi-lê-át không?" Ông đáp: "Ta như ngươi, dân ta như dân ngươi, và chúng ta sẽ cùng đi với ngươi trong cuộc chiến."'),
(11547, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 4, 'OT', 'Đa-nh bi nói cùng vua Y-sơ-ra-ên: "Xin hãy cầu hỏi lời Đức Giê-hô-va hôm nay."'),
(11548, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 5, 'OT', 'Vua Y-sơ-ra-ên tập họp bốn trăm tiên tri, và nói với họ: "Ta có nên đi đánh Ra-mốt trong đất Ghi-lê-đa, hay nên kiềm chế?" Họ đáp: "Hãy đi lên, vì Đức Chúa Trời sẽ trao nó vào tay vua."'),
(11549, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 6, 'OT', 'Giô-sa-phát hỏi: "Ở đây chẳng còn tiên tri nào của Đức Giê-hô-va sao, để chúng ta có thể hỏi người đó?"'),
(11550, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 7, 'OT', 'Vua Y-sơ-ra-ên nói với Giê-hô-sa-phát: "Còn một người nữa, nhờ người đó chúng ta có thể cầu hỏi Đức Giê-hô-va, nhưng tôi ghét người ấy, vì người ấy chẳng bao giờ nói tiên tri tốt lành về tôi, mà chỉ nói điều xấu mọi lúc; đó là Mi-cha, con trai của Y-ma-lá." Nhưng Giê-hô-sa-phát nói: "Xin vua chớ nói như vậy."'),
(11551, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 8, 'OT', 'Vua Y-sa-ra-ên gọi một viên quan cận vệ, rồi nói: "Hãy mau đi, dẫn Mi-cai-a, con trai của Y-ma-lá, đến đây."'),
(11552, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 9, 'OT', 'Vua Y-sơ-ra-ên và vua Giô-sa-phát, vua của Giu-đa, ngồi mỗi người trên ngôi mình, mặc các bộ áo dài, và ngồi ở nơi trống trải tại lối vào cổng thành Sa-ma-ri; và tất cả các đấng tiên tri đang nói tiên tri trước mặt hai người.'),
(11553, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 10, 'OT', 'Xê-đê-kia, con trai của Xê-na-an, làm cho vua những chiếc sừng bằng sắt và nói rằng: Đức Giê-hô-va phán như vầy: Ngươi sẽ dùng những cái này mà húc dân Sy-ria cho đến khi chúng bị tiêu diệt.'),
(11554, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 11, 'OT', 'Tất cả các nhà tiên tri đều nói tiên tri như vậy, rằng: "Hãy đi lên Râmôth Ghil-ead, và ngươi sẽ thành công; vì Đức Giê-hô-va sẽ trao nó vào tay vua."'),
(11555, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 12, 'OT', 'Và thiên sứ đã đi gọi Mi-cai-a nói với người rằng: "Này, các lời của các nhà tiên tri đều đồng lòng nói điều tốt lành cho vua; vậy nguyện lời của ngươi cũng như một trong các lời của họ, hãy nói điều tốt lành."'),
(11556, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 13, 'OT', 'Mi-cai-hu nói: "Nhân danh Đức Giê-hô-va, tôi sẽ nói điều mà Đức Chúa Trời tôi phán."'),
(11557, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 14, 'OT', 'Và khi người đến cùng vua, thì vua nói cùng người rằng: "Mi-cai-a, chúng ta có nên đi lên Râmôth trong xứ Ghilêad để giao chiến, hay là nên kiềm chế?" Người đáp: "Hãy đi lên, và sẽ thành công; chúng sẽ bị trao vào tay các ngài."'),
(11558, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 15, 'OT', 'Vua nói với ông: "Ta phải lấy danh Đức Giê-hô-va mà khiến ngươi thề mấy lần nữa, để ngươi chỉ nói sự thật với ta?"'),
(11559, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 16, 'OT', 'Rồi người nói: Tôi thấy toàn thể Y-sơ-ra-ên bị phân tán trên các ngọn núi, như những con chiên không có người chăn. Và Đức Giê-hô-va phán: Những người nầy không có chủ rồi; hãy để mỗi người trở về nhà mình trong bình an.'),
(11560, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 17, 'OT', 'Vua Y-sơ-ra-ên nói với Giê-hô-sa-phát: "Tôi há chẳng bảo ngài rằng người nầy sẽ không nói tiên tri lành cho tôi, mà chỉ nói điều dữ sao?"'),
(11561, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 18, 'OT', 'Vậy người nói: Bởi vậy, hãy nghe lời của Đức Giê-hô-va: Ta thấy Đức Giê-hô-va đang ngồi trên ngôi của Ngài, và toàn thể đạo binh thiên đàng đứng chầu bên phải Ngài và bên trái Ngài.'),
(11562, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 19, 'OT', 'Đức Giê-hô-va phán: "Ai sẽ dụ A-háp, vua Y-sơ-ra-ên, để người lên và ngã tại Ra-mốt trong Ghít-thê-ên?" Thì có người nói theo cách này, và người khác nói theo cách khác.'),
(11563, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 20, 'OT', 'Một thần linh đi ra, đứng trước mặt Đức Giê-hô-va và nói: "Tôi sẽ lừa kẻ ấy." Đức Giê-hô-va phán với người đó: "Ngươi sẽ làm bằng cách nào?"'),
(11564, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 21, 'OT', 'Rồi người ấy nói: "Tôi sẽ ra đi và làm thần lừa dối ở trong miệng mọi nhà tiên tri của vua." Đức Giê-hô-va phán: "Ngươi hãy lừa vua và ngươi sẽ thành công. Hãy ra đi và làm như vậy."'),
(11565, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 22, 'OT', 'Bây giờ, Đức Giê-hô-va đã đặt một thần dối trá trong miệng các tiên tri ngươi nầy, và Đức Giê-hô-va đã phán điều dữ nghịch cùng ngươi.'),
(11566, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 23, 'OT', 'Rồi Xít-đê-kia, con trai của Kê-na-na, đến gần, đánh Mi-cai-a vào má, rồi nói: "Thần của Đức Giê-hô-va đã đi đâu từ ta mà đến nói với ngươi?"'),
(11567, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 24, 'OT', 'Rồi Mi-cai-a nói: "Này, ngày đó ngươi sẽ thấy, khi ngươi vào một phòng trong để trốn giấu mình."'),
(11568, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 25, 'OT', 'Bấy giờ, vua Y-sơ-ra-ên nói: "Hãy bắt Mi-ca-gia và dẫn người trở lại cho A-môn, quan tổng trấn thành, và cho Giô-ách, con trai vua."'),
(11569, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 26, 'OT', 'Hãy nói: "Vua phán như vầy: Hãy giam người này trong ngục, và cho người ấy ăn bánh hoạn nạn và uống nước hoạn nạn, cho đến khi ta trở về bình an."'),
(11570, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 27, 'OT', 'Mi-cai-hu nói: "Nếu ngài chắc chắn trở về trong bình an, thì Đức Giê-hô-va đã không phán qua tôi." Rồi ông nói: "Hỡi mọi dân, hãy lắng nghe!"'),
(11571, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 28, 'OT', 'Vua Y-sơ-ra-ên và Giô-sa-phát, vua Giu-đa, đi lên Ra-mốt trong Ga-la-át.'),
(11572, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 29, 'OT', 'Vua Y-sơ-ra-ên nói với Giô-sa-phát: "Hãy cải trang và đi vào trận chiến, còn ngươi thì mặc áo của mình." Vậy vua Y-sơ-ra-ên đã cải trang, và họ đi vào trận chiến.'),
(11573, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 30, 'OT', 'Vua của Á-ram đã ra lệnh cho các viên chỉ huy xe chiến xa đi theo mình rằng: "Đừng chiến đấu với người nhỏ hay người lớn; các ngươi chỉ được chiến đấu cùng vua Y-sơ-ra-ên mà thôi."'),
(11574, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 31, 'OT', 'Khi các viên chỉ huy xe chiến thấy Giô-sa-phát, thì nói rằng: "Đó là vua Ít-ra-en." Vậy chúng vòng quanh người để giao chiến; nhưng Giô-sa-phát kêu lớn, và Đức Giê-hô-va giúp đỡ người; rồi Đức Chúa Trời khiến chúng rời khỏi người.'),
(11575, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 32, 'OT', 'Khi các viên chỉ huy xe ngựa thấy rằng đó không phải là vua Y-sơ-ra-ên, họ liền quay lại, không đuổi theo nữa.'),
(11576, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 33, 'OT', 'Một người giương cung bắn bừa, nhưng trúng vua Y-sơ-ra-ên giữa các miếng nối của áo giáp và áo trang bị; người ấy nói với người đánh xe mình: "Hãy quay tay lại, đưa ta ra khỏi đạo quân, vì ta bị thương."'),
(11577, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 18, 34, 'OT', 'Trận chiến ngày ấy càng lúc càng ác liệt; nhưng vua Y-sơ-ra-ên cứ đứng vững trong xe chiến đấu đối diện quân A-ram cho đến chiều, rồi vào lúc mặt trời lặn, ông qua đời.'),
(11578, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 19, 1, 'OT', 'Vua Giô-sa-phát, vua nước Giu-đa, trở về nhà mình trong sự bình an tại Giê-ru-sa-lem.'),
(11579, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 19, 2, 'OT', 'Vậy thì Giê-hu, con trai của Ha-na-ni, là đấng tiên kiến, đi ra gặp vua Giô-sa-phát và nói: "Ngài há giúp kẻ ác và yêu những kẻ ghét Đức Giê-hô-va sao? Vì điều này, cơn thịnh nộ từ trước mặt Đức Giê-hô-va sẽ đổ trên ngài."'),
(11580, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 19, 3, 'OT', 'Tuy nhiên, những điều tốt lành đã được tìm thấy nơi ngươi, vì ngươi đã dẹp bỏ các nơi thờ hình tượng khỏi đất và đã định lòng tìm kiếm Đức Chúa Trời.'),
(11581, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 19, 4, 'OT', 'Và Giô-sa-phát ở tại Giê-ru-sa-lem; rồi ông đi ra đến giữa dân chúng, từ Bê-e-Sê-va cho đến núi Ép-ra-im, và khiến họ trở lại cùng Đức Giê-hô-va, Đức Chúa Trời của tổ tiên họ.'),
(11582, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 19, 5, 'OT', 'Ông đặt các quan xét xử trong xứ, tại mỗi thành có vách thành kiên cố của Giu-đa, mỗi thành một quan.'),
(11583, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 19, 6, 'OT', 'Hãy coi chừng điều các ngươi làm, vì các ngươi không xét xử cho loài người, mà cho Đức Giê-hô-va, và Ngài ở cùng các ngươi trong việc xét xử.'),
(11584, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 19, 7, 'OT', 'Vì vậy, bây giờ hãy để sự kính sợ Đức Giê-hô-va đè nặng trên các ngươi; hãy cẩn trọng và thực hiện, vì ở cùng Đức Giê-hô-va Đức Chúa Trời chúng ta không có sự gian ác, không thiên vị, và không nhận của hối lộ.'),
(11585, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 19, 8, 'OT', 'Giô-sa-phát cũng lập tại Giê-ru-sa-lem những người trong vòng người Lê-vi, các thầy tế lễ và các tổ trưởng của Y-sơ-ra-ên để xét xử theo luật pháp của Đức Giê-hô-va và giải quyết các vụ tranh tụng; họ trở về Giê-ru-sa-lem.'),
(11586, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 19, 9, 'OT', 'Và người ra lệnh cho họ rằng: "Các ngươi phải làm như thế trong sự kính sợ Đức Giê-hô-va, trung thành và với tấm lòng hoàn toàn."'),
(11587, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 19, 10, 'OT', 'Mọi vụ tranh chấp nào giữa anh em các ngươi, là những người cư ngụ trong các thành của họ, về huyết với huyết, về luật pháp với điều răn, về quy định và án lệ, thì các ngươi phải cảnh tỉnh họ, hầu họ không phạm tội cùng Đức Giê-hô-va, và cơn thịnh nộ giáng trên các ngươi và anh em các ngươi. Các ngươi hãy làm điều này, thì sẽ không phạm tội.'),
(11588, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 19, 11, 'OT', 'Này, hãy xem, A-ma-ri-a, thầy tế lễ trưởng, sẽ đứng đầu các ngươi trong mọi việc thuộc về Đức Giê-hô-va; còn Xê-ba-đia, con trai của Ích-ma-ên, người cai trị nhà Giu-đa, sẽ lo mọi việc của vua; các thầy Lê-vi sẽ làm viên chức trước mặt các ngươi. Hãy mạnh dạn lên và thực hiện đi, và Đức Giê-hô-va sẽ ở cùng những người thiện.'),
(11589, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 1, 'OT', 'Sau những việc ấy, dân Mô-áp và dân Am-môn cùng những người đến từ các dân khác hợp lại nghịch cùng Giô-sa-phát để gây chiến.'),
(11590, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 2, 'OT', 'Có những người đến và báo cho Giô-sa-phát rằng: "Một đạo quân rất đông đã đến chống nghịch ông, từ phía bên kia biển, từ xứ Sy-ria, và nay họ đang ở Ha-xa-xôn Ta-ma, tức là Ên-ge-đi."'),
(11591, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 3, 'OT', 'Đức Giê-hô-va, thì Giô-sa-phát sợ hãi, đặt mặt mình để tìm cầu Đức Giê-hô-va, và ra lệnh cho cả Giu-đa phải ăn chay.'),
(11592, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 4, 'OT', 'Dân Giu-đa cùng nhau nhóm lại để cầu khẩn Đức Giê-hô-va; và từ mọi thành của Giu-đa, họ đến để tìm cầu Đức Giê-hô-va.'),
(11593, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 5, 'OT', 'Vậy Giô-sa-phát đứng giữa hội chúng của Giu-đa và Giê-ru-sa-lem, trong nhà của Đức Giê-hô-va, trước sân mới.'),
(11594, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 6, 'OT', 'Lạy Đức Giê-hô-va Đức Chúa Trời của tổ phụ chúng tôi, chẳng phải Ngài là Đức Chúa Trời trên trời sao? Ngài cai trị trên mọi nước các dân tộc; trong tay Ngài có quyền năng và sức mạnh, chẳng ai có thể chống cự lại Ngài.'),
(11595, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 7, 'OT', 'Lạy Đức Chúa Trời của chúng tôi, chẳng phải chính Ngài đã đuổi dân ở đất nầy ra khỏi trước mặt dân Ngài là Y-sơ-ra-ên, và ban đất ấy cho dòng dõi Áp-ra-ham, người bạn Ngài, đến muôn đời sao?'),
(11596, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 8, 'OT', 'Họ đã ở trong đó, và xây cho Ngài một đền thánh trong đó cho danh Ngài, mà rằng,'),
(11597, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 9, 'OT', 'Nếu tai họa giáng trên chúng tôi, như gươm, như án phạt, như ôn dịch, hay như đói kém, chúng tôi sẽ đứng trước nhà nầy và trước mặt Ngài, vì danh Ngài ở trong nhà nầy; và chúng tôi sẽ kêu lên cùng Ngài trong cơn khốn khổ, thì Ngài sẽ nghe và cứu giúp.'),
(11598, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 10, 'OT', 'Và nầy, các con trai của Amôn, Moáp và núi Sê-ir, mà Ngài đã không cho phép Y-sơ-ra-ên xâm chiếm khi họ ra khỏi đất Ai-cập, vì họ đã tránh khỏi chúng, và không tiêu diệt chúng.'),
(11599, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 11, 'OT', 'Nầy, chúng nó đền đáp chúng tôi, đến để trục xuất chúng tôi khỏi phần đất thuộc về Ngài mà Ngài đã cho chúng tôi hưởng làm sản nghiệp.'),
(11600, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 12, 'OT', 'Lạy Đức Chúa Trời của chúng tôi, há Ngài sẽ không xét xử chúng nó sao? Vì chúng tôi không có sức lực nào chống lại đoàn đông này đang đến nghịch cùng chúng tôi; và chúng tôi cũng chẳng biết phải làm gì, nhưng mắt chúng tôi đang nhìn về phía Ngài.'),
(11601, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 13, 'OT', 'Toàn thể người Giu-đa đứng trước mặt Đức Giê-hô-va, cả những trẻ nhỏ, vợ và con cái của họ.'),
(11602, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 14, 'OT', 'Rồi Đức Giê-hô-va đặt thần trên Giách-xi-ên, con trai Xác-cha-ri, con trai Bê-na-gia, con trai Giê-i-ên, con trai Ma-ta-nia, người Lê-vi, thuộc các con trai A-sáp, giữa hội chúng.'),
(11603, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 15, 'OT', 'Hãy lắng nghe, cả Giu-đa và những người ở Giê-ru-sa-lem, cùng với vua Giô-sa-phát! Đức Giê-hô-va phán cùng các ngươi như vầy: Các ngươi chớ sợ, chớ kinh hãi vì cơn hỗn loạn đông đảo này; vì chiến trận không phải của các ngươi, mà là của Đức Chúa Trời.'),
(11604, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 16, 'OT', 'Ngày mai hãy đi xuống nghịch họ; nầy, chúng nó đang lên theo dốc đá Xít; và các ngươi sẽ gặp chúng nó ở cuối suối, trước đồng vắng Giê-ru-ên.'),
(11605, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 17, 'OT', 'Không phải các ngươi phải chiến đấu trong điều này; hãy đứng vững, hãy yên lặng mà nhìn sự cứu rỗi của Đức Giê-hô-va ở cùng các ngươi, hỡi Giu-đa và Giê-ru-sa-lem; đừng sợ hãi, cũng đừng kinh hoàng; ngày mai hãy ra đi nghênh chiến với chúng; Đức Giê-hô-va sẽ ở cùng các ngươi.'),
(11606, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 18, 'OT', 'Vua Giô-sa-phát cúi mặt xuống đất; toàn thể người Giu-đa và dân cư Giê-ru-sa-lem đều sấp mình xuống trước mặt Đức Giê-hô-va để thờ lạy Ngài.'),
(11607, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 19, 'OT', 'Các người Lê-vi, thuộc con cháu của Kê-hát và con cháu của Cô-rê, đứng dậy để ca ngợi Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en bằng tiếng reo lớn vang trời.'),
(11608, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 20, 'OT', 'Sáng hôm sau, họ dậy sớm và ra đi vào đồng vắng Tê-cô-a. Khi họ khởi hành, Giô-sa-phát đứng dậy và nói: "Hỡi người Giu-đa và các cư dân Giê-ru-sa-lem, hãy nghe ta! Hãy tin cậy Đức Giê-hô-va Đức Chúa Trời các ngươi, thì các ngươi sẽ được vững lập; hãy tin các đấng tiên tri của Ngài, thì các ngươi sẽ thạnh vượng."'),
(11609, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 21, 'OT', 'Sau khi tham vấn cùng dân chúng, ông đặt các ca sĩ phục vụ Đức Giê-hô-va, ca ngợi vẻ vinh hiển thánh khiết, khi họ ra đi phía trước đạo quân, và nói rằng: "Hãy cảm tạ Đức Giê-hô-va, vì sự nhân từ của Ngài tồn tại đời đời."'),
(11610, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 22, 'OT', 'Khi họ bắt đầu hát những bài ca ngợi và ca ngợi, Đức Giê-hô-va khiến những toán phục kích chống lại con cái Amôn, Mô-áp và núi Sê-ir, là những kẻ đến nghịch cùng Giu-đa; và chúng bị đánh bại.'),
(11611, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 23, 'OT', 'Các con trai của Amôn và Mô-áp đứng lên chống lại những người ở núi Sê-ir, để tiêu diệt và hủy diệt họ; và khi họ đã tiêu diệt những người ở Sê-ir xong, thì mỗi người lại giúp đồng bọn mình tiêu diệt lẫn nhau.'),
(11612, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 24, 'OT', 'Vua Giu-đa đi về phía tháp canh trong đồng vắng, nhìn về phía đoàn người đông đảo, và nầy, các xác chết nằm ngổn ngang trên đất, chẳng có ai thoát được.'),
(11613, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 25, 'OT', 'Và Giô-sa-phát cùng dân người đến để lấy chiến lợi phẩm, thì thấy ở đó rất nhiều tài sản, xác chết và những đồ trang sức quý giá; họ thu lấy cho mình những thứ ấy đến nỗi không thể mang hết được; và họ đã ba ngày mới dọn dẹp xong chiến lợi phẩm, vì số lượng quá lớn.'),
(11614, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 26, 'OT', 'Vào ngày thứ tư, họ tập hợp tại thung lũng Bê-ra-ca; vì tại đó họ đã ca ngợi Đức Giê-hô-va. Bởi lẽ đó, người ta đặt tên cho nơi ấy là Thung lũng Bê-ra-ca cho đến ngày nay.'),
(11615, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 27, 'OT', 'Hết thảy những người của Giu-đa và Giê-ru-sa-lem trở về, có Giô-sa-phát đi đầu, để về Giê-ru-sa-lem trong sự vui mừng; vì Đức Giê-hô-va đã khiến họ vui mừng trước mặt kẻ thù nghịch mình.'),
(11616, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 28, 'OT', 'Họ vào Giê-ru-sa-lem với những cây đờn nghịch và đờn cầm, cùng những cây kèn, đến nhà Đức Giê-hô-va.'),
(11617, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 29, 'OT', 'Sự kính sợ Đức Chúa Trời giáng trên mọi nước vương quốc, khi chúng nghe rằng Đức Giê-hô-va chiến đấu chống lại các kẻ thù của Ít-ra-en.'),
(11618, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 30, 'OT', 'Vậy nên vương quốc của Giô-sa-phát được yên ổn, và Đức Chúa Trời của ông ban cho ông sự an nghỉ xung quanh.'),
(11619, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 31, 'OT', 'Giô-sa-phát trị vì trên Giu-đa; người lên ngôi khi ba mươi lăm tuổi, và trị vì tại Giê-ru-sa-lem hai mươi lăm năm. Tên mẹ người là A-xu-va, con gái của Si-lhi.'),
(11620, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 32, 'OT', 'Người đi theo con đường của A-sa, cha mình, và không xây bỏ nó, làm điều ngay thẳng trước mắt Đức Giê-hô-va.'),
(11621, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 33, 'OT', 'Nhưng các nơi cao thì chưa bị bỏ đi; và lòng dân chúng vẫn chưa sẵn sàng cho Đức Chúa Trời của tổ tiên họ.'),
(11622, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 34, 'OT', 'Còn các việc khác của Giô-sa-phát, những việc đầu tiên và cuối cùng, thì đã ghi chép trong sách của Giê-hu, con trai của Ha-na-ni, người được đề cập trong sách các vua của Y-sơ-ra-ên.'),
(11623, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 35, 'OT', 'Sau điều đó, Giô-sa-phát, vua Giu-đa, liên kết với A-ha-xi-a, vua Ít-ra-en, là người đã phạm tội rất nặng khi làm điều ác.'),
(11624, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 36, 'OT', 'Ông liên kết với ông ấy để làm các tàu đi Tạt-si; và họ làm các tàu tại Ê-xi-ôn-ghê-be.'),
(11625, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 20, 37, 'OT', 'Ê-li-ê-xe, con trai Đô-đa-va, người Ma-rê-sa, đã nói tiên tri nghịch lại Giô-sa-phát, rằng: Vì ngươi đã liên kết với A-ha-xi-a, nên Đức Giê-hô-va đã phá hủy các công việc của ngươi; và những chiếc tàu đã bị vỡ, không thể đi đến Ta-rơ-si-s được.'),
(11626, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 21, 1, 'OT', 'Giô-sa-phát an giấc cùng các tổ phụ mình, và được chôn cùng các tổ phụ mình trong thành Đa-vít. Giô-ram, con trai ông, lên ngôi làm vua thay cho ông.'),
(11627, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 21, 2, 'OT', 'Và người có các anh em, là những con trai của Giô-sa-phát: A-xa-ri-ah, Giê-hi-ên, Xa-cha-ri-a, A-xa-ri-ah, Mi-kha-ên và Sê-pha-ti-a; tất cả những người này đều là con trai của Giô-sa-phát, vua của Y-sơ-ra-ên.'),
(11628, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 21, 3, 'OT', 'Vua cha của chúng ban cho họ những món quà lớn bằng bạc, bằng vàng và những vật quý giá, cùng các thành có vách thành vững chắc trong xứ Giu-đa; nhưng vương quốc thì ông trao cho Giô-ram, vì ông là con cả.'),
(11629, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 21, 4, 'OT', 'Khi Giô-ram lên ngôi làm vua thay cho cha mình, người củng cố quyền lực và giết tất cả các anh em mình bằng gươm, cùng với một số quan chức của Y-sơ-ra-ên.'),
(11630, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 21, 5, 'OT', 'Giô-ram được ba mươi hai tuổi khi người lên ngôi vua, và người trị vì tám năm tại Giê-ru-sa-lem.'),
(11631, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 21, 6, 'OT', 'Vua ấy đi theo đường lối các vua Y-sơ-ra-ên, như nhà A-háp đã làm; vì người có vợ là con gái A-háp; và vua ấy làm điều ác trước mặt Đức Giê-hô-va.'),
(11632, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 21, 7, 'OT', 'Đức Giê-hô-va không chịu tiêu diệt nhà Đa-vít, vì cớ giao ước mà Ngài đã lập với Đa-vít, và như lời Ngài đã hứa ban cho người một ngọn đèn và cho các con trai người mọi ngày.'),
(11633, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 21, 8, 'OT', 'Trong những ngày của người, dân Ê-đôm nổi dậy khỏi sự cai trị của Giu-đa và lập cho mình một vua.'),
(11634, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 21, 9, 'OT', 'Vua Giô-ram đi ra cùng các quan trưởng mình và tất cả các xe chiến mã đi theo ông; ông ấy đã trỗi dậy trong đêm khuya và đánh bại người Ê-đôm vây quanh ông, cùng các quan chỉ huy xe chiến mã.'),
(11635, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 21, 10, 'OT', 'Vậy Ê-đôm đã nổi loạn khỏi tay Giu-đa cho đến ngày nay. Cũng trong thời ấy, Li-banh đã nổi loạn khỏi tay người, vì người đã lìa bỏ Đức Giê-hô-va, Đức Chúa Trời của tổ tiên mình.'),
(11636, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 21, 11, 'OT', 'Người ấy cũng lập các nơi cao trên các núi của Giu-đa, khiến những người ở Giê-ru-sa-lem phạm tội tà dâm, và ép Giu-đa phải làm điều đó.'),
(11637, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 21, 12, 'OT', 'Có một bức thư đến cùng vua từ Ê-li-a, đấng tiên tri, rằng: "Đây Đức Giê-hô-va Đức Chúa Trời của Đa-vít, cha ngươi, phán: Vì ngươi không đi theo các đường lối của Giô-sa-phát, cha ngươi, và các đường lối của A-sa, vua Giu-đa,'),
(11638, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 21, 13, 'OT', 'Ngươi đã đi theo con đường của các vua Y-sơ-ra-ên, khiến cho Giu-đa và những người ở Giê-ru-sa-lem phải phạm tội tà dâm như tội tà dâm của nhà A-háp; và ngươi cũng đã giết các anh em ngươi, những người trong gia đình cha ngươi, là những người tốt hơn ngươi.'),
(11639, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 21, 14, 'OT', 'Nầy, Đức Giê-hô-va sẽ giáng một cơn dịch lớn trên dân ngươi, các con trai ngươi, các vợ ngươi, và mọi tài sản ngươi.'),
(11640, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 21, 15, 'OT', 'Còn ngươi, ngươi sẽ bị nhiều bệnh tật nghiêm trọng do bệnh ở ruột ngươi, cho đến khi ruột ngươi bị sa ra khỏi cơ thể vì bệnh tật, ngày này qua ngày khác.'),
(11641, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 21, 16, 'OT', 'Đức Giê-hô-va khiến cho thần của người Phi-li-tin và người Ả-rập, là những kẻ ở gần người Cu-si, nổi lên chống lại Giô-ram.'),
(11642, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 21, 17, 'OT', 'Họ lên đánh Giu-đa, phá tan nó, cướp lấy mọi tài sản tìm thấy trong nhà vua, cả các con trai và các vợ của vua; không còn lại cho người một người con trai nào, ngoại trừ Giô-a-cha-xết, người con trai nhỏ nhất của người.'),
(11643, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 21, 18, 'OT', 'Sau hết thảy những điều nầy, Đức Giê-hô-va đánh người trong ruột người bằng một bệnh không thể chữa được.'),
(11644, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 21, 19, 'OT', 'Sau một thời gian, đến kỳ cuối cùng của hai năm, các phủ tạng của ông đã rơi ra cùng với bệnh tật của ông; rồi ông chết trong những bệnh tật ác liệt, và dân sự ông không đốt xác ông như thể đốt xác các tổ phụ ông.'),
(11645, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 21, 20, 'OT', 'Ba mươi hai tuổi khi người bắt đầu trị vì, và người trị vì tại Giê-ru-sa-lem tám năm. Người ra đi mà không được mong đợi; tuy nhiên, họ chôn cất người trong thành Đa-vít, nhưng không ở trong các phần mộ của các vua.'),
(11646, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 22, 1, 'OT', 'Dân cư Giê-ru-sa-lem lập A-ha-xi-a, con trai út của người, làm vua thay cho người; vì tất cả những người con trưởng đã bị toán quân đến cùng người A-ráp giết tại doanh trại. Vậy A-ha-xi-a, con trai của Giô-ram, vua nước Giu-đa, lên làm vua.'),
(11647, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 22, 2, 'OT', 'Achazyahu bốn mươi hai tuổi khi người bắt đầu trị vì; người trị vì một năm tại Giê-ru-sa-lem. Tên mẹ người là A-ta-li-a, con gái Ôm-ri.'),
(11648, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 22, 3, 'OT', 'Cũng như vậy, người đi theo các đường lối của nhà A-háp, vì mẹ người là người tư vấn cho người làm điều ác.'),
(11649, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 22, 4, 'OT', 'Vì vậy, người đã làm điều ác trước mắt Đức Giê-hô-va như nhà A-háp, vì những người ấy đã làm cố vấn cho người sau khi cha người qua đời, khiến người bị tiêu diệt.'),
(11650, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 22, 5, 'OT', 'Cũng đi theo mưu kế của họ, người ấy đi cùng với Giô-ram, con trai của A-háp, vua Y-sơ-ra-ên, ra chiến trận chống lại Ha-xa-ên, vua Sy-ri, tại Ra-mốt Ga-la-át; và người Sy-ri đã đánh Giô-ram.'),
(11651, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 22, 6, 'OT', 'Vua Giô-ram trở về Giết-rê-ên để chữa lành các vết thương mình đã bị trong lúc chiến đấu với Ha-xa-ên, vua nước Sy-ria, tại Ra-ma. A-xa-ri-gia, con trai vua Giô-ram, vua nước Giu-đa, cũng xuống thăm Giô-ram, con trai A-háp, tại Giết-rê-ên, vì ông đang đau yếu.'),
(11652, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 22, 7, 'OT', 'Sự bại vong của A-ha-xi-a là do từ Đức Chúa Trời, khi người đến cùng Giô-ram; và khi người đến, người đi ra cùng Giô-ram nghịch cùng Giê-hu, con trai của Nim-si, là người mà Đức Giê-hô-va đã xức dầu để tiêu diệt dòng họ A-háp.'),
(11653, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 22, 8, 'OT', 'Xảy ra rằng, khi Giê-hu thi hành sự xét xử đối với nhà A-háp, thì gặp các quan trưởng của Giu-đa và các con trai của anh em A-ha-xi-a, những người phục vụ cho A-ha-xi-a; và người đã giết họ.'),
(11654, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 22, 9, 'OT', 'Người ta tìm kiếm A-ha-xi-a, bắt được ông khi ông đang trốn ở Sa-ma-ri, rồi dẫn ông đến với Giê-hu; họ giết ông. Họ chôn cất ông, vì họ nói: "Ông ấy là con trai Giô-sa-phát, người đã tìm kiếm Đức Giê-hô-va trọn cả tấm lòng mình." Vậy nên nhà của A-ha-xi-a không còn sức mạnh nào để giữ ngôi vương quốc.'),
(11655, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 22, 10, 'OT', 'Vua Át-ta-lia, mẹ của A-cha-xia, thấy con mình đã chết, liền chỗi dậy và diệt sạch toàn thể dòng dõi hoàng gia nhà Giu-đa.'),
(11656, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 22, 11, 'OT', 'Bà Giô-sa-bát, con gái của vua, lấy ông Giô-ách, con trai của A-ha-xi-a, và đem ông trốn khỏi giữa những con trai của vua bị giết; bà đặt ông và người vú nuôi của ông trong buồng ngủ. Bà Giô-sa-bát, con gái của vua Giô-ram, vợ của thầy tế lễ Giô-ia-đa (vì bà là em gái của A-ha-xi-a), đã giấu ông khỏi bà A-tha-lya, nên bà ấy không giết được ông.'),
(11657, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 22, 12, 'OT', 'Ông ở cùng họ, được giấu trong nhà Đức Chúa Trời sáu năm; còn A-ta-li-a thì làm nữ vương cai trị đất nước.'),
(11658, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 23, 1, 'OT', 'Vào năm thứ bảy, Giô-ia-đa lấy sức mạnh và lập giao ước cùng các quan trưởng trăm người: A-xa-ria, con trai của Giê-rô-ham; Ích-ma-ên, con trai của Giê-hô-ha-nan; A-xa-ria, con trai của Ô-bết; Ma-a-xe-gia, con trai của A-đai-a; và Ê-li-sa-phát, con trai của Xích-ri.'),
(11659, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 23, 2, 'OT', 'Họ đi khắp Giu-đa, nhóm các thầy Lê-vi từ mọi thành của Giu-đa và các tộc trưởng của Ít-ra-en, rồi đến Giê-ru-sa-lem.'),
(11660, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 23, 3, 'OT', 'Toàn thể hội chúng lập giao ước với nhà vua trong đền thờ Đức Chúa Trời. Người nói với họ: "Nầy, con trai của vua sẽ trị vì, như Đức Giê-hô-va đã phán về con cháu của Đa-vít."'),
(11661, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 23, 4, 'OT', 'Đây là điều các ngươi sẽ làm: một phần ba trong các ngươi vào ngày sa-bát, gồm các thầy tế lễ và người Lê-vi, sẽ canh gác các cửa.'),
(11662, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 23, 5, 'OT', 'Một phần ba canh gác tại cung vua; một phần ba tại cổng nền; và toàn thể dân chúng tại các hành lang trong đền thờ Đức Giê-hô-va.'),
(11663, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 23, 6, 'OT', 'Chỉ những thầy tế lễ và những người Lê-vi phục vụ mới được vào nhà của Đức Giê-hô-va; chính họ sẽ vào, vì họ là thánh; còn toàn thể dân chúng phải tuân giữ sự canh giữ của Đức Giê-hô-va.'),
(11664, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 23, 7, 'OT', 'Các thầy Lê-vi sẽ vây quanh vua, mỗi người có vũ khí trong tay; ai vào nhà thì sẽ bị giết; còn các ngươi thì phải ở bên vua khi người vào và khi người ra.'),
(11665, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 23, 8, 'OT', 'Các thầy Lê-vi và toàn thể người Giu-đa đều làm theo mọi điều mà thầy tế lễ Giô-gia-đa đã truyền dạy; mỗi người nhận lấy những thuộc hạ mình đến phiên phục vụ trong ngày Sa-bát, cùng với những người đang phiên ra về; vì thầy tế lễ Giô-gia-đa không giải tán các ca-bin.'),
(11666, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 23, 9, 'OT', 'Thầy tế lễ Giô-ya-đa trao cho các quan chỉ huy một trăm cây giáo, thuẫn và khiên của vua Đa-vít, những vật đó ở trong nhà Đức Chúa Trời.'),
(11667, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 23, 10, 'OT', 'Ông đặt toàn thể dân chúng đứng ở mọi nơi, mỗi người cầm vũ khí trong tay, từ vai phải của đền thờ cho đến vai trái của đền thờ, dọc theo bàn thờ và đền thờ, xung quanh vua.'),
(11668, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 23, 11, 'OT', 'Họ đưa hoàng tử ra, đặt mão triều lên đầu người và trao cho người bảng chứng, rồi phong người làm vua. Giô-ia-đa và các con trai ông xức dầu cho người và nói: "Nguyện đức vua sống mãi!"'),
(11669, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 23, 12, 'OT', 'Bấy giờ, khi A-ta-li-a nghe tiếng dân chúng reo lên và ca ngợi vua, bà đi đến nơi dân chúng ở đền thờ của Đức Giê-hô-va.'),
(11670, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 23, 13, 'OT', 'Bà Atalia nhìn thấy, và nầy, nhà vua đang đứng bên cột trụ của mình nơi cửa vào, các quan trưởng cùng các tù và đứng gần nhà vua; toàn thể dân trong xứ thì hớn hở vui mừng, thổi tù và, các nhạc sĩ dùng nhạc cụ ca hát, và những người dạy dân hát lời ca ngợi. Bấy giờ Atalia xé áo mình, và kêu lên: "Phản nghịch! Phản nghịch!"'),
(11671, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 23, 14, 'OT', 'Vua thầy tế lễ Giô-ya-đa đưa các quan chỉ huy trăm người lãnh đạo quân đội ra, và nói với họ: "Hãy đưa nàng ra khỏi hàng ngũ; ai đi theo nàng thì phải bị giết bằng gươm." Vì thầy tế lễ đã nói: "Không được giết nàng trong nhà Đức Giê-hô-va."'),
(11672, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 23, 15, 'OT', 'Họ tra tay vào bà; và khi bà đến nơi vào cửa Ngựa tại nhà vua, họ giết bà tại đó.'),
(11673, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 23, 16, 'OT', 'Và Giê-hô-ia-đa lập giao ước giữa chính mình với toàn thể dân chúng và giữa nhà vua, để dân sự thuộc về Đức Giê-hô-va.'),
(11674, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 23, 17, 'OT', 'Toàn thể dân chúng đi đến đền thờ của Ba-an, phá hủy nó, đập tan các bàn thờ và các tượng hình tượng của nó, và giết Ma-tần, thầy tế lễ của Ba-an, trước các bàn thờ.'),
(11675, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 23, 18, 'OT', 'Và Giê-hô-i-đa thiết lập các chức vụ trong đền thờ Đức Giê-hô-va do các thầy tế lễ Lê-vi đảm nhiệm, những người mà Đa-vít đã phân bổ trong đền thờ Đức Giê-hô-va, để dâng của lễ thiêu cho Đức Giê-hô-va theo như chép trong luật pháp của Môi-se, cách vui vẻ và với tiếng hát, theo sự hướng dẫn của Đa-vít.'),
(11676, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 23, 19, 'OT', 'Ông đặt các người giữ cửa tại các cổng đền thờ của Đức Giê-hô-va, để không ai bị ô uế về bất cứ điều gì được phép vào.'),
(11677, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 23, 20, 'OT', 'Ông ấy triệu tập các quan chỉ huy một trăm người, các quan quyền quý, các quan cai trị trong dân sự, và toàn thể dân chúng trong đất nước; rồi cùng nhau đưa nhà vua từ đền thờ Đức Giê-hô-va xuống, đi qua cổng trên vào cung điện vua, và đặt nhà vua ngồi trên ngôi vương quyền.'),
(11678, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 23, 21, 'OT', 'Toàn thể dân trong xứ đều vui mừng, và thành phố được yên lặng; còn A-ta-li-a thì họ giết bằng gươm.'),
(11679, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 24, 1, 'OT', 'Giô-ách lên ngôi lúc bảy tuổi và trị vì bốn mươi năm tại Giê-ru-sa-lem. Tên mẹ người là Xíp-ya, người Bê-ersê-va.'),
(11680, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 24, 2, 'OT', 'Vua Giô-ách làm điều ngay lành trước mặt Đức Giê-hô-va trong suốt mọi ngày đời thầy tế lễ Giê-hô-ya-đa.'),
(11681, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 24, 3, 'OT', 'Giô-ya-đa lấy cho mình hai vợ, và sinh được các con trai và các con gái.'),
(11682, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 24, 4, 'OT', 'Sau điều đó, lòng của Giô-ách khởi ý tu sửa đền thờ Đức Giê-hô-va.'),
(11683, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 24, 5, 'OT', 'Và người tập họp các thầy tế lễ và người Lê-vi, rồi nói với họ: "Hãy đi ra các thành của Giu-đa, và thu từ khắp cả Ít-ra-en tiền bạc để tu bổ nhà của Đức Chúa Trời các ngươi hằng năm; và các ngươi hãy mau chóng thực hiện điều này." Nhưng những người Lê-vi đã không mau mắn thực hiện điều đó.'),
(11684, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 24, 6, 'OT', 'Vua gọi thầy tế lễ trưởng Giô-ya-đa và nói với người rằng: "Tại sao ngươi không đòi các thầy Lê-vi phải thu lấy từ Giu-đa và Giê-ru-sa-lem món tiền thuế mà Môi-se, đầy tớ của Đức Giê-hô-va, và hội chúng Ít-ra-en đã quy định để dùng cho nhà tạm làm chứng cớ?"'),
(11685, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 24, 7, 'OT', 'Vì Athalia, người đàn bà gian ác, đã khiến các con trai của nàng phá hủy đền thờ Đức Chúa Trời, và còn dùng mọi vật thánh trong đền thờ Đức Giê-hô-va để dâng cho các tượng Ba-al.'),
(11686, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 24, 8, 'OT', 'Vua truyền lệnh, người ta làm một cái hòm và đặt nó bên ngoài tại cổng đền thờ Đức Giê-hô-va.'),
(11687, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 24, 9, 'OT', 'Họ liền truyền rao khắp Giu-đa và Giê-ru-sa-lem, kêu gọi dân chúng mang đến cho Đức Giê-hô-va khoản tiền quyên góp mà Môi-se, tôi tớ Đức Chúa Trời, đã quy định cho Ít-ra-en trong đồng vắng.'),
(11688, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 24, 10, 'OT', 'Các quan trưởng và toàn thể dân chúng đều vui mừng, và họ mang đến, rồi ném vào hòm cho đến khi đầy.'),
(11689, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 24, 11, 'OT', 'Và xảy ra rằng, mỗi khi hòm được mang đến cho viên chức của vua qua tay các người Lê-vi, và khi họ thấy tiền bạc rất nhiều, thì viên thư ký của vua và viên quản lý thuộc giới tế lễ thượng phẩm đến, đổ hòm ra, rồi khiêng nó trở lại chỗ cũ. Họ làm như vậy mỗi ngày, và thu được tiền bạc rất dồi dào.'),
(11690, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 24, 12, 'OT', 'Vua và Giô-gia-đa trao số tiền đó cho những người lo công việc phục vụ nhà Đức Giê-hô-va, và họ thuê thợ đục đá và thợ mộc để sửa chữa nhà Đức Giê-hô-va, cũng như thợ rèn sắt và thợ rèn đồng để gia cố nhà Đức Giê-hô-va.'),
(11691, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 24, 13, 'OT', 'Các thợ làm việc thì công việc nhờ tay họ được tiến triển, và họ sửa lại đền thờ Đức Chúa Trời theo đúng thiết kế ban đầu, rồi củng cố đền ấy.'),
(11692, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 24, 14, 'OT', 'Sau khi hoàn thành việc đó, họ đem phần tiền còn lại đến trước mặt vua và thầy tế tự Giô-ya-đa; người ta dùng số tiền ấy làm các đồ dùng cho đền thờ của Đức Giê-hô-va, tức là các đồ dùng để hầu việc và dâng của lễ thiêu, thìa, cùng các đồ dùng bằng vàng và bạc. Và họ dâng của lễ thiêu trong đền thờ của Đức Giê-hô-va cách đều đặn suốt mọi ngày đời của Giô-ya-đa.'),
(11693, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 24, 15, 'OT', 'Ông Giô-ya-đa về già, sống đủ số năm đời rồi qua đời; ông thọ một trăm ba mươi tuổi khi qua đời.'),
(11694, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 24, 16, 'OT', 'Họ chôn ông trong thành Đa-vít cùng các vua, vì ông đã làm điều thiện trong Ít-ra-ên và đối với Đức Chúa Trời cùng nhà Ngài.'),
(11695, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 24, 17, 'OT', 'Sau khi Giô-ya-đa qua đời, các quan trưởng Giu-đa đến, cúi lạy vua. Bấy giờ, vua nghe theo họ.'),
(11696, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 24, 18, 'OT', 'Họ từ bỏ nhà của Đức Giê-hô-va Đức Chúa Trời của tổ tiên mình, và thờ các thần Ách-sê-rim và các hình tượng; vì sự phạm tội nầy, cơn thạnh nộ giáng trên Giu-đa và Giê-ru-sa-lem.'),
(11697, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 24, 19, 'OT', 'Đức Giê-hô-va sai các nhà tiên tri đến cùng họ, để dẫn họ trở lại cùng Đức Giê-hô-va; các nhà tiên tri làm chứng cho họ, nhưng họ không chịu lắng nghe.'),
(11698, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 24, 20, 'OT', 'Thần của Đức Chúa Trời ngự trên Xa-cha-ri, con trai thầy tế lễ Giô-ê-đa, người ấy đứng lên trên dân chúng và nói với họ rằng: Đức Chúa Trời phán như thế này: "Tại sao các ngươi vi phạm các điều răn của Đức Giê-hô-va, khiến các ngươi không được thạnh vượng? Vì các ngươi đã lìa bỏ Đức Giê-hô-va, nên Ngài cũng lìa bỏ các ngươi."'),
(11699, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 24, 21, 'OT', 'Họ cùng nhau âm mưu nghịch lại ông và ném đá ông chết theo lệnh vua, tại sân đền thờ của Đức Giê-hô-va.'),
(11700, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 24, 22, 'OT', 'Vua Giô-ách không nhớ ơn thương xót mà Giê-hô-gia-đa, cha mình, đã làm cho mình, bèn giết con trai ông. Khi chết, ông nói: "Nguyện Đức Giê-hô-va nhìn xem và đòi hỏi điều đó."'),
(11701, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 24, 23, 'OT', 'Sau một năm, đạo quân của xứ A-ram kéo lên đánh vua ấy; họ đến Giu-đa và Giê-ru-sa-lem, tiêu diệt hết các quan trưởng trong dân, và gửi toàn bộ của cải cướp được về cho vua Đa-mách.'),
(11702, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 24, 24, 'OT', 'Vì đạo quân của người Sy-ri đến với một số ít người, nhưng Đức Giê-hô-va đã phó một đạo quân rất đông vào tay chúng, bởi vì chúng đã lìa bỏ Đức Giê-hô-va Đức Chúa Trời của tổ tiên mình; và chúng đã thi hành án phạt đối với Giô-ách.'),
(11703, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 24, 25, 'OT', 'Khi họ rời khỏi ông, vì đã bỏ ông trong nhiều bệnh tật, thì các tôi tớ của ông đã cấu kết nghịch lại ông vì huyết các con trai của Giô-ya-đa, thầy tế lễ, và giết ông trên giường ông, rồi ông qua đời. Họ chôn ông trong thành Đa-vít, nhưng không chôn ông trong các phần mộ của các vua.'),
(11704, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 24, 26, 'OT', 'Những kẻ cấu kết nghịch cùng vua là Xa-bát, con trai của Si-mé-at, người nữ Am-môn, và Giô-xa-bát, con trai của Si-mrít, người nữ Mô-áp.'),
(11705, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 24, 27, 'OT', 'Còn về các con trai của ông, và gánh nặng lớn chất lên ông, và việc sửa chữa nhà của Đức Chúa Trời, thì này, chúng đã được ghi chép trong sách truyện các vua. Và A-ma-xia, con trai ông, lên ngôi làm vua thay ông.'),
(11706, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 25, 1, 'OT', 'Am-xia được hai mươi lăm tuổi khi người bắt đầu trị vì, và người trị vì hai mươi chín năm tại Giê-ru-sa-lem. Tên mẹ người là Giô-ê-đan, người Giê-ru-sa-lem.'),
(11707, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 25, 2, 'OT', 'Vua làm điều ngay thẳng trước mắt Đức Giê-hô-va, nhưng không phải với một lòng trọn vẹn.'),
(11708, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 25, 3, 'OT', 'Sau khi vương quyền được củng cố trong tay người, thì người đã giết những đầy tớ đã giết vua cha mình.'),
(11709, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 25, 4, 'OT', 'Nhưng người không giết các con trai của chúng, vì theo điều đã chép trong Luật pháp, trong sách Môi-se, mà Đức Giê-hô-va đã truyền rằng: "Cha không chết thay cho con, con cũng không chết thay cho cha; mỗi người phải chết vì tội riêng của mình."'),
(11710, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 25, 5, 'OT', 'Vua A-ma-xia tập hợp người Giu-đa, đặt các quan chỉ huy theo gia tộc, các quan ngàn và các quan trăm trong toàn thể Giu-đa và Bên-gia-min; người điểm kiểm những kẻ từ hai mươi tuổi trở lên, và tìm được ba trăm ngàn trai tráng tinh nhuệ, sẵn sàng ra trận, biết dùng giáo và khiên.'),
(11711, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 25, 6, 'OT', 'Ông thuê từ Y-sơ-ra-ên một trăm ngàn người lính hùng mạnh, bằng một trăm ta-lâng bạc.'),
(11712, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 25, 7, 'OT', 'Nhưng một người của Đức Chúa Trời đến cùng vua, nói rằng: Hỡi vua, chớ để đạo quân Y-sơ-ra-ên đi với ngài; vì Đức Giê-hô-va không ở cùng Y-sơ-ra-ên, tức là cùng mọi con cháu Ép-ra-im.'),
(11713, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 25, 8, 'OT', 'Nếu ngươi cứ đi, hãy ra sức chiến đấu; nhưng Đức Chúa Trời sẽ khiến ngươi thất bại trước mặt kẻ thù, vì Đức Chúa Trời có quyền năng giúp đỡ hoặc làm cho ngã.'),
(11714, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 25, 9, 'OT', 'Vua Am-xa-ia nói với người của Đức Chúa Trời: "Nhưng ta phải làm sao về trăm ta-lâng mà ta đã đưa cho đạo quân Ít-ra-ên?" Người của Đức Chúa Trời đáp: "Đức Giê-hô-va có thể ban cho vua nhiều hơn thế này gấp bội."'),
(11715, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 25, 10, 'OT', 'Bấy giờ, Am-xa-ia phân biệt những người thuộc đạo quân đến cùng ông từ Ép-ra-im, để họ trở về nơi ở của mình; nhưng cơn thịnh nộ của họ nổi lên dữ dội đối với Giu-đa, nên họ bèn trở về nơi ở mình trong cơn giận dữ.'),
(11716, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 25, 11, 'OT', 'Am-xi-gia củng cố sức lực, dẫn dân mình đi, đến Thung lũng Muối, và đánh bại mười ngàn người con cái Sê-i-rơ.'),
(11717, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 25, 12, 'OT', 'Mười ngàn người sống sót, con cái Giu-đa bắt làm tù binh, họ đem đến đỉnh vách đá, rồi xô từ đỉnh vách đá xuống, khiến tất cả đều bị tan xác.'),
(11718, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 25, 13, 'OT', 'Nhưng những người lính trong đạo quân mà A-ma-xia đã cho trở về, không đi cùng ông ra trận, đã xông vào các thành của Giu-đa, từ Xô-mê-ri đến Bết-hô-rôn, giết chết ba ngàn người trong số họ và cướp lấy rất nhiều chiến lợi phẩm.'),
(11719, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 25, 14, 'OT', 'Sau khi A-ma-xia trở về từ cuộc đánh bại người Ê-đôm, ông đã mang các thần của con cái Xê-ir về, lập chúng làm thần mình, cúi lạy trước mặt chúng và dâng hương cho chúng.'),
(11720, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 25, 15, 'OT', 'Đức Giê-hô-va nổi giận cùng A-ma-xia, bèn sai một đấng tiên tri đến cùng người, và người nói với người rằng: "Sao ngươi đi tìm các thần của dân, là những thần chẳng cứu nổi dân chúng khỏi tay ngươi?"'),
(11721, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 25, 16, 'OT', 'Khi người ấy nói với vua, thì người tư vấn cho vua nói với người ấy: "Ông được nhận vào hàng cố vấn của vua sao? Hãy ngừng lại đi! Tại sao ông phải bị đánh?" Rồi đấng tiên tri ngừng lại và nói: "Tôi biết Đức Chúa Trời đã quyết định hủy diệt vua, vì vua đã làm điều này và không nghe theo lời khuyên của tôi."'),
(11722, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 25, 17, 'OT', 'Vua A-ma-xia của Giu-đa bàn luận, rồi sai sứ đến Giô-ách, con trai của Giê-hô-a-ha, con trai của Giê-hu, vua của Y-sơ-ra-ên, nói rằng: "Hãy đến, chúng ta sẽ đối diện nhau."'),
(11723, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 25, 18, 'OT', 'Vua Giô-ách, vua của Y-sơ-ra-ên, sai sứ đến cùng A-ma-xia, vua của Giu-đa, rằng: "Cây tầm gửi ở Li-băng đã sai đến cây bá hương ở Li-băng mà nói: ''Hãy gả con gái ngươi cho con trai ta làm vợ.'' Nhưng có một con thú rừng đi ngang qua Li-băng, giày đạp cây tầm gửi.'),
(11724, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 25, 19, 'OT', 'Ngươi nói: "Này, ta đã đánh bại người Ê-đôm"; lòng ngươi tự đắc đến nỗi muốn kiêu ngạo. Bây giờ hãy ở yên tại nhà ngươi; tại sao ngươi phải gây ra điều dữ, khiến ngươi và Giu-đa cùng ngã xuống?'),
(11725, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 25, 20, 'OT', 'Nhưng A-ma-xia không chịu nghe; vì điều này đến từ Đức Chúa Trời, để họ bị giao vào tay kẻ thù, bởi họ đã tìm theo các thần của Ê-đôm.'),
(11726, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 25, 21, 'OT', 'Vua Yô-ách của Y-sơ-ra-ên đi lên, và hai người nhìn thấy nhau mặt đối mặt, tức là người ấy và A-ma-xia, vua của Giu-đa, tại Bết-sê-mết thuộc về Giu-đa.'),
(11727, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 25, 22, 'OT', 'Giô-đa bị đánh bại trước mặt Ít-ra-en, và mỗi người chạy trốn về trại của mình.'),
(11728, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 25, 23, 'OT', 'Vua Yô-ách, vua của Y-sơ-ra-ên, bắt A-ma-xia, vua của Giu-đa, con trai của Yô-ách, con trai của Giô-ha-ách, tại Bết-sê-mết, rồi dẫn người đến Giê-ru-sa-lem; và người phá vỡ tường thành Giê-ru-sa-lem từ cổng Ép-ra-im cho đến cổng Góc, dài bốn trăm thước.'),
(11729, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 25, 24, 'OT', 'Và tất cả vàng bạc, cùng mọi đồ dùng tìm thấy trong đền thờ Đức Chúa Trời với Ô-bê-đôm, các kho báu trong cung vua, và những con tin, rồi trở về Sa-ma-ri.'),
(11730, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 25, 25, 'OT', 'A-ma-xia, con trai của Giô-ash, vua nước Giu-đa, sống thêm mười lăm năm sau khi Giô-ash, con trai của Giê-hô-a-ha-xu, vua nước Ít-ra-en, qua đời.'),
(11731, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 25, 26, 'OT', 'Còn các việc khác của A-ma-xia, những việc đầu tiên và cuối cùng, thì chẳng phải đã chép trong sách các vua Giu-đa và Y-sơ-ra-ên sao?'),
(11732, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 25, 27, 'OT', 'Từ khi A-ma-xia quay lưng khỏi theo sau Đức Giê-hô-va, người ta lập mưu phản nghịch cùng nhau nghịch lại người tại Giê-ru-sa-lem; người chạy trốn đến La-kích; họ liền sai người đến La-kích đuổi theo, và giết người tại đó.'),
(11733, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 25, 28, 'OT', 'Họ khiêng ông trên những con ngựa và chôn ông cùng với các tổ tiên mình trong thành Giu-đa.'),
(11734, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 26, 1, 'OT', 'Toàn dân Giu-đa lập Út-xia, khi người lên mười sáu tuổi, làm vua thay cho cha mình là A-ma-xia.'),
(11735, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 26, 2, 'OT', 'Người đã xây dựng Ê-lốt và phục hồi nó cho Giu-đa, sau khi vua an nghỉ cùng các tổ tiên mình.'),
(11736, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 26, 3, 'OT', 'U-xi-a được mười sáu tuổi khi người bắt đầu trị vì, và trị vì năm mươi hai năm tại Giê-ru-sa-lem. Tên mẹ người là Giê-cô-lia, người Giê-ru-sa-lem.'),
(11737, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 26, 4, 'OT', 'Và người làm điều ngay thẳng trong mắt Đức Giê-hô-va, giống như mọi điều mà A-ma-xia, cha người, đã làm.'),
(11738, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 26, 5, 'OT', 'Và người tìm kiếm Đức Chúa Trời trong những ngày của Xa-cha-ri, người hiểu biết về sự hiện thấy của Đức Chúa Trời; và trong suốt thời gian người tìm kiếm Đức Giê-hô-va, Đức Chúa Trời khiến người được thạnh vượng.'),
(11739, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 26, 6, 'OT', 'Vua ra đi đánh giặc cùng người Phi-li-tin, phá đổ tường thành Ga-tha, tường thành Gia-ba-nê và tường thành Ách-đốt; rồi vua xây các thành quanh Ách-đốt và trong vùng người Phi-li-tin.'),
(11740, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 26, 7, 'OT', 'Đức Chúa Trời giúp ông chống lại người Phi-li-tin và những người Ả-rập sống ở Ghô-ba-al và những người Mê-hu-nim.'),
(11741, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 26, 8, 'OT', 'Người Am-môn dâng lễ vật cho Út-xia, và danh tiếng người lan rộng cho đến lối vào Ai Cập, vì người được củng cố cách quyền năng.'),
(11742, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 26, 9, 'OT', 'U-xi-a xây các tháp canh tại Giê-ru-sa-lem, ở cổng Góc, ở cổng Thung lũng và ở cổng Đoạn cuối, rồi củng cố các nơi ấy.'),
(11743, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 26, 10, 'OT', 'Người xây các tháp canh trong đồng vắng, đào nhiều giếng, vì người có rất nhiều súc vật, ở vùng đất thấp và đồng bằng; người có những người trồng trọt và trồng nho trên các ngọn núi và ở Carmel, vì người yêu mến nghề nông.'),
(11744, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 26, 11, 'OT', 'Út-xi-a có một đạo quân chiến đấu, những người ra trận theo từng nhóm, theo số lượng đã ghi chép, dưới sự chỉ huy của Giê-i-ên, người văn thư, và Ma-a-sê-gia, người chỉ huy, dưới quyền của Ha-na-nia, một trong các quan tướng của vua.'),
(11745, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 26, 12, 'OT', 'Tất cả số người đứng đầu các họ hàng, những người anh dũng chiến đấu, là hai ngàn sáu trăm người.'),
(11746, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 26, 13, 'OT', 'Dưới quyền chỉ huy của họ có đạo quân ba trăm ngàn người, bảy ngàn năm trăm người, tất cả đều là những người chiến đấu với sức mạnh lớn, để giúp vua chống lại kẻ thù.'),
(11747, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 26, 14, 'OT', 'Vua U-xi-a đã chuẩn bị cho toàn thể đạo quân những cái khiên, giáo, mũ trụ, áo giáp, cung tên và những dây ná để bắn đá.'),
(11748, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 26, 15, 'OT', 'Ông làm tại Giê-ru-sa-lem những máy chiến, do những người khéo léo nghĩ ra, đặt trên các tháp và các góc tường, để bắn tên và những hòn đá lớn. Danh tiếng ông lan xa; vì ông được giúp đỡ cách kỳ diệu cho đến khi trở nên mạnh mẽ.'),
(11749, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 26, 16, 'OT', 'Khi người được quyền lực, lòng người trở nên kiêu ngạo dẫn đến sự bại hoại, và người phạm tội nghịch cùng Đức Giê-hô-va Đức Chúa Trời của mình, nên người vào đền thờ Đức Giê-hô-va để dâng hương trên bàn thờ vàng dâng hương.'),
(11750, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 26, 17, 'OT', 'A-xa-ria, thầy tế lễ, đi theo người, và cùng với ông có tám mươi thầy tế lễ của Đức Giê-hô-va, là những người mạnh dạn:'),
(11751, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 26, 18, 'OT', 'Các thầy tế lễ đứng đối nghịch vua U-xi-a và nói với ông: "Hỡi U-xi-a, không phải phần ngươi để dâng hương cho Đức Giê-hô-va, mà là cho các thầy tế lễ, con cháu A-rôn, là những người đã được biệt riêng ra để dâng hương. Hãy ra khỏi nơi thánh, vì ngươi đã phạm tội; và điều này sẽ không mang lại vinh hiển cho ngươi từ Đức Giê-hô-va Đức Chúa Trời."'),
(11752, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 26, 19, 'OT', 'Ông Út-xi-a nổi giận, tay cầm lư hương để đốt hương. Trong lúc ông nổi giận cùng các thầy tế lễ, thì bệnh phong bắt đầu xuất hiện trên trán ông, trước mặt các thầy tế lễ trong nhà của Đức Giê-hô-va, ngay cạnh bàn thờ đốt hương.'),
(11753, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 26, 20, 'OT', 'Rồi A-xa-ria, thầy tế lễ trưởng, cùng mọi thầy tế lễ đều nhìn về phía vua, và nầy, vua bị phung ở trán mình; nên họ vội đuổi vua ra khỏi đó; chính vua cũng vội vã đi ra, vì Đức Giê-hô-va đã đánh phạt vua.'),
(11754, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 26, 21, 'OT', 'Vua U-xi-a mắc bệnh phong cho đến ngày qua đời, và vua ở trong một nhà riêng biệt, mắc bệnh phong, vì bị truất khỏi đền thờ của Đức Giê-hô-va; còn Giô-tham, con trai vua, thì quản lý cung đình, xét xử dân sự trên đất.'),
(11755, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 26, 22, 'OT', 'Phần còn lại của các việc đời đầu và đời cuối của Út-xia, thì có Ê-sai, con trai A-mốt, là đấng tiên tri, đã chép lại.'),
(11756, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 26, 23, 'OT', 'Ô-zi-a qua đời, được an táng cùng các tổ tiên mình trong khu đất mộ thuộc về các vua; vì người ta nói: "Ông ấy bị phung hủi"; và Giô-tham, con trai ông, lên ngôi kế vị.'),
(11757, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 27, 1, 'OT', 'Giô-tham lúc bắt đầu trị vì được hai mươi lăm tuổi, và người trị vì ở Giê-ru-sa-lem mười sáu năm. Tên mẹ người là Giê-ru-sa, con gái Xa-đốc.'),
(11758, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 27, 2, 'OT', 'Vua Giô-tham làm điều ngay thẳng trước mặt Đức Giê-hô-va, giống như mọi điều mà cha người là vua U-xi-a đã làm; nhưng người không vào đền thờ Đức Giê-hô-va. Dân chúng vẫn tiếp tục làm điều gian ác.'),
(11759, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 27, 3, 'OT', 'Người xây cổng cao của nhà Đức Giê-hô-va, và trên tường thành Ô-phên, Người xây cất nhiều phần.'),
(11760, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 27, 4, 'OT', 'Người xây cất các thành ở núi Giu-đa, và trong các khu rừng, Người xây cất các đồn lũy và tháp canh.'),
(11761, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 27, 5, 'OT', 'Người đã giao chiến với vua con cái Amôn và chiến thắng chúng. Trong năm ấy, con cái Amôn đã nộp cho người một trăm kikar bạc, mười ngàn khor lúa mì và mười ngàn khor lúa mạch. Con cái Amôn đã nộp số đó cho người cả năm thứ hai và năm thứ ba.'),
(11762, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 27, 6, 'OT', 'Vậy, Giô-tham trở nên cường thịnh, vì người đã chuẩn bị các đường lối mình trước mặt Đức Giê-hô-va Đức Chúa Trời của người.'),
(11763, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 27, 7, 'OT', 'Phần còn lại về các việc của Giô-tham, mọi cuộc chiến và mọi đường lối của ông, thì đều đã chép trong sách các vua Y-sơ-ra-ên và Giu-đa.'),
(11764, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 27, 8, 'OT', 'Hắn được hai mươi lăm tuổi khi bắt đầu trị vì, và trị vì mười sáu năm tại Giê-ru-sa-lem.'),
(11765, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 27, 9, 'OT', 'Vua Giô-tham nằm nghỉ cùng tổ tiên mình, và người ta chôn ông trong thành Đa-vít; rồi A-xách, con trai ông, lên ngôi làm vua thay ông.'),
(11766, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 28, 1, 'OT', 'A-cha lên ngôi lúc hai mươi tuổi, và trị vì mười sáu năm tại Giê-ru-sa-lem; nhưng người không làm điều ngay thẳng trước mắt Đức Giê-hô-va như Đa-vít, cha người.'),
(11767, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 28, 2, 'OT', 'Người đi theo các đường lối của các vua Y-sơ-ra-ên, và cũng làm những tượng đúc cho các thần Ba-anh.'),
(11768, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 28, 3, 'OT', 'Và người đã dâng hương trong trũng Bên Hinnom, và thiêu các con mình trong lửa, theo những điều gớm ghê của các dân tộc mà Đức Giê-hô-va đã đuổi ra khỏi trước mặt con cái Y-sơ-ra-ên.'),
(11769, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 28, 4, 'OT', 'Người dâng tế lễ và đốt hương nơi các nơi cao, trên các ngọn đồi, và dưới mọi cây xanh tươi.'),
(11770, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 28, 5, 'OT', 'Vì vậy, Đức Giê-hô-va là Đức Chúa Trời của ông đã phó ông vào tay vua nước A-ram; họ đánh bại ông và bắt đi một số lượng lớn người làm phu tù, rồi mang họ đến Đa-mách. Cũng vậy, ông bị phó vào tay vua Y-sa-ra-ên, và người này đánh bại ông bằng một trận đánh lớn.'),
(11771, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 28, 6, 'OT', 'Bấy giờ Pê-ka, con trai của Rê-ma-lia, đã giết trong Giu-đa một trăm hai mươi ngàn người trong một ngày, tất cả đều là những người dũng cảm, vì họ đã lìa bỏ Đức Giê-hô-va, Đức Chúa Trời của tổ phụ mình.'),
(11772, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 28, 7, 'OT', 'Zích-ri, một người mạnh dạn thuộc chi phái Ép-ra-im, đã giết Ma-a-sê-ia, con trai của vua, và A-xơ-ri-cam, quan cai trị nhà vua, và Ên-ca-na, người đứng hàng thứ nhì sau vua.'),
(11773, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 28, 8, 'OT', 'Con trai của Y-sơ-ra-ên bắt làm phu tù anh em mình hai trăm ngàn người, gồm phụ nữ, con trai và con gái; và cũng cướp lấy rất nhiều chiến lợi phẩm từ chúng, rồi đem số chiến lợi phẩm ấy đến Sa-ma-ri.'),
(11774, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 28, 9, 'OT', 'Tại đó có một đấng tiên tri của Đức Giê-hô-va, tên là Ô-đết; người ra nghênh đón đoàn quân đang đến Sa-ma-ri, và nói với họ: "Nầy, vì cơn thịnh nộ của Đức Giê-hô-va Đức Chúa Trời của tổ tiên các ngươi đối với Giu-đa, nên Ngài đã phó họ vào tay các ngươi; nhưng các ngươi đã giết họ cách hung bạo, đến nỗi sự hung bạo ấy đã lên tận trời.'),
(11775, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 28, 10, 'OT', 'Vả lại, hỡi các ngươi là con cái Giu-đa và Giê-ru-sa-lem, các ngươi định bắt con cái Giu-đa và Giê-ru-sa-lem làm tôi mọi cho các ngươi; nhưng chẳng phải chính các ngươi cũng phạm tội cùng Đức Giê-hô-va Đức Chúa Trời các ngươi sao?'),
(11776, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 28, 11, 'OT', 'Vậy bây giờ hãy nghe tôi và trả lại những người bị bắt mà các anh đã bắt từ anh em mình; vì cơn thịnh nộ dữ dội của Đức Giê-hô-va đang nổi giận các anh.'),
(11777, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 28, 12, 'OT', 'Bấy giờ các người lãnh tụ con cháu Ép-ra-im, là A-xa-ria con trai của Giô-ha-nan, Bê-rê-ki-a con trai của Mê-si-lê-mốt, Giê-hi-xki-a con trai của Sa-lum, và A-ma-sa con trai của Ha-đlai, đứng lên chống lại những người từ đạo quân trở về.'),
(11778, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 28, 13, 'OT', 'Họ nói với họ: "Các ngươi không được mang những người bị bắt làm tù binh này đến đây, vì các ngươi đang nói rằng hãy làm tăng thêm tội lỗi và sự vi phạm của chúng ta trước Đức Giê-hô-va; sự vi phạm của chúng ta đã rất lớn, và cơn thịnh nộ dữ dội đã giáng trên Ít-ra-en."'),
(11779, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 28, 14, 'OT', 'Những người lính vũ trang bỏ các phu tù và chiến lợi phẩm lại trước mặt các quan trưởng và toàn thể hội chúng.'),
(11780, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 28, 15, 'OT', 'Các người đã được chỉ định theo tên liền đứng dậy, đem những người bị bắt làm tù binh, lấy của cải chiến lợi phẩm mà mặc cho tất cả những người trần truồng trong bọn họ, rồi mặc cho họ, xỏ giày vào chân họ, cho họ ăn và uống, xức dầu cho họ, và đưa những người yếu ớt trong bọn họ đi trên các con lừa đến Giê-ri-cô, thành phố của các cây chà là, để đoàn tụ với anh em mình; sau đó họ trở về Sa-ma-ri.'),
(11781, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 28, 16, 'OT', 'Vào thời ấy, vua A-xát sai sứ đến các vua Át-xu-ri xin giúp đỡ mình.'),
(11782, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 28, 17, 'OT', 'Đoạn người Ê-đôm lại đến, đánh vào Giu-đa và bắt đi một số người làm phu tù.'),
(11783, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 28, 18, 'OT', 'Người Phi-li-tin cũng xâm chiếm các thành phố ở các vùng đồng bằng thấp và miền nam xứ Giu-đa, chiếm lấy Bết Sê-mết, A-ya-lôn, Ghê-đe-rốt, Sô-cô và các làng mạc chung quanh nó, rồi đến Tim-na và các làng mạc chung quanh nó, và Ghim-3ô cùng các làng mạc chung quanh nó, rồi ở lại đó.'),
(11784, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 28, 19, 'OT', 'Vì Đức Giê-hô-va đã khu phục Giu-đa vì cớ A-xách, vua Y-sơ-ra-ên; vì người đã làm cho Giu-đa trở nên hỗn loạn, và phạm tội nặng nề cùng Đức Giê-hô-va.'),
(11785, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 28, 20, 'OT', 'Vua Tilgath-pilneser của Ái-thuật đến nghịch cùng người, và gây khốn khổ cho người, nhưng chẳng giúp người thêm mạnh.'),
(11786, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 28, 21, 'OT', 'Vì A-cha đã lấy phần của đền thờ Đức Giê-hô-va, và của đền vua cùng các quan trưởng, rồi dâng cho vua A-si-ri: nhưng người ấy không giúp đỡ nó.'),
(11787, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 28, 22, 'OT', 'Trong lúc gặp khốn khổ, vua A-cha lại càng phạm tội nghịch cùng Đức Giê-hô-va.'),
(11788, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 28, 23, 'OT', 'Và người đã dâng tế lễ cho các thần của Đam-xéc, là những thần đã đánh bại mình; người nói: "Vì các thần của các vua Sy-ri giúp đỡ họ, nên ta sẽ dâng tế lễ cho chúng, để chúng giúp đỡ ta." Nhưng chính chúng lại trở nên nguyên nhân làm cho người và toàn thể Y-sơ-ra-ên sa ngã.'),
(11789, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 28, 24, 'OT', 'A-cha nhóm lại các khí cụ trong đền thờ Đức Chúa Trời, rồi đập vỡ các khí cụ trong đền thờ Đức Chúa Trời, đóng các cửa đền thờ Đức Giê-hô-va, và lập cho mình các bàn thờ ở khắp các ngã tư đường trong Giê-ru-sa-lem.'),
(11790, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 28, 25, 'OT', 'Và tại mỗi thành và thành của Giu-đa, người ấy lập các nơi cao để đốt hương cho các thần khác, và chọc giận Đức Giê-hô-va, Đức Chúa Trời của tổ tiên người.'),
(11791, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 28, 26, 'OT', 'Còn các việc khác của ông và mọi đường lối của ông, những việc đầu tiên và cuối cùng, đều đã chép trong sách các vua Giu-đa và Y-sơ-ra-ên.'),
(11792, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 28, 27, 'OT', 'A-hác nằm ngủ cùng các tổ tiên mình, và người ta chôn ông trong thành Giê-ru-sa-lem; nhưng họ không đưa ông vào các phần mộ của các vua Y-sơ-ra-ên. Rồi Ê-xê-chia, con trai ông, lên ngôi kế vị.'),
(11793, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 1, 'OT', 'Ê-xê-chia lên ngôi làm vua lúc được hai mươi lăm tuổi, và trị vì hai mươi chín năm tại Giê-ru-sa-lem. Tên mẹ ông là A-bi-gia, con gái Xác-cha-ri.'),
(11794, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 2, 'OT', 'Và người đã làm điều ngay thẳng trước mắt Đức Giê-hô-va, giống như tất cả những gì Đa-vít, cha người, đã làm.'),
(11795, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 3, 'OT', 'Người mở các cửa đền thờ của Đức Giê-hô-va và sửa chữa chúng trong tháng đầu tiên, năm đầu tiên đời trị vì của người.'),
(11796, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 4, 'OT', 'Ông đưa các thầy tế lễ và người Lê-vi vào, rồi triệu tập họ đến hành lang phía đông.'),
(11797, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 5, 'OT', 'Hỡi các thầy Lê-vi, hãy nghe ta: Hãy tự biệt riêng mình ra thánh, và thánh hóa đền thờ của Đức Giê-hô-va Đức Chúa Trời của tổ tiên các ngươi, rồi khiêng những vật ô uế ra khỏi nơi thánh.'),
(11798, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 6, 'OT', 'Vì tổ tiên chúng ta đã phạm tội, làm điều ác trước mặt Đức Giê-hô-va Đức Chúa Trời chúng ta, bỏ Ngài, quay mặt khỏi nơi ở của Đức Giê-hô-va và ngoảnh lưng lại.'),
(11799, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 7, 'OT', 'Họ cũng đã đóng các cửa hành lang, dập tắt các ngọn đèn, không đốt hương, không dâng của lễ thiêu trong nơi thánh cho Đức Chúa Trời của Y-sơ-ra-ên.'),
(11800, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 8, 'OT', 'Vì vậy, cơn thịnh nộ của Đức Giê-hô-va nổi lên nghịch cùng Giu-đa và Giê-ru-sa-lem, và Ngài đã phó họ vào sự kinh hãi, hoang vu và chế giễu, như các ngươi thấy bằng chính mắt mình.'),
(11801, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 9, 'OT', 'Nầy, tổ tiên chúng ta đã ngã dưới lưỡi gươm, và con trai, con gái, vợ chúng ta bị bắt làm phu tù vì điều nầy.'),
(11802, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 10, 'OT', 'Bây giờ, lòng tôi quyết tâm lập giao ước với Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên, để cơn thịnh nộ của Ngài quay khỏi chúng ta.'),
(11803, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 11, 'OT', 'Hỡi các con ta, bây giờ chớ làm điều sơ suất; vì Đức Giê-hô-va đã chọn các con để đứng trước mặt Ngài, hầu phục sự Ngài, và làm đầy tớ cho Ngài, cùng dâng hương.'),
(11804, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 12, 'OT', 'Các thầy Lê-vi đứng dậy, Ma-hát con trai của A-ma-xai, và Giô-ên con trai của A-xa-ria, thuộc con cháu Kê-hát; và thuộc con cháu Mê-ra-ri, Kít con trai của Áp-di, và A-xa-ria con trai của Giê-ha-lê-ên; và thuộc con cháu Ghẹt-xun, Giô-ách con trai của Xim-ma, và Ê-đen con trai của Giô-ách.'),
(11805, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 13, 'OT', 'Và trong con cái của Ê-li-xa-phan có Sim-ri và Giê-i-ên; và trong con cái của A-sáp có Xa-cha-ri và Ma-ta-nia.'),
(11806, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 14, 'OT', 'Thuộc về con trai của Hê-man: Giê-hi-ên và Si-mê-i; và thuộc về con trai của Giê-đu-thun: Sê-ma-gia và Út-xi-ên.'),
(11807, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 15, 'OT', 'Họ tập hợp các anh em mình, rồi làm cho mình nên thánh, và đến theo mệnh lệnh của vua và theo lời của Đức Giê-hô-va, để làm sạch đền thờ của Đức Giê-hô-va.'),
(11808, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 16, 'OT', 'Các thầy tế lễ vào bên trong đền thờ Đức Giê-hô-va để làm sạch, và họ mang ra ngoài tất cả những vật ô uế mà họ tìm thấy trong đền thờ Đức Giê-hô-va, đến hành lang của đền thờ Đức Giê-hô-va; rồi các thầy Lê-vi nhận lấy để mang ra ngoài, đến suối Ki-trôn.'),
(11809, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 17, 'OT', 'Họ bắt đầu vào ngày mồng một tháng đầu tiên để làm lễ thanh tẩy, và vào ngày tám của tháng đó, họ đến hành lang của đền Đức Giê-hô-va; họ thanh tẩy đền Đức Giê-hô-va trong tám ngày; và vào ngày mười sáu tháng đầu tiên, họ hoàn tất.'),
(11810, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 18, 'OT', 'Họ vào cùng vua Ê-xê-chia và thưa rằng: Chúng tôi đã làm sạch toàn bộ nhà của Đức Giê-hô-va, bàn thờ của của lễ thiêu cùng với mọi đồ dùng của nó, bàn bánh trần thiết cùng với mọi đồ dùng của nó.'),
(11811, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 19, 'OT', 'Chúng tôi cũng đã sửa sang và biệt riêng thánh mọi đồ dùng mà vua A-cha trong triều đại mình đã bỏ bê vì tội phạm của mình, và nầy, chúng nó ở trước bàn thờ của Đức Giê-hô-va.'),
(11812, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 20, 'OT', 'Vua Ê-xê-chia dậy sớm, triệu tập các quan trưởng trong thành, rồi cùng lên đền thờ Đức Giê-hô-va.'),
(11813, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 21, 'OT', 'Họ mang đến bảy con bò đực, bảy con chiên đực, bảy con chiên con và bảy con dê đực làm của lễ chuộc tội cho vương quốc, cho đền thánh và cho Giu-đa. Người ra lệnh cho các thầy tế lễ, con trai A-ha-ron, dâng những con vật này lên bàn thờ của Đức Giê-hô-va.'),
(11814, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 22, 'OT', 'Vậy, họ giết các con bò đực, các thầy tế lễ nhận lấy huyết rồi rảy lên bàn thờ; họ cũng giết các con chiên đực, rảy huyết lên bàn thờ; rồi họ giết các con chiên con, và rảy huyết lên bàn thờ.'),
(11815, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 23, 'OT', 'Họ dâng các dê đực làm của lễ chuộc tội ra trước mặt vua và hội chúng; rồi đặt tay mình lên chúng.'),
(11816, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 24, 'OT', 'Các thầy tế lễ đã giết những con vật ấy, rồi dùng huyết của chúng rảy trên bàn thờ để làm lễ chuộc tội cho toàn thể Y-sơ-ra-ên; vì nhà vua đã truyền rằng của lễ thiêu và của lễ chuộc tội phải dâng thay cho toàn thể Y-sơ-ra-ên.'),
(11817, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 25, 'OT', 'Ông đặt các thầy Lê-vi trong đền thờ của Đức Giê-hô-va với những chiếc chập chỏa, đàn cầm và đàn sắt, theo lệnh của Đa-vít, của Gát, nhà tiên kiến của vua, và Na-than, nhà tiên tri; vì mạng lịnh ấy là của Đức Giê-hô-va, do tay các nhà tiên tri của Ngài.'),
(11818, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 26, 'OT', 'Các thầy Lê-vi đứng với các nhạc khí của Đa-vít, và các thầy tế lễ với những chiếc kèn.'),
(11819, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 27, 'OT', 'Ê-xê-chia truyền dâng lễ thiêu trên bàn thờ; và khi lễ thiêu bắt đầu, bài ca ngợi Đức Giê-hô-va cũng bắt đầu với tiếng kèn và các nhạc cụ của Đa-vít, vua Y-sơ-ra-ên.'),
(11820, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 28, 'OT', 'Toàn thể hội chúng cúi lạy, các ca sĩ thì hát, các nhạc công thổi kèn; mọi việc đó tiếp tục cho đến khi của lễ thiêu được dâng trọn vẹn.'),
(11821, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 29, 'OT', 'Khi các thầy xong việc dâng của lễ thiêu, thì vua cùng tất cả những người hiện diện với người đều cúi lạy và thờ lạy.'),
(11822, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 30, 'OT', 'Vua Hi-ki-a và các quan chức truyền cho những người Lê-vi hãy ca ngợi Đức Giê-hô-va bằng các lời của Đa-vít và Ách-áp, người thấy đạo. Họ liền ca ngợi với lòng vui mừng, cúi đầu và thờ lạy.'),
(11823, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 31, 'OT', 'Hê-xê-chi-a đáp và nói: "Bây giờ các ngươi đã dâng mình cho Đức Giê-hô-va, hãy đến gần và mang lễ vật cùng lễ tạ ơn vào nhà Đức Giê-hô-va." Dân chúng liền mang lễ vật và lễ tạ ơn; và mỗi người có lòng hăng hái thì mang lễ thiêu.'),
(11824, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 32, 'OT', 'Số lượng sinh tế thiêu mà hội chúng dâng gồm bảy mươi con bò đực, một trăm con chiên đực, hai trăm con chiên con: tất cả những điều này đều là sinh tế thiêu dâng cho Đức Giê-hô-va.'),
(11825, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 33, 'OT', 'Các của lễ thánh là sáu trăm con bò và ba ngàn con chiên.'),
(11826, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 34, 'OT', 'Dù các thầy tế lễ quá ít, không thể lột da hết các của lễ thiêu, nhưng anh em họ là những người Lê-vi đã giúp đỡ họ cho đến khi công việc hoàn tất và các thầy tế lễ đã được biệt riêng ra thánh; vì những người Lê-vi có lòng thành thực hơn các thầy tế lễ trong việc biệt riêng mình ra thánh.'),
(11827, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 35, 'OT', 'Hỏa lễ thì rất dồi dào, cùng với mỡ các của lễ thù ân và các lễ đồ uống cho mỗi của lễ thiêu; như thế, công việc phục vụ trong đền thờ Đức Giê-hô-va được tổ chức ổn định.'),
(11828, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 29, 36, 'OT', 'Đức vua Ê-xê-chia và toàn thể dân chúng đều vui mừng, vì Đức Chúa Trời đã chuẩn bị sẵn lòng dân; vì công việc ấy được thực hiện cách bất ngờ.'),
(11829, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 30, 1, 'OT', 'Ê-xê-chia sai sứ đi khắp toàn thể Y-sơ-ra-ên và Giu-đa, và cũng viết thơ gởi cho Ép-ra-im và Ma-na-xe, mời họ đến đền thờ của Đức Giê-hô-va tại Giê-ru-sa-lem để giữ lễ Vượt Qua cho Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên.'),
(11830, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 30, 2, 'OT', 'Vua cùng các quan trưởng và toàn thể hội chúng tại Giê-ru-sa-lem đã cùng bàn luận để giữ lễ Vượt Qua vào tháng thứ hai.'),
(11831, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 30, 3, 'OT', 'Vì họ không thể giữ lễ vào thời điểm ấy, vì các thầy tế lễ chưa được biệt riêng đủ mức, và dân chúng cũng chưa được tập họp về Giê-ru-sa-lem.'),
(11832, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 30, 4, 'OT', 'Việc ấy đẹp lòng vua và toàn thể hội chúng.'),
(11833, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 30, 5, 'OT', 'Họ quyết định ban hành lệnh truyền khắp toàn thể Y-sơ-ra-ên, từ Bê-e-Sê-ba cho đến Đan, để dân chúng đến giữ lễ Vượt Qua cho Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên tại Giê-ru-sa-lem; vì phần đông chưa giữ lễ theo cách đã chép trong Kinh Thánh.'),
(11834, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 30, 6, 'OT', 'Các sứ giả đi khắp Ít-ra-en và Giu-đa, mang những bức thư từ tay vua và các quan chức, theo lệnh vua mà nói rằng: Hỡi con cháu Ít-ra-en, hãy trở lại cùng Đức Giê-hô-va Đức Chúa Trời của Áp-ra-ham, Y-sác và Ít-ra-en, thì Ngài sẽ trở lại cùng số ít còn sót lại của các ngươi, tức những người đã thoát khỏi tay các vua A-xi-ri.'),
(11835, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 30, 7, 'OT', 'Và đừng nên giống như tổ tiên các ngươi và như anh em các ngươi, là những người đã phạm tội nghịch cùng Đức Giê-hô-va Đức Chúa Trời của tổ tiên họ, nên Ngài đã phó họ vào cảnh điêu tàn, như các ngươi thấy vậy.'),
(11836, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 30, 8, 'OT', 'Bây giờ, chớ cứng cổ như tổ tiên các ngươi; hãy dâng tay cho Đức Giê-hô-va và đến cùng đền thánh mà Ngài đã biệt riêng để dùng đời đời, và hãy hầu việc Đức Giê-hô-va Đức Chúa Trời các ngươi, hầu cho cơn thạnh nộ của Ngài rút khỏi các ngươi.'),
(11837, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 30, 9, 'OT', 'Vì nếu các ngươi trở lại cùng Đức Giê-hô-va, anh em và con cái các ngươi sẽ được thương xót trước mặt những kẻ đã bắt giữ họ, và họ sẽ trở lại đất nầy; vì Đức Giê-hô-va Đức Chúa Trời các ngươi là đầy ơn và lòng thương xót, và Ngài sẽ không quay mặt khỏi các ngươi, nếu các ngươi trở lại cùng Ngài.'),
(11838, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 30, 10, 'OT', 'Các sứ giả đi từ thành này sang thành khác trong đất Ép-ra-im và Ma-na-se, cho đến Xê-bu-lun, nhưng người ta chế nhạo và sỉ nhục họ.'),
(11839, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 30, 11, 'OT', 'Dù vậy, vài người từ A-ser, từ Ma-na-xe và từ Xê-bu-lun đã khiêm nhường mình và đến Giê-ru-sa-lem.'),
(11840, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 30, 12, 'OT', 'Cũng tại Giu-đa, tay Đức Chúa Trời giúp cho dân sự có một lòng để thi hành mệnh lệnh của vua và các quan trưởng, theo lời của Đức Giê-hô-va.'),
(11841, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 30, 13, 'OT', 'Dân chúng đông đảo đã tụ họp tại Giê-ru-sa-lem để giữ lễ Vượt Qua trong tháng thứ hai; ấy là một hội chúng rất đông đảo.'),
(11842, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 30, 14, 'OT', 'Họ đứng dậy, dẹp bỏ các bàn thờ ở Giê-ru-sa-lem, và loại bỏ mọi bàn thờ dùng để đốt hương; họ ném những thứ đó xuống suối Ki-trôn.'),
(11843, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 30, 15, 'OT', 'Họ giết lễ Vượt Qua vào ngày mười bốn của tháng thứ hai; các thầy tế lễ và người Lê-vi cảm thấy xấu hổ, nên họ làm cho mình nên thánh và mang các của lễ thiêu vào nhà Đức Giê-hô-va.'),
(11844, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 30, 16, 'OT', 'Họ đứng tại chỗ của mình theo nghi thức riêng, theo luật pháp của Môi-se, người của Đức Chúa Trời; các thầy tế lễ rảy huyết mà họ nhận từ tay các người Lê-vi.'),
(11845, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 30, 17, 'OT', 'Vì có rất nhiều người trong hội chúng chưa được biệt riêng ra, nên các thầy Lê-vi phải lo việc giết các con chiên Vượt Qua cho mọi người không sạch, để biệt riêng họ ra thánh cho Đức Giê-hô-va.'),
(11846, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 30, 18, 'OT', 'Vì dân chúng đông đảo, nhất là từ Ép-ra-im, Man-na-xe, Y-xa-sa-cha và Xê-bu-lôn, không thanh tẩy mình, nhưng vẫn ăn lễ Vượt Qua không theo như điều đã chép. Song Ê-xe-chia cầu xin cho họ, rằng: Đức Giê-hô-va, là Đấng nhân từ, xin tha thứ cho mỗi người.'),
(11847, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 30, 19, 'OT', 'Chúng hết lòng chuẩn bị để tìm kiếm Đức Giê-hô-va, Đức Chúa Trời của tổ tiên mình, dù chưa được tinh sạch theo nghi thức thánh.'),
(11848, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 30, 20, 'OT', 'Đức Giê-hô-va nghe lời Hê-xê-kia và chữa lành cho dân chúng.'),
(11849, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 30, 21, 'OT', 'Dân Y-sơ-ra-ên có mặt tại Giê-ru-sa-lem giữ lễ bánh không men bảy ngày trong niềm vui mừng lớn; còn các thầy Lê-vi và các thầy tế lễ thì ngày ngày dùng nhạc khí hùng tráng để ca ngợi Đức Giê-hô-va.'),
(11850, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 30, 22, 'OT', 'Ê-xê-chia nói khích lệ mọi thầy Lê-vi, là những người dạy biết sự hiểu biết tốt về Đức Giê-hô-va; và họ ăn mừng lễ bảy ngày, dâng các của lễ thù ơn, và xưng tội cùng Đức Giê-hô-va Đức Chúa Trời của tổ tiên họ.'),
(11851, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 30, 23, 'OT', 'Cả hội chúng cùng bàn bạc để giữ bảy ngày nữa, và họ đã giữ bảy ngày vui mừng ấy.'),
(11852, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 30, 24, 'OT', 'Vì vua Ê-xê-chia của Giu-đa đã dâng cho hội chúng một ngàn con bò đực và bảy ngàn chiên; còn các quan lại thì dâng cho hội chúng một ngàn con bò đực và mười ngàn chiên; và rất nhiều thầy tế lễ đã tự biệt riêng ra thánh.'),
(11853, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 30, 25, 'OT', 'Toàn thể hội chúng Giu-đa, các thầy tế lễ, người Lê-vi, toàn thể hội chúng từ Ít-ra-en đến, và những người ngoại bang từ đất Ít-ra-en đến và cư ngụ tại Giu-đa đều vui mừng.'),
(11854, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 30, 26, 'OT', 'Vậy nên có sự vui mừng lớn tại Giê-ru-sa-lem; vì từ thời Sa-lô-môn, con trai của Đa-vít, vua Ít-ra-en, chưa từng có điều gì giống như vậy tại Giê-ru-sa-lem.'),
(11855, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 30, 27, 'OT', 'Các thầy tế lễ người Lê-vi đứng dậy và chúc phước cho dân chúng; tiếng của họ được lắng nghe, và lời cầu nguyện của họ đến nơi thánh của Ngài ở trên trời.'),
(11856, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 31, 1, 'OT', 'Sau khi mọi việc nầy đã hoàn tất, toàn thể Y-sơ-ra-ên hiện diện đều đi ra các thành của Giu-đa, đập phá các tượng trụ thờ, chặt các cây thờ A-she-ra, phá hủy các nơi cao và các bàn thờ trong khắp Giu-đa, Bên-gia-min, Ép-ra-im và Ma-na-xe, cho đến khi hoàn toàn tiêu diệt chúng. Rồi toàn thể con cái Y-sơ-ra-ên trở về, mỗi người vào đất sản nghiệp mình, về các thành của họ.'),
(11857, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 31, 2, 'OT', 'Ê-xê-chi-a thiết lập các nhóm của các thầy tế lễ và người Lê-vi theo các nhóm của họ, mỗi người theo chức vụ mình, để các thầy tế lễ và người Lê-vi lo việc của các lễ thiêu và lễ thù ân, phục vụ, cảm tạ và ca ngợi tại các cổng đền tạm của Đức Giê-hô-va.'),
(11858, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 31, 3, 'OT', 'Phần do vua cấp từ tài sản của mình là để dâng các của lễ thiêu, tức là các của lễ thiêu buổi sáng và chiều, cùng các của lễ thiêu trong các ngày Sa-bát, các ngày đầu tháng và các lễ hội định kỳ, như đã chép trong luật pháp của Đức Giê-hô-va.'),
(11859, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 31, 4, 'OT', 'Người ra lệnh cho dân cư ở Giê-ru-sa-lem phải nộp phần tithes dành cho các thầy tế lễ và người Lê-vi, để họ có thể chuyên tâm vào luật của Đức Giê-hô-va.'),
(11860, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 31, 5, 'OT', 'Khi tin về sắc lệnh được loan ra, con cái Ít-ra-en liền dâng nhiều sản vật đầu mùa về lúa mì, rượu, dầu ô-liu và mật ong, cũng như mọi sản phẩm của đồng ruộng; và họ mang đến dâng phần mười của mọi thứ một cách dồi dào.'),
(11861, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 31, 6, 'OT', 'Các con trai của Y-sơ-ra-ên và Giu-đa sống trong các thành của Giu-đa cũng dâng phần mười của bò đực và chiên, cùng phần mười các vật thánh đã được biệt riêng ra cho Đức Giê-hô-va Đức Chúa Trời của họ, rồi họ mang đến và chất thành từng đống.'),
(11862, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 31, 7, 'OT', 'Đến tháng thứ ba, họ bắt đầu chất các đống lương thực, và đến tháng thứ bảy thì hoàn tất.'),
(11863, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 31, 8, 'OT', 'Vậy, khi Hê-xê-kia và các quan chức đến thấy những đống chất đầy ấy, thì họ chúc phước cho Đức Giê-hô-va và cho dân sự Y-sơ-ra-ên của Ngài.'),
(11864, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 31, 9, 'OT', 'Rồi Ê-xê-chia hỏi các thầy tế lễ và người Lê-vi về các đống chất đó.'),
(11865, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 31, 10, 'OT', 'Và A-xa-ria, thầy tế lễ cả thuộc nhà Xa-đốc, đáp với người rằng: "Từ khi dân bắt đầu mang các lễ vật đến nhà Đức Giê-hô-va, chúng tôi đã có đủ ăn, được no nê, và còn dư lại rất nhiều; vì Đức Giê-hô-va đã ban phước cho dân Ngài; và điều còn lại là kho tàng lớn này."'),
(11866, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 31, 11, 'OT', 'Bấy giờ, Ê-xê-chia truyền phải chuẩn bị các phòng trong nhà của Đức Giê-hô-va; và họ đã chuẩn bị.'),
(11867, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 31, 12, 'OT', 'Họ mang đến các lễ dâng, các phần thập phần và các vật biệt riêng ra thánh một cách trung tín; và người quản lý các công việc ấy là Kô-nan-ya, người Lê-vi, còn Si-mê-i, anh trai người, thì giúp việc.'),
(11868, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 31, 13, 'OT', 'Và Giê-hi-ên, A-xa-zi-a, Na-hát, A-sa-ên, Giê-ri-mốt, Giô-xa-bát, Ê-li-ên, Ít-ma-ki-a, Ma-hát và Bê-nai-a, đều là các viên chức quản lý dưới quyền Cô-nô-nia và Si-mi, anh em của người ấy, theo lệnh của vua Ê-xê-chia và A-xa-ria, viên chức cai quản nhà Đức Chúa Trời.'),
(11869, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 31, 14, 'OT', 'Và Kore, con trai của Im-na, người Lê-vi, người giữ cửa về hướng đông, được đặt quản lý các lễ dâng tự nguyện cho Đức Chúa Trời, để phân phát các của lễ dâng cho Đức Giê-hô-va và các vật thánh nhất.'),
(11870, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 31, 15, 'OT', 'Và dưới quyền ông có Ê-đên, Minh-ya-min, Giê-sua, Sê-ma-gia, A-ma-ri-a, và Sê-can-gia, ở các thành của các thầy tế lễ, cách trung tín, để phân phát cho anh em mình theo từng nhóm, từ người lớn đến người nhỏ.'),
(11871, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 31, 16, 'OT', 'Ngoài những người nam được ghi trong gia phả, từ con trai ba tuổi trở lên, cho mỗi người vào đền thờ Đức Giê-hô-va, phần hằng ngày cho công việc của họ, theo các nhóm phục vụ và theo nhiệm vụ của họ theo từng kỳ.'),
(11872, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 31, 17, 'OT', 'Và về gia phả của các thầy tế lễ theo nhà tổ tiên họ, và các người Lê-vi từ hai mươi tuổi trở lên, theo nhiệm vụ của họ theo từng ban riêng.'),
(11873, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 31, 18, 'OT', 'và cho gia đình của tất cả con cái nhỏ, vợ, con trai và con gái của chúng, thuộc toàn thể hội chúng; vì trong đức tin của chúng, chúng đã biệt riêng mình ra thánh.'),
(11874, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 31, 19, 'OT', 'Và cho các con trai A-ha-ron, các thầy tế lễ, ở các vùng đất đồng ngoại quanh các thành của họ, tại mỗi thành và thành, những người đàn ông đã được chỉ định rõ tên, để phân phát phần cho mọi người nam trong các thầy tế lễ, và cho mọi người được ghi chép theo gia phổ trong vòng người Lê-vi.'),
(11875, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 31, 20, 'OT', 'Ê-xê-chia làm như vậy trong khắp cả xứ Giu-đa, và thực hiện điều thiện, điều ngay thẳng, và điều chân thật trước mặt Đức Giê-hô-va Đức Chúa Trời của ông.'),
(11876, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 31, 21, 'OT', 'Và trong mọi công việc mà người khởi sự làm trong sự phục vụ đền thờ Đức Chúa Trời, trong luật pháp và các điều răn, để tìm cầu Đức Chúa Trời mình, người đều làm với trọn tấm lòng mình, và được thạnh vượng.'),
(11877, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 1, 'OT', 'Sau các việc ấy và sự thật này, San-chết-rip vua A-si-ri đến, xâm nhập vào Giu-đa, đóng trại chống các thành có tường vững chắc, và toan tính chiếm chúng về mình.'),
(11878, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 2, 'OT', 'Khi Ê-xê-chia thấy Xanh-ke-ríp đã đến và có ý định chiến đấu chống lại Giê-ru-sa-lem,'),
(11879, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 3, 'OT', 'Ông cùng các quan trưởng và các dũng sĩ bàn kế hoạch bịt các nguồn nước ở bên ngoài thành phố; và họ giúp ông thực hiện điều đó.'),
(11880, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 4, 'OT', 'Vậy dân chúng tập họp đông đảo, và họ bịt tất cả các mạch nước cùng con suối chảy giữa đất, nói rằng: "Tại sao các vua Ách-siếc lại đến và tìm thấy nhiều nước?"'),
(11881, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 5, 'OT', 'Ngài củng cố sức lực, xây cất lại tất cả đoạn tường bị sập, xây cao các tháp canh, xây thêm một bức tường khác bên ngoài, củng cố phần đất đầy trong thành Đa-vít, và làm rất nhiều giáo cùng khiên.'),
(11882, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 6, 'OT', 'Ông đặt các viên chỉ huy quân đội trên dân chúng, rồi tập hợp họ nơi phố trước cửa thành; ông nói khích lệ lòng họ, rằng:'),
(11883, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 7, 'OT', 'Hãy mạnh dạn và can đảm, đừng sợ hãi cũng đừng kinh hoàng vì vua A-si-ri và vì mọi đoàn quân đi cùng người ấy; vì Đấng ở cùng chúng ta đông hơn là ở cùng người ấy.'),
(11884, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 8, 'OT', 'Cùng người chỉ là cánh tay bằng thịt; nhưng cùng chúng ta là Đức Giê-hô-va Đức Chúa Trời chúng ta để giúp đỡ và chiến đấu cho các trận chiến của chúng ta. Dân chúng bèn nhờ cậy vào các lời của Ê-xê-chia, vua Giu-đa.'),
(11885, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 9, 'OT', 'Sau việc này, San-cha-rip, vua nước A-si-ri, sai các đầy tớ người đến Giê-ru-sa-lem, còn chính người thì đang ở tại La-kích, cùng với toàn thể đạo quân người, để nói cùng Hê-xê-kia, vua nước Giu-đa, và cùng toàn thể người Giu-đa đang ở Giê-ru-sa-lem, rằng:'),
(11886, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 10, 'OT', 'Đây, Sát-na-kê-rib, vua nước A-ssu-ri, phán: "Các ngươi tin cậy điều gì mà cứ ở lại trong thành Giê-ru-sa-lem bị vây thành này?"'),
(11887, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 11, 'OT', 'Hẳn là Hê-xê-kia không phải đang xúi giục các ngươi để các ngươi chết đói và chết khát sao, khi nói rằng: "Đức Giê-hô-va Đức Chúa Trời chúng ta sẽ giải cứu chúng ta khỏi tay vua Ái-thu?'),
(11888, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 12, 'OT', 'Hả chẳng phải chính Ê-xê-chia đã dẹp các nơi cao và các bàn thờ của người, rồi truyền cho Giu-đa và Giê-ru-sa-lem rằng: "Các ngươi sẽ thờ lạy trước một bàn thờ duy nhất và dâng hương trên đó sao?"'),
(11889, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 13, 'OT', 'Các ngươi há chẳng biết điều ta và các tổ phụ ta đã làm cho mọi dân các xứ sao? Các thần của các nước ấy há có thể cứu đất nước mình khỏi tay ta được chăng?'),
(11890, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 14, 'OT', 'Ai trong mọi thần các nước mà tổ tiên ta đã tiêu diệt, có thể giải cứu dân mình khỏi tay ta, mà các thần của các ngươi lại có thể giải cứu các ngươi khỏi tay ta?'),
(11891, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 15, 'OT', 'Bây giờ, đừng để Hê-xê-kia làm các ngươi bị lừa dối, cũng đừng để người xúi giục các ngươi như thế nầy, và đừng tin người; vì chẳng một thần nào của bất cứ dân tộc hay vương quốc nào có thể giải cứu dân mình khỏi tay ta và khỏi tay tổ tiên ta; huống chi thần của các ngươi, chẳng thể nào giải cứu các ngươi khỏi tay ta!'),
(11892, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 16, 'OT', 'Các tôi tớ của ông còn nói thêm những lời chống lại Đức Giê-hô-va Đức Chúa Trời và chống lại đầy tớ Ngài là Hê-xê-kia.'),
(11893, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 17, 'OT', 'Người cũng viết những bức thư để sỉ vả Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en, và nói nghịch cùng Ngài rằng: "Như các thần của các nước trên đất đã không giải cứu dân sự mình khỏi tay ta, thì cũng vậy, Đức Chúa Trời của Hê-xê-kia sẽ không giải cứu dân sự Ngài khỏi tay ta."'),
(11894, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 18, 'OT', 'Họ kêu lớn bằng tiếng Do-thái về phía dân Giê-ru-sa-lem đang ở trên vách thành, để khiếp sợ và làm rối trí họ, hầu chiếm lấy thành phố.'),
(11895, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 19, 'OT', 'Họ nói nghịch lại Đức Chúa Trời của Giê-ru-sa-lem như thể nghịch lại các thần của các dân trên đất, là những thần do tay người làm ra.'),
(11896, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 20, 'OT', 'Vua Ê-xê-chia và Ê-sai, con trai của A-mốt, là đấng tiên tri, đã cầu nguyện về việc nầy; và họ kêu khẩn lên trời.'),
(11897, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 21, 'OT', 'Đức Giê-hô-va sai một thiên sứ đi, và thiên sứ tiêu diệt tất cả các chiến sĩ dũng cảm, các quan chỉ huy và các tướng lãnh trong trại của vua A-xi-ri. Vua ấy bèn trở về đất nước mình trong sự hổ thẹn. Khi người vào nhà thần của mình, thì những người con ruột thịt của người đã giết người bằng gươm tại đó.'),
(11898, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 22, 'OT', 'Đức Giê-hô-va cứu Ê-xê-chia và những người ở Giê-ru-sa-lem khỏi tay San-chê-rib, vua Ái-thu, và khỏi tay mọi kẻ thù, rồi dẫn dắt họ từ mọi phía.'),
(11899, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 23, 'OT', 'Rất nhiều người mang lễ vật dâng cho Đức Giê-hô-va tại Giê-ru-sa-lem, và các của lễ cho Ê-xê-chia, vua nước Giu-đa; từ thời đó, người được tôn trọng trước mắt mọi dân tộc.'),
(11900, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 24, 'OT', 'Trong những ngày ấy, Hê-xê-kia bị bệnh nặng gần chết; người cầu nguyện cùng Đức Giê-hô-va, và Đức Giê-hô-va phán với người, rồi ban cho người một dấu kỳ.'),
(11901, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 25, 'OT', 'Nhưng Hê-xê-kia không đáp ứng xứng đáng với ân phúc dành cho ông, vì lòng ông đã kiêu căng; nên cơn thịnh nộ giáng trên ông và trên Giu-đa cùng Giê-ru-sa-lem.'),
(11902, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 26, 'OT', 'Ê-xê-chia khiêm nhường trước sự kiêu ngạo trong lòng mình, cùng với các dân cư Giê-ru-sa-lem; nên cơn thịnh nộ của Đức Giê-hô-va không đổ trên họ trong những ngày của Ê-xê-chia.'),
(11903, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 27, 'OT', 'Và Ê-xê-chia có rất nhiều của cải và vinh hiển; người đã làm cho mình những kho tàng để chứa bạc, vàng, đá quí, hương liệu, khiên, và mọi thứ đồ quý báu.'),
(11904, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 28, 'OT', 'Các kho lương thực để chứa sản vật lúa mì, rượu mới và dầu ô liu; các chuồng cho mọi loại súc vật và gia súc; và các ràn cho các đàn chiên.'),
(11905, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 29, 'OT', 'Người đã xây dựng các thành phố cho ông, và ban cho ông rất nhiều súc vật, chiên và bò, vì Đức Chúa Trời đã ban cho ông của cải rất lớn.'),
(11906, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 30, 'OT', 'Chính Hê-xê-kia đã bịt nguồn nước phía trên của Ghích-ôn, và dẫn nước đó chảy thẳng xuống phía tây thành Đa-vít. Hê-xê-kia đã thành công trong mọi công việc người làm.'),
(11907, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 31, 'OT', 'Cũng vậy, khi các sứ giả của các quan trưởng Ba-by-lôn đến gặp người để hỏi về điềm lạ đã xảy ra trong đất, Đức Chúa Trời đã để người bị bỏ mặc, để thử người, hầu biết rõ mọi điều trong lòng người.'),
(11908, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 32, 'OT', 'Còn các việc khác của Ê-xê-chia và những điều nhân từ của người, nầy, đều đã chép trong sách các lời tiên kiến của Ê-sai, con trai A-mốt, đấng tiên tri, và trong sách các vua Giu-đa và Ít-ra-en.'),
(11909, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 32, 33, 'OT', 'Ê-xê-chia nằm xuống cùng với tổ tiên mình, và người ta chôn ông trong các hầm mả của con cháu Đa-vít; toàn thể Giu-đa và những người sống ở Giê-ru-sa-lem đều tỏ lòng kính trọng ông khi ông qua đời. Man-xa, con trai ông, lên ngôi kế vị ông.'),
(11910, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 33, 1, 'OT', 'Ma-na-se lên ngôi vua lúc mười hai tuổi, và trị vì năm mươi lăm năm tại Giê-ru-sa-lem.'),
(11911, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 33, 2, 'OT', 'Làm điều ác trong mắt Đức Giê-hô-va, giống như những điều đáng ghê tởm của các dân tộc mà Đức Giê-hô-va đã đuổi ra khỏi trước mặt con cái Y-sơ-ra-ên.'),
(11912, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 33, 3, 'OT', 'Vua Ma-na-xe lại xây dựng các nơi cao mà Ê-xe-ki-a, cha người, đã phá hủy; người lập các bàn thờ cho Ba-anh, làm các trụ thờ A-she-ra, thờ lạy toàn thể thiên binh trên trời và phục vụ chúng.'),
(11913, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 33, 4, 'OT', 'Người xây các bàn thờ trong đền thờ của Đức Giê-hô-va, là nơi Đức Giê-hô-va đã phán: "Danh Ta sẽ ở tại Giê-ru-sa-lem đời đời."'),
(11914, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 33, 5, 'OT', 'Và người đã xây các bàn thờ cho toàn thể đạo binh trên trời trong hai hành lang của đền thờ Đức Giê-hô-va.'),
(11915, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 33, 6, 'OT', 'Và người đã khiến các con trai mình đi ngang qua lửa trong thung lũng con trai Hinnom; người cũng bói toán, dùng phép phù chú, làm thầy phù thủy, dùng đồng cốt và thỉnh vong linh; người càng làm nhiều điều ác trước mặt Đức Giê-hô-va, khiến Ngài nổi giận.'),
(11916, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 33, 7, 'OT', 'Và người đặt tượng chạm khắc, tượng chạm mà người đã làm, trong nhà của Đức Chúa Trời, là nơi mà Đức Chúa Trời đã phán cùng Đa-vít và cùng Sa-lô-môn, con trai người rằng: "Trong đền nầy và trong Giê-ru-sa-lem, mà Ta đã chọn giữa các chi phái của Y-sơ-ra-ên, Ta sẽ đặt danh Ta ở đó đời đời."'),
(11917, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 33, 8, 'OT', 'Ta sẽ không còn dời chân của Y-sơ-ra-ên khỏi đất mà Ta đã chỉ định cho các tổ phụ các ngươi, miễn là họ cẩn thận làm theo mọi điều mà Ta đã truyền cho họ, theo trọn luật pháp, các điều lệ và các luật lệ do tay Môi-se.'),
(11918, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 33, 9, 'OT', 'Ma-na-xe khiến cho Giu-đa và những người ở Giê-ru-sa-lem đi lạc, làm điều ác hơn các dân tộc mà Đức Giê-hô-va đã tiêu diệt trước mặt con cái Ít-ra-ên.'),
(11919, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 33, 10, 'OT', 'Đức Giê-hô-va phán cùng Ma-na-xe và cùng dân sự người, nhưng họ không chịu nghe.'),
(11920, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 33, 11, 'OT', 'Đức Giê-hô-va khiến các quan trưởng đạo quân của vua A-si-ri, đến nghịch cùng chúng; chúng bắt Ma-na-xe trong các gai góc, trói người trong xiềng bằng đồng, rồi dẫn người đến Ba-by-lôn.'),
(11921, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 33, 12, 'OT', 'Khi bị khốn khổ, người ấy cầu xin Đức Giê-hô-va Đức Chúa Trời mình, và hết sức tự hạ trước mặt Đức Chúa Trời của các tổ phụ mình.'),
(11922, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 33, 13, 'OT', 'Và người cầu nguyện cùng Đức Giê-hô-va, và Đức Giê-hô-va nhậm lời người, nghe lời khẩn cầu của người, và đưa người trở lại Giê-ru-sa-lem để người trở về ngôi vua; và Mê-na-xe biết rằng Đức Giê-hô-va chính là Đức Chúa Trời.'),
(11923, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 33, 14, 'OT', 'Sau điều đó, người xây một bức tường bên ngoài thành Đa-vít, phía tây Ghíchôn, dọc theo thung lũng cho đến lối vào Cửa Cá, và vòng quanh Ô-phên, rồi xây cao lên rất nhiều; người cũng đặt các quan chỉ huy quân đội vào mọi thành có vách thành kiên cố trong xứ Giu-đa.'),
(11924, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 33, 15, 'OT', 'Ngài gỡ bỏ các thần ngoại bang và tượng hình khỏi đền thờ của Đức Giê-hô-va, cùng tất cả các bàn thờ mà người đã xây trên núi đền thờ của Đức Giê-hô-va và tại Giê-ru-sa-lem, rồi ném ra ngoài thành.'),
(11925, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 33, 16, 'OT', 'Ông lập lại bàn thờ của Đức Giê-hô-va, rồi dâng trên đó các của lễ thù ân và của lễ cầu hòa; và ông truyền cho Giu-đa phải phục sự Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en.'),
(11926, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 33, 17, 'OT', 'Dù vậy, dân chúng vẫn tiếp tục dâng tế lễ tại các nơi cao, nhưng chỉ dâng cho Đức Giê-hô-va Đức Chúa Trời của chúng.'),
(11927, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 33, 18, 'OT', 'Còn các việc khác của Ma-na-xe, lời cầu nguyện người dâng lên Đức Chúa Trời mình, và lời các nhà tiên tri nói với người nhân danh Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en, thì ghi chép trong sách các vua Ít-ra-en.'),
(11928, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 33, 19, 'OT', 'Lời cầu nguyện của ông và cách Đức Chúa Trời đáp lời ông, cùng mọi tội lỗi và sự phạm tội của ông, và các nơi mà ông đã xây các nơi cao và dựng các hình tượng A-sê-ra và các tượng chạm trước khi ông bị khuất phục: này, những điều đó được chép trong các lời của các nhà tiên kiến.'),
(11929, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 33, 20, 'OT', 'Ma-na-xe nằm ngủ cùng với tổ tiên mình, và người ta chôn cất ông trong nhà riêng của ông; rồi A-môn, con trai ông, lên ngôi kế vị ông.'),
(11930, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 33, 21, 'OT', 'A-môn hai mươi hai tuổi khi người bắt đầu trị vì, và trị vì hai năm tại Giê-ru-sa-lem.'),
(11931, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 33, 22, 'OT', 'A-môn làm điều ác trước mặt Đức Giê-hô-va, như Ma-na-xe cha mình đã làm; A-môn dâng của lễ cho mọi tượng chạm mà Ma-na-xe cha mình đã làm, và phục sự chúng.'),
(11932, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 33, 23, 'OT', 'Và người không hạ mình xuống trước mặt Đức Giê-hô-va như Man-xe, cha mình đã hạ mình; nhưng chính A-môn phạm tội càng ngày càng nhiều.'),
(11933, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 33, 24, 'OT', 'Các tôi tớ của ông lập mưu nghịch lại ông và giết ông trong nhà riêng của ông.'),
(11934, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 33, 25, 'OT', 'Dân sự trong xứ giết hết thảy những kẻ âm mưu nghịch cùng vua A-môn; và dân sự trong xứ lập Giô-xi-a, con trai vua, lên làm vua thế cho người.'),
(11935, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 1, 'OT', 'Giô-xi-a lên ngôi vua khi được tám tuổi, và ông trị vì tại Giê-ru-sa-lem ba mươi mốt năm.'),
(11936, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 2, 'OT', 'Và người làm điều ngay thẳng trong mắt Đức Giê-hô-va, đi theo các con đường của Đa-vít, cha mình, và không nghiêng sang bên phải hay bên trái.'),
(11937, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 3, 'OT', 'Ngay trong năm thứ tám đời trị vì của mình, khi ông còn là một thanh niên, thì bắt đầu tìm kiếm Đức Chúa Trời của Đa-vít, cha mình; và trong năm thứ mười hai, ông bắt đầu thanh tẩy Giu-đa và Giê-ru-sa-lem khỏi các nơi cao, các trụ thờ A-sê-ra, các tượng chạm và các tượng đúc.'),
(11938, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 4, 'OT', 'Chúng phá hủy các bàn thờ của Ba-alim trước mặt vua; các hình tượng mặt trời ở trên cao phía trên chúng thì vua chặt đổ; còn các tượng A-sê-ra, tượng chạm và tượng đúc, vua đập vỡ ra từng mảnh, nghiền thành bụi, rồi rải lên các ngôi mộ của những kẻ đã dâng sinh tế cho các hình tượng ấy.'),
(11939, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 5, 'OT', 'Ông thiêu đốt các hài cốt của những thầy tế lễ trên các bàn thờ, và làm sạch Giu-đa và Giê-ru-sa-lem.'),
(11940, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 6, 'OT', 'Trong các thành của Ma-na-xe, Ép-ra-im, Si-mê-ôn, cho đến Náp-ta-li, người phá hủy các nơi thờ thần của chúng quanh khắp các nơi ở của chúng.'),
(11941, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 7, 'OT', 'Ông phá đổ các bàn thờ, các trụ thờ A-sê-ra, các tượng chạm và tượng đúc, đập nát chúng ra thành từng mảnh, chặt bỏ mọi bàn thờ mặt trời trong khắp đất Y-sơ-ra-ên, rồi trở về Giê-ru-sa-lem.'),
(11942, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 8, 'OT', 'Vào năm thứ mười tám đời trị vì của mình, khi đã thanh tẩy xứ và đền thờ, vua sai Sáp-phan, con trai của A-xa-ly-a, và Ma-a-xe-gia, quan tổng trấn thành phố, và Giô-ách, con trai của Giô-ách-át, người ghi chép sử, đi sửa sang lại đền thờ của Đức Giê-hô-va Đức Chúa Trời ông.'),
(11943, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 9, 'OT', 'Họ đến gặp Hinh-kia, thầy tế lễ thượng phẩm, và giao cho ông số tiền đã mang vào nhà Đức Chúa Trời, tức là số tiền mà các thầy Lêvi giữ cửa đã thu được từ tay dân của Ma-na-xe, Ép-ra-im, và tất cả những người còn sót lại trong Y-sơ-ra-ên, cùng toàn thể Giu-đa, Bên-gia-min và những người ở Giê-ru-sa-lem.'),
(11944, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 10, 'OT', 'Họ trao số tiền đó vào tay những người thợ chịu trách nhiệm quản lý công việc trong đền thờ của Đức Giê-hô-va, rồi những người thợ làm việc trong đền thờ của Đức Giê-hô-va dùng số tiền đó để sửa chữa và gia cố ngôi nhà.'),
(11945, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 11, 'OT', 'Các thợ mộc và thợ xây được giao tiền để mua đá đẽo, gỗ dùng để nối kết, và dùng để lát các ngôi nhà mà các vua Giu-đa đã phá hủy.'),
(11946, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 12, 'OT', 'Các người thợ làm việc cách trung tín; những người quản lý họ là Gia-thát và Ô-ba-đia, người Lê-vi, thuộc con cháu của Mê-ra-ri; và Xa-cha-ri và Mê-thu-lam, thuộc con cháu của Kê-hát, để chỉ huy; và các người Lê-vi khác, tất cả những người hiểu biết về các nhạc khí.'),
(11947, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 13, 'OT', 'Và trên những người khiêng gánh nặng, và các giám sát viên cho mọi công việc phục vụ, mọi công việc phục vụ; và trong các người Lêvi có những người chép sách, các viên chức và các người giữ cửa.'),
(11948, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 14, 'OT', 'Khi đem số bạc mang vào nhà Đức Giê-hô-va ra, thì thầy tế lễ Hinh-kia tìm được sách luật pháp của Đức Giê-hô-va do tay Môi-se.'),
(11949, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 15, 'OT', 'Hinh-kia đáp và nói với Sáp-phan, người sao chép: "Tôi đã tìm thấy cuốn sách luật pháp trong đền thờ của Đức Giê-hô-va." Rồi Hinh-kia trao cuốn sách đó cho Sáp-phan.'),
(11950, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 16, 'OT', 'Sáp-phan mang sách đến cho vua và tâu lại vua rằng: "Tất cả những gì được giao cho các đầy tớ của ngài, họ đang làm."'),
(11951, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 17, 'OT', 'Họ đã thu thập số bạc tìm được trong đền thờ của Đức Giê-hô-va, rồi trao nó vào tay những người được chỉ định quản lý và vào tay những thợ thợ làm công việc.'),
(11952, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 18, 'OT', 'Sau đó, Xa-phan, viên thư ký, tâu cùng vua rằng: "Hinh-kia, thầy tế lễ, đã trao cho tôi một cuốn sách." Rồi Xa-phan đọc sách ấy trước mặt vua.'),
(11953, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 19, 'OT', 'Khi vua nghe những lời của luật pháp, thì xé rách quần áo mình.'),
(11954, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 20, 'OT', 'Vua truyền lệnh cho Hinh-kia, cho Ahikam con trai của Sáp-phan, cho Áp-đôn con trai của Mica, cho Sáp-phan người ký tự, và cho Asaiah, tôi tớ của vua, rằng:'),
(11955, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 21, 'OT', 'Hãy đi cầu hỏi Đức Giê-hô-va nhân danh tôi và nhân danh những người còn sót lại trong Y-sơ-ra-ên và trong Giu-đa, về lời của cuốn sách đã được tìm thấy; vì cơn thịnh nộ lớn của Đức Giê-hô-va đã đổ ra trên chúng ta, bởi vì tổ tiên chúng ta đã không giữ lời của Đức Giê-hô-va để làm theo mọi điều được chép trong cuốn sách này.'),
(11956, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 22, 'OT', 'Hinh-kia và những người mà vua đã cử đi đến cùng bà Hulđa, nữ tiên tri, vợ của Sa-lum, con trai của Tikvath, con trai của Hasra, người giữ áo lễ; bà sống tại Giê-ru-sa-lem trong khu phố thứ hai; và họ nói với bà điều đó.'),
(11957, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 23, 'OT', 'Bà nói với họ: "Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en phán như vầy: Hãy nói với người đàn ông đã sai các ông đến ta,'),
(11958, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 24, 'OT', 'Đức Giê-hô-va phán như vầy: Nầy, Ta sẽ giáng tai họa trên nơi nầy và trên những người ở đây, tức là mọi lời nguyền rủa đã chép trong sách mà người ta đã đọc trước mặt vua Giu-đa.'),
(11959, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 25, 'OT', 'Vì chúng đã từ bỏ Ta và đốt hương cho các thần khác, để chọc giận Ta bằng mọi việc tay chúng làm; nên cơn thịnh nộ của Ta sẽ trút xuống nơi này và không bị dập tắt.'),
(11960, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 26, 'OT', 'Còn về vua Giu-đa, người đã sai các ngươi đi cầu vấn Đức Giê-hô-va, thì các ngươi hãy nói với người như vầy: Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en phán như thế này về những lời mà ngươi đã nghe:'),
(11961, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 27, 'OT', 'Vì lòng ngươi mềm mại và ngươi đã tự hạ mình trước mặt Đức Chúa Trời khi nghe các lời của Ngài về nơi này và về những người ở đây, ngươi đã tự hạ mình trước mặt Ta, xé áo mình và khóc than trước mặt Ta; chính Ta cũng đã nghe ngươi, Đức Giê-hô-va phán vậy.'),
(11962, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 28, 'OT', 'Nầy, Ta sẽ khiến ngươi được về cùng các tổ phụ ngươi, và ngươi sẽ được thâu vào mồ mả mình trong sự bình an; mắt ngươi sẽ không thấy mọi điều dữ mà Ta sẽ giáng trên nơi nầy và trên những người ở đây. Vậy họ đem lời ấy thuật lại cho vua.'),
(11963, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 29, 'OT', 'Vua sai người triệu tập tất cả các trưởng lão của Giu-đa và Giê-ru-sa-lem.'),
(11964, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 30, 'OT', 'Vua lên đền thờ Đức Giê-hô-va, cùng với mọi người nam của Giu-đa, những người sống tại Giê-ru-sa-lem, các thầy tế lễ, các thầy Lê-vi, và toàn thể dân chúng, từ người lớn đến người nhỏ; rồi người đọc cho họ nghe mọi lời trong sách của giao ước mà đã được tìm thấy trong đền thờ Đức Giê-hô-va.'),
(11965, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 31, 'OT', 'Vua đứng tại chỗ của mình, lập giao ước trước mặt Đức Giê-hô-va, để bước theo Đức Giê-hô-va, giữ các điều răn, các lời chứng và các luật lệ của Ngài với trọn tấm lòng và trọn tâm hồn mình, để thực hiện những lời của giao ước đã chép trong sách này.'),
(11966, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 32, 'OT', 'Ông khiến tất cả những người hiện diện tại Giê-ru-sa-lem và Bên-gia-min phải đứng dậy; rồi những người dân cư ngụ tại Giê-ru-sa-lem lập lại giao ước với Đức Chúa Trời, là Đức Chúa Trời của tổ tiên họ.'),
(11967, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 34, 33, 'OT', 'Vua Giô-si-a dẹp bỏ mọi hình tượng đáng ghê tởm khỏi các vùng đất thuộc về con cháu Ít-ra-en, khiến tất cả những người còn sót lại trong Ít-ra-en phải phục vụ Đức Giê-hô-va, Đức Chúa Trời của họ. Trong suốt đời vua, họ không hề lìa bỏ Đức Giê-hô-va, Đức Chúa Trời của tổ tiên họ.'),
(11968, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 35, 1, 'OT', 'Vua Giô-xi-a dâng lễ Vượt Qua cho Đức Giê-hô-va tại Giê-ru-sa-lem; và họ giết con chiên Vượt Qua vào ngày mười bốn của tháng đầu.'),
(11969, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 35, 2, 'OT', 'Ông đặt các thầy tế lễ vào chức vụ của họ và khích lệ họ làm việc phục vụ trong đền thờ của Đức Giê-hô-va.'),
(11970, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 35, 3, 'OT', 'Bấy giờ người bảo các thầy Lê-vi, những người dạy dỗ cả Y-sơ-ra-ên, là những người thánh dành riêng cho Đức Giê-hô-va: "Hãy đặt hòm thánh vào trong đền thờ mà Sa-lô-môn, con trai của vua Đa-vít nước Y-sơ-ra-ên, đã xây dựng; các ngươi không cần phải khiêng nó trên vai nữa. Ngày nay, hãy phục vụ Đức Giê-hô-va Đức Chúa Trời các ngươi và dân Y-sơ-ra-ên của Ngài."'),
(11971, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 35, 4, 'OT', 'Hãy chuẩn bị theo các nhà của tổ tiên các ngươi, theo từng cấp bậc của các ngươi, theo chỉ thị của Đa-vít, vua Y-sơ-ra-ên, và theo chỉ thị của Sa-lô-môn, con trai ông.'),
(11972, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 35, 5, 'OT', 'Hãy đứng trong nơi thánh theo các ban ngành của các gia đình tổ phụ anh em mình thuộc dân chúng, và theo sự phân chia của các gia đình thầy Lê-vi.'),
(11973, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 35, 6, 'OT', 'Hãy giết chiên lễ Vượt Qua, hãy làm cho mình nên thánh và chuẩn bị cho anh em các ngươi, để họ thực hiện theo lời của Đức Giê-hô-va do tay Môi-se truyền dạy.'),
(11974, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 35, 7, 'OT', 'Vua Giô-xi-a cấp cho dân chúng, từ đoàn chiên của mình, chiên con và dê con, tất cả dùng cho các lễ Vượt Qua, cho mọi người hiện diện, với số lượng ba mươi ngàn con, và ba ngàn con bò đực: những vật này lấy từ tài sản của nhà vua.'),
(11975, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 35, 8, 'OT', 'Các quan cầm quyền của vua dâng của lễ theo lòng hảo tâm cho dân, cho các thầy tế lễ và các thầy Lê-vi. Hê-li-kia, Xa-cha-ri, và Giê-hi-ên, những người cai quản nhà Đức Chúa Trời, đã cấp cho các thầy tế lễ để dùng vào các của lễ Vượt Qua hai ngàn sáu trăm chiên con và ba trăm con bò.'),
(11976, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 35, 9, 'OT', 'Cũng như Conaniah, Semaya, Nethaneel, các anh em người, Haxabia, Jiel và Jozabad, những người chỉ huy trong các thầy Lêvi, đã cung cấp cho các thầy Lêvi năm ngàn chiên con và năm trăm con bò để dâng các của lễ Vượt Qua.'),
(11977, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 35, 10, 'OT', 'Vậy thì công việc phụng sự được chuẩn bị xong, các thầy tế lễ đứng vào vị trí của mình, và các người Lê-vi theo các ban của họ, theo như lệnh vua truyền.'),
(11978, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 35, 11, 'OT', 'Dân sự dâng lễ Vượt Qua, các thầy tế lễ lấy máu từ tay họ mà rảy ra, còn những người Lêvi thì lột da.'),
(11979, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 35, 12, 'OT', 'Họ dọn bỏ những của lễ thiêu để phân phát theo các nhóm gia đình trong dân, hầu dâng lên Đức Giê-hô-va như đã chép trong sách Môi-se. Họ cũng làm như vậy đối với các con bò.'),
(11980, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 35, 13, 'OT', 'Họ nướng lễ Vượt Qua bằng lửa như luật quy định, còn các lễ vật thánh thì nấu trong các nồi, các cái chảo và các cái chảo dẹt, rồi nhanh chóng phân phát cho toàn thể dân chúng.'),
(11981, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 35, 14, 'OT', 'Sau đó, họ chuẩn bị cho chính mình và cho các thầy tế lễ; vì các thầy tế lễ là con cháu A-ha-ron bận việc dâng của lễ toàn thiêu và mỡ cho đến tối; nên các thầy Lê-vi đã chuẩn bị cho chính mình và cho các thầy tế lễ, con cháu A-ha-ron.'),
(11982, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 35, 15, 'OT', 'Còn các thầy hát, tức con trai của A-sáp, thì ở nơi chỉ định mình theo như mạng lịnh của Đa-vít, và A-sáp, và Hi-man, và Giê-đu-thun, là các tiên kiến của vua; còn các thầy giữ cửa thì ở tại mỗi cửa; họ không được lìa khỏi công việc mình; vì anh em họ là người Lê-vi đã dọn sẵn cho họ.'),
(11983, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 35, 16, 'OT', 'Tất cả công việc phụng sự Đức Giê-hô-va được chuẩn bị xong trong ngày ấy để giữ lễ Vượt Qua, và để dâng các của lễ thiêu trên bàn thờ Đức Giê-hô-va, theo như mạng lịnh của vua Giô-si-a.'),
(11984, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 35, 17, 'OT', 'Các con trai Y-sơ-ra-ên hiện diện đã giữ lễ Vượt Qua trong thời gian đó, và giữ lễ bánh không men trong bảy ngày.'),
(11985, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 35, 18, 'OT', 'Chưa từng có lễ Vượt Qua nào giống như lễ nầy tại Y-sơ-ra-ên từ những ngày của Sa-mu-ên, đấng tiên tri; và tất cả các vua Y-sơ-ra-ên cũng không giữ lễ Vượt Qua nào giống như lễ mà Giô-xi-a giữ, cùng với các thầy tế lễ, các người Lê-vi, toàn thể Giu-đa và Y-sơ-ra-ên hiện diện, và những người ở tại Giê-ru-sa-lem.'),
(11986, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 35, 19, 'OT', 'Vào năm thứ mười tám triều vua Giô-si-a, thì lễ Vượt Qua nầy được cử hành.'),
(11987, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 35, 20, 'OT', 'Sau hết thảy những việc nầy, khi Giô-si-a đã sửa sang xong đền thờ, thì Nê-cô, vua Ê-díp-tô, đi lên để đánh giặc tại Cạt-kê-mít, gần sông Ơ-phơ-rát; và Giô-si-a ra nghênh chiến cùng người.'),
(11988, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 35, 21, 'OT', 'Ông ta sai các sứ giả đến gặp ông, nói: Ta có việc gì với ngươi, hỡi vua Giu-đa? Hôm nay ngươi không phải là đối tượng của ta, vì ta đang tiến đánh nơi ta có chiến tranh; Đức Chúa Trời đã phán cùng ta rằng phải mau lên. Hãy tránh ra khỏi Đức Chúa Trời là Đấng ở cùng ta, để ngươi không bị tiêu diệt.'),
(11989, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 35, 22, 'OT', 'Nhưng Giô-xi-a không xây khỏi mặt người, vì người đã cải trang để giao chiến với người ấy; người cũng không nghe theo các lời của Nê-cô do miệng Đức Chúa Trời, mà đến giao chiến trong thung lũng Mê-ghi-đô.'),
(11990, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 35, 23, 'OT', 'Các tay bắn cung bắn vào vua Giô-xi-a; và vua bảo các đầy tớ mình: "Hãy khiêng ta đi, vì ta bị thương rất nặng."'),
(11991, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 35, 24, 'OT', 'Các tôi tớ người đưa người khỏi cỗ xe, rồi khiêng người lên cỗ xe thứ hai mà người có, và họ mang người về Giê-ru-sa-lem. Người qua đời và được chôn trong các mồ mả của tổ tiên mình. Toàn thể Giu-đa và Giê-ru-sa-lem khóc than cho Giô-si-a.'),
(11992, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 35, 25, 'OT', 'Giê-rê-mi than khóc cho Giô-xi-a. Tất cả các quan trưởng và các nữ hát xướng đều nói về Giô-xi-a trong những bài than khóc của họ cho đến ngày nay, và họ đã lập điều đó làm luật lệ cho Y-sơ-ra-ên. Nầy, những điều đó được chép trong các bài than khóc.'),
(11993, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 35, 26, 'OT', 'Còn các việc khác của Giô-xi-a, và lòng nhân từ của người, theo như điều đã chép trong luật pháp của Đức Giê-hô-va,'),
(11994, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 35, 27, 'OT', 'Các việc đầu tiên và cuối cùng của ông, hãy xem, đều đã được chép trong sách các vua Y-sơ-ra-ên và Giu-đa.'),
(11995, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 36, 1, 'OT', 'Dân chúng trong xứ lập Giô-ha-xa, con trai của Giô-xi-a, làm vua thay cho cha mình tại Giê-ru-sa-lem.'),
(11996, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 36, 2, 'OT', 'Jo-ách-áp mới hai mươi ba tuổi khi người lên ngôi, và người trị vì tại Giê-ru-sa-lem ba tháng.'),
(11997, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 36, 3, 'OT', 'Vua nước Ai Cập bãi truất người khỏi Giê-ru-sa-lem, và phạt xứ này một trăm kikar bạc và một kikar vàng.'),
(11998, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 36, 4, 'OT', 'Vua Ai Cập đặt Ê-li-a-kim, anh người đó, làm vua trên Giu-đa và Giê-ru-sa-lem, và đổi tên người đó thành Giê-hô-i-a-kim; còn Giô-a-khát, anh người đó, thì Nê-cô bắt đi và mang đến Ai Cập.'),
(11999, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 36, 5, 'OT', 'Giô-ya-kim được hai mươi lăm tuổi khi người bắt đầu trị vì, và người trị vì mười một năm tại Giê-ru-sa-lem; người làm điều ác trước mặt Đức Giê-hô-va, Đức Chúa Trời của người.'),
(12000, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 36, 6, 'OT', 'Vua Nê-bu-cát-nết-sa, vua Ba-by-lôn, kéo lên nghịch cùng người, bắt người trong xiềng xích để đem về Ba-by-lôn.'),
(12001, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 36, 7, 'OT', 'Nê-bu-cát-nết-sa cũng mang những đồ dùng trong đền thờ của Đức Giê-hô-va về Ba-by-lôn, và đặt chúng trong đền thờ của người tại Ba-by-lôn.'),
(12002, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 36, 8, 'OT', 'Còn các việc khác của Giô-ya-kim, những điều gớm ghiếc mà người làm, và những điều tìm thấy chống lại người, thì đều đã chép trong sách các vua Y-sơ-ra-ên và Giu-đa. Giô-ya-chin, con trai người, lên ngôi kế vị người.'),
(12003, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 36, 9, 'OT', 'Giô-ha-kin lên ngôi vua khi được tám tuổi, và người trị vì tại Giê-ru-sa-lem ba tháng và mười ngày. Người làm điều ác trước mặt Đức Giê-hô-va.'),
(12004, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 36, 10, 'OT', 'Sau một năm, vua Nê-bu-cát-nết-xa sai điệu người ấy đến Ba-by-lôn, cùng với các đồ quý báu trong đền thờ Đức Giê-hô-va, và đặt Xít-ki-gia, anh người ấy, làm vua cai trị Giu-đa và Giê-ru-sa-lem.'),
(12005, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 36, 11, 'OT', 'Xít-đê-kia lên ngôi vua lúc hai mươi mốt tuổi, và người trị vì mười một năm tại Giê-ru-sa-lem.'),
(12006, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 36, 12, 'OT', 'Và người đã làm điều ác trước mặt Đức Giê-hô-va, Đức Chúa Trời của mình, không chịu hạ mình xuống trước Giê-rê-mi, đấng tiên tri, là người nói nhân danh Đức Giê-hô-va.'),
(12007, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 36, 13, 'OT', 'Và người cũng nổi loạn chống lại vua Nê-bu-cát-nết-xa, là người đã khiến người phải thề bằng Đức Chúa Trời; người cứng cổ và làm cho lòng mình ra chai cứng, không trở lại cùng Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en.'),
(12008, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 36, 14, 'OT', 'Các thầy tế lễ trưởng và toàn thể dân chúng cũng phạm tội rất nặng, bắt chước mọi điều gớm ghê của các dân tộc, và làm ô uế đền thờ Đức Giê-hô-va mà Ngài đã biệt riêng ra tại Giê-ru-sa-lem.'),
(12009, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 36, 15, 'OT', 'Đức Giê-hô-va, Đức Chúa Trời của tổ tiên họ, sai các sứ giả đến cùng họ, sai đi sớm và tiếp tục sai đến, vì Ngài thương xót dân Ngài và nơi ở của Ngài.'),
(12010, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 36, 16, 'OT', 'Họ chế nhạo các sứ giả của Đức Chúa Trời, khinh bỉ các lời Ngài, và nhạo báng các đấng tiên tri Ngài, cho đến khi cơn thịnh nộ của Đức Giê-hô-va nổi lên nghịch cùng dân Ngài, đến nỗi không còn cách chữa nào nữa.'),
(12011, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 36, 17, 'OT', 'Vì vậy, Đức Giê-hô-va khiến vua các người Canh-đê nổi lên chống lại chúng, và Người đã giết những người trẻ tuổi của chúng bằng gươm trong đền thánh của chúng; Người không thương xót trai trẻ hay gái đồng trinh, người già hay kẻ bạc đầu; tất cả đều bị trao vào tay người ấy.'),
(12012, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 36, 18, 'OT', 'Và mọi đồ dùng trong đền thờ Đức Chúa Trời, cả những đồ lớn lẫn những đồ nhỏ, cùng các kho báu trong đền thờ Đức Giê-hô-va, các kho báu của nhà vua và của các quan trưởng, tất cả những điều đó người ta đều mang đến Ba-by-lôn.'),
(12013, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 36, 19, 'OT', 'Chúng cháy đốt nhà của Đức Chúa Trời, phá đổ tường thành Giê-ru-sa-lem, thiêu hủy mọi cung điện bằng lửa, và hủy diệt mọi đồ quý giá của thành.'),
(12014, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 36, 20, 'OT', 'Phần còn sót lại thoát khỏi lưỡi gươm, người ấy đem sang Ba-by-lôn; và họ phục vụ người và các con trai người cho đến khi vương quốc Ba-tư trị vì.'),
(12015, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 36, 21, 'OT', 'Để hoàn thành lời của Đức Giê-hô-va bởi miệng Giê-rê-mi, cho đến khi đất được nghỉ những ngày sa-bát mình; suốt những năm đất hoang vu, nó đã được nghỉ sa-bát, để hoàn thành bảy mươi năm.'),
(12016, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 36, 22, 'OT', 'Vào năm đầu đời vua Ky-rơ nước Ba-tư, để ứng nghiệm lời Đức Giê-hô-va đã phán qua miệng Giê-rê-mi, Đức Giê-hô-va khiến thần linh vua Ky-rơ nước Ba-tư được thôi thúc, nên người ban lệnh truyền khắp cả vương quốc mình, và cũng viết thành văn kiện, rằng:'),
(12017, 14, 'GOI_vi', 'GOI_vi', 'vi', '2CH', 36, 23, 'OT', 'Si-ru, vua nước Ba-tư, phán rằng: Đức Giê-hô-va Đức Chúa Trời của các từng trời đã ban cho ta mọi nước trên đất, và chính Ngài đã giao cho ta trách nhiệm xây một ngôi nhà cho Ngài tại Giê-ru-sa-lem, thuộc về Giu-đa. Ai trong các ngươi là người thuộc về dân Ngài, Đức Giê-hô-va Đức Chúa Trời của người sẽ ở cùng người ấy; và người ấy hãy lên đi.'),
(12018, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 1, 1, 'OT', 'Vào năm đầu đời vua Ký-bác vua nước Ba-tư, để ứng nghiệm lời Đức Giê-hô-va phán bởi miệng Giê-rê-mi, Đức Giê-hô-va khiến thần linh vua Ký-bác vua Ba-tư được thức tỉnh, khiến người ra lệnh loan truyền khắp cả vương quốc mình, và cũng viết ra trong văn thư rằng,'),
(12019, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 1, 2, 'OT', 'Si-ru, vua nước Ba-tư, phán: Đức Giê-hô-va Đức Chúa Trời các từng trời đã ban cho tôi mọi nước trên đất, và chính Ngài đã giao cho tôi xây một ngôi nhà cho Ngài tại Giê-ru-sa-lem, thuộc về Giu-đa.'),
(12020, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 1, 3, 'OT', 'Ai trong vòng các ngươi, thuộc toàn thể dân Y-sơ-ra-ên, Đức Chúa Trời của người ở cùng người, thì hãy chỗi dậy, lên Giê-ru-sa-lem ở trong xứ Giu-đa, và xây cất đền thờ của Đức Giê-hô-va, Đức Chúa Trời của Y-sơ-ra-ên—Ngài là Đức Chúa Trời ngự tại Giê-ru-sa-lem.'),
(12021, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 1, 4, 'OT', 'Phàm những ai còn sót lại ở bất cứ nơi nào mà người ấy đang tạm trú, hãy để những người ở nơi ấy giúp đỡ người ấy bằng bạc, vàng, tài sản và súc vật, cùng với của lễ tự nguyện dâng cho nhà Đức Chúa Trời tại Giê-ru-sa-lem.'),
(12022, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 1, 5, 'OT', 'Các trưởng tộc của Giu-đa và Bên-gia-min, các thầy tế lễ và người Lê-vi đều đứng lên, cùng với tất cả những người mà Đức Chúa Trời đã khiến tâm thần họ được thức tỉnh, để lên xây cất đền thờ của Đức Giê-hô-va tại Giê-ru-sa-lem.'),
(12023, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 1, 6, 'OT', 'Và tất cả những người xung quanh họ đã giúp đỡ họ bằng cách đưa cho họ các đồ dùng bằng bạc, bằng vàng, tài sản, súc vật, và các vật quý giá, ngoài tất cả những gì họ dâng lên một cách tự nguyện.'),
(12024, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 1, 7, 'OT', 'Vua Si-ru đã đưa ra những đồ dùng của đền thờ Đức Giê-hô-va, mà Nê-bu-cát-nết-xa đã mang ra từ Giê-ru-sa-lem và đặt trong đền thờ các thần của mình.'),
(12025, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 1, 8, 'OT', 'Vua Si-ru của Ba-tư đã trao những vật đó ra tay Mít-rê-đát, viên quan coi kho, để ông này đếm và giao cho Sê-sơ-bát-xa, viên lãnh tụ của Giu-đa.'),
(12026, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 1, 9, 'OT', 'Và đây là số lượng của chúng: ba mươi cái dĩa vàng, một ngàn cái dĩa bạc, hai mươi chín cái dao.'),
(12027, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 1, 10, 'OT', 'Ba mươi cái chậu vàng, bốn trăm mười cái chậu bạc loại thứ hai, và một ngàn đồ vật khác.'),
(12028, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 1, 11, 'OT', 'Tất cả các đồ bằng vàng và bằng bạc là năm ngàn bốn trăm. Tất cả những thứ ấy, Sê-sơ-bát-xa đã mang lên, khi những người bị bắt đi làm phu thê từ Ba-by-lôn trở về Giê-ru-sa-lem.'),
(12029, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 1, 'OT', 'Những người sau đây là con cháu của tỉnh ấy, là những người trở về từ nơi lưu đày, mà trước kia vua Nê-bu-cát-nết-xa của Ba-by-lôn đã bắt đi lưu đày tại Ba-by-lôn; và họ đã trở về Giê-ru-sa-lem và Giu-đa, mỗi người về thành phố của mình.'),
(12030, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 2, 'OT', 'Những người đi cùng Xê-ru-ba-bên: Giê-sua, Nê-hê-mi, Xê-rai-ah, Rê-e-lai-ah, Mạc-đô-chai, Bích-sa-an, Mích-sa-par, Bích-vai, Rê-hum, Ba-a-nai. Số người nam của dân Y-sơ-ra-ên:'),
(12031, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 3, 'OT', 'Con cháu của Pha-rốt: hai ngàn một trăm bảy mươi hai người.'),
(12032, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 4, 'OT', 'Con cái của Sê-phát-chia, ba trăm bảy mươi hai người.'),
(12033, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 5, 'OT', 'Con cháu của A-ra, bảy trăm bảy mươi lăm người.'),
(12034, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 6, 'OT', 'Con cái của Pha-thát Mô-áp, thuộc dòng dõi Giê-su và Giô-áp, là hai ngàn tám trăm mười hai người.'),
(12035, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 7, 'OT', 'Con cái của Ê-lam: một ngàn hai trăm năm mươi bốn người.'),
(12036, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 8, 'OT', 'Con cái của Xát-tu, chín trăm bốn mươi lăm người.'),
(12037, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 9, 'OT', 'Con cháu của Xác-cai: bảy trăm sáu mươi người.'),
(12038, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 10, 'OT', 'Con cái của Ba-ni là sáu trăm bốn mươi hai người.'),
(12039, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 11, 'OT', 'Con cái của Bê-bai, sáu trăm hai mươi ba người.'),
(12040, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 12, 'OT', 'Con cháu của A-xơ-gát: một ngàn hai trăm hai mươi hai người.'),
(12041, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 13, 'OT', 'Con cái của A-đô-ni-cam, sáu trăm sáu mươi sáu người.'),
(12042, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 14, 'OT', 'Con cái của Bích-vai: hai ngàn năm mươi sáu người.'),
(12043, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 15, 'OT', 'Con cái của A-đin: bốn trăm năm mươi bốn người.'),
(12044, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 16, 'OT', 'Con cái của A-ter, thuộc dòng dõi Hê-xê-kia, chín mươi tám người.'),
(12045, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 17, 'OT', 'Con cháu của Bê-zai, ba trăm hai mươi ba người.'),
(12046, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 18, 'OT', 'Con cái của Giô-ra, một trăm mười hai người.'),
(12047, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 19, 'OT', 'Con cái của Ha-sum: hai trăm hai mươi ba người.'),
(12048, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 20, 'OT', 'Con cái của Ghi-ba, chín mươi lăm người.'),
(12049, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 21, 'OT', 'Con cái của Bết-lê-hem: một trăm hai mươi ba người.'),
(12050, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 22, 'OT', 'Người của Nê-tô-pha: năm mươi sáu người.'),
(12051, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 23, 'OT', 'Người của A-na-thốt: một trăm hai mươi tám.'),
(12052, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 24, 'OT', 'Con cái của Az-ma-vết, bốn mươi hai người.'),
(12053, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 25, 'OT', 'Con cái của Kir-yath A-rim, Khe-phi-rah và Bê-e-rot: bảy trăm bốn mươi ba người.'),
(12054, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 26, 'OT', 'Con cái của Râmah và Ghi-bê, sáu trăm hai mươi mốt người.'),
(12055, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 27, 'OT', 'Người của Mích-ma, một trăm hai mươi hai người.'),
(12056, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 28, 'OT', 'Người của Bê-thên và Ai: hai trăm hai mươi ba người.'),
(12057, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 29, 'OT', 'Con cái của Nê-bô, năm mươi hai người.'),
(12058, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 30, 'OT', 'Con cái của Mác-bích: một trăm năm mươi sáu người.'),
(12059, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 31, 'OT', 'Con cái của Ê-lam khác, một ngàn hai trăm năm mươi bốn người.'),
(12060, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 32, 'OT', 'Con cái của Ha-rim, ba trăm hai mươi người.'),
(12061, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 33, 'OT', 'Con cái của Lót, Ha-đít và Ô-nô, bảy trăm hai mươi lăm người.'),
(12062, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 34, 'OT', 'Con cái Giê-ri-cô, ba trăm bốn mươi lăm người.'),
(12063, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 35, 'OT', 'Con cái của Sê-na-a, ba ngàn sáu trăm ba mươi người.'),
(12064, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 36, 'OT', 'Các thầy tế lễ: con cháu của Y-đa-i-a, thuộc nhà Giê-sua, chín trăm bảy mươi ba người.'),
(12065, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 37, 'OT', 'Con cái của Im-mết: một ngàn năm mươi hai người.'),
(12066, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 38, 'OT', 'Con cái của Pha-sê-chu, một ngàn hai trăm bốn mươi bảy người.'),
(12067, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 39, 'OT', 'Con cháu của Ha-rim, một ngàn mười bảy người.'),
(12068, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 40, 'OT', 'Các người Lê-vi: con cháu của Giê-su và Ca-đmi-ên, thuộc con cháu của Hô-đa-vi-a, bảy mươi bốn người.'),
(12069, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 41, 'OT', 'Ca-vu-nhạc: con cháu của A-sáp, một trăm hai mươi tám người.'),
(12070, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 42, 'OT', 'Con cái các người giữ cửa: con cái của Sa-lum, con cái của A-te, con cái của Tanh-môn, con cái của A-cúp, con cái của Ha-ti-ta, con cái của Sô-bai; tất cả là một trăm ba mươi chín người.'),
(12071, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 43, 'OT', 'Các người Nê-thi-nim: con cháu của Xi-ha, con cháu của Ha-xu-pha, con cháu của Táp-ba-ốt.'),
(12072, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 44, 'OT', 'Con cái của Kê-rốt, con cái của Xi-a-ha, con cái của Pa-đôn,'),
(12073, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 45, 'OT', 'Con cái của Lê-ba-nah, con cái của Ha-ga-bah, con cái của Ác-cúc.'),
(12074, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 46, 'OT', 'Con cái của Ha-gáp, con cái của Sa-lai, con cái của Ha-nan.'),
(12075, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 47, 'OT', 'Con cháu của Ghi-đên, con cháu của Ga-ha, con cháu của Rê-a-gia.'),
(12076, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 48, 'OT', 'Con cái của Rê-xin, con cái của Nê-cô-đa, con cái của Gát-xam.'),
(12077, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 49, 'OT', 'Con cái của U-za, con cái của Pa-xê-ách, con cái của Be-xai,'),
(12078, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 50, 'OT', 'Con cháu của As-na, con cháu của Mê-hu-nim, con cháu của Nê-phu-sim.'),
(12079, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 51, 'OT', 'Con cháu của Bác-búc, con cháu của Ha-cu-pha, con cháu của Ha-hu.'),
(12080, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 52, 'OT', 'Con cái của Baz-lut, con cái của Mê-hi-da, con cái của Ha-rơ-sa.'),
(12081, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 53, 'OT', 'Con cái của Bar-cốt, con cái của Si-xe-ra, con cái của Tha-ma.'),
(12082, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 54, 'OT', 'Con cái của Nết-xi-ách, con cái của Ha-típ-ha.'),
(12083, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 55, 'OT', 'Con cái của các đầy tớ Sa-lô-môn: con cái của Sốt-ai, con cái của Sô-phê-rết, con cái của Phê-ru-đa.'),
(12084, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 56, 'OT', 'Con cái của Ja-la, con cái của Đác-kôn, con cái của Ghít-đen.'),
(12085, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 57, 'OT', 'Con cái của Sê-phát-gia, con cái của Ha-til, con cái của Phô-ke-rết Xê-bai-im, con cái của A-mi.'),
(12086, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 58, 'OT', 'Tất cả những người Nê-ti-nim và con cháu của các đầy tớ Sa-lô-môn là ba trăm chín mươi hai người.'),
(12087, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 59, 'OT', 'Và đây là những người từ Tên-mê-lách, Tên-hát-sa, Kê-ru-bốt, A-đan, và Ít-ma; họ không thể chỉ rõ được nhà tổ tiên và dòng dõi của mình, không biết họ có phải là người Y-sơ-ra-ên hay không.'),
(12088, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 60, 'OT', 'Con cái của Đê-la-iah, con cái của Tô-bi-ah, con cái của Nê-cô-đa: sáu trăm năm mươi hai người.'),
(12089, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 61, 'OT', 'Và trong con cháu thầy tế lễ: con cháu Ha-bai-a, con cháu Kô-x, con cháu Ba-rích-lai, là người đã lấy vợ là con gái của Ba-rích-lai, người Ga-la-đi, và được gọi theo tên các bà vợ ấy.'),
(12090, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 62, 'OT', 'Những người này đã tìm kiếm sách gia phả của mình để chứng minh dòng dõi, nhưng không tìm thấy; nên họ bị loại khỏi chức thầy tế lễ như những người bị ô uế.'),
(12091, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 63, 'OT', 'Người Thi-rơ-sa-tha nói với họ rằng họ không được ăn các vật thánh nhất cho đến khi có thầy tế lễ đứng lên với U-rim và Thu-mim.'),
(12092, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 64, 'OT', 'Toàn thể hội chúng cộng lại thành một là bốn mươi hai ngàn ba trăm sáu mươi người.'),
(12093, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 65, 'OT', 'Ngoài các đầy tớ và các tớ gái của họ, có bảy ngàn ba trăm ba mươi bảy người; và trong số họ có hai trăm người đàn ông và người đàn bà hát xướng.'),
(12094, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 66, 'OT', 'Ngựa của họ: bảy trăm ba mươi sáu con; lừa la của họ: hai trăm bốn mươi lăm con.'),
(12095, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 67, 'OT', 'Lạc đà của họ, bốn trăm ba mươi lăm con; lừa của họ, sáu ngàn bảy trăm hai mươi con.'),
(12096, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 68, 'OT', 'Và một số thủ lĩnh trong các gia đình họ hàng, khi họ đến đền thờ của Đức Giê-hô-va tại Giê-ru-sa-lem, đã dâng hiến tự nguyện cho đền thờ của Đức Chúa Trời, để dựng lại nơi đó trên nền tảng của nó.'),
(12097, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 69, 'OT', 'Theo khả năng của mình, họ dâng cho kho quỹ công việc này: sáu mươi một ngàn đồng đar-cơ-môn vàng, năm ngàn mi-na bạc, và một trăm áo tế lễ cho các thầy tế lễ.'),
(12098, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 2, 70, 'OT', 'Các thầy tế lễ, người Lê-vi, những người trong dân, các ca sĩ, các người giữ cửa và những người Nê-thi-nim đều ở trong các thành của mình; và toàn thể Y-sơ-ra-ên cũng ở trong các thành của họ.'),
(12099, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 3, 1, 'OT', 'Khi tháng thứ bảy đến, con cái Y-sơ-ra-ên ở trong các thành, thì toàn dân nhóm lại như một người đến Giê-ru-sa-lem.'),
(12100, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 3, 2, 'OT', 'Ông Giê-su, con trai ông Giô-xa-đắc, cùng các anh em mình là các thầy tế lễ, và ông Xê-ru-ba-bên, con trai ông Sanh-lát-i-ên, cùng các anh em mình, đứng dậy xây dựng bàn thờ của Đức Chúa Trời Y-sơ-ra-ên để dâng của lễ thiêu trên đó, như đã chép trong Luật pháp của Môi-se, người của Đức Chúa Trời.'),
(12101, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 3, 3, 'OT', 'Họ lập bàn thờ trên nền tảng của nó, vì sự sợ hãi đè nặng trên họ từ các dân trong các vùng đất ấy; và họ dâng trên bàn thờ những của lễ thiêu cho Đức Giê-hô-va, tức là những của lễ thiêu buổi sáng và buổi chiều.'),
(12102, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 3, 4, 'OT', 'Họ cũng giữ lễ các lều như đã chép, và các lễ thiêu hàng ngày theo số lượng quy định, theo luật lệ của từng ngày.'),
(12103, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 3, 5, 'OT', 'Và sau đó, của lễ thiêu luôn dâng hằng ngày, và các ngày trăng mới, và mọi kỳ lễ hội thánh dành riêng cho Đức Giê-hô-va, cùng mọi của lễ tự nguyện mà mỗi người dâng lên Đức Giê-hô-va.'),
(12104, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 3, 6, 'OT', 'Kể từ ngày đầu tiên của tháng bảy, họ bắt đầu dâng những của lễ thiêu cho Đức Giê-hô-va. Nhưng nền đền thờ của Đức Giê-hô-va chưa được đặt.'),
(12105, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 3, 7, 'OT', 'Họ đưa bạc cho các thợ đục đá và thợ mộc, cùng lương thực, đồ uống và dầu cho người Xi-đôn và người Típ, để chở gỗ bá hương từ Li-băng đến biển Gia-phô, theo sự cho phép mà Ky-rơ, vua nước Ba-tư, đã ban cho họ.'),
(12106, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 3, 8, 'OT', 'Vào năm thứ hai sau khi họ đến đền thờ Đức Chúa Trời tại Giê-ru-sa-lem, vào tháng thứ hai, Xê-ru-ba-bên con trai Sát-ên, và Giê-sua con trai Giô-xa-đắc, cùng những anh em còn lại của họ là các thầy tế lễ và người Lê-vi, và tất cả những người từ nơi đày trở về Giê-ru-sa-lem, đều bắt tay vào thực hiện công việc; họ bổ nhiệm những người Lê-vi từ hai mươi tuổi trở lên để chỉ huy công việc xây cất đền thờ Đức Giê-hô-va.'),
(12107, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 3, 9, 'OT', 'Vậy, Giê-sua cùng các con trai và anh em mình, và Kad-mi-ên cùng các con trai mình, các con trai Giu-đa, cùng nhau đứng dậy để đốc thúc những thợ làm việc trong đền thờ Đức Chúa Trời, cùng với các con trai của Ê-nát-đáp, các con trai và anh em họ, những người Lê-vi.'),
(12108, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 3, 10, 'OT', 'Khi các thợ xây đặt nền của đền thờ Đức Giê-hô-va, thì họ đặt các thầy tế lễ mặc lễ phục cầm kèn, và các người Lê-vi, con cháu của A-sáp, cầm chập chỏa để ca ngợi Đức Giê-hô-va, theo sự chỉ dẫn của Đa-vít, vua Ít-ra-en.'),
(12109, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 3, 11, 'OT', 'Họ đáp lời bằng việc ca ngợi và tạ ơn Đức Giê-hô-va, vì Ngài là thiện, vì sự nhân từ của Ngài còn mãi đời đời đối với Ít-ra-en. Và toàn thể dân chúng reo lớn tiếng reo thật lớn khi ca ngợi Đức Giê-hô-va, vì nền nhà của Đức Giê-hô-va đã được đặt xuống.'),
(12110, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 3, 12, 'OT', 'Nhưng nhiều người trong các thầy tế lễ và người Lê-vi cùng các tộc trưởng già cả, là những người đã thấy đền thờ đầu tiên, khi thấy nền của đền thờ nầy trước mặt mình, thì khóc lớn tiếng; còn nhiều người khác thì reo mừng vang dậy.'),
(12111, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 3, 13, 'OT', 'Dân chúng không phân biệt được tiếng reo mừng với tiếng khóc than của dân, vì dân chúng thét vang một tiếng lớn, và tiếng ấy vang xa.'),
(12112, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 4, 1, 'OT', 'Khi những kẻ thù của Giu-đa và Bên-gia-min nghe biết rằng con cái những người bị bắt đi làm phu tù đang xây cất đền thờ cho Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en,'),
(12113, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 4, 2, 'OT', 'Bấy giờ, họ đến cùng Xê-ru-ba-bên và các tổ trưởng, rồi nói với họ: "Chúng tôi sẽ xây cất cùng các ông, vì chúng tôi cũng thờ phượng Đức Chúa Trời của các ông như các ông vậy; và chúng tôi vẫn dâng tế lễ cho Ngài từ những ngày Ê-xa-hát-tôn, vua A-si-ri, người đã đem chúng tôi đến đây."'),
(12114, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 4, 3, 'OT', 'Bấy giờ Xê-ru-ba-bên, và Giê-su, và những người lãnh đạo khác của các họ hàng lớn ở Y-sơ-ra-ên nói với họ rằng: "Các ông không can dự gì đến việc chúng tôi xây cất đền thờ cho Đức Chúa Trời chúng tôi; nhưng chính chúng tôi sẽ cùng nhau xây cất cho Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên, y như vua Ky-rơ, vua nước Ba-tư, đã truyền cho chúng tôi."'),
(12115, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 4, 4, 'OT', 'Dân của xứ làm suy yếu tay dân sự Giu-đa, và làm họ nản lòng trong việc xây cất.'),
(12116, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 4, 5, 'OT', 'và họ thuê những người cố vấn chống lại họ để phá vỡ kế hoạch của họ, trong suốt mọi ngày đời trị vì của Si-ru, vua Ba-tư, cho đến triều đại của Đa-ri-út, vua Ba-tư.'),
(12117, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 4, 6, 'OT', 'Và trong triều đại A-ha-su-ơ, ngay từ đầu triều đại người, họ đã viết một bản cáo buộc chống lại những người ở Giu-đa và Giê-ru-sa-lem.'),
(12118, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 4, 7, 'OT', 'Vào những ngày trị vì của A-tác-xét-xe, Bích-lam, Mít-rê-đát, Ta-bê-ên và những người bạn đồng hành khác của họ đã viết thư gửi cho A-tác-xét-xe, vua Ba Tư; bức thư được viết bằng tiếng A-ram và được dịch ra tiếng A-ram.'),
(12119, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 4, 8, 'OT', 'Rê-hum, viên quan tổng trấn, và Sim-shai, người thư ký, đã viết một bức thư về Giê-ru-sa-lem gửi cho vua A-ri-ta-xét, như sau:'),
(12120, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 4, 9, 'OT', 'Bấy giờ, Rê-hum, viên quan tổng trấn, và Sim-shai, viên thư ký, cùng những người bạn đồng sự của họ, gồm những người Đin-ai, A-phạt-sát-chít, Tạt-phê-lít, A-phạt-sít, A-ki-ve, người Ba-by-lôn, người Su-san-chít, người Đê-ha-vít, và người Ê-lam,'),
(12121, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 4, 10, 'OT', 'Còn các dân tộc khác mà Át-náp-pa lớn và oai nghiêm đã bắt đi đày và đặt họ trong các thành của Sa-ma-ri, và những người khác ở bên kia sông, cùng những người ở thời điểm đó.'),
(12122, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 4, 11, 'OT', 'Đây là bản sao của bức thư mà các tôi tớ của ngài, những người đàn ông bên kia sông, đã gửi cho ngài, vua A-tác-xét-xe.'),
(12123, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 4, 12, 'OT', 'Xin hãy biết cho đức vua rằng những người Do Thái từ ngài trở về đây đã đến Giê-ru-sa-lem, xây cất thành phố phản loạn và gian ác, dựng lại các tường thành và nối các nền móng.'),
(12124, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 4, 13, 'OT', 'Xin hãy cho đức vua biết rằng nếu thành này được xây dựng lại và các bức tường được hoàn tất, thì từ đó thuế khóa, lệ phí và các khoản nộp sẽ không được nộp, và như vậy sẽ làm tổn hại đến lợi tức của các vua.'),
(12125, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 4, 14, 'OT', 'Vì chúng tôi nhận bổng lộc từ cung điện, nên không thể nào để chúng tôi chứng kiến sự sỉ nhục của nhà vua; vì lý do này, chúng tôi xin gửi thư thông báo cho nhà vua.'),
(12126, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 4, 15, 'OT', 'Hãy tra cứu trong sách sử ký của tổ tiên ngươi, và sẽ tìm thấy trong sách sử ký, biết rằng thành này là thành phản loạn, gây hại cho các vua và các tỉnh, và đã nổi loạn từ xưa; vì cớ đó, thành này đã bị hủy diệt.'),
(12127, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 4, 16, 'OT', 'Chúng tôi xin tấu trình với vua biết rằng nếu thành này được xây dựng lại và các tường thành được hoàn tất, thì từ phía bên kia sông, vua sẽ không còn phần nào cả.'),
(12128, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 4, 17, 'OT', 'Vua sai chiếu chỉ cho Rê-hum, viên quan tổng trấn, và Sim-sai, viên thư ký, cùng các đồng sự của các ông ấy đang cư ngụ tại Sa-ma-ri và những người khác ở bên kia sông: Chúc bình an, và mọi việc tốt lành.'),
(12129, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 4, 18, 'OT', 'Thư các ngươi gửi cho chúng ta đã được đọc rõ ràng trước mặt ta.'),
(12130, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 4, 19, 'OT', 'Ta đã ra lệnh điều tra, và người ta đã tìm thấy rằng thành này từ xưa vẫn chống nghịch các vua, và sự nổi loạn cùng phản loạn đã xảy ra trong đó.'),
(12131, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 4, 20, 'OT', 'Các vua hùng mạnh đã trị vì tại Giê-ru-sa-lem, và họ cai trị khắp mọi miền bên kia sông; và thuế khóa, lệ phí, và các khoản nộp đều được nộp cho họ.'),
(12132, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 4, 21, 'OT', 'Hãy ban hành lệnh đình chỉ những người này, và thành phố này không được xây dựng cho đến khi có lệnh khác từ ta.'),
(12133, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 4, 22, 'OT', 'Hãy coi chừng, chớ đừng để điều này xảy ra; tại sao lại để cho tai họa gia tăng, gây tổn hại đến các vua?'),
(12134, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 4, 23, 'OT', 'Vừa khi bản chiếu chỉ của vua A-tác-xét-xe được đọc trước mặt Rê-hum, Sim-sai là viên thư ký, và những đồng bạn của họ, thì họ vội vã lên Giê-ru-sa-lem gặp người Do Thái và dùng quyền lực cùng sức mạnh bắt họ phải ngưng lại.'),
(12135, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 4, 24, 'OT', 'Bấy giờ công việc xây cất nhà của Đức Chúa Trời tại Giê-ru-sa-lem ngừng lại, và nó bị đình chỉ cho đến năm thứ hai đời trị vì của Đa-ri-út, vua Ba-tư.'),
(12136, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 5, 1, 'OT', 'Bấy giờ, các nhà tiên tri Hách-gai và Xa-cha-ri, con trai của Ích-đô, đã nói tiên tri cho những người Do-thái ở trong Giu-đa và Giê-ru-sa-lem, nhân danh Đức Chúa Trời của Y-sơ-ra-ên mà nói với họ.'),
(12137, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 5, 2, 'OT', 'Bấy giờ Xê-ru-ba-bên, con trai Sát-ên, và Giê-sua, con trai Giô-xa-đắc, đứng dậy xây cất đền thờ Đức Chúa Trời tại Giê-ru-sa-lem; và các đấng tiên tri của Đức Chúa Trời giúp đỡ họ.'),
(12138, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 5, 3, 'OT', 'Cùng lúc ấy, Tát-nai, quan tổng trấn bên kia sông, và Sê-ta-bót-xai cùng các đồng sự của họ đến gặp họ và hỏi: "Ai đã ra lệnh cho các ông xây cất ngôi nhà này và xây tường thành này?"'),
(12139, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 5, 4, 'OT', 'Bấy giờ chúng tôi nói với họ như sau: "Tên những người đàn ông đang xây công trình này là gì?"'),
(12140, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 5, 5, 'OT', 'Nhưng mắt của Đức Chúa Trời họ ở trên các trưởng lão người Giu-đa, khiến người ta không thể bắt họ ngưng lại, cho đến khi việc này được trình cho Đa-ri-út; rồi họ mới trả lời về việc này bằng một bức thư.'),
(12141, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 5, 6, 'OT', 'Bản sao bức thư mà Tát-nai, tổng trấn vùng bên kia sông, và Sê-ta-bô-xnai cùng các đồng sự của ông là những người A-phác-sa-chai sống bên kia sông, đã gửi cho vua Đa-ri-út:'),
(12142, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 5, 7, 'OT', 'Họ gửi một thông điệp đến cùng ngài, và trong đó có viết như sau: "Kính gửi vua Đa-ri-út, xin ngài bình an trọn vẹn."'),
(12143, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 5, 8, 'OT', 'Xin cho nhà vua biết rằng chúng tôi đã đi đến tỉnh Giu-đê, đến đền thờ Đức Chúa Trời lớn, đang được xây bằng những tảng đá lớn, và các xà gỗ được đặt vào trong các vách tường; công việc này đang được thực hiện nhanh chóng và thịnh vượng trong tay họ.'),
(12144, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 5, 9, 'OT', 'Bấy giờ, chúng tôi hỏi những người già cả ấy và nói với họ như vầy: "Ai đã ra lệnh cho các ông xây cất ngôi nhà này và xây tường bao quanh?"'),
(12145, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 5, 10, 'OT', 'Chúng tôi cũng đã hỏi tên của họ, để báo cho ngài biết, hầu ghi lại tên những người đàn ông làm lãnh tụ của họ.'),
(12146, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 5, 11, 'OT', 'Chúng tôi trả lời như sau: Chúng tôi là các đầy tớ của Đức Chúa Trời trên trời và đất, và đang xây cất đền thờ mà đã được xây dựng cách đây nhiều năm, do một vị vua lớn của Y-sơ-ra-ên xây và thiết lập.'),
(12147, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 5, 12, 'OT', 'Vì tổ tiên chúng tôi đã làm cho Đức Chúa Trời trên trời nổi giận, nên Ngài đã trao họ vào tay Nê-bu-cát-nết-xa, vua Ba-by-lôn, người Can-đê, và ông ấy đã phá hủy ngôi nhà này, còn dân sự thì bắt đi đày sang Ba-by-lôn.'),
(12148, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 5, 13, 'OT', 'Nhưng trong năm đầu đời vua Ký-ớp, vua Ba-by-lôn, thì vua Ký-ớp ra sắc lệnh xây cất đền thờ Đức Chúa Trời nầy.'),
(12149, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 5, 14, 'OT', 'Và các đồ đựng bằng vàng và bạc của nhà Đức Chúa Trời, mà Nê-bu-cát-nết-sa đã lấy ra từ đền thờ ở Giê-ru-sa-lem và mang đến đền thờ Ba-by-lôn, thì vua Cơ-rơ-sơ đã lấy những đồ đó ra khỏi đền thờ Ba-by-lôn và trao cho người tên là Sê-sơ-bát-xa, mà vua đã đặt làm tổng trấn.'),
(12150, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 5, 15, 'OT', 'Và bảo người ấy: "Hãy mang những đồ vật này đi, đem vào đền thờ tại Giê-ru-sa-lem, và ngôi nhà của Đức Chúa Trời sẽ được xây cất lại trên nền cũ của nó."'),
(12151, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 5, 16, 'OT', 'Bấy giờ, Sê-sơ-bát-xa, quan tổng trấn của ngài, đã đến và đặt nền móng cho ngôi nhà của Đức Chúa Trời tại Giê-ru-sa-lem; và từ lúc ấy cho đến nay, công trình được xây dựng nhưng vẫn chưa hoàn tất.'),
(12152, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 5, 17, 'OT', 'Vậy bây giờ, nếu thấy tốt trước mặt vua, hãy tìm kiếm trong kho tàng của vua, nơi ở Ba-by-lôn, xem có thật là một sắc lệnh đã được vua Cơ-rơ ban ra để xây cất đền thờ Đức Chúa Trời nầy tại Giê-ru-sa-lem chăng, và xin vua hãy gửi quyết định của vua về cho chúng tôi liên quan đến việc nầy.'),
(12153, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 6, 1, 'OT', 'Bấy giờ, vua Đa-ri-út ra lệnh, và người ta đã tìm kiếm trong nhà kho lưu trữ các bản văn, nơi cất giữ các kho báu tại Ba-by-lôn.'),
(12154, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 6, 2, 'OT', 'Và người ta đã tìm thấy tại Ách-mê-tha, trong cung điện ở tỉnh Mi-đi, một cuộn sách, và trong đó có ghi một bản ghi chép như thế này:'),
(12155, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 6, 3, 'OT', 'Trong năm đầu đời vua Cơ-rê-sơ, vua Cơ-rê-sơ ra lệnh về đền thờ Đức Chúa Trời tại Giê-ru-sa-lem: "Ngôi đền phải được xây lại, tại nơi dân chúng dâng lễ thiêu, và nền móng phải được đặt vững chắc; chiều cao là sáu mươi thước, chiều rộng là sáu mươi thước."'),
(12156, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 6, 4, 'OT', 'Ba hàng đá lớn và một hàng gỗ mới; và các chi phí hãy cấp ra từ nhà vua.'),
(12157, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 6, 5, 'OT', 'Vả lại, các đồ đựng bằng vàng và bằng bạc của nhà Đức Chúa Trời, mà Nê-bu-cát-nết-xa đã lấy ra từ đền thờ tại Giê-ru-sa-lem và mang đến Ba-by-lôn, thì phải hoàn trả lại và đặt chúng trong đền thờ tại Giê-ru-sa-lem, mỗi món về chỗ nó, và đặt chúng trong nhà Đức Chúa Trời.'),
(12158, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 6, 6, 'OT', 'Bây giờ, hỡi Tát-nai, tổng trấn bên kia sông, và Sê-ta-bô-xnai cùng các bạn hữu của các ngươi, những người A-phác-sa-chai ở bên kia sông, hãy tránh xa nơi đó:'),
(12159, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 6, 7, 'OT', 'Hãy để công việc của đền thờ Đức Chúa Trời các ngươi được tự do; viên tổng trấn xứ Giu-đa và các trưởng lão của Giu-đa hãy xây cất đền thờ Đức Chúa Trời của các ngươi tại nơi cũ của nó.'),
(12160, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 6, 8, 'OT', 'Ta cũng ra sắc lệnh về điều các ngươi phải làm cho các bậc trưởng lão của dân Giu-đa này trong việc xây cất nhà của Đức Chúa Trời: từ tài sản của nhà vua, tức là các khoản cống nộp từ vùng bên kia sông, phải cấp phát ngay các khoản chi phí cho những người đàn ông này, để công việc không bị đình trệ.'),
(12161, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 6, 9, 'OT', 'Và những gì họ cần, gồm các con bò đực nhỏ, các con cừu đực và chiên con dùng cho các của lễ thiêu dâng cho Đức Chúa Trời trên trời, cùng với lúa mì, muối, rượu và dầu, theo như sự chỉ định của các thầy tế lễ ở Giê-ru-sa-lem, hãy cấp cho họ hằng ngày, không được thiếu sót:'),
(12162, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 6, 10, 'OT', 'để họ dâng những lễ vật thơm tho cho Đức Chúa Trời trên trời, và cầu nguyện cho đời sống của vua và các con trai người.'),
(12163, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 6, 11, 'OT', 'Tôi cũng đã ban lệnh: bất kỳ ai thay đổi lời này, thì phải lấy gỗ từ nhà người ấy mà dựng lên, rồi treo người ấy lên đó; và nhà người ấy phải bị biến thành nơi chất rác vì điều này.'),
(12164, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 6, 12, 'OT', 'Đức Chúa Trời, Đấng đã khiến danh Ngài ngự tại nơi đó, nguyện Ngài tiêu diệt mọi vua chúa và dân tộc nào ra tay thay đổi hay phá hủy ngôi nhà Đức Chúa Trời tại Giê-ru-sa-lem. Ta là Đa-ri-út, đã ban sắc lệnh này; hãy thi hành cách nhanh chóng.'),
(12165, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 6, 13, 'OT', 'Bấy giờ, Tát-nai, tổng trấn bên kia sông, Sê-ta-bót-xai và các bạn hữu của họ, theo như điều vua Đa-ri-út đã sai, lập tức thi hành.'),
(12166, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 6, 14, 'OT', 'Các trưởng lão của người Giu-đa xây cất và làm việc thạnh vượng nhờ lời tiên tri của Hê-gai, nhà tiên tri, và Xa-cha-ri, con trai của Ít-đô; họ xây cất và hoàn thành theo chỉ thị của Đức Chúa Trời của Ít-ra-en, và theo chỉ thị của Si-ru, Đa-ri-út, và A-tác-xét-xe, vua Ba-tư.'),
(12167, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 6, 15, 'OT', 'Và ngôi nhà này được hoàn tất vào ngày mùng ba tháng A-đa, là năm thứ sáu triều vua Đa-ri-út vua.'),
(12168, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 6, 16, 'OT', 'Các con trai của Y-sơ-ra-ên, các thầy tế lễ, các người Lê-vi và phần còn lại của các con trai những kẻ bị bắt đi lưu đày đã giữ lễ khánh thành ngôi nhà của Đức Chúa Trời nầy cách vui mừng.'),
(12169, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 6, 17, 'OT', 'Và nhân dịp khánh thành ngôi nhà Đức Chúa Trời nầy, họ dâng một trăm con bò đực, hai trăm con chiên đực, bốn trăm con chiên con; và làm của lễ chuộc tội cho toàn thể Y-sơ-ra-ên, mười hai con dê đực, theo số lượng các chi phái Y-sơ-ra-ên.'),
(12170, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 6, 18, 'OT', 'Họ đặt các thầy tế lễ theo nhóm của mình và các người Lê-vi theo ban ngành của họ để lo việc Đức Chúa Trời tại Giê-ru-sa-lem, như đã chép trong sách Môi-se.'),
(12171, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 6, 19, 'OT', 'Các con trai của những người bị đày làm lễ Vượt Qua vào ngày mười bốn tháng giêng.'),
(12172, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 6, 20, 'OT', 'Các thầy tế lễ và các thầy Lê-vi đã làm lễ tẩy sạch, tất cả đều được sạch, rồi họ giết lễ Vượt Qua cho toàn thể con cái những người bị bắt đi lưu đày, cho anh em mình là các thầy tế lễ, và cho chính mình họ.'),
(12173, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 6, 21, 'OT', 'Các con trai của Y-sơ-ra-ên, là những người trở về từ nơi đày ải, và tất cả những ai tách ra khỏi sự ô uế của các dân trong xứ để tìm kiếm Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên, thì ăn.'),
(12174, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 6, 22, 'OT', 'Và họ giữ lễ bánh không men trong bảy ngày, đầy niềm vui mừng; vì Đức Giê-hô-va đã làm cho họ vui mừng, và đã khiến lòng vua A-ssy-ri nghiêng về phía họ, để thêm sức cho họ trong công việc nhà Đức Chúa Trời, là Đức Chúa Trời của Y-sơ-ra-ên.'),
(12175, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 7, 1, 'OT', 'Sau các việc nầy, trong triều đại của A-tác-xét-xe, vua nước Ba-tư, Ê-xơ-ra, con trai của Xê-rai-a, con trai của A-xa-ria, con trai của Hinh-kia,'),
(12176, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 7, 2, 'OT', 'con trai của Sa-lum, con trai của Xa-đốc, con trai của A-hi-túp,'),
(12177, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 7, 3, 'OT', 'con trai của A-ma-ri, con trai của A-xa-ri, con trai của Mê-ra-i-ốt,'),
(12178, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 7, 4, 'OT', 'con trai của Xe-ra-hia, con trai của Út-xi, con trai của Bu-ki,'),
(12179, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 7, 5, 'OT', 'con trai của A-bi-xu, con trai của Phi-nê-xê, con trai của Ê-lê-a-xa, con trai của A-rôn thầy tế lễ cả:'),
(12180, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 7, 6, 'OT', 'Ê-xơ-ra lên từ Ba-by-lôn; người là một thầy thông luật tinh thông luật pháp của Môi-se, mà Đức Giê-hô-va Đức Chúa Trời của Ít-ra-en đã ban cho. Vua ban cho người mọi điều người xin, theo như tay Đức Giê-hô-va Đức Chúa Trời người trên người.'),
(12181, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 7, 7, 'OT', 'Một số người trong con cháu Y-sơ-ra-ên, các thầy tế lễ, người Lê-vi, những người ca hát, những người giữ cửa và những người Nê-thi-nim lên Giê-ru-sa-lem trong năm thứ bảy đời vua Ạt-ta-xét-xe.'),
(12182, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 7, 8, 'OT', 'Người đến Giê-ru-sa-lem trong tháng năm, là năm thứ bảy đời vua.'),
(12183, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 7, 9, 'OT', 'Vì vào ngày mùng một tháng đầu tiên, người ấy bắt đầu lên đường từ Ba-by-lôn; và vào ngày mùng một tháng năm, người ấy đến Giê-ru-sa-lem, theo tay tốt lành của Đức Chúa Trời mình trên người ấy.'),
(12184, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 7, 10, 'OT', 'Vì Ê-xơ-ra đã định tâm nghiên cứu luật của Đức Giê-hô-va, thực hành và dạy cho dân Ít-ra-en các điều lệ và án lệ.'),
(12185, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 7, 11, 'OT', 'Đây là bản sao bức thư mà vua A-tác-xét-xe đã trao cho thầy tế lễ Ê-xơ-ra, người đánh chữ, chuyên chép lời các điều răn và luật lệ của Đức Giê-hô-va cho dân Y-sơ-ra-ên.'),
(12186, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 7, 12, 'OT', 'A-tác-xét-xe, vua các vua, gửi cho Ê-xơ-ra thầy tế lễ, người thông hiểu luật pháp của Đức Chúa Trời trên trời, đầy đủ sự hoàn hảo và đúng thời điểm.'),
(12187, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 7, 13, 'OT', 'Ta ra lệnh rằng bất cứ ai trong dân Y-sơ-ra-ên, các thầy tế lễ và người Lê-vi thuộc vương quốc ta, hễ ai tự nguyện lên Giê-ru-sa-lem, đều phải đi với ngươi.'),
(12188, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 7, 14, 'OT', 'Bởi ngươi được vua và bảy vị cố vấn của ngài sai đi để điều tra về Giu-đa và Giê-ru-sa-lem, theo luật pháp của Đức Chúa Trời ngươi mà ngươi đang cầm trong tay;'),
(12189, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 7, 15, 'OT', 'và để mang bạc và vàng, mà vua và các cố vấn của ông đã dâng lên cách tự nguyện cho Đức Chúa Trời của Y-sơ-ra-ên, Đấng ngự tại Giê-ru-sa-lem.'),
(12190, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 7, 16, 'OT', 'Và tất cả bạc và vàng mà ngươi có thể tìm được trong toàn cõi tỉnh Ba-by-lôn, cùng với của lễ lạc ý của dân và các thầy tế lễ dâng tự nguyện cho đền thờ Đức Chúa Trời của họ tại Giê-ru-sa-lem:'),
(12191, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 7, 17, 'OT', 'Hãy dùng số tiền này mà lập tức mua bò đực, chiên đực, chiên con, cùng các lễ vật đi kèm và lễ đồ uống của chúng, rồi dâng những của lễ ấy trên bàn thờ của nhà Đức Chúa Trời các ngươi tại Giê-ru-sa-lem.'),
(12192, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 7, 18, 'OT', 'Và điều gì mà ngươi và anh em ngươi xét là tốt, hãy dùng phần bạc và vàng còn lại mà làm, theo như ý Đức Chúa Trời của các ngươi.'),
(12193, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 7, 19, 'OT', 'Các đồ dùng mà đã ban cho ngươi để phục vụ trong nhà Đức Chúa Trời ngươi, hãy trao đầy đủ trước mặt Đức Chúa Trời ở Giê-ru-sa-lem.'),
(12194, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 7, 20, 'OT', 'Và bất cứ điều gì còn thiếu sót cho đền thờ của Đức Chúa Trời ngươi, mà ngươi cần phải cấp phát, thì hãy cấp phát từ kho tàng của vua.'),
(12195, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 7, 21, 'OT', 'Ta, chính ta, vua A-tác-xét-xe, ra sắc lệnh cho tất cả các viên chức quản lý kho bạc ở bên kia sông: bất cứ điều gì thầy tế lễ Ê-xơ-ra, người thầy dạy luật pháp của Đức Chúa Trời trên trời, yêu cầu các ngươi, phải được thực hiện cách mau lẹ,'),
(12196, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 7, 22, 'OT', 'Cho đến một trăm kikar bạc, và một trăm kôr lúa mì, và một trăm bát rượu, và một trăm bát dầu, và muối thì không hạn chế số lượng.'),
(12197, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 7, 23, 'OT', 'Mọi điều nào theo lệnh của Đức Chúa Trời trên trời, đều phải được thực hiện cách tận tụy cho đền thờ của Đức Chúa Trời trên trời, hầu cho cơn thịnh nộ không đổ xuống trên vương quốc của nhà vua và các con trai người.'),
(12198, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 7, 24, 'OT', 'Cũng xin cho các ngươi biết rằng mọi thầy tế lễ, thầy Lê-vi, người hát, kẻ canh giữ, người phục vụ, và những kẻ làm việc tại đền thờ Đức Chúa Trời nầy, thì không được phép bắt họ đóng thuế, lệ phí, hay sưu dịch.'),
(12199, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 7, 25, 'OT', 'Và ngươi, Ê-xơ-ra, hãy theo sự khôn ngoan của Đức Chúa Trời ngươi, là điều ngươi đang có trong tay, mà bổ nhiệm các quan xét và quan án để xét xử toàn thể dân chúng ở bên kia sông, tức tất cả những người biết luật pháp của Đức Chúa Trời ngươi; còn những người không biết, thì hãy dạy họ.'),
(12200, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 7, 26, 'OT', 'Bất cứ ai không vâng theo luật pháp của Đức Chúa Trời ngươi và luật pháp của nhà vua, thì phải thi hành án phạt nghiêm khắc đối với người ấy, hoặc là xử tử, hoặc là trục xuất, hoặc là tịch thu tài sản, hoặc là bỏ tù.'),
(12201, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 7, 27, 'OT', 'Đáng ngợi khen thay Đức Giê-hô-va, Đức Chúa Trời của tổ tiên chúng tôi, Đấng đã đặt điều nầy trong lòng vua để làm rực rỡ đền thờ của Đức Giê-hô-va tại Giê-ru-sa-lem.'),
(12202, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 7, 28, 'OT', 'Và Ngài đã tỏ lòng nhân từ đối với tôi trước mặt vua, các cố vấn của vua và tất cả các quan chức hùng mạnh của vua. Tôi đã được thêm sức mạnh nhờ tay Đức Giê-hô-va Đức Chúa Trời tôi đặt trên tôi, và tôi đã tập hợp những người lãnh đạo từ Y-sơ-ra-ên để cùng tôi lên đường.'),
(12203, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 1, 'OT', 'Đây là các trưởng tộc và gia phả của những người lên cùng tôi từ Ba-by-lôn, trong triều đại vua A-tác-xét-xe.'),
(12204, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 2, 'OT', 'Từ con cháu của Phi-nê-xết, Ghẹt-sôm; từ con cháu của Ít-ha-ma, Đa-ni-ên; từ con cháu của Đa-vít, Ha-tút.'),
(12205, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 3, 'OT', 'Thuộc các con trai của Sê-can-ya, thuộc các con trai của Pha-rốt; Xa-cha-ri; và cùng người được ghi theo gia phổ là một trăm năm mươi nam giới.'),
(12206, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 4, 'OT', 'Thuộc về con cháu của Pha-thát Mô-áp: Ê-li-hô-ênai, con trai của Xe-rai-gia, và cùng người có hai trăm nam giới.'),
(12207, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 5, 'OT', 'Từ con cháu của Sê-can-ya, con trai của Gia-ha-xi-ên, và cùng người có ba trăm nam giới.'),
(12208, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 6, 'OT', 'Và trong con cháu của A-đin, Ê-bết, con trai của Giô-na-than, cùng với ông có năm mươi người nam.'),
(12209, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 7, 'OT', 'Và từ con cháu Ê-lam, có Ê-sai-a con trai của A-tha-lya, và cùng ông có bảy mươi người nam.'),
(12210, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 8, 'OT', 'Và trong các con trai của Sê-phát-gia, có Xê-ba-đia con trai của Mi-chên, và cùng người có tám mươi người nam.'),
(12211, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 9, 'OT', 'Thuộc con cháu của Giô-áp, có Ô-ba-đia, con trai của Giê-hi-ên, cùng với hai trăm mười tám người nam.'),
(12212, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 10, 'OT', 'Và từ con trai của Sê-lô-mít, là con trai của Giô-xi-phi-a, và cùng người có một trăm sáu mươi người nam.'),
(12213, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 11, 'OT', 'Và trong con cháu của Bê-bai, có Xa-cha-ri, con trai của Bê-bai, và cùng người có hai mươi tám nam giới.'),
(12214, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 12, 'OT', 'Và trong con cháu của A-xơ-gát, có Giô-ha-nan, con trai của Ha-cát-tan, cùng với ông là một trăm mười người nam.'),
(12215, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 13, 'OT', 'Và từ con cháu của A-đô-ni-cam, những người đến sau, tên của họ là Ê-li-phê-lết, Giê-i-ên và Sê-ma-gia, cùng với họ có sáu mươi người nam.'),
(12216, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 14, 'OT', 'Từ con cháu của Bích-vai, có Út-ai, Xáp-bút, và cùng họ có bảy mươi người nam.'),
(12217, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 15, 'OT', 'Tôi đã triệu tập họ bên cạnh con sông chảy về A-ha-va, và chúng tôi cư ngụ tại đó ba ngày. Tôi đã kiểm tra dân sự và các thầy tế lễ, nhưng không tìm thấy ở đó một người nào thuộc con cháu Lê-vi.'),
(12218, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 16, 'OT', 'Tôi đã sai đi Ê-li-ê-xe, A-ri-ên, Sê-ma-gia, Ê-lna-than, Gia-rib, Ê-lna-than, Na-than, Xa-cha-ri, và Mê-thu-lam, những người làm đầu; và cho Giô-ia-rib và Ê-lna-than, những người hiểu biết.'),
(12219, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 17, 'OT', 'Tôi đã sai họ đến Ích-đô, người lãnh đạo tại nơi Ca-xíp-hia, và tôi dặn họ những lời phải nói với Ích-đô và các anh em người, những người Nê-thi-nim ở nơi Ca-xíp-hia, để họ mang đến cho chúng tôi những người hầu việc cho đền thờ Đức Chúa Trời của chúng ta.'),
(12220, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 18, 'OT', 'Chúng tôi được một người khôn ngoan, thuộc con cháu của Mách-li, con của Lê-vi, con của Ít-ra-en, do tay tốt lành của Đức Chúa Trời chúng tôi dẫn đến; và Sê-rê-bia cùng các con trai và anh em người, tất cả mười tám người.'),
(12221, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 19, 'OT', 'Và Ha-sa-bia, cùng với người là Ye-sa-gia, thuộc con cháu của Mê-ra-ri, anh em ông ấy và các con trai của họ, hai mươi người.'),
(12222, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 20, 'OT', 'Cũng từ các Nê-ti-nim, mà Đa-vít và các quan trưởng đã chỉ định để phục vụ người Lê-vi, có hai trăm hai mươi người Nê-ti-nim; tất cả đều được ghi rõ tên.'),
(12223, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 21, 'OT', 'Tôi đã tuyên bố một sự kiêng ăn tại sông A-ha-va, để chúng tôi tự hạ mình trước Đức Chúa Trời của chúng tôi, và cầu xin Ngài chỉ cho chúng tôi con đường ngay thẳng cho chúng tôi, cho con cái nhỏ bé của chúng tôi, và cho mọi tài sản chúng tôi.'),
(12224, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 22, 'OT', 'Vì tôi cảm thấy hổ thẹn khi xin vua một toán quân và kỵ binh để giúp chúng tôi chống lại kẻ thù dọc đường, vì chúng tôi đã nói với vua rằng: "Tay Đức Chúa Trời chúng tôi phù hộ cho mọi người tìm kiếm Ngài để làm điều thiện; nhưng quyền năng và cơn thịnh nộ của Ngài chống lại mọi kẻ từ bỏ Ngài."'),
(12225, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 23, 'OT', 'Chúng tôi nhịn ăn và cầu xin Đức Chúa Trời chúng tôi về điều này, và Ngài đã nhậm lời chúng tôi.'),
(12226, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 24, 'OT', 'Tôi đã biệt riêng mười hai người trong các thầy tế lễ làm lãnh đạo, gồm Sê-rê-bia, Ha-sa-bia, và mười người anh em của họ cùng đi với họ.'),
(12227, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 25, 'OT', 'Và tôi cân cho họ bạc, vàng và các đồ dùng, tức phần dâng cho đền thờ Đức Chúa Trời chúng ta, mà vua, các cố vấn và các quan chức của ông, cùng toàn thể dân Y-sơ-ra-ên còn sống sót, đã dâng lên.'),
(12228, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 26, 'OT', 'Tôi đã cân trao vào tay họ sáu trăm năm mươi kiếc bạc, các đồ bằng bạc một trăm kiếc, và vàng một trăm kiếc.'),
(12229, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 27, 'OT', 'Hai mươi cái chậu vàng, mỗi cái nặng một ngàn đaríc; và hai đồ bằng đồng mạ vàng tốt, quý báu như vàng.'),
(12230, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 28, 'OT', 'Tôi nói với họ: "Các ngươi là thánh dành riêng cho Đức Giê-hô-va, các đồ dùng cũng là thánh; còn bạc và vàng thì là của lễ tự nguyện dâng cho Đức Giê-hô-va Đức Chúa Trời của tổ tiên các ngươi."'),
(12231, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 29, 'OT', 'Hãy lo lắng chăm chỉ và giữ gìn cho đến khi các ngươi cân chúng trước mặt các thầy tế lễ, người Lê-vi và các tộc trưởng của Y-sơ-ra-ên tại Giê-ru-sa-lem, trong các phòng của nhà Đức Giê-hô-va.'),
(12232, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 30, 'OT', 'Các thầy tế lễ và các người Lê-vi nhận số cân bạc, vàng và các đồ dùng để mang đến Giê-ru-sa-lem, vào đền thờ Đức Chúa Trời của chúng ta.'),
(12233, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 31, 'OT', 'Chúng tôi rời khỏi sông A-ha-va vào ngày mười hai của tháng đầu tiên, để đi về Giê-ru-sa-lem; tay Đức Chúa Trời chúng tôi phù hộ chúng tôi, và Ngài giải cứu chúng tôi khỏi tay kẻ thù và những kẻ rình rập dọc đường.'),
(12234, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 32, 'OT', 'Chúng tôi đến Giê-ru-sa-lem và ở đó ba ngày.'),
(12235, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 33, 'OT', 'Vào ngày thứ tư, bạc, vàng và các đồ vật được cân trong nhà Đức Chúa Trời của chúng ta, do tay Mê-rê-mốt, con trai Ú-ri, thầy tế lễ; cùng với ông là Ê-lê-a-xơ, con trai Phi-nê-ha; và cùng các ông ấy là Giô-xáp, con trai Giê-su, và Nô-a-đia, con trai Bin-nui, những người Lê-vi.'),
(12236, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 34, 'OT', 'Theo số lượng và theo trọng lượng của từng người; và toàn bộ trọng lượng đã được chép lại vào lúc ấy.'),
(12237, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 35, 'OT', 'Những người từ nơi lưu đày trở về, con cháu của hội chúng lưu đày, dâng các lễ thiêu cho Đức Chúa Trời của Ít-ra-en: mười hai con bò tơ cho toàn thể Ít-ra-en, chín mươi sáu con chiên đực, bảy mươi bảy con chiên con, và mười hai con dê đực làm lễ chuộc tội; tất cả đều là của lễ thiêu dâng cho Đức Giê-hô-va.'),
(12238, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 8, 36, 'OT', 'Họ trao các sắc lệnh của vua cho các quan tổng trấn của vua và các quan toàn quyền bên kia sông, và họ giúp đỡ dân sự và đền thờ Đức Chúa Trời.'),
(12239, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 9, 1, 'OT', 'Khi các việc nầy đã xong, các quan trưởng đến cùng tôi mà rằng: "Dân Y-sơ-ra-ên, các thầy tế lễ và các người Lê-vi không tách mình ra khỏi các dân tộc trong xứ, mà làm theo những điều gớm ghê như các dân Ca-na-an, dân Hê-th, dân Phê-ri-xi, dân Yê-bu-xi, dân Am-môn, dân Mô-áp, dân Ê-díp-tô, và dân A-mô-rị."'),
(12240, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 9, 2, 'OT', 'Vì chúng đã cưới các con gái của chúng làm vợ cho mình và cho các con trai mình, nên dòng dõi thánh đã lẫn lộn với các dân trong các xứ; hơn nữa, chính tay các quan trưởng và các viên chức đã dẫn đầu trong sự phạm tội nầy.'),
(12241, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 9, 3, 'OT', 'Khi tôi nghe điều đó, tôi xé áo và áo ngoài mình, nhổ tóc trên đầu và râu mình, rồi ngồi lặng người trong sự kinh hoàng.'),
(12242, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 9, 4, 'OT', 'Bấy giờ, mọi người sợ hãi vì các lời của Đức Chúa Trời Y-sơ-ra-ên, vì tội bất trung của những người bị lưu đày, đều nhóm lại cùng tôi; còn tôi, tôi ngồi buồn rầu cho đến buổi tế chiều.'),
(12243, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 9, 5, 'OT', 'Khi của lễ chiều được dâng lên, tôi đứng dậy khỏi cơn buồn rầu, rồi xé áo và áo ngoài mình ra, quỳ gối xuống và giang tay ra trước mặt Đức Giê-hô-va Đức Chúa Trời tôi.'),
(12244, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 9, 6, 'OT', 'Lạy Đức Chúa Trời tôi, tôi hổ thẹn và xấu hổ đến nỗi không dám ngước mặt lên cùng Ngài, vì những tội ác của chúng tôi đã gia tăng quá đầu chúng tôi, và tội lỗi chúng tôi đã lớn đến tận trời.'),
(12245, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 9, 7, 'OT', 'Từ những ngày của tổ tiên chúng tôi, chúng tôi đã phạm tội trọng cho đến ngày nay; và vì những tội lỗi chúng tôi, chúng tôi, các vua và thầy tế lễ của chúng tôi, đã bị trao vào tay các vua các nước, chịu gươm, bị bắt làm phu tù, bị cướp phá, và bị sỉ nhục mặt mày, như ngày nay.'),
(12246, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 9, 8, 'OT', 'Và bây giờ, trong chốc lát ngắn ngủi, có ơn thương xót từ Đức Giê-hô-va Đức Chúa Trời chúng ta, để còn sót lại một nhóm người thoát nạn, và đặt cho chúng ta một cái đinh nơi thánh địa của Ngài, để Đức Chúa Trời chúng ta soi sáng mắt chúng ta, và ban cho chúng ta chút sự sống lại trong cảnh nô lệ của mình.'),
(12247, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 9, 9, 'OT', 'Vì chúng tôi là kẻ tôi mọi, nhưng Đức Chúa Trời của chúng tôi không từ bỏ chúng tôi trong lúc chúng tôi bị lưu đày; Ngài đã đổ sự thương xót trên chúng tôi trước mặt các vua nước Ba Tư, để ban cho chúng tôi sự sống lại, dựng lại đền thờ Đức Chúa Trời chúng tôi và sửa chữa những nơi đổ nát của nó, và ban cho chúng tôi một bức tường tại Giu-đa và tại Giê-ru-sa-lem.'),
(12248, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 9, 10, 'OT', 'Và bây giờ, lạy Đức Chúa Trời chúng tôi, chúng tôi còn nói gì nữa đây, vì chúng tôi đã từ bỏ các mạng lịnh của Ngài?'),
(12249, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 9, 11, 'OT', 'Đức Giê-hô-va đã truyền cho các tiên tri tôi tớ Ngài rằng: "Đất mà các ngươi sẽ vào để chiếm lấy là đất ô uế, vì sự ô uế của các dân tộc nơi đó, do những điều gớm ghê mà chúng đã làm cho đầy đất, từ đầu này đến đầu kia, bằng sự ô uế của chúng."'),
(12250, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 9, 12, 'OT', 'Bây giờ, các con gái các ngươi, đừng gả cho các con trai của chúng; các con gái của chúng, cũng đừng lấy cho các con trai các ngươi. Đừng tìm sự bình an và lợi ích của chúng đến đời đời, để các ngươi được vững mạnh, ăn những điều tốt lành của đất và để lại làm cơ nghiệp cho con cháu các ngươi đến mãi mãi.'),
(12251, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 9, 13, 'OT', 'Và sau tất cả những điều đã xảy đến cho chúng tôi vì các việc ác của chúng tôi và tội lỗi lớn chúng tôi, vì Ngài là Đức Chúa Trời của chúng tôi đã khoan giảm cho chúng tôi khỏi tội lỗi chúng tôi, và đã ban cho chúng tôi sự thoát khỏi như thế này;'),
(12252, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 9, 14, 'OT', 'Chúng tôi há sẽ trở lại mà vi phạm các mạng lịnh của Ngài, và kết thông gia với các dân tộc làm những điều ghê tởm sao? Há Ngài sẽ không nổi giận cùng chúng tôi cho đến khi tiêu diệt hoàn toàn, không còn sót lại một ai hay một kẻ thoát thân nào sao?'),
(12253, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 9, 15, 'OT', 'Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên, Ngài là Đấng công bình; vì chúng tôi còn sót lại một nhóm người thoát nạn như ngày nay. Nầy, chúng tôi đứng trước mặt Ngài trong tội lỗi của chúng tôi; bởi vì chúng tôi không thể đứng trước mặt Ngài vì điều nầy.'),
(12254, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 1, 'OT', 'Khi Ê-xơ-ra đang cầu nguyện và thú nhận tội mình, vừa khóc vừa sấp mình trước đền thờ Đức Chúa Trời, thì có một hội chúng rất đông từ Y-sơ-ra-ên gồm các đàn ông, đàn bà và trẻ em tụ họp quanh ông; vì dân chúng khóc rất thảm thiết.'),
(12255, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 2, 'OT', 'Sê-can-nia, con trai của Giê-hi-ên, thuộc dòng dõi Ê-lam, đáp lời Ê-xơ-ra rằng: "Chúng tôi đã phạm tội cùng Đức Chúa Trời chúng tôi, khi cưới các người vợ ngoại quốc từ các dân trong xứ; nhưng hiện nay vẫn còn hy vọng cho Ít-ra-en về điều này."'),
(12256, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 3, 'OT', 'Bây giờ, hãy lập giao ước với Đức Chúa Trời chúng ta để đuổi ra khỏi tất cả các người vợ và những đứa con sinh ra từ họ, theo ý kiến của các lãnh đạo và những người kính sợ mạng lịnh của Đức Chúa Trời chúng ta; và việc đó phải được thực hiện theo luật pháp.'),
(12257, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 4, 'OT', 'Hãy chỗi dậy, vì điều nầy thuộc về ngươi; chúng tôi cũng ở cùng ngươi: hãy vững lòng và thực hiện đi.'),
(12258, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 5, 'OT', 'Bấy giờ Ê-xơ-ra đứng dậy, khiến các thầy tế lễ cả, người Lê-vi và toàn thể dân Y-sơ-ra-ên phải thề hứa rằng họ sẽ làm theo lời này. Và họ đã thề.'),
(12259, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 6, 'OT', 'Ê-xơ-ra đứng dậy khỏi trước nhà Đức Chúa Trời, đi vào phòng của Giô-ha-nan, con trai Ê-li-a-síp, và khi đến nơi, ông không ăn bánh, không uống nước, vì khóc than về tội lỗi của những người bị lưu đày.'),
(12260, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 7, 'OT', 'Họ truyền tin khắp Giu-đa và Giê-ru-sa-lem cho mọi con cái của những người bị lưu đày, để họ phải tập họp tại Giê-ru-sa-lem.'),
(12261, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 8, 'OT', 'Phàm kẻ nào không đến trong vòng ba ngày, theo ý kiến của các quan trưởng và các bậc trưởng lão, thì mọi tài sản của người ấy sẽ bị tịch thu, và chính người ấy sẽ bị truất khỏi hội chúng những kẻ bị lưu đày.'),
(12262, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 9, 'OT', 'Vậy hết thảy người nam của Giu-đa và Bên-gia-min đều nhóm hiệp về Giê-ru-sa-lem trong vòng ba ngày, ấy là tháng chín, ngày hai mươi của tháng đó. Hết thảy dân chúng ngồi trong sân nhà Đức Chúa Trời, run rẩy vì điều này và vì cơn mưa lớn.'),
(12263, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 10, 'OT', 'Bấy giờ, thầy tế lễ Ê-xơ-ra đứng dậy và nói với họ rằng: "Chính các ngươi đã phạm tội, lại còn cưới các vợ ngoại bang, làm tăng thêm tội lỗi của Ít-ra-en."'),
(12264, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 11, 'OT', 'Bây giờ, hãy dâng lời cảm tạ cho Đức Giê-hô-va Đức Chúa Trời của tổ tiên các ngươi, và làm theo ý muốn Ngài; hãy phân rẽ khỏi dân các nước và khỏi những người vợ ngoại.'),
(12265, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 12, 'OT', 'Bấy giờ, toàn thể hội chúng đáp lại và nói bằng tiếng kêu lớn: "Đúng như lời ông, chúng tôi phải làm điều đó."'),
(12266, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 13, 'OT', 'Nhưng dân chúng rất đông, và thời tiết đang mưa nhiều, chúng tôi không thể đứng ngoài trời được, và công việc này không thể hoàn tất trong một ngày hay hai ngày, vì chúng tôi đã phạm tội rất nhiều trong việc nầy.'),
(12267, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 14, 'OT', 'Hãy để các quan trưởng của chúng ta đứng ra lo cho cả cộng đồng, và tất cả những người trong các thành chúng ta đã cưới vợ ngoại bang phải đến vào những thời điểm đã định, cùng với các trưởng lão của mỗi thành và các quan xét của thành ấy, cho đến khi cơn thịnh nộ dữ dội của Đức Chúa Trời chúng ta vì việc này được quay khỏi chúng ta.'),
(12268, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 15, 'OT', 'Chỉ có Giô-na-than, con trai của A-xa-ên, và Gia-ha-xi-a, con trai của Tích-va, đứng về việc nầy; và Mê-thu-sa-lam cùng Sáp-bê-thai, người Lê-vi, giúp đỡ họ.'),
(12269, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 16, 'OT', 'Các con cái của những người bị lưu đày đã làm như vậy. Bấy giờ, Ê-xơ-ra thầy tế lễ và những người trưởng tộc theo các nhà họ hàng của họ, và tất cả đều theo tên riêng của mình, được tách ra và ngồi xuống vào ngày đầu tháng mười, trong triều đại Đa-ri-ú.'),
(12270, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 17, 'OT', 'Họ hoàn tất việc xử lý tất cả những người đàn ông đã cưới vợ người nước ngoài, đến ngày đầu tiên của tháng đầu tiên.'),
(12271, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 18, 'OT', 'Trong các con trai của thầy tế lễ, người ta phát hiện có những kẻ đã cưới vợ người ngoại: thuộc dòng dõi của Giê-sua, con trai của Giô-xa-đắc, và các anh em ông là Ma-a-xe-ya, Ê-li-ê-xe, Gia-rib và Ghê-đa-lia.'),
(12272, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 19, 'OT', 'Họ đã đưa tay ra để đuổi các vợ mình đi, và những người có tội đã dâng một con chiên đực trong bầy làm của lễ chuộc tội mình.'),
(12273, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 20, 'OT', 'Và từ con trai của Im-mê: Ha-na-ni và Xê-ba-đia.'),
(12274, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 21, 'OT', 'Và trong con cháu của Ha-rim: Ma-a-xe-ia, Ê-li-a, Sê-ma-ia, Giê-chi-ên và Út-xi-a.'),
(12275, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 22, 'OT', 'Và trong con cháu của Pha-šhur: Ê-li-ô-ênai, Ma-a-xe-gia, Ích-ma-ên, Nét-ha-nên, Giô-xa-bát và Ê-la-sa.'),
(12276, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 23, 'OT', 'Về phía các người Lê-vi: Giô-xa-bát, Si-mê-i, Kê-la-i-a (chính là Kê-li-ta), Phê-tha-hia, Giu-đa và Ê-li-ê-xe.'),
(12277, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 24, 'OT', 'Trong các người ca hát có Ê-li-a-síp; và trong các người giữ cửa có Sa-lum, Tê-lem và Ú-ri.'),
(12278, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 25, 'OT', 'Và từ Y-sơ-ra-ên, con cháu của Pha-rốt: Ra-mi-a, Giê-xi-a, Ma-lê-ki-a, Mi-a-min, Ê-lê-a-xa, Ma-lê-ki-a, và Bên-nai-a.'),
(12279, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 26, 'OT', 'Và trong các con trai của Ê-lam: Mát-ta-nia, Xa-cha-ri, Giê-hi-ên, Áp-đi, Giê-rê-mốt, và Ê-li-a.'),
(12280, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 27, 'OT', 'Về con trai của Xát-tu: Ê-li-ô-ê-nai, Ê-li-a-síp, Mát-ta-nia, Giê-rê-mốt, Xa-bát và A-xi-xa.'),
(12281, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 28, 'OT', 'Về con trai của Bê-bai: Giô-hô-chân, Ha-na-nia, Xáp-bai, A-thlai.'),
(12282, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 29, 'OT', 'Và trong con trai của Ba-ni: Mêsulam, Malúc, A-đai-ah, Gia-sub, Sê-ál và Ra-mốt.'),
(12283, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 30, 'OT', 'Về con cháu của Pha-thết-mô-áp: A-đna, Kê-lan, Bê-nai-a, Ma-a-xe-ia, Ma-ta-nia, Bết-xa-lên, và Bin-nui, và Ma-na-xe.'),
(12284, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 31, 'OT', 'Và các con trai của Ha-rim: Ê-li-ê-xe, I-si-gia, Ma-lê-ki-a, Sê-ma-gia, Si-mê-ôn.'),
(12285, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 32, 'OT', 'Bên-gia-min, Mal-lych, và Sê-ma-ri-a.'),
(12286, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 33, 'OT', 'Từ con trai của Ha-sum: Mát-tê-nai, Mát-ta-tha, Xa-bát, Ê-li-phê-lết, Giê-rê-mai, Ma-na-se và Si-mê-i.'),
(12287, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 34, 'OT', 'Trong con cái của Ba-ni: Ma-a-đai, A-mơ-ram và U-ên.'),
(12288, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 35, 'OT', 'Bê-nai-a, Bê-đê-a, Kê-lu-ha,'),
(12289, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 36, 'OT', 'Va-ni-a, Mê-rê-mốt, Ê-li-a-síp.'),
(12290, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 37, 'OT', 'Mát-ta-nia, Mát-tên-nai và Gia-a-sau.'),
(12291, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 38, 'OT', 'Ba-ni, Bi-nui và Sê-mi.'),
(12292, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 39, 'OT', 'Và Sê-lê-mi-a, và Na-than, và A-đai-a.'),
(12293, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 40, 'OT', 'Mách-na-đe-bai, Sát-xai, Sa-rai,'),
(12294, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 41, 'OT', 'A-xa-rên, và Sê-lê-mi-a, Sê-ma-ri-a,'),
(12295, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 42, 'OT', 'Sa-lum, A-ma-ri-a, và Giô-sép.'),
(12296, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 43, 'OT', 'Con trai cháu dòng họ Nê-bô: Giê-i-ên, Ma-tít-thi-a, Xa-bát, Xê-bin-nai, Gia-đau, Giô-ên và Bê-na-gia.'),
(12297, 15, 'GOI_vi', 'GOI_vi', 'vi', 'EZR', 10, 44, 'OT', 'Tất cả những người này đều lấy vợ ngoại giáo; và trong số họ có người đã có vợ và sinh con cái.'),
(12298, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 1, 1, 'OT', 'Lời của Nê-hê-mi, con trai của Ha-cha-lai-a. Xảy ra trong tháng Kít-lêu, năm thứ hai mươi, khi ấy tôi đang ở tại thành Su-sơ, thủ đô.'),
(12299, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 1, 2, 'OT', 'Vậy Ha-na-ni, một người anh em của tôi, đến cùng vài người đàn ông từ Giu-đa; tôi liền hỏi họ về những người Do Thái còn sót lại, những người đã thoát nạn còn sống sót từ cuộc lưu đày, và về tình trạng Giê-ru-sa-lem.'),
(12300, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 1, 3, 'OT', 'Họ nói với tôi: "Những người còn sót lại, là những người còn sót lại từ cuộc lưu đày, đang ở trong cảnh khốn khổ lớn và bị sỉ nhục; còn tường thành Giê-ru-sa-lem thì bị phá vỡ, và các cổng của nó đã bị lửa thiêu cháy."'),
(12301, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 1, 4, 'OT', 'Khi tôi nghe những lời nầy, tôi ngồi xuống khóc, than khóc một vài ngày, nhịn ăn và cầu nguyện trước mặt Đức Chúa Trời của các từng trời.'),
(12302, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 1, 5, 'OT', 'Lạy Đức Giê-hô-va, là Đức Chúa Trời của các từng trời, là Đức Chúa Trời lớn và đáng kính sợ, giữ giao ước và sự nhân từ cho những người yêu Ngài và tuân giữ các điều răn của Ngài, tôi xin Ngài hãy nghe.'),
(12303, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 1, 6, 'OT', 'Xin hãy để tai Ngài chăm chú lắng nghe và mắt Ngài mở ra, hầu nghe được lời cầu nguyện của đầy tớ Ngài mà tôi đang dâng trước mặt Ngài ngày và đêm vì các con của Y-sơ-ra-ên, những đầy tớ Ngài; và tôi thú nhận các tội lỗi mà các con của Y-sơ-ra-ên đã phạm nghịch cùng Ngài: cả tôi và nhà cha tôi đều đã phạm tội.'),
(12304, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 1, 7, 'OT', 'Chúng tôi đã phạm tội nặng nề cùng Ngài, và không giữ các điều răn, các luật lệ và các quyết định mà Ngài đã truyền cho Môi-se, tôi tớ Ngài.'),
(12305, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 1, 8, 'OT', 'Xin hãy nhớ lời mà Ngài đã truyền cho Môi-se, tôi tớ Ngài, rằng: "Nếu các ngươi phạm tội, Ta sẽ phân tán các ngươi giữa các dân tộc."'),
(12306, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 1, 9, 'OT', 'Nhưng nếu các ngươi trở lại cùng ta, giữ các điều răn ta và làm theo, thì dầu các ngươi bị đuổi đến tận cùng trời, ta cũng sẽ nhóm các ngươi lại từ nơi đó, và đem các ngươi đến nơi mà ta đã chọn để đặt danh ta ở đó.'),
(12307, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 1, 10, 'OT', 'Chúng là các tôi tớ Ngài và dân sự Ngài, mà Ngài đã chuộc bằng quyền năng lớn và bằng tay quyền năng của Ngài.'),
(12308, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 1, 11, 'OT', 'Lạy Đức Giê-hô-va, xin hãy lắng nghe lời cầu nguyện của đầy tớ Ngài và lời cầu nguyện của các đầy tớ Ngài, là những người hết lòng kính sợ danh Ngài; xin làm cho đầy tớ Ngài được thành công hôm nay và ban cho đầy tớ Ngài được ơn trước mặt người đàn ông này. Vì tôi là người hầu rượu của vua.'),
(12309, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 2, 1, 'OT', 'Vào tháng Ni-san, năm thứ hai mươi đời vua A-tác-xét-xe, rượu được dọn ra trước mặt vua; tôi bèn bưng rượu dâng vua. Trước đó, tôi chưa hề buồn rầu trước mặt vua.'),
(12310, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 2, 2, 'OT', 'Vua hỏi tôi: "Tại sao mặt mày buồn, trong khi ngươi không đau ốm gì? Chắc chắn điều này chẳng qua là nỗi buồn trong lòng." Tôi rất sợ hãi, cực kỳ sợ hãi.'),
(12311, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 2, 3, 'OT', 'Tôi thưa cùng vua: "Nguyện vua sống đời đời! Sao nét mặt tôi không buồn được, khi thành phố, nơi phần mộ tổ tiên tôi, đang hoang tàn, và các cổng thành của nó bị lửa thiêu rụi?"'),
(12312, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 2, 4, 'OT', 'Vua hỏi tôi: "Ngươi xin điều gì?" Tôi bèn cầu nguyện Đức Chúa Trời của các từng trời.'),
(12313, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 2, 5, 'OT', 'Tôi tâu với vua: "Nếu được ơn trước mặt vua, và nếu tôi có được ơn trước mặt ngài, xin vua sai tôi đi Giu-đa, đến thành có mồ mả tổ tiên tôi, để tôi xây cất lại thành ấy."'),
(12314, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 2, 6, 'OT', 'Vua nói với tôi: "Hoàng hậu cũng đang ngồi bên cạnh vua. Ngươi sẽ đi bao lâu, và khi nào trở lại?" Và điều đó đẹp lòng vua, nên người cho tôi đi; tôi đã định rõ cho vua một thời gian.'),
(12315, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 2, 7, 'OT', 'Tôi thưa cùng vua: "Nếu thấy vừa lòng trước mặt vua, xin vua ban cho tôi những bức thư gửi các quan tổng trấn bên kia sông, để họ cho tôi qua cho đến khi tôi đến Giu-đa."'),
(12316, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 2, 8, 'OT', 'Và một bức thư cho Ách-áp, người giữ rừng vua, để ông cấp cho tôi gỗ làm xà cho các cổng đồn trú gần đền thờ, cho tường thành và cho ngôi nhà mà tôi sẽ vào ở. Vua đã cấp cho tôi điều đó theo tay tốt lành của Đức Chúa Trời tôi trên tôi.'),
(12317, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 2, 9, 'OT', 'Tôi đi đến các quan tổng trấn bên kia sông, và trao cho họ các thư của vua. Vả, vua đã sai các quan chỉ huy quân đội và kỵ binh đi cùng tôi.'),
(12318, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 2, 10, 'OT', 'San-ba-lát người Hô-rô-nim và Tô-bi-gia, đầy tớ người Am-môn, nghe thấy điều đó, thì rất tức giận vì có một người đến tìm điều tốt cho con cái Ít-ra-en.'),
(12319, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 2, 11, 'OT', 'Tôi đến Giê-ru-sa-lem và ở đó ba ngày.'),
(12320, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 2, 12, 'OT', 'Tôi chỗi dậy giữa đêm, tôi và một vài người đàn ông cùng tôi; tôi không cho một ai biết điều Đức Chúa Trời đã đặt trong lòng tôi để làm tại Giê-ru-sa-lem; và không có súc vật nào cùng tôi, ngoại trừ con vật mà tôi cỡi trên nó.'),
(12321, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 2, 13, 'OT', 'Tôi ra đi ban đêm qua cổng Thung lũng, hướng về suối Rồng và đến cổng Phế liệu; tôi xem xét các tường thành Giê-ru-sa-lem, thấy các nơi bị phá sập và các cổng của thành bị lửa thiêu rụi.'),
(12322, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 2, 14, 'OT', 'Tôi đi đến cổng Suối, rồi đến hồ của vua; nhưng không có chỗ nào để con vật tôi cưỡi đi qua.'),
(12323, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 2, 15, 'OT', 'Tôi đi lên về phía khe vào ban đêm, quan sát bức tường, rồi trở lại, đi vào cổng Thung Lũng và trở về.'),
(12324, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 2, 16, 'OT', 'Các quan tổng trấn không biết tôi đã đi đâu, hay tôi đang làm gì; tôi cũng chưa cho người Do Thái, các thầy tế lễ, các người lãnh đạo, các quan tổng trấn, hay những người khác làm công việc biết điều đó.'),
(12325, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 2, 17, 'OT', 'Tôi nói với họ: "Các anh thấy rõ cảnh khốn khổ chúng ta đang gặp phải: Giê-ru-sa-lem bị tàn phá, các cổng thành bị lửa thiêu cháy. Nào, hãy cùng nhau xây lại tường thành Giê-ru-sa-lem, để chúng ta không còn bị sỉ nhục nữa."'),
(12326, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 2, 18, 'OT', 'Tôi đã thuật cho họ về tay Đức Chúa Trời nhân từ đối với tôi, và cả những lời của vua mà người đã nói với tôi. Họ đáp: "Hãy đứng lên, chúng ta sẽ xây cất." Vậy họ vững tay trong công việc lành ấy.'),
(12327, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 2, 19, 'OT', 'Khi ấy, San-ba-lát, người Hô-rô-nít, và Tô-bi-gia, đầy tớ người Am-môn, và Ghê-sem, người Ả-rập, nghe biết điều đó, bèn chế nhạo chúng tôi, khinh bỉ chúng tôi, và nói rằng: "Việc các ngươi đang làm này là việc gì? Các ngươi định phản nghịch với vua sao?"'),
(12328, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 2, 20, 'OT', 'Tôi đáp lại họ và nói: Đức Chúa Trời của các tầng trời, chính Ngài sẽ giúp chúng tôi thành công; vì vậy chúng tôi là tôi tớ của Ngài sẽ đứng dậy và xây cất; còn các ông thì không có phần, không có quyền lợi, cũng không có kỷ niệm gì tại Giê-ru-sa-lem.'),
(12329, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 3, 1, 'OT', 'Thầy tế lễ lớn Ê-li-a-síp cùng các anh em thầy tế lễ chung nhau xây dựng cổng Chiên; họ biệt riêng cổng này ra thánh, dựng các cánh cửa của nó, và biệt riêng ra thánh cho đến tháp Mê-a, cho đến tháp Ha-na-nên.'),
(12330, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 3, 2, 'OT', 'Kế bên người ấy, những người đàn ông của Giê-ri-khô xây cất. Và kế bên họ, Xác-cua con trai Ím-ri xây cất.'),
(12331, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 3, 3, 'OT', 'Còn về cổng Cá, thì con trai của Ha-xen-nanh xây cất; chính họ tra đòn tay, dựng các cửa, các then khóa và các thanh gài của cổng ấy.'),
(12332, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 3, 4, 'OT', 'Và kế bên họ, Mê-rê-mốt, con trai Ú-ri-gia, cháu nội Ha-cốt, đã ra sức xây sửa. Kế bên họ, Mê-thu-lam, con trai Bê-rê-ki-gia, cháu nội Mết-xe-xa-bên, đã ra sức xây sửa. Và kế bên họ, Xa-đốc, con trai Ba-ana, đã ra sức xây sửa.'),
(12333, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 3, 5, 'OT', 'Các người Tê-ko-ít tiếp tục sửa chữa sau họ; nhưng những người lãnh đạo của họ không chịu cúi cổ mình vào công việc của Chúa các ông.'),
(12334, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 3, 6, 'OT', 'Còn về cái cổng cũ, thì Giô-i-đa, con trai của Pa-xê-ách, và Mê-xu-lam, con trai của Bê-xô-đi-ách, đã sửa chữa nó; họ đã sửa lại các đà ngang của nó, dựng các cửa của nó lên, cùng với then khóa và các cây gài cửa của nó.'),
(12335, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 3, 7, 'OT', 'Và kế bên họ, Mê-latia người Ghi-bê-ôn, và Ya-đôn người Mê-rô-nốt, những người của Ghi-bê-ôn và Mít-pa, sửa chữa đến ngôi ngai của viên tổng trấn bên kia sông.'),
(12336, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 3, 8, 'OT', 'U-xi-ên, con trai của Ha-cha-i-a, thuộc nhóm thợ vàng, cùng xây cất bên cạnh ông; và Ha-na-nia, con trai của một người thuộc nhóm thợ thuốc, cũng xây cất bên cạnh ông; họ xây cất cho đến bức tường rộng tại Giê-ru-sa-lem.'),
(12337, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 3, 9, 'OT', 'Cùng với họ, Rê-pha-i-a, con trai của Hur, người cai trị phân nửa phần Giê-ru-sa-lem, đã ra sức giúp đỡ.'),
(12338, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 3, 10, 'OT', 'Còn họ hàng bên cạnh họ, thì Giê-đa-i-ah, con trai của Ha-ru-máp, tiếp tục sửa chữa ngay đối diện nhà mình. Và bên cạnh ông ấy, thì Ha-tút, con trai của Ha-sáp-ni-a, tiếp tục sửa chữa.'),
(12339, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 3, 11, 'OT', 'Ma-láchi-a, con trai của Ha-rim, và Ha-súp, con trai của Pha-thát-mô-áp, cùng sửa đoạn thứ nhì và tháp các lò lửa.'),
(12340, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 3, 12, 'OT', 'Sau người ấy, Sa-lum con trai Ha-lô-hết, lãnh đạo nửa phần thành Giê-ru-sa-lem, cùng các con gái người, tiếp tục sửa chữa.'),
(12341, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 3, 13, 'OT', 'Ha-nun cùng những người dân ở Xa-nô-ách sửa chữa cổng Thung Lũng; họ xây dựng cổng ấy, dựng các cửa, then khóa và then cài của nó, và một ngàn thước tường cho đến Cổng Phân.'),
(12342, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 3, 14, 'OT', 'Còn cổng Dung, Ma-lê-chi-a, con trai Rê-cáp, người cai quản một phần xứ Bết Ha-xe-rem, đã sửa chữa; người xây cất cổng ấy, dựng các cửa, then cài và then gài của nó.'),
(12343, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 3, 15, 'OT', 'Còn về phần cổng Nước, thì Xa-lun, con trai của Can-hô-xe, người cai trị một phần Mít-pa, sửa chữa cổng ấy; người xây cất và đóng mái lại, đặt các cửa, then khóa và then ngang của nó; và người xây tường bao quanh hồ Si-lo-am gần khu vườn của vua, cho đến các bậc thang dẫn xuống từ thành Đa-vít.'),
(12344, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 3, 16, 'OT', 'Sau người ấy, Nê-hê-mi, con trai A-xbúc, lãnh đạo phân nửa phần Bết-xu-rơ, đã sửa chữa cho đến đối diện các phần mộ của Đa-vít, rồi đến cái hồ đã xây, và đến nhà các dũng sĩ.'),
(12345, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 3, 17, 'OT', 'Sau người ấy, các người Lê-vi là Rê-hum con trai của Ba-ni tiếp tục xây cất; kế bên người ấy, Ha-sa-bia, lãnh tụ phân nửa phần đất của Kê-ila, xây cất phần thuộc về mình.'),
(12346, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 3, 18, 'OT', 'Sau người ấy, anh em họ sửa lại cùng làm, là Ba-vai con trai của Hê-na-đát, lãnh đạo phân nửa phần đất Kê-ila.'),
(12347, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 3, 19, 'OT', 'Và người tiếp theo cùng xây là Ê-xơ, con trai của Giê-su, lãnh tụ của Mít-pah, một đoạn khác đối diện với dốc lên đến kho vũ khí, ở khúc quẹo.'),
(12348, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 3, 20, 'OT', 'Sau người ấy, Ba-rúc con trai Xáp-bai hết lòng sửa chữa phần còn lại, từ khúc quẹo đến cửa nhà Ê-li-a-síp thầy tế lễ cả.'),
(12349, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 3, 21, 'OT', 'Sau người ấy, Mê-rê-mốt, con trai Úc-ri-gia, con trai Ha-cốt, sửa chữa một đoạn khác, từ cửa nhà Ê-li-a-síp cho đến cuối nhà Ê-li-a-síp.'),
(12350, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 3, 22, 'OT', 'Sau người ấy, các thầy tế lễ, những người đàn ông ở đồng bằng, tiếp tục sửa chữa.'),
(12351, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 3, 23, 'OT', 'Sau người ấy, Binh-gia-min và Ha-xúp củng cố phần đối diện nhà mình. Sau người ấy, A-xa-ria, con trai Ma-a-xe-ia, con trai An-nan-nia, củng cố phần gần nhà ông.'),
(12352, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 3, 24, 'OT', 'Sau người ấy, Bin-nui con trai của Hen-na-đát sửa chữa một đoạn khác, từ nhà A-xa-ria cho đến điểm ngoặt và đến góc tường.'),
(12353, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 3, 25, 'OT', 'Pha-lal, con trai của Út-xai, sửa đoạn đối diện với chỗ ngoặt và tháp nhô ra từ nhà trên của vua, gần sân nhà tù. Sau người là Phê-đai-a, con trai của Pha-rốt.'),
(12354, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 3, 26, 'OT', 'Dân Nê-thi-nim ở tại Ô-phên cho đến đối diện với cửa nước về hướng đông và cái tháp nhô ra.'),
(12355, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 3, 27, 'OT', 'Sau họ, những người Tê-ko-ít tiếp tục sửa chữa một đoạn khác, đối diện tháp lớn nhô ra, cho đến tường thành Ô-phên.'),
(12356, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 3, 28, 'OT', 'Kể từ trên cổng ngựa, các thầy tế lễ đã sửa chữa, mỗi người đối diện nhà mình.'),
(12357, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 3, 29, 'OT', 'Sau họ, Xa-đốc, con trai của I-mê, tiếp tục sửa chữa đối diện nhà mình. Sau người ấy, Sê-ma-gia, con trai của Sê-can-gia, người giữ cửa Đông, cũng tiếp tục sửa chữa.'),
(12358, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 3, 30, 'OT', 'Sau người đó, Han-ni-a con trai của Sê-lê-mi-a và Ha-nun, con trai thứ sáu của Xa-láp, sửa chữa một phần khác. Sau người đó, Mết-đu-lam con trai của Bê-réc-ki-a sửa chữa đối diện với buồng riêng của người.'),
(12359, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 3, 31, 'OT', 'Sau người ấy, Mác-ki-a, con trai thợ vàng, sửa đến nơi ở của các Nê-ti-nim và các thương gia, đối diện với cửa Míp-hách, cho đến đoạn dốc lên góc tường.'),
(12360, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 3, 32, 'OT', 'Giữa đoạn đi lên từ góc đến cổng Chiên, các thợ bạc và các thương gia đã sửa chữa.'),
(12361, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 4, 1, 'OT', 'Khi San-ba-lát nghe được rằng chúng tôi đang xây bức tường, thì người ấy nổi giận và rất tức giận, rồi chế nhạo dân Giu-đa.'),
(12362, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 4, 2, 'OT', 'Hắn nói trước mặt anh em mình và đạo quân Sa-ma-ri, rồi nói: "Những người Do Thái yếu đuối này đang làm gì vậy? Chúng có tự xây thành bảo vệ mình không? Có dâng lễ tế không? Có hoàn tất trong một ngày không? Có làm sống lại những viên đá từ các đống phế tích bị thiêu cháy không?"'),
(12363, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 4, 3, 'OT', 'Và Tô-bi-gia người Am-môn ở gần người đó, và người ấy nói: "Ngay cả điều chúng đang xây, nếu một con chồn leo lên, nó cũng sẽ sập tường đá của chúng."'),
(12364, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 4, 4, 'OT', 'Lạy Đức Chúa Trời của chúng tôi, xin hãy nghe, vì chúng tôi bị sỉ nhục; xin trả sự sỉ nhục của chúng nó lại trên đầu chúng nó, và phó chúng nó cho sự cướp bóc tại đất lưu đày.'),
(12365, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 4, 5, 'OT', 'Đừng che lấp tội ác của chúng nó, và đừng để tội lỗi chúng nó được xóa khỏi trước mặt Ngài; vì chúng đã chọc giận trước mặt những người xây dựng.'),
(12366, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 4, 6, 'OT', 'Chúng tôi xây bức tường, và toàn bộ bức tường được nối liền cho đến nửa phần của nó; dân chúng có lòng sốt sắng làm việc.'),
(12367, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 4, 7, 'OT', 'Khi San-ba-lát, Tô-bi-gia, người Ả-rập, người Am-môn và người Ách-đốt nghe biết các bức tường thành Giê-ru-sa-lem đã được xây lại, các chỗ bị phá bắt đầu được sửa chữa, thì chúng rất tức giận.'),
(12368, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 4, 8, 'OT', 'Và tất cả bọn họ đã cấu kết cùng nhau để đến đánh nhau tại Giê-ru-sa-lem và cản trở việc xây dựng thành ấy.'),
(12369, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 4, 9, 'OT', 'Chúng tôi cầu nguyện cùng Đức Chúa Trời của chúng tôi, và đặt người canh giữ họ cả ngày lẫn đêm vì cớ họ.'),
(12370, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 4, 10, 'OT', 'Và Giu-đa nói: "Sức lực của những người gánh vác đã kiệt, và đống phế thải thì quá nhiều, nên chúng ta không thể xây tường được."'),
(12371, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 4, 11, 'OT', 'Kẻ thù chúng tôi nói: "Chúng nó sẽ không biết và không thấy, cho đến khi chúng tôi xông vào giữa chúng, giết chúng nó, và làm cho công việc phải ngừng lại."'),
(12372, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 4, 12, 'OT', 'Khi những người Do Thái sống gần họ đến, thì họ nói với chúng ta mười lần: "Từ khắp các nơi mà các ngươi sẽ trở về với chúng ta."'),
(12373, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 4, 13, 'OT', 'Tôi đã đặt những người ở các vị trí thấp phía sau tường và trên các chỗ cao; tôi đã sắp đặt dân theo các gia đình của họ, cùng với gươm, giáo và cung của họ.'),
(12374, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 4, 14, 'OT', 'Tôi nhìn quanh, rồi đứng dậy và nói với các quan trưởng, các lãnh tụ và phần còn lại của dân chúng: "Đừng sợ chúng; hãy nhớ đến Đức Giê-hô-va, là Đấng cao cả và đáng kính sợ, và hãy chiến đấu vì anh em, con trai và con gái, vợ và nhà cửa của các ngươi."'),
(12375, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 4, 15, 'OT', 'Khi quân thù chúng tôi nghe biết điều đó đã được tiết lộ cho chúng tôi, và Đức Chúa Trời khiến mưu kế của chúng trở nên vô hiệu, thì tất cả chúng tôi trở về lại vách thành, mỗi người trở lại công việc của mình.'),
(12376, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 4, 16, 'OT', 'Kể từ ngày đó, một nửa các đầy tớ của tôi làm việc, còn một nửa cầm các ngọn giáo, các cái khiên, các cây cung và các áo giáp; và các quan cai trị đứng phía sau cả nhà Giu-đa.'),
(12377, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 4, 17, 'OT', 'Những người xây trên tường và những người khiêng gánh nặng đều làm việc một tay thì làm công việc, tay kia thì nắm chắc ngọn giáo.'),
(12378, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 4, 18, 'OT', 'Các thợ xây, mỗi người đều đeo gươm bên hông mình mà xây. Còn người thổi loa thì ở gần tôi.'),
(12379, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 4, 19, 'OT', 'Tôi nói với các quan chức, các viên chức và phần còn lại của dân chúng: "Công việc thì lớn lao và rộng lớn, còn chúng ta thì bị chia rẽ trên bức tường, mỗi người cách xa anh em mình."'),
(12380, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 4, 20, 'OT', 'Ở đâu các ngươi nghe tiếng kèn, hãy tụ họp đến đó với chúng tôi; Đức Chúa Trời chúng tôi sẽ chiến đấu cho chúng ta.'),
(12381, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 4, 21, 'OT', 'Chúng tôi thì làm việc, còn một nửa cầm ngọn giáo từ khi trời vừa hửng sáng cho đến khi xuất hiện các ngôi sao.'),
(12382, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 4, 22, 'OT', 'Cũng trong thời ấy, tôi nói với dân chúng: "Mỗi người cùng đầy tớ của anh ấy hãy ở lại trong Giê-ru-sa-lem, để ban đêm họ canh giữ cho chúng ta, và ban ngày làm việc."'),
(12383, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 4, 23, 'OT', 'Tôi và anh em tôi, các đầy tớ tôi, cùng những người canh giữ đi theo tôi, không ai cởi áo mình ra, mỗi người chỉ cởi áo ra để tắm rửa.'),
(12384, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 5, 1, 'OT', 'Và có tiếng kêu lớn của dân chúng và các vợ họ chống lại anh em họ là người Giu-đa.'),
(12385, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 5, 2, 'OT', 'Có những người nói: Chúng tôi, các con trai và con gái của chúng tôi, đông lắm; vậy nên chúng tôi phải mua thóc để ăn và sống.'),
(12386, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 5, 3, 'OT', 'Cũng có những người nói: "Chúng tôi đã thế chấp ruộng đất, vườn nho và nhà cửa mình để mua thóc lúa trong lúc đói kém."'),
(12387, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 5, 4, 'OT', 'Cũng có những người nói: "Chúng tôi đã vay tiền để nộp thuế cho vua, dùng đất đai và vườn nho của chúng tôi làm thế chấp."'),
(12388, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 5, 5, 'OT', 'Và bây giờ, thân thể chúng tôi vẫn là thân thể anh em chúng tôi, con cái chúng tôi vẫn là con cái họ; và nầy, chúng tôi phải bán các con trai và con gái mình làm đầy tớ, và có những con gái của chúng tôi đã bị bắt làm đầy tớ; chúng tôi không thể làm gì được, vì đất đai và các vườn nho của chúng tôi đều thuộc về người khác.'),
(12389, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 5, 6, 'OT', 'Tôi rất tức giận khi nghe tiếng kêu than của họ và những lời này.'),
(12390, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 5, 7, 'OT', 'Tôi đã suy nghĩ trong lòng mình, rồi trách cứ các quan quyền và các viên chức; tôi nói với họ: "Tại sao các ông lại cho vay nặng lãi, mỗi người trên anh em mình?" Sau đó, tôi triệu tập một hội nghị lớn chống lại họ.'),
(12391, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 5, 8, 'OT', 'Tôi nói với họ: "Chúng tôi đã chuộc anh em mình là người Do Thái bị bán cho các dân ngoại, bằng khả năng của mình; vậy mà các anh cũng định bán anh em mình sao? Họ sẽ bị bán cho chúng tôi sao?" Họ im lặng và không tìm được lời nào để đáp lại.'),
(12392, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 5, 9, 'OT', 'Tôi nói: Việc các ông làm thật không tốt. Các ông chẳng lẽ không sống trong sự kính sợ Đức Chúa Trời chúng ta, vì sợ dân ngoại, kẻ thù của chúng ta, sỉ nhục sao?'),
(12393, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 5, 10, 'OT', 'Cả tôi, anh em tôi, và các đầy tớ tôi cũng cho họ vay bạc và lúa mì. Vậy hãy thôi ngay việc cho vay nặng lãi này đi.'),
(12394, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 5, 11, 'OT', 'Xin hãy trả lại cho họ ngay hôm nay các ruộng đất, các vườn nho, các vườn ô-liu và các nhà cửa của họ, cùng phần trăm tiền, thóc lúa, rượu và dầu mà các ông đang đòi lấy từ họ.'),
(12395, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 5, 12, 'OT', 'Họ nói: "Chúng tôi sẽ hoàn trả lại mọi thứ và sẽ không đòi hỏi gì nơi họ. Chúng tôi sẽ làm như ông nói." Rồi tôi gọi các thầy tế lễ và bắt họ thề rằng sẽ thực hiện điều này.'),
(12396, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 5, 13, 'OT', 'Tôi cũng xốc áo tôi lên và nói: "Đức Chúa Trời sẽ xốc ra khỏi nhà và khỏi công việc của mình mọi người không thực hiện lời hứa này, cũng như vậy, người ấy sẽ bị xốc ra và trở nên trống rỗng." Toàn thể hội chúng đáp: "A-men," và ca ngợi Đức Giê-hô-va. Dân chúng làm theo lời hứa ấy.'),
(12397, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 5, 14, 'OT', 'Cũng từ ngày ta được chỉ định làm tổng trấn cai trị miền đất Giu-đa, từ năm thứ hai mươi cho đến năm thứ ba mươi hai đời vua Ác-ta-xét-xe, tức là mười hai năm, ta và các anh em ta đã không ăn lương bổng của tổng trấn.'),
(12398, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 5, 15, 'OT', 'Các quan tổng trấn trước đây, những người đã ở trước mặt ta, đã gây gánh nặng cho dân, lấy của họ bánh và rượu, ngoài ra còn bốn mươi séc-lơ bạc; và cả các đầy tớ của họ cũng thống trị dân. Nhưng ta đã không làm như vậy, vì kính sợ Đức Chúa Trời.'),
(12399, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 5, 16, 'OT', 'Và chính tôi cũng tiếp tục công việc xây bức tường này; chúng tôi không mua đất đai nào, và tất cả các đầy tớ tôi đều tập trung tại đó để làm việc.'),
(12400, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 5, 17, 'OT', 'Hơn nữa, có một trăm năm mươi người Do Thái và các quan chức cùng những người đến cùng chúng tôi từ các dân tộc xung quanh ngồi bàn tiệc của tôi.'),
(12401, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 5, 18, 'OT', 'Mỗi ngày dâng một con bò, sáu con chiên tốt, và các loại chim được dọn cho tôi; còn mỗi mười ngày thì có đủ thứ rượu để dùng. Nhưng tôi không đòi lương thực của chức quan tổng trấn, vì gánh nặng đã đè nặng trên dân này.'),
(12402, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 5, 19, 'OT', 'Lạy Đức Chúa Trời của tôi, xin hãy nhớ tôi để làm điều thiện, về mọi điều tôi đã làm cho dân sự nầy.'),
(12403, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 6, 1, 'OT', 'Khi San-ba-lát, Tô-bi-gia, Ghê-sem người Ả-rập và phần còn lại của các kẻ thù chúng tôi nghe biết rằng tôi đã xây tường và trên đó không còn chỗ nứt vỡ nào cả, dù đến lúc ấy tôi vẫn chưa đặt các cánh cửa lên các cổng.'),
(12404, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 6, 2, 'OT', 'Bấy giờ San-ba-lát và Ghê-sem sai đến bảo tôi rằng: "Hãy đến, chúng ta sẽ họp nhau cùng nhau tại Kê-phí-rim, trong thung lũng A-nô." Nhưng chúng toan làm điều ác hại tôi.'),
(12405, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 6, 3, 'OT', 'Tôi đã sai các sứ giả đến cùng họ, nói rằng: Tôi đang làm một công việc lớn, tôi không thể xuống được. Sao công việc lại phải ngưng lại khi tôi rời bỏ nó để xuống cùng các ông?'),
(12406, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 6, 4, 'OT', 'Họ đã sai đến tôi như vậy bốn lần, và tôi đều đáp lại họ như lời ấy.'),
(12407, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 6, 5, 'OT', 'Bấy giờ San-ba-lát sai đầy tớ đến cùng tôi lần thứ năm, tay người ấy cầm thư mở.'),
(12408, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 6, 6, 'OT', 'Được chép trong đó rằng: "Điều này đã được đồn đại giữa các dân tộc, và Gát-mu nói rằng: ''Ngươi và người Do Thái định nổi loạn; vì lý do đó, ngươi xây bức tường nầy, để ngươi có thể làm vua cho họ theo những lời nầy.''"'),
(12409, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 6, 7, 'OT', 'Hơn nữa, Ngài đã lập các nhà tiên tri để rao giảng về Ngài tại Giê-ru-sa-lem rằng: "Vua tại Giu-đa!" Và bây giờ, những lời này sẽ được tâu lên cho vua. Vậy bây giờ, hãy đến, và chúng ta sẽ cùng nhau bàn luận.'),
(12410, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 6, 8, 'OT', 'Tôi sai người đến gặp người đó, nói: Những điều mà người nói không hề xảy ra; chính từ lòng người mà người tưởng tượng ra những điều ấy.'),
(12411, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 6, 9, 'OT', 'Vì tất cả bọn chúng đều làm chúng tôi sợ hãi, nói rằng: "Tay chúng nó sẽ yếu đi khỏi công việc, và công việc sẽ không được hoàn thành." Bây giờ, xin hãy làm cho tay tôi được vững mạnh.'),
(12412, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 6, 10, 'OT', 'Sau đó, tôi đến nhà Sê-ma-gia, con trai của Đê-la-gia, con trai của Mê-hê-ta-bên, người đang bị giam giữ. Người ấy nói: "Chúng ta hãy cùng nhau đến nhà Đức Chúa Trời, vào bên trong đền thờ, và hãy đóng các cửa đền thờ lại, vì họ đang đến để giết ông; chính trong đêm nay họ sẽ đến để giết ông."'),
(12413, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 6, 11, 'OT', 'Tôi đã nói: Một người như tôi sao lại chạy trốn? Và ai như tôi lại vào đền thờ để cứu mạng sống mình? Tôi sẽ không vào đâu.'),
(12414, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 6, 12, 'OT', 'Tôi nhận biết rằng Đức Chúa Trời không sai phái người ấy; vì lời tiên tri mà người nói về tôi là do lòng riêng; thật ra, Tô-bi-a và Sanballát đã trả tiền cho người ấy.'),
(12415, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 6, 13, 'OT', 'Vì người đã được trả công để tôi phải sợ hãi mà làm điều đó, phạm tội; và họ sẽ có cớ để vu khống tôi.'),
(12416, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 6, 14, 'OT', 'Lạy Đức Chúa Trời, xin hãy nhớ lại Tô-bi-gia và Xan-ba-lát tùy theo các việc mà họ đã làm; và cũng xin nhớ lại nữ tiên tri Nô-a-đia cùng các đấng tiên tri khác, những người đã tìm cách làm tôi sợ hãi.'),
(12417, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 6, 15, 'OT', 'Vậy, bức tường được hoàn thành vào ngày hai mươi lăm tháng Ê-lul, trong năm mươi hai ngày.'),
(12418, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 6, 16, 'OT', 'Khi mọi kẻ thù nghịch chúng tôi nghe điều đó, và mọi dân tộc xung quanh chúng tôi thấy việc này, thì chúng đều rất hụt chí trong mắt mình; và chúng biết rằng công việc này được thực hiện bởi Đức Chúa Trời chúng tôi.'),
(12419, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 6, 17, 'OT', 'Cũng trong những ngày ấy, các quan trong Giu-đa gửi nhiều thơ đến Tô-bi-a; và những thơ của Tô-bi-a được gửi đến họ.'),
(12420, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 6, 18, 'OT', 'Vì nhiều người ở Giu-đa đã thề trung thành với nó, vì nó là con rể của Xéc-cha-nia, con trai của A-rách; và Giô-ha-nan, con trai nó, đã cưới con gái của Mết-đu-lam, con trai của Bê-réc-ki-a.'),
(12421, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 6, 19, 'OT', 'Họ cũng thuật lại trước mặt tôi những điều tốt lành của ông ta, và thuật lại những lời tôi nói với ông ta. Tô-bi-a đã gửi những bức thư để khiến tôi sợ hãi.'),
(12422, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 1, 'OT', 'Khi bức tường đã được xây xong, tôi đã dựng các cửa ra vào; các người giữ cửa, các người hát và các người Lê-vi đã được bổ nhiệm.'),
(12423, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 2, 'OT', 'Tôi đã giao cho Ha-na-ni, anh tôi, và Ha-na-nia, viên cai quản thành, trách nhiệm quản lý Giê-ru-sa-lem; vì người ấy thật trung tín và kính sợ Đức Chúa Trời hơn nhiều người.'),
(12424, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 3, 'OT', 'Tôi nói với họ: "Các cổng Giê-ru-sa-lem không được mở cho đến khi mặt trời lên cao; và khi họ đang canh giữ, hãy đóng các cửa lại, khóa chặt vào; và hãy bổ nhiệm những người canh gác trong dân cư Giê-ru-sa-lem, mỗi người tại chỗ canh giữ của mình, và mỗi người đối diện nhà mình."'),
(12425, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 4, 'OT', 'Thành phố thì rộng lớn, dân cư lại thưa thớt, và chưa có nhà nào được xây dựng.'),
(12426, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 5, 'OT', 'Thiên Chúa đã đặt vào lòng tôi ý định tập hợp các quý tộc, các quan chức và dân chúng để tra khảo gia phả; tôi bèn tìm được sách gia phả của những người đầu tiên đã trở về, và tìm thấy điều được chép trong đó,'),
(12427, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 6, 'OT', 'Đây là những người con của tỉnh, đã lên từ nơi lưu đày, là những người mà Nê-bu-cát-nết-xa, vua Ba-by-lôn, đã bắt đi lưu đày; họ đã trở về Giê-ru-sa-lem và Giu-đa, mỗi người về thành phố của mình.'),
(12428, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 7, 'OT', 'Những người đến cùng Xê-ru-báp-ben: Giê-sua, Nê-hê-mi, A-xa-ria, Ra-a-mi, Na-ha-ma-ni, Mạc-đô-chai, Bích-sơ-lan, Mịp-xa-rết, Bích-vai, Nê-hum, Ba-a-nah. Số người của dân Y-sơ-ra-ên là như thế này:'),
(12429, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 8, 'OT', 'Con cái của Pha-rốt, hai ngàn một trăm bảy mươi hai người.'),
(12430, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 9, 'OT', 'Con cái của Sê-phát-gia, ba trăm bảy mươi hai người.'),
(12431, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 10, 'OT', 'Con cái của A-ra, sáu trăm năm mươi hai người.'),
(12432, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 11, 'OT', 'Con cái của Pha-thát Mô-áp, thuộc dòng dõi của Giê-su và Giô-áp, là hai ngàn tám trăm mười tám người.'),
(12433, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 12, 'OT', 'Con cái Ê-lam: một ngàn hai trăm năm mươi bốn người.'),
(12434, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 13, 'OT', 'Con cái của Xát-tu, tám trăm bốn mươi lăm người.'),
(12435, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 14, 'OT', 'Con cái của Xác-cai: bảy trăm sáu mươi người.'),
(12436, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 15, 'OT', 'Con cái của Bin-nui, sáu trăm bốn mươi tám người.'),
(12437, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 16, 'OT', 'Con cái của Bê-bai: sáu trăm hai mươi tám người.'),
(12438, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 17, 'OT', 'Con cháu của A-xgát: hai ngàn ba trăm hai mươi hai người.'),
(12439, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 18, 'OT', 'Con cái của A-đô-ni-cam, sáu trăm sáu mươi bảy người.'),
(12440, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 19, 'OT', 'Con cái của Bích-vai, hai ngàn sáu mươi bảy người.'),
(12441, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 20, 'OT', 'Con cái của A-đin: sáu trăm năm mươi lăm người.'),
(12442, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 21, 'OT', 'Con cái của A-tẹc thuộc về Hít-ki-a, chín mươi tám người.'),
(12443, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 22, 'OT', 'Con cái của Ha-sum, ba trăm hai mươi tám người.'),
(12444, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 23, 'OT', 'Con cái của Bê-zai, ba trăm hai mươi tư người.'),
(12445, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 24, 'OT', 'Con cái của Ha-ríp, một trăm mười hai người.'),
(12446, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 25, 'OT', 'Con cái Ghi-bê-ôn, chín mươi lăm người.'),
(12447, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 26, 'OT', 'Các người của Bết-lê-hem và Nết-ô-phah: một trăm tám mươi tám người.'),
(12448, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 27, 'OT', 'Người của A-na-thốt, một trăm hai mươi tám người.'),
(12449, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 28, 'OT', 'Người của Bết-át-ma-vết, bốn mươi hai người.'),
(12450, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 29, 'OT', 'Người của Kir-iath-ye-a-rim, Kê-phi-ra và Bê-e-rot: bảy trăm bốn mươi ba người.'),
(12451, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 30, 'OT', 'Những người của Ra-ma và Ga-ba: sáu trăm hai mươi mốt người.'),
(12452, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 31, 'OT', 'Những người từ Mích-ma, một trăm hai mươi hai người.'),
(12453, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 32, 'OT', 'Người của Bê-thên và Ai là một trăm hai mươi ba người.'),
(12454, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 33, 'OT', 'Các người đàn ông của Nê-bô khác, năm mươi hai người.'),
(12455, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 34, 'OT', 'Con cái của Ê-lam khác, một ngàn hai trăm năm mươi bốn người.'),
(12456, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 35, 'OT', 'Con cái của Ha-rim, ba trăm hai mươi người.'),
(12457, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 36, 'OT', 'Con cái của Giê-ri-hô, ba trăm bốn mươi lăm người.'),
(12458, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 37, 'OT', 'Con cái của Lót: Ha-đít và Ô-nô, bảy trăm hai mươi mốt người.'),
(12459, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 38, 'OT', 'Con cái của Sê-na-a, ba ngàn chín trăm ba mươi người.'),
(12460, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 39, 'OT', 'Các thầy tế lễ, con cháu của Y-đa-i-a, thuộc nhà Giê-sua, là chín trăm bảy mươi ba người.'),
(12461, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 40, 'OT', 'Con cháu của Im-mẹc, một ngàn năm mươi hai người.'),
(12462, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 41, 'OT', 'Con cái của Pha-xhur: một ngàn hai trăm bốn mươi bảy người.'),
(12463, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 42, 'OT', 'Con cháu của Ha-rim: một ngàn mười bảy người.'),
(12464, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 43, 'OT', 'Các người Lê-vi: con cháu của Giê-su, thuộc về dòng họ của Ca-đmi-ên, con cháu của Hô-đe-va, bảy mươi tư người.'),
(12465, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 44, 'OT', 'Những người hát xướng: con cháu của A-sáp, một trăm bốn mươi tám người.'),
(12466, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 45, 'OT', 'Các người giữ cửa là con cháu của Sa-lum, con cháu của A-ter, con cháu của Tal-môn, con cháu của Ác-cúp, con cháu của Ha-ti-ta, con cháu của Sô-bai, tất cả một trăm ba mươi tám người.'),
(12467, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 46, 'OT', 'Các người Nê-thi-nim, con cái của Xi-ha, con cái của Ha-xu-pha, con cái của Táp-bao-th.'),
(12468, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 47, 'OT', 'Con cái của Kê-rốt, con cái của Si-ách, con cái của Pa-đôn,'),
(12469, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 48, 'OT', 'Con cái của Lê-ba-na, con cái của Ha-ga-ba, con cái của Sách-mai.'),
(12470, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 49, 'OT', 'Con cái của Ha-nan, con cái của Gít-đen, con cái của Ga-ha.'),
(12471, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 50, 'OT', 'Con cháu của Rê-a-hia, con cháu của Rê-xin, con cháu của Nê-cô-đa,'),
(12472, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 51, 'OT', 'Con cái của Gát-xam, con cái của Út-xa, con cái của Pha-xê-ách.'),
(12473, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 52, 'OT', 'Con cái của Bê-sai, con cái của Mê-u-nim, con cái của Nê-phi-sê-sim.'),
(12474, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 53, 'OT', 'Con cái của Bác-búc, con cái của Ha-cu-pha, con cái của Ha-hu-rơ.'),
(12475, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 54, 'OT', 'Con cái của Baz-lít, con cái của Mê-hi-da, con cái của Ha-rê-sa.'),
(12476, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 55, 'OT', 'Con cái của Bar-côs, con cái của Xi-xê-ra, con cái của Ta-mách.'),
(12477, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 56, 'OT', 'Con cái của Nết-xi-ách, con cái của Ha-típ-ha.'),
(12478, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 57, 'OT', 'Con cái của các đầy tớ Sa-lô-môn: con cái Xô-tai, con cái Xô-phê-rết, con cái Phê-ri-đa.'),
(12479, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 58, 'OT', 'Con cái của Gia-la, con cái của Đa-rông, con cái của Ghít-đen,'),
(12480, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 59, 'OT', 'Con cái của Sê-phát-gia, con cái của Ha-til, con cái của Phô-ke-rết Xê-bai-im, con cái của A-môn.'),
(12481, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 60, 'OT', 'Tất cả những người Nê-thi-nim và con cháu của các đầy tớ Sa-lô-môn là ba trăm chín mươi hai người.'),
(12482, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 61, 'OT', 'Và đây là những người lên từ Tel-Mê-la, Tel-Ha-sa, Kê-ru-ub, A-đôn và Y-mê; họ không thể chỉ rõ được nhà của tổ tiên mình và dòng dõi mình, không biết họ có phải là người Y-sơ-ra-ên hay không.'),
(12483, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 62, 'OT', 'Con cái của Đê-la-i-a, con cái của Tô-bi-a, con cái của Nê-cô-đa, sáu trăm bốn mươi hai người.'),
(12484, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 63, 'OT', 'Về các thầy tế lễ: con cháu của Hô-bai-a, con cháu của Kốt, con cháu của Ba-rích-lai, người đã lấy một người con gái của Ba-rích-lai người Ghi-lê-át làm vợ và được gọi theo tên họ.'),
(12485, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 64, 'OT', 'Những người nầy đã tìm giấy chứng gia phả của mình, nhưng không tìm thấy; nên họ bị loại khỏi chức thầy tế lễ như những người bị ô uế.'),
(12486, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 65, 'OT', 'Vị Thi-rơ-sa-tha nói cùng họ rằng họ không được ăn các vật thánh nhất cho đến khi có thầy tế lễ đứng lên dùng U-rim và Thu-mim.'),
(12487, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 66, 'OT', 'Toàn thể hội chúng hiệp lại làm một là bốn mươi hai ngàn ba trăm sáu mươi người.'),
(12488, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 67, 'OT', 'Ngoài các đầy tớ trai và đầy tớ gái của họ, gồm bảy ngàn ba trăm ba mươi bảy người; và họ có hai trăm bốn mươi lăm người nam và người nữ hát xướng.'),
(12489, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 68, 'OT', 'Ngựa của họ: bảy trăm ba mươi sáu; lừa la của họ: hai trăm bốn mươi lăm.'),
(12490, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 69, 'OT', 'Lạc đà: bốn trăm ba mươi lăm con; lừa: sáu ngàn bảy trăm hai mươi con.'),
(12491, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 70, 'OT', 'Một số thủ lĩnh các gia tộc đã dâng cho công việc xây dựng. Ông Trấn thủ dâng vào kho bạc một ngàn đồng vàng Đác-môn, năm mươi cái chậu, và ba mươi lăm bộ áo xống cho các thầy tế lễ.'),
(12492, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 71, 'OT', 'Một số thủ lĩnh các gia tộc đã dâng cho kho tàng công việc hai mươi ngàn đarêcmon vàng và hai ngàn hai trăm mina bạc.'),
(12493, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 72, 'OT', 'Số còn lại của dân chúng dâng gồm hai mươi ngàn đồng đar-rơ-cơ-môn vàng, hai ngàn minh bạc, và sáu mươi bảy áo thầy tế lễ.'),
(12494, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 7, 73, 'OT', 'Các thầy tế lễ, các thầy Lê-vi, các người giữ cửa, các ca sĩ, một số dân chúng, các Nê-thi-nim và toàn thể Y-sơ-ra-ên đều ở trong các thành của mình. Khi tháng bảy đến, con cháu Y-sơ-ra-ên đã ở trong các thành của họ.'),
(12495, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 8, 1, 'OT', 'Và toàn thể dân chúng nhóm lại như một người vào khu vực trước cổng Nước; họ nói với Ê-xơ-ra người thầy thông thái rằng hãy mang đến sách luật pháp của Môi-se, mà Đức Giê-hô-va đã truyền cho Ít-ra-en.'),
(12496, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 8, 2, 'OT', 'Ê-xơ-ra, thầy tế lễ, mang luật pháp đến trước hội chúng, từ người nam cho đến người nữ, và tất cả những người có thể hiểu mà nghe được, vào ngày đầu tháng bảy.'),
(12497, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 8, 3, 'OT', 'Và người đọc trong đó trước mặt quảng trường ở trước cổng Nước, từ lúc rạng đông cho đến giữa trưa, trước mặt những người đàn ông, đàn bà và những người hiểu biết; và tai của toàn thể dân chúng chăm chú vào sách Luật.'),
(12498, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 8, 4, 'OT', 'Ê-xơ-ra người thầy thông thái đứng trên bục bằng gỗ mà người ta đã làm cho mục đích ấy; bên cạnh ông đứng Mát-ti-thia, Sêma, A-na-ia, U-ri-a, Hinh-kia và Ma-a-sê-gia bên tay phải ông; còn bên tay trái ông thì có Pêdaya, Mi-sa-ên, Manh-ki-gia, Ha-sum, Hách-ba-đa-na, Xa-cha-ri và Mê-su-lam.'),
(12499, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 8, 5, 'OT', 'Ê-xơ-ra mở sách trước mặt toàn thể dân chúng, vì người đứng cao hơn toàn thể dân chúng; và khi người mở sách ra, thì toàn thể dân chúng đứng dậy.'),
(12500, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 8, 6, 'OT', 'Và Ê-xơ-ra chúc tụng Đức Giê-hô-va, Đức Chúa Trời lớn lao. Toàn thể dân chúng đáp lại: "A-men, A-men!" đồng thời giơ tay lên; rồi cúi đầu xuống đất mà thờ lạy Đức Giê-hô-va.'),
(12501, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 8, 7, 'OT', 'Và Giê-su, Ba-ni, Sê-rê-bia, Gia-min, A-cúc, Sáp-bê-thai, Hô-đi-gia, Ma-a-xe-ia, Kê-li-ta, A-xa-ria, Giô-xa-bát, Ha-nan, Phê-lai-a, và các thầy Lê-vi, giúp cho dân hiểu luật pháp; và dân đứng tại chỗ của mình.'),
(12502, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 8, 8, 'OT', 'Họ đọc trong sách luật pháp của Đức Chúa Trời cách rõ ràng, giải nghĩa và làm cho người ta hiểu được phần đọc.'),
(12503, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 8, 9, 'OT', 'Và Nê-hê-mi, người là Thir-sa-tha, cùng với Ê-xơ-ra thầy tế lễ người chuyên chép Kinh, và những người Lê-vi hiểu biết dân sự, nói với toàn thể dân sự rằng: "Ngày nay là thánh dành cho Đức Giê-hô-va Đức Chúa Trời các ngươi; chớ khóc lóc, cũng đừng than van." Vì toàn thể dân sự đều khóc khi nghe các lời dạy của Luật Pháp.'),
(12504, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 8, 10, 'OT', 'Rồi ông nói với họ: "Hãy đi, hãy ăn những món béo tốt, uống những thứ ngon ngọt, và gửi phần cho những người không có gì sắm sửa; vì ngày nay là thánh dành cho Chúa-chúng-ta; đừng buồn rầu, vì niềm vui của Đức Giê-hô-va là sức lực các ngươi."'),
(12505, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 8, 11, 'OT', 'Các thầy Lê-vi làm cho toàn thể dân chúng yên lặng, nói rằng: "Hãy im lặng, vì hôm nay là ngày thánh; và đừng buồn bã."'),
(12506, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 8, 12, 'OT', 'Và toàn thể dân chúng đi về để ăn uống, gửi phần cho nhau, và bày tỏ niềm vui lớn, vì họ đã hiểu những lời mà người ta đã giảng dạy cho họ.'),
(12507, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 8, 13, 'OT', 'Vào ngày thứ hai, các tộc trưởng của mọi người, các thầy tế lễ và người Lê-vi, đều được tập họp lại cùng Ê-xơ-ra người văn sĩ, để tìm hiểu các lời luật pháp.'),
(12508, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 8, 14, 'OT', 'Họ tìm thấy trong luật pháp, mà Đức Giê-hô-va đã truyền dạy bởi tay Môi-se, rằng con cái Ít-ra-en phải ở trong các lều trong dịp lễ hội tháng thứ bảy:'),
(12509, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 8, 15, 'OT', 'Hãy thông báo và loan truyền trong tất cả các thành của các ngươi và tại Giê-ru-sa-lem rằng: "Hãy đi ra núi, mang về các cành ô liu, các cành cây dầu, các cành hắc đán, các cành thùy liễu, và các cành cây rậm lá, để làm những lều, như điều đã chép."'),
(12510, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 8, 16, 'OT', 'Dân chúng ra đi, mang cây về và dựng lều cho mình, mỗi người trên mái nhà mình, trong các sân nhà họ, trong các sân đền thờ Đức Chúa Trời, tại quảng trường cổng Nước và tại quảng trường cổng Ép-ra-im.'),
(12511, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 8, 17, 'OT', 'Cả hội chúng trở về từ nơi bị lưu đày đều làm lều và ngồi trong các lều; vì từ những ngày của Giô-suê, con trai của Nun, đến ngày ấy, dân Y-sơ-ra-ên chưa từng làm như vậy. Và niềm vui mừng trở nên rất lớn.'),
(12512, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 8, 18, 'OT', 'Hằng ngày, từ ngày đầu cho đến ngày cuối cùng, người ta đọc trong sách luật pháp của Đức Chúa Trời. Họ giữ lễ trong bảy ngày; và ngày thứ tám là ngày hội họp trang nghiêm, theo đúng quy định.'),
(12513, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 1, 'OT', 'Vào ngày hai mươi bốn tháng này, dân Y-sơ-ra-ên nhóm lại với nhau ăn chay, mặc áo bằng bao gai, và bụi đất trên đầu họ.'),
(12514, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 2, 'OT', 'Dòng dõi Y-sơ-ra-ên tách ra khỏi mọi con cái người ngoại bang, rồi đứng dậy và thú nhận các tội lỗi mình cùng những điều gian ác mà tổ tiên họ đã phạm.'),
(12515, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 3, 'OT', 'Họ đứng tại chỗ mình, rồi đọc trong sách luật pháp của Đức Giê-hô-va Đức Chúa Trời họ một phần tư ngày, và một phần tư ngày họ xưng tội và thờ lạy Đức Giê-hô-va Đức Chúa Trời họ.'),
(12516, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 4, 'OT', 'Các thầy Lê-vi là Giê-sua, Ba-ni, Ca-đơ-mi-ên, Sê-ba-nia, Bun-ni, Sê-rê-bia, Ba-ni và Kên-ni, đứng trên các bậc cao mà kêu lớn cùng Đức Giê-hô-va Đức Chúa Trời của họ.'),
(12517, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 5, 'OT', 'Các thầy Lê-vi, gồm Giê-su, Ca-đmi-ên, các con trai của Ha-sáp-ni-a, Sê-rê-bia, Hô-đi-gia, Sê-ba-nia và Phê-ta-hi-a, nói rằng: "Hãy đứng dậy, chúc phước cho Đức Giê-hô-va Đức Chúa Trời các ngươi từ đời đời cho đến đời đời. Nguyện danh hiệu vinh hiển của Ngài được chúc phước và được tôn cao trên mọi lời chúc phước và lời ngợi khen."'),
(12518, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 6, 'OT', 'Chính Ngài là Đức Giê-hô-va, một mình Ngài; chính Ngài đã làm ra các từng trời, các trời của các từng trời, cùng toàn thể đạo binh chúng nó, đất và mọi vật trên đó, các biển và mọi vật ở trong đó; và chính Ngài làm cho mọi vật được sống; còn đạo binh các từng trời thì thờ lạy Ngài.'),
(12519, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 7, 'OT', 'Chính Ngài là Đức Giê-hô-va Đức Chúa Trời, Đấng đã chọn Áp-ram, dẫn người ra khỏi thành Úc của người Can-đê, và đặt tên người là Áp-ra-ham.'),
(12520, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 8, 'OT', 'Và Ngài thấy lòng người trung tín trước mặt Ngài, nên lập giao ước với người để ban đất của người Ca-na-an, người Hê-tít, người A-mô-rít, người Phê-ri-sít, người Giê-bu-sít và người Ghích-ga-sít, mà ban cho dòng dõi người; và Ngài đã thực hiện lời Ngài, vì Ngài là Đấng công bình.'),
(12521, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 9, 'OT', 'Chúa đã thấy sự khốn khổ của tổ tiên chúng tôi tại Ai Cập, và đã nghe tiếng kêu cứu của họ bên bờ Biển Đỏ.'),
(12522, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 10, 'OT', 'Ngài đã làm những điềm và phép lạ nơi Pha-ra-ôn, nơi tất cả các tôi tớ ông và nơi toàn dân đất nước ông, vì Ngài biết rằng họ kiêu ngạo đối với họ; và Ngài đã làm cho Ngài một danh tiếng như ngày nay.'),
(12523, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 11, 'OT', 'Ngài đã rẽ biển trước mặt họ, và họ đi qua giữa biển trên đất khô; còn những kẻ đuổi theo họ thì Ngài quăng xuống vực sâu, như đá chìm giữa nước mạnh.'),
(12524, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 12, 'OT', 'Ngài dẫn họ ban ngày bằng trụ mây, và ban đêm bằng trụ lửa để soi sáng con đường họ phải đi.'),
(12525, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 13, 'OT', 'Ngài đã ngự xuống trên núi Xi-nai, phán cùng họ từ trời, và ban cho họ những điều luật công chính, những luật lệ chân thật, những quy định và mệnh lệnh tốt lành.'),
(12526, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 14, 'OT', 'Và Ngài đã cho họ biết ngày Sa-bát thánh của Ngài, và truyền cho họ các điều răn, luật lệ và giáo lý nhân danh Môi-se, tôi tớ Ngài.'),
(12527, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 15, 'OT', 'Ngài đã ban cho họ bánh từ trời để thỏa cơn đói, và cho họ nước chảy ra từ vách đá để thỏa cơn khát; Ngài cũng dặn họ phải vào để chiếm lấy đất mà Ngài đã giơ tay hứa ban cho họ.'),
(12528, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 16, 'OT', 'Nhưng họ và tổ tiên chúng tôi đã kiêu ngạo, làm cứng cổ mình, và không nghe theo các điều răn của Ngài.'),
(12529, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 17, 'OT', 'Họ từ chối vâng lời, chẳng nhớ các việc kỳ diệu Ngài đã làm giữa họ; họ cứng cổ mình, nổi loạn và muốn đặt một người lãnh đạo để trở về kiếp nô lệ; nhưng Ngài là Đức Chúa Trời hay tha thứ, đầy ân sủng và lòng thương xót, chậm giận, rất nhân từ, và chẳng lìa bỏ họ.'),
(12530, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 18, 'OT', 'Dầu vậy, họ đã làm cho mình một con bò con đúc bằng kim loại, và nói: "Đây là thần của ngươi, hỡi Ích-la, Đấng đã đưa ngươi lên khỏi Ai-cập"; và họ đã làm những điều gớm ghiếc lớn lao.'),
(12531, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 19, 'OT', 'Nhưng Ngài, vì những lòng thương xót rất lớn của Ngài, đã không bỏ họ trong đồng vắng; trụ mây không rời khỏi họ ban ngày để dẫn họ trên đường đi, và trụ lửa ban đêm cũng không rời khỏi họ để soi sáng cho họ và chỉ cho họ con đường phải đi.'),
(12532, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 20, 'OT', 'Ngươi đã ban cho họ Thần tốt lành của Ngài để dạy dỗ họ, không từ chối bánh manna khỏi miệng họ, và ban cho họ nước để thỏa cơn khát.'),
(12533, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 21, 'OT', 'Đức Giê-hô-va nuôi dưỡng họ trong đồng vắng bốn mươi năm, họ chẳng thiếu thốn gì; áo xống của họ không cũ rách, và chân họ không sưng phù.'),
(12534, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 22, 'OT', 'Ngươi đã ban cho họ các vương quốc và các dân tộc, và chia cắt họ đến tận cùng đất; họ đã chiếm lấy đất của Si-hôn, và đất của vua Hết-bôn, và đất của Oùc, vua Ba-san.'),
(12535, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 23, 'OT', 'Con cái của chúng, Ngài làm cho đông đảo như những ngôi sao trên trời, và Ngài dẫn chúng vào đất đai mà Ngài đã hứa cùng tổ phụ chúng rằng chúng sẽ vào để chiếm hữu.'),
(12536, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 24, 'OT', 'Các con cái vào và chiếm hữu đất ấy; Ngài đã khuất phục trước mặt chúng các dân cư đất ấy, là người Ca-na-an, và trao họ, cùng các vua và dân sự của đất ấy, vào tay con cái để chúng làm điều mình muốn với họ.'),
(12537, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 25, 'OT', 'Họ chiếm các thành kiên cố và vùng đất phì nhiêu, được hưởng những ngôi nhà đầy đủ mọi điều tốt lành, những giếng đã được đào, những vườn nho, vườn ô-liu và cây trái ăn được rất nhiều; họ ăn no nê, trở nên mập mạp và hưởng lạc trong sự tốt lành lớn lao của Ngài.'),
(12538, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 26, 'OT', 'Họ đã chống cãi và nổi loạn cùng Ngài, quăng luật lệ Ngài ra phía sau lưng, giết các đấng tiên tri của Ngài là những người đã làm chứng cùng họ để họ trở lại cùng Ngài, và họ đã làm những điều xúc phạm lớn lao.'),
(12539, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 27, 'OT', 'Vì vậy, Ngài đã phó họ vào tay các kẻ thù nghịch, và chúng làm khổ họ. Nhưng khi họ gặp hoạn nạn, họ kêu lên cùng Ngài, thì Ngài từ trên trời nghe thấy; và theo những sự thương xót lớn lao của Ngài, Ngài ban cho họ những người giải cứu, và họ được cứu khỏi tay các kẻ thù nghịch mình.'),
(12540, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 28, 'OT', 'Khi họ được yên ổn, họ lại làm điều ác trước mặt Ngài; nên Ngài bỏ mặc họ vào tay kẻ thù, khiến chúng thống trị họ. Nhưng khi họ trở lại và kêu lên cùng Ngài, thì Ngài từ các từng trời đã nghe và nhiều lần giải cứu họ theo lòng thương xót lớn lao của Ngài.'),
(12541, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 29, 'OT', 'Ngươi đã làm chứng chống lại họ, để dẫn họ trở lại luật lệ của Ngài; nhưng họ lại kiêu ngạo, không vâng theo các điều răn của Ngài, phạm tội nghịch các mạng lịnh của Ngài—điều mà nếu người nào làm theo, sẽ nhờ đó mà sống—họ trơ vai cứng cỏi, cổ cứng nhắc, và không chịu nghe.'),
(12542, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 30, 'OT', 'Ngài đã khoan dung cho họ nhiều năm, và lấy Đức Thánh Linh Ngài mà cảnh cáo họ qua các đấng tiên tri của Ngài, nhưng họ không chịu lắng nghe; vì vậy, Ngài đã trao họ vào tay các dân tộc trong các vùng đất.'),
(12543, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 31, 'OT', 'Tuy nhiên, vì những lòng thương xót lớn lao của Ngài, Ngài đã không tiêu diệt họ hoàn toàn, cũng không từ bỏ họ; vì Ngài là Đức Chúa Trời đầy ơn và lòng thương xót.'),
(12544, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 32, 'OT', 'Bây giờ, hỡi Đức Chúa Trời của chúng tôi, Đức Chúa Trời lớn, mạnh mẽ và đáng kính sợ, Đấng giữ giao ước và sự nhân từ, xin đừng coi nhẹ trước mặt Ngài mọi nỗi khốn khổ đã giáng trên chúng tôi, trên các vua chúng tôi, các quan trưởng, các thầy tế lễ, các nhà tiên tri, tổ tiên chúng tôi và toàn thể dân Ngài, từ thời các vua Ách-siếc cho đến ngày nay.'),
(12545, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 33, 'OT', 'Nhưng Ngài là Đấng công bình về mọi điều xảy đến với chúng tôi; vì Ngài đã làm điều phải, còn chúng tôi thì đã phạm tội ác.'),
(12546, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 34, 'OT', 'Các vua, các quan trưởng, các thầy tế lễ và tổ tiên của chúng tôi đã không tuân giữ luật lệ Ngài, cũng chẳng chịu lắng nghe các điều răn và các lời chứng mà Ngài đã dùng để cảnh cáo họ.'),
(12547, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 35, 'OT', 'Họ đã không phục vụ Ngài trong vương quốc của họ, và trong sự nhân từ lớn mà Ngài đã ban cho họ, và trong đất rộng lớn, béo tốt mà Ngài đã ban cho họ, họ cũng không từ bỏ những việc ác của mình.'),
(12548, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 36, 'OT', 'Kìa, ngày nay chúng tôi là tôi tớ; còn đất mà Ngài đã ban cho tổ tiên chúng tôi để hưởng hoa quả và điều tốt lành của nó, thì nay chúng tôi là tôi tớ trên đất ấy.'),
(12549, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 37, 'OT', 'Các sản vật của nó đem lại lợi nhuận dồi dào cho các vua mà Ngài đã đặt cai trị chúng tôi vì những tội lỗi của chúng tôi; và họ thống trị trên thân thể chúng tôi và trên súc vật của chúng tôi theo ý muốn mình; và chúng tôi đang ở trong cơn khốn khổ lớn.'),
(12550, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 9, 38, 'OT', 'Vì mọi điều nầy, chúng tôi lập một giao ước chắc chắn, viết ra, và các lãnh đạo, người Lê-vi, thầy tế lễ của chúng tôi đều ký tên đóng ấn.'),
(12551, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 1, 'OT', 'Và những người đã ký tên là: Nê-hê-mi, tổng trấn, con trai của Ha-ca-lia, và Xi-đê-ki-a.'),
(12552, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 2, 'OT', 'Xê-rai-ah, A-xa-ri-ah, Giê-rê-mi-ah,'),
(12553, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 3, 'OT', 'Pha-sê-hu, A-ma-ri-a, Ma-lê-ki-a,'),
(12554, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 4, 'OT', 'Hát-túch, Sê-ba-nia, Ma-lúc,'),
(12555, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 5, 'OT', 'Ha-rim, Mê-rê-mốt, Ô-ba-đi-a,'),
(12556, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 6, 'OT', 'Đa-ni-ên, Gin-nê-thôn, Ba-rúc,'),
(12557, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 7, 'OT', 'Mê-su-lam, A-bi-gia, Mi-ya-min,'),
(12558, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 8, 'OT', 'Ma-a-xi-a, Binh-gai, Sê-ma-gia; những người nầy là các thầy tế lễ.'),
(12559, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 9, 'OT', 'Còn các người Lê-vi: có Giê-sua, con trai của A-xa-nia; Bin-nui, thuộc con cháu của Hê-na-đát; và Ca-đmi-ên.'),
(12560, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 10, 'OT', 'Và các anh em của họ: Sê-ba-nia, Hô-đi-a, Kê-li-ta, Phê-lai-a, Ha-nan,'),
(12561, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 11, 'OT', 'Mích-gia, Rê-hốp, Ha-sa-bia,'),
(12562, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 12, 'OT', 'Xác-cúc, Sê-rê-bia, Sê-ba-nia,'),
(12563, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 13, 'OT', 'Hô-đi-ya, Ba-ni, Bê-ni-nu.'),
(12564, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 14, 'OT', 'Các thủ lãnh của dân sự: Pa-rốt, Pha-hát Mô-áp, Ê-lam, Zát-tu, và Ba-ni.'),
(12565, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 15, 'OT', 'Bun-ni, A-xgát, Bê-bai,'),
(12566, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 16, 'OT', 'A-đô-ni-a, Bích-gay, A-đin,'),
(12567, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 17, 'OT', 'A-ter, Hi-xki-a, A-xu-r,'),
(12568, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 18, 'OT', 'Hô-đi-ya, Ha-shum, Bê-zai,'),
(12569, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 19, 'OT', 'Ha-ríp, A-na-thốt, Nê-bai,'),
(12570, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 20, 'OT', 'Mag-pi-ách, Mê-su-lam, Hê-xích,'),
(12571, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 21, 'OT', 'Mê-sê-xa-bên, Xa-đốc, Gia-đu-a,'),
(12572, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 22, 'OT', 'Phê-lat-ia, Ha-nan, A-na-ia,'),
(12573, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 23, 'OT', 'Hô-sê-a, Ha-na-nia, Ha-súp.'),
(12574, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 24, 'OT', 'Ha-lô-hết, Pi-lê-ha, và Sô-béc.'),
(12575, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 25, 'OT', 'Rê-hum, Ha-sách-ba-nah, Ma-a-xe-gia.'),
(12576, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 26, 'OT', 'A-hi-gia, Ha-nan, A-nan,'),
(12577, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 27, 'OT', 'Man-lúc, Ha-rim, và Ba-a-nah.'),
(12578, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 28, 'OT', 'Còn lại những người dân, các thầy tế lễ, người Lê-vi, kẻ canh giữ cửa, người hát xướng, người Nê-thi-nim, và mọi người đã tách mình ra khỏi các dân trong các xứ để theo luật pháp của Đức Chúa Trời, cùng các vợ mình, con trai và con gái mình, mọi người có tri thức và hiểu biết;'),
(12579, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 29, 'OT', 'Họ gắn bó với anh em mình, những người quý tộc của họ, và vào giao ước với lời thề, để bước đi theo luật pháp của Đức Chúa Trời, là luật pháp đã được ban cho qua tay Môi-se, tôi tớ của Đức Chúa Trời, và để giữ và thực hành mọi điều răn của Đức Giê-hô-va Đức Chúa chúng ta, cùng các án lệ và các luật lệ của Ngài.'),
(12580, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 30, 'OT', 'và không gả con gái chúng tôi cho dân của đất, cũng không cưới con gái họ cho con trai chúng tôi.'),
(12581, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 31, 'OT', 'Chúng tôi sẽ không mua hàng hóa hay bất cứ thứ gì từ dân xứ vào ngày Sa-bát hoặc ngày thánh; và chúng tôi sẽ miễn trừ việc thu thuế trong năm thứ bảy, cũng như mọi khoản nợ nần.'),
(12582, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 32, 'OT', 'Chúng tôi đã tự đặt ra các điều quy định cho mình, để mỗi năm đóng một phần ba siếc-ken cho công việc nhà Đức Chúa Trời của chúng tôi.'),
(12583, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 33, 'OT', 'Về bánh trần, về lễ vật chay hằng định, về của lễ thiêu hằng định, về các ngày Sa-bát, các ngày trăng mới, các kỳ lễ hội, về các vật thánh, về các của lễ chuộc tội để làm lễ chuộc cho Y-sơ-ra-ên, và về mọi công việc trong nhà Đức Chúa Trời chúng ta.'),
(12584, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 34, 'OT', 'Chúng tôi đã bắt thăm giữa các thầy tế lễ, người Lê-vi và dân chúng về phần đóng góp củi, để mang vào nhà Đức Chúa Trời của chúng tôi, theo các gia đình tổ tiên chúng tôi, vào những kỳ đã định hằng năm, để nhóm trên bàn thờ Đức Giê-hô-va Đức Chúa Trời của chúng tôi, như đã chép trong luật pháp.'),
(12585, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 35, 'OT', 'Đem các sản vật đầu mùa của đất chúng ta và các sản vật đầu mùa của mọi thứ trái cây mỗi loại cây mỗi năm, dâng vào nhà Đức Giê-hô-va.'),
(12586, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 36, 'OT', 'Cũng vậy, chúng tôi dâng các con đầu lòng của chúng tôi và súc vật của chúng tôi, y như điều đã chép trong luật pháp, và các đầu lòng của bò và chiên của chúng tôi, để mang đến nhà Đức Chúa Trời chúng tôi, cho các thầy tế lễ phục sự trong nhà Đức Chúa Trời chúng tôi.'),
(12587, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 37, 'OT', 'Chúng tôi sẽ mang phần đầu mùa của bột mì chúng tôi, các lễ vật dâng riêng của chúng tôi, và trái của mọi thứ cây, rượu và dầu, đến cho các thầy tế lễ, vào các buồng trong nhà Đức Chúa Trời của chúng tôi; còn phần mười sản vật đất đai chúng tôi thì dành cho người Lê-vi; chính những người Lê-vi ấy thu phần mười ở mọi thành thuộc vùng canh tác của chúng tôi.'),
(12588, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 38, 'OT', 'Các thầy tế lễ là con cháu A-ha-ron sẽ cùng các người Lê-vi khi các người Lê-vi thu lấy phần mười; và các người Lê-vi phải đem phần mười của phần mười đó đến nhà Đức Chúa Trời chúng ta, để vào các buồng tại nhà kho tàng.'),
(12589, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 10, 39, 'OT', 'Vì con cái Y-sơ-ra-ên và con cái Lê-vi sẽ mang các lễ vật về ngũ cốc, rượu mới và dầu vào các phòng kho; tại đó có các khí cụ của nơi thánh, các thầy tế lễ phục vụ, các kẻ giữ cửa và các người ca xướng; và chúng tôi sẽ không bỏ nhà của Đức Chúa Trời chúng tôi.'),
(12590, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 1, 'OT', 'Các quan cai trị dân sự sống tại Giê-ru-sa-lem; phần còn lại của dân chúng thì bắt thăm, để chọn một phần mười đến ở Giê-ru-sa-lem, thành thánh, và chín phần còn lại ở các thành khác.'),
(12591, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 2, 'OT', 'Dân chúng chúc phước cho mọi người, là những người tự nguyện dâng mình để ở lại Giê-ru-sa-lem.'),
(12592, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 3, 'OT', 'Và đây là những người lãnh đạo tỉnh, những người ở tại Giê-ru-sa-lem; còn tại các thành của Giu-đa, mỗi người ở trên phần đất của mình, trong các thành của họ, gồm dân Y-sơ-ra-ên, các thầy tế lễ, các người Lê-vi, những người Nê-ti-nim, và con cháu các đầy tớ của Sa-lô-môn.'),
(12593, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 4, 'OT', 'Tại Giê-ru-sa-lem, có một số người thuộc con cháu Giu-đa và con cháu Bên-gia-min cư ngụ. Thuộc con cháu Giu-đa có A-thai-ah, con trai của Út-xi-a, con trai của Xe-cha-ri-a, con trai của A-ma-ri-a, con trai của Sê-pha-ti-a, con trai của Ma-ha-la-lên, thuộc dòng dõi Pha-rết.'),
(12594, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 5, 'OT', 'Và Ma-a-xe-gia, con trai của Ba-rúc, con trai của Can-hô-xe, con trai của Ha-xa-ia, con trai của A-đai-a, con trai của Giô-i-a-ríp, con trai của Xa-cha-ri, con trai của Xi-lo-ni.'),
(12595, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 6, 'OT', 'Tất cả con trai của Pha-rết sống tại Giê-ru-sa-lem là bốn trăm sáu mươi tám người đàn ông dũng cảm.'),
(12596, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 7, 'OT', 'Và đây là các con trai của Bên-gia-min: Xan-lu, con trai của Mết-su-lam, con trai của Giô-éd, con trai của Phê-đai-gia, con trai của Cô-lai-gia, con trai của Ma-a-xe-gia, con trai của Ít-hi-ên, con trai của Giê-xa-gia.'),
(12597, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 8, 'OT', 'Và sau người là Gáp-bai, Sa-lai, chín trăm hai mươi tám người.'),
(12598, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 9, 'OT', 'Và Giô-ên, con trai của Xích-ri, thì quản lý các người ấy; còn Giu-đa, con trai của Sê-nu-a, thì làm thứ trưởng trong thành.'),
(12599, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 10, 'OT', 'Trong các thầy tế lễ: Giê-đa-i-ah, con trai của Giô-i-a-ríp, và Gia-kin.'),
(12600, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 11, 'OT', 'Xê-rai-ah, con trai của Hinh-kia, con trai của Mê-thu-lam, con trai của Xa-đốc, con trai của Mê-ra-i-ốt, con trai của A-hi-túp, là người đứng đầu nhà Đức Chúa Trời.'),
(12601, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 12, 'OT', 'Và anh em họ, những người làm công việc trong đền thờ, là tám trăm hai mươi hai người; và A-đai-a, con trai của Giê-rô-ham, con trai của Pê-la-lia, con trai của Am-xi, con trai của Xa-cha-ri, con trai của Pha-xhur, con trai của Man-ki-a.'),
(12602, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 13, 'OT', 'Và anh em người, các trưởng tộc, hai trăm bốn mươi hai người; và Am-xa-i, con trai của A-xa-rên, con trai của A-cha-xai, con trai của Mê-si-lê-mốt, con trai của I-mê-r.'),
(12603, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 14, 'OT', 'Và các anh em họ là những người dũng cảm, một trăm hai mươi tám người; và người quản lý họ là Xáp-đi-ên, con trai của Ha-ge-đô-lim.'),
(12604, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 15, 'OT', 'Và trong các người Lê-vi, có Sê-ma-gia, con trai của Ha-xúp, cháu trai của A-xri-cam, chắt của Ha-sa-bia, chít của Bun-ni.'),
(12605, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 16, 'OT', 'Sabbê-thai và Giô-xa-bát, thuộc các người lãnh đạo người Lê-vi, chịu trách nhiệm về các công việc bên ngoài của nhà Đức Chúa Trời.'),
(12606, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 17, 'OT', 'Và Mát-ta-nia, con trai của Mi-cha, con trai của Xáp-đi, con trai của A-sáp, người đứng đầu trong việc bắt đầu lời cầu nguyện và cảm tạ; và Bác-bu-ki-a, người thứ hai trong các anh em ông; và Áp-đa, con trai của Sam-mua, con trai của Ga-lal, con trai của Giê-đu-thun.'),
(12607, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 18, 'OT', 'Tất cả những người Lê-vi trong thành thánh là hai trăm tám mươi bốn người.'),
(12608, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 19, 'OT', 'Các người giữ cửa là A-kup, Ta-lôn và anh em họ giữ các cổng, tất cả là một trăm bảy mươi hai người.'),
(12609, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 20, 'OT', 'Phần còn lại của Y-sơ-ra-ên, các thầy tế lễ và người Lê-vi, ở trong mọi thành của Giu-đa, mỗi người trong sản nghiệp của mình.'),
(12610, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 21, 'OT', 'Các người Nê-ti-nim ở tại Ô-phên; Xi-ha và Gít-pha cai quản các người Nê-ti-nim.'),
(12611, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 22, 'OT', 'Người quản lý các thầy Lê-vi tại Giê-ru-sa-lem là Út-xi, con trai của Ba-ni, con trai của Ha-sa-bia, con trai của Ma-ta-nia, con trai của Mi-ka, thuộc các con trai của A-sáp, những người hát xướng, trông coi công việc của nhà Đức Chúa Trời.'),
(12612, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 23, 'OT', 'Vì có lệnh vua giao cho họ, và một phần bổng lộc nhất định được ấn định cho các ca sĩ mỗi ngày.'),
(12613, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 24, 'OT', 'Và Phê-ta-hi-a, con trai của Mê-sê-xa-bên, thuộc con cháu Sê-rách, con trai của Giu-đa, phục vụ bên cạnh vua trong mọi việc liên quan đến dân chúng.'),
(12614, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 25, 'OT', 'Và tại các làng mạc cùng các đồng ruộng của chúng, con cái của Giu-đa ở tại Kir-gia-tha Ha-rba và các làng mạc thuộc về nó, tại Đi-bôn và các làng mạc thuộc về nó, tại Giê-cap-xe-ên và các làng mạc thuộc về nó.'),
(12615, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 26, 'OT', 'Và ở Giê-su, và ở Mô-la-đa, và ở Bê-th Pha-lết,'),
(12616, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 27, 'OT', 'Và tại Ha-xa Sua, và tại Bê-e Sê-va, và các làng mạc thuộc về các nơi ấy,'),
(12617, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 28, 'OT', 'Và tại Xích-lách, và tại Mê-kô-nah, và tại các làng mạc thuộc về nó,'),
(12618, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 29, 'OT', 'Và tại Bê-tên Rim-môn, và tại Xa-rê-a, và tại Gia-mút.'),
(12619, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 30, 'OT', 'Za-nô-ách, A-đu-lam và các làng mạc của chúng, La-ki và các đồng ruộng của nó, A-xéch và các con cái của nó; họ đóng trại từ Bê-e-Sê-ba cho đến thung lũng Hin-nom.'),
(12620, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 31, 'OT', 'Con cái của Bên-gia-min, từ Ga-ba, ở tại Mích-mát, A-i, Bê-thên và các làng mạc của chúng.'),
(12621, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 32, 'OT', 'ở A-na-thốt, Nôp, A-na-ni-ah,'),
(12622, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 33, 'OT', 'Ha-xô, Ra-ma, Ghít-ta-im,'),
(12623, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 34, 'OT', 'Ha-đít, Xê-bô-im, Nê-ba-lát,'),
(12624, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 35, 'OT', 'Lô-đ và Ô-nô, thung lũng thợ thủ công.'),
(12625, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 11, 36, 'OT', 'Thuộc về người Lê-vi, có các ban được phân chia tại xứ Giu-đa và Bên-gia-min.'),
(12626, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 1, 'OT', 'Và đây là những thầy tế lễ và người Lêvi đã lên cùng Xê-ru-ba-bên, con trai của Sê-át-ti-ên, và Giê-sua: Xê-rai-ah, Giê-rê-mi, Ét-ra.'),
(12627, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 2, 'OT', 'A-ma-ri-a, Man-lúc, Hát-túc.'),
(12628, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 3, 'OT', 'Sê-can-gia, Rê-hum, Mê-rê-mốt,'),
(12629, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 4, 'OT', 'I-đô, Gin-né-thô, A-bi-gia.'),
(12630, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 5, 'OT', 'Ma-a-đi-a, Binh-ga.'),
(12631, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 6, 'OT', 'Sê-ma-gia, và Giô-i-a-ríp, Giê-đa-gia.'),
(12632, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 7, 'OT', 'Sa-lu, A-mốc, Hinh-kia, Giê-đa-i-a. Những người này là các thầy tế lễ trưởng và anh em của họ trong những ngày của Giê-sua.'),
(12633, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 8, 'OT', 'Các thầy Lê-vi: Giê-su, Bin-nui, Ca-đmi-ên, Sê-rê-bia, Giu-đa, Ma-ta-nia; người nầy và anh em người quản nhiệm việc tạ ơn.'),
(12634, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 9, 'OT', 'Bak-bu-ki-a và Un-ni, anh em của họ, đối diện với họ trong các ca canh.'),
(12635, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 10, 'OT', 'Và Giê-xua sinh ra Giô-i-akim, Giô-i-akim sinh ra Ê-li-a-síp, và Ê-li-a-síp sinh ra Giô-ia-đa.'),
(12636, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 11, 'OT', 'Và Giô-i-đa sinh ra Giô-na-than, và Giô-na-than sinh ra Gia-đu-a.'),
(12637, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 12, 'OT', 'Vào các ngày của Giô-gia-kim, các thầy tế lễ và các tổ trưởng là: về Sê-rai-ah, Mê-rai-ah; về Giê-rê-mi, Ha-na-nai-ah.'),
(12638, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 13, 'OT', 'Về Xô-ra, Mết-đu-lam; về A-ma-ri-a, Giê-hô-cha-nan;'),
(12639, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 14, 'OT', 'Thuộc về Mê-li-cu, là Giô-na-than; thuộc về Sê-ba-nia, là Giô-sép.'),
(12640, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 15, 'OT', 'Thuộc về Ha-rim, A-đna; thuộc về Mê-ra-i-ốt, Hên-kai.'),
(12641, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 16, 'OT', 'Của Ít-đô, là Xa-cha-ri; của Gin-nê-thôn, là Mê-xu-lam.'),
(12642, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 17, 'OT', 'A-bi-gia có Xích-ri; Min-ni-a-min có Mô-a-đia và Pít-tai.'),
(12643, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 18, 'OT', 'Bấy giờ, về dòng họ của Bích-ga, có Sam-mua; về dòng họ của Sê-ma-gia, có Giê-hô-nát-an.'),
(12644, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 19, 'OT', 'Về dòng Giô-gia-ríp, có Mát-tê-nai; về dòng Giê-đa-i-a, có U-xi.'),
(12645, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 20, 'OT', 'Sau Sa-lai là Ca-lai; sau A-mốc là Ê-bẹc.'),
(12646, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 21, 'OT', 'Thuộc về Hinh-ki-a là Ha-sa-bi-a; thuộc về Giê-đa-i-a là Nét-ha-nên.'),
(12647, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 22, 'OT', 'Các thầy Lê-vi, trong đời Ê-li-a-síp, Giô-ia-đa, Giô-ha-nan và Gia-đu-a, thì các trưởng tộc của họ được ghi chép; và các thầy tế lễ cho đến đời vua Đa-ri-út, vua Ba-tư.'),
(12648, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 23, 'OT', 'Các con trai của Lêvi, các tộc trưởng, đã được chép trong sách các niên kỷ cho đến các ngày của Giô-ha-nan, con trai Ê-li-a-síp.'),
(12649, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 24, 'OT', 'Các trưởng tộc người Lêvi là Ha-sa-bia, Sê-rê-bia, và Giê-su, con trai của Ca-đmi-ên, cùng các anh em của họ đối diện với họ, để ca ngợi và cảm tạ, theo mệnh lệnh của Đa-vít, người của Đức Chúa Trời, từng ban một đối diện từng ban.'),
(12650, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 25, 'OT', 'Mát-ta-nia, Bác-bu-cu, Ô-ba-đi-a, Mê-su-lam, Tanh-môn và A-cúp là những người giữ cửa, canh giữ nhiệm vụ tại các ngưỡng cửa của các cổng.'),
(12651, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 26, 'OT', 'Đây là những người thời Giô-gia-kim, con trai của Jêsua, con trai của Giô-xa-đắc, và thời Nê-hê-mi, tổng trấn, cùng với Ê-xơ-ra, thầy tế lễ, người văn sĩ.'),
(12652, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 27, 'OT', 'Và trong lễ khánh thành tường thành Giê-ru-sa-lem, người ta tìm các thầy Lê-vi từ mọi nơi ở của họ, để đưa họ đến Giê-ru-sa-lem, hầu cử hành lễ khánh thành với niềm vui mừng, cùng những lời cảm tạ và hát xướng, cùng với những chiếc chập chỏa, đờn nghẹ và đờn cầm.'),
(12653, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 28, 'OT', 'Các con trai của những người ca hát nhóm lại, từ đồng bằng xung quanh Giê-ru-sa-lem và từ các làng mạc của Nê-tô-pha-thi.'),
(12654, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 29, 'OT', 'Cũng từ nhà Gi-lê-ganh, và từ đồng bằng Gê-ba và A-xơ-ma-vết; vì các ca sĩ đã xây dựng cho mình những làng mạc chung quanh Giê-ru-sa-lem.'),
(12655, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 30, 'OT', 'Các thầy tế lễ và các người Lê-vi làm lễ tinh sạch mình, rồi làm lễ tinh sạch dân sự, các cửa và vách thành.'),
(12656, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 31, 'OT', 'Tôi đưa các quan trưởng của Giu-đa lên trên vách thành, và tôi đặt hai đoàn người lớn dâng lời cảm tạ, đi bên phải trên vách thành về hướng cổng Phân.'),
(12657, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 32, 'OT', 'Và sau họ đi Hô-sa-ia, và phân nửa các quan trưởng của Giu-đa,'),
(12658, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 33, 'OT', 'Và A-xa-ri-ah, Ê-xơ-ra, và Mê-thu-lam,'),
(12659, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 34, 'OT', 'Giu-đa, và Bên-gia-min, và Sê-ma-gia, và Giê-rê-mi.'),
(12660, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 35, 'OT', 'Và trong các con trai của thầy tế lễ, những người thổi kèn: Xa-cha-ri, con trai của Giô-na-than, con trai của Sê-ma-ia, con trai của Mát-ta-nia, con trai của Mi-cha-ia, con trai của Xa-cua, con trai của A-sáp.'),
(12661, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 36, 'OT', 'Và các anh em của người là Sê-ma-gia, A-xa-rên, Mi-la-lai, Gi-la-lai, Ma-ai, Nét-ha-nên, Giu-đa, và Ha-na-ni, mang các nhạc khí của Đa-vít, người của Đức Chúa Trời, và Ê-xơ-ra người thông thái đi trước họ.'),
(12662, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 37, 'OT', 'Và tại cổng Suối, đối diện với họ, họ đi lên các bậc thang của thành Đa-vít, theo lối lên trên bức tường, phía trên nhà Đa-vít, cho đến cổng Nước về hướng đông.'),
(12663, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 38, 'OT', 'Và đoàn tạ ơn thứ hai đi về hướng ngược lại, còn tôi đi theo sau họ; và phân nửa dân chúng đi trên tường, từ tháp các lò lửa trở đi cho đến bức tường rộng.'),
(12664, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 39, 'OT', 'Từ trên cổng Ép-ra-im, qua cổng Cũ, qua cổng Cá, tháp Ha-na-nên, tháp Một Trăm, cho đến cổng Chiên; và họ dừng lại ở cổng Ngục Tù.'),
(12665, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 40, 'OT', 'Hai đoàn tạ ơn đứng trong nhà Đức Chúa Trời, và tôi cùng phân nửa các quan chức đi với tôi.'),
(12666, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 41, 'OT', 'Các thầy tế lễ: Ê-li-a-kim, Ma-a-xe-ia, Mi-nhi-a-min, Mi-khai-a, Ê-li-ô-ênai, Xa-cha-ri, và Ha-na-nia, đều có kèn.'),
(12667, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 42, 'OT', 'Ma-a-xe, Sê-ma-gia, Ê-le-a-xa, U-xi, Giô-hô-chân, Man-ki-gia, Ê-lam và Ê-xe. Những người hát xướng đã cất tiếng lớn, với Giê-xa-ria làm người chỉ huy.'),
(12668, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 43, 'OT', 'Họ dâng những lễ vật lớn trong ngày ấy và vui mừng, vì Đức Chúa Trời đã làm cho họ vui mừng bằng niềm vui lớn; cả các vợ và con cái cũng vui mừng. Tiếng vui mừng của Giê-ru-sa-lem vang xa.'),
(12669, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 44, 'OT', 'Ngày ấy, những người được chỉ định quản lý các phòng chứa kho tàng, các lễ dâng đầu mùa và các phần thập phần, để thu vào đó từ các cánh đồng của các thành những phần quy định theo luật pháp dành cho các thầy tế lễ và người Lê-vi; vì Giu-đa vui mừng về các thầy tế lễ và người Lê-vi đang phục vụ.'),
(12670, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 45, 'OT', 'Và họ giữ gìn bổn phận thờ phượng Đức Chúa Trời mình, giữ gìn bổn phận về sự thanh sạch, cùng với các thầy nhạc và các thầy canh giữ cửa, theo như mạng lệnh của Đa-vít và của Sô-lô-môn, con trai ông.'),
(12671, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 46, 'OT', 'Vì trong những ngày xưa của Đa-vít và A-sáp, đã có các trưởng nhóm người hát, và những bài ca ngợi, ca tụng và tạ ơn Đức Chúa Trời.'),
(12672, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 12, 47, 'OT', 'Tất cả dân Y-sơ-ra-ên trong các ngày của Xê-ru-ba-bên và trong các ngày của Nê-hê-mi đều cấp phần cho các ca sĩ và các người giữ cửa, mỗi ngày một phần theo ngày đó; và họ biệt riêng các phần thánh cho người Lê-vi; còn người Lê-vi thì biệt riêng các phần thánh cho con cháu A-ha-ron.'),
(12673, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 13, 1, 'OT', 'Ngày ấy, người ta đọc trong sách Môi-se trước mặt dân chúng, và người ta tìm thấy chép ở đó rằng người Am-môn và người Mô-áp không được vào hội chúng của Đức Chúa Trời mãi mãi.'),
(12674, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 13, 2, 'OT', 'Vì chúng không mang bánh và nước ra đón con cái Ít-ra-en, mà lại thuê Ba-la-am chống lại họ để nguyền rủa họ; nhưng Đức Chúa Trời chúng tôi đã đổi lời nguyền rủa ấy ra phước lành.'),
(12675, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 13, 3, 'OT', 'Khi họ nghe đọc luật pháp, thì họ phân rẽ khỏi dân Y-sơ-ra-ên mọi người thuộc đoàn dân pha lộn.'),
(12676, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 13, 4, 'OT', 'Trước khi điều này xảy ra, thầy tế lễ Ê-li-a-síp, người được giao quản nhiệm phòng trong nhà Đức Chúa Trời của chúng ta, đã kết thông gia với Tô-bi-a.'),
(12677, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 13, 5, 'OT', 'Ông đã dọn cho ông một phòng lớn, nơi trước kia người ta để các lễ vật chay, lễ vật nhũ hương, các đồ dùng, và phần mười phần lúa mì, rượu mới và dầu ô-liu, là những thứ theo mạng lệnh phải đưa cho người Lê-vi, những người hát xướng và những người giữ cửa; cùng với lễ vật dành cho các thầy tế lễ.'),
(12678, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 13, 6, 'OT', 'Trong suốt thời gian ấy, tôi không ở Giê-ru-sa-lem, vì vào năm thứ ba mươi hai đời vua Ác-ta-xét-xe, vua Ba-by-lôn, tôi đã đến cùng vua; và sau một thời gian, tôi xin phép vua.'),
(12679, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 13, 7, 'OT', 'Tôi trở về Giê-ru-sa-lem và nhận biết điều ác mà Ê-li-a-síp đã làm cho Tô-bi-a, khi sửa sang cho người một phòng trong các hành lang của đền Đức Chúa Trời.'),
(12680, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 13, 8, 'OT', 'Ta rất lấy làm buồn rầu, nên ta đã quăng hết thảy đồ đạc trong nhà của Tô-bi-ah ra khỏi buồng ấy.'),
(12681, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 13, 9, 'OT', 'Tôi ra lệnh, và họ làm sạch các phòng; rồi tôi mang các đồ dùng của đền thờ Đức Chúa Trời, lễ vật và nhũ hương, đặt trở lại đó.'),
(12682, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 13, 10, 'OT', 'Tôi nhận biết rằng phần dành cho các thầy Lê-vi chưa được cung cấp, nên các thầy Lê-vi và các ca sĩ làm công việc đều đã trốn mỗi người về ruộng đất của mình.'),
(12683, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 13, 11, 'OT', 'Tôi đã quở trách các quan trưởng và nói: "Tại sao nhà Đức Chúa Trời bị bỏ bê?" Rồi tôi tập hợp họ lại và đặt họ vào đúng vị trí của họ.'),
(12684, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 13, 12, 'OT', 'Toàn thể người Giu-đa mang đến phần mười của ngũ cốc, rượu mới và dầu ô-liu để dâng vào các kho chứa.'),
(12685, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 13, 13, 'OT', 'Tôi đã đặt Sê-lê-mi-a, thầy tế lễ, và Xa-đốc, người văn sĩ, và từ các người Lê-vi, Phi-đa-i-a, làm người coi giữ các kho tàng; và dưới quyền họ là Ha-nan, con trai Xa-cua, cháu trai Ma-ta-thi-a; vì họ được xem là trung tín, và bổn phận của họ là phân phát cho anh em mình.'),
(12686, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 13, 14, 'OT', 'Lạy Đức Chúa Trời của tôi, xin hãy nhớ điều nầy cho tôi, và đừng xoá bỏ những ân huệ mà tôi đã làm cho nhà Đức Chúa Trời tôi và cho các chức vụ của Ngài.'),
(12687, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 13, 15, 'OT', 'Trong những ngày đó, tôi thấy tại Giu-đa người ta đạp các cái máy ép rượu vào ngày Sa-bát, và mang bó lúa, chất lên lừa, cũng như rượu, nho, sung và mọi thứ hàng hóa, rồi mang vào Giê-ru-sa-lem vào ngày Sa-bát; và tôi đã làm chứng chống lại họ vào ngày họ bán lương thực.'),
(12688, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 13, 16, 'OT', 'Người Ty-rơ cũng cư ngụ tại đó, mang cá và đủ thứ hàng hóa đến và bán vào ngày Sa-bát cho con cái Giu-đa và tại Giê-ru-sa-lem.'),
(12689, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 13, 17, 'OT', 'Tôi đã chất vấn những người lãnh tụ của Giu-đa và nói với họ: "Điều ác này mà các ngươi đang làm, khiến ngày Sa-bát bị xúc phạm, là điều gì vậy?"'),
(12690, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 13, 18, 'OT', 'Chẳng phải tổ tiên các ngươi đã làm như vậy sao, khiến Đức Chúa Trời chúng ta giáng xuống trên chúng ta mọi điều ác này và trên thành phố này sao? Thế mà các ngươi lại càng làm gia tăng cơn thịnh nộ trên Y-sơ-ra-ên bằng cách xúc phạm ngày Sa-bát.'),
(12691, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 13, 19, 'OT', 'Khi các cổng thành Giê-ru-sa-lem bắt đầu đổ bóng trước ngày Sa-bát, tôi ra lệnh đóng các cánh cửa lại và truyền rằng không được mở cho đến sau ngày Sa-bát; tôi cũng đặt các đầy tớ tôi canh giữ các cổng, để không một gánh nặng nào được mang vào trong ngày Sa-bát.'),
(12692, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 13, 20, 'OT', 'Các thương gia và những người bán đủ thứ hàng hóa đã trọ bên ngoài Giê-ru-sa-lem một hoặc hai lần.'),
(12693, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 13, 21, 'OT', 'Tôi đã cảnh cáo họ và nói với họ: "Tại sao các ngươi lại nằm nghỉ bên cạnh tường? Nếu các ngươi còn làm điều đó nữa, ta sẽ ra tay bắt các ngươi." Từ thời điểm ấy, họ không còn đến vào ngày Sa-bát nữa.'),
(12694, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 13, 22, 'OT', 'Tôi dặn các thầy Lê-vi phải làm cho mình được thanh sạch và đến canh giữ các cổng để thánh hóa ngày Sa-bát. Lạy Đức Chúa Trời của tôi, xin nhớ điều nầy khi Ngài xét đến tôi, và thương xót tôi theo sự nhân từ lớn lao của Ngài.'),
(12695, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 13, 23, 'OT', 'Trong những ngày ấy, tôi cũng thấy các người Giu-đa lấy vợ người A-sốt, người Am-môn và người Mô-áp.'),
(12696, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 13, 24, 'OT', 'Con cái chúng nói một nửa bằng tiếng A-sốt, không biết nói tiếng Do-thái, mà theo tiếng của từng dân tộc.'),
(12697, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 13, 25, 'OT', 'Tôi đã tranh cãi với chúng, rủa chúng, đánh đập một số người trong chúng, làm cho chúng phải thề thốt nhân danh Đức Chúa Trời rằng: Các ngươi sẽ không gả con gái các ngươi cho con trai chúng, cũng không cưới con gái chúng cho con trai các ngươi hoặc cho chính các ngươi.'),
(12698, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 13, 26, 'OT', 'Chẳng phải vua Sa-lô-môn của Ít-ra-ên đã phạm tội vì những điều này sao? Dù giữa rất nhiều dân tộc, không có một vị vua nào sánh được với ông, và ông được Đức Chúa Trời mình yêu mến, và Đức Chúa Trời đã đặt ông làm vua cai trị toàn thể Ít-ra-ên, vậy mà những phụ nữ ngoại đạo ấy vẫn khiến ông sa vào tội lỗi.'),
(12699, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 13, 27, 'OT', 'Chúng ta há sẽ nghe các ngươi để làm mọi điều ác lớn nầy, phạm tội cùng Đức Chúa Trời chúng ta bằng cách cưới các vợ ngoại đạo sao?'),
(12700, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 13, 28, 'OT', 'Một trong các con trai của Giô-i-đa, con trai của Ê-li-a-síp thầy tế lễ thượng phẩm, là rể của San-ba-lát người Hô-rôn; nên tôi đã đuổi hắn khỏi tôi.'),
(12701, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 13, 29, 'OT', 'Lạy Đức Chúa Trời của tôi, xin nhớ đến họ, vì họ đã làm ô uế chức thầy tế lễ, giao ước của thầy tế lễ và những người Lê-vi.'),
(12702, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 13, 30, 'OT', 'Tôi đã làm cho họ sạch khỏi mọi người ngoại bang, và tôi đặt các chức vụ cho các thầy tế lễ và người Lê-vi, mỗi người theo công việc của mình.'),
(12703, 16, 'GOI_vi', 'GOI_vi', 'vi', 'NEH', 13, 31, 'OT', 'Và về việc dâng củi theo kỳ đã định, và về các lễ đầu mùa. Lạy Đức Chúa Trời của tôi, xin nhớ đến tôi để được ơn lành.'),
(12704, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 1, 1, 'OT', 'Xảy ra trong những ngày của vua Achasvêrô, chính là Achasvêrô trị vì từ Ấn Độ cho đến Ê-thi-ô-pi, một trăm hai mươi bảy tỉnh.'),
(12705, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 1, 2, 'OT', 'Trong những ngày ấy, khi vua A-ha-su-ơ-rô-sơ đang ngự trên ngôi vương quyền của mình, tức là ngôi tại thành Sô-sơ, kinh đô.'),
(12706, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 1, 3, 'OT', 'Vào năm thứ ba triều đại mình, ông làm một bữa tiệc cho tất cả các quan trưởng và đầy tớ mình, cùng với các sĩ quan của Ba Tư và Mê-đi, và các quan tổng trấn các tỉnh, đang ở trước mặt ông.'),
(12707, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 1, 4, 'OT', 'Khi ông bày tỏ sự giàu có về vinh hiển của vương quốc mình và sự sang trọng vẻ đẹp về quyền cao của mình trong nhiều ngày, là một trăm tám mươi ngày.'),
(12708, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 1, 5, 'OT', 'Sau khi những ngày ấy đã mãn, vua làm một tiệc cho toàn thể dân chúng hiện diện tại thành trì Su-san, từ người lớn đến kẻ nhỏ, trong bảy ngày, tại sân vườn trong cung điện của nhà vua.'),
(12709, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 1, 6, 'OT', 'Rèm bằng vải gai mịn và màu xanh biếc, buộc bằng dây chỉ gai trắng và màu tím vào những vòng bạc và cột bằng đá cẩm thạch; những chiếc giường bằng vàng và bạc đặt trên nền bằng đá cẩm thạch đỏ, trắng, xanh và đen.'),
(12710, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 1, 7, 'OT', 'Họ uống rượu trong các đồ uống bằng vàng, và các đồ uống thì khác nhau, cùng với rượu vua ban phát dồi dào tùy theo quyền thế của nhà vua.'),
(12711, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 1, 8, 'OT', 'Và việc uống rượu thì theo luật lệ, không ai ép buộc; vì vua đã chỉ định cho tất cả các quan trưởng trong nhà mình phải làm theo ý muốn của mỗi người, mỗi người một cách.'),
(12712, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 1, 9, 'OT', 'Hoàng hậu Va-thi cũng tổ chức một tiệc cho các phụ nữ trong cung điện thuộc về vua A-suê-ru.'),
(12713, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 1, 10, 'OT', 'Vào ngày thứ bảy, khi lòng vua vui vẻ vì rượu, vua truyền cho Mê-hu-man, Biz-tha, Har-bô-na, Big-tha, A-ba-gô-tha, Xe-tha và Ca-rcas, bảy thái giám phục vụ trước mặt vua A-suê-ru,'),
(12714, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 1, 11, 'OT', 'Để mang hoàng hậu Va-thi đến trước mặt vua, đội mão triều, để cho dân chúng và các quan chức thấy vẻ đẹp của bà, vì bà là người xinh đẹp về dung mạo.'),
(12715, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 1, 12, 'OT', 'Hoàng hậu Va-shti từ chối đến theo lời truyền của nhà vua mà các hoạn quan chuyển đạt; vua bèn hết sức nổi giận, và cơn thịnh nộ của người bùng lên trong lòng.'),
(12716, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 1, 13, 'OT', 'Vua nói với các nhà thông thái, là những người hiểu biết về thời vụ, vì theo thói quen của vua, việc này được trình bày trước mọi người biết luật pháp và án lệ.'),
(12717, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 1, 14, 'OT', 'Và những người gần vua nhất là Cạt-sê-na, Sê-tha, Át-ma-tha, Ta-rê-si, Mê-re, Ma-sê-na và Mê-mu-can, bảy vị quan đầu nước Ba Tư và Mêđi, những người được diện kiến mặt vua và giữ chức quyền cao nhất trong vương quốc.'),
(12718, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 1, 15, 'OT', 'Theo luật pháp, phải xử lý hoàng hậu Va-shti thế nào, vì bà đã không tuân theo mệnh lệnh của vua A-suê-ru truyền qua các hoạn quan?'),
(12719, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 1, 16, 'OT', 'Mô-mu-kan tâu cùng vua và các quan rằng: "Không phải hoàng hậu Va-shti chỉ xúc phạm đến riêng một mình đức vua, mà còn xúc phạm đến tất cả các quan và toàn thể dân chúng trong mọi tỉnh của vua A-suê-ru."'),
(12720, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 1, 17, 'OT', 'Vì việc của hoàng hậu sẽ lan ra cho mọi phụ nữ, khiến họ coi thường chồng mình trong mắt họ, khi người ta nói rằng: Vua A-xa-su-ru-sơ đã truyền mang hoàng hậu Va-si-ti đến trước mặt vua, nhưng nàng đã không đến.'),
(12721, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 1, 18, 'OT', 'Ngày nay, các bà hoàng hậu của Ba-tư và Ma-đô sẽ nói với tất cả các quan trưởng của vua, là những người đã nghe tin về việc của hoàng hậu, và điều đó sẽ gây ra sự khinh bỉ và cơn thịnh nộ quá lớn.'),
(12722, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 1, 19, 'OT', 'Nếu điều này đẹp lòng nhà vua, xin hãy ban ra một sắc lệnh từ trước mặt vua, và được ghi vào luật lệ của người Ba-tư và người Ma-đô, không được phép hủy bỏ, rằng bà Vạt-thi không được đến trước mặt vua A-suê-ru, và vua sẽ ban ngôi vương hậu của bà cho người khác tốt hơn bà.'),
(12723, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 1, 20, 'OT', 'Khi sắc lệnh của vua mà người sẽ ban ra được công bố khắp toàn cõi vương quốc người (vì nó rất rộng lớn), thì mọi người vợ sẽ phải kính trọng chồng mình, từ người lớn đến người nhỏ.'),
(12724, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 1, 21, 'OT', 'Lời nói ấy đẹp lòng nhà vua và các quan trưởng; nhà vua bèn thi hành theo lời của Mê-mu-can.'),
(12725, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 1, 22, 'OT', 'Gửi các bức thư đến mọi tỉnh của vua, mỗi tỉnh theo văn tự riêng và mỗi dân tộc theo tiếng nói riêng, để mỗi người làm chủ trong nhà mình và nói theo tiếng dân tộc mình.'),
(12726, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 2, 1, 'OT', 'Sau những việc ấy, khi cơn thịnh nộ của vua A-suê-ru đã dịu xuống, thì người nhớ đến Va-thi, và điều mà nàng đã làm, và điều đã quyết định về nàng.'),
(12727, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 2, 2, 'OT', 'Các tôi tớ của vua phục sự người nói: Hãy tìm cho vua các gái trẻ đồng trinh, có vẻ ngoài xinh đẹp.'),
(12728, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 2, 3, 'OT', 'Vua hãy cử những quan chức trong các tỉnh khắp vương quốc mình, để họ tập trung tất cả các trinh nữ xinh đẹp về thành Súsơ, vào nhà các nữ nhân, dưới sự quản lý của Hê-ge, thái giám của vua, kẻ coi sóc các nữ nhân; và hãy cấp cho họ những vật dụng để thanh tẩy.'),
(12729, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 2, 4, 'OT', 'Và người gái trẻ nào được vua hài lòng sẽ trị vì thay cho Va-thi. Việc này được vua chấp thuận, và người làm như vậy.'),
(12730, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 2, 5, 'OT', 'Tại Xua, trong cung điện, có một người Do-thái tên là Mạc-đô-chê, con trai Giai-rơ, cháu trai Si-mê-i, chắt trai Ki-sơ, người thuộc chi phái Bên-gia-min.'),
(12731, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 2, 6, 'OT', 'đã bị lưu đày từ Giê-ru-sa-lem cùng với những người bị lưu đày mà vua Giê-cô-nia của Giu-đa đã bị lưu đày với họ, người mà vua Nê-bu-cát-nết-sa của Ba-by-lôn đã bắt đi.'),
(12732, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 2, 7, 'OT', 'Và người đã nuôi dưỡng Ha-đa-sa, tức là Ê-xơ-tê, con gái em trai của mình, vì cô không có cha lẫn mẹ; và cô gái này có sắc đẹp và dung mạo xinh đẹp. Khi cha và mẹ cô qua đời, Mạc-đô-chê nhận cô làm con gái mình.'),
(12733, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 2, 8, 'OT', 'Xảy ra khi tin về mệnh lệnh và sắc chỉ của vua được loan truyền, và các trinh nữ đông đảo được tập trung về tỉnh Su-sơ, dưới sự quản lý của Hê-ghê, thì Ê-xơ-tê cũng được đưa đến cung điện của vua, dưới sự quản lý của Hê-ghê, người giữ các người phụ nữ.'),
(12734, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 2, 9, 'OT', 'Cô gái được người ấy ưa chuộng và nhận được ơn thương xót trước mặt người ấy; người ấy liền cho cấp các vật dụng để thanh tẩy và những thứ cần dùng cho cô, cùng bảy thiếu nữ xứng đáng được giao cho cô từ nhà vua; người ấy đưa cô và các nữ tì của cô vào nơi tốt nhất trong khu nhà của các phụ nữ.'),
(12735, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 2, 10, 'OT', 'Ê-xơ-tê đã không tiết lộ dân tộc và nguồn gốc của mình, vì Mạc-đô-chê đã dặn nàng không được tiết lộ.'),
(12736, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 2, 11, 'OT', 'Mỗi ngày, Mạc-đô-chai đi dạo trước sân nhà các người đàn bà, để biết tình trạng của Ê-xơ-tê ra sao và điều gì sẽ xảy đến với nàng.'),
(12737, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 2, 12, 'OT', 'Khi đến lượt mỗi trinh nữ vào gặp vua A-suê-ru, sau mười hai tháng theo nghi thức dành cho các thiếu nữ—vì thời gian thanh tẩy của các cô phải đầy đủ như vậy: sáu tháng dùng dầu myrrh và sáu tháng dùng các hương liệu cùng mỹ phẩm dành cho phụ nữ—'),
(12738, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 2, 13, 'OT', 'Mỗi một thiếu nữ đến cùng vua, thì mọi điều nàng muốn đều được cấp cho để mang theo từ nhà các nữ nhân vào nhà vua.'),
(12739, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 2, 14, 'OT', 'Đến tối, nàng vào; rồi sáng hôm sau, nàng trở lại nhà hai của các người đàn bà, dưới quyền Sha-as-gát, thái giám của vua, kẻ giữ các thứ thiếp; nàng sẽ không vào cùng vua nữa, trừ khi vua ưa thích nàng và nàng được gọi theo danh tánh.'),
(12740, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 2, 15, 'OT', 'Khi đến lượt Ê-xơ-tê, con gái của A-bi-hai-l, người cậu của Mạc-đô-chai, mà Mạc-đô-chai đã nhận làm con gái mình, phải vào chầu vua, thì nàng không xin điều gì khác ngoài điều mà Hê-gai, hoạn quan của vua, kẻ giữ các người nữ, đã chỉ định. Và Ê-xơ-tê được ơn thương trong mắt mọi người nhìn thấy nàng.'),
(12741, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 2, 16, 'OT', 'Ê-xơ-tê được đưa đến cùng vua A-suê-ru, vào cung điện của ông, trong tháng thứ mười, tức là tháng Tê-bết, năm thứ bảy đời trị vì của ông.'),
(12742, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 2, 17, 'OT', 'Vua yêu thương Ê-xơ-tê hơn mọi người phụ nữ, và nàng được ơn và sự thương xót trước mặt vua hơn tất cả các trinh nữ; vua đặt triều thiên vương miện trên đầu nàng và lập nàng làm hoàng hậu thay cho Va-shti.'),
(12743, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 2, 18, 'OT', 'Vua đã tổ chức một bữa tiệc lớn cho tất cả các quan trưởng và đầy tớ mình, tức là bữa tiệc của Ê-xơ-tê; vua cũng ban sự nhẹ nhõm cho các tỉnh và ban phát những món quà tuỳ theo khả năng của vua.'),
(12744, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 2, 19, 'OT', 'Khi các trinh nữ được tập hợp lần thứ hai, Mạc Đô-chai vẫn ngồi tại cổng vua.'),
(12745, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 2, 20, 'OT', 'Ê-xơ-tơ chưa tiết lộ quê quán hay dân tộc mình, như Mạc-đô-chê đã dặn; và Ê-xơ-tơ làm theo lệnh Mạc-đô-chê, y như lúc còn được ông nuôi dưỡng.'),
(12746, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 2, 21, 'OT', 'Trong những ngày ấy, khi Mạc-đô-chai đang ngồi nơi cửa thành của vua, thì hai thái giám của vua, Bích-than và Tê-rết, những người giữ cửa, đã nổi giận và tìm cách ra tay hại vua A-suê-ru.'),
(12747, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 2, 22, 'OT', 'Điều đó được Mạc-đô-chai biết đến, rồi ông báo cho hoàng hậu Ê-xơ-tê; và Ê-xơ-tê tấu lên cho vua biết, nhân danh Mạc-đô-chai.'),
(12748, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 2, 23, 'OT', 'Khi điều tra về việc đó, thì phát hiện ra sự thật; cả hai người đều bị treo cổ trên cây. Sự việc được ghi vào sách sử ký, trước mặt vua.'),
(12749, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 3, 1, 'OT', 'Sau các việc ấy, vua A-xa-su-ru-sơ làm cho Ha-man, con trai của Ha-mê-đa-tha người A-ga-ghi, được tôn cao; ông làm cho người được nâng lên và đặt ngôi của người cao hơn tất cả các quan trưởng cùng ở với ông.'),
(12750, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 3, 2, 'OT', 'Tất cả các đầy tớ của vua, là những người ở nơi cửa vua, đều cúi lạy và thờ lạy Ha-man, vì vua đã truyền lệnh như vậy cho người ấy. Nhưng Mạc-đô-chai thì không chịu cúi lạy, cũng không chịu thờ lạy.'),
(12751, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 3, 3, 'OT', 'Các đầy tớ của vua, những người ở nơi cửa vua, nói với Mạc-đô-chê: "Tại sao ngươi vi phạm mạng lệnh của vua?"'),
(12752, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 3, 4, 'OT', 'Mỗi ngày họ nói với người đó, nhưng người ấy không nghe theo họ; họ liền thuật lại cho Ha-man, để xem lời của Mạc-đô-chai có đứng vững được chăng, vì người đã cho họ biết mình là người Do-thái.'),
(12753, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 3, 5, 'OT', 'Khi Ha-man thấy Mạc-đô-chai không cúi lạy, cũng không tỏ lòng kính trọng người, thì Ha-man đầy lòng thịnh nộ.'),
(12754, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 3, 6, 'OT', 'Rồi ông ta coi thường việc tra tay vào Mạc-đô-chai chỉ một mình ông ta thôi, vì người ta đã cho ông ta biết về dân tộc của Mạc-đô-chai; nên Ha-man tìm cách tiêu diệt tất cả người Do-thái ở khắp mọi nơi trong vương quốc của A-xu-ê-ru-sơ, tức là dân tộc của Mạc-đô-chai.'),
(12755, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 3, 7, 'OT', 'Trong tháng đầu tiên, tức là tháng Nisan, năm thứ mười hai đời vua A-suê-ros, người ta đã gieo Pur, tức là cái vẽ thăm, trước mặt Ha-man, từ ngày này sang ngày khác, và từ tháng này sang tháng kia, đến tháng thứ mười hai, tức là tháng A-đa.'),
(12756, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 3, 8, 'OT', 'Ha-man tâu với vua A-xu-ê-ru-sơ: "Có một dân riêng rẽ và phân tán giữa các dân trong mọi tỉnh của nước người; luật lệ họ khác hẳn mọi dân, và họ không tuân theo luật vua; nên không lợi cho vua nếu dung thứ họ."'),
(12757, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 3, 9, 'OT', 'Nếu được vua đẹp lòng, xin hãy ra lệnh viết để tiêu diệt chúng; và tôi sẽ nộp mười ngàn kikar bạc vào tay những người phụ trách công việc, để đưa vào kho bạc của vua.'),
(12758, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 3, 10, 'OT', 'Vua cất ấn triều từ tay mình và trao cho Ha-man, con trai Ha-mê-đa-tha, người A-gát, kẻ thù của dân Do Thái.'),
(12759, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 3, 11, 'OT', 'Vua nói với Ha-man: "Bạc thì đã cho ngươi rồi, còn dân sự nữa, để ngươi làm điều mình cho là tốt theo mắt ngươi."'),
(12760, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 3, 12, 'OT', 'Các văn thư của vua được triệu tập vào ngày mười ba tháng đầu tiên, và người ta đã viết ra theo mọi điều Ha-man truyền cho các quan tổng trấn của vua, cho các quan toàn quyền cai trị mỗi tỉnh và mỗi tỉnh, và cho các quan chức của mỗi dân tộc và mỗi dân tộc, mỗi tỉnh và mỗi tỉnh theo văn tự riêng, và mỗi dân tộc theo tiếng riêng của họ; bức thư được viết nhân danh vua A-suê-ru, và đóng ấn bằng ấn triều của vua.'),
(12761, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 3, 13, 'OT', 'Các bức thư đã được gửi đi bởi những sứ giả đến mọi tỉnh của vua, để tiêu diệt, giết và diệt trừ mọi người Do-thái, từ trẻ nhỏ đến người già, cả trẻ em và phụ nữ, trong một ngày, tức là ngày mười ba tháng mười hai, là tháng A-đa, và cướp đoạt tài sản của họ.'),
(12762, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 3, 14, 'OT', 'Bản văn sắc lệnh được phổ biến trong mọi tỉnh và xứ, để mọi dân tộc đều biết, hầu sẵn sàng cho ngày đó.'),
(12763, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 3, 15, 'OT', 'Các sứ giả vội vã ra đi theo lệnh vua, và sắc chỉ đã được ban hành tại Su-sơ, kinh đô. Vua và Ha-man ngồi xuống uống rượu, còn thành phố Su-sơ thì bối rối.'),
(12764, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 4, 1, 'OT', 'Mô-rắc-tai biết mọi điều đã xảy ra, bèn xé áo mình, mặc áo bằng vải gai và tro, đi ra giữa thành phố, kêu khóc lớn tiếng và cay đắng.'),
(12765, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 4, 2, 'OT', 'Và ông đến ngay trước cổng vua, vì không ai được phép vào cổng vua khi đang mặc áo bằng vải sô.'),
(12766, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 4, 3, 'OT', 'Trong mỗi tỉnh và tỉnh, tại mọi nơi mà sắc lệnh và luật lệ của vua truyền đến, người Do-thái đều than khóc thảm thiết, ăn chay, khóc lóc và than vãn; nhiều người nằm trên bao và tro.'),
(12767, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 4, 4, 'OT', 'Các nữ tì của Ê-xơ-tê và các thái giám đến báo cho nàng, thì nàng rất bối rối. Nàng sai mang quần áo đến cho Mạc-đô-chai mặc và cởi bỏ cái bao gai khỏi người ông, nhưng ông không nhận.'),
(12768, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 4, 5, 'OT', 'Bà Ê-xơ-tê gọi Ha-thác, một thái giám của vua, người đã được đặt để hầu trước mặt bà, và truyền lệnh cho ông đến với Mạc-đô-chê, để biết điều đó là gì và vì sao có điều đó.'),
(12769, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 4, 6, 'OT', 'Ha-tác đi ra đến cùng Mardôcai, tại phố phố của thành, là nơi trước cửa vua.'),
(12770, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 4, 7, 'OT', 'Mạc-đô-chai thuật lại cho ông mọi điều đã xảy đến cho mình, và số tiền mà Ha-man đã nói sẽ nộp vào kho bạc của nhà vua để tiêu diệt dân Do-thái.'),
(12771, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 4, 8, 'OT', 'Và người trao cho hắn bản sao văn thư quy định đã ban hành tại Xua để tiêu diệt họ, hầu cho hắn chỉ cho Ê-xơ-tê xem, và thuật lại cho nàng, rồi truyền lệnh nàng phải vào yết kiến vua, khẩn nài người và xin người vì dân tộc nàng.'),
(12772, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 4, 9, 'OT', 'Ha-tác đi đến và thuật lại cho Ê-xơ-tê những lời của Mạc-đô-cải.'),
(12773, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 4, 10, 'OT', 'Ê-xơ-tê nói với Ha-tách và truyền lệnh cho Mạc-đô-chê qua người ấy.'),
(12774, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 4, 11, 'OT', 'Mọi tôi tớ của vua và mọi dân trong các tỉnh của vua đều biết rằng bất cứ người nào, nam hay nữ, vào sân trong cùng gặp vua mà không được triệu kiến, thì chỉ có một luật lệ dành cho người ấy là phải chết, ngoại trừ người mà vua giơ ra cây trượng vàng thì sẽ được sống; nhưng tôi đây đã ba mươi ngày nay chưa được triệu kiến để vào gặp vua.'),
(12775, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 4, 12, 'OT', 'Họ thuật lại cho Mạc-đô-chai những lời của Ê-xơ-tê.'),
(12776, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 4, 13, 'OT', 'Mạc-đô-chê truyền đáp lại Ê-xơ-tê: Đừng tưởng rằng ngươi sẽ thoát khỏi trong nhà vua hơn bất cứ người Do-thái nào khác.'),
(12777, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 4, 14, 'OT', 'Vì nếu như ngươi giữ im lặng trọn vẹn trong lúc này, dân Do-thái sẽ được giải cứu và thoát nạn từ một nơi nào đó; còn ngươi và nhà của cha ngươi sẽ bị tiêu diệt. Và ai biết được, có thể chính vì lúc như thế này mà ngươi đã được đưa đến ngôi vua?'),
(12778, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 4, 15, 'OT', 'Bấy giờ Ê-xơ-tê bảo người trả lời cho Mạc-đô-chai rằng:'),
(12779, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 4, 16, 'OT', 'Hãy đi, quy tụ tất cả người Do-thái đang ở tại Su-san, và ăn chay vì tôi, đừng ăn hay uống trong ba ngày, cả ban đêm lẫn ban ngày; tôi và các nữ tì tôi cũng sẽ ăn chay như vậy; rồi tôi sẽ vào ra mắt vua, dù điều đó trái luật lệ; và nếu tôi phải chết, tôi sẽ chết.'),
(12780, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 4, 17, 'OT', 'Vậy Mạc-đô-chai đi và làm theo mọi điều mà Ê-xơ-tê đã truyền dạy ông.'),
(12781, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 5, 1, 'OT', 'Ngày thứ ba ấy, bà Ê-xơ-tê mặc lễ phục vương hậu, rồi đứng trong sân trong của cung vua, đối diện với cung vua; còn nhà vua thì đang ngồi trên ngôi vương quyền của mình trong cung vua, đối diện với cửa cung.'),
(12782, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 5, 2, 'OT', 'Khi vua thấy bà hoàng Ê-xơ-tê đứng trong hành lang, bà được ơn trong mắt vua; vua bèn giơ ra về phía bà Ê-xơ-tê cây trượng vàng trong tay mình; bà Ê-xơ-tê bèn đến gần, và chạm vào đầu cây trượng.'),
(12783, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 5, 3, 'OT', 'Vua nói với nàng: "Nàng muốn điều gì, hoàng hậu Ê-xơ-tê? Và điều nàng xin là gì? Dù là phân nửa vương quốc, ta cũng sẽ ban cho nàng."'),
(12784, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 5, 4, 'OT', 'Bấy giờ Ê-xơ-tê đáp: "Nếu được ơn vua, xin vua và ông Ha-man đến dự tiệc mà tôi đã dọn cho ngài hôm nay."'),
(12785, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 5, 5, 'OT', 'Vua nói: "Hãy vội vàng gọi Ha-man đến để thi hành điều mà Ê-xơ-tê đã nói." Vậy vua và Ha-man đến dự tiệc yến mà Ê-xơ-tê đã dọn sẵn.'),
(12786, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 5, 6, 'OT', 'Vua nói với Ê-xơ-tê trong bữa tiệc rượu: "Này, hỡi nàng, điều gì ngươi mong muốn, hãy nói ra, và sẽ ban cho ngươi; điều gì ngươi thỉnh cầu, dù là nửa vương quốc, cũng sẽ được thực hiện."'),
(12787, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 5, 7, 'OT', 'Bấy giờ Ê-xơ-tê đáp và nói: Lời khẩn cầu và thỉnh nguyện của tôi là;'),
(12788, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 5, 8, 'OT', 'Nếu tôi được ơn trước mặt đức vua, và nếu đẹp lòng đức vua ban cho điều tôi xin và thực hiện điều tôi cầu, thì xin đức vua và ông Ha-man đến dự tiệc mà tôi đã chuẩn bị cho họ; ngày mai tôi sẽ làm theo lời đức vua.'),
(12789, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 5, 9, 'OT', 'Ha-man ra đi ngày ấy với lòng vui vẻ và hân hoan; nhưng khi thấy Mạc-đô-cải ở nơi cửa vua, thấy người không đứng dậy và không nhúc nhích trước mặt mình, thì Ha-man đầy lòng tức giận đối với Mạc-đô-cải.'),
(12790, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 5, 10, 'OT', 'Ha-man nhịn giận, rồi đi về nhà mình, sai người mời các bạn hữu và Xê-rết, vợ mình, đến.'),
(12791, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 5, 11, 'OT', 'Ha-man nói với họ về vinh hiển của sự giàu có, về số đông các con trai mình, về tất cả những điều vua đã làm cho ông được tôn vinh, và về việc ông được nâng lên trên các quan trưởng và các đầy tớ của vua.'),
(12792, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 5, 12, 'OT', 'Ha-man nói thêm: "Ngay cả hoàng hậu Ê-xơ-tê cũng chẳng cho phép ai khác cùng vua dự tiệc mà nàng đã dọn, ngoài tôi ra; và ngày mai tôi cũng được mời đến cùng vua nơi nàng."'),
(12793, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 5, 13, 'OT', 'Tuy nhiên, tất cả những điều này chẳng mang lại lợi ích gì cho tôi, mỗi khi tôi thấy Mạc-đô-chai người Do-thái ngồi ở cổng vua.'),
(12794, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 5, 14, 'OT', 'Bấy giờ, bà Xe-resh, vợ người, và tất cả những kẻ thân cận nói với người: "Hãy làm một cây gỗ cao năm mươi thước, rồi mai kia hãy xin vua treo Mạc-đô-chê lên đó; rồi người hãy vui vẻ vào dự tiệc cùng vua." Điều đó vừa lòng Ha-man, và người làm cây gỗ ấy.'),
(12795, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 6, 1, 'OT', 'Đêm ấy, nhà vua không ngủ được, bèn truyền mang sách kỷ niệm các sự việc ngày xưa đến; và người ta đọc những điều ấy trước mặt nhà vua.'),
(12796, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 6, 2, 'OT', 'Và người ta tìm thấy được ghi chép rằng Mạc-đô-cải đã báo tin về Bích-tha-na và Tê-rết, hai thái giám của vua, những người giữ cửa, là những kẻ đã toan tính ra tay hại vua A-suê-ru.'),
(12797, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 6, 3, 'OT', 'Vua nói: "Vì điều nầy, người ta đã làm điều gì vinh hiển và cao trọng cho Mạc-đô-chai chưa?" Các đầy tớ của vua phục vụ người ấy thưa: "Chưa có gì được làm cho ông."'),
(12798, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 6, 4, 'OT', 'Vua nói: "Ai đang ở trong hành lang?" Và Ha-man đã vào hành lang ngoài của cung điện vua, để thưa với vua rằng hãy treo Mạc-đô-chai trên cây gỗ mà người đã chuẩn bị cho hắn.'),
(12799, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 6, 5, 'OT', 'Các tôi tớ của vua thưa với người: "Nầy, Hâmân đang đứng trong sân." Vua nói: "Hãy để người ấy vào."'),
(12800, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 6, 6, 'OT', 'Vậy Ha-man vào. Vua hỏi người ấy rằng: "Phải làm gì cho người mà vua muốn tôn vinh?" Ha-man nghĩ thầm trong lòng: "Vua muốn tôn vinh ai hơn tôi nữa?"'),
(12801, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 6, 7, 'OT', 'Ha-man tâu với vua rằng: "Chính là người mà nhà vua muốn tôn vinh sự vinh hiển của người ấy."'),
(12802, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 6, 8, 'OT', 'Hãy mang áo bào vương quyền mà nhà vua đã mặc, và con ngựa mà nhà vua đã cỡi, và mão triều vương đã đặt trên đầu người ấy.'),
(12803, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 6, 9, 'OT', 'Và hãy trao y phục cùng con ngựa cho một người trong các quan đại thần của vua, rồi cho mặc y phục đó vào người mà vua muốn tôn vinh, đưa người ấy cỡi ngựa đi ngang các phố chính của thành phố, và rao truyền trước mặt người ấy rằng: "Kẻ nầy sẽ được đối xử như thế nầy, là người mà vua muốn tôn vinh."'),
(12804, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 6, 10, 'OT', 'Vua nói với Ha-man: "Hãy mau lên, lấy áo xống và con ngựa như lời ngươi đã nói, rồi làm cho Ma-thơ-đô-chai người Do Thái, đang ngồi nơi cửa vua, như vậy đi. Đừng để thiếu sót điều gì trong tất cả những điều ngươi đã nói."'),
(12805, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 6, 11, 'OT', 'Ha-man lấy áo xống và con ngựa, mặc cho Mạc-đô-chai, rồi dắt ông cỡi ngựa đi qua phố chính của thành phố, và rao trước mặt ông: "Người ta sẽ làm như thế này cho người mà vua muốn tôn vinh."'),
(12806, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 6, 12, 'OT', 'Mạc-đô-chê trở lại cổng vua; còn Ha-man vội vã về nhà mình, than khóc và đầu bị che phủ.'),
(12807, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 6, 13, 'OT', 'Ha-man thuật lại cho Xe-resh, vợ mình, và cho tất cả những người thân tín mọi điều xảy đến cho mình. Các bậc hiền triết và Xe-resh, vợ ông, nói với ông: "Nếu Mạc-đô-chê thuộc dòng dõi người Do-thái, trước mặt người mà ông đã bắt đầu sa ngã, thì ông sẽ không thể thắng được người ấy, mà chắc chắn sẽ bị khuất phục trước mặt người ấy."'),
(12808, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 6, 14, 'OT', 'Họ còn đang nói chuyện với ông ta thì các thái giám của vua đã đến, vội vã đưa Hâmân đi dự tiệc mà Ê-xơ-tê đã dọn sẵn.'),
(12809, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 7, 1, 'OT', 'Vua và Ha-man đến dự tiệc rượu cùng với bà hoàng hậu Ê-xơ-tê.'),
(12810, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 7, 2, 'OT', 'Vua lại nói với Ê-xơ-tê trong ngày thứ hai, tại tiệc rượu: "Này hoàng hậu Ê-xơ-tê, điều ngươi xin là gì? Nó sẽ được ban cho ngươi. Điều ngươi cầu xin là gì? Dù là phân nửa vương quốc, nó cũng sẽ được thực hiện."'),
(12811, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 7, 3, 'OT', 'Bấy giờ hoàng hậu Ê-xơ-tê đáp và nói: Nếu tôi được ơn trước mặt vua, và nếu điều đó vừa lòng vua, xin ban cho tôi mạng sống tôi theo lời khẩn xin của tôi, và dân tôi theo lời thỉnh cầu của tôi.'),
(12812, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 7, 4, 'OT', 'Vì tôi và dân tôi đã bị bán để bị tiêu diệt, giết hại và hủy diệt; nhưng nếu chúng tôi đã bị bán làm tôi mọi và tớ gái, tôi đã làm thinh, vì tổn hại này không đáng kể so với thiệt hại của nhà vua.'),
(12813, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 7, 5, 'OT', 'Vua A-xu-ru-sơ nói và hỏi hoàng hậu Ê-xơ-tê: "Kẻ nào, ở đâu, dám nảy lòng làm điều này?"'),
(12814, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 7, 6, 'OT', 'Bấy giờ Ê-xơ-tê nói: "Kẻ thù nghịch và kẻ thù dữ ác ấy chính là Ha-man. Và Ha-man thấy sợ hãi trước mặt vua và hoàng hậu."'),
(12815, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 7, 7, 'OT', 'Vua đứng dậy trong cơn thịnh nộ từ bữa tiệc rượu đi vào vườn cung điện; còn Ha-man thì đứng dậy để xin mạng sống mình nơi hoàng hậu Ê-xơ-tê, vì người thấy rõ điều dữ từ nơi vua đã được quyết định nghịch lại mình.'),
(12816, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 7, 8, 'OT', 'Vua trở về từ khu vườn trong hành lang vào nơi ăn tiệc rượu, còn Ha-man thì đang ngã gục trên giường nơi Ê-xơ-tê ngồi. Vua nói: "Hắn cũng dám hãm hiếp hoàng hậu ngay trước mặt ta trong nhà sao?" Ngay khi lời vua vừa ra khỏi miệng, người ta liền che mặt Ha-man.'),
(12817, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 7, 9, 'OT', 'Har-bô-na, một trong các hoạn quan, tâu vua rằng: "Kìa, cái cây mà Ha-man đã làm để treo Mạc-đô-chai, người đã nói điều tốt cho vua, thì đang dựng đứng trong nhà Ha-man, cao năm mươi thước. Vua bèn truyền: "Hãy treo hắn lên đó."'),
(12818, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 7, 10, 'OT', 'Họ treo Ha-man trên cây gỗ mà hắn đã làm sẵn để giết Mạc-đô-chê; cơn thịnh nộ của nhà vua bèn dịu xuống.'),
(12819, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 8, 1, 'OT', 'Trong ngày ấy, vua A-ha-su-e-rơ đã ban cho bà Ê-xơ-tê hoàng hậu ngôi nhà của Ha-man, kẻ thù của dân Do Thái. Còn Mạc-đô-chai thì đến ra mắt trước mặt vua, vì Ê-xơ-tê đã cho vua biết mối quan hệ giữa bà với ông.'),
(12820, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 8, 2, 'OT', 'Vua cất chiếc ấn nhẫn mà người đã lấy từ nơi Ha-man và trao cho Mạc-đô-chai; và Ê-xơ-tê đặt Mạc-đô-chai quản trị nhà của Ha-man.'),
(12821, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 8, 3, 'OT', 'Bấy giờ Ê-xơ-tê lại tiếp tục nói trước mặt vua, rồi sấp mình xuống dưới chân người, khóc lóc và nài xin người hãy ngăn cản điều ác do Hơ-man, người A-gác, gây ra và hủy bỏ mưu kế mà hắn đã bày ra chống lại dân Do-thái.'),
(12822, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 8, 4, 'OT', 'Vua đưa ra cây trượng vàng về phía Ê-xơ-tê. Ê-xơ-tê bèn đứng dậy và đứng trước mặt vua.'),
(12823, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 8, 5, 'OT', 'Bà thưa: Nếu điều này đẹp lòng đức vua, nếu tôi được ơn trước mặt người, và nếu việc này vừa lòng đức vua và tôi đẹp ý người, nguyện cho viết sắc chỉ để hủy bỏ những bức thư do Ha-man, con trai Ha-mê-đa-tha người A-gát, đã soạn thảo và gửi đi nhằm tiêu diệt các người Do-thái trong mọi tỉnh của đức vua.'),
(12824, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 8, 6, 'OT', 'Làm sao tôi có thể chịu đựng mà nhìn thấy tai họa sẽ giáng trên dân tôi? Làm sao tôi có thể chịu đựng mà nhìn thấy sự diệt vong của những người cùng dòng giống tôi?'),
(12825, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 8, 7, 'OT', 'Vua A-suê-ru nói với hoàng hậu Ê-xơ-tê và Mạc-đô-chai người Do Thái: "Nầy, ta đã ban nhà của Ha-man cho Ê-xơ-tê, còn chính hắn thì đã bị treo trên cây vì đã ra tay chống lại dân Do Thái."'),
(12826, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 8, 8, 'OT', 'Hãy viết cho người Do-thái tùy theo điều tốt lành trong mắt các ngươi, nhân danh vua và đóng ấn với ấn triều của vua; vì bức thư nào đã được viết nhân danh vua và đóng ấn với ấn triều của vua, thì không ai được phép hủy bỏ.'),
(12827, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 8, 9, 'OT', 'Bấy giờ, các văn thư ký của vua được triệu tập trong tháng thứ ba, tức là tháng Si-va, ngày hai mươi ba của tháng ấy; và người ta đã chép theo mọi điều mà Mạc-đô-chai truyền dạy cho các người Do-thái, cho các tổng trấn, các quan cai trị và các quan trưởng các tỉnh từ Ích-chi-đô cho đến Ê-thi-ô-bi, tổng cộng một trăm hai mươi bảy tỉnh, mỗi tỉnh theo văn thư của mình, mỗi dân tộc theo tiếng của họ, và cho các người Do-thái theo văn tự và tiếng nói của họ.'),
(12828, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 8, 10, 'OT', 'Ông viết bằng danh vua A-suê-ru, đóng ấn bằng ấn triều vua, rồi sai các bức thư trao vào tay những sứ giả cưỡi ngựa, những người cưỡi ngựa chiến thuộc giống ngựa nhanh.'),
(12829, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 8, 11, 'OT', 'Điều mà nhà vua cho phép người Do-thái, những người ở mỗi thành phố và thành phố, được nhóm họp và tự vệ, để tiêu diệt, giết và diệt trừ toàn thể lực lượng của dân sự và tỉnh nào muốn hãm hại họ, cả trẻ nhỏ và phụ nữ, và cướp lấy của cải họ làm chiến lợi phẩm.'),
(12830, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 8, 12, 'OT', 'Vào một ngày duy nhất trong mọi tỉnh của vua A-ha-su-ơ-sơ, tức là ngày mười ba tháng mười hai, tức là tháng A-đa.'),
(12831, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 8, 13, 'OT', 'Bản sao của văn thư, để phổ biến luật lệ trong mọi tỉnh và tỉnh, được công bố rõ ràng cho mọi dân tộc, và để người Do Thái sẵn sàng vào ngày đó, nhằm báo thù các kẻ thù mình.'),
(12832, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 8, 14, 'OT', 'Các sứ giả cưỡi ngựa kéo xe nhanh, là những con ngựa được nuôi trong chuồng vua, vội vã và hối hả ra đi theo lệnh vua; và đạo luật được ban ra tại Su-sơ, thành trì.'),
(12833, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 8, 15, 'OT', 'Mạc-đô-chai đi ra khỏi mặt vua, mặc áo triều phục bằng vải xanh biếc và trắng, đội mão triều vàng lớn, khoác áo vải gai mịn và tím; thành phố Su-san reo vui và hớn hở.'),
(12834, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 8, 16, 'OT', 'Người Do-thái được ánh sáng, niềm vui mừng, sự hân hoan và vinh dự.'),
(12835, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 8, 17, 'OT', 'Trong mỗi tỉnh và mỗi tỉnh, trong mỗi thành và mỗi thành, tại mọi nơi mà sắc lệnh và luật lệ của vua truyền đến, người Do-thái được vui mừng, hớn hở, ăn tiệc và giữ ngày lễ tốt đẹp. Rất nhiều người trong các dân tộc trên đất đã trở thành người Do-thái, vì sự khiếp sợ người Do-thái đã đè nặng trên họ.'),
(12836, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 9, 1, 'OT', 'Vào tháng thứ mười hai, tức là tháng A-đa, ngày mười ba của tháng ấy, khi mệnh lệnh của vua và luật lệ của người sắp được thi hành, vào chính ngày mà kẻ thù của dân Do-thái mong ước được quyền thống trị trên họ, thì điều ngược lại đã xảy ra, khiến cho chính dân Do-thái được quyền cai trị trên những kẻ ghét họ.'),
(12837, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 9, 2, 'OT', 'Người Do-thái nhóm lại với nhau trong các thành của họ ở khắp các tỉnh của vua A-xu-ê-ru-sơ, để ra tay chống những kẻ tìm hại mình; và chẳng ai đứng nổi trước mặt họ, vì sự khiếp sợ về họ đã đổ trên mọi dân tộc.'),
(12838, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 9, 3, 'OT', 'Tất cả các quan tổng trấn, các quan trấn thủ, các quan chấp chính và các viên chức thi hành công vụ của vua đều ủng hộ người Do-thái; vì sự khiếp sợ Mạc-đô-chai đã giáng trên họ.'),
(12839, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 9, 4, 'OT', 'Vì Mạc-đô-chai rất nổi bật trong nhà vua, và tiếng đồn về ông lan ra khắp các tỉnh; vì người đàn ông Mạc-đô-chai ngày càng lớn lên và trở nên vĩ đại.'),
(12840, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 9, 5, 'OT', 'Người Do-thái đánh tất cả các kẻ thù của mình bằng lưỡi gươm, sự tàn sát và tiêu diệt, và họ làm điều mình muốn đối với những kẻ ghét họ.'),
(12841, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 9, 6, 'OT', 'Tại Su-sơ, kinh thành, dân Y-sơ-ra-ên đã giết và tiêu diệt năm trăm người đàn ông.'),
(12842, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 9, 7, 'OT', 'Và Pha-rân-đa-ta, và Đa-lê-phôn, và A-xáp-ta,'),
(12843, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 9, 8, 'OT', 'Và Phô-ra-tha, và A-đa-li-a, và A-ri-đa-tha,'),
(12844, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 9, 9, 'OT', 'Và Pa-mách-ta, và A-ri-sai, và A-ri-đai, và Va-giê-xa-tha,'),
(12845, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 9, 10, 'OT', 'Mười người con trai của Ha-man, con trai của Ha-mê-tha, kẻ thù của người Do Thái, đã bị giết; nhưng họ không tra tay vào chiến lợi phẩm.'),
(12846, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 9, 11, 'OT', 'Trong ngày ấy, số người bị giết tại Su-sơ, thủ đô, đã được trình trước mặt vua.'),
(12847, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 9, 12, 'OT', 'Vua nói với bà hoàng hậu Ê-xơ-tê: "Tại Xua, kinh đô, người Do Thái đã giết và tiêu diệt năm trăm người, cùng với mười người con trai của Ha-man; vậy thì trong các tỉnh khác của vua, họ đã làm gì? Vậy điều ngươi xin là gì, để ta ban cho? Hay điều ngươi yêu cầu thêm là gì, để ta thực hiện?"'),
(12848, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 9, 13, 'OT', 'Bấy giờ Ê-xơ-tê nói: Nếu điều đó đẹp lòng vua, xin cho phép người Do-thái ở trong Xua để ngày mai cũng làm theo luật lệ ngày nay, và treo mười người con của Ha-man trên cây gỗ.'),
(12849, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 9, 14, 'OT', 'Vua truyền lệnh thực hiện điều đó, và sắc lệnh được ban hành tại Su-sơ; còn mười người con trai của Ha-man thì bị treo cổ.'),
(12850, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 9, 15, 'OT', 'Dân Y-sơ-ra-ên ở trong Xua đã nhóm hiệp lại cả ngày mười bốn tháng A-đa, và giết ba trăm người tại Xua; nhưng họ không tra tay vào chiến lợi phẩm.'),
(12851, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 9, 16, 'OT', 'Còn các người Do-thái khác trong các tỉnh của vua thì nhóm lại, đứng lên tự vệ, được yên nghỉ khỏi kẻ thù mình, và giết những kẻ ghét họ bảy mươi lăm ngàn người, nhưng không hề đụng đến chiến lợi phẩm.'),
(12852, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 9, 17, 'OT', 'Vào ngày mười ba tháng A-đa; còn ngày mười bốn tháng ấy thì họ nghỉ ngơi, và làm ngày ấy thành ngày tiệc tùng và vui mừng.'),
(12853, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 9, 18, 'OT', 'Những người Do Thái ở Xua đã tụ họp vào ngày mười ba và ngày mười bốn của tháng ấy; rồi vào ngày mười lăm của tháng ấy họ nghỉ ngơi và lấy ngày đó làm ngày tiệc vui vẻ.'),
(12854, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 9, 19, 'OT', 'Vì vậy, các người Do Thái sống ở các làng mạc, ở những thành không có vách thành, cử hành ngày mười bốn tháng A-đa, làm một ngày vui mừng, ăn tiệc, ngày lễ tốt lành, và gửi tặng phẩm vật từ người này đến người kia.'),
(12855, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 9, 20, 'OT', 'Mô-rắc-hai đã chép những điều này, rồi sai các thơ đến cho mọi người Do Thái ở tất cả các tỉnh của vua A-suê-ru-sơ, những người gần và những người xa.'),
(12856, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 9, 21, 'OT', 'thiết lập điều này cho họ, để họ giữ ngày mười bốn tháng A-đa và ngày mười lăm trong tháng đó, mỗi năm một lần.'),
(12857, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 9, 22, 'OT', 'là những ngày mà người Do Thái được nghỉ ngơi khỏi kẻ thù mình, và tháng mà tình cảnh của họ đã đổi từ nỗi buồn sang vui mừng, từ tang chế sang một ngày lễ tốt lành, để lập nên những ngày ấy làm ngày tiệc mừng và vui vẻ, cùng trao tặng quà bánh cho nhau và bố thí cho kẻ nghèo khó.'),
(12858, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 9, 23, 'OT', 'Người Do Thái nhận lấy điều mà họ đã khởi sự làm và điều mà Mạc-đô-chê đã viết cho họ.'),
(12859, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 9, 24, 'OT', 'Vì Ha-man, con trai của Ha-mê-đa-tha, người A-gát, là kẻ thù của mọi người Do Thái, đã toan tính tiêu diệt toàn thể dân Do Thái, và đã gieo thăm (Pur), tức là xổ số, để diệt trừ và hủy diệt họ.'),
(12860, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 9, 25, 'OT', 'Khi nàng đến trước mặt vua, vua truyền bằng các bức thư rằng mưu ác mà hắn đã toan tính chống lại người Do Thái phải đổ lại trên đầu chính hắn, và hắn cùng các con trai của hắn phải bị treo lên cây gỗ.'),
(12861, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 9, 26, 'OT', 'Vì vậy, họ gọi những ngày này là Phu-rim, theo tên gọi Phu. Vì lý do này, theo mọi lời trong bức thư này, và những điều họ đã thấy xảy đến cho mình, và những điều đã giáng xuống trên họ,'),
(12862, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 9, 27, 'OT', 'Người Do-thái đã cam kết và nhận lấy điều nầy trên chính mình, trên dòng dõi họ, và trên mọi người gia nhập cùng họ, không được phép bỏ qua, phải luôn giữ hai ngày nầy theo đúng văn bản và đúng thời gian của chúng, mỗi năm một lần.'),
(12863, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 9, 28, 'OT', 'Và những ngày này sẽ được ghi nhớ và giữ kính trong mọi thế hệ, mọi gia đình, mọi tỉnh, và mọi thành phố; những ngày lễ Phu-rim cần không bao giờ bị loại bỏ khỏi vòng người Do-thái, và kỷ niệm về chúng sẽ không bao giờ chấm dứt nơi dòng dõi họ.'),
(12864, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 9, 29, 'OT', 'Hoàng hậu Ê-xơ-tê, con gái của A-bi-hai, và Mạc-đô-chai người Do Thái đã viết, với mọi quyền uy, để xác nhận bức thư thứ hai về lễ Phu-rim này.'),
(12865, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 9, 30, 'OT', 'Ông sai các bức thư đến toàn thể người Do Thái, đến một trăm hai mươi bảy tỉnh của vương quốc A-suê-ru, với những lời về sự hòa bình và chân lý.'),
(12866, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 9, 31, 'OT', 'để lập định những ngày lễ Phu-ri-mô này theo đúng thời kỳ của chúng, y như điều mà Mạc-đô-chai người Do-thái và bà Ê-xơ-tê hoàng hậu đã lập định cho họ, và y như điều mà họ đã quyết định cho chính mình và cho dòng dõi mình về những điều liên quan đến các kỳ ăn chay và tiếng kêu cứu của họ.'),
(12867, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 9, 32, 'OT', 'Lời của bà Ê-xơ-tê đã xác nhận những điều nầy về lễ Pơ-ru-im, và điều đó đã được chép vào sách.'),
(12868, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 10, 1, 'OT', 'Vua A-suê-ru đã đặt một khoản thuế trên đất và các đảo của biển.'),
(12869, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 10, 2, 'OT', 'Vả lại, mọi việc quyền năng và oai hùng của vua, cùng sự tường thuật về sự vinh hiển lớn lao của Mạc-đô-chai mà nhà vua đã nâng cao, há chẳng chép trong sách sử ký các vua xứ Mê-đi và Ba-tư sao?'),
(12870, 17, 'GOI_vi', 'GOI_vi', 'vi', 'EST', 10, 3, 'OT', 'Vì Mô-rđô-chai, người Do Thái, là người thứ hai sau vua A-suê-ru, rất có thế lực đối với người Do Thái và được phần đông anh em mình yêu mến; người tìm điều tốt lành cho dân mình và nói lời hòa bình cho toàn thể dòng dõi mình.'),
(12871, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 1, 1, 'OT', 'Tại trong xứ Uùt-xơ có một người tên là Gióp; người ấy vốn trọn vẹn và ngay thẳng, kính sợ Đức Chúa Trời và lánh khỏi điều ác.'),
(12872, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 1, 2, 'OT', 'Sinh được bảy con trai và ba con gái;'),
(12873, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 1, 3, 'OT', 'Vật súc của người gồm bảy ngàn chiên, ba ngàn lạc đà, năm trăm cặp bò, năm trăm lừa cái, và đầy tớ rất nhiều; người ấy trở nên người lớn hơn hết trong các con trai phương Đông.'),
(12874, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 1, 4, 'OT', 'Các con trai người thường đi ăn tiệc, mỗi người thay phiên nhau đãi tiệc trong nhà mình; rồi sai mời ba chị em gái mình đến ăn và uống cùng mình.'),
(12875, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 1, 5, 'OT', 'Khi các ngày yến tiệc đã trọn, thì Gióp sai người đi khiến các con cái mình được thánh hóa; người dậy sớm vào buổi sáng, dâng những của lễ thiêu tùy theo số lượng tất cả các con mình; vì Gióp nói: "Biết đâu các con ta đã phạm tội và trong lòng từ chối Đức Chúa Trời chăng." Gióp làm như vậy trọn các ngày.'),
(12876, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 1, 6, 'OT', 'Một ngày kia, các con trai của Đức Chúa Trời đến đứng trước mặt Đức Giê-hô-va, và Sa-tan cũng đến giữa họ.'),
(12877, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 1, 7, 'OT', 'Đức Giê-hô-va phán cùng Sa-tan rằng: "Ngươi từ đâu đến?" Sa-tan thưa cùng Đức Giê-hô-va và thưa rằng: "Tôi đã đi vòng quanh trên đất và đi dạo trên đó."'),
(12878, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 1, 8, 'OT', 'Đức Giê-hô-va phán cùng Sa-tan rằng: Ngươi đã để lòng mình trên tôi tớ ta là Gióp chưa? Vì chẳng có ai giống như người trên đất, một người trọn vẹn và ngay thẳng, kính sợ Đức Chúa Trời và lánh khỏi điều ác.'),
(12879, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 1, 9, 'OT', 'Sa-tan đáp cùng Đức Giê-hô-va rằng: "Gióp há kính sợ Đức Chúa Trời không vì điều gì sao?"'),
(12880, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 1, 10, 'OT', 'Chẳng phải Ngài đã dựng một hàng rào bảo vệ quanh người ấy, quanh nhà người ấy và quanh mọi điều thuộc về người ấy sao? Công việc của tay người ấy, Ngài đã ban phước, và gia súc người ấy sinh sôi nảy nở khắp đất.'),
(12881, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 1, 11, 'OT', 'Nhưng bây giờ xin Ngài hãy giơ tay Ngài ra, và đụng đến tất cả những gì người có; nếu không, người sẽ phỉ báng Ngài trước mặt.'),
(12882, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 1, 12, 'OT', 'Đức Giê-hô-va phán cùng Sa-tan: Nầy, tất cả những gì người có đều phó trong tay ngươi; nhưng chớ tra tay vào chính mình người. Rồi Sa-tan lui ra khỏi mặt Đức Giê-hô-va.'),
(12883, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 1, 13, 'OT', 'Một ngày kia, các con trai và con gái người đang ăn uống rượu tại nhà người anh cả của chúng.'),
(12884, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 1, 14, 'OT', 'Một thiên sứ đến cùng ông Gióp và nói: Bò đang cày, lừa đang ăn cỏ gần bên cạnh chúng,'),
(12885, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 1, 15, 'OT', 'Dân Sê-ba xông vào, cướp lấy tất cả, và dùng lưỡi gươm giết các đầy tớ; chỉ mình tôi thoát khỏi để báo tin cho ông.'),
(12886, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 1, 16, 'OT', 'Người nầy còn đang nói, thì một người khác đến và nói: Lửa của Đức Chúa Trời từ trên trời giáng xuống, thiêu đốt các bầy chiên và các người đầy tớ, nuốt hết bọn họ; chỉ mình tôi thoát khỏi để báo tin cho ông.'),
(12887, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 1, 17, 'OT', 'Người nầy còn đang nói, thì một người khác đến và nói: Dân Canh-đê chia thành ba nhóm, xông vào đàn lạc đà, cướp lấy chúng, và dùng gươm giết các đầy tớ; chỉ có một mình tôi thoát khỏi để báo cho ông biết.'),
(12888, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 1, 18, 'OT', 'Người nầy còn đang nói, thì người khác đến và nói: Các con trai và con gái ngươi đang ăn uống và uống rượu tại nhà anh cả của chúng nó,'),
(12889, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 1, 19, 'OT', 'Nầy, một luồng gió lớn từ phía xa hoang mạc thổi tới, đụng vào bốn góc ngôi nhà, khiến nó sập xuống đè các người trẻ tuổi, và họ chết cả; chỉ một mình tôi trốn thoát để báo tin cho ông.'),
(12890, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 1, 20, 'OT', 'Ông Gióp chổi dậy, xé áo mình, cạo đầu, rồi phủ phục xuống đất và thờ lạy,'),
(12891, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 1, 21, 'OT', 'Tôi trần truồng ra khỏi lòng mẹ tôi, và trần truồng tôi sẽ trở về đó; Đức Giê-hô-va ban cho, Đức Giê-hô-va đã cất đi; đáng ngợi khen danh Đức Giê-hô-va!'),
(12892, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 1, 22, 'OT', 'Trong mọi điều ấy, ông Gióp không phạm tội, cũng không nói lời vu khống cùng Đức Chúa Trời.'),
(12893, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 2, 1, 'OT', 'Một ngày kia, các con trai của Đức Chúa Trời đến đứng trước mặt Đức Giê-hô-va, và Sa-tan cũng đến giữa họ để đứng trước mặt Đức Giê-hô-va.'),
(12894, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 2, 2, 'OT', 'Đức Giê-hô-va phán cùng Sa-tan: "Ngươi từ đâu đến?" Sa-tan thưa cùng Đức Giê-hô-va rằng: "Tôi từ đi dạo trên đất và đi dạo khắp nơi ấy."'),
(12895, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 2, 3, 'OT', 'Đức Giê-hô-va phán cùng Sa-tan rằng: Ngươi có để lòng vào tôi tớ ta là Gióp chăng? Vì trên đất không ai giống như người, một người trọn vẹn, ngay thẳng, kính sợ Đức Chúa Trời và lánh khỏi điều ác; người vẫn còn giữ vững sự ngay thẳng mình, mặc dầu ngươi xúi giục ta để tiêu diệt người vô cớ.'),
(12896, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 2, 4, 'OT', 'Sa-tan đáp cùng Đức Giê-hô-va rằng: Da đổi da, mọi vật mà người ta có, đều trao thế cho mạng sống mình.'),
(12897, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 2, 5, 'OT', 'Nhưng bây giờ xin Ngài hãy giơ tay ra, chạm đến xương và thịt người; nếu không, người sẽ chúc phước cho Ngài trước mặt Ngài.'),
(12898, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 2, 6, 'OT', 'Đức Giê-hô-va phán cùng Sa-tan rằng: Kìa, người ở trong tay ngươi; nhưng hãy giữ mạng sống người.'),
(12899, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 2, 7, 'OT', 'Sa-tan bèn lui ra khỏi trước mặt Đức Giê-hô-va, và đánh Gióp bằng một bệnh ung nhọt ác liệt, từ lòng bàn chân cho đến đỉnh đầu.'),
(12900, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 2, 8, 'OT', 'Gióp lấy một miếng sành để cạo mình, và ngồi giữa đống tro.'),
(12901, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 2, 9, 'OT', 'Vợ người nói với người: "Ông còn giữ sự trọn vẹn của mình mãi sao? Hãy chúc phỉ báng Đức Chúa Trời và chết đi!"'),
(12902, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 2, 10, 'OT', 'Người nói với nàng: "Ngươi nói như một người đàn bà ngu dại. Chúng ta nhận điều lành từ tay Đức Chúa Trời, lẽ nào lại không nhận điều dữ sao?" Trong mọi việc đó, ông Gióp không phạm tội bởi môi miệng mình.'),
(12903, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 2, 11, 'OT', 'Ba người bạn của ông Gióp là Ê-li-pha người Thê-man, Binh-đát người Su-a, và Sô-pha người Na-a-ma, nghe được mọi điều tai họa nặng nề đã xảy đến cho ông, liền hẹn cùng nhau từ nơi mình ở mà đến, để đi đến thăm và an ủi ông.'),
(12904, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 2, 12, 'OT', 'Nhìn từ xa, họ không nhận biết ông; họ cất tiếng khóc lớn, mỗi người xé áo mình, và lấy bụi ném lên trời, rải trên đầu mình.'),
(12905, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 2, 13, 'OT', 'Vậy họ ngồi xuống đất cùng người bảy ngày bảy đêm, và không ai nói với người một lời nào, vì họ thấy nỗi đau của người thật quá lớn.'),
(12906, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 3, 1, 'OT', 'Sau điều ấy, ông Gióp mở miệng mình và nguyền rủa ngày sinh của ông.'),
(12907, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 3, 2, 'OT', 'Gióp cất tiếng than rằng:'),
(12908, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 3, 3, 'OT', 'Ngày ta sinh ra, nguyện ngày ấy bị tiêu diệt; và đêm đã nói: "Đã mang thai một con trai," nguyện đêm ấy cũng bị tiêu diệt!'),
(12909, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 3, 4, 'OT', 'Nguyện ngày ấy trở nên tối tăm! Đừng tìm kiếm nó từ nơi cao, và ánh sáng chớ chiếu trên nó!'),
(12910, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 3, 5, 'OT', 'Tối tăm và bóng sự chết hãy nuốt chửng nó; mây đen hãy phủ lấy nó; bóng đêm hãy khiến nó kinh khiếp như thể những ngày bi thảm.'),
(12911, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 3, 6, 'OT', 'Nguyện đêm ấy bị bóng tối nuốt lấy; chớ cho nó hiệp với các ngày của năm; chớ cho nó vào số các tháng!'),
(12912, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 3, 7, 'OT', 'Nguyện cho đêm ấy trở nên hoang vu, đừng có tiếng reo vui nào vang ra trong nó!'),
(12913, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 3, 8, 'OT', 'Hãy nguyền rủa nó đi, những kẻ nguyền rủa ngày, những kẻ sắp sửa đánh thức Lê-vi-a-than.'),
(12914, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 3, 9, 'OT', 'Nguyện các ngôi sao trên trời của đêm ấy bị tối tăm; nguyện nó trông đợi ánh sáng nhưng không thấy, và nguyện nó không nhìn thấy ánh rạng đông.'),
(12915, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 3, 10, 'OT', 'Vì nó đã không khép cửa bụng tôi, cũng chẳng giấu nỗi đau khỏi mắt tôi.'),
(12916, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 3, 11, 'OT', 'Tại sao tôi không chết từ trong lòng mẹ? Tại sao lại ra khỏi bụng mẹ rồi phải tắt hơi?'),
(12917, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 3, 12, 'OT', 'Cớ sao hai đầu gối đỡ tôi, và vú nào nuôi tôi bú?'),
(12918, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 3, 13, 'OT', 'Vì giờ đây tôi đã nằm xuống và được yên lặng, lúc ấy tôi đã ngủ thì đã được an nghỉ.'),
(12919, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 3, 14, 'OT', 'cùng các vua và các mưu sĩ của đất, những kẻ đã xây cho mình những lâu đài đổ nát'),
(12920, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 3, 15, 'OT', 'Hoặc cùng các quan lớn có vàng, làm đầy nhà mình bằng bạc.'),
(12921, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 3, 16, 'OT', 'Hoặc tôi chẳng hề có, như một thai nhi chôn vùi, giống các con trẻ không thấy ánh sáng.'),
(12922, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 3, 17, 'OT', 'Ở đó, kẻ ác ngừng gây rối loạn, và những kẻ kiệt sức được an nghỉ.'),
(12923, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 3, 18, 'OT', 'Cùng nhau, những kẻ bị giam được an nghỉ, chẳng còn nghe tiếng kẻ đốc công nữa.'),
(12924, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 3, 19, 'OT', 'Người bé nhỏ và người lớn đều ở đó, và kẻ tôi mọi được tự do khỏi chủ mình.'),
(12925, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 3, 20, 'OT', 'Tại sao ban ánh sáng cho kẻ đau khổ, và sự sống cho kẻ lòng đầy cay đắng?'),
(12926, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 3, 21, 'OT', 'Những kẻ mong chờ cái chết mà nó không đến, và tìm kiếm nó như tìm kho báu giấu kín;'),
(12927, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 3, 22, 'OT', 'vui mừng và hớn hở khi tìm được mồ mả,'),
(12928, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 3, 23, 'OT', 'Cho người nào đường lối bị che khuất, và Đức Chúa Trời vây phủ quanh người ấy?'),
(12929, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 3, 24, 'OT', 'Vì trước khi đến bữa ăn, tiếng rên siết của tôi đã nổi lên, và tiếng gào thét của tôi tuôn ra như nước.'),
(12930, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 3, 25, 'OT', 'Vì điều tôi sợ hãi đã đến trên tôi; điều tôi kinh khủng đã xảy ra cho tôi.'),
(12931, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 3, 26, 'OT', 'Tôi chẳng được yên, chẳng được lặng, chẳng được nghỉ ngơi, mà sự xao xuyến đã đến.'),
(12932, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 4, 1, 'OT', 'Ê-li-pha người Thê-man đáp và nói rằng:'),
(12933, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 4, 2, 'OT', 'Nếu có điều gì ông thử nói ra, liệu ông sẽ thấy mệt sao? Nhưng ai có thể cầm giữ mình không nói được?'),
(12934, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 4, 3, 'OT', 'Này, ông đã khuyên dạy nhiều người, và làm cho những tay yếu đuối được vững mạnh.'),
(12935, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 4, 4, 'OT', 'Lời nói của ông đã nâng đỡ kẻ vấp ngã, và đầu gối run rẩy, ông đã làm cho vững chắc.'),
(12936, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 4, 5, 'OT', 'Nhưng bây giờ điều đó xảy đến cho ông, ông lại nản lòng; nó xảy đến ông, thì ông bối rối.'),
(12937, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 4, 6, 'OT', 'Sự kính sợ Đức Chúa Trời há chẳng phải là chỗ nương náu của ông sao? Sự trông cậy của ông và sự ngay thẳng của các đường lối ông?'),
(12938, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 4, 7, 'OT', 'Hãy nhớ lại, ai là người ngay lành bị tiêu vong? Và người ngay thẳng ở đâu bị diệt mất?'),
(12939, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 4, 8, 'OT', 'Theo điều tôi đã thấy, kẻ cày điều gian ác và gieo điều khổ nạn sẽ gặt lấy nó.'),
(12940, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 4, 9, 'OT', 'Bởi hơi thở của Đức Chúa Trời chúng sẽ hư mất, và bởi luồng khí từ cơn thịnh nộ của Ngài, chúng sẽ tiêu tan.'),
(12941, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 4, 10, 'OT', 'Tiếng gầm của sư tử và tiếng gầm của sư tử cái đã im bặt, và nanh của các sư tử con bị gãy.'),
(12942, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 4, 11, 'OT', 'Sư tử chết mất vì thiếu mồi, và các con sư tử bị tản lạc.'),
(12943, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 4, 12, 'OT', 'Một lời nói thầm đã lén truyền đến tôi, tai tôi vẳng nghe tiếng thì thầm của nó.'),
(12944, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 4, 13, 'OT', 'Vào những sợi mỏng manh của các thị kiến ban đêm, khi một cơn mê man rơi xuống trên loài người,'),
(12945, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 4, 14, 'OT', 'Sự kinh khủng khiến tôi run sợ, và sự run rẩy làm cho các xương tôi rụng rời.'),
(12946, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 4, 15, 'OT', 'Một hơi thở đi ngang qua mặt tôi; các lông tóc trên thân thể tôi liền dựng đứng lên.'),
(12947, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 4, 16, 'OT', 'Một hình dạng đứng trước mắt tôi; tôi không nhận biết được diện mạo của nó. Có tiếng thì thầm nhẹ nhỏ, tôi nghe thấy:'),
(12948, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 4, 17, 'OT', 'Người phàm há được công bình hơn Đức Chúa Trời sao? Người đàn ông há được trong sạch hơn Đấng Tạo hóa mình sao?'),
(12949, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 4, 18, 'OT', 'Kìa, Đức Chúa Trời không tin cậy các đầy tớ Ngài, và Ngài quy trách điều điên dại cho các thiên sứ Ngài.'),
(12950, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 4, 19, 'OT', 'Huống chi những kẻ ở nhà bằng đất sét, nền móng của chúng đặt trên bụi đất, bị nghiền nát trước sâu mọt!'),
(12951, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 4, 20, 'OT', 'Chúng bị đánh bại từ sáng đến chiều; chẳng ai để ý, chúng bị tiêu diệt mà không ai lưu tâm.'),
(12952, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 4, 21, 'OT', 'Dây chằng của chúng há chẳng bị rút khỏi chúng sao? Chúng chết, mà không được khôn ngoan.'),
(12953, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 5, 1, 'OT', 'Hãy kêu lên! Có ai đáp lời ngươi chăng? Ngươi sẽ quay về cùng ai trong các đấng thánh?'),
(12954, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 5, 2, 'OT', 'Vì cơn thịnh nộ giết người ngu dại, và lòng ghen tuông làm chết kẻ nhẹ dạ.'),
(12955, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 5, 3, 'OT', 'Tôi đã thấy kẻ ngu muội đâm rễ; nhưng ta bỗng nhiên rủa nơi ở của người ấy.'),
(12956, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 5, 4, 'OT', 'Con cái nó bị xa cách khỏi sự cứu giúp; chúng bị áp bức nơi cửa thành, và không ai cứu nó.'),
(12957, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 5, 5, 'OT', 'Mùa gặt của người đói sẽ ăn, và kẻ đói khát sẽ lấy nó về các hốc đá; còn của cải chúng bị gió khô nuốt mất.'),
(12958, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 5, 6, 'OT', 'Vì tai họa chẳng sinh ra từ bụi đất, và sự khốn khổ chẳng mọc lên từ nơi đất đai.'),
(12959, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 5, 7, 'OT', 'Vì loài người sinh ra để gặp khốn khổ, và con cái của tia lửa vươn mình như chim bay.'),
(12960, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 5, 8, 'OT', 'Nhưng tôi sẽ tìm cầu Đức Chúa Trời, và ta sẽ đặt lời biện luận của tôi nơi Đức Chúa Trời.'),
(12961, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 5, 9, 'OT', 'Làm những công việc lớn lao không thể dò xét, và những điều kỳ diệu không thể đếm được.'),
(12962, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 5, 10, 'OT', 'Đấng ban mưa trên mặt đất, và sai nước chảy trên mặt các nơi ngoài đồng.'),
(12963, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 5, 11, 'OT', 'Nâng kẻ thấp hèn lên cao, và cứu những kẻ buồn rầu được an toàn.'),
(12964, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 5, 12, 'OT', 'Người làm phá sản những mưu kế của kẻ xảo quyệt, khiến tay chúng nó không thực hiện được điều khôn ngoan.'),
(12965, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 5, 13, 'OT', 'Bắt những người khôn ngoan bằng mưu mẹo của chúng, và mưu kế của kẻ xảo quyệt bị phá hủy ngay tức thì.'),
(12966, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 5, 14, 'OT', 'Ban ngày chúng gặp tối tăm, và giữa trưa chúng mò mẫm như trong đêm.'),
(12967, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 5, 15, 'OT', 'Đức Chúa Trời cứu kẻ nghèo khỏi gươm nơi miệng chúng nó, và khỏi tay kẻ mạnh.'),
(12968, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 5, 16, 'OT', 'Vì vậy, kẻ yếu đuối có sự trông đợi, và kẻ ác phải ngậm miệng lại.'),
(12969, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 5, 17, 'OT', 'Kìa, người ta thật có phước khi Đức Chúa Trời sửa dạy; vậy, chớ khinh sự sửa phạt của Đấng Toàn Năng.'),
(12970, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 5, 18, 'OT', 'Vì chính Ngài làm đau, rồi lại băng bó; đánh đập, rồi tay Ngài chữa lành.'),
(12971, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 5, 19, 'OT', 'Người sẽ cứu ngươi trong sáu cơn khốn khổ, và trong cơn thứ bảy, tai họa sẽ không đụng đến ngươi.'),
(12972, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 5, 20, 'OT', 'Trong cơn đói kém, Ngài sẽ giải cứu ngươi khỏi sự chết; và trong thời chiến tranh, khỏi tay gươm.'),
(12973, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 5, 21, 'OT', 'Ông sẽ được giấu khuất khỏi tai hại của lưỡi; và sẽ không sợ hãi khi tai họa đến.'),
(12974, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 5, 22, 'OT', 'Ông sẽ cười thầm trước sự cướp phá và đói kém, và sẽ không sợ các loài vật trên đất;'),
(12975, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 5, 23, 'OT', 'Vì ngươi lập giao ước với các hòn đá ngoài đồng ruộng, và các thú vật của đồng sẽ sống hòa thuận với ngươi.'),
(12976, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 5, 24, 'OT', 'Ông sẽ biết rằng sự bình an trong trại mình; ông sẽ kiểm tra lều mình và chẳng thấy thiếu điều gì.'),
(12977, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 5, 25, 'OT', 'Ngươi sẽ biết rằng dòng dõi ngươi sẽ đông đảo, và thế hệ sau ngươi sẽ như cỏ mọc trên đất.'),
(12978, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 5, 26, 'OT', 'Ông sẽ vào phần mộ trong tuổi già, như một đống lúa được gặt đúng thì.'),
(12979, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 5, 27, 'OT', 'Nầy, chúng tôi đã tìm hiểu điều đó, quả thật như vậy; hãy nghe và nhận biết để làm ích cho mình.'),
(12980, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 6, 1, 'OT', 'Gióp đáp và nói rằng:'),
(12981, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 6, 2, 'OT', 'Ôi! Giá như nỗi khổ tôi được đặt trên bàn cân, và các tai nạn tôi được đặt cùng trên đĩa cân!'),
(12982, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 6, 3, 'OT', 'Vì hiện giờ nỗi đau của tôi nặng hơn cát biển; nên các lời tôi nói ra trở nên cuồng loạn.'),
(12983, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 6, 4, 'OT', 'Vì các mũi tên của Đức Chúa Trời nhằm vào tôi, và lòng tôi uống nọc độc của chúng; sự kinh hãi của Đức Chúa Trời giương hàng nghịch cùng tôi.'),
(12984, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 6, 5, 'OT', 'Lừa rừng há kêu la vì cỏ non sao? Bò đực há gầm lên khi có thức ăn của nó?'),
(12985, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 6, 6, 'OT', 'Thức gì nhạt nhẽo thì ai chịu ăn không muối? Còn nước ép của cây rau chua thì có vị chi cho được?'),
(12986, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 6, 7, 'OT', 'Linh hồn tôi từ chối không chịu động đến; ấy là những vật như thức ăn ghê tởm của tôi.'),
(12987, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 6, 8, 'OT', 'Ôi! Chớ gì lời cầu xin tôi được ứng nghiệm, và Đức Chúa Trời ban cho tôi điều tôi mong đợi!'),
(12988, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 6, 9, 'OT', 'Nguyện rằng Đức Chúa Trời đẹp lòng nghiền nát tôi, buông tay Ngài ra nghiền ép tôi!'),
(12989, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 6, 10, 'OT', 'Thì nỗi buồn tôi còn được an ủi, và giữa cơn đau tôi vẫn kiên cường; Ngài chẳng thương xót, vì tôi không chối bỏ lời của Đấng Thánh.'),
(12990, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 6, 11, 'OT', 'Sức lực tôi được bao nhiêu, mà tôi phải đợi? Và cuối cùng tôi sẽ ra sao, mà tôi phải kéo dài lòng mình?'),
(12991, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 6, 12, 'OT', 'Sức lực tôi há phải là sức lực của đá sao? Thịt tôi há phải là đồng?'),
(12992, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 6, 13, 'OT', 'Trong tôi chẳng có sự giúp đỡ nào, và sự thông sáng đã lìa khỏi tôi.'),
(12993, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 6, 14, 'OT', 'Bạn bè phải tỏ lòng thương xót kẻ gặp khốn khổ, kẻo người ấy bỏ sự kính sợ Đấng Toàn Năng.'),
(12994, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 6, 15, 'OT', 'Anh em ta đã phản ta như một con suối, như các dòng chảy của các con sông khi nước đã cạn.'),
(12995, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 6, 16, 'OT', 'Bị đục vì nước đá, tuyết ẩn khuất nằm trong lòng.'),
(12996, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 6, 17, 'OT', 'Khi nắng nóng làm cho chúng khô cạn, thì giữa cơn nóng chúng bị tiêu tan khỏi chỗ chúng nằm.'),
(12997, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 6, 18, 'OT', 'Các lối đi của chúng bị rối loạn, chúng đi lên sa mạc rồi tiêu vong.'),
(12998, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 6, 19, 'OT', 'Các đoàn lữ hành Thê-ma nhìn ngóng, các kẻ đi đường Sê-ba trông đợi nó.'),
(12999, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 6, 20, 'OT', 'Chúng hổ thẹn vì đã tin cậy; chúng đến nơi đó và phải xấu hổ.'),
(13000, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 6, 21, 'OT', 'Bây giờ các anh đã chẳng ra gì, các anh thấy điều đáng sợ và run rẩy.'),
(13001, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 6, 22, 'OT', 'Tôi há đã nói: "Hãy ban cho tôi, lấy của cải các ngươi mà hối lộ vì tôi sao?"'),
(13002, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 6, 23, 'OT', 'Hoặc giải cứu tôi khỏi tay kẻ khốn khổ, và chuộc tôi khỏi tay những kẻ bạo ác?'),
(13003, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 6, 24, 'OT', 'Hãy dạy dỗ tôi, tôi sẽ làm thinh; hãy cho tôi hiểu tôi đã sai lầm nơi đâu.'),
(13004, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 6, 25, 'OT', 'Lời ngay thẳng thật là đắng cay! Còn lời quở trách của các bạn thì có thuyết phục được điều chi?'),
(13005, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 6, 26, 'OT', 'Các lời trách móc các ngươi định để dạy dỗ, còn các lời nói của người tuyệt vọng thì chỉ như gió mà thôi.'),
(13006, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 6, 27, 'OT', 'Thậm chí các ngươi còn hãm hại kẻ mồ côi và đào hầm để gài người bạn mình.'),
(13007, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 6, 28, 'OT', 'Vậy bây giờ, nếu các bạn muốn, hãy nhìn tôi; tôi nào dám nói dối trước mặt các bạn đâu.'),
(13008, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 6, 29, 'OT', 'Xin hãy trở lại, chớ nên làm điều bất chính; hãy xét lại, vì lý do của tôi là điều công bình.'),
(13009, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 6, 30, 'OT', 'Lưỡi tôi há có điều gian ác chăng? Hay họng tôi không nhận biết sự dữ?'),
(13010, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 7, 1, 'OT', 'Người đời há chẳng phải là một đạo quân trên đất sao? Các ngày đời người há chẳng giống như các ngày của người làm công?'),
(13011, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 7, 2, 'OT', 'Như kẻ tôi mọi khao khát bóng râm, như người làm thuê mong đợi phần thưởng của mình,'),
(13012, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 7, 3, 'OT', 'Như vậy tôi được phần các tháng hư không, và những đêm cực nhọc được định cho tôi.'),
(13013, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 7, 4, 'OT', 'Nếu tôi nằm xuống, thì nói rằng: Chừng nào tôi mới chỗi dậy? Tôi ngóng đợi chiều tà, nhưng lại no nê những lần lảo đảo cho đến rạng đông.'),
(13014, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 7, 5, 'OT', 'Thịt tôi mặc toàn giun và bụi đất; da tôi nứt nẻ, rồi bị bỏ rơi.'),
(13015, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 7, 6, 'OT', 'Các ngày tôi qua mau hơn thoi đưa, tiêu tan đi mà chẳng còn hy vọng.'),
(13016, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 7, 7, 'OT', 'Lạy Đức Giê-hô-va, xin nhớ đời sống tôi chỉ là hơi thở; mắt tôi sẽ không còn trở lại để thấy điều tốt lành nữa.'),
(13017, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 7, 8, 'OT', 'Mắt đã thấy tôi sẽ chẳng còn nhìn tôi nữa; mắt Ngài nhìn tôi, nhưng tôi sẽ không còn tồn tại.'),
(13018, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 7, 9, 'OT', 'Mây tan đi và mất tích, kẻ nào xuống âm phủ cũng không hề trở lên.'),
(13019, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 7, 10, 'OT', 'Không trở về nhà mình nữa, và nơi người ở chẳng còn nhận biết người.'),
(13020, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 7, 11, 'OT', 'Vì vậy, tôi không nén được miệng mình; tôi sẽ nói trong sự khốn khổ của tâm thần tôi; tôi sẽ than thở trong cay đắng của linh hồn tôi.'),
(13021, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 7, 12, 'OT', 'Tôi há là biển hay là rồng biển, mà Ngài phải đặt người canh giữ tôi?'),
(13022, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 7, 13, 'OT', 'Khi tôi nói: Chiếc giường sẽ an ủi tôi, cái nằm sẽ nâng đỡ lời than thở của tôi.'),
(13023, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 7, 14, 'OT', 'Rồi Ngài dùng chiêm bao khiến tôi bồn chồn, và dùng dị tượng làm tôi kinh hãi.'),
(13024, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 7, 15, 'OT', 'Nên linh hồn tôi chọn sự chết, ưa chết hơn là còn sống trong xương cốt tôi.'),
(13025, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 7, 16, 'OT', 'Tôi ghét bỏ, chẳng muốn sống đời đời; xin buông tôi ra, vì các ngày tôi chỉ là hư không.'),
(13026, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 7, 17, 'OT', 'Loài người là gì mà Ngài coi trọng, và sao Ngài để lòng Ngài hướng về người?'),
(13027, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 7, 18, 'OT', 'Hằng sáng sớm, Ngài thăm viếng người; từng lúc, từng lúc, Ngài thử thách người.'),
(13028, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 7, 19, 'OT', 'Nhân sao Ngài không xây mắt khỏi tôi, không để tôi được yên cho đến khi nuốt nước miếng tôi?'),
(13029, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 7, 20, 'OT', 'Lạy Đấng gìn giữ loài người, tôi đã phạm tội chi mà phải làm điều nghịch cùng Ngài? Nhân sao Ngài đặt tôi làm mục tiêu tấn công, khiến tôi trở thành gánh nặng cho chính mình?'),
(13030, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 7, 21, 'OT', 'Cớ sao Ngài không mang gánh tội ác tôi, và bỏ qua sự gian tà tôi? Vì ngay bây giờ tôi sẽ nằm xuống trong bụi đất; Ngài sẽ tìm tôi, nhưng tôi sẽ không còn nữa.'),
(13031, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 8, 1, 'OT', 'Binh-đát, người Su-a, bèn đáp và nói rằng:'),
(13032, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 8, 2, 'OT', 'Ông sẽ nói những điều nầy cho đến chừng nào, và hơi thở của đấng hùng dũng sẽ làm cho lời của miệng ông như gió bão đến chừng nào?'),
(13033, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 8, 3, 'OT', 'Đức Chúa Trời há sẽ làm cho sự xét xử trở nên sai lệch sao? Đấng Toàn Năng há sẽ làm cho sự công bình trở nên sai trái sao?'),
(13034, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 8, 4, 'OT', 'Nếu con cái ngươi phạm tội cùng Ngài, thì Ngài đã đuổi chúng nó ra vì tội ác của chúng nó.'),
(13035, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 8, 5, 'OT', 'Nếu ông chuyên tâm tìm kiếm Đức Chúa Trời, và nài xin Đấng Toàn Năng,'),
(13036, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 8, 6, 'OT', 'Nếu ngươi trong sạch và ngay thẳng, chắc chắn bây giờ Đức Giê-hô-va sẽ thức tỉnh vì ngươi, và phục hồi nơi ở công bình của ngươi.'),
(13037, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 8, 7, 'OT', 'Ban đầu tuy nhỏ bé, nhưng về sau sẽ phát triển rất lớn.'),
(13038, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 8, 8, 'OT', 'Hãy hỏi thử đời xưa, và hãy tra khảo các tổ phụ.'),
(13039, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 8, 9, 'OT', 'Vì chúng ta chỉ mới có hôm qua và chẳng biết gì; các ngày đời ta trên đất khác nào cái bóng.'),
(13040, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 8, 10, 'OT', 'Chúng chẳng sẽ dạy ngươi, nói với ngươi sao? Và từ trong lòng mình, chúng sẽ đưa ra những lời nói.'),
(13041, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 8, 11, 'OT', 'Sậy có mọc lên được nếu không có bùn lầy chăng? Lác có mọc lên nếu không có nước chăng?'),
(13042, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 8, 12, 'OT', 'Khi nó còn ở trong bụi lá của nó thì chưa bị hái, và trước mọi cỏ xanh đã bị héo khô.'),
(13043, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 8, 13, 'OT', 'Đường lối của mọi kẻ quên Đức Chúa Trời là như vậy; sự trông đợi của kẻ gian ác sẽ bị tiêu mất.'),
(13044, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 8, 14, 'OT', 'Người nương tựa vào điều làm cho mình thất vọng; nơi mình tin cậy giống như nhà nhện.'),
(13045, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 8, 15, 'OT', 'Nó nương tựa vào nhà mình, nhưng nhà ấy không đứng vững; nó níu giữ, nhưng chẳng tồn tại được.'),
(13046, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 8, 16, 'OT', 'Trước mặt trời, nó vẫn tươi tốt; nơi vườn nó, dây leo của nó mọc ra.'),
(13047, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 8, 17, 'OT', 'Rễ nó quấn quanh đống đá, nhà nó nằm giữa đống đá.'),
(13048, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 8, 18, 'OT', 'Nếu nó bị nhổ khỏi chỗ nó, thì chính chỗ ấy sẽ chối bỏ nó, mà rằng: Ta chẳng thấy ngươi!'),
(13049, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 8, 19, 'OT', 'Kìa, nó vui thích trong đường lối mình; nhưng từ bụi đất, người khác sẽ mọc lên.'),
(13050, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 8, 20, 'OT', 'Kìa, Đức Chúa Trời chẳng từ chối người trọn vẹn, cũng chẳng nắm tay kẻ gian ác.'),
(13051, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 8, 21, 'OT', 'Cho đến khi Ngài làm đầy miệng ngươi bằng tiếng cười, và môi ngươi bằng tiếng reo mừng.'),
(13052, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 8, 22, 'OT', 'Kẻ thù ngươi sẽ mặc lấy sự hổ thẹn, và lều trại của kẻ ác sẽ không còn.'),
(13053, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 1, 'OT', 'Gióp đáp và nói rằng:'),
(13054, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 2, 'OT', 'Quả thật, tôi biết rằng ấy là như vậy; Nhưng loài người nào được công bình trước mặt Đức Chúa Trời?'),
(13055, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 3, 'OT', 'Nếu Ngài muốn tranh luận với người ấy, thì một trong ngàn lần, loài người chẳng thể đáp lại được.'),
(13056, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 4, 'OT', 'Đức Chúa Trời có lòng khôn sáng và sức lực mạnh mẽ; ai cứng cỏi cùng Ngài mà được bình an?'),
(13057, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 5, 'OT', 'Ngài làm cho các núi dời đi mà chúng chẳng hay biết, Ngài đánh đổ chúng trong cơn thịnh nộ của Ngài.'),
(13058, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 6, 'OT', 'Kẻ làm cho đất rung chuyển khỏi nền tảng nó, và các trụ đỡ nó đều lay chuyển;'),
(13059, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 7, 'OT', 'Ngài phán cùng mặt trời, nó không mọc; Ngài đóng ấn trên các ngôi sao;'),
(13060, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 8, 'OT', 'Chính Ngài một mình trải các từng trời ra, và bước đi trên các ngọn sóng biển.'),
(13061, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 9, 'OT', 'Ngài làm nên sao Bắc Đẩu, sao Lạp Hộ, và sao Tua Rua, cùng những buồng của phương Nam.'),
(13062, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 10, 'OT', 'Làm những việc lớn lao không thể dò xét, và những điều kỳ diệu vô số kể.'),
(13063, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 11, 'OT', 'Kìa, Ngài đi ngang qua gần tôi, mà tôi chẳng thấy; Ngài bước qua, nhưng tôi không nhận biết được Ngài.'),
(13064, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 12, 'OT', 'Kìa, nếu Ngài vồ lấy, ai sẽ đẩy lại được? Ai sẽ nói với Ngài: Ngài làm chi vậy?'),
(13065, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 13, 'OT', 'Đức Chúa Trời không rút lại cơn thịnh nộ của Ngài; dưới Ngài, những kẻ giúp đỡ Ra-háp đều phải cúi mình.'),
(13066, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 14, 'OT', 'Phương chi tôi đáp lại cùng Ngài, tôi phải chọn lời lẽ tranh luận với Ngài!'),
(13067, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 15, 'OT', 'Dù khi tôi công bình, tôi cũng không dám trả lời Ngài; tôi phải nài xin ơn của Đấng xét xử tôi.'),
(13068, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 16, 'OT', 'Nếu tôi kêu cầu và Ngài đáp lời tôi, tôi cũng không tin rằng Ngài lắng nghe tiếng tôi.'),
(13069, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 17, 'OT', 'Vì Ngài nghiền nát tôi trong cơn gió bão, và càng làm cho những vết thương của tôi thêm nhiều cách vô cớ.'),
(13070, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 18, 'OT', 'Ngài không cho phép tôi lấy lại hơi thở Ngài, nhưng làm cho tôi no đầy những điều đắng cay.'),
(13071, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 19, 'OT', 'Nếu tranh luận về sức mạnh, nầy, Ngài rất quyền năng; nếu xét đến sự xét đoán, thì ai sẽ triệu thỉnh ta ra tòa?'),
(13072, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 20, 'OT', 'Dẫu cho tôi công bình, miệng tôi sẽ lên án tôi; tôi trọn vẹn, mà nó khiến tôi trở nên què quặt.'),
(13073, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 21, 'OT', 'Dẫu tôi vô tội, tôi không tự biết mình; tôi khinh bỉ mạng sống tôi.'),
(13074, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 22, 'OT', 'Một điều ấy là như nhau; bởi vậy tôi đã nói: Kẻ trọn lành và kẻ ác Đức Chúa Trời đều tiêu diệt.'),
(13075, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 23, 'OT', 'Nếu tai họa bất ngờ giết chết, thì Ngài chế nhạo sự thử thách của người vô tội.'),
(13076, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 24, 'OT', 'Đất bị trao vào tay kẻ ác; Ngài che khuất mặt các quan xét của nó; nếu không phải Ngài, vậy thì ai?'),
(13077, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 25, 'OT', 'Các ngày đời tôi chóng qua hơn người chạy; chúng trốn tránh, không thấy điều thiện lành.'),
(13078, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 26, 'OT', 'Chúng qua mau như tàu biển, như chim ưng lao đến mồi.'),
(13079, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 27, 'OT', 'Nếu tôi nói: Ta sẽ quên lời than thở của ta, bỏ đi nét mặt buồn rầu và vui vẻ lên,'),
(13080, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 28, 'OT', 'Tôi sợ hãi mọi nỗi đau của tôi, biết rằng Ngài sẽ không xem tôi là vô tội.'),
(13081, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 29, 'OT', 'Tôi có tội, vậy sao tôi còn phải làm cho mình mệt nhọc vô ích?'),
(13082, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 30, 'OT', 'Dù tôi có tắm rửa bằng tuyết, và lấy tro mà giặt tay tôi cho sạch,'),
(13083, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 31, 'OT', 'Bấy giờ Ngài sẽ nhúng tôi vào hầm sâu, khiến chính áo mặc tôi cũng ghê tởm tôi.'),
(13084, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 32, 'OT', 'Vì Ngài không phải là người như tôi, để tôi có thể đáp lại Ngài, để chúng ta cùng đến tòa án.'),
(13085, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 33, 'OT', 'Không có đấng nào phân xử giữa chúng ta, đặt tay người ấy trên cả hai chúng ta.'),
(13086, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 34, 'OT', 'Ước gì Ngài rút cây roi của Ngài khỏi tôi, và sự kinh khiếp của Ngài đừng làm tôi rối loạn nữa;'),
(13087, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 9, 35, 'OT', 'Tôi sẽ nói, và chẳng sợ Ngài; vì tôi không phải là kẻ như vậy trước mặt Ngài.'),
(13088, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 10, 1, 'OT', 'Linh hồn tôi chán ghét mạng sống tôi; tôi sẽ để lời than vãn của tôi tự do; tôi sẽ nói trong cay đắng của lòng tôi.'),
(13089, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 10, 2, 'OT', 'Tôi nói cùng Đức Chúa Trời: Xin chớ đoán tôi là có tội; Xin chỉ cho tôi biết vì sao Ngài tranh luận cùng tôi.'),
(13090, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 10, 3, 'OT', 'Há phải điều thiện cho Ngài khi ép bức, khinh bỉ công việc do tay Ngài làm ra, và chiếu sáng cho mưu kế của kẻ ác chăng?'),
(13091, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 10, 4, 'OT', 'Đức Chúa Trời có mắt bằng thịt hay sao? Ngài thấy như loài người thấy chăng?'),
(13092, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 10, 5, 'OT', 'Các ngày của Ngài há như ngày loài người sao? Các năm của Ngài há như năm loài người vậy?'),
(13093, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 10, 6, 'OT', 'Sao Ngài tìm kiếm tội ác tôi, tra xét tội lỗi tôi?'),
(13094, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 10, 7, 'OT', 'Dầu Chúa biết tôi không gian ác, và chẳng có ai giải thoát khỏi tay Chúa?'),
(13095, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 10, 8, 'OT', 'Tay Ngài đã tạo nên tôi và làm cho tôi trọn vẹn; thế mà nay Ngài lại hủy diệt tôi!'),
(13096, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 10, 9, 'OT', 'Xin hãy nhớ rằng Ngài đã làm tôi như bằng bùn; và Ngài sẽ khiến tôi trở về bụi đất sao?'),
(13097, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 10, 10, 'OT', 'Chúa há chẳng đổ tôi ra như sữa, khiến tôi đông đặc như pho mát sao?'),
(13098, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 10, 11, 'OT', 'Ngài lấy da và thịt mà mặc cho tôi, lấy xương và gân mà bao bọc tôi.'),
(13099, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 10, 12, 'OT', 'Ngài đã ban cho tôi sự sống và sự nhân từ, và sự giám sát của Ngài đã gìn giữ linh hồn tôi.'),
(13100, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 10, 13, 'OT', 'Nhưng những điều nầy, Ngài đã giấu trong lòng Ngài; tôi biết rằng điều ấy ở nơi Ngài.'),
(13101, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 10, 14, 'OT', 'Nếu tôi phạm tội, Ngài gìn giữ tôi; nhưng từ tội lỗi tôi, Ngài không làm cho tôi trong sạch.'),
(13102, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 10, 15, 'OT', 'Nếu tôi có phạm tội, thì khốn cho tôi thay! Còn nếu tôi công bình, tôi cũng chẳng ngước đầu lên được, Vì đã đầy dẫy sỉ nhục và thấy nỗi khốn khổ tôi.'),
(13103, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 10, 16, 'OT', 'Nếu tôi ngước đầu lên, Ngài sẽ săn đuổi tôi như một con sư tử, và lại làm những điều kỳ lạ trên tôi.'),
(13104, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 10, 17, 'OT', 'Người đổi mới các nhân chứng chống lại tôi, và gia tăng cơn thịnh nộ cùng tôi; những điều bất hạnh nối tiếp nhau và đạo quân hãm hại tôi.'),
(13105, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 10, 18, 'OT', 'Vậy sao Ngài rút tôi ra khỏi lòng mẹ? Giá tôi đã chết đi, và chẳng con mắt nào thấy tôi!'),
(13106, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 10, 19, 'OT', 'Như thể tôi chưa từng hiện hữu, sẽ trở về bụi đất ngay từ lúc lọt lòng mẹ!'),
(13107, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 10, 20, 'OT', 'Các ngày tôi há chẳng phải ngắn ngủi sao? Vậy, xin Ngài thôi đừng để mắt nhìn tôi nữa, để tôi được an ủi một chút,'),
(13108, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 10, 21, 'OT', 'Trước khi tôi đi và không trở lại, đến đất tối tăm và bóng sự chết;'),
(13109, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 10, 22, 'OT', 'Đất tối tăm như mực, là miền bóng sự chết, không có trật tự, và ánh sáng cũng như tối tăm.'),
(13110, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 11, 1, 'OT', 'Sô-pha, người Na-a-ma, đáp và nói rằng:'),
(13111, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 11, 2, 'OT', 'Lời nói nhiều há chẳng bị chất vấn sao? Người lắm mồm há được xưng là công bình?'),
(13112, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 11, 3, 'OT', 'Các lời nói của ngươi khiến kẻ chết phải nín lặng sao? Ngươi nhạo báng, mà không ai quở trách ngươi sao?'),
(13113, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 11, 4, 'OT', 'Ông nói cùng Đức Chúa Trời rằng: Lời dạy tôi trong sạch, tôi không ô uế trước mặt Ngài.'),
(13114, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 11, 5, 'OT', 'Nhưng ước gì Đức Chúa Trời phán và mở miệng Ngài nói chuyện cùng ngươi,'),
(13115, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 11, 6, 'OT', 'Ngài sẽ bày tỏ cho ông những điều bí ẩn của sự khôn ngoan, vì nó có hai lần bội phần thông hiểu; vậy hãy biết rằng Đức Chúa Trời đã gán cho ông ít hơn tội ác của ông.'),
(13116, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 11, 7, 'OT', 'Há phải ngươi dò xét được sự sâu nhiệm của Đức Chúa Trời, hay tìm đến tận cùng của Đấng Toàn Năng sao?'),
(13117, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 11, 8, 'OT', 'Cao hơn các từng trời, ông làm sao làm được? Sâu hơn âm phủ, ông biết sao được?'),
(13118, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 11, 9, 'OT', 'Chiều dài của nó vượt quá cỡ đất, và bề rộng của nó rộng hơn biển cả.'),
(13119, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 11, 10, 'OT', 'Nếu Đức Chúa Trời đi ngang qua, bắt giữ, và triệu tập một phiên toà, thì ai có thể ngăn cản Ngài được?'),
(13120, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 11, 11, 'OT', 'Vì Ngài biết những kẻ giả dối, thấy gian ác mà chẳng suy xét.'),
(13121, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 11, 12, 'OT', 'Nhưng người nào ngu dốt sẽ được thông sáng, và người nào như lừa rừng sẽ được sinh ra làm người.'),
(13122, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 11, 13, 'OT', 'Nếu ngươi sửa lòng mình cho ngay thẳng, và giơ tay hướng về Ngài;'),
(13123, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 11, 14, 'OT', 'Nếu trong tay ông có điều gian ác, hãy xa cách nó đi, chớ để sự bất chính cư ngụ trong trại ông.'),
(13124, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 11, 15, 'OT', 'Bấy giờ, ngươi sẽ ngước mặt lên, không còn tì vít; và ngươi sẽ được vững vàng, chẳng còn sợ hãi.'),
(13125, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 11, 16, 'OT', 'Ngươi sẽ quên nỗi khổ mình, và nhớ đến nó như nước đã chảy qua.'),
(13126, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 11, 17, 'OT', 'Đời ngươi sẽ rạng rỡ hơn lúc giữa trưa; tuy bây giờ còn tăm tối, sau sẽ trở nên như buổi sáng.'),
(13127, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 11, 18, 'OT', 'Ông sẽ tin tưởng vì còn có sự trông đợi, và được an toàn, ông sẽ nằm nghỉ.'),
(13128, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 11, 19, 'OT', 'Ông sẽ nằm xuống mà không ai làm cho sợ hãi, và nhiều người sẽ tìm đến ông.'),
(13129, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 11, 20, 'OT', 'Nhưng mắt của kẻ ác sẽ mờ đi, và nơi ẩn náu của chúng sẽ tiêu tan; điều mong đợi của chúng là hơi thở lìa khỏi xác.'),
(13130, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 12, 1, 'OT', 'Gióp đáp và nói rằng:'),
(13131, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 12, 2, 'OT', 'Thật vậy, các ngươi mới là người, và sự khôn ngoan sẽ chết theo các ngươi!'),
(13132, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 12, 3, 'OT', 'Ta cũng có lòng như các ngươi, chẳng kém các ngươi đâu; ai là người không biết những điều như vậy?'),
(13133, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 12, 4, 'OT', 'Ta là trò cười cho bạn hữu ta, người kêu cầu Đức Chúa Trời và được Ngài đáp lời; người công bình, người trọn vẹn đã trở nên trò cười!'),
(13134, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 12, 5, 'OT', 'Kẻ được an toàn khinh bỉ tai họa; tai họa sẵn sàng giáng trên kẻ sắp vấp ngã.'),
(13135, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 12, 6, 'OT', 'Những trại của kẻ cướp được thịnh vượng, và những kẻ chọc giận Đức Chúa Trời lại ở bình an vô sự, tức những kẻ mà Đức Chúa Trời đặt của cải dư dật trong tay họ.'),
(13136, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 12, 7, 'OT', 'Hãy hỏi loài vật trên đất, chúng sẽ dạy ngươi; hãy hỏi chim trời, chúng sẽ nói cho ngươi biết;'),
(13137, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 12, 8, 'OT', 'Hoặc hãy nói với cỏ cây dưới đất, nó sẽ dạy ngươi; và các loài cá biển sẽ thuật lại cho ngươi biết.'),
(13138, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 12, 9, 'OT', 'Ai chẳng biết trong các loài nầy, rằng tay của Đức Chúa Trời đã làm nên điều nầy?'),
(13139, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 12, 10, 'OT', 'Trong tay Ngài là sự sống của mọi vật sống, và hơi thở của mọi loài người.'),
(13140, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 12, 11, 'OT', 'Chẳng phải lỗ tai thử lời nói, và khẩu vị nếm thức ăn sao?'),
(13141, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 12, 12, 'OT', 'Người già có sự khôn ngoan, và tuổi thọ đem lại sự thông sáng.'),
(13142, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 12, 13, 'OT', 'Cùng Đức Chúa Trời có sự khôn ngoan và quyền năng; mưu luận và thông sáng đều thuộc về Ngài.'),
(13143, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 12, 14, 'OT', 'Nầy, Ngài phá hủy, chẳng ai xây dựng lại được; Ngài giam một người, chẳng ai mở ra được.'),
(13144, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 12, 15, 'OT', 'Nầy, nếu Ngài ngăn nước lại thì nước sẽ khô cạn; nếu Ngài buông nó ra, nó sẽ phá hủy đất.'),
(13145, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 12, 16, 'OT', 'Quyền năng và sự thông sáng thuộc về Ngài; kẻ lầm lạc và kẻ làm cho người khác lầm lạc đều thuộc về Ngài.'),
(13146, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 12, 17, 'OT', 'Dẫn những kẻ mưu kế đi làm tù nhân, khiến các quan xét trở nên điên dại.'),
(13147, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 12, 18, 'OT', 'Mở xiềng cho các vua, lại siết đai lưng của chúng;'),
(13148, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 12, 19, 'OT', 'Người làm cho các thầy tế lễ bị lưu đày, và lật đổ những người kiên cố.'),
(13149, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 12, 20, 'OT', 'Người cất lấy lời nói của kẻ trung tín, và tước đi sự thông sáng của người già cả.'),
(13150, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 12, 21, 'OT', 'Người đổ sự sỉ nhục trên những người quý tộc, và tháo gỡ đai lưng của những người hùng cường.'),
(13151, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 12, 22, 'OT', 'Người tiết lộ những điều sâu thẳm từ trong bóng tối, và đem bóng sự chết ra ánh sáng.'),
(13152, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 12, 23, 'OT', 'Làm cho các dân tộc lớn mạnh, rồi lại tiêu diệt; làm cho các nước lan rộng ra, rồi lại thu nhỏ chúng lại.'),
(13153, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 12, 24, 'OT', 'Người cất lấy lòng của các thủ lãnh các dân trên đất, khiến chúng đi lang thang trong nơi hoang vu không đường lối.'),
(13154, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 12, 25, 'OT', 'Chúng mò mẫm trong tối tăm, không có ánh sáng; Ngài khiến chúng đi xiêu tó như người say rượu.'),
(13155, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 13, 1, 'OT', 'Nầy, mắt tôi đã thấy các điều đó, tai tôi đã nghe và hiểu rõ.'),
(13156, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 13, 2, 'OT', 'Điều gì các ngươi biết, ta cũng biết; ta chẳng thua kém các ngươi đâu.'),
(13157, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 13, 3, 'OT', 'Nhưng ta sẽ nói chuyện cùng Đức Chúa Trời, và tranh luận với Đức Chúa Trời.'),
(13158, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 13, 4, 'OT', 'Nhưng các ngươi là những kẻ pha trộn lời dối trá, thảy đều là thầy thuốc vô ích.'),
(13159, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 13, 5, 'OT', 'Ước gì các ngươi nín lặng! Thật vậy, điều đó sẽ là sự khôn ngoan cho các ngươi.'),
(13160, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 13, 6, 'OT', 'Hãy nghe lời biện luận của tôi, Khá lắng nghe những điều tranh luận từ môi miệng tôi.'),
(13161, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 13, 7, 'OT', 'Các ngươi há sẽ nói điều bất công với Đức Chúa Trời sao? Các ngươi há sẽ vì Ngài mà nói điều gian dối sao?'),
(13162, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 13, 8, 'OT', 'Các ngươi há sẽ thiên vị cho Đức Chúa Trời, hay là tranh tụng cho Ngài sao?'),
(13163, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 13, 9, 'OT', 'Các ngươi tưởng tốt chăng nếu Ngài dò xét các ngươi? Các ngươi sẽ đối xử với Ngài như đối xử với loài người sao?'),
(13164, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 13, 10, 'OT', 'Người sẽ quở trách các ngươi; nếu các ngươi lén tây vị ai, thì sao?'),
(13165, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 13, 11, 'OT', 'Sự oai nghi của Đức Chúa Trời há chẳng khiến các ngươi sợ hãi sao? Và sự kinh hãi của Ngài há chẳng đổ xuống trên các ngươi sao?'),
(13166, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 13, 12, 'OT', 'Những điều các ngươi nhắc nhớ giống như những câu chuyện ngụ ngôn về tro bụi; còn các ngươi thì như những bức tường bằng đất sét.'),
(13167, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 13, 13, 'OT', 'Hãy lặng đi, khá tránh khỏi ta, để ta nói; và hãy để xảy đến cho ta điều gì đi.'),
(13168, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 13, 14, 'OT', 'Tại sao ta phải mang thịt mình nơi răng, và đặt linh hồn ta trong tay ta?'),
(13169, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 13, 15, 'OT', 'Dẫu Ngài giết tôi, tôi cũng chẳng ngóng đợi; tuy nhiên, tôi sẽ biện minh các đường lối mình trước mặt Ngài.'),
(13170, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 13, 16, 'OT', 'Cũng chính điều ấy là sự cứu rỗi của tôi; vì kẻ gian ác sẽ không được đến trước mặt Ngài.'),
(13171, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 13, 17, 'OT', 'Hãy nghe, hãy lắng nghe lời tôi, và các anh em tôi, hãy để tai các anh em tiếp nhận lời tôi.'),
(13172, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 13, 18, 'OT', 'Này, ta đã sắp đặt vụ kiện của ta; ta biết ta sẽ được tuyên công chính.'),
(13173, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 13, 19, 'OT', 'Ai là người tranh luận với ta? Bây giờ ta sẽ nín lặng và chết đi.'),
(13174, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 13, 20, 'OT', 'Chỉ xin Ngài đừng làm cho tôi hai điều nầy, bấy giờ tôi sẽ không trốn khỏi mặt Ngài.'),
(13175, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 13, 21, 'OT', 'Xin rút bàn tay Ngài khỏi tôi, và sự kinh hãi của Ngài chớ làm tôi bối rối nữa.'),
(13176, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 13, 22, 'OT', 'Hãy gọi tôi, tôi sẽ trả lời; hoặc tôi sẽ nói, và Ngài hãy đáp lại tôi.'),
(13177, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 13, 23, 'OT', 'Tội ác và tội lỗi tôi có bao nhiêu? Lỗi lầm và tội tôi là gì, xin hãy cho tôi biết.'),
(13178, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 13, 24, 'OT', 'Tại sao Ngài giấu mặt Ngài, và xem tôi như kẻ thù của Ngài?'),
(13179, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 13, 25, 'OT', 'Ngươi há muốn làm cho kẻ bị thổi bay phải khiếp sợ, và đuổi theo rơm rạ khô sao?'),
(13180, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 13, 26, 'OT', 'Vì Ngài ghi trên tôi những điều cay đắng, và khiến tôi mang các tội ác thời thanh niên tôi,'),
(13181, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 13, 27, 'OT', 'Ngài đặt xiềng nơi bàn chân tôi, và canh giữ mọi nẻo đường tôi; Ngài ghi dấu vết quanh bước chân tôi.'),
(13182, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 13, 28, 'OT', 'Người ấy bị tiêu mòn như vật mục nát, như áo bị sâu mọt gặm nhấm.'),
(13183, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 14, 1, 'OT', 'Người bởi người nữ sinh ra sống ít ngày và đầy dẫy điều lo lắng.'),
(13184, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 14, 2, 'OT', 'Sinh ra như hoa, rồi héo tàn; chạy qua như bóng, chẳng dừng lại.'),
(13185, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 14, 3, 'OT', 'Dầu vậy, Ngài há còn mở mắt mình ra sao? Và khiến tôi phải đến chịu sự xét đoán cùng Ngài sao?'),
(13186, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 14, 4, 'OT', 'Ai có thể làm cho người thanh sạch ra từ kẻ ô uế? Chẳng ai cả!'),
(13187, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 14, 5, 'OT', 'Nếu các ngày của người đã định trước, số tháng người ở nơi Ngài, Ngài đã định giới hạn cho người, mà người không thể vượt qua,'),
(13188, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 14, 6, 'OT', 'Xin hãy xây mắt khỏi người và để người được yên nghỉ, cho đến khi trọn ngày của người như kẻ làm thuê.'),
(13189, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 14, 7, 'OT', 'Vì cây cối nếu bị đốn ngã thì còn có sự trông cậy, nó sẽ mọc chồi mới ra, và nhánh nó sẽ không thôi nức.'),
(13190, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 14, 8, 'OT', 'Nếu rễ nó già đi dưới đất, và thân nó chết nơi bụi tro,'),
(13191, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 14, 9, 'OT', 'Từ hơi nước nó sẽ đâm chồi, và sinh ra bông trái như một cây mới trồng.'),
(13192, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 14, 10, 'OT', 'Người ta chết rồi suy yếu; người ta tắt hơi, thì đi đâu?'),
(13193, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 14, 11, 'OT', 'Nước chảy từ biển đi mất, và con sông bị cạn khô.'),
(13194, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 14, 12, 'OT', 'Người ta nằm xuống rồi không chổi dậy nữa; cho đến khi các từng trời không còn, người ấy cũng không thức dậy, và không ai đánh thức người ấy khỏi giấc ngủ mình.'),
(13195, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 14, 13, 'OT', 'Ôi! Chớ gì Ngài giấu tôi trong âm phủ, che khuất tôi cho đến khi cơn thịnh nộ Ngài qua đi, đặt cho tôi một kỳ hạn và nhớ lại tôi!'),
(13196, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 14, 14, 'OT', 'Người chết rồi, há còn sống lại sao? Trọn những ngày binh nghiệp tôi, tôi sẽ trông đợi, cho đến khi đến kỳ thay phiên tôi.'),
(13197, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 14, 15, 'OT', 'Ngài sẽ gọi, và tôi sẽ đáp lại; Ngài sẽ mong nhớ công việc của tay Ngài.'),
(13198, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 14, 16, 'OT', 'Nhưng bây giờ, Ngài đếm các bước chân tôi; sao Ngài không giữ gìn trên tội lỗi tôi?'),
(13199, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 14, 17, 'OT', 'Các tội ác tôi bị niêm ấn trong một cái bị, và Ngài gìn giữ tội lỗi tôi.'),
(13200, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 14, 18, 'OT', 'Nhưng núi sụp đổ thì tan ra, và tảng đá bị dời khỏi chỗ nó.'),
(13201, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 14, 19, 'OT', 'Nước làm mòn những hòn đá, lũ cuốn trôi bụi đất; cũng vậy, Ngài hủy bỏ sự trông đợi của loài người.'),
(13202, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 14, 20, 'OT', 'Ngài bắt ép nó đến trọn đời, rồi nó qua đi; Ngài đổi sắc mặt nó, và cho nó đi.'),
(13203, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 14, 21, 'OT', 'Con cái người được tôn trọng, nhưng người không biết; chúng bị hạ xuống, nhưng người chẳng hiểu gì về chúng.'),
(13204, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 14, 22, 'OT', 'Nhưng thân thể người ấy chỉ đau đớn vì chính mình người ấy, và linh hồn người ấy chỉ than khóc trên chính mình người ấy mà thôi.'),
(13205, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 1, 'OT', 'Ê-li-pha, người Thê-man, đáp rằng:'),
(13206, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 2, 'OT', 'Người khôn ngoan sẽ đáp lại bằng tri thức của thần linh mình, và làm đầy bụng mình bằng gió phương đông.'),
(13207, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 3, 'OT', 'Người há có thể lấy lời cãi lẽ mà được yên ổn, hay dùng những lời biện luận chẳng ích lợi gì để được giúp đỡ sao?'),
(13208, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 4, 'OT', 'Thật vậy, ông hủy bỏ sự kính sợ Đức Chúa Trời, và ngăn cản điều suy gẫm trước mặt Đức Chúa Trời.'),
(13209, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 5, 'OT', 'Vì tội ác ngươi dạy cho miệng ngươi nói, và ngươi chọn lưỡi của kẻ gian trá.'),
(13210, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 6, 'OT', 'Miệng ngươi sẽ lên án ngươi, chứ không phải ta; và môi ngươi sẽ chống lại ngươi.'),
(13211, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 7, 'OT', 'Ông sinh ra có phải là người đầu tiên sao? Há đã được mang đến trước các ngọn núi sao?'),
(13212, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 8, 'OT', 'Ông có nghe được điều bàn luận trong ý nhiệm của Đức Chúa Trời sao? Ông có nhận lấy sự khôn ngoan về mình riêng sao?'),
(13213, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 9, 'OT', 'Ông biết điều gì mà chúng tôi không biết? Ông hiểu điều gì mà chúng tôi lại không thông hiểu?'),
(13214, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 10, 'OT', 'Cả người bạc tóc và kẻ già cả đều ở giữa chúng tôi; tuổi đời của người lớn tuổi hơn cha ngươi.'),
(13215, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 11, 'OT', 'Sự an ủi của Đức Chúa Trời và lời nói dịu dàng đối với ông, lẽ nào là nhỏ bé đối với ông sao?'),
(13216, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 12, 'OT', 'Lòng ngươi lấy gì làm cho ngươi xúc động, và mắt ngươi nhìn thấy gì?'),
(13217, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 13, 'OT', 'Tại sao ngươi khiến tâm thần mình phản nghịch cùng Đức Chúa Trời, và để những lời ấy ra khỏi miệng mình?'),
(13218, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 14, 'OT', 'Người ta là gì mà được xem là thanh sạch? Và kẻ sinh bởi người phụ nữ làm sao có thể được xem là công bình?'),
(13219, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 15, 'OT', 'Kìa, trong các thánh đồ, Đức Chúa Trời không tin cậy, và các từng trời cũng chẳng thanh sạch trước mắt Ngài.'),
(13220, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 16, 'OT', 'Phương chi một người gớm ghiếc và đáng khinh, kẻ uống sự gian ác như nước!'),
(13221, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 17, 'OT', 'Tôi sẽ chỉ dạy ông, hãy nghe tôi; điều tôi đã thấy, tôi sẽ thuật lại,'),
(13222, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 18, 'OT', 'Là điều mà những người khôn ngoan đã chỉ dạy, và không giấu giếm khỏi tổ tiên họ;'),
(13223, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 19, 'OT', 'Chỉ riêng họ được trao đất nầy, và không một người ngoại nào đi ngang qua giữa họ.'),
(13224, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 20, 'OT', 'Trọn đời kẻ ác đều đau đớn vật vã, và số năm đã định sẵn dành cho kẻ hung ác.'),
(13225, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 21, 'OT', 'Tiếng kinh khủng vang vào tai người; đang lúc yên ổn, kẻ cướp sẽ xông đến người.'),
(13226, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 22, 'OT', 'Người không tin mình sẽ trở lại khỏi bóng tối, và bị gươm rình rập.'),
(13227, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 23, 'OT', 'Lạc lõng, người ta tìm bánh: Bánh ở đâu? Người ấy biết rằng ngày tăm tối đã sẵn trong tay mình.'),
(13228, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 24, 'OT', 'Sự gian nan và khốn khổ khiến người sợ hãi, xông vào người như một vua sẵn sàng ra trận'),
(13229, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 25, 'OT', 'Vì người đã giơ tay mình ra chống Đức Chúa Trời, và chống Đấng Toàn Năng mà phạm tội.'),
(13230, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 26, 'OT', 'Người xông thẳng đến Ngài với cổ ngẩng cao, dưới lớp khiên dày đặc của Ngài.'),
(13231, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 27, 'OT', 'Vì người lấy mỡ che mặt mình, và làm cho hai hông mình đầy đặn.'),
(13232, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 28, 'OT', 'Người đã ở những thành bị hủy hoại, những nhà không ai ở, vốn đã bị dự bị cho sự sụp đổ.'),
(13233, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 29, 'OT', 'Chẳng trở nên giàu có, và tài sản người không vững bền; chẳng lan rộng sản nghiệp mình trên đất.'),
(13234, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 30, 'OT', 'Người sẽ không tránh khỏi bóng tối; chồi non của người sẽ bị lửa làm khô héo, và người sẽ bị thổi bay đi bởi hơi thở từ miệng người.'),
(13235, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 31, 'OT', 'Đừng tin cậy vào điều hư không, kẻo bị lừa dối; vì điều hư không sẽ là phần thay thế cho nó.'),
(13236, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 32, 'OT', 'Trước kỳ người chưa đến, nó sẽ bị tiêu diệt, và nhánh nó sẽ không xanh tươi.'),
(13237, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 33, 'OT', 'Hắn sẽ làm rụng trái mình như cây nho chưa chín, và vứt bỏ hoa mình như cây ô-liu đã khô.'),
(13238, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 34, 'OT', 'Vì hội của kẻ ác bị tiêu diệt, lửa sẽ nuốt các trại của kẻ tham hối lộ.'),
(13239, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 15, 35, 'OT', 'Họ mang thai điều ác, đẻ ra sự hư không, lòng họ đầy dẫy mưu gian.'),
(13240, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 16, 1, 'OT', 'Khi ấy, ông Gióp đáp và nói rằng:'),
(13241, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 16, 2, 'OT', 'Ta đã nghe nhiều lời như thế rồi; hết thảy các ngươi đều là những kẻ an ủi đầy rẫy sự đau buồn.'),
(13242, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 16, 3, 'OT', 'Lời nói suông và thần khí ấy bao giờ mới dứt? Điều gì thúc đẩy ngươi mà ngươi phải đáp?'),
(13243, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 16, 4, 'OT', 'Ta cũng sẽ nói như các ngươi nói; nếu linh hồn các ngươi thay cho linh hồn ta, ta sẽ lập lại lời lẽ để an ủi các ngươi, và lắc đầu ngao ngán về các ngươi.'),
(13244, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 16, 5, 'OT', 'Ta sẽ dùng miệng ta làm cho các ngươi vững lòng, và lời an ủi nơi môi ta sẽ giảm bớt nỗi đau của các ngươi.'),
(13245, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 16, 6, 'OT', 'Nếu ta nói, cơn đau ta chẳng được giảm; ta làm thinh, nó nào rời khỏi ta?'),
(13246, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 16, 7, 'OT', 'Nhưng bây giờ, Đức Chúa Trời khiến tôi mệt mỏi; Ngài đã tàn hại toàn thể đoàn thể tôi.'),
(13247, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 16, 8, 'OT', 'Ngươi làm ta teo tóp lại, điều ấy làm chứng nghịch cùng ta; chính sự tàn lực của ta đứng lên chống lại ta, cáo buộc ta ngay trước mặt ta.'),
(13248, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 16, 9, 'OT', 'Cơn giận người xé tôi và ghét tôi; người nghiến răng nghịch tôi, kẻ thù tôi trừng mắt nhìn tôi.'),
(13249, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 16, 10, 'OT', 'Chúng há miệng nghịch cùng tôi, nhạo báng mà vả má tôi; chúng cùng nhau xúm lại nghịch tôi.'),
(13250, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 16, 11, 'OT', 'Đức Chúa Trời đã phó tôi cho kẻ gian ác, và nộp tôi vào tay những kẻ ác.'),
(13251, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 16, 12, 'OT', 'Tôi đang yên ổn, thì Ngài phá vỡ tôi ra; Ngài nắm lấy cổ tôi, và quật tôi xuống; Ngài đặt tôi làm mục tiêu cho Ngài.'),
(13252, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 16, 13, 'OT', 'Các chủ của tôi vây hãm tôi, đâm thủng lòng tôi và chẳng thương xót, đổ nọc độc tôi xuống đất.'),
(13253, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 16, 14, 'OT', 'Ngài xé tôi ra từng mảnh, miếng này chồng lên miếng kia, xông vào tôi như một người mạnh mẽ.'),
(13254, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 16, 15, 'OT', 'Tôi lấy vải thô may trên da tôi, và hạ sừng tôi xuống bụi đất.'),
(13255, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 16, 16, 'OT', 'Mặt tôi đỏ lên vì khóc, và trên mí mắt tôi là bóng tối sự chết.'),
(13256, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 16, 17, 'OT', 'Dù nơi tay tôi không có sự bạo ngược, và lời cầu nguyện tôi vẫn trong sạch.'),
(13257, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 16, 18, 'OT', 'Hỡi đất, chớ che huyết ta; và ước gì tiếng kêu cứu ta không có chỗ nương thân!'),
(13258, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 16, 19, 'OT', 'Kìa, ngay lúc này, Đấng làm chứng cho tôi ở trên trời, và Đấng bảo lãnh cho tôi ở nơi cao.'),
(13259, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 16, 20, 'OT', 'Các bạn hữu tôi nhạo báng tôi, còn mắt tôi khóc than hướng về Đức Chúa Trời.'),
(13260, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 16, 21, 'OT', 'Ngài sẽ khuyên bảo một người với Đức Chúa Trời, và một con người với bạn hữu mình.'),
(13261, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 16, 22, 'OT', 'Vì những năm được định sẵn thì ít ỏi, và tôi sẽ đi con đường mà tôi không trở lại.'),
(13262, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 17, 1, 'OT', 'Hơi thở tôi hao mòn, các ngày tôi đã gần tàn; mồ mả dành sẵn cho tôi!'),
(13263, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 17, 2, 'OT', 'Những kẻ chế nhạo tôi đều ở chung một chỗ, và mắt tôi phải nhìn xem sự nhục nhã của chúng.'),
(13264, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 17, 3, 'OT', 'Xin hãy làm người bảo lãnh cho tôi trước mặt Ngài; còn ai sẽ bảo lãnh cho tôi?'),
(13265, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 17, 4, 'OT', 'Vì Ngài đã che khuất lòng chúng khỏi sự thông sáng, nên Ngài sẽ không nâng chúng lên.'),
(13266, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 17, 5, 'OT', 'Ai lấy bạn hữu mình làm mồi cho sự cướp bóc, thì mắt các con nó sẽ mòn mỏi.'),
(13267, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 17, 6, 'OT', 'Nhưng Đức Chúa Trời đặt tôi làm trò cười cho dân, khiến tôi trở thành vật khinh dể trước mặt họ.'),
(13268, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 17, 7, 'OT', 'Mắt tôi mờ đi vì buồn khổ, và các bộ phận tôi đều tiêu tan như bóng tối.'),
(13269, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 17, 8, 'OT', 'Người ngay thẳng sẽ kinh ngạc về điều nầy, và kẻ thanh sạch sẽ nổi giận cùng kẻ gian ác.'),
(13270, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 17, 9, 'OT', 'Người công bình sẽ nắm giữ đường lối mình, và người có tay trong sạch sẽ càng ngày càng thêm mạnh mẽ.'),
(13271, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 17, 10, 'OT', 'Nhưng hỡi các ngươi, hết thảy khá trở lại mà đến đây; thật, ta không tìm thấy trong các ngươi một người khôn ngoan.'),
(13272, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 17, 11, 'OT', 'Các ngày tôi đã qua, các mưu toan tôi đã bị phá bỏ, phần hưởng của lòng tôi thì đã tiêu tan.'),
(13273, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 17, 12, 'OT', 'Chúng đổi đêm thành ngày; ánh sáng gần hơn trước mặt sự tối tăm.'),
(13274, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 17, 13, 'OT', 'Nếu tôi trông đợi âm phủ làm nhà tôi, nơi tối tăm tôi đã trải giường nằm tôi;'),
(13275, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 17, 14, 'OT', 'Tôi đã gọi cái huyệt là cha tôi, và sâu bọ là mẹ tôi, là chị tôi.'),
(13276, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 17, 15, 'OT', 'Vậy thì hi vọng của tôi ở đâu? Và hi vọng của tôi, ai sẽ thấy được nó?'),
(13277, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 17, 16, 'OT', 'Sự trông cậy của tôi sẽ đi xuống âm phủ, khi tôi nằm yên trong bụi đất.'),
(13278, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 18, 1, 'OT', 'Binh-đát, người Su-a, bèn đáp rằng:'),
(13279, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 18, 2, 'OT', 'Cho đến bao giờ các ông còn đặt ra những câu nói châm chọc? Hãy suy nghĩ, rồi sau đó chúng tôi sẽ nói.'),
(13280, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 18, 3, 'OT', 'Tại sao chúng ta bị kể là loài vật, bị coi là ô uế trong mắt các ngươi?'),
(13281, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 18, 4, 'OT', 'Người xé lòng mình trong cơn thịnh nộ của mình; há vì ngươi mà đất sẽ bị bỏ hoang, và hòn đá bị dời khỏi chỗ nó sao?'),
(13282, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 18, 5, 'OT', 'Cũng vậy, ánh sáng của kẻ ác sẽ tắt, và ngọn lửa của nó sẽ không chiếu sáng nữa.'),
(13283, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 18, 6, 'OT', 'Ánh sáng trở nên tối tăm trong lều người ấy, ngọn đèn trên đầu người ấy sẽ tắt.'),
(13284, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 18, 7, 'OT', 'Các bước của hắn sẽ bị thu hẹp, và mưu kế của hắn sẽ làm hắn ngã xuống.'),
(13285, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 18, 8, 'OT', 'Vì hắn đã bị sa chân vào lưới, và bước đi trên cái bẫy.'),
(13286, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 18, 9, 'OT', 'Bẫy sẽ chụp lấy gót chân nó, và lưới siết chặt nó.'),
(13287, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 18, 10, 'OT', 'Sợi dây lừa nó dưới đất, và bẫy rập nó trên lối đi.'),
(13288, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 18, 11, 'OT', 'Từ bốn phía, sự kinh khủng khiến người bối rối; chúng xua đuổi người và rải rác dưới chân người.'),
(13289, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 18, 12, 'OT', 'Sức lực nó yếu vì đói khát, và tai họa đã sẵn sàng chờ bên cạnh nó.'),
(13290, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 18, 13, 'OT', 'Các chi thể hắn sẽ bị tiêu diệt, chính con đầu lòng của sự chết sẽ nuốt chửng hắn.'),
(13291, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 18, 14, 'OT', 'Người sẽ bị lôi ra khỏi trại mình, nơi người tin cậy, và bị xua đến vua của sự kinh hãi.'),
(13292, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 18, 15, 'OT', 'Người không thuộc về nó sẽ ở trong lều nó, diêm sinh sẽ rải ra trên nơi ở của nó.'),
(13293, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 18, 16, 'OT', 'Dưới rễ hắn thì khô héo, trên ngọn thì mùa gặt bị chặt đi.'),
(13294, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 18, 17, 'OT', 'Dấu vết người ấy bị tiêu diệt khỏi đất, và danh người ấy không còn lưu lại trên mặt đất.'),
(13295, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 18, 18, 'OT', 'Người ta sẽ xô đuổi nó khỏi ánh sáng vào chốn tối tăm, và khỏi thế gian này người ta sẽ trục xuất nó.'),
(13296, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 18, 19, 'OT', 'Người sẽ không có con trai hay cháu trai giữa dân tộc mình, cũng không có ai sót lại trong nơi cư ngụ của người.'),
(13297, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 18, 20, 'OT', 'Những người đến sau kinh hãi về ngày đời hắn; những kẻ trước đó kinh hoàng, tóc dựng đứng lên.'),
(13298, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 18, 21, 'OT', 'Nhưng đây là những nơi ở của kẻ ác, và đây là chỗ của người không biết Đức Chúa Trời.'),
(13299, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 19, 1, 'OT', 'Gióp đáp và nói rằng:'),
(13300, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 19, 2, 'OT', 'Bao lâu nữa các ngươi còn làm đau lòng tôi, và lấy lời lẽ mà đè ép tôi?'),
(13301, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 19, 3, 'OT', 'Mười lần các ngươi sỉ nhục ta, không biết hổ thẹn; các ngươi cứ khinh miệt ta mãi.'),
(13302, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 19, 4, 'OT', 'Dầu cho ta thực sự lầm lạc, sự lầm lạc của ta vẫn ở nơi ta.'),
(13303, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 19, 5, 'OT', 'Nếu thật các ngươi muốn lên mình ta, và lấy sự sỉ nhục ta mà bắt lỗi ta,'),
(13304, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 19, 6, 'OT', 'Hãy biết rằng ấy là Đức Chúa Trời đã đối xử bất công với tôi, và lưới Ngài bao phủ lấy tôi.'),
(13305, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 19, 7, 'OT', 'Nầy, tôi kêu la về sự bạo tàn, nhưng không được đáp lời; tôi kêu cứu, nhưng không có sự công bình.'),
(13306, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 19, 8, 'OT', 'Người phong tỏa con đường tôi, khiến tôi không thể đi qua; Ngài đặt bóng tối trên các lối đi của tôi.'),
(13307, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 19, 9, 'OT', 'Ngài đã bóc lột sự vinh quang tôi, và cất mão triều khỏi đầu tôi.'),
(13308, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 19, 10, 'OT', 'Ngài làm tôi khốn khổ tứ phía, và tôi phải đi; Ngài nhổ hy vọng của tôi lên như cây.'),
(13309, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 19, 11, 'OT', 'Cơn thịnh nộ của Ngài nổi lên nghịch cùng tôi, và Ngài xem tôi như kẻ thù nghịch với Ngài.'),
(13310, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 19, 12, 'OT', 'Các đạo binh của Ngài cùng kéo đến, trải đường trên con đường chúng nó mà đến hãm đánh tôi, và đóng trại vây quanh lều tôi.'),
(13311, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 19, 13, 'OT', 'Anh em ta khiến ta xa lìa, và những người quen biết ta hoàn toàn trở nên xa lạ với ta.'),
(13312, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 19, 14, 'OT', 'Các người thân cận tôi đều bỏ tôi xa, và những kẻ quen biết tôi đã quên tôi.'),
(13313, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 19, 15, 'OT', 'Những người ở nhà tôi và các tớ gái tôi coi tôi như người xa lạ; tôi đã trở nên người ngoại trước mắt họ.'),
(13314, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 19, 16, 'OT', 'Tôi kêu gọi kẻ tôi tớ tôi, nhưng nó không trả lời; tôi lấy miệng mình nài xin nó, mà nó cũng chẳng đoái hoài.'),
(13315, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 19, 17, 'OT', 'Hơi thở tôi trở nên kinh tởm cho vợ tôi, và những đứa con của lòng tôi ghét bỏ tôi.'),
(13316, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 19, 18, 'OT', 'Ngay cả những kẻ vô đạo cũng khinh tôi; tôi đứng lên, chúng lại buông lời sỉ nhục tôi.'),
(13317, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 19, 19, 'OT', 'Tất cả những người thân cận đều ghê tởm tôi, và những người tôi yêu dấu đã chống lại tôi.'),
(13318, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 19, 20, 'OT', 'Xương cốt tôi bám chặt vào da thịt tôi, và tôi chỉ còn thoát được với lớp da bọc quanh răng tôi mà thôi.'),
(13319, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 19, 21, 'OT', 'Hỡi các bạn hữu ta, hãy thương xót ta, hãy thương xót ta! Vì tay Đức Chúa Trời đã đánh ta.'),
(13320, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 19, 22, 'OT', 'Cớ sao các ngươi bắt bớ tôi như Đức Chúa Trời, và chưa no nê vì thịt tôi?'),
(13321, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 19, 23, 'OT', 'Ôi! Chớ gì các lời tôi được chép lại! Chớ gì chúng được ghi trong một quyển sách!'),
(13322, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 19, 24, 'OT', 'Ôi, ước gì những lời nầy được viết bằng bút sắt và chì, và khắc sâu vào đá cho đến đời đời!'),
(13323, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 19, 25, 'OT', 'Nhưng tôi biết Đấng cứu chuộc tôi vẫn sống, và cuối cùng Ngài sẽ đứng trên đống tro.'),
(13324, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 19, 26, 'OT', 'Sau khi da tôi bị tan nát, từ xác thịt tôi sẽ nhìn thấy Đức Chúa Trời;'),
(13325, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 19, 27, 'OT', 'Tôi sẽ thấy Đức Chúa Trời, chính tôi sẽ thấy Ngài, mắt tôi sẽ nhìn thấy Ngài, chứ không phải người khác; lòng tôi hao mòn trong chính mình tôi.'),
(13326, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 19, 28, 'OT', 'Nếu các ngươi nói: "Chúng ta sẽ khuấy rối người ấy ra sao?" Thì rễ của lời nói ấy lại tìm thấy nơi ta.'),
(13327, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 19, 29, 'OT', 'Hãy sợ hãi trước lưỡi gươm, vì cơn thịnh nộ do tội ác gây ra gươm, để các ngươi biết rằng có sự xét đoán.'),
(13328, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 20, 1, 'OT', 'Xô-pha người Na-a-ma đáp rằng:'),
(13329, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 20, 2, 'OT', 'Vì cớ ấy, các ý tưởng của tôi khiến tôi đáp lại, và sự bối rối trong tôi khiến tôi xúc động.'),
(13330, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 20, 3, 'OT', 'Tôi đã nghe lời trách móc làm tôi hổ thẹn; và thần linh trong trí hiểu biết tôi đáp lời tôi.'),
(13331, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 20, 4, 'OT', 'Hãy biết rằng từ khi loài người được đặt trên đất, điều này đã xảy ra.'),
(13332, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 20, 5, 'OT', 'Vì sự reo vui của kẻ ác chỉ gần bên, và niềm vui của người gian ác chỉ tồn tại trong chốc lát.'),
(13333, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 20, 6, 'OT', 'Nếu sự kiêu ngạo nó bay lên tận trời, và đầu nó chạm đến mây,'),
(13334, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 20, 7, 'OT', 'Như phân bón, nó sẽ mãi mãi bị tiêu tan; những kẻ thấy nó sẽ nói: "Nó đâu rồi?"'),
(13335, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 20, 8, 'OT', 'Như giấc mơ, sáng ra không còn thấy nữa; như hình ảnh trong đêm, sẽ không ai tìm được.'),
(13336, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 20, 9, 'OT', 'Mắt đã thấy nó sẽ không thấy nữa, nơi nó ở cũng chẳng còn nhìn thấy nó.'),
(13337, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 20, 10, 'OT', 'Con cái nó sẽ phải xin ơn kẻ nghèo, và tay nó phải hoàn lại sự bất công mà nó đã gây ra.'),
(13338, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 20, 11, 'OT', 'Xương cốt nó đầy sức lực thời thanh xuân, nhưng rồi sẽ nằm xuống cùng bụi đất.'),
(13339, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 20, 12, 'OT', 'Dẫu sự ác lấy làm ngọt ngào trong miệng nó, dẫu giấu dưới lưỡi nó,'),
(13340, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 20, 13, 'OT', 'Dẫu nó yêu mến điều ác và không từ bỏ, lại giữ điều ấy trong miệng mình,'),
(13341, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 20, 14, 'OT', 'Thức ăn nó trong lòng bị biến đổi, trở thành nọc rắn hổ trong bụng nó.'),
(13342, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 20, 15, 'OT', 'Của cải nó nuốt vào, phải mửa ra; Đức Chúa Trời khiến nó trục xuất khỏi bụng nó.'),
(13343, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 20, 16, 'OT', 'Nó sẽ mút sữa đầu của rắn hổ; lưỡi của rắn lục sẽ giết nó.'),
(13344, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 20, 17, 'OT', 'Chẳng thấy các dòng sông, các suối nước chảy ra mật ong và sữa béo.'),
(13345, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 20, 18, 'OT', 'Hắn phải trả lại hoa lợi của công lao mình, không được nuốt trọn; phải hoàn trả theo giá trị đổi lấy, không được hưởng dùng.'),
(13346, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 20, 19, 'OT', 'Vì nó đã nghiền nát kẻ nghèo, bỏ mặc người khốn khổ; cướp lấy nhà, nhưng không xây dựng nó.'),
(13347, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 20, 20, 'OT', 'Vì nó không biết được sự yên ổn trong lòng mình, nên nó sẽ không giữ lại được điều gì mình tham muốn.'),
(13348, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 20, 21, 'OT', 'Không còn sót lại gì cho việc ăn uống của nó; bởi đó, sự thịnh vượng của nó không tồn tại.'),
(13349, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 20, 22, 'OT', 'Khi đã đầy đủ, lòng tham nó sẽ dấy lên; mọi bàn tay khốn khổ sẽ chống lại nó.'),
(13350, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 20, 23, 'OT', 'Ngài sẽ khiến bụng nó đầy dẫy, sai cơn thạnh nộ Ngài hãm mình nó, và trong lúc nó ăn, Ngài sẽ giáng cơn giận Ngài trên mình nó.'),
(13351, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 20, 24, 'OT', 'Nó sẽ chạy trốn khỏi cây giáo bằng sắt, cây cung bằng đồng sẽ bắn trúng nó.'),
(13352, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 20, 25, 'OT', 'Lưỡi gươm tra ra khỏi bụng nó, và tia chớp từ nỗi cay đắng của nó sẽ xông trên nó; các sự kinh khủng xông đánh nó.'),
(13353, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 20, 26, 'OT', 'Tất cả sự tối tăm bị cất giấu dành cho kho tàng nó; lửa không do người ta thổi sẽ nuốt chửng nó; kẻ sót lại trong trại nó sẽ bị tiêu diệt.'),
(13354, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 20, 27, 'OT', 'Các tầng trời sẽ tiết lộ tội ác nó, và đất sẽ đứng lên chống lại nó.'),
(13355, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 20, 28, 'OT', 'Của cải trong nhà nó sẽ bị đem đi, của nó sẽ bị cuốn trôi trong ngày cơn thịnh nộ của Ngài.'),
(13356, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 20, 29, 'OT', 'Đó là phần của người đàn ông ác từ Đức Chúa Trời, và là cơ nghiệp mà lời Ngài phán định cho nó.'),
(13357, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 1, 'OT', 'Gióp đáp và nói:'),
(13358, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 2, 'OT', 'Hãy nghe, thật chăm chú nghe lời tôi; và điều đó sẽ là sự an ủi cho các bạn.'),
(13359, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 3, 'OT', 'Hãy chịu đựng tôi, để tôi nói; sau khi tôi nói, các ngươi có thể nhạo báng.'),
(13360, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 4, 'OT', 'Than van tôi há phải hướng về loài người sao? Vậy thì nhân sao lòng tôi không chịu nóng giận?'),
(13361, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 5, 'OT', 'Hãy nhìn tôi và lấy làm kinh ngạc; khá đặt tay lên miệng.'),
(13362, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 6, 'OT', 'Khi tôi nhớ lại thì kinh hãi, và sự kinh hãi khiến thịt tôi run rẩy.'),
(13363, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 7, 'OT', 'Tại sao kẻ ác lại sống, thêm tuổi tác, lại càng quyền thế?'),
(13364, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 8, 'OT', 'Dòng dõi chúng nó được vững lập trước mặt chúng nó, và con cháu chúng nó được thấy trước mắt chúng nó.'),
(13365, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 9, 'OT', 'Nhà chúng nó được bình yên, không sợ hãi, roi của Đức Chúa Trời chẳng giáng trên chúng nó.'),
(13366, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 10, 'OT', 'Bò đực của chúng nó sinh sản mà không thất bại, bò cái của chúng nó sinh đẻ mà không sảy thai.'),
(13367, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 11, 'OT', 'Chúng nó cho kẻ ác của mình ra như bầy chiên, và con cái chúng nó nhảy múa.'),
(13368, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 12, 'OT', 'Họ nâng cây đờn cầm và cây đờn lia, rồi vui mừng theo tiếng trổi nhạc cụ dây.'),
(13369, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 13, 'OT', 'Chúng sống trọn các ngày đời mình trong phước lành, rồi bỗng chốc xuống âm phủ.'),
(13370, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 14, 'OT', 'Chúng nói cùng Đức Chúa Trời: "Hãy lui ra khỏi chúng tôi, vì chúng tôi không muốn biết điều Ngài dạy."'),
(13371, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 15, 'OT', 'Đức Chúa Trời Toàn Năng là chi mà chúng ta phải phục sự Ngài? Và chúng ta được ích gì nếu cầu khẩn Ngài?'),
(13372, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 16, 'OT', 'Kìa, sự thịnh vượng của chúng chẳng phải ở trong tay chúng; mưu kế của kẻ ác xa tôi.'),
(13373, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 17, 'OT', 'Bao nhiêu lần cái đèn của kẻ ác tắt đi, tai họa giáng trên chúng nó, và trong cơn thạnh nộ, Đức Chúa Trời phân phát những cơn đau cho chúng nó?'),
(13374, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 18, 'OT', 'Chúng nó sẽ như rơm trước gió, như trấu mà cơn lốc cuốn đi.'),
(13375, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 19, 'OT', 'Đức Chúa Trời để dành cho con cái nó sự gian ác của nó; chính nó sẽ trả, để nó biết.'),
(13376, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 20, 'OT', 'Mắt hắn sẽ thấy tai họa mình, và hắn sẽ uống sự thạnh nộ của Đấng Toàn Năng.'),
(13377, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 21, 'OT', 'Vì sao nó quan tâm đến gia đình mình sau khi chết, khi số tháng của nó đã bị cắt đứt?'),
(13378, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 22, 'OT', 'Người ta há sẽ dạy tri thức cho Đức Chúa Trời sao, bởi Ngài là Đấng xét đoán những kẻ ở trên cao?'),
(13379, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 23, 'OT', 'Người này chết trong khi còn mạnh mẽ, toàn thể được yên ổn và thanh nhàn.'),
(13380, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 24, 'OT', 'Hai vú người đầy sữa, và tủy xương người được nuôi dưỡng.'),
(13381, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 25, 'OT', 'Kẻ ấy chết trong cay đắng linh hồn, chẳng hề nếm điều tốt lành nào.'),
(13382, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 26, 'OT', 'Cùng nằm trên bụi đất, và giòi sâu phủ trên họ.'),
(13383, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 27, 'OT', 'Nầy, tôi biết những ý tưởng của các bạn, và những mưu kế các bạn toan tính để chống lại tôi.'),
(13384, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 28, 'OT', 'Vì các ngươi nói: "Nhà người hào phóng ở đâu? Trại những nơi ở của kẻ ác ở đâu?"'),
(13385, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 29, 'OT', 'Há các ngươi không hỏi những người qua đường sao? Còn dấu tích của họ, các ngươi há chẳng nhận biết?'),
(13386, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 30, 'OT', 'Vì cơn dữ được cất khỏi ngày tai họa, và trong ngày thịnh nộ, kẻ ác được giải cứu.'),
(13387, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 31, 'OT', 'Ai dám trách hắn về con đường hắn đã đi? Ai sẽ báo ứng cho hắn về điều hắn đã làm?'),
(13388, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 32, 'OT', 'Và người ấy sẽ được đưa đến mồ mả, và canh giữ phần mộ người ấy.'),
(13389, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 33, 'OT', 'Các bờ khe lấy làm êm dịu cho nó, và sau nó mọi người đều theo đuổi; còn trước mặt nó thì vô số kẻ đi trước.'),
(13390, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 21, 34, 'OT', 'Làm sao những lời an ủi vô ích của các ngươi có thể an ủi tôi được? Và những câu trả lời của các ngươi chỉ còn lại sự phản bội mà thôi.'),
(13391, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 22, 1, 'OT', 'Ê-li-pha, người Thê-man, bèn đáp rằng:'),
(13392, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 22, 2, 'OT', 'Người ta có thể làm cho Đức Chúa Trời được lợi ích gì chăng? Người ta khôn ngoan, chỉ có ích cho chính mình mà thôi.'),
(13393, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 22, 3, 'OT', 'Đức Chúa Trời há thích điều công bình khi ông làm điều công bình sao? Hay vì ông hoàn toàn giữ trọn đường lối mình, nên Ngài được lợi ích gì chăng?'),
(13394, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 22, 4, 'OT', 'Đức Chúa Trời há vì sự kính sợ của ngươi mà trách ngươi sao? Há phải vì điều đó mà Ngài vào cùng ngươi trong sự xét đoán?'),
(13395, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 22, 5, 'OT', 'Sự ác của ngươi há chẳng nhiều sao, và tội lỗi ngươi há chẳng vô cùng sao?'),
(13396, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 22, 6, 'OT', 'Vì ngươi đã lấy của cải người anh em mình vô cớ, và lột áo quần của những kẻ trần truồng.'),
(13397, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 22, 7, 'OT', 'Ông không cho nước uống kẻ mệt lả, và từ chối bánh cho người đói.'),
(13398, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 22, 8, 'OT', 'Người có cánh tay hùng mạnh thì đất thuộc về người, và kẻ mặt mày kiêu ngạo sẽ ngự trên đất ấy.'),
(13399, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 22, 9, 'OT', 'Ngươi đã để cho những người góa bụa ra đi tay không, và làm yếu sức những cánh tay của kẻ mồ côi.'),
(13400, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 22, 10, 'OT', 'Vì vậy, những cái bẫy vây quanh ông, và sự kinh hoàng thình lình khiến ông hoảng sợ;'),
(13401, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 22, 11, 'OT', 'Hoặc tối tăm ngươi không thấy được, và dòng nước tràn ngập che khuất ngươi.'),
(13402, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 22, 12, 'OT', 'Đức Chúa Trời há chẳng phải ở trên các từng trời cao sao? Hãy xem đỉnh các ngôi sao: cao biết bao!'),
(13403, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 22, 13, 'OT', 'Còn ông nói: Đức Chúa Trời biết điều gì? Ngài có thể xét đoán xuyên qua bóng tối sao?'),
(13404, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 22, 14, 'OT', 'Đám mây tối tăm che khuất Ngài, khiến Ngài không thấy; Ngài bước đi trên vòng tròn các tầng trời.'),
(13405, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 22, 15, 'OT', 'Ngươi sẽ giữ con đường đời xưa, mà những kẻ ác đã đi?'),
(13406, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 22, 16, 'OT', 'Bị quét đi mà không phải đến kỳ hạn; dòng nước lũ cuốn trôi nền tảng của chúng.'),
(13407, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 22, 17, 'OT', 'Chúng nói cùng Đức Chúa Trời rằng: Hãy lìa khỏi chúng tôi; và bảo Đấng Toàn Năng: Người sẽ làm gì được cho chúng ta?'),
(13408, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 22, 18, 'OT', 'Nhưng Ngài làm đầy nhà chúng nó bằng điều lành; còn mưu kế kẻ ác thì cách xa tôi.'),
(13409, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 22, 19, 'OT', 'Người công bình thấy thì mừng rỡ, và kẻ vô tội nhạo báng chúng nó.'),
(13410, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 22, 20, 'OT', 'Chúng ta đã không bị tiêu diệt sao? Còn phần còn lại của chúng thì lửa đã nuốt.'),
(13411, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 22, 21, 'OT', 'Hãy làm cho yên hòa với Ngài, thì sự thịnh vượng tốt lành sẽ đến cùng ông.'),
(13412, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 22, 22, 'OT', 'Hãy nhận lấy lời dạy dỗ từ miệng Ngài, và đặt các lời Ngài vào lòng ngươi.'),
(13413, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 22, 23, 'OT', 'Nếu ngươi trở lại cùng Đấng Toàn Năng, ngươi sẽ được xây dựng lại; ngươi sẽ dời xa sự gian ác khỏi trại ngươi.'),
(13414, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 22, 24, 'OT', 'Hãy quăng vàng mình vào bụi đất, và vàng Ô-phia vào đá giữa các khe nước.'),
(13415, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 22, 25, 'OT', 'Đức Chí Cao sẽ là bửu vật của ngươi, và bạc quí giá sẽ thuộc về ngươi.'),
(13416, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 22, 26, 'OT', 'Vì bấy giờ, ngươi sẽ lấy làm vui nơi Đức Chúa Trời, và sẽ ngước mặt lên cùng Đức Chúa Trời.'),
(13417, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 22, 27, 'OT', 'Ông sẽ cầu nguyện cùng Đức Chúa Trời, thì Ngài sẽ nghe ông; và những lời hứa nguyện của ông, ông sẽ trả trọn.'),
(13418, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 22, 28, 'OT', 'Nếu ông quyết định một điều gì, điều ấy sẽ lập tức được thực hiện cho ông; ánh sáng sẽ chiếu trên các nẻo đường của ông.'),
(13419, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 22, 29, 'OT', 'Khi người ta bị hạ xuống, thì ngươi sẽ nói: Hãy chỗi dậy! Còn kẻ nào cúi mắt, Đức Chúa Trời sẽ cứu.'),
(13420, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 22, 30, 'OT', 'Người công bình sẽ được giải cứu, và chính nhờ sự trong sạch nơi tay ngươi mà người ấy được cứu thoát.'),
(13421, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 23, 1, 'OT', 'Gióp đáp và nói rằng:'),
(13422, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 23, 2, 'OT', 'Ngay cả hôm nay, lời than vãn tôi vẫn cay đắng; tay tôi nặng hơn tiếng rên rỉ tôi.'),
(13423, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 23, 3, 'OT', 'Than ôi! Phải chi tôi biết nơi nào tìm được Ngài, đặng đến nơi chỗ Ngài ngự!'),
(13424, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 23, 4, 'OT', 'Tôi sẽ trình bày vụ kiện tôi trước mặt Ngài, và làm đầy miệng tôi những lý luận.'),
(13425, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 23, 5, 'OT', 'Tôi sẽ biết những lời Ngài đáp lại tôi, và hiểu điều Ngài sẽ nói cùng tôi.'),
(13426, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 23, 6, 'OT', 'Đức Giê-hô-va dùng quyền năng lớn lao tranh luận với tôi sao? Không, chính Ngài sẽ để ý đến tôi.'),
(13427, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 23, 7, 'OT', 'Nơi đó người ngay thẳng sẽ tranh luận cùng Ngài, và tôi được giải thoát đời đời khỏi quan xét xử tôi.'),
(13428, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 23, 8, 'OT', 'Nầy, tôi đi về phía trước thì Ngài không ở đó; tôi đi về phía sau mà cũng không thể thấy Ngài;'),
(13429, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 23, 9, 'OT', 'Ngài làm việc bên trái, nhưng tôi không nắm được; Ngài quay về bên phải, và tôi không thấy Ngài.'),
(13430, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 23, 10, 'OT', 'Nhưng Ngài biết con đường tôi đi; khi Ngài thử tôi, tôi sẽ ra như vàng.'),
(13431, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 23, 11, 'OT', 'Tôi đã bám sát các bước Ngài; tôi giữ đường lối Ngài và không hề chệch khỏi.'),
(13432, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 23, 12, 'OT', 'Tôi không hề từ bỏ các mệnh lệnh từ môi Ngài; tôi giữ kỹ các lời từ miệng Ngài hơn cả lương thực nuôi sống linh hồn tôi.'),
(13433, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 23, 13, 'OT', 'Nhưng Ngài là một, ai có thể khiến Ngài đổi ý? Ý Ngài muốn điều gì, thì Ngài làm điều ấy.'),
(13434, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 23, 14, 'OT', 'Vì Ngài đã hoàn tất điều đã định cho tôi, và trong lòng Ngài còn rất nhiều điều như vậy.'),
(13435, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 23, 15, 'OT', 'Vì cớ đó, tôi sợ hãi trước mặt Ngài; khi suy gẫm điều ấy, tôi run sợ Ngài.'),
(13436, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 23, 16, 'OT', 'Và Đức Chúa Trời khiến lòng tôi yếu đuối, Đấng Toàn Năng làm tôi khiếp sợ;'),
(13437, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 23, 17, 'OT', 'Nhưng ta không bị khuất phục vì sự tối tăm, và bóng tối che khuất trước mặt ta.'),
(13438, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 24, 1, 'OT', 'Tại sao những kỳ của Đấng Toàn Năng không được ấn định, và những người biết Ngài lại không thấy các ngày của Ngài?'),
(13439, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 24, 2, 'OT', 'Chúng dời mốc giới, cướp bầy chiên và dẫn đi chăn.'),
(13440, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 24, 3, 'OT', 'Chúng bắt lừa của kẻ mồ côi đi làm việc, lấy bò của người góa bụa làm vật thế chấp.'),
(13441, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 24, 4, 'OT', 'Chúng làm cho kẻ nghèo phải rời bỏ đường lối, khiến những người khốn cùng trong đất cùng nhau ẩn khuất.'),
(13442, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 24, 5, 'OT', 'Kìa, những kẻ như lừa rừng nơi đồng vắng, ra đi từ sáng sớm để tìm kiếm miếng ăn; đồng vắng là lương thực cho các trẻ nhỏ của chúng.'),
(13443, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 24, 6, 'OT', 'Chúng gặt ngũ cốc tại đồng ruộng trong đêm tối, và hái nho trong vườn nho của kẻ ác.'),
(13444, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 24, 7, 'OT', 'Chúng phải ngủ trần truồng, không có quần áo, và không có chăn đắp giữa trời lạnh.'),
(13445, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 24, 8, 'OT', 'Chúng bị ướt đẫm vì mưa từ các ngọn núi, không có nơi ná ẩn, phải ôm lấy vách đá.'),
(13446, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 24, 9, 'OT', 'Có kẻ cướp đứa trẻ mồ côi đang bú, và bắt kẻ nghèo phải thế chấp áo mình.'),
(13447, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 24, 10, 'OT', 'Người ta đi trần truồng, không có áo mặc; kẻ đói lấy lúa gánh mà vẫn phải mang.'),
(13448, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 24, 11, 'OT', 'Giữa các hàng rào, chúng vắt dầu; chúng đạp nho vào bồn ép rượu, mà vẫn khát.'),
(13449, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 24, 12, 'OT', 'Từ trong thành, người chết rên siết; linh hồn những kẻ bị giết kêu cứu; nhưng Đức Chúa Trời không để ý đến điều bất công.'),
(13450, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 24, 13, 'OT', 'Chúng chống nghịch lại ánh sáng, không nhận biết con đường của ánh sáng, và không ở trong các lối đi của nó.'),
(13451, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 24, 14, 'OT', 'Người giết người chổi dậy vì ánh sáng, giết kẻ nghèo và kẻ khốn cùng; còn ban đêm nó lại như kẻ trộm.'),
(13452, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 24, 15, 'OT', 'Mắt người phạm tội ngoại tình cũng rình mò lúc hoàng hôn, mà nói rằng: "Chẳng có mắt nào thấy được tôi"; và nó che khuất mặt mình.'),
(13453, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 24, 16, 'OT', 'Ban đêm chúng khoét nhà; ban ngày thì dấu mình, không biết đến ánh sáng.'),
(13454, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 24, 17, 'OT', 'Bởi ban mai đều là bóng tối chết cho chúng nó, vì chúng nó biết sự kinh hãi của bóng tối chết.'),
(13455, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 24, 18, 'OT', 'Chúng nó nhẹ trôi như trên mặt nước; phần đất của chúng bị rủa sả trên đất; chúng không quay lại con đường dẫn đến vườn nho.'),
(13456, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 24, 19, 'OT', 'Sự khô hạn và nắng làm tiêu tan nước tuyết; âm phủ cũng thể ấy cho kẻ có tội.'),
(13457, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 24, 20, 'OT', 'Lòng mẹ sẽ quên nó; sâu bọ ăn nó như món ngon; nó sẽ không còn được nhớ đến nữa; và điều ác sẽ bị bẻ gãy như cây cối.'),
(13458, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 24, 21, 'OT', 'Cướp người đàn bà son sẻ không sinh con, chẳng làm điều lành cho người góa bụa.'),
(13459, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 24, 22, 'OT', 'Nhưng Đức Chúa Trời dùng quyền năng mình kéo những kẻ mạnh ra khỏi chỗ an toàn; Ngài đứng lên, và chẳng ai tin được sự sống mình.'),
(13460, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 24, 23, 'OT', 'Người ban cho chúng sự an toàn và chúng được nương cậy; nhưng mắt Người chăm xem xét các lối đi của chúng.'),
(13461, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 24, 24, 'OT', 'Chúng được nâng cao lên một chút rồi chẳng còn nữa; chúng bị hạ xuống, bị cuốn đi như mọi người, và như ngọn lúa bị cắt.'),
(13462, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 24, 25, 'OT', 'Nếu không phải như vậy, thì ai sẽ chứng minh tôi nói dối, và làm cho lời nói của tôi trở nên vô nghĩa?'),
(13463, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 25, 1, 'OT', 'Binh-đát, người Su-a, bèn đáp rằng:'),
(13464, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 25, 2, 'OT', 'Quyền năng và sự kinh hãi thuộc về Ngài, Đấng làm cho sự bình an trong các nơi cao của Ngài.'),
(13465, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 25, 3, 'OT', 'Số đạo binh của Ngài ai tính được? Và ánh sáng Ngài ai mà không chỗi dậy?'),
(13466, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 25, 4, 'OT', 'Loài người làm sao được xưng công bình trước mặt Đức Chúa Trời? Kẻ được sinh ra bởi người phụ nữ làm sao được coi là trong sạch?'),
(13467, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 25, 5, 'OT', 'Kìa, mặt trăng cũng không chiếu sáng, các ngôi sao cũng chẳng tinh sạch trước mặt Đức Chúa Trời.'),
(13468, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 25, 6, 'OT', 'Phương chi loài người là giun, và con cái loài người là sâu bọ!'),
(13469, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 26, 1, 'OT', 'Gióp đáp và nói rằng:'),
(13470, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 26, 2, 'OT', 'Ngươi đã giúp đỡ kẻ nào không sức mạnh dường nào! Ngươi đã cứu giúp cánh tay không sức lực,'),
(13471, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 26, 3, 'OT', 'Ngươi đã khuyên bảo kẻ nào không có sự khôn ngoan, và làm cho ai biết sự thông sáng?'),
(13472, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 26, 4, 'OT', 'Ngươi đã giảng dạy cho ai, và linh hồn của ai đã ra khỏi ngươi?'),
(13473, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 26, 5, 'OT', 'Các kẻ chết run rẩy dưới vực nước và những gì ở cùng chúng.'),
(13474, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 26, 6, 'OT', 'Âm phủ trần truồng trước mặt Đức Chúa Trời, và vực thẳm không có màn che.'),
(13475, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 26, 7, 'OT', 'Chúa Trời giương phương Bắc trên khoảng trống vô hình, treo đất trên chỗ không gì cả.'),
(13476, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 26, 8, 'OT', 'Ngài gom nước vào trong các đám mây của Ngài, mà đám mây không vỡ ra dưới nước ấy.'),
(13477, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 26, 9, 'OT', 'Người nắm giữ mặt của ngôi báu, trải mây Ngài trên nó.'),
(13478, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 26, 10, 'OT', 'Người đã định một giới hạn trên mặt nước, cho đến tận cùng nơi ánh sáng giáp với bóng tối.'),
(13479, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 26, 11, 'OT', 'Các trụ của các từng trời rúng động, và kinh hãi trước tiếng quở trách của Đức Chúa Trời.'),
(13480, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 26, 12, 'OT', 'Nhờ quyền năng mình, Ngài khiến biển yên lặng; nhờ sự hiểu biết mình, Ngài đánh bại Ra-háp.'),
(13481, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 26, 13, 'OT', 'Nhờ thần Ngài, các từng trời được điểm trang; tay Ngài đấm lũng con rắn đang chạy trốn.'),
(13482, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 26, 14, 'OT', 'Kìa, những điều nầy chỉ là đầu mút các lối Ngài; còn một hơi thở nhỏ mọn của lời Ngài, chúng ta đã nghe; nhưng ai hiểu được tiếng sấm của quyền năng Ngài?'),
(13483, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 27, 1, 'OT', 'Gióp tiếp tục nói lời lẽ của mình, mà rằng:'),
(13484, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 27, 2, 'OT', 'Nhân đức Chúa Trời hằng sống, Ngài đã đoạt lấy lý lẽ của tôi, và Đấng Toàn Năng khiến linh hồn tôi cay đắng.'),
(13485, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 27, 3, 'OT', 'Hễ hơi thở tôi còn trong mình tôi, và thần của Đức Chúa Trời còn trong lỗ mũi tôi,'),
(13486, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 27, 4, 'OT', 'Môi tôi sẽ không nói điều gian ác, và lưỡi tôi sẽ không thốt ra điều gian trá.'),
(13487, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 27, 5, 'OT', 'Nguyện xin điều đó đừng xảy đến cho tôi, nếu tôi cho các ông là phải! Trọn đời tôi, tôi sẽ không bỏ sự ngay thẳng của tôi.'),
(13488, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 27, 6, 'OT', 'Tôi nắm giữ sự công chính của tôi và sẽ không buông ra; trọn đời tôi, lòng tôi sẽ không khiển trách tôi.'),
(13489, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 27, 7, 'OT', 'Nguyện kẻ thù tôi bị xử như kẻ ác, và kẻ dấy lên nghịch cùng tôi bị xử như kẻ gian ác.'),
(13490, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 27, 8, 'OT', 'Vì sự trông cậy của kẻ ác là gì khi nó được chia phần, khi Đức Chúa Trời lấy đi linh hồn nó?'),
(13491, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 27, 9, 'OT', 'Khi hoạn nạn xảy đến cho người ấy, Đức Chúa Trời há sẽ nghe tiếng kêu của người ấy sao?'),
(13492, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 27, 10, 'OT', 'Hắn có được vui thỏa trong Đấng Toàn Năng, có kêu cầu Đức Chúa Trời trong mọi lúc không?'),
(13493, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 27, 11, 'OT', 'Ta sẽ dạy các ngươi những điều thuộc về tay Đức Chúa Trời, không giấu các ngươi điều gì về ý định của Đấng Toàn Năng.'),
(13494, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 27, 12, 'OT', 'Nầy, chính các ngươi đã thấy điều đó; vậy thì tại sao các ngươi còn níu giữ những điều hư không vô ích?'),
(13495, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 27, 13, 'OT', 'Này là phần của người ác nơi Đức Chúa Trời, và cơ nghiệp của những kẻ bạo ngược sẽ nhận lãnh từ Đức Chúa Trời:'),
(13496, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 27, 14, 'OT', 'Nếu con cái người ấy đông đến nỗi bị gươm giết hại, và dòng dõi người ấy sẽ không được no nê bánh.'),
(13497, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 27, 15, 'OT', 'Những kẻ còn sót lại của nó sẽ bị chôn vùi trong cõi chết, và các góa phụ của nó sẽ không khóc than.'),
(13498, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 27, 16, 'OT', 'Nếu hắn chất bạc như bụi đất, và sắm quần áo như bùn.'),
(13499, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 27, 17, 'OT', 'Người ngay thẳng sẽ mặc lấy của cải, và bạc tinh sạch sẽ được chia cho người vô tội.'),
(13500, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 27, 18, 'OT', 'Người xây nhà mình như tổ bọ, và làm nơi ở như cái chòi của người giữ vườn nho.'),
(13501, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 27, 19, 'OT', 'Người giàu có nằm xuống nhưng không được chôn, mở mắt ra thì đã không còn nữa.'),
(13502, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 27, 20, 'OT', 'Khốn khổ ập đến cho nó như nước lũ cuốn trôi; trong đêm tối, cơn bão táp thình lình cuốn nó đi.'),
(13503, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 27, 21, 'OT', 'Gió đông nâng nó lên và cuốn đi; một cơn bão lớn hất nó khỏi nơi nó đứng.'),
(13504, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 27, 22, 'OT', 'Đức Chúa Trời sẽ giáng họa xuống trên hắn, chẳng thương xót; hắn sẽ chạy trốn khỏi tay Ngài trong cơn gió.'),
(13505, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 27, 23, 'OT', 'Người ta sẽ vỗ tay về nó, và huýt sáo đuổi nó khỏi nơi ở của nó.'),
(13506, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 28, 1, 'OT', 'Vì bạc có nơi tìm được, và vàng có chỗ người ta luyện nó.'),
(13507, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 28, 2, 'OT', 'Sắt được lấy từ bụi đất, và đá được nấu chảy ra để lấy đồng.'),
(13508, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 28, 3, 'OT', 'Người ta đặt ranh giới cho bóng tối, và dò tìm mọi cực điểm; đá nơi u ám và bóng tối sâu thẳm.'),
(13509, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 28, 4, 'OT', 'Kẻ ta đào mỏ xa chỗ người ở, nơi hoang vắng không ai đặt chân tới; chúng bị treo lơ lửng và đung đưa xa cách loài người.'),
(13510, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 28, 5, 'OT', 'Đất sinh ra lương thực, nhưng bên dưới nó bị đảo lộn như bởi lửa.'),
(13511, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 28, 6, 'OT', 'Nơi ấy là chỗ ngọc lam, và bụi vàng là của nó.'),
(13512, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 28, 7, 'OT', 'Đường lối ấy chim ăn mồi không biết, mắt chim ưng cũng chẳng thấy.'),
(13513, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 28, 8, 'OT', 'Chúng không đi qua đó, con cái của đồng cỏ hoang vu; thú dữ chẳng từng bước trên nó.'),
(13514, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 28, 9, 'OT', 'Người tra tay vào đá hoa cương, lật đổ các núi từ nơi gốc rễ nó.'),
(13515, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 28, 10, 'OT', 'Người đục các khe trong vách đá; mắt người thấy mọi vật quý giá.'),
(13516, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 28, 11, 'OT', 'Người ngăn nước các sông không cho tràn ra; và làm lộ ra ánh sáng cho điều gì khuất lấp.'),
(13517, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 28, 12, 'OT', 'Sự khôn ngoan tìm được ở đâu? Và nơi nào có chỗ của sự thông sáng?'),
(13518, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 28, 13, 'OT', 'Người ta không biết giá trị của nó, cũng không tìm được nó tại đất của những kẻ sống.'),
(13519, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 28, 14, 'OT', 'Vực sâu nói: "Nó không ở trong tôi"; biển nói: "Nó không ở cùng ta."'),
(13520, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 28, 15, 'OT', 'Vàng ròng không thể đổi lấy nó, cũng chẳng thể cân bạc để mua giá trị nó.'),
(13521, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 28, 16, 'OT', 'Không thể đánh giá nó bằng vàng Ô-phir, bằng ngọc đỏ quí giá hay bằng ngọc lam.'),
(13522, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 28, 17, 'OT', 'Vàng hay thủy tinh không thể sánh được với nó; vật đổi lấy nó cũng chẳng phải là khí cụ bằng vàng ròng.'),
(13523, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 28, 18, 'OT', 'Ngọc đỏ và ngọc thạch không đáng kể; giá trị của sự khôn ngoan vượt trên các viên ngọc quý.'),
(13524, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 28, 19, 'OT', 'Vàng Ê-thi-ô-bi không thể sánh được với nó; cũng không thể cân bằng bằng vàng ròng.'),
(13525, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 28, 20, 'OT', 'Sự khôn ngoan sẽ từ đâu mà đến? Nơi nào có sự thông sáng?'),
(13526, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 28, 21, 'OT', 'Nó được giấu kín khỏi mọi mắt của kẻ sống, và bị che khuất khỏi các chim trời.'),
(13527, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 28, 22, 'OT', 'Chốn diệt vong và sự chết nói: "Tai chúng tôi đã nghe tiếng đồn về nó."'),
(13528, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 28, 23, 'OT', 'Đức Chúa Trời hiểu biết con đường của nó, và Ngài biết rõ nơi ở của nó.'),
(13529, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 28, 24, 'OT', 'Vì chính Ngài nhìn thấu tận cùng đất, và quan sát dưới khắp các từng trời.'),
(13530, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 28, 25, 'OT', 'Ngài định sức nặng cho gió, và đo lường các dòng nước.'),
(13531, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 28, 26, 'OT', 'Khi Ngài lập luật lệ cho mưa, và vạch đường đi cho tiếng sấm.'),
(13532, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 28, 27, 'OT', 'Bấy giờ Ngài thấy nó, và thuật lại; Ngài lập nên nó, và cũng dò xét nó nữa;'),
(13533, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 28, 28, 'OT', 'Đức Giê-hô-va phán với loài người rằng: Nầy, sự kính sợ Đức Giê-hô-va ấy là sự khôn ngoan; còn lánh khỏi điều ác, ấy là sự thông sáng.'),
(13534, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 29, 1, 'OT', 'Gióp lại tiếp tục bài ca than van của mình và nói rằng:'),
(13535, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 29, 2, 'OT', 'Ôi! Ước gì tôi được như những tháng ngày xưa, như những ngày Đức Chúa Trời gìn giữ tôi!'),
(13536, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 29, 3, 'OT', 'Khi ngọn đèn Ngài soi trên đầu tôi, nhờ ánh sáng Ngài, tôi đi qua chỗ tối tăm.'),
(13537, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 29, 4, 'OT', 'Như khi tôi còn ở những ngày tráng kiện, khi tình thương của Đức Chúa Trời còn ở trên trại tôi.'),
(13538, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 29, 5, 'OT', 'Khi Ðức Chúa Trời Toàn Năng còn ở cùng tôi, những người trẻ tuổi vây quanh tôi;'),
(13539, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 29, 6, 'OT', 'Khi tôi rửa bước chân mình trong dầu, và hòn đá bên cạnh tôi tuôn ra các dòng dầu.'),
(13540, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 29, 7, 'OT', 'Khi tôi ra khỏi cổng thành, đến nơi phố chợ, người ta sửa ghế tôi ngồi.'),
(13541, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 29, 8, 'OT', 'Các thiếu niên thấy tôi thì núp vào, và những người già cả đều đứng dậy mà đứng;'),
(13542, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 29, 9, 'OT', 'Những người lãnh đạo nín lặng không nói, và lấy tay che miệng;'),
(13543, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 29, 10, 'OT', 'Tiếng của các quan trưởng thì im lặng, và lưỡi chúng dính nơi hàm mồm.'),
(13544, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 29, 11, 'OT', 'Vì tai nghe tôi thì ca ngợi tôi, và mắt thấy tôi thì làm chứng cho tôi.'),
(13545, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 29, 12, 'OT', 'Vì tôi giải cứu kẻ khốn cùng kêu cứu, và kẻ mồ côi không ai giúp đỡ.'),
(13546, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 29, 13, 'OT', 'Phước của kẻ sắp chết đã giáng trên tôi, và lòng người góa bụa reo lên vui sướng.'),
(13547, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 29, 14, 'OT', 'Tôi mặc sự công bình, và nó mặc lấy tôi; sự xét đoán tôi như chiếc áo choàng và mũ triều.'),
(13548, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 29, 15, 'OT', 'Tôi đã là đôi mắt cho kẻ mù và là đôi chân cho kẻ què.'),
(13549, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 29, 16, 'OT', 'Tôi đã làm cha cho kẻ nghèo khó, và vụ án của người không quen biết, tôi đã điều tra kỹ lưỡng.'),
(13550, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 29, 17, 'OT', 'Tôi bẻ gãy nanh kẻ ác và ném thịt nó ra khỏi răng nó.'),
(13551, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 29, 18, 'OT', 'Tôi nói: Tôi sẽ chết trong tổ của tôi, và số ngày tôi sẽ nhiều như cát.'),
(13552, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 29, 19, 'OT', 'Rễ tôi mở ra gần nước, và sương đọng lại trên mùa gặt của tôi.'),
(13553, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 29, 20, 'OT', 'Vinh quang ta mới mẻ ở cùng ta, và cây cung ta được đổi mới trong tay ta.'),
(13554, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 29, 21, 'OT', 'Họ lắng tai nghe tôi và chờ đợi, rồi làm thinh để nghe lời khuyên dạy của tôi.'),
(13555, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 29, 22, 'OT', 'Sau khi tôi nói, họ không phản đối; lời tôi rơi xuống trên họ như sương.'),
(13556, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 29, 23, 'OT', 'Họ trông đợi tôi như trông đợi mưa rào, miệng họ há ra như khao khát mưa xuân.'),
(13557, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 29, 24, 'OT', 'Tôi mỉm cười với họ khi họ không tin; ánh sáng trên khuôn mặt tôi, họ chẳng hề làm tắt đi.'),
(13558, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 29, 25, 'OT', 'Tôi chọn đường lối của họ và ngồi làm đầu; tôi ở như vua giữa đoàn người, như kẻ an ủi những kẻ buồn bã.'),
(13559, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 30, 1, 'OT', 'Bây giờ, những kẻ trẻ tuổi hơn tôi đã nhạo báng tôi, những kẻ mà tôi từng khinh cha họ, không chịu đặt chung với chó bầy chiên tôi.'),
(13560, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 30, 2, 'OT', 'Sức mạnh của tay họ đã tiêu tan rồi; vậy, điều đó có ích gì cho tôi?'),
(13561, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 30, 3, 'OT', 'Bị tiêu hao vì thiếu thốn và đói khát, chúng gặm đất hoang, nơi từ lâu đã hoang vu và đổ nát.'),
(13562, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 30, 4, 'OT', 'Chúng hái rau mặn dưới bụi cây, rễ cây gai làm thức ăn cho chúng.'),
(13563, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 30, 5, 'OT', 'Bị trục xuất khỏi đất liền, họ bị la ó như kẻ trộm.'),
(13564, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 30, 6, 'OT', 'Họ phải cư ngụ trong các thung lũng khô cằn, trong những hang đất và giữa các vách đá.'),
(13565, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 30, 7, 'OT', 'Chúng kêu la giữa các bụi gai, tụ tập dưới các bụi cây có gai.'),
(13566, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 30, 8, 'OT', 'Chúng là con cái kẻ khinh bỉ, cũng là con cái kẻ vô danh, bị khinh dể khỏi đất.'),
(13567, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 30, 9, 'OT', 'Bây giờ, tôi đã trở thành bài ca của chúng, và tôi đã trở thành lời nói chuyện cho chúng.'),
(13568, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 30, 10, 'OT', 'Chúng ghét tôi, xa tránh tôi; trước mặt tôi, chúng chẳng ngập ngừng nhổ xuống.'),
(13569, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 30, 11, 'OT', 'Vì Ngài làm lỏng dây cung ta, và sỉ nhục ta; chúng ném hàm ngựa khỏi trước mặt ta.'),
(13570, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 30, 12, 'OT', 'Những kẻ ở bên phải tôi nổi lên chống tôi; chúng xô chân tôi và dựng sẵn cho tôi những con đường hủy diệt của chúng.'),
(13571, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 30, 13, 'OT', 'Chúng phá đường lối tôi, khiến tôi hư hại; chẳng giúp đỡ cho chúng.'),
(13572, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 30, 14, 'OT', 'Chúng xông vào như nơi khe nứt rộng, ào xuống giữa lúc tai họa hoành hành.'),
(13573, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 30, 15, 'OT', 'Các tai họa bất ngờ đổ xuống trên tôi, đuổi theo sự thịnh vượng tôi như theo gió; và sự cứu rỗi tôi đã qua như mây.'),
(13574, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 30, 16, 'OT', 'Bây giờ, linh hồn tôi đổ ra trong tôi; các ngày khốn khổ đã nắm giữ tôi.'),
(13575, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 30, 17, 'OT', 'Đêm đến, xương cốt tôi bị buốt giá ra khỏi tôi, và các khớp tôi thì không được ngủ nghỉ.'),
(13576, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 30, 18, 'OT', 'Nhờ quyền năng lớn của Đức Chúa Trời, áo ngoài tôi bị hủy nát; chính quyền năng ấy siết chặt tôi lại như cổ áo tôi.'),
(13577, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 30, 19, 'OT', 'Đức Chúa Trời quăng tôi vào bùn, tôi trở nên như bụi đất và tro tàn.'),
(13578, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 30, 20, 'OT', 'Tôi kêu cầu Ngài, nhưng Ngài không đáp lời tôi; tôi đứng dậy, và Ngài nhìn tôi.'),
(13579, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 30, 21, 'OT', 'Người đổi trở nên tàn nhẫn đối với tôi; lấy quyền năng tay Ngài mà tấn công tôi.'),
(13580, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 30, 22, 'OT', 'Ngài nâng tôi lên trên gió, khiến gió đưa tôi đi, và tiêu tan tôi giữa cơn bão.'),
(13581, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 30, 23, 'OT', 'Vì tôi biết rằng cái chết sẽ đưa tôi trở về, là nơi hẹn cho mọi người sống.'),
(13582, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 30, 24, 'OT', 'Nhưng người bị tàn hại há chẳng giơ tay ra sao? Hay khi gặp tai họa, họ há không kêu cứu?'),
(13583, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 30, 25, 'OT', 'Tôi há chẳng khóc cho kẻ gặp ngày hoạn nạn sao? Linh hồn tôi há chẳng đau buồn cho kẻ nghèo khó sao?'),
(13584, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 30, 26, 'OT', 'Tôi mong điều tốt lành, nhưng tai họa đã đến; tôi trông đợi ánh sáng, nhưng bóng tối ập xuống.'),
(13585, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 30, 27, 'OT', 'Lòng tôi sôi sục chẳng yên nghỉ; các ngày khốn khổ xông đến tôi.'),
(13586, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 30, 28, 'OT', 'Tôi đi trong u tối, không phải vì nắng; tôi đứng dậy giữa hội chúng mà kêu cứu.'),
(13587, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 30, 29, 'OT', 'Tôi trở nên anh em với chó rừng, và bạn hữu cùng con đà điểu.'),
(13588, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 30, 30, 'OT', 'Da tôi chuyển sang màu đen và bong ra khỏi tôi, xương tôi nóng rực vì cơn sốt.'),
(13589, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 30, 31, 'OT', 'Đàn cầm tôi trở nên tiếng khóc than, và tiếng sáo tôi chỉ ra tiếng than khóc.'),
(13590, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 1, 'OT', 'Tôi đã lập giao ước với mắt tôi, vậy thì làm sao tôi còn nhìn xem một trinh nữ?'),
(13591, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 2, 'OT', 'Vì phần của Đức Chúa Trời từ trên cao, và cơ nghiệp của Đấng Toàn Năng từ nơi cực cao, là gì?'),
(13592, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 3, 'OT', 'Nào chẳng phải tai họa cho kẻ ác, và sự sụp đổ cho những kẻ làm điều gian ác?'),
(13593, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 4, 'OT', 'Chẳng phải Đức Chúa Trời thấy các nẻo đường tôi sao? Và đếm tất cả các bước tôi sao?'),
(13594, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 5, 'OT', 'Nếu tôi đã đi với kẻ gian dối, và bàn chân tôi vội vã theo điều gian trá,'),
(13595, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 6, 'OT', 'Nguyện Đức Chúa Trời cân tôi bằng cân công bình, thì Ngài sẽ biết sự trọn vẹn của tôi.'),
(13596, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 7, 'OT', 'Nếu bàn chân tôi lệch khỏi con đường ngay thẳng, và lòng tôi theo sau ánh mắt mình; nếu điều gì ô uế dính nơi tay tôi,'),
(13597, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 8, 'OT', 'Nguyện tôi gieo, mà kẻ khác ăn; nguyện con cháu tôi bị nhổ rễ!'),
(13598, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 9, 'OT', 'Nếu lòng tôi bị quyến dụ về người phụ nữ, và nếu tôi rình rập tại cửa nhà người lân cận mình,'),
(13599, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 10, 'OT', 'Nguyện vợ tôi làm tôi cho người khác, và có những người khác nằm trên nàng.'),
(13600, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 11, 'OT', 'Vì đó là gian ác, và là tội đáng bị xét xử.'),
(13601, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 12, 'OT', 'Vì ấy là lửa sẽ thiêu đến âm phủ, và sẽ tiêu hủy toàn bộ mùa màng tôi.'),
(13602, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 13, 'OT', 'Nếu tôi khước từ xét xử tôi tớ trai hay gái tôi, khi chúng tranh cãi với tôi,'),
(13603, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 14, 'OT', 'Thì tôi sẽ làm gì khi Đức Chúa Trời chỗi dậy? Và khi Ngài kiểm tra, tôi sẽ trả lời sao?'),
(13604, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 15, 'OT', 'Đấng đã tạo nên tôi trong bụng mẹ, há chẳng phải cũng dựng nên người đó sao? Và trong lòng mẹ, một Đức Chúa Trời đã tạo nên chúng ta.'),
(13605, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 16, 'OT', 'Nếu tôi từ chối không cho kẻ nghèo điều họ mong ước, hoặc làm cho mắt người góa bụa phải mỏi mòn,'),
(13606, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 17, 'OT', 'Nếu tôi có ăn miếng bánh của tôi một mình, và kẻ mồ côi không được ăn từ đó;'),
(13607, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 18, 'OT', 'Vì từ khi tôi còn thơ ấu, Người đã nuôi nấng tôi như cha; và từ khi tôi lọt lòng mẹ tôi, Người đã dẫn dắt tôi.'),
(13608, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 19, 'OT', 'Nếu tôi thấy ai chết vì không có áo, hay kẻ nghèo thiếu không có chăn;'),
(13609, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 20, 'OT', 'Nếu lòng người không chúc phước cho tôi, và người không nhờ lông chiên tôi mà được ấm áp;'),
(13610, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 21, 'OT', 'Nếu tôi đã giơ tay chống lại kẻ mồ côi, vì thấy nơi cửa có sự giúp đỡ tôi;'),
(13611, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 22, 'OT', 'Nguyện cho vai tôi rời khỏi bả vai, và cẳng tay tôi gãy rời khỏi ống tay!'),
(13612, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 23, 'OT', 'Vì tôi sợ tai họa từ Đức Chúa Trời giáng xuống, và trước sự oai nghiêm của Ngài, tôi không thể chịu nổi.'),
(13613, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 24, 'OT', 'Nếu tôi đặt vàng làm chỗ nương nhờ tôi, và nói với vàng ròng rằng: Ngươi là sự trông cậy tôi;'),
(13614, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 25, 'OT', 'Nếu tôi vui mừng vì tài sản tôi rất nhiều, và vì tay tôi đã kiếm được lớn.'),
(13615, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 26, 'OT', 'Nếu tôi thấy ánh sáng khi nó chiếu ra, và trăng non khi nó di chuyển rạng rỡ,'),
(13616, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 27, 'OT', 'Nếu lòng tôi thầm tưởng điều sai trái, và tay tôi đưa lên môi mà hôn;'),
(13617, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 28, 'OT', 'Cũng là một tội đáng bị trừng phạt, vì tôi đã chối bỏ Đức Chúa Trời ở trên cao.'),
(13618, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 29, 'OT', 'Nếu tôi vui mừng khi kẻ ghét tôi bị tai họa, và hớn hở khi người ấy gặp điều bất hạnh;'),
(13619, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 30, 'OT', 'Tôi không để cho miệng tôi phạm tội, bằng cách cầu nguyện cho linh hồn nó bị rủa sả.'),
(13620, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 31, 'OT', 'Nếu những người trong lều tôi không nói: "Ai sẽ cho kẻ nào chưa được no nê thịt của nó?"'),
(13621, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 32, 'OT', 'Khách lạ không phải ngủ đêm ngoài đường; tôi mở cửa cho kẻ qua đường.'),
(13622, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 33, 'OT', 'Nếu tôi che giấu tội mình như A-đam, giấu sự gian ác mình trong lòng,'),
(13623, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 34, 'OT', 'Vì tôi sợ dân chúng đông đảo, và sự khinh bỉ của các gia tộc làm tôi khiếp sợ, nên tôi làm thinh, không dám ra khỏi cửa.'),
(13624, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 35, 'OT', 'Ôi! Chớ chi có người nghe tôi! Nầy là dấu chỉ tôi ký; nguyện Đấng Toàn Năng đáp lời tôi; nguyện kẻ kiện tôi viết một bản cáo trạng!'),
(13625, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 36, 'OT', 'Tôi hẳn sẽ mang nó trên vai mình, buộc nó làm mão đội đầu tôi.'),
(13626, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 37, 'OT', 'Tôi sẽ trình bày số bước tôi cho Ngài biết, như một lãnh tụ, tôi sẽ đến gần Ngài.'),
(13627, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 38, 'OT', 'Nếu đất của tôi kêu cáo tôi, và các luống cày nó đồng than khóc?'),
(13628, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 39, 'OT', 'Nếu tôi ăn sản vật của nó mà không trả bạc, hay khiến cho linh hồn chủ nó phải hao mòn;'),
(13629, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 31, 40, 'OT', 'Thay vì lúa mì, hãy để mọc lên cây gai góc; và thay vì lúa mạch, hãy để mọc lên cây cỏ dại! Những lời của ông Gióp đều đã chấm dứt.'),
(13630, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 32, 1, 'OT', 'Bấy giờ, ba người ấy ngừng đáp lời với ông Gióp, vì người cho mình là công bình trong mắt mình.'),
(13631, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 32, 2, 'OT', 'Ê-li-hu, con trai của Ba-ra-kê-ên, người Bu-xi, về dòng dõi Ram, nổi giận cùng Gióp; cơn giận của người nổi lên vì người cho rằng mình công bình hơn Đức Chúa Trời.'),
(13632, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 32, 3, 'OT', 'Ê-li-hu nổi giận ba người bạn của ông ấy, vì họ không tìm được lời đáp, mà lại lên án ông ấy.'),
(13633, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 32, 4, 'OT', 'Ê-li-hu đợi Gióp nói xong, vì hai người đó già hơn ông về tuổi.'),
(13634, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 32, 5, 'OT', 'Ê-li-hu thấy không còn câu trả lời nào nơi miệng ba người đó, thì cơn thịnh nộ của người nổi lên.'),
(13635, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 32, 6, 'OT', 'Ê-li-hu, con trai Ba-ra-kê-ên người Bu-xi, bèn đáp và nói: Tôi trẻ tuổi, còn các ông thì già cả; vì cớ đó, tôi e sợ, không dám bày tỏ sự hiểu biết của mình cho các ông.'),
(13636, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 32, 7, 'OT', 'Tôi nói rằng: Những người sống lâu năm sẽ nói, và tuổi đời cao sẽ dạy sự khôn ngoan.'),
(13637, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 32, 8, 'OT', 'Nhưng thực vậy, thần khí ở trong loài người, và hơi thở của Đức Chúa Trời khiến họ thông sáng.'),
(13638, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 32, 9, 'OT', 'Người có tuổi không hẳn là người khôn ngoan, và các bậc lão thành không hẳn hiểu biết luật lệ.'),
(13639, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 32, 10, 'OT', 'Vì vậy tôi nói: Hãy nghe tôi; tôi cũng sẽ bày tỏ điều tôi biết.'),
(13640, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 32, 11, 'OT', 'Nầy, tôi đã đợi các lời các anh, lắng tai nghe sự thông sáng của các anh, cho đến khi các anh tra xét các lời nói.'),
(13641, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 32, 12, 'OT', 'Tôi chăm chỉ nhìn xem các anh, và này, chẳng có ai trong các anh có thể bác bỏ Gióp, chẳng có ai trong các anh đáp lại các lời nói của người.'),
(13642, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 32, 13, 'OT', 'Đừng nói: Chúng ta đã tìm được sự khôn ngoan; Đức Chúa Trời sẽ bác bỏ nó, chứ không phải người.'),
(13643, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 32, 14, 'OT', 'Họ không tranh luận với tôi, nên tôi cũng không dùng lời các anh mà phản bác người.'),
(13644, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 32, 15, 'OT', 'Họ sững sờ, không trả lời thêm nữa; lời nói của họ đã dứt rồi.'),
(13645, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 32, 16, 'OT', 'Tôi đã chờ đợi vì họ không nói gì nữa, đã đứng im, không còn đáp lại điều gì.'),
(13646, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 32, 17, 'OT', 'Tôi cũng sẽ nói lên phần lý lẽ của tôi, tôi cũng sẽ bày tỏ hiểu biết của mình.'),
(13647, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 32, 18, 'OT', 'Vì tôi đã đầy dẫy lời nói, thần trong lòng tôi ép chặt tôi.'),
(13648, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 32, 19, 'OT', 'Nầy, bụng ta như rượu chẳng khui nút, như bầu da đựng rượu mới gần nứt ra.'),
(13649, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 32, 20, 'OT', 'Tôi sẽ nói để được thoải mái; tôi sẽ mở môi và đáp lại.'),
(13650, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 32, 21, 'OT', 'Xin đừng nhìn xem mặt người nào, cũng đừng tâng bốc bất cứ ai.'),
(13651, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 32, 22, 'OT', 'Vì tôi không biết tâng bốc; nếu tôi tâng bốc, Đấng Tạo Hóa tôi hẳn sẽ mau chóng đem tôi đi.'),
(13652, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 1, 'OT', 'Nhưng vậy, hỡi Ái-ốp, hãy nghe lời ta; khá lắng tai nghe các lời nói ta.'),
(13653, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 2, 'OT', 'Này, ta đã mở miệng, lưỡi ta nói trong họng ta.'),
(13654, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 3, 'OT', 'Lời tôi nói ra theo sự ngay thẳng của lòng tôi; tri thức nơi môi miệng tôi nói ra cách minh bạch.'),
(13655, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 4, 'OT', 'Thần của Đức Chúa Trời đã tạo nên tôi, và hơi thở của Đấng Toàn Năng khiến tôi được sống.'),
(13656, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 5, 'OT', 'Nếu ngươi có thể, hãy đáp lại ta; hãy đứng trước mặt ta mà biện luận!'),
(13657, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 6, 'OT', 'Nầy, ta cũng như ngươi trước mặt Đức Chúa Trời; ta cũng bởi bụi đất mà ra.'),
(13658, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 7, 'OT', 'Nầy, oai nghi ta sẽ không làm ngươi kinh khiếp, và quyền năng ta sẽ không đè nặng trên ngươi.'),
(13659, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 8, 'OT', 'Nhưng ông đã nói vào tai tôi, và tôi nghe được tiếng những lời của ông.'),
(13660, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 9, 'OT', 'Tôi trong sạch, không phạm tội; tôi thanh sạch, và tôi chẳng có điều ác nào.'),
(13661, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 10, 'OT', 'Nhưng Ngài tìm dịp chống lại tôi, coi tôi như kẻ thù nghịch Ngài.'),
(13662, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 11, 'OT', 'Ngài đặt xiềng vào chân tôi, canh giữ mọi nẻo đường tôi.'),
(13663, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 12, 'OT', 'Nầy, điều nầy không phải là công bình; ta sẽ đáp cho ông, vì Đức Chúa Trời lớn hơn loài người.'),
(13664, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 13, 'OT', 'Tại sao ngươi tranh luận cùng Ngài? Vì về mọi lời của Ngài, Ngài không đáp lại.'),
(13665, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 14, 'OT', 'Vì Đức Chúa Trời phán một lần, hay hai lần, nhưng loài người không chịu để ý.'),
(13666, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 15, 'OT', 'Trong chiêm bao, trong dị tượng ban đêm, khi người ta ngủ mê, nằm ngủ trên giường.'),
(13667, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 16, 'OT', 'Bấy giờ Ngài sẽ mở tai loài người, và ấn định lời dạy bảo của Ngài cho họ,'),
(13668, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 17, 'OT', 'Để ngăn con người khỏi hành động của nó, và che khuất sự kiêu ngạo khỏi người.'),
(13669, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 18, 'OT', 'Giữ cho linh hồn người khỏi bị nuốt bởi huyệt sâu, và sự sống người khỏi qua tay kẻ diệt vong.'),
(13670, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 19, 'OT', 'Người ta bị sửa phạt bởi đau đớn trên giường mình, và các xương người tranh cãi với nhau cách vững bền.'),
(13671, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 20, 'OT', 'Sự sống người ấy trở nên ghét bỏ thức ăn, và linh hồn người ấy từ chối món ăn ưa thích.'),
(13672, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 21, 'OT', 'Thịt người ấy hao mòn đến nỗi không còn thấy được nữa, và xương người ấy, trước kia không nhìn thấy, nay lộ rõ ra.'),
(13673, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 22, 'OT', 'Linh hồn người đến gần huyệt mộ, và sự sống người gần kẻ chết.'),
(13674, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 23, 'OT', 'Nếu người ấy có một thiên sứ làm người truyền đạt, một trong ngàn ngàn, để chỉ cho người biết điều ngay thẳng của người,'),
(13675, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 24, 'OT', 'Đức Chúa Trời làm ơn cho người ấy và phán: "Hãy cứu nó khỏi sa xuống hầm sâu; Ta đã tìm được giá chuộc."'),
(13676, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 25, 'OT', 'Da thịt người sẽ mềm mại hơn thời niên thiếu, người sẽ trở lại những ngày thơ ấu.'),
(13677, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 26, 'OT', 'Người sẽ cầu xin Đức Chúa Trời, và Ngài sẽ đoái nhận người; người sẽ nhìn thấy mặt Ngài với tiếng reo vui, và Ngài sẽ phục hồi cho người sự công bình của người.'),
(13678, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 27, 'OT', 'Người ấy sẽ nói trước mặt loài người: Ta đã phạm tội, làm sai điều ngay thẳng, và điều đó chẳng ích lợi gì cho ta.'),
(13679, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 28, 'OT', 'Đức Chúa Trời đã chuộc linh hồn tôi khỏi bước qua hầm hố, và sự sống tôi sẽ thấy ánh sáng.'),
(13680, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 29, 'OT', 'Nầy, Đức Chúa Trời làm tất cả những điều nầy cho loài người, hai lần, hay là ba lần,'),
(13681, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 30, 'OT', 'để khiến linh hồn người trở lại khỏi hầm sâu, để được chiếu sáng bằng ánh sáng của sự sống.'),
(13682, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 31, 'OT', 'Hỡi Gióp, hãy lắng nghe ta; hãy làm thinh, để ta nói.'),
(13683, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 32, 'OT', 'Nếu ngươi có điều nào muốn nói, hãy đáp lại ta; hãy nói đi, vì ta muốn xưng công bình cho ngươi.'),
(13684, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 33, 33, 'OT', 'Nếu ngươi không nghe ta, hãy làm thinh, để ta dạy ngươi sự khôn ngoan.'),
(13685, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 1, 'OT', 'Ê-li-hu đáp và nói rằng:'),
(13686, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 2, 'OT', 'Hỡi các người khôn ngoan, hãy nghe lời tôi; hỡi những người hiểu biết, hãy lắng tai nghe tôi;'),
(13687, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 3, 'OT', 'Vì tai nghe thử các lời nói, và vòm họng nếm lấy đồ ăn.'),
(13688, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 4, 'OT', 'Chúng ta hãy chọn lấy điều công chính cho mình, cùng nhau nhận biết điều gì là tốt lành.'),
(13689, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 5, 'OT', 'Vì Gióp đã nói: "Tôi thật là công bình, nhưng Đức Chúa Trời đã cất khỏi tôi quyền xét đoán tôi."'),
(13690, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 6, 'OT', 'Dẫu tôi ngay thẳng, người ta bảo tôi nói dối; tôi không phạm tội, nhưng vết thương tôi không được chữa lành.'),
(13691, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 7, 'OT', 'Ai là người như Gióp, uống sự nhạo báng như nước?'),
(13692, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 8, 'OT', 'Và ưa thích kết bạn với những kẻ làm điều ác, và đồng hành với những người gian ác?'),
(13693, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 9, 'OT', 'Vì người đã nói: "Loài người chẳng được ích lợi gì khi tìm được niềm vui của mình nơi Đức Chúa Trời."'),
(13694, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 10, 'OT', 'Vì vậy, hỡi những người có lòng hiểu biết, hãy nghe tôi: Đức Chúa Trời hoàn toàn không thể làm điều ác, Đấng Toàn năng cũng chẳng bao giờ làm điều gian ác.'),
(13695, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 11, 'OT', 'Vì theo việc làm của loài người, Ngài sẽ báo ứng cho người ấy, khiến mỗi người tìm thấy điều xứng với con đường của mình.'),
(13696, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 12, 'OT', 'Quả thật, Đức Chúa Trời không làm điều ác, và Đấng Toàn Năng không làm lệch pháp lý.'),
(13697, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 13, 'OT', 'Ai đã giao cho Ngài trách nhiệm coi sóc đất nầy? Ai đã đặt Ngài cai trị toàn thể đất nầy?'),
(13698, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 14, 'OT', 'Nếu Ngài đặt lòng Ngài hướng về mình Ngài, rút lại thần khí và hơi thở của Ngài về mình Ngài,'),
(13699, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 15, 'OT', 'Thì mọi loài xác thịt sẽ chết chung nhau, và loài người sẽ trở về bụi đất.'),
(13700, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 16, 'OT', 'Nếu ngươi hiểu được, hãy nghe điều nầy; hãy lắng tai nghe tiếng lời nói của ta.'),
(13701, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 17, 'OT', 'Chớ thì người ghét sự xét xử, người ấy sẽ cai trị sao? Hay ngươi dám lên án Đấng công bình, Đấng Toàn năng?'),
(13702, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 18, 'OT', 'Có nên nói với vua rằng: "Ngươi là kẻ vô đạo" không? Hay nói với các quan rằng: "Hỡi kẻ gian ác"?'),
(13703, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 19, 'OT', 'Đức Chúa Trời không thiên vị các quan quyền, cũng không phân biệt kẻ giàu trước mặt người nghèo, vì tất cả đều là công việc của tay Ngài.'),
(13704, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 20, 'OT', 'Trong khoảnh khắc, họ chết cả; giữa đêm khuya, dân chúng rung chuyển và qua đời; những người cường quyền bị đem đi, chẳng phải bởi tay loài người.'),
(13705, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 21, 'OT', 'Vì mắt Đức Chúa Trời xem xét các nẻo đường của loài người, và Ngài thấy mọi bước đi của họ.'),
(13706, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 22, 'OT', 'Không có tối tăm, cũng không có bóng tối, để cho những kẻ làm ác ẩn náu mình tại đó.'),
(13707, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 23, 'OT', 'Vì Ngài không để cho loài người phải đến trước mặt Đức Chúa Trời hai lần để chịu xét xử.'),
(13708, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 24, 'OT', 'Người hủy diệt những kẻ cường quyền mà không cần tra xét, rồi lập những kẻ khác thế vào cho.'),
(13709, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 25, 'OT', 'Vì vậy, Ngài nhận biết các việc của chúng nó, và đánh đổ chúng nó trong đêm tối, khiến chúng bị hủy diệt.'),
(13710, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 26, 'OT', 'Người đánh phạt chúng dưới mắt thiên hạ, như những kẻ ác.'),
(13711, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 27, 'OT', 'Vì chúng xây bỏ Ngài, không để ý đến các đường lối Ngài.'),
(13712, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 28, 'OT', 'Chúng khiến tiếng kêu của kẻ nghèo đến cùng Ngài, và tiếng kêu của kẻ khốn khổ được Ngài nghe thấy.'),
(13713, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 29, 'OT', 'Nếu Ngài làm yên lặng, ai sẽ khiến gian ác? Nếu Ngài che khuất mặt, ai sẽ sửa cho người ấy? Dù cho một dân tộc hay cho một người riêng,'),
(13714, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 30, 'OT', 'Để ngăn kẻ ác trị vì, và không để ai giăng bẫy hại dân chúng.'),
(13715, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 31, 'OT', 'Vì ta đã nói cùng Đức Chúa Trời: Tôi đã mang chịu sửa phạt, tôi sẽ không còn gian ác nữa.'),
(13716, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 32, 'OT', 'Điều gì tôi không thấy, xin hãy dạy tôi; nếu tôi đã làm điều gian ác, tôi sẽ không làm nữa.'),
(13717, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 33, 'OT', 'Đức Chúa Trời há sẽ thưởng phạt theo ý ông sao? Vì ông đã từ chối, nên chính ông phải chọn lựa, chứ không phải tôi; vậy điều ông biết, hãy nói đi.'),
(13718, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 34, 'OT', 'Những người có lòng hãy nói với tôi, và người khôn ngoan đang nghe tôi, hãy lắng nghe tôi.'),
(13719, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 35, 'OT', 'Gióp nói mà không hiểu biết, và lời người không có sự thông sáng.'),
(13720, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 36, 'OT', 'Nguyện cho Gióp được thử thách đến trọn đời, vì những câu trả lời của người dành cho những kẻ gian ác.'),
(13721, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 34, 37, 'OT', 'Vì nó thêm sự phạm tội vào tội lỗi mình, vỗ tay mình giữa chúng ta, và nhân thêm những lời nói nghịch cùng Đức Chúa Trời.'),
(13722, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 35, 1, 'OT', 'Ê-li-hu đáp và nói rằng:'),
(13723, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 35, 2, 'OT', 'Hà, ngươi đã nghĩ điều này là công bình sao? Ngươi nói: Ta công bình hơn Đức Chúa Trời.'),
(13724, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 35, 3, 'OT', 'Dù ngươi nói: "Điều đó có ích gì cho ngươi? Ta há được lợi chi từ tội lỗi ta?"'),
(13725, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 35, 4, 'OT', 'Ta sẽ đáp lời ngươi, và các bạn hữu ngươi cùng với ngươi.'),
(13726, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 35, 5, 'OT', 'Hãy ngước nhìn các từng trời và xem, hãy xem các áng mây cao hơn ngươi.'),
(13727, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 35, 6, 'OT', 'Nếu ngươi phạm tội, há làm hại gì đến Đức Chúa Trời sao? Nếu ngươi phạm nhiều tội ác, há ảnh hưởng gì đến Ngài sao?'),
(13728, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 35, 7, 'OT', 'Nếu ngươi công bình, ngươi sẽ ban cho Ngài điều gì? Hoặc điều gì từ tay ngươi sẽ được Ngài nhận lấy?'),
(13729, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 35, 8, 'OT', 'Tội ác của ngươi chỉ làm hại người đồng loại ngươi, và sự công chính của ngươi chỉ làm ích cho một con người.'),
(13730, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 35, 9, 'OT', 'Vì nhiều sự áp bức, họ kêu la; kêu cứu vì tay kẻ quyền thế.'),
(13731, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 35, 10, 'OT', 'Nhưng không ai nói: Đức Chúa Trời, là Đấng Tạo Hóa tôi, ở đâu? Ngài ban những bài ca trong đêm.'),
(13732, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 35, 11, 'OT', 'Dạy dỗ chúng tôi thông sáng hơn các loài vật nơi đất, và làm cho chúng tôi khôn ngoan hơn các loài chim trên trời.'),
(13733, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 35, 12, 'OT', 'Chúng kêu cứu nhưng không ai trả lời, vì sự kiêu ngạo của kẻ ác.'),
(13734, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 35, 13, 'OT', 'Nhưng thật vô ích, Đức Chúa Trời không nghe; Đấng Toàn Năng chẳng đoái đến.'),
(13735, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 35, 14, 'OT', 'Dù ngươi có nói: "Ngài sẽ chẳng thấy ta đâu", hãy mang sự xét đoán của ngươi ra trước mặt Ngài và hãy đợi chờ Ngài.'),
(13736, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 35, 15, 'OT', 'Bây giờ, vì cơn thịnh nộ của Ngài chưa trừng phạt, và Ngài không để ý đến sự phạm tội cách nghiêm trọng.'),
(13737, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 35, 16, 'OT', 'Vả lại, Gióp mở miệng nói điều vô lý, và nhân nhiều lời không có tri thức.'),
(13738, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 1, 'OT', 'Ê-li-hu lại tiếp tục nói rằng:'),
(13739, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 2, 'OT', 'Xin hãy nhịn tôi một chút, tôi sẽ dạy ngươi; vì tôi còn những lời nói về Đức Chúa Trời.'),
(13740, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 3, 'OT', 'Tôi sẽ đem sự hiểu biết của tôi đến từ nơi xa, và sẽ ban cho Đấng Tạo Hóa tôi sự công chính.'),
(13741, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 4, 'OT', 'Vì quả thật lời tôi không phải là dối trá; Đấng có đầy đủ tri thức đang ở cùng ông.'),
(13742, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 5, 'OT', 'Nầy, Đức Chúa Trời quyền năng, không khinh bỉ ai; Ngài có sức lực lớn về trí tuệ.'),
(13743, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 6, 'OT', 'Người không cho kẻ ác sống, và ban công lý cho kẻ khốn cùng.'),
(13744, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 7, 'OT', 'Chúa không quay mắt khỏi người công bình, và Ngài khiến các vua ngồi trên ngôi đời đời, rồi được tôn cao.'),
(13745, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 8, 'OT', 'Nếu bị xiềng xích trói buộc, bị gian truân quấn như dây rợ,'),
(13746, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 9, 'OT', 'Người chỉ bảo cho họ việc họ làm, và những tội ác của họ, vì họ đã tự phụ.'),
(13747, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 10, 'OT', 'Ngài mở tai chúng để dạy dỗ, và phán rằng: "Hãy trở lại, đừng theo điều ác."'),
(13748, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 11, 'OT', 'Nếu chúng nghe và phục sự, thì các ngày của chúng sẽ trọn đời trong điều tốt lành, và những năm của chúng trong sự vui vẻ.'),
(13749, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 12, 'OT', 'Nếu họ không chịu nghe, thì sẽ chết mất vì gươm dao, và chết đi trong sự không hiểu biết.'),
(13750, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 13, 'OT', 'Những kẻ lòng chai dạ đá thì tích chứa cơn thịnh nộ; khi Đức Chúa Trời trói buộc chúng, chúng không kêu cứu.'),
(13751, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 14, 'OT', 'Họ chết khi còn trẻ tuổi, và đời sống họ tiêu vong giữa những kẻ gian tà.'),
(13752, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 15, 'OT', 'Đức Chúa Trời dùng sự khốn khổ mà giải cứu người khốn khổ; Ngài mở tai họ trong cơn gian truân.'),
(13753, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 16, 'OT', 'Ngài cũng đã muốn quyến dụ ông khỏi miệng gian truân, mở rộng không bị bóp nghẹt dưới nó; và sự an ủi nơi bàn ông đầy mỡ màng.'),
(13754, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 17, 'OT', 'Nhưng ngươi đã đầy sự xét đoán của kẻ ác; sự xét đoán và công lý sẽ nắm giữ ngươi.'),
(13755, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 18, 'OT', 'Đừng để cơn thịnh nộ dẫn ngươi đến chỗ phản kháng, cũng đừng để số tiền chuộc lớn làm ngươi lạc lối.'),
(13756, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 19, 'OT', 'Sự giàu có của ông có thể cứu ông khỏi cơn khốn khổ không? Hay tất cả các thế lực trong sức mạnh của ông?'),
(13757, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 20, 'OT', 'Đừng khao khát đêm tối, khi các dân bị dời khỏi nơi mình.'),
(13758, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 21, 'OT', 'Hãy giữ mình, chớ hướng về điều hư không; vì ấy là điều ngươi đã chọn thay cho sự khốn khổ.'),
(13759, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 22, 'OT', 'Kìa, Đức Chúa Trời lấy quyền năng Ngài mà làm cao cả; ai dạy được Ngài như vậy chăng?'),
(13760, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 23, 'OT', 'Ai đã chỉ dẫn đường lối cho người ấy? Và ai đã nói: Ngươi đã làm điều ác?'),
(13761, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 24, 'OT', 'Hãy nhớ tôn vinh công việc của Ngài, mà loài người thường ca ngợi.'),
(13762, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 25, 'OT', 'Mọi người đều đã thấy Ngài; loài người từ xa nhìn xem Ngài.'),
(13763, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 26, 'OT', 'Phải, Đức Chúa Trời rất cao cả, chúng ta không thể hiểu thấu; số năm của Ngài không thể dò xét, không ai kể xiết được.'),
(13764, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 27, 'OT', 'Vì Ngài làm cho các giọt nước co lại, rồi mưa từ đám mây mù ấy đổ xuống.'),
(13765, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 28, 'OT', 'Các đám mây nhỏ giọt nước mưa ấy xuống rất nhiều trên loài người.'),
(13766, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 29, 'OT', 'Dầu ai có thể hiểu được những đám mây rợp phủ, và tiếng động vang dội từ lều của Ngài?'),
(13767, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 30, 'OT', 'Kìa, Ngài giương ánh sáng ra chung quanh mình, và che phủ các gốc rễ của biển.'),
(13768, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 31, 'OT', 'Vì nhờ những điều ấy Ngài xét đoán các dân; Ngài ban thực phẩm cho kẻ mạnh.'),
(13769, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 32, 'OT', 'Người lấy tay che ánh sáng, và truyền cho nó phải đánh vào nơi nào.'),
(13770, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 36, 33, 'OT', 'Bạn hữu sẽ loan tin về nó, còn súc vật thì cảm thấy cơn bão sắp tới.'),
(13771, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 37, 1, 'OT', 'Vả lại, lòng tôi run sợ vì điều đó, và rời khỏi chỗ nó.'),
(13772, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 37, 2, 'OT', 'Hãy nghe, nghe tiếng vang rền rĩ của Ngài, và âm thanh vang ra từ miệng Ngài!'),
(13773, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 37, 3, 'OT', 'Ngài khiến nó dội dưới khắp các từng trời, và chớp sáng của Ngài chiếu đến các đầu cùng trái đất.'),
(13774, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 37, 4, 'OT', 'Sau đó, tiếng sấm vang lên, Ngài khiến sấm sét nổi lên trong tiếng oai hùng của Ngài; và khi tiếng Ngài vang lên, chẳng ai cản được ánh chớp.'),
(13775, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 37, 5, 'OT', 'Đức Chúa Trời làm sấm sét theo tiếng của Ngài, làm những điều kỳ diệu, những việc lớn lao mà không ai hiểu được.'),
(13776, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 37, 6, 'OT', 'Vì Ngài phán cùng tuyết rằng: "Hãy sa xuống đất!" và cùng mưa rào cùng các trận mưa lớn của quyền năng Ngài.'),
(13777, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 37, 7, 'OT', 'Ngài niêm phong tay của mỗi người, để cho mọi người biết được công việc của Ngài.'),
(13778, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 37, 8, 'OT', 'Bấy giờ các sinh vật vào nơi ẩn náu của chúng, và ở trong các hang nó.'),
(13779, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 37, 9, 'OT', 'Từ buồng trong bão táp nổi lên, và từ các khe hở, gió lạnh thổi đến.'),
(13780, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 37, 10, 'OT', 'Từ hơi thở của Đức Chúa Trời thì nước đá hình thành, và bề mặt của các khối nước thì bị đóng băng.'),
(13781, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 37, 11, 'OT', 'Người khiến mây nặng vì mưa, trải rộng mây sáng của Ngài.'),
(13782, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 37, 12, 'OT', 'Chính Ngài khiến mây chuyển động xoay vần theo mưu định của mình, để thực hiện mọi điều Ngài truyền lệnh trên khắp mặt đất.'),
(13783, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 37, 13, 'OT', 'Dù để trừng phạt, dù để đất, hay để làm ơn, Ngài khiến xảy ra.'),
(13784, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 37, 14, 'OT', 'Hỡi Gióp, hãy nghe điều nầy; khá đứng dậy và suy gẫm các việc diệu kỳ của Đức Chúa Trời.'),
(13785, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 37, 15, 'OT', 'Ông có biết Đức Chúa Trời đặt định các việc ấy ra sao, và làm cho chớp sáng từ đám mây của Ngài không?'),
(13786, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 37, 16, 'OT', 'Ông có biết cách phân chia các đám mây, những điều kỳ diệu của Đấng có tri thức trọn vẹn sao?'),
(13787, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 37, 17, 'OT', 'Áo quần ngươi nóng là vì đất yên lặng về phương nam?'),
(13788, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 37, 18, 'OT', 'Ông có thể cùng Đức Chúa Trời trải rộng các tầng trời ra không, những tầng trời vững chắc như một tấm kính đúc?'),
(13789, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 37, 19, 'OT', 'Hãy chỉ bảo chúng tôi biết điều chúng tôi phải nói với Ngài; chúng tôi không thể trình bày được vì sự tối tăm.'),
(13790, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 37, 20, 'OT', 'Người ta há sẽ thuật cùng Đức Chúa Trời rằng tôi muốn thưa với Ngài sao? Nếu người ta nói, quả hẳn sẽ bị nuốt đi.'),
(13791, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 37, 21, 'OT', 'Bây giờ, người ta không thấy ánh sáng rực rỡ, vì Ngài đã ẩn mình trong các tầng trời; nhưng gió thổi qua, làm cho chúng được tinh tẩy.'),
(13792, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 37, 22, 'OT', 'Vàng rực từ phương Bắc tuôn đến; trên Đức Chúa Trời là oai nghi khủng khiếp.'),
(13793, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 37, 23, 'OT', 'Đức Chúa Trời toàn năng, chúng ta không thể tìm thấy Ngài; quyền năng Ngài rất lớn, và về sự xét xử cùng sự công bình trọn vẹn, Ngài không hề trách phạt ai.'),
(13794, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 37, 24, 'OT', 'Vì vậy, người ta kính sợ Ngài; Ngài không nhìn đến bất cứ ai là khôn ngoan trong lòng.'),
(13795, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 1, 'OT', 'Đức Giê-hô-va đáp cùng Gióp từ giữa cơn bão và phán:'),
(13796, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 2, 'OT', 'Ai là người dùng những lời vô tri thức mà làm cho tối tăm các mưu định, không có sự hiểu biết?'),
(13797, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 3, 'OT', 'Hãy thắt lưng như người tráng sĩ; Ta sẽ hỏi ngươi, hãy đáp lại Ta!'),
(13798, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 4, 'OT', 'Khi Ta đặt nền trái đất, ngươi ở đâu? Nếu ngươi hiểu biết, hãy nói ra đi.'),
(13799, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 5, 'OT', 'Ai đã định kích thước cho nó, nếu ngươi biết? Hay ai đã giương dây đo trên nó?'),
(13800, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 6, 'OT', 'Nền nó dựa vào đâu? Ai đã đặt hòn đá tảng góc của nó?'),
(13801, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 7, 'OT', 'Khi ấy các ngôi sao mai cùng hát hòa nhau, và mọi con trai Đức Chúa Trời cất tiếng reo mừng.'),
(13802, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 8, 'OT', 'Khi biển bùng lên khỏi lòng mẹ, ai đã dùng cửa mà đóng lại cho nó?'),
(13803, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 9, 'OT', 'Khi Ta đặt mây làm áo cho nó, và lấy tăm tối làm khăn vấn cho nó;'),
(13804, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 10, 'OT', 'Ta đặt giới hạn cho nó, đặt then và cửa cho nó,'),
(13805, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 11, 'OT', 'Ta đã phán: "Đến đây, không được đi xa hơn nữa; đây là nơi ngươi phải dừng lại, hỡi những cơn sóng kiêu ngạo của ngươi!"'),
(13806, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 12, 'OT', 'Từ những ngày của ngươi, ngươi đã ra lệnh cho buổi sáng, ngươi đã biết chỗ ở của hừng đông,'),
(13807, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 13, 'OT', 'Để nắm lấy các rìa của đất và làm cho những kẻ ác bị lắc ra khỏi nó?'),
(13808, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 14, 'OT', 'Trái đất biến đổi như đất dưới dấu ấn, và mọi vật hiện ra như được mặc áo.'),
(13809, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 15, 'OT', 'Sự sáng bị cất khỏi kẻ ác, và cánh tay kiêu căng bị gãy.'),
(13810, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 16, 'OT', 'Ngươi có đi đến nơi sâu thẳm của biển, và bước đi trong vực thẳm hay chăng?'),
(13811, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 17, 'OT', 'Các cửa của sự chết há đã được tỏ ra cho ngươi sao? Ngươi có thấy các cửa của bóng tối sự chết chăng?'),
(13812, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 18, 'OT', 'Ngươi có nhìn thấu những khoảng rộng lớn của đất chăng? Hãy nói đi, nếu ngươi biết trọn điều đó.'),
(13813, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 19, 'OT', 'Đường nào dẫn đến nơi ở của ánh sáng, và nơi tối tăm ở đâu?'),
(13814, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 20, 'OT', 'Ngươi có thể dẫn nó đến ranh giới của nó và hiểu được các lối đi đến nhà nó sao?'),
(13815, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 21, 'OT', 'Ngươi hẳn biết, vì ngươi đã sinh ra từ xưa, và số năm đời ngươi thật nhiều.'),
(13816, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 22, 'OT', 'Ngươi đã vào các kho tuyết chưa? Ngươi có thấy các kho băng đá không?'),
(13817, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 23, 'OT', 'mà Ta đã để dành cho lúc khốn khó, cho ngày tranh chiến và chiến tranh.'),
(13818, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 24, 'OT', 'Đường nào chia ra ánh sáng, và gió đông được phát ra trên đất?'),
(13819, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 25, 'OT', 'Ai đã chia dòng nước lũ thành đường lạch, và mở đường cho ánh chớp của sấm sét?'),
(13820, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 26, 'OT', 'Để làm mưa xuống đất không có người, xuống đồng vắng không có ai ở;'),
(13821, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 27, 'OT', 'Để làm no đất hoang vu và cằn cỗi, và để khiến mọc lên nơi phát xuất của cỏ xanh.'),
(13822, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 28, 'OT', 'Mưa có cha chăng, hay ai đã sinh ra các giọt sương?'),
(13823, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 29, 'OT', 'Băng giá sinh ra từ lòng ai? Và sương giá trên trời ai là người sinh ra?'),
(13824, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 30, 'OT', 'Nước đông lại như đá, và mặt vực thẳm bị đóng chặt.'),
(13825, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 31, 'OT', 'Ngươi có thể buộc các dây nối của sao Kim Ngưu, hay tháo các xiềng của sao Đại Hùng ra được chăng?'),
(13826, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 32, 'OT', 'Ngươi có thể khiến các chòm sao xuất hiện đúng mùa, và dẫn dắt sao Bắc Đẩu cùng các con của nó ra chăng?'),
(13827, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 33, 'OT', 'Ngươi có biết các luật lệ của các từng trời, hay có thể lập quyền cai trị của nó trên đất chăng?'),
(13828, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 34, 'OT', 'Ngươi có thể cất tiếng mình lên cùng đám mây, khiến nước mưa bao phủ ngươi chăng?'),
(13829, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 35, 'OT', 'Ngươi có thể sai các tia chớp mà chúng đi sao, và chúng nói với ngươi: Thưa, chúng tôi đây?'),
(13830, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 36, 'OT', 'Ai đã đặt sự khôn ngoan trong lòng người, hoặc ban sự hiểu biết cho tâm trí chim?'),
(13831, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 37, 'OT', 'Ai là người dùng sự khôn ngoan mà đếm được các đám mây? Ai là người làm cho các bình trên trời đổ xuống?'),
(13832, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 38, 'OT', 'Khi bụi đất đông cứng thành khối và các cục đất dính lại với nhau?'),
(13833, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 39, 'OT', 'Ngươi có săn mồi cho sư tử đực, và làm đầy bụng cho các sư tử con sao?'),
(13834, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 40, 'OT', 'Khi sư tử cái nằm phục trong hang, khi chúng ngồi trong bụi rậm để rình mồi,'),
(13835, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 38, 41, 'OT', 'Ai sắm sửa đồ ăn cho quạ, khi con nó kêu cùng Đức Chúa Trời và đi lang thang vì không có gì ăn?'),
(13836, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 39, 1, 'OT', 'Ngươi có biết khi nào dê rừng đẻ không? Có để ý đến kỳ nai cái sinh con không?'),
(13837, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 39, 2, 'OT', 'Ngươi có biết bao nhiêu tháng nó đầy đủ, và biết kỳ nó sinh nở chăng?'),
(13838, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 39, 3, 'OT', 'Nó quỳ xuống, đẻ con nhỏ ra, và được giải thoát khỏi cơn đau đớn của mình.'),
(13839, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 39, 4, 'OT', 'Các con nó lớn mạnh, lớn lên trong đồng cỏ; chúng ra đi và không trở lại cùng nó.'),
(13840, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 39, 5, 'OT', 'Ai đã thả con lừa rừng tự do, và ai đã cởi trói cho con lừa hoang dã?'),
(13841, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 39, 6, 'OT', 'Ta đã đặt đồng vắng làm nhà cho nó, và những nơi ở của nó là đất mặn.'),
(13842, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 39, 7, 'OT', 'Nó chế giễu tiếng ồn ào của thành phố, tiếng reo hò của người coi sóc, nó không nghe.'),
(13843, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 39, 8, 'OT', 'Các ngọn núi là đồng cỏ của nó, và sau mọi thứ xanh tươi, nó tìm kiếm.'),
(13844, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 39, 9, 'OT', 'Con trâu rừng có chịu phục dịch ngươi chăng? Nó có chịu nằm nghỉ gần máng thức ăn ngươi chăng?'),
(13845, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 39, 10, 'OT', 'Ngươi há có thể lấy dây cột bò tót nơi luống cày sao? Nó há sẽ chịu cày các trũng sau ngươi chăng?'),
(13846, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 39, 11, 'OT', 'Ngươi há sẽ tin cậy nó vì sức lực nó lớn sao? Ngươi sẽ giao công việc cực nhọc của ngươi cho nó sao?'),
(13847, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 39, 12, 'OT', 'Ngươi có tin tưởng nó rằng nó sẽ mang lại hạt giống ngươi, và sân ngươi nó sẽ gom góp hay không?'),
(13848, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 39, 13, 'OT', 'Cánh chim công đập vui vẻ, nhưng cánh và lông nó há có lòng nhân từ chăng?'),
(13849, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 39, 14, 'OT', 'Vì nó để trứng mình xuống đất, và ấp ủ chúng trong bụi cát,'),
(13850, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 39, 15, 'OT', 'và nó quên rằng chân có thể giẫm nát nó, hay dẫm đạp nó dưới chân bởi dã thú ngoài đồng.'),
(13851, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 39, 16, 'OT', 'Nó làm cho con cái mình trở nên cứng cỏi, không phải vì nó; sự vất vả của nó là vô ích, chẳng sợ hãi gì.'),
(13852, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 39, 17, 'OT', 'Vì Đức Chúa Trời đã làm cho nó thiếu khôn ngoan, và không ban cho nó sự thông sáng.'),
(13853, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 39, 18, 'OT', 'Khi nó vỗ cánh bay lên cao, bèn nhạo báng ngựa và người cỡi ngựa.'),
(13854, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 39, 19, 'OT', 'Ngươi có ban sức mạnh cho con ngựa, có mặc cho cổ nó cái bờm phấp phới không?'),
(13855, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 39, 20, 'OT', 'Ngươi há khiến nó rung chuyển như châu chấu sao? Sức mạnh trong cổ nó thật đáng khiếp sợ.'),
(13856, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 39, 21, 'OT', 'Nó đào đất trong thung lũng, vui vẻ vì sức mạnh mình; lao ra nghênh chiến với ngọn giáo.'),
(13857, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 39, 22, 'OT', 'Nó cười vào sự sợ hãi, không kinh hoàng; trước lưỡi gươm, nó không quay lại.'),
(13858, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 39, 23, 'OT', 'Tiếng gươm giáo và ngọn giáo sáng chói vang vọng trên nó.'),
(13859, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 39, 24, 'OT', 'Nó hí vang, ngậm đất, rung chuyển cả đất đai; chẳng tin rằng tiếng kèn là thật.'),
(13860, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 39, 25, 'OT', 'Khi tiếng kèn vang lên, nó liền kêu: "Hã!"; từ xa nó đánh hơi thấy trận chiến, nghe tiếng vang của các quan trưởng và tiếng thét vang.'),
(13861, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 39, 26, 'OT', 'Con diều vùng bay có phải nhờ sự hiểu biết của ngươi mà sải cánh về hướng nam?'),
(13862, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 39, 27, 'OT', 'Phải chăng chim ưng vì ngươi mà bay lên cao, và làm tổ nó nơi chỗ cao?'),
(13863, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 39, 28, 'OT', 'Nó ở nơi vách đá và làm tổ, trên mỏm đá sắc và nơi hiểm trở.'),
(13864, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 39, 29, 'OT', 'Từ đó nó rình mồi, mắt nó thấy xa.'),
(13865, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 39, 30, 'OT', 'Các con nó mổ xé huyết, và nơi nào có những xác chết, thì chính nó ở đó.'),
(13866, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 40, 1, 'OT', 'Đức Giê-hô-va đáp lời ông Gióp, mà phán rằng:'),
(13867, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 40, 2, 'OT', 'Kẻ tranh luận cùng Đấng Toàn Năng, sẽ được sửa dạy sao? Kẻ bắt bẻ Đức Chúa Trời, hãy đáp lại đi!'),
(13868, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 40, 3, 'OT', 'Bấy giờ ông Gióp thưa cùng Đức Giê-hô-va rằng:'),
(13869, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 40, 4, 'OT', 'Này tôi thật nhỏ mọn, tôi sẽ đáp lại Ngài điều gì? Tay tôi đã đặt trên miệng tôi.'),
(13870, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 40, 5, 'OT', 'Tôi đã nói một lần rồi, mà không dám đáp lại; nói hai lần rồi, nhưng chẳng dám thêm điều gì nữa.'),
(13871, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 40, 6, 'OT', 'Từ giữa cơn bão, Đức Giê-hô-va đáp lời ông Gióp và phán:'),
(13872, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 40, 7, 'OT', 'Hãy thắt lưng như người tráng sĩ; Ta sẽ hỏi ngươi, hãy cho Ta biết.'),
(13873, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 40, 8, 'OT', 'Ngươi há muốn hủy bỏ sự xét đoán của ta, kết án ta để tự cho mình là công bình sao?'),
(13874, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 40, 9, 'OT', 'Ngươi có cánh tay như của Đức Chúa Trời chăng? Có thể dùng tiếng của mình mà gầm thét như Ngài sao?'),
(13875, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 40, 10, 'OT', 'Vậy hãy nhìn xem, hãy mặc lấy sự kiêu hãnh và ngạo mạn, mặc lấy vẻ vang và huy hoàng.'),
(13876, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 40, 11, 'OT', 'Hãy tuôn trào cơn thịnh nộ của ngươi, nhìn xem mọi kẻ kiêu ngạo và đánh hạ nó xuống.'),
(13877, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 40, 12, 'OT', 'Hãy nhìn xem mọi kẻ kiêu ngạo mà khuất phục nó, và đạp dưới chân những kẻ ác.'),
(13878, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 40, 13, 'OT', 'Hãy vùi chúng nó cùng nhau trong bụi đất, và lấy sự tối tăm che phủ mặt chúng nó.'),
(13879, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 40, 14, 'OT', 'Ta cũng sẽ ca ngợi ngươi, vì tay phải ngươi sẽ giải cứu ngươi.'),
(13880, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 40, 15, 'OT', 'Nầy, hãy xem con bò tót mà Ta đã làm ra cùng ngươi; nó ăn cỏ như bò.'),
(13881, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 40, 16, 'OT', 'Nầy, sức lực nó ở nơi hông, và quyền năng nó ở nơi gân bụng nó.'),
(13882, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 40, 17, 'OT', 'Đuôi nó vươn thẳng như cây hương bá, gân đùi nó đan chắc chắn.'),
(13883, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 40, 18, 'OT', 'Xương cốt nó như những ống đồng, gân cốt nó như những thanh sắt.'),
(13884, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 40, 19, 'OT', 'Nó là đầu công việc của Đức Chúa Trời; Đấng tạo nên nó đã đưa gươm cho nó.'),
(13885, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 40, 20, 'OT', 'Các núi non sanh đồng cỏ cho nó ăn, và mọi loài thú đồng đều chơi giỡn nơi đó.'),
(13886, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 40, 21, 'OT', 'Nó nằm dưới bóng cây, trong chỗ ẩn khuất của cây sậy và đầm lầy.'),
(13887, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 40, 22, 'OT', 'Các cây bóng râm che phủ nó; những bụi cây bên bờ suối vây quanh nó.'),
(13888, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 40, 23, 'OT', 'Nầy, nó không hốt hoảng khi sông chảy xiết; nó tin chắc rằng Giô-đanh sẽ phun vào miệng nó.'),
(13889, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 40, 24, 'OT', 'Người sẽ bắt lấy nó ngay trước mắt Người; bằng những cái bẫy, người ta sẽ đâm thủng lỗ mũi nó.'),
(13890, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 1, 'OT', 'Ngươi có thể câu con Li-vi-a-than bằng lưỡi câu, và dùng dây mà xỏ lưỡi nó sao?'),
(13891, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 2, 'OT', 'Có thể đặt một cái móc vào lỗ mũi nó, và xỏ xuyên qua hàm nó bằng một cái xiên ư?'),
(13892, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 3, 'OT', 'Nó há sẽ khẩn xin ngươi nhiều ơn, hay nói với ngươi những lời dịu dàng sao?'),
(13893, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 4, 'OT', 'Ngươi sẽ lập giao ước cùng nó, để bắt nó làm đầy tớ đời đời sao?'),
(13894, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 5, 'OT', 'Ngươi há sẽ chơi đùa với nó như với một con chim, và buộc nó cho các con gái nhỏ của ngươi chơi sao?'),
(13895, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 6, 'OT', 'Các thợ buôn sẽ mặc cả về nó; các lái buôn Kenaan sẽ chia cắt nó.'),
(13896, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 7, 'OT', 'Ngươi có thể lấy móc sắt có ngạnh đầy da nó, dùng ngọn giáo câu cá mà đầy đầu nó sao?'),
(13897, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 8, 'OT', 'Hãy đặt tay ngươi trên nó; hãy nhớ đến trận chiến, đừng làm điều đó nữa.'),
(13898, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 9, 'OT', 'Này, nếu ai mong bắt được nó thì sẽ thất vọng; còn chi thấy hình dạng nó mà không kinh hãi sao?'),
(13899, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 10, 'OT', 'Chẳng ai dám trêu chọc nó khi nó đang nổi giận; vậy ai có thể đứng vững trước mặt ta?'),
(13900, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 11, 'OT', 'Ai đã đối xử tốt với Ta trước mà đòi Ta phải đền đáp? Mọi vật dưới các từng trời đều thuộc về Ta.'),
(13901, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 12, 'OT', 'Ta sẽ không giữ im lặng về các chi thể nó, về lời nói về sức lực của nó và sự tốt đẹp của hình dáng nó.'),
(13902, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 13, 'OT', 'Ai có thể lột được lớp áo ngoài của nó? Ai dám vào giữa hai hàm răng của nó?'),
(13903, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 14, 'OT', 'Ai sẽ mở các cửa nơi mặt nó ra? Sự kinh khủng vây quanh các răng nó.'),
(13904, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 15, 'OT', 'Sự kiêu hãnh của nó gồm những hàng thuẫn khép kín, áp sát nhau như bị niêm phong.'),
(13905, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 16, 'OT', 'Chúng khép sát nhau từng cặp một, đến nỗi không khí không lọt qua được giữa chúng.'),
(13906, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 17, 'OT', 'Mỗi cái dính vào cái kia, gắn bó với nhau, không hề tách rời.'),
(13907, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 18, 'OT', 'Hơi phun ra từ mũi nó làm bừng sáng lên, và đôi mắt nó như mí mắt của bình minh.'),
(13908, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 19, 'OT', 'Từ miệng nó những ngọn lửa bắn ra, và những tia lửa bốc lên.'),
(13909, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 20, 'OT', 'Từ lỗ mũi nó khói bốc ra, như nồi đồng được thổi lửa và đun sôi.'),
(13910, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 21, 'OT', 'Hơi thở nó làm than hồng cháy bừng, và ngọn lửa từ miệng nó phun ra.'),
(13911, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 22, 'OT', 'Trong cổ nó, sức mạnh ngự trị; trước mặt nó, sự kinh hoàng nhảy múa.'),
(13912, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 23, 'OT', 'Các vảy thịt nó dính chặt vào nhau, như đúc liền trên thân nó, không hề lay chuyển.'),
(13913, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 24, 'OT', 'Lòng nó cứng như đá, đổ đúc như khúc đáy cối.'),
(13914, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 25, 'OT', 'Khi nó nổi dậy, các thần cũng run sợ; vì sợ hãi mà các bậc anh hùng phải tháo chạy.'),
(13915, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 26, 'OT', 'Gươm đâm nó cũng chẳng ăn nhập gì, giáo, lao và chùy cũng đều vô hiệu.'),
(13916, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 27, 'OT', 'Nó coi sắt khác nào rơm rạ, và đồng như thể gỗ mục nát.'),
(13917, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 28, 'OT', 'Mũi tên không khiến nó chạy trốn; đá bắn trúng nó cũng hóa như rơm rạ.'),
(13918, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 29, 'OT', 'Các gậy nó coi như rơm rạ, và nó cười nhạo tiếng rền vang của ngọn giáo.'),
(13919, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 30, 'OT', 'Dưới bụng nó là những mũi nhọn sắc bén; nó trải ra như cái cào cào trên bùn.'),
(13920, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 31, 'OT', 'Nó làm sôi nước sâu như cái nồi, khiến biển cả trở nên như cái chảo đựng dầu.'),
(13921, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 32, 'OT', 'Sau nó, đường đi phát sáng rạng rỡ; vực thẳm có thể tưởng là râu bạc.'),
(13922, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 33, 'OT', 'Trên đất không ai sánh bằng nó; nó được dựng nên để không sợ gì hết.'),
(13923, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 41, 34, 'OT', 'Người nhìn thấy mọi vật cao lớn; Người là Vua trên mọi con cái của sự kiêu ngạo.'),
(13924, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 42, 1, 'OT', 'Gióp đáp lời Đức Chúa Trời và nói rằng:'),
(13925, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 42, 2, 'OT', 'Tôi biết rằng Ngài có thể làm mọi sự, và không có mưu nào ngăn cản được từ nơi Ngài.'),
(13926, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 42, 3, 'OT', 'Ai là người làm mờ ý định bằng sự thiếu hiểu biết? Vì vậy, tôi đã nói mà không hiểu rõ, những điều kỳ diệu vượt quá tôi, tôi không thể biết được.'),
(13927, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 42, 4, 'OT', 'Xin hãy nghe, rồi tôi sẽ nói; tôi sẽ hỏi Ngài, và xin Ngài làm sáng tỏ cho tôi.'),
(13928, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 42, 5, 'OT', 'Trước kia tôi chỉ nghe bằng tai về Đức Giê-hô-va, nhưng bây giờ mắt tôi đã thấy Ngài.'),
(13929, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 42, 6, 'OT', 'Vì vậy, tôi ghét bỏ chính mình và ăn năn trong bụi tro.'),
(13930, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 42, 7, 'OT', 'Sau khi Đức Giê-hô-va phán các lời nầy với ông Gióp, thì Đức Giê-hô-va phán cùng Ê-li-pha người Thê-man rằng: Cơn thạnh nộ ta nổi lên cùng ngươi và hai bạn ngươi; vì các ngươi không nói về ta cách ngay thẳng như ông Gióp, kẻ tôi tớ ta.'),
(13931, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 42, 8, 'OT', 'Vậy bây giờ, các ngươi hãy lấy cho mình bảy con bò đực và bảy con chiên đực, rồi đi đến tôi tớ ta là Ái-áp, và dâng của lễ thiêu vì các ngươi; Ái-áp, tôi tớ ta sẽ cầu nguyện cho các ngươi, vì ta sẽ chấp nhận lời người, để không xử các ngươi theo sự ngu muội của các ngươi; vì các ngươi đã không nói về ta cách đúng đắn như Ái-áp, tôi tớ ta.'),
(13932, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 42, 9, 'OT', 'Ê-li-pha người Thê-man, Binh-đát người Su-a, và Sô-pha người Na-a-ma, bèn đi và làm theo điều Đức Giê-hô-va đã phán cùng họ; và Đức Giê-hô-va nhận lời cầu cho của ông Gióp.'),
(13933, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 42, 10, 'OT', 'Sau khi Gióp cầu nguyện cho bạn hữu mình, Đức Giê-hô-va khiến cảnh khốn khổ của Gióp được đổi lại, và Đức Giê-hô-va ban cho Gióp gấp đôi mọi thứ mà ông đã có.'),
(13934, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 42, 11, 'OT', 'Tất cả anh em trai, chị em gái và mọi người quen biết ông trước kia đều đến cùng ông, cùng ăn bánh trong nhà ông; họ chia buồn và an ủi ông về mọi tai họa mà Đức Giê-hô-va đã giáng trên ông; mỗi người cho ông một tiền bạc và một cái vòng vàng.'),
(13935, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 42, 12, 'OT', 'Đức Giê-hô-va ban phước cho phần cuối đời của Gióp hơn phần đầu đời người; người có mười bốn ngàn chiên, sáu ngàn lạc đà, một ngàn cặp bò, và một ngàn lừa cái.'),
(13936, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 42, 13, 'OT', 'Ông có bảy con trai và ba con gái.'),
(13937, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 42, 14, 'OT', 'Người đặt tên cho đứa con gái thứ nhất là Giê-mi-ma, tên đứa thứ hai là Kê-xia, và tên đứa thứ ba là Kê-ren-Ha-búc.'),
(13938, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 42, 15, 'OT', 'Trong khắp đất không tìm được người nữ nào đẹp bằng các con gái của Gióp; cha của các cô đã cấp cho các cô một phần gia nghiệp giữa các anh em của họ.'),
(13939, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 42, 16, 'OT', 'Sau những việc ấy, ông Gióp sống một trăm bốn mươi năm, và thấy các con, các cháu, chắt và chít của mình, đến đời thứ tư.'),
(13940, 18, 'GOI_vi', 'GOI_vi', 'vi', 'JOB', 42, 17, 'OT', 'Sau đó, ông Gióp qua đời, một người già nua và sống lâu năm.'),
(13941, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 1, 1, 'OT', 'Phước cho người nào không theo mưu kế của kẻ ác, không đứng trên con đường của người tội lỗi, và không ngồi nơi chỗ hội hiệp của những kẻ nhạo báng.'),
(13942, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 1, 2, 'OT', 'Nhưng lấy làm vui vẻ về luật pháp của Đức Giê-hô-va, và suy gẫm luật pháp ấy ngày và đêm.'),
(13943, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 1, 3, 'OT', 'Sẽ như cây trồng bên bờ các dòng nước, sinh quả đúng mùa nó, lá nó không hề héo úa; và mọi điều người ấy làm đều thạnh vượng.'),
(13944, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 1, 4, 'OT', 'Kẻ ác không phải như vậy đâu; nhưng chúng nó khác nào rơm rạ mà gió thổi đi.'),
(13945, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 1, 5, 'OT', 'Bởi vậy, kẻ ác sẽ không đứng vững trong ngày phán xét, và tội nhân cũng không đứng trong hội người công bình.'),
(13946, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 1, 6, 'OT', 'Vì Đức Giê-hô-va biết con đường của người công bình, nhưng con đường của kẻ ác sẽ bị tiêu diệt.'),
(13947, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 2, 1, 'OT', 'Tại sao các dân lại náo động, và các nước toan tính điều vô ích?'),
(13948, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 2, 2, 'OT', 'Các vua đất cùng đứng dậy, các quan quyền liên hiệp đồng lòng nghịch cùng Đức Giê-hô-va và nghịch cùng Đấng Christ của Ngài.'),
(13949, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 2, 3, 'OT', 'Hãy bẻ gãy xiềng xích họ, và quăng xa khỏi mình dây trói của chúng.'),
(13950, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 2, 4, 'OT', 'Đức Giê-hô-va ngự nơi các từng trời sẽ cười, Chúa sẽ nhạo báng chúng nó.'),
(13951, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 2, 5, 'OT', 'Bấy giờ, Ngài sẽ phán với chúng nó trong cơn thạnh nộ, và dùng cơn giận của Ngài khiến chúng nó hoảng sợ.'),
(13952, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 2, 6, 'OT', 'Nhưng ta đã lập vua ta làm vua trên Si-ôn, núi thánh của ta.'),
(13953, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 2, 7, 'OT', 'Ta sẽ công bố điều Đức Giê-hô-va đã chỉ định: Người phán cùng ta: "Ngươi là Con Ta, hôm nay Ta đã sinh ngươi."'),
(13954, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 2, 8, 'OT', 'Hãy xin Ta, Ta sẽ ban cho ngươi các nước làm cơ nghiệp, và các đầu mút đất làm phần sở hữu ngươi.'),
(13955, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 2, 9, 'OT', 'Ngài sẽ đập tan chúng nó bằng cây gậy sắt; Ngài sẽ đập bể chúng nó như cái chén của thợ gốm.'),
(13956, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 2, 10, 'OT', 'Bây giờ, hỡi các vua, hãy thông sáng; hãy chịu sửa dạy, hỡi các quan xét đất.'),
(13957, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 2, 11, 'OT', 'Hãy hầu việc Đức Giê-hô-va cách kính sợ, và hãy vui mừng cách run rẩy.'),
(13958, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 2, 12, 'OT', 'Hãy hôn Con, e rằng Ngài nổi giận, các ngươi sẽ hư mất trên đường đời; vì cơn thịnh nộ của Ngài sẽ bừng cháy trong chốc lát. Phước thay cho mọi kẻ nương náu nơi Ngài.'),
(13959, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 3, 1, 'OT', 'Lời cầu nguyện của Đa-vít, khi ông chạy trốn trước mặt Áp-xa-lôm, con trai mình. Đức Giê-hô-va ôi, bao nhiêu kẻ thù tôi đã gia tăng! Nhiều kẻ dấy lên nghịch cùng tôi!'),
(13960, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 3, 2, 'OT', 'Biết bao kẻ nói với linh hồn tôi rằng: "Nơi Đức Chúa Trời chẳng có sự cứu rỗi cho nó."'),
(13961, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 3, 3, 'OT', 'Nhưng, hỡi Đức Giê-hô-va, Ngài là cái khiên che chở tôi; là sự vinh hiển tôi, và là Đấng nâng đầu tôi lên.'),
(13962, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 3, 4, 'OT', 'Tôi lấy tiếng tôi mà kêu cầu Đức Giê-hô-va, và Ngài đáp lời tôi từ núi thánh của Ngài.'),
(13963, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 3, 5, 'OT', 'Tôi nằm xuống và ngủ; tôi thức dậy, vì Đức Giê-hô-va nâng đỡ tôi.'),
(13964, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 3, 6, 'OT', 'Tôi sẽ không sợ muôn người vây quanh tôi.'),
(13965, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 3, 7, 'OT', 'Hỡi Đức Giê-hô-va, hãy chỗi dậy; Hỡi Đức Chúa Trời tôi, hãy cứu tôi! Vì Ngài đã đánh vào hàm tất cả các kẻ thù tôi, Và bẻ gãy răng những kẻ ác.'),
(13966, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 3, 8, 'OT', 'Sự cứu rỗi thuộc về Đức Giê-hô-va; trên dân Ngài, nguyện phước lành của Ngài ở đó.'),
(13967, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 4, 1, 'OT', 'Đức Chúa Trời của sự công bình tôi, khi tôi kêu cầu, xin hãy đáp lời tôi; trong cơn gian truân, Ngài mở rộng chỗ cho tôi. Xin hãy thương xót tôi và nghe lời cầu nguyện tôi.'),
(13968, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 4, 2, 'OT', 'Hỡi con loài người, bao lâu vinh hiển ta còn bị sỉ nhục? Các ngươi sẽ yêu điều hư không, tìm kiếm điều dối trá đến chừng nào?'),
(13969, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 4, 3, 'OT', 'Hãy biết rằng Đức Giê-hô-va đã biệt riêng người trung tín cho chính mình; khi tôi kêu cầu Đức Giê-hô-va, Ngài sẽ nhậm lời tôi.'),
(13970, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 4, 4, 'OT', 'Hãy run sợ và chớ phạm tội; trong lòng mình, trên giường các ngươi hãy tự nói và nín lặng.'),
(13971, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 4, 5, 'OT', 'Hãy dâng những của lễ công bình, và hãy tin cậy nơi Đức Giê-hô-va.'),
(13972, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 4, 6, 'OT', 'Nhiều người nói: Ai sẽ cho chúng ta thấy điều thiện? Xin hãy soi trên chúng tôi ánh sáng mặt Ngài, hỡi Đức Giê-hô-va.'),
(13973, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 4, 7, 'OT', 'Ngài đã đặt niềm vui trong lòng tôi, hơn cả khi lúa mì và rượu nho của chúng nó gia tăng.'),
(13974, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 4, 8, 'OT', 'Tôi sẽ nằm xuống và ngủ một cách bình an, vì chỉ mình Đức Giê-hô-va khiến tôi được ở an toàn.'),
(13975, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 5, 1, 'OT', 'Đức Giê-hô-va ôi, xin lắng nghe lời tôi, để ý đến tiếng kêu than của tôi.'),
(13976, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 5, 2, 'OT', 'Lạy Vua tôi, Đức Chúa Trời tôi, xin hãy lắng nghe tiếng kêu của tôi, vì tôi cầu nguyện cùng Ngài.'),
(13977, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 5, 3, 'OT', 'Đức Giê-hô-va ôi! Buổi sáng Ngài sẽ nghe tiếng tôi; buổi sáng tôi sẽ dọn sẵn lời cầu nguyện cho Ngài và chăm chú nhìn xem.'),
(13978, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 5, 4, 'OT', 'Vì Ngài không phải là Đức Chúa Trời ham thích điều ác; kẻ gian ác không thể cư ngụ nơi Ngài.'),
(13979, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 5, 5, 'OT', 'Kẻ gian ác không đứng vững trước mặt Đức Giê-hô-va; Ngài ghét tất cả những kẻ làm điều ác.'),
(13980, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 5, 6, 'OT', 'Đức Giê-hô-va sẽ hủy diệt những kẻ nói lời dối trá; Ngài gớm ghét người đổ máu và kẻ gian dối.'),
(13981, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 5, 7, 'OT', 'Còn tôi, nhờ sự nhân từ lớn lao của Đức Giê-hô-va, tôi sẽ vào nhà Ngài; tôi sẽ thờ lạy hướng về đền thánh khiết của Ngài với lòng kính sợ Ngài.'),
(13982, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 5, 8, 'OT', 'Hỡi Đức Giê-hô-va, xin hãy dẫn tôi trong sự công bình của Ngài vì cớ những kẻ thù nghịch tôi; xin hãy làm cho đường lối Ngài ngay thẳng trước mặt tôi.'),
(13983, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 5, 9, 'OT', 'Vì nơi miệng chúng nó chẳng có điều chân thật; lòng chúng nó đầy dẫy điều gian ác; họng chúng nó như mồ mả mở ngỏ; lưỡi chúng nó trơn trượt.'),
(13984, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 5, 10, 'OT', 'Hỡi Đức Chúa Trời, xin hãy trừng phạt chúng nó; nguyện chúng nó sa ngã từ các mưu kế của chúng nó; vì sự phạm tội rất nhiều mà xô đuổi chúng nó khỏi, vì chúng nó đã chống nghịch cùng Đức Giê-hô-va.'),
(13985, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 5, 11, 'OT', 'Nhưng ai nương náu nơi Ngài sẽ được vui mừng mãi mãi, luôn luôn reo vui; Ngài sẽ che chở họ, và những người yêu mến danh Ngài sẽ hân hoan trong Ngài.'),
(13986, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 5, 12, 'OT', 'Vì chính Ngài sẽ ban phước cho người công bình, hỡi Đức Giê-hô-va, lấy ơn Ngài mà che chở người như bằng cái khiên.'),
(13987, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 6, 1, 'OT', 'Đức Giê-hô-va ôi, xin chớ lấy cơn thạnh nộ mà quở trách tôi, cũng chớ lấy cơn giận mà sửa dạy tôi.'),
(13988, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 6, 2, 'OT', 'Hỡi Đức Giê-hô-va, xin thương xót tôi, vì tôi yếu mỏn; Lạy Đức Giê-hô-va, xin chữa lành tôi, vì xương cốt tôi run rẩy.'),
(13989, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 6, 3, 'OT', 'Và linh hồn tôi bối rối quá đỗi; Đức Giê-hô-va ôi, còn đến chừng nào?'),
(13990, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 6, 4, 'OT', 'Lạy Đức Giê-hô-va, xin hãy trở lại, cứu giải linh hồn tôi; cứu tôi đi, vì cớ lòng nhân từ của Ngài.'),
(13991, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 6, 5, 'OT', 'Vì trong sự chết đâu còn nhớ đến Ngài; nơi âm phủ, ai sẽ cảm tạ Ngài?'),
(13992, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 6, 6, 'OT', 'Tôi mõi mệt vì than vãn; mỗi đêm tôi làm trôi giường tôi, ngâm dầm nó với nước mắt tôi.'),
(13993, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 6, 7, 'OT', 'Mắt tôi hao mòn vì tức giận, suy yếu đi vì hết thảy kẻ thù tôi.'),
(13994, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 6, 8, 'OT', 'Hỡi mọi kẻ làm ác, hãy lìa khỏi ta; vì Đức Giê-hô-va đã nghe tiếng khóc than của ta.'),
(13995, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 6, 9, 'OT', 'Đức Giê-hô-va đã nghe sự nài xin của tôi; Đức Giê-hô-va nhận lời cầu nguyện của tôi.'),
(13996, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 6, 10, 'OT', 'Hết thảy kẻ thù tôi sẽ phải hổ thẹy và bối rối dữ dội; chúng sẽ quay lui, hổ thẹy tức thì.'),
(13997, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 7, 1, 'OT', 'Bài ca của Đa-vít, mà người đã hát cho Đức Giê-hô-va, về lời của Cu-sơ, con trai của Y-mi-ni. Hỡi Đức Giê-hô-va Đức Chúa Trời tôi, tôi tin cậy nơi Ngài; xin cứu tôi khỏi mọi kẻ đuổi theo tôi và giải thoát tôi,'),
(13998, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 7, 2, 'OT', 'Kẻo nó nuốt lấy linh hồn tôi như sư tử, xé xác ra, mà chẳng ai cứu giúp.'),
(13999, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 7, 3, 'OT', 'Hỡi Đức Giê-hô-va Đức Chúa Trời tôi, nếu tôi đã làm điều nầy, nếu trong tay tôi có sự gian ác;'),
(14000, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 7, 4, 'OT', 'Nếu tôi đã lấy ác báo người sống hòa thuận với tôi, và đã cứu kẻ thù tôi cách vô cớ,'),
(14001, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 7, 5, 'OT', 'Nguyện kẻ thù đuổi theo mạng tôi, bắt kịp, giày đạp mạng sống tôi xuống đất, và làm nhục vinh hiển tôi nằm trong bụi.'),
(14002, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 7, 6, 'OT', 'Lạy Đức Giê-hô-va, xin chỗi dậy trong cơn thạnh nộ Ngài, hãy dấy lên chống lại cơn giận của kẻ thù nghịch tôi; xin thức tỉnh vì tôi, theo sự đoán xét mà Ngài đã truyền định.'),
(14003, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 7, 7, 'OT', 'Hội các dân sẽ vây quanh Ngài; và trên hội ấy, hãy trở lại nơi cao.'),
(14004, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 7, 8, 'OT', 'Đức Giê-hô-va sẽ xét xử các dân; Đức Giê-hô-va ôi, xin hãy xét đoán tôi theo sự công chính và sự ngay thẳng của tôi.'),
(14005, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 7, 9, 'OT', 'Lạy Đức Chúa Trời công bình, Đấng dò xét lòng và nội tạng, xin hãy chấm dứt sự ác của kẻ ác, và xác lập người công bình.'),
(14006, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 7, 10, 'OT', 'Đức Chúa Trời là cái khiên của tôi, Đấng cứu những kẻ lòng ngay thẳng.'),
(14007, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 7, 11, 'OT', 'Đức Chúa Trời là Đấng xét xử người công chính, và là Đức Chúa Trời đầy cơn thịnh nộ mỗi ngày.'),
(14008, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 7, 12, 'OT', 'Nếu nó không trở lại, thì gươm nó sẽ mài nhọn; cung nó đã giương ra và giương sẵn,'),
(14009, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 7, 13, 'OT', 'Và cho nó, Ngài đã chuẩn bị những khí giới gây chết; những mũi tên của Ngài, Ngài làm cho bừng cháy.'),
(14010, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 7, 14, 'OT', 'Nầy, nó chịu đau đẻ điều ác, hoài thai sự gian trá, và sinh ra điều dối trá.'),
(14011, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 7, 15, 'OT', 'Đào hố và đào sâu, rồi rơi vào hố mình đã làm.'),
(14012, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 7, 16, 'OT', 'Sự ác nó gây ra sẽ đổ lại trên đầu nó, và trên trán nó, bạo lực nó sẽ giáng xuống.'),
(14013, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 7, 17, 'OT', 'Tôi sẽ ngợi khen Đức Giê-hô-va theo sự công bình Ngài, và sẽ hát xướng danh Đức Giê-hô-va là Đấng Chí Cao.'),
(14014, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 8, 1, 'OT', 'Đức Giê-hô-va, Đức Chúa Trời chúng tôi, danh Ngài oai nghiêm biết bao trên khắp đất, Ngài đã đặt sự rực rỡ của Ngài trên các từng trời.'),
(14015, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 8, 2, 'OT', 'Từ miệng trẻ sơ sinh và những kẻ đang bú, Ngài đã thiết lập sức mạnh, để khiến kẻ thù và kẻ báo thù phải im lặng.'),
(14016, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 8, 3, 'OT', 'Khi tôi nhìn xem các từng trời, là công việc của ngón tay Ngài, mặt trăng và các ngôi sao mà Ngài đã lập nên,'),
(14017, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 8, 4, 'OT', 'Loài người là gì mà Ngài nhớ đến? Con loài người là chi mà Ngài thăm viếng?'),
(14018, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 8, 5, 'OT', 'Ngài khiến người chỉ kém một ít Đức Chúa Trời, và đội cho người sự vinh hiển cùng sự sang trọng.'),
(14019, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 8, 6, 'OT', 'Ngài khiến người cai trị các công việc của tay Ngài làm; mọi vật Ngài đặt dưới chân người.'),
(14020, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 8, 7, 'OT', 'Cả chiên lẫn bò, và muôn thú ngoài đồng.'),
(14021, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 8, 8, 'OT', 'Chim trời và cá biển, cùng những vật nào đi qua các lối của biển.'),
(14022, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 8, 9, 'OT', 'Hỡi Đức Giê-hô-va là Chúa chúng tôi, danh Ngài oai nghiêm biết bao trên khắp đất!'),
(14023, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 9, 1, 'OT', 'Tôi sẽ cảm tạ Đức Giê-hô-va hết lòng mình, Kể ra các việc lạ lùng của Ngài.'),
(14024, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 9, 2, 'OT', 'Hỡi Đấng Chí Cao, tôi sẽ vui mừng và hân hoan trong Ngài; tôi sẽ ca ngợi danh Ngài.'),
(14025, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 9, 3, 'OT', 'Khi kẻ thù tôi lui bước, chúng nó vấp ngã và bị tiêu diệt trước mặt Đức Giê-hô-va.'),
(14026, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 9, 4, 'OT', 'Vì Ngài xét xử công bình cho tôi, và Ngài ngồi trên ngôi xét đoán cách ngay thẳng.'),
(14027, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 9, 5, 'OT', 'Ngài quở trách các dân, tiêu diệt kẻ ác; danh chúng nó Ngài xóa đi đời đời mãi mãi.'),
(14028, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 9, 6, 'OT', 'Kẻ thù bị tiêu diệt tận cùng đời đời; các thành của nó Ngài đã phá đổ, kỷ niệm về chúng đã tiêu tan.'),
(14029, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 9, 7, 'OT', 'Nhưng Đức Giê-hô-va ngự đời đời; Ngài lập ngôi mình cho sự đoán xét.'),
(14030, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 9, 8, 'OT', 'Đức Giê-hô-va sẽ xét xử thế gian cách công bình, và đoán các dân tộc cách ngay thẳng.'),
(14031, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 9, 9, 'OT', 'Đức Giê-hô-va sẽ là nơi náu ẩn cao cho kẻ bị áp bức, một nơi náu ẩn cao trong lúc gian truân.'),
(14032, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 9, 10, 'OT', 'Hỡi Đức Giê-hô-va, những người biết danh Ngài sẽ tin cậy nơi Ngài; vì Ngài chẳng từ bỏ những kẻ tìm kiếm Ngài.'),
(14033, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 9, 11, 'OT', 'Hãy hát ngợi khen Đức Giê-hô-va, là Đấng ngự tại Si-ôn; hãy loan truyền giữa các dân những việc Ngài làm.'),
(14034, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 9, 12, 'OT', 'Vì Ngài tìm kiếm những kẻ bị giết, Ngài nhớ đến họ; chẳng hề quên tiếng kêu của kẻ khốn cùng.'),
(14035, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 9, 13, 'OT', 'Đức Giê-hô-va ôi, xin thương xót tôi; xin nhìn xem sự khốn khổ tôi vì những kẻ ghét tôi, Đấng nâng tôi lên khỏi các cửa của sự chết.'),
(14036, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 9, 14, 'OT', 'Hầu cho tại các cổng thành của con gái Si-ôn, tôi sẽ thuật mọi lời ca ngợi danh Ngài, và vui mừng vì sự cứu giúp của Ngài.'),
(14037, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 9, 15, 'OT', 'Các dân tộc đã sa xuống hố mà chúng đã làm; chân chúng nó vướng vào lưới mà chúng đã giăng.'),
(14038, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 9, 16, 'OT', 'Đức Giê-hô-va được biết đến khi thi hành sự xét xử; Ngài dùng công việc tay mình mà gài bẫy cho kẻ ác. Hết.'),
(14039, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 9, 17, 'OT', 'Kẻ ác sẽ trở lại âm phủ, mọi dân tộc quên Đức Chúa Trời.'),
(14040, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 9, 18, 'OT', 'Kẻ thiếu thốn sẽ không bị quên đời đời, sự trông cậy của người khiêm nhường sẽ không bị tiêu mất mãi mãi.'),
(14041, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 9, 19, 'OT', 'Hỡi Đức Giê-hô-va, xin hãy chỗi dậy, đừng để loài người được thắng; các dân hãy bị xét xử trước mặt Ngài.'),
(14042, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 9, 20, 'OT', 'Hỡi Đức Giê-hô-va, xin đặt sự kinh hãi trên chúng nó; nguyện các dân biết mình chỉ là loài người, chỉ là người phàm. Selah'),
(14043, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 10, 1, 'OT', 'Đức Giê-hô-va ôi! Vì sao Ngài đứng xa? Tại thời gian hoạn nạn, sao Ngài ẩn mình?'),
(14044, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 10, 2, 'OT', 'Vì lòng kiêu ngạo của kẻ ác, kẻ khốn cùng bị hăm dọa; nguyện chúng nó mắc vào mưu kế mà chúng đã toan tính.'),
(14045, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 10, 3, 'OT', 'Vì kẻ ác tự hào về lòng tham của mình, và kẻ tham lam phỉ báng Đức Giê-hô-va.'),
(14046, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 10, 4, 'OT', 'Kẻ ác vì kiêu ngạo mà không tìm kiếm; chẳng có Đức Chúa Trời là điều chi phối mọi mưu toan của hắn.'),
(14047, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 10, 5, 'OT', 'Các nẻo đường của hắn đều thịnh vượng trong mọi thời; các sự xét đoán của Ngài cao vượt quá trước mặt hắn; hắn thổi phớt lờ mọi kẻ thù nghịch mình.'),
(14048, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 10, 6, 'OT', 'Người ấy nói trong lòng mình: "Ta sẽ không bị dời bỏ; đời nầy sang đời khác, ta sẽ chẳng gặp điều ác."'),
(14049, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 10, 7, 'OT', 'Miệng nó đầy lời nguyền rủa, gian dối và mưu mô; dưới lưỡi nó là sự đau khổ và gian ác.'),
(14050, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 10, 8, 'OT', 'Hắn ngồi trong chỗ rình rập gần các làng mạc, trong nơi khuất tất giết kẻ vô tội; mắt hắn rình rập người khốn cùng.'),
(14051, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 10, 9, 'OT', 'Hắn rình rập trong nơi khuất như sư tử trong bụi rậm, rình rập để bắt kẻ khốn cùng; khi kéo kẻ khốn cùng vào lưới mình, thì bắt được người ấy.'),
(14052, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 10, 10, 'OT', 'Hắn cúi xuống, sập bẫy; kẻ khốn khổ ngã vào tay hắn.'),
(14053, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 10, 11, 'OT', 'Người nói trong lòng mình: "Đức Chúa Trời đã quên, Ngài đã che mặt mình, sẽ chẳng nhìn thấy đến mãi mãi."'),
(14054, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 10, 12, 'OT', 'Hỡi Đức Giê-hô-va, xin hãy chỗi dậy; hỡi Đức Chúa Trời, hãy giơ tay Ngài lên; chớ quên kẻ khốn cùng.'),
(14055, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 10, 13, 'OT', 'Tại sao kẻ ác khinh dể Đức Chúa Trời, và nói trong lòng rằng: Ngài sẽ không tìm kiếm?'),
(14056, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 10, 14, 'OT', 'Ngài đã thấy, vì chính Ngài nhìn xem sự đau khổ và cơn giận dữ, để đặt nơi tay Ngài mà báo ứng; kẻ yếu thế giao phó cho Ngài, chính Ngài là Đấng phù trợ kẻ mồ côi.'),
(14057, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 10, 15, 'OT', 'Xin hãy bẻ gãy cánh tay kẻ ác và kẻ dữ; xin tra xét sự ác nó, chẳng còn thấy được nữa.'),
(14058, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 10, 16, 'OT', 'Đức Giê-hô-va làm Vua đời đời vô cùng; các dân tộc đã bị tiêu diệt khỏi đất của Ngài.'),
(14059, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 10, 17, 'OT', 'Hỡi Đức Giê-hô-va, Ngài đã nghe điều ước ao của kẻ khiêm nhường; Ngài khiến lòng họ được vững bền, và Ngài lắng tai nghe.'),
(14060, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 10, 18, 'OT', 'Để xét xử kẻ mồ côi và người bị hà hiếp, hầu cho loài người không còn làm cho sợ hãi nữa từ đất.'),
(14061, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 11, 1, 'OT', 'Cho Đức Giê-hô-va tôi đã nương náu; sao các ngươi nói cùng linh hồn tôi: Hãy trốn lên núi như con chim?'),
(14062, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 11, 2, 'OT', 'Vì kìa, những kẻ ác đang giương cung, tra tên mình trên dây, để bắn vào những kẻ lòng ngay thẳng trong bóng tối.'),
(14063, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 11, 3, 'OT', 'Nếu các nền bị phá đổ, người công bình sẽ làm gì?'),
(14064, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 11, 4, 'OT', 'Đức Giê-hô-va ở trong đền thánh Ngài; Đức Giê-hô-va ngôi Ngài ở trên trời; mắt Ngài nhìn xem, mí mắt Ngài dò xét con loài người.'),
(14065, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 11, 5, 'OT', 'Đức Giê-hô-va thử người công bình; còn người ác và kẻ yêu thích bạo lực, linh hồn Ngài ghét.'),
(14066, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 11, 6, 'OT', 'Ngài sẽ giáng trên các kẻ ác những cái bẫy, lửa và bụi than; gió nóng sẽ là phần trong chén của chúng nó.'),
(14067, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 11, 7, 'OT', 'Vì Đức Giê-hô-va là công chính, Ngài yêu những điều công chính; người ngay thẳng sẽ chiêm ngưỡng mặt Ngài.'),
(14068, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 12, 1, 'OT', 'Đức Giê-hô-va ôi, xin cứu giúp, vì người nhân từ đã tiêu tan, và kẻ trung tín không còn nữa giữa con loài người.'),
(14069, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 12, 2, 'OT', 'Chúng nó đều nói dối người nầy với người kia; môi láo xảo hùng hổ, lòng nầy nói với lòng kia.'),
(14070, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 12, 3, 'OT', 'Đức Giê-hô-va sẽ diệt mọi môi môi trơn tru, và lưỡi nói những điều kiêu căng.'),
(14071, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 12, 4, 'OT', 'Là những kẻ nói: Nhờ lưỡi mình, ta sẽ mạnh; môi ta thuộc về ta; ai là Chúa trên ta?'),
(14072, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 12, 5, 'OT', 'Vì cớ sự hà hiếp người khốn khổ và tiếng rên siết người nghèo hèn, Đức Giê-hô-va phán: Bây giờ ta sẽ chỗi dậy, đặt người trong sự an ổn mà người mong ước.'),
(14073, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 12, 6, 'OT', 'Các lời của Đức Giê-hô-va là những lời trong sạch, như bạc được thử trong lò đất, đã luyện đến bảy lần.'),
(14074, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 12, 7, 'OT', 'Đức Giê-hô-va, Ngài sẽ gìn giữ họ, bảo vệ họ khỏi dòng dõi nầy đời đời.'),
(14075, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 12, 8, 'OT', 'Xung quanh, kẻ ác đi lại tự do, khi sự hạ tiện được nâng cao giữa con cái loài người.'),
(14076, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 13, 1, 'OT', 'Đức Giê-hô-va ôi, còn bao lâu Ngài sẽ quên tôi mãi mãi? Còn bao lâu Ngài sẽ giấu mặt Ngài khỏi tôi?'),
(14077, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 13, 2, 'OT', 'Lạy Đức Giê-hô-va, đến bao giờ Ngài còn để tôi phải lo lắng trong lòng, ngày ngày than khóc trong lòng tôi cho đến bao giờ? Kẻ thù tôi sẽ còn ngạo mạn trên tôi cho đến bao giờ?'),
(14078, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 13, 3, 'OT', 'Hỡi Đức Giê-hô-va, Đức Chúa Trời tôi, xin hãy nhìn xem và nhậm lời tôi; hãy soi sáng đôi mắt tôi, kẻo tôi ngủ trong cái chết.'),
(14079, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 13, 4, 'OT', 'Đừng để kẻ thù tôi nói: "Tôi đã thắng được nó"; Đừng để kẻ chống nghịch tôi vui mừng khi tôi vấp ngã.'),
(14080, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 13, 5, 'OT', 'Nhưng tôi đã tin cậy nơi sự nhân từ của Đức Giê-hô-va; lòng tôi vui mừng về sự cứu rỗi của Ngài.'),
(14081, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 13, 6, 'OT', 'Tôi sẽ hát ngợi khen Đức Giê-hô-va, vì Ngài đã làm điều tốt lành cho tôi.'),
(14082, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 14, 1, 'OT', 'Kẻ ngu dại nói trong lòng rằng: chẳng có Đức Chúa Trời. Chúng nó đã bại hoại, làm những điều ghê tởm; chẳng có ai làm điều lành.'),
(14083, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 14, 2, 'OT', 'Đức Giê-hô-va từ các từng trời ngó xuống trên con loài người, đặng xem có ai hiểu biết, ai tìm kiếm Đức Chúa Trời chăng.'),
(14084, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 14, 3, 'OT', 'Tất cả đều bội đạo, đồng loạt trở nên ô uế; chẳng ai làm điều thiện, không một người nào.'),
(14085, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 14, 4, 'OT', 'Các kẻ làm ác há chẳng hiểu biết sao? Chúng nó ăn dân ta như ăn bánh, và chẳng kêu cầu Đức Giê-hô-va.'),
(14086, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 14, 5, 'OT', 'Chúng nó kinh khiếp tại đó, vì Đức Chúa Trời ở trong dòng dõi người công bình.'),
(14087, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 14, 6, 'OT', 'Các ngươi làm bại mưu người khốn cùng, vì Đức Giê-hô-va là nơi nương náu người ấy.'),
(14088, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 14, 7, 'OT', 'Ôi! chớ chi sự cứu rỗi cho Y-sơ-ra-ên đã đến từ Si-ôn! Khi Đức Giê-hô-va đem về những phu tù của dân Ngài, Gia-cốp sẽ hớn hở, Y-sơ-ra-ên sẽ vui mừng.'),
(14089, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 15, 1, 'OT', 'Hỡi Đức Giê-hô-va, ai sẽ ngụ trong đền tạm Ngài? Ai sẽ ở trên núi thánh Ngài?'),
(14090, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 15, 2, 'OT', 'Đi đời sống thanh sạch, làm điều công bình, và nói sự thật trong lòng mình.'),
(14091, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 15, 3, 'OT', 'Không nói hành bằng lưỡi mình, không làm điều ác cho người thân cận, không mang sỉ nhục đến người gần gũi mình;'),
(14092, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 15, 4, 'OT', 'Người khinh bỉ kẻ bị khinh bỉ trong mắt mình, nhưng tôn trọng kẻ kính sợ Đức Giê-hô-va; người đã thề hứa điều ác thì không thay đổi.'),
(14093, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 15, 5, 'OT', 'Không cho vay tiền lấy lời, cũng không nhận hối lộ để hại người vô tội. Ai làm những điều đó sẽ không bao giờ rúng động.'),
(14094, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 16, 1, 'OT', 'Lạy Đức Chúa Trời, xin giữ gìn tôi, vì tôi đã nương náu nơi Ngài.'),
(14095, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 16, 2, 'OT', 'Tôi nói cùng Đức Giê-hô-va: "Ngài là Chúa tôi; ngoài Ngài, tôi chẳng có điều thiện nào khác."'),
(14096, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 16, 3, 'OT', 'Các thánh trên đất, ấy là những người cao trọng, trọn điều tôi ưa thích đều ở trong họ.'),
(14097, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 16, 4, 'OT', 'Những thần khác mà người ta vội vàng theo đuổi, thì sự đau buồn của chúng sẽ càng gia tăng; tôi sẽ không rót của lễ quán bằng huyết chúng nó, cũng không để danh chúng nó ra khỏi môi tôi.'),
(14098, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 16, 5, 'OT', 'Đức Giê-hô-va là phần sản nghiệp và là chén của tôi; chính Ngài giữ chắc phần tôi.'),
(14099, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 16, 6, 'OT', 'Các dây đo đã rơi cho tôi trong những nơi tốt lành; phải, cơ nghiệp tôi thật đẹp đẽ.'),
(14100, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 16, 7, 'OT', 'Tôi sẽ ngợi khen Đức Giê-hô-va, là Đấng đã ban cho tôi sự chỉ dạy; ngay cả ban đêm, các thận tôi cũng nhắc nhở tôi.'),
(14101, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 16, 8, 'OT', 'Tôi hằng đặt Đức Giê-hô-va ở trước mặt tôi; vì Ngài ở bên phải tôi, tôi sẽ không bị rung chuyển.'),
(14102, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 16, 9, 'OT', 'Vì vậy, lòng tôi mừng rỡ, và vinh hiển tôi nhảy mừng; ngay cả thân thể tôi cũng sẽ ở yên trong sự an toàn;'),
(14103, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 16, 10, 'OT', 'Vì Ngài sẽ không để linh hồn tôi bị bỏ trong âm phủ, cũng không để người thánh của Ngài thấy sự hư nát.'),
(14104, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 16, 11, 'OT', 'Chúa sẽ chỉ cho tôi biết con đường sự sống; đầy sự vui mừng trước mặt Chúa, nơi tay phải Ngài là điều tốt lành đời đời.'),
(14105, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 17, 1, 'OT', 'Lạy Đức Giê-hô-va, xin hãy nghe điều công bình, xin hãy lắng nghe tiếng tôi kêu; xin hãy lắng tai nghe lời cầu nguyện tôi, ra từ môi không gian dối.'),
(14106, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 17, 2, 'OT', 'Quyền xét đoán tôi sẽ ra từ trước mặt Ngài; mắt Ngài sẽ nhìn xem điều ngay thẳng.'),
(14107, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 17, 3, 'OT', 'Ngài đã thử lòng tôi, thăm viếng tôi ban đêm; Ngài đã luyện tôi, chẳng tìm thấy điều gì gian ác; ý định tôi, miệng tôi không vượt quá giới hạn.'),
(14108, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 17, 4, 'OT', 'Về hành động của loài người, nhờ lời nơi môi miệng Ngài, tôi giữ mình khỏi các lối đi của kẻ bạo lực.'),
(14109, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 17, 5, 'OT', 'Các bước chân tôi, Ngài giữ vững trong các lối Ngài; chân tôi không hề lay động.'),
(14110, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 17, 6, 'OT', 'Lạy Đức Giê-hô-va, tôi kêu cầu Ngài, vì Ngài sẽ nhậm lời tôi: xin nghiêng tai Ngài về phía tôi, nghe lời tôi nói.'),
(14111, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 17, 7, 'OT', 'Xin hãy tỏ ra sự nhân từ lạ lùng của Ngài, Ngài dùng tay hữu cứu kẻ nương náu mình nơi Ngài khỏi những kẻ dấy lên nghịch cùng họ.'),
(14112, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 17, 8, 'OT', 'Hãy giữ gìn tôi như con ngươi của mắt; dưới bóng các cánh Ngài, xin che khuất tôi.'),
(14113, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 17, 9, 'OT', 'Xin bảo vệ tôi khỏi những kẻ ác đang ức hiếp tôi, khỏi kẻ thù nghịch lấy mạng sống tôi mà vây hãm tôi.'),
(14114, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 17, 10, 'OT', 'Lòng chúng nó đã bị bít lại; miệng chúng nó nói cách kiêu căng.'),
(14115, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 17, 11, 'OT', 'Bước chân chúng nó nay vây quanh tôi; mắt chúng nó đặt để nghiêng ngả trên đất.'),
(14116, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 17, 12, 'OT', 'Hình dạng nó như sư tử thèm nuốt mồi, như sư tử con nằm phục trong chỗ ẩn khuất.'),
(14117, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 17, 13, 'OT', 'Hỡi Đức Giê-hô-va, xin hãy chỗi dậy, ngăn chặn và khuất phục nó; xin giải cứu linh hồn tôi khỏi kẻ ác bằng gươm Ngài.'),
(14118, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 17, 14, 'OT', 'Hỡi Đức Giê-hô-va, xin lấy tay Ngài cứu tôi khỏi những kẻ chết, khỏi những kẻ chết đời này, phần của chúng nó là trong cõi sống; Ngài làm đầy bụng chúng nó bằng của cải Ngài, chúng nó được no đủ và để lại phần còn lại cho con cái mình.'),
(14119, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 17, 15, 'OT', 'Còn tôi, tôi sẽ được thấy mặt Ngài trong sự công bình; khi tôi tỉnh thức, tôi sẽ được no đủ bởi hình dạng Ngài.'),
(14120, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 1, 'OT', 'Đức Giê-hô-va là sức lực tôi; tôi yêu mến Ngài.'),
(14121, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 2, 'OT', 'Đức Giê-hô-va là hòn đá tôi, đồn lũy tôi, Đấng giải cứu tôi; Đức Chúa Trời là hòn đá tôi, nơi tôi nương náu; Ngài là cái khiên tôi, sừng cứu rỗi tôi, nơi náu ẩn cao của tôi.'),
(14122, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 3, 'OT', 'Tôi sẽ ngợi khen Đức Giê-hô-va, và kêu cầu Ngài, thì được cứu khỏi các kẻ thù tôi.'),
(14123, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 4, 'OT', 'Các dây sự chết xiết chặt tôi, các dòng nước gian ác tràn vào vây hãm tôi.'),
(14124, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 5, 'OT', 'Những dây âm phủ bao quanh tôi; các bẫy của sự chết đến gần tôi.'),
(14125, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 6, 'OT', 'Trong cơn gian truân, tôi kêu cầu Đức Giê-hô-va, và hướng về Đức Chúa Trời tôi mà kêu cứu; Ngài đã nghe tiếng tôi từ đền thánh Ngài, và tiếng kêu cứu của tôi đã thấu đến tai Ngài.'),
(14126, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 7, 'OT', 'Đất liền rung chuyển và lay động, các nền của núi cũng rúng rợn và chao đảo, vì cơn thịnh nộ của Ngài nổi lên.'),
(14127, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 8, 'OT', 'Khói bốc lên từ cơn thịnh nộ của Ngài, và lửa từ miệng Ngài nuốt vào; những than hồng cháy bừng từ nơi Ngài.'),
(14128, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 9, 'OT', 'Người làm nghiêng các từng trời và ngự xuống; dưới chân Ngài là vực tối tăm.'),
(14129, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 10, 'OT', 'Ngài cỡi trên chê-ru-bin và bay lên, Ngài lướt trên cánh gió.'),
(14130, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 11, 'OT', 'Đặt sự tối tăm làm nơi ẩn náu mình, các đám mây, sự tối đen của các tầng trời, bao quanh Ngài như lều trại.'),
(14131, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 12, 'OT', 'Từ nơi sáng chói trước mặt Ngài, các đám mây của Ngài trôi qua; mưa đá và những cục than rực lửa.'),
(14132, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 13, 'OT', 'Đức Giê-hô-va sấm sét trên các từng trời, Đấng Chí cao phát ra tiếng Ngài, mưa đá và than hồng lửa bắn ra.'),
(14133, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 14, 'OT', 'Đức Giê-hô-va bắn ra các mũi tên của Ngài, khiến chúng nó tản lạc; Ngài phóng nhiều tia chớp, khiến chúng nó rối loạn.'),
(14134, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 15, 'OT', 'Hỡi Đức Giê-hô-va, các khe nước hiện ra, các nền của đất lộ ra bởi sự quở trách Ngài, bởi hơi thở từ lỗ mũi Ngài.'),
(14135, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 16, 'OT', 'Từ nơi cao Ngài giơ tay ra bắt lấy tôi, kéo tôi ra khỏi những dòng nước lớn.'),
(14136, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 17, 'OT', 'Ngài giải cứu tôi khỏi kẻ thù mạnh mẽ, và khỏi những kẻ ghét tôi, vì chúng mạnh hơn tôi.'),
(14137, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 18, 'OT', 'Trong ngày tai họa chúng nó xông vào tôi; nhưng Đức Giê-hô-va phù hộ tôi.'),
(14138, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 19, 'OT', 'Ngài đưa tôi ra chỗ rộng rãi, giải cứu tôi, vì Ngài thương tôi.'),
(14139, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 20, 'OT', 'Đức Giê-hô-va đối xử với tôi tùy theo sự công bình tôi, theo sự trong sạch của tay tôi, Ngài đền đáp tôi.'),
(14140, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 21, 'OT', 'Vì tôi đã giữ các đường lối của Đức Giê-hô-va, và không phạm tội ác ra khỏi Đức Chúa Trời tôi.'),
(14141, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 22, 'OT', 'Vì mọi phán quyết của Đức Giê-hô-va đều ở trước mặt tôi, và các luật lệ của Ngài, tôi không hề lìa bỏ.'),
(14142, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 23, 'OT', 'Tôi cũng trọn vẹn cùng Ngài, và giữ mình tôi khỏi tội lỗi.'),
(14143, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 24, 'OT', 'Vì vậy, Đức Giê-hô-va đã trả tôi tùy theo sự công bình tôi, và thưởng tôi tùy theo sự thanh sạch của tay tôi trước mặt Ngài.'),
(14144, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 25, 'OT', 'Với kẻ nhân từ, Ngài sẽ nhân từ; với kẻ toàn vẹn, Ngài sẽ toàn vẹn.'),
(14145, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 26, 'OT', 'Đối cùng kẻ thanh sạch, Ngài sẽ tỏ mình thanh sạch; đối cùng kẻ quanh co, Ngài sẽ tỏ mình quanh co.'),
(14146, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 27, 'OT', 'Vì chính Ngài cứu dân khiêm nhường; còn mắt kiêu ngạo, Ngài sẽ hạ xuống.'),
(14147, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 28, 'OT', 'Vì chính Ngài thắp sáng ngọn đèn tôi; Đức Giê-hô-va Đức Chúa Trời tôi soi sáng nơi tối tăm tôi.'),
(14148, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 29, 'OT', 'Nhờ Ngài tôi đánh tan đoàn quân, nhờ Đức Chúa Trời tôi, tôi nhảy qua lũy thành.'),
(14149, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 30, 'OT', 'Còn Đức Chúa Trời, đường lối Ngài trọn vẹn; lời của Đức Giê-hô-va đã được luyện sạch; Ngài là cái khiên cho mọi kẻ nương náu nơi Ngài.'),
(14150, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 31, 'OT', 'Trừ ra Đức Giê-hô-va, ai là Đức Chúa Trời? Ngoài Đức Chúa Trời chúng tôi, ai là hòn đá?'),
(14151, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 32, 'OT', 'Đức Chúa Trời làm tôi vững mạnh về sức lực, và làm cho đường lối tôi được vững chắc.'),
(14152, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 33, 'OT', 'Đức Giê-hô-va khiến chân tôi như chân các con nai cái, và trên các nơi cao của tôi, Ngài đặt tôi đứng vững.'),
(14153, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 34, 'OT', 'Dạy tay tôi chiến đấu, khiến cho đôi cánh tay tôi giương được cung bằng đồng.'),
(14154, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 35, 'OT', 'Ngài ban cho tôi cái khiên của sự cứu rỗi Ngài; tay phải Ngài nâng đỡ tôi; sự khiêm nhường của Ngài làm tôi nên lớn mạnh.'),
(14155, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 36, 'OT', 'Ngài làm rộng bước đi dưới chân tôi, và chân tôi không trượt ngã.'),
(14156, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 37, 'OT', 'Tôi rượt đuổi các kẻ thù nghịch tôi và bắt kịp chúng; tôi không trở lại cho đến khi chúng bị tiêu diệt.'),
(14157, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 38, 'OT', 'Tôi đánh tan chúng, đến nỗi chúng không thể đứng dậy; chúng ngã gục dưới chân tôi.'),
(14158, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 39, 'OT', 'Ngài đã lấy sức mạnh thắt lưng cho tôi để chiến đấu, khiến kẻ dấy lên nghịch cùng tôi phải bị khuất phục dưới chân tôi.'),
(14159, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 40, 'OT', 'Còn những kẻ thù nghịch ta, Ngài đã khiến chúng xây lưng chạy trốn; còn những kẻ ghét ta, ta đã tiêu diệt chúng.'),
(14160, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 41, 'OT', 'Chúng kêu cứu, nhưng không ai giải cứu; chúng kêu cầu Đức Giê-hô-va, nhưng Ngài không đáp lời.'),
(14161, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 42, 'OT', 'Tôi nghiền nát chúng như bụi trước mặt gió, tôi hất chúng đi như bùn ngoài đường.'),
(14162, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 43, 'OT', 'Ngài đã giải cứu tôi khỏi những xung đột của dân, đặt tôi làm đầu các nước; một dân mà tôi không biết sẽ phục vụ tôi.'),
(14163, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 44, 'OT', 'Ngay khi nghe tiếng nói, các dân tộc ngoại bang phải phục dưới quyền tôi.'),
(14164, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 45, 'OT', 'Các con cháu người ngoại sẽ hao mòn, và run rẩy từ các nơi ẩn náu của chúng.'),
(14165, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 46, 'OT', 'Đức Giê-hô-va hằng sống, đáng ngợi khen hòn đá tôi! Đức Chúa Trời về sự cứu rỗi tôi được tôn cao!'),
(14166, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 47, 'OT', 'Đức Chúa Trời là Đấng ban cho tôi sự báo oán, khiến các dân phục dưới tôi.'),
(14167, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 48, 'OT', 'Ngài giải cứu tôi khỏi kẻ thù tôi, thật Ngài làm tôi vượt cao hơn những kẻ dấy lên nghịch tôi; và cứu tôi khỏi người hung bạo.'),
(14168, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 49, 'OT', 'Vì vậy, tôi sẽ cảm tạ Ngài giữa các dân, hỡi Đức Giê-hô-va, và hát xướng danh Ngài.'),
(14169, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 18, 50, 'OT', 'Đức Giê-hô-va ban cho vua Ngài sự cứu rỗi lớn lao, và làm ơn cho Đấng chịu xức dầu của Ngài, tức là cho Đa-vít và cho dòng dõi người đến đời đời.'),
(14170, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 19, 1, 'OT', 'Các từng trời rao truyền sự vinh hiển của Đức Chúa Trời, và bầu trời truyền giảng công việc của tay Ngài.'),
(14171, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 19, 2, 'OT', 'Ngày nầy truyền thông cho ngày kia, đêm nầy bày tỏ sự hiểu biết cho đêm kia.'),
(14172, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 19, 3, 'OT', 'Không có lời nói, không có câu từ, cũng không nghe thấy âm thanh của chúng.'),
(14173, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 19, 4, 'OT', 'Trong khắp đất, âm thanh của chúng ra đi; và lời nói của chúng truyền đến tận cùng thế gian. Ngài đã đặt nơi ở cho mặt trời trong chúng.'),
(14174, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 19, 5, 'OT', 'Khác nào tân lang ra khỏi buồng cưới, nó vui mừng như chiến sĩ hùng dũng chạy đường dài.'),
(14175, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 19, 6, 'OT', 'Từ đầu trời nầy ra đi, và vòng chạy của nó đến tận đầu trời kia; chẳng có chi ẩn giấu khỏi sức nóng của nó.'),
(14176, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 19, 7, 'OT', 'Luật pháp của Đức Giê-hô-va là trọn vẹn, làm cho linh hồn sống lại; sự chứng cớ của Đức Giê-hô-va là vững chắc, làm cho người đơn sơ trở nên khôn ngoan.'),
(14177, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 19, 8, 'OT', 'Các mệnh lệnh của Đức Giê-hô-va là ngay thẳng, làm cho lòng vui vẻ; điều răn của Đức Giê-hô-va là trong sạch, làm sáng mắt.'),
(14178, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 19, 9, 'OT', 'Sự kính sợ Đức Giê-hô-va là thánh khiết, tồn tại đến muôn đời; các phán quyết của Đức Giê-hô-va là chân thật, đều công bình cả.'),
(14179, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 19, 10, 'OT', 'Còn ưa chuộng hơn vàng và vàng ròng rất nhiều, lại ngọt ngào hơn mật ong và mật chảy ra từ tổ ong.'),
(14180, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 19, 11, 'OT', 'Cả tôi tớ Ngài cũng được cảnh tỉnh bởi những điều đó; ai giữ được chúng thì nhận được phần thưởng lớn.'),
(14181, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 19, 12, 'OT', 'Lỗi lầm nào ai hiểu được? Xin Đức Giê-hô-va thanh sạch tôi khỏi những điều khuất tất.'),
(14182, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 19, 13, 'OT', 'Xin Đức Giê-hô-va giữ kẻ tôi tớ Ngài khỏi những tội cố ý; nguyện những tội ấy không cai trị tôi. Bấy giờ tôi sẽ không chỗ trách được, và sẽ được sạch khỏi tội lớn.'),
(14183, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 19, 14, 'OT', 'Nguyện lời nói của miệng tôi và sự suy gẫm trong lòng tôi được đẹp ý trước mặt Ngài, Đức Giê-hô-va là hòn đá tôi và là Đấng cứu chuộc tôi.'),
(14184, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 20, 1, 'OT', 'Nguyện Đức Giê-hô-va đáp lời ngươi trong ngày hoạn nạn; nguyện danh Đức Chúa Trời của Gia-cốp phù trì ngươi,'),
(14185, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 20, 2, 'OT', 'Người sẽ sai sự giúp đỡ ngươi từ nơi thánh, và từ Si-ôn nâng đỡ ngươi!'),
(14186, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 20, 3, 'OT', 'Nguyện Đức Giê-hô-va nhớ đến mọi lễ vật chay của ngươi, và lễ toàn thiêu của ngươi Ngài khiến cho béo mẫm!'),
(14187, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 20, 4, 'OT', 'Ngài sẽ ban cho ngươi điều lòng ngươi mong ước, và làm trọn mọi mưu toan của ngươi.'),
(14188, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 20, 5, 'OT', 'Chúng tôi sẽ reo mừng vì sự cứu giúp của Ngài; nhân danh Đức Chúa Trời chúng tôi mà phất cờ chiến thắng. Nguyện Đức Giê-hô-va làm trọn mọi điều Ngài cầu xin.'),
(14189, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 20, 6, 'OT', 'Bây giờ tôi biết rằng Đức Giê-hô-va đã cứu Đấng chịu xức dầu của Ngài; Ngài sẽ đáp người từ các từng trời thánh, bằng quyền năng cứu rỗi của tay phải Ngài.'),
(14190, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 20, 7, 'OT', 'Có kẻ nhờ cậy xe, có kẻ nhờ cậy ngựa, còn chúng tôi nhờ cậy danh Đức Giê-hô-va, là Đức Chúa Trời chúng tôi.'),
(14191, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 20, 8, 'OT', 'Chúng nó khuỵu xuống và ngã, còn chúng tôi chỗi dậy và đứng vững.'),
(14192, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 20, 9, 'OT', 'Hỡi Đức Giê-hô-va, xin hãy cứu! Nguyện Vua đáp lời chúng tôi trong ngày chúng tôi kêu cầu.'),
(14193, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 21, 1, 'OT', 'Hỡi Đức Giê-hô-va, nhân sức mạnh của Ngài, vua sẽ vui mừng; nơi sự cứu rỗi của Ngài, người sẽ rất vui sướng.'),
(14194, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 21, 2, 'OT', 'Người ước ao trong lòng, Ngài đã ban cho; điều môi miệng người khẩn cầu, Ngài không từ chối.'),
(14195, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 21, 3, 'OT', 'Vì Ngài lấy các phước lành mà đón rước người, đặt trên đầu người mão triều bằng vàng ròng.'),
(14196, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 21, 4, 'OT', 'Người đã cầu xin Đức Giê-hô-va sự sống, Ngài đã ban cho Người; một đời sống lâu dài đời đời vô cùng.'),
(14197, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 21, 5, 'OT', 'Sự vinh hiển của người thật lớn nhờ sự cứu rỗi do Ngài thực hiện; Ngài lấy sự tôn nghiêm và oai nghi mà đội cho người.'),
(14198, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 21, 6, 'OT', 'Vì Ngài đặt người làm phúc đến muôn đời, khiến người đầy vẻ vui mừng trước mặt Ngài.'),
(14199, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 21, 7, 'OT', 'Vì vua tin cậy nơi Đức Giê-hô-va, và nhờ sự nhân từ của Đấng Chí Cao, người sẽ không bị lay động.'),
(14200, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 21, 8, 'OT', 'Tay của Ngài sẽ tìm được mọi kẻ thù nghịch Ngài; tay phải của Ngài sẽ tìm được những kẻ ghét Ngài.'),
(14201, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 21, 9, 'OT', 'Ngài sẽ đặt chúng nó như cái lò lửa hừng khi Ngài hiện ra; Đức Giê-hô-va sẽ nuốt chúng nó trong cơn thạnh nộ của Ngài, và lửa sẽ thiêu đốt chúng nó.'),
(14202, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 21, 10, 'OT', 'Con cháu của chúng nó, Chúa sẽ tiêu diệt khỏi đất, và dòng dõi chúng nó khỏi giữa con cái loài người.'),
(14203, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 21, 11, 'OT', 'Vì chúng nó đã toan rủi ro cho Ngài, Sáng mưu kế mà chúng nó không thể thực hiện được.'),
(14204, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 21, 12, 'OT', 'Ngài sẽ khiến chúng nó xây lưng, Ngài sẽ sửa cây cung của Ngài, nhắm mặt chúng nó.'),
(14205, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 21, 13, 'OT', 'Hỡi Đức Giê-hô-va, nguyện Ngài được tôn cao trong quyền năng Ngài! Chúng tôi sẽ ca hát và đàn hát về sức mạnh của Ngài.'),
(14206, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 22, 1, 'OT', 'Đức Chúa Trời tôi ôi! Đức Chúa Trời tôi ôi! sao Ngài lìa bỏ tôi? Xa cách sự cứu rỗi tôi, lời kêu khóc tôi.'),
(14207, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 22, 2, 'OT', 'Đức Chúa Trời tôi ôi, tôi kêu cầu ban ngày mà Ngài chẳng đáp lại; tôi kêu cầu ban đêm mà cũng chẳng được yên lặng nào cho tôi'),
(14208, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 22, 3, 'OT', 'Nhưng Ngài là Đấng Thánh, Đấng ngự giữa những lời ca ngợi của Y-sơ-ra-ên.'),
(14209, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 22, 4, 'OT', 'Tổ tiên chúng tôi đã tin cậy nơi Ngài; họ tin cậy và Ngài đã giải cứu họ.'),
(14210, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 22, 5, 'OT', 'Họ kêu cứu cùng Đức Giê-hô-va và được giải cứu; họ tin cậy nơi Ngài và không bị hổ thẹn.'),
(14211, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 22, 6, 'OT', 'Nhưng tôi là một con sâu, chứ không phải người, là sự sỉ nhục của loài người, và bị dân sự khinh bỉ.'),
(14212, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 22, 7, 'OT', 'Hết thảy những kẻ thấy tôi đều nhạo báng tôi; chúng nói bằng môi miệng, lay đầu mà chế giễu.'),
(14213, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 22, 8, 'OT', 'Hãy phó thác mình cho Đức Giê-hô-va, Ngài sẽ giải cứu nó; Ngài sẽ cứu nó khỏi nguy khốn, vì Ngài yêu thích nó.'),
(14214, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 22, 9, 'OT', 'Chính Ngài đã rút tôi khỏi lòng mẹ, khiến tôi tin cậy ngay từ khi nằm trên vú mẹ tôi.'),
(14215, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 22, 10, 'OT', 'Từ khi còn trong lòng mẹ, tôi đã được trao phó cho Đức Giê-hô-va; từ lúc mới lọt lòng, Đức Chúa Trời đã là Đấng tôi nương tựa.'),
(14216, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 22, 11, 'OT', 'Xin chớ cách xa tôi, vì tai họa đã gần, chẳng có ai giúp đỡ.'),
(14217, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 22, 12, 'OT', 'Nhiều bò đực vây quanh tôi; những con bò hùng mạnh của Ba-san bao phủ tôi.'),
(14218, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 22, 13, 'OT', 'Chúng há miệng ra nghịch cùng tôi, sư tử gầm thét và xé nát.'),
(14219, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 22, 14, 'OT', 'Tôi bị đổ ra như nước, các xương tôi đều rời rã; lòng tôi như sáp, tan chảy trong lòng tôi.'),
(14220, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 22, 15, 'OT', 'Sức lực tôi khô héo như đất sét, lưỡi tôi dính vào hàm; Ngài đặt tôi trong bụi đất của sự chết.'),
(14221, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 22, 16, 'OT', 'Vì những chó đã bao vây tôi; một đám ác nhân vây quanh tôi; chúng đã xiết chặt tay tôi và chân tôi như sư tử.'),
(14222, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 22, 17, 'OT', 'Tôi đếm được mọi xương tôi; chúng nhìn xem, chăm chú nhìn tôi.'),
(14223, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 22, 18, 'OT', 'Chúng chia nhau áo xống tôi, và bắt thăm về quần áo tôi.'),
(14224, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 22, 19, 'OT', 'Lạy Đức Giê-hô-va, xin chớ xa con; hỡi sức mạnh cứu giúp con, xin mau đến giúp đỡ con.'),
(14225, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 22, 20, 'OT', 'Xin cứu lấy linh hồn tôi khỏi lưỡi gươm, mạng sống tôi khỏi nanh vuốt loài chó.'),
(14226, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 22, 21, 'OT', 'Cứu tôi khỏi miệng sư tử, và khỏi các sừng của trâu rừng, Ngài đã nhậm lời tôi.'),
(14227, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 22, 22, 'OT', 'Tôi sẽ loan truyền danh Ngài cho các anh em tôi, và ngợi khen Ngài giữa vòng hội chúng.'),
(14228, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 22, 23, 'OT', 'Hỡi những kẻ kính sợ Đức Giê-hô-va, hãy ngợi khen Ngài; hỡi cả dòng dõi Gia-cốp, hãy tôn vinh Ngài; và hỡi cả dòng dõi Y-sơ-ra-ên, hãy kính sợ Ngài;'),
(14229, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 22, 24, 'OT', 'Vì Ngài không khinh bỉ, chẳng gớm ghiếc sự khốn khổ của người khiêm nhường, cũng không giấu mặt Ngài khỏi người ấy; mà khi người kêu cứu Ngài, thì Ngài lắng nghe.'),
(14230, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 22, 25, 'OT', 'Từ nơi Ngài, lời ngợi khen của tôi được bày ra trong hội đông; tôi sẽ trả trọn các lời hứa nguyện mình trước mặt những kẻ kính sợ Ngài.'),
(14231, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 22, 26, 'OT', 'Kẻ hiền từ sẽ ăn và được no; những người tìm Đức Giê-hô-va sẽ ngợi khen Ngài; nguyện lòng các ngươi được sống mãi mãi.'),
(14232, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 22, 27, 'OT', 'Bốn phương đất sẽ nhớ lại và trở về cùng Đức Giê-hô-va; mọi dòng dõi các dân tộc sẽ thờ lạy trước mặt Ngài.'),
(14233, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 22, 28, 'OT', 'Vì nước thuộc về Đức Giê-hô-va, và Ngài cai trị trên các nước.'),
(14234, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 22, 29, 'OT', 'Tất cả những người béo tốt trên đất sẽ ăn và thờ lạy; trước mặt Ngài, mọi kẻ xuống bụi đất sẽ quỳ gối; còn chính người ấy thì không được sống lại.'),
(14235, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 22, 30, 'OT', 'Một dòng dõi sẽ hầu việc Ngài; người ta sẽ thuật về Chúa cho thế hệ này.'),
(14236, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 22, 31, 'OT', 'Sẽ có người đến loan truyền sự công bình của Ngài cho một dòng dõi sẽ sinh ra, rằng Đức Giê-hô-va đã làm điều nầy.'),
(14237, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 23, 1, 'OT', 'Đức Giê-hô-va là Đấng chăn giữ tôi; tôi sẽ không thiếu thốn điều gì.'),
(14238, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 23, 2, 'OT', 'Ngài cho tôi nằm nghỉ nơi đồng cỏ xanh tươi; dẫn tôi dọc theo những dòng nước yên lặng.'),
(14239, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 23, 3, 'OT', 'Linh hồn tôi, Ngài làm cho sống lại; Ngài dẫn tôi trên các nẻo công bình, vì danh Ngài.'),
(14240, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 23, 4, 'OT', 'Dù khi tôi đi trong trũng bóng tối của cái chết, tôi sẽ không sợ điều ác nào, vì Đức Giê-hô-va ở cùng tôi; cây trượng và cây gậy của Ngài an ủi tôi.'),
(14241, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 23, 5, 'OT', 'Ngài bày biện cho tôi một bàn tiệc trước mặt những kẻ thù nghịch tôi; đầu tôi, Ngài xức bằng dầu; chén tôi đầy tràn.'),
(14242, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 23, 6, 'OT', 'Chỉ điều thiện và sự thương xót sẽ theo tôi mọi ngày trong đời sống; tôi sẽ ở trong nhà Đức Giê-hô-va cho đến trọn đời.'),
(14243, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 24, 1, 'OT', 'Đất và muôn vật trên đất, thế gian và những kẻ ở trong đó, đều thuộc về Đức Giê-hô-va.'),
(14244, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 24, 2, 'OT', 'Vì chính Ngài đã đặt nền tảng của nó trên các biển, và thiết lập nó vững chắc trên các sông nước.'),
(14245, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 24, 3, 'OT', 'Ai sẽ được lên núi Đức Giê-hô-va, và ai sẽ được đứng nơi chốn thánh của Ngài?'),
(14246, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 24, 4, 'OT', 'Là người tay sạch và lòng thanh khiết, chẳng để linh hồn mình hướng về điều hư không, cũng không thề nguyện giả dối.'),
(14247, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 24, 5, 'OT', 'Người ấy sẽ nhận được phước lành từ nơi Đức Giê-hô-va, và sự công bình từ nơi Đức Chúa Trời về sự cứu rỗi người.'),
(14248, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 24, 6, 'OT', 'Đây là dòng dõi của những người tìm kiếm, là kẻ cầu mong được thấy mặt Đức Giê-hô-va, hỡi Gia-cốp.'),
(14249, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 24, 7, 'OT', 'Hỡi các cửa, hãy cất đầu lên! Hỡi các cửa đời đời, hãy mở cao lên, để Vua vinh hiển vào.'),
(14250, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 24, 8, 'OT', 'Vua vinh hiển ấy là ai? Ấy là Đức Giê-hô-va, Đấng quyền lực và dũng cảm, Đức Giê-hô-va hùng mạnh trong chiến trận.'),
(14251, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 24, 9, 'OT', 'Hỡi các cửa, hãy cất đầu lên! Hỡi các cửa đời đời, hãy mở cao lên, để Vua Vinh-Hiển bước vào.'),
(14252, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 24, 10, 'OT', 'Vua vinh hiển ấy là ai? Ấy là Đức Giê-hô-va vạn quân, Ngài là Vua vinh hiển. Sê-la.'),
(14253, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 25, 1, 'OT', 'Đức Giê-hô-va, linh hồn tôi hướng về Ngài.'),
(14254, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 25, 2, 'OT', 'Lạy Đức Chúa Trời, tôi tin cậy nơi Ngài; xin đừng để tôi bị hổ thẹy, cũng đừng để kẻ thù tôi được vui mừng vì tôi.'),
(14255, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 25, 3, 'OT', 'Tất cả những người nào trông cậy Ngài sẽ chẳng bị hổ thẹy; còn những kẻ bất trung vô cớ sẽ phải hổ thẹy.'),
(14256, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 25, 4, 'OT', 'Hỡi Đức Giê-hô-va, xin chỉ cho tôi biết các đường lối Ngài, dạy tôi các lối đi của Ngài.'),
(14257, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 25, 5, 'OT', 'Xin hãy dẫn dắt tôi trong sự thật của Đức Giê-hô-va và dạy tôi, vì Đức Giê-hô-va là Đức Chúa Trời về sự cứu rỗi tôi; suốt cả ngày tôi trông đợi Ngài.'),
(14258, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 25, 6, 'OT', 'Lạy Đức Giê-hô-va, xin nhớ lại các sự thương xót và các sự nhân từ của Ngài, vì các điều ấy vốn có từ xưa.'),
(14259, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 25, 7, 'OT', 'Xin đừng nhớ các tội lỗi thời trẻ tôi và các sự phạm tội tôi; hỡi Đức Giê-hô-va, xin nhớ đến tôi tùy theo sự nhân từ của Ngài, vì cớ sự tốt lành của Ngài.'),
(14260, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 25, 8, 'OT', 'Đức Giê-hô-va tốt lành và ngay thẳng; vì vậy Ngài dạy kẻ phạm tội về con đường.'),
(14261, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 25, 9, 'OT', 'Ngài sẽ hướng dẫn kẻ khiêm nhường theo lẽ công bình, Và dạy đường lối Ngài cho những người nhu mì.'),
(14262, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 25, 10, 'OT', 'Mọi nẻo đường của Đức Giê-hô-va đều là nhân từ và chân thật, dành cho những ai giữ giao ước và chứng cớ của Ngài.'),
(14263, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 25, 11, 'OT', 'Nhân danh Đức Giê-hô-va, xin tha cho tội lỗi tôi, vì tội ấy rất nhiều.'),
(14264, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 25, 12, 'OT', 'Ai là người kính sợ Đức Giê-hô-va? Ngài sẽ dạy người ấy con đường người ấy sẽ chọn.'),
(14265, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 25, 13, 'OT', 'Linh hồn người sẽ sống trong thịnh vượng, và dòng dõi người sẽ thừa hưởng đất đai.'),
(14266, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 25, 14, 'OT', 'Sự thân mật của Đức Giê-hô-va dành cho những người kính sợ Ngài, và giao ước Ngài để tỏ cho họ biết.'),
(14267, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 25, 15, 'OT', 'Mắt tôi luôn chăm chăm nhìn xem Đức Giê-hô-va; Vì chính Ngài sẽ rút chân tôi ra khỏi lưới.'),
(14268, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 25, 16, 'OT', 'Xin Đức Giê-hô-va đoái nhìn tôi và thương xót tôi, vì tôi cô độc và khốn cùng.'),
(14269, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 25, 17, 'OT', 'Cơn gian truân trong lòng tôi đã gia tăng; xin hãy đưa tôi ra khỏi những nỗi khốn khổ tôi gặp phải.'),
(14270, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 25, 18, 'OT', 'Hãy xem sự khốn khổ và nỗi cực nhọc của tôi, và tha thứ mọi tội lỗi tôi.'),
(14271, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 25, 19, 'OT', 'Hãy xem kẻ thù tôi, vì chúng đông; và lòng ghét hận bạo lực ghét tôi.'),
(14272, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 25, 20, 'OT', 'Xin hãy giữ linh hồn tôi và giải cứu tôi; chớ để tôi phải hổ thẹy, vì tôi đã tin cậy nơi Ngài.'),
(14273, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 25, 21, 'OT', 'Sự ngay thẳng và ngay lành sẽ gìn giữ tôi, vì tôi trông đợi Đức Giê-hô-va.'),
(14274, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 25, 22, 'OT', 'Cứu chuộc, Đức Chúa Trời ôi, Y-sơ-ra-ên khỏi mọi sự gian truồng của người.'),
(14275, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 26, 1, 'OT', 'Hỡi Đức Giê-hô-va, xin đoán xét tôi, vì tôi đã bước đi trong sự ngay thẳng của tôi, và tôi tin cậy nơi Đức Giê-hô-va, tôi sẽ không lay động.'),
(14276, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 26, 2, 'OT', 'Lạy Đức Giê-hô-va, xin hãy dò xét tôi và thử thách tôi, rèn luyện lòng tôi và lòng dạ tôi.'),
(14277, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 26, 3, 'OT', 'Vì sự nhân từ của Đức Giê-hô-va ở trước mặt tôi, tôi đã bước đi trong lẽ thật của Ngài.'),
(14278, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 26, 4, 'OT', 'Tôi không ngồi cùng những kẻ hư không, cũng không vào cùng những kẻ mưu mô.'),
(14279, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 26, 5, 'OT', 'Tôi ghét hội những kẻ làm ác, và chẳng ngồi chung với bọn gian ác.'),
(14280, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 26, 6, 'OT', 'Lạy Đức Giê-hô-va, tôi sẽ rửa tay trong sự thanh khiết, rồi đi vòng quanh bàn thờ của Ngài,'),
(14281, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 26, 7, 'OT', 'để nghe tiếng cảm tạ, và thuật lại mọi việc làm kỳ diệu của Đức Giê-hô-va'),
(14282, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 26, 8, 'OT', 'Hỡi Đức Giê-hô-va, tôi yêu nơi ở của nhà Ngài, và chỗ đặt đền tạm sự vinh hiển Ngài.'),
(14283, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 26, 9, 'OT', 'Đừng nhóm linh hồn tôi cùng với kẻ tội lỗi, và mạng sống tôi cùng với những người đổ máu;'),
(14284, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 26, 10, 'OT', 'Những kẻ tay chúng đầy mưu gian ác, và tay phải đầy hối lộ.'),
(14285, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 26, 11, 'OT', 'Còn tôi, tôi sẽ đi trong sự ngay thẳng của tôi; xin hãy chuộc tôi và thương xót tôi.'),
(14286, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 26, 12, 'OT', 'Chân tôi đứng trên đường ngay thẳng; trong các hội chúng tôi sẽ ngợi khen Đức Giê-hô-va.'),
(14287, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 27, 1, 'OT', 'Đức Giê-hô-va là ánh sáng tôi và là sự cứu rỗi tôi; tôi sẽ sợ ai? Đức Giê-hô-va là đồn lũy của đời tôi; tôi sẽ khiếp ai?'),
(14288, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 27, 2, 'OT', 'Khi những kẻ ác đến gần tôi để ăn thịt tôi, thì những kẻ thù nghịch và kẻ thù tôi bị vấp ngã và ngã gục.'),
(14289, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 27, 3, 'OT', 'Dầu một đạo quân đóng lại nghịch cùng tôi, lòng tôi chẳng sợ hãi; dầu giặc giã dấy lên nghịch cùng tôi, trong điều đó tôi vẫn tin cậy.'),
(14290, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 27, 4, 'OT', 'Một điều tôi xin nơi Đức Giê-hô-va, ấy là điều tôi tìm kiếm: suốt mọi ngày đời tôi được ở trong nhà Đức Giê-hô-va, để chiêm ngưỡng sự tốt lành của Đức Giê-hô-va, và tìm cầu trong đền thánh Ngài.'),
(14291, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 27, 5, 'OT', 'Vì Ngài sẽ giấu tôi trong lều Ngài trong ngày tai họa, che tôi trong nơi kín nhiệm của Ngài; trên một hòn đá, Ngài sẽ nâng tôi lên.'),
(14292, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 27, 6, 'OT', 'Và bây giờ đầu tôi sẽ được ngước cao trên các kẻ thù nghịch vây quanh tôi; tôi sẽ dâng tế lễ trong trại Ngài với tiếng reo vui; tôi sẽ hát và gảy đàn ca ngợi Đức Giê-hô-va.'),
(14293, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 27, 7, 'OT', 'Hỡi Đức Giê-hô-va, xin hãy nghe tiếng tôi kêu cầu; xin thương xót tôi và nhậm lời tôi.'),
(14294, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 27, 8, 'OT', 'Khi lòng tôi nói với tôi: "Hãy tìm kiếm mặt Đức Giê-hô-va," thì tôi sẽ tìm kiếm mặt Đức Giê-hô-va.'),
(14295, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 27, 9, 'OT', 'Xin chớ giấu mặt Ngài khỏi tôi, chớ đuổi kẻ tôi tớ Ngài trong cơn thịnh nộ; Ngài đã là sự giúp đỡ tôi, xin chớ lìa tôi, chớ bỏ tôi, hỡi Đức Chúa Trời về sự cứu rỗi tôi.'),
(14296, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 27, 10, 'OT', 'Dù cha tôi và mẹ tôi lìa bỏ tôi, thì Đức Giê-hô-va sẽ tiếp rước tôi.'),
(14297, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 27, 11, 'OT', 'Hỡi Đức Giê-hô-va, xin chỉ dạy tôi con đường Ngài, và dẫn tôi trên lối ngay thẳng, vì cớ những kẻ rình rập tôi.'),
(14298, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 27, 12, 'OT', 'Xin Đừng phó tôi vào tay kẻ hà hiếp tôi; vì những kẻ làm chứng dối và kẻ buông ra sự hung bạo đã dấy nghịch cùng tôi.'),
(14299, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 27, 13, 'OT', 'Nếu tôi không tin chắc mình sẽ thấy sự tốt lành của Đức Giê-hô-va tại đất người sống, thì tôi đã thất vọng rồi.'),
(14300, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 27, 14, 'OT', 'Hãy trông đợi Đức Giê-hô-va, hãy mạnh mẽ và can đảm lòng ngươi; và hãy trông đợi Đức Giê-hô-va.'),
(14301, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 28, 1, 'OT', 'Hỡi Đức Giê-hô-va, tôi kêu cầu Ngài; hỡi Đá tôi, xin đừng làm thinh trước mặt tôi; nếu Ngài làm im lặng trước mặt tôi, thì tôi sẽ giống như những kẻ xuống hầm.'),
(14302, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 28, 2, 'OT', 'Xin hãy nghe tiếng khẩn nguyện của tôi khi tôi kêu cầu cùng Ngài, khi tôi giơ tay hướng về nơi chí thánh Ngài.'),
(14303, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 28, 3, 'OT', 'Xin đừng kéo tôi đi cùng kẻ ác và những kẻ làm điều ác, những kẻ nói lời hòa bình với người láng giềng mình, nhưng trong lòng lại toan tính điều dữ.'),
(14304, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 28, 4, 'OT', 'Xin Đức Giê-hô-va lấy việc làm của chúng mà trả cho chúng, và tùy điều ác trong hành động chúng; lấy điều tay chúng làm mà trả cho chúng, và hoàn trả cho chúng sự báo ứng xứng đáng.'),
(14305, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 28, 5, 'OT', 'Vì chúng nó không hiểu đến công việc của Đức Giê-hô-va, cũng không để ý đến việc tay Ngài làm; nên Ngài sẽ hủy diệt chúng nó, không xây dựng chúng nó lên.'),
(14306, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 28, 6, 'OT', 'Đáng ngợi khen Đức Giê-hô-va, vì Ngài đã nghe tiếng khẩn cầu của tôi.'),
(14307, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 28, 7, 'OT', 'Đức Giê-hô-va là sức lực và là cái khiên của tôi; lòng tôi đã tin cậy nơi Ngài, và tôi được Ngài cứu giúp; lòng tôi mừng rỡ, và bằng bài ca tôi sẽ ngợi khen Ngài.'),
(14308, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 28, 8, 'OT', 'Đức Giê-hô-va là sức lực cho họ, và là đồn lũy cứu rỗi cho Đấng Christ của Ngài.'),
(14309, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 28, 9, 'OT', 'Cứu dân Ngài và ban phước cho cơ nghiệp Ngài; hãy chăn giữ và nâng đỡ họ đến mãi mãi.'),
(14310, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 29, 1, 'OT', 'Hỡi các con của Đức Chúa Trời, hãy dâng cho Đức Giê-hô-va sự vinh hiển và quyền năng.'),
(14311, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 29, 2, 'OT', 'Hãy dâng cho Đức Giê-hô-va sự vinh hiển xứng đáng với danh Ngài; hãy thờ lạy Đức Giê-hô-va trong vẻ trang nghiêm thánh khiết.'),
(14312, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 29, 3, 'OT', 'Tiếng Đức Giê-hô-va dội trên các nước; Đức Chúa Trời vinh hiển sấm sét; Đức Giê-hô-va trên các nước lớn.'),
(14313, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 29, 4, 'OT', 'Tiếng Đức Giê-hô-va đầy quyền năng; tiếng Đức Giê-hô-va đầy oai nghiêm.'),
(14314, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 29, 5, 'OT', 'Tiếng Đức Giê-hô-va bẻ gãy những cây hương nam; phải Đức Giê-hô-va bẻ gãy những cây hương nam Li-ban.'),
(14315, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 29, 6, 'OT', 'Khiến Li-ban nhảy như bò con, và Si-ri-ôn như bò tót tơ.'),
(14316, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 29, 7, 'OT', 'Tiếng Đức Giê-hô-va làm tia lửa bừng lên.'),
(14317, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 29, 8, 'OT', 'Tiếng Đức Giê-hô-va làm cho đồng vắng rúng động; tiếng Đức Giê-hô-va làm cho đồng vắng Ca-đe rúng động.'),
(14318, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 29, 9, 'OT', 'Tiếng Đức Giê-hô-va khiến các con nai cái chuyển dạ sinh con, và làm cho các khu rừng trụi lá; trong đền thờ Ngài, mọi loài đều kêu lên: Vinh hiển!'),
(14319, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 29, 10, 'OT', 'Đức Giê-hô-va ngự trên cơn lụt; Đức Giê-hô-va ngự ngôi vua đời đời.'),
(14320, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 29, 11, 'OT', 'Đức Giê-hô-va sẽ ban sức lực cho dân Ngài; Đức Giê-hô-va sẽ ban phước cho dân Ngài bằng sự bình an.'),
(14321, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 30, 1, 'OT', 'Bài ca của Đa-vít, bài ca mừng việc xây cất đền thờ. Lạy Đức Giê-hô-va, con sẽ cao rao Ngài, vì Ngài đã kéo con lên, không để kẻ thù nghịch con được vui mừng về con.'),
(14322, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 30, 2, 'OT', 'Lạy Đức Giê-hô-va, Đức Chúa Trời tôi, tôi đã kêu cầu cùng Ngài, và Ngài đã chữa lành tôi.'),
(14323, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 30, 3, 'OT', 'Hỡi Đức Giê-hô-va, Ngài đã đem linh hồn tôi lên từ âm phủ, khiến tôi sống lại, không để tôi xuống huyệt.'),
(14324, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 30, 4, 'OT', 'Hỡi các thánh của Đức Giê-hô-va, hãy ca hát cho Đức Giê-hô-va, và hãy cảm tạ danh thánh của Ngài.'),
(14325, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 30, 5, 'OT', 'Vì cơn giận Ngài chỉ trong chốc lát, Còn ơn lành Ngài trọn đời: Buổi tối, nước mắt còn ở lại, Nhưng sáng mai, có tiếng reo mừng.'),
(14326, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 30, 6, 'OT', 'Còn tôi, tôi nói trong sự thịnh vượng của tôi: "Tôi sẽ chẳng bao giờ rung rinh."'),
(14327, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 30, 7, 'OT', 'Hỡi Đức Giê-hô-va, nhờ ơn Ngài, núi tôi được lập vững bền; Ngài ẩn mặt đi, tôi bèn bối rối.'),
(14328, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 30, 8, 'OT', 'Lạy Đức Giê-hô-va, tôi kêu cầu Ngài, và nài xin cùng Chúa.'),
(14329, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 30, 9, 'OT', 'Máu tôi đổ ra, khi tôi xuống huyệt, có ích lợi gì đâu? Bụi đất há sẽ cảm tạ Ngài ư? Nó há sẽ rao báo sự thật Ngài sao?'),
(14330, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 30, 10, 'OT', 'Hỡi Đức Giê-hô-va, xin nghe và thương xót tôi; Đức Giê-hô-va ôi, hãy làm đấng phù trợ tôi.'),
(14331, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 30, 11, 'OT', 'Ngài đã đổi sự than khóc của tôi thành điệu nhảy, mở áo tang tôi và thắt lưng tôi bằng sự vui mừng.'),
(14332, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 30, 12, 'OT', 'Hầu cho sự vinh hiển ngợi khen Chúa và không nín lặng. Giê-hô-va Đức Chúa Trời tôi, tôi sẽ cảm tạ Chúa đến đời đời.'),
(14333, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 31, 1, 'OT', 'Hỡi Đức Giê-hô-va, tôi tin cậy Ngài; xin đừng để tôi hổ thẹn mãi mãi. Nhờ sự công chính của Ngài, xin giải cứu tôi.'),
(14334, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 31, 2, 'OT', 'Xin nghiêng tai về phía tôi, mau mau giải cứu tôi. Xin làm cho tôi một hòn đá làm nơi nương náu, một thành trì để cứu tôi.'),
(14335, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 31, 3, 'OT', 'Vì Ngài là hòn đá và đồn lũy của tôi; nhân danh Ngài, xin dẫn dắt và hướng dẫn tôi.'),
(14336, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 31, 4, 'OT', 'Xin Đức Giê-hô-va kéo tôi ra khỏi lưới mà chúng nó giăng kín tôi; vì chính Ngài là nơi nương náu của tôi.'),
(14337, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 31, 5, 'OT', 'Tôi phó linh hồn tôi trong tay Đức Giê-hô-va; Ngài đã chuộc tôi, hỡi Đức Giê-hô-va, Đức Chúa Trời thành thực.'),
(14338, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 31, 6, 'OT', 'Tôi ghét những kẻ giữ các điều hư không vô ích; còn tôi, tôi tin cậy nơi Đức Giê-hô-va.'),
(14339, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 31, 7, 'OT', 'Tôi sẽ vui mừng và hớn hở vì sự nhân từ của Đức Giê-hô-va, vì Ngài đã nhìn xem nỗi khốn khổ tôi, biết rõ sự gian truân của linh hồn tôi.'),
(14340, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 31, 8, 'OT', 'Chúa không nộp tôi vào tay kẻ thù, mà đặt chân tôi trên đất rộng rãi.'),
(14341, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 31, 9, 'OT', 'Lạy Đức Giê-hô-va, xin thương xót tôi, vì tôi đang gặp gian truân; mắt tôi hao mòn vì cơn thịnh nộ, cả linh hồn lẫn bụng tôi.'),
(14342, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 31, 10, 'OT', 'Vì buồn sầu làm cho đời tôi cạn kiệt, các năm tôi tiêu hao trong tiếng than vãn; sức lực tôi suy sụp vì tội lỗi, xương cốt tôi cũng khô héo.'),
(14343, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 31, 11, 'OT', 'Vì mọi kẻ thù tôi, tôi đã trở nên điều đáng sỉ nhục, thật sự rất đáng sỉ nhục cho những người hàng xóm tôi, và là điều đáng sợ cho những người quen biết tôi; những kẻ thấy tôi ngoài đường thì tránh xa tôi.'),
(14344, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 31, 12, 'OT', 'Tôi bị lãng quên như kẻ chết khỏi lòng người; tôi trở nên như một đồ dùng bị mất.'),
(14345, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 31, 13, 'OT', 'Tôi đã nghe lời đồn đại của nhiều người, kinh hoàng ở khắp bốn phía; khi chúng cùng nhau âm mưu chống tôi, toan lấy mạng sống tôi.'),
(14346, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 31, 14, 'OT', 'Nhưng tôi tin cậy nơi Đức Giê-hô-va; tôi nói: Ngài là Đức Chúa Trời tôi.'),
(14347, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 31, 15, 'OT', 'Các thì điểm của tôi ở trong tay Ngài; xin giải cứu tôi khỏi tay kẻ thù và khỏi tay kẻ đuổi theo tôi.'),
(14348, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 31, 16, 'OT', 'Xin soi sáng mặt Đức Giê-hô-va trên kẻ tôi tớ Ngài, và lấy sự nhân từ Ngài mà cứu tôi.'),
(14349, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 31, 17, 'OT', 'Lạy Đức Giê-hô-va, xin đừng để tôi phải hổ thẹn, vì tôi đã kêu cầu Ngài; nguyện kẻ ác phải hổ thẹn, và bị câm lặng trong âm phủ!'),
(14350, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 31, 18, 'OT', 'Nguyện các môi lưỡi dối trá bị câm lặng, chúng nói lời gian ác nghịch cùng người công bình với kiêu căng và khinh miệt.'),
(14351, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 31, 19, 'OT', 'Đức Giê-hô-va ơi, điều thiện lành Ngài đã dành cho kẻ kính sợ Ngài, điều Ngài đã làm cho những kẻ tin cậy Ngài trước mặt con cái loài người, thật là lớn lao biết bao!'),
(14352, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 31, 20, 'OT', 'Ngài sẽ giấu họ trong nơi khuất khỏi mặt Ngài, để tránh mưu toan của kẻ dữ; Ngài sẽ che kín họ trong lều, để khỏi lời cãi vã của lưỡi.'),
(14353, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 31, 21, 'OT', 'Đáng ngợi khen Đức Giê-hô-va, vì Ngài đã tỏ cho tôi sự nhân từ lạ lùng của Ngài trong thành có vách thành.'),
(14354, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 31, 22, 'OT', 'Tôi nói trong cơn vội vàng: Tôi bị cắt đứt khỏi trước mặt Ngài; nhưng thật, Ngài đã nghe tiếng nài xin của tôi khi tôi kêu cứu cùng Ngài.'),
(14355, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 31, 23, 'OT', 'Hỡi các thánh của Đức Giê-hô-va, hãy yêu mến Ngài; Đức Giê-hô-va gìn giữ những người thành tín, nhưng báo trả nặng nề kẻ làm điều kiêu ngạo.'),
(14356, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 31, 24, 'OT', 'Hỡi những người trông cậy nơi Đức Giê-hô-va, hãy mạnh mẽ và can đảm trong lòng các ngươi.'),
(14357, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 32, 1, 'OT', 'Phước thay cho người nào được tha thứ tội ác, được che phủ tội lỗi!'),
(14358, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 32, 2, 'OT', 'Phước thay cho người mà Đức Giê-hô-va không kể tội ác, và trong lòng người ấy không có sự gian dối!'),
(14359, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 32, 3, 'OT', 'Khi tôi nín lặng, các xương tôi tiêu hao, vì tôi rên rỉ suốt cả ngày.'),
(14360, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 32, 4, 'OT', 'Vì ngày và đêm tay Ngài đè nặng trên tôi; thân tôi hao mòn như bởi nắng cháy mùa hè.'),
(14361, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 32, 5, 'OT', 'Tôi đã thú nhận tội lỗi tôi cùng Đức Giê-hô-va, và không che giấu gian ác tôi. Tôi nói: Tôi sẽ xưng các sự phạm tội tôi cùng Đức Giê-hô-va; và Ngài tha tội lỗi tôi. Hết.'),
(14362, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 32, 6, 'OT', 'Vì cớ đó, mọi người nhân từ sẽ cầu xin Ngài trong lúc Ngài có thể được tìm thấy; thật vậy, khi nước lũ lớn dâng lên, chúng sẽ không đến gần người ấy.'),
(14363, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 32, 7, 'OT', 'Chính Ngài là nơi ẩn náu cho tôi; Ngài sẽ bảo vệ tôi khỏi cơn gian truân; Ngài lấy tiếng reo mừng giải cứu mà vây quanh tôi.'),
(14364, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 32, 8, 'OT', 'Ta sẽ dạy dỗ ngươi và hướng dẫn ngươi con đường ngươi phải đi; mắt Ta sẽ chăm chú nhìn ngươi mà khuyên bảo ngươi.'),
(14365, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 32, 9, 'OT', 'Đừng như ngựa, như lừa không hiểu biết, phải dùng mõm và dây cương mới khống chế được, nếu không sẽ không đến gần ngươi.'),
(14366, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 32, 10, 'OT', 'Kẻ ác phải chịu nhiều đau đớn; nhưng ai tin cậy nơi Đức Giê-hô-va thì sự nhân từ sẽ bao quanh người ấy.'),
(14367, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 32, 11, 'OT', 'Hỡi những người công bình, hãy vui vẻ và hớn hở trong Đức Giê-hô-va; hỡi mọi người có lòng ngay thẳng, hãy reo mừng!'),
(14368, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 33, 1, 'OT', 'Hỡi các người công bình, hãy reo vui trong Đức Giê-hô-va; sự ngợi khen thật xứng hợp cho những kẻ ngay thẳng.'),
(14369, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 33, 2, 'OT', 'Hãy cảm tạ Đức Giê-hô-va bằng đàn cầm, dùng đàn mười dây mà hát ngợi khen Ngài.'),
(14370, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 33, 3, 'OT', 'Hãy hát cho Đức Giê-hô-va một bài ca mới; hãy khéo tấu nhạc với tiếng reo hò.'),
(14371, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 33, 4, 'OT', 'Vì lời Đức Giê-hô-va là ngay thẳng, và mọi công việc Ngài làm đều trung thực.'),
(14372, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 33, 5, 'OT', 'Chúa yêu chuộng sự công bình và sự đoán xét; đất đầy dẫy sự nhân từ của Đức Giê-hô-va.'),
(14373, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 33, 6, 'OT', 'Bởi lời của Đức Giê-hô-va, các từng trời được tạo nên; và bởi hơi thở từ miệng Ngài, cả đạo binh trên trời được dựng lập.'),
(14374, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 33, 7, 'OT', 'Ngài gom các nước biển lại như chất vào một đống, để các vực thẳm vào kho tàng của Ngài.'),
(14375, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 33, 8, 'OT', 'Toàn thể đất hãy kính sợ Đức Giê-hô-va; mọi người sống trên thế gian hãy sợ hãi Ngài.'),
(14376, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 33, 9, 'OT', 'Vì Ngài phán thì điều đó xảy ra; Ngài truyền lệnh thì điều đó được lập định.'),
(14377, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 33, 10, 'OT', 'Đức Giê-hô-va phá tan mưu kế của các nước, làm thất bại những ý định của các dân tộc.'),
(14378, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 33, 11, 'OT', 'Mưu sự của Đức Giê-hô-va thì đứng vững mãi mãi, các ý định trong lòng Ngài thì còn từ đời này sang đời khác.'),
(14379, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 33, 12, 'OT', 'Phước thay cho dân tộc mà Đức Giê-hô-va là Đức Chúa Trời mình, và dân sự mà Ngài chọn làm cơ nghiệp cho Ngài!'),
(14380, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 33, 13, 'OT', 'Từ trên trời, Đức Giê-hô-va ngó xuống, thấy hết thảy con cái loài người.'),
(14381, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 33, 14, 'OT', 'Từ nơi Ngài ngự, Đức Giê-hô-va quan sát, nhìn xem mọi người sống trên đất.'),
(14382, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 33, 15, 'OT', 'Đấng nắn nên lòng mỗi người, Đấng thấu hiểu mọi việc họ làm.'),
(14383, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 33, 16, 'OT', 'Chẳng phải vua nào được cứu bởi đạo binh đông đảo, cũng chẳng phải người mạnh mẽ nào được giải thoát nhờ sức lực hùng cường.'),
(14384, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 33, 17, 'OT', 'Ngựa cứu giúp là điều giả dối; dù mạnh mẽ bao nhiêu, nó cũng không thể giải cứu.'),
(14385, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 33, 18, 'OT', 'Kìa, mắt của Đức Giê-hô-va chăm nom người kính sợ Ngài, Chăm nom người trông cậy nơi sự nhân từ Ngài.'),
(14386, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 33, 19, 'OT', 'Để cứu linh hồn họ khỏi sự chết, và cho họ sống trong cơn đói kém.'),
(14387, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 33, 20, 'OT', 'Linh hồn chúng tôi trông đợi Đức Giê-hô-va; Ngài là sự giúp đỡ và cái khiên che chở chúng tôi.'),
(14388, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 33, 21, 'OT', 'Lòng chúng tôi sẽ vui mừng nơi Ngài, vì chúng tôi đã tin cậy nơi danh thánh của Ngài.'),
(14389, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 33, 22, 'OT', 'Nguyện sự nhân từ của Đức Giê-hô-va giáng trên chúng tôi, y như chúng tôi đã trông đợi Ngài.'),
(14390, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 34, 1, 'OT', 'Tôi sẽ chúc tụng Đức Giê-hô-va mọi lúc, sự ngợi khen Ngài luôn ở nơi miệng tôi.'),
(14391, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 34, 2, 'OT', 'Linh hồn tôi sẽ khoe mình về Đức Giê-hô-va; những người khiêm nhường sẽ nghe và vui mừng.'),
(14392, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 34, 3, 'OT', 'Hãy cùng ta tôn vinh Đức Giê-hô-va, và cùng nhau cao rao danh Ngài.'),
(14393, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 34, 4, 'OT', 'Tôi đã tìm cầu Đức Giê-hô-va, Ngài đáp lại tôi, và giải cứu tôi khỏi mọi sự sợ hãi của tôi.'),
(14394, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 34, 5, 'OT', 'Chúng nhìn về Ngài thì sáng láng, và mặt chúng chẳng phải hổ thẹy.'),
(14395, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 34, 6, 'OT', 'Người khốn khổ nầy kêu cầu, Đức Giê-hô-va bèn nghe, và từ mọi điều gian truân của người, Ngài cứu người.'),
(14396, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 34, 7, 'OT', 'Thiên sứ của Đức Giê-hô-va đóng trại chung quanh những người kính sợ Ngài, và giải cứu họ.'),
(14397, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 34, 8, 'OT', 'Hãy nếm và xem Đức Giê-hô-va thiện lành biết bao! Phước cho người nào nương náu nơi Ngài!'),
(14398, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 34, 9, 'OT', 'Hỡi các thánh của Đức Giê-hô-va, hãy kính sợ Ngài; vì chẳng có ai kính sợ Ngài mà thiếu thốn điều gì.'),
(14399, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 34, 10, 'OT', 'Sư tử con thì thiếu thốn và đói; nhưng những kẻ tìm kiếm Đức Giê-hô-va không thiếu mọi điều tốt lành.'),
(14400, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 34, 11, 'OT', 'Hỡi các con, hãy đến nghe ta; ta sẽ dạy các con sự kính sợ Đức Giê-hô-va.'),
(14401, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 34, 12, 'OT', 'Ai là người ham muốn sự sống, yêu thích những ngày để thấy điều thiện?'),
(14402, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 34, 13, 'OT', 'Hãy giữ lưỡi mình khỏi điều ác, và môi mình khỏi nói lời gian dối.'),
(14403, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 34, 14, 'OT', 'Hãy lánh khỏi điều ác và làm điều lành, hãy tìm kiếm sự bình an và theo đuổi nó.'),
(14404, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 34, 15, 'OT', 'Mắt Đức Giê-hô-va chăm xem người công bình, tai Ngài lắng nghe tiếng kêu cầu của họ.'),
(14405, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 34, 16, 'OT', 'Mặt Đức Giê-hô-va nghịch cùng những kẻ làm điều ác, để diệt khỏi đất sự tưởng nhớ đến họ.'),
(14406, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 34, 17, 'OT', 'Kẻ hiền nhân kêu cầu, Đức Giê-hô-va bèn nghe, và giải cứu họ khỏi mọi sự gian truân của họ.'),
(14407, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 34, 18, 'OT', 'Đức Giê-hô-va ở gần những người có lòng tan vỡ, và cứu những người có tinh thần khiêm nhường.'),
(14408, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 34, 19, 'OT', 'Người công bình gặp nhiều tai họa, nhưng Đức Giê-hô-va sẽ giải cứu người khỏi các điều ấy.'),
(14409, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 34, 20, 'OT', 'Ngài giữ gìn mọi xương người, chẳng một cái nào bị gãy.'),
(14410, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 34, 21, 'OT', 'Cái chết của kẻ ác là điều ác; những kẻ ghét người công chính sẽ mang tội.'),
(14411, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 34, 22, 'OT', 'Đức Giê-hô-va chuộc linh hồn của kẻ tôi tớ Ngài; và phàm ai nương náu nơi Ngài ắt sẽ không bị định tội.'),
(14412, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 35, 1, 'OT', 'Hỡi Đức Giê-hô-va, xin hãy tranh tụng cùng kẻ tranh tụng tôi, xin chiến đấu cùng kẻ chiến đấu tôi.'),
(14413, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 35, 2, 'OT', 'Hãy cầm lấy cái khiên và cái thuẫn, Chổi-dậy giúp đỡ tôi.'),
(14414, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 35, 3, 'OT', 'Hãy rút ngọn giáo và cái chắn ra nghênh chiến những kẻ rượt đuổi tôi; Hãy nói với linh hồn tôi: "Ta là sự cứu rỗi của ngươi."'),
(14415, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 35, 4, 'OT', 'Nguyện những kẻ tìm mạng sống tôi phải bị hổ thẹy và sỉ nhục; nguyện những kẻ toan mưu điều ác cho tôi phải lùi lại và xấu hổ.'),
(14416, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 35, 5, 'OT', 'Nguyện chúng nó như bụi bị gió thổi đi, và thiên sứ của Đức Giê-hô-va xua đuổi chúng nó!'),
(14417, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 35, 6, 'OT', 'Nguyện đường chúng nó phải tối tăm và trơn trợt, và thiên sứ của Đức Giê-hô-va sẽ đuổi theo chúng nó.'),
(14418, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 35, 7, 'OT', 'Vì vô cớ, chúng nó đã rải lưới tôi; vô cớ, chúng nó đã đào hầm cho mạng tôi.'),
(14419, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 35, 8, 'OT', 'Nguyện tai họa bất ngờ ập đến nó, và cái bẫy nó đã giấu kín sẽ bắt nó; nguyện nó sa vào tai họa ấy.'),
(14420, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 35, 9, 'OT', 'Linh hồn tôi sẽ vui vẻ trong Đức Giê-hô-va, mừng rỡ về sự cứu rỗi của Ngài.'),
(14421, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 35, 10, 'OT', 'Các xương cốt tôi sẽ nói: Hỡi Đức Giê-hô-va, ai bằng Ngài, Đấng giải cứu người khiêm nhường khỏi kẻ mạnh hơn mình, và người nghèo khó, kẻ thiếu thốn khỏi kẻ cướp lột?'),
(14422, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 35, 11, 'OT', 'Những kẻ làm chứng gian ác hãy đứng lên; chúng tra hỏi tôi về những điều tôi không hề biết.'),
(14423, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 35, 12, 'OT', 'Chúng lấy điều ác đáp đền điều lành, khiến cho linh hồn tôi bị bỏ rơi.'),
(14424, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 35, 13, 'OT', 'Còn tôi, khi chúng đau yếu, tôi mặc áo bằng vải thô, ăn chay và ép lòng tôi; còn lời cầu nguyện tôi trở về ngực tôi.'),
(14425, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 35, 14, 'OT', 'Tôi đi lại như người anh em của kẻ đau buồn, cúi đầu như kẻ than khóc mẹ mình.'),
(14426, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 35, 15, 'OT', 'Nhưng khi tôi sa ngã, chúng vui mừng và tụ tập lại; những kẻ khinh bỉ tôi tụ họp nghịch cùng tôi, mà tôi chẳng biết; chúng xé nát tôi không ngừng.'),
(14427, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 35, 16, 'OT', 'Những kẻ gian ác hay nhạo báng, chúng nghiến răng nghịch lại tôi.'),
(14428, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 35, 17, 'OT', 'Lạy Đức Giê-hô-va, Ngài sẽ nhìn xem bao lâu nữa? Xin hãy trở lại, giải cứu linh hồn tôi khỏi những kẻ tấn công tôi, mạng sống tôi khỏi những sư tử.'),
(14429, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 35, 18, 'OT', 'Tôi sẽ cảm tạ Ngài trong hội đông đảo, sẽ ngợi khen Ngài giữa một dân sự hùng mạnh.'),
(14430, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 35, 19, 'OT', 'Đừng để kẻ thù tôi là kẻ nói dối vui mừng về tôi; những kẻ ghét tôi cách vô cớ đừng nháy mắt.'),
(14431, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 35, 20, 'OT', 'Vì chúng không nói điều hòa bình, mà toan tính những lời gian dối chống lại những người sống yên ổn trong đất.'),
(14432, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 35, 21, 'OT', 'Chúng nó há miệng rộng ra nghịch tôi, mà rằng: Ha! ha! Mắt chúng ta đã thấy rồi.'),
(14433, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 35, 22, 'OT', 'Đức Giê-hô-va đã thấy điều đó, xin chớ làm thinh; lạy Chúa, xin chớ lìa xa tôi.'),
(14434, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 35, 23, 'OT', 'Đức Chúa Trời và Chúa tôi, hãy tỉnh thức và chỗi dậy để xét đoán cho tôi, để bênh vực sự tranh tụng của tôi.'),
(14435, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 35, 24, 'OT', 'Hỡi Đức Giê-hô-va Đức Chúa Trời tôi, xin hãy xét đoán tôi theo sự công bình của Ngài, và chớ để chúng vui mừng vì tôi.'),
(14436, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 35, 25, 'OT', 'Đừng để chúng nó nói trong lòng mình: "Chúng ta đã toại nguyện!" Đừng để chúng nó nói: "Chúng ta đã nuốt chửng nó rồi!"'),
(14437, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 35, 26, 'OT', 'Chúng nó phải cùng nhau hổ thẹy và xấu hổ, những kẻ vui mừng vì tai họa tôi; nguyện chúng nó mặc lấy sự hổ thẹn và sỉ nhục, những kẻ tự phụ lên tôi.'),
(14438, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 35, 27, 'OT', 'Hãy reo mừng và vui vẻ, những kẻ yêu mến sự công bình tôi; và họ sẽ luôn nói: Đáng tôn vinh thay Đức Giê-hô-va, Đấng vui thích sự bình an của tôi tớ Ngài.'),
(14439, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 35, 28, 'OT', 'Và lưỡi tôi sẽ nói về sự công bình của Đức Giê-hô-va; suốt cả ngày tôi sẽ ca ngợi sự công bình của Ngài.'),
(14440, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 36, 1, 'OT', 'Đức Giê-hô-va phán hằng về sự phạm tội của kẻ ác trong lòng tôi: Chẳng có sự kính sợ Đức Chúa Trời trước mặt nó.'),
(14441, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 36, 2, 'OT', 'Vì nó làm cho lòng mình êm ái trước mặt nó, để không thấy tội mình mà ghét bỏ.'),
(14442, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 36, 3, 'OT', 'Các lời nơi miệng người ấy là sự gian ác và lừa dối; người ấy đã thôi suy nghĩ để làm điều thiện.'),
(14443, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 36, 4, 'OT', 'Nó toan tính điều ác trên giường nó; nó đứng trên con đường chẳng phải lành, chẳng từ chối điều dữ.'),
(14444, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 36, 5, 'OT', 'Hỡi Đức Giê-hô-va, sự nhân từ của Ngài ở trên các từng trời; sự thành tín của Ngài đến tận các từng mây.'),
(14445, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 36, 6, 'OT', 'Sự công bình của Ngài giống như núi Đức Chúa Trời, sự đoán xét của Ngài như vực thẳm sâu xa. Hỡi Đức Giê-hô-va, Ngài cứu giúp loài người và súc vật.'),
(14446, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 36, 7, 'OT', 'Hỡi Đức Chúa Trời, ân lộc của Ngài quí bao! Con cái loài người nương náu mình dưới bóng cánh của Ngài.'),
(14447, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 36, 8, 'OT', 'Họ sẽ được no thỏa bởi sự dư dật trong nhà Ngài; Ngài sẽ cho họ uống từ dòng sông phước lạc của Ngài.'),
(14448, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 36, 9, 'OT', 'Vì nơi Ngài là nguồn sự sống; trong ánh sáng của Ngài, chúng tôi thấy ánh sáng.'),
(14449, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 36, 10, 'OT', 'Xin giương sự nhân từ của Đức Giê-hô-va ra cho những người biết Ngài, và sự công bình của Ngài cho những người lòng ngay thẳng.'),
(14450, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 36, 11, 'OT', 'Xin chớ để chân kẻ kiêu ngạo bước vào tôi, và tay kẻ ác chớ xô tôi ngã.'),
(14451, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 36, 12, 'OT', 'Tại đó, những kẻ làm điều ác ngã xuống; chúng bị xô đổ và không thể đứng lên được.'),
(14452, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 1, 'OT', 'Đừng nóng lòng vì kẻ làm ác, Đừng ghen tức kẻ làm điều gian tà.'),
(14453, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 2, 'OT', 'Vì như cỏ, chúng sẽ mau bị chặt, và như rau xanh, chúng sẽ chóng héo tàn.'),
(14454, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 3, 'OT', 'Hãy tin cậy Đức Giê-hô-va và làm điều lành; hãy ở trong đất và chăn nuôi bằng sự trung tín.'),
(14455, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 4, 'OT', 'Hãy lấy làm vui nơi Đức Giê-hô-va, thì Ngài sẽ ban cho ngươi những điều lòng ngươi ao ước.'),
(14456, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 5, 'OT', 'Hãy phó thác con đường của ngươi cho Đức Giê-hô-va, và tin cậy nơi Ngài, thì chính Ngài sẽ thực hiện điều đó.'),
(14457, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 6, 'OT', 'Ngài sẽ làm cho sự công bình của ngươi nổi lên như ánh sáng, và sự xét đoán của ngươi như trưa nắng.'),
(14458, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 7, 'OT', 'Hãy nín lặng trước mặt Đức Giê-hô-va và hãy trông đợi Ngài; chớ nóng lòng vì kẻ thạnh lợi trong con đường mình, hay vì kẻ làm thành những mưu ác.'),
(14459, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 8, 'OT', 'Hãy ngưng tức giận, và bỏ cơn thịnh nộ; đừng nóng lòng, vì chỉ dẫn đến điều ác.'),
(14460, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 9, 'OT', 'Vì những kẻ làm ác sẽ bị tiêu diệt; còn những kẻ trông đợi Đức Giê-hô-va sẽ được đất làm cơ nghiệp.'),
(14461, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 10, 'OT', 'Lại một chút nữa, và kẻ ác sẽ không còn; ngươi sẽ nhìn kỹ chỗ nó ở, thật nó không còn nữa.'),
(14462, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 11, 'OT', 'Những người hiền lành sẽ hưởng đất làm cơ nghiệp, và khoái lạc trong sự thịnh vượng bình an.'),
(14463, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 12, 'OT', 'Kẻ ác lập mưu nghịch cùng người công bình, và nghiến răng nghịch cùng người.'),
(14464, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 13, 'OT', 'Đức Giê-hô-va sẽ cười nó, vì thấy ngày của nó sẽ đến.'),
(14465, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 14, 'OT', 'Kẻ ác rút gươm ra, giương cung mình, để làm đổ kẻ khốn cùng và kẻ thiếu thốn, để giết những người ngay thẳng trong đường lối.'),
(14466, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 15, 'OT', 'Gươm của chúng sẽ đâm vào lòng chúng, và cây cung của chúng sẽ bị gãy.'),
(14467, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 16, 'OT', 'Của ít người công bình tốt hơn rất nhiều của cải dư dật của kẻ ác.'),
(14468, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 17, 'OT', 'Vì những cánh tay của kẻ ác sẽ bị gãy, còn Đức Giê-hô-va nâng đỡ những người công bình.'),
(14469, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 18, 'OT', 'Đức Giê-hô-va biết các ngày của kẻ trọn lành, và cơ nghiệp của họ sẽ còn mãi đời đời.'),
(14470, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 19, 'OT', 'Trong thời gian khốn khó, họ sẽ không bị hổ thẹn; trong những ngày đói kém, họ sẽ được no đủ.'),
(14471, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 20, 'OT', 'Vì kẻ ác sẽ bị tiêu diệt, và những kẻ thù nghịch Đức Giê-hô-va sẽ như mỡ chiên con: chúng nó bị thiêu tan trong khói.'),
(14472, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 21, 'OT', 'Kẻ ác vay mượn mà không trả; còn người công bình thì nhân từ và rộng rãi cho mượn.'),
(14473, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 22, 'OT', 'Vì những người được Đức Giê-hô-va ban phước sẽ hưởng đất; còn những kẻ bị Ngài rủa sả sẽ bị diệt mất.'),
(14474, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 23, 'OT', 'Các bước của người được Đức Giê-hô-va định liệu, và Ngài hài lòng về đường lối người.'),
(14475, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 24, 'OT', 'Dầu người té, cũng không ngã xuống; vì Đức Giê-hô-va lấy tay nâng đỡ người.'),
(14476, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 25, 'OT', 'Tôi đã từng là trẻ nhỏ, nay đã già, mà chẳng hề thấy người công bình bị bỏ rơi, hay dòng dõi người đi tìm bánh mì.'),
(14477, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 26, 'OT', 'Cả ngày người thương xót và cho vay mượn; dòng dõi người được phước.'),
(14478, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 27, 'OT', 'Hãy lánh khỏi điều ác và làm điều lành, thì sẽ được ở đời đời.'),
(14479, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 28, 'OT', 'Vì Đức Giê-hô-va yêu mến sự công bình và không từ bỏ các thánh nhân của Ngài; họ sẽ được giữ gìn đời đời, còn dòng dõi kẻ ác sẽ bị diệt trừ.'),
(14480, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 29, 'OT', 'Người công bình sẽ hưởng đất, và sẽ ở trên đất đời đời.'),
(14481, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 30, 'OT', 'Miệng người công chính sẽ suy ngẫm điều khôn ngoan, và lưỡi người sẽ nói ra sự công bình.'),
(14482, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 31, 'OT', 'Luật pháp Đức Chúa Trời người ở trong lòng người; các bước đi của người không hề xiêu té.'),
(14483, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 32, 'OT', 'Kẻ ác rình người công bình, và tìm cách giết người ấy.'),
(14484, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 33, 'OT', 'Đức Giê-hô-va không bỏ mặc người trong tay kẻ ác, cũng không lên án người khi người bị xét xử.'),
(14485, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 34, 'OT', 'Hãy trông đợi Đức Giê-hô-va và giữ theo đường lối Ngài, thì Ngài sẽ nâng ngươi lên để nhận đất; khi các kẻ ác bị tiêu diệt, ngươi sẽ thấy điều đó.'),
(14486, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 35, 'OT', 'Tôi đã thấy kẻ ác đầy quyền thế, và phất lên như cây xanh tươi mọc nơi đất bản địa.'),
(14487, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 36, 'OT', 'Người ấy đi qua, nầy, hắn không còn nữa; tôi tìm người ấy, nhưng không gặp.'),
(14488, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 37, 'OT', 'Hãy giữ trọn vẹn và nhìn xem điều ngay thẳng, vì cuối cùng người bình an sẽ được phước.'),
(14489, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 38, 'OT', 'Còn những kẻ phạm tội sẽ bị tiêu diệt cùng nhau; cuối cùng của những kẻ ác bị cắt đứt.'),
(14490, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 39, 'OT', 'Sự cứu rỗi của người công bình đến từ Đức Giê-hô-va; Ngài là đồn lũy của họ trong lúc gian truân.'),
(14491, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 37, 40, 'OT', 'Đức Giê-hô-va giúp đỡ và giải cứu họ; Ngài giải họ khỏi kẻ ác và cứu rỗi họ, vì họ đã nương náu mình nơi Ngài.'),
(14492, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 38, 1, 'OT', 'Một bài ca của Đa-vít, để nhắc nhở: Đức Giê-hô-va ôi, xin chớ lấy cơn thạnh nộ mà quở trách tôi, cũng đừng lấy cơn giận mà sửa phạt tôi.'),
(14493, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 38, 2, 'OT', 'Vì các mũi tên của Ngài đã cắm vào tôi, và tay Ngài đè nặng trên tôi.'),
(14494, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 38, 3, 'OT', 'Nhân vì cơn thạnh nộ của Đức Giê-hô-va, thịt tôi không còn lành mạnh nào; nhân vì tội lỗi tôi, xương tôi không còn bình an nào.'),
(14495, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 38, 4, 'OT', 'Vì tội lỗi tôi đã vượt quá đầu tôi; như một gánh nặng nặng nề, chúng quá sức tôi chịu đựng.'),
(14496, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 38, 5, 'OT', 'Các vết thương tôi thối rữa và hôi thối vì cớ sự điên dại tôi.'),
(14497, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 38, 6, 'OT', 'Tôi bị cong vẹo, sụp xuống rất sâu; suốt cả ngày tôi đi trong u ám.'),
(14498, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 38, 7, 'OT', 'Vì các hông tôi đầy rẫy ô nhục, và thân thể tôi chẳng còn lành mạnh nào.'),
(14499, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 38, 8, 'OT', 'Tôi kiệt sức và bị đè ép cực kỳ; tôi rống lên vì sự rên siết của lòng tôi.'),
(14500, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 38, 9, 'OT', 'Lạy Đức Giê-hô-va, mọi sự ao ước của tôi đều ở trước mặt Ngài, và tiếng rên siết tôi không giấu khỏi Ngài.'),
(14501, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 38, 10, 'OT', 'Lòng tôi bồn chồn, sức tôi tiêu tan; và ánh sáng nơi mắt tôi, ngay cả điều đó cũng không còn với tôi nữa.'),
(14502, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 38, 11, 'OT', 'Các người yêu tôi và kẻ thân cận tôi đứng xa tôi vì tai họa tôi, và những người gần gũi tôi đứng cách xa.'),
(14503, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 38, 12, 'OT', 'Kẻ tìm mạng sống tôi thì gài bẫy tôi, những kẻ tìm hại tôi thì nói điều hư không, và suốt cả ngày toan tính điều gian dối.'),
(14504, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 38, 13, 'OT', 'Nhưng tôi như kẻ điếc, không nghe; như người câm, không mở miệng mình.'),
(14505, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 38, 14, 'OT', 'Tôi đã trở nên như người không nghe, và trong miệng người ấy không có lời biện hộ.'),
(14506, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 38, 15, 'OT', 'Vì, Đức Giê-hô-va ôi! tôi đã trông đợi Ngài; chính Ngài sẽ đáp lời, lạy Chúa, là Đức Chúa Trời tôi.'),
(14507, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 38, 16, 'OT', 'Vì tôi đã nói: "Nguyện chúng nó đừng vì cớ tôi mà vui mừng! Khi chân tôi vấp ngã, chúng nó tự đắc lên án tôi."'),
(14508, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 38, 17, 'OT', 'Vì tôi sắp vấp ngã, và nỗi đau của tôi luôn ở trước mặt tôi.'),
(14509, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 38, 18, 'OT', 'Vì tôi sẽ xưng tội ác mình ra, tôi buồn sầu vì tội lỗi tôi.'),
(14510, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 38, 19, 'OT', 'Kẻ thù tôi còn sống và mạnh mẽ, những kẻ ghét tôi cách giả dối thì đông đảo.'),
(14511, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 38, 20, 'OT', 'Những kẻ lấy điều ác đáp lại điều lành thì chống nghịch tôi, vì tôi theo điều thiện.'),
(14512, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 38, 21, 'OT', 'Đức Giê-hô-va ôi, xin chớ bỏ tôi; Đức Chúa Trời tôi ôi, xin chớ cách xa tôi.'),
(14513, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 38, 22, 'OT', 'Lạy Đức Chúa, là sự cứu rỗi của tôi, xin mau đến giúp đỡ tôi.'),
(14514, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 39, 1, 'OT', 'Tôi nói: "Tôi sẽ giữ gìn các lối đi của tôi, để khỏi phạm tội bằng lưỡi mình; tôi sẽ đặt cái khóa nơi miệng tôi, khi kẻ ác đứng trước mặt tôi."'),
(14515, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 39, 2, 'OT', 'Tôi nín lặng, lặng thinh, không nói lời tốt lành; còn nỗi đau tôi thì lại gia tăng.'),
(14516, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 39, 3, 'OT', 'Lòng tôi nóng lên trong nội tâm tôi, khi tôi suy gẫm thì lửa bùng lên; rồi lưỡi tôi nói.'),
(14517, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 39, 4, 'OT', 'Hỡi Đức Giê-hô-va, xin cho tôi biết kỳ hạn của tôi và số các ngày tôi là bao nhiêu, để tôi biết mình mỏng mảnh đến chừng nào.'),
(14518, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 39, 5, 'OT', 'Kìa, Ngài đã định các ngày tôi bằng những khoảng ngắn, và đời tôi như không trước mặt Ngài; chỉ mỗi người, dầu đứng vững, cũng chỉ là hư không.'),
(14519, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 39, 6, 'OT', 'Quả thật, loài người chỉ bước đi như bóng; thật là hư không, họ huyên náo vô ích; người ta thu góp của cải, nhưng chẳng biết ai sẽ thu lượm chúng.'),
(14520, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 39, 7, 'OT', 'Bây giờ, lạy Đức Giê-hô-va, tôi còn trông đợi điều gì? Sự trông đợi của tôi thuộc về Ngài.'),
(14521, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 39, 8, 'OT', 'Xin hãy giải cứu tôi khỏi mọi sự phạm tội của tôi; chớ đặt tôi nên sự nhục nhã của kẻ ngu dại.'),
(14522, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 39, 9, 'OT', 'Tôi làm thinh, không mở miệng mình ra, vì chính Ngài đã làm điều đó.'),
(14523, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 39, 10, 'OT', 'Xin hãy dẹp khỏi tôi sự đánh phạt của Ngài; tôi đã hao mòn vì sự sửa phạt của tay Ngài.'),
(14524, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 39, 11, 'OT', 'Khi Ngài quở trách vì tội lỗi, Ngài sửa dạy loài người; Ngài làm cho sự đẹp ưa của người tiêu tan như mọt gặm; thật vậy, mọi người chỉ là hư không.'),
(14525, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 39, 12, 'OT', 'Lạy Đức Giê-hô-va, xin hãy nghe lời cầu nguyện tôi, và lắng tai đến tiếng kêu cứu của tôi; xin chớ làm thinh trước nước mắt tôi; vì tôi là khách lạ cùng Ngài, là người tạm trú như mọi tổ tiên tôi.'),
(14526, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 39, 13, 'OT', 'Lạy Đức Giê-hô-va, xin hãy ngoảnh khỏi tôi để tôi khóc ròng, trước khi tôi qua đi và không còn nữa.'),
(14527, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 40, 1, 'OT', 'Tôi đã kiên trì trông đợi Đức Giê-hô-va, và Ngài chăm chú nhìn tôi, lắng nghe tiếng kêu cứu của tôi.'),
(14528, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 40, 2, 'OT', 'Đức Giê-hô-va kéo tôi lên khỏi hầm sôi động, khỏi vũng lầy; Ngài đặt chân tôi trên hòn đá, làm vững bước đi tôi.'),
(14529, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 40, 3, 'OT', 'Ngài đặt nơi miệng tôi một bài ca mới, lời ngợi khen Đức Chúa Trời chúng tôi; nhiều người sẽ thấy và kính sợ, và sẽ nhờ cậy nơi Đức Giê-hô-va.'),
(14530, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 40, 4, 'OT', 'Phước thay cho người đặt Đức Giê-hô-va làm chỗ tin cậy mình, và không quay về cùng những kẻ kiêu ngạo hay theo đường lối sự dối trá!'),
(14531, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 40, 5, 'OT', 'Lạy Đức Giê-hô-va, Đức Chúa Trời tôi, rất nhiều điều lạ lùng và những tư tưởng của Ngài hướng về chúng tôi; nếu tôi muốn kể ra và nói đến, thì quá nhiều, không thể đếm được.'),
(14532, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 40, 6, 'OT', 'Chúa không muốn của lễ thiêu hay của lễ chay; Chúa đã khoét tai tôi. Chúa không đòi của lễ toàn thiêu hay của lễ chuộc tội.'),
(14533, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 40, 7, 'OT', 'Bấy giờ tôi nói: Nầy, tôi đến; trong cuốn sách đã chép về tôi;'),
(14534, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 40, 8, 'OT', 'Lòng tôi vui mừng làm theo ý muốn Ngài, hỡi Đức Chúa Trời tôi, luật pháp Ngài ở trong lòng tôi.'),
(14535, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 40, 9, 'OT', 'Tôi đã rao sự công bình trong hội lớn; nầy, tôi không ngăn môi lại; Đức Giê-hô-va, chính Ngài biết điều đó.'),
(14536, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 40, 10, 'OT', 'Sự công bình của Ngài, tôi không giấu trong lòng tôi; sự trung thực và sự cứu rỗi của Ngài, tôi đã nói ra; tôi không giấu sự nhân từ và sự thật của Ngài khỏi hội đông.'),
(14537, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 40, 11, 'OT', 'Đức Giê-hô-va ôi, chớ ngăn lòng thương xót của Ngài khỏi tôi; sự nhân từ và sự chân thật của Ngài luôn luôn giữ gìn tôi.'),
(14538, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 40, 12, 'OT', 'Vì các tai họa bao quanh tôi không đếm được; các tội lỗi tôi đã bắt kịp tôi, đến nỗi tôi không thể nhìn rõ được; chúng nhiều hơn tóc trên đầu tôi, và lòng tôi đã bỏ tôi.'),
(14539, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 40, 13, 'OT', 'Đức Giê-hô-va ôi, xin sẵn lòng giải cứu tôi; Đức Giê-hô-va hỡi, xin mau mau giúp đỡ tôi.'),
(14540, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 40, 14, 'OT', 'Nguyện những kẻ tìm mạng tôi để tiêu diệt đều bị mất mặt và hổ thẹn; nguyện những kẻ vui vì sự khốn khổ tôi phải lùi lại và mang hổ nhục.'),
(14541, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 40, 15, 'OT', 'Nguyện những kẻ nói về ta: "Ha ha!" phải kinh hãi vì cớ sự xấu hổ của chúng nó.'),
(14542, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 40, 16, 'OT', 'Nguyện tất cả những kẻ tìm kiếm Ngài đều vui vẻ và hớn hở trong Ngài; nguyện những kẻ yêu mến sự cứu rỗi của Ngài luôn nói rằng: Đức Giê-hô-va đáng được tôn vinh!'),
(14543, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 40, 17, 'OT', 'Còn tôi, tôi là kẻ khốn cùng và nghèo khó; Đức Giê-hô-va ôi, xin hãy nghĩ đến tôi. Ngài là Đấng giúp đỡ tôi và là Đấng giải cứu tôi. Đức Chúa Trời tôi ôi! xin chớ chậm trễ.'),
(14544, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 41, 1, 'OT', 'Phước cho người nào thông hiểu giúp kẻ khốn cùng; trong ngày tai họa Đức Giê-hô-va sẽ giải cứu người ấy.'),
(14545, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 41, 2, 'OT', 'Đức Giê-hô-va sẽ gìn giữ người và khiến người sống, người sẽ được phước trên đất; và Ngài sẽ không phó người vào tay kẻ thù nghịch người.'),
(14546, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 41, 3, 'OT', 'Đức Giê-hô-va sẽ nâng đỡ người trên giường bệnh; Ngài đổi toàn thể chỗ nằm của người trong cơn đau yếu.'),
(14547, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 41, 4, 'OT', 'Tôi đã nói: Đức Giê-hô-va ôi! xin thương xót tôi; chữa lành linh hồn tôi, vì tôi đã phạm tội cùng Ngài.'),
(14548, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 41, 5, 'OT', 'Kẻ thù tôi nói điều ác về tôi: Chừng nào nó chết đi, và danh nó tiêu mất?'),
(14549, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 41, 6, 'OT', 'Nếu ai đến thăm để xem xét, thì nói những lời hư không; lòng nó ấp ủ điều ác cho nó; khi ra ngoài, nó nói ra.'),
(14550, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 41, 7, 'OT', 'Tất cả những kẻ thù ghét tôi đều âm mưu nghịch cùng tôi; chúng toan tính điều ác hại tôi:'),
(14551, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 41, 8, 'OT', 'Một lời nói độc ác đã giáng trên nó; và kẻ nằm xuống rồi sẽ không còn chỗi dậy nữa.'),
(14552, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 41, 9, 'OT', 'Người bạn thân của tôi, người tôi tin cậy, người đã ăn bánh tôi, chính người ấy giơ gót chân nghịch lại tôi.'),
(14553, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 41, 10, 'OT', 'Đức Giê-hô-va ôi, xin thương xót tôi, và khiến tôi đứng vững; thì tôi sẽ đáp trả chúng nó.'),
(14554, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 41, 11, 'OT', 'Điều này cho tôi biết rằng Ngài đẹp lòng tôi, vì kẻ thù tôi không thể chiến thắng tôi.'),
(14555, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 41, 12, 'OT', 'Còn tôi, vì sự ngay thẳng tôi, Ngài đã nâng đỡ tôi, và đặt tôi đứng vững trước mặt Ngài đời đời.'),
(14556, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 41, 13, 'OT', 'Đáng ngợi khen Đức Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên, từ trước vô cùng cho đến đời đời! A-men, A-men!'),
(14557, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 42, 1, 'OT', 'Linh hồn tôi khao khát Đức Chúa Trời, như con nai cái khao khát các khe nước.'),
(14558, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 42, 2, 'OT', 'Linh hồn tôi khao khát Đức Chúa Trời, là Đức Chúa Trời hằng sống; chừng nào tôi mới được đến và thấy mặt Đức Chúa Trời?'),
(14559, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 42, 3, 'OT', 'Nước mắt tôi làm lương thực ngày và đêm, khi người ta hằng hỏi tôi mỗi ngày: Đức Chúa Trời ngươi đâu?'),
(14560, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 42, 4, 'OT', 'Ta nhớ điều nầy, và đổ nước mắt trên ta, khi ta từng vượt qua cùng họ, dắt đoàn người đi đến nhà Đức Chúa Trời, trong tiếng reo mừng và cảm tạ, một đoàn dân đông đảo giữ lễ.'),
(14561, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 42, 5, 'OT', 'Hỡi linh hồn ta, vì sao ngươi sờn lòng và bồn chồn trong ta? Hãy cậy trông nơi Đức Chúa Trời, vì ta sẽ còn cảm tạ Ngài nữa; sự cứu rỗi của khuôn mặt Ngài.'),
(14562, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 42, 6, 'OT', 'Đức Chúa Trời tôi ôi, linh hồn tôi sờn ngã trong tôi; nên tôi nhớ đến Ngài từ xứ Giô-đanh, và các đỉnh Hẹt-môn, từ ngọn núi Mít-sê-a.'),
(14563, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 42, 7, 'OT', 'Vực nầy gọi vực khác theo tiếng ào ào của các thác nước Ngài; mọi con sóng và từng lớp nước lớn của Ngài đều tràn qua tôi.'),
(14564, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 42, 8, 'OT', 'Ban ngày, Đức Giê-hô-va sẽ truyền lệnh về sự nhân từ Ngài; và ban đêm, bài ca của tôi sẽ ở cùng tôi, tức là lời cầu nguyện cùng Đức Chúa Trời của sự sống tôi.'),
(14565, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 42, 9, 'OT', 'Ta sẽ thưa cùng Đức Chúa Trời, là hòn đá ta, rằng: Sao Ngài quên tôi? Sao tôi phải đi trong cảnh buồn thảm, dưới áp lực của kẻ thù nghịch?'),
(14566, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 42, 10, 'OT', 'Khi kẻ thù tôi ngày nào cũng hỏi: "Đức Chúa Trời ngươi đâu?" thì chúng sỉ nhục tôi, như thể đánh gãy các xương tôi ra.'),
(14567, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 42, 11, 'OT', 'Hỡi linh hồn ta, vì sao ngươi buồn rầu và vì sao ngươi bồn chồn trong ta? Hãy trông đợi nơi Đức Chúa Trời, vì ta sẽ còn ca ngợi Ngài nữa; Ngài là sự cứu rỗi của mặt ta, và là Đức Chúa Trời ta.'),
(14568, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 43, 1, 'OT', 'Đức Chúa Trời ôi, xin hãy xét đoán tôi, và tranh biện cho tôi trước mặt dân không nhân từ; xin giải cứu tôi khỏi người gian trá và bất công.'),
(14569, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 43, 2, 'OT', 'Vì chính Ngài là Đức Chúa Trời, nơi nương náu của tôi; cớ sao Ngài từ bỏ tôi? Cớ sao tôi phải đi trong buồn bã, dưới sự hà hiếp của kẻ thù?'),
(14570, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 43, 3, 'OT', 'Xin sai ánh sáng Ngài và sự thật Ngài dẫn tôi đi; chúng sẽ dẫn tôi đến núi thánh của Ngài và nơi Ngài ngự.'),
(14571, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 43, 4, 'OT', 'Tôi sẽ đến cùng bàn thờ Đức Chúa Trời, đến cùng Đức Chúa Trời, là niềm vui mừng của tôi; và tôi sẽ ngợi khen Ngài bằng cây đàn cầm, hỡi Đức Chúa Trời, là Đức Chúa Trời của tôi.'),
(14572, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 43, 5, 'OT', 'Hỡi linh hồn ta, vì sao ngươi buồn rầu và vì sao ngươi bồn chồn trong ta? Hãy trông đợi nơi Đức Giê-hô-va; vì ta sẽ còn ngợi khen Ngài nữa: sự cứu rỗi của mặt ta và là Đức Chúa Trời ta.'),
(14573, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 44, 1, 'OT', 'Đức Chúa Trời ôi, tai chúng tôi đã nghe; tổ tiên chúng tôi đã thuật lại cho chúng tôi công việc Ngài làm trong đời họ, những ngày xưa.'),
(14574, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 44, 2, 'OT', 'Chính tay Ngài đuổi các dân tộc ra khỏi đất, rồi trồng vào đó tổ tiên chúng tôi; Ngài xua đuổi các nước khác đi, rồi cho tổ tiên chúng tôi phát triển.'),
(14575, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 44, 3, 'OT', 'Vì chẳng phải bởi gươm họ mà chiếm được đất, cũng chẳng phải cánh tay họ cứu giúp họ; nhưng là bởi tay phải Ngài, cánh tay Ngài, và ánh sáng nhan Ngài, vì Ngài yêu thương họ.'),
(14576, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 44, 4, 'OT', 'Chính Ngài là Vua tôi, hỡi Đức Chúa Trời; xin truyền các sự giải cứu cho Gia-cốp.'),
(14577, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 44, 5, 'OT', 'Nhờ nơi Ngài, chúng tôi đâm ngã kẻ thù nghịch; nhân danh Ngài, chúng tôi giày đạp những kẻ chỗi lên nghịch cùng chúng tôi.'),
(14578, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 44, 6, 'OT', 'Vì tôi chẳng nhờ cây nỏ tôi, và gươm tôi cũng không cứu tôi được;'),
(14579, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 44, 7, 'OT', 'Vì Ngài đã cứu chúng tôi khỏi kẻ áp bức chúng tôi, và làm hổ thẹn những kẻ ghét chúng tôi.'),
(14580, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 44, 8, 'OT', 'Nhờ Đức Chúa Trời, chúng tôi khoe mình trọn ngày; chúng tôi sẽ cảm tạ danh Ngài đến muôn đời.'),
(14581, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 44, 9, 'OT', 'Nhưng Ngài đã từ bỏ và làm chúng tôi hổ thẹn, không ra đi cùng các đạo quân của chúng tôi.'),
(14582, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 44, 10, 'OT', 'Ngài khiến chúng tôi phải lùi bước trước kẻ thù, và kẻ ghét chúng tôi thì cướp bóc tùy ý.'),
(14583, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 44, 11, 'OT', 'Ngài phó chúng tôi như đàn chiên để làm đồ ăn, và trong các dân, Ngài đã rải chúng tôi ra.'),
(14584, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 44, 12, 'OT', 'Ngài bán dân Ngài mà không được lợi gì, và chẳng nhân giá chúng nó lên trong khi bán.'),
(14585, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 44, 13, 'OT', 'Chúa để chúng tôi bị kẻ lân cận sỉ nhục, Làm vật nhạo báng và chế giễu cho những kẻ ở chung quanh chúng tôi.'),
(14586, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 44, 14, 'OT', 'Ngài khiến chúng tôi trở thành lời châm biếm giữa các nước, bị chế nhạo giữa các dân tộc.'),
(14587, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 44, 15, 'OT', 'Cả ngày sự sỉ nhục của tôi ở trước mặt tôi, và sự hổ thẹn trên mặt tôi đã che phủ tôi,'),
(14588, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 44, 16, 'OT', 'Từ tiếng kẻ sỉ nhục và phỉ báng, trước mặt kẻ thù và kẻ báo oán.'),
(14589, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 44, 17, 'OT', 'Tất cả điều nầy đã xảy đến cho chúng tôi, mà chúng tôi chẳng hề quên Ngài, cũng chẳng hề dối gian trong giao ước của Ngài.'),
(14590, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 44, 18, 'OT', 'Lòng chúng tôi không lui lại, và các đường lối chúng tôi cũng không xây khỏi nẻo Ngài.'),
(14591, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 44, 19, 'OT', 'Dầu vậy, Ngài đã nghiền nát chúng tôi tại nơi chó rừng, và phủ chúng tôi bằng bóng tối sự chết.'),
(14592, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 44, 20, 'OT', 'Nếu chúng tôi quên danh Đức Chúa Trời chúng tôi, và giơ tay chúng tôi về một thần lạ,'),
(14593, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 44, 21, 'OT', 'Chẳng lẽ Đức Chúa Trời không dò xét điều đó sao? Vì chính Ngài biết các điều kín nhiệm của lòng.'),
(14594, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 44, 22, 'OT', 'Thật vậy, vì Ngài mà chúng tôi bị giết mỗi ngày, bị kể như những chiên để làm của lễ sát tế.'),
(14595, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 44, 23, 'OT', 'Hỡi Chúa, hãy thức dậy! Vì sao Ngài còn ngủ? Hãy chỗi dậy, chớ bỏ chúng tôi mãi mãi.'),
(14596, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 44, 24, 'OT', 'Cớ sao Ngài giấu mặt đi, quên nỗi khốn khổ và sự áp bức của chúng tôi?'),
(14597, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 44, 25, 'OT', 'Vì linh hồn chúng tôi đã cúi xuống bụi đất; bụng chúng tôi dính chặt vào mặt đất.'),
(14598, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 44, 26, 'OT', 'Xin hãy chỗi dậy, giúp đỡ chúng tôi, và vì cớ lòng nhân từ Ngài mà chuộc chúng tôi.'),
(14599, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 45, 1, 'OT', 'Dâng cho người chỉ huy, trên nền nhạc Shoshannim, cho các con của Korah, một bài học, một bài ca về tình yêu. Lòng tôi nảy ra điều tốt lành; tôi nói về những việc tôi làm cho vua; lưỡi tôi như ngòi bút sắc sảo của một văn sĩ.'),
(14600, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 45, 2, 'OT', 'Ngài đẹp hơn mọi con trai loài người; ân sủng được đổ ra nơi môi Ngài; nên Đức Chúa Trời đã ban phước cho Ngài mãi mãi.'),
(14601, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 45, 3, 'OT', 'Hỡi đấng anh hùng, hãy đeo gươm nơi hông ngươi, oai phong ngươi và vẻ vang ngươi.'),
(14602, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 45, 4, 'OT', 'Hãy vì lẽ thật, sự khiêm nhường và sự công bình mà tiến ra oai nghi, cỡi xe thắng trận; tay phải ngươi sẽ dạy cho ngươi những điều đáng sợ.'),
(14603, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 45, 5, 'OT', 'Các mũi tên của ngươi sắc nhọn, các dân đổ xuống dưới ngươi; chúng ngã xuống ngay trong lòng kẻ thù vua.'),
(14604, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 45, 6, 'OT', 'Ngôi báu của Đức Chúa Trời còn đời đời vô tận; Scepter cai trị của Ngài là cây trượng công bình.'),
(14605, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 45, 7, 'OT', 'Chúa yêu điều công chính và ghét điều gian ác; bởi vậy Đức Chúa Trời, là Đức Chúa Trời của Chúa, đã xức dầu cho Chúa bằng dầu vui vẻ hơn các đồng bạn của Chúa.'),
(14606, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 45, 8, 'OT', 'Các áo xức mùi thơm, hương lai, và hoàng liên; từ lâu đài ngà, các nhạc cụ dây làm vui vẻ ngươi.'),
(14607, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 45, 9, 'OT', 'Các con gái các vua ở trong những người được Ngài tôn trọng; hoàng hậu đứng bên phải Ngài, đeo vàng Ô-phir.'),
(14608, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 45, 10, 'OT', 'Hỡi con gái, hãy nghe và hãy nhìn, hãy nghiêng tai ngươi; khá quên dân ngươi và nhà cha ngươi;'),
(14609, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 45, 11, 'OT', 'Thì hoàng đế sẽ yêu vẻ đẹp của nàng; vì Ngài là Chúa ngươi, hãy cúi lạy Ngài.'),
(14610, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 45, 12, 'OT', 'Con gái Ty-rơ sẽ nài xin ơn mặt con, người giàu có nhất trong dân sẽ mang lễ vật đến.'),
(14611, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 45, 13, 'OT', 'Công chúa ở trong cung điện rất vinh hiển; y phục nàng dệt bằng vàng.'),
(14612, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 45, 14, 'OT', 'Các nàng đi theo sau nàng, những người bạn gái của nàng, được dẫn đến cho vua; nàng được mang đến cùng các hoa văn thêu tay.'),
(14613, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 45, 15, 'OT', 'Chúng sẽ được dẫn dắt trong niềm vui và sự hân hoan, bước vào đền của vua.'),
(14614, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 45, 16, 'OT', 'Thay vì tổ tiên ngươi sẽ có các con trai ngươi; ngươi sẽ đặt chúng nó làm quan trưởng khắp đất.'),
(14615, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 45, 17, 'OT', 'Tôi sẽ nhắc đến danh Ngài qua mọi thế hệ; vì vậy các dân tộc sẽ ca ngợi Ngài đời đời mãi mãi.'),
(14616, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 46, 1, 'OT', 'Đức Chúa Trời là nơi nương náu và sức mạnh của chúng tôi, là sự giúp đỡ sẵn sàng trong cơn hoạn nạn.'),
(14617, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 46, 2, 'OT', 'Vì vậy, chúng tôi sẽ không sợ, dù đất có đổi dời, hay các núi có lay động giữa lòng biển.'),
(14618, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 46, 3, 'OT', 'Dù nước biển gào thét và sôi sục, các núi rúng động vì kiêu hãnh của nó.'),
(14619, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 46, 4, 'OT', 'Có một con sông và các nhánh nước của nó làm cho thành Đức Chúa Trời vui vẻ, là nơi thánh của đền tạm Đấng Chí Cao.'),
(14620, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 46, 5, 'OT', 'Đức Chúa Trời ở giữa thành ấy, nên thành ấy sẽ không bị rúng động; Đức Chúa Trời sẽ giúp đỡ nó ngay khi hừng đông.'),
(14621, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 46, 6, 'OT', 'Các dân náo loạn, các nước đổ gục; Đức Chúa Trời phát tiếng, đất bèn tan chảy.'),
(14622, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 46, 7, 'OT', 'Đức Giê-hô-va vạn quân ở cùng chúng ta; Đức Chúa Trời Gia-cốp là nơi nương náu của chúng ta.'),
(14623, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 46, 8, 'OT', 'Hãy đến xem các công việc của Đức Giê-hô-va, những điều Ngài đã đặt sự hoang vu trên đất.'),
(14624, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 46, 9, 'OT', 'Làm cho các cuộc chiến tranh phải ngừng đến tận cùng đất, bẻ gãy cung, chặt ngọn giáo, và đốt các xe nơi lửa.'),
(14625, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 46, 10, 'OT', 'Hãy dừng lại và biết rằng Ta là Đức Chúa Trời; Ta sẽ được tôn cao giữa các nước, Ta sẽ được tôn cao trên đất.'),
(14626, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 46, 11, 'OT', 'Đức Giê-hô-va vạn quân ở cùng chúng tôi; Đức Chúa Trời Gia-cốp là nơi nương náu cho chúng tôi.'),
(14627, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 47, 1, 'OT', 'Dân các nước, hãy vỗ tay; hãy reo mừng cho Đức Chúa Trời bằng tiếng reo vui.'),
(14628, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 47, 2, 'OT', 'Vì Đức Giê-hô-va Chí Cao thật đáng kính sợ, là Vua lớn trên khắp cả đất.'),
(14629, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 47, 3, 'OT', 'Ngài khiến các dân phục dưới chúng tôi, và các nước phục dưới chân chúng tôi.'),
(14630, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 47, 4, 'OT', 'Ngài sẽ chọn phần cơ nghiệp chúng tôi, sự vinh hiển của Gia-cốp mà Ngài yêu dấu.'),
(14631, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 47, 5, 'OT', 'Đức Chúa Trời ngự lên với tiếng reo vang, Đức Giê-hô-va thăng thiên với tiếng kèn.'),
(14632, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 47, 6, 'OT', 'Hãy hát ngợi khen Đức Chúa Trời, khá hát đi; Hãy hát ngợi khen Vua chúng ta, khá hát đi;'),
(14633, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 47, 7, 'OT', 'Vì Đức Chúa Trời là Vua của cả đất; hãy hát bài thông sáng.'),
(14634, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 47, 8, 'OT', 'Đức Chúa Trời đã trị vì làm vua trên các dân tộc; Đức Chúa Trời ngồi trên ngôi thánh của Ngài.'),
(14635, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 47, 9, 'OT', 'Các thủ lĩnh của các dân tộc nhóm lại thành dân Đức Chúa Trời của Aùp-ra-ham; vì các cái khiên của đất đều thuộc về Đức Chúa Trời, Ngài được tôn làm cực cao.'),
(14636, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 48, 1, 'OT', 'Một bài ca, một bài thơ của con cháu Cô-rách: Đức Giê-hô-va là lớn và rất đáng được ngợi khen trong thành của Đức Chúa Trời chúng ta, trên núi thánh Ngài.'),
(14637, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 48, 2, 'OT', 'Núi Si-ôn, đẹp đẽ về hình thế, là niềm vui vẻ của cả thế gian, nằm về phía bắc, là thành của Vua cao cả.'),
(14638, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 48, 3, 'OT', 'Đức Chúa Trời đã tỏ mình ra là nơi nương náu bền vững trong các đền của thành ấy.'),
(14639, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 48, 4, 'OT', 'Vì kìa, các vua nhóm họp, cùng nhau tiến qua.'),
(14640, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 48, 5, 'OT', 'Chúng thấy vậy liền kinh hãi, sửng sốt và vội vàng chạy trốn.'),
(14641, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 48, 6, 'OT', 'Sự run rẩy bắt lấy chúng tại đó, cơn đau đớn như một người đàn bà sinh đẻ.'),
(14642, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 48, 7, 'OT', 'Đức Giê-hô-va dùng gió đông đánh bể các tàu Ta-rê-si.'),
(14643, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 48, 8, 'OT', 'Như điều chúng tôi đã nghe, thì nay chúng tôi đã thấy, trong thành của Đức Giê-hô-va vạn quân, trong thành của Đức Chúa Trời chúng tôi; Đức Chúa Trời làm cho thành ấy vững bền mãi mãi.'),
(14644, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 48, 9, 'OT', 'Hỡi Đức Chúa Trời, chúng tôi đã suy nghĩ về sự nhân từ của Ngài trong đền thờ Ngài.'),
(14645, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 48, 10, 'OT', 'Hỡi Đức Chúa Trời, danh Ngài thể nào thì sự ngợi khen Ngài cũng như vậy đến các đầu cùng đất; tay phải Ngài đầy dẫy sự công bình.'),
(14646, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 48, 11, 'OT', 'Nguyện núi Si-ôn vui mừng, các con gái Giu-đa mừng rỡ vì cớ các sự đoán xét của Đức Giê-hô-va.'),
(14647, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 48, 12, 'OT', 'Hãy đi vòng quanh Si-ôn, hãy đi quanh thành ấy, hãy đếm các tháp của nó.'),
(14648, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 48, 13, 'OT', 'Hãy để lòng vào sức mạnh của nó, hãy đi quanh các pháo đài nó, để các ngươi có thể thuật lại cho thế hệ tương lai.'),
(14649, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 48, 14, 'OT', 'Vì Đức Chúa Trời nầy là Đức Chúa Trời chúng tôi đời đời mãi mãi; Ngài sẽ dẫn chúng tôi cho đến chết.'),
(14650, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 49, 1, 'OT', 'Hỡi các dân, hãy nghe điều nầy; hỡi mọi người sống trên đất, hãy lắng tai nghe,'),
(14651, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 49, 2, 'OT', 'Cả con cái loài người, cả con cái người đàn ông, cùng nhau kẻ giàu và người nghèo.'),
(14652, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 49, 3, 'OT', 'Miệng tôi sẽ nói những lời khôn ngoan, sự suy gẫm trong lòng tôi sẽ là những điều thông sáng.'),
(14653, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 49, 4, 'OT', 'Tôi sẽ nghiêng tai lắng nghe lời châm ngôn; tôi sẽ dùng đàn cầm bầy lên câu đố của tôi.'),
(14654, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 49, 5, 'OT', 'Tại sao tôi phải sợ trong những ngày tai họa, khi tội ác của những kẻ theo sau tôi vây hãm tôi?'),
(14655, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 49, 6, 'OT', 'Những kẻ cậy vào tài sản mình, và khoe mình giàu có dồi dào.'),
(14656, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 49, 7, 'OT', 'Người anh em không thể chuộc được người, cũng chẳng thể dâng cho Đức Chúa Trời giá chuộc cho người.'),
(14657, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 49, 8, 'OT', 'Vì rất đắt giá việc chuộc mạng sống họ, nên phải thôi mãi mãi.'),
(14658, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 49, 9, 'OT', 'Người sẽ sống mãi mãi đời đời, chẳng thấy sự hư nát.'),
(14659, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 49, 10, 'OT', 'Vì người thấy người khôn ngoan chết, cả kẻ ngu dại và kẻ dốt nát cũng tiêu vong, và để lại tài sản mình cho người khác.'),
(14660, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 49, 11, 'OT', 'Những người thân họ, nhà họ sẽ còn đời đời; nơi ở họ qua nhiều thế hệ; họ đặt tên mình trên những vùng đất của họ.'),
(14661, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 49, 12, 'OT', 'Người ta dù được tôn trọng cũng không còn mãi; họ được ví như loài thú vật phải chết mất.'),
(14662, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 49, 13, 'OT', 'Đây là con đường chúng theo, thật là điều ngu dại của chúng; và những kẻ theo sau chúng sẽ ưng thuận lời nói của chúng.'),
(14663, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 49, 14, 'OT', 'Như bầy chiên, chúng bị định cho âm phủ; sự chết sẽ chăn giữ chúng; người ngay thẳng sẽ thống trị chúng vào buổi sáng, và hình dạng chúng sẽ tiêu tan trong âm phủ, không còn nơi ở nào cho chúng nữa.'),
(14664, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 49, 15, 'OT', 'Nhưng Đức Chúa Trời sẽ cứu chuộc linh hồn tôi khỏi tay âm phủ, vì Ngài sẽ tiếp rước tôi.'),
(14665, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 49, 16, 'OT', 'Đừng sợ khi một người trở nên giàu có, khi vinh hiển trong nhà người ấy ngày càng gia tăng.'),
(14666, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 49, 17, 'OT', 'Vì người chết không mang theo được gì, vinh hiển người cũng không theo người xuống mồ mả.'),
(14667, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 49, 18, 'OT', 'Vì linh hồn người đó sẽ chúc phước cho mình khi còn sống, và người ta sẽ khen ngợi ngươi khi ngươi làm điều tốt cho mình.'),
(14668, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 49, 19, 'OT', 'Người ấy sẽ về cùng dòng dõi tổ tiên mình, đến mãi mãi không thấy ánh sáng.'),
(14669, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 49, 20, 'OT', 'Người ta được tôn trọng mà không hiểu biết, được ví như loài vật phải chết mất.'),
(14670, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 50, 1, 'OT', 'Một bài thơ của A-sáp: Đức Chúa Trời, là Đức Giê-hô-va, đã phán và kêu gọi đất, từ nơi mặt trời mọc cho đến nơi nó lặn.'),
(14671, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 50, 2, 'OT', 'Từ Si-ôn, nơi trọn vẹn vẻ đẹp, Đức Chúa Trời đã tỏa sáng.'),
(14672, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 50, 3, 'OT', 'Đức Chúa Trời chúng tôi đến, Ngài không nín lặng; trước mặt Ngài có lửa thiêu đốt, và chung quanh Ngài bão tố dữ dội.'),
(14673, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 50, 4, 'OT', 'Đức Giê-hô-va kêu các từng trời từ trên cao, và đất dưới để xét đoán dân sự Ngài.'),
(14674, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 50, 5, 'OT', 'Hãy nhóm lại cho ta các người thánh của ta, là những kẻ đã lập giao ước ta trên của lễ thiêu.'),
(14675, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 50, 6, 'OT', 'Các từng trời loan truyền sự công bình của Ngài, vì Đức Chúa Trời là Đấng xét đoán, Hô-i.'),
(14676, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 50, 7, 'OT', 'Hỡi dân ta, hãy nghe ta sẽ nói; hỡi Y-sơ-ra-ên, ta sẽ làm chứng nghịch ngươi: Ta là Đức Chúa Trời, tức là Đức Chúa Trời ngươi.'),
(14677, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 50, 8, 'OT', 'Ta sẽ không quở trách ngươi vì các lễ vật thiêu của ngươi, cũng không khiển trách ngươi vì những lễ thiêu luôn ở trước mặt ta.'),
(14678, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 50, 9, 'OT', 'Ta sẽ không nhận bò đực từ nhà ngươi, cũng chẳng lấy dê đực từ chuồng ngươi.'),
(14679, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 50, 10, 'OT', 'Vì mọi thú rừng đều thuộc về Ta, các bầy vật trên ngàn ngọn núi cũng vậy.'),
(14680, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 50, 11, 'OT', 'Ta biết mọi chim trời, và mọi loài vật chạy nhảy trong đồng cỏ đều thuộc về Ta.'),
(14681, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 50, 12, 'OT', 'Nếu ta đói, ta sẽ không nói với ngươi; vì trái đất và đầy dẫy của nó đều thuộc về ta.'),
(14682, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 50, 13, 'OT', 'Ta há ăn thịt bò tót, hay uống huyết chiên đực sao!'),
(14683, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 50, 14, 'OT', 'Hãy dâng cho Đức Chúa Trời của lễ cảm tạ, và trả lễ hứa nguyện ngươi cho Đấng Chí Cao.'),
(14684, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 50, 15, 'OT', 'Trong ngày hoạn nạn, hãy kêu cầu Ta; Ta sẽ cứu ngươi, và ngươi sẽ tôn vinh Ta.'),
(14685, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 50, 16, 'OT', 'Nhưng Đức Chúa Trời phán cùng kẻ ác rằng: Ngươi đã làm gì mà thuật lại các mạng lịnh ta, và lấy giao ước ta đặt trên môi ngươi?'),
(14686, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 50, 17, 'OT', 'Còn ngươi, ngươi ghét sự sửa dạy, và ném các lời ta ra phía sau lưng ngươi.'),
(14687, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 50, 18, 'OT', 'Nếu ngươi thấy kẻ trộm, thì ngươi vội vàng chạy theo cùng nó, và ngươi đã chia phần mình cùng kẻ phạm tội tà dâm.'),
(14688, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 50, 19, 'OT', 'Miệng ngươi buông ra điều ác, lưỡi ngươi nối kết sự gian dối.'),
(14689, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 50, 20, 'OT', 'Ngươi ngồi nói chuyện nghịch anh em mình, gièm chê con trai của mẹ ngươi.'),
(14690, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 50, 21, 'OT', 'Ngươi đã làm những điều nầy, ta nín lặng; ngươi tưởng Ta sẽ giống như ngươi; Ta sẽ quở trách ngươi, đặt các điều đó ra trước mắt ngươi.'),
(14691, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 50, 22, 'OT', 'Hỡi những kẻ quên Đức Chúa Trời, hãy suy nghĩ điều nầy, e khi ta xé nát, chẳng ai cứu giúp.'),
(14692, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 50, 23, 'OT', 'Đức Chúa Trời phán: Kẻ nào dâng của lễ cảm tạ sẽ tôn vinh Ta; còn ai định rõ con đường Ta sẽ cho người ấy thấy sự cứu rỗi của Đức Chúa Trời.'),
(14693, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 51, 1, 'OT', 'Đức Chúa Trời ôi, xin thương xót tôi theo sự nhân từ của Ngài; xin xoá các sự phạm tội tôi theo lượng lớn lòng thương xót của Ngài.'),
(14694, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 51, 2, 'OT', 'Hãy lấy nước rửa tôi cho sạch khỏi tội ác tôi, và làm tôi được trong sạch về tội lỗi tôi.'),
(14695, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 51, 3, 'OT', 'Vì tôi biết các sự phạm tội tôi, và tội lỗi tôi luôn ở trước mặt tôi.'),
(14696, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 51, 4, 'OT', 'Chỉ cùng một mình Ngài mà thôi, tôi đã phạm tội, và làm điều ác trước mặt Ngài, hầu cho Ngài được xưng công bình trong lời phán của Ngài, được tỏ ra thanh sạch trong khi Ngài xét đoán.'),
(14697, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 51, 5, 'OT', 'Nầy, tôi đã được hoài thai trong sự gian ác, và mẹ tôi đã mang thai tôi trong tội lỗi.'),
(14698, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 51, 6, 'OT', 'Nầy, Ngài ưa sự thật trong lòng sâu thẳm; nơi kín nhiệm, Ngài sẽ dạy tôi sự khôn ngoan.'),
(14699, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 51, 7, 'OT', 'Xin hãy tẩy sạch tôi bằng cây hương thảo, thì tôi sẽ được tinh sạch; xin hãy rửa tôi, thì tôi sẽ trắng hơn tuyết.'),
(14700, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 51, 8, 'OT', 'Xin cho con được nghe sự vui mừng hoan hỷ, hầu các xương cốt mà Đức Giê-hô-va đã nghiền nát được hớn hở vui mừng.'),
(14701, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 51, 9, 'OT', 'Xin giấu mặt khỏi các tội lỗi tôi, và xóa sạch mọi sự gian ác tôi.'),
(14702, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 51, 10, 'OT', 'Lòng trong sạch, xin hãy tạo nên cho tôi, hỡi Đức Chúa Trời, và làm mới lại trong tôi một thần linh ngay thẳng.'),
(14703, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 51, 11, 'OT', 'Xin chớ ném tôi ra khỏi trước mặt Ngài, và Thánh Linh của Ngài xin chớ cất khỏi tôi.'),
(14704, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 51, 12, 'OT', 'Xin hãy phục hồi cho tôi sự vui mừng về sự cứu rỗi của Ngài, và lấy thần linh quảng đại mà nâng đỡ tôi.'),
(14705, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 51, 13, 'OT', 'Tôi sẽ dạy các kẻ phạm tội đường lối Ngài, và những kẻ có tội sẽ trở lại cùng Ngài.'),
(14706, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 51, 14, 'OT', 'Lạy Đức Chúa Trời, là Đức Chúa Trời về sự cứu rỗi tôi, xin giải cứu tôi khỏi tội đổ huyết; thì lưỡi tôi sẽ reo mừng vì sự công bình của Ngài.'),
(14707, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 51, 15, 'OT', 'Lạy Đức Giê-hô-va, xin mở mang môi con ra, và miệng con sẽ rao truyền sự ngợi khen Ngài.'),
(14708, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 51, 16, 'OT', 'Vì Ngài không ưa thích của lễ, nếu không thì tôi đã dâng; của lễ thiêu cũng không làm Ngài vừa lòng.'),
(14709, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 51, 17, 'OT', 'Các lễ vật của Đức Chúa Trời là tinh thần bị đập tan; một tấm lòng bị đập tan và bị nghiền nát, Đức Chúa Trời không khinh dể.'),
(14710, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 51, 18, 'OT', 'Xin Đức Giê-hô-va làm lành cho Si-ôn theo ý tốt Ngài; xin xây lại các vách thành Giê-ru-sa-lem.'),
(14711, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 51, 19, 'OT', 'Bấy giờ Ngài sẽ ưa thích các lễ vật công bình, lễ thiêu và của lễ toàn thiêu; bấy giờ các con bò đực sẽ dâng lên bàn thờ Ngài.'),
(14712, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 52, 1, 'OT', 'Hỡi người mạnh mẽ, sao ngươi tự khoe về điều ác? Sự nhân từ của Đức Chúa Trời luôn có suốt cả ngày.'),
(14713, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 52, 2, 'OT', 'Lưỡi ngươi toan bày điều ác; lưỡi ngươi làm điều giả dối như dao cạo bén.'),
(14714, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 52, 3, 'OT', 'Ngươi yêu điều ác hơn điều lành, yêu sự dối trá hơn lời nói công bình.'),
(14715, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 52, 4, 'OT', 'Ngươi đã yêu mọi lời nuốt trôi, hỡi lưỡi gian dối.'),
(14716, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 52, 5, 'OT', 'Đức Chúa Trời cũng sẽ hủy diệt ngươi mãi mãi, bắt ngươi, nhổ ngươi khỏi trại ngươi, và gốc rễ ngươi khỏi đất kẻ sống. Hết.'),
(14717, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 52, 6, 'OT', 'Người công bình sẽ thấy và run sợ, và sẽ cười người đó.'),
(14718, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 52, 7, 'OT', 'Kìa, người ấy không đặt Đức Chúa Trời làm sức lực mình, mà tin cậy nơi sự giàu có rất nhiều của mình, và dựa vào điều ác mình để được vững chắc.'),
(14719, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 52, 8, 'OT', 'Còn tôi, tôi như cây ô-liu xanh tươi trong nhà Đức Chúa Trời; tôi tin cậy nơi sự nhân từ của Đức Chúa Trời đời đời mãi mãi.'),
(14720, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 52, 9, 'OT', 'Tôi sẽ cảm tạ Đức Giê-hô-va đời đời, vì Ngài đã làm điều đó; tôi sẽ trông đợi danh Ngài, vì điều đó là tốt lành trước mặt các thánh nhân của Ngài.'),
(14721, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 53, 1, 'OT', 'Đối với người chỉ huy: theo thể điệu "Machalath"; một bài thơ suy gẫm của Đa-vít. Kẻ ngu dại nói trong lòng rằng: Chẳng có Đức Chúa Trời. Chúng nó đã hư hỏng, đã làm điều gớm ghiếc; chẳng có ai làm điều lành.'),
(14722, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 53, 2, 'OT', 'Đức Chúa Trời từ các từng trời ngó xuống trên con loài người, đặng xem thử có ai hiểu biết, tìm kiếm Đức Chúa Trời chăng.'),
(14723, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 53, 3, 'OT', 'Tất cả đều lui lại, cùng nhau trở nên ô uế; chẳng ai làm điều lành, không một ai.'),
(14724, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 53, 4, 'OT', 'Các kẻ làm ác há chẳng biết sao? Chúng nó ăn dân ta như ăn bánh, và chẳng hề kêu cầu Đức Chúa Trời.'),
(14725, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 53, 5, 'OT', 'Nơi chẳng có sự kinh khiếp, chúng nó kinh hãi; vì Đức Chúa Trời làm tan xương kẻ thù nghịch ngươi; ngươi làm chúng nó hổ thẹan, vì Đức Chúa Trời từ bỏ chúng nó.'),
(14726, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 53, 6, 'OT', 'Ôi! chớ chi sự cứu rỗi cho Y-sơ-ra-ên xuất phát từ Si-ôn! Khi Đức Chúa Trời đem về các phu tù của dân Ngài, Gia-cốp sẽ hớn hở, Y-sơ-ra-ên sẽ vui mừng.'),
(14727, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 54, 1, 'OT', 'Đức Chúa Trời ôi, xin lấy danh Ngài mà cứu tôi, và lấy quyền năng Ngài mà xét đoán tôi.'),
(14728, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 54, 2, 'OT', 'Hỡi Đức Chúa Trời, xin hãy nghe lời cầu nguyện tôi, xin lắng tai nghe các lời của miệng tôi, khi những người Xi-phi đến nói với Sau-lơ rằng: "Đa-vít đang ẩn náu giữa chúng tôi."'),
(14729, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 54, 3, 'OT', 'Vì những kẻ ngoại đã nổi lên nghịch cùng tôi, và những kẻ hung bạo tìm hại mạng sống tôi; chúng nó không đặt Đức Chúa Trời trước mặt mình.'),
(14730, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 54, 4, 'OT', 'Nầy, Đức Chúa Trời là Đấng giúp đỡ tôi, Chúa là Đấng nâng đỡ linh hồn tôi.'),
(14731, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 54, 5, 'OT', 'Ác sẽ trở lại cho những kẻ bắt bớ tôi; nhờ sự thật của Đức Giê-hô-va, xin diệt chúng nó đi.'),
(14732, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 54, 6, 'OT', 'Tôi sẽ dâng cho Ngài của lễ tình nguyện; hỡi Đức Giê-hô-va, tôi sẽ cảm tạ danh Ngài, vì Ngài tốt lành.'),
(14733, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 54, 7, 'OT', 'Vì Ngài đã giải cứu tôi khỏi mọi cơn nguy khốn; và mắt tôi đã thấy điều xảy ra cho kẻ thù nghịch tôi.'),
(14734, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 55, 1, 'OT', 'Lạy Đức Chúa Trời, xin hãy lắng nghe lời cầu nguyện tôi; chớ ẩn mình khỏi nghe lời khẩn nài tôi.'),
(14735, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 55, 2, 'OT', 'Xin hãy lắng nghe tôi và đáp lời tôi; tôi bồn chồn lo lắng, than vãn và bối rối.'),
(14736, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 55, 3, 'OT', 'Bởi tiếng kẻ thù, bởi sự hà hiếp của kẻ ác; vì chúng nó đem điều ác đổ trên tôi, và giận dữ bắt bớ tôi.'),
(14737, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 55, 4, 'OT', 'Lòng tôi bồn chồn trong chính mình tôi, và những sự kinh hoàng của sự chết đã giáng trên tôi.'),
(14738, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 55, 5, 'OT', 'Sự sợ hãi và run rẩy ập xuống trên tôi, và sự kinh hãi bao phủ tôi.'),
(14739, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 55, 6, 'OT', 'Tôi nói: Ôi! chỉ mong tôi có cánh như chim bồ câu, tôi sẽ bay đi và tìm được nơi an nghỉ.'),
(14740, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 55, 7, 'OT', 'Này, tôi sẽ trốn xa, trú ẩn trong đồng vắng.'),
(14741, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 55, 8, 'OT', 'Tôi sẽ vội vàng chạy trốn khỏi gió bão và khỏi cơn cuồng phong.'),
(14742, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 55, 9, 'OT', 'Lạy Đức Giê-hô-va, xin nuốt lấy sự chia rẽ của họ, khiến cho tiếng nói của họ lộn xộn; vì tôi thấy sự bạo lực và tranh chấp trong thành.'),
(14743, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 55, 10, 'OT', 'Ngày và đêm chúng đi vòng quanh các vách thành nó; sự gian ác và điều đau khổ ở giữa lòng nó.'),
(14744, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 55, 11, 'OT', 'Sự gian tà và dối trá ở giữa thành; chúng không rời khỏi phố phường nó.'),
(14745, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 55, 12, 'OT', 'Vì chẳng phải kẻ thù ghét tôi sỉ nhục tôi; nếu vậy, tôi có thể chịu được; cũng chẳng phải kẻ oán tôi ngạo nghễ chống lại tôi; nếu vậy, tôi có thể trốn tránh nó.'),
(14746, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 55, 13, 'OT', 'Nhưng chính ngươi, là người ngang hàng với ta, bạn thân ta, người rất thân thiết ta.'),
(14747, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 55, 14, 'OT', 'Người mà tôi từng thân mật trò chuyện cùng nhau, cùng nhau bước đi trong nhà Đức Chúa Trời với đoàn người hân hoan.'),
(14748, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 55, 15, 'OT', 'Nguyện sự chết thình lình xảy đến chúng nó! Nguyện chúng nó còn sống phải sa xuống âm phủ! Vì sự ác ở nơi chỗ ở chúng nó, ngay giữa lòng chúng nó.'),
(14749, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 55, 16, 'OT', 'Còn tôi, tôi kêu cầu cùng Đức Chúa Trời, và Đức Giê-hô-va sẽ cứu tôi.'),
(14750, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 55, 17, 'OT', 'Buổi chiều, buổi sáng, và giữa trưa, tôi sẽ than vãn và kêu la; Ngài sẽ nghe tiếng tôi.'),
(14751, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 55, 18, 'OT', 'Ngài đã chuộc linh hồn tôi cách bình an khỏi cơn chiến trận chống tôi, vì những kẻ chiến đấu cùng tôi rất đông.'),
(14752, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 55, 19, 'OT', 'Đức Chúa Trời sẽ nghe và đáp trả chúng nó, Đấng hằng ngồi từ xưa xa, Hết sức lâu dài. Chúng nó không biết ăn năn, nên chẳng kính sợ Đức Chúa Trời.'),
(14753, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 55, 20, 'OT', 'Kẻ ấy đã giơ tay ra chống lại những người sống hòa thuận với mình; nó đã làm ô uế giao ước của Ngài.'),
(14754, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 55, 21, 'OT', 'Miệng nó trơn tru như kem sữa, lòng nó lại chứa đầy sự chiến tranh; các lời nó mềm mại hơn dầu, nhưng thực ra là những lưỡi gươm trần.'),
(14755, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 55, 22, 'OT', 'Hãy ném gánh nặng của ngươi trên Đức Giê-hô-va, chính Ngài sẽ nuôi dưỡng ngươi; Ngài sẽ không để người công bình bị rúng động đời đời.'),
(14756, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 55, 23, 'OT', 'Còn như ngươi, Đức Chúa Trời, chính Ngài sẽ khiến chúng nó sa xuống hầm hủy diệt; những kẻ ưa đổ máu và gian dối chẳng sống được đến nửa đời mình. Còn tôi, tôi sẽ tin cậy nơi Ngài.'),
(14757, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 56, 1, 'OT', 'Đức Chúa Trời ôi, xin thương xót tôi, vì người ta muốn nuốt chửng tôi; suốt cả ngày họ chiến đấu và hà hiếp tôi.'),
(14758, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 56, 2, 'OT', 'Trọn ngày những kẻ rình mò tôi tìm nuốt tôi, vì nhiều kẻ chiến đấu cùng tôi cách kiêu ngạo.'),
(14759, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 56, 3, 'OT', 'Trong ngày tôi sợ hãi, tôi sẽ tin cậy nơi Đức Giê-hô-va.'),
(14760, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 56, 4, 'OT', 'Tôi nhờ Đức Chúa Trời mà ngợi khen lời Ngài; tôi tin cậy nơi Đức Chúa Trời, chẳng sợ gì; người xác thịt sẽ làm chi tôi?'),
(14761, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 56, 5, 'OT', 'Cả ngày chúng nó làm cho lời tôi phải đau buồn, mọi ý tưởng của chúng đều toan hại tôi.'),
(14762, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 56, 6, 'OT', 'Chúng nó nhóm lại rình mò, rình theo các bước tôi, vì chúng rình mò mạng sống tôi.'),
(14763, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 56, 7, 'OT', 'Chúng nó sẽ nhờ sự gian ác mà được thoát khỏi sao? Hỡi Đức Chúa Trời, xin hãy nổi giận mà đánh đổ các dân.'),
(14764, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 56, 8, 'OT', 'Ngài đã đếm các bước đi của tôi; xin để nước mắt tôi vào bầu da của Ngài. Nước mắt tôi há chẳng được ghi trong sổ của Ngài sao?'),
(14765, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 56, 9, 'OT', 'Ngày tôi kêu cầu, các kẻ thù tôi sẽ quay lưng chạy trốn; tôi biết điều đó, vì Đức Chúa Trời ở về phía tôi.'),
(14766, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 56, 10, 'OT', 'Tôi nhờ Đức Chúa Trời mà ngợi khen lời Ngài; tôi nhờ Đức Giê-hô-va mà ngợi khen lời Ngài.'),
(14767, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 56, 11, 'OT', 'Tôi đã tin cậy nơi Đức Chúa Trời, tôi sẽ chẳng sợ chi; loài người sẽ làm gì tôi?'),
(14768, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 56, 12, 'OT', 'Hỡi Đức Chúa Trời, những lời hứa nguyện của tôi dành cho Ngài vẫn còn trên tôi; tôi sẽ trả những lời tạ ơn Ngài.'),
(14769, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 56, 13, 'OT', 'Vì Ngài đã giải cứu linh hồn tôi khỏi sự chết; chẳng phải chăng Ngài giữ cho chân tôi khỏi vấp ngã, để tôi đi trước mặt Đức Chúa Trời trong ánh sáng của sự sống?'),
(14770, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 57, 1, 'OT', 'Đức Chúa Trời ôi, xin thương xót tôi, xin thương xót tôi, vì linh hồn tôi nương náu nơi Ngài; dưới bóng các cánh Ngài, tôi lánh mình, cho đến khi cơn họa qua đi.'),
(14771, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 57, 2, 'OT', 'Tôi sẽ kêu cầu cùng Đức Chúa Trời Chí cao, cùng Đức Chúa Trời làm trọn việc nầy cho tôi.'),
(14772, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 57, 3, 'OT', 'Ngài sẽ sai từ các từng trời và cứu tôi; Ngài sẽ làm sỉ nhục kẻ muốn nuốt tôi. Sê-la. Đức Chúa Trời sẽ sai sự nhân từ và sự thật của Ngài.'),
(14773, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 57, 4, 'OT', 'Linh hồn tôi ở giữa các sư tử; tôi nằm giữa những kẻ thổi lửa, con loài người có răng như giáo và tên, lưỡi chúng nó như gươm sắc bén.'),
(14774, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 57, 5, 'OT', 'Hỡi Đức Chúa Trời, nguyện Ngài được tôn cao trên các từng trời; sự vinh hiển Ngài trên khắp đất.'),
(14775, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 57, 6, 'OT', 'Chúng đã giăng lưới cho bước chân tôi, linh hồn tôi sa xuống giữa hầm; chúng đào hố trước mặt tôi, thì chính chúng lại sa vào đó.'),
(14776, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 57, 7, 'OT', 'Lòng tôi vững chắc, Đức Chúa Trời, lòng tôi vững chắc; tôi sẽ hát và gảy đàn.'),
(14777, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 57, 8, 'OT', 'Hỡi vinh hiển ta, hãy thức dậy! Hỡi đờn sắt và đờn cầm, hãy thức dậy! Ta sẽ đánh thức bình minh.'),
(14778, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 57, 9, 'OT', 'Lạy Đức Giê-hô-va, tôi sẽ cảm tạ Ngài giữa các dân; tôi sẽ ca ngợi Ngài giữa các nước.'),
(14779, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 57, 10, 'OT', 'Vì sự nhân từ Ngài cao tới tận trời, Và sự chân thật Ngài tới các từng mây.'),
(14780, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 57, 11, 'OT', 'Hỡi Đức Chúa Trời, xin được tôn cao trên các từng trời; sự vinh hiển Ngài trên khắp đất.'),
(14781, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 58, 1, 'OT', 'Hỡi các quan xét, các ngươi có thật sự nói lời công bình chăng? Các ngươi xét đoán con cái loài người có ngay thẳng chăng?'),
(14782, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 58, 2, 'OT', 'Thật vậy, trong lòng các ngươi làm điều gian ác; trên đất các ngươi dùng tay mình đo lường sự bạo ngược.'),
(14783, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 58, 3, 'OT', 'Kẻ ác quay lưng từ trong lòng mẹ, lạc lối ngay từ khi mới sinh, nói dối ngay từ thuở lọt lòng.'),
(14784, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 58, 4, 'OT', 'Cơn thịnh nộ của chúng giống như cơn thịnh nộ của rắn; như loài rắn điếc bịt tai mình.'),
(14785, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 58, 5, 'OT', 'Chúng không nghe tiếng người rỉ tai, dù người rỉ tai có khéo léo đến đâu.'),
(14786, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 58, 6, 'OT', 'Lạy Đức Chúa Trời, xin hãy đập bể răng chúng nó trong miệng; lạy Đức Giê-hô-va, xin hãy bẻ gãy nanh của những sư tử con.'),
(14787, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 58, 7, 'OT', 'Nguyện chúng tan đi như nước chảy trôi! Khi chúng ra oai, nguyện những mũi tên của chúng như bị gãy mất!'),
(14788, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 58, 8, 'OT', 'Như ốc sên tan chảy, nó sẽ đi qua; như thai chết của người đàn bà, chẳng bao giờ thấy mặt trời.'),
(14789, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 58, 9, 'OT', 'Trước khi các vạc của các ngươi nhận biết được gai, Đức Giê-hô-va sẽ cuốn chúng đi như thể còn sống, như thể đã cháy.'),
(14790, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 58, 10, 'OT', 'Người công bình sẽ vui mừng khi thấy báo phục; người sẽ rửa chân mình trong huyết kẻ ác.'),
(14791, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 58, 11, 'OT', 'Người ta sẽ nói: Quả thật có phần thưởng cho người công bình; quả thật có Đức Chúa Trời xét xử trên đất.'),
(14792, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 59, 1, 'OT', 'Đức Chúa Trời ôi, xin cứu tôi khỏi kẻ thù tôi, bảo vệ tôi khỏi những kẻ dấy lên chống tôi.'),
(14793, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 59, 2, 'OT', 'Xin hãy giải cứu tôi khỏi những kẻ làm điều ác, và cứu tôi khỏi những người đầy máu.'),
(14794, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 59, 3, 'OT', 'Vì kìa, chúng nó rình rập hại mạng sống tôi; những người mạnh bạo rình đánh tôi; chẳng phải vì sự vi phạm tôi, cũng chẳng phải vì tội lỗi tôi, Đức Giê-hô-va ôi.'),
(14795, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 59, 4, 'OT', 'Mặc dù tôi không phạm tội, chúng vội chạy đến và tấn công tôi; xin Đấng hãy thức dậy đón tiếp tôi và nhìn xem.'),
(14796, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 59, 5, 'OT', 'Hỡi Đức Giê-hô-va Đức Chúa Trời vạn quân, là Đức Chúa Trời của Y-sơ-ra-ên, xin hãy chỗi dậy để thăm viếng muôn dân; chớ dung tha mọi kẻ phản bội gian ác.'),
(14797, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 59, 6, 'OT', 'Chúng trở lại buổi chiều, gầm vang như chó, và đi vòng quanh thành.'),
(14798, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 59, 7, 'OT', 'Này, chúng sẽ tuôn ra nơi miệng mình những lời như gươm, và nơi môi chúng nó là những lưỡi gươm; vì chúng nói: "Ai sẽ nghe thấy?"'),
(14799, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 59, 8, 'OT', 'Nhưng, Đức Giê-hô-va, Ngài sẽ chế nhạo chúng nó, sẽ cười nhạo mọi dân tộc.'),
(14800, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 59, 9, 'OT', 'Sức lực tôi, tôi sẽ ngửa trông Đức Giê-hô-va; vì Đức Chúa Trời là nơi ẩn náu cao của tôi.'),
(14801, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 59, 10, 'OT', 'Đức Chúa Trời sẽ lấy sự nhân từ của Ngài mà đi trước tôi; Đức Chúa Trời sẽ cho tôi thấy điều ác của những kẻ thù nghịch tôi.'),
(14802, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 59, 11, 'OT', 'Đức Giê-hô-va là cái khiên của chúng tôi, xin đừng giết chúng nó, e rằng dân sự tôi quên mất; xin hãy dùng quyền năng Ngài mà lay động và đánh đổ chúng nó.'),
(14803, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 59, 12, 'OT', 'Vì tội nơi miệng chúng nó, vì lời trên môi chúng nó, nguyện chúng nó bị mắc trong sự kiêu ngạo mình, và vì những lời nguyền rủa và dối trá mà chúng nó nói ra!'),
(14804, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 59, 13, 'OT', 'Xin Đức Giê-hô-va nổi giận tiêu diệt chúng nó, tiêu diệt đi, hầu cho chúng nó không còn nữa; và cho chúng nó biết rằng Đức Chúa Trời cai trị nơi Gia-cốp cho đến tận cùng trái đất.'),
(14805, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 59, 14, 'OT', 'Chúng sẽ trở lại buổi chiều, gây ồn ào như chó, và đi vòng quanh thành.'),
(14806, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 59, 15, 'OT', 'Chúng đi lang thang để ăn; nếu không được no, thì sẽ ở lại suốt đêm.'),
(14807, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 59, 16, 'OT', 'Nhưng tôi sẽ hát về sức mạnh Ngài, Sáng sớm tôi sẽ reo vui về sự nhân từ Ngài, Vì Ngài đã là nơi nương náu cao cả cho tôi, Và là nơi ẩn náu tôi trong ngày hoạn nạn.'),
(14808, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 59, 17, 'OT', 'Lực lượng tôi, tôi sẽ hát ngợi khen Ngài; vì Đức Chúa Trời là đồn lũy của tôi, Đức Chúa Trời là sự nhân từ của tôi.'),
(14809, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 60, 1, 'OT', 'Lạy Đức Chúa Trời, Ngài đã từ bỏ chúng tôi, làm tan tác chúng tôi; Ngài nổi giận, xin trở lại cùng chúng tôi.'),
(14810, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 60, 2, 'OT', 'Ngài khiến đất rúng động, làm cho nó nứt ra; hãy hàn đắp các chỗ nứt của nó, vì nó đang lay động.'),
(14811, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 60, 3, 'OT', 'Ngài đã cho dân Ngài thấy sự khốn khổ, khiến chúng tôi uống một thứ rượu xây xẩm.'),
(14812, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 60, 4, 'OT', 'Ngài đã ban cho những kẻ kính sợ Ngài một ngọn cờ, để vì lẽ thật mà phất lên.'),
(14813, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 60, 5, 'OT', 'Hầu cho những người thân yêu của Ngài được giải cứu, xin hãy dùng tay phải Ngài mà cứu giúp và nhậm lời chúng tôi.'),
(14814, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 60, 6, 'OT', 'Đức Chúa Trời đã phán trong thánh địa Ngài: Ta sẽ hớn hở, Ta sẽ chia phần Si-chem và đo trũng Su-cốt.'),
(14815, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 60, 7, 'OT', 'Ga-la-át thuộc về ta, Ma-na-se cũng thuộc về ta; Eùp-ra-im là sức mạnh của đầu ta; Giu-đa là cây quyền bính của ta.'),
(14816, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 60, 8, 'OT', 'Mô-áp là cái chậu rửa chân ta; trên Ê-đôm ta ném dép ta; hỡi Phi-li-tin, hãy hò reo vì cớ ta.'),
(14817, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 60, 9, 'OT', 'Ai sẽ dẫn tôi vào thành có vách thành? Ai sẽ dẫn tôi đến Ê-đôm?'),
(14818, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 60, 10, 'OT', 'Hỡi Đức Chúa Trời, chẳng phải Ngài đã từ bỏ chúng tôi sao? Hỡi Đức Chúa Trời, Ngài không ra trận cùng đoàn quân chúng tôi nữa.'),
(14819, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 60, 11, 'OT', 'Xin Đức Giê-hô-va ban cho chúng tôi sự giúp đỡ trong cơn gian truân; vì sự cứu giúp của loài người là vô ích.'),
(14820, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 60, 12, 'OT', 'Nhờ Đức Chúa Trời chúng tôi sẽ làm được quyền năng; chính Ngài sẽ đạp giày kẻ thù nghịch chúng tôi.'),
(14821, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 61, 1, 'OT', 'Hỡi Đức Chúa Trời, xin nghe tiếng kêu than của tôi; xin lắng nghe lời cầu nguyện tôi.'),
(14822, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 61, 2, 'OT', 'Từ cuối đất tôi kêu cầu cùng Đức Giê-hô-va khi lòng tôi mệt mỏi; xin dẫn tôi đến hòn đá cao hơn tôi.'),
(14823, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 61, 3, 'OT', 'Vì Ngài đã là nơi nương náu cho tôi, một tháp đài quyền năng tránh khỏi kẻ thù.'),
(14824, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 61, 4, 'OT', 'Tôi sẽ nương nhờ trong trại Ngài trọn đời lâu dài, tôi sẽ ẩn mình dưới bóng các cánh Ngài.'),
(14825, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 61, 5, 'OT', 'Hỡi Đức Chúa Trời, chính Ngài đã nghe các lời hứa nguyện của tôi; Ngài đã ban cho những người kính sợ danh Ngài được hưởng cơ nghiệp.'),
(14826, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 61, 6, 'OT', 'Hãy gia tăng thêm những ngày cho đời vua; các năm của người sẽ như nhiều đời.'),
(14827, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 61, 7, 'OT', 'Người sẽ sống lâu dài trước mặt Đức Chúa Trời; nguyện sự nhân từ và sự thành thật gìn giữ người.'),
(14828, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 61, 8, 'OT', 'Vâng, tôi sẽ hát ngợi khen danh Ngài đời đời, để trọn các lời hứa nguyện tôi từng ngày.'),
(14829, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 62, 1, 'OT', 'Chỉ mình Đức Chúa Trời, linh hồn tôi mới được yên lặng; từ Ngài, sự cứu rỗi tôi.'),
(14830, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 62, 2, 'OT', 'Chỉ mình Ngài là hòn đá tôi, sự cứu rỗi tôi, nơi nương náu cao tôi; tôi sẽ chẳng lay động nhiều.'),
(14831, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 62, 3, 'OT', 'Các ngươi còn định phá hại một người cho đến bao giờ? Hết thảy các ngươi cùng nhau đánh đổ người, như một bức tường nghiêng, như một tấm rào sắp đổ?'),
(14832, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 62, 4, 'OT', 'Chúng chỉ toan tính lật đổ người khỏi ngôi cao; chúng ưa thích điều dối trá; miệng chúng chúc phước, nhưng trong lòng chúng rủa sả.'),
(14833, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 62, 5, 'OT', 'Chỉ mình Đức Chúa Trời, hỡi linh hồn ta, ngươi hãy im lặng; vì từ nơi Ngài là sự trông cậy ta.'),
(14834, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 62, 6, 'OT', 'Chỉ mình Ngài là hòn đá tôi, là sự cứu rỗi tôi; là nơi nương náu cao tôi, tôi sẽ chẳng bị rung chuyển.'),
(14835, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 62, 7, 'OT', 'Sự cứu rỗi và sự vinh hiển ta ở nơi Đức Chúa Trời; hòn đá vững bền về sức lực ta và nơi nương náu ta ở nơi Đức Chúa Trời.'),
(14836, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 62, 8, 'OT', 'Hỡi muôn người, hãy tin cậy nơi Ngài mọi lúc; hãy đổ ra trước mặt Ngài lòng các ngươi; Đức Chúa Trời là nơi nương náu của chúng ta.'),
(14837, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 62, 9, 'OT', 'Chỉ là hư không, con cái loài người; chỉ là dối trá, con cái loài người; đặt trên bàn cân để lên, chúng đồng loạt nhẹ hơn hư không.'),
(14838, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 62, 10, 'OT', 'Chớ nhờ cậy sự áp bức, cũng đừng trông cậy vào sự cướp bóc; của cải có gia tăng, chớ đặt lòng vào đó.'),
(14839, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 62, 11, 'OT', 'Một điều Đức Chúa Trời đã phán, điều thứ hai tôi đã nghe: Quyền năng thuộc về Đức Chúa Trời.'),
(14840, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 62, 12, 'OT', 'Lạy Chúa, sự nhân từ thuộc về Ngài, vì chính Ngài sẽ đền đáp cho mỗi người tùy theo việc họ làm.'),
(14841, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 63, 1, 'OT', 'Một bài thơ của Đa-vít, khi người ở trong đồng vắng Giu-đa: Hỡi Đức Chúa Trời, Chúa là Đức Chúa Trời tôi, tôi khao khát Ngài; linh hồn tôi mong mỏi Ngài, thân thể tôi ao ước Ngài trong một đất khô cằn, vắng vẻ và không nước.'),
(14842, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 63, 2, 'OT', 'Vì nơi thánh tôi đã thấy Ngài, đặng nhìn xem quyền năng và sự vinh hiển của Ngài.'),
(14843, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 63, 3, 'OT', 'Vì ân trung của Ngài tốt hơn sự sống, môi tôi sẽ ca ngợi Ngài.'),
(14844, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 63, 4, 'OT', 'Vậy nên tôi sẽ chúc tụng Ngài trọn đời tôi; nhân danh Ngài tôi sẽ giơ tay lên.'),
(14845, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 63, 5, 'OT', 'Linh hồn tôi được no thỏa như mỡ và tủy; và môi tôi sẽ ngợi khen bằng lời ca vui vẻ.'),
(14846, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 63, 6, 'OT', 'Khi trên giường tôi nhớ đến Ngài, tôi suy gẫm về Ngài trong các canh đêm;'),
(14847, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 63, 7, 'OT', 'Vì Ngài đã giúp đỡ tôi, dưới bóng cánh của Ngài tôi sẽ reo mừng.'),
(14848, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 63, 8, 'OT', 'Linh hồn tôi bám sát theo Ngài; Tay phải Ngài nâng đỡ tôi.'),
(14849, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 63, 9, 'OT', 'Chúng sẽ tìm hại mạng sống tôi, rồi sẽ sa xuống các nơi sâu thẳm dưới đất.'),
(14850, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 63, 10, 'OT', 'Bọn nó sẽ bị nộp vào tay gươm; phần chúng nó sẽ trở nên mồi cho các loài chồn.'),
(14851, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 63, 11, 'OT', 'Vua sẽ vui vẻ trong Đức Chúa Trời; hễ ai chỉ Ngài mà thề sẽ khoe mình; vì miệng những kẻ nói dối sẽ bị bịt lại.'),
(14852, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 64, 1, 'OT', 'Lạy Đức Chúa Trời, xin hãy nghe tiếng kêu của tôi trong lời than thở; xin bảo vệ mạng sống tôi khỏi sợ hãi kẻ thù.'),
(14853, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 64, 2, 'OT', 'Xin giấu tôi khỏi mưu toan của kẻ ác, khỏi âm mưu của những kẻ làm điều gian ác.'),
(14854, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 64, 3, 'OT', 'Chúng nó đã mài lưỡi mình như gươm, nhắm những lời cay đắng như tên.'),
(14855, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 64, 4, 'OT', 'Họ rình bắn kẻ trọn lành từ nơi khuất; thình lình bắn vào người ấy mà không sợ hãi.'),
(14856, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 64, 5, 'OT', 'Chúng nó làm cho điều ác được vững chắc, bàn nhau kín giấu những bẫy rập, nói rằng: Ai sẽ thấy chúng nó?'),
(14857, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 64, 6, 'OT', 'Chúng tìm mưu kế độc ác; chúng nói: "Chúng tôi đã toan tính xong mưu kín giấu kỹ; tư tưởng sâu xa và lòng người thật sâu thẳm."'),
(14858, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 64, 7, 'OT', 'Nhưng Đức Chúa Trời giương tên thình lình; các vết thương của chúng nó bèn xuất hiện.'),
(14859, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 64, 8, 'OT', 'Chúng nó vấp ngã vì lưỡi của chúng nó; mọi kẻ thấy chúng đều lắc đầu.'),
(14860, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 64, 9, 'OT', 'Cả loài người đều sẽ sợ hãi, và sẽ loan truyền công việc của Đức Chúa Trời, và hiểu biết điều Ngài đã làm.'),
(14861, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 64, 10, 'OT', 'Người công bình sẽ vui vẻ trong Đức Giê-hô-va và nương náu trong Ngài, và mọi người có lòng ngay thẳng sẽ khoe mình.'),
(14862, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 65, 1, 'OT', 'Đức Giê-hô-va, tại Si-ôn, sự ngợi khen thuộc về Ngài; và lời hứa nguyện sẽ được trả cho Ngài.'),
(14863, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 65, 2, 'OT', 'Đức Giê-hô-va nghe lời cầu nguyện; mọi loài xác thịt sẽ đến cùng Ngài.'),
(14864, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 65, 3, 'OT', 'Các điều gian ác thắng hơn tôi; còn về những sự phạm tội của chúng tôi, Ngài sẽ xóa bỏ.'),
(14865, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 65, 4, 'OT', 'Phước thay cho người mà Đức Giê-hô-va chọn và khiến đến gần, được ở trong các hành lang của Ngài; chúng tôi sẽ được no nê điều thiện hảo trong nhà Ngài, là đền thánh của Ngài.'),
(14866, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 65, 5, 'OT', 'Đức Chúa Trời là Đấng cứu rỗi chúng tôi, Ngài lấy những điều kinh khủng đáp lời theo sự công bình; Ngài là nơi nương tựa của mọi đầu cùng đất và biển xa xăm.'),
(14867, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 65, 6, 'OT', 'Đức Giê-hô-va dùng quyền năng mình thiết lập các núi, và lấy sức lực mà thắt lưng.'),
(14868, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 65, 7, 'OT', 'Làm yên sự ầm ĩ của biển, sự ồn ào của sóng biển nó, và sự xao động của các dân.'),
(14869, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 65, 8, 'OT', 'Những kẻ ở nơi tận cùng trái đất đều sợ hãi trước các dấu kỳ của Ngài; các nơi xuất hiện của buổi sáng và buổi tối đều reo mừng.'),
(14870, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 65, 9, 'OT', 'Chúa thăm viếng đất và tưới ướt nó, làm cho nó trở nên phong phú; suối của Đức Chúa Trời đầy nước. Chúa chuẩn bị ngũ cốc, vì chính Chúa đã sắm sửa đất ấy.'),
(14871, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 65, 10, 'OT', 'Người tưới các luống cày của nó, san bằng các cục đất của nó, làm cho mềm bằng cơn mưa, và ban phước cho cây sinh trưởng của nó.'),
(14872, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 65, 11, 'OT', 'Ngài lấy năm tốt lành của Ngài làm mão triều, các lối bước của Ngài nhỏ ra chất béo.'),
(14873, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 65, 12, 'OT', 'Các đồng cỏ nơi đồng vắng được nuôi dưỡng đầy đủ, và các ngọn đồi thắt lưng bằng sự vui mừng.'),
(14874, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 65, 13, 'OT', 'Đàn chiên mặc lấy đồng cỏ; các thung lũng bao phủ bằng lúa mì; chúng reo vui và hát xướng.'),
(14875, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 66, 1, 'OT', 'Hỡi cả đất, hãy reo lên cho Đức Chúa Trời.'),
(14876, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 66, 2, 'OT', 'Hãy hát mừng sự vinh hiển của danh Ngài; hãy tôn vinh Ngài bằng lời ca ngợi.'),
(14877, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 66, 3, 'OT', 'Hãy thưa cùng Đức Chúa Trời rằng: Các việc Ngài thật đáng sợ thay! Nhờ quyền năng lớn thay của Ngài, những kẻ thù nghịch Ngài đều phải bóp miệng phục Ngài.'),
(14878, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 66, 4, 'OT', 'Cả trái đất sẽ thờ lạy Ngài và hát cho Ngài; chúng sẽ ca tụng danh Ngài.'),
(14879, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 66, 5, 'OT', 'Hãy đến xem các việc của Đức Chúa Trời, những việc đáng sợ Ngài đã làm cho con cái loài người.'),
(14880, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 66, 6, 'OT', 'Ngài khiến biển trở nên đất khô; họ đi ngang qua sông bằng chân; tại nơi ấy chúng tôi vui mừng trong Ngài.'),
(14881, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 66, 7, 'OT', 'Ngài dùng quyền năng Ngài mà cai trị đời đời; mắt Ngài nhìn xem các dân tộc. Hỡi những kẻ nổi loạn, đừng tự cao.'),
(14882, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 66, 8, 'OT', 'Hỡi các dân, hãy chúc tụng Đức Chúa Trời chúng ta, và làm cho vang tiếng ngợi khen Ngài.'),
(14883, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 66, 9, 'OT', 'Chính Ngài đặt linh hồn chúng ta trong sự sống, và không để cho chân chúng ta vấp ngã.'),
(14884, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 66, 10, 'OT', 'Vì Đức Chúa Trời, Ngài đã thử thách chúng tôi, luyện chúng tôi như người luyện bạc.'),
(14885, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 66, 11, 'OT', 'Ngài dẫn chúng tôi vào chỗ gài bẫy, đặt gánh nặng trên lưng chúng tôi.'),
(14886, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 66, 12, 'OT', 'Ngài khiến loài người cỡi trên đầu chúng tôi; chúng tôi đi qua lửa và qua nước; rồi Ngài dẫn chúng tôi ra nơi sung túc.'),
(14887, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 66, 13, 'OT', 'Tôi sẽ vào nhà Ngài với những lễ thiêu, tôi sẽ trả cho Ngài các lời hứa mà tôi đã khấn.'),
(14888, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 66, 14, 'OT', 'Mà môi tôi đã hứa, và miệng tôi đã nói trong lúc gian truân.'),
(14889, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 66, 15, 'OT', 'Ta sẽ dâng các lễ thiêu bằng chiên đực béo, cùng với hương thơm của chiên đực; Ta sẽ làm lễ của bò đực cùng với những con dê đực.'),
(14890, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 66, 16, 'OT', 'Hỡi các ngươi là mọi người kính sợ Đức Chúa Trời, hãy đến, hãy nghe tôi thuật lại điều Đức Chúa Trời đã làm cho linh hồn tôi.'),
(14891, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 66, 17, 'OT', 'Tôi đã kêu cầu Ngài bằng miệng tôi, và lưỡi tôi ngợi cao Ngài.'),
(14892, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 66, 18, 'OT', 'Nếu tôi nhìn thấy điều gian ác trong lòng tôi, thì Đức Giê-hô-va sẽ không nghe tôi.'),
(14893, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 66, 19, 'OT', 'Nhưng thật, Đức Chúa Trời đã nghe; Ngài lắng tai nghe tiếng cầu nguyện tôi.'),
(14894, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 66, 20, 'OT', 'Đáng ngợi khen Đức Chúa Trời, vì Ngài không rút lời cầu nguyện tôi, và sự nhân từ Ngài không rời khỏi tôi.'),
(14895, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 67, 1, 'OT', 'Nguyện Đức Chúa Trời thương xót chúng tôi và ban phước cho chúng tôi, soi sáng mặt Ngài trên chúng tôi.'),
(14896, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 67, 2, 'OT', 'Để cho người ta biết trên đất đường lối Ngài, và giữa mọi dân sự cứu rỗi của Ngài.'),
(14897, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 67, 3, 'OT', 'Hỡi Đức Chúa Trời, nguyện các dân tộc ca ngợi Ngài! Nguyện muôn dân tộc đều ca ngợi Ngài!'),
(14898, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 67, 4, 'OT', 'Các nước hãy vui mừng và reo hò, vì Đức Giê-hô-va sẽ đoán xét các dân cách ngay thẳng, và cai trị các nước trên đất.'),
(14899, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 67, 5, 'OT', 'Các dân tộc sẽ ca ngợi Ngài, hỡi Đức Chúa Trời; muôn dân sẽ ca ngợi Ngài.'),
(14900, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 67, 6, 'OT', 'Đất đã sinh hoa lợi nó; Đức Chúa Trời, Đức Chúa Trời chúng tôi, sẽ ban phước cho chúng tôi.'),
(14901, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 67, 7, 'OT', 'Đức Chúa Trời sẽ ban phước cho chúng tôi, và mọi đầu mút đất sẽ kính sợ Ngài.'),
(14902, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 1, 'OT', 'Nguyện Đức Chúa Trời chỗi dậy, các kẻ thù Ngài sẽ tan tác, và những kẻ ghét Ngài sẽ chạy trốn trước mặt Ngài.'),
(14903, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 2, 'OT', 'Như khói bị xua tan, Ngài sẽ xua tan chúng nó; như sáp tan chảy trước mặt lửa, những kẻ ác sẽ bị tiêu diệt trước mặt Đức Chúa Trời.'),
(14904, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 3, 'OT', 'Nhưng người công bình sẽ vui mừng, sẽ hớn hở trước mặt Đức Chúa Trời, và sẽ nức lòng mừng rỡ trong niềm vui.'),
(14905, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 4, 'OT', 'Hãy hát cho Đức Chúa Trời, hãy đàn ngợi danh Ngài; Hãy dọn đường cho Đấng cỡi ngựa đi ngang qua đồng vắng; Danh Ngài là Đức Giê-hô-va; hãy vui mừng trước mặt Ngài.'),
(14906, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 5, 'OT', 'Đức Chúa Trời ở nơi thánh của Ngài, là Cha kẻ mồ côi và quan xét người góa bụa.'),
(14907, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 6, 'OT', 'Đức Chúa Trời khiến kẻ cô đơn được ở trong nhà, đưa kẻ bị giam ra nơi thịnh vượng; nhưng những kẻ nổi loạn phải ở đất khô cằn.'),
(14908, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 7, 'OT', 'Đức Chúa Trời ơi, khi Ngài đi ra trước dân Ngài, khi Ngài bước đi trong đồng vắng, ngựơng!'),
(14909, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 8, 'OT', 'Đất rúng động, các từng trời cũng nhỏ giọt nước trước mặt Đức Chúa Trời; hỡi Si-na-i, ngươi cũng rúng động trước mặt Đức Chúa Trời, là Đức Chúa Trời của Y-sơ-ra-ên.'),
(14910, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 9, 'OT', 'Đức Chúa Trời đổ mưa phước xuống; sản nghiệp Ngài, khi đã kiệt sức, chính Ngài đã củng cố.'),
(14911, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 10, 'OT', 'Hỡi Đức Chúa Trời, muôn loài sống của Ngài ngự nơi đó; chính nơi tốt lành của Ngài, Ngài sắm sửa cho kẻ khốn cùng.'),
(14912, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 11, 'OT', 'Đức Giê-hô-va ban lời phán; đoàn quân các người báo tin tin thật rất đông.'),
(14913, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 12, 'OT', 'Các vua đạo binh đều chạy trốn, chạy trốn; còn người đàn bà ở nhà thì chia của chiến lợi phẩm.'),
(14914, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 13, 'OT', 'Nếu các ngươi nằm giữa hai cái lò sưởi, thì cánh của bồ câu phủ bạc, và lông nó phủ vàng ròng.'),
(14915, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 14, 'OT', 'Khi Đức Chúa Trời tản lạc các vua tại đó, thì tuyết rơi trên Sanh-môn.'),
(14916, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 15, 'OT', 'Núi của Đức Chúa Trời là núi Ba-san, núi Ba-san là núi nhiều chót.'),
(14917, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 16, 'OT', 'Hỡi các núi có nhiều chót, sao các ngươi ngó cách ganh ghét núi mà Đức Chúa Trời đã ưa chuộng để ở? Phải, Đức Giê-hô-va sẽ ở tại đó đến đời đời.'),
(14918, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 17, 'OT', 'Xe của Đức Chúa Trời là hàng vạn, ngàn ngàn, Chúa ngự giữa chúng tại Si-na-i trong nơi thánh.'),
(14919, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 18, 'OT', 'Đức Giê-hô-va đã lên cao rước theo những phu tù; Ngài đã nhận lễ vật trong loài người, và ngay cả những kẻ chống nghịch, hầu cho Đức Chúa Trời được ở đó.'),
(14920, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 19, 'OT', 'Đáng ngợi khen Đức Giê-hô-va, hằng ngày Ngài gánh vác cho chúng tôi; Đức Chúa Trời là Đấng cứu chúng tôi. Hê-xê-na.'),
(14921, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 20, 'OT', 'Đức Chúa Trời là Đấng ban sự cứu rỗi cho chúng tôi; và bởi Đức Giê-hô-va, là Chúa, mà người ta được giải thoát khỏi sự chết.'),
(14922, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 21, 'OT', 'Nhưng Đức Chúa Trời sẽ đập nát đầu các kẻ thù nghịch, và đầu của kẻ đi trong sự gian ác.'),
(14923, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 22, 'OT', 'Chúa phán: Từ Ba-san Ta sẽ đem nó trở về; Ta sẽ đem nó trở về từ những vực thẳm của biển.'),
(14924, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 23, 'OT', 'Ngõ hầu ngươi dẫm chân trong huyết; Ngươi khiến lưỡi chó ngươi được phần từ kẻ thù nghịch ngươi.'),
(14925, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 24, 'OT', 'Hỡi Đức Chúa Trời, người ta đã thấy các bước đi của Ngài, các bước đi của Đức Chúa Trời, là Vua tôi, vào nơi thánh.'),
(14926, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 25, 'OT', 'Các nhạc trưởng đi trước, người đánh nhạc theo sau, giữa những thiếu nữ đánh trống.'),
(14927, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 26, 'OT', 'Trong các hội, hãy chúc tụng Đức Chúa Trời, hỡi những người xuất phát từ nguồn mạch Y-sơ-ra-ên.'),
(14928, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 27, 'OT', 'Này, Bê-gia-min là kẻ nhỏ cai trị chúng nó; các lãnh tụ Giu-đa, và đoàn người của họ; các lãnh tụ Sa-bu-lôn, các lãnh tụ Nép-ta-li.'),
(14929, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 28, 'OT', 'Đức Chúa Trời của ngươi đã ra lệnh cho sức lực ngươi; hỡi Đức Chúa Trời, xin hãy làm cho vững bền điều mà Ngài đã thực hiện cho chúng tôi.'),
(14930, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 29, 'OT', 'Từ đền thờ Ngài tại Giê-ru-sa-lem, các vua sẽ dâng lễ vật cho Ngài.'),
(14931, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 30, 'OT', 'Hãy quở trách muông thú trong bụi sậy, hội các dũng sĩ cùng bò con của các dân; chúng cúi lạy nơi chân bạc, hãy tản lạc các dân ưa chuộng chiến tranh.'),
(14932, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 31, 'OT', 'Những người từ Ê-dốp sẽ đến; Ê-thi-ô-bi giơ tay về hướng Đức Chúa Trời.'),
(14933, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 32, 'OT', 'Hỡi các nước trên đất, hãy hát cho Đức Chúa Trời; hãy hát xướng Đức Giê-hô-va.'),
(14934, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 33, 'OT', 'Đấng cỡi trên các từng trời đời đời; nầy, Ngài phát tiếng ra, tiếng có quyền năng.'),
(14935, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 34, 'OT', 'Hãy ban sức mạnh cho Đức Chúa Trời; sự oai nghiêm Ngài ở trên Y-sơ-ra-ên, và quyền năng Ngài ở trong các tầng trời.'),
(14936, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 68, 35, 'OT', 'Đức Chúa Trời thật đáng sợ từ nơi thánh Ngài; chính Đức Chúa Trời của Y-sơ-ra-ên ban sức mạnh và quyền năng cho dân sự; Đức Chúa Trời được ca ngợi.'),
(14937, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 1, 'OT', 'Lạy Đức Chúa Trời, xin cứu con, vì nước đã dâng lên tận mạng sống con.'),
(14938, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 2, 'OT', 'Tôi chìm trong vũng lầy sâu, không nơi nào đứng vững; tôi vào nơi sâu thẳm của nước, và dòng lũ cuốn tôi đi.'),
(14939, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 3, 'OT', 'Tôi la mệt, cuống họng tôi khô; mắt tôi hao mòn vì trông đợi Đức Chúa Trời tôi.'),
(14940, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 4, 'OT', 'Kẻ thù tôi, không vì cớ gì, đông hơn số tóc trên đầu tôi; những kẻ chống tôi cách dối trá mạnh thế thay. Điều tôi không lấy, chúng buộc tôi phải đền bồi.'),
(14941, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 5, 'OT', 'Đức Chúa Trời ôi, Ngài biết sự ngu dại tôi; các tội lỗi tôi không giấu khỏi Ngài được.'),
(14942, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 6, 'OT', 'Đức Giê-hô-va vạn quân ôi, xin đừng để những kẻ trông đợi tôi phải hổ thẹn vì cớ tôi; Đức Chúa Trời của Y-sơ-ra-ên ôi, xin đừng để những kẻ tìm kiếm tôi phải nhục nhã vì tôi.'),
(14943, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 7, 'OT', 'Vì cớ Ngài, tôi đã mang sự sỉ nhục; sự xấu hổ đã che phủ mặt tôi.'),
(14944, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 8, 'OT', 'Tôi đã trở nên người xa lạ đối với anh em tôi, và là người ngoại với các con trai của mẹ tôi.'),
(14945, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 9, 'OT', 'Vì lòng sốt sắng về nhà Ngài đã tiêu nuốt tôi, và sự sỉ nhục của những kẻ sỉ nhục Ngài đã đổ trên tôi.'),
(14946, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 10, 'OT', 'Tôi khóc khi nhịn ăn, linh hồn tôi đau buồn; điều đó trở nên sự sỉ nhục cho tôi.'),
(14947, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 11, 'OT', 'Tôi lấy áo bằng bao gai làm y phục mình, và trở nên một câu chuyện ngụ ngôn cho chúng nó.'),
(14948, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 12, 'OT', 'Những kẻ ngồi nơi cửa thành bàn tán về tôi; còn kẻ uống rượu thì lấy tôi làm bài hát chê cười.'),
(14949, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 13, 'OT', 'Nhưng tôi, hỡi Đức Giê-hô-va, lời cầu nguyện tôi dành cho Ngài là trong lúc đẹp ý; hỡi Đức Chúa Trời, theo sự thương xót lớn của Ngài, xin hãy nhậm lời tôi theo lẽ thật về sự cứu rỗi của Ngài.'),
(14950, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 14, 'OT', 'Xin hãy cứu tôi khỏi vũng bùn, đừng để tôi sa lầy; xin giải thoát tôi khỏi những kẻ ghét tôi và khỏi những vực sâu nước.'),
(14951, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 15, 'OT', 'Nguyện chớ để dòng nước tràn qua tôi, chớ để vực sâu nuốt tôi, chớ để hầm kín đóng miệng lại trên tôi.'),
(14952, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 16, 'OT', 'Đức Giê-hô-va ơi, xin hãy nhậm lời tôi, vì ơn Ngài tốt lành; theo sự thương xót lớn của Ngài, xin hãy đoái đến tôi.'),
(14953, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 17, 'OT', 'Xin đừng giấu mặt cùng tôi tớ Ngài, vì tôi đang gặp điều khốn khổ; hãy mau mau đáp lời tôi.'),
(14954, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 18, 'OT', 'Cầu cho Đức Giê-hô-va đến gần linh hồn tôi và chuộc nó; vì cớ kẻ thù tôi, xin cứu chuộc tôi.'),
(14955, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 19, 'OT', 'Chúa biết sự sỉ nhục, sự hổ thẹn và sự nhục nhã của tôi; tất cả những kẻ thù tôi đều ở trước mặt Đức Giê-hô-va.'),
(14956, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 20, 'OT', 'Sự sỉ nhục làm tan nát lòng tôi, tôi đau buồn khôn tả; tôi mong đợi có người chia sẻ nỗi buồn, nhưng chẳng thấy ai; tôi tìm người an ủi, mà cũng không tìm được.'),
(14957, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 21, 'OT', 'Chúng đặt thuốc độc vào thức ăn tôi, và khi tôi khát thì cho tôi uống giấm.'),
(14958, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 22, 'OT', 'Nguyện bàn tiệc của chúng nó trước mặt chúng nó trở nên bẫy; và sự bình an của chúng nó trở nên cái bẫy rập.'),
(14959, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 23, 'OT', 'Nguyện mắt chúng nó tối tăm không thấy được, và lưng chúng nó luôn luôn run rẩy.'),
(14960, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 24, 'OT', 'Hãy đổ cơn thịnh nộ của Ngài trên chúng nó, và cơn giận phừng phừng của Ngài bắt kịp chúng nó.'),
(14961, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 25, 'OT', 'Nguyện nơi ở của chúng nó trở nên hoang vu, trong các trại của chúng nó chớ có ai ở nữa.'),
(14962, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 26, 'OT', 'Vì chính Ngài đã đánh, chúng nó mới bắt bớ; và về cơn đau của những người bị thương do Ngài, chúng nó thuật lại.'),
(14963, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 27, 'OT', 'Xin để tội ác chất thêm trên tội ác chúng nó, và đừng để chúng vào trong sự công bình của Ngài.'),
(14964, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 28, 'OT', 'Nguyện chúng bị xoá khỏi sách sự sống, và không được ghi tên cùng với người công bình.'),
(14965, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 29, 'OT', 'Còn tôi, tôi khốn khổ và đau đớn; sự cứu rỗi của Ngài, Đức Chúa Trời, sẽ nâng cao tôi lên.'),
(14966, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 30, 'OT', 'Tôi sẽ lấy bài ca mà ngợi khen danh Đức Chúa Trời, và lấy sự cảm tạ mà tôn cao Ngài.'),
(14967, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 31, 'OT', 'Thật đẹp lòng Đức Giê-hô-va hơn là con bò đực, hay con bò tơ có sừng và móng chia nhẽ.'),
(14968, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 32, 'OT', 'Kẻ khiêm nhường xem thấy sẽ vui mừng; hỡi những kẻ tìm kiếm Đức Chúa Trời, nguyện lòng các ngươi được sống.'),
(14969, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 33, 'OT', 'Vì Đức Giê-hô-va nghe những kẻ khốn khổ, và không khinh thường các phu tù của Ngài.'),
(14970, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 34, 'OT', 'Nguyện các từng trời và đất đều ca ngợi Ngài; nguyện các biển và mọi loài bò sát trong đó đều ngợi khen Ngài.'),
(14971, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 35, 'OT', 'Vì Đức Chúa Trời sẽ cứu Si-ôn, và xây cất các thành của Giu-đa; họ sẽ ở đó và thừa hưởng nó.'),
(14972, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 69, 36, 'OT', 'Và dòng dõi các tôi tớ Ngài sẽ kế tự nó; những kẻ yêu mến danh Ngài sẽ cư ngụ trong đó.'),
(14973, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 70, 1, 'OT', 'Đức Chúa Trời ôi, xin mau mau giải cứu tôi; Đức Giê-hô-va ôi, xin mau mau giúp đỡ tôi.'),
(14974, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 70, 2, 'OT', 'Nguyện những kẻ tìm hại mạng sống tôi phải hổ thẹn và xấu hổ; nguyện những kẻ vui vì tai họa tôi phải lùi lại và nhục nhã.'),
(14975, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 70, 3, 'OT', 'Nguyện những kẻ vì hổ thẹn mà phải quay lui, là những kẻ nói: "Ha ha! Ha ha!"'),
(14976, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 70, 4, 'OT', 'Nguyện tất cả những người tìm kiếm Ngài đều vui mừng và hớn hở trong Ngài; nguyện họ luôn nói rằng: Đức Chúa Trời được tôn lên cao, những người yêu mến sự cứu rỗi của Ngài.'),
(14977, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 70, 5, 'OT', 'Còn tôi, tôi là kẻ khốn cùng và nghèo khổ; Đức Chúa Trời ôi, xin mau mau đến cùng tôi. Ngài là Đấng giúp đỡ tôi và là Đấng giải cứu tôi; Đức Giê-hô-va ôi, xin chớ chậm trễ.'),
(14978, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 71, 1, 'OT', 'Hỡi Đức Giê-hô-va, tôi tin cậy nơi Ngài; xin đừng để tôi bị hổ thẹn đời đời.'),
(14979, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 71, 2, 'OT', 'Nhân sự công bình của Ngài, xin hãy giải cứu tôi và cứu tôi thoát ra; xin hãy nghiêng tai Ngài về phía tôi và cứu tôi.'),
(14980, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 71, 3, 'OT', 'Xin hãy làm cho tôi hòn đá làm nơi nương náu, để tôi luôn luôn được vào đó; Ngài đã truyền cứu tôi, vì Ngài là hòn đá và thành lũy của tôi.'),
(14981, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 71, 4, 'OT', 'Lạy Đức Chúa Trời, xin giải cứu tôi khỏi tay kẻ ác, khỏi vòng tay người gian ác và hung bạo.'),
(14982, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 71, 5, 'OT', 'Vì, Đức Giê-hô-va ôi, Ngài là sự trông đợi tôi, và là chỗ tôi tin cậy từ khi tôi còn thơ ấu.'),
(14983, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 71, 6, 'OT', 'Tôi nương tựa Ngài từ lúc còn trong lòng mẹ, chính Ngài đã cho tôi ra khỏi lòng mẹ tôi; Ngài là lý do tôi luôn luôn ca ngợi.'),
(14984, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 71, 7, 'OT', 'Tôi đã trở nên điều kỳ lạ đối với nhiều người; còn Ngài là nơi tôi nương náu vững chắc.'),
(14985, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 71, 8, 'OT', 'Miệng tôi đầy sự ngợi khen Ngài suốt cả ngày, và sự tôn vinh Ngài.'),
(14986, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 71, 9, 'OT', 'Xin đừng loại bỏ tôi trong thời già yếu; khi sức lực tôi suy tàn, xin đừng bỏ tôi.'),
(14987, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 71, 10, 'OT', 'Vì những kẻ thù tôi nói nghịch tôi, và những kẻ rình rập mạng sống tôi cùng nhau mưu kế.'),
(14988, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 71, 11, 'OT', 'Mà rằng: Đức Chúa Trời đã bỏ hắn; hãy đuổi theo và bắt lấy hắn, vì chẳng có ai giải cứu.'),
(14989, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 71, 12, 'OT', 'Đức Chúa Trời, xin chớ lìa xa tôi; hỡi Đức Chúa Trời tôi, xin mau đến giúp đỡ tôi.'),
(14990, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 71, 13, 'OT', 'Nguyện những kẻ thù ghét mạng sống tôi phải xấu hổ và tiêu vong; nguyện những kẻ tìm kiếm điều dữ cho tôi bị bao phủ bởi sự sỉ nhục và ô nhục.'),
(14991, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 71, 14, 'OT', 'Nhưng tôi luôn luôn trông cậy, và sẽ nhân thêm mọi lời ca ngợi Ngài.'),
(14992, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 71, 15, 'OT', 'Miệng tôi sẽ truyền rao sự công bình của Đức Giê-hô-va trọn ngày; sự cứu rỗi của Ngài, vì tôi không biết được số lượng của nó.'),
(14993, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 71, 16, 'OT', 'Tôi sẽ vào trong các việc quyền năng của Đức Giê-hô-va; tôi sẽ nhắc đến sự công bình của Ngài, chỉ riêng sự công bình của Ngài mà thôi.'),
(14994, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 71, 17, 'OT', 'Lạy Đức Chúa Trời, Ngài đã dạy tôi từ khi tôi còn nhỏ; và cho đến nay tôi rao giảng các việc lạ lùng của Ngài.'),
(14995, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 71, 18, 'OT', 'Lạy Đức Chúa Trời, xin chớ bỏ tôi cho đến khi già cả và tóc bạc, để tôi còn rao giảng về cánh tay quyền năng của Ngài cho thế hệ tương lai, và sự oai hùng của Ngài cho những người sẽ đến.'),
(14996, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 71, 19, 'OT', 'Sự công bình của Ngài, hỡi Đức Chúa Trời, cao đến tận nơi cao cả; những việc lớn lao Ngài đã làm, hỡi Đức Chúa Trời, ai giống như Ngài?'),
(14997, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 71, 20, 'OT', 'Đấng đã cho tôi thấy nhiều nỗi gian truân và điều ác, Ngài sẽ khiến tôi sống lại và đưa tôi lên từ vực sâu của đất.'),
(14998, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 71, 21, 'OT', 'Ngài sẽ làm cho sự vinh hiển của tôi được gia tăng thêm, và trở lại an ủi tôi.'),
(14999, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 71, 22, 'OT', 'Hỡi Đức Chúa Trời tôi, tôi cũng sẽ ngợi khen Ngài bằng đàn cầm, tán tạ sự thành tín của Ngài; hỡi Đấng Thánh của Y-sơ-ra-ên, tôi sẽ dùng đàn sắt mà ca ngợi Ngài.'),
(15000, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 71, 23, 'OT', 'Môi tôi sẽ reo vui khi tôi ca ngợi Ngài, và linh hồn tôi mà Ngài đã chuộc lại.'),
(15001, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 71, 24, 'OT', 'Cả ngày lưỡi tôi sẽ nói về sự công bình của Đức Giê-hô-va; Vì những kẻ tìm hại tôi đã bị xấu hổ và phải nhục nhã.'),
(15002, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 72, 1, 'OT', 'Hỡi Đức Chúa Trời, xin ban cho vua sự xét đoán của Ngài, và sự công bình của Ngài cho con trai vua.'),
(15003, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 72, 2, 'OT', 'Người sẽ xét đoán dân Ngài cách công bình, và xử lý những kẻ nghèo khó cách chính trực.'),
(15004, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 72, 3, 'OT', 'Các núi sẽ đem bình an cho dân sự, các gò sẽ đem sự công bình.'),
(15005, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 72, 4, 'OT', 'Người sẽ xét xử kẻ nghèo khổ trong dân, cứu giúp con cái kẻ khốn cùng, và nghiền nát kẻ áp bức.'),
(15006, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 72, 5, 'OT', 'Chúng sẽ kính sợ Ngài cùng mặt trời, và trước mặt trăng đến muôn đời.'),
(15007, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 72, 6, 'OT', 'Sẽ giáng xuống như mưa trên cỏ non, Khác nào những giọt mưa tưới đất.'),
(15008, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 72, 7, 'OT', 'Trong đời người ấy, người công bình sẽ phát triển mạnh, và sẽ có nhiều sự bình an cho đến khi mặt trăng không còn.'),
(15009, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 72, 8, 'OT', 'Người sẽ thống trị từ biển này đến biển kia, và từ sông kia cho đến các đầu cùng đất.'),
(15010, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 72, 9, 'OT', 'Các đảo sẽ phủ phục trước mặt Ngài; và những kẻ thù nghịch Ngài sẽ liếm bụi.'),
(15011, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 72, 10, 'OT', 'Các vua Ta-rê-si và các hải đảo sẽ dâng lễ vật; các vua Sa-ba và Sê-ba sẽ dâng của lễ.'),
(15012, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 72, 11, 'OT', 'Mọi vua sẽ thờ lạy Ngài, mọi nước sẽ phục vụ Ngài.'),
(15013, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 72, 12, 'OT', 'Vì người sẽ giải cứu kẻ nghèo khó khi kêu cứu, và kẻ khốn cùng không có ai giúp đỡ.'),
(15014, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 72, 13, 'OT', 'Người sẽ thương xót kẻ khốn cùng và người thiếu thốn, và cứu sống linh hồn những kẻ thiếu thốn.'),
(15015, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 72, 14, 'OT', 'Người sẽ cứu chuộc linh hồn họ khỏi sự áp bức và bạo lực; huyết họ đối với mắt Ngài là quý báu.'),
(15016, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 72, 15, 'OT', 'Người sẽ được sống, và người ta sẽ dâng cho Người vàng Sa-ba; người ta sẽ cầu nguyện cho Người luôn luôn; suốt cả ngày người ta sẽ chúc phước cho Người.'),
(15017, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 72, 16, 'OT', 'Sẽ có lúa mì trên đất, trên đỉnh các núi bông trái nó sẽ lao xao như Li-ban; người ở trong thành sẽ nở rộ như cỏ trên đất.'),
(15018, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 72, 17, 'OT', 'Danh Ngài sẽ còn đời đời, trước mặt mặt trời sẽ nảy ra mầm non danh Ngài; muôn dân sẽ nhờ Ngài mà được phước, sẽ ca tụng Ngài là Đấng có phước.'),
(15019, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 72, 18, 'OT', 'Đáng ngợi khen Đức Giê-hô-va Đức Chúa Trời, là Đức Chúa Trời của Y-sơ-ra-ên, Đấng làm những sự lạ lùng một mình Ngài!'),
(15020, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 72, 19, 'OT', 'Đáng ngợi khen danh vinh hiển của Ngài đời đời vô cùng! Nguyện sự vinh hiển của Ngài đầy khắp đất! A-men và A-men!'),
(15021, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 72, 20, 'OT', 'Các lời cầu nguyện của Đa-vít, con trai Y-sai, đã được hoàn tất.'),
(15022, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 73, 1, 'OT', 'Một bài ca của A-sáp: Thật vậy, Đức Chúa Trời tốt lành cho Y-sơ-ra-ên, cho những ai có lòng thanh khiết.'),
(15023, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 73, 2, 'OT', 'Còn tôi, chân tôi hầu như vấp ngã, bước đi tôi suýt nữa trượt chân.'),
(15024, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 73, 3, 'OT', 'Vì tôi đã ganh tị với những kẻ kiêu ngạo, khi thấy sự thạnh vượng của những kẻ ác.'),
(15025, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 73, 4, 'OT', 'Vì chúng nó không bị khốn khổ trong cơn chết; sức lực của chúng nó vẫn vững mạnh.'),
(15026, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 73, 5, 'OT', 'Chúng nó không bị khốn khổ như loài người; chẳng bị tai họa như người đời.'),
(15027, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 73, 6, 'OT', 'Vì vậy, chúng lấy kiêu ngạo làm vòng cổ, lấy bạo ác làm áo choàng quấn quanh mình.'),
(15028, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 73, 7, 'OT', 'Mắt chúng nó lộ ra trong mỡ; lòng chúng nó tràn đầy những điều tham muốn.'),
(15029, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 73, 8, 'OT', 'Chúng nó gièm pha và nói điều ác về sự hà hiếp; từ nơi cao chúng nó buông lời.'),
(15030, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 73, 9, 'OT', 'Miệng chúng đặt trên trời, và lưỡi chúng đi dạo trên đất.'),
(15031, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 73, 10, 'OT', 'Vì lý do đó, dân chúng trở về đây, và nước đầy tràn được tuôn ra cho họ.'),
(15032, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 73, 11, 'OT', 'Họ nói rằng: "Làm sao Đức Chúa Trời biết được? Há có tri thức nơi Đấng Tối Cao sao?"'),
(15033, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 73, 12, 'OT', 'Kìa, những kẻ ác ấy bình an đời này, nên của cải chúng nó gia tăng.'),
(15034, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 73, 13, 'OT', 'Nhưng tôi đã vô ích làm cho lòng tôi thanh sạch, và rửa tay trong sự trong sạch,'),
(15035, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 73, 14, 'OT', 'Tôi đã bị đau đớn suốt cả ngày, và bị sửa phạt từ sáng sớm.'),
(15036, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 73, 15, 'OT', 'Nếu tôi nói: Ta sẽ thuật ra như vậy, thì thật vậy, ta đã phản trọn dòng dõi các con của Ngài.'),
(15037, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 73, 16, 'OT', 'Khi tôi nghĩ đến việc hiểu biết điều này, thì thấy thật là cực nhọc trước mắt tôi.'),
(15038, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 73, 17, 'OT', 'Cho đến khi tôi vào nơi thánh của Đức Chúa Trời, thì tôi hiểu rõ điều cuối cùng của chúng nó.'),
(15039, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 73, 18, 'OT', 'Nhưng trong những nơi trơn trợt, Ngài đặt chúng nó vào đó; Ngài làm cho chúng nó sa ngã đến chỗ hủy diệt.'),
(15040, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 73, 19, 'OT', 'Làm sao chúng nó trở nên hoang vu trong chớp mắt! Chúng nó bị tiêu diệt, tan biến đi vì kinh hoàng.'),
(15041, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 73, 20, 'OT', 'Lạy Chúa, như chiêm bao tan biến khi tỉnh giấc, Ngài khi thức dậy sẽ khinh dể hình ảnh chúng nó.'),
(15042, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 73, 21, 'OT', 'Khi lòng tôi đầy ghen tức, và lòng tôi xao xuyến,'),
(15043, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 73, 22, 'OT', 'Tôi thì ngu dốt và không hiểu biết; trước mặt Ngài, tôi khác nào một loài thú vật.'),
(15044, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 73, 23, 'OT', 'Tôi luôn luôn ở cùng Đức Giê-hô-va; Ngài nắm lấy tay phải tôi.'),
(15045, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 73, 24, 'OT', 'Ngài sẽ lấy sự chỉ dẫn của Ngài mà dẫn dắt tôi, rồi sau đó sẽ đem tôi vào vinh hiển.'),
(15046, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 73, 25, 'OT', 'Trên trời, tôi có ai ngoài Ngài? Còn dưới đất, tôi chẳng thèm muốn ai khác ngoài Ngài.'),
(15047, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 73, 26, 'OT', 'Thịt tôi và lòng tôi hao mòn; Đức Chúa Trời là vầng đá của lòng tôi và là phần tôi đời đời.'),
(15048, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 73, 27, 'OT', 'Kìa, những kẻ lìa xa Ngài sẽ bị tiêu diệt; Ngài sẽ hủy diệt mọi kẻ gian dâm xa rời Ngài.'),
(15049, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 73, 28, 'OT', 'Nhưng lấy làm tốt thay cho tôi đến gần Đức Chúa Trời; tôi đặt Đức Giê-hô-va làm nơi nương náu mình, đặng thuật lại hết thảy các công việc Ngài.'),
(15050, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 74, 1, 'OT', 'Lạy Đức Chúa Trời, sao Ngài bỏ chúng tôi mãi mãi? Cơn thịnh nộ của Ngài sẽ còn cháy như khói chống lại bầy chiên trong đồng cỏ của Ngài đến bao giờ?'),
(15051, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 74, 2, 'OT', 'Hãy nhớ lại hội chúng Ngài đã chiếm hữu từ xưa, đã chuộc làm cơ nghiệp của Ngài; núi Si-ôn, nơi Ngài đã ngự.'),
(15052, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 74, 3, 'OT', 'Hãy đưa bước Ngài đến những nơi bị hủy hoại đời đời; kẻ thù đã làm ác tràn ngập nơi thánh.'),
(15053, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 74, 4, 'OT', 'Kẻ thù Ngài gầm thét trong nơi thánh Ngài; chúng đặt các dấu hiệu của chúng làm dấu.'),
(15054, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 74, 5, 'OT', 'Chúng nó giương rìu lên như kẻ đốn cây trong rừng rậm.'),
(15055, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 74, 6, 'OT', 'Bây giờ chúng nó dùng rìu và búa, đập tan mọi chỗ chạm trổ.'),
(15056, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 74, 7, 'OT', 'Chúng nó đã phóng lửa vào nơi thánh của Ngài, làm cho nơi ở danh Ngài bị phàm tục hóa xuống đất.'),
(15057, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 74, 8, 'OT', 'Chúng nó nói trong lòng rằng: "Hãy cùng nhau tiêu diệt hết thảy." Chúng nó đã thiêu hủy mọi nơi nhóm họp của Đức Chúa Trời trên đất.'),
(15058, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 74, 9, 'OT', 'Chúng tôi không còn thấy các dấu kỳ của chúng tôi; chẳng còn nhà tiên tri nào nữa, và giữa chúng tôi cũng không ai biết đến chừng nào.'),
(15059, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 74, 10, 'OT', 'Lạy Đức Chúa Trời, kẻ thù sẽ sỉ nhục Ngài cho đến bao giờ? Kẻ địch nghịch sẽ khinh bỉ danh Ngài mãi mãi sao?'),
(15060, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 74, 11, 'OT', 'Sao Ngài rút lại tay mình, tay phải Ngài? Xin rút nó ra khỏi lòng Ngài và tiêu diệt kẻ thù!'),
(15061, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 74, 12, 'OT', 'Đức Chúa Trời là Vua tôi từ trước, Đấng làm những công việc cứu giúp ở giữa đất.'),
(15062, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 74, 13, 'OT', 'Chính Ngài đã dùng quyền năng mà rẽ biển, bẻ gãy đầu những con rồng trên mặt nước.'),
(15063, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 74, 14, 'OT', 'Chính Ngài đã đập tan đầu của Li-vi-a-than, ban nó làm thức ăn cho dân sống ở nơi hoang vu.'),
(15064, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 74, 15, 'OT', 'Chúa đã nứt ra suối nước và khe nước, Chúa đã làm cho khô các sông hùng mạnh.'),
(15065, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 74, 16, 'OT', 'Đức Giê-hô-va, ngày thuộc về Ngài, đêm cũng vậy; chính Ngài đã thiết lập mặt trăng và mặt trời.'),
(15066, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 74, 17, 'OT', 'Chính Ngài đã lập mọi ranh giới của đất; chính Ngài đã tạo nên mùa hè và mùa đông.'),
(15067, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 74, 18, 'OT', 'Hỡi Đức Giê-hô-va, xin hãy nhớ điều nầy: kẻ thù đã sỉ nhục, và một dân ngu dại đã khinh bỉ danh Ngài.'),
(15068, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 74, 19, 'OT', 'Xin chớ phó linh hồn thú vật của dân Ngài cho loài vật dữ; cũng đừng quên mãi kẻ khốn cùng của Ngài.'),
(15069, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 74, 20, 'OT', 'Xin hãy đoái đến giao ước, vì các nơi tối tăm trên đất đều đầy những hang ổ bạo tàn.'),
(15070, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 74, 21, 'OT', 'Nguyện kẻ bị hà hiếp chẳng trở về hổ thẹy; nguyện kẻ khốn cùng và kẻ thiếu thốn ca ngợi danh Ngài.'),
(15071, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 74, 22, 'OT', 'Hỡi Đức Chúa Trời, hãy chỗi dậy, tranh luận sự tranh luận của Ngài; hãy nhớ lại sự sỉ nhục mà kẻ ngu dại sỉ nhục Ngài suốt cả ngày.'),
(15072, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 74, 23, 'OT', 'Xin chớ quên tiếng kẻ thù Ngài; tiếng ồn ào của những kẻ dấy lên nghịch cùng Ngài cứ dâng lên không ngừng.'),
(15073, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 75, 1, 'OT', 'Đức Chúa Trời, chúng tôi cảm tạ Ngài; chúng tôi cảm tạ, vì danh Ngài gần; chúng tôi thuật lại các việc lạ lùng của Ngài.'),
(15074, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 75, 2, 'OT', 'Ta sẽ chọn thời kỳ đã định; chính ta sẽ xét đoán cách ngay thẳng.'),
(15075, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 75, 3, 'OT', 'Đất và mọi người sống trên đất đều rung chuyển; chính ta đã vững vàng các trụ của nó.'),
(15076, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 75, 4, 'OT', 'Tôi phán cùng những kẻ ăn mừng cách điên rồ: Đừng ăn mừng nữa; và bảo những kẻ ác: Đừng giương sừng lên.'),
(15077, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 75, 5, 'OT', 'Chớ ngước sừng các ngươi lên cao, chớ nói cách ngạo mạn với cổ cứng nhắc.'),
(15078, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 75, 6, 'OT', 'Vì sự tôn cao không đến từ phương đông hay phương tây, cũng không đến từ nơi hoang mạc giữa các ngọn núi.'),
(15079, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 75, 7, 'OT', 'Vì Đức Chúa Trời là Đấng xét đoán: Ngài làm cho kẻ nầy hạ xuống, và kẻ kia được nhắc lên.'),
(15080, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 75, 8, 'OT', 'Vì trong tay Đức Giê-hô-va có một chén, rượu nồng đầy ủ; Ngài rót ra từ đó, nhưng những kẻ ác trên đất sẽ uống cặn nó và uống sạch.'),
(15081, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 75, 9, 'OT', 'Còn tôi, tôi sẽ thuật lại điều đó mãi mãi; tôi sẽ hát mừng cho Đức Chúa Trời của Gia-cốp.'),
(15082, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 75, 10, 'OT', 'Tôi sẽ chặt hết thảy các sừng kẻ ác; các sừng người công bình sẽ được ngước lên.'),
(15083, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 76, 1, 'OT', 'Trong Giu-đa người ta biết Đức Chúa Trời, Danh Ngài lớn tại Y-sơ-ra-ên.'),
(15084, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 76, 2, 'OT', 'Đền tạm của Ngài ở Sa-lem, và nơi ở của Ngài tại Si-ôn.'),
(15085, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 76, 3, 'OT', 'Tại nơi ấy, Ngài đã bẻ gãy những ngọn tên, cái khiên, thanh gươ0m, và khí giới chiến tranh.'),
(15086, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 76, 4, 'OT', 'Đức Giê-hô-va, Ngài oai nghiêm rực rỡ hơn các núi cướp giật.'),
(15087, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 76, 5, 'OT', 'Các dũng sĩ lòng gan dạ đều bị cướp mất, ngủ mê, không một người chiến sĩ nào tìm lại được tay mình.'),
(15088, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 76, 6, 'OT', 'Từ sự quở trách của Đức Chúa Trời Gia-cốp, người ta ngủ mê, xe và ngựa đều ngã gục.'),
(15089, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 76, 7, 'OT', 'Chính Ngài thật là đáng sợ; ai có thể đứng trước mặt Ngài từ khi cơn thịnh nộ của Ngài nổi lên?'),
(15090, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 76, 8, 'OT', 'Từ trên trời, Đức Chúa Trời phán ra sự xét đoán; đất sợ hãi và im lặng.'),
(15091, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 76, 9, 'OT', 'Khi Đức Chúa Trời chỗi dậy để xét đoán, Ngài cứu giúp mọi người khiêm nhường trên đất.'),
(15092, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 76, 10, 'OT', 'Cơn thịnh nộ của loài người sẽ tôn vinh Đức Giê-hô-va; còn phần sót lại của cơn thịnh nộ, Ngài sẽ kiềm chế.'),
(15093, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 76, 11, 'OT', 'Hãy hứa nguyện và trả xong cho Đức Giê-hô-va Đức Chúa Trời các ngươi; hết thảy những kẻ xung quanh Ngài đều phải dâng lễ vật cho Đấng đáng kính sợ.'),
(15094, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 76, 12, 'OT', 'Hãy dập tắt cơn thịnh nộ của các quan trưởng; Đáng sợ đối với các vua thế gian.'),
(15095, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 77, 1, 'OT', 'Ta sẽ kêu lên Đức Chúa Trời, ta sẽ kêu lớn; ta sẽ kêu lên Đức Chúa Trời, Ngài sẽ chăm nghe ta.'),
(15096, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 77, 2, 'OT', 'Trong ngày hoạn nạn, tôi tìm cầu Chúa; tay tôi giơ lên suốt đêm, không hề mỏi mệt; linh hồn tôi từ chối được an ủi.'),
(15097, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 77, 3, 'OT', 'Tôi nhớ đến Đức Chúa Trời thì bồn chồn; tôi than thở, và thần linh tôi sờn mỏi.'),
(15098, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 77, 4, 'OT', 'Ngài nắm giữ những canh gác của mắt tôi; tôi bồn chồn và không thể nói.'),
(15099, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 77, 5, 'OT', 'Tôi nhớ lại những ngày xưa, những năm xa xưa của muôn đời.'),
(15100, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 77, 6, 'OT', 'Đêm về, tôi nhớ lại bài ca của tôi; lòng tôi suy gẫm, và thần linh tôi tìm tòi kỹ lưỡng.'),
(15101, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 77, 7, 'OT', 'Đức Giê-hô-va há sẽ từ bỏ đến đời đời sao? Ngài há sẽ không còn ban ơn nữa bao giờ?'),
(15102, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 77, 8, 'OT', 'Ân điển của Ngài chăng chẳng còn đến mãi mãi? Lời hứa của Ngài chăng chẳng còn cho đời nầy sang đời khác?'),
(15103, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 77, 9, 'OT', 'Đức Chúa Trời há đã quên làm ơn sao? Hay trong cơn giận Ngài đã khép lại sự thương xót của Ngài?'),
(15104, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 77, 10, 'OT', 'Tôi nói: Chính điều này làm tôi đau buồn; ấy vậy tôi sẽ nhớ đến các năm về tay phải của Đấng Tối Cao.'),
(15105, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 77, 11, 'OT', 'Tôi sẽ nhớ lại các việc làm của Đức Giê-hô-va, Nhớ đến những điều kỳ diệu của Ngài từ xưa.'),
(15106, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 77, 12, 'OT', 'Tôi sẽ suy gẫm về mọi công việc của Ngài, và suy nghĩ về các việc quyền năng của Ngài.'),
(15107, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 77, 13, 'OT', 'Lạy Đức Chúa Trời, đường lối Ngài ở nơi thánh; có thần nào lớn bằng Đức Chúa Trời chúng tôi chăng?'),
(15108, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 77, 14, 'OT', 'Chính Ngài là Đức Chúa Trời làm nên những điều kỳ diệu, đã tỏ quyền năng Ngài ra giữa các dân.'),
(15109, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 77, 15, 'OT', 'Ngài đã dùng tay mình mà chuộc dân Ngài, tức là con cháu của Gia-cốp và Giô-sép.'),
(15110, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 77, 16, 'OT', 'Các nước đã thấy Ngài, hỡi Đức Chúa Trời; các nước đã thấy Ngài bèn run rẩy; chính vực thẳm cũng rúng động.'),
(15111, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 77, 17, 'OT', 'Các đám mây đổ nước xuống, bầu trời phát ra tiếng; ngay cả các tia chớp của Ngài cũng lượn đi lượn lại.'),
(15112, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 77, 18, 'OT', 'Tiếng sấm của Ngài vang dội trong đám mây; chớp giật soi sáng khắp đất; đất rung chuyển và rúng động.'),
(15113, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 77, 19, 'OT', 'Con đường Ngài ở trong biển, lối Ngài đi giữa biển cả mênh mông, và dấu chân Ngài không ai biết được.'),
(15114, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 77, 20, 'OT', 'Ngài đã dẫn dân Ngài như một đoàn chiên, bằng tay Môi-se và A-rôn.'),
(15115, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 1, 'OT', 'Hỡi dân ta, hãy lắng nghe luật pháp ta; hãy nghiêng tai nghe những lời từ miệng ta.'),
(15116, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 2, 'OT', 'Ta sẽ mở miệng nói bằng thí dụ, Bày tỏ những điều bí ẩn từ xưa,'),
(15117, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 3, 'OT', 'Chúng ta đã nghe và biết rõ, tổ phụ chúng ta đã thuật lại cho chúng ta.'),
(15118, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 4, 'OT', 'Chúng tôi sẽ không giấu điều đó khỏi con cái chúng nó, mà sẽ thuật lại cho thế hệ tương lai các sự ngợi khen Đức Giê-hô-va, quyền năng Ngài và những điều kỳ diệu mà Ngài đã làm.'),
(15119, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 5, 'OT', 'Ngài đã lập một bằng chứng nơi Gia-cốp, và đặt một luật lệ trong Y-sơ-ra-ên, mà Ngài đã truyền cho tổ phụ chúng ta phải truyền dạy lại cho con cái họ.'),
(15120, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 6, 'OT', 'Để dòng dõi sau, các con cái sẽ sinh ra, đứng dậy và thuật lại cho con cái mình.'),
(15121, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 7, 'OT', 'Hầu cho lòng chúng nó đặt tin cậy nơi Đức Chúa Trời, không hề quên các việc Ngài làm, và gìn giữ các điều răn của Ngài.'),
(15122, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 8, 'OT', 'để chúng nó không như tổ tiên mình, một dòng dõi lòng chẳng kiên định, chẳng trung thành cùng Đức Chúa Trời.'),
(15123, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 9, 'OT', 'Con cái Eùp-ra-im, những kẻ giữ cung tên, đã quay lưng chạy trốn trong ngày chiến đấu.'),
(15124, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 10, 'OT', 'Chúng không giữ giao ước của Đức Chúa Trời, và từ chối đi theo luật pháp Ngài.'),
(15125, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 11, 'OT', 'Họ đã quên những việc Ngài làm, và các việc kỳ diệu mà Ngài đã cho chúng nó xem thấy.'),
(15126, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 12, 'OT', 'Trước mặt tổ phụ chúng nó, Ngài đã làm những điều kỳ diệu tại đất Ê-díp-tô, trong đồng bằng Xô-an.'),
(15127, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 13, 'OT', 'Ngài chia biển và cho họ đi ngang qua, khiến nước đứng như một đống.'),
(15128, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 14, 'OT', 'Ngài dẫn họ ban ngày bằng mây, và trọn đêm bằng ánh sáng của lửa.'),
(15129, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 15, 'OT', 'Ngài bẻ vỡ các tảng đá trong đồng vắng, và cho uống nước như từ các vực thẳm lớn.'),
(15130, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 16, 'OT', 'Ngài khiến nước rỉ ra từ tảng đá, và làm cho nước chảy xuống như các con sông.'),
(15131, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 17, 'OT', 'Họ lại còn tiếp tục phạm tội cùng Ngài, chống nghịch Đấng Chí Cao trong đồng vắng.'),
(15132, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 18, 'OT', 'Họ thử Đức Chúa Trời trong lòng mình, mà xin thức ăn theo sự thèm muốn của linh hồn.'),
(15133, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 19, 'OT', 'Họ nói nghịch cùng Đức Chúa Trời, mà rằng: Đức Chúa Trời há có thể dọn bàn nơi đồng vắng sao?'),
(15134, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 20, 'OT', 'Kìa, Ngài đã đập vào hòn đá, nước bèn tuôn ra, các dòng sông liền tràn lan; Ngài há chẳng thể nào ban cho bánh sao? Ngài há chẳng thể sắm sửa thịt cho dân Ngài sao?'),
(15135, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 21, 'OT', 'Vì vậy Đức Giê-hô-va nghe thấy và nổi giận; lửa cháy phừng lên nghịch cùng Gia-cốp, và cơn thịnh nộ trỗi lên nghịch cùng Y-sơ-ra-ên.'),
(15136, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 22, 'OT', 'Vì chúng không tin Đức Chúa Trời, cũng chẳng tin cậy nơi sự cứu giúp của Ngài.'),
(15137, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 23, 'OT', 'Nhưng Ngài đã ra lệnh cho các tầng mây ở trên cao, và mở các cửa trời,'),
(15138, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 24, 'OT', 'Giáng xuống cho họ ma-na ăn, và ban cho họ lương thực từ các từng trời.'),
(15139, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 25, 'OT', 'Người ta ăn bánh của đấng quyền năng; Ngài sai đến cho họ thức ăn no đủ.'),
(15140, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 26, 'OT', 'Đức Giê-hô-va khiến gió đông thổi lên trên trời, và nhờ quyền năng Ngài mà dẫn gió nam.'),
(15141, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 27, 'OT', 'Ngài khiến mưa thịt trên chúng nó như bụi đất, và chim có cánh như cát biển;'),
(15142, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 28, 'OT', 'Ngài làm rơi xuống giữa trại quân người, khắp xung quanh nơi ở của họ.'),
(15143, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 29, 'OT', 'Chúng ăn và được no thỏa cách dư dật, và điều ước ao của chúng, Ngài đã ban cho chúng nó.'),
(15144, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 30, 'OT', 'Chúng chưa xa khỏi điều mình thèm muốn, thức ăn còn trong miệng chúng nó.'),
(15145, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 31, 'OT', 'Cơn thịnh nộ của Đức Chúa Trời nổi lên nghịch cùng chúng nó, Ngài giết những người mập mạp trong chúng nó, và đánh ngã những trai trẻ của Y-sơ-ra-ên.'),
(15146, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 32, 'OT', 'Dầu cho mọi điều ấy, chúng vẫn phạm tội và không tin nơi các việc lạ lùng của Ngài.'),
(15147, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 33, 'OT', 'Ngài khiến các ngày đời chúng nó tan biến vô ích, và những năm tháng của chúng nó trong lo lắng bất an.'),
(15148, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 34, 'OT', 'Khi Ngài đánh giết chúng nó, thì chúng nó cầu hỏi Ngài; chúng nó trở lại và sốt sắng tìm cầu Đức Chúa Trời.'),
(15149, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 35, 'OT', 'Chúng nhớ lại rằng Đức Chúa Trời là hòn đá của mình, và Đức Chúa Trời Chí Cao là Đấng cứu chuộc mình.'),
(15150, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 36, 'OT', 'Nhưng chúng nó dùng miệng mình dụ dỗ Ngài, và dùng lưỡi mình nói dối cùng Ngài.'),
(15151, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 37, 'OT', 'Vì lòng chúng nó không ngay thẳng cùng Ngài, cũng không trung tín trong giao ước của Ngài.'),
(15152, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 38, 'OT', 'Nhưng Ngài là Đấng đầy lòng thương xót, sẽ xóa tội lỗi và không tiêu diệt; Ngài thường xuyên dẹp cơn thịnh nộ mình, và không khơi dậy trọn cơn giận dữ của Ngài.'),
(15153, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 39, 'OT', 'Người nhớ lại chúng nó chỉ là xác thịt, là hơi thở qua đi, rồi không trở lại.'),
(15154, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 40, 'OT', 'Biết bao lần chúng nó làm buồn lòng Ngài trong đồng vắng, khiến Ngài phải đau lòng trong nơi khô cằn!'),
(15155, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 41, 'OT', 'Họ lại trở về mà thử Đức Chúa Trời, và thách thức Đấng Thánh của Y-sơ-ra-ên.'),
(15156, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 42, 'OT', 'Chúng không nhớ lại tay Ngài, ngày Ngài chuộc chúng khỏi kẻ hà hiếp.'),
(15157, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 43, 'OT', 'Là Đấng đã đặt các dấu lạ của Ngài tại Ai-cập, và những phép lạ của Ngài trong đồng Xô-an.'),
(15158, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 44, 'OT', 'Chúa đổi các sông và các dòng nước của chúng nó ra huyết, đến nỗi chúng không thể uống được.'),
(15159, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 45, 'OT', 'Ngài sai ruồi muỗi đến giữa họ và nuốt chúng; Ngài sai ếch và chúng tiêu diệt chúng.'),
(15160, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 46, 'OT', 'Ngài phó sản vật của chúng cho châu chấu, và công lao của chúng cho bầy cào cào.'),
(15161, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 47, 'OT', 'Ngài dùng mưa đá đánh chết cây nho của chúng nó, và dùng sương móc hủy hoại cây sung của chúng nó.'),
(15162, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 48, 'OT', 'Ngài phó thành của chúng nó cho mưa đá, và gia súc của chúng nó cho tia chớp.'),
(15163, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 49, 'OT', 'Ngài sai cơn thịnh nộ, cơn giận và sự gian truân của Ngài giáng xuống chúng, tức là một đoàn sứ giả dữ.'),
(15164, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 50, 'OT', 'Ngài định sẵn một con đường cho cơn thịnh nộ Ngài, không để linh hồn họ khỏi chết, mà phó mạng sống chúng nó cho dịch bệnh;'),
(15165, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 51, 'OT', 'Đánh chết mọi con đầu lòng trong xứ Ê-díp-tô, tức đứa cường tráng đầu tiên trong các trại của Hăm.'),
(15166, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 52, 'OT', 'Dân sự Ngài, Ngài dẫn ra như bầy chiên; trong đồng vắng, Ngài dẫn dắt họ như đoàn chiên.'),
(15167, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 53, 'OT', 'Dẫn dắt họ an toàn, họ không sợ hãi; còn biển thì che phủ những kẻ thù nghịch của họ.'),
(15168, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 54, 'OT', 'Ngài dẫn họ đến bờ cõi thánh của Ngài, đến núi mà tay phải Ngài đã đoạt được.'),
(15169, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 55, 'OT', 'Ngài đuổi các dân ra khỏi trước mặt chúng nó, bắt thăm và chia đất làm sản nghiệp cho chúng nó, khiến các chi phái Y-sơ-ra-ên ở trong các trại của các dân ấy.'),
(15170, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 56, 'OT', 'Chúng thử và phản nghịch Đức Chúa Trời Chí cao, không giữ các chứng cớ của Ngài.'),
(15171, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 57, 'OT', 'Họ quay lưng và phản nghịch như tổ tiên mình, trở nên giả dối như cây cung cong vẹo.'),
(15172, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 58, 'OT', 'Chúng nó chọc giận Ngài nơi các nơi cao, và khiến Ngài ghen tuông bởi những tượng chạm của chúng nó.'),
(15173, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 59, 'OT', 'Đức Chúa Trời nghe điều đó, bèn nổi giận, và ghê gớm khinh bỉ Y-sơ-ra-ên quá đỗi;'),
(15174, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 60, 'OT', 'Ngài đã từ bỏ đền tạm tại Si-lô, tức là lều mà Ngài đã dựng giữa loài người.'),
(15175, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 61, 'OT', 'Trao sức mạnh Ngài cho kẻ bắt làm tù, và vinh hiển Ngài nộp vào tay kẻ thù.'),
(15176, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 62, 'OT', 'Ngài phó dân sự Ngài cho lưỡi gươm, và nổi giận cùng cơ nghiệp mình.'),
(15177, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 63, 'OT', 'Lửa thiêu nuốt những thanh niên của Ngài, và các nữ đồng trinh của họ không được hát nghinh.'),
(15178, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 64, 'OT', 'Các thầy tế lễ của chúng nó ngã chết bởi gươm, và các góa phụ của chúng nó không khóc than.'),
(15179, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 65, 'OT', 'Đức Giê-hô-va bèn thức dậy như người từ giấc ngủ, như một dũng sĩ hét vang sau khi uống rượu.'),
(15180, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 66, 'OT', 'Ngài đánh đuổi những kẻ thù nghịch mình ra phía sau; Ngài ban cho chúng sự sỉ nhục đời đời.'),
(15181, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 67, 'OT', 'Ngài từ chối trại của Giô-sép, và không chọn chi phái Eùp-ra-im.'),
(15182, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 68, 'OT', 'Nhưng Ngài chọn chi phái Giu-đa, núi Si-ôn mà Ngài yêu mến.'),
(15183, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 69, 'OT', 'Ngài xây đền thánh của Ngài như nơi cao sang, Khác nào trái đất mà Ngài đã lập bền vững đời đời.'),
(15184, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 70, 'OT', 'Ngài chọn Đa-vít là tôi tớ Ngài, và đem người ấy từ các chuồng chiên.'),
(15185, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 71, 'OT', 'Từ sau các chiên cho bú, Ngài dẫn người đến chăn giữ Gia-cốp, là dân sự Ngài, và Y-sơ-ra-ên, là cơ nghiệp Ngài.'),
(15186, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 78, 72, 'OT', 'Người chăn giữ họ theo sự ngay thẳng của lòng mình, và lấy sự khôn ngoan của tay mình mà dẫn dắt họ.'),
(15187, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 79, 1, 'OT', 'Lạy Đức Chúa Trời, các dân đã xâm nhập vào đất cơ nghiệp của Ngài, làm ô uế đền thánh khiết của Ngài, và biến Giê-ru-sa-lem thành đống đổ nát.'),
(15188, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 79, 2, 'OT', 'Chúng nó đã phó xác các tôi tớ Ngài làm thức ăn cho chim trời, thịt các thánh dân Ngài cho dã thú đất.'),
(15189, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 79, 3, 'OT', 'Chúng đổ máu của họ như nước quanh quanh Giê-ru-sa-lem, và không có ai chôn cất.'),
(15190, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 79, 4, 'OT', 'Chúng tôi đã trở thành sự sỉ nhục cho những kẻ lân cận mình, vật nhạo báng và khinh miệt cho những kẻ xung quanh chúng tôi.'),
(15191, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 79, 5, 'OT', 'Đức Giê-hô-va hỡi, cho đến bao giờ Ngài còn nổi giận đời đời? Sự nóng lòng của Ngài há sẽ bốc lên như lửa?'),
(15192, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 79, 6, 'OT', 'Xin đổ cơn thịnh nộ của Ngài trên các dân không biết Ngài, và trên các nước không kêu cầu danh Ngài.'),
(15193, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 79, 7, 'OT', 'Vì chúng đã ăn nuốt Gia-cốp, và làm cho nơi ở của người trở nên hoang vu.'),
(15194, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 79, 8, 'OT', 'Xin chớ nhớ lại cho chúng tôi các tội lỗi thuở ban đầu; nguyện sự thương xót của Đức Giê-hô-va mau mau đến đón gặp chúng tôi, vì chúng tôi đã khốn khổ quá mức.'),
(15195, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 79, 9, 'OT', 'Hỡi Đức Chúa Trời về sự cứu rỗi chúng tôi, vì vinh hiển danh Ngài, xin giúp đỡ chúng tôi; xin giải cứu chúng tôi và xá tội cho chúng tôi, vì danh Ngài.'),
(15196, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 79, 10, 'OT', 'Tại sao các dân lại nói: Đức Chúa Trời của họ đâu rồi? Nguyện sự báo thù huyết các tôi tớ Ngài, huyết đã đổ ra, được tỏ ra giữa các dân, ngay trước mắt chúng tôi.'),
(15197, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 79, 11, 'OT', 'Nguyện tiếng kêu của người bị xiềng xích thấu đến trước mặt Ngài; tùy theo quyền năng lớn lao của Ngài, xin hãy giải cứu những con cái bị định chết.'),
(15198, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 79, 12, 'OT', 'Xin hãy hoàn trả cho những kẻ lân cận chúng tôi bảy lần vào lòng chúng nó sự sỉ nhục mà chúng đã sỉ vả Ngài, hỡi Chúa.'),
(15199, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 79, 13, 'OT', 'Còn chúng tôi là dân sự Ngài và là bầy chiên trong đồng cỏ Ngài, chúng tôi sẽ cảm tạ Ngài đời đời, từ thế hệ này sang thế hệ kia, chúng tôi sẽ thuật lại sự ngợi khen Ngài.'),
(15200, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 80, 1, 'OT', 'Đấng dẫn dắt Y-sơ-ra-ên, hãy lắng nghe, Đấng chăn giữ như bầy chiên Gia-cốp; hỡi Đấng ngự trên các chê-ru-bim, hãy hiện ra.'),
(15201, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 80, 2, 'OT', 'Trước mặt Eùp-ra-im, Bên-gia-min và Ma-na-se, xin hãy làm cho sức mạnh Ngài thức tỉnh, và ngự đến đặng cứu giúp chúng tôi.'),
(15202, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 80, 3, 'OT', 'Đức Chúa Trời, xin hãy khiến chúng tôi trở lại; và làm sáng mặt Ngài, thì chúng tôi sẽ được cứu.'),
(15203, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 80, 4, 'OT', 'Hỡi Đức Giê-hô-va, Đức Chúa Trời vạn quân, cho đến chừng nào Ngài còn nổi giận lời cầu nguyện của dân Ngài?'),
(15204, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 80, 5, 'OT', 'Ngài khiến họ ăn bánh bằng nước mắt, và cho họ uống nước mắt đầy ba đấu.'),
(15205, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 80, 6, 'OT', 'Ngài khiến chúng tôi trở thành đối tượng tranh cãi cho những người láng giềng mình, và kẻ thù nghịch chúng tôi thì cùng nhau chế giễu chúng tôi.'),
(15206, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 80, 7, 'OT', 'Hỡi Đức Chúa Trời vạn quân, xin hãy khiến chúng tôi trở lại, và soi sáng mặt Ngài, thì chúng tôi sẽ được cứu.'),
(15207, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 80, 8, 'OT', 'Chúa đã đem một cây nho từ Ai Cập mà dời đi; Chúa đuổi các dân ra khỏi đất, rồi trồng cây nho ấy.'),
(15208, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 80, 9, 'OT', 'Ngài dọn đường trước mặt nó, nó đâm rễ, và trải đầy đất.'),
(15209, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 80, 10, 'OT', 'Các núi bị bóng của nó che phủ, và các nhánh của nó là những cây bách của Đức Chúa Trời.'),
(15210, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 80, 11, 'OT', 'Ngài đã sai các nhánh nó đến biển, và các tua nó đến sông.'),
(15211, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 80, 12, 'OT', 'Vì sao Ngài phá đổ hàng rào của nó, để mọi kẻ qua đường hái lấy nó?'),
(15212, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 80, 13, 'OT', 'Heo rừng cắn phá nó, và các loài thú đồng ăn nó.'),
(15213, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 80, 14, 'OT', 'Đức Chúa Trời vạn quân ôi, xin hãy trở lại, xin hãy nhìn từ trên trời và xem, hãy đoái thăm cây nho nầy,'),
(15214, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 80, 15, 'OT', 'Là cây nho mà tay phải Ngài đã trồng, và là cây con mà Ngài đã củng cố cho mình.'),
(15215, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 80, 16, 'OT', 'Cây nho ấy bị lửa thiêu đốt, bị cháy trụi; vì sự quở trách nơi mặt Ngài, chúng nó bị tiêu diệt.'),
(15216, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 80, 17, 'OT', 'Nguyện tay Ngài phù hộ cho người ở bên tay phải Ngài, cho con người mà Ngài đã chọn cho mình.'),
(15217, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 80, 18, 'OT', 'Chúng tôi sẽ không rút lui khỏi Ngài; xin khiến chúng tôi được sống lại, và chúng tôi sẽ kêu cầu danh Ngài.'),
(15218, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 80, 19, 'OT', 'Hỡi Đức Giê-hô-va Đức Chúa Trời vạn quân, xin hãy đem chúng tôi trở lại; làm cho mặt Ngài sáng lên thì chúng tôi sẽ được cứu.'),
(15219, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 81, 1, 'OT', 'Hãy hát reo cho Đức Chúa Trời là sức lực chúng ta; hãy reo vui cho Đức Chúa Trời của Gia-cốp.'),
(15220, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 81, 2, 'OT', 'Hãy dâng bài ca và gõ trống, cây đờn cầm và cây đờn sắt vang lời hòa âm.'),
(15221, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 81, 3, 'OT', 'Hãy thổi rợn trong tháng mới, và thổi loa trong ngày lễ trăng tròn của chúng ta.'),
(15222, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 81, 4, 'OT', 'Vì ấy là một luật lệ cho Y-sơ-ra-ên, Một điều lệ của Đức Chúa Trời Gia-cốp.'),
(15223, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 81, 5, 'OT', 'Ngài lập một bằng chứng nơi Giô-sép, khi Ngài ra khỏi đất Ai-cập; tôi nghe một thứ tiếng mà tôi không hiểu.'),
(15224, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 81, 6, 'OT', 'Ta đã dỡ gánh nặng khỏi vai người; tay người khỏi thùng đựng gạch đã được buông ra.'),
(15225, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 81, 7, 'OT', 'Trong lúc gian nan, ngươi kêu cầu, và Ta giải cứu ngươi; Ta đáp lời ngươi từ nơi khuất sau tiếng sấm sét; Ta thử thách ngươi bên những dòng nước Mê-ri-ba.'),
(15226, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 81, 8, 'OT', 'Hỡi dân ta, hãy nghe, ta sẽ làm chứng cho ngươi: ù Y-sơ-ra-ên! Nếu ngươi khứng nghe ta!'),
(15227, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 81, 9, 'OT', 'Giữa ngươi không được có thần nào khác, và ngươi cũng không được thờ lạy thần của người ngoại.'),
(15228, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 81, 10, 'OT', 'Ta là Đức Giê-hô-va, Đức Chúa Trời ngươi, Đấng đem ngươi lên khỏi đất Ai Cập; hãy mở miệng ngươi ra, thì ta sẽ làm đầy nó.'),
(15229, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 81, 11, 'OT', 'Nhưng dân ta không chịu nghe tiếng ta, Y-sơ-ra-ên không chịu vâng theo ta.'),
(15230, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 81, 12, 'OT', 'Ta để mặc chúng theo sự cứng lòng trong lòng chúng nó, để chúng đi theo mưu kế của mình.'),
(15231, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 81, 13, 'OT', 'Ôi! chớ chi dân ta nghe ta! Y-sơ-ra-ên bước đi trong đường lối ta!'),
(15232, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 81, 14, 'OT', 'Thì chẳng bao lâu ta bắt các kẻ thù nghịch nó phải khuất phục, và trở tay ta nghịch cùng những kẻ ghét nó.'),
(15233, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 81, 15, 'OT', 'Những kẻ ghét Đức Giê-hô-va sẽ phải giả hàng Ngài; còn dân ta sẽ sống đến đời đời.'),
(15234, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 81, 16, 'OT', 'Ta sẽ cho người ăn màu mỡ của lúa mì; từ hòn đá, Ta sẽ làm cho ngươi no nê bằng mật ong.'),
(15235, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 82, 1, 'OT', 'Thi-thiên của A-sáp. Đức Chúa Trời đứng trong hội của Ðức Chúa Trời; Ngài đoán xét giữa các thần.'),
(15236, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 82, 2, 'OT', 'Các ngươi sẽ đoán xét điều gian ác, và thiên vị mặt kẻ ác cho đến bao giờ?'),
(15237, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 82, 3, 'OT', 'Hãy xét xử người nghèo và kẻ mồ côi, xử công bình cho người khốn khổ và kẻ túng thiếu.'),
(15238, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 82, 4, 'OT', 'Hãy giải cứu kẻ khốn cùng và người nghèo khó, giải thoát họ khỏi tay những kẻ gian ác.'),
(15239, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 82, 5, 'OT', 'Chúng không biết, chẳng hiểu gì; chúng đi lại trong bóng tối; mọi nền đất đều chao đảo.'),
(15240, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 82, 6, 'OT', 'Ta đã nói: Các ngươi là thần, và hết thảy các ngươi đều là con trai của Đấng Chí Cao.'),
(15241, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 82, 7, 'OT', 'Quả thật, các ngươi sẽ chết như loài người, và ngã xuống như một viên quan trưởng.'),
(15242, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 82, 8, 'OT', 'Hỡi Đức Chúa Trời, hãy chỗi dậy, đoán xét đất; vì chính Ngài sẽ được hưởng muôn dân làm cơ nghiệp.'),
(15243, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 83, 1, 'OT', 'Một bài ca, một bài thơ thiêng của A-sáp. Đức Chúa Trời ôi, xin chớ làm thinh; Đức Chúa Trời ôi, xin chớ nín lặng, chớ đứng yên.'),
(15244, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 83, 2, 'OT', 'Kìa, các kẻ thù nghịch Ngài đang náo loạn, và những kẻ ghét Ngài đang ngước đầu lên.'),
(15245, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 83, 3, 'OT', 'Chúng bày mưu nghịch cùng dân Ngài, cùng bàn kế chống lại những người Ngài che giấu.'),
(15246, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 83, 4, 'OT', 'Chúng nó nói: Hãy đến, ta sẽ tiêu diệt chúng nó đến nỗi không còn là một dân tộc nữa, hầu cho danh Y-sơ-ra-ên không còn được nhắc đến mãi mãi.'),
(15247, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 83, 5, 'OT', 'Vì chúng nó đồng lòng bàn mưu, lập giao ước nghịch cùng Đức Giê-hô-va.'),
(15248, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 83, 6, 'OT', 'Những trại của Ê-đôm và người Ích-ma-ên, Mô-áp và người Ha-ga-rít.'),
(15249, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 83, 7, 'OT', 'Ghê-banh, Am-môn, và A-ma-léc, cùng dân Phi-li-tin ở với những người sống tại Ty-rơ;'),
(15250, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 83, 8, 'OT', 'A-si-ri cũng liên kết với chúng, trở thành cánh tay cho con cháu Lót.'),
(15251, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 83, 9, 'OT', 'Xin hãy đãi chúng nó như Ma-đi-an, như Si-sê-ra, như Gia-bin tại khe Ki-sôn,'),
(15252, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 83, 10, 'OT', 'Bị tiêu diệt tại Eân-Đô-rơ, trở nên tro bụi cho đất.'),
(15253, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 83, 11, 'OT', 'Hãy khiến các lãnh tụ của chúng nó như Ô-rép và Xê-ép, và hết thảy các quan trưởng của chúng nó như Xê-bách và Xanh-mu-na;'),
(15254, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 83, 12, 'OT', 'Vì chúng nó nói rằng: Hãy chiếm lấy cho chúng ta các nơi ở của Đức Chúa Trời.'),
(15255, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 83, 13, 'OT', 'Lạy Đức Chúa Trời tôi, xin khiến chúng nó như bánh xe cuộn tròn, như rơm rạ trước mặt gió.'),
(15256, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 83, 14, 'OT', 'Như lửa thiêu đốt rừng, như ngọn lửa bừng cháy núi.'),
(15257, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 83, 15, 'OT', 'Như vậy, xin đuổi chúng nó trong cơn gió lốc của Ngài, và trong trận cuồng phong của Ngài khiến chúng nó khiếp sợ.'),
(15258, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 83, 16, 'OT', 'Xin làm đầy mặt chúng nó sự hổ nhục, để chúng nó tìm kiếm danh Ngài, Đức Giê-hô-va.'),
(15259, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 83, 17, 'OT', 'Nguyện chúng nó bị hổ thẹy và bối rối mãi mãi; nguyện chúng nó bị nhục nhã và tiêu vong.'),
(15260, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 83, 18, 'OT', 'Hầu cho chúng nó biết rằng chỉ một mình Ngài, danh Ngài là Đức Giê-hô-va, là Đấng Tối Cao trên khắp đất.'),
(15261, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 84, 1, 'OT', 'Lạy Đức Giê-hô-va vạn quân, những nơi ở của Ngài thật là đáng yêu!'),
(15262, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 84, 2, 'OT', 'Linh hồn tôi khao khát, thậm chí hao mòn, về các hành lang của Đức Giê-hô-va; lòng tôi và thịt tôi reo lên về Đức Chúa Trời hằng sống.'),
(15263, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 84, 3, 'OT', 'Cả chim sẻ cũng tìm được nhà, và chim én tìm được tổ cho mình, để đẻ con nó, ngay bên bàn thờ của Ngài, hỡi Đức Giê-hô-va vạn quân, là Vua tôi và Đức Chúa Trời tôi.'),
(15264, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 84, 4, 'OT', 'Phước cho những kẻ ở trong nhà Ngài, họ sẽ còn luôn ngợi khen Ngài.'),
(15265, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 84, 5, 'OT', 'Phước cho người nào có sức mạnh trong Ngài; lòng họ hướng về các đường dẫn đến Si-ôn.'),
(15266, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 84, 6, 'OT', 'Đi qua thung lũng Bác-a, họ biến nơi ấy thành suối nguồn; mưa đầu mùa cũng phủ phước cho nó.'),
(15267, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 84, 7, 'OT', 'Họ đi từ sức mạnh nầy đến sức mạnh khác, ra mắt Đức Chúa Trời tại Si-ôn.'),
(15268, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 84, 8, 'OT', 'Hỡi Đức Giê-hô-va, Đức Chúa Trời vạn quân, xin hãy nghe lời cầu nguyện tôi; xin hãy lắng tai nghe, hỡi Đức Chúa Trời của Gia-cốp.'),
(15269, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 84, 9, 'OT', 'Hỡi Đức Chúa Trời, là mộc khiên của chúng tôi, xin hãy nhìn xem và đoái đến mặt của Đấng chịu xức dầu của Ngài.'),
(15270, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 84, 10, 'OT', 'Vì một ngày trong hành lang của Ngài tốt hơn ngàn ngày; tôi đã chọn làm kẻ đứng gác trong nhà Đức Chúa Trời tôi, hơn là ở trong trại của kẻ ác.'),
(15271, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 84, 11, 'OT', 'Vì Đức Giê-hô-va Đức Chúa Trời là mặt trời và là cái khiên; ơn và vinh hiển, Đức Giê-hô-va sẽ ban cho; Ngài sẽ không từ chối điều lành nào cho những ai sống trọn vẹn.'),
(15272, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 84, 12, 'OT', 'Hỡi Đức Giê-hô-va vạn quân, phước cho người nào tin cậy nơi Ngài!'),
(15273, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 85, 1, 'OT', 'Đức Giê-hô-va đã đoái thương cho đất nước Ngài, khiến Gia-cốp trở lại từ nơi bị lưu đày.'),
(15274, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 85, 2, 'OT', 'Ngài đã mang lấy gian ác của dân Ngài, che phủ mọi tội lỗi của họ.'),
(15275, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 85, 3, 'OT', 'Ngài đã thu lại mọi cơn thạnh nộ của Ngài, và nguôi đi cơn giận dữ về cơn thịnh nộ của Ngài.'),
(15276, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 85, 4, 'OT', 'Đức Chúa Trời về sự cứu rỗi chúng tôi, xin hãy khiến chúng tôi trở lại, và quay khỏi cơn thạnh nộ của Ngài đối với chúng tôi.'),
(15277, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 85, 5, 'OT', 'Đức Giê-hô-va há sẽ nổi giận chúng tôi mãi mãi sao? Ngài há sẽ kéo dài cơn thịnh nộ Ngài qua đời này sang đời khác?'),
(15278, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 85, 6, 'OT', 'Chẳng phải chính Ngài sẽ khiến chúng tôi sống lại sao? Dân Ngài sẽ vui vẻ trong Ngài.'),
(15279, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 85, 7, 'OT', 'Hãy cho chúng tôi thấy sự nhân từ của Đức Giê-hô-va, Và sự cứu rỗi của Ngài, xin ban cho chúng tôi.'),
(15280, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 85, 8, 'OT', 'Tôi sẽ lắng nghe điều Đức Giê-hô-va phán; vì Đức Giê-hô-va sẽ phán sự bình an cho dân sự Ngài và cho những người thánh của Ngài; và chớ có ai trở lại sự ngu dại.'),
(15281, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 85, 9, 'OT', 'Sự cứu rỗi của Ngài thật gần những kẻ kính sợ Ngài, để sự vinh hiển được ngự trong đất nước chúng ta.'),
(15282, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 85, 10, 'OT', 'Ơn nhân từ và lẽ thật gặp nhau; sự công chính và sự bình an hôn nhau.'),
(15283, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 85, 11, 'OT', 'Sự thật sẽ nứt ra từ đất, và sự công chính sẽ nhìn xuống từ trời.'),
(15284, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 85, 12, 'OT', 'Phải, Đức Giê-hô-va sẽ ban điều tốt lành, và đất chúng ta sẽ sinh sản hoa lợi nó.'),
(15285, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 85, 13, 'OT', 'Sự công chính sẽ đi trước mặt Ngài, và đặt con đường cho các bước chân của Ngài.'),
(15286, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 86, 1, 'OT', 'Lời cầu nguyện của Đa-vít. Đức Giê-hô-va, xin nghiêng tai Ngài về tôi, nhậm lời tôi; vì tôi khốn khổ và nghèo hèn.'),
(15287, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 86, 2, 'OT', 'Xin hãy giữ gìn linh hồn tôi, vì tôi là người nhân từ; xin hãy cứu kẻ tôi tớ Ngài, Đức Chúa Trời tôi ôi, là người tin cậy nơi Ngài.'),
(15288, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 86, 3, 'OT', 'Xin thương xót tôi, Đức Giê-hô-va, vì tôi kêu cầu Ngài suốt cả ngày.'),
(15289, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 86, 4, 'OT', 'Xin hãy làm vui vẻ linh hồn kẻ tôi tớ Ngài, vì, Đức Giê-hô-va ôi! linh hồn tôi ngước về Ngài.'),
(15290, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 86, 5, 'OT', 'Vì Đức Giê-hô-va là thiện, dễ tha thứ, và đầy dẫy sự nhân từ đối với mọi người kêu cầu cùng Ngài.'),
(15291, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 86, 6, 'OT', 'Hỡi Đức Giê-hô-va, xin hãy lắng nghe lời cầu nguyện tôi, và hãy chăm chú đến tiếng kêu xin của tôi.'),
(15292, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 86, 7, 'OT', 'Trong ngày hoạn nạn, tôi sẽ kêu cầu Ngài, vì Ngài sẽ nhậm lời tôi.'),
(15293, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 86, 8, 'OT', 'Lạy Đức Giê-hô-va, không có ai giống như Ngài giữa các thần, và chẳng có việc gì giống như các việc Ngài làm.'),
(15294, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 86, 9, 'OT', 'Hết thảy các dân mà Đức Giê-hô-va đã làm nên sẽ đến thờ lạy trước mặt Ngài, và tôn vinh danh Ngài.'),
(15295, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 86, 10, 'OT', 'Vì Đức Giê-hô-va là rất lớn và làm những sự lạ lùng; chỉ một mình Đức Chúa Trời mà thôi.'),
(15296, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 86, 11, 'OT', 'Hỡi Đức Giê-hô-va, xin dạy tôi đường lối Ngài, để tôi đi trong sự thật của Ngài; xin làm cho lòng tôi được hiệp nhất để kính sợ danh Ngài.'),
(15297, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 86, 12, 'OT', 'Lạy Đức Giê-hô-va, là Đức Chúa Trời tôi, tôi sẽ hết lòng cảm tạ Ngài, và sẽ tôn vinh danh Ngài đời đời.'),
(15298, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 86, 13, 'OT', 'Vì tình yêu thương lớn lao của Đức Giê-hô-va đối với tôi, Ngài đã cứu lấy mạng sống tôi khỏi hầm sâu dưới đất.'),
(15299, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 86, 14, 'OT', 'Lạy Đức Chúa Trời, những kẻ kiêu ngạo đã dấy lên nghịch cùng tôi, và một hội người hung bạo tìm hại mạng sống tôi; chúng nó không đặt Đức Giê-hô-va trước mặt mình.'),
(15300, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 86, 15, 'OT', 'Nhưng, Đức Giê-hô-va ơi, Ngài là Đức Chúa Trời đầy lòng thương xót và nhân từ, chậm nóng giận, có lòng nhân từ và sự thật dồi dào.'),
(15301, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 86, 16, 'OT', 'Xin Đức Giê-hô-va đoái lại cùng tôi và thương xót tôi; xin ban sức lực Ngài cho kẻ tôi tớ Ngài, và cứu con trai của người nữ tôi tớ Ngài.'),
(15302, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 86, 17, 'OT', 'Xin Đức Giê-hô-va làm một dấu lạ tốt lành cho tôi, để kẻ ghét tôi thấy mà xấu hổ; vì chính Đức Giê-hô-va đã giúp đỡ tôi và an ủi tôi.'),
(15303, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 87, 1, 'OT', 'Dành cho các con trai Kô-rách, một bài thơ ca. Nền tảng của nó ở trên các núi thánh.'),
(15304, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 87, 2, 'OT', 'Đức Giê-hô-va yêu các cửa Si-ôn Hơn mọi nơi ở của Gia-cốp.'),
(15305, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 87, 3, 'OT', 'Đã nói những điều vinh hiển về ngươi, hỡi thành của Đức Chúa Trời.'),
(15306, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 87, 4, 'OT', 'Ta sẽ nhắc đến Ra-háp và Ba-by-lôn, là những người biết ta; Kìa, Phi-li-tin và Ty-rơ cùng với Cúch; người nầy đã sinh ra tại Si-ôn.'),
(15307, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 87, 5, 'OT', 'Và về Si-ôn người ta sẽ nói: Người nầy và người nầy được sinh ra trong đó; chính Đấng Chí Cao sẽ lập vững Si-ôn.'),
(15308, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 87, 6, 'OT', 'Đức Giê-hô-va sẽ ghi trong sách các dân, rằng: Người nầy đã sinh tại Si-ôn.'),
(15309, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 87, 7, 'OT', 'Các quan trưởng đều như những người múa hát; mọi suối nước của tôi đều ở trong ngươi.'),
(15310, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 88, 1, 'OT', 'Lời cầu nguyện của Hê-man, người Ê-xơ-ra-hít. Hỡi Đức Giê-hô-va, Đức Chúa Trời về sự cứu rỗi tôi, ngày và đêm tôi kêu cầu trước mặt Ngài.'),
(15311, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 88, 2, 'OT', 'Nguyện lời cầu nguyện tôi đến trước mặt Đức Giê-hô-va; xin nghiêng tai Ngài đến nghe tiếng kêu cứu tôi.'),
(15312, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 88, 3, 'OT', 'Vì linh hồn tôi đã đầy dẫy điều bất hạnh, và mạng sống tôi đã đến gần âm phủ.'),
(15313, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 88, 4, 'OT', 'Tôi bị kể như những kẻ xuống hầm mỏ, trở nên người không sức lực.'),
(15314, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 88, 5, 'OT', 'Bị bỏ giữa những kẻ chết, như những người đã chết nằm trong mồ mả, mà Ngài không còn nhớ đến nữa; họ bị cắt đứt khỏi tay Ngài.'),
(15315, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 88, 6, 'OT', 'Người đã đặt tôi xuống hầm sâu tối tăm, trong vực thẳm.'),
(15316, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 88, 7, 'OT', 'Cơn thịnh nộ của Đức Giê-hô-va đè nặng trên tôi, và mọi con sóng dữ dội của Ngài khiến tôi khốn khổ.'),
(15317, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 88, 8, 'OT', 'Ngài đã khiến những người quen biết tôi xa cách tôi, đặt tôi thành điều đáng ghét đối với họ; tôi bị giam hãm, không thể ra được.'),
(15318, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 88, 9, 'OT', 'Mắt tôi hao mòn vì hoạn nạn; tôi kêu cầu Đức Giê-hô-va hằng ngày, giơ tay hướng về Ngài.'),
(15319, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 88, 10, 'OT', 'Chúa há sẽ làm phép lạ cho những kẻ chết sao? Những kẻ được chữa lành há sẽ chỗi dậy ngợi khen Chúa sao?'),
(15320, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 88, 11, 'OT', 'Sự nhân từ của Đức Giê-hô-va há sẽ được kể trong mồ mả sao? Sự trung thực của Ngài há sẽ được loan báo trong vực thẳm?'),
(15321, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 88, 12, 'OT', 'Các phép lạ của Đức Giê-hô-va há sẽ được biết trong nơi tối tăm sao? Và sự công bình của Ngài há sẽ được tỏ ra trong vùng đất bị lãng quên?'),
(15322, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 88, 13, 'OT', 'Còn tôi, tôi kêu cứu cùng Đức Giê-hô-va; và ngay buổi sáng, lời cầu nguyện của tôi sẽ đến trước mặt Ngài.'),
(15323, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 88, 14, 'OT', 'Đức Giê-hô-va ôi, vì sao Ngài từ bỏ linh hồn tôi, giấu mặt Ngài khỏi tôi?'),
(15324, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 88, 15, 'OT', 'Tôi đây khốn khổ và gần chết từ buổi thơ ấu; tôi mang những kinh khiếp của Ngài, lòng hoảng hốt.'),
(15325, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 88, 16, 'OT', 'Các cơn thạnh nộ của Đức Giê-hô-va đã tràn trên tôi; các sự hãi hùng của Ngài đã đè ép tôi.'),
(15326, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 88, 17, 'OT', 'Hằng ngày, chúng vây quanh tôi như nước; cùng nhau xúm lại nghịch tôi.'),
(15327, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 88, 18, 'OT', 'Người đã khiến bạn hữu và người quen biết của tôi xa cách tôi, và họ ẩn mình trong bóng tối.'),
(15328, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 1, 'OT', 'Là người hiểu biết, của Ê-than, người Ê-xơ-ra-hi: Tôi sẽ hát mãi về các ân đức của Đức Giê-hô-va; qua mọi thế hệ, tôi sẽ rao ra sự trung tín của Ngài bằng miệng tôi.'),
(15329, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 2, 'OT', 'Vì tôi đã nói: Lòng thương xót sẽ được lập định đời đời; trên các từng trời, sự thành tín Ngài sẽ được lập vững bền.'),
(15330, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 3, 'OT', 'Ta đã lập giao ước với Đa-vít, kẻ được chọn của ta; Ta đã chỉ Đức Giê-hô-va mà thề cùng Đa-vít, kẻ tôi tớ ta.'),
(15331, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 4, 'OT', 'Ta sẽ thiết lập dòng dõi ngươi đến muôn đời, và xây ngôi ngươi cho đến các thế hệ, mãi mãi.'),
(15332, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 5, 'OT', 'Các từng trời sẽ ca ngợi những điều kỳ diệu của Đức Giê-hô-va; sự trung thành của Ngài cũng sẽ được ca ngợi trong hội các thánh.'),
(15333, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 6, 'OT', 'Vì ai trên các từng trời có thể sánh bằng Đức Giê-hô-va? Ai trong các con trai của Đức Chúa Trời có thể giống như Đức Giê-hô-va?'),
(15334, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 7, 'OT', 'Đức Chúa Trời rất đáng kính sợ trong hội các thánh, đầy quyền năng và đáng sợ hơn mọi kẻ chầu chung quanh Ngài.'),
(15335, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 8, 'OT', 'Hỡi Đức Giê-hô-va Đức Chúa Trời vạn quân, ai giống như Ngài, Đấng quyền năng và thánh khiết? Sự thành tín của Ngài bao quanh Ngài.'),
(15336, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 9, 'OT', 'Chúa cai trị sự kiêu căng của biển; khi các đợt sóng dâng lên, Chúa làm cho chúng nó im lặng.'),
(15337, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 10, 'OT', 'Chính Ngài đã nghiền nát Ra-háp như một người đã chết, dùng cánh tay quyền năng của Ngài, Ngài đã xua tan những kẻ thù nghịch mình.'),
(15338, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 11, 'OT', 'Các từng trời thuộc về Ngài, đất cũng thuộc về Ngài; thế gian và mọi vật chứa đựng trong đó, chính Ngài đã lập nên.'),
(15339, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 12, 'OT', 'Phía Bắc và phía Nam, chính Ngài đã tạo nên; Tha-bô và Hẹt-môn đều reo mừng vì danh Ngài.'),
(15340, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 13, 'OT', 'Danh cho Ngài là cánh tay cùng quyền năng; tay Ngài trở nên mạnh mẽ, tay phải Ngài được nhắc cao lên.'),
(15341, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 14, 'OT', 'Công bình và chính trực là nền của ngôi báu Ngài; nhân từ và chân thật đi trước mặt Ngài.'),
(15342, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 15, 'OT', 'Phước thay cho dân biết tiếng reo hò! Hỡi Đức Giê-hô-va, họ bước đi trong ánh sáng của mặt Ngài.'),
(15343, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 16, 'OT', 'Hằng ngày họ sẽ vui mừng trong danh Ngài, và nhờ sự công bình của Ngài mà được nhắc cao lên.'),
(15344, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 17, 'OT', 'Vì chính Ngài là sự vinh hiển về sức mạnh của họ; nhờ ơn Ngài, sừng chúng tôi sẽ được ngước cao lên.'),
(15345, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 18, 'OT', 'Vì Đức Giê-hô-va là cái khiên của chúng tôi, và Đấng Thánh của Y-sơ-ra-ên là Vua chúng tôi.'),
(15346, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 19, 'OT', 'Bấy giờ, trong sự hiện thấy, Ngài phán cùng người trung tín của Ngài, rằng: Ta đã đặt một đấng phù trợ trên người hùng dũng, Ta đã nâng cao một thanh niên từ giữa dân chúng.'),
(15347, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 20, 'OT', 'Ta đã tìm được Đa-vít, là tôi tớ ta, xức cho người bằng dầu thánh ta.'),
(15348, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 21, 'OT', 'Tay ta sẽ lập vững người, và cánh tay ta sẽ làm cho người vững mạnh.'),
(15349, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 22, 'OT', 'Kẻ thù sẽ không áp bức người, và con trai kẻ ác cũng sẽ không làm khổ người.'),
(15350, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 23, 'OT', 'Ta sẽ đánh bại những kẻ áp bức người ra khỏi trước mặt người, và những kẻ ghét người, Ta sẽ đánh phạt.'),
(15351, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 24, 'OT', 'Sự thành tín và lòng nhân từ của Ta sẽ ở cùng người; nhờ danh Ta, sừng người sẽ được nâng cao.'),
(15352, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 25, 'OT', 'Ta sẽ đặt tay người trên biển, và tay phải người trên các con sông.'),
(15353, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 26, 'OT', 'Người sẽ kêu cùng ta rằng: Cha ta là Ngài, Đức Chúa Trời tôi và hòn đá cứu rỗi tôi.'),
(15354, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 27, 'OT', 'Ta sẽ đặt người làm con cả, cao cả hơn các vua trên đất.'),
(15355, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 28, 'OT', 'Ta sẽ luôn giữ lòng nhân từ dành cho người đến muôn đời, và giao ước Ta lập với người sẽ được giữ vững chắc.'),
(15356, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 29, 'OT', 'Ta sẽ làm cho dòng dõi người còn mãi mãi, và ngôi vua người còn lâu dài như các ngày trên trời.'),
(15357, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 30, 'OT', 'Nếu con cháu nó từ bỏ luật pháp ta, không đi theo các mạng lịnh ta,'),
(15358, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 31, 'OT', 'Nếu chúng nó làm ô uế các luật lệ ta, và không giữ các mệnh lệnh ta,'),
(15359, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 32, 'OT', 'Thì ta sẽ dùng roi đánh phạt sự phạm tội của chúng nó, và lấy những vết thương mà phạt sự gian ác của chúng nó.'),
(15360, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 33, 'OT', 'Nhưng sự nhân từ của Ta sẽ không rút lui khỏi người, và Ta sẽ không vi phạm sự trung thực của Ta.'),
(15361, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 34, 'OT', 'Ta sẽ không hủy bỏ giao ước Ta, và điều ra từ môi miệng Ta, Ta sẽ không thay đổi.'),
(15362, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 35, 'OT', 'Ta đã chỉ sự thánh của Ta mà thề một lần, chẳng hề nói dối với Đa-vít:'),
(15363, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 36, 'OT', 'Dòng dõi người sẽ còn đời đời, và ngôi người sẽ còn như mặt trời trước mặt ta.'),
(15364, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 37, 'OT', 'Ngôi ấy sẽ được lập vững bền đời đời như mặt trăng, và nhân chứng trung thành nơi tầng trời thì chắc thật.'),
(15365, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 38, 'OT', 'Nhưng Ngài đã từ chối và khinh dể, nổi giận cùng đấng chịu xức dầu của Ngài.'),
(15366, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 39, 'OT', 'Ngài đã làm cho giao ước của đầy tớ Ngài bị khinh dể, và ném xuống đất mão triều của người.'),
(15367, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 40, 'OT', 'Ngài đã phá vỡ mọi hàng rào của nó, đặt các đồn lũy của nó trở thành nơi sụp đổ.'),
(15368, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 41, 'OT', 'Hết thảy những kẻ qua đường đều cướp giật người ấy; người đã trở nên sự nhục nhã cho những kẻ lân cận mình.'),
(15369, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 42, 'OT', 'Người đã nâng cao tay các kẻ thù nghịch người, khiến mọi kẻ thù người vui vẻ.'),
(15370, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 43, 'OT', 'Nhưng Ngài làm cho lưỡi gươm người quay trở lại, và không giúp người đứng vững trong trận chiến.'),
(15371, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 44, 'OT', 'Ngài đã khiến sự rực rỡ của người phải ngưng lại, và ngôi người thì Ngài đã ném xuống đất.'),
(15372, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 45, 'OT', 'Người đã rút ngắn những ngày thanh xuân của người ấy, và phủ kín người ấy bằng sự hổ thẹn.'),
(15373, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 46, 'OT', 'Đức Giê-hô-va ôi, Ngài sẽ ẩn mình cho đến bao lâu? Cơn thạnh nộ của Ngài sẽ cháy như lửa mãi mãi sao?'),
(15374, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 47, 'OT', 'Lạy Đức Giê-hô-va, xin nhớ tôi là loài người chóng tàn; loài người mà Ngài đã dựng nên đều hư không là thể nào!'),
(15375, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 48, 'OT', 'Người nào là người sống mà không thấy sự chết? Ai sẽ cứu lấy linh hồn mình khỏi tay Âm phủ?'),
(15376, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 49, 'OT', 'Lạy Đức Giê-hô-va, những ân huệ thuở ban đầu của Ngài ở đâu, mà Ngài đã chỉ Đức trung tín mình mà thề cùng Đa-vít?'),
(15377, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 50, 'OT', 'Lạy Đức Giê-hô-va, xin nhớ sự sỉ nhục của các tôi tớ Ngài; tôi đã mang trong lòng sự sỉ nhục của nhiều dân tộc,'),
(15378, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 51, 'OT', 'Hỡi Đức Giê-hô-va, ấy là sự sỉ nhục mà kẻ thù nghịch Ngài đã dùng để sỉ nhục các bước chân của Đấng chịu xức dầu Ngài.'),
(15379, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 89, 52, 'OT', 'Đáng ngợi khen Đức Giê-hô-va đến muôn đời! A-men và A-men!'),
(15380, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 90, 1, 'OT', 'Lời cầu nguyện của Môi-se, người của Đức Chúa Trời: Lạy Đức Giê-hô-va, Ngài là nơi nương náu của chúng tôi qua các đời.'),
(15381, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 90, 2, 'OT', 'Trước khi núi non được sinh ra, trước khi đất và thế gian được tạo thành, từ trước vô cùng cho đến đời đời, Ngài là Đức Chúa Trời.'),
(15382, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 90, 3, 'OT', 'Ngài khiến loài người trở về bụi tro, và phán rằng: Hỡi con cái loài người, hãy trở lại.'),
(15383, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 90, 4, 'OT', 'Vì một ngàn năm trước mắt Đức Giê-hô-va khác nào ngày hôm qua đã qua, và như một canh của đêm.'),
(15384, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 90, 5, 'OT', 'Ngài cuốn trôi họ đi như nước lũ; sáng mai, họ như cỏ xanh tươi.'),
(15385, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 90, 6, 'OT', 'Sáng ra cỏ xanh mọc lên và nở hoa; chiều đến, người ta cắt, nó liền héo khô.'),
(15386, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 90, 7, 'OT', 'Vì chúng tôi bị tiêu hao trong cơn thạnh nộ của Ngài, và trong sự nóng giận của Ngài bị bối rối.'),
(15387, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 90, 8, 'OT', 'Ngài đã đặt những tội lỗi chúng tôi ở trước mặt Ngài, Những điều kín nhiệm của chúng tôi dưới ánh sáng mặt Ngài.'),
(15388, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 90, 9, 'OT', 'Vì các ngày đời chúng tôi đều qua đi trong cơn thạnh nộ của Đức Giê-hô-va; Chúng tôi tiêu tan các năm mình như một hơi thở.'),
(15389, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 90, 10, 'OT', 'Tuổi đời của chúng ta là bảy mươi năm; nếu mạnh khỏe thì tám mươi năm. Nhưng phần lớn của nó đầy rẫy điều khổ cực và hư không, vì đời sống mau chóng qua đi, rồi chúng ta bay mất.'),
(15390, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 90, 11, 'OT', 'Ai biết được sức mạnh cơn thịnh nộ của Đức Giê-hô-va? Tùy theo sự kính sợ Ngài, ai biết được quyền năng cơn giận của Ngài?'),
(15391, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 90, 12, 'OT', 'Xin dạy chúng tôi biết đếm các ngày đời mình, để chúng tôi được lòng khôn ngoan.'),
(15392, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 90, 13, 'OT', 'Đức Giê-hô-va, xin trở lại cho đến bao giờ? Xin hãy đổi lòng về các tôi tớ Ngài.'),
(15393, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 90, 14, 'OT', 'Xin cho chúng tôi được đầy dẫy sự nhân từ của Đức Giê-hô-va mỗi buổi sáng, để chúng tôi được reo mừng và vui vẻ trọn mọi ngày đời chúng tôi.'),
(15394, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 90, 15, 'OT', 'Làm cho chúng tôi được vui vẻ tùy theo các ngày Ngài làm cho chúng tôi khốn khổ, và tùy theo những năm mà chúng tôi đã thấy điều dữ.'),
(15395, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 90, 16, 'OT', 'Nguyện việc làm của Ngài hiện ra cho các tôi tớ Ngài, và sự oai nghiêm của Ngài chiếu trên con cái họ!'),
(15396, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 90, 17, 'OT', 'Nguyện ơn lành của Đức Giê-hô-va, Đức Chúa Trời chúng tôi, giáng trên chúng tôi; và xin lập cho vững chắc công việc của tay chúng tôi, phải, xin lập cho vững chắc công việc của tay chúng tôi.'),
(15397, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 91, 1, 'OT', 'Người ngồi nơi kín đáo của Đức Chúa Trời Chí Cao, Sẽ được ở dưới bóng của Đức Giê-hô-va Toàn Năng.'),
(15398, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 91, 2, 'OT', 'Tôi nói về Đức Giê-hô-va rằng: Ngài là nơi nương náu tôi, và là đồn lũy tôi; Đức Chúa Trời tôi, tôi tin cậy nơi Ngài.'),
(15399, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 91, 3, 'OT', 'Vì chính Ngài sẽ cứu ngươi khỏi bẫy rập và khỏi dịch hạch hủy diệt.'),
(15400, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 91, 4, 'OT', 'Người sẽ lấy cánh mình mà che chở ngươi, và dưới cánh Người, ngươi sẽ được nương náu; sự thật của Người là cái khiên và cái thuẫn.'),
(15401, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 91, 5, 'OT', 'Ngươi sẽ không sợ sự kinh hoàng ban đêm, cũng không sợ mũi tên bay giữa ban ngày,'),
(15402, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 91, 6, 'OT', 'không sợ hại dịch lan trong bóng tối, hay tai họa tàn phá giữa trưa'),
(15403, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 91, 7, 'OT', 'Một ngàn người sẽ ngã bên cạnh ngươi, và muôn người bên phải ngươi; nhưng đến gần ngươi thì không.'),
(15404, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 91, 8, 'OT', 'Chỉ bằng đôi mắt ngươi mà xem, và sẽ thấy sự báo ứng dành cho kẻ ác.'),
(15405, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 91, 9, 'OT', 'Vì Đức Giê-hô-va là nơi náu ẩn của con, con đã đặt Đấng Chí cao làm chỗ ở mình.'),
(15406, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 91, 10, 'OT', 'Không có điều ác nào xảy đến cho ngươi, và tai họa chẳng đến gần trại ngươi.'),
(15407, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 91, 11, 'OT', 'Vì Ngài sẽ truyền cho các thiên sứ Ngài giữ ngươi trong mọi nẻo đường ngươi.'),
(15408, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 91, 12, 'OT', 'Các Ngài sẽ nâng ngươi trên tay mình, hầu ngươi khỏi vấp chân vào hòn đá.'),
(15409, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 91, 13, 'OT', 'Ngươi sẽ giày đạp trên sư tử và rắn hổ mang; Ngươi sẽ nghiền nát sư tử tơ và con rắn.'),
(15410, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 91, 14, 'OT', 'Vì người hết lòng yêu ta, ta sẽ giải cứu người; ta sẽ làm cho người được tôn cao, vì người biết danh ta.'),
(15411, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 91, 15, 'OT', 'Người sẽ kêu cầu ta, ta sẽ nhậm lời; ta sẽ ở cùng người trong sự hoạn nạn, ta sẽ giải cứu và làm cho người được tôn trọng.'),
(15412, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 91, 16, 'OT', 'Ta sẽ cho người ấy no đủ tuổi thọ, và cho người ấy thấy sự cứu rỗi của Ta.'),
(15413, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 92, 1, 'OT', 'Bài ca, bài thơ để tưởng niệm ngày Sa-bát: Thật tốt lành để cảm tạ Đức Giê-hô-va, và để ca ngợi danh Ngài, hỡi Đấng Chí Cao.'),
(15414, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 92, 2, 'OT', 'Để thuật rõ sự nhân từ của Đức Giê-hô-va vào buổi sáng, và sự thành tín của Ngài vào các đêm tối.'),
(15415, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 92, 3, 'OT', 'Trên nhạc khí mười dây và trên đàn lia, hòa nhạc với tiếng đàn cầm.'),
(15416, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 92, 4, 'OT', 'Vì, hỡi Đức Giê-hô-va, Ngài đã làm cho tôi vui vẻ bởi công việc của Ngài; tôi sẽ hân hoan về các việc tay Ngài làm.'),
(15417, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 92, 5, 'OT', 'Lạy Đức Giê-hô-va, công việc Ngài lớn biết bao! Tư tưởng Ngài sâu thẳm biết bao!'),
(15418, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 92, 6, 'OT', 'Người ngu dốt không biết, kẻ ngu muội cũng không hiểu điều này.'),
(15419, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 92, 7, 'OT', 'Khi những kẻ ác nở rộ như cỏ dại, và mọi kẻ làm điều gian ác nở hoa, thì ấy là để chúng bị tiêu diệt đời đời.'),
(15420, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 92, 8, 'OT', 'Nhưng, Đức Giê-hô-va, Ngài được tôn cao mãi mãi.'),
(15421, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 92, 9, 'OT', 'Vì này, hỡi Đức Giê-hô-va, kìa các kẻ thù nghịch Ngài, kìa các kẻ thù nghịch Ngài sẽ bị tiêu diệt; mọi kẻ làm điều ác sẽ bị tan lạc.'),
(15422, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 92, 10, 'OT', 'Nhưng sừng tôi, Ngài làm cho ngước cao lên như sừng bò rừng; tôi được xức bằng dầu tươi mới.'),
(15423, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 92, 11, 'OT', 'Mắt tôi đã nhìn thấy điều rủa tôi khi kẻ thù nghịch tôi trỗi dậy; tai tôi đã nghe điều rủa tôi khi kẻ ác chống tôi bị trừng phạt.'),
(15424, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 92, 12, 'OT', 'Người công bình sẽ nở hoa như cây chàm, vươn lên như cây tùng ở Li-ban.'),
(15425, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 92, 13, 'OT', 'Những kẻ được trồng trong nhà Đức Giê-hô-va sẽ trổ bông trong các hành lang của Đức Chúa Trời chúng ta.'),
(15426, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 92, 14, 'OT', 'Dẫu đến tuổi già, họ vẫn xanh tươi; họ sẽ sinh bông trái, vẫn xanh tốt và dồi dào.'),
(15427, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 92, 15, 'OT', 'Để nói rằng Đức Giê-hô-va là ngay thẳng; hòn đá tôi, trong Ngài chẳng có điều gian ác.'),
(15428, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 93, 1, 'OT', 'Đức Giê-hô-va cai trị, mặc lấy oai hùng; Đức Giê-hô-va mặc lấy quyền năng và thắt lưng. Cũng bởi Ngài, thế gian được thiết lập vững chắc, không hề rúng động.'),
(15429, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 93, 2, 'OT', 'Ngai của Ngài đã được lập từ lâu; Ngài hằng hữu từ trước vô cùng.'),
(15430, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 93, 3, 'OT', 'Hỡi Đức Giê-hô-va, các dòng sông đã dâng lên, các dòng sông đã cất tiếng lên, các dòng sông đã dâng lên tiếng ầm ầm.'),
(15431, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 93, 4, 'OT', 'Tiếng nước lớn, các đợt sóng biển mạnh dữ dội, nhưng Đức Giê-hô-va quyền năng hơn nơi cao.'),
(15432, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 93, 5, 'OT', 'Đức Giê-hô-va, các điều chứng cớ của Ngài rất trung thực; sự thánh khiết xứng đáng cho nhà Ngài đến trọn đời.'),
(15433, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 94, 1, 'OT', 'Đức Giê-hô-va là Đức Chúa Trời báo phục, Đức Chúa Trời báo phục, Ngài đã sáng rực lên.'),
(15434, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 94, 2, 'OT', 'Hỡi Đấng xét xử đất nầy, hãy chỗi dậy; xin báo trả sự báo ứng cho những kẻ kiêu ngạo.'),
(15435, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 94, 3, 'OT', 'Hỡi Đức Giê-hô-va, cho đến chừng nào kẻ ác còn hớn hở?'),
(15436, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 94, 4, 'OT', 'Chúng buông lời nói cách ngạo mạn; mọi kẻ làm điều ác đều tự đắc.'),
(15437, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 94, 5, 'OT', 'Dân sự của Đức Giê-hô-va mà chúng nó chà đạp, và cơ nghiệp của Ngài mà chúng nó làm khổ.'),
(15438, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 94, 6, 'OT', 'Chúng giết người góa bụa và kẻ lữ khách, và sát hại những đứa trẻ mồ côi.'),
(15439, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 94, 7, 'OT', 'Chúng nói rằng: Đức Giê-hô-va sẽ không thấy, Đức Chúa Trời của Gia-cốp chẳng hiểu biết.'),
(15440, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 94, 8, 'OT', 'Hỡi những kẻ ngu dại trong dân, hãy hiểu biết; hỡi những kẻ dại dột, bao giờ các ngươi mới khôn ngoan?'),
(15441, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 94, 9, 'OT', 'Đấng đã trồng tai há chẳng nghe sao? Đấng đã tạo mắt há chẳng nhìn sao?'),
(15442, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 94, 10, 'OT', 'Đấng sửa phạt các nước há chẳng sửa dạy sao? Đấng dạy loài người tri thức, há chẳng răn bảo sao?'),
(15443, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 94, 11, 'OT', 'Đức Giê-hô-va biết các ý tưởng của loài người, vì chúng chỉ là hư không.'),
(15444, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 94, 12, 'OT', 'Phước cho người mà Đức Giê-hô-va sửa phạt, và dạy người ấy theo luật pháp Ngài,'),
(15445, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 94, 13, 'OT', 'Để cho người được yên nghỉ trong những ngày tai họa, cho đến khi cái hầm dành cho kẻ ác được đào xong.'),
(15446, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 94, 14, 'OT', 'Vì Đức Giê-hô-va sẽ không lìa bỏ dân Ngài, và cơ nghiệp Ngài sẽ không bị bỏ mặc.'),
(15447, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 94, 15, 'OT', 'Vì đến chừng nào sự đoán xét trở về công bình, thì mọi người lòng ngay thẳng sẽ theo sau nó.'),
(15448, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 94, 16, 'OT', 'Ai sẽ đứng lên bênh vực tôi chống lại những kẻ làm ác? Ai sẽ đứng bên tôi chống lại những kẻ hành động gian ác?'),
(15449, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 94, 17, 'OT', 'Nếu Đức Giê-hô-va không giúp đỡ tôi, thì hầu như linh hồn tôi đã ở nơi nín lặng.'),
(15450, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 94, 18, 'OT', 'Hỡi Đức Giê-hô-va, khi tôi nói: "Chân tôi đã xiêu té," thì sự nhân từ Ngài nâng đỡ tôi.'),
(15451, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 94, 19, 'OT', 'Khi những lo lắng trong lòng tôi chồng chất, thì sự an ủi của Ngài làm cho tâm thần tôi được vui vẻ.'),
(15452, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 94, 20, 'OT', 'Ngôi vị kết hiệp cùng cái ghế sự hư không, Đấng tạo nên điều ác nhân danh luật pháp, há sẽ giao thông với ngươi sao?'),
(15453, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 94, 21, 'OT', 'Chúng hợp nhau chống lại linh hồn người công chính, và kết án huyết vô tội.'),
(15454, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 94, 22, 'OT', 'Nhưng Đức Giê-hô-va là nơi nương náu của tôi; và Đức Chúa Trời tôi là hòn đá để tôi nương nhờ.'),
(15455, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 94, 23, 'OT', 'Ngài khiến sự ác chúng nó đổ lại trên chúng nó, và trong sự hung dữ chúng nó Ngài sẽ tiêu diệt chúng nó; Đức Giê-hô-va Đức Chúa Trời chúng tôi sẽ tiêu diệt chúng nó.'),
(15456, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 95, 1, 'OT', 'Hãy đến, chúng ta hát xướng cho Đức Giê-hô-va, reo mừng cho Hòn đá về sự cứu rỗi chúng ta.'),
(15457, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 95, 2, 'OT', 'Chúng ta hãy đến trước mặt Ngài với lời cảm tạ, hân hoan reo vui ngợi khen Ngài.'),
(15458, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 95, 3, 'OT', 'Vì Đức Giê-hô-va là Đức Chúa Trời lớn lao, và là Vua lớn trên hết thảy các thần.'),
(15459, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 95, 4, 'OT', 'Các vực sâu của đất ở trong tay Ngài, và những đỉnh núi cao cũng thuộc về Ngài.'),
(15460, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 95, 5, 'OT', 'Biển thuộc về Ngài, vì chính Ngài đã làm nên nó; còn đất khô, tay Ngài đã tạo nên.'),
(15461, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 95, 6, 'OT', 'Hãy đến, chúng ta hãy thờ lạy và quỳ xuống; hãy cúi mình trước mặt Đức Giê-hô-va là Đấng đã tạo nên chúng ta.'),
(15462, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 95, 7, 'OT', 'Vì chính Ngài là Đức Chúa Trời chúng tôi, và chúng tôi là dân trong đồng cỏ của Ngài, là chiên nơi tay Ngài; ngày nay, nếu các ngươi nghe tiếng Ngài,'),
(15463, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 95, 8, 'OT', 'Đừng làm cho lòng các ngươi ra cứng cỏi như tại Mê-ri-ba, như ngày Ma-sa trong đồng vắng,'),
(15464, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 95, 9, 'OT', 'Là nơi tổ phụ các ngươi thử ta, dò xét ta, và đã thấy các việc ta làm.'),
(15465, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 95, 10, 'OT', 'Trong bốn mươi năm Đức Giê-hô-va gớm ghét dòng dõi nầy, và phán rằng: Ấy là một dân lòng lầm lạc, chẳng từng biết các đường lối ta;'),
(15466, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 95, 11, 'OT', 'Ta đã nghiêm nghị thề trong cơn thịnh nộ: Chúng nó sẽ không vào nơi Ta cho nghỉ yên.'),
(15467, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 96, 1, 'OT', 'Hãy hát một bài ca mới cho Đức Giê-hô-va; hỡi cả đất, hãy hát cho Đức Giê-hô-va.'),
(15468, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 96, 2, 'OT', 'Hãy hát cho Đức Giê-hô-va, hãy chúc tụng danh Ngài; từng ngày hãy loan báo sự cứu rỗi của Ngài.'),
(15469, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 96, 3, 'OT', 'Hãy thuật sự vinh hiển Ngài giữa các dân, các phép lạ của Ngài giữa mọi nước.'),
(15470, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 96, 4, 'OT', 'Vì Đức Giê-hô-va rất lớn và được ngợi khen cách dồi dào; Ngài đáng kính sợ hơn mọi thần.'),
(15471, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 96, 5, 'OT', 'Vì mọi thần của các dân đều là hình tượng; còn Đức Giê-hô-va đã làm nên các từng trời.'),
(15472, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 96, 6, 'OT', 'Sự oai nghi và vẻ đẹp ở trước mặt Ngài; sự quyền năng và vinh quang ở nơi đền thánh của Ngài.'),
(15473, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 96, 7, 'OT', 'Hỡi các họ tộc của các dân, hãy dâng cho Đức Giê-hô-va sự vinh hiển và quyền năng.'),
(15474, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 96, 8, 'OT', 'Hãy dâng cho Đức Giê-hô-va sự vinh hiển của danh Ngài; hãy mang lễ vật mà vào các hành lang của Ngài.'),
(15475, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 96, 9, 'OT', 'Hãy thờ lạy Đức Giê-hô-va trong trang sức thánh; hỡi cả trái đất, hãy run sợ trước mặt Ngài.'),
(15476, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 96, 10, 'OT', 'Hãy nói giữa các nước: Đức Giê-hô-va đã trị vì; chính Ngài làm cho thế gian vững bền, không lay chuyển; Ngài sẽ xét đoán các dân cách ngay thẳng.'),
(15477, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 96, 11, 'OT', 'Các từng trời hãy vui vẻ, đất hãy hân hoan; biển và mọi vật trong đó hãy reo lên.'),
(15478, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 96, 12, 'OT', 'Đồng ruộng hãy vui mừng và mọi vật ở trong nó; bấy giờ mọi cây cối trong rừng sẽ reo lên mừng rỡ.'),
(15479, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 96, 13, 'OT', 'Trước mặt Đức Giê-hô-va, vì Ngài đã đến, Ngài đã đến đặng xét đoán đất; Ngài sẽ xét đoán thế gian cách công bình, và các dân tộc cách trung thành Ngài.'),
(15480, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 97, 1, 'OT', 'Đức Giê-hô-va làm Vua; đất hãy mừng rỡ, các hải đảo hãy vui vẻ.'),
(15481, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 97, 2, 'OT', 'Mây đen và bóng tối bao quanh Ngài; sự công chính và lẽ công bình làm nền cho ngôi Ngài.'),
(15482, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 97, 3, 'OT', 'Lửa đi trước mặt Ngài, và thiêu đốt những kẻ thù nghịch xung quanh Ngài.'),
(15483, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 97, 4, 'OT', 'Chớp sáng của Ngài soi rạng mặt đất; mặt đất thấy và run rẩy.'),
(15484, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 97, 5, 'OT', 'Các núi tan chảy như sáp trước mặt Đức Giê-hô-va, trước mặt Chúa của cả đất.'),
(15485, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 97, 6, 'OT', 'Các từng trời loan báo sự công chính của Ngài, và mọi dân tộc thấy sự vinh hiển của Ngài.'),
(15486, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 97, 7, 'OT', 'Nguyện mọi kẻ phục vụ tượng chạm và tự hào về các thần tượng đều phải xấu hổ. Hỡi các thần, hãy cúi lạy Đức Giê-hô-va.'),
(15487, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 97, 8, 'OT', 'Si-ôn nghe và mừng rỡ, các con gái Giu-đa vui vẻ, vì các phán quyết của Đức Giê-hô-va.'),
(15488, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 97, 9, 'OT', 'Vì chính Đức Giê-hô-va, Ngài thật cao cả trên khắp đất, và Ngài được tôn cao hơn hết thảy các thần.'),
(15489, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 97, 10, 'OT', 'Hỡi những kẻ yêu mến Đức Giê-hô-va, hãy ghét sự ác; Ngài gìn giữ mạng sống các thánh nhân Ngài, giải cứu họ khỏi tay kẻ ác.'),
(15490, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 97, 11, 'OT', 'Ánh sáng được gieo cho người công bình, và niềm vui cho người có lòng ngay thẳng.'),
(15491, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 97, 12, 'OT', 'Hỡi các người công bình, hãy vui mừng trong Đức Giê-hô-va, và hãy cảm tạ vì nhớ đến sự thánh khiết của Ngài.'),
(15492, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 98, 1, 'OT', 'Hỡi các ngươi, hãy hát cho Đức Giê-hô-va một bài ca mới, vì Đức Giê-hô-va đã làm nên những việc lạ lùng; tay phải và cánh tay thánh của Ngài đã cứu giúp Ngài.'),
(15493, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 98, 2, 'OT', 'Đức Giê-hô-va đã tỏ ra sự cứu rỗi của Ngài, trước mắt các dân tộc, Ngài bày ra sự công bình của Ngài.'),
(15494, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 98, 3, 'OT', 'Ngài đã nhớ lại lòng nhân từ và sự thành tín của Ngài đối với nhà Y-sơ-ra-ên; mọi đầu cùng đất đã thấy sự cứu rỗi của Đức Chúa Trời chúng tôi.'),
(15495, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 98, 4, 'OT', 'Hỡi cả trái đất, hãy reo mừng cho Đức Giê-hô-va; cất tiếng reo vui, hát mừng và dâng bài ca!'),
(15496, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 98, 5, 'OT', 'Hãy gảy đàn cho Đức Giê-hô-va bằng đàn cầm, bằng đàn cầm và tiếng hát mà ngợi khen Ngài!'),
(15497, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 98, 6, 'OT', 'Hãy lấy tiếng loa và tiếng kèn chàm-bau mà reo mừng trước mặt Đức Vua, Đức Giê-hô-va.'),
(15498, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 98, 7, 'OT', 'Nguyện biển reo vang và muôn vật đầy dẫy trong nó, nguyện đất cùng những người sống trên đất cùng reo lên!'),
(15499, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 98, 8, 'OT', 'Các sông vỗ tay; các núi cùng nhau reo vui trước mặt Đức Giê-hô-va!'),
(15500, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 98, 9, 'OT', 'Trước mặt Đức Giê-hô-va, vì Ngài đến để xét xử đất; Ngài sẽ xét xử thế gian cách công bình, và các dân tộc cách ngay thẳng.'),
(15501, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 99, 1, 'OT', 'Đức Giê-hô-va làm Vua; các dân phải run rẩy; Ngài ngự trên các chê-ru-bim; đất phải rúng động.'),
(15502, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 99, 2, 'OT', 'Đức Giê-hô-va tại Si-ôn thật lớn lao, Ngài cao cả trên muôn dân.'),
(15503, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 99, 3, 'OT', 'Nguyện họ ca ngợi danh lớn và đáng sợ của Ngài; Ngài là Đấng Thánh.'),
(15504, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 99, 4, 'OT', 'Quyền năng của vua yêu sự công bình; chính Ngài lập vững bền sự ngay thẳng; sự đoán xét và sự công bình trong Gia-cốp, chính Ngài đã thực hiện.'),
(15505, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 99, 5, 'OT', 'Hãy tôn cao Đức Giê-hô-va Đức Chúa Trời chúng ta, và hãy thờ lạy nơi bệ dưới chân Ngài; Ngài là thánh.'),
(15506, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 99, 6, 'OT', 'Môi-se và A-rôn trong các thầy tế lễ của Ngài, và Sa-mu-ên trong những kẻ cầu khẩn danh Ngài; họ kêu cầu Đức Giê-hô-va, và Ngài đáp lời họ.'),
(15507, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 99, 7, 'OT', 'Đức Giê-hô-va phán cùng họ trong trụ mây; họ giữ các chứng cớ Ngài, và luật lệ mà Ngài ban cho họ.'),
(15508, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 99, 8, 'OT', 'Hỡi Đức Giê-hô-va Đức Chúa Trời chúng tôi, Ngài đã nhậm lời họ; Ngài là Đức Chúa Trời hay tha thứ cho họ, và báo phạt vì những điều họ phạm.'),
(15509, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 99, 9, 'OT', 'Hãy tôn cao Đức Giê-hô-va Đức Chúa Trời chúng ta, và thờ lạy nơi núi thánh của Ngài; vì Đức Giê-hô-va Đức Chúa Trời chúng ta là thánh.'),
(15510, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 100, 1, 'OT', 'Hỡi cả trái đất, hãy reo mừng cho Đức Giê-hô-va!'),
(15511, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 100, 2, 'OT', 'Hãy hầu việc Đức Giê-hô-va cách vui mừng, hãy đến trước mặt Ngài với tiếng reo mừng.'),
(15512, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 100, 3, 'OT', 'Hãy biết rằng Đức Giê-hô-va là Đức Chúa Trời; chính Ngài đã làm nên chúng ta, chứ không phải chúng ta tự làm nên mình; chúng ta là dân sự Ngài, và là bầy chiên trong đồng cỏ của Ngài.'),
(15513, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 100, 4, 'OT', 'Hãy vào các cửa Ngài với lời cảm tạ, vào các hành lang Ngài với lời ca ngợi. Hãy cảm tạ Ngài, chúc tụng danh Đức Giê-hô-va.'),
(15514, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 100, 5, 'OT', 'Vì Đức Giê-hô-va là thiện, sự nhân từ của Ngài hằng có mãi mãi, và sự thành tín của Ngài còn đến đời nầy sang đời khác.'),
(15515, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 101, 1, 'OT', 'Ta sẽ hát về sự nhân từ và sự đoán xét. Hỡi Đức Giê-hô-va, ta sẽ hát ngợi kinh Ngài.'),
(15516, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 101, 2, 'OT', 'Tôi sẽ chuyên tâm theo con đường ngay thẳng; chừng nào Ngài mới đến cùng tôi? Tôi sẽ sống trọn vẹn lòng ngay thẳng trong nhà tôi.'),
(15517, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 101, 3, 'OT', 'Tôi sẽ không đặt điều gì gian ác trước mặt mình; tôi ghét công việc làm của kẻ gian tà; việc ấy sẽ không dính vào tôi.'),
(15518, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 101, 4, 'OT', 'Lòng cong vênh sẽ lìa khỏi ta; ta sẽ không biết điều ác.'),
(15519, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 101, 5, 'OT', 'Kẻ lén nói hành người bạn mình nơi kín đáo, chính ta sẽ tiêu diệt nó; kẻ nào có mắt kiêu căng và lòng tự cao, ta không chịu được.'),
(15520, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 101, 6, 'OT', 'Mắt tôi sẽ nhìn người trung tín trong đất nước để họ ở cùng tôi; ai đi theo con đường ngay thẳng, người ấy sẽ hầu việc tôi.'),
(15521, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 101, 7, 'OT', 'Kẻ làm điều gian trá sẽ không ở giữa nhà ta; kẻ nói dối sẽ không đứng vững trước mặt ta.'),
(15522, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 101, 8, 'OT', 'Mỗi buổi sáng tôi sẽ tiêu diệt tất cả những kẻ gian ác trong đất, để loại bỏ khỏi thành của Đức Giê-hô-va mọi kẻ làm điều ác.'),
(15523, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 102, 1, 'OT', 'Lời cầu nguyện của kẻ khốn khổ khi lâm nguy, và trước mặt Đức Giê-hô-va, người ấy tuôn đổ tâm sự mình. Hỡi Đức Giê-hô-va, xin nghe lời cầu nguyện tôi, và tiếng kêu cứu tôi xin đến Ngài.'),
(15524, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 102, 2, 'OT', 'Xin đừng giấu mặt Ngài khỏi tôi; trong ngày hoạn nạn, xin nghiêng tai về phía tôi; khi tôi kêu cầu, xin mau mau đáp lời tôi.'),
(15525, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 102, 3, 'OT', 'Vì các ngày ta tiêu tan như khói, các xương ta khô héo như bị hơ trên lửa.'),
(15526, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 102, 4, 'OT', 'Lòng tôi bị đánh như cỏ và khô héo, vì tôi quên ăn bánh ta.'),
(15527, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 102, 5, 'OT', 'Vì tiếng rên siết của tôi, xương tôi dính sát vào thịt tôi.'),
(15528, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 102, 6, 'OT', 'Tôi đã trở nên như chim quạ trong đồng vắng, tôi đã giống như chim cú trong nơi đổ nát.'),
(15529, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 102, 7, 'OT', 'Tôi thức trắng và trở nên như con chim sẻ cô đơn trên mái nhà.'),
(15530, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 102, 8, 'OT', 'Cả ngày kẻ thù sỉ vả tôi; những kẻ nổi giận tôi lấy tôi làm lời thề.'),
(15531, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 102, 9, 'OT', 'Vì tôi đã ăn tro như bánh, và trộn nước uống tôi với khóc than,'),
(15532, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 102, 10, 'OT', 'Vì cơn thịnh nộ và sự phẫn nộ của Ngài, Ngài đã nâng tôi lên rồi quăng tôi xuống.'),
(15533, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 102, 11, 'OT', 'Các ngày tôi như bóng ngã dài ra, còn tôi như cỏ khô héo.'),
(15534, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 102, 12, 'OT', 'Nhưng Đức Giê-hô-va, Ngài ngồi trị vì đời đời; kỷ niệm về Ngài còn lại từ đời này sang đời khác.'),
(15535, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 102, 13, 'OT', 'Ngài sẽ chỗi dậy, thương xót Si-ôn; vì đã đến thì giờ để lấy lòng thương xót nàng; thời điểm định sẵn đã đến.'),
(15536, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 102, 14, 'OT', 'Các tôi tớ của Đức Giê-hô-va yêu chuộng các hòn đá của Si-ôn, và thương xót bụi đất nó.'),
(15537, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 102, 15, 'OT', 'Các dân tộc sẽ kính sợ danh Đức Giê-hô-va, và mọi vua trên đất sẽ kính sợ sự vinh hiển của Ngài.'),
(15538, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 102, 16, 'OT', 'Vì Đức Giê-hô-va sẽ xây lại Si-ôn; Ngài sẽ hiện ra trong vinh hiển Ngài.'),
(15539, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 102, 17, 'OT', 'Đức Giê-hô-va trở về cùng lời cầu nguyện của kẻ khốn cùng, và không khinh dể lời cầu nguyện của họ.'),
(15540, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 102, 18, 'OT', 'Điều nầy sẽ được chép cho đời tương lai, và một dân sự được tạo nên sẽ ngợi khen Đức Giê-hô-va.'),
(15541, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 102, 19, 'OT', 'Vì Ngài đã ngó xuống từ nơi thánh cao Ngài, Đức Giê-hô-va ngó từ các từng trời xuống đất,'),
(15542, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 102, 20, 'OT', 'Để nghe tiếng kêu than của kẻ bị giam, và giải thoát cho con cái của sự chết.'),
(15543, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 102, 21, 'OT', 'Để loan truyền danh Đức Giê-hô-va tại Si-ôn và sự ngợi khen Ngài tại Giê-ru-sa-lem,'),
(15544, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 102, 22, 'OT', 'Khi các dân tộc nhóm lại cùng nhau, và các vương quốc hầu việc Đức Giê-hô-va.'),
(15545, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 102, 23, 'OT', 'Người làm cho sức lực tôi yếu ớt giữa đường đời, khiến cho các ngày tôi được rút ngắn.'),
(15546, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 102, 24, 'OT', 'Lạy Đức Chúa Trời tôi, xin chớ cất tôi đi giữa đời; các năm của Chúa còn đến muôn đời.'),
(15547, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 102, 25, 'OT', 'Thuở trước, Ngài đã lập nền trái đất; các từng trời là công việc của tay Ngài.'),
(15548, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 102, 26, 'OT', 'Chúng sẽ bị tiêu hủy, còn Ngài thì đứng vững; chúng đều cũ mòn như áo mặc; Ngài sẽ thay áo cho chúng như quần áo, và chúng sẽ qua đi.'),
(15549, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 102, 27, 'OT', 'Nhưng chính Ngài vẫn là một, và các năm tháng của Ngài sẽ chẳng hề chấm dứt.'),
(15550, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 102, 28, 'OT', 'Con cái của các tôi tớ Ngài sẽ ở lại, và dòng dõi chúng sẽ được lập vững trước mặt Ngài.'),
(15551, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 103, 1, 'OT', 'Hỡi linh hồn ta, hãy ca ngợi Đức Giê-hô-va; và hết thảy những phần trong ta hãy ca ngợi danh thánh của Ngài!'),
(15552, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 103, 2, 'OT', 'Hỡi linh hồn ta, hãy tôn vinh Đức Giê-hô-va, và chớ quên một ơn nào của Ngài.'),
(15553, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 103, 3, 'OT', 'Đấng tha thứ mọi tội lỗi ngươi, Đấng chữa lành mọi bệnh tật ngươi,'),
(15554, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 103, 4, 'OT', 'Cứu chuộc mạng sống ngươi khỏi huyệt sâu, lấy sự nhân từ và thương xót làm mão triều đội cho ngươi.'),
(15555, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 103, 5, 'OT', 'Làm cho miệng ngươi đầy những điều tốt lành, khiến tuổi trẻ ngươi được đổi mới như chim ưng.'),
(15556, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 103, 6, 'OT', 'Đức Giê-hô-va làm điều công bình và xét đoán cho mọi kẻ bị ức hiếp.'),
(15557, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 103, 7, 'OT', 'Ngài cho Môi-se biết các đường lối Ngài, cho con cái Y-sơ-ra-ên biết các công việc Ngài.'),
(15558, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 103, 8, 'OT', 'Đức Giê-hô-va đầy lòng thương xót và nhân từ, chậm giận và giàu lòng nhân hậu.'),
(15559, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 103, 9, 'OT', 'Ngài không tranh tụng đời đời, Cũng chẳng mãi mãi giữ lòng giận.'),
(15560, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 103, 10, 'OT', 'Ngài không xử chúng tôi theo tội lỗi chúng tôi, cũng không trả chúng tôi tùy theo sự gian ác chúng tôi.'),
(15561, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 103, 11, 'OT', 'Vì hễ các từng trời cao cách biệt trên đất thể nào, thì sự nhân từ của Ngài càng lớn hơn trên những kẻ kính sợ Ngài thể ấy.'),
(15562, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 103, 12, 'OT', 'Đức Giê-hô-va cách xa chúng ta khỏi tội ác mình bao nhiêu, thì đông cách tây bấy nhiêu.'),
(15563, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 103, 13, 'OT', 'Như cha thương xót con cái mình, Đức Giê-hô-va thương xót kẻ kính sợ Ngài.'),
(15564, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 103, 14, 'OT', 'Vì Ngài biết hình dáng chúng tôi, nhớ rằng chúng tôi chỉ là bụi đất.'),
(15565, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 103, 15, 'OT', 'Đời người như cỏ, như hoa nơi đồng, người nở ra;'),
(15566, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 103, 16, 'OT', 'Gió thổi qua, thì người không còn nữa, và nơi người ấy cũng chẳng còn nhận biết người ấy.'),
(15567, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 103, 17, 'OT', 'Nhưng sự nhân từ của Đức Giê-hô-va từ đời này đến đời khác dành cho những người kính sợ Ngài, và sự công bình của Ngài dành cho con cháu đời đời.'),
(15568, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 103, 18, 'OT', 'Cho những kẻ giữ giao ước Ngài và nhớ các mạng lịnh Ngài để thực hành.'),
(15569, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 103, 19, 'OT', 'Đức Giê-hô-va đã đặt ngôi Ngài trên các từng trời, và nước Ngài thống trị trên muôn vật.'),
(15570, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 103, 20, 'OT', 'Hỡi các thiên sứ của Đức Giê-hô-va, là những đấng mạnh mẽ đầy quyền năng, thực hiện lời Ngài, vâng nghe theo tiếng Ngài, hãy ngợi khen Đức Giê-hô-va!'),
(15571, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 103, 21, 'OT', 'Hỡi cả đạo binh của Đức Giê-hô-va, là những tôi tớ Ngài làm theo ý chỉ Ngài, hãy ca ngợi Đức Giê-hô-va!'),
(15572, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 103, 22, 'OT', 'Hỡi các công việc của Đức Giê-hô-va, trong mọi nơi Ngài cai trị, hãy ca ngợi Đức Giê-hô-va! Hỡi linh hồn ta, hãy ca ngợi Đức Giê-hô-va!'),
(15573, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 1, 'OT', 'Hỡi linh hồn ta, hãy ngợi khen Đức Giê-hô-va! Lạy Đức Giê-hô-va, Đức Chúa Trời tôi, Ngài thật sự rất lớn; Ngài mặc sự oai nghiêm và vinh hiển.'),
(15574, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 2, 'OT', 'Người lấy ánh sáng làm áo mà mặc, trải các từng trời ra như màn trướng.'),
(15575, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 3, 'OT', 'Chấp các đòn tay của phòng cao Ngài trong nước, đặt mây làm xe Ngài, đi bước trên cánh gió.'),
(15576, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 4, 'OT', 'Ngài khiến các sứ giả của Ngài thành gió, các đầy tớ của Ngài thành ngọn lửa rực cháy.'),
(15577, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 5, 'OT', 'Đức Giê-hô-va đặt nền đất trên các trụ của nó; đất sẽ không lay động đến muôn đời.'),
(15578, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 6, 'OT', 'Ngươi lấy vực sâu như cái áo mà che phủ nó; nước đứng trên các núi.'),
(15579, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 7, 'OT', 'Từ lời quở trách của Ngài, nước bèn chạy trốn; từ tiếng sấm của Ngài, nước vội vàng bỏ chạy.'),
(15580, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 8, 'OT', 'Núi non dâng lên, các trũng sụp xuống, đến nơi mà Ngài đã đặt định cho chúng.'),
(15581, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 9, 'OT', 'Ngài đặt ranh giới cho nước, không được phép vượt qua, để nước không còn trở lại che phủ đất nữa.'),
(15582, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 10, 'OT', 'Ngài khiến các suối chảy ra trong các thung lũng, chúng chạy giữa các núi.'),
(15583, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 11, 'OT', 'Các suối nước cho mọi loài thú đồng uống; các lừa rừng dập tắt cơn khát của mình.'),
(15584, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 12, 'OT', 'Chim trời đều ở trên các cây của nó, từ giữa các bụi cây, chúng cất tiếng ca.'),
(15585, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 13, 'OT', 'Từ các phòng cao của Ngài, Ngài tưới các núi; đất được no đủ bởi bông trái của công việc Ngài.'),
(15586, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 14, 'OT', 'Làm mọc cỏ cho súc vật, và rau xanh để phục vụ loài người, để sản xuất bánh mì từ đất.'),
(15587, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 15, 'OT', 'và rượu nho khiến lòng người vui vẻ, làm mặt người sáng lên hơn dầu; bánh thì bổ sức cho lòng người.'),
(15588, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 16, 'OT', 'Các cây cối của Đức Giê-hô-va được no đủ, những cây li-ban tại Li-ban mà Ngài đã trồng.'),
(15589, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 17, 'OT', 'Là nơi chim làm tổ, chim cò lấy cây thông làm nhà nó.'),
(15590, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 18, 'OT', 'Các núi cao là nơi ở của dê rừng; các vách đá là nơi náu ẩn của loài chồn.'),
(15591, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 19, 'OT', 'Người đã làm mặt trăng để chỉ các kỳ lễ; mặt trời biết nơi lặn của nó.'),
(15592, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 20, 'OT', 'Ngài đặt sự tối tăm, và đêm liền đến; trong đó mọi loài vật rừng núi đều bò ra.'),
(15593, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 21, 'OT', 'Những sư tử con gầm gừ để được mồi, và tìm thức ăn mình nơi Đức Chúa Trời.'),
(15594, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 22, 'OT', 'Mặt trời mọc lên, chúng rút về và nằm trong các nơi ở của chúng.'),
(15595, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 23, 'OT', 'Người ta ra đi làm việc của mình, và lao động cho đến chiều tối.'),
(15596, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 24, 'OT', 'Hỡi Đức Giê-hô-va, công việc Ngài thật vô số! Ngài đã làm nên tất cả bằng sự khôn ngoan; cả đất đầy dẫy của cải Ngài.'),
(15597, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 25, 'OT', 'Biển cả này thật lớn lao và rộng rãi vô biên; trong đó có muôn loài sinh vật, từ nhỏ đến lớn, đông vô số kể.'),
(15598, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 26, 'OT', 'Tại đó những chiếc tàu đi qua lại; còn có con Li-vi-a-than mà Ngài đã tạo nên để vui chơi trong biển.'),
(15599, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 27, 'OT', 'Hết thảy đều trông đợi Ngài, để Ngài ban cho đồ ăn theo đúng thì giờ.'),
(15600, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 28, 'OT', 'Chúa cho, chúng nó nhận; Chúa mở tay ra, chúng nó được no đủ điều lành.'),
(15601, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 29, 'OT', 'Ngài giấu mặt đi, chúng hoảng hốt; Ngài rút lấy hơi thở chúng nó, chúng tắt thở, và trở về bụi đất.'),
(15602, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 30, 'OT', 'Ngài sai Thần Ngài ra, chúng nó được dựng nên; Ngài đổi mới mặt đất.'),
(15603, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 31, 'OT', 'Nguyện sự vinh hiển Đức Giê-hô-va còn đời đời; nguyện Đức Giê-hô-va vui vẻ trong các công việc của Ngài.'),
(15604, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 32, 'OT', 'Ngài nhìn đất, đất liền rúng động; Ngài đụng đến núi, núi liền bốc khói.'),
(15605, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 33, 'OT', 'Tôi sẽ hát xướng cho Đức Giê-hô-va trọn đời tôi sống; còn chừng nào tôi tồn tại, tôi sẽ hát cho Đức Chúa Trời tôi.'),
(15606, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 34, 'OT', 'Nguyện sự suy gẫm tôi làm đẹp lòng Ngài; tôi sẽ vui vẻ trong Đức Giê-hô-va.'),
(15607, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 104, 35, 'OT', 'Nguyện các kẻ tội lỗi bị tiêu diệt khỏi đất, và ác nhân chẳng còn nữa. Hỡi linh hồn ta, hãy ngợi khen Đức Giê-hô-va! Ha-lê-lu-gia!'),
(15608, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 1, 'OT', 'Hãy tạ ơn Đức Giê-hô-va, hãy kêu cầu danh Ngài; hãy loan truyền giữa các dân những điều kỳ diệu Ngài làm.'),
(15609, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 2, 'OT', 'Hãy hát cho Ngài, hãy đàn hát cho Ngài, hãy nói đến mọi việc diệu kỳ của Ngài.'),
(15610, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 3, 'OT', 'Hãy tự hào trong danh thánh của Ngài; nguyện lòng những kẻ tìm cầu Đức Giê-hô-va được vui mừng!'),
(15611, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 4, 'OT', 'Hãy tìm Đức Giê-hô-va và quyền năng Ngài, hãy cầu mong mặt Ngài luôn mãi.'),
(15612, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 5, 'OT', 'Hãy nhớ các việc kỳ diệu Ngài đã làm, những dấu kỳ và các quyết định từ miệng Ngài.'),
(15613, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 6, 'OT', 'Hỡi dòng dõi Áp-ra-ham, tôi tớ của Ngài, hỡi con cháu của Gia-cốp, những kẻ được Ngài chọn lựa,'),
(15614, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 7, 'OT', 'Chính Ngài là Đức Giê-hô-va Đức Chúa Trời chúng tôi; các phán quyết của Ngài trải khắp đất.'),
(15615, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 8, 'OT', 'Đức Giê-hô-va nhớ đến giao ước Ngài mãi mãi, một lời Ngài đã truyền cho đến ngàn đời,'),
(15616, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 9, 'OT', 'Giao ước Ngài lập với Aùp-ra-ham, và lời thề của Ngài cho Y-sác.'),
(15617, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 10, 'OT', 'Lập cho Gia-cốp làm điều răn, cho Y-sơ-ra-ên làm giao ước đời đời.'),
(15618, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 11, 'OT', 'Mà rằng: Ta sẽ ban cho ngươi đất Ca-na-an, làm phần sản nghiệp của các ngươi.'),
(15619, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 12, 'OT', 'Khi họ còn ít người, rất ít, và là khách lạ trong xứ,'),
(15620, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 13, 'OT', 'Họ đi từ dân này đến dân khác, từ một vương quốc đến một dân tộc khác.'),
(15621, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 14, 'OT', 'Đức Giê-hô-va không để ai hà hiếp họ; và Ngài quở trách các vua vì cớ họ.'),
(15622, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 15, 'OT', 'Đừng đụng đến kẻ Ta đã xức dầu, và đừng làm hại các nhà tiên tri của Ta.'),
(15623, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 16, 'OT', 'Ngài gọi cơn đói đến trên đất, và bẻ gãy mọi cây gậy của lương thực.'),
(15624, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 17, 'OT', 'Ngài sai một người đi trước họ, là Giô-sép, bị bán làm tôi mọi.'),
(15625, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 18, 'OT', 'Họ tra tấn người bằng xiềng xích nơi chân người, và linh hồn người bị giam giữ trong xiềng sắt.'),
(15626, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 19, 'OT', 'Cho đến khi lời người phán được ứng nghiệm: Lời Đức Giê-hô-va thử luyện người.'),
(15627, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 20, 'OT', 'Vua sai đi, bèn tha Giô-sép; Đấng cai trị các dân, bèn mở mang người.'),
(15628, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 21, 'OT', 'Người đặt ông làm chủ trong nhà mình, và làm người quản trị toàn bộ tài sản mình.'),
(15629, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 22, 'OT', 'Để người trói buộc các quan trưởng mình theo ý mình, và dạy dỗ các bậc trưởng lão mình bằng sự khôn ngoan.'),
(15630, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 23, 'OT', 'Y-sơ-ra-ên vào Ai-cập, và Gia-cốp tạm trú trong đất của Hăm.'),
(15631, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 24, 'OT', 'Đức Giê-hô-va khiến dân Ngài sinh sôi rất nhiều và trở nên mạnh mẽ hơn các kẻ thù nghịch mình.'),
(15632, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 25, 'OT', 'Ngài khiến lòng họ đổi để ghét dân Ngài, Lập mưu hại các tôi tớ Ngài.'),
(15633, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 26, 'OT', 'Ngài sai Môi-se tôi tớ Ngài, A-rôn mà Ngài đã chọn.'),
(15634, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 27, 'OT', 'Đặt các lời dấu và những phép lạ của Ngài trong xứ Hăm.'),
(15635, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 28, 'OT', 'Ngài sai sự tối tăm xuống, và nó làm cho trời tối sầm; nhưng chúng không chống nghịch lời Ngài.'),
(15636, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 29, 'OT', 'Ngài đổi nước của chúng nó ra huyết, và làm chết cá của chúng nó.'),
(15637, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 30, 'OT', 'Đất chúng nó đầy dẫy ếch nhái, ngay trong các phòng của các vua chúng nó nữa.'),
(15638, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 31, 'OT', 'Ngài phán, liền có ruồi muỗi bay đến, và kiến lửa trong khắp các bờ cõi chúng.'),
(15639, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 32, 'OT', 'Ngài ban mưa đá thay vì mưa móc, và ngọn lửa chớp cháy trong đất nước họ.'),
(15640, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 33, 'OT', 'Ngài đánh hại cây nho và cây vả của chúng nó, bẻ gãy cây cối nơi biên giới chúng nó.'),
(15641, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 34, 'OT', 'Ngài phán, liền có châu chấu, và cào cào, vô số lượng.'),
(15642, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 35, 'OT', 'Cắn-sả hết thảy các cây cỏ trong đất nước chúng nó, và cắn-sả trái của đất đai chúng nó.'),
(15643, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 36, 'OT', 'Ngài đánh giết mọi con đầu lòng trong xứ, tức là sức mạnh đầu tiên của mọi người.'),
(15644, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 37, 'OT', 'Đức Giê-hô-va dẫn Y-sơ-ra-ên ra khỏi đó với bạc và vàng; trong các chi phái của họ không có ai vấp ngã.'),
(15645, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 38, 'OT', 'Ê-díp-tô vui mừng khi dân Y-sơ-ra-ên ra đi; vì sự sợ hãi về họ đã giáng trên dân ấy.'),
(15646, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 39, 'OT', 'Ngài trải mây ra làm mái che, và lửa soi sáng ban đêm.'),
(15647, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 40, 'OT', 'Chúng nó cầu xin, thì Ngài khiến chim cút đến, và lấy bánh từ trời mà làm cho chúng nó no đủ.'),
(15648, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 41, 'OT', 'Mở vầng đá, nước bèn chảy ra, đi ngang qua nơi khô như thể một con sông.'),
(15649, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 42, 'OT', 'Vì Đức Giê-hô-va nhớ đến lời thánh của Ngài, nhớ đến Aùp-ra-ham, kẻ tôi tớ Ngài.'),
(15650, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 43, 'OT', 'Người dẫn dân mình ra trong niềm hân hoan, dẫn những kẻ chọn ra với tiếng reo mừng.'),
(15651, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 44, 'OT', 'Ngài ban cho họ đất các nước, và họ tiếp nhận công lao của các dân tộc;'),
(15652, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 105, 45, 'OT', 'Hầu cho họ giữ các mạng lịnh Ngài, và gìn giữ các luật lệ Ngài. Ha-lê-lu-gia!'),
(15653, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 1, 'OT', 'Ha-lê-lu-gia! Hãy ngợi khen Đức Giê-hô-va, vì Ngài là thiện; Bởi sự nhân từ Ngài tồn tại đời đời.'),
(15654, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 2, 'OT', 'Ai có thể thuật các việc dũng cảm của Đức Giê-hô-va, làm cho nghe được hết mọi lời ca ngợi Ngài?'),
(15655, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 3, 'OT', 'Phước thay cho kẻ giữ sự xét đoán, làm điều công chính mọi lúc!'),
(15656, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 4, 'OT', 'Lạy Đức Giê-hô-va, xin nhớ đến tôi theo ơn Ngài đối với dân Ngài; xin viếng thăm tôi với sự cứu rỗi của Ngài.'),
(15657, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 5, 'OT', 'Để được thấy điều tốt lành của những người Ngài chọn, để vui hưởng niềm vui của dân Ngài, và được hân hoan cùng cơ nghiệp Ngài.'),
(15658, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 6, 'OT', 'Chúng tôi đã phạm tội cùng tổ tiên mình, chúng tôi đã làm điều sai trái, chúng tôi đã làm điều ác.'),
(15659, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 7, 'OT', 'Tổ tiên chúng tôi ở Ai Cập không hiểu các phép lạ Ngài, chẳng nhớ đến sự nhân từ dồi dào của Ngài, và đã nổi loạn bên biển, tại Biển Đỏ.'),
(15660, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 8, 'OT', 'Nhưng Ngài đã cứu họ vì cớ danh Ngài, để tỏ ra quyền năng của Ngài.'),
(15661, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 9, 'OT', 'Ngài quở Biển Đỏ, nó bèn khô; Ngài dẫn Y-sơ-ra-ên đi ngang qua vực sâu như ngang đồng vắng.'),
(15662, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 10, 'OT', 'Ngài giải cứu họ khỏi tay kẻ ghét, và chuộc họ khỏi tay kẻ thù.'),
(15663, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 11, 'OT', 'Nước che phủ những kẻ thù nghịch của chúng nó; chẳng còn một ai trong bọn chúng nó.'),
(15664, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 12, 'OT', 'Họ tin theo lời Ngài, bèn hát bài ca ngợi khen Ngài.'),
(15665, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 13, 'OT', 'Họ vội vàng quên các công việc Ngài, không đợi theo lời khuyên bảo của Ngài.'),
(15666, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 14, 'OT', 'Họ thèm khát điều thèm muốn trong đồng vắng, và thử Đức Chúa Trời trong nơi hoang vu.'),
(15667, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 15, 'OT', 'Ngài ban cho chúng nó điều chúng nó mong ước, nhưng sai sự thèm muốn vào trong tâm hồn chúng nó.'),
(15668, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 16, 'OT', 'Trong trại, họ ganh ghét Môi-se và A-rôn, là người thánh của Đức Giê-hô-va.'),
(15669, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 17, 'OT', 'Đất nứt ra nuốt Đa-than, và phủ lấy hội chúng của A-bi-ran.'),
(15670, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 18, 'OT', 'Lửa bốc lên trong hội chúng của chúng nó, ngọn lửa thiêu trụi những kẻ ác.'),
(15671, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 19, 'OT', 'Tổ tiên chúng tôi đã làm một con bò tơ tại Hô-rếp, và thờ lạy trước hình đúc.'),
(15672, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 20, 'OT', 'Họ đổi vinh hiển mình lấy hình tượng con bò ăn cỏ.'),
(15673, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 21, 'OT', 'Họ quên Đức Chúa Trời là Đấng cứu rỗi mình, Đấng đã làm những việc lớn lao tại Ai Cập.'),
(15674, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 22, 'OT', 'Những việc kỳ diệu tại xứ Hăm, những việc đáng sợ trên Biển Đỏ.'),
(15675, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 23, 'OT', 'Thì Ngài phán sẽ tiêu diệt chúng nó, nếu không phải Môi-se, kẻ được Ngài chọn, đứng vào chỗ nứt nẻ trước mặt Ngài, để xây lại cơn thịnh nộ của Ngài khỏi tiêu diệt chúng nó.'),
(15676, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 24, 'OT', 'Họ khinh bỉ đất lành, không tin lời của Ngài.'),
(15677, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 25, 'OT', 'Họ lằm bằm trong trại mình, không nghe tiếng Đức Giê-hô-va.'),
(15678, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 26, 'OT', 'Người đã giơ tay mình lên cùng họ, để làm cho chúng ngã đổ trong đồng vắng,'),
(15679, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 27, 'OT', 'và làm đổ dòng dõi họ giữa các dân tộc, và làm tan lạc họ trong các xứ.'),
(15680, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 28, 'OT', 'Chúng liên kết với Ba-anh-Phê-ô và ăn của lễ tế những người chết.'),
(15681, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 29, 'OT', 'Họ làm cho Đức Chúa Trời nổi giận vì những hành động của mình, và một cơn dịch bệnh đã lan tràn giữa họ.'),
(15682, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 30, 'OT', 'Bấy giờ Phi-nê-a đứng dậy cầu nguyện, và tai vạ liền bị chặn lại.'),
(15683, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 31, 'OT', 'Việc đó được kể cho người như sự công bình, cho đến muôn đời, đời này sang đời khác, mãi mãi vô cùng.'),
(15684, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 32, 'OT', 'Họ làm cho Đức Giê-hô-va nổi giận tại các nước Mê-ri-ba, nên tai họa xảy đến cho Môi-se vì cớ họ.'),
(15685, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 33, 'OT', 'Vì chúng làm cho lòng người nổi giận, nên người nói ra những lời thiếu suy nghĩ.'),
(15686, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 34, 'OT', 'Họ không tiêu diệt các dân mà Đức Giê-hô-va đã phán dặn họ.'),
(15687, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 35, 'OT', 'Họ lại kết hợp với các dân tộc ngoại, và học theo cách hành động của chúng,'),
(15688, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 36, 'OT', 'Họ thờ lạy các hình tượng của chúng nó, và những hình tượng ấy trở nên cái bẫy cho họ.'),
(15689, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 37, 'OT', 'Họ giết con trai con gái mình mà dâng tế cho các thần.'),
(15690, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 38, 'OT', 'Họ đổ huyết vô tội, tức là huyết các con trai và con gái mình, mà họ đã dâng tế cho các hình tượng của xứ Ca-na-an; nên đất bị ô uế bởi những huyết đó.'),
(15691, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 39, 'OT', 'Họ làm mình ra ô uế vì hành động của mình, và thông dâm bởi những việc họ làm.'),
(15692, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 40, 'OT', 'Cơn giận của Đức Giê-hô-va nổi lên nghịch cùng dân Ngài, và Ngài gớm ghét cơ nghiệp mình;'),
(15693, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 41, 'OT', 'Người phó họ vào tay các dân tộc, và những kẻ ghét họ thống trị họ.'),
(15694, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 42, 'OT', 'Kẻ thù hà hiếp chúng, và chúng bị khuất phục dưới tay chúng nó.'),
(15695, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 43, 'OT', 'Nhiều lần Đức Giê-hô-va giải cứu họ, nhưng họ lại chống nghịch trong mưu kế mình, và bị bại hoại vì tội ác của họ.'),
(15696, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 44, 'OT', 'Dầu vậy, khi nghe tiếng kêu la của họ, Ngài bèn đoái xem họ trong cơn khốn khổ họ,'),
(15697, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 45, 'OT', 'Nhớ lại cho họ giao ước mình, và hối tiếc theo sự nhân từ rất lớn của Ngài.'),
(15698, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 46, 'OT', 'Người khiến họ được thương xót trước mặt mọi kẻ bắt giữ họ.'),
(15699, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 47, 'OT', 'Cứu chúng tôi, hỡi Đức Giê-hô-va Đức Chúa Trời chúng tôi, và nhóm chúng tôi lại từ giữa các dân, để cảm tạ danh thánh Ngài, để khoe mình về sự ngợi khen Ngài.'),
(15700, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 106, 48, 'OT', 'Đáng ngợi khen Đức Giê-hô-va, Đức Chúa Trời của Y-sơ-ra-ên, từ trước vô cùng cho đến đời đời! Và cả dân sự nói: A-men! Ha-lê-lu-gia!'),
(15701, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 1, 'OT', 'Hãy cảm tạ Đức Giê-hô-va vì Ngài là thiện; sự nhân từ của Ngài tồn tại đời đời.'),
(15702, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 2, 'OT', 'Các người đã được Đức Giê-hô-va chuộc, mà Ngài đã chuộc khỏi tay kẻ hà hiếp, hãy nói điều đó.'),
(15703, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 3, 'OT', 'Họ đã hiệp lại từ các vùng đất, từ phương đông và phương tây, từ phương bắc và phương nam.'),
(15704, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 4, 'OT', 'Họ lang thang trong đồng vắng, trên con đường hoang vu, không tìm được thành phố để ở.'),
(15705, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 5, 'OT', 'Họ bị đói khát, linh hồn họ hao mòn trong chính mình.'),
(15706, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 6, 'OT', 'Họ kêu cứu Đức Giê-hô-va trong cơn gian truân; Ngài bèn giải cứu họ khỏi những nỗi khốn khổ của họ.'),
(15707, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 7, 'OT', 'Dẫn dắt họ trên con đường ngay thẳng, để đi đến một thành nơi ở.'),
(15708, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 8, 'OT', 'Hãy cảm tạ Đức Giê-hô-va về sự nhân từ của Ngài, và các việc diệu kỳ Ngài làm cho con cái loài người!'),
(15709, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 9, 'OT', 'Vì Ngài làm cho hồn khao khát được no đủ, và hồn đói được đầy dẫy điều tốt.'),
(15710, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 10, 'OT', 'Những kẻ ngồi trong tối tăm và bóng sự chết, làm tù nhân trong cảnh khốn khổ và xiềng xích,'),
(15711, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 11, 'OT', 'Vì chúng đã chống nghịch các lời phán của Đức Chúa Trời, Và khinh dể mưu luận của Đấng Tối Cao.'),
(15712, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 12, 'OT', 'Ngài lấy sự lao khổ mà khuất phục lòng họ; họ vấp ngã, không ai giúp đỡ.'),
(15713, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 13, 'OT', 'Họ kêu cầu Đức Giê-hô-va trong cơn gian truân; Ngài bèn giải cứu họ khỏi khốn cảnh.'),
(15714, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 14, 'OT', 'Người kéo họ ra khỏi bóng tối và bóng sự chết, và bẻ gãy xiềng xích của họ.'),
(15715, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 15, 'OT', 'Hãy cảm tạ Đức Giê-hô-va về sự nhân từ của Ngài, và những việc kỳ diệu Ngài làm cho con loài người.'),
(15716, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 16, 'OT', 'Vì Ngài đã phá vỡ các cửa đồng, Và đập gãy các then sắt.'),
(15717, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 17, 'OT', 'Kẻ ngu dại bị khốn khổ vì con đường vi phạm của chúng, và vì tội ác mình mà phải chịu đau đớn'),
(15718, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 18, 'OT', 'Họ kinh tởm mọi thứ thức ăn; họ gần đến cửa ải của sự chết.'),
(15719, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 19, 'OT', 'Họ kêu cầu Đức Giê-hô-va trong cơn gian truân của mình; Ngài giải cứu họ khỏi sự khốn khổ họ.'),
(15720, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 20, 'OT', 'Ngài sai lời Ngài đến, và chữa lành họ; Ngài cứu họ khỏi sự hủy diệt.'),
(15721, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 21, 'OT', 'Hãy cảm tạ Đức Giê-hô-va về sự nhân từ của Ngài, và các việc lạ lùng Ngài làm cho con cái loài người!'),
(15722, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 22, 'OT', 'Họ hãy dâng những của lễ tạ ơn, và thuật lại các công việc Ngài trong tiếng reo mừng.'),
(15723, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 23, 'OT', 'Họ xuống biển trên những chiếc tàu, làm việc nơi các vùng nước rộng lớn.'),
(15724, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 24, 'OT', 'Họ đã thấy công việc của Đức Giê-hô-va, và những sự kỳ diệu của Ngài trong vực thẳm.'),
(15725, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 25, 'OT', 'Đức Giê-hô-va phán, liền nổi gió bão lên, khiến các lượn sóng mình cao lên.'),
(15726, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 26, 'OT', 'Họ lên tận các từng trời, rồi xuống tận vực thẳm; lòng họ tan chảy vì khốn khổ.'),
(15727, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 27, 'OT', 'Họ loạng choạng, vật vã như người say rượu, và mọi sự khôn ngoan của họ đều bị nuốt mất.'),
(15728, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 28, 'OT', 'Họ kêu cầu Đức Giê-hô-va trong cơn khốn khổ, và Ngài giải cứu họ khỏi những nỗi nguy nan.'),
(15729, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 29, 'OT', 'Ngài làm cho cơn bão trở nên yên lặng, và các con sóng liền im ắng.'),
(15730, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 30, 'OT', 'Họ vui mừng vì biển yên lặng; Ngài dẫn họ đến nơi họ mong ước.'),
(15731, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 31, 'OT', 'Nguyện người ta cảm tạ Đức Giê-hô-va về sự nhân từ của Ngài, và về các việc lạ lùng Ngài làm cho con loài người!'),
(15732, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 32, 'OT', 'Họ hãy tôn cao Ngài trong hội chúng dân sự, và ngợi khen Ngài tại nơi nhóm họp của các bậc trưởng lão.'),
(15733, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 33, 'OT', 'Biến các con sông thành đồng vắng, các mạch nước thành đất khô hanh.'),
(15734, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 34, 'OT', 'Đất màu mỡ trở nên đất mặn, vì sự gian ác của những người cư ngụ trong đó.'),
(15735, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 35, 'OT', 'Ngài biến sa mạc thành ao nước, đất khô thành suối nước.'),
(15736, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 36, 'OT', 'Người ta lập nơi đó cho kẻ đói được ở, và họ xây thành để cư ngụ.'),
(15737, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 37, 'OT', 'Họ gieo các thửa ruộng và trồng các vườn nho, rồi làm ra hoa quả của mùa màng.'),
(15738, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 38, 'OT', 'Người ban phước cho họ, và họ sinh sản rất nhiều; và súc vật của họ không bị giảm bớt.'),
(15739, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 39, 'OT', 'Họ lại trở nên ít ỏi và bị khuất phục, vì sự áp bức, khốn khổ và buồn rầu.'),
(15740, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 40, 'OT', 'Ngài đổ sự sỉ nhục trên những người quyền quý, khiến họ lang thang trong vùng đất hoang vu không có đường đi.'),
(15741, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 41, 'OT', 'Nhưng Ngài làm cho kẻ nghèo khó được lên khỏi sự khốn cùng, và đặt gia quyến người như bầy chiên.'),
(15742, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 42, 'OT', 'Các người ngay thẳng sẽ thấy và vui mừng, còn mọi điều gian ác phải ngậm miệng lại.'),
(15743, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 107, 43, 'OT', 'Ai là người khôn ngoan thì sẽ giữ những điều nầy, và suy gẫm các ân huệ của Đức Giê-hô-va.'),
(15744, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 108, 1, 'OT', 'Lòng tôi vững chắc, hỡi Đức Chúa Trời; tôi sẽ hát và gảy nhạc, cả lòng tôi.'),
(15745, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 108, 2, 'OT', 'Hãy tỉnh thức, hỡi đờn sắt và đờn cầm! Tôi sẽ đánh thức buổi ban mai.'),
(15746, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 108, 3, 'OT', 'Hỡi Đức Giê-hô-va, tôi sẽ cảm tạ Ngài giữa các dân; tôi sẽ đàn hát ngợi khen Ngài giữa các nước.'),
(15747, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 108, 4, 'OT', 'Vì sự nhân từ của Ngài cao hơn các từng trời, và sự thật của Ngài đến tận các đám mây.'),
(15748, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 108, 5, 'OT', 'Hỡi Đức Chúa Trời, nguyện Ngài được tôn cao trên các từng trời; và sự vinh hiển Ngài trên khắp cả đất.'),
(15749, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 108, 6, 'OT', 'Hầu cho những người yêu dấu của Ngài được giải cứu, xin hãy lấy tay phải Ngài mà cứu giúp và nhậm lời tôi.'),
(15750, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 108, 7, 'OT', 'Đức Chúa Trời đã phán trong nơi thánh Ngài: Ta sẽ mừng rỡ; Ta sẽ chia Si-chem và đo trũng Su-cốt.'),
(15751, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 108, 8, 'OT', 'Ga-la-át thuộc về ta, Ma-na-se cũng thuộc về ta; Eùp-ra-im là đồn lũy của đầu ta; Giu-đa là cây phủ việt ta;'),
(15752, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 108, 9, 'OT', 'Mô-áp là cái chậu rửa chân tôi; trên Ê-đôm tôi quăng dép tôi; về đất Phi-li-tin tôi cất tiếng reo mừng.'),
(15753, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 108, 10, 'OT', 'Ai sẽ dẫn tôi đến thành có vách thành? Ai sẽ dẫn tôi đến Ê-đôm?'),
(15754, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 108, 11, 'OT', 'Hỡi Đức Chúa Trời, há chẳng phải Ngài đã từ bỏ chúng tôi sao? Hỡi Đức Chúa Trời, Ngài há chẳng ra đi cùng các đạo binh chúng tôi nữa?'),
(15755, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 108, 12, 'OT', 'Xin hãy ban cho chúng tôi sự giúp đỡ từ nơi gian truân; vì sự cứu rỗi của loài người là hư không.'),
(15756, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 108, 13, 'OT', 'Nhờ Đức Chúa Trời chúng tôi sẽ làm những việc dũng mãnh; Chính Ngài sẽ giày đạp các kẻ thù nghịch chúng tôi.'),
(15757, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 109, 1, 'OT', 'Hỡi Đức Chúa Trời của sự ngợi khen tôi, xin chớ nín lặng.'),
(15758, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 109, 2, 'OT', 'Vì miệng kẻ ác và miệng sự gian dối đã mở ra nghịch lại tôi; chúng nói với tôi bằng lưỡi dối trá.'),
(15759, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 109, 3, 'OT', 'Lời nói đầy oán ghét vây hãm tôi, và chúng tranh chiến với tôi cách vô cớ.'),
(15760, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 109, 4, 'OT', 'Thay vì yêu tôi, chúng ghét tôi; còn tôi, tôi cứ chuyên lòng cầu nguyện.'),
(15761, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 109, 5, 'OT', 'Chúng đặt điều ác thay cho điều lành ta làm, và lấy sự ghét bỏ thay cho tình yêu ta dành cho chúng.'),
(15762, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 109, 6, 'OT', 'Hãy đặt một kẻ ác cai trị nó, và cho Sa-tan đứng bên phải nó.'),
(15763, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 109, 7, 'OT', 'Khi bị xét xử, nguyện nó ra kẻ có tội, và lời cầu nguyện của nó trở nên tội lỗi.'),
(15764, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 109, 8, 'OT', 'Nguyện các ngày nó ngắn ngủi; nguyện kẻ khác nhận chức vụ nó.'),
(15765, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 109, 9, 'OT', 'Nguyện các con nó trở nên mồ côi, và vợ nó trở nên góa bụa.'),
(15766, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 109, 10, 'OT', 'Các con nó sẽ lang thang, ăn xin và tìm kiếm từ các nơi đổ nát của chúng.'),
(15767, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 109, 11, 'OT', 'Nguyện chủ nợ bắt giữ mọi vật người ấy sở hữu; và kẻ ngoại bang cướp lấy hoa lợi của công lao người ấy.'),
(15768, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 109, 12, 'OT', 'Nguyện chẳng ai tỏ lòng nhân từ với nó, và nguyện chẳng ai tỏ lòng thương xót cho các con mồ côi của nó.'),
(15769, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 109, 13, 'OT', 'Nguyện dòng dõi nó bị diệt mất, trong đời sau tên nó bị xóa đi.'),
(15770, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 109, 14, 'OT', 'Nguyện tội ác của cha nó được Đức Giê-hô-va ghi nhớ, và tội lỗi mẹ nó thì chẳng bao giờ bị xóa bỏ.'),
(15771, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 109, 15, 'OT', 'Nguyện chúng luôn ở trước mặt Đức Giê-hô-va, để Ngài diệt khỏi đất kỷ niệm về chúng nó.'),
(15772, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 109, 16, 'OT', 'Vì người không nhớ làm ơn, mà ngược lại bắt bớ người nghèo khó, kẻ thiếu thốn và kẻ lòng đau thương, để giết chết.'),
(15773, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 109, 17, 'OT', 'Nó yêu sự rủa sả, và sự rủa sả ấy đã đến với nó; nó không ưa sự chúc phước, nên phước lành bèn lìa xa nó.'),
(15774, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 109, 18, 'OT', 'Nó mặc sự rủa sả như cái áo, sự rủa sả ấy thấm vào lòng nó như nước, và như dầu vào xương cốt nó.'),
(15775, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 109, 19, 'OT', 'Nguyện sự rủa sả bao phủ nó như cái áo, và như cái đai, luôn luôn thắt chặt quanh mình.'),
(15776, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 109, 20, 'OT', 'Đức Giê-hô-va sẽ làm như vậy cho những kẻ chống nghịch tôi, và cho những kẻ nói điều ác nghịch linh hồn tôi.'),
(15777, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 109, 21, 'OT', 'Nhưng, hỡi Đức Giê-hô-va, Chúa tôi, xin hãy làm điều nầy vì cớ danh Ngài; vì sự nhân từ của Ngài là tốt, xin hãy giải cứu tôi.'),
(15778, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 109, 22, 'OT', 'Vì tôi khốn khổ và nghèo hèn, lòng tôi bị tan nát trong chính mình tôi.'),
(15779, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 109, 23, 'OT', 'Tôi đi như bóng lúc chiều tà, bị xua đuổi như con châu chấu.'),
(15780, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 109, 24, 'OT', 'Đầu gối tôi run rẩy vì đói, và thân thể tôi tiều tụy vì thiếu chất béo.'),
(15781, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 109, 25, 'OT', 'Còn tôi, tôi đã trở thành sự sỉ nhục cho chúng nó; chúng thấy tôi thì lắc đầu.'),
(15782, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 109, 26, 'OT', 'Lạy Đức Giê-hô-va, Đức Chúa Trời tôi, xin giúp đỡ tôi; cứu tôi theo sự nhân từ của Ngài.'),
(15783, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 109, 27, 'OT', 'Hầu cho người ta biết rằng tay nầy là của Ngài; chính Đức Giê-hô-va, chính Ngài đã làm điều đó.'),
(15784, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 109, 28, 'OT', 'Chúng nó rủa sả, còn Ngài sẽ ban phước; chúng nó dấy lên chống lại, rồi phải hổ thẹan, nhưng tôi tớ Ngài sẽ vui vẻ.'),
(15785, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 109, 29, 'OT', 'Nguyện những kẻ chống nghịch tôi mặc lấy sự sỉ nhục, và bao phủ mình bằng sự hổ thẹn như cái áo.'),
(15786, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 109, 30, 'OT', 'Tôi sẽ hết lòng cảm tạ Đức Giê-hô-va bằng miệng tôi, và giữa vòng đông người tôi sẽ ngợi khen Ngài.'),
(15787, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 109, 31, 'OT', 'Vì Ngài đứng bên phải người nghèo khó, đặng giải cứu người khỏi những kẻ kết án linh hồn người.'),
(15788, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 110, 1, 'OT', 'Đức Giê-hô-va phán cùng Chúa tôi: Hãy ngồi bên phải Ta, cho đến khi Ta đặt các kẻ thù nghịch ngươi dưới bệ chân ngươi.'),
(15789, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 110, 2, 'OT', 'Đức Giê-hô-va sẽ từ Si-ôn sai ra cây quyền trượng quyền năng của ngươi; hãy thống trị giữa vòng các kẻ thù nghịch ngươi.'),
(15790, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 110, 3, 'OT', 'Dân ngươi tình nguyện trong ngày quyền năng của ngươi, trong vẻ vang thánh khiết, từ lòng rạng đông, sương của những đứa trẻ ngươi.'),
(15791, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 110, 4, 'OT', 'Đức Giê-hô-va đã thề và sẽ không hối hận: Ngươi là thầy tế lễ đời đời, theo phẩm trật của Mên-chi-xê-đéc.'),
(15792, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 110, 5, 'OT', 'Đức Giê-hô-va ở bên phải ngươi sẽ nghiền nát các vua trong ngày Ngài nổi giận.'),
(15793, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 110, 6, 'OT', 'Ngài sẽ xét xử giữa các nước, làm đầy khắp nơi bởi những xác chết; nghiền nát đầu của đất nước lớn.'),
(15794, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 110, 7, 'OT', 'Từ dòng nước bên đường, Ngài sẽ uống; bởi vậy, Ngài sẽ ngước đầu lên.'),
(15795, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 111, 1, 'OT', 'Ha-lê-lu-gia! Tôi sẽ hết lòng ngợi khen Đức Giê-hô-va, trong vòng hội những người ngay thẳng và trong hội chúng.'),
(15796, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 111, 2, 'OT', 'Các công việc của Đức Giê-hô-va đều lớn lao; người nào ưa thích, sẽ tìm tòi kỹ chúng.'),
(15797, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 111, 3, 'OT', 'Sự oai nghiêm và vẻ huy hoàng thuộc về công việc Ngài; sự công chính của Ngài tồn tại đời đời.'),
(15798, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 111, 4, 'OT', 'Đức Giê-hô-va đã để lại kỷ niệm về những việc lạ lùng Ngài làm; Ngài nhân từ và đầy lòng thương xót.'),
(15799, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 111, 5, 'OT', 'Ngài đã ban của ăn cho những kẻ kính sợ Ngài; Ngài nhớ đến sự giao ước đời đời của Ngài.'),
(15800, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 111, 6, 'OT', 'Ngài đã tỏ cho dân Ngài quyền năng các công việc Ngài, để ban cho họ sản nghiệp của các nước.'),
(15801, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 111, 7, 'OT', 'Các công việc của tay Ngài là chân thật và công chính; mọi điều răn của Ngài đều đáng tin cậy.'),
(15802, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 111, 8, 'OT', 'Đứng vững chắc đến muôn đời, làm bởi sự thật và ngay thẳng.'),
(15803, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 111, 9, 'OT', 'Ngài đã sai sự cứu chuộc cho dân Ngài; lập giao ước Ngài đời đời. Danh Ngài là thánh và đáng kính sợ.'),
(15804, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 111, 10, 'OT', 'Sự kính sợ Đức Giê-hô-va là khởi đầu sự khôn ngoan; sự hiểu biết tốt đẹp cho mọi người làm theo Ngài. Sự ngợi khen Ngài còn đến đời đời.'),
(15805, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 112, 1, 'OT', 'Ha-lê-lu-gia! Phước cho người nào kính sợ Đức Giê-hô-va, rất ưa thích điều răn của Ngài!'),
(15806, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 112, 2, 'OT', 'Dòng dõi người sẽ hùng cường trên đất; dòng dõi những người ngay thẳng sẽ được ban phước.'),
(15807, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 112, 3, 'OT', 'Của cải và sự giàu có ở trong nhà người, và sự công bình của người đứng vững mãi mãi.'),
(15808, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 112, 4, 'OT', 'Ánh sáng mọc lên trong bóng tối cho người ngay thẳng; Đấng nhân từ, đầy lòng thương xót và công bình.'),
(15809, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 112, 5, 'OT', 'Phước cho người nhân từ và cho vay mượn; người ấy sẽ xét đoán công việc mình cách ngay thẳng.'),
(15810, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 112, 6, 'OT', 'Người sẽ không bao giờ bị lay chuyển; đến đời đời người công bình sẽ được ghi nhớ.'),
(15811, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 112, 7, 'OT', 'Người không sợ trước tin dữ; lòng người vững vàng, tin cậy nơi Đức Giê-hô-va.'),
(15812, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 112, 8, 'OT', 'Lòng người vững chắc, không sợ hãi, cho đến khi thấy kẻ thù mình bị báo oán.'),
(15813, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 112, 9, 'OT', 'Phân phát, ban cho kẻ nghèo khó; sự công bình người còn mãi đời đời; sừng người được ngước lên trong vinh hiển.'),
(15814, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 112, 10, 'OT', 'Kẻ ác sẽ thấy và tức giận, nghiến răng và tan nát; sự ước ao của kẻ ác sẽ tiêu mất.'),
(15815, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 113, 1, 'OT', 'Ha-lê-lu-gia! Hỡi các tôi tớ Đức Giê-hô-va, hãy ngợi khen; hãy ngợi khen danh Đức Giê-hô-va.'),
(15816, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 113, 2, 'OT', 'Đáng chúc tụng danh Đức Giê-hô-va, từ bây giờ và đến mãi đời đời.'),
(15817, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 113, 3, 'OT', 'Từ nơi mặt trời mọc cho đến nơi mặt trời lặp, danh Đức Giê-hô-va được ca ngợi.'),
(15818, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 113, 4, 'OT', 'Đức Giê-hô-va siêu cao hơn mọi dân tộc, sự vinh hiển Ngài siêu cao trên các từng trời.'),
(15819, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 113, 5, 'OT', 'Ai giống như Đức Giê-hô-va Đức Chúa Trời chúng tôi, Đấng ngự cao sang trên trời?'),
(15820, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 113, 6, 'OT', 'Đấng làm hạ mình xuống để nhìn xem nơi các từng trời và đất.'),
(15821, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 113, 7, 'OT', 'Đấng làm cho người nghèo khó đứng dậy từ bụi tro, khiến kẻ khốn cùng từ đống rác đứng lên,'),
(15822, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 113, 8, 'OT', 'Để cho người ngồi cùng với các quý tộc, cùng với các quý tộc trong dân sự Ngài.'),
(15823, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 113, 9, 'OT', 'Ha-lê-lu-gia! Ngài khiến người đàn bà son sẻ ngồi trong nhà, làm mẹ vui vẻ của các con cái.'),
(15824, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 114, 1, 'OT', 'Khi Y-sơ-ra-ên ra khỏi Ai-cập, nhà Gia-cốp ra khỏi một dân nói tiếng lạ,'),
(15825, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 114, 2, 'OT', 'Giu-đa trở nên đền thánh của Đức Giê-hô-va, Y-sơ-ra-ên trở nên nơi cai trị của Ngài.'),
(15826, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 114, 3, 'OT', 'Biển thấy vậy liền chạy trốn, sông Giô-đanh chảy ngược lại phía sau.'),
(15827, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 114, 4, 'OT', 'Các núi nhảy múa như những con chiên đực, các gò đống như những con chiên con.'),
(15828, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 114, 5, 'OT', 'Biển ơi, vì sao ngươi chạy trốn? Giô-đanh ơi, vì sao ngươi chảy ngược về phía sau?'),
(15829, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 114, 6, 'OT', 'Hỡi các núi, hãy nhảy múa như những con chiên đực; hỡi các đồi, như những con chiên con!'),
(15830, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 114, 7, 'OT', 'Hỡi đất, hãy run rẩy trước mặt Đức Giê-hô-va, trước mặt Đức Chúa Trời của Gia-cốp.'),
(15831, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 114, 8, 'OT', 'Là Đấng biến tảng đá thành ao nước, tảng đá cứng thành suối nước.'),
(15832, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 115, 1, 'OT', 'Hỡi Đức Giê-hô-va, chớ về chúng tôi, chớ về chúng tôi, nhưng vì danh Ngài mà ban sự vinh hiển, vì sự nhân từ và sự chân thật của Ngài.'),
(15833, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 115, 2, 'OT', 'Tại sao các dân lại nói: Đức Giê-hô-va của chúng nó ở đâu?'),
(15834, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 115, 3, 'OT', 'Đức Chúa Trời chúng tôi ở trên trời, làm mọi điều Ngài ưa muốn.'),
(15835, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 115, 4, 'OT', 'Tượng thần của chúng bằng bạc và vàng, là công việc làm ra bởi tay loài người.'),
(15836, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 115, 5, 'OT', 'Chúng có miệng mà không nói; có mắt mà không thấy;'),
(15837, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 115, 6, 'OT', 'Tai chúng nó có mà không nghe được; lỗ mũi chúng nó có mà không ngửi được.'),
(15838, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 115, 7, 'OT', 'Chúng có tay nhưng không thể nắm, có chân nhưng không thể đi, họng chúng không thể phát ra tiếng.'),
(15839, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 115, 8, 'OT', 'Họ sẽ giống như những hình tượng ấy, mọi người tin cậy nơi chúng.'),
(15840, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 115, 9, 'OT', 'Hỡi Y-sơ-ra-ên, hãy nhờ cậy nơi Đức Giê-hô-va; Ngài là sự giúp đỡ và cái khiên che chở ngươi.'),
(15841, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 115, 10, 'OT', 'Hỡi nhà A-rôn, hãy tin cậy nơi Đức Giê-hô-va; chính Ngài là sự giúp đỡ và là cái khiên của các ngươi.'),
(15842, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 115, 11, 'OT', 'Hỡi các người kính sợ Đức Giê-hô-va, hãy tin cậy nơi Đức Giê-hô-va; Ngài là Đấng phù trợ và là cái khiên của họ.'),
(15843, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 115, 12, 'OT', 'Đức Giê-hô-va nhớ đến chúng tôi; Ngài sẽ ban phước, ban phước cho nhà Y-sơ-ra-ên, ban phước cho nhà A-rôn.'),
(15844, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 115, 13, 'OT', 'Ngài sẽ ban phước cho những kẻ kính sợ Đức Giê-hô-va, kẻ nhỏ cùng với kẻ lớn.'),
(15845, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 115, 14, 'OT', 'Nguyện Đức Giê-hô-va ban thêm ơn cho các ngươi, cho các ngươi và cho con cái các ngươi.'),
(15846, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 115, 15, 'OT', 'Phước cho các ngươi bởi Đức Giê-hô-va, là Đấng làm nên trời và đất.'),
(15847, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 115, 16, 'OT', 'Các từng trời là của Đức Giê-hô-va; còn đất thì Ngài đã ban cho con cái loài người.'),
(15848, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 115, 17, 'OT', 'Kẻ chết không ngợi khen Đức Giê-hô-va, và cũng không ai xuống vực im lặng.'),
(15849, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 115, 18, 'OT', 'Nhưng chúng tôi sẽ chúc tụng Đức Giê-hô-va từ bây giờ và đến mãi mãi. Ha-lê-lu-gia!'),
(15850, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 116, 1, 'OT', 'Tôi yêu Đức Giê-hô-va, vì Ngài nghe tiếng tôi, và lời khẩn cầu của tôi.'),
(15851, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 116, 2, 'OT', 'Vì Ngài đã nghiêng tai về tôi, nên trọn đời tôi tôi sẽ kêu cầu Ngài.'),
(15852, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 116, 3, 'OT', 'Các dây sự chết xiết chặt tôi, và những cơn đau của âm phủ đã tìm được tôi; tôi gặp sự khốn quẫn và nỗi buồn thảm.'),
(15853, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 116, 4, 'OT', 'Tôi kêu cầu danh Đức Giê-hô-va, rằng: Đức Giê-hô-va ôi! xin cứu lấy linh hồn tôi.'),
(15854, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 116, 5, 'OT', 'Đức Giê-hô-va nhân từ và công bình; Đức Chúa Trời chúng ta đầy lòng thương xót.'),
(15855, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 116, 6, 'OT', 'Đức Giê-hô-va giữ gìn kẻ chất phác; khi tôi bị khốn khổ, thì Ngài cứu tôi.'),
(15856, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 116, 7, 'OT', 'Hỡi linh hồn ta, hãy trở về nơi an nghỉ của ngươi; vì Đức Giê-hô-va đã làm ơn cho ngươi.'),
(15857, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 116, 8, 'OT', 'Vì Đức Giê-hô-va đã giải cứu linh hồn tôi khỏi sự chết, mắt tôi khỏi lệ rơi, chân tôi khỏi vấp ngã.'),
(15858, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 116, 9, 'OT', 'Tôi sẽ đi trước mặt Đức Giê-hô-va trong các miền đất của kẻ sống.'),
(15859, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 116, 10, 'OT', 'Tôi tin, nên tôi nói; tôi đã bị khốn khổ rất nhiều.'),
(15860, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 116, 11, 'OT', 'Trong cơn hoảng hốt, tôi nói: Mọi loài người đều nói dối.'),
(15861, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 116, 12, 'OT', 'Tôi sẽ lấy gì đền đáp Đức Giê-hô-va về mọi ơn lành Ngài đã làm cho tôi?'),
(15862, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 116, 13, 'OT', 'Tôi sẽ cầm chén cứu rỗi, và cầu khẩn danh Đức Giê-hô-va.'),
(15863, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 116, 14, 'OT', 'Tôi sẽ trả xong cho Đức Giê-hô-va các lời hứa nguyện của tôi, tại trước mặt cả dân sự Ngài.'),
(15864, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 116, 15, 'OT', 'Sự chết của những người trung tín là quí báu trước mặt Đức Giê-hô-va.'),
(15865, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 116, 16, 'OT', 'Hỡi Đức Giê-hô-va, tôi thật là tôi tớ Ngài; tôi là tôi tớ Ngài, con trai người nữ tớ của Ngài; Ngài đã mở mang xiềng xích cho tôi.'),
(15866, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 116, 17, 'OT', 'Tôi sẽ dâng cho Ngài của lễ tạ ơn, và nhân danh Đức Giê-hô-va mà kêu cầu.'),
(15867, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 116, 18, 'OT', 'Tôi sẽ trả các lời hứa nguyện cho Đức Giê-hô-va, trước mặt cả dân sự Ngài.'),
(15868, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 116, 19, 'OT', 'Trong các hành lang của nhà Đức Giê-hô-va, ở giữa ngươi, Giê-ru-sa-lem. Ha-lê-lu-gia!'),
(15869, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 117, 1, 'OT', 'Hãy ngợi khen Đức Giê-hô-va, hỡi muôn dân! Hãy ca tụng Ngài, hỡi muôn nước!'),
(15870, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 117, 2, 'OT', 'Vì sự nhân từ Ngài đã thắng lớn cho chúng ta; sự thật của Đức Giê-hô-va còn đến đời đời. Ha-lê-lu-gia!'),
(15871, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 118, 1, 'OT', 'Hãy cảm tạ Đức Giê-hô-va vì Ngài là thiện; sự nhân từ Ngài còn mãi đời đời.'),
(15872, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 118, 2, 'OT', 'Nguyện Y-sơ-ra-ên nói rằng, Đức Giê-hô-va có lòng nhân từ đến đời đời.'),
(15873, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 118, 3, 'OT', 'Nhà A-rôn hãy nói rằng, sự nhân từ của Đức Giê-hô-va còn đời đời.'),
(15874, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 118, 4, 'OT', 'Nguyện những người kính sợ Đức Giê-hô-va nói rằng, vì sự nhân từ của Ngài còn đời đời.'),
(15875, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 118, 5, 'OT', 'Trong cơn gian truân tôi kêu cầu Đức Giê-hô-va; Đức Giê-hô-va đáp lời tôi trong nơi rộng rãi.'),
(15876, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 118, 6, 'OT', 'Đức Giê-hô-va ở cùng tôi, tôi không sợ; loài người sẽ làm gì tôi?'),
(15877, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 118, 7, 'OT', 'Đức Giê-hô-va ở cùng tôi, làm đấng giúp đỡ tôi; tôi sẽ nhìn thấy điều xảy ra cho những kẻ ghét tôi.'),
(15878, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 118, 8, 'OT', 'Thà nương náu nơi Đức Giê-hô-va Còn hơn tin cậy loài người.'),
(15879, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 118, 9, 'OT', 'Thà nương náu mình nơi Đức Giê-hô-va còn hơn tin cậy nơi các bậc quyền quý.'),
(15880, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 118, 10, 'OT', 'Các dân tộc đã vây quanh tôi; nhân danh Đức Giê-hô-va tôi sẽ tiêu diệt chúng nó.'),
(15881, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 118, 11, 'OT', 'Chúng vây tôi, phải, chúng vây tôi; tôi tiêu diệt chúng nó nhân danh Đức Giê-hô-va.'),
(15882, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 118, 12, 'OT', 'Họ vây tôi như bầy ong, thiêu đốt tôi như lửa gai; nhờ danh Đức Giê-hô-va, tôi đã nghiền nát chúng nó.'),
(15883, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 118, 13, 'OT', 'Người đã xô tôi cho ngã cách mạnh mẽ, nhưng Đức Giê-hô-va phù giúp tôi.'),
(15884, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 118, 14, 'OT', 'Đức Giê-hô-va là sức lực và bài ca của tôi; Ngài đã trở nên sự cứu rỗi của tôi.'),
(15885, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 118, 15, 'OT', 'Tiếng reo mừng và cứu rỗi vang lên trong các trại của người công bình: Tay phải Đức Giê-hô-va thi thố quyền năng.'),
(15886, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 118, 16, 'OT', 'Tay hữu Đức Giê-hô-va được ngự cao sang, tay hữu Đức Giê-hô-va làm nên quyền năng.'),
(15887, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 118, 17, 'OT', 'Tôi sẽ không chết, mà sẽ sống, và thuật lại những công việc của Đức Giê-hô-va.'),
(15888, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 118, 18, 'OT', 'Đức Giê-hô-va sửa phạt tôi cách nghiêm trọng, nhưng không phó tôi cho sự chết.'),
(15889, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 118, 19, 'OT', 'Hãy mở cho tôi các cửa công bình, tôi sẽ vào đó mà ngợi kinh Đức Giê-hô-va.'),
(15890, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 118, 20, 'OT', 'Đây là cổng của Đức Giê-hô-va; những người ngay thẳng sẽ vào trong đó.'),
(15891, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 118, 21, 'OT', 'Tôi sẽ cảm tạ Đức Giê-hô-va vì Ngài đã đáp lời tôi, Và đã trở nên sự cứu rỗi cho tôi.'),
(15892, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 118, 22, 'OT', 'Hòn đá mà những người thợ xây loại bỏ, đã trở nên đá góc nền.'),
(15893, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 118, 23, 'OT', 'Điều ấy là từ Đức Giê-hô-va, một điều lạ lùng trước mắt chúng tôi.'),
(15894, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 118, 24, 'OT', 'Đây là ngày Đức Giê-hô-va làm nên, chúng ta hãy vui mừng và hớn hở trong ngày ấy.'),
(15895, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 118, 25, 'OT', 'Đức Giê-hô-va ôi, xin cứu giúp! Đức Giê-hô-va ôi, xin ban sự thạnh vượng!'),
(15896, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 118, 26, 'OT', 'Đáng ngợi khen đấng nhân danh Đức Giê-hô-va mà đến! Chúng tôi đã chúc tụng các ngươi từ nhà Đức Giê-hô-va.'),
(15897, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 118, 27, 'OT', 'Đức Giê-hô-va là Đức Chúa Trời, và Ngài đã chiếu sáng cho chúng tôi. Hãy buộc lễ vật vào bằng các dây, cho đến các sừng của bàn thờ.'),
(15898, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 118, 28, 'OT', 'Đức Chúa Trời là Chúa tôi, tôi sẽ cảm tạ Ngài; Đức Chúa Trời tôi, tôi sẽ cao rao Ngài.'),
(15899, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 118, 29, 'OT', 'Hãy cảm tạ Đức Giê-hô-va, vì Ngài là thiện; sự nhân từ của Ngài còn mãi đời đời.'),
(15900, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 1, 'OT', 'Phước cho những người trọn vẹn trong đường lối, đi theo luật pháp của Đức Giê-hô-va,'),
(15901, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 2, 'OT', 'Phước cho những người giữ các chứng cớ của Đức Giê-hô-va, lấy trọn lòng tìm cầu Ngài.'),
(15902, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 3, 'OT', 'Họ không làm điều gian ác, mà bước đi trong các con đường của Ngài.'),
(15903, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 4, 'OT', 'Ngài đã ra lệnh phải hết sức tuân giữ các mạng lịnh của Ngài.'),
(15904, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 5, 'OT', 'Ôi! Phải chi các đường lối tôi được vững lập, để tôi giữ các luật lệ của Đức Giê-hô-va!'),
(15905, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 6, 'OT', 'Khi tôi nhìn xem mọi điều răn của Ngài, thì tôi sẽ không hổ thẹn.'),
(15906, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 7, 'OT', 'Tôi sẽ cảm tạ Đức Giê-hô-va trong sự ngay thẳng của lòng tôi, khi tôi học các mạng lịnh công bình của Ngài.'),
(15907, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 8, 'OT', 'Tôi sẽ giữ các luật lệ của Ngài; xin chớ bỏ tôi đến cùng.'),
(15908, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 9, 'OT', 'Người trẻ tuổi phải giữ gìn đường lối mình trong sạch bằng cách nào? Nhờ cẩn thận theo lời Ngài.'),
(15909, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 10, 'OT', 'Tôi hết lòng tìm cầu Ngài; xin chớ để tôi lạc khỏi các điều răn của Ngài.'),
(15910, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 11, 'OT', 'Tôi đã giấu lời Ngài trong lòng tôi, để tôi không phạm tội cùng Ngài.'),
(15911, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 12, 'OT', 'Đức Giê-hô-va, Ngài là Đáng Khen; xin dạy tôi các mạng lịnh của Ngài.'),
(15912, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 13, 'OT', 'Tôi lấy môi miệng thuật lại mọi quyết định từ miệng Ngài.'),
(15913, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 14, 'OT', 'Tôi vui mừng trong đường lối chứng cớ của Ngài, như thể vui mừng về mọi của cải.'),
(15914, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 15, 'OT', 'Tôi sẽ suy gẫm về các điều răn của Ngài, và chăm xem các đường lối của Ngài.'),
(15915, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 16, 'OT', 'Tôi vui vẻ trong các luật lệ của Ngài; tôi sẽ không quên lời Ngài.'),
(15916, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 17, 'OT', 'Xin Đức Giê-hô-va làm ơn cho tôi tớ Ngài, để tôi được sống; thì tôi sẽ giữ lời Ngài.'),
(15917, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 18, 'OT', 'Xin Đức Giê-hô-va mở mắt tôi để tôi nhìn thấy những điều kỳ diệu trong luật pháp Ngài.'),
(15918, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 19, 'OT', 'Tôi là khách lạ trên đất; xin chớ giấu tôi các mạng lịnh của Ngài.'),
(15919, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 20, 'OT', 'Linh hồn tôi hao mòn vì khao khát các mạng lịnh của Đức Giê-hô-va luôn luôn.'),
(15920, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 21, 'OT', 'Chúa Giê-hô-va quở trách những kẻ kiêu ngạo, bị rủa sả, những kẻ lạc xa các mạng lịnh của Ngài.'),
(15921, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 22, 'OT', 'Xin lăn khỏi tôi sự sỉ nhục và khinh miệt, vì tôi gìn giữ các chứng cớ của Đức Giê-hô-va.'),
(15922, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 23, 'OT', 'Các quan quyền cũng ngồi bàn luận nghịch cùng tôi; tôi tớ Ngài suy gẫm luật lệ Ngài.'),
(15923, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 24, 'OT', 'Các chứng cớ Ngài là niềm vui thỏa của tôi, là những người cố vấn tôi.'),
(15924, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 25, 'OT', 'Linh hồn tôi bám chặt vào bụi đất; xin cho tôi sống lại theo lời Ngài.'),
(15925, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 26, 'OT', 'Tôi đã thuật các đường lối tôi, và Ngài đáp lời tôi; xin dạy tôi các mạng lệnh của Ngài.'),
(15926, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 27, 'OT', 'Xin khiến tôi hiểu biết con đường các mạng lịnh Ngài, để tôi suy ngẫm về các điều kỳ diệu của Ngài.'),
(15927, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 28, 'OT', 'Linh hồn tôi tan chảy vì buồn bã; xin Ngài làm tôi vững bền theo lời Ngài.'),
(15928, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 29, 'OT', 'Xin hãy dời xa tôi con đường dối trá, và xin ban cho tôi ân điển của luật pháp Ngài.'),
(15929, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 30, 'OT', 'Tôi đã chọn con đường trung tín; các mạng lịnh Ngài, tôi đặt trước mặt tôi.'),
(15930, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 31, 'OT', 'Tôi bám víu vào các chứng cớ Ngài, Đức Giê-hô-va ôi, xin chớ để tôi phải hổ thẹy.'),
(15931, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 32, 'OT', 'Tôi sẽ chạy theo con đường các điều răn của Đức Giê-hô-va, vì Ngài mở rộng lòng tôi.'),
(15932, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 33, 'OT', 'Hỡi Đức Giê-hô-va, xin chỉ dạy tôi đường lối các điều luật của Ngài, thì tôi sẽ giữ trọn đến cùng.'),
(15933, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 34, 'OT', 'Xin hãy làm cho tôi hiểu, để tôi giữ luật pháp Ngài, và hết lòng tuân giữ.'),
(15934, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 35, 'OT', 'Xin hãy dẫn tôi đi trên con đường các điều răn của Ngài, vì tôi lấy làm vui mừng tại đó.'),
(15935, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 36, 'OT', 'Xin hãy làm cho lòng tôi nghiêng về những lời chứng cớ của Ngài, và chớ để tôi nghiêng về sự tham lam.'),
(15936, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 37, 'OT', 'Xin làm tôi khỏi nhìn những điều hư không, khiến tôi sống theo các đường lối Ngài.'),
(15937, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 38, 'OT', 'Xin làm ứng nghiệm lời Ngài cho kẻ tôi tớ Ngài, tức là kẻ kính sợ Ngài.'),
(15938, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 39, 'OT', 'Xin hãy gỡ bỏ khỏi tôi sự sỉ nhục mà tôi đã sợ hãi; vì mạng lịnh Ngài là tốt lành.'),
(15939, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 40, 'OT', 'Nầy, tôi khao khát các mạng lịnh Ngài; xin khiến tôi sống bởi sự công bình của Ngài.'),
(15940, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 41, 'OT', 'Hỡi Đức Giê-hô-va, nguyện sự nhân từ của Ngài đến cùng tôi, sự cứu rỗi của Ngài theo lời Ngài đã hứa.'),
(15941, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 42, 'OT', 'Tôi sẽ có lời đáp lại kẻ sỉ nhục tôi, vì tôi tin cậy nơi lời Ngài.'),
(15942, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 43, 'OT', 'Xin chớ cất khỏi miệng tôi lời chân lý đến cùng cực; vì tôi trông cậy nơi mạng lệnh Ngài.'),
(15943, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 44, 'OT', 'Tôi sẽ trung thành giữ luật lệ của Đức Giê-hô-va mãi mãi đời này sang đời khác.'),
(15944, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 45, 'OT', 'Tôi sẽ bước đi trong khoảng rộng rãi, vì tôi đã tìm cầu các mạng lịnh của Đức Giê-hô-va.'),
(15945, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 46, 'OT', 'Tôi sẽ nói về các chứng cớ của Đức Giê-hô-va trước mặt các vua, và chẳng bị hổ thẹn.'),
(15946, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 47, 'OT', 'Tôi sẽ vui vẻ trong các điều răn của Ngài, là điều răn mà tôi yêu mến.'),
(15947, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 48, 'OT', 'Tôi sẽ giơ hai tay về phía các điều răn của Đức Giê-hô-va mà tôi yêu mến, và suy gẫm các mạng lịnh của Ngài.'),
(15948, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 49, 'OT', 'Xin hãy nhớ lời đã phán cùng tôi tớ Ngài, vì chính Ngài khiến tôi đặt niềm trông cậy nơi điều đó.'),
(15949, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 50, 'OT', 'Lời phán của Ngài làm tôi sống lại; ấy là sự an ủi tôi trong cảnh khốn cùng.'),
(15950, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 51, 'OT', 'Kẻ kiêu ngạo chế nhạo tôi cách quá đáng; nhưng tôi không xây bỏ luật lệ Ngài.'),
(15951, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 52, 'OT', 'Hỡi Đức Giê-hô-va, tôi nhớ lại các mạng lịnh Ngài từ lâu đời, nên tôi được yên ủi.'),
(15952, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 53, 'OT', 'Cơn phẫn nộ đã chiếm lấy tôi vì những kẻ ác, những kẻ từ bỏ luật pháp của Đức Giê-hô-va.'),
(15953, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 54, 'OT', 'Các điều lệ của Ngài đã là bài ca của tôi, trong nhà tôi ở như khách lạ.'),
(15954, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 55, 'OT', 'Hỡi Đức Giê-hô-va, ban đêm tôi nhớ lại danh Ngài, và tôi gìn giữ luật lệ Ngài.'),
(15955, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 56, 'OT', 'Điều nầy đã thuộc về tôi, bởi tôi đã gìn giữ các mạng lịnh của Đức Giê-hô-va.'),
(15956, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 57, 'OT', 'Ngài là phần con, lạy Đức Giê-hô-va; con đã nói rằng mình sẽ giữ lời Ngài.'),
(15957, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 58, 'OT', 'Tôi đã hết lòng cầu khẩn mặt Đức Giê-hô-va; xin thương xót tôi theo lời Đức Chúa Trời.'),
(15958, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 59, 'OT', 'Tôi suy nghĩ về đường lối mình, rồi quay bước chân tôi trở về với các chứng cớ của Đức Giê-hô-va.'),
(15959, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 60, 'OT', 'Tôi vội vàng, không chậm trễ, để giữ các mạng lịnh của Ngài.'),
(15960, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 61, 'OT', 'Dây sợi của kẻ ác đã quấn quanh tôi; nhưng tôi không quên luật pháp của Đức Giê-hô-va.'),
(15961, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 62, 'OT', 'Giữa đêm, tôi sẽ chỗi dậy để cảm tạ Ngài vì các mạng lịnh công bình của Ngài.'),
(15962, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 63, 'OT', 'Tôi là người đồng hành với mọi kẻ kính sợ Ngài và với những kẻ giữ các mạng lịnh của Ngài.'),
(15963, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 64, 'OT', 'Đức Giê-hô-va ơi, đất đầy dẫy sự nhân từ của Ngài; xin dạy tôi các luật lệ của Ngài.'),
(15964, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 65, 'OT', 'Đức Giê-hô-va đã làm điều tốt cho kẻ tôi tớ Ngài, y như lời Ngài phán.'),
(15965, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 66, 'OT', 'Xin dạy tôi sự khôn ngoan và tri thức tốt lành, vì tôi tin nơi các điều răn của Đức Giê-hô-va.'),
(15966, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 67, 'OT', 'Trước khi bị thử thách, tôi lạc lối; nhưng bây giờ tôi tuân giữ lời Ngài.'),
(15967, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 68, 'OT', 'Đức Giê-hô-va là thiện và làm điều thiện; xin dạy tôi các mạng lịnh của Ngài.'),
(15968, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 69, 'OT', 'Kẻ ngạo mạn đã bịa đặt lời dối trá chống nghịch tôi; tôi sẽ hết lòng gìn giữ các mạng lịnh của Đức Giê-hô-va.'),
(15969, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 70, 'OT', 'Lòng chúng nó trở nên chai lì như mỡ; còn tôi, tôi vui thỏa trong luật pháp của Đức Giê-hô-va.'),
(15970, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 71, 'OT', 'Thật tốt cho tôi vì tôi đã bị sửa phạt, để học các mạng lịnh của Đức Giê-hô-va.'),
(15971, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 72, 'OT', 'Lời dạy của Ngài quý cho tôi hơn ngàn nén vàng và bạc.'),
(15972, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 73, 'OT', 'Chính tay Ngài đã làm tôi và định hình tôi; xin hãy ban cho tôi sự hiểu biết, để tôi học các điều răn của Ngài.'),
(15973, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 74, 'OT', 'Những người kính sợ Đức Giê-hô-va sẽ nhìn tôi và vui mừng, vì tôi trông đợi lời Đức Giê-hô-va.'),
(15974, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 75, 'OT', 'Hỡi Đức Giê-hô-va, tôi biết rằng mạng lịnh Ngài là công bình, và ấy là bởi sự thành tín mà Ngài làm cho tôi bị khổ.'),
(15975, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 76, 'OT', 'Nguyện sự nhân từ của Đức Giê-hô-va an ủi tôi, y như lời Ngài hứa cùng kẻ tôi tớ Ngài.'),
(15976, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 77, 'OT', 'Nguyện các sự thương xót của Ngài đến cùng tôi, để tôi được sống; vì luật pháp Ngài là điều tôi yêu thích.'),
(15977, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 78, 'OT', 'Nguyện những kẻ kiêu ngạo phải hổ thẹy, vì chúng dùng sự dối trá mà hãm hại tôi; còn tôi, tôi sẽ suy gẫm các mạng lịnh của Đức Giê-hô-va.'),
(15978, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 79, 'OT', 'Nguyện những kẻ kính sợ Ngài trở lại cùng tôi, thì họ sẽ biết những chứng cớ của Ngài.'),
(15979, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 80, 'OT', 'Nguyện lòng tôi được trọn vẹn trong các luật lệ Ngài, hầu cho tôi không bị hổ thẹn.'),
(15980, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 81, 'OT', 'Linh hồn tôi hao mòn vì mong đợi sự cứu rỗi của Đức Giê-hô-va; tôi trông đợi lời Ngài.'),
(15981, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 82, 'OT', 'Mắt tôi hao mòn vì lời hứa của Ngài; tôi nói: "Bao giờ Ngài sẽ an ủi tôi?"'),
(15982, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 83, 'OT', 'Vì tôi trở nên như bầu rượu da giữa làn khói; nhưng tôi không quên các mạng lịnh Ngài.'),
(15983, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 84, 'OT', 'Kẻ tôi tớ Chúa còn sống được bao nhiêu ngày? Chừng nào thì Ngài sẽ thực hiện xét xử những kẻ bắt bớ tôi?'),
(15984, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 85, 'OT', 'Kẻ kiêu ngạo đã đào hầm hại tôi, việc không theo luật pháp của Đức Giê-hô-va.'),
(15985, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 86, 'OT', 'Mọi điều răn của Ngài đều chân thật; chúng dùng sự dối trá để bắt bớ tôi; xin hãy giúp đỡ tôi.'),
(15986, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 87, 'OT', 'Hầu như chúng đã tiêu diệt tôi khỏi mặt đất; nhưng tôi không từ bỏ các mạng lịnh của Ngài.'),
(15987, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 88, 'OT', 'Nhờ sự nhân từ của Ngài, xin cho tôi được sống; và tôi sẽ giữ lời chứng của miệng Ngài.'),
(15988, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 89, 'OT', 'Đức Giê-hô-va, lời Ngài đứng vững đời đời trên trời.'),
(15989, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 90, 'OT', 'Lòng trung thành của Đức Giê-hô-va còn đến đời này sang đời khác; Ngài đã lập trái đất, và nó đứng vững.'),
(15990, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 91, 'OT', 'Theo các mạng phán xét của Đức Giê-hô-va, ngày nay mọi vật vẫn tồn tại; vì muôn vật đều là tôi tớ Ngài.'),
(15991, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 92, 'OT', 'Nếu không có luật pháp Ngài làm niềm vui thích của tôi, thì tôi đã chết trong cảnh khốn khổ.'),
(15992, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 93, 'OT', 'Tôi sẽ không bao giờ quên các mạng lịnh của Ngài, vì nhờ chúng mà Ngài đã ban sự sống cho tôi.'),
(15993, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 94, 'OT', 'Lạy Đức Giê-hô-va, tôi thuộc về Ngài; xin cứu tôi, vì tôi đã tìm kiếm các mạng lịnh của Ngài.'),
(15994, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 95, 'OT', 'Kẻ ác rình rập để tiêu diệt tôi; còn tôi thì suy gẫm các chứng cớ của Ngài.'),
(15995, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 96, 'OT', 'Tôi đã thấy giới hạn của mọi sự trọn vẹn; nhưng điều răn của Ngài thì rộng lớn vô cùng.'),
(15996, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 97, 'OT', 'Tôi yêu luật pháp Ngài biết bao! Trọn ngày tôi suy gẫm luật pháp ấy.'),
(15997, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 98, 'OT', 'Các điều răn của Đức Giê-hô-va làm cho tôi khôn ngoan hơn các kẻ thù tôi, vì các điều răn ấy thuộc về tôi đời đời.'),
(15998, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 99, 'OT', 'Tôi thông sáng hơn mọi thầy dạy tôi, vì chứng cớ Ngài là đề tài suy gẫm của tôi.'),
(15999, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 100, 'OT', 'Tôi hiểu biết hơn những người già, vì tôi tuân giữ các mạng lịnh của Ngài.'),
(16000, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 101, 'OT', 'Tôi đã ngăn chân tôi khỏi mọi đường xấu xa, để giữ lời Ngài.'),
(16001, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 102, 'OT', 'Tôi không xây bỏ các mạng lịnh của Ngài; vì chính Ngài đã dạy tôi.'),
(16002, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 103, 'OT', 'Lời phán của Ngài ngon ngọt cho vòm họng tôi biết bao! Ngọt hơn mật ong trong miệng tôi!'),
(16003, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 104, 'OT', 'Tôi nhờ các điều răn của Ngài mà hiểu biết; vì vậy tôi ghét mọi lối đi gian dối.'),
(16004, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 105, 'OT', 'Lời Ngài là ngọn đèn soi bước chân tôi, và ánh sáng trên nẻo đường tôi.'),
(16005, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 106, 'OT', 'Tôi đã thề hứa và xác nhận sẽ giữ các mạng lịnh công bình của Đức Giê-hô-va.'),
(16006, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 107, 'OT', 'Đức Giê-hô-va ôi, tôi bị áp khổ đến cực độ; xin cho tôi được sống theo lời Ngài.'),
(16007, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 108, 'OT', 'Lạy Đức Giê-hô-va, xin Ngài vui lòng chấp nhận các lễ vật do miệng tôi dâng; xin dạy tôi các mạng lịnh của Ngài.'),
(16008, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 109, 'OT', 'Mạng sống tôi luôn ở trong tay tôi, nhưng tôi không quên luật pháp Ngài.'),
(16009, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 110, 'OT', 'Kẻ ác đã đặt bẫy cho tôi, nhưng tôi không đi chệch khỏi các mạng lịnh của Ngài.'),
(16010, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 111, 'OT', 'Tôi đã nhận chứng cớ Ngài làm cơ nghiệp cho đến đời đời, vì chúng là niềm vui trong lòng tôi.'),
(16011, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 112, 'OT', 'Tôi đã nghiêng lòng mình để làm các mạng lịnh của Đức Giê-hô-va trọn đời, đến cuối cùng.'),
(16012, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 113, 'OT', 'Tôi ghét những kẻ hai lòng, nhưng yêu luật pháp của Ngài.'),
(16013, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 114, 'OT', 'Đức Giê-hô-va là nơi náu ẩn và cái khiên của tôi; tôi nhờ cậy nơi lời Ngài.'),
(16014, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 115, 'OT', 'Hỡi những kẻ gian ác, hãy lìa khỏi ta, để ta giữ các mạng lệnh của Đức Chúa Trời ta.'),
(16015, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 116, 'OT', 'Hãy nâng đỡ tôi theo lời Ngài phán, thì tôi sẽ sống; chớ để tôi phải nhục về sự trông cậy tôi.'),
(16016, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 117, 'OT', 'Xin hãy nâng đỡ tôi, thì tôi sẽ được cứu rỗi, và tôi sẽ chăm chú vào các luật lệ Ngài luôn luôn.'),
(16017, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 118, 'OT', 'Người đã từ chối mọi kẻ lầm lạc khỏi các mạng lịnh của Ngài, vì sự dối trá là điều chúng nó đã bày ra.'),
(16018, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 119, 'OT', 'Người cất bỏ mọi kẻ ác trong đất như bã; vì vậy tôi yêu mến các lời chứng của Ngài.'),
(16019, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 120, 'OT', 'Thịt tôi nổi trầy vì kính sợ Ngài, và tôi sợ các phán quyết của Ngài.'),
(16020, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 121, 'OT', 'Tôi đã làm điều công bình và ngay thẳng; chớ để tôi bị kẻ hà hiếp tôi bắt nạt.'),
(16021, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 122, 'OT', 'Xin hãy bảo vệ tôi tớ Ngài để được điều tốt; chớ để kẻ ngạo mạn ức hiếp tôi.'),
(16022, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 123, 'OT', 'Mắt tôi hao mòn vì trông đợi sự cứu rỗi của Đức Giê-hô-va, và vì lời công bình của Ngài.'),
(16023, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 124, 'OT', 'Xin hãy đối xử với kẻ tôi tớ Ngài theo sự nhân từ của Ngài, và dạy tôi các mạng lịnh Ngài.'),
(16024, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 125, 'OT', 'Tôi là kẻ tôi tớ Ngài; xin cho tôi sự hiểu biết, để tôi biết các chứng cớ của Ngài.'),
(16025, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 126, 'OT', 'Đã đến thì giờ phải làm cho Đức Giê-hô-va, vì người ta đã phế bỏ luật pháp Ngài.'),
(16026, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 127, 'OT', 'Vì vậy, tôi yêu các điều răn của Ngài hơn vàng, hơn cả vàng ròng.'),
(16027, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 128, 'OT', 'Vì vậy, tôi coi mọi điều răn của Ngài về mọi vật đều ngay thẳng; tôi ghét mọi con đường giả dối.'),
(16028, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 129, 'OT', 'Chứng cớ của Ngài thật lạ lùng; vì vậy linh hồn tôi giữ giữ chúng.'),
(16029, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 130, 'OT', 'Sự mở ra lời Ngài làm sáng lên, ban sự hiểu biết cho người ngây thơ.'),
(16030, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 131, 'OT', 'Tôi há miệng ra và hít thở, vì tôi khao khát các mạng lịnh của Ngài.'),
(16031, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 132, 'OT', 'Xin hãy đoái lại cùng tôi và thương xót tôi, y như luật lệ của những kẻ yêu mến danh Ngài.'),
(16032, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 133, 'OT', 'Xin hãy lập định các bước chân tôi trong lời Ngài, và chớ để điều ác nào thống trị tôi.'),
(16033, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 134, 'OT', 'Xin chuộc tôi khỏi sự áp bức của loài người, để tôi giữ các mạng lịnh của Ngài.'),
(16034, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 135, 'OT', 'Xin hãy làm sáng mặt Ngài trên kẻ tôi tớ Ngài, và dạy tôi các mạng lịnh của Ngài.'),
(16035, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 136, 'OT', 'Những dòng nước từ mắt tôi chảy xuống, vì người ta không giữ luật lệ Ngài.'),
(16036, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 137, 'OT', 'Đức Giê-hô-va là công bình, và các phán quyết của Ngài là ngay thẳng.'),
(16037, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 138, 'OT', 'Ngài đã truyền phán các minh chứng của Ngài là sự công chính, và rất thành tín.'),
(16038, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 139, 'OT', 'Sự sốt sắng của tôi làm tôi tiêu hao, vì những kẻ thù tôi đã quên lời Ngài.'),
(16039, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 140, 'OT', 'Lời Ngài đã được thử nghiệm cách tuyệt đối, và kẻ tôi tớ Ngài hết lòng yêu mến lời ấy.'),
(16040, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 141, 'OT', 'Tôi bé nhỏ và bị khinh thường, nhưng tôi không quên các điều răn của Đức Giê-hô-va.'),
(16041, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 142, 'OT', 'Công bình của Đức Giê-hô-va là công bình đời đời, và luật pháp Ngài là sự thật.'),
(16042, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 143, 'OT', 'Sự khốn khó và gian truân áp hãm tôi; điều răn của Đức Giê-hô-va là niềm vui tôi.'),
(16043, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 144, 'OT', 'Phán quyết của Ngài là công bình đời đời; xin khiến tôi thông hiểu, để tôi được sống.'),
(16044, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 145, 'OT', 'Hỡi Đức Giê-hô-va, tôi kêu cầu Ngài hết lòng; xin đáp lại tôi; tôi sẽ gìn giữ các mạng lịnh Ngài.'),
(16045, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 146, 'OT', 'Tôi đã kêu cầu Đức Giê-hô-va, xin cứu tôi; tôi sẽ giữ các chứng cớ của Ngài.'),
(16046, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 147, 'OT', 'Tôi thức dậy trước khi rạng đông và than khẩn; tôi trông đợi nơi lời Ngài.'),
(16047, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 148, 'OT', 'Mắt tôi tỉnh thức trước giờ canh khuya, để suy gẫm lời Đức Giê-hô-va.'),
(16048, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 149, 'OT', 'Lạy Đức Giê-hô-va, xin hãy nghe tiếng tôi theo sự nhân từ của Ngài; theo mạng lịnh Ngài, khiến tôi được sống.'),
(16049, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 150, 'OT', 'Kẻ theo đuổi điều gian ác đến gần; chúng cách xa luật pháp Ngài.'),
(16050, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 151, 'OT', 'Đức Giê-hô-va ở gần; mọi điều răn của Ngài là chân thật.'),
(16051, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 152, 'OT', 'Tôi đã biết từ trước các chứng cớ của Ngài, vì Ngài đã lập chúng đến đời đời.'),
(16052, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 153, 'OT', 'Xin hãy nhìn xem sự khốn khổ của tôi, và giải cứu tôi; vì tôi không quên luật pháp của Đức Giê-hô-va.'),
(16053, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 154, 'OT', 'Hãy binh vực duyên cớ tôi và chuộc tôi; theo lời phán của Ngài, xin cho tôi được sống.'),
(16054, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 155, 'OT', 'Sự cứu rỗi ở xa người ác, vì chúng nó không tìm cầu các mạng lịnh của Ngài.'),
(16055, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 156, 'OT', 'Lòng thương xót của Đức Giê-hô-va rất lớn; theo các phán quyết của Ngài, xin cho tôi được sống.'),
(16056, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 157, 'OT', 'Kẻ bắt bớ tôi và kẻ thù tôi rất đông; nhưng tôi không xây bỏ chứng cớ Ngài.'),
(16057, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 158, 'OT', 'Tôi thấy những kẻ phản bội, bèn ghê tởm; vì chúng không tuân giữ lời Ngài.'),
(16058, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 159, 'OT', 'Xin hãy xem, tôi yêu các mạng lịnh của Ngài dường bao! Hỡi Đức Giê-hô-va, xin lấy sự nhân từ của Ngài khiến tôi được sống.'),
(16059, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 160, 'OT', 'Lời đầu của Ngài là chân thật; mọi phán quyết công bình của Đức Giê-hô-va tồn tại đời đời.'),
(16060, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 161, 'OT', 'Các quan quyền bắt bớ tôi vô cớ, nhưng lòng tôi kính sợ lời Ngài.'),
(16061, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 162, 'OT', 'Tôi vui mừng về lời Ngài, như kẻ tìm được của cải lớn.'),
(16062, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 163, 'OT', 'Tôi ghét và khinh bỉ sự dối trá; luật pháp Ngài, tôi yêu mến.'),
(16063, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 164, 'OT', 'Tôi ngợi khen Đức Giê-hô-va bảy lần mỗi ngày, vì các mạng lịnh công bình của Ngài.'),
(16064, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 165, 'OT', 'Người nào yêu luật pháp Ngài được bình an lớn, và chẳng có điều gì khiến họ vấp ngã.'),
(16065, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 166, 'OT', 'Hỡi Đức Giê-hô-va, tôi đã trông đợi sự cứu rỗi của Ngài, và làm theo các mạng lịnh của Ngài.'),
(16066, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 167, 'OT', 'Linh hồn tôi giữ các chứng cớ của Ngài, và tôi hết lòng yêu mến chúng.'),
(16067, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 168, 'OT', 'Tôi đã gìn giữ các mạng lịnh và các lời chứng của Đức Giê-hô-va, vì mọi nẻo đường tôi đều ở trước mặt Ngài.'),
(16068, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 169, 'OT', 'Hỡi Đức Giê-hô-va, nguyện tiếng than khóc của tôi thấu đến trước mặt Ngài; xin theo lời Ngài mà làm cho tôi thông sáng.'),
(16069, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 170, 'OT', 'Nguyện sự nài xin của tôi đến trước mặt Đức Giê-hô-va, theo lời Ngài phán, xin giải cứu tôi.'),
(16070, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 171, 'OT', 'Môi miệng tôi sẽ thốt ra lời ngợi khen, vì Đức Giê-hô-va dạy tôi các điều lệ của Ngài.'),
(16071, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 172, 'OT', 'Nguyện lưỡi tôi xướng lên về lời của Ngài; vì mọi điều răn của Ngài đều là công bình.'),
(16072, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 173, 'OT', 'Nguyện tay Đức Giê-hô-va giúp đỡ tôi; vì tôi đã chọn các mạng lịnh của Ngài.'),
(16073, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 174, 'OT', 'Hỡi Đức Giê-hô-va, tôi khao khát sự cứu rỗi của Ngài; luật pháp Ngài là niềm vui thích của tôi.'),
(16074, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 175, 'OT', 'Nguyện cho linh hồn tôi được sống, để ngợi khen Ngài; và mạng lịnh Ngài sẽ giúp đỡ tôi.'),
(16075, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 119, 176, 'OT', 'Tôi lạc như chiên đi lạc; xin tìm kẻ tôi tớ Ngài, vì tôi không quên các điều răn của Ngài.'),
(16076, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 120, 1, 'OT', 'Bài ca những bậc thang: Trong cơn gian truân tôi kêu cầu Đức Giê-hô-va; Đức Giê-hô-va bèn đáp lời tôi.'),
(16077, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 120, 2, 'OT', 'Hỡi Đức Giê-hô-va, xin cứu lấy linh hồn tôi khỏi môi miệng nói dối, khỏi lưỡi gian trá.'),
(16078, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 120, 3, 'OT', 'Lưỡi phỉnh gạt, người ta sẽ ban cho ngươi điều gì, và thêm cho ngươi điều gì nữa?'),
(16079, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 120, 4, 'OT', 'Mũi tên sắc bén của dũng sĩ, cùng những thanh than hồng hộc của cây bách xanh.'),
(16080, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 120, 5, 'OT', 'Khốn thay cho tôi, vì tôi phải ngụ ở Mê-siếc, tôi sống giữa các trại của Kê-đa.'),
(16081, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 120, 6, 'OT', 'Lâu lắm rồi linh hồn tôi sống cùng kẻ ghét sự hòa bình.'),
(16082, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 120, 7, 'OT', 'Tôi muốn sự bình an, nhưng khi tôi nói ra, chúng nó lại muốn chiến tranh.'),
(16083, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 121, 1, 'OT', 'Tôi ngước mắt lên các ngọn núi; sự giúp đỡ tôi từ nơi nào đến?'),
(16084, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 121, 2, 'OT', 'Sự tiếp trợ tôi đến từ Đức Giê-hô-va, là Đấng làm nên trời và đất.'),
(16085, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 121, 3, 'OT', 'Chân ngươi, Ngài sẽ không để lung lay; Đấng giữ gìn ngươi sẽ không hề buồn ngủ.'),
(16086, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 121, 4, 'OT', 'Nầy, Đấng gìn giữ Y-sơ-ra-ên chẳng hề mệt mỏi, cũng chẳng hề buồn ngủ.'),
(16087, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 121, 5, 'OT', 'Đức Giê-hô-va là Đấng giữ gìn ngươi; Đức Giê-hô-va là bóng râm ngươi bên tay phải ngươi.'),
(16088, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 121, 6, 'OT', 'Ban ngày mặt trời không làm hại ngươi, ban đêm mặt trăng cũng không tổn thương ngươi.'),
(16089, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 121, 7, 'OT', 'Đức Giê-hô-va sẽ gìn giữ ngươi khỏi mọi điều ác; Ngài sẽ gìn giữ linh hồn ngươi.'),
(16090, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 121, 8, 'OT', 'Đức Giê-hô-va sẽ gìn giữ sự ra đi và sự vào của ngươi, từ bây giờ và đến mãi mãi.'),
(16091, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 122, 1, 'OT', 'Một bài ca của các bậc lên, của Đa-vít. Tôi vui mừng khi người ta nói với tôi: Chúng ta hãy đi đến nhà Đức Giê-hô-va.'),
(16092, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 122, 2, 'OT', 'Chúng tôi đứng nơi các cửa thành của ngươi, hỡi Giê-ru-sa-lem.'),
(16093, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 122, 3, 'OT', 'Giê-ru-sa-lem là thành đã được xây, như một thành kết nối chặt chẽ với nhau.'),
(16094, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 122, 4, 'OT', 'Nơi ấy các chi phái lên, các chi phái của Đức Giê-hô-va, làm chứng cho Y-sơ-ra-ên, để cảm tạ danh Đức Giê-hô-va.'),
(16095, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 122, 5, 'OT', 'Vì tại đó có các ngôi tòa xét xử, các ngôi tòa của nhà Đa-vít.'),
(16096, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 122, 6, 'OT', 'Hãy cầu an bình cho Giê-ru-sa-lem; ai yêu mến ngươi sẽ được thạnh vượng.'),
(16097, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 122, 7, 'OT', 'Nguyện sự bình an ngự trong hàng quân đội ngươi, sự thịnh vượng trong các cung điện ngươi!'),
(16098, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 122, 8, 'OT', 'Vì cớ anh em ta và người thân cận ta, ta xin nói: Nguyện sự bình an ở nơi ngươi!'),
(16099, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 122, 9, 'OT', 'Vì cớ nhà của Đức Giê-hô-va Đức Chúa Trời chúng ta, tôi sẽ cầu xin điều thiện cho ngươi.'),
(16100, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 123, 1, 'OT', 'Thơ của những bước lên: Hỡi Đấng ngự trên các từng trời, tôi ngước mắt lên cùng Ngài.'),
(16101, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 123, 2, 'OT', 'Kìa, như mắt của các đầy tớ nhìn xem tay các chủ mình, như mắt của một người nữ đòi nhìn xem tay bà chủ mình, thì mắt chúng tôi cũng chăm chăm ngó về Giê-hô-va Đức Chúa Trời chúng tôi, cho đến khi nào Ngài thương xót chúng tôi.'),
(16102, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 123, 3, 'OT', 'Đức Giê-hô-va ôi, xin thương xót chúng tôi, xin thương xót chúng tôi; vì chúng tôi đã chán ngán sự khinh dể.'),
(16103, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 123, 4, 'OT', 'Linh hồn chúng tôi đã chán ngán lắm rồi, vì sự nhạo báng của kẻ tự phụ, và sự khinh miệt của kẻ kiêu căng.'),
(16104, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 124, 1, 'OT', 'Y-sơ-ra-ên đáng nói: Nếu Đức Giê-hô-va chẳng binh vực chúng ta,'),
(16105, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 124, 2, 'OT', 'Nếu Đức Giê-hô-va không ở về phe chúng ta, khi loài người dấy lên nghịch cùng chúng ta,'),
(16106, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 124, 3, 'OT', 'Nếu Đức Giê-hô-va không binh vực chúng ta, thì chắc nó đã nuốt sống chúng ta rồi;'),
(16107, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 124, 4, 'OT', 'Nước đã tràn ngập chúng ta, dòng lũ tràn qua linh hồn chúng ta,'),
(16108, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 124, 5, 'OT', 'Nếu vậy, những nước kiêu ngạo đã tràn qua linh hồn chúng ta.'),
(16109, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 124, 6, 'OT', 'Đáng ngợi khen Đức Giê-hô-va, vì Ngài không phó chúng ta làm mồi cho răng chúng nó!'),
(16110, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 124, 7, 'OT', 'Linh hồn chúng ta như chim sổng khỏi cái bẫy; cái bẫy đã bể, và chúng ta được thoát khỏi.'),
(16111, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 124, 8, 'OT', 'Sự giúp đỡ chúng ta ở trong danh Đức Giê-hô-va, Đấng đã làm nên trời và đất.'),
(16112, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 125, 1, 'OT', 'Những người tin cậy nơi Đức Giê-hô-va giống như núi Si-ôn, không hề rúng động, luôn vững bền đời đời.'),
(16113, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 125, 2, 'OT', 'Các núi vây quanh Giê-ru-sa-lem thể nào, Đức Giê-hô-va vây quanh dân sự Ngài thể ấy, từ nay cho đến mãi mãi.'),
(16114, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 125, 3, 'OT', 'Vì cây gậy kẻ ác sẽ không nằm yên trên phần sản nghiệp của người công chính, để người công chính khỏi đưa tay mình ra làm điều gian ác.'),
(16115, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 125, 4, 'OT', 'Hỡi Đức Giê-hô-va, xin hãy làm điều lành cho những người lành và cho những kẻ có lòng ngay thẳng.'),
(16116, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 125, 5, 'OT', 'Còn Đức Giê-hô-va sẽ dẫn những kẻ đi theo đường cong quẹo ra chung với kẻ làm ác. Bình an trên Y-sơ-ra-ên!'),
(16117, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 126, 1, 'OT', 'Một bài ca của các bậc lên đền. Khi Đức Giê-hô-va đem những người bị bắt về từ Si-ôn, thì chúng tôi khác nào kẻ nằm mộng.'),
(16118, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 126, 2, 'OT', 'Bấy giờ miệng chúng tôi sẽ đầy nụ cười, và lưỡi chúng tôi sẽ hát vang bài ca mừng rỡ. Bấy giờ các dân sẽ nói: Đức Giê-hô-va đã làm những việc lớn cho họ.'),
(16119, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 126, 3, 'OT', 'Đức Giê-hô-va đã làm lớn việc cho chúng tôi, và chúng tôi vui vẻ.'),
(16120, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 126, 4, 'OT', 'Hỡi Đức Giê-hô-va, xin trở lại dẫn phu tù chúng tôi về, như các suối ở miền nam chảy nước.'),
(16121, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 126, 5, 'OT', 'Kẻ gieo bằng nước mắt sẽ gặt bằng tiếng reo mừng.'),
(16122, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 126, 6, 'OT', 'Người đi vừa khóc, mang giống ra gieo; kẻ về sẽ về trong hân hoan, mang những bó lúa mình.'),
(16123, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 127, 1, 'OT', 'Nếu Đức Giê-hô-va không xây nhà, thì uổng công những người thợ xây dựng nó; nếu Đức Giê-hô-va không canh giữ thành phố, thì uổng công kẻ thức canh giữ.'),
(16124, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 127, 2, 'OT', 'Vô ích thay, các ngươi thức dậy sớm, ngồi khuya, ăn bánh lao khổ; chính Ngài cũng ban giấc ngủ cho kẻ được Ngài yêu thương.'),
(16125, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 127, 3, 'OT', 'Kìa, con cái là cơ nghiệp của Đức Giê-hô-va; bông trái của lòng mẹ là phần thưởng.'),
(16126, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 127, 4, 'OT', 'Như những mũi tên trong tay dũng sĩ, cũng vậy là các con trai của tuổi trẻ.'),
(16127, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 127, 5, 'OT', 'Phúc thay cho người nào làm đầy túi mình bằng những người ấy! Người ấy sẽ không hổ thẹn, khi nói chuyện với kẻ thù nghịch mình nơi cửa thành.'),
(16128, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 128, 1, 'OT', 'Phước cho mọi người kính sợ Đức Giê-hô-va, đi trong các đường lối của Ngài!'),
(16129, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 128, 2, 'OT', 'Công việc của đôi tay ngươi, ấy là điều ngươi sẽ ăn; thật phước cho ngươi, và sẽ tốt lành cho ngươi.'),
(16130, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 128, 3, 'OT', 'Vợ ngươi ở trong nhà ngươi sẽ như cây nho đầy trái; con cái ngươi quanh bàn ngươi như những cây ô-liu non.'),
(16131, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 128, 4, 'OT', 'Kìa, chính như vậy sẽ được phước người nào kính sợ Đức Giê-hô-va.'),
(16132, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 128, 5, 'OT', 'Nguyện Đức Giê-hô-va từ Si-ôn ban phước cho ngươi, và nguyện ngươi được thấy sự thịnh vượng của Giê-ru-sa-lem trọn những ngày trong đời sống ngươi.'),
(16133, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 128, 6, 'OT', 'Nguyện ngươi được thấy con cái của con cháu ngươi! Nguyện sự bình an trên Y-sơ-ra-ên!'),
(16134, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 129, 1, 'OT', 'Một bài ca lên các bậc. Từ khi tôi còn thơ ấu, chúng nó thường hà hiếp tôi, Y-sơ-ra-ên đáng nói,'),
(16135, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 129, 2, 'OT', 'Từ khi tôi còn thơ ấu, người ta đã hà hiếp tôi rất nhiều, nhưng không thắng hơn tôi được.'),
(16136, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 129, 3, 'OT', 'Các kẻ cày đã cày trên lưng tôi; chúng kéo dài những đường cày của mình.'),
(16137, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 129, 4, 'OT', 'Đức Giê-hô-va là công chính; Ngài đã chặt đứt dây giây của kẻ ác.'),
(16138, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 129, 5, 'OT', 'Nguyện mọi kẻ ghét Si-ôn đều bị hổ thẹn và lui lại phía sau.'),
(16139, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 129, 6, 'OT', 'Nguyện chúng như cỏ trên mái nhà, Mới trổ mình đã bị khô héo.'),
(16140, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 129, 7, 'OT', 'Kẻ gặt không đầy tay mình, và kẻ bó lúa không đầy ôm mình.'),
(16141, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 129, 8, 'OT', 'Và những kẻ đi ngang không nói: "Nguyện phước của Đức Giê-hô-va ở cùng các ngươi! Chúng tôi chúc phước cho các ngươi nhân danh Đức Giê-hô-va."'),
(16142, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 130, 1, 'OT', 'Từ những vực sâu, tôi kêu lên cùng Đức Giê-hô-va.'),
(16143, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 130, 2, 'OT', 'Lạy Đức Giê-hô-va, xin nghe tiếng tôi; nguyện tai Ngài chăm chú lắng nghe tiếng kêu nài của tôi.'),
(16144, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 130, 3, 'OT', 'Hỡi Đức Giê-hô-va, nếu Ngài gìn giữ các sự gian ác, thì ai sẽ đứng vững được?'),
(16145, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 130, 4, 'OT', 'Nhưng nơi Ngài có sự tha thứ, để được kính sợ.'),
(16146, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 130, 5, 'OT', 'Tôi trông đợi Đức Giê-hô-va; chính linh hồn tôi trông đợi Ngài; tôi mong đợi lời Ngài.'),
(16147, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 130, 6, 'OT', 'Linh hồn tôi trông đợi Đức Giê-hô-va Hơn những người canh giữ chờ rạng đông, thật, hơn những người canh giữ chờ rạng đông.'),
(16148, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 130, 7, 'OT', 'Hỡi Y-sơ-ra-ên, hãy trông đợi nơi Đức Giê-hô-va; vì nơi Đức Giê-hô-va có sự thương xót, và nơi Ngài có sự cứu chuộc dồi dào.'),
(16149, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 130, 8, 'OT', 'Chính Ngài sẽ chuộc Y-sơ-ra-ên khỏi mọi tội ác của người.'),
(16150, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 131, 1, 'OT', 'Bài ca Hành khúc. Của Đa-vít. Đức Giê-hô-va, lòng tôi không tự kiêu, mắt tôi không ngạo mạn, tôi cũng không bước đi trong những điều lớn lao, hay những điều kỳ lạ quá mức tôi.'),
(16151, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 131, 2, 'OT', 'Tôi đã khiến linh hồn tôi được yên lặng và bình tịnh, như con trẻ vừa cai sữa bên mẹ nó; linh hồn tôi cũng như con trẻ vừa cai sữa vậy.'),
(16152, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 131, 3, 'OT', 'Hỡi Y-sơ-ra-ên, hãy trông cậy nơi Đức Giê-hô-va, từ bây giờ cho đến mãi mãi.'),
(16153, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 132, 1, 'OT', 'Một bài ca bước lên: Lạy Đức Giê-hô-va, xin nhớ đến Đa-vít và mọi nỗi khốn khổ của người.'),
(16154, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 132, 2, 'OT', 'Thật người đã thề cùng Đức Giê-hô-va, khấn hứa cùng Đấng Toàn năng của Gia-cốp.'),
(16155, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 132, 3, 'OT', 'Tôi sẽ không vào lều nhà tôi, không lên giường nằm nghỉ,'),
(16156, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 132, 4, 'OT', 'Tôi sẽ không để mắt mình ngủ, cũng không để mí mắt mình chợp mắt,'),
(16157, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 132, 5, 'OT', 'Cho đến khi tôi tìm được một chỗ cho Đức Giê-hô-va, các nơi ở cho Đấng Toàn năng của Gia-cốp!'),
(16158, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 132, 6, 'OT', 'Này, chúng tôi đã nghe nói về nó tại Ê-phrát, đã tìm thấy nó trong các đồng cỏ Gia-a.'),
(16159, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 132, 7, 'OT', 'Chúng ta sẽ vào nơi ở của Ngài, cúi lạy trước bệ chân Ngài.'),
(16160, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 132, 8, 'OT', 'Hỡi Đức Giê-hô-va, hãy chỗi dậy, đến nơi an nghỉ của Ngài, Ngài và hòm chứa sự quyền năng của Ngài!'),
(16161, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 132, 9, 'OT', 'Các thầy tế lễ của Ngài sẽ mặc lấy sự công bình, và các người thánh của Ngài sẽ hò reo vui mừng.'),
(16162, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 132, 10, 'OT', 'Vì cớ Đa-vít, là tôi tớ Ngài, xin chớ từ chối mặt đấng chịu xức dầu của Ngài.'),
(16163, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 132, 11, 'OT', 'Đức Giê-hô-va đã thề hứa thật với Đa-vít, lời ấy không hề rút lại: Ta sẽ đặt con của ngươi trên ngôi ngươi.'),
(16164, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 132, 12, 'OT', 'Nếu con cái ngươi giữ giao ước ta và những chứng cớ ta sẽ dạy cho chúng nó, thì con cái chúng nó đến đời đời cũng sẽ ngồi trên ngôi ngươi.'),
(16165, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 132, 13, 'OT', 'Vì Đức Giê-hô-va đã chọn Si-ôn; Ngài ao ước Si-ôn làm nơi ở cho Ngài;'),
(16166, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 132, 14, 'OT', 'Đây là nơi an nghỉ của ta đời đời; ta sẽ ở đây, vì ta đã ưa chuộng nơi ấy.'),
(16167, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 132, 15, 'OT', 'Ta sẽ ban phước cho lương thực của Si-ôn, làm cho nó dư dật; Ta sẽ làm cho những kẻ nghèo của nó được ăn bánh no nê.'),
(16168, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 132, 16, 'OT', 'Ta sẽ mặc sự cứu rỗi cho các thầy tế lễ của Ngài, và các người thánh của Ngài sẽ reo mừng.'),
(16169, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 132, 17, 'OT', 'Tại đó ta sẽ khiến sừng Đa-vít đâm chồi; ta đã sắm sửa ngọn đèn cho Đấng chịu xức dầu của ta.'),
(16170, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 132, 18, 'OT', 'Ta sẽ mặc cho kẻ thù nghịch người áo hổ thẹn; còn trên đầu người, mão triều của người sẽ nở rộ.'),
(16171, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 133, 1, 'OT', 'Kìa, thật tốt lành và thật vui sướng thay khi anh em cùng sống chung một nơi!'),
(16172, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 133, 2, 'OT', 'Khác nào dầu quý chảy trên đầu, chảy xuống râu, tức râu của A-rôn, chảy đến mép áo người.'),
(16173, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 133, 3, 'OT', 'Khác nào sương móc từ Hẹt-môn tuôn xuống các núi Si-ôn; vì tại đó Đức Giê-hô-va đã truyền ban phước, là sự sống đời đời.'),
(16174, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 134, 1, 'OT', 'Hỡi các tôi tớ Đức Giê-hô-va, là những kẻ đứng trong nhà Đức Giê-hô-va ban đêm, hãy ngợi khen Đức Giê-hô-va!'),
(16175, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 134, 2, 'OT', 'Hãy giơ tay các ngươi về nơi thánh và chúc phước cho Đức Giê-hô-va.'),
(16176, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 134, 3, 'OT', 'Nguyện Đức Giê-hô-va từ Si-ôn ban phước cho ngươi, là Đấng làm nên trời và đất.'),
(16177, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 135, 1, 'OT', 'Ha-lê-lu-gia! Hãy ngợi khen danh Đức Giê-hô-va; hỡi các tôi tớ Đức Giê-hô-va, hãy ngợi khen,'),
(16178, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 135, 2, 'OT', 'Là những kẻ đứng trong đền thờ Đức Giê-hô-va, tại các hành lang của nhà Đức Chúa Trời chúng ta.'),
(16179, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 135, 3, 'OT', 'Hãy ngợi khen Đức Giê-hô-va, vì Đức Giê-hô-va là thiện; hãy hát xướng danh Ngài, vì thật là ngọt ngào.'),
(16180, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 135, 4, 'OT', 'Vì Gia-cốp được Đức Giê-hô-va chọn làm của riêng mình, Y-sơ-ra-ên được chọn làm cơ nghiệp riêng.'),
(16181, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 135, 5, 'OT', 'Vì tôi biết rằng Đức Giê-hô-va là lớn, và Chúa chúng tôi vượt trên hết thảy các thần.'),
(16182, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 135, 6, 'OT', 'Tất cả những điều Đức Giê-hô-va ưa muốn, Ngài đã làm, trên các từng trời và dưới đất, trong biển cả và mọi vực sâu.'),
(16183, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 135, 7, 'OT', 'Đức Giê-hô-va khiến mây lên từ nơi cùng cực của đất, làm chớp cho mưa xuống, khiến gió ra từ các kho tàng của Ngài.'),
(16184, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 135, 8, 'OT', 'Đánh giết các con đầu lòng của Ai Cập, từ loài người cho đến loài vật.'),
(16185, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 135, 9, 'OT', 'Đức Giê-hô-va sai các dấu kỳ và phép lạ vào giữa đất Ai Cập, trên Pha-ra-ôn và trên tất cả các tôi tớ người.'),
(16186, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 135, 10, 'OT', 'Đã đánh bại nhiều dân tộc lớn, và giết các vua quyền năng,'),
(16187, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 135, 11, 'OT', 'đức vua dân A-mô-rít Si-hôn, và Oùc, vua Ba-san, và mọi nước Ca-na-an'),
(16188, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 135, 12, 'OT', 'Ngài ban đất nước của chúng làm sản nghiệp, một sản nghiệp cho Y-sơ-ra-ên, là dân sự Ngài.'),
(16189, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 135, 13, 'OT', 'Hỡi Đức Giê-hô-va, danh Ngài còn mãi đời đời; hỡi Đức Giê-hô-va, kỷ niệm Ngài trải qua các thế hệ và thế hệ.'),
(16190, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 135, 14, 'OT', 'Vì Đức Giê-hô-va sẽ xét đoán dân Ngài, và sẽ đổi lòng về những kẻ tôi tớ Ngài.'),
(16191, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 135, 15, 'OT', 'Tượng thần của các dân ngoại bằng bạc và bằng vàng, là công việc làm ra bởi tay loài người.'),
(16192, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 135, 16, 'OT', 'Chúng có miệng mà không nói, có mắt mà không thấy,'),
(16193, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 135, 17, 'OT', 'Chúng có tai mà không nghe, miệng chúng không có hơi thở.'),
(16194, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 135, 18, 'OT', 'Cũng như hình tượng ấy, kẻ làm ra chúng sẽ trở nên như vậy, mọi người tin cậy nơi chúng cũng vậy.'),
(16195, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 135, 19, 'OT', 'Hỡi nhà Y-sơ-ra-ên, hãy chúc tụng Đức Giê-hô-va! Hỡi nhà A-rôn, hãy chúc tụng Đức Giê-hô-va!'),
(16196, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 135, 20, 'OT', 'Hỡi nhà Lê-vi, hãy chúc tụng Đức Giê-hô-va; hỡi các người kính sợ Đức Giê-hô-va, hãy chúc tụng Đức Giê-hô-va!'),
(16197, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 135, 21, 'OT', 'Ha-lê-lu-gia! Đáng chúc tụng Đức Giê-hô-va từ Si-ôn, là Đấng ngự tại Giê-ru-sa-lem.'),
(16198, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 136, 1, 'OT', 'Hãy cảm tạ Đức Giê-hô-va, vì Ngài tốt lành; sự nhân từ của Ngài còn mãi đời đời.'),
(16199, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 136, 2, 'OT', 'Hãy cảm tạ Đức Chúa Trời của các thần, vì sự nhân từ của Ngài còn mãi đến đời đời.'),
(16200, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 136, 3, 'OT', 'Hãy cảm tạ Đức Chúa Trời của các chúa; vì sự nhân từ của Ngài còn đến đời đời.'),
(16201, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 136, 4, 'OT', 'Chỉ một mình Ngài làm nên những điều kỳ diệu lớn lao, Vì sự nhân từ Ngài còn mãi đời đời.'),
(16202, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 136, 5, 'OT', 'Đức Chúa Trời đã làm các tầng trời cách khôn ngoan, vì sự nhân từ Ngài còn đến đời đời.'),
(16203, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 136, 6, 'OT', 'Chúa Giê-hô-va trải đất ra trên mặt nước, vì sự nhân từ của Ngài còn mãi đến đời đời.'),
(16204, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 136, 7, 'OT', 'Làm những vì sao lớn, vì sự nhân từ của Ngài còn đời đời.'),
(16205, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 136, 8, 'OT', 'Mặt trời để cai trị ban ngày, vì sự nhân từ của Đức Giê-hô-va còn đến đời đời.'),
(16206, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 136, 9, 'OT', 'Mặt trăng và các ngôi sao để cai trị ban đêm, vì sự nhân từ của Đức Giê-hô-va còn đến đời đời.'),
(16207, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 136, 10, 'OT', 'Đấng đánh giết người Ai-cập tại các con đầu lòng của chúng, vì sự nhân từ của Ngài còn đời đời.'),
(16208, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 136, 11, 'OT', 'Đức Giê-hô-va dẫn Y-sơ-ra-ên ra khỏi giữa chúng nó, vì sự nhân từ của Ngài còn đến đời đời.'),
(16209, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 136, 12, 'OT', 'Bởi tay quyền năng và cánh tay giơ thẳng, vì sự nhân từ Ngài còn đến đời đời.'),
(16210, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 136, 13, 'OT', 'Đấng phân biển Biển Đỏ ra từng phần, vì sự nhân từ Ngài còn đến đời đời.'),
(16211, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 136, 14, 'OT', 'Khiến Y-sơ-ra-ên đi qua giữa biển, vì sự nhân từ Ngài còn đến đời đời.'),
(16212, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 136, 15, 'OT', 'Và xô Pha-ra-ôn cùng đạo binh người xuống Biển Sậy, vì tình yêu thương Ngài tồn tại mãi mãi.'),
(16213, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 136, 16, 'OT', 'Đức Giê-hô-va dẫn dân Ngài qua đồng vắng, vì sự nhân từ Ngài còn đời đời.'),
(16214, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 136, 17, 'OT', 'Đánh bại các vua lớn, vì sự nhân từ của Đức Giê-hô-va còn đời đời.'),
(16215, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 136, 18, 'OT', 'Đánh giết các vua quyền năng, vì sự nhân từ của Đức Giê-hô-va còn đời đời.'),
(16216, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 136, 19, 'OT', 'Cho Si-hôn, vua dân A-mô-rít, vì sự nhân từ của Đức Giê-hô-va còn đến đời đời.'),
(16217, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 136, 20, 'OT', 'và Oùc, vua Ba-san, vì sự nhân từ của Đức Giê-hô-va còn đến đời đời.'),
(16218, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 136, 21, 'OT', 'Ngài ban đất nước của chúng nó làm sản nghiệp, vì sự nhân từ của Ngài còn đời đời.'),
(16219, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 136, 22, 'OT', 'Làm sản nghiệp cho Y-sơ-ra-ên, là tôi tớ Ngài, vì sự nhân từ của Đức Giê-hô-va còn mãi đời đời.'),
(16220, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 136, 23, 'OT', 'Đức Giê-hô-va nhớ đến chúng tôi trong sự khiêm nhường của chúng tôi, vì sự nhân từ Ngài còn đến đời đời.'),
(16221, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 136, 24, 'OT', 'Giải cứu chúng tôi khỏi kẻ thù, vì sự nhân từ của Ngài còn đến đời đời.'),
(16222, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 136, 25, 'OT', 'Đức Giê-hô-va ban bánh cho mọi loài xác thịt, vì sự nhân từ của Ngài còn mãi đời đời.'),
(16223, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 136, 26, 'OT', 'Hãy cảm tạ Đức Chúa Trời của các từng trời, vì sự nhân từ của Ngài còn mãi đời đời.'),
(16224, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 137, 1, 'OT', 'Trên các dòng sông Ba-by-lôn, chúng tôi đã ngồi đó và khóc, khi nhớ đến Si-ôn.'),
(16225, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 137, 2, 'OT', 'Chúng tôi treo những cây đờn cầm của chúng tôi trên các cây liễu ở giữa nơi ấy.'),
(16226, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 137, 3, 'OT', 'Vì tại đó những kẻ bắt chúng tôi làm phu tù đã yêu cầu chúng tôi nói lời ca hát; và những kẻ cướp giật chúng tôi lại đòi chúng tôi hát mừng mà rằng: Hãy hát cho chúng ta một bài ca của Si-ôn.'),
(16227, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 137, 4, 'OT', 'Làm sao chúng ta có thể hát bài ca của Đức Giê-hô-va trên đất nước của người ngoại?'),
(16228, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 137, 5, 'OT', 'Nếu tôi quên Giê-ru-sa-lem, nguyện tay phải tôi quên đi!'),
(16229, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 137, 6, 'OT', 'Nếu tôi không nhớ đến ngươi, nguyện lưỡi tôi dính nơi hàm họng tôi; nếu tôi không coi Giê-ru-sa-lem là niềm vui lớn nhất của tôi.'),
(16230, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 137, 7, 'OT', 'Hỡi Đức Giê-hô-va, xin hãy nhớ các con cái Ê-đôm, trong ngày Giê-ru-sa-lem, khi chúng nói: Hủy đi, hủy đi, cho đến nền của nó!'),
(16231, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 137, 8, 'OT', 'Hỡi con gái Ba-by-lôn, là kẻ bị tiêu diệt, phước cho người nào trả cho ngươi điều mà ngươi đã làm cho chúng ta!'),
(16232, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 137, 9, 'OT', 'Phúc thay người nào nắm lấy và đập tan con nhỏ ngươi trên tảng đá!'),
(16233, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 138, 1, 'OT', 'Tôi sẽ cảm tạ Ngài hết lòng mình, trước mặt các thần ta sẽ hát ngợi kinh Ngài.'),
(16234, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 138, 2, 'OT', 'Tôi sẽ thờ lạy về đền thánh khiết của Ngài, và cảm tạ danh Ngài vì nhân từ và lẽ thật của Ngài; vì Ngài đã làm cho lời Ngài được tôn cao hơn mọi danh Ngài.'),
(16235, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 138, 3, 'OT', 'Ngày tôi kêu cầu, Ngài đáp lời tôi, làm tôi mạnh dạn trong tâm linh.'),
(16236, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 138, 4, 'OT', 'Hỡi Đức Giê-hô-va, mọi vua trên đất sẽ ca ngợi Ngài, vì họ đã nghe các lời từ miệng Ngài.'),
(16237, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 138, 5, 'OT', 'Họ sẽ hát xướng về các nẻo đường của Đức Giê-hô-va, vì vinh hiển của Đức Giê-hô-va thật cao cả.'),
(16238, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 138, 6, 'OT', 'Dầu Đức Giê-hô-va cao cả, Ngài vẫn đoái đến kẻ khiêm nhường; còn kẻ kiêu ngạo, Ngài nhận biết từ xa.'),
(16239, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 138, 7, 'OT', 'Dẫu tôi bước giữa cảnh gian truân, Đức Giê-hô-va sẽ khiến tôi được sống; Ngài sẽ giơ tay chống cơn thịnh nộ của kẻ thù tôi, và tay phải Ngài sẽ cứu tôi.'),
(16240, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 138, 8, 'OT', 'Đức Giê-hô-va sẽ hoàn tất điều đã làm cho tôi. Đức Giê-hô-va ôi, sự nhân từ của Ngài còn mãi đời đời; công việc của tay Ngài, xin chớ buông bỏ.'),
(16241, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 139, 1, 'OT', 'Hỡi Đức Giê-hô-va, Ngài đã dò xét tôi, và biết tôi.'),
(16242, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 139, 2, 'OT', 'Chúa biết khi tôi ngồi, khi tôi đứng dậy; Ngài hiểu rõ ý tưởng tôi từ xa.'),
(16243, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 139, 3, 'OT', 'Chúa xét nét đường lối và nơi tôi nằm nghỉ; mọi nẻo bước tôi, Ngài đều quen biết.'),
(16244, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 139, 4, 'OT', 'Vì chưa có lời nào trên lưỡi tôi, kìa Đức Giê-hô-va đã biết trọn hết.'),
(16245, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 139, 5, 'OT', 'Ngài bao bọc tôi phía sau và phía trước, và đặt tay Ngài trên tôi.'),
(16246, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 139, 6, 'OT', 'Sự hiểu biết ấy thật kỳ diệu đối với tôi, cao cả quá, tôi không thể với tới được!'),
(16247, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 139, 7, 'OT', 'Tôi sẽ đi đâu khỏi Thần của Ngài? Tôi sẽ trốn đâu khỏi mặt Ngài?'),
(16248, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 139, 8, 'OT', 'Nếu tôi bay lên trời, Ngài ở đó; nếu tôi xuống âm phủ, kìa Ngài cũng ở đó.'),
(16249, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 139, 9, 'OT', 'Nếu tôi mang cánh bay về bình minh, đậu nơi tận cùng biển cả,'),
(16250, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 139, 10, 'OT', 'Cũng tại đó tay Ngài sẽ dẫn dắt tôi, và tay phải Ngài sẽ nắm giữ tôi.'),
(16251, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 139, 11, 'OT', 'Tôi nói: "Chắc hẳn bóng tối sẽ nuốt chửng tôi, và ban đêm sẽ trở thành ánh sáng quanh tôi."'),
(16252, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 139, 12, 'OT', 'Cả bóng tối cũng không thể làm khuất khỏi Ngài; đêm sáng chói như ngày, bóng tối đối với Ngài cũng sáng như ánh sáng.'),
(16253, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 139, 13, 'OT', 'Vì chính Ngài đã tạo nên nội tạng tôi; Ngài bao bọc tôi trong lòng mẹ tôi.'),
(16254, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 139, 14, 'OT', 'Tôi cảm tạ Đức Chúa Trời vì tôi được dựng nên cách đáng sợ và lạ lùng; công việc Ngài thật kỳ diệu, và lòng tôi biết rõ lắm.'),
(16255, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 139, 15, 'OT', 'Các xương cốt tôi chưa được che khuất khỏi Ngài, khi tôi được tạo nên cách kín nhiệm, được thêu dệt nơi các tầng sâu dưới đất.'),
(16256, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 139, 16, 'OT', 'Thể chất vô hình của tôi đã thấy bởi mắt Ngài; và trên sổ sách Ngài, tất cả các ngày đời tôi đều được ghi lại, các ngày ấy đã định sẵn, nhưng chưa có một ngày nào trong số đó.'),
(16257, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 139, 17, 'OT', 'Lạy Đức Chúa Trời, những ý tưởng của Ngài đối với tôi quí giá biết bao! Chúng đông vô số!'),
(16258, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 139, 18, 'OT', 'Nếu tôi đếm những ý tưởng ấy, thì nhiều hơn cát; tôi thức dậy, tôi vẫn ở cùng Ngài.'),
(16259, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 139, 19, 'OT', 'Lạy Đức Chúa Trời, nếu Ngài giết kẻ ác, thì những kẻ đổ máu hãy lìa xa tôi.'),
(16260, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 139, 20, 'OT', 'Vì chúng nói nghịch ngươi cách phỉnh dối, hỡi Đức Giê-hô-va, chúng lấy danh ngươi làm trò chơi.'),
(16261, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 139, 21, 'OT', 'Hỡi Đức Giê-hô-va, tôi há chẳng ghét những kẻ ghét Ngài sao? Và tôi há chẳng gớm ghiếc những kẻ dấy lên nghịch cùng Ngài sao?'),
(16262, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 139, 22, 'OT', 'Tôi ghét chúng đến cùng, thật sự ghét; chúng trở nên kẻ thù nghịch tôi.'),
(16263, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 139, 23, 'OT', 'Đức Chúa Trời ơi, hãy tra xét tôi và biết lòng tôi; thử tôi và biết những lo âu trong tôi.'),
(16264, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 139, 24, 'OT', 'Xin hãy xem xét, nơi tôi có đường lối đau buồn nào chăng, và dẫn dắt tôi trên con đường đời đời.'),
(16265, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 140, 1, 'OT', 'Hỡi Đức Giê-hô-va, xin giải cứu tôi khỏi người ác; bảo vệ tôi khỏi kẻ hung bạo,'),
(16266, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 140, 2, 'OT', 'Là những kẻ toan tính điều ác trong lòng; hằng ngày chúng gây ra chiến tranh.'),
(16267, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 140, 3, 'OT', 'Chúng mài lưỡi mình như rắn, nọc độc rắn hổ nằm dưới môi chúng nó.'),
(16268, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 140, 4, 'OT', 'Lạy Đức Giê-hô-va, xin giữ con khỏi tay kẻ ác; xin bảo vệ con khỏi người hung bạo, là kẻ đã toan tính làm cho bước chân con vấp ngã.'),
(16269, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 140, 5, 'OT', 'Những kẻ kiêu ngạo đã rình rập tôi, giăng bẫy cho tôi; dọc theo lối đi, chúng giăng lưới, đặt những cạm bẫy cho tôi. Hết.'),
(16270, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 140, 6, 'OT', 'Tôi thưa cùng Đức Giê-hô-va: Ngài là Đức Chúa Trời tôi; Đức Giê-hô-va ôi, xin lắng nghe tiếng nài xin của tôi.'),
(16271, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 140, 7, 'OT', 'Hỡi Đức Giê-hô-va, là sức lực về sự cứu rỗi tôi, xin che chở đầu tôi trong ngày giao chiến.'),
(16272, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 140, 8, 'OT', 'Hỡi Đức Giê-hô-va, xin chớ cho điều ác nhân mong muốn được thực hiện; mưu ác nó, xin chớ giúp thành tựu, để nó khỏi tự cao, luôn mãi.'),
(16273, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 140, 9, 'OT', 'Nguyện sự ác nơi môi những kẻ vây quanh tôi phủ lấy đầu chúng nó!'),
(16274, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 140, 10, 'OT', 'Nguyện Ngài đổ than hồng trên chúng nó! Nguyện từ trong lửa, Ngài quăng chúng nó xuống; chúng nó sẽ không thể đứng lên được nữa!'),
(16275, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 140, 11, 'OT', 'Người có lưỡi gian tà sẽ không được vững lập trong đất; người hung bạo và ác sẽ bị săn đuổi để đánh đổ.'),
(16276, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 140, 12, 'OT', 'Tôi biết rằng Đức Giê-hô-va sẽ làm công bình cho kẻ bị áp bức, xét đoán công lý cho người nghèo khó.'),
(16277, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 140, 13, 'OT', 'Chỉ những người ngay lành sẽ cảm tạ danh Đức Giê-hô-va; những người ngay thẳng sẽ ngồi trước mặt Ngài.'),
(16278, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 141, 1, 'OT', 'Một bài thơ của Đa-vít. Đức Giê-hô-va, tôi đã kêu cầu Ngài, xin hãy mau đến cùng tôi; khi tôi kêu cầu Ngài, xin hãy lắng nghe tiếng tôi.'),
(16279, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 141, 2, 'OT', 'Nguyện lời cầu nguyện tôi được chuẩn bị như hương thơm trước mặt Đức Giê-hô-va; nguyện việc giơ tay tôi lên như của lễ buổi chiều.'),
(16280, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 141, 3, 'OT', 'Hỡi Đức Giê-hô-va, xin đặt một sự canh giữ nơi miệng tôi, và giữ gìn cửa môi tôi.'),
(16281, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 141, 4, 'OT', 'Xin chớ để lòng tôi nghiêng về điều ác, để làm những mưu gian ác cùng những kẻ làm điều gian ác; cũng đừng để tôi ăn những món ngon của chúng nó.'),
(16282, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 141, 5, 'OT', 'Nguyện người công bình sửa dạy tôi bằng lòng nhân từ, và quở trách tôi; dầu đầu đừng làm đầu tôi sầu khổ. Vì lời cầu nguyện tôi vẫn còn trong lúc họ gặp tai họa.'),
(16283, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 141, 6, 'OT', 'Các quan xét của chúng nó bị vất xuống bên tảng đá; và chúng nó sẽ nghe lời tôi, vì lời tôi dịu dàng.'),
(16284, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 141, 7, 'OT', 'Hài cốt chúng tôi bị rải rác nơi miệng âm phủ, như khi người ta cày đất và đập vụn đất ra.'),
(16285, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 141, 8, 'OT', 'Hỡi Đức Giê-hô-va, tôi ngước mắt về Ngài; nơi Ngài, tôi nương náu mình; xin đừng đổ linh hồn tôi ra.'),
(16286, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 141, 9, 'OT', 'Xin Đức Giê-hô-va giữ con khỏi tay cái bẫy mà kẻ ác đã giăng cho con, và khỏi những dây lùng những kẻ làm điều ác.'),
(16287, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 141, 10, 'OT', 'Các kẻ ác sẽ sa vào lưới của chúng; còn tôi, tôi sẽ đi qua cho đến khi được thoát.'),
(16288, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 142, 1, 'OT', 'Lời cầu nguyện của Đa-vít, khi người ở trong hang động: Ta kêu lên Đức Giê-hô-va bằng tiếng ta; ta nài xin Đức Giê-hô-va bằng tiếng ta.'),
(16289, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 142, 2, 'OT', 'Tôi tuôn đổ trước mặt Ngài sự than thở tôi, bày tỏ trước mặt Ngài sự gian truân tôi.'),
(16290, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 142, 3, 'OT', 'Khi thần linh tôi sa sút, chính Ngài biết rõ lối bước tôi; trên con đường tôi đi, chúng giăng bẫy kín cho tôi.'),
(16291, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 142, 4, 'OT', 'Xin Đức Giê-hô-va nhìn sang bên phải, coi xem, chẳng có ai nhận biết tôi; nơi ẩn náu tôi đã mất, chẳng ai tìm kiếm linh hồn tôi.'),
(16292, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 142, 5, 'OT', 'Hỡi Đức Giê-hô-va, tôi kêu cầu Ngài, mà rằng: Ngài là nơi nương náu của tôi, phần tôi trong đất người sống.'),
(16293, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 142, 6, 'OT', 'Xin Đức Giê-hô-va hãy lắng nghe tiếng than khóc của tôi, vì tôi khốn khổ quá đỗi; xin cứu tôi khỏi kẻ đuổi theo tôi, vì chúng mạnh hơn tôi.'),
(16294, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 142, 7, 'OT', 'Xin hãy rút linh hồn tôi khỏi ngục tù, để tôi cảm tạ danh Đức Giê-hô-va. Những người công bình sẽ vây quanh tôi, vì Ngài làm ơn cho tôi.'),
(16295, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 143, 1, 'OT', 'Lời cầu nguyện của Đa-vít. Hỡi Đức Giê-hô-va, xin hãy nghe lời cầu nguyện tôi, xin hãy lắng tai nghe sự nài xin của tôi; nhân sự thành tín của Ngài, xin hãy đáp lại tôi theo sự công bình của Ngài.'),
(16296, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 143, 2, 'OT', 'Xin chớ vào xét đoán cùng kẻ tôi tớ của Ngài, vì trước mặt Ngài chẳng có người sống nào được xưng công bình.'),
(16297, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 143, 3, 'OT', 'Kẻ thù đã đuổi theo mạng sống tôi, giày đạp tôi xuống đất; nó đặt tôi trong nơi tối tăm, như những kẻ chết từ lâu.'),
(16298, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 143, 4, 'OT', 'Thần linh tôi hãi hùng; lòng tôi trong tôi sững sờ.'),
(16299, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 143, 5, 'OT', 'Tôi nhớ lại những ngày xưa, suy gẫm mọi công việc của Ngài, và chiêm ngưỡng những hành động nơi tay Ngài làm ra.'),
(16300, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 143, 6, 'OT', 'Tôi giơ tay mình hướng về Ngài; linh hồn tôi khao khát Ngài như đất khô khan.'),
(16301, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 143, 7, 'OT', 'Lạy Đức Giê-hô-va, xin mau đáp lời tôi; thần linh tôi đã hao mòn. Xin chớ giấu mặt Ngài khỏi tôi, kẻo tôi sẽ giống như những kẻ sa xuống hầm.'),
(16302, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 143, 8, 'OT', 'Xin cho con được nghe sự nhân từ Ngài vào buổi sáng, vì con tin cậy nơi Ngài; xin chỉ dạy con con đường mà con phải đi, vì linh hồn con ngước lên cùng Ngài.'),
(16303, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 143, 9, 'OT', 'Hỡi Đức Giê-hô-va, xin giải cứu tôi khỏi kẻ thù; tôi chạy đến nương náu nơi Ngài.'),
(16304, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 143, 10, 'OT', 'Xin dạy tôi làm theo ý muốn Ngài, vì chính Ngài là Đức Chúa Trời tôi; Thần tốt lành của Ngài sẽ dẫn tôi vào đất bằng phẳng.'),
(16305, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 143, 11, 'OT', 'Hỡi Đức Giê-hô-va, vì danh Ngài, xin cho tôi được sống; nhờ sự công bình Ngài, xin rút linh hồn tôi khỏi cơn khốn khổ.'),
(16306, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 143, 12, 'OT', 'Nhờ sự nhân từ Ngài, xin diệt hết kẻ thù tôi, và tiêu diệt mọi kẻ hà hiếp mạng sống tôi; vì tôi là tôi tớ Ngài.'),
(16307, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 144, 1, 'OT', 'Đáng ngợi khen Đức Giê-hô-va, hòn đá của tôi, Đấng dạy tay tôi đánh giặc, các ngón tay tôi tranh đấu.'),
(16308, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 144, 2, 'OT', 'Đức Giê-hô-va là sự nhân từ tôi, là đồn lũy tôi, là nơi ẩn náu cao sang, là Đấng giải cứu tôi, là cái khiên tôi, là nơi tôi nương náu; Ngài khiến dân tôi phục dưới tôi.'),
(16309, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 144, 3, 'OT', 'Hỡi Đức Giê-hô-va, loài người là chi mà Ngài biết đến? Con loài người là gì mà Ngài nghĩ đến?'),
(16310, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 144, 4, 'OT', 'Người ta giống như hơi thở, các ngày đời người như bóng trôi qua.'),
(16311, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 144, 5, 'OT', 'Hỡi Đức Giê-hô-va, xin hãy hạ các từng trời mà ngự xuống, hãy đụng đến núi, thì núi sẽ tỏa khói.'),
(16312, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 144, 6, 'OT', 'Xin hãy chớp tia chớp và làm tan tác chúng; bắn các mũi tên của Ngài khiến chúng hoảng hốt.'),
(16313, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 144, 7, 'OT', 'Xin hãy giơ tay Ngài ra từ trên cao, giải cứu tôi và vớt tôi lên khỏi những dòng nước lớn, khỏi tay những con cái người ngoại.'),
(16314, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 144, 8, 'OT', 'Miệng chúng nói lời hư không, và tay phải chúng là tay phải dối trá.'),
(16315, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 144, 9, 'OT', 'Hỡi Đức Chúa Trời, tôi sẽ hát cho Ngài một bài ca mới, lấy đàn cầm mười dây tôi sẽ hát ngợi khen Ngài.'),
(16316, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 144, 10, 'OT', 'Chúa ban sự cứu rỗi cho các vua, giải cứu Đa-vít tôi tớ Ngài khỏi gươm hung ác.'),
(16317, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 144, 11, 'OT', 'Xin hãy giải cứu tôi và cứu tôi khỏi tay con cái người ngoại; vì miệng chúng nói điều hư không, và tay phải chúng là tay phải dối trá.'),
(16318, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 144, 12, 'OT', 'Nguyện các con trai chúng tôi như những cây non đã được vun trồng trong tuổi trẻ mình; nguyện các con gái chúng tôi như những trụ đá, chạm trổ theo kiểu dáng của đền thờ.'),
(16319, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 144, 13, 'OT', 'Kho lẫm chúng tôi đầy dẫy, cung cấp từ kho này đến kho khác; chiên chúng tôi sinh sản thành từng ngàn từng vạn, ở ngoài đồng chúng tôi.'),
(16320, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 144, 14, 'OT', 'Nguyện các bò cái của chúng tôi mang thai và đẻ nhiều; nguyện không có sự phá vỡ, không có sự ra ngoài, và không có tiếng kêu la trong các phố chợ của chúng tôi.'),
(16321, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 144, 15, 'OT', 'Phước thay cho dân nào có cảnh tượng như vậy! Phước thay cho dân nào có Đức Giê-hô-va làm Đức Chúa Trời mình!'),
(16322, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 145, 1, 'OT', 'Lời ca ngợi của Đa-vít. Lạy Đức Chúa Trời, là Vua của tôi, tôi sẽ tôn cao Ngài, và chúc tụng danh Ngài đến muôn đời mãi mãi.'),
(16323, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 145, 2, 'OT', 'Hằng ngày tôi sẽ chúc tụng Đức Giê-hô-va, và ca ngợi danh Ngài đời đời vô cùng.'),
(16324, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 145, 3, 'OT', 'Đức Giê-hô-va thật vĩ đại và rất đáng ngợi khen; sự cao cả của Ngài thì không thể dò xét.'),
(16325, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 145, 4, 'OT', 'Thế hệ nầy sẽ ca ngợi các công việc của Đức Giê-hô-va, và thế hệ khác sẽ kể lại các việc quyền năng của Ngài.'),
(16326, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 145, 5, 'OT', 'Tôi sẽ suy gẫm về vẻ vang oai nghi rực rỡ của Ngài, và về các việc làm kỳ diệu của Ngài.'),
(16327, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 145, 6, 'OT', 'Người ta sẽ nói về sức mạnh của những điều đáng sợ thuộc về Chúa; còn tôi sẽ thuật lại sự vĩ đại của Ngài.'),
(16328, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 145, 7, 'OT', 'Họ sẽ nói ra sự nhớ đến sự tốt lành lớn của Ngài, và hát lớn lên về sự công chính của Ngài.'),
(16329, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 145, 8, 'OT', 'Đức Giê-hô-va đầy ơn và lòng thương xót, chậm nóng giận và giàu lòng nhân từ.'),
(16330, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 145, 9, 'OT', 'Đức Giê-hô-va tốt lành cho mọi người, và sự thương xót của Ngài trải rộng trên mọi công việc Ngài làm.'),
(16331, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 145, 10, 'OT', 'Hỡi Đức Giê-hô-va, mọi công việc của Ngài sẽ ca ngợi Ngài; và những người thánh của Ngài sẽ chúc tụng Ngài.'),
(16332, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 145, 11, 'OT', 'Họ sẽ nói về sự vinh hiển của vương quốc Ngài, và nói về quyền năng của Ngài.'),
(16333, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 145, 12, 'OT', 'Để cho con loài người biết được các việc quyền năng của Ngài, và sự vinh hiển oai nghiêm của vương quốc Ngài.'),
(16334, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 145, 13, 'OT', 'Nước Chúa là nước của mọi đời, và quyền cai trị của Ngài tồn tại qua mọi thế hệ.'),
(16335, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 145, 14, 'OT', 'Đức Giê-hô-va nâng đỡ mọi người sa ngã, và làm cho ngay thẳng mọi người bị khuỳnh.'),
(16336, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 145, 15, 'OT', 'Mắt mọi loài đều ngước về Ngài; chính Ngài ban cho chúng thức ăn đúng thì.'),
(16337, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 145, 16, 'OT', 'Chúa mở rộng tay ra, làm cho thỏa nguyện mọi sinh vật theo ý muốn của Ngài.'),
(16338, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 145, 17, 'OT', 'Đức Giê-hô-va là công bình trong mọi đường lối của Ngài, và đầy ơn trong mọi công việc của Ngài.'),
(16339, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 145, 18, 'OT', 'Đức Giê-hô-va ở gần mọi người kêu cầu Ngài, tức là gần mọi người kêu cầu Ngài cách thành thực.'),
(16340, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 145, 19, 'OT', 'Ngài sẽ làm trọn điều ước ao của những kẻ kính sợ Ngài; và Ngài sẽ nghe tiếng kêu xin của họ, rồi cứu giúp họ.'),
(16341, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 145, 20, 'OT', 'Đức Giê-hô-va giữ gìn mọi người yêu mến Ngài, còn mọi kẻ ác thì Ngài sẽ tiêu diệt.'),
(16342, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 145, 21, 'OT', 'Miệng tôi sẽ nói ra sự ngợi khen Đức Giê-hô-va; và mọi loài xác thịt sẽ chúc tụng danh thánh của Ngài đến muôn đời mãi mãi.'),
(16343, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 146, 1, 'OT', 'Ha-lê-lu-gia! Hỡi linh hồn ta, hãy ngợi khen Đức Giê-hô-va!'),
(16344, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 146, 2, 'OT', 'Tôi sẽ ngợi khen Đức Giê-hô-va trọn đời tôi còn sống; tôi sẽ hát xướng cho Đức Chúa Trời tôi bao lâu tôi còn tồn tại.'),
(16345, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 146, 3, 'OT', 'Đừng tin cậy nơi các bậc quyền quý, cũng đừng nơi con loài người, là nơi không có sự cứu rỗi.'),
(16346, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 146, 4, 'OT', 'Hơi thở người ấy ra đi, trở về với đất của mình; trong ngày ấy, các mưu toan người ấy đều tiêu tan.'),
(16347, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 146, 5, 'OT', 'Phước cho người nào có Đức Chúa Trời của Gia-cốp giúp đỡ mình, và đặt niềm tin cậy nơi Đức Giê-hô-va Đức Chúa Trời mình!'),
(16348, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 146, 6, 'OT', 'Làm ra trời đất, biển cả và mọi vật ở trong đó; giữ sự thật đến đời đời,'),
(16349, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 146, 7, 'OT', 'Làm công bình cho kẻ bị hà hiếp, ban bánh cho người đói; Đức Giê-hô-va buông tha kẻ bị trói.'),
(16350, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 146, 8, 'OT', 'Đức Giê-hô-va làm sáng mắt người mù; Đức Giê-hô-va làm thẳng kẻ cong queo; Đức Giê-hô-va yêu kẻ công bình.'),
(16351, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 146, 9, 'OT', 'Đức Giê-hô-va bảo vệ kẻ ngoại, nâng đỡ kẻ mồ côi và người goá bụa; nhưng Ngài làm xiêu đổ đường lối kẻ ác.'),
(16352, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 146, 10, 'OT', 'Đức Giê-hô-va sẽ trị vì đời đời; hỡi Si-ôn, Đức Chúa Trời ngươi làm Vua đến muôn đời! Ha-lê-lu-gia!'),
(16353, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 147, 1, 'OT', 'Hãy ngợi khen Đức Giê-hô-va, vì thật tốt lành; hãy hát ngợi khen Đức Chúa Trời chúng ta, vì thật đẹp đẽ; sự ngợi khen là điều đáng yêu mến.'),
(16354, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 147, 2, 'OT', 'Đức Giê-hô-va xây cất Giê-ru-sa-lem; Ngài hiệp lại những kẻ bị đuổi ra khỏi Y-sơ-ra-ên.'),
(16355, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 147, 3, 'OT', 'Chữa lành những người có lòng bị vỡ, và băng bó những vết thương của họ.'),
(16356, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 147, 4, 'OT', 'Người đếm số các ngôi sao, gọi tên từng ngôi hết thảy.'),
(16357, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 147, 5, 'OT', 'Chúa Tể chúng tôi thật lớn và quyền năng rất mạnh; sự thông sáng của Ngài thì vô số.'),
(16358, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 147, 6, 'OT', 'Đức Giê-hô-va nâng đỡ kẻ khiêm nhường, làm cho kẻ ác phải hạ mình xuống tận đất.'),
(16359, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 147, 7, 'OT', 'Hãy xướng lên cho Đức Giê-hô-va lời cảm tạ, Hãy gảy đàn cầm mà ca ngợi Đức Chúa Trời chúng tôi.'),
(16360, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 147, 8, 'OT', 'Đức Giê-hô-va là Đấng che các từng trời bằng mây, chuẩn bị mưa cho đất, khiến cỏ mọc trên các núi.'),
(16361, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 147, 9, 'OT', 'Ngài ban thức ăn cho súc vật, và cho những con quạ con kêu tiếng.'),
(16362, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 147, 10, 'OT', 'Ngài không vui thích sức mạnh của ngựa, cũng không ưa thích chân của người.'),
(16363, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 147, 11, 'OT', 'Đức Giê-hô-va ưa thích những người kính sợ Ngài, và những người trông đợi sự nhân từ của Ngài.'),
(16364, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 147, 12, 'OT', 'Hỡi Giê-ru-sa-lem, hãy ngợi khen Đức Giê-hô-va; hỡi Si-ôn, hãy ngợi khen Đức Chúa Trời ngươi!'),
(16365, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 147, 13, 'OT', 'Vì Ngài đã làm vững chắc then cửa thành ngươi, ban phước cho các con trai ngươi ở giữa lòng ngươi.'),
(16366, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 147, 14, 'OT', 'Đặt nơi biên giới ngươi sự bình an, khiến ngươi được no đủ bởi tinh chất của lúa mì.'),
(16367, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 147, 15, 'OT', 'Ngài sai lời Ngài ra trên đất, lời Ngài chạy rất mau.'),
(16368, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 147, 16, 'OT', 'Ngài ban tuyết như len, rải sương giá trắng như tro.'),
(16369, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 147, 17, 'OT', 'Ngài quăng tuyết trắng như vải gai; ai chịu nổi trước cái lạnh của Ngài?'),
(16370, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 147, 18, 'OT', 'Ngài phán ra lời, tuyết giá bèn đông cứng; Ngài cho gió thần của Ngài thổi lên, nước bèn chảy.'),
(16371, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 147, 19, 'OT', 'Ngài rao giảng lời Ngài cho Gia-cốp, các điều luật và các quyết định của Ngài cho Y-sơ-ra-ên.'),
(16372, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 147, 20, 'OT', 'Ngài chẳng làm như vậy cho dân nào khác; các mạng lịnh của Ngài, chúng nó không biết. Ha-lê-lu-gia'),
(16373, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 148, 1, 'OT', 'Ha-lê-lu-gia! Ha-lê-lu-gia Đức Giê-hô-va từ các từng trời! Ngợi khen Ngài nơi các nơi cao cả!'),
(16374, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 148, 2, 'OT', 'Hãy ngợi khen Ngài, hỡi mọi thiên sứ của Ngài; hãy ngợi khen Ngài, hỡi cả đạo binh Ngài!'),
(16375, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 148, 3, 'OT', 'Hãy ngợi khen Ngài, hỡi mặt trời và mặt trăng! Hãy ngợi kقن Ngài, hỡi mọi ngôi sao sáng!'),
(16376, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 148, 4, 'OT', 'Hãy ngợi khen Ngài, các từng trời và các nước ở trên các từng trời!'),
(16377, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 148, 5, 'OT', 'Hãy ngợi khen danh Đức Giê-hô-va, vì Ngài ra lệnh và chúng được tạo nên.'),
(16378, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 148, 6, 'OT', 'Ngài đã thiết lập chúng đến muôn đời, một mạng lệnh đã ban ra, sẽ không bị vi phạm.'),
(16379, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 148, 7, 'OT', 'Hãy ngợi khen Đức Giê-hô-va từ nơi đất, hỡi các quái vật biển và mọi vực sâu.'),
(16380, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 148, 8, 'OT', 'Lửa cùng mưa đá, tuyết và sương mù, gió bão thi hành lời Ngài,'),
(16381, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 148, 9, 'OT', 'Các núi và mọi gò, cây trái và mọi cây tùng.'),
(16382, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 148, 10, 'OT', 'Thú vật và mọi loài cầm thú, sinh vật bò trên đất và chim có cánh.'),
(16383, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 148, 11, 'OT', 'Các vua của đất và mọi dân tộc, Công-hầu và tất cả các quan xét trên đất,'),
(16384, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 148, 12, 'OT', 'Các thanh niên và cả các nữ đồng trinh, các người già cùng các trẻ nhỏ:'),
(16385, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 148, 13, 'OT', 'Hãy ngợi khen danh Đức Giê-hô-va, vì danh Ngài được tôn cao riêng một mình; sự oai nghiêm của Ngài vượt trên đất và các từng trời.'),
(16386, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 148, 14, 'OT', 'Ngài đã nâng cao cái sừng cho dân sự Ngài, là sự ngợi khen cho mọi thánh nhân của Ngài, cho con cái Y-sơ-ra-ên, là dân gần Ngài. Ha-lê-lu-gia!'),
(16387, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 149, 1, 'OT', 'Ha-lê-lu-gia! Hãy hát xướng cho Đức Giê-hô-va một bài ca mới! Hãy ca ngợi Ngài trong hội chúng các thánh.'),
(16388, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 149, 2, 'OT', 'Nguyện Y-sơ-ra-ên vui mừng nơi Đấng Tạo Hóa mình; các con trai Si-ôn hân hoan nơi Vua họ.'),
(16389, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 149, 3, 'OT', 'Nguyện chúng nó ca ngợi danh Ngài trong điệu múa, dùng trống và đàn cầm mà hát xướng cho Ngài!'),
(16390, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 149, 4, 'OT', 'Vì Đức Giê-hô-va yêu dân sự Ngài; Ngài dùng sự cứu rỗi mà trang sức cho người khiêm nhường.'),
(16391, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 149, 5, 'OT', 'Các thánh của Đức Chúa Trời hãy vui mừng trong vinh hiển; hãy reo lên trên giường mình!'),
(16392, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 149, 6, 'OT', 'Sự ngợi khen Đức Chúa Trời ở trong miệng họ, và thanh gươm hai lưỡi sắc bén ở trong tay họ.'),
(16393, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 149, 7, 'OT', 'Để thực hiện sự báo thù trên các nước, các sự trừng phạt trên các dân.'),
(16394, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 149, 8, 'OT', 'Để trói các vua chúng nó bằng xiềng, và các người sang trọng của chúng nó bằng gông sắt.'),
(16395, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 149, 9, 'OT', 'Để thi hành nơi chúng sự xét xử đã chép sẵn; sự vinh hiển ấy là cho mọi người thánh của Ngài. Ha-lê-lu-gia!'),
(16396, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 150, 1, 'OT', 'Ha-lê-lu-gia! Hãy ngợi khen Đức Giê-hô-va trong nơi thánh của Ngài! Hãy ngợi khen Ngài trong vòm trời quyền năng của Ngài!'),
(16397, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 150, 2, 'OT', 'Hãy ngợi khen Ngài vì các việc quyền năng của Ngài; hãy ngợi khen Ngài theo sự lớn lao rực rỡ của Ngài!'),
(16398, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 150, 3, 'OT', 'Hãy ngợi khen Ngài bằng tiếng thổi của loa tù và, hãy ngợi khen Ngài bằng đàn cầm và đàn sắt.'),
(16399, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 150, 4, 'OT', 'Hãy ngợi khen Ngài với trống cơm và điệu múa; hãy ngợi khen Ngài với nhạc cụ dây và sáo.'),
(16400, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 150, 5, 'OT', 'Hãy ngợi khen Ngài bằng những chiếc chập chỏa phát ra tiếng vang; hãy ngợi khen Ngài bằng những chiếc chập chỏa rền vang.'),
(16401, 19, 'GOI_vi', 'GOI_vi', 'vi', 'PSA', 150, 6, 'OT', 'Mọi vật thở đều hãy ngợi khen Đức Giê-hô-va. Ha-lê-lu-gia!'),
(16402, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 1, 'OT', 'Các câu tục ngữ của Sa-lô-môn, con trai Đa-vít, vua Y-sơ-ra-ên:'),
(16403, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 2, 'OT', 'Để biết sự khôn ngoan và sự khuyên dạy, để hiểu các lời lẽ thông sáng.'),
(16404, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 3, 'OT', 'để tiếp nhận sự dạy dỗ theo lẽ khôn, sự công bình, sự xét đoán và sự ngay thẳng;'),
(16405, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 4, 'OT', 'Để ban sự khôn khéo cho kẻ vô tri, cho người trẻ tuổi được sự hiểu biết và thông sáng.'),
(16406, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 5, 'OT', 'Kẻ khôn sẽ nghe và gia tăng sự học hỏi, người thông sáng sẽ nhận được sự hiểu biết sâu sắc.'),
(16407, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 6, 'OT', 'Để hiểu châm ngôn và lời ẩn dụ, các lời của người khôn ngoan và câu đố của họ.'),
(16408, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 7, 'OT', 'Sự kính sợ Đức Giê-hô-va là khởi đầu của tri thức; kẻ ngu muội khinh bỉ sự khôn ngoan và sự dạy dỗ.'),
(16409, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 8, 'OT', 'Hỡi con, hãy nghe lời dạy của cha ngươi, và chớ từ bỏ luật pháp của mẹ ngươi.'),
(16410, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 9, 'OT', 'Vì chúng sẽ như một dây hoa trên đầu ngươi, và như những vòng đeo quanh cổ ngươi.'),
(16411, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 10, 'OT', 'Hỡi con, nếu những kẻ tội lỗi quyến dụ con, chớ chịu đi theo.'),
(16412, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 11, 'OT', 'Nếu chúng nói: "Hãy đi với chúng ta, ta sẽ rình rập huyết người, ta sẽ phục kích vô cớ kẻ vô tội;"'),
(16413, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 12, 'OT', 'Hãy nuốt sống chúng nó như kẻ xuống âm phủ, và còn nguyên vẹn như những kẻ sa xuống hầm hố;'),
(16414, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 13, 'OT', 'Ta sẽ tìm được mọi thứ của cải quý giá, chất đầy nhà ta những của cướp;'),
(16415, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 14, 'OT', 'Hãy quăng phần ngươi vào giữa chúng ta; túi nào cũng sẽ là một cho tất cả chúng ta.'),
(16416, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 15, 'OT', 'Hỡi con, chớ đi theo con đường của chúng nó; hãy kiêng giữ chân con khỏi lối đi của chúng nó.'),
(16417, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 16, 'OT', 'Vì chân chúng nó chạy về điều ác, và vội vã làm đổ huyết.'),
(16418, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 17, 'OT', 'Vì luống công giăng lưới trước mắt mọi loài chim bay.'),
(16419, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 18, 'OT', 'Chúng phục mưu để đổ huyết mình ra, núp rình hại mạng sống mình.'),
(16420, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 19, 'OT', 'Đường lối của mọi kẻ tham của bất chính đều như vậy; nó sẽ đoạt lấy mạng sống của chính chủ nó.'),
(16421, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 20, 'OT', 'Sự khôn ngoan kêu lên ngoài đường phố, cất tiếng mình nơi các quảng trường.'),
(16422, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 21, 'OT', 'Ở đầu các ngã đường ồn ào, người kêu gọi; tại các cửa thành, người nói lời mình.'),
(16423, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 22, 'OT', 'Đến bao giờ kẻ dại dột còn yêu sự dại dột, kẻ nhạo báng còn ưa thích sự nhạo báng, và kẻ ngu si ghét sự hiểu biết?'),
(16424, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 23, 'OT', 'Hãy trở lại cùng sự sửa dạy của ta; nầy, ta sẽ đổ thần ta ra cho các ngươi, sẽ cho các ngươi biết các lời ta.'),
(16425, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 24, 'OT', 'Vì ta đã kêu gọi mà các ngươi không chịu nghe, ta giơ tay ra mà chẳng ai để ý;'),
(16426, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 25, 'OT', 'Nhưng các ngươi đã khước từ mọi lời khuyên dạy của ta, và không chịu lời quở trách của ta;'),
(16427, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 26, 'OT', 'Ta cũng sẽ chế giễu trong lúc tai họa các ngươi đến, sẽ nhạo báng khi sự sợ hãi các ngươi ập tới.'),
(16428, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 27, 'OT', 'Khi sự sợ hãi các ngươi đến như gió bão, tai họa các ngươi ập đến như cơn lốc xoáy; khi hoạn nạn và khốn khổ giáng trên các ngươi.'),
(16429, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 28, 'OT', 'Bấy giờ chúng sẽ kêu cầu ta, nhưng ta sẽ không đáp; chúng sẽ tìm ta, nhưng không gặp được ta.'),
(16430, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 29, 'OT', 'Vì chúng ghét sự thông sáng và không chọn sự kính sợ Đức Giê-hô-va,'),
(16431, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 30, 'OT', 'không chịu nghe theo lời khuyên dạy ta, khinh bỉ mọi lời sửa dạy ta;'),
(16432, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 31, 'OT', 'Chúng sẽ ăn trái của đường lối mình, và được no nê những mưu kế của chúng.'),
(16433, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 32, 'OT', 'Vì sự từ bỏ của kẻ ngu muội sẽ giết chúng nó, và sự an nhàn của kẻ dại dột sẽ tiêu diệt chúng nó.'),
(16434, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 1, 33, 'OT', 'Nhưng ai nghe lời ta sẽ ở yên ổn, và được an nhiên, không sợ tai họa.'),
(16435, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 2, 1, 'OT', 'Hỡi con, nếu con nhận lấy các lời ta, và giữ các mạng lịnh ta nơi con,'),
(16436, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 2, 2, 'OT', 'Để lắng tai nghe sự khôn ngoan, chuyên lòng con về sự thông sáng;'),
(16437, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 2, 3, 'OT', 'vì nếu ngươi kêu cầu sự hiểu biết, và ra tiếng ngươi cầu xin sự thông sáng,'),
(16438, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 2, 4, 'OT', 'Nếu con tìm kiếm nó như tìm bạc, và ransao nó như những kho tàng ẩn giấu,'),
(16439, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 2, 5, 'OT', 'Bấy giờ ngươi sẽ hiểu biết sự kính sợ Đức Giê-hô-va, và sẽ tìm được tri thức của Đức Chúa Trời.'),
(16440, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 2, 6, 'OT', 'Vì Đức Giê-hô-va ban cho sự khôn ngoan; từ miệng Ngài ra sự hiểu biết và thông sáng.'),
(16441, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 2, 7, 'OT', 'Ngài cất giữ sự vững chắc cho người ngay thẳng; Ngài là cái khiên che chở cho những kẻ ăn ở ngay lành.'),
(16442, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 2, 8, 'OT', 'Bảo vệ các nẻo đường công lý, và gìn giữ các lối đi của người trung tín.'),
(16443, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 2, 9, 'OT', 'Bấy giờ con sẽ hiểu biết sự công bình, sự xét đoán, sự ngay thẳng, và mọi lối tốt lành.'),
(16444, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 2, 10, 'OT', 'Vì sự khôn ngoan sẽ vào trong lòng con, và sự hiểu biết sẽ làm lòng con vui vẻ.'),
(16445, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 2, 11, 'OT', 'Sự suy xét sẽ gìn giữ con, sự hiểu biết sẽ bảo vệ con,'),
(16446, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 2, 12, 'OT', 'Để cứu con khỏi đường dữ, khỏi người đàn ông nói điều gian dối,'),
(16447, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 2, 13, 'OT', 'rời bỏ các lối ngay thẳng để đi theo các con đường tăm tối;'),
(16448, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 2, 14, 'OT', 'Vui mừng làm điều ác, hớn hở vì những điều gian tà.'),
(16449, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 2, 15, 'OT', 'Đường lối chúng cong vạy, và các lối đi của chúng quanh co.'),
(16450, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 2, 16, 'OT', 'để cứu bạn khỏi người phụ nữ ngoại đạo, khỏi người đàn bà xa lạ nói lời trơn tru.'),
(16451, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 2, 17, 'OT', 'Người bỏ người bạn thời thanh niên, và quên giao ước của Đức Chúa Trời mình;'),
(16452, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 2, 18, 'OT', 'Vì nhà nó nghiêng về phía sự chết, và các lối đi của nó dẫn đến những kẻ đã qua đời;'),
(16453, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 2, 19, 'OT', 'Mọi kẻ đến cùng nàng sẽ không trở lại, và chẳng đạt được các lối sống.'),
(16454, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 2, 20, 'OT', 'để con đi theo con đường của người thiện và giữ gìn các lối của kẻ công bình.'),
(16455, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 2, 21, 'OT', 'Vì người ngay thẳng sẽ được ở trên đất, và người trọn lành sẽ được vững lập trên đất ấy.'),
(16456, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 2, 22, 'OT', 'Còn kẻ ác sẽ bị truất khỏi đất, và kẻ phản bội sẽ bị nhổ rứt khỏi nơi ấy.'),
(16457, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 1, 'OT', 'Hỡi con, chớ quên lời dạy dỗ ta, và các điều răn ta, lòng con phải giữ gìn.'),
(16458, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 2, 'OT', 'vì nó sẽ gia tăng cho con thêm tuổi thọ, số năm đời sống và sự bình an.'),
(16459, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 3, 'OT', 'Đức nhân từ và lẽ chân thật, chớ để chúng rời khỏi con; hãy buộc chúng quanh cổ con, viết chúng trên bảng lòng con.'),
(16460, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 4, 'OT', 'Và con sẽ được ơn và sự khôn ngoan tốt lành trong mắt Đức Chúa Trời và loài người.'),
(16461, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 5, 'OT', 'Hãy tin cậy Đức Giê-hô-va hết lòng con, và chớ nương cậy nơi sự hiểu biết của con;'),
(16462, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 6, 'OT', 'Trong mọi nẻo đường của con, hãy nhận biết Ngài, thì chính Ngài sẽ làm cho các lối đi của con được ngay thẳng.'),
(16463, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 7, 'OT', 'Chớ khôn ngoan trong mắt mình; hãy kính sợ Đức Giê-hô-va và lìa khỏi điều ác.'),
(16464, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 8, 'OT', 'Sẽ là phương thuốc cho thân thể ngươi, và sự bổ dưỡng cho xương cốt ngươi.'),
(16465, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 9, 'OT', 'Hãy tôn vinh Đức Giê-hô-va bằng tài sản con, và bằng hoa lợi đầu mùa của mọi sản vật con.'),
(16466, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 10, 'OT', 'Các kho lẫm của con sẽ đầy dẫy lương thực, và các hầm ép rượu của con sẽ tràn đầy rượu mới.'),
(16467, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 11, 'OT', 'Hỡi con, chớ khinh dể sự sửa phạt của Đức Giê-hô-va, và chớ ghét bỏ khi Ngài quở trách con.'),
(16468, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 12, 'OT', 'Vì Đức Giê-hô-va chỉ bảo kẻ mà Ngài yêu thương, và như một người cha đối với con trai mình ưa thích.'),
(16469, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 13, 'OT', 'Phước thay cho người tìm được sự khôn ngoan, và ai nhận được sự hiểu biết!'),
(16470, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 14, 'OT', 'Vì buôn bán nó tốt hơn buôn bán bạc, và lợi nhuận nó mang lại quý hơn cả vàng ròng.'),
(16471, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 15, 'OT', 'Nó quý trọng hơn châu báu, và mọi vật con ao ước cũng không sánh được với nó.'),
(16472, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 16, 'OT', 'Tay phải nó nắm giữ sự sống lâu dài, tay trái nó nắm giữ sự giàu có và vinh hiển.'),
(16473, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 17, 'OT', 'Các nẻo của nó là nẻo khoái lạc, và mọi lối đi của nó đều bình an.'),
(16474, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 18, 'OT', 'Cây ấy là cây sự sống cho những ai níu giữ nó; ai nâng đỡ nó đều được phước.'),
(16475, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 19, 'OT', 'Đức Giê-hô-va dùng sự khôn ngoan mà lập nên đất; Ngài dùng sự thông sáng mà đặt vững các từng trời.'),
(16476, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 20, 'OT', 'Nhờ tri thức Ngài, các vực thẳm nứt ra, và các tầng mây rơi xuống sương móc.'),
(16477, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 21, 'OT', 'Hỡi con, chớ để sự khôn ngoan và mưu trí rời khỏi mắt con; hãy giữ lấy sự khôn ngoan và mưu trí.'),
(16478, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 22, 'OT', 'Thì chúng sẽ là sự sống cho linh hồn ngươi, và như sự thương xót cho cổ ngươi.'),
(16479, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 23, 'OT', 'Bấy giờ ngươi sẽ đi cách an toàn trên con đường mình, và chân ngươi sẽ không vấp ngã.'),
(16480, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 24, 'OT', 'Khi ngươi nằm, ngươi sẽ không sợ hãi; ngươi nằm xuống và giấc ngủ ngươi sẽ êm ái.'),
(16481, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 25, 'OT', 'Đừng sợ sự kinh hoàng xảy đến bất ngờ, và sự hoảng hốt của kẻ ác khi nó ập đến.'),
(16482, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 26, 'OT', 'Vì Đức Giê-hô-va sẽ là nơi nương náu của con, và Ngài sẽ giữ gìn chân con khỏi bị mắc lừa.'),
(16483, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 27, 'OT', 'Đừng từ chối làm điều thiện cho người đáng được nhận, khi tay con có khả năng thực hiện điều đó.'),
(16484, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 28, 'OT', 'Đừng nói với người láng giềng rằng: "Hãy đi và trở lại, ngày mai tôi sẽ cho," trong khi của cải hiện đang ở cùng bạn.'),
(16485, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 29, 'OT', 'Chớ lập mưu hại người lân cận của con, khi người đang sống yên ổn bên con.'),
(16486, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 30, 'OT', 'Đừng tranh cãi vô cớ với một người nào, nếu người ấy không làm điều ác hại con.'),
(16487, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 31, 'OT', 'Chớ ganh ghét người làm ác, cũng chớ chọn bất cứ đường lối nào của hắn;'),
(16488, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 32, 'OT', 'Vì Đức Giê-hô-va ghét kẻ quanh co; nhưng Ngài thân mật với người ngay thẳng.'),
(16489, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 33, 'OT', 'Sự rủa sả của Đức Giê-hô-va giáng trên nhà kẻ ác, còn chỗ ở của người công bình thì Ngài ban phước.'),
(16490, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 34, 'OT', 'Thật vậy, Ngài chế giễu những kẻ hay chế giễu; nhưng ban ơn cho những kẻ khiêm nhường.'),
(16491, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 3, 35, 'OT', 'Người khôn ngoan sẽ được hưởng sự vinh hiển; còn kẻ ngu dại sẽ mang điều sỉ nhục.'),
(16492, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 4, 1, 'OT', 'Hỡi các con, hãy nghe lời dạy dỗ của cha, và hãy chăm chỉ lắng nghe để nhận biết sự thông sáng.'),
(16493, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 4, 2, 'OT', 'Vì ta đã ban cho các con một đạo lý tốt lành; đừng từ bỏ lời dạy dỗ của ta.'),
(16494, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 4, 3, 'OT', 'Vì tôi từng là con trai của cha tôi, yếu đuối và duy nhất trước mặt mẹ tôi.'),
(16495, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 4, 4, 'OT', 'Cha tôi đã dạy tôi và nói rằng: Lòng con hãy giữ chắc các lời tôi; hãy gìn giữ các mạng lịnh tôi thì con sẽ được sống.'),
(16496, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 4, 5, 'OT', 'Hãy mua lấy sự khôn ngoan, hãy mua lấy sự thông sáng; chớ quên, chớ xây bỏ các lời của miệng ta.'),
(16497, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 4, 6, 'OT', 'Đừng từ bỏ nó, thì nó sẽ gìn giữ ngươi; hãy yêu nó, thì nó sẽ che chở ngươi.'),
(16498, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 4, 7, 'OT', 'Sự khôn ngoan là điều cần nhất; hãy kiếm lấy sự khôn ngoan, và trong mọi điều con kiếm được, hãy kiếm lấy sự thông sáng.'),
(16499, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 4, 8, 'OT', 'Hãy nâng niu sự khôn ngoan, thì nó sẽ làm cho ngươi được cao trọng; nó sẽ làm cho ngươi được vinh hiển, khi ngươi ôm lấy nó.'),
(16500, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 4, 9, 'OT', 'Sự khôn ngoan sẽ trao cho đầu ngươi một vòng hoa ân ái, một triều thiên vinh hiển sẽ tôn vinh ngươi.'),
(16501, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 4, 10, 'OT', 'Hỡi con, hãy nghe và nhận lấy các lời ta, thì những năm đời con sẽ được thêm nhiều lên.'),
(16502, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 4, 11, 'OT', 'Ta đã dạy con đường khôn ngoan, dẫn dắt con trong các lối ngay thẳng.'),
(16503, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 4, 12, 'OT', 'Khi con đi, bước chân con sẽ không bị chật hẹp; và nếu con chạy, con sẽ không vấp ngã.'),
(16504, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 4, 13, 'OT', 'Hãy nắm chắc sự dạy dỗ, chớ buông ra; hãy giữ gìn nó, vì ấy là sự sống của con.'),
(16505, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 4, 14, 'OT', 'Đừng đi vào con đường của kẻ ác, và đừng bước đi trên lối người gian ác.'),
(16506, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 4, 15, 'OT', 'Hãy tránh khỏi nó, chớ đi qua đó; hãy rẽ ra khỏi nó và đi ngang qua.'),
(16507, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 4, 16, 'OT', 'Vì chúng không ngủ được nếu chưa làm ác, và giấc ngủ chúng bị cất khỏi nếu chưa khiến người ta vấp ngã.'),
(16508, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 4, 17, 'OT', 'Vì chúng nó ăn bánh của sự gian ác, và uống rượu của sự bạo lực.'),
(16509, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 4, 18, 'OT', 'Đường người ngay thẳng như ánh sáng rạng ngời, đi mãi và càng sáng hơn cho đến khi trọn ngày.'),
(16510, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 4, 19, 'OT', 'Lối của kẻ ác tối tăm; chúng không biết mình vấp ngã vì điều gì.'),
(16511, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 4, 20, 'OT', 'Hỡi con, hãy lắng nghe các lời ta, nghiêng tai về phía các bài giảng của ta.'),
(16512, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 4, 21, 'OT', 'Đừng để những lời ấy rời khỏi mắt con, hãy gìn giữ chúng ở trong lòng con.'),
(16513, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 4, 22, 'OT', 'Vì chúng là sự sống cho những người tìm được nó, và sự lành mạnh cho toàn thể thân thể của họ.'),
(16514, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 4, 23, 'OT', 'Hãy hết sức giữ lấy lòng ngươi, vì từ đó phát xuất các nguồn sự sống.'),
(16515, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 4, 24, 'OT', 'Hãy loại bỏ khỏi miệng ngươi sự méo mó, và loại bỏ xa ngươi sự dối trá của môi.'),
(16516, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 4, 25, 'OT', 'Mắt ngươi hãy nhìn thẳng phía trước, và mi mắt ngươi hãy chăm về phía trước mặt ngươi.'),
(16517, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 4, 26, 'OT', 'Hãy san bằng con đường dưới chân con, và mọi lối bước con sẽ vững chắc.'),
(16518, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 4, 27, 'OT', 'Đừng nghiêng sang bên phải hay bên trái; hãy rút chân ngươi khỏi điều ác.'),
(16519, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 5, 1, 'OT', 'Hỡi con, hãy lắng nghe sự khôn ngoan của cha, nghiêng tai mà nghe lời thông sáng của cha.'),
(16520, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 5, 2, 'OT', 'Để giữ lấy sự khôn khéo, và tri thức nơi môi con sẽ được gìn giữ.'),
(16521, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 5, 3, 'OT', 'Vì môi người đàn bà ngoại tình nhỏ ra mật, và vòm họng nàng trơn tru hơn dầu.'),
(16522, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 5, 4, 'OT', 'Nhưng cuối cùng nó đắng như ngải cứu, sắc như gươm hai lưỡi.'),
(16523, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 5, 5, 'OT', 'Chân người ấy bước xuống chỗ chết; các bước người ấy dẫm lên âm phủ.'),
(16524, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 5, 6, 'OT', 'Nàng không suy xét con đường dẫn đến sự sống, các lối nó quanh co, mà nàng không biết.'),
(16525, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 5, 7, 'OT', 'Bây giờ, hỡi các con, hãy nghe ta; chớ đi chệch khỏi các lời từ miệng ta.'),
(16526, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 5, 8, 'OT', 'Hãy giữ đường lối mình cách xa khỏi nàng, và chớ đến gần cửa nhà nàng.'),
(16527, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 5, 9, 'OT', 'e rằng con sẽ trao sự vinh hiển của mình cho kẻ khác, và những năm đời con cho kẻ hà hiếp.'),
(16528, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 5, 10, 'OT', 'Kẻo người ngoài được no đầy sức lực con, và những công khó con đổ vào nhà người ngoại.'),
(16529, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 5, 11, 'OT', 'Rồi cuối cùng ngươi phải rên siết, khi thân thể và xương thịt ngươi đã tiêu hao.'),
(16530, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 5, 12, 'OT', 'Và ngươi sẽ nói: "Than ôi, ta đã ghét sự sửa dạy, lòng ta khinh dể lời quở trách."'),
(16531, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 5, 13, 'OT', 'Tôi đã không nghe theo tiếng thầy dạy tôi, và chẳng nghiêng tai về phía người chỉ bảo tôi.'),
(16532, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 5, 14, 'OT', 'Tôi hầu như sa vào mọi điều ác, ngay giữa hội chúng và cộng đồng.'),
(16533, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 5, 15, 'OT', 'Hãy uống nước từ giếng của con, và nước chảy ra từ giếng con.'),
(16534, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 5, 16, 'OT', 'Các mạch nước của con há nên tuôn tràn ra ngoài, các dòng nước chảy lan ra các đường phố sao?'),
(16535, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 5, 17, 'OT', 'Hãy để chúng thuộc về con mà thôi, chớ đừng chia sẻ với người ngoại.'),
(16536, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 5, 18, 'OT', 'Nguyện nguồn mạch ngươi được phước; hãy vui vẻ nơi vợ tuổi thanh xuân của ngươi.'),
(16537, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 5, 19, 'OT', 'Nai cái của tình yêu, hoàng dương duyên dáng, sữa nàng cho con no thỏa mọi lúc, trong tình yêu nàng, con luôn say sưa mãi mãi.'),
(16538, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 5, 20, 'OT', 'Hỡi con, tại sao con lại say mê người đàn bà ngoại đạo, và ôm ấp lòng của kẻ ngoại?'),
(16539, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 5, 21, 'OT', 'Vì các đường lối của loài người ở trước cặp mắt Đức Giê-hô-va; Ngài cân nhắc mọi lối đi của người ấy.'),
(16540, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 5, 22, 'OT', 'Tội ác của nó sẽ bắt lấy kẻ ác, và nó sẽ bị trói buộc bởi dây tội lỗi mình.'),
(16541, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 5, 23, 'OT', 'Người ấy sẽ chết vì không có sự sửa dạy, và vì sự ngu dại quá nhiều mà đi lạc đường.'),
(16542, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 1, 'OT', 'Hỡi con, nếu con đã bảo lãnh cho người bạn mình, nếu con đã lấy tay mình mà cam kết cho người dưng,'),
(16543, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 2, 'OT', 'Con đã bị mắc vào lời của miệng mình, bị bắt giữ bởi các lời của miệng mình.'),
(16544, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 3, 'OT', 'Hãy làm điều nầy, hỡi con, và cứu mình ra, vì con đã sa vào tay người đồng bạn con; hãy đi, hạ mình xuống, và nài xin người đồng bạn con.'),
(16545, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 4, 'OT', 'Đừng cho hai mắt mình ngủ, cũng đừng để mí mắt mình chợp lại.'),
(16546, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 5, 'OT', 'Hãy thoát thân ngươi như con nai khỏi tay thợ săn, và như con chim khỏi tay kẻ đặt bẫy.'),
(16547, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 6, 'OT', 'Hỡi kẻ biếng nhác, hãy đi đến loài kiến; hãy nhìn xem đường lối nó mà trở nên khôn ngoan.'),
(16548, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 7, 'OT', 'không có quan trưởng, quan cai trị, hay người cai quản nó'),
(16549, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 8, 'OT', 'Nó sắm sửa lương thực mình trong mùa hè, và thu góp đồ ăn mình trong mùa gặt.'),
(16550, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 9, 'OT', 'Hỡi kẻ biếng nhác, ngươi sẽ nằm ngủ cho đến bao giờ? Bao giờ ngươi sẽ thức dậy khỏi giấc ngủ ngươi?'),
(16551, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 10, 'OT', 'Một ít năm, một ít chợp mắt, một ít khoanh tay nằm.'),
(16552, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 11, 'OT', 'Thì sự nghèo khổ của ngươi sẽ ập đến như người đi bộ, và sự thiếu thốn của ngươi như một người cầm khiên.'),
(16553, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 12, 'OT', 'Một người vô lại, kẻ làm ác, đi với miệng méo mó.'),
(16554, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 13, 'OT', 'Chớp mắt, dùng chân ám hiệu, và ra dấu bằng ngón tay mình;'),
(16555, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 14, 'OT', 'Trong lòng nó đầy điều quấy, luôn toan mưu ác, và gieo rắc sự tranh cạnh.'),
(16556, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 15, 'OT', 'Vì cớ đó, tai vạ nó sẽ đến thình lình; bỗng chốc nó bị đỗ nát, không có thuốc chữa.'),
(16557, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 16, 'OT', 'Sáu điều Đức Giê-hô-va ghét, và bảy điều lòng Ngài lấy làm gớm ghiếc:'),
(16558, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 17, 'OT', 'Mắt kiêu ngạo, lưỡi nói dối, tay đổ huyết người vô tội'),
(16559, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 18, 'OT', 'Lòng toan tính những điều ác, chân vội vàng chạy đến điều ác.'),
(16560, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 19, 'OT', 'Kẻ làm chứng dối và phao truyền điều giả dối, cùng kẻ gieo rắc sự bất hòa giữa anh em.'),
(16561, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 20, 'OT', 'Hỡi con, hãy giữ mạng lịnh của cha con, chớ từ bỏ luật pháp của mẹ con.'),
(16562, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 21, 'OT', 'Hãy buộc lấy chúng nơi lòng con luôn mãi, và treo chúng nơi cổ con.'),
(16563, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 22, 'OT', 'Khi con đi, nó sẽ dẫn dắt con; khi con nằm, nó sẽ giữ gìn con; và khi con thức dậy, nó sẽ trò chuyện với con.'),
(16564, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 23, 'OT', 'Vì điều răn là ngọn đèn, và luật pháp là ánh sáng, còn những lời khuyên dạy sửa trị là con đường dẫn đến sự sống.'),
(16565, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 24, 'OT', 'Để giữ ngươi khỏi người đàn bà xấu xa, khỏi lời nói quyến rũ của kẻ ngoại đạo.'),
(16566, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 25, 'OT', 'Đừng thèm muốn sắc đẹp của nàng trong lòng con, và đừng để mình bị cuốn theo mí mắt nàng.'),
(16567, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 26, 'OT', 'Vì một người đàn bà điếm, người ta chỉ còn một ổ bánh mì; nhưng vợ người khác săn bắt linh hồn quý giá.'),
(16568, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 27, 'OT', 'Người nào có thể đốt lửa trong lòng mình mà áo xống người ấy lại không bị cháy?'),
(16569, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 28, 'OT', 'Nếu một người đi trên than hồng, thì chân người ấy há chẳng bị bỏng sao?'),
(16570, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 29, 'OT', 'Cũng vậy, kẻ nào đến cùng vợ người bạn mình; bất kỳ ai đụng đến nàng sẽ không được tha.'),
(16571, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 30, 'OT', 'Người ta không khinh bỉ kẻ trộm, nếu nó ăn cắp để thỏa lòng mình khi đói.'),
(16572, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 31, 'OT', 'Khi bị phát hiện, nó phải đền bảy lần; tất cả tài sản trong nhà nó sẽ phải trao ra.'),
(16573, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 32, 'OT', 'Người phạm tội ngoại tình với vợ người khác là kẻ thiếu hiểu biết; ai làm như vậy sẽ hủy hoại linh hồn mình.'),
(16574, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 33, 'OT', 'Sẽ gặp tai họa và ô nhục, và sự sỉ nhục nó sẽ không bị xóa đi.'),
(16575, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 34, 'OT', 'Vì lòng ghen tuông là cơn thịnh nộ của người đàn ông, và trong ngày báo phục, người ấy sẽ không thương tình.'),
(16576, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 6, 35, 'OT', 'Chẳng chịu nhận mọi tiền đền bù, cũng chẳng chịu dù của lễ chuộc tội có thêm lên bao nhiêu.'),
(16577, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 7, 1, 'OT', 'Hỡi con, hãy giữ các lời ta, và gìn giữ các mạng lệnh ta bên cạnh con.'),
(16578, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 7, 2, 'OT', 'Hãy giữ các mạng lịnh ta thì sẽ được sống, và giữ lời dạy dỗ ta như ngươi của mắt con.'),
(16579, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 7, 3, 'OT', 'Hãy cột chúng nơi ngón tay ngươi, ghi chúng trên bảng lòng ngươi.'),
(16580, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 7, 4, 'OT', 'Hãy nói với sự khôn ngoan: "Ngươi là chị ta!" và hãy gọi sự hiểu biết là người quen biết.'),
(16581, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 7, 5, 'OT', 'Để giữ gìn con khỏi người đàn bà ngoại, khỏi người đàn bà xa lạ nói lời trơn tru.'),
(16582, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 7, 6, 'OT', 'Vì từ cửa sổ nhà tôi, qua khe cửa sổ buồng tôi, tôi đã nhìn ra,'),
(16583, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 7, 7, 'OT', 'Tôi thấy giữa những kẻ ngu dốt, trong vòng các thiếu niên, một người trẻ tuổi thiếu sự hiểu biết.'),
(16584, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 7, 8, 'OT', 'Đi ngang qua phố gần góc nhà nàng, bước đi trên con đường dẫn đến nhà nàng.'),
(16585, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 7, 9, 'OT', 'trong lúc chạng vạng khi rốt ngày, giữa ban đêm tối tăm mịt mùng.'),
(16586, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 7, 10, 'OT', 'Kìa, một người đàn bà đi ra đón người ấy, là kẻ dâm nữ trá hình, lòng đầy mưu kế.'),
(16587, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 7, 11, 'OT', 'Nàng kêu la ầm ĩ, không biết vâng phục; hai chân nàng chẳng chịu ở yên trong nhà mình.'),
(16588, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 7, 12, 'OT', 'Lúc thì ngoài đường, lúc thì nơi các phố chợ, rình rập bên cạnh mọi góc phố.'),
(16589, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 7, 13, 'OT', 'Nàng nắm lấy người và hôn chàng, mặt dạn mày dày, nói cùng người rằng:'),
(16590, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 7, 14, 'OT', 'Tôi có dâng các lễ vật hóa bình an; hôm nay tôi đã hoàn tất các lời khấn hứa của mình.'),
(16591, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 7, 15, 'OT', 'Vì vậy, tôi đã ra gặp anh, để tìm kiếm mặt anh, và tôi đã tìm thấy anh.'),
(16592, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 7, 16, 'OT', 'Tôi đã trải giường tôi bằng những tấm thảm, những tấm trải bằng gai gấm Ai Cập, đủ sắc màu.'),
(16593, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 7, 17, 'OT', 'Tôi đã rắc giường tôi bằng nhựa thơm, mộc dược, và quế.'),
(16594, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 7, 18, 'OT', 'Hãy đến, chúng ta sẽ say sưa tình ái cho đến sáng, thỏa lòng trong sự âu yếm.'),
(16595, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 7, 19, 'OT', 'Vì người chồng chẳng có ở nhà, người ấy đã đi đường xa,'),
(16596, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 7, 20, 'OT', 'Người cầm theo túi bạc trong tay, sẽ đến nhà mình vào ngày trăng tròn.'),
(16597, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 7, 21, 'OT', 'Dùng nhiều lời ngọt ngào mà quyến rũ người ấy, khiến người ấy sa vào bẫy bởi những lời nói mị dân của môi miệng mình.'),
(16598, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 7, 22, 'OT', 'Đi theo nàng ngay tức thì, như con bò đi đến nơi giết, và như kẻ ngu dại đến dây phạt.'),
(16599, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 7, 23, 'OT', 'Cho đến khi mũi tên đâm xuyên qua gan nó; như chim nhảy vội vào lưới, chẳng biết rằng mạng sống mình đang bị đe dọa.'),
(16600, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 7, 24, 'OT', 'Vậy bây giờ, hỡi các con, hãy nghe ta, và chăm chú về các lời của miệng ta.'),
(16601, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 7, 25, 'OT', 'Lòng ngươi chớ nghiêng về con đường nàng; chớ đi lạc vào các lối của nàng.'),
(16602, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 7, 26, 'OT', 'Vì nàng đã làm ngã rất nhiều người, và tất cả những kẻ bị nàng giết đều là những người cường tráng.'),
(16603, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 7, 27, 'OT', 'Những nẻo đường của nhà nó là những nẻo đường âm phủ, dẫn xuống các buồng của cõi chết.'),
(16604, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 1, 'OT', 'Sự khôn ngoan há chẳng kêu lên sao? Sự thông sáng há chẳng phát tiếng mình ra sao?'),
(16605, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 2, 'OT', 'Nơi đầu các nơi cao dọc đường phố, tại nơi giao nhau của các lối đi, nàng đứng.'),
(16606, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 3, 'OT', 'Gần bên các cửa, tại nơi vào thành, ở các lối vào, sự khôn ngoan cất tiếng la lên.'),
(16607, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 4, 'OT', 'Hỡi loài người, ta kêu gọi các ngươi, và tiếng ta hướng về con cái loài người!'),
(16608, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 5, 'OT', 'Hỡi những kẻ ngu ngơ, hãy hiểu sự khôn khéo; hỡi những kẻ dại dột, hãy hiểu lòng mình.'),
(16609, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 6, 'OT', 'Hãy nghe, vì ta sẽ nói những lời cao trọng; từ môi ta, những điều ngay thẳng sẽ tuôn ra.'),
(16610, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 7, 'OT', 'Vì lẽ thật sẽ ra từ miệng ta; Còn sự gian ác, môi ta ghét.'),
(16611, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 8, 'OT', 'Tất cả các lời từ miệng tôi đều công bình, chẳng có điều gì gian tà hay quanh co trong đó.'),
(16612, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 9, 'OT', 'Thảy đều ngay thẳng cho người hiểu biết, và chính trực cho kẻ tìm được tri thức.'),
(16613, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 10, 'OT', 'Hãy nhận lấy sự dạy dỗ ta, chứ đừng lấy bạc; và sự hiểu biết, hơn cả bạc được chọn lọc.'),
(16614, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 11, 'OT', 'Vì sự khôn ngoan tốt lành hơn ngọc quý, và mọi vật mong ước không sánh được với nó.'),
(16615, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 12, 'OT', 'Ta là sự khôn ngoan, đã chọn sự thông minh làm nơi ở của mình, và tìm được tri thức cùng những mưu kế.'),
(16616, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 13, 'OT', 'Sự kính sợ Đức Giê-hô-va là ghét điều ác; ta ghét sự kiêu ngạo và ngạo mạn, con đường ác và miệng nói những điều gian tà.'),
(16617, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 14, 'OT', 'Lòng tôi đầy mưu luận và thông sáng; tôi là sự hiểu biết, sức mạnh quyền năng thuộc về tôi.'),
(16618, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 15, 'OT', 'Nhờ ta, các vua trị vì, và các quan quyền thiết lập sự công chính.'),
(16619, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 16, 'OT', 'Nhờ ta, các quan trưởng cai trị, và các bậc quý tộc, tất cả những quan xét công bình.'),
(16620, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 17, 'OT', 'Ta yêu những người yêu mến ta, và ai tìm kiếm ta sẽ gặp ta.'),
(16621, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 18, 'OT', 'Sự giàu có và vinh hiển đều ở cùng ta, của cải bền lâu và sự công chính.'),
(16622, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 19, 'OT', 'Bông trái ta tốt hơn cả vàng ròng và vàng rực rỡ; lợi nhuận ta quý hơn cả bạc tinh luyện.'),
(16623, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 20, 'OT', 'Ta đi theo con đường công lý, giữa các nẻo chính trực.'),
(16624, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 21, 'OT', 'Để ban cho những người yêu ta hưởng của cải thực sự, và làm cho đầy các kho tàng của họ.'),
(16625, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 22, 'OT', 'Đức Giê-hô-va đã lập ta từ buổi khởi đầu của đường lối Ngài, trước những công việc đầu tiên của Ngài, ngay từ xưa.'),
(16626, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 23, 'OT', 'Ta đã được thiết lập từ trước muôn đời, từ lúc khởi nguyên, trước khi đất được tạo nên.'),
(16627, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 24, 'OT', 'Khi chưa có các vực sâu, ta đã được sinh ra; khi chưa có các suối nước đầy tràn.'),
(16628, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 25, 'OT', 'Trước khi các núi được đóng chặt xuống, trước khi các gò đồi được sinh ra, ta đã được sinh ra.'),
(16629, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 26, 'OT', 'Trước khi Đức Giê-hô-va dựng nên đất và các miền ngoài, và ngay cả tro bụi đầu tiên của thế gian.'),
(16630, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 27, 'OT', 'Khi Đức Chúa Trời lập các từng trời, Ta đã ở đó; khi Ngài định cái vòng trên mặt vực sâu, Ta đã ở đó.'),
(16631, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 28, 'OT', 'Khi Ngài làm vững các tầng mây ở trên cao, khi Ngài làm chắc các mạch nước ở vực thẳm,'),
(16632, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 29, 'OT', 'Khi Ngài đặt luật cho biển cả, để nước không vượt quá giới hạn Ngài; khi Ngài định các nền tảng của đất.'),
(16633, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 30, 'OT', 'Ta ở bên Ngài như một người thợ lành nghề, hằng ngày là niềm vui của Ngài, luôn luôn vui vẻ trước mặt Ngài mọi lúc.'),
(16634, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 31, 'OT', 'Ta vui thích nơi thế gian có người ở của Ngài, và niềm vui thích ta ở nơi con cái loài người.'),
(16635, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 32, 'OT', 'Vậy bây giờ, hỡi các con, hãy nghe ta; Phước thay cho kẻ giữ các nẻo đường ta!'),
(16636, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 33, 'OT', 'Hãy nghe lời dạy dỗ và hãy trở nên khôn ngoan, chớ đừng khước từ.'),
(16637, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 34, 'OT', 'Phước thay cho người nào nghe ta, ngày ngày canh giữ tại các cửa ta, thức canh bên các trụ cửa ta.'),
(16638, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 35, 'OT', 'Vì ai tìm được ta thì gặp sự sống, và sẽ nhận được ơn lành từ Đức Giê-hô-va;'),
(16639, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 8, 36, 'OT', 'Nhưng ai phạm đến ta là làm hại linh hồn mình; còn mọi kẻ ghét ta đều yêu thích sự chết.'),
(16640, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 9, 1, 'OT', 'Sự khôn ngoan đã xây dựng nhà mình; đẽo đẽo bảy cây cột của nó.'),
(16641, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 9, 2, 'OT', 'Đã giết thịt, đã pha rượu mình, lại cũng đã bày biện bàn tiệc mình.'),
(16642, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 9, 3, 'OT', 'Nữ nhân sai các tớ gái mình đi, kêu lên từ các chỗ cao của thành phố:'),
(16643, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 9, 4, 'OT', 'Kẻ nào ngây thơ, hãy đến đây; Đức khôn ngoan nói với người thiếu trí.'),
(16644, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 9, 5, 'OT', 'Hãy đến, hãy ăn bánh ta làm, và hãy uống rượu ta đã pha chế.'),
(16645, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 9, 6, 'OT', 'Hãy bỏ sự ngu ngốc mà sống, và hãy đi theo con đường hiểu biết.'),
(16646, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 9, 7, 'OT', 'Ai quở trách kẻ nhạo báng sẽ chuốc lấy sự sỉ nhục cho mình; ai khiển trách người ác sẽ mang điều nhục nhã cho bản thân.'),
(16647, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 9, 8, 'OT', 'Đừng quở trách kẻ nhạo báng, e nó sẽ ghét ngươi; hãy quở trách người khôn ngoan, nó sẽ yêu mến ngươi.'),
(16648, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 9, 9, 'OT', 'Hãy ban cho người khôn ngoan, thì người sẽ khôn ngoan thêm; hãy chỉ dạy người ngay thẳng, thì người sẽ thêm tri thức.'),
(16649, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 9, 10, 'OT', 'Sự kính sợ Đức Giê-hô-va là khởi đầu của sự khôn ngoan; sự nhận biết Đấng Thánh là sự hiểu biết.'),
(16650, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 9, 11, 'OT', 'Vì nhờ ta, các ngày của ngươi sẽ thêm nhiều lên, và các năm đời sống của ngươi sẽ được gia tăng.'),
(16651, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 9, 12, 'OT', 'Nếu ngươi khôn ngoan, thì ngươi khôn ngoan cho chính mình ngươi; còn nếu ngươi nhạo báng, thì một mình ngươi phải gánh lấy.'),
(16652, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 9, 13, 'OT', 'Người đàn bà dại dột, ồn ào, ngang ngược, chẳng biết điều gì cả.'),
(16653, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 9, 14, 'OT', 'Nàng ngồi tại cửa nhà mình, trên ghế cao nơi các nẻo đường thành phố.'),
(16654, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 9, 15, 'OT', 'Mời những kẻ đi đường, những kẻ đi thẳng con đường mình,'),
(16655, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 9, 16, 'OT', 'Kẻ nào ngu dại, hãy đến đây; và người thiếu trí nói cùng nó rằng:'),
(16656, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 9, 17, 'OT', 'Nước trộm thì ngọt ngào, bánh ăn lén thì ngon thay.'),
(16657, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 9, 18, 'OT', 'Nhưng người không biết rằng ở đó có những kẻ chết, những người được nàng mời gọi đều ở trong các vực sâu của âm phủ.'),
(16658, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 10, 1, 'OT', 'Con trai khôn làm cha vui vẻ; con trai dại làm mẹ buồn rầu.'),
(16659, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 10, 2, 'OT', 'Của cải gian ác chẳng ích lợi gì; còn sự công bình thì giải cứu khỏi sự chết.'),
(16660, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 10, 3, 'OT', 'Đức Giê-hô-va không để linh hồn người công bình phải chịu đói, nhưng xua đuổi điều ước ao của kẻ ác.'),
(16661, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 10, 4, 'OT', 'Tay biếng nhác làm cho nghèo túng; nhưng tay siêng năng làm cho giàu có.'),
(16662, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 10, 5, 'OT', 'Thu hoạch trong mùa hè là con trai khôn ngoan; kẻ biếng nhác trong mùa gặt là con trai gây sỉ nhục.'),
(16663, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 10, 6, 'OT', 'Phước lành ở trên đầu người công bình; nhưng miệng kẻ ác che giấu sự hung bạo.'),
(16664, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 10, 7, 'OT', 'Danh tiếng người công bình được chúc phước; nhưng danh tiếng người ác sẽ mục nát.'),
(16665, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 10, 8, 'OT', 'Người có lòng khôn ngoan sẽ tiếp nhận các điều răn; Nhưng kẻ ngu muội nơi môi miệng sẽ bị sa ngã.'),
(16666, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 10, 9, 'OT', 'Người nào đi theo đường lối ngay thẳng sẽ đi cách an toàn; còn kẻ làm cho các đường lối mình cong vẹo sẽ bị lộ ra.'),
(16667, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 10, 10, 'OT', 'Ai nheo mắt gây ra buồn bã; Kẻ ngu dại về lời nói sẽ bị ngã.'),
(16668, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 10, 11, 'OT', 'Miệng người công bình là nguồn sự sống; miệng kẻ ác che khuất sự hung bạo.'),
(16669, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 10, 12, 'OT', 'Sự ghét bỏ xui nên điều tranh cãi; còn tình yêu thương thì che phủ mọi tội ác.'),
(16670, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 10, 13, 'OT', 'Trên môi người khôn ngoan có sự khôn sáng; còn roi đòn dành cho lưng kẻ thiếu trí.'),
(16671, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 10, 14, 'OT', 'Người khôn ngoan giữ gìn tri thức; nhưng miệng kẻ ngu dại hối hả đến sự bại hoại.'),
(16672, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 10, 15, 'OT', 'Của cải người giàu là thành trì vững chắc của người; sự nghèo khó người nghèo là sự hủy hoại của họ.'),
(16673, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 10, 16, 'OT', 'Công việc của người công bình dẫn đến sự sống; hoa lợi của kẻ ác dẫn đến tội lỗi.'),
(16674, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 10, 17, 'OT', 'Kẻ giữ lời khuyên dạy đi trên con đường sự sống; còn kẻ bỏ qua sự sửa dạy là kẻ lầm lạc.'),
(16675, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 10, 18, 'OT', 'Kẻ che giấu sự ghét ghen thì dùng môi miệng nói dối, còn kẻ rêu rao điều ác lại là kẻ ngu dại.'),
(16676, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 10, 19, 'OT', 'Nói nhiều thì không tránh khỏi phạm tội; nhưng ai giữ môi mình là người khôn ngoan.'),
(16677, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 10, 20, 'OT', 'Lưỡi người công bình như bạc tinh ròng; lòng kẻ ác chỉ đáng một ít.'),
(16678, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 10, 21, 'OT', 'Môi miệng người công bình nuôi dưỡng nhiều người; còn kẻ ngu dại thì chết vì thiếu trí khôn.'),
(16679, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 10, 22, 'OT', 'Phước lành của Đức Giê-hô-va là làm cho giàu có; Ngài không thêm nỗi khổ nào cùng với nó.'),
(16680, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 10, 23, 'OT', 'Kẻ dại coi việc làm ác như trò vui; còn người có trí hiểu thì coi sự khôn ngoan là điều đáng quý.'),
(16681, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 10, 24, 'OT', 'Sự sợ hãi của kẻ ác sẽ giáng trên nó; còn điều ao ước của người công bình, Đức Chúa Trời sẽ ban cho.'),
(16682, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 10, 25, 'OT', 'Khi cơn lốc đi qua, kẻ ác không còn nữa; nhưng người công chính là nền tảng vững chắc đời đời.'),
(16683, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 10, 26, 'OT', 'Như giấm làm nhức răng, như khói làm cay mắt, kẻ biếng nhác đối với người sai khiến mình cũng vậy.'),
(16684, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 10, 27, 'OT', 'Sự kính sợ Đức Giê-hô-va làm tăng thêm ngày tháng; còn những năm của kẻ ác sẽ bị rút ngắn.'),
(16685, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 10, 28, 'OT', 'Sự trông đợi của người công bình đem lại niềm vui; còn sự mong mỏi của kẻ ác sẽ bị tiêu tan.'),
(16686, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 10, 29, 'OT', 'Đường lối của Đức Giê-hô-va là đồn lũy cho người ngay thẳng; nhưng là sự sụp đổ cho những kẻ làm điều ác.'),
(16687, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 10, 30, 'OT', 'Người công bình sẽ không hề bị lay chuyển đời đời; còn kẻ ác thì không được ở trên đất.'),
(16688, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 10, 31, 'OT', 'Miệng người công bình sinh ra sự khôn ngoan; còn lưỡi kẻ gian tà sẽ bị chặt đứt.'),
(16689, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 10, 32, 'OT', 'Môi người công bình biết điều đẹp lòng; nhưng miệng kẻ ác chỉ nói điều gian tà.'),
(16690, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 11, 1, 'OT', 'Các cái cân gian dối là điều đáng gớm ghét cho Đức Giê-hô-va; còn hòn đá cân trọn vẹn thì được đẹp lòng Ngài.'),
(16691, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 11, 2, 'OT', 'Khi sự kiêu ngạo đến, thì sự sỉ nhục cũng đến; nhưng người khiêm nhường giữ được sự khôn ngoan.'),
(16692, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 11, 3, 'OT', 'Sự ngay thẳng của người ngay lành dẫn dắt họ; còn sự gian tà của kẻ phản bội sẽ hủy diệt chính nó.'),
(16693, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 11, 4, 'OT', 'Của cải chẳng ích gì trong ngày thịnh nộ, nhưng sự công bình cứu chuộc khỏi sự chết.'),
(16694, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 11, 5, 'OT', 'Sự công chính của người ngay thẳng làm cho đường lối người ngay thẳng; nhưng kẻ ác sẽ sa ngã vì sự ác của mình.'),
(16695, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 11, 6, 'OT', 'Sự công bình của người ngay thẳng sẽ giải cứu họ; còn sự tham lam của kẻ phản bội sẽ bắt giữ chính chúng.'),
(16696, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 11, 7, 'OT', 'Khi người ác chết, sự trông mong bị tiêu tan; và sự mong đợi của kẻ gian ác bị tiêu diệt.'),
(16697, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 11, 8, 'OT', 'Người công bình được giải cứu khỏi cơn nguy khốn; còn kẻ ác lại sa vào đó thay cho người.'),
(16698, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 11, 9, 'OT', 'Kẻ hàm mưu lấy lời nói hủy hoại người bạn mình; còn các người ngay thẳng nhờ tri thức mà được cứu rỗi.'),
(16699, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 11, 10, 'OT', 'Khi người công bình được ơn phước thì thành phố hớn hở vui mừng; khi kẻ ác bị tiêu diệt thì có tiếng reo mừng.'),
(16700, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 11, 11, 'OT', 'Nhờ ơn phước của người ngay thẳng, thành phố được nâng cao; nhưng bởi miệng kẻ ác, nó bị hủy diệt.'),
(16701, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 11, 12, 'OT', 'Kẻ khinh bỉ người lân cận mình là người thiếu trí; Còn người có hiểu biết thì giữ im lặng.'),
(16702, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 11, 13, 'OT', 'Kẻ đi rêu rao tiết lộ điều bí mật; còn người trung tín gìn giữ lời thề.'),
(16703, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 11, 14, 'OT', 'Không có mưu lược thì dân sự sẽ sa ngã; nhưng nếu có nhiều người cố vấn, thì được cứu giúp.'),
(16704, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 11, 15, 'OT', 'Người nào bảo lãnh cho kẻ ngoại bang, ắt sẽ gặp tai họa; Còn ai ghét việc vỗ tay cam kết, thì được an toàn.'),
(16705, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 11, 16, 'OT', 'Người vợ có ân tình thì được tôn trọng; còn kẻ bạo ngược thì được của cải.'),
(16706, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 11, 17, 'OT', 'Người nhân từ làm ơn cho linh hồn mình; Còn kẻ tàn nhẫn gây hại cho thân thể mình.'),
(16707, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 11, 18, 'OT', 'Kẻ ác làm công việc giả dối, còn người gieo điều công chính nhận được phần thưởng thật.'),
(16708, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 11, 19, 'OT', 'Người nào theo đường công bình sẽ được sống; còn kẻ theo điều ác sẽ chết.'),
(16709, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 11, 20, 'OT', 'Lòng người cong vênh lấy làm gớm ghiếc cho Đức Giê-hô-va; Nhưng ai trọn vẹn về đường lối được đẹp lòng Ngài.'),
(16710, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 11, 21, 'OT', 'Tay vào tay, kẻ ác sẽ không khỏi bị trừng phạt; còn dòng dõi người công bình sẽ được thoát khỏi.'),
(16711, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 11, 22, 'OT', 'Vòng vàng nơi mũi heo, người phụ nữ xinh đẹp mà thiếu duyên.'),
(16712, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 11, 23, 'OT', 'Sự mong ước của người công bình chỉ nhằm điều thiện; còn điều kẻ ác trông đợi là cơn thịnh nộ.'),
(16713, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 11, 24, 'OT', 'Có người phân phát của mình ra mà lại càng thêm nhiều; có người keo kiệt cách bất công mà chỉ gặp sự thiếu thốn.'),
(16714, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 11, 25, 'OT', 'Linh hồn làm phước sẽ được đầy đủ, và ai tưới nước cũng sẽ được tưới nước lại.'),
(16715, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 11, 26, 'OT', 'Kẻ ngăn cản không bán thóc lúa sẽ bị dân chúng rủa; nhưng đầu kẻ bán thóc sẽ được Đức Chúa Trời ban phước.'),
(16716, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 11, 27, 'OT', 'Ai tìm điều thiện thì tìm được ơn; nhưng ai tìm điều ác, điều ác ấy sẽ giáng trên nó.'),
(16717, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 11, 28, 'OT', 'Kẻ tin cậy nơi của cải mình sẽ ngã xuống; còn người công bình sẽ nở hoa như lá xanh.'),
(16718, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 11, 29, 'OT', 'Ai làm đổ vỡ nhà mình sẽ được gió làm cơ nghiệp; còn kẻ ngu dại sẽ phải làm tôi mọi cho người có lòng khôn ngoan.'),
(16719, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 11, 30, 'OT', 'Cây sự sống là trái của người công chính; còn người khôn ngoan thì đoạt lấy linh hồn.'),
(16720, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 11, 31, 'OT', 'Kìa, người công bình sẽ được báo đáp ngay trên đất này; huống chi kẻ ác và kẻ phạm tội!'),
(16721, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 12, 1, 'OT', 'Ai yêu sự sửa dạy thì yêu sự hiểu biết; còn kẻ ghét sự quở trách là người ngu dại.'),
(16722, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 12, 2, 'OT', 'Người lành được ơn của Đức Giê-hô-va; còn kẻ toan mưu ác Đức Giê-hô-va sẽ định tội.'),
(16723, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 12, 3, 'OT', 'Người ta không được lập vững bền bởi điều ác, nhưng gốc rễ của người công bình sẽ không bị lay động.'),
(16724, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 12, 4, 'OT', 'Người vợ hiền đức là mão cho chồng mình; còn vợ làm nhục chồng thì như sự mục nát trong xương cốt người.'),
(16725, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 12, 5, 'OT', 'Ý tưởng của người công chính là sự công bình; mưu kế của kẻ ác đều là gian dối.'),
(16726, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 12, 6, 'OT', 'Lời nói của kẻ ác rình rập lấy máu; nhưng miệng người ngay thẳng sẽ giải cứu họ.'),
(16727, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 12, 7, 'OT', 'Kẻ ác bị lật đổ thì không còn nữa, còn nhà người công bình sẽ đứng vững.'),
(16728, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 12, 8, 'OT', 'Người ta sẽ được ca ngợi tùy theo sự thông sáng của mình; còn kẻ có lòng phe phẩy sẽ bị khinh dể.'),
(16729, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 12, 9, 'OT', 'Tốt hơn là bị khinh thường mà có tôi tớ phục dịch, còn hơn tự phụ mà thiếu thốn lương thực.'),
(16730, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 12, 10, 'OT', 'Người công bình nhận biết hồn vật nuôi của mình; còn lòng thương xót của kẻ ác thì tàn nhẫn.'),
(16731, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 12, 11, 'OT', 'Người nào làm ruộng đất mình sẽ được no đủ về lương thực; còn kẻ theo đuổi những điều vô ích thì thiếu khôn ngoan.'),
(16732, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 12, 12, 'OT', 'Kẻ ác thèm muốn mưu mô gian ác, còn gốc rễ người công bình sẽ sinh hoa trái.'),
(16733, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 12, 13, 'OT', 'Trong tội lỗi của môi miệng có một cái bẫy tàn hại; nhưng người công bình được ra khỏi cơn khốn khổ.'),
(16734, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 12, 14, 'OT', 'Nhờ bông trái nơi miệng mình, người ta được no đủ điều lành; và công việc tay người làm sẽ báo lại cho người đó.'),
(16735, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 12, 15, 'OT', 'Đường lối của kẻ dại dột thì ngay thẳng trong mắt nó; còn người khôn ngoan chịu nghe lời khuyên dạy.'),
(16736, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 12, 16, 'OT', 'Kẻ ngu dại biểu lộ cơn giận mình ngay tức khắc; còn người khôn ngoan che giấu sự sỉ nhục.'),
(16737, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 12, 17, 'OT', 'Kẻ nói thật thì rao truyền lẽ công bình; còn kẻ làm chứng dối thì phô bày sự gian dối.'),
(16738, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 12, 18, 'OT', 'Có kẻ nói lời bừa bãi như đâm thọc bằng gươm; nhưng lưỡi của người khôn ngoan lại là sự chữa lành.'),
(16739, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 12, 19, 'OT', 'Môi nói thật sẽ tồn tại mãi mãi, còn lưỡi nói dối chỉ tồn tại một khoảnh khắc.'),
(16740, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 12, 20, 'OT', 'Sự lừa dối ở trong lòng những kẻ âm mưu điều ác; nhưng sự vui mừng thuộc về những kẻ góp phần cho sự hòa bình.'),
(16741, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 12, 21, 'OT', 'Người công bình sẽ không bị tai họa nào đụng đến; còn kẻ ác thì đầy dẫy điều dữ.'),
(16742, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 12, 22, 'OT', 'Môi miệng nói dối là điều gớm ghiếc cho Đức Giê-hô-va; còn những kẻ làm việc chân thật thì đẹp lòng Ngài.'),
(16743, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 12, 23, 'OT', 'Người khôn giấu sự hiểu biết; lòng kẻ dại bày tỏ sự ngu muội.'),
(16744, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 12, 24, 'OT', 'Tay người siêng năng sẽ cai trị; nhưng tay kẻ biếng nhác phải phục dịch.'),
(16745, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 12, 25, 'OT', 'Sự lo lắng trong lòng người làm cho lòng nao sờn; còn một lời tốt khiến lòng vui vẻ.'),
(16746, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 12, 26, 'OT', 'Người công bình hơn bạn mình, còn các nẻo của kẻ ác làm cho chúng nó lạc lối.'),
(16747, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 12, 27, 'OT', 'Kẻ biếng nhác không nướng thịt con mồi mình săn được; Còn của cải quí báu của người chăm chỉ.'),
(16748, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 12, 28, 'OT', 'Đường công chính là đường sự sống; trên lối ấy chẳng có sự chết.'),
(16749, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 13, 1, 'OT', 'Con khôn ngoan vâng lời khuyên dạy của cha; còn kẻ nhạo báng thì không nghe lời quở trách.'),
(16750, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 13, 2, 'OT', 'Nhờ bông trái nơi miệng người nào, người ấy được hưởng điều lành; còn linh hồn kẻ phản bội sẽ ăn điều bạo lực.'),
(16751, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 13, 3, 'OT', 'Kẻ giữ miệng mình thì giữ mạng sống mình; còn kẻ buông tuồng môi lưỡi sẽ gặp tai hoạ.'),
(16752, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 13, 4, 'OT', 'Người biếng lLazy mong ước mà không có gì; nhưng lòng người siêng năng sẽ được no đủ.'),
(16753, 20, 'GOI_vi', 'GOI_vi', 'vi', 'PRO', 13, 5, 'OT', 'Người công bình ghét lời nói dối; kẻ ác làm điều ghê tởm và phải hổ thẹn.'),
